-- RPC
-- ============================================================================

-- 등급 추첨: pool_odds 가중 RNG
create or replace function public.roll_rarity(p_pool_id uuid)
returns rarity
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare v_r numeric := random(); v_acc numeric := 0; v_total numeric; rec record;
begin
  select coalesce(sum(probability), 0) into v_total
    from pool_odds where pool_id = p_pool_id;
  if v_total <> 1 then raise exception 'pool odds must sum to 1'; end if;

  for rec in select rarity, probability from pool_odds where pool_id = p_pool_id order by rarity loop
    v_acc := v_acc + rec.probability;
    if v_r < v_acc then return rec.rarity; end if;
  end loop;
  raise exception 'failed to roll rarity';
end; $$

-- 충전 시작: pending 결제 행 생성(클라이언트가 토스로 결제). 멱등 키 사용.
create or replace function public.charge_wallet_init(p_amount bigint, p_idempotency_key text)
returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_user uuid := (select auth.uid()); v_pay uuid;
begin
  if v_user is null then raise exception 'auth required'; end if;
  if p_amount <= 0 then raise exception 'invalid amount'; end if;

  insert into payments (user_id, purpose, ref_id, amount, status, idempotency_key)
  values (v_user, 'wallet', null, p_amount, 'pending', p_idempotency_key)
  on conflict (idempotency_key) do nothing
  returning id into v_pay;
  if v_pay is not null then return v_pay; end if;

  select id into v_pay
    from payments
    where idempotency_key = p_idempotency_key
      and user_id = v_user
      and purpose = 'wallet'
      and ref_id is null
      and amount = p_amount;
  if v_pay is null then raise exception 'idempotency conflict'; end if;

  return v_pay;
end; $$

-- 충전 확정(웹훅): 멱등. 지갑 적립 + 장부.
create or replace function public.confirm_wallet_charge(
  p_idempotency_key text, p_payment_key text, p_amount bigint, p_raw jsonb
)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_user uuid; v_status payment_status; v_pay uuid; v_amount bigint; v_purpose payment_purpose; v_ref uuid;
begin
  select id, user_id, status, amount, purpose, ref_id
    into v_pay, v_user, v_status, v_amount, v_purpose, v_ref
    from payments where idempotency_key = p_idempotency_key for update;
  if v_pay is null then raise exception 'payment not found'; end if;
  if v_purpose <> 'wallet' or v_ref is not null then raise exception 'idempotency conflict'; end if;
  if v_status in ('paid', 'refunded') then return; end if;            -- 멱등
  if v_status <> 'pending' then raise exception 'payment not payable'; end if;
  if p_amount <> v_amount then raise exception 'amount mismatch'; end if;

  update payments set status = 'paid', payment_key = p_payment_key, raw = p_raw where id = v_pay;

  insert into wallets (user_id, balance) values (v_user, p_amount)
    on conflict (user_id) do update set balance = wallets.balance + excluded.balance;
  insert into wallet_ledger (user_id, delta, reason, ref_id) values (v_user, p_amount, 'charge', v_pay);
end; $$

-- 가챠 뽑기: 지갑 차감 + RNG + 천장 + 적립 (1 트랜잭션). 확률/천장은 서버에서만 결정.
create or replace function public.pull_gacha(p_pool_id uuid, p_count integer)
returns table (card_id text, rarity rarity, is_new boolean)
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_user   uuid := (select auth.uid());
  v_cost   bigint;
  v_thr    integer;
  v_total  bigint;
  v_bal    bigint;
  v_pity   integer;
  v_pull   uuid;
  v_rarity rarity;
  v_card   text;
  v_new    boolean;
begin
  if v_user is null then raise exception 'auth required'; end if;
  if p_count not in (1, 10) then raise exception 'invalid count'; end if;

  select cost_per_pull, pity_threshold into v_cost, v_thr
    from card_pools
    where id = p_pool_id and now() >= active_from and (active_to is null or now() < active_to);
  if v_cost is null then raise exception 'pool not active'; end if;
  v_total := v_cost * p_count;

  -- 지갑 잠금/차감
  insert into wallets (user_id, balance) values (v_user, 0) on conflict (user_id) do nothing;
  select balance into v_bal from wallets where user_id = v_user for update;
  if v_bal < v_total then raise exception 'insufficient balance'; end if;
  update wallets set balance = balance - v_total where user_id = v_user;
  insert into wallet_ledger (user_id, delta, reason, ref_id) values (v_user, -v_total, 'pull', p_pool_id);

  -- 천장 카운터 잠금
  insert into gacha_pity (user_id, pool_id, pity) values (v_user, p_pool_id, 0) on conflict do nothing;
  select pity into v_pity from gacha_pity where user_id = v_user and pool_id = p_pool_id for update;

  insert into pulls (user_id, pool_id, cost, count) values (v_user, p_pool_id, v_total, p_count)
    returning id into v_pull;

  for i in 1..p_count loop
    v_pity := v_pity + 1;
    if v_pity >= v_thr then
      v_rarity := 'HOLO';        -- 천장: 최고 등급 보장
      v_pity := 0;
    else
      v_rarity := roll_rarity(p_pool_id);
      if v_rarity in ('SSR', 'HOLO') then v_pity := 0; end if;
    end if;

    select c.id into v_card from cards c
      where c.pool_id = p_pool_id and c.rarity = v_rarity
      order by random() limit 1;
    if v_card is null then raise exception 'pool has no card of rarity %', v_rarity; end if;

    v_new := not exists (
      select 1 from user_cards uc where uc.user_id = v_user and uc.card_id = v_card
    );
    insert into user_cards as uc (user_id, card_id, qty) values (v_user, v_card, 1)
      on conflict on constraint user_cards_pkey do update set qty = uc.qty + 1;
    insert into pull_results (pull_id, card_id, rarity) values (v_pull, v_card, v_rarity);

    card_id := v_card; rarity := v_rarity; is_new := v_new;
    return next;
  end loop;

  update gacha_pity set pity = v_pity where user_id = v_user and pool_id = p_pool_id;
end; $$

-- ============================================================================
-- RPC
-- ============================================================================

-- 예매: 재고 원자적 차감(FOR UPDATE) + pending 예매. 결제 확정 시 QR 발급.
create or replace function public.reserve_tickets(p_ticket_type_id uuid, p_qty integer)
returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_user  uuid := (select auth.uid());
  v_cap   integer; v_sold integer; v_price integer; v_limit integer; v_open timestamptz;
  v_event text; v_order uuid; v_already integer;
begin
  if v_user is null then raise exception 'auth required'; end if;
  if p_qty < 1 then raise exception 'invalid qty'; end if;

  select capacity, sold, price, per_user_limit, sales_open_at, event_id
    into v_cap, v_sold, v_price, v_limit, v_open, v_event
    from ticket_types where id = p_ticket_type_id for update;
  if v_cap is null then raise exception 'ticket type not found'; end if;
  if v_open is not null and now() < v_open then raise exception 'sales not open'; end if;
  if v_sold + p_qty > v_cap then raise exception 'sold out'; end if;

  -- 1인 한도(확정+선점 합산)
  select coalesce(sum(t.cnt),0) into v_already from (
    select count(*) cnt from tickets tk
      join ticket_orders o on o.id = tk.ticket_order_id
      where tk.ticket_type_id = p_ticket_type_id and o.user_id = v_user and o.status <> 'canceled'
  ) t;
  if v_already + p_qty > v_limit then raise exception 'per-user limit exceeded'; end if;

  update ticket_types set sold = sold + p_qty where id = p_ticket_type_id;

  insert into ticket_orders (user_id, event_id, status, total, expires_at)
  values (v_user, v_event, 'pending', v_price::bigint * p_qty, now() + interval '10 minutes')
  returning id into v_order;

  -- 좌석 자리 확보용 placeholder 티켓(QR은 결제 확정 시 발급)
  insert into tickets (ticket_order_id, ticket_type_id)
  select v_order, p_ticket_type_id from generate_series(1, p_qty);

  return v_order;
end; $$

-- 결제 확정(웹훅): 멱등. QR 발급 + 예매 paid.
create or replace function public.confirm_ticket_payment(
  p_idempotency_key text, p_ticket_order_id uuid, p_payment_key text, p_amount bigint, p_raw jsonb
)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_user uuid; v_total bigint; v_status ticket_order_status; v_expires_at timestamptz;
        v_existing record;
begin
  select id, purpose, ref_id, amount, status into v_existing
    from payments where idempotency_key = p_idempotency_key for update;
  if v_existing.id is not null then
    if v_existing.purpose <> 'ticket' or v_existing.ref_id is distinct from p_ticket_order_id then
      raise exception 'idempotency conflict';
    end if;
    if v_existing.status in ('paid', 'refunded') then return; end if;
    if v_existing.status <> 'pending' then raise exception 'payment not payable'; end if;
  end if;

  select user_id, total, status, expires_at into v_user, v_total, v_status, v_expires_at
    from ticket_orders where id = p_ticket_order_id for update;
  if v_user is null then raise exception 'ticket order not found'; end if;
  if v_status <> 'pending' then raise exception 'ticket order not payable'; end if;
  if v_expires_at is not null and now() >= v_expires_at then raise exception 'ticket order expired'; end if;
  if p_amount <> v_total then raise exception 'amount mismatch'; end if;
  if v_existing.id is not null and v_existing.amount <> p_amount then raise exception 'amount mismatch'; end if;

  insert into payments (user_id, purpose, ref_id, amount, status, payment_key, idempotency_key, raw)
  values (v_user, 'ticket', p_ticket_order_id, p_amount, 'paid', p_payment_key, p_idempotency_key, p_raw)
  on conflict (idempotency_key) do update set status = 'paid', payment_key = excluded.payment_key, raw = excluded.raw;

  if v_status = 'pending' then
    update ticket_orders set status = 'paid', expires_at = null where id = p_ticket_order_id;
    update tickets set qr_token = encode(extensions.gen_random_bytes(16), 'hex')
      where ticket_order_id = p_ticket_order_id and qr_token is null;
  end if;
end; $$

-- 검표: QR 1회 사용 보장
create or replace function public.check_in_ticket(p_qr_token text)
returns ticket_status
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_id uuid; v_status ticket_status;
begin
  if not is_staff() then raise exception 'forbidden'; end if;
  select id, status into v_id, v_status from tickets where qr_token = p_qr_token for update;
  if v_id is null then raise exception 'invalid ticket'; end if;
  if v_status <> 'valid' then return v_status; end if;   -- 이미 사용/환불
  update tickets set status = 'used' where id = v_id;
  insert into check_ins (ticket_id, by_staff) values (v_id, (select auth.uid()))
    on conflict (ticket_id) do nothing;
  return 'used'::ticket_status;
end; $$

-- 예매 취소/환불: 재고 복원 + 티켓 무효 + refunds
create or replace function public.refund_ticket_order(p_ticket_order_id uuid, p_reason text)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_user uuid; v_status ticket_order_status; v_pay uuid; v_amt bigint; r record;
begin
  select user_id, status into v_user, v_status from ticket_orders where id = p_ticket_order_id for update;
  if v_user is null then raise exception 'ticket order not found'; end if;
  if (select auth.uid()) <> v_user and not is_staff() then raise exception 'forbidden'; end if;
  if v_status = 'canceled' then return; end if;

  -- 미사용 티켓만 환불 가능
  if exists (select 1 from tickets where ticket_order_id = p_ticket_order_id and status = 'used') then
    raise exception 'used ticket cannot be refunded';
  end if;

  for r in
    select ticket_type_id, count(*) cnt from tickets
    where ticket_order_id = p_ticket_order_id group by ticket_type_id
  loop
    update ticket_types set sold = sold - r.cnt where id = r.ticket_type_id;
  end loop;

  update tickets set status = 'refunded' where ticket_order_id = p_ticket_order_id;
  update ticket_orders set status = 'canceled' where id = p_ticket_order_id;

  select id, amount into v_pay, v_amt from payments
    where purpose = 'ticket' and ref_id = p_ticket_order_id and status = 'paid' limit 1;
  if v_pay is not null then
    insert into refunds (payment_id, amount, reason) values (v_pay, v_amt, p_reason);
    update payments set status = 'refunded' where id = v_pay;
  end if;
end; $$

-- IP follow actions keep the public fan count cache in sync without trusting
-- client-provided user IDs.

create or replace function public.follow_ip(target_ip_id text)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := auth.uid();
  inserted_count integer := 0;
  current_fans_count integer := 0;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not exists (select 1 from public.ips where id = target_ip_id) then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  insert into public.ip_follows (user_id, ip_id)
  values (actor_id, target_ip_id)
  on conflict (user_id, ip_id) do nothing;

  get diagnostics inserted_count = row_count;

  if inserted_count > 0 then
    update public.ips
    set fans_count = fans_count + 1,
        updated_at = now()
    where id = target_ip_id
    returning fans_count into current_fans_count;
  else
    select fans_count into current_fans_count
    from public.ips
    where id = target_ip_id;
  end if;

  return coalesce(current_fans_count, 0);
end;
$$

create or replace function public.unfollow_ip(target_ip_id text)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := auth.uid();
  deleted_count integer := 0;
  current_fans_count integer := 0;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not exists (select 1 from public.ips where id = target_ip_id) then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  delete from public.ip_follows
  where user_id = actor_id and ip_id = target_ip_id;

  get diagnostics deleted_count = row_count;

  if deleted_count > 0 then
    update public.ips
    set fans_count = greatest(fans_count - 1, 0),
        updated_at = now()
    where id = target_ip_id
    returning fans_count into current_fans_count;
  else
    select fans_count into current_fans_count
    from public.ips
    where id = target_ip_id;
  end if;

  return coalesce(current_fans_count, 0);
end;
$$

create policy posts_update on public.posts for update
  using ((select auth.uid()) = user_id or (select public.is_staff()))
  with check (
    (select public.is_staff())
    or (
      (select auth.uid()) = user_id
      and (
        image_path is null
        or (storage.foldername(image_path))[1] = (select auth.uid())::text
      )
    )
  )

create or replace function public.create_post_comment(
  target_post_id uuid,
  comment_text text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := auth.uid();
  normalized_text text := nullif(btrim(comment_text), '');
  inserted_comment_id uuid;
  post_ip_id text;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if normalized_text is null then
    raise exception 'comment_text_required' using errcode = '22023';
  end if;

  select posts.ip_id
    into post_ip_id
    from public.posts
    where posts.id = target_post_id
      and posts.status = 'visible';

  if not found then
    raise exception 'post_not_visible' using errcode = '42501';
  end if;

  insert into public.comments (post_id, user_id, text)
  values (target_post_id, actor_id, normalized_text)
  returning id into inserted_comment_id;

  return jsonb_build_object('commentId', inserted_comment_id, 'ipId', post_ip_id);
end;
$$

create or replace function public.set_post_like(
  target_post_id uuid,
  should_like boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := auth.uid();
  post_ip_id text;
  current_liked boolean;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  select posts.ip_id
    into post_ip_id
    from public.posts
    where posts.id = target_post_id
      and posts.status = 'visible';

  if not found then
    raise exception 'post_not_visible' using errcode = '42501';
  end if;

  if coalesce(should_like, false) then
    insert into public.likes (post_id, user_id)
    values (target_post_id, actor_id)
    on conflict (post_id, user_id) do nothing;
  else
    delete from public.likes
    where post_id = target_post_id
      and user_id = actor_id;
  end if;

  select exists (
    select 1
    from public.likes
    where likes.post_id = target_post_id
      and likes.user_id = actor_id
  ) into current_liked;

  return jsonb_build_object('liked', current_liked, 'ipId', post_ip_id);
end;
$$

