-- Ensure staff hide actions only resolve reports linked to the hidden post.

create or replace function public.admin_hide_community_post(
  target_post_id uuid,
  target_report_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := auth.uid();
  previous_status post_status;
  target_ip_id text;
  linked_report_target report_target;
  linked_report_target_id text;
  linked_report_post_id uuid;
begin
  if actor_id is null or not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select posts.status, posts.ip_id
    into previous_status, target_ip_id
    from public.posts
    where posts.id = target_post_id
    for update;

  if not found then
    raise exception 'post_not_found' using errcode = '22023';
  end if;

  update public.posts
  set status = 'hidden'
  where posts.id = target_post_id;

  if target_report_id is not null then
    select reports.target_type, reports.target_id
      into linked_report_target, linked_report_target_id
      from public.reports
      where reports.id = target_report_id
      for update;

    if not found then
      raise exception 'report_not_found' using errcode = '22023';
    end if;

    if linked_report_target = 'post' then
      if linked_report_target_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        raise exception 'report_target_mismatch' using errcode = '22023';
      end if;

      linked_report_post_id := linked_report_target_id::uuid;
    elsif linked_report_target = 'comment' then
      if linked_report_target_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        raise exception 'report_target_mismatch' using errcode = '22023';
      end if;

      select comments.post_id
        into linked_report_post_id
        from public.comments
        where comments.id = linked_report_target_id::uuid;

      if not found then
        raise exception 'report_target_mismatch' using errcode = '22023';
      end if;
    else
      raise exception 'report_target_mismatch' using errcode = '22023';
    end if;

    if linked_report_post_id <> target_post_id then
      raise exception 'report_target_mismatch' using errcode = '22023';
    end if;

    update public.reports
    set status = 'resolved'
    where reports.id = target_report_id;
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'community_post_hide',
    'post:' || target_post_id::text,
    jsonb_build_object('from', previous_status, 'to', 'hidden', 'reportId', target_report_id)
  );

  return jsonb_build_object('ipId', target_ip_id);
end;
$$

-- Remove the previous prototype catalog rows before the licensed mock catalog seed runs.
-- Guard transactional/gacha/ticket references so production history is never silently deleted.

do $$
declare
  old_verticals text[] := array['blgl', 'rofan', 'global', 'vtuber', 'streamer'];
  old_ips text[] := array['hwasan', 'cheong', 'lumen', 'nocturne', 'lilac', 'hoshina', 'rune', 'aster'];
  old_goods text[] := array['g1', 'g2', 'g3', 'g4', 'g5', 'g6', 'g7', 'g8', 'g9', 'g10', 'g11', 'g12'];
  old_cards text[] := array['c1', 'c2', 'c3', 'c4', 'c5', 'c6', 'c7', 'c8', 'c9', 'c10', 'c11', 'c12'];
  old_events text[] := array['e1', 'e2', 'e3', 'e4', 'e5'];
  dependency_count integer;
begin
  select count(*) into dependency_count
  from public.order_items
  where good_id = any(old_goods);
  if dependency_count > 0 then
    raise exception 'old mock catalog cleanup aborted: % order_items reference old goods', dependency_count;
  end if;

  select count(*) into dependency_count
  from public.ticket_orders
  where event_id = any(old_events);
  if dependency_count > 0 then
    raise exception 'old mock catalog cleanup aborted: % ticket_orders reference old events', dependency_count;
  end if;

  select count(*) into dependency_count
  from public.card_pools
  where ip_id = any(old_ips);
  if dependency_count > 0 then
    raise exception 'old mock catalog cleanup aborted: % card_pools reference old IPs', dependency_count;
  end if;

  select count(*) into dependency_count
  from public.pull_results
  where card_id = any(old_cards);
  if dependency_count > 0 then
    raise exception 'old mock catalog cleanup aborted: % pull_results reference old cards', dependency_count;
  end if;

  select count(*) into dependency_count
  from public.user_cards
  where card_id = any(old_cards);
  if dependency_count > 0 then
    raise exception 'old mock catalog cleanup aborted: % user_cards reference old cards', dependency_count;
  end if;

  delete from public.cart_items
  where good_id = any(old_goods);

  delete from public.ticket_types
  where event_id = any(old_events);

  delete from public.ip_follows
  where ip_id = any(old_ips);

  update public.posts
  set ip_id = null
  where ip_id = any(old_ips);

  delete from public.goods
  where id = any(old_goods);

  delete from public.events
  where id = any(old_events);

  delete from public.cards
  where id = any(old_cards);

  delete from public.ips
  where id = any(old_ips);

  delete from public.verticals v
  where v.key = any(old_verticals)
    and not exists (
      select 1
      from public.ips i
      where i.vertical_key = v.key
    );
end $$

-- ============================================================================
-- RPC
-- ============================================================================

-- 카드 발급 프리미티브: pool_odds 기반(roll_rarity) 무작위 무상 발급 + 바인더 적립.
-- 내부 호출 전용 — open_draw_ticket(·이후 #64 play_game) 안에서만 부른다.
-- 결제로 카드·뽑기권을 직접 사는 RPC는 존재하지 않는다(ADR-0003 규제 가드).
create or replace function public.grant_cards(
  p_user_id uuid, p_pool_id uuid, p_source text, p_source_id uuid,
  p_idempotency_key text, p_count integer default 1
)
returns jsonb
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_existing jsonb;
  v_cards    jsonb := '[]'::jsonb;
  v_rarity   rarity;
  v_card     text;
  v_new      boolean;
begin
  if p_count < 1 or p_count > 100 then raise exception 'invalid count'; end if;

  -- 멱등: 같은 키의 기존 발급이 있으면 그 결과를 그대로 반환
  select granted_cards into v_existing from card_grants where idempotency_key = p_idempotency_key;
  if v_existing is not null then return v_existing; end if;

  for i in 1..p_count loop
    v_rarity := roll_rarity(p_pool_id);
    select c.id into v_card from cards c
      where c.pool_id = p_pool_id and c.rarity = v_rarity
      order by random() limit 1;
    if v_card is null then raise exception 'pool has no card of rarity %', v_rarity; end if;

    v_new := not exists (
      select 1 from user_cards uc where uc.user_id = p_user_id and uc.card_id = v_card
    );
    insert into user_cards as uc (user_id, card_id, qty) values (p_user_id, v_card, 1)
      on conflict on constraint user_cards_pkey do update set qty = uc.qty + 1;

    v_cards := v_cards || jsonb_build_object('cardId', v_card, 'rarity', v_rarity, 'isNew', v_new);
  end loop;

  insert into card_grants (user_id, pool_id, source, source_id, granted_cards, idempotency_key)
  values (p_user_id, p_pool_id, p_source, p_source_id, v_cards, p_idempotency_key);
  return v_cards;
end; $$

-- 뽑기권 개봉: 본인·미사용 검증 → 행 잠금 → 서버가 카드 결정 → 소비 기록.
-- 미사용 티켓은 풀 운영 기간과 무관하게 개봉 가능(무기한, ADR-0004).
-- 멱등: 이미 개봉된 티켓을 재요청하면 동일한 발급 결과를 반환한다(결과 불변).
create or replace function public.open_draw_ticket(p_ticket_id uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_user   uuid := (select auth.uid());
  v_ticket record;
  v_cards  jsonb;
  v_idem   text;
begin
  if v_user is null then raise exception 'auth required'; end if;

  select id, user_id, pool_id, consumed_at into v_ticket
    from draw_tickets where id = p_ticket_id for update;
  if v_ticket.id is null then raise exception 'ticket not found'; end if;
  if v_ticket.user_id <> v_user then raise exception 'forbidden'; end if;

  v_idem := 'draw_ticket:' || v_ticket.id::text;

  if v_ticket.consumed_at is not null then
    select granted_cards into v_cards from card_grants where idempotency_key = v_idem;
    if v_cards is not null then return v_cards; end if;  -- 멱등 재생
    raise exception 'ticket already consumed';
  end if;

  v_cards := grant_cards(v_user, v_ticket.pool_id, 'draw_ticket', v_ticket.id, v_idem, 1);
  update draw_tickets set consumed_at = now() where id = p_ticket_id;
  return v_cards;
end; $$

-- 결제 확정(웹훅): 멱등. 주문을 paid로. (P1 본문 유지 + ★뽑기권 발급 부수효과 추가)
create or replace function public.confirm_order_payment(
  p_idempotency_key text, p_order_id uuid, p_payment_key text, p_amount bigint, p_raw jsonb
)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_user uuid; v_total bigint; v_status order_status; v_expires_at timestamptz;
        v_existing record;
begin
  -- 멱등: 같은 목적/대상으로 이미 처리된 키만 무시한다.
  select id, purpose, ref_id, amount, status into v_existing
    from payments where idempotency_key = p_idempotency_key for update;
  if v_existing.id is not null then
    if v_existing.purpose <> 'order' or v_existing.ref_id is distinct from p_order_id then
      raise exception 'idempotency conflict';
    end if;
    if v_existing.status in ('paid', 'refunded') then return; end if;
    if v_existing.status <> 'pending' then raise exception 'payment not payable'; end if;
  end if;

  select user_id, total, status, expires_at into v_user, v_total, v_status, v_expires_at
    from orders where id = p_order_id for update;
  if v_user is null then raise exception 'order not found'; end if;
  if v_status <> 'pending' then raise exception 'order not payable'; end if;
  if v_expires_at is not null and now() >= v_expires_at then raise exception 'order expired'; end if;
  if p_amount <> v_total then raise exception 'amount mismatch'; end if;
  if v_existing.id is not null and v_existing.amount <> p_amount then raise exception 'amount mismatch'; end if;

  insert into payments (user_id, purpose, ref_id, amount, status, payment_key, idempotency_key, raw)
  values (v_user, 'order', p_order_id, p_amount, 'paid', p_payment_key, p_idempotency_key, p_raw)
  on conflict (idempotency_key) do update set status = 'paid', payment_key = excluded.payment_key, raw = excluded.raw;

  if v_status = 'pending' then
    update orders set status = 'paid', expires_at = null where id = p_order_id;

    -- ★ 무상 뽑기권(카드팩) 발급 부수효과(ADR-0004).
    -- 정책 매칭은 풀 바인딩 서사대로 IP 스코프: 풀의 IP에 속한 굿즈 소계가 min_amount 이상일 때만.
    -- 발급 시점엔 풀이 운영 중이어야 한다(풀 종료 = 신규 발급 중단).
    insert into draw_tickets (user_id, pool_id, source, source_id, ordinal)
    select v_user, rp.pool_id, 'order_paid', p_order_id,
           row_number() over (order by rp.id, gs.n)
    from reward_policies rp
    join card_pools cp on cp.id = rp.pool_id
    join lateral (
      select coalesce(sum(oi.qty * oi.unit_price), 0) as ip_subtotal
      from order_items oi
      join goods g on g.id = oi.good_id
      where oi.order_id = p_order_id and g.ip_id = cp.ip_id
    ) sub on true
    cross join lateral generate_series(1, rp.tickets_per_grant) as gs(n)
    where rp.trigger = 'order_paid'
      and rp.active
      and sub.ip_subtotal > 0
      and sub.ip_subtotal >= rp.min_amount
      and now() >= cp.active_from and (cp.active_to is null or now() < cp.active_to)
    on conflict (source, source_id, ordinal) do nothing;
  end if;
end; $$

-- 주문 취소/환불: 재고 복원 + refunds 기록. (P1 본문 유지 + ★미사용 뽑기권 회수 추가)
create or replace function public.cancel_order(p_order_id uuid, p_reason text)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_user uuid; v_status order_status; v_pay uuid; v_amt bigint; v_staff boolean := is_staff(); r record;
begin
  select user_id, status into v_user, v_status from orders where id = p_order_id for update;
  if v_user is null then raise exception 'order not found'; end if;
  if (select auth.uid()) <> v_user and not v_staff then raise exception 'forbidden'; end if;
  if v_status = 'canceled' then return; end if;
  if not v_staff and v_status not in ('pending', 'paid') then raise exception 'order not cancelable'; end if;

  for r in select good_id, qty from order_items where order_id = p_order_id loop
    update goods set stock_qty = stock_qty + r.qty where id = r.good_id;
  end loop;

  update orders set status = 'canceled' where id = p_order_id;

  -- ★ 미사용 뽑기권 회수(개봉된 티켓·발급된 카드는 회수하지 않음 — 무상 리워드).
  --   재고 복원과 같은 운영 상태 원복이며, 발급 이력(card_grants)은 그대로 남는다.
  delete from draw_tickets
    where source = 'order_paid' and source_id = p_order_id and consumed_at is null;

  select id, amount into v_pay, v_amt from payments
    where purpose = 'order' and ref_id = p_order_id and status = 'paid' limit 1;
  if v_pay is not null then
    insert into refunds (payment_id, amount, reason) values (v_pay, v_amt, p_reason);
    update payments set status = 'refunded' where id = v_pay;
  end if;
end; $$

-- ============================================================================
-- RPC
-- ============================================================================

-- 참여형 게임 1회: 자격·활성 창·일일 한도(KST 자정 경계) → 서버 RNG 발급 → 기록.
-- 멱등: 일일 한도 소진 후 재호출은 그 날 마지막 결과를 그대로 반환(발급 불변 —
--       같은 시드 → 같은 연출. 스펙 §4 "재호출 → 이전 결과 반환").
-- 동시성: user×game advisory xact lock으로 카운트→발급→기록을 직렬화.
--         games 행 잠금은 전 사용자를 직렬화해서 부적합. idempotency_key unique는
--         잠금 우회 시 트랜잭션 전체(발급 포함)를 원자 롤백하는 백스톱.
create or replace function public.play_game(p_game_id text)
returns jsonb
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_user   uuid := (select auth.uid());
  v_game   record;
  v_today  date;
  v_count  integer;
  v_last   jsonb;
  v_play   uuid;
  v_idem   text;
  v_seed   text;
  v_cards  jsonb;
  v_result jsonb;
begin
  if v_user is null then raise exception 'auth required'; end if;

  select id, reward_pool_id, per_user_daily_limit, active_from, active_to
    into v_game from games where id = p_game_id;
  if v_game.id is null then raise exception 'game not found'; end if;
  if now() < v_game.active_from or (v_game.active_to is not null and now() >= v_game.active_to) then
    raise exception 'game not active';
  end if;
  -- 풀 활성 창은 검사하지 않는다 — 게임 자체의 active_from/to가 운영 창의 진실원
  -- (개봉과 같은 무기한 규율, ADR-0004. 풀 종료 시 staff가 게임도 종료한다).
  if v_game.reward_pool_id is null then raise exception 'game has no reward pool'; end if;

  perform pg_advisory_xact_lock(
    hashtextextended('play_game:' || v_user::text || ':' || p_game_id, 0));

  v_today := (now() at time zone 'Asia/Seoul')::date;

  select count(*) into v_count from game_plays
    where game_id = p_game_id and user_id = v_user
      and (created_at at time zone 'Asia/Seoul')::date = v_today;

  if v_count >= v_game.per_user_daily_limit then
    -- 마지막 슬롯의 멱등 키로 정확 조회 — created_at 정렬은 같은 초/트랜잭션의
    -- 연속 플레이에서 동률이라 재생 결과가 흔들린다.
    select result into v_last from game_plays
      where idempotency_key = 'game_play:' || p_game_id || ':' || v_user::text || ':'
            || to_char(v_today, 'YYYY-MM-DD') || ':' || v_count;
    if v_last is null then raise exception 'daily limit state corrupted'; end if;
    return v_last;
  end if;

  v_play := extensions.gen_random_uuid();
  v_idem := 'game_play:' || p_game_id || ':' || v_user::text || ':'
            || to_char(v_today, 'YYYY-MM-DD') || ':' || (v_count + 1);
  v_seed := encode(extensions.gen_random_bytes(16), 'hex');

  v_cards := grant_cards(v_user, v_game.reward_pool_id, 'game_play', v_play, v_idem, 1);

  v_result := jsonb_build_object(
    'playId', v_play,
    'rewards', (
      select coalesce(jsonb_agg(jsonb_build_object('kind', 'card') || t.elem order by t.ord), '[]'::jsonb)
      from jsonb_array_elements(v_cards) with ordinality as t(elem, ord)
    ),
    'animationSeed', v_seed
  );

  insert into game_plays (id, game_id, user_id, result, idempotency_key)
  values (v_play, p_game_id, v_user, v_result, v_idem);

  return v_result;
end; $$

-- 로그인 시 로컬 장바구니를 서버 장바구니에 원자적으로 병합한다.
-- 재시도와 동시 탭에서도 더 작은 수량이 기존 수량을 덮어쓰지 않는다.
create or replace function public.merge_cart_items(p_items jsonb)
returns void
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise check_violation using message = 'cart items must be an array';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_items) as item(good_id text, qty integer)
    where nullif(btrim(item.good_id), '') is null
       or item.qty is null
       or item.qty <= 0
  ) then
    raise check_violation using message = 'invalid cart item';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_items) as item(good_id text, qty integer)
    left join public.goods good on good.id = btrim(item.good_id)
    where good.id is null
  ) then
    raise foreign_key_violation using message = 'cart good not found';
  end if;

  insert into public.cart_items (user_id, good_id, qty)
  select v_user, btrim(item.good_id), max(item.qty)
  from jsonb_to_recordset(p_items) as item(good_id text, qty integer)
  group by btrim(item.good_id)
  on conflict (user_id, good_id) do update
  set qty = greatest(public.cart_items.qty, excluded.qty);
end;
$$

create or replace function public.place_order(
  p_address jsonb,
  p_checkout_key uuid
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := (select auth.uid());
  v_order uuid;
  v_existing_address jsonb;
  v_total bigint := 0;
  v_item_count integer := 0;
  v_recipient_name text;
  v_phone text;
  v_postal_code text;
  v_address1 text;
  v_optional text;
  r record;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if not exists (
    select 1
    from public.profiles as profile
    join auth.users as auth_user on auth_user.id = profile.id
    where profile.id = v_user
      and nullif(btrim(coalesce(profile.email, auth_user.email)), '') is not null
      and nullif(btrim(profile.nickname), '') is not null
      and profile.birth_date is not null
      and profile.birth_date <= current_date
      and profile.onboarded_at is not null
      and profile.consents ->> 'terms' = 'true'
      and profile.consents ->> 'privacy' = 'true'
  ) then
    raise insufficient_privilege using message = 'onboarding required';
  end if;

  if p_checkout_key is null then
    raise not_null_violation using message = 'checkout key required';
  end if;

  if p_address is null or jsonb_typeof(p_address) <> 'object' then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if not (p_address ?& array['recipientName', 'phone', 'postalCode', 'address1'])
     or exists (
       select 1
       from jsonb_object_keys(p_address) as address_key(key)
       where address_key.key not in (
         'recipientName', 'phone', 'postalCode', 'address1', 'address2', 'deliveryNote'
       )
     )
     or exists (
       select 1
       from jsonb_each(p_address) as address_value(key, value)
       where jsonb_typeof(address_value.value) <> 'string'
     ) then
    raise check_violation using message = 'invalid checkout address';
  end if;

  v_recipient_name := p_address ->> 'recipientName';
  v_phone := p_address ->> 'phone';
  v_postal_code := p_address ->> 'postalCode';
  v_address1 := p_address ->> 'address1';

  if v_recipient_name <> btrim(v_recipient_name, E' \t\n\r\f\v')
     or length(v_recipient_name) not between 1 and 50
     or v_phone !~ '^[0-9]{8,15}$'
     or v_postal_code !~ '^[0-9]{5}$'
     or v_address1 <> btrim(v_address1, E' \t\n\r\f\v')
     or length(v_address1) not between 1 and 200 then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if p_address ? 'address2' then
    v_optional := p_address ->> 'address2';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  if p_address ? 'deliveryNote' then
    v_optional := p_address ->> 'deliveryNote';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  -- 같은 사용자의 다른 탭 주문을 직렬화한다. 동일 키 재시도는 먼저 생성된
  -- 주문을 반환하고, 다른 키는 첫 주문이 비운 장바구니를 확인하게 된다.
  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  select orders.id, orders.address
    into v_order, v_existing_address
  from public.orders
  where orders.user_id = v_user
    and orders.checkout_key = p_checkout_key;

  if found then
    if v_existing_address is distinct from p_address then
      raise unique_violation using message = 'checkout key conflict';
    end if;
    return v_order;
  end if;

  insert into public.orders (user_id, status, total, address, expires_at, checkout_key)
  values (v_user, 'pending', 0, p_address, now() + interval '15 minutes', p_checkout_key)
  returning id into v_order;

  -- 카트와 재고를 같은 결정적 순서로 잠근 뒤 DB 가격·수량만으로 스냅샷을 만든다.
  for r in
    select cart.good_id, cart.qty, good.price, good.stock, good.stock_qty
    from public.cart_items as cart
    join public.goods as good on good.id = cart.good_id
    where cart.user_id = v_user
    order by cart.good_id
    for update of cart, good
  loop
    v_item_count := v_item_count + 1;

    if r.stock = 'soldout' or r.stock_qty < r.qty then
      raise check_violation using message = format('out of stock: %s', r.good_id);
    end if;

    update public.goods
    set stock_qty = stock_qty - r.qty
    where id = r.good_id;

    insert into public.order_items (order_id, good_id, qty, unit_price)
    values (v_order, r.good_id, r.qty, r.price);

    -- 조회 시 잠근 스냅샷 행만 지운다. 동시에 새로 담긴 다른 상품까지
    -- 마지막 broad delete가 없애지 않도록 상품 단위로 소비한다.
    delete from public.cart_items
    where user_id = v_user
      and good_id = r.good_id;

    v_total := v_total + (r.price::bigint * r.qty::bigint);
  end loop;

  if v_item_count = 0 then
    raise check_violation using message = 'cart empty';
  end if;

  update public.orders
  set total = v_total
  where id = v_order;

  return v_order;
end;
$$

