create or replace function public.claim_order_cancellation(
  p_order_id uuid,
  p_user_id uuid
)
returns text
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id uuid;
  v_status public.order_status;
  v_previous_status public.order_status;
begin
  select orders.user_id, orders.status
  into v_user_id, v_status
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found or p_user_id is null or v_user_id is distinct from p_user_id then
    return 'not_found';
  end if;

  if v_status = 'canceled' then
    delete from public.order_cancellation_claims
    where order_id = p_order_id;
    return 'already_canceled';
  end if;

  if v_status not in ('pending', 'paid') then
    return 'not_cancelable';
  end if;

  select claim.previous_status
  into v_previous_status
  from public.order_cancellation_claims as claim
  where claim.order_id = p_order_id;

  if found then
    return v_previous_status::text;
  end if;

  insert into public.order_cancellation_claims (
    order_id,
    requested_by,
    previous_status
  )
  values (
    p_order_id,
    p_user_id,
    v_status
  );

  return v_status::text;
end;
$$

-- 결제 승인과 취소가 같은 주문에서 겹쳐도 교착하지 않도록 두 RPC 모두
-- 주문을 먼저 잠그고 결제 행을 잠근다. 기존 승인 동작과 멱등 계약은 유지한다.
create or replace function public.confirm_order_payment(
  p_idempotency_key text,
  p_order_id uuid,
  p_payment_key text,
  p_amount bigint,
  p_raw jsonb
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid;
  v_total bigint;
  v_status public.order_status;
  v_expires_at timestamptz;
  v_existing record;
begin
  select orders.user_id, orders.total, orders.status, orders.expires_at
    into v_user, v_total, v_status, v_expires_at
  from public.orders
  where orders.id = p_order_id
  for update;

  -- 멱등: 같은 목적/대상으로 이미 처리된 키만 무시한다.
  select payments.id, payments.purpose, payments.ref_id, payments.amount, payments.status
    into v_existing
  from public.payments
  where payments.idempotency_key = p_idempotency_key
  for update;

  if v_existing.id is not null then
    if v_existing.purpose <> 'order' or v_existing.ref_id is distinct from p_order_id then
      raise exception 'idempotency conflict';
    end if;
    if v_existing.status in ('paid', 'refunded') then
      return;
    end if;
    if v_existing.status <> 'pending' then
      raise exception 'payment not payable';
    end if;
  end if;

  if exists (
    select 1
    from public.order_cancellation_claims as claim
    where claim.order_id = p_order_id
  ) then
    raise exception 'order not payable';
  end if;

  if v_user is null then
    raise exception 'order not found';
  end if;
  if v_status <> 'pending' then
    raise exception 'order not payable';
  end if;
  if v_expires_at is not null and now() >= v_expires_at then
    raise exception 'order expired';
  end if;
  if p_amount <> v_total then
    raise exception 'amount mismatch';
  end if;
  if v_existing.id is not null and v_existing.amount <> p_amount then
    raise exception 'amount mismatch';
  end if;

  insert into public.payments (
    user_id,
    purpose,
    ref_id,
    amount,
    status,
    payment_key,
    idempotency_key,
    raw
  )
  values (
    v_user,
    'order',
    p_order_id,
    p_amount,
    'paid',
    p_payment_key,
    p_idempotency_key,
    p_raw
  )
  on conflict (idempotency_key) do update
    set
      status = 'paid',
      payment_key = excluded.payment_key,
      raw = excluded.raw;

  if v_status = 'pending' then
    update public.orders
    set status = 'paid', expires_at = null
    where id = p_order_id;

    insert into public.draw_tickets (user_id, pool_id, source, source_id, ordinal)
    select
      v_user,
      reward_policy.pool_id,
      'order_paid',
      p_order_id,
      row_number() over (order by reward_policy.id, grant_series.n)
    from public.reward_policies as reward_policy
    join public.card_pools as card_pool on card_pool.id = reward_policy.pool_id
    join lateral (
      select coalesce(sum(order_item.qty * order_item.unit_price), 0) as ip_subtotal
      from public.order_items as order_item
      where order_item.order_id = p_order_id
        and order_item.good_ip_id_snapshot = card_pool.ip_id
    ) as subtotal on true
    cross join lateral generate_series(1, reward_policy.tickets_per_grant) as grant_series(n)
    where reward_policy.trigger = 'order_paid'
      and reward_policy.active
      and subtotal.ip_subtotal > 0
      and subtotal.ip_subtotal >= reward_policy.min_amount
      and now() >= card_pool.active_from
      and (card_pool.active_to is null or now() < card_pool.active_to)
    on conflict (source, source_id, ordinal) do nothing;
  end if;
end;
$$

create trigger trg_order_cancellation_requests_updated
before update on public.order_cancellation_requests
for each row execute function public.set_updated_at()

-- 신규 요청은 사용자 소유권과 주문 상태를 주문 행 잠금 아래 다시 확인한다.
-- 결제 행이 전혀 없는 pending만 즉시 정리하고, 그 외에는 provider 호출 없이
-- requested 상태로 남겨 배송/결제 확정을 차단한다.
create or replace function public.request_order_cancellation(
  p_order_id uuid,
  p_user_id uuid,
  p_reason text
)
returns text
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id uuid;
  v_status public.order_status;
  v_request_id uuid;
begin
  select orders.user_id, orders.status
  into v_user_id, v_status
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found or p_user_id is null or v_user_id is distinct from p_user_id then
    return 'not_found';
  end if;

  if v_status = 'canceled' then
    return 'already_canceled';
  end if;

  if v_status not in ('pending', 'paid') then
    return 'not_cancelable';
  end if;

  if p_reason is null
    or btrim(p_reason) <> p_reason
    or length(p_reason) not between 1 and 200
  then
    raise check_violation using message = 'invalid cancellation reason';
  end if;

  if exists (
    select 1
    from public.order_cancellation_requests as request
    where request.order_id = p_order_id
      and request.status in ('requested', 'processing', 'needs_review')
  ) then
    return 'already_requested';
  end if;

  insert into public.order_cancellation_requests (
    order_id,
    requested_by,
    reason,
    status
  )
  values (
    p_order_id,
    p_user_id,
    p_reason,
    'requested'
  )
  returning id into v_request_id;

  if v_status = 'pending'
    and not exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'order'
        and payment.ref_id = p_order_id
    )
  then
    perform public.finalize_order_cancellation_with_provider_evidence(
      p_order_id,
      p_reason,
      array[]::text[]
    );

    update public.order_cancellation_requests
    set
      status = 'completed',
      completed_at = now(),
      updated_at = now()
    where id = v_request_id;

    return 'completed';
  end if;

  return 'requested';
end;
$$

-- provider 호출 결과가 불확실하면 claim과 주문/재고를 그대로 두고 운영 검토로 전환한다.
create or replace function public.mark_order_cancellation_needs_review(
  p_request_id uuid,
  p_actor_id uuid,
  p_error_code text
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_id uuid;
  v_request_status text;
begin
  if p_actor_id is null or not exists (
    select 1
    from public.profiles as profile
    where profile.id = p_actor_id
      and profile.role in ('staff', 'admin')
  ) then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if p_error_code is null or p_error_code !~ '^[a-z0-9_]{1,64}$' then
    raise check_violation using message = 'invalid review code';
  end if;

  select request.order_id
  into v_order_id
  from public.order_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'cancellation_request_not_found';
  end if;

  perform orders.id
  from public.orders
  where orders.id = v_order_id
  for update;

  select request.status
  into v_request_status
  from public.order_cancellation_requests as request
  where request.id = p_request_id
  for update;

  if v_request_status = 'needs_review' then
    return;
  end if;

  if v_request_status <> 'processing' then
    raise exception using message = 'cancellation_request_not_processing';
  end if;

  if not exists (
    select 1
    from public.order_cancellation_claims as claim
    where claim.order_id = v_order_id
  ) then
    raise exception using message = 'cancellation_claim_missing';
  end if;

  update public.refunds
  set status = 'failed'
  where cancellation_request_id = p_request_id
    and status <> 'done';

  update public.order_cancellation_requests
  set
    status = 'needs_review',
    last_error_code = p_error_code,
    updated_at = now()
  where id = p_request_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_actor_id,
    'admin.order.cancellation_needs_review',
    'order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'from', 'processing',
      'to', 'needs_review',
      'errorCode', p_error_code
    )
  );
end;
$$

-- needs_review는 삭제/거절하지 않고 같은 claim·refund intent로만 재조회/재시도한다.
create or replace function public.admin_begin_order_cancellation_reconcile(
  p_request_id uuid
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := (select auth.uid());
  v_order_id uuid;
  v_request_status text;
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff required';
  end if;

  select request.order_id
  into v_order_id
  from public.order_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'cancellation_request_not_found';
  end if;

  perform orders.id
  from public.orders
  where orders.id = v_order_id
  for update;

  select request.status
  into v_request_status
  from public.order_cancellation_requests as request
  where request.id = p_request_id
  for update;

  if v_request_status = 'processing' then
    return;
  end if;

  if v_request_status <> 'needs_review' then
    raise exception using message = 'cancellation_request_not_reconcilable';
  end if;

  if not exists (
    select 1
    from public.order_cancellation_claims as claim
    where claim.order_id = v_order_id
  ) then
    raise exception using message = 'cancellation_claim_missing';
  end if;

  update public.refunds
  set status = 'requested'
  where cancellation_request_id = p_request_id
    and status = 'failed';

  update public.order_cancellation_requests
  set
    status = 'processing',
    decided_by = coalesce(decided_by, v_actor),
    decided_at = coalesce(decided_at, now()),
    provider_started_at = coalesce(provider_started_at, now()),
    updated_at = now()
  where id = p_request_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.cancellation_reconcile_started',
    'order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'from', 'needs_review',
      'to', 'processing'
    )
  );
end;
$$

-- fresh provider GET으로 모든 active 결제의 전액 취소를 확인한 뒤에만 #92 finalizer를
-- 호출한다. payment key 배열은 증거 비교에만 쓰고 테이블/감사 로그에는 남기지 않는다.
create or replace function public.complete_order_cancellation_request(
  p_request_id uuid,
  p_provider_payment_keys text[],
  p_actor_id uuid
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_id uuid;
  v_reason text;
  v_request_status text;
  v_provider_payment_keys text[];
  v_refund_count integer;
begin
  if p_actor_id is null or not exists (
    select 1
    from public.profiles as profile
    where profile.id = p_actor_id
      and profile.role in ('staff', 'admin')
  ) then
    raise insufficient_privilege using message = 'staff required';
  end if;

  select request.order_id
  into v_order_id
  from public.order_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'cancellation_request_not_found';
  end if;

  perform orders.id
  from public.orders
  where orders.id = v_order_id
  for update;

  select request.status, request.reason
  into v_request_status, v_reason
  from public.order_cancellation_requests as request
  where request.id = p_request_id
  for update;

  if v_request_status = 'completed' then
    return;
  end if;

  if v_request_status <> 'processing' then
    raise exception using message = 'cancellation_request_not_processing';
  end if;

  if not exists (
    select 1
    from public.order_cancellation_claims as claim
    where claim.order_id = v_order_id
  ) then
    raise exception using message = 'cancellation_claim_missing';
  end if;

  select coalesce(array_agg(keys.payment_key order by keys.payment_key), array[]::text[])
  into v_provider_payment_keys
  from (
    select distinct btrim(payment_key) as payment_key
    from unnest(coalesce(p_provider_payment_keys, array[]::text[])) as input(payment_key)
    where payment_key is not null
      and btrim(payment_key) <> ''
  ) as keys;

  -- 로컬 장부가 canceled/refunded여도 provider 취소 완료의 진실원은 fresh GET이다.
  -- 실제 capture가 없었던 failed 결제만 증거 대상에서 제외한다.
  if exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'order'
      and payment.ref_id = v_order_id
      and payment.status <> 'failed'
      and (
        payment.payment_key is null
        or not (payment.payment_key = any(v_provider_payment_keys))
      )
  ) then
    raise exception using message = 'provider cancellation required';
  end if;

  perform public.finalize_order_cancellation_with_provider_evidence(
    v_order_id,
    v_reason,
    v_provider_payment_keys
  );

  update public.refunds as refund
  set cancellation_request_id = p_request_id
  from public.payments as payment
  where refund.payment_id = payment.id
    and payment.purpose = 'order'
    and payment.ref_id = v_order_id
    and (
      refund.cancellation_request_id is null
      or refund.cancellation_request_id = p_request_id
    );

  if exists (
    select 1
    from public.refunds as refund
    where refund.cancellation_request_id = p_request_id
      and refund.status <> 'done'
  ) then
    raise exception using message = 'provider cancellation required';
  end if;

  select count(*)::integer
  into v_refund_count
  from public.refunds as refund
  where refund.cancellation_request_id = p_request_id
    and refund.status = 'done';

  update public.order_cancellation_requests
  set
    status = 'completed',
    completed_at = coalesce(completed_at, now()),
    updated_at = now()
  where id = p_request_id
    and status = 'processing';

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_actor_id,
    'admin.order.cancellation_completed',
    'order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'to', 'completed',
      'refundCount', v_refund_count
    )
  );
end;
$$

-- 배송 상태는 명시된 단방향 상태기계만 허용하고, 실제 전이만 감사한다.
create or replace function public.admin_update_order_status(
  p_order_id uuid,
  p_status public.order_status
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := (select auth.uid());
  v_current_status public.order_status;
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff required';
  end if;

  select orders.status
  into v_current_status
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise no_data_found using message = 'order_not_found';
  end if;

  if p_status not in ('shipping', 'done') then
    raise check_violation using message = 'invalid_order_status';
  end if;

  if v_current_status = p_status then
    return;
  end if;

  if not (
    (v_current_status = 'paid' and p_status = 'shipping')
    or (v_current_status = 'shipping' and p_status = 'done')
  ) then
    raise exception using message = 'invalid_order_transition';
  end if;

  if exists (
    select 1
    from public.order_cancellation_requests as request
    where request.order_id = p_order_id
      and request.status in ('requested', 'processing', 'needs_review')
  ) then
    raise check_violation using message = 'order cancellation in progress';
  end if;

  update public.orders
  set status = p_status
  where id = p_order_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.status_updated',
    'order:' || p_order_id::text,
    jsonb_build_object(
      'from', v_current_status::text,
      'to', p_status::text
    )
  );
end;
$$

-- Audited, idempotent inventory adjustments for staff operations (#94).

create or replace function public.admin_adjust_stock(
  target_adjustment_id uuid,
  target_good_id text,
  target_expected_stock_qty integer,
  target_delta integer,
  target_reason text
)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_reason text;
  previous_stock_qty integer;
  next_stock_qty bigint;
  requested_diff jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  normalized_reason := btrim(target_reason, E' \t\n\r\f\v');

  if target_adjustment_id is null then
    raise exception 'invalid_adjustment_id' using errcode = '22004';
  end if;

  if target_expected_stock_qty is null or target_expected_stock_qty < 0 then
    raise exception 'invalid_expected_stock_qty' using errcode = '22023';
  end if;

  if target_delta is null or target_delta = 0 then
    raise exception 'invalid_stock_delta' using errcode = '22023';
  end if;

  if normalized_reason is null
    or char_length(normalized_reason) < 1
    or char_length(normalized_reason) > 200
  then
    raise exception 'invalid_stock_reason' using errcode = '22023';
  end if;

  -- A lost-response retry must observe the first committed audit before deciding
  -- whether this adjustment ID is an idempotent replay or a conflicting reuse.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_stock_adjustment:' || target_adjustment_id::text, 0)
  );

  next_stock_qty := target_expected_stock_qty::bigint + target_delta::bigint;
  requested_diff := jsonb_build_object(
    'from', target_expected_stock_qty,
    'delta', target_delta,
    'to', next_stock_qty,
    'reason', normalized_reason
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_adjustment_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.good.stock_adjusted'
      and existing_target = 'goods:' || target_good_id
      and existing_diff = requested_diff
    then
      return (existing_diff ->> 'to')::integer;
    end if;

    raise exception 'adjustment_conflict' using errcode = '23505';
  end if;

  select good.stock_qty
    into previous_stock_qty
  from public.goods as good
  where good.id = target_good_id
  for update;

  if not found then
    raise exception 'good_not_found' using errcode = 'P0002';
  end if;

  if previous_stock_qty <> target_expected_stock_qty then
    raise exception 'stock_changed' using errcode = 'P0001';
  end if;

  next_stock_qty := previous_stock_qty::bigint + target_delta::bigint;

  if next_stock_qty < 0 or next_stock_qty > 2147483647 then
    raise exception 'stock_out_of_range' using errcode = '22003';
  end if;

  update public.goods
  set stock_qty = next_stock_qty::integer
  where id = target_good_id;

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_adjustment_id,
    actor_id,
    'admin.good.stock_adjusted',
    'goods:' || target_good_id,
    jsonb_build_object(
      'from', previous_stock_qty,
      'delta', target_delta,
      'to', next_stock_qty,
      'reason', normalized_reason
    )
  );

  return next_stock_qty::integer;
end;
$$

create or replace function public.admin_upsert_ticket_type(
  target_operation_id uuid,
  target_ticket_type_id uuid,
  target_event_id text,
  target_name text,
  target_price integer,
  target_capacity integer
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_event_id text := btrim(target_event_id, E' \t\n\r\f\v');
  normalized_name text := btrim(target_name, E' \t\n\r\f\v');
  request_payload jsonb;
  previous_ticket_type public.ticket_types%rowtype;
  previous_payload jsonb := null;
  after_payload jsonb;
  ticket_type_exists boolean := false;
  has_ticket_history boolean := false;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if target_ticket_type_id is null then
    raise exception 'invalid_ticket_type_id' using errcode = '22004';
  end if;

  if normalized_event_id is null or normalized_event_id = '' then
    raise exception 'event_not_found' using errcode = 'P0002';
  end if;

  if normalized_name is null or normalized_name = '' then
    raise exception 'invalid_ticket_type_name' using errcode = '22023';
  end if;

  if target_price is null or target_price < 0 then
    raise exception 'invalid_ticket_type_price' using errcode = '22023';
  end if;

  if target_capacity is null or target_capacity < 0 then
    raise exception 'invalid_ticket_type_capacity' using errcode = '22023';
  end if;

  request_payload := jsonb_build_object(
    'event_id', normalized_event_id,
    'name', normalized_name,
    'price', target_price,
    'capacity', target_capacity
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_ticket_type_operation:' || target_operation_id::text, 0)
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.ticket_type.upserted'
      and existing_target = 'ticket_types:' || target_ticket_type_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_ticket_type_id;
    end if;

    raise exception 'operation_conflict' using errcode = '23505';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_ticket_type:' || target_ticket_type_id::text, 0)
  );

  perform 1
  from public.events
  where id = normalized_event_id
  for key share;

  if not found then
    raise exception 'event_not_found' using errcode = 'P0002';
  end if;

  select ticket_type.*
    into previous_ticket_type
  from public.ticket_types as ticket_type
  where ticket_type.id = target_ticket_type_id
  for update;

  ticket_type_exists := found;

  if ticket_type_exists then
    if target_capacity < previous_ticket_type.sold then
      raise exception 'capacity_below_sold' using errcode = '23514';
    end if;

    select exists (
      select 1
      from public.tickets as ticket
      where ticket.ticket_type_id = target_ticket_type_id
    ) into has_ticket_history;

    if has_ticket_history and (
      previous_ticket_type.event_id is distinct from normalized_event_id
      or previous_ticket_type.name is distinct from normalized_name
      or previous_ticket_type.price is distinct from target_price
    ) then
      raise exception 'ticket_type_catalog_locked' using errcode = '23514';
    end if;

    previous_payload := jsonb_build_object(
      'event_id', previous_ticket_type.event_id,
      'name', previous_ticket_type.name,
      'price', previous_ticket_type.price,
      'capacity', previous_ticket_type.capacity,
      'sold', previous_ticket_type.sold
    );

    update public.ticket_types
    set event_id = normalized_event_id,
        name = normalized_name,
        price = target_price,
        capacity = target_capacity
    where id = target_ticket_type_id;

    after_payload := jsonb_build_object(
      'event_id', normalized_event_id,
      'name', normalized_name,
      'price', target_price,
      'capacity', target_capacity,
      'sold', previous_ticket_type.sold
    );
  else
    insert into public.ticket_types (id, event_id, name, price, capacity)
    values (
      target_ticket_type_id,
      normalized_event_id,
      normalized_name,
      target_price,
      target_capacity
    );

    after_payload := jsonb_build_object(
      'event_id', normalized_event_id,
      'name', normalized_name,
      'price', target_price,
      'capacity', target_capacity,
      'sold', 0
    );
  end if;

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.ticket_type.upserted',
    'ticket_types:' || target_ticket_type_id::text,
    jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_ticket_type_id;
end;
$$

create function public.reserve_tickets(
  p_user_id uuid,
  p_ticket_type_id uuid,
  p_qty integer,
  p_reservation_key uuid
)
returns uuid
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := p_user_id;
  v_event_id text;
  v_locked_event_id text;
  v_event_status text;
  v_capacity integer;
  v_sold integer;
  v_price integer;
  v_per_user_limit integer;
  v_sales_open_at timestamptz;
  v_existing_order public.ticket_orders%rowtype;
  v_existing_ticket_type_id uuid;
  v_existing_ticket_type_count bigint;
  v_existing_qty bigint;
  v_already_reserved bigint;
  v_order_id uuid;
begin
  if v_user is null then
    raise not_null_violation using message = 'user required';
  end if;

  if not exists (
    select 1
    from public.profiles as profile
    join auth.users as auth_user on auth_user.id = profile.id
    where profile.id = v_user
      and nullif(btrim(coalesce(profile.email, auth_user.email)), '') is not null
      and nullif(btrim(profile.nickname), '') is not null
      and profile.birth_date is not null
      and profile.birth_date <= current_date
      and profile.onboarded_at is not null
      and profile.consents ->> 'terms' = 'true'
      and profile.consents ->> 'privacy' = 'true'
  ) then
    raise insufficient_privilege using message = 'onboarding required';
  end if;

  if p_qty is null or p_qty < 1 then
    raise check_violation using message = 'quantity must be positive';
  end if;

  if p_reservation_key is null then
    raise not_null_violation using message = 'reservation key required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'ticket_reservation:' || v_user::text || ':' || p_reservation_key::text,
      0
    )
  );

  select ticket_order.*
    into v_existing_order
  from public.ticket_orders as ticket_order
  where ticket_order.user_id = v_user
    and ticket_order.reservation_key = p_reservation_key
  for share;

  if found then
    select
      min(ticket.ticket_type_id::text)::uuid,
      count(distinct ticket.ticket_type_id),
      count(*)
      into
        v_existing_ticket_type_id,
        v_existing_ticket_type_count,
        v_existing_qty
    from public.tickets as ticket
    where ticket.ticket_order_id = v_existing_order.id;

    if v_existing_ticket_type_count = 1
      and v_existing_ticket_type_id = p_ticket_type_id
      and v_existing_qty = p_qty::bigint
    then
      return v_existing_order.id;
    end if;

    raise unique_violation using message = 'reservation conflict';
  end if;

  select ticket_type.event_id
    into v_event_id
  from public.ticket_types as ticket_type
  where ticket_type.id = p_ticket_type_id;

  if not found then
    raise no_data_found using message = 'ticket type not found';
  end if;

  select event_record.status
    into v_event_status
  from public.events as event_record
  where event_record.id = v_event_id
  for share of event_record;

  if not found then
    raise no_data_found using message = 'event not found';
  end if;

  select
    ticket_type.event_id,
    ticket_type.capacity,
    ticket_type.sold,
    ticket_type.price,
    ticket_type.per_user_limit,
    ticket_type.sales_open_at
    into
      v_locked_event_id,
      v_capacity,
      v_sold,
      v_price,
      v_per_user_limit,
      v_sales_open_at
  from public.ticket_types as ticket_type
  where ticket_type.id = p_ticket_type_id
  for update of ticket_type;

  if not found then
    raise no_data_found using message = 'ticket type not found';
  end if;

  if v_locked_event_id is distinct from v_event_id then
    raise serialization_failure using message = 'ticket type changed';
  end if;

  if v_event_status <> '예매중' then
    raise check_violation using message = 'event not bookable';
  end if;

  if v_price <= 0 then
    raise check_violation using message = 'paid ticket required';
  end if;

  if v_sales_open_at is not null and now() < v_sales_open_at then
    raise check_violation using message = 'sales not open';
  end if;

  if p_qty::bigint > v_capacity::bigint - v_sold::bigint then
    raise check_violation using message = 'sold out';
  end if;

  select count(*)
    into v_already_reserved
  from public.tickets as ticket
  join public.ticket_orders as ticket_order
    on ticket_order.id = ticket.ticket_order_id
  where ticket.ticket_type_id = p_ticket_type_id
    and ticket_order.user_id = v_user
    and ticket_order.status <> 'canceled';

  if v_already_reserved + p_qty::bigint > v_per_user_limit::bigint then
    raise check_violation using message = 'per-user limit exceeded';
  end if;

  update public.ticket_types
  set sold = sold + p_qty
  where id = p_ticket_type_id;

  insert into public.ticket_orders (
    user_id,
    event_id,
    status,
    total,
    expires_at,
    reservation_key
  )
  values (
    v_user,
    v_event_id,
    'pending',
    v_price::bigint * p_qty::bigint,
    now() + interval '10 minutes',
    p_reservation_key
  )
  returning id into v_order_id;

  insert into public.tickets (ticket_order_id, ticket_type_id)
  select v_order_id, p_ticket_type_id
  from generate_series(1, p_qty);

  return v_order_id;
end;
$$

create or replace function public.confirm_ticket_payment(
  p_idempotency_key text,
  p_ticket_order_id uuid,
  p_payment_key text,
  p_amount bigint,
  p_raw jsonb
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid;
  v_total bigint;
  v_order_status public.ticket_order_status;
  v_expires_at timestamptz;
  v_existing_payment public.payments%rowtype;
  v_has_existing_payment boolean := false;
begin
  if p_idempotency_key is null
    or nullif(btrim(p_idempotency_key), '') is null
    or length(p_idempotency_key) > 200
    or p_payment_key is null
    or nullif(btrim(p_payment_key), '') is null
    or length(p_payment_key) > 200
  then
    raise check_violation using message = 'invalid payment evidence';
  end if;

  if p_idempotency_key is distinct from p_payment_key then
    raise unique_violation using message = 'idempotency conflict';
  end if;

  select
    ticket_order.user_id,
    ticket_order.total,
    ticket_order.status,
    ticket_order.expires_at
    into
      v_user,
      v_total,
      v_order_status,
      v_expires_at
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;

  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ticket_payment:' || p_idempotency_key, 0)
  );

  select payment.*
    into v_existing_payment
  from public.payments as payment
  where payment.idempotency_key = p_idempotency_key
  for update of payment;

  v_has_existing_payment := found;

  if v_has_existing_payment then
    if v_existing_payment.purpose <> 'ticket'
      or v_existing_payment.ref_id is distinct from p_ticket_order_id
      or v_existing_payment.user_id is distinct from v_user
      or v_existing_payment.amount is distinct from p_amount
      or v_existing_payment.payment_key is distinct from p_payment_key
    then
      raise unique_violation using message = 'idempotency conflict';
    end if;

    if v_existing_payment.status in ('paid', 'refunded') then
      return;
    end if;

    if v_existing_payment.status <> 'pending' then
      raise check_violation using message = 'payment not payable';
    end if;
  end if;

  if v_order_status <> 'pending' then
    raise check_violation using message = 'ticket order not payable';
  end if;

  if v_expires_at is not null and now() >= v_expires_at then
    raise check_violation using message = 'ticket order expired';
  end if;

  if p_amount is distinct from v_total then
    raise check_violation using message = 'amount mismatch';
  end if;

  if v_has_existing_payment then
    update public.payments
    set
      status = 'paid',
      raw = p_raw
    where id = v_existing_payment.id;
  else
    insert into public.payments (
      user_id,
      purpose,
      ref_id,
      amount,
      status,
      payment_key,
      idempotency_key,
      raw
    )
    values (
      v_user,
      'ticket',
      p_ticket_order_id,
      p_amount,
      'paid',
      p_payment_key,
      p_idempotency_key,
      p_raw
    );
  end if;

  update public.ticket_orders
  set
    status = 'paid',
    expires_at = null
  where id = p_ticket_order_id;

  update public.tickets
  set qr_token = encode(extensions.gen_random_bytes(16), 'hex')
  where ticket_order_id = p_ticket_order_id
    and qr_token is null;
end;
$$

-- Provider가 취소됐다고 fresh 조회한 정확한 paymentKey만 정합화한다. 같은 예매에
-- 다른 결제 시도가 남아 있으면 그 시도의 돈과 선점을 건드리지 않는다.
create function public.refund_ticket_order_with_provider_evidence(
  p_ticket_order_id uuid,
  p_reason text,
  p_provider_payment_key text
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_user_id uuid;
  v_order_status public.ticket_order_status;
  v_order_total bigint;
  v_payment_id uuid;
  v_payment_user_id uuid;
  v_payment_purpose public.payment_purpose;
  v_payment_ref_id uuid;
  v_payment_amount bigint;
  v_payment_status public.payment_status;
  v_payment_key text;
  v_current_was_paid boolean := false;
  v_has_other_active_payment boolean;
  v_has_paid_cancellation_evidence boolean;
  v_ticket record;
begin
  if p_provider_payment_key is null
    or nullif(btrim(p_provider_payment_key), '') is null
    or length(p_provider_payment_key) > 200
  then
    raise check_violation using message = 'invalid payment evidence';
  end if;

  select
    ticket_order.user_id,
    ticket_order.status,
    ticket_order.total
    into
      v_order_user_id,
      v_order_status,
      v_order_total
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;

  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;

  -- 결제 확정과 같은 order → payment 순서로 모든 시도를 결정적으로 잠근다.
  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket'
    and payment.ref_id = p_ticket_order_id
  order by payment.id
  for update of payment;

  select
    payment.id,
    payment.user_id,
    payment.purpose,
    payment.ref_id,
    payment.amount,
    payment.status,
    payment.payment_key
    into
      v_payment_id,
      v_payment_user_id,
      v_payment_purpose,
      v_payment_ref_id,
      v_payment_amount,
      v_payment_status,
      v_payment_key
  from public.payments as payment
  where payment.idempotency_key = p_provider_payment_key;

  if not found
    or v_payment_purpose is distinct from 'ticket'
    or v_payment_ref_id is distinct from p_ticket_order_id
    or v_payment_user_id is distinct from v_order_user_id
    or v_payment_amount is distinct from v_order_total
    or v_payment_key is distinct from p_provider_payment_key
  then
    raise check_violation using message = 'payment evidence mismatch';
  end if;

  -- Provider가 취소한 현재 키 하나만 먼저 terminal 장부로 수렴시킨다.
  if v_payment_status = 'paid' then
    v_current_was_paid := true;

    insert into public.refunds (payment_id, amount, reason, status)
    values (v_payment_id, v_payment_amount, p_reason, 'done')
    on conflict (payment_id) do update
    set
      amount = excluded.amount,
      reason = coalesce(public.refunds.reason, excluded.reason),
      status = 'done';

    update public.payments
    set status = 'refunded'
    where id = v_payment_id;
  elsif v_payment_status in ('pending', 'failed') then
    update public.payments
    set status = 'canceled'
    where id = v_payment_id;
  end if;

  -- 이미 닫힌 예매의 같은 provider 취소 replay는 sold를 다시 원복하지 않는다.
  if v_order_status = 'canceled' then
    return;
  end if;

  if v_order_status not in ('pending', 'paid') then
    raise check_violation using message = 'ticket order not cancelable';
  end if;

  select exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = p_ticket_order_id
      and payment.id <> v_payment_id
      and payment.status in ('pending', 'paid')
  ) into v_has_other_active_payment;

  -- 다른 live 결제는 이 취소 key의 증거가 아니므로 예매와 선점을 보존한다.
  if v_has_other_active_payment then
    return;
  end if;

  -- paid 예매는 이번 키가 실제 paid였거나, 앞선 호출이 paid 키를 정확히
  -- 환불 완료한 장부가 있어야만 마지막 선점을 해제할 수 있다.
  if v_order_status = 'paid' then
    select exists (
      select 1
      from public.payments as payment
      join public.refunds as refund on refund.payment_id = payment.id
      where payment.purpose = 'ticket'
        and payment.ref_id = p_ticket_order_id
        and payment.status = 'refunded'
        and refund.status = 'done'
    ) into v_has_paid_cancellation_evidence;

    if not v_current_was_paid and not v_has_paid_cancellation_evidence then
      raise check_violation using message = 'payment evidence required';
    end if;
  end if;

  -- 다른 결제 시도가 모두 terminal인 실제 종료 시점에만 사용 여부를 검사한다.
  if exists (
    select 1
    from public.tickets as ticket
    where ticket.ticket_order_id = p_ticket_order_id
      and ticket.status = 'used'
  ) then
    raise check_violation using message = 'used ticket cannot be refunded';
  end if;

  for v_ticket in
    select ticket.ticket_type_id, count(*)::integer as qty
    from public.tickets as ticket
    where ticket.ticket_order_id = p_ticket_order_id
    group by ticket.ticket_type_id
    order by ticket.ticket_type_id
  loop
    update public.ticket_types
    set sold = sold - v_ticket.qty
    where id = v_ticket.ticket_type_id;
  end loop;

  update public.tickets
  set status = 'refunded'
  where ticket_order_id = p_ticket_order_id;

  update public.ticket_orders
  set
    status = 'canceled',
    expires_at = null
  where id = p_ticket_order_id;
end;
$$

-- Cron/expiry는 provider active payment가 전혀 없는 pending 예매만 닫는 wrapper를 유지한다.
create or replace function public.refund_ticket_order(
  p_ticket_order_id uuid,
  p_reason text
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_status public.ticket_order_status;
  v_ticket record;
begin
  select ticket_order.status
    into v_order_status
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;

  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;

  if v_order_status = 'canceled' then
    return;
  end if;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket'
    and payment.ref_id = p_ticket_order_id
  order by payment.id
  for update of payment;

  if v_order_status <> 'pending' then
    raise check_violation using message = 'payment evidence required';
  end if;

  if exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = p_ticket_order_id
      and payment.status in ('pending', 'paid')
  ) then
    raise check_violation using message = 'provider cancellation required';
  end if;

  for v_ticket in
    select ticket.ticket_type_id, count(*)::integer as qty
    from public.tickets as ticket
    where ticket.ticket_order_id = p_ticket_order_id
    group by ticket.ticket_type_id
    order by ticket.ticket_type_id
  loop
    update public.ticket_types
    set sold = sold - v_ticket.qty
    where id = v_ticket.ticket_type_id;
  end loop;

  update public.tickets
  set status = 'refunded'
  where ticket_order_id = p_ticket_order_id;

  update public.ticket_orders
  set
    status = 'canceled',
    expires_at = null
  where id = p_ticket_order_id;
end;
$$

create trigger trg_ticket_cancellation_requests_updated
before update on public.ticket_cancellation_requests
for each row execute function public.set_updated_at()

-- 모든 취소 경로의 마지막 allocation 전이는 이 함수 한 곳에서만 수행한다.
-- 호출자가 이미 잠갔더라도 같은 order → request → payment → ticket → type 순서로
-- 다시 잠가 독립 호출에도 동일한 직렬화 계약을 유지한다.
create function public.finalize_ticket_cancellation_request(
  p_request_id uuid,
  p_actor_id uuid
)
returns text
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_id uuid;
  v_order_status public.ticket_order_status;
  v_request_status text;
  v_request_source text;
  v_refund_count integer;
begin
  select request.ticket_order_id
  into v_order_id
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'ticket cancellation request not found';
  end if;

  select ticket_order.status
  into v_order_status
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;

  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;

  select request.status, request.source
  into v_request_status, v_request_source
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id
  for update of request;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket'
    and payment.ref_id = v_order_id
  order by payment.id
  for update of payment;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order_id
  order by ticket.id
  for update of ticket;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id in (
    select ticket.ticket_type_id
    from public.tickets as ticket
    where ticket.ticket_order_id = v_order_id
  )
  order by ticket_type.id
  for update of ticket_type;

  if v_request_status = 'completed' then
    return 'completed';
  end if;

  if v_order_status = 'canceled' then
    update public.ticket_cancellation_requests
    set
      status = 'completed',
      attempt_token = null,
      completed_at = coalesce(completed_at, now()),
      last_error_code = null
    where id = p_request_id;
    return 'completed';
  end if;

  if v_order_status not in ('pending', 'paid') then
    raise check_violation using message = 'ticket order not cancelable';
  end if;

  if exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = v_order_id
      and payment.status in ('pending', 'paid')
  ) then
    return 'processing';
  end if;

  if v_order_status = 'paid' and not exists (
    select 1
    from public.payments as payment
    join public.refunds as refund on refund.payment_id = payment.id
    where payment.purpose = 'ticket'
      and payment.ref_id = v_order_id
      and payment.status = 'refunded'
      and refund.status = 'done'
  ) then
    raise check_violation using message = 'payment evidence required';
  end if;

  if exists (
    select 1
    from public.tickets as ticket
    where ticket.ticket_order_id = v_order_id
      and ticket.status = 'used'
  ) then
    update public.ticket_cancellation_requests
    set
      status = 'needs_review',
      attempt_token = null,
      last_error_code = 'used_ticket_after_provider_cancellation'
    where id = p_request_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      p_actor_id,
      'ticket.cancellation.needs_review',
      'ticket_order:' || v_order_id::text,
      jsonb_build_object(
        'requestId', p_request_id,
        'source', v_request_source,
        'to', 'needs_review',
        'errorCode', 'used_ticket_after_provider_cancellation'
      )
    );
    return 'needs_review';
  end if;

  update public.ticket_types as ticket_type
  set sold = ticket_type.sold - allocation.qty
  from (
    select ticket.ticket_type_id, count(*)::integer as qty
    from public.tickets as ticket
    where ticket.ticket_order_id = v_order_id
    group by ticket.ticket_type_id
  ) as allocation
  where ticket_type.id = allocation.ticket_type_id;

  update public.tickets
  set status = 'refunded'
  where ticket_order_id = v_order_id;

  update public.ticket_orders
  set
    status = 'canceled',
    expires_at = null
  where id = v_order_id;

  update public.ticket_cancellation_requests
  set
    status = 'completed',
    attempt_token = null,
    completed_at = coalesce(completed_at, now()),
    last_error_code = null
  where id = p_request_id;

  select count(*)::integer
  into v_refund_count
  from public.refunds as refund
  where refund.ticket_cancellation_request_id = p_request_id
    and refund.status = 'done';

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_actor_id,
    'ticket.cancellation.completed',
    'ticket_order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'source', v_request_source,
      'to', 'completed',
      'refundCount', v_refund_count
    )
  );

  return 'completed';
end;
$$

create function public.request_ticket_cancellation(
  p_user_id uuid,
  p_ticket_order_id uuid
)
returns table (request_id uuid, result text)
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_user_id uuid;
  v_order_status public.ticket_order_status;
  v_order_total bigint;
  v_event_id text;
  v_cutoff_at timestamptz;
  v_existing_request record;
begin
  select
    ticket_order.user_id,
    ticket_order.status,
    ticket_order.total,
    ticket_order.event_id
  into
    v_order_user_id,
    v_order_status,
    v_order_total,
    v_event_id
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;

  if not found or p_user_id is null or v_order_user_id is distinct from p_user_id then
    request_id := null;
    result := 'not_found';
    return next;
    return;
  end if;

  if v_order_status = 'canceled' then
    select request.id
    into request_id
    from public.ticket_cancellation_requests as request
    where request.ticket_order_id = p_ticket_order_id
      and request.status = 'completed'
    order by request.requested_at desc, request.id
    limit 1;

    result := case when request_id is null then 'already_canceled' else 'completed' end;
    return next;
    return;
  end if;

  if v_order_status not in ('pending', 'paid') then
    request_id := null;
    result := 'not_cancelable';
    return next;
    return;
  end if;

  select request.id, request.status
  into v_existing_request
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = p_ticket_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  limit 1
  for update of request;

  if found then
    request_id := v_existing_request.id;
    result := v_existing_request.status;
    return next;
    return;
  end if;

  select event_record.starts_at
  into v_cutoff_at
  from public.events as event_record
  where event_record.id = v_event_id
  for share of event_record;

  if v_cutoff_at is null or now() >= v_cutoff_at then
    request_id := null;
    result := 'policy_closed';
    return next;
    return;
  end if;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket'
    and payment.ref_id = p_ticket_order_id
  order by payment.id
  for update of payment;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = p_ticket_order_id
  order by ticket.id
  for update of ticket;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id in (
    select ticket.ticket_type_id
    from public.tickets as ticket
    where ticket.ticket_order_id = p_ticket_order_id
  )
  order by ticket_type.id
  for update of ticket_type;

  if not exists (
    select 1
    from public.tickets as ticket
    where ticket.ticket_order_id = p_ticket_order_id
  ) or exists (
    select 1
    from public.tickets as ticket
    where ticket.ticket_order_id = p_ticket_order_id
      and ticket.status <> 'valid'
  ) then
    request_id := null;
    result := 'not_cancelable';
    return next;
    return;
  end if;

  insert into public.ticket_cancellation_requests (
    ticket_order_id,
    requested_by,
    source,
    status,
    policy_code,
    cutoff_at,
    gross_amount,
    fee_amount,
    refund_amount,
    reason
  )
  values (
    p_ticket_order_id,
    p_user_id,
    'user',
    'requested',
    'event_start_full_refund_v1',
    v_cutoff_at,
    v_order_total,
    0,
    v_order_total,
    '사용자 예매 취소 요청'
  )
  returning id into request_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_user_id,
    'ticket.cancellation.requested',
    'ticket_order:' || p_ticket_order_id::text,
    jsonb_build_object(
      'requestId', request_id,
      'source', 'user',
      'policyCode', 'event_start_full_refund_v1',
      'to', 'requested'
    )
  );

  if v_order_status = 'pending' and not exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = p_ticket_order_id
  ) then
    result := public.finalize_ticket_cancellation_request(request_id, p_user_id);
  else
    result := 'requested';
  end if;

  return next;
end;
$$

create function public.begin_ticket_cancellation_reconcile(
  p_request_id uuid,
  p_user_id uuid,
  p_attempt_token uuid
)
returns text
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_id uuid;
  v_requested_by uuid;
  v_status text;
  v_attempt_token uuid;
  v_provider_started_at timestamptz;
begin
  if p_attempt_token is null then
    raise not_null_violation using message = 'attempt token required';
  end if;

  select request.ticket_order_id, request.requested_by
  into v_order_id, v_requested_by
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null or p_user_id is null or v_requested_by is distinct from p_user_id then
    raise no_data_found using message = 'ticket cancellation request not found';
  end if;

  perform ticket_order.id
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;

  select request.status, request.attempt_token, request.provider_started_at
  into v_status, v_attempt_token, v_provider_started_at
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id
  for update of request;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket'
    and payment.ref_id = v_order_id
  order by payment.id
  for update of payment;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order_id
  order by ticket.id
  for update of ticket;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id in (
    select ticket.ticket_type_id
    from public.tickets as ticket
    where ticket.ticket_order_id = v_order_id
  )
  order by ticket_type.id
  for update of ticket_type;

  if v_status = 'completed' then
    return 'completed';
  end if;

  if v_status = 'processing' then
    if v_attempt_token = p_attempt_token then
      return 'processing';
    end if;

    if v_attempt_token is not null
      and v_provider_started_at is not null
      and v_provider_started_at > now() - interval '5 minutes'
    then
      return 'in_progress';
    end if;

    update public.ticket_cancellation_requests
    set
      attempt_token = p_attempt_token,
      provider_started_at = now(),
      last_error_code = null
    where id = p_request_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      p_user_id,
      'ticket.cancellation.processing_reclaimed',
      'ticket_order:' || v_order_id::text,
      jsonb_build_object(
        'requestId', p_request_id,
        'from', 'processing',
        'to', 'processing'
      )
    );

    return 'processing';
  end if;

  if v_status not in ('requested', 'needs_review') then
    raise check_violation using message = 'ticket cancellation not reconcilable';
  end if;

  update public.ticket_cancellation_requests
  set
    status = 'processing',
    attempt_token = p_attempt_token,
    provider_started_at = now(),
    last_error_code = null
  where id = p_request_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_user_id,
    'ticket.cancellation.processing',
    'ticket_order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'from', v_status,
      'to', 'processing'
    )
  );

  return 'processing';
end;
$$

create function public.mark_ticket_cancellation_needs_review(
  p_request_id uuid,
  p_attempt_token uuid,
  p_error_code text
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_id uuid;
  v_requested_by uuid;
  v_status text;
  v_current_attempt_token uuid;
begin
  if p_error_code is null or p_error_code !~ '^[a-z0-9_]{1,64}$' then
    raise check_violation using message = 'invalid review code';
  end if;

  select request.ticket_order_id, request.requested_by
  into v_order_id, v_requested_by
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'ticket cancellation request not found';
  end if;

  perform ticket_order.id
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;

  select request.status, request.attempt_token
  into v_status, v_current_attempt_token
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id
  for update of request;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket'
    and payment.ref_id = v_order_id
  order by payment.id
  for update of payment;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order_id
  order by ticket.id
  for update of ticket;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id in (
    select ticket.ticket_type_id
    from public.tickets as ticket
    where ticket.ticket_order_id = v_order_id
  )
  order by ticket_type.id
  for update of ticket_type;

  if v_status in ('completed', 'needs_review') then
    return;
  end if;

  if v_status <> 'processing' then
    raise check_violation using message = 'ticket cancellation not processing';
  end if;

  if p_attempt_token is null or v_current_attempt_token is distinct from p_attempt_token then
    raise check_violation using message = 'ticket cancellation attempt mismatch';
  end if;

  update public.ticket_cancellation_requests
  set
    status = 'needs_review',
    attempt_token = null,
    last_error_code = p_error_code
  where id = p_request_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_requested_by,
    'ticket.cancellation.needs_review',
    'ticket_order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'from', 'processing',
      'to', 'needs_review',
      'errorCode', p_error_code
    )
  );
end;
$$

create function public.complete_ticket_cancellation_request(
  p_request_id uuid,
  p_attempt_token uuid,
  p_provider_payment_keys text[]
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_id uuid;
  v_order_user_id uuid;
  v_reason text;
  v_status text;
  v_current_attempt_token uuid;
  v_provider_payment_keys text[];
  v_key text;
begin
  select request.ticket_order_id, request.requested_by, request.reason
  into v_order_id, v_order_user_id, v_reason
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'ticket cancellation request not found';
  end if;

  perform ticket_order.id
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;

  select request.status, request.attempt_token
  into v_status, v_current_attempt_token
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id
  for update of request;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket'
    and payment.ref_id = v_order_id
  order by payment.id
  for update of payment;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order_id
  order by ticket.id
  for update of ticket;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id in (
    select ticket.ticket_type_id
    from public.tickets as ticket
    where ticket.ticket_order_id = v_order_id
  )
  order by ticket_type.id
  for update of ticket_type;

  if v_status = 'completed' then
    return;
  end if;

  if v_status <> 'processing' then
    raise check_violation using message = 'ticket cancellation not processing';
  end if;

  if p_attempt_token is null or v_current_attempt_token is distinct from p_attempt_token then
    raise check_violation using message = 'ticket cancellation attempt mismatch';
  end if;

  select coalesce(array_agg(keys.payment_key order by keys.payment_key), array[]::text[])
  into v_provider_payment_keys
  from (
    select distinct btrim(input.payment_key) as payment_key
    from unnest(coalesce(p_provider_payment_keys, array[]::text[])) as input(payment_key)
    where input.payment_key is not null
      and btrim(input.payment_key) <> ''
  ) as keys;

  if exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = v_order_id
      and payment.status <> 'failed'
      and (
        payment.payment_key is null
        or not (payment.payment_key = any(v_provider_payment_keys))
      )
  ) or exists (
    select 1
    from unnest(v_provider_payment_keys) as input(payment_key)
    where not exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'ticket'
        and payment.ref_id = v_order_id
        and payment.user_id = v_order_user_id
        and payment.payment_key = input.payment_key
        and payment.idempotency_key = input.payment_key
    )
  ) then
    raise check_violation using message = 'provider cancellation required';
  end if;

  foreach v_key in array v_provider_payment_keys
  loop
    perform public.record_ticket_provider_cancellation_evidence(
      v_order_id,
      v_reason,
      v_key
    );
  end loop;

  perform public.finalize_ticket_cancellation_request(p_request_id, v_order_user_id);
end;
$$

-- provider 승인 API를 호출하기 전에 pending payment placeholder를 먼저 선점한다.
-- 사용자 취소와 같은 order → request → payment 순서로 잠가 둘 중 하나만 먼저
-- 외부 부작용을 시작할 수 있게 한다.
create function public.begin_ticket_payment_approval(
  p_user_id uuid,
  p_ticket_order_id uuid,
  p_payment_key text,
  p_amount bigint
)
returns text
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_user_id uuid;
  v_order_total bigint;
  v_order_status public.ticket_order_status;
  v_expires_at timestamptz;
  v_matching_payment_count integer;
  v_existing_payment public.payments%rowtype;
  v_has_existing_payment boolean := false;
begin
  if p_payment_key is null
    or nullif(btrim(p_payment_key), '') is null
    or btrim(p_payment_key) <> p_payment_key
    or length(p_payment_key) > 200
    or p_amount is null
    or p_amount <= 0
  then
    raise check_violation using message = 'invalid payment approval evidence';
  end if;

  select
    ticket_order.user_id,
    ticket_order.total,
    ticket_order.status,
    ticket_order.expires_at
  into
    v_order_user_id,
    v_order_total,
    v_order_status,
    v_expires_at
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;

  if not found or p_user_id is null or v_order_user_id is distinct from p_user_id then
    raise no_data_found using message = 'ticket order not found';
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = p_ticket_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;

  if found then
    raise check_violation using message = 'ticket cancellation in progress';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ticket_payment:' || p_payment_key, 0)
  );

  perform payment.id
  from public.payments as payment
  where (
      payment.purpose = 'ticket'
      and payment.ref_id = p_ticket_order_id
    )
    or payment.idempotency_key = p_payment_key
    or payment.payment_key = p_payment_key
  order by payment.id
  for update of payment;

  select count(*)::integer
  into v_matching_payment_count
  from public.payments as payment
  where payment.idempotency_key = p_payment_key
     or payment.payment_key = p_payment_key;

  if v_matching_payment_count > 1 then
    raise unique_violation using message = 'payment approval conflict';
  end if;

  select payment.*
  into v_existing_payment
  from public.payments as payment
  where payment.idempotency_key = p_payment_key
     or payment.payment_key = p_payment_key;

  v_has_existing_payment := found;

  if p_amount is distinct from v_order_total then
    raise check_violation using message = 'amount mismatch';
  end if;

  if v_has_existing_payment then
    if v_existing_payment.purpose <> 'ticket'
      or v_existing_payment.ref_id is distinct from p_ticket_order_id
      or v_existing_payment.user_id is distinct from p_user_id
      or v_existing_payment.amount is distinct from p_amount
      or v_existing_payment.idempotency_key is distinct from p_payment_key
      or (
        v_existing_payment.payment_key is not null
        and v_existing_payment.payment_key is distinct from p_payment_key
      )
    then
      raise unique_violation using message = 'payment approval conflict';
    end if;
  end if;

  if exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = p_ticket_order_id
      and payment.status in ('pending', 'paid', 'refunded')
      and payment.id is distinct from v_existing_payment.id
  ) then
    raise unique_violation using message = 'payment approval conflict';
  end if;

  if v_has_existing_payment then
    if v_existing_payment.status = 'paid' then
      if v_order_status <> 'paid' then
        raise unique_violation using message = 'payment approval conflict';
      end if;
      return 'already_confirmed';
    end if;

    if v_existing_payment.status = 'refunded' then
      if v_order_status <> 'canceled' then
        raise unique_violation using message = 'payment approval conflict';
      end if;
      return 'already_confirmed';
    end if;

    if v_existing_payment.status <> 'pending' then
      raise check_violation using message = 'payment not payable';
    end if;
  end if;

  if v_order_status <> 'pending' then
    raise check_violation using message = 'ticket order not payable';
  end if;

  if v_expires_at is not null and now() >= v_expires_at then
    raise check_violation using message = 'ticket order expired';
  end if;

  if v_has_existing_payment then
    update public.payments
    set payment_key = p_payment_key
    where id = v_existing_payment.id;
  else
    insert into public.payments (
      user_id,
      purpose,
      ref_id,
      amount,
      status,
      payment_key,
      idempotency_key,
      raw
    )
    values (
      p_user_id,
      'ticket',
      p_ticket_order_id,
      p_amount,
      'pending',
      p_payment_key,
      p_payment_key,
      null
    );
  end if;

  return 'pending';
end;
$$

-- 결제 확정도 취소와 같은 order → request → payment 순서로 잠근다. active
-- 취소 요청이 먼저면 승인 replay를 포함한 모든 결제 확정을 fail closed한다.
create or replace function public.confirm_ticket_payment(
  p_idempotency_key text,
  p_ticket_order_id uuid,
  p_payment_key text,
  p_amount bigint,
  p_raw jsonb
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid;
  v_total bigint;
  v_order_status public.ticket_order_status;
  v_expires_at timestamptz;
  v_existing_payment public.payments%rowtype;
  v_has_existing_payment boolean := false;
begin
  if p_idempotency_key is null
    or nullif(btrim(p_idempotency_key), '') is null
    or length(p_idempotency_key) > 200
    or p_payment_key is null
    or nullif(btrim(p_payment_key), '') is null
    or length(p_payment_key) > 200
  then
    raise check_violation using message = 'invalid payment evidence';
  end if;

  if p_idempotency_key is distinct from p_payment_key then
    raise unique_violation using message = 'idempotency conflict';
  end if;

  select
    ticket_order.user_id,
    ticket_order.total,
    ticket_order.status,
    ticket_order.expires_at
  into
    v_user,
    v_total,
    v_order_status,
    v_expires_at
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;

  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = p_ticket_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;

  if found then
    raise check_violation using message = 'ticket cancellation in progress';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ticket_payment:' || p_idempotency_key, 0)
  );

  select payment.*
  into v_existing_payment
  from public.payments as payment
  where payment.idempotency_key = p_idempotency_key
  for update of payment;

  v_has_existing_payment := found;

  if v_has_existing_payment then
    if v_existing_payment.purpose <> 'ticket'
      or v_existing_payment.ref_id is distinct from p_ticket_order_id
      or v_existing_payment.user_id is distinct from v_user
      or v_existing_payment.amount is distinct from p_amount
      or v_existing_payment.payment_key is distinct from p_payment_key
    then
      raise unique_violation using message = 'idempotency conflict';
    end if;

    if v_existing_payment.status in ('paid', 'refunded') then
      return;
    end if;

    if v_existing_payment.status <> 'pending' then
      raise check_violation using message = 'payment not payable';
    end if;
  end if;

  if v_order_status <> 'pending' then
    raise check_violation using message = 'ticket order not payable';
  end if;

  if v_expires_at is not null and now() >= v_expires_at then
    raise check_violation using message = 'ticket order expired';
  end if;

  if p_amount is distinct from v_total then
    raise check_violation using message = 'amount mismatch';
  end if;

  if v_has_existing_payment then
    update public.payments
    set
      status = 'paid',
      raw = p_raw
    where id = v_existing_payment.id;
  else
    insert into public.payments (
      user_id,
      purpose,
      ref_id,
      amount,
      status,
      payment_key,
      idempotency_key,
      raw
    )
    values (
      v_user,
      'ticket',
      p_ticket_order_id,
      p_amount,
      'paid',
      p_payment_key,
      p_idempotency_key,
      p_raw
    );
  end if;

  update public.ticket_orders
  set
    status = 'paid',
    expires_at = null
  where id = p_ticket_order_id;

  update public.tickets
  set qr_token = encode(extensions.gen_random_bytes(16), 'hex')
  where ticket_order_id = p_ticket_order_id
    and qr_token is null;
end;
$$

-- 검표는 QR로 order를 찾는 비잠금 lookup 뒤 order → request → ticket 순서로
-- 직렬화한다. 어느 쪽이 먼저 잠겨도 사용과 환불이 동시에 성공할 수 없다.
create or replace function public.check_in_ticket(p_qr_token text)
returns public.ticket_status
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_id uuid;
  v_ticket_id uuid;
  v_status public.ticket_status;
begin
  if not public.is_staff() then
    raise insufficient_privilege using message = 'forbidden';
  end if;

  select ticket.ticket_order_id
  into v_order_id
  from public.tickets as ticket
  where ticket.qr_token = p_qr_token;

  if not found then
    raise no_data_found using message = 'invalid ticket';
  end if;

  perform ticket_order.id
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = v_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;

  if found then
    raise check_violation using message = 'ticket cancellation in progress';
  end if;

  select ticket.id, ticket.status
  into v_ticket_id, v_status
  from public.tickets as ticket
  where ticket.qr_token = p_qr_token
    and ticket.ticket_order_id = v_order_id
  for update of ticket;

  if not found then
    raise no_data_found using message = 'invalid ticket';
  end if;

  if v_status <> 'valid' then
    return v_status;
  end if;

  update public.tickets
  set status = 'used'
  where id = v_ticket_id;

  insert into public.check_ins (ticket_id, by_staff)
  values (v_ticket_id, (select auth.uid()))
  on conflict (ticket_id) do nothing;

  return 'used'::public.ticket_status;
end;
$$

create function public.check_in_ticket(
  p_staff_id uuid,
  p_qr_token text
)
returns table (
  result text,
  checked_at timestamptz,
  event_id text,
  event_title text,
  ticket_type_id uuid,
  ticket_type_name text
)
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_id uuid;
  v_order_status public.ticket_order_status;
  v_ticket_id uuid;
  v_ticket_status public.ticket_status;
  v_ticket_type_id uuid;
  v_event_id text;
  v_event_title text;
  v_ticket_type_name text;
  v_checked_at timestamptz;
begin
  if p_staff_id is null or not exists (
    select 1
    from public.profiles as profile
    where profile.id = p_staff_id
      and profile.role in ('staff', 'admin')
  ) then
    raise insufficient_privilege using message = 'staff access required';
  end if;

  if p_qr_token is null or p_qr_token !~ '^[0-9a-f]{32}$' then
    raise check_violation using message = 'invalid qr token';
  end if;

  -- QR lookup 자체는 잠그지 않는다. order 잠금이 검표·취소의 직렬화 기준이다.
  select ticket.id, ticket.ticket_order_id
  into v_ticket_id, v_order_id
  from public.tickets as ticket
  where ticket.qr_token = p_qr_token;

  if not found then
    return query
    select
      'not_found'::text,
      null::timestamptz,
      null::text,
      null::text,
      null::uuid,
      null::text;
    return;
  end if;

  select ticket_order.status
  into v_order_status
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;

  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = v_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;

  if found then
    raise check_violation using message = 'ticket cancellation in progress';
  end if;

  select
    ticket.status,
    ticket.ticket_type_id,
    ticket_type.event_id,
    event.title,
    ticket_type.name
  into
    v_ticket_status,
    v_ticket_type_id,
    v_event_id,
    v_event_title,
    v_ticket_type_name
  from public.tickets as ticket
  join public.ticket_types as ticket_type on ticket_type.id = ticket.ticket_type_id
  join public.events as event on event.id = ticket_type.event_id
  where ticket.id = v_ticket_id
    and ticket.ticket_order_id = v_order_id
    and ticket.qr_token = p_qr_token
  for update of ticket;

  if not found then
    raise check_violation using message = 'ticket changed during check-in';
  end if;

  if v_ticket_status = 'valid' then
    if v_order_status <> 'paid' then
      raise check_violation using message = 'ticket order not paid';
    end if;

    v_checked_at := clock_timestamp();

    update public.tickets
    set status = 'used'
    where id = v_ticket_id;

    insert into public.check_ins (ticket_id, checked_at, by_staff)
    values (v_ticket_id, v_checked_at, p_staff_id);

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      p_staff_id,
      'admin.ticket.checked_in',
      format('tickets:%s', v_ticket_id),
      jsonb_build_object(
        'before', jsonb_build_object('status', 'valid'),
        'after', jsonb_build_object('status', 'used')
      )
    );

    return query
    select
      'checked_in'::text,
      v_checked_at,
      v_event_id,
      v_event_title,
      v_ticket_type_id,
      v_ticket_type_name;
    return;
  end if;

  if v_ticket_status = 'used' then
    select check_in.checked_at
    into v_checked_at
    from public.check_ins as check_in
    where check_in.ticket_id = v_ticket_id;

    if not found then
      raise check_violation using message = 'used ticket check-in ledger missing';
    end if;

    return query
    select
      'already_used'::text,
      v_checked_at,
      v_event_id,
      v_event_title,
      v_ticket_type_id,
      v_ticket_type_name;
    return;
  end if;

  if v_ticket_status = 'refunded' then
    return query
    select
      'refunded'::text,
      null::timestamptz,
      v_event_id,
      v_event_title,
      v_ticket_type_id,
      v_ticket_type_name;
    return;
  end if;

  raise check_violation using message = 'unsupported ticket status';
end;
$$

create or replace function public.admin_upsert_card_pool(
  target_operation_id uuid,
  target_pool_id uuid,
  target_ip_id text,
  target_name text,
  target_active_from timestamptz,
  target_active_to timestamptz
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_ip_id text := btrim(target_ip_id, E' \t\n\r\f\v');
  normalized_name text := btrim(target_name, E' \t\n\r\f\v');
  request_payload jsonb;
  previous_pool public.card_pools%rowtype;
  previous_payload jsonb := null;
  after_payload jsonb;
  pool_exists boolean := false;
  has_dependency boolean := false;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if target_pool_id is null then
    raise exception 'invalid_pool_id' using errcode = '22004';
  end if;

  if normalized_ip_id is null or normalized_ip_id = '' then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  if normalized_name is null or normalized_name = '' then
    raise exception 'invalid_pool_name' using errcode = '22023';
  end if;

  if target_active_from is null then
    raise exception 'invalid_active_from' using errcode = '22004';
  end if;

  if target_active_to is not null and target_active_to <= target_active_from then
    raise exception 'invalid_pool_active_window' using errcode = '23514';
  end if;

  request_payload := jsonb_build_object(
    'ip_id', normalized_ip_id,
    'name', normalized_name,
    'active_from', target_active_from,
    'active_to', target_active_to
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_card_pool_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.card_pool.upserted'
      and existing_target = 'card_pools:' || target_pool_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_pool_id;
    end if;

    raise exception 'operation_conflict' using errcode = '23505';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_card_pool:' || target_pool_id::text, 0)
  );

  perform 1
  from public.ips
  where id = normalized_ip_id
  for key share;

  if not found then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  select pool.*
    into previous_pool
  from public.card_pools as pool
  where pool.id = target_pool_id
  for update;

  pool_exists := found;

  if pool_exists then
    previous_payload := jsonb_build_object(
      'id', previous_pool.id,
      'ip_id', previous_pool.ip_id,
      'name', previous_pool.name,
      'active_from', previous_pool.active_from,
      'active_to', previous_pool.active_to
    );

    if previous_pool.ip_id is distinct from normalized_ip_id then
      select exists (
        select 1 from public.cards where pool_id = target_pool_id
        union all
        select 1 from public.reward_policies where pool_id = target_pool_id
        union all
        select 1 from public.games where reward_pool_id = target_pool_id
        union all
        select 1 from public.draw_tickets where pool_id = target_pool_id
        union all
        select 1 from public.card_grants where pool_id = target_pool_id
      ) into has_dependency;

      if has_dependency then
        raise exception 'pool_ip_locked' using errcode = '23514';
      end if;
    end if;

    update public.card_pools
    set ip_id = normalized_ip_id,
        name = normalized_name,
        active_from = target_active_from,
        active_to = target_active_to
    where id = target_pool_id;
  else
    insert into public.card_pools (id, ip_id, name, active_from, active_to)
    values (
      target_pool_id,
      normalized_ip_id,
      normalized_name,
      target_active_from,
      target_active_to
    );
  end if;

  after_payload := jsonb_build_object(
    'id', target_pool_id,
    'ip_id', normalized_ip_id,
    'name', normalized_name,
    'active_from', target_active_from,
    'active_to', target_active_to
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.card_pool.upserted',
    'card_pools:' || target_pool_id::text,
    jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_pool_id;
end;
$$

create or replace function public.admin_set_pool_odds(
  target_operation_id uuid,
  target_pool_id uuid,
  target_n numeric,
  target_r numeric,
  target_sr numeric,
  target_ssr numeric,
  target_holo numeric
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  request_payload jsonb;
  previous_payload jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if target_pool_id is null then
    raise exception 'invalid_pool_id' using errcode = '22004';
  end if;

  if target_n is null or target_r is null or target_sr is null
    or target_ssr is null or target_holo is null
    or target_n < 0 or target_n > 1
    or target_r < 0 or target_r > 1
    or target_sr < 0 or target_sr > 1
    or target_ssr < 0 or target_ssr > 1
    or target_holo < 0 or target_holo > 1
  then
    raise exception 'invalid_pool_probability' using errcode = '22023';
  end if;

  if target_n <> round(target_n, 5)
    or target_r <> round(target_r, 5)
    or target_sr <> round(target_sr, 5)
    or target_ssr <> round(target_ssr, 5)
    or target_holo <> round(target_holo, 5)
  then
    raise exception 'invalid_probability_precision' using errcode = '22023';
  end if;

  if target_n + target_r + target_sr + target_ssr + target_holo <> 1 then
    raise exception 'pool_odds_must_sum_to_one' using errcode = '23514';
  end if;

  request_payload := jsonb_build_object(
    'N', target_n,
    'R', target_r,
    'SR', target_sr,
    'SSR', target_ssr,
    'HOLO', target_holo
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_pool_odds_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.card_pool.odds_set'
      and existing_target = 'card_pools:' || target_pool_id::text
      and existing_diff -> 'request' = request_payload
    then
      return;
    end if;

    raise exception 'operation_conflict' using errcode = '23505';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_card_pool:' || target_pool_id::text, 0)
  );

  perform 1
  from public.card_pools
  where id = target_pool_id
  for update;

  if not found then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from (values
      ('N'::public.rarity, target_n),
      ('R'::public.rarity, target_r),
      ('SR'::public.rarity, target_sr),
      ('SSR'::public.rarity, target_ssr),
      ('HOLO'::public.rarity, target_holo)
    ) as requested(rarity, probability)
    where requested.probability > 0
      and not exists (
        select 1
        from public.cards as card
        where card.pool_id = target_pool_id
          and card.rarity = requested.rarity
      )
  ) then
    raise exception 'pool_rarity_uncovered' using errcode = '23514';
  end if;

  select jsonb_build_object(
    'N', coalesce(max(probability) filter (where rarity = 'N'), 0),
    'R', coalesce(max(probability) filter (where rarity = 'R'), 0),
    'SR', coalesce(max(probability) filter (where rarity = 'SR'), 0),
    'SSR', coalesce(max(probability) filter (where rarity = 'SSR'), 0),
    'HOLO', coalesce(max(probability) filter (where rarity = 'HOLO'), 0)
  )
    into previous_payload
  from public.pool_odds
  where pool_id = target_pool_id;

  delete from public.pool_odds
  where pool_id = target_pool_id;

  insert into public.pool_odds (pool_id, rarity, probability)
  values
    (target_pool_id, 'N', target_n),
    (target_pool_id, 'R', target_r),
    (target_pool_id, 'SR', target_sr),
    (target_pool_id, 'SSR', target_ssr),
    (target_pool_id, 'HOLO', target_holo);

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.card_pool.odds_set',
    'card_pools:' || target_pool_id::text,
    jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', request_payload
    )
  );
end;
$$

create function public.admin_upsert_card(
  target_id text,
  target_ip_id text,
  target_name text,
  target_no text,
  target_rarity rarity,
  target_bg text,
  target_image_path text,
  target_pool_id uuid default null,
  target_pool_binding_provided boolean default false
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_id text := btrim(target_id, E' \t\n\r\f\v');
  normalized_ip_id text := btrim(target_ip_id, E' \t\n\r\f\v');
  normalized_name text := btrim(target_name, E' \t\n\r\f\v');
  previous_card public.cards%rowtype;
  previous_payload jsonb := null;
  after_payload jsonb;
  request_payload jsonb;
  card_exists boolean := false;
  effective_pool_id uuid;
  target_pool_ip_id text;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if normalized_id is null or normalized_id = '' then
    raise exception 'invalid_card_id' using errcode = '22023';
  end if;

  if normalized_ip_id is null or normalized_ip_id = '' then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  if normalized_name is null or normalized_name = '' then
    raise exception 'invalid_card_name' using errcode = '22023';
  end if;

  if target_rarity is null then
    raise exception 'invalid_card_rarity' using errcode = '22004';
  end if;

  if target_pool_binding_provided is null
    or (not target_pool_binding_provided and target_pool_id is not null)
  then
    raise exception 'invalid_pool_binding_mode' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_card:' || normalized_id, 0)
  );

  select card.*
    into previous_card
  from public.cards as card
  where card.id = normalized_id
  for update;

  card_exists := found;

  if target_pool_binding_provided then
    effective_pool_id := target_pool_id;
  elsif card_exists then
    effective_pool_id := previous_card.pool_id;
  else
    effective_pool_id := null;
  end if;

  perform pool.id
  from public.card_pools as pool
  where pool.id = previous_card.pool_id
     or pool.id = effective_pool_id
  order by pool.id
  for update;

  perform 1
  from public.ips
  where id = normalized_ip_id
  for key share;

  if not found then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  if card_exists then
    previous_payload := jsonb_build_object(
      'id', previous_card.id,
      'ip_id', previous_card.ip_id,
      'name', previous_card.name,
      'no', previous_card.no,
      'rarity', previous_card.rarity,
      'bg', previous_card.bg,
      'image_path', previous_card.image_path,
      'pool_id', previous_card.pool_id
    );

    if previous_card.pool_id is not null
      and (
        previous_card.ip_id is distinct from normalized_ip_id
        or previous_card.rarity is distinct from target_rarity
      )
    then
      raise exception 'pooled_card_catalog_contract_locked' using errcode = '23514';
    end if;
  end if;

  if effective_pool_id is not null then
    select pool.ip_id
      into target_pool_ip_id
    from public.card_pools as pool
    where pool.id = effective_pool_id;

    if not found then
      raise exception 'pool_not_found' using errcode = 'P0002';
    end if;

    if target_pool_ip_id is distinct from normalized_ip_id then
      raise exception 'card_pool_ip_mismatch' using errcode = '23514';
    end if;
  end if;

  if card_exists
    and previous_card.pool_id is not null
    and previous_card.pool_id is distinct from effective_pool_id
    and exists (
      select 1
      from public.pool_odds
      where pool_id = previous_card.pool_id
        and rarity = previous_card.rarity
        and probability > 0
    )
    and not exists (
      select 1
      from public.cards as other_card
      where other_card.pool_id = previous_card.pool_id
        and other_card.rarity = previous_card.rarity
        and other_card.id <> previous_card.id
    )
  then
    raise exception 'pool_rarity_uncovered' using errcode = '23514';
  end if;

  request_payload := jsonb_build_object(
    'id', normalized_id,
    'ip_id', normalized_ip_id,
    'name', normalized_name,
    'no', target_no,
    'rarity', target_rarity,
    'bg', target_bg,
    'image_path', target_image_path,
    'pool_id', effective_pool_id,
    'pool_binding_provided', target_pool_binding_provided
  );

  insert into public.cards (
    id,
    ip_id,
    name,
    no,
    rarity,
    bg,
    image_path,
    pool_id
  )
  values (
    normalized_id,
    normalized_ip_id,
    normalized_name,
    target_no,
    target_rarity,
    target_bg,
    target_image_path,
    effective_pool_id
  )
  on conflict (id) do update set
    ip_id = excluded.ip_id,
    name = excluded.name,
    no = excluded.no,
    rarity = excluded.rarity,
    bg = excluded.bg,
    image_path = excluded.image_path,
    pool_id = excluded.pool_id;

  update public.ips
  set cards_count = (
      select count(*)::integer from public.cards where cards.ip_id = ips.id
    ),
    updated_at = now()
  where id in (normalized_ip_id, previous_card.ip_id);

  after_payload := jsonb_build_object(
    'id', normalized_id,
    'ip_id', normalized_ip_id,
    'name', normalized_name,
    'no', target_no,
    'rarity', target_rarity,
    'bg', target_bg,
    'image_path', target_image_path,
    'pool_id', effective_pool_id
  );

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'catalog.card.upsert',
    'cards:' || normalized_id,
    jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );
end;
$$

-- Hold a shared lock on the pool while reading its current odds and cards. All
-- admin pool/odds/card mutations take the conflicting exclusive row lock.
create or replace function public.grant_cards(
  p_user_id uuid,
  p_pool_id uuid,
  p_source text,
  p_source_id uuid,
  p_idempotency_key text,
  p_count integer default 1
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_existing jsonb;
  v_cards jsonb := '[]'::jsonb;
  v_rarity rarity;
  v_card text;
  v_new boolean;
begin
  if p_count < 1 or p_count > 100 then
    raise exception 'invalid count';
  end if;

  perform 1
  from public.card_pools
  where id = p_pool_id
  for share;

  if not found then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  select granted_cards
    into v_existing
  from public.card_grants
  where idempotency_key = p_idempotency_key;

  if v_existing is not null then
    return v_existing;
  end if;

  for i in 1..p_count loop
    v_rarity := public.roll_rarity(p_pool_id);

    select card.id
      into v_card
    from public.cards as card
    where card.pool_id = p_pool_id
      and card.rarity = v_rarity
    order by random()
    limit 1;

    if v_card is null then
      raise exception 'pool has no card of rarity %', v_rarity;
    end if;

    v_new := not exists (
      select 1
      from public.user_cards
      where user_id = p_user_id
        and card_id = v_card
    );

    insert into public.user_cards as user_card (user_id, card_id, qty)
    values (p_user_id, v_card, 1)
    on conflict on constraint user_cards_pkey
    do update set qty = user_card.qty + 1;

    v_cards := v_cards || jsonb_build_object(
      'cardId', v_card,
      'rarity', v_rarity,
      'isNew', v_new
    );
  end loop;

  insert into public.card_grants (
    user_id,
    pool_id,
    source,
    source_id,
    granted_cards,
    idempotency_key
  )
  values (
    p_user_id,
    p_pool_id,
    p_source,
    p_source_id,
    v_cards,
    p_idempotency_key
  );

  return v_cards;
end;
$$

-- New game grants require both their own operating window and the reward pool's
-- current operating window. A completed daily slot remains replayable after a
-- later pool end; otherwise the pool is locked before any grant ledger write.
create or replace function public.play_game(p_game_id text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := (select auth.uid());
  v_game record;
  v_pool record;
  v_today date;
  v_count integer;
  v_last jsonb;
  v_play uuid;
  v_idem text;
  v_seed text;
  v_cards jsonb;
  v_result jsonb;
begin
  if v_user is null then
    raise exception 'auth required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'play_game:' || v_user::text || ':' || p_game_id,
      0
    )
  );

  select game.id,
         game.reward_pool_id,
         game.per_user_daily_limit,
         game.active_from,
         game.active_to
    into v_game
  from public.games as game
  where game.id = p_game_id
  for share;

  if v_game.id is null then
    raise exception 'game not found';
  end if;

  if now() < v_game.active_from
    or (v_game.active_to is not null and now() >= v_game.active_to)
  then
    raise exception 'game not active';
  end if;

  if v_game.reward_pool_id is null then
    raise exception 'game has no reward pool';
  end if;

  v_today := (now() at time zone 'Asia/Seoul')::date;

  select count(*)
    into v_count
  from public.game_plays
  where game_id = p_game_id
    and user_id = v_user
    and (created_at at time zone 'Asia/Seoul')::date = v_today;

  if v_count >= v_game.per_user_daily_limit then
    select result
      into v_last
    from public.game_plays
    where idempotency_key = 'game_play:' || p_game_id || ':' || v_user::text || ':'
      || to_char(v_today, 'YYYY-MM-DD') || ':' || v_count;

    if v_last is null then
      raise exception 'daily limit state corrupted';
    end if;

    return v_last;
  end if;

  select pool.id, pool.active_from, pool.active_to
    into v_pool
  from public.card_pools as pool
  where pool.id = v_game.reward_pool_id
  for share;

  if v_pool.id is null
    or now() < v_pool.active_from
    or (v_pool.active_to is not null and now() >= v_pool.active_to)
  then
    raise exception 'reward_pool_not_active' using errcode = '55000';
  end if;

  v_play := extensions.gen_random_uuid();
  v_idem := 'game_play:' || p_game_id || ':' || v_user::text || ':'
    || to_char(v_today, 'YYYY-MM-DD') || ':' || (v_count + 1);
  v_seed := encode(extensions.gen_random_bytes(16), 'hex');

  v_cards := public.grant_cards(
    v_user,
    v_game.reward_pool_id,
    'game_play',
    v_play,
    v_idem,
    1
  );

  v_result := jsonb_build_object(
    'playId', v_play,
    'rewards', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object('kind', 'card') || reward.elem
          order by reward.ordinality
        ),
        '[]'::jsonb
      )
      from jsonb_array_elements(v_cards) with ordinality as reward(elem, ordinality)
    ),
    'animationSeed', v_seed
  );

  insert into public.game_plays (id, game_id, user_id, result, idempotency_key)
  values (v_play, p_game_id, v_user, v_result, v_idem);

  return v_result;
end;
$$

