-- Linked event identity remains compatible with its reward-pool-derived IP.
create or replace function public.guard_game_event_contract()
returns trigger
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
begin
  if (
    old.ip_id is distinct from new.ip_id
    or old.mode is distinct from new.mode
  ) and exists (
    select 1
    from public.games as game
    where game.event_id = old.id
  ) then
    raise exception 'game_event_contract_locked' using errcode = '23514';
  end if;

  return new;
end;
$$

create or replace function public.admin_upsert_game(
  target_operation_id uuid,
  target_previous_game_id text,
  target_game_id text,
  target_title text,
  target_reward_pool_id uuid,
  target_event_id text,
  target_per_user_daily_limit integer,
  target_active_from timestamptz,
  target_active_to timestamptz,
  target_end_now boolean
)
returns text
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_previous_game_id text := case
    when target_previous_game_id is null then null
    else nullif(btrim(target_previous_game_id, E' \t\n\r\f\v'), '')
  end;
  normalized_game_id text := case
    when target_game_id is null then null
    else nullif(btrim(target_game_id, E' \t\n\r\f\v'), '')
  end;
  normalized_title text := case
    when target_title is null then null
    else nullif(btrim(target_title, E' \t\n\r\f\v'), '')
  end;
  normalized_event_id text := case
    when target_event_id is null then null
    else nullif(btrim(target_event_id, E' \t\n\r\f\v'), '')
  end;
  request_payload jsonb;
  previous_game public.games%rowtype;
  new_pool public.card_pools%rowtype;
  new_event public.events%rowtype;
  previous_payload jsonb := null;
  after_payload jsonb;
  generated_config jsonb;
  effective_config jsonb;
  rarity_lineup jsonb;
  previous_game_exists boolean := false;
  has_plays boolean := false;
  pool_is_ready boolean := false;
  effective_end timestamptz;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  locked_game_id text;
  locked_pool_id uuid;
  locked_event_id text;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if target_end_now is true then
    if normalized_previous_game_id is null
      or normalized_previous_game_id !~ '^[a-z0-9][a-z0-9-]*$'
    then
      raise exception 'invalid_game_id' using errcode = '22023';
    end if;

    request_payload := jsonb_build_object(
      'game_id', normalized_previous_game_id,
      'end_now', true
    );

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'admin_game_operation:' || target_operation_id::text,
        0
      )
    );

    select audit.actor_id, audit.action, audit.target, audit.diff
      into existing_actor_id, existing_action, existing_target, existing_diff
    from public.audit_log as audit
    where audit.id = target_operation_id;

    if found then
      if existing_actor_id = actor_id
        and existing_action = 'admin.game.ended'
        and existing_target = 'games:' || normalized_previous_game_id
        and existing_diff -> 'request' = request_payload
      then
        return normalized_previous_game_id;
      end if;

      raise exception 'operation_conflict' using errcode = '23505';
    end if;

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'admin_game:' || normalized_previous_game_id,
        0
      )
    );

    select game.*
      into previous_game
    from public.games as game
    where game.id = normalized_previous_game_id
    for update;

    if not found then
      raise exception 'game_not_found' using errcode = 'P0002';
    end if;

    if previous_game.type is distinct from 'marble_roulette'
      or previous_game.config #>> '{variant,kind}' is distinct from 'card'
      or previous_game.config ->> 'marbleCount' is distinct from '10'
      or previous_game.reward_pool_id is null
    then
      raise exception 'game_variant_read_only' using errcode = '23514';
    end if;

    effective_end := statement_timestamp();

    if effective_end <= previous_game.active_from
      or (
        previous_game.active_to is not null
        and effective_end >= previous_game.active_to
      )
    then
      raise exception 'game_not_active' using errcode = '55000';
    end if;

    previous_payload := jsonb_build_object(
      'id', previous_game.id,
      'type', previous_game.type,
      'title', previous_game.title,
      'event_id', previous_game.event_id,
      'config', previous_game.config,
      'reward_pool_id', previous_game.reward_pool_id,
      'per_user_daily_limit', previous_game.per_user_daily_limit,
      'active_from', previous_game.active_from,
      'active_to', previous_game.active_to
    );

    update public.games
    set active_to = effective_end
    where id = normalized_previous_game_id;

    after_payload := previous_payload || jsonb_build_object('active_to', effective_end);

    insert into public.audit_log (id, actor_id, action, target, diff)
    values (
      target_operation_id,
      actor_id,
      'admin.game.ended',
      'games:' || normalized_previous_game_id,
      jsonb_build_object(
        'request', request_payload,
        'before', previous_payload,
        'after', after_payload
      )
    );

    return normalized_previous_game_id;
  end if;

  if normalized_game_id is null
    or normalized_game_id !~ '^[a-z0-9][a-z0-9-]*$'
    or (
      normalized_previous_game_id is not null
      and normalized_previous_game_id !~ '^[a-z0-9][a-z0-9-]*$'
    )
  then
    raise exception 'invalid_game_id' using errcode = '22023';
  end if;

  if normalized_title is null then
    raise exception 'invalid_game_title' using errcode = '22023';
  end if;

  if target_per_user_daily_limit is null
    or target_per_user_daily_limit not between 1 and 100
  then
    raise exception 'invalid_game_daily_limit' using errcode = '22023';
  end if;

  if target_active_from is null then
    raise exception 'invalid_game_active_from' using errcode = '22004';
  end if;

  if target_active_to is not null and target_active_to <= target_active_from then
    raise exception 'invalid_game_active_window' using errcode = '23514';
  end if;

  if target_reward_pool_id is null then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  request_payload := jsonb_build_object(
    'previous_game_id', normalized_previous_game_id,
    'game_id', normalized_game_id,
    'title', normalized_title,
    'reward_pool_id', target_reward_pool_id,
    'event_id', normalized_event_id,
    'per_user_daily_limit', target_per_user_daily_limit,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'end_now', false
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_game_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.game.upserted'
      and existing_target = 'games:' || normalized_game_id
      and existing_diff -> 'request' = request_payload
    then
      return normalized_game_id;
    end if;

    raise exception 'operation_conflict' using errcode = '23505';
  end if;

  -- A->B and B->A renames take identical advisory locks in lexical order.
  for locked_game_id in
    select distinct locked.id
    from unnest(array[normalized_previous_game_id, normalized_game_id]::text[])
      as locked(id)
    where locked.id is not null
    order by locked.id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('admin_game:' || locked_game_id, 0)
    );
  end loop;

  if normalized_previous_game_id is null then
    perform 1
    from public.games as game
    where game.id = normalized_game_id
    for update;

    if found then
      raise exception 'game_id_conflict' using errcode = '23505';
    end if;
  else
    select game.*
      into previous_game
    from public.games as game
    where game.id = normalized_previous_game_id
    for update;

    if not found then
      raise exception 'game_not_found' using errcode = 'P0002';
    end if;

    previous_game_exists := true;

    if previous_game.type is distinct from 'marble_roulette'
      or previous_game.config #>> '{variant,kind}' is distinct from 'card'
      or previous_game.config ->> 'marbleCount' is distinct from '10'
      or previous_game.reward_pool_id is null
    then
      raise exception 'game_variant_read_only' using errcode = '23514';
    end if;

    if normalized_game_id is distinct from normalized_previous_game_id then
      perform 1
      from public.games as game
      where game.id = normalized_game_id
      for update;

      if found then
        raise exception 'game_id_conflict' using errcode = '23505';
      end if;
    end if;

    -- This separate statement runs after the row lock wait, so a concurrent
    -- play committed ahead of us is visible before any immutable mutation.
    select exists (
      select 1
      from public.game_plays as game_play
      where game_play.game_id = normalized_previous_game_id
    ) into has_plays;

    if has_plays and (
      normalized_game_id is distinct from previous_game.id
      or target_reward_pool_id is distinct from previous_game.reward_pool_id
      or normalized_event_id is distinct from previous_game.event_id
    ) then
      raise exception 'game_catalog_locked' using errcode = '23514';
    end if;
  end if;

  -- Pool rows are shared in a stable order. This serializes both play/runtime
  -- reads and pool-window mutations with the same catalog snapshot.
  for locked_pool_id in
    select distinct locked.id
    from unnest(array[
      case when previous_game_exists then previous_game.reward_pool_id else null end,
      target_reward_pool_id
    ]::uuid[]) as locked(id)
    where locked.id is not null
    order by locked.id
  loop
    perform 1
    from public.card_pools as pool
    where pool.id = locked_pool_id
    for share;
  end loop;

  select pool.*
    into new_pool
  from public.card_pools as pool
  where pool.id = target_reward_pool_id;

  if not found then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  if new_pool.active_to is not null
    and statement_timestamp() >= new_pool.active_to
  then
    raise exception 'reward_pool_not_ready' using errcode = '55000';
  end if;

  select
    count(*) = 5
    and coalesce(sum(pool_odd.probability), 0) = 1
    and coalesce(bool_and(pool_odd.probability between 0 and 1), false)
    and not exists (
      select 1
      from public.pool_odds as positive_odd
      where positive_odd.pool_id = target_reward_pool_id
        and positive_odd.probability > 0
        and not exists (
          select 1
          from public.cards as card
          where card.pool_id = target_reward_pool_id
            and card.rarity = positive_odd.rarity
        )
    )
    into pool_is_ready
  from public.pool_odds as pool_odd
  where pool_odd.pool_id = target_reward_pool_id;

  if not pool_is_ready then
    raise exception 'reward_pool_not_ready' using errcode = '55000';
  end if;

  if new_pool.active_from > target_active_from
    or (target_active_to is null and new_pool.active_to is not null)
    or (
      target_active_to is not null
      and new_pool.active_to is not null
      and new_pool.active_to < target_active_to
    )
  then
    raise exception 'game_pool_window_not_covered' using errcode = '23514';
  end if;

  -- Existing and requested events are shared in lexical order. FOR SHARE is
  -- required because IP/mode updates do not necessarily change key columns.
  for locked_event_id in
    select distinct locked.id
    from unnest(array[
      case when previous_game_exists then previous_game.event_id else null end,
      normalized_event_id
    ]::text[]) as locked(id)
    where locked.id is not null
    order by locked.id
  loop
    perform 1
    from public.events as event
    where event.id = locked_event_id
    for share;
  end loop;

  if normalized_event_id is not null then
    select event.*
      into new_event
    from public.events as event
    where event.id = normalized_event_id;

    if not found then
      raise exception 'event_not_found' using errcode = 'P0002';
    end if;

    if new_event.ip_id is distinct from new_pool.ip_id then
      raise exception 'game_event_ip_mismatch' using errcode = '23514';
    end if;

    if new_event.mode is distinct from '온라인' then
      raise exception 'game_event_mode_invalid' using errcode = '23514';
    end if;
  end if;

  -- Hamilton/largest-remainder allocation. Equal remainders and the final
  -- cosmetic lineup both use the public.rarity enum order N,R,SR,SSR,HOLO.
  with slot_share as (
    select
      pool_odd.rarity,
      floor(pool_odd.probability * 10)::integer as base_slots,
      pool_odd.probability * 10 - floor(pool_odd.probability * 10) as remainder
    from public.pool_odds as pool_odd
    where pool_odd.pool_id = target_reward_pool_id
  ),
  ranked_share as (
    select
      slot_share.*,
      row_number() over (
        order by slot_share.remainder desc, slot_share.rarity
      ) as remainder_rank,
      10 - sum(slot_share.base_slots) over () as remaining_slots
    from slot_share
  ),
  expanded_slot as (
    select ranked_share.rarity, generated.slot
    from ranked_share
    cross join lateral generate_series(
      1,
      ranked_share.base_slots
        + case
            when ranked_share.remainder_rank <= ranked_share.remaining_slots then 1
            else 0
          end
    ) as generated(slot)
  )
  select jsonb_agg(to_jsonb(expanded_slot.rarity::text)
    order by expanded_slot.rarity, expanded_slot.slot)
    into rarity_lineup
  from expanded_slot;

  generated_config := jsonb_build_object(
    'marbleCount', 10,
    'variant', jsonb_build_object(
      'kind', 'card',
      'rarityLineup', rarity_lineup
    )
  );

  if previous_game_exists then
    previous_payload := jsonb_build_object(
      'id', previous_game.id,
      'type', previous_game.type,
      'title', previous_game.title,
      'event_id', previous_game.event_id,
      'config', previous_game.config,
      'reward_pool_id', previous_game.reward_pool_id,
      'per_user_daily_limit', previous_game.per_user_daily_limit,
      'active_from', previous_game.active_from,
      'active_to', previous_game.active_to
    );
  end if;

  effective_config := case
    when has_plays then previous_game.config
    else generated_config
  end;

  if previous_game_exists then
    update public.games
    set
      id = normalized_game_id,
      type = 'marble_roulette',
      title = normalized_title,
      event_id = normalized_event_id,
      config = effective_config,
      reward_pool_id = target_reward_pool_id,
      per_user_daily_limit = target_per_user_daily_limit,
      active_from = target_active_from,
      active_to = target_active_to
    where id = normalized_previous_game_id;
  else
    insert into public.games (
      id,
      type,
      title,
      event_id,
      config,
      reward_pool_id,
      per_user_daily_limit,
      active_from,
      active_to
    )
    values (
      normalized_game_id,
      'marble_roulette',
      normalized_title,
      normalized_event_id,
      effective_config,
      target_reward_pool_id,
      target_per_user_daily_limit,
      target_active_from,
      target_active_to
    );
  end if;

  after_payload := jsonb_build_object(
    'id', normalized_game_id,
    'type', 'marble_roulette',
    'title', normalized_title,
    'event_id', normalized_event_id,
    'config', effective_config,
    'reward_pool_id', target_reward_pool_id,
    'per_user_daily_limit', target_per_user_daily_limit,
    'active_from', target_active_from,
    'active_to', target_active_to
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.game.upserted',
    'games:' || normalized_game_id,
    jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return normalized_game_id;
end;
$$

revoke all on function public.admin_upsert_game(
  uuid, text, text, text, uuid, text, integer, timestamptz, timestamptz, boolean
) from public, anon, authenticated, service_role

grant execute on function public.admin_upsert_game(
  uuid, text, text, text, uuid, text, integer, timestamptz, timestamptz, boolean
) to authenticated

do $$
begin
  if exists (
    select lower(btrim(
      nickname,
      U&'\0009\000B\000C\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\202F\205F\3000\FEFF\000A\000D\2028\2029'
    ))
    from public.profiles
    where nickname is not null
    group by lower(btrim(
      nickname,
      U&'\0009\000B\000C\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\202F\205F\3000\FEFF\000A\000D\2028\2029'
    ))
    having count(*) > 1
  ) then
    raise exception using message = 'profiles contain normalized nickname conflicts';
  end if;

  if exists (
    select 1
    from public.profiles
    where nickname is not null
      and (
        nickname <> btrim(
          nickname,
          U&'\0009\000B\000C\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\202F\205F\3000\FEFF\000A\000D\2028\2029'
        )
        or nickname = ''
        or char_length(nickname) > 512
      )
  ) then
    raise exception using message = 'profiles contain invalid nickname values';
  end if;

  if exists (
    select 1
    from public.profiles
    where avatar_path is not null
      and avatar_path !~ (
        '^'
        || id::text
        || '/profile/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
      )
  ) then
    raise exception using message = 'profiles contain invalid avatar paths';
  end if;
end;
$$

create or replace function public.service_reject_profile_avatar_claim(
  p_user_id uuid,
  p_avatar_path text
)
returns table (
  rejected boolean,
  cleanup_safe boolean
)
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_status text;
begin
  select claim.status
  into v_status
  from public.profile_avatar_claims as claim
  where claim.path = p_avatar_path
    and claim.user_id = p_user_id
  for update;

  if not found or v_status <> 'pending' then
    return query select false, false;
    return;
  end if;

  update public.profile_avatar_claims as claim
  set
    status = 'rejected',
    resolved_at = now()
  where claim.path = p_avatar_path
    and claim.user_id = p_user_id
    and claim.status = 'pending';

  if not found then
    return query select false, false;
    return;
  end if;

  return query select true, true;
end;
$$

create or replace function public.service_update_profile_identity(
  p_user_id uuid,
  p_nickname text,
  p_avatar_path text,
  p_replace_avatar boolean
)
returns table (
  applied boolean,
  error_code text,
  cleanup_safe boolean,
  previous_avatar_path text
)
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_previous_avatar_path text;
  v_claim_status text;
  v_error_code text;
  v_rejected_count bigint := 0;
begin
  if p_user_id is null or p_nickname is null or p_replace_avatar is null then
    return query select false, '22023'::text, false, null::text;
    return;
  end if;

  if p_replace_avatar and p_avatar_path is null then
    return query select false, '22023'::text, false, null::text;
    return;
  end if;

  if not p_replace_avatar and p_avatar_path is not null then
    return query select false, '22023'::text, false, null::text;
    return;
  end if;

  select profile.avatar_path
  into v_previous_avatar_path
  from public.profiles as profile
  where profile.id = p_user_id
  for update;

  if not found then
    return query select false, 'P0002'::text, false, null::text;
    return;
  end if;

  if p_replace_avatar then
    select claim.status
    into v_claim_status
    from public.profile_avatar_claims as claim
    where claim.path = p_avatar_path
      and claim.user_id = p_user_id
    for update;

    if not found then
      return query select false, 'avatar_unclaimed'::text, false, null::text;
      return;
    end if;

    if v_claim_status <> 'pending' then
      return query select false, 'avatar_replayed'::text, false, null::text;
      return;
    end if;
  end if;

  begin
    update public.profiles as profile
    set
      nickname = p_nickname,
      avatar_path = case
        when p_replace_avatar then p_avatar_path
        else profile.avatar_path
      end
    where profile.id = p_user_id;

    if p_replace_avatar and v_previous_avatar_path is not null then
      update public.profile_avatar_claims as claim
      set
        status = 'retired',
        resolved_at = now()
      where claim.path = v_previous_avatar_path
        and claim.user_id = p_user_id
        and claim.status = 'active';

      if not found then
        raise exception using
          errcode = '23514',
          message = 'active previous avatar claim is missing';
      end if;
    end if;

    if p_replace_avatar then
      update public.profile_avatar_claims as claim
      set
        status = 'active',
        resolved_at = now()
      where claim.path = p_avatar_path
        and claim.user_id = p_user_id
        and claim.status = 'pending';

      if not found then
        raise exception using
          errcode = '23514',
          message = 'pending avatar claim changed during finalization';
      end if;
    end if;
  exception
    when others then
      get stacked diagnostics v_error_code = returned_sqlstate;

      if p_replace_avatar then
        update public.profile_avatar_claims as claim
        set
          status = 'rejected',
          resolved_at = now()
        where claim.path = p_avatar_path
          and claim.user_id = p_user_id
          and claim.status = 'pending';

        get diagnostics v_rejected_count = row_count;
      end if;

      return query select false, v_error_code, v_rejected_count = 1, null::text;
      return;
  end;

  return query select true, null::text, false, v_previous_avatar_path;
end;
$$

create or replace function public.open_notification(target_notification_id uuid)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor_id uuid := (select auth.uid());
  notification_link text;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  update public.notifications as notification
  set read_at = coalesce(notification.read_at, now())
  where notification.id = target_notification_id
    and notification.user_id = actor_id
  returning notification.link_path into notification_link;

  if not found then
    raise exception 'notification_not_found' using errcode = 'P0002';
  end if;

  return notification_link;
end;
$$

create or replace function public.set_ip_notification_preferences(
  target_ip_id text,
  target_notify_drops boolean default null,
  target_notify_events boolean default null,
  target_auto_follow boolean default false
)
returns table (notify_drops boolean, notify_events boolean)
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor_id uuid := (select auth.uid());
  updated_notify_drops boolean;
  updated_notify_events boolean;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if target_auto_follow then
    perform public.follow_ip(target_ip_id);
  end if;

  update public.ip_follows as follow
  set
    notify_drops = coalesce(target_notify_drops, follow.notify_drops),
    notify_events = coalesce(target_notify_events, follow.notify_events)
  where follow.user_id = actor_id
    and follow.ip_id = target_ip_id
  returning follow.notify_drops, follow.notify_events
  into updated_notify_drops, updated_notify_events;

  if not found then
    raise exception 'notification_preferences_not_found' using errcode = 'P0002';
  end if;

  return query
    select updated_notify_drops, updated_notify_events;
end;
$$

create or replace function public.admin_estimate_notification_recipients(
  target_scope text,
  target_ip_id text default null
)
returns table (
  scope text,
  ip_id text,
  ip_title text,
  recipient_count bigint,
  can_send boolean
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_scope text := pg_catalog.btrim(target_scope, E' \t\n\r\f\v');
  normalized_ip_id text := nullif(
    pg_catalog.btrim(target_ip_id, E' \t\n\r\f\v'),
    ''
  );
  selected_ip_title text;
  estimated_recipient_count bigint;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if normalized_scope is null
    or normalized_scope not in ('all', 'ip_followers')
  then
    raise exception 'invalid_notification_scope' using errcode = '22023';
  end if;

  if normalized_scope = 'all' then
    if normalized_ip_id is not null then
      raise exception 'invalid_notification_target' using errcode = '22023';
    end if;

    select pg_catalog.count(*)
      into estimated_recipient_count
    from public.profiles;
  else
    if normalized_ip_id is null then
      raise exception 'invalid_notification_target' using errcode = '22023';
    end if;

    select ip.title
      into selected_ip_title
    from public.ips as ip
    where ip.id = normalized_ip_id;

    if not found then
      raise exception 'ip_not_found' using errcode = 'P0002';
    end if;

    select pg_catalog.count(*)
      into estimated_recipient_count
    from public.ip_follows as follow
    where follow.ip_id = normalized_ip_id;
  end if;

  return query
    select
      normalized_scope,
      normalized_ip_id,
      selected_ip_title,
      estimated_recipient_count,
      estimated_recipient_count > 0;
end;
$$

create or replace function public.admin_send_notification(
  target_operation_id uuid,
  target_scope text,
  target_ip_id text,
  target_title text,
  target_body text
)
returns table (
  recipient_count bigint,
  sent_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_scope text := pg_catalog.btrim(target_scope, E' \t\n\r\f\v');
  normalized_ip_id text := nullif(
    pg_catalog.btrim(target_ip_id, E' \t\n\r\f\v'),
    ''
  );
  normalized_title text := pg_catalog.btrim(target_title, E' \t\n\r\f\v');
  normalized_body text := pg_catalog.btrim(target_body, E' \t\n\r\f\v');
  request_payload jsonb;
  requested_target text;
  selected_ip_title text;
  actual_recipient_count bigint;
  sent_timestamp timestamptz;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  existing_sent_at timestamptz;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if normalized_scope is null
    or normalized_scope not in ('all', 'ip_followers')
  then
    raise exception 'invalid_notification_scope' using errcode = '22023';
  end if;

  if normalized_scope = 'all' then
    if normalized_ip_id is not null then
      raise exception 'invalid_notification_target' using errcode = '22023';
    end if;
    requested_target := 'notifications:all';
  else
    if normalized_ip_id is null then
      raise exception 'invalid_notification_target' using errcode = '22023';
    end if;
    requested_target := 'notifications:ip_followers:' || normalized_ip_id;
  end if;

  if normalized_title is null
    or pg_catalog.char_length(normalized_title) < 1
    or pg_catalog.char_length(normalized_title) > 120
  then
    raise exception 'invalid_notification_title' using errcode = '22023';
  end if;

  if normalized_body is null
    or pg_catalog.char_length(normalized_body) < 1
    or pg_catalog.char_length(normalized_body) > 500
  then
    raise exception 'invalid_notification_body' using errcode = '22023';
  end if;

  request_payload := pg_catalog.jsonb_build_object(
    'scope', normalized_scope,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'body', normalized_body
  );

  -- A lost-response retry must observe the first commit before deciding whether
  -- the operation is an idempotent replay or a conflicting reuse.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_notification_operation:' || target_operation_id::text,
      0
    )
  );

  select
    audit.actor_id,
    audit.action,
    audit.target,
    audit.diff,
    audit.created_at
  into
    existing_actor_id,
    existing_action,
    existing_target,
    existing_diff,
    existing_sent_at
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.notification.sent'
      and existing_target = requested_target
      and existing_diff -> 'request' = request_payload
    then
      return query
        select
          (existing_diff #>> '{result,recipient_count}')::bigint,
          existing_sent_at;
      return;
    end if;

    raise exception 'operation_conflict' using errcode = '23505';
  end if;

  if normalized_scope = 'ip_followers' then
    select ip.title
      into selected_ip_title
    from public.ips as ip
    where ip.id = normalized_ip_id
    for key share;

    if not found then
      raise exception 'ip_not_found' using errcode = 'P0002';
    end if;
  end if;

  if normalized_scope = 'all' then
    insert into public.notifications (
      user_id,
      type,
      title,
      body,
      link_path,
      source_type,
      source_id,
      dedupe_key
    )
    select
      profile.id,
      'announcement',
      normalized_title,
      normalized_body,
      '/notifications',
      'admin_announcement',
      target_operation_id::text,
      'announcement:' || target_operation_id::text
    from public.profiles as profile;
  else
    insert into public.notifications (
      user_id,
      type,
      title,
      body,
      link_path,
      source_type,
      source_id,
      dedupe_key
    )
    select
      follow.user_id,
      'announcement',
      normalized_title,
      normalized_body,
      '/notifications',
      'admin_announcement',
      target_operation_id::text,
      'announcement:' || target_operation_id::text
    from public.ip_follows as follow
    where follow.ip_id = normalized_ip_id;
  end if;

  get diagnostics actual_recipient_count = row_count;

  if actual_recipient_count = 0 then
    raise exception 'notification_no_recipients' using errcode = '22023';
  end if;

  sent_timestamp := pg_catalog.clock_timestamp();

  insert into public.audit_log (
    id,
    actor_id,
    action,
    target,
    diff,
    created_at
  )
  values (
    target_operation_id,
    actor_id,
    'admin.notification.sent',
    requested_target,
    pg_catalog.jsonb_build_object(
      'request', request_payload,
      'result', pg_catalog.jsonb_build_object(
        'ip_title', selected_ip_title,
        'link_path', '/notifications',
        'recipient_count', actual_recipient_count
      )
    ),
    sent_timestamp
  );

  return query
    select actual_recipient_count, sent_timestamp;
end;
$$

create or replace function public.edit_own_post(
  target_post_id uuid,
  post_text text,
  post_ip_id text,
  post_tag text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor_id uuid := auth.uid();
  normalized_text text := nullif(btrim(post_text), '');
  normalized_ip_id text := nullif(btrim(post_ip_id), '');
  normalized_tag text := nullif(btrim(post_tag), '');
  previous_ip_id text;
  edited_at timestamptz;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if normalized_text is null then
    raise exception 'invalid_post_text' using errcode = '22023';
  end if;

  perform 1
  from public.ips
  where ips.id = normalized_ip_id
  for key share;

  if not found then
    raise exception 'invalid_post_ip' using errcode = '22023';
  end if;

  select posts.ip_id
    into previous_ip_id
    from public.posts
    where posts.id = target_post_id
      and posts.user_id = actor_id
      and posts.status = 'visible'
    for update;

  if not found then
    raise exception 'post_not_editable' using errcode = '42501';
  end if;

  update public.posts
  set
    text = normalized_text,
    ip_id = normalized_ip_id,
    tag = normalized_tag
  where id = target_post_id
  returning updated_at into edited_at;

  return jsonb_build_object(
    'previousIpId', previous_ip_id,
    'ipId', normalized_ip_id,
    'updatedAt', edited_at
  );
end;
$$

create or replace function public.submit_community_report(
  target_type public.report_target,
  target_id text,
  reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor_id uuid := auth.uid();
  target_uuid uuid;
  normalized_reason text := nullif(btrim(reason), '');
  target_ip_id text := null;
  target_post_id uuid;
  inserted_report_id uuid;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if target_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'target_not_found' using errcode = '22023';
  end if;

  target_uuid := target_id::uuid;

  if target_type = 'post' then
    select posts.ip_id
      into target_ip_id
      from public.posts
      where posts.id = target_uuid
        and posts.status = 'visible';

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  elsif target_type = 'comment' then
    select comments.post_id
      into target_post_id
      from public.comments
      where comments.id = target_uuid;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;

    select posts.ip_id
      into target_ip_id
      from public.posts
      where posts.id = target_post_id
        and posts.status = 'visible'
      for share;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;

    perform 1
    from public.comments
    where comments.id = target_uuid
      and comments.post_id = target_post_id
      and comments.status = 'visible'
    for share;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  elsif target_type = 'user' then
    perform 1
    from public.profiles
    where profiles.id = target_uuid;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  else
    raise exception 'target_not_found' using errcode = '22023';
  end if;

  insert into public.reports (target_type, target_id, reporter_id, reason)
  values (target_type, target_uuid::text, actor_id, normalized_reason)
  returning id into inserted_report_id;

  return jsonb_build_object('reportId', inserted_report_id, 'ipId', target_ip_id);
end;
$$

create or replace function public.admin_hide_community_comment(
  target_comment_id uuid,
  target_report_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor_id uuid := auth.uid();
  previous_status public.post_status;
  target_ip_id text;
  target_post_id uuid;
  linked_report_target public.report_target;
  linked_report_target_id text;
  linked_report_status public.report_status;
begin
  if actor_id is null or not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select comments.post_id
    into target_post_id
    from public.comments
    where comments.id = target_comment_id;

  if not found then
    raise exception 'comment_not_found' using errcode = '22023';
  end if;

  select posts.ip_id
    into target_ip_id
    from public.posts
    where posts.id = target_post_id
    for update;

  if not found then
    raise exception 'comment_not_found' using errcode = '22023';
  end if;

  select comments.status
    into previous_status
    from public.comments
    where comments.id = target_comment_id
      and comments.post_id = target_post_id
    for update;

  if not found then
    raise exception 'comment_not_found' using errcode = '22023';
  end if;

  if target_report_id is not null then
    select reports.target_type, reports.target_id, reports.status
      into linked_report_target, linked_report_target_id, linked_report_status
      from public.reports
      where reports.id = target_report_id
      for update;

    if not found then
      raise exception 'report_not_found' using errcode = '22023';
    end if;

    if linked_report_target <> 'comment'
      or linked_report_target_id <> target_comment_id::text then
      raise exception 'report_target_mismatch' using errcode = '22023';
    end if;
  end if;

  if previous_status = 'hidden' then
    if target_report_id is not null and linked_report_status <> 'resolved' then
      raise exception 'comment_already_hidden' using errcode = '22023';
    end if;

    return jsonb_build_object('ipId', target_ip_id);
  end if;

  update public.comments
  set status = 'hidden'
  where id = target_comment_id;

  if target_report_id is not null then
    update public.reports
    set status = 'resolved'
    where id = target_report_id;
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'community_comment_hide',
    'comment:' || target_comment_id::text,
    jsonb_build_object(
      'from', previous_status,
      'to', 'hidden',
      'reportId', target_report_id
    )
  );

  return jsonb_build_object('ipId', target_ip_id);
end;
$$

