  if v_current_carrier is not distinct from v_carrier
    and v_current_tracking is not distinct from v_tracking
  then
    return;
  end if;

  update public.orders
  set
    shipping_carrier = v_carrier,
    tracking_number = v_tracking
  where id = p_order_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.tracking_updated',
    'order:' || p_order_id::text,
    jsonb_build_object(
      'fromCarrier', v_current_carrier,
      'fromTrackingNumber', v_current_tracking,
      'toCarrier', v_carrier,
      'toTrackingNumber', v_tracking
    )
  );
end;
$$

-- 발송 권한 클레임. true를 받은 호출자만 실제로 메일을 보낸다.
-- 이미 sent이거나 다른 시도가 아직 살아 있으면 false — 웹훅 재전송이 여기서 흡수된다.
create or replace function public.claim_email_delivery(
  target_dedupe_key text,
  target_template text,
  target_recipient text,
  target_subject text,
  target_retry_after interval default interval '10 minutes'
)
returns boolean
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  normalized_key text := btrim(coalesce(target_dedupe_key, ''), E' \t\n\r\f\v');
  normalized_subject text := btrim(coalesce(target_subject, ''), E' \t\n\r\f\v');
  normalized_recipient text := btrim(coalesce(target_recipient, ''), E' \t\n\r\f\v');
  existing record;
begin
  if char_length(normalized_key) < 1 or char_length(normalized_key) > 200 then
    raise exception 'invalid_dedupe_key' using errcode = '22023';
  end if;
  if target_template is null or target_template not in ('order_confirmation', 'order_shipped') then
    raise exception 'invalid_email_template' using errcode = '22023';
  end if;
  if char_length(normalized_recipient) < 3 or char_length(normalized_recipient) > 320 then
    raise exception 'invalid_email_recipient' using errcode = '22023';
  end if;
  if char_length(normalized_subject) < 1 or char_length(normalized_subject) > 200 then
    raise exception 'invalid_email_subject' using errcode = '22023';
  end if;

  -- 응답이 유실된 재시도는 먼저 커밋된 클레임을 관측한 뒤에 판단해야 한다.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('email_delivery:' || normalized_key, 0)
  );

  select delivery.id, delivery.status, delivery.attempt_count, delivery.claimed_at
    into existing
  from public.email_deliveries as delivery
  where delivery.dedupe_key = normalized_key
  for update;

  if found then
    if existing.status = 'sent' then
      return false;
    end if;
    if existing.status = 'pending'
      and existing.claimed_at > now() - coalesce(target_retry_after, interval '10 minutes')
    then
      return false;
    end if;
    if existing.attempt_count >= 1000 then
      return false;
    end if;

    update public.email_deliveries
    set
      status = 'pending',
      attempt_count = existing.attempt_count + 1,
      subject = normalized_subject,
      recipient = normalized_recipient,
      claimed_at = now(),
      completed_at = null
    where id = existing.id;

    return true;
  end if;

  insert into public.email_deliveries (
    dedupe_key,
    template,
    recipient,
    subject,
    status
  )
  values (
    normalized_key,
    target_template,
    normalized_recipient,
    normalized_subject,
    'pending'
  );

  return true;
end;
$$

-- 수동 발급은 남용 여지가 크므로 한 번에 낼 수 있는 수량을 묶어둔다.
-- 자동 발급 정책의 tickets_per_grant(1~100)보다 낮게 잡는다 — 정책은 조건을 통과한
-- 주문에만 발동하지만 수동 발급은 조건 없이 임의 사용자에게 나간다.
create or replace function public.admin_grant_draw_tickets(
  target_operation_id uuid,
  target_profile_id uuid,
  target_pool_id uuid,
  target_quantity integer,
  target_reason text
)
returns integer
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_reason text;
  requested_diff jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  recipient record;
  pool_record public.card_pools%rowtype;
  pool_is_ready boolean := false;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  -- 발급 정책 콘솔과 같은 권한선을 쓴다. staff는 이미 조건 없는 자동 발급 정책을 만들 수
  -- 있으므로 수동 발급만 admin으로 좁히는 것은 실질 방어가 되지 않는다. 대신 수량 상한과
  -- 감사 기록으로 막는다.
  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if target_quantity is null or target_quantity not between 1 and 10 then
    raise exception 'invalid_grant_quantity' using errcode = '22023';
  end if;

  normalized_reason := btrim(coalesce(target_reason, ''), E' \t\n\r\f\v');
  if char_length(normalized_reason) < 1 or char_length(normalized_reason) > 200 then
    raise exception 'invalid_grant_reason' using errcode = '22023';
  end if;

  -- 응답이 유실된 재시도는 먼저 커밋된 감사 기록을 관측한 뒤에 판단해야 한다.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_draw_ticket_grant:' || target_operation_id::text, 0)
  );

  requested_diff := jsonb_build_object(
    'poolId', target_pool_id,
    'quantity', target_quantity,
    'reason', normalized_reason
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.draw_ticket.granted'
      and existing_target = 'profiles:' || target_profile_id::text
      and existing_diff = requested_diff
    then
      return (existing_diff ->> 'quantity')::integer;
    end if;

    raise exception 'grant_conflict' using errcode = '23505';
  end if;

  select profile.id, profile.suspended_at
    into recipient
  from public.profiles as profile
  where profile.id = target_profile_id
  for key share;

  if not found then
    raise exception 'profile_not_found' using errcode = 'P0002';
  end if;

  -- 정지 계정은 개봉 자체가 막혀 있다(trg_draw_tickets_active_consumption).
  -- 열 수 없는 티켓을 쌓아두지 않는다.
  if recipient.suspended_at is not null then
    raise exception 'recipient_suspended' using errcode = '55000';
  end if;

  select pool.*
    into pool_record
  from public.card_pools as pool
  where pool.id = target_pool_id
  for share;

  if not found then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  if pool_record.active_to is not null and now() >= pool_record.active_to then
    raise exception 'reward_pool_not_ready' using errcode = '55000';
  end if;

  -- 발급 정책 콘솔과 같은 준비 판정이다. 확률 합이 100%가 아니거나 확률이 양수인 등급에
  -- 카드가 없으면 개봉이 'pool has no card of rarity'로 실패한다 — 열 수 없는 티켓을
  -- 만들지 않는다.
  select
    count(*) = 5
    and coalesce(sum(pool_odd.probability), 0) = 1
    and coalesce(bool_and(pool_odd.probability between 0 and 1), false)
    and not exists (
      select 1
      from public.pool_odds as positive_odd
      where positive_odd.pool_id = target_pool_id
        and positive_odd.probability > 0
        and not exists (
          select 1
          from public.cards as card
          where card.pool_id = target_pool_id
            and card.rarity = positive_odd.rarity
        )
    )
    into pool_is_ready
  from public.pool_odds as pool_odd
  where pool_odd.pool_id = target_pool_id;

  if not pool_is_ready then
    raise exception 'reward_pool_not_ready' using errcode = '55000';
  end if;

  -- source_id = operation_id 라서 unique (source, source_id, ordinal)이 재시도 이중 발급을
  -- DB 레벨에서 한 번 더 막는다. reward_policy_id는 비워 정책 집계와 분리한다.
  insert into public.draw_tickets (
    user_id,
    pool_id,
    source,
    source_id,
    ordinal
  )
  select
    target_profile_id,
    target_pool_id,
    'admin_grant',
    target_operation_id,
    grant_series.n
  from generate_series(1, target_quantity) as grant_series(n)
  on conflict (source, source_id, ordinal) do nothing;

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.draw_ticket.granted',
    'profiles:' || target_profile_id::text,
    requested_diff
  );

  return target_quantity;
end;
$$

-- 재발송 게이트. 통과한 호출자만 발송 훅을 다시 부른다.
-- 반환값은 템플릿 이름 — 호출자가 어떤 메일을 다시 만들지 고르는 데 쓴다.
create or replace function public.admin_request_email_resend(p_dedupe_key text)
returns text
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := (select auth.uid());
  v_key text := nullif(btrim(coalesce(p_dedupe_key, ''), E' \t\n\r\f\v'), '');
  v_template text;
  v_status text;
  v_attempt_count integer;
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if v_key is null then
    raise check_violation using message = 'invalid_dedupe_key';
  end if;

  select delivery.template, delivery.status, delivery.attempt_count
  into v_template, v_status, v_attempt_count
  from public.email_deliveries as delivery
  where delivery.dedupe_key = v_key
  for update;

  if not found then
    raise no_data_found using message = 'email_delivery_not_found';
  end if;

  -- 이미 도착한 메일을 다시 보내지 않는다. claim_email_delivery도 같은 판단을 하지만,
  -- 운영자에게는 발송 훅을 부르기 전에 이유를 알려주는 편이 낫다.
