  uuid, public.order_status, text, text
) to authenticated

create or replace function public.request_order_cancellation(
  p_order_id uuid,
  p_user_id uuid,
  p_reason text,
  p_reason_type text
)
returns text
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id uuid;
  v_status public.order_status;
  v_delivered_at timestamptz;
  v_request_id uuid;
begin
  if p_reason_type is null or p_reason_type not in ('change_of_mind', 'defect') then
    raise check_violation using message = 'invalid cancellation reason type';
  end if;

  select orders.user_id, orders.status, orders.delivered_at
  into v_user_id, v_status, v_delivered_at
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found or p_user_id is null or v_user_id is distinct from p_user_id then
    return 'not_found';
  end if;

  if v_status = 'canceled' then
    return 'already_canceled';
  end if;

  if v_status not in ('pending', 'paid', 'shipping', 'done') then
    return 'not_cancelable';
  end if;

  if p_reason is null
    or btrim(p_reason) <> p_reason
    or length(p_reason) not between 1 and 200
  then
    raise check_violation using message = 'invalid cancellation reason';
  end if;

  -- 기한 판정은 중복 요청 검사보다 앞선다. 기한이 끝난 주문에 대해 "이미
  -- 요청됨"을 돌려주면 사용자가 처리 중인 요청이 있다고 오해한다.
  if public.order_withdrawal_deadline_passed(v_delivered_at, p_reason_type, now()) then
    return 'deadline_expired';
  end if;

  if exists (
    select 1
    from public.order_cancellation_requests as request
    where request.order_id = p_order_id
      and request.status in ('requested', 'processing', 'needs_review')
  ) then
    return 'already_requested';
  end if;

  insert into public.order_cancellation_requests (
    order_id,
    requested_by,
    reason,
    reason_type,
    status
  )
  values (
    p_order_id,
    p_user_id,
    p_reason,
    p_reason_type,
    'requested'
  )
  returning id into v_request_id;

  if v_status = 'pending'
    and not exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'order'
        and payment.ref_id = p_order_id
    )
  then
    perform public.finalize_order_cancellation_with_provider_evidence(
      p_order_id,
      p_reason,
      array[]::text[]
    );

    update public.order_cancellation_requests
    set
      status = 'completed',
      completed_at = now(),
      updated_at = now()
    where id = v_request_id;

    return 'completed';
  end if;

  return 'requested';
end;
$$

create function private.guard_community_post_write()
returns trigger
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  selected_enabled boolean := false;
  moderation_hide_only boolean := false;
begin
  -- App-role requests may enter through SECURITY DEFINER RPCs. The session
  -- helper stays false whenever SET ROLE carries an application role.
  if private.is_community_write_maintenance() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    select control.post_create_enabled
      into selected_enabled
    from private.community_write_control as control
    where control.singleton;
  elsif tg_op = 'UPDATE' then
    moderation_hide_only := new.status = 'hidden'
      and (to_jsonb(new) - 'status' - 'updated_at')
        is not distinct from
        (to_jsonb(old) - 'status' - 'updated_at');

    if moderation_hide_only then
      return new;
    end if;

    select control.post_edit_enabled
      into selected_enabled
    from private.community_write_control as control
    where control.singleton;
  end if;

  if not coalesce(selected_enabled, false) then
    raise exception 'community_writes_disabled' using errcode = '55000';
  end if;

  return new;
end;
$$

