  values (v_user_id, p_idempotency_key, v_internal_status, v_blockers)
  returning deletion_event_id into v_deletion_event_id;

  perform private.snapshot_account_deletion_legal_records(
    v_deletion_event_id,
    v_user_id
  );

  insert into private.account_action_fences (
    subject_user_id,
    deletion_event_id
  )
  values (v_user_id, v_deletion_event_id);

  return private.account_deletion_public_status(v_user_id);
end;
$$

create or replace function public.get_my_account_deletion_status()
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
begin
  if v_user_id is null then
    raise insufficient_privilege using message = 'authentication_required';
  end if;
  if not exists (
    select 1 from public.profiles as profile where profile.id = v_user_id
  ) then
    raise no_data_found using message = 'account_not_found';
  end if;

  return coalesce(
    private.reconcile_account_deletion_request(v_user_id),
    pg_catalog.jsonb_build_object(
      'status', 'not_requested',
      'phase', 'none',
      'nextAction', '/settings',
      'blockers', '[]'::jsonb
    )
  );
end;
$$

create or replace function private.is_account_write_fenced(p_user_id uuid)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
begin
  if p_user_id is null then
    return false;
  end if;
  perform private.lock_account_action_subject(p_user_id);
  return exists (
    select 1
    from private.account_action_fences as fence
    where fence.subject_user_id = p_user_id
  );
end;
$$

-- A user's global last_sign_in_at is updated by every browser. Account
-- deletion reauthentication must instead prove that the session presenting
-- the current JWT is itself recent and still belongs to the same subject.

create or replace function private.has_recent_account_authentication(p_user_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_session_id_text text := auth.jwt() ->> 'session_id';
  v_session_id uuid;
begin
  if p_user_id is null
    or v_session_id_text is null
    or v_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  then
    return false;
  end if;

  begin
    v_session_id := v_session_id_text::uuid;
  exception
    when invalid_text_representation then
      return false;
  end;

  return exists (
    select 1
    from auth.sessions as auth_session
    where auth_session.id = v_session_id
      and auth_session.user_id = p_user_id
      and auth_session.created_at >= pg_catalog.now() - interval '10 minutes'
      and (
        auth_session.not_after is null
        or auth_session.not_after > pg_catalog.now()
      )
  );
end;
$$

-- The application passes the authenticated user id through a service-role
-- adapter. Ownership, suspension, deletion fence, amount, order snapshot, and
-- reservation state are revalidated under the order row lock.
create function public.prepare_goods_payment_attempt(
  p_user_id uuid,
  p_order_id uuid,
  p_provider public.payment_provider
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_order public.orders%rowtype;
  v_attempt public.payment_attempts%rowtype;
  v_attempt_id uuid;
  v_attempt_expires_at timestamptz;
begin
  if p_user_id is null or p_order_id is null or p_provider is distinct from 'korpay' then
    raise exception 'goods_payment_unavailable' using errcode = '55000';
  end if;

  select order_record.*
  into v_order
  from public.orders as order_record
  where order_record.id = p_order_id
  for update;

  if not found or v_order.user_id is distinct from p_user_id then
    raise no_data_found using message = 'goods_order_not_found';
  end if;

  if v_order.status is distinct from 'pending'
    or v_order.expires_at is null
    or v_order.expires_at <= pg_catalog.clock_timestamp()
    or v_order.total <= 0
  then
    raise object_not_in_prerequisite_state using message = 'goods_order_not_payable';
  end if;

  if private.is_account_write_fenced(p_user_id)
    or exists (
      select 1
      from public.profiles as profile
      where profile.id = p_user_id
        and profile.suspended_at is not null
    )
  then
    raise insufficient_privilege using message = 'goods_payment_account_blocked';
  end if;

  if not private.goods_order_snapshot_matches(
    v_order.id,
    v_order.total,
    v_order.shipping_fee
  ) then
    raise check_violation using message = 'goods_order_snapshot_mismatch';
  end if;

  if exists (
    select 1
    from public.order_cancellation_requests as request
    where request.order_id = v_order.id
      and request.status in ('requested', 'processing', 'needs_review')
  ) or exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'order'
      and payment.ref_id = v_order.id
      and payment.status in ('pending', 'paid')
  ) then
    raise object_not_in_prerequisite_state using message = 'goods_order_not_payable';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'order'
    and attempt.ref_id = v_order.id
  for update;

  if found then
    if v_attempt.user_id is distinct from p_user_id
      or v_attempt.provider is distinct from p_provider
      or v_attempt.amount is distinct from v_order.total
      or v_attempt.currency is distinct from 'KRW'
      or v_attempt.state is distinct from 'prepared'
      or v_attempt.expires_at <= pg_catalog.clock_timestamp()
    then
      raise object_not_in_prerequisite_state using message = 'goods_payment_attempt_not_preparable';
    end if;
    return private.goods_payment_attempt_json(v_attempt);
  end if;

  v_attempt_id := extensions.gen_random_uuid();
  v_attempt_expires_at := least(
    v_order.expires_at,
    pg_catalog.clock_timestamp() + interval '10 minutes'
  );

  insert into public.payment_attempts (
    id,
    provider,
    user_id,
    purpose,
    ref_id,
    amount,
    currency,
    state,
    idempotency_key,
    provider_order_id,
    provider_product_code,
    expires_at
  )
  values (
    v_attempt_id,
    p_provider,
    p_user_id,
    'order',
    v_order.id,
    v_order.total,
    'KRW',
    'prepared',
    'goods:' || v_order.id::text,
    'O' || pg_catalog.replace(v_attempt_id::text, '-', ''),
    'P' || pg_catalog.replace(v_attempt_id::text, '-', ''),
    v_attempt_expires_at
  )
  returning * into v_attempt;

  return private.goods_payment_attempt_json(v_attempt);
end;
$function$

-- Callback lookup is session independent: provider order id + nonce digest
-- locate and atomically claim the attempt before any provider network call.
create function public.claim_goods_payment_attempt(
  p_provider public.payment_provider,
  p_provider_order_id text,
  p_callback_nonce_digest text,
  p_claim_token uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_attempt public.payment_attempts%rowtype;
  v_order public.orders%rowtype;
begin
  if p_provider is distinct from 'korpay'
    or p_provider_order_id is null
    or pg_catalog.length(p_provider_order_id) not between 1 and 200
    or p_callback_nonce_digest is null
    or p_callback_nonce_digest !~ '^[0-9a-f]{64}$'
    or p_claim_token is null
  then
    raise invalid_parameter_value using message = 'goods_payment_callback_invalid';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.provider = p_provider
    and attempt.provider_order_id = p_provider_order_id
    and attempt.purpose = 'order';

  if not found
    or v_attempt.callback_nonce_digest is null
    or v_attempt.callback_nonce_digest is distinct from p_callback_nonce_digest
  then
    raise no_data_found using message = 'goods_payment_callback_invalid';
  end if;

  if v_attempt.state in ('approved', 'declined', 'canceled', 'unknown', 'needs_review') then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.goods_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;

  if v_attempt.state = 'confirming' then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.goods_payment_attempt_json(v_attempt)
    );
  end if;

  if v_attempt.state is distinct from 'prepared'
    or v_attempt.expires_at <= pg_catalog.clock_timestamp()
  then
    raise object_not_in_prerequisite_state using message = 'goods_payment_attempt_expired';
  end if;

  -- All goods transitions lock order before attempt. This matches prepare,
  -- cancellation, and expiry ordering and avoids an order/attempt deadlock.
  select order_record.*
  into v_order
  from public.orders as order_record
  where order_record.id = v_attempt.ref_id
  for update;

  if not found then
    raise no_data_found using message = 'goods_order_not_found';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.provider = p_provider
    and attempt.provider_order_id = p_provider_order_id
    and attempt.purpose = 'order'
  for update;

  if not found
    or v_attempt.callback_nonce_digest is null
    or v_attempt.callback_nonce_digest is distinct from p_callback_nonce_digest
  then
    raise no_data_found using message = 'goods_payment_callback_invalid';
  end if;

  if v_attempt.state in ('approved', 'declined', 'canceled', 'unknown', 'needs_review') then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.goods_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;

  if v_attempt.state = 'confirming' then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.goods_payment_attempt_json(v_attempt)
    );
  end if;

  if v_attempt.state is distinct from 'prepared'
    or v_attempt.expires_at <= pg_catalog.clock_timestamp()
  then
    raise object_not_in_prerequisite_state using message = 'goods_payment_attempt_expired';
  end if;

  if v_order.user_id is distinct from v_attempt.user_id
    or v_order.status is distinct from 'pending'
    or v_order.expires_at is null
    or v_order.expires_at <= pg_catalog.clock_timestamp()
    or v_order.total is distinct from v_attempt.amount
    or v_attempt.currency is distinct from 'KRW'
    or private.is_account_write_fenced(v_attempt.user_id)
    or exists (
      select 1
      from public.profiles as profile
      where profile.id = v_attempt.user_id
        and profile.suspended_at is not null
    )
    or not private.goods_order_snapshot_matches(
      v_order.id,
      v_order.total,
      v_order.shipping_fee
    )
    or exists (
      select 1
      from public.order_cancellation_requests as request
      where request.order_id = v_order.id
        and request.status in ('requested', 'processing', 'needs_review')
    )
    or exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'order'
        and payment.ref_id = v_order.id
        and payment.status in ('pending', 'paid')
    )
  then
    raise object_not_in_prerequisite_state using message = 'goods_order_not_payable';
  end if;

  update public.payment_attempts
  set
    state = 'confirming',
    claim_token = p_claim_token,
    claim_expires_at = pg_catalog.clock_timestamp() + interval '10 minutes'
  where id = v_attempt.id
  returning * into v_attempt;

  return pg_catalog.jsonb_build_object(
    'claim_status', 'claimed',
    'attempt', private.goods_payment_attempt_json(v_attempt)
  );
end;
$function$

revoke all on function public.prepare_goods_payment_attempt(
  uuid, uuid, public.payment_provider
) from public, anon, authenticated, service_role

grant execute on function public.prepare_goods_payment_attempt(
  uuid, uuid, public.payment_provider
) to service_role

revoke all on function public.claim_goods_payment_attempt(
  public.payment_provider, text, text, uuid
) from public, anon, authenticated, service_role

grant execute on function public.claim_goods_payment_attempt(
  public.payment_provider, text, text, uuid
) to service_role

create or replace function public.request_order_cancellation(
  p_order_id uuid,
  p_user_id uuid,
  p_reason text,
  p_reason_type text
)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_user_id uuid;
  v_status public.order_status;
  v_delivered_at timestamptz;
  v_request_id uuid;
  v_has_unresolved_attempt boolean;
begin
  if p_reason_type is null
    or p_reason_type not in ('change_of_mind', 'defect')
  then
    raise check_violation using message = 'invalid cancellation reason type';
  end if;

  -- Shared ordering invariant: order first, then every goods attempt in a
  -- deterministic order. Claim/finalize use the same ordering.
  select order_record.user_id, order_record.status, order_record.delivered_at
  into v_user_id, v_status, v_delivered_at
  from public.orders as order_record
  where order_record.id = p_order_id
  for update;

  if not found or p_user_id is null or v_user_id is distinct from p_user_id then
    return 'not_found';
  end if;

  perform attempt.id
  from public.payment_attempts as attempt
  where attempt.purpose = 'order'
    and attempt.ref_id = p_order_id
  order by attempt.id
  for update;

  select exists (
    select 1
    from public.payment_attempts as attempt
    where attempt.purpose = 'order'
      and attempt.ref_id = p_order_id
      and attempt.state in (
        'prepared',
        'confirming',
        'unknown',
        'needs_review',
        'approved'
      )
  )
  into v_has_unresolved_attempt;

  if v_status = 'canceled' then
    return 'already_canceled';
  end if;

  if v_status not in ('pending', 'paid', 'shipping', 'done') then
    return 'not_cancelable';
  end if;

  if p_reason is null
    or pg_catalog.btrim(p_reason) <> p_reason
    or pg_catalog.length(p_reason) not between 1 and 200
  then
    raise check_violation using message = 'invalid cancellation reason';
  end if;

  if public.order_withdrawal_deadline_passed(
    v_delivered_at,
    p_reason_type,
    pg_catalog.now()
  ) then
    return 'deadline_expired';
  end if;

  if exists (
    select 1
    from public.order_cancellation_requests as request
    where request.order_id = p_order_id
      and request.status in ('requested', 'processing', 'needs_review')
  ) then
    return 'already_requested';
  end if;

  insert into public.order_cancellation_requests (
    order_id,
    requested_by,
    reason,
    reason_type,
    status
  )
  values (
    p_order_id,
    p_user_id,
    p_reason,
    p_reason_type,
    'requested'
  )
  returning id into v_request_id;

  -- A provider result can no longer be inferred from a payment row alone.
  -- Preserve stock and the order until staff reconciliation resolves the
  -- attempt. Clearly terminal declined/canceled attempts may use the existing
  -- immediate cancellation path.
  if v_status = 'pending'
    and not v_has_unresolved_attempt
    and not exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'order'
        and payment.ref_id = p_order_id
    )
  then
    perform public.finalize_order_cancellation_with_provider_evidence(
      p_order_id,
      p_reason,
      array[]::text[]
    );

    update public.order_cancellation_requests as request
    set
      status = 'completed',
      completed_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
    where request.id = v_request_id;

    return 'completed';
  end if;

  return 'requested';
end;
$function$

revoke all on function private.record_ticket_reconciliation_audit(
  uuid, text, uuid, text, text, text, public.payment_attempt_state
) from public, anon, authenticated, service_role

-- An unpaid reservation no longer has placeholder ticket rows, so the admin
-- console's historical ticket guard cannot see it. Lock only the fields that
-- define the payable snapshot; capacity and the existing operational controls
-- keep their prior contract.
create function private.enforce_ticket_reservation_catalog_lock()
returns trigger
language plpgsql
set search_path = ''
as $function$
begin
  if (
    old.event_id is distinct from new.event_id
    or old.price is distinct from new.price
  ) and exists (
    select 1
    from public.ticket_order_reservations as reservation
    where reservation.ticket_type_id = old.id
  ) then
    raise check_violation using message = 'ticket_type_catalog_locked';
  end if;
  return new;
end;
$function$

-- New reservations hold capacity only. No ticket row exists until an approved
-- provider finalization creates it with a QR in the same transaction.
create or replace function public.reserve_tickets(
  p_user_id uuid,
  p_ticket_type_id uuid,
  p_qty integer,
  p_reservation_key uuid
)
returns uuid
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $function$
declare
  v_user uuid := p_user_id;
  v_event_id text;
  v_locked_event_id text;
  v_event_status text;
  v_capacity integer;
  v_sold integer;
  v_price integer;
  v_per_user_limit integer;
  v_sales_open_at timestamptz;
  v_existing_order public.ticket_orders%rowtype;
  v_existing_reservation public.ticket_order_reservations%rowtype;
  v_already_reserved bigint;
  v_order_id uuid;
begin
  if v_user is null then
    raise not_null_violation using message = 'user required';
  end if;

  perform private.assert_active_user(v_user);

  if not exists (
    select 1
    from public.profiles as profile
    join auth.users as auth_user on auth_user.id = profile.id
    where profile.id = v_user
      and nullif(btrim(coalesce(profile.email, auth_user.email)), '') is not null
      and nullif(btrim(profile.nickname), '') is not null
      and profile.birth_date is not null
      and profile.birth_date <= current_date
      and profile.onboarded_at is not null
      and profile.consents ->> 'terms' = 'true'
      and profile.consents ->> 'privacy' = 'true'
  ) or private.is_account_write_fenced(v_user) then
    raise insufficient_privilege using message = 'onboarding required';
  end if;

  if p_qty is null or p_qty < 1 then
    raise check_violation using message = 'quantity must be positive';
  end if;
  if p_reservation_key is null then
    raise not_null_violation using message = 'reservation key required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'ticket_reservation:' || v_user::text || ':' || p_reservation_key::text,
      0
    )
  );

  select ticket_order.*
  into v_existing_order
  from public.ticket_orders as ticket_order
  where ticket_order.user_id = v_user
    and ticket_order.reservation_key = p_reservation_key
  for share;

  if found then
    select reservation.*
    into v_existing_reservation
    from public.ticket_order_reservations as reservation
    where reservation.ticket_order_id = v_existing_order.id;

    if found
      and v_existing_reservation.ticket_type_id = p_ticket_type_id
      and v_existing_reservation.quantity = p_qty
    then
      return v_existing_order.id;
    end if;
    raise unique_violation using message = 'reservation conflict';
  end if;

  select ticket_type.event_id
  into v_event_id
  from public.ticket_types as ticket_type
  where ticket_type.id = p_ticket_type_id;
  if not found then
    raise no_data_found using message = 'ticket type not found';
  end if;

  select event_record.status
  into v_event_status
  from public.events as event_record
  where event_record.id = v_event_id
  for share of event_record;
  if not found then
    raise no_data_found using message = 'event not found';
  end if;

  select
    ticket_type.event_id,
    ticket_type.capacity,
    ticket_type.sold,
    ticket_type.price,
    ticket_type.per_user_limit,
    ticket_type.sales_open_at
  into
    v_locked_event_id,
    v_capacity,
    v_sold,
    v_price,
    v_per_user_limit,
    v_sales_open_at
  from public.ticket_types as ticket_type
  where ticket_type.id = p_ticket_type_id
  for update of ticket_type;

  if not found then
    raise no_data_found using message = 'ticket type not found';
  end if;
  if v_locked_event_id is distinct from v_event_id then
    raise serialization_failure using message = 'ticket type changed';
  end if;
  if v_event_status <> '예매중' then
    raise check_violation using message = 'event not bookable';
  end if;
  if v_price <= 0 then
    raise check_violation using message = 'paid ticket required';
  end if;
  if v_sales_open_at is not null and now() < v_sales_open_at then
    raise check_violation using message = 'sales not open';
  end if;
  if p_qty::bigint > v_capacity::bigint - v_sold::bigint then
    raise check_violation using message = 'sold out';
  end if;

  select coalesce(sum(reservation.quantity), 0)
  into v_already_reserved
  from public.ticket_order_reservations as reservation
  join public.ticket_orders as ticket_order
    on ticket_order.id = reservation.ticket_order_id
  where reservation.ticket_type_id = p_ticket_type_id
    and ticket_order.user_id = v_user
    and ticket_order.status <> 'canceled';

  if v_already_reserved + p_qty::bigint > v_per_user_limit::bigint then
    raise check_violation using message = 'per-user limit exceeded';
  end if;

  update public.ticket_types
  set sold = sold + p_qty
  where id = p_ticket_type_id;

  insert into public.ticket_orders (
    user_id,
    event_id,
    status,
    total,
    expires_at,
    reservation_key
  )
  values (
    v_user,
    v_event_id,
    'pending',
    v_price::bigint * p_qty::bigint,
    now() + interval '10 minutes',
    p_reservation_key
  )
  returning id into v_order_id;

  insert into public.ticket_order_reservations (
    ticket_order_id,
    ticket_type_id,
    quantity,
    unit_price
  )
  values (v_order_id, p_ticket_type_id, p_qty, v_price);

  return v_order_id;
end;
$function$

create function public.bind_ticket_payment_callback_nonce(
  p_attempt_id uuid,
  p_callback_nonce_digest text
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_attempt public.payment_attempts%rowtype;
begin
  if p_attempt_id is null
    or p_callback_nonce_digest is null
    or p_callback_nonce_digest !~ '^[0-9a-f]{64}$'
  then
    raise invalid_parameter_value using message = 'ticket_payment_nonce_invalid';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.purpose = 'ticket'
  for update;

  if not found or v_attempt.provider is distinct from 'korpay' then
    raise no_data_found using message = 'ticket_payment_attempt_not_found';
  end if;
  if v_attempt.state is distinct from 'prepared'
    or v_attempt.expires_at <= pg_catalog.clock_timestamp()
  then
    raise object_not_in_prerequisite_state using message = 'ticket_payment_attempt_not_preparable';
  end if;

  if v_attempt.callback_nonce_digest is null then
    update public.payment_attempts
    set callback_nonce_digest = p_callback_nonce_digest
    where id = v_attempt.id;
  elsif v_attempt.callback_nonce_digest is distinct from p_callback_nonce_digest then
    raise unique_violation using message = 'ticket_payment_nonce_conflict';
  end if;
end;
$function$

create function public.claim_ticket_payment_attempt(
  p_provider public.payment_provider,
  p_provider_order_id text,
  p_callback_nonce_digest text,
  p_claim_token uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_attempt public.payment_attempts%rowtype;
  v_order public.ticket_orders%rowtype;
begin
  if p_provider is distinct from 'korpay'
    or p_provider_order_id is null
    or pg_catalog.length(p_provider_order_id) not between 1 and 200
    or p_callback_nonce_digest is null
    or p_callback_nonce_digest !~ '^[0-9a-f]{64}$'
    or p_claim_token is null
  then
    raise invalid_parameter_value using message = 'ticket_payment_callback_invalid';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.provider = p_provider
    and attempt.provider_order_id = p_provider_order_id
    and attempt.purpose = 'ticket';

  if not found
    or v_attempt.callback_nonce_digest is null
    or v_attempt.callback_nonce_digest is distinct from p_callback_nonce_digest
  then
    raise no_data_found using message = 'ticket_payment_callback_invalid';
  end if;

  if v_attempt.state in ('approved', 'declined', 'canceled', 'unknown', 'needs_review') then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;
  if v_attempt.state = 'confirming' then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;

  select ticket_order.*
  into v_order
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_attempt.ref_id
  for update;
  if not found then
    raise no_data_found using message = 'ticket_order_not_found';
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = v_order.id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;
  -- A cancellation may race an already-created provider session. Keep the
  -- request fenced, but still learn provider truth for this known order+nonce.
  -- The finalizer records approval without issuing QR and makes it refund-ready.

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.provider = p_provider
    and attempt.provider_order_id = p_provider_order_id
    and attempt.purpose = 'ticket'
  for update;

  if not found
    or v_attempt.callback_nonce_digest is null
    or v_attempt.callback_nonce_digest is distinct from p_callback_nonce_digest
  then
    raise no_data_found using message = 'ticket_payment_callback_invalid';
  end if;
  if v_attempt.state in ('approved', 'declined', 'canceled', 'unknown', 'needs_review') then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;
  if v_attempt.state = 'confirming' then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;

  if v_attempt.state is distinct from 'prepared'
    or v_attempt.expires_at <= pg_catalog.clock_timestamp()
    or v_order.user_id is distinct from v_attempt.user_id
    or v_order.status is distinct from 'pending'
    or v_order.expires_at is null
    or v_order.expires_at <= pg_catalog.clock_timestamp()
    or v_order.total is distinct from v_attempt.amount
    or v_attempt.currency is distinct from 'KRW'
    or private.is_account_write_fenced(v_attempt.user_id)
    or exists (
      select 1 from public.profiles as profile
      where profile.id = v_attempt.user_id and profile.suspended_at is not null
    )
    or not private.ticket_order_snapshot_matches(
      v_order.id,
      v_order.event_id,
      v_order.total
    )
    or exists (
      select 1 from public.tickets as ticket
      where ticket.ticket_order_id = v_order.id
    )
    or exists (
      select 1 from public.payments as payment
      where payment.purpose = 'ticket'
        and payment.ref_id = v_order.id
        and payment.status in ('pending', 'paid')
    )
  then
    raise object_not_in_prerequisite_state using message = 'ticket_order_not_payable';
  end if;

  update public.payment_attempts
  set
    state = 'confirming',
    claim_token = p_claim_token,
    claim_expires_at = pg_catalog.clock_timestamp() + interval '10 minutes'
  where id = v_attempt.id
  returning * into v_attempt;

  return pg_catalog.jsonb_build_object(
    'claim_status', 'claimed',
    'attempt', private.ticket_payment_attempt_json(v_attempt)
  );
end;
$function$

-- Explicit staff reconciliation reclaims only ambiguous attempts (or a stale
-- confirming claim). It never scans or retries automatically: an authorized
-- service caller must name the attempt after reviewing the operational case.
create function public.claim_ticket_payment_reconciliation(
  p_attempt_id uuid,
  p_claim_token uuid,
  p_case_ref text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_attempt public.payment_attempts%rowtype;
  v_order public.ticket_orders%rowtype;
begin
  if p_attempt_id is null
    or p_claim_token is null
    or p_case_ref is null
    or p_case_ref !~ '^[A-Za-z0-9_-]{16,128}$'
  then
    raise invalid_parameter_value using message = 'ticket_reconciliation_claim_invalid';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.purpose = 'ticket'
    and attempt.provider = 'korpay';
  if not found then
    raise no_data_found using message = 'ticket_payment_attempt_not_found';
  end if;

  if v_attempt.state in ('approved', 'declined', 'canceled') then
    perform private.record_ticket_reconciliation_audit(
      p_claim_token,
      'payment',
      p_attempt_id,
      'payment_reconciliation_service_v1',
      p_case_ref,
      'terminal',
      v_attempt.state
    );
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;
  if v_attempt.state = 'confirming'
    and v_attempt.claim_expires_at is not null
    and v_attempt.claim_expires_at > pg_catalog.clock_timestamp()
  then
    perform private.record_ticket_reconciliation_audit(
      p_claim_token,
      'payment',
      p_attempt_id,
      'payment_reconciliation_service_v1',
      p_case_ref,
      'in_progress'
    );
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;

  select ticket_order.*
  into v_order
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_attempt.ref_id
  for update;
  if not found then
    raise no_data_found using message = 'ticket_order_not_found';
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = v_order.id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.purpose = 'ticket'
    and attempt.provider = 'korpay'
  for update;
  if not found then
    raise no_data_found using message = 'ticket_payment_attempt_not_found';
  end if;

  if v_attempt.state in ('approved', 'declined', 'canceled') then
    perform private.record_ticket_reconciliation_audit(
      p_claim_token,
      'payment',
      p_attempt_id,
      'payment_reconciliation_service_v1',
      p_case_ref,
      'terminal',
      v_attempt.state
    );
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;
  if v_attempt.state = 'confirming'
    and v_attempt.claim_expires_at is not null
    and v_attempt.claim_expires_at > pg_catalog.clock_timestamp()
  then
    perform private.record_ticket_reconciliation_audit(
      p_claim_token,
      'payment',
      p_attempt_id,
      'payment_reconciliation_service_v1',
      p_case_ref,
      'in_progress'
    );
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;
  if v_attempt.state not in ('unknown', 'needs_review', 'confirming') then
    raise object_not_in_prerequisite_state using message = 'ticket_payment_not_reconcilable';
  end if;

  update public.payment_attempts
  set
    state = 'confirming',
    claim_token = p_claim_token,
    claim_expires_at = pg_catalog.clock_timestamp() + interval '10 minutes'
  where id = v_attempt.id
  returning * into v_attempt;

  perform private.record_ticket_reconciliation_audit(
    p_claim_token,
    'payment',
    p_attempt_id,
    'payment_reconciliation_service_v1',
    p_case_ref,
    'claimed'
  );

  return pg_catalog.jsonb_build_object(
    'claim_status', 'claimed',
    'attempt', private.ticket_payment_attempt_json(v_attempt)
  );
end;
$function$

create function public.claim_ticket_payment_refund(
  p_request_id uuid,
  p_user_id uuid,
  p_claim_token uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_order public.ticket_orders%rowtype;
  v_request public.ticket_cancellation_requests%rowtype;
  v_attempt public.payment_attempts%rowtype;
begin
  if p_request_id is null or p_user_id is null or p_claim_token is null then
    raise invalid_parameter_value using message = 'ticket_refund_claim_invalid';
  end if;

  select ticket_order.*
  into v_order
  from public.ticket_orders as ticket_order
  join public.ticket_cancellation_requests as request
    on request.ticket_order_id = ticket_order.id
  where request.id = p_request_id
  for update of ticket_order;
  if not found or v_order.user_id is distinct from p_user_id then
    raise no_data_found using message = 'ticket_refund_not_found';
  end if;

  select request.*
  into v_request
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id
    and request.ticket_order_id = v_order.id
    and request.requested_by = p_user_id
  for update;
  if not found then
    raise no_data_found using message = 'ticket_refund_not_found';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'ticket'
    and attempt.ref_id = v_order.id
  for update;

  if not found or v_attempt.provider is distinct from 'korpay' then
    return pg_catalog.jsonb_build_object('claim_status', 'legacy');
  end if;

  if v_request.status = 'completed' then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', 'approved'
    );
  end if;
  if v_request.status = 'needs_review' then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', 'needs_review'
    );
  end if;
  if v_attempt.state = 'prepared' then
    -- A provider session exists but no callback truth does. Do not call refund
    -- or release capacity; callback drain or authoritative attempt TTL must win.
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;
  if v_request.status = 'processing'
    and v_request.attempt_token is distinct from p_claim_token
    and v_request.attempt_token is not null
    and v_request.provider_started_at > pg_catalog.clock_timestamp() - interval '5 minutes'
  then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order.id
  order by ticket.id
  for update of ticket;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  join public.ticket_order_reservations as reservation
    on reservation.ticket_type_id = ticket_type.id
  where reservation.ticket_order_id = v_order.id
  for update of ticket_type;

  if v_request.status not in ('requested', 'processing')
    or v_order.status is distinct from 'paid'
    or v_attempt.state is distinct from 'approved'
    or v_attempt.payment_id is null
    or not exists (
      select 1
      from public.payments as payment
      where payment.id = v_attempt.payment_id
        and payment.provider = v_attempt.provider
        and payment.purpose = 'ticket'
        and payment.ref_id = v_order.id
        and payment.user_id = p_user_id
        and payment.amount = v_order.total
        and payment.status = 'paid'
    )
    or not exists (
      select 1 from public.tickets as ticket
      where ticket.ticket_order_id = v_order.id
    )
    or exists (
      select 1 from public.tickets as ticket
      where ticket.ticket_order_id = v_order.id
        and ticket.status <> 'valid'
    )
  then
    update public.ticket_cancellation_requests
    set
      status = 'needs_review',
      attempt_token = null,
      last_error_code = 'payment_not_refundable'
    where id = v_request.id;

    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', 'needs_review'
    );
  end if;

  update public.ticket_cancellation_requests
  set
    status = 'processing',
    attempt_token = p_claim_token,
    provider_started_at = pg_catalog.clock_timestamp(),
    last_error_code = null
  where id = v_request.id;

  return pg_catalog.jsonb_build_object(
    'claim_status', 'claimed',
    'attempt', private.ticket_payment_attempt_json(v_attempt)
  );
end;
$function$

-- Cancellation keeps the same global lock order and consumes the explicit
-- reservation snapshot for both legacy and provider-neutral ticket orders.
create or replace function public.finalize_ticket_cancellation_request(
  p_request_id uuid,
  p_actor_id uuid
)
returns text
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $function$
declare
  v_order_id uuid;
  v_order_status public.ticket_order_status;
  v_request_status text;
  v_request_source text;
  v_reservation public.ticket_order_reservations%rowtype;
  v_refund_count integer;
begin
  select request.ticket_order_id
  into v_order_id
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id;
  if v_order_id is null then
    raise no_data_found using message = 'ticket cancellation request not found';
  end if;

  select ticket_order.status
  into v_order_status
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;
  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;

  select request.status, request.source
  into v_request_status, v_request_source
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id
  for update of request;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket' and payment.ref_id = v_order_id
  order by payment.id
  for update of payment;

  perform attempt.id
  from public.payment_attempts as attempt
  where attempt.purpose = 'ticket' and attempt.ref_id = v_order_id
  order by attempt.id
  for update of attempt;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order_id
  order by ticket.id
  for update of ticket;

  select reservation.*
  into v_reservation
  from public.ticket_order_reservations as reservation
  where reservation.ticket_order_id = v_order_id
  for update;
  if not found then
    raise check_violation using message = 'ticket reservation missing';
  end if;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id = v_reservation.ticket_type_id
  for update of ticket_type;

  if v_request_status = 'completed' then
    return 'completed';
  end if;
  if v_order_status = 'canceled' then
    update public.ticket_cancellation_requests
    set
      status = 'completed',
      attempt_token = null,
      completed_at = coalesce(completed_at, now()),
      last_error_code = null
    where id = p_request_id;
    return 'completed';
  end if;
  if v_order_status not in ('pending', 'paid') then
    raise check_violation using message = 'ticket order not cancelable';
  end if;

  if exists (
    select 1 from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = v_order_id
      and payment.status in ('pending', 'paid')
  ) or exists (
    select 1 from public.payment_attempts as attempt
    where attempt.purpose = 'ticket'
      and attempt.ref_id = v_order_id
      and attempt.state in ('prepared', 'confirming', 'approved', 'unknown', 'needs_review')
  ) then
    return 'processing';
  end if;

  if v_order_status = 'paid' and not exists (
    select 1
    from public.payments as payment
    join public.refunds as refund on refund.payment_id = payment.id
    where payment.purpose = 'ticket'
      and payment.ref_id = v_order_id
      and payment.status = 'refunded'
      and refund.status = 'done'
  ) then
    raise check_violation using message = 'payment evidence required';
  end if;

  if exists (
    select 1 from public.tickets as ticket
    where ticket.ticket_order_id = v_order_id and ticket.status = 'used'
  ) then
    update public.ticket_cancellation_requests
    set
      status = 'needs_review',
      attempt_token = null,
      last_error_code = 'used_ticket_after_provider_cancellation'
    where id = p_request_id;
    return 'needs_review';
  end if;

  update public.payment_attempts
  set
    state = 'canceled',
    claim_token = null,
    claim_expires_at = null
  where purpose = 'ticket'
    and ref_id = v_order_id
    and state = 'prepared';

  update public.ticket_types
  set sold = sold - v_reservation.quantity
  where id = v_reservation.ticket_type_id;

  update public.tickets
  set status = 'refunded'
  where ticket_order_id = v_order_id;

  update public.ticket_orders
  set status = 'canceled', expires_at = null
  where id = v_order_id;

  update public.ticket_cancellation_requests
  set
    status = 'completed',
    attempt_token = null,
    completed_at = coalesce(completed_at, now()),
    last_error_code = null
  where id = p_request_id;

  select count(*)::integer
  into v_refund_count
  from public.refunds as refund
  where refund.ticket_cancellation_request_id = p_request_id
    and refund.status = 'done';

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_actor_id,
    'ticket.cancellation.completed',
    'ticket_order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'source', v_request_source,
      'to', 'completed',
      'refundCount', v_refund_count
    )
  );
  return 'completed';
end;
$function$

create or replace function public.request_ticket_cancellation(
  p_user_id uuid,
  p_ticket_order_id uuid
)
returns table (request_id uuid, result text)
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $function$
declare
  v_order_user_id uuid;
  v_order_status public.ticket_order_status;
  v_order_total bigint;
  v_event_id text;
  v_cutoff_at timestamptz;
  v_existing_request record;
  v_reservation public.ticket_order_reservations%rowtype;
begin
  select
    ticket_order.user_id,
    ticket_order.status,
    ticket_order.total,
    ticket_order.event_id
  into
    v_order_user_id,
    v_order_status,
    v_order_total,
    v_event_id
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;

  if not found or p_user_id is null or v_order_user_id is distinct from p_user_id then
    request_id := null;
    result := 'not_found';
    return next;
    return;
  end if;
  if v_order_status = 'canceled' then
    select request.id into request_id
    from public.ticket_cancellation_requests as request
    where request.ticket_order_id = p_ticket_order_id
      and request.status = 'completed'
    order by request.requested_at desc, request.id
    limit 1;
    result := case when request_id is null then 'already_canceled' else 'completed' end;
    return next;
    return;
  end if;
  if v_order_status not in ('pending', 'paid') then
    request_id := null;
    result := 'not_cancelable';
    return next;
    return;
  end if;

  select request.id, request.status
  into v_existing_request
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = p_ticket_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  limit 1
  for update of request;
  if found then
    request_id := v_existing_request.id;
    result := v_existing_request.status;
    return next;
    return;
  end if;

  select event_record.starts_at
  into v_cutoff_at
  from public.events as event_record
  where event_record.id = v_event_id
  for share of event_record;
  if v_cutoff_at is null or now() >= v_cutoff_at then
    request_id := null;
    result := 'policy_closed';
    return next;
    return;
  end if;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket' and payment.ref_id = p_ticket_order_id
  order by payment.id
  for update of payment;

  perform attempt.id
  from public.payment_attempts as attempt
  where attempt.purpose = 'ticket' and attempt.ref_id = p_ticket_order_id
  order by attempt.id
  for update of attempt;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = p_ticket_order_id
  order by ticket.id
  for update of ticket;

  select reservation.*
  into v_reservation
  from public.ticket_order_reservations as reservation
  where reservation.ticket_order_id = p_ticket_order_id
  for update;
  if not found then
    request_id := null;
    result := 'not_cancelable';
    return next;
    return;
  end if;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id = v_reservation.ticket_type_id
  for update of ticket_type;

  if v_order_status = 'paid' and (
    not exists (
      select 1 from public.tickets as ticket
      where ticket.ticket_order_id = p_ticket_order_id
    )
    or exists (
      select 1 from public.tickets as ticket
      where ticket.ticket_order_id = p_ticket_order_id
        and ticket.status <> 'valid'
    )
  ) then
    request_id := null;
    result := 'not_cancelable';
    return next;
    return;
  end if;

  insert into public.ticket_cancellation_requests (
    ticket_order_id,
    requested_by,
    source,
    status,
    policy_code,
    cutoff_at,
    gross_amount,
    fee_amount,
    refund_amount,
    reason
  )
  values (
    p_ticket_order_id,
    p_user_id,
    'user',
    'requested',
    'event_start_full_refund_v1',
    v_cutoff_at,
    v_order_total,
    0,
    v_order_total,
    '사용자 예매 취소 요청'
  )
  returning id into request_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_user_id,
    'ticket.cancellation.requested',
    'ticket_order:' || p_ticket_order_id::text,
    jsonb_build_object(
      'requestId', request_id,
      'source', 'user',
      'policyCode', 'event_start_full_refund_v1',
      'to', 'requested'
    )
  );

  if v_order_status = 'pending'
    and not exists (
      select 1 from public.payments as payment
      where payment.purpose = 'ticket'
        and payment.ref_id = p_ticket_order_id
        and payment.status in ('pending', 'paid')
    )
    and not exists (
      select 1 from public.payment_attempts as attempt
      where attempt.purpose = 'ticket'
        and attempt.ref_id = p_ticket_order_id
        and attempt.state in ('prepared', 'confirming', 'approved', 'unknown', 'needs_review')
    )
  then
    result := public.finalize_ticket_cancellation_request(request_id, p_user_id);
  else
    result := 'requested';
  end if;
  return next;
end;
$function$

-- Expiry and no-payment cancellation use the same explicit capacity snapshot.
-- Any confirming or ambiguous attempt preserves the reservation for staff
-- reconciliation; only a prepared/declined/canceled attempt can be released.
create or replace function public.refund_ticket_order(
  p_ticket_order_id uuid,
  p_reason text
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $function$
declare
  v_order_status public.ticket_order_status;
  v_reservation public.ticket_order_reservations%rowtype;
begin
  -- Keep the legacy signature stable for callers while retaining the reason
  -- as an explicit input to this operational path.
  perform p_reason;

  select ticket_order.status
  into v_order_status
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;
  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;
  if v_order_status = 'canceled' then
    return;
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = p_ticket_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket' and payment.ref_id = p_ticket_order_id
  order by payment.id
  for update of payment;

  perform attempt.id
  from public.payment_attempts as attempt
  where attempt.purpose = 'ticket' and attempt.ref_id = p_ticket_order_id
  order by attempt.id
  for update of attempt;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = p_ticket_order_id
  order by ticket.id
  for update of ticket;

  select reservation.*
  into v_reservation
  from public.ticket_order_reservations as reservation
  where reservation.ticket_order_id = p_ticket_order_id
  for update;
  if not found then
    raise check_violation using message = 'ticket reservation missing';
  end if;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id = v_reservation.ticket_type_id
  for update of ticket_type;

  if v_order_status <> 'pending' then
    raise check_violation using message = 'payment evidence required';
  end if;
  if exists (
    select 1 from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = p_ticket_order_id
      and payment.status in ('pending', 'paid')
  ) then
    raise check_violation using message = 'provider cancellation required';
  end if;
  if exists (
    select 1 from public.payment_attempts as attempt
    where attempt.purpose = 'ticket'
      and attempt.ref_id = p_ticket_order_id
      and attempt.state in ('confirming', 'approved', 'unknown', 'needs_review')
  ) then
    raise check_violation using message = 'provider reconciliation required';
  end if;

  update public.payment_attempts
  set
    state = 'canceled',
    claim_token = null,
    claim_expires_at = null
  where purpose = 'ticket'
    and ref_id = p_ticket_order_id
    and state = 'prepared';

  update public.ticket_types
  set sold = sold - v_reservation.quantity
  where id = v_reservation.ticket_type_id;

  update public.tickets
  set status = 'refunded'
  where ticket_order_id = p_ticket_order_id;

  update public.ticket_orders
  set status = 'canceled', expires_at = null
  where id = p_ticket_order_id;
end;
$function$

create or replace function public.expire_stale_checkouts()
returns integer
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $function$
declare
  v_count integer := 0;
  v_can_expire boolean;
  v_expired_prepared_transitioned boolean;
  v_cancel_reason text;
  v_request_id uuid;
  r record;
  v_request record;
  v_attempt public.payment_attempts%rowtype;
begin
  for r in
    select orders.id
    from public.orders
    where orders.status = 'pending'
      and orders.expires_at is not null
      and orders.expires_at < now() - interval '5 minutes'
      and not exists (
        select 1
        from public.payments as payment
        where payment.purpose = 'order'
          and payment.ref_id = orders.id
          and payment.status in ('pending', 'paid')
      )
      and not exists (
        select 1
        from public.order_cancellation_requests as request
        where request.order_id = orders.id
          and request.status in ('processing', 'needs_review')
      )
      and not exists (
        select 1
        from public.payment_attempts as attempt
        where attempt.purpose = 'order'
          and attempt.ref_id = orders.id
          and attempt.state in ('confirming', 'unknown', 'needs_review', 'approved')
      )
    order by orders.expires_at
    limit 200
    for update of orders skip locked
  loop
    v_can_expire := true;
    v_expired_prepared_transitioned := false;
    v_cancel_reason := '결제 시간 만료 자동 취소';
    v_request_id := null;

    -- The baseline partial unique index guarantees one attempt per goods
    -- order. Locking it only after the order matches claim/finalize exactly.
    select attempt.*
    into v_attempt
    from public.payment_attempts as attempt
    where attempt.purpose = 'order'
      and attempt.ref_id = r.id
    for update;

    if found then
      if v_attempt.state = 'prepared' then
        if v_attempt.expires_at > pg_catalog.clock_timestamp() then
          v_can_expire := false;
        else
          update public.payment_attempts as attempt
          set
            state = 'canceled',
            claim_token = null,
            claim_expires_at = null
          where attempt.id = v_attempt.id
            and attempt.state = 'prepared'
            and attempt.expires_at <= pg_catalog.clock_timestamp()
          returning true into v_expired_prepared_transitioned;

          if not coalesce(v_expired_prepared_transitioned, false) then
            v_can_expire := false;
          end if;
        end if;
      elsif v_attempt.state in (
        'confirming',
        'unknown',
        'needs_review',
        'approved'
      ) then
        -- Defensive recheck after locking: a callback may have won after the
        -- candidate snapshot but before this transaction acquired the order.
        v_can_expire := false;
      end if;
    end if;

    if not v_can_expire then
      continue;
    end if;

    -- A user can request cancellation while the provider action is still
    -- valid. That request intentionally holds inventory until the attempt TTL
    -- proves the provider can no longer claim it. Lock and finish that durable
    -- request in this same transaction; the compatibility cancel_order wrapper
    -- correctly rejects active requests and therefore is used only when none
    -- exists.
    select request.id, request.reason
    into v_request
    from public.order_cancellation_requests as request
    where request.order_id = r.id
      and request.status = 'requested'
    order by request.requested_at desc, request.id desc
    limit 1
    for update;

    if found then
      -- A durable request is provider-sensitive evidence. Close it only when
      -- this exact order→attempt critical section proved the action TTL and
      -- performed prepared→canceled itself. An absent, previously terminal,
      -- or legacy failed-ledger attempt is not proof that cancellation is safe.
      if not v_expired_prepared_transitioned then
        continue;
      end if;

      v_request_id := v_request.id;
      v_cancel_reason := v_request.reason;
    end if;

    if v_request_id is null then
      perform public.cancel_order(r.id, v_cancel_reason);
    else
      perform public.finalize_order_cancellation_with_provider_evidence(
        r.id,
        v_cancel_reason,
        array[]::text[]
      );

      update public.order_cancellation_requests as request
      set
        status = 'completed',
        completed_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
      where request.id = v_request_id
        and request.status = 'requested';
    end if;

    v_count := v_count + 1;
  end loop;

  -- Ticket checkout follows the same lock order and attempt-TTL proof. A
  -- durable cancellation request is completed only when this critical section
  -- itself transitions its expired prepared attempt to canceled.
  for r in
    select ticket_orders.id
    from public.ticket_orders
    where ticket_orders.status = 'pending'
      and ticket_orders.expires_at is not null
      and ticket_orders.expires_at < now() - interval '5 minutes'
      and not exists (
        select 1 from public.payments as payment
        where payment.purpose = 'ticket'
          and payment.ref_id = ticket_orders.id
          and payment.status in ('pending', 'paid')
      )
      and not exists (
        select 1 from public.ticket_cancellation_requests as request
        where request.ticket_order_id = ticket_orders.id
          and request.status in ('processing', 'needs_review')
      )
      and not exists (
        select 1 from public.payment_attempts as attempt
        where attempt.purpose = 'ticket'
          and attempt.ref_id = ticket_orders.id
          and attempt.state in ('confirming', 'unknown', 'needs_review', 'approved')
      )
    order by ticket_orders.expires_at
    limit 200
    for update of ticket_orders skip locked
  loop
    v_can_expire := true;
    v_expired_prepared_transitioned := false;
    v_request_id := null;

    select attempt.*
    into v_attempt
    from public.payment_attempts as attempt
    where attempt.purpose = 'ticket'
      and attempt.ref_id = r.id
    for update;

    if found then
      if v_attempt.state = 'prepared' then
        if v_attempt.expires_at > pg_catalog.clock_timestamp() then
          v_can_expire := false;
        else
          update public.payment_attempts as attempt
          set
            state = 'canceled',
            claim_token = null,
            claim_expires_at = null
          where attempt.id = v_attempt.id
            and attempt.state = 'prepared'
            and attempt.expires_at <= pg_catalog.clock_timestamp()
          returning true into v_expired_prepared_transitioned;

          if not coalesce(v_expired_prepared_transitioned, false) then
            v_can_expire := false;
          end if;
        end if;
      elsif v_attempt.state in (
        'confirming',
        'unknown',
        'needs_review',
        'approved'
      ) then
        v_can_expire := false;
      end if;
    end if;

    if not v_can_expire then
      continue;
    end if;

    select request.id, request.requested_by
    into v_request
    from public.ticket_cancellation_requests as request
    where request.ticket_order_id = r.id
      and request.status = 'requested'
    order by request.requested_at desc, request.id desc
    limit 1
    for update;

    if found then
      if not v_expired_prepared_transitioned then
        continue;
      end if;

      v_request_id := v_request.id;
    end if;

    if v_request_id is null then
      perform public.refund_ticket_order(r.id, '결제 시간 만료 자동 취소');
    else
      perform public.finalize_ticket_cancellation_request(
        v_request_id,
        v_request.requested_by
      );
    end if;

    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$

