create function public.recover_email_acceptance_persistence_failure(
  target_intent_id uuid,
  target_claim_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_intent private.email_intents%rowtype;
begin
  if target_intent_id is null or target_claim_id is null then
    raise check_violation using message = 'invalid_email_dispatch_recovery_claim';
  end if;

  select * into v_intent
  from private.email_intents as intent
  where intent.id = target_intent_id
  for update;
  if not found then raise no_data_found using message = 'email_intent_not_found'; end if;

  if v_intent.state = 'dispatching'
    and v_intent.dispatch_claim_id = target_claim_id
  then
    update private.email_intents set
      state = 'unknown',
      dispatch_claim_id = null,
      updated_at = pg_catalog.now()
    where id = v_intent.id
    returning * into v_intent;
    return pg_catalog.jsonb_build_object('kind', 'released', 'state', 'unknown');
  end if;

  return pg_catalog.jsonb_build_object('kind', 'preserved', 'state', v_intent.state);
end;
$$

-- Korpay's published card flow rejects amounts below KRW 1,000. Enforce the
-- bound inside the same reservation transaction so capacity is never held for
-- an order that the configured provider cannot prepare.

create or replace function private.enforce_korpay_ticket_minimum_amount()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.status = 'pending' and new.total > 0 and new.total < 1000 then
    raise check_violation using message = 'payment amount below provider minimum';
  end if;
  if new.status = 'pending' and new.total > 999999999999 then
    raise check_violation using message = 'payment amount above provider maximum';
  end if;
  return new;
end;
$$

-- place_order creates its pending shell at total=0 and then calculates the
-- authoritative total while inventory/cart rows are locked. Reject the final
-- update, not the shell insert, so an unpayable zero-total cart rolls back the
-- whole reservation transaction.
create or replace function private.enforce_korpay_goods_minimum_amount()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.status = 'pending' and new.total < 1000 then
    raise check_violation using message = 'payment amount below provider minimum';
  end if;
  if new.status = 'pending' and new.total > 999999999999 then
    raise check_violation using message = 'payment amount above provider maximum';
  end if;
  return new;
end;
$$

