security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := (select auth.uid());
  v_current_status public.order_status;
  v_current_carrier text;
  v_current_tracking text;
  v_carrier text := nullif(btrim(coalesce(p_carrier, '')), '');
  v_tracking text := nullif(btrim(coalesce(p_tracking_number, '')), '');
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if v_carrier is null or v_tracking is null then
    raise check_violation using message = 'tracking_required';
  end if;

  select orders.status, orders.shipping_carrier, orders.tracking_number
  into v_current_status, v_current_carrier, v_current_tracking
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise no_data_found using message = 'order_not_found';
  end if;

  -- 출고 전 주문에는 운송장이 없다. 배송이 시작된 주문만 정정 대상이다.
  if v_current_status not in ('shipping', 'delivered', 'done') then
    raise check_violation using message = 'order_not_shipped';
  end if;

  if v_current_carrier is not distinct from v_carrier
    and v_current_tracking is not distinct from v_tracking
  then
    return;
  end if;

  -- 정정으로 택배사를 바꾸는 경우도 활성 택배사여야 한다.
  if v_carrier is distinct from v_current_carrier then
    if not exists (
      select 1
      from public.shipping_carriers as carrier
      where carrier.code = v_carrier
        and carrier.is_active
    ) then
      raise check_violation using message = 'inactive_shipping_carrier';
    end if;
  end if;

  update public.orders
  set
    shipping_carrier = v_carrier,
    tracking_number = v_tracking
  where id = p_order_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.tracking_updated',
    'order:' || p_order_id::text,
    jsonb_build_object(
      'fromCarrier', v_current_carrier,
      'fromTrackingNumber', v_current_tracking,
      'toCarrier', v_carrier,
      'toTrackingNumber', v_tracking
    )
  );
end;
$$

create trigger order_dispatch_delays_touch
  before update on public.order_dispatch_delays
  for each row execute function public.set_updated_at()

-- ---------------------------------------------------------------------------
-- 2. 메모 등록·해제
-- ---------------------------------------------------------------------------
-- 사유를 비워 부르면 메모를 지운다. "지연이 풀렸다"를 표현할 방법이 없으면
-- 운영자는 사유를 '해결'로 덮어쓰고, 그러면 지연 목록이 영원히 줄지 않는다.
create or replace function public.admin_upsert_order_dispatch_delay(
  p_order_id uuid,
  p_reason text,
  p_expected_ship_date date
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := (select auth.uid());
  v_status public.order_status;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff required';
  end if;

  select orders.status into v_status
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise no_data_found using message = 'order_not_found';
  end if;

  -- 발송 전 주문에만 붙는 메모다. 이미 나간 주문의 "지연 사유"는 기록이 아니라 혼선이다.
  if v_status not in ('paid', 'confirmed') then
    raise check_violation using message = 'order_already_dispatched';
  end if;

  if v_reason is null then
    delete from public.order_dispatch_delays where order_id = p_order_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_actor,
      'admin.order.dispatch_delay_cleared',
      'order:' || p_order_id::text,
      jsonb_build_object('status', v_status::text)
    );
    return;
  end if;

  insert into public.order_dispatch_delays (order_id, reason, expected_ship_date, noted_by)
  values (p_order_id, v_reason, p_expected_ship_date, v_actor)
  on conflict (order_id) do update set
    reason = excluded.reason,
    expected_ship_date = excluded.expected_ship_date,
    noted_by = excluded.noted_by;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.dispatch_delay_noted',
    'order:' || p_order_id::text,
    jsonb_build_object(
      'reason', v_reason,
      'expectedShipDate', p_expected_ship_date,
      'status', v_status::text
    )
  );
end;
$$

