-- 첨부 경로가 호출자 소유인지. CHECK는 형식만 보고, 소유는 여기서 본다 —
-- 형식만 맞으면 남의 uuid 폴더를 가리키는 경로도 통과하기 때문이다.
create function private.assert_own_review_image_paths(
  target_paths text[],
  target_owner uuid
)
returns text[]
language plpgsql
immutable
security invoker
set search_path = ''
as $$
declare
  normalized text[] := coalesce(target_paths, '{}'::text[]);
begin
  if pg_catalog.cardinality(normalized) > 5 then
    raise check_violation using message = 'review_image_limit';
  end if;

  if exists (
    select 1
    from pg_catalog.unnest(normalized) as entry(path)
    where entry.path is null
      or pg_catalog.left(entry.path, pg_catalog.char_length(target_owner::text) + 8)
        <> target_owner::text || '/review/'
  ) then
    raise check_violation using message = 'invalid_review_image_path';
  end if;

  if not private.is_safe_review_image_paths(normalized) then
    raise check_violation using message = 'invalid_review_image_path';
  end if;

  return normalized;
end;
$$

-- ---------------------------------------------------------------------------
-- 7. 사용자 RPC
-- ---------------------------------------------------------------------------
-- 작성. 자격 판정이 전부 여기 있다 — 주문 소유 · 배송완료 이상 · 그 주문에
-- 실제로 담겼던 굿즈 · 90일 기한 · 주문×굿즈당 1회.
--
-- `delivered_at`이 비어 있으면 거절한다. 기산점을 모르는 주문에 기한을 지어내면
-- 90일이 아니라 무기한이 된다(#250은 기존 행을 백필하지 않았다).
create function public.create_good_review(
  target_order_id uuid,
  target_good_id text,
  target_rating integer,
  target_body text,
  target_image_paths text[] default '{}'
)
returns uuid
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := (select auth.uid());
  v_body text := btrim(coalesce(target_body, ''));
  v_paths text[];
  v_status text;
  v_delivered_at timestamptz;
  v_review_id uuid;
begin
  if v_actor is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_actor
      and profile.suspended_at is not null
  ) then
    raise insufficient_privilege using message = 'account_suspended';
  end if;

  if target_rating is null or target_rating not between 1 and 5 then
    raise invalid_parameter_value using message = 'invalid_review_rating';
  end if;
  if char_length(v_body) not between 5 and 1000 then
    raise invalid_parameter_value using message = 'invalid_review_body';
  end if;

  select target.status::text, target.delivered_at
    into v_status, v_delivered_at
  from public.orders as target
  where target.id = target_order_id
    and target.user_id = v_actor
  for share;

  if not found then
    raise no_data_found using message = 'review_order_not_found';
  end if;

  -- "delivered 이상"이 자격선이다(#250 사다리). done은 거래확정이라 당연히
  -- 포함하고, shipping까지 열면 받아 보지 않은 굿즈에 별점이 붙는다.
  if v_status not in ('delivered', 'done') then
    raise check_violation using message = 'review_order_not_delivered';
  end if;
  if v_delivered_at is null then
    raise check_violation using message = 'review_order_not_delivered';
  end if;

  if not exists (
    select 1
    from public.order_items as item
    where item.order_id = target_order_id
      and item.good_id = target_good_id
  ) then
    raise no_data_found using message = 'review_good_not_in_order';
  end if;

  if now() > private.review_write_deadline(v_delivered_at) then
    raise check_violation using message = 'review_window_closed';
  end if;

  v_paths := private.assert_own_review_image_paths(target_image_paths, v_actor);

  begin
    insert into public.reviews (user_id, good_id, order_id, rating, body, image_paths)
    values (v_actor, target_good_id, target_order_id, target_rating::smallint, v_body, v_paths)
    returning id into v_review_id;
  exception
    when unique_violation then
      raise unique_violation using message = 'review_already_exists';
  end;

  return v_review_id;
end;
$$

-- 작성자 수정 — 기한 안에서만. 블라인드된 리뷰는 수정 대상이 아니다:
-- 상태는 그대로 hidden이라 고쳐도 공개되지 않고, 운영자가 판단한 원문만
-- 사라져 블라인드 사유를 검증할 수 없게 된다.
create function public.update_good_review(
  target_review_id uuid,
  target_rating integer,
  target_body text,
  target_image_paths text[] default '{}'
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := (select auth.uid());
  v_body text := btrim(coalesce(target_body, ''));
  v_paths text[];
  v_status text;
  v_order_id uuid;
  v_delivered_at timestamptz;
begin
  if v_actor is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_actor
      and profile.suspended_at is not null
  ) then
    raise insufficient_privilege using message = 'account_suspended';
  end if;

  if target_rating is null or target_rating not between 1 and 5 then
    raise invalid_parameter_value using message = 'invalid_review_rating';
  end if;
  if char_length(v_body) not between 5 and 1000 then
    raise invalid_parameter_value using message = 'invalid_review_body';
  end if;

  select review.status, review.order_id
    into v_status, v_order_id
  from public.reviews as review
  where review.id = target_review_id
    and review.user_id = v_actor
  for update;

  if not found then
    raise no_data_found using message = 'review_not_found';
  end if;
  if v_status <> 'visible' then
    raise insufficient_privilege using message = 'review_hidden';
  end if;

  select target.delivered_at
    into v_delivered_at
  from public.orders as target
  where target.id = v_order_id;

  if v_delivered_at is null or now() > private.review_write_deadline(v_delivered_at) then
    raise check_violation using message = 'review_window_closed';
  end if;

  v_paths := private.assert_own_review_image_paths(target_image_paths, v_actor);

  update public.reviews
  set
    rating = target_rating::smallint,
    body = v_body,
    image_paths = v_paths,
    edited_at = now()
  where id = target_review_id;
end;
$$

-- 작성자 삭제 — 상시. 기한이 지난 뒤에도 자기 글을 내릴 수 있어야 한다.
-- 운영자 블라인드와 달리 행 자체가 사라지므로 평균·분포에서도 즉시 빠진다.
create function public.delete_good_review(target_review_id uuid)
returns text[]
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := (select auth.uid());
  v_paths text[];
begin
  if v_actor is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  delete from public.reviews
  where id = target_review_id
    and user_id = v_actor
  returning image_paths into v_paths;

  if not found then
    raise no_data_found using message = 'review_not_found';
  end if;

  -- 첨부 파일 정리는 호출자가 소유자 권한으로 한다. 여기서 지우려면 RPC가
  -- storage.objects 쓰기 권한을 가져야 하는데, 그 권한을 열면 이 함수 하나가
  -- 버킷 전체를 지울 수 있는 도구가 된다.
  return coalesce(v_paths, '{}'::text[]);
end;
$$

-- ---------------------------------------------------------------------------
-- 9. 신고 연동
-- ---------------------------------------------------------------------------
-- enum 값은 20260818130000이 먼저 커밋했다. 여기서는 접수 함수의 분기와
-- 숨김 가드의 대상 검증을 함께 넓힌다 — enum만 늘리면 'review' 신고를 접수할
-- 경로가 없고, 접수만 열면 그 신고가 엉뚱한 숨김 액션에 소비된다.
create or replace function public.submit_community_report(
  target_type public.report_target,
  target_id text,
  reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor_id uuid := auth.uid();
  target_uuid uuid;
  normalized_reason text := nullif(btrim(reason), '');
  target_ip_id text := null;
  target_post_id uuid;
  inserted_report_id uuid;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if target_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'target_not_found' using errcode = '22023';
  end if;

  target_uuid := target_id::uuid;

  if target_type = 'post' then
    select posts.ip_id
      into target_ip_id
      from public.posts
      where posts.id = target_uuid
        and posts.status = 'visible';

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  elsif target_type = 'comment' then
    select comments.post_id
      into target_post_id
      from public.comments
      where comments.id = target_uuid;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;

    select posts.ip_id
      into target_ip_id
      from public.posts
      where posts.id = target_post_id
        and posts.status = 'visible'
      for share;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;

    perform 1
    from public.comments
    where comments.id = target_uuid
      and comments.post_id = target_post_id
      and comments.status = 'visible'
    for share;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  elsif target_type = 'review' then
    -- 리뷰는 IP가 아니라 굿즈에 매인다. 반환값의 ipId는 커뮤니티 피드 갱신용
    -- 힌트라 리뷰에는 해당이 없다 — 굿즈의 IP를 넣어 주면 신고 한 번이 엉뚱한
    -- IP 피드를 다시 그리게 만든다. null로 둔다.
    perform 1
    from public.reviews
    where reviews.id = target_uuid
      and reviews.status = 'visible'
    for share;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  elsif target_type = 'user' then
    perform 1
    from public.profiles
    where profiles.id = target_uuid;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  else
    raise exception 'target_not_found' using errcode = '22023';
  end if;

  insert into public.reports (target_type, target_id, reporter_id, reason)
  values (target_type, target_uuid::text, actor_id, normalized_reason)
  returning id into inserted_report_id;

  return jsonb_build_object('reportId', inserted_report_id, 'ipId', target_ip_id);
end;
$$

-- 숨김 가드 — 신고 하나가 엉뚱한 대상의 숨김으로 소비되지 않게 한다.
-- 'review' 신고는 여기서 절대 종결되지 않는다. 리뷰의 처리 경로는
-- admin_set_review_status이고, 그 함수가 같은 방향의 검증을 대칭으로 한다.
-- 이 else 분기를 열어 두면 운영자가 리뷰 신고를 아무 포스트에 붙여 닫을 수 있다.
create or replace function public.admin_hide_community_post(
  target_post_id uuid,
  target_report_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := auth.uid();
  previous_status post_status;
  target_ip_id text;
  linked_report_target report_target;
  linked_report_target_id text;
  linked_report_post_id uuid;
begin
  if actor_id is null or not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select posts.status, posts.ip_id
    into previous_status, target_ip_id
    from public.posts
    where posts.id = target_post_id
    for update;

  if not found then
    raise exception 'post_not_found' using errcode = '22023';
  end if;

  update public.posts
  set status = 'hidden'
  where posts.id = target_post_id;

  if target_report_id is not null then
    select reports.target_type, reports.target_id
      into linked_report_target, linked_report_target_id
      from public.reports
      where reports.id = target_report_id
      for update;

    if not found then
      raise exception 'report_not_found' using errcode = '22023';
    end if;

    if linked_report_target = 'post' then
      if linked_report_target_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        raise exception 'report_target_mismatch' using errcode = '22023';
      end if;

      linked_report_post_id := linked_report_target_id::uuid;
    elsif linked_report_target = 'comment' then
      if linked_report_target_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        raise exception 'report_target_mismatch' using errcode = '22023';
      end if;

      select comments.post_id
        into linked_report_post_id
        from public.comments
        where comments.id = linked_report_target_id::uuid;

      if not found then
        raise exception 'report_target_mismatch' using errcode = '22023';
      end if;
    else
      /* 'user'와 'review'가 여기로 온다. 둘 다 포스트 숨김으로는 해소되지 않는다. */
      raise exception 'report_target_mismatch' using errcode = '22023';
    end if;

    if linked_report_post_id <> target_post_id then
      raise exception 'report_target_mismatch' using errcode = '22023';
    end if;

    update public.reports
    set status = 'resolved'
    where reports.id = target_report_id;
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'community_post_hide',
    'post:' || target_post_id::text,
    jsonb_build_object('from', previous_status, 'to', 'hidden', 'reportId', target_report_id)
  );

  return jsonb_build_object('ipId', target_ip_id);
end;
$$

-- 블라인드/해제. 작성자 삭제와는 다른 행위라 행을 지우지 않고 상태만 바꾼다 —
-- 원문이 남아야 왜 내렸는지 검증할 수 있다.
--
-- 연결 신고를 함께 종결할 수 있지만, 그 신고가 정말 이 리뷰를 가리키는지 확인한
-- 뒤에만 한다(admin_hide_community_post의 대칭). 확인 없이 닫으면 운영자가 아무
-- 신고나 임의의 리뷰 블라인드로 소비할 수 있다.
create function public.admin_set_review_status(
  target_review_id uuid,
  target_status text,
  target_reason text default null,
  target_report_id uuid default null
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := (select auth.uid());
  v_status text := btrim(coalesce(target_status, ''));
  v_reason text := nullif(btrim(coalesce(target_reason, '')), '');
  v_previous text;
  v_good_id text;
  v_linked_target public.report_target;
  v_linked_target_id text;
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if v_status not in ('visible', 'hidden') then
    raise invalid_parameter_value using message = 'invalid_review_status';
  end if;
  -- 블라인드는 사유가 필수다. 사유 없는 비공개는 나중에 아무도 해제하지 못한다.
  if v_status = 'hidden' and (v_reason is null or char_length(v_reason) not between 2 and 500) then
    raise invalid_parameter_value using message = 'review_hide_reason_required';
  end if;

  select review.status, review.good_id
    into v_previous, v_good_id
  from public.reviews as review
  where review.id = target_review_id
  for update;

  if not found then
    raise no_data_found using message = 'review_not_found';
  end if;

  update public.reviews
  set
    status = v_status,
    hidden_reason = case when v_status = 'hidden' then v_reason else null end,
    hidden_at = case when v_status = 'hidden' then now() else null end,
    hidden_by = case when v_status = 'hidden' then v_actor else null end
  where id = target_review_id;

  if target_report_id is not null then
    select report.target_type, report.target_id
      into v_linked_target, v_linked_target_id
    from public.reports as report
    where report.id = target_report_id
    for update;

    if not found then
      raise no_data_found using message = 'report_not_found';
    end if;
    if v_linked_target <> 'review' or v_linked_target_id <> target_review_id::text then
      raise check_violation using message = 'report_target_mismatch';
    end if;

    update public.reports
    set status = 'resolved'
    where reports.id = target_report_id;
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.review.status',
    'review:' || target_review_id::text,
    jsonb_build_object(
      'from', v_previous,
      'to', v_status,
      'goodId', v_good_id,
      'reason', v_reason,
      'reportId', target_report_id
    )
  );
end;
$$

revoke all on function public.admin_search_reviews(
  uuid, date, date, integer, text, boolean, boolean, boolean, text, text, text, integer, integer
) from public, anon, authenticated, service_role

grant execute on function public.admin_search_reviews(
  uuid, date, date, integer, text, boolean, boolean, boolean, text, text, text, integer, integer
) to authenticated

-- ---------------------------------------------------------------------------
-- 5. 알림 타입 확장
-- ---------------------------------------------------------------------------
-- 기존 정의에서 값을 읽어 덧붙인다. 목록을 손으로 다시 적으면 병렬 브랜치가
-- 추가한 타입을 조용히 지운다 — 각 브랜치는 단독으로 통과하고 리베이스 뒤에야
-- 드러나므로, 열거형 CHECK를 넓힐 때는 항상 이 형태를 쓴다.
do $$
declare
  v_def text;
  v_values text;
begin
  select pg_catalog.pg_get_constraintdef(constraint_row.oid)
  into v_def
  from pg_catalog.pg_constraint as constraint_row
  join pg_catalog.pg_class as table_row on table_row.oid = constraint_row.conrelid
  join pg_catalog.pg_namespace as schema_row on schema_row.oid = table_row.relnamespace
  where schema_row.nspname = 'public'
    and table_row.relname = 'notifications'
    and constraint_row.conname = 'notifications_type_check';

  select string_agg(distinct quote_literal(matched[1]), ', ')
  into v_values
  from regexp_matches(v_def, '''([a-z_]+)''::text', 'g') as matched;

  if v_values is null then
    raise exception 'notifications_type_check has no readable type list';
  end if;

  if position('''order_bank_transfer_pending''' in v_values) = 0 then
    v_values := v_values || ', ' || quote_literal('order_bank_transfer_pending');
  end if;

  execute 'alter table public.notifications drop constraint notifications_type_check';
  execute format(
    'alter table public.notifications add constraint notifications_type_check check (type in (%s))',
    v_values
  );
end;
$$

-- ---------------------------------------------------------------------------
-- 6. 주문 생성 — 결제수단 분기
-- ---------------------------------------------------------------------------
create or replace function public.place_order(
  p_address jsonb,
  p_checkout_key uuid,
  p_payment_method public.order_payment_method
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  -- lib/shipping.ts의 SHIPPING_FEE · FREE_SHIPPING_THRESHOLD와 같은 값이어야 한다.
  c_shipping_fee constant bigint := 3000;
  c_free_shipping_threshold constant bigint := 50000;
  v_user uuid := (select auth.uid());
  v_order uuid;
  v_existing_address jsonb;
  v_existing_payment_method public.order_payment_method;
  v_expires_at timestamptz;
  v_subtotal bigint := 0;
  v_shipping_fee bigint := 0;
  v_item_count integer := 0;
  v_recipient_name text;
  v_phone text;
  v_postal_code text;
  v_address1 text;
  v_optional text;
  r record;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if not exists (
    select 1
    from public.profiles as profile
    join auth.users as auth_user on auth_user.id = profile.id
    where profile.id = v_user
      and nullif(btrim(coalesce(profile.email, auth_user.email)), '') is not null
      and nullif(btrim(profile.nickname), '') is not null
      and profile.birth_date is not null
      and profile.birth_date <= current_date
      and profile.onboarded_at is not null
      and profile.consents ->> 'terms' = 'true'
      and profile.consents ->> 'privacy' = 'true'
  ) then
    raise insufficient_privilege using message = 'onboarding required';
  end if;

  if p_checkout_key is null then
    raise not_null_violation using message = 'checkout key required';
  end if;

  if p_address is null or jsonb_typeof(p_address) <> 'object' then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if not (p_address ?& array['recipientName', 'phone', 'postalCode', 'address1'])
     or exists (
       select 1
       from jsonb_object_keys(p_address) as address_key(key)
       where address_key.key not in (
         'recipientName', 'phone', 'postalCode', 'address1', 'address2', 'deliveryNote'
       )
     )
     or exists (
       select 1
       from jsonb_each(p_address) as address_value(key, value)
       where jsonb_typeof(address_value.value) <> 'string'
     ) then
    raise check_violation using message = 'invalid checkout address';
  end if;

  v_recipient_name := p_address ->> 'recipientName';
  v_phone := p_address ->> 'phone';
  v_postal_code := p_address ->> 'postalCode';
  v_address1 := p_address ->> 'address1';

  if v_recipient_name <> btrim(v_recipient_name, E' \t\n\r\f\v')
     or length(v_recipient_name) not between 1 and 50
     or v_phone !~ '^[0-9]{8,15}$'
     or v_postal_code !~ '^[0-9]{5}$'
     or v_address1 <> btrim(v_address1, E' \t\n\r\f\v')
     or length(v_address1) not between 1 and 200 then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if p_address ? 'address2' then
    v_optional := p_address ->> 'address2';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  if p_address ? 'deliveryNote' then
    v_optional := p_address ->> 'deliveryNote';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  -- 같은 사용자의 다른 탭 주문을 직렬화한다. 동일 키 재시도는 먼저 생성된
  -- 주문을 반환하고, 다른 키는 첫 주문이 비운 장바구니를 확인하게 된다.
  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  select orders.id, orders.address, orders.payment_method
    into v_order, v_existing_address, v_existing_payment_method
  from public.orders
  where orders.user_id = v_user
    and orders.checkout_key = p_checkout_key;

  if found then
    -- 같은 checkout key로 결제수단만 바꿔 다시 부르면 24시간 선점을 15분 주문에
    -- 덧씌우거나 그 반대가 된다. 주소와 같은 등급의 충돌로 막는다.
    if v_existing_address is distinct from p_address
      or v_existing_payment_method is distinct from p_payment_method
    then
      raise unique_violation using message = 'checkout key conflict';
    end if;
    return v_order;
  end if;

  -- 카드 15분 · 무통장 24시간. 무통장은 사람이 은행 앱을 열고 이체할 시간을
  -- 줘야 해서 선점 창이 길고, 그만큼 재고가 오래 묶인다 — 한정 드롭은
  -- goods.allow_bank_transfer로 아예 차단한다(ADR-0007).
  v_expires_at := case
    when p_payment_method = 'bank_transfer' then now() + interval '24 hours'
    else now() + interval '15 minutes'
  end;

  insert into public.orders (
    user_id, status, total, shipping_fee, address, expires_at, checkout_key, payment_method
  )
  values (v_user, 'pending', 0, 0, p_address, v_expires_at, p_checkout_key, p_payment_method)
  returning id into v_order;

  -- 카트와 재고를 같은 결정적 순서로 잠근 뒤 DB 값만으로 주문 스냅샷을 만든다.
  for r in
    select
      cart.good_id,
      cart.qty,
      good.price,
      good.stock,
      good.stock_qty,
      good.name,
      good.type,
      good.ip_id,
      good.allow_bank_transfer
    from public.cart_items as cart
    join public.goods as good on good.id = cart.good_id
    where cart.user_id = v_user
    order by cart.good_id
    for update of cart, good
  loop
    v_item_count := v_item_count + 1;

    if r.stock = 'soldout' or r.stock_qty < r.qty then
      raise check_violation using message = format('out of stock: %s', r.good_id);
    end if;

    if p_payment_method = 'bank_transfer' and not r.allow_bank_transfer then
      raise check_violation using message = format('bank transfer blocked: %s', r.good_id);
    end if;

    update public.goods
    set stock_qty = stock_qty - r.qty
    where id = r.good_id;

    insert into public.order_items (
      order_id,
      good_id,
      qty,
      unit_price,
      good_name_snapshot,
      good_type_snapshot,
      good_ip_id_snapshot
    )
    values (
      v_order,
      r.good_id,
      r.qty,
      r.price,
      r.name,
      r.type,
      r.ip_id
    );

    -- 조회 시 잠근 스냅샷 행만 지운다. 동시에 새로 담긴 다른 상품까지
    -- 마지막 broad delete가 없애지 않도록 상품 단위로 소비한다.
    delete from public.cart_items
    where user_id = v_user
      and good_id = r.good_id;

    v_subtotal := v_subtotal + (r.price::bigint * r.qty::bigint);
  end loop;

  if v_item_count = 0 then
    raise check_violation using message = 'cart empty';
  end if;

  if v_subtotal > 0 and v_subtotal < c_free_shipping_threshold then
    v_shipping_fee := c_shipping_fee;
  end if;

  update public.orders
  set total = v_subtotal + v_shipping_fee,
      shipping_fee = v_shipping_fee
  where id = v_order;

  -- 무통장에는 결제사 왕복이 없다. 그래서 원장 anchor(payment_attempts)를 여기서
  -- 바로 연다 — 없으면 운영자가 입금을 확인할 대상 자체가 없고, "결제 준비" 버튼을
  -- 눌러야 생기는 구조는 구매자가 이미 이체한 뒤에도 확인이 안 되는 창을 만든다.
  -- 새 함수를 두지 않고 카드와 같은 prepare를 부른다: 소유권·금액·스냅샷·정지
  -- 계정 검사가 한 곳에만 있어야 한다.
  if p_payment_method = 'bank_transfer' then
    perform public.prepare_goods_payment_attempt(v_user, v_order, 'bank_transfer');
  end if;

  -- 무통장 주문은 만든 순간이 안내 시점이다. 금액·입금자명 코드·기한이 모두
  -- 정해졌고, 이 알림을 놓치면 구매자는 어디로 얼마를 보낼지 알 수 없다.
  if p_payment_method = 'bank_transfer' then
    insert into public.notifications (
      user_id, type, title, body, link_path, source_type, source_id, dedupe_key
    )
    values (
      v_user,
      'order_bank_transfer_pending',
      '입금 안내를 확인해주세요',
      format(
        '%s원을 기한 안에 입금해주세요. 입금자명 끝에 주문코드 %s를 붙이면 확인이 빨라집니다.',
        to_char(v_subtotal + v_shipping_fee, 'FM999,999,999'),
        private.bank_transfer_deposit_code(v_order)
      ),
      '/checkout/' || v_order::text,
      'order',
      v_order::text,
      'order:bank_transfer_pending:' || v_order::text
    )
    on conflict (user_id, dedupe_key) do nothing;
  end if;

  return v_order;
end;
$$

-- 브라우저는 주문 생성 RPC를 직접 부르지 못한다(20260722062300). 서버가 인증을
-- 확인한 뒤 service role로 사용자 id를 넘기는 이 래퍼만 실행 권한을 갖는다.
-- 결제수단도 같은 경계를 지나야 한다 — 열어 두면 브라우저가 24시간 선점을
-- 스스로 고를 수 있다.
create function public.place_order(
  p_user_id uuid,
  p_address jsonb,
  p_checkout_key uuid,
  p_payment_method public.order_payment_method
)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  previous_subject text := pg_catalog.current_setting('request.jwt.claim.sub', true);
  placed_order_id uuid;
begin
  if p_user_id is null then
    raise not_null_violation using message = 'user required';
  end if;

  perform pg_catalog.set_config('request.jwt.claim.sub', p_user_id::text, true);
  placed_order_id := public.place_order(p_address, p_checkout_key, p_payment_method);
  perform pg_catalog.set_config('request.jwt.claim.sub', coalesce(previous_subject, ''), true);
  return placed_order_id;
exception
  when others then
    perform pg_catalog.set_config('request.jwt.claim.sub', coalesce(previous_subject, ''), true);
    raise;
end;
$$

-- 입금 확인. 증빙을 남기고 attempt를 confirming으로 옮긴 뒤 **기존 finalizer**를
-- 부른다. 운영자 액션이 orders.status를 직접 건드리지 않는 것이 핵심이다 —
-- 재고·원장·뽑기권 부수효과가 전부 finalizer 한 곳에만 있다.
create function public.admin_confirm_bank_transfer_deposit(
  p_order_id uuid,
  p_memo text
)
returns public.payment_attempt_state
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $function$
declare
  v_actor uuid := (select auth.uid());
  v_memo text := btrim(coalesce(p_memo, ''));
  v_order public.orders%rowtype;
  v_attempt public.payment_attempts%rowtype;
  v_claim_token uuid := extensions.gen_random_uuid();
  v_outcome public.payment_attempt_state;
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if char_length(v_memo) not between 5 and 200 then
    raise check_violation using message = 'invalid deposit memo';
  end if;

  -- 전역 잠금 순서: orders → payment_attempts → payments.
  select orders.* into v_order
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise no_data_found using message = 'order_not_found';
  end if;

  if v_order.payment_method is distinct from 'bank_transfer' then
    raise check_violation using message = 'order_not_bank_transfer';
  end if;

  if v_order.status is distinct from 'pending' then
    raise object_not_in_prerequisite_state using message = 'order_not_unpaid';
  end if;

  select attempt.* into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'order'
    and attempt.ref_id = v_order.id
    and attempt.provider = 'bank_transfer'
  for update;

  if not found then
    raise no_data_found using message = 'bank_transfer_attempt_not_found';
  end if;

  -- 만료 스윕이 이미 attempt를 닫았으면 여기서 멈춘다. finalizer는 종결 상태를
  -- 그대로 되돌려 주므로 그냥 부르면 "확인했는데 아무 일도 없다"가 된다.
  if v_attempt.state is distinct from 'prepared' then
    raise object_not_in_prerequisite_state using message = 'bank_transfer_attempt_not_confirmable';
  end if;

  update public.payment_attempts
  set
    state = 'confirming',
    claim_token = v_claim_token,
    claim_expires_at = now() + interval '5 minutes'
  where id = v_attempt.id;

  insert into public.bank_transfer_confirmations (order_id, attempt_id, confirmed_by, memo)
  values (v_order.id, v_attempt.id, v_actor, v_memo);

  v_outcome := public.finalize_goods_payment_attempt(
    v_attempt.id,
    v_claim_token,
    'approved',
    'bank_transfer:' || v_attempt.id::text,
    null,
    null,
    null,
    'bank_transfer',
    null,
    now()
  );

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.bank_transfer_confirmed',
    'order:' || v_order.id::text,
    jsonb_build_object(
      'attemptId', v_attempt.id,
      'amount', v_order.total,
      'depositCode', private.bank_transfer_deposit_code(v_order.id),
      'memo', v_memo,
      'outcome', v_outcome
    )
  );

  return v_outcome;
end;
$function$

-- 기한 연장 1회. 사유는 필수다 — 연장은 재고를 하루 더 묶는 판단이라
-- 누가 왜 늘렸는지가 남지 않으면 나중에 검증할 수 없다.
create function public.admin_extend_bank_transfer_deadline(
  p_order_id uuid,
  p_reason text
)
returns timestamptz
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $function$
declare
  v_actor uuid := (select auth.uid());
  v_reason text := btrim(coalesce(p_reason, ''));
  v_order public.orders%rowtype;
  v_new_expiry timestamptz;
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if char_length(v_reason) not between 5 and 200 then
    raise check_violation using message = 'invalid extension reason';
  end if;

  select orders.* into v_order
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise no_data_found using message = 'order_not_found';
  end if;

  if v_order.payment_method is distinct from 'bank_transfer' then
    raise check_violation using message = 'order_not_bank_transfer';
  end if;

  if v_order.status is distinct from 'pending' then
    raise object_not_in_prerequisite_state using message = 'order_not_unpaid';
  end if;

  if v_order.bank_transfer_extended_at is not null then
    raise object_not_in_prerequisite_state using message = 'bank_transfer_already_extended';
  end if;

  v_new_expiry := now() + interval '24 hours';

  update public.orders
  set expires_at = v_new_expiry,
      bank_transfer_extended_at = now()
  where id = v_order.id;

  -- attempt TTL이 곧 입금 기한이다. 주문만 늘리고 attempt를 두면 확인 시점에
  -- 만료된 attempt가 남는다.
  update public.payment_attempts
  set expires_at = v_new_expiry
  where purpose = 'order'
    and ref_id = v_order.id
    and provider = 'bank_transfer'
    and state = 'prepared';

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.bank_transfer_extended',
    'order:' || v_order.id::text,
    jsonb_build_object(
      'from', v_order.expires_at,
      'to', v_new_expiry,
      'reason', v_reason
    )
  );

  return v_new_expiry;
end;
$function$

-- 즉시 취소. 미입금이라 환불할 돈이 없다 — 재고 복원만 하면 된다. 만료 스윕과
-- 같은 순서(attempt를 먼저 닫고 주문을 취소)를 따른다.
--
-- `prepared`뿐 아니라 `needs_review`·`unknown` attempt도 취소할 수 있어야 한다.
-- finalizer가 확정 직전 검사에서 걸리면 attempt가 `prepared`를 벗어나는데, 그러면
-- 확인도 취소도 막히고 만료 스윕까지 그 상태를 건너뛴다 — 주문이 재고를 문 채
-- 콘솔에서 빠져나갈 길이 없어진다. 카드에는 #208 수동 복구 경로가 있지만
-- 무통장에는 없으므로 이 함수가 그 출구다.
--
-- 다만 결제 원장이 열려 있으면 막는다. 무통장은 PG 왕복이 없어 `payments` 행이
-- 곧 "확정된 돈"이고, 그 상태에서 취소하면 환불 없이 재고만 되돌아간다.
create function public.admin_cancel_unpaid_bank_transfer_order(
  p_order_id uuid,
  p_reason text
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $function$
declare
  v_actor uuid := (select auth.uid());
  v_reason text := btrim(coalesce(p_reason, ''));
  v_order public.orders%rowtype;
  v_attempt public.payment_attempts%rowtype;
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if char_length(v_reason) not between 5 and 200 then
    raise check_violation using message = 'invalid cancellation reason';
  end if;

  select orders.* into v_order
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise no_data_found using message = 'order_not_found';
  end if;

  if v_order.payment_method is distinct from 'bank_transfer' then
    raise check_violation using message = 'order_not_bank_transfer';
  end if;

  if v_order.status is distinct from 'pending' then
    raise object_not_in_prerequisite_state using message = 'order_not_unpaid';
  end if;

  select attempt.* into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'order'
    and attempt.ref_id = v_order.id
    and attempt.provider = 'bank_transfer'
  for update;

  if found then
    if v_attempt.state not in ('prepared', 'needs_review', 'unknown') then
      raise object_not_in_prerequisite_state using message = 'bank_transfer_attempt_not_cancelable';
    end if;

    if exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'order'
        and payment.ref_id = v_order.id
        and payment.status in ('pending', 'paid')
    ) then
      raise object_not_in_prerequisite_state using message = 'bank_transfer_payment_exists';
    end if;

    update public.payment_attempts
    set state = 'canceled',
        claim_token = null,
        claim_expires_at = null
    where id = v_attempt.id;
  end if;

  perform public.cancel_order(v_order.id, v_reason);

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.bank_transfer_canceled',
    'order:' || v_order.id::text,
    jsonb_build_object(
      'reason', v_reason,
      'amount', v_order.total,
      'attemptState', v_attempt.state
    )
  );
end;
$function$

-- 미아 입금·환불 출금처럼 주문에 붙지 않는 기록을 큐에서 내린다. 지우지 않는
-- 이유는 반환 절차의 근거가 이 행이기 때문이다.
create function public.admin_ignore_bank_deposit(
  p_deposit_id uuid,
  p_reason text
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $function$
declare
  v_actor uuid := (select auth.uid());
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if char_length(v_reason) not between 5 and 200 then
    raise check_violation using message = 'invalid ignore reason';
  end if;

  update public.bank_deposits
  set
    status = 'ignored',
    decided_by = v_actor,
    decision_note = v_reason
  where id = p_deposit_id
    and status = 'unmatched';

  if not found then
    raise no_data_found using message = 'deposit_not_ignorable';
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.bank_deposit.ignored',
    'bank_deposit:' || p_deposit_id::text,
    jsonb_build_object('reason', v_reason)
  );
end;
$function$

revoke all on function public.admin_search_order_claims(
