create function public.admin_upsert_home_curation(
  target_operation_id uuid,
  target_curation_id uuid,
  target_kind text,
  target_ip_id text,
  target_title text,
  target_image_path text,
  target_link_path text,
  target_display_order integer,
  target_active_from timestamptz,
  target_active_to timestamptz,
  target_enabled boolean,
  target_slot text default null,
  target_payload jsonb default null
)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor_id uuid := (select auth.uid());
  -- Alias with a column-safe name: inside the claim UPDATE below, a bare
  -- actor_id would be ambiguous against admin_artwork_upload_claims.actor_id.
  claim_owner_id uuid := actor_id;
  normalized_kind text := pg_catalog.btrim(target_kind);
  normalized_ip_id text := nullif(pg_catalog.btrim(target_ip_id), '');
  normalized_title text := pg_catalog.btrim(target_title);
  normalized_image_path text := nullif(pg_catalog.btrim(target_image_path), '');
  normalized_link_path text := pg_catalog.btrim(target_link_path);
  normalized_slot text := nullif(pg_catalog.btrim(target_slot), '');
  normalized_payload jsonb := case
    when target_payload is null or target_payload = '{}'::jsonb then null
    else target_payload
  end;
  allowed_payload_keys text[];
  payload_key text;
  payload_text_value text;
  payload_good_ids jsonb;
  payload_good_id_limit integer;
  payload_good_id text;
  payload_mobile_image_path text;
  previous_mobile_image_path text;
  referenced_archived_at timestamptz;
  request_payload jsonb;
  previous_payload jsonb := 'null'::jsonb;
  after_payload jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  previous_curation public.home_curations%rowtype;
  curation_exists boolean := false;
begin
  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  if not public.is_staff() then
    raise insufficient_privilege using message = 'forbidden';
  end if;

  if target_operation_id is null then
    raise null_value_not_allowed using message = 'invalid_operation_id';
  end if;
  if target_curation_id is null then
    raise null_value_not_allowed using message = 'invalid_curation_id';
  end if;
  if normalized_kind is null
    or normalized_kind not in (
      'hero', 'featured_ip', 'announcement',
      'notice_strip', 'editor_pick', 'band_banner', 'best_tab', 'benefit'
    )
  then
    raise invalid_parameter_value using message = 'invalid_curation_kind';
  end if;
  if normalized_title is null
    or pg_catalog.char_length(normalized_title) not between 1 and 120
  then
    raise invalid_parameter_value using message = 'invalid_curation_title';
  end if;
  if normalized_kind = 'featured_ip' and normalized_ip_id is null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind <> 'featured_ip' and normalized_ip_id is not null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind in ('hero', 'notice_strip', 'editor_pick', 'band_banner')
    and normalized_image_path is null
  then
    raise check_violation using message = 'curation_image_required';
  end if;
  if normalized_image_path is not null
    and normalized_image_path !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  then
    raise check_violation using message = 'invalid_curation_image_path';
  end if;
  if normalized_link_path is null
    or not private.is_safe_home_curation_link(normalized_link_path)
  then
    raise invalid_parameter_value using message = 'invalid_curation_link_path';
  end if;
  if target_display_order is null or target_display_order < 0 then
    raise invalid_parameter_value using message = 'invalid_curation_display_order';
  end if;
  if target_active_from is null then
    raise null_value_not_allowed using message = 'invalid_curation_active_from';
  end if;
  if not pg_catalog.isfinite(target_active_from) then
    raise invalid_parameter_value using message = 'invalid_curation_active_from';
  end if;
  if target_active_to is not null
    and (
      not pg_catalog.isfinite(target_active_to)
      or target_active_to <= target_active_from
    )
  then
    raise check_violation using message = 'invalid_curation_active_window';
  end if;
  if target_enabled is null then
    raise null_value_not_allowed using message = 'invalid_curation_enabled';
  end if;

  if normalized_kind = 'best_tab' then
    if normalized_slot is null or normalized_slot not in ('category', 'popular') then
      raise invalid_parameter_value using message = 'invalid_curation_slot';
    end if;
  elsif normalized_slot is not null then
    raise invalid_parameter_value using message = 'invalid_curation_slot';
  end if;

  -- Per-kind payload whitelist. Unknown keys are rejected outright so typos
  -- never ship silently dead configuration.
  allowed_payload_keys := case normalized_kind
    when 'hero' then array['subtitle', 'mobile_image_path']
    when 'editor_pick' then array['badge', 'description']
    when 'band_banner' then array['subcopy', 'good_ids']
    when 'best_tab' then array['good_ids']
    when 'benefit' then array['description']
    else array[]::text[]
  end;

  if normalized_payload is not null then
    if pg_catalog.jsonb_typeof(normalized_payload) <> 'object' then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    if pg_catalog.cardinality(allowed_payload_keys) = 0 then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    for payload_key in
      select key from pg_catalog.jsonb_object_keys(normalized_payload) as keys(key)
    loop
      if not payload_key = any (allowed_payload_keys) then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
    end loop;

    for payload_key in
      select unnest from pg_catalog.unnest(array['subtitle', 'badge', 'description', 'subcopy'])
    loop
      if normalized_payload ? payload_key then
        if pg_catalog.jsonb_typeof(normalized_payload -> payload_key) <> 'string' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        payload_text_value := pg_catalog.btrim(normalized_payload ->> payload_key);
        if pg_catalog.char_length(payload_text_value) not between 1 and 200
          or (payload_key = 'badge' and pg_catalog.char_length(payload_text_value) > 20)
        then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        normalized_payload := pg_catalog.jsonb_set(
          normalized_payload, array[payload_key], pg_catalog.to_jsonb(payload_text_value)
        );
      end if;
    end loop;

    if normalized_payload ? 'good_ids' then
      payload_good_ids := normalized_payload -> 'good_ids';
      payload_good_id_limit := case normalized_kind when 'best_tab' then 12 else 4 end;
      if pg_catalog.jsonb_typeof(payload_good_ids) <> 'array'
        or pg_catalog.jsonb_array_length(payload_good_ids) not between 1 and payload_good_id_limit
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      for payload_good_id in
        select value from pg_catalog.jsonb_array_elements_text(payload_good_ids) as elements(value)
      loop
        if payload_good_id !~ '^[A-Za-z0-9_-]{1,64}$' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
      end loop;
    end if;

    if normalized_payload ? 'mobile_image_path' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'mobile_image_path') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      payload_mobile_image_path := normalized_payload ->> 'mobile_image_path';
      if payload_mobile_image_path
        !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
      then
        raise check_violation using message = 'invalid_curation_image_path';
      end if;
    end if;
  end if;

  request_payload := pg_catalog.jsonb_build_object(
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.home_curation.upserted'
      and existing_target = 'home_curations:' || target_curation_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_curation_id;
    end if;

    raise unique_violation using message = 'operation_conflict';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation:' || target_curation_id::text,
      0
    )
  );

  if normalized_ip_id is not null then
    select ip.archived_at
      into referenced_archived_at
    from public.ips as ip
    where ip.id = normalized_ip_id
    for update of ip;

    if not found then
      raise no_data_found using message = 'curation_ip_not_found';
    end if;
    if referenced_archived_at is not null then
      raise check_violation using message = 'catalog_item_archived';
    end if;
  end if;

  select curation.*
    into previous_curation
  from public.home_curations as curation
  where curation.id = target_curation_id
  for update of curation;
  curation_exists := found;

  if curation_exists then
    previous_payload := pg_catalog.jsonb_build_object(
      'id', previous_curation.id,
      'kind', previous_curation.kind,
      'ip_id', previous_curation.ip_id,
      'title', previous_curation.title,
      'image_path', previous_curation.image_path,
      'link_path', previous_curation.link_path,
      'display_order', previous_curation.display_order,
      'active_from', previous_curation.active_from,
      'active_to', previous_curation.active_to,
      'enabled', previous_curation.enabled,
      'slot', previous_curation.slot,
      'payload', previous_curation.payload
    );
    previous_mobile_image_path := previous_curation.payload ->> 'mobile_image_path';
  end if;

  -- The artwork-claim trigger only guards the image_path column, so the
  -- mobile artwork carried inside payload consumes its verified upload claim
  -- here, under the same actor/kind/single-use rules (#112 contract).
  if payload_mobile_image_path is not null
    and payload_mobile_image_path is distinct from previous_mobile_image_path
  then
    update public.admin_artwork_upload_claims as claim
    set
      status = 'attached',
      attached_at = pg_catalog.clock_timestamp(),
      resolved_at = pg_catalog.clock_timestamp()
    where claim.actor_id = claim_owner_id
      and claim.path = pg_catalog.substr(
        payload_mobile_image_path,
        pg_catalog.length('public-media/') + 1
      )
      and claim.kind = 'curation'
      and claim.status = 'verified'
      and claim.verified_at is not null
      and claim.final_size is not null
      and claim.attached_at is null
      and claim.expires_at > pg_catalog.clock_timestamp();

    if not found then
      raise check_violation using message = 'unverified_artwork';
    end if;
  end if;

  if curation_exists then
    update public.home_curations
    set
      kind = normalized_kind,
      ip_id = normalized_ip_id,
      title = normalized_title,
      image_path = normalized_image_path,
      link_path = normalized_link_path,
      display_order = target_display_order,
      active_from = target_active_from,
      active_to = target_active_to,
      enabled = target_enabled,
      slot = normalized_slot,
      payload = normalized_payload
    where id = target_curation_id;
  else
    insert into public.home_curations (
      id, kind, ip_id, title, image_path, link_path,
      display_order, active_from, active_to, enabled, slot, payload
    )
    values (
      target_curation_id, normalized_kind, normalized_ip_id, normalized_title,
      normalized_image_path, normalized_link_path, target_display_order,
      target_active_from, target_active_to, target_enabled, normalized_slot,
      normalized_payload
    );
  end if;

  after_payload := pg_catalog.jsonb_build_object(
    'id', target_curation_id,
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.home_curation.upserted',
    'home_curations:' || target_curation_id::text,
    pg_catalog.jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_curation_id;
end;
$$

-- Codex review follow-up on #325 (PR #358): the notice strip renders on both
-- desktop and mobile from a single artwork, but the two surfaces need very
-- different proportions (R-01 records separate PC/MO sources). Allow the same
-- payload-carried mobile artwork the hero already uses. Signature is unchanged,
-- so this is a body-only redefinition; the verified-claim consumption path is
-- key-driven and picks the new kind up automatically.

create or replace function public.admin_upsert_home_curation(
  target_operation_id uuid,
  target_curation_id uuid,
  target_kind text,
  target_ip_id text,
  target_title text,
  target_image_path text,
  target_link_path text,
  target_display_order integer,
  target_active_from timestamptz,
  target_active_to timestamptz,
  target_enabled boolean,
  target_slot text default null,
  target_payload jsonb default null
)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor_id uuid := (select auth.uid());
  -- Alias with a column-safe name: inside the claim UPDATE below, a bare
  -- actor_id would be ambiguous against admin_artwork_upload_claims.actor_id.
  claim_owner_id uuid := actor_id;
  normalized_kind text := pg_catalog.btrim(target_kind);
  normalized_ip_id text := nullif(pg_catalog.btrim(target_ip_id), '');
  normalized_title text := pg_catalog.btrim(target_title);
  normalized_image_path text := nullif(pg_catalog.btrim(target_image_path), '');
  normalized_link_path text := pg_catalog.btrim(target_link_path);
  normalized_slot text := nullif(pg_catalog.btrim(target_slot), '');
  normalized_payload jsonb := case
    when target_payload is null or target_payload = '{}'::jsonb then null
    else target_payload
  end;
  allowed_payload_keys text[];
  payload_key text;
  payload_text_value text;
  payload_good_ids jsonb;
  payload_good_id_limit integer;
  payload_good_id text;
  payload_mobile_image_path text;
  previous_mobile_image_path text;
  referenced_archived_at timestamptz;
  request_payload jsonb;
  previous_payload jsonb := 'null'::jsonb;
  after_payload jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  previous_curation public.home_curations%rowtype;
  curation_exists boolean := false;
begin
  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  if not public.is_staff() then
    raise insufficient_privilege using message = 'forbidden';
  end if;

  if target_operation_id is null then
    raise null_value_not_allowed using message = 'invalid_operation_id';
  end if;
  if target_curation_id is null then
    raise null_value_not_allowed using message = 'invalid_curation_id';
  end if;
  if normalized_kind is null
    or normalized_kind not in (
      'hero', 'featured_ip', 'announcement',
      'notice_strip', 'editor_pick', 'band_banner', 'best_tab', 'benefit'
    )
  then
    raise invalid_parameter_value using message = 'invalid_curation_kind';
  end if;
  if normalized_title is null
    or pg_catalog.char_length(normalized_title) not between 1 and 120
  then
    raise invalid_parameter_value using message = 'invalid_curation_title';
  end if;
  if normalized_kind = 'featured_ip' and normalized_ip_id is null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind <> 'featured_ip' and normalized_ip_id is not null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind in ('hero', 'notice_strip', 'editor_pick', 'band_banner')
    and normalized_image_path is null
  then
    raise check_violation using message = 'curation_image_required';
  end if;
  if normalized_image_path is not null
    and normalized_image_path !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  then
    raise check_violation using message = 'invalid_curation_image_path';
  end if;
  if normalized_link_path is null
    or not private.is_safe_home_curation_link(normalized_link_path)
  then
    raise invalid_parameter_value using message = 'invalid_curation_link_path';
  end if;
  if target_display_order is null or target_display_order < 0 then
    raise invalid_parameter_value using message = 'invalid_curation_display_order';
  end if;
  if target_active_from is null then
    raise null_value_not_allowed using message = 'invalid_curation_active_from';
  end if;
  if not pg_catalog.isfinite(target_active_from) then
    raise invalid_parameter_value using message = 'invalid_curation_active_from';
  end if;
  if target_active_to is not null
    and (
      not pg_catalog.isfinite(target_active_to)
      or target_active_to <= target_active_from
    )
  then
    raise check_violation using message = 'invalid_curation_active_window';
  end if;
  if target_enabled is null then
    raise null_value_not_allowed using message = 'invalid_curation_enabled';
  end if;

  if normalized_kind = 'best_tab' then
    if normalized_slot is null or normalized_slot not in ('category', 'popular') then
      raise invalid_parameter_value using message = 'invalid_curation_slot';
    end if;
  elsif normalized_slot is not null then
    raise invalid_parameter_value using message = 'invalid_curation_slot';
  end if;

  -- Per-kind payload whitelist. Unknown keys are rejected outright so typos
  -- never ship silently dead configuration.
  allowed_payload_keys := case normalized_kind
    when 'hero' then array['subtitle', 'mobile_image_path']
    when 'notice_strip' then array['mobile_image_path']
    when 'editor_pick' then array['badge', 'description']
    when 'band_banner' then array['subcopy', 'good_ids']
    when 'best_tab' then array['good_ids']
    when 'benefit' then array['description']
    else array[]::text[]
  end;

  if normalized_payload is not null then
    if pg_catalog.jsonb_typeof(normalized_payload) <> 'object' then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    if pg_catalog.cardinality(allowed_payload_keys) = 0 then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    for payload_key in
      select key from pg_catalog.jsonb_object_keys(normalized_payload) as keys(key)
    loop
      if not payload_key = any (allowed_payload_keys) then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
    end loop;

    for payload_key in
      select unnest from pg_catalog.unnest(array['subtitle', 'badge', 'description', 'subcopy'])
    loop
      if normalized_payload ? payload_key then
        if pg_catalog.jsonb_typeof(normalized_payload -> payload_key) <> 'string' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        payload_text_value := pg_catalog.btrim(normalized_payload ->> payload_key);
        if pg_catalog.char_length(payload_text_value) not between 1 and 200
          or (payload_key = 'badge' and pg_catalog.char_length(payload_text_value) > 20)
        then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        normalized_payload := pg_catalog.jsonb_set(
          normalized_payload, array[payload_key], pg_catalog.to_jsonb(payload_text_value)
        );
      end if;
    end loop;

    if normalized_payload ? 'good_ids' then
      payload_good_ids := normalized_payload -> 'good_ids';
      payload_good_id_limit := case normalized_kind when 'best_tab' then 12 else 4 end;
      if pg_catalog.jsonb_typeof(payload_good_ids) <> 'array'
        or pg_catalog.jsonb_array_length(payload_good_ids) not between 1 and payload_good_id_limit
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      for payload_good_id in
        select value from pg_catalog.jsonb_array_elements_text(payload_good_ids) as elements(value)
      loop
        if payload_good_id !~ '^[A-Za-z0-9_-]{1,64}$' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
      end loop;
    end if;

    if normalized_payload ? 'mobile_image_path' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'mobile_image_path') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      payload_mobile_image_path := normalized_payload ->> 'mobile_image_path';
      if payload_mobile_image_path
        !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
      then
        raise check_violation using message = 'invalid_curation_image_path';
      end if;
    end if;
  end if;

  request_payload := pg_catalog.jsonb_build_object(
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.home_curation.upserted'
      and existing_target = 'home_curations:' || target_curation_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_curation_id;
    end if;

    raise unique_violation using message = 'operation_conflict';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation:' || target_curation_id::text,
      0
    )
  );

  if normalized_ip_id is not null then
    select ip.archived_at
      into referenced_archived_at
    from public.ips as ip
    where ip.id = normalized_ip_id
    for update of ip;

    if not found then
      raise no_data_found using message = 'curation_ip_not_found';
    end if;
    if referenced_archived_at is not null then
      raise check_violation using message = 'catalog_item_archived';
    end if;
  end if;

  select curation.*
    into previous_curation
  from public.home_curations as curation
  where curation.id = target_curation_id
  for update of curation;
  curation_exists := found;

  if curation_exists then
    previous_payload := pg_catalog.jsonb_build_object(
      'id', previous_curation.id,
      'kind', previous_curation.kind,
      'ip_id', previous_curation.ip_id,
      'title', previous_curation.title,
      'image_path', previous_curation.image_path,
      'link_path', previous_curation.link_path,
      'display_order', previous_curation.display_order,
      'active_from', previous_curation.active_from,
      'active_to', previous_curation.active_to,
      'enabled', previous_curation.enabled,
      'slot', previous_curation.slot,
      'payload', previous_curation.payload
    );
    previous_mobile_image_path := previous_curation.payload ->> 'mobile_image_path';
  end if;

  -- The artwork-claim trigger only guards the image_path column, so the
  -- mobile artwork carried inside payload consumes its verified upload claim
  -- here, under the same actor/kind/single-use rules (#112 contract).
  if payload_mobile_image_path is not null
    and payload_mobile_image_path is distinct from previous_mobile_image_path
  then
    update public.admin_artwork_upload_claims as claim
    set
      status = 'attached',
      attached_at = pg_catalog.clock_timestamp(),
      resolved_at = pg_catalog.clock_timestamp()
    where claim.actor_id = claim_owner_id
      and claim.path = pg_catalog.substr(
        payload_mobile_image_path,
        pg_catalog.length('public-media/') + 1
      )
      and claim.kind = 'curation'
      and claim.status = 'verified'
      and claim.verified_at is not null
      and claim.final_size is not null
      and claim.attached_at is null
      and claim.expires_at > pg_catalog.clock_timestamp();

    if not found then
      raise check_violation using message = 'unverified_artwork';
    end if;
  end if;

  if curation_exists then
    update public.home_curations
    set
      kind = normalized_kind,
      ip_id = normalized_ip_id,
      title = normalized_title,
      image_path = normalized_image_path,
      link_path = normalized_link_path,
      display_order = target_display_order,
      active_from = target_active_from,
      active_to = target_active_to,
      enabled = target_enabled,
      slot = normalized_slot,
      payload = normalized_payload
    where id = target_curation_id;
  else
    insert into public.home_curations (
      id, kind, ip_id, title, image_path, link_path,
      display_order, active_from, active_to, enabled, slot, payload
    )
    values (
      target_curation_id, normalized_kind, normalized_ip_id, normalized_title,
      normalized_image_path, normalized_link_path, target_display_order,
      target_active_from, target_active_to, target_enabled, normalized_slot,
      normalized_payload
    );
  end if;

  after_payload := pg_catalog.jsonb_build_object(
    'id', target_curation_id,
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.home_curation.upserted',
    'home_curations:' || target_curation_id::text,
    pg_catalog.jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_curation_id;
end;
$$

create policy restock_alerts_self_read on public.restock_alerts
  for select to authenticated
  using ((select auth.uid()) = user_id)

-- 신청·재신청. 품절 판정과 upsert 를 한 트랜잭션에서 goods 행 잠금(for share)과 함께
-- 수행한다 — 판정과 신청 사이에 재입고 전이(goods UPDATE, for update)가 끼어들면
-- 트리거는 신청자를 못 보고 신청은 pending 으로 남아 다음 사이클까지 침묵하는
-- 경합이 있었다. 잠금으로 전이 트랜잭션과 직렬화한다.
create function public.request_restock_alert(target_good_id text)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  good_stock text;
  good_stock_qty integer;
  good_archived_at timestamptz;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  select stock, stock_qty, archived_at
  into good_stock, good_stock_qty, good_archived_at
  from public.goods
  where id = target_good_id
  for share;

  if not found or good_archived_at is not null then
    raise exception 'good_missing' using errcode = 'P0002';
  end if;

  -- 판매 가능 술어는 앱 표시·카트·주문 게이트와 같다. 판매 중인 굿즈에 신청이
  -- 붙으면 전이 조건(거짓→참)이 영영 성립하지 않아 신청자가 기다리다 끝난다.
  if good_stock <> 'soldout' and good_stock_qty > 0 then
    raise exception 'good_available' using errcode = '22023';
  end if;

  insert into public.restock_alerts (user_id, good_id)
  values (actor_id, target_good_id)
  on conflict (user_id, good_id)
  do update set status = 'pending', notified_at = null, created_at = now();
end;
$$

-- 알림함 type 에 restock_available 을 덧붙인다. 목록을 통째로 다시 쓰면 브랜치가
-- 갈라졌을 때 다른 타입을 조용히 지우므로, 기존 정의를 읽어 덧붙인다
-- (20260818130001 goods_reviews 의 확장 패턴).
do $$
declare
  v_def text;
  v_values text;
begin
  select pg_get_constraintdef(constraint_row.oid)
  into strict v_def
  from pg_catalog.pg_constraint as constraint_row
  where constraint_row.conrelid = 'public.notifications'::regclass
    and constraint_row.conname = 'notifications_type_check';

  select string_agg(distinct quote_literal(matched[1]), ', ')
  into v_values
  from regexp_matches(v_def, '''([a-z_]+)''::text', 'g') as matched;

  if v_values is null then
    raise exception 'notifications_type_check has no readable type list';
  end if;

  if position('''restock_available''' in v_values) = 0 then
    v_values := v_values || ', ' || quote_literal('restock_available');
  end if;

  execute 'alter table public.notifications drop constraint notifications_type_check';
  execute format(
    'alter table public.notifications add constraint notifications_type_check check (type in (%s))',
    v_values
  );
end;
$$

-- 트랜잭셔널 메일 template 에 restock_alert 를 덧붙인다. CHECK 는 이름을 정의로
-- 찾아 지우고(20260818110000 의 주의문 — 이름을 짐작해 drop 하면 실제 이름이 다를 때
-- 조용히 남는다), 클레임 함수 본문의 허용 목록도 함께 넓힌다 — CHECK 만 넓히면
-- invalid_email_template 로 한 통도 나가지 않는다.
do $$
declare
  v_name text;
begin
  select constraint_check.conname
  into v_name
  from pg_catalog.pg_constraint as constraint_check
  where constraint_check.conrelid = 'public.email_deliveries'::regclass
    and constraint_check.contype = 'c'
    and pg_catalog.pg_get_constraintdef(constraint_check.oid) like '%order_confirmation%';

  if v_name is null then
    raise exception 'email_deliveries template check not found';
  end if;

  execute pg_catalog.format(
    'alter table public.email_deliveries drop constraint %I',
    v_name
  );
end;
$$

create or replace function public.claim_email_delivery(
  target_dedupe_key text,
  target_template text,
  target_recipient text,
  target_subject text,
  target_retry_after interval default interval '10 minutes'
)
returns boolean
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  normalized_key text := btrim(coalesce(target_dedupe_key, ''), E' \t\n\r\f\v');
  normalized_subject text := btrim(coalesce(target_subject, ''), E' \t\n\r\f\v');
  normalized_recipient text := btrim(coalesce(target_recipient, ''), E' \t\n\r\f\v');
  existing record;
begin
  if char_length(normalized_key) < 1 or char_length(normalized_key) > 200 then
    raise exception 'invalid_dedupe_key' using errcode = '22023';
  end if;
  if target_template is null
    or target_template not in ('order_confirmation', 'order_shipped', 'inquiry_answered', 'restock_alert')
  then
    raise exception 'invalid_email_template' using errcode = '22023';
  end if;
  if char_length(normalized_recipient) < 3 or char_length(normalized_recipient) > 320 then
    raise exception 'invalid_email_recipient' using errcode = '22023';
  end if;
  if char_length(normalized_subject) < 1 or char_length(normalized_subject) > 200 then
    raise exception 'invalid_email_subject' using errcode = '22023';
  end if;

  -- 응답이 유실된 재시도는 먼저 커밋된 클레임을 관측한 뒤에 판단해야 한다.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('email_delivery:' || normalized_key, 0)
  );

  select delivery.id, delivery.status, delivery.attempt_count, delivery.claimed_at
    into existing
  from public.email_deliveries as delivery
  where delivery.dedupe_key = normalized_key
  for update;

  if found then
    if existing.status = 'sent' then
      return false;
    end if;
    if existing.status = 'pending'
      and existing.claimed_at > now() - coalesce(target_retry_after, interval '10 minutes')
    then
      return false;
    end if;
    if existing.attempt_count >= 1000 then
      return false;
    end if;

    update public.email_deliveries
    set
      status = 'pending',
      attempt_count = existing.attempt_count + 1,
      subject = normalized_subject,
      recipient = normalized_recipient,
      claimed_at = now(),
      completed_at = null
    where id = existing.id;

    return true;
  end if;

  insert into public.email_deliveries (
    dedupe_key,
    template,
    recipient,
    subject,
    status
  )
  values (
    normalized_key,
    target_template,
    normalized_recipient,
    normalized_subject,
    'pending'
  );

  return true;
end;
$$

create trigger coupons_set_updated_at
before update on public.coupons
for each row execute function public.set_updated_at()

-- 쿠폰 정의 공개 조회를 열면 코드가 열거된다. 보유자와 staff에게만 보인다.
create policy coupons_select_held_or_staff on public.coupons
  for select using (
    public.is_staff()
    or exists (
      select 1
      from public.user_coupons as held
      where held.coupon_code = coupons.code
        and held.user_id = (select auth.uid())
    )
  )

create policy user_coupons_select_own_or_staff on public.user_coupons
  for select using (
    user_id = (select auth.uid()) or public.is_staff()
  )

create policy coupon_redemptions_select_own_or_staff on public.coupon_redemptions
  for select using (
    user_id = (select auth.uid()) or public.is_staff()
  )

-- 보유 쿠폰 하나를 소계에 대해 평가한다. o_reason이 null이면 사용 가능하고
-- o_discount가 확정 할인액이다. 적용(apply)과 주문 확정(place_order)이 같은
-- 판정을 공유해야 "카트에서는 됐는데 주문에서 다른 이유" 같은 어긋남이 없다.
-- 행 잠금은 호출부 책임이다 — 이 함수는 판정만 한다.
create function private.evaluate_user_coupon(
  p_user_coupon_id uuid,
  p_user_id uuid,
  p_subtotal bigint,
  out o_reason text,
  out o_discount bigint,
  out o_coupon_code text
)
returns record
language plpgsql
stable
set search_path = ''
as $$
declare
  v_held record;
  v_coupon record;
begin
  o_reason := null;
  o_discount := 0;
  o_coupon_code := null;

  select held.coupon_code, held.user_id, held.status, held.expires_at
  into v_held
  from public.user_coupons as held
  where held.id = p_user_coupon_id;

  if not found or v_held.user_id is distinct from p_user_id then
    o_reason := 'coupon_not_owned';
    return;
  end if;

  o_coupon_code := v_held.coupon_code;

  if v_held.status = 'used' then
    o_reason := 'coupon_already_used';
    return;
  end if;

  select coupon.status, coupon.starts_at, coupon.ends_at, coupon.min_subtotal,
         coupon.discount_type, coupon.discount_value, coupon.max_discount_amount
  into v_coupon
  from public.coupons as coupon
  where coupon.code = v_held.coupon_code;

  if not found or v_coupon.status <> 'active' then
    o_reason := 'coupon_not_found';
    return;
  end if;

  if now() < v_coupon.starts_at then
    o_reason := 'coupon_not_started';
    return;
  end if;

  if (v_coupon.ends_at is not null and now() > v_coupon.ends_at)
     or (v_held.expires_at is not null and now() > v_held.expires_at) then
    o_reason := 'coupon_expired';
    return;
  end if;

  if p_subtotal < v_coupon.min_subtotal then
    o_reason := 'coupon_min_subtotal';
    return;
  end if;

  -- 할인은 상품 소계에만 적용된다(배송비 제외 — R-05 §4.4). 정액도 정률 상한도
  -- 소계를 넘지 못하므로 total은 음수가 될 수 없다.
  if v_coupon.discount_type = 'fixed' then
    o_discount := least(v_coupon.discount_value::bigint, p_subtotal);
  else
    o_discount := least(
      (p_subtotal * v_coupon.discount_value::bigint) / 100,
      coalesce(v_coupon.max_discount_amount::bigint, p_subtotal),
      p_subtotal
    );
  end if;
end;
$$

-- ── 사용자 RPC: 발급·카트 적용·해제 ─────────────────────────────────────────

-- 코드 직접 입력: 미보유면 발급까지, 보유면 적용만 — 카트의 "직접 입력"과
-- 캠페인 경품 코드(S8)가 같은 문을 지난다. place_order와 같은 사용자 advisory
-- lock을 잡아 주문 생성 중의 선택 교체 경합을 직렬화한다.
create function public.apply_cart_coupon_code(p_code text)
returns uuid
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := (select auth.uid());
  v_code text;
  v_coupon record;
  v_user_coupon_id uuid;
  v_subtotal bigint;
  v_eval record;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  v_code := upper(btrim(coalesce(p_code, '')));
  if v_code = '' then
    raise check_violation using message = 'coupon_not_found';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  -- 발급 한도 경합은 쿠폰 행 잠금으로 직렬화한다.
  select coupon.code, coupon.status, coupon.starts_at, coupon.ends_at,
         coupon.issue_limit, coupon.issued_count
  into v_coupon
  from public.coupons as coupon
  where coupon.code = v_code
  for update;

  -- 없는 코드와 보관된 코드는 같은 사유로 답한다 — 코드 존재를 노출하지 않는다.
  if not found or v_coupon.status <> 'active' then
    raise check_violation using message = 'coupon_not_found';
  end if;

  if now() < v_coupon.starts_at then
    raise check_violation using message = 'coupon_not_started';
  end if;

  if v_coupon.ends_at is not null and now() > v_coupon.ends_at then
    raise check_violation using message = 'coupon_expired';
  end if;

  select held.id into v_user_coupon_id
  from public.user_coupons as held
  where held.coupon_code = v_code and held.user_id = v_user;

  if v_user_coupon_id is null then
    if v_coupon.issue_limit is not null and v_coupon.issued_count >= v_coupon.issue_limit then
      raise check_violation using message = 'coupon_exhausted';
    end if;

    update public.coupons
    set issued_count = issued_count + 1
    where code = v_code;

    insert into public.user_coupons (coupon_code, user_id, issued_source, expires_at)
    values (v_code, v_user, 'code_entry', v_coupon.ends_at)
    returning id into v_user_coupon_id;
  end if;

  -- 최소 주문 금액 미달은 발급·선택을 막지 않는다 — 더 담으면 살아나는 선택이고,
  -- 확정 거부는 place_order 가 한다(카트가 미달 경고를 그린다). 그 밖의 사유
  -- (만료·사용됨 등)는 쓸 수 없는 선택이므로 여기서 거부한다.
  v_subtotal := private.cart_subtotal(v_user);
  select * into v_eval from private.evaluate_user_coupon(v_user_coupon_id, v_user, v_subtotal);
  if v_eval.o_reason is not null and v_eval.o_reason <> 'coupon_min_subtotal' then
    raise check_violation using message = v_eval.o_reason;
  end if;

  insert into public.cart_coupon_selections (user_id, user_coupon_id)
  values (v_user, v_user_coupon_id)
  on conflict (user_id) do update set
    user_coupon_id = excluded.user_coupon_id,
    created_at = now();

  return v_user_coupon_id;
end;
$$

-- 보유 쿠폰을 카트에 적용한다(쿠폰 select 경로).
create function public.apply_cart_coupon(p_user_coupon_id uuid)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := (select auth.uid());
  v_subtotal bigint;
  v_eval record;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if p_user_coupon_id is null then
    raise check_violation using message = 'coupon_not_owned';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  -- 코드 입력과 같은 계약: 최소 금액 미달만은 선택으로 받아들인다.
  v_subtotal := private.cart_subtotal(v_user);
  select * into v_eval from private.evaluate_user_coupon(p_user_coupon_id, v_user, v_subtotal);
  if v_eval.o_reason is not null and v_eval.o_reason <> 'coupon_min_subtotal' then
    raise check_violation using message = v_eval.o_reason;
  end if;

  insert into public.cart_coupon_selections (user_id, user_coupon_id)
  values (v_user, p_user_coupon_id)
  on conflict (user_id) do update set
    user_coupon_id = excluded.user_coupon_id,
    created_at = now();
end;
$$

create function public.clear_cart_coupon()
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  delete from public.cart_coupon_selections where user_id = v_user;
end;
$$

-- ── 주문 생성 할인 통합 ─────────────────────────────────────────────────────

-- 20260818140001의 본문에 쿠폰 확정 블록만 더한 재정의다. 시그니처·기존 검증·
-- 재고 흐름·멱등 계약은 그대로다 — 쿠폰 선택이 없으면 금액 경로는 한 줄도
-- 다르게 동작하지 않는다(checkout_order.sql 회귀가 이를 지킨다).
create or replace function public.place_order(
  p_address jsonb,
  p_checkout_key uuid,
  p_payment_method public.order_payment_method
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  -- lib/shipping.ts의 SHIPPING_FEE · FREE_SHIPPING_THRESHOLD와 같은 값이어야 한다.
  c_shipping_fee constant bigint := 3000;
  c_free_shipping_threshold constant bigint := 50000;
  -- 결제사 최소 결제액(20260813242000 가드·lib/coupons.ts MIN_PAYABLE_TOTAL와 동치).
  -- 할인이 총액을 이 밑으로 내리면 가드가 주문 전체를 롤백하므로, 여기서 캡한다.
  c_min_payable_total constant bigint := 1000;
  v_user uuid := (select auth.uid());
  v_order uuid;
  v_existing_address jsonb;
  v_existing_payment_method public.order_payment_method;
  v_expires_at timestamptz;
  v_subtotal bigint := 0;
  v_shipping_fee bigint := 0;
  v_item_count integer := 0;
  v_recipient_name text;
  v_phone text;
  v_postal_code text;
  v_address1 text;
  v_optional text;
  v_selected_coupon uuid;
  v_coupon_eval record;
  v_discount bigint := 0;
  r record;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if not exists (
    select 1
    from public.profiles as profile
    join auth.users as auth_user on auth_user.id = profile.id
    where profile.id = v_user
      and nullif(btrim(coalesce(profile.email, auth_user.email)), '') is not null
      and nullif(btrim(profile.nickname), '') is not null
      and profile.birth_date is not null
      and profile.birth_date <= current_date
      and profile.onboarded_at is not null
      and profile.consents ->> 'terms' = 'true'
      and profile.consents ->> 'privacy' = 'true'
  ) then
    raise insufficient_privilege using message = 'onboarding required';
  end if;

  if p_checkout_key is null then
    raise not_null_violation using message = 'checkout key required';
  end if;

  if p_address is null or jsonb_typeof(p_address) <> 'object' then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if not (p_address ?& array['recipientName', 'phone', 'postalCode', 'address1'])
     or exists (
       select 1
       from jsonb_object_keys(p_address) as address_key(key)
       where address_key.key not in (
         'recipientName', 'phone', 'postalCode', 'address1', 'address2', 'deliveryNote'
       )
     )
     or exists (
       select 1
       from jsonb_each(p_address) as address_value(key, value)
       where jsonb_typeof(address_value.value) <> 'string'
     ) then
    raise check_violation using message = 'invalid checkout address';
  end if;

  v_recipient_name := p_address ->> 'recipientName';
  v_phone := p_address ->> 'phone';
  v_postal_code := p_address ->> 'postalCode';
  v_address1 := p_address ->> 'address1';

  if v_recipient_name <> btrim(v_recipient_name, E' \t\n\r\f\v')
     or length(v_recipient_name) not between 1 and 50
     or v_phone !~ '^[0-9]{8,15}$'
     or v_postal_code !~ '^[0-9]{5}$'
     or v_address1 <> btrim(v_address1, E' \t\n\r\f\v')
     or length(v_address1) not between 1 and 200 then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if p_address ? 'address2' then
    v_optional := p_address ->> 'address2';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  if p_address ? 'deliveryNote' then
    v_optional := p_address ->> 'deliveryNote';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  -- 같은 사용자의 다른 탭 주문을 직렬화한다. 동일 키 재시도는 먼저 생성된
  -- 주문을 반환하고, 다른 키는 첫 주문이 비운 장바구니를 확인하게 된다.
  -- 쿠폰 적용·해제도 같은 잠금을 잡으므로 선택 교체와 소비가 경합하지 않는다.
  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  select orders.id, orders.address, orders.payment_method
    into v_order, v_existing_address, v_existing_payment_method
  from public.orders
  where orders.user_id = v_user
    and orders.checkout_key = p_checkout_key;

  if found then
    -- 같은 checkout key로 결제수단만 바꿔 다시 부르면 24시간 선점을 15분 주문에
    -- 덧씌우거나 그 반대가 된다. 주소와 같은 등급의 충돌로 막는다.
    if v_existing_address is distinct from p_address
      or v_existing_payment_method is distinct from p_payment_method
    then
      raise unique_violation using message = 'checkout key conflict';
    end if;
    return v_order;
  end if;

  -- 카드 15분 · 무통장 24시간. 무통장은 사람이 은행 앱을 열고 이체할 시간을
  -- 줘야 해서 선점 창이 길고, 그만큼 재고가 오래 묶인다 — 한정 드롭은
  -- goods.allow_bank_transfer로 아예 차단한다(ADR-0007).
  v_expires_at := case
    when p_payment_method = 'bank_transfer' then now() + interval '24 hours'
    else now() + interval '15 minutes'
  end;

  insert into public.orders (
    user_id, status, total, shipping_fee, address, expires_at, checkout_key, payment_method
  )
  values (v_user, 'pending', 0, 0, p_address, v_expires_at, p_checkout_key, p_payment_method)
  returning id into v_order;

  -- 카트와 재고를 같은 결정적 순서로 잠근 뒤 DB 값만으로 주문 스냅샷을 만든다.
  for r in
    select
      cart.good_id,
      cart.qty,
      good.price,
      good.stock,
      good.stock_qty,
      good.name,
      good.type,
      good.ip_id,
      good.allow_bank_transfer
    from public.cart_items as cart
    join public.goods as good on good.id = cart.good_id
    where cart.user_id = v_user
    order by cart.good_id
    for update of cart, good
  loop
    v_item_count := v_item_count + 1;

    if r.stock = 'soldout' or r.stock_qty < r.qty then
      raise check_violation using message = format('out of stock: %s', r.good_id);
    end if;

    if p_payment_method = 'bank_transfer' and not r.allow_bank_transfer then
      raise check_violation using message = format('bank transfer blocked: %s', r.good_id);
    end if;

    update public.goods
    set stock_qty = stock_qty - r.qty
    where id = r.good_id;

    insert into public.order_items (
      order_id,
      good_id,
      qty,
      unit_price,
      good_name_snapshot,
      good_type_snapshot,
      good_ip_id_snapshot
    )
    values (
      v_order,
      r.good_id,
      r.qty,
      r.price,
      r.name,
      r.type,
      r.ip_id
    );

    -- 조회 시 잠근 스냅샷 행만 지운다. 동시에 새로 담긴 다른 상품까지
    -- 마지막 broad delete가 없애지 않도록 상품 단위로 소비한다.
    delete from public.cart_items
    where user_id = v_user
      and good_id = r.good_id;

    v_subtotal := v_subtotal + (r.price::bigint * r.qty::bigint);
  end loop;

  if v_item_count = 0 then
    raise check_violation using message = 'cart empty';
  end if;

  -- 배송비 판정은 할인 전 소계 기준이다 — 쿠폰이 무료배송 경계를 흔들면
  -- 카트의 "얼마 더 담으면 무료배송" 안내가 거짓말이 된다.
  if v_subtotal > 0 and v_subtotal < c_free_shipping_threshold then
    v_shipping_fee := c_shipping_fee;
  end if;

  -- 카트에 적용해 둔 쿠폰을 여기서 최종 검증하고 소비한다. 조건 미달이면 주문
  -- 전체를 거부한다 — 할인을 기대한 사용자를 조용히 정가로 결제시키지 않는다.
  select selection.user_coupon_id
  into v_selected_coupon
  from public.cart_coupon_selections as selection
  where selection.user_id = v_user;

  if v_selected_coupon is not null then
    -- 상태 전이 전에 보유 행을 잠근다. 같은 유저는 advisory lock으로 이미
    -- 직렬화되어 있고, 이 잠금은 향후 다른 경로가 생겨도 이중 사용을 막는 안전벨트다.
    perform held.id
    from public.user_coupons as held
    where held.id = v_selected_coupon
    for update;

    select * into v_coupon_eval
    from private.evaluate_user_coupon(v_selected_coupon, v_user, v_subtotal);
    if v_coupon_eval.o_reason is not null then
      raise check_violation using message = v_coupon_eval.o_reason;
    end if;
    -- 결제사 최소 결제액을 지키도록 할인을 캡한다 — 전액 쿠폰이 주문을
    -- 결제 불가(총액 < 1,000원)로 만들면 혜택이 주문 실패로 둔갑한다.
    v_discount := least(
      v_coupon_eval.o_discount,
      greatest(0, v_subtotal + v_shipping_fee - c_min_payable_total)
    );

    update public.user_coupons
    set status = 'used',
        used_at = now(),
        used_order_id = v_order
    where id = v_selected_coupon;

    insert into public.coupon_redemptions (
      user_coupon_id, coupon_code, user_id, order_id, discount_amount
    )
    values (
      v_selected_coupon, v_coupon_eval.o_coupon_code, v_user, v_order, v_discount
    );

    -- 소비한 선택만 지운다. 주문 진행 중 다른 탭이 교체한 새 선택은 남는다.
    delete from public.cart_coupon_selections
    where user_id = v_user
      and user_coupon_id = v_selected_coupon;
  end if;

  update public.orders
  set total = v_subtotal + v_shipping_fee - v_discount,
      shipping_fee = v_shipping_fee,
      discount_total = v_discount
  where id = v_order;

  -- 무통장에는 결제사 왕복이 없다. 그래서 원장 anchor(payment_attempts)를 여기서
  -- 바로 연다 — 없으면 운영자가 입금을 확인할 대상 자체가 없고, "결제 준비" 버튼을
  -- 눌러야 생기는 구조는 구매자가 이미 이체한 뒤에도 확인이 안 되는 창을 만든다.
  -- 새 함수를 두지 않고 카드와 같은 prepare를 부른다: 소유권·금액·스냅샷·정지
  -- 계정 검사가 한 곳에만 있어야 한다.
  if p_payment_method = 'bank_transfer' then
    perform public.prepare_goods_payment_attempt(v_user, v_order, 'bank_transfer');
  end if;

  -- 무통장 주문은 만든 순간이 안내 시점이다. 금액·입금자명 코드·기한이 모두
  -- 정해졌고, 이 알림을 놓치면 구매자는 어디로 얼마를 보낼지 알 수 없다.
  if p_payment_method = 'bank_transfer' then
    insert into public.notifications (
      user_id, type, title, body, link_path, source_type, source_id, dedupe_key
    )
    values (
      v_user,
      'order_bank_transfer_pending',
      '입금 안내를 확인해주세요',
      format(
        '%s원을 기한 안에 입금해주세요. 입금자명 끝에 주문코드 %s를 붙이면 확인이 빨라집니다.',
        to_char(v_subtotal + v_shipping_fee - v_discount, 'FM999,999,999'),
        private.bank_transfer_deposit_code(v_order)
      ),
      '/checkout/' || v_order::text,
      'order',
      v_order::text,
      'order:bank_transfer_pending:' || v_order::text
    )
    on conflict (user_id, dedupe_key) do nothing;
  end if;

  return v_order;
end;
$$

revoke all on function public.admin_upsert_coupon(
  text, text, text, integer, integer, integer, timestamptz, timestamptz, integer, text, text
) from public, anon, authenticated, service_role

grant execute on function public.admin_upsert_coupon(
  text, text, text, integer, integer, integer, timestamptz, timestamptz, integer, text, text
) to authenticated

create policy loyalty_grade_events_select_own_or_staff on public.loyalty_grade_events
  for select using (
    user_id = (select auth.uid()) or public.is_staff()
  )

-- 등급 승급 알림 type 등록. 목록을 통째로 다시 쓰지 않고 기존 정의에 덧붙인다 —
-- 다른 마이그레이션이 넣은 값을 지우면 알림 발급이 조용히 깨진다.
do $$
declare
  v_def text;
  v_values text;
begin
  select pg_get_constraintdef(constraint_row.oid)
  into strict v_def
  from pg_catalog.pg_constraint as constraint_row
  where constraint_row.conrelid = 'public.notifications'::regclass
    and constraint_row.conname = 'notifications_type_check';

  select string_agg(distinct quote_literal(matched[1]), ', ')
  into v_values
  from regexp_matches(v_def, '''([a-z_]+)''::text', 'g') as matched;

  if position('''loyalty_grade_upgraded''' in v_values) = 0 then
    v_values := v_values || ', ' || quote_literal('loyalty_grade_upgraded');
  end if;

  execute 'alter table public.notifications drop constraint notifications_type_check';
  execute format(
    'alter table public.notifications add constraint notifications_type_check check (type in (%s))',
    v_values
  );
end;
$$

-- 실적을 다시 계산해 등급을 맞춘다. 승급이면 혜택·알림까지, 강등이면 이력만
-- 남기고 조용히 내린다(이미 발급된 혜택은 회수하지 않는다). 멱등 — 같은 실적
-- 재실행은 아무것도 바꾸지 않는다.
create function private.recalculate_loyalty_grade(p_user_id uuid)
returns public.loyalty_grade
language plpgsql
volatile
set search_path = ''
as $$
declare
  c_window constant interval := interval '90 days';
  v_current public.loyalty_grade;
  v_spend bigint;
  v_manual_floor public.loyalty_grade;
  v_next public.loyalty_grade;
begin
  -- 같은 유저의 동시 재산정(두 주문이 동시에 paid)을 직렬화한다.
  select profile.loyalty_grade
  into v_current
  from public.profiles as profile
  where profile.id = p_user_id
  for update;

  if not found then
    return null;
  end if;

  -- 실적 = 창 안에서 결제 확정(paid 이후 상태) 상태로 남아 있는 주문의 총
  -- 청구액. 취소는 상태가 canceled로 빠지며 자동 차감된다.
  select coalesce(sum(order_row.total), 0)
  into v_spend
  from public.orders as order_row
  where order_row.user_id = p_user_id
    and order_row.status in ('paid', 'confirmed', 'shipping', 'delivered', 'done')
    and order_row.created_at >= now() - c_window;

  -- 창 안의 수동 보정은 재산정의 바닥이다 — 오프라인 실적 보정이 다음 온라인
  -- 주문 한 건에 지워지면 안 된다(감사 이벤트가 그 근거다). 창을 벗어난 보정은
  -- 온라인 실적과 같은 규칙으로 소멸한다.
  select event.next_grade
  into v_manual_floor
  from public.loyalty_grade_events as event
  where event.user_id = p_user_id
    and event.reason = 'manual_adjustment'
    and event.created_at >= now() - c_window
  order by event.created_at desc
  limit 1;

  v_next := greatest(
    private.loyalty_grade_for_spend(v_spend),
    coalesce(v_manual_floor, 'welcome'::public.loyalty_grade)
  );

  if v_next = v_current then
    return v_current;
  end if;

  update public.profiles
  set loyalty_grade = v_next
  where id = p_user_id;

  insert into public.loyalty_grade_events (user_id, previous_grade, next_grade, reason, basis)
  values (
    p_user_id, v_current, v_next, 'recalculation',
    jsonb_build_object('spend', v_spend, 'windowDays', 90)
  );

  if v_next > v_current then
    perform private.grant_grade_benefit_coupons(p_user_id, v_current, v_next);

    -- 강등 후 재승급도 알림 가치가 있다 — 같은 dedupe 키는 재부상시킨다.
    insert into public.notifications (
      user_id, type, title, body, link_path, source_type, source_id, dedupe_key
    )
    values (
      p_user_id,
      'loyalty_grade_upgraded',
      '회원 등급이 올랐어요',
      format('%s 등급이 되었어요. 등급 혜택 쿠폰은 쿠폰함에서 확인할 수 있어요.', upper(v_next::text)),
      '/my/coupons',
      'profile',
      p_user_id::text,
      'loyalty:upgrade:' || p_user_id::text || ':' || v_next::text
    )
    on conflict (user_id, dedupe_key) do update set
      read_at = null,
      created_at = now();
  end if;

  return v_next;
end;
$$

-- ── 어드민: 수동 보정·재산정 ────────────────────────────────────────────────

-- 오프라인 실적·분쟁 대응용 수동 보정. 산정과 같은 혜택 경로를 지나고,
-- 이벤트와 audit_log 양쪽에 근거를 남긴다.
create function public.admin_adjust_loyalty_grade(
  p_user_id uuid,
  p_grade public.loyalty_grade,
  p_note text
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  v_current public.loyalty_grade;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if v_note is null then
    raise check_violation using message = 'note_required';
  end if;

  select profile.loyalty_grade
  into v_current
  from public.profiles as profile
  where profile.id = p_user_id
  for update;

  if not found then
    raise exception 'member_missing' using errcode = 'P0002';
  end if;

  if v_current is distinct from p_grade then
    update public.profiles
    set loyalty_grade = p_grade
    where id = p_user_id;

    insert into public.loyalty_grade_events (
      user_id, previous_grade, next_grade, reason, actor_id, note
    )
    values (p_user_id, v_current, p_grade, 'manual_adjustment', actor_id, v_note);

    -- 수동 승급도 자동 산정과 같은 대우다(US7) — 혜택 쿠폰과 승급 알림을 함께 준다.
    if p_grade > v_current then
      perform private.grant_grade_benefit_coupons(p_user_id, v_current, p_grade);

      insert into public.notifications (
        user_id, type, title, body, link_path, source_type, source_id, dedupe_key
      )
      values (
        p_user_id,
        'loyalty_grade_upgraded',
        '회원 등급이 올랐어요',
        format('%s 등급이 되었어요. 등급 혜택 쿠폰은 쿠폰함에서 확인할 수 있어요.', upper(p_grade::text)),
        '/my/coupons',
        'profile',
        p_user_id::text,
        'loyalty:upgrade:' || p_user_id::text || ':' || p_grade::text
      )
      on conflict (user_id, dedupe_key) do update set
        read_at = null,
        created_at = now();
    end if;
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'loyalty.grade.adjust',
    'profiles:' || p_user_id::text,
    jsonb_build_object('from', v_current, 'to', p_grade, 'note', v_note)
  );
end;
$$

-- 트리거가 삼킨 실패를 사람 손으로 따라잡는 복구 경로(분쟁 대응 포함).
create function public.admin_recalculate_loyalty_grade(p_user_id uuid)
