-- ── 사용자 RPC: 출석 ────────────────────────────────────────────────────────

-- 일일 경계는 Asia/Seoul 자정이다(참여형 게임 일일 한도와 같은 정의 —
-- 20260707093001). UTC 자정을 쓰면 한국 사용자에게 오전 9시 리셋으로 보인다.
create function public.attendance_check_in()
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_today date;
  v_inserted integer;
  v_balance integer;
begin
  if v_user is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_user
      and profile.suspended_at is not null
  ) then
    raise exception 'account_suspended' using errcode = '55000';
  end if;

  -- 탈퇴 신청으로 쓰기가 봉인된 계정. 적립은 삭제 대상 계정에 새 잔액을 만드는
  -- 일이고, 그 잔액은 교환으로만 빠져나간다 — 봉인 뒤에 새로 생기면 안 된다
  -- (20260813193000 의 계정 fence 관례를 그대로 미러한다).
  if private.is_account_write_fenced(v_user) then
    raise object_not_in_prerequisite_state
      using message = 'account_deletion_write_fenced';
  end if;

  v_today := (now() at time zone 'Asia/Seoul')::date;

  -- 같은 날 두 번째 호출은 아무것도 바꾸지 않는다. 경합하는 두 탭도 PK가
  -- 직렬화한다 — 하나만 원장을 남기고 다른 하나는 already_checked를 받는다.
  insert into public.coin_attendance (user_id, attended_on)
  values (v_user, v_today)
  on conflict (user_id, attended_on) do nothing;

  get diagnostics v_inserted = row_count;

  if v_inserted = 0 then
    select balance into v_balance
    from public.coin_balances
    where user_id = v_user;

    return jsonb_build_object(
      'status', 'already_checked',
      'balance', coalesce(v_balance, 0),
      'attended_on', v_today
    );
  end if;

  insert into public.coin_ledger (user_id, amount, reason, attended_on)
  values (v_user, 1, 'attendance', v_today);

  insert into public.coin_balances (user_id, balance)
  values (v_user, 1)
  on conflict (user_id) do update set
    balance = coin_balances.balance + 1,
    updated_at = now()
  returning balance into v_balance;

  return jsonb_build_object(
    'status', 'checked',
    'balance', v_balance,
    'attended_on', v_today
  );
end;
$$

-- ── 사용자 RPC: 코인 → 카드팩 교환 ─────────────────────────────────────────

-- 이 함수의 핵심 불변식: 코인이 빠졌으면 카드팩도 반드시 발급됐다.
--
-- 전역 카드 리워드 게이트가 OFF면 BEFORE INSERT 트리거가 draw_tickets 행을
-- 삼킨다(예외를 던지지 않는다 — 결제 확정을 깨지 않으려는 설계). 삽입 행 수를
-- 세지 않으면 그 침묵이 코인만 소각하는 결과로 나타난다.
create function public.exchange_coins_for_draw_tickets(
  p_operation_id uuid,
  p_offer_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_offer public.coin_exchange_offers%rowtype;
  v_ledger_owner uuid;
  v_ledger_offer uuid;
  v_balance integer;
  v_issued integer;
  v_existing_count integer;
begin
  if v_user is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_user
      and profile.suspended_at is not null
  ) then
    raise exception 'account_suspended' using errcode = '55000';
  end if;

  -- 탈퇴 신청으로 쓰기가 봉인된 계정(20260813193000 의 계정 fence 관례).
  if private.is_account_write_fenced(v_user) then
    raise object_not_in_prerequisite_state
      using message = 'account_deletion_write_fenced';
  end if;

  if p_operation_id is null then
    raise exception 'invalid_operation' using errcode = '22004';
  end if;

  -- 응답이 유실된 재시도는 먼저 커밋된 원장을 관측한 뒤에 판단해야 한다
  -- (admin_grant_draw_tickets와 같은 관용구). 잠금이 없으면 두 재시도가 모두
  -- "없음"을 보고 각자 차감한 뒤 하나가 unique 위반으로 되돌아간다.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('coin_exchange:' || p_operation_id::text, 0)
  );

  select ledger.user_id, ledger.offer_id
    into v_ledger_owner, v_ledger_offer
  from public.coin_ledger as ledger
  where ledger.operation_id = p_operation_id;

  if found then
    -- 남의 멱등 키를 재생해 잔액·발급 수를 읽어 가는 경로를 막는다.
    if v_ledger_owner is distinct from v_user then
      raise exception 'exchange_operation_conflict' using errcode = '23505';
    end if;

    -- 같은 키인데 다른 상품이면 재시도가 아니라 다른 요청이다. 캠페인 한 장에
    -- 교환 블록이 여러 개일 때 화면이 키를 공유하면 여기로 온다 — already_exchanged
    -- 로 답하면 두 번째 상품은 교환되지 않았는데 성공으로 읽힌다.
    if v_ledger_offer is distinct from p_offer_id then
      raise exception 'exchange_operation_conflict' using errcode = '23505',
        detail = 'operation_id is bound to a different offer';
    end if;

    select coalesce(balance, 0) into v_balance
    from public.coin_balances
    where user_id = v_user;

    select count(*)::integer into v_existing_count
    from public.draw_tickets as ticket
    where ticket.source = 'coin_exchange'
      and ticket.source_id = p_operation_id;

    return jsonb_build_object(
      'status', 'already_exchanged',
      'balance', coalesce(v_balance, 0),
      'issued_count', v_existing_count
    );
  end if;

  select offer.*
    into v_offer
  from public.coin_exchange_offers as offer
  where offer.id = p_offer_id
  for share;

  if not found or v_offer.status <> 'active' then
    raise exception 'offer_unavailable' using errcode = 'P0002';
  end if;

  perform private.assert_card_pool_ready(v_offer.pool_id);

  -- 직렬화 지점. 두 세션이 같은 잔액을 노리면 뒤에 온 쪽은 잠금 해제 후 갱신된
  -- 행으로 조건을 다시 평가해 0행을 얻는다 — 초과 인출이 성립할 창이 없다.
  update public.coin_balances
  set balance = balance - v_offer.coin_cost,
      updated_at = now()
  where user_id = v_user
    and balance >= v_offer.coin_cost
  returning balance into v_balance;

  if not found then
    raise exception 'insufficient_coins';
  end if;

  insert into public.coin_ledger (user_id, amount, reason, operation_id, offer_id)
  values (v_user, -v_offer.coin_cost, 'exchange', p_operation_id, v_offer.id);

  -- source_id = operation_id 라서 unique (source, source_id, ordinal)이 재시도
  -- 이중 발급을 DB 레벨에서 한 번 더 막는다.
  insert into public.draw_tickets (user_id, pool_id, source, source_id, ordinal)
  select v_user, v_offer.pool_id, 'coin_exchange', p_operation_id, issue_series.n
  from pg_catalog.generate_series(1, v_offer.ticket_count) as issue_series(n);

  get diagnostics v_issued = row_count;

  -- 게이트가 행을 삼켰다. 코인 차감·원장·잔액까지 전부 되돌린다.
  if v_issued <> v_offer.ticket_count then
    raise exception 'card_rewards_disabled' using errcode = '55000';
  end if;

  -- 알림은 draw_tickets STATEMENT 트리거(20260716090001)가 보낸다. 여기서 직접
  -- 넣으면 발급 한 건에 알림이 두 번 간다.
  return jsonb_build_object(
    'status', 'exchanged',
    'balance', v_balance,
    'issued_count', v_issued
  );
end;
$$

-- ── 어드민: 교환 상품 upsert ────────────────────────────────────────────────

create function public.admin_upsert_coin_exchange_offer(
  target_id uuid,
  target_pool_id uuid,
  target_label text,
  target_coin_cost integer,
  target_ticket_count integer,
  target_status text
)
returns uuid
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_label text := btrim(coalesce(target_label, ''), E' \t\n\r\f\v');
  normalized_status text := coalesce(nullif(btrim(coalesce(target_status, '')), ''), 'active');
  normalized_ticket_count integer := coalesce(target_ticket_count, 1);
  offer_id uuid;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if char_length(normalized_label) not between 1 and 80 then
    raise exception 'invalid_offer_label' using errcode = '22023';
  end if;

  if target_coin_cost is null or target_coin_cost not between 1 and 100000 then
    raise exception 'invalid_offer_coin_cost' using errcode = '22023';
  end if;

  if normalized_ticket_count not between 1 and 10 then
    raise exception 'invalid_offer_ticket_count' using errcode = '22023';
  end if;

  if normalized_status not in ('active', 'disabled') then
    raise exception 'invalid_offer_status' using errcode = '22023';
  end if;

  -- 없는 풀을 가리키는 상품은 캠페인 화면에 "교환 가능"으로 그려진 뒤 교환
  -- 시점에야 실패한다. 등록 시점에 막는다.
  perform 1 from public.card_pools where id = target_pool_id for share;
  if not found then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  if target_id is null then
    insert into public.coin_exchange_offers (pool_id, label, coin_cost, ticket_count, status)
    values (target_pool_id, normalized_label, target_coin_cost, normalized_ticket_count, normalized_status)
    returning id into offer_id;
  else
    update public.coin_exchange_offers
    set pool_id = target_pool_id,
        label = normalized_label,
        coin_cost = target_coin_cost,
        ticket_count = normalized_ticket_count,
        status = normalized_status
    where id = target_id
    returning id into offer_id;

    if not found then
      raise exception 'catalog_record_missing' using errcode = 'P0002';
    end if;
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'coin.exchange_offer.upsert',
    'coin_exchange_offers:' || offer_id::text,
    jsonb_build_object(
      'mode', case when target_id is null then 'create' else 'update' end,
      'after', jsonb_build_object(
        'poolId', target_pool_id,
        'label', normalized_label,
        'coinCost', target_coin_cost,
        'ticketCount', normalized_ticket_count,
        'status', normalized_status
      )
    )
  );

  return offer_id;
end;
$$

-- S8 상품 Q&A (#330): 굿즈 상세의 공개 문의와 운영 답변.
--
-- 리뷰(20260818130001)와 같은 모양의 표면이지만 자격이 정반대다. 리뷰는 "그
-- 굿즈를 실제로 받은 주문"에 매여 있고, Q&A는 사기 전에 묻는 글이라 주문 자격이
-- 없다. 그래서 작성 경로가 RPC가 아니라 RLS insert 정책이다 — 판정할 자격이
-- "로그인했고 정지되지 않았다" 뿐이면 RPC는 껍데기만 늘린다.
--
-- 1:1 문의(inquiries)와도 다르다. 저쪽은 비공개 스레드고 이쪽은 굿즈 상세에
-- 공개로 붙는 한 문답이다. 그래서 답변이 별도 테이블이 아니라 같은 행의
-- answer_* 컬럼이다 — 문답이 1:1이라 스레드 구조를 만들 이유가 없다.

-- ── 알림 type 확장 ──────────────────────────────────────────────────────────
--
-- 목록을 통째로 다시 쓰지 않고 기존 정의에서 값을 읽어 덧붙인다. 손으로 적은
-- 목록은 브랜치가 갈라진 사이에 다른 마이그레이션이 추가한 타입을 조용히 지운다.
do $$
declare
  v_def text;
  v_values text;
begin
  select pg_get_constraintdef(constraint_row.oid)
  into strict v_def
  from pg_catalog.pg_constraint as constraint_row
  where constraint_row.conrelid = 'public.notifications'::regclass
    and constraint_row.conname = 'notifications_type_check';

  select string_agg(distinct quote_literal(matched[1]), ', ')
  into v_values
  from regexp_matches(v_def, '''([a-z_]+)''::text', 'g') as matched;

  if v_values is null then
    raise exception 'notifications_type_check has no readable type list';
  end if;

  if position('''product_question_answered''' in v_values) = 0 then
    v_values := v_values || ', ' || quote_literal('product_question_answered');
  end if;

  execute 'alter table public.notifications drop constraint notifications_type_check';
  execute format(
    'alter table public.notifications add constraint notifications_type_check check (type in (%s))',
    v_values
  );
end;
$$

create trigger product_questions_set_updated_at
before update on public.product_questions
for each row execute function public.set_updated_at()

-- ── 어드민 RPC ──────────────────────────────────────────────────────────────

-- 답변 등록·수정. 재답변은 허용하고, 그때마다 알림을 다시 띄운다 — 답변 내용이
-- 바뀌었는데 조용하면 구매자는 이전 답변을 그대로 믿는다.
create function public.admin_answer_product_question(
  target_question_id uuid,
  target_answer_body text
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_answer text := btrim(coalesce(target_answer_body, ''), E' \t\n\r\f\v');
  v_user_id uuid;
  v_good_id text;
  v_good_name text;
  v_previous text;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if char_length(normalized_answer) not between 1 and 2000 then
    raise exception 'invalid_question_answer' using errcode = '22023';
  end if;

  select question.user_id, question.good_id, question.answer_body
    into v_user_id, v_good_id, v_previous
  from public.product_questions as question
  where question.id = target_question_id
  for update;

  if not found then
    raise exception 'question_not_found' using errcode = 'P0002';
  end if;

  update public.product_questions
  set answer_body = normalized_answer,
      answered_at = now(),
      answered_by = actor_id
  where id = target_question_id;

  select good.name into v_good_name
  from public.goods as good
  where good.id = v_good_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'product_question.answer',
    'product_questions:' || target_question_id::text,
    jsonb_build_object(
      'goodId', v_good_id,
      'isEdit', v_previous is not null,
      'answerLength', char_length(normalized_answer)
    )
  );

  -- body CHECK 상한은 500자다. 굿즈 이름이 길어 알림 insert가 실패하면 답변
  -- 저장까지 함께 되돌아간다 — 이름을 잘라서라도 답변은 남긴다.
  insert into public.notifications (
    user_id, type, title, body, link_path, source_type, source_id, dedupe_key
  )
  values (
    v_user_id,
    'product_question_answered',
    -- 용어 규율(CONTEXT.md): 공개 상품 Q&A를 1:1 '문의'와 섞어 부르지 않는다.
    '상품 Q&A에 답변이 등록됐어요',
    left(coalesce(v_good_name, '굿즈'), 100) || ' 질문에 ICONS 운영자가 답변을 남겼습니다.',
    '/my/questions',
    'product_question',
    target_question_id::text,
    'product_question_answered:' || target_question_id::text
  )
  on conflict (user_id, dedupe_key) do update set
    title = excluded.title,
    body = excluded.body,
    read_at = null,
    created_at = now();
end;
$$

-- 블라인드/해제. 행을 지우지 않고 상태만 바꾼다 — 원문이 남아야 왜 내렸는지
-- 검증할 수 있다.
create function public.admin_set_product_question_visibility(
  target_question_id uuid,
  target_hidden boolean
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  next_status text := case when coalesce(target_hidden, false) then 'hidden' else 'visible' end;
  v_previous text;
  v_good_id text;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select question.status, question.good_id
    into v_previous, v_good_id
  from public.product_questions as question
  where question.id = target_question_id
  for update;

  if not found then
    raise exception 'question_not_found' using errcode = 'P0002';
  end if;

  update public.product_questions
  set status = next_status
  where id = target_question_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'product_question.visibility',
    'product_questions:' || target_question_id::text,
    jsonb_build_object('from', v_previous, 'to', next_status, 'goodId', v_good_id)
  );
end;
$$

-- S8 리뷰 하드닝 (#330 / PR #373): 캠페인·코인·Q&A 도메인이 열어 둔 구멍을
-- 스키마 변경 없이 닫는다.
--
-- 20260831100000~20260831100300은 이미 적용된 마이그레이션이라 고치지 않는다.
-- 여기서는 함수를 재정의하고 트리거를 덧붙이는 방식만 쓴다.
--
-- 다섯 가지를 담는다.
--   1) 교환 RPC가 "실제 노출 경로가 있는 상품"만 받는다.
--   2) 계정 삭제 write fence를 코인·Q&A 테이블 자체에 건다(RPC 밖 경로까지).
--   3) 오프라인 팝업 알림 백필의 나머지 — 제목·본문.
--   4) 캠페인 슬러그를 이벤트가 되가져가는 역방향 섀도잉 차단.
--   5) 온라인 이벤트에 '오프라인 팝업' 알림을 보내지 않는다.

-- ── 1. 교환은 진행 중 공개 캠페인이 걸어 둔 상품에만 성립한다 ───────────────
--
-- 기존 게이트는 coin_exchange_offers.status 하나였다. 캠페인이 끝난 뒤 운영자가
-- 상품을 'disabled'로 내리는 것을 잊으면, 화면에서는 사라진 교환이 직접 RPC
-- 호출이나 캐시된 폼 재제출로는 계속 성립한다 — 종료된 편성의 카드팩이 기간
-- 밖에서 계속 나간다.
--
-- 스키마를 바꾸지 않고 판정을 뒤집는다: 상품이 "살아 있는가"가 아니라 그 상품을
-- 지금 실제로 노출하는 경로가 있는가를 묻는다. 노출 경로는 진행 중 공개 캠페인의
-- exchange 블록 하나뿐이다(캠페인 상세 외에 교환 버튼을 그리는 표면이 없다).
--
-- 시간 경계는 화면의 ClosedNotice(campaign displayState 'ended')와 같다 —
-- now() < ends_at. 두 경계가 갈라지면 "종료됨"이라고 적힌 화면에서 교환이
-- 성립하거나, 열려 있는 화면이 거절당한다.
--
-- 에러는 offer_unavailable을 재사용한다. 사용자에게는 "지금은 교환할 수 없는
-- 상품"이라는 사실 하나면 되고, 앱의 문구 매핑(participation-actions.ts)도
-- 그대로 둔다.
create or replace function public.exchange_coins_for_draw_tickets(
  p_operation_id uuid,
  p_offer_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_offer public.coin_exchange_offers%rowtype;
  v_ledger_owner uuid;
  v_ledger_offer uuid;
  v_balance integer;
  v_issued integer;
  v_existing_count integer;
begin
  if v_user is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_user
      and profile.suspended_at is not null
  ) then
    raise exception 'account_suspended' using errcode = '55000';
  end if;

  -- 탈퇴 신청으로 쓰기가 봉인된 계정(20260813193000 의 계정 fence 관례).
  if private.is_account_write_fenced(v_user) then
    raise object_not_in_prerequisite_state
      using message = 'account_deletion_write_fenced';
  end if;

  if p_operation_id is null then
    raise exception 'invalid_operation' using errcode = '22004';
  end if;

  -- 응답이 유실된 재시도는 먼저 커밋된 원장을 관측한 뒤에 판단해야 한다
  -- (admin_grant_draw_tickets와 같은 관용구). 잠금이 없으면 두 재시도가 모두
  -- "없음"을 보고 각자 차감한 뒤 하나가 unique 위반으로 되돌아간다.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('coin_exchange:' || p_operation_id::text, 0)
  );

  select ledger.user_id, ledger.offer_id
    into v_ledger_owner, v_ledger_offer
  from public.coin_ledger as ledger
  where ledger.operation_id = p_operation_id;

  if found then
    -- 남의 멱등 키를 재생해 잔액·발급 수를 읽어 가는 경로를 막는다.
    if v_ledger_owner is distinct from v_user then
      raise exception 'exchange_operation_conflict' using errcode = '23505';
    end if;

    -- 같은 키인데 다른 상품이면 재시도가 아니라 다른 요청이다. 캠페인 한 장에
    -- 교환 블록이 여러 개일 때 화면이 키를 공유하면 여기로 온다 — already_exchanged
    -- 로 답하면 두 번째 상품은 교환되지 않았는데 성공으로 읽힌다.
    if v_ledger_offer is distinct from p_offer_id then
      raise exception 'exchange_operation_conflict' using errcode = '23505',
        detail = 'operation_id is bound to a different offer';
    end if;

    select coalesce(balance, 0) into v_balance
    from public.coin_balances
    where user_id = v_user;

    select count(*)::integer into v_existing_count
    from public.draw_tickets as ticket
    where ticket.source = 'coin_exchange'
      and ticket.source_id = p_operation_id;

    -- 이미 성립한 교환의 재생은 캠페인 상태를 다시 묻지 않는다. 커밋된 사실을
    -- 나중의 편성 변경으로 뒤집으면, 응답만 유실된 사용자가 발급받은 카드팩을
    -- 설명할 수 없는 상태가 된다.
    return jsonb_build_object(
      'status', 'already_exchanged',
      'balance', coalesce(v_balance, 0),
      'issued_count', v_existing_count
    );
  end if;

  select offer.*
    into v_offer
  from public.coin_exchange_offers as offer
  where offer.id = p_offer_id
  for share;

  if not found or v_offer.status <> 'active' then
    raise exception 'offer_unavailable' using errcode = 'P0002';
  end if;

  -- 노출 경로 확인. sections는 admin_upsert_campaign의 검증을 통과한 배열이라
  -- exchange 블록의 offer_id는 uuid 문자열이다. 대소문자만 정규화한다 —
  -- 검증 정규식이 대소문자를 가리지 않아 대문자 uuid도 저장될 수 있다.
  if not exists (
    select 1
    from public.campaigns as campaign,
      lateral pg_catalog.jsonb_array_elements(campaign.sections) as section(entry)
    where campaign.status = 'published'
      and campaign.starts_at <= now()
      and now() < campaign.ends_at
      and section.entry ->> 'type' = 'exchange'
      and pg_catalog.lower(section.entry ->> 'offer_id') = p_offer_id::text
  ) then
    raise exception 'offer_unavailable' using errcode = 'P0002';
  end if;

  perform private.assert_card_pool_ready(v_offer.pool_id);

  -- 직렬화 지점. 두 세션이 같은 잔액을 노리면 뒤에 온 쪽은 잠금 해제 후 갱신된
  -- 행으로 조건을 다시 평가해 0행을 얻는다 — 초과 인출이 성립할 창이 없다.
  update public.coin_balances
  set balance = balance - v_offer.coin_cost,
      updated_at = now()
  where user_id = v_user
    and balance >= v_offer.coin_cost
  returning balance into v_balance;

  if not found then
    raise exception 'insufficient_coins';
  end if;

  insert into public.coin_ledger (user_id, amount, reason, operation_id, offer_id)
  values (v_user, -v_offer.coin_cost, 'exchange', p_operation_id, v_offer.id);

  -- source_id = operation_id 라서 unique (source, source_id, ordinal)이 재시도
  -- 이중 발급을 DB 레벨에서 한 번 더 막는다.
  insert into public.draw_tickets (user_id, pool_id, source, source_id, ordinal)
  select v_user, v_offer.pool_id, 'coin_exchange', p_operation_id, issue_series.n
  from pg_catalog.generate_series(1, v_offer.ticket_count) as issue_series(n);

  get diagnostics v_issued = row_count;

  -- 게이트가 행을 삼켰다. 코인 차감·원장·잔액까지 전부 되돌린다.
  if v_issued <> v_offer.ticket_count then
    raise exception 'card_rewards_disabled' using errcode = '55000';
  end if;

  -- 알림은 draw_tickets STATEMENT 트리거(20260716090001)가 보낸다. 여기서 직접
  -- 넣으면 발급 한 건에 알림이 두 번 간다.
  return jsonb_build_object(
    'status', 'exchanged',
    'balance', v_balance,
    'issued_count', v_issued
  );
end;
$$

