create function public.admin_save_store_settings(target_section text,target_values jsonb,expected_updated_at timestamptz)
returns timestamptz language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid()); previous public.store_settings; saved public.store_settings; normalized jsonb; allowed text[]; filled integer;
begin
  if actor is null or not public.is_staff() or not exists(select 1 from public.profiles where id=actor and role='admin') then
    raise insufficient_privilege using message='admin_required';
  end if;
  if target_section not in ('business','bank_transfer') or target_section is null or jsonb_typeof(target_values) is distinct from 'object' then
    raise invalid_parameter_value using message='invalid_store_settings';
  end if;
  allowed:=case target_section when 'business' then array['companyName','representative','registrationNumber','mailOrderNumber','address','phone','email','hostingProvider'] else array['bank','accountNumber','holder'] end;
  if exists(select 1 from jsonb_each(target_values) where not(key=any(allowed)) or jsonb_typeof(value)<>'string') then
    raise invalid_parameter_value using message='invalid_store_settings';
  end if;
  select coalesce(jsonb_object_agg(key,btrim(value,E' \t\n\r\f\v')),'{}') into normalized from jsonb_each_text(target_values);
  if exists(select 1 from jsonb_each_text(normalized) where length(value)>500 or value ~ '[[:cntrl:]]')
    or (target_section='business' and coalesce(normalized->>'email','')<>'' and normalized->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then
    raise invalid_parameter_value using message='invalid_store_settings';
  end if;
  if target_section='bank_transfer' then
    select count(*) into filled from jsonb_each_text(normalized) where value<>'';
    if not normalized ?& allowed or filled not in (0,3) then raise invalid_parameter_value using message='incomplete_bank_account'; end if;
  end if;
  select * into previous from public.store_settings where singleton for update;
  if expected_updated_at is distinct from previous.updated_at then raise serialization_failure using message='store_settings_conflict'; end if;
  update public.store_settings set
    business=case when target_section='business' then normalized else business end,
    bank_transfer=case when target_section='bank_transfer' then normalized else bank_transfer end,
    updated_at=greatest(clock_timestamp(),previous.updated_at+interval '1 microsecond') where singleton returning * into saved;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.store_settings.updated','store_settings:'||target_section,
    jsonb_build_object('before',case target_section when 'business' then previous.business else previous.bank_transfer end,
      'after',normalized));
  return saved.updated_at;
end $$

create function public.admin_save_shipping_carrier(target_code text,target_label text,target_url text,target_active boolean,expected_updated_at timestamptz)
returns timestamptz language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid()); previous public.shipping_carriers; saved public.shipping_carriers;
  code_value text:=btrim(coalesce(target_code,'')); label_value text:=btrim(coalesce(target_label,'')); url_value text:=btrim(coalesce(target_url,''));
begin
  if actor is null or not public.is_staff() or not exists(select 1 from public.profiles where id=actor and role='admin') then raise insufficient_privilege using message='admin_required'; end if;
  if code_value !~ '^[a-z0-9_]{2,32}$' or length(label_value) not between 1 and 60 or target_active is null
    or length(url_value)>500 or position('{trackingNumber}' in url_value)=0
    or url_value !~ '^https://[A-Za-z0-9][A-Za-z0-9.-]*(:[0-9]{1,5})?[/#?]'
    or url_value ~ '[[:space:]\\]' then raise invalid_parameter_value using message='invalid_shipping_carrier'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('shipping_carrier:'||code_value,0));
  select * into previous from public.shipping_carriers where code=code_value for update;
  if found then
    if expected_updated_at is distinct from previous.updated_at then raise serialization_failure using message='store_settings_conflict'; end if;
    update public.shipping_carriers set label=label_value,tracking_url_template=url_value,is_active=target_active
      where code=code_value returning * into saved;
  else
    if expected_updated_at is not null then raise no_data_found using message='shipping_carrier_not_found'; end if;
    insert into public.shipping_carriers(code,label,tracking_url_template,is_active)
      values(code_value,label_value,url_value,target_active) returning * into saved;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.shipping_carrier.saved','shipping_carriers:'||code_value,
    jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
  return saved.updated_at;
end $$

-- Staff catalogue search returns a table relation so PostgREST filters/count/range
-- remain server-owned. An option code locates its parent good without duplicate rows.
create or replace function public.admin_search_goods(search_text text default null)
returns setof public.goods
language plpgsql stable security invoker
set search_path = ''
as $$
declare
  needle text := btrim(coalesce(search_text, ''));
  pattern text;
begin
  if auth.uid() is null or not public.is_staff() then
    raise insufficient_privilege using message = 'admin_only';
  end if;
  if length(needle) > 100 then
    raise invalid_parameter_value using message = 'goods_search_too_long';
  end if;
  pattern := '%' || replace(replace(replace(needle, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%';
  return query
    select g.* from public.goods g
    where needle = '' or g.name ilike pattern escape E'\\'
      or g.code ilike pattern escape E'\\'
      or g.id ilike pattern escape E'\\'
      or exists (
        select 1 from public.goods_variants v
        where v.good_id = g.id and v.code ilike pattern escape E'\\'
      );
end;
$$

alter table public.goods add constraint goods_type_check check (
 type in ('피규어','인형','키링','아크릴','문구','쿠션','파우치','세트') or (published_at is null and type='')
)

create or replace function private.guard_goods_public_slug()
returns trigger language plpgsql security definer set search_path='' as $$
begin
  if tg_op='UPDATE' then
    if old.first_published_at is not null and new.id is distinct from old.id then
      raise check_violation using message='goods_slug_locked';
    end if;
    if old.first_published_at is not null then new.first_published_at:=old.first_published_at; end if;
  end if;
  if new.archived_at is not null then new.published_at:=null; end if;
  if new.published_at is not null and new.first_published_at is null then new.first_published_at:=clock_timestamp(); end if;
  return new;
end $$

create function private.set_good_published(target_id text,publish_requested boolean)
returns boolean language plpgsql security invoker set search_path='' as $$
declare selected public.goods; transition_at timestamptz;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  if publish_requested is null then raise invalid_parameter_value using message='invalid_publish_state'; end if;
  select * into selected from public.goods where id=target_id for update;
  if not found then raise no_data_found using message='catalog_not_found'; end if;
  if selected.archived_at is not null then raise check_violation using message='catalog_item_archived'; end if;
  if publish_requested=(selected.published_at is not null) then return false; end if;
  if publish_requested and (
    nullif(btrim(selected.name),'') is null or nullif(btrim(selected.type),'') is null
    or nullif(btrim(selected.image_path),'') is null
    or exists(select 1 from unnest(array[selected.notice_maker,selected.notice_origin,selected.notice_material,
      selected.notice_size,selected.notice_made_on,selected.notice_as_manager,selected.notice_as_contact]) field
      where nullif(btrim(field),'') is null)
    or not exists(select 1 from public.goods_variants where good_id=target_id and archived_at is null)
  ) then raise check_violation using message='goods_publish_incomplete'; end if;
  transition_at:=case when publish_requested then clock_timestamp() else null end;
  update public.goods set published_at=transition_at where id=target_id;
  insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),
    case when publish_requested then 'admin.good.published' else 'admin.good.unpublished' end,'goods:'||target_id,
    jsonb_build_object('published_at',transition_at,'previous_published_at',selected.published_at));
  return true;
end $$

create or replace function public.admin_save_good(target_good jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  actor_id uuid:=(select auth.uid());
  previous_id text:=nullif(btrim(target_good->>'previous_id'),'');
  target_id text:=nullif(btrim(target_good->>'id'),'');
  target_ip text:=target_good->>'ip_id';
  previous_ip text;
  previous_code text;
  requested_code text:=nullif(upper(btrim(target_good->>'code')),'');
  requested_variant_code text:=nullif(upper(btrim(target_good->>'default_variant_code')),'');
  saved_code text; saved_variant_code text;
begin
  if actor_id is null then raise invalid_authorization_specification using message='auth_required'; end if;
  if not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
  if jsonb_typeof(target_good) is distinct from 'object' then raise invalid_parameter_value using message='invalid_good'; end if;
  if previous_id is not null then
    perform pg_advisory_xact_lock(hashtextextended('admin_good:'||previous_id,0));
    select ip_id,code into previous_ip,previous_code from public.goods where id=previous_id for update;
    if not found then raise no_data_found using message='catalog_record_missing'; end if;
  end if;
  if target_id is null then
    perform pg_advisory_xact_lock(hashtextextended('goods_slug:'||private.goods_slug_from_name(target_good->>'name'),0));
    target_id:=private.available_goods_slug(target_good->>'name',previous_id);
  end if;
  if target_id !~ '^[a-z0-9][a-z0-9-]{0,63}$' then raise invalid_parameter_value using message='invalid_goods_slug'; end if;
  if previous_id is not null and previous_id is distinct from target_id then
    update public.goods set id=target_id where id=previous_id;
    update public.reward_policies set target_good_id=target_id where target_good_id=previous_id;
    update public.home_curations set payload=jsonb_set(payload,'{good_ids}',(
      select jsonb_agg(case when item=to_jsonb(previous_id) then to_jsonb(target_id) else item end order by position)
      from jsonb_array_elements(payload->'good_ids') with ordinality items(item,position)
    )) where jsonb_typeof(payload->'good_ids')='array' and payload->'good_ids' ? previous_id;
    update public.campaigns campaign set sections=(
      select jsonb_agg(case when jsonb_typeof(section->'good_ids')='array' and section->'good_ids' ? previous_id
        then jsonb_set(section,'{good_ids}',(
          select jsonb_agg(case when item=to_jsonb(previous_id) then to_jsonb(target_id) else item end order by item_position)
          from jsonb_array_elements(section->'good_ids') with ordinality items(item,item_position)
        )) else section end order by section_position)
      from jsonb_array_elements(campaign.sections) with ordinality sections(section,section_position)
    ) where campaign.sections @> jsonb_build_array(jsonb_build_object('good_ids',jsonb_build_array(previous_id)));
  end if;

  perform public.admin_upsert_good(
    target_id,target_ip,target_good->>'name',target_good->>'type',(target_good->>'price')::integer,
    target_good->>'badge',target_good->>'stock',target_good->>'bg',target_good->>'image_path',
    target_good->>'notice_maker',target_good->>'notice_origin',target_good->>'notice_material',target_good->>'notice_size',
    target_good->>'notice_made_on',target_good->>'notice_as_manager',target_good->>'notice_as_contact',
    target_good->>'description',array(select jsonb_array_elements_text(coalesce(target_good->'gallery_paths','[]'::jsonb))),
    target_good->>'detail_image_path',case when previous_id is null then null else target_id end,
    nullif(target_good->>'compare_at_price','')::integer,
    (target_good->>'publish')::boolean
  );
  if requested_code is not null then update public.goods set code=requested_code where id=target_id; end if;
  if requested_variant_code is not null then
    update public.goods_variants set code=requested_variant_code where good_id=target_id and is_default;
  end if;
  select code into saved_code from public.goods where id=target_id;
  select code into saved_variant_code from public.goods_variants where good_id=target_id and is_default;
  insert into public.audit_log(actor_id,action,target,diff) values(actor_id,'admin.good.identifiers_saved','goods:'||target_id,
    jsonb_build_object('previous_id',previous_id,'id',target_id,'previous_code',previous_code,'code',saved_code,'default_variant_code',saved_variant_code));
  return jsonb_build_object('id',target_id,'code',saved_code,'default_variant_code',saved_variant_code);
end;
$$

-- New orders fence unpublished goods after the existing idempotent order lookup.
CREATE OR REPLACE FUNCTION public.place_order(p_address jsonb, p_checkout_key uuid, p_payment_method order_payment_method)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  -- 결제사 최소 결제액(20260813242000 가드·lib/coupons.ts MIN_PAYABLE_TOTAL와 동치).
  -- 할인이 총액을 이 밑으로 내리면 가드가 주문 전체를 롤백하므로, 여기서 캡한다.
  c_min_payable_total constant bigint := 1000;
  v_user uuid := (select auth.uid());
  v_order uuid;
  v_existing_address jsonb;
  v_existing_payment_method public.order_payment_method;
  v_expires_at timestamptz;
  v_subtotal bigint := 0;
  v_shipping_fee bigint := 0;
  v_item_count integer := 0;
  v_recipient_name text;
  v_phone text;
  v_postal_code text;
  v_address1 text;
  v_optional text;
  v_selected_coupon uuid;
  v_coupon_eval record;
  v_discount bigint := 0;
  r record;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if not exists (
    select 1
    from public.profiles as profile
    join auth.users as auth_user on auth_user.id = profile.id
    where profile.id = v_user
      and nullif(btrim(coalesce(profile.email, auth_user.email)), '') is not null
      and nullif(btrim(profile.nickname), '') is not null
      and profile.birth_date is not null
      and profile.birth_date <= current_date
      and profile.onboarded_at is not null
      and profile.consents ->> 'terms' = 'true'
      and profile.consents ->> 'privacy' = 'true'
  ) then
    raise insufficient_privilege using message = 'onboarding required';
  end if;

  if p_checkout_key is null then
    raise not_null_violation using message = 'checkout key required';
  end if;

  if p_address is null or jsonb_typeof(p_address) <> 'object' then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if not (p_address ?& array['recipientName', 'phone', 'postalCode', 'address1'])
     or exists (
       select 1
       from jsonb_object_keys(p_address) as address_key(key)
       where address_key.key not in (
         'recipientName', 'phone', 'postalCode', 'address1', 'address2', 'deliveryNote'
       )
     )
     or exists (
       select 1
       from jsonb_each(p_address) as address_value(key, value)
       where jsonb_typeof(address_value.value) <> 'string'
     ) then
    raise check_violation using message = 'invalid checkout address';
  end if;

  v_recipient_name := p_address ->> 'recipientName';
  v_phone := p_address ->> 'phone';
  v_postal_code := p_address ->> 'postalCode';
  v_address1 := p_address ->> 'address1';

  if v_recipient_name <> btrim(v_recipient_name, E' \t\n\r\f\v')
     or length(v_recipient_name) not between 1 and 50
     or v_phone !~ '^[0-9]{8,15}$'
     or v_postal_code !~ '^[0-9]{5}$'
     or v_address1 <> btrim(v_address1, E' \t\n\r\f\v')
     or length(v_address1) not between 1 and 200 then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if p_address ? 'address2' then
    v_optional := p_address ->> 'address2';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  if p_address ? 'deliveryNote' then
    v_optional := p_address ->> 'deliveryNote';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  -- 같은 사용자의 다른 탭 주문을 직렬화한다. 동일 키 재시도는 먼저 생성된
  -- 주문을 반환하고, 다른 키는 첫 주문이 비운 장바구니를 확인하게 된다.
  -- 쿠폰 적용·해제도 같은 잠금을 잡으므로 선택 교체와 소비가 경합하지 않는다.
  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  select orders.id, orders.address, orders.payment_method
    into v_order, v_existing_address, v_existing_payment_method
  from public.orders
  where orders.user_id = v_user
    and orders.checkout_key = p_checkout_key;

  if found then
    -- 같은 checkout key로 결제수단만 바꿔 다시 부르면 24시간 선점을 15분 주문에
    -- 덧씌우거나 그 반대가 된다. 주소와 같은 등급의 충돌로 막는다.
    if v_existing_address is distinct from p_address
      or v_existing_payment_method is distinct from p_payment_method
    then
      raise unique_violation using message = 'checkout key conflict';
    end if;
    return v_order;
  end if;

  -- 카드 15분 · 무통장 24시간. 무통장은 사람이 은행 앱을 열고 이체할 시간을
  -- 줘야 해서 선점 창이 길고, 그만큼 재고가 오래 묶인다 — 한정 드롭은
  -- goods.allow_bank_transfer로 아예 차단한다(ADR-0007).
  v_expires_at := case
    when p_payment_method = 'bank_transfer' then now() + interval '24 hours'
    else now() + interval '15 minutes'
  end;

  insert into public.orders (
    user_id, status, total, shipping_fee, address, expires_at, checkout_key, payment_method
  )
  values (v_user, 'pending', 0, 0, p_address, v_expires_at, p_checkout_key, p_payment_method)
  returning id into v_order;

  -- 카트와 재고를 같은 결정적 순서로 잠근 뒤 DB 값만으로 주문 스냅샷을 만든다.
  for r in
    select
      cart.good_id,
      cart.qty,
      good.price,
      good.stock,
      good.stock_qty,
      good.name,
      good.type,
      good.ip_id,
      good.allow_bank_transfer,
      good.sale_restriction,
      good.published_at,
      good.archived_at
    from public.cart_items as cart
    join public.goods as good on good.id = cart.good_id
    where cart.user_id = v_user
    order by cart.good_id
    for update of cart, good
  loop
    -- The locked good fixes its parent association. Keep the IP SHARE lock until
    -- this order commits, serializing new purchases with an unpublish UPDATE.
    perform private.assert_ip_purchasable(r.ip_id);
    if r.published_at is null or r.archived_at is not null then
      raise check_violation using message='catalog_item_unavailable';
    end if;
    v_item_count := v_item_count + 1;

    if r.stock = 'soldout' or r.stock_qty < r.qty then
      raise check_violation using message = format('out of stock: %s', r.good_id);
    end if;

    if p_payment_method = 'bank_transfer' and not r.allow_bank_transfer then
      raise check_violation using message = format('bank transfer blocked: %s', r.good_id);
    end if;

    -- 성인인증(#209·#210)이 도입되기 전까지 판매 제한 상품은 서버가 구매를
    -- 차단한다. 결제수단과 무관한 상품 축이라 무통장 검사와 별개로 판정한다.
    if r.sale_restriction <> 'none' then
      raise check_violation using message = format('restricted good blocked: %s', r.good_id);
    end if;

    perform private.change_default_goods_variant_stock(r.good_id, -r.qty::bigint);

    insert into public.order_items (
      order_id,
      good_id,
      qty,
      unit_price,
      good_name_snapshot,
      good_type_snapshot,
      good_ip_id_snapshot
    )
    values (
      v_order,
      r.good_id,
      r.qty,
      r.price,
      r.name,
      r.type,
      r.ip_id
    );

    -- 조회 시 잠근 스냅샷 행만 지운다. 동시에 새로 담긴 다른 상품까지
    -- 마지막 broad delete가 없애지 않도록 상품 단위로 소비한다.
    delete from public.cart_items
    where user_id = v_user
      and good_id = r.good_id;

    v_subtotal := v_subtotal + (r.price::bigint * r.qty::bigint);
  end loop;

  if v_item_count = 0 then
    raise check_violation using message = 'cart empty';
  end if;

  -- 배송비 판정은 할인 전 소계 기준이다 — 쿠폰이 무료배송 경계를 흔들면
  -- 카트의 "얼마 더 담으면 무료배송" 안내가 거짓말이 된다.
  v_shipping_fee := private.goods_shipping_fee_for(v_subtotal);

  -- 카트에 적용해 둔 쿠폰을 여기서 최종 검증하고 소비한다. 조건 미달이면 주문
  -- 전체를 거부한다 — 할인을 기대한 사용자를 조용히 정가로 결제시키지 않는다.
  select selection.user_coupon_id
  into v_selected_coupon
  from public.cart_coupon_selections as selection
  where selection.user_id = v_user;

  if v_selected_coupon is not null then
    -- 상태 전이 전에 보유 행을 잠근다. 같은 유저는 advisory lock으로 이미
    -- 직렬화되어 있고, 이 잠금은 향후 다른 경로가 생겨도 이중 사용을 막는 안전벨트다.
    perform held.id
    from public.user_coupons as held
    where held.id = v_selected_coupon
    for update;

    select * into v_coupon_eval
    from private.evaluate_user_coupon(v_selected_coupon, v_user, v_subtotal);
    if v_coupon_eval.o_reason is not null then
      raise check_violation using message = v_coupon_eval.o_reason;
    end if;
    -- 결제사 최소 결제액을 지키도록 할인을 캡한다 — 전액 쿠폰이 주문을
    -- 결제 불가(총액 < 1,000원)로 만들면 혜택이 주문 실패로 둔갑한다.
    v_discount := least(
      v_coupon_eval.o_discount,
      greatest(0, v_subtotal + v_shipping_fee - c_min_payable_total)
    );

    update public.user_coupons
    set status = 'used',
        used_at = now(),
        used_order_id = v_order
    where id = v_selected_coupon;

    insert into public.coupon_redemptions (
      user_coupon_id, coupon_code, user_id, order_id, discount_amount
    )
    values (
      v_selected_coupon, v_coupon_eval.o_coupon_code, v_user, v_order, v_discount
    );

    -- 소비한 선택만 지운다. 주문 진행 중 다른 탭이 교체한 새 선택은 남는다.
    delete from public.cart_coupon_selections
    where user_id = v_user
      and user_coupon_id = v_selected_coupon;
  end if;

  update public.orders
  set total = v_subtotal + v_shipping_fee - v_discount,
      shipping_fee = v_shipping_fee,
      discount_total = v_discount
  where id = v_order;

  -- 무통장에는 결제사 왕복이 없다. 그래서 원장 anchor(payment_attempts)를 여기서
  -- 바로 연다 — 없으면 운영자가 입금을 확인할 대상 자체가 없고, "결제 준비" 버튼을
  -- 눌러야 생기는 구조는 구매자가 이미 이체한 뒤에도 확인이 안 되는 창을 만든다.
  -- 새 함수를 두지 않고 카드와 같은 prepare를 부른다: 소유권·금액·스냅샷·정지
  -- 계정 검사가 한 곳에만 있어야 한다.
  if p_payment_method = 'bank_transfer' then
    perform public.prepare_goods_payment_attempt(v_user, v_order, 'bank_transfer');
  end if;

  -- 무통장 주문은 만든 순간이 안내 시점이다. 금액·입금자명 코드·기한이 모두
  -- 정해졌고, 이 알림을 놓치면 구매자는 어디로 얼마를 보낼지 알 수 없다.
  if p_payment_method = 'bank_transfer' then
    insert into public.notifications (
      user_id, type, title, body, link_path, source_type, source_id, dedupe_key
    )
    values (
      v_user,
      'order_bank_transfer_pending',
      '입금 안내를 확인해주세요',
      format(
        '%s원을 기한 안에 입금해주세요. 입금자명 끝에 주문코드 %s를 붙이면 확인이 빨라집니다.',
        to_char(v_subtotal + v_shipping_fee - v_discount, 'FM999,999,999'),
        private.bank_transfer_deposit_code(v_order)
      ),
      '/checkout/' || v_order::text,
      'order',
      v_order::text,
      'order:bank_transfer_pending:' || v_order::text
    )
    on conflict (user_id, dedupe_key) do nothing;
  end if;

  return v_order;
end;
$function$

create function private.guard_good_fulfillment() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.published_at is not null then
    if new.origin_id is null then raise check_violation using message='fulfillment_origin_required'; end if;
    if tg_op='INSERT' or new.origin_id is distinct from old.origin_id or old.published_at is null then
      perform id from public.fulfillment_origins where id=new.origin_id and is_active for share;
      if not found then raise check_violation using message='fulfillment_origin_inactive'; end if;
    end if;
  end if;
  if new.shipping_fee_type<>'individual' then new.individual_fee:=0; end if;
  return new;
end $$

create function public.admin_save_fulfillment_origin(target_id uuid,target_values jsonb,expected_updated_at timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid()); previous public.fulfillment_origins; saved public.fulfillment_origins;
 code_value text; name_value text; carrier_value text; base_value bigint; threshold_value bigint; active_value boolean;
begin
  if actor is null or not public.is_staff() or not exists(select 1 from public.profiles where id=actor and role='admin') then
    raise insufficient_privilege using message='admin_required';
  end if;
  if jsonb_typeof(target_values) is distinct from 'object' or exists(select 1 from jsonb_object_keys(target_values) k
    where k not in ('code','name','default_carrier','base_fee','free_threshold','return_address','cutoff','export_template','is_active')) then
    raise invalid_parameter_value using message='invalid_fulfillment_origin';
  end if;
  code_value:=btrim(target_values->>'code'); name_value:=btrim(target_values->>'name');
  carrier_value:=nullif(target_values->>'default_carrier','');
  base_value:=(target_values->>'base_fee')::bigint; threshold_value:=nullif(target_values->>'free_threshold','')::bigint;
  active_value:=(target_values->>'is_active')::boolean;
  if code_value is null or code_value !~ '^[a-z][a-z0-9-]{1,39}$' or name_value is null or length(name_value) not between 1 and 80
    or base_value is null or base_value not between 0 and 1000000 or threshold_value not between 0 and 100000000 or active_value is null
    or coalesce(target_values->>'return_address','') ~ '[[:cntrl:]]'
    or length(coalesce(target_values->>'return_address',''))>500
    or coalesce(target_values->>'export_template','') not in ('standard','wms_csv','seowon_xlsx') then
    raise invalid_parameter_value using message='invalid_fulfillment_origin';
  end if;
  if carrier_value is not null and not exists(select 1 from public.shipping_carriers where code=carrier_value and is_active) then
    raise check_violation using message='shipping_carrier_inactive';
  end if;
  if active_value and carrier_value is null then raise check_violation using message='shipping_carrier_required'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('fulfillment_origin:'||code_value,0));
  if target_id is not null then
    select * into previous from public.fulfillment_origins where id=target_id for update;
    if not found then raise no_data_found using message='fulfillment_origin_not_found'; end if;
    if previous.updated_at is distinct from expected_updated_at then raise serialization_failure using message='fulfillment_origin_conflict'; end if;
    if previous.code<>code_value then raise check_violation using message='fulfillment_origin_code_locked'; end if;
    update public.fulfillment_origins set name=name_value,default_carrier=carrier_value,base_fee=base_value,free_threshold=threshold_value,
      return_address=btrim(coalesce(target_values->>'return_address','')),cutoff=nullif(target_values->>'cutoff','')::time,
      export_template=target_values->>'export_template',is_active=active_value,
      updated_at=greatest(clock_timestamp(),previous.updated_at+interval '1 microsecond')
      where id=target_id returning * into saved;
  else
    if expected_updated_at is not null then raise invalid_parameter_value using message='invalid_fulfillment_origin'; end if;
    insert into public.fulfillment_origins(code,name,default_carrier,base_fee,free_threshold,return_address,cutoff,export_template,is_active)
      values(code_value,name_value,carrier_value,base_value,threshold_value,btrim(coalesce(target_values->>'return_address','')),
        nullif(target_values->>'cutoff','')::time,target_values->>'export_template',active_value) returning * into saved;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.fulfillment_origin.saved','fulfillment_origins:'||saved.id,
    jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
  return jsonb_build_object('id',saved.id,'updatedAt',saved.updated_at);
end $$

create function public.quote_goods_shipping(items jsonb)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare input record; good public.goods; variant public.goods_variants; line_qty integer; variant_key uuid; lines jsonb:='[]';
begin
  if jsonb_typeof(items) is distinct from 'array' or jsonb_array_length(items)>1000 then
    raise invalid_parameter_value using message='invalid_shipping_quote_items';
  end if;
  for input in select value from jsonb_array_elements(items) loop
    if jsonb_typeof(input.value) is distinct from 'object' or exists(select 1 from jsonb_object_keys(input.value) k where k not in ('goodId','variantId','qty'))
      or jsonb_typeof(input.value->'qty') is distinct from 'number' then raise invalid_parameter_value using message='invalid_shipping_quote_items'; end if;
    line_qty:=(input.value->>'qty')::integer;
    if line_qty not between 1 and 2147483647 then raise invalid_parameter_value using message='invalid_shipping_quote_items'; end if;
    select g.* into good from public.goods g join public.ips ip on ip.id=g.ip_id
      join public.fulfillment_origins origin on origin.id=g.origin_id and origin.is_active
      where g.id=input.value->>'goodId' and g.archived_at is null and g.published_at is not null and g.sale_restriction='none'
        and ip.archived_at is null and ip.published_at is not null;
    if not found then raise check_violation using message='shipping_quote_good_unavailable'; end if;
    variant_key:=nullif(input.value->>'variantId','')::uuid;
    select v.* into variant from public.goods_variants v where v.good_id=good.id and v.archived_at is null
      and (case when variant_key is null then v.is_default else v.id=variant_key end);
    if not found then raise check_violation using message='shipping_quote_variant_unavailable'; end if;
    lines:=lines||jsonb_build_array(jsonb_build_object('origin_id',good.origin_id,'good_id',good.id,'qty',line_qty,
      'unit_price',variant.price,'fee_type',good.shipping_fee_type,'individual_fee',good.individual_fee));
  end loop;
  return private.calculate_goods_shipping(lines);
end $$

create function private.snapshot_order_item_fulfillment() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.good_id is null then
    new.origin_id_snapshot:=coalesce(new.origin_id_snapshot,'00000000-0000-4000-8000-000000042201');
    new.shipping_fee_type_snapshot:=coalesce(new.shipping_fee_type_snapshot,'policy');
    new.individual_fee_snapshot:=coalesce(new.individual_fee_snapshot,0);
  else
    select origin_id,shipping_fee_type,individual_fee into new.origin_id_snapshot,new.shipping_fee_type_snapshot,new.individual_fee_snapshot
      from public.goods where id=new.good_id;
  end if;
  return new;
end $$

create function private.goods_shipping_fee_for(target_order uuid)
returns bigint language plpgsql security invoker set search_path='' as $$
declare origin_key uuid; lines jsonb; quote jsonb;
begin
  for origin_key in select origin.id from public.fulfillment_origins origin where origin.id in (
    select item.origin_id_snapshot from public.order_items item where item.order_id=target_order
  ) order by origin.id for share loop
    if not (select is_active from public.fulfillment_origins where id=origin_key) then
      raise check_violation using message='fulfillment_origin_inactive';
    end if;
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('origin_id',origin_id_snapshot,'good_id',good_id,'qty',qty,
    'unit_price',unit_price,'fee_type',shipping_fee_type_snapshot,'individual_fee',individual_fee_snapshot)),'[]')
    into lines from public.order_items where order_id=target_order;
  quote:=private.calculate_goods_shipping(lines);
  update public.orders set shipping_fee_breakdown=quote->'groups' where id=target_order;
  return (quote->>'totalFee')::bigint;
end $$

create function public.admin_save_good(target_good jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare saved jsonb; previous public.goods; updated public.goods; origin_key uuid; fee_type text; fee_value bigint;
begin
  if (select auth.uid()) is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  if target_good ? 'origin_id' then
    origin_key:=(target_good->>'origin_id')::uuid;
  end if;
  if target_good ? 'shipping_fee_type' then
    fee_type:=target_good->>'shipping_fee_type';
    if fee_type is null or fee_type not in ('policy','free','individual') then raise invalid_parameter_value using message='invalid_good_shipping_type'; end if;
  end if;
  if target_good ? 'individual_fee' then
    fee_value:=(target_good->>'individual_fee')::bigint;
    if fee_value is null or fee_value not between 0 and 1000000 then raise invalid_parameter_value using message='invalid_individual_fee'; end if;
  end if;
  -- Keep publication at its prior state while this transaction sets shipping.
  -- A new draft can fill its origin and publish in the same save.
  saved:=private.admin_save_good_before_fulfillment(case when target_good->>'publish'='true'
    and target_good ?| array['origin_id','shipping_fee_type','individual_fee'] then target_good||'{"publish":null}'::jsonb else target_good end);
  if target_good ?| array['origin_id','shipping_fee_type','individual_fee'] then
    select * into previous from public.goods where id=saved->>'id' for update;
    update public.goods set origin_id=case when target_good ? 'origin_id' then origin_key else origin_id end,shipping_fee_type=coalesce(fee_type,shipping_fee_type),
      individual_fee=coalesce(fee_value,individual_fee) where id=previous.id returning * into updated;
    insert into public.audit_log(actor_id,action,target,diff) values((select auth.uid()),'catalog.good.fulfillment_updated','goods:'||updated.id,
      jsonb_build_object('before',jsonb_build_object('origin_id',previous.origin_id,'shipping_fee_type',previous.shipping_fee_type,'individual_fee',previous.individual_fee),
        'after',jsonb_build_object('origin_id',updated.origin_id,'shipping_fee_type',updated.shipping_fee_type,'individual_fee',updated.individual_fee)));
  end if;
  if target_good->>'publish'='true' then perform public.admin_set_good_published(saved->>'id',true); end if;
  return saved;
end $$

