create or replace function private.save_goods_options(target_id text, target_rows jsonb, baseline jsonb, is_new boolean)
returns void language plpgsql security definer set search_path='' as $$
declare
 actor_id uuid:=auth.uid(); good public.goods%rowtype; variant public.goods_variants%rowtype;
 item jsonb; option_id uuid; retained uuid[]:='{}'::uuid[]; ordinal integer:=0; expected_qty integer; desired_qty integer;
 current_ids jsonb; before_rows jsonb; seen_attributes jsonb[]:='{}'::jsonb[]; desired_price bigint;
begin
 if actor_id is null then raise exception 'auth_required' using errcode='28000'; end if;
 if not public.is_staff() then raise exception 'forbidden' using errcode='42501'; end if;
 if target_rows is null or jsonb_typeof(target_rows)<>'array' or jsonb_array_length(target_rows) not between 1 and 100
   or baseline is null or jsonb_typeof(baseline)<>'array' then raise check_violation using message='invalid_goods_options'; end if;
 select * into good from public.goods where id=target_id for update;
 if not found or good.archived_at is not null then raise check_violation using message='good_unavailable'; end if;
 perform 1 from public.goods_variants where good_id=target_id order by id for update;
 select coalesce(jsonb_agg(id::text order by id),'[]') into current_ids from public.goods_variants where good_id=target_id and archived_at is null;
 if not is_new and current_ids is distinct from (select coalesce(jsonb_agg(value order by value),'[]') from jsonb_array_elements_text(baseline)) then
   raise sqlstate 'PT409' using message='goods_options_changed';
 end if;
 select jsonb_agg(to_jsonb(v) order by v.sort_order,v.id) into before_rows from public.goods_variants v where v.good_id=target_id;
 -- The first submitted row becomes the default. The deferred invariant checks the complete batch.
 update public.goods_variants set is_default=false where good_id=target_id and is_default;
 if is_new then delete from public.goods_variants where good_id=target_id; end if;
 for item in select value from jsonb_array_elements(target_rows) loop
   if jsonb_typeof(item)<>'object' or char_length(btrim(coalesce(item->>'name',''))) not between 1 and 200
     or jsonb_typeof(item->'attributes') is distinct from 'object'
     or exists(select 1 from jsonb_each(item->'attributes') a where char_length(btrim(a.key)) not between 1 and 40
       or jsonb_typeof(a.value)<>'string' or char_length(btrim(a.value#>>'{}')) not between 1 and 80)
     or coalesce(item->>'extraPrice','') !~ '^[0-9]+$' or coalesce(item->>'stockQty','') !~ '^[0-9]+$'
     or char_length(btrim(coalesce(item->>'code','')))>120
     or coalesce(jsonb_typeof(item->'code'),'null') not in ('string','null')
     or item->'attributes'=any(seen_attributes) then raise check_violation using message='invalid_goods_options'; end if;
   if item?'lowStockThreshold' and item->'lowStockThreshold'<>'null'::jsonb and (
     jsonb_typeof(item->'lowStockThreshold')<>'number' or item->>'lowStockThreshold' !~ '^[0-9]+$'
     or (item->>'lowStockThreshold')::numeric>2147483647
   ) then raise check_violation using message='invalid_goods_options'; end if;
   if item?'isActive' and jsonb_typeof(item->'isActive') is distinct from 'boolean' then
     raise check_violation using message='invalid_goods_options'; end if;
   seen_attributes:=array_append(seen_attributes,item->'attributes');
   desired_price:=good.price::bigint+(item->>'extraPrice')::bigint;
   desired_qty:=(item->>'stockQty')::integer;
   if desired_price>2147483647 then raise numeric_value_out_of_range using message='invalid_goods_options'; end if;
   option_id:=nullif(item->>'id','')::uuid;
   if option_id is not null then
     select * into variant from public.goods_variants where id=option_id and good_id=target_id;
     if not found or option_id=any(retained) or coalesce(item->>'expectedStockQty','') !~ '^[0-9]+$' then
       raise check_violation using message='invalid_goods_options'; end if;
     expected_qty:=(item->>'expectedStockQty')::integer;
     -- An untouched quantity is metadata, not an instruction to restore stock sold meanwhile.
     if desired_qty<>expected_qty then
       if variant.stock_qty<>expected_qty then raise sqlstate 'PT409' using message='stock_changed'; end if;
       perform private.change_goods_variant_stock(target_id,option_id,desired_qty::bigint-variant.stock_qty);
     end if;
     update public.goods_variants set name=btrim(item->>'name'),attributes=item->'attributes',price=desired_price::integer,
       low_stock_threshold=case when item?'lowStockThreshold' then (item->>'lowStockThreshold')::integer else variant.low_stock_threshold end,
       archived_at=case when item?'isActive' then case when (item->>'isActive')::boolean then null
         else coalesce(variant.archived_at,clock_timestamp()) end else variant.archived_at end,
       code=coalesce(nullif(item->>'code',''),variant.code),sort_order=ordinal,is_default=(ordinal=0) where id=option_id;
   else
     insert into public.goods_variants(good_id,name,attributes,price,code,sort_order,is_default,low_stock_threshold,archived_at)
       values(target_id,btrim(item->>'name'),item->'attributes',desired_price::integer,nullif(item->>'code',''),ordinal,ordinal=0,
         (item->>'lowStockThreshold')::integer,
         case when coalesce((item->>'isActive')::boolean,true) then null else clock_timestamp() end)
       returning id into option_id;
     if desired_qty<>0 then perform private.change_goods_variant_stock(target_id,option_id,desired_qty); end if;
   end if;
   retained:=array_append(retained,option_id); ordinal:=ordinal+1;
 end loop;
 for variant in select * from public.goods_variants where good_id=target_id and archived_at is null and not(id=any(retained)) order by id loop
   if exists(select 1 from public.order_items where variant_id=variant.id)
     or exists(select 1 from public.cart_items where variant_id=variant.id)
     or exists(select 1 from public.order_claim_reshipment_items where variant_id=variant.id or source_variant_id=variant.id) then
     update public.goods_variants set archived_at=now() where id=variant.id;
   else
     -- Later features may attach immutable history without an order/cart row.
     -- Let their FK be the lifetime boundary instead of naming not-yet-created
     -- tables here. A failed DELETE and all of its cascades roll back together.
     begin
       delete from public.goods_variants where id=variant.id;
     exception when foreign_key_violation then
       update public.goods_variants set archived_at=coalesce(archived_at,clock_timestamp()) where id=variant.id;
     end;
   end if;
 end loop;
 insert into public.audit_log(actor_id,action,target,diff) values(actor_id,'admin.good.options_saved','goods:'||target_id,
   jsonb_build_object('before',before_rows,'after',(select jsonb_agg(to_jsonb(v) order by v.sort_order,v.id) from public.goods_variants v where v.good_id=target_id)));
end;
$$

-- An explicit stop preserves even an unreferenced option. Removal from the full
-- editor continues to archive referenced rows and delete only unused rows.
create function public.admin_set_goods_variant_active(
  target_good_id text, target_variant_id uuid, target_active boolean,
  target_expected_updated_at timestamptz, target_price integer default null
)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 actor uuid:=auth.uid(); good public.goods; variant public.goods_variants;
 before_row jsonb; restored_price integer;
begin
 if actor is null then raise sqlstate '28000' using message='auth_required'; end if;
 if not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
 if target_variant_id is null or target_active is null or target_expected_updated_at is null
   or (not target_active and target_price is not null) then
   raise invalid_parameter_value using message='invalid_variant_availability'; end if;
 select * into good from public.goods where id=target_good_id for update;
 if not found then raise no_data_found using message='good_not_found'; end if;
 if good.archived_at is not null then raise check_violation using message='catalog_archived'; end if;
 select * into variant from public.goods_variants where id=target_variant_id and good_id=target_good_id for update;
 if not found then raise no_data_found using message='goods_variant_not_found'; end if;
 if target_active is distinct from (variant.archived_at is null) then
   if variant.updated_at is distinct from target_expected_updated_at then
     raise sqlstate 'PT409' using message='goods_variant_changed'; end if;
   restored_price:=coalesce(target_price,variant.price);
   if target_active then
     if restored_price<good.price then raise check_violation using message='variant_price_below_base'; end if;
     if exists(select 1 from public.goods_variants other where other.good_id=good.id
       and other.id<>variant.id and other.archived_at is null and other.attributes=variant.attributes) then
       raise check_violation using message='goods_variant_combination_exists'; end if;
     if (select count(*) from public.goods_variants other where other.good_id=good.id
       and (other.archived_at is null or other.is_default or other.id=variant.id))>100 then
       raise check_violation using message='goods_options_limit'; end if;
   end if;
   before_row:=to_jsonb(variant);
   update public.goods_variants set
     archived_at=case when target_active then null else clock_timestamp() end,
     price=case when target_active then restored_price else price end
     where id=variant.id returning * into variant;
   insert into public.audit_log(actor_id,action,target,diff) values(actor,
     case when target_active then 'admin.good.option_activated' else 'admin.good.option_stopped' end,
     'goods:'||good.id,jsonb_build_object('variantId',variant.id,'before',before_row,'after',to_jsonb(variant)));
 end if;
 return jsonb_build_object('variantId',variant.id,'isActive',variant.archived_at is null,
   'price',variant.price,'updatedAt',variant.updated_at,'ipId',good.ip_id);
end;
$$

-- Computed fields retain the existing search relation and PostgREST's exact
-- count/filter/range. The unnamed row argument keeps them off the RPC surface.
create function public.admin_goods_active_stock_qty(public.goods)
returns integer language plpgsql stable security invoker set search_path='' as $$
begin
 if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='admin_only'; end if;
 return (select coalesce(sum(stock_qty),0)::integer from public.goods_variants
   where good_id=($1).id and archived_at is null);
end;
$$

create function public.admin_goods_low_stock_option_count(public.goods)
returns integer language plpgsql stable security invoker set search_path='' as $$
begin
 if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='admin_only'; end if;
 return (select count(*)::integer from public.goods_variants
   where good_id=($1).id and low_stock_threshold is not null and stock_qty<=low_stock_threshold);
end;
$$

create function public.admin_save_good(target_good jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  saved jsonb;
  previous_name text;
  next_name text;
begin
  if auth.uid() is null or not public.is_staff() then
    raise insufficient_privilege using message='staff_required';
  end if;
  if target_good ? 'name_en' then
    if jsonb_typeof(target_good->'name_en') not in ('string','null') then
      raise check_violation using message='invalid_good_english_name';
    end if;
    next_name := nullif(btrim(target_good->>'name_en'), '');
    if char_length(next_name) > 200 then
      raise check_violation using message='invalid_good_english_name';
    end if;
  end if;
  saved := private.admin_save_good_before_english_name(target_good);
  if target_good ? 'name_en' then
    select name_en into previous_name from public.goods where id=saved->>'id' for update;
    if previous_name is distinct from next_name then
      update public.goods set name_en=next_name where id=saved->>'id';
      insert into public.audit_log(actor_id,action,target,diff)
      values(auth.uid(),'admin.good.english_name_saved','goods:'||(saved->>'id'),
        jsonb_build_object('before',previous_name,'after',next_name));
    end if;
  end if;
  return saved;
end;
$$

-- Keep the relation-returning RPC used by the paginated admin goods list and Excel
-- candidate export. Search remains staff-only and wildcard-safe.
create or replace function public.admin_search_goods(search_text text default null)
returns setof public.goods
language plpgsql stable security invoker
set search_path = ''
as $$
declare
  needle text := btrim(coalesce(search_text, ''));
  pattern text;
begin
  if auth.uid() is null or not public.is_staff() then
    raise insufficient_privilege using message = 'admin_only';
  end if;
  if length(needle) > 100 then
    raise invalid_parameter_value using message = 'goods_search_too_long';
  end if;
  pattern := '%' || replace(replace(replace(needle, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%';
  return query
    select g.* from public.goods g
    where needle = '' or g.name ilike pattern escape E'\\'
      or coalesce(g.name_en, '') ilike pattern escape E'\\'
      or g.code ilike pattern escape E'\\'
      or g.id ilike pattern escape E'\\'
      or exists (
        select 1 from unnest(g.search_keywords) as item(keyword)
        where keyword ilike pattern escape E'\\'
      )
      or exists (
        select 1 from public.goods_variants v
        where v.good_id = g.id and v.code ilike pattern escape E'\\'
      );
end;
$$

-- #470 already owns the public save seam and delegates the established write/audit
-- contract to private.admin_save_good_before_english_name. Extend that wrapper in
-- place so existing import callers and the English-name seam continue to compose.
create or replace function public.admin_save_good(target_good jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  saved jsonb;
  previous_name text;
  next_name text;
  previous_search_keywords text[];
  next_search_keywords text[];
  previous_display_order integer;
  next_display_order integer;
  metadata_diff jsonb := '{}'::jsonb;
  has_search_keywords boolean := target_good ? 'search_keywords';
  has_display_order boolean := target_good ? 'display_order';
begin
  if auth.uid() is null or not public.is_staff() then
    raise insufficient_privilege using message='staff_required';
  end if;

  if target_good ? 'name_en' then
    if jsonb_typeof(target_good->'name_en') not in ('string','null') then
      raise check_violation using message='invalid_good_english_name';
    end if;
    next_name := nullif(btrim(target_good->>'name_en'), '');
    if char_length(next_name) > 200 then
      raise check_violation using message='invalid_good_english_name';
    end if;
  end if;

  if has_search_keywords then
    if target_good->'search_keywords' is null
      or jsonb_typeof(target_good->'search_keywords') = 'null' then
      next_search_keywords := '{}'::text[];
    elsif jsonb_typeof(target_good->'search_keywords') <> 'array'
      or jsonb_array_length(target_good->'search_keywords') > 50
      or exists (
        select 1 from jsonb_array_elements(target_good->'search_keywords') as item(value)
        where jsonb_typeof(item.value) <> 'string'
      )
      or exists (
        select 1 from jsonb_array_elements_text(target_good->'search_keywords') as item(value)
        where char_length(btrim(item.value)) > 80
      ) then
      raise check_violation using message='invalid_good_search_keywords';
    else
      select coalesce(array_agg(keyword order by ordinal), '{}'::text[])
        into next_search_keywords
      from (
        select distinct on (lower(btrim(item.value)))
          btrim(item.value) as keyword,
          item.ordinal
        from jsonb_array_elements_text(target_good->'search_keywords')
          with ordinality as item(value, ordinal)
        where btrim(item.value) <> ''
        order by lower(btrim(item.value)), item.ordinal
      ) as deduplicated;
      if not private.good_search_keywords_valid(next_search_keywords) then
        raise check_violation using message='invalid_good_search_keywords';
      end if;
    end if;
  end if;

  if has_display_order then
    if target_good->'display_order' is null
      or jsonb_typeof(target_good->'display_order') = 'null' then
      next_display_order := null;
    elsif jsonb_typeof(target_good->'display_order') <> 'number'
      or target_good->>'display_order' !~ '^[0-9]+$'
      or (target_good->>'display_order')::numeric > 2147483647 then
      raise check_violation using message='invalid_good_display_order';
    else
      next_display_order := (target_good->>'display_order')::integer;
    end if;
  end if;

  saved := private.admin_save_good_before_english_name(target_good);

  if target_good ? 'name_en' then
    select name_en into previous_name
    from public.goods
    where id=saved->>'id'
    for update;
    if previous_name is distinct from next_name then
      update public.goods set name_en=next_name where id=saved->>'id';
      insert into public.audit_log(actor_id,action,target,diff)
      values(auth.uid(),'admin.good.english_name_saved','goods:'||(saved->>'id'),
        jsonb_build_object('before',previous_name,'after',next_name));
    end if;
  end if;

  if has_search_keywords or has_display_order then
    select search_keywords, display_order
      into previous_search_keywords, previous_display_order
    from public.goods
    where id=saved->>'id'
    for update;

    if has_search_keywords and previous_search_keywords is distinct from next_search_keywords then
      update public.goods
      set search_keywords=next_search_keywords
      where id=saved->>'id';
      metadata_diff := metadata_diff || jsonb_build_object(
        'search_keywords_before', previous_search_keywords,
        'search_keywords_after', next_search_keywords
      );
    end if;
    if has_display_order and previous_display_order is distinct from next_display_order then
      update public.goods
      set display_order=next_display_order
      where id=saved->>'id';
      metadata_diff := metadata_diff || jsonb_build_object(
        'display_order_before', previous_display_order,
        'display_order_after', next_display_order
      );
    end if;
    if metadata_diff <> '{}'::jsonb then
      insert into public.audit_log(actor_id,action,target,diff)
      values(auth.uid(),'admin.good.discovery_metadata_saved','goods:'||(saved->>'id'),metadata_diff);
    end if;
  end if;

  return saved;
end;
$$

-- Legacy metadata upserts do not know about public_slug yet. Existing-row
-- handling must happen before the global namespace lock: admin_upsert_ip can
-- already hold the IP row lock, while the identity RPC takes the global lock
-- before that row lock. This ordering avoids a row↔global advisory deadlock.
create function private.default_ip_public_slug()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  existing_public_slug text;
begin
  -- `admin_upsert_ip` uses INSERT ... ON CONFLICT(id) DO UPDATE. Its
  -- pre-existing call shape has no public_slug argument, so an update of a
  -- renamed IP must retain the current canonical value instead of treating
  -- the immutable id as a fresh slug candidate.
  select ip.public_slug
    into existing_public_slug
  from public.ips as ip
  where ip.id = new.id;
  if found then
    if new.public_slug is null then
      new.public_slug := existing_public_slug;
      return new;
    end if;
    if new.public_slug is distinct from existing_public_slug then
      raise insufficient_privilege using message = 'ip_public_slug_write_requires_rpc';
    end if;
    return new;
  end if;

  -- New internal IDs retain the existing catalog ID contract. A direct
  -- INSERT may only derive public_slug from that ID; selecting a different
  -- public slug belongs to the audited identity RPC after creation.
  if new.public_slug is null then
    new.public_slug := new.id;
  elsif new.public_slug is distinct from new.id then
    raise insufficient_privilege using message = 'ip_public_slug_write_requires_rpc';
  end if;

  -- Only the namespace check for a genuinely new ID needs the global lock.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ip_public_slug_identity', 0)
  );
  if exists (
    select 1 from public.ips as ip where ip.public_slug = new.public_slug
  ) or exists (
    select 1 from public.ip_public_slug_aliases as alias where alias.slug = new.public_slug
  ) then
    raise unique_violation using message = 'ip_public_slug_taken';
  end if;
  return new;
end;
$$

create trigger ips_default_public_slug
before insert on public.ips
for each row execute function private.default_ip_public_slug()

create trigger ips_public_slug_write_guard
before update of public_slug on public.ips
for each row execute function private.guard_ip_public_slug_write()

create policy ip_public_slug_aliases_read
  on public.ip_public_slug_aliases for select
  using (
    exists (
      select 1
      from public.ips as ip
      where ip.id = ip_public_slug_aliases.ip_id
        and (
          (ip.archived_at is null and ip.published_at is not null)
          or (select public.is_staff())
        )
    )
  )

create function public.admin_update_ip_identity(
  target_id text,
  target_public_slug text,
  target_expected_public_slug text
)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor_id uuid := (select auth.uid());
  current_public_slug text;
begin
  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;
  if not public.is_staff() then
    raise insufficient_privilege using message = 'forbidden';
  end if;
  if target_id is null
     or target_id !~ '^[a-z0-9][a-z0-9-]*$'
     or target_public_slug is null
     or target_expected_public_slug is null
  then
    raise invalid_parameter_value using message = 'invalid_ip_identity';
  end if;
  if target_public_slug !~ '^[a-z0-9](?:[a-z0-9-]{0,78}[a-z0-9])?$'
     or target_public_slug = 'aouad'
  then
    raise invalid_parameter_value using message = 'invalid_ip_public_slug';
  end if;

  -- All slug checks and the alias append happen under one global identity lock.
  -- The row lock then makes the expected slug a real stale-write guard.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ip_public_slug_identity', 0)
  );
  select ip.public_slug
    into current_public_slug
  from public.ips as ip
  where ip.id = target_id
  for update of ip;

  if not found then
    raise no_data_found using message = 'catalog_not_found';
  end if;
  if current_public_slug is distinct from target_expected_public_slug then
    -- PostgREST retries SQLSTATE 40001 indefinitely. This is an expected
    -- business stale-write response, so use a private 409 class instead.
    raise exception using errcode = 'PT409', message = 'ip_public_slug_conflict';
  end if;
  if current_public_slug = target_public_slug then
    return false;
  end if;

  if exists (
    select 1 from public.ips as ip
    where ip.public_slug = target_public_slug
      and ip.id <> target_id
  ) or exists (
    select 1 from public.ip_public_slug_aliases as alias
    where alias.slug = target_public_slug
  ) then
    raise unique_violation using message = 'ip_public_slug_taken';
  end if;

  -- This FK deliberately prevents hard deletion of an IP whose old URL is a
  -- historical alias. The alias row is append-only and uniquely owned.
  insert into public.ip_public_slug_aliases (slug, ip_id)
  values (current_public_slug, target_id);

  perform pg_catalog.set_config('app.ip_public_slug_write', 'admin_update_ip_identity', true);
  update public.ips
  set public_slug = target_public_slug,
      updated_at = pg_catalog.now()
  where id = target_id;
  perform pg_catalog.set_config('app.ip_public_slug_write', '', true);

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'admin.ip.identity_updated',
    'ips:' || target_id,
    pg_catalog.jsonb_build_object(
      'internal_id', target_id,
      'previous_public_slug', current_public_slug,
      'public_slug', target_public_slug,
      'alias_preserved', true
    )
  );

  return true;
end;
$$

create trigger goods_variant_external_identity_touch
before update on private.goods_variant_external_identity
for each row execute function private.touch_goods_variant_external_identity()

-- One private writer owns normalization, row locking, optimistic conflict
-- detection, and the audit record. The public RPC below is the authenticated
-- entry point; admin_save_good/import can call this helper in the same
-- transaction when an option row carries external fields.
create function private.save_goods_variant_external_identity(
  target_good_id text,
  target_variant_id uuid,
  target_erp_code text,
  target_erp_name text,
  target_barcode text,
  target_expected_updated_at timestamptz default null,
  target_actor uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor_id uuid := coalesce(target_actor, auth.uid());
  variant public.goods_variants;
  previous private.goods_variant_external_identity;
  saved private.goods_variant_external_identity;
  previous_json jsonb;
  next_erp_code text := nullif(btrim(target_erp_code), '');
  next_erp_name text := nullif(btrim(target_erp_name), '');
  next_barcode text := nullif(btrim(target_barcode), '');
begin
  if actor_id is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if target_good_id is null or btrim(target_good_id) = '' or char_length(target_good_id) > 200 then
    raise invalid_parameter_value using message = 'invalid_goods_variant_external_identity';
  end if;

  -- Keep the catalog lock order used by the option editor and checkout:
  -- parent good, then variant, then its private external_identity row.
  perform 1 from public.goods where id = target_good_id for update;
  if not found then
    raise no_data_found using message = 'goods_variant_not_found';
  end if;
  select * into variant
  from public.goods_variants
  where id = target_variant_id and good_id = target_good_id
  for update;
  if not found then
    raise no_data_found using message = 'goods_variant_not_found';
  end if;

  select * into previous
  from private.goods_variant_external_identity
  where variant_id = target_variant_id
  for update;

  -- Presence-aware optimistic concurrency: NULL expected means the editor saw
  -- no external_identity row. It is valid for a first write, but conflicts when another
  -- operator created a row after that read. Conversely, an existing row must
  -- always be submitted with its exact revision, including when it is being
  -- cleared.
  if (case when previous.variant_id is null then null::timestamptz else previous.updated_at end)
    is distinct from target_expected_updated_at then
    -- PT409 is a business stale-write response. Using PostgreSQL's 40001 here
    -- makes PostgREST retry the RPC as if it were a transient transaction
    -- serialization failure.
    raise exception using errcode = 'PT409', message = 'goods_variant_external_identity_changed';
  end if;

  if next_erp_code is not null and char_length(next_erp_code) > 120
    or next_erp_name is not null and char_length(next_erp_name) > 200
    or next_barcode is not null and char_length(next_barcode) > 120 then
    raise check_violation using message = 'invalid_goods_variant_external_identity';
  end if;

  previous_json := jsonb_build_object(
    'erpCode', case when previous.variant_id is null then null else previous.erp_code end,
    'erpName', case when previous.variant_id is null then null else previous.erp_name end,
    'barcode', case when previous.variant_id is null then null else previous.barcode end
  );

  if next_erp_code is null and next_erp_name is null and next_barcode is null then
    delete from private.goods_variant_external_identity where variant_id = target_variant_id;
  else
    insert into private.goods_variant_external_identity (variant_id, erp_code, erp_name, barcode)
    values (target_variant_id, next_erp_code, next_erp_name, next_barcode)
    on conflict (variant_id) do update set
      erp_code = excluded.erp_code,
      erp_name = excluded.erp_name,
      barcode = excluded.barcode;
  end if;

  select * into saved
  from private.goods_variant_external_identity
  where variant_id = target_variant_id;

  if previous_json is distinct from jsonb_build_object(
    'erpCode', case when saved.variant_id is null then null else saved.erp_code end,
    'erpName', case when saved.variant_id is null then null else saved.erp_name end,
    'barcode', case when saved.variant_id is null then null else saved.barcode end
  ) then
    insert into public.audit_log(actor_id, action, target, diff)
    values (
      actor_id,
      'admin.good.variant_external_identity_saved',
      'goods_variant:' || target_variant_id::text,
      jsonb_build_object(
        'before', previous_json,
        'after', jsonb_build_object(
          'erpCode', case when saved.variant_id is null then null else saved.erp_code end,
          'erpName', case when saved.variant_id is null then null else saved.erp_name end,
          'barcode', case when saved.variant_id is null then null else saved.barcode end
        )
      )
    );
  end if;

  return jsonb_build_object(
    'variantId', target_variant_id,
    'goodId', target_good_id,
    'erpCode', case when saved.variant_id is null then null else saved.erp_code end,
    'erpName', case when saved.variant_id is null then null else saved.erp_name end,
    'barcode', case when saved.variant_id is null then null else saved.barcode end,
    'updatedAt', case when saved.variant_id is null then null else saved.updated_at end
  );
end;
$$

-- Bulk option saves and workbook imports can carry these keys without making
-- the public goods_variants row or its own code contract depend on ERP data.
-- Rows that omit every external key preserve their existing external_identity; an
-- explicit blank/null clears it.
create function private.save_goods_variant_external_identities(
  target_good_id text,
  target_rows jsonb,
  target_actor uuid default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor_id uuid := coalesce(target_actor, auth.uid());
  item jsonb;
  ordinal integer;
  variant_id uuid;
  external_identity jsonb;
  has_external_fields boolean;
  code_value text;
  name_value text;
  barcode_value text;
  expected_updated_at timestamptz;
begin
  if actor_id is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if target_rows is null or jsonb_typeof(target_rows) is distinct from 'array' then
    raise check_violation using message = 'invalid_goods_options';
  end if;

  for item, ordinal in
    select value, ordinality::integer
    from jsonb_array_elements(target_rows) with ordinality
  loop
    if jsonb_typeof(item) is distinct from 'object' then
      raise check_violation using message = 'invalid_goods_options';
    end if;
    external_identity := case
      when item ? 'externalIdentity' then item -> 'externalIdentity'
      else item
    end;
    has_external_fields :=
      external_identity ? 'erpCode' or external_identity ? 'erpName' or external_identity ? 'barcode'
      or external_identity ? 'erp_code' or external_identity ? 'erp_name';
    if not has_external_fields then
      continue;
    end if;
    if jsonb_typeof(external_identity) is distinct from 'object' then
      raise check_violation using message = 'invalid_goods_variant_external_identity';
    end if;

    code_value := case when external_identity ? 'erpCode' then external_identity ->> 'erpCode' else external_identity ->> 'erp_code' end;
    name_value := case when external_identity ? 'erpName' then external_identity ->> 'erpName' else external_identity ->> 'erp_name' end;
    barcode_value := external_identity ->> 'barcode';
    expected_updated_at := null;
    if external_identity ? 'externalUpdatedAt' or external_identity ? 'external_updated_at' then
      begin
        expected_updated_at := coalesce(external_identity ->> 'externalUpdatedAt', external_identity ->> 'external_updated_at')::timestamptz;
      exception when others then
        raise check_violation using message = 'invalid_goods_variant_external_identity';
      end;
    end if;

    if nullif(item ->> 'id', '') is not null then
      if (item ->> 'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        raise check_violation using message = 'invalid_goods_variant_external_identity';
      end if;
      variant_id := (item ->> 'id')::uuid;
    else
      select variant.id into variant_id
      from public.goods_variants variant
      where variant.good_id = target_good_id and variant.sort_order = ordinal - 1
        and variant.attributes = coalesce(item -> 'attributes', '{}'::jsonb)
      order by variant.id
      limit 1;
    end if;
    if variant_id is null then
      raise check_violation using message = 'goods_variant_not_found';
    end if;

    perform private.save_goods_variant_external_identity(
      target_good_id, variant_id, code_value, name_value, barcode_value, expected_updated_at, actor_id
    );
  end loop;
end;
$$

create function public.admin_save_good(target_good jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  saved jsonb;
begin
  if auth.uid() is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  saved := private.admin_save_good_before_external_identity(target_good);
  if target_good ? 'variants' then
    perform private.save_goods_variant_external_identities(
      saved ->> 'id', target_good -> 'variants', auth.uid()
    );
  end if;
  return saved;
end;
$$

create trigger order_items_capture_external_identity
after insert on public.order_items
for each row execute function private.capture_order_item_external_identity()

-- Published versions keep their economics forever; stopping a version only changes
-- its state. A changed offer is a new row. Orders retain both the row id and amounts.
create function private.guard_goods_price_period() returns trigger
language plpgsql security definer set search_path='' as $$
declare variant public.goods_variants;
begin
  perform 1 from public.goods where id=new.good_id for update;
  select * into variant from public.goods_variants
    where id=new.variant_id and good_id=new.good_id for update;
  if not found then raise check_violation using message='goods_variant_not_found'; end if;
  if tg_op='UPDATE' then
    -- A never-published good can still change its draft slug. Its immutable
    -- option id remains the identity while the composite FK cascades good_id.
    if (new.id,new.variant_id,new.created_at,new.created_by)
      is distinct from (old.id,old.variant_id,old.created_at,old.created_by) then
      raise check_violation using message='price_period_identity_immutable';
    end if;
    if old.state in ('active','disabled') and (
      (new.regular_price,new.discount_price,new.starts_at,new.ends_at)
        is distinct from (old.regular_price,old.discount_price,old.starts_at,old.ends_at)
      or new.state='draft' or (old.state='disabled' and new.state<>'disabled')
    ) then raise check_violation using message='price_period_requires_new_version'; end if;
  end if;
  if new.state='active' then
    if variant.archived_at is not null then
      raise check_violation using message='price_period_variant_inactive';
    end if;
    if new.regular_price is distinct from variant.price then
      raise check_violation using message='price_period_regular_price_changed';
    end if;
    if exists(select 1 from private.goods_variant_price_periods period
      where period.variant_id=new.variant_id and period.id<>new.id and period.state='active'
        and tstzrange(period.starts_at,period.ends_at,'[)') && tstzrange(new.starts_at,new.ends_at,'[)')) then
      raise exclusion_violation using message='price_period_overlap';
    end if;
  end if;
  return new;
end $$

create function private.guard_goods_variant_period_price() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.price is distinct from old.price and exists (
    select 1 from private.goods_variant_price_periods
    where variant_id=old.id and state='active' and ends_at>statement_timestamp()
  ) then raise check_violation using message='active_price_period_requires_reset'; end if;
  return new;
end $$

create function public.admin_list_goods_price_periods(p_good_id text)
returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id',id,'goodId',good_id,'variantId',variant_id,
    'state',state,'regularPrice',regular_price,'discountPrice',discount_price,'startsAt',starts_at,'endsAt',ends_at,
    'revision',revision,'createdAt',created_at,'updatedAt',updated_at) order by created_at,id)
    from private.goods_variant_price_periods where good_id=p_good_id),'[]'::jsonb);
end $$

create function public.admin_save_goods_price_period(
  p_good_id text,p_variant_id uuid,p_period_id uuid,p_period jsonb,p_expected_revision integer default null
) returns jsonb language plpgsql security definer set search_path='' as $$
declare
  previous private.goods_variant_price_periods;
  saved private.goods_variant_price_periods;
  variant public.goods_variants;
  next_state text;
  next_price integer;
  next_start timestamptz;
  next_end timestamptz;
  next_regular integer;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  if jsonb_typeof(p_period) is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(p_period) key where key not in ('state','discountPrice','startsAt','endsAt'))
    or p_period->>'state' is null or p_period->>'state' not in ('draft','active','disabled') then
    raise check_violation using message='invalid_price_period';
  end if;
  next_state:=p_period->>'state';
  if coalesce(jsonb_typeof(p_period->'discountPrice'),'null')<>'null' then
    if jsonb_typeof(p_period->'discountPrice')<>'number' or p_period->>'discountPrice' !~ '^[1-9][0-9]*$'
      or (p_period->>'discountPrice')::numeric>2147483647 then
      raise check_violation using message='invalid_price_period';
    end if;
    next_price:=(p_period->>'discountPrice')::integer;
  end if;
  if coalesce(jsonb_typeof(p_period->'startsAt'),'null')<>'null' then
    if jsonb_typeof(p_period->'startsAt')<>'string' or p_period->>'startsAt' !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' then
      raise check_violation using message='price_period_timezone_required';
    end if;
    next_start:=(p_period->>'startsAt')::timestamptz;
  end if;
  if coalesce(jsonb_typeof(p_period->'endsAt'),'null')<>'null' then
    if jsonb_typeof(p_period->'endsAt')<>'string' or p_period->>'endsAt' !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' then
      raise check_violation using message='price_period_timezone_required';
    end if;
    next_end:=(p_period->>'endsAt')::timestamptz;
  end if;
  if next_state='active' and (next_price is null or next_start is null or next_end is null) then
    raise check_violation using message='price_period_not_configured';
  end if;
  if (next_start is not null and not isfinite(next_start)) or (next_end is not null and not isfinite(next_end))
    or (next_start is not null and next_end is not null and next_start>=next_end) then
    raise check_violation using message='invalid_price_period';
  end if;
  perform 1 from public.goods where id=p_good_id for update;
  select * into variant from public.goods_variants where id=p_variant_id and good_id=p_good_id for update;
  if not found then raise check_violation using message='goods_variant_not_found'; end if;
  next_regular:=variant.price;
  if p_period_id is not null then
    select * into previous from private.goods_variant_price_periods
      where id=p_period_id and good_id=p_good_id and variant_id=p_variant_id for update;
    if not found then raise no_data_found using message='price_period_not_found'; end if;
    if p_expected_revision is null or previous.revision<>p_expected_revision then
      raise sqlstate 'PT409' using message='price_period_changed';
    end if;
    if previous.state<>'draft' then next_regular:=previous.regular_price; end if;
    update private.goods_variant_price_periods set state=next_state,regular_price=next_regular,
      discount_price=next_price,starts_at=next_start,ends_at=next_end,revision=revision+1,
      updated_by=auth.uid(),updated_at=clock_timestamp()
    where id=p_period_id returning * into saved;
  else
    if p_expected_revision is not null then raise check_violation using message='invalid_price_period'; end if;
    insert into private.goods_variant_price_periods(good_id,variant_id,state,regular_price,discount_price,starts_at,ends_at,created_by,updated_by)
    values(p_good_id,p_variant_id,next_state,next_regular,next_price,next_start,next_end,auth.uid(),auth.uid())
    returning * into saved;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.good.price_period_saved','goods:'||p_good_id,
    jsonb_build_object('before',case when previous.id is null then null else to_jsonb(previous) end,'after',to_jsonb(saved)));
  return jsonb_build_object('id',saved.id,'revision',saved.revision,
    'ipId',(select ip_id from public.goods where id=p_good_id));
end $$

-- Keep the existing public save/import seam atomic. Omitted fields are preserved;
-- disabled numeric drafts are retained but never evaluated as active limits.
alter function public.admin_save_good(jsonb) set schema private

create function public.admin_save_good(target_good jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare saved jsonb; previous public.goods; next_good public.goods; field text; before_policy jsonb; after_policy jsonb;
  owned_payload jsonb; initial_controls jsonb; existing_id text;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  foreach field in array array['allow_card_payment','allow_bank_transfer','order_quantity_limit_enabled','member_purchase_limit_enabled'] loop
    if target_good ? field and jsonb_typeof(target_good->field) is distinct from 'boolean' then
      raise check_violation using message='invalid_goods_sales_policy';
    end if;
  end loop;
  if target_good ? 'sale_restriction' and (jsonb_typeof(target_good->'sale_restriction') is distinct from 'string'
    or target_good->>'sale_restriction' not in ('none','adult')) then
    raise check_violation using message='invalid_goods_sales_policy';
  end if;
  foreach field in array array['min_order_qty','max_order_qty','member_lifetime_qty_limit'] loop
    if target_good ? field and jsonb_typeof(target_good->field)<>'null' then
      if jsonb_typeof(target_good->field)<>'number' or target_good->>field !~ '^[1-9][0-9]*$'
        or (target_good->>field)::numeric>2147483647 then
        raise check_violation using message='invalid_goods_sales_policy';
      end if;
    end if;
  end loop;
  -- Apply controls before the legacy writer can emit a stock/publication alert.
  -- Match the legacy editor's advisory->good lock order, including a draft rename.
  existing_id:=coalesce(nullif(btrim(target_good->>'previous_id'),''),nullif(btrim(target_good->>'id'),''));
  if existing_id is not null then
    perform pg_advisory_xact_lock(hashtextextended('admin_good:'||existing_id,0));
    select * into previous from public.goods where id=existing_id for update;
    if found then
      initial_controls:=jsonb_build_object('allow_card_payment',previous.allow_card_payment,
        'allow_bank_transfer',previous.allow_bank_transfer,'sale_restriction',previous.sale_restriction);
      update public.goods set
        allow_card_payment=case when target_good?'allow_card_payment' then (target_good->>'allow_card_payment')::boolean else allow_card_payment end,
        allow_bank_transfer=case when target_good?'allow_bank_transfer' then (target_good->>'allow_bank_transfer')::boolean else allow_bank_transfer end,
        sale_restriction=case when target_good?'sale_restriction' then (target_good->>'sale_restriction')::public.goods_sale_restriction else sale_restriction end
      where id=existing_id;
      if target_good->>'publish'='false' then perform public.admin_set_good_published(existing_id,false); end if;
    end if;
  end if;
  -- New goods begin as drafts. The final controls must exist before first publish.
  saved:=private.admin_save_good_before_sales_policy(case when target_good->>'publish' in ('true','false')
    then target_good||'{"publish":null}'::jsonb else target_good end);
  select * into previous from public.goods where id=saved->>'id' for update;
  select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into owned_payload
  from jsonb_each(target_good) where key=any(array['allow_card_payment','allow_bank_transfer','sale_restriction',
    'order_quantity_limit_enabled','min_order_qty','max_order_qty','member_purchase_limit_enabled','member_lifetime_qty_limit']);
  next_good:=jsonb_populate_record(previous,owned_payload);
  before_policy:=jsonb_build_object('allow_card_payment',previous.allow_card_payment,
    'allow_bank_transfer',previous.allow_bank_transfer,'sale_restriction',previous.sale_restriction,
    'order_quantity_limit_enabled',previous.order_quantity_limit_enabled,'min_order_qty',previous.min_order_qty,
    'max_order_qty',previous.max_order_qty,'member_purchase_limit_enabled',previous.member_purchase_limit_enabled,
    'member_lifetime_qty_limit',previous.member_lifetime_qty_limit);
  before_policy:=before_policy||coalesce(initial_controls,'{}'::jsonb);
  after_policy:=jsonb_build_object('allow_card_payment',next_good.allow_card_payment,
    'allow_bank_transfer',next_good.allow_bank_transfer,'sale_restriction',next_good.sale_restriction,
    'order_quantity_limit_enabled',next_good.order_quantity_limit_enabled,'min_order_qty',next_good.min_order_qty,
    'max_order_qty',next_good.max_order_qty,'member_purchase_limit_enabled',next_good.member_purchase_limit_enabled,
    'member_lifetime_qty_limit',next_good.member_lifetime_qty_limit);
  if after_policy is distinct from before_policy then
    update public.goods set allow_card_payment=next_good.allow_card_payment,
      allow_bank_transfer=next_good.allow_bank_transfer,sale_restriction=next_good.sale_restriction,
      order_quantity_limit_enabled=next_good.order_quantity_limit_enabled,min_order_qty=next_good.min_order_qty,
      max_order_qty=next_good.max_order_qty,member_purchase_limit_enabled=next_good.member_purchase_limit_enabled,
      member_lifetime_qty_limit=next_good.member_lifetime_qty_limit where id=previous.id;
    insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.good.sales_policy_saved','goods:'||previous.id,
      jsonb_build_object('before',before_policy,'after',after_policy));
  end if;
  -- Both methods may be deliberately disabled. The public quote advertises an
  -- empty intersection and the locked order writer rejects either method.
  if target_good->>'publish' in ('true','false') then
    perform public.admin_set_good_published(saved->>'id',(target_good->>'publish')::boolean);
  end if;
  return saved;
end $$

-- Replace the authoritative writer, keeping its existing wrapper and grants.
CREATE OR REPLACE FUNCTION private.place_order_before_shipments(p_address jsonb, p_checkout_key uuid, p_payment_method order_payment_method)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  -- 결제사 최소 결제액(20260813242000 가드·lib/coupons.ts MIN_PAYABLE_TOTAL와 동치).
  -- 할인이 총액을 이 밑으로 내리면 가드가 주문 전체를 롤백하므로, 여기서 캡한다.
  c_min_payable_total constant bigint := 1000;
  v_user uuid := (select auth.uid());
  v_order uuid;
  v_existing_address jsonb;
  v_existing_payment_method public.order_payment_method;
  v_expires_at timestamptz;
  v_subtotal bigint := 0;
  v_shipping_fee bigint := 0;
  v_item_count integer := 0;
  v_recipient_name text;
  v_phone text;
  v_postal_code text;
  v_address1 text;
  v_optional text;
  v_selected_coupon uuid;
  v_coupon_eval record;
  v_discount bigint := 0;
  r record;
  v_variant public.goods_variants;
  v_price record;
  v_price_at timestamptz;
  v_limit_good public.goods;
  v_good_qty bigint;
  v_last_good_id text;
  v_quantity_error text;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if not exists (
    select 1
    from public.profiles as profile
    join auth.users as auth_user on auth_user.id = profile.id
    where profile.id = v_user
      and nullif(btrim(coalesce(profile.email, auth_user.email)), '') is not null
      and nullif(btrim(profile.nickname), '') is not null
      and profile.birth_date is not null
      and profile.birth_date <= current_date
      and profile.onboarded_at is not null
      and profile.consents ->> 'terms' = 'true'
      and profile.consents ->> 'privacy' = 'true'
  ) then
    raise insufficient_privilege using message = 'onboarding required';
  end if;

  if p_checkout_key is null then
    raise not_null_violation using message = 'checkout key required';
  end if;

  if p_address is null or jsonb_typeof(p_address) <> 'object' then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if not (p_address ?& array['recipientName', 'phone', 'postalCode', 'address1'])
     or exists (
       select 1
       from jsonb_object_keys(p_address) as address_key(key)
       where address_key.key not in (
         'recipientName', 'phone', 'postalCode', 'address1', 'address2', 'deliveryNote'
       )
     )
     or exists (
       select 1
       from jsonb_each(p_address) as address_value(key, value)
       where jsonb_typeof(address_value.value) <> 'string'
     ) then
    raise check_violation using message = 'invalid checkout address';
  end if;

  v_recipient_name := p_address ->> 'recipientName';
  v_phone := p_address ->> 'phone';
  v_postal_code := p_address ->> 'postalCode';
  v_address1 := p_address ->> 'address1';

  if v_recipient_name <> btrim(v_recipient_name, E' \t\n\r\f\v')
     or length(v_recipient_name) not between 1 and 50
     or v_phone !~ '^[0-9]{8,15}$'
     or v_postal_code !~ '^[0-9]{5}$'
     or v_address1 <> btrim(v_address1, E' \t\n\r\f\v')
     or length(v_address1) not between 1 and 200 then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if p_address ? 'address2' then
    v_optional := p_address ->> 'address2';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  if p_address ? 'deliveryNote' then
    v_optional := p_address ->> 'deliveryNote';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  -- 같은 사용자의 다른 탭 주문을 직렬화한다. 동일 키 재시도는 먼저 생성된
  -- 주문을 반환하고, 다른 키는 첫 주문이 비운 장바구니를 확인하게 된다.
  -- 쿠폰 적용·해제도 같은 잠금을 잡으므로 선택 교체와 소비가 경합하지 않는다.
  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  select orders.id, orders.address, orders.payment_method
    into v_order, v_existing_address, v_existing_payment_method
  from public.orders
  where orders.user_id = v_user
    and orders.checkout_key = p_checkout_key;

  if found then
    -- 같은 checkout key로 결제수단만 바꿔 다시 부르면 24시간 선점을 15분 주문에
    -- 덧씌우거나 그 반대가 된다. 주소와 같은 등급의 충돌로 막는다.
    if v_existing_address is distinct from p_address
      or v_existing_payment_method is distinct from p_payment_method
    then
      raise unique_violation using message = 'checkout key conflict';
    end if;
    return v_order;
  end if;

  if p_payment_method is null then
    raise invalid_parameter_value using message='payment method required';
  end if;

  -- 카드 15분 · 무통장 24시간. 무통장은 사람이 은행 앱을 열고 이체할 시간을
  -- 줘야 해서 선점 창이 길고, 그만큼 재고가 오래 묶인다 — 한정 드롭은
  -- goods.allow_bank_transfer로 아예 차단한다(ADR-0007).
  v_expires_at := case
    when p_payment_method = 'bank_transfer' then now() + interval '24 hours'
    else now() + interval '15 minutes'
  end;

  insert into public.orders (
    user_id, status, total, shipping_fee, address, expires_at, checkout_key, payment_method
  )
  values (v_user, 'pending', 0, 0, p_address, v_expires_at, p_checkout_key, p_payment_method)
  returning id into v_order;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('cart:'||v_user::text,0));
  -- This timestamp is fixed after the member/cart locks. Waiting for a competing
  -- checkout cannot select a stale pre-lock clock value. Each order has one price
  -- boundary, including all its coupon and shipping calculations.
  v_price_at:=clock_timestamp();
  -- Parent goods are locked before their selected options and cache updates.
  for r in
    select
      cart.good_id,
      cart.variant_id,
      cart.qty,
      good.price,
      good.stock,
      good.stock_qty,
      good.name,
      good.type,
      good.ip_id,
      good.allow_bank_transfer,
      good.allow_card_payment,
      good.sale_restriction,
      good.published_at,
      good.archived_at
    from public.cart_items as cart
    join public.goods as good on good.id = cart.good_id
    where cart.user_id = v_user
    order by cart.good_id, cart.variant_id
    for update of cart, good
  loop
    -- The locked good fixes its parent association. Keep the IP SHARE lock until
    -- this order commits, serializing new purchases with an unpublish UPDATE.
    perform private.assert_ip_purchasable(r.ip_id);
    if r.published_at is null or r.archived_at is not null then
      raise check_violation using message='catalog_item_unavailable';
    end if;
    select * into v_variant from public.goods_variants where id=r.variant_id and good_id=r.good_id for update;
    if not found or v_variant.archived_at is not null then raise check_violation using message='catalog_item_unavailable'; end if;
    v_item_count := v_item_count + 1;

    -- Cart has one row per option. Check a good only before its first row is
    -- consumed, summing every selected option and any optional add-on of it.
    if v_last_good_id is distinct from r.good_id then
      select * into v_limit_good from public.goods where id=r.good_id;
      select sum(qty::bigint) into v_good_qty from public.cart_items where user_id=v_user and good_id=r.good_id;
      v_quantity_error:=private.check_goods_purchase_quantity(v_limit_good,v_user,v_good_qty,true);
      if v_quantity_error is not null then
        raise check_violation using message=v_quantity_error||': '||r.good_id;
      end if;
      v_last_good_id:=r.good_id;
    end if;
    select * into v_price from private.resolve_goods_variant_price(v_variant.id,v_price_at);


    if r.stock = 'soldout' or v_variant.stock_qty < r.qty then
      raise check_violation using message = format('out of stock: %s', r.good_id);
    end if;

    if p_payment_method = 'card' and not r.allow_card_payment then
      raise check_violation using message=format('card payment blocked: %s',r.good_id);
    end if;

    if p_payment_method = 'bank_transfer' and not r.allow_bank_transfer then
      raise check_violation using message = format('bank transfer blocked: %s', r.good_id);
    end if;

    -- 성인인증(#209·#210)이 도입되기 전까지 판매 제한 상품은 서버가 구매를
    -- 차단한다. 결제수단과 무관한 상품 축이라 무통장 검사와 별개로 판정한다.
    if r.sale_restriction <> 'none' then
      raise check_violation using message = format('restricted good blocked: %s', r.good_id);
    end if;

    perform private.change_goods_variant_stock(r.good_id, r.variant_id, -r.qty::bigint);

    insert into public.order_items (
      order_id,
      good_id,
      variant_id,
      qty,
      unit_price,
      good_name_snapshot,
      good_type_snapshot,
      good_ip_id_snapshot,
      regular_unit_price_snapshot,
      price_period_id,
      price_evaluated_at,
      sales_policy_snapshot
    )
    values (
      v_order,
      r.good_id,
      r.variant_id,
      r.qty,
      v_price.effective_price,
      r.name,
      r.type,
      r.ip_id,
      v_price.regular_price,
      v_price.price_period_id,
      v_price_at,
      jsonb_build_object('version',1,'allowCardPayment',r.allow_card_payment,'allowBankTransfer',r.allow_bank_transfer,
        'orderQuantityLimitEnabled',v_limit_good.order_quantity_limit_enabled,
        'minOrderQty',v_limit_good.min_order_qty,'maxOrderQty',v_limit_good.max_order_qty,
        'memberPurchaseLimitEnabled',v_limit_good.member_purchase_limit_enabled,
        'memberLifetimeQtyLimit',v_limit_good.member_lifetime_qty_limit)
    );

    -- 조회 시 잠근 스냅샷 행만 지운다. 동시에 새로 담긴 다른 상품까지
    -- 마지막 broad delete가 없애지 않도록 상품 단위로 소비한다.
    delete from public.cart_items
    where user_id = v_user
      and good_id = r.good_id and variant_id = r.variant_id;

    v_subtotal := v_subtotal + (v_price.effective_price::bigint * r.qty::bigint);
  end loop;

  if v_item_count = 0 then
    raise check_violation using message = 'cart empty';
  end if;

  -- Shipping uses the period-adjusted item subtotal before coupon/credit deductions.
  -- Its order-item inputs already contain the immutable effective price.
  v_shipping_fee := private.goods_shipping_fee_for(v_order);

  -- 카트에 적용해 둔 쿠폰을 여기서 최종 검증하고 소비한다. 조건 미달이면 주문
  -- 전체를 거부한다 — 할인을 기대한 사용자를 조용히 정가로 결제시키지 않는다.
  select selection.user_coupon_id
  into v_selected_coupon
  from public.cart_coupon_selections as selection
  where selection.user_id = v_user;

  if v_selected_coupon is not null then
    -- 상태 전이 전에 보유 행을 잠근다. 같은 유저는 advisory lock으로 이미
    -- 직렬화되어 있고, 이 잠금은 향후 다른 경로가 생겨도 이중 사용을 막는 안전벨트다.
    perform held.id
    from public.user_coupons as held
    where held.id = v_selected_coupon
    for update;

    select * into v_coupon_eval
    from private.evaluate_user_coupon(v_selected_coupon, v_user, v_subtotal);
    if v_coupon_eval.o_reason is not null then
      raise check_violation using message = v_coupon_eval.o_reason;
    end if;
    -- 결제사 최소 결제액을 지키도록 할인을 캡한다 — 전액 쿠폰이 주문을
    -- 결제 불가(총액 < 1,000원)로 만들면 혜택이 주문 실패로 둔갑한다.
    v_discount := least(
      v_coupon_eval.o_discount,
      greatest(0, v_subtotal + v_shipping_fee - c_min_payable_total)
    );

    update public.user_coupons
    set status = 'used',
        used_at = now(),
        used_order_id = v_order
    where id = v_selected_coupon;

    insert into public.coupon_redemptions (
      user_coupon_id, coupon_code, user_id, order_id, discount_amount
    )
    values (
      v_selected_coupon, v_coupon_eval.o_coupon_code, v_user, v_order, v_discount
    );

    -- 소비한 선택만 지운다. 주문 진행 중 다른 탭이 교체한 새 선택은 남는다.
    delete from public.cart_coupon_selections
    where user_id = v_user
      and user_coupon_id = v_selected_coupon;
  end if;

  update public.orders
  set total = v_subtotal + v_shipping_fee - v_discount,
      shipping_fee = v_shipping_fee,
      discount_total = v_discount
  where id = v_order;

  -- 무통장에는 결제사 왕복이 없다. 그래서 원장 anchor(payment_attempts)를 여기서
  -- 바로 연다 — 없으면 운영자가 입금을 확인할 대상 자체가 없고, "결제 준비" 버튼을
  -- 눌러야 생기는 구조는 구매자가 이미 이체한 뒤에도 확인이 안 되는 창을 만든다.
  -- 새 함수를 두지 않고 카드와 같은 prepare를 부른다: 소유권·금액·스냅샷·정지
  -- 계정 검사가 한 곳에만 있어야 한다.
  if p_payment_method = 'bank_transfer' then
    perform public.prepare_goods_payment_attempt(v_user, v_order, 'bank_transfer');
  end if;

  -- 무통장 주문은 만든 순간이 안내 시점이다. 금액·입금자명 코드·기한이 모두
  -- 정해졌고, 이 알림을 놓치면 구매자는 어디로 얼마를 보낼지 알 수 없다.
  if p_payment_method = 'bank_transfer' then
    insert into public.notifications (
      user_id, type, title, body, link_path, source_type, source_id, dedupe_key
    )
    values (
      v_user,
      'order_bank_transfer_pending',
      '입금 안내를 확인해주세요',
      format(
        '%s원을 기한 안에 입금해주세요. 입금자명 끝에 주문코드 %s를 붙이면 확인이 빨라집니다.',
        to_char(v_subtotal + v_shipping_fee - v_discount, 'FM999,999,999'),
        private.bank_transfer_deposit_code(v_order)
      ),
      '/checkout/' || v_order::text,
      'order',
      v_order::text,
      'order:bank_transfer_pending:' || v_order::text
    )
    on conflict (user_id, dedupe_key) do nothing;
  end if;

  return v_order;
end;
$function$

-- #443: shipping quotes require the same explicit option identity as cart/order writes.
CREATE OR REPLACE FUNCTION public.quote_goods_shipping(items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare input record; good public.goods; variant public.goods_variants; line_qty integer; variant_key uuid; lines jsonb:='[]';
begin
  if jsonb_typeof(items) is distinct from 'array' or jsonb_array_length(items)>1000 then
    raise invalid_parameter_value using message='invalid_shipping_quote_items';
  end if;
  for input in select value from jsonb_array_elements(items) loop
    if jsonb_typeof(input.value) is distinct from 'object' or exists(select 1 from jsonb_object_keys(input.value) k where k not in ('goodId','variantId','qty'))
      or jsonb_typeof(input.value->'qty') is distinct from 'number'
      or jsonb_typeof(input.value->'variantId') is distinct from 'string'
      or (input.value->>'variantId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise invalid_parameter_value using message='invalid_shipping_quote_items'; end if;
    line_qty:=(input.value->>'qty')::integer;
    if line_qty not between 1 and 2147483647 then raise invalid_parameter_value using message='invalid_shipping_quote_items'; end if;
    select g.* into good from public.goods g join public.ips ip on ip.id=g.ip_id
      join public.fulfillment_origins origin on origin.id=g.origin_id and origin.is_active
      where g.id=input.value->>'goodId' and g.archived_at is null and g.published_at is not null and g.sale_restriction='none'
        and ip.archived_at is null and ip.published_at is not null;
    if not found then raise check_violation using message='shipping_quote_good_unavailable'; end if;
    variant_key:=(input.value->>'variantId')::uuid;
    select v.* into variant from public.goods_variants v where v.good_id=good.id and v.archived_at is null
      and v.id=variant_key;
    if not found then raise check_violation using message='shipping_quote_variant_unavailable'; end if;
    lines:=lines||jsonb_build_array(jsonb_build_object('origin_id',good.origin_id,'good_id',good.id,'qty',line_qty,
      'unit_price',(select effective_price from private.resolve_goods_variant_price(variant.id,statement_timestamp())),'fee_type',good.shipping_fee_type,'individual_fee',good.individual_fee));
  end loop;
  return private.calculate_goods_shipping(lines);
end $function$

-- Public/cart advisory quote. Member history is always derived from auth.uid();
-- there is no customer-supplied user id. It does not reserve or release anything.
create function public.quote_goods_sales(items jsonb)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare
  input record;
  line record;
  good public.goods;
  variant public.goods_variants;
  price record;
  normalized jsonb:='[]';
  quoted_lines jsonb:='[]';
  quoted_goods jsonb:='[]';
  at_time timestamptz:=statement_timestamp();
  actor uuid:=auth.uid();
  subtotal bigint:=0;
  card_allowed boolean:=true;
  bank_allowed boolean:=true;
  reserved_qty bigint;
  quantity_error text;
begin
  if jsonb_typeof(items) is distinct from 'array' or jsonb_array_length(items)>1000 then
    raise invalid_parameter_value using message='invalid_sales_quote_items';
  end if;
  for input in select value from jsonb_array_elements(items) loop
    if jsonb_typeof(input.value) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(input.value) key where key not in ('goodId','variantId','qty'))
      or jsonb_typeof(input.value->'goodId') is distinct from 'string'
      or nullif(btrim(input.value->>'goodId'),'') is null
      or jsonb_typeof(input.value->'variantId') is distinct from 'string'
      or input.value->>'variantId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or jsonb_typeof(input.value->'qty') is distinct from 'number'
      or input.value->>'qty' !~ '^[1-9][0-9]*$' then
      raise invalid_parameter_value using message='invalid_sales_quote_items';
    end if;
    if (input.value->>'qty')::numeric>2147483647 then
      raise invalid_parameter_value using message='invalid_sales_quote_items';
    end if;
    normalized:=normalized||jsonb_build_array(jsonb_build_object('good_id',input.value->>'goodId',
      'variant_id',(input.value->>'variantId')::uuid,'qty',(input.value->>'qty')::integer));
  end loop;
  for line in select good_id,variant_id,sum(qty::bigint)::bigint qty
    from jsonb_to_recordset(normalized) as item(good_id text,variant_id uuid,qty integer)
    group by good_id,variant_id order by good_id,variant_id
  loop
    select g.* into good from public.goods g join public.ips ip on ip.id=g.ip_id
      where g.id=line.good_id and g.archived_at is null and g.published_at is not null and g.sale_restriction='none'
        and ip.archived_at is null and ip.published_at is not null;
    if not found then raise check_violation using message='sales_quote_good_unavailable'; end if;
    select * into variant from public.goods_variants
      where id=line.variant_id and good_id=good.id and archived_at is null;
    if not found then raise check_violation using message='sales_quote_variant_unavailable'; end if;
    select * into price from private.resolve_goods_variant_price(variant.id,at_time);
    quoted_lines:=quoted_lines||jsonb_build_array(jsonb_build_object('goodId',good.id,'variantId',variant.id,'qty',line.qty,
      'regularPrice',price.regular_price,'effectivePrice',price.effective_price,'pricePeriodId',price.price_period_id,
      'startsAt',price.starts_at,'endsAt',price.ends_at,'available',good.stock<>'soldout' and line.qty<=variant.stock_qty));
    subtotal:=subtotal+line.qty*price.effective_price::bigint;
    card_allowed:=card_allowed and good.allow_card_payment;
    bank_allowed:=bank_allowed and good.allow_bank_transfer;
  end loop;
  for line in select good_id,sum(qty::bigint)::bigint qty
    from jsonb_to_recordset(normalized) as item(good_id text,variant_id uuid,qty integer)
    group by good_id order by good_id
  loop
    select * into good from public.goods where id=line.good_id;
    reserved_qty:=case when actor is null then null else private.member_goods_reserved_qty(actor,good.id) end;
    quantity_error:=private.check_goods_purchase_quantity(good,actor,line.qty,true);
    quoted_goods:=quoted_goods||jsonb_build_array(jsonb_build_object('goodId',good.id,'qty',line.qty,
      'orderQuantityLimitEnabled',good.order_quantity_limit_enabled,'minOrderQty',good.min_order_qty,'maxOrderQty',good.max_order_qty,
      'memberPurchaseLimitEnabled',good.member_purchase_limit_enabled,'memberLifetimeQtyLimit',good.member_lifetime_qty_limit,
      'memberReservedQty',reserved_qty,'memberRemainingQty',case when not good.member_purchase_limit_enabled or actor is null
        then null else greatest(0,good.member_lifetime_qty_limit::bigint-reserved_qty) end,'reason',quantity_error));
  end loop;
  return jsonb_build_object('calculatedAt',at_time,'subtotal',subtotal,'lines',quoted_lines,'goods',quoted_goods,
    'shipping',public.quote_goods_shipping(items),
    'nextChangeAt',(select min(boundary.change_at) from private.goods_variant_price_periods schedule
      cross join lateral (values(schedule.starts_at),(schedule.ends_at)) boundary(change_at)
      where schedule.state='active' and boundary.change_at>at_time
        and schedule.variant_id in (select (value->>'variant_id')::uuid from jsonb_array_elements(normalized))),
    'paymentMethods',jsonb_build_object('card',card_allowed and jsonb_array_length(normalized)>0,
      'bankTransfer',bank_allowed and jsonb_array_length(normalized)>0));
end $$

create trigger shipping_notice_template_immutable
  before update on public.shipping_notice_templates
  for each row execute function private.guard_shipping_notice_template_immutable()

create function public.admin_save_shipping_notice_template(
  target_id uuid,
  target_code text,
  target_version integer,
  target_name text,
  target_shipping_notice text,
  target_return_exchange_notice text,
  target_cs_name text,
  target_cs_phone text,
  target_cs_email text,
  expected_updated_at timestamptz
)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  actor uuid := (select auth.uid());
  previous public.shipping_notice_templates;
  saved public.shipping_notice_templates;
  normalized_code text := btrim(coalesce(target_code, ''), E' \t\n\r');
  normalized_name text := btrim(coalesce(target_name, ''), E' \t\n\r');
  normalized_shipping text := btrim(coalesce(target_shipping_notice, ''), E' \t\n\r');
  normalized_return_exchange text := btrim(coalesce(target_return_exchange_notice, ''), E' \t\n\r');
  normalized_cs_name text := btrim(coalesce(target_cs_name, ''), E' \t\n\r');
  normalized_cs_phone text := btrim(coalesce(target_cs_phone, ''), E' \t\n\r');
  normalized_cs_email text := btrim(coalesce(target_cs_email, ''), E' \t\n\r');
begin
  if actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if normalized_code !~ '^[a-z][a-z0-9-]{1,39}$'
    or target_version is null or target_version not between 1 and 1000000
    or char_length(normalized_name) not between 1 and 80
    or char_length(normalized_shipping) > 4000 or char_length(normalized_return_exchange) > 4000
    or char_length(normalized_cs_name) > 120 or char_length(normalized_cs_phone) > 80
    or char_length(normalized_cs_email) > 320
    or private.has_disallowed_shipping_notice_control(normalized_shipping)
    or private.has_disallowed_shipping_notice_control(normalized_return_exchange)
    or private.has_disallowed_shipping_notice_control(normalized_cs_name)
    or private.has_disallowed_shipping_notice_control(normalized_cs_phone)
    or private.has_disallowed_shipping_notice_control(normalized_cs_email)
  then
    raise invalid_parameter_value using message = 'invalid_shipping_notice_template';
  end if;

  if target_id is not null then
    select * into previous from public.shipping_notice_templates where id = target_id for update;
    if not found then raise no_data_found using message = 'shipping_notice_template_not_found'; end if;
    if previous.updated_at is distinct from expected_updated_at then
      raise exception using errcode = 'PT409', message = 'shipping_notice_template_conflict';
    end if;
    if previous.status <> 'draft' then
      raise check_violation using message = 'shipping_notice_template_active_immutable';
    end if;
    if previous.code <> normalized_code or previous.version <> target_version then
      raise check_violation using message = 'shipping_notice_template_identity_locked';
    end if;
    update public.shipping_notice_templates set
      name = normalized_name,
      shipping_notice = normalized_shipping,
      return_exchange_notice = normalized_return_exchange,
      cs_name = normalized_cs_name,
      cs_phone = normalized_cs_phone,
      cs_email = normalized_cs_email,
      updated_at = greatest(clock_timestamp(), previous.updated_at + interval '1 microsecond')
      where id = target_id returning * into saved;
  else
    if expected_updated_at is not null then
      raise invalid_parameter_value using message = 'invalid_shipping_notice_template';
    end if;
    insert into public.shipping_notice_templates(
      code, version, name, shipping_notice, return_exchange_notice, cs_name, cs_phone, cs_email
    ) values (
      normalized_code, target_version, normalized_name, normalized_shipping, normalized_return_exchange,
      normalized_cs_name, normalized_cs_phone, normalized_cs_email
    ) returning * into saved;
  end if;

  insert into public.audit_log(actor_id, action, target, diff)
    values (
      actor,
      case when target_id is null then 'catalog.shipping_notice_template.created'
        else 'catalog.shipping_notice_template.updated' end,
      'shipping_notice_templates:' || saved.id::text,
      jsonb_build_object('before', to_jsonb(previous), 'after', to_jsonb(saved))
    );
  return jsonb_build_object('id', saved.id, 'version', saved.version, 'updatedAt', saved.updated_at);
end;
$$

create function public.admin_activate_shipping_notice_template(
  target_id uuid,
  expected_updated_at timestamptz,
  evidence text
)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  actor uuid := (select auth.uid());
  previous public.shipping_notice_templates;
  saved public.shipping_notice_templates;
  normalized_evidence text := btrim(coalesce(evidence, ''), E' \t\n\r');
begin
  if actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  select * into previous from public.shipping_notice_templates where id = target_id for update;
  if not found then raise no_data_found using message = 'shipping_notice_template_not_found'; end if;
  if previous.status <> 'draft' then raise check_violation using message = 'shipping_notice_template_not_draft'; end if;
  if previous.updated_at is distinct from expected_updated_at then
    raise exception using errcode = 'PT409', message = 'shipping_notice_template_conflict';
  end if;
  if char_length(btrim(previous.shipping_notice, E' \t\n\r')) = 0
    or char_length(btrim(previous.return_exchange_notice, E' \t\n\r')) = 0
    or char_length(btrim(previous.cs_name, E' \t\n\r')) = 0
    or (char_length(btrim(previous.cs_phone, E' \t\n\r')) = 0 and char_length(btrim(previous.cs_email, E' \t\n\r')) = 0)
    or char_length(normalized_evidence) = 0 or char_length(normalized_evidence) > 2000
    or private.has_disallowed_shipping_notice_control(normalized_evidence) then
    raise check_violation using message = 'shipping_notice_template_required';
  end if;
  update public.shipping_notice_templates set
    status = 'active', confirmation_evidence = normalized_evidence,
    confirmed_by = actor, confirmed_at = clock_timestamp(),
    updated_at = greatest(clock_timestamp(), previous.updated_at + interval '1 microsecond')
    where id = target_id returning * into saved;
  insert into public.audit_log(actor_id, action, target, diff)
    values (actor, 'catalog.shipping_notice_template.activated', 'shipping_notice_templates:' || saved.id::text,
      jsonb_build_object('before', to_jsonb(previous), 'after', to_jsonb(saved)));
  return jsonb_build_object('id', saved.id, 'version', saved.version, 'updatedAt', saved.updated_at, 'status', saved.status);
end;
$$

create function public.admin_apply_shipping_notice_template(
  target_good_id text,
  target_template_id uuid,
  expected_good_updated_at timestamptz
)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  actor uuid := (select auth.uid());
  template public.shipping_notice_templates;
  previous public.goods;
  saved public.goods;
  snapshot jsonb;
begin
  if actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  select * into previous from public.goods where id = target_good_id for update;
  if not found then raise no_data_found using message = 'good_not_found'; end if;
  if expected_good_updated_at is null or previous.updated_at is distinct from expected_good_updated_at then
    raise exception using errcode = 'PT409', message = 'good_shipping_notice_conflict';
  end if;
  if previous.archived_at is not null then raise check_violation using message='good_archived'; end if;
  if target_template_id is not distinct from previous.shipping_notice_template_id then
    return jsonb_build_object('goodId',previous.id,'templateId',previous.shipping_notice_template_id,
      'templateVersion',previous.shipping_notice_template_version,'updatedAt',previous.updated_at);
  end if;
  if target_template_id is null then
    update public.goods set
      shipping_notice_template_id = null,
      shipping_notice_template_version = null,
      shipping_notice_snapshot = null,
      updated_at = greatest(clock_timestamp(), previous.updated_at + interval '1 microsecond')
      where id = target_good_id returning * into saved;
    insert into public.audit_log(actor_id, action, target, diff)
      values (actor, 'catalog.good.shipping_notice_template_cleared', 'goods:' || saved.id,
        jsonb_build_object('before', jsonb_build_object(
          'templateId', previous.shipping_notice_template_id,
          'templateVersion', previous.shipping_notice_template_version,
          'snapshot', previous.shipping_notice_snapshot
        ), 'after', null));
    return jsonb_build_object('goodId', saved.id, 'templateId', null, 'templateVersion', null, 'updatedAt', saved.updated_at);
  end if;
  select * into template from public.shipping_notice_templates where id = target_template_id;
  if not found then raise no_data_found using message = 'shipping_notice_template_not_found'; end if;
  if template.status <> 'active' then raise check_violation using message = 'shipping_notice_template_not_active'; end if;
  snapshot := jsonb_build_object(
    'templateId', template.id,
    'templateVersion', template.version,
    'code', template.code,
    'name', template.name,
    'shippingNotice', template.shipping_notice,
    'returnExchangeNotice', template.return_exchange_notice,
    'csName', template.cs_name,
    'csPhone', template.cs_phone,
    'csEmail', template.cs_email
  );
  update public.goods set
    shipping_notice_template_id = template.id,
    shipping_notice_template_version = template.version,
    shipping_notice_snapshot = snapshot,
    updated_at = greatest(clock_timestamp(), previous.updated_at + interval '1 microsecond')
    where id = target_good_id returning * into saved;
  insert into public.audit_log(actor_id, action, target, diff)
    values (actor, 'catalog.good.shipping_notice_template_applied', 'goods:' || saved.id,
      jsonb_build_object('before', jsonb_build_object(
        'templateId', previous.shipping_notice_template_id,
        'templateVersion', previous.shipping_notice_template_version,
        'snapshot', previous.shipping_notice_snapshot
      ), 'after', jsonb_build_object(
        'templateId', saved.shipping_notice_template_id,
        'templateVersion', saved.shipping_notice_template_version,
        'snapshot', saved.shipping_notice_snapshot
      )));
  return jsonb_build_object(
    'goodId', saved.id,
    'templateId', saved.shipping_notice_template_id,
    'templateVersion', saved.shipping_notice_template_version,
    'updatedAt', saved.updated_at
  );
end;
$$

-- Goods forms and workbook imports identify a template by its external
-- code/version contract. Resolve that reference and call the same atomic
-- apply/clear writer used by the dedicated admin screen.
create function private.apply_shipping_notice_template_reference(
  target_good_id text,
  target_code text,
  target_version integer
)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  template_id uuid;
  good_stamp timestamptz;
begin
  if nullif(btrim(coalesce(target_code, ''), E' \t\n\r'), '') is null then
    select updated_at into good_stamp from public.goods where id = target_good_id;
    if not found then raise no_data_found using message = 'good_not_found'; end if;
    return public.admin_apply_shipping_notice_template(target_good_id, null, good_stamp);
  end if;
  if target_version is null then raise invalid_parameter_value using message = 'shipping_notice_template_version_required'; end if;
  select id into template_id from public.shipping_notice_templates
    where code = btrim(target_code) and version = target_version;
  if not found then raise check_violation using message = 'shipping_notice_template_not_found'; end if;
  select updated_at into good_stamp from public.goods where id = target_good_id;
  if not found then raise no_data_found using message = 'good_not_found'; end if;
  return public.admin_apply_shipping_notice_template(target_good_id, template_id, good_stamp);
end;
$$

create function public.admin_save_good(target_good jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare saved jsonb; previous public.goods; next_good public.goods; field text; before_policy jsonb; after_policy jsonb;
  owned_payload jsonb; initial_controls jsonb; existing_id text; legacy_payload jsonb;
  template_code text; template_version integer; template_fields_present boolean := false;
  template_version_text text;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  template_fields_present := target_good ? 'shipping_notice_template_code'
    or target_good ? 'shipping_notice_template_version'
    or target_good ? 'shippingNoticeTemplateCode'
    or target_good ? 'shippingNoticeTemplateVersion';
  legacy_payload := target_good - 'shipping_notice_template_code' - 'shipping_notice_template_version'
    - 'shippingNoticeTemplateCode' - 'shippingNoticeTemplateVersion';
  if template_fields_present then
    if (target_good ? 'shipping_notice_template_code' and jsonb_typeof(target_good->'shipping_notice_template_code') not in ('string','null'))
      or (target_good ? 'shippingNoticeTemplateCode' and jsonb_typeof(target_good->'shippingNoticeTemplateCode') not in ('string','null')) then
      raise invalid_parameter_value using message='invalid_shipping_notice_template';
    end if;
    template_code := nullif(btrim(coalesce(target_good->>'shipping_notice_template_code', target_good->>'shippingNoticeTemplateCode', '')), '');
    template_version_text := nullif(btrim(coalesce(target_good->>'shipping_notice_template_version', target_good->>'shippingNoticeTemplateVersion', '')), '');
    if template_version_text is not null then
      begin
        template_version := template_version_text::integer;
      exception when others then
        raise invalid_parameter_value using message='invalid_shipping_notice_template';
      end;
    end if;
    if template_code is not null and (template_code !~ '^[a-z][a-z0-9-]{1,39}$' or template_version is null or template_version not between 1 and 1000000) then
      raise invalid_parameter_value using message='invalid_shipping_notice_template';
    end if;
    if template_code is null and template_version is not null then
      raise invalid_parameter_value using message='invalid_shipping_notice_template';
    end if;
  end if;
  foreach field in array array['allow_card_payment','allow_bank_transfer','order_quantity_limit_enabled','member_purchase_limit_enabled'] loop
    if target_good ? field and jsonb_typeof(target_good->field) is distinct from 'boolean' then
      raise check_violation using message='invalid_goods_sales_policy';
    end if;
  end loop;
  if target_good ? 'sale_restriction' and (jsonb_typeof(target_good->'sale_restriction') is distinct from 'string'
    or target_good->>'sale_restriction' not in ('none','adult')) then
    raise check_violation using message='invalid_goods_sales_policy';
  end if;
  foreach field in array array['min_order_qty','max_order_qty','member_lifetime_qty_limit'] loop
    if target_good ? field and jsonb_typeof(target_good->field)<>'null' then
      if jsonb_typeof(target_good->field)<>'number' or target_good->>field !~ '^[1-9][0-9]*$'
        or (target_good->>field)::numeric>2147483647 then
        raise check_violation using message='invalid_goods_sales_policy';
      end if;
    end if;
  end loop;
  -- Apply controls before the legacy writer can emit a stock/publication alert.
  -- Match the legacy editor's advisory->good lock order, including a draft rename.
  existing_id:=coalesce(nullif(btrim(target_good->>'previous_id'),''),nullif(btrim(target_good->>'id'),''));
  if existing_id is not null then
    perform pg_advisory_xact_lock(hashtextextended('admin_good:'||existing_id,0));
    select * into previous from public.goods where id=existing_id for update;
    if found then
      initial_controls:=jsonb_build_object('allow_card_payment',previous.allow_card_payment,
        'allow_bank_transfer',previous.allow_bank_transfer,'sale_restriction',previous.sale_restriction);
      update public.goods set
        allow_card_payment=case when target_good?'allow_card_payment' then (target_good->>'allow_card_payment')::boolean else allow_card_payment end,
        allow_bank_transfer=case when target_good?'allow_bank_transfer' then (target_good->>'allow_bank_transfer')::boolean else allow_bank_transfer end,
        sale_restriction=case when target_good?'sale_restriction' then (target_good->>'sale_restriction')::public.goods_sale_restriction else sale_restriction end
      where id=existing_id;
      if target_good->>'publish'='false' then perform public.admin_set_good_published(existing_id,false); end if;
    end if;
  end if;
  -- New goods begin as drafts. The final controls must exist before first publish.
  saved:=private.admin_save_good_before_shipping_notice(case when legacy_payload->>'publish' in ('true','false')
    then legacy_payload||'{"publish":null}'::jsonb else legacy_payload end);
  select * into previous from public.goods where id=saved->>'id' for update;
  select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into owned_payload
  from jsonb_each(target_good) where key=any(array['allow_card_payment','allow_bank_transfer','sale_restriction',
    'order_quantity_limit_enabled','min_order_qty','max_order_qty','member_purchase_limit_enabled','member_lifetime_qty_limit']);
  next_good:=jsonb_populate_record(previous,owned_payload);
  before_policy:=jsonb_build_object('allow_card_payment',previous.allow_card_payment,
    'allow_bank_transfer',previous.allow_bank_transfer,'sale_restriction',previous.sale_restriction,
    'order_quantity_limit_enabled',previous.order_quantity_limit_enabled,'min_order_qty',previous.min_order_qty,
    'max_order_qty',previous.max_order_qty,'member_purchase_limit_enabled',previous.member_purchase_limit_enabled,
    'member_lifetime_qty_limit',previous.member_lifetime_qty_limit);
  before_policy:=before_policy||coalesce(initial_controls,'{}'::jsonb);
  after_policy:=jsonb_build_object('allow_card_payment',next_good.allow_card_payment,
    'allow_bank_transfer',next_good.allow_bank_transfer,'sale_restriction',next_good.sale_restriction,
    'order_quantity_limit_enabled',next_good.order_quantity_limit_enabled,'min_order_qty',next_good.min_order_qty,
    'max_order_qty',next_good.max_order_qty,'member_purchase_limit_enabled',next_good.member_purchase_limit_enabled,
    'member_lifetime_qty_limit',next_good.member_lifetime_qty_limit);
  if after_policy is distinct from before_policy then
    update public.goods set allow_card_payment=next_good.allow_card_payment,
      allow_bank_transfer=next_good.allow_bank_transfer,sale_restriction=next_good.sale_restriction,
      order_quantity_limit_enabled=next_good.order_quantity_limit_enabled,min_order_qty=next_good.min_order_qty,
      max_order_qty=next_good.max_order_qty,member_purchase_limit_enabled=next_good.member_purchase_limit_enabled,
      member_lifetime_qty_limit=next_good.member_lifetime_qty_limit where id=previous.id;
    insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.good.sales_policy_saved','goods:'||previous.id,
      jsonb_build_object('before',before_policy,'after',after_policy));
  end if;
  -- Both methods may be deliberately disabled. The public quote advertises an
  -- empty intersection and the locked order writer rejects either method.
  if legacy_payload->>'publish' in ('true','false') then
    perform public.admin_set_good_published(saved->>'id',(legacy_payload->>'publish')::boolean);
  end if;
  if template_fields_present then
    perform private.apply_shipping_notice_template_reference(saved->>'id', template_code, template_version);
    saved := saved || jsonb_build_object('shippingNoticeTemplateCode', template_code, 'shippingNoticeTemplateVersion', template_version);
  end if;
  return saved;
end $$

create policy catalog_categories_public_read on public.catalog_categories for select using (
  archived_at is null and private.category_customer_enabled()
)

create function private.category_validate_parent(target_category_id uuid, target_parent_id uuid)
returns integer language plpgsql security definer set search_path = '' as $$
declare
  current_id uuid := target_parent_id;
  current_parent_id uuid;
  current_archived_at timestamptz;
  depth integer := 1;
  descendant_depth integer;
begin
  if target_parent_id is null then return 1; end if;
  while current_id is not null loop
    if current_id = target_category_id then raise check_violation using message = 'category_cycle'; end if;
    select category.parent_id, category.archived_at into current_parent_id, current_archived_at
    from public.catalog_categories as category where category.id = current_id;
    if not found then raise foreign_key_violation using message = 'category_parent_not_found'; end if;
    if current_archived_at is not null then raise check_violation using message = 'category_parent_archived'; end if;
    depth := depth + 1;
    if depth > 4 then raise check_violation using message = 'category_depth_exceeded'; end if;
    current_id := current_parent_id;
  end loop;
  with recursive descendants as (
    select category.id, 1 as relative_depth from public.catalog_categories as category where category.parent_id = target_category_id
    union all
    select child.id, descendants.relative_depth + 1 from descendants join public.catalog_categories as child on child.parent_id = descendants.id
  ) select coalesce(max(relative_depth), 0) into descendant_depth from descendants;
  if depth + descendant_depth > 4 then raise check_violation using message = 'category_depth_exceeded'; end if;
  return depth;
end;
$$

create function private.guard_category_tree()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  perform private.lock_catalog_category_tree();
  if new.parent_id is not null then
    if tg_op = 'INSERT' then
      if exists (select 1 from public.goods where category_id = new.parent_id) then
        raise check_violation using message = 'category_has_goods';
      end if;
    elsif old.parent_id is distinct from new.parent_id
      and exists (select 1 from public.goods where category_id = new.parent_id)
    then
      raise check_violation using message = 'category_has_goods';
    end if;
  end if;
  new.depth := private.category_validate_parent(new.id, new.parent_id);
  return new;
end;
$$

create function private.guard_good_category()
returns trigger language plpgsql security definer set search_path = '' as $$
declare child_count integer; archived_at timestamptz;
begin
  if new.category_id is null then return new; end if;
  select category.archived_at,
    (select count(*)::integer from public.catalog_categories as child where child.parent_id = category.id and child.archived_at is null)
    into archived_at, child_count
  from public.catalog_categories as category where category.id = new.category_id for share;
  if not found then raise foreign_key_violation using message = 'category_not_found'; end if;
  if archived_at is not null then
    if tg_op = 'UPDATE' then
      if old.category_id is not distinct from new.category_id then return new; end if;
    end if;
    raise check_violation using message = 'category_archived';
  end if;
  if child_count > 0 then raise check_violation using message = 'category_not_leaf'; end if;
  return new;
end;
$$

create function public.admin_upsert_category(
  target_operation_id uuid,
  target_category_id uuid,
  target_code text,
  target_name text,
  target_parent_id uuid,
  target_sort_order integer,
  target_expected_updated_at timestamptz
)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  actor_id uuid := (select auth.uid());
  category_row public.catalog_categories;
  next_depth integer;
  result_id uuid;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  request_payload jsonb;
begin
  if actor_id is null or not public.is_staff() then raise insufficient_privilege using message = 'forbidden'; end if;
  if target_operation_id is null or target_code is null or target_code !~ '^[a-z0-9][a-z0-9-]*$' or length(target_code) > 80
     or target_name is null or btrim(target_name) = '' or length(target_name) > 120
     or target_sort_order is null or target_sort_order < 0 then
    raise invalid_parameter_value using message = 'invalid_category';
  end if;
  request_payload := jsonb_build_object(
    'category_id', target_category_id,
    'code', target_code,
    'name', btrim(target_name),
    'parent_id', target_parent_id,
    'sort_order', target_sort_order,
    'expected_updated_at', target_expected_updated_at
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || target_operation_id::text, 0));
  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;
  if found then
    if existing_actor_id = actor_id
       and existing_action in ('admin.catalog.category.created', 'admin.catalog.category.updated')
       and existing_diff -> 'request' = request_payload
    then
      result_id := coalesce(target_category_id, nullif(existing_diff ->> 'category_id', '')::uuid);
      next_depth := nullif(existing_diff #>> '{after,depth}', '')::integer;
      if result_id is not null and next_depth is not null then
        return jsonb_build_object('id', result_id, 'depth', next_depth);
      end if;
    end if;
    raise unique_violation using message = 'operation_conflict';
  end if;
  perform private.lock_catalog_category_tree();

  if target_category_id is null then
    if exists (select 1 from public.catalog_categories where code = target_code) then raise unique_violation using message = 'category_code_taken'; end if;
    result_id := extensions.gen_random_uuid();
    next_depth := private.category_validate_parent(result_id, target_parent_id);
    insert into public.catalog_categories (id, code, name, parent_id, depth, sort_order)
    values (result_id, target_code, btrim(target_name), target_parent_id, next_depth, target_sort_order);
    insert into public.audit_log(id, actor_id, action, target, diff)
    values (target_operation_id, actor_id, 'admin.catalog.category.created', 'catalog_categories:' || result_id::text,
      jsonb_build_object('category_id', result_id, 'request', request_payload,
        'after', jsonb_build_object('code', target_code, 'name', btrim(target_name), 'parent_id', target_parent_id, 'depth', next_depth)));
  else
    select * into category_row from public.catalog_categories where id = target_category_id for update;
    if not found then raise no_data_found using message = 'category_not_found'; end if;
    if target_expected_updated_at is null or category_row.updated_at is distinct from target_expected_updated_at then raise exception using errcode = 'PT409', message = 'category_changed'; end if;
    if exists (select 1 from public.catalog_categories where code = target_code and id <> target_category_id) then raise unique_violation using message = 'category_code_taken'; end if;
    next_depth := private.category_validate_parent(target_category_id, target_parent_id);
    update public.catalog_categories
    set code = target_code, name = btrim(target_name), parent_id = target_parent_id, depth = next_depth,
        sort_order = target_sort_order, updated_at = pg_catalog.now()
    where id = target_category_id;
    with recursive descendants as (
      select category.id, 1 as relative_depth
      from public.catalog_categories as category
      where category.parent_id = target_category_id
      union all
      select child.id, descendants.relative_depth + 1
      from descendants
      join public.catalog_categories as child on child.parent_id = descendants.id
    )
    update public.catalog_categories as child
    set depth = next_depth + descendants.relative_depth, updated_at = pg_catalog.now()
    from descendants
    where child.id = descendants.id;
    result_id := target_category_id;
    insert into public.audit_log(id, actor_id, action, target, diff)
    values (target_operation_id, actor_id, 'admin.catalog.category.updated', 'catalog_categories:' || target_category_id::text,
      jsonb_build_object('category_id', target_category_id, 'request', request_payload,
        'after', jsonb_build_object('code', target_code, 'name', btrim(target_name), 'parent_id', target_parent_id, 'depth', next_depth)));
  end if;
  return jsonb_build_object('id', result_id, 'depth', next_depth);
end;
$$

create function public.admin_archive_category(target_operation_id uuid, target_category_id uuid, target_expected_updated_at timestamptz)
returns boolean language plpgsql security definer set search_path = '' as $$
declare
  actor_id uuid := (select auth.uid());
  category_row public.catalog_categories;
  existing_actor_id uuid;
  existing_action text;
  existing_diff jsonb;
  request_payload jsonb;
  changed boolean;
begin
  if actor_id is null or not public.is_staff() then raise insufficient_privilege using message = 'forbidden'; end if;
  if target_operation_id is null or target_category_id is null or target_expected_updated_at is null then raise invalid_parameter_value using message = 'invalid_category_operation'; end if;
  request_payload := jsonb_build_object('category_id', target_category_id, 'expected_updated_at', target_expected_updated_at);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || target_operation_id::text, 0));
  select audit.actor_id, audit.action, audit.diff into existing_actor_id, existing_action, existing_diff
  from public.audit_log as audit where audit.id = target_operation_id;
  if found then
    if existing_actor_id = actor_id and existing_action = 'admin.catalog.category.archived' and existing_diff -> 'request' = request_payload then
      return coalesce((existing_diff ->> 'changed')::boolean, true);
    end if;
    raise unique_violation using message = 'operation_conflict';
  end if;
  perform private.lock_catalog_category_tree();
  select * into category_row from public.catalog_categories where id = target_category_id for update;
  if not found then raise no_data_found using message = 'category_not_found'; end if;
  if category_row.updated_at is distinct from target_expected_updated_at then raise exception using errcode = 'PT409', message = 'category_changed'; end if;
  if category_row.archived_at is not null then
    changed := false;
  else
    if exists (select 1 from public.catalog_categories where parent_id = target_category_id and archived_at is null) then raise check_violation using message = 'category_has_active_children'; end if;
    update public.catalog_categories set archived_at = pg_catalog.now(), updated_at = pg_catalog.now() where id = target_category_id;
    changed := true;
  end if;
  insert into public.audit_log(id, actor_id, action, target, diff)
  values (target_operation_id, actor_id, 'admin.catalog.category.archived', 'catalog_categories:' || target_category_id::text,
    jsonb_build_object('request', request_payload, 'changed', changed));
  return changed;
end;
$$

create function public.admin_unarchive_category(target_operation_id uuid, target_category_id uuid, target_expected_updated_at timestamptz)
returns boolean language plpgsql security definer set search_path = '' as $$
declare
  actor_id uuid := (select auth.uid());
  category_row public.catalog_categories;
  next_depth integer;
  existing_actor_id uuid;
  existing_action text;
  existing_diff jsonb;
  request_payload jsonb;
  changed boolean;
begin
  if actor_id is null or not public.is_staff() then raise insufficient_privilege using message = 'forbidden'; end if;
  if target_operation_id is null or target_category_id is null or target_expected_updated_at is null then raise invalid_parameter_value using message = 'invalid_category_operation'; end if;
  request_payload := jsonb_build_object('category_id', target_category_id, 'expected_updated_at', target_expected_updated_at);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || target_operation_id::text, 0));
  select audit.actor_id, audit.action, audit.diff into existing_actor_id, existing_action, existing_diff
  from public.audit_log as audit where audit.id = target_operation_id;
  if found then
    if existing_actor_id = actor_id and existing_action = 'admin.catalog.category.unarchived' and existing_diff -> 'request' = request_payload then
      return coalesce((existing_diff ->> 'changed')::boolean, true);
    end if;
    raise unique_violation using message = 'operation_conflict';
  end if;
  perform private.lock_catalog_category_tree();
  select * into category_row from public.catalog_categories where id = target_category_id for update;
  if not found then raise no_data_found using message = 'category_not_found'; end if;
  if category_row.updated_at is distinct from target_expected_updated_at then raise exception using errcode = 'PT409', message = 'category_changed'; end if;
  if category_row.archived_at is null then
    changed := false;
    next_depth := category_row.depth;
  else
    next_depth := private.category_validate_parent(target_category_id, category_row.parent_id);
    update public.catalog_categories set archived_at = null, depth = next_depth, updated_at = pg_catalog.now() where id = target_category_id;
    changed := true;
  end if;
  insert into public.audit_log(id, actor_id, action, target, diff)
  values (target_operation_id, actor_id, 'admin.catalog.category.unarchived', 'catalog_categories:' || target_category_id::text,
    jsonb_build_object('request', request_payload, 'changed', changed, 'depth', next_depth));
  return changed;
end;
$$

create function public.admin_set_category_erp_mapping(
