create function private.validate_shopping_story_values(p_values jsonb)
returns void language plpgsql immutable set search_path='' as $$
declare section_value jsonb; item jsonb; image_value jsonb; section_ids uuid[]:='{}'; good_ids text[]:='{}'; images text[]:='{}'; section_id uuid; start_value timestamptz; end_value timestamptz;
begin
 if p_values is null or jsonb_typeof(p_values)<>'object'
  or exists(select 1 from jsonb_object_keys(p_values) k where k not in ('title','bodyHtml','imagePaths','startsAt','endsAt','sections'))
  or not(p_values ?& array['title','bodyHtml','imagePaths','startsAt','endsAt','sections'])
  or jsonb_typeof(p_values->'title')<>'string' or char_length(btrim(p_values->>'title')) not between 1 and 50
  or jsonb_typeof(p_values->'bodyHtml')<>'string' or char_length(p_values->>'bodyHtml') not between 1 and 30000
  or jsonb_typeof(p_values->'imagePaths')<>'array' or jsonb_array_length(p_values->'imagePaths')>20
  or jsonb_typeof(p_values->'sections')<>'array' or jsonb_array_length(p_values->'sections')>10
  or jsonb_typeof(p_values->'startsAt') not in ('null','string') or jsonb_typeof(p_values->'endsAt') not in ('null','string')
  or (p_values->>'startsAt' is not null and (p_values->>'startsAt')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$')
  or (p_values->>'endsAt' is not null and (p_values->>'endsAt')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$')
 then raise invalid_parameter_value using message='invalid_shopping_story';end if;
 begin
  start_value:=(p_values->>'startsAt')::timestamptz; end_value:=(p_values->>'endsAt')::timestamptz;
 exception when others then raise invalid_parameter_value using message='invalid_shopping_story_window';end;
 if (start_value is not null and not isfinite(start_value)) or (end_value is not null and not isfinite(end_value))
  or (start_value is not null and end_value is not null and start_value>=end_value)
 then raise invalid_parameter_value using message='invalid_shopping_story_window';end if;
 for image_value in select value from jsonb_array_elements(p_values->'imagePaths') loop
  if jsonb_typeof(image_value)<>'string' or (image_value#>>'{}')!~'^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
   or (image_value#>>'{}')=any(images) then raise invalid_parameter_value using message='invalid_shopping_story_images';end if;
  images:=array_append(images,image_value#>>'{}');
 end loop;
 for section_value in select value from jsonb_array_elements(p_values->'sections') loop
  if jsonb_typeof(section_value)<>'object'
   or exists(select 1 from jsonb_object_keys(section_value) k where k not in ('id','title','imageShape','goodIds'))
   or not(section_value ?& array['id','title','imageShape','goodIds'])
   or jsonb_typeof(section_value->'id')<>'string' or (section_value->>'id')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(section_value->'title')<>'string' or char_length(btrim(section_value->>'title')) not between 1 and 13
   or jsonb_typeof(section_value->'imageShape')<>'string' or section_value->>'imageShape' not in ('square','portrait')
   or jsonb_typeof(section_value->'goodIds')<>'array' or jsonb_array_length(section_value->'goodIds') not between 1 and 200
  then raise invalid_parameter_value using message='invalid_shopping_story_section';end if;
  section_id:=(section_value->>'id')::uuid;
  if section_id=any(section_ids) then raise invalid_parameter_value using message='invalid_shopping_story_section';end if;
  section_ids:=array_append(section_ids,section_id);
  for item in select value from jsonb_array_elements(section_value->'goodIds') loop
   if jsonb_typeof(item)<>'string' or (item#>>'{}')!~'^[a-z0-9][a-z0-9-]{0,119}$' or (item#>>'{}')=any(good_ids)
   then raise invalid_parameter_value using message='invalid_shopping_story_goods';end if;
   good_ids:=array_append(good_ids,item#>>'{}');
  end loop;
 end loop;
 if cardinality(good_ids)>300 then raise invalid_parameter_value using message='shopping_story_goods_limit';end if;
end;
$$

create function public.admin_save_shopping_story(p_id uuid,p_expected_revision integer,p_operation_id uuid,p_values jsonb)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid(); previous public.shopping_stories; saved public.shopping_stories; existing public.audit_log;
 request_value jsonb; result_value jsonb; before_value jsonb; image_paths text[]; image_path text; ids text[]; bad_good text; section_value jsonb; section_position bigint; good_value text; good_position bigint;
begin
 perform private.require_operator_capability('store.manage',false);
 if p_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 then raise invalid_parameter_value using message='invalid_shopping_story';end if;
 perform private.validate_shopping_story_values(p_values);
 request_value:=jsonb_build_object('expectedRevision',p_expected_revision,'values',p_values);
 perform pg_advisory_xact_lock(hashtextextended('shopping-story-operation:'||p_operation_id::text,0));
 select * into existing from public.audit_log where id=p_operation_id;
 if found then
  if existing.actor_id=actor and existing.action='admin.shopping_story.saved' and existing.target='shopping_stories:'||p_id::text and existing.diff->'request'=request_value
  then return existing.diff->'result';end if;
  raise sqlstate 'PT409' using message='shopping_story_operation_conflict';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('shopping-story:'||p_id::text,0));
 select * into previous from public.shopping_stories where id=p_id for update;
 if found then
  if previous.deleted_at is not null then raise no_data_found using message='shopping_story_not_found';end if;
  if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='shopping_story_conflict';end if;
  before_value:=private.shopping_story_document(p_id);
 elsif p_expected_revision<>0 then raise no_data_found using message='shopping_story_not_found';end if;
 select coalesce(array_agg(value order by value),'{}') into image_paths from jsonb_array_elements_text(p_values->'imagePaths');
 select coalesce(array_agg(good_id order by good_id),'{}') into ids
 from jsonb_array_elements(p_values->'sections') section_entry cross join lateral jsonb_array_elements_text(section_entry->'goodIds') good_id;
 -- Lock every reference in deterministic order; all 300 identifiers are checked
 -- inside Postgres, independent of PostgREST's default row limit.
 perform 1 from public.goods g where g.id=any(ids) order by g.id for share;
 select input.id into bad_good from unnest(ids) input(id) left join public.goods g on g.id=input.id left join public.ips ip on ip.id=g.ip_id
 where g.id is null or ((g.archived_at is not null or ip.archived_at is not null) and not exists(
  select 1 from public.shopping_story_goods old_link where old_link.story_id=p_id and old_link.good_id=input.id)) limit 1;
 if bad_good is not null then raise check_violation using message='shopping_story_good_unavailable';end if;
 if exists(select 1 from public.shopping_story_sections x where x.story_id<>p_id and x.id in
  (select (entry->>'id')::uuid from jsonb_array_elements(p_values->'sections') entry)) then raise invalid_parameter_value using message='invalid_shopping_story_section';end if;
 foreach image_path in array image_paths loop
  if image_path=any(coalesce(previous.body_image_paths,'{}')) then continue;end if;
  update public.admin_artwork_upload_claims claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
  where claim.actor_id=actor and claim.kind='curation' and claim.path=substr(image_path,length('public-media/')+1)
   and claim.status='verified' and claim.verified_at is not null and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
  if not found then raise check_violation using message='unverified_artwork';end if;
 end loop;
 if previous.id is null then
  insert into public.shopping_stories(id,title,body_html,body_image_paths,starts_at,ends_at,created_by,updated_by)
  values(p_id,btrim(p_values->>'title'),p_values->>'bodyHtml',image_paths,(p_values->>'startsAt')::timestamptz,(p_values->>'endsAt')::timestamptz,actor,actor) returning * into saved;
 else
  update public.shopping_stories set title=btrim(p_values->>'title'),body_html=p_values->>'bodyHtml',body_image_paths=image_paths,
   starts_at=(p_values->>'startsAt')::timestamptz,ends_at=(p_values->>'endsAt')::timestamptz,revision=revision+1,updated_at=clock_timestamp(),updated_by=actor
  where id=p_id returning * into saved;
 end if;
 delete from public.shopping_story_sections where story_id=p_id;
 for section_value,section_position in select value,ordinality-1 from jsonb_array_elements(p_values->'sections') with ordinality loop
  insert into public.shopping_story_sections(id,story_id,title,image_shape,sort_order)
  values((section_value->>'id')::uuid,p_id,btrim(section_value->>'title'),section_value->>'imageShape',section_position::integer);
  for good_value,good_position in select value,ordinality-1 from jsonb_array_elements_text(section_value->'goodIds') with ordinality loop
   insert into public.shopping_story_goods(story_id,section_id,good_id,sort_order) values(p_id,(section_value->>'id')::uuid,good_value,good_position::integer);
  end loop;
 end loop;
 result_value:=jsonb_build_object('id',saved.id,'reference',saved.reference,'revision',saved.revision);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.shopping_story.saved','shopping_stories:'||p_id::text,
  jsonb_build_object('request',request_value,'before',before_value,'after',private.shopping_story_document(p_id),'result',result_value));
 return result_value;
end;
$$

create function public.admin_delete_shopping_stories(p_operation_id uuid,p_entries jsonb)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid(); existing public.audit_log; entry jsonb; target_id uuid; ids uuid[]:='{}'; current_story public.shopping_stories; before_rows jsonb:='[]'; result_value jsonb;
begin
 perform private.require_operator_capability('store.manage',false);
 if p_operation_id is null or p_entries is null or jsonb_typeof(p_entries)<>'array' or jsonb_array_length(p_entries) not between 1 and 100
 then raise invalid_parameter_value using message='invalid_shopping_story_delete';end if;
 for entry in select value from jsonb_array_elements(p_entries) loop
  if jsonb_typeof(entry)<>'object' or not(entry ?& array['id','revision']) or exists(select 1 from jsonb_object_keys(entry) k where k not in ('id','revision'))
   or jsonb_typeof(entry->'id')<>'string' or (entry->>'id')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(entry->'revision')<>'number' or (entry->>'revision')!~'^[1-9][0-9]{0,8}$' then raise invalid_parameter_value using message='invalid_shopping_story_delete';end if;
  target_id:=(entry->>'id')::uuid;
  if target_id=any(ids) then raise invalid_parameter_value using message='invalid_shopping_story_delete';end if;
  ids:=array_append(ids,target_id);
 end loop;
 perform pg_advisory_xact_lock(hashtextextended('shopping-story-operation:'||p_operation_id::text,0));
 select * into existing from public.audit_log where id=p_operation_id;
 if found then
  if existing.actor_id=actor and existing.action='admin.shopping_stories.deleted' and existing.target='shopping_stories' and existing.diff->'request'=p_entries then return existing.diff->'result';end if;
  raise sqlstate 'PT409' using message='shopping_story_operation_conflict';
 end if;
 for target_id in select value from unnest(ids) value order by value loop
  perform pg_advisory_xact_lock(hashtextextended('shopping-story:'||target_id::text,0));
  select * into current_story from public.shopping_stories where id=target_id for update;
  if not found or current_story.deleted_at is not null then raise no_data_found using message='shopping_story_not_found';end if;
  if current_story.revision<>(select (value->>'revision')::integer from jsonb_array_elements(p_entries) where (value->>'id')::uuid=target_id)
  then raise sqlstate 'PT409' using message='shopping_story_conflict';end if;
  before_rows:=before_rows||jsonb_build_array(jsonb_build_object('id',current_story.id,'title',current_story.title,'revision',current_story.revision));
 end loop;
 update public.shopping_stories set deleted_at=clock_timestamp(),updated_at=clock_timestamp(),updated_by=actor,revision=revision+1 where id=any(ids);
 result_value:=jsonb_build_object('deletedCount',cardinality(ids));
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.shopping_stories.deleted','shopping_stories',
  jsonb_build_object('request',p_entries,'before',before_rows,'result',result_value));
 return result_value;
end;
$$

create function public.admin_get_shopping_story(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result_value jsonb;
begin
 if not public.has_operator_capability('store.manage') then raise insufficient_privilege using message='operator_capability_required';end if;
 if not exists(select 1 from public.shopping_stories where id=p_id and deleted_at is null) then return null;end if;
 result_value:=private.shopping_story_document(p_id);
 return result_value||jsonb_build_object('goods',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'code',g.code,
  'imagePath',g.image_path,'price',g.price,'archived',g.archived_at is not null or ip.archived_at is not null,
  'published',g.published_at is not null and ip.published_at is not null and g.archived_at is null and ip.archived_at is null and g.sale_restriction='none',
  'soldOut',g.stock='soldout' or coalesce(g.stock_qty,0)<=0) order by g.id)
  from public.shopping_story_goods links join public.goods g on g.id=links.good_id join public.ips ip on ip.id=g.ip_id where links.story_id=p_id),'[]'::jsonb));
end;
$$

create function public.admin_list_shopping_stories(p_query text default '',p_state text default 'all',p_from date default null,p_to date default null,p_sort text default 'created_desc',p_limit integer default 100,p_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare at_value timestamptz:=statement_timestamp(); result_value jsonb;
begin
 if not public.has_operator_capability('store.manage') then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_query is null or char_length(p_query)>100 or p_state is null or p_state not in ('all','scheduled','active','ended')
  or p_sort is null or p_sort not in ('created_desc','created_asc','updated_desc') or p_limit is null or p_limit not between 1 and 100 or p_offset is null or p_offset<0
  or (p_from is not null and p_to is not null and p_from>p_to) then raise invalid_parameter_value using message='invalid_shopping_story_filter';end if;
 with filtered as (
  select s.*,private.shopping_story_state(s.starts_at,s.ends_at,at_value) display_state from public.shopping_stories s
  where s.deleted_at is null and (p_query='' or position(lower(p_query) in lower(s.title))>0)
   and (p_state='all' or private.shopping_story_state(s.starts_at,s.ends_at,at_value)=p_state)
   and (p_from is null or s.created_at>=p_from::timestamp at time zone 'Asia/Seoul')
   and (p_to is null or s.created_at<(p_to+1)::timestamp at time zone 'Asia/Seoul')
 ), page as (
  select * from filtered order by case when p_sort='created_asc' then created_at end asc,
   case when p_sort='updated_desc' then updated_at end desc,created_at desc,id desc limit p_limit offset p_offset
 ) select jsonb_build_object('total',(select count(*) from filtered),'checkedAt',at_value,'rows',coalesce((select jsonb_agg(jsonb_build_object(
  'id',p.id,'reference',p.reference,'title',p.title,'startsAt',p.starts_at,'endsAt',p.ends_at,'state',p.display_state,'revision',p.revision,
  'createdAt',p.created_at,'updatedAt',p.updated_at,'sectionCount',(select count(*) from public.shopping_story_sections x where x.story_id=p.id),
  'goodCount',(select count(*) from public.shopping_story_goods x where x.story_id=p.id)) order by case when p_sort='created_asc' then p.created_at end asc,
   case when p_sort='updated_desc' then p.updated_at end desc,p.created_at desc,p.id desc) from page p),'[]'::jsonb)) into result_value;
 return result_value;
end;
$$

create function public.admin_search_shopping_story_goods(p_query text default '',p_page integer default 1)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result_value jsonb;
begin
 if not public.has_operator_capability('store.manage') then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_query is null or char_length(p_query)>100 or p_page is null or p_page not between 1 and 1000000 then raise invalid_parameter_value using message='invalid_shopping_story_goods_search';end if;
 with filtered as (
  select g.*,ip.published_at as ip_published_at from public.goods g join public.ips ip on ip.id=g.ip_id
  where g.archived_at is null and ip.archived_at is null and (p_query='' or position(lower(p_query) in lower(g.name||' '||g.code||' '||g.id))>0)
 ), page as (select * from filtered order by name,id limit 20 offset (p_page-1)*20)
 select jsonb_build_object('page',p_page,'pageSize',20,'total',(select count(*) from filtered),'rows',coalesce((select jsonb_agg(jsonb_build_object(
  'id',p.id,'name',p.name,'code',p.code,'imagePath',p.image_path,'price',p.price,'archived',false,
  'published',p.published_at is not null and p.ip_published_at is not null and p.sale_restriction='none',
  'soldOut',p.stock='soldout' or coalesce(p.stock_qty,0)<=0) order by p.name,p.id) from page p),'[]'::jsonb)) into result_value;
 return result_value;
end;
$$

create function public.get_shopping_stories(p_limit integer default 12,p_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare at_value timestamptz:=statement_timestamp(); result_value jsonb;
begin
 if p_limit is null or p_limit not between 1 and 100 or p_offset is null or p_offset<0 then raise invalid_parameter_value using message='invalid_shopping_story_page';end if;
 with visible as (select * from public.shopping_stories s where deleted_at is null and private.shopping_story_state(starts_at,ends_at,at_value)='active'),
 page as (select * from visible order by created_at desc,id desc limit p_limit offset p_offset)
 select jsonb_build_object('total',(select count(*) from visible),'rows',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'reference',p.reference,
  'title',p.title,'bodyHtml',p.body_html,'imagePaths',to_jsonb(p.body_image_paths),'createdAt',p.created_at,'startsAt',p.starts_at,'endsAt',p.ends_at) order by p.created_at desc,p.id desc) from page p),'[]'::jsonb),
  'nextChangeAt',(select min(boundary) from public.shopping_stories s cross join lateral (values(s.starts_at),(s.ends_at)) dates(boundary) where s.deleted_at is null and dates.boundary>at_value)) into result_value;
 return result_value;
end;
$$

create function public.get_shopping_story(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare at_value timestamptz:=statement_timestamp(); story public.shopping_stories;
begin
 select * into story from public.shopping_stories s where s.id=p_id and s.deleted_at is null and private.shopping_story_state(s.starts_at,s.ends_at,at_value)='active';
 if not found then return null;end if;
 return jsonb_build_object('id',story.id,'reference',story.reference,'title',story.title,'bodyHtml',story.body_html,
  'imagePaths',to_jsonb(story.body_image_paths),'createdAt',story.created_at,'startsAt',story.starts_at,'endsAt',story.ends_at,'nextChangeAt',story.ends_at,
  'sections',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'title',x.title,'imageShape',x.image_shape,
   'goodIds',coalesce((select jsonb_agg(links.good_id order by links.sort_order) from public.shopping_story_goods links join public.goods g on g.id=links.good_id join public.ips ip on ip.id=g.ip_id
    where links.section_id=x.id and g.archived_at is null and g.published_at is not null and ip.archived_at is null and ip.published_at is not null and g.sale_restriction='none'),'[]'::jsonb)) order by x.sort_order)
    from public.shopping_story_sections x where x.story_id=p_id),'[]'::jsonb),
  -- A single JSON aggregate contains every related product. It cannot be cut
  -- to a PostgREST row page, and 300 long IDs never become an oversized GET URL.
  'goods',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'price',g.price,'compareAtPrice',g.compare_at_price,
   'showDiscountRate',g.show_discount_rate,'badge',g.badge,'stock',g.stock,'imagePath',g.image_path,'bg',g.bg,
   'variants',coalesce((select jsonb_agg(jsonb_build_object('price',v.price,'pricing',public.goods_variant_pricing(v),'supply',public.goods_variant_supply(v)) order by v.id)
    from public.goods_variants v where v.good_id=g.id and v.archived_at is null),'[]'::jsonb)) order by g.id)
   from public.shopping_story_goods links join public.goods g on g.id=links.good_id join public.ips ip on ip.id=g.ip_id
   where links.story_id=p_id and g.archived_at is null and g.published_at is not null and ip.archived_at is null and ip.published_at is not null and g.sale_restriction='none'),'[]'::jsonb));
end;
$$

do $$ begin
 perform private.register_operator_rpc_contract('public.admin_save_shopping_story(uuid,integer,uuid,jsonb)'::regprocedure,'store.manage','write',false);
 perform private.register_operator_rpc_contract('public.admin_delete_shopping_stories(uuid,jsonb)'::regprocedure,'store.manage','write',false);
 perform private.register_operator_rpc_contract('public.admin_get_shopping_story(uuid)'::regprocedure,'store.manage','read',false);
 perform private.register_operator_rpc_contract('public.admin_list_shopping_stories(text,text,date,date,text,integer,integer)'::regprocedure,'store.manage','read',false);
 perform private.register_operator_rpc_contract('public.admin_search_shopping_story_goods(text,integer)'::regprocedure,'store.manage','read',false);
 perform private.register_operator_policy_contract('public.shopping_stories'::regclass,'shopping_stories_operator_read','store.manage');
 perform private.register_operator_policy_contract('public.shopping_story_sections'::regclass,'shopping_story_sections_operator_read','store.manage');
 perform private.register_operator_policy_contract('public.shopping_story_goods'::regclass,'shopping_story_goods_operator_read','store.manage');
 perform private.register_operator_internal_contract('public.get_shopping_story(uuid)'::regprocedure);
 perform private.register_operator_internal_contract('public.get_shopping_stories(integer,integer)'::regprocedure);
 perform private.register_operator_internal_contract('private.shopping_story_state(timestamptz,timestamptz,timestamptz)'::regprocedure);
 perform private.register_operator_internal_contract('private.validate_shopping_story_values(jsonb)'::regprocedure);
 perform private.register_operator_internal_contract('private.shopping_story_document(uuid)'::regprocedure);
 perform private.register_operator_internal_contract('private.goods_photo_references(text)'::regprocedure);
end $$

-- Batch projection for member-list/detail sanction controls. The mutation repeats
-- the same rules under actor/target locks; this read is never authorization proof.
create function public.admin_member_moderation_context(p_profile_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=(select auth.uid()); legacy boolean; actor_role public.user_role;
begin
  if not public.has_operator_capability('platform.manage',false) then
    raise insufficient_privilege using message='operator_capability_required';end if;
  if p_profile_ids is null or cardinality(p_profile_ids)>100 or array_position(p_profile_ids,null) is not null then
    raise invalid_parameter_value using message='invalid_member_moderation_targets';end if;
  legacy:=(private.operator_access_for(actor)->>'mode')='legacy';
  select role into actor_role from public.profiles where id=actor;
  return (select coalesce(jsonb_agg(jsonb_build_object('profileId',profile.id,'managerRole',membership.manager_role,
    'canModerate',profile.id<>actor and coalesce(membership.manager_role not in ('owner','primary'),true)
      and (not legacy or (profile.role<>'admin' and (actor_role<>'staff' or profile.role='user')))
  ) order by profile.id),'[]') from public.profiles profile
  left join private.operator_memberships membership on membership.profile_id=profile.id
  where profile.id=any(p_profile_ids));
end $$

-- Keep the existing authenticated writer contract: a missing principal is an
-- authentication error; a present principal without authority is a denial.
create or replace function private.require_operator_capability(p_capability text,p_legacy_admin_only boolean default false)
returns uuid language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());
begin
  if actor is null then raise invalid_authorization_specification using message='auth_required';end if;
  return private.require_actor_operator_capability(actor,p_capability,p_legacy_admin_only);
end $$

-- Keep the confirmed Auth email stable through the membership grant. Account
-- deletion already acquires the same account-action fence before Auth deletion.
do $$
declare definition text; revised text;
begin
  definition:=pg_get_functiondef('public.accept_operator_invitation(text,uuid)'::regprocedure);
  revised:=replace(definition,
    'select lower(email),email_confirmed_at into current_email,confirmed_at from auth.users where id=actor;',
    'select lower(email),email_confirmed_at into current_email,confirmed_at from auth.users where id=actor for share;');
  if definition=revised then raise exception 'invitation verified email contract changed'; end if;
  execute revised;
end $$

-- RPC authorization receipts cover execution metadata as well as body text.
-- Register after final owner/ACL/attributes are set, including future migrations.
create or replace function private.register_operator_rpc_contract(p_function regprocedure,p_capability text,p_guard_kind text,p_legacy_admin_only boolean default false)
returns void language plpgsql volatile security definer set search_path='' as $$
declare function_name text;function_body text;
begin
  select p.oid::regprocedure::text,p.prosrc into function_name,function_body from pg_proc p where p.oid=p_function::oid;
  if not found then raise undefined_function using message='operator_rpc_contract_function_missing';end if;
  insert into private.operator_rpc_contracts(signature,capability,guard_kind,legacy_admin_only,body_md5)
  values(function_name,p_capability,p_guard_kind,p_legacy_admin_only,md5(function_body))
  on conflict(signature) do update set capability=excluded.capability,guard_kind=excluded.guard_kind,
    legacy_admin_only=excluded.legacy_admin_only,body_md5=excluded.body_md5;
  perform private.register_operator_internal_contract(p_function);
end $$

do $$ declare contract record;
begin
  for contract in select signature from private.operator_rpc_contracts loop
    perform private.register_operator_internal_contract(contract.signature::regprocedure);
  end loop;
  perform private.register_operator_internal_contract('private.register_operator_rpc_contract(regprocedure,text,text,boolean)'::regprocedure);
end $$

-- Read the actual loyalty grade through the existing narrow operator projection.
-- Cross-member profiles SELECT remains self-only; never present a fabricated WELCOME grade.
create or replace function public.admin_member_moderation_context(p_profile_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=(select auth.uid()); legacy boolean; actor_role public.user_role;
begin
  if not public.has_operator_capability('platform.manage',false) then
    raise insufficient_privilege using message='operator_capability_required';end if;
  if p_profile_ids is null or cardinality(p_profile_ids)>100 or array_position(p_profile_ids,null) is not null then
    raise invalid_parameter_value using message='invalid_member_moderation_targets';end if;
  legacy:=(private.operator_access_for(actor)->>'mode')='legacy';
  select role into actor_role from public.profiles where id=actor;
  return (select coalesce(jsonb_agg(jsonb_build_object('profileId',profile.id,'managerRole',membership.manager_role,
    'loyaltyGrade',profile.loyalty_grade,
    'canModerate',profile.id<>actor and coalesce(membership.manager_role not in ('owner','primary'),true)
      and (not legacy or (profile.role<>'admin' and (actor_role<>'staff' or profile.role='user')))
  ) order by profile.id),'[]') from public.profiles profile
  left join private.operator_memberships membership on membership.profile_id=profile.id
  where profile.id=any(p_profile_ids));
end $$

-- Drafting/stopping a preorder stays catalog work; activation retains the
-- separate platform approval gate inside the existing state transition.
CREATE OR REPLACE FUNCTION public.admin_save_goods_preorder(p_good_id text, p_variant_id uuid, p_policy_id uuid, p_values jsonb, p_expected_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); variant public.goods_variants; previous private.goods_preorder_policies; saved private.goods_preorder_policies;
  state_value text; capacity_value integer; starts_value timestamptz; ends_value timestamptz; date_value date; evidence_value text; is_admin boolean;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null or not coalesce(public.has_operator_capability('catalog.manage',false),false) then raise insufficient_privilege using message='staff required'; end if;
  is_admin:=exists(select 1 from public.profiles where id=actor and private.has_operator_capability(id,'platform.manage',true));
  if jsonb_typeof(p_values) is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(p_values) key where key not in ('state','capacityQty','startsAt','endsAt','expectedShipDate','approvalReference')) then
    raise invalid_parameter_value using message='invalid_preorder_policy';
  end if;
  state_value:=p_values->>'state';
  if state_value is null or state_value not in ('draft','active','stopped') then raise check_violation using message='invalid_preorder_policy'; end if;
  if state_value='active' and not is_admin then raise insufficient_privilege using message='preorder_admin_required'; end if;
  perform 1 from public.goods where id=p_good_id and archived_at is null for update;
  if not found then raise no_data_found using message='good_not_found'; end if;
  select * into variant from public.goods_variants where id=p_variant_id and good_id=p_good_id for update;
  if not found then raise no_data_found using message='goods_variant_not_found'; end if;
  if p_policy_id is not null then
    select * into previous from private.goods_preorder_policies where id=p_policy_id and variant_id=p_variant_id for update;
    if not found then raise no_data_found using message='preorder_policy_not_found'; end if;
  end if;
  if previous.revision is distinct from p_expected_revision then raise sqlstate 'PT409' using message='preorder_policy_changed'; end if;
  if state_value='stopped' then
    if previous.state is null or previous.state='draft' then raise check_violation using message='preorder_not_active'; end if;
    if previous.state='stopped' then return jsonb_build_object('id',previous.id,'revision',previous.revision,'changed',false); end if;
    update private.goods_preorder_policies set state='stopped',stopped_by=actor,stopped_at=clock_timestamp(),
      revision=revision+1,updated_at=clock_timestamp() where id=previous.id returning * into saved;
  else
    if previous.state is not null and previous.state<>'draft' then raise check_violation using message='preorder_policy_immutable'; end if;
    if p_values->'capacityQty' is not null and p_values->'capacityQty'<>'null'::jsonb then
      if jsonb_typeof(p_values->'capacityQty')<>'number' or p_values->>'capacityQty' !~ '^[1-9][0-9]*$'
        or (p_values->>'capacityQty')::numeric>2147483647 then raise check_violation using message='invalid_preorder_policy'; end if;
      capacity_value:=(p_values->>'capacityQty')::integer;
    end if;
    if nullif(p_values->>'startsAt','') is not null then
      if jsonb_typeof(p_values->'startsAt')<>'string' or p_values->>'startsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' then raise check_violation using message='invalid_preorder_policy'; end if;
      starts_value:=(p_values->>'startsAt')::timestamptz;
    end if;
    if nullif(p_values->>'endsAt','') is not null then
      if jsonb_typeof(p_values->'endsAt')<>'string' or p_values->>'endsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' then raise check_violation using message='invalid_preorder_policy'; end if;
      ends_value:=(p_values->>'endsAt')::timestamptz;
    end if;
    if nullif(p_values->>'expectedShipDate','') is not null then
      if p_values->>'expectedShipDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise check_violation using message='invalid_preorder_policy'; end if;
      date_value:=(p_values->>'expectedShipDate')::date;
    end if;
    if p_values->'approvalReference' is not null and p_values->'approvalReference'<>'null'::jsonb and jsonb_typeof(p_values->'approvalReference')<>'string' then
      raise check_violation using message='invalid_preorder_policy';
    end if;
    evidence_value:=nullif(btrim(p_values->>'approvalReference'),'');
    if (starts_value is not null and not isfinite(starts_value)) or (ends_value is not null and not isfinite(ends_value))
      or (starts_value is not null and ends_value is not null and starts_value>=ends_value)
      or length(evidence_value)>2000 then raise check_violation using message='invalid_preorder_policy'; end if;
    if state_value='active' then
      if to_regprocedure('private.preorder_checkout_ready()') is null then raise check_violation using message='preorder_runtime_not_ready'; end if;
      if capacity_value is null or starts_value is null or ends_value is null or date_value is null or evidence_value is null
        or ends_value<=clock_timestamp() or date_value<(ends_value at time zone 'Asia/Seoul')::date then
        raise check_violation using message='preorder_policy_not_configured';
      end if;
      if variant.archived_at is not null then raise check_violation using message='goods_variant_inactive'; end if;
      if exists(select 1 from private.goods_preorder_policies where variant_id=variant.id and state='active' and id is distinct from previous.id) then
        raise check_violation using message='preorder_policy_already_active';
      end if;
    end if;
    if previous.id is null then
      insert into private.goods_preorder_policies(variant_id,state,capacity_qty,starts_at,ends_at,expected_ship_date,approval_reference,created_by,activated_by,activated_at)
      values(variant.id,state_value,capacity_value,starts_value,ends_value,date_value,evidence_value,actor,
        case when state_value='active' then actor end,case when state_value='active' then clock_timestamp() end) returning * into saved;
    else
      update private.goods_preorder_policies set state=state_value,capacity_qty=capacity_value,starts_at=starts_value,ends_at=ends_value,
        expected_ship_date=date_value,approval_reference=evidence_value,revision=revision+1,updated_at=clock_timestamp(),
        activated_by=case when state_value='active' then actor end,activated_at=case when state_value='active' then clock_timestamp() end
        where id=previous.id returning * into saved;
    end if;
    if saved.state='active' then update public.goods_variants set preorder_policy_id=saved.id where id=variant.id; end if;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.good.preorder_saved','goods:'||p_good_id,
    jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
  return jsonb_build_object('id',saved.id,'revision',saved.revision,'changed',true);
end $function$

create or replace function private.store_navigation_valid(settings jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
declare entry jsonb; ids text[]:='{}'; label text;
begin
  if jsonb_typeof(settings) is distinct from 'array' then return false; end if;
  if jsonb_array_length(settings)<>8 then return false; end if;
  for entry in select value from jsonb_array_elements(settings) loop
    if jsonb_typeof(entry) is distinct from 'object' then return false; end if;
    if not entry ?& array['id','label','visible'] or (select count(*) from jsonb_object_keys(entry))<>3
      or jsonb_typeof(entry->'id') is distinct from 'string'
      or entry->>'id' not in ('new','best','shop','iphub','packs','events','community','stories')
      or jsonb_typeof(entry->'label') is distinct from 'string'
      or jsonb_typeof(entry->'visible') is distinct from 'boolean'
      or entry->>'id'=any(ids) then return false; end if;
    label:=entry->>'label';
    if length(label) not between 1 and 20 or label ~ '[[:cntrl:]]'
      or label<>btrim(label,E' \t\n\r\f\v'||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
      or (entry->>'id'='shop' and not (entry->>'visible')::boolean) then return false; end if;
    ids:=array_append(ids,entry->>'id');
  end loop;
  return true;
end $$

-- The original five blocks remain valid for saved layouts. A missing story key
-- appends by default; an explicit disabled story key remains hidden.
create or replace function private.is_valid_home_layout_blocks(candidate jsonb)
returns boolean language plpgsql immutable set search_path = '' as $$
declare entry jsonb; block_key text; seen text[] := '{}';
begin
  if candidate is null then return true; end if;
  if pg_catalog.jsonb_typeof(candidate) <> 'array'
    or pg_catalog.jsonb_array_length(candidate) not between 5 and 1000 then return false; end if;
  for entry in select value from pg_catalog.jsonb_array_elements(candidate)
  loop
    if pg_catalog.jsonb_typeof(entry) <> 'object'
      or pg_catalog.jsonb_typeof(entry->'key') is distinct from 'string'
      or pg_catalog.jsonb_typeof(entry->'enabled') is distinct from 'boolean'
      or exists(select 1 from pg_catalog.jsonb_object_keys(entry) field where field not in ('key','enabled'))
    then return false; end if;
    block_key := entry->>'key';
    if block_key = any(seen) then return false; end if;
    if block_key not in ('hero','editor_picks','category_best','popular','benefits','stories')
      and block_key !~ '^(band|sales|reviews|mosaic):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then return false; end if;
    seen := pg_catalog.array_append(seen, block_key);
  end loop;
  return array['hero','editor_picks','category_best','popular','benefits']::text[] <@ seen;
end;
$$

create or replace function public.get_home_layout_order()
returns text[] language plpgsql stable security definer set search_path = '' as $$
declare configured jsonb; result text[];
begin
  select blocks into configured from public.home_layout_settings where singleton;
  if configured is null then return null; end if;
  with requested as (
    select item->>'key' as key, item->'enabled'='true'::jsonb as enabled, position
    from pg_catalog.jsonb_array_elements(configured) with ordinality entries(item,position)
  ), active_bands as (
    select (case kind when 'band_banner' then 'band:' when 'sales_best' then 'sales:' when 'review_best' then 'reviews:' else 'mosaic:' end)||id::text as key,
      case kind when 'band_banner' then 0 when 'sales_best' then 1 when 'review_best' then 2 else 3 end as kind_order,display_order, active_from, id
    from public.home_curations
    where kind in ('band_banner','sales_best','review_best','product_mosaic') and enabled and active_from<=now()
      and (active_to is null or active_to>now())
  ), ordered as (
    select requested.key, requested.position
    from requested
    where requested.enabled and (
      requested.key in ('hero','editor_picks','category_best','popular','benefits','stories')
      or exists(select 1 from active_bands where active_bands.key=requested.key)
    )
    union all
    select active_bands.key,
      pg_catalog.jsonb_array_length(configured)+row_number() over(order by kind_order,display_order,active_from,id)
    from active_bands where not exists(select 1 from requested where requested.key=active_bands.key)
    union all
    select 'stories',pg_catalog.jsonb_array_length(configured)+(select count(*) from active_bands)+1
    where not exists(select 1 from requested where key='stories')
  )
  select coalesce(pg_catalog.array_agg(key order by position),'{}'::text[]) into result from ordered;
  return result;
end;
$$

create function public.admin_issue_marketing_links(p_source text,p_target_ids text[],p_operation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid(); ids text[]; target text; label text; item_id uuid; issued uuid[]:='{}'; request jsonb; replay jsonb;
begin
 if p_source is null or p_source not in ('home','good','story','category') or p_operation_id is null
  or p_target_ids is null or cardinality(p_target_ids) not between 1 and 100 or array_ndims(p_target_ids)<>1
  or exists(select 1 from unnest(p_target_ids) v where v is null or char_length(v) not between 1 and 200 or v ~ '[[:cntrl:]]')
  or cardinality(p_target_ids)<>(select count(distinct v) from unnest(p_target_ids) v)
  or (p_source='home' and p_target_ids<>array['home'])
  or (p_source='good' and exists(select 1 from unnest(p_target_ids) v where v!~'^[a-z0-9][a-z0-9-]{0,199}$'))
  or (p_source in ('story','category') and exists(select 1 from unnest(p_target_ids) v where v!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'))
 then raise invalid_parameter_value using message='invalid_marketing_targets';end if;
 perform private.require_actor_operator_capability(actor,case when p_source in ('home','story') then 'store.manage' else 'catalog.manage' end,false);
 select array_agg(v order by v) into ids from unnest(p_target_ids) v;
 request:=jsonb_build_object('source',p_source,'targetIds',ids);
 perform pg_advisory_xact_lock(hashtextextended('marketing-link:operation:'||p_operation_id::text,0));
 replay:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.marketing_links.issued',request);
 if replay is not null then
  select array_agg(value::uuid) into issued from jsonb_array_elements_text(replay->'ids');
  return jsonb_build_object('rows',private.marketing_link_rows(issued));
 end if;
 for target in select unnest(ids) loop
  label:=null;
  if p_source='home' then label:='스토어 홈';
  elsif p_source='good' then select name into label from public.goods where id=target for key share;
  elsif p_source='story' then select title into label from public.shopping_stories where id=target::uuid and deleted_at is null for key share;
  else select name into label from public.catalog_categories where id=target::uuid for key share;end if;
  if label is null then raise no_data_found using message='marketing_target_missing';end if;
  -- Per-target lock and uniqueness protect simultaneous issue requests. Names and
  -- publish states may change later; the stored token never changes with them.
  perform pg_advisory_xact_lock(hashtextextended('marketing-link:'||p_source||':'||target,0));
  select id into item_id from private.marketing_links where source=p_source and
   case p_source when 'home' then true when 'good' then good_id=target when 'story' then story_id=target::uuid else category_id=target::uuid end;
  if item_id is null then
   insert into private.marketing_links(source,original_target_id,original_title,good_id,story_id,category_id,created_by)
   values(p_source,target,label,case when p_source='good' then target end,case when p_source='story' then target::uuid end,
     case when p_source='category' then target::uuid end,actor) returning id into item_id;
  end if;
  issued:=array_append(issued,item_id);
 end loop;
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.marketing_links.issued','marketing_links:'||p_source,
  jsonb_build_object('request',request,'result',jsonb_build_object('ids',issued)));
 return jsonb_build_object('rows',private.marketing_link_rows(issued));
end $$

create function public.admin_list_marketing_links(p_source text default 'home',p_query text default '',p_status text default 'all',p_page integer default 1,p_page_size integer default 20)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ids uuid[]; total_count bigint; q text:=btrim(coalesce(p_query,''));
begin
 if not private.has_operator_capability(auth.uid(),'marketing.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_source is null or p_source not in ('home','good','story','category') or length(q)>100 or p_status is null or p_status not in ('all','available','unavailable')
  or p_page is null or p_page not between 1 and 1000000 or p_page_size is null or p_page_size not in (20,50,100)
 then raise invalid_parameter_value using message='invalid_marketing_filter';end if;
 with matched as materialized(select l.id,l.created_at from private.marketing_links l
  left join public.goods g on g.id=l.good_id left join public.shopping_stories s on s.id=l.story_id left join public.catalog_categories c on c.id=l.category_id
  where l.source=p_source and (q='' or strpos(lower(coalesce(g.name,s.title,c.name,l.original_title)),lower(q))>0
    or strpos(lower(coalesce(l.good_id,l.story_id::text,l.category_id::text,l.original_target_id)),lower(q))>0 or strpos(l.token,lower(q))>0)
  and (p_status='all' or private.marketing_link_available(l)=(p_status='available'))), page_rows as (
   select * from matched order by created_at desc,id desc limit p_page_size offset (p_page-1)*p_page_size)
 select (select count(*) from matched),coalesce((select array_agg(id) from page_rows),'{}') into total_count,ids;
 return jsonb_build_object('total',total_count,'rows',private.marketing_link_rows(ids));
end $$

create function private.normalize_customer_segment_rule(p_rule jsonb)
returns jsonb language plpgsql immutable set search_path='' as $$
declare target text; scope text; good_ids text[]; grades text[]; age_bands integer[]; months integer; days integer;
 category_id uuid; ip_id text; coupon_code text; item jsonb;
begin
 if p_rule is null or jsonb_typeof(p_rule)<>'object' or p_rule->'version' is distinct from '1'::jsonb
  or jsonb_typeof(p_rule->'target') is distinct from 'string'
  or exists(select 1 from jsonb_object_keys(p_rule) key where key not in
   ('version','target','goodsScope','goodIds','categoryId','months','activityDays','grades','ageBands','ipId','couponCode')) then
  raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 target:=p_rule->>'target';scope:=coalesce(p_rule->>'goodsScope','all');
 if target not in ('first_purchase','cart_unpurchased','wishlist_unpurchased','unused_coupon','ip_notifications','purchased','first_purchase_recent','lapsed_purchase','repeat_purchase')
  or scope not in ('all','goods','category')
  or (p_rule ? 'goodsScope' and jsonb_typeof(p_rule->'goodsScope')<>'string')
  or jsonb_typeof(coalesce(p_rule->'goodIds','[]'))<>'array'
  or jsonb_array_length(coalesce(p_rule->'goodIds','[]'))>100
  or jsonb_typeof(coalesce(p_rule->'grades','[]'))<>'array'
  or jsonb_array_length(coalesce(p_rule->'grades','[]'))>4
  or jsonb_typeof(coalesce(p_rule->'ageBands','[]'))<>'array'
  or jsonb_array_length(coalesce(p_rule->'ageBands','[]'))>6 then
  raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 for item in select value from jsonb_array_elements(coalesce(p_rule->'goodIds','[]')) loop
  if jsonb_typeof(item)<>'string' or (item#>>'{}')!~'^[a-z0-9][a-z0-9-]{0,199}$' then
   raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 end loop;
 select coalesce(array_agg(value order by value),'{}'::text[]) into good_ids from jsonb_array_elements_text(coalesce(p_rule->'goodIds','[]'));
 if cardinality(good_ids)<>(select count(distinct value) from unnest(good_ids) value) then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 for item in select value from jsonb_array_elements(coalesce(p_rule->'grades','[]')) loop
  if jsonb_typeof(item)<>'string' or (item#>>'{}') not in ('welcome','silver','gold','platinum') then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 end loop;
 select coalesce(array_agg(value order by value),'{}'::text[]) into grades from jsonb_array_elements_text(coalesce(p_rule->'grades','[]'));
 if cardinality(grades)<>(select count(distinct value) from unnest(grades) value) then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 for item in select value from jsonb_array_elements(coalesce(p_rule->'ageBands','[]')) loop
  if jsonb_typeof(item)<>'number' or item::text not in ('10','20','30','40','50','60') then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 end loop;
 select coalesce(array_agg(value::integer order by value::integer),'{}'::integer[]) into age_bands from jsonb_array_elements_text(coalesce(p_rule->'ageBands','[]'));
 if cardinality(age_bands)<>(select count(distinct value) from unnest(age_bands) value) then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 if coalesce(p_rule->'categoryId','null')<>'null'::jsonb then
  if jsonb_typeof(p_rule->'categoryId')<>'string' or (p_rule->>'categoryId')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
  category_id:=(p_rule->>'categoryId')::uuid;
 end if;
 if (scope='all' and (cardinality(good_ids)>0 or category_id is not null))
  or (scope='goods' and (cardinality(good_ids)=0 or category_id is not null))
  or (scope='category' and (category_id is null or cardinality(good_ids)>0))
  or (target not in ('cart_unpurchased','wishlist_unpurchased','purchased') and scope<>'all') then
  raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 if coalesce(p_rule->'months','null')<>'null'::jsonb then
  if jsonb_typeof(p_rule->'months')<>'number' or (p_rule->'months')::text not in ('1','3','6') then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
  months:=(p_rule->>'months')::integer;
 end if;
 if (target='first_purchase_recent' and months is null) or (target='lapsed_purchase' and coalesce(months,0) not in (3,6))
  or (target='repeat_purchase' and months is not null and months not in (1,3))
  or (target not in ('first_purchase_recent','lapsed_purchase','repeat_purchase','purchased') and months is not null) then
  raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 if coalesce(p_rule->'activityDays','null')<>'null'::jsonb then
  if jsonb_typeof(p_rule->'activityDays')<>'number' or (p_rule->'activityDays')::text not in ('7','30','90')
   or target not in ('cart_unpurchased','wishlist_unpurchased') then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
  days:=(p_rule->>'activityDays')::integer;
 end if;
 if coalesce(p_rule->'ipId','null')<>'null'::jsonb then
  if jsonb_typeof(p_rule->'ipId')<>'string' or (p_rule->>'ipId')!~'^[a-z0-9][a-z0-9-]{0,199}$' or target<>'ip_notifications' then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
  ip_id:=p_rule->>'ipId';
 end if;
 if coalesce(p_rule->'couponCode','null')<>'null'::jsonb then
  if jsonb_typeof(p_rule->'couponCode')<>'string' or (p_rule->>'couponCode')!~'^[A-Z0-9][A-Z0-9-]{2,23}$' or target<>'unused_coupon' then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
  coupon_code:=p_rule->>'couponCode';
 end if;
 return jsonb_build_object('version',1,'target',target,'goodsScope',scope,'goodIds',to_jsonb(good_ids),'categoryId',category_id,
  'months',months,'activityDays',days,'grades',to_jsonb(grades),'ageBands',to_jsonb(age_bands),'ipId',ip_id,'couponCode',coupon_code);
end $$

-- Reusable execution boundary: a caller must bind the expected definition.
-- This function is not exposed to authenticated/service clients. A downstream
-- publisher must call it inside its own current-authority and delivery guards.
create function private.customer_segment_execution_members(p_segment_id uuid,p_expected_revision integer,p_expected_hash text)
returns table(customer_id uuid) language plpgsql stable security definer set search_path='' as $$
declare segment private.customer_segments;
begin
 select * into segment from private.customer_segments where id=p_segment_id and archived_at is null;
 if not found then raise no_data_found using message='customer_segment_not_found';end if;
 if segment.revision is distinct from p_expected_revision or segment.rule_hash is distinct from p_expected_hash then
  raise sqlstate 'PT409' using message='customer_segment_changed';end if;
 return query select members.customer_id from private.customer_segment_members(segment.rule,statement_timestamp()) members where members.marketing_consent;
end $$

create function public.admin_customer_segment_overview()
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare at_value timestamptz:=statement_timestamp(); interested_count bigint; buyer_count bigint; loyal_count bigint; first_count bigint;
begin
 if not public.has_operator_capability('marketing.manage') then raise insufficient_privilege using message='operator_capability_required';end if;
 select count(*) into first_count from private.customer_segment_members('{"version":1,"target":"first_purchase"}',at_value);
 select count(*) into buyer_count from private.customer_segment_members('{"version":1,"target":"purchased"}',at_value);
 select count(*) into loyal_count from private.customer_segment_members('{"version":1,"target":"repeat_purchase"}',at_value);
 select count(distinct customer_id) into interested_count from (
  select customer_id from private.customer_segment_members('{"version":1,"target":"cart_unpurchased"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"wishlist_unpurchased"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"unused_coupon"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"ip_notifications"}',at_value)
 ) interested;
 return jsonb_build_object('checkedAt',at_value,'groups',jsonb_build_object('potential',null,'visitor',null,'interested',interested_count,'buyer',buyer_count,'loyal',loyal_count),
  'firstPurchaseMembers',first_count,'memberCount',first_count+buyer_count);
end $$

create function public.admin_estimate_customer_segment(p_rule jsonb,p_operation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid; rule jsonb; hash text; existing private.customer_segment_estimates; at_value timestamptz:=statement_timestamp(); matched bigint; consented bigint;
begin
 actor:=private.require_operator_capability('marketing.manage',false);
 if p_operation_id is null then raise invalid_parameter_value using message='invalid_customer_segment_operation';end if;
 rule:=private.normalize_customer_segment_rule(p_rule);hash:=private.customer_segment_rule_hash(rule);
 perform pg_advisory_xact_lock(hashtextextended('customer-segment-estimate:'||p_operation_id::text,0));
 select * into existing from private.customer_segment_estimates where id=p_operation_id;
 if found then
  if existing.actor_id=actor and existing.rule_hash=hash and existing.rule=rule then return private.customer_segment_estimate_document(existing.id);end if;
  raise sqlstate 'PT409' using message='customer_segment_operation_conflict';
 end if;
 select count(*),count(*) filter(where marketing_consent) into matched,consented from private.customer_segment_members(rule,at_value);
 insert into private.customer_segment_estimates(id,actor_id,rule_version,rule,rule_hash,evaluated_at,matched_count,consented_count,valid_until)
 values(p_operation_id,actor,1,rule,hash,at_value,matched,consented,at_value+interval '15 minutes');
 return private.customer_segment_estimate_document(p_operation_id);
end $$

create function public.admin_save_customer_segment(p_id uuid,p_expected_revision integer,p_operation_id uuid,p_name text,p_rule jsonb,p_estimate_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid; rule jsonb; hash text; estimate private.customer_segment_estimates; previous private.customer_segments;
 request jsonb; replay jsonb; result jsonb; name_value text:=btrim(p_name); saved_revision integer;
begin
 actor:=private.require_operator_capability('marketing.manage',false);
 if p_id is null or p_expected_revision is null or p_expected_revision<0 or p_operation_id is null or p_estimate_id is null
  or name_value is null or char_length(name_value) not between 1 and 50 or name_value ~ '[[:cntrl:]]' then
  raise invalid_parameter_value using message='invalid_customer_segment';end if;
 rule:=private.normalize_customer_segment_rule(p_rule);hash:=private.customer_segment_rule_hash(rule);
 request:=jsonb_build_object('id',p_id,'expectedRevision',p_expected_revision,'name',name_value,'rule',rule,'estimateId',p_estimate_id);
 perform pg_advisory_xact_lock(hashtextextended('customer-segment-operation:'||p_operation_id::text,0));
 replay:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.customer_segment.saved',request);
 if replay is not null then return replay;end if;
 perform pg_advisory_xact_lock(hashtextextended('customer-segment-catalog',0));
 select * into previous from private.customer_segments where id=p_id for update;
 if found then
  if previous.archived_at is not null then raise no_data_found using message='customer_segment_not_found';end if;
  if previous.preset_key is not null then raise insufficient_privilege using message='customer_segment_preset_readonly';end if;
  if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='customer_segment_changed';end if;
 elsif p_expected_revision<>0 then raise no_data_found using message='customer_segment_not_found';
 elsif (select count(*) from private.customer_segments where archived_at is null and preset_key is null)>=1000 then
  raise check_violation using message='customer_segment_limit';
 end if;
 select * into estimate from private.customer_segment_estimates where id=p_estimate_id;
 if not found or estimate.actor_id is distinct from actor or estimate.rule_hash<>hash or estimate.rule<>rule
  or estimate.valid_until<=clock_timestamp() then raise object_not_in_prerequisite_state using message='customer_segment_estimate_required';end if;
 if not private.customer_segment_references_available(rule) then raise object_not_in_prerequisite_state using message='customer_segment_target_unavailable';end if;
 if previous.id is null then
  insert into private.customer_segments(id,name,rule_version,rule,rule_hash,estimate_id,created_by,updated_by)
  values(p_id,name_value,1,rule,hash,p_estimate_id,actor,actor) returning revision into saved_revision;
 else
  update private.customer_segments set name=name_value,rule_version=1,rule=rule,rule_hash=hash,estimate_id=p_estimate_id,
   revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id=p_id returning revision into saved_revision;
 end if;
 result:=jsonb_build_object('id',p_id,'revision',saved_revision,'ruleHash',hash);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.customer_segment.saved','customer_segment:'||p_id::text,
  jsonb_build_object('request',request,'previousRuleHash',previous.rule_hash,'result',result));
 return result;
end $$

create function public.admin_archive_customer_segments(p_entries jsonb,p_operation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid; entry jsonb; ids uuid[]:='{}'::uuid[]; id_value uuid; previous private.customer_segments; request jsonb; replay jsonb; result jsonb;
begin
 actor:=private.require_operator_capability('marketing.manage',false);
 if p_operation_id is null or p_entries is null or jsonb_typeof(p_entries)<>'array' or jsonb_array_length(p_entries) not between 1 and 100 then
  raise invalid_parameter_value using message='invalid_customer_segment_archive';end if;
 for entry in select value from jsonb_array_elements(p_entries) loop
  if jsonb_typeof(entry)<>'object' or not(entry ?& array['id','revision']) or (select count(*) from jsonb_object_keys(entry))<>2
   or jsonb_typeof(entry->'id')<>'string' or (entry->>'id')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(entry->'revision')<>'number' or (entry->>'revision')!~'^[1-9][0-9]{0,8}$' then
   raise invalid_parameter_value using message='invalid_customer_segment_archive';end if;
  id_value:=(entry->>'id')::uuid;
  if id_value=any(ids) then raise invalid_parameter_value using message='invalid_customer_segment_archive';end if;
  ids:=array_append(ids,id_value);
 end loop;
 select jsonb_agg(value order by value->>'id') into request from jsonb_array_elements(p_entries);
 perform pg_advisory_xact_lock(hashtextextended('customer-segment-operation:'||p_operation_id::text,0));
 replay:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.customer_segments.archived',request);
 if replay is not null then return replay;end if;
 perform pg_advisory_xact_lock(hashtextextended('customer-segment-catalog',0));
 for id_value in select value from unnest(ids) value order by value loop
  select * into previous from private.customer_segments where id=id_value for update;
  if not found or previous.archived_at is not null then raise no_data_found using message='customer_segment_not_found';end if;
  if previous.preset_key is not null then raise insufficient_privilege using message='customer_segment_preset_readonly';end if;
  if previous.revision<>(select (value->>'revision')::integer from jsonb_array_elements(request) where (value->>'id')::uuid=id_value) then
   raise sqlstate 'PT409' using message='customer_segment_changed';end if;
 end loop;
 update private.customer_segments set archived_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id=any(ids);
 delete from private.customer_segment_favorites where segment_id=any(ids);
 result:=jsonb_build_object('archivedCount',cardinality(ids));
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.customer_segments.archived','customer_segments',jsonb_build_object('request',request,'result',result));
 return result;
end $$

create function public.admin_set_customer_segment_favorite(p_segment_id uuid,p_favorite boolean)
returns boolean language plpgsql volatile security definer set search_path='' as $$
declare actor uuid;
begin
 actor:=private.require_operator_capability('marketing.manage',false);
 if p_segment_id is null or p_favorite is null then raise invalid_parameter_value using message='invalid_customer_segment_favorite';end if;
 perform 1 from private.customer_segments where id=p_segment_id and archived_at is null for share;
 if not found then raise no_data_found using message='customer_segment_not_found';end if;
 if p_favorite then
  if exists(select 1 from private.customer_segment_favorites where actor_id=actor and segment_id=p_segment_id) then return true;end if;
  if (select count(*) from private.customer_segment_favorites where actor_id=actor)>=3 then raise check_violation using message='customer_segment_favorite_limit';end if;
  insert into private.customer_segment_favorites(actor_id,segment_id) values(actor,p_segment_id);
 else delete from private.customer_segment_favorites where actor_id=actor and segment_id=p_segment_id;end if;
 return p_favorite;
end $$

create function public.admin_get_customer_segment(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=auth.uid(); segment private.customer_segments; months jsonb; choices jsonb; at_value timestamptz:=statement_timestamp();
begin
 if not public.has_operator_capability('marketing.manage') then raise insufficient_privilege using message='operator_capability_required';end if;
 select * into segment from private.customer_segments where id=p_id and archived_at is null;
 if not found then return null;end if;
 with calendar as (select date_trunc('month',at_value at time zone 'Asia/Seoul')-make_interval(months=>ago) month_start from generate_series(12,0,-1) ago),
 observations as (
  select calendar.month_start,observation.* from calendar left join lateral (
   select e.evaluated_at,e.matched_count,e.consented_count from private.customer_segment_estimates e
   where e.rule_hash=segment.rule_hash and e.evaluated_at>=calendar.month_start at time zone 'Asia/Seoul'
    and e.evaluated_at<(calendar.month_start+interval '1 month') at time zone 'Asia/Seoul' and e.evaluated_at<=at_value
   order by e.evaluated_at desc,e.id desc limit 1
  ) observation on true
 ) select jsonb_agg(jsonb_build_object('month',to_char(month_start,'YYYY-MM'),'evaluatedAt',evaluated_at,
  'matchedCount',matched_count,'consentedCount',consented_count) order by month_start) into months from observations;
 select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'label',label) order by kind,label,id),'[]'::jsonb) into choices from (
  select 'good'::text kind,g.id,g.name label from public.goods g where segment.rule->'goodIds' ? g.id
  union all select 'category',c.id::text,c.name from public.catalog_categories c where c.id=(segment.rule->>'categoryId')::uuid
  union all select 'ip',ip.id,ip.title from public.ips ip where ip.id=segment.rule->>'ipId'
  union all select 'coupon',c.code,c.name from public.coupons c where c.code=segment.rule->>'couponCode'
 ) selected;
 return jsonb_build_object('segment',private.customer_segment_document(p_id,actor),'history',months,'selectedOptions',choices);
end $$

create function public.admin_customer_segment_options(p_kind text,p_query text default '',p_page integer default 1)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare q text:=btrim(coalesce(p_query,'')); result jsonb;
begin
 if not public.has_operator_capability('marketing.manage') then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_kind is null or p_kind not in ('good','category','ip','coupon') or length(q)>100 or p_page is null or p_page not between 1 and 1000000 then
  raise invalid_parameter_value using message='invalid_customer_segment_options';end if;
 with candidates as (
  select 'good'::text kind,g.id,g.name label,g.code extra from public.goods g where p_kind='good' and g.archived_at is null and g.sale_restriction='none'
  union all select 'category',c.id::text,c.name,c.code from public.catalog_categories c where p_kind='category' and c.archived_at is null
  union all select 'ip',ip.id,ip.title,'' from public.ips ip where p_kind='ip' and ip.archived_at is null
  union all select 'coupon',c.code,c.name,c.code from public.coupons c where p_kind='coupon' and c.status<>'archived'
 ), matched as materialized(select * from candidates where q='' or position(lower(q) in lower(id||' '||label||' '||extra))>0),
 page_rows as (select * from matched order by label,id limit 20 offset (p_page-1)*20)
 select jsonb_build_object('total',(select count(*) from matched),'page',p_page,'pageSize',20,
  'rows',coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'id',id,'label',label,'extra',extra) order by label,id) from page_rows),'[]'::jsonb)) into result;
 return result;
end $$

