 if not found then raise no_data_found using message='store_presentation_missing';end if;
 if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='store_presentation_conflict';end if;
 update private.store_presentation_settings set values=p_values,revision=revision+1,updated_at=clock_timestamp() where section=p_section;
 receipt:=jsonb_build_object('section',p_section,'values',p_values,'revision',previous.revision+1);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.store_presentation.updated','store_presentation:'||p_section,
  jsonb_build_object('request',request,'result',receipt,'before',previous.values));
 return receipt;
end $$

-- Explicit chips only: an option name never becomes a guessed CSS color.
create function private.goods_listing_colors_valid(p_colors jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
declare chip jsonb; labels text[]:='{}';
begin
 if jsonb_typeof(p_colors) is distinct from 'array' then return false;end if;
 if jsonb_array_length(p_colors)>20 then return false;end if;
 for chip in select value from jsonb_array_elements(p_colors) loop
  if jsonb_typeof(chip) is distinct from 'object' then return false;end if;
  if (select count(*) from jsonb_object_keys(chip))<>2 or not chip ?& array['label','hex']
   or jsonb_typeof(chip->'label') is distinct from 'string' or jsonb_typeof(chip->'hex') is distinct from 'string'
   or char_length(chip->>'label') not between 1 and 30 or chip->>'label' ~ '[[:cntrl:]]'
   or chip->>'label'<>btrim(chip->>'label',E' \t\n\r\f\v'||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
   or chip->>'hex' !~ '^#[0-9a-f]{6}$' or chip->>'label'=any(labels) then return false;end if;
  labels:=array_append(labels,chip->>'label');
 end loop;return true;
end $$

create function public.admin_get_goods_listing_colors(p_good_id text)
returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if not private.has_operator_capability(auth.uid(),'catalog.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 if not exists(select 1 from public.goods where id=p_good_id) then raise no_data_found using message='good_missing';end if;
 return coalesce((select jsonb_build_object('colors',colors,'revision',revision) from private.goods_listing_colors where good_id=p_good_id),'{"colors":[],"revision":0}');
end $$

create function public.admin_save_goods_listing_colors(p_good_id text,p_colors jsonb,p_expected_revision bigint,p_operation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid(); previous private.goods_listing_colors%rowtype; request jsonb; receipt jsonb;
begin
 perform private.require_actor_operator_capability(actor,'catalog.manage',false);
 if p_operation_id is null or p_good_id is null or p_expected_revision is null or p_expected_revision<0 or private.goods_listing_colors_valid(p_colors) is distinct from true then
  raise invalid_parameter_value using message='invalid_goods_listing_colors';end if;
 request:=jsonb_build_object('goodId',p_good_id,'colors',p_colors,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('goods-listing-colors:operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.goods_listing_colors.updated',request);
 if receipt is not null then return receipt;end if;
 -- Serialize with rename/archive and make the first empty row participate in CAS.
 perform 1 from public.goods where id=p_good_id and archived_at is null for update;
 if not found then raise no_data_found using message='good_missing';end if;
 insert into private.goods_listing_colors(good_id) values(p_good_id) on conflict do nothing;
 select * into previous from private.goods_listing_colors where good_id=p_good_id for update;
 if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='goods_listing_colors_conflict';end if;
 update private.goods_listing_colors set colors=p_colors,revision=revision+1,updated_at=clock_timestamp() where good_id=p_good_id;
 receipt:=jsonb_build_object('colors',p_colors,'revision',previous.revision+1);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.goods_listing_colors.updated','goods:'||p_good_id,
  jsonb_build_object('request',request,'result',receipt,'before',previous.colors));
 return receipt;
end $$

-- Customer-agreed whole-order cancellation intake before confirmation/export.
-- This creates a request only; provider cancellation and stock/benefit restoration
-- remain owned by the existing approval, reconciliation and finalizer paths.
create function private.seller_cancel_intake_block(p_order_id uuid) returns text
language plpgsql stable security invoker set search_path='' as $$
declare target public.orders;
begin
 select * into target from public.orders where id=p_order_id;
 if not found then return 'order_not_found';end if;
 if target.status='canceled' then return 'already_canceled';end if;
 if not private.order_cancel_eligible(p_order_id) then return 'not_cancelable';end if;
 if exists(select 1 from public.order_cancellation_requests where order_id=p_order_id and status in('requested','processing','needs_review')) then return 'already_requested';end if;
 if exists(select 1 from public.order_cancellation_claims where order_id=p_order_id) then return 'reconciliation_in_progress';end if;
 return null;
end $$

CREATE OR REPLACE FUNCTION public.admin_seller_claim_intake_context(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.orders; result jsonb; observed_at timestamptz := clock_timestamp();
begin
  if not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='operator_capability_required'; end if;

  perform (select auth.uid());
  select * into target from public.orders where id = p_order_id;
  if not found then return null; end if;
  select jsonb_build_object(
    'orderId', target.id, 'orderStatus', target.status, 'orderTotal', target.total,
    'buyerName', profile.nickname, 'createdAt', target.created_at, 'deliveredAt', target.delivered_at,
    'address', target.address, 'observedAt', observed_at,
    'cancelBlockedReason',private.seller_cancel_intake_block(target.id),
    'blockedReasons', jsonb_build_object(
      'change_of_mind', private.seller_claim_intake_block(target.id, 'change_of_mind', observed_at),
      'defect', private.seller_claim_intake_block(target.id, 'defect', observed_at)),
    'activeClaim', (select jsonb_build_object('id', c.id, 'claimType', c.claim_type, 'stage', c.stage)
      from public.order_cancellation_requests c where c.order_id = target.id and c.status in ('requested', 'processing', 'needs_review') order by c.requested_at desc limit 1),
    'collections', private.seller_claim_collection_targets(target.id),
    'carriers', coalesce((select jsonb_agg(jsonb_build_object('code', c.code, 'label', c.label, 'active', c.is_active, 'trackingUrlTemplate', c.tracking_url_template) order by c.sort_order, c.code)
      from public.shipping_carriers c where c.is_active), '[]'),
    'inquiries', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'reference', i.reference, 'title', i.title, 'createdAt', i.created_at) order by i.created_at desc)
      from (select * from public.inquiries where user_id = target.user_id and order_id = target.id order by created_at desc, id limit 50) i), '[]')
  ) into result from public.profiles profile where profile.id = target.user_id;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_submit_seller_claim_intake(p_request_id uuid, p_payload jsonb, p_refund_account jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid()); target public.orders;
  previous private.seller_order_claim_intakes; saved_payload jsonb; collections jsonb; targets jsonb;
  block text; submitted_at timestamptz; requested_at timestamptz; target_id uuid;
begin
  perform private.require_operator_capability('sales.manage',false);

  if p_request_id is null then raise invalid_parameter_value using message = 'invalid_seller_claim_request'; end if;
  perform private.validate_seller_claim_intake(p_payload, p_refund_account);
  target_id := (p_payload->>'orderId')::uuid;
  requested_at := (p_payload->>'customerRequestedAt')::timestamptz;
  -- Raw bank details have exactly one storage destination and its existing purge
  -- lifecycle. The idempotency receipt stores only their SHA-256 fingerprint.
  saved_payload := p_payload || jsonb_build_object('refundAccountDigest',
    case when p_refund_account is null or p_refund_account = 'null'::jsonb then null
      else encode(extensions.digest(p_refund_account::text, 'sha256'), 'hex') end);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('seller_claim_intake:' || p_request_id, 0));
  select * into previous from private.seller_order_claim_intakes where claim_id = p_request_id;
  if found then
    if previous.actor_id <> actor or previous.payload <> saved_payload then
      raise exception using errcode = 'PT409', message = 'seller_claim_request_conflict';
    end if;
    return private.seller_claim_intake_json(p_request_id);
  end if;
  if exists(select 1 from public.order_cancellation_requests where id = p_request_id) then
    raise exception using errcode = 'PT409', message = 'seller_claim_request_conflict';
  end if;

  -- Same parent-first order as customer intake and dispatch. No financial
  -- operation is performed after these locks; they only stabilize eligibility.
  select * into target from public.orders where id = target_id for update;
  if not found then raise no_data_found using message = 'order_not_found'; end if;
  perform s.id from public.order_shipments s where s.order_id = target_id order by s.id for update;
  perform attempt.id from public.payment_attempts attempt where attempt.purpose = 'order' and attempt.ref_id = target_id order by attempt.id for update;
  submitted_at := clock_timestamp();
  block := case when p_payload->>'claimType'='cancel' then private.seller_cancel_intake_block(target_id)
    else private.seller_claim_intake_block(target_id, p_payload->>'reasonType', submitted_at) end;
  if block is not null then raise check_violation using message = block; end if;
  if requested_at < target.created_at or requested_at > submitted_at then
    raise invalid_parameter_value using message = 'invalid_seller_claim_customer_time';
  end if;
  if p_payload->>'source' = 'inquiry' then
    perform 1 from public.inquiries where id = (p_payload->>'inquiryId')::uuid and user_id = target.user_id and order_id = target_id for share;
    if not found then raise check_violation using message = 'seller_claim_inquiry_mismatch'; end if;
  end if;
  if p_payload->>'claimType'='cancel' then
    collections:='[]'::jsonb;
  else
  targets := private.seller_claim_collection_targets(target_id);
  if jsonb_array_length(targets) <> jsonb_array_length(p_payload->'collections')
    or (select count(distinct (x->>'shipmentId')::uuid) from jsonb_array_elements(p_payload->'collections') x) <> jsonb_array_length(targets)
    or exists(select 1 from jsonb_array_elements(p_payload->'collections') x where not exists(select 1 from jsonb_array_elements(targets) t where (t->>'shipmentId')::uuid = (x->>'shipmentId')::uuid))
  then raise check_violation using message = 'seller_claim_collections_changed'; end if;
  if exists(select 1 from jsonb_array_elements(p_payload->'collections') x where x->>'carrier' is not null
    and not exists(select 1 from public.shipping_carriers carrier where carrier.code = x->>'carrier' and carrier.is_active))
  then raise check_violation using message = 'unknown_shipping_carrier'; end if;
  select jsonb_agg(x || jsonb_build_object('originId', t->>'originId', 'originName', t->>'originName', 'items', t->'items') order by t->>'originId', t->>'shipmentId')
    into collections from jsonb_array_elements(p_payload->'collections') x join jsonb_array_elements(targets) t on (x->>'shipmentId')::uuid = (t->>'shipmentId')::uuid;

  end if;

  insert into public.order_cancellation_requests(id, order_id, requested_by, claim_type, reason_type, reason, stage, requested_at)
    values(p_request_id, target_id, target.user_id, p_payload->>'claimType', p_payload->>'reasonType', p_payload->>'reason', 'requested', submitted_at);
  insert into private.seller_order_claim_intakes(claim_id, actor_id, payload, collection_snapshot, created_at)
    values(p_request_id, actor, saved_payload, collections, submitted_at);
  -- Preserve the submitted payload for exact idempotency while the immutable
  -- target labels/items are stored separately inside the same private receipt.
  -- They are returned by joining the original input with its intake snapshot.
  if p_refund_account is not null and p_refund_account <> 'null'::jsonb then
    insert into private.claim_refund_accounts(claim_id, bank_name, account_number, account_holder, masked_account, masked_holder)
      values(p_request_id, p_refund_account->>'bankName', p_refund_account->>'accountNumber', p_refund_account->>'accountHolder',
        (p_refund_account->>'bankName') || ' ' || public.mask_refund_account_number(p_refund_account->>'accountNumber'),
        public.mask_refund_account_holder(p_refund_account->>'accountHolder'));
  end if;
  insert into public.audit_log(actor_id, action, target, diff) values(actor, 'admin.order.claim_intake_created', 'order:' || target_id::text,
    jsonb_build_object('claimId', p_request_id, 'claimType', p_payload->>'claimType', 'to', 'requested', 'source', p_payload->>'source',
      'inquiryId', p_payload->>'inquiryId', 'customerRequestedAt', requested_at, 'collectionCount', jsonb_array_length(collections)));
  perform private.notify_order_claim(p_request_id, 'seller_requested', case when p_payload->>'claimType'='cancel' then '취소 요청이 접수됐어요' else '반품·교환 요청이 접수됐어요' end,
    '고객님과 확인한 내용을 바탕으로 담당자가 요청을 접수했습니다. 승인과 이후 처리는 별도로 진행됩니다.');
  return private.seller_claim_intake_json(p_request_id);
end $function$

create function private.validate_goods_relation_composition(p_values jsonb) returns void
language plpgsql stable set search_path='' as $$
declare relation_kind text; visual jsonb; ids text[]; point jsonb; seen text[]:='{}'; starts_value timestamptz;ends_value timestamptz;
begin
 if jsonb_typeof(p_values) is distinct from 'object'
  or not(p_values ?& array['kind','title','representativeGoodId','enabled','startsAt','endsAt','goodIds','visual'])
  or exists(select 1 from jsonb_object_keys(p_values) key where key<>all(array['kind','title','representativeGoodId','enabled','startsAt','endsAt','goodIds','visual']))
  or jsonb_typeof(p_values->'kind') is distinct from 'string' or p_values->>'kind' not in ('together','similar','codi')
  or jsonb_typeof(p_values->'title') is distinct from 'string' or char_length(btrim(p_values->>'title')) not between 1 and 15
  or jsonb_typeof(p_values->'representativeGoodId') is distinct from 'string' or jsonb_typeof(p_values->'enabled') is distinct from 'boolean'
  or jsonb_typeof(p_values->'goodIds') is distinct from 'array' or jsonb_typeof(p_values->'startsAt') not in ('null','string')
  or jsonb_typeof(p_values->'endsAt') not in ('null','string') or jsonb_typeof(p_values->'visual') not in ('null','object')
 then raise invalid_parameter_value using message='invalid_goods_relation';end if;
 relation_kind:=p_values->>'kind';visual:=nullif(p_values->'visual','null'::jsonb);
 if jsonb_array_length(p_values->'goodIds') not between 2 and (case when visual is not null or relation_kind='codi' then 5 when relation_kind='together' then 6 else 10 end)
  or exists(select 1 from jsonb_array_elements(p_values->'goodIds') item where jsonb_typeof(item)<>'string' or item#>>'{}' !~ '^[a-z0-9][a-z0-9-]{0,119}$')
 then raise invalid_parameter_value using message='invalid_goods_relation_goods';end if;
 select array_agg(value order by position) into ids from jsonb_array_elements_text(p_values->'goodIds') with ordinality item(value,position);
 if cardinality(ids)<>(select count(distinct id) from unnest(ids) id) or not(p_values->>'representativeGoodId'=any(ids)) then raise invalid_parameter_value using message='invalid_goods_relation_goods';end if;
 begin starts_value:=(p_values->>'startsAt')::timestamptz;ends_value:=(p_values->>'endsAt')::timestamptz;
 exception when invalid_datetime_format or datetime_field_overflow then raise invalid_parameter_value using message='invalid_goods_relation_period';end;
 if starts_value is not null and not isfinite(starts_value) or ends_value is not null and not isfinite(ends_value)
  or starts_value is not null and ends_value is not null and starts_value>=ends_value then raise invalid_parameter_value using message='invalid_goods_relation_period';end if;
 if relation_kind='codi' and visual is null or relation_kind='similar' and visual is not null then raise invalid_parameter_value using message='invalid_goods_relation_visual';end if;
 if visual is null then return;end if;
 if not(visual ?& array['imagePath','alt','description','hotspots'])
  or exists(select 1 from jsonb_object_keys(visual) key where key<>all(array['imagePath','alt','description','hotspots']))
  or jsonb_typeof(visual->'imagePath') is distinct from 'string'
  or visual->>'imagePath' !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  or jsonb_typeof(visual->'alt') is distinct from 'string' or char_length(btrim(visual->>'alt')) not between 1 and 120
  or jsonb_typeof(visual->'description') is distinct from 'string' or char_length(btrim(visual->>'description'))>90
  or jsonb_typeof(visual->'hotspots') is distinct from 'array' or jsonb_array_length(visual->'hotspots')>5
 then raise invalid_parameter_value using message='invalid_goods_relation_visual';end if;
 for point in select value from jsonb_array_elements(visual->'hotspots') loop
  if jsonb_typeof(point) is distinct from 'object' or not(point ?& array['goodId','x','y'])
   or exists(select 1 from jsonb_object_keys(point) key where key<>all(array['goodId','x','y']))
   or jsonb_typeof(point->'goodId') is distinct from 'string' or not(point->>'goodId'=any(ids)) or point->>'goodId'=any(seen)
   or jsonb_typeof(point->'x') is distinct from 'number' or point->>'x' !~ '^[0-9]{1,5}$'
   or jsonb_typeof(point->'y') is distinct from 'number' or point->>'y' !~ '^[0-9]{1,5}$'
  then raise invalid_parameter_value using message='invalid_goods_relation_visual';end if;
  if (point->>'x')::integer>10000 or (point->>'y')::integer>10000 then raise invalid_parameter_value using message='invalid_goods_relation_visual';end if;
  seen:=array_append(seen,point->>'goodId');
 end loop;
end $$

create function public.admin_save_goods_relation_composition(p_id uuid,p_expected_revision integer,p_operation_id uuid,p_values jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid();prior public.goods_relations;saved public.goods_relations;existing public.audit_log;
 request_value jsonb;result_value jsonb;before_document jsonb;visual jsonb;ids text[];bad_id text;image_value text;
begin
 perform private.require_operator_capability('catalog.manage',false);
 if p_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 then raise invalid_parameter_value using message='invalid_goods_relation';end if;
 perform private.validate_goods_relation_composition(p_values);
 request_value:=jsonb_build_object('expectedRevision',p_expected_revision,'values',p_values);
 perform pg_advisory_xact_lock(hashtextextended('goods-relation-operation:'||p_operation_id::text,0));
 select * into existing from public.audit_log where id=p_operation_id;
 if found then
  if existing.actor_id=actor and existing.action='admin.goods.relation.saved' and existing.target='goods_relation:'||p_id::text and existing.diff->'request'=request_value then return existing.diff->'result';end if;
  raise sqlstate 'PT409' using message='goods_relation_operation_conflict';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-relation:'||p_id::text,0));
 select * into prior from public.goods_relations where id=p_id for update;
 if found then
  if prior.revision<>p_expected_revision then raise sqlstate 'PT409' using message='goods_relation_changed';end if;
  before_document:=private.goods_relation_document(p_id);
 elsif p_expected_revision<>0 then raise sqlstate 'PT409' using message='goods_relation_changed';end if;
 select array_agg(value order by position) into ids from jsonb_array_elements_text(p_values->'goodIds') with ordinality item(value,position);
 perform 1 from public.goods where id=any(ids) order by id for share;
 -- Retain the existing relation contract: unavailable records can remain in a
 -- composition, while both public readers independently apply visibility gates.
 select requested.id into bad_id from unnest(ids) requested(id) left join public.goods g on g.id=requested.id where g.id is null limit 1;
 if bad_id is not null then raise invalid_parameter_value using message='invalid_goods_relation_goods';end if;
 visual:=nullif(p_values->'visual','null'::jsonb);image_value:=visual->>'imagePath';
 if image_value is not null and image_value is distinct from prior.image_path then
  update public.admin_artwork_upload_claims claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
  where claim.actor_id=actor and claim.kind='curation' and claim.path=substr(image_value,length('public-media/')+1)
   and claim.status='verified' and claim.verified_at is not null and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
  if not found then raise check_violation using message='unverified_artwork';end if;
 end if;
 if prior.id is null then
  insert into public.goods_relations(id,kind,title,representative_good_id,enabled,starts_at,ends_at,image_path,image_alt,description,created_by,updated_by)
  values(p_id,p_values->>'kind',btrim(p_values->>'title'),p_values->>'representativeGoodId',(p_values->>'enabled')::boolean,
   (p_values->>'startsAt')::timestamptz,(p_values->>'endsAt')::timestamptz,image_value,coalesce(btrim(visual->>'alt'),''),coalesce(btrim(visual->>'description'),''),actor,actor) returning * into saved;
 else
  update public.goods_relations set kind=p_values->>'kind',title=btrim(p_values->>'title'),representative_good_id=p_values->>'representativeGoodId',enabled=(p_values->>'enabled')::boolean,
   starts_at=(p_values->>'startsAt')::timestamptz,ends_at=(p_values->>'endsAt')::timestamptz,image_path=image_value,image_alt=coalesce(btrim(visual->>'alt'),''),description=coalesce(btrim(visual->>'description'),''),
   revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id=p_id returning * into saved;
 end if;
 -- Member replacement cascades old points; recreated points must target the new members.
 delete from public.goods_relation_members where relation_id=p_id;
 insert into public.goods_relation_members(relation_id,good_id,position) select p_id,id,position::integer from unnest(ids) with ordinality item(id,position);
 if visual is not null then
  insert into public.goods_relation_hotspots(relation_id,good_id,x,y) select p_id,item->>'goodId',(item->>'x')::integer,(item->>'y')::integer from jsonb_array_elements(visual->'hotspots')item;
 end if;
 result_value:=jsonb_build_object('id',p_id,'revision',saved.revision);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.goods.relation.saved','goods_relation:'||p_id,
  jsonb_build_object('request',request_value,'before',before_document,'after',private.goods_relation_document(p_id),'result',result_value));
 return result_value;
end $$

-- Preserve the list API for existing callers; it cannot silently erase a newer image map.
create or replace function public.admin_save_goods_relation(p_id uuid,p_expected_revision integer,p_values jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
 perform private.require_operator_capability('catalog.manage',false);
 if jsonb_typeof(p_values) is distinct from 'object' or p_values ? 'visual' or p_values->>'kind' not in ('together','similar')
  or exists(select 1 from public.goods_relations where id=p_id and image_path is not null) then raise invalid_parameter_value using message='goods_relation_visual_required';end if;
 return public.admin_save_goods_relation_composition(p_id,p_expected_revision,gen_random_uuid(),p_values||'{"visual":null}'::jsonb);
end $$

create or replace function public.admin_list_goods_relations(p_query text default '',p_kind text default 'all',p_state text default 'all',p_page integer default 1,p_page_size integer default 20)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 if not public.has_operator_capability('catalog.read') then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_query is null or char_length(p_query)>100 or p_kind is null or p_kind not in ('all','together','similar','codi')
  or p_state is null or p_state not in ('all','active','scheduled','stopped','ended') or p_page is null or p_page not between 1 and 100000 or p_page_size is null or p_page_size not in (20,50,100)
 then raise invalid_parameter_value using message='invalid_goods_relation_filter';end if;
 with matched as materialized (
  select r.*,case when not r.enabled then 'stopped' when r.starts_at>statement_timestamp() then 'scheduled' when r.ends_at<=statement_timestamp() then 'ended' else 'active' end state
  from public.goods_relations r where (p_kind='all' or r.kind=p_kind) and (btrim(p_query)='' or strpos(lower(r.title),lower(btrim(p_query)))>0 or strpos(r.id::text,btrim(p_query))>0
   or exists(select 1 from public.goods_relation_members m join public.goods g on g.id=m.good_id where m.relation_id=r.id
    and (strpos(lower(g.name),lower(btrim(p_query)))>0 or strpos(lower(g.code),lower(btrim(p_query)))>0 or strpos(g.id,btrim(p_query))>0)))
 ),filtered as materialized(select * from matched where p_state='all' or state=p_state),page_rows as(select id,updated_at from filtered order by updated_at desc,id limit p_page_size offset(p_page-1)*p_page_size)
 select jsonb_build_object('total',(select count(*) from filtered),'page',p_page,'pageSize',p_page_size,'rows',coalesce((select jsonb_agg(private.goods_relation_document(id) order by updated_at desc,id) from page_rows),'[]'::jsonb)) into result;
 return result;
end $$

