-- An unresolved submission is identified by its actor and complete original
-- payload, including the existing private refund-account fingerprint. A null
-- result says only that no committed receipt exists at this read's lock boundary.
create function public.admin_read_seller_claim_intake(p_request_id uuid,p_payload jsonb,p_refund_account jsonb default null)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid; previous private.seller_order_claim_intakes; expected_payload jsonb;
begin
 actor:=private.require_operator_capability('sales.manage',false);
 if p_request_id is null then raise invalid_parameter_value using message='invalid_seller_claim_request';end if;
 perform private.validate_seller_claim_intake(p_payload,p_refund_account);
 expected_payload:=p_payload||jsonb_build_object('refundAccountDigest',
  case when p_refund_account is null or p_refund_account='null'::jsonb then null
   else encode(extensions.digest(p_refund_account::text,'sha256'),'hex') end);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('seller_claim_intake:'||p_request_id,0));
 select * into previous from private.seller_order_claim_intakes where claim_id=p_request_id;
 if not found then
  if exists(select 1 from public.order_cancellation_requests where id=p_request_id) then
   raise exception using errcode='PT409',message='seller_claim_request_conflict';
  end if;
  return null;
 end if;
 if previous.actor_id<>actor or previous.payload<>expected_payload then
  raise exception using errcode='PT409',message='seller_claim_request_conflict';
 end if;
 return private.seller_claim_intake_json(p_request_id);
end $$

-- Independent PDP experiences. The existing banner/modules contract stays intact.
create function private.product_detail_experience_values_valid(p_section text,p_values jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
declare field text;
begin
 if jsonb_typeof(p_values) is distinct from 'object' then return false;end if;
 if p_section='messages' then
  if (select count(*) from jsonb_object_keys(p_values))<>7
   or not p_values ?& array['buyers','minBuyers','twoYears','repeatBuyers','minRepeatBuyers','bestSeller','newProduct'] then return false;end if;
  foreach field in array array['buyers','twoYears','repeatBuyers','bestSeller','newProduct'] loop
   if jsonb_typeof(p_values->field) is distinct from 'boolean' then return false;end if;
  end loop;
  foreach field in array array['minBuyers','minRepeatBuyers'] loop
   if jsonb_typeof(p_values->field) is distinct from 'number' or p_values->>field !~ '^[0-9]+$'
    or (p_values->>field)::numeric not between 10 and 1000 then return false;end if;
  end loop;
  return true;
 elsif p_section='discovery' then
  return (select count(*)=2 from jsonb_object_keys(p_values)) and p_values ?& array['interests','shippingSavings']
   and jsonb_typeof(p_values->'interests')='boolean' and jsonb_typeof(p_values->'shippingSavings')='boolean';
 end if;
 return false;
exception when others then return false;
end $$

create function public.admin_get_product_detail_experiences() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 perform private.require_actor_operator_capability(auth.uid(),'store.manage',false);
 select jsonb_build_object('values',jsonb_object_agg(section,values),'revisions',jsonb_object_agg(section,revision)) into result
 from private.product_detail_experience_settings;
 return result;
end $$

create function public.admin_save_product_detail_experiences(p_section text,p_values jsonb,p_expected_revision bigint,p_operation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid(); previous private.product_detail_experience_settings%rowtype; request jsonb; receipt jsonb;
begin
 perform private.require_actor_operator_capability(actor,'store.manage',false);
 if p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or private.product_detail_experience_values_valid(p_section,p_values) is distinct from true then
  raise invalid_parameter_value using message='invalid_product_detail_experience';end if;
 request:=jsonb_build_object('section',p_section,'values',p_values,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('product-detail-experience:operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.product_detail_experience.updated',request);
 if receipt is not null then return receipt;end if;
 select * into previous from private.product_detail_experience_settings where section=p_section for update;
 if not found then raise no_data_found using message='product_detail_experience_missing';end if;
 if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='product_detail_experience_conflict';end if;
 update private.product_detail_experience_settings set values=p_values,revision=revision+1,updated_at=clock_timestamp() where section=p_section;
 receipt:=jsonb_build_object('section',p_section,'values',p_values,'revision',previous.revision+1);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.product_detail_experience.updated','product_detail_experience:'||p_section,
  jsonb_build_object('request',request,'result',receipt,'before',previous.values));
 return receipt;
end $$

create function public.get_product_detail_experience(p_good_id text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare current_good public.goods%rowtype; config jsonb; messages jsonb:='[]'; window_row record; customer_count bigint; sale_rank bigint;
 at_time timestamptz:=statement_timestamp(); today timestamptz:=date_trunc('day',statement_timestamp() at time zone 'Asia/Seoul') at time zone 'Asia/Seoul';
 next_change timestamptz;
begin
 select g.* into current_good from public.goods g join public.ips ip on ip.id=g.ip_id
 where g.id=p_good_id and g.published_at is not null and g.archived_at is null and g.sale_restriction='none'
  and ip.published_at is not null and ip.archived_at is null;
 if not found then return null;end if;
 select values into config from private.product_detail_experience_settings where section='messages';
 if (config->>'buyers')::boolean then
  for window_row in select * from (values
   (1,'today',today),(2,'week',today-interval '6 days'),(3,'sixMonths',today-interval '6 months'),
   (4,'year',today-interval '1 year'),(5,'twoYears',today-interval '2 years')
  ) periods(position,key,starts_at) where key<>'twoYears' or (config->>'twoYears')::boolean order by position loop
   select count(distinct o.user_id) into customer_count from private.product_detail_paid_orders(window_row.starts_at,at_time) paid
    join public.orders o on o.id=paid.id where exists(select 1 from public.order_items i where i.order_id=o.id and i.good_id=p_good_id);
   if customer_count >= (config->>'minBuyers')::integer then
    messages:=messages||jsonb_build_array(jsonb_build_object('kind','buyers','window',window_row.key,'count',customer_count));exit;
   end if;
  end loop;
 end if;
 if (config->>'repeatBuyers')::boolean then
  for window_row in select * from (values
   (1,'threeMonths',today-interval '3 months'),(2,'sixMonths',today-interval '6 months'),(3,'year',today-interval '1 year')
  ) periods(position,key,starts_at) order by position loop
   select count(*) into customer_count from (
    select o.user_id from private.product_detail_paid_orders(window_row.starts_at,at_time) paid
     join public.orders o on o.id=paid.id where exists(select 1 from public.order_items i where i.order_id=o.id and i.good_id=p_good_id)
     group by o.user_id having count(distinct o.id)>=2
   ) repeated;
   if customer_count >= (config->>'minRepeatBuyers')::integer then
    messages:=messages||jsonb_build_array(jsonb_build_object('kind','repeatBuyers','window',window_row.key,'count',customer_count));exit;
   end if;
  end loop;
 end if;
 if (config->>'bestSeller')::boolean then
  with sales as (
   select item.good_id,sum(item.qty::bigint) quantity from private.product_detail_paid_orders(today-interval '3 days',today) paid
    join public.order_items item on item.order_id=paid.id join public.goods g on g.id=item.good_id join public.ips ip on ip.id=g.ip_id
   where g.published_at is not null and g.archived_at is null and g.sale_restriction='none'
    and ip.published_at is not null and ip.archived_at is null group by item.good_id
  ), ranked as (select good_id,row_number() over(order by quantity desc,good_id) rank from sales where quantity>0)
  select rank into sale_rank from ranked where good_id=p_good_id and rank<=10;
  if sale_rank is not null then messages:=messages||jsonb_build_array(jsonb_build_object('kind','bestSeller','rank',sale_rank));end if;
 end if;
 if (config->>'newProduct')::boolean and current_good.created_at<=at_time and current_good.created_at>at_time-interval '7 days' then
  messages:=messages||jsonb_build_array(jsonb_build_object('kind','newProduct'));
  next_change:=current_good.created_at+interval '7 days';
 end if;
 if (config->>'buyers')::boolean or (config->>'repeatBuyers')::boolean or (config->>'bestSeller')::boolean then next_change:=least(next_change,today+interval '1 day');end if;
 return jsonb_build_object('messages',messages,'discovery',public.get_product_detail_experience_config(),'nextChangeAt',next_change);
end $$

-- No requested customer id: the authenticated identity is the only ownership key.
create function public.get_my_product_detail_interests() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=auth.uid(); result jsonb;
begin
 if actor is null or not (public.get_product_detail_experience_config()->>'interests')::boolean then
  return jsonb_build_object('ownerId',actor,'cart','[]'::jsonb,'wishlist','[]'::jsonb,'repurchase','[]'::jsonb);end if;
 with eligible as materialized (
  select g.id from public.goods g join public.ips ip on ip.id=g.ip_id where g.published_at is not null and g.archived_at is null
   and g.sale_restriction='none' and ip.published_at is not null and ip.archived_at is null
 ), cart as (
  select c.good_id id,max(c.created_at) moment from public.cart_items c join eligible g on g.id=c.good_id where c.user_id=actor
   group by c.good_id order by moment desc,c.good_id limit 30
 ), wishes as (
  select w.good_id id,w.created_at moment from public.wishlists w join eligible g on g.id=w.good_id where w.user_id=actor
   order by moment desc,w.good_id limit 30
 ), repeated as (
  select i.good_id id,max(paid.approved_at) moment from private.product_detail_paid_orders(statement_timestamp()-interval '2 years',statement_timestamp()) paid
   join public.orders o on o.id=paid.id and o.user_id=actor join public.order_items i on i.order_id=o.id join eligible g on g.id=i.good_id
   group by i.good_id having count(distinct o.id)>=2 order by moment desc,i.good_id limit 30
 ) select jsonb_build_object('ownerId',actor,
  'cart',coalesce((select jsonb_agg(id order by moment desc,id) from cart),'[]'::jsonb),
  'wishlist',coalesce((select jsonb_agg(id order by moment desc,id) from wishes),'[]'::jsonb),
  'repurchase',coalesce((select jsonb_agg(id order by moment desc,id) from repeated),'[]'::jsonb)) into result;
 return result;
end $$

-- Advisory shipping quotes reuse checkout calculations; no inventory/cart writes.
create function public.get_product_shipping_savings(p_good_id text,p_variant_id uuid,p_qty integer) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare current_good public.goods%rowtype; candidate record; base_items jsonb; other_items jsonb; base_quote jsonb; other_quote jsonb; combined_quote jsonb;
 rows jsonb:='[]'; separate_fee bigint; combined_fee bigint; result jsonb; next_change timestamptz;
begin
 if p_good_id is null or p_variant_id is null or p_qty is null or p_qty not between 1 and 1000 then raise invalid_parameter_value using message='invalid_shipping_savings_selection';end if;
 if not (public.get_product_detail_experience_config()->>'shippingSavings')::boolean then return jsonb_build_object('items','[]'::jsonb,'nextChangeAt',null);end if;
 select g.* into current_good from public.goods g join public.ips ip on ip.id=g.ip_id
 where g.id=p_good_id and g.published_at is not null and g.archived_at is null and g.sale_restriction='none'
  and ip.published_at is not null and ip.archived_at is null;
 if not found then return null;end if;
 base_items:=jsonb_build_array(jsonb_build_object('goodId',p_good_id,'variantId',p_variant_id,'qty',p_qty));
 base_quote:=public.quote_goods_sales(base_items);
 if exists(select 1 from jsonb_array_elements(base_quote->'lines') l where not (l->>'available')::boolean)
  or exists(select 1 from jsonb_array_elements(base_quote->'goods') g where g->'reason'<>'null'::jsonb) then
  return jsonb_build_object('items','[]'::jsonb,'selectionUnavailable',true,'nextChangeAt',base_quote->'nextChangeAt');end if;
 next_change:=(base_quote->>'nextChangeAt')::timestamptz;
 for candidate in
  select g.id,chosen.id variant_id,chosen.name variant_name,case when g.order_quantity_limit_enabled then g.min_order_qty else 1 end qty
  from public.goods g join public.ips ip on ip.id=g.ip_id
  join lateral (
   select v.id,v.name from public.goods_variants v cross join lateral private.resolve_goods_variant_supply(v.id,statement_timestamp()) supply
    cross join lateral private.resolve_goods_variant_price(v.id,statement_timestamp()) pricing
   where v.good_id=g.id and v.archived_at is null and (supply.available_qty is null or supply.available_qty>=case when g.order_quantity_limit_enabled then g.min_order_qty else 1 end)
   order by v.is_default desc,pricing.effective_price,v.id limit 1
  ) chosen on true
  where g.id<>p_good_id and g.origin_id=current_good.origin_id and g.published_at is not null and g.archived_at is null and g.sale_restriction='none'
   and ip.published_at is not null and ip.archived_at is null and (not g.order_quantity_limit_enabled or g.min_order_qty between 1 and 1000)
  order by md5(g.id||(statement_timestamp() at time zone 'Asia/Seoul')::date::text),g.id limit 50
 loop
  other_items:=jsonb_build_array(jsonb_build_object('goodId',candidate.id,'variantId',candidate.variant_id,'qty',candidate.qty));
  begin
   other_quote:=public.quote_goods_sales(other_items);combined_quote:=public.quote_goods_sales(base_items||other_items);
  exception when check_violation or no_data_found then continue;end;
  if exists(select 1 from jsonb_array_elements(combined_quote->'lines') l where not (l->>'available')::boolean)
   or exists(select 1 from jsonb_array_elements(combined_quote->'goods') g where g->'reason'<>'null'::jsonb) then continue;end if;
  separate_fee:=(base_quote#>>'{shipping,totalFee}')::bigint+(other_quote#>>'{shipping,totalFee}')::bigint;
  combined_fee:=(combined_quote#>>'{shipping,totalFee}')::bigint;
  if combined_fee<separate_fee then
   rows:=rows||jsonb_build_array(jsonb_build_object('goodId',candidate.id,'variantId',candidate.variant_id,'variantName',candidate.variant_name,'qty',candidate.qty,
    'separateFee',separate_fee,'combinedFee',combined_fee,'savings',separate_fee-combined_fee));
   next_change:=least(next_change,(combined_quote->>'nextChangeAt')::timestamptz);
  end if;
  exit when jsonb_array_length(rows)>=12;
 end loop;
 result:=jsonb_build_object('items',rows,'nextChangeAt',next_change,'calculatedAt',statement_timestamp());
 return result;
end $$

create table private.store_analytics_health (
 minute timestamptz primary key, observed_at timestamptz not null
)

create table private.store_analytics_rate_buckets (
 bucket timestamptz not null, scope text not null, requests integer not null check(requests>0), primary key(bucket,scope)
)

do $$declare name text;begin
 foreach name in array array['settings','windows','health','sessions','events','order_bindings','rate_buckets','daily','daily_coverage'] loop
  execute format('alter table private.store_analytics_%I enable row level security',name);
  execute format('revoke all on private.store_analytics_%I from public,anon,authenticated,service_role',name);
 end loop;
end $$

create function private.store_analytics_rate(p_scope text,p_limit integer,p_at timestamptz) returns void
language plpgsql volatile security invoker set search_path='' as $$declare used integer;begin
 insert into private.store_analytics_rate_buckets(bucket,scope,requests) values(date_trunc('minute',p_at),p_scope,1)
 on conflict(bucket,scope) do update set requests=store_analytics_rate_buckets.requests+1 returning requests into used;
 if used>p_limit then raise exception using errcode='P0429',message='analytics_rate_limited';end if;
end $$

-- Operational activation is separate from deployment and never accepts a date
-- supplied by the caller. No customer traffic is backfilled on activation.
create function public.set_store_analytics_collection(p_enabled boolean,p_notice_version text) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare at_time timestamptz; current private.store_analytics_settings;
begin
 perform private.store_analytics_require_service();
 if p_enabled is null or p_notice_version is distinct from 'analytics-v1' then raise invalid_parameter_value using message='analytics_invalid_activation';end if;
 select * into current from private.store_analytics_settings where id for update;
 at_time:=clock_timestamp();
 if current.enabled is distinct from p_enabled then
  update private.store_analytics_settings set enabled=p_enabled,revision=revision+1,
   activated_at=case when p_enabled then coalesce(activated_at,at_time) else activated_at end where id;
  if p_enabled then insert into private.store_analytics_windows(started_at) values(at_time);
  else update private.store_analytics_windows set ended_at=at_time where ended_at is null;end if;
 end if;
 return public.get_store_analytics_state();
end $$

create function public.start_store_analytics_session(p_token_hash text,p_notice_version text) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare at_time timestamptz;
begin
 perform private.store_analytics_require_service();
 if p_token_hash is null or p_token_hash!~'^[0-9a-f]{64}$' or p_notice_version is distinct from 'analytics-v1' then
  raise invalid_parameter_value using message='analytics_invalid_session';end if;
 perform 1 from private.store_analytics_settings where id and enabled for share;
 if not found then raise object_not_in_prerequisite_state using message='analytics_disabled';end if;
 at_time:=clock_timestamp();
 perform private.store_analytics_rate('session-start',1000,at_time);
 insert into private.store_analytics_sessions(token_hash,notice_version,created_at,last_seen_at)
 values(p_token_hash,p_notice_version,at_time,at_time);
 return jsonb_build_object('startedAt',at_time);
end $$

create function public.revoke_store_analytics_session(p_token_hash text) returns void
language plpgsql volatile security definer set search_path='' as $$
declare session private.store_analytics_sessions;
begin
 perform private.store_analytics_require_service();
 if p_token_hash is null or p_token_hash!~'^[0-9a-f]{64}$' then raise invalid_parameter_value using message='analytics_invalid_session';end if;
 select * into session from private.store_analytics_sessions where token_hash=p_token_hash for update;
 if not found then return;end if;
 -- Delete the entire observed session, including its last target and token hash.
 -- Missing tokens are rejected exactly like revoked tokens; no tombstone is needed.
 delete from private.store_analytics_rate_buckets where scope='session:'||session.id::text;
 delete from private.store_analytics_sessions where id=session.id;
end $$

create function private.store_analytics_page(p_kind text,p_target text,p_at timestamptz) returns jsonb
language plpgsql stable security invoker set search_path='' as $$declare result jsonb;
begin
 if p_kind='home' and p_target='home' or p_kind='shop' and p_target in ('all','new','best')
  or p_kind='stories' and p_target='all' or p_kind='events' and p_target='all' then return '{}';end if;
 if p_kind='shop' and p_target~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  and exists(select 1 from public.get_catalog_categories() where id=p_target::uuid) then return jsonb_build_object('categoryId',p_target);end if;
 if p_kind='good' then
  select jsonb_build_object('ipId',g.ip_id,'categoryId',g.category_id) into result
  from public.goods g join public.ips ip on ip.id=g.ip_id where g.id=p_target and g.published_at is not null and g.archived_at is null
   and g.sale_restriction='none' and ip.published_at is not null and ip.archived_at is null;
 elsif p_kind='ip' then
  select jsonb_build_object('ipId',id) into result from public.ips where public_slug=p_target and published_at is not null and archived_at is null;
 elsif p_kind='story' and p_target~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
  select '{}'::jsonb into result from public.shopping_stories where id=p_target::uuid and deleted_at is null
   and(starts_at is null or starts_at<=p_at) and(ends_at is null or ends_at>p_at);
 elsif p_kind='event' then
  select jsonb_build_object('ipId',e.ip_id) into result from public.events e join public.ips ip on ip.id=e.ip_id
   where e.id=p_target and e.archived_at is null and ip.published_at is not null and ip.archived_at is null;
 end if;
 return result;
end $$

create function public.record_store_analytics_event(p_token_hash text,p_event_id uuid,p_page_kind text,p_target_id text,
 p_channel text,p_source text,p_medium text,p_link_token text default null) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare session private.store_analytics_sessions; existing private.store_analytics_events; target jsonb; linked private.marketing_links;
 at_time timestamptz; fingerprint text; landing uuid;
begin
 perform private.store_analytics_require_service();
 if p_token_hash is null or p_token_hash!~'^[0-9a-f]{64}$' or p_event_id is null
  or p_page_kind is null or p_page_kind not in ('home','shop','good','stories','story','ip','events','event')
  or p_target_id is null or length(p_target_id) not between 1 and 200 or p_target_id~'[[:cntrl:]]'
  or p_channel is null or p_channel not in ('direct','search','social','email','paid','referral','internal')
  or p_source is null or p_source not in ('none','google','naver','bing','daum','instagram','facebook','youtube','kakao','x','threads','email','other','icons')
  or p_medium is null or p_medium not in ('none','organic','social','email','cpc','paid_social','referral','internal')
  or(p_link_token is not null and p_link_token!~'^[0-9a-f]{32}$') then raise invalid_parameter_value using message='analytics_invalid_event';end if;
 perform 1 from private.store_analytics_settings where id and enabled for share;
 if not found then raise object_not_in_prerequisite_state using message='analytics_disabled';end if;
 select * into session from private.store_analytics_sessions where token_hash=p_token_hash for update;
 at_time:=clock_timestamp();
 if not found or session.revoked_at is not null then raise invalid_authorization_specification using message='analytics_session_unavailable';end if;
 fingerprint:=encode(extensions.digest(jsonb_build_array(p_page_kind,p_target_id,p_channel,p_source,p_medium,p_link_token)::text,'sha256'),'hex');
 select * into existing from private.store_analytics_events where id=p_event_id;
 if found then
  if existing.session_id<>session.id or existing.payload_hash<>fingerprint then raise exception using errcode='PT409',message='analytics_event_conflict';end if;
  return jsonb_build_object('recorded',true,'replayed',true);
 end if;
 if at_time>=session.last_seen_at+interval '30 minutes' or at_time>=session.created_at+interval '24 hours'
  or (at_time at time zone 'Asia/Seoul')::date<>(session.created_at at time zone 'Asia/Seoul')::date then
  raise invalid_authorization_specification using message='analytics_session_expired';end if;
 if session.event_count>=2000 then raise exception using errcode='P0429',message='analytics_rate_limited';end if;
 target:=private.store_analytics_page(p_page_kind,p_target_id,at_time);
 if target is null then raise no_data_found using message='analytics_page_unavailable';end if;
 if p_link_token is not null then
  select * into linked from private.marketing_links where token=p_link_token;
  if not found or not private.marketing_link_available(linked)
   or not((linked.source='home' and p_page_kind='home') or(linked.source='good' and p_page_kind='good' and linked.good_id=p_target_id)
    or(linked.source='story' and p_page_kind='story' and linked.story_id::text=p_target_id)
    or(linked.source='category' and p_page_kind='shop' and linked.category_id::text=p_target_id)) then
   raise invalid_parameter_value using message='analytics_link_target_mismatch';end if;
  landing:=linked.id;
 end if;
 perform private.store_analytics_rate('events',10000,at_time);
 perform private.store_analytics_rate('session:'||session.id::text,120,at_time);
 -- Direct/internal navigation keeps the most recent measured acquisition.
 if session.event_count=0 or landing is not null or p_channel not in ('direct','internal') then
  session.channel:=p_channel;session.source:=p_source;session.medium:=p_medium;session.last_link_id:=landing;
 end if;
 insert into private.store_analytics_events(id,session_id,observed_at,page_kind,target_id,ip_id,category_id,channel,source,medium,link_id,landing_link_id,payload_hash)
 values(p_event_id,session.id,at_time,p_page_kind,p_target_id,target->>'ipId',(target->>'categoryId')::uuid,
  session.channel,session.source,session.medium,session.last_link_id,landing,fingerprint);
 update private.store_analytics_sessions set last_seen_at=at_time,event_count=event_count+1,
  channel=session.channel,source=session.source,medium=session.medium,last_link_id=session.last_link_id,last_page_kind=p_page_kind,last_page_target=p_target_id where id=session.id;
 insert into private.store_analytics_health(minute,observed_at) values(date_trunc('minute',at_time),at_time) on conflict(minute) do nothing;
 return jsonb_build_object('recorded',true,'replayed',false);
end $$

create function public.bind_store_analytics_order(p_token_hash text,p_order_id uuid,p_user_id uuid) returns boolean
language plpgsql volatile security definer set search_path='' as $$
declare session private.store_analytics_sessions; target public.orders; previous private.store_analytics_order_bindings; at_time timestamptz;
begin
 perform private.store_analytics_require_service();
 if p_token_hash is null or p_token_hash!~'^[0-9a-f]{64}$' or p_order_id is null or p_user_id is null then
  raise invalid_parameter_value using message='analytics_invalid_binding';end if;
 -- Account -> settings -> session -> order. The service boundary supplies the
 -- authenticated actor; this argument is never accepted from a browser body.
 perform private.lock_operator_subjects(array[p_user_id]);
 if private.is_account_write_fenced(p_user_id) or not exists(select 1 from public.profiles where id=p_user_id and role='user' and suspended_at is null) then
  raise insufficient_privilege using message='analytics_order_unavailable';end if;
 perform 1 from private.store_analytics_settings where id and enabled for share;
 if not found then return false;end if;
 select * into session from private.store_analytics_sessions where token_hash=p_token_hash for update;
 at_time:=clock_timestamp();
 if not found or session.revoked_at is not null or session.event_count=0
  or at_time>=session.last_seen_at+interval '30 minutes' or at_time>=session.created_at+interval '24 hours'
  or(at_time at time zone 'Asia/Seoul')::date<>(session.created_at at time zone 'Asia/Seoul')::date then return false;end if;
 select * into target from public.orders where id=p_order_id for update;
 if not found or target.user_id<>p_user_id then raise insufficient_privilege using message='analytics_order_unavailable';end if;
 select * into previous from private.store_analytics_order_bindings where order_id=p_order_id;
 if found then
  if previous.session_id<>session.id then raise exception using errcode='PT409',message='analytics_order_binding_conflict';end if;
  return true;
 end if;
 if target.status<>'pending' or target.created_at<session.created_at or target.created_at<at_time-interval '2 minutes'
  or target.payment_method<>'card' or target.total<=0 then return false;end if;
 insert into private.store_analytics_order_bindings(order_id,session_id,bound_at,channel,source,medium,link_id,page_kind,page_target)
 values(target.id,session.id,at_time,session.channel,session.source,session.medium,session.last_link_id,session.last_page_kind,session.last_page_target);
 return true;
end $$

create function private.store_analytics_day_coverage(p_day date,p_at timestamptz) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare began timestamptz; ended timestamptz; expected integer; observed integer; first_at timestamptz; state_value text; archived private.store_analytics_daily_coverage; collection_enabled boolean;
begin
 if p_day>(p_at at time zone 'Asia/Seoul')::date then return jsonb_build_object('state','future','expectedMinutes',0,'observedMinutes',0,'archived',false);end if;
 if p_day<((p_at at time zone 'Asia/Seoul')::date-interval '13 months')::date then return jsonb_build_object('state','expired','expectedMinutes',0,'observedMinutes',0,'archived',false);end if;
 select * into archived from private.store_analytics_daily_coverage where day=p_day;
 if found then return jsonb_build_object('state',archived.state,'expectedMinutes',archived.expected_minutes,'observedMinutes',archived.observed_minutes,'archived',true,'observedUntil',archived.observed_until);end if;
 select activated_at,enabled into first_at,collection_enabled from private.store_analytics_settings where id;
 if first_at is null or p_day<(first_at at time zone 'Asia/Seoul')::date then
  return jsonb_build_object('state','unmeasured','expectedMinutes',0,'observedMinutes',0,'archived',false);end if;
 began:=p_day::timestamp at time zone 'Asia/Seoul';ended:=least((p_day+1)::timestamp at time zone 'Asia/Seoul',date_trunc('minute',p_at));
 select floor(coalesce(sum(greatest(0,extract(epoch from (least(coalesce(w.ended_at,p_at),ended)-greatest(w.started_at,began)))))/60,0))::integer
 into expected from private.store_analytics_windows w where w.started_at<ended and coalesce(w.ended_at,p_at)>began;
 select count(*)::integer into observed from private.store_analytics_health h where h.minute>=began and h.minute<ended;
 if p_day=(p_at at time zone 'Asia/Seoul')::date and collection_enabled then state_value:='collecting';
 elsif expected=0 then state_value:='paused';
 elsif expected>=1440 and observed>=expected then state_value:='observed';
 else state_value:='partial';end if;
 return jsonb_build_object('state',state_value,'expectedMinutes',expected,'observedMinutes',observed,'archived',false,'observedUntil',p_at);
end $$

create function public.process_store_analytics_retention() returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare at_time timestamptz:=clock_timestamp(); cutoff date; first_day date; day_value date; coverage jsonb; archived_count integer:=0; enabled_value boolean;
begin
 perform private.store_analytics_require_service();
 if not pg_try_advisory_xact_lock(hashtextextended('store-analytics:retention',0)) then return jsonb_build_object('busy',true);end if;
 select enabled,(activated_at at time zone 'Asia/Seoul')::date into enabled_value,first_day from private.store_analytics_settings where id for share;
 if enabled_value then
  insert into private.store_analytics_health(minute,observed_at) values(date_trunc('minute',at_time),at_time) on conflict(minute) do nothing;
 end if;
 -- Keep exactly the latest 90 Korean calendar dates, including today.
 cutoff:=(at_time at time zone 'Asia/Seoul')::date-89;
 if first_day is not null then
  for day_value in select day::date from generate_series(greatest(first_day,((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date)::timestamp,
   (cutoff-1)::timestamp,interval '1 day') days(day)
   where not exists(select 1 from private.store_analytics_daily_coverage where day=days.day::date) order by day limit 7 loop
   -- Revocation either completes before this snapshot or waits until all raw
   -- identifiers have been removed. Anonymous archived totals cannot be relinked.
   perform id from private.store_analytics_sessions where created_at>=day_value::timestamp at time zone 'Asia/Seoul'
    and created_at<(day_value+1)::timestamp at time zone 'Asia/Seoul' order by id for update;
   coverage:=private.store_analytics_day_coverage(day_value,at_time);
   insert into private.store_analytics_daily(day,dimension,key,page_views,product_views,sessions,link_landings,orders,converted_sessions,gross_amount,refund_amount,observed_until)
    select day_value,r.*,at_time from private.store_analytics_raw_rows(day_value) r;
   insert into private.store_analytics_daily_coverage(day,state,expected_minutes,observed_minutes,observed_until)
    values(day_value,coverage->>'state',(coverage->>'expectedMinutes')::integer,(coverage->>'observedMinutes')::integer,at_time);
   delete from private.store_analytics_sessions where created_at>=day_value::timestamp at time zone 'Asia/Seoul' and created_at<(day_value+1)::timestamp at time zone 'Asia/Seoul';
   delete from private.store_analytics_health where minute>=day_value::timestamp at time zone 'Asia/Seoul' and minute<(day_value+1)::timestamp at time zone 'Asia/Seoul';
   archived_count:=archived_count+1;
  end loop;
 end if;
 delete from private.store_analytics_sessions where created_at<(((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date)::timestamp at time zone 'Asia/Seoul';
 delete from private.store_analytics_daily where day<((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date;
 delete from private.store_analytics_daily_coverage where day<((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date;
 delete from private.store_analytics_health where minute<(((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date)::timestamp at time zone 'Asia/Seoul';
 delete from private.store_analytics_rate_buckets where bucket<date_trunc('minute',at_time)-interval '10 minutes';
 return jsonb_build_object('busy',false,'archivedDays',archived_count,'checkedAt',at_time);
end $$

create function private.preserve_claim_withdrawal() returns trigger
language plpgsql set search_path='' as $$
begin
 if old.stage='withdrawn' and (new.stage<>old.stage or new.status<>old.status or new.claim_type<>old.claim_type or new.withdrawn_at is distinct from old.withdrawn_at) then
  raise check_violation using message='claim_already_withdrawn';end if;
 new.claim_revision:=old.claim_revision+1;
 return new;
end $$

create or replace function private.seal_order_claim_refund_account() returns trigger
language plpgsql volatile security definer set search_path='' as $$
begin
 if new.stage in('completed','rejected','withdrawn') and (tg_op='INSERT' or old.stage is distinct from new.stage) then
  update private.claim_refund_accounts set purge_after=coalesce(purge_after,now()+interval '30 days') where claim_id=new.id and purged_at is null;
 end if;
 return null;
end $$

create function private.read_order_claim_withdrawal_context(p_claim_id uuid,p_actor uuid,p_as_operator boolean) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare claim public.order_cancellation_requests;purchase public.orders;blocker text;
begin
 if p_actor is null then raise insufficient_privilege using message='auth_required';end if;
 if p_as_operator and not private.has_operator_capability(p_actor,'sales.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 select * into claim from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found';end if;
 select * into purchase from public.orders where id=claim.order_id;
 if not p_as_operator and purchase.user_id<>p_actor then raise no_data_found using message='claim_not_found';end if;
 blocker:=private.order_claim_withdrawal_blocker(claim);
 return jsonb_build_object('claimId',claim.id,'orderId',claim.order_id,'claimType',claim.claim_type,'stage',claim.stage,
  'revision',claim.claim_revision,'allowed',blocker is null,'blocker',blocker,'orderTotal',purchase.total,
  'withdrawal',(select jsonb_build_object('actorKind',w.actor_kind,'reason',w.reason,'createdAt',w.created_at) from private.order_claim_withdrawals w where w.claim_id=claim.id));
end $$

create function private.apply_order_claim_withdrawal(p_claim_id uuid,p_operation_id uuid,p_expected_revision integer,p_reason text,p_confirmed boolean,p_as_operator boolean)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();purchase public.orders;claim public.order_cancellation_requests;previous private.order_claim_withdrawals;
 order_key uuid;buyer uuid;blocker text;kind text:=case when p_as_operator then 'operator' else 'customer' end;reason text:=btrim(p_reason);happened timestamptz;
begin
 if actor is null then raise insufficient_privilege using message='auth_required';end if;
 if p_as_operator and not private.has_operator_capability(actor,'sales.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 or p_confirmed is distinct from true
  or reason is null or char_length(reason) not between 2 and 500 or reason~'[[:cntrl:]]' then raise invalid_parameter_value using message='invalid_claim_withdrawal';end if;
 select c.order_id,o.user_id into order_key,buyer from public.order_cancellation_requests c join public.orders o on o.id=c.order_id where c.id=p_claim_id;
 if order_key is null or not p_as_operator and buyer<>actor then raise no_data_found using message='claim_not_found';end if;
 -- Existing-order recovery remains available to its owner, including suspended owners.
 perform private.lock_operator_subjects(array[actor,buyer]);
 if p_as_operator then perform private.require_actor_operator_capability(actor,'sales.manage',false);end if;
 perform pg_advisory_xact_lock(hashtextextended('claim-withdrawal:'||p_operation_id::text,0));
 select * into previous from private.order_claim_withdrawals where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.actor_kind<>kind or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision or previous.reason<>reason then
   raise unique_violation using message='claim_withdrawal_request_conflict';end if;
  return private.order_claim_withdrawal_receipt(p_operation_id,actor);
 end if;
 select * into purchase from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 perform shipment_id from public.order_claim_collections where claim_id=p_claim_id order by shipment_id for update;
 if claim.claim_revision<>p_expected_revision then raise sqlstate 'PT409' using message='claim_changed';end if;
 blocker:=private.order_claim_withdrawal_blocker(claim);
 if blocker is not null then raise check_violation using message=blocker;end if;
 happened:=clock_timestamp();
 insert into private.order_claim_withdrawals(id,claim_id,order_id,actor_id,actor_kind,expected_revision,reason,from_stage,created_at)
 values(p_operation_id,p_claim_id,order_key,actor,kind,p_expected_revision,reason,claim.stage,happened);
 update public.order_cancellation_requests set stage='withdrawn',withdrawn_at=happened,decided_at=happened,decided_by=actor,
  decision_note=null,held_from=null,hold_reason=null,held_at=null,updated_at=happened where id=p_claim_id;
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'order.claim_withdrawn','order:'||order_key,
  jsonb_build_object('claimId',p_claim_id,'claimType',claim.claim_type,'from',claim.stage,'to','withdrawn','actorKind',kind,'customerConfirmed',true));
 perform private.notify_order_claim(p_claim_id,'withdrawn','요청을 철회했어요',
  case when p_as_operator then '고객님과 확인한 요청 철회를 담당자가 기록했습니다. 주문과 결제는 유지되며 환불을 실행하지 않습니다.'
  else '요청을 철회했습니다. 주문과 결제는 유지되며 환불을 실행하지 않습니다.' end);
 return private.order_claim_withdrawal_receipt(p_operation_id,actor);
end $$

create function public.read_my_order_claim_withdrawal(p_operation_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();begin
 if actor is null or p_operation_id is null then raise insufficient_privilege using message='auth_required';end if;
 perform private.lock_operator_subjects(array[actor]);
 perform pg_advisory_xact_lock(hashtextextended('claim-withdrawal:'||p_operation_id::text,0));
 if not exists(select 1 from private.order_claim_withdrawals where id=p_operation_id and actor_id=actor and actor_kind='customer') then return null;end if;
 return private.order_claim_withdrawal_receipt(p_operation_id,actor);
end $$

