language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();begin
 perform private.require_actor_operator_capability(actor,'sales.manage',false);
 if p_operation_id is null then raise invalid_parameter_value using message='invalid_claim_withdrawal';end if;
 perform pg_advisory_xact_lock(hashtextextended('claim-withdrawal:'||p_operation_id::text,0));
 if not exists(select 1 from private.order_claim_withdrawals where id=p_operation_id and actor_id=actor and actor_kind='operator') then return null;end if;
 return private.order_claim_withdrawal_receipt(p_operation_id,actor);
end $$

create or replace function public.admin_order_claim_stage_counts_console(p_claim_type text default null,p_reason_type text default null,p_from date default null,p_to date default null,p_query text default null,p_field text default 'all',p_date_field text default 'requested')
returns table(stage text,total bigint) language plpgsql stable security definer set search_path='' as $$
declare needle text:=nullif(btrim(p_query),'');begin
 if not private.has_operator_capability(auth.uid(),'sales.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 if (p_claim_type is not null and p_claim_type not in('cancel','return','exchange')) or p_field is null or p_field not in('all','order','buyer','email')
  or p_date_field is null or p_date_field not in('requested','collected','completed') or p_from is not null and p_to is not null and p_from>p_to or char_length(needle)>100 then
  raise invalid_parameter_value using message='invalid_claim_search';end if;
  if p_reason_type is not null and p_reason_type not in('change_of_mind','defect','staff',
    'staff:out_of_stock','staff:customer_request','staff:test_payment_cleanup','staff:other') then
    raise check_violation using message='invalid claim reason filter';
  end if;
 return query select known.value,count(request.id)::bigint from unnest(array['requested','in_review','collecting','collected','on_hold','processing','needs_review','completed','rejected','withdrawn'])known(value)
 left join public.order_cancellation_requests request on request.stage=known.value and(p_claim_type is null or request.claim_type=p_claim_type)
  and private.admin_sales_claim_matches(request,p_reason_type,p_from,p_to,needle,p_field,p_date_field) group by known.value;
end $$

-- PostgREST runs STABLE RPCs in a read-only transaction. Reads inspect current
-- authority without row locks; mutating RPCs keep the actor-lock guard.
create or replace function public.admin_get_product_detail_experiences() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 if not private.has_operator_capability(auth.uid(),'store.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';end if;
 select jsonb_build_object('values',jsonb_object_agg(section,values),'revisions',jsonb_object_agg(section,revision)) into result
 from private.product_detail_experience_settings;
 return result;
end $$

-- The optional two-year fallback uses at least one verified buyer after every
-- shorter window failed the configured threshold, matching the source control.
create or replace function public.get_product_detail_experience(p_good_id text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare current_good public.goods%rowtype; config jsonb; messages jsonb:='[]'; window_row record; customer_count bigint; sale_rank bigint;
 at_time timestamptz:=statement_timestamp(); today timestamptz:=date_trunc('day',statement_timestamp() at time zone 'Asia/Seoul') at time zone 'Asia/Seoul';
 next_change timestamptz;
begin
 select g.* into current_good from public.goods g join public.ips ip on ip.id=g.ip_id
 where g.id=p_good_id and g.published_at is not null and g.archived_at is null and g.sale_restriction='none'
  and ip.published_at is not null and ip.archived_at is null;
 if not found then return null;end if;
 select values into config from private.product_detail_experience_settings where section='messages';
 if (config->>'buyers')::boolean then
  for window_row in select * from (values
   (1,'today',today),(2,'week',today-interval '6 days'),(3,'sixMonths',today-interval '6 months'),
   (4,'year',today-interval '1 year'),(5,'twoYears',today-interval '2 years')
  ) periods(position,key,starts_at) where key<>'twoYears' or (config->>'twoYears')::boolean order by position loop
   select count(distinct o.user_id) into customer_count from private.product_detail_paid_orders(window_row.starts_at,at_time) paid
    join public.orders o on o.id=paid.id where exists(select 1 from public.order_items i where i.order_id=o.id and i.good_id=p_good_id);
   if customer_count >= (case when window_row.key='twoYears' then 1 else (config->>'minBuyers')::integer end) then
    messages:=messages||jsonb_build_array(jsonb_build_object('kind','buyers','window',window_row.key,'count',customer_count));exit;
   end if;
  end loop;
 end if;
 if (config->>'repeatBuyers')::boolean then
  for window_row in select * from (values
   (1,'threeMonths',today-interval '3 months'),(2,'sixMonths',today-interval '6 months'),(3,'year',today-interval '1 year')
  ) periods(position,key,starts_at) order by position loop
   select count(*) into customer_count from (
    select o.user_id from private.product_detail_paid_orders(window_row.starts_at,at_time) paid
     join public.orders o on o.id=paid.id where exists(select 1 from public.order_items i where i.order_id=o.id and i.good_id=p_good_id)
     group by o.user_id having count(distinct o.id)>=2
   ) repeated;
   if customer_count >= (config->>'minRepeatBuyers')::integer then
    messages:=messages||jsonb_build_array(jsonb_build_object('kind','repeatBuyers','window',window_row.key,'count',customer_count));exit;
   end if;
  end loop;
 end if;
 if (config->>'bestSeller')::boolean then
  with sales as (
   select item.good_id,sum(item.qty::bigint) quantity from private.product_detail_paid_orders(today-interval '3 days',today) paid
    join public.order_items item on item.order_id=paid.id join public.goods g on g.id=item.good_id join public.ips ip on ip.id=g.ip_id
   where g.published_at is not null and g.archived_at is null and g.sale_restriction='none'
    and ip.published_at is not null and ip.archived_at is null group by item.good_id
  ), ranked as (select good_id,row_number() over(order by quantity desc,good_id) rank from sales where quantity>0)
  select rank into sale_rank from ranked where good_id=p_good_id and rank<=10;
  if sale_rank is not null then messages:=messages||jsonb_build_array(jsonb_build_object('kind','bestSeller','rank',sale_rank));end if;
 end if;
 if (config->>'newProduct')::boolean and current_good.created_at<=at_time and current_good.created_at>at_time-interval '7 days' then
  messages:=messages||jsonb_build_array(jsonb_build_object('kind','newProduct'));
  next_change:=current_good.created_at+interval '7 days';
 end if;
 if (config->>'buyers')::boolean or (config->>'repeatBuyers')::boolean or (config->>'bestSeller')::boolean then next_change:=least(next_change,today+interval '1 day');end if;
 return jsonb_build_object('messages',messages,'discovery',public.get_product_detail_experience_config(),'nextChangeAt',next_change);
end $$

-- Read-only, caller-scoped review-event exports. Existing reward contracts stay sealed.
create function private.review_event_export_snapshot(p_filters jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare mode_value text; query_value text; state_value text; date_field text; from_day date; to_day date;
 target_event_id uuid; filter_value text; event_doc jsonb; exported jsonb; fingerprint_rows jsonb; row_count integer; fingerprint text;
begin
 if p_filters is null or jsonb_typeof(p_filters)<>'object' or octet_length(p_filters::text)>2000
  or exists(select 1 from jsonb_each(p_filters) f where jsonb_typeof(f.value) not in ('string','null')) then
  raise invalid_parameter_value using message='invalid_review_event_export';end if;
 mode_value:=p_filters->>'mode'; query_value:=p_filters->>'query';
 if mode_value is null or mode_value not in ('events','entries') or query_value is null or char_length(query_value)>100 or query_value<>btrim(query_value) then
  raise invalid_parameter_value using message='invalid_review_event_export';end if;
 if mode_value='events' then
  if (select array_agg(key order by key) from jsonb_object_keys(p_filters) key)<>array['dateField','from','mode','query','state','to'] then
   raise invalid_parameter_value using message='invalid_review_event_export';end if;
  state_value:=p_filters->>'state';date_field:=p_filters->>'dateField';
  if state_value is null or state_value not in ('all','scheduled','active','closed','ready','announced','archived')
   or date_field is null or date_field not in ('created','start','end','announce')
   or (p_filters->>'from' is not null and p_filters->>'from'!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}$')
   or (p_filters->>'to' is not null and p_filters->>'to'!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}$') then
   raise invalid_parameter_value using message='invalid_review_event_export';end if;
  from_day:=(p_filters->>'from')::date;to_day:=(p_filters->>'to')::date;
  if from_day is not null and to_day is not null and from_day>to_day then raise invalid_parameter_value using message='invalid_review_event_export';end if;
  with candidates as (
   select e.*,private.review_event_state(e,statement_timestamp()) state,
    case date_field when 'start' then starts_on when 'end' then ends_on when 'announce' then announces_on else (created_at at time zone 'Asia/Seoul')::date end filter_day
   from private.review_events e where query_value='' or position(lower(query_value) in lower(e.title))>0 or e.number::text=query_value or e.id::text=query_value
  ), filtered as (select * from candidates where (state_value='all' and archived_at is null or state=state_value)
   and (from_day is null or filter_day>=from_day) and (to_day is null or filter_day<=to_day)), bounded as (
   select * from filtered order by created_at desc,id limit 10001
  ), documents as (
   select id,created_at,private.review_event_document(id) value from bounded
  ) select count(*),coalesce(jsonb_agg((value-'goodIds'-'categoryIds')||jsonb_build_object(
   'targetCount',jsonb_array_length(value->'goodIds')+jsonb_array_length(value->'categoryIds'),
   'targetsFingerprint',encode(extensions.digest(jsonb_build_array(value->'goodIds',value->'categoryIds')::text,'sha256'),'hex'))
   order by created_at desc,id),'[]'::jsonb) into row_count,exported from documents;
  fingerprint_rows:=exported;
 else
  if (select array_agg(key order by key) from jsonb_object_keys(p_filters) key)<>array['eventId','filter','mode','query']
   or p_filters->>'eventId' is null or p_filters->>'eventId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   raise invalid_parameter_value using message='invalid_review_event_export';end if;
  target_event_id:=(p_filters->>'eventId')::uuid;filter_value:=p_filters->>'filter';
  if filter_value is null or filter_value not in ('all','eligible','selected','awarded','revoked','unavailable') then
   raise invalid_parameter_value using message='invalid_review_event_export';end if;
  event_doc:=private.review_event_document(target_event_id);
  if event_doc is null then raise no_data_found using message='review_event_not_found';end if;
  with candidates as materialized (
   select entry.*,r.body,r.rating,r.updated_at review_updated_at,private.review_event_review_fingerprint(r) review_fingerprint,
    cardinality(coalesce(r.image_paths,'{}')) image_count,coalesce(nullif(btrim(profile.nickname),''),'고객') nickname,
    coalesce(g.name,'삭제된 상품') good_name,coalesce(g.code,'') good_code,private.review_event_entry_problem(entry) problem,
    award.granted_at,award.revoked_at,award.expires_at
   from private.review_event_entries entry left join public.reviews r on r.id=entry.review_id
   left join public.profiles profile on profile.id=entry.user_id left join public.goods g on g.id=entry.good_id
   left join private.review_event_awards award on award.entry_id=entry.id where entry.event_id=target_event_id
  ), filtered as (
   select * from candidates where (query_value='' or position(lower(query_value) in lower(nickname||' '||good_name||' '||coalesce(body,'')))>0 or source_review_id::text=query_value)
    and (filter_value='all' or filter_value='eligible' and problem is null and granted_at is null or filter_value='selected' and selected
     or filter_value='awarded' and granted_at is not null and revoked_at is null or filter_value='revoked' and revoked_at is not null or filter_value='unavailable' and problem is not null)
  ), bounded as (select * from filtered order by entered_at desc,id limit 10001), documents as (
   select entered_at,id,review_fingerprint,jsonb_build_object('id',id,'reviewId',source_review_id,'goodId',good_id,'goodCode',good_code,'goodName',good_name,
    'nickname',nickname,'rating',rating,'imageCount',image_count,'enteredAt',entered_at,'reviewUpdatedAt',review_updated_at,
    'selected',selected,'selectionChanged',selected and (selected_review_updated_at is distinct from review_updated_at or selected_review_fingerprint is distinct from review_fingerprint),
    'problem',problem,'creditAmount',credit_amount,'creditValidityDays',credit_validity_days,'eventRevision',event_revision,
    'grantedAt',granted_at,'revokedAt',revoked_at,'expiresAt',expires_at) value from bounded
  ) select count(*),coalesce(jsonb_agg(value order by entered_at desc,id),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_array(value,review_fingerprint) order by entered_at desc,id),'[]'::jsonb)
   into row_count,exported,fingerprint_rows from documents;
 end if;
 if row_count>10000 then raise program_limit_exceeded using message='review_event_export_limit';end if;
 fingerprint:=encode(extensions.digest(jsonb_build_object('filters',p_filters,'event',event_doc,'rows',fingerprint_rows)::text,'sha256'),'hex');
 return jsonb_build_object('filters',p_filters,'event',event_doc,'total',row_count,'rows',exported,'fingerprint',fingerprint,'capturedAt',statement_timestamp());
end $$

create function public.admin_export_review_events(p_filters jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if not private.has_operator_capability(auth.uid(),'cs.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 return private.review_event_export_snapshot(p_filters);
