-- Reviewed encrypted file issuance audit. Existing receipt/audit rows are immutable.
-- Only the application service can attest file issuance; actor is verified again under locks.
-- Passwords and password hashes are intentionally absent from both signatures.
create function public.service_record_encrypted_list_export(
 p_actor_id uuid,p_screen text,p_filters jsonb,p_row_count integer,p_record_count integer,p_file_sha256 text
) returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=p_actor_id; recorded_id uuid;
begin
 perform private.require_actor_operator_capability(actor,case when p_screen='orders' then 'sales.read' else 'sales.manage' end,false);
 if actor is null then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_screen is null or p_screen not in('orders','unpaid','dispatch','shipping','claims-cancels','claims-returns','claims-exchanges') then
  raise invalid_parameter_value using message='invalid_list_export_screen';end if;
 if p_filters is null or jsonb_typeof(p_filters)<>'object' or octet_length(p_filters::text)>2000
  or exists(select 1 from jsonb_each(p_filters) f where f.key not in
   ('view','field','query','status','state','from','to','dateField','paymentMethod','sort','fingerprint','tab','originId','method','delayNotice','stage','reasonType')
   or jsonb_typeof(f.value) not in('string','null')) then
  raise invalid_parameter_value using message='invalid_list_export_filters';end if;
 if p_row_count is null or p_row_count not between 0 and 10000 or p_record_count is null or p_record_count not between 0 and p_row_count then
  raise invalid_parameter_value using message='invalid_list_export_count';end if;
 if p_file_sha256 is null or p_file_sha256!~'^[a-f0-9]{64}$' then
  raise invalid_parameter_value using message='invalid_export_file_hash';end if;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.list_export.file_issued','admin_screen:'||p_screen,
  jsonb_build_object('screen',p_screen,'filters',p_filters,'rowCount',p_row_count,'recordCount',p_record_count,
   'format','xlsx','encryption','ECMA-376-Agile','fileSha256',p_file_sha256)) returning id into recorded_id;
 return recorded_id;
end $$

create function public.service_record_encrypted_settled_export(p_actor_id uuid,p_export_id uuid,p_file_sha256 text)
returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=p_actor_id; receipt private.settled_export_receipts; recorded_id uuid; item_count integer;
begin
 perform private.require_actor_operator_capability(actor,'sales.manage',false);
 if actor is null then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_file_sha256 is null or p_file_sha256!~'^[a-f0-9]{64}$' then
  raise invalid_parameter_value using message='invalid_export_file_hash';end if;
 select * into receipt from private.settled_export_receipts where id=p_export_id and actor_id=actor;
 if not found then raise no_data_found using message='settled_export_not_found';end if;
 select coalesce(sum(jsonb_array_length(value->'items')),0)::integer into item_count from jsonb_array_elements(receipt.payload->'orders');
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.settled_export.file_issued','settled_export:'||receipt.id,
  jsonb_build_object('receiptId',receipt.id,'filters',receipt.filters,'orderCount',jsonb_array_length(receipt.payload->'orders'),
   'itemCount',item_count,'capturedAt',receipt.payload->>'capturedAt','format','xlsx','encryption','ECMA-376-Agile','fileSha256',p_file_sha256))
 returning id into recorded_id;
 return recorded_id;
end $$

create function public.admin_order_claim_reason_context(p_claim_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=auth.uid();claim public.order_cancellation_requests;purchase public.orders;blocker text;original private.order_claim_reason_operations;
begin
 if actor is null or not private.has_operator_capability(actor,'sales.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 select * into claim from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found';end if;
 select * into purchase from public.orders where id=claim.order_id;
 select * into original from private.order_claim_reason_operations where claim_id=claim.id and changed order by created_at,id limit 1;
 blocker:=private.order_claim_reason_blocker(claim);
 return jsonb_build_object('actorId',actor,'claimId',claim.id,'orderId',claim.order_id,'claimType',claim.claim_type,
  'stage',claim.stage,'revision',claim.claim_revision,'reasonType',claim.reason_type,'reason',claim.reason,
  'originalReasonType',coalesce(original.from_reason_type,claim.reason_type),'originalReason',coalesce(original.from_reason,claim.reason),
  'requestedAt',claim.requested_at,'deliveredAt',purchase.delivered_at,'allowed',blocker is null,'blocker',blocker,
  'canUseChangeOfMind',not public.order_withdrawal_deadline_passed(purchase.delivered_at,'change_of_mind',claim.requested_at),
  'canUseDefect',not public.order_withdrawal_deadline_passed(purchase.delivered_at,'defect',claim.requested_at),
  'fee',case when claim.operational_fee_amount is null then null else jsonb_build_object('kind',claim.operational_fee_kind,
    'amount',claim.operational_fee_amount,'note',claim.operational_fee_note,'confirmedAt',claim.operational_fee_confirmed_at) end,
  'history',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'claimId',claim_id,'actorId',actor_id,
   'fromReasonType',from_reason_type,'fromReason',from_reason,'toReasonType',to_reason_type,'toReason',to_reason,
   'requestedAt',requested_at,'createdAt',created_at,'agreement',agreement) order by created_at,id),'[]'::jsonb)
   from private.order_claim_reason_operations where claim_id=claim.id and changed));
end $$

create function public.admin_change_order_claim_reason(p_claim_id uuid,p_operation_id uuid,p_expected_revision integer,
 p_expected_actor_id uuid,p_reason_type text,p_reason text,p_agreement text,p_confirmed boolean,p_fee_reviewed boolean)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();claim public.order_cancellation_requests;purchase public.orders;previous private.order_claim_reason_operations;
 order_key uuid;buyer uuid;reason_text text:=btrim(p_reason);agreement_text text:=btrim(p_agreement);blocker text;happened timestamptz;
 changed boolean;result_revision integer;
begin
 if actor is null or actor is distinct from p_expected_actor_id or not private.has_operator_capability(actor,'sales.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';end if;
 if p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or p_reason_type is null or p_reason_type not in('change_of_mind','defect') or p_confirmed is distinct from true or p_fee_reviewed is null
  or reason_text is null or char_length(reason_text) not between 1 and 200 or p_reason~'[[:cntrl:]]'
  or agreement_text is null or char_length(agreement_text) not between 2 and 500 or p_agreement~'[[:cntrl:]]' then
  raise invalid_parameter_value using message='invalid_claim_reason_change';end if;
 select c.order_id,o.user_id into order_key,buyer from public.order_cancellation_requests c join public.orders o on o.id=c.order_id where c.id=p_claim_id;
 if order_key is null then raise no_data_found using message='claim_not_found';end if;
 perform private.lock_operator_subjects(array[actor,buyer]);
 perform private.require_actor_operator_capability(actor,'sales.manage',false);
 perform pg_advisory_xact_lock(hashtextextended('claim-reason-change:'||p_operation_id::text,0));
 select * into previous from private.order_claim_reason_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision
   or previous.to_reason_type<>p_reason_type or previous.to_reason<>reason_text or previous.agreement<>agreement_text
   or previous.fee_reviewed<>p_fee_reviewed then raise unique_violation using message='claim_reason_request_conflict';end if;
  return private.order_claim_reason_receipt(p_operation_id,actor);
 end if;
 select * into purchase from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 perform shipment_id from public.order_claim_collections where claim_id=p_claim_id order by shipment_id for update;
 if claim.claim_revision<>p_expected_revision or claim.order_id is distinct from order_key or purchase.user_id is distinct from buyer then
  raise sqlstate 'PT409' using message='claim_changed';end if;
 blocker:=private.order_claim_reason_blocker(claim);
 if blocker is not null then raise check_violation using message=blocker;end if;
 if claim.operational_fee_amount is not null and not p_fee_reviewed then raise check_violation using message='claim_reason_fee_review_required';end if;
 -- The new classification is evaluated at original intake, never the edit time.
 if claim.reason_type<>p_reason_type and public.order_withdrawal_deadline_passed(purchase.delivered_at,p_reason_type,claim.requested_at) then
  raise check_violation using message='claim_reason_original_deadline_expired';end if;
 changed:=(claim.reason_type,claim.reason) is distinct from(p_reason_type,reason_text);
 happened:=clock_timestamp();result_revision:=claim.claim_revision;
 if changed then
  update public.order_cancellation_requests set reason_type=p_reason_type,reason=reason_text,updated_at=happened
   where id=p_claim_id returning claim_revision into result_revision;
 end if;
 insert into private.order_claim_reason_operations(id,claim_id,order_id,actor_id,expected_revision,result_revision,
  from_reason_type,from_reason,to_reason_type,to_reason,agreement,fee_reviewed,changed,from_stage,requested_at,delivered_at,created_at)
 values(p_operation_id,p_claim_id,order_key,actor,p_expected_revision,result_revision,claim.reason_type,claim.reason,
  p_reason_type,reason_text,agreement_text,p_fee_reviewed,changed,claim.stage,claim.requested_at,purchase.delivered_at,happened);
 if changed then
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.order.claim_reason_changed','order:'||order_key,
   jsonb_build_object('claimId',p_claim_id,'fromReasonType',claim.reason_type,'toReasonType',p_reason_type,
    'descriptionChanged',claim.reason<>reason_text,'customerConfirmed',true,'feeReviewed',p_fee_reviewed));
  insert into public.notifications(user_id,type,title,body,link_path,source_type,source_id,dedupe_key)
   values(buyer,'claim_updated','교환 요청 사유가 정정됐어요',
    case p_reason_type when 'defect' then '상품 하자·오배송' else '단순 변심' end||': '||reason_text,
    '/orders/'||order_key,'order_claim',p_claim_id::text,'claim:reason_changed:'||p_operation_id)
   on conflict(user_id,dedupe_key) do nothing;
 end if;
 return private.order_claim_reason_receipt(p_operation_id,actor);
end $$

create function public.admin_read_order_claim_reason_change(p_operation_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();begin
 perform private.require_actor_operator_capability(actor,'sales.manage',false);
 if p_operation_id is null then raise invalid_parameter_value using message='invalid_claim_reason_change';end if;
 perform pg_advisory_xact_lock(hashtextextended('claim-reason-change:'||p_operation_id::text,0));
 return private.order_claim_reason_receipt(p_operation_id,actor);
end $$

create function public.get_my_order_claim_reason_changes(p_order_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if auth.uid() is null then raise insufficient_privilege using message='auth_required';end if;
 if not exists(select 1 from public.orders where id=p_order_id and user_id=auth.uid()) then raise no_data_found using message='order_not_found';end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'claimId',claim_id,'fromReasonType',from_reason_type,'fromReason',from_reason,
  'toReasonType',to_reason_type,'toReason',to_reason,'requestedAt',requested_at,'createdAt',created_at)
  order by created_at,id),'[]'::jsonb) from private.order_claim_reason_operations where order_id=p_order_id and changed);
end $$

create function private.is_valid_home_hero_style(candidate jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
begin
 if candidate is null then return true;end if;
 if jsonb_typeof(candidate)<>'object' then return false;end if;
 if candidate ? 'image_dim' and (jsonb_typeof(candidate->'image_dim') is distinct from 'string'
   or candidate->>'image_dim' not in ('none','white','black')) then return false;end if;
 if candidate ? 'text_color' and (jsonb_typeof(candidate->'text_color') is distinct from 'string'
   or candidate->>'text_color' not in ('white','black')) then return false;end if;
 return true;
end $$

create or replace function private.guard_home_promotion_banner() returns trigger
language plpgsql security definer set search_path='' as $$
declare previous_live boolean:=false; next_live boolean;
begin
 -- Version precision and legacy long-copy preservation remain unchanged.
 if tg_op='UPDATE' then
  new.updated_at:=greatest(clock_timestamp(),old.updated_at+interval '1 microsecond');
  previous_live:=old.kind='hero' and old.archived_at is null;
 end if;
 next_live:=new.kind='hero' and new.archived_at is null;
 -- Both exits and entries serialize through the same count pool. Row locks are
 -- already owned on updates; the pool holder never locks another curation row.
 if previous_live is distinct from next_live then
  perform pg_advisory_xact_lock(hashtextextended('home_promotion_banner_count',0));
  if next_live and (select count(*) from public.home_curations where kind='hero' and archived_at is null and id<>new.id)>=10 then
   raise check_violation using message='home_hero_limit';
  end if;
 end if;
 if new.kind<>'hero' then return new;end if;
 if (tg_op='INSERT' or old.kind<>'hero' or new.title is distinct from old.title) and char_length(new.title)>40 then
  raise invalid_parameter_value using message='invalid_hero_title';
 end if;
 if (tg_op='INSERT' or old.kind<>'hero' or new.payload->>'subtitle' is distinct from old.payload->>'subtitle')
  and (char_length(new.payload->>'subtitle')>150 or cardinality(string_to_array(new.payload->>'subtitle',chr(10)))>3) then
  raise invalid_parameter_value using message='invalid_hero_subtitle';
 end if;
 return new;
end $$

CREATE OR REPLACE FUNCTION private.save_home_curation(target_operation_id uuid, target_curation_id uuid, target_kind text, target_ip_id text, target_title text, target_image_path text, target_link_path text, target_display_order integer, target_active_from timestamp with time zone, target_active_to timestamp with time zone, target_enabled boolean, target_slot text, target_payload jsonb, target_expected_updated_at timestamp with time zone, require_saved_version boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  -- Alias with a column-safe name: inside the claim UPDATE below, a bare
  -- actor_id would be ambiguous against admin_artwork_upload_claims.actor_id.
  claim_owner_id uuid := actor_id;
  normalized_kind text := pg_catalog.btrim(target_kind);
  normalized_ip_id text := nullif(pg_catalog.btrim(target_ip_id), '');
  normalized_title text := pg_catalog.btrim(target_title);
  normalized_image_path text := nullif(pg_catalog.btrim(target_image_path), '');
  normalized_link_path text := nullif(pg_catalog.btrim(target_link_path),'');
  normalized_slot text := nullif(pg_catalog.btrim(target_slot), '');
  normalized_payload jsonb := case
    when target_payload is null or target_payload = '{}'::jsonb then null
    else target_payload
  end;
  allowed_payload_keys text[];
  payload_key text;
  payload_text_value text;
  payload_good_ids jsonb;
  payload_good_id_limit integer;
  payload_good_id text;
  payload_mobile_image_path text;
  previous_mobile_image_path text;
  referenced_archived_at timestamptz;
  request_payload jsonb;
  previous_payload jsonb := 'null'::jsonb;
  after_payload jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  previous_curation public.home_curations%rowtype;
  curation_exists boolean := false;
begin
  perform private.require_operator_capability('store.manage',false);

  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  perform 1 from public.profiles where id=actor_id and role in ('staff','admin') and suspended_at is null for share;
  if not found then
    raise insufficient_privilege using message = 'forbidden';
  end if;

  if target_operation_id is null then
    raise null_value_not_allowed using message = 'invalid_operation_id';
  end if;
  if target_curation_id is null then
    raise null_value_not_allowed using message = 'invalid_curation_id';
  end if;
  if normalized_kind is null
    or normalized_kind not in (
      'hero', 'featured_ip', 'announcement',
      'notice_strip', 'editor_pick', 'band_banner', 'best_tab', 'benefit', 'sales_best', 'review_best', 'product_mosaic', 'product_collection'
    )
  then
    raise invalid_parameter_value using message = 'invalid_curation_kind';
  end if;
  if normalized_title is null
    or pg_catalog.char_length(normalized_title) not between (case when normalized_kind='hero' then 0 else 1 end) and 120
    or (normalized_kind in ('sales_best','review_best','product_mosaic','product_collection') and pg_catalog.char_length(normalized_title)>15)
  then
    raise invalid_parameter_value using message = 'invalid_curation_title';
  end if;
  if normalized_kind = 'featured_ip' and normalized_ip_id is null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind <> 'featured_ip' and normalized_ip_id is not null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind in ('hero', 'notice_strip', 'editor_pick', 'band_banner')
    and normalized_image_path is null
  then
    raise check_violation using message = 'curation_image_required';
  end if;
  if normalized_image_path is not null
    and normalized_image_path !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  then
    raise check_violation using message = 'invalid_curation_image_path';
  end if;
  if (normalized_link_path is null and normalized_kind not in ('hero','product_collection'))
    or (normalized_kind='product_collection' and normalized_link_path is not null)
    or (normalized_link_path is not null and not private.is_safe_home_curation_link(normalized_link_path))
  then
    raise invalid_parameter_value using message = 'invalid_curation_link_path';
  end if;
  if target_display_order is null or target_display_order < 0 then
    raise invalid_parameter_value using message = 'invalid_curation_display_order';
  end if;
  if target_active_from is null then
    raise null_value_not_allowed using message = 'invalid_curation_active_from';
  end if;
  if not pg_catalog.isfinite(target_active_from) then
    raise invalid_parameter_value using message = 'invalid_curation_active_from';
  end if;
  if target_active_to is not null
    and (
      not pg_catalog.isfinite(target_active_to)
      or target_active_to <= target_active_from
    )
  then
    raise check_violation using message = 'invalid_curation_active_window';
  end if;
  if target_enabled is null then
    raise null_value_not_allowed using message = 'invalid_curation_enabled';
  end if;

  if normalized_kind = 'best_tab' then
    if normalized_slot is null or normalized_slot not in ('category', 'popular') then
      raise invalid_parameter_value using message = 'invalid_curation_slot';
    end if;
  elsif normalized_slot is not null then
    raise invalid_parameter_value using message = 'invalid_curation_slot';
  end if;

  -- Per-kind payload whitelist. Unknown keys are rejected outright so typos
  -- never ship silently dead configuration.
  allowed_payload_keys := case normalized_kind
    when 'hero' then array['subtitle', 'mobile_image_path', 'alt_enabled', 'alt_title', 'alt_content', 'image_dim', 'text_color']
    when 'notice_strip' then array['mobile_image_path']
    when 'editor_pick' then array['badge', 'description']
    when 'band_banner' then array['subcopy', 'good_ids']
    when 'best_tab' then array['good_ids', 'selection_mode', 'item_count']
    when 'benefit' then array['description']
    when 'sales_best' then array['exposure_mode','period']
    when 'review_best' then array['selection_mode','good_ids']
    when 'product_mosaic' then array['mosaic_title','mosaic_subtitle','slots']
    when 'product_collection' then array['layout','image_shape','item_count','good_ids']
    else array[]::text[]
  end;

  if normalized_payload is not null then
    if pg_catalog.jsonb_typeof(normalized_payload) <> 'object' then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    if pg_catalog.cardinality(allowed_payload_keys) = 0 then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    for payload_key in
      select key from pg_catalog.jsonb_object_keys(normalized_payload) as keys(key)
    loop
      if not payload_key = any (allowed_payload_keys) then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
    end loop;

    for payload_key in
      select unnest from pg_catalog.unnest(array['subtitle', 'badge', 'description', 'subcopy'])
    loop
      if normalized_payload ? payload_key then
        if pg_catalog.jsonb_typeof(normalized_payload -> payload_key) <> 'string' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        payload_text_value := pg_catalog.btrim(normalized_payload ->> payload_key);
        if pg_catalog.char_length(payload_text_value) not between 1 and 200
          or (payload_key = 'badge' and pg_catalog.char_length(payload_text_value) > 20)
        then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        normalized_payload := pg_catalog.jsonb_set(
          normalized_payload, array[payload_key], pg_catalog.to_jsonb(payload_text_value)
        );
      end if;
    end loop;

    if normalized_payload ? 'good_ids' then
      payload_good_ids := normalized_payload -> 'good_ids';
      payload_good_id_limit := case normalized_kind when 'best_tab' then 12 when 'review_best' then 20 when 'product_collection' then 100 else 4 end;
      if pg_catalog.jsonb_typeof(payload_good_ids) <> 'array'
        or pg_catalog.jsonb_array_length(payload_good_ids) not between (case when normalized_kind in ('review_best','product_collection') then 0 else 1 end) and payload_good_id_limit
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      for payload_good_id in
        select value from pg_catalog.jsonb_array_elements_text(payload_good_ids) as elements(value)
      loop
        if payload_good_id !~ '^[A-Za-z0-9_-]{1,64}$' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
      end loop;
    end if;

    -- Automatic selection is a rule, never a saved snapshot of product IDs.
    if normalized_kind='best_tab' and normalized_payload ? 'selection_mode' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'selection_mode') <> 'string'
        or normalized_payload ->> 'selection_mode' <> 'latest'
        or normalized_payload ? 'good_ids'
        or not normalized_payload ? 'item_count'
        or pg_catalog.jsonb_typeof(normalized_payload -> 'item_count') <> 'number'
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      if (normalized_payload ->> 'item_count')::numeric not between 3 and 10
        or pg_catalog.trunc((normalized_payload ->> 'item_count')::numeric)
          <> (normalized_payload ->> 'item_count')::numeric
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['item_count'],
        pg_catalog.to_jsonb(((normalized_payload ->> 'item_count')::numeric)::integer)
      );
    elsif normalized_kind='best_tab' and normalized_payload ? 'item_count' then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;

    if normalized_payload ? 'mobile_image_path' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'mobile_image_path') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      payload_mobile_image_path := normalized_payload ->> 'mobile_image_path';
      if payload_mobile_image_path
        !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
      then
        raise check_violation using message = 'invalid_curation_image_path';
      end if;
    end if;
  end if;

  if not private.is_valid_home_ranked_curation(normalized_kind, normalized_payload) then
    raise invalid_parameter_value using message='invalid_curation_payload';
  end if;

  if normalized_kind='product_mosaic' and (not private.is_valid_home_mosaic(normalized_payload) or normalized_image_path is not null) then
    raise invalid_parameter_value using message='invalid_curation_mosaic';
  end if;

  if normalized_kind='hero' and not private.is_valid_home_hero_style(normalized_payload) then
    raise invalid_parameter_value using message='invalid_hero_style';
  end if;

  if normalized_kind='hero' and not private.is_valid_home_hero_alt(normalized_payload) then
    raise invalid_parameter_value using message='invalid_hero_alt';
  end if;

  if normalized_kind='product_collection' and (not private.is_valid_home_product_collection(normalized_payload)
    or normalized_image_path is not null or normalized_title~'[[:cntrl:]]') then
    raise invalid_parameter_value using message='invalid_curation_product_collection';
  end if;

  request_payload := pg_catalog.jsonb_build_object(
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  if require_saved_version then
    request_payload := request_payload || pg_catalog.jsonb_build_object('expected_updated_at',target_expected_updated_at);
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.home_curation.upserted'
      and existing_target = 'home_curations:' || target_curation_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_curation_id;
    end if;

    raise unique_violation using message = 'operation_conflict';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation:' || target_curation_id::text,
      0
    )
  );

  if normalized_ip_id is not null then
    select ip.archived_at
      into referenced_archived_at
    from public.ips as ip
    where ip.id = normalized_ip_id
    for update of ip;

    if not found then
      raise no_data_found using message = 'curation_ip_not_found';
    end if;
    if referenced_archived_at is not null then
      raise check_violation using message = 'catalog_item_archived';
    end if;
  end if;

  select curation.*
    into previous_curation
  from public.home_curations as curation
  where curation.id = target_curation_id
  for update of curation;
  curation_exists := found;
  if curation_exists and previous_curation.archived_at is not null then
    raise sqlstate 'PT409' using message='curation_archived';
  end if;

  if require_saved_version and ((curation_exists and previous_curation.updated_at is distinct from target_expected_updated_at)
    or (not curation_exists and target_expected_updated_at is not null)) then
    raise sqlstate 'PT409' using message='curation_conflict';
  end if;

  if curation_exists then
    previous_payload := pg_catalog.jsonb_build_object(
      'id', previous_curation.id,
      'kind', previous_curation.kind,
      'ip_id', previous_curation.ip_id,
      'title', previous_curation.title,
      'image_path', previous_curation.image_path,
      'link_path', previous_curation.link_path,
      'display_order', previous_curation.display_order,
      'active_from', previous_curation.active_from,
      'active_to', previous_curation.active_to,
      'enabled', previous_curation.enabled,
      'slot', previous_curation.slot,
      'payload', previous_curation.payload
    );
    previous_mobile_image_path := previous_curation.payload ->> 'mobile_image_path';
  end if;

  -- The artwork-claim trigger only guards the image_path column, so the
  -- mobile artwork carried inside payload consumes its verified upload claim
  -- here, under the same actor/kind/single-use rules (#112 contract).
  if payload_mobile_image_path is not null
    and payload_mobile_image_path is distinct from previous_mobile_image_path
  then
    update public.admin_artwork_upload_claims as claim
    set
      status = 'attached',
      attached_at = pg_catalog.clock_timestamp(),
      resolved_at = pg_catalog.clock_timestamp()
    where claim.actor_id = claim_owner_id
      and claim.path = pg_catalog.substr(
        payload_mobile_image_path,
        pg_catalog.length('public-media/') + 1
      )
      and claim.kind = 'curation'
      and claim.status = 'verified'
      and claim.verified_at is not null
      and claim.final_size is not null
      and claim.attached_at is null
      and claim.expires_at > pg_catalog.clock_timestamp();

    if not found then
      raise check_violation using message = 'unverified_artwork';
    end if;
  end if;

  if curation_exists then
    update public.home_curations
    set
      kind = normalized_kind,
      ip_id = normalized_ip_id,
      title = normalized_title,
      image_path = normalized_image_path,
      link_path = normalized_link_path,
      display_order = target_display_order,
      active_from = target_active_from,
      active_to = target_active_to,
      enabled = target_enabled,
      slot = normalized_slot,
      payload = normalized_payload
    where id = target_curation_id;
  else
    insert into public.home_curations (
      id, kind, ip_id, title, image_path, link_path,
      display_order, active_from, active_to, enabled, slot, payload
    )
    values (
      target_curation_id, normalized_kind, normalized_ip_id, normalized_title,
      normalized_image_path, normalized_link_path, target_display_order,
      target_active_from, target_active_to, target_enabled, normalized_slot,
      normalized_payload
    );
  end if;

  after_payload := pg_catalog.jsonb_build_object(
    'id', target_curation_id,
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.home_curation.upserted',
    'home_curations:' || target_curation_id::text,
    pg_catalog.jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_curation_id;
end;
$function$

create function public.admin_set_home_banner_archived(target_operation_id uuid,target_curation_id uuid,
 target_expected_updated_at timestamptz,archive_requested boolean)
returns uuid language plpgsql security definer set search_path='' as $$
declare
 actor_id uuid:=(select auth.uid()); before_row public.home_curations%rowtype; after_row public.home_curations%rowtype;
 receipt public.audit_log%rowtype; request_payload jsonb; action_name text;
begin
 perform private.require_operator_capability('store.manage',false);
 if actor_id is null then raise invalid_authorization_specification using message='auth_required';end if;
 perform 1 from public.profiles where id=actor_id and role in ('staff','admin') and suspended_at is null for share;
 if not found then raise insufficient_privilege using message='forbidden';end if;
 if target_operation_id is null or target_curation_id is null or target_expected_updated_at is null
  or not isfinite(target_expected_updated_at) or archive_requested is null then
  raise invalid_parameter_value using message='invalid_curation_archive_request';end if;
 action_name:=case when archive_requested then 'admin.home_curation.archived' else 'admin.home_curation.restored' end;
 request_payload:=jsonb_build_object('expected_updated_at',target_expected_updated_at,'archive',archive_requested);
 -- Share the writer's operation/target lock namespaces to preserve receipt and
 -- stale-version behavior across save, delete, restore and lost-response retry.
 perform pg_advisory_xact_lock(hashtextextended('admin_home_curation_operation:'||target_operation_id::text,0));
 select * into receipt from public.audit_log where id=target_operation_id;
 if found then
  if receipt.actor_id=actor_id and receipt.action=action_name
   and receipt.target='home_curations:'||target_curation_id::text and receipt.diff->'request'=request_payload then
   return target_curation_id;
  end if;
  raise unique_violation using message='operation_conflict';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('admin_home_curation:'||target_curation_id::text,0));
 select * into before_row from public.home_curations where id=target_curation_id for update;
 if not found then raise no_data_found using message='curation_not_found';end if;
 if before_row.kind<>'hero' then raise invalid_parameter_value using message='curation_archive_hero_only';end if;
 if before_row.updated_at is distinct from target_expected_updated_at then
  raise sqlstate 'PT409' using message='curation_conflict';end if;
 if (before_row.archived_at is not null)=archive_requested then
  raise invalid_parameter_value using message='curation_archive_state';end if;
 -- Keep artwork paths, consumed claims, payload, schedule and ordinary save
 -- receipts byte-for-byte. Restore never reenables an old campaign implicitly.
 update public.home_curations set archived_at=case when archive_requested then clock_timestamp() else null end,
  enabled=false where id=target_curation_id returning * into after_row;
 insert into public.audit_log(id,actor_id,action,target,diff) values(target_operation_id,actor_id,action_name,
  'home_curations:'||target_curation_id::text,jsonb_build_object('request',request_payload,'before',to_jsonb(before_row),'after',to_jsonb(after_row)));
 return target_curation_id;
end $$

