create function private.reconcile_order_collect_after_cancel() returns trigger
language plpgsql volatile security definer set search_path='' as $$declare obligation private.shipping_collect_obligations;shipment public.order_shipments;next_state text;reason text;begin
 perform 1 from public.order_shipments where order_id=new.id order by id for update;
 for obligation in select * from private.shipping_collect_obligations where order_id=new.id order by shipment_id for update loop
  if obligation.state in('void','refunded','refund_review') then continue;end if;
  select * into shipment from public.order_shipments where id=obligation.shipment_id;
  if obligation.state='planned' and shipment.shipped_at is null and shipment.delivered_at is null and shipment.status::text not in('shipping','delivered') then
   next_state:='void';reason:='order_canceled_before_dispatch';
  else next_state:='refund_review';reason:='order_canceled_collection_review';end if;
  update private.shipping_collect_obligations set state=next_state,revision=revision+1,updated_at=clock_timestamp() where shipment_id=obligation.shipment_id;
  insert into private.shipping_collect_events(operation_id,shipment_id,event,amount,evidence,previous_state,previous_revision)
   values(gen_random_uuid(),obligation.shipment_id,next_state,case when next_state='void' then 0 else obligation.amount end,
    jsonb_build_object('orderId',new.id,'reason',reason),obligation.state,obligation.revision);
 end loop;
 return new;
end $$

create function private.normalize_goods_transaction_selection(p_selection jsonb) returns jsonb
language plpgsql immutable security invoker set search_path='' as $$declare entry jsonb;result jsonb;begin
 if jsonb_typeof(p_selection) is distinct from 'array' or jsonb_array_length(p_selection) not between 1 and 19239
  or octet_length(p_selection::text)>2097152 then raise invalid_parameter_value using message='invalid_transaction_selection';end if;
 for entry in select value from jsonb_array_elements(p_selection) loop
  if not private.transaction_json_keys(entry,array['goodId','variantId','qty','inputRevision','inputValues'])
   or jsonb_typeof(entry->'goodId') is distinct from 'string' or char_length(entry->>'goodId') not between 1 and 200
   or entry->>'goodId'<>btrim(entry->>'goodId') or entry->>'goodId'~'[[:cntrl:]]'
   or jsonb_typeof(entry->'variantId') is distinct from 'string' or entry->>'variantId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or not private.transaction_uint(entry->'qty',1,2147483647) or not private.transaction_uint(entry->'inputRevision',0,2147483647)
   or jsonb_typeof(entry->'inputValues') is distinct from 'object' then raise invalid_parameter_value using message='invalid_transaction_selection';end if;
  if (select count(*) from jsonb_each(entry->'inputValues'))>5
   or (((entry->>'inputRevision')::integer=0) is distinct from (entry->'inputValues'='{}'::jsonb))
   or exists(select 1 from jsonb_each(entry->'inputValues') e where e.key!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or jsonb_typeof(e.value) is distinct from 'string' or char_length(e.value#>>'{}') not between 1 and 100
    or (e.value#>>'{}')<>btrim(e.value#>>'{}') or (e.value#>>'{}')~'[[:cntrl:]]') then
   raise invalid_parameter_value using message='invalid_transaction_selection';end if;
 end loop;
 if (select count(distinct value-'qty') from jsonb_array_elements(p_selection))<>jsonb_array_length(p_selection) then
  raise invalid_parameter_value using message='duplicate_transaction_selection';end if;
 select jsonb_agg(value order by value->>'goodId',value->>'variantId',(value->>'inputRevision')::integer,(value->'inputValues')::text)
  into result from jsonb_array_elements(p_selection);return result;
end $$

create function private.normalize_goods_transaction_address(p_address jsonb) returns jsonb
language plpgsql immutable security invoker set search_path='' as $$declare name text;phone text;postal text;address1 text;begin
 if jsonb_typeof(p_address) is distinct from 'object' or not(p_address ?& array['recipientName','phone','postalCode','address1'])
  or p_address-array['recipientName','phone','postalCode','address1','address2','deliveryNote']<>'{}'::jsonb
  or exists(select 1 from jsonb_each(p_address) e where jsonb_typeof(e.value) is distinct from 'string'
   or (e.value#>>'{}')<>btrim(e.value#>>'{}') or (e.value#>>'{}')~'[[:cntrl:]]') then
  raise invalid_parameter_value using message='invalid_checkout_address';end if;
 name:=p_address->>'recipientName';phone:=p_address->>'phone';postal:=p_address->>'postalCode';address1:=p_address->>'address1';
 if char_length(name) not between 1 and 50 or phone!~'^[0-9]{8,15}$' or postal!~'^[0-9]{5}$'
  or char_length(address1) not between 1 and 200 or char_length(coalesce(p_address->>'address2',''))>200
  or char_length(coalesce(p_address->>'deliveryNote',''))>200 then raise invalid_parameter_value using message='invalid_checkout_address';end if;
 return jsonb_build_object('recipientName',name,'phone',phone,'postalCode',postal,'address1',address1,
  'address2',coalesce(p_address->>'address2',''),'deliveryNote',coalesce(p_address->>'deliveryNote',''));
end $$

create function private.lock_goods_transaction_catalog(p_actor uuid,p_selection jsonb,p_user_coupon_id uuid) returns void
language plpgsql volatile security definer set search_path='' as $$begin
 -- All mutable catalog parents precede all variants and supply policies.
 perform 1 from public.goods g where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection)) order by g.id for update;
 perform 1 from public.goods_variants v where v.id in(select (value->>'variantId')::uuid from jsonb_array_elements(p_selection)) order by v.good_id,v.id for update;
 perform 1 from public.ips ip where ip.id in(select g.ip_id from public.goods g where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection))) order by ip.id for share;
 perform 1 from private.goods_preorder_policies p where p.id in(select v.preorder_policy_id from public.goods_variants v
  where v.id in(select (value->>'variantId')::uuid from jsonb_array_elements(p_selection))) order by p.id for update;
 perform 1 from public.fulfillment_origins o where o.id in(select g.origin_id from public.goods g
  where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection))) order by o.id for share;
 perform 1 from public.shipping_carriers c where c.code in(select o.default_carrier from public.fulfillment_origins o join public.goods g on g.origin_id=o.id
  where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection))) order by c.code for share;
 if p_user_coupon_id is not null then
  perform 1 from public.user_coupons h where h.id=p_user_coupon_id for update;
  perform 1 from public.coupons c join public.user_coupons h on h.coupon_code=c.code where h.id=p_user_coupon_id for share of c;
 end if;
 perform 1 from private.store_credit_policy where singleton for share;
 perform private.lock_store_credit_account(p_actor);
 perform 1 from private.store_credit_lots where user_id=p_actor order by expires_at,id for update;
end $$

-- Refactor the live held-validity definition into one timestamp-aware owner.
-- Existing ABI, owner, and ACL remain unchanged; v2 passes the common time only
-- after catalog/coupon/credit locks. Legacy callers keep statement-time input.
do $$declare definition text;old_header text;new_header text;begin
 definition:=pg_get_functiondef('private.evaluate_coupon_target_lines(uuid,uuid,jsonb,uuid)'::regprocedure);
 if (length(definition)-length(replace(definition,'statement_timestamp()','')))/length('statement_timestamp()')<>3 then
  raise exception 'transaction_coupon_clock_anchor_changed';end if;
 old_header:='private.evaluate_coupon_target_lines(p_user_coupon_id uuid, p_user_id uuid, p_lines jsonb, p_order_id uuid DEFAULT NULL::uuid,';
 new_header:='private.evaluate_coupon_target_lines_at(p_user_coupon_id uuid, p_user_id uuid, p_lines jsonb, p_order_id uuid, p_at timestamp with time zone,';
 if position(old_header in definition)=0 then raise exception 'transaction_coupon_signature_anchor_changed';end if;
 definition:=replace(definition,old_header,new_header);definition:=replace(definition,'statement_timestamp()','p_at');
 definition:=replace(definition,E'begin\n o_reason:=',E'begin\n if p_at is null or not isfinite(p_at) then raise invalid_parameter_value using message=''invalid_coupon_evaluation_time'';end if;\n o_reason:=');
 execute definition;
end $$

create function private.reserve_order_store_credits_explicit(p_order_id uuid,p_user_id uuid,p_subtotal bigint,p_coupon_discount bigint,p_shipping_fee bigint,
 p_requested_amount bigint,p_at timestamptz) returns bigint language plpgsql volatile security definer set search_path='' as $$
declare policy private.store_credit_policy;balance jsonb;outstanding bigint;take bigint;lot private.store_credit_lots;begin
 if p_at is null or not isfinite(p_at) or p_requested_amount is null or p_requested_amount not between 0 and 999999999999 then
  raise invalid_parameter_value using message='store_credit_amount_invalid';end if;
 perform 1 from public.orders where id=p_order_id and user_id=p_user_id and status='pending';
 if not found then raise check_violation using message='store_credit_order_invalid';end if;
 select * into policy from private.store_credit_policy where singleton for share;
 update public.orders set store_credit_policy_snapshot=case when policy.enabled then private.store_credit_policy_json()-'evidence' else null end where id=p_order_id;
 if p_requested_amount=0 then return 0;end if;
 if not policy.enabled then raise check_violation using message='store_credit_disabled';end if;
 if p_requested_amount<policy.min_use or p_requested_amount>policy.max_use or p_requested_amount>greatest(0,p_subtotal-p_coupon_discount)
  or p_subtotal::numeric+p_shipping_fee-p_coupon_discount-p_requested_amount<1000 then raise check_violation using message='store_credit_amount_invalid';end if;
 perform private.expire_store_credit_lots(p_user_id,p_at);balance:=private.store_credit_balance(p_user_id);
 if (balance->>'debt')::bigint>0 then raise check_violation using message='store_credit_debt';end if;
 if (balance->>'available')::bigint<p_requested_amount then raise check_violation using message='store_credit_insufficient';end if;
 outstanding:=p_requested_amount;
 for lot in select * from private.store_credit_lots where user_id=p_user_id and available_amount>0 and revoked_at is null and expires_at>p_at order by expires_at,id for update loop
  take:=least(outstanding,lot.available_amount);
  update private.store_credit_lots set available_amount=available_amount-take,reserved_amount=reserved_amount+take where id=lot.id;
  insert into private.store_credit_allocations(order_id,user_id,lot_id,amount,original_expires_at,restore_grace_days)
   values(p_order_id,p_user_id,lot.id,take,lot.expires_at,policy.restore_grace_days);
  insert into public.store_credit_ledger(user_id,kind,amount,available_delta,reserved_delta,order_id,lot_id,expires_at)
   values(p_user_id,'reserve',-take,-take,take,p_order_id,lot.id,lot.expires_at);
  outstanding:=outstanding-take;exit when outstanding=0;
 end loop;
 if outstanding<>0 then raise check_violation using message='store_credit_insufficient';end if;return p_requested_amount;
end $$

create or replace function private.reserve_order_store_credits(p_order_id uuid,p_user_id uuid,p_subtotal bigint,p_coupon_discount bigint,p_shipping_fee bigint)
returns bigint language plpgsql volatile security definer set search_path='' as $$declare requested bigint;begin
 select coalesce(intent.amount,0) into requested from public.orders o
  left join private.store_credit_checkout_intents intent on intent.user_id=o.user_id and intent.checkout_key=o.checkout_key
  where o.id=p_order_id and o.user_id=p_user_id and o.status='pending';
 if not found then raise check_violation using message='store_credit_order_invalid';end if;
 return private.reserve_order_store_credits_explicit(p_order_id,p_user_id,p_subtotal,p_coupon_discount,p_shipping_fee,requested,clock_timestamp());
end $$

create function private.calculate_goods_transaction_shipping(p_lines jsonb,p_destination jsonb,p_choices jsonb,p_at timestamptz) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare grouped jsonb:='[]';row record;delivery private.goods_delivery_versions;shipping_lines jsonb:='[]';base_quote jsonb;regional_quote jsonb;
 raw_group jsonb;group_goods jsonb;policy_rows jsonb;regional_rows jsonb;policy_allocations jsonb;base_allocations jsonb;regional_allocations jsonb;
 region private.shipping_region_policies;component jsonb;components jsonb;raw_groups jsonb:='[]';display_groups jsonb:='[]';good_line jsonb;
 quantity numeric;fee numeric;subtotal numeric;policy_sum numeric;regional_sum numeric;prepaid numeric;collect numeric;prepaid_total numeric:=0;collect_total numeric:=0;
 payment_mode text;contract private.shipping_collect_contract_versions;collector jsonb;contract_id uuid;regional_eligible boolean;basis text;basis_sum numeric;
begin
 for row in select good_id,origin_id,sum(qty::numeric) qty,sum(unit_price::numeric*qty) subtotal,max(fee_type) fee_type,max(individual_fee) individual_fee
  from jsonb_to_recordset(p_lines) l(good_id text,origin_id uuid,qty integer,unit_price bigint,fee_type text,individual_fee bigint)
  group by good_id,origin_id order by good_id loop
  select d.* into delivery from private.goods_transaction_configs c join private.goods_delivery_versions d on d.id=c.delivery_version_id
   where c.good_id=row.good_id and d.status='active';
  payment_mode:=case when delivery.id is null then 'prepaid' when delivery.payment_mode='buyer_choice' then coalesce(p_choices->>row.good_id,'prepaid') else delivery.payment_mode end;
  if p_choices ? row.good_id and delivery.id is not null and delivery.payment_mode<>'buyer_choice' and p_choices->>row.good_id<>delivery.payment_mode then
   return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','delivery_choice_required','goodId',row.good_id)));end if;
  if p_choices ? row.good_id and delivery.id is null and p_choices->>row.good_id<>'prepaid' then
   return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','delivery_choice_required','goodId',row.good_id)));end if;
  fee:=case when delivery.quantity_terms is not null then private.goods_quantity_delivery_fee(row.qty,delivery.quantity_terms)
   when row.fee_type='individual' then row.individual_fee else 0 end;
  grouped:=grouped||jsonb_build_array(jsonb_build_object('goodId',row.good_id,'originId',row.origin_id,'qty',row.qty,'subtotal',row.subtotal,
   'feeType',case when delivery.quantity_terms is not null then 'individual' else row.fee_type end,'individualFee',fee,'paymentMode',payment_mode,
   'deliveryPolicyId',delivery.id,'deliveryPolicyRevision',delivery.revision,'quantityTerms',delivery.quantity_terms));
  shipping_lines:=shipping_lines||jsonb_build_array(jsonb_build_object('origin_id',row.origin_id,'good_id',row.good_id,'qty',1,'unit_price',row.subtotal,
   'fee_type',case when delivery.quantity_terms is not null then 'individual' else row.fee_type end,'individual_fee',fee));
 end loop;
 base_quote:=private.calculate_goods_shipping(shipping_lines);
 regional_quote:=private.apply_shipping_region_quote(base_quote,shipping_lines,p_destination,p_at);
 if not (regional_quote->>'checkoutAllowed')::boolean then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','shipping_unresolved','goodId',null)));end if;
 for raw_group in select value from jsonb_array_elements(regional_quote->'groups') loop
  select jsonb_agg(value order by value->>'goodId') into group_goods from jsonb_array_elements(grouped) where value->>'originId'=raw_group->>'originId';
  select coalesce(sum((value->>'subtotal')::numeric),0) into policy_sum from jsonb_array_elements(group_goods) where value->>'feeType'='policy';
  select coalesce(jsonb_agg(jsonb_build_object('id',value->>'goodId','weight',case when policy_sum>0 then (value->>'subtotal')::numeric else (value->>'qty')::numeric end)),'[]')
   into policy_rows from jsonb_array_elements(group_goods) where value->>'feeType'='policy';
  policy_allocations:=case when jsonb_array_length(policy_rows)>0 then private.allocate_transaction_amount((raw_group->>'policyFee')::numeric,policy_rows) else '{}'::jsonb end;
  select jsonb_object_agg(value->>'goodId',case when value->>'feeType'='policy' then (policy_allocations->>(value->>'goodId'))::numeric else (value->>'individualFee')::numeric end)
   into base_allocations from jsonb_array_elements(group_goods);
  region:=null;if raw_group->>'policyId' is not null then select * into region from private.shipping_region_policies where id=(raw_group->>'policyId')::uuid;end if;
  regional_rows:='[]';
  for good_line in select value from jsonb_array_elements(group_goods) loop
   regional_eligible:=region.id is not null and raw_group->>'regionStatus'='surcharge' and case good_line->>'feeType'
    when 'policy' then (region.configuration->>'chargePolicyGoods')::boolean and not((region.configuration->>'waivePolicyThreshold')::boolean
     and raw_group->>'freeThreshold' is not null and (raw_group->>'policySubtotal')::numeric>=(raw_group->>'freeThreshold')::numeric)
    when 'free' then (region.configuration->>'chargeFreeGoods')::boolean else (region.configuration->>'chargeIndividualGoods')::boolean end;
   if regional_eligible then regional_rows:=regional_rows||jsonb_build_array(good_line);end if;
  end loop;
  regional_allocations:='{}';
  if jsonb_array_length(regional_rows)>0 then
   if raw_group->>'feeUnit'='per_good' then
    select jsonb_object_agg(value->>'goodId',(raw_group->>'regionalContractFee')::numeric) into regional_allocations from jsonb_array_elements(regional_rows);
   else
    select sum((base_allocations->>(value->>'goodId'))::numeric),sum((value->>'subtotal')::numeric) into basis_sum,subtotal from jsonb_array_elements(regional_rows);
    basis:=case when basis_sum>0 then 'base' when subtotal>0 then 'subtotal' else 'qty' end;
    select jsonb_agg(jsonb_build_object('id',value->>'goodId','weight',case when basis='base' then (base_allocations->>(value->>'goodId'))::numeric else (value->>basis)::numeric end))
     into regional_rows from jsonb_array_elements(regional_rows);
    regional_allocations:=private.allocate_transaction_amount((raw_group->>'regionalFee')::numeric,regional_rows);
   end if;
  end if;
  components:='[]';prepaid:=0;collect:=0;contract:=null;collector:=null;contract_id:=null;regional_sum:=0;
  for good_line in select value from jsonb_array_elements(group_goods) loop
   fee:=(base_allocations->>(good_line->>'goodId'))::numeric+coalesce((regional_allocations->>(good_line->>'goodId'))::numeric,0);
   regional_sum:=regional_sum+coalesce((regional_allocations->>(good_line->>'goodId'))::numeric,0);
   component:=jsonb_build_object('goodId',good_line->>'goodId','paymentMode',good_line->>'paymentMode',
    'baseFee',(base_allocations->>(good_line->>'goodId'))::numeric,'regionalFee',coalesce((regional_allocations->>(good_line->>'goodId'))::numeric,0),
    'totalFee',fee,'deliveryPolicyId',good_line->'deliveryPolicyId');
   components:=components||jsonb_build_array(component);
   if good_line->>'paymentMode'='collect' then collect:=collect+fee;else prepaid:=prepaid+fee;end if;
  end loop;
  if regional_sum<>(raw_group->>'regionalFee')::numeric or prepaid+collect<>(raw_group->>'finalFee')::numeric then
   raise check_violation using message='transaction_shipping_allocation_mismatch';end if;
  -- Contract readiness is required even for a zero-fee collect choice: later
  -- regional/base changes must not turn a dormant unsupported mode payable.
  if exists(select 1 from jsonb_array_elements(group_goods) where value->>'paymentMode'='collect') then
   select v.* into contract from private.shipping_collect_contracts c join private.shipping_collect_contract_versions v on v.id=c.version_id
    where c.origin_id=(raw_group->>'originId')::uuid and v.status='active';
   if not found then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','collect_not_ready','goodId',null)));end if;
   contract_id:=contract.id;collector:=jsonb_build_object('name',contract.contract_values->>'collectorName','method',contract.contract_values->>'collectionMethod',
    'refundContact',contract.contract_values->>'refundContact','instructions',contract.contract_values->>'customerInstructions');
  end if;
  prepaid_total:=prepaid_total+prepaid;collect_total:=collect_total+collect;
  if prepaid_total+collect_total>9007199254740991 then raise numeric_value_out_of_range using message='transaction_amount_overflow';end if;
  raw_groups:=raw_groups||jsonb_build_array(raw_group||jsonb_build_object('calculationVersion',2,'totalFee',prepaid,'prepaidFee',prepaid,'collectFee',collect,
   'fullFee',prepaid+collect,'components',components,'collector',collector,'collectContractId',contract_id,'collectContractSnapshot',to_jsonb(contract),
   'deliveryTerms',group_goods));
  display_groups:=display_groups||jsonb_build_array(jsonb_build_object('originId',raw_group->'originId','prepaidFee',prepaid,'collectFee',collect,
   'fullFee',prepaid+collect,'components',components,'collector',collector));
 end loop;
 return jsonb_build_object('state','calculated','prepaidFee',prepaid_total,'collectFee',collect_total,'rawGroups',raw_groups,'displayGroups',display_groups,
  'nextChangeAt',regional_quote->'nextChangeAt');
end $$

create function private.calculate_goods_transaction_locked(p_actor uuid,p_selection jsonb,p_address jsonb,p_delivery_choices jsonb,
 p_user_coupon_id uuid,p_store_credit_amount bigint,p_at timestamptz,p_line_ids jsonb,p_order_id uuid default null) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare entry jsonb;index integer:=0;good public.goods;variant public.goods_variants;price record;supply record;good_qty numeric;variant_qty numeric;
 custom_inputs jsonb;quantity_error text;priced_lines jsonb:='[]';shipping_lines jsonb:='[]';internal_lines jsonb:='[]';display_lines jsonb:='[]';policies jsonb;volume jsonb;
 discounted jsonb;line jsonb;shipping jsonb;coupon_eval record;coupon_data jsonb;coupon_lines jsonb;coupon_weights jsonb;credit_weights jsonb;
 coupon_allocations jsonb;credit_allocations jsonb;policy private.store_credit_policy;balance jsonb;available numeric;maximum numeric:=0;
 subtotal numeric;volume_total numeric;net numeric;coupon numeric:=0;credit numeric:=p_store_credit_amount;online numeric;customer numeric;
 next_change timestamptz;boundary timestamptz;card_allowed boolean:=true;bank_allowed boolean:=true;selected_policy jsonb;line_coupon numeric;line_credit numeric;
begin
 if p_at is null or not isfinite(p_at) or p_store_credit_amount is null or p_store_credit_amount not between 0 and 999999999999
  or jsonb_typeof(p_line_ids) is distinct from 'array' or jsonb_array_length(p_line_ids)<>jsonb_array_length(p_selection)
  or exists(select 1 from jsonb_array_elements(p_line_ids) id where jsonb_typeof(id) is distinct from 'string'
   or id#>>'{}'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  or (select count(distinct id) from jsonb_array_elements(p_line_ids) id)<>jsonb_array_length(p_line_ids) then
  raise invalid_parameter_value using message='invalid_transaction_calculation';end if;
 begin perform private.assert_goods_purchase_allowed(p_actor);
 exception when check_violation then
  if sqlerrm<>'goods_purchase_restricted' then raise;end if;
  return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','purchase_restricted','goodId',null)));
 end;
 select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'goodId',v.good_id,'revision',v.revision,'status',v.status,'terms',v.terms,'draftValues',v.draft_values)),'[]')
  into policies from private.goods_transaction_configs c join private.goods_volume_discount_versions v on v.id=c.volume_version_id
  where c.good_id in(select value->>'goodId' from jsonb_array_elements(p_selection));
 for entry in select value from jsonb_array_elements(p_selection) loop
  select g.* into good from public.goods g join public.ips ip on ip.id=g.ip_id
   join public.fulfillment_origins origin on origin.id=g.origin_id and origin.is_active
   where g.id=entry->>'goodId' and g.archived_at is null and g.published_at is not null and g.sale_restriction='none'
    and (g.sale_starts_at is null or g.sale_starts_at<=p_at) and (g.sale_ends_at is null or g.sale_ends_at>p_at)
    and ip.archived_at is null and ip.published_at is not null;
  if not found then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','goods_unavailable','goodId',entry->>'goodId')));end if;
  select * into variant from public.goods_variants where id=(entry->>'variantId')::uuid and good_id=good.id and archived_at is null;
  if not found then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','goods_unavailable','goodId',good.id)));end if;
  select sum((value->>'qty')::numeric) into good_qty from jsonb_array_elements(p_selection) where value->>'goodId'=good.id;
  quantity_error:=private.check_goods_purchase_quantity(good,p_actor,good_qty::bigint,true);
  if quantity_error is not null then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','purchase_limit','goodId',good.id)));end if;
  begin custom_inputs:=private.resolve_goods_custom_inputs(good.id,(entry->>'inputRevision')::integer,entry->'inputValues');
  exception when check_violation or invalid_parameter_value then
   return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','invalid_selection','goodId',good.id)));
  end;
  select * into supply from private.resolve_goods_variant_supply(variant.id,p_at);
  select sum((value->>'qty')::numeric) into variant_qty from jsonb_array_elements(p_selection) where value->>'variantId'=variant.id::text;
  if good.stock='soldout' or supply.available_qty<variant_qty or (supply.mode='preorder' and supply.state<>'open') then
   return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','goods_unavailable','goodId',good.id)));end if;
  select * into price from private.resolve_goods_variant_price(variant.id,p_at);
  priced_lines:=priced_lines||jsonb_build_array(jsonb_build_object('lineId',p_line_ids->>index,'goodId',good.id,'regularUnitPrice',price.regular_price,
   'unitPrice',price.effective_price,'qty',entry->'qty'));
  shipping_lines:=shipping_lines||jsonb_build_array(jsonb_build_object('origin_id',good.origin_id,'good_id',good.id,'qty',entry->'qty',
   'unit_price',price.effective_price,'fee_type',good.shipping_fee_type,'individual_fee',good.individual_fee));
  select value into selected_policy from jsonb_array_elements(policies) where value->>'goodId'=good.id;
  internal_lines:=internal_lines||jsonb_build_array(entry||jsonb_build_object('lineId',p_line_ids->>index,
   'goodName',good.name,'goodType',good.type,'goodIpId',good.ip_id,'originId',good.origin_id,'variantName',variant.name,
   'customInputsSnapshot',custom_inputs,'regularUnitPrice',price.regular_price,'unitPrice',price.effective_price,'pricePeriodId',price.price_period_id,
   'priceStartsAt',price.starts_at,'priceEndsAt',price.ends_at,'volumePolicySnapshot',selected_policy,
   'supplySource',supply.mode,'preorderPolicyId',supply.policy_id,'preorderPolicyRevision',supply.policy_revision,
   'preorderStartsAt',supply.starts_at,'preorderEndsAt',supply.ends_at,'preorderExpectedShipDate',supply.expected_ship_date,
   'salesPolicySnapshot',jsonb_build_object('version',2,'allowCardPayment',good.allow_card_payment,'allowBankTransfer',good.allow_bank_transfer,
    'orderQuantityLimitEnabled',good.order_quantity_limit_enabled,'minOrderQty',good.min_order_qty,'maxOrderQty',good.max_order_qty,
    'memberPurchaseLimitEnabled',good.member_purchase_limit_enabled,'memberLifetimeQtyLimit',good.member_lifetime_qty_limit,
    'saleStartsAt',good.sale_starts_at,'saleEndsAt',good.sale_ends_at,'salePeriodRevision',good.sale_period_revision)));
  select min(moment) into boundary from (
   select schedule.starts_at moment from private.goods_variant_price_periods schedule where schedule.variant_id=variant.id and schedule.state='active' and schedule.starts_at>p_at
   union all select schedule.ends_at from private.goods_variant_price_periods schedule where schedule.variant_id=variant.id and schedule.state='active' and schedule.ends_at>p_at
   union all select good.sale_starts_at where good.sale_starts_at>p_at union all select good.sale_ends_at where good.sale_ends_at>p_at
   union all select supply.next_change_at where supply.next_change_at>p_at) moments;
  next_change:=least(next_change,boundary);card_allowed:=card_allowed and good.allow_card_payment;bank_allowed:=bank_allowed and good.allow_bank_transfer;
  index:=index+1;
 end loop;
 if not card_allowed and not bank_allowed then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','payment_method_unavailable','goodId',null)));end if;
 volume:=private.calculate_goods_volume_discounts(priced_lines,policies,p_at);
 subtotal:=(volume->>'subtotal')::numeric;volume_total:=(volume->>'volumeDiscountTotal')::numeric;net:=subtotal-volume_total;
 next_change:=least(next_change,(volume->>'nextChangeAt')::timestamptz);
 shipping:=private.calculate_goods_transaction_shipping(shipping_lines,jsonb_build_object('postalCode',p_address->>'postalCode','address1',p_address->>'address1'),p_delivery_choices,p_at);
 if shipping->>'state'='blocked' then return shipping;end if;
 next_change:=least(next_change,(shipping->>'nextChangeAt')::timestamptz);
 select jsonb_agg(jsonb_build_object('good_id',value->>'goodId','subtotal',(value->>'netSubtotal')::bigint)) into coupon_lines from jsonb_array_elements(volume->'lines');
 if p_user_coupon_id is not null then
  select * into coupon_eval from private.evaluate_coupon_target_lines_at(p_user_coupon_id,p_actor,coupon_lines,p_order_id,p_at);
  if coupon_eval.o_reason is not null then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','coupon_unavailable','goodId',null)));end if;
  coupon:=least(coupon_eval.o_discount,greatest(0,net+(shipping->>'prepaidFee')::numeric-1000));
  if coupon<=0 then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','coupon_unavailable','goodId',null)));end if;
  coupon_data:=jsonb_build_object('userCouponId',p_user_coupon_id,'couponCode',coupon_eval.o_coupon_code,'eligibleSubtotal',coupon_eval.o_eligible_subtotal,
   'discount',coupon,'termsSnapshot',coupon_eval.o_terms_snapshot||jsonb_build_object('calculationVersion',2,'eligibleNetSubtotal',coupon_eval.o_eligible_subtotal));
  select min(moment) into boundary from public.user_coupons held join public.coupons definition on definition.code=held.coupon_code
   cross join lateral(values(held.usable_from),(held.expires_at),(definition.starts_at),(definition.ends_at)) moments(moment)
   where held.id=p_user_coupon_id and moment>p_at;
  next_change:=least(next_change,boundary);
 end if;
 select jsonb_agg(jsonb_build_object('id',value->>'lineId','weight',case when p_user_coupon_id is null then 0
   when coupon_data#>>'{termsSnapshot,goodsScope}'='all' or (coupon_data#>'{termsSnapshot,targetGoodIds}') ? (value->>'goodId')
   then (value->>'netSubtotal')::numeric else 0 end)) into coupon_weights from jsonb_array_elements(volume->'lines');
 coupon_allocations:=private.allocate_transaction_amount(coupon,coupon_weights);
 select * into policy from private.store_credit_policy where singleton;
 perform private.expire_store_credit_lots(p_actor,p_at);balance:=private.store_credit_balance(p_actor);available:=(balance->>'available')::numeric;
 if policy.enabled and (balance->>'debt')::numeric=0 then
  maximum:=least(policy.max_use,available,greatest(0,net-coupon),greatest(0,net+(shipping->>'prepaidFee')::numeric-coupon-1000));end if;
 if credit>0 and (credit<policy.min_use or credit>maximum) then
  return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','store_credit_unavailable','goodId',null)));end if;
 if credit>0 then
  select min(expires_at) into boundary from private.store_credit_lots where user_id=p_actor and available_amount>0 and expires_at>p_at and revoked_at is null;
  next_change:=least(next_change,boundary);
 end if;
 online:=net+(shipping->>'prepaidFee')::numeric-coupon-credit;customer:=online+(shipping->>'collectFee')::numeric;
 if online<1000 then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','below_minimum_payment','goodId',null)));end if;
 if customer>9007199254740991 or online>999999999999 then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','amount_overflow','goodId',null)));end if;
 select jsonb_agg(jsonb_build_object('id',value->>'lineId','weight',(value->>'netSubtotal')::numeric-(coupon_allocations->>(value->>'lineId'))::numeric))
  into credit_weights from jsonb_array_elements(volume->'lines');
 credit_allocations:=private.allocate_transaction_amount(credit,credit_weights);
 index:=0;
 for discounted in select value from jsonb_array_elements(volume->'lines') loop
  line:=internal_lines->index;line_coupon:=(coupon_allocations->>(line->>'lineId'))::numeric;line_credit:=(credit_allocations->>(line->>'lineId'))::numeric;
  line:=line||jsonb_build_object('subtotal',(discounted->>'unitPrice')::numeric*(discounted->>'qty')::numeric,
   'volumeUnitDiscount',discounted->'volumeUnitDiscount','volumeDiscountTotal',discounted->'volumeDiscountTotal','netSubtotal',discounted->'netSubtotal',
   'couponDiscount',line_coupon,'storeCreditDiscount',line_credit,'paidGoodsTotal',(discounted->>'netSubtotal')::numeric-line_coupon-line_credit,
   'volumePolicyId',discounted->'policyId');
  internal_lines:=jsonb_set(internal_lines,array[index::text],line);
  display_lines:=display_lines||jsonb_build_array(jsonb_build_object('lineId',line->'lineId','goodId',line->'goodId','variantId',line->'variantId','qty',line->'qty',
   'regularUnitPrice',line->'regularUnitPrice','unitPrice',line->'unitPrice','volumeUnitDiscount',line->'volumeUnitDiscount','subtotal',line->'subtotal',
   'volumeDiscountTotal',line->'volumeDiscountTotal','netSubtotal',line->'netSubtotal','couponDiscount',line->'couponDiscount',
   'storeCreditDiscount',line->'storeCreditDiscount','paidGoodsTotal',line->'paidGoodsTotal','volumePolicyId',line->'volumePolicyId'));
  index:=index+1;
 end loop;
 return jsonb_build_object('state','calculated','display',jsonb_build_object('calculationVersion',2,'currency','KRW','calculatedAt',p_at,'nextChangeAt',next_change,
  'lines',display_lines,'shipping',shipping->'displayGroups','totals',jsonb_build_object('subtotal',subtotal,'volumeDiscountTotal',volume_total,'netGoodsTotal',net,
   'couponDiscountTotal',coupon,'storeCreditTotal',credit,'prepaidShippingTotal',shipping->'prepaidFee','collectShippingTotal',shipping->'collectFee','onlineTotal',online,'customerTotal',customer),
  'userCouponId',p_user_coupon_id,'storeCreditMaximum',maximum,'paymentMethods',jsonb_build_object('card',card_allowed,'bankTransfer',bank_allowed)),
  'lines',internal_lines,'shippingRaw',shipping->'rawGroups','coupon',coupon_data,'creditPolicy',case when policy.enabled then private.store_credit_policy_json()-'evidence' else null end);
exception when numeric_value_out_of_range then
 return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','amount_overflow','goodId',null)));
end $$

create function private.quote_goods_transaction(p_actor uuid,p_source jsonb,p_selection jsonb,p_address jsonb,p_delivery_choices jsonb,
 p_user_coupon_id uuid,p_store_credit_amount bigint) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare selection jsonb;address jsonb;choices jsonb;line_ids jsonb;at_time timestamptz;expires timestamptz;calculation jsonb;quote_id uuid;
begin
 perform private.lock_goods_transaction_source(p_actor,p_source);
 perform private.assert_goods_transaction_actor(p_actor);
 selection:=private.normalize_goods_transaction_selection(p_selection);
 if p_address is null or p_address='null'::jsonb then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','address_required','goodId',null)));end if;
 address:=private.normalize_goods_transaction_address(p_address);choices:=private.normalize_goods_transaction_choices(p_delivery_choices,selection);
 perform private.lock_goods_transaction_catalog(p_actor,selection,p_user_coupon_id);
 perform private.assert_goods_transaction_runtime();
 at_time:=clock_timestamp();
 -- Delete expired actor quote PII while the actor lock serializes issuance.
 delete from private.goods_transaction_quotes where actor_id=p_actor and expires_at<=at_time;
 if (select count(*) from private.goods_transaction_quotes where actor_id=p_actor and expires_at>at_time and order_id is null)>=10 then
  delete from private.goods_transaction_quotes where id=(select id from private.goods_transaction_quotes where actor_id=p_actor and expires_at>at_time and order_id is null order by created_at,id limit 1);
 end if;
 select jsonb_agg(gen_random_uuid() order by position) into line_ids from jsonb_array_elements(selection) with ordinality selected(value,position);
 calculation:=private.calculate_goods_transaction_locked(p_actor,selection,address,choices,p_user_coupon_id,p_store_credit_amount,at_time,line_ids);
 if calculation->>'state'='blocked' then return calculation;end if;
 expires:=least(at_time+interval '10 minutes',(calculation#>>'{display,nextChangeAt}')::timestamptz);
 if expires<=clock_timestamp() then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','source_changed','goodId',null)));end if;
 if octet_length(calculation::text)>2097152 then raise program_limit_exceeded using message='transaction_quote_too_large';end if;
 insert into private.goods_transaction_quotes(actor_id,source,selection,address,delivery_choices,user_coupon_id,store_credit_amount,line_ids,calculation,created_at,expires_at)
  values(p_actor,p_source,selection,address,choices,p_user_coupon_id,p_store_credit_amount,line_ids,calculation,at_time,expires) returning id into quote_id;
 return jsonb_build_object('state','quoted','quoteId',quote_id,'expiresAt',expires,'display',calculation->'display');
end $$

create function private.replay_goods_transaction_receipt(p_actor uuid,p_source jsonb,p_quote_id uuid,p_checkout_key uuid,
 p_payment_method public.order_payment_method) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare existing private.order_goods_transactions;method public.order_payment_method;begin
 perform private.lock_goods_transaction_source(p_actor,p_source);
 if p_quote_id is null or p_checkout_key is null or p_payment_method is null then raise invalid_parameter_value using message='invalid_transaction_replay';end if;
 select * into existing from private.order_goods_transactions where actor_id=p_actor and checkout_key=p_checkout_key;
 if not found then return null;end if;
 select payment_method into method from public.orders where id=existing.order_id;
 if existing.quote_id<>p_quote_id or existing.source_kind<>p_source->>'kind' or existing.source_id<>(p_source->>'id')::uuid
  or existing.source_revision<>p_source->>'revision' or method<>p_payment_method then raise sqlstate 'PT409' using message='checkout_key_conflict';end if;
 return existing.original_receipt;
end $$

create function private.place_goods_transaction(p_actor uuid,p_source jsonb,p_selection jsonb,p_address jsonb,p_quote_id uuid,p_checkout_key uuid,
 p_payment_method public.order_payment_method) returns uuid language plpgsql volatile security definer set search_path='' as $$
<<transaction_place>>
declare selection jsonb;address jsonb;existing private.order_goods_transactions;quoted private.goods_transaction_quotes;calculation jsonb;
 order_id uuid;at_time timestamptz;expires timestamptz;request_salt uuid:=gen_random_uuid();receipt jsonb;totals jsonb;line jsonb;coupon jsonb;
 raw_group jsonb;component jsonb;shipment_id uuid;shipping_snapshot jsonb;reserved_credit bigint;item_id uuid;delivery_terms jsonb;
begin
 perform private.lock_goods_transaction_source(p_actor,p_source);
 if p_quote_id is null or p_checkout_key is null or p_payment_method is null then raise invalid_parameter_value using message='invalid_transaction_place';end if;
 selection:=private.normalize_goods_transaction_selection(p_selection);address:=private.normalize_goods_transaction_address(p_address);
 -- Durable success replay is intentionally before quote expiry/PII cleanup,
 -- current cart, current source lifecycle, and present-day price calculations.
 select * into existing from private.order_goods_transactions where actor_id=p_actor and checkout_key=p_checkout_key;
 if found then
  if existing.quote_id<>p_quote_id or existing.source_kind<>p_source->>'kind' or existing.source_id<>(p_source->>'id')::uuid
   or existing.source_revision<>p_source->>'revision' or existing.request_digest is distinct from
    private.goods_transaction_request_digest(existing.request_salt,p_source,selection,address,p_quote_id,p_payment_method) then
   raise sqlstate 'PT409' using message='checkout_key_conflict';end if;
  return existing.order_id;
 end if;
 if exists(select 1 from public.orders where user_id=p_actor and checkout_key=p_checkout_key) then raise sqlstate 'PT409' using message='checkout_key_conflict';end if;
 perform private.assert_goods_transaction_actor(p_actor);
 select * into quoted from private.goods_transaction_quotes where id=p_quote_id and actor_id=p_actor for update;
 if not found or quoted.source is distinct from p_source or quoted.selection is distinct from selection or quoted.address is distinct from address then
  raise sqlstate 'PT409' using message='transaction_quote_changed';end if;
 if quoted.order_id is not null then raise sqlstate 'PT409' using message='transaction_quote_already_used';end if;
 if quoted.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='transaction_quote_expired';end if;
 if p_source->>'kind'='gift' and to_regprocedure('private.bind_goods_transaction_delivery_snapshot(uuid,uuid,jsonb,jsonb,jsonb)') is null then
  raise check_violation using message='gift_delivery_owner_not_ready';end if;
 expires:=case when p_payment_method='bank_transfer' then clock_timestamp()+interval '24 hours' else clock_timestamp()+interval '15 minutes' end;
 insert into public.orders(user_id,status,total,shipping_fee,address,expires_at,checkout_key,payment_method,calculation_version)
  values(p_actor,'pending',0,0,case when p_source->>'kind'='gift' then null else address end,expires,p_checkout_key,p_payment_method,2) returning id into order_id;
 perform private.assert_first_purchase_checkout(p_actor,order_id);
 perform private.lock_goods_transaction_catalog(p_actor,selection,quoted.user_coupon_id);
 perform private.assert_goods_transaction_runtime();
 at_time:=clock_timestamp();
 if quoted.expires_at<=at_time then raise sqlstate 'PT409' using message='transaction_quote_expired';end if;
 calculation:=private.calculate_goods_transaction_locked(p_actor,selection,address,quoted.delivery_choices,quoted.user_coupon_id,quoted.store_credit_amount,at_time,quoted.line_ids,order_id);
 if calculation->>'state'<>'calculated' or private.goods_transaction_calculation_contract(calculation) is distinct from private.goods_transaction_calculation_contract(quoted.calculation) then
  raise sqlstate 'PT409' using message='transaction_quote_changed';end if;
 if not (calculation#>>array['display','paymentMethods',case when p_payment_method='bank_transfer' then 'bankTransfer' else 'card' end])::boolean then
  raise check_violation using message='transaction_payment_method_unavailable';end if;
 totals:=calculation#>'{display,totals}';receipt:=jsonb_build_object('orderId',order_id,'quoteId',p_quote_id,'display',calculation->'display');
 insert into private.order_goods_transactions(order_id,actor_id,source_kind,source_id,source_revision,quote_id,checkout_key,request_digest,request_salt,original_receipt)
  values(order_id,p_actor,p_source->>'kind',(p_source->>'id')::uuid,p_source->>'revision',p_quote_id,p_checkout_key,
   private.goods_transaction_request_digest(request_salt,p_source,selection,address,p_quote_id,p_payment_method),request_salt,receipt);
 update private.goods_transaction_quotes set order_id=transaction_place.order_id where id=p_quote_id;
 if p_source->>'kind'='gift' then
  perform private.bind_goods_transaction_delivery_snapshot(order_id,p_actor,p_source,address,calculation->'shippingRaw');
 end if;
 for line in select value from jsonb_array_elements(calculation->'lines') loop
  if line->>'supplySource'='stock' then perform private.change_goods_variant_stock(line->>'goodId',(line->>'variantId')::uuid,-(line->>'qty')::bigint);end if;
  item_id:=(line->>'lineId')::uuid;
  insert into public.order_items(id,order_id,good_id,variant_id,qty,unit_price,good_name_snapshot,good_type_snapshot,good_ip_id_snapshot,
   regular_unit_price_snapshot,price_period_id,price_evaluated_at,sales_policy_snapshot,supply_source,preorder_policy_id,preorder_expected_ship_date,
   preorder_snapshot,custom_inputs_snapshot,volume_unit_discount,volume_discount_total,volume_discount_snapshot)
  values(item_id,order_id,line->>'goodId',(line->>'variantId')::uuid,(line->>'qty')::integer,(line->>'unitPrice')::integer,
   line->>'goodName',line->>'goodType',line->>'goodIpId',(line->>'regularUnitPrice')::integer,(line->>'pricePeriodId')::uuid,at_time,line->'salesPolicySnapshot',
   line->>'supplySource',(line->>'preorderPolicyId')::uuid,(line->>'preorderExpectedShipDate')::date,
   case when line->>'supplySource'='preorder' then jsonb_build_object('version',1,'policyId',line->'preorderPolicyId','policyRevision',line->'preorderPolicyRevision',
    'startsAt',line->'preorderStartsAt','endsAt',line->'preorderEndsAt','expectedShipDate',line->'preorderExpectedShipDate') end,
   nullif(line->'customInputsSnapshot','null'::jsonb),(line->>'volumeUnitDiscount')::bigint,(line->>'volumeDiscountTotal')::bigint,
   jsonb_build_object('calculationVersion',2,'policy',line->'volumePolicySnapshot','applied',line->>'volumePolicyId' is not null));
  if line->>'supplySource'='preorder' then perform private.reserve_goods_preorder_item(item_id,at_time);end if;
  insert into private.order_price_allocations(order_item_id,order_id,calculation_version,subtotal,volume_discount,net_subtotal,coupon_discount,store_credit_discount,paid_goods_total)
   values(item_id,order_id,2,(line->>'subtotal')::bigint,(line->>'volumeDiscountTotal')::bigint,(line->>'netSubtotal')::bigint,
    (line->>'couponDiscount')::bigint,(line->>'storeCreditDiscount')::bigint,(line->>'paidGoodsTotal')::bigint);
 end loop;
 coupon:=calculation->'coupon';
 if quoted.user_coupon_id is not null then
  perform private.reserve_first_purchase_coupon(order_id,p_actor,coupon->>'couponCode');
  update public.user_coupons set status='used',used_at=at_time,used_order_id=order_id where id=quoted.user_coupon_id and user_id=p_actor and status<>'used';
  if not found then raise check_violation using message='coupon_already_used';end if;
  insert into public.coupon_redemptions(user_coupon_id,coupon_code,user_id,order_id,discount_amount,eligible_subtotal,terms_snapshot)
   values(quoted.user_coupon_id,coupon->>'couponCode',p_actor,order_id,(coupon->>'discount')::bigint,(coupon->>'eligibleSubtotal')::bigint,coupon->'termsSnapshot');
 end if;
 reserved_credit:=private.reserve_order_store_credits_explicit(order_id,p_actor,(totals->>'netGoodsTotal')::bigint,(totals->>'couponDiscountTotal')::bigint,
  (totals->>'prepaidShippingTotal')::bigint,quoted.store_credit_amount,at_time);
 if reserved_credit<>(totals->>'storeCreditTotal')::bigint then raise check_violation using message='transaction_credit_snapshot_mismatch';end if;
 shipping_snapshot:=private.goods_transaction_public_shipping(p_source->>'kind',calculation->'shippingRaw');
 update public.orders set total=(totals->>'onlineTotal')::bigint,shipping_fee=(totals->>'prepaidShippingTotal')::bigint,
  volume_discount_total=(totals->>'volumeDiscountTotal')::bigint,discount_total=(totals->>'couponDiscountTotal')::bigint,
  store_credit_total=reserved_credit,shipping_collect_total=(totals->>'collectShippingTotal')::bigint,shipping_fee_breakdown=shipping_snapshot where id=order_id;
 perform private.create_order_shipments(order_id);
 for raw_group in select value from jsonb_array_elements(calculation->'shippingRaw') loop
  update public.order_shipments set shipping_collect_fee=(raw_group->>'collectFee')::bigint
   where order_shipments.order_id=transaction_place.order_id and origin_id=(raw_group->>'originId')::uuid returning id into shipment_id;
  for component in select value from jsonb_array_elements(raw_group->'components') loop
   select value into delivery_terms from jsonb_array_elements(raw_group->'deliveryTerms') where value->>'goodId'=component->>'goodId';
   insert into private.shipping_charge_components(order_id,shipment_id,good_id,origin_id,calculation_version,payment_mode,base_fee,regional_fee,total_fee,
    delivery_policy_id,collect_contract_id,terms_snapshot)
   values(order_id,shipment_id,component->>'goodId',(raw_group->>'originId')::uuid,2,component->>'paymentMode',(component->>'baseFee')::bigint,
    (component->>'regionalFee')::bigint,(component->>'totalFee')::bigint,(component->>'deliveryPolicyId')::uuid,(raw_group->>'collectContractId')::uuid,
    jsonb_build_object('deliveryTerms',delivery_terms,'regionalPolicyId',raw_group->'policyId','regionalPolicyVersion',raw_group->'policyVersion',
     'regionStatus',raw_group->'regionStatus','collectContract',raw_group->'collectContractSnapshot'));
  end loop;
  if (raw_group->>'collectFee')::bigint>0 then
   insert into private.shipping_collect_obligations(shipment_id,order_id,amount,contract_snapshot)
    values(shipment_id,order_id,(raw_group->>'collectFee')::bigint,raw_group->'collectContractSnapshot');
   insert into private.shipping_collect_events(operation_id,shipment_id,event,amount,evidence)
    values(gen_random_uuid(),shipment_id,'planned',(raw_group->>'collectFee')::bigint,jsonb_build_object('orderId',order_id,'quoteId',p_quote_id));
  end if;
 end loop;
 if not private.goods_order_snapshot_matches(order_id,(totals->>'onlineTotal')::bigint,(totals->>'prepaidShippingTotal')::bigint) then
  raise check_violation using message='transaction_order_snapshot_mismatch';end if;
 if quoted.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='transaction_quote_expired';end if;
 perform private.assert_order_goods_sale_period(order_id);
 if p_payment_method='bank_transfer' then
  perform public.prepare_goods_payment_attempt(p_actor,order_id,'bank_transfer');
  insert into public.notifications(user_id,type,title,body,link_path,source_type,source_id,dedupe_key)
   values(p_actor,'order_bank_transfer_pending','입금 안내를 확인해주세요',format('%s원을 기한 안에 입금해주세요. 입금자명 끝에 주문코드 %s를 붙이면 확인이 빨라집니다.',
    to_char((totals->>'onlineTotal')::bigint,'FM999,999,999,999,999,999'),private.bank_transfer_deposit_code(order_id)),
    '/checkout/'||order_id::text,'order',order_id::text,'order:bank_transfer_pending:'||order_id::text) on conflict(user_id,dedupe_key) do nothing;
 end if;
 return order_id;
end $$

-- Preserve the current v1 amount AND preorder-reservation guard verbatim.
do $$declare definition text;begin
 definition:=pg_get_functiondef('private.goods_order_snapshot_matches(uuid,bigint,bigint)'::regprocedure);
 if position('reservation.state' in definition)=0 or position('reservation.qty' in definition)=0 then raise exception 'transaction_legacy_snapshot_anchor_changed';end if;
 definition:=replace(definition,'private.goods_order_snapshot_matches(','private.goods_order_snapshot_matches_v1(');execute definition;
end $$

create function private.guard_order_transaction_terms() returns trigger
language plpgsql volatile security definer set search_path='' as $$declare version integer;begin
 select calculation_version into version from public.orders where id=new.order_id;
 if version=2 then
  if not exists(select 1 from private.order_goods_transactions where order_id=new.order_id) then
   raise check_violation using message='transaction_order_binding_required';end if;
 elsif exists(select 1 from private.goods_transaction_configs c left join private.goods_volume_discount_versions v on v.id=c.volume_version_id
  left join private.goods_delivery_versions d on d.id=c.delivery_version_id where c.good_id=new.good_id and (v.status='active' or d.status='active')) then
  raise check_violation using message='checkout_contract_upgrade_required';
 elsif new.volume_unit_discount<>0 or new.volume_discount_total<>0 then raise check_violation using message='transaction_order_binding_required';end if;
 return new;
end $$

create function private.cart_goods_transaction_expected_selection(p_expected_cart jsonb) returns jsonb
language plpgsql immutable security invoker set search_path='' as $$declare selection jsonb;begin
 if jsonb_typeof(p_expected_cart) is distinct from 'array' or jsonb_array_length(p_expected_cart) not between 1 and 19239
  or exists(select 1 from jsonb_array_elements(p_expected_cart) r where not private.transaction_json_keys(r,array['good_id','variant_id','qty','input_revision','input_values'])) then
  raise invalid_parameter_value using message='invalid_checkout_cart_snapshot';end if;
 select jsonb_agg(jsonb_build_object('goodId',value->'good_id','variantId',value->'variant_id','qty',value->'qty',
  'inputRevision',value->'input_revision','inputValues',value->'input_values')) into selection from jsonb_array_elements(p_expected_cart);
 return private.normalize_goods_transaction_selection(selection);
end $$

create function private.assert_cart_goods_transaction_selection(p_actor uuid,p_selection jsonb) returns void
language plpgsql volatile security definer set search_path='' as $$declare actual jsonb;begin
 select coalesce(jsonb_agg(jsonb_build_object('goodId',good_id,'variantId',variant_id,'qty',qty,'inputRevision',input_revision,'inputValues',input_values)
  order by good_id,variant_id,input_revision,input_values::text),'[]') into actual from public.cart_items where user_id=p_actor;
 if actual is distinct from p_selection then raise sqlstate 'PT409' using message='cart_snapshot_changed';end if;
end $$

create function public.quote_cart_goods_transaction(p_user_id uuid,p_expected_cart jsonb,p_address jsonb,p_delivery_choices jsonb,
 p_user_coupon_id uuid,p_store_credit_amount bigint) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare selection jsonb;source jsonb;selected_coupon uuid;begin
 selection:=private.cart_goods_transaction_expected_selection(p_expected_cart);source:=private.goods_cart_transaction_source(p_user_id,selection);
 perform private.lock_goods_transaction_source(p_user_id,source);
 perform private.assert_cart_goods_transaction_selection(p_user_id,selection);
 select user_coupon_id into selected_coupon from public.cart_coupon_selections where user_id=p_user_id;
 if selected_coupon is distinct from p_user_coupon_id then raise sqlstate 'PT409' using message='coupon_snapshot_changed';end if;
 return private.quote_goods_transaction(p_user_id,source,selection,p_address,p_delivery_choices,p_user_coupon_id,p_store_credit_amount);
end $$

create function public.place_cart_goods_transaction(p_user_id uuid,p_expected_cart jsonb,p_address jsonb,p_quote_id uuid,p_checkout_key uuid,
 p_payment_method public.order_payment_method) returns uuid language plpgsql volatile security definer set search_path='' as $$
declare selection jsonb;source jsonb;selected_coupon uuid;quoted_coupon uuid;result uuid;begin
 selection:=private.cart_goods_transaction_expected_selection(p_expected_cart);source:=private.goods_cart_transaction_source(p_user_id,selection);
 perform private.lock_goods_transaction_source(p_user_id,source);
 if exists(select 1 from private.order_goods_transactions where actor_id=p_user_id and checkout_key=p_checkout_key) then
  return private.place_goods_transaction(p_user_id,source,selection,p_address,p_quote_id,p_checkout_key,p_payment_method);end if;
 perform private.assert_cart_goods_transaction_selection(p_user_id,selection);
 select user_coupon_id into selected_coupon from public.cart_coupon_selections where user_id=p_user_id;
 select user_coupon_id into quoted_coupon from private.goods_transaction_quotes where id=p_quote_id and actor_id=p_user_id;
 if found and selected_coupon is distinct from quoted_coupon then raise sqlstate 'PT409' using message='coupon_snapshot_changed';end if;
 result:=private.place_goods_transaction(p_user_id,source,selection,p_address,p_quote_id,p_checkout_key,p_payment_method);
 -- Only this adapter owns the live cart. Gift/subscription never read it.
 delete from public.cart_items cart where user_id=p_user_id and exists(select 1 from jsonb_array_elements(selection) selected
  where selected->>'goodId'=cart.good_id and (selected->>'variantId')::uuid=cart.variant_id and (selected->>'qty')::integer=cart.qty
   and (selected->>'inputRevision')::integer=cart.input_revision and selected->'inputValues'=cart.input_values);
 delete from public.cart_coupon_selections where user_id=p_user_id and user_coupon_id=quoted_coupon;
 return result;
end $$

create function public.resume_cart_goods_transaction(p_user_id uuid,p_quote_id uuid,p_checkout_key uuid,p_payment_method public.order_payment_method,
 p_allow_new boolean default false) returns uuid language plpgsql volatile security definer set search_path='' as $$
declare existing private.order_goods_transactions;quoted private.goods_transaction_quotes;source jsonb;receipt jsonb;expected_cart jsonb;begin
 perform private.lock_goods_transaction_actor(p_user_id);
 if p_quote_id is null or p_checkout_key is null or p_payment_method is null or p_allow_new is null then
  raise invalid_parameter_value using message='invalid_transaction_resume';end if;
 select * into existing from private.order_goods_transactions where actor_id=p_user_id and checkout_key=p_checkout_key;
 if found then
  if existing.source_kind<>'cart' then raise sqlstate 'PT409' using message='checkout_key_conflict';end if;
  source:=jsonb_build_object('kind',existing.source_kind,'id',existing.source_id,'revision',existing.source_revision);
  receipt:=private.replay_goods_transaction_receipt(p_user_id,source,p_quote_id,p_checkout_key,p_payment_method);
  return (receipt->>'orderId')::uuid;
 end if;
 if not p_allow_new then raise check_violation using message='transaction_new_payment_disabled';end if;
 select * into quoted from private.goods_transaction_quotes where id=p_quote_id and actor_id=p_user_id;
 if not found or quoted.source->>'kind'<>'cart' or quoted.source->>'id'<>p_user_id::text then
  raise sqlstate 'PT409' using message='transaction_quote_expired';end if;
 select jsonb_agg(jsonb_build_object('good_id',value->'goodId','variant_id',value->'variantId','qty',value->'qty',
  'input_revision',value->'inputRevision','input_values',value->'inputValues')) into expected_cart from jsonb_array_elements(quoted.selection);
 return public.place_cart_goods_transaction(p_user_id,expected_cart,quoted.address,p_quote_id,p_checkout_key,p_payment_method);
end $$

create function public.get_my_goods_transaction_receipt(p_order_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare actor uuid:=auth.uid();receipt jsonb;begin
 if actor is null then raise insufficient_privilege using message='auth_required';end if;
 select original_receipt into receipt from private.order_goods_transactions where order_id=p_order_id and actor_id=actor;
 return receipt;
end $$

create function public.purge_expired_goods_transaction_quotes(p_limit integer default 1000) returns integer
language plpgsql volatile security definer set search_path='' as $$declare deleted integer;begin
 if p_limit is null or p_limit not between 1 and 10000 then raise invalid_parameter_value using message='invalid_quote_cleanup_limit';end if;
 with expired as(select id from private.goods_transaction_quotes where expires_at<=clock_timestamp() order by expires_at,id for update skip locked limit p_limit)
 delete from private.goods_transaction_quotes q using expired where q.id=expired.id;
 get diagnostics deleted=row_count;return deleted;
end $$

-- Existing profile-first cart mutations could form a three-session cycle with
-- account suspension and a quote holding the cart lock. Acquire the common
-- actor/account/profile order before any cart or catalog row is touched.
do $$declare signature regprocedure;definition text;anchor text:='  perform private.assert_active_user(actor);';begin
 foreach signature in array array['private.set_cart_quantity_with_inputs(text,uuid,integer,integer,jsonb)'::regprocedure,
  'public.merge_cart_items(jsonb)'::regprocedure,'public.add_cart_selection(text,jsonb)'::regprocedure] loop
  definition:=pg_get_functiondef(signature);
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'transaction_cart_lock_anchor_changed: %',signature;end if;
  definition:=replace(definition,anchor,E'  perform private.lock_goods_transaction_actor(actor);\n'||anchor);execute definition;
  perform private.register_operator_internal_contract(signature);
 end loop;
end $$

do $$declare item regclass;fn regprocedure;begin
 foreach item in array array['private.goods_transaction_quotes'::regclass,'private.order_goods_transactions'::regclass,
  'private.order_price_allocations'::regclass,'private.shipping_charge_components'::regclass,
  'private.shipping_collect_obligations'::regclass,'private.shipping_collect_events'::regclass] loop
  execute format('alter table %s enable row level security',item);
  execute format('revoke all on %s from public,anon,authenticated,service_role',item);
 end loop;
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'
  and p.proname=any(array['normalize_goods_transaction_selection','normalize_goods_transaction_address','normalize_goods_transaction_choices',
   'assert_goods_transaction_actor','assert_goods_transaction_runtime','lock_goods_transaction_catalog','evaluate_coupon_target_lines_at','reserve_order_store_credits_explicit','reconcile_order_collect_after_cancel',
   'calculate_goods_transaction_shipping','calculate_goods_transaction_locked','goods_transaction_calculation_contract','quote_goods_transaction',
   'goods_transaction_public_shipping','goods_transaction_request_digest','replay_goods_transaction_receipt','place_goods_transaction','goods_transaction_snapshot_matches',
   'goods_order_snapshot_matches_v1','guard_order_transaction_terms','cart_goods_transaction_expected_selection','goods_cart_transaction_source',
   'assert_cart_goods_transaction_selection']) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',fn);
  execute format('grant execute on function %s to postgres',fn);
  perform private.register_operator_internal_contract(fn);
 end loop;
end $$

revoke all on function public.quote_cart_goods_transaction(uuid,jsonb,jsonb,jsonb,uuid,bigint),
 public.place_cart_goods_transaction(uuid,jsonb,jsonb,uuid,uuid,public.order_payment_method),public.get_my_goods_transaction_receipt(uuid),
 public.resume_cart_goods_transaction(uuid,uuid,uuid,public.order_payment_method,boolean),
 public.get_goods_transaction_runtime_enabled(),public.get_goods_transaction_offers(text[]),public.purge_expired_goods_transaction_quotes(integer) from public,anon,authenticated,service_role

grant execute on function public.quote_cart_goods_transaction(uuid,jsonb,jsonb,jsonb,uuid,bigint),
 public.place_cart_goods_transaction(uuid,jsonb,jsonb,uuid,uuid,public.order_payment_method),
 public.resume_cart_goods_transaction(uuid,uuid,uuid,public.order_payment_method,boolean),public.purge_expired_goods_transaction_quotes(integer) to service_role

-- A deployment with pg_cron gets bounded cleanup. Disposable clones omit cron.
do $$begin
 if exists(select 1 from pg_extension where extname='pg_cron') then
  perform cron.schedule('goods-transaction-quote-cleanup','*/5 * * * *','select public.purge_expired_goods_transaction_quotes(10000)');
 end if;
end $$

create function private.gift_require_runtime() returns void language plpgsql volatile security definer set search_path='' as $$begin
 perform singleton from private.gift_runtime where singleton and enabled and privacy_ready for share;
 if not found then
  raise object_not_in_prerequisite_state using message='gift_not_available';end if;
end $$

create function private.gift_lock_subjects(p_actors uuid[]) returns void
language plpgsql volatile security definer set search_path='' as $$declare subject uuid;begin
 -- Match the common transaction actor lock before account-action/profile locks.
 -- All participants are known before taking any source or domain row lock.
 for subject in select distinct id from unnest(p_actors) ids(id) where id is not null order by id loop
  perform pg_advisory_xact_lock(hashtextextended(subject::text,0));
 end loop;
 for subject in select distinct id from unnest(p_actors) ids(id) where id is not null order by id loop
  perform private.lock_account_action_subject(subject);
 end loop;
 perform 1 from public.profiles where id=any(p_actors) order by id for share;
end $$

create function private.gift_lock(p_id uuid,p_extra_actor uuid default null) returns private.gift_intents
language plpgsql volatile security definer set search_path='' as $$
declare gift private.gift_intents;previous_recipient uuid;begin
 select * into gift from private.gift_intents where id=p_id;
 if not found then raise no_data_found using message='gift_not_found';end if;
 previous_recipient:=gift.recipient_id;
 perform private.gift_lock_subjects(array[gift.sender_id,gift.recipient_id,p_extra_actor]);
 perform private.lock_goods_transaction_source(gift.sender_id,private.gift_source(gift));
 select * into gift from private.gift_intents where id=p_id for update;
 -- Never acquire a newly bound recipient lock after the source lock. The caller
 -- reloads and retries with the current complete participant set instead.
 if gift.recipient_id is distinct from previous_recipient then raise sqlstate 'PT409' using message='gift_changed';end if;
 return gift;
end $$

create function private.gift_operation_replay(p_actor uuid,p_gift_id uuid,p_kind text,p_request jsonb,p_operation_id uuid) returns boolean
language plpgsql volatile security definer set search_path='' as $$declare receipt private.gift_operations;begin
 if p_operation_id is null then raise invalid_parameter_value using message='gift_operation_required';end if;
 perform pg_advisory_xact_lock(hashtextextended('gift-operation:'||p_operation_id::text,0));
 select * into receipt from private.gift_operations where id=p_operation_id;
 if not found then return false;end if;
 if receipt.actor_id is distinct from p_actor or receipt.gift_id<>p_gift_id or receipt.kind<>p_kind
  or receipt.request_hash<>encode(extensions.digest(p_request::text,'sha256'),'hex') then raise unique_violation using message='gift_operation_conflict';end if;
 return true;
end $$

create function private.gift_record_operation(p_actor uuid,p_gift_id uuid,p_kind text,p_request jsonb,p_operation_id uuid) returns void
language plpgsql volatile security definer set search_path='' as $$declare gift private.gift_intents;begin
 select * into gift from private.gift_intents where id=p_gift_id;
 insert into private.gift_operations(id,actor_id,gift_id,kind,request_hash,revision)
 values(p_operation_id,p_actor,p_gift_id,p_kind,encode(extensions.digest(p_request::text,'sha256'),'hex'),gift.revision);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_actor,'gift.'||p_kind,'gift:'||p_gift_id,
  jsonb_build_object('giftId',p_gift_id,'state',gift.state,'revision',gift.revision));
end $$

create function private.gift_selection_display(p_selection jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare item jsonb;good public.goods;variant public.goods_variants;custom jsonb;result jsonb:='[]';begin
 if jsonb_typeof(p_selection) is distinct from 'array' or jsonb_array_length(p_selection) not between 1 and 100 or octet_length(p_selection::text)>100000 then
  raise invalid_parameter_value using message='gift_selection_invalid';end if;
 if (select count(distinct jsonb_build_array(e->'goodId',e->'variantId',e->'inputRevision',e->'inputValues')) from jsonb_array_elements(p_selection)e)<>jsonb_array_length(p_selection) then
  raise invalid_parameter_value using message='gift_selection_duplicate';end if;
 for item in select e from jsonb_array_elements(p_selection)e loop
  if not private.transaction_json_keys(item,array['goodId','variantId','qty','inputRevision','inputValues'])
   or jsonb_typeof(item->'goodId') is distinct from 'string' or char_length(item->>'goodId') not between 1 and 200
   or jsonb_typeof(item->'variantId') is distinct from 'string' or item->>'variantId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or not private.transaction_uint(item->'qty',1,2147483647) or not private.transaction_uint(item->'inputRevision',0,2147483647)
   or jsonb_typeof(item->'inputValues') is distinct from 'object' or (select count(*) from jsonb_object_keys(item->'inputValues'))>5
   or exists(select 1 from jsonb_each(item->'inputValues')e where e.key!~'^[0-9a-f-]{36}$' or jsonb_typeof(e.value)<>'string' or char_length(e.value#>>'{}')>100) then
   raise invalid_parameter_value using message='gift_selection_invalid';end if;
  select g.* into good from public.goods g join public.ips ip on ip.id=g.ip_id where g.id=item->>'goodId' and g.archived_at is null and g.published_at is not null
   and g.sale_restriction='none' and ip.archived_at is null and ip.published_at is not null;
  if not found then raise no_data_found using message='gift_good_unavailable';end if;
  select * into variant from public.goods_variants where id=(item->>'variantId')::uuid and good_id=good.id and archived_at is null;
  if not found then raise no_data_found using message='gift_variant_unavailable';end if;
  custom:=private.resolve_goods_custom_inputs(good.id,(item->>'inputRevision')::integer,item->'inputValues');
  result:=result||jsonb_build_array(jsonb_build_object('goodId',good.id,'variantId',variant.id,'name',good.name,'variantName',variant.name,
   'qty',(item->>'qty')::integer,'imagePath',good.image_path,'customInputs',custom));
 end loop;return result;
end $$

create function private.gift_detail(p_actor uuid,p_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare gift private.gift_intents;address private.gift_recipient_addresses;purchase public.orders;party text;effective_state text;delivery jsonb;begin
 select * into gift from private.gift_intents where id=p_id and (sender_id=p_actor or recipient_id=p_actor);
 if not found or p_actor is null then return null;end if;
 party:=case when gift.sender_id=p_actor then 'sender' else 'recipient' end;
 effective_state:=case when gift.order_id is null and gift.state in('awaiting_acceptance','accepted') and gift.expires_at<=statement_timestamp() then 'expired' else gift.state end;
 select * into address from private.gift_recipient_addresses where gift_id=gift.id;
 select * into purchase from public.orders where id=gift.order_id;
 if purchase.id is not null then select jsonb_build_object('address',d.address,'addressRevision',d.address_revision) into delivery from private.order_delivery_private_snapshots d where d.order_id=purchase.id;end if;
 return jsonb_build_object('id',gift.id,'party',party,'isRecipient',coalesce(gift.recipient_id=p_actor,false),'state',effective_state,'revision',gift.revision,'message',gift.message,'senderLabel',gift.sender_label,
  'recipientLabel',gift.recipient_label,'createdAt',gift.created_at,'expiresAt',gift.expires_at,'acceptedAt',gift.accepted_at,
  'items',(select coalesce(jsonb_agg(i.item_display||jsonb_build_object('goodId',i.good_id) order by i.position),'[]') from private.gift_items i where i.gift_id=gift.id),
  'address',case when gift.recipient_id=p_actor then case when purchase.id is not null then delivery->'address' else address.address end else null end,
  'addressRevision',case when gift.recipient_id=p_actor then case when purchase.id is not null then (delivery->>'addressRevision')::bigint else address.revision end else null end,
  'order',case when purchase.id is null then null else jsonb_build_object('id',purchase.id,'status',purchase.status,'createdAt',purchase.created_at,
   'expiresAt',purchase.expires_at,'total',case when party='sender' then purchase.total else null end,
   'paymentMethod',case when party='sender' then purchase.payment_method::text else null end) end,
  'shipments',case when purchase.id is null then '[]'::jsonb else (select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'status',s.status,'shippedAt',s.shipped_at,'deliveredAt',s.delivered_at,
   'expectedShipDate',s.expected_ship_date,'carrier',case when gift.recipient_id=p_actor then s.carrier else null end,
   'trackingNumber',case when gift.recipient_id=p_actor then s.tracking_number else null end) order by s.created_at,s.id),'[]') from public.order_shipments s where s.order_id=purchase.id) end);
end $$

create function public.get_my_gift(p_id uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select private.gift_detail(auth.uid(),p_id);
$$

create function public.list_my_gifts(p_party text,p_before timestamptz default null,p_before_id uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare actor uuid:=auth.uid();begin
 perform private.gift_require_actor(actor,false);
 if p_party not in('sender','recipient') or (p_before is null)<>(p_before_id is null) then raise invalid_parameter_value using message='gift_list_invalid';end if;
 return (select jsonb_build_object('items',coalesce(jsonb_agg(private.gift_detail(actor,g.id) order by g.created_at desc,g.id desc) filter(where g.row_number<=20),'[]'),'hasMore',count(*)>20)
  from (select i.*,row_number() over(order by i.created_at desc,i.id desc) from private.gift_intents i where (case when p_party='sender' then i.sender_id else i.recipient_id end)=actor
   and (p_before is null or (i.created_at,i.id)<(p_before,p_before_id)) order by i.created_at desc,i.id desc limit 21)g);
end $$

create function public.get_gift_availability() returns boolean language sql stable security definer set search_path='' as $$
 select coalesce((select enabled and privacy_ready from private.gift_runtime where singleton),false);
$$

create function public.create_my_gift(p_id uuid,p_selection jsonb,p_message text,p_operation_id uuid,p_expected_actor_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();request jsonb;display jsonb;line jsonb;ordinal bigint;begin
 if actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 if p_id is null or p_message is null or char_length(p_message)>300 or p_message~'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]' then raise invalid_parameter_value using message='gift_input_invalid';end if;
 perform private.gift_lock_subjects(array[actor]);
 perform private.lock_goods_transaction_source(actor,jsonb_build_object('kind','gift','id',p_id,'revision','new'));
 request:=jsonb_build_object('selection',p_selection,'message',p_message);
 if private.gift_operation_replay(actor,p_id,'created',request,p_operation_id) then return private.gift_operation_result(actor,p_operation_id);end if;
 perform private.gift_require_actor(actor);perform private.gift_require_runtime();
 if exists(select 1 from private.gift_intents where id=p_id) then raise unique_violation using message='gift_identity_conflict';end if;
 if (select count(*) from private.gift_intents where sender_id=actor and state in('awaiting_acceptance','accepted') and expires_at>clock_timestamp())>=50 then
  raise check_violation using message='gift_open_limit';end if;
 display:=private.gift_selection_display(p_selection);
 insert into private.gift_intents(id,sender_id,message,sender_label,expires_at) values(p_id,actor,p_message,(select nickname from public.profiles where id=actor),clock_timestamp()+interval '7 days');
 for line,ordinal in select value,ordinality from jsonb_array_elements(p_selection) with ordinality as entries(value,ordinality) loop
  insert into private.gift_items(gift_id,position,good_id,variant_id,qty,input_revision,input_values,item_display)
  values(p_id,ordinal-1,line->>'goodId',(line->>'variantId')::uuid,(line->>'qty')::integer,(line->>'inputRevision')::bigint,line->'inputValues',display->(ordinal::integer-1));
 end loop;
 perform private.gift_record_operation(actor,p_id,'created',request,p_operation_id);return private.gift_operation_result(actor,p_operation_id);
end $$

create function public.issue_my_gift_link(p_id uuid,p_expected_revision bigint,p_token_hash text,p_operation_id uuid,p_expected_actor_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$declare actor uuid:=auth.uid();gift private.gift_intents;request jsonb;generation bigint;begin
 if actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_lock(p_id,actor);
 if gift.sender_id<>actor then raise insufficient_privilege using message='gift_not_found';end if;
 if p_token_hash is null or p_token_hash!~'^[a-f0-9]{64}$' or p_expected_revision is null then raise invalid_parameter_value using message='gift_link_invalid';end if;
 request:=jsonb_build_object('revision',p_expected_revision,'tokenHash',p_token_hash);
 if private.gift_operation_replay(actor,p_id,'link_issued',request,p_operation_id) then
  if not exists(select 1 from private.gift_link_tokens where token_hash=p_token_hash and revoked_at is null and consumed_at is null and expires_at>clock_timestamp()) then raise check_violation using message='gift_link_closed';end if;
  return private.gift_operation_result(actor,p_operation_id)||jsonb_build_object('generation',(select t.generation from private.gift_link_tokens t where token_hash=p_token_hash));
 end if;
 perform private.gift_require_actor(actor);perform private.gift_require_runtime();
 if gift.revision<>p_expected_revision then raise sqlstate 'PT409' using message='gift_changed';end if;
 if gift.state<>'awaiting_acceptance' or gift.expires_at<=clock_timestamp() then raise check_violation using message='gift_link_closed';end if;
 select coalesce(max(t.generation),0)+1 into generation from private.gift_link_tokens t where gift_id=p_id;
 if generation>100 then raise check_violation using message='gift_link_limit';end if;
 update private.gift_link_tokens set revoked_at=clock_timestamp() where gift_id=p_id and revoked_at is null;
 delete from private.gift_claim_sessions s using private.gift_link_tokens t where s.token_hash=t.token_hash and t.gift_id=p_id;
 insert into private.gift_link_tokens(token_hash,gift_id,generation,expires_at) values(p_token_hash,p_id,generation,gift.expires_at);
 update private.gift_intents set revision=revision+1,updated_at=clock_timestamp() where id=p_id;
 perform private.gift_record_operation(actor,p_id,'link_issued',request,p_operation_id);
 return private.gift_operation_result(actor,p_operation_id)||jsonb_build_object('generation',generation);
end $$

create function public.service_begin_gift_claim_session(p_token_hash text,p_session_hash text) returns timestamptz
language plpgsql volatile security definer set search_path='' as $$declare token private.gift_link_tokens;gift private.gift_intents;ends timestamptz;begin
 if p_token_hash is null or p_token_hash!~'^[a-f0-9]{64}$' or p_session_hash is null or p_session_hash!~'^[a-f0-9]{64}$' then return null;end if;
 select * into token from private.gift_link_tokens where token_hash=p_token_hash;
 if not found then return null;end if;
 gift:=private.gift_lock(token.gift_id);select * into token from private.gift_link_tokens where token_hash=p_token_hash for update;
 if gift.state<>'awaiting_acceptance' or token.revoked_at is not null or token.consumed_at is not null or token.expires_at<=clock_timestamp() then return null;end if;
 delete from private.gift_claim_sessions where token_hash=p_token_hash and expires_at<=clock_timestamp();
 if (select count(*) from private.gift_claim_sessions where token_hash=p_token_hash)>=5 then return null;end if;
 ends:=least(token.expires_at,clock_timestamp()+interval '10 minutes');
 insert into private.gift_claim_sessions(session_hash,token_hash,expires_at) values(p_session_hash,p_token_hash,ends);return ends;
end $$

create function public.read_my_gift_invitation(p_session_hash text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare gift private.gift_intents;actor uuid:=auth.uid();begin
 perform private.gift_require_actor(actor,false);
 select * into gift from private.gift_intents where id=private.gift_session_id(p_session_hash,statement_timestamp()) and state='awaiting_acceptance' and expires_at>statement_timestamp();
 if not found then return null;end if;
 return jsonb_build_object('id',gift.id,'revision',gift.revision,'message',gift.message,'senderLabel',gift.sender_label,'expiresAt',gift.expires_at,
  'items',(select jsonb_agg(i.item_display||jsonb_build_object('goodId',i.good_id) order by i.position) from private.gift_items i where gift_id=gift.id));
end $$

create function public.respond_to_gift(p_id uuid,p_session_hash text,p_accept boolean,p_address jsonb,p_expected_revision bigint,p_operation_id uuid,p_expected_actor_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();gift private.gift_intents;request jsonb;address jsonb;at_time timestamptz;begin
 if actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_lock(p_id,actor);
 if p_accept is null or p_expected_revision is null then raise invalid_parameter_value using message='gift_response_invalid';end if;
 address:=case when p_accept then private.normalize_order_address_change(p_address) else null end;
 if not p_accept and p_address is not null then raise invalid_parameter_value using message='gift_response_invalid';end if;
 request:=jsonb_build_object('sessionHash',p_session_hash,'accept',p_accept,'address',address,'revision',p_expected_revision);
 if private.gift_operation_replay(actor,p_id,'responded',request,p_operation_id) then return private.gift_operation_result(actor,p_operation_id);end if;
 perform private.gift_require_actor(actor);perform private.gift_require_runtime();
 at_time:=clock_timestamp();
 if private.gift_session_id(p_session_hash,at_time) is distinct from p_id then raise insufficient_privilege using message='gift_invitation_unavailable';end if;
 if gift.revision<>p_expected_revision then raise sqlstate 'PT409' using message='gift_changed';end if;
 if gift.state<>'awaiting_acceptance' or gift.expires_at<=at_time then raise check_violation using message='gift_response_closed';end if;
 perform private.gift_require_actor(gift.sender_id);
 if p_accept then
  perform private.gift_selection_display(private.gift_selection(p_id));
  insert into private.gift_recipient_addresses(gift_id,recipient_id,address) values(p_id,actor,address);
 end if;
 update private.gift_intents set recipient_id=actor,recipient_label=(select nickname from public.profiles where id=actor),state=case when p_accept then 'accepted' else 'declined' end,
  accepted_at=case when p_accept then clock_timestamp() end,closed_at=case when not p_accept then clock_timestamp() end,revision=revision+1,updated_at=clock_timestamp() where id=p_id;
 update private.gift_link_tokens set consumed_at=clock_timestamp() where gift_id=p_id and revoked_at is null;
 perform private.gift_record_operation(actor,p_id,'responded',request,p_operation_id);return private.gift_operation_result(actor,p_operation_id);
end $$

create function public.update_my_gift_address(p_id uuid,p_address jsonb,p_expected_revision bigint,p_operation_id uuid,p_expected_actor_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$declare actor uuid:=auth.uid();gift private.gift_intents;address_value jsonb;request jsonb;begin
 if actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_lock(p_id,actor);perform private.gift_require_actor(actor,false);
 if gift.recipient_id is distinct from actor then raise insufficient_privilege using message='gift_not_found';end if;
 address_value:=private.normalize_order_address_change(p_address);request:=jsonb_build_object('address',address_value,'revision',p_expected_revision);
 if private.gift_operation_replay(actor,p_id,'address_changed',request,p_operation_id) then return private.gift_operation_result(actor,p_operation_id);end if;
 if p_expected_revision is null or gift.revision<>p_expected_revision then raise sqlstate 'PT409' using message='gift_changed';end if;
 if gift.state<>'accepted' or gift.order_id is not null or gift.expires_at<=clock_timestamp() then raise check_violation using message='gift_address_closed';end if;
 delete from private.goods_transaction_quotes where actor_id=gift.sender_id and source->>'kind'='gift' and source->>'id'=gift.id::text and order_id is null;
 update private.gift_recipient_addresses set address=address_value,revision=revision+1,updated_at=clock_timestamp() where gift_id=p_id;
 update private.gift_intents set revision=revision+1,updated_at=clock_timestamp() where id=p_id;
 perform private.gift_record_operation(actor,p_id,'address_changed',request,p_operation_id);return private.gift_operation_result(actor,p_operation_id);
end $$

create function public.close_my_gift(p_id uuid,p_expected_revision bigint,p_operation_id uuid,p_expected_actor_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$declare actor uuid:=auth.uid();gift private.gift_intents;request jsonb;begin
 if actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_lock(p_id,actor);perform private.gift_require_actor(actor,false);
 if gift.sender_id<>actor and gift.recipient_id is distinct from actor then raise insufficient_privilege using message='gift_not_found';end if;
 request:=jsonb_build_object('revision',p_expected_revision);
 if private.gift_operation_replay(actor,p_id,'closed',request,p_operation_id) then return private.gift_operation_result(actor,p_operation_id);end if;
 if p_expected_revision is null or gift.revision<>p_expected_revision then raise sqlstate 'PT409' using message='gift_changed';end if;
 if gift.state not in('awaiting_acceptance','accepted') or gift.order_id is not null then raise check_violation using message='gift_close_unavailable';end if;
 update private.gift_intents set state='canceled',closed_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where id=p_id;
 update private.gift_link_tokens set revoked_at=clock_timestamp() where gift_id=p_id and revoked_at is null;
 delete from private.gift_claim_sessions s using private.gift_link_tokens t where s.token_hash=t.token_hash and t.gift_id=p_id;
 delete from private.goods_transaction_quotes where actor_id=gift.sender_id and source->>'kind'='gift' and source->>'id'=gift.id::text and order_id is null;
 delete from private.gift_recipient_addresses where gift_id=p_id;
 perform private.gift_record_operation(actor,p_id,'closed',request,p_operation_id);return private.gift_operation_result(actor,p_operation_id);
end $$

create function public.service_expire_gifts(p_limit integer default 100) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare candidate record;gift private.gift_intents;changed integer:=0;begin
 for candidate in select id from private.gift_intents where order_id is null and state in('awaiting_acceptance','accepted') and expires_at<=clock_timestamp()
  order by sender_id,id limit greatest(1,least(coalesce(p_limit,100),100)) loop
  begin gift:=private.gift_lock(candidate.id);exception when sqlstate 'PT409' then continue;end;
  if gift.order_id is not null or gift.state not in('awaiting_acceptance','accepted') or gift.expires_at>clock_timestamp() then continue;end if;
  update private.gift_intents set state='expired',closed_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where id=gift.id;
  update private.gift_link_tokens set revoked_at=clock_timestamp() where gift_id=gift.id and revoked_at is null;
  delete from private.goods_transaction_quotes where actor_id=gift.sender_id and source->>'kind'='gift' and source->>'id'=gift.id::text and order_id is null;
  delete from private.gift_recipient_addresses where gift_id=gift.id;changed:=changed+1;
 end loop;
 delete from private.gift_claim_sessions s where s.expires_at<=clock_timestamp() or exists(select 1 from private.gift_link_tokens t where t.token_hash=s.token_hash and (t.revoked_at is not null or t.consumed_at is not null));
 return jsonb_build_object('expired',changed);
end $$

create function private.bind_goods_transaction_delivery_snapshot(p_order_id uuid,p_actor uuid,p_source jsonb,p_address jsonb,p_shipping_snapshot jsonb) returns void
language plpgsql volatile security definer set search_path='' as $$declare gift private.gift_intents;destination private.gift_recipient_addresses;purchase public.orders;begin
 if p_source->>'kind'<>'gift' then return;end if;
 gift:=private.gift_lock((p_source->>'id')::uuid);
 if gift.sender_id is distinct from p_actor or private.gift_source(gift)<>p_source or gift.state<>'accepted' or gift.order_id is not null or gift.expires_at<=clock_timestamp() then
  raise check_violation using message='gift_source_changed';end if;
 select * into destination from private.gift_recipient_addresses where gift_id=gift.id for update;
 if not found or destination.recipient_id is distinct from gift.recipient_id or destination.address is distinct from p_address then
  raise check_violation using message='gift_address_changed';end if;
 select * into purchase from public.orders where id=p_order_id;
 if not found or purchase.user_id is distinct from p_actor or purchase.address is not null then raise check_violation using message='gift_public_address_forbidden';end if;
 if jsonb_typeof(p_shipping_snapshot) is distinct from 'array' then raise check_violation using message='gift_shipping_evidence_invalid';end if;
 insert into private.order_delivery_private_snapshots(order_id,gift_id,recipient_id,address,gift_address_revision,source_revision,shipping_evidence)
 values(p_order_id,gift.id,gift.recipient_id,p_address,destination.revision,p_source->>'revision',p_shipping_snapshot);
 delete from private.gift_recipient_addresses where gift_id=gift.id;
 update private.gift_intents set state='ordered',order_id=p_order_id,ordered_source_revision=p_source->>'revision',revision=revision+1,updated_at=clock_timestamp() where id=gift.id;
end $$

create function public.gift_direct_order_read_allowed(p_order_id uuid) returns boolean language sql stable security definer set search_path='' as $$
 select private.gift_direct_order_read_allowed(p_order_id,auth.uid());
$$

-- Seal tables and internal routines; only existing trusted owner functions may
-- call private delivery getters. No caller receives direct private table grants.
do $$declare item regclass;fn regprocedure;begin
 foreach item in array array['private.gift_runtime'::regclass,'private.gift_intents'::regclass,'private.gift_items'::regclass,
  'private.gift_recipient_addresses'::regclass,'private.gift_link_tokens'::regclass,'private.gift_claim_sessions'::regclass,
  'private.gift_operations'::regclass,'private.order_delivery_private_snapshots'::regclass] loop
  execute format('alter table %s enable row level security',item);execute format('revoke all on %s from public,anon,authenticated,service_role',item);
 end loop;
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'
  and p.proname=any(array['gift_require_actor','gift_require_runtime','gift_source','gift_lock_subjects','gift_lock','gift_operation_replay','gift_record_operation','gift_selection',
   'gift_selection_display','gift_item_identity_changed','gift_detail','gift_operation_result','gift_session_id','gift_direct_order_read_allowed','order_delivery_snapshot','bind_goods_transaction_delivery_snapshot']) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',fn);execute format('grant execute on function %s to postgres',fn);
  perform private.register_operator_internal_contract(fn);
 end loop;
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'
  and p.proname=any(array['get_my_gift','list_my_gifts','get_gift_availability','create_my_gift','issue_my_gift_link','service_begin_gift_claim_session','read_my_gift_invitation',
   'respond_to_gift','update_my_gift_address','close_my_gift','service_expire_gifts','gift_direct_order_read_allowed']) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',fn);
  execute format('grant execute on function %s to %s',fn,case when fn::text ~ '(^|[.])service_' then 'service_role' else 'authenticated' end);
  perform private.register_operator_internal_contract(fn);
 end loop;
end $$

create function private.gift_checkout_source(p_id uuid,p_actor uuid,p_expected_revision bigint default null) returns private.gift_intents
language plpgsql volatile security definer set search_path='' as $$declare gift private.gift_intents;begin
 gift:=private.gift_lock(p_id,p_actor);
 if gift.sender_id is distinct from p_actor then raise insufficient_privilege using message='gift_not_found';end if;
 if p_expected_revision is not null and gift.revision<>p_expected_revision then raise sqlstate 'PT409' using message='gift_changed';end if;
 return gift;
end $$

create function private.gift_require_payment_ready(p_gift private.gift_intents) returns void
language plpgsql volatile security definer set search_path='' as $$begin
 perform private.gift_require_runtime();
 perform private.gift_require_actor(p_gift.sender_id);perform private.gift_require_actor(p_gift.recipient_id);
 if p_gift.state<>'accepted' or p_gift.order_id is not null or p_gift.expires_at<=clock_timestamp() then
  raise check_violation using message='gift_payment_not_ready';end if;
 if not exists(select 1 from private.gift_recipient_addresses a where a.gift_id=p_gift.id and a.recipient_id=p_gift.recipient_id) then
  raise check_violation using message='gift_payment_not_ready';end if;
end $$

create function public.quote_my_gift(p_id uuid,p_expected_revision bigint,p_user_coupon_id uuid,p_store_credit_amount bigint,p_expected_actor_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();gift private.gift_intents;address jsonb;selection jsonb;choices jsonb;quoted jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_checkout_source(p_id,actor,p_expected_revision);perform private.gift_require_payment_ready(gift);
 selection:=private.gift_selection(gift.id);
 select a.address into address from private.gift_recipient_addresses a where a.gift_id=gift.id;
 select jsonb_object_agg(value->>'goodId','prepaid') into choices from jsonb_array_elements(selection);
 quoted:=private.quote_goods_transaction(actor,private.gift_source(gift),selection,address,choices,p_user_coupon_id,p_store_credit_amount);
 if quoted->>'state'='quoted' and (quoted#>>'{display,totals,collectShippingTotal}')::numeric<>0 then
  raise check_violation using message='gift_prepaid_required';end if;
 return quoted;
end $$

create function public.replay_my_gift_order(p_id uuid,p_quote_id uuid,p_checkout_key uuid,p_payment_method public.order_payment_method,p_expected_actor_id uuid) returns uuid
language plpgsql volatile security definer set search_path='' as $$declare actor uuid:=auth.uid();gift private.gift_intents;receipt jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_checkout_source(p_id,actor);
 receipt:=private.replay_goods_transaction_receipt(actor,private.gift_source(gift),p_quote_id,p_checkout_key,p_payment_method);
 return (receipt->>'orderId')::uuid;
end $$

create function public.place_my_gift(p_id uuid,p_quote_id uuid,p_checkout_key uuid,p_payment_method public.order_payment_method,p_expected_actor_id uuid) returns uuid
language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();gift private.gift_intents;address jsonb;selection jsonb;receipt jsonb;quoted private.goods_transaction_quotes;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_checkout_source(p_id,actor);
 -- Recovery uses only the durable receipt. It survives quote/address retention,
 -- account fencing, runtime closure, and an already ordered gift.
 receipt:=private.replay_goods_transaction_receipt(actor,private.gift_source(gift),p_quote_id,p_checkout_key,p_payment_method);
 if receipt is not null then return (receipt->>'orderId')::uuid;end if;
 perform private.gift_require_payment_ready(gift);
 select * into quoted from private.goods_transaction_quotes where id=p_quote_id and actor_id=actor;
 if not found or quoted.source is distinct from private.gift_source(gift) then raise sqlstate 'PT409' using message='gift_source_changed';end if;
 if (quoted.calculation#>>'{display,totals,collectShippingTotal}')::numeric<>0 then raise check_violation using message='gift_prepaid_required';end if;
 selection:=private.gift_selection(gift.id);
 select a.address into address from private.gift_recipient_addresses a where a.gift_id=gift.id;
 return private.place_goods_transaction(actor,private.gift_source(gift),selection,address,p_quote_id,p_checkout_key,p_payment_method);
end $$

-- An explicit tri-state prevents a failed gift read from falling through to a
-- raw orders reader. No address, carrier, tracking, region, or customer note is
-- present in the payer projection, even for a sender who also receives a gift.
create function public.get_my_gift_checkout_order(p_order_id uuid,p_expected_actor_id uuid default auth.uid()) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=auth.uid();purchase public.orders;gift private.gift_intents;receipt jsonb;payment_status text;attempt_state text;begin
 if actor is null or actor is distinct from p_expected_actor_id then return jsonb_build_object('kind','unavailable');end if;
 select * into purchase from public.orders where id=p_order_id and user_id=actor;
 if not found then return jsonb_build_object('kind','unavailable');end if;
 select * into gift from private.gift_intents where order_id=purchase.id and sender_id=actor;
 if not found then
  if exists(select 1 from private.order_delivery_private_snapshots where order_id=purchase.id) then return jsonb_build_object('kind','unavailable');end if;
  return jsonb_build_object('kind','ordinary');
 end if;
 select t.original_receipt into receipt from private.order_goods_transactions t where t.order_id=purchase.id and t.actor_id=actor and t.source_kind='gift' and t.source_id=gift.id;
 if receipt is null or purchase.calculation_version<>2 or purchase.address is not null then raise check_violation using message='gift_order_projection_invalid';end if;
 select p.status::text into payment_status from public.payments p where p.purpose='order' and p.ref_id=purchase.id and p.user_id=actor order by p.created_at desc,p.id desc limit 1;
 select a.state into attempt_state from public.payment_attempts a where a.purpose='order' and a.ref_id=purchase.id and a.user_id=actor order by a.created_at desc,a.id desc limit 1;
 return jsonb_build_object('kind','gift','receipt',receipt,'order',jsonb_build_object(
  'id',purchase.id,'giftId',gift.id,'status',purchase.status,'total',purchase.total,'shippingFee',purchase.shipping_fee,'discountTotal',purchase.discount_total,
  'storeCreditTotal',purchase.store_credit_total,'address',null,'expiresAt',purchase.expires_at,'createdAt',purchase.created_at,
  'deliveredAt',purchase.delivered_at,'paymentStatus',case when attempt_state in('confirming','unknown','needs_review') then 'pending' else payment_status end,'paymentMethod',purchase.payment_method,
  'items',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'goodId',i.good_id,'variantId',i.variant_id,'variantName',i.variant_name_snapshot,
   'variantCode',i.variant_code_snapshot,'name',i.good_name_snapshot,'type',i.good_type_snapshot,'qty',i.qty,'unitPrice',i.unit_price,
   'customInputs',i.custom_inputs_snapshot,'supplySource',i.supply_source,'preorderExpectedShipDate',i.preorder_expected_ship_date) order by i.id),'[]') from public.order_items i where i.order_id=purchase.id),
  'shipments',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'orderId',s.order_id,'originId',s.origin_id,'originName',s.origin_name_snapshot,
   'shippingFee',s.shipping_fee,'status',s.status,'carrier',null,'carrierLabel',null,'trackingNumber',null,'trackingUrl',null,
   'shippedAt',s.shipped_at,'deliveredAt',s.delivered_at,'exportedAt',null,'orderItemIds',(select coalesce(jsonb_agg(si.order_item_id order by si.order_item_id),'[]') from public.order_shipment_items si where si.shipment_id=s.id),
   'originalExpectedShipDate',s.original_expected_ship_date,'expectedShipDate',s.expected_ship_date,'preorderReady',public.shipment_preorder_ready(s),
   'regionalShipping',null,'delivery',null) order by s.id),'[]') from public.order_shipments s where s.order_id=purchase.id)));
end $$

do $$declare fn regprocedure;begin
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where
  n.nspname='private' and p.proname=any(array['gift_checkout_source','gift_require_payment_ready']) or
  n.nspname='public' and p.proname=any(array['quote_my_gift','replay_my_gift_order','place_my_gift','get_my_gift_checkout_order','get_my_gift_menu_state','get_my_gift_latest_claim']) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',fn);
  execute format('grant execute on function %s to %s',fn,case when fn::text like 'private.%' then 'postgres' else 'authenticated' end);
  perform private.register_operator_internal_contract(fn);
 end loop;
end $$

create function public.admin_get_order_delivery_snapshots(p_order_ids uuid[]) returns jsonb
language plpgsql stable security definer set search_path='' as $$begin
 perform private.require_actor_operator_capability(auth.uid(),'sales.read',false);
 if p_order_ids is null or cardinality(p_order_ids)>1000 or array_position(p_order_ids,null) is not null then
  raise invalid_parameter_value using message='invalid_delivery_order_ids';end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('orderId',o.id,'isGift',g.id is not null,
   'address',d->'address','addressRevision',d->'addressRevision','shippingEvidence',d->'shippingEvidence') order by o.id),'[]')
  from public.orders o left join private.gift_intents g on g.order_id=o.id
  cross join lateral(select private.order_delivery_snapshot(o.id)d)delivery where o.id=any(p_order_ids));
end $$

create or replace function public.admin_order_address_context(p_order_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare purchase public.orders;blocker text;result jsonb;
begin
 if not private.has_operator_capability(auth.uid(),'sales.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 select * into purchase from public.orders where id=p_order_id;
 if not found then raise no_data_found using message='order_not_found';end if;
 blocker:=private.order_address_change_blocker(purchase);
 select jsonb_build_object('orderId',purchase.id,'address',private.order_delivery_snapshot(purchase.id)->'address','revision',private.order_delivery_snapshot(purchase.id)->'addressRevision',
  'isGift',exists(select 1 from private.gift_intents where order_id=purchase.id),
  'allowed',blocker is null,'blocker',blocker,'shipmentCount',(select count(*) from public.order_shipments where order_id=p_order_id),
  'history',coalesce((select jsonb_agg(entry order by happened desc) from (
   select c.created_at happened,jsonb_build_object('id',c.id,'changedAt',c.created_at,'actorName',coalesce(p.nickname,'이름 미등록'),
    'before',c.before_address,'after',c.after_address,'reason',c.reason) entry
   from private.order_address_changes c join public.profiles p on p.id=c.actor_id where c.order_id=p_order_id
   order by c.created_at desc,c.id desc limit 20)h),'[]'::jsonb)) into result;
 return result;
end $$

create or replace function public.admin_change_order_address(p_operation_id uuid,p_order_id uuid,p_expected_revision integer,p_address jsonb,p_reason text,p_customer_agreed boolean)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();purchase public.orders; previous private.order_address_changes; address_value jsonb;
 reason text:=nullif(btrim(p_reason),'');blocked text;shipment public.order_shipments;base_groups jsonb:='[]';lines jsonb;
 quote jsonb;origin_key uuid;group_value jsonb;changed_fields jsonb;delivery jsonb;is_gift boolean;v2_lines jsonb;choices jsonb;
begin
 perform private.require_actor_operator_capability(actor,'sales.manage',false);
 if p_operation_id is null or p_order_id is null or p_expected_revision is null or p_expected_revision<0
  or p_customer_agreed is distinct from true or reason is null or char_length(reason)>500 or reason~'[[:cntrl:]]' then
  raise invalid_parameter_value using message='invalid_order_address_change';end if;
 address_value:=private.normalize_order_address_change(p_address);
 perform pg_advisory_xact_lock(hashtextextended('order_address_change:'||p_operation_id::text,0));
 select * into previous from private.order_address_changes where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.order_id<>p_order_id or previous.expected_order_revision<>p_expected_revision
   or previous.after_address<>address_value or previous.reason<>reason then raise unique_violation using message='order_address_request_conflict';end if;
  return private.order_address_change_receipt(p_operation_id,actor);
 end if;
 select * into purchase from public.orders where id=p_order_id for update;
 if not found then raise no_data_found using message='order_not_found';end if;
 perform id from public.order_shipments where order_id=p_order_id order by id for update;
 perform order_id from private.order_delivery_private_snapshots where order_id=p_order_id for update;
 delivery:=private.order_delivery_snapshot(p_order_id);
 is_gift:=exists(select 1 from private.gift_intents where order_id=p_order_id);
 if (delivery->>'addressRevision')::integer<>p_expected_revision then raise sqlstate 'PT409' using message='order_address_changed';end if;
 blocked:=private.order_address_change_blocker(purchase);
 if blocked is not null then raise check_violation using message=blocked;end if;
 select jsonb_agg(k order by k) into changed_fields from jsonb_object_keys(address_value)k where coalesce((delivery->'address')->>k,'')<>address_value->>k;
 if changed_fields is null then raise invalid_parameter_value using message='order_address_unchanged';end if;
 -- Contact/detail-note corrections preserve the destination quote. A changed
 -- postal/base address must remain deliverable at every frozen shipment amount.
 if (delivery->'address')->>'postalCode' is distinct from address_value->>'postalCode'
  or private.shipping_region_text((delivery->'address')->>'address1') is distinct from private.shipping_region_text(address_value->>'address1') then
  if purchase.calculation_version=2 then
   -- Match quote/place's catalog lock order before any origin policy lock.
   perform id from public.goods where id in(select good_id from public.order_items where order_id=p_order_id) order by id for share;
   perform good_id from private.goods_transaction_configs where good_id in(select good_id from public.order_items where order_id=p_order_id) order by good_id for share;
  end if;
  for origin_key in select distinct origin_id from public.order_shipments where order_id=p_order_id order by origin_id loop
   perform id from public.fulfillment_origins where id=origin_key for share;
  end loop;
  if purchase.calculation_version=2 then
   select jsonb_agg(jsonb_build_object('good_id',good_id,'origin_id',origin_id_snapshot,'qty',qty,'unit_price',unit_price,'fee_type',shipping_fee_type_snapshot,'individual_fee',individual_fee_snapshot)) into v2_lines
    from public.order_items where order_id=p_order_id;
   select jsonb_object_agg(good_id,payment_mode) into choices from private.shipping_charge_components where order_id=p_order_id;
   quote:=private.calculate_goods_transaction_shipping(v2_lines,jsonb_build_object('postalCode',address_value->>'postalCode','address1',address_value->>'address1'),choices,clock_timestamp());
   if quote->>'state'='blocked' then raise check_violation using message='order_address_region_unavailable';end if;
   if (quote->>'prepaidFee')::bigint<>purchase.shipping_fee or (quote->>'collectFee')::bigint<>purchase.shipping_collect_total
    or exists(select 1 from jsonb_array_elements(quote->'rawGroups')g full join (select * from public.order_shipments where order_id=p_order_id)s on s.origin_id=(g->>'originId')::uuid
     where (s.id is null or g is null or (g->>'prepaidFee')::bigint<>s.shipping_fee or (g->>'collectFee')::bigint<>s.shipping_collect_fee)) then
    raise check_violation using message='order_address_shipping_fee_changed';end if;
  else
  for shipment in select * from public.order_shipments where order_id=p_order_id order by id loop
   group_value:=shipment.shipping_fee_snapshot;
   if shipment.delivery_method<>'parcel' or group_value->>'originId' is distinct from shipment.origin_id::text
    or not(group_value ?& array['policySubtotal','baseFee','freeThreshold','policyFee','individualFee','totalFee'])
    or jsonb_typeof(group_value->'totalFee') is distinct from 'number'
    or (group_value->>'totalFee')::bigint<>shipment.shipping_fee then
    raise check_violation using message='order_address_quote_unavailable';end if;
   base_groups:=base_groups||jsonb_build_array(group_value||jsonb_build_object('totalFee',shipment.shipping_fee-coalesce((group_value->>'regionalFee')::bigint,0)));
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('origin_id',origin_id_snapshot,'good_id',good_id,'fee_type',shipping_fee_type_snapshot)),'[]') into lines
   from public.order_items where order_id=p_order_id;
  quote:=private.apply_shipping_region_quote(jsonb_build_object('groups',base_groups),lines,
   jsonb_build_object('postalCode',address_value->>'postalCode','address1',address_value->>'address1'),clock_timestamp());
  if not coalesce((quote->>'checkoutAllowed')::boolean,false) then raise check_violation using message='order_address_region_unavailable';end if;
  if (quote->>'finalTotalFee')::bigint<>purchase.shipping_fee or exists(
   select 1 from jsonb_array_elements(quote->'groups')g join public.order_shipments s on s.order_id=p_order_id and s.origin_id=(g->>'originId')::uuid
   where (g->>'finalFee')::bigint<>s.shipping_fee) then raise check_violation using message='order_address_shipping_fee_changed';end if;
  end if;
 end if;
 insert into private.order_address_changes(id,order_id,actor_id,expected_order_revision,before_address,after_address,reason,destination_quote)
 values(p_operation_id,p_order_id,actor,p_expected_revision,delivery->'address',address_value,reason,quote);
 if is_gift then
  update private.order_delivery_private_snapshots set address=address_value,address_revision=address_revision+1,updated_at=clock_timestamp() where order_id=p_order_id;
  if not found then raise check_violation using message='gift_delivery_snapshot_missing';end if;
 else update public.orders set address=address_value,updated_at=clock_timestamp() where id=p_order_id;end if;
 -- Invalidate any export prepared before the change but not yet marked sent.
 update public.order_shipments set updated_at=clock_timestamp() where order_id=p_order_id;
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.order.address_changed','order:'||p_order_id,
  jsonb_build_object('changedFields',changed_fields,'customerAgreed',true,'agreementParty',case when is_gift then 'recipient' else 'buyer' end,'shipmentCount',(select count(*) from public.order_shipments where order_id=p_order_id),'shippingFeeUnchanged',true));
 return private.order_address_change_receipt(p_operation_id,actor);
end $$

CREATE FUNCTION private.request_order_claim_for_parties(p_order_id uuid, p_actor uuid, p_user_id uuid, p_gift_id uuid, p_claim_type text, p_reason text, p_reason_type text, p_bank_name text DEFAULT NULL::text, p_account_number text DEFAULT NULL::text, p_account_holder text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  claim_at timestamptz;
  gift private.gift_intents;
  v_status public.order_status;
  v_delivered_at timestamptz;
  v_claim_id uuid;
  v_has_unresolved_attempt boolean;
  v_masked_account text;
  v_masked_holder text;
  v_payment_count integer;
begin
  if p_claim_type is null or p_claim_type not in ('cancel', 'return', 'exchange') then
    raise check_violation using message = 'invalid claim type';
  end if;
  if p_reason_type is null or p_reason_type not in ('change_of_mind', 'defect') then
    raise check_violation using message = 'invalid cancellation reason type';
  end if;
  if p_reason is null
    or btrim(p_reason) <> p_reason
    or length(p_reason) not between 1 and 200
  then
    raise check_violation using message = 'invalid cancellation reason';
  end if;

  -- Actor is the actual requester; p_user_id is exclusively the financial owner.
  if p_gift_id is null then
    if p_actor is distinct from p_user_id then return jsonb_build_object('outcome','not_found','claimId',v_claim_id);end if;
    -- Preserve the ordinary-order intake lock graph unchanged.
  else
    select * into gift from private.gift_intents where id=p_gift_id and order_id=p_order_id;
    if not found or p_actor is null or p_user_id is distinct from gift.sender_id or not(p_actor=gift.sender_id or p_actor=gift.recipient_id)
      or p_actor<>gift.sender_id and p_claim_type='cancel' then return jsonb_build_object('outcome','not_found','claimId',v_claim_id);end if;
    perform private.gift_lock_subjects(array[p_actor,gift.sender_id,gift.recipient_id]);
    if p_actor<>gift.sender_id and (p_bank_name is not null or p_account_number is not null or p_account_holder is not null) then
      raise insufficient_privilege using message='gift_payer_refund_account_required';end if;
  end if;

  -- Common intake/dispatch lock order: order → shipments → payment attempts/payments.
  select orders.user_id, orders.status, orders.delivered_at
  into v_user_id, v_status, v_delivered_at
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found or p_user_id is null or v_user_id is distinct from p_user_id then
    return jsonb_build_object('outcome','not_found','claimId',v_claim_id);
  end if;

  perform s.id from public.order_shipments s where s.order_id=p_order_id order by s.id for update;

  perform attempt.id
  from public.payment_attempts as attempt
  where attempt.purpose = 'order'
    and attempt.ref_id = p_order_id
  order by attempt.id
  for update;

  select exists (
    select 1
    from public.payment_attempts as attempt
    where attempt.purpose = 'order'
      and attempt.ref_id = p_order_id
      and attempt.state in (
        'prepared', 'confirming', 'unknown', 'needs_review', 'approved'
      )
  )
  into v_has_unresolved_attempt;

  claim_at:=case when p_gift_id is null then now() else clock_timestamp() end;
  if v_status = 'canceled' then
    return jsonb_build_object('outcome','already_canceled','claimId',v_claim_id);
  end if;

  -- 반품·교환은 물리적 회수를 전제한다. 배송이 끝나기 전에는 회수할 물건이
  -- Customer cancellation is available only before order confirmation.
  if p_claim_type in ('return', 'exchange') then
    if not private.order_all_items_delivered(p_order_id) then
      return jsonb_build_object('outcome','not_claimable','claimId',v_claim_id);
    end if;
  elsif not private.order_cancel_eligible(p_order_id) then
    return jsonb_build_object('outcome','not_cancelable','claimId',v_claim_id);
  end if;

  -- 교환도 청약철회 기한을 준용한다(변심 7일 · 하자 3개월). 판정의 진실원은
  -- 계속 order_withdrawal_deadline_passed 하나다.
  if public.order_withdrawal_deadline_passed(v_delivered_at, p_reason_type, claim_at) then
    return jsonb_build_object('outcome','deadline_expired','claimId',v_claim_id);
  end if;

  if exists (
    select 1
    from public.order_cancellation_requests as request
    where request.order_id = p_order_id
      and request.status in ('requested', 'processing', 'needs_review')
  ) then
    return jsonb_build_object('outcome','already_requested','claimId',v_claim_id);
  end if;

  -- status는 적지 않는다. 투영은 private.order_claim_status_for_stage 하나가 만든다.
  insert into public.order_cancellation_requests (
    order_id,
    requested_by,
    reason,
    reason_type,
    claim_type,
    stage,
    requested_at
  )
  values (
    p_order_id,
    p_user_id,
    p_reason,
    p_reason_type,
    p_claim_type,
    'requested',
    claim_at
  )
  returning id into v_claim_id;
  if p_gift_id is not null then
    insert into private.gift_claim_parties(claim_id,gift_id,payer_id,recipient_id,actual_requester)
    values(v_claim_id,p_gift_id,gift.sender_id,gift.recipient_id,p_actor);
    insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'gift.claim_requested','order:'||p_order_id,
      jsonb_build_object('giftId',p_gift_id,'claimId',v_claim_id,'claimType',p_claim_type,'reasonType',p_reason_type,'requesterParty',case when p_actor=gift.sender_id then 'sender' else 'recipient' end));
  end if;


  /*
   * 환불계좌는 무통장 환불의 유일한 경로이고 카드 fallback의 안전망이다.
   * 세 칸이 모두 있을 때만 저장한다 — 반쪽 계좌는 송금에 쓸 수 없다.
   *
   * 교환에는 저장하지 않는다. 교환의 종결은 재출고이고 어떤 경로로도 돈이
   * 돌아가지 않으므로 계좌를 받을 목적 자체가 없다. 화면은 반품에만 폼을
   * 보이지만 API로는 실어 보낼 수 있으므로 접수 함수가 거른다. 취소·반품은
   * 결제사 취소가 막혔을 때 송금이 유일한 경로라 계속 받고, 보관 기간은
   * 종결 stage에서 seal_order_claim_refund_account가 잡는다.
   */
  if p_claim_type <> 'exchange'
    and p_bank_name is not null
    and p_account_number is not null
    and p_account_holder is not null
  then
    v_masked_account := public.mask_refund_account_number(p_account_number);
    v_masked_holder := public.mask_refund_account_holder(p_account_holder);

    insert into private.claim_refund_accounts (
      claim_id,
      bank_name,
      account_number,
      account_holder,
      masked_account,
      masked_holder
    )
    values (
      v_claim_id,
      btrim(p_bank_name),
      p_account_number,
      btrim(p_account_holder),
      btrim(p_bank_name) || ' ' || v_masked_account,
      v_masked_holder
    );
  end if;

  -- 결제 이력이 없는 pending 주문은 예전처럼 즉시 종결한다.
  if p_claim_type = 'cancel'
    and v_status = 'pending'
    and not v_has_unresolved_attempt
    and not exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'order'
        and payment.ref_id = p_order_id
    )
  then
    perform public.finalize_order_cancellation_with_provider_evidence(
      p_order_id,
      p_reason,
      array[]::text[]
    );

    update public.order_cancellation_requests
    set
      stage = 'completed',
      completed_at = now(),
      updated_at = now()
    where id = v_claim_id;

    return jsonb_build_object('outcome','completed','claimId',v_claim_id);
  end if;

  /*
   * 자동 승인 — paid(발주확인 전) 변심 취소.
   *
   * 아직 발주확인도 하지 않은 주문의 변심 취소를 사람이 판단할 이유가 없다.
   * 스마트스토어와 같은 경계다. confirmed부터는 발송 준비가 시작됐으므로
   * 운영자 판단으로 남긴다.
   *
   * 승인의 실질(durable claim + 환불 intent)은 admin_decide_order_cancellation의
   * 승인 분기와 같다. decided_by는 null로 남긴다 — 사람이 누른 적이 없다.
   */
  if p_claim_type = 'cancel'
    and v_status = 'paid'
    and p_reason_type = 'change_of_mind'
  then
    insert into public.order_cancellation_claims (
      order_id,
      requested_by,
      previous_status
    )
    values (p_order_id, p_user_id, v_status)
    on conflict (order_id) do nothing;

    insert into public.refunds (
      payment_id,
      amount,
      reason,
      status,
      cancellation_request_id
    )
    select
      payment.id,
      payment.amount,
      p_reason,
      case when refund.status = 'done' then 'done' else 'requested' end,
      v_claim_id
    from public.payments as payment
    left join public.refunds as refund on refund.payment_id = payment.id
    where payment.purpose = 'order'
      and payment.ref_id = p_order_id
      and payment.status in ('pending', 'paid', 'canceled', 'refunded')
    on conflict (payment_id) do update
    set
      cancellation_request_id = excluded.cancellation_request_id,
      reason = coalesce(public.refunds.reason, excluded.reason),
      status = case
        when public.refunds.status = 'done' then 'done'
        else 'requested'
      end;

    select count(*)::integer
    into v_payment_count
    from public.payments as payment
    where payment.purpose = 'order'
      and payment.ref_id = p_order_id
      and payment.status in ('pending', 'paid', 'canceled', 'refunded');

    update public.order_cancellation_requests
    set
      stage = 'processing',
      decided_at = now(),
      provider_started_at = now(),
      updated_at = now()
    where id = v_claim_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      p_user_id,
      'order.claim_auto_approved',
      'order:' || p_order_id::text,
      jsonb_build_object(
        'claimId', v_claim_id,
        'claimType', 'cancel',
        'from', 'requested',
        'to', 'processing',
        'previousOrderStatus', v_status::text,
        'reasonType', p_reason_type,
        'paymentCount', v_payment_count
      )
    );

    perform private.notify_order_claim(
      v_claim_id,
      'auto_approved',
      '취소 요청이 접수됐어요',
      '발송 전 주문이라 자동으로 승인됐습니다. 결제 취소 처리를 시작합니다.'
    );

    return jsonb_build_object('outcome','auto_approved','claimId',v_claim_id);
  end if;

  perform private.notify_order_claim(
    v_claim_id,
    'requested',
    '클레임 요청이 접수됐어요',
    '요청을 접수했습니다. 담당자가 확인한 뒤 진행 상황을 알려드립니다.'
  );

  return jsonb_build_object('outcome','requested','claimId',v_claim_id);
end;
$function$

create or replace function public.request_order_claim(p_order_id uuid,p_user_id uuid,p_claim_type text,p_reason text,p_reason_type text,
 p_bank_name text default null,p_account_number text default null,p_account_holder text default null) returns text
language plpgsql volatile security definer set search_path='' as $$declare gift private.gift_intents;begin
 select * into gift from private.gift_intents where order_id=p_order_id;
 return private.request_order_claim_for_parties(p_order_id,p_user_id,coalesce(gift.sender_id,p_user_id),gift.id,p_claim_type,p_reason,p_reason_type,p_bank_name,p_account_number,p_account_holder)->>'outcome';
end $$

create function private.gift_claim_actor(p_claim_id uuid) returns uuid language sql stable security definer set search_path='' as $$
 select coalesce(g.actual_requester,c.requested_by) from public.order_cancellation_requests c left join private.gift_claim_parties g on g.claim_id=c.id where c.id=p_claim_id;
$$

create function private.gift_claim_context(p_actor uuid,p_gift_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare gift private.gift_intents;claim public.order_cancellation_requests;purchase public.orders;own boolean;account private.claim_refund_accounts;begin
 select * into gift from private.gift_intents where id=p_gift_id and(p_actor=sender_id or p_actor=recipient_id);
 if not found or p_actor is null then return null;end if;
 select * into purchase from public.orders where id=gift.order_id;
 select * into claim from public.order_cancellation_requests where order_id=gift.order_id order by requested_at desc,id desc limit 1;
 own:=claim.id is not null and private.gift_claim_actor(claim.id)=p_actor;
 select * into account from private.claim_refund_accounts where claim_id=claim.id;
 return jsonb_build_object('giftId',gift.id,'isSender',p_actor=gift.sender_id,'isRecipient',p_actor=gift.recipient_id,
  'canRequest',purchase.id is not null and private.order_all_items_delivered(purchase.id) and purchase.status<>'canceled'
    and not exists(select 1 from public.order_cancellation_requests where order_id=purchase.id and status in('requested','processing','needs_review')),
  'claim',case when claim.id is null then null else jsonb_build_object('id',claim.id,'type',claim.claim_type,'stage',claim.stage,'revision',claim.claim_revision,'requestedAt',claim.requested_at,
   'isRequester',own,'canWithdraw',own and private.order_claim_withdrawal_blocker(claim) is null,
   'refundAccountNeeded',p_actor=gift.sender_id and(purchase.payment_method='bank_transfer' or claim.stage='needs_review') and claim.claim_type<>'exchange' and claim.stage not in('completed','rejected','withdrawn') and(account.claim_id is null or account.purged_at is not null),
   'maskedRefundAccount',case when p_actor=gift.sender_id then account.masked_account else null end,
   'reshipCarrier',case when p_actor=gift.recipient_id then claim.reship_carrier else null end,
   'reshipTrackingNumber',case when p_actor=gift.recipient_id then claim.reship_tracking_number else null end) end);
end $$

create function public.get_my_gift_claim_context(p_gift_id uuid,p_expected_actor_id uuid default auth.uid()) returns jsonb
language plpgsql stable security definer set search_path='' as $$begin
 if auth.uid() is null or auth.uid() is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 return private.gift_claim_context(auth.uid(),p_gift_id);
end $$

create function public.request_my_gift_claim(p_gift_id uuid,p_claim_type text,p_reason_type text,p_operation_id uuid,p_expected_actor_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$declare actor uuid:=auth.uid();gift private.gift_intents;previous private.gift_claim_operations;request_hash text;outcome jsonb;claim_id uuid;result jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 if p_operation_id is null or p_claim_type is null or p_claim_type not in('return','exchange') or p_reason_type is null or p_reason_type not in('change_of_mind','defect') then raise invalid_parameter_value using message='invalid_gift_claim';end if;
 select * into gift from private.gift_intents where id=p_gift_id and(actor=sender_id or actor=recipient_id);
 if not found or gift.order_id is null then raise no_data_found using message='gift_not_found';end if;
 perform private.gift_lock_subjects(array[actor,gift.sender_id,gift.recipient_id]);
 perform pg_advisory_xact_lock(hashtextextended('gift-claim-operation:'||p_operation_id,0));
 request_hash:=encode(extensions.digest(jsonb_build_array(p_gift_id,p_claim_type,p_reason_type)::text,'sha256'),'hex');
 select * into previous from private.gift_claim_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.gift_id<>p_gift_id or previous.kind<>'requested' or previous.request_hash<>request_hash then raise unique_violation using message='gift_operation_conflict';end if;
  return jsonb_build_object('receipt',previous.result,'context',private.gift_claim_context(actor,p_gift_id));
 end if;
 outcome:=private.request_order_claim_for_parties(gift.order_id,actor,gift.sender_id,gift.id,p_claim_type,
  case p_reason_type when 'defect' then '상품 하자' else '단순 변심' end,p_reason_type);
 if outcome->>'outcome'<>'requested' then raise check_violation using message=outcome->>'outcome';end if;
 claim_id:=(outcome->>'claimId')::uuid;
 result:=jsonb_build_object('operationId',p_operation_id,'kind','requested','claimId',claim_id);
 insert into private.gift_claim_operations(id,actor_id,gift_id,kind,request_hash,result) values(p_operation_id,actor,p_gift_id,'requested',request_hash,result);
 return jsonb_build_object('receipt',result,'context',private.gift_claim_context(actor,p_gift_id));
end $$

create function public.set_my_gift_claim_refund_account(p_gift_id uuid,p_claim_id uuid,p_operation_id uuid,p_bank_name text,p_account_number text,p_account_holder text,p_expected_actor_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$declare actor uuid:=auth.uid();gift private.gift_intents;claim public.order_cancellation_requests;purchase public.orders;previous private.gift_claim_operations;request_hash text;result jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 if p_operation_id is null or p_bank_name is null or p_bank_name<>btrim(p_bank_name) or length(p_bank_name) not between 1 and 40
  or p_account_number is null or p_account_number!~'^[0-9-]{8,30}$' or p_account_holder is null or p_account_holder<>btrim(p_account_holder) or length(p_account_holder) not between 1 and 40 then
  raise invalid_parameter_value using message='invalid_refund_account';end if;
 select * into gift from private.gift_intents where id=p_gift_id and sender_id=actor;
 if not found or gift.order_id is null then raise no_data_found using message='gift_not_found';end if;
 perform private.gift_lock_subjects(array[actor,gift.recipient_id]);
 perform pg_advisory_xact_lock(hashtextextended('gift-claim-operation:'||p_operation_id,0));
 request_hash:=encode(extensions.digest(jsonb_build_array(p_operation_id,p_gift_id,p_claim_id,p_bank_name,p_account_number,p_account_holder)::text,'sha256'),'hex');
 select * into previous from private.gift_claim_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.gift_id<>p_gift_id or previous.kind<>'refund_account' or previous.request_hash<>request_hash then raise unique_violation using message='gift_operation_conflict';end if;
  return jsonb_build_object('receipt',previous.result,'context',private.gift_claim_context(actor,p_gift_id));
 end if;
 select * into purchase from public.orders where id=gift.order_id for update;
 perform id from public.order_shipments where order_id=purchase.id order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id and order_id=purchase.id for update;
 if not found or (purchase.payment_method<>'bank_transfer' and claim.stage<>'needs_review') or claim.claim_type='exchange' or claim.stage not in('requested','in_review','collecting','collected','on_hold','needs_review') then raise check_violation using message='gift_refund_account_closed';end if;
 if exists(select 1 from private.claim_refund_accounts where claim_id=claim.id) then raise check_violation using message='gift_refund_account_exists';end if;
 insert into private.claim_refund_accounts(claim_id,bank_name,account_number,account_holder,masked_account,masked_holder)
 values(claim.id,p_bank_name,p_account_number,p_account_holder,p_bank_name||' '||public.mask_refund_account_number(p_account_number),public.mask_refund_account_holder(p_account_holder));
 result:=jsonb_build_object('operationId',p_operation_id,'kind','refund_account','claimId',claim.id);
 insert into private.gift_claim_operations(id,actor_id,gift_id,kind,request_hash,result) values(p_operation_id,actor,gift.id,'refund_account',request_hash,result);
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'gift.refund_account_confirmed','order:'||purchase.id,jsonb_build_object('claimId',claim.id,'giftId',gift.id));
 return jsonb_build_object('receipt',result,'context',private.gift_claim_context(actor,gift.id));
end $$

create or replace function private.read_order_claim_withdrawal_context(p_claim_id uuid,p_actor uuid,p_as_operator boolean) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare claim public.order_cancellation_requests;purchase public.orders;blocker text;
begin
 if p_actor is null then raise insufficient_privilege using message='auth_required';end if;
 if p_as_operator and not private.has_operator_capability(p_actor,'sales.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 select * into claim from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found';end if;
 select * into purchase from public.orders where id=claim.order_id;
 if not p_as_operator and private.gift_claim_actor(p_claim_id) is distinct from p_actor then raise no_data_found using message='claim_not_found';end if;
 blocker:=private.order_claim_withdrawal_blocker(claim);
 return jsonb_build_object('claimId',claim.id,'orderId',claim.order_id,'claimType',claim.claim_type,'stage',claim.stage,
  'revision',claim.claim_revision,'allowed',blocker is null,'blocker',blocker,'orderTotal',case when p_as_operator or purchase.user_id=p_actor then purchase.total else null end,
  'withdrawal',(select jsonb_build_object('actorKind',w.actor_kind,'reason',case when exists(select 1 from private.gift_intents where order_id=claim.order_id) then '선물 요청 철회' else w.reason end,'createdAt',w.created_at) from private.order_claim_withdrawals w where w.claim_id=claim.id));
end $$

create or replace function private.apply_order_claim_withdrawal(p_claim_id uuid,p_operation_id uuid,p_expected_revision integer,p_reason text,p_confirmed boolean,p_as_operator boolean)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid();purchase public.orders;claim public.order_cancellation_requests;previous private.order_claim_withdrawals;
 order_key uuid;buyer uuid;blocker text;kind text:=case when p_as_operator then 'operator' else 'customer' end;reason text:=btrim(p_reason);happened timestamptz;
begin
 if actor is null then raise insufficient_privilege using message='auth_required';end if;
 if p_as_operator and not private.has_operator_capability(actor,'sales.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 or p_confirmed is distinct from true
  or reason is null or char_length(reason) not between 2 and 500 or reason~'[[:cntrl:]]' then raise invalid_parameter_value using message='invalid_claim_withdrawal';end if;
 select c.order_id,o.user_id into order_key,buyer from public.order_cancellation_requests c join public.orders o on o.id=c.order_id where c.id=p_claim_id;
 if order_key is null or not p_as_operator and private.gift_claim_actor(p_claim_id) is distinct from actor then raise no_data_found using message='claim_not_found';end if;
 -- Existing-order recovery remains available to its owner, including suspended owners.
 perform private.lock_operator_subjects(array[actor,buyer]);
 if p_as_operator then perform private.require_actor_operator_capability(actor,'sales.manage',false);end if;
 perform pg_advisory_xact_lock(hashtextextended('claim-withdrawal:'||p_operation_id::text,0));
 select * into previous from private.order_claim_withdrawals where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.actor_kind<>kind or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision or previous.reason<>reason then
   raise unique_violation using message='claim_withdrawal_request_conflict';end if;
  return private.order_claim_withdrawal_receipt(p_operation_id,actor);
 end if;
 select * into purchase from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 perform shipment_id from public.order_claim_collections where claim_id=p_claim_id order by shipment_id for update;
 if claim.claim_revision<>p_expected_revision then raise sqlstate 'PT409' using message='claim_changed';end if;
 blocker:=private.order_claim_withdrawal_blocker(claim);
 if blocker is not null then raise check_violation using message=blocker;end if;
 happened:=clock_timestamp();
 insert into private.order_claim_withdrawals(id,claim_id,order_id,actor_id,actor_kind,expected_revision,reason,from_stage,created_at)
 values(p_operation_id,p_claim_id,order_key,actor,kind,p_expected_revision,reason,claim.stage,happened);
 update public.order_cancellation_requests set stage='withdrawn',withdrawn_at=happened,decided_at=happened,decided_by=actor,
  decision_note=null,held_from=null,hold_reason=null,held_at=null,updated_at=happened where id=p_claim_id;
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'order.claim_withdrawn','order:'||order_key,
  jsonb_build_object('claimId',p_claim_id,'claimType',claim.claim_type,'from',claim.stage,'to','withdrawn','actorKind',kind,'customerConfirmed',true));
 perform private.notify_order_claim(p_claim_id,'withdrawn','요청을 철회했어요',
  case when p_as_operator then '고객님과 확인한 요청 철회를 담당자가 기록했습니다. 주문과 결제는 유지되며 환불을 실행하지 않습니다.'
  else '요청을 철회했습니다. 주문과 결제는 유지되며 환불을 실행하지 않습니다.' end);
 return private.order_claim_withdrawal_receipt(p_operation_id,actor);
end $$

create or replace function public.get_my_order_claim_reason_changes(p_order_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if auth.uid() is null then raise insufficient_privilege using message='auth_required';end if;
 if not exists(select 1 from public.orders where id=p_order_id and user_id=auth.uid()) then raise no_data_found using message='order_not_found';end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'claimId',claim_id,'fromReasonType',from_reason_type,'fromReason',case when exists(select 1 from private.gift_intents where order_id=p_order_id) then case from_reason_type when 'defect' then '상품 하자' else '단순 변심' end else from_reason end,
  'toReasonType',to_reason_type,'toReason',case when exists(select 1 from private.gift_intents where order_id=p_order_id) then case to_reason_type when 'defect' then '상품 하자' else '단순 변심' end else to_reason end,'requestedAt',requested_at,'createdAt',created_at)
  order by created_at,id),'[]'::jsonb) from private.order_claim_reason_operations where order_id=p_order_id and changed);
end $$

create function public.withdraw_my_gift_claim(p_gift_id uuid,p_claim_id uuid,p_operation_id uuid,p_expected_revision integer,p_expected_actor_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$declare actor uuid:=auth.uid();receipt jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 if not exists(select 1 from private.gift_intents g join public.order_cancellation_requests c on c.order_id=g.order_id where g.id=p_gift_id and c.id=p_claim_id and(actor=g.sender_id or actor=g.recipient_id)) then raise no_data_found using message='gift_not_found';end if;
 receipt:=private.apply_order_claim_withdrawal(p_claim_id,p_operation_id,p_expected_revision,'선물 요청 철회',true,false);
 return jsonb_build_object('receipt',jsonb_build_object('operationId',p_operation_id,'kind','withdrawn','claimId',p_claim_id),'context',private.gift_claim_context(actor,p_gift_id));
end $$

-- Operational claim detail distinguishes the actual requester from the buyer.
-- A withdrawn request is terminal and must not block a later, fully collected
-- return. Preserve active-claim checks for gift and ordinary orders alike.
do $patch$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('private.assert_order_collections_complete(uuid)'::regprocedure);
 anchor:=$old$stage not in ('completed','rejected') and collection_required$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'gift_withdrawn_collection_anchor_changed';end if;
 execute replace(definition,anchor,$new$stage not in ('completed','rejected','withdrawn') and collection_required$new$);
 perform private.register_operator_internal_contract('private.assert_order_collections_complete(uuid)'::regprocedure);
end $patch$

do $patch$declare definition text;anchor text;contract record;begin
 definition:=pg_get_functiondef('public.admin_order_claim_detail(uuid)'::regprocedure);
 anchor:=$old$return result || jsonb_build_object('sellerIntake', private.seller_claim_intake_json(p_claim_id));$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'gift_claim_requester_anchor_changed';end if;
 execute replace(definition,anchor,$new$return result || jsonb_build_object('sellerIntake', private.seller_claim_intake_json(p_claim_id),'gift',private.gift_admin_claim_party(p_claim_id));$new$);
 select * into contract from private.operator_rpc_contracts where signature::regprocedure='public.admin_order_claim_detail(uuid)'::regprocedure;
 if not found then raise exception 'gift_claim_requester_contract_missing';end if;
 perform private.register_operator_rpc_contract('public.admin_order_claim_detail(uuid)'::regprocedure,contract.capability,contract.guard_kind,contract.legacy_admin_only);
end $patch$

create function public.service_list_fenced_gifts(p_actor uuid,p_after uuid default null,p_limit integer default 100) returns uuid[]
language plpgsql stable security definer set search_path='' as $$begin
 if p_actor is null or p_limit is null or p_limit not between 1 and 100 then raise invalid_parameter_value using message='invalid_gift_cleanup';end if;
 if not exists(select 1 from private.account_action_fences where subject_user_id=p_actor) then return array[]::uuid[];end if;
 return array(select g.id from private.gift_intents g where(g.sender_id=p_actor or g.recipient_id=p_actor) and g.order_id is null
  and(g.state in('awaiting_acceptance','accepted') or exists(select 1 from private.gift_recipient_addresses where gift_id=g.id)
    or exists(select 1 from private.goods_transaction_quotes q where q.source->>'kind'='gift' and q.source->>'id'=g.id::text and q.order_id is null))
  and(p_after is null or g.id>p_after) order by g.id limit p_limit);
end $$

create function public.service_cleanup_fenced_gift(p_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$declare gift private.gift_intents;begin
 begin gift:=private.gift_lock(p_id);exception when no_data_found then return jsonb_build_object('giftId',p_id,'state','missing');end;
 if gift.id is null then return jsonb_build_object('giftId',p_id,'state','missing');end if;
 if gift.order_id is not null then return jsonb_build_object('giftId',p_id,'state','ordered');end if;
 if not exists(select 1 from private.account_action_fences where subject_user_id in(gift.sender_id,gift.recipient_id)) then return jsonb_build_object('giftId',p_id,'state','not_fenced');end if;
 if gift.state in('awaiting_acceptance','accepted') then update private.gift_intents set state='canceled',closed_at=clock_timestamp(),updated_at=clock_timestamp(),revision=revision+1 where id=gift.id;end if;
 update private.gift_link_tokens set revoked_at=coalesce(revoked_at,clock_timestamp()) where gift_id=gift.id;
 delete from private.gift_claim_sessions where token_hash in(select token_hash from private.gift_link_tokens where gift_id=gift.id);
 delete from private.goods_transaction_quotes where actor_id=gift.sender_id and source->>'kind'='gift' and source->>'id'=gift.id::text and order_id is null;
 delete from private.gift_recipient_addresses where gift_id=gift.id;
 return jsonb_build_object('giftId',p_id,'state','cleaned');
end $$

create or replace function public.service_expire_gifts(p_limit integer default 100) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare candidate uuid;ids uuid[];subjects uuid[];gift private.gift_intents;changed integer:=0;begin
 ids:=array(select id from private.gift_intents where order_id is null and state in('awaiting_acceptance','accepted') and expires_at<=clock_timestamp()
  order by id limit greatest(1,least(coalesce(p_limit,100),100)));
 select array_agg(distinct subject order by subject) into subjects from private.gift_intents g cross join lateral unnest(array[g.sender_id,g.recipient_id]) subject where g.id=any(ids) and subject is not null;
 perform private.gift_lock_subjects(subjects);
 -- A recipient may have committed while the initial sender locks were waiting.
 -- Abort before any source lock; a fresh transaction can acquire the complete set.
 if exists(select 1 from private.gift_intents where id=any(ids) and recipient_id is not null and not(recipient_id=any(subjects))) then raise sqlstate 'PT409' using message='gift_changed';end if;
 foreach candidate in array ids loop
  begin gift:=private.gift_lock(candidate);exception when sqlstate 'PT409' then continue;end;
  if gift.order_id is not null or gift.state not in('awaiting_acceptance','accepted') or gift.expires_at>clock_timestamp() then continue;end if;
  update private.gift_intents set state='expired',closed_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where id=gift.id;
  update private.gift_link_tokens set revoked_at=clock_timestamp() where gift_id=gift.id and revoked_at is null;
  delete from private.goods_transaction_quotes where actor_id=gift.sender_id and source->>'kind'='gift' and source->>'id'=gift.id::text and order_id is null;
  delete from private.gift_recipient_addresses where gift_id=gift.id;changed:=changed+1;
 end loop;
 delete from private.gift_claim_sessions s where s.expires_at<=clock_timestamp() or exists(select 1 from private.gift_link_tokens t where t.token_hash=s.token_hash and(t.revoked_at is not null or t.consumed_at is not null));
 return jsonb_build_object('expired',changed);
end $$

-- Preserve the established order/customer/operator policies. Gift records are
-- already hidden by their parent restrictive policy, including collection rows.
do $$declare fn regprocedure;begin
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where
  n.nspname='private' and p.proname=any(array['request_order_claim_for_parties','gift_claim_actor','gift_claim_context','gift_admin_claim_party','gift_account_deletion_blockers']) or
  n.nspname='public' and p.proname=any(array['withdraw_my_gift_claim','get_my_gift_claim_context','request_my_gift_claim','set_my_gift_claim_refund_account','service_list_fenced_gifts','service_list_fenced_gift_cleanup_candidates','service_cleanup_fenced_gift']) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',fn);
  if (select n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.oid=fn::oid)='public' then
   execute format('grant execute on function %s to %s',fn,case when (select proname from pg_proc where oid=fn::oid) like 'service_%' then 'service_role' else 'authenticated' end);
  else execute format('grant execute on function %s to postgres',fn);end if;
  perform private.register_operator_internal_contract(fn);
 end loop;
end $$

-- Only these existing, capability-protected operation/search readers are changed.
-- All function signatures, owners, ACLs, filtering and ordering remain intact.
-- Unpaid/deposit-name readers intentionally keep the payer-visible public address:
-- gift payers are instructed to use the order code, never the recipient's private name.
do $$declare target record;definition text;changed text;found_count integer;begin
 for target in select * from (values
  ('public.admin_search_order_items_console(text,date,date,text,integer,integer,text,text,text,text)','o',3),
  ('public.admin_search_orders_console(text,date,date,text,integer,integer,timestamptz,text,text,text,text)','orders',1),
  ('public.admin_search_orders(text,date,date,text,integer,integer,timestamptz,text)','orders',3),
  ('public.admin_search_shipments_notice_console(text,uuid,text,date,date,integer,integer,text,text,text,text,text,text)','o',2),
  ('private.admin_order_detail_before_preorder(uuid)','o',6),
  ('private.admin_sales_claim_matches(public.order_cancellation_requests,text,date,date,text,text,text)','o',1),
  ('private.admin_search_shipments_before_delivery_methods(text,uuid,text,date,date,integer,integer)','o',2),
  ('private.admin_search_shipments_console_before_custom_inputs(text,uuid,text,date,date,integer,integer,text,text,text,text,text)','o',2),
  ('private.admin_shipment_export_before_preorder(uuid[])','o',6),
  ('private.collect_settled_export(date,date,text)','o',1)
 ) supplied(signature,alias,expected_count) loop
  definition:=pg_get_functiondef(target.signature::regprocedure);
  select count(*) into found_count from regexp_matches(definition,'\m'||target.alias||'\.address\M','g');
  if found_count<>target.expected_count then raise exception 'operational_address_reader_anchor_changed: %',target.signature;end if;
  changed:=regexp_replace(definition,'\m'||target.alias||'\.address\M','private.operational_order_address('||target.alias||'.id)','g');
  execute changed;
 end loop;
 definition:=pg_get_functiondef('private.admin_sales_order_matches(public.orders,date,date,text,text,text,text)'::regprocedure);
 if (length(definition)-length(replace(definition,'(p_order).address','')))/length('(p_order).address')<>2 then
  raise exception 'operational_order_search_anchor_changed';end if;
 execute replace(definition,'(p_order).address','private.operational_order_address((p_order).id)');
end $$

create function public.admin_get_order_transaction_receipts(p_order_ids uuid[]) returns jsonb
language plpgsql stable security definer set search_path='' as $$begin
 perform private.require_actor_operator_capability(auth.uid(),'sales.read',false);
 if p_order_ids is null or cardinality(p_order_ids)>1000 or array_position(p_order_ids,null) is not null then
  raise invalid_parameter_value using message='invalid_order_transaction_ids';end if;
 if exists(select 1 from public.orders o left join private.order_goods_transactions t on t.order_id=o.id
   where o.id=any(p_order_ids) and o.calculation_version=2 and t.order_id is null) then
  raise check_violation using message='order_transaction_receipt_missing';end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('orderId',o.id,'receipt',case when o.calculation_version=2 then t.original_receipt else null end) order by o.id),'[]')
  from public.orders o left join private.order_goods_transactions t on t.order_id=o.id where o.id=any(p_order_ids));
end $$

create function public.service_get_order_transaction_receipt(p_order_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare receipt jsonb;version integer;begin
 select o.calculation_version,t.original_receipt into version,receipt from public.orders o
  left join private.order_goods_transactions t on t.order_id=o.id where o.id=p_order_id;
 if not found or version=1 then return null;end if;
 if receipt is null then raise check_violation using message='order_transaction_receipt_missing';end if;
 return receipt;
end $$

create or replace function public.admin_shipment_export(target_ids uuid[]) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin
 if auth.uid() is null or not public.has_operator_capability('sales.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';end if;
 if exists(select 1 from public.order_shipments where id=any(target_ids) and delivery_method<>'parcel') then
  raise check_violation using message='delivery_method_evidence_required';end if;
 result:=private.admin_shipment_export_before_delivery_methods(target_ids);
 return jsonb_set(result,'{shipments}',(select jsonb_agg(entry.value||jsonb_build_object(
  'isGift',exists(select 1 from private.gift_intents g where g.order_id=s.order_id),
  'shippingCollectFee',s.shipping_collect_fee,
  'collector',(select group_value->'collector' from jsonb_array_elements(t.original_receipt#>'{display,shipping}') group_value
   where group_value->>'originId'=s.origin_id::text)) order by entry.ordinality)
  from jsonb_array_elements(result->'shipments') with ordinality entry(value,ordinality)
  join public.order_shipments s on s.id=(entry.value->>'id')::uuid
  left join private.order_goods_transactions t on t.order_id=s.order_id));
end $$

