create function public.service_record_gift_export(p_actor_id uuid,p_receipt_id uuid,p_fingerprint text,p_file_sha256 text) returns uuid
language plpgsql volatile security definer set search_path='' as $$declare receipt private.gift_export_receipts;audit_id uuid;begin
 if auth.role() is distinct from 'service_role' then raise insufficient_privilege using message='service_role_required';end if;
 perform private.require_actor_operator_capability(p_actor_id,'sales.read',false);
 select * into receipt from private.gift_export_receipts where id=p_receipt_id and actor_id=p_actor_id for share;
 if not found or receipt.expires_at<=clock_timestamp() or receipt.fingerprint is distinct from p_fingerprint
  or p_file_sha256 is null or p_file_sha256!~'^[0-9a-f]{64}$' then raise check_violation using message='gift_export_changed';end if;
 insert into public.audit_log(actor_id,action,target,diff) values(p_actor_id,'admin.gift_export.file_issued','gift-export:'||receipt.id::text,
  jsonb_build_object('receiptId',receipt.id,'fingerprint',receipt.fingerprint,'rowCount',jsonb_array_length(receipt.payload),
   'fileSha256',p_file_sha256,'format','xlsx','encryption','ECMA-376-Agile')) returning id into audit_id;
 return audit_id;
end $$

create function public.service_purge_gift_exports(p_limit integer default 1000) returns integer
language plpgsql volatile security definer set search_path='' as $$declare removed integer;begin
 if auth.role() is distinct from 'service_role' then raise insufficient_privilege using message='service_role_required';end if;
 if p_limit is null or p_limit not between 1 and 1000 then raise invalid_parameter_value using message='invalid_gift_purge_limit';end if;
 delete from private.gift_export_receipts where id in(select id from private.gift_export_receipts where created_at<clock_timestamp()-interval '24 hours'
  order by created_at,id for update skip locked limit p_limit);get diagnostics removed=row_count;return removed;
end $$

do $$declare item record;begin
 for item in select p.oid::regprocedure signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where
  n.nspname='private' and p.proname in('gift_console_state','gift_console_row','gift_console_query','gift_console_ids')
  or n.nspname='public' and p.proname in('admin_list_gifts','admin_prepare_gift_export','service_record_gift_export','service_purge_gift_exports') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',item.signature);
  if item.nspname='public' and item.proname like 'service_%' then execute format('grant execute on function %s to service_role',item.signature);
  elsif item.nspname='public' then execute format('grant execute on function %s to authenticated',item.signature);
  else execute format('grant execute on function %s to postgres',item.signature);end if;
  perform private.register_operator_internal_contract(item.signature);
 end loop;
end $$

-- Keep reviewed pure order readers compatible with PostgREST READ ONLY requests.
-- A STABLE RPC runs read-only even for POST. These readers do not reserve work
-- or mutate an order, so use the same capability predicate as address context.
-- https://docs.postgrest.org/en/v14/references/transactions.html#access-mode-on-functions

do $patch$
declare signature text;fn regprocedure;definition text;contract record;
 anchor text:=$old$perform private.require_actor_operator_capability(auth.uid(),'sales.read',false);$old$;
 replacement text:=$new$if not coalesce(private.has_operator_capability(auth.uid(),'sales.read',false),false) then
  raise insufficient_privilege using message='operator_capability_required';end if;$new$;
begin
 foreach signature in array array['public.admin_get_order_delivery_snapshots(uuid[])','public.admin_get_order_transaction_receipts(uuid[])'] loop
  fn:=signature::regprocedure;
  if (select provolatile from pg_proc where oid=fn::oid)<>'s' then raise exception 'order_reader_volatility_changed: %',signature;end if;
  definition:=pg_get_functiondef(fn);
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then
   raise exception 'order_reader_capability_anchor_changed: %',signature;end if;
  execute replace(definition,anchor,replacement);
  select * into contract from private.operator_rpc_contracts registered where registered.signature::regprocedure=fn;
  if not found or contract.capability<>'sales.read' or contract.guard_kind<>'read' or contract.legacy_admin_only then
   raise exception 'order_reader_permission_contract_changed: %',signature;end if;
  perform private.register_operator_rpc_contract(fn,contract.capability,contract.guard_kind,contract.legacy_admin_only);
 end loop;
end $patch$

create or replace function public.admin_list_category_displays() returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.has_operator_capability('store.manage') then raise insufficient_privilege using message='operator_capability_required';end if;
 return jsonb_build_object('checkedAt',statement_timestamp(),'revision',(select revision from private.category_display_tree_control where singleton),
 'categories',coalesce((with recursive tree as (
  select n.id,array[lpad(n.sort_order::text,10,'0')||':'||coalesce(n.legacy_sort_key,n.id::text)] path from private.category_display_nodes n where n.parent_id is null
  union all select n.id,t.path||(lpad(n.sort_order::text,10,'0')||':'||coalesce(n.legacy_sort_key,n.id::text)) from private.category_display_nodes n join tree t on n.parent_id=t.id
 ) select jsonb_agg(private.category_display_category(n.id) order by t.path) from private.category_display_nodes n join tree t on t.id=n.id),'[]'::jsonb),
 'sourceCategories',coalesce((select jsonb_agg(private.category_display_source_category(c.id) order by c.depth,c.sort_order,c.code)
  from public.catalog_categories c where c.archived_at is null),'[]'::jsonb));
end $$

create function public.admin_update_category_display_tree(p_change jsonb,p_expected_revision bigint,p_operation_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid; action_name text; node_id uuid; parent_node_id uuid; node_name text; destination integer;
 previous private.category_display_nodes; current_revision bigint; receipt public.audit_log; request jsonb; result jsonb;
 parent_depth integer; subtree_height integer; sibling_count integer; member record; ordered_ids uuid[];
begin
 actor:=private.require_operator_capability('store.manage',false);
 if p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or jsonb_typeof(p_change) is distinct from 'object' or jsonb_typeof(p_change->'action') is distinct from 'string'
  or p_change->>'action' not in('create','update','archive','restore')
  or jsonb_typeof(p_change->'id') is distinct from 'string'
  or p_change->>'id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 then raise invalid_parameter_value using message='invalid_display_tree_change';end if;
 action_name:=p_change->>'action';node_id:=(p_change->>'id')::uuid;
 if action_name in('create','update') then
  if (select count(*) from jsonb_object_keys(p_change))<>5 or not p_change ?& array['action','id','name','parentId','position']
   or jsonb_typeof(p_change->'name') is distinct from 'string' or btrim(p_change->>'name')=''
   or p_change->>'name' ~ '[\x00-\x1f\x7f]' or p_change->>'name'<>btrim(p_change->>'name')
   or jsonb_typeof(p_change->'parentId') not in('string','null')
   or p_change->>'parentId' is not null and p_change->>'parentId' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(p_change->'position') is distinct from 'number' or p_change->>'position' !~ '^[0-9]{1,6}$'
   then raise invalid_parameter_value using message='invalid_display_tree_details';end if;
  parent_node_id:=(p_change->>'parentId')::uuid;node_name:=p_change->>'name';destination:=(p_change->>'position')::integer;
 elsif (select count(*) from jsonb_object_keys(p_change))<>2 then raise invalid_parameter_value using message='invalid_display_tree_lifecycle';end if;
 request:=jsonb_build_object('change',p_change,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('category-display-operation:'||p_operation_id,0));
 select * into receipt from public.audit_log where id=p_operation_id;
 if found then
  if receipt.actor_id=actor and receipt.action='admin.category_display.tree_changed' and receipt.target='category-display:'||node_id and receipt.diff->'request'=request then return receipt.diff->'result';end if;
  raise unique_violation using message='operation_conflict';
 end if;
 -- The same lock precedes source-category/product locks in composition writes.
 perform pg_advisory_xact_lock(hashtextextended('catalog_category_tree',0));
 select revision into current_revision from private.category_display_tree_control where singleton for update;
 if current_revision<>p_expected_revision then raise sqlstate 'PT409' using message='category_display_tree_conflict';end if;
 select * into previous from private.category_display_nodes where id=node_id for update;
 if action_name='create' and found then raise unique_violation using message='display_node_exists';end if;
 if action_name<>'create' and not found then raise no_data_found using message='display_node_missing';end if;
 if action_name in('create','update') then
  if char_length(node_name)>20 and (action_name='create' or node_name is distinct from previous.name) then raise check_violation using message='display_node_name_limit';end if;
  if node_id=parent_node_id then raise check_violation using message='display_tree_cycle';end if;
  if parent_node_id is not null then
   if not exists(select 1 from private.category_display_nodes where id=parent_node_id and archived_at is null)
    or exists(with recursive ancestors as (select * from private.category_display_nodes where id=parent_node_id
      union all select p.* from private.category_display_nodes p join ancestors a on p.id=a.parent_id)
      select 1 from ancestors where id=node_id or archived_at is not null)
    then raise check_violation using message='display_parent_unavailable';end if;
   parent_depth:=(private.category_display_category(parent_node_id)->>'depth')::integer;
  else parent_depth:=0;end if;
  if action_name='create' or parent_node_id is distinct from previous.parent_id then
   with recursive descendants as (select node_id id,1 height union all select n.id,d.height+1 from private.category_display_nodes n join descendants d on n.parent_id=d.id)
   select max(height) into subtree_height from descendants;
   if parent_depth+subtree_height>3 then raise check_violation using message='display_tree_depth_limit';end if;
  end if;
  if action_name='create' or parent_node_id is distinct from previous.parent_id then
   select count(*) into sibling_count from private.category_display_nodes where parent_id is not distinct from parent_node_id and archived_at is null and id<>node_id;
   if sibling_count>=(case when parent_node_id is null then 19 else 15 end) then raise check_violation using message='display_tree_sibling_limit';end if;
  end if;
  if action_name='create' then
   insert into private.category_display_nodes(id,parent_id,name,sort_order) values(node_id,parent_node_id,node_name,0);
  else
   update private.category_display_nodes set name=node_name,parent_id=parent_node_id,updated_at=clock_timestamp() where id=node_id;
  end if;
  select coalesce(array_agg(id order by sort_order,coalesce(legacy_sort_key,id::text),id),'{}'::uuid[]) into ordered_ids from private.category_display_nodes where parent_id is not distinct from parent_node_id and id<>node_id;
  if destination>cardinality(ordered_ids) then raise invalid_parameter_value using message='display_tree_position_out_of_range';end if;
  ordered_ids:=coalesce(ordered_ids[1:destination],'{}'::uuid[])||array[node_id]||coalesce(ordered_ids[destination+1:cardinality(ordered_ids)],'{}'::uuid[]);
  for member in select id,ordinality-1 position from unnest(ordered_ids) with ordinality ids(id,ordinality) loop
   update private.category_display_nodes set sort_order=member.position,updated_at=clock_timestamp() where id=member.id and sort_order<>member.position;
  end loop;
 elsif action_name='archive' then
  if previous.archived_at is not null then raise check_violation using message='display_node_already_archived';end if;
  update private.category_display_nodes set archived_at=clock_timestamp(),updated_at=clock_timestamp() where id=node_id;
 else
  if previous.archived_at is null then raise check_violation using message='display_node_not_archived';end if;
  select count(*) into sibling_count from private.category_display_nodes where parent_id is not distinct from previous.parent_id and archived_at is null;
  if sibling_count>=(case when previous.parent_id is null then 19 else 15 end) then raise check_violation using message='display_tree_sibling_limit';end if;
  if previous.parent_id is not null and exists(with recursive ancestors as (select * from private.category_display_nodes where id=previous.parent_id
    union all select p.* from private.category_display_nodes p join ancestors a on p.id=a.parent_id) select 1 from ancestors where archived_at is not null)
    then raise check_violation using message='display_parent_unavailable';end if;
  update private.category_display_nodes set archived_at=null,updated_at=clock_timestamp() where id=node_id;
 end if;
 update private.category_display_tree_control set revision=current_revision+1 where singleton;
 result:=jsonb_build_object('nodeId',node_id,'directory',public.admin_list_category_displays());
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.category_display.tree_changed','category-display:'||node_id,
  jsonb_build_object('request',request,'before',case when action_name='create' then null else to_jsonb(previous) end,'result',result));
 return result;
end $$

-- Keep the existing composition implementation and owner/ACL; only separate its
-- source-category validation from the display target and preserve lock ordering.
do $$declare definition text;
begin
 definition:=pg_get_functiondef('public.admin_save_category_display(uuid,jsonb,bigint,uuid)'::regprocedure);
 if position('where c.id=p_category_id or c.id in' in definition)=0
  or position('where private.category_display_category(id::uuid) is null' in definition)=0 then raise exception 'category_display_save_source_drift';end if;
 definition:=replace(definition,'where c.id=p_category_id or c.id in','where c.id in');
 definition:=replace(definition,'where private.category_display_category(id::uuid) is null','where private.category_display_source_category(id::uuid) is null');
 execute definition;
 definition:=pg_get_functiondef('private.category_display_matching_goods(jsonb)'::regprocedure);
 if position('private.category_display_category(c.id)' in definition)=0 then raise exception 'category_display_match_source_drift';end if;
 execute replace(definition,'private.category_display_category(c.id)','private.category_display_source_category(c.id)');
end $$

create function private.lock_claim_refund_account_session(p_actor uuid,p_session_id uuid) returns void
language plpgsql volatile security definer set search_path='' as $$
begin
 -- A logout/expiry update and an accepted write have a single ordering point.
 -- Readers that only return context remain STABLE and do not take row locks.
 perform id from auth.sessions where id=p_session_id and user_id=p_actor
  and (not_after is null or not_after>clock_timestamp()) for share;
 if not found then raise insufficient_privilege using message='refund_account_auth_changed';end if;
 perform private.require_claim_refund_account_identity(p_actor,p_session_id);
end $$

create function public.get_my_order_claim_refund_account_context(p_order_id uuid,p_claim_id uuid,p_expected_actor_id uuid,p_expected_session_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare purchase public.orders;claim public.order_cancellation_requests;account private.claim_refund_accounts;blocker text;
begin
 perform private.require_claim_refund_account_identity(p_expected_actor_id,p_expected_session_id);
 select * into purchase from public.orders where id=p_order_id and user_id=p_expected_actor_id;
 select * into claim from public.order_cancellation_requests where id=p_claim_id and order_id=purchase.id;
 if purchase.id is null or claim.id is null or exists(select 1 from private.gift_intents where order_id=purchase.id) then
  raise sqlstate 'PT404' using message='claim_not_found';end if;
 blocker:=private.order_claim_refund_account_blocker(claim,purchase);
 select * into account from private.claim_refund_accounts where claim_id=claim.id;
 return jsonb_build_object('actorId',p_expected_actor_id,'orderId',purchase.id,'claimId',claim.id,
  'claimType',claim.claim_type,'stage',claim.stage,'revision',claim.claim_revision,'allowed',blocker is null,'blocker',blocker,
  'maskedAccount',account.masked_account,'maskedHolder',account.masked_holder,'recordedAt',account.created_at);
end $$

create function public.set_my_order_claim_refund_account(p_order_id uuid,p_claim_id uuid,p_operation_id uuid,p_expected_revision integer,
 p_bank_name text,p_account_number text,p_account_holder text,p_expected_actor_id uuid,p_expected_session_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare purchase public.orders;claim public.order_cancellation_requests;previous private.order_claim_refund_account_operations;
 request_hash text;blocker text;result_revision integer;
begin
 perform private.require_claim_refund_account_identity(p_expected_actor_id,p_expected_session_id);
 if p_order_id is null or p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or p_bank_name is null or p_bank_name<>btrim(p_bank_name) or char_length(p_bank_name) not between 1 and 40 or p_bank_name~'[[:cntrl:]]'
  or p_account_number is null or p_account_number!~'^[0-9-]{8,30}$' or p_account_number!~'[0-9]'
  or p_account_holder is null or p_account_holder<>btrim(p_account_holder) or char_length(p_account_holder) not between 1 and 40 or p_account_holder~'[[:cntrl:]]'
  then raise invalid_parameter_value using message='invalid_claim_refund_account';end if;
 if not exists(select 1 from public.orders o join public.order_cancellation_requests c on c.order_id=o.id
  where o.id=p_order_id and o.user_id=p_expected_actor_id and c.id=p_claim_id)
  or exists(select 1 from private.gift_intents where order_id=p_order_id) then raise sqlstate 'PT404' using message='claim_not_found';end if;
 -- Match existing account-deletion, claim, and refund ordering. Existing-order
 -- recovery remains available to its owner even when new purchases are fenced.
 perform private.lock_operator_subjects(array[p_expected_actor_id]);
 perform private.lock_claim_refund_account_session(p_expected_actor_id,p_expected_session_id);
 perform pg_advisory_xact_lock(hashtextextended('claim-refund-account:'||p_operation_id::text,0));
 request_hash:=encode(extensions.digest(jsonb_build_array(p_operation_id,p_order_id,p_claim_id,p_expected_actor_id,
  p_expected_session_id,p_expected_revision,p_bank_name,p_account_number,p_account_holder)::text,'sha256'),'hex');
 select * into previous from private.order_claim_refund_account_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>p_expected_actor_id or previous.session_id<>p_expected_session_id or previous.order_id<>p_order_id
   or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision then
   raise unique_violation using message='refund_account_request_conflict';end if;
  if previous.state='sealed' then raise check_violation using message='refund_account_request_sealed';end if;
  if previous.request_hash is null then raise check_violation using message='refund_account_request_expired';end if;
  if previous.request_hash<>request_hash then raise unique_violation using message='refund_account_request_conflict';end if;
  return private.order_claim_refund_account_receipt(p_operation_id,p_expected_actor_id,p_expected_session_id);
 end if;
 select * into purchase from public.orders where id=p_order_id and user_id=p_expected_actor_id for update;
 if not found then raise sqlstate 'PT404' using message='claim_not_found';end if;
 perform id from public.order_shipments where order_id=purchase.id order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id and order_id=purchase.id for update;
 if not found then raise sqlstate 'PT404' using message='claim_not_found';end if;
 if claim.claim_revision<>p_expected_revision then raise sqlstate 'PT409' using message='claim_changed';end if;
 perform id from public.payments where purpose='order' and ref_id=purchase.id order by id for update;
 perform r.id from public.refunds r join public.payments p on p.id=r.payment_id
  where p.purpose='order' and p.ref_id=purchase.id order by r.id for update of r;
 blocker:=private.order_claim_refund_account_blocker(claim,purchase);
 if blocker is not null then raise check_violation using message=blocker;end if;
 insert into private.claim_refund_accounts(claim_id,bank_name,account_number,account_holder,masked_account,masked_holder)
 values(claim.id,p_bank_name,p_account_number,p_account_holder,p_bank_name||' '||public.mask_refund_account_number(p_account_number),public.mask_refund_account_holder(p_account_holder));
 update public.order_cancellation_requests set updated_at=clock_timestamp() where id=claim.id returning claim_revision into result_revision;
 insert into private.order_claim_refund_account_operations(id,actor_id,session_id,order_id,claim_id,expected_revision,result_revision,state,request_hash)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,purchase.id,claim.id,p_expected_revision,result_revision,'saved',request_hash);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'order.claim_refund_account_confirmed','order:'||purchase.id,
  jsonb_build_object('claimId',claim.id,'claimType',claim.claim_type,'revision',p_expected_revision,'resultRevision',result_revision));
 return private.order_claim_refund_account_receipt(p_operation_id,p_expected_actor_id,p_expected_session_id);
end $$

create function public.read_my_order_claim_refund_account_operation(p_order_id uuid,p_claim_id uuid,p_operation_id uuid,p_expected_revision integer,
 p_expected_actor_id uuid,p_expected_session_id uuid,p_seal boolean default false) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare previous private.order_claim_refund_account_operations;
begin
 perform private.require_claim_refund_account_identity(p_expected_actor_id,p_expected_session_id);
 if p_order_id is null or p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 or p_seal is null then
  raise invalid_parameter_value using message='invalid_claim_refund_account';end if;
 if not exists(select 1 from public.orders o join public.order_cancellation_requests c on c.order_id=o.id
  where o.id=p_order_id and o.user_id=p_expected_actor_id and c.id=p_claim_id)
  or exists(select 1 from private.gift_intents where order_id=p_order_id) then raise sqlstate 'PT404' using message='claim_not_found';end if;
 perform private.lock_operator_subjects(array[p_expected_actor_id]);
 perform private.lock_claim_refund_account_session(p_expected_actor_id,p_expected_session_id);
 -- A read waits for the current writer; sealing also excludes a delayed writer.
 perform pg_advisory_xact_lock(hashtextextended('claim-refund-account:'||p_operation_id::text,0));
 select * into previous from private.order_claim_refund_account_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>p_expected_actor_id or previous.session_id<>p_expected_session_id or previous.order_id<>p_order_id
   or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision then
   raise unique_violation using message='refund_account_request_conflict';end if;
 elsif p_seal then
  insert into private.order_claim_refund_account_operations(id,actor_id,session_id,order_id,claim_id,expected_revision,result_revision,state)
  values(p_operation_id,p_expected_actor_id,p_expected_session_id,p_order_id,p_claim_id,p_expected_revision,p_expected_revision,'sealed');
 end if;
 return private.order_claim_refund_account_receipt(p_operation_id,p_expected_actor_id,p_expected_session_id);
end $$

revoke all on function private.require_claim_refund_account_identity(uuid,uuid),
 private.lock_claim_refund_account_session(uuid,uuid),
 private.order_claim_refund_account_blocker(public.order_cancellation_requests,public.orders),
 private.order_claim_refund_account_receipt(uuid,uuid,uuid),private.purge_claim_refund_account_operation_hash(),
 public.get_my_order_claim_refund_account_context(uuid,uuid,uuid,uuid),
 public.set_my_order_claim_refund_account(uuid,uuid,uuid,integer,text,text,text,uuid,uuid),
 public.read_my_order_claim_refund_account_operation(uuid,uuid,uuid,integer,uuid,uuid,boolean)
 from public,anon,authenticated,service_role

grant execute on function public.get_my_order_claim_refund_account_context(uuid,uuid,uuid,uuid),
 public.set_my_order_claim_refund_account(uuid,uuid,uuid,integer,text,text,text,uuid,uuid),
 public.read_my_order_claim_refund_account_operation(uuid,uuid,uuid,integer,uuid,uuid,boolean) to authenticated

create function private.require_bank_transfer_refund_identity(p_actor uuid,p_session uuid) returns void
language plpgsql stable security definer set search_path='' as $$begin
 perform private.require_claim_refund_account_identity(p_actor,p_session);
 -- The current payment-operations gate is sales.manage with legacy admin-only;
 -- there is no payments.manage capability in the accepted capability registry.
 if not private.has_operator_capability(p_actor,'sales.manage',true) then
  raise insufficient_privilege using message='bank_refund_permission_required';end if;
end $$

create function private.lock_bank_transfer_refund_identity(p_order uuid,p_claim uuid,p_actor uuid,p_session uuid) returns void
language plpgsql volatile security definer set search_path='' as $$
declare payer uuid;recipient uuid;
begin
 perform private.require_bank_transfer_refund_identity(p_actor,p_session);
 select o.user_id,g.recipient_id into payer,recipient from public.orders o
  join public.order_cancellation_requests c on c.order_id=o.id and c.id=p_claim
  left join private.gift_intents g on g.order_id=o.id where o.id=p_order;
 if payer is null then raise sqlstate 'PT404' using message='claim_not_found';end if;
 -- Include the payer/recipient account fence before any order lock, in the same
 -- sorted order used by gift requests and account-deletion admission.
 perform private.lock_operator_subjects(array[p_actor,payer,recipient]);
 perform private.require_operator_capability('sales.manage',true);
 perform private.lock_claim_refund_account_session(p_actor,p_session);
 perform private.require_bank_transfer_refund_identity(p_actor,p_session);
end $$

create function private.bank_transfer_refund_blocker(p_claim public.order_cancellation_requests,p_order public.orders,p_kind text) returns text
language plpgsql stable security definer set search_path='' as $$
declare payment public.payments;refund public.refunds;lifecycle private.bank_transfer_claim_refunds;gift private.gift_intents;
begin
 if p_order.id is null or p_claim.id is null or p_claim.order_id is distinct from p_order.id then return 'claim_not_found';end if;
 if p_order.payment_method is distinct from 'bank_transfer' or p_order.total<=0 then return 'bank_refund_payment_unavailable';end if;
 if p_claim.claim_type not in('cancel','return') then return 'bank_refund_claim_unavailable';end if;
 select * into gift from private.gift_intents where order_id=p_order.id;
 if gift.id is not null and not exists(select 1 from private.gift_claim_parties party where party.claim_id=p_claim.id
  and party.gift_id=gift.id and party.payer_id=gift.sender_id and party.payer_id=p_order.user_id
  and party.payer_id=p_claim.requested_by and party.recipient_id=gift.recipient_id
  and party.actual_requester in(party.payer_id,party.recipient_id)) then return 'bank_refund_gift_parties_invalid';end if;
 if (select count(*) from public.payments where purpose='order' and ref_id=p_order.id)<>1 then return 'bank_refund_payment_unavailable';end if;
 select * into payment from public.payments where purpose='order' and ref_id=p_order.id;
 if payment.provider<>'bank_transfer' or payment.user_id is distinct from p_order.user_id or payment.amount<>p_order.total
  or payment.amount<=0 or payment.payment_key is null or payment.payment_key not like 'bank_transfer:%'
  or payment.status<>'paid' then return 'bank_refund_payment_unavailable';end if;
 if exists(select 1 from public.payment_attempts attempt where attempt.purpose='order' and attempt.ref_id=p_order.id
  and(attempt.state in('prepared','confirming','unknown','needs_review')
   or attempt.state='approved' and(attempt.provider<>'bank_transfer' or attempt.payment_id is distinct from payment.id or attempt.amount<>payment.amount)))
 then return 'bank_refund_payment_unavailable';end if;
 if not private.claim_collections_complete(p_claim.id) then return 'claim_collections_incomplete';end if;
 if not exists(select 1 from private.claim_refund_accounts where claim_id=p_claim.id and purged_at is null
  and bank_name is not null and account_number is not null and account_holder is not null) then return 'claim_refund_account_missing';end if;
 select * into refund from public.refunds where payment_id=payment.id;
 if refund.id is not null and(refund.cancellation_request_id is distinct from p_claim.id or refund.amount<>payment.amount
  or refund.method is not null and refund.method<>'bank_transfer' or refund.completed_at is not null or refund.status='done') then
  return 'bank_refund_ledger_unavailable';end if;
 select * into lifecycle from private.bank_transfer_claim_refunds where claim_id=p_claim.id;
 if p_claim.stage not in('collected','processing','needs_review') or p_claim.status not in('requested','processing','needs_review') then
  return 'bank_refund_claim_unavailable';end if;
 if p_kind='file_transfer' then
  if refund.filed_at is not null then return 'bank_refund_already_filed';end if;
  if p_claim.claim_type='cancel' and lifecycle.state is distinct from 'awaiting_transfer' then return 'bank_refund_confirmation_required';end if;
  if p_claim.claim_type='return' and p_claim.stage not in('collected','processing') then return 'bank_refund_claim_unavailable';end if;
  if lifecycle.claim_id is null and p_order.status not in('paid','confirmed','shipping','delivered','done') then return 'bank_refund_claim_unavailable';end if;
 elsif p_kind='confirm_cancellation' then
  if lifecycle.claim_id is not null then return 'bank_refund_already_confirmed';end if;
  if p_order.status not in('paid','confirmed','shipping','delivered','done') or p_claim.stage not in('processing','needs_review') then return 'bank_refund_claim_unavailable';end if;
  if p_claim.claim_type='return' and(refund.filed_at is null or refund.method is distinct from 'bank_transfer') then return 'bank_refund_filing_required';end if;
  if not exists(select 1 from public.order_cancellation_claims where order_id=p_order.id) then return 'bank_refund_approval_required';end if;
  if p_claim.claim_type='cancel' and not p_claim.collection_required and not private.order_cancel_eligible(p_order.id) then return 'order_not_cancelable';end if;
 elsif p_kind in('complete_transfer','view_account') then
  if lifecycle.state is distinct from 'awaiting_transfer' or p_order.status<>'canceled'
   or lifecycle.payment_id<>payment.id or lifecycle.payer_id is distinct from p_order.user_id or lifecycle.amount<>payment.amount
   or refund.status is distinct from 'awaiting_transfer' then return 'bank_refund_confirmation_required';end if;
  if refund.filed_at is null or refund.method is distinct from 'bank_transfer' then return 'bank_refund_filing_required';end if;
 else return 'invalid_bank_refund_operation';end if;
 return null;
end $$

create function private.finalize_bank_transfer_claim_refund(p_order_id uuid,p_reason text) returns void
language plpgsql volatile security definer set search_path='' as $$
declare purchase public.orders;payment public.payments;lifecycle private.bank_transfer_claim_refunds;item record;
begin
 select * into purchase from public.orders where id=p_order_id for update;
 perform id from public.order_shipments where order_id=p_order_id order by id for update;
 select * into lifecycle from private.bank_transfer_claim_refunds where order_id=p_order_id for update;
 if not found and private.bank_transfer_refund_legacy_completed(p_order_id) then
  -- Preserve a completely finished historical ledger as an exact no-op. This
  -- cannot advance any active claim, create transfer proof or restore stock.
  return;
 end if;
 if not found or purchase.payment_method is distinct from 'bank_transfer' or purchase.total<>lifecycle.amount then
  raise check_violation using message='bank_refund_operator_evidence_required';end if;
 perform id from public.order_cancellation_requests where id=lifecycle.claim_id and order_id=p_order_id for update;
 perform private.assert_claim_collections_complete(lifecycle.claim_id);
 perform id from public.payments where purpose='order' and ref_id=p_order_id order by id for update;
 if (select count(*) from public.payments where purpose='order' and ref_id=p_order_id)<>1 then
  raise check_violation using message='bank_refund_payment_unavailable';end if;
 select * into payment from public.payments where id=lifecycle.payment_id;
 if payment.provider<>'bank_transfer' or payment.purpose<>'order' or payment.ref_id<>p_order_id
  or payment.user_id is distinct from lifecycle.payer_id or purchase.user_id is distinct from lifecycle.payer_id
  or payment.amount<>lifecycle.amount or payment.status not in('paid','refunded') then
  raise check_violation using message='bank_refund_payment_unavailable';end if;
 if lifecycle.state='awaiting_transfer' and payment.status<>'paid' then raise check_violation using message='bank_refund_payment_unavailable';end if;
 if purchase.status not in('paid','confirmed','shipping','delivered','done','canceled') then
  raise check_violation using message='bank_refund_claim_unavailable';end if;
 if not exists(select 1 from public.order_cancellation_claims where order_id=p_order_id) and purchase.status<>'canceled' then
  raise check_violation using message='bank_refund_approval_required';end if;
 if purchase.status<>'canceled' then
  for item in select id from public.order_items where order_id=p_order_id order by good_id,id loop
   perform private.restore_order_item_supply(item.id,p_reason);
  end loop;
  perform id from public.draw_tickets where source='order_paid' and source_id=p_order_id and consumed_at is null and revoked_at is null order by id for update;
  update public.draw_tickets set revoked_at=clock_timestamp() where source='order_paid' and source_id=p_order_id and consumed_at is null and revoked_at is null;
 end if;
 insert into public.refunds(payment_id,amount,reason,status,cancellation_request_id,method)
 values(payment.id,payment.amount,p_reason,case when lifecycle.state='completed' then 'done' else 'awaiting_transfer' end,lifecycle.claim_id,'bank_transfer')
 on conflict(payment_id) do update set status=excluded.status,method='bank_transfer',cancellation_request_id=excluded.cancellation_request_id;
 if lifecycle.state='completed' then update public.payments set status='refunded' where id=payment.id and status<>'refunded';end if;
 if purchase.status<>'canceled' then update public.orders set status='canceled',expires_at=null where id=p_order_id;end if;
 if lifecycle.state='completed' then delete from public.order_cancellation_claims where order_id=p_order_id;end if;
end $$

do $patch$ declare definition text;anchor text:=E'begin
  select orders.status';begin
 definition:=pg_get_functiondef('public.finalize_order_cancellation_with_provider_evidence(uuid,text,text[])'::regprocedure);
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'bank_finalizer_anchor_changed';end if;
 execute replace(definition,anchor,E'begin
  if exists(select 1 from public.payments where purpose=''order'' and ref_id=p_order_id and provider=''bank_transfer'' and status<>''failed'') then
    perform private.finalize_bank_transfer_claim_refund(p_order_id,p_reason);
    return;
  end if;
  select orders.status');
end $patch$

-- A returned bank order can be canceled while the actual transfer is pending.
-- The exception is the confirmed, exact bank ledger above; provider-card and
-- unknown/prepared attempt evidence rules remain byte-for-byte unchanged.
do $patch$ declare definition text;anchor text;begin
 definition:=pg_get_functiondef('private.guard_order_claim_cancellation_transition()'::regprocedure);
 anchor:='if not private.order_cancel_eligible(old.id) and (';
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'bank_claim_transition_anchor_changed';end if;
 execute replace(definition,anchor,'if not private.order_cancel_eligible(old.id) and not private.bank_transfer_refund_pending_evidence_valid(old.id,null) and (');
 definition:=pg_get_functiondef('private.guard_unresolved_goods_payment_cancellation()'::regprocedure);
 anchor:='        and attempt.ref_id = old.id';
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'bank_attempt_transition_anchor_changed';end if;
 execute replace(definition,anchor,anchor||$new$
        and not(attempt.provider='bank_transfer' and attempt.state='approved'
          and private.bank_transfer_refund_pending_evidence_valid(old.id,attempt.payment_id))
$new$);
end $patch$

create function private.guard_bank_transfer_refund_ledger() returns trigger
language plpgsql volatile security definer set search_path='' as $$
declare lifecycle private.bank_transfer_claim_refunds;payment public.payments;
begin
 select * into payment from public.payments where id=new.payment_id;
 if payment.provider='bank_transfer' and payment.purpose='order' then
  if new.method is not null and new.method<>'bank_transfer' then raise check_violation using message='bank_refund_method_required';end if;
  select * into lifecycle from private.bank_transfer_claim_refunds where payment_id=payment.id;
  if new.status='awaiting_transfer' and lifecycle.state is distinct from 'awaiting_transfer'
   or new.status='done' and lifecycle.state is distinct from 'completed'
   or lifecycle.state='awaiting_transfer' and new.status<>'awaiting_transfer'
   or lifecycle.state='completed' and new.status<>'done'
   or lifecycle.claim_id is not null and(new.cancellation_request_id is distinct from lifecycle.claim_id or new.amount<>lifecycle.amount)
  then raise check_violation using message='bank_refund_evidence_required';end if;
 elsif new.status='awaiting_transfer' then raise check_violation using message='bank_refund_payment_unavailable';end if;
 return new;
end $$

create function private.guard_bank_transfer_refund_lifecycle() returns trigger
language plpgsql volatile security definer set search_path='' as $$
declare lifecycle private.bank_transfer_claim_refunds;
begin
 if tg_table_name='payments' then
  select * into lifecycle from private.bank_transfer_claim_refunds where payment_id=old.id;
  if lifecycle.claim_id is not null and(new.user_id is distinct from old.user_id or new.provider is distinct from old.provider
   or new.purpose is distinct from old.purpose or new.ref_id is distinct from old.ref_id or new.amount is distinct from old.amount
   or new.payment_key is distinct from old.payment_key or lifecycle.state='awaiting_transfer' and new.status<>'paid'
   or lifecycle.state='completed' and new.status<>'refunded') then raise check_violation using message='bank_refund_evidence_required';end if;
 elsif tg_table_name='order_cancellation_requests' then
  select * into lifecycle from private.bank_transfer_claim_refunds where claim_id=old.id;
  if lifecycle.state='awaiting_transfer' and(new.stage in('completed','rejected','withdrawn') or new.status in('completed','rejected')
   or new.claim_type is distinct from old.claim_type or new.requested_by is distinct from old.requested_by or new.order_id is distinct from old.order_id)
  then raise check_violation using message='bank_refund_transfer_pending';end if;
 elsif tg_table_name='claim_refund_accounts' then
  select * into lifecycle from private.bank_transfer_claim_refunds where claim_id=old.claim_id;
  if lifecycle.state='awaiting_transfer' and(new.bank_name is distinct from old.bank_name or new.account_number is distinct from old.account_number
   or new.account_holder is distinct from old.account_holder or new.purged_at is not null or new.purge_after is not null)
  then raise check_violation using message='bank_refund_transfer_pending';end if;
 end if;
 return new;
end $$

-- Existing refund recording remains the shared notification/audit path. A bank
-- cancellation must have been confirmed first; bank completion needs the new
-- durable transfer evidence even when a caller reaches this older public RPC.
do $patch$ declare definition text;anchor text:='  perform private.assert_claim_collections_complete(p_claim_id);';begin
 definition:=pg_get_functiondef('public.admin_record_order_claim_refund(uuid,text,text,text)'::regprocedure);
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'bank_refund_record_anchor_changed';end if;
 execute replace(definition,anchor,anchor||$new$
  if exists(select 1 from public.orders where id=v_claim.order_id and payment_method='bank_transfer') then
    perform private.require_operator_capability('sales.manage',true);
    if p_method<>'bank_transfer' then raise check_violation using message='bank_refund_method_required';end if;
    if p_stage='completed' and private.bank_transfer_refund_legacy_completed_claim(v_claim.order_id,p_claim_id) then return 'completed';end if;
    if p_stage='filed' and v_claim.claim_type='cancel' and not exists(select 1 from private.bank_transfer_claim_refunds where claim_id=p_claim_id and state='awaiting_transfer') then
      raise check_violation using message='bank_refund_confirmation_required';end if;
    if p_stage='completed' and not exists(select 1 from private.bank_transfer_claim_refunds where claim_id=p_claim_id and state='completed') then
      raise check_violation using message='bank_refund_evidence_required';end if;
  end if;
$new$);
end $patch$

create function public.admin_bank_transfer_refund_context(p_order_id uuid,p_claim_id uuid,p_expected_actor_id uuid,p_expected_session_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare purchase public.orders;claim public.order_cancellation_requests;payment public.payments;refund public.refunds;
 lifecycle private.bank_transfer_claim_refunds;account private.claim_refund_accounts;
begin
 perform private.require_bank_transfer_refund_identity(p_expected_actor_id,p_expected_session_id);
 select * into purchase from public.orders where id=p_order_id;
 select * into claim from public.order_cancellation_requests where id=p_claim_id and order_id=purchase.id;
 if purchase.id is null or claim.id is null then raise sqlstate 'PT404' using message='claim_not_found';end if;
 select * into payment from public.payments where purpose='order' and ref_id=p_order_id order by id limit 1;
 select * into refund from public.refunds where payment_id=payment.id and cancellation_request_id=claim.id;
 select * into lifecycle from private.bank_transfer_claim_refunds where claim_id=claim.id;
 select * into account from private.claim_refund_accounts where claim_id=claim.id;
 return jsonb_build_object('actorId',p_expected_actor_id,'orderId',purchase.id,'claimId',claim.id,'claimType',claim.claim_type,
  'revision',claim.claim_revision,'amount',purchase.total,'stage',claim.stage,
  'phase',coalesce(lifecycle.state,case when private.bank_transfer_refund_legacy_completed_claim(purchase.id,claim.id) then 'completed' else 'not_confirmed' end),'filedAt',refund.filed_at,
  'confirmedAt',lifecycle.confirmed_at,'transferredAt',lifecycle.transferred_at,
  'confirmationNotBefore',greatest(payment.created_at,claim.requested_at),
  'transferNotBefore',greatest(payment.created_at,refund.filed_at,lifecycle.confirmed_at),
  'maskedAccount',account.masked_account,'maskedHolder',account.masked_holder,
  'confirmBlocker',private.bank_transfer_refund_blocker(claim,purchase,'confirm_cancellation'),
  'fileBlocker',private.bank_transfer_refund_blocker(claim,purchase,'file_transfer'),
  'completeBlocker',private.bank_transfer_refund_blocker(claim,purchase,'complete_transfer'),
  'viewBlocker',private.bank_transfer_refund_blocker(claim,purchase,'view_account'),
  'gift',exists(select 1 from private.gift_intents where order_id=purchase.id));
end $$

create function public.admin_record_bank_transfer_refund(p_order_id uuid,p_claim_id uuid,p_operation_id uuid,p_kind text,
 p_expected_revision integer,p_expected_amount integer,p_occurred_at timestamptz,p_evidence text,p_note text,p_confirmed boolean,
 p_expected_actor_id uuid,p_expected_session_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare purchase public.orders;claim public.order_cancellation_requests;payment public.payments;refund public.refunds;
 previous private.bank_transfer_refund_operations;lifecycle private.bank_transfer_claim_refunds;blocker text;request_hash text;
 result_revision integer;receipt jsonb;happened timestamptz;
begin
 perform private.lock_bank_transfer_refund_identity(p_order_id,p_claim_id,p_expected_actor_id,p_expected_session_id);
 if p_operation_id is null or p_kind is null or p_kind not in('confirm_cancellation','file_transfer','complete_transfer')
  or p_expected_revision is null or p_expected_revision<0 or p_expected_amount is null or p_expected_amount<=0
  or p_occurred_at is null or not isfinite(p_occurred_at) or p_confirmed is distinct from true
  or p_evidence is null or p_evidence<>btrim(p_evidence) or char_length(p_evidence) not between 2 and 300 or p_evidence~'[[:cntrl:]]'
  or p_note is null or p_note<>btrim(p_note) or char_length(p_note) not between 2 and 300 or p_note~'[[:cntrl:]]'
 then raise invalid_parameter_value using message='invalid_bank_refund_operation';end if;
 perform pg_advisory_xact_lock(hashtextextended('bank-transfer-refund:'||p_operation_id::text,0));
 request_hash:=encode(extensions.digest(jsonb_build_array(p_order_id,p_claim_id,p_operation_id,p_kind,p_expected_revision,p_expected_amount,
  p_occurred_at,p_evidence,p_note,p_confirmed,p_expected_actor_id,p_expected_session_id)::text,'sha256'),'hex');
 select * into previous from private.bank_transfer_refund_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>p_expected_actor_id or previous.session_id<>p_expected_session_id or previous.order_id<>p_order_id
   or previous.claim_id<>p_claim_id or previous.kind<>p_kind or previous.expected_revision<>p_expected_revision or previous.amount<>p_expected_amount then
   raise unique_violation using message='bank_refund_request_conflict';end if;
  if previous.state='sealed' then raise check_violation using message='bank_refund_request_sealed';end if;
  if previous.request_hash<>request_hash then raise unique_violation using message='bank_refund_request_conflict';end if;
  return previous.receipt;
 end if;
 select * into purchase from public.orders where id=p_order_id for update;
 perform id from public.order_shipments where order_id=p_order_id order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id and order_id=p_order_id for update;
 if not found then raise sqlstate 'PT404' using message='claim_not_found';end if;
 if claim.claim_revision<>p_expected_revision or purchase.total<>p_expected_amount then raise sqlstate 'PT409' using message='claim_changed';end if;
 perform shipment_id from public.order_claim_collections where claim_id=claim.id order by shipment_id for update;
 perform id from public.payments where purpose='order' and ref_id=p_order_id order by id for update;
 perform r.id from public.refunds r join public.payments p on p.id=r.payment_id where p.purpose='order' and p.ref_id=p_order_id order by r.id for update of r;
 select * into lifecycle from private.bank_transfer_claim_refunds where claim_id=claim.id for update;
 perform claim_id from private.claim_refund_accounts where claim_id=claim.id for update;
 blocker:=private.bank_transfer_refund_blocker(claim,purchase,p_kind);
 if blocker is not null then raise check_violation using message=blocker;end if;
 select * into payment from public.payments where purpose='order' and ref_id=p_order_id;
 select * into refund from public.refunds where payment_id=payment.id;
 happened:=clock_timestamp();
 if p_occurred_at>happened or p_occurred_at<greatest(payment.created_at,claim.requested_at)
  or p_kind='complete_transfer' and p_occurred_at<greatest(refund.filed_at,lifecycle.confirmed_at) then
  raise invalid_parameter_value using message='bank_refund_occurred_at_invalid';end if;
 if p_kind='file_transfer' then
  perform public.admin_record_order_claim_refund(claim.id,'bank_transfer','filed',p_note);
 elsif p_kind='confirm_cancellation' then
  insert into private.bank_transfer_claim_refunds(claim_id,order_id,payment_id,payer_id,amount,state,confirmation_operation_id,
   confirmed_by,confirmed_at,confirmation_evidence,confirmation_note)
  values(claim.id,purchase.id,payment.id,purchase.user_id,payment.amount,'awaiting_transfer',p_operation_id,
   p_expected_actor_id,p_occurred_at,p_evidence,p_note);
  perform public.finalize_order_cancellation_with_provider_evidence(purchase.id,claim.reason,array[]::text[]);
 elsif p_kind='complete_transfer' then
  update private.bank_transfer_claim_refunds set state='completed',transfer_operation_id=p_operation_id,transferred_by=p_expected_actor_id,
   transferred_at=p_occurred_at,transfer_evidence=p_evidence,transfer_note=p_note,updated_at=happened where claim_id=claim.id;
  -- The accepted transfer evidence unlocks the existing idempotent finalizer.
  -- Its bank branch changes money status; its card branch is never entered.
  if claim.status<>'processing' then update public.order_cancellation_requests set stage='processing',last_error_code=null where id=claim.id;end if;
  perform public.complete_order_cancellation_request(claim.id,array[payment.payment_key],p_expected_actor_id);
  perform public.admin_record_order_claim_refund(claim.id,'bank_transfer','completed',p_note);
 end if;
 if p_kind<>'complete_transfer' then
  update public.order_cancellation_requests set stage='processing',last_error_code=null,updated_at=happened where id=claim.id;
 end if;
 select claim_revision into result_revision from public.order_cancellation_requests where id=claim.id;
 receipt:=jsonb_build_object('operationId',p_operation_id,'actorId',p_expected_actor_id,'orderId',purchase.id,'claimId',claim.id,
  'kind',p_kind,'revision',p_expected_revision,'resultRevision',result_revision,'amount',payment.amount,'state','recorded','createdAt',happened);
 insert into private.bank_transfer_refund_operations(id,actor_id,session_id,order_id,claim_id,kind,expected_revision,amount,state,request_hash,occurred_at,evidence,note,receipt,created_at)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,purchase.id,claim.id,p_kind,p_expected_revision,payment.amount,'recorded',request_hash,p_occurred_at,p_evidence,p_note,receipt,happened);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'admin.order.bank_refund_'||p_kind,'order:'||purchase.id,
  jsonb_build_object('claimId',claim.id,'kind',p_kind,'amount',payment.amount,'occurredAt',p_occurred_at,'revision',p_expected_revision,'resultRevision',result_revision));
 return receipt;
end $$

create function public.admin_read_bank_transfer_refund(p_order_id uuid,p_claim_id uuid,p_operation_id uuid,p_kind text,
 p_expected_revision integer,p_expected_amount integer,p_expected_actor_id uuid,p_expected_session_id uuid,p_seal boolean default false) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare previous private.bank_transfer_refund_operations;receipt jsonb;
begin
 perform private.lock_bank_transfer_refund_identity(p_order_id,p_claim_id,p_expected_actor_id,p_expected_session_id);
 if p_operation_id is null or p_kind is null or p_kind not in('confirm_cancellation','file_transfer','complete_transfer')
  or p_expected_revision is null or p_expected_revision<0 or p_expected_amount is null or p_expected_amount<=0 or p_seal is null then
  raise invalid_parameter_value using message='invalid_bank_refund_operation';end if;
 perform pg_advisory_xact_lock(hashtextextended('bank-transfer-refund:'||p_operation_id::text,0));
 select * into previous from private.bank_transfer_refund_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>p_expected_actor_id or previous.session_id<>p_expected_session_id or previous.order_id<>p_order_id
   or previous.claim_id<>p_claim_id or previous.kind<>p_kind or previous.expected_revision<>p_expected_revision or previous.amount<>p_expected_amount then
   raise unique_violation using message='bank_refund_request_conflict';end if;
  return previous.receipt;
 end if;
 if not p_seal then return null;end if;
 receipt:=jsonb_build_object('operationId',p_operation_id,'actorId',p_expected_actor_id,'orderId',p_order_id,'claimId',p_claim_id,
  'kind',p_kind,'revision',p_expected_revision,'resultRevision',p_expected_revision,'amount',p_expected_amount,'state','sealed','createdAt',clock_timestamp());
 insert into private.bank_transfer_refund_operations(id,actor_id,session_id,order_id,claim_id,kind,expected_revision,amount,state,receipt)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,p_order_id,p_claim_id,p_kind,p_expected_revision,p_expected_amount,'sealed',receipt);
 return receipt;
end $$

create function public.admin_view_bank_transfer_refund_account(p_order_id uuid,p_claim_id uuid,p_view_id uuid,p_expected_revision integer,
 p_expected_actor_id uuid,p_expected_session_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare purchase public.orders;claim public.order_cancellation_requests;account private.claim_refund_accounts;blocker text;happened timestamptz;
begin
 perform private.lock_bank_transfer_refund_identity(p_order_id,p_claim_id,p_expected_actor_id,p_expected_session_id);
 if p_view_id is null or p_expected_revision is null or p_expected_revision<0 then raise invalid_parameter_value using message='invalid_bank_refund_operation';end if;
 select * into purchase from public.orders where id=p_order_id for update;
 perform id from public.order_shipments where order_id=p_order_id order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id and order_id=p_order_id for update;
 if not found then raise sqlstate 'PT404' using message='claim_not_found';end if;
 if claim.claim_revision<>p_expected_revision then raise sqlstate 'PT409' using message='claim_changed';end if;
 perform id from public.payments where purpose='order' and ref_id=p_order_id order by id for update;
 perform r.id from public.refunds r join public.payments p on p.id=r.payment_id where p.purpose='order' and p.ref_id=p_order_id order by r.id for update of r;
 select * into account from private.claim_refund_accounts where claim_id=claim.id for share;
 blocker:=private.bank_transfer_refund_blocker(claim,purchase,'view_account');
 if blocker is not null then raise check_violation using message=blocker;end if;
 happened:=clock_timestamp();
 -- No account data enters the audit payload or durable response receipts. A
 -- duplicate view UUID is rejected rather than returning a cached plaintext.
 insert into private.bank_transfer_refund_account_views(id,actor_id,session_id,order_id,claim_id,created_at)
 values(p_view_id,p_expected_actor_id,p_expected_session_id,p_order_id,p_claim_id,happened);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_view_id,p_expected_actor_id,'admin.order.bank_refund_account_viewed','order:'||p_order_id,
  jsonb_build_object('claimId',p_claim_id,'purpose','prepare_bank_transfer','revision',p_expected_revision));
 perform set_config('response.headers','[{"Cache-Control":"no-store, private"},{"Pragma":"no-cache"}]',true);
 return jsonb_build_object('viewId',p_view_id,'actorId',p_expected_actor_id,'orderId',p_order_id,'claimId',p_claim_id,'revision',p_expected_revision,
  'bankName',account.bank_name,'accountNumber',account.account_number,'accountHolder',account.account_holder,'viewedAt',happened);
end $$

create function public.admin_list_bank_transfer_refunds(p_limit integer default 50,p_offset integer default 0) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=auth.uid();session_id uuid;rows jsonb;total bigint;
begin
 begin session_id:=(auth.jwt()->>'session_id')::uuid;exception when invalid_text_representation then raise insufficient_privilege using message='bank_refund_permission_required';end;
 perform private.require_bank_transfer_refund_identity(actor,session_id);
 if p_limit is null or p_limit not between 1 and 100 or p_offset is null or p_offset<0 then
  raise invalid_parameter_value using message='invalid_bank_refund_page';end if;
 select count(*) into total from private.bank_transfer_claim_refunds where state='awaiting_transfer';
 select coalesce(jsonb_agg(row_data order by confirmed_at,claim_id),'[]') into rows from(
  select lifecycle.confirmed_at,lifecycle.claim_id,jsonb_build_object('claimId',claim.id,'orderId',purchase.id,'reference',claim.reference,
   'claimType',claim.claim_type,'amount',lifecycle.amount,'confirmedAt',lifecycle.confirmed_at,'filedAt',refund.filed_at,
   'updatedAt',greatest(lifecycle.updated_at,claim.updated_at),'revision',claim.claim_revision,
   'gift',parties.claim_id is not null,'payerName',payer.nickname,'requesterName',requester.nickname) row_data
  from private.bank_transfer_claim_refunds lifecycle join public.order_cancellation_requests claim on claim.id=lifecycle.claim_id
  join public.orders purchase on purchase.id=lifecycle.order_id
  join public.refunds refund on refund.payment_id=lifecycle.payment_id
  left join private.gift_claim_parties parties on parties.claim_id=claim.id
  left join public.profiles payer on payer.id=lifecycle.payer_id
  left join public.profiles requester on requester.id=coalesce(parties.actual_requester,claim.requested_by)
  where lifecycle.state='awaiting_transfer' order by lifecycle.confirmed_at,lifecycle.claim_id limit p_limit offset p_offset
 ) queue;
 return jsonb_build_object('rows',rows,'total',total,'limit',p_limit,'offset',p_offset);
end $$

-- Awaiting transfers remain unresolved for account deletion even after the
-- order has been canceled and its stock restored. Existing blocker codes stay.
do $patch$ declare definition text;anchor text:='refund.status in (''requested'', ''failed'')';begin
 definition:=pg_get_functiondef('private.account_deletion_blockers(uuid)'::regprocedure);
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'bank_refund_account_blocker_anchor_changed';end if;
 execute replace(definition,anchor,'refund.status in (''requested'', ''failed'', ''awaiting_transfer'')');
end $patch$

do $patch$ declare definition text;anchor text:='''status'', refund.status,';begin
 definition:=pg_get_functiondef('private.snapshot_account_deletion_legal_records(uuid,uuid)'::regprocedure);
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'bank_refund_legal_snapshot_anchor_changed';end if;
 execute replace(definition,anchor,anchor||E'\n      ''bankTransferProof'', private.bank_transfer_refund_legal_proof(refund.payment_id),');
end $patch$

-- A payer may supply an absent gift account after approval, until filing or a
-- bank cancellation confirmation starts. The recipient/payer checks, locking,
-- immutable first account and gift-specific retention stay in the existing RPC.
do $patch$ declare definition text;anchor text:='claim.stage not in(''requested'',''in_review'',''collecting'',''collected'',''on_hold'',''needs_review'')';begin
 definition:=pg_get_functiondef('public.set_my_gift_claim_refund_account(uuid,uuid,uuid,text,text,text,uuid)'::regprocedure);
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'bank_gift_account_stage_anchor_changed';end if;
 definition:=replace(definition,anchor,'claim.stage not in(''requested'',''in_review'',''collecting'',''collected'',''on_hold'',''processing'',''needs_review'')');
 anchor:=' if exists(select 1 from private.claim_refund_accounts where claim_id=claim.id) then';
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'bank_gift_account_filing_anchor_changed';end if;
 execute replace(definition,anchor,$new$ if exists(select 1 from private.bank_transfer_claim_refunds where claim_id=claim.id)
  or exists(select 1 from public.refunds r join public.payments p on p.id=r.payment_id where p.purpose='order' and p.ref_id=purchase.id
   and(r.filed_at is not null or r.completed_at is not null or r.method is not null)) then raise check_violation using message='gift_refund_account_closed';end if;
$new$||anchor);
end $patch$

do $permissions$ declare signature text;begin
 foreach signature in array array[
  'private.require_bank_transfer_refund_identity(uuid,uuid)',
  'private.lock_bank_transfer_refund_identity(uuid,uuid,uuid,uuid)',
  'private.bank_transfer_refund_blocker(public.order_cancellation_requests,public.orders,text)',
  'private.bank_transfer_refund_legacy_completed(uuid)',
  'private.bank_transfer_refund_legacy_completed_claim(uuid,uuid)',
  'private.bank_transfer_refund_pending_evidence_valid(uuid,uuid)',
  'private.finalize_bank_transfer_claim_refund(uuid,text)',
  'private.guard_bank_transfer_refund_ledger()',
  'private.guard_bank_transfer_refund_lifecycle()',
  'private.bank_transfer_refund_legal_proof(uuid)',
  'public.admin_bank_transfer_refund_context(uuid,uuid,uuid,uuid)',
  'public.admin_record_bank_transfer_refund(uuid,uuid,uuid,text,integer,integer,timestamptz,text,text,boolean,uuid,uuid)',
  'public.admin_read_bank_transfer_refund(uuid,uuid,uuid,text,integer,integer,uuid,uuid,boolean)',
  'public.admin_view_bank_transfer_refund_account(uuid,uuid,uuid,integer,uuid,uuid)',
  'public.admin_list_bank_transfer_refunds(integer,integer)'
 ] loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',signature);
  if signature in('private.finalize_bank_transfer_claim_refund(uuid,text)','private.bank_transfer_refund_legal_proof(uuid)',
   'private.bank_transfer_refund_pending_evidence_valid(uuid,uuid)','private.bank_transfer_refund_legacy_completed(uuid)',
   'private.bank_transfer_refund_legacy_completed_claim(uuid,uuid)') then
   execute format('grant execute on function %s to postgres',signature);
  end if;
  if signature like 'public.%' then
   execute format('grant execute on function %s to authenticated',signature);
   perform private.register_operator_rpc_contract(signature::regprocedure,'sales.manage',
    case when signature like 'public.admin_bank_transfer_refund_context%' or signature like 'public.admin_list_bank_transfer_refunds%' then 'read' else 'write' end,true);
  else perform private.register_operator_internal_contract(signature::regprocedure);end if;
 end loop;
 -- Modified existing functions retain their owner and ACL. Refresh their exact
 -- metadata receipts; no existing capability or policy grant is changed.
 perform private.register_operator_internal_contract('public.finalize_order_cancellation_with_provider_evidence(uuid,text,text[])'::regprocedure);
 perform private.register_operator_internal_contract('private.guard_order_claim_cancellation_transition()'::regprocedure);
 perform private.register_operator_internal_contract('private.guard_unresolved_goods_payment_cancellation()'::regprocedure);
 perform private.register_operator_rpc_contract('public.admin_record_order_claim_refund(uuid,text,text,text)'::regprocedure,'sales.manage','write',false);
 perform private.register_operator_internal_contract('private.account_deletion_blockers(uuid)'::regprocedure);
 perform private.register_operator_internal_contract('private.snapshot_account_deletion_legal_records(uuid,uuid)'::regprocedure);
 perform private.register_operator_internal_contract('public.set_my_gift_claim_refund_account(uuid,uuid,uuid,text,text,text,uuid)'::regprocedure);
end $permissions$

-- Called by the converter after locking the sorted union of source/owner/new goods,
-- then variants. Targets are unpublished goods created in the same transaction.
create function private.bind_goods_aggregation(p_source_good_id text,p_new_good_ids text[],p_operation_id uuid,p_actor uuid) returns uuid
language plpgsql security definer set search_path='' as $$
declare owner_id text;family_id uuid;target_id text;begin
 if p_actor is null or auth.uid() is distinct from p_actor then raise insufficient_privilege using message='auth_context_changed';end if;
 perform private.require_actor_operator_capability(p_actor,'catalog.manage');
 if p_operation_id is null or p_source_good_id is null or p_new_good_ids is null or cardinality(p_new_good_ids) not between 1 and 99
  or array_position(p_new_good_ids,null) is not null or p_source_good_id=any(p_new_good_ids)
  or (select count(distinct id) from unnest(p_new_good_ids) id)<>cardinality(p_new_good_ids) then
  raise invalid_parameter_value using message='invalid_goods_aggregation_binding';end if;
 owner_id:=private.goods_aggregation_owner(p_source_good_id);
 perform 1 from public.goods where id in (owner_id,p_source_good_id) order by id for update;
 if not exists(select 1 from public.goods where id=p_source_good_id and archived_at is null) then raise no_data_found using message='good_not_found';end if;
 if exists(select 1 from unnest(p_new_good_ids) target(id) left join public.goods g on g.id=target.id
  where g.id is null or g.published_at is not null or g.archived_at is not null or g.xmin<>pg_current_xact_id()::text::xid
   or exists(select 1 from private.goods_aggregation_members where good_id=target.id)
   or exists(select 1 from private.goods_transaction_configs where good_id=target.id)
   or exists(select 1 from public.order_items where good_id=target.id)) then
  raise check_violation using message='goods_aggregation_target_not_new';end if;
 if coalesce((select count(*) from private.goods_aggregation_members where root_good_id=owner_id),1)+cardinality(p_new_good_ids)>100 then
  raise check_violation using message='goods_aggregation_member_limit';end if;
 insert into private.goods_aggregation_roots(root_good_id,created_by,operation_id) values(owner_id,p_actor,p_operation_id) on conflict do nothing;
 insert into private.goods_aggregation_members(good_id,root_good_id,created_by,operation_id) values(owner_id,owner_id,p_actor,p_operation_id) on conflict do nothing;
 insert into private.goods_aggregation_members(good_id,root_good_id,created_by,operation_id)
  select id,owner_id,p_actor,p_operation_id from unnest(p_new_good_ids) id order by id;
 select aggregation_id into family_id from private.goods_aggregation_roots where root_good_id=owner_id;
 return family_id;
end $$

create function public.admin_get_goods_aggregation(p_good_id text) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin
 if not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 select jsonb_build_object('goodId',g.id,'ownerGoodId',coalesce(m.root_good_id,g.id),'aggregationId',r.aggregation_id,
  'sharedPolicy',private.goods_aggregation_shared_policy(g.id),'shared',m.good_id is not null,'editable',coalesce(m.root_good_id,g.id)=g.id)
 into result from public.goods g left join private.goods_aggregation_members m on m.good_id=g.id
 left join private.goods_aggregation_roots r on r.root_good_id=m.root_good_id where g.id=p_good_id;
 return result;
end $$

create function private.guard_goods_aggregation_policy() returns trigger
language plpgsql security definer set search_path='' as $$
declare owner_id text;owner_row public.goods;field text;begin
 owner_id:=private.goods_aggregation_owner(new.id);
 if owner_id=new.id then return new;end if;
 select * into owner_row from public.goods where id=owner_id;
 foreach field in array array['origin_id','shipping_fee_type','individual_fee','order_quantity_limit_enabled','min_order_qty','max_order_qty',
  'member_purchase_limit_enabled','member_lifetime_qty_limit'] loop
  -- An unrelated stale editor save is harmless. A deliberate separate policy is not.
  if to_jsonb(new)->field is distinct from to_jsonb(old)->field and to_jsonb(new)->field is distinct from to_jsonb(owner_row)->field then
   raise check_violation using message='goods_aggregation_policy_owned_by_source';end if;
 end loop;
 return new;
end $$

create function private.guard_goods_aggregation_config() returns trigger
language plpgsql security definer set search_path='' as $$begin
 if private.goods_aggregation_owner(new.good_id)<>new.good_id then raise check_violation using message='goods_aggregation_policy_owned_by_source';end if;
 return new;
end $$

CREATE OR REPLACE FUNCTION private.lock_goods_transaction_catalog(p_actor uuid, p_selection jsonb, p_user_coupon_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 -- All mutable catalog parents precede all variants and supply policies.
 perform 1 from public.goods g where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection)) order by g.id for update;
 perform 1 from public.goods_variants v where v.id in(select (value->>'variantId')::uuid from jsonb_array_elements(p_selection)) order by v.good_id,v.id for update;
 perform 1 from public.ips ip where ip.id in(select g.ip_id from public.goods g where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by ip.id for share;
 perform 1 from private.goods_preorder_policies p where p.id in(select v.preorder_policy_id from public.goods_variants v
  where v.id in(select (value->>'variantId')::uuid from jsonb_array_elements(p_selection))) order by p.id for update;
 perform 1 from public.fulfillment_origins o where o.id in(select g.origin_id from public.goods g
  where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by o.id for share;
 perform 1 from public.shipping_carriers c where c.code in(select o.default_carrier from public.fulfillment_origins o join public.goods g on g.origin_id=o.id
  where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by c.code for share;
 if p_user_coupon_id is not null then
  perform 1 from public.user_coupons h where h.id=p_user_coupon_id for update;
  perform 1 from public.coupons c join public.user_coupons h on h.coupon_code=c.code where h.id=p_user_coupon_id for share of c;
 end if;
 perform 1 from private.store_credit_policy where singleton for share;
 perform private.lock_store_credit_account(p_actor);
 perform 1 from private.store_credit_lots where user_id=p_actor order by expires_at,id for update;
end $function$

CREATE OR REPLACE FUNCTION private.calculate_goods_transaction_locked(p_actor uuid, p_selection jsonb, p_address jsonb, p_delivery_choices jsonb, p_user_coupon_id uuid, p_store_credit_amount bigint, p_at timestamp with time zone, p_line_ids jsonb, p_order_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare entry jsonb;index integer:=0;good public.goods;owner_row public.goods;variant public.goods_variants;price record;supply record;good_qty numeric;variant_qty numeric;
 custom_inputs jsonb;quantity_error text;priced_lines jsonb:='[]';shipping_lines jsonb:='[]';internal_lines jsonb:='[]';display_lines jsonb:='[]';policies jsonb;volume jsonb;
 discounted jsonb;line jsonb;shipping jsonb;coupon_eval record;coupon_data jsonb;coupon_lines jsonb;coupon_weights jsonb;credit_weights jsonb;
 coupon_allocations jsonb;credit_allocations jsonb;policy private.store_credit_policy;balance jsonb;available numeric;maximum numeric:=0;
 subtotal numeric;volume_total numeric;net numeric;coupon numeric:=0;credit numeric:=p_store_credit_amount;online numeric;customer numeric;
 next_change timestamptz;boundary timestamptz;card_allowed boolean:=true;bank_allowed boolean:=true;selected_policy jsonb;line_coupon numeric;line_credit numeric;
begin
 if p_at is null or not isfinite(p_at) or p_store_credit_amount is null or p_store_credit_amount not between 0 and 999999999999
  or jsonb_typeof(p_line_ids) is distinct from 'array' or jsonb_array_length(p_line_ids)<>jsonb_array_length(p_selection)
  or exists(select 1 from jsonb_array_elements(p_line_ids) id where jsonb_typeof(id) is distinct from 'string'
   or id#>>'{}'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  or (select count(distinct id) from jsonb_array_elements(p_line_ids) id)<>jsonb_array_length(p_line_ids) then
  raise invalid_parameter_value using message='invalid_transaction_calculation';end if;
 begin perform private.assert_goods_purchase_allowed(p_actor);
 exception when check_violation then
  if sqlerrm<>'goods_purchase_restricted' then raise;end if;
  return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','purchase_restricted','goodId',null)));
 end;
 select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'goodId',v.good_id,'revision',v.revision,'status',v.status,'terms',v.terms,'draftValues',v.draft_values)),'[]')
  into policies from private.goods_transaction_configs c join private.goods_volume_discount_versions v on v.id=c.volume_version_id
  where c.good_id in(select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection));
 for entry in select value from jsonb_array_elements(p_selection) loop
  select g.* into good from public.goods g join public.ips ip on ip.id=g.ip_id
   join public.goods owner_good on owner_good.id=private.goods_aggregation_owner(g.id)
   join public.fulfillment_origins origin on origin.id=owner_good.origin_id and origin.is_active
   where g.id=entry->>'goodId' and g.archived_at is null and g.published_at is not null and g.sale_restriction='none'
    and (g.sale_starts_at is null or g.sale_starts_at<=p_at) and (g.sale_ends_at is null or g.sale_ends_at>p_at)
    and ip.archived_at is null and ip.published_at is not null;
  if not found then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','goods_unavailable','goodId',entry->>'goodId')));end if;
  select * into owner_row from public.goods where id=private.goods_aggregation_owner(good.id);
  good.origin_id:=owner_row.origin_id;good.shipping_fee_type:=owner_row.shipping_fee_type;good.individual_fee:=owner_row.individual_fee;
  good.order_quantity_limit_enabled:=owner_row.order_quantity_limit_enabled;good.min_order_qty:=owner_row.min_order_qty;good.max_order_qty:=owner_row.max_order_qty;
  good.member_purchase_limit_enabled:=owner_row.member_purchase_limit_enabled;good.member_lifetime_qty_limit:=owner_row.member_lifetime_qty_limit;
  select * into variant from public.goods_variants where id=(entry->>'variantId')::uuid and good_id=good.id and archived_at is null;
  if not found then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','goods_unavailable','goodId',good.id)));end if;
  select sum((value->>'qty')::numeric) into good_qty from jsonb_array_elements(p_selection) where private.goods_aggregation_owner(value->>'goodId')=owner_row.id;
  quantity_error:=private.check_goods_purchase_quantity(good,p_actor,good_qty::bigint,true);
  if quantity_error is not null then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','purchase_limit','goodId',good.id)));end if;
  begin custom_inputs:=private.resolve_goods_custom_inputs(good.id,(entry->>'inputRevision')::integer,entry->'inputValues');
  exception when check_violation or invalid_parameter_value then
   return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','invalid_selection','goodId',good.id)));
  end;
  select * into supply from private.resolve_goods_variant_supply(variant.id,p_at);
  select sum((value->>'qty')::numeric) into variant_qty from jsonb_array_elements(p_selection) where value->>'variantId'=variant.id::text;
  if good.stock='soldout' or supply.available_qty<variant_qty or (supply.mode='preorder' and supply.state<>'open') then
   return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','goods_unavailable','goodId',good.id)));end if;
  select * into price from private.resolve_goods_variant_price(variant.id,p_at);
  priced_lines:=priced_lines||jsonb_build_array(jsonb_build_object('lineId',p_line_ids->>index,'goodId',owner_row.id,'regularUnitPrice',price.regular_price,
   'unitPrice',price.effective_price,'qty',entry->'qty'));
  shipping_lines:=shipping_lines||jsonb_build_array(jsonb_build_object('origin_id',good.origin_id,'good_id',good.id,'qty',entry->'qty',
   'unit_price',price.effective_price,'fee_type',good.shipping_fee_type,'individual_fee',good.individual_fee));
  select value into selected_policy from jsonb_array_elements(policies) where value->>'goodId'=owner_row.id;
  internal_lines:=internal_lines||jsonb_build_array(entry||jsonb_build_object('lineId',p_line_ids->>index,
   'goodName',good.name,'goodType',good.type,'goodIpId',good.ip_id,'originId',good.origin_id,'variantName',variant.name,
   'customInputsSnapshot',custom_inputs,'regularUnitPrice',price.regular_price,'unitPrice',price.effective_price,'pricePeriodId',price.price_period_id,
   'priceStartsAt',price.starts_at,'priceEndsAt',price.ends_at,'volumePolicySnapshot',selected_policy,
   'supplySource',supply.mode,'preorderPolicyId',supply.policy_id,'preorderPolicyRevision',supply.policy_revision,
   'preorderStartsAt',supply.starts_at,'preorderEndsAt',supply.ends_at,'preorderExpectedShipDate',supply.expected_ship_date,
   'salesPolicySnapshot',jsonb_build_object('version',2,'allowCardPayment',good.allow_card_payment,'allowBankTransfer',good.allow_bank_transfer,
    'orderQuantityLimitEnabled',good.order_quantity_limit_enabled,'minOrderQty',good.min_order_qty,'maxOrderQty',good.max_order_qty,
    'memberPurchaseLimitEnabled',good.member_purchase_limit_enabled,'memberLifetimeQtyLimit',good.member_lifetime_qty_limit,
    'saleStartsAt',good.sale_starts_at,'saleEndsAt',good.sale_ends_at,'salePeriodRevision',good.sale_period_revision)));
  select min(moment) into boundary from (
   select schedule.starts_at moment from private.goods_variant_price_periods schedule where schedule.variant_id=variant.id and schedule.state='active' and schedule.starts_at>p_at
   union all select schedule.ends_at from private.goods_variant_price_periods schedule where schedule.variant_id=variant.id and schedule.state='active' and schedule.ends_at>p_at
   union all select good.sale_starts_at where good.sale_starts_at>p_at union all select good.sale_ends_at where good.sale_ends_at>p_at
   union all select supply.next_change_at where supply.next_change_at>p_at) moments;
  next_change:=least(next_change,boundary);card_allowed:=card_allowed and good.allow_card_payment;bank_allowed:=bank_allowed and good.allow_bank_transfer;
  index:=index+1;
 end loop;
 if not card_allowed and not bank_allowed then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','payment_method_unavailable','goodId',null)));end if;
 volume:=private.calculate_goods_volume_discounts(priced_lines,policies,p_at);
 -- Restore actual selected IDs before coupon targeting, display and immutable order snapshots.
 select jsonb_agg(v.value||jsonb_build_object('goodId',i.value->>'goodId') order by v.ordinality) into discounted
  from jsonb_array_elements(volume->'lines') with ordinality v(value,ordinality)
  join jsonb_array_elements(internal_lines) i(value) on i.value->>'lineId'=v.value->>'lineId';
 volume:=jsonb_set(volume,'{lines}',discounted);
 subtotal:=(volume->>'subtotal')::numeric;volume_total:=(volume->>'volumeDiscountTotal')::numeric;net:=subtotal-volume_total;
 next_change:=least(next_change,(volume->>'nextChangeAt')::timestamptz);
 shipping:=private.calculate_goods_transaction_shipping(shipping_lines,jsonb_build_object('postalCode',p_address->>'postalCode','address1',p_address->>'address1'),p_delivery_choices,p_at);
 if shipping->>'state'='blocked' then return shipping;end if;
 next_change:=least(next_change,(shipping->>'nextChangeAt')::timestamptz);
 select jsonb_agg(jsonb_build_object('good_id',value->>'goodId','subtotal',(value->>'netSubtotal')::bigint)) into coupon_lines from jsonb_array_elements(volume->'lines');
 if p_user_coupon_id is not null then
  select * into coupon_eval from private.evaluate_coupon_target_lines_at(p_user_coupon_id,p_actor,coupon_lines,p_order_id,p_at);
  if coupon_eval.o_reason is not null then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','coupon_unavailable','goodId',null)));end if;
  coupon:=least(coupon_eval.o_discount,greatest(0,net+(shipping->>'prepaidFee')::numeric-1000));
  if coupon<=0 then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','coupon_unavailable','goodId',null)));end if;
  coupon_data:=jsonb_build_object('userCouponId',p_user_coupon_id,'couponCode',coupon_eval.o_coupon_code,'eligibleSubtotal',coupon_eval.o_eligible_subtotal,
   'discount',coupon,'termsSnapshot',coupon_eval.o_terms_snapshot||jsonb_build_object('calculationVersion',2,'eligibleNetSubtotal',coupon_eval.o_eligible_subtotal));
  select min(moment) into boundary from public.user_coupons held join public.coupons definition on definition.code=held.coupon_code
   cross join lateral(values(held.usable_from),(held.expires_at),(definition.starts_at),(definition.ends_at)) moments(moment)
   where held.id=p_user_coupon_id and moment>p_at;
  next_change:=least(next_change,boundary);
 end if;
 select jsonb_agg(jsonb_build_object('id',value->>'lineId','weight',case when p_user_coupon_id is null then 0
   when coupon_data#>>'{termsSnapshot,goodsScope}'='all' or ((coupon_data#>'{termsSnapshot,targetGoodIds}') ? (value->>'goodId')
    or (coupon_data#>'{termsSnapshot,targetGoodIds}') ? private.goods_aggregation_owner(value->>'goodId'))
   then (value->>'netSubtotal')::numeric else 0 end)) into coupon_weights from jsonb_array_elements(volume->'lines');
 coupon_allocations:=private.allocate_transaction_amount(coupon,coupon_weights);
 select * into policy from private.store_credit_policy where singleton;
 perform private.expire_store_credit_lots(p_actor,p_at);balance:=private.store_credit_balance(p_actor);available:=(balance->>'available')::numeric;
 if policy.enabled and (balance->>'debt')::numeric=0 then
  maximum:=least(policy.max_use,available,greatest(0,net-coupon),greatest(0,net+(shipping->>'prepaidFee')::numeric-coupon-1000));end if;
 if credit>0 and (credit<policy.min_use or credit>maximum) then
  return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','store_credit_unavailable','goodId',null)));end if;
 if credit>0 then
  select min(expires_at) into boundary from private.store_credit_lots where user_id=p_actor and available_amount>0 and expires_at>p_at and revoked_at is null;
  next_change:=least(next_change,boundary);
 end if;
 online:=net+(shipping->>'prepaidFee')::numeric-coupon-credit;customer:=online+(shipping->>'collectFee')::numeric;
 if online<1000 then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','below_minimum_payment','goodId',null)));end if;
 if customer>9007199254740991 or online>999999999999 then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','amount_overflow','goodId',null)));end if;
 select jsonb_agg(jsonb_build_object('id',value->>'lineId','weight',(value->>'netSubtotal')::numeric-(coupon_allocations->>(value->>'lineId'))::numeric))
  into credit_weights from jsonb_array_elements(volume->'lines');
 credit_allocations:=private.allocate_transaction_amount(credit,credit_weights);
 index:=0;
 for discounted in select value from jsonb_array_elements(volume->'lines') loop
  line:=internal_lines->index;line_coupon:=(coupon_allocations->>(line->>'lineId'))::numeric;line_credit:=(credit_allocations->>(line->>'lineId'))::numeric;
  line:=line||jsonb_build_object('subtotal',(discounted->>'unitPrice')::numeric*(discounted->>'qty')::numeric,
   'volumeUnitDiscount',discounted->'volumeUnitDiscount','volumeDiscountTotal',discounted->'volumeDiscountTotal','netSubtotal',discounted->'netSubtotal',
   'couponDiscount',line_coupon,'storeCreditDiscount',line_credit,'paidGoodsTotal',(discounted->>'netSubtotal')::numeric-line_coupon-line_credit,
   'volumePolicyId',discounted->'policyId');
  internal_lines:=jsonb_set(internal_lines,array[index::text],line);
  display_lines:=display_lines||jsonb_build_array(jsonb_build_object('lineId',line->'lineId','goodId',line->'goodId','variantId',line->'variantId','qty',line->'qty',
   'regularUnitPrice',line->'regularUnitPrice','unitPrice',line->'unitPrice','volumeUnitDiscount',line->'volumeUnitDiscount','subtotal',line->'subtotal',
   'volumeDiscountTotal',line->'volumeDiscountTotal','netSubtotal',line->'netSubtotal','couponDiscount',line->'couponDiscount',
   'storeCreditDiscount',line->'storeCreditDiscount','paidGoodsTotal',line->'paidGoodsTotal','volumePolicyId',line->'volumePolicyId'));
  index:=index+1;
 end loop;
 return jsonb_build_object('state','calculated','display',jsonb_build_object('calculationVersion',2,'currency','KRW','calculatedAt',p_at,'nextChangeAt',next_change,
  'lines',display_lines,'shipping',shipping->'displayGroups','totals',jsonb_build_object('subtotal',subtotal,'volumeDiscountTotal',volume_total,'netGoodsTotal',net,
   'couponDiscountTotal',coupon,'storeCreditTotal',credit,'prepaidShippingTotal',shipping->'prepaidFee','collectShippingTotal',shipping->'collectFee','onlineTotal',online,'customerTotal',customer),
  'userCouponId',p_user_coupon_id,'storeCreditMaximum',maximum,'paymentMethods',jsonb_build_object('card',card_allowed,'bankTransfer',bank_allowed)),
  'lines',internal_lines,'shippingRaw',shipping->'rawGroups','coupon',coupon_data,'creditPolicy',case when policy.enabled then private.store_credit_policy_json()-'evidence' else null end);
exception when numeric_value_out_of_range then
 return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','amount_overflow','goodId',null)));
end $function$

CREATE OR REPLACE FUNCTION private.evaluate_coupon_target_lines_at(p_user_coupon_id uuid, p_user_id uuid, p_lines jsonb, p_order_id uuid, p_at timestamp with time zone, OUT o_reason text, OUT o_discount bigint, OUT o_coupon_code text, OUT o_eligible_subtotal bigint, OUT o_terms_snapshot jsonb)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare held public.user_coupons; coupon public.coupons;
begin
 if p_at is null or not isfinite(p_at) then raise invalid_parameter_value using message='invalid_coupon_evaluation_time';end if;
 o_reason:=null; o_discount:=0; o_coupon_code:=null; o_eligible_subtotal:=0; o_terms_snapshot:=null;
 select * into held from public.user_coupons where id=p_user_coupon_id;
 if not found or held.user_id is distinct from p_user_id then o_reason:='coupon_not_owned'; return; end if;
 o_coupon_code:=held.coupon_code;
 if held.status='used' then o_reason:='coupon_already_used'; return; end if;
 select * into coupon from public.coupons where code=held.coupon_code;
 if not found or coupon.status<>'active' then o_reason:='coupon_not_found'; return; end if;
 if p_at<(case when coupon.issue_starts_at is null then coupon.starts_at else held.usable_from end) then o_reason:='coupon_not_started'; return; end if;
 if (coupon.issue_starts_at is null and coupon.ends_at is not null and p_at>coupon.ends_at) or (held.expires_at is not null and p_at>held.expires_at)
   then o_reason:='coupon_expired'; return; end if;
 o_reason:=private.coupon_recipient_reason(coupon.recipient_segment,p_user_id);
 if o_reason is not null then return; end if;
 if coupon.recipient_segment='first_purchase' then
   if exists(select 1 from private.coupon_first_purchase_claims where user_id=p_user_id and state='reserved' and order_id is distinct from p_order_id)
     then o_reason:='coupon_first_purchase_reserved'; return; end if;
   if exists(select 1 from public.orders where user_id=p_user_id and status='pending' and id is distinct from p_order_id)
     then o_reason:='coupon_first_purchase_pending'; return; end if;
 end if;
 select coalesce(sum(line.subtotal),0) into o_eligible_subtotal
   from jsonb_to_recordset(p_lines) line(good_id text,subtotal bigint)
   where coupon.goods_scope='all' or line.good_id=any(coupon.target_good_ids) or private.goods_aggregation_owner(line.good_id)=any(coupon.target_good_ids);
 o_terms_snapshot:=jsonb_build_object('revision',coupon.terms_revision,'recipientSegment',coupon.recipient_segment,'goodsScope',coupon.goods_scope,
   'targetGoodIds',coupon.target_good_ids,'eligibleSubtotal',o_eligible_subtotal,'discountType',coupon.discount_type,'discountValue',coupon.discount_value,
   'maxDiscountAmount',coupon.max_discount_amount,'minSubtotal',coupon.min_subtotal,'startsAt',coupon.starts_at,'endsAt',coupon.ends_at,'expiresAt',held.expires_at,'usableFrom',held.usable_from,'issueStartsAt',coupon.issue_starts_at,'issueEndsAt',coupon.issue_ends_at,'validDays',coupon.valid_days);
 if o_eligible_subtotal=0 then o_reason:='coupon_no_eligible_goods'; return; end if;
 if o_eligible_subtotal<coupon.min_subtotal then o_reason:='coupon_min_subtotal'; return; end if;
 o_discount:=case when coupon.discount_type='fixed' then least(coupon.discount_value::bigint,o_eligible_subtotal)
   else least((o_eligible_subtotal*coupon.discount_value::bigint)/100,coalesce(coupon.max_discount_amount::bigint,o_eligible_subtotal),o_eligible_subtotal) end;
end $function$

CREATE OR REPLACE FUNCTION private.calculate_goods_transaction_shipping_families_base(p_lines jsonb, p_destination jsonb, p_choices jsonb, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare grouped jsonb:='[]';row record;delivery private.goods_delivery_versions;shipping_lines jsonb:='[]';base_quote jsonb;regional_quote jsonb;
 raw_group jsonb;group_goods jsonb;policy_rows jsonb;regional_rows jsonb;policy_allocations jsonb;base_allocations jsonb;regional_allocations jsonb;
 region private.shipping_region_policies;component jsonb;components jsonb;raw_groups jsonb:='[]';display_groups jsonb:='[]';good_line jsonb;
 quantity numeric;fee numeric;subtotal numeric;policy_sum numeric;regional_sum numeric;prepaid numeric;collect numeric;prepaid_total numeric:=0;collect_total numeric:=0;
 payment_mode text;contract private.shipping_collect_contract_versions;collector jsonb;contract_id uuid;regional_eligible boolean;basis text;basis_sum numeric;
begin
 for row in select good_id,origin_id,sum(qty::numeric) qty,sum(unit_price::numeric*qty) subtotal,max(fee_type) fee_type,max(individual_fee) individual_fee
  from jsonb_to_recordset(p_lines) l(good_id text,origin_id uuid,qty integer,unit_price bigint,fee_type text,individual_fee bigint)
  group by good_id,origin_id order by good_id loop
  select d.* into delivery from private.goods_transaction_configs c join private.goods_delivery_versions d on d.id=c.delivery_version_id
   where c.good_id=row.good_id and d.status='active';
  payment_mode:=case when delivery.id is null then 'prepaid' when delivery.payment_mode='buyer_choice' then coalesce(p_choices->>row.good_id,'prepaid') else delivery.payment_mode end;
  if p_choices ? row.good_id and delivery.id is not null and delivery.payment_mode<>'buyer_choice' and p_choices->>row.good_id<>delivery.payment_mode then
   return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','delivery_choice_required','goodId',row.good_id)));end if;
  if p_choices ? row.good_id and delivery.id is null and p_choices->>row.good_id<>'prepaid' then
   return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','delivery_choice_required','goodId',row.good_id)));end if;
  fee:=case when delivery.quantity_terms is not null then private.goods_quantity_delivery_fee(row.qty,delivery.quantity_terms)
   when row.fee_type='individual' then row.individual_fee else 0 end;
  grouped:=grouped||jsonb_build_array(jsonb_build_object('goodId',row.good_id,'originId',row.origin_id,'qty',row.qty,'subtotal',row.subtotal,
   'feeType',case when delivery.quantity_terms is not null then 'individual' else row.fee_type end,'individualFee',fee,'paymentMode',payment_mode,
   'deliveryPolicyId',delivery.id,'deliveryPolicyRevision',delivery.revision,'quantityTerms',delivery.quantity_terms));
  shipping_lines:=shipping_lines||jsonb_build_array(jsonb_build_object('origin_id',row.origin_id,'good_id',row.good_id,'qty',1,'unit_price',row.subtotal,
   'fee_type',case when delivery.quantity_terms is not null then 'individual' else row.fee_type end,'individual_fee',fee));
 end loop;
 base_quote:=private.calculate_goods_shipping(shipping_lines);
 regional_quote:=private.apply_shipping_region_quote(base_quote,shipping_lines,p_destination,p_at);
 if not (regional_quote->>'checkoutAllowed')::boolean then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','shipping_unresolved','goodId',null)));end if;
 for raw_group in select value from jsonb_array_elements(regional_quote->'groups') loop
  select jsonb_agg(value order by value->>'goodId') into group_goods from jsonb_array_elements(grouped) where value->>'originId'=raw_group->>'originId';
  select coalesce(sum((value->>'subtotal')::numeric),0) into policy_sum from jsonb_array_elements(group_goods) where value->>'feeType'='policy';
  select coalesce(jsonb_agg(jsonb_build_object('id',value->>'goodId','weight',case when policy_sum>0 then (value->>'subtotal')::numeric else (value->>'qty')::numeric end)),'[]')
   into policy_rows from jsonb_array_elements(group_goods) where value->>'feeType'='policy';
  policy_allocations:=case when jsonb_array_length(policy_rows)>0 then private.allocate_transaction_amount((raw_group->>'policyFee')::numeric,policy_rows) else '{}'::jsonb end;
  select jsonb_object_agg(value->>'goodId',case when value->>'feeType'='policy' then (policy_allocations->>(value->>'goodId'))::numeric else (value->>'individualFee')::numeric end)
   into base_allocations from jsonb_array_elements(group_goods);
  region:=null;if raw_group->>'policyId' is not null then select * into region from private.shipping_region_policies where id=(raw_group->>'policyId')::uuid;end if;
  regional_rows:='[]';
  for good_line in select value from jsonb_array_elements(group_goods) loop
   regional_eligible:=region.id is not null and raw_group->>'regionStatus'='surcharge' and case good_line->>'feeType'
    when 'policy' then (region.configuration->>'chargePolicyGoods')::boolean and not((region.configuration->>'waivePolicyThreshold')::boolean
     and raw_group->>'freeThreshold' is not null and (raw_group->>'policySubtotal')::numeric>=(raw_group->>'freeThreshold')::numeric)
    when 'free' then (region.configuration->>'chargeFreeGoods')::boolean else (region.configuration->>'chargeIndividualGoods')::boolean end;
   if regional_eligible then regional_rows:=regional_rows||jsonb_build_array(good_line);end if;
  end loop;
  regional_allocations:='{}';
  if jsonb_array_length(regional_rows)>0 then
   if raw_group->>'feeUnit'='per_good' then
    select jsonb_object_agg(value->>'goodId',(raw_group->>'regionalContractFee')::numeric) into regional_allocations from jsonb_array_elements(regional_rows);
   else
    select sum((base_allocations->>(value->>'goodId'))::numeric),sum((value->>'subtotal')::numeric) into basis_sum,subtotal from jsonb_array_elements(regional_rows);
    basis:=case when basis_sum>0 then 'base' when subtotal>0 then 'subtotal' else 'qty' end;
    select jsonb_agg(jsonb_build_object('id',value->>'goodId','weight',case when basis='base' then (base_allocations->>(value->>'goodId'))::numeric else (value->>basis)::numeric end))
     into regional_rows from jsonb_array_elements(regional_rows);
    regional_allocations:=private.allocate_transaction_amount((raw_group->>'regionalFee')::numeric,regional_rows);
   end if;
  end if;
  components:='[]';prepaid:=0;collect:=0;contract:=null;collector:=null;contract_id:=null;regional_sum:=0;
  for good_line in select value from jsonb_array_elements(group_goods) loop
   fee:=(base_allocations->>(good_line->>'goodId'))::numeric+coalesce((regional_allocations->>(good_line->>'goodId'))::numeric,0);
   regional_sum:=regional_sum+coalesce((regional_allocations->>(good_line->>'goodId'))::numeric,0);
   component:=jsonb_build_object('goodId',good_line->>'goodId','paymentMode',good_line->>'paymentMode',
    'baseFee',(base_allocations->>(good_line->>'goodId'))::numeric,'regionalFee',coalesce((regional_allocations->>(good_line->>'goodId'))::numeric,0),
    'totalFee',fee,'deliveryPolicyId',good_line->'deliveryPolicyId');
   components:=components||jsonb_build_array(component);
   if good_line->>'paymentMode'='collect' then collect:=collect+fee;else prepaid:=prepaid+fee;end if;
  end loop;
  if regional_sum<>(raw_group->>'regionalFee')::numeric or prepaid+collect<>(raw_group->>'finalFee')::numeric then
   raise check_violation using message='transaction_shipping_allocation_mismatch';end if;
  -- Contract readiness is required even for a zero-fee collect choice: later
  -- regional/base changes must not turn a dormant unsupported mode payable.
  if exists(select 1 from jsonb_array_elements(group_goods) where value->>'paymentMode'='collect') then
   select v.* into contract from private.shipping_collect_contracts c join private.shipping_collect_contract_versions v on v.id=c.version_id
    where c.origin_id=(raw_group->>'originId')::uuid and v.status='active';
   if not found then return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','collect_not_ready','goodId',null)));end if;
   contract_id:=contract.id;collector:=jsonb_build_object('name',contract.contract_values->>'collectorName','method',contract.contract_values->>'collectionMethod',
    'refundContact',contract.contract_values->>'refundContact','instructions',contract.contract_values->>'customerInstructions');
  end if;
  prepaid_total:=prepaid_total+prepaid;collect_total:=collect_total+collect;
  if prepaid_total+collect_total>9007199254740991 then raise numeric_value_out_of_range using message='transaction_amount_overflow';end if;
  raw_groups:=raw_groups||jsonb_build_array(raw_group||jsonb_build_object('calculationVersion',2,'totalFee',prepaid,'prepaidFee',prepaid,'collectFee',collect,
   'fullFee',prepaid+collect,'components',components,'collector',collector,'collectContractId',contract_id,'collectContractSnapshot',to_jsonb(contract),
   'deliveryTerms',group_goods));
  display_groups:=display_groups||jsonb_build_array(jsonb_build_object('originId',raw_group->'originId','prepaidFee',prepaid,'collectFee',collect,
   'fullFee',prepaid+collect,'components',components,'collector',collector));
 end loop;
 return jsonb_build_object('state','calculated','prepaidFee',prepaid_total,'collectFee',collect_total,'rawGroups',raw_groups,'displayGroups',display_groups,
  'nextChangeAt',regional_quote->'nextChangeAt');
end $function$

create or replace function private.calculate_goods_transaction_shipping(p_lines jsonb,p_destination jsonb,p_choices jsonb,p_at timestamptz) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare lines jsonb;choices jsonb:='{}';calculation jsonb;selected record;root_id text;selected_mode text;delivery_mode text;
 raw_group jsonb;component jsonb;terms jsonb;weights jsonb;base_alloc jsonb;regional_alloc jsonb;member jsonb;
 components jsonb;delivery_terms jsonb;raw_groups jsonb:='[]';display_groups jsonb:='[]';expanded jsonb;family_subtotal numeric;begin
 if not exists(select 1 from jsonb_to_recordset(p_lines) l(good_id text) join private.goods_aggregation_members m on m.good_id=l.good_id) then
  return private.calculate_goods_transaction_shipping_families_base(p_lines,p_destination,p_choices,p_at);end if;
 select jsonb_agg(l.value||jsonb_build_object('good_id',owner.id,'origin_id',owner.origin_id,'fee_type',owner.shipping_fee_type,'individual_fee',owner.individual_fee) order by l.ordinality)
 into lines from jsonb_array_elements(p_lines) with ordinality l(value,ordinality)
 join public.goods owner on owner.id=private.goods_aggregation_owner(l.value->>'good_id');
 -- Choices are keyed by actual selected IDs. A shared charge cannot be both collect and prepaid.
 for selected in select distinct good_id from jsonb_to_recordset(p_lines) l(good_id text) order by good_id loop
  root_id:=private.goods_aggregation_owner(selected.good_id);
  select d.payment_mode into delivery_mode from private.goods_transaction_configs c join private.goods_delivery_versions d on d.id=c.delivery_version_id
   where c.good_id=root_id and d.status='active';
  selected_mode:=coalesce(p_choices->>selected.good_id,case when delivery_mode='collect' then 'collect' else 'prepaid' end);
  if choices ? root_id and choices->>root_id<>selected_mode then
   return jsonb_build_object('state','blocked','issues',jsonb_build_array(jsonb_build_object('code','delivery_choice_required','goodId',selected.good_id)));end if;
  choices:=choices||jsonb_build_object(root_id,selected_mode);
 end loop;
 calculation:=private.calculate_goods_transaction_shipping_families_base(lines,p_destination,choices,p_at);
 if calculation->>'state'='blocked' then
  -- Do not disclose an unselected/unpublished owner's catalog identity in errors.
  select jsonb_agg(value||jsonb_build_object('goodId',case when value->>'goodId' is null then null else
   (select min(l.good_id) from jsonb_to_recordset(p_lines) l(good_id text) where private.goods_aggregation_owner(l.good_id)=value->>'goodId') end))
  into components from jsonb_array_elements(calculation->'issues');
  return jsonb_set(calculation,'{issues}',components);
 end if;
 for raw_group in select value from jsonb_array_elements(calculation->'rawGroups') loop
  components:='[]';delivery_terms:='[]';
  for component in select value from jsonb_array_elements(raw_group->'components') loop
   select value into terms from jsonb_array_elements(raw_group->'deliveryTerms') where value->>'goodId'=component->>'goodId';
   select sum(qty::numeric*unit_price) into family_subtotal from jsonb_to_recordset(p_lines) l(good_id text,qty integer,unit_price bigint)
    where private.goods_aggregation_owner(good_id)=component->>'goodId';
   select jsonb_agg(jsonb_build_object('id',good_id,'weight',weight) order by good_id) into weights from
    (select good_id,sum(case when family_subtotal>0 then qty::numeric*unit_price else qty::numeric end) weight
     from jsonb_to_recordset(p_lines) l(good_id text,qty integer,unit_price bigint)
     where private.goods_aggregation_owner(good_id)=component->>'goodId' group by good_id) grouped;
   base_alloc:=private.allocate_transaction_amount((component->>'baseFee')::numeric,weights);
   regional_alloc:=private.allocate_transaction_amount((component->>'regionalFee')::numeric,weights);
   for member in select jsonb_build_object('goodId',good_id,'qty',sum(qty::numeric),'subtotal',sum(qty::numeric*unit_price))
    from jsonb_to_recordset(p_lines) l(good_id text,qty integer,unit_price bigint)
    where private.goods_aggregation_owner(good_id)=component->>'goodId' group by good_id order by good_id loop
    expanded:=component||jsonb_build_object('goodId',member->>'goodId','baseFee',(base_alloc->>(member->>'goodId'))::numeric,
     'regionalFee',(regional_alloc->>(member->>'goodId'))::numeric,
     'totalFee',(base_alloc->>(member->>'goodId'))::numeric+(regional_alloc->>(member->>'goodId'))::numeric);
    components:=components||jsonb_build_array(expanded);
    delivery_terms:=delivery_terms||jsonb_build_array(terms||member);
   end loop;
  end loop;
  raw_groups:=raw_groups||jsonb_build_array(raw_group||jsonb_build_object('components',components,'deliveryTerms',delivery_terms));
  display_groups:=display_groups||jsonb_build_array(jsonb_build_object('originId',raw_group->'originId','prepaidFee',raw_group->'prepaidFee',
   'collectFee',raw_group->'collectFee','fullFee',raw_group->'fullFee','components',components,'collector',raw_group->'collector'));
 end loop;
 return calculation||jsonb_build_object('rawGroups',raw_groups,'displayGroups',display_groups);
end $$

CREATE OR REPLACE FUNCTION private.guard_order_transaction_terms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare version integer;begin
 select calculation_version into version from public.orders where id=new.order_id;
 if version=2 then
  if not exists(select 1 from private.order_goods_transactions where order_id=new.order_id) then
   raise check_violation using message='transaction_order_binding_required';end if;
 elsif exists(select 1 from private.goods_aggregation_members where good_id=new.good_id) then
  raise check_violation using message='checkout_contract_upgrade_required';
 elsif exists(select 1 from private.goods_transaction_configs c left join private.goods_volume_discount_versions v on v.id=c.volume_version_id
  left join private.goods_delivery_versions d on d.id=c.delivery_version_id where c.good_id=new.good_id and (v.status='active' or d.status='active')) then
  raise check_violation using message='checkout_contract_upgrade_required';
 elsif new.volume_unit_discount<>0 or new.volume_discount_total<>0 then raise check_violation using message='transaction_order_binding_required';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.place_order(p_address jsonb, p_checkout_key uuid, p_payment_method order_payment_method)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_key uuid;
begin
  if not exists(select 1 from public.orders where user_id=auth.uid() and checkout_key=p_checkout_key)
   and exists(select 1 from public.cart_items cart join private.goods_aggregation_members family on family.good_id=cart.good_id where cart.user_id=auth.uid()) then
   raise check_violation using message='checkout_contract_upgrade_required';end if;
  order_key:=private.place_order_before_shipments(p_address,p_checkout_key,p_payment_method);
  perform private.create_order_shipments(order_key);
  return order_key;
end $function$

do $$declare fn regprocedure;begin
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='private' and p.proname=any(array['goods_aggregation_owner','guard_goods_aggregation_identity','bind_goods_aggregation',
   'goods_aggregation_shared_policy','guard_goods_aggregation_policy','guard_goods_aggregation_config','calculate_goods_transaction_shipping_families_base']) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',fn);
  execute format('grant execute on function %s to postgres',fn);
  perform private.register_operator_internal_contract(fn);
 end loop;
 -- Existing internals are re-registered after their bodies change.
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='private' and p.proname=any(array['member_goods_reserved_qty','check_goods_purchase_quantity','lock_goods_transaction_catalog',
   'calculate_goods_transaction_locked','evaluate_coupon_target_lines_at','calculate_goods_transaction_shipping','goods_transaction_base_shipping_quote',
   'guard_order_transaction_terms','goods_transaction_terms_document']) loop
  perform private.register_operator_internal_contract(fn);
 end loop;
end $$

