-- Called only by the atomic converter after moving stock and creating the new
-- sales unit. Returns/reshipments take TRY-SHARED on this same topology key;
-- ordinary checkout and stock adjustment never follow this mapping.
create function private.record_goods_stock_successor(
 p_source_good_id text,p_source_variant_id uuid,p_target_good_id text,p_target_variant_id uuid,
 p_operation_id uuid,p_moved_qty integer,p_actor_id uuid) returns void
language plpgsql security invoker set search_path='' as $$
declare s public.goods_variants%rowtype;t public.goods_variants%rowtype;
begin
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 if p_moved_qty is null or p_moved_qty<0 or p_source_good_id is not distinct from p_target_good_id
  or p_source_variant_id is not distinct from p_target_variant_id
  or not exists(select 1 from private.goods_group_operations o where o.operation_id=p_operation_id
    and o.actor_id=p_actor_id and o.command='convert' and o.completed_at is null) then
  raise check_violation using message='goods_stock_successor_invalid';
 end if;
 perform 1 from public.goods where id=any(array[p_source_good_id,p_target_good_id]) order by id for update nowait;
 perform 1 from public.goods_variants where id=any(array[p_source_variant_id,p_target_variant_id]) order by id for update nowait;
 select * into s from public.goods_variants where id=p_source_variant_id and good_id=p_source_good_id;
 select * into t from public.goods_variants where id=p_target_variant_id and good_id=p_target_good_id;
 if s.id is null or t.id is null or s.archived_at is null or s.stock_qty<>0
  or t.archived_at is not null or t.stock_qty<>p_moved_qty
  or exists(select 1 from private.goods_stock_successors where source_variant_id=p_source_variant_id
    or source_variant_id=p_target_variant_id or target_variant_id=p_target_variant_id)
  or exists(select 1 from public.order_items where good_id=p_target_good_id)
  or not exists(select 1 from private.goods_group_write_authorizations
    where transaction_id=txid_current() and good_id=p_target_good_id and actor_id=p_actor_id) then
  raise check_violation using message='goods_stock_successor_invalid';
 end if;
 insert into private.goods_stock_successors(source_variant_id,source_good_id,target_variant_id,target_good_id,operation_id,moved_qty,actor_id)
 values(p_source_variant_id,p_source_good_id,p_target_variant_id,p_target_good_id,p_operation_id,p_moved_qty,p_actor_id);
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$$

-- Dedicated one-option creation. The ordinary clone contract deliberately creates
-- every source option with zero stock and is not a conversion implementation.
create function private.create_goods_group_product(p_source_good_id text,p_source_variant_id uuid,p_name text,p_actor uuid)
returns text language plpgsql security invoker set search_path='' as $$
declare
 source_good public.goods;source_variant public.goods_variants;category_value uuid;
 source_variants jsonb;target_payload jsonb;source_attribute_entries jsonb;clone_attribute_fields jsonb;clone_attribute_revision integer;
 clone_attribute_submission jsonb;clone_attribute_entries jsonb;saved jsonb;saved_id text;actor_id uuid:=p_actor;
 category_ids uuid[];
begin
 select * into source_good from public.goods where id=p_source_good_id;
 select * into source_variant from public.goods_variants where id=p_source_variant_id and good_id=p_source_good_id and archived_at is null;
 if source_good.id is null or source_variant.id is null or p_actor is distinct from auth.uid()
   or p_name is null or char_length(p_name) not between 1 and 200 then
  raise check_violation using message='goods_group_source_invalid';end if;
 category_value:=source_good.category_id;
 if category_value is not null and not exists(select 1 from public.catalog_categories c where c.id=category_value and c.archived_at is null
  and not exists(select 1 from public.catalog_categories child where child.parent_id=c.id and child.archived_at is null)) then
  raise check_violation using message='goods_group_category_review_required';end if;
 source_variants:=jsonb_build_array(jsonb_build_object('name','기본 옵션','attributes','{}'::jsonb,'extraPrice',0,'stockQty',0,
   'isActive',true,'lowStockThreshold',source_variant.low_stock_threshold));
  target_payload := pg_catalog.jsonb_build_object(
    'id', null,
    'code', null,
    'ip_id', source_good.ip_id,
    'name', p_name,
    'name_en', source_good.name_en,
    'type', source_good.type,
    'origin_id', source_good.origin_id,
    'shipping_fee_type', source_good.shipping_fee_type,
    'individual_fee', source_good.individual_fee,
    'allow_card_payment', source_good.allow_card_payment,
    'allow_bank_transfer', source_good.allow_bank_transfer,
    'sale_restriction', source_good.sale_restriction,
    'order_quantity_limit_enabled', source_good.order_quantity_limit_enabled,
    'min_order_qty', source_good.min_order_qty,
    'max_order_qty', source_good.max_order_qty,
    'member_purchase_limit_enabled', source_good.member_purchase_limit_enabled,
    'member_lifetime_qty_limit', source_good.member_lifetime_qty_limit,
    'claim_policy', jsonb_build_object('returnAllowed',source_good.claim_return_allowed,
      'exchangeAllowed',source_good.claim_exchange_allowed,'restrictionReason',source_good.claim_restriction_reason,
      'returnFee',source_good.claim_return_fee,'returnFreeShippingFee',source_good.claim_return_free_shipping_fee,
      'exchangeFee',source_good.claim_exchange_fee),
    'price', source_variant.price,
    'compare_at_price', case when source_good.compare_at_price is null then null else source_good.compare_at_price+(source_variant.price-source_good.price) end,
    'badge', source_good.badge,
    'stock', 'ok',
    'bg', source_good.bg,
    'image_path', null,
    'notice_maker', source_good.notice_maker,
    'notice_origin', source_good.notice_origin,
    'notice_material', source_good.notice_material,
    'notice_size', source_good.notice_size,
    'notice_made_on', source_good.notice_made_on,
    'notice_as_manager', source_good.notice_as_manager,
    'notice_as_contact', source_good.notice_as_contact,
    'description', source_good.description,
    'description_format', source_good.description_format,
    'description_image_paths', '[]'::jsonb,
    'gallery_paths', '[]'::jsonb,
    'detail_image_path', null,
    'search_keywords', coalesce(to_jsonb(source_good.search_keywords), '[]'::jsonb),
    'category_id', category_value,
    'publish', false,
    'variants', source_variants,
    'variant_baseline', '[]'::jsonb
  );

  select entries into source_attribute_entries from public.goods_attribute_values where good_id=source_good.id for share;
  select fields,revision into clone_attribute_fields,clone_attribute_revision
    from public.catalog_category_attribute_schemas where category_id=category_value for share;
  source_attribute_entries:=coalesce(source_attribute_entries,'[]');
  clone_attribute_fields:=coalesce(clone_attribute_fields,'[]');
  clone_attribute_submission:=jsonb_build_object('categoryId',category_value,'schemaRevision',coalesce(clone_attribute_revision,0),
    'expectedRevision',0,'values',coalesce((select jsonb_object_agg(entry#>>'{field,id}',entry->'value')
      from jsonb_array_elements(source_attribute_entries) entry
      where exists(select 1 from jsonb_array_elements(clone_attribute_fields) field where field->>'id'=entry#>>'{field,id}'
        and field->>'kind'=entry#>>'{field,kind}' and field->>'unit'=entry#>>'{field,unit}'
        and private.goods_attribute_value_valid(field,entry->'value'))),'{}'),
    'removeIds','[]'::jsonb);
  clone_attribute_entries:=private.merge_goods_attributes(source_attribute_entries,clone_attribute_fields,clone_attribute_submission->'values','[]');
  target_payload:=target_payload||jsonb_build_object('product_attributes',clone_attribute_submission);
  saved := public.admin_save_good(target_payload);

  saved_id := saved ->> 'id';
  if saved_id is null then
    raise check_violation using message = 'goods_clone_result_missing';
  end if;


  -- Creation remains one transaction/version, including values retained after a
  -- source category change. Publication still exposes only matching definitions.
  update public.goods_attribute_values set entries=clone_attribute_entries
    where good_id=saved_id and entries is distinct from clone_attribute_entries;
  if clone_attribute_entries<>'[]'::jsonb then
    insert into public.audit_log(actor_id,action,target,diff) values(actor_id,'catalog.goods_attributes_cloned','goods:'||saved_id,
      jsonb_build_object('sourceGoodId',source_good.id,'after',clone_attribute_entries,'revision',1));
  end if;

  perform private.clone_goods_benefit_content(source_good.id,saved_id,actor_id);

  perform private.clone_goods_after_sales_content(source_good.id,saved_id,actor_id);

  perform private.clone_goods_size_chart(source_good.id,saved_id,actor_id);
  insert into private.goods_artwork_copy_authorizations(transaction_id,target_good_id,source_good_id,actor_id,allowed_paths)
    values(txid_current(),saved_id,source_good.id,actor_id,
      array_remove(array[source_good.image_path,source_good.detail_image_path]||coalesce(source_good.gallery_paths,'{}')||coalesce(source_good.description_image_paths,'{}'),null));
  update public.goods set image_path=source_good.image_path,gallery_paths=source_good.gallery_paths,
    detail_image_path=source_good.detail_image_path,description_image_paths=source_good.description_image_paths where id=saved_id;
  delete from private.goods_artwork_copy_authorizations where transaction_id=txid_current() and target_good_id=saved_id;

  -- Shipping notice is an immutable snapshot on the source good. Applying the
  -- exact references/snapshot avoids resolving a later template revision.
  update public.goods
  set shipping_notice_template_id = source_good.shipping_notice_template_id,
      shipping_notice_template_version = source_good.shipping_notice_template_version,
      shipping_notice_snapshot = source_good.shipping_notice_snapshot
  where id = saved_id;


 update public.goods copied set custom_inputs_enabled=source_good.custom_inputs_enabled,custom_input_fields=source_good.custom_input_fields,
  show_discount_rate=source_good.show_discount_rate,sale_starts_at=source_good.sale_starts_at,sale_ends_at=source_good.sale_ends_at,
  shipping_settings_template_id=source_good.shipping_settings_template_id,
  shipping_settings_template_revision=source_good.shipping_settings_template_revision,shipping_settings_snapshot=source_good.shipping_settings_snapshot
 where copied.id=saved_id;
 select coalesce(array_agg(m.category_id),'{}'::uuid[]) into category_ids from public.goods_additional_categories m
  join public.catalog_categories c on c.id=m.category_id where m.good_id=p_source_good_id and c.archived_at is null;
 perform private.apply_goods_additional_categories(saved_id,category_ids);
 insert into private.goods_listing_colors(good_id,colors,revision)
  select saved_id,colors,1 from private.goods_listing_colors where good_id=p_source_good_id;
 insert into private.goods_additional_sets(good_id,revision,updated_by)
  select saved_id,1,p_actor from private.goods_additional_sets where good_id=p_source_good_id;
 insert into private.goods_additional_links(base_good_id,target_good_id,sort_order)
  select saved_id,target_good_id,sort_order from private.goods_additional_links where base_good_id=p_source_good_id;
 perform 1 from private.goods_media_assets where id in(select video_asset_id from private.goods_media_bindings where good_id=p_source_good_id
  union select shortclip_asset_id from private.goods_media_bindings where good_id=p_source_good_id) order by id for share;
 if exists(select 1 from private.goods_media_bindings b join private.goods_media_assets a on a.id in(b.video_asset_id,b.shortclip_asset_id)
   where b.good_id=p_source_good_id and a.status<>'attached') then
  raise check_violation using message='goods_group_media_unavailable';end if;
 insert into private.goods_media_bindings(good_id,video_asset_id,video_title,shortclip_asset_id,shortclip_title,revision)
  select saved_id,video_asset_id,video_title,shortclip_asset_id,shortclip_title,1 from private.goods_media_bindings where good_id=p_source_good_id;
 insert into private.goods_group_write_authorizations(transaction_id,good_id,actor_id) values(txid_current(),saved_id,p_actor);
 return saved_id;
end;
$$

create function private.require_goods_group_identity(p_actor uuid,p_session_id uuid) returns void
language plpgsql security invoker set search_path='' as $$
begin
 perform private.require_operator_capability('catalog.manage',false);
 if p_actor is null or p_actor is distinct from auth.uid() or p_session_id is null
  or auth.jwt()->>'session_id' is distinct from p_session_id::text then
  raise insufficient_privilege using message='goods_group_auth_changed';end if;
 perform 1 from auth.sessions where id=p_session_id and user_id=p_actor
  and (not_after is null or not_after>clock_timestamp()) for share;
 if not found then raise insufficient_privilege using message='goods_group_auth_changed';end if;
end;
$$

create function private.validate_goods_group_conversion(p_request jsonb) returns void
language plpgsql immutable security invoker set search_path='' as $$
declare axes text[];row jsonb;vals text[];
begin
 if jsonb_typeof(p_request) is distinct from 'object'
  or not (p_request ?& array['sourceGoodId','name','optionNames','selections'])
  or (select count(*) from jsonb_object_keys(p_request))<>4
  or jsonb_typeof(p_request->'sourceGoodId') is distinct from 'string'
  or coalesce(p_request->>'sourceGoodId','')!~'^[a-z0-9][a-z0-9-]{0,63}$'
  or jsonb_typeof(p_request->'name') is distinct from 'string'
  or p_request->>'name'<>btrim(p_request->>'name')
  or not private.goods_group_valid_labels(array[p_request->>'name'],40)
  or jsonb_typeof(p_request->'optionNames') is distinct from 'array'
  or jsonb_typeof(p_request->'selections') is distinct from 'array' then
  raise invalid_parameter_value using message='invalid_goods_group_conversion';end if;
 if jsonb_array_length(p_request->'optionNames') not between 1 and 3
  or exists(select 1 from jsonb_array_elements(p_request->'optionNames') v where jsonb_typeof(v)<>'string')
  or jsonb_array_length(p_request->'selections') not between 2 and 100 then
  raise invalid_parameter_value using message='invalid_goods_group_conversion';end if;
 axes:=array(select jsonb_array_elements_text(p_request->'optionNames'));
 if not private.goods_group_valid_labels(axes,40) or (select count(distinct v) from unnest(axes) v)<>cardinality(axes) then
  raise invalid_parameter_value using message='invalid_goods_group_conversion';end if;
 for row in select value from jsonb_array_elements(p_request->'selections') loop
  if jsonb_typeof(row) is distinct from 'object' or not (row ?& array['variantId','values'])
   or (select count(*) from jsonb_object_keys(row))<>2
   or jsonb_typeof(row->'variantId') is distinct from 'string'
   or coalesce(row->>'variantId','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(row->'values') is distinct from 'array' then
   raise invalid_parameter_value using message='invalid_goods_group_conversion';end if;
  if jsonb_array_length(row->'values')<>cardinality(axes)
   or exists(select 1 from jsonb_array_elements(row->'values') v where jsonb_typeof(v)<>'string') then
   raise invalid_parameter_value using message='invalid_goods_group_conversion';end if;
  vals:=array(select jsonb_array_elements_text(row->'values'));
  if not private.goods_group_valid_labels(vals,80)
   or char_length(p_request->>'name'||' '||array_to_string(vals,' / '))>200 then
   raise invalid_parameter_value using message='invalid_goods_group_conversion';end if;
 end loop;
 if (select count(distinct v->>'variantId') from jsonb_array_elements(p_request->'selections') v)<>jsonb_array_length(p_request->'selections')
  or (select count(distinct v->'values') from jsonb_array_elements(p_request->'selections') v)<>jsonb_array_length(p_request->'selections') then
  raise invalid_parameter_value using message='invalid_goods_group_conversion';end if;
end;
$$

create function private.goods_group_lock_conversion_source(p_good_id text) returns void
language plpgsql security invoker set search_path='' as $$
declare source_ip text;
begin
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 if not pg_try_advisory_xact_lock(hashtextextended('goods-additional-graph',0)) then
  raise sqlstate 'PT409' using message='goods_group_retry';end if;
 perform private.lock_catalog_category_tree();
 perform 1 from public.goods where id in(p_good_id,private.goods_aggregation_owner(p_good_id)) order by id for update;
 perform 1 from public.goods_variants where good_id=p_good_id order by id for update;
 select ip_id into source_ip from public.goods where id=p_good_id;
 if source_ip is null then raise no_data_found using message='goods_group_source_not_found';end if;
 perform 1 from public.ips where id=source_ip for update nowait;
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$$

create function public.admin_preview_goods_group_conversion(p_request jsonb,p_expected_actor_id uuid,p_expected_session_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare source_id text;preview private.goods_group_conversion_previews;plan jsonb;blockers text[];
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 perform private.validate_goods_group_conversion(p_request);
 source_id:=p_request->>'sourceGoodId';
 perform private.goods_group_lock_conversion_source(source_id);
 blockers:=private.goods_group_conversion_blockers(source_id);
 if cardinality(blockers)>0 then return jsonb_build_object('state','blocked','blockers',to_jsonb(blockers));end if;
 if exists(select 1 from jsonb_array_elements(p_request->'selections') s
  left join public.goods_variants v on v.id=(s->>'variantId')::uuid and v.good_id=source_id and v.archived_at is null
  where v.id is null) then raise check_violation using message='goods_group_selection_changed';end if;
 plan:=jsonb_build_object('sourceGoodId',source_id,'name',p_request->'name','optionNames',p_request->'optionNames',
  'members',(select jsonb_agg(jsonb_build_object('sourceVariantId',v.id,'sourceVariantName',v.name,'values',s.value->'values',
    'retainsGoodId',s.ordinality=1,'goodId',case when s.ordinality=1 then source_id end,
    'price',v.price,'stockQty',v.stock_qty,'name',p_request->>'name'||' '||array_to_string(array(select jsonb_array_elements_text(s.value->'values')),' / ')) order by s.ordinality)
    from jsonb_array_elements(p_request->'selections') with ordinality s(value,ordinality)
    join public.goods_variants v on v.id=(s.value->>'variantId')::uuid),
  'unselectedOptions',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'name',v.name,'stockQty',v.stock_qty) order by v.sort_order,v.id)
    from public.goods_variants v where v.good_id=source_id and v.archived_at is null
      and not exists(select 1 from jsonb_array_elements(p_request->'selections') s where s->>'variantId'=v.id::text)),'[]'::jsonb),
  'requiresKcReview',true,'allProductsUnpublished',true,'aggregationPreserved',true,
  'historicalOrdersPreserved',true,'unselectedStockPreserved',true,'activeCartSelectionsRequireReview',true);
 insert into private.goods_group_conversion_previews(actor_id,session_id,request,source_hash,public_plan)
 values(p_expected_actor_id,p_expected_session_id,p_request,private.goods_group_source_hash(source_id),plan) returning * into preview;
 return jsonb_build_object('state','ready','previewId',preview.id,'expiresAt',preview.expires_at,'plan',preview.public_plan);
end;
$$

create function public.admin_confirm_goods_group_conversion(p_preview_id uuid,p_operation_id uuid,p_expected_actor_id uuid,p_expected_session_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare preview private.goods_group_conversion_previews;prior private.goods_group_operations;
 source_good public.goods;source_variant public.goods_variants;cost private.goods_variant_purchase_costs;
 external_row private.goods_variant_external_identity;source_id text;first_variant_id uuid;first_price integer;
 group_id uuid:=gen_random_uuid();request_hash text;selection record;target_good_id text;target_variant_id uuid;
 members jsonb:='[]';new_ids text[]:='{}';target_name text;target_values text[];family_id uuid;v_receipt jsonb;before_stock bigint;after_stock bigint;
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 if p_preview_id is null or p_operation_id is null then raise invalid_parameter_value using message='invalid_goods_group_operation';end if;
 request_hash:=encode(extensions.digest(jsonb_build_array('convert',p_preview_id)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('goods-group-operation:'||p_operation_id::text,0));
 select * into prior from private.goods_group_operations where operation_id=p_operation_id;
 if found then
  if prior.actor_id<>p_expected_actor_id or prior.session_id<>p_expected_session_id or prior.command<>'convert'
   or prior.request_hash<>request_hash or prior.receipt is null then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  return prior.receipt;
 end if;
 select * into preview from private.goods_group_conversion_previews where id=p_preview_id for update;
 if not found or preview.actor_id<>p_expected_actor_id or preview.session_id<>p_expected_session_id then
  raise insufficient_privilege using message='goods_group_preview_unavailable';end if;
 if preview.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='goods_group_preview_expired';end if;
 source_id:=preview.request->>'sourceGoodId';
 perform private.goods_group_lock_conversion_source(source_id);
 if preview.source_hash is distinct from private.goods_group_source_hash(source_id)
  or cardinality(private.goods_group_conversion_blockers(source_id))>0 then
  raise sqlstate 'PT409' using message='goods_group_source_changed';end if;
 select * into source_good from public.goods where id=source_id;
 select sum(stock_qty::bigint) into before_stock from public.goods_variants where good_id=source_id;
 first_variant_id:=(preview.request#>>'{selections,0,variantId}')::uuid;
 select price into first_price from public.goods_variants where id=first_variant_id and good_id=source_id and archived_at is null;
 if first_price is null then raise sqlstate 'PT409' using message='goods_group_source_changed';end if;
 insert into private.goods_group_operations(operation_id,actor_id,session_id,command,request_hash)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,'convert',request_hash);
 insert into private.goods_group_write_authorizations(transaction_id,good_id,actor_id) values(txid_current(),source_id,p_expected_actor_id);
 -- Every resulting product is reviewed before publication, including the source
 -- whose name/options changed. Historical public slugs and first-publication dates remain.
 update public.goods set published_at=null where id=source_id;
 perform private.invalidate_goods_kc_review(source_id,'goods_group_converted');
 for selection in select value,ordinality from jsonb_array_elements(preview.request->'selections') with ordinality loop
  select * into source_variant from public.goods_variants where id=(selection.value->>'variantId')::uuid and good_id=source_id and archived_at is null;
  if not found then raise sqlstate 'PT409' using message='goods_group_source_changed';end if;
  target_values:=array(select jsonb_array_elements_text(selection.value->'values'));
  target_name:=preview.request->>'name'||' '||array_to_string(target_values,' / ');
  if selection.ordinality=1 then target_good_id:=source_id;target_variant_id:=first_variant_id;
  else
   target_good_id:=private.create_goods_group_product(source_id,source_variant.id,target_name,p_expected_actor_id);
   select id into target_variant_id from public.goods_variants where good_id=target_good_id and is_default and archived_at is null;
   if target_variant_id is null then raise check_violation using message='goods_group_result_missing';end if;
   new_ids:=array_append(new_ids,target_good_id);
   insert into private.goods_variant_price_periods(good_id,variant_id,state,regular_price,discount_price,starts_at,ends_at,created_by,updated_by)
    select target_good_id,target_variant_id,state,regular_price,discount_price,starts_at,ends_at,p_expected_actor_id,p_expected_actor_id
    from private.goods_variant_price_periods where variant_id=source_variant.id and state in('active','draft') order by id;
   select * into cost from private.goods_variant_purchase_costs where variant_id=source_variant.id;
   if found and cost.unit_cost_krw is not null then
    perform private.save_goods_variant_purchase_cost(target_good_id,target_variant_id,cost.unit_cost_krw,cost.tax_basis,null);
   end if;
   select * into external_row from private.goods_variant_external_identity where variant_id=source_variant.id for update;
   if found then
    insert into private.goods_group_external_identity_moves(source_variant_id,target_variant_id,operation_id,before_value,actor_id)
    values(source_variant.id,target_variant_id,p_operation_id,to_jsonb(external_row),p_expected_actor_id);
    delete from private.goods_variant_external_identity where variant_id=source_variant.id;
    insert into private.goods_variant_external_identity(variant_id,erp_code,erp_name,barcode)
     values(target_variant_id,external_row.erp_code,external_row.erp_name,external_row.barcode);
   end if;
   if source_variant.stock_qty>0 then
    perform private.change_goods_variant_stock(source_id,source_variant.id,-source_variant.stock_qty::bigint);
    perform private.change_goods_variant_stock(target_good_id,target_variant_id,source_variant.stock_qty::bigint);
   end if;
  end if;
  members:=members||jsonb_build_array(jsonb_build_object('sourceVariantId',source_variant.id,'goodId',target_good_id,'variantId',target_variant_id,
    'values',to_jsonb(target_values),'sortOrder',selection.ordinality-1,'movedQty',case when selection.ordinality=1 then 0 else source_variant.stock_qty end));
 end loop;
 family_id:=private.bind_goods_aggregation(source_id,new_ids,p_operation_id,p_expected_actor_id);
 update private.goods_variant_price_periods set state='disabled',updated_by=p_expected_actor_id,updated_at=clock_timestamp()
  where good_id=source_id and variant_id<>first_variant_id and state='active';
 -- No old option is physically deleted. Even unselected, never-ordered options
 -- retain their quantities and immutable identity for a later explicit decision.
 update public.goods_variants set is_default=false where good_id=source_id and is_default;
 update public.goods_variants set archived_at=coalesce(archived_at,clock_timestamp()) where good_id=source_id and id<>first_variant_id;
 update public.goods_variants set is_default=true,name='기본 옵션',attributes='{}',sort_order=0 where id=first_variant_id;
 update public.goods set name=preview.request->>'name'||' '||array_to_string(array(select jsonb_array_elements_text(preview.request#>'{selections,0,values}')),' / '),
  price=first_price,compare_at_price=case when source_good.compare_at_price is null then null else source_good.compare_at_price+(first_price-source_good.price) end
  where id=source_id;
 for selection in select value from jsonb_array_elements(members) loop
  if selection.value->>'goodId'<>source_id then
   perform private.record_goods_stock_successor(source_id,(selection.value->>'sourceVariantId')::uuid,selection.value->>'goodId',
    (selection.value->>'variantId')::uuid,p_operation_id,(selection.value->>'movedQty')::integer,p_expected_actor_id);
  end if;
 end loop;
 insert into private.goods_groups(id,name,option_names,common_good_id,created_by,updated_by)
 values(group_id,preview.request->>'name',array(select jsonb_array_elements_text(preview.request->'optionNames')),source_id,p_expected_actor_id,p_expected_actor_id);
 insert into private.goods_group_members(group_id,good_id,variant_id,option_values,sort_order)
 select group_id,m->>'goodId',(m->>'variantId')::uuid,array(select jsonb_array_elements_text(m->'values')),(m->>'sortOrder')::integer
 from jsonb_array_elements(members) m;
 select sum(stock_qty::bigint) into after_stock from public.goods_variants where good_id=any(array_append(new_ids,source_id));
 if before_stock is distinct from after_stock then raise check_violation using message='goods_group_stock_conservation_failed';end if;
 v_receipt:=jsonb_build_object('state','completed','operationId',p_operation_id,'group',private.goods_group_snapshot(group_id),'aggregationId',family_id);
 insert into private.goods_group_changes(group_id,operation_id,actor_id,revision,after_value)
 values(group_id,p_operation_id,p_expected_actor_id,1,v_receipt->'group');
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'catalog.goods_group.converted','goods_group:'||group_id::text,
  jsonb_build_object('sourceGoodId',source_id,'previewId',p_preview_id,'members',members,'stockBefore',before_stock,'stockAfter',after_stock,'aggregationId',family_id));
 update private.goods_group_operations set receipt=v_receipt,completed_at=clock_timestamp() where operation_id=p_operation_id;
 delete from private.goods_group_write_authorizations where transaction_id=txid_current() and actor_id=p_expected_actor_id and good_id=any(array_append(new_ids,source_id));
 return v_receipt;
end;
$$

create function private.guard_goods_group_operation() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
 if tg_op='DELETE' or old.completed_at is not null
  or (to_jsonb(new)-'receipt'-'completed_at') is distinct from (to_jsonb(old)-'receipt'-'completed_at')
  or new.receipt is null or new.completed_at is null then
  raise check_violation using message='goods_group_operation_immutable';end if;
 return new;
end;
$$

create function public.admin_read_goods_group_conversion(p_preview_id uuid,p_operation_id uuid,p_expected_actor_id uuid,p_expected_session_id uuid,p_seal boolean default false)
returns jsonb language plpgsql security definer set search_path='' as $$
declare previous private.goods_group_operations;expected_hash text;result jsonb;
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 if p_preview_id is null or p_operation_id is null or p_seal is null then raise invalid_parameter_value using message='invalid_goods_group_operation';end if;
 expected_hash:=encode(extensions.digest(jsonb_build_array('convert',p_preview_id)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('goods-group-operation:'||p_operation_id::text,0));
 select * into previous from private.goods_group_operations where operation_id=p_operation_id;
 if found then
  if previous.actor_id<>p_expected_actor_id or previous.session_id<>p_expected_session_id or previous.command<>'convert'
   or previous.request_hash<>expected_hash then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  return previous.receipt;
 end if;
 if not exists(select 1 from private.goods_group_conversion_previews where id=p_preview_id and actor_id=p_expected_actor_id and session_id=p_expected_session_id) then
  raise insufficient_privilege using message='goods_group_preview_unavailable';end if;
 if p_seal then
  result:=jsonb_build_object('state','sealed','operationId',p_operation_id);
  insert into private.goods_group_operations(operation_id,actor_id,session_id,command,request_hash,receipt,completed_at)
  values(p_operation_id,p_expected_actor_id,p_expected_session_id,'convert',expected_hash,result,clock_timestamp());
  return result;
 end if;
 return jsonb_build_object('state','unresolved','operationId',p_operation_id);
end;
$$

create function private.guard_goods_stock_successor_source() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.archived_at is null and exists(select 1 from private.goods_stock_successors where source_variant_id=new.id) then
  raise check_violation using message='goods_group_old_variant_retired';end if;
 return new;
end;
$$

-- Deferred because the existing normal editor briefly clears the default flag
-- while updating its one retained option. The completed transaction must still
-- contain exactly the member's active default unit and no nested sales options.
create function private.check_goods_group_single_variant() returns trigger
language plpgsql security definer set search_path='' as $$
declare target_id text;member private.goods_group_members;
begin
 target_id:=case when tg_op='DELETE' then old.good_id else new.good_id end;
 select * into member from private.goods_group_members where good_id=target_id;
 if not found then return null;end if;
 if (select count(*) from public.goods_variants where good_id=target_id and archived_at is null)<>1
  or not exists(select 1 from public.goods_variants where id=member.variant_id and good_id=target_id
   and archived_at is null and is_default and name='기본 옵션' and attributes='{}'::jsonb)
  or cardinality(member.option_values)<>(select cardinality(option_names) from private.goods_groups where id=member.group_id)
  or not exists(select 1 from public.goods good join private.goods_groups g on g.id=member.group_id where good.id=member.good_id
    and good.name=g.name||' '||array_to_string(member.option_values,' / ')) then
  raise check_violation using message='goods_group_single_variant_required';end if;
 return null;
end;
$$

create function private.guard_goods_group_name() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if exists(select 1 from private.goods_group_members where good_id=old.id) then
  if new.id is distinct from old.id then raise check_violation using message='goods_group_identity_immutable';end if;
  if new.name is distinct from old.name and not exists(select 1 from private.goods_group_write_authorizations
   where transaction_id=txid_current() and good_id=old.id and actor_id=auth.uid()) then
   raise check_violation using message='goods_group_name_owned_by_group';end if;
 end if;
 return new;
end;
$$

create function public.admin_get_goods_group(p_group_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 return private.goods_group_snapshot(p_group_id);
end;
$$

create function public.admin_search_goods_groups(p_query text default '',p_page integer default 1,p_page_size integer default 30) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare query text:=btrim(coalesce(p_query,''));total bigint;rows jsonb;
begin
 if not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 if char_length(query)>100 or p_page is null or p_page not between 1 and 999999 or p_page_size is null or p_page_size not between 1 and 100 then
  raise invalid_parameter_value using message='invalid_goods_group_page';end if;
 select count(*) into total from private.goods_groups g where query='' or position(lower(query) in lower(g.name))>0
  or exists(select 1 from private.goods_group_members m join public.goods good on good.id=m.good_id
   where m.group_id=g.id and position(lower(query) in lower(good.id||' '||good.code||' '||good.name))>0);
 select coalesce(jsonb_agg(private.goods_group_snapshot(g.id) order by g.updated_at desc,g.id),'[]') into rows
 from(select g.id,g.updated_at from private.goods_groups g where query='' or position(lower(query) in lower(g.name))>0
   or exists(select 1 from private.goods_group_members m join public.goods good on good.id=m.good_id
    where m.group_id=g.id and position(lower(query) in lower(good.id||' '||good.code||' '||good.name))>0)
  order by g.updated_at desc,g.id limit p_page_size offset (p_page::bigint-1)*p_page_size) g;
 return jsonb_build_object('rows',rows,'total',total,'page',p_page,'pageSize',p_page_size);
end;
$$

create function public.admin_get_goods_group_source(p_good_id text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 return(select jsonb_build_object('goodId',g.id,'name',g.name,'code',g.code,
  'groupId',(select group_id from private.goods_group_members where good_id=g.id),'blockers',to_jsonb(private.goods_group_conversion_blockers(g.id)),
  'variants',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'name',v.name,'attributes',v.attributes,'price',v.price,'stockQty',v.stock_qty,'code',v.code)
    order by v.is_default desc,v.sort_order,v.id) from public.goods_variants v where v.good_id=g.id and v.archived_at is null),'[]'))
  from public.goods g where g.id=p_good_id and g.archived_at is null);
end;
$$

create function private.validate_goods_group_structure(p_values jsonb) returns void
language plpgsql immutable security invoker set search_path='' as $$
declare axes text[];member jsonb;vals text[];
begin
 if jsonb_typeof(p_values) is distinct from 'object' or not (p_values ?& array['name','optionNames','members'])
  or (select count(*) from jsonb_object_keys(p_values))<>3
  or jsonb_typeof(p_values->'name') is distinct from 'string' or p_values->>'name'<>btrim(p_values->>'name')
  or not private.goods_group_valid_labels(array[p_values->>'name'],40)
  or jsonb_typeof(p_values->'optionNames') is distinct from 'array' or jsonb_typeof(p_values->'members') is distinct from 'array' then
  raise invalid_parameter_value using message='invalid_goods_group_structure';end if;
 if jsonb_array_length(p_values->'optionNames') not between 1 and 3
  or exists(select 1 from jsonb_array_elements(p_values->'optionNames') v where jsonb_typeof(v)<>'string')
  or jsonb_array_length(p_values->'members') not between 1 and 100 then
  raise invalid_parameter_value using message='invalid_goods_group_structure';end if;
 axes:=array(select jsonb_array_elements_text(p_values->'optionNames'));
 if not private.goods_group_valid_labels(axes,40) or (select count(distinct a) from unnest(axes) a)<>cardinality(axes) then
  raise invalid_parameter_value using message='invalid_goods_group_structure';end if;
 for member in select value from jsonb_array_elements(p_values->'members') loop
  if jsonb_typeof(member) is distinct from 'object' or not (member ?& array['goodId','values'])
   or (select count(*) from jsonb_object_keys(member))<>2
   or jsonb_typeof(member->'goodId') is distinct from 'string' or coalesce(member->>'goodId','')!~'^[a-z0-9][a-z0-9-]{0,63}$'
   or jsonb_typeof(member->'values') is distinct from 'array' then
   raise invalid_parameter_value using message='invalid_goods_group_structure';end if;
  if jsonb_array_length(member->'values')<>cardinality(axes)
   or exists(select 1 from jsonb_array_elements(member->'values') v where jsonb_typeof(v)<>'string') then
   raise invalid_parameter_value using message='invalid_goods_group_structure';end if;
  vals:=array(select jsonb_array_elements_text(member->'values'));
  if not private.goods_group_valid_labels(vals,80) or char_length(p_values->>'name'||' '||array_to_string(vals,' / '))>200 then
   raise invalid_parameter_value using message='invalid_goods_group_structure';end if;
 end loop;
 if (select count(distinct m->>'goodId') from jsonb_array_elements(p_values->'members') m)<>jsonb_array_length(p_values->'members')
  or (select count(distinct m->'values') from jsonb_array_elements(p_values->'members') m)<>jsonb_array_length(p_values->'members') then
  raise invalid_parameter_value using message='invalid_goods_group_structure';end if;
end;
$$

create function public.admin_save_goods_group(p_group_id uuid,p_expected_revision bigint,p_values jsonb,p_operation_id uuid,p_expected_actor_id uuid,p_expected_session_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare prior private.goods_group_operations;existing private.goods_groups;expected_hash text;target_ids text[];lock_ids text[];
 common_id text;common_data jsonb;source_ip text;row record;unit_id uuid;before_value jsonb;result jsonb;current_command text;
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 perform private.validate_goods_group_structure(p_values);
 if p_group_id is null or p_expected_revision is null or p_expected_revision<0 or p_operation_id is null then
  raise invalid_parameter_value using message='invalid_goods_group_operation';end if;
 current_command:=case when p_expected_revision=0 then 'create' else 'update' end;
 expected_hash:=encode(extensions.digest(jsonb_build_array(current_command,p_group_id,p_expected_revision,p_values)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('goods-group-operation:'||p_operation_id::text,0));
 select * into prior from private.goods_group_operations where operation_id=p_operation_id;
 if found then
  if prior.actor_id<>p_expected_actor_id or prior.session_id<>p_expected_session_id or prior.command<>current_command
   or prior.target_group_id is distinct from p_group_id or prior.expected_revision is distinct from p_expected_revision
   or prior.receipt is null then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  if prior.receipt->>'state'='sealed' then return prior.receipt;end if;
  if prior.request_hash<>expected_hash then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  return prior.receipt;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 perform private.lock_catalog_category_tree();
 select * into existing from private.goods_groups where id=p_group_id for update;
 if (existing.id is null and p_expected_revision<>0) or (existing.id is not null and existing.revision<>p_expected_revision)
  or existing.archived_at is not null then raise sqlstate 'PT409' using message='goods_group_changed';end if;
 if existing.id is null and jsonb_array_length(p_values->'members')<2 then
  raise check_violation using message='goods_group_members_required';end if;
 before_value:=private.goods_group_snapshot(p_group_id);
 target_ids:=array(select m->>'goodId' from jsonb_array_elements(p_values->'members') m);
 lock_ids:=array(select distinct id from(
  select unnest(target_ids) id union select good_id from private.goods_group_members where group_id=p_group_id
  union select private.goods_aggregation_owner(unnest(target_ids))) all_ids order by id);
 perform 1 from public.goods where id=any(lock_ids) order by id for update;
 perform 1 from public.goods_variants where good_id=any(lock_ids) order by good_id,id for update;
 for source_ip in select distinct ip_id from public.goods where id=any(target_ids) order by ip_id loop
  begin perform 1 from public.ips where id=source_ip for update nowait;
  exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';end;
 end loop;
 if (select count(*) from public.goods where id=any(target_ids) and archived_at is null)<>cardinality(target_ids)
  or exists(select 1 from private.goods_group_members where good_id=any(target_ids) and group_id<>p_group_id) then
  raise check_violation using message='goods_group_member_unavailable';end if;
 common_id:=case when existing.common_good_id=any(target_ids) then existing.common_good_id else target_ids[1] end;
 common_data:=private.goods_group_common_identity(common_id);
 if exists(select 1 from unnest(target_ids) id where private.goods_group_common_identity(id) is distinct from common_data) then
  raise check_violation using message='goods_group_common_information_differs';end if;
 if exists(select 1 from unnest(target_ids) target(id) where (select count(*) from public.goods_variants v where v.good_id=target.id and v.archived_at is null)<>1
  or not exists(select 1 from public.goods_variants v where v.good_id=target.id and v.archived_at is null and v.is_default)) then
  raise check_violation using message='goods_group_single_variant_required';end if;
 insert into private.goods_group_operations(operation_id,actor_id,session_id,command,target_group_id,expected_revision,request_hash)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,current_command,p_group_id,p_expected_revision,expected_hash);
 insert into private.goods_group_write_authorizations(transaction_id,good_id,actor_id)
 select txid_current(),id,p_expected_actor_id from unnest(target_ids) id;
 if existing.id is null then
  insert into private.goods_groups(id,name,option_names,common_good_id,created_by,updated_by)
  values(p_group_id,p_values->>'name',array(select jsonb_array_elements_text(p_values->'optionNames')),common_id,p_expected_actor_id,p_expected_actor_id);
 else
  update private.goods_groups set name=p_values->>'name',option_names=array(select jsonb_array_elements_text(p_values->'optionNames')),
   common_good_id=common_id,revision=revision+1,updated_by=p_expected_actor_id,updated_at=clock_timestamp() where id=p_group_id;
 end if;
 delete from private.goods_group_members where group_id=p_group_id;
 for row in select value,ordinality from jsonb_array_elements(p_values->'members') with ordinality loop
  select id into unit_id from public.goods_variants where good_id=row.value->>'goodId' and archived_at is null and is_default;
  update public.goods set published_at=null,name=p_values->>'name'||' '||array_to_string(array(select jsonb_array_elements_text(row.value->'values')),' / ')
   where id=row.value->>'goodId';
  perform private.invalidate_goods_kc_review(row.value->>'goodId','goods_group_updated');
  update public.goods_variants set name='기본 옵션',attributes='{}' where id=unit_id;
  insert into private.goods_group_members(group_id,good_id,variant_id,option_values,sort_order)
  values(p_group_id,row.value->>'goodId',unit_id,array(select jsonb_array_elements_text(row.value->'values')),row.ordinality-1);
 end loop;
 result:=jsonb_build_object('state','completed','operationId',p_operation_id,'group',private.goods_group_snapshot(p_group_id));
 insert into private.goods_group_changes(group_id,operation_id,actor_id,revision,before_value,after_value)
 values(p_group_id,p_operation_id,p_expected_actor_id,(result#>>'{group,revision}')::bigint,before_value,result->'group');
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'catalog.goods_group.'||current_command,'goods_group:'||p_group_id::text,
  jsonb_build_object('before',before_value,'after',result->'group','aggregationRelationshipsPreserved',true));
 update private.goods_group_operations set receipt=result,completed_at=clock_timestamp() where operation_id=p_operation_id;
 delete from private.goods_group_write_authorizations where transaction_id=txid_current() and actor_id=p_expected_actor_id and good_id=any(target_ids);
 return result;
end;
$$

create function public.admin_archive_goods_group(p_group_id uuid,p_expected_revision bigint,p_operation_id uuid,p_expected_actor_id uuid,p_expected_session_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare prior private.goods_group_operations;current_group private.goods_groups;expected_hash text;before_value jsonb;result jsonb;
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 if p_group_id is null or p_expected_revision is null or p_expected_revision<1 or p_operation_id is null then
  raise invalid_parameter_value using message='invalid_goods_group_operation';end if;
 expected_hash:=encode(extensions.digest(jsonb_build_array('archive',p_group_id,p_expected_revision)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('goods-group-operation:'||p_operation_id::text,0));
 select * into prior from private.goods_group_operations where operation_id=p_operation_id;
 if found then
  if prior.actor_id<>p_expected_actor_id or prior.session_id<>p_expected_session_id or prior.command<>'archive'
   or prior.target_group_id is distinct from p_group_id or prior.expected_revision is distinct from p_expected_revision
   or prior.receipt is null then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  if prior.receipt->>'state'='sealed' then return prior.receipt;end if;
  if prior.request_hash<>expected_hash then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  return prior.receipt;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 select * into current_group from private.goods_groups where id=p_group_id for update;
 if not found or current_group.revision<>p_expected_revision or current_group.archived_at is not null then
  raise sqlstate 'PT409' using message='goods_group_changed';end if;
 before_value:=private.goods_group_snapshot(p_group_id);
 insert into private.goods_group_operations(operation_id,actor_id,session_id,command,target_group_id,expected_revision,request_hash)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,'archive',p_group_id,p_expected_revision,expected_hash);
 delete from private.goods_group_members where group_id=p_group_id;
 update private.goods_groups set revision=revision+1,archived_at=clock_timestamp(),updated_at=clock_timestamp(),updated_by=p_expected_actor_id where id=p_group_id;
 result:=jsonb_build_object('state','completed','operationId',p_operation_id,'group',private.goods_group_snapshot(p_group_id));
 insert into private.goods_group_changes(group_id,operation_id,actor_id,revision,before_value,after_value)
 values(p_group_id,p_operation_id,p_expected_actor_id,current_group.revision+1,before_value,result->'group');
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'catalog.goods_group.archived','goods_group:'||p_group_id::text,
  jsonb_build_object('before',before_value,'after',result->'group','aggregationRelationshipsPreserved',true));
 update private.goods_group_operations set receipt=result,completed_at=clock_timestamp() where operation_id=p_operation_id;
 return result;
end;
$$

create function public.admin_read_goods_group_change(p_group_id uuid,p_expected_revision bigint,p_command text,p_operation_id uuid,
 p_expected_actor_id uuid,p_expected_session_id uuid,p_seal boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare prior private.goods_group_operations;result jsonb;expected_hash text;
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 if p_group_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 or p_seal is null
  or p_command is null or p_command not in('create','update','common','archive')
  or (p_expected_revision=0) is distinct from (p_command='create') then
  raise invalid_parameter_value using message='invalid_goods_group_operation';end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-group-operation:'||p_operation_id::text,0));
 select * into prior from private.goods_group_operations where operation_id=p_operation_id;
 if found then
  if prior.actor_id<>p_expected_actor_id or prior.session_id<>p_expected_session_id or prior.command<>p_command
   or prior.target_group_id is distinct from p_group_id or prior.expected_revision is distinct from p_expected_revision
   or prior.receipt is null then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  return prior.receipt;
 end if;
 if p_seal then
  expected_hash:=encode(extensions.digest(jsonb_build_array('sealed',p_command,p_group_id,p_expected_revision)::text,'sha256'),'hex');
  result:=jsonb_build_object('state','sealed','operationId',p_operation_id);
  insert into private.goods_group_operations(operation_id,actor_id,session_id,command,target_group_id,expected_revision,request_hash,receipt,completed_at)
  values(p_operation_id,p_expected_actor_id,p_expected_session_id,p_command,p_group_id,p_expected_revision,expected_hash,result,clock_timestamp());
  return result;
 end if;
 return jsonb_build_object('state','unresolved','operationId',p_operation_id);
end;
$$

-- Fulfillment presentation reads the same financial owner as checkout. Customer
-- service/claim notices remain the actual selected product's content.
do $patch$ declare definition text;anchor text;begin
 definition:=pg_get_functiondef('public.get_good_shipping_policy(text)'::regprocedure);
 foreach anchor in array array['''feeType'', good.shipping_fee_type','''individualFee'', good.individual_fee',
  'join public.fulfillment_origins origin on origin.id = good.origin_id and origin.is_active'] loop
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'goods_group_shipping_reader_anchor_changed';end if;
 end loop;
 definition:=replace(definition,'''feeType'', good.shipping_fee_type','''feeType'', policy_good.shipping_fee_type');
 definition:=replace(definition,'''individualFee'', good.individual_fee','''individualFee'', policy_good.individual_fee');
 definition:=replace(definition,'join public.fulfillment_origins origin on origin.id = good.origin_id and origin.is_active',
  E'join public.goods policy_good on policy_good.id = private.goods_aggregation_owner(good.id)\n  join public.fulfillment_origins origin on origin.id = policy_good.origin_id and origin.is_active');
 execute definition;
 perform private.register_operator_internal_contract('public.get_good_shipping_policy(text)'::regprocedure);
end $patch$

create function private.resolve_goods_stock_successor(p_good_id text,p_variant_id uuid)
returns table(good_id text,variant_id uuid,hop_count integer,operation_path uuid[])
language plpgsql stable security invoker set search_path='' as $$
declare edge private.goods_stock_successors%rowtype; seen uuid[];
begin
 good_id:=p_good_id;variant_id:=p_variant_id;hop_count:=0;operation_path:='{}';seen:=array[p_variant_id];
 loop
  if not exists(select 1 from public.goods_variants v where v.id=resolve_goods_stock_successor.variant_id and v.good_id=resolve_goods_stock_successor.good_id) then
   raise check_violation using message='goods_stock_successor_pair_invalid';
  end if;
  select * into edge from private.goods_stock_successors s where s.source_variant_id=resolve_goods_stock_successor.variant_id;
  if not found then return next;return;end if;
  if edge.source_good_id<>good_id or edge.target_variant_id=any(seen) or hop_count>=128 then
   raise check_violation using message='goods_stock_successor_invalid';
  end if;
  good_id:=edge.target_good_id;variant_id:=edge.target_variant_id;hop_count:=hop_count+1;
  operation_path:=array_append(operation_path,edge.operation_id);seen:=array_append(seen,variant_id);
 end loop;
end;
$$

-- A batch owns every involved good before any variant. Validate final per-option
-- and aggregate integer bounds before applying negative deltas first, so a swap
-- at the aggregate ceiling has no transient overflow.
create function private.apply_group_physical_stock_deltas(p_deltas jsonb) returns void
language plpgsql security invoker set search_path='' as $$
declare item record;
begin
 if jsonb_typeof(p_deltas) is distinct from 'array' or jsonb_array_length(p_deltas)>2000 then
  raise check_violation using message='group_stock_deltas_invalid';
 end if;
 perform 1 from public.goods g where g.id in(select x->>'goodId' from jsonb_array_elements(p_deltas) x) order by g.id for update nowait;
 perform 1 from public.goods_variants v where v.id in(select (x->>'variantId')::uuid from jsonb_array_elements(p_deltas) x) order by v.id for update nowait;
 for item in select x->>'goodId' good_id,(x->>'variantId')::uuid variant_id,sum((x->>'delta')::bigint) delta
  from jsonb_array_elements(p_deltas) x group by 1,2 loop
  if not exists(select 1 from public.goods_variants v where v.id=item.variant_id and v.good_id=item.good_id) then
   raise check_violation using message='goods_stock_successor_pair_invalid';
  end if;
  if (select v.stock_qty::bigint+item.delta from public.goods_variants v where v.id=item.variant_id) not between 0 and 2147483647 then
   raise check_violation using message='insufficient_or_overflowing_stock';
  end if;
 end loop;
 for item in select x->>'goodId' good_id,sum((x->>'delta')::bigint) delta from jsonb_array_elements(p_deltas) x group by 1 loop
  if (select coalesce(sum(v.stock_qty::bigint),0)+item.delta from public.goods_variants v where v.good_id=item.good_id) not between 0 and 2147483647 then
   raise check_violation using message='stock_aggregate_overflow';
  end if;
 end loop;
 for item in select x->>'goodId' good_id,(x->>'variantId')::uuid variant_id,sum((x->>'delta')::bigint) delta
  from jsonb_array_elements(p_deltas) x group by 1,2 having sum((x->>'delta')::bigint)<>0 order by 1,3,2 loop
  perform private.change_goods_variant_stock(item.good_id,item.variant_id,item.delta::bigint);
 end loop;
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$$

create or replace function private.restore_order_item_supply(p_order_item_id uuid,p_reason text)
returns void language plpgsql security invoker set search_path='' as $$
declare item public.order_items;reservation private.goods_preorder_reservations;physical record;target record;
 reason_value text:=coalesce(nullif(btrim(p_reason),''),'주문 전체 취소');affected boolean;inserted integer;
begin
 select * into item from public.order_items where id=p_order_item_id;
 if not found then raise no_data_found using message='order_item_not_found';end if;
 -- All public writers own this order first; the reentrant lock also protects
 -- internal direct retries from restoring one physical generation twice.
 perform 1 from public.orders where id=item.order_id for update;
 perform private.lock_goods_stock_successor_topology();
 select * into physical from private.order_item_physical_unit(item.id);
 select * into target from private.resolve_goods_stock_successor(physical.good_id,physical.variant_id);
 perform 1 from public.goods where id=any(array[item.good_id,physical.good_id,target.good_id]) order by id for update nowait;
 perform 1 from public.goods_variants where id=any(array[item.variant_id,physical.variant_id,target.variant_id]) order by id for update nowait;
 if item.supply_source='preorder' then
  select * into reservation from private.goods_preorder_reservations where order_item_id=item.id for update;
  if not found then raise check_violation using message='preorder_reservation_missing';end if;
  if reservation.state in ('released','returned') then return;end if;
  if reservation.state='reserved' then
   update private.goods_preorder_reservations set state='released',released_at=clock_timestamp(),released_by=auth.uid(),release_reason=reason_value where order_item_id=item.id;
   insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'order.preorder_capacity_released','order:'||item.order_id::text,
    jsonb_build_object('orderItemId',item.id,'goodId',item.good_id,'variantId',item.variant_id,'policyId',reservation.policy_id,'qty',item.qty,'physicalStockDelta',0,'reason',reason_value));
   return;
  end if;
 end if;
 affected:=target.hop_count>0 or physical.good_id<>item.good_id or exists(select 1 from private.group_claim_reshipment_allocations where order_item_id=item.id);
 if affected then
  insert into private.group_stock_restorations(order_item_id,generation_kind,generation_id,original_good_id,original_variant_id,
   source_good_id,source_variant_id,target_good_id,target_variant_id,operation_path,qty,cause,actor_id,reason)
  values(item.id,physical.generation_kind,physical.generation_id,item.good_id,item.variant_id,
   physical.good_id,physical.variant_id,target.good_id,target.variant_id,target.operation_path,item.qty,'refund',auth.uid(),reason_value)
  on conflict do nothing;
  get diagnostics inserted=row_count;
  if inserted=0 then return;end if;
 end if;
 perform private.apply_group_physical_stock_deltas(jsonb_build_array(jsonb_build_object('goodId',target.good_id,'variantId',target.variant_id,'delta',item.qty)));
 if item.supply_source='preorder' then
  update private.goods_preorder_reservations set state='returned',released_at=clock_timestamp(),released_by=auth.uid(),release_reason=reason_value where order_item_id=item.id;
 end if;
 insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'order.option_stock_restored','order:'||item.order_id::text,
  jsonb_build_object('orderItemId',item.id,'goodId',target.good_id,'variantId',target.variant_id,'delta',item.qty,
   'originalGoodId',item.good_id,'originalVariantId',item.variant_id,'physicalGoodId',physical.good_id,'physicalVariantId',physical.variant_id,
   'generationKind',physical.generation_kind,'generationId',physical.generation_id,'operationPath',target.operation_path,
   'supplySource',item.supply_source,'preorderPolicyId',item.preorder_policy_id,'reason',p_reason));
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$$

create function private.record_group_claim_reshipment(p_claim_id uuid,p_carrier text,p_tracking text,p_selections jsonb)
returns text language plpgsql security invoker set search_path='' as $$
declare actor uuid:=auth.uid();claim public.order_cancellation_requests;order_state public.order_status;receipt private.group_claim_reshipment_receipts;
 item public.order_items;physical record;target record;choice record;selected_variant uuid;allocations jsonb:='[]';entry jsonb;
 good_ids text[];variant_ids uuid[];deltas jsonb;shipped_items jsonb;inserted integer;
begin
 perform private.require_operator_capability('sales.manage',false);
 select * into claim from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found';end if;
 select status into order_state from public.orders where id=claim.order_id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 if claim.claim_type<>'exchange' then raise check_violation using message='claim_type_has_no_reshipment';end if;
 select * into receipt from private.group_claim_reshipment_receipts where claim_id=p_claim_id;
 if found then
  if claim.stage='completed' and receipt.actor_id=actor and receipt.carrier=p_carrier and receipt.tracking_number=p_tracking and receipt.selections=p_selections then return 'completed';end if;
  raise unique_violation using message='reshipment_conflict';
 end if;
 if claim.stage='completed' or exists(select 1 from public.order_claim_reshipment_items where claim_id=p_claim_id) then
  raise unique_violation using message='reshipment_conflict';
 end if;
 perform private.assert_claim_collections_complete(p_claim_id);
 if claim.stage<>'collected' or order_state not in ('delivered','done') or exists(select 1 from public.order_cancellation_claims where order_id=claim.order_id) then
  raise check_violation using message='claim_not_reshippable';
 end if;
 if not exists(select 1 from public.shipping_carriers where code=p_carrier and is_active) then raise check_violation using message='unknown shipping carrier';end if;
 if exists(select 1 from jsonb_array_elements(p_selections) x where not exists(select 1 from public.order_items oi where oi.id=(x->>'orderItemId')::uuid and oi.order_id=claim.order_id)) then
  raise check_violation using message='invalid reshipment items';
 end if;
 perform private.lock_goods_stock_successor_topology();
 for item in select * from public.order_items where order_id=claim.order_id order by good_id,id loop
  select * into physical from private.order_item_physical_unit(item.id);
  select * into target from private.resolve_goods_stock_successor(physical.good_id,physical.variant_id);
  select (x->>'variantId')::uuid into selected_variant from jsonb_array_elements(p_selections) x where (x->>'orderItemId')::uuid=item.id;
  selected_variant:=coalesce(selected_variant,target.variant_id);
  select * into choice from private.order_item_reshipment_options(item.id) where variant_id=selected_variant;
  if not found then raise check_violation using message='reshipment_variant_unavailable';end if;
  allocations:=allocations||jsonb_build_array(jsonb_build_object('orderItemId',item.id,'originalGoodId',item.good_id,'originalVariantId',item.variant_id,
   'sourceGoodId',physical.good_id,'sourceVariantId',physical.variant_id,'generationKind',physical.generation_kind,'generationId',physical.generation_id,
   'returnedGoodId',target.good_id,'returnedVariantId',target.variant_id,'operationPath',to_jsonb(target.operation_path),
   'goodId',choice.good_id,'variantId',choice.variant_id,'goodName',choice.good_name,'variantName',choice.variant_name,'variantCode',choice.variant_code,'qty',item.qty));
 end loop;
 if jsonb_array_length(allocations) not between 1 and 1000 then raise check_violation using message='invalid reshipment items';end if;
 select array_agg(distinct id order by id) into good_ids from (
  select x->>'originalGoodId' id from jsonb_array_elements(allocations) x union select x->>'sourceGoodId' from jsonb_array_elements(allocations) x
  union select x->>'returnedGoodId' from jsonb_array_elements(allocations) x union select x->>'goodId' from jsonb_array_elements(allocations) x) ids;
 select array_agg(distinct id order by id) into variant_ids from (
  select (x->>'originalVariantId')::uuid id from jsonb_array_elements(allocations) x union select (x->>'sourceVariantId')::uuid from jsonb_array_elements(allocations) x
  union select (x->>'returnedVariantId')::uuid from jsonb_array_elements(allocations) x union select (x->>'variantId')::uuid from jsonb_array_elements(allocations) x) ids;
 perform 1 from public.goods where id=any(good_ids) order by id for update nowait;
 perform 1 from public.goods_variants where id=any(variant_ids) order by id for update nowait;
 -- Metadata and availability are read again after locks; topology remains fixed.
 for entry in select value from jsonb_array_elements(allocations) loop
  if not exists(select 1 from private.order_item_reshipment_options((entry->>'orderItemId')::uuid) where variant_id=(entry->>'variantId')::uuid) then
   raise sqlstate 'PT409' using message='reshipment_variant_unavailable';
  end if;
 end loop;
 insert into private.group_claim_reshipment_receipts(claim_id,actor_id,carrier,tracking_number,selections) values(p_claim_id,actor,p_carrier,p_tracking,p_selections);
 for entry in select value from jsonb_array_elements(allocations) loop
  insert into private.group_stock_restorations(order_item_id,generation_kind,generation_id,original_good_id,original_variant_id,
   source_good_id,source_variant_id,target_good_id,target_variant_id,operation_path,qty,cause,claim_id,actor_id,reason)
  values((entry->>'orderItemId')::uuid,entry->>'generationKind',(entry->>'generationId')::uuid,entry->>'originalGoodId',(entry->>'originalVariantId')::uuid,
   entry->>'sourceGoodId',(entry->>'sourceVariantId')::uuid,entry->>'returnedGoodId',(entry->>'returnedVariantId')::uuid,
   array(select value::uuid from jsonb_array_elements_text(entry->'operationPath')),(entry->>'qty')::integer,'exchange',p_claim_id,actor,'교환 회수품 입고') on conflict do nothing;
  get diagnostics inserted=row_count;
  if inserted<>1 then raise check_violation using message='physical_generation_already_restored';end if;
  insert into private.group_claim_reshipment_allocations(claim_id,order_item_id,original_good_id,original_variant_id,source_good_id,source_variant_id,
   source_generation_kind,source_generation_id,returned_good_id,returned_variant_id,operation_path,target_good_id,target_variant_id,
   good_name_snapshot,variant_name_snapshot,variant_code_snapshot,qty)
  select p_claim_id,(entry->>'orderItemId')::uuid,entry->>'originalGoodId',(entry->>'originalVariantId')::uuid,entry->>'sourceGoodId',(entry->>'sourceVariantId')::uuid,
   entry->>'generationKind',(entry->>'generationId')::uuid,entry->>'returnedGoodId',(entry->>'returnedVariantId')::uuid,
   array(select value::uuid from jsonb_array_elements_text(entry->'operationPath')),entry->>'goodId',(entry->>'variantId')::uuid,g.name,v.name,v.code,(entry->>'qty')::integer
  from public.goods g join public.goods_variants v on v.good_id=g.id where v.id=(entry->>'variantId')::uuid and g.id=entry->>'goodId';
 end loop;
 select jsonb_agg(value) into deltas from (
  select jsonb_build_object('goodId',a.returned_good_id,'variantId',a.returned_variant_id,'delta',a.qty) value from private.group_claim_reshipment_allocations a where claim_id=p_claim_id
  union all select jsonb_build_object('goodId',a.target_good_id,'variantId',a.target_variant_id,'delta',-a.qty) from private.group_claim_reshipment_allocations a where claim_id=p_claim_id) movement;
 perform private.apply_group_physical_stock_deltas(deltas);
 select coalesce(jsonb_agg(jsonb_build_object('orderItemId',r.order_item_id,'originalGoodId',r.original_good_id,'sourceGoodId',r.source_good_id,'sourceVariantId',r.source_variant_id,
  'goodId',r.good_id,'variantId',r.variant_id,'qty',r.qty) order by r.order_item_id),'[]') into shipped_items from private.claim_reshipment_items_read(p_claim_id) r;
 update public.order_cancellation_requests set stage='completed',reship_carrier=p_carrier,reship_tracking_number=p_tracking,reshipped_at=clock_timestamp(),completed_at=clock_timestamp(),updated_at=clock_timestamp() where id=p_claim_id;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.claim_reshipped','order:'||claim.order_id::text,
  jsonb_build_object('claimId',p_claim_id,'claimType','exchange','from','collected','to','completed','carrier',p_carrier,'items',shipped_items));
 perform private.notify_order_claim(p_claim_id,'reshipped','교환 상품이 재출고됐어요','교환 상품을 새 운송장으로 발송했습니다.');
 return 'completed';
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$$

-- Existing same-product exchange behavior remains the fallback.
CREATE OR REPLACE FUNCTION public.admin_record_order_claim_reshipment(p_claim_id uuid, p_carrier text, p_tracking_number text, p_items jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid:=(select auth.uid()); selected_order uuid; order_status public.order_status;
  claim public.order_cancellation_requests; item record; selected_variant uuid; source_variant uuid;
  variant public.goods_variants; carrier text:=nullif(btrim(p_carrier),''); tracking text:=nullif(btrim(p_tracking_number),'');
  selections jsonb; requested jsonb; shipped_items jsonb;
begin
  perform private.require_operator_capability('sales.manage',false);

  if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required'; end if;
  if carrier is null or tracking is null or tracking!~'^[A-Z0-9]{8,30}$' then raise check_violation using message='invalid reshipment tracking'; end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>1000 then raise check_violation using message='invalid reshipment items'; end if;
  for requested in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(requested) is distinct from 'object' or not(requested ?& array['orderItemId','variantId'])
      or (select count(*) from jsonb_object_keys(requested))<>2
      or (requested->>'orderItemId') is null or (requested->>'variantId') is null
      or requested->>'orderItemId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or requested->>'variantId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then raise check_violation using message='invalid reshipment items'; end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(p_items) x group by (x->>'orderItemId')::uuid having count(*)>1) then
    raise check_violation using message='invalid reshipment items';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('orderItemId',(x->>'orderItemId')::uuid,'variantId',(x->>'variantId')::uuid)
    order by (x->>'orderItemId')::uuid),'[]') into selections from jsonb_array_elements(p_items) x;
  select order_id into selected_order from public.order_cancellation_requests where id=p_claim_id;
  if not found then raise no_data_found using message='claim_not_found'; end if;
  -- Cancellation, payment finalization and claim operations all lock order first.
  select status into order_status from public.orders where id=selected_order for update;
  select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
  if claim.claim_type<>'exchange' then raise exception using message='claim_type_has_no_reshipment'; end if;
  perform private.lock_goods_stock_successor_topology();
  if exists(select 1 from private.group_claim_reshipment_receipts where claim_id=p_claim_id)
    or (claim.stage<>'completed' and (
      exists(select 1 from public.order_items oi cross join lateral private.order_item_physical_unit(oi.id) unit
        where oi.order_id=selected_order and (unit.good_id<>oi.good_id
          or exists(select 1 from private.goods_stock_successors where source_variant_id=unit.variant_id)
          or exists(select 1 from private.goods_group_members where variant_id=unit.variant_id)
          or exists(select 1 from private.group_claim_reshipment_allocations where order_item_id=oi.id)))
      or exists(select 1 from jsonb_array_elements(selections) x join public.order_items oi on oi.id=(x->>'orderItemId')::uuid
        join public.goods_variants v on v.id=(x->>'variantId')::uuid where oi.good_id<>v.good_id))) then
    return private.record_group_claim_reshipment(p_claim_id,carrier,tracking,selections);
  end if;
  if claim.stage='completed' then
    if claim.reship_carrier=carrier and claim.reship_tracking_number=tracking and not exists(
      select 1 from jsonb_array_elements(selections) selected where not exists(
        select 1 from public.order_claim_reshipment_items shipped where shipped.claim_id=p_claim_id
          and shipped.order_item_id=(selected->>'orderItemId')::uuid and shipped.variant_id=(selected->>'variantId')::uuid))
      then return 'completed'; end if;
    raise unique_violation using message='reshipment_conflict';
  end if;
  perform private.assert_claim_collections_complete(p_claim_id);
  if claim.stage<>'collected' or order_status not in('delivered','done')
    or exists(select 1 from public.order_cancellation_claims where order_id=selected_order)
    then raise exception using message='claim_not_reshippable'; end if;
  if not exists(select 1 from public.shipping_carriers c where c.code=carrier and c.is_active) then raise check_violation using message='unknown shipping carrier'; end if;
  if exists(select 1 from jsonb_array_elements(selections) selected where not exists(
    select 1 from public.order_items oi where oi.id=(selected->>'orderItemId')::uuid and oi.order_id=selected_order)) then
    raise check_violation using message='invalid reshipment items';
  end if;
  perform 1 from public.goods g where g.id in(select good_id from public.order_items where order_id=selected_order) order by g.id for update;
  for item in select * from public.order_items where order_id=selected_order order by good_id,id loop
    source_variant:=private.order_item_stock_variant(item.id);
    select (selected->>'variantId')::uuid into selected_variant from jsonb_array_elements(selections) selected where (selected->>'orderItemId')::uuid=item.id;
    selected_variant:=coalesce(selected_variant,source_variant);
    select * into variant from public.goods_variants where id=selected_variant and good_id=item.good_id;
    if not found or (variant.archived_at is not null and selected_variant<>source_variant) then raise check_violation using message='reshipment_variant_unavailable'; end if;
    insert into public.order_claim_reshipment_items(claim_id,order_item_id,good_id,source_variant_id,variant_id,variant_name_snapshot,variant_code_snapshot,qty)
      values(p_claim_id,item.id,item.good_id,source_variant,selected_variant,variant.name,variant.code,item.qty);
  end loop;
  -- Net all returned/shipped options first. A two-line blue/red swap also works
  -- with no spare stock; every recovered unit belongs to this collected claim.
  for item in select changes.good_id,changes.variant_id,sum(changes.delta)::bigint delta from (
    select good_id,source_variant_id variant_id,qty::bigint delta from public.order_claim_reshipment_items where claim_id=p_claim_id
    union all select good_id,variant_id,-qty::bigint from public.order_claim_reshipment_items where claim_id=p_claim_id
  ) changes group by changes.good_id,changes.variant_id having sum(changes.delta)<>0 order by changes.good_id,delta desc,changes.variant_id loop
    perform private.change_goods_variant_stock(item.good_id,item.variant_id,item.delta::bigint);
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('orderItemId',order_item_id,'goodId',good_id,'sourceVariantId',source_variant_id,'variantId',variant_id,'qty',qty) order by order_item_id),'[]')
    into shipped_items from public.order_claim_reshipment_items where claim_id=p_claim_id;
  update public.order_cancellation_requests set stage='completed',reship_carrier=carrier,reship_tracking_number=tracking,
    reshipped_at=now(),completed_at=now(),updated_at=now() where id=p_claim_id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.claim_reshipped','order:'||selected_order::text,
    jsonb_build_object('claimId',p_claim_id,'claimType','exchange','from','collected','to','completed','carrier',carrier,'items',shipped_items));
  perform private.notify_order_claim(p_claim_id,'reshipped','교환 상품이 재출고됐어요','교환 상품을 새 운송장으로 발송했습니다.');
  return 'completed';
end $function$

-- Customer read is scoped to the actual recipient. Gift payer projections keep
-- their existing privacy contract (no recipient exchange fulfillment details).
create function public.get_my_order_claim_reshipment_items(p_order_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=auth.uid();result jsonb;
begin
 if actor is null or not exists(select 1 from public.orders o left join private.gift_intents gift on gift.order_id=o.id
  where o.id=p_order_id and ((gift.id is null and o.user_id=actor) or gift.recipient_id=actor)) then
  raise no_data_found using message='order_not_found';
 end if;
 result:=private.order_claim_reshipment_history(p_order_id);
 return result;
end;
$$

CREATE OR REPLACE FUNCTION private.gift_claim_context(p_actor uuid, p_gift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare gift private.gift_intents;claim public.order_cancellation_requests;purchase public.orders;own boolean;account private.claim_refund_accounts;begin
 select * into gift from private.gift_intents where id=p_gift_id and(p_actor=sender_id or p_actor=recipient_id);
 if not found or p_actor is null then return null;end if;
 select * into purchase from public.orders where id=gift.order_id;
 select * into claim from public.order_cancellation_requests where order_id=gift.order_id order by requested_at desc,id desc limit 1;
 own:=claim.id is not null and private.gift_claim_actor(claim.id)=p_actor;
 select * into account from private.claim_refund_accounts where claim_id=claim.id;
 return jsonb_build_object('giftId',gift.id,'isSender',p_actor=gift.sender_id,'isRecipient',p_actor=gift.recipient_id,
  'reshipmentHistory',case when p_actor=gift.recipient_id then private.order_claim_reshipment_history(gift.order_id) else '[]'::jsonb end,
  'canRequest',purchase.id is not null and private.order_all_items_delivered(purchase.id) and purchase.status<>'canceled'
    and not exists(select 1 from public.order_cancellation_requests where order_id=purchase.id and status in('requested','processing','needs_review')),
  'claim',case when claim.id is null then null else jsonb_build_object('id',claim.id,'type',claim.claim_type,'stage',claim.stage,'revision',claim.claim_revision,'requestedAt',claim.requested_at,
   'isRequester',own,'canWithdraw',own and private.order_claim_withdrawal_blocker(claim) is null,
   'refundAccountNeeded',p_actor=gift.sender_id and(purchase.payment_method='bank_transfer' or claim.stage='needs_review') and claim.claim_type<>'exchange' and claim.stage not in('completed','rejected','withdrawn') and(account.claim_id is null or account.purged_at is not null),
   'maskedRefundAccount',case when p_actor=gift.sender_id then account.masked_account else null end,
   'reshipCarrier',case when p_actor=gift.recipient_id then claim.reship_carrier else null end,
   'reshipTrackingNumber',case when p_actor=gift.recipient_id then claim.reship_tracking_number else null end) end);
end $function$

do $$declare fn regprocedure;begin
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='private' and p.proname=any(array['resolve_goods_stock_successor','claim_reshipment_items_read','order_item_physical_unit',
   'order_claim_reshipment_history','lock_goods_stock_successor_topology','apply_group_physical_stock_deltas','order_item_reshipment_options','record_group_claim_reshipment']) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',fn);
  execute format('grant execute on function %s to postgres',fn);
  perform private.register_operator_internal_contract(fn);
 end loop;
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='private' and p.proname=any(array['order_item_stock_variant','restore_order_item_supply',
   'gift_claim_context','admin_order_claim_detail_before_operational_fee','order_claim_type_change_blocker','order_claim_reason_blocker']) loop
  perform private.register_operator_internal_contract(fn);
 end loop;
end $$

create function private.assert_goods_group_common_write(p_good_id text,p_before jsonb,p_after jsonb) returns void
language plpgsql security invoker set search_path='' as $$
begin
 if p_before is not distinct from p_after then return;end if;
 if exists(select 1 from private.goods_group_members where good_id=p_good_id)
  and not exists(select 1 from private.goods_group_write_authorizations
   where transaction_id=txid_current() and good_id=p_good_id and actor_id=auth.uid()) then
  raise check_violation using message='goods_group_common_owned_by_group';
 end if;
end;
$$

create function private.guard_goods_group_common_information() returns trigger
language plpgsql security definer set search_path='' as $$
declare old_good text;new_good text;before_value jsonb;after_value jsonb;
begin
 if tg_op<>'INSERT' then old_good:=case when tg_table_name='goods' then to_jsonb(old)->>'id' else to_jsonb(old)->>'good_id' end;end if;
 if tg_op<>'DELETE' then new_good:=case when tg_table_name='goods' then to_jsonb(new)->>'id' else to_jsonb(new)->>'good_id' end;end if;
 if tg_table_name='goods' then
  before_value:=private.goods_group_common_public_fields(to_jsonb(old));after_value:=private.goods_group_common_public_fields(to_jsonb(new));
 elsif tg_table_name='goods_attribute_values' then
  before_value:=coalesce(to_jsonb(old)->'entries','[]');after_value:=coalesce(to_jsonb(new)->'entries','[]');
 elsif tg_table_name='goods_after_sales_content' then
  if tg_op<>'INSERT' then before_value:=jsonb_build_array(old.phone,old.guide,old.seller_special_notes);end if;
  if tg_op<>'DELETE' then after_value:=jsonb_build_array(new.phone,new.guide,new.seller_special_notes);end if;
 elsif tg_table_name='goods_size_charts' then
  if tg_op<>'INSERT' then before_value:=jsonb_build_array(old.enabled,old.chart);end if;
  if tg_op<>'DELETE' then after_value:=jsonb_build_array(new.enabled,new.chart);end if;
 elsif tg_table_name='goods_additional_categories' then
  if tg_op='INSERT' and exists(select 1 from public.goods_additional_categories where good_id=new.good_id and category_id=new.category_id) then return new;end if;
  if tg_op<>'INSERT' then before_value:=jsonb_build_array(old.good_id,old.category_id);end if;
  if tg_op<>'DELETE' then after_value:=jsonb_build_array(new.good_id,new.category_id);end if;
 end if;
 if old_good is not null then perform private.assert_goods_group_common_write(old_good,before_value,after_value);end if;
 if new_good is distinct from old_good then perform private.assert_goods_group_common_write(new_good,before_value,after_value);end if;
 if tg_op='DELETE' then return old;end if;return new;
end;
$$

create function public.admin_get_goods_group_common(p_group_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare current_group private.goods_groups;
begin
 if not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 select * into current_group from private.goods_groups where id=p_group_id and archived_at is null;
 if not found then return null;end if;
 return jsonb_build_object('group',private.goods_group_snapshot(p_group_id),'common',private.goods_group_common_identity(current_group.common_good_id),
  'afterSales',public.admin_get_goods_after_sales_content(current_group.common_good_id),'sizeChart',public.admin_get_goods_size_chart(current_group.common_good_id));
end;
$$

create function public.admin_save_goods_group_common(p_group_id uuid,p_expected_revision bigint,p_values jsonb,p_operation_id uuid,
 p_expected_actor_id uuid,p_expected_session_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare prior private.goods_group_operations;current_group private.goods_groups;target_ids text[];lock_ids text[];target_id text;item public.goods;
 expected_hash text;before_group jsonb;before_common jsonb;after_common jsonb;individual_before jsonb;individual_after jsonb;variant_before jsonb;variant_after jsonb;
 payload jsonb;source_paths text[];attribute_revision integer;child_revision integer;child_operation uuid;result jsonb;
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 perform private.validate_goods_group_common_values(p_values);
 if p_group_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision not between 1 and 9007199254740990 then
  raise invalid_parameter_value using message='invalid_goods_group_operation';end if;
 expected_hash:=encode(extensions.digest(jsonb_build_array('common',p_group_id,p_expected_revision,p_values)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('goods-group-operation:'||p_operation_id::text,0));
 select * into prior from private.goods_group_operations where operation_id=p_operation_id;
 if found then
  if prior.actor_id<>p_expected_actor_id or prior.session_id<>p_expected_session_id or prior.command<>'common'
   or prior.target_group_id is distinct from p_group_id or prior.expected_revision is distinct from p_expected_revision or prior.receipt is null then
   raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  if prior.receipt->>'state'='sealed' then return prior.receipt;end if;
  if prior.request_hash<>expected_hash then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  return prior.receipt;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 perform private.lock_catalog_category_tree();
 select * into current_group from private.goods_groups where id=p_group_id for update;
 if not found or current_group.archived_at is not null or current_group.revision<>p_expected_revision then
  raise sqlstate 'PT409' using message='goods_group_changed';end if;
 select array_agg(good_id order by good_id) into target_ids from private.goods_group_members where group_id=p_group_id;
 if cardinality(target_ids) not between 1 and 100 or not(current_group.common_good_id=any(target_ids)) then
  raise check_violation using message='goods_group_members_invalid';end if;
 select array_agg(distinct id order by id) into lock_ids from (
  select unnest(target_ids) id union select private.goods_aggregation_owner(id) from unnest(target_ids) id) all_goods;
 -- Existing normal editors acquire admin_good advisory before their goods row.
 -- Claim those locks without waiting before owning the union of goods rows.
 foreach target_id in array lock_ids loop
  if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||target_id,0)) then raise sqlstate 'PT409' using message='goods_group_retry';end if;
  if target_id=any(target_ids) and (not pg_try_advisory_xact_lock(hashtextextended('goods-after-sales-operation:'||md5('goods-group-common-after-sales:'||p_operation_id::text||':'||target_id)::uuid::text,0))
   or not pg_try_advisory_xact_lock(hashtextextended('goods-size-operation:'||md5('goods-group-common-size:'||p_operation_id::text||':'||target_id)::uuid::text,0))) then
   raise sqlstate 'PT409' using message='goods_group_retry';end if;
 end loop;
 perform 1 from public.goods where id=any(lock_ids) order by id for update nowait;
 if exists(select 1 from public.goods where id=any(target_ids) and archived_at is not null) then raise check_violation using message='goods_group_member_unavailable';end if;
 perform 1 from public.goods_variants where good_id=any(target_ids) order by id for update nowait;
 perform 1 from public.ips where id in(select ip_id from public.goods where id=any(target_ids) union select p_values#>>'{goods,ip_id}') order by id for share nowait;
 if not exists(select 1 from public.ips where id=p_values#>>'{goods,ip_id}' and archived_at is null) then
  raise check_violation using message='catalog_parent_archived';end if;
 before_group:=private.goods_group_snapshot(p_group_id);before_common:=private.goods_group_common_identity(current_group.common_good_id);
 if exists(select 1 from unnest(target_ids) id where private.goods_group_common_identity(id) is distinct from before_common) then
  raise check_violation using message='goods_group_common_mismatch';end if;
 select jsonb_object_agg(g.id,to_jsonb(g)-array['ip_id','type','category_id','name_en','notice_maker','notice_origin','notice_material','notice_size','notice_made_on',
  'notice_as_manager','notice_as_contact','description','description_format','description_image_paths','search_keywords','published_at','updated_at','kc_disclosures']) into individual_before
 from public.goods g where id=any(target_ids);
 select jsonb_agg(to_jsonb(v) order by v.id) into variant_before from public.goods_variants v where good_id=any(target_ids);
 insert into private.goods_group_operations(operation_id,actor_id,session_id,command,target_group_id,expected_revision,request_hash)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,'common',p_group_id,p_expected_revision,expected_hash);
 insert into private.goods_group_write_authorizations(transaction_id,good_id,actor_id)
 select txid_current(),id,p_expected_actor_id from unnest(target_ids) id;
 update public.goods set published_at=null where id=any(target_ids) and published_at is not null;
 -- Save and validate the common source first. Its new HTML images acquire their
 -- real single-use upload claim there before sealed copying to other members.
 for item in select * from public.goods where id=any(target_ids) order by (id=current_group.common_good_id) desc,id loop
  select coalesce(revision,0) into attribute_revision from public.goods_attribute_values where good_id=item.id;
  payload:=to_jsonb(item)||(p_values->'goods')||jsonb_build_object('previous_id',item.id,'id',item.id,'publish',false,
   'product_attributes',case when item.id=current_group.common_good_id then p_values->'attributes'
    else jsonb_set(p_values->'attributes','{expectedRevision}',to_jsonb(coalesce(attribute_revision,0))) end);
  if item.id<>current_group.common_good_id then
   insert into private.goods_artwork_copy_authorizations(transaction_id,target_good_id,source_good_id,actor_id,allowed_paths)
   values(txid_current(),item.id,current_group.common_good_id,p_expected_actor_id,
    array_remove(array[item.image_path,item.detail_image_path]||coalesce(item.gallery_paths,'{}')||coalesce(item.description_image_paths,'{}')||coalesce(source_paths,'{}'),null));
  end if;
  perform public.admin_save_good(payload);
  if item.id=current_group.common_good_id then select description_image_paths into source_paths from public.goods where id=item.id;end if;
  delete from private.goods_artwork_copy_authorizations where transaction_id=txid_current() and target_good_id=item.id and actor_id=p_expected_actor_id;
  select coalesce(revision,0) into child_revision from private.goods_after_sales_content where good_id=item.id;
  child_operation:=md5('goods-group-common-after-sales:'||p_operation_id::text||':'||item.id)::uuid;
  perform public.admin_save_goods_after_sales_content(item.id,coalesce(child_revision,0),child_operation,p_values->'afterSales');
  select coalesce(revision,0) into child_revision from private.goods_size_charts where good_id=item.id;
  child_operation:=md5('goods-group-common-size:'||p_operation_id::text||':'||item.id)::uuid;
  perform public.admin_save_goods_size_chart(item.id,coalesce(child_revision,0),child_operation,p_values->'sizeChart');
  perform private.invalidate_goods_kc_review(item.id,'goods_group_common_changed');
  update public.goods set kc_disclosures='[]' where id=item.id;
 end loop;
 after_common:=private.goods_group_common_identity(current_group.common_good_id);
 if exists(select 1 from unnest(target_ids) id where private.goods_group_common_identity(id) is distinct from after_common) then
  raise check_violation using message='goods_group_common_mismatch';end if;
 select jsonb_object_agg(g.id,to_jsonb(g)-array['ip_id','type','category_id','name_en','notice_maker','notice_origin','notice_material','notice_size','notice_made_on',
  'notice_as_manager','notice_as_contact','description','description_format','description_image_paths','search_keywords','published_at','updated_at','kc_disclosures']) into individual_after
 from public.goods g where id=any(target_ids);
 select jsonb_agg(to_jsonb(v) order by v.id) into variant_after from public.goods_variants v where good_id=any(target_ids);
 if individual_after is distinct from individual_before or variant_after is distinct from variant_before then
  raise check_violation using message='goods_group_individual_fields_changed';end if;
 update private.goods_groups set revision=revision+1,updated_at=clock_timestamp(),updated_by=p_expected_actor_id where id=p_group_id;
 result:=jsonb_build_object('state','completed','operationId',p_operation_id,'group',private.goods_group_snapshot(p_group_id));
 insert into private.goods_group_changes(group_id,operation_id,actor_id,revision,before_value,after_value)
 values(p_group_id,p_operation_id,p_expected_actor_id,p_expected_revision+1,before_group||jsonb_build_object('common',before_common),
  (result->'group')||jsonb_build_object('common',after_common));
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'catalog.goods_group.common_saved','goods_group:'||p_group_id::text,
  jsonb_build_object('before',before_common,'after',after_common,'goodIds',to_jsonb(target_ids),'allProductsUnpublished',true,'requiresKcReview',true));
 update private.goods_group_operations set receipt=result,completed_at=clock_timestamp() where operation_id=p_operation_id;
 delete from private.goods_group_write_authorizations where transaction_id=txid_current() and actor_id=p_expected_actor_id and good_id=any(target_ids);
 return result;
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$$

-- Preserve an existing sealed cross-product copy authorization while the
-- normal description wrapper temporarily preserves its own old image slots.
CREATE OR REPLACE FUNCTION private.admin_save_good_before_discount_display(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid:=(select auth.uid());
  previous_good public.goods;
  description_value text:=nullif(btrim(target_good->>'description',E' \t\n\r\f\v'),'');
  format_value text;
  image_paths text[];
  saved jsonb;
  before_value jsonb;
  after_value jsonb;
begin
  if v_actor_id is null then raise invalid_authorization_specification using message='auth_required'; end if;
  if not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
  if jsonb_typeof(target_good) is distinct from 'object' then raise invalid_parameter_value using message='invalid_good'; end if;
  -- Match category assignment and cloning: tree before product advisory/row.
  -- Taking a product lock first would deadlock with those existing writers.
  perform private.lock_catalog_category_tree();
  if nullif(target_good->>'previous_id','') is not null then
    perform pg_advisory_xact_lock(hashtextextended('admin_good:'||(target_good->>'previous_id'),0));
    select * into previous_good from public.goods where id=target_good->>'previous_id' for update;
    if not found then raise no_data_found using message='catalog_record_missing'; end if;
  end if;
  format_value:=case when target_good ? 'description_format' then target_good->>'description_format' else coalesce(previous_good.description_format,'plain') end;
  if format_value is null or format_value not in ('plain','html') then raise check_violation using message='goods_description_format'; end if;
  -- Keep legacy plain rows and their clone path compatible. The existing form
  -- still caps newly edited plain text at 2,000; this new DB cap is HTML-only.
  if format_value='html' and char_length(description_value)>30000 then
    raise check_violation using message='goods_description_length';
  end if;
  if target_good ? 'description_image_paths' then
    if jsonb_typeof(target_good->'description_image_paths') is distinct from 'array' then raise check_violation using message='goods_description_images'; end if;
    if jsonb_array_length(target_good->'description_image_paths')>20
      or exists(select 1 from jsonb_array_elements(target_good->'description_image_paths') item where jsonb_typeof(item)<>'string' or item='""'::jsonb)
    then raise check_violation using message='goods_description_images'; end if;
    image_paths:=array(select jsonb_array_elements_text(target_good->'description_image_paths'));
  else
    image_paths:=case when format_value='html' and description_value is not distinct from previous_good.description then coalesce(previous_good.description_image_paths,'{}') else '{}' end;
  end if;
  if format_value='plain' and cardinality(image_paths)>0 then raise check_violation using message='goods_description_images'; end if;
  before_value:=jsonb_build_object('format',coalesce(previous_good.description_format,'plain'),'description',previous_good.description,'imagePaths',coalesce(previous_good.description_image_paths,'{}'));
  saved:=private.admin_save_good_before_description(target_good-'description_format'-'description_image_paths');
  if previous_good.id is not null then
    -- The lower writer may have removed the old main/gallery/detail slot or
    -- renamed this draft. Preserve only this locked source row's verified paths
    -- across the final HTML update. The destination now exists under saved.id,
    -- so no authorization FK ever points at an intermediate or another good.
    insert into private.goods_artwork_copy_authorizations(transaction_id,target_good_id,source_good_id,actor_id,allowed_paths)
      values(txid_current(),saved->>'id',saved->>'id',v_actor_id,
        array_remove(array[previous_good.image_path,previous_good.detail_image_path]
          || coalesce(previous_good.gallery_paths,'{}') || coalesce(previous_good.description_image_paths,'{}'),null))
      on conflict(transaction_id,target_good_id) do nothing;
  end if;
  update public.goods set description_format=format_value,description_image_paths=image_paths where id=saved->>'id';
  if previous_good.id is not null then
    delete from private.goods_artwork_copy_authorizations permission
      where permission.transaction_id=txid_current() and permission.target_good_id=saved->>'id'
        and permission.source_good_id=saved->>'id' and permission.actor_id=v_actor_id;
  end if;
  after_value:=jsonb_build_object('format',format_value,'description',description_value,'imagePaths',image_paths);
  if before_value is distinct from after_value then
    insert into public.audit_log(actor_id,action,target,diff)
      values(v_actor_id,'admin.good.description_saved','goods:'||(saved->>'id'),jsonb_build_object('before',before_value,'after',after_value));
  end if;
  return saved;
end $function$

do $$declare fn regprocedure;begin
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='private' and p.proname=any(array['goods_group_common_public_fields','assert_goods_group_common_write','guard_goods_group_common_information','validate_goods_group_common_values']) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',fn);
  execute format('grant execute on function %s to postgres',fn);
  perform private.register_operator_internal_contract(fn);
 end loop;
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.proname=any(array['admin_get_goods_group_editor_ownership','admin_get_goods_group_common','admin_save_goods_group_common']) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',fn);
  execute format('grant execute on function %s to authenticated',fn);
 end loop;
end $$

create function private.contact_keys(p_value jsonb,p_keys text[]) returns boolean language sql immutable set search_path='' as $$
 select coalesce(jsonb_typeof(p_value)='object' and p_value ?& p_keys and (select count(*) from jsonb_object_keys(case when jsonb_typeof(p_value)='object' then p_value else '{}'::jsonb end))=cardinality(p_keys),false);
$$

create function private.contact_uuid(p_value jsonb) returns boolean language sql immutable set search_path='' as $$
 select coalesce(jsonb_typeof(p_value)='string' and p_value#>>'{}'~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',false);
$$

create function private.contact_digest(p_value jsonb) returns boolean language sql immutable set search_path='' as $$
 select coalesce(jsonb_typeof(p_value)='string' and p_value#>>'{}'~'^[0-9a-f]{64}$',false);
$$

create function private.contact_key_version(p_value jsonb) returns boolean language sql immutable set search_path='' as $$
 select coalesce(jsonb_typeof(p_value)='string' and p_value#>>'{}'~'^[A-Za-z0-9_-]{1,64}$',false);
$$

create function private.contact_base64url(p_value jsonb,p_bytes integer,p_max integer) returns boolean language plpgsql immutable set search_path='' as $$
declare value text;decoded bytea;begin
 if jsonb_typeof(p_value) is distinct from 'string' then return false;end if;value:=p_value#>>'{}';
 if length(value)>p_max or value!~'^[A-Za-z0-9_-]*$' or length(value)%4=1 then return false;end if;
 decoded:=decode(translate(value,'-_','+/')||repeat('=',(4-length(value)%4)%4),'base64');
 return(p_bytes is null or octet_length(decoded)=p_bytes) and rtrim(translate(replace(encode(decoded,'base64'),E'\n',''),'+/','-_'),'=')=value;
 exception when others then return false;end $$

create function private.contact_parties(p_order uuid) returns uuid[] language sql stable security definer set search_path='' as $$
 select array_remove(array[o.user_id,g.recipient_id],null) from public.orders o left join private.gift_intents g on g.order_id=o.id where o.id=p_order;
$$

create function private.contact_subject(p_order uuid) returns uuid language sql stable security definer set search_path='' as $$
 select case when g.id is not null then g.recipient_id else o.user_id end from public.orders o left join private.gift_intents g on g.order_id=o.id where o.id=p_order;
$$

create function private.contact_require_identity(p_actor uuid,p_session uuid,p_capability text,p_admin boolean,p_parties uuid[],p_pii boolean) returns void
language plpgsql volatile security definer set search_path='' as $$
begin
 if auth.role() is distinct from 'service_role' or p_actor is null or p_session is null then raise insufficient_privilege using message='auth_changed';end if;
 perform private.gift_lock_subjects(array_append(coalesce(p_parties,'{}'),p_actor));
 -- Membership updates use the same subject fence. Keep that membership locked
 -- through completion even when a caller is retrying a historical operation.
 perform private.lock_operator_subjects(array[p_actor]);
 perform 1 from auth.sessions where id=p_session and user_id=p_actor and(not_after is null or not_after>clock_timestamp()) for share;
 if not found or exists(select 1 from public.profiles where id=p_actor and suspended_at is not null)
 or exists(select 1 from private.account_action_fences where subject_user_id=p_actor)
 or(p_capability is not null and not private.has_operator_capability(p_actor,p_capability,p_admin)) then
 raise insufficient_privilege using message='auth_changed';end if;
 if p_pii and exists(select 1 from private.account_action_fences where subject_user_id=any(p_parties)) then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
end $$

create function private.contact_lock_scope(p_order uuid,p_claim uuid,p_parties uuid[]) returns public.order_cancellation_requests
language plpgsql volatile security definer set search_path='' as $$
declare claim public.order_cancellation_requests;begin
 perform 1 from public.orders where id=p_order for update;
 if not found or private.contact_parties(p_order) is distinct from p_parties then raise sqlstate 'PT409' using message='claim_contact_changed';end if;
 perform 1 from public.order_shipments where order_id=p_order order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim and order_id=p_order for update;
 if not found or claim.claim_type not in('return','exchange') then raise no_data_found using message='claim_not_found';end if;
 perform 1 from public.order_claim_collections where claim_id=p_claim order by shipment_id for update;
 perform 1 from private.order_claim_contact_retention_cases where claim_id=p_claim order by case_ref for update;
 perform 1 from private.order_claim_contact_plans where claim_id=p_claim order by target for update;
 return claim;
end $$

create function private.contact_runtime() returns void language plpgsql volatile security definer set search_path='' as $$begin
 perform singleton from private.order_claim_contact_runtime where singleton and enabled for share;
 if not found then raise sqlstate '55000' using message='feature_disabled';end if;
end $$

-- This gate deliberately uses actual fulfillment evidence even for a done order.
-- Canceled orders may have completed return/refund duties and must not stay
-- permanently blocked by order_all_items_delivered's top-level status predicate.
create function private.contact_order_obligations(p_order uuid) returns text language plpgsql stable security definer set search_path='' as $$
declare purchase public.orders;begin
 select * into purchase from public.orders where id=p_order;if not found then return 'operational_unknown';end if;
 if purchase.status not in('delivered','done','canceled') or exists(select 1 from public.order_cancellation_requests where order_id=p_order and status in('requested','processing','needs_review'))
 or exists(select 1 from public.order_cancellation_claims where order_id=p_order)
 or exists(select 1 from public.payments p where p.ref_id=p_order and p.purpose='order' and p.status='pending')
 or exists(select 1 from public.payment_attempts where ref_id=p_order and purpose='order' and(state in('prepared','confirming','unknown','needs_review') or(state='approved' and payment_id is null)))
 or exists(select 1 from public.refunds r join public.payments p on p.id=r.payment_id where p.ref_id=p_order and p.purpose='order' and r.status<>'done') then return 'operational_pending';end if;
 if purchase.status in('delivered','done') and not private.order_all_items_delivered(p_order) then return 'operational_unknown';end if;
 if purchase.status='canceled' and(not exists(select 1 from public.order_items where order_id=p_order)
 or exists(select 1 from public.order_items i where i.order_id=p_order and coalesce((select sum(l.qty) from public.order_shipment_items l join public.order_shipments s on s.id=l.shipment_id
 where l.order_item_id=i.id and l.order_id=p_order and s.shipped_at is not null and s.delivered_at is not null),0)<>i.qty)) then return 'operational_unknown';end if;
 if purchase.status='canceled' and(not exists(select 1 from public.order_cancellation_requests c where c.order_id=p_order and c.claim_type='return' and c.stage='completed' and c.collected_at is not null and c.completed_at is not null)
 or(purchase.total>0 and(not exists(select 1 from public.payments p join public.refunds r on r.payment_id=p.id where p.ref_id=p_order and p.purpose='order' and p.status='refunded' and r.status='done' and r.completed_at is not null)
 or exists(select 1 from public.payments p where p.ref_id=p_order and p.purpose='order' and p.status in('pending','paid'))))) then return 'operational_unknown';end if;
 if exists(select 1 from public.order_cancellation_requests c where c.order_id=p_order and c.claim_type='exchange' and c.stage='completed'
 and(c.reshipped_at is null or c.reship_carrier is null or c.reship_tracking_number is null or c.reship_delivered_at is null or c.reship_delivered_by is null or c.reship_delivery_evidence is null))
 or exists(select 1 from public.order_cancellation_requests c where c.order_id=p_order and c.stage='completed' and c.collection_required and c.collected_at is null)
 or exists(select 1 from public.order_cancellation_requests c join public.order_claim_collections x on x.claim_id=c.id where c.order_id=p_order and c.stage='completed' and c.collection_required and(x.collected_at is null or x.collected_by is null or x.evidence is null))
 or exists(select 1 from public.refunds r join public.payments p on p.id=r.payment_id where p.ref_id=p_order and r.status='done' and r.completed_at is null)
 then return 'operational_unknown';end if;
 return null;
end $$

create function private.contact_retention(p_claim uuid,p_now timestamptz) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare c public.order_cancellation_requests;state text;ended timestamptz;base_at timestamptz;effective timestamptz;hold_until timestamptz;active_count integer;expired_count integer;
begin
 select * into c from public.order_cancellation_requests where id=p_claim;
 state:=private.contact_order_obligations(c.order_id);
 if state is null then
  ended:=case c.stage when 'completed' then c.completed_at when 'rejected' then c.decided_at when 'withdrawn' then c.withdrawn_at else null end;
  if c.stage not in('completed','rejected','withdrawn') then state:='operational_pending';elsif ended is null or not isfinite(ended) or ended>p_now then state:='operational_unknown';end if;
 end if;
 select count(*) filter(where r.state='held' and r.retain_until>p_now),count(*) filter(where r.state='held' and r.retain_until<=p_now),max(r.retain_until) filter(where r.state='held' and r.retain_until>p_now)
 into active_count,expired_count,hold_until from private.order_claim_contact_retention_cases r where r.claim_id=p_claim;
 if state is null then
  select greatest(ended,(select max(delivered_at) from public.order_shipments where order_id=c.order_id),
   (select max(greatest(completed_at,reship_delivered_at,decided_at,withdrawn_at,operational_fee_confirmed_at)) from public.order_cancellation_requests where order_id=c.order_id),
   (select max(r.completed_at) from public.refunds r join public.payments p on p.id=r.payment_id where p.ref_id=c.order_id and p.purpose='order'),
   (select max(case_closed_at) from private.order_claim_contact_retention_cases where claim_id=p_claim and legal_basis='dispute_resolution')) into ended;
  base_at:=ended+interval '30 days';effective:=greatest(base_at,hold_until);
  state:=case when effective<=p_now then 'due' when hold_until>base_at then 'held' else 'not_due' end;
 end if;
 if exists(select 1 from private.order_claim_contact_plans where claim_id=p_claim and purged_at is not null) then state:='purged';end if;
 return jsonb_build_object('state',state,'purposeEndedAt',ended,'basePurgeAt',base_at,'effectivePurgeAt',effective,'activeHoldCount',active_count,'expiredHoldCount',expired_count);
end $$

create function private.contact_source_address(p_raw jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare field text;value text;address jsonb;begin
 if jsonb_typeof(p_raw) is distinct from 'object' or not p_raw ?& array['recipientName','phone','postalCode','address1'] then return null;end if;
 foreach field in array array['recipientName','phone','postalCode','address1','address2'] loop
  if field='address2' and(p_raw->field is null or p_raw->field='null') then continue;end if;
  if jsonb_typeof(p_raw->field) is distinct from 'string' or p_raw->>field~('['||chr(1)||'-'||chr(31)||chr(127)||'-'||chr(159)||']') then return null;end if;
 end loop;
 if p_raw->>'phone'!~'^[0-9 ()+-]+$' then return null;end if;
 address:=jsonb_build_object('recipientName',private.contact_trim(p_raw->>'recipientName'),
 'phone',regexp_replace(p_raw->>'phone','[ ()+-]','','g'),'postalCode',p_raw->>'postalCode','address1',p_raw->>'address1',
 'address2',private.contact_trim(coalesce(p_raw->>'address2','')));
 if char_length(address->>'recipientName') not between 1 and 50 or address->>'phone'!~'^[0-9]{8,15}$'
 or char_length(address->>'postalCode') not between 1 and 20 or private.contact_trim(address->>'postalCode')=''
 or char_length(address->>'address1') not between 1 and 200 or private.contact_trim(address->>'address1')='' or char_length(address->>'address2')>200 then return null;end if;
 return address;
end $$

create function private.contact_target(p_order uuid,p_claim uuid,p_target text,p_access boolean,p_due jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare c public.order_cancellation_requests;plan private.order_claim_contact_plans;raw jsonb;address jsonb;source jsonb;kind text;source_id uuid;source_revision text;
 result jsonb:=jsonb_build_object('target',p_target,'piiState','unavailable','source',null,'referenceOnly',false,'sourceAddress',null,'plan',null,'unavailableReason','source_unavailable');
begin
 select * into c from public.order_cancellation_requests where id=p_claim and order_id=p_order;
 if p_target='reshipment' and c.claim_type<>'exchange' then return result||jsonb_build_object('piiState','not_applicable','unavailableReason',null);end if;
 if not p_access then return result||jsonb_build_object('piiState','restricted','unavailableReason',null);end if;
 -- Do not read a source address or ciphertext until lifecycle gates pass.
 if p_due->>'state'='purged' then return result||jsonb_build_object('piiState','purged','unavailableReason',null);end if;
 if p_due->>'state'='due' then return result||jsonb_build_object('unavailableReason','retention_due');end if;
 select * into plan from private.order_claim_contact_plans where claim_id=p_claim and target=p_target;
 if found then
  if plan.purged_at is not null then return result||jsonb_build_object('piiState','purged','unavailableReason',null);end if;
  return result||jsonb_build_object('piiState','available','unavailableReason',null,'plan',plan.sealed_plan,
   'source',jsonb_build_object('sourceKind','contact_plan','sourceId',plan.id,'sourceRevision',null,'sourceFingerprint',null,'planRevision',plan.revision,'piiVersion',plan.pii_version));
 end if;
 if p_target='collection' then
  select payload->'collectionAddress' into raw from private.seller_order_claim_intakes where claim_id=p_claim;
  if found then kind:='seller_intake';source_id:=p_claim;end if;
 end if;
 if kind is null then
  source:=private.order_delivery_snapshot(p_order);raw:=source->'address';kind:='order_delivery';source_id:=p_order;source_revision:=source->>'addressRevision';
  if source_revision is null or source_revision!~'^(0|[1-9][0-9]*)$' then return result;end if;
 end if;
 address:=private.contact_source_address(raw);if address is null then return result;end if;
 source:=jsonb_build_object('sourceKind',kind,'sourceId',source_id,'sourceRevision',source_revision,'planRevision',0,'piiVersion',null,
 'sourceFingerprint',encode(extensions.digest(convert_to(jsonb_build_array('claim-contact-source-v1',p_order,p_claim,p_target,kind,source_id,source_revision,
 raw->>'recipientName',raw->>'phone',raw->>'postalCode',raw->>'address1',coalesce(raw->>'address2',''))::text,'UTF8'),'sha256'),'hex'));
 return result||jsonb_build_object('piiState','available','unavailableReason',null,'source',source,'sourceAddress',address,'referenceOnly',kind='order_delivery');
end $$

create function private.contact_blocker(p_claim public.order_cancellation_requests,p_target text,p_command text) returns text
language plpgsql stable security definer set search_path='' as $$
declare stage text:=case when p_claim.stage='on_hold' then p_claim.held_from else p_claim.stage end;intake jsonb;row jsonb;
begin
 if p_claim.claim_type not in('return','exchange') or(p_target='reshipment' and p_claim.claim_type<>'exchange') then return 'not_applicable';end if;
 if exists(select 1 from public.orders where id=p_claim.order_id and status='canceled') or exists(select 1 from public.order_cancellation_claims where order_id=p_claim.order_id)
 or exists(select 1 from public.refunds r join public.payments p on p.id=r.payment_id where p.ref_id=p_claim.order_id and p.purpose='order') then return 'financial_state';end if;
 if stage is null or stage not in('requested','in_review','collecting','collected') then return 'claim_stage';end if;
 if p_target='reshipment' then
  if p_claim.reshipped_at is not null or p_claim.reship_carrier is not null or p_claim.reship_tracking_number is not null or p_claim.reship_delivered_at is not null
  or exists(select 1 from private.claim_reshipment_items_read(p_claim.id)) or exists(select 1 from private.group_claim_reshipment_receipts where claim_id=p_claim.id)
  or exists(select 1 from private.order_claim_reshipment_destinations where claim_id=p_claim.id) then return 'reshipment_started';end if;
  if p_command='reshipment' then
   if p_claim.stage<>'collected' then return 'claim_stage';end if;
   begin perform private.assert_claim_collections_complete(p_claim.id);exception when others then return 'collection_incomplete';end;
  end if;
 else
  if stage not in('requested','in_review') or p_claim.collecting_at is not null or p_claim.collected_at is not null
  or exists(select 1 from public.order_claim_collections where claim_id=p_claim.id and(collected_at is not null or collected_by is not null or evidence is not null)) then return 'collection_started';end if;
  select payload->'collections' into intake from private.seller_order_claim_intakes where claim_id=p_claim.id;
  if found then
   if jsonb_typeof(intake) is distinct from 'array' or jsonb_array_length(intake)=0 then return 'collection_unknown';end if;
   for row in select value from jsonb_array_elements(intake) loop
    if not private.contact_keys(row,array['shipmentId','method','carrier','trackingNumber','note']) or not private.contact_uuid(row->'shipmentId')
    or row->>'method' is distinct from 'not_requested' or row->'carrier' is distinct from 'null'::jsonb or row->'trackingNumber' is distinct from 'null'::jsonb then return 'collection_started';end if;
   end loop;
  end if;
 end if;
 return null;
end $$

create function public.service_get_order_claim_contact_context(p_order_id uuid,p_claim_id uuid,p_actor_id uuid,p_session_id uuid,p_target text,p_command text) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare parties uuid[]:=private.contact_parties(p_order_id);c public.order_cancellation_requests;view jsonb;due jsonb;blocker text;begin
 if p_target is null or p_target not in('collection','reshipment') or p_command is null or p_command not in('change','reshipment') or(p_command='reshipment' and p_target<>'reshipment') then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 perform private.contact_require_identity(p_actor_id,p_session_id,'sales.manage',false,parties,true);
 c:=private.contact_lock_scope(p_order_id,p_claim_id,parties);perform private.contact_runtime();
 due:=private.contact_retention(p_claim_id,clock_timestamp());view:=private.contact_target(p_order_id,p_claim_id,p_target,true,due);
 blocker:=private.contact_blocker(c,p_target,p_command);
 if view->>'piiState'<>'available' then blocker:=coalesce(view->>'unavailableReason',view->>'piiState');end if;
 return jsonb_build_object('orderId',p_order_id,'claimId',p_claim_id,'target',p_target,'command',p_command,'claimType',c.claim_type,'claimRevision',c.claim_revision,'allowed',blocker is null,'blocker',blocker,'current',view);
end $$

create function private.contact_operation_scope(p_op private.order_claim_contact_operations,p_order uuid,p_claim uuid,p_actor uuid,p_session uuid,p_command text,p_target text,p_type text,p_revision integer) returns void
language plpgsql immutable set search_path='' as $$begin
 if (p_op.order_id,p_op.claim_id,p_op.actor_id,p_op.session_id,p_op.command,p_op.target,p_op.expected_claim_type,p_op.expected_claim_revision)
 is distinct from(p_order,p_claim,p_actor,p_session,p_command,p_target,p_type,p_revision) then raise unique_violation using message='claim_contact_operation_conflict';end if;
end $$

create function private.contact_operation_input(p_operation uuid,p_command text,p_target text,p_type text,p_revision integer) returns void language plpgsql immutable set search_path='' as $$begin
 if p_operation is null or p_command is null or p_command not in('change','reshipment') or p_target is null or p_target not in('collection','reshipment')
 or p_type is null or p_type not in('return','exchange') or p_revision is null or p_revision<0 or(p_target='reshipment' and p_type<>'exchange')
 or(p_command='reshipment' and p_target<>'reshipment') then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
end $$

create function public.service_read_order_claim_contact_operation(p_order_id uuid,p_claim_id uuid,p_actor_id uuid,p_session_id uuid,p_operation_id uuid,p_command text,p_target text,p_expected_claim_type text,p_expected_claim_revision integer,p_seal_if_absent boolean) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare parties uuid[]:=private.contact_parties(p_order_id);op private.order_claim_contact_operations;c public.order_cancellation_requests;begin
 perform private.contact_operation_input(p_operation_id,p_command,p_target,p_expected_claim_type,p_expected_claim_revision);
 if p_seal_if_absent is null then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 perform private.contact_require_identity(p_actor_id,p_session_id,'sales.manage',false,parties,false);
 perform pg_advisory_xact_lock(hashtextextended('claim-contact-operation:'||p_operation_id,0));
 -- Scope locking validates current relationship but never fetches PII.
 c:=private.contact_lock_scope(p_order_id,p_claim_id,parties);
 select id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,result_claim_revision,
 state,changed_fields,null::text,hmac_key_version,null::jsonb,created_at,purged_at into op
 from private.order_claim_contact_operations where id=p_operation_id;
 if found then perform private.contact_operation_scope(op,p_order_id,p_claim_id,p_actor_id,p_session_id,p_command,p_target,p_expected_claim_type,p_expected_claim_revision);
 elsif p_seal_if_absent then
  insert into private.order_claim_contact_operations(id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,state)
  values(p_operation_id,p_actor_id,p_session_id,p_order_id,p_claim_id,p_command,p_target,p_expected_claim_type,p_expected_claim_revision,'sealed') returning * into op;
 end if;
 return jsonb_build_object('receipt',case when op.id is null then null else private.contact_operation_receipt(op) end,'hmacKeyVersion',op.hmac_key_version);
end $$

create function private.contact_assert_context(p_claim public.order_cancellation_requests,p_target text,p_command text,p_type text,p_revision integer,p_expected jsonb) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare view jsonb;due jsonb;begin
 if p_claim.claim_type<>p_type or p_claim.claim_revision<>p_revision then raise sqlstate 'PT409' using message='claim_contact_changed';end if;
 perform private.contact_runtime();due:=private.contact_retention(p_claim.id,clock_timestamp());
 if due->>'state'='purged' then raise sqlstate 'PT410' using message='claim_contact_purged';end if;
 if due->>'state'='due' then raise sqlstate 'PT410' using message='claim_contact_retention_due';end if;
 if private.contact_blocker(p_claim,p_target,p_command) is not null then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
 view:=private.contact_target(p_claim.order_id,p_claim.id,p_target,true,due);
 if view->>'piiState'<>'available' then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
 if not private.contact_keys(p_expected,array['sourceKind','sourceId','sourceRevision','sourceFingerprint','planRevision','piiVersion','addressHmac','addressHmacKeyVersion'])
 or not private.contact_digest(p_expected->'addressHmac') or not private.contact_key_version(p_expected->'addressHmacKeyVersion') then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 if p_expected-array['addressHmac','addressHmacKeyVersion'] is distinct from view->'source' then raise sqlstate 'PT409' using message='claim_contact_changed';end if;
 return view;
end $$

create function public.service_change_order_claim_contact(p_order_id uuid,p_claim_id uuid,p_actor_id uuid,p_session_id uuid,p_operation_id uuid,p_target text,p_expected_claim_type text,p_expected_claim_revision integer,p_expected_context jsonb,p_sealed_change jsonb,p_request_hmac text,p_hmac_key_version text,p_confirmed boolean) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare parties uuid[]:=private.contact_parties(p_order_id);op private.order_claim_contact_operations;c public.order_cancellation_requests;view jsonb;plan jsonb;hist jsonb;fields text[];result_revision integer;old_plan private.order_claim_contact_plans;begin
 perform private.contact_operation_input(p_operation_id,'change',p_target,p_expected_claim_type,p_expected_claim_revision);
 perform private.contact_require_identity(p_actor_id,p_session_id,'sales.manage',false,parties,false);
 perform pg_advisory_xact_lock(hashtextextended('claim-contact-operation:'||p_operation_id,0));
 c:=private.contact_lock_scope(p_order_id,p_claim_id,parties);
 select id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,result_claim_revision,
 state,changed_fields,request_hmac,hmac_key_version,null::jsonb,created_at,purged_at into op
 from private.order_claim_contact_operations where id=p_operation_id;
 if found then
  perform private.contact_operation_scope(op,p_order_id,p_claim_id,p_actor_id,p_session_id,'change',p_target,p_expected_claim_type,p_expected_claim_revision);
  if op.state='sealed' then raise sqlstate 'PT409' using message='claim_contact_operation_sealed';end if;
  if op.purged_at is not null then raise sqlstate 'PT410' using message='claim_contact_purged';end if;
  if op.request_hmac is distinct from p_request_hmac or op.hmac_key_version is distinct from p_hmac_key_version then raise unique_violation using message='claim_contact_operation_conflict';end if;
  return private.contact_operation_receipt(op);
 end if;
 if exists(select 1 from private.account_action_fences where subject_user_id=any(parties)) then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
 if p_confirmed is distinct from true or not private.contact_digest(to_jsonb(p_request_hmac)) or not private.contact_key_version(to_jsonb(p_hmac_key_version))
 or not private.contact_keys(p_sealed_change,array['effect','changedFields','beforeAddressHmac','afterAddressHmac','addressHmacKeyVersion','plan','history'])
 or not private.contact_digest(p_sealed_change->'beforeAddressHmac') or not private.contact_digest(p_sealed_change->'afterAddressHmac')
 or not private.contact_key_version(p_sealed_change->'addressHmacKeyVersion') or jsonb_typeof(p_sealed_change->'changedFields') is distinct from 'array'
 or jsonb_typeof(p_sealed_change->'effect') is distinct from 'string' or p_sealed_change->>'effect' not in('change','noop') then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 fields:=array(select jsonb_array_elements_text(p_sealed_change->'changedFields'));
 if cardinality(fields)>3 or fields is distinct from array(select f from unnest(array['recipientName','phone','address2']) f where f=any(fields)) then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 view:=private.contact_assert_context(c,p_target,'change',p_expected_claim_type,p_expected_claim_revision,p_expected_context);
 if p_sealed_change->>'effect'='noop' then
  if fields<>'{}' or p_sealed_change->'plan' is distinct from 'null'::jsonb or p_sealed_change->'history' is distinct from 'null'::jsonb or p_sealed_change->'beforeAddressHmac' is distinct from p_sealed_change->'afterAddressHmac' then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
  result_revision:=c.claim_revision;
 else
  plan:=p_sealed_change->'plan';hist:=p_sealed_change->'history';
  if cardinality(fields)=0 or not private.contact_plan_envelope(plan) or not private.contact_history_envelope(hist)
   or plan->'addressHmac' is distinct from p_sealed_change->'afterAddressHmac' or plan->'addressHmacKeyVersion' is distinct from p_sealed_change->'addressHmacKeyVersion'
   or plan->'keyVersion' is distinct from hist->'keyVersion'
   or p_sealed_change->'beforeAddressHmac'=p_sealed_change->'afterAddressHmac' then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
  select * into old_plan from private.order_claim_contact_plans where claim_id=p_claim_id and target=p_target;
  if (old_plan.id is not null and(old_plan.id is distinct from(plan->>'planId')::uuid or old_plan.pii_version=(plan->>'piiVersion')::uuid))
   or exists(select 1 from private.order_claim_contact_operations where claim_id=p_claim_id and target=p_target and history->>'piiVersion'=plan->>'piiVersion') then raise sqlstate 'PT409' using message='claim_contact_changed';end if;
  insert into private.order_claim_contact_plans(id,order_id,claim_id,target,revision,pii_version,sealed_plan,source_kind,source_id,source_revision,last_operation_id)
  values((plan->>'planId')::uuid,p_order_id,p_claim_id,p_target,1,(plan->>'piiVersion')::uuid,plan,coalesce(old_plan.source_kind,view#>>'{source,sourceKind}'),coalesce(old_plan.source_id,(view#>>'{source,sourceId}')::uuid),case when old_plan.id is not null then old_plan.source_revision else view#>>'{source,sourceRevision}' end,p_operation_id)
  on conflict(claim_id,target) do update set revision=private.order_claim_contact_plans.revision+1,pii_version=excluded.pii_version,sealed_plan=excluded.sealed_plan,last_operation_id=p_operation_id,updated_at=clock_timestamp();
  update public.order_cancellation_requests set updated_at=clock_timestamp() where id=p_claim_id returning claim_revision into result_revision;
  insert into public.audit_log(actor_id,action,target,diff) values(p_actor_id,'admin.order.claim_contact_changed','order:'||p_order_id,
   jsonb_build_object('claimId',p_claim_id,'operationId',p_operation_id,'target',p_target,'changedFields',to_jsonb(fields),'claimRevision',result_revision));
  perform private.notify_order_claim(p_claim_id,'claim_updated','클레임 연락처가 변경됐어요','고객과 확인한 연락처 정보로 변경했습니다.');
 end if;
 insert into private.order_claim_contact_operations(id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,result_claim_revision,state,changed_fields,request_hmac,hmac_key_version,history)
 values(p_operation_id,p_actor_id,p_session_id,p_order_id,p_claim_id,'change',p_target,p_expected_claim_type,p_expected_claim_revision,result_revision,
 case when p_sealed_change->>'effect'='noop' then 'noop' else 'saved' end,fields,p_request_hmac,p_hmac_key_version,hist) returning * into op;
 return private.contact_operation_receipt(op);
end $$

-- Preserve the full frozen physical engine, including legacy and group branches.
CREATE FUNCTION private.record_order_claim_reshipment_physical(p_claim_id uuid, p_carrier text, p_tracking_number text, p_items jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid:=(select auth.uid()); selected_order uuid; order_status public.order_status;
  claim public.order_cancellation_requests; item record; selected_variant uuid; source_variant uuid;
  variant public.goods_variants; carrier text:=nullif(btrim(p_carrier),''); tracking text:=nullif(btrim(p_tracking_number),'');
  selections jsonb; requested jsonb; shipped_items jsonb;
begin
  perform private.require_operator_capability('sales.manage',false);

  if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required'; end if;
  if carrier is null or tracking is null or tracking!~'^[A-Z0-9]{8,30}$' then raise check_violation using message='invalid reshipment tracking'; end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>1000 then raise check_violation using message='invalid reshipment items'; end if;
  for requested in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(requested) is distinct from 'object' or not(requested ?& array['orderItemId','variantId'])
      or (select count(*) from jsonb_object_keys(requested))<>2
      or (requested->>'orderItemId') is null or (requested->>'variantId') is null
      or requested->>'orderItemId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or requested->>'variantId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then raise check_violation using message='invalid reshipment items'; end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(p_items) x group by (x->>'orderItemId')::uuid having count(*)>1) then
    raise check_violation using message='invalid reshipment items';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('orderItemId',(x->>'orderItemId')::uuid,'variantId',(x->>'variantId')::uuid)
    order by (x->>'orderItemId')::uuid),'[]') into selections from jsonb_array_elements(p_items) x;
  select order_id into selected_order from public.order_cancellation_requests where id=p_claim_id;
  if not found then raise no_data_found using message='claim_not_found'; end if;
  -- Cancellation, payment finalization and claim operations all lock order first.
  select status into order_status from public.orders where id=selected_order for update;
  select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
  if claim.claim_type<>'exchange' then raise exception using message='claim_type_has_no_reshipment'; end if;
  perform private.lock_goods_stock_successor_topology();
  if exists(select 1 from private.group_claim_reshipment_receipts where claim_id=p_claim_id)
    or (claim.stage<>'completed' and (
      exists(select 1 from public.order_items oi cross join lateral private.order_item_physical_unit(oi.id) unit
        where oi.order_id=selected_order and (unit.good_id<>oi.good_id
          or exists(select 1 from private.goods_stock_successors where source_variant_id=unit.variant_id)
          or exists(select 1 from private.goods_group_members where variant_id=unit.variant_id)
          or exists(select 1 from private.group_claim_reshipment_allocations where order_item_id=oi.id)))
      or exists(select 1 from jsonb_array_elements(selections) x join public.order_items oi on oi.id=(x->>'orderItemId')::uuid
        join public.goods_variants v on v.id=(x->>'variantId')::uuid where oi.good_id<>v.good_id))) then
    return private.record_group_claim_reshipment(p_claim_id,carrier,tracking,selections);
  end if;
  if claim.stage='completed' then
    if claim.reship_carrier=carrier and claim.reship_tracking_number=tracking and not exists(
      select 1 from jsonb_array_elements(selections) selected where not exists(
        select 1 from public.order_claim_reshipment_items shipped where shipped.claim_id=p_claim_id
          and shipped.order_item_id=(selected->>'orderItemId')::uuid and shipped.variant_id=(selected->>'variantId')::uuid))
      then return 'completed'; end if;
    raise unique_violation using message='reshipment_conflict';
  end if;
  perform private.assert_claim_collections_complete(p_claim_id);
  if claim.stage<>'collected' or order_status not in('delivered','done')
    or exists(select 1 from public.order_cancellation_claims where order_id=selected_order)
    then raise exception using message='claim_not_reshippable'; end if;
  if not exists(select 1 from public.shipping_carriers c where c.code=carrier and c.is_active) then raise check_violation using message='unknown shipping carrier'; end if;
  if exists(select 1 from jsonb_array_elements(selections) selected where not exists(
    select 1 from public.order_items oi where oi.id=(selected->>'orderItemId')::uuid and oi.order_id=selected_order)) then
    raise check_violation using message='invalid reshipment items';
  end if;
  perform 1 from public.goods g where g.id in(select good_id from public.order_items where order_id=selected_order) order by g.id for update;
  for item in select * from public.order_items where order_id=selected_order order by good_id,id loop
    source_variant:=private.order_item_stock_variant(item.id);
    select (selected->>'variantId')::uuid into selected_variant from jsonb_array_elements(selections) selected where (selected->>'orderItemId')::uuid=item.id;
    selected_variant:=coalesce(selected_variant,source_variant);
    select * into variant from public.goods_variants where id=selected_variant and good_id=item.good_id;
    if not found or (variant.archived_at is not null and selected_variant<>source_variant) then raise check_violation using message='reshipment_variant_unavailable'; end if;
    insert into public.order_claim_reshipment_items(claim_id,order_item_id,good_id,source_variant_id,variant_id,variant_name_snapshot,variant_code_snapshot,qty)
      values(p_claim_id,item.id,item.good_id,source_variant,selected_variant,variant.name,variant.code,item.qty);
  end loop;
  -- Net all returned/shipped options first. A two-line blue/red swap also works
  -- with no spare stock; every recovered unit belongs to this collected claim.
  for item in select changes.good_id,changes.variant_id,sum(changes.delta)::bigint delta from (
    select good_id,source_variant_id variant_id,qty::bigint delta from public.order_claim_reshipment_items where claim_id=p_claim_id
    union all select good_id,variant_id,-qty::bigint from public.order_claim_reshipment_items where claim_id=p_claim_id
  ) changes group by changes.good_id,changes.variant_id having sum(changes.delta)<>0 order by changes.good_id,delta desc,changes.variant_id loop
    perform private.change_goods_variant_stock(item.good_id,item.variant_id,item.delta::bigint);
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('orderItemId',order_item_id,'goodId',good_id,'sourceVariantId',source_variant_id,'variantId',variant_id,'qty',qty) order by order_item_id),'[]')
    into shipped_items from public.order_claim_reshipment_items where claim_id=p_claim_id;
  update public.order_cancellation_requests set stage='completed',reship_carrier=carrier,reship_tracking_number=tracking,
    reshipped_at=now(),completed_at=now(),updated_at=now() where id=p_claim_id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.claim_reshipped','order:'||selected_order::text,
    jsonb_build_object('claimId',p_claim_id,'claimType','exchange','from','collected','to','completed','carrier',carrier,'items',shipped_items));
  perform private.notify_order_claim(p_claim_id,'reshipped','교환 상품이 재출고됐어요','교환 상품을 새 운송장으로 발송했습니다.');
  return 'completed';
end $function$

create or replace function public.admin_record_order_claim_reshipment(p_claim_id uuid,p_carrier text,p_tracking_number text,p_items jsonb) returns text
language plpgsql volatile security definer set search_path='' as $$
declare c public.order_cancellation_requests;parties uuid[];begin
 select * into c from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found';end if;
 parties:=private.contact_parties(c.order_id);perform private.gift_lock_subjects(array_append(parties,auth.uid()));
 perform private.require_operator_capability('sales.manage',false);
 c:=private.contact_lock_scope(c.order_id,p_claim_id,parties);
 if c.stage<>'completed' then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
 return private.record_order_claim_reshipment_physical(p_claim_id,p_carrier,p_tracking_number,p_items);
end $$

