create function private.validate_shipping_settings_fulfillment(p_directive jsonb) returns void language plpgsql immutable set search_path='' as $$
declare p jsonb;m jsonb;begin
 if private.transaction_json_keys(p_directive,array['mode']) and p_directive->>'mode'='preserve' then return;end if;
 if not private.transaction_json_keys(p_directive,array['mode','policy']) or p_directive->>'mode' is distinct from 'replace' then raise invalid_parameter_value using message='invalid_shipping_settings_fulfillment';end if;
 p:=p_directive->'policy';
 if not private.transaction_json_keys(p,array['mode','methods','publicNote','evidence','confirmed']) or coalesce(p->>'mode','') not in('shipping','no_delivery')
  or p->'confirmed' is distinct from 'true'::jsonb or jsonb_typeof(p->'methods') is distinct from 'array' or jsonb_array_length(p->'methods') not between 1 and 5
  or jsonb_typeof(p->'publicNote') is distinct from 'string' or char_length(p->>'publicNote')>1000 or p->>'publicNote'<>btrim(p->>'publicNote')
  or jsonb_typeof(p->'evidence') is distinct from 'string' or char_length(p->>'evidence') not between 2 and 1000 or p->>'evidence'<>btrim(p->>'evidence')
  or ((p->>'publicNote')||(p->>'evidence'))~'[[:cntrl:]]' then raise invalid_parameter_value using message='invalid_shipping_settings_fulfillment';end if;
 if (select count(distinct value->>'method') from jsonb_array_elements(p->'methods'))<>jsonb_array_length(p->'methods') then raise invalid_parameter_value;end if;
 for m in select value from jsonb_array_elements(p->'methods') loop
  if not private.transaction_json_keys(m,array['method','feeAmount','feeBasis','installationFee']) or coalesce(m->>'method','') not in('parcel','quick','pickup','direct','freight','none')
   or coalesce(m->>'feeBasis','') not in('per_order','per_item') or not private.transaction_uint(m->'installationFee',0,1000000)
   or (m->>'method'='parcel') is distinct from (m->'feeAmount'='null'::jsonb)
   or m->>'method'<>'parcel' and not private.transaction_uint(m->'feeAmount',0,1000000)
   or m->>'method' in('pickup','none') and (m->'feeAmount'<>'0'::jsonb or m->'installationFee'<>'0'::jsonb)
   or m->>'method'='parcel' and m->>'feeBasis'<>'per_order'
   or p->>'mode'='shipping' and m->>'method'='none' or p->>'mode'='no_delivery' and m->>'method'<>'none'
   then raise invalid_parameter_value using message='invalid_shipping_settings_fulfillment';end if;
 end loop;
end $$

CREATE OR REPLACE FUNCTION private.validate_shipping_settings_charge(p_settings jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$declare directive jsonb;begin
 perform private.validate_shipping_settings_extended(p_settings-array['chargeGroup','fulfillment']);
 if p_settings ? 'fulfillment' then perform private.validate_shipping_settings_fulfillment(p_settings->'fulfillment');end if;
 if not(p_settings ? 'chargeGroup') then return;end if;
 directive:=p_settings->'chargeGroup';
 if private.transaction_json_keys(directive,array['mode']) and directive->>'mode' in('preserve','clear') then return;end if;
 if not coalesce(private.transaction_json_keys(directive,array['mode','groupId']) and directive->>'mode'='assign'
  and private.shipping_settings_uuid(directive->'groupId'),false) then
  raise invalid_parameter_value using message='invalid_shipping_settings_charge_group';end if;
end $function$

CREATE OR REPLACE FUNCTION private.validate_shipping_settings_charge_apply(p_request jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$declare legacy jsonb;row jsonb;target jsonb;begin
 if not private.transaction_json_keys(p_request,array['operationId','command','templateId','expectedRevision','expectedActorId','expectedSessionId',
  'originUpdatedAt','collectRevision','collectVersionId','goods','targetGroup']) then
  raise invalid_parameter_value using message='invalid_shipping_settings_application';end if;
 if jsonb_typeof(p_request->'goods') is distinct from 'array' then
  raise invalid_parameter_value using message='invalid_shipping_settings_targets';end if;
 target:=p_request->'targetGroup';
 if target<>'null'::jsonb and not coalesce(private.transaction_json_keys(target,array['id','revision'])
  and private.shipping_settings_uuid(target->'id') and private.transaction_uint(target->'revision',1,2147483647),false) then
  raise invalid_parameter_value using message='invalid_shipping_settings_charge_group';end if;
 for row in select value from jsonb_array_elements(p_request->'goods') loop
  if not private.transaction_json_keys(row-'fulfillmentRevision',array['id','updatedAt','ownerGoodId','ownerUpdatedAt','familyGoodIds','transactionRevision','deliveryVersionId',
   'assignmentRevision','assignmentVersionId','groupId','groupRevision'])
   or (row ? 'fulfillmentRevision' and not private.transaction_uint(row->'fulfillmentRevision',0,2147483647))
   or not private.transaction_uint(row->'assignmentRevision',0,2147483647)
   or not(row->'assignmentVersionId'='null'::jsonb or private.shipping_settings_uuid(row->'assignmentVersionId'))
   or (row->>'assignmentRevision'='0') is distinct from (row->'assignmentVersionId'='null'::jsonb)
   or not(row->'groupId'='null'::jsonb or private.shipping_settings_uuid(row->'groupId'))
   or not(row->'groupRevision'='null'::jsonb or private.transaction_uint(row->'groupRevision',1,2147483647))
   or (row->'groupId'='null'::jsonb) is distinct from (row->'groupRevision'='null'::jsonb)
   or (row->'groupId'<>'null'::jsonb and row->>'assignmentRevision'='0') then
   raise invalid_parameter_value using message='invalid_shipping_settings_targets';end if;
 end loop;
 legacy:=(p_request-'targetGroup')||jsonb_build_object('goods',(select jsonb_agg(value-array['assignmentRevision','assignmentVersionId','groupId','groupRevision','fulfillmentRevision'])
  from jsonb_array_elements(p_request->'goods')));
 perform private.validate_shipping_settings_apply(legacy);
end $function$

CREATE OR REPLACE FUNCTION private.shipping_settings_charge_blocker(p_good goods, p_settings jsonb, p_current_delivery jsonb, p_origin jsonb, p_group jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare reason text;directive text;begin
 reason:=private.shipping_settings_delivery_blocker(p_good.id,p_settings,p_current_delivery,p_origin);
 if reason is not null then return reason;end if;
 if p_settings#>>'{fulfillment,mode}'='replace' and not coalesce((select enabled from private.goods_transaction_runtime where singleton),false) then
  return 'checkout_contract_upgrade_required';end if;
 directive:=coalesce(p_settings#>>'{chargeGroup,mode}','preserve');
 if directive='assign' and (p_group is null or p_group='null'::jsonb) then return 'shipping_charge_group_unavailable';end if;
 if p_group is not null and p_group<>'null'::jsonb then
  if p_group->>'originId' is distinct from p_settings->>'originId' then return 'shipping_charge_group_origin_mismatch';end if;
  if not coalesce((p_group->>'enabled')::boolean,false) or coalesce((p_group->>'archived')::boolean,true) then
   return 'shipping_charge_group_unavailable';end if;
 end if;
 if ((p_group is not null and p_group<>'null'::jsonb) or directive='clear')
  and not coalesce((select enabled from private.goods_transaction_runtime where singleton),false) then
  return 'checkout_contract_upgrade_required';end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.admin_preview_shipping_settings_template_v3(p_template_id uuid, p_good_ids text[], p_expected_actor_id uuid, p_expected_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare template public.shipping_settings_templates;origin public.fulfillment_origins;good public.goods;owner public.goods;rows jsonb:='[]';
 origin_doc jsonb;target_group jsonb;before_group jsonb;after_group jsonb;directive text;current_delivery jsonb;next_delivery jsonb;blocker text;can_apply boolean:=true;
begin
 perform private.require_shipping_settings_identity(p_expected_actor_id,p_expected_session_id);
 if p_template_id is null or p_good_ids is null or cardinality(p_good_ids) not between 1 and 100 or array_position(p_good_ids,null) is not null
  or exists(select 1 from unnest(p_good_ids) id where not private.shipping_settings_good_id(to_jsonb(id)))
  or (select count(distinct id) from unnest(p_good_ids) id)<>cardinality(p_good_ids) then
  raise invalid_parameter_value using message='invalid_shipping_settings_targets';end if;
 select * into template from public.shipping_settings_templates where id=p_template_id and enabled;
 if not found then raise check_violation using message='shipping_settings_template_unavailable';end if;
 perform private.validate_shipping_settings_charge(template.settings);
 select * into origin from public.fulfillment_origins where id=(template.settings->>'originId')::uuid and is_active;
 if not found then raise check_violation using message='shipping_settings_origin_unavailable';end if;
 origin_doc:=private.shipping_settings_origin(origin);
 directive:=coalesce(template.settings#>>'{chargeGroup,mode}','preserve');
 target_group:=case when directive='assign' then private.shipping_charge_group_summary((template.settings#>>'{chargeGroup,groupId}')::uuid) else null end;
 if directive='assign' and target_group is null then raise check_violation using message='shipping_charge_group_unavailable';end if;
 if (select count(*) from public.goods where id=any(p_good_ids) and archived_at is null)<>cardinality(p_good_ids) then
  raise check_violation using message='shipping_settings_goods_unavailable';end if;
 for good in select * from public.goods where id=any(p_good_ids) order by id loop
  select * into owner from public.goods where id=private.goods_aggregation_owner(good.id);
  current_delivery:=private.shipping_settings_delivery_input(good.id);
  next_delivery:=case when template.settings#>>'{delivery,mode}'='replace' then template.settings#>'{delivery,policy}' else current_delivery end;
  before_group:=private.shipping_settings_charge_summary(good);
  after_group:=case when directive='preserve' then before_group when directive='assign' then target_group else 'null'::jsonb end;
  blocker:=private.shipping_settings_charge_blocker(good,template.settings,current_delivery,origin_doc,after_group);can_apply:=can_apply and blocker is null;
  rows:=rows||jsonb_build_array(private.shipping_settings_charge_good_guard(good)||jsonb_build_object('name',good.name,'code',good.code,
   'editable',owner.id=good.id,'blocker',blocker,'before',private.good_shipping_settings(good),'after',template.settings,
   'effectiveBefore',private.shipping_settings_charge_effective(private.good_shipping_settings(owner),current_delivery,before_group)||jsonb_build_object('fulfillment',private.goods_fulfillment_document(good.id,false)),
   'effectiveAfter',private.shipping_settings_charge_effective(template.settings,next_delivery,after_group)||jsonb_build_object('fulfillment',private.shipping_settings_fulfillment_after(good.id,template.settings))));
 end loop;
 return jsonb_build_object('template',private.shipping_settings_template_json(template),'actorId',p_expected_actor_id,'sessionId',p_expected_session_id,
  'canApply',can_apply,'origin',origin_doc,'goods',rows,'targetGroup',coalesce(target_group,'null'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.admin_apply_shipping_settings_template_v3(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare context jsonb;payload_hash text;receipt jsonb;template public.shipping_settings_templates;origin public.fulfillment_origins;origin_doc jsonb;
 good public.goods;target text;ids text[];row jsonb;actual jsonb;current_delivery jsonb;blocker text;child_operation uuid;transaction_receipt jsonb;
 target_group jsonb;next_group jsonb;directive text;assignment_guard jsonb;previous jsonb;results jsonb:='[]';config private.goods_transaction_configs;
begin
 -- Reject missing authority before parsing caller-controlled operation JSON.
 if (select auth.uid()) is null then raise invalid_authorization_specification using message='auth_required';end if;
 if not public.has_operator_capability('catalog.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';
 end if;
 context:=private.shipping_settings_operation_context(p_request);
 perform private.require_shipping_settings_identity((context->>'expectedActorId')::uuid,(context->>'expectedSessionId')::uuid);
 perform private.validate_shipping_settings_charge_apply(p_request);
 p_request:=jsonb_set(p_request,'{goods}',(select jsonb_agg(value order by value->>'id') from jsonb_array_elements(p_request->'goods')));
 payload_hash:=encode(extensions.digest(p_request::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('shipping-settings-operation:'||(context->>'operationId'),0));
 receipt:=private.shipping_settings_prior(context,payload_hash);if receipt is not null then return receipt;end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 select * into template from public.shipping_settings_templates where id=(context->>'templateId')::uuid for share;
 if not found or not template.enabled then raise check_violation using message='shipping_settings_template_unavailable';end if;
 if template.revision<>(context->>'expectedRevision')::integer then raise sqlstate 'PT409' using message='shipping_settings_template_changed';end if;
 perform private.validate_shipping_settings_charge(template.settings);
 select array_agg(value->>'id' order by value->>'id') into ids from jsonb_array_elements(p_request->'goods');
 -- Claim operation/editor advisory locks before product rows. NOWAIT keeps
 -- cross-workflow contention recoverable instead of reversing lock order.
 foreach target in array ids loop
  if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||target,0)) then raise sqlstate 'PT409' using message='shipping_settings_retry';end if;
  child_operation:=md5('shipping-settings-delivery:'||(context->>'operationId')||':'||target)::uuid;
  if not pg_try_advisory_xact_lock(hashtextextended('goods-transaction-operation:'||child_operation::text,0)) then
   raise sqlstate 'PT409' using message='shipping_settings_retry';end if;
 end loop;
 perform 1 from public.goods where id=any(ids) order by id for update nowait;
 if (select count(*) from public.goods where id=any(ids) and archived_at is null)<>cardinality(ids) then
  raise check_violation using message='shipping_settings_goods_unavailable';end if;
 if exists(select 1 from unnest(ids) id where private.goods_aggregation_owner(id)<>id) then
  raise check_violation using message='goods_aggregation_policy_owned_by_source';end if;
 perform 1 from private.goods_transaction_configs where good_id=any(ids) order by good_id for update nowait;
 perform 1 from private.goods_fulfillment_settings where good_id=any(ids) order by good_id for update nowait;
 select * into origin from public.fulfillment_origins where id=(template.settings->>'originId')::uuid for share nowait;
 if not found or not origin.is_active then raise check_violation using message='shipping_settings_origin_unavailable';end if;
 perform 1 from private.shipping_collect_contracts where origin_id=origin.id for share nowait;
 origin_doc:=private.shipping_settings_origin(origin);
 if origin.updated_at is distinct from (p_request->>'originUpdatedAt')::timestamptz
  or origin_doc->'collectRevision' is distinct from p_request->'collectRevision' or origin_doc->'collectVersionId' is distinct from p_request->'collectVersionId' then
  raise sqlstate 'PT409' using message='shipping_settings_origin_changed';end if;
 directive:=coalesce(template.settings#>>'{chargeGroup,mode}','preserve');
 perform 1 from private.shipping_charge_groups g where g.id in (
  select a.group_id from private.shipping_charge_group_assignments a where a.owner_good_id=any(ids)
  union select (template.settings#>>'{chargeGroup,groupId}')::uuid where directive='assign'
 ) order by g.id for share nowait;
 perform 1 from private.shipping_charge_group_assignments where owner_good_id=any(ids) order by owner_good_id for update nowait;
 target_group:=case when directive='assign' then private.shipping_charge_group_summary((template.settings#>>'{chargeGroup,groupId}')::uuid) else null end;
 if directive='assign' then
  if target_group is null or p_request->'targetGroup' is distinct from jsonb_build_object('id',target_group->'id','revision',target_group->'revision') then
   raise sqlstate 'PT409' using message='shipping_charge_group_changed';end if;
 elsif p_request->'targetGroup'<>'null'::jsonb then raise invalid_parameter_value using message='invalid_shipping_settings_charge_group';end if;
 for good in select * from public.goods where id=any(ids) order by id loop
  select value into row from jsonb_array_elements(p_request->'goods') where value->>'id'=good.id;
  actual:=private.shipping_settings_charge_good_guard(good);
  if not(row ? 'fulfillmentRevision') then
   if template.settings#>>'{fulfillment,mode}'='replace' then raise sqlstate 'PT409' using message='shipping_settings_preview_upgrade_required';end if;
   actual:=actual-'fulfillmentRevision';
  end if;
  if actual->>'ownerGoodId' is distinct from row->>'ownerGoodId' or actual->'familyGoodIds' is distinct from row->'familyGoodIds'
   or (actual->>'updatedAt')::timestamptz is distinct from (row->>'updatedAt')::timestamptz
   or (actual->>'ownerUpdatedAt')::timestamptz is distinct from (row->>'ownerUpdatedAt')::timestamptz
   or actual->'transactionRevision' is distinct from row->'transactionRevision' or actual->'deliveryVersionId' is distinct from row->'deliveryVersionId'
   or (actual-array['id','updatedAt','ownerGoodId','ownerUpdatedAt','familyGoodIds','transactionRevision','deliveryVersionId'])
    is distinct from (row-array['id','updatedAt','ownerGoodId','ownerUpdatedAt','familyGoodIds','transactionRevision','deliveryVersionId']) then
   raise sqlstate 'PT409' using message='shipping_settings_goods_changed';end if;
 end loop;
 -- Hold the activation state while creating active delivery versions.
 perform 1 from private.goods_transaction_runtime where singleton for share nowait;
 for good in select * from public.goods where id=any(ids) order by id loop
  current_delivery:=private.shipping_settings_delivery_input(good.id);
  next_group:=case when directive='preserve' then private.shipping_settings_charge_summary(good) when directive='assign' then target_group else 'null'::jsonb end;
  blocker:=private.shipping_settings_charge_blocker(good,template.settings,current_delivery,origin_doc,next_group);
  if blocker is not null then raise check_violation using message=blocker;end if;
 end loop;
 for good in select * from public.goods where id=any(ids) order by id loop
  previous:=jsonb_build_object('settings',private.good_shipping_settings(good),'effective',private.shipping_settings_charge_effective(private.good_shipping_settings(good),private.shipping_settings_delivery_input(good.id),private.shipping_settings_charge_summary(good))||jsonb_build_object('fulfillment',private.goods_fulfillment_document(good.id,false)));
  perform public.admin_save_good_claim_policy(good.id,template.settings->'claimPolicy',good.updated_at);
  -- Bind the final origin before the existing delivery writer validates the
  -- collector. Nothing can commit if any later product fails.
  update public.goods set origin_id=origin.id,shipping_fee_type=template.settings->>'feeType',individual_fee=(template.settings->>'individualFee')::bigint
   where id=good.id returning * into good;
  if template.settings#>>'{delivery,mode}'='replace' then
   select * into config from private.goods_transaction_configs where good_id=good.id;
   child_operation:=md5('shipping-settings-delivery:'||(context->>'operationId')||':'||good.id)::uuid;
   transaction_receipt:=public.admin_save_good_transaction_terms(good.id,coalesce(config.revision,0),good.updated_at,null,template.settings#>'{delivery,policy}',
    child_operation,(context->>'expectedActorId')::uuid);
  end if;
  select value into row from jsonb_array_elements(p_request->'goods') where value->>'id'=good.id;
  select * into good from public.goods where id=good.id;
  if directive<>'preserve' and (row->>'groupId')::uuid is distinct from (case when directive='assign' then (target_group->>'id')::uuid else null end) then
   assignment_guard:=private.apply_shipping_charge_group_assignment_locked(good.id,
    case when directive='assign' then (target_group->>'id')::uuid else null end,
    case when directive='assign' then (target_group->>'revision')::integer else 0 end,
    (row->>'assignmentRevision')::integer,(row->>'assignmentVersionId')::uuid,
    array(select jsonb_array_elements_text(row->'familyGoodIds')),good.updated_at,origin.updated_at,
    (context->>'operationId')::uuid,(context->>'expectedActorId')::uuid,(context->>'expectedSessionId')::uuid);
  else perform private.assert_shipping_charge_group_owner_assignment(good.id);end if;
  if template.settings#>>'{fulfillment,mode}'='replace' then
   perform public.admin_save_goods_fulfillment(good.id,(template.settings#>'{fulfillment,policy}')||jsonb_build_object('assetIds','[]'::jsonb),
    (row->>'fulfillmentRevision')::bigint,md5('shipping-settings-fulfillment:'||(context->>'operationId')||':'||good.id)::uuid,
    (context->>'expectedActorId')::uuid,(context->>'expectedSessionId')::uuid);
  end if;
  update public.goods set shipping_settings_template_id=template.id,shipping_settings_template_revision=template.revision,
   shipping_settings_snapshot=jsonb_build_object('templateId',template.id,'templateRevision',template.revision,'name',template.name,'settings',template.settings,
    'appliedDelivery',case when template.settings#>>'{delivery,mode}'='replace' then private.shipping_settings_delivery_input(good.id) else null end,
    'appliedFulfillment',case when template.settings#>>'{fulfillment,mode}'='replace' then private.goods_fulfillment_document(good.id,false) else null end,
    'appliedChargeGroup',case when directive='preserve' then null else jsonb_build_object('groupId',case when directive='assign' then target_group->'id' else 'null'::jsonb end) end,
    'appliedAt',clock_timestamp(),'originUpdatedAt',origin.updated_at,'collectRevision',origin_doc->'collectRevision','collectVersionId',origin_doc->'collectVersionId')
  where id=good.id returning * into good;
  actual:=private.shipping_settings_charge_good_guard(good);
  insert into public.audit_log(actor_id,action,target,diff) values((context->>'expectedActorId')::uuid,'catalog.good.shipping_settings_applied','goods:'||good.id,
   jsonb_build_object('requestId',context->'operationId','templateId',template.id,'templateRevision',template.revision,'before',previous,
    'after',jsonb_build_object('settings',private.good_shipping_settings(good),'effective',private.shipping_settings_charge_effective(private.good_shipping_settings(good),private.shipping_settings_delivery_input(good.id),private.shipping_settings_charge_summary(good))||jsonb_build_object('fulfillment',private.goods_fulfillment_document(good.id,false))),
    'originUpdatedAt',origin.updated_at,'collectRevision',origin_doc->'collectRevision','collectVersionId',origin_doc->'collectVersionId'));
  results:=results||jsonb_build_array(jsonb_build_object('id',good.id,'updatedAt',good.updated_at,'transactionRevision',actual->'transactionRevision','deliveryVersionId',actual->'deliveryVersionId','assignmentRevision',actual->'assignmentRevision','assignmentVersionId',actual->'assignmentVersionId','groupId',actual->'groupId','groupRevision',actual->'groupRevision','fulfillmentRevision',actual->'fulfillmentRevision'));
 end loop;
 receipt:=private.shipping_settings_receipt(context,'applied',private.shipping_settings_template_json(template),results)||jsonb_build_object('chargeGroupVersion',1,'fulfillmentVersion',1);
 perform private.record_shipping_settings_operation(context,payload_hash,receipt);return receipt;
exception when lock_not_available then raise sqlstate 'PT409' using message='shipping_settings_retry';
end $function$

CREATE OR REPLACE FUNCTION private.detach_changed_shipping_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if new.shipping_settings_template_id is not null and (
  ((new.shipping_settings_snapshot->'settings')-array['delivery','chargeGroup','fulfillment']) is distinct from private.good_shipping_settings(new)
  or (new.shipping_settings_snapshot#>>'{settings,delivery,mode}'='replace'
   and new.shipping_settings_snapshot->'appliedDelivery' is distinct from private.shipping_settings_delivery_input(old.id))) then
  new.shipping_settings_template_id:=null;new.shipping_settings_template_revision:=null;new.shipping_settings_snapshot:=null;
 end if;
 if new.shipping_settings_snapshot is distinct from old.shipping_settings_snapshot or private.good_shipping_settings(new) is distinct from private.good_shipping_settings(old) then
  new.updated_at:=greatest(clock_timestamp(),old.updated_at+interval '1 microsecond');end if;
 return new;
end $function$

create function public.customer_demographic_state() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=auth.uid(); session_value uuid:=(auth.jwt()->>'session_id')::uuid;
 c private.customer_demographic_consents;
begin
 if actor is null or session_value is null or not exists(select 1 from auth.sessions
  where id=session_value and user_id=actor and (not_after is null or not_after>statement_timestamp())) then
  raise insufficient_privilege using message='customer_demographic_auth_changed'; end if;
 if not exists(select 1 from public.profiles p where p.id=actor and p.role='user'
  and p.onboarded_at is not null and p.suspended_at is null
  and p.consents->'terms'='true'::jsonb and p.consents->'privacy'='true'::jsonb
  and p.birth_date<=((statement_timestamp() at time zone 'Asia/Seoul')::date-interval '14 years')::date)
  or exists(select 1 from private.account_action_fences where subject_user_id=actor) then return null; end if;
 select * into c from private.customer_demographic_consents where user_id=actor;
 return jsonb_build_object('actorId',actor,'sessionId',session_value,'choice',coalesce(c.choice,'unset'),
  'gender',c.gender,'revision',coalesce(c.revision,0),'noticeVersion','customer-demographics-v1','acceptedAt',c.accepted_at);
end $$

create function public.set_customer_demographic_consent(p_choice text,p_gender text,p_expected_revision bigint,
 p_expected_actor uuid,p_expected_session uuid,p_notice_version text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare c private.customer_demographic_consents;
begin
 -- The shared identity helper locks the live customer, session and deletion
 -- boundary. It does not read or inherit the member-activity consent.
 perform private.require_member_activity_identity(p_expected_actor,p_expected_session);
 if p_choice is null or p_choice not in ('accepted','declined') or p_expected_revision is null or p_expected_revision<0
  or p_notice_version is distinct from 'customer-demographics-v1'
  or (p_choice='accepted' and (p_gender is null or p_gender not in ('female','male','other')))
  or (p_choice='declined' and p_gender is not null) then
  raise invalid_parameter_value using message='invalid_customer_demographic_choice'; end if;
 select * into c from private.customer_demographic_consents where user_id=p_expected_actor for update;
 if coalesce(c.revision,0)<>p_expected_revision then
  -- An immediate identical retry is safe, but an older accept cannot undo a
  -- later withdrawal/change, including an accept->decline->accept sequence.
  if c.revision=p_expected_revision+1 and c.choice=p_choice and c.gender is not distinct from p_gender then
   return public.customer_demographic_state(); end if;
  raise sqlstate 'PT409' using message='customer_demographic_choice_changed'; end if;
 if c.choice is distinct from p_choice or c.gender is distinct from p_gender then
  insert into private.customer_demographic_consents(user_id,choice,gender,notice_version,revision,accepted_at)
   values(p_expected_actor,p_choice,p_gender,p_notice_version,coalesce(c.revision,0)+1,
    case when p_choice='accepted' then clock_timestamp() end)
   on conflict(user_id) do update set choice=excluded.choice,gender=excluded.gender,notice_version=excluded.notice_version,
    revision=excluded.revision,accepted_at=excluded.accepted_at,updated_at=clock_timestamp();
 end if;
 return public.customer_demographic_state();
end $$

revoke all on function public.customer_demographic_state(),public.set_customer_demographic_consent(text,text,bigint,uuid,uuid,text),
 private.erase_fenced_customer_demographics(),public.admin_customer_demographic_report(text,text,date,date)
 from public,anon,authenticated,service_role

CREATE OR REPLACE FUNCTION public.order_claim_eligibility(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare delivery_complete boolean;
begin
 if (select auth.uid()) is null or not exists(select 1 from public.orders o where o.id=p_order_id and (o.user_id=(select auth.uid()) or public.has_operator_capability('sales.read',false))) then return null; end if;
 delivery_complete:=private.order_return_intake_eligible(p_order_id);
 return jsonb_build_object('cancel',private.order_cancel_eligible(p_order_id),'return',delivery_complete,'exchange',delivery_complete and not private.order_has_digital_items(p_order_id));
end $function$

CREATE OR REPLACE FUNCTION public.admin_seller_claim_intake_context(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.orders; result jsonb; observed_at timestamptz := clock_timestamp();
begin
  if not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='operator_capability_required'; end if;

  perform (select auth.uid());
  select * into target from public.orders where id = p_order_id;
  if not found then return null; end if;
  select jsonb_build_object(
    'orderId', target.id, 'orderStatus', target.status, 'orderTotal', target.total,
    'buyerName', profile.nickname, 'createdAt', target.created_at, 'deliveredAt', target.delivered_at,
    'address', target.address, 'observedAt', observed_at,
    'cancelBlockedReason',private.seller_cancel_intake_block(target.id),
    'digitalExchangeBlocked',private.order_has_digital_items(target.id),
    'blockedReasons', jsonb_build_object(
      'change_of_mind', private.seller_claim_intake_block(target.id, 'change_of_mind', observed_at),
      'defect', private.seller_claim_intake_block(target.id, 'defect', observed_at)),
    'activeClaim', (select jsonb_build_object('id', c.id, 'claimType', c.claim_type, 'stage', c.stage)
      from public.order_cancellation_requests c where c.order_id = target.id and c.status in ('requested', 'processing', 'needs_review') order by c.requested_at desc limit 1),
    'collections', private.seller_claim_collection_targets(target.id),
    'carriers', coalesce((select jsonb_agg(jsonb_build_object('code', c.code, 'label', c.label, 'active', c.is_active, 'trackingUrlTemplate', c.tracking_url_template) order by c.sort_order, c.code)
      from public.shipping_carriers c where c.is_active), '[]'),
    'inquiries', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'reference', i.reference, 'title', i.title, 'createdAt', i.created_at) order by i.created_at desc)
      from (select * from public.inquiries where user_id = target.user_id and order_id = target.id order by created_at desc, id limit 50) i), '[]')
  ) into result from public.profiles profile where profile.id = target.user_id;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_submit_seller_claim_intake(p_request_id uuid, p_payload jsonb, p_refund_account jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid()); target public.orders;
  previous private.seller_order_claim_intakes; saved_payload jsonb; collections jsonb; targets jsonb;
  block text; submitted_at timestamptz; requested_at timestamptz; target_id uuid;
begin
  perform private.require_operator_capability('sales.manage',false);

  if p_request_id is null then raise invalid_parameter_value using message = 'invalid_seller_claim_request'; end if;
  perform private.validate_seller_claim_intake(p_payload, p_refund_account);
  target_id := (p_payload->>'orderId')::uuid;
  requested_at := (p_payload->>'customerRequestedAt')::timestamptz;
  -- Raw bank details have exactly one storage destination and its existing purge
  -- lifecycle. The idempotency receipt stores only their SHA-256 fingerprint.
  saved_payload := p_payload || jsonb_build_object('refundAccountDigest',
    case when p_refund_account is null or p_refund_account = 'null'::jsonb then null
      else encode(extensions.digest(p_refund_account::text, 'sha256'), 'hex') end);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('seller_claim_intake:' || p_request_id, 0));
  select * into previous from private.seller_order_claim_intakes where claim_id = p_request_id;
  if found then
    if previous.actor_id <> actor or previous.payload <> saved_payload then
      raise exception using errcode = 'PT409', message = 'seller_claim_request_conflict';
    end if;
    return private.seller_claim_intake_json(p_request_id);
  end if;
  if exists(select 1 from public.order_cancellation_requests where id = p_request_id) then
    raise exception using errcode = 'PT409', message = 'seller_claim_request_conflict';
  end if;

  -- Same parent-first order as customer intake and dispatch. No financial
  -- operation is performed after these locks; they only stabilize eligibility.
  select * into target from public.orders where id = target_id for update;
  if not found then raise no_data_found using message = 'order_not_found'; end if;
  perform s.id from public.order_shipments s where s.order_id = target_id order by s.id for update;
  perform attempt.id from public.payment_attempts attempt where attempt.purpose = 'order' and attempt.ref_id = target_id order by attempt.id for update;
  if p_payload->>'claimType'='exchange' and private.order_has_digital_items(target_id) then
    raise check_violation using message='digital_exchange_unavailable'; end if;
  submitted_at := clock_timestamp();
  block := case when p_payload->>'claimType'='cancel' then private.seller_cancel_intake_block(target_id)
    else private.seller_claim_intake_block(target_id, p_payload->>'reasonType', submitted_at) end;
  if block is not null then raise check_violation using message = block; end if;
  if requested_at < target.created_at or requested_at > submitted_at then
    raise invalid_parameter_value using message = 'invalid_seller_claim_customer_time';
  end if;
  if p_payload->>'source' = 'inquiry' then
    perform 1 from public.inquiries where id = (p_payload->>'inquiryId')::uuid and user_id = target.user_id and order_id = target_id for share;
    if not found then raise check_violation using message = 'seller_claim_inquiry_mismatch'; end if;
  end if;
  if p_payload->>'claimType'='cancel' then
    collections:='[]'::jsonb;
  else
  targets := private.seller_claim_collection_targets(target_id);
  if jsonb_array_length(targets) <> jsonb_array_length(p_payload->'collections')
    or (select count(distinct (x->>'shipmentId')::uuid) from jsonb_array_elements(p_payload->'collections') x) <> jsonb_array_length(targets)
    or exists(select 1 from jsonb_array_elements(p_payload->'collections') x where not exists(select 1 from jsonb_array_elements(targets) t where (t->>'shipmentId')::uuid = (x->>'shipmentId')::uuid))
  then raise check_violation using message = 'seller_claim_collections_changed'; end if;
  if exists(select 1 from jsonb_array_elements(p_payload->'collections') x where x->>'carrier' is not null
    and not exists(select 1 from public.shipping_carriers carrier where carrier.code = x->>'carrier' and carrier.is_active))
  then raise check_violation using message = 'unknown_shipping_carrier'; end if;
  select jsonb_agg(x || jsonb_build_object('originId', t->>'originId', 'originName', t->>'originName', 'items', t->'items') order by t->>'originId', t->>'shipmentId')
    into collections from jsonb_array_elements(p_payload->'collections') x join jsonb_array_elements(targets) t on (x->>'shipmentId')::uuid = (t->>'shipmentId')::uuid;

  end if;

  insert into public.order_cancellation_requests(id, order_id, requested_by, claim_type, reason_type, reason, stage, requested_at)
    values(p_request_id, target_id, target.user_id, p_payload->>'claimType', p_payload->>'reasonType', p_payload->>'reason', 'requested', submitted_at);
  insert into private.seller_order_claim_intakes(claim_id, actor_id, payload, collection_snapshot, created_at)
    values(p_request_id, actor, saved_payload, collections, submitted_at);
  -- Preserve the submitted payload for exact idempotency while the immutable
  -- target labels/items are stored separately inside the same private receipt.
  -- They are returned by joining the original input with its intake snapshot.
  if p_refund_account is not null and p_refund_account <> 'null'::jsonb then
    insert into private.claim_refund_accounts(claim_id, bank_name, account_number, account_holder, masked_account, masked_holder)
      values(p_request_id, p_refund_account->>'bankName', p_refund_account->>'accountNumber', p_refund_account->>'accountHolder',
        (p_refund_account->>'bankName') || ' ' || public.mask_refund_account_number(p_refund_account->>'accountNumber'),
        public.mask_refund_account_holder(p_refund_account->>'accountHolder'));
  end if;
  insert into public.audit_log(actor_id, action, target, diff) values(actor, 'admin.order.claim_intake_created', 'order:' || target_id::text,
    jsonb_build_object('claimId', p_request_id, 'claimType', p_payload->>'claimType', 'to', 'requested', 'source', p_payload->>'source',
      'inquiryId', p_payload->>'inquiryId', 'customerRequestedAt', requested_at, 'collectionCount', jsonb_array_length(collections)));
  perform private.notify_order_claim(p_request_id, 'seller_requested', case when p_payload->>'claimType'='cancel' then '취소 요청이 접수됐어요' else '반품·교환 요청이 접수됐어요' end,
    '고객님과 확인한 내용을 바탕으로 담당자가 요청을 접수했습니다. 승인과 이후 처리는 별도로 진행됩니다.');
  return private.seller_claim_intake_json(p_request_id);
end $function$

create function private.guard_digital_exchange_policy() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.claim_type='exchange' and private.order_has_digital_items(new.order_id) then
  raise check_violation using message='digital_exchange_unavailable'; end if;
 return new;
end $$

-- PostgREST runs STABLE RPCs in a read-only transaction. The read capability
-- predicate rechecks current access without the mutation guard's row locks.
do $$declare source text; anchor text:='perform private.require_operator_capability(''stats.read'',false);';
begin
 source:=pg_get_functiondef('public.admin_customer_demographic_report(text,text,date,date)'::regprocedure);
 if (length(source)-length(replace(source,anchor,'')))/length(anchor)<>1 then
  raise exception 'customer_demographic_guard_source_changed'; end if;
 execute replace(source,anchor,'if not public.has_operator_capability(''stats.read'',false) then raise insufficient_privilege using message=''operator_capability_required''; end if;');
end $$

create function public.admin_mark_inquiry_chat_read(p_inquiry_id uuid,p_message_ids uuid[])
returns integer language plpgsql volatile security definer set search_path='' as $$
declare v_actor uuid;v_inserted integer;
begin
  v_actor:=private.require_operator_capability('cs.manage',false);
  if p_inquiry_id is null or p_message_ids is null or cardinality(p_message_ids) not between 1 and 500
    or array_position(p_message_ids,null) is not null then
    raise invalid_parameter_value using message='invalid_inquiry_chat_read';
  end if;
  if not exists(select 1 from public.inquiries where id=p_inquiry_id) then
    raise no_data_found using message='inquiry_not_found';
  end if;
  if exists(select 1 from unnest(p_message_ids) ids(id) where not exists(
    select 1 from public.inquiry_messages message where message.id=ids.id and message.inquiry_id=p_inquiry_id and message.author='user')) then
    raise invalid_parameter_value using message='invalid_inquiry_chat_message';
  end if;
  insert into private.inquiry_chat_reads(actor_id,message_id)
    select v_actor,message.id from public.inquiry_messages message
    where message.inquiry_id=p_inquiry_id and message.author='user' and message.id=any(p_message_ids)
    on conflict(actor_id,message_id) do nothing;
  get diagnostics v_inserted=row_count;
  return v_inserted;
end $$

-- Use the existing trusted CS owner; never grant privileged dependencies to client roles.
do $owner$ declare owner_id oid;entry regprocedure;
begin
  select proowner into owner_id from pg_proc where oid='public.admin_inquiry_satisfaction_console(text,text,date,date,text,text,integer,integer,text)'::regprocedure;
  if owner_id is null or owner_id in ('anon'::regrole::oid,'authenticated'::regrole::oid,'service_role'::regrole::oid)
    or not exists(select 1 from pg_roles where oid=owner_id and (rolsuper or rolbypassrls)) then
    raise exception 'inquiry_chat_trusted_owner_required';
  end if;
  if not has_function_privilege(owner_id,'private.require_operator_capability(text,boolean)'::regprocedure,'EXECUTE')
    or not has_function_privilege(owner_id,'private.has_operator_capability(uuid,text,boolean)'::regprocedure,'EXECUTE') then
    raise exception 'inquiry_chat_dependency_denied';
  end if;
  execute format('grant select,insert on private.inquiry_chat_reads to %I',pg_get_userbyid(owner_id));
  foreach entry in array array[
    'public.admin_inquiry_chat_console(text,text,text,text,text,text,integer,integer)'::regprocedure,
    'public.admin_mark_inquiry_chat_read(uuid,uuid[])'::regprocedure
  ] loop
    execute format('alter function %s owner to %I',entry,pg_get_userbyid(owner_id));
    execute format('revoke all on function %s from public,anon,authenticated,service_role',entry);
    execute format('grant execute on function %s to authenticated,postgres',entry);
  end loop;
end $owner$

-- The reply sheet identifies an order item, not an order or a shipment. Resolve
-- that exact UUID through the allocation table; never guess by an ID suffix.
create function public.admin_import_item_tracking_batch(target_rows jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  input jsonb; normalized jsonb:='[]'; delegated jsonb:='[]'; results jsonb:='[]';
  outcomes jsonb:='{}'; group_errors jsonb:='{}'; completed jsonb; outcome jsonb;
  reference_value text; item_key uuid; shipment_key uuid; order_key uuid;
  carrier_value text; tracking_value text; row_error text; group_error text; batch_error text;
  grouped record; seen uuid[]:='{}';
begin
  perform private.require_operator_capability('sales.manage',false);
  if jsonb_typeof(target_rows) is distinct from 'array' then raise invalid_parameter_value using message='invalid_tracking_batch';end if;
  if jsonb_array_length(target_rows) not between 1 and 1000 then raise invalid_parameter_value using message='invalid_tracking_batch';end if;

  for input in select value from jsonb_array_elements(target_rows) loop
    reference_value:=null;item_key:=null;shipment_key:=null;order_key:=null;
    carrier_value:=null;tracking_value:=null;row_error:=null;
    begin
      if jsonb_typeof(input) is distinct from 'object' then raise invalid_parameter_value using message='invalid_tracking_row';end if;
      if jsonb_typeof(input->'reference') is distinct from 'string' then raise invalid_parameter_value using message='invalid_item_order_reference';end if;
      reference_value:=btrim(input->>'reference');
      if reference_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        raise invalid_parameter_value using message='invalid_item_order_reference';end if;
      item_key:=reference_value::uuid;
      select link.shipment_id,link.order_id into shipment_key,order_key from public.order_shipment_items link where link.order_item_id=item_key;
      if shipment_key is null then raise no_data_found using message='shipment_item_not_found';end if;
      -- Resolve before the remaining validation so one malformed item row blocks
      -- every sibling in its shipment, including a valid row earlier in the file.
      if exists(select 1 from jsonb_object_keys(input) key where key not in('line','reference','carrier','trackingNumber'))
        or jsonb_typeof(input->'line') is distinct from 'number' or (input->>'line') !~ '^[0-9]+$'
        or (input->>'line')::numeric not between 1 and 2147483647
        or jsonb_typeof(input->'carrier') is distinct from 'string'
        or jsonb_typeof(input->'trackingNumber') is distinct from 'string' then
        raise invalid_parameter_value using message='invalid_tracking_row';end if;
      carrier_value:=btrim(input->>'carrier');
      tracking_value:=upper(regexp_replace(btrim(input->>'trackingNumber'),'[[:space:]-]','','g'));
      if carrier_value='' or char_length(carrier_value)>100 or tracking_value !~ '^[A-Z0-9]{8,30}$' then
        raise check_violation using message='invalid_tracking_input';end if;
    exception when others then row_error:=sqlerrm;
    end;
    normalized:=normalized||jsonb_build_array(jsonb_build_object('line',input->'line','reference',reference_value,
      'shipmentId',shipment_key,'orderId',order_key,'carrier',carrier_value,'trackingNumber',tracking_value,'error',row_error));
  end loop;

  for grouped in select value->>'shipmentId' as id,jsonb_agg(value) as rows
    from jsonb_array_elements(normalized) where value->>'shipmentId' is not null
    group by value->>'shipmentId' order by value->>'shipmentId'
  loop
    select value->>'error' into group_error from jsonb_array_elements(grouped.rows) where value->>'error' is not null limit 1;
    if group_error is null and (
      (select count(distinct value->>'carrier') from jsonb_array_elements(grouped.rows))<>1
      or (select count(distinct value->>'trackingNumber') from jsonb_array_elements(grouped.rows))<>1
    ) then group_error:='conflicting_shipment_tracking';end if;
    group_errors:=group_errors||jsonb_build_object(grouped.id,group_error);
    -- Invalid groups remain in the existing whole-pack preflight with empty
    -- assignment data. Omitting them could dispatch a pack via a valid sibling.
    delegated:=delegated||jsonb_build_array(jsonb_build_object('line',1,'reference',grouped.id,
      'carrier',case when group_error is null then grouped.rows->0->>'carrier' else '' end,
      'trackingNumber',case when group_error is null then grouped.rows->0->>'trackingNumber' else '' end));
  end loop;
  if jsonb_array_length(delegated)>0 then
    begin
      completed:=public.admin_import_shipment_tracking_batch(delegated);
      if jsonb_typeof(completed) is distinct from 'array' or jsonb_array_length(completed)<>jsonb_array_length(delegated) then
        raise check_violation using message='tracking_batch_result_missing';end if;
      select jsonb_object_agg(value->>'reference',value) into outcomes from jsonb_array_elements(completed);
    exception when others then
      batch_error:=sqlerrm;
      select jsonb_object_agg(value->>'reference',jsonb_build_object('ok',false,'error',batch_error)) into outcomes from jsonb_array_elements(delegated);
    end;
  end if;

  for input in select value from jsonb_array_elements(normalized) loop
    shipment_key:=(input->>'shipmentId')::uuid;
    if shipment_key is null then outcome:=jsonb_build_object('ok',false,'error',input->>'error');
    elsif group_errors->>shipment_key::text is not null then
      outcome:=jsonb_build_object('ok',false,'error',group_errors->>shipment_key::text);
    else outcome:=outcomes->shipment_key::text;end if;
    if outcome->>'ok'='true' then
      if shipment_key=any(seen) then outcome:=outcome||jsonb_build_object('duplicate',true,'dispatched',false);
      else seen:=array_append(seen,shipment_key);outcome:=outcome||jsonb_build_object('duplicate',false);end if;
    end if;
    results:=results||jsonb_build_array(outcome||jsonb_build_object('line',input->'line','reference',input->>'reference',
      'shipmentId',shipment_key,'orderId',input->'orderId'));
  end loop;
  return results;
end $$

create function public.admin_inquiry_chat_context(p_inquiry_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_customer uuid;
begin
  if (select auth.uid()) is null or not public.has_operator_capability('cs.manage',false) then
    raise insufficient_privilege using message='operator_capability_required';end if;
  select user_id into v_customer from public.inquiries where id=p_inquiry_id;
  if not found then raise no_data_found using message='inquiry_not_found';end if;
  return jsonb_build_object('inquiryId',p_inquiry_id,
    'tags',coalesce((select jsonb_agg(label order by label) from private.inquiry_chat_tags where inquiry_id=p_inquiry_id),'[]'::jsonb),
    'previousCount',(select count(*) from public.inquiries where user_id=v_customer and id<>p_inquiry_id),
    'previous',coalesce((select jsonb_agg(jsonb_build_object('id',prior.id,'reference',prior.reference,'title',prior.title,
      'status',prior.status,'lastMessageAt',prior.last_message_at) order by prior.last_message_at desc,prior.id)
      from (select id,reference,title,status,last_message_at from public.inquiries where user_id=v_customer and id<>p_inquiry_id
        order by last_message_at desc,id limit 20) prior),'[]'::jsonb));
end $$

create function public.admin_update_inquiry_chat_tag(p_expected_actor_id uuid,p_inquiry_id uuid,p_label text,p_present boolean)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v_actor uuid;v_label text:=btrim(coalesce(p_label,''));v_changed integer;
begin
  v_actor:=private.require_operator_capability('cs.manage',false);
  if p_expected_actor_id is distinct from v_actor then raise insufficient_privilege using message='inquiry_chat_actor_changed';end if;
  if p_inquiry_id is null or p_present is null or char_length(v_label) not between 1 and 20 or v_label ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message='invalid_inquiry_chat_tag';end if;
  perform 1 from public.inquiries where id=p_inquiry_id for update;
  if not found then raise no_data_found using message='inquiry_not_found';end if;
  if p_present then
    if not exists(select 1 from private.inquiry_chat_tags where inquiry_id=p_inquiry_id and label=v_label)
      and (select count(*) from private.inquiry_chat_tags where inquiry_id=p_inquiry_id)>=10 then
      raise check_violation using message='inquiry_chat_tag_limit';end if;
    insert into private.inquiry_chat_tags(inquiry_id,label,actor_id) values(p_inquiry_id,v_label,v_actor)
      on conflict(inquiry_id,label) do nothing;
  else
    delete from private.inquiry_chat_tags where inquiry_id=p_inquiry_id and label=v_label;
  end if;
  get diagnostics v_changed=row_count;
  if v_changed>0 then
    insert into public.audit_log(actor_id,action,target,diff) values(v_actor,'admin.inquiry.chat_tag_changed','inquiries:'||p_inquiry_id::text,
      jsonb_build_object('label',v_label,'present',p_present));
  end if;
  return public.admin_inquiry_chat_context(p_inquiry_id);
end $$

do $owner$ declare owner_id oid;entry regprocedure;
begin
  select proowner into owner_id from pg_proc where oid='public.admin_inquiry_chat_console(text,text,text,text,text,text,integer,integer)'::regprocedure;
  if owner_id is null or owner_id in ('anon'::regrole::oid,'authenticated'::regrole::oid,'service_role'::regrole::oid)
    or not exists(select 1 from pg_roles where oid=owner_id and (rolsuper or rolbypassrls)) then raise exception 'inquiry_chat_trusted_owner_required';end if;
  execute format('grant select,insert,delete on private.inquiry_chat_tags to %I',pg_get_userbyid(owner_id));
  foreach entry in array array[
    'public.admin_inquiry_chat_context(uuid)'::regprocedure,'public.admin_update_inquiry_chat_tag(uuid,uuid,text,boolean)'::regprocedure,
    'public.admin_inquiry_chat_console(text,text,text,text,text,text,integer,integer)'::regprocedure
  ] loop
    execute format('alter function %s owner to %I',entry,pg_get_userbyid(owner_id));
