    execute format('grant execute on function %s to authenticated,postgres',entry);
  end loop;
end $owner$

create function public.admin_import_item_tracking_batch(target_rows jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare input jsonb;identified jsonb:='[]';reference_value text;shipment_key uuid;order_key uuid;row_error text;
begin
  perform private.require_operator_capability('sales.manage',false);
  if jsonb_typeof(target_rows) is distinct from 'array' then raise invalid_parameter_value using message='invalid_tracking_batch';end if;
  if jsonb_array_length(target_rows) not between 1 and 1000 then raise invalid_parameter_value using message='invalid_tracking_batch';end if;
  for input in select value from jsonb_array_elements(target_rows) loop
    reference_value:=null;shipment_key:=null;order_key:=null;row_error:=null;
    if jsonb_typeof(input) is distinct from 'object' then row_error:='invalid_tracking_row';
    elsif jsonb_typeof(input->'reference') is distinct from 'string' then row_error:='invalid_item_order_reference';
    else
      reference_value:=btrim(input->>'reference');
      if reference_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then row_error:='invalid_item_order_reference';
      else
        select link.shipment_id,link.order_id into shipment_key,order_key from public.order_shipment_items link where link.order_item_id=reference_value::uuid;
        if shipment_key is null then row_error:='shipment_item_not_found';end if;
      end if;
    end if;
    identified:=identified||jsonb_build_array(jsonb_build_object('line',input->'line','reference',reference_value,
      'shipmentId',shipment_key,'orderId',order_key,'error',row_error));
  end loop;
  if exists(select 1 from jsonb_array_elements(identified) row_value where row_value->>'error' is not null) then
    return(select jsonb_agg(row_value.value||jsonb_build_object('ok',false,
      'error',coalesce(row_value.value->>'error','item_tracking_identity_unresolved')) order by row_value.ordinality)
      from jsonb_array_elements(identified) with ordinality row_value(value,ordinality));
  end if;
  return private.admin_import_item_tracking_batch_before_identity_guard(target_rows);
end $$

create function private.inquiry_file_session(p_actor uuid,p_session uuid,p_staff boolean) returns void language plpgsql security definer set search_path='' as $$begin
 if p_actor is null or p_session is null then raise insufficient_privilege;end if;
 perform private.assert_active_user(p_actor);
 if private.is_account_write_fenced(p_actor) then raise insufficient_privilege;end if;
 perform 1 from auth.sessions where id=p_session and user_id=p_actor and(not_after is null or not_after>clock_timestamp()) for share;
 if not found then raise insufficient_privilege;end if;
 if p_staff then perform private.require_actor_operator_capability(p_actor,'cs.manage');end if;
end $$

create function public.service_prepare_inquiry_file(p_actor uuid,p_session uuid,p_id uuid,p_name text,p_mime text,p_size integer,p_library boolean) returns jsonb
language plpgsql security definer set search_path='' as $$declare f private.inquiry_chat_files;extension text;begin
 perform private.inquiry_file_session(p_actor,p_session,true);extension:=private.inquiry_file_extension(p_mime);
 if p_id is null or p_library is null or p_size is null or p_size not between 1 and 20971520 or extension is null
 or p_name is null or char_length(btrim(p_name)) not between 1 and 160 or p_name~'[[:cntrl:]/\\]' then raise invalid_parameter_value;end if;
 perform pg_advisory_xact_lock(hashtextextended('inquiry-file-library',0));
 select * into f from private.inquiry_chat_files where id=p_id for update;
 if found then
  if f.actor_id is distinct from p_actor or f.session_id<>p_session or f.filename<>btrim(p_name) or f.mime_type<>p_mime or f.size_bytes<>p_size or f.in_library<>p_library then raise sqlstate 'PT409';end if;
  if f.state not in('pending','verified') or f.state='pending' and f.expires_at<=clock_timestamp() then raise check_violation using message='inquiry_file_expired';end if;
 else
  if (select count(*) from private.inquiry_chat_files where actor_id=p_actor and state='pending' and expires_at>clock_timestamp())>=10
   or p_library and (select count(*) from private.inquiry_chat_files where in_library and(state='verified' or state='pending' and expires_at>clock_timestamp()))>=100 then
   raise check_violation using message='inquiry_file_limit';end if;
  insert into private.inquiry_chat_files(id,actor_id,session_id,filename,mime_type,size_bytes,path,in_library,expires_at)
  values(p_id,p_actor,p_session,btrim(p_name),p_mime,p_size,p_actor::text||'/'||p_id::text||'.'||extension,p_library,clock_timestamp()+interval '30 minutes') returning * into f;
 end if;
 return jsonb_build_object('id',f.id,'path',f.path,'state',f.state,'name',f.filename,'mimeType',f.mime_type,'size',f.size_bytes,'sha256',f.sha256);
end $$

-- There are deliberately no storage SELECT/UPDATE/DELETE policies. Files cannot
-- be overwritten, and every private download rechecks the session and message.
create function public.service_read_inquiry_file(p_actor uuid,p_session uuid,p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare f private.inquiry_chat_files;begin
 perform private.inquiry_file_session(p_actor,p_session,true);
 select * into f from private.inquiry_chat_files where id=p_id and actor_id=p_actor and session_id=p_session and state in('pending','verified') and(state='verified' or expires_at>clock_timestamp());
 if not found then raise no_data_found;end if;
 return jsonb_build_object('id',f.id,'path',f.path,'state',f.state,'name',f.filename,'mimeType',f.mime_type,'size',f.size_bytes,'sha256',f.sha256);
end $$

create function public.service_verify_inquiry_file(p_actor uuid,p_session uuid,p_id uuid,p_sha256 text) returns jsonb language plpgsql security definer set search_path='' as $$declare f private.inquiry_chat_files;begin
 perform private.inquiry_file_session(p_actor,p_session,true);
 select * into f from private.inquiry_chat_files where id=p_id and actor_id=p_actor and session_id=p_session for update;
 if not found or p_sha256 is null or p_sha256!~'^[a-f0-9]{64}$' then raise insufficient_privilege;end if;
 if f.state='verified' then if f.sha256<>p_sha256 then raise sqlstate 'PT409';end if;
 elsif f.state='pending' and f.expires_at>clock_timestamp() and exists(select 1 from storage.objects o where o.bucket_id='inquiry-files-private' and o.name=f.path
  and o.metadata->>'mimetype'=f.mime_type and o.metadata->>'size'=f.size_bytes::text) then
  update private.inquiry_chat_files set state='verified',sha256=p_sha256,verified_at=clock_timestamp(),expires_at=clock_timestamp()+interval '24 hours' where id=p_id;
 else raise check_violation using message='inquiry_file_unverified';end if;
 return private.inquiry_file_metadata(array[p_id])->0;
end $$

create function public.admin_inquiry_file_library() returns jsonb language plpgsql volatile security definer set search_path='' as $$begin
 perform private.require_operator_capability('cs.manage',false);
 return private.inquiry_file_metadata(array(select id from private.inquiry_chat_files where in_library and state='verified' order by created_at desc,id));
end $$

create function public.admin_retire_inquiry_file(p_id uuid) returns boolean language plpgsql security definer set search_path='' as $$begin
 perform private.require_operator_capability('cs.manage',false);
 update private.inquiry_chat_files set state='retired',expires_at=clock_timestamp() where id=p_id and state in('pending','verified');
 if found then insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.inquiry.file_removed','inquiry_file:'||p_id,jsonb_build_object('fileId',p_id));return true;end if;
 return exists(select 1 from private.inquiry_chat_files where id=p_id and state='retired');
end $$

create function public.inquiry_message_files(p_inquiry_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$begin
 if auth.uid() is null or not exists(select 1 from public.inquiries where id=p_inquiry_id and(user_id=auth.uid() or public.has_operator_capability('cs.manage',false))) then raise insufficient_privilege;end if;
 return coalesce((select jsonb_object_agg(m.id,private.inquiry_file_metadata(m.file_ids)) from public.inquiry_messages m where m.inquiry_id=p_inquiry_id and cardinality(m.file_ids)>0),'{}'::jsonb);
end $$

create function public.service_inquiry_file_download(p_actor uuid,p_session uuid,p_file uuid,p_message uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare f private.inquiry_chat_files;staff boolean;begin
 perform private.inquiry_file_session(p_actor,p_session,false);staff:=private.has_operator_capability(p_actor,'cs.manage',false);
 select * into f from private.inquiry_chat_files where id=p_file and sha256 is not null and state in('verified','retired');
 if not found then raise insufficient_privilege;end if;
 if p_message is null then
  if not staff or not f.in_library or f.state<>'verified' then raise insufficient_privilege;end if;
 elsif not exists(select 1 from public.inquiry_messages m join public.inquiries i on i.id=m.inquiry_id
  where m.id=p_message and p_file=any(m.file_ids) and(staff or i.user_id=p_actor)) then raise insufficient_privilege;end if;
 return (private.inquiry_file_metadata(array[p_file])->0)||jsonb_build_object('path',f.path,'sha256',f.sha256);
end $$

create function public.admin_send_inquiry_chat_message(p_inquiry uuid,p_body text,p_files uuid[],p_operation uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid();body text:=btrim(coalesce(p_body,''));files uuid[]:=coalesce(p_files,'{}');thread public.inquiries;receipt private.inquiry_chat_send_receipts;request jsonb;message uuid;begin
 perform private.require_operator_capability('cs.manage',false);
 if p_operation is null or p_inquiry is null or char_length(body)>2000 or(body='' and cardinality(files)=0) or cardinality(files)>3
  or array_position(files,null) is not null or cardinality(files)<>(select count(distinct x) from unnest(files)x) then raise invalid_parameter_value;end if;
 request:=jsonb_build_object('inquiryId',p_inquiry,'body',body,'fileIds',files);
 perform pg_advisory_xact_lock(hashtextextended('inquiry-send:'||p_operation::text,0));
 select * into receipt from private.inquiry_chat_send_receipts where operation_id=p_operation;
 if found then
  if receipt.actor_id is distinct from actor or receipt.request is distinct from request then raise sqlstate 'PT409';end if;
  message:=receipt.message_id;
 else
  select * into thread from public.inquiries where id=p_inquiry for update;
  if not found then raise no_data_found using message='inquiry_not_found';end if;
  if thread.status='closed' then raise check_violation using message='inquiry_closed';end if;
  perform id from private.inquiry_chat_files where id=any(files) order by id for share;
  if(select count(*) from private.inquiry_chat_files where id=any(files) and state='verified' and(in_library or actor_id=actor and expires_at>clock_timestamp()))<>cardinality(files) then raise check_violation using message='inquiry_file_unavailable';end if;
  insert into public.inquiry_messages(inquiry_id,author,author_id,body,file_ids) values(p_inquiry,'staff',actor,body,files) returning id into message;
  update public.inquiries set status='answered',handled_by=actor,answered_at=coalesce(answered_at,now()),last_message_at=now() where id=p_inquiry;
  insert into public.notifications(user_id,type,title,body,link_path,source_type,source_id,dedupe_key)
  values(thread.user_id,'inquiry_answered','문의에 답변이 등록됐어요',left('문의 #'||thread.reference::text||' — '||thread.title,500),'/my/inquiries/'||p_inquiry::text,'inquiry',p_inquiry::text,'inquiry:answered:'||message::text) on conflict(user_id,dedupe_key) do nothing;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.inquiry.answered','inquiries:'||p_inquiry,jsonb_build_object('messageId',message,'previousStatus',thread.status,'attachmentCount',cardinality(files),'operationId',p_operation));
  insert into private.inquiry_chat_send_receipts(operation_id,actor_id,inquiry_id,request,message_id) values(p_operation,actor,p_inquiry,request,message);
 end if;
 return(select jsonb_build_object('messageId',message,'recipientId',i.user_id,'recipientEmail',p.email,'reference',i.reference,'title',i.title,'operationId',p_operation) from public.inquiries i join public.profiles p on p.id=i.user_id where i.id=p_inquiry);
end $$

CREATE OR REPLACE FUNCTION public.admin_answer_inquiry(target_inquiry_id uuid, target_body text, target_image_paths text[] DEFAULT '{}'::text[])
 RETURNS TABLE(message_id uuid, recipient_id uuid, recipient_email text, inquiry_reference bigint, inquiry_title text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_body text := btrim(coalesce(target_body, ''));
  v_paths text[];
  v_thread public.inquiries%rowtype;
  v_message_id uuid;
begin
  perform private.require_operator_capability('cs.manage',false);

  if v_actor is null or not public.has_operator_capability('cs.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if char_length(v_body)>2000 or (v_body='' and cardinality(coalesce(target_image_paths,'{}'))=0) then
    raise invalid_parameter_value using message = 'invalid_inquiry_body';
  end if;

  select *
  into v_thread
  from public.inquiries as thread
  where thread.id = target_inquiry_id
  for update;

  if not found then
    raise no_data_found using message = 'inquiry_not_found';
  end if;
  if v_thread.status = 'closed' then
    raise check_violation using message = 'inquiry_closed';
  end if;

  v_paths := private.assert_own_inquiry_image_paths(target_image_paths, v_actor);
  if v_body='' and exists(select 1 from unnest(v_paths) image(path) where not exists(
    select 1 from storage.objects object where object.bucket_id='user-uploads' and object.name=image.path)) then
    raise check_violation using message='inquiry_image_missing';
  end if;

  insert into public.inquiry_messages (inquiry_id, author, author_id, body, image_paths)
  values (target_inquiry_id, 'staff', v_actor, v_body, v_paths)
  returning id into v_message_id;

  update public.inquiries as thread
  set
    status = 'answered',
    handled_by = v_actor,
    answered_at = coalesce(thread.answered_at, now()),
    last_message_at = now()
  where thread.id = target_inquiry_id;

  insert into public.notifications (
    user_id,
    type,
    title,
    body,
    link_path,
    source_type,
    source_id,
    dedupe_key
  )
  values (
    v_thread.user_id,
    'inquiry_answered',
    '문의에 답변이 등록됐어요',
    left('문의 #' || v_thread.reference::text || ' — ' || v_thread.title, 500),
    '/my/inquiries/' || target_inquiry_id::text,
    'inquiry',
    target_inquiry_id::text,
    'inquiry:answered:' || v_message_id::text
  )
  on conflict (user_id, dedupe_key) do nothing;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.inquiry.answered',
    'inquiries:' || target_inquiry_id::text,
    jsonb_build_object(
      'messageId', v_message_id,
      'previousStatus', v_thread.status,
      'attachmentCount', cardinality(v_paths)
    )
  );

  return query
    select
      v_message_id,
      v_thread.user_id,
      profile.email,
      v_thread.reference,
      v_thread.title
    from public.profiles as profile
    where profile.id = v_thread.user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.append_inquiry_message(target_inquiry_id uuid, target_body text, target_image_paths text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_body text := btrim(coalesce(target_body, ''));
  v_paths text[];
  v_status text;
  v_message_id uuid;
begin
  if v_actor is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;
  if char_length(v_body)>2000 or (v_body='' and cardinality(coalesce(target_image_paths,'{}'))=0) then
    raise invalid_parameter_value using message = 'invalid_inquiry_body';
  end if;

  select thread.status
  into v_status
  from public.inquiries as thread
  where thread.id = target_inquiry_id
    and thread.user_id = v_actor
  for update;

  if not found then
    raise no_data_found using message = 'inquiry_not_found';
  end if;

  -- 종결 후 재문의는 새 스레드다. 닫힌 대화를 되살리면 어드민 큐의 처리 이력과
  -- 자동 종결 기준(마지막 답변 시각)이 한 행 안에서 여러 번 뒤집힌다.
  if v_status = 'closed' then
    raise check_violation using message = 'inquiry_closed';
  end if;

  v_paths := private.assert_own_inquiry_image_paths(target_image_paths, v_actor);
  if v_body='' and exists(select 1 from unnest(v_paths) image(path) where not exists(
    select 1 from storage.objects object where object.bucket_id='user-uploads' and object.name=image.path)) then
    raise check_violation using message='inquiry_image_missing';
  end if;

  insert into public.inquiry_messages (inquiry_id, author, author_id, body, image_paths)
  values (target_inquiry_id, 'user', v_actor, v_body, v_paths)
  returning id into v_message_id;

  update public.inquiries as thread
  set
    status = 'open',
    last_message_at = now()
  where thread.id = target_inquiry_id;

  return v_message_id;
end;
$function$

create function public.service_complete_inquiry_file_cleanup(p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin
 perform 1 from private.inquiry_chat_files where id=p_id for update;
 if exists(select 1 from public.inquiry_messages where p_id=any(file_ids)) then raise check_violation;end if;
 update private.inquiry_chat_files set state='cleaned' where id=p_id and state='retired';
end $$

create or replace function private.inquiry_file_session(p_actor uuid,p_session uuid,p_staff boolean) returns void language plpgsql security definer set search_path='' as $$begin
 if p_actor is null or p_session is null then raise insufficient_privilege;end if;
 perform private.lock_account_action_subject(p_actor);
 perform private.assert_active_user(p_actor);
 if private.is_account_write_fenced(p_actor) then raise insufficient_privilege;end if;
 perform 1 from auth.sessions where id=p_session and user_id=p_actor and(not_after is null or not_after>clock_timestamp()) for share;
 if not found then raise insufficient_privilege;end if;
 if p_staff then perform private.require_actor_operator_capability(p_actor,'cs.manage');end if;
end $$

-- The deployed staff-cancellation implementation stays intact. Bind its start to
-- the current operator and persist the right to finish that one provider action.
do $patch$
declare definition text;anchor text;
begin
 if (select md5(prosrc) from pg_proc where oid='public.admin_start_order_cancellation(uuid,text,text,boolean)'::regprocedure)
  is distinct from '673d476cc39b15fe2f9a032db30d2979' then raise exception 'staff_cancellation_release_source_changed';end if;
 definition:=pg_get_functiondef('public.admin_start_order_cancellation(uuid,text,text,boolean)'::regprocedure);
 anchor:=$old$  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff required';
  end if;$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'staff_cancellation_authority_anchor_changed';end if;
 definition:=replace(definition,anchor,$new$  perform private.require_actor_operator_capability(v_actor,'sales.manage',false);$new$);
 anchor:='  returning id into v_request_id;';
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'staff_cancellation_receipt_anchor_changed';end if;
 definition:=replace(definition,anchor,anchor||$new$

  insert into private.operator_cancellation_authorizations(request_id,actor_id)
  values(v_request_id,v_actor) on conflict do nothing;$new$);
 execute definition;
end $patch$

-- Seowon replies omit order identifiers. The app sends only unambiguously
-- matched shipments, so require every member before a single pack can move.
-- Other workbook formats intentionally keep their existing batch semantics.
create function public.admin_import_seowon_tracking_batch(target_origin_id uuid,target_rows jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare origin public.fulfillment_origins;row_value jsonb;sid uuid;ids uuid[]:='{}';scope_ids uuid[];
 shipment public.order_shipments;tracking_value text;carrier_value text;
begin
 perform private.require_operator_capability('sales.manage',false);
 if target_origin_id is null or jsonb_typeof(target_rows) is distinct from 'array'
  or jsonb_array_length(target_rows) not between 1 and 1000 then raise invalid_parameter_value using message='invalid_tracking_batch';end if;
 select * into origin from public.fulfillment_origins where id=target_origin_id;
 if not found then raise no_data_found using message='warehouse_origin_not_found';end if;
 if not origin.is_active or origin.export_template<>'seowon_xlsx' then raise check_violation using message='warehouse_origin_unavailable';end if;
 for row_value in select value from jsonb_array_elements(target_rows) loop
  if jsonb_typeof(row_value) is distinct from 'object' or jsonb_typeof(row_value->'reference') is distinct from 'string'
   or row_value->>'reference'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   raise invalid_parameter_value using message='invalid_tracking_row';end if;
  sid:=(row_value->>'reference')::uuid;
  if sid=any(ids) then raise check_violation using message='duplicate_shipment_reference';end if;
  ids:=array_append(ids,sid);
 end loop;
 scope_ids:=private.lock_shipment_pack_scope(ids);
 perform private.assert_whole_shipment_packs(ids);
 -- Validate all matching/scope evidence before delegating to per-row savepoints.
 for row_value in select value from jsonb_array_elements(target_rows) loop
  sid:=(row_value->>'reference')::uuid;
  select * into strict shipment from public.order_shipments where id=sid;
  carrier_value:=nullif(btrim(row_value->>'carrier'),'');
  tracking_value:=nullif(upper(regexp_replace(btrim(row_value->>'trackingNumber'),'[[:space:]-]','','g')),'');
  if shipment.origin_id<>origin.id then raise check_violation using message='warehouse_origin_mismatch';end if;
  if shipment.delivery_method<>'parcel' then raise check_violation using message='delivery_method_evidence_required';end if;
  if carrier_value is distinct from origin.default_carrier or tracking_value is null then
   raise check_violation using message='invalid_tracking_row';end if;
  if shipment.status='ready' then
   if shipment.exported_at is null then raise check_violation using message='shipment_not_exported';end if;
   if exists(select 1 from public.order_shipments where id=any(private.shipment_pack_scope(array[sid])) and status<>'ready') then
    raise check_violation using message='shipment_tracking_conflict';end if;
   perform private.assert_order_dispatch_allowed(shipment.order_id);
   perform private.assert_shipment_preorder_ready(sid);
   if(private.shipment_production_summary(sid)->>'ready')::boolean is distinct from true then
    raise check_violation using message='production_incomplete';end if;
  elsif shipment.status not in('shipping','delivered') or exists(select 1 from public.orders where id=shipment.order_id and status='canceled') then
   raise check_violation using message='order_not_shipped';
  elsif shipment.carrier is distinct from carrier_value or shipment.tracking_number is distinct from tracking_value then
   raise check_violation using message='shipment_tracking_conflict';
  end if;
 end loop;
 perform private.prepare_pack_tracking_batch(target_rows);
 return public.admin_import_shipment_tracking_batch(target_rows);
end $$

revoke all on function public.admin_start_order_cancellation(uuid,text,text,boolean),
 public.admin_origin_tracking_candidates(uuid,text[],text[]),public.admin_origin_pending_export_ids(uuid),
 public.admin_import_seowon_tracking_batch(uuid,jsonb) from public,anon,authenticated,service_role

grant execute on function public.admin_start_order_cancellation(uuid,text,text,boolean),
 public.admin_origin_tracking_candidates(uuid,text[],text[]),public.admin_origin_pending_export_ids(uuid),
 public.admin_import_seowon_tracking_batch(uuid,jsonb) to authenticated

create function private.next_commerce_number(p_created_at timestamptz,p_kind smallint)
returns text language plpgsql security definer set search_path='' as $$
declare business_day date := (p_created_at at time zone 'Asia/Seoul')::date; n integer;
begin
  if business_day is null or not isfinite(business_day) or business_day not between date '2000-01-01' and date '9999-12-31'
    or p_kind is null or p_kind not in (1,2,3) then
    raise invalid_parameter_value using message='invalid_commerce_number_input';
  end if;
  insert into private.commerce_number_counters as counter(business_date,kind,last_value)
    values(business_day,p_kind,1)
    on conflict(business_date,kind) do update set last_value=counter.last_value+1
    returning last_value into n;
  return to_char(business_day,'YYYYMMDD')||p_kind::text||lpad(n::text,7,'0');
end $$

do $$declare entry record;begin
  for entry in select * from commerce_number_trigger_states where tgenabled<>'D' loop
    execute format('alter table %s disable trigger %I',entry.tgrelid::regclass,entry.tgname);
  end loop;
end $$

do $$declare entry record;begin
  for entry in select * from commerce_number_trigger_states where tgenabled<>'D' loop
    execute format('alter table %s %s trigger %I',entry.tgrelid::regclass,
      case entry.tgenabled when 'A' then 'enable always' when 'R' then 'enable replica' else 'enable' end,entry.tgname);
  end loop;
end $$

create function private.assign_commerce_number() returns trigger
language plpgsql security definer set search_path='' as $$
declare column_name text := tg_argv[0]; kind smallint := tg_argv[1]::smallint; created timestamptz; number text;
begin
  if tg_op='UPDATE' then
    if (to_jsonb(new)->>column_name) is distinct from (to_jsonb(old)->>column_name) then
      raise check_violation using message='commerce_number_immutable';
    end if;
    return new;
  end if;
  if to_jsonb(new)->>column_name is not null then
    raise check_violation using message='commerce_number_is_generated';
  end if;
  if kind=1 then created:=new.created_at;
  else select created_at into strict created from public.orders where id=new.order_id;end if;
  number:=private.next_commerce_number(created,kind);
  new:=jsonb_populate_record(new,jsonb_build_object(column_name,number));
  return new;
end $$

-- Preserve the existing role, filter, gift, claim and dispatch contracts. Each
-- replacement has an exact anchor count so a changed upstream reader fails.
create function pg_temp.patch_commerce_reader(signature text,anchor text,replacement text,expected integer default 1)
returns void language plpgsql as $$
declare definition text;
begin
  definition:=pg_get_functiondef(signature::regprocedure);
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>expected then
    raise exception 'commerce_number_reader_anchor_changed: % / %',signature,anchor;
  end if;
  execute replace(definition,anchor,replacement);
end $$

-- Existing deployed readers validate exact JSON keys. Opt-in read RPCs keep
-- those responses and frozen mutation receipts valid during DB-first rollout.
create function pg_temp.copy_commerce_reader(signature text,target_name text)
returns void language plpgsql as $$
declare source regprocedure:=signature::regprocedure; schema_name text; source_name text; definition text; target regprocedure;
begin
  select n.nspname,p.proname,pg_get_functiondef(p.oid) into schema_name,source_name,definition
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.oid=source;
  execute replace(definition,format('CREATE OR REPLACE FUNCTION %I.%I(',schema_name,source_name),
    format('CREATE OR REPLACE FUNCTION %I.%I(',schema_name,target_name));
  select format('%I.%I(%s)',schema_name,target_name,oidvectortypes(proargtypes))::regprocedure into target from pg_proc where oid=source;
  execute format('revoke all on function %s from public,anon,authenticated,service_role',target);
  if has_function_privilege('authenticated',source,'execute') then
    execute format('grant execute on function %s to authenticated',target);
  end if;
end $$

do $$declare signature text;begin
  foreach signature in array array[
    'private.admin_search_shipments_console_before_custom_inputs(text,uuid,text,date,date,integer,integer,text,text,text,text,text)',
    'public.admin_search_shipments_notice_console(text,uuid,text,date,date,integer,integer,text,text,text,text,text,text)'
  ] loop
    perform pg_temp.patch_commerce_reader(signature,$a$position(lower(needle) in s.id::text)>0$a$,
      $a$(position(lower(needle) in s.id::text)>0 or position(needle in s.shipment_number)>0)$a$);
    perform pg_temp.patch_commerce_reader(signature,$a$position(lower(needle) in o.id::text)>0$a$,
      $a$(position(lower(needle) in o.id::text)>0 or position(needle in o.order_number)>0)$a$);
    perform pg_temp.patch_commerce_reader(signature,'o.created_at order_created_at,','o.created_at order_created_at,o.order_number,');
    perform pg_temp.patch_commerce_reader(signature,$a$'id',id,'orderId',order_id,'originId'$a$,
      $a$'id',id,'orderId',order_id,'orderNumber',order_number,'shipmentNumber',shipment_number,'originId'$a$);
    perform pg_temp.patch_commerce_reader(signature,$a$'id',i.id,'name',i.good_name_snapshot$a$,
      $a$'id',i.id,'productOrderNumber',i.product_order_number,'name',i.good_name_snapshot$a$);
  end loop;
end $$

create function public.admin_import_item_tracking_batch(target_rows jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare input jsonb; normalized jsonb:='[]'; result jsonb; number text; item_id uuid;
begin
  perform private.require_operator_capability('sales.manage',false);
  if jsonb_typeof(target_rows) is distinct from 'array' or jsonb_array_length(target_rows) not between 1 and 1000 then
    raise invalid_parameter_value using message='invalid_tracking_batch';end if;
  for input in select value from jsonb_array_elements(target_rows) loop
    number:=case when jsonb_typeof(input->'reference')='string' then btrim(input->>'reference') end;
    if number ~ '^[0-9]{8}2[0-9]{7}$' then
      select id into item_id from public.order_items where product_order_number=number;
      -- Leave unresolved numbers unchanged: the identity guard rejects the
      -- whole batch, including valid siblings, before delegating any writes.
      if item_id is not null then input:=jsonb_set(input,'{reference}',to_jsonb(item_id::text));end if;
    end if;
    normalized:=normalized||jsonb_build_array(input);
  end loop;
  result:=private.admin_import_item_tracking_batch_before_numbers(normalized);
  if jsonb_typeof(result) is distinct from 'array' or jsonb_array_length(result)<>jsonb_array_length(target_rows) then
    raise check_violation using message='tracking_batch_result_missing';end if;
  return (select jsonb_agg(outcome.value||case when jsonb_typeof(target_rows->(outcome.ordinality::integer-1)->'reference')='string'
      then jsonb_build_object('reference',btrim(target_rows->(outcome.ordinality::integer-1)->>'reference')) else '{}'::jsonb end order by outcome.ordinality)
    from jsonb_array_elements(result) with ordinality outcome(value,ordinality));
end $$

select pg_temp.patch_commerce_reader('private.resolve_shipment_reference(text)',
