-- 캠페인 본문 블록에 `cta`(이동 버튼)를 더한다 (LFS 패리티 2차 L10 · 11 §8 EV-03 · 12 §4 LD-18).
--
-- 블록 모양: { "type": "cta", "label": "<버튼 문구 1~30자>", "href": "<ICONS 내부 경로 1~300자>" }
-- (모든 블록처럼 선택 키 anchor 1~20자를 받는다.)
--
-- ## 링크는 ICONS 안의 경로만 받는다 (LD-18)
--
-- 외부 링크는 피싱·추적 위험이 있어 운영자 편성으로 열지 않는다. 필요해지면 허용 도메인
-- 목록을 따로 정한다. 판정은 lib/campaigns.ts isCampaignInternalHref 와 1:1이다.
--   - `/` 로 시작해야 한다 — 스킴(`https:`·`javascript:`)과 도메인 주소는 여기서 걸러진다.
--   - `//` 로 시작하면 안 된다 — 브라우저가 프로토콜 상대 주소(다른 호스트)로 읽는다.
--   - 역슬래시·공백·제어문자(0x01–0x20, 0x7F)는 어디에도 둘 수 없다. 브라우저 URL 파서가
--     `\`를 `/`로 바꾸고 탭·줄바꿈을 지우므로 `/\evil.example`·`/<TAB>/evil.example`이
--     `//evil.example`로 바뀐다.
--   - `.`·`..` 경로 조각(`%2e` 포함, 대소문자 무시)도 받지 않는다. `/..//evil.example`은 같은
--     출처지만 정규화된 pathname 이 `//evil.example`이 되어, pathname 을 다시 주소로 읽는
--     소비자가 프로토콜 상대 주소로 오해한다.
--   - `%` 뒤에는 16진수 두 자리가 와야 한다(`%zz`·끝의 `%A` 같은 깨진 인코딩은 라우터가 400 으로 끊는다).
--   - label 은 공백만으로 채울 수 없다(그릴 문구가 없는 버튼). 공백의 범위는 JS String.prototype.trim 과
--     같다 — 유니코드 공백(U+00A0·U+3000·U+FEFF 등)만 든 문구도 어드민 폼과 공개 파서가 버리므로 여기서 막는다.
--
-- ## 바뀌는 것은 private 검증 함수 하나다
--
-- admin_upsert_campaign(운영자 RPC 계약 20261020085215:16767)은 본문 검증을
-- private.validate_campaign_sections에 맡긴다. 그 함수 본문만 바꾸므로 공개 RPC의 본문·ACL·
-- 운영자 계약 해시는 그대로다. 기존 캠페인 본문은 이전 8종 규칙을 통과한 값이라 새 규칙에서도
-- 그대로 유효하다(블록 종류를 더할 뿐 기존 블록의 규칙은 바꾸지 않는다).

create or replace function private.validate_campaign_sections(p_sections jsonb)
returns void
language plpgsql
stable
set search_path = ''
as $$
declare
  c_types constant text[] := array[
    'intro', 'image', 'text', 'attendance', 'exchange', 'coupon', 'goods', 'notice', 'cta'
  ];
  v_index integer := -1;
  v_section jsonb;
  v_type text;
  v_allowed text[];
  v_required text[];
  v_text_keys text[];
  v_text_limits integer[];
  v_key text;
begin
  if p_sections is null or jsonb_typeof(p_sections) <> 'array' then
    raise exception 'invalid_sections'
      using errcode = '22023', detail = 'sections: not a json array';
  end if;

  if jsonb_array_length(p_sections) > 20 then
    raise exception 'invalid_sections'
      using errcode = '22023',
        detail = format('sections: at most 20 blocks (got %s)', jsonb_array_length(p_sections));
  end if;

  for v_section in select entry from jsonb_array_elements(p_sections) as element(entry)
  loop
    v_index := v_index + 1;

    if jsonb_typeof(v_section) <> 'object' then
      raise exception 'invalid_sections'
        using errcode = '22023', detail = format('sections[%s]: not an object', v_index);
    end if;

    if jsonb_typeof(v_section -> 'type') is distinct from 'string'
       or not ((v_section ->> 'type') = any (c_types)) then
      raise exception 'invalid_sections'
        using errcode = '22023', detail = format('sections[%s].type: unknown block type', v_index);
    end if;

    v_type := v_section ->> 'type';

    -- anchor는 모든 블록의 선택 키다(상세 페이지 목차 링크).
    if v_section ? 'anchor'
       and (
         jsonb_typeof(v_section -> 'anchor') <> 'string'
         or char_length(v_section ->> 'anchor') not between 1 and 20
       ) then
      raise exception 'invalid_sections'
        using errcode = '22023', detail = format('sections[%s].anchor: invalid', v_index);
    end if;

    v_text_keys := null;
    v_text_limits := null;

    case v_type
      when 'intro' then
        v_required := array['copy'];
        v_allowed := array['copy'];
        v_text_keys := array['copy'];
        v_text_limits := array[500];
      when 'image' then
        v_required := array['image_path', 'alt'];
        v_allowed := array['image_path', 'alt'];
        v_text_keys := array['image_path', 'alt'];
        v_text_limits := array[300, 200];
      when 'text' then
        v_required := array['body'];
        v_allowed := array['heading', 'body'];
        v_text_keys := array['heading', 'body'];
        v_text_limits := array[120, 2000];
      when 'attendance' then
        v_required := array[]::text[];
        v_allowed := array[]::text[];
      when 'exchange' then
        v_required := array['offer_id'];
        v_allowed := array['offer_id'];
        v_text_keys := array['offer_id'];
        v_text_limits := array[36];
      when 'coupon' then
        v_required := array['coupon_code'];
        v_allowed := array['coupon_code', 'description'];
        v_text_keys := array['coupon_code', 'description'];
        v_text_limits := array[24, 200];
      when 'goods' then
        v_required := array['good_ids'];
        v_allowed := array['good_ids'];
      when 'cta' then
        v_required := array['label', 'href'];
        v_allowed := array['label', 'href'];
        v_text_keys := array['label', 'href'];
        v_text_limits := array[30, 300];
      else
        -- 'notice'
        v_required := array['items'];
        v_allowed := array['items'];
    end case;

    -- 모르는 키는 통과시키지 않는다. 오타 하나가 조용히 저장되면 화면에서만
    -- 빈 블록으로 보이고, 원인을 데이터에서 찾아야 한다.
    for v_key in select object_key from jsonb_object_keys(v_section) as keys(object_key)
    loop
      if v_key not in ('type', 'anchor') and not (v_key = any (v_allowed)) then
        raise exception 'invalid_sections'
          using errcode = '22023',
            detail = format('sections[%s].%s: unexpected key for type %s', v_index, v_key, v_type);
      end if;
    end loop;

    foreach v_key in array v_required
    loop
      if not (v_section ? v_key) then
        raise exception 'invalid_sections'
          using errcode = '22023',
            detail = format('sections[%s].%s: required for type %s', v_index, v_key, v_type);
      end if;
    end loop;

    for v_cursor in 1 .. coalesce(array_length(v_text_keys, 1), 0)
    loop
      if v_section ? v_text_keys[v_cursor]
         and (
           jsonb_typeof(v_section -> v_text_keys[v_cursor]) <> 'string'
           or char_length(v_section ->> v_text_keys[v_cursor]) not between 1 and v_text_limits[v_cursor]
         ) then
        raise exception 'invalid_sections'
          using errcode = '22023',
            detail = format(
              'sections[%s].%s: expected a string of 1..%s characters',
              v_index, v_text_keys[v_cursor], v_text_limits[v_cursor]
            );
      end if;
    end loop;

    -- 교환 블록은 coin_exchange_offers 행을 가리킨다. FK를 걸 수 없는 자리라
    -- 최소한 형식은 확인한다 — 상세 페이지가 uuid 캐스팅에서 터지지 않게.
    if v_type = 'exchange'
       and (v_section ->> 'offer_id')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'invalid_sections'
        using errcode = '22023',
          detail = format('sections[%s].offer_id: not a uuid', v_index);
    end if;

    -- 이동 버튼은 ICONS 안의 경로만 가리킨다(LD-18). 문자열 형식·길이는 위에서 확인했다.
    -- 판정은 lib/campaigns.ts isCampaignInternalHref 와 같다.
    if v_type = 'cta'
       and (
         left(v_section ->> 'href', 1) <> '/'
         or left(v_section ->> 'href', 2) = '//'
         or (v_section ->> 'href') ~ '[\x01-\x20\x7f\\]'
         or (v_section ->> 'href') ~* '(^|/)(\.|%2e){1,2}(/|[?#]|$)'
         or (v_section ->> 'href') ~ '%(?![0-9A-Fa-f]{2})'
       ) then
      raise exception 'invalid_sections'
        using errcode = '22023',
          detail = format('sections[%s].href: must be an internal path starting with /', v_index);
    end if;

    -- 공백 집합은 JS trim 과 같다(WhiteSpace·LineTerminator — Zs 전부·TAB·VT·FF·LF·CR·LS·PS·ZWNBSP).
    if v_type = 'cta' and btrim(
      v_section ->> 'label',
      E' \t\n\v\f\r\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'
    ) = '' then
      raise exception 'invalid_sections'
        using errcode = '22023',
          detail = format('sections[%s].label: must not be blank', v_index);
    end if;

    if v_type = 'goods'
       and (
         jsonb_typeof(v_section -> 'good_ids') <> 'array'
         or jsonb_array_length(v_section -> 'good_ids') not between 1 and 8
         or exists (
           select 1
           from jsonb_array_elements(v_section -> 'good_ids') as entries(entry)
           where jsonb_typeof(entries.entry) <> 'string'
             or char_length(entries.entry #>> '{}') not between 1 and 120
         )
       ) then
      raise exception 'invalid_sections'
        using errcode = '22023',
          detail = format('sections[%s].good_ids: expected 1..8 non-empty strings', v_index);
    end if;

    if v_type = 'notice'
       and (
         jsonb_typeof(v_section -> 'items') <> 'array'
         or jsonb_array_length(v_section -> 'items') not between 1 and 20
         or exists (
           select 1
           from jsonb_array_elements(v_section -> 'items') as entries(entry)
           where jsonb_typeof(entries.entry) <> 'string'
             or char_length(entries.entry #>> '{}') not between 1 and 300
         )
       ) then
      raise exception 'invalid_sections'
        using errcode = '22023',
          detail = format('sections[%s].items: expected 1..20 strings of 1..300 characters', v_index);
    end if;
  end loop;
end;
$$

-- ── 4. ② 옵션 행의 재고로 살 수 없음→살 수 있음 전이 ────────────────
create function private.notify_goods_variant_restock()
returns trigger
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  target_good public.goods;
begin
  -- 트리거 WHEN 과 같은 조건이다. 함수가 다른 자리에 다시 쓰여도 뜻이 바뀌지 않게 여기서도 본다.
  -- 예약판매 옵션에 실물이 입고돼도(할당 전 재고 조정) 재고 판매가 아니라 깨우지 않는다. 재고 판매로
  -- 바꾸는 순간(preorder_policy_id → null) 재고가 남아 있으면 그때가 이 옵션의 재입고다.
  if not (new.archived_at is null and new.preorder_policy_id is null and new.stock_qty > 0)
    or (old.archived_at is null and old.preorder_policy_id is null and old.stock_qty > 0) then
    return null;
  end if;

  -- 굿즈 행을 잠근 뒤에 신청을 본다. 신청 RPC 는 같은 행을 for share 로 잡은 채 판정·삽입하므로
  -- 잠그지 않고 보면 커밋 직전의 신청을 놓쳐 그 신청이 다음 사이클까지 침묵한다. 재고를 쓰는
  -- 경로는 이미 이 행을 잠갔고(재고 캐시 갱신 트리거도 같은 잠금을 잡는다) 잠금 순서도 그대로다.
  select * into target_good from public.goods where id = new.good_id for update;
  if not found then
    return null;
  end if;

  -- 재고 외 판매 가능 조건(판매 기간 포함). 재고 조건은 이 옵션의 전이 자체다. 닫혀 있으면 신청은 pending 으로
  -- 남고, 조건이 다시 열릴 때 ① 트리거나 청소 작업이 깨운다.
  if not private.restock_parent_open(target_good) then
    return null;
  end if;

  perform private.wake_restock_alerts(target_good, new.id);
  return null;
end;
$$

-- ── 5. 신청 RPC ─────────────────────────────────────────────────────
-- 굿즈 단위(모든 옵션) 신청. 시그니처·권한·에러 코드는 그대로다. 바뀐 것:
--   · 유일성이 (user, good, variant) 라 충돌 대상에 옵션 키(null)를 더한다.
--   · "판매 중" 판정은 재고로 살 수 있는 옵션(사용 중·재고 판매·재고 > 0)이 있는가다 — 깨우는 술어와
--     같아서, 받아들인 신청은 언제나 다음 전이로 깨어날 수 있다. goods.stock_qty 는 보관 옵션 재고와
--     예약판매 옵션의 실물 입고분까지 더한 캐시라, 그 값만 보면 공개 화면은 품절(재입고 CTA)인데
--     신청은 good_available 로 거절됐다. 그런 재고가 없는 굿즈에서는 이전과 같은 판정이다.
--     공개 상세는 열린 예약판매도 판매 중으로 보지만 그때 CTA 는 재입고가 아니라 담기·구매다.
--   · 탈퇴 신청으로 쓰기가 봉인된 계정의 신청을 거절한다(계정 fence 관례, 20260813193000).
create or replace function public.request_restock_alert(target_good_id text)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  good_stock text;
  good_archived_at timestamptz;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if private.is_account_write_fenced(actor_id) then
    raise object_not_in_prerequisite_state using message = 'account_deletion_write_fenced';
  end if;

  -- 판정과 신청 사이에 재입고 전이가 끼지 않도록 굿즈 행을 잠근다(전이 쪽은 for update).
  select good.stock, good.archived_at
  into good_stock, good_archived_at
  from public.goods as good
  where good.id = target_good_id
  for share;

  if not found or good_archived_at is not null then
    raise exception 'good_missing' using errcode = 'P0002';
  end if;

  -- 판매 중인 굿즈에 신청이 붙으면 전이 조건(거짓→참)이 영영 성립하지 않는다.
  if good_stock <> 'soldout' and exists (
    select 1 from public.goods_variants as variant
    where variant.good_id = target_good_id
      and variant.archived_at is null
      and variant.preorder_policy_id is null
      and variant.stock_qty > 0
  ) then
    raise exception 'good_available' using errcode = '22023';
  end if;

  insert into public.restock_alerts (user_id, good_id, variant_id)
  values (actor_id, target_good_id, null)
  on conflict (user_id, good_id, variant_id)
  do update set status = 'pending', notified_at = null, created_at = now();
end;
$$

-- 옵션 단위 신청(PD-11). 굿즈는 판매 중이고 고른 옵션만 품절일 때 쓴다.
-- 예약판매 옵션은 재고가 아니라 예약 기간·물량으로 열리고 닫혀 재입고 알림 대상이 아니다. 재고 판매일 때
-- 받아 둔 신청이 그 뒤 예약판매로 바뀐 옵션에 남으면, 재고 판매로 돌아와 재고가 있을 때 깨어난다(②).
create function public.request_variant_restock_alert(target_good_id text, target_variant_id uuid)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor_id uuid := (select auth.uid());
  good_stock text;
  good_archived_at timestamptz;
  variant_stock_qty integer;
  variant_archived_at timestamptz;
  variant_preorder_policy_id uuid;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if target_good_id is null or target_variant_id is null then
    raise exception 'variant_missing' using errcode = 'P0002';
  end if;

  if private.is_account_write_fenced(actor_id) then
    raise object_not_in_prerequisite_state using message = 'account_deletion_write_fenced';
  end if;

  -- 굿즈 단위 신청과 같은 잠금. 옵션 행은 잠그지 않는다 — 재고를 쓰는 경로가 굿즈 → 옵션
  -- 순서로 잠그고, 옵션 재고 갱신 트리거와 옵션 전이 트리거가 굿즈 행을 for update 로 다시
  -- 잡으므로 이 잠금 하나로 판정·삽입과 전이가 직렬화된다.
  select good.stock, good.archived_at
  into good_stock, good_archived_at
  from public.goods as good
  where good.id = target_good_id
  for share;

  if not found or good_archived_at is not null then
    raise exception 'good_missing' using errcode = 'P0002';
  end if;

  select variant.stock_qty, variant.archived_at, variant.preorder_policy_id
  into variant_stock_qty, variant_archived_at, variant_preorder_policy_id
  from public.goods_variants as variant
  where variant.id = target_variant_id
    and variant.good_id = target_good_id;

  if not found or variant_archived_at is not null then
    raise exception 'variant_missing' using errcode = 'P0002';
  end if;

  if variant_preorder_policy_id is not null then
    raise exception 'variant_preorder' using errcode = '22023';
  end if;

  if good_stock <> 'soldout' and variant_stock_qty > 0 then
    raise exception 'variant_available' using errcode = '22023';
  end if;

  insert into public.restock_alerts (user_id, good_id, variant_id)
  values (actor_id, target_good_id, target_variant_id)
  on conflict (user_id, good_id, variant_id)
  do update set status = 'pending', notified_at = null, created_at = now();
end;
$$

create function private.is_valid_home_notice_payload(candidate_kind text, candidate jsonb, candidate_link text)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
declare
  label text;
begin
  if candidate_kind is null or candidate_kind not in ('notice_bar', 'notice_strip') then return true; end if;
  if candidate is not null and pg_catalog.jsonb_typeof(candidate) <> 'object' then return false; end if;

  if candidate_kind = 'notice_strip' then
    if candidate is null then return true; end if;
    if exists (
      select 1 from pg_catalog.jsonb_object_keys(candidate) as keys(key)
      where key not in ('mobile_image_path', 'page_types')
    ) then
      return false;
    end if;
    return not (candidate ? 'page_types')
      or private.is_valid_home_notice_page_types(candidate -> 'page_types');
  end if;

  if candidate is null or not (candidate ? 'page_types') then return false; end if;
  if exists (
    select 1 from pg_catalog.jsonb_object_keys(candidate) as keys(key)
    where key not in ('cta_label', 'page_types')
  ) then
    return false;
  end if;
  if not private.is_valid_home_notice_page_types(candidate -> 'page_types') then return false; end if;
  -- A button needs a destination and a destination needs a visible button.
  if candidate_link is null then return not (candidate ? 'cta_label'); end if;
  if not (candidate ? 'cta_label') or pg_catalog.jsonb_typeof(candidate -> 'cta_label') <> 'string' then
    return false;
  end if;
  label := candidate ->> 'cta_label';
  return label = pg_catalog.btrim(label)
    and pg_catalog.char_length(label) between 1 and 12
    and label !~ '[[:cntrl:]]';
end $$

-- Shared write core: notice_bar kind, notice payload whitelist/normalization.
create or replace function private.save_home_curation(target_operation_id uuid, target_curation_id uuid, target_kind text, target_ip_id text, target_title text, target_image_path text, target_link_path text, target_display_order integer, target_active_from timestamp with time zone, target_active_to timestamp with time zone, target_enabled boolean, target_slot text, target_payload jsonb, target_expected_updated_at timestamp with time zone, require_saved_version boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  -- Alias with a column-safe name: inside the claim UPDATE below, a bare
  -- actor_id would be ambiguous against admin_artwork_upload_claims.actor_id.
  claim_owner_id uuid := actor_id;
  normalized_kind text := pg_catalog.btrim(target_kind);
  normalized_ip_id text := nullif(pg_catalog.btrim(target_ip_id), '');
  normalized_title text := pg_catalog.btrim(target_title);
  normalized_image_path text := nullif(pg_catalog.btrim(target_image_path), '');
  normalized_link_path text := nullif(pg_catalog.btrim(target_link_path),'');
  normalized_slot text := nullif(pg_catalog.btrim(target_slot), '');
  normalized_payload jsonb := case
    when target_payload is null or target_payload = '{}'::jsonb then null
    else target_payload
  end;
  allowed_payload_keys text[];
  payload_key text;
  payload_text_value text;
  payload_good_ids jsonb;
  payload_good_id_limit integer;
  payload_good_id text;
  payload_mobile_image_path text;
  previous_mobile_image_path text;
  referenced_archived_at timestamptz;
  request_payload jsonb;
  previous_payload jsonb := 'null'::jsonb;
  after_payload jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  previous_curation public.home_curations%rowtype;
  curation_exists boolean := false;
begin
  perform private.require_operator_capability('store.manage',false);

  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  perform 1 from public.profiles where id=actor_id and role in ('staff','admin') and suspended_at is null for share;
  if not found then
    raise insufficient_privilege using message = 'forbidden';
  end if;

  if target_operation_id is null then
    raise null_value_not_allowed using message = 'invalid_operation_id';
  end if;
  if target_curation_id is null then
    raise null_value_not_allowed using message = 'invalid_curation_id';
  end if;
  if normalized_kind is null
    or normalized_kind not in (
      'hero', 'featured_ip', 'announcement',
      'notice_strip', 'notice_bar', 'editor_pick', 'band_banner', 'best_tab', 'benefit', 'sales_best', 'review_best', 'product_mosaic', 'product_collection'
    )
  then
    raise invalid_parameter_value using message = 'invalid_curation_kind';
  end if;
  if normalized_title is null
    or pg_catalog.char_length(normalized_title) not between (case when normalized_kind='hero' then 0 else 1 end) and 120
    or (normalized_kind in ('sales_best','review_best','product_mosaic','product_collection') and pg_catalog.char_length(normalized_title)>15)
    -- The text notice bar is one short line of copy in the global shell.
    or (normalized_kind='notice_bar' and (pg_catalog.char_length(normalized_title)>60 or normalized_title ~ '[[:cntrl:]]'))
  then
    raise invalid_parameter_value using message = 'invalid_curation_title';
  end if;
  if normalized_kind = 'featured_ip' and normalized_ip_id is null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind <> 'featured_ip' and normalized_ip_id is not null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind in ('hero', 'notice_strip', 'editor_pick', 'band_banner')
    and normalized_image_path is null
  then
    raise check_violation using message = 'curation_image_required';
  end if;
  if normalized_kind = 'notice_bar' and normalized_image_path is not null then
    raise invalid_parameter_value using message = 'invalid_curation_notice';
  end if;
  if normalized_image_path is not null
    and normalized_image_path !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  then
    raise check_violation using message = 'invalid_curation_image_path';
  end if;
  if (normalized_link_path is null and normalized_kind not in ('hero','product_collection','notice_bar'))
    or (normalized_kind='product_collection' and normalized_link_path is not null)
    or (normalized_link_path is not null and not private.is_safe_home_curation_link(normalized_link_path))
  then
    raise invalid_parameter_value using message = 'invalid_curation_link_path';
  end if;
  if target_display_order is null or target_display_order < 0 then
    raise invalid_parameter_value using message = 'invalid_curation_display_order';
  end if;
  if target_active_from is null then
    raise null_value_not_allowed using message = 'invalid_curation_active_from';
  end if;
  if not pg_catalog.isfinite(target_active_from) then
    raise invalid_parameter_value using message = 'invalid_curation_active_from';
  end if;
  if target_active_to is not null
    and (
      not pg_catalog.isfinite(target_active_to)
      or target_active_to <= target_active_from
    )
  then
    raise check_violation using message = 'invalid_curation_active_window';
  end if;
  if target_enabled is null then
    raise null_value_not_allowed using message = 'invalid_curation_enabled';
  end if;

  if normalized_kind = 'best_tab' then
    if normalized_slot is null or normalized_slot not in ('category', 'popular') then
      raise invalid_parameter_value using message = 'invalid_curation_slot';
    end if;
  elsif normalized_slot is not null then
    raise invalid_parameter_value using message = 'invalid_curation_slot';
  end if;

  -- Per-kind payload whitelist. Unknown keys are rejected outright so typos
  -- never ship silently dead configuration.
  allowed_payload_keys := case normalized_kind
    when 'hero' then array['subtitle', 'mobile_image_path', 'alt_enabled', 'alt_title', 'alt_content', 'image_dim', 'text_color']
    when 'notice_strip' then array['mobile_image_path', 'page_types']
    when 'notice_bar' then array['cta_label', 'page_types']
    when 'editor_pick' then array['badge', 'description']
    when 'band_banner' then array['subcopy', 'good_ids']
    when 'best_tab' then array['good_ids', 'selection_mode', 'item_count']
    when 'benefit' then array['description']
    when 'sales_best' then array['exposure_mode','period']
    when 'review_best' then array['selection_mode','good_ids']
    when 'product_mosaic' then array['mosaic_title','mosaic_subtitle','slots']
    when 'product_collection' then array['layout','image_shape','item_count','good_ids']
    else array[]::text[]
  end;

  if normalized_payload is not null then
    if pg_catalog.jsonb_typeof(normalized_payload) <> 'object' then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    if pg_catalog.cardinality(allowed_payload_keys) = 0 then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    for payload_key in
      select key from pg_catalog.jsonb_object_keys(normalized_payload) as keys(key)
    loop
      if not payload_key = any (allowed_payload_keys) then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
    end loop;

    for payload_key in
      select unnest from pg_catalog.unnest(array['subtitle', 'badge', 'description', 'subcopy'])
    loop
      if normalized_payload ? payload_key then
        if pg_catalog.jsonb_typeof(normalized_payload -> payload_key) <> 'string' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        payload_text_value := pg_catalog.btrim(normalized_payload ->> payload_key);
        if pg_catalog.char_length(payload_text_value) not between 1 and 200
          or (payload_key = 'badge' and pg_catalog.char_length(payload_text_value) > 20)
        then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        normalized_payload := pg_catalog.jsonb_set(
          normalized_payload, array[payload_key], pg_catalog.to_jsonb(payload_text_value)
        );
      end if;
    end loop;

    if normalized_payload ? 'good_ids' then
      payload_good_ids := normalized_payload -> 'good_ids';
      payload_good_id_limit := case normalized_kind when 'best_tab' then 12 when 'review_best' then 20 when 'product_collection' then 100 else 4 end;
      if pg_catalog.jsonb_typeof(payload_good_ids) <> 'array'
        or pg_catalog.jsonb_array_length(payload_good_ids) not between (case when normalized_kind in ('review_best','product_collection') then 0 else 1 end) and payload_good_id_limit
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      for payload_good_id in
        select value from pg_catalog.jsonb_array_elements_text(payload_good_ids) as elements(value)
      loop
        if payload_good_id !~ '^[A-Za-z0-9_-]{1,64}$' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
      end loop;
    end if;

    -- Automatic selection is a rule, never a saved snapshot of product IDs.
    if normalized_kind='best_tab' and normalized_payload ? 'selection_mode' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'selection_mode') <> 'string'
        or normalized_payload ->> 'selection_mode' <> 'latest'
        or normalized_payload ? 'good_ids'
        or not normalized_payload ? 'item_count'
        or pg_catalog.jsonb_typeof(normalized_payload -> 'item_count') <> 'number'
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      if (normalized_payload ->> 'item_count')::numeric not between 3 and 10
        or pg_catalog.trunc((normalized_payload ->> 'item_count')::numeric)
          <> (normalized_payload ->> 'item_count')::numeric
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['item_count'],
        pg_catalog.to_jsonb(((normalized_payload ->> 'item_count')::numeric)::integer)
      );
    elsif normalized_kind='best_tab' and normalized_payload ? 'item_count' then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;

    if normalized_payload ? 'mobile_image_path' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'mobile_image_path') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      payload_mobile_image_path := normalized_payload ->> 'mobile_image_path';
      if payload_mobile_image_path
        !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
      then
        raise check_violation using message = 'invalid_curation_image_path';
      end if;
    end if;

    if normalized_payload ? 'cta_label' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'cta_label') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_notice';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['cta_label'],
        pg_catalog.to_jsonb(pg_catalog.btrim(normalized_payload ->> 'cta_label'))
      );
    end if;

    -- Page-type targeting is stored in one canonical order so an identical
    -- operator request replays byte-for-byte (operation receipt comparison).
    if normalized_payload ? 'page_types' then
      if not private.is_valid_home_notice_page_types(normalized_payload -> 'page_types') then
        raise invalid_parameter_value using message = 'invalid_curation_notice';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['page_types'],
        (
          select pg_catalog.jsonb_agg(page_type order by pg_catalog.array_position(
            array['home', 'collection', 'product', 'content', 'other']::text[], page_type
          ))
          from pg_catalog.jsonb_array_elements_text(normalized_payload -> 'page_types') as page_types(page_type)
        )
      );
    end if;
  end if;

  if not private.is_valid_home_ranked_curation(normalized_kind, normalized_payload) then
    raise invalid_parameter_value using message='invalid_curation_payload';
  end if;

  if not private.is_valid_home_notice_payload(normalized_kind, normalized_payload, normalized_link_path) then
    raise invalid_parameter_value using message='invalid_curation_notice';
  end if;

  if normalized_kind='product_mosaic' and (not private.is_valid_home_mosaic(normalized_payload) or normalized_image_path is not null) then
    raise invalid_parameter_value using message='invalid_curation_mosaic';
  end if;

  if normalized_kind='hero' and not private.is_valid_home_hero_style(normalized_payload) then
    raise invalid_parameter_value using message='invalid_hero_style';
  end if;

  if normalized_kind='hero' and not private.is_valid_home_hero_alt(normalized_payload) then
    raise invalid_parameter_value using message='invalid_hero_alt';
  end if;

  if normalized_kind='product_collection' and (not private.is_valid_home_product_collection(normalized_payload)
    or normalized_image_path is not null or normalized_title~'[[:cntrl:]]') then
    raise invalid_parameter_value using message='invalid_curation_product_collection';
  end if;

  request_payload := pg_catalog.jsonb_build_object(
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  if require_saved_version then
    request_payload := request_payload || pg_catalog.jsonb_build_object('expected_updated_at',target_expected_updated_at);
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.home_curation.upserted'
      and existing_target = 'home_curations:' || target_curation_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_curation_id;
    end if;

    raise unique_violation using message = 'operation_conflict';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation:' || target_curation_id::text,
      0
    )
  );

  if normalized_ip_id is not null then
    select ip.archived_at
      into referenced_archived_at
    from public.ips as ip
    where ip.id = normalized_ip_id
    for update of ip;

    if not found then
      raise no_data_found using message = 'curation_ip_not_found';
    end if;
    if referenced_archived_at is not null then
      raise check_violation using message = 'catalog_item_archived';
    end if;
  end if;

  select curation.*
    into previous_curation
  from public.home_curations as curation
  where curation.id = target_curation_id
  for update of curation;
  curation_exists := found;
  if curation_exists and previous_curation.archived_at is not null then
    raise sqlstate 'PT409' using message='curation_archived';
  end if;

  if require_saved_version and ((curation_exists and previous_curation.updated_at is distinct from target_expected_updated_at)
    or (not curation_exists and target_expected_updated_at is not null)) then
    raise sqlstate 'PT409' using message='curation_conflict';
  end if;

  if curation_exists then
    previous_payload := pg_catalog.jsonb_build_object(
      'id', previous_curation.id,
      'kind', previous_curation.kind,
      'ip_id', previous_curation.ip_id,
      'title', previous_curation.title,
      'image_path', previous_curation.image_path,
      'link_path', previous_curation.link_path,
      'display_order', previous_curation.display_order,
      'active_from', previous_curation.active_from,
      'active_to', previous_curation.active_to,
      'enabled', previous_curation.enabled,
      'slot', previous_curation.slot,
      'payload', previous_curation.payload
    );
    previous_mobile_image_path := previous_curation.payload ->> 'mobile_image_path';
  end if;

  -- The artwork-claim trigger only guards the image_path column, so the
  -- mobile artwork carried inside payload consumes its verified upload claim
  -- here, under the same actor/kind/single-use rules (#112 contract).
  if payload_mobile_image_path is not null
    and payload_mobile_image_path is distinct from previous_mobile_image_path
  then
    update public.admin_artwork_upload_claims as claim
    set
      status = 'attached',
      attached_at = pg_catalog.clock_timestamp(),
      resolved_at = pg_catalog.clock_timestamp()
    where claim.actor_id = claim_owner_id
      and claim.path = pg_catalog.substr(
        payload_mobile_image_path,
        pg_catalog.length('public-media/') + 1
      )
      and claim.kind = 'curation'
      and claim.status = 'verified'
      and claim.verified_at is not null
      and claim.final_size is not null
      and claim.attached_at is null
      and claim.expires_at > pg_catalog.clock_timestamp();

    if not found then
      raise check_violation using message = 'unverified_artwork';
    end if;
  end if;

  if curation_exists then
    update public.home_curations
    set
      kind = normalized_kind,
      ip_id = normalized_ip_id,
      title = normalized_title,
      image_path = normalized_image_path,
      link_path = normalized_link_path,
      display_order = target_display_order,
      active_from = target_active_from,
      active_to = target_active_to,
      enabled = target_enabled,
      slot = normalized_slot,
      payload = normalized_payload
    where id = target_curation_id;
  else
    insert into public.home_curations (
      id, kind, ip_id, title, image_path, link_path,
      display_order, active_from, active_to, enabled, slot, payload
    )
    values (
      target_curation_id, normalized_kind, normalized_ip_id, normalized_title,
      normalized_image_path, normalized_link_path, target_display_order,
      target_active_from, target_active_to, target_enabled, normalized_slot,
      normalized_payload
    );
  end if;

  after_payload := pg_catalog.jsonb_build_object(
    'id', target_curation_id,
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.home_curation.upserted',
    'home_curations:' || target_curation_id::text,
    pg_catalog.jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_curation_id;
end;
$function$

do $$declare name text;begin
 foreach name in array array['notice_events','notice_daily'] loop
  execute format('alter table private.store_analytics_%I enable row level security',name);
  execute format('revoke all on private.store_analytics_%I from public,anon,authenticated,service_role',name);
 end loop;
end $$

create function public.record_store_analytics_notice_event(p_token_hash text,p_event_id uuid,p_curation_id uuid,p_interaction text)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare session private.store_analytics_sessions; existing private.store_analytics_notice_events; at_time timestamptz;
 fingerprint text; notice_kind text; recorded integer;
begin
 perform private.store_analytics_require_service();
 if p_token_hash is null or p_token_hash!~'^[0-9a-f]{64}$' or p_event_id is null or p_curation_id is null
  or p_interaction is null or p_interaction not in ('impression','click') then
  raise invalid_parameter_value using message='analytics_invalid_event';end if;
 perform 1 from private.store_analytics_settings where id and enabled for share;
 if not found then raise object_not_in_prerequisite_state using message='analytics_disabled';end if;
 select * into session from private.store_analytics_sessions where token_hash=p_token_hash for update;
 at_time:=clock_timestamp();
 if not found or session.revoked_at is not null then raise invalid_authorization_specification using message='analytics_session_unavailable';end if;
 fingerprint:=encode(extensions.digest(jsonb_build_array('notice',p_curation_id,p_interaction)::text,'sha256'),'hex');
 select * into existing from private.store_analytics_notice_events where id=p_event_id;
 if found then
  if existing.session_id<>session.id or existing.payload_hash<>fingerprint then raise exception using errcode='PT409',message='analytics_event_conflict';end if;
  return jsonb_build_object('recorded',true,'replayed',true);
 end if;
 if at_time>=session.last_seen_at+interval '30 minutes' or at_time>=session.created_at+interval '24 hours'
  or (at_time at time zone 'Asia/Seoul')::date<>(session.created_at at time zone 'Asia/Seoul')::date then
  raise invalid_authorization_specification using message='analytics_session_expired';end if;
 -- Only a notice the public shell can show at this instant is countable; an
 -- arbitrary identifier, a disabled, scheduled, ended or other-kind row is not.
 select c.kind into notice_kind from public.home_curations c
  where c.id=p_curation_id and c.kind in ('notice_bar','notice_strip') and c.enabled and c.archived_at is null
   and c.active_from<=at_time and (c.active_to is null or c.active_to>at_time);
 if not found then raise no_data_found using message='analytics_notice_unavailable';end if;
 -- A click must follow an impression of the same notice in the same session.
 if p_interaction='click' and not exists(select 1 from private.store_analytics_notice_events e
  where e.session_id=session.id and e.curation_id=p_curation_id and e.interaction='impression') then
  raise invalid_parameter_value using message='analytics_notice_not_shown';end if;
 select count(*) into recorded from private.store_analytics_notice_events where session_id=session.id;
 if recorded>=500 then raise exception using errcode='P0429',message='analytics_rate_limited';end if;
 perform private.store_analytics_rate('notice-events',10000,at_time);
 -- Shares the session's page-view budget: one browsing session, one limit.
 perform private.store_analytics_rate('session:'||session.id::text,120,at_time);
 insert into private.store_analytics_notice_events(id,session_id,observed_at,curation_id,placement,interaction,payload_hash)
 values(p_event_id,session.id,at_time,p_curation_id,notice_kind,p_interaction,fingerprint);
 insert into private.store_analytics_health(minute,observed_at) values(date_trunc('minute',at_time),at_time) on conflict(minute) do nothing;
 return jsonb_build_object('recorded',true,'replayed',false);
end $$

-- Retention: unchanged except that each archived day first keeps its notice
-- totals (no session identifier) before the day's sessions — and with them the
-- raw notice rows — are deleted, and notice totals expire after 13 months.
create or replace function public.process_store_analytics_retention() returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare at_time timestamptz:=clock_timestamp(); cutoff date; first_day date; day_value date; coverage jsonb; archived_count integer:=0; enabled_value boolean;
begin
 perform private.store_analytics_require_service();
 if not pg_try_advisory_xact_lock(hashtextextended('store-analytics:retention',0)) then return jsonb_build_object('busy',true);end if;
 select enabled,(activated_at at time zone 'Asia/Seoul')::date into enabled_value,first_day from private.store_analytics_settings where id for share;
 if enabled_value then
  insert into private.store_analytics_health(minute,observed_at) values(date_trunc('minute',at_time),at_time) on conflict(minute) do nothing;
 end if;
 -- Keep exactly the latest 90 Korean calendar dates, including today.
 cutoff:=(at_time at time zone 'Asia/Seoul')::date-89;
 if first_day is not null then
  for day_value in select day::date from generate_series(greatest(first_day,((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date)::timestamp,
   (cutoff-1)::timestamp,interval '1 day') days(day)
   where not exists(select 1 from private.store_analytics_daily_coverage where day=days.day::date) order by day limit 7 loop
   -- Revocation either completes before this snapshot or waits until all raw
   -- identifiers have been removed. Anonymous archived totals cannot be relinked.
   perform id from private.store_analytics_sessions where created_at>=day_value::timestamp at time zone 'Asia/Seoul'
    and created_at<(day_value+1)::timestamp at time zone 'Asia/Seoul' order by id for update;
   coverage:=private.store_analytics_day_coverage(day_value,at_time);
   insert into private.store_analytics_daily(day,dimension,key,page_views,product_views,sessions,link_landings,orders,converted_sessions,gross_amount,refund_amount,observed_until)
    select day_value,r.*,at_time from private.store_analytics_raw_rows(day_value) r;
   insert into private.store_analytics_notice_daily(day,curation_id,placement,impressions,clicks,impression_sessions,click_sessions,observed_until)
    select day_value,e.curation_id,e.placement,count(*) filter(where e.interaction='impression'),count(*) filter(where e.interaction='click'),
     count(distinct e.session_id) filter(where e.interaction='impression'),count(distinct e.session_id) filter(where e.interaction='click'),at_time
    from private.store_analytics_notice_events e join private.store_analytics_sessions s on s.id=e.session_id and s.revoked_at is null
    where e.observed_at>=day_value::timestamp at time zone 'Asia/Seoul' and e.observed_at<(day_value+1)::timestamp at time zone 'Asia/Seoul'
    group by e.curation_id,e.placement;
   insert into private.store_analytics_daily_coverage(day,state,expected_minutes,observed_minutes,observed_until)
    values(day_value,coverage->>'state',(coverage->>'expectedMinutes')::integer,(coverage->>'observedMinutes')::integer,at_time);
   delete from private.store_analytics_sessions where created_at>=day_value::timestamp at time zone 'Asia/Seoul' and created_at<(day_value+1)::timestamp at time zone 'Asia/Seoul';
   delete from private.store_analytics_health where minute>=day_value::timestamp at time zone 'Asia/Seoul' and minute<(day_value+1)::timestamp at time zone 'Asia/Seoul';
   archived_count:=archived_count+1;
  end loop;
 end if;
 delete from private.store_analytics_sessions where created_at<(((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date)::timestamp at time zone 'Asia/Seoul';
 delete from private.store_analytics_daily where day<((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date;
 delete from private.store_analytics_notice_daily where day<((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date;
 delete from private.store_analytics_daily_coverage where day<((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date;
 delete from private.store_analytics_health where minute<(((at_time at time zone 'Asia/Seoul')::date-interval '13 months')::date)::timestamp at time zone 'Asia/Seoul';
 delete from private.store_analytics_rate_buckets where bucket<date_trunc('minute',at_time)-interval '10 minutes';
 return jsonb_build_object('busy',false,'archivedDays',archived_count,'checkedAt',at_time);
end $$

-- 어드민 전시분류 목록에 노드 이미지를 더한다. 공개 페이지가 쓰는 category_display_category 결과(조회 토큰의 일부)는 그대로 둔다.
create or replace function public.admin_list_category_displays() returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.has_operator_capability('store.manage') then raise insufficient_privilege using message='operator_capability_required';end if;
 return jsonb_build_object('checkedAt',statement_timestamp(),'revision',(select revision from private.category_display_tree_control where singleton),
 'categories',coalesce((with recursive tree as (
  select n.id,array[lpad(n.sort_order::text,10,'0')||':'||coalesce(n.legacy_sort_key,n.id::text)] path from private.category_display_nodes n where n.parent_id is null
  union all select n.id,t.path||(lpad(n.sort_order::text,10,'0')||':'||coalesce(n.legacy_sort_key,n.id::text)) from private.category_display_nodes n join tree t on n.parent_id=t.id
 ) select jsonb_agg(private.category_display_category(n.id)||jsonb_build_object('imagePath',n.image_path) order by t.path) from private.category_display_nodes n join tree t on t.id=n.id),'[]'::jsonb),
 'sourceCategories',coalesce((select jsonb_agg(private.category_display_source_category(c.id) order by c.depth,c.sort_order,c.code)
  from public.catalog_categories c where c.archived_at is null),'[]'::jsonb));
end $$

-- 노드 이미지 적용·해제. 전시분류 트리와 같은 잠금 순서(운영자 → 요청 UUID → 카테고리 트리 → 트리 revision)와
-- 같은 revision CAS·요청 UUID 멱등·감사를 쓴다. 새 이미지는 본인이 검증 완료한 curation claim만 소비한다.
create function public.admin_set_category_display_node_image(p_node_id uuid,p_image_path text,p_expected_revision bigint,p_operation_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid;previous private.category_display_nodes;current_revision bigint;receipt public.audit_log;request jsonb;result jsonb;
begin
 actor:=private.require_operator_capability('store.manage',false);
 if p_node_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or p_image_path is not null and p_image_path !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|png|webp)$'
 then raise invalid_parameter_value using message='invalid_display_node_image';end if;
 request:=jsonb_build_object('nodeId',p_node_id,'imagePath',p_image_path,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('category-display-operation:'||p_operation_id,0));
 select * into receipt from public.audit_log where id=p_operation_id;
 if found then
  if receipt.actor_id=actor and receipt.action='admin.category_display.image_changed' and receipt.target='category-display:'||p_node_id and receipt.diff->'request'=request then return receipt.diff->'result';end if;
  raise unique_violation using message='operation_conflict';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('catalog_category_tree',0));
 select revision into current_revision from private.category_display_tree_control where singleton for update;
 if current_revision<>p_expected_revision then raise sqlstate 'PT409' using message='category_display_tree_conflict';end if;
 select * into previous from private.category_display_nodes where id=p_node_id for update;
 if not found then raise no_data_found using message='display_node_missing';end if;
 if p_image_path is not null and p_image_path is distinct from previous.image_path then
  update public.admin_artwork_upload_claims as claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
  where claim.actor_id=actor and claim.path=substr(p_image_path,length('public-media/')+1) and claim.kind='curation'
   and claim.status='verified' and claim.verified_at is not null and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
  if not found then raise check_violation using message='unverified_artwork';end if;
 end if;
 update private.category_display_nodes set image_path=p_image_path,updated_at=clock_timestamp() where id=p_node_id;
 update private.category_display_tree_control set revision=current_revision+1 where singleton;
 result:=jsonb_build_object('nodeId',p_node_id,'directory',public.admin_list_category_displays());
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.category_display.image_changed','category-display:'||p_node_id,
  jsonb_build_object('request',request,'before',jsonb_build_object('imagePath',previous.image_path),'result',result));
 return result;
end $$

create or replace function private.category_display_page(p_category_id uuid,p_values jsonb,p_query jsonb,p_offset integer,p_token text,p_revision bigint) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare category jsonb;result jsonb;fingerprint text;b jsonb;r jsonb;video jsonb;recommendations jsonb;keys text[]:=array['ips','types','min','max','sort'];
begin
 category:=private.category_display_category(p_category_id);
 if category is null or not (category->>'publicEnabled')::boolean then return null;end if;
 if p_offset is null or p_offset<0 or p_offset>10000000 or p_offset%20<>0 or p_offset>0 and (p_token is null or p_token !~ '^[0-9a-f]{32}$')
  or jsonb_typeof(p_query) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_query))<>5 or not p_query ?& keys
  or jsonb_typeof(p_query->'ips') is distinct from 'array' or jsonb_typeof(p_query->'types') is distinct from 'array'
  or jsonb_typeof(p_query->'sort') is distinct from 'string' or p_query->>'sort' not in('recommended','name_asc','name_desc','price_asc','price_desc','oldest','newest')
  or jsonb_typeof(p_query->'min') not in('null','number') or jsonb_typeof(p_query->'max') not in('null','number') then raise invalid_parameter_value using message='invalid_category_display_query';end if;
 if jsonb_array_length(p_query->'ips')>100 or jsonb_array_length(p_query->'types')>9
  or exists(select 1 from jsonb_array_elements(p_query->'ips') value where jsonb_typeof(value)<>'string' or value#>>'{}' !~ '^[a-z0-9][a-z0-9-]{0,199}$')
  or exists(select 1 from jsonb_array_elements(p_query->'types') value where jsonb_typeof(value)<>'string' or value#>>'{}' not in('피규어','인형','키링','아크릴','문구','쿠션','파우치','세트','예약판매'))
  or exists(select 1 from jsonb_each_text(p_query) e where e.key in('min','max') and e.value is not null and (e.value !~ '^[0-9]{1,9}$' or e.value::numeric>100000000))
  or (p_query->>'min')::numeric>(p_query->>'max')::numeric then raise invalid_parameter_value using message='invalid_category_display_query';end if;
 -- Materialize the complete option quote once per candidate. A flattenable
 -- lateral SELECT would run the price/supply helper separately for each of the
 -- JSON projection, minimum price and available-stock expressions.
 with quoted as materialized (
  select g as good,g.id,g.ip_id,g.name,g.type,g.created_at,g.updated_at,g.display_order,m.ordinal_position,ip.title ip_name,
   private.category_display_public_variants(g.id) variants
  from private.category_display_matching_goods(p_values) m join public.goods g on g.id=m.id join public.ips ip on ip.id=g.ip_id
 ), base as materialized (
  select quoted.*,
   coalesce((select min((v#>>'{pricing,effectivePrice}')::numeric) from jsonb_array_elements(variants) v),(good).price) current_price,
   coalesce((select sum((v#>>'{supply,availableQty}')::bigint) from jsonb_array_elements(variants) v),0) available,
   exists(select 1 from jsonb_array_elements(variants) v where v#>>'{supply,mode}'='preorder') preorder
  from quoted
 ), filtered as materialized (
  select * from base where (jsonb_array_length(p_query->'ips')=0 or ip_id in(select value from jsonb_array_elements_text(p_query->'ips')))
   and (jsonb_array_length(p_query->'types')=0 or type in(select value from jsonb_array_elements_text(p_query->'types')) or preorder and p_query->'types' ? '예약판매')
   and (p_query->>'min' is null or current_price>=(p_query->>'min')::numeric) and (p_query->>'max' is null or current_price<=(p_query->>'max')::numeric)
 ), ranked as materialized (
  select *,row_number() over(order by
   case when p_query->>'sort'='price_asc' then current_price end asc,
   case when p_query->>'sort'='price_desc' then current_price end desc,
   (case when p_query->>'sort'='name_asc' then name end) collate private.category_display_name_ko asc,
   (case when p_query->>'sort'='name_desc' then name end) collate private.category_display_name_ko desc,
   case when p_query->>'sort'='newest' then created_at end desc nulls last,
   case when p_query->>'sort'='oldest' then created_at end asc nulls last,
   case when p_values->>'mode'='manual' then ordinal_position end asc nulls last,
   case when p_values->>'mode'='categories' then display_order end asc nulls last,
   case when p_values->>'mode'='categories' then private.category_display_natural_key(id) end collate "C" asc,
   id collate "C") rank from filtered
 ), page as (select * from ranked order by rank limit 20 offset p_offset)
 select jsonb_build_object('category',jsonb_build_object('id',category->'id','name',category->'name'),'checkedAt',statement_timestamp(),
  'total',(select count(*) from base),'filteredTotal',(select count(*) from filtered),'priceCeil',coalesce((select max(current_price) from base),0),
  'token',md5(jsonb_build_array(p_category_id,p_revision,category,p_query,coalesce((select string_agg(id||':'||current_price||':'||available||':'||updated_at,',' order by rank) from ranked),'') )::text),
  'offset',p_offset,'nextOffset',case when (select count(*) from filtered)>p_offset+20 then p_offset+20 else null end,
  'ipFacets',coalesce((select jsonb_agg(jsonb_build_object('value',ip_id,'label',ip_name,'count',n) order by ip_name,ip_id) from (select ip_id,ip_name,count(*) n from base group by ip_id,ip_name) f),'[]'::jsonb),
  'typeFacets',coalesce((select jsonb_agg(jsonb_build_object('value',type,'label',type,'count',n) order by array_position(array['피규어','인형','키링','아크릴','문구','쿠션','파우치','세트'],type)) from (select type,count(*) n from base group by type) f),'[]'::jsonb)
   ||coalesce((select jsonb_build_array(jsonb_build_object('value','예약판매','label','예약판매','count',count(*))) from base where preorder having count(*)>0),'[]'::jsonb),
  'rows',coalesce((select jsonb_agg(private.category_display_public_good(good,variants) order by rank) from page),'[]'::jsonb)) into result;
 fingerprint:=result->>'token';if p_token is not null and p_token is distinct from fingerprint then raise sqlstate 'PT409' using message='category_display_page_changed';end if;
 if (result->>'total')::bigint=0 then return result||jsonb_build_object('banner',null,'video',null,'recommendations',null);end if;
 b:=p_values->'banner';r:=p_values->'recommendations';
 if not (b->>'enabled')::boolean then b:=null;else
  b:=jsonb_build_object('title',b->'title','content',b->'content','imagePath',b->'imagePath','mobileImagePath',b->'mobileImagePath',
   'linkPath',b->'linkPath','imageDim',b->'imageDim','textColor',b->'textColor','altText',case when (b->>'altEnabled')::boolean then concat_ws(' · ',nullif(btrim(b->>'altTitle'),''),nullif(btrim(b->>'altContent'),'')) else '' end);
 end if;
 if (p_values#>>'{video,enabled}')::boolean then
  video:=public.get_good_media(p_values#>>'{video,goodId}')->'video';
  if video='null'::jsonb then video:=null;end if;
  if video is not null then video:=jsonb_build_object('asset',video,'poster',(select image_path from public.goods where id=p_values#>>'{video,goodId}'));end if;
 end if;
 if (r->>'enabled')::boolean then
  select jsonb_build_object('title',r->'title','rows',coalesce(jsonb_agg(private.category_display_public_good(good,variants) order by position),'[]'::jsonb)) into recommendations
  from (select g as good,ordinality position,private.category_display_public_variants(g.id) variants
   from jsonb_array_elements_text(r->'goodIds') with ordinality ids join public.goods g on g.id=ids.value join public.ips ip on ip.id=g.ip_id
   where g.archived_at is null and g.published_at is not null and g.sale_restriction='none' and ip.archived_at is null and ip.published_at is not null
   order by ordinality limit (r->>'itemCount')::integer) selected;
 end if;
 return result||jsonb_build_object('banner',b,'video',video,'recommendations',recommendations);
end $$

create function public.get_loyalty_grade_benefits()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  actor uuid := (select auth.uid());
  member_grade public.loyalty_grade;
  credit_enabled boolean;
  reward_enabled boolean;
  reward_rates jsonb;
  rates_effective boolean;
  result jsonb;
begin
  if actor is null then
    raise insufficient_privilege using message = 'auth_required';
  end if;

  -- 프로필이 없으면(가입 직후 경합 등) 가입 기본 등급으로 본다 — 상위 등급 쿠폰은 요약만 나간다.
  select coalesce(profile.loyalty_grade, 'welcome'::public.loyalty_grade) into member_grade
  from public.profiles as profile
  where profile.id = actor;
  member_grade := coalesce(member_grade, 'welcome'::public.loyalty_grade);

  select policy.enabled into credit_enabled
  from private.store_credit_policy as policy
  where policy.singleton;

  select policy.grade_enabled, policy.grade_rates into reward_enabled, reward_rates
  from private.customer_reward_policy as policy
  where policy.singleton;

  rates_effective := coalesce(credit_enabled, false) and coalesce(reward_enabled, false);

  with grades as (
    select grade.value as grade, grade.position
    from pg_catalog.unnest(pg_catalog.enum_range(null::public.loyalty_grade)) with ordinality as grade(value, position)
  ), grantable as (
    -- private.grant_grade_benefit_coupons 와 같은 거름(받는 회원 조건만 값으로 남긴다).
    select coupon.*
    from public.coupons as coupon
    where coupon.grade_benefit is not null
      and coupon.grade_benefit > 'welcome'::public.loyalty_grade
      and coupon.status = 'active'
      and (coupon.ends_at is null or coupon.ends_at > statement_timestamp())
      and (coupon.issue_starts_at is null or coupon.issue_starts_at <= statement_timestamp())
      and (coupon.issue_starts_at is null or coupon.issue_ends_at is null or coupon.issue_ends_at > statement_timestamp())
      and (coupon.issue_limit is null or coupon.issued_count < coupon.issue_limit)
  )
  select jsonb_build_object(
    'creditRatesEnabled', rates_effective,
    'grades', jsonb_agg(
      jsonb_build_object(
        'grade', grades.grade,
        -- 내가 오른 등급(이하)인지. 오르지 않은 등급은 쿠폰 내용 대신 종류별 장수만 싣는다.
        'reached', grades.grade <= member_grade,
        'creditRateBps', case when rates_effective then (reward_rates ->> grades.grade::text)::integer end,
        'couponCounts', jsonb_build_object(
          'goods', (select count(*) from grantable as coupon where coupon.grade_benefit = grades.grade and coupon.benefit_kind = 'goods'),
          'shipping', (select count(*) from grantable as coupon where coupon.grade_benefit = grades.grade and coupon.benefit_kind = 'shipping')
        ),
        'coupons', case when grades.grade > member_grade then '[]'::jsonb else coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'name', coupon.name,
              'benefitKind', coupon.benefit_kind,
              'discountType', coupon.discount_type,
              'discountValue', coupon.discount_value,
              'maxDiscountAmount', coupon.max_discount_amount,
              'minSubtotal', coupon.min_subtotal,
              'goodsScope', coupon.goods_scope,
              'recipientSegment', coupon.recipient_segment,
              'startsAt', coupon.starts_at,
              'endsAt', coupon.ends_at,
              'validDays', coupon.valid_days
            )
            -- 코드는 정렬의 마지막 결정자로만 쓰고 내보내지 않는다(같은 조건의 정의도 순서가 흔들리지 않게).
            order by coupon.min_subtotal, coupon.benefit_kind, coupon.discount_type, coupon.discount_value desc, coupon.name, coupon.code
          )
          from grantable as coupon
          where coupon.grade_benefit = grades.grade
        ), '[]'::jsonb) end
      )
      order by grades.position
    )
  )
  into result
  from grades;

  return result;
end;
$$

-- 한 수단의 선택을 원장에 쓴다. 같은 선택이면 아무것도 바꾸지 않는다(멱등, false 반환).
-- 처음 기록하는 거부는 "안내를 보고 동의하지 않음"의 근거로 한 줄 남긴다.
-- 호출자가 회원 행을 먼저 잠근다(RPC는 FOR UPDATE, 트리거는 UPDATE 자체의 행 잠금).
create function private.write_customer_marketing_consent(p_user uuid,p_channel text,p_choice boolean,
 p_notice_version text,p_source text,p_at timestamptz) returns boolean
language plpgsql security definer set search_path='' as $$
declare current_row private.customer_marketing_consents; had_row boolean;
begin
 select * into current_row from private.customer_marketing_consents c where c.user_id=p_user and c.channel=p_channel for update;
 had_row:=found;
 if had_row and current_row.agreed=p_choice then return false; end if;
 insert into private.customer_marketing_consents(user_id,channel,agreed,notice_version,source,agreed_at,withdrawn_at,revision,updated_at)
 values(p_user,p_channel,p_choice,p_notice_version,p_source,
  case when p_choice then p_at end,
  case when not p_choice and had_row and current_row.agreed then p_at end,
  coalesce(current_row.revision,0)+1,p_at)
 on conflict(user_id,channel) do update set agreed=excluded.agreed,notice_version=excluded.notice_version,source=excluded.source,
  agreed_at=excluded.agreed_at,withdrawn_at=excluded.withdrawn_at,revision=excluded.revision,updated_at=excluded.updated_at;
 insert into private.customer_marketing_consent_events(user_id,channel,agreed,notice_version,source,occurred_at)
 values(p_user,p_channel,p_choice,p_notice_version,p_source,p_at);
 return true;
end $$

create function public.my_marketing_consent_state() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=auth.uid();
begin
 if actor is null or not exists(select 1 from public.profiles p where p.id=actor) then
  raise insufficient_privilege using message='marketing_consent_auth_required'; end if;
 return private.customer_marketing_consent_document(actor);
end $$

create function public.set_my_marketing_consents(p_email boolean,p_sms boolean,p_notice_version text,p_source text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); profile_consents jsonb; changed_at timestamptz:=clock_timestamp(); derived boolean;
begin
 if actor is null then raise insufficient_privilege using message='marketing_consent_auth_required'; end if;
 if p_email is null or p_sms is null or p_notice_version is distinct from 'marketing-channels-v1'
  or p_source is null or p_source not in ('onboarding','settings') then
  raise invalid_parameter_value using message='invalid_marketing_consent'; end if;
 -- 계정 잠금(account-action)을 회원 행보다 먼저 잡는다 — 결제 확정·미결제 주문 닫기가 계정 잠금 →
 -- 회원 행(등급 재산정) 순서라, 반대로 잡으면 같은 회원의 동시 처리와 교착한다(ADR-0026 잠금 순서).
 if private.is_account_write_fenced(actor) then
  raise object_not_in_prerequisite_state using message='account_deletion_write_fenced'; end if;
 -- 회원 행 잠금으로 같은 회원의 동시 저장(다른 탭·온보딩 재제출·옛 앱 직접 쓰기)을 직렬화한다.
 select p.consents into profile_consents from public.profiles p where p.id=actor for update;
 if not found then raise insufficient_privilege using message='marketing_consent_auth_required'; end if;
 perform private.write_customer_marketing_consent(actor,'email',p_email,p_notice_version,p_source,changed_at);
 perform private.write_customer_marketing_consent(actor,'sms',p_sms,p_notice_version,p_source,changed_at);
 derived:=p_email or p_sms;
 -- 원장을 먼저 쓰고 파생값을 맞춘다. 아래 동기화 트리거는 파생값과 원장이 같으면 아무것도 하지 않는다.
 if profile_consents->'marketing' is distinct from to_jsonb(derived) then
  update public.profiles set consents=coalesce(consents,'{}'::jsonb)||jsonb_build_object('marketing',derived) where id=actor;
 end if;
 return private.customer_marketing_consent_document(actor);
end $$

-- 원장 밖에서 바뀐 consents.marketing(배포 창 동안의 옛 앱 Data API 쓰기, 운영 SQL)을 원장에 반영한다.
-- false는 동의 중인 수단을 모두 철회하고, true는 옛 단일 안내와 같은 이메일 동의로 기록한다
-- (source legacy_app, 안내 버전 marketing-legacy-v0). RPC 경로는 원장을 먼저 써서 파생값과
-- 원장이 이미 같으므로 여기서 아무것도 하지 않는다.
create function private.sync_marketing_consent_ledger() returns trigger
language plpgsql security definer set search_path='' as $$
declare wanted boolean; derived boolean; channel_value text; changed_at timestamptz:=clock_timestamp();
begin
 if new.consents->'marketing' is not distinct from old.consents->'marketing' then return null; end if;
 wanted:=coalesce(new.consents->'marketing'='true'::jsonb,false);
 derived:=exists(select 1 from private.customer_marketing_consents c where c.user_id=new.id and c.agreed);
 if wanted=derived then return null; end if;
 if wanted then
  perform private.write_customer_marketing_consent(new.id,'email',true,'marketing-legacy-v0','legacy_app',changed_at);
 else
  for channel_value in select c.channel from private.customer_marketing_consents c where c.user_id=new.id and c.agreed order by c.channel loop
   perform private.write_customer_marketing_consent(new.id,channel_value,false,'marketing-legacy-v0','legacy_app',changed_at);
  end loop;
 end if;
 return null;
end $$

revoke all on function private.write_customer_marketing_consent(uuid,text,boolean,text,text,timestamptz),
 private.customer_marketing_consent_document(uuid),public.my_marketing_consent_state(),
 public.set_my_marketing_consents(boolean,boolean,text,text),private.keep_marketing_consent_shape(),
 private.sync_marketing_consent_ledger()
 from public,anon,authenticated,service_role

-- 미결제 카드 장바구니 주문 하나를 결제 없이 닫는다. 만료 sweep(expire_stale_checkouts,
-- 20261013110400)과 같은 잠금 순서(order → request → attempt)와 같은 종결 함수를 쓰고,
-- 차이는 prepared 시도를 TTL과 무관하게 canceled로 바꾼다는 점뿐이다. 호출자는 계정
-- advisory lock을 쥐고 있어야 한다.
-- 반환: closed | payment_confirming | unresolved | not_pending
create function private.close_unpaid_cart_order(p_order_id uuid, p_reason text, p_trigger text)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
  v_attempt public.payment_attempts%rowtype;
  v_has_attempt boolean := false;
  v_attempt_canceled boolean := false;
  v_request record;
  v_request_id uuid;
begin
  select o.* into v_order from public.orders as o where o.id = p_order_id for update;
  if not found or v_order.status <> 'pending' or v_order.payment_method <> 'card' then
    return 'not_pending';
  end if;
  -- finalize·claim과 같은 순서(주문 → account-action → profiles). 취소 트리거(등급 재계산)가
  -- profiles를 잠그기 전에 account-action을 먼저 쥐어, 같은 계정의 다른 주문 finalize와 엇갈려
  -- 기다리지 않게 한다.
  perform private.lock_account_action_subject(v_order.user_id);

  -- 같은 임계 구역: order → request → attempt (claim·finalizer·sweep과 같은 순서).
  select request.id, request.reason, request.status
    into v_request
  from public.order_cancellation_requests as request
  where request.order_id = p_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id desc
  limit 1
  for update;
  if found and v_request.status <> 'requested' then
    -- 승인된 결제의 취소(환불)가 진행 중이다. 돈이 움직였으므로 닫지 않는다.
    return 'unresolved';
  end if;

  select attempt.* into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'order' and attempt.ref_id = p_order_id
  for update;
  v_has_attempt := found;

  if v_has_attempt and v_attempt.state = 'confirming'
    and v_attempt.claim_expires_at is not null
    and v_attempt.claim_expires_at > pg_catalog.clock_timestamp()
  then
    return 'payment_confirming';
  end if;
  if (v_has_attempt and v_attempt.state in ('confirming', 'unknown', 'needs_review', 'approved'))
    or exists (
      select 1 from public.payments as payment
      where payment.purpose = 'order' and payment.ref_id = p_order_id
        and payment.status in ('pending', 'paid')
    )
  then
    return 'unresolved';
  end if;

  if v_has_attempt and v_attempt.state = 'prepared' then
    update public.payment_attempts as attempt
    set state = 'canceled', claim_token = null, claim_expires_at = null
    where attempt.id = v_attempt.id and attempt.state = 'prepared';
    v_attempt_canceled := found;
  end if;

  -- 보류를 먼저 닫아야 아래 취소 트리거가 사유를 order_closed로 덮지 않는다.
  update private.cart_order_holds
  set state = 'released', settled_at = pg_catalog.clock_timestamp(), release_reason = 'superseded'
  where order_id = p_order_id and state = 'awaiting_payment';

  if v_request.id is not null then
    -- 결제 중 접수된 고객 취소 요청. 시도가 결제 없이 끝났으므로(방금 canceled로
    -- 바꿨거나 이미 declined/canceled) sweep과 같이 요청을 종결하고 알린다.
    v_request_id := v_request.id;
    perform public.finalize_order_cancellation_with_provider_evidence(
      p_order_id, v_request.reason, array[]::text[]);
    update public.order_cancellation_requests as request
    set status = 'completed',
        completed_at = coalesce(request.completed_at, pg_catalog.clock_timestamp()),
        updated_at = pg_catalog.clock_timestamp()
    where request.id = v_request_id and request.status = 'requested';
    perform private.notify_order_claim(
      v_request_id, 'completed', '주문이 취소됐어요',
      '결제가 완료되지 않은 주문이라 결제 없이 취소했습니다.');
  else
    perform public.cancel_order(p_order_id, p_reason);
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    null,
    'system.order.unpaid_cart_order_closed',
    'order:' || p_order_id::text,
    pg_catalog.jsonb_build_object(
      'trigger', p_trigger,
      'attemptState', case when v_has_attempt then v_attempt.state::text end,
      'attemptCanceled', v_attempt_canceled,
      'requestId', v_request_id,
      'actor', 'system'
    )
  );
  return 'closed';
end;
$$

-- 계정의 미결제 카드 장바구니 주문을 닫는다. 호출자는 계정 advisory lock만 쥐고 있어야 한다.
-- account-action·profiles·장바구니 잠금은 아직 쥐지 않아야 한다(finalizer·claim은 주문 →
-- account-action → profiles → 장바구니 순서로 잠근다). 대상 주문 행을 모두 먼저 잠근 뒤에
-- account-action을 잡는다.
-- p_new_order=true: 새 장바구니 주문 직전. 승인 확인 중인 이전 주문이 있으면 막고,
--   자동으로 확정할 수 없는 이전 주문의 보류는 장바구니에서 떼어 낸다.
-- p_new_order=false: 고객이 장바구니·주문서로 돌아왔을 때. 닫을 수 있는 것만 닫는다.
create function private.supersede_unpaid_cart_orders(p_user_id uuid, p_new_order boolean)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  r record;
  v_result text;
  v_closed integer := 0;
begin
  if p_user_id is null or p_new_order is null then
    raise invalid_parameter_value using message = 'cart_order_supersede_invalid';
  end if;
  perform 1
  from public.orders as o
  join private.cart_order_holds as hold on hold.order_id = o.id
  where hold.user_id = p_user_id and hold.state = 'awaiting_payment'
  order by o.id
  for update of o;
  if not found then
    return 0;
  end if;
  perform private.lock_account_action_subject(p_user_id);
  for r in
    select hold.order_id
    from private.cart_order_holds as hold
    where hold.user_id = p_user_id and hold.state = 'awaiting_payment'
    order by hold.created_at, hold.order_id
  loop
    v_result := private.close_unpaid_cart_order(
      r.order_id,
      case when p_new_order then '같은 장바구니로 새 주문을 만들어 결제 대기 주문 자동 취소'
        else '장바구니로 돌아와 결제 대기 주문 자동 취소' end,
      case when p_new_order then 'new_cart_order' else 'returned_to_cart' end);
    if v_result = 'closed' then
      v_closed := v_closed + 1;
    elsif v_result = 'payment_confirming' and p_new_order then
      raise sqlstate 'PT409' using message = 'checkout_payment_in_progress';
    elsif v_result = 'unresolved' and p_new_order then
      update private.cart_order_holds
      set state = 'released', settled_at = pg_catalog.clock_timestamp(), release_reason = 'detached'
      where order_id = r.order_id and state = 'awaiting_payment';
      insert into public.audit_log (actor_id, action, target, diff)
      values (null, 'system.order.cart_hold_detached', 'order:' || r.order_id::text,
        pg_catalog.jsonb_build_object('trigger', 'new_cart_order', 'actor', 'system'));
    end if;
  end loop;
  return v_closed;
end;
$$

-- 고객이 장바구니·주문서로 돌아왔을 때 앱(service role)이 부른다. 닫힌 주문 수를 돌려준다.
create function public.release_unpaid_cart_orders(p_user_id uuid)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
begin
  if p_user_id is null then
    raise invalid_parameter_value using message = 'cart_order_supersede_invalid';
  end if;
  -- 주문 생성·쿠폰 선택과 같은 계정 잠금. 장바구니 잠금은 잡지 않는다.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text, 0));
  if not exists (
    select 1 from private.cart_order_holds as hold
    where hold.user_id = p_user_id and hold.state = 'awaiting_payment'
  ) then
    return 0;
  end if;
  return private.supersede_unpaid_cart_orders(p_user_id, false);
end;
$$

-- 결제 확정(pending → paid) 또는 닫힘(pending → canceled)에서 보류를 정산한다. 이름은
-- 다른 AFTER 트리거(적립금·쿠폰·등급 등)보다 먼저 실행되도록 고른다 — finalizer의 잠금
-- 순서가 order → attempt → account-action → payments(profiles) → 장바구니 줄 → (적립금·쿠폰)이 된다.
create function private.settle_cart_order_hold()
returns trigger
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_hold private.cart_order_holds%rowtype;
  v_line jsonb;
  v_cart public.cart_items%rowtype;
  v_ordered integer;
  v_outcome text;
  v_result jsonb := '[]'::jsonb;
  v_cleared integer := 0;
begin
  if new.status = 'canceled' then
    update private.cart_order_holds
    set state = 'released', settled_at = pg_catalog.clock_timestamp(), release_reason = 'order_closed'
    where order_id = new.id and state = 'awaiting_payment';
    return null;
  end if;

  select hold.* into v_hold
  from private.cart_order_holds as hold
  where hold.order_id = new.id and hold.state = 'awaiting_payment'
  for update;
  if not found then
    return null;
  end if;

  -- 결제는 이미 확정됐다. 장바구니 정리가 어떤 이유로 실패해도 결제 확정을 되돌리지 않는다.
  -- 장바구니 advisory('cart:')는 잡지 않고 해당 줄의 행 잠금만 쓴다. 장바구니 변경 RPC는 'cart:'를
  -- 쥔 채 INSERT 계정 fence에서 account-action을 기다리는데, finalizer는 이미 account-action을 쥐고
  -- 있으므로 여기서 'cart:'를 기다리면 교착한다. 새 장바구니 주문은 이전 주문 행을 먼저 잠그므로
  -- 이 정리와 스냅샷 비교가 엇갈리지 않는다.
  begin
    for v_line in select value from pg_catalog.jsonb_array_elements(v_hold.lines) loop
      v_ordered := (v_line ->> 'qty')::integer;
      select cart.* into v_cart
      from public.cart_items as cart
      where cart.user_id = v_hold.user_id
        and cart.variant_id = (v_line ->> 'variantId')::uuid
        and cart.input_key = v_line ->> 'inputKey'
      for update;
      if not found then
        v_outcome := 'absent';
      elsif v_cart.qty > v_ordered then
        begin
          update public.cart_items
          set qty = qty - v_ordered
          where user_id = v_hold.user_id and variant_id = v_cart.variant_id and input_key = v_cart.input_key;
          v_outcome := 'decreased';
        exception when others then
          -- 장바구니 행 트리거·잠금 등으로 수량을 바꾸지 못했다. 결제는 확정됐으므로 줄은 그대로 둔다.
          v_outcome := 'kept';
        end;
      else
        delete from public.cart_items
        where user_id = v_hold.user_id and variant_id = v_cart.variant_id and input_key = v_cart.input_key;
        v_outcome := 'removed';
      end if;
      v_result := v_result || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'variantId', v_line -> 'variantId', 'inputKey', v_line -> 'inputKey', 'orderedQty', v_ordered,
        'cartQtyBefore', case when v_outcome = 'absent' then null else v_cart.qty end, 'outcome', v_outcome));
    end loop;

    delete from public.cart_coupon_selections as selection
    where selection.user_id = v_hold.user_id
      and selection.user_coupon_id in (
        select redemption.user_coupon_id from public.coupon_redemptions as redemption
        where redemption.order_id = new.id and redemption.status = 'applied');
    get diagnostics v_cleared = row_count;

    update private.cart_order_holds
    set state = 'consumed', settled_at = pg_catalog.clock_timestamp(),
        consumption = pg_catalog.jsonb_build_object('lines', v_result, 'couponSelectionCleared', v_cleared > 0)
    where order_id = new.id;
  exception when others then
    update private.cart_order_holds
    set state = 'consumed', settled_at = pg_catalog.clock_timestamp(),
        consumption = pg_catalog.jsonb_build_object('failed', sqlstate)
    where order_id = new.id and state = 'awaiting_payment';
  end;
  return null;
end;
$$

-- legacy 주문 코어: 앱 진입점이 장바구니 유지를 켠 카드 주문만 장바구니 줄과 쿠폰 선택을
-- 남긴다. 나머지 본문(가격·재고·쿠폰·적립금·무통장 시도)은 현재 정의 그대로다.
do $$
declare
  v_definition text;
  v_cart_anchor text := E'    delete from public.cart_items\n    where user_id = v_user\n      and id = r.cart_item_id;';
  v_coupon_anchor text := E'    delete from public.cart_coupon_selections\n    where user_id = v_user\n      and user_coupon_id = v_selected_coupon;';
begin
  v_definition := pg_catalog.pg_get_functiondef('private.place_order_before_shipments(jsonb,uuid,public.order_payment_method)'::regprocedure);
  if (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_cart_anchor, ''))) / pg_catalog.length(v_cart_anchor) <> 1
    or (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_coupon_anchor, ''))) / pg_catalog.length(v_coupon_anchor) <> 1
  then
    raise exception 'cart_retention_place_order_anchor_changed';
  end if;
  v_definition := pg_catalog.replace(v_definition, v_cart_anchor,
    E'    -- 카드 장바구니 주문은 결제 확정 때 장바구니에서 뺀다(ADR-0026).\n'
    || E'    if not (p_payment_method = ''card'' and private.cart_retention_active()) then\n'
    || E'      delete from public.cart_items\n      where user_id = v_user\n        and id = r.cart_item_id;\n'
    || E'    end if;');
  v_definition := pg_catalog.replace(v_definition, v_coupon_anchor,
    E'    if not (p_payment_method = ''card'' and private.cart_retention_active()) then\n'
    || E'      delete from public.cart_coupon_selections\n      where user_id = v_user\n        and user_coupon_id = v_selected_coupon;\n'
    || E'    end if;');
  execute v_definition;
end;
$$

-- 앱의 legacy 장바구니 주문 진입점. 이전 미결제 장바구니 주문을 먼저 닫고(계정 잠금 →
-- 주문 → 장바구니 잠금 순서), 카드 주문이면 장바구니를 남긴 채 보류를 기록한다.
create or replace function public.place_order_with_cart_snapshot(
 p_user_id uuid,p_address jsonb,p_checkout_key uuid,p_payment_method public.order_payment_method,
 p_store_credit_amount bigint,p_expected_user_coupon_id uuid,p_expected_cart jsonb
) returns uuid language plpgsql volatile security definer set search_path='' as $$
declare expected_cart jsonb; actual_cart jsonb; entry jsonb; placed uuid;
begin
 if p_user_id is null or p_checkout_key is null then raise invalid_parameter_value using message='invalid_checkout_cart_snapshot'; end if;
 -- Match the pre-existing checkout/coupon lock order: user, then cart. Replays
 -- validate their original order contract without looking at today's cart.
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
 if exists(select 1 from public.orders where user_id=p_user_id and checkout_key=p_checkout_key) then
   return public.place_order_with_store_credits(p_user_id,p_address,p_checkout_key,p_payment_method,p_store_credit_amount,p_expected_user_coupon_id);
 end if;
 if jsonb_typeof(p_expected_cart) is distinct from 'array' then raise invalid_parameter_value using message='invalid_checkout_cart_snapshot'; end if;
 for entry in select value from jsonb_array_elements(p_expected_cart) loop
   if jsonb_typeof(entry)<>'object' or not(entry ?& array['good_id','variant_id','qty','input_revision','input_values'])
     or exists(select 1 from jsonb_object_keys(entry) key where key not in ('good_id','variant_id','qty','input_revision','input_values'))
     or jsonb_typeof(entry->'good_id')<>'string' or nullif(btrim(entry->>'good_id'),'') is null
     or jsonb_typeof(entry->'variant_id')<>'string' or entry->>'variant_id'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or jsonb_typeof(entry->'qty')<>'number' or entry->>'qty'!~'^[1-9][0-9]*$'
     or jsonb_typeof(entry->'input_revision')<>'number' or entry->>'input_revision'!~'^(0|[1-9][0-9]*)$'
     or jsonb_typeof(entry->'input_values')<>'object' then
     raise invalid_parameter_value using message='invalid_checkout_cart_snapshot';
   end if;
 end loop;
 -- 이전 미결제 장바구니 주문의 재고·쿠폰·적립금·구매 한도를 먼저 돌려준다(ADR-0026).
 perform private.supersede_unpaid_cart_orders(p_user_id,true);
 -- 주문 → account-action → 장바구니 순서. 새 주문 INSERT의 계정 fence도 같은 키를 다시 잡는다.
 perform private.lock_account_action_subject(p_user_id);
 -- Compare canonical values, not labels or hashes supplied by the browser.
 select coalesce(jsonb_agg(value order by value->>'good_id',(value->>'variant_id')::uuid,value->>'input_revision',(value->'input_values')::text),'[]')
   into expected_cart from jsonb_array_elements(p_expected_cart);
 perform pg_advisory_xact_lock(hashtextextended('cart:'||p_user_id::text,0));
 select coalesce(jsonb_agg(jsonb_build_object('good_id',good_id,'variant_id',variant_id,'qty',qty,
   'input_revision',input_revision,'input_values',input_values) order by good_id,variant_id,input_revision::text,input_values::text),'[]')
   into actual_cart from public.cart_items where user_id=p_user_id;
 if expected_cart is distinct from actual_cart then raise sqlstate 'PT409' using message='cart_snapshot_changed'; end if;
 if p_payment_method='card' then perform set_config('icons.cart_order_retention','on',true); end if;
 placed:=public.place_order_with_store_credits(p_user_id,p_address,p_checkout_key,p_payment_method,p_store_credit_amount,p_expected_user_coupon_id);
 perform set_config('icons.cart_order_retention','',true);
 if p_payment_method='card' then perform private.record_cart_order_hold(placed,p_user_id,'legacy_checkout'); end if;
 return placed;
end $$

-- 거래 런타임 장바구니 어댑터. 계정 잠금 → 이전 미결제 주문 닫기 → 장바구니 잠금 순서.
CREATE OR REPLACE FUNCTION public.place_cart_goods_transaction(p_user_id uuid, p_expected_cart jsonb, p_address jsonb, p_quote_id uuid, p_checkout_key uuid, p_payment_method order_payment_method)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare selection jsonb;source jsonb;selected_coupon uuid;quoted_coupon uuid;combined boolean;result uuid;begin
 selection:=private.cart_goods_transaction_expected_selection(p_expected_cart);source:=private.goods_cart_transaction_source(p_user_id,selection);
 -- 계정 단위 직렬화는 사용자 advisory만 먼저 잡는다. account-action·profiles(actor 잠금)는
 -- 이전 주문 행을 잠근 뒤에 잡아야 claim·prepare·finalize(주문 → account-action)와 엇갈리지 않는다.
 if p_user_id is null then raise invalid_parameter_value using message='invalid_transaction_actor';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
 if exists(select 1 from private.order_goods_transactions where actor_id=p_user_id and checkout_key=p_checkout_key) then
  perform private.lock_goods_transaction_source(p_user_id,source);
  return private.place_goods_transaction(p_user_id,source,selection,p_address,p_quote_id,p_checkout_key,p_payment_method);end if;
 -- 이전 미결제 장바구니 주문의 재고·쿠폰·적립금·구매 한도를 먼저 돌려준다(ADR-0026).
 perform private.supersede_unpaid_cart_orders(p_user_id,true);
 perform private.lock_goods_transaction_source(p_user_id,source);
 perform private.assert_cart_goods_transaction_selection(p_user_id,selection);
 select user_coupon_id into selected_coupon from public.cart_coupon_selections where user_id=p_user_id;
 select user_coupon_id,user_coupon_ids is not null into quoted_coupon,combined from private.goods_transaction_quotes where id=p_quote_id and actor_id=p_user_id;
 if found and not combined and selected_coupon is distinct from quoted_coupon then raise sqlstate 'PT409' using message='coupon_snapshot_changed';end if;
 result:=private.place_goods_transaction(p_user_id,source,selection,p_address,p_quote_id,p_checkout_key,p_payment_method);
 if p_payment_method='bank_transfer' then
  -- 무통장은 접수 = 주문 완료(입금대기)다. 종전처럼 지금 장바구니에서 뺀다.
  -- Only this adapter owns the live cart. Gift/subscription never read it.
  delete from public.cart_items cart where user_id=p_user_id and exists(select 1 from jsonb_array_elements(selection) selected
   where selected->>'goodId'=cart.good_id and (selected->>'variantId')::uuid=cart.variant_id and (selected->>'qty')::integer=cart.qty
    and (selected->>'inputRevision')::integer=cart.input_revision and selected->'inputValues'=cart.input_values);
  delete from public.cart_coupon_selections where user_id=p_user_id and (combined or user_coupon_id=quoted_coupon);
 else
  -- 카드는 결제 확정 때 장바구니에서 뺀다(ADR-0026).
  perform private.record_cart_order_hold(result,p_user_id,'cart_transaction');
 end if;
 return result;
end $function$

-- 복구 진입점도 같은 순서를 따른다. 새 주문이면 place_cart_goods_transaction이 사용자 advisory →
-- 이전 주문 닫기 → actor/장바구니 잠금을 한다. 여기서 actor(account-action·profiles)를 먼저 잡으면
-- 그 순서가 뒤집힌다. 원래 영수증 재생은 종전처럼 actor 잠금 아래에서 한다(20261020085341).
create or replace function public.resume_cart_goods_transaction(p_user_id uuid,p_quote_id uuid,p_checkout_key uuid,p_payment_method public.order_payment_method,
 p_allow_new boolean default false) returns uuid language plpgsql volatile security definer set search_path='' as $$
declare existing private.order_goods_transactions;quoted private.goods_transaction_quotes;source jsonb;receipt jsonb;expected_cart jsonb;begin
 if p_user_id is null then raise invalid_parameter_value using message='invalid_transaction_actor';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
 if p_quote_id is null or p_checkout_key is null or p_payment_method is null or p_allow_new is null then
  raise invalid_parameter_value using message='invalid_transaction_resume';end if;
 select * into existing from private.order_goods_transactions where actor_id=p_user_id and checkout_key=p_checkout_key;
 if found then
  perform private.lock_goods_transaction_actor(p_user_id);
  if existing.source_kind<>'cart' then raise sqlstate 'PT409' using message='checkout_key_conflict';end if;
  source:=jsonb_build_object('kind',existing.source_kind,'id',existing.source_id,'revision',existing.source_revision);
  receipt:=private.replay_goods_transaction_receipt(p_user_id,source,p_quote_id,p_checkout_key,p_payment_method);
  return (receipt->>'orderId')::uuid;
 end if;
 if not p_allow_new then raise check_violation using message='transaction_new_payment_disabled';end if;
 select * into quoted from private.goods_transaction_quotes where id=p_quote_id and actor_id=p_user_id;
 if not found or quoted.source->>'kind'<>'cart' or quoted.source->>'id'<>p_user_id::text then
  raise sqlstate 'PT409' using message='transaction_quote_expired';end if;
 select jsonb_agg(jsonb_build_object('good_id',value->'goodId','variant_id',value->'variantId','qty',value->'qty',
  'input_revision',value->'inputRevision','input_values',value->'inputValues')) into expected_cart from jsonb_array_elements(quoted.selection);
 return public.place_cart_goods_transaction(p_user_id,expected_cart,quoted.address,p_quote_id,p_checkout_key,p_payment_method);
end $$

create function private.record_order_paid_mark() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.status='paid' and old.status is distinct from 'paid' then
  insert into private.order_paid_marks(order_id,paid_at) values(new.id,clock_timestamp()) on conflict(order_id) do nothing;
 end if;
 return null;
end $$

-- 3. 수동·자동 공통 전이. 호출자는 주문 → 배송 건 순서로 잠그고 paid임을 확인한 뒤 부른다.
create function private.confirm_paid_order(p_order_id uuid,p_actor uuid,p_context jsonb) returns void
language plpgsql set search_path='' as $$
begin
 perform private.assert_order_dispatch_allowed(p_order_id);
 update public.orders set status='confirmed',confirmed_at=clock_timestamp() where id=p_order_id and status='paid';
 if not found then raise exception using message='invalid_order_transition';end if;
 insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'admin.order.status_updated','order:'||p_order_id,
  jsonb_build_object('from','paid','to','confirmed')||coalesce(p_context,'{}'::jsonb));
end $$

CREATE OR REPLACE FUNCTION public.admin_update_order_status(p_order_id uuid, p_status order_status, p_carrier text, p_tracking_number text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid());purchase public.orders;
begin
  perform private.require_operator_capability('sales.manage',false);

 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required';end if;
 if p_status in ('shipping','delivered') then
   perform public.admin_update_shipment_status(private.single_order_shipment(p_order_id),p_status::text,p_carrier,p_tracking_number);return;
 end if;
 select * into purchase from public.orders where id=p_order_id for update;
 if not found then raise no_data_found using message='order_not_found';end if;
 perform id from public.order_shipments where order_id=p_order_id order by id for update;
 if p_status is null or p_status not in ('confirmed','shipping','delivered') then raise check_violation using message='invalid_order_status';end if;
 if p_status in ('shipping','delivered') then
   perform public.admin_update_shipment_status(private.single_order_shipment(p_order_id),p_status::text,p_carrier,p_tracking_number);return;
 end if;
 if purchase.status='confirmed' then return;end if;
 if purchase.status<>'paid' then raise exception using message='invalid_order_transition';end if;
 perform private.confirm_paid_order(p_order_id,actor,'{}'::jsonb);
end $function$

create function public.admin_get_auto_order_confirmation() returns jsonb
language plpgsql security definer set search_path='' as $$
begin
 perform private.require_operator_capability('sales.manage',false);
 return private.auto_order_confirmation_document(clock_timestamp());
end $$

-- 실행을 닫고 시스템 감사를 남긴다. 완료·설정 변경·끄기 모두 같은 기록을 쓴다.
create function private.finish_auto_order_confirmation_run(p_run_date date,p_reason text) returns void
language plpgsql security definer set search_path='' as $$
declare run private.auto_order_confirmation_runs;
begin
 update private.auto_order_confirmation_runs set finished_at=clock_timestamp() where run_date=p_run_date and finished_at is null returning * into run;
 if not found then return;end if;
 insert into public.audit_log(actor_id,action,target,diff) values(null,'system.order.auto_confirmation_run','auto_order_confirmation:'||run.run_date,
  jsonb_build_object('runDate',run.run_date,'cutoffAt',run.cutoff_at,'enabledAt',run.enabled_at,'settingsRevision',run.settings_revision,
   'confirmed',run.confirmed_count,'excluded',run.excluded_count,'batches',run.batch_count,'closedBy',p_reason));
end $$

-- 5. 운영자 설정 변경. 켤 때마다 enabled_at을 새로 잡아 그 뒤 결제분만 대상이 된다.
create function public.admin_save_auto_order_confirmation(p_enabled boolean,p_run_time text,p_expected_revision bigint,p_operation_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid;previous private.auto_order_confirmation_settings;request jsonb;receipt jsonb;at_value timestamptz;
begin
 actor:=private.require_operator_capability('sales.manage',false);
 if p_enabled is null or p_run_time is null or p_run_time!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'
  or p_expected_revision is null or p_expected_revision<1 or p_operation_id is null then
  raise invalid_parameter_value using message='invalid_auto_order_confirmation';end if;
 request:=jsonb_build_object('enabled',p_enabled,'runTime',p_run_time,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('auto-order-confirmation-operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.auto_order_confirmation.settings',request);
 if receipt is not null then return receipt;end if;
 select * into previous from private.auto_order_confirmation_settings where singleton for update;
 if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='auto_order_confirmation_changed';end if;
 at_value:=clock_timestamp();
 update private.auto_order_confirmation_settings set revision=revision+1,enabled=p_enabled,run_time=p_run_time::time,
  enabled_at=case when p_enabled and not previous.enabled then at_value else previous.enabled_at end,
  updated_by=actor,updated_at=at_value where singleton;
 -- 끄면 이어 가던 실행도 닫는다. 다시 켜면 새 켠 시각 기준의 실행이 새로 시작된다.
 if not p_enabled then
  perform private.finish_auto_order_confirmation_run(r.run_date,'disabled')
  from private.auto_order_confirmation_runs r where r.finished_at is null order by r.run_date;
 end if;
 receipt:=private.auto_order_confirmation_document(at_value);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.auto_order_confirmation.settings','auto_order_confirmation',
  jsonb_build_object('request',request,'before',jsonb_build_object('enabled',previous.enabled,'runTime',to_char(previous.run_time,'HH24:MI'),'enabledAt',previous.enabled_at),'result',receipt));
 return receipt;
end $$

create function private.run_auto_order_confirmation(p_now timestamptz,p_batch integer default 200) returns jsonb
language plpgsql security definer set search_path='' as $$
declare s private.auto_order_confirmation_settings;run private.auto_order_confirmation_runs;today date;cutoff timestamptz;
 candidate record;purchase public.orders;outcome text;detail text;confirmed integer:=0;excluded integer:=0;seen integer:=0;
 base_timeout text:=current_setting('lock_timeout');
begin
 if p_now is null or p_batch is null or p_batch not between 1 and 1000 then raise invalid_parameter_value using message='invalid_auto_order_confirmation_run';end if;
 today:=(p_now at time zone 'Asia/Seoul')::date;
 -- 잠금 없는 사전 확인: 대부분의 틱은 여기서 끝난다.
 select * into s from private.auto_order_confirmation_settings where singleton;
 if not found or not s.enabled then return jsonb_build_object('status','disabled');end if;
 if not exists(select 1 from private.auto_order_confirmation_runs where finished_at is null and run_date<=today) then
  cutoff:=(today+s.run_time) at time zone 'Asia/Seoul';
  if p_now<cutoff then return jsonb_build_object('status','before_cutoff','cutoffAt',cutoff);end if;
  if s.enabled_at>=cutoff then return jsonb_build_object('status','enabled_after_cutoff','cutoffAt',cutoff);end if;
  if exists(select 1 from private.auto_order_confirmation_runs where run_date=today) then return jsonb_build_object('status','already_ran','runDate',today);end if;
 end if;
 -- 동시 틱을 직렬화하고, 실행 중에는 설정 변경을 기다리게 한다.
 perform pg_advisory_xact_lock(hashtextextended('auto-order-confirmation-run',0));
 select * into s from private.auto_order_confirmation_settings where singleton for share;
 if not s.enabled then return jsonb_build_object('status','disabled');end if;
 -- 이전 날짜에서 넘어온 실행을 포함해 가장 이른 미완료 실행을 먼저 이어 간다.
 select * into run from private.auto_order_confirmation_runs where finished_at is null and run_date<=today order by run_date limit 1 for update;
 if found then
  -- 실행 도중 껐다 켜면 새 켠 시각 이전 결제분을 더 처리하지 않고 그 실행을 닫는다.
  if s.enabled_at is distinct from run.enabled_at then
   perform private.finish_auto_order_confirmation_run(run.run_date,'settings_changed');
   return jsonb_build_object('status','settings_changed','runDate',run.run_date);
  end if;
 else
  cutoff:=(today+s.run_time) at time zone 'Asia/Seoul';
  if p_now<cutoff then return jsonb_build_object('status','before_cutoff','cutoffAt',cutoff);end if;
  if s.enabled_at>=cutoff then return jsonb_build_object('status','enabled_after_cutoff','cutoffAt',cutoff);end if;
  insert into private.auto_order_confirmation_runs(run_date,cutoff_at,enabled_at,settings_revision)
   values(today,cutoff,s.enabled_at,s.revision) on conflict(run_date) do nothing;
  select * into run from private.auto_order_confirmation_runs where run_date=today for update;
  if run.finished_at is not null then return jsonb_build_object('status','already_ran','runDate',today);end if;
 end if;
 for candidate in
  select picked.id from (
   select o.id from public.orders o join private.order_paid_marks m on m.order_id=o.id
   where o.status='paid' and m.paid_at>=run.enabled_at and m.paid_at<=run.cutoff_at
    and not exists(select 1 from private.auto_order_confirmation_outcomes x where x.run_date=run.run_date and x.order_id=o.id)
   order by m.paid_at,o.id limit p_batch) picked
  order by picked.id
 loop
  seen:=seen+1;detail:=null;
  -- 잠그기 전에 이미 보이는 제외 사유는 잠금 없이 남긴다.
  outcome:=private.auto_order_confirmation_blocker(candidate.id);
  if outcome is null then
   begin
    perform set_config('lock_timeout','3s',true);
    -- 고객 직접 취소·수동 발주확인과 같은 주문 → 배송 건 순서. 먼저 잠근 쪽만 반영된다.
    select * into purchase from public.orders where id=candidate.id for update;
    perform id from public.order_shipments where order_id=candidate.id order by id for update;
    if purchase.status<>'paid' then raise sqlstate 'AOC01' using message='status_changed';end if;
    outcome:=private.auto_order_confirmation_blocker(candidate.id);
    if outcome is not null then raise sqlstate 'AOC01' using message=outcome;end if;
    perform private.confirm_paid_order(candidate.id,null,jsonb_build_object('trigger','auto_order_confirmation','runDate',run.run_date,'cutoffAt',run.cutoff_at));
    outcome:='confirmed';
    perform set_config('lock_timeout',base_timeout,true);
   exception
    -- 블록을 되돌리므로 제외·실패한 주문의 잠금은 여기서 풀린다.
    when sqlstate 'AOC01' then outcome:=sqlerrm;
    when lock_not_available or deadlock_detected then outcome:='locked';detail:=sqlstate;
    when others then outcome:='failed';detail:=left(sqlstate||' '||sqlerrm,300);
   end;
  end if;
  insert into private.auto_order_confirmation_outcomes(run_date,order_id,outcome,detail) values(run.run_date,candidate.id,outcome,detail);
  if outcome='confirmed' then confirmed:=confirmed+1;elsif outcome<>'status_changed' then excluded:=excluded+1;end if;
 end loop;
 update private.auto_order_confirmation_runs set confirmed_count=confirmed_count+confirmed,excluded_count=excluded_count+excluded,
  batch_count=batch_count+1 where run_date=run.run_date;
 if seen<p_batch then perform private.finish_auto_order_confirmation_run(run.run_date,'completed');end if;
 return jsonb_build_object('status',case when seen<p_batch then 'finished' else 'continuing' end,'runDate',run.run_date,
  'confirmed',confirmed,'excluded',excluded);
end $$

-- 기한 없는 배송완료 주문에 현재 정책 기한을 채운다. 정책이 꺼져 있으면 아무것도 하지 않는다.
-- 확정·클레임·보류 판정은 그대로 자동 확정 작업(settle_delivered_orders)이 다시 검사한다.
create function private.backfill_purchase_confirmation_due_dates() returns integer
language plpgsql security definer set search_path='' as $$
declare p private.purchase_confirmation_policy;snapshot jsonb;updated integer:=0;inserted integer:=0;
begin
 select * into p from private.purchase_confirmation_policy where singleton;
 if not p.auto_enabled or p.auto_after_days is null then return 0;end if;
 snapshot:=jsonb_build_object('revision',p.revision,'autoEnabled',true,'autoAfterDays',p.auto_after_days,
  'buyerExtensionDays',p.buyer_extension_days,'retroactive',true);
 update private.order_purchase_confirmations c set revision=c.revision+1,policy_snapshot=snapshot,
  auto_due_at=o.delivered_at+make_interval(days=>p.auto_after_days)
 from public.orders o where o.id=c.order_id and o.status='delivered' and o.delivered_at is not null
  and c.auto_due_at is null and c.confirmed_at is null;
 get diagnostics updated=row_count;
 insert into private.order_purchase_confirmations(order_id,revision,policy_snapshot,auto_due_at)
 select o.id,1,snapshot,o.delivered_at+make_interval(days=>p.auto_after_days) from public.orders o
 where o.status='delivered' and o.delivered_at is not null
  and not exists(select 1 from private.order_purchase_confirmations c where c.order_id=o.id)
 on conflict(order_id) do nothing;
 get diagnostics inserted=row_count;
 return updated+inserted;
end $$

CREATE OR REPLACE FUNCTION public.admin_save_purchase_confirmation_policy(p_values jsonb, p_revision bigint, p_operation_id uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare policy private.purchase_confirmation_policy; prior public.audit_log; request jsonb; result jsonb; field text; retroactive integer;
begin
 perform private.purchase_confirmation_identity(p_actor,p_session,true);
 if p_operation_id is null or p_revision is null or p_revision<1 or jsonb_typeof(p_values) is distinct from 'object'
  or (select count(*) from jsonb_object_keys(p_values))<>5 or exists(select 1 from jsonb_object_keys(p_values) k where k not in ('autoEnabled','autoAfterDays','buyerExtensionDays','evidence','acknowledged'))
  or jsonb_typeof(p_values->'autoEnabled') is distinct from 'boolean' or p_values->'acknowledged' is distinct from 'true'::jsonb
  or jsonb_typeof(p_values->'evidence') is distinct from 'string' or char_length(btrim(p_values->>'evidence')) not between 1 and 2000 then raise invalid_parameter_value;end if;
 foreach field in array array['autoAfterDays','buyerExtensionDays'] loop
  if p_values->field<>'null'::jsonb and (jsonb_typeof(p_values->field)<>'number' or p_values->>field!~'^[1-9][0-9]*$' or (p_values->>field)::numeric>36500) then raise invalid_parameter_value;end if;
 end loop;
 if p_values->'autoEnabled'='true'::jsonb and p_values->'autoAfterDays'='null'::jsonb then raise invalid_parameter_value;end if;
 select * into policy from private.purchase_confirmation_policy where singleton for update;
 request:=jsonb_build_object('values',p_values,'revision',p_revision,'sessionId',p_session);
 select * into prior from public.audit_log where id=p_operation_id;
 if found then
  if prior.actor_id is distinct from p_actor or prior.action<>'admin.purchase_confirmation.policy' or prior.diff->'request' is distinct from request then raise sqlstate 'PT409';end if;
  return prior.diff->'result';end if;
 if policy.revision<>p_revision then raise sqlstate 'PT409' using message='purchase_confirmation_changed';end if;
 update private.purchase_confirmation_policy set revision=revision+1,auto_enabled=(p_values->>'autoEnabled')::boolean,auto_after_days=(p_values->>'autoAfterDays')::integer,
  buyer_extension_days=(p_values->>'buyerExtensionDays')::integer,evidence=btrim(p_values->>'evidence'),updated_at=clock_timestamp() where singleton;
 retroactive:=private.backfill_purchase_confirmation_due_dates();
 result:=private.purchase_confirmation_policy_document();
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_actor,'admin.purchase_confirmation.policy','purchase_confirmation',
  jsonb_build_object('request',request,'result',result,'retroactiveDueDates',retroactive));
 return result;
end $function$

create function public.admin_staging_test_tools() returns jsonb
language plpgsql security definer set search_path='' as $$
begin
 perform private.require_operator_capability('sales.manage',false);
 return jsonb_build_object('testDelivery',private.staging_test_tools_available());
end $$

-- 발주확인 이후 택배 주문의 남은 배송 건을 운송장 없이 배송완료로 기록한다. 발송 메일 대기열은
-- 준비 → 배송중 전이에서만 생기므로 준비 → 배송완료로 바로 옮기면 메일이 생기지 않는다.
-- 합포장 소속이면 운영 배송완료와 같이 묶음 전체를 함께 처리한다(lock_shipment_pack_scope:
-- 주문 id 순 → 배송 건 id 순 잠금). 주문 상태는 기존 배송 건 집계 트리거가 파생하고,
-- 구매확정 기한도 기존 트리거가 저장한다.
create function public.admin_mark_staging_test_delivered(p_order_number text,p_operation_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid;purchase public.orders;targets uuid[];ids uuid[];shipment record;delivered integer:=0;at_value timestamptz;request jsonb;receipt jsonb;
begin
 actor:=private.require_operator_capability('sales.manage',false);
 if not private.staging_test_tools_available() then raise insufficient_privilege using message='staging_test_delivery_unavailable';end if;
 if p_order_number is null or p_order_number!~'^[0-9]{8}1[0-9]{7}$' or p_operation_id is null then
  raise invalid_parameter_value using message='invalid_staging_test_delivery';end if;
 request:=jsonb_build_object('orderNumber',p_order_number);
 perform pg_advisory_xact_lock(hashtextextended('staging-test-delivery:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.staging.test_delivered',request);
 if receipt is not null then return receipt;end if;
 select * into purchase from public.orders where order_number=p_order_number;
 if not found then raise no_data_found using message='order_not_found';end if;
 select coalesce(array_agg(id order by id),'{}'::uuid[]) into targets from public.order_shipments where order_id=purchase.id and status in ('ready','shipping');
 if cardinality(targets)=0 then
  select * into purchase from public.orders where id=purchase.id for update;
  if purchase.status not in ('confirmed','shipping') then raise check_violation using message='staging_test_delivery_requires_confirmed';end if;
  raise check_violation using message='staging_test_delivery_nothing_to_deliver';
 end if;
 ids:=private.lock_shipment_pack_scope(targets);
 if exists(select 1 from public.order_shipments where order_id=purchase.id and status in ('ready','shipping') and id<>all(ids)) then
  raise sqlstate 'PT409' using message='shipment_pack_changed';end if;
 if exists(select 1 from public.orders o where o.id in(select order_id from public.order_shipments where id=any(ids)) and o.status not in ('confirmed','shipping')) then
  raise check_violation using message='staging_test_delivery_requires_confirmed';end if;
 perform private.assert_order_dispatch_allowed(order_id) from (select distinct order_id from public.order_shipments where id=any(ids) order by order_id) packed;
 if exists(select 1 from public.order_shipments where id=any(ids) and status in ('ready','shipping') and delivery_method<>'parcel') then
  raise check_violation using message='staging_test_delivery_parcel_only';end if;
 at_value:=clock_timestamp();
 for shipment in select id from public.order_shipments where id=any(ids) and status in ('ready','shipping') order by id loop
  perform private.assert_shipment_preorder_ready(shipment.id);
  update public.order_shipments set status='delivered',shipped_at=coalesce(shipped_at,at_value),delivered_at=at_value where id=shipment.id;
  delivered:=delivered+1;
 end loop;
 if delivered=0 then raise check_violation using message='staging_test_delivery_nothing_to_deliver';end if;
 select * into purchase from public.orders where id=purchase.id;
 receipt:=jsonb_build_object('orderId',purchase.id,'orderNumber',purchase.order_number,'status',purchase.status,'deliveredShipments',delivered,
  'orderCount',(select count(distinct order_id) from public.order_shipments where id=any(ids))::integer,'deliveredAt',at_value);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.staging.test_delivered','order:'||purchase.id,
  jsonb_build_object('request',request,'result',receipt,'staging',true,'shipmentIds',to_jsonb(ids)));
 return receipt;
end $$

do $patch$
declare definition text; anchor text; replacement text;
begin
 definition:=pg_get_functiondef('public.admin_prepare_order_delay_notice(uuid,uuid[],text,text,date)'::regprocedure);
 anchor:=$old$select array_agg(origin_name_snapshot||' · '||upper(right(id::text,8)) order by id) into labels from public.order_shipments where id=any(g.shipment_ids);$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'delay_notice_label_anchor_changed'; end if;
 replacement:=$new$select array_agg(origin_name_snapshot||' · '||coalesce(shipment_number,upper(right(id::text,8))) order by id) into labels from public.order_shipments where id=any(g.shipment_ids);$new$;
 definition:=replace(definition,anchor,replacement);
 anchor:=$old$(select string_agg(upper(right(x::text,8)),', ' order by x) from unnest(g.shipment_ids[1:3])x)$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'delay_notice_body_anchor_changed'; end if;
 replacement:=$new$(select string_agg(coalesce(s.shipment_number,upper(right(s.id::text,8))),', ' order by s.id) from public.order_shipments s where s.id=any(g.shipment_ids[1:3]))$new$;
 execute replace(definition,anchor,replacement);

 definition:=pg_get_functiondef('public.claim_order_delay_email_jobs(integer)'::regprocedure);
 anchor:=$old$'orderId',c.order_id,$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'delay_email_order_anchor_changed'; end if;
 definition:=replace(definition,anchor,anchor||$new$'orderNumber',(select o.order_number from public.orders o where o.id=c.order_id),$new$);
 anchor:=$old$'shipmentLabels',c.shipment_labels$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'delay_email_label_anchor_changed'; end if;
 execute replace(definition,anchor,$new$'shipmentLabels',(select coalesce(array_agg(coalesce(s.shipment_number,upper(right(s.id::text,8))) order by s.id),'{}'::text[])
   from public.order_shipments s where s.id=any(c.shipment_ids))$new$);

 -- 주문 상세 타임라인: 감사 기록의 trigger(예: T3 자동 발주확인 'auto_order_confirmation')를 판독기가 함께 낸다.
 definition:=pg_get_functiondef('private.admin_order_detail_before_preorder(uuid)'::regprocedure);
 anchor:=$old$'body',case when a.action='admin.order.note' then a.diff->>'body' end)$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'order_timeline_trigger_anchor_changed'; end if;
 execute replace(definition,anchor,$new$'body',case when a.action='admin.order.note' then a.diff->>'body' end,'trigger',a.diff->>'trigger')$new$);
end $patch$

-- 본문만 바꿨다. 기존 권한 계약은 그대로 다시 등록해 지문을 맞춘다.
do $$declare signature text;fn regprocedure;contract record;registered boolean;begin
 foreach signature in array ARRAY[
  'public.admin_prepare_order_delay_notice(uuid,uuid[],text,text,date)',
  'public.claim_order_delay_email_jobs(integer)',
  'private.admin_order_detail_before_preorder(uuid)'
 ] loop
  fn:=signature::regprocedure;registered:=false;
  select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure=fn;
  if found then perform private.register_operator_rpc_contract(fn,contract.capability,contract.guard_kind,contract.legacy_admin_only);registered:=true; end if;
  if exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure=fn) then
   perform private.register_operator_internal_contract(fn);registered:=true;
  end if;
  if not registered and signature like 'public.admin_%' then raise exception 'operational_rpc_contract_missing: %',signature; end if;
 end loop;
end $$

-- 출고지시 전달 표시(admin_mark_shipments_exported)와 서원 접미사 기록을 한 트랜잭션으로 묶는다.
-- 표시가 실패하면 기록도 남지 않는다. 라벨은 이번에 표시하는 서원 출고지 배송 건만 받는다.
create function public.admin_mark_seowon_shipments_exported(target_versions jsonb,target_batch uuid,target_labels jsonb) returns integer
language plpgsql security definer set search_path='' as $$
declare actor uuid; total integer;
begin
  actor:=private.require_operator_capability('sales.manage',false);
  if target_batch is null or jsonb_typeof(target_labels) is distinct from 'array' or jsonb_array_length(target_labels) not between 1 and 1000
    or jsonb_typeof(target_versions) is distinct from 'array'
    or exists(select 1 from jsonb_array_elements(target_labels) label where jsonb_typeof(label)<>'object'
      or label->>'shipmentId' is null or label->>'shipmentId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or jsonb_typeof(label->'suffix')<>'string' or label->>'suffix' !~ '^([0-9]{2,3})?$')
    or (select count(distinct lower(label->>'shipmentId')) from jsonb_array_elements(target_labels) label)<>jsonb_array_length(target_labels)
    or exists(select 1 from jsonb_array_elements(target_labels) label where not exists(
      select 1 from jsonb_array_elements(target_versions) version where lower(version->>'id')=lower(label->>'shipmentId'))) then
    raise invalid_parameter_value using message='invalid_seowon_export_labels';
  end if;
  if exists(select 1 from jsonb_array_elements(target_labels) label
    left join public.order_shipments s on s.id=(label->>'shipmentId')::uuid
    left join public.fulfillment_origins origin on origin.id=s.origin_id
    where s.id is null or origin.export_template is distinct from 'seowon_xlsx') then
    raise check_violation using message='invalid_seowon_export_labels';
  end if;
  total:=public.admin_mark_shipments_exported(target_versions);
  insert into private.seowon_export_labels(shipment_id,export_batch,recipient_suffix,recorded_by)
  select (label->>'shipmentId')::uuid,target_batch,label->>'suffix',actor from jsonb_array_elements(target_labels) label
  on conflict(shipment_id) do update set export_batch=excluded.export_batch,recipient_suffix=excluded.recipient_suffix,
    recorded_by=excluded.recorded_by,recorded_at=clock_timestamp();
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.shipment.seowon_labels_recorded','seowon_export:'||target_batch,
    jsonb_build_object('shipments',jsonb_array_length(target_labels),'suffixed',(select count(*) from jsonb_array_elements(target_labels) label where label->>'suffix'<>'')));
  return total;
end $$

do $patch$
declare definition text; anchor text;
begin
 definition:=pg_get_functiondef('public.admin_shipment_export(uuid[])'::regprocedure);
 anchor:=$old$ return result;
end$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'shipment_export_numbers_anchor_changed'; end if;
 execute replace(definition,anchor,$new$ return jsonb_set(result,'{shipments}',coalesce((select jsonb_agg(entry.value||jsonb_build_object(
  'shipmentNumber',s.shipment_number,'orderNumber',o.order_number) order by entry.ordinality)
  from jsonb_array_elements(result->'shipments') with ordinality entry(value,ordinality)
  join public.order_shipments s on s.id=(entry.value->>'id')::uuid join public.orders o on o.id=s.order_id),'[]'::jsonb));
end$new$);

 definition:=pg_get_functiondef('public.admin_origin_tracking_candidates(uuid,text[],text[])'::regprocedure);
 anchor:=$old$select s.id,s.order_id,s.status,s.carrier,s.tracking_number,s.shipped_at,a.address$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'tracking_candidates_select_anchor_changed'; end if;
 definition:=replace(definition,anchor,$new$select s.id,s.shipment_number,s.order_id,s.status,s.carrier,s.tracking_number,s.shipped_at,a.address$new$);
 anchor:=$old$jsonb_build_object('id',c.id,'orderId',c.order_id,'status',c.status,$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'tracking_candidates_projection_anchor_changed'; end if;
 execute replace(definition,anchor,$new$jsonb_build_object('id',c.id,'shipmentNumber',c.shipment_number,
   'seowonLabel',(select jsonb_build_object('batch',l.export_batch,'suffix',l.recipient_suffix) from private.seowon_export_labels l where l.shipment_id=c.id),
   'pack',(select jsonb_build_object('id',pack.summary->>'id','shipmentIds',pack.summary->'shipmentIds')
     from (select private.shipment_pack_summary(c.id) summary) pack where pack.summary is not null),
   'orderId',c.order_id,'status',c.status,$new$);
end $patch$

do $$declare signature text;fn regprocedure;contract record;registered boolean;begin
 foreach signature in array ARRAY[
  'public.admin_shipment_export(uuid[])',
  'public.admin_origin_tracking_candidates(uuid,text[],text[])'
 ] loop
  fn:=signature::regprocedure;registered:=false;
  select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure=fn;
  if found then perform private.register_operator_rpc_contract(fn,contract.capability,contract.guard_kind,contract.legacy_admin_only);registered:=true; end if;
  if exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure=fn) then
   perform private.register_operator_internal_contract(fn);registered:=true;
  end if;
  if not registered then raise exception 'operational_rpc_contract_missing: %',signature; end if;
 end loop;
end $$

do $patch$
declare definition text; anchor text;
begin
 -- 입금 제안: 코드가 입금 대기 주문 한 건에만 맞을 때만 코드로 제안한다. 둘 이상이면 금액·이름 제안도 하지 않는다.
 -- 전환 직후 구간의 주문은 옛 코드(grace_code)도 코드 일치로 본다.
 definition:=pg_get_functiondef('private.suggest_bank_deposit_order(text,bigint)'::regprocedure);
 anchor:=$old$private.bank_transfer_deposit_code(orders.id) as code,$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'deposit_suggest_code_column_anchor_changed'; end if;
 definition:=replace(definition,anchor,anchor||$new$
      private.bank_transfer_switch_grace_code(orders.id) as grace_code,$new$);
 anchor:=$old$where position(candidate.code in normalized.name) > 0$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'deposit_suggest_match_anchor_changed'; end if;
 definition:=replace(definition,anchor,$new$where (position(candidate.code in normalized.name) > 0
      or (candidate.grace_code is not null and position(candidate.grace_code in normalized.name) > 0))$new$);
 anchor:=$old$  by_code as ($old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'deposit_suggest_code_anchor_changed'; end if;
 definition:=replace(definition,anchor,$new$  by_code_all as ($new$);
 anchor:=$old$  by_amount as ($old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'deposit_suggest_amount_anchor_changed'; end if;
 definition:=replace(definition,anchor,$new$  by_code as (
    select * from by_code_all where (select count(distinct by_code_all.id) from by_code_all) = 1
  ),
  by_amount as ($new$);
 anchor:=$old$where not exists (select 1 from by_code)$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'deposit_suggest_fallback_anchor_changed'; end if;
 execute replace(definition,anchor,$new$where not exists (select 1 from by_code_all)$new$);

 -- 미입금 검색: 주문번호 부분 일치는 8자리 이상 숫자만. 6자리 입금코드는 코드 정확 일치로만 찾는다.
 definition:=pg_get_functiondef('private.admin_unpaid_bank_transfer_orders_console_before_numbers(text,integer,integer,text,text)'::regprocedure);
 anchor:=$old$position(v_query in numbered.order_number)>0$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'unpaid_console_number_anchor_changed'; end if;
 definition:=replace(definition,anchor,$new$v_query ~ '^[0-9]{8,16}$' and position(v_query in numbered.order_number)>0$new$);
 anchor:=$old$or candidate.code = upper(v_query)$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'unpaid_console_code_anchor_changed'; end if;
 execute replace(definition,anchor,$new$or candidate.code = upper(v_query)
      or private.bank_transfer_switch_grace_code(candidate.id) = upper(v_query)$new$);

 definition:=pg_get_functiondef('public.admin_unpaid_bank_transfer_orders(text,integer,integer)'::regprocedure);
 anchor:=$old$or candidate.code = upper(v_query)$old$;
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'unpaid_code_anchor_changed'; end if;
 execute replace(definition,anchor,$new$or candidate.code = upper(v_query)
      or private.bank_transfer_switch_grace_code(candidate.id) = upper(v_query)$new$);
end $patch$

