create function private.coupon_line_eligible_now(p_terms jsonb,p_good text,p_ip text) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare scope text:=p_terms->>'goodsScope'; categories uuid[]; category_match boolean;
begin
  if p_terms is null or p_good is null or jsonb_typeof(p_terms)<>'object' then return null; end if;
  if scope='all' then return true; end if;
  if scope='selected_goods' then
    return coalesce(p_good in (select jsonb_array_elements_text(coalesce(p_terms->'targetGoodIds','[]'::jsonb))),false)
      or coalesce(private.goods_aggregation_owner(p_good) in (select jsonb_array_elements_text(coalesce(p_terms->'targetGoodIds','[]'::jsonb))),false);
  end if;
  if scope='selected_ips' then
    return p_ip is not null and coalesce(p_ip in (select jsonb_array_elements_text(coalesce(p_terms->'targetIpIds','[]'::jsonb))),false);
  end if;
  if scope is distinct from 'selected_categories' then return null; end if;
  categories:=array(select value::uuid from jsonb_array_elements_text(coalesce(p_terms->'targetCategoryIds','[]'::jsonb)) value);
  -- private.coupon_good_matches의 카테고리 분기와 같은 판정이다(읽기 전용이라 체크아웃 잠금은 잡지 않는다).
  with recursive assigned as (
    select g.category_id as id from public.goods g where g.id=p_good and g.category_id is not null
    union select a.category_id from public.goods_additional_categories a where a.good_id=p_good
  ), ancestors(start_id,id,parent_id,active,matched,visited) as (
    select c.id,c.id,c.parent_id,c.archived_at is null,c.id=any(categories),array[c.id]
      from public.catalog_categories c join assigned a on a.id=c.id
    union all select a.start_id,c.id,c.parent_id,a.active and c.archived_at is null,a.matched or c.id=any(categories),a.visited||c.id
      from public.catalog_categories c join ancestors a on a.parent_id=c.id
      where cardinality(a.visited)<4 and not c.id=any(a.visited)
  ) select exists(select 1 from ancestors where parent_id is null and active and matched) into category_match;
  return category_match;
end $$

-- 거래확정 엑셀 수집: 품목에 당시 IP와 쿠폰 대상 판정을 싣는다(이전 수집본은 이 두 값이 없어도 그대로 읽는다).
do $patch$
declare target text; definition text;
  anchor constant text:=$old$'id',item.id,'goodId',item.good_id,$old$;
  replacement constant text:=$new$'id',item.id,'goodId',item.good_id,'ipId',item.good_ip_id_snapshot,
    'couponEligible',private.coupon_line_eligible_now((select r.terms_snapshot from public.coupon_redemptions r
      where r.order_id=o.id and r.status='applied' and r.benefit_kind='goods' and o.calculation_version=1 order by r.application_index limit 1),
      item.good_id,item.good_ip_id_snapshot),$new$;
begin
  foreach target in array ARRAY['private.collect_settled_export(date,date,text)','private.collect_settled_export_for_date(date,date,text,text)',
    'private.collect_settled_export_for_search(date,date,text,text,text)'] loop
    definition:=pg_get_functiondef(target::regprocedure);
    if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 or position('from selected o' in definition)=0 then
      raise exception 'settled_export_item_anchor_changed: %',target;
    end if;
    execute replace(definition,anchor,replacement);
    if exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure=target::regprocedure) then
      perform private.register_operator_internal_contract(target::regprocedure);
    end if;
  end loop;
end $patch$

-- The IP argument is separate so the four-argument contract keeps its meaning.
-- An unpatched four-argument caller treats an IP coupon conservatively (no match).
create function private.coupon_good_matches(p_scope text,p_goods text[],p_categories uuid[],p_ips text[],p_good text) returns boolean
language plpgsql volatile set search_path='' as $$
begin
 if p_scope='selected_ips' then
  return exists(select 1 from public.goods g where g.id=p_good and g.ip_id=any(coalesce(p_ips,'{}')));
 end if;
 return private.coupon_good_matches(p_scope,p_goods,p_categories,p_good);
end $$

create function public.admin_coupon_target_ips(target_coupon public.coupons) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 if not public.has_operator_capability('marketing.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',selected.id,'title',coalesce(ip.title,'정보 미확인'),'blocked',ip.id is null or ip.archived_at is not null) order by coalesce(ip.title,selected.id),selected.id),'[]') into result
 from public.coupons source cross join lateral unnest(source.target_ip_ids) selected(id)
 left join public.ips ip on ip.id=selected.id where source.code=target_coupon.code;
 return result;
end $$

create function public.admin_search_coupon_ips(p_query text default '',p_page integer default 1) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;needle text:=btrim(coalesce(p_query,''));
begin
 if not public.has_operator_capability('marketing.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_query is null or length(p_query)>100 or p_page is null or p_page not between 1 and 100000 then raise invalid_parameter_value using message='invalid_coupon_ip_search';end if;
 with filtered as materialized(select ip.id,ip.title,false as blocked from public.ips ip
   where ip.archived_at is null and (needle='' or strpos(lower(ip.title),lower(needle))>0 or strpos(ip.id,lower(needle))>0)),
 rows as(select * from filtered order by title,id limit 20 offset(p_page-1)*20)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(rows) order by title,id) from rows),'[]'),'total',(select count(*) from filtered),'page',p_page,'pageSize',20) into result;
 return result;
end $$

CREATE OR REPLACE FUNCTION public.admin_upsert_coupon_targeted(target_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); previous public.coupons; saved public.coupons;
  normalized_code text:=upper(btrim(target_payload->>'target_code')); previous_code text:=nullif(upper(btrim(target_payload->>'target_previous_code')),'');
  segment text:=target_payload->>'target_recipient_segment'; scope text:=target_payload->>'target_goods_scope'; good_ids text[]; category_ids uuid[]; ip_ids text[]; issue_mode text;
  next_status text:=coalesce(target_payload->>'target_status','active');
begin
  perform private.require_operator_capability('marketing.manage',false);

 perform private.assert_active_user(actor);
 if not public.has_operator_capability('marketing.manage',false) or private.is_account_write_fenced(actor) then raise insufficient_privilege using message='staff_required'; end if;
 if jsonb_typeof(target_payload) is distinct from 'object' or exists(select 1 from jsonb_object_keys(target_payload) k
    where k not in ('target_code','target_name','target_discount_type','target_discount_value','target_max_discount_amount','target_min_subtotal','target_starts_at','target_ends_at','target_issue_limit','target_status','target_grade_benefit','target_previous_code','target_recipient_segment','target_goods_scope','target_good_ids','target_expected_revision','target_category_ids','target_issuance_mode','target_ip_ids'))
    or segment is null or segment not in ('all','first_purchase','repeat_purchase') or scope is null or scope not in ('all','selected_goods','selected_categories','selected_ips')
    or next_status not in ('active','archived')
    or jsonb_typeof(target_payload->'target_good_ids') is distinct from 'array' or jsonb_array_length(target_payload->'target_good_ids')>1000
    or exists(select 1 from jsonb_array_elements(target_payload->'target_good_ids') e where jsonb_typeof(e)<>'string' or length(e#>>'{}') not between 1 and 200)
    then raise invalid_parameter_value using message='invalid_coupon_targeting'; end if;
 select coalesce(array_agg(distinct btrim(value) order by btrim(value)),'{}') into good_ids from jsonb_array_elements_text(target_payload->'target_good_ids');
 if scope<>'selected_goods' and cardinality(good_ids)>0 then raise invalid_parameter_value using message='invalid_coupon_targeting'; end if;
 if scope='selected_goods' and next_status='active' and cardinality(good_ids)=0 then raise check_violation using message='coupon_goods_scope_ready'; end if;
 if previous_code is not null and previous_code is distinct from normalized_code then raise invalid_parameter_value using message='catalog_id_immutable'; end if;
 -- Per-code lock covers a new definition before its row exists and prevents a
 -- concurrent creator from being converted into an update.
 perform pg_advisory_xact_lock(hashtextextended('coupon_admin:'||normalized_code,0));
 select * into previous from public.coupons where code=normalized_code for update;
 if previous_code is null and found then raise unique_violation using message='catalog_id_taken'; end if;
 if previous_code is not null then
   if previous.code is null then raise no_data_found using message='catalog_record_missing'; end if;
   if (target_payload->>'target_expected_revision')::integer is distinct from previous.terms_revision then raise exception using errcode='PT409',message='coupon_terms_changed'; end if;
 end if;
 issue_mode:=coalesce(target_payload->>'target_issuance_mode',previous.issuance_mode,'code');
 if issue_mode not in ('code','targeted') or (target_payload?'target_issuance_mode' and jsonb_typeof(target_payload->'target_issuance_mode') is distinct from 'string') then raise invalid_parameter_value using message='invalid_coupon_targeting';end if;
 if target_payload?'target_category_ids' then
  if jsonb_typeof(target_payload->'target_category_ids') is distinct from 'array' or jsonb_array_length(target_payload->'target_category_ids')>100
   or exists(select 1 from jsonb_array_elements(target_payload->'target_category_ids') e where jsonb_typeof(e)<>'string' or e#>>'{}' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') then raise invalid_parameter_value using message='invalid_coupon_category_targeting';end if;
  select coalesce(array_agg(distinct value::uuid order by value::uuid),'{}') into category_ids from jsonb_array_elements_text(target_payload->'target_category_ids');
 else category_ids:=case when scope='selected_categories' then coalesce(previous.target_category_ids,'{}') else '{}' end;end if;
 if (scope<>'selected_categories' and cardinality(category_ids)>0) or (scope='selected_categories' and next_status='active' and cardinality(category_ids)=0) then raise check_violation using message='coupon_category_scope_ready';end if;
 if target_payload?'target_ip_ids' then
  if jsonb_typeof(target_payload->'target_ip_ids') is distinct from 'array' or jsonb_array_length(target_payload->'target_ip_ids')>100
   or exists(select 1 from jsonb_array_elements(target_payload->'target_ip_ids') e where jsonb_typeof(e)<>'string' or e#>>'{}' !~ '^[a-z0-9][a-z0-9-]{0,99}$') then raise invalid_parameter_value using message='invalid_coupon_ip_targeting';end if;
  select coalesce(array_agg(distinct value order by value),'{}') into ip_ids from jsonb_array_elements_text(target_payload->'target_ip_ids');
 else ip_ids:=case when scope='selected_ips' then coalesce(previous.target_ip_ids,'{}') else '{}' end;end if;
 if (scope<>'selected_ips' and cardinality(ip_ids)>0) or (scope='selected_ips' and next_status='active' and cardinality(ip_ids)=0) then raise check_violation using message='coupon_ip_scope_ready';end if;
 -- An archived IP may stay on an existing definition (its goods are not sold), but cannot be newly targeted.
 if exists(select 1 from unnest(ip_ids) selected(id) left join public.ips ip on ip.id=selected.id
   where ip.id is null or ip.archived_at is not null and not selected.id=any(coalesce(previous.target_ip_ids,'{}'))) then raise check_violation using message='coupon_target_ip_unavailable';end if;
 if issue_mode='targeted' and nullif(target_payload->>'target_grade_benefit','') is not null then raise check_violation using message='coupon_targeted_grade_exclusive';end if;
 if cardinality(category_ids)>0 then
  if not pg_try_advisory_xact_lock_shared(hashtextextended('catalog_category_tree',0)) then raise exception using errcode='PT409',message='coupon_category_changed';end if;
  if exists(select 1 from unnest(category_ids) selected(id) left join private.coupon_category_catalog() c on c.id=selected.id
   where c.id is null or c.blocked and not selected.id=any(coalesce(previous.target_category_ids,'{}'))) then raise check_violation using message='coupon_target_category_unavailable';end if;
 end if;
 if exists(select 1 from unnest(good_ids) target(id) where not exists(select 1 from public.goods g where g.id=target.id and (g.archived_at is null or target.id=any(previous.target_good_ids))))
   then raise check_violation using message='coupon_target_good_unavailable'; end if;
 -- Install validated targeting, issuance mode and status together before the
 -- legacy definition writer. A single transaction preserves grade/status checks
 -- during mode changes and never exposes partially updated terms.
 if previous.code is not null then
   update public.coupons set status=next_status,recipient_segment=segment,goods_scope=scope,target_good_ids=good_ids,target_category_ids=category_ids,target_ip_ids=ip_ids,issuance_mode=issue_mode,grade_benefit=case when issue_mode='targeted' then null else grade_benefit end where code=normalized_code;
 end if;
 perform public.admin_upsert_coupon(
   normalized_code,target_payload->>'target_name',target_payload->>'target_discount_type',(target_payload->>'target_discount_value')::integer,
   (target_payload->>'target_max_discount_amount')::integer,(target_payload->>'target_min_subtotal')::integer,
   (target_payload->>'target_starts_at')::timestamptz,(target_payload->>'target_ends_at')::timestamptz,
   (target_payload->>'target_issue_limit')::integer,next_status,(target_payload->>'target_grade_benefit')::public.loyalty_grade,previous_code);
 update public.coupons set recipient_segment=segment,goods_scope=scope,target_good_ids=good_ids,target_category_ids=category_ids,target_ip_ids=ip_ids,issuance_mode=issue_mode where code=normalized_code returning * into saved;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'commerce.coupon.targeting_updated','coupons:'||normalized_code,
   jsonb_build_object('before',case when previous.code is null then null else jsonb_build_object('recipientSegment',previous.recipient_segment,'goodsScope',previous.goods_scope,'targetGoodIds',previous.target_good_ids,'targetCategoryIds',previous.target_category_ids,'targetIpIds',previous.target_ip_ids,'issuanceMode',previous.issuance_mode,'revision',previous.terms_revision) end,
     'after',jsonb_build_object('recipientSegment',saved.recipient_segment,'goodsScope',saved.goods_scope,'targetGoodIds',saved.target_good_ids,'targetCategoryIds',saved.target_category_ids,'targetIpIds',saved.target_ip_ids,'issuanceMode',saved.issuance_mode,'revision',saved.terms_revision)));
 return jsonb_build_object('code',saved.code,'revision',saved.terms_revision);
end $function$

-- Exact substring patches: each replacement must match exactly the expected
-- number of times, so a concurrent redefinition that changes the coupon call
-- fails here instead of silently dropping IP eligibility.
do $patch$
declare source text;
 procedure_name regprocedure;
 old_text text;new_text text;expected integer;found_count integer;
 patches jsonb:=jsonb_build_array(
  jsonb_build_array('private.touch_coupon_terms_revision()',$o$new.target_category_ids,new.issuance_mode)$o$,$n$new.target_category_ids,new.issuance_mode,new.target_ip_ids)$n$,1),
  jsonb_build_array('private.touch_coupon_terms_revision()',$o$old.target_category_ids,old.issuance_mode)$o$,$n$old.target_category_ids,old.issuance_mode,old.target_ip_ids)$n$,1),
  jsonb_build_array('private.evaluate_coupon_target_lines_at(uuid,uuid,jsonb,uuid,timestamp with time zone)',
   $o$private.coupon_good_matches(coupon.goods_scope,coupon.target_good_ids,coupon.target_category_ids,line.good_id)$o$,
   $n$private.coupon_good_matches(coupon.goods_scope,coupon.target_good_ids,coupon.target_category_ids,coupon.target_ip_ids,line.good_id)$n$,1),
  jsonb_build_array('private.evaluate_coupon_target_lines_at(uuid,uuid,jsonb,uuid,timestamp with time zone)',
   $o$||case when coupon.issuance_mode='targeted' then$o$,
   $n$||case when coupon.goods_scope='selected_ips' then jsonb_build_object('targetIpIds',coupon.target_ip_ids) else '{}'::jsonb end
  ||case when coupon.issuance_mode='targeted' then$n$,1),
  jsonb_build_array('private.calculate_goods_transaction_combined_locked(uuid,jsonb,jsonb,jsonb,uuid[],bigint,timestamp with time zone,jsonb,uuid)',
   $o$private.coupon_good_matches(definition.goods_scope,definition.target_good_ids,definition.target_category_ids,$o$,
   $n$private.coupon_good_matches(definition.goods_scope,definition.target_good_ids,definition.target_category_ids,definition.target_ip_ids,$n$,2),
  jsonb_build_array('private.calculate_goods_transaction_locked(uuid,jsonb,jsonb,jsonb,uuid,bigint,timestamp with time zone,jsonb,uuid)',
   $o$array(select jsonb_array_elements_text(coalesce(coupon_data#>'{termsSnapshot,targetCategoryIds}','[]'))::uuid),value->>'goodId')$o$,
   $n$array(select jsonb_array_elements_text(coalesce(coupon_data#>'{termsSnapshot,targetCategoryIds}','[]'))::uuid),
    array(select jsonb_array_elements_text(coalesce(coupon_data#>'{termsSnapshot,targetIpIds}','[]'))),value->>'goodId')$n$,1));
 patch jsonb;
begin
 for patch in select value from jsonb_array_elements(patches) loop
  procedure_name:=to_regprocedure(patch->>0);
  if procedure_name is null then raise exception 'coupon IP dependency missing: %',patch->>0;end if;
  old_text:=patch->>1;new_text:=patch->>2;expected:=(patch->>3)::integer;
  select pg_get_functiondef(procedure_name) into source;
  found_count:=(length(source)-length(replace(source,old_text,'')))/length(old_text);
  if found_count<>expected then raise exception 'coupon IP dependency changed: % (% of % matches)',patch->>0,found_count,expected;end if;
  execute replace(source,old_text,new_text);
 end loop;
end $patch$

-- Discounted price without raising: null when the result would not be a valid
-- discount (below 1 won or not lower than the regular price).
create function private.goods_bulk_discount_price(p_price integer,p_values jsonb) returns integer
language plpgsql immutable set search_path='' as $$
declare result numeric;amount numeric:=(p_values->>'value')::numeric;
begin
 result:=case p_values->>'mode' when 'amount' then p_price-amount when 'rate' then floor(p_price*(100-amount)/100) end;
 if result is null or result<1 or result>=p_price then return null;end if;
 return result::integer;
end $$

CREATE OR REPLACE FUNCTION public.admin_preview_goods_bulk(p_id uuid,p_request jsonb,p_actor uuid,p_session uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare prior private.goods_bulk_operations;ids text[];groups jsonb:='[]';rows jsonb:='[]';guards jsonb:='{}';g public.goods;
 next_price integer;min_price integer;max_price integer;next_min integer;next_max integer;expires timestamptz;result jsonb;
 command text:=p_request->>'command';kind text:=p_request->>'kind';target_limit integer;skip text;applied integer:=0;
 window_range tstzrange;discounts jsonb;
begin
 perform private.require_goods_group_identity(p_actor,p_session);
 perform private.goods_bulk_validate(p_request);
 if p_id is null then raise invalid_parameter_value using message='goods_bulk_invalid';end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-bulk:'||p_id::text,0));
 select * into prior from private.goods_bulk_operations where id=p_id;
 if found then
  if prior.actor_id<>p_actor or prior.session_id<>p_session or prior.request<>p_request then raise sqlstate 'PT409' using message='goods_bulk_operation_conflict';end if;
  if prior.receipt is not null or prior.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='goods_bulk_preview_expired';end if;
  return prior.preview;
 end if;
 -- Group membership is stable while expanding the exact selected group set.
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 target_limit:=case when kind='ip' then 1000 else 100 end;
 if kind='groups' then
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'revision',revision) order by id),'[]') into groups
   from private.goods_groups where id in(select value::uuid from jsonb_array_elements_text(p_request->'ids')) and archived_at is null;
  if jsonb_array_length(groups)<>jsonb_array_length(p_request->'ids') then raise check_violation using message='goods_bulk_group_unavailable';end if;
  select array_agg(distinct good_id order by good_id) into ids from private.goods_group_members
   where group_id in(select value::uuid from jsonb_array_elements_text(p_request->'ids'));
 elsif kind='ip' then
  -- The IP filter result: every non-archived good of that IP at preview time.
  if not exists(select 1 from public.ips where id=p_request->'ids'->>0 and archived_at is null) then raise check_violation using message='goods_bulk_ip_unavailable';end if;
  select array_agg(id order by id) into ids from public.goods where ip_id=p_request->'ids'->>0 and archived_at is null;
 else select array_agg(value order by value) into ids from jsonb_array_elements_text(p_request->'ids');end if;
 if coalesce(cardinality(ids),0) not between 1 and target_limit then raise check_violation using message='goods_bulk_target_limit';end if;
 if (select count(*) from public.goods where id=any(ids))<>cardinality(ids) then raise check_violation using message='goods_bulk_good_unavailable';end if;
 if command='discount' then window_range:=tstzrange((p_request#>>'{values,startsAt}')::timestamptz,(p_request#>>'{values,endsAt}')::timestamptz,'[)');end if;
 -- One statement owns both the summary and fingerprint to avoid torn previews.
 for g in select * from public.goods where id=any(ids) order by id for share nowait loop
  perform 1 from public.goods_variants where good_id=g.id order by id for share nowait;
  if g.archived_at is not null and command not in ('restore','archive','dissolve') then raise check_violation using message='good_archived';end if;
  next_price:=case when command='price' then private.goods_bulk_price(g.price,p_request->'values') else g.price end;
  select min(price),max(price) into min_price,max_price from public.goods_variants where good_id=g.id and archived_at is null;
  next_min:=min_price;next_max:=max_price;skip:=null;discounts:=null;
  if command='price' then
   -- Same predicate as private.guard_goods_variant_period_price (every option, current or upcoming).
   if exists(select 1 from private.goods_variant_price_periods p where p.good_id=g.id and p.state='active' and p.ends_at>statement_timestamp()) then
    raise check_violation using message='active_price_period_requires_reset';end if;
   if g.compare_at_price is not null and g.compare_at_price<=next_price then raise check_violation using message='goods_compare_at_price_invalid';end if;
   if exists(select 1 from public.goods_variants where good_id=g.id and (price<g.price or price::bigint-g.price+next_price>2147483647)) then
    raise check_violation using message='goods_bulk_price_invalid';end if;
   next_min:=min_price-g.price+next_price;next_max:=max_price-g.price+next_price;
  elsif command='discount' then
   -- A good is skipped (not the whole batch) when it cannot take this discount.
   if min_price is null then skip:='price_period_variant_inactive';
   elsif exists(select 1 from public.goods_variants v join private.goods_variant_price_periods p on p.variant_id=v.id and p.good_id=v.good_id
     where v.good_id=g.id and v.archived_at is null and p.state='active' and tstzrange(p.starts_at,p.ends_at,'[)') && window_range) then skip:='price_period_overlap';
   elsif exists(select 1 from public.goods_variants v where v.good_id=g.id and v.archived_at is null and private.goods_bulk_discount_price(v.price,p_request->'values') is null) then skip:='goods_bulk_price_invalid';
   else next_min:=private.goods_bulk_price(min_price,p_request->'values');next_max:=private.goods_bulk_price(max_price,p_request->'values');end if;
  elsif command='discount_stop' then
   select case when count(*)=0 then null else jsonb_build_object('count',count(*),'minPrice',min(p.discount_price),'maxPrice',max(p.discount_price),
     'startsAt',min(p.starts_at),'endsAt',max(p.ends_at)) end into discounts
    from private.goods_variant_price_periods p where p.good_id=g.id and p.state='active' and p.ends_at>statement_timestamp();
   if discounts is null then skip:='no_active_discount';end if;
  end if;
  if skip is null then applied:=applied+1;end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('id',g.id,'name',g.name,'code',g.code,'price',g.price,'nextPrice',next_price,
   'priceMin',min_price,'priceMax',max_price,'nextMin',next_min,'nextMax',next_max,'published',g.published_at is not null,
   'archived',g.archived_at is not null,'stopped',g.stock='soldout','skip',skip,'discounts',discounts));
  guards:=guards||jsonb_build_object(g.id,case when command in ('discount','discount_stop') then private.goods_bulk_price_fingerprint(g.id) else private.goods_bulk_fingerprint(g.id) end);
 end loop;
 if applied=0 then raise check_violation using message=case when command='discount_stop' then 'goods_bulk_no_active_discount' else 'goods_bulk_all_skipped' end;end if;
 expires:=clock_timestamp()+interval '15 minutes';
 result:=jsonb_build_object('state','ready','operationId',p_id,'request',p_request,'groups',groups,'goods',rows,'expiresAt',expires);
 insert into private.goods_bulk_operations(id,actor_id,session_id,request,guards,preview,expires_at) values(p_id,p_actor,p_session,p_request,guards,result,expires);
 return result;
end $$

CREATE OR REPLACE FUNCTION public.admin_commit_goods_bulk(p_id uuid,p_actor uuid,p_session uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare operation private.goods_bulk_operations;ids text[];lock_ids text[];id_value text;group_value jsonb;g public.goods;v public.goods_variants;
 p private.goods_variant_price_periods;command text;values_doc jsonb;payload jsonb;result jsonb;failure text;options jsonb;baseline jsonb;
 skipped_ids text[];skipped jsonb;
begin
 perform private.require_goods_group_identity(p_actor,p_session);
 perform pg_advisory_xact_lock(hashtextextended('goods-bulk:'||p_id::text,0));
 select * into operation from private.goods_bulk_operations where id=p_id for update;
 if not found or operation.actor_id<>p_actor or operation.session_id<>p_session then raise insufficient_privilege using message='goods_bulk_operation_unavailable';end if;
 if operation.receipt is not null then return operation.receipt;end if;
 command:=operation.request->>'command';values_doc:=operation.request->'values';
 select array_agg(key order by key) into ids from jsonb_object_keys(operation.guards) key;
 -- Skips were frozen in the reviewed preview; a preview stored before this
 -- change has no skip key and therefore applies to every good as before.
 select coalesce(array_agg(r->>'id' order by r->>'id'),'{}'),
  coalesce(jsonb_agg(jsonb_build_object('id',r->>'id','name',r->>'name','code',r->'code','reason',r->>'skip') order by r->>'id'),'[]')
  into skipped_ids,skipped from jsonb_array_elements(operation.preview->'goods') r where nullif(r->>'skip','') is not null;
 begin
  perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
  perform private.lock_catalog_category_tree();
  for group_value in select value from jsonb_array_elements(operation.preview->'groups') loop
   perform 1 from private.goods_groups where id=(group_value->>'id')::uuid and revision=(group_value->>'revision')::bigint and archived_at is null for update nowait;
   if not found then raise sqlstate 'PT409' using message='goods_bulk_changed';end if;
  end loop;
  select array_agg(distinct id order by id) into lock_ids from (select unnest(ids) id union select private.goods_aggregation_owner(unnest(ids))) members;
  foreach id_value in array lock_ids loop
   if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||id_value,0)) then raise sqlstate 'PT409' using message='goods_bulk_busy';end if;
  end loop;
  perform 1 from public.goods where id=any(lock_ids) order by id for update nowait;
  perform 1 from public.goods_variants where good_id=any(ids) order by id for update nowait;
  perform 1 from private.goods_variant_price_periods where good_id=any(ids) order by id for update nowait;
  perform 1 from public.ips where id in(select ip_id from public.goods where id=any(ids)) order by id for update nowait;
  -- Recheck expiration after lock acquisition, and reject the entire batch if
  -- an option, stock, discount, membership or catalog value changed meanwhile.
  -- Discount commands guard prices, options and periods but not stock.
  if operation.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='goods_bulk_preview_expired';end if;
  -- A discount preview stored before this migration carries a full fingerprint
  -- and is rejected here as changed, which only asks the operator to re-review.
  if exists(select 1 from unnest(ids) id where (case when command in ('discount','discount_stop')
     then private.goods_bulk_price_fingerprint(id) else private.goods_bulk_fingerprint(id) end) is distinct from operation.guards->>id) then
   raise sqlstate 'PT409' using message='goods_bulk_changed';end if;
  if command='dissolve' then
   for group_value in select value from jsonb_array_elements(operation.preview->'groups') loop
    perform public.admin_archive_goods_group((group_value->>'id')::uuid,(group_value->>'revision')::bigint,
     md5('goods-bulk-group:'||p_id::text||':'||(group_value->>'id'))::uuid,p_actor,p_session);
   end loop;
  else
   for g in select * from public.goods where id=any(ids) and not id=any(skipped_ids) order by id loop
    if command='publish' then perform public.admin_set_good_published(g.id,true);
    elsif command='unpublish' then perform public.admin_set_good_published(g.id,false);
    elsif command='archive' then perform public.admin_archive_good(g.id);
    elsif command='restore' then perform public.admin_unarchive_good(g.id);
    elsif command in ('discount','discount_stop') then
     if command='discount' then
      for v in select * from public.goods_variants where good_id=g.id and archived_at is null order by id loop
       perform public.admin_save_goods_price_period(g.id,v.id,null,jsonb_build_object('state','active',
        'discountPrice',private.goods_bulk_price(v.price,values_doc),'startsAt',values_doc->'startsAt','endsAt',values_doc->'endsAt'),null);
      end loop;
     else
      for p in select * from private.goods_variant_price_periods where good_id=g.id and state='active' order by id loop
       perform public.admin_save_goods_price_period(g.id,p.variant_id,p.id,jsonb_build_object('state','disabled',
        'discountPrice',p.discount_price,'startsAt',p.starts_at,'endsAt',p.ends_at),p.revision);
      end loop;
     end if;
    else
     payload:=to_jsonb(g)||jsonb_build_object('previous_id',g.id,'publish',null,'custom_inputs_expected_revision',g.custom_inputs_revision);
     if command='start' then payload:=payload||'{"stock":"ok"}'::jsonb;
     elsif command='stop' then payload:=payload||'{"stock":"soldout"}'::jsonb;
     elsif command='period' then payload:=payload||jsonb_build_object('sale_period',values_doc||jsonb_build_object('expectedRevision',g.sale_period_revision));
     elsif command='price' then
      select jsonb_agg(jsonb_build_object('id',id,'name',name,'attributes',attributes,'code',code,'extraPrice',price-g.price,
       'stockQty',stock_qty,'expectedStockQty',stock_qty,'isActive',archived_at is null,'lowStockThreshold',low_stock_threshold)
       order by is_default desc,sort_order,id) into options from public.goods_variants where good_id=g.id;
      select coalesce(jsonb_agg(id::text order by id),'[]') into baseline from public.goods_variants where good_id=g.id and archived_at is null;
      payload:=payload||jsonb_build_object('price',private.goods_bulk_price(g.price,values_doc),'variants',options,'variant_baseline',baseline);
     end if;
     perform public.admin_save_good(payload);
    end if;
   end loop;
  end if;
  result:=jsonb_build_object('state','completed','operationId',p_id,'goodsCount',cardinality(ids)-cardinality(skipped_ids),'groupsCount',jsonb_array_length(operation.preview->'groups'),'error',null)
   ||case when command in ('discount','discount_stop') then jsonb_build_object('skipped',skipped) else '{}'::jsonb end;
  insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'catalog.goods_bulk.completed','goods_bulk:'||p_id::text,
   jsonb_build_object('request',operation.request,'preview',operation.preview,'receipt',result));
 exception when others then
  -- The subtransaction rolls back every product and child-operation change.
  -- Persist a terminal rejection so an uncertain network reply cannot replay it.
  get stacked diagnostics failure=message_text;
  result:=jsonb_build_object('state','rejected','operationId',p_id,'goodsCount',0,'groupsCount',0,
   'error',case when failure ~ '^[a-z][a-z0-9_]{0,100}$' then failure else 'goods_bulk_rejected' end);
 end;
 update private.goods_bulk_operations set receipt=result where id=p_id;
 return result;
end $$

create function public.admin_goods_list_price_states(p_good_ids text[]) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 if not public.has_operator_capability('catalog.read',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_good_ids is null or cardinality(p_good_ids)>100 or array_position(p_good_ids,null) is not null then
  raise invalid_parameter_value using message='invalid_goods_list_price_states';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'price',g.price,'compareAtPrice',g.compare_at_price,
   -- Same predicate as private.guard_goods_variant_period_price.
   'activeDiscountEndsAt',(select max(p.ends_at) from private.goods_variant_price_periods p
     where p.good_id=g.id and p.state='active' and p.ends_at>statement_timestamp())) order by g.id),'[]') into result
 from public.goods g where g.id=any(p_good_ids);
 return result;
end $$

-- ── 2. 쓰기 공통: 인증 · 봉인 · 회원 단위 잠금 ─────────────────────────
-- p_new_write: 추가·수정·기본 지정이면 true(온보딩·정지 확인), 삭제면 false(자기 개인정보 삭제는 막지 않는다).
create function private.address_book_actor(p_new_write boolean)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor uuid := (select auth.uid());
  actor_profile public.profiles;
begin
  if actor is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;
  -- 계정 행동 잠금을 먼저 잡는다(위 잠금 순서). 봉인된 계정은 여기서 끝난다.
  if private.is_account_write_fenced(actor) then
    raise object_not_in_prerequisite_state using message = 'account_deletion_write_fenced';
  end if;
  if p_new_write is distinct from false then
    select * into actor_profile from public.profiles where id = actor;
    if not found then
      raise exception 'auth_required' using errcode = '28000';
    end if;
    if actor_profile.suspended_at is not null then
      raise insufficient_privilege using message = 'account_suspended';
    end if;
    -- 개인정보처리방침에 동의하고 온보딩을 마친 회원만 연락처·주소를 저장한다(subscription_lock_actor 관례).
    if actor_profile.onboarded_at is null
      or actor_profile.consents->>'terms' is distinct from 'true'
      or actor_profile.consents->>'privacy' is distinct from 'true' then
      raise insufficient_privilege using message = 'onboarding_required';
    end if;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('address-book:' || actor::text, 0)
  );
  return actor;
end;
$$

-- ── 3. 저장(추가·수정) ────────────────────────────────────────────────
-- p_entry_id 가 null 이면 추가, 있으면 내 주소 수정. p_address 는 주문 배송지 JSON 과 같은 키
-- (recipientName·phone·postalCode·address1·address2)만 받는다 — 배송 메모는 주문마다 다르므로 담지 않는다.
-- 첫 주소는 언제나 기본 배송지가 된다. 기본 배송지를 수정하면서 기본을 끄는 일은 없다(다른 주소를 기본으로
-- 지정하면 넘어간다) — 그래야 주소가 있는 동안 기본 배송지가 늘 1개다.
create function public.save_my_address_book_entry(
  p_entry_id uuid,
  p_label text,
  p_address jsonb,
  p_make_default boolean
)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor uuid;
  clean_label text := btrim(coalesce(p_label, ''));
  normalized jsonb;
  target public.address_book_entries;
  entry_count integer;
  becomes_default boolean;
  saved_id uuid;
begin
  actor := private.address_book_actor(true);

  if char_length(clean_label) not between 1 and 20 or clean_label ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message = 'address_book_invalid';
  end if;
  if p_address is null or jsonb_typeof(p_address) <> 'object' or p_address ? 'deliveryNote' then
    raise invalid_parameter_value using message = 'address_book_invalid';
  end if;
  begin
    normalized := private.normalize_order_address_change(p_address);
  exception when invalid_parameter_value then
    raise invalid_parameter_value using message = 'address_book_invalid';
  end;

  if p_entry_id is null then
    select count(*) into entry_count
    from public.address_book_entries
    where user_id = actor;

    if entry_count >= 10 then
      raise check_violation using message = 'address_book_full';
    end if;

    becomes_default := coalesce(p_make_default, false) or entry_count = 0;
    if becomes_default then
      -- 기본 해제는 회원의 수정이 아니다 — updated_at 을 그대로 둔다.
      update public.address_book_entries
      set is_default = false
      where user_id = actor and is_default;
    end if;

    insert into public.address_book_entries (
      user_id, label, recipient_name, phone, postal_code, address1, address2, is_default
    )
    values (
      actor,
      clean_label,
      normalized->>'recipientName',
      normalized->>'phone',
      normalized->>'postalCode',
      normalized->>'address1',
      nullif(normalized->>'address2', ''),
      becomes_default
    )
    returning id into saved_id;

    return saved_id;
  end if;

  select * into target
  from public.address_book_entries
  where id = p_entry_id and user_id = actor
  for update;

  if not found then
    raise no_data_found using message = 'address_book_entry_missing';
  end if;

  becomes_default := target.is_default or coalesce(p_make_default, false);
  if becomes_default and not target.is_default then
    update public.address_book_entries
    set is_default = false
    where user_id = actor and is_default;
  end if;

  update public.address_book_entries
  set label = clean_label,
      recipient_name = normalized->>'recipientName',
      phone = normalized->>'phone',
      postal_code = normalized->>'postalCode',
      address1 = normalized->>'address1',
      address2 = nullif(normalized->>'address2', ''),
      is_default = becomes_default,
      updated_at = clock_timestamp()
  where id = target.id;

  return target.id;
end;
$$

-- ── 4. 기본 배송지 지정 ───────────────────────────────────────────────
-- 한 트랜잭션·회원 단위 잠금 안에서 내리고 올린다 — 동시에 서로 다른 주소를 지정해도 끝나면 1개다.
-- 지정·해제는 회원이 배송지 내용을 고친 것이 아니라 updated_at 을 바꾸지 않는다(기본 승계 순서가 흔들리지 않게).
create function public.set_my_default_address_book_entry(p_entry_id uuid)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor uuid;
begin
  actor := private.address_book_actor(true);

  if p_entry_id is null or not exists (
    select 1 from public.address_book_entries where id = p_entry_id and user_id = actor
  ) then
    raise no_data_found using message = 'address_book_entry_missing';
  end if;

  update public.address_book_entries
  set is_default = false
  where user_id = actor and is_default and id <> p_entry_id;

  update public.address_book_entries
  set is_default = true
  where id = p_entry_id and user_id = actor and not is_default;
end;
$$

-- ── 6. 탈퇴 시 삭제 ───────────────────────────────────────────────────
-- 회원 한 명의 주소록 전부를 지운다. 계정 행동 잠금 → 주소록 잠금 순서로 잡아(같은 트랜잭션이면 재진입) 진행 중인
-- 저장이 끝나기를 기다린 뒤 지우므로, 삭제 직전에 시작한 저장이 삭제 뒤에 남지 않는다. 지운 개수를 돌려준다.
-- 주문에 저장된 배송지·선물 수령인 주소는 이 범위가 아니다.
--   · 탈퇴 신청(봉인): 아래 트리거가 봉인 행이 생기는 트랜잭션 안에서 부른다.
--   · 탈퇴 신청 기능이 꺼져 있는 동안 문의로 받은 탈퇴: 운영자가 계정을 정지한 뒤(새 저장이 막힌다) SQL 편집기에서
--     `select private.erase_member_address_book('<회원 id>');`로 부른다. API 롤에는 열지 않는다.
create function private.erase_member_address_book(p_user_id uuid)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  erased integer;
begin
  if p_user_id is null then
    raise invalid_parameter_value using message = 'address_book_member_required';
  end if;
  perform private.lock_account_action_subject(p_user_id);
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('address-book:' || p_user_id::text, 0)
  );
  delete from public.address_book_entries where user_id = p_user_id;
  get diagnostics erased = row_count;
  return erased;
end;
$$

create trigger erase_fenced_address_book
after insert on private.account_action_fences
for each row execute function private.erase_fenced_address_book()

-- L8b (#574, CL-09·CH-10): collection banners and operator-edited suggested
-- search terms as two more home_curations kinds. Both follow the L8a notice
-- precedent (20261023030000): the storefront reads them with a cookie-free
-- cached anon query, the admin curation editor saves them through the same
-- audited operator RPCs, and saving expires the same cache tag.
--
-- * collection_banner: the banner that heads a collection page. slot names the
--   page: 'all' (goods shop, a manual slider), 'best' or 'new'. PC artwork is
--   image_path; payload may carry mobile_image_path, a one-line subtitle
--   (1..80), image_alt (1..100, the image's own meaning — the visible copy is a
--   text layer, not baked into the artwork) and the hero style keys
--   image_dim/text_color. title is the visible headline (1..40). Optional
--   internal link. Category display pages carry no banner.
-- * search_terms: one row is a whole chip list. payload.terms is 1..10 unique
--   (case-insensitive) terms of 1..20 characters, stored trimmed with inner
--   whitespace collapsed so the chip label equals the search query. title is
--   the list's admin name (1..40). No image, no link: each chip links to
--   /search?q=<term>. Several rows may be scheduled; the storefront shows the
--   most recently started list that is live now.

create function private.is_valid_home_collection_banner(candidate_title text, candidate jsonb)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
declare
  field text;
  value text;
begin
  if candidate_title is null
    or candidate_title <> pg_catalog.btrim(candidate_title)
    or pg_catalog.char_length(candidate_title) not between 1 and 40
    or candidate_title ~ '[[:cntrl:]]'
  then
    return false;
  end if;
  if candidate is null then return true; end if;
  if pg_catalog.jsonb_typeof(candidate) <> 'object' then return false; end if;
  if exists (
    select 1 from pg_catalog.jsonb_object_keys(candidate) as keys(key)
    where key not in ('subtitle', 'mobile_image_path', 'image_alt', 'image_dim', 'text_color')
  ) then
    return false;
  end if;
  foreach field in array array['subtitle', 'image_alt'] loop
    if not candidate ? field then continue; end if;
    if pg_catalog.jsonb_typeof(candidate -> field) <> 'string' then return false; end if;
    value := candidate ->> field;
    if value <> pg_catalog.btrim(value)
      or pg_catalog.char_length(value) not between 1 and (case field when 'subtitle' then 80 else 100 end)
      or value ~ '[[:cntrl:]]'
    then
      return false;
    end if;
  end loop;
  if candidate ? 'mobile_image_path' and (
    pg_catalog.jsonb_typeof(candidate -> 'mobile_image_path') <> 'string'
    or candidate ->> 'mobile_image_path'
      !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  ) then
    return false;
  end if;
  return private.is_valid_home_hero_style(candidate);
end $$

create function private.is_valid_home_search_terms(candidate_title text, candidate jsonb)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
begin
  if candidate_title is null
    or candidate_title <> pg_catalog.btrim(candidate_title)
    or pg_catalog.char_length(candidate_title) not between 1 and 40
    or candidate_title ~ '[[:cntrl:]]'
  then
    return false;
  end if;
  -- plpgsql keeps the evaluation order explicit: the array functions below
  -- would raise on a scalar instead of rejecting it.
  if candidate is null or pg_catalog.jsonb_typeof(candidate) <> 'object' then return false; end if;
  if exists (
    select 1 from pg_catalog.jsonb_object_keys(candidate) as keys(key) where key <> 'terms'
  ) then
    return false;
  end if;
  if pg_catalog.jsonb_typeof(candidate -> 'terms') is distinct from 'array' then return false; end if;
  if pg_catalog.jsonb_array_length(candidate -> 'terms') not between 1 and 10 then return false; end if;
  if exists (
    select 1 from pg_catalog.jsonb_array_elements(candidate -> 'terms') as entries(entry)
    where pg_catalog.jsonb_typeof(entry) <> 'string'
      or entry #>> '{}' <> pg_catalog.btrim(entry #>> '{}')
      or pg_catalog.char_length(entry #>> '{}') not between 1 and 20
      or entry #>> '{}' ~ '[[:cntrl:]]'
      or entry #>> '{}' ~ '[[:space:]][[:space:]]'
  ) then
    return false;
  end if;
  return (
    select pg_catalog.count(distinct pg_catalog.lower(entry))
    from pg_catalog.jsonb_array_elements_text(candidate -> 'terms') as entries(entry)
  ) = pg_catalog.jsonb_array_length(candidate -> 'terms');
end $$

-- Shared write core: collection_banner/search_terms kinds, slot, payload
-- whitelist and normalization. Everything else is unchanged from
-- 20261023030000_home_notice_bar.sql.
create or replace function private.save_home_curation(target_operation_id uuid, target_curation_id uuid, target_kind text, target_ip_id text, target_title text, target_image_path text, target_link_path text, target_display_order integer, target_active_from timestamp with time zone, target_active_to timestamp with time zone, target_enabled boolean, target_slot text, target_payload jsonb, target_expected_updated_at timestamp with time zone, require_saved_version boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  -- Alias with a column-safe name: inside the claim UPDATE below, a bare
  -- actor_id would be ambiguous against admin_artwork_upload_claims.actor_id.
  claim_owner_id uuid := actor_id;
  normalized_kind text := pg_catalog.btrim(target_kind);
  normalized_ip_id text := nullif(pg_catalog.btrim(target_ip_id), '');
  normalized_title text := pg_catalog.btrim(target_title);
  normalized_image_path text := nullif(pg_catalog.btrim(target_image_path), '');
  normalized_link_path text := nullif(pg_catalog.btrim(target_link_path),'');
  normalized_slot text := nullif(pg_catalog.btrim(target_slot), '');
  normalized_payload jsonb := case
    when target_payload is null or target_payload = '{}'::jsonb then null
    else target_payload
  end;
  allowed_payload_keys text[];
  payload_key text;
  payload_text_value text;
  payload_good_ids jsonb;
  payload_good_id_limit integer;
  payload_good_id text;
  payload_mobile_image_path text;
  previous_mobile_image_path text;
  referenced_archived_at timestamptz;
  request_payload jsonb;
  previous_payload jsonb := 'null'::jsonb;
  after_payload jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  previous_curation public.home_curations%rowtype;
  curation_exists boolean := false;
begin
  perform private.require_operator_capability('store.manage',false);

  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  perform 1 from public.profiles where id=actor_id and role in ('staff','admin') and suspended_at is null for share;
  if not found then
    raise insufficient_privilege using message = 'forbidden';
  end if;

  if target_operation_id is null then
    raise null_value_not_allowed using message = 'invalid_operation_id';
  end if;
  if target_curation_id is null then
    raise null_value_not_allowed using message = 'invalid_curation_id';
  end if;
  if normalized_kind is null
    or normalized_kind not in (
      'hero', 'featured_ip', 'announcement',
      'notice_strip', 'notice_bar', 'editor_pick', 'band_banner', 'best_tab', 'benefit', 'sales_best', 'review_best', 'product_mosaic', 'product_collection',
      'collection_banner', 'search_terms'
    )
  then
    raise invalid_parameter_value using message = 'invalid_curation_kind';
  end if;
  if normalized_title is null
    or pg_catalog.char_length(normalized_title) not between (case when normalized_kind='hero' then 0 else 1 end) and 120
    or (normalized_kind in ('sales_best','review_best','product_mosaic','product_collection') and pg_catalog.char_length(normalized_title)>15)
    -- The text notice bar is one short line of copy in the global shell.
    or (normalized_kind='notice_bar' and (pg_catalog.char_length(normalized_title)>60 or normalized_title ~ '[[:cntrl:]]'))
    -- Collection banner copy and the search-term list name are one short line.
    or (normalized_kind in ('collection_banner','search_terms') and (pg_catalog.char_length(normalized_title)>40 or normalized_title ~ '[[:cntrl:]]'))
  then
    raise invalid_parameter_value using message = 'invalid_curation_title';
  end if;
  if normalized_kind = 'featured_ip' and normalized_ip_id is null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind <> 'featured_ip' and normalized_ip_id is not null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind in ('hero', 'notice_strip', 'editor_pick', 'band_banner', 'collection_banner')
    and normalized_image_path is null
  then
    raise check_violation using message = 'curation_image_required';
  end if;
  if normalized_kind = 'notice_bar' and normalized_image_path is not null then
    raise invalid_parameter_value using message = 'invalid_curation_notice';
  end if;
  -- Suggested search terms are text chips only.
  if normalized_kind = 'search_terms' and normalized_image_path is not null then
    raise invalid_parameter_value using message = 'invalid_curation_search_terms';
  end if;
  if normalized_image_path is not null
    and normalized_image_path !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  then
    raise check_violation using message = 'invalid_curation_image_path';
  end if;
  if (normalized_link_path is null and normalized_kind not in ('hero','product_collection','notice_bar','collection_banner','search_terms'))
    or (normalized_kind in ('product_collection','search_terms') and normalized_link_path is not null)
    or (normalized_link_path is not null and not private.is_safe_home_curation_link(normalized_link_path))
  then
    raise invalid_parameter_value using message = 'invalid_curation_link_path';
  end if;
  if target_display_order is null or target_display_order < 0 then
    raise invalid_parameter_value using message = 'invalid_curation_display_order';
  end if;
  if target_active_from is null then
    raise null_value_not_allowed using message = 'invalid_curation_active_from';
  end if;
  if not pg_catalog.isfinite(target_active_from) then
    raise invalid_parameter_value using message = 'invalid_curation_active_from';
  end if;
  if target_active_to is not null
    and (
      not pg_catalog.isfinite(target_active_to)
      or target_active_to <= target_active_from
    )
  then
    raise check_violation using message = 'invalid_curation_active_window';
  end if;
  if target_enabled is null then
    raise null_value_not_allowed using message = 'invalid_curation_enabled';
  end if;

  if normalized_kind = 'best_tab' then
    if normalized_slot is null or normalized_slot not in ('category', 'popular') then
      raise invalid_parameter_value using message = 'invalid_curation_slot';
    end if;
  -- A collection banner names the collection page it heads: the whole goods
  -- shop slider, BEST or NEW. Category display pages carry no banner.
  elsif normalized_kind = 'collection_banner' then
    if normalized_slot is null or normalized_slot not in ('all', 'best', 'new') then
      raise invalid_parameter_value using message = 'invalid_curation_slot';
    end if;
  elsif normalized_slot is not null then
    raise invalid_parameter_value using message = 'invalid_curation_slot';
  end if;

  -- Per-kind payload whitelist. Unknown keys are rejected outright so typos
  -- never ship silently dead configuration.
  allowed_payload_keys := case normalized_kind
    when 'hero' then array['subtitle', 'mobile_image_path', 'alt_enabled', 'alt_title', 'alt_content', 'image_dim', 'text_color']
    when 'notice_strip' then array['mobile_image_path', 'page_types']
    when 'notice_bar' then array['cta_label', 'page_types']
    when 'editor_pick' then array['badge', 'description']
    when 'band_banner' then array['subcopy', 'good_ids']
    when 'best_tab' then array['good_ids', 'selection_mode', 'item_count']
    when 'benefit' then array['description']
    when 'sales_best' then array['exposure_mode','period']
    when 'review_best' then array['selection_mode','good_ids']
    when 'product_mosaic' then array['mosaic_title','mosaic_subtitle','slots']
    when 'product_collection' then array['layout','image_shape','item_count','good_ids']
    when 'collection_banner' then array['subtitle', 'mobile_image_path', 'image_alt', 'image_dim', 'text_color']
    when 'search_terms' then array['terms']
    else array[]::text[]
  end;

  if normalized_payload is not null then
    if pg_catalog.jsonb_typeof(normalized_payload) <> 'object' then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    if pg_catalog.cardinality(allowed_payload_keys) = 0 then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    for payload_key in
      select key from pg_catalog.jsonb_object_keys(normalized_payload) as keys(key)
    loop
      if not payload_key = any (allowed_payload_keys) then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
    end loop;

    for payload_key in
      select unnest from pg_catalog.unnest(array['subtitle', 'badge', 'description', 'subcopy'])
    loop
      if normalized_payload ? payload_key then
        if pg_catalog.jsonb_typeof(normalized_payload -> payload_key) <> 'string' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        payload_text_value := pg_catalog.btrim(normalized_payload ->> payload_key);
        if pg_catalog.char_length(payload_text_value) not between 1 and 200
          or (payload_key = 'badge' and pg_catalog.char_length(payload_text_value) > 20)
        then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        normalized_payload := pg_catalog.jsonb_set(
          normalized_payload, array[payload_key], pg_catalog.to_jsonb(payload_text_value)
        );
      end if;
    end loop;

    if normalized_payload ? 'good_ids' then
      payload_good_ids := normalized_payload -> 'good_ids';
      payload_good_id_limit := case normalized_kind when 'best_tab' then 12 when 'review_best' then 20 when 'product_collection' then 100 else 4 end;
      if pg_catalog.jsonb_typeof(payload_good_ids) <> 'array'
        or pg_catalog.jsonb_array_length(payload_good_ids) not between (case when normalized_kind in ('review_best','product_collection') then 0 else 1 end) and payload_good_id_limit
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      for payload_good_id in
        select value from pg_catalog.jsonb_array_elements_text(payload_good_ids) as elements(value)
      loop
        if payload_good_id !~ '^[A-Za-z0-9_-]{1,64}$' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
      end loop;
    end if;

    -- Automatic selection is a rule, never a saved snapshot of product IDs.
    if normalized_kind='best_tab' and normalized_payload ? 'selection_mode' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'selection_mode') <> 'string'
        or normalized_payload ->> 'selection_mode' <> 'latest'
        or normalized_payload ? 'good_ids'
        or not normalized_payload ? 'item_count'
        or pg_catalog.jsonb_typeof(normalized_payload -> 'item_count') <> 'number'
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      if (normalized_payload ->> 'item_count')::numeric not between 3 and 10
        or pg_catalog.trunc((normalized_payload ->> 'item_count')::numeric)
          <> (normalized_payload ->> 'item_count')::numeric
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['item_count'],
        pg_catalog.to_jsonb(((normalized_payload ->> 'item_count')::numeric)::integer)
      );
    elsif normalized_kind='best_tab' and normalized_payload ? 'item_count' then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;

    if normalized_payload ? 'mobile_image_path' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'mobile_image_path') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      payload_mobile_image_path := normalized_payload ->> 'mobile_image_path';
      if payload_mobile_image_path
        !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
      then
        raise check_violation using message = 'invalid_curation_image_path';
      end if;
    end if;

    if normalized_payload ? 'cta_label' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'cta_label') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_notice';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['cta_label'],
        pg_catalog.to_jsonb(pg_catalog.btrim(normalized_payload ->> 'cta_label'))
      );
    end if;

    if normalized_payload ? 'image_alt' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'image_alt') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_collection_banner';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['image_alt'],
        pg_catalog.to_jsonb(pg_catalog.btrim(normalized_payload ->> 'image_alt'))
      );
    end if;

    -- Each suggested term is stored exactly as the chip label and search query:
    -- trimmed with inner whitespace collapsed (lib/search.ts normalizeSearchQuery).
    if normalized_payload ? 'terms' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'terms') <> 'array' then
        raise invalid_parameter_value using message = 'invalid_curation_search_terms';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['terms'],
        coalesce((
          select pg_catalog.jsonb_agg(
            case when pg_catalog.jsonb_typeof(term.value) = 'string'
              then pg_catalog.to_jsonb(pg_catalog.btrim(pg_catalog.regexp_replace(term.value #>> '{}', '[[:space:]]+', ' ', 'g')))
              else term.value
            end
            order by term.ordinality
          )
          from pg_catalog.jsonb_array_elements(normalized_payload -> 'terms') with ordinality as term(value, ordinality)
        ), '[]'::jsonb)
      );
    end if;

    -- Page-type targeting is stored in one canonical order so an identical
    -- operator request replays byte-for-byte (operation receipt comparison).
    if normalized_payload ? 'page_types' then
      if not private.is_valid_home_notice_page_types(normalized_payload -> 'page_types') then
        raise invalid_parameter_value using message = 'invalid_curation_notice';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['page_types'],
        (
          select pg_catalog.jsonb_agg(page_type order by pg_catalog.array_position(
            array['home', 'collection', 'product', 'content', 'other']::text[], page_type
          ))
          from pg_catalog.jsonb_array_elements_text(normalized_payload -> 'page_types') as page_types(page_type)
        )
      );
    end if;
  end if;

  if not private.is_valid_home_ranked_curation(normalized_kind, normalized_payload) then
    raise invalid_parameter_value using message='invalid_curation_payload';
  end if;

  if not private.is_valid_home_notice_payload(normalized_kind, normalized_payload, normalized_link_path) then
    raise invalid_parameter_value using message='invalid_curation_notice';
  end if;

  if normalized_kind='product_mosaic' and (not private.is_valid_home_mosaic(normalized_payload) or normalized_image_path is not null) then
    raise invalid_parameter_value using message='invalid_curation_mosaic';
  end if;

  if normalized_kind='hero' and not private.is_valid_home_hero_style(normalized_payload) then
    raise invalid_parameter_value using message='invalid_hero_style';
  end if;

  if normalized_kind='collection_banner' and (
    not private.is_valid_home_hero_style(normalized_payload)
    or not private.is_valid_home_collection_banner(normalized_title, normalized_payload)
  ) then
    raise invalid_parameter_value using message='invalid_curation_collection_banner';
  end if;

  if normalized_kind='search_terms' and not private.is_valid_home_search_terms(normalized_title, normalized_payload) then
    raise invalid_parameter_value using message='invalid_curation_search_terms';
  end if;

  if normalized_kind='hero' and not private.is_valid_home_hero_alt(normalized_payload) then
    raise invalid_parameter_value using message='invalid_hero_alt';
  end if;

  if normalized_kind='product_collection' and (not private.is_valid_home_product_collection(normalized_payload)
    or normalized_image_path is not null or normalized_title~'[[:cntrl:]]') then
    raise invalid_parameter_value using message='invalid_curation_product_collection';
  end if;

  request_payload := pg_catalog.jsonb_build_object(
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  if require_saved_version then
    request_payload := request_payload || pg_catalog.jsonb_build_object('expected_updated_at',target_expected_updated_at);
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.home_curation.upserted'
      and existing_target = 'home_curations:' || target_curation_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_curation_id;
    end if;

    raise unique_violation using message = 'operation_conflict';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation:' || target_curation_id::text,
      0
    )
  );

  if normalized_ip_id is not null then
    select ip.archived_at
      into referenced_archived_at
    from public.ips as ip
    where ip.id = normalized_ip_id
    for update of ip;

    if not found then
      raise no_data_found using message = 'curation_ip_not_found';
    end if;
    if referenced_archived_at is not null then
      raise check_violation using message = 'catalog_item_archived';
    end if;
  end if;

  select curation.*
    into previous_curation
  from public.home_curations as curation
  where curation.id = target_curation_id
  for update of curation;
  curation_exists := found;
  if curation_exists and previous_curation.archived_at is not null then
    raise sqlstate 'PT409' using message='curation_archived';
  end if;

  if require_saved_version and ((curation_exists and previous_curation.updated_at is distinct from target_expected_updated_at)
    or (not curation_exists and target_expected_updated_at is not null)) then
    raise sqlstate 'PT409' using message='curation_conflict';
  end if;

  if curation_exists then
    previous_payload := pg_catalog.jsonb_build_object(
      'id', previous_curation.id,
      'kind', previous_curation.kind,
      'ip_id', previous_curation.ip_id,
      'title', previous_curation.title,
      'image_path', previous_curation.image_path,
      'link_path', previous_curation.link_path,
      'display_order', previous_curation.display_order,
      'active_from', previous_curation.active_from,
      'active_to', previous_curation.active_to,
      'enabled', previous_curation.enabled,
      'slot', previous_curation.slot,
      'payload', previous_curation.payload
    );
    previous_mobile_image_path := previous_curation.payload ->> 'mobile_image_path';
  end if;

  -- The artwork-claim trigger only guards the image_path column, so the
  -- mobile artwork carried inside payload consumes its verified upload claim
  -- here, under the same actor/kind/single-use rules (#112 contract).
  if payload_mobile_image_path is not null
    and payload_mobile_image_path is distinct from previous_mobile_image_path
  then
    update public.admin_artwork_upload_claims as claim
    set
      status = 'attached',
      attached_at = pg_catalog.clock_timestamp(),
      resolved_at = pg_catalog.clock_timestamp()
    where claim.actor_id = claim_owner_id
      and claim.path = pg_catalog.substr(
        payload_mobile_image_path,
        pg_catalog.length('public-media/') + 1
      )
      and claim.kind = 'curation'
      and claim.status = 'verified'
      and claim.verified_at is not null
      and claim.final_size is not null
      and claim.attached_at is null
      and claim.expires_at > pg_catalog.clock_timestamp();

    if not found then
      raise check_violation using message = 'unverified_artwork';
    end if;
  end if;

  if curation_exists then
    update public.home_curations
    set
      kind = normalized_kind,
      ip_id = normalized_ip_id,
      title = normalized_title,
      image_path = normalized_image_path,
      link_path = normalized_link_path,
      display_order = target_display_order,
      active_from = target_active_from,
      active_to = target_active_to,
      enabled = target_enabled,
      slot = normalized_slot,
      payload = normalized_payload
    where id = target_curation_id;
  else
    insert into public.home_curations (
      id, kind, ip_id, title, image_path, link_path,
      display_order, active_from, active_to, enabled, slot, payload
    )
    values (
      target_curation_id, normalized_kind, normalized_ip_id, normalized_title,
      normalized_image_path, normalized_link_path, target_display_order,
      target_active_from, target_active_to, target_enabled, normalized_slot,
      normalized_payload
    );
  end if;

  after_payload := pg_catalog.jsonb_build_object(
    'id', target_curation_id,
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.home_curation.upserted',
    'home_curations:' || target_curation_id::text,
    pg_catalog.jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_curation_id;
end;
$function$

-- Claim guard for the two banner columns. The shared artwork trigger only
-- watches image_path, and ips_update RLS lets a platform operator write the row
-- directly, so the claim rule lives on the table rather than only in the RPC.
-- A path that this row already carried (in either column) needs no new claim:
-- swapping or re-saving the same artwork never consumes another upload.
create function private.guard_ip_hall_banner_artwork()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_actor_id uuid := (select auth.uid());
  previous_paths text[] := '{}';
  banner_path text;
begin
  if tg_op = 'UPDATE' then
    previous_paths := pg_catalog.array_remove(
      array[old.hall_banner_image_path, old.hall_banner_mobile_image_path], null
    );
  end if;

  for banner_path in
    select distinct candidate
    from pg_catalog.unnest(array[new.hall_banner_image_path, new.hall_banner_mobile_image_path]) as paths(candidate)
    where candidate is not null
    order by candidate
  loop
    if banner_path = any(previous_paths) then continue; end if;

    if current_actor_id is null then
      -- Migrations and seeds run as postgres without a request actor.
      if session_user = 'postgres' then continue; end if;
      raise check_violation using message = 'unverified_artwork';
    end if;

    update public.admin_artwork_upload_claims as claim
    set
      status = 'attached',
      attached_at = pg_catalog.clock_timestamp(),
      resolved_at = pg_catalog.clock_timestamp()
    where claim.actor_id = current_actor_id
      and claim.path = pg_catalog.substr(banner_path, pg_catalog.length('public-media/') + 1)
      and claim.kind = 'ip'
      and claim.status = 'verified'
      and claim.verified_at is not null
      and claim.final_size is not null
      and claim.attached_at is null
      and claim.expires_at > pg_catalog.clock_timestamp();

    if not found then
      raise check_violation using message = 'unverified_artwork';
    end if;
  end loop;

  return new;
end $$

create trigger ips_hall_banner_artwork
  before insert or update of hall_banner_image_path, hall_banner_mobile_image_path on public.ips
  for each row execute function private.guard_ip_hall_banner_artwork()

-- Audited write for the admin IP form. admin_upsert_ip keeps its signature
-- (its save-intent contract is coupled to many smokes); the banner has its own
-- form and RPC under the same platform.manage authority.
create function public.admin_save_ip_hall_banner(
  target_ip_id text,
  target_image_path text,
  target_mobile_image_path text
)
returns timestamp with time zone
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_image_path text := nullif(pg_catalog.btrim(target_image_path), '');
  normalized_mobile_image_path text := nullif(pg_catalog.btrim(target_mobile_image_path), '');
  previous_ip public.ips%rowtype;
  saved_at timestamptz;
begin
  perform private.require_operator_capability('platform.manage', false);

  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;
  if target_ip_id is null or pg_catalog.btrim(target_ip_id) = '' then
    raise invalid_parameter_value using message = 'invalid_ip_id';
  end if;
  if (normalized_image_path is not null
      and normalized_image_path !~ '^public-media/catalog/ip/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$')
    or (normalized_mobile_image_path is not null
      and normalized_mobile_image_path !~ '^public-media/catalog/ip/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$')
  then
    raise check_violation using message = 'invalid_ip_banner_image_path';
  end if;

  select ip.* into previous_ip from public.ips as ip where ip.id = target_ip_id for update of ip;
  if not found then
    raise no_data_found using message = 'catalog_record_missing';
  end if;

  -- Saving the same pair again is a no-op: no new version, no audit noise.
  if previous_ip.hall_banner_image_path is not distinct from normalized_image_path
    and previous_ip.hall_banner_mobile_image_path is not distinct from normalized_mobile_image_path
  then
    return previous_ip.updated_at;
  end if;

  update public.ips
  set
    hall_banner_image_path = normalized_image_path,
    hall_banner_mobile_image_path = normalized_mobile_image_path
  where id = target_ip_id
  returning updated_at into saved_at;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'catalog.ip.hall_banner',
    'ips:' || target_ip_id,
    pg_catalog.jsonb_build_object(
      'before', pg_catalog.jsonb_build_object(
        'hall_banner_image_path', previous_ip.hall_banner_image_path,
        'hall_banner_mobile_image_path', previous_ip.hall_banner_mobile_image_path
      ),
      'after', pg_catalog.jsonb_build_object(
        'hall_banner_image_path', normalized_image_path,
        'hall_banner_mobile_image_path', normalized_mobile_image_path
      )
    )
  );

  return saved_at;
end $$

create trigger home_curations_collection_banner_limit
before insert or update on public.home_curations
for each row execute function private.guard_home_collection_banner_limit()

do $patch$
declare definition text; anchor text;
begin
  definition := pg_get_functiondef('private.validate_seller_claim_intake(jsonb,jsonb)'::regprocedure);
  anchor := $old$  if p_payload->>'claimType' = 'cancel' then
    if p_payload->'collectionAddress' is distinct from 'null'::jsonb$old$;
  if (length(definition) - length(replace(definition, anchor, ''))) / length(anchor) <> 1 then
    raise exception 'seller_cancel_reason_anchor_changed';
  end if;
  execute replace(definition, anchor, $new$  if p_payload->>'claimType' = 'cancel' then
    if p_payload->>'reasonType' <> 'change_of_mind' then
      raise invalid_parameter_value using message = 'invalid_seller_cancel_reason';
    end if;
    if p_payload->'collectionAddress' is distinct from 'null'::jsonb$new$);
end $patch$

-- 화면이 보낸 옵션 참조를 이 상품의 옵션 하나로 해석한다. 저장된 옵션은 id로 찾는다(보관된 옵션 포함 — 기존 독립 패널과
-- 같은 범위). 새 옵션은 저장 전 id가 없으므로 옵션값 조합으로 찾는다(한 제출 안에서 조합은 중복될 수 없다 —
-- private.save_goods_options). 활성 옵션을 먼저 보고, 없으면 이번 저장이 만든 옵션(p_new_variants)에서 찾는다:
-- 새 옵션을 '사용 중지'로 등록하면 save_goods_options가 저장과 함께 보관하지만 KC 모델 연결·예약 초안 대상이 될 수 있다.
-- 이전 저장에서 보관된 옵션은 조합으로 찾지 않는다(같은 조합의 낡은 옵션을 잘못 고르지 않게).
-- 실패 코드는 섹션(kc·preorder)을 담아 화면이 해당 카드에 안내한다.
create function private.resolve_goods_workspace_variant(p_good_id text,p_ref jsonb,p_new_variants uuid[],p_section text) returns uuid
language plpgsql stable security definer set search_path='' as $$
declare matched uuid[]; invalid text; unresolved text;
begin
  if p_section is null or p_section not in ('kc','preorder') then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  invalid:='invalid_goods_workspace_'||p_section||'_variant';
  unresolved:='goods_workspace_'||p_section||'_variant_unresolved';
  if jsonb_typeof(p_ref) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_ref))<>1 then
    raise check_violation using message=invalid;
  end if;
  if p_ref ? 'id' then
    if jsonb_typeof(p_ref->'id') is distinct from 'string'
      or p_ref->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise check_violation using message=invalid;
    end if;
    select array_agg(id) into matched from public.goods_variants where id=(p_ref->>'id')::uuid and good_id=p_good_id;
  elsif p_ref ? 'attributes' then
    if jsonb_typeof(p_ref->'attributes') is distinct from 'object' then
      raise check_violation using message=invalid;
    end if;
    select array_agg(id) into matched from public.goods_variants
      where good_id=p_good_id and archived_at is null and attributes=p_ref->'attributes';
    if coalesce(cardinality(matched),0)=0 then
      select array_agg(id) into matched from public.goods_variants
        where good_id=p_good_id and id=any(coalesce(p_new_variants,'{}')) and attributes=p_ref->'attributes';
    end if;
  else
    raise check_violation using message=invalid;
  end if;
  if coalesce(cardinality(matched),0)<>1 then raise check_violation using message=unresolved; end if;
  return matched[1];
end $$

create function public.admin_save_good_workspace(p_request jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid; operation uuid; good jsonb; draft jsonb; sections jsonb; kc jsonb; preorders jsonb;
  request_hash text; prior private.goods_workspace_operations; previous_id text; current_review private.goods_kc_reviews;
  saved jsonb; saved_id text; models jsonb:='[]'::jsonb; model jsonb; resolved jsonb; kc_revision integer; kc_saved jsonb;
  entry jsonb; variant uuid; policy jsonb; preorder_results jsonb:='[]'::jsonb; result jsonb;
  prior_variants uuid[]:='{}'; new_variants uuid[]:='{}';
  uuid_pattern constant text:='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
begin
  actor:=private.require_operator_capability('catalog.manage',false);
  if jsonb_typeof(p_request) is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(p_request) key where key not in ('operationId','good','draft','sections'))
    or jsonb_typeof(p_request->'operationId') is distinct from 'string' or p_request->>'operationId' !~ uuid_pattern
    or jsonb_typeof(p_request->'good') is distinct from 'object'
    or coalesce(jsonb_typeof(p_request->'draft'),'null') not in ('null','object')
    or coalesce(jsonb_typeof(p_request->'sections'),'null') not in ('null','object') then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  operation:=(p_request->>'operationId')::uuid;
  good:=p_request->'good';
  draft:=case when jsonb_typeof(p_request->'draft')='object' then p_request->'draft' end;
  sections:=case when jsonb_typeof(p_request->'sections')='object' then p_request->'sections' else '{}'::jsonb end;
  if exists(select 1 from jsonb_object_keys(sections) key where key not in ('kc','preorders')) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  if draft is not null and (exists(select 1 from jsonb_object_keys(draft) key where key not in ('id','revision'))
    or jsonb_typeof(draft->'id') is distinct from 'string' or draft->>'id' !~ uuid_pattern
    or jsonb_typeof(draft->'revision') is distinct from 'number' or draft->>'revision' !~ '^[1-9][0-9]*$'
    or (draft->>'revision')::numeric>2147483647) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  -- 공개는 기존 게시 상태 전환이 맡는다. 래퍼는 초안 저장만 한다.
  if coalesce(good->'publish','null'::jsonb) not in ('null'::jsonb,'false'::jsonb) then
    raise check_violation using message='goods_workspace_publish_unsupported';
  end if;
  kc:=case when jsonb_typeof(sections->'kc')='object' then sections->'kc' end;
  if sections ? 'kc' and coalesce(jsonb_typeof(sections->'kc'),'null') not in ('null','object') then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  if kc is not null and ((select array_agg(key order by key) from jsonb_object_keys(kc) key)
      is distinct from array['attested','expectedContextFingerprint','expectedRevision','models','status']
    or jsonb_typeof(kc->'models') is distinct from 'array' or jsonb_array_length(kc->'models')>50
    or jsonb_typeof(kc->'attested') is distinct from 'boolean'
    or jsonb_typeof(kc->'status') is distinct from 'string' or kc->>'status' not in ('unreviewed','reviewed')
    or jsonb_typeof(kc->'expectedRevision') not in ('null','number')
    or (jsonb_typeof(kc->'expectedRevision')='number' and (kc->>'expectedRevision' !~ '^[1-9][0-9]*$' or (kc->>'expectedRevision')::numeric>2147483647))
    or jsonb_typeof(kc->'expectedContextFingerprint') not in ('null','string')) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  preorders:=case when jsonb_typeof(sections->'preorders')='array' then sections->'preorders' end;
  if sections ? 'preorders' and coalesce(jsonb_typeof(sections->'preorders'),'null') not in ('null','array') then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  if preorders is not null and (jsonb_array_length(preorders)>100 or exists(select 1 from jsonb_array_elements(preorders) item
    where jsonb_typeof(item) is distinct from 'object'
      or (select array_agg(key order by key) from jsonb_object_keys(item) key) is distinct from array['expectedRevision','policyId','values','variant']
      or jsonb_typeof(item->'policyId') not in ('null','string') or (jsonb_typeof(item->'policyId')='string' and item->>'policyId' !~ uuid_pattern)
      or jsonb_typeof(item->'expectedRevision') not in ('null','number')
      or (jsonb_typeof(item->'expectedRevision')='number' and (item->>'expectedRevision' !~ '^[1-9][0-9]*$' or (item->>'expectedRevision')::numeric>2147483647))
      or jsonb_typeof(item->'values') is distinct from 'object')) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  previous_id:=nullif(good->>'previous_id','');

  -- 1. 작업 영수증. 같은 요청의 재시도는 저장 결과를 그대로 돌려준다.
  request_hash:=encode(extensions.digest(convert_to(p_request::text,'UTF8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('goods-workspace-operation:'||operation::text,0));
  select * into prior from private.goods_workspace_operations where operation_id=operation;
  if found then
    if prior.actor_id<>actor or prior.request_hash<>request_hash then
      raise sqlstate 'PT409' using message='goods_workspace_operation_conflict';
    end if;
    return prior.receipt||jsonb_build_object('replayed',true);
  end if;

  -- 2. 저장 전 CAS. admin_save_good(카테고리 트리 → 상품 행)·admin_save_goods_kc(상품 행 → KC 행)와 같은 잠금 순서다.
  perform private.lock_catalog_category_tree();
  if previous_id is not null then
    perform 1 from public.goods where id=previous_id for update;
    -- 저장 전 옵션. 저장 뒤 이 목록에 없는 옵션이 이번 저장이 만든 새 옵션이다(옵션 참조 해석).
    select coalesce(array_agg(id),'{}') into prior_variants from public.goods_variants where good_id=previous_id;
    if kc is not null then
      select * into current_review from private.goods_kc_reviews where good_id=previous_id for update;
      if current_review.revision is distinct from (kc->>'expectedRevision')::integer
        or kc->>'expectedContextFingerprint' is distinct from private.goods_kc_fingerprint(previous_id) then
        raise sqlstate 'PT409' using message='goods_kc_review_changed';
      end if;
    end if;
  elsif kc is not null and (kc->'expectedRevision'<>'null'::jsonb or kc->'expectedContextFingerprint'<>'null'::jsonb) then
    raise sqlstate 'PT409' using message='goods_kc_review_changed';
  end if;

  -- 3. 기본 상품·옵션 저장
  if draft is null then saved:=public.admin_save_good(good);
  else saved:=public.admin_save_good_from_draft(good,(draft->>'id')::uuid,(draft->>'revision')::integer);
  end if;
  saved_id:=saved->>'id';
  if coalesce(saved_id,'')='' then raise check_violation using message='goods_workspace_save_failed'; end if;

  if coalesce((saved->>'draftAlreadyCompleted')::boolean,false) then
    -- 이 임시저장은 다른 요청(다른 탭·다른 작업 ID)이 이미 상품으로 등록했다. 같은 작업의 재시도는 위 영수증이 돌려주므로,
    -- 여기 온 요청의 KC·예약판매 섹션은 그 등록에 들어간 적이 없다. 섹션이 있으면 저장되지 않은 입력을 성공으로
    -- 알리지 않도록 거절한다(화면 입력은 유지된다). 섹션이 없으면 등록된 상품을 돌려준다.
    if kc is not null or coalesce(jsonb_array_length(preorders),0)>0 then
      raise sqlstate 'PT409' using message='goods_workspace_draft_completed_sections_skipped';
    end if;
    result:=jsonb_build_object('id',saved_id,'operationId',operation,'created',false,'draftAlreadyCompleted',true,
      'good',saved,'kc',null,'preorders','[]'::jsonb);
  else
    select coalesce(array_agg(id),'{}') into new_variants from public.goods_variants
      where good_id=saved_id and not (id=any(prior_variants));
    -- 4·5. KC: 옵션 참조를 저장된 옵션 id로 바꾼 뒤 저장 후의 새 버전·맥락 지문으로 저장한다.
    if kc is not null then
      for model in select value from jsonb_array_elements(kc->'models') loop
        if jsonb_typeof(model) is distinct from 'object' or model ? 'variantIds'
          or jsonb_typeof(model->'variantRefs') is distinct from 'array' or jsonb_array_length(model->'variantRefs')>200 then
          raise check_violation using message='invalid_goods_kc_models';
        end if;
        select coalesce(jsonb_agg(id order by id),'[]'::jsonb) into resolved from (
          select distinct private.resolve_goods_workspace_variant(saved_id,ref,new_variants,'kc')::text id
          from jsonb_array_elements(model->'variantRefs') ref) refs;
        models:=models||jsonb_build_array((model-'variantRefs')||jsonb_build_object('variantIds',resolved));
      end loop;
      select revision into kc_revision from private.goods_kc_reviews where good_id=saved_id;
      kc_saved:=public.admin_save_goods_kc(saved_id,models,kc->>'status',kc_revision,
        private.goods_kc_fingerprint(saved_id),(kc->>'attested')::boolean);
    end if;
    -- 6. 예약판매: 옵션별 정책. 활성화 권한·조건은 admin_save_goods_preorder가 검사한다.
    if preorders is not null then
      for entry in select value from jsonb_array_elements(preorders) loop
        variant:=private.resolve_goods_workspace_variant(saved_id,entry->'variant',new_variants,'preorder');
        policy:=public.admin_save_goods_preorder(saved_id,variant,(entry->>'policyId')::uuid,entry->'values',
          (entry->>'expectedRevision')::integer);
        preorder_results:=preorder_results||jsonb_build_array(policy||jsonb_build_object('variantId',variant));
      end loop;
    end if;
    result:=jsonb_build_object('id',saved_id,'operationId',operation,'created',previous_id is null,'good',saved,
      'kc',case when kc_saved is null then null else jsonb_build_object('changed',kc_saved->'changed',
        'status',kc_saved#>'{configuration,status}','revision',kc_saved#>'{configuration,revision}') end,
      'preorders',preorder_results);
  end if;
  insert into private.goods_workspace_operations(operation_id,actor_id,request_hash,good_id,receipt)
    values(operation,actor,request_hash,saved_id,result);
  insert into public.audit_log(id,actor_id,action,target,diff) values(operation,actor,'admin.good.workspace_saved','goods:'||saved_id,
    jsonb_build_object('created',previous_id is null,'draft',draft is not null,'kc',kc is not null,
      'preorders',coalesce(jsonb_array_length(preorders),0),'draftAlreadyCompleted',coalesce((saved->>'draftAlreadyCompleted')::boolean,false)));
  return result;
end $$

-- `대>중>소` 원문 → 이름 배열. 각 이름은 ERP 원문과 같은 규칙(private.erp_item_text)으로 다듬는다.
-- 빈 이름이 하나라도 있으면 null(잘못된 경로). erp_item_text가 남기는 제로폭 공백(U+200B)만으로 된 이름도
-- 비교 키(catalog_category_name_key)가 비므로 빈 이름이다 — 남기면 '같은 부모·같은 이름' 판정이 늘 거짓이라
-- 보이지 않는 카테고리가 붙여넣을 때마다 쌓인다.
create function private.catalog_category_path_segments(p_path text)
returns text[]
language plpgsql
immutable
set search_path = ''
as $$
declare
  part text;
  result text[] := array[]::text[];
begin
  if p_path is null then return null; end if;
  foreach part in array pg_catalog.string_to_array(p_path, '>') loop
    part := private.erp_item_text(part, true);
    if part is null or private.catalog_category_name_key(part) is null then return null; end if;
    result := pg_catalog.array_append(result, part);
  end loop;
  return case when pg_catalog.cardinality(result) > 0 then result end;
end;
$$

-- 전체 경로가 같은 활성 말단 하나. 단계마다 같은 키의 활성 카테고리가 정확히 하나여야 하고, 끝이 말단이어야 한다.
create function private.catalog_category_path_target(p_path text)
returns uuid
language plpgsql
stable
set search_path = ''
as $$
declare
  segments text[] := private.catalog_category_path_segments(p_path);
  segment text;
  current_id uuid;
  matched uuid[];
begin
  if segments is null or pg_catalog.cardinality(segments) > 4 then return null; end if;
  foreach segment in array segments loop
    select pg_catalog.array_agg(category.id) into matched
    from public.catalog_categories as category
    where category.archived_at is null
      and case when current_id is null then category.parent_id is null else category.parent_id = current_id end
      and private.catalog_category_name_key(category.name) = private.catalog_category_name_key(segment);
    if coalesce(pg_catalog.cardinality(matched), 0) <> 1 then return null; end if;
    current_id := matched[1];
  end loop;
  if exists (
    select 1 from public.catalog_categories as child
    where child.parent_id = current_id and child.archived_at is null
  ) then return null; end if;
  return current_id;
end;
$$

create function public.admin_bulk_create_categories(p_operation_id uuid, p_paths jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor uuid := (select auth.uid());
  request jsonb;
  receipt jsonb;
  entry record;
  segments text[];
  segment text;
  path_keys text[];
  parent uuid;
  matched uuid[];
  new_id uuid;
  base_code text;
  new_code text;
  suffix integer;
  line_ids uuid[];
  created_ids uuid[] := array[]::uuid[];
  lines jsonb[] := array[]::jsonb[];
  reason text;
  created_lines integer := 0;
  skipped_lines integer := 0;
  failed_lines integer := 0;
begin
  perform private.require_operator_capability('catalog.manage', false);
  if actor is null or not public.has_operator_capability('catalog.manage', false) then
    raise insufficient_privilege using message = 'forbidden';
  end if;
  if p_operation_id is null or p_paths is null or pg_catalog.jsonb_typeof(p_paths) <> 'array'
     or pg_catalog.jsonb_array_length(p_paths) not between 1 and 1000
     or exists (
       select 1 from pg_catalog.jsonb_array_elements(p_paths) as item(value)
       where pg_catalog.jsonb_typeof(item.value) <> 'string' or pg_catalog.char_length(item.value #>> '{}') > 1000
     ) then
    raise invalid_parameter_value using message = 'invalid_category_paths';
  end if;

  request := pg_catalog.jsonb_build_object('paths', p_paths);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || p_operation_id::text, 0));
  receipt := private.operator_lifecycle_replay(actor, p_operation_id, 'admin.catalog.category.bulk_created', request);
  if receipt is not null then return receipt; end if;
  perform private.lock_catalog_category_tree();

  for entry in
    select item.value #>> '{}' as raw, item.ordinality::integer as line
    from pg_catalog.jsonb_array_elements(p_paths) with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    segments := private.catalog_category_path_segments(entry.raw);
    reason := null;
    line_ids := array[]::uuid[];
    if segments is null then
      reason := 'invalid_category_path';
    elsif pg_catalog.cardinality(segments) > 4 then
      reason := 'category_depth_exceeded';
    elsif exists (select 1 from pg_catalog.unnest(segments) as name where pg_catalog.char_length(name) > 120) then
      reason := 'invalid_category_name';
    end if;

    if reason is null then
      begin
        parent := null;
        path_keys := array[]::text[];
        foreach segment in array segments loop
          path_keys := pg_catalog.array_append(path_keys, private.catalog_category_name_key(segment));
          select pg_catalog.array_agg(category.id) into matched
          from public.catalog_categories as category
          where category.archived_at is null
            and case when parent is null then category.parent_id is null else category.parent_id = parent end
            and private.catalog_category_name_key(category.name) = private.catalog_category_name_key(segment);
          if pg_catalog.cardinality(matched) > 1 then
            raise check_violation using message = 'category_path_ambiguous';
          end if;
          if matched is not null then
            parent := matched[1];
            continue;
          end if;
          new_id := extensions.gen_random_uuid();
          base_code := 'c-' || pg_catalog.left(pg_catalog.md5(pg_catalog.array_to_string(path_keys, '>')), 10);
          new_code := base_code;
          suffix := 1;
          while exists (select 1 from public.catalog_categories as category where category.code = new_code) loop
            suffix := suffix + 1;
            new_code := base_code || '-' || suffix::text;
          end loop;
          insert into public.catalog_categories (id, code, name, parent_id, depth, sort_order)
          values (
            new_id, new_code, segment, parent, pg_catalog.cardinality(path_keys),
            coalesce((
              select pg_catalog.max(sibling.sort_order) + 1 from public.catalog_categories as sibling
              where case when parent is null then sibling.parent_id is null else sibling.parent_id = parent end
            ), 0)
          );
          line_ids := pg_catalog.array_append(line_ids, new_id);
          parent := new_id;
        end loop;
      exception when check_violation or foreign_key_violation or unique_violation or invalid_parameter_value then
        get stacked diagnostics reason = message_text;
        line_ids := array[]::uuid[];
      end;
    end if;

    if reason is not null then
      failed_lines := failed_lines + 1;
      lines := pg_catalog.array_append(lines, pg_catalog.jsonb_build_object(
        'line', entry.line, 'path', pg_catalog.left(entry.raw, 300), 'status', 'failed', 'created', 0, 'reason', reason));
    elsif pg_catalog.cardinality(line_ids) > 0 then
      created_lines := created_lines + 1;
      created_ids := created_ids || line_ids;
      lines := pg_catalog.array_append(lines, pg_catalog.jsonb_build_object(
        'line', entry.line, 'path', pg_catalog.array_to_string(segments, '>'), 'status', 'created',
        'created', pg_catalog.cardinality(line_ids), 'reason', null));
    else
      skipped_lines := skipped_lines + 1;
      lines := pg_catalog.array_append(lines, pg_catalog.jsonb_build_object(
        'line', entry.line, 'path', pg_catalog.array_to_string(segments, '>'), 'status', 'skipped', 'created', 0, 'reason', null));
    end if;
  end loop;

  receipt := pg_catalog.jsonb_build_object(
    'createdCategories', pg_catalog.cardinality(created_ids),
    'createdLines', created_lines,
    'skippedLines', skipped_lines,
    'failedLines', failed_lines,
    'lines', pg_catalog.to_jsonb(lines));
  insert into public.audit_log (id, actor_id, action, target, diff)
  values (p_operation_id, actor, 'admin.catalog.category.bulk_created', 'catalog_categories',
    pg_catalog.jsonb_build_object('request', request, 'result', receipt, 'created_ids', pg_catalog.to_jsonb(created_ids)));
  return receipt;
end;
$$

