CREATE OR REPLACE FUNCTION public.admin_list_goods_photos(p_query text DEFAULT ''::text, p_archived boolean DEFAULT false, p_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; total_count bigint; search_term text;
begin
  if not public.has_operator_capability('catalog.read',false) then raise insufficient_privilege using message='operator_capability_required'; end if;

  if auth.uid() is null or not public.has_operator_capability('catalog.read',false) then raise insufficient_privilege using message='forbidden'; end if;
  if p_page is null or p_page < 1 or p_page > 100000 or p_query is null or char_length(p_query)>100 or p_archived is null then raise invalid_parameter_value using message='invalid_photo_search'; end if;
  -- 이름과 검색어를 모두 NFC로 맞춘다. 저장 경로는 NFC로만 쓰지만, 비교도 정규화해 어느 쪽이 NFD여도 찾는다.
  search_term:=lower(normalize(btrim(p_query),NFC));
  select count(*) into total_count from public.goods_photo_library p where (p.archived_at is not null)=p_archived and strpos(lower(normalize(p.name,NFC)),search_term)>0;
  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'imagePath',p.image_path,'revision',p.revision,'archived',p.archived_at is not null,'createdAt',p.created_at,'references',private.goods_photo_references(p.image_path)) order by p.created_at desc,p.id),'[]') into result
    from (select * from public.goods_photo_library p where (p.archived_at is not null)=p_archived and strpos(lower(normalize(p.name,NFC)),search_term)>0 order by p.created_at desc,p.id limit 20 offset (p_page-1)*20) p;
  return jsonb_build_object('rows',result,'total',total_count,'page',p_page,'pageSize',20);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_photo(p_id uuid, p_image_path text, p_name text, p_expected_revision integer, p_archived boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); previous public.goods_photo_library; saved public.goods_photo_library; object_path text; refs jsonb; clean_name text;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='forbidden'; end if;
  -- macOS 파일 이름(NFD 한글)도 화면에 보이는 그대로의 NFC로 저장해 검색에 걸리게 한다.
  clean_name:=normalize(btrim(p_name),NFC);
  if p_id is null or clean_name is null or char_length(clean_name) not between 1 and 100 or p_expected_revision is null or p_expected_revision<0 or p_archived is null then raise invalid_parameter_value using message='invalid_goods_photo'; end if;
  perform pg_advisory_xact_lock(hashtextextended('goods-photo:'||p_id::text,0));
  select * into previous from public.goods_photo_library where id=p_id for update;
  if found then
    if previous.image_path is distinct from p_image_path then raise check_violation using message='photo_path_immutable'; end if;
    -- Register retries are safe only for the exact creator and original payload.
    if p_expected_revision=0 and previous.created_by=actor and previous.revision=1 and previous.name=clean_name and previous.archived_at is null and not p_archived then
      return jsonb_build_object('id',previous.id,'revision',previous.revision);
    end if;
    if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='goods_photo_changed'; end if;
    refs:=private.goods_photo_references(previous.image_path);
    if p_archived and jsonb_array_length(refs)>0 then raise check_violation using message='goods_photo_in_use'; end if;
    update public.goods_photo_library set name=clean_name,archived_at=case when p_archived then coalesce(archived_at,clock_timestamp()) else null end,revision=revision+1,updated_at=clock_timestamp() where id=p_id returning * into saved;
  else
    if p_expected_revision<>0 or p_archived then raise sqlstate 'PT409' using message='goods_photo_changed'; end if;
    if p_image_path is null or p_image_path !~ '^public-media/catalog/good/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$' then raise check_violation using message='unverified_artwork'; end if;
    object_path:=substr(p_image_path,length('public-media/')+1);
    update public.admin_artwork_upload_claims claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
      where claim.actor_id=actor and claim.path=object_path and claim.kind='good' and claim.status='verified'
        and claim.verified_at is not null and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
    if not found then raise check_violation using message='unverified_artwork'; end if;
    insert into public.goods_photo_library(id,image_path,name,created_by) values(p_id,p_image_path,clean_name,actor) returning * into saved;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.goods.photo.saved','goods_photo:'||p_id::text,jsonb_build_object('before',case when previous.id is null then null else to_jsonb(previous) end,'after',to_jsonb(saved)));
  return jsonb_build_object('id',saved.id,'revision',saved.revision);
end $function$

-- ---------------------------------------------------------------------------
-- 5. 콜백 선점 · 결과 보류 (service role)
-- ---------------------------------------------------------------------------
-- KCP 인증창이 사용자의 브라우저를 Ret_URL로 보내면 처리기가 부른다. 그 요청은
-- 교차 사이트 POST라 로그인 쿠키가 없으므로 계정은 세션 행에서만 읽는다.
--
-- 선점은 세션마다 한 번뿐이다. 선점한 요청만 완료 토큰 해시를 세션에 적고, 처리기는
-- 그 토큰을 같은 브라우저에만 쿠키로 준다. 선점이 만료된 confirming(처리기가 중간에
-- 죽은 경우)은 다시 선점하지 않고 실패로 닫는다 — 재선점을 허용하면 nonce와 거래등록키를
-- 아는 다른 브라우저가 남의 결과에 새 완료 토큰을 받을 수 있다.
--
-- 반환 claim_status:
--   claimed     — 이 호출이 결과 조회 권한을 얻었다(선점 토큰 2분)
--   in_progress — 다른 요청이 조회 중이다
--   staged      — 결과가 이미 보류돼 본인 세션 확정만 남았다(재전송·새로고침)
--   terminal    — 이미 끝났다(state를 함께 돌려준다)
create function public.claim_adult_verification_callback(
  p_callback_nonce_digest text,
  p_registration_key text,
  p_claim_token uuid,
  p_completion_token_digest text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_session private.adult_verification_sessions%rowtype;
begin
  if p_callback_nonce_digest is null
    or p_callback_nonce_digest !~ '^[0-9a-f]{64}$'
    or p_registration_key is null
    or p_registration_key !~ '^[A-Za-z0-9]{1,40}$'
    or p_claim_token is null
    or p_completion_token_digest is null
    or p_completion_token_digest !~ '^[0-9a-f]{64}$'
  then
    raise invalid_parameter_value using message = 'adult_verification_callback_invalid';
  end if;

  select session.*
  into v_session
  from private.adult_verification_sessions as session
  where session.callback_nonce_digest = p_callback_nonce_digest
  for update;

  if not found
    or v_session.registration_key is null
    or v_session.registration_key is distinct from p_registration_key
  then
    raise no_data_found using message = 'adult_verification_callback_invalid';
  end if;

  if v_session.state in ('verified', 'underage', 'failed', 'expired') then
    return pg_catalog.jsonb_build_object(
      'claimStatus', 'terminal',
      'state', v_session.state,
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.expires_at <= v_now then
    perform private.close_adult_verification_session(v_session.id, 'expired', 'session_expired');
    return pg_catalog.jsonb_build_object(
      'claimStatus', 'terminal',
      'state', 'expired',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.state = 'awaiting_owner' then
    return pg_catalog.jsonb_build_object(
      'claimStatus', 'staged',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.state = 'confirming' then
    if v_session.claim_expires_at > v_now then
      return pg_catalog.jsonb_build_object(
        'claimStatus', 'in_progress',
        'presentation', v_session.presentation,
        'returnPath', v_session.return_path
      );
    end if;

    perform private.close_adult_verification_session(v_session.id, 'failed', 'claim_expired');
    return pg_catalog.jsonb_build_object(
      'claimStatus', 'terminal',
      'state', 'failed',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  -- 거래등록만 끝난 registered만 남는다.
  update private.adult_verification_sessions
  set
    state = 'confirming',
    claim_token = p_claim_token,
    claim_expires_at = v_now + interval '2 minutes',
    completion_token_digest = p_completion_token_digest
  where id = v_session.id
  returning * into v_session;

  return pg_catalog.jsonb_build_object(
    'claimStatus', 'claimed',
    'sessionId', v_session.id,
    'providerMode', v_session.provider_mode,
    'providerOrderId', v_session.provider_order_id,
    'registrationKey', v_session.registration_key,
    'presentation', v_session.presentation,
    'returnPath', v_session.return_path
  );
end;
$function$

-- ---------------------------------------------------------------------------
-- 6. 본인 세션 확정 (authenticated)
-- ---------------------------------------------------------------------------
-- 콜백 처리기는 결과를 보류한 뒤 같은 브라우저를 이 확정 경로로 보낸다. 그 요청은
-- GET 최상위 이동이라 로그인 쿠키와 완료 토큰 쿠키가 함께 실린다. auth.uid()가 세션을
-- 만든 계정이고 완료 토큰이 콜백을 선점한 브라우저의 것일 때만 증거가 생긴다. 둘 중
-- 하나라도 어긋나면 "없음"과 구별되지 않게 거절한다.
create function public.complete_my_adult_verification(
  p_callback_nonce_digest text,
  p_completion_token_digest text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_user uuid := (select auth.uid());
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_session private.adult_verification_sessions%rowtype;
  v_evidence private.adult_verifications%rowtype;
  v_moved record;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if p_callback_nonce_digest is null
    or p_callback_nonce_digest !~ '^[0-9a-f]{64}$'
    or p_completion_token_digest is null
    or p_completion_token_digest !~ '^[0-9a-f]{64}$'
  then
    raise invalid_parameter_value using message = 'adult_verification_invalid';
  end if;

  -- 잠금 순서: 계정(fence 잠금) → 세션 → 명의. begin과 같은 계정 잠금을 먼저 잡아
  -- 탈퇴 신청·새 인증 시작과 직렬화한다.
  if private.is_account_write_fenced(v_user) then
    raise insufficient_privilege using message = 'adult_verification_account_blocked';
  end if;

  select session.*
  into v_session
  from private.adult_verification_sessions as session
  where session.callback_nonce_digest = p_callback_nonce_digest
  for update;

  if not found
    or v_session.user_id is distinct from v_user
    or v_session.completion_token_digest is null
    or v_session.completion_token_digest is distinct from p_completion_token_digest
  then
    raise no_data_found using message = 'adult_verification_not_found';
  end if;

  if v_session.state in ('verified', 'underage', 'failed', 'expired') then
    return pg_catalog.jsonb_build_object(
      'outcome', v_session.state,
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.expires_at <= v_now then
    perform private.close_adult_verification_session(v_session.id, 'expired', 'session_expired');
    return pg_catalog.jsonb_build_object(
      'outcome', 'expired',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  -- 결과 조회 중이다. 선점이 만료됐으면 처리기가 중간에 죽은 것이고 콜백은 다시 오지
  -- 않는다 — 기다리게 두지 않고 실패로 닫아 다시 시작하게 한다.
  if v_session.state = 'confirming' and v_session.claim_expires_at <= v_now then
    perform private.close_adult_verification_session(v_session.id, 'failed', 'claim_expired');
    return pg_catalog.jsonb_build_object(
      'outcome', 'failed',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.state <> 'awaiting_owner' then
    return pg_catalog.jsonb_build_object(
      'outcome', 'pending',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_user
      and profile.suspended_at is not null
  ) then
    perform private.close_adult_verification_session(v_session.id, 'failed', 'account_blocked');
    return pg_catalog.jsonb_build_object(
      'outcome', 'failed',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.staged_outcome = 'underage' then
    update private.adult_verifications
    set revoked_at = v_now, revoked_reason = 'underage_result'
    where user_id = v_user
      and revoked_at is null;

    perform private.close_adult_verification_session(v_session.id, 'underage', null);

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_user,
      'identity.adult_verification.underage',
      'profiles:' || v_user::text,
      pg_catalog.jsonb_build_object(
        'provider', v_session.provider,
        'providerMode', v_session.provider_mode,
        'policyVersion', v_session.staged_policy_version
      )
    );

    return pg_catalog.jsonb_build_object(
      'outcome', 'underage',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  -- 같은 명의의 동시 확정을 직렬화한다. 두 계정이 같은 DI로 동시에 확정해도
  -- 활성 증거는 하나만 남고, 나중에 확정한 계정이 그 명의를 가진다.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('adult-verification-subject:' || v_session.staged_subject_digest, 0)
  );

  -- 아래 두 해제가 건드릴 활성 증거(내 증거 + 이 명의의 다른 계정 증거)를 id 순서로 먼저
  -- 잠근다. 인증된 두 계정이 서로의 명의로 동시에 확정하면 명의 잠금이 달라 직렬화되지
  -- 않고, 각자 자기 증거를 먼저 잠근 뒤 상대 증거를 기다려 교착될 수 있다 — 잠금 순서를
  -- 하나로 고정해 한쪽이 기다리게 한다.
  perform 1
  from private.adult_verifications as evidence
  where evidence.revoked_at is null
    and (evidence.user_id = v_user or evidence.subject_digest = v_session.staged_subject_digest)
  order by evidence.id
  for update;

  update private.adult_verifications
  set revoked_at = v_now, revoked_reason = 'superseded'
  where user_id = v_user
    and revoked_at is null;

  for v_moved in
    update private.adult_verifications
    set revoked_at = v_now, revoked_reason = 'subject_moved'
    where subject_digest = v_session.staged_subject_digest
      and user_id <> v_user
      and revoked_at is null
    returning user_id
  loop
    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_user,
      'identity.adult_verification.subject_moved',
      'profiles:' || v_moved.user_id::text,
      pg_catalog.jsonb_build_object('toUser', v_user)
    );
  end loop;

  insert into private.adult_verifications (
    user_id,
    session_id,
    provider,
    provider_mode,
    subject_digest,
    transaction_digest,
    policy_version,
    verified_at,
    expires_at
  )
  values (
    v_user,
    v_session.id,
    v_session.provider,
    v_session.provider_mode,
    v_session.staged_subject_digest,
    v_session.staged_transaction_digest,
    v_session.staged_policy_version,
    v_now,
    v_now + interval '1 year'
  )
  returning * into v_evidence;

  perform private.close_adult_verification_session(v_session.id, 'verified', null);

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_user,
    'identity.adult_verification.verified',
    'profiles:' || v_user::text,
    pg_catalog.jsonb_build_object(
      'provider', v_evidence.provider,
      'providerMode', v_evidence.provider_mode,
      'policyVersion', v_evidence.policy_version,
      'expiresAt', v_evidence.expires_at
    )
  );

  return pg_catalog.jsonb_build_object(
    'outcome', 'verified',
    'presentation', v_session.presentation,
    'returnPath', v_session.return_path,
    'expiresAt', v_evidence.expires_at
  );
end;
$function$

-- ---------------------------------------------------------------------------
-- 7. 내 성인 인증 상태 (authenticated)
-- ---------------------------------------------------------------------------
-- 화면 표시용이다. 노출·구매 경계는 이 응답이 아니라 서버 함수 안의
-- adult_verification_valid로 다시 판정한다.
create function public.get_my_adult_verification()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  v_user uuid := (select auth.uid());
  v_evidence private.adult_verifications%rowtype;
begin
  if v_user is null then
    return pg_catalog.jsonb_build_object('status', 'none');
  end if;

  select evidence.*
  into v_evidence
  from private.adult_verifications as evidence
  where evidence.user_id = v_user
  order by evidence.verified_at desc, evidence.id desc
  limit 1;

  if not found then
    return pg_catalog.jsonb_build_object('status', 'none');
  end if;

  if v_evidence.revoked_at is not null then
    return pg_catalog.jsonb_build_object(
      'status', 'revoked',
      'reason', v_evidence.revoked_reason,
      'revokedAt', v_evidence.revoked_at
    );
  end if;

  if v_evidence.expires_at <= pg_catalog.now() then
    return pg_catalog.jsonb_build_object(
      'status', 'expired',
      'verifiedAt', v_evidence.verified_at,
      'expiresAt', v_evidence.expires_at
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'status', 'verified',
    'verifiedAt', v_evidence.verified_at,
    'expiresAt', v_evidence.expires_at
  );
end;
$function$

-- pg_cron이 있는 배포만 등록한다. cron.schedule은 이름 기준 upsert라 재적용에 안전하다.
