-- 버킷은 종류를 모르므로 가장 큰 한도를 둔다. 종류별 판정은 아래 클레임 제약과 함수가 맡는다.
do $$
begin
  update storage.buckets set file_size_limit = 20 * 1024 * 1024
    where id in ('public-media', 'admin-artwork-staging');
  if (select count(*) from storage.buckets
      where id in ('public-media', 'admin-artwork-staging') and file_size_limit = 20 * 1024 * 1024) <> 2 then
    raise exception 'admin_artwork_bucket_missing';
  end if;
end $$

do $patch$
declare
  target regprocedure;
  body text;
  anchor text;
begin
  target := 'public.service_prepare_admin_artwork_upload(uuid,text,text,text,integer,timestamptz)'::regprocedure;
  body := pg_get_functiondef(target);
  anchor := $a$or p_source_size > 5 * 1024 * 1024$a$;
  if (length(body) - length(replace(body, anchor, ''))) / length(anchor) <> 1 then
    raise exception 'artwork_prepare_size_anchor_changed';
  end if;
  execute replace(body, anchor,
    $a$or p_source_size > (case when p_kind = 'good' then 20 * 1024 * 1024 else 5 * 1024 * 1024 end)$a$);

  target := 'public.service_verify_admin_artwork_upload(uuid,text,integer)'::regprocedure;
  body := pg_get_functiondef(target);
  anchor := $a$p_final_size > 5 * 1024 * 1024 then$a$;
  if (length(body) - length(replace(body, anchor, ''))) / length(anchor) <> 1 then
    raise exception 'artwork_verify_size_anchor_changed';
  end if;
  execute replace(body, anchor, $a$p_final_size > (case when (
      select claim.kind from public.admin_artwork_upload_claims as claim
      where claim.actor_id = p_actor_id and claim.path = p_path
    ) = 'good' then 20 * 1024 * 1024 else 5 * 1024 * 1024 end) then$a$);

  target := 'public.service_verify_admin_artwork_upload(uuid,text,integer,integer,integer)'::regprocedure;
  body := pg_get_functiondef(target);
  anchor := $a$p_final_width not between 1 and 8192 or p_final_height not between 1 and 8192$a$;
  if (length(body) - length(replace(body, anchor, ''))) / length(anchor) <> 1 then
    raise exception 'artwork_verify_dimension_anchor_changed';
  end if;
  execute replace(body, anchor, $a$least(p_final_width, p_final_height) < 1
    or greatest(p_final_width, p_final_height) > (case when (
      select claim.kind from public.admin_artwork_upload_claims as claim
      where claim.actor_id = p_actor_id and claim.path = p_path
    ) = 'good' then 30000 else 8192 end)$a$);
end $patch$

create function public.admin_set_erp_category_mappings(p_entries jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_entry jsonb;
  v_index integer;
  v_raw text;
  v_erp_category text;
  v_seen text[] := array[]::text[];
  v_result jsonb;
  v_changed integer := 0;
  v_unchanged integer := 0;
  v_rejected jsonb := '[]'::jsonb;
begin
  perform private.require_operator_capability('platform.manage', false);

  if v_actor is null or not public.has_operator_capability('platform.manage', false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if p_entries is null
     or pg_catalog.jsonb_typeof(p_entries) <> 'array'
     or pg_catalog.jsonb_array_length(p_entries) not between 1 and 500 then
    raise invalid_parameter_value using message = 'invalid_erp_category_mappings';
  end if;

  -- 카테고리 보관·이동과 같은 트리 잠금을 처음에 잡아 묶음 전체를 같은 트리로 검사한다.
  -- 단건 RPC가 다시 잡아도 같은 트랜잭션이라 기다리지 않는다.
  perform private.lock_catalog_category_tree();

  for v_entry, v_index in
    select item.value, item.ordinality::integer - 1
    from pg_catalog.jsonb_array_elements(p_entries) with ordinality as item(value, ordinality)
  loop
    v_raw := case
      when pg_catalog.jsonb_typeof(v_entry) = 'object' and pg_catalog.jsonb_typeof(v_entry -> 'erp_category') = 'string'
        then v_entry ->> 'erp_category'
    end;
    v_erp_category := private.erp_item_text(v_raw, true);

    if v_erp_category is null then
      v_rejected := v_rejected || pg_catalog.jsonb_build_object('index', v_index, 'erp_category', v_raw, 'reason', 'invalid_erp_category');
      continue;
    end if;
    if v_erp_category = any(v_seen) then
      v_rejected := v_rejected || pg_catalog.jsonb_build_object('index', v_index, 'erp_category', v_raw, 'reason', 'duplicate_erp_category');
      continue;
    end if;
    v_seen := v_seen || v_erp_category;

    -- category_id는 있어야 하고 uuid 문자열 또는 null이다(null은 연결 해제).
    if coalesce(pg_catalog.jsonb_typeof(v_entry -> 'category_id'), '') not in ('string', 'null') then
      v_rejected := v_rejected || pg_catalog.jsonb_build_object('index', v_index, 'erp_category', v_raw, 'reason', 'invalid_category_id');
      continue;
    end if;

    begin
      v_result := public.admin_set_erp_category_mapping(v_erp_category, (v_entry ->> 'category_id')::uuid);
      if (v_result ->> 'changed')::boolean then
        v_changed := v_changed + 1;
      else
        v_unchanged := v_unchanged + 1;
      end if;
    exception
      when invalid_text_representation then
        v_rejected := v_rejected || pg_catalog.jsonb_build_object('index', v_index, 'erp_category', v_raw, 'reason', 'invalid_category_id');
      when invalid_parameter_value or check_violation or no_data_found then
        v_rejected := v_rejected || pg_catalog.jsonb_build_object('index', v_index, 'erp_category', v_raw, 'reason', sqlerrm);
    end;
  end loop;

  return pg_catalog.jsonb_build_object('changed', v_changed, 'unchanged', v_unchanged, 'rejected', v_rejected);
end;
$$

-- 1. 랜덤 조건 ------------------------------------------------------------------------------------------
create or replace function private.goods_random_option_problem(p_good_id text) returns text
language plpgsql stable security definer set search_path='' as $$
declare good public.goods;
begin
  select * into good from public.goods where id=p_good_id;
  if not found then return 'good_not_found'; end if;
  if (select count(*) from public.goods_variants where good_id=p_good_id and archived_at is null)<2 then return 'random_option_count'; end if;
  if not exists(select 1 from public.goods_variants where good_id=p_good_id and is_default and archived_at is null) then
    return 'random_option_default_inactive';
  end if;
  -- 예약판매: 판매 중 옵션이 모두 예약을 선택했거나 모두 일반 재고이고, 예약이면 접수 시작·종료·발송 예정일이 같아야 한다.
  if (exists(select 1 from public.goods_variants where good_id=p_good_id and archived_at is null and preorder_policy_id is null)
      and exists(select 1 from public.goods_variants where good_id=p_good_id and archived_at is null and preorder_policy_id is not null))
    or (select count(distinct format('%s|%s|%s',policy.starts_at,policy.ends_at,policy.expected_ship_date))
      from public.goods_variants variant join private.goods_preorder_policies policy on policy.id=variant.preorder_policy_id
      where variant.good_id=p_good_id and variant.archived_at is null)>1 then
    return 'random_option_preorder_mismatch';
  end if;
  if (select count(distinct price) from public.goods_variants where good_id=p_good_id and archived_at is null)>1
    or (select count(distinct coalesce(schedule.signature,'')) from public.goods_variants variant
      cross join lateral (select string_agg(format('%s|%s|%s',period.starts_at,period.ends_at,period.discount_price),','
          order by period.starts_at,period.ends_at,period.discount_price) signature
        from private.goods_variant_price_periods period
        where period.variant_id=variant.id and period.state='active' and period.ends_at>clock_timestamp()) schedule
      where variant.good_id=p_good_id and variant.archived_at is null)>1 then
    return 'random_option_price_mismatch';
  end if;
  -- 같은 옵션 배정 상한: 고객은 옵션을 고르지 않으므로 판매 중 모든 옵션이 같은 값이어야 한다(null = 상한 없음).
  if (select count(distinct format('%s|%s',order_max_qty,member_max_qty)) from public.goods_variants
    where good_id=p_good_id and archived_at is null)>1 then
    return 'random_option_limit_mismatch';
  end if;
  if good.custom_inputs_enabled then return 'random_option_custom_inputs'; end if;
  if exists(select 1 from private.goods_aggregation_members where good_id=p_good_id or root_good_id=p_good_id)
    or exists(select 1 from private.goods_aggregation_roots where root_good_id=p_good_id) then
    return 'random_option_aggregation';
  end if;
  if exists(select 1 from private.goods_group_members where good_id=p_good_id)
    or exists(select 1 from private.goods_groups where common_good_id=p_good_id) then
    return 'random_option_group';
  end if;
  return null;
end $$

-- 배송비 절약 추천: 랜덤 후보는 예약이어도 풀 기준이다(옵션별 남은 예약 물량으로 후보가 갈리지 않게).
do $patch$
declare definition text;
  target constant regprocedure:='public.get_product_shipping_savings(text,uuid,integer)'::regprocedure;
  anchor constant text:=$old$case when g.option_sale_mode='random' and resolved.mode='stock'$old$;
begin
  definition:=pg_get_functiondef(target);
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'shipping_savings_random_preorder_anchor_changed'; end if;
  execute replace(definition,anchor,$new$case when g.option_sale_mode='random'$new$);
  if exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure=target) then
    perform private.register_operator_internal_contract(target);
  end if;
end $patch$

-- 3. 배정 ------------------------------------------------------------------------------------------------
-- 난수 범위를 2^32에서 2^62로 넓힌다. 예약 물량은 옵션마다 integer 상한까지 받을 수 있어(운영자가 '사실상 무제한'으로 큰 값을 넣는 경우)
-- 남은 물량 합이 2^32를 넘으면 모든 주문이 invalid_random_bound로 실패했다. 8바이트에서 하위 62비트를 거부 추출한다(균등).
create or replace function private.random_below(p_bound bigint) returns bigint
language plpgsql volatile set search_path='' as $$
declare accept_below bigint; drawn bigint;
  span constant bigint:=4611686018427387904;
begin
  if p_bound is null or p_bound<1 or p_bound>span then raise invalid_parameter_value using message='invalid_random_bound'; end if;
  accept_below:=span-(span%p_bound);
  loop
    drawn:=('x'||encode(extensions.gen_random_bytes(8),'hex'))::bit(64)::bigint & 4611686018427387903;
    if drawn<accept_below then return drawn%p_bound; end if;
  end loop;
end $$

-- 20261028160100의 배정에 예약 공급과 같은 옵션 배정 상한을 더한다. 호출자(legacy 주문 코어)는 회원·장바구니 잠금과
-- 굿즈 행 FOR UPDATE를 쥐고 있다. 반환값은 배정 행 소계.
--   풀: 판매 중 옵션 전부(id 순 FOR UPDATE). 공급 방식이 섞이거나 옵션 가격이 다르면 random_option_unavailable.
--   예약: 접수 중인 옵션이 없으면 preorder_sale_not_open, 남은 예약 물량 합이 모자라면 preorder_capacity_exceeded.
--   상한: 옵션별 잔여 = min(주문당 상한 - 이 주문의 앞선 행, 1인 상한 - 회원 누적(결제 대기 포함)). 가능 수량이 모자라면 추출 전에
--   random_option_limit_exceeded. 추출은 상한에 닿지 않은 옵션의 남은 물량에 비례한다(상한이 없으면 20261028160100과 같다).
--   한 번 뽑을 때마다 가능 수량이 정확히 1 줄므로 미리 판정한 가능 수량이 있으면 추출 중에 막히지 않는다.
create or replace function private.allocate_random_option_items(p_order_id uuid,p_user_id uuid,p_cart_item_id uuid,p_good_id text,
  p_cart_variant_id uuid,p_qty integer,p_at timestamptz,p_custom_inputs jsonb,p_sales_policy jsonb) returns bigint
language plpgsql security definer set search_path='' as $$
declare good public.goods; key_price record; candidate record; supply record; price record;
  pool_ids uuid[]:='{}'; pool_left integer[]:='{}'; pool_cap bigint[]:='{}'; pool_before jsonb:='[]'; counts integer[];
  pool_mode text; any_open boolean:=false; remaining bigint:=0; feasible bigint:=0; weight bigint; cap bigint; in_order bigint;
  roll bigint; walk bigint; slot integer; allocated jsonb:='[]';
  draw_rolls bigint[]; draw_bounds bigint[]; draw_slots integer[]; slot_draws jsonb[];
  draw uuid:=pg_catalog.gen_random_uuid(); item_id uuid; subtotal bigint:=0; step integer;
  rng constant text:='pgcrypto.gen_random_bytes:rejection';
begin
  if p_qty is null or p_qty<1 then raise check_violation using message='invalid cart item'; end if;
  select * into good from public.goods where id=p_good_id;
  if not found or good.option_sale_mode<>'random' then
    raise check_violation using message=format('random_option_unavailable: %s',p_good_id);
  end if;
  select * into key_price from private.resolve_goods_variant_price(p_cart_variant_id,p_at);
  for candidate in select v.id,v.order_max_qty,v.member_max_qty from public.goods_variants v
    where v.good_id=p_good_id and v.archived_at is null order by v.id for update loop
    select * into supply from private.resolve_goods_variant_supply(candidate.id,p_at);
    select * into price from private.resolve_goods_variant_price(candidate.id,p_at);
    -- 견적은 장바구니 키 옵션 가격으로 보였다. 배정 옵션 가격이 다르면 청구가 달라지므로 주문하지 않는다.
    -- 일반 재고·예약이 섞이면 배정에 따라 발송 약속이 달라지므로 주문하지 않는다(조건 함수가 저장도 막는다).
    if (pool_mode is not null and supply.mode<>pool_mode) or price.effective_price is distinct from key_price.effective_price
      or price.regular_price is distinct from key_price.regular_price then
      raise check_violation using message=format('random_option_unavailable: %s',p_good_id);
    end if;
    pool_mode:=supply.mode;
    any_open:=any_open or supply.state='open';
    cap:=null;
    if candidate.order_max_qty is not null then
      select coalesce(sum(item.qty::bigint),0) into in_order from public.order_items item
        where item.order_id=p_order_id and item.variant_id=candidate.id;
      cap:=greatest(candidate.order_max_qty-in_order,0);
    end if;
    if candidate.member_max_qty is not null then
      cap:=least(coalesce(cap,9223372036854775807),
        greatest(candidate.member_max_qty-private.member_variant_reserved_qty(p_user_id,candidate.id),0));
    end if;
    pool_ids:=pool_ids||candidate.id;
    pool_left:=pool_left||greatest(supply.available_qty,0);
    pool_cap:=array_append(pool_cap,cap);
    -- 증빙 모양은 상한이 없으면 20261028160100과 같다. 상한이 있으면 그 옵션의 배정 가능 잔여(capQty)를 더한다.
    pool_before:=pool_before||jsonb_build_array(jsonb_build_object('variantId',candidate.id,'availableQty',greatest(supply.available_qty,0))
      ||case when cap is null then '{}'::jsonb else jsonb_build_object('capQty',cap) end);
    remaining:=remaining+greatest(supply.available_qty,0);
    feasible:=feasible+least(greatest(supply.available_qty,0)::bigint,coalesce(cap,9223372036854775807));
  end loop;
  if cardinality(pool_ids)<2 then raise check_violation using message=format('random_option_unavailable: %s',p_good_id); end if;
  if pool_mode='preorder' then
    if not any_open then raise check_violation using message='preorder_sale_not_open'; end if;
    if remaining<p_qty then raise check_violation using message='preorder_capacity_exceeded'; end if;
  elsif remaining<p_qty then
    raise check_violation using message=format('out of stock: %s',p_good_id);
  end if;
  if feasible<p_qty then raise check_violation using message=format('random_option_limit_exceeded: %s',p_good_id); end if;
  counts:=array_fill(0,array[cardinality(pool_ids)]);
  -- 추출 근거는 고정 길이 배열에 모은다(원소 대입은 제자리라 수량에 선형). jsonb 변환은 루프 뒤 한 번이다.
  draw_rolls:=array_fill(0::bigint,array[p_qty]); draw_bounds:=array_fill(0::bigint,array[p_qty]); draw_slots:=array_fill(0,array[p_qty]);
  for step in 1..p_qty loop
    weight:=0;
    for slot in 1..cardinality(pool_ids) loop
      if pool_cap[slot] is null or counts[slot]<pool_cap[slot] then weight:=weight+pool_left[slot]; end if;
    end loop;
    roll:=private.random_below(weight);
    walk:=roll; slot:=1;
    loop
      if pool_cap[slot] is null or counts[slot]<pool_cap[slot] then
        exit when walk<pool_left[slot];
        walk:=walk-pool_left[slot];
      end if;
      slot:=slot+1;
    end loop;
    draw_rolls[step]:=roll; draw_bounds[step]:=weight; draw_slots[step]:=slot;
    pool_left[slot]:=pool_left[slot]-1; counts[slot]:=counts[slot]+1;
  end loop;
  -- 배정 행마다 그 옵션에 떨어진 추출만 담는다(같은 근거를 행마다 복사하지 않는다). 풀 순서(slot)대로 한 번에 묶는다.
  select array_agg(coalesce(grouped.steps,'[]'::jsonb) order by slot_index.value) into slot_draws
  from generate_series(1,cardinality(pool_ids)) slot_index(value)
  left join (select drawn.slot_no,jsonb_agg(jsonb_build_object('step',drawn.step,'roll',drawn.roll,'bound',drawn.bound,
        'variantId',pool_ids[drawn.slot_no]) order by drawn.step) steps
      from unnest(draw_rolls,draw_bounds,draw_slots) with ordinality drawn(roll,bound,slot_no,step)
      group by drawn.slot_no) grouped on grouped.slot_no=slot_index.value;
  for slot in 1..cardinality(pool_ids) loop
    continue when counts[slot]=0;
    select * into supply from private.resolve_goods_variant_supply(pool_ids[slot],p_at);
    select * into price from private.resolve_goods_variant_price(pool_ids[slot],p_at);
    if supply.mode='stock' then
      perform private.change_goods_variant_stock(p_good_id,pool_ids[slot],-counts[slot]::bigint);
    end if;
    insert into public.order_items(order_id,good_id,variant_id,qty,unit_price,good_name_snapshot,good_type_snapshot,good_ip_id_snapshot,
      regular_unit_price_snapshot,price_period_id,price_evaluated_at,sales_policy_snapshot,supply_source,preorder_policy_id,
      preorder_expected_ship_date,preorder_snapshot,custom_inputs_snapshot,option_sale_mode_snapshot)
    values(p_order_id,p_good_id,pool_ids[slot],counts[slot],price.effective_price,good.name,good.type,good.ip_id,
      price.regular_price,price.price_period_id,p_at,p_sales_policy,supply.mode,supply.policy_id,supply.expected_ship_date,
      case when supply.mode='preorder' then jsonb_build_object('version',1,'policyId',supply.policy_id,
        'policyRevision',supply.policy_revision,'startsAt',supply.starts_at,'endsAt',supply.ends_at,
        'expectedShipDate',supply.expected_ship_date) end,
      p_custom_inputs,'random')
    returning id into item_id;
    if supply.mode='preorder' then
      perform private.reserve_goods_preorder_item(item_id,p_at);
    end if;
    insert into private.order_item_random_allocations(order_item_id,order_id,user_id,good_id,draw_id,cart_item_id,cart_variant_id,
      variant_id,qty,pool_before,draws,rng)
    values(item_id,p_order_id,p_user_id,p_good_id,draw,p_cart_item_id,p_cart_variant_id,pool_ids[slot],counts[slot],pool_before,slot_draws[slot],rng);
    allocated:=allocated||jsonb_build_array(jsonb_build_object('orderItemId',item_id,'variantId',pool_ids[slot],'qty',counts[slot]));
    subtotal:=subtotal+price.effective_price::bigint*counts[slot];
  end loop;
  insert into public.audit_log(actor_id,action,target,diff) values(p_user_id,'order.random_option_allocated','order:'||p_order_id,
    jsonb_build_object('drawId',draw,'goodId',p_good_id,'cartVariantId',p_cart_variant_id,'qty',p_qty,'rng',rng,
      'supplySource',pool_mode,'pool',pool_before,'allocations',allocated));
  return subtotal;
end $$

-- 4. 장바구니·견적 -----------------------------------------------------------------------------------------
-- 장바구니 담기: 랜덤 굿즈의 가용 수량은 예약이어도 풀 합계다(현재 본문에 앵커 치환).
do $patch$
declare definition text;
  target constant regprocedure:='private.set_cart_quantity_with_inputs(text,uuid,integer,integer,jsonb)'::regprocedure;
  anchor constant text:=$old$    select coalesce(sum(supply.available_qty),0)::integer into available_stock from public.goods_variants variant
      cross join lateral private.resolve_goods_variant_supply(variant.id,statement_timestamp()) supply
      where variant.good_id=p_good_id and variant.archived_at is null and supply.mode='stock';$old$;
begin
  definition:=pg_get_functiondef(target);
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'set_cart_random_preorder_anchor_changed'; end if;
  execute replace(definition,anchor,$new$    -- 일반 재고·예약 모두 풀 합계(예약은 접수 중일 때만 남은 예약 물량 합).
    available_stock:=private.random_option_pool_qty(p_good_id,statement_timestamp());$new$);
  if exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure=target) then
    perform private.register_operator_internal_contract(target);
  end if;
end $patch$

-- legacy 장바구니 견적. 랜덤 줄(20261028160100):
--   supply는 goods_variant_supply가 이미 풀로 답한다(일반 재고·예약). available = 같은 굿즈 줄 수량 합 ≤ 풀.
--   optionLimit = 랜덤 줄의 정적 상한(판매 중 옵션 수 × 같은 옵션 배정 상한)과 회원의 이 굿즈 누적 수량(옵션 합이라 배정과 무관).
--   옵션별 누적은 내보내지 않는다 — 결제 대기 주문의 배정 옵션이 드러난다.
create or replace function public.quote_goods_sales(items jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare quote jsonb; lines jsonb:='[]'; line jsonb; supply jsonb; next_change timestamptz; selling boolean; shipping_quote jsonb;
  variant public.goods_variants; actor uuid:=auth.uid(); reserved bigint; limit_reason text; sale_mode text; good_qty bigint; available boolean;
  option_count bigint; order_max bigint; member_max bigint;
begin
  quote:=private.quote_goods_sales_before_preorder(items);
  next_change:=(quote->>'nextChangeAt')::timestamptz;
  for line in select value from jsonb_array_elements(quote->'lines') loop
    select public.goods_variant_supply(v),good.stock<>'soldout',good.option_sale_mode into supply,selling,sale_mode
      from public.goods_variants v join public.goods good on good.id=v.good_id
      where v.id=(line->>'variantId')::uuid and good.id=line->>'goodId';
    if supply is null then raise check_violation using message='sales_quote_variant_unavailable'; end if;
    select * into variant from public.goods_variants where id=(line->>'variantId')::uuid;
    if sale_mode='random' then
      select coalesce(sum((other->>'qty')::bigint),0) into good_qty from jsonb_array_elements(quote->'lines') other where other->>'goodId'=line->>'goodId';
      available:=selling and good_qty<=(supply->>'availableQty')::bigint;
      select count(*) into option_count from public.goods_variants where good_id=variant.good_id and archived_at is null;
      order_max:=case when variant.order_max_qty is null then null else least(variant.order_max_qty::bigint*option_count,2147483647) end;
      member_max:=case when variant.member_max_qty is null then null else least(variant.member_max_qty::bigint*option_count,2147483647) end;
      reserved:=case when actor is null or member_max is null then null else (select coalesce(sum(item.qty::bigint),0)
        from public.orders o join public.order_items item on item.order_id=o.id
        where o.user_id=actor and o.status<>'canceled' and item.good_id=variant.good_id) end;
      limit_reason:=case
        when order_max is not null and good_qty>order_max then 'option_order_limit_exceeded'
        when reserved is not null and reserved+good_qty>member_max then 'option_member_limit_exceeded' end;
    else
      available:=selling and (line->>'qty')::bigint<=(supply->>'availableQty')::integer;
      order_max:=variant.order_max_qty; member_max:=variant.member_max_qty;
      reserved:=case when actor is null or variant.member_max_qty is null then null
        else private.member_variant_reserved_qty(actor,variant.id) end;
      limit_reason:=case
        when variant.order_max_qty is not null and (line->>'qty')::bigint>variant.order_max_qty then 'option_order_limit_exceeded'
        when reserved is not null and reserved+(line->>'qty')::bigint>variant.member_max_qty then 'option_member_limit_exceeded' end;
    end if;
    lines:=lines||jsonb_build_array(line||jsonb_build_object('supply',supply,'available',available,'optionSaleMode',sale_mode,
      'optionLimit',jsonb_build_object('orderMaxQty',order_max,'memberMaxQty',member_max,
        'memberReservedQty',reserved,'memberRemainingQty',case when reserved is null then null else greatest(0,member_max-reserved) end,
        'reason',limit_reason)));
    next_change:=least(next_change,(supply->>'nextChangeAt')::timestamptz);
  end loop;
  shipping_quote:=public.quote_goods_shipping(items);
  return quote||jsonb_build_object('lines',lines,'nextChangeAt',next_change,'shipping',shipping_quote,
    'coupon',private.quote_selected_coupon(lines,(quote->>'subtotal')::bigint,(shipping_quote->>'totalFee')::bigint));
end $$

-- 5. 운영자 일괄 예약 저장 -----------------------------------------------------------------------------------
-- 랜덤 굿즈의 옵션별 예약 저장을 한 트랜잭션으로 묶는다. 옵션마다 기존 RPC(admin_save_goods_preorder·admin_use_stock_supply)를
-- 부르므로 입력 검증·낙관 잠금(정책 revision)·권한(활성화·일반 재고 전환은 platform.manage)·감사는 옵션 단위로 그대로 남는다.
--   p_state draft·active: p_values = 공통 {startsAt, endsAt, expectedShipDate, approvalReference}, p_options = 판매 중 옵션 전부
--     [{variantId, policyId(이어 쓸 초안·없으면 null), expectedRevision, capacityQty}].
--   p_state stopped: p_options = 접수 중(active) 선택 정책이 있는 판매 중 옵션 전부 [{variantId, policyId, expectedRevision}].
--   p_state stock: p_options = 예약을 선택한 판매 중 옵션 전부 [{variantId, policyId, expectedRevision}].
-- 대상 집합이 다르면 random_preorder_options_mismatch. 커밋에서 랜덤 조건(같은 일정)을 다시 판정한다.
create function public.admin_save_random_goods_preorders(p_good_id text,p_state text,p_values jsonb,p_options jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid; good public.goods; entry jsonb; listed uuid[]:='{}'; expected uuid[]; saved jsonb; results jsonb:='[]';
  uuid_pattern constant text:='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
begin
  actor:=private.require_operator_capability('catalog.manage',false);
  if nullif(btrim(p_good_id),'') is null or p_state is null or p_state not in ('draft','active','stopped','stock')
    or jsonb_typeof(p_options) is distinct from 'array' or jsonb_array_length(p_options) not between 1 and 100
    or (p_state in ('draft','active') and (jsonb_typeof(p_values) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(p_values) key where key not in ('startsAt','endsAt','expectedShipDate','approvalReference')))) then
    raise invalid_parameter_value using message='invalid_random_preorder';
  end if;
  for entry in select value from jsonb_array_elements(p_options) loop
    if jsonb_typeof(entry) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(entry) key where key not in ('variantId','policyId','expectedRevision','capacityQty'))
      or jsonb_typeof(entry->'variantId') is distinct from 'string' or entry->>'variantId' !~ uuid_pattern
      or (coalesce(entry->'policyId','null'::jsonb)<>'null'::jsonb
        and (jsonb_typeof(entry->'policyId')<>'string' or entry->>'policyId' !~ uuid_pattern))
      or (coalesce(entry->'expectedRevision','null'::jsonb)<>'null'::jsonb
        and (jsonb_typeof(entry->'expectedRevision')<>'number' or entry->>'expectedRevision' !~ '^[1-9][0-9]{0,8}$'))
      or (p_state not in ('draft','active') and entry ? 'capacityQty') then
      raise invalid_parameter_value using message='invalid_random_preorder';
    end if;
    listed:=listed||(entry->>'variantId')::uuid;
  end loop;
  if cardinality(listed)<>(select count(distinct value) from unnest(listed) value) then
    raise invalid_parameter_value using message='invalid_random_preorder';
  end if;
  select * into good from public.goods where id=p_good_id for update;
  if not found or good.archived_at is not null then raise no_data_found using message='good_not_found'; end if;
  if good.option_sale_mode<>'random' then raise check_violation using message='random_option_required'; end if;
  perform 1 from public.goods_variants where good_id=p_good_id order by id for update;
  select coalesce(array_agg(variant.id order by variant.id),'{}') into expected from public.goods_variants variant
    left join private.goods_preorder_policies policy on policy.id=variant.preorder_policy_id
    where variant.good_id=p_good_id and variant.archived_at is null
      and (p_state in ('draft','active') or (p_state='stopped' and policy.state='active')
        or (p_state='stock' and variant.preorder_policy_id is not null));
  if cardinality(expected)=0 or (select array_agg(value order by value) from unnest(listed) value) is distinct from expected then
    raise check_violation using message='random_preorder_options_mismatch';
  end if;
  for entry in select value from jsonb_array_elements(p_options) order by value->>'variantId' loop
    if p_state='stock' then
      saved:=public.admin_use_stock_supply(p_good_id,(entry->>'variantId')::uuid,(entry->>'policyId')::uuid,(entry->>'expectedRevision')::integer);
    elsif p_state='stopped' then
      saved:=public.admin_save_goods_preorder(p_good_id,(entry->>'variantId')::uuid,(entry->>'policyId')::uuid,
        jsonb_build_object('state','stopped'),(entry->>'expectedRevision')::integer);
    else
      saved:=public.admin_save_goods_preorder(p_good_id,(entry->>'variantId')::uuid,(entry->>'policyId')::uuid,
        p_values||jsonb_build_object('state',p_state,'capacityQty',coalesce(entry->'capacityQty','null'::jsonb)),
        (entry->>'expectedRevision')::integer);
    end if;
    results:=results||jsonb_build_array(jsonb_build_object('variantId',entry->>'variantId')||saved);
  end loop;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.good.random_preorders_saved','goods:'||p_good_id,
    jsonb_build_object('state',p_state,'values',case when p_state in ('draft','active') then p_values end,'results',results));
  return jsonb_build_object('goodId',p_good_id,'state',p_state,'results',results);
end $$

-- ── 주문 줄 원본 ─────────────────────────────────────────────────────────────
-- 설정이 비어 있으면 계정 장바구니 전체(지금 계약). p_lock이면 줄을 굿즈·옵션·행 순서로 잠근다 — 코어는 굿즈
-- 부모 행을 먼저 잠근 뒤 커서에서 이 함수를 부르므로 잠금 순서(굿즈 → 장바구니 행 → 옵션)가 그대로다.
-- selection은 초안이 고른 장바구니 행만, direct는 초안 줄(장바구니 행 없음, cart_item_id null)이다.
create function private.checkout_source_lines(p_user_id uuid, p_lock boolean)
returns table (cart_item_id uuid, good_id text, variant_id uuid, qty integer, input_revision integer, input_values jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_setting text := coalesce(pg_catalog.current_setting('icons.checkout_draft', true), '');
  v_draft private.checkout_drafts%rowtype;
begin
  if v_setting = '' then
    if p_lock then
      return query select cart.id, cart.good_id, cart.variant_id, cart.qty, cart.input_revision, cart.input_values
        from public.cart_items as cart where cart.user_id = p_user_id
        order by cart.good_id, cart.variant_id, cart.id for update;
    else
      return query select cart.id, cart.good_id, cart.variant_id, cart.qty, cart.input_revision, cart.input_values
        from public.cart_items as cart where cart.user_id = p_user_id;
    end if;
    return;
  end if;
  select draft.* into v_draft from private.checkout_drafts as draft
  where draft.id = v_setting::uuid and draft.user_id = p_user_id;
  if not found then
    raise check_violation using message = 'checkout_draft_unavailable';
  end if;
  if v_draft.source = 'selection' then
    if p_lock then
      return query select cart.id, cart.good_id, cart.variant_id, cart.qty, cart.input_revision, cart.input_values
        from public.cart_items as cart
        where cart.user_id = p_user_id
          and cart.id in (select (line ->> 'cartItemId')::uuid from pg_catalog.jsonb_array_elements(v_draft.lines) as line)
        order by cart.good_id, cart.variant_id, cart.id for update;
    else
      return query select cart.id, cart.good_id, cart.variant_id, cart.qty, cart.input_revision, cart.input_values
        from public.cart_items as cart
        where cart.user_id = p_user_id
          and cart.id in (select (line ->> 'cartItemId')::uuid from pg_catalog.jsonb_array_elements(v_draft.lines) as line);
    end if;
    return;
  end if;
  return query select null::uuid, line ->> 'goodId', (line ->> 'variantId')::uuid, (line ->> 'qty')::integer,
      (line ->> 'inputRevision')::integer, line -> 'inputValues'
    from pg_catalog.jsonb_array_elements(v_draft.lines) as line;
end;
$$

-- 주문이 쓸 쿠폰. 장바구니·선택 주문은 지금처럼 장바구니 쿠폰 선택(한 장), 바로구매는 주문서에서 고른 쿠폰이다.
create function private.checkout_source_coupon(p_user_id uuid)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_setting text := coalesce(pg_catalog.current_setting('icons.checkout_draft', true), '');
  v_draft private.checkout_drafts%rowtype;
begin
  if v_setting <> '' then
    select draft.* into v_draft from private.checkout_drafts as draft
    where draft.id = v_setting::uuid and draft.user_id = p_user_id;
    if not found then
      raise check_violation using message = 'checkout_draft_unavailable';
    end if;
    if v_draft.source = 'direct' then
      return v_draft.user_coupon_id;
    end if;
  end if;
  return (select selection.user_coupon_id from public.cart_coupon_selections as selection where selection.user_id = p_user_id);
end;
$$

-- ── legacy 주문 코어·래퍼: 장바구니 직접 읽기를 원본 함수로 바꾼다 ───────────────────
do $$
declare
  v_definition text;
  v_anchor record;
begin
  v_definition := pg_catalog.pg_get_functiondef('private.place_order_before_shipments(jsonb,uuid,public.order_payment_method)'::regprocedure);
  for v_anchor in
    select * from (values
      (1, E'    join (select distinct good_id from public.cart_items where user_id=v_user) selected on selected.good_id=good.id',
          E'    join (select distinct source.good_id from private.checkout_source_lines(v_user,false) as source) selected on selected.good_id=good.id'),
      (2, E'      cart.id as cart_item_id,',
          E'      cart.cart_item_id,'),
      (3, E'    from public.cart_items as cart\n    join public.goods as good on good.id = cart.good_id\n    where cart.user_id = v_user\n    order by cart.good_id, cart.variant_id, cart.id\n    for update of cart',
          E'    -- 주문 줄 원본(ADR-0030): 장바구니 전체·선택 줄·바로구매 초안. 장바구니 행은 원본 함수가 이 순서로 잠근다.\n    from private.checkout_source_lines(v_user,true) as cart\n    join public.goods as good on good.id = cart.good_id\n    order by cart.good_id, cart.variant_id, cart.cart_item_id'),
      (4, E'      select sum(qty::bigint) into v_good_qty from public.cart_items where user_id=v_user and good_id=r.good_id;',
          E'      select sum(source.qty::bigint) into v_good_qty from private.checkout_source_lines(v_user,false) as source where source.good_id=r.good_id;'),
      (5, E'  select selection.user_coupon_id\n  into v_selected_coupon\n  from public.cart_coupon_selections as selection\n  where selection.user_id = v_user;',
          E'  -- 장바구니·선택 주문은 장바구니 쿠폰 선택, 바로구매는 주문서에서 고른 쿠폰이다(ADR-0030).\n  v_selected_coupon := private.checkout_source_coupon(v_user);')
    ) as anchors(position, anchor, replacement)
    order by position
  loop
    if (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_anchor.anchor, ''))) / pg_catalog.length(v_anchor.anchor) <> 1 then
      raise exception 'checkout_source_place_order_anchor_changed: %', v_anchor.position;
    end if;
    v_definition := pg_catalog.replace(v_definition, v_anchor.anchor, v_anchor.replacement);
  end loop;
  execute v_definition;

  v_definition := pg_catalog.pg_get_functiondef('public.place_order(jsonb,uuid,public.order_payment_method)'::regprocedure);
  for v_anchor in
    select * from (values
      (1, 'exists(select 1 from public.cart_items cart join private.goods_aggregation_members family on family.good_id=cart.good_id where cart.user_id=auth.uid())',
          'exists(select 1 from private.checkout_source_lines(auth.uid(),false) cart join private.goods_aggregation_members family on family.good_id=cart.good_id)'),
      (2, 'exists(select 1 from public.cart_items c join private.shipping_charge_group_assignments a on a.owner_good_id=private.goods_aggregation_owner(c.good_id) and a.group_id is not null where c.user_id=auth.uid())',
          'exists(select 1 from private.checkout_source_lines(auth.uid(),false) c join private.shipping_charge_group_assignments a on a.owner_good_id=private.goods_aggregation_owner(c.good_id) and a.group_id is not null)')
    ) as anchors(position, anchor, replacement)
    order by position
  loop
    if (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_anchor.anchor, ''))) / pg_catalog.length(v_anchor.anchor) <> 1 then
      raise exception 'checkout_source_place_order_wrapper_anchor_changed: %', v_anchor.position;
    end if;
    v_definition := pg_catalog.replace(v_definition, v_anchor.anchor, v_anchor.replacement);
  end loop;
  execute v_definition;
end;
$$

-- ── 보류: 주문에 들어간 줄을 그대로 받는다 ─────────────────────────────────────────
-- record_cart_order_hold(장바구니 전체)는 옛 진입점이 그대로 쓴다. 선택 주문은 선택 줄만 넘긴다.
create function private.record_checkout_order_hold(p_order_id uuid, p_user_id uuid, p_source text, p_lines jsonb)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.orders as o
    where o.id = p_order_id and o.user_id = p_user_id
      and o.status = 'pending' and o.payment_method = 'card'
  ) then
    raise check_violation using message = 'cart_order_hold_order_invalid';
  end if;
  if pg_catalog.jsonb_typeof(p_lines) is distinct from 'array' or pg_catalog.jsonb_array_length(p_lines) = 0 then
    raise check_violation using message = 'cart_order_hold_empty';
  end if;
  insert into private.cart_order_holds (order_id, user_id, source, lines)
  values (p_order_id, p_user_id, p_source, p_lines)
  on conflict (order_id) do nothing;
end;
$$

-- 주문 진입점의 초안 확인(계정 advisory 안에서 부른다 — 같은 초안의 두 탭 제출은 이 잠금에서 차례로 온다).
-- 이 초안으로 만든 이전 주문이 있으면 그 주문 행을 먼저 잠근다(p_lock — 계정 advisory → 주문 → account-action, supersede·
-- finalizer와 같은 방향). 그래서 결제 확정이 진행 중이면 그 트랜잭션이 끝난 뒤의 상태로 판정한다. 그 주문이 무통장 접수·결제
-- 완료 이후면 PT409 checkout_draft_used, 결제가 아직 확정되지 않았으면(승인 확인 중·리스가 지난 confirming·결과 불명 등)
-- PT409 checkout_payment_in_progress로 거절한다(detail = 그 주문 id, 화면이 그 주문으로 안내한다). 이렇게 해야 같은 초안에서
-- supersede가 그 주문을 떼어 내고 새 주문을 만들지 못하고, 정산된 이전 주문의 order_id도 덮이지 않는다. 초안이 없거나
-- 만료됐으면 PT409 checkout_draft_expired. 견적(p_lock = false)은 잠그지 않고 지금 확정된 상태로 같은 판정을 한다.
create function private.checkout_draft_for_order(p_user_id uuid, p_draft_id uuid, p_source text, p_lock boolean)
returns private.checkout_drafts
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_draft private.checkout_drafts%rowtype;
begin
  select draft.* into v_draft from private.checkout_drafts as draft
  where draft.id = p_draft_id and draft.user_id = p_user_id and draft.source = p_source;
  if not found then
    raise sqlstate 'PT409' using message = 'checkout_draft_expired';
  end if;
  if v_draft.order_id is not null then
    if p_lock then
      perform 1 from public.orders as o where o.id = v_draft.order_id for update;
    end if;
    if private.checkout_draft_order_settled(v_draft.order_id) then
      raise sqlstate 'PT409' using message = 'checkout_draft_used', detail = v_draft.order_id::text;
    end if;
    if private.checkout_draft_order_payment_unresolved(v_draft.order_id) then
      raise sqlstate 'PT409' using message = 'checkout_payment_in_progress', detail = v_draft.order_id::text;
    end if;
  end if;
  if v_draft.scrubbed_at is not null or v_draft.expires_at <= pg_catalog.clock_timestamp() then
    raise sqlstate 'PT409' using message = 'checkout_draft_expired';
  end if;
  return v_draft;
end;
$$

-- 결제 없이 끝난 장바구니 주문의 '다시 결제하기'(ADR-0026 retry_from_cart). 그 주문의 보류 줄 가운데 아직 장바구니에
-- 있는 줄(옵션·직접입력값 기준, 수량은 지금 장바구니 값)로 선택 초안을 만든다 — 선택 주문을 다시 결제할 때
-- 고르지 않았던 줄이 주문서에 끼어들지 않는다. 남은 줄이 없거나 장바구니 주문이 아니면 null.
create function public.service_create_checkout_retry_draft(p_user_id uuid, p_order_id uuid)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_hold private.cart_order_holds%rowtype;
  v_lines jsonb;
  v_draft uuid;
begin
  if p_user_id is null or p_order_id is null then
    raise invalid_parameter_value using message = 'invalid_checkout_retry';
  end if;
  perform private.assert_active_user(p_user_id);
  select hold.* into v_hold from private.cart_order_holds as hold
  where hold.order_id = p_order_id and hold.user_id = p_user_id
    and hold.source in ('legacy_checkout', 'cart_transaction')
    and (hold.state = 'awaiting_payment' or (hold.state = 'released' and hold.release_reason <> 'detached'));
  if not found then
    return null;
  end if;
  select jsonb_agg(jsonb_build_object('cartItemId', cart.id, 'goodId', cart.good_id, 'variantId', cart.variant_id,
      'qty', cart.qty, 'inputRevision', cart.input_revision, 'inputValues', cart.input_values, 'inputSnapshot', cart.input_snapshot)
      order by cart.good_id, cart.variant_id, cart.input_key)
    into v_lines
  from public.cart_items as cart
  where cart.user_id = p_user_id
    and exists (select 1 from jsonb_array_elements(v_hold.lines) as line
      where (line ->> 'variantId')::uuid = cart.variant_id and line ->> 'inputKey' = cart.input_key);
  if v_lines is null then
    return null;
  end if;
  perform private.trim_checkout_drafts(p_user_id);
  insert into private.checkout_drafts (user_id, source, lines, expires_at)
  values (p_user_id, 'selection', v_lines, pg_catalog.clock_timestamp() + private.checkout_draft_ttl())
  returning id into v_draft;
  return v_draft;
end;
$$

-- ── 선택 주문 진입점 ─────────────────────────────────────────────────────────────
create function public.place_order_with_cart_selection(
  p_user_id uuid, p_draft_id uuid, p_address jsonb, p_checkout_key uuid,
  p_payment_method public.order_payment_method, p_store_credit_amount bigint, p_expected_user_coupon_id uuid
) returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_draft private.checkout_drafts%rowtype;
  v_hold_lines jsonb;
  v_matched integer;
  placed uuid;
begin
  if p_user_id is null or p_checkout_key is null or p_draft_id is null then
    raise invalid_parameter_value using message = 'invalid_checkout_selection';
  end if;
  -- 주문 생성·쿠폰 선택과 같은 계정 잠금. 같은 키 재요청은 지금 장바구니·초안을 보지 않고 원래 주문을 돌려준다.
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));
  if exists (select 1 from public.orders where user_id = p_user_id and checkout_key = p_checkout_key) then
    return public.place_order_with_store_credits(p_user_id, p_address, p_checkout_key, p_payment_method, p_store_credit_amount, p_expected_user_coupon_id);
  end if;
  -- 이 초안으로 만든 주문을 먼저 잠근 뒤, 이미 무통장 접수·결제 완료면 새 키의 재제출(다른 탭·뒤로 가기)을 PT409
  -- checkout_draft_used로, 결제가 아직 확정되지 않았으면 PT409 checkout_payment_in_progress로 거절한다.
  v_draft := private.checkout_draft_for_order(p_user_id, p_draft_id, 'selection', true);
  -- 이전 미결제 주문의 재고·쿠폰·적립금·구매 한도를 먼저 돌려준다(ADR-0026, 출처 무관).
  perform private.supersede_unpaid_cart_orders(p_user_id, true);
  -- 주문 → account-action → 장바구니 순서. 새 주문 INSERT의 계정 fence도 같은 키를 다시 잡는다.
  perform private.lock_account_action_subject(p_user_id);
  perform pg_advisory_xact_lock(hashtextextended('cart:' || p_user_id::text, 0));
  -- 고른 장바구니 행을 id 순으로 잠그고, 초안의 줄과 정확히 같은지 본다(수량·직접입력값까지).
  perform 1 from public.cart_items as cart
  where cart.user_id = p_user_id
    and cart.id in (select (line ->> 'cartItemId')::uuid from jsonb_array_elements(v_draft.lines) as line)
  order by cart.id
  for update;
  select count(*),
    coalesce(jsonb_agg(jsonb_build_object('goodId', cart.good_id, 'variantId', cart.variant_id, 'inputKey', cart.input_key,
      'inputRevision', cart.input_revision, 'inputValues', cart.input_values, 'qty', cart.qty)
      order by cart.good_id, cart.variant_id, cart.input_key), '[]'::jsonb)
    into v_matched, v_hold_lines
  from public.cart_items as cart
  join jsonb_array_elements(v_draft.lines) as line on (line ->> 'cartItemId')::uuid = cart.id
  where cart.user_id = p_user_id
    and cart.good_id = line ->> 'goodId' and cart.variant_id = (line ->> 'variantId')::uuid
    and cart.qty = (line ->> 'qty')::integer and cart.input_revision = (line ->> 'inputRevision')::integer
    and cart.input_values = line -> 'inputValues';
  if v_matched <> jsonb_array_length(v_draft.lines) then
    raise sqlstate 'PT409' using message = 'cart_snapshot_changed';
  end if;
  if p_payment_method = 'card' then perform set_config('icons.cart_order_retention', 'on', true); end if;
  perform set_config('icons.checkout_draft', p_draft_id::text, true);
  placed := public.place_order_with_store_credits(p_user_id, p_address, p_checkout_key, p_payment_method, p_store_credit_amount, p_expected_user_coupon_id);
  perform set_config('icons.checkout_draft', '', true);
  perform set_config('icons.cart_order_retention', '', true);
  update private.checkout_drafts set order_id = placed where id = p_draft_id;
  -- 카드는 결제 확정 때 장바구니에서 뺀다(ADR-0026). 보류 줄 = 고른 줄이라 고르지 않은 줄은 결제 뒤에도 남는다.
  if p_payment_method = 'card' then
    perform private.record_checkout_order_hold(placed, p_user_id, 'legacy_checkout', v_hold_lines);
  end if;
  return placed;
end;
$$

-- ── 고른 품목 기준 쿠폰·적립금 견적 ───────────────────────────────────────────────
-- quote_selected_coupon(장바구니 쿠폰 선택)과 같은 모양으로 쿠폰 한 장을 평가한다. 쿠폰이 없으면 null.
create function private.quote_user_coupon(p_user_coupon_id uuid, p_lines jsonb, p_subtotal bigint, p_shipping_fee bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare actor uuid := (select auth.uid()); lines jsonb; evaluated record; discount bigint;
begin
  if actor is null or p_user_coupon_id is null then return null; end if;
  -- 배송비 쿠폰은 legacy 주문서가 받지 않는다(장바구니 선택 RPC와 같은 거절).
  if exists (select 1 from public.user_coupons as held join public.coupons as c on c.code = held.coupon_code
    where held.id = p_user_coupon_id and c.benefit_kind = 'shipping') then
    return jsonb_build_object('userCouponId', p_user_coupon_id, 'couponCode', '', 'eligibleSubtotal', 0, 'discount', 0, 'reason', 'coupon_checkout_required');
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('good_id', line ->> 'goodId', 'subtotal', (line ->> 'qty')::bigint * (line ->> 'effectivePrice')::bigint)), '[]')
    into lines from jsonb_array_elements(p_lines) as line;
  select * into evaluated from private.evaluate_coupon_target_lines(p_user_coupon_id, actor, lines, null);
  discount := case when evaluated.o_reason is null then least(evaluated.o_discount, greatest(0, p_subtotal + p_shipping_fee - 1000)) else 0 end;
  return jsonb_build_object('userCouponId', p_user_coupon_id, 'couponCode', coalesce(evaluated.o_coupon_code, ''),
    'eligibleSubtotal', evaluated.o_eligible_subtotal, 'discount', discount,
    'reason', case when evaluated.o_reason is null and discount = 0 then 'coupon_no_discount' else evaluated.o_reason end);
end;
$$

-- store_credit_checkout_quote(장바구니 전체)와 같은 판정을 넘겨받은 품목으로 한다. p_cart_coupon이면 장바구니 쿠폰
-- 선택(선택 주문), 아니면 p_user_coupon_id(바로구매 주문서에서 고른 쿠폰)로 쿠폰 할인을 뺀다.
create function private.store_credit_checkout_quote_for_items(
  p_requested_amount bigint, p_destination jsonb, p_items jsonb, p_cart_coupon boolean, p_user_coupon_id uuid
) returns jsonb
language plpgsql
set search_path = ''
as $$
declare actor uuid := (select auth.uid()); policy private.store_credit_policy; balance jsonb; sales jsonb;
  subtotal bigint; shipping bigint; coupon_quote jsonb; coupon bigint := 0; maximum bigint := 0; reason text;
begin
  if actor is null then raise insufficient_privilege using message = 'auth_required'; end if;
  if p_requested_amount is null or p_requested_amount not between 0 and 999999999999 then
    raise invalid_parameter_value using message = 'store_credit_amount_invalid'; end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 19239 or p_cart_coupon is null then
    raise invalid_parameter_value using message = 'invalid_store_credit_items'; end if;
  select * into policy from private.store_credit_policy where singleton;
  perform private.expire_store_credit_lots(actor, clock_timestamp()); balance := private.store_credit_balance(actor);
  if not policy.enabled then reason := 'store_credit_disabled';
  elsif (balance ->> 'debt')::bigint > 0 then reason := 'store_credit_debt';
  else
    sales := public.quote_goods_sales_for_address(p_items, p_destination);
    subtotal := (sales ->> 'subtotal')::bigint; shipping := (sales -> 'shipping' ->> 'totalFee')::bigint;
    coupon_quote := case when p_cart_coupon then sales -> 'coupon' else private.quote_user_coupon(p_user_coupon_id, sales -> 'lines', subtotal, shipping) end;
    if not (sales -> 'shipping' ->> 'checkoutAllowed')::boolean then reason := 'shipping_region_unresolved';
    elsif coupon_quote ->> 'reason' is not null then reason := coupon_quote ->> 'reason';
    else coupon := coalesce((coupon_quote ->> 'discount')::bigint, 0); end if;
    if reason is null then
      maximum := least(policy.max_use, (balance ->> 'available')::bigint, greatest(0, subtotal - coupon), greatest(0, subtotal + shipping - coupon - 1000));
      if p_requested_amount > 0 and (p_requested_amount < policy.min_use or p_requested_amount > maximum) then reason := 'store_credit_amount_invalid'; end if;
    end if;
  end if;
  return balance || jsonb_build_object('enabled', policy.enabled, 'minUse', policy.min_use, 'maxUse', maximum,
    'requestedAmount', p_requested_amount, 'valid', p_requested_amount = 0 or reason is null, 'reason', reason);
end;
$$

-- pg_cron이 있는 배포만 등록한다. cron.schedule은 이름 기준 upsert라 재적용에 안전하다. 일회용 복제본은 cron이 없다.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('checkout-draft-cleanup', '*/10 * * * *', 'select public.purge_expired_checkout_drafts(10000)');
  end if;
end;
$$

-- 바로구매 줄은 장바구니 행이 아니다. 보류 줄은 감사·다시 구매 판단용이고 결제 확정 정산은 장바구니를 건드리지 않는다.
create function private.record_direct_order_hold(p_order_id uuid, p_user_id uuid, p_source text, p_lines jsonb, p_base_good_id text)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
begin
  if p_source not in ('direct_checkout', 'direct_transaction') or nullif(btrim(p_base_good_id), '') is null then
    raise invalid_parameter_value using message = 'direct_order_hold_invalid';
  end if;
  if not exists (
    select 1 from public.orders as o
    where o.id = p_order_id and o.user_id = p_user_id
      and o.status = 'pending' and o.payment_method = 'card'
  ) then
    raise check_violation using message = 'cart_order_hold_order_invalid';
  end if;
  if pg_catalog.jsonb_typeof(p_lines) is distinct from 'array' or pg_catalog.jsonb_array_length(p_lines) = 0 then
    raise check_violation using message = 'cart_order_hold_empty';
  end if;
  insert into private.cart_order_holds (order_id, user_id, source, lines, base_good_id)
  values (p_order_id, p_user_id, p_source,
    (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('goodId', line ->> 'goodId', 'variantId', line ->> 'variantId',
        'inputKey', case when (line ->> 'inputRevision')::integer = 0 and line -> 'inputValues' = '{}'::jsonb then ''
          else pg_catalog.md5((line ->> 'inputRevision') || ':' || (line -> 'inputValues')::text) end,
        'inputRevision', (line ->> 'inputRevision')::integer, 'inputValues', line -> 'inputValues', 'qty', (line ->> 'qty')::integer)
        order by position)
      from pg_catalog.jsonb_array_elements(p_lines) with ordinality as entries(line, position)),
    p_base_good_id)
  on conflict (order_id) do nothing;
end;
$$

-- 결제 확정 정산: 바로구매 보류는 장바구니 줄을 건너뛰고(장바구니 효과 없음) 쓴 쿠폰의 장바구니 선택만 정리한다.
do $$
declare
  v_definition text;
  v_anchor text := E'    for v_line in select value from pg_catalog.jsonb_array_elements(v_hold.lines) loop';
begin
  v_definition := pg_catalog.pg_get_functiondef('private.settle_cart_order_hold()'::regprocedure);
  if (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_anchor, ''))) / pg_catalog.length(v_anchor) <> 1 then
    raise exception 'direct_order_settle_anchor_changed';
  end if;
  v_definition := pg_catalog.replace(v_definition, v_anchor,
    E'    -- 바로구매 보류(ADR-0030)는 장바구니 줄을 건너뛴다 — 장바구니를 읽지도 바꾸지도 않은 주문이다.\n'
    || E'    for v_line in select value from pg_catalog.jsonb_array_elements(case when v_hold.source in (''direct_checkout'', ''direct_transaction'') then ''[]''::jsonb else v_hold.lines end) loop');
  execute v_definition;
end;
$$

-- ── 이전 미결제 주문 닫기: 출처 범위 ───────────────────────────────────────────────
-- 20261027120000 supersede_unpaid_cart_orders의 본문에 닫을 출처(p_sources, null = 모두)와 계기(p_trigger)를 더했다.
-- 잠금 순서(계정 advisory → 대상 주문 행 → account-action)와 닫기 판정은 그대로다.
create function private.supersede_unpaid_checkout_orders(p_user_id uuid, p_new_order boolean, p_sources text[], p_trigger text)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  r record;
  v_result text;
  v_closed integer := 0;
  v_reason text;
begin
  if p_user_id is null or p_new_order is null
    or p_trigger is null or p_trigger not in ('new_cart_order', 'returned_to_cart', 'new_direct_order', 'customer_released') then
    raise invalid_parameter_value using message = 'cart_order_supersede_invalid';
  end if;
  v_reason := case p_trigger
    when 'new_cart_order' then '같은 장바구니로 새 주문을 만들어 결제 대기 주문 자동 취소'
    when 'returned_to_cart' then '장바구니로 돌아와 결제 대기 주문 자동 취소'
    when 'new_direct_order' then '바로구매로 새 주문을 만들어 결제 대기 주문 자동 취소'
    else '고객이 진행 중인 미결제 주문을 취소하고 주문을 계속함' end;
  perform 1
  from public.orders as o
  join private.cart_order_holds as hold on hold.order_id = o.id
  where hold.user_id = p_user_id and hold.state = 'awaiting_payment'
    and (p_sources is null or hold.source = any (p_sources))
  order by o.id
  for update of o;
  if not found then
    return 0;
  end if;
  perform private.lock_account_action_subject(p_user_id);
  for r in
    select hold.order_id
    from private.cart_order_holds as hold
    where hold.user_id = p_user_id and hold.state = 'awaiting_payment'
      and (p_sources is null or hold.source = any (p_sources))
    order by hold.created_at, hold.order_id
  loop
    v_result := private.close_unpaid_cart_order(r.order_id, v_reason, p_trigger);
    if v_result = 'closed' then
      v_closed := v_closed + 1;
    elsif v_result = 'payment_confirming' and p_new_order then
      -- detail = 승인 확인 중인 주문. 주문서가 '결제 확인 중인 주문이 있어요'와 그 주문으로 안내한다.
      raise sqlstate 'PT409' using message = 'checkout_payment_in_progress', detail = r.order_id::text;
    elsif v_result = 'unresolved' and p_new_order then
      update private.cart_order_holds
      set state = 'released', settled_at = pg_catalog.clock_timestamp(), release_reason = 'detached'
      where order_id = r.order_id and state = 'awaiting_payment';
      insert into public.audit_log (actor_id, action, target, diff)
      values (null, 'system.order.cart_hold_detached', 'order:' || r.order_id::text,
        pg_catalog.jsonb_build_object('trigger', p_trigger, 'actor', 'system'));
    end if;
  end loop;
  return v_closed;
end;
$$

-- 고객이 확인창에서 본 결제 대기 주문을 확인한 뒤에만 부른다(서버가 로그인 사용자로만 부른다 — 주문서·장바구니를 열기만
-- 해서는 다른 탭의 결제창을 끊지 않는다). 견적이 결제 대기 주문의 쿠폰·첫구매 예약·구매 한도·재고 때문에 막혔을 때 고객이
-- 고른 주문(p_order_ids — 확인창에 보인 주문, 출처 무관)만 ADR-0026 닫기 경로로 닫는다. 확인창 뒤에 새로 생긴 주문은 닫지
-- 않는다. 잠금 순서는 supersede와 같다(계정 advisory → 대상 주문 행 → account-action). 결제 승인을 확인 중이거나 결과를
-- 알 수 없는 주문은 닫지 않고 confirming으로 센다(새 주문의 checkout_payment_in_progress 거절과 같은 판단).
create function public.release_unpaid_checkout_orders(p_user_id uuid, p_order_ids uuid[])
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  r record;
  v_result text;
  v_released integer := 0;
  v_confirming integer := 0;
begin
  if p_user_id is null or p_order_ids is null or pg_catalog.cardinality(p_order_ids) not between 1 and 20
    or pg_catalog.array_position(p_order_ids, null) is not null then
    raise invalid_parameter_value using message = 'cart_order_supersede_invalid';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text, 0));
  perform 1
  from public.orders as o
  join private.cart_order_holds as hold on hold.order_id = o.id
  where hold.user_id = p_user_id and hold.state = 'awaiting_payment' and o.id = any (p_order_ids)
  order by o.id
  for update of o;
  if found then
    perform private.lock_account_action_subject(p_user_id);
    for r in
      select hold.order_id
      from private.cart_order_holds as hold
      where hold.user_id = p_user_id and hold.state = 'awaiting_payment' and hold.order_id = any (p_order_ids)
      order by hold.created_at, hold.order_id
    loop
      v_result := private.close_unpaid_cart_order(r.order_id, '고객이 진행 중인 미결제 주문을 취소하고 주문을 계속함', 'customer_released');
      if v_result = 'closed' then
        v_released := v_released + 1;
      elsif v_result in ('payment_confirming', 'unresolved') then
        v_confirming := v_confirming + 1;
      end if;
    end loop;
  end if;
  return pg_catalog.jsonb_build_object('released', v_released, 'confirming', v_confirming);
end;
$$

-- ── 바로구매 초안 ─────────────────────────────────────────────────────────────────

create function public.service_create_checkout_direct_draft(p_user_id uuid, p_base_good_id text, p_lines jsonb)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  item record;
  v_variant uuid;
  v_key text;
  v_seen text[] := '{}';
  v_snapshot jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_draft uuid;
begin
  if p_user_id is null or nullif(btrim(p_base_good_id), '') is null
    or jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) not between 1 and 51
    or exists (
      select 1 from jsonb_array_elements(p_lines) as line
      where jsonb_typeof(line) <> 'object' or not line ?& array['good_id', 'variant_id', 'qty']
        or exists (select 1 from jsonb_object_keys(line) as key where key not in ('good_id', 'variant_id', 'qty', 'input_revision', 'input_values'))
        or jsonb_typeof(line -> 'good_id') <> 'string' or nullif(btrim(line ->> 'good_id'), '') is null
        or jsonb_typeof(line -> 'variant_id') <> 'string'
        or line ->> 'variant_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(line -> 'qty') <> 'number' or line ->> 'qty' !~ '^[1-9][0-9]{0,8}$'
        or (line ? 'input_revision' and (jsonb_typeof(line -> 'input_revision') <> 'number' or line ->> 'input_revision' !~ '^(0|[1-9][0-9]*)$'))
        or (line ? 'input_values' and jsonb_typeof(line -> 'input_values') <> 'object')
    )
    or not exists (select 1 from jsonb_array_elements(p_lines) as line where line ->> 'good_id' = p_base_good_id)
  then
    raise invalid_parameter_value using message = 'invalid_checkout_direct';
  end if;
  perform private.assert_active_user(p_user_id);
  for item in
    select line ->> 'good_id' as good_id, (line ->> 'variant_id')::uuid as variant_id, (line ->> 'qty')::integer as qty,
      coalesce((line ->> 'input_revision')::integer, 0) as input_revision, coalesce(line -> 'input_values', '{}'::jsonb) as input_values,
      position
    from jsonb_array_elements(p_lines) with ordinality as entries(line, position)
    order by position
  loop
    -- 랜덤 판매 굿즈(D5②)는 장바구니 키(기본 옵션)로 모은다. 배정은 주문 생성이 한다.
    v_variant := private.cart_variant_key(item.good_id, item.variant_id);
    v_key := v_variant::text || ':' || case when item.input_revision = 0 and item.input_values = '{}'::jsonb then ''
      else md5(item.input_revision::text || ':' || item.input_values::text) end;
    if v_key = any (v_seen) then
      raise invalid_parameter_value using message = 'invalid_checkout_direct';
    end if;
    v_seen := array_append(v_seen, v_key);
    -- 담기(add_cart_selection)와 같은 규칙: 본품은 판매 중(19금은 인증 성인만), 추가 구성은 연결된 일반 굿즈만.
    if item.good_id = p_base_good_id then
      if not private.goods_selection_base_available(item.good_id, p_user_id) then
        if exists (select 1 from public.goods as good where good.id = item.good_id and good.sale_restriction = 'adult')
          and not private.adult_verification_valid(p_user_id) then
          raise check_violation using message = 'adult_verification_required';
        end if;
        raise check_violation using message = 'catalog_item_unavailable';
      end if;
    elsif not exists (select 1 from private.goods_additional_links as link where link.base_good_id = p_base_good_id and link.target_good_id = item.good_id)
      or not private.goods_additional_available(item.good_id) then
      raise check_violation using message = 'additional_good_unavailable';
    end if;
    if not exists (
      select 1 from public.goods_variants as variant
      where variant.id = v_variant and variant.good_id = item.good_id and variant.archived_at is null
    ) then
      raise check_violation using message = 'catalog_item_unavailable';
    end if;
    v_snapshot := private.resolve_goods_custom_inputs(item.good_id, item.input_revision, item.input_values);
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('goodId', item.good_id, 'variantId', v_variant, 'qty', item.qty,
      'inputRevision', item.input_revision, 'inputValues', item.input_values, 'inputSnapshot', v_snapshot));
  end loop;
  perform private.trim_checkout_drafts(p_user_id);
  insert into private.checkout_drafts (user_id, source, base_good_id, lines, expires_at)
  values (p_user_id, 'direct', p_base_good_id, v_lines, pg_catalog.clock_timestamp() + private.checkout_draft_ttl())
  returning id into v_draft;
  return v_draft;
end;
$$

-- 바로구매 결제가 승인 전에 끝난 주문을 닫는다 — '다시 구매하기'와 '이 주문 닫고 굿즈 상세에서 다시 고르기'의 공용 판정.
-- 잠금 순서는 계정 advisory → 주문 행 → account-action → profiles다(close_unpaid_cart_order가 주문 행부터 잠그고, 취소 전이의
-- 등급 재계산이 profiles를 FOR UPDATE로 잡는다 — 결제 확정과 같은 방향). 그래서 정지 계정 확인은 profiles를 잠그지 않는 단순
-- 조회로 맨 앞에서 한다(assert_active_user의 FOR SHARE를 advisory보다 먼저 잡으면 다른 탭의 새 주문·결제 확정과 교착한다).
-- 초안을 만드는 service_create_checkout_direct_draft가 assert_active_user로 다시 막는다. 반환: closed(닫았거나 이미 결제 없이
-- 취소됨) | payment_in_progress(승인 확인 중·결과 불명 — 닫지 않는다) | not_retryable(결제가 끝났거나 아직 결제할 수 있는 주문이
-- 아니다). 이 계정의 바로구매 주문이 아니면 null. 닫는 감사 기록의 trigger는 고객 동작(customer_released)이다.
create function private.close_direct_order_for_retry(p_user_id uuid, p_order_id uuid)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_hold private.cart_order_holds%rowtype;
  v_result text;
  v_status public.order_status;
  v_suspended_at timestamptz;
begin
  if p_user_id is null or p_order_id is null then
    raise invalid_parameter_value using message = 'invalid_checkout_retry';
  end if;
  select profile.suspended_at into v_suspended_at from public.profiles as profile where profile.id = p_user_id;
  if not found then
    raise exception 'profile_not_found' using errcode = '22023';
  end if;
  if v_suspended_at is not null then
    raise exception 'account_suspended' using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text, 0));
  select hold.* into v_hold from private.cart_order_holds as hold
  where hold.order_id = p_order_id and hold.user_id = p_user_id and hold.source in ('direct_checkout', 'direct_transaction');
  if not found then
    return null;
  end if;
  if v_hold.state = 'awaiting_payment' then
    v_result := private.close_unpaid_cart_order(p_order_id, '고객이 진행 중인 미결제 주문을 취소하고 주문을 계속함', 'customer_released');
    if v_result in ('payment_confirming', 'unresolved') then
      return 'payment_in_progress';
    end if;
  end if;
  select o.status into v_status from public.orders as o where o.id = p_order_id;
  if v_status = 'pending' and private.checkout_draft_order_payment_unresolved(p_order_id) then
    return 'payment_in_progress';
  end if;
  return case when v_status = 'canceled' then 'closed' else 'not_retryable' end;
end;
$$

-- 바로구매 결제가 승인 전에 끝난 주문의 '다시 구매하기'(ADR-0030 확정 동작 8). 그 주문을 닫아 재고·쿠폰·적립금·첫구매 예약·
-- 구매 한도를 돌려준 뒤, 같은 줄(옵션·수량·추가 구성·직접입력값)로 바로구매 초안을 다시 만든다 — 고객은 굿즈 상세에서 다시
-- 고르지 않고 주문서로 간다(장바구니는 읽지도 바꾸지도 않는다). 본인 결제 대기 주문이 그 굿즈 재고를 잡고 있어 상세가 품절로
-- 보이던 문제도 함께 풀린다.
-- 같은 주문의 다시 구매는 한 번이다(두 탭·뒤로 가기): 그 주문에 연결된 다시 구매 초안(retry_order_id)이 살아 있으면 그 초안을
-- 돌려주고, 그 초안이 이미 무통장 접수·결제 완료 주문을 만들었으면 not_retryable(orderId = 그 주문), 그 주문의 결제를 확인하고
-- 있으면 payment_in_progress(orderId = 그 주문)다. 초안이 만료됐으면 연결을 풀고 새로 만든다. 두 호출은 계정 advisory에서
-- 차례로 오므로 초안은 하나다(부분 유일 색인이 한 번 더 막는다).
-- 반환: {"result":"draft","draftId"} | {"result":"payment_in_progress"[,"orderId"]} | {"result":"not_retryable"[,"orderId"]}
--      | {"result":"unavailable","baseGoodId","reason"}(닫았지만 지금 같은 줄로 초안을 만들 수 없다 — 굿즈 상세에서 다시
--      고른다). 이 계정의 바로구매 주문이 아니면 null.
create function public.service_retry_direct_order(p_user_id uuid, p_order_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_result text;
  v_hold private.cart_order_holds%rowtype;
  v_existing private.checkout_drafts%rowtype;
  v_lines jsonb;
  v_draft uuid;
begin
  v_result := private.close_direct_order_for_retry(p_user_id, p_order_id);
  if v_result is null then
    return null;
  end if;
  if v_result <> 'closed' then
    return pg_catalog.jsonb_build_object('result', v_result);
  end if;
  select draft.* into v_existing from private.checkout_drafts as draft
  where draft.retry_order_id = p_order_id and draft.user_id = p_user_id
  for update;
  if found then
    if v_existing.order_id is not null and private.checkout_draft_order_settled(v_existing.order_id) then
      return pg_catalog.jsonb_build_object('result', 'not_retryable', 'orderId', v_existing.order_id);
    end if;
    if v_existing.order_id is not null and private.checkout_draft_order_payment_unresolved(v_existing.order_id) then
      return pg_catalog.jsonb_build_object('result', 'payment_in_progress', 'orderId', v_existing.order_id);
    end if;
    if v_existing.scrubbed_at is null and v_existing.expires_at > pg_catalog.clock_timestamp() then
      return pg_catalog.jsonb_build_object('result', 'draft', 'draftId', v_existing.id);
    end if;
    update private.checkout_drafts set retry_order_id = null where id = v_existing.id;
  end if;
  select hold.* into v_hold from private.cart_order_holds as hold where hold.order_id = p_order_id;
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('good_id', line ->> 'goodId', 'variant_id', line ->> 'variantId',
      'qty', (line ->> 'qty')::integer, 'input_revision', coalesce((line ->> 'inputRevision')::integer, 0),
      'input_values', coalesce(line -> 'inputValues', '{}'::jsonb)) order by position)
    into v_lines
  from pg_catalog.jsonb_array_elements(v_hold.lines) with ordinality as entries(line, position);
  -- 닫기는 남기고 초안만 되돌린다 — 지금 같은 줄을 살 수 없으면(판매 중지·옵션 정리·직접입력 설정 변경·성인 인증) 굿즈 상세로.
  begin
    v_draft := public.service_create_checkout_direct_draft(p_user_id, v_hold.base_good_id, v_lines);
  exception when check_violation or invalid_parameter_value then
    return pg_catalog.jsonb_build_object('result', 'unavailable', 'baseGoodId', v_hold.base_good_id, 'reason', sqlerrm);
  end;
  update private.checkout_drafts set retry_order_id = p_order_id where id = v_draft;
  return pg_catalog.jsonb_build_object('result', 'draft', 'draftId', v_draft);
end;
$$

-- '이 주문 닫고 굿즈 상세에서 다시 고르기': 같은 닫기만 하고 초안은 만들지 않는다 — 마지막 재고를 잡은 본인 주문 때문에 상세가
-- 품절로 보이지 않게, 상세로 가기 전에 닫는다. 반환은 {"result":"closed"|"payment_in_progress"|"not_retryable","baseGoodId"}.
-- 이 계정의 바로구매 주문이 아니면 null.
create function public.service_close_direct_order(p_user_id uuid, p_order_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_result text;
begin
  v_result := private.close_direct_order_for_retry(p_user_id, p_order_id);
  if v_result is null then
    return null;
  end if;
  return pg_catalog.jsonb_build_object('result', v_result, 'baseGoodId',
    (select hold.base_good_id from private.cart_order_holds as hold where hold.order_id = p_order_id));
end;
$$

-- ── 바로구매 주문서 견적: 주문서에서 고른 쿠폰 ─────────────────────────────────────
create function public.quote_goods_sales_for_address_with_coupon(items jsonb, destination jsonb, p_user_coupon_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare quote jsonb;
begin
  quote := public.quote_goods_sales_for_address(items, destination);
  return quote || jsonb_build_object('coupon', private.quote_user_coupon(p_user_coupon_id, quote -> 'lines',
    (quote ->> 'subtotal')::bigint, (quote -> 'shipping' ->> 'totalFee')::bigint));
end;
$$

-- ── 바로구매 주문 진입점 ─────────────────────────────────────────────────────────────
create function public.place_direct_order(
  p_user_id uuid, p_draft_id uuid, p_address jsonb, p_checkout_key uuid,
  p_payment_method public.order_payment_method, p_store_credit_amount bigint, p_user_coupon_id uuid
) returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_draft private.checkout_drafts%rowtype;
  placed uuid;
begin
  if p_user_id is null or p_checkout_key is null or p_draft_id is null then
    raise invalid_parameter_value using message = 'invalid_checkout_direct';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));
  -- 같은 키 재요청은 초안·장바구니를 다시 보지 않고 원래 주문(쓴 쿠폰까지)을 돌려준다.
  if exists (select 1 from public.orders where user_id = p_user_id and checkout_key = p_checkout_key) then
    return public.place_order_with_store_credits(p_user_id, p_address, p_checkout_key, p_payment_method, p_store_credit_amount, p_user_coupon_id);
  end if;
  -- 이 초안으로 만든 주문을 먼저 잠근 뒤, 이미 무통장 접수·결제 완료면 새 키의 재제출(다른 탭·뒤로 가기)을 PT409
  -- checkout_draft_used로, 결제가 아직 확정되지 않았으면(승인 확인 중·결과 불명) PT409 checkout_payment_in_progress로
  -- 거절한다. 승인 전에 끝난 카드 미결제 주문이면 아래 supersede가 그 주문을 닫고 새 주문을 만든다.
  v_draft := private.checkout_draft_for_order(p_user_id, p_draft_id, 'direct', true);
  -- 배송비 쿠폰은 legacy 주문서가 받지 않는다(장바구니 쿠폰 선택과 같은 거절).
  if p_user_coupon_id is not null and exists (
    select 1 from public.user_coupons as held join public.coupons as c on c.code = held.coupon_code
    where held.id = p_user_coupon_id and c.benefit_kind = 'shipping'
  ) then
    raise check_violation using message = 'coupon_checkout_required';
  end if;
  -- 이전 미결제 주문(장바구니·바로구매 모두)의 재고·쿠폰·적립금·첫구매 예약·구매 한도를 먼저 돌려준다(ADR-0026·0030).
  perform private.supersede_unpaid_checkout_orders(p_user_id, true, null, 'new_direct_order');
  perform private.lock_account_action_subject(p_user_id);
  update private.checkout_drafts set user_coupon_id = p_user_coupon_id where id = p_draft_id;
  -- 카드는 쿠폰의 장바구니 선택을 결제 확정 때 정리한다(보류). 무통장은 접수 때 코어가 같은 쿠폰 선택만 지운다.
  if p_payment_method = 'card' then perform set_config('icons.cart_order_retention', 'on', true); end if;
  perform set_config('icons.checkout_draft', p_draft_id::text, true);
  placed := public.place_order_with_store_credits(p_user_id, p_address, p_checkout_key, p_payment_method, p_store_credit_amount);
  perform set_config('icons.checkout_draft', '', true);
  perform set_config('icons.cart_order_retention', '', true);
  update private.checkout_drafts set order_id = placed where id = p_draft_id;
  if p_payment_method = 'card' then
    perform private.record_direct_order_hold(placed, p_user_id, 'direct_checkout', v_draft.lines, v_draft.base_good_id);
  end if;
  return placed;
end;
$$

-- 카드 보류 줄은 고른 줄이다(장바구니 전체가 아니다). 나머지 본문은 20261027120000 정의 그대로다.
do $$
declare
  v_definition text;
  v_anchor text := E' perform private.record_cart_order_hold(result,p_user_id,''cart_transaction'');';
begin
  v_definition := pg_catalog.pg_get_functiondef('public.place_cart_goods_transaction(uuid,jsonb,jsonb,uuid,uuid,public.order_payment_method)'::regprocedure);
  if (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_anchor, ''))) / pg_catalog.length(v_anchor) <> 1 then
    raise exception 'transaction_selection_hold_anchor_changed';
  end if;
  v_definition := pg_catalog.replace(v_definition, v_anchor,
    E' -- 보류 줄 = 고른 줄(ADR-0030). 고른 줄은 위에서 지금 장바구니와 정확히 같다고 단언했다.\n'
    || E' perform private.record_checkout_order_hold(result,p_user_id,''cart_transaction'',(select jsonb_agg(jsonb_build_object(''goodId'',cart.good_id,''variantId'',cart.variant_id,\n'
    || E'   ''inputKey'',cart.input_key,''inputRevision'',cart.input_revision,''inputValues'',cart.input_values,''qty'',cart.qty) order by cart.good_id,cart.variant_id,cart.input_key)\n'
    || E'   from public.cart_items cart where cart.user_id=p_user_id and exists(select 1 from jsonb_array_elements(selection) selected\n'
    || E'    where selected->>''goodId''=cart.good_id and (selected->>''variantId'')::uuid=cart.variant_id\n'
    || E'     and (selected->>''inputRevision'')::integer=cart.input_revision and selected->''inputValues''=cart.input_values)));');
  execute v_definition;
end;
$$

do $$
declare
  v_definition text;
  v_anchor record;
begin
  v_definition := pg_catalog.pg_get_functiondef('private.lock_goods_transaction_source(uuid,jsonb)'::regprocedure);
  for v_anchor in
    select * from (values
      (1, E'not in (''cart'',''gift'',''subscription'')', E'not in (''cart'',''gift'',''subscription'',''direct'')'),
      (2, E'if p_source->>''kind''=''cart'' and source_id<>p_actor', E'if p_source->>''kind'' in (''cart'',''direct'') and source_id<>p_actor')
    ) as anchors(position, anchor, replacement)
    order by position
  loop
    if (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_anchor.anchor, ''))) / pg_catalog.length(v_anchor.anchor) <> 1 then
      raise exception 'transaction_direct_source_anchor_changed: %', v_anchor.position;
    end if;
    v_definition := pg_catalog.replace(v_definition, v_anchor.anchor, v_anchor.replacement);
  end loop;
  execute v_definition;
end;
$$

-- 견적: 바로구매 초안 줄 + 견적에서 고른 쿠폰. 장바구니 쿠폰 선택과 비교하지 않는다.
create function public.quote_direct_goods_transaction(
  p_user_id uuid, p_draft_id uuid, p_address jsonb, p_delivery_choices jsonb, p_user_coupon_id uuid, p_store_credit_amount bigint
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare selection jsonb; source jsonb;
begin
  if p_user_id is null or p_draft_id is null then raise invalid_parameter_value using message = 'invalid_transaction_actor'; end if;
  selection := private.direct_goods_transaction_selection(p_user_id, p_draft_id, false);
  source := private.goods_direct_transaction_source(p_user_id, selection);
  return private.quote_goods_transaction(p_user_id, source, selection, p_address, p_delivery_choices, p_user_coupon_id, p_store_credit_amount);
end;
$$

create function public.quote_direct_goods_transaction_combined(
  p_user_id uuid, p_draft_id uuid, p_address jsonb, p_delivery_choices jsonb, p_user_coupon_ids uuid[], p_store_credit_amount bigint
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare selection jsonb; source jsonb;
begin
  if p_user_id is null or p_draft_id is null then raise invalid_parameter_value using message = 'invalid_transaction_actor'; end if;
  selection := private.direct_goods_transaction_selection(p_user_id, p_draft_id, false);
  source := private.goods_direct_transaction_source(p_user_id, selection);
  perform private.lock_goods_transaction_source(p_user_id, source);
  return private.quote_goods_transaction_combined(p_user_id, source, selection, p_address, p_delivery_choices, p_user_coupon_ids, p_store_credit_amount);
end;
$$

-- 주문: 계정 advisory → (같은 키면 원래 영수증) → 이전 미결제 점유 닫기(출처 무관) → 원본 잠금 → 코어.
create function public.place_direct_goods_transaction(
  p_user_id uuid, p_draft_id uuid, p_address jsonb, p_quote_id uuid, p_checkout_key uuid, p_payment_method public.order_payment_method
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare existing private.order_goods_transactions; selection jsonb; source jsonb; base_good text; draft_lines jsonb; result uuid;
begin
  if p_user_id is null or p_draft_id is null then raise invalid_parameter_value using message = 'invalid_transaction_actor'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));
  -- 같은 checkout key의 재요청은 초안(만료됐을 수 있다)을 다시 보지 않고 원래 영수증을 돌려준다.
  select * into existing from private.order_goods_transactions where actor_id = p_user_id and checkout_key = p_checkout_key;
  if found then
    if existing.source_kind <> 'direct' then raise sqlstate 'PT409' using message = 'checkout_key_conflict'; end if;
    perform private.lock_goods_transaction_actor(p_user_id);
    return (private.replay_goods_transaction_receipt(p_user_id,
      jsonb_build_object('kind', existing.source_kind, 'id', existing.source_id, 'revision', existing.source_revision),
      p_quote_id, p_checkout_key, p_payment_method) ->> 'orderId')::uuid;
  end if;
  selection := private.direct_goods_transaction_selection(p_user_id, p_draft_id, true);
  source := private.goods_direct_transaction_source(p_user_id, selection);
  select draft.base_good_id, draft.lines into base_good, draft_lines from private.checkout_drafts as draft where draft.id = p_draft_id;
  -- 이전 미결제 주문(장바구니·바로구매 모두)의 재고·쿠폰·적립금·첫구매 예약·구매 한도를 먼저 돌려준다(ADR-0026·0030).
  perform private.supersede_unpaid_checkout_orders(p_user_id, true, null, 'new_direct_order');
  perform private.lock_goods_transaction_source(p_user_id, source);
  result := private.place_goods_transaction(p_user_id, source, selection, p_address, p_quote_id, p_checkout_key, p_payment_method);
  -- 같은 초안의 재제출을 막는 연결(무통장 접수·결제 완료 뒤에는 checkout_draft_used).
  update private.checkout_drafts set order_id = result where id = p_draft_id;
  if p_payment_method = 'bank_transfer' then
    -- 무통장은 접수 = 주문 완료다. 장바구니 줄은 건드리지 않고, 이 주문이 쓴 쿠폰의 장바구니 선택만 해제한다.
    delete from public.cart_coupon_selections as selection_row
    where selection_row.user_id = p_user_id
      and selection_row.user_coupon_id in (select redemption.user_coupon_id from public.coupon_redemptions as redemption
        where redemption.order_id = result and redemption.status = 'applied');
  else
    -- 카드는 장바구니 효과 없는 보류를 남긴다(다음 주문이 이 미결제 점유를 닫는 색인, 결제 확정 때 쿠폰 선택만 정리).
    perform private.record_direct_order_hold(result, p_user_id, 'direct_transaction', draft_lines, base_good);
  end if;
  return result;
end;
$$

-- 복구: 같은 키로 만든 주문이 있으면 그 영수증, 없으면(그리고 새 결제가 허용되면) 견적의 배송지로 다시 주문한다.
create function public.resume_direct_goods_transaction(
  p_user_id uuid, p_draft_id uuid, p_quote_id uuid, p_checkout_key uuid, p_payment_method public.order_payment_method, p_allow_new boolean default false
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare existing private.order_goods_transactions; quoted private.goods_transaction_quotes;
begin
  if p_user_id is null then raise invalid_parameter_value using message = 'invalid_transaction_actor'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));
  if p_quote_id is null or p_checkout_key is null or p_payment_method is null or p_allow_new is null then
    raise invalid_parameter_value using message = 'invalid_transaction_resume'; end if;
  select * into existing from private.order_goods_transactions where actor_id = p_user_id and checkout_key = p_checkout_key;
  if found then
    perform private.lock_goods_transaction_actor(p_user_id);
    if existing.source_kind <> 'direct' then raise sqlstate 'PT409' using message = 'checkout_key_conflict'; end if;
    return (private.replay_goods_transaction_receipt(p_user_id,
      jsonb_build_object('kind', existing.source_kind, 'id', existing.source_id, 'revision', existing.source_revision),
      p_quote_id, p_checkout_key, p_payment_method) ->> 'orderId')::uuid;
  end if;
  if not p_allow_new then raise check_violation using message = 'transaction_new_payment_disabled'; end if;
  select * into quoted from private.goods_transaction_quotes where id = p_quote_id and actor_id = p_user_id;
  if not found or quoted.source ->> 'kind' <> 'direct' or quoted.source ->> 'id' <> p_user_id::text then
    raise sqlstate 'PT409' using message = 'transaction_quote_expired'; end if;
  return public.place_direct_goods_transaction(p_user_id, p_draft_id, quoted.address, p_quote_id, p_checkout_key, p_payment_method);
end;
$$

-- 시도 한도. 숫자는 런북(docs/runbooks/signup-contact-channels.md)과 같아야 한다.
create function private.member_phone_rate_limited(p_column text, p_value text, p_hour_limit integer, p_day_limit integer)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  hour_count integer;
  day_count integer;
  oldest timestamptz;
  now_at timestamptz := clock_timestamp();
begin
  if p_value is null then return null; end if;
  if p_column = 'user' then
    select count(*) filter (where c.created_at > now_at - interval '1 hour'), count(*)
      into hour_count, day_count
      from private.member_phone_verification_challenges c
      where c.user_id = p_value::uuid and c.created_at > now_at - interval '24 hours';
  elsif p_column = 'phone' then
    select count(*) filter (where c.created_at > now_at - interval '1 hour'), count(*)
      into hour_count, day_count
      from private.member_phone_verification_challenges c
      where c.phone_digest = p_value and c.created_at > now_at - interval '24 hours';
  elsif p_column = 'ip' then
    select count(*) filter (where c.created_at > now_at - interval '1 hour'), count(*)
      into hour_count, day_count
      from private.member_phone_verification_challenges c
      where c.ip_digest = p_value and c.created_at > now_at - interval '24 hours';
  else
    raise invalid_parameter_value using message = 'member_phone_rate_column';
  end if;

  if day_count >= p_day_limit then
    select min(c.created_at) into oldest from private.member_phone_verification_challenges c
      where c.created_at > now_at - interval '24 hours'
        and ((p_column = 'user' and c.user_id = p_value::uuid)
          or (p_column = 'phone' and c.phone_digest = p_value)
          or (p_column = 'ip' and c.ip_digest = p_value));
    return greatest(1, ceil(extract(epoch from (oldest + interval '24 hours' - now_at)))::integer);
  end if;
  if hour_count >= p_hour_limit then
    select min(c.created_at) into oldest from private.member_phone_verification_challenges c
      where c.created_at > now_at - interval '1 hour'
        and ((p_column = 'user' and c.user_id = p_value::uuid)
          or (p_column = 'phone' and c.phone_digest = p_value)
          or (p_column = 'ip' and c.ip_digest = p_value));
    return greatest(1, ceil(extract(epoch from (oldest + interval '1 hour' - now_at)))::integer);
  end if;
  return null;
end;
$$

-- 인증번호 발송 전에 요청을 기록한다. 한도·재발송 간격을 넘으면 기록하지 않고 거절한다.
-- 같은 회원의 진행 중 요청은 새 요청이 대신한다(superseded) — 가장 최근 문자의 번호만 맞는다.
create function public.service_issue_member_phone_verification(
  p_challenge_id uuid,
  p_user_id uuid,
  p_phone_e164 text,
  p_phone_digest text,
  p_ip_digest text,
  p_code_digest text,
  p_ttl_seconds integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  now_at timestamptz;
  retry_after integer;
  last_at timestamptz;
  profile_suspended timestamptz;
begin
  if p_challenge_id is null or p_user_id is null
    or p_phone_e164 is null or p_phone_e164 !~ '^\+[1-9][0-9]{6,14}$'
    or p_phone_digest is null or p_phone_digest !~ '^[A-Za-z0-9_-]{32,128}$'
    or (p_ip_digest is not null and p_ip_digest !~ '^[A-Za-z0-9_-]{32,128}$')
    or p_code_digest is null or p_code_digest !~ '^[A-Za-z0-9_-]{32,128}$'
    or p_ttl_seconds is null or p_ttl_seconds not between 60 and 900 then
    raise invalid_parameter_value using message = 'invalid_member_phone_verification';
  end if;

  if private.is_account_write_fenced(p_user_id) then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-phone:user:' || p_user_id::text, 0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-phone:number:' || p_phone_digest, 0));

  select p.suspended_at into profile_suspended from public.profiles p where p.id = p_user_id;
  if not found or profile_suspended is not null then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  -- 동의·만 14세 확인 전에는 번호를 받지 않는다(요청 행도 남기지 않는다).
  if not private.member_phone_onboarding_ready(p_user_id) then
    return jsonb_build_object('ok', false, 'reason', 'onboarding_required');
  end if;

  if exists (select 1 from private.member_phone_verification_challenges c where c.id = p_challenge_id) then
    raise unique_violation using message = 'member_phone_verification_replayed';
  end if;

  now_at := clock_timestamp();

  -- 같은 회원이나 같은 번호로 60초 안에 다시 보내지 않는다.
  select max(c.created_at) into last_at from private.member_phone_verification_challenges c
    where (c.user_id = p_user_id or c.phone_digest = p_phone_digest) and c.created_at > now_at - interval '60 seconds';
  if last_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'cooldown',
      'retryAfterSeconds', greatest(1, ceil(extract(epoch from (last_at + interval '60 seconds' - now_at)))::integer));
  end if;

  retry_after := coalesce(
    private.member_phone_rate_limited('user', p_user_id::text, 5, 10),
    private.member_phone_rate_limited('phone', p_phone_digest, 5, 10),
    private.member_phone_rate_limited('ip', p_ip_digest, 10, 30)
  );
  if retry_after is not null then
    return jsonb_build_object('ok', false, 'reason', 'rate_limited', 'retryAfterSeconds', retry_after);
  end if;

  update private.member_phone_verification_challenges
    set status = 'superseded', resolved_at = now_at, phone_e164 = null
    where user_id = p_user_id and status = 'pending';

  insert into private.member_phone_verification_challenges (
    id, user_id, phone_e164, phone_digest, ip_digest, code_digest, status, attempts, created_at, expires_at
  ) values (
    p_challenge_id, p_user_id, p_phone_e164, p_phone_digest, p_ip_digest, p_code_digest, 'pending', 0,
    now_at, now_at + make_interval(secs => p_ttl_seconds)
  );

  return jsonb_build_object('ok', true, 'expiresAt', now_at + make_interval(secs => p_ttl_seconds));
end;
$$

-- 인증번호를 확인한다. 5번 틀리면 그 요청은 닫힌다. 맞으면 번호를 회원에게 옮겨 기록한다.
create function public.service_verify_member_phone_verification(
  p_challenge_id uuid,
  p_user_id uuid,
  p_code_digest text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  challenge private.member_phone_verification_challenges;
  peek_digest text;
  now_at timestamptz;
  released_user uuid;
begin
  if p_challenge_id is null or p_user_id is null
    or p_code_digest is null or p_code_digest !~ '^[A-Za-z0-9_-]{32,128}$' then
    raise invalid_parameter_value using message = 'invalid_member_phone_verification';
  end if;

  select c.phone_digest into peek_digest from private.member_phone_verification_challenges c
    where c.id = p_challenge_id and c.user_id = p_user_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  if private.is_account_write_fenced(p_user_id) then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-phone:user:' || p_user_id::text, 0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-phone:number:' || peek_digest, 0));

  select * into challenge from private.member_phone_verification_challenges c
    where c.id = p_challenge_id and c.user_id = p_user_id
    for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if challenge.status = 'verified' then
    return jsonb_build_object('ok', true, 'replayed', true);
  end if;
  if challenge.status <> 'pending' then
    return jsonb_build_object('ok', false, 'reason', challenge.status);
  end if;

  now_at := clock_timestamp();
  if challenge.expires_at <= now_at then
    update private.member_phone_verification_challenges
      set status = 'expired', resolved_at = now_at, phone_e164 = null
      where id = challenge.id;
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;

  if challenge.code_digest <> p_code_digest then
    if challenge.attempts + 1 >= 5 then
      update private.member_phone_verification_challenges
        set attempts = challenge.attempts + 1, status = 'exhausted', resolved_at = now_at, phone_e164 = null
        where id = challenge.id;
      return jsonb_build_object('ok', false, 'reason', 'exhausted');
    end if;
    update private.member_phone_verification_challenges
      set attempts = challenge.attempts + 1
      where id = challenge.id;
    return jsonb_build_object('ok', false, 'reason', 'mismatch', 'remainingAttempts', 5 - (challenge.attempts + 1));
  end if;

  if exists (select 1 from public.profiles p where p.id = p_user_id and p.suspended_at is not null) then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  -- 요청 뒤 동의·연령 조건이 깨졌으면 기록하지 않고 요청을 닫는다(번호 원문도 지운다).
  if not private.member_phone_onboarding_ready(p_user_id) then
    update private.member_phone_verification_challenges
      set status = 'refused', resolved_at = now_at, phone_e164 = null
      where id = challenge.id;
    return jsonb_build_object('ok', false, 'reason', 'onboarding_required');
  end if;

  -- 같은 번호를 인증해 둔 다른 계정이 있으면 번호를 옮기고, 그 계정에는 재인증 필요 표시만 남긴다.
  for released_user in
    update private.member_phone_numbers n
      set phone_e164 = null, verified_at = null, released_at = now_at, updated_at = now_at
      where n.phone_e164 = challenge.phone_e164 and n.user_id <> p_user_id
      returning n.user_id
  loop
    insert into private.member_phone_verification_events (user_id, event, phone_digest, occurred_at)
      values (released_user, 'released', challenge.phone_digest, now_at);
  end loop;

  insert into private.member_phone_numbers (user_id, phone_e164, verified_at, released_at, updated_at)
    values (p_user_id, challenge.phone_e164, now_at, null, now_at)
    on conflict (user_id) do update
      set phone_e164 = excluded.phone_e164, verified_at = excluded.verified_at, released_at = null,
        updated_at = excluded.updated_at;
  insert into private.member_phone_verification_events (user_id, event, phone_digest, occurred_at)
    values (p_user_id, 'verified', challenge.phone_digest, now_at);
  update private.member_phone_verification_challenges
    set status = 'verified', resolved_at = now_at, phone_e164 = null
    where id = challenge.id;

  return jsonb_build_object('ok', true, 'replayed', false);
end;
$$

-- 본인의 인증 상태. 온보딩·설정 화면이 서버에서 읽어 가려진 번호로 보여 주고, 스위치가 켜졌을 때 앱의 온보딩
-- 게이트가 재인증 필요(reverificationRequired)를 읽어 보호 액션 전에 다시 인증하게 한다.
create function public.my_member_phone_verification()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  actor uuid := auth.uid();
begin
  if actor is null or not exists (select 1 from public.profiles p where p.id = actor) then
    raise insufficient_privilege using message = 'member_phone_auth_required';
  end if;
  return coalesce(
    (select jsonb_build_object('verified', n.phone_e164 is not null, 'phoneE164', n.phone_e164, 'verifiedAt', n.verified_at,
       'reverificationRequired', n.phone_e164 is null and n.released_at is not null)
      from private.member_phone_numbers n where n.user_id = actor),
    jsonb_build_object('verified', false, 'phoneE164', null, 'verifiedAt', null, 'reverificationRequired', false)
  );
end;
$$

-- 탈퇴 신청(계정 봉인) 행이 생기는 트랜잭션 안에서 번호·요청 행·인증 이력을 지운다. 주소록과 같은 잠금 순서다.
create function private.erase_member_phone(p_user_id uuid)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  erased integer;
begin
  if p_user_id is null then
    raise invalid_parameter_value using message = 'member_phone_member_required';
  end if;
  perform private.lock_account_action_subject(p_user_id);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-phone:user:' || p_user_id::text, 0));
  delete from private.member_phone_numbers where user_id = p_user_id;
  get diagnostics erased = row_count;
  delete from private.member_phone_verification_challenges where user_id = p_user_id;
  delete from private.member_phone_verification_events where user_id = p_user_id;
  return erased;
end;
$$

create trigger erase_fenced_member_phone
after insert on private.account_action_fences
for each row execute function private.erase_fenced_member_phone()

-- 보관 기한. 시간이 지난 진행 중 요청은 만료로 닫으며 번호 원문을 지우고, 이틀 지난 요청 행과 1년 지난 인증·해제
-- 이력은 삭제한다. 처리방침 초안(런북)의 '요청 기록 2일·인증 이력 1년 뒤 파기'가 이 작업에 기댄다.
create function private.prune_member_phone_verification_challenges(p_limit integer default 5000)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  now_at timestamptz := clock_timestamp();
  pruned integer;
  pruned_events integer;
begin
  if p_limit is null or p_limit not between 1 and 50000 then
    raise invalid_parameter_value using message = 'invalid_member_phone_prune_limit';
  end if;
  update private.member_phone_verification_challenges
    set status = 'expired', resolved_at = now_at, phone_e164 = null
    where status = 'pending' and expires_at <= now_at;
  delete from private.member_phone_verification_challenges
    where ctid in (
      select c.ctid from private.member_phone_verification_challenges c
      where c.created_at < now_at - interval '2 days'
      order by c.created_at
      limit p_limit
    );
  get diagnostics pruned = row_count;
  delete from private.member_phone_verification_events
    where ctid in (
      select e.ctid from private.member_phone_verification_events e
      where e.occurred_at < now_at - interval '1 year'
      order by e.occurred_at
      limit p_limit
    );
  get diagnostics pruned_events = row_count;
  return pruned + pruned_events;
end;
$$

revoke all on function private.member_phone_onboarding_ready(uuid),
