-- 2) 일련번호 카운터. 종전 next_commerce_number 본문의 검증·원자적 증가를 그대로 옮겼다.
create function private.next_commerce_sequence(p_business_day date,p_kind smallint)
returns integer language plpgsql security definer set search_path='' as $$
declare n integer;
begin
  if p_business_day is null or not isfinite(p_business_day) or p_business_day not between date '2000-01-01' and date '9999-12-31'
    or p_kind is null or p_kind not in (1,2,3) then
    raise invalid_parameter_value using message='invalid_commerce_number_input';
  end if;
  insert into private.commerce_number_counters as counter(business_date,kind,last_value)
    values(p_business_day,p_kind,1)
    on conflict(business_date,kind) do update set last_value=counter.last_value+1
    returning last_value into n;
  return n;
end $$

-- 옛 형식(16자리) 발급. 결과는 종전과 같다 — 배송건번호, 전환 전 주문번호, 옛 주문의 상품주문번호가 쓴다.
create or replace function private.next_commerce_number(p_created_at timestamptz,p_kind smallint)
returns text language plpgsql security definer set search_path='' as $$
declare business_day date := (p_created_at at time zone 'Asia/Seoul')::date; n integer;
begin
  n:=private.next_commerce_sequence(business_day,p_kind);
  return to_char(business_day,'YYYYMMDD')||p_kind::text||lpad(n::text,7,'0');
end $$

-- 새 주문번호(20자리): 주문 생성 시각(KST)의 날짜·시·분 + 1 + 그날 주문 일련번호.
create function private.next_timed_order_number(p_created_at timestamptz)
returns text language plpgsql security definer set search_path='' as $$
declare local_time timestamp := p_created_at at time zone 'Asia/Seoul'; n integer;
begin
  n:=private.next_commerce_sequence(local_time::date,1::smallint);
  return to_char(local_time,'YYYYMMDDHH24MI')||'1'||lpad(n::text,7,'0');
end $$

-- 상품주문번호: 주문번호의 앞자리(옛 형식은 날짜 8자리, 새 형식은 날짜·시각 12자리) + 2 + 그날 상품주문 일련번호.
-- 주문번호에서 바로 만들므로 주문번호와 상품주문번호의 날짜·시각이 늘 같다.
create function private.next_product_order_number(p_order_number text)
returns text language plpgsql security definer set search_path='' as $$
declare prefix text; n integer;
begin
  if not coalesce(private.is_commerce_number(p_order_number,1::smallint),false) then
    raise invalid_parameter_value using message='invalid_commerce_number_input';
  end if;
  prefix:=left(p_order_number,length(p_order_number)-8);
  n:=private.next_commerce_sequence(to_date(left(prefix,8),'YYYYMMDD'),2::smallint);
  return prefix||'2'||lpad(n::text,7,'0');
end $$

-- 4) 발급 트리거. 갱신 금지·임의 번호 금지는 종전 그대로다.
create or replace function private.assign_commerce_number() returns trigger
language plpgsql security definer set search_path='' as $$
declare column_name text := tg_argv[0]; kind smallint := tg_argv[1]::smallint; created timestamptz; parent_number text; number text;
begin
  if tg_op='UPDATE' then
    if (to_jsonb(new)->>column_name) is distinct from (to_jsonb(old)->>column_name) then
      raise check_violation using message='commerce_number_immutable';
    end if;
    return new;
  end if;
  if to_jsonb(new)->>column_name is not null then
    raise check_violation using message='commerce_number_is_generated';
  end if;
  if kind=1 then
    if new.created_at>=(select s.switched_at from private.commerce_number_time_switch s where s.singleton) then
      number:=private.next_timed_order_number(new.created_at);
    else
      number:=private.next_commerce_number(new.created_at,kind);
    end if;
  else
    select o.created_at,o.order_number into strict created,parent_number from public.orders o where o.id=new.order_id;
    if kind=2 then number:=private.next_product_order_number(parent_number);
    else number:=private.next_commerce_number(created,kind);
    end if;
  end if;
  new:=jsonb_populate_record(new,jsonb_build_object(column_name,number));
  return new;
end $$

-- 7) 번호 형식을 직접 보던 읽기 함수: 운송장 입력(주문번호 → 단일 배송 건), ICONS 표준 양식 회신(상품주문번호),
--    테스트 배송완료(주문번호), 미입금 검색(주문번호 부분 일치 8~20자리). 다른 조건·권한은 바꾸지 않는다.
create function pg_temp.patch_number_reader(signature text,anchor text,replacement text) returns void language plpgsql as $$
declare definition text:=pg_get_functiondef(signature::regprocedure);
begin
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then
    raise exception 'order_number_time_anchor_changed: % / %',signature,anchor;
  end if;
  execute replace(definition,anchor,replacement);
end $$

-- 고친 함수의 운영자 계약 지문을 다시 등록한다. 권한·가드 종류는 등록된 값을 그대로 쓴다.
do $$declare signature text;fn regprocedure;contract record;begin
 foreach signature in array array[
  'private.resolve_shipment_reference(text)',
  'public.admin_import_item_tracking_batch(jsonb)',
  'public.admin_mark_staging_test_delivered(text,uuid)',
  'private.admin_unpaid_bank_transfer_orders_console_before_numbers(text,integer,integer,text,text)'
 ] loop
  fn:=signature::regprocedure;
  select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure=fn;
  if found then perform private.register_operator_rpc_contract(fn,contract.capability,contract.guard_kind,contract.legacy_admin_only); end if;
  if exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure=fn) then
   perform private.register_operator_internal_contract(fn);
  else raise exception 'order_number_time_internal_contract_missing: %',signature;
  end if;
 end loop;
end $$

-- 미리보기: 파일 행을 검사·매칭하고 그 시점의 재고수량과 실물 흐름을 기록한다. 재고는 바꾸지 않는다.
-- 기준 시각은 7일 안만 받는다 — 파일이 오래될수록 기록으로 가를 수 없는 입고·조정이 끼기 쉽다.
create function public.admin_preview_stock_reconcile(p_origin_id uuid,p_as_of timestamptz,p_source_label text,p_rows jsonb)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid;label text;snapshot uuid;resolved jsonb;matched integer;issues jsonb;variant_ids uuid[];now_at timestamptz:=clock_timestamp();
begin
  actor:=private.require_operator_capability('catalog.manage',false);
  label:=btrim(coalesce(p_source_label,''),E' \t\n\r\f\v');
  if p_as_of is null or p_as_of>now_at+interval '5 minutes' or p_as_of<now_at-interval '7 days' then
    raise invalid_parameter_value using message='invalid_stock_reconcile_as_of';
  end if;
  if char_length(label) not between 1 and 200 or label ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message='invalid_stock_reconcile_label';
  end if;
  if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 2000 then
    raise invalid_parameter_value using message='invalid_stock_reconcile_rows';
  end if;
  -- CASE로 순서를 고정한다(OR는 평가 순서를 보장하지 않아 객체가 아닌 값에 jsonb_each·형 변환이 먼저 돌 수 있다).
  if exists(select 1 from jsonb_array_elements(p_rows) x where case
      when jsonb_typeof(x) is distinct from 'object' then true
      when jsonb_typeof(x->'row') is distinct from 'number' or (x->>'row')!~'^[1-9][0-9]{0,8}$' then true
      when jsonb_typeof(x->'qty') is distinct from 'number' or (x->>'qty')!~'^(0|[1-9][0-9]{0,8})$' then true
      when (x->>'qty')::bigint>100000000 then true
      when not (x ? 'goodsCode' or x ? 'optionCode' or x ? 'erpCode' or x ? 'barcode') then true
      else exists(select 1 from jsonb_each(x) field where field.key not in ('row','qty','goodsCode','optionCode','erpCode','barcode')
        or (field.key<>'row' and field.key<>'qty' and case when jsonb_typeof(field.value) is distinct from 'string' then true
          else char_length(btrim(field.value#>>'{}')) not between 1 and 200 or (field.value#>>'{}') ~ '[[:cntrl:]]' end))
    end)
    or (select count(distinct x->>'row') from jsonb_array_elements(p_rows) x)<>jsonb_array_length(p_rows) then
    raise invalid_parameter_value using message='invalid_stock_reconcile_rows';
  end if;
  if p_origin_id is not null and not exists(select 1 from public.fulfillment_origins where id=p_origin_id) then
    raise no_data_found using message='fulfillment_origin_not_found';
  end if;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.source_row),'[]'::jsonb) into resolved
  from private.stock_reconcile_resolve(p_rows,p_origin_id) r;
  select count(*) into matched from jsonb_to_recordset(resolved) as r(issue text) where r.issue is null;
  select coalesce(jsonb_agg(jsonb_build_object('row',r.source_row,'key',r.match_key,'fileQty',r.file_qty,'reason',r.issue) order by r.source_row),'[]'::jsonb)
    into issues from jsonb_to_recordset(resolved) as r(source_row integer,match_key text,file_qty integer,issue text) where r.issue is not null;
  variant_ids:=array(select (e->>'variant_id')::uuid from jsonb_array_elements(resolved) e where e->>'issue' is null);

  insert into private.stock_reconcile_snapshots(origin_id,source_label,as_of,created_by,created_at,row_count,matched_count,issue_count,issues)
  values(p_origin_id,label,p_as_of,actor,now_at,jsonb_array_length(p_rows),matched,jsonb_array_length(issues),issues)
  returning id into snapshot;

  insert into private.stock_reconcile_snapshot_items(snapshot_id,variant_id,good_id,source_row,match_kind,file_qty,stock_qty,
    pending_qty,shipped_since_qty,returned_since_qty,awaiting_return_qty,adjusted_since_count,adjusted_since_qty,difference,target_qty)
  select snapshot,r.variant_id,v.good_id,r.source_row,r.match_kind,r.file_qty,v.stock_qty,
    f.pending_qty::integer,f.shipped_since_qty::integer,f.returned_since_qty::integer,f.awaiting_return_qty::integer,
    adj.adjusted_count,adj.adjusted_qty::integer,
    (r.file_qty::bigint-(v.stock_qty::bigint+f.pending_qty+f.awaiting_return_qty+f.shipped_since_qty-f.returned_since_qty))::integer,
    greatest(r.file_qty::bigint-f.pending_qty-f.awaiting_return_qty-f.shipped_since_qty+f.returned_since_qty,0)::integer
  from jsonb_to_recordset(resolved) as r(source_row integer,variant_id uuid,good_id text,match_kind text,file_qty integer,issue text)
  join public.goods_variants v on v.id=r.variant_id
  join private.stock_reconcile_flows(variant_ids,p_as_of) f on f.variant_id=r.variant_id
  join private.stock_reconcile_adjustments(variant_ids,p_as_of) adj on adj.variant_id=r.variant_id
  where r.issue is null;

  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.stock_reconcile.previewed','stock_reconcile:'||snapshot,
    jsonb_build_object('originId',p_origin_id,'asOf',p_as_of,'sourceLabel',label,'rows',jsonb_array_length(p_rows),
      'matched',matched,'issues',jsonb_array_length(issues)));
  return private.stock_reconcile_document(snapshot);
end $$

-- 확정: 미리보기에서 바뀌는 옵션만, 차이가 그대로일 때 한 번에 반영한다. 하나라도 달라졌으면 아무것도 바꾸지 않고
-- 달라진 옵션을 돌려준다. 같은 미리보기의 재확정은 처음 결과를 돌려준다(응답 유실 재시도).
-- 잠금 순서는 재고 조정·주문과 같다: 상품(id 순) → 옵션(id 순). 상품은 옵션의 지금 상품이다.
create function public.admin_apply_stock_reconcile(p_snapshot_id uuid,p_expected_changes integer,p_reason text)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid;reason text;snap private.stock_reconcile_snapshots;item record;conflicts jsonb:='[]'::jsonb;
  preview_changes integer;changed_ids uuid[];now_difference bigint;target bigint;delta integer;increased integer:=0;decreased integer:=0;
  shortages integer:=0;total_delta bigint:=0;result jsonb;
begin
  actor:=private.require_operator_capability('catalog.manage',false);
  reason:=btrim(coalesce(p_reason,''),E' \t\n\r\f\v');
  if p_snapshot_id is null or p_expected_changes is null or p_expected_changes<0 then
    raise invalid_parameter_value using message='invalid_stock_reconcile_apply';
  end if;
  if char_length(reason) not between 1 and 200 or reason ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message='invalid_stock_reconcile_reason';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('stock_reconcile:'||p_snapshot_id::text,0));
  select * into snap from private.stock_reconcile_snapshots where id=p_snapshot_id for update;
  if not found then raise no_data_found using message='stock_reconcile_not_found';end if;
  if snap.applied_at is not null then
    if snap.applied_by=actor and snap.apply_reason=reason and (snap.apply_result->>'expectedChanges')::integer=p_expected_changes then
      return jsonb_build_object('status','applied','replayed',true,'snapshot',private.stock_reconcile_document(snap.id));
    end if;
    raise sqlstate 'PT409' using message='stock_reconcile_already_applied';
  end if;
  if snap.created_at<clock_timestamp()-interval '24 hours' then
    raise check_violation using message='stock_reconcile_expired';
  end if;
  changed_ids:=array(select i.variant_id from private.stock_reconcile_snapshot_items i where i.snapshot_id=snap.id and i.target_qty<>i.stock_qty);
  preview_changes:=cardinality(changed_ids);
  if preview_changes<>p_expected_changes then raise sqlstate 'PT409' using message='stock_reconcile_preview_mismatch';end if;

  perform 1 from public.goods g where g.id in(select v.good_id from public.goods_variants v where v.id=any(changed_ids)) order by g.id for update;
  perform 1 from public.goods_variants v where v.id=any(changed_ids) order by v.id for update;

  for item in
    select i.*,v.good_id as current_good_id,v.stock_qty as current_stock,v.archived_at as variant_archived_at,g.archived_at as goods_archived_at,
      g.name as goods_name,v.name as option_name,v.code as option_code,f.pending_qty as now_pending,f.shipped_since_qty as now_shipped,
      f.returned_since_qty as now_returned,f.awaiting_return_qty as now_awaiting
    from private.stock_reconcile_snapshot_items i
    join public.goods_variants v on v.id=i.variant_id
    join public.goods g on g.id=v.good_id
    join private.stock_reconcile_flows(changed_ids,snap.as_of) f on f.variant_id=i.variant_id
    where i.snapshot_id=snap.id and i.target_qty<>i.stock_qty
    order by v.good_id,i.variant_id
  loop
    now_difference:=item.file_qty::bigint-(item.current_stock::bigint+item.now_pending+item.now_awaiting+item.now_shipped-item.now_returned);
    if now_difference<>item.difference or item.variant_archived_at is not null or item.goods_archived_at is not null then
      conflicts:=conflicts||jsonb_build_object('variantId',item.variant_id,'goodsName',item.goods_name,'optionName',item.option_name,
        'optionCode',item.option_code,'previewDifference',item.difference,'currentDifference',now_difference,
        'reason',case when item.goods_archived_at is not null then 'goods_archived' when item.variant_archived_at is not null then 'option_stopped' else 'changed' end);
    end if;
  end loop;
  if jsonb_array_length(conflicts)>0 then
    return jsonb_build_object('status','conflict','conflicts',conflicts);
  end if;

  for item in
    select i.*,v.good_id as current_good_id,v.stock_qty as current_stock from private.stock_reconcile_snapshot_items i
    join public.goods_variants v on v.id=i.variant_id
    where i.snapshot_id=snap.id and i.target_qty<>i.stock_qty
    order by v.good_id,i.variant_id
  loop
    target:=greatest(item.current_stock::bigint+item.difference,0);
    delta:=(target-item.current_stock)::integer;
    if delta<>0 then
      perform private.change_goods_variant_stock(item.current_good_id,item.variant_id,delta::bigint);
    end if;
    update private.stock_reconcile_snapshot_items set applied_delta=delta,stock_after=target::integer
      where snapshot_id=snap.id and variant_id=item.variant_id;
    if delta>0 then increased:=increased+1;elsif delta<0 then decreased:=decreased+1;end if;
    if item.current_stock::bigint+item.difference<0 then shortages:=shortages+1;end if;
    total_delta:=total_delta+delta;
    insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.good.stock_reconciled','goods:'||item.current_good_id,
      jsonb_build_object('snapshotId',snap.id,'variantId',item.variant_id,'from',item.current_stock,'delta',delta,'to',target,
        'fileQty',item.file_qty,'pendingQty',item.pending_qty,'shippedSinceQty',item.shipped_since_qty,
        'returnedSinceQty',item.returned_since_qty,'awaitingReturnQty',item.awaiting_return_qty,'asOf',snap.as_of,'reason',reason));
  end loop;

  result:=jsonb_build_object('expectedChanges',p_expected_changes,'changed',increased+decreased,'increased',increased,
    'decreased',decreased,'shortages',shortages,'totalDelta',total_delta);
  update private.stock_reconcile_snapshots set applied_at=clock_timestamp(),applied_by=actor,apply_reason=reason,apply_result=result
    where id=snap.id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.stock_reconcile.applied','stock_reconcile:'||snap.id,
    result||jsonb_build_object('originId',snap.origin_id,'asOf',snap.as_of,'sourceLabel',snap.source_label,'reason',reason));
  return jsonb_build_object('status','applied','replayed',false,'snapshot',private.stock_reconcile_document(snap.id));
end $$

create function public.admin_get_stock_reconcile(p_snapshot_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare document jsonb;
begin
  if not public.has_operator_capability('catalog.read',false) then raise insufficient_privilege using message='operator_capability_required';end if;
  if p_snapshot_id is null then raise invalid_parameter_value using message='invalid_stock_reconcile_snapshot';end if;
  document:=private.stock_reconcile_document(p_snapshot_id);
  if document is null then raise no_data_found using message='stock_reconcile_not_found';end if;
  return document;
end $$

-- 수신 주소: 앞뒤 공백 제거·소문자·중복 제거(처음 순서 유지). 형식이 틀리거나 상한을 넘으면 거절한다.
create function private.normalize_stock_digest_recipients(p_values text[],p_limit integer)
returns text[] language plpgsql immutable set search_path='' as $$
declare value text;normalized text[]:='{}'::text[];
begin
  if p_values is null then raise invalid_parameter_value using message='invalid_stock_digest_recipient';end if;
  foreach value in array p_values loop
    value:=lower(btrim(coalesce(value,''),E' \t\n\r\f\v'));
    if value='' then continue;end if;
    if char_length(value)>254 or value!~'^[^@[:space:][:cntrl:],;<>"]{1,64}@[^@[:space:][:cntrl:],;<>"]+\.[^@[:space:][:cntrl:],;<>".]+$' then
      raise invalid_parameter_value using message='invalid_stock_digest_recipient';
    end if;
    if not value=any(normalized) then normalized:=normalized||value;end if;
  end loop;
  if cardinality(normalized)>p_limit then raise invalid_parameter_value using message='stock_digest_recipient_limit';end if;
  return normalized;
end $$

create function public.admin_get_stock_safety_digest()
returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
  if not public.has_operator_capability('platform.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
  return private.stock_safety_digest_document(clock_timestamp());
end $$

create function public.admin_save_stock_safety_digest(p_enabled boolean,p_send_time text,p_operator_recipients text[],
  p_expected_revision bigint,p_operation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid;previous private.stock_safety_digest_settings;recipients text[];request jsonb;receipt jsonb;at_value timestamptz;
begin
  actor:=private.require_operator_capability('platform.manage',false);
  if p_enabled is null or p_send_time is null or p_send_time!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'
    or p_expected_revision is null or p_expected_revision<1 or p_operation_id is null then
    raise invalid_parameter_value using message='invalid_stock_safety_digest';
  end if;
  recipients:=private.normalize_stock_digest_recipients(p_operator_recipients,10);
  request:=jsonb_build_object('enabled',p_enabled,'sendTime',p_send_time,'operatorRecipients',to_jsonb(recipients),
    'expectedRevision',p_expected_revision);
  perform pg_advisory_xact_lock(hashtextextended('stock-safety-digest-operation:'||p_operation_id::text,0));
  receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.stock_safety_digest.settings',request);
  if receipt is not null then return receipt;end if;
  select * into previous from private.stock_safety_digest_settings where singleton for update;
  if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='stock_safety_digest_changed';end if;
  at_value:=clock_timestamp();
  update private.stock_safety_digest_settings set revision=revision+1,enabled=p_enabled,send_time=p_send_time::time,
    operator_recipients=recipients,enabled_at=case when p_enabled and not previous.enabled then at_value
      when p_enabled then previous.enabled_at else null end,
    updated_by=actor,updated_at=at_value where singleton;
  receipt:=private.stock_safety_digest_document(at_value);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.stock_safety_digest.settings','stock_safety_digest',
    jsonb_build_object('request',request,'before',jsonb_build_object('enabled',previous.enabled,'sendTime',to_char(previous.send_time,'HH24:MI'),
      'operatorRecipients',to_jsonb(previous.operator_recipients)),'result',receipt));
  return receipt;
end $$

-- 출고지 담당자 주소. 처음 저장할 때 기대 버전은 0이다.
create function public.admin_save_stock_safety_digest_origin(p_origin_id uuid,p_recipients text[],p_expected_revision bigint,p_operation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid;previous private.stock_safety_digest_origin_recipients;recipients text[];request jsonb;receipt jsonb;at_value timestamptz;
begin
  actor:=private.require_operator_capability('platform.manage',false);
  if p_origin_id is null or p_expected_revision is null or p_expected_revision<0 or p_operation_id is null then
    raise invalid_parameter_value using message='invalid_stock_safety_digest_origin';
  end if;
  recipients:=private.normalize_stock_digest_recipients(p_recipients,5);
  request:=jsonb_build_object('originId',p_origin_id,'recipients',to_jsonb(recipients),'expectedRevision',p_expected_revision);
  perform pg_advisory_xact_lock(hashtextextended('stock-safety-digest-operation:'||p_operation_id::text,0));
  receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.stock_safety_digest.origin',request);
  if receipt is not null then return receipt;end if;
  perform 1 from public.fulfillment_origins where id=p_origin_id for share;
  if not found then raise no_data_found using message='fulfillment_origin_not_found';end if;
  perform pg_advisory_xact_lock(hashtextextended('stock-safety-digest-origin:'||p_origin_id::text,0));
  select * into previous from private.stock_safety_digest_origin_recipients where origin_id=p_origin_id for update;
  if coalesce(previous.revision,0)<>p_expected_revision then raise sqlstate 'PT409' using message='stock_safety_digest_changed';end if;
  at_value:=clock_timestamp();
  insert into private.stock_safety_digest_origin_recipients(origin_id,revision,recipients,updated_by,updated_at)
    values(p_origin_id,1,recipients,actor,at_value)
    on conflict(origin_id) do update set revision=private.stock_safety_digest_origin_recipients.revision+1,
      recipients=excluded.recipients,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
  receipt:=(select e.value from jsonb_array_elements(private.stock_safety_digest_document(at_value)->'origins') e
    where e.value->>'originId'=p_origin_id::text);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.stock_safety_digest.origin',
    'fulfillment_origin:'||p_origin_id,jsonb_build_object('request',request,
      'before',jsonb_build_object('recipients',coalesce(to_jsonb(previous.recipients),'[]'::jsonb)),'result',receipt));
  return receipt;
end $$

-- 그날 실행을 만든다. 켜져 있고 설정 시각(KST)이 지났고 그날 실행이 없을 때만. 대상 옵션이 없거나
-- 수신 주소가 없으면 발송 행 없이 실행만 남긴다(같은 날 다시 만들지 않는다).
-- 출고지 담당자 주소는 주소마다 묶는다: 한 주소가 여러 출고지의 담당자면 대상 옵션이 있는 출고지들을 한 통에 싣는다.
-- 운영자 주소에도 있으면 전체 목록 한 통으로 충분하다.
create function private.prepare_stock_safety_digest(p_now timestamptz)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare s private.stock_safety_digest_settings;today date;due timestamptz;items jsonb;recipient text;target record;
  delivered text[]:='{}'::text[];deliveries integer:=0;
begin
  if p_now is null then raise invalid_parameter_value using message='invalid_stock_safety_digest_run';end if;
  select * into s from private.stock_safety_digest_settings where singleton;
  if not found or not s.enabled then return jsonb_build_object('status','disabled');end if;
  today:=(p_now at time zone 'Asia/Seoul')::date;
  due:=(today+s.send_time) at time zone 'Asia/Seoul';
  if p_now<due then return jsonb_build_object('status','before_time','dueAt',due);end if;
  if exists(select 1 from private.stock_safety_digest_runs where digest_date=today) then
    return jsonb_build_object('status','already_prepared','digestDate',today);
  end if;
  -- 동시 틱을 직렬화하고 설정 변경과 겹치지 않게 한다.
  perform pg_advisory_xact_lock(hashtextextended('stock-safety-digest-prepare',0));
  select * into s from private.stock_safety_digest_settings where singleton for share;
  if not s.enabled then return jsonb_build_object('status','disabled');end if;
  if exists(select 1 from private.stock_safety_digest_runs where digest_date=today) then
    return jsonb_build_object('status','already_prepared','digestDate',today);
  end if;
  items:=private.stock_safety_digest_items();
  insert into private.stock_safety_digest_runs(digest_date,settings_revision,send_time,item_count,items)
    values(today,s.revision,s.send_time,jsonb_array_length(items),items);
  if jsonb_array_length(items)>0 then
    foreach recipient in array s.operator_recipients loop
      insert into private.stock_safety_digest_deliveries(digest_date,audience,recipient,item_count)
        values(today,'operator',recipient,jsonb_array_length(items));
      delivered:=delivered||recipient;deliveries:=deliveries+1;
    end loop;
    for target in
      select contact.address,array_agg(o.id order by o.name,o.id) as origin_ids,array_agg(o.name order by o.name,o.id) as origin_names
      from private.stock_safety_digest_origin_recipients r
      join public.fulfillment_origins o on o.id=r.origin_id
      cross join unnest(r.recipients) as contact(address)
      where exists(select 1 from jsonb_array_elements(items) i where i->>'originId'=o.id::text)
        and not contact.address=any(delivered)
      group by contact.address
      order by min(o.name),contact.address
    loop
      insert into private.stock_safety_digest_deliveries(digest_date,audience,origin_ids,origin_names,recipient,item_count)
        values(today,'origin',target.origin_ids,target.origin_names,target.address,
          (select count(*) from jsonb_array_elements(items) i where i->>'originId'=any(target.origin_ids::text[])));
      deliveries:=deliveries+1;
    end loop;
  end if;
  update private.stock_safety_digest_runs set delivery_count=deliveries where digest_date=today;
  insert into public.audit_log(actor_id,action,target,diff) values(null,'system.stock_safety_digest.prepared','stock_safety_digest:'||today,
    jsonb_build_object('digestDate',today,'settingsRevision',s.revision,'items',jsonb_array_length(items),'deliveries',deliveries));
  return jsonb_build_object('status','prepared','digestDate',today,'items',jsonb_array_length(items),'deliveries',deliveries);
end $$

create function public.claim_stock_safety_digest_jobs(batch_limit integer default 25)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare result jsonb;
begin
  if batch_limit is null or batch_limit not between 1 and 25 then raise invalid_parameter_value using message='invalid_stock_digest_batch';end if;
  perform private.prepare_stock_safety_digest(clock_timestamp());
  -- 꺼져 있으면 새로 선점하지 않는다. 하루가 지난 대기 요약은 보내지 않는다(다음 날 요약이 대신한다).
  -- 결과 불명(unknown)은 공급사가 받았을 수 있어 만료시키지 않고 dispatcher의 24시간 검토 경계를 따른다.
  if not coalesce((select enabled from private.stock_safety_digest_settings where singleton),false) then return '[]'::jsonb;end if;
  update private.stock_safety_digest_deliveries d set email_status='failed',error_code='digest_expired',retryable=false,
    available_at=null,lease_until=null,claim_token=null,updated_at=clock_timestamp()
    from private.stock_safety_digest_runs r
    where r.digest_date=d.digest_date and d.email_status='queued' and r.created_at<clock_timestamp()-interval '20 hours';
  update private.stock_safety_digest_deliveries set email_status='unknown',error_code='delivery_needs_review',retryable=false,
    available_at=null,lease_until=null,claim_token=null,updated_at=clock_timestamp()
    where email_status in ('queued','processing','unknown') and attempts>=100 and (lease_until is null or lease_until<clock_timestamp());
  with selected as (
    select d.id from private.stock_safety_digest_deliveries d
    where d.attempts<100 and ((d.email_status in ('queued','unknown') and d.available_at<=clock_timestamp())
      or (d.email_status='processing' and d.lease_until<clock_timestamp()))
    order by d.available_at nulls last,d.id for update skip locked limit batch_limit
  ), claimed as (
    update private.stock_safety_digest_deliveries d set email_status='processing',claim_token=extensions.gen_random_uuid(),
      lease_until=clock_timestamp()+interval '10 minutes',attempts=attempts+1,updated_at=clock_timestamp()
    from selected where d.id=selected.id returning d.*
  )
  select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'claimToken',c.claim_token,'audience',c.audience,'originNames',to_jsonb(c.origin_names),
      'digestDate',c.digest_date,'recipient',c.recipient,'itemCount',c.item_count,
      'items',private.stock_safety_digest_job_items(c.digest_date,c.origin_ids)) order by c.id),'[]'::jsonb)
    into result from claimed c;
  return result;
end $$

create function public.bind_stock_safety_digest_intent(target_id uuid,target_claim uuid,target_intent uuid)
returns boolean language plpgsql volatile security definer set search_path='' as $$
declare d private.stock_safety_digest_deliveries%rowtype;i private.email_intents%rowtype;
begin
  select * into d from private.stock_safety_digest_deliveries where id=target_id for update;
  if not found or d.email_status<>'processing' or d.claim_token is distinct from target_claim or d.lease_until<=clock_timestamp() then return false;end if;
  select * into i from private.email_intents where id=target_intent for update;
  if not found or i.source<>'stock_safety_digest' or i.message_kind<>'stock_safety_digest' or i.content_revision<>'stock_safety_digest_v1'
    or (d.email_intent_id is not null and d.email_intent_id<>i.id) then raise check_violation using message='stock_digest_intent_mismatch';end if;
  update private.stock_safety_digest_deliveries set email_intent_id=i.id where id=d.id;
  return true;
end $$

create function public.finish_stock_safety_digest_job(target_id uuid,target_claim uuid,target_status text,target_error text,target_retryable boolean)
returns boolean language plpgsql volatile security definer set search_path='' as $$
declare d private.stock_safety_digest_deliveries%rowtype;i private.email_intents%rowtype;status text:=target_status;code text:=target_error;can_retry boolean:=target_retryable;
begin
  if target_status is null or target_status not in ('sent','queued','failed','unknown','suppressed') or target_retryable is null
    or target_error is not null and target_error not in ('provider_suppressed','provider_rejected','delivery_disabled','delivery_in_progress',
      'delivery_needs_review','delivery_outcome_unknown','provider_retryable','provider_not_configured')
  then raise invalid_parameter_value using message='invalid_stock_digest_result';end if;
  select * into d from private.stock_safety_digest_deliveries where id=target_id for update;
  if not found or d.email_status<>'processing' or d.claim_token is distinct from target_claim then return false;end if;
  select * into i from private.email_intents where id=d.email_intent_id for update;
  -- 공급사 수락이 커밋됐으면 응답 유실과 무관하게 그 결과가 이긴다.
  if i.state in ('accepted','sent','delivered','delayed') then status:='sent';code:=null;can_retry:=false;
  elsif i.state in ('bounced','complained','failed') then status:='failed';code:='provider_rejected';can_retry:=false;
  elsif i.state='suppressed' then status:='suppressed';code:='provider_suppressed';can_retry:=false;
  elsif i.state='needs_review' then status:='unknown';code:='delivery_needs_review';can_retry:=false;
  elsif status='sent' then raise check_violation using message='stock_digest_acceptance_required';
  end if;
  if status='failed' and can_retry then
    -- 재시도 가능한 실패(공급사 일시 오류·발송 설정 대기)는 10분 뒤 다시 줄을 선다. 하루가 지나면 선점 단계가 만료시킨다.
    update private.stock_safety_digest_deliveries set email_status='queued',error_code=code,retryable=true,
      available_at=clock_timestamp()+interval '10 minutes',claim_token=null,lease_until=null,updated_at=clock_timestamp()
      where id=d.id;
  else
    update private.stock_safety_digest_deliveries set email_status=status,error_code=code,retryable=false,
      available_at=case when status='queued' or (status='unknown' and code='delivery_outcome_unknown')
        then clock_timestamp()+interval '2 minutes' end,
      claim_token=null,lease_until=null,updated_at=clock_timestamp()
      where id=d.id;
  end if;
  return true;
end $$

-- #191 dispatcher에 새 출처를 더한다. 다른 출처 목록이 늘어 있어도 끝에 덧붙이고, 앵커가 정확히 한 번
-- 나오지 않으면 실패한다(조용히 덮어쓰지 않는다).
do $$
declare spec record;definition text;anchor text:='''::text])';
begin
  for spec in select * from (values
    ('private.email_intents','email_intents_source_check'),
    ('private.email_intents','email_intents_message_kind_check'),
    ('private.email_intent_fences','email_intent_fences_source_check')) supplied(table_name,constraint_name) loop
    select pg_get_constraintdef(c.oid) into definition from pg_constraint c
      where c.conrelid=spec.table_name::regclass and c.conname=spec.constraint_name;
    if definition is null or position('stock_safety_digest' in definition)>0
      or (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then
      raise exception 'stock digest email constraint changed: %',spec.constraint_name;
    end if;
    execute format('alter table %s drop constraint %I',spec.table_name,spec.constraint_name);
    execute format('alter table %s add constraint %I %s',spec.table_name,spec.constraint_name,
      replace(definition,anchor,'''::text, ''stock_safety_digest''::text])'));
  end loop;
end $$

do $patch$
declare target record;definition text;patch record;
begin
  for target in select * from (values
    ('public.enqueue_email_intent(text,text,text,text,text)'),
    ('public.claim_email_intent_dispatch(uuid,text)')) supplied(signature) loop
    definition:=pg_get_functiondef(target.signature::regprocedure);
    for patch in select * from (values
      ('public.enqueue_email_intent(text,text,text,text,text)','source_list',
        $old$) then raise check_violation using message='invalid_email_source'$old$,
        $new$,'stock_safety_digest') then raise check_violation using message='invalid_email_source'$new$),
      ('public.enqueue_email_intent(text,text,text,text,text)','kind_list',
        E')\n then raise check_violation using message=''invalid_email_message_kind''',
        E',''stock_safety_digest'')\n then raise check_violation using message=''invalid_email_message_kind'''),
      ('public.enqueue_email_intent(text,text,text,text,text)','kind_pair',
        ' if target_content_revision is null',
        E' if (target_source=''stock_safety_digest'') is distinct from (target_message_kind=''stock_safety_digest'') then raise check_violation using message=''invalid_email_message_kind'';end if;\n if target_content_revision is null'),
      -- 주문 지연 안내와 같은 방식의 전용 gate: 안전재고 요약 메일 설정의 '사용'.
      ('public.claim_email_intent_dispatch(uuid,text)','digest_gate',
        ' else v_control.enabled end',
        ' when v_intent.source=''stock_safety_digest'' then coalesce((select d.enabled from private.stock_safety_digest_settings d where d.singleton),false) else v_control.enabled end')
    ) supplied(signature,name,old_text,new_text) where supplied.signature=target.signature loop
      if (length(definition)-length(replace(definition,patch.old_text,'')))/length(patch.old_text)<>1 then
        raise exception 'stock digest dispatcher anchor changed: %',patch.name;
      end if;
      definition:=replace(definition,patch.old_text,patch.new_text);
    end loop;
    execute definition;
  end loop;
end $patch$

-- 재정의한 함수의 운영자 계약을 새 본문·ACL로 다시 등록한다(등록돼 있지 않으면 아무것도 하지 않는다).
do $$declare fn regprocedure;contract record;begin
  foreach fn in array array['public.enqueue_email_intent(text,text,text,text,text)'::regprocedure,
    'public.claim_email_intent_dispatch(uuid,text)'::regprocedure] loop
    select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure=fn;
    if found then perform private.register_operator_rpc_contract(fn,contract.capability,contract.guard_kind,contract.legacy_admin_only);
    elsif exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure=fn) then
      perform private.register_operator_internal_contract(fn);
    end if;
  end loop;
end $$

-- 2. 요청 검증·가격 계산 -----------------------------------------------------------------------------------------------
create function private.discount_promotion_validate(p_request jsonb) returns void
language plpgsql stable set search_path='' as $$
declare kind text; ids jsonb; rule jsonb; starts timestamptz; ends timestamptz; item jsonb; id_pattern text;
begin
  if jsonb_typeof(p_request) is distinct from 'object'
    or not p_request ?& array['name','startsAt','endsAt','target','rule','exceptions'] or (select count(*) from jsonb_object_keys(p_request))<>6
    or jsonb_typeof(p_request->'name') is distinct from 'string' or p_request->>'name'<>btrim(p_request->>'name')
    or char_length(p_request->>'name') not between 1 and 60 or p_request->>'name' ~ '[[:cntrl:]]'
    or jsonb_typeof(p_request->'target') is distinct from 'object'
    or not (p_request->'target') ?& array['kind','ids'] or (select count(*) from jsonb_object_keys(p_request->'target'))<>2
    or jsonb_typeof(p_request#>'{target,kind}') is distinct from 'string' or p_request#>>'{target,kind}' not in ('campaign','ip','goods')
    or jsonb_typeof(p_request#>'{target,ids}') is distinct from 'array'
    or jsonb_typeof(p_request->'rule') is distinct from 'object' or jsonb_typeof(p_request->'exceptions') is distinct from 'array'
    or jsonb_typeof(p_request->'startsAt') is distinct from 'string' or jsonb_typeof(p_request->'endsAt') is distinct from 'string'
    or p_request->>'startsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' or p_request->>'endsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' then
    raise invalid_parameter_value using message='discount_promotion_invalid';
  end if;
  kind:=p_request#>>'{target,kind}'; ids:=p_request#>'{target,ids}';
  id_pattern:=case kind when 'campaign' then '^[a-z0-9][a-z0-9-]{1,63}$' when 'ip' then '^[a-z0-9][a-z0-9-]{0,99}$' else '^[a-z0-9][a-z0-9-]{0,63}$' end;
  if (kind in ('campaign','ip') and jsonb_array_length(ids)<>1) or (kind='goods' and jsonb_array_length(ids) not between 1 and 1000)
    or exists(select 1 from jsonb_array_elements(ids) value where jsonb_typeof(value)<>'string' or value#>>'{}' !~ id_pattern)
    or (select count(distinct value) from jsonb_array_elements(ids) value)<>jsonb_array_length(ids) then
    raise invalid_parameter_value using message='discount_promotion_invalid';
  end if;
  begin
    starts:=(p_request->>'startsAt')::timestamptz; ends:=(p_request->>'endsAt')::timestamptz;
  exception when others then raise invalid_parameter_value using message='discount_promotion_invalid';
  end;
  if not isfinite(starts) or not isfinite(ends) or starts>=ends then raise invalid_parameter_value using message='discount_promotion_invalid'; end if;
  -- 일괄 규칙은 율·금액만, 예외는 율·금액·예외가(기준 판매가의 할인 후 가격)·제외를 받는다.
  rule:=p_request->'rule';
  if not rule ?& array['mode','value'] or (select count(*) from jsonb_object_keys(rule))<>2
    or jsonb_typeof(rule->'mode') is distinct from 'string' or rule->>'mode' not in ('rate','amount')
    or jsonb_typeof(rule->'value') is distinct from 'number' or rule->>'value' !~ '^[1-9][0-9]*$' or (rule->>'value')::numeric>2147483647
    or (rule->>'mode'='rate' and (rule->>'value')::numeric>=100) then
    raise invalid_parameter_value using message='discount_promotion_invalid';
  end if;
  if jsonb_array_length(p_request->'exceptions')>1000 then raise invalid_parameter_value using message='discount_promotion_invalid'; end if;
  for item in select value from jsonb_array_elements(p_request->'exceptions') loop
    if jsonb_typeof(item) is distinct from 'object' or jsonb_typeof(item->'goodId') is distinct from 'string'
      or item->>'goodId' !~ '^[a-z0-9][a-z0-9-]{0,63}$' or jsonb_typeof(item->'mode') is distinct from 'string'
      or item->>'mode' not in ('rate','amount','price','exclude')
      or (item->>'mode'='exclude' and ((select count(*) from jsonb_object_keys(item))<>2 or not item ?& array['goodId','mode']))
      or (item->>'mode'<>'exclude' and ((select count(*) from jsonb_object_keys(item))<>3 or not item ?& array['goodId','mode','value']
        or jsonb_typeof(item->'value') is distinct from 'number' or item->>'value' !~ '^[1-9][0-9]*$' or (item->>'value')::numeric>2147483647
        or (item->>'mode'='rate' and (item->>'value')::numeric>=100))) then
      raise invalid_parameter_value using message='discount_promotion_invalid';
    end if;
  end loop;
  if (select count(distinct value->>'goodId') from jsonb_array_elements(p_request->'exceptions') value)<>jsonb_array_length(p_request->'exceptions') then
    raise invalid_parameter_value using message='discount_promotion_invalid';
  end if;
end $$

-- 옵션 하나의 할인가. 할인가가 1원 미만이거나 그 옵션 판매가 이상이면 null(그 상품은 건너뛴다).
-- 율·금액은 일괄 즉시할인과 같은 계산(private.goods_bulk_discount_price)이다. 예외가는 기준 판매가(goods.price)를 그 값으로
-- 내리는 할인 금액을 모든 옵션에 같게 뺀다 — 옵션 추가금에는 할인을 붙이지 않는 상품 할인 규칙과 같은 모양이다.
create function private.discount_promotion_price(p_good_price integer,p_variant_price integer,p_rule jsonb) returns integer
language plpgsql stable set search_path='' as $$
declare amount bigint;
begin
  if p_rule->>'mode' in ('rate','amount') then
    return private.goods_bulk_discount_price(p_variant_price,jsonb_build_object('mode',p_rule->>'mode','value',p_rule->'value'));
  elsif p_rule->>'mode'='price' then
    amount:=p_good_price::bigint-(p_rule->>'value')::bigint;
    if amount<1 then return null; end if;
    return private.goods_bulk_discount_price(p_variant_price,jsonb_build_object('mode','amount','value',amount));
  end if;
  return null;
end $$

-- 프로모션이 만든 기간할인 한 행. 원장 트리거(겹침·정상가·랜덤 판매 조건)를 그대로 지나고, 상품 기록에는 개별 저장과
-- 같은 감사 행을 남긴다(출처는 after.promotion_id로 읽힌다).
create function private.insert_discount_promotion_period(p_promotion_id uuid,p_good_id text,p_variant_id uuid,p_discount_price integer,
  p_starts timestamptz,p_ends timestamptz,p_actor uuid) returns uuid
language plpgsql security definer set search_path='' as $$
declare variant public.goods_variants; saved private.goods_variant_price_periods;
begin
  perform 1 from public.goods where id=p_good_id for update;
  select * into variant from public.goods_variants where id=p_variant_id and good_id=p_good_id for update;
  if not found then raise check_violation using message='goods_variant_not_found'; end if;
  insert into private.goods_variant_price_periods(good_id,variant_id,state,regular_price,discount_price,starts_at,ends_at,created_by,updated_by,promotion_id)
  values(p_good_id,p_variant_id,'active',variant.price,p_discount_price,p_starts,p_ends,p_actor,p_actor,p_promotion_id)
  returning * into saved;
  insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'admin.good.price_period_saved','goods:'||p_good_id,
    jsonb_build_object('before',null,'after',to_jsonb(saved)));
  return saved.id;
end $$

-- 3. 미리보기·확정·결과 조회 -------------------------------------------------------------------------------------------
create function public.admin_preview_discount_promotion(p_id uuid,p_request jsonb,p_actor uuid,p_session uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare prior private.discount_promotion_operations; kind text; target_ids text[]; ids text[]; label text; g public.goods;
  rows jsonb:='[]'::jsonb; guards jsonb:='{}'::jsonb; applied integer:=0; window_range tstzrange; rule jsonb; skip text; overlap jsonb;
  min_price integer; max_price integer; next_min integer; next_max integer; expires timestamptz; result jsonb;
begin
  perform private.require_goods_group_identity(p_actor,p_session);
  perform private.discount_promotion_validate(p_request);
  if p_id is null then raise invalid_parameter_value using message='discount_promotion_invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('discount-promotion:'||p_id::text,0));
  select * into prior from private.discount_promotion_operations where id=p_id;
  if found then
    if prior.actor_id<>p_actor or prior.session_id<>p_session or prior.request<>p_request then
      raise sqlstate 'PT409' using message='discount_promotion_operation_conflict';
    end if;
    if prior.receipt is not null or prior.expires_at<=clock_timestamp() then
      raise sqlstate 'PT409' using message='discount_promotion_preview_expired';
    end if;
    return prior.preview;
  end if;
  if (p_request->>'endsAt')::timestamptz<=clock_timestamp() then raise check_violation using message='discount_promotion_period_ended'; end if;
  kind:=p_request#>>'{target,kind}';
  target_ids:=array(select value from jsonb_array_elements_text(p_request#>'{target,ids}') with ordinality item(value,ordinality) order by ordinality);
  if kind='campaign' then
    select title into label from public.campaigns where id=target_ids[1];
    if not found then raise check_violation using message='discount_promotion_campaign_unavailable'; end if;
    -- 기획전 본문의 굿즈 블록 순서대로, 처음 나온 자리를 쓴다. 지금 없는 상품 ID는 대상이 아니다.
    ids:=array(select entry.good_id from (
        select item.value good_id,min(section.ordinality*100+item.ordinality) first_seen
        from public.campaigns campaign
        cross join lateral jsonb_array_elements(campaign.sections) with ordinality section(value,ordinality)
        cross join lateral jsonb_array_elements_text(case when section.value->>'type'='goods' and jsonb_typeof(section.value->'good_ids')='array'
          then section.value->'good_ids' else '[]'::jsonb end) with ordinality item(value,ordinality)
        where campaign.id=target_ids[1] and exists(select 1 from public.goods where id=item.value)
        group by item.value) entry order by entry.first_seen,entry.good_id);
  elsif kind='ip' then
    select title into label from public.ips where id=target_ids[1] and archived_at is null;
    if not found then raise check_violation using message='discount_promotion_ip_unavailable'; end if;
    ids:=array(select id from public.goods where ip_id=target_ids[1] and archived_at is null order by id);
  else
    ids:=target_ids;
    if (select count(*) from public.goods where id=any(ids))<>cardinality(ids) then
      raise check_violation using message='discount_promotion_good_unavailable';
    end if;
  end if;
  if coalesce(cardinality(ids),0)=0 then raise check_violation using message='discount_promotion_no_goods'; end if;
  if cardinality(ids)>1000 then raise check_violation using message='discount_promotion_target_limit'; end if;
  if exists(select 1 from jsonb_array_elements(p_request->'exceptions') item where not (item->>'goodId'=any(ids))) then
    raise check_violation using message='discount_promotion_exception_outside_target';
  end if;
  window_range:=tstzrange((p_request->>'startsAt')::timestamptz,(p_request->>'endsAt')::timestamptz,'[)');
  -- 요약과 지문을 같은 시점에 고정한다(일괄 변경과 같은 잠금). 판매로 인한 재고 변동은 지문에 들지 않는다.
  begin
    perform 1 from public.goods where id=any(ids) order by id for share nowait;
    perform 1 from public.goods_variants where good_id=any(ids) order by id for share nowait;
  exception when lock_not_available then raise sqlstate 'PT409' using message='discount_promotion_busy';
  end;
  for g in select goods.* from unnest(ids) with ordinality target(id,ordinality) join public.goods goods on goods.id=target.id order by target.ordinality loop
    rule:=coalesce(
      (select jsonb_build_object('source','exception','mode',item->>'mode','value',item->'value')
        from jsonb_array_elements(p_request->'exceptions') item where item->>'goodId'=g.id),
      jsonb_build_object('source','default','mode',p_request#>>'{rule,mode}','value',p_request#>'{rule,value}'));
    select min(price),max(price) into min_price,max_price from public.goods_variants where good_id=g.id and archived_at is null;
    skip:=null; overlap:=null; next_min:=null; next_max:=null;
    if rule->>'mode'='exclude' then skip:='discount_promotion_excluded';
    elsif g.archived_at is not null then skip:='good_archived';
    elsif min_price is null then skip:='price_period_variant_inactive';
    else
      select jsonb_build_object('promotionId',period.promotion_id,'promotionName',promotion.name,'startsAt',period.starts_at,'endsAt',period.ends_at)
        into overlap
      from public.goods_variants variant
      join private.goods_variant_price_periods period on period.variant_id=variant.id and period.good_id=variant.good_id
      left join private.discount_promotions promotion on promotion.id=period.promotion_id
      where variant.good_id=g.id and variant.archived_at is null and period.state='active'
        and tstzrange(period.starts_at,period.ends_at,'[)') && window_range
      order by period.starts_at,period.id limit 1;
      if overlap is not null then skip:='price_period_overlap';
      elsif exists(select 1 from public.goods_variants variant where variant.good_id=g.id and variant.archived_at is null
          and private.discount_promotion_price(g.price,variant.price,rule) is null) then skip:='goods_bulk_price_invalid';
      else
        select min(private.discount_promotion_price(g.price,variant.price,rule)),max(private.discount_promotion_price(g.price,variant.price,rule))
          into next_min,next_max from public.goods_variants variant where variant.good_id=g.id and variant.archived_at is null;
      end if;
    end if;
    if skip is null then
      applied:=applied+1;
      guards:=guards||jsonb_build_object(g.id,private.goods_bulk_price_fingerprint(g.id));
    end if;
    rows:=rows||jsonb_build_array(jsonb_build_object('id',g.id,'name',g.name,'code',g.code,'price',g.price,
      'priceMin',min_price,'priceMax',max_price,'nextMin',next_min,'nextMax',next_max,
      'published',g.published_at is not null,'archived',g.archived_at is not null,'rule',rule,'skip',skip,'overlap',overlap));
  end loop;
  if applied=0 then raise check_violation using message='discount_promotion_all_skipped'; end if;
  expires:=clock_timestamp()+interval '15 minutes';
  result:=jsonb_build_object('state','ready','operationId',p_id,'request',p_request,
    'target',jsonb_build_object('kind',kind,'ids',to_jsonb(target_ids),'label',label),'goods',rows,'expiresAt',expires);
  insert into private.discount_promotion_operations(id,actor_id,session_id,request,guards,preview,expires_at)
  values(p_id,p_actor,p_session,p_request,guards,result,expires);
  return result;
end $$

create function public.admin_commit_discount_promotion(p_id uuid,p_actor uuid,p_session uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare operation private.discount_promotion_operations; applied_ids text[]; id_value text; line jsonb; g public.goods;
  variant public.goods_variants; starts timestamptz; ends timestamptz; period_count integer:=0; skipped jsonb; result jsonb; failure text;
begin
  perform private.require_goods_group_identity(p_actor,p_session);
  if p_id is null then raise invalid_parameter_value using message='discount_promotion_invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('discount-promotion:'||p_id::text,0));
  select * into operation from private.discount_promotion_operations where id=p_id for update;
  if not found or operation.actor_id<>p_actor or operation.session_id<>p_session then
    raise insufficient_privilege using message='discount_promotion_operation_unavailable';
  end if;
  if operation.receipt is not null then return operation.receipt; end if;
  starts:=(operation.request->>'startsAt')::timestamptz; ends:=(operation.request->>'endsAt')::timestamptz;
  applied_ids:=array(select key from jsonb_object_keys(operation.guards) key order by key);
  select coalesce(jsonb_agg(jsonb_build_object('id',item->>'id','name',item->>'name','code',item->'code','reason',item->>'skip') order by ordinality),'[]'::jsonb)
    into skipped from jsonb_array_elements(operation.preview->'goods') with ordinality goods(item,ordinality) where nullif(item->>'skip','') is not null;
  begin
    foreach id_value in array applied_ids loop
      if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||id_value,0)) then
        raise sqlstate 'PT409' using message='discount_promotion_busy';
      end if;
    end loop;
    begin
      perform 1 from public.goods where id=any(applied_ids) order by id for update nowait;
      perform 1 from public.goods_variants where good_id=any(applied_ids) order by id for update nowait;
      perform 1 from private.goods_variant_price_periods where good_id=any(applied_ids) order by id for update nowait;
    exception when lock_not_available then raise sqlstate 'PT409' using message='discount_promotion_busy';
    end;
    -- 잠근 뒤 다시 본다: 유효기간, 그리고 옵션 가격·옵션 구성·기간할인이 비교 이후 바뀌었는지(재고 변동은 보지 않는다).
    if operation.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='discount_promotion_preview_expired'; end if;
    if exists(select 1 from unnest(applied_ids) id where private.goods_bulk_price_fingerprint(id) is distinct from operation.guards->>id) then
      raise sqlstate 'PT409' using message='discount_promotion_changed';
    end if;
    if ends<=clock_timestamp() then raise check_violation using message='discount_promotion_period_ended'; end if;
    insert into private.discount_promotions(id,name,state,starts_at,ends_at,target_kind,target_ids,target_label,default_rule,request,
      goods_count,applied_count,created_by)
    values(p_id,operation.request->>'name','active',starts,ends,operation.preview#>>'{target,kind}',
      array(select value from jsonb_array_elements_text(operation.preview#>'{target,ids}') with ordinality item(value,ordinality) order by ordinality),
      operation.preview#>>'{target,label}',operation.request->'rule',operation.request,
      jsonb_array_length(operation.preview->'goods'),cardinality(applied_ids),p_actor);
    insert into private.discount_promotion_goods(promotion_id,good_id,position,name,code,rule,skip_reason)
    select p_id,item->>'id',ordinality,item->>'name',item->>'code',item->'rule',nullif(item->>'skip','')
    from jsonb_array_elements(operation.preview->'goods') with ordinality goods(item,ordinality);
    for line in select item from jsonb_array_elements(operation.preview->'goods') with ordinality goods(item,ordinality)
      where nullif(item->>'skip','') is null order by ordinality loop
      select * into g from public.goods where id=line->>'id';
      for variant in select * from public.goods_variants where good_id=g.id and archived_at is null order by id loop
        perform private.insert_discount_promotion_period(p_id,g.id,variant.id,private.discount_promotion_price(g.price,variant.price,line->'rule'),
          starts,ends,p_actor);
        period_count:=period_count+1;
      end loop;
    end loop;
    result:=jsonb_build_object('state','completed','operationId',p_id,'promotionId',p_id,'goodsCount',cardinality(applied_ids),
      'periodCount',period_count,'skipped',skipped,'error',null);
    insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'catalog.discount_promotion.created','discount_promotion:'||p_id::text,
      jsonb_build_object('request',operation.request,'preview',operation.preview,'receipt',result));
  exception when others then
    -- 하위 트랜잭션이 프로모션·기간할인·감사 행을 모두 되돌린다. 거절도 영수증으로 남겨 불명확한 응답을 재실행하지 않는다.
    get stacked diagnostics failure=message_text;
    result:=jsonb_build_object('state','rejected','operationId',p_id,'promotionId',null,'goodsCount',0,'periodCount',0,'skipped','[]'::jsonb,
      'error',case when failure ~ '^[a-z][a-z0-9_]{0,100}$' then failure else 'discount_promotion_rejected' end);
  end;
  update private.discount_promotion_operations set receipt=result where id=p_id;
  return result;
end $$

create function public.admin_read_discount_promotion_operation(p_id uuid,p_actor uuid,p_session uuid,p_seal boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare operation private.discount_promotion_operations; result jsonb;
begin
  perform private.require_goods_group_identity(p_actor,p_session);
  if p_id is null or p_seal is null then raise invalid_parameter_value using message='discount_promotion_invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('discount-promotion:'||p_id::text,0));
  select * into operation from private.discount_promotion_operations where id=p_id for update;
  if not found or operation.actor_id<>p_actor or operation.session_id<>p_session then
    raise insufficient_privilege using message='discount_promotion_operation_unavailable';
  end if;
  if operation.receipt is not null then return operation.receipt; end if;
  result:=jsonb_build_object('state',case when p_seal then 'sealed' else 'unresolved' end,'operationId',p_id,'promotionId',null,
    'goodsCount',0,'periodCount',0,'skipped','[]'::jsonb,'error',null);
  if p_seal then update private.discount_promotion_operations set receipt=result where id=p_id; end if;
  return result;
end $$

-- 4. 중지 ----------------------------------------------------------------------------------------------------------------
-- 이 프로모션이 만든 진행·예정 할인만 끈다. 이미 끝난 기간 행은 그대로 두어 실제로 진행된 이력을 남긴다.
-- 개별로 건 할인과 다른 프로모션의 할인은 promotion_id가 달라 닿지 않는다. 같은 요청번호의 재시도는 저장된 영수증을 돌려준다.
create function public.admin_stop_discount_promotion(p_promotion_id uuid,p_operation_id uuid,p_actor uuid,p_session uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare promotion private.discount_promotions; period private.goods_variant_price_periods; ids text[]; id_value text;
  disabled integer:=0; result jsonb;
begin
  perform private.require_goods_group_identity(p_actor,p_session);
  if p_promotion_id is null or p_operation_id is null then raise invalid_parameter_value using message='discount_promotion_invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('discount-promotion:'||p_promotion_id::text,0));
  select * into promotion from private.discount_promotions where id=p_promotion_id for update;
  if not found then raise no_data_found using message='discount_promotion_not_found'; end if;
  if promotion.state='stopped' then
    if promotion.stop_operation_id=p_operation_id then return promotion.stop_receipt; end if;
    raise sqlstate 'PT409' using message='discount_promotion_already_stopped';
  end if;
  ids:=array(select distinct good_id from private.goods_variant_price_periods
    where promotion_id=p_promotion_id and state='active' and ends_at>clock_timestamp() order by good_id);
  if cardinality(ids)=0 and promotion.ends_at<=clock_timestamp() then raise check_violation using message='discount_promotion_ended'; end if;
  foreach id_value in array ids loop
    if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||id_value,0)) then
      raise sqlstate 'PT409' using message='discount_promotion_busy';
    end if;
  end loop;
  begin
    perform 1 from public.goods where id=any(ids) order by id for update nowait;
    perform 1 from public.goods_variants where good_id=any(ids) order by id for update nowait;
    perform 1 from private.goods_variant_price_periods where good_id=any(ids) order by id for update nowait;
  exception when lock_not_available then raise sqlstate 'PT409' using message='discount_promotion_busy';
  end;
  for period in select * from private.goods_variant_price_periods
    where promotion_id=p_promotion_id and state='active' and ends_at>clock_timestamp() order by good_id,variant_id,id loop
    perform public.admin_save_goods_price_period(period.good_id,period.variant_id,period.id,jsonb_build_object('state','disabled',
      'discountPrice',period.discount_price,'startsAt',period.starts_at,'endsAt',period.ends_at),period.revision);
    disabled:=disabled+1;
  end loop;
  result:=jsonb_build_object('state','completed','operationId',p_operation_id,'promotionId',p_promotion_id,
    'disabledCount',disabled,'goodsCount',cardinality(ids),'stoppedAt',clock_timestamp());
  update private.discount_promotions set state='stopped',stopped_by=p_actor,stopped_at=clock_timestamp(),stop_operation_id=p_operation_id,
    stop_receipt=result,revision=revision+1 where id=p_promotion_id;
  insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'catalog.discount_promotion.stopped','discount_promotion:'||p_promotion_id::text,
    jsonb_build_object('before',to_jsonb(promotion),'receipt',result));
  return result;
end $$

create function public.admin_get_discount_promotion(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare promotion private.discount_promotions;
begin
  if not public.has_operator_capability('catalog.read',false) then raise insufficient_privilege using message='operator_capability_required'; end if;
  if p_id is null then raise invalid_parameter_value using message='discount_promotion_invalid'; end if;
  select * into promotion from private.discount_promotions where id=p_id;
  if not found then raise no_data_found using message='discount_promotion_not_found'; end if;
  return private.discount_promotion_summary(promotion)||jsonb_build_object('checkedAt',statement_timestamp(),
    'stopReceipt',promotion.stop_receipt,
    'goods',coalesce((select jsonb_agg(jsonb_build_object('id',line.good_id,'name',coalesce(good.name,line.name),'code',coalesce(good.code,line.code),
        'archived',coalesce(good.archived_at is not null,true),'rule',line.rule,'skip',line.skip_reason,
        'priceMin',(select min(variant.price) from public.goods_variants variant where variant.good_id=line.good_id and variant.archived_at is null),
        'priceMax',(select max(variant.price) from public.goods_variants variant where variant.good_id=line.good_id and variant.archived_at is null),
        'discounts',(select jsonb_build_object(
            'active',count(*) filter (where period.state='active' and period.ends_at>statement_timestamp()),
            'ended',count(*) filter (where period.state='active' and period.ends_at<=statement_timestamp()),
            'disabled',count(*) filter (where period.state='disabled'),
            'minPrice',min(period.discount_price),'maxPrice',max(period.discount_price))
          from private.goods_variant_price_periods period where period.promotion_id=line.promotion_id and period.good_id=line.good_id))
        order by line.position)
      from private.discount_promotion_goods line left join public.goods good on good.id=line.good_id where line.promotion_id=promotion.id),'[]'::jsonb));
end $$

