end $patch$

-- 교환품 제작: 시작·완료는 클레임 전체 입고가 아니라 그 품목이 담긴 배송 건의 입고(또는 회수 생략 결정)로 연다.
do $patch$
declare definition text:=pg_get_functiondef('private.order_production_document(uuid,boolean)'::regprocedure);
 start_anchor text:=$a$else exists(select 1 from public.order_cancellation_requests where id=j.claim_id and claim_type='exchange' and stage='collected') end),
 'canComplete'$a$;
 complete_anchor text:=$a$else exists(select 1 from public.order_cancellation_requests where id=j.claim_id and claim_type='exchange' and stage='collected') end),
 'history'$a$;
begin
 if (length(definition)-length(replace(definition,start_anchor,'')))/length(start_anchor)<>1
  or (length(definition)-length(replace(definition,complete_anchor,'')))/length(complete_anchor)<>1 then raise exception 'order_production_document anchors must appear once';end if;
 execute replace(replace(definition,start_anchor,$a$else private.claim_production_ready(j.claim_id,j.order_item_id) end),
 'canComplete'$a$),complete_anchor,$a$else private.claim_production_ready(j.claim_id,j.order_item_id) end),
 'history'$a$);
end $patch$

-- 첫 재출고(reshipped_at)의 제작 완료 검사는 재출고한 배송 건의 주문제작 품목만 본다. 배송 건 기록이 없는 옛 재출고는
-- 주문 전체 그대로다. 남은 배송 건은 그 배송 건 재출고 때 private.record_order_claim_shipment_reshipment가 본다.
do $patch$
declare definition text:=pg_get_functiondef('private.production_claim_changed()'::regprocedure);
 anchor text:=$a$if exists(select 1 from public.order_items i where i.order_id=new.order_id and i.production_terms_snapshot is not null and not exists(select 1 from private.order_production_jobs j where j.order_item_id=i.id and j.claim_id=new.id and j.state='completed')) then raise check_violation using message='production_incomplete';end if;$a$;
 replacement text:=$a$if exists(select 1 from public.order_items i where i.order_id=new.order_id and i.production_terms_snapshot is not null
   and(not exists(select 1 from public.order_claim_reshipments r where r.claim_id=new.id)
    or exists(select 1 from public.order_claim_reshipments r where r.claim_id=new.id and(r.shipment_id is null
     or exists(select 1 from public.order_shipment_items l where l.shipment_id=r.shipment_id and l.order_item_id=i.id))))
   and not exists(select 1 from private.order_production_jobs j where j.order_item_id=i.id and j.claim_id=new.id and j.state='completed')) then raise check_violation using message='production_incomplete';end if;$a$;
 -- 클레임 입고완료 때 만드는 작업도 같은 열기 규칙(교환→반품→교환으로 취소된 작업은 되살린다)을 쓴다.
 open_anchor text:=$a$insert into private.order_production_jobs(order_id,order_item_id,claim_id,terms,basis_at,due_at) values(new.order_id,item.id,new.id,item.production_terms_snapshot,basis,private.production_deadline(basis,item.production_terms_snapshot)) on conflict do nothing;$a$;
 open_replacement text:=$a$perform private.open_claim_production_job(new.order_id,item.id,new.id,item.production_terms_snapshot,basis);$a$;
begin
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1
  or (length(definition)-length(replace(definition,open_anchor,'')))/length(open_anchor)<>1 then raise exception 'production_claim_changed anchors must appear once';end if;
 execute replace(replace(definition,anchor,replacement),open_anchor,open_replacement);
end $patch$

-- 회수 생략 결정은 하자·오배송 교환인 동안에만 회수를 대신한다. 반품 전환·사유 정정으로 결정이 효력을 잃었는데 그 배송 건이 실제로
-- 입고되지 않았으면, 결정 덕에 '입고완료'가 된 클레임을 '수거중'으로 되돌리고 회수 완료 시각을 비운다(감사 기록). 고객 화면의
-- '모두 입고' 안내와 환급 기한이 실제 반환 전부터 흐르지 않게 한다. 실제 입고 기록·결정 기록은 그대로 둔다. 단계 투영
-- (trg_order_cancellation_requests_stage_projection)보다 먼저 돌도록 이름이 claims_로 시작한다.
create function private.reopen_ineffective_collection_waivers() returns trigger language plpgsql security definer set search_path='' as $$
declare pending uuid[];
begin
 if old.claim_type='exchange' and old.reason_type='defect' and not(new.claim_type='exchange' and new.reason_type='defect')
  and(new.stage='collected' or new.stage='on_hold' and new.held_from='collected') then
  select array_agg(x.shipment_id order by x.shipment_id) into pending
  from public.order_claim_collection_waivers w join public.order_claim_collections x on x.claim_id=w.claim_id and x.shipment_id=w.shipment_id
  where w.claim_id=new.id and x.collected_at is null;
  if pending is not null then
   if new.stage='collected' then new.stage:='collecting';else new.held_from:='collecting';end if;
   new.collected_at:=null;
   insert into public.audit_log(actor_id,action,target,diff) values((select auth.uid()),'admin.order.claim_collection_reopened','order:'||new.order_id::text,
    jsonb_build_object('claimId',new.id,'claimType',new.claim_type,'reasonType',new.reason_type,'from','collected','to','collecting',
     'shipmentIds',to_jsonb(pending),'cause','collection_waiver_ineffective'));
  end if;
 end if;
 return new;
end $$

-- 이 migration 전에 입고돼 진행 중인 교환의 주문제작 품목에 교환품 제작 작업을 만든다(멱등, 이미 있으면 그대로).
do $backfill$declare target uuid;begin
 for target in select id from public.order_cancellation_requests where claim_type='exchange' and stage in('collecting','collected') order by id loop
  perform private.ensure_claim_ready_production_jobs(target);
 end loop;
end $backfill$

-- 선물 받은 분에게 배송 건 재출고 소포(운송장)를 싣는다. 정확한 키를 요구하는 옛 앱 파서가 배포 틈에 기존 선물을 읽지
-- 못하는 일이 없게 배송 건 재출고 기록이 있을 때만 싣고, 옛 한 쌍 재출고는 claim.reship*로 그대로 보인다.
do $patch$
declare definition text:=pg_get_functiondef('private.gift_claim_context(uuid,uuid)'::regprocedure);
 anchor text:=$a$return jsonb_build_object('giftId',gift.id,'isSender',p_actor=gift.sender_id,'isRecipient',p_actor=gift.recipient_id,$a$;
 replacement text:=$a$return (case when p_actor=gift.recipient_id and exists(select 1 from public.order_claim_reshipments r where r.order_id=gift.order_id)
  then jsonb_build_object('reshipmentParcels',(select coalesce(jsonb_agg(p.value order by p.n),'[]'::jsonb)
   from jsonb_array_elements(private.order_claim_reshipment_parcels(gift.order_id)) with ordinality p(value,n) where p.value->>'reshipmentId' is not null))
  else '{}'::jsonb end)||jsonb_build_object('giftId',gift.id,'isSender',p_actor=gift.sender_id,'isRecipient',p_actor=gift.recipient_id,$a$;
begin
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'gift_claim_context anchor must appear once';end if;
 execute replace(definition,anchor,replacement);
end $patch$

create function public.admin_record_order_claim_origin_collection(p_claim_id uuid, p_shipment_id uuid, p_evidence text, p_received_on date)
 returns text
 language plpgsql
 security definer
 set search_path to ''
as $function$
declare actor uuid:=(select auth.uid());claim public.order_cancellation_requests;collection public.order_claim_collections;order_key uuid;address_value text;
 order_day date;today date:=(clock_timestamp() at time zone 'Asia/Seoul')::date;received date;
begin
  perform private.require_operator_capability('sales.manage',false);

 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required'; end if;
 if p_evidence is null or p_evidence<>btrim(p_evidence) or char_length(p_evidence) not between 1 and 500 or translate(p_evidence,E'\n\r\t','') ~ '[[:cntrl:]]' then
   raise check_violation using message='invalid_collection_evidence'; end if;
 select order_id into order_key from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found'; end if;
 select (created_at at time zone 'Asia/Seoul')::date into order_day from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 if claim.collection_policy<>'origin' or not claim.collection_required then raise check_violation using message='claim_type_has_no_collection'; end if;
 select * into collection from public.order_claim_collections where claim_id=p_claim_id and shipment_id=p_shipment_id for update;
 if not found then raise no_data_found using message='claim_collection_not_found'; end if;
 if collection.collected_at is not null then
   -- 같은 근거·같은 입고일의 재전송은 멱등하다. 입고일 없이 부르는 옛 경로는 근거만 맞춰 본다.
   if collection.evidence=p_evidence and (p_received_on is null or collection.received_on is not distinct from p_received_on) then
     return case when private.claim_collections_complete(p_claim_id) then 'collected' else 'collecting' end; end if;
   raise unique_violation using message='claim_collection_conflict';
 end if;
 received:=coalesce(p_received_on,today);
 if received>today or received<order_day then raise check_violation using message='invalid_collection_received_on'; end if;
 if claim.stage not in ('collecting','collected','processing','needs_review') then raise exception using message='claim_not_collectable'; end if;
 address_value:=collection.return_address_snapshot;
 if btrim(address_value)='' then
   select return_address into address_value from public.fulfillment_origins where id=collection.origin_id for share;
   if coalesce(btrim(address_value),'')='' then raise check_violation using message='claim_return_address_required'; end if;
 end if;
 update public.order_claim_collections set return_address_snapshot=address_value,collected_at=clock_timestamp(),collected_by=actor,evidence=p_evidence,received_on=received
 where claim_id=p_claim_id and shipment_id=p_shipment_id;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.claim_origin_collected','order:'||order_key::text,
  jsonb_build_object('claimId',p_claim_id,'shipmentId',p_shipment_id,'originId',collection.origin_id,'items',collection.items_snapshot,'returnAddress',address_value,'evidence',p_evidence,
   'receivedOn',received,'collectionWaived',private.claim_collection_waived(p_claim_id,p_shipment_id)));
 -- 회수 완료는 회수가 끝날 때 한 번 적고 알린다(private.complete_order_claim_collection). 회수 생략 배송 건은 회수가 끝난
 -- 것으로 보므로(ADR-0041) 그 배송 건이 늦게 도착해 확인돼도 완료일·단계·알림을 다시 만들지 않는다. 회수 생략 결정이 효력을
 -- 잃어 수거중으로 돌아간 클레임(감사 admin.order.claim_collection_reopened)은 실제 입고로 다시 끝날 때 새 회차로 적고 알린다.
 perform private.complete_order_claim_collection(p_claim_id);
 return case when private.claim_collections_complete(p_claim_id) then 'collected' else 'collecting' end;
end $function$

-- ---------------------------------------------------------------------------
-- 3. 레거시 회수 확인(출고지별 회수 이전 클레임, 입고일)
-- ---------------------------------------------------------------------------
create function public.admin_record_order_claim_collection(p_claim_id uuid, p_stage text, p_received_on date, p_evidence text)
 returns text
 language plpgsql
 security definer
 set search_path to 'public', 'pg_temp'
as $function$
declare
  v_actor uuid := (select auth.uid());
  v_claim record;
  v_order_day date;
  v_today date := (clock_timestamp() at time zone 'Asia/Seoul')::date;
  v_received date;
begin
  perform private.require_operator_capability('sales.manage',false);

  if v_actor is null or not public.has_operator_capability('sales.manage',false) then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if p_stage not in ('collecting', 'collected') then
    raise check_violation using message = 'invalid collection stage';
  end if;
  -- 레거시 회수에는 근거 열이 없어 감사 기록에만 남긴다. 출고지별 회수 확인 근거와 같은 규칙이다.
  if p_evidence is not null and (p_evidence <> btrim(p_evidence) or char_length(p_evidence) not between 1 and 500
    or translate(p_evidence, E'\n\r\t', '') ~ '[[:cntrl:]]') then
    raise check_violation using message = 'invalid_collection_evidence';
  end if;

  select (o.created_at at time zone 'Asia/Seoul')::date into v_order_day
  from public.orders o join public.order_cancellation_requests c on c.order_id=o.id where c.id=p_claim_id for update of o;
  perform s.id from public.order_shipments s join public.order_cancellation_requests c on c.order_id=s.order_id where c.id=p_claim_id order by s.id for update of s;

  select request.*
  into v_claim
  from public.order_cancellation_requests as request
  where request.id = p_claim_id
  for update;

  if not found then
    raise no_data_found using message = 'claim_not_found';
  end if;

  if v_claim.collection_policy='origin' and p_stage='collected' then raise check_violation using message='origin_collection_required'; end if;

  if v_claim.claim_type = 'cancel' then
    raise exception using message = 'claim_type_has_no_collection';
  end if;

  -- 수거 시작은 승인이 이미 만든다. 같은 값으로 다시 부르면 멱등하게 통과하고,
  -- 그 밖의 단계에서 부르면 거절한다 — 뒤로 감는 전이를 만들지 않는다.
  if p_stage = 'collecting' then
    if v_claim.stage = 'collecting' then
      return 'collecting';
    end if;
    raise exception using message = 'claim_not_collectable';
  end if;

  if v_claim.stage = 'collected' then
    return 'collected';
  end if;
  if v_claim.stage <> 'collecting' then
    raise exception using message = 'claim_not_collectable';
  end if;

  -- 실제 입고일(KST 날짜). 비우면 오늘이다. 미래와 주문일보다 이른 날은 받지 않는다.
  v_received := coalesce(p_received_on, v_today);
  if v_received > v_today or v_received < v_order_day then
    raise check_violation using message = 'invalid_collection_received_on';
  end if;

  update public.order_cancellation_requests
  set
    stage = p_stage,
    collected_at = case when p_stage = 'collected' then now() else collected_at end,
    collection_received_on = v_received,
    updated_at = now()
  where id = p_claim_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.claim_collected',
    'order:' || v_claim.order_id::text,
    jsonb_build_object(
      'claimId', p_claim_id,
      'claimType', v_claim.claim_type,
      'from', v_claim.stage,
      'to', p_stage,
      'receivedOn', v_received,
      'evidence', p_evidence
    )
  );

  perform private.notify_order_claim(
    p_claim_id,
    'collected',
    '반송한 굿즈가 입고됐어요',
    case
      when v_claim.claim_type = 'exchange'
        then '입고가 확인됐습니다. 교환 상품 재출고를 준비합니다.'
      else '입고가 확인됐습니다. 영업일 기준 3일 이내에 환급 절차를 진행합니다.'
    end
  );

  return p_stage;
end;
$function$

-- 다른 트랙이 같은 함수를 이어 고치므로 앵커 치환으로 최소 변경한다.
do $patch$
declare definition text:=pg_get_functiondef('public.admin_order_claim_detail(uuid)'::regprocedure);
 anchor text:='  return result || jsonb_build_object(''sellerIntake'', private.seller_claim_intake_json(p_claim_id),''gift'',private.gift_admin_claim_party(p_claim_id));';
 replacement text:='  -- 실제 입고일(1027T-033): 클레임의 회수 완료일. 환급 기한은 이 날부터 센다(비어 있으면 옛 기록이라 collectedAt).
  if jsonb_typeof(result->''claim'')=''object'' then
    result:=jsonb_set(result,''{claim}'',(result->''claim'')||jsonb_build_object(''collectionReceivedOn'',
      (select c.collection_received_on from public.order_cancellation_requests c where c.id=p_claim_id)));
  end if;
  return result || jsonb_build_object(''sellerIntake'', private.seller_claim_intake_json(p_claim_id),''gift'',private.gift_admin_claim_party(p_claim_id));';
begin
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'admin_order_claim_detail anchor must appear once';end if;
 execute replace(definition,anchor,replacement);
end $patch$

-- 회수 생략 결정이 효력을 잃어 입고완료를 수거중으로 되돌릴 때(ADR-0041) 클레임의 회수 완료일도 비운다. 실제 입고로 다시
-- 완료되면 회수 확인이 확인된 출고지 행에서 다시 센다. 다른 트랙의 트리거 함수라 앵커 치환으로 한 줄만 더한다.
do $patch$
declare definition text:=pg_get_functiondef('private.reopen_ineffective_collection_waivers()'::regprocedure);
 anchor text:=$a$new.collected_at:=null;$a$;
 replacement text:=$a$new.collected_at:=null;new.collection_received_on:=null;$a$;
begin
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'reopen_ineffective_collection_waivers anchor must appear once';end if;
 execute replace(definition,anchor,replacement);
end $patch$

-- 회수 생략을 다른 출고지 입고 뒤에 결정해도 회수 완료가 된다(입고 → 결정 순서). 결정 순서와 상관없이 같은 완료·알림이
-- 되도록 결정 뒤에 공용 완료를 부른다(같은 결정의 재전송은 이미 완료면 아무것도 하지 않는다). 다른 트랙의 함수라 앵커 치환으로
-- 한 줄만 더한다. 재출고와 같은 요청의 회수 생략(private.record_order_claim_shipment_reshipment)은 연락처 작업 영수증이
-- 클레임 버전을 정확히 1 올리는 계약이라 여기서 완료하지 않는다(그 교환은 재출고로 끝난다).
do $patch$
declare definition text:=pg_get_functiondef('public.admin_waive_order_claim_collection(uuid,uuid,jsonb)'::regprocedure);
 anchor text:=$a$select * into target from private.claim_reshipment_targets(p_claim_id) t where t.shipment_id=p_shipment_id;$a$;
 replacement text:=$a$perform private.complete_order_claim_collection(p_claim_id,'collection_waiver_decided');
 select * into target from private.claim_reshipment_targets(p_claim_id) t where t.shipment_id=p_shipment_id;$a$;
begin
 if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'admin_waive_order_claim_collection anchor must appear once';end if;
 execute replace(definition,anchor,replacement);
end $patch$

-- 교환→반품→교환 왕복으로 취소된 교환품 제작 작업을 완료 전 상태로 되살릴 때는 납기를 되살린 때부터 다시 센다(ADR-0041 8).
-- 부르는 쪽이 준 준비 시각(처음 입고·결정 시각)으로 다시 세면 왕복에 걸린 날만큼 이미 지난 납기로 되살아나 고객 화면에
-- 지난 날짜가, 운영 패널에 기한 초과가 바로 뜬다. 기준 시각은 준비 시각과 지금 중 늦은 쪽이다. 처음 만들 때의 규칙과
-- 완료 뒤 취소된 작업(완료 그대로)은 바꾸지 않는다. 다른 트랙의 함수라 앵커 치환(각 1회)으로 두 줄만 바꾼다.
do $patch$
declare definition text:=pg_get_functiondef('private.open_claim_production_job(uuid,uuid,uuid,jsonb,timestamptz)'::regprocedure);
 basis_anchor text:=$a$else excluded.basis_at end,$a$;
 basis_replacement text:=$a$else greatest(excluded.basis_at,clock_timestamp()) end,$a$;
 due_anchor text:=$a$else excluded.due_at end,$a$;
 due_replacement text:=$a$else private.production_deadline(greatest(excluded.basis_at,clock_timestamp()),excluded.terms) end,$a$;
begin
 if (length(definition)-length(replace(definition,basis_anchor,'')))/length(basis_anchor)<>1
  or (length(definition)-length(replace(definition,due_anchor,'')))/length(due_anchor)<>1 then
  raise exception 'open_claim_production_job anchors must appear once';end if;
 execute replace(replace(definition,basis_anchor,basis_replacement),due_anchor,due_replacement);
end $patch$

create function public.admin_order_claim_bulk_context(p_claim_ids uuid[])
 returns jsonb
 language plpgsql
 stable security definer
 set search_path to ''
as $function$
begin
  if not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='operator_capability_required'; end if;
  if auth.uid() is null then raise insufficient_privilege using message='staff required'; end if;
  if p_claim_ids is null or cardinality(p_claim_ids) not between 1 and 50 or array_position(p_claim_ids,null) is not null then
    raise check_violation using message='invalid_claim_bulk_ids'; end if;
  -- 고른 순서대로, 같은 요청은 한 번만, 없는 요청은 빼고 돌려준다.
  return coalesce((select jsonb_agg(private.order_claim_bulk_context_row(picked.id) order by picked.position)
    from (select distinct on (u.id) u.id,u.position from unnest(p_claim_ids) with ordinality u(id,position) order by u.id,u.position) picked
    where exists(select 1 from public.order_cancellation_requests c where c.id=picked.id)),'[]'::jsonb);
end $function$

-- 스위치 변경은 누가(migration·SQL 편집기 포함) 언제 바꿨는지 감사 기록에 남기고, 바뀔 때마다 리비전을 올린다. 행은 지우지 못한다.
create function private.audit_return_fee_deduction_settings() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then raise check_violation using message = 'return_fee_deduction_settings_required'; end if;
  if tg_when = 'BEFORE' then
    new.revision := old.revision + 1;
    new.updated_at := clock_timestamp();
    return new;
  end if;
  insert into public.audit_log(actor_id, action, target, diff)
  values (null, 'system.return_fee_deduction.settings_changed', 'return_fee_deduction_settings',
    jsonb_build_object('before', to_jsonb(old) - 'singleton', 'after', to_jsonb(new) - 'singleton', 'sessionUser', session_user::text));
  return new;
end $$

-- 결정의 금액·근거는 바꾸지 못하고, 상태는 정해진 방향으로만 간다. 행은 지우지 못한다.
create function private.guard_claim_refund_deduction() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then raise check_violation using message = 'refund_deduction_immutable'; end if;
  if (new.claim_id, new.order_id, new.payment_id, new.provider, new.payment_amount, new.one_way_amount, new.basis,
      new.initial_shipping_fee, new.deduction_amount, new.refund_amount, new.settings_revision, new.decided_by, new.decided_at)
    is distinct from
     (old.claim_id, old.order_id, old.payment_id, old.provider, old.payment_amount, old.one_way_amount, old.basis,
      old.initial_shipping_fee, old.deduction_amount, old.refund_amount, old.settings_revision, old.decided_by, old.decided_at)
    or not (old.state = new.state
      or old.state = 'planned' and new.state in ('provider_confirmed', 'applied', 'not_applied')
      or old.state = 'provider_confirmed' and new.state = 'applied')
  then
    raise check_violation using message = 'refund_deduction_immutable';
  end if;
  new.updated_at := clock_timestamp();
  return new;
end $$

-- 3. 판정(읽기 전용). 스위치가 꺼졌거나 단순 변심 반품이 아니면 null — 부르는 쪽은 아무것도 덧붙이지 않는다.
--    켜져 있고 단순 변심 반품이면 차감할 수 있는지(applicable)와 할 수 없는 이유(reason), 금액을 돌려준다.
create function private.return_fee_deduction_plan(p_claim_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  settings private.return_fee_deduction_settings;
  claim public.order_cancellation_requests;
  purchase public.orders;
  pay public.payments;
  payment_count integer;
  basis text;
  fee bigint;
  reason text;
begin
  select * into settings from private.return_fee_deduction_settings where singleton;
  if not found or not settings.enabled then return null; end if;
  select * into claim from public.order_cancellation_requests where id = p_claim_id;
  if not found or claim.claim_type <> 'return' or claim.reason_type <> 'change_of_mind' then return null; end if;
  select * into purchase from public.orders where id = claim.order_id;
  -- 왕복은 '최초 배송비를 한 푼도 내지 않은' 주문만이다. 선결제 배송비(shipping_fee)와 착불(shipping_collect_total) 둘 다 0원일 때.
  basis := case when coalesce(purchase.shipping_fee, 0) = 0 and coalesce(purchase.shipping_collect_total, 0) = 0 then 'round_trip' else 'one_way' end;
  fee := settings.one_way_amount::bigint * case when basis = 'round_trip' then 2 else 1 end;
  select count(*) into payment_count from public.payments p
   where p.purpose = 'order' and p.ref_id = claim.order_id and p.status <> 'failed';
  select * into pay from public.payments p
   where p.purpose = 'order' and p.ref_id = claim.order_id and p.status <> 'failed'
   order by p.created_at desc, p.id desc limit 1;
  reason := case
    when payment_count <> 1 or pay.id is null or pay.amount <= 0 then 'payment_unavailable'
    when exists(select 1 from private.gift_intents g where g.order_id = claim.order_id) then 'gift_order'
    when pay.provider not in ('toss', 'bank_transfer') then 'partial_cancel_unsupported'
    -- 정기배송(billing) 결제는 결제사 부분 취소 계약이 없다 — 차감을 결정하지 않고 전액 환불 + 배송비 청구로 간다.
    when exists(select 1 from public.payment_attempts a
      join private.payment_provider_bindings b on b.attempt_id = a.id
      where a.purpose = 'order' and a.ref_id = claim.order_id) then 'partial_cancel_unsupported'
    when pay.provider = 'toss' and exists(select 1 from public.payment_attempts a
      join private.payment_provider_evidence e on e.payment_attempt_id = a.id
      where a.purpose = 'order' and a.ref_id = claim.order_id
        and (e.payment_method = '가상계좌' or e.result_code = 'DONE_virtual_account')) then 'partial_cancel_unsupported'
    when exists(select 1 from private.claim_fee_invoices i where i.claim_id = claim.id and i.state in ('unpaid', 'reported', 'paid')) then 'claim_fee_invoiced'
    when fee >= pay.amount then 'fee_exceeds_payment'
    else null end;
  return jsonb_build_object(
    'applicable', reason is null,
    'reason', reason,
    'oneWayAmount', settings.one_way_amount,
    'basis', basis,
    'initialShippingFee', coalesce(purchase.shipping_fee, 0) + coalesce(purchase.shipping_collect_total, 0),
    'deductionAmount', fee,
    'paymentId', pay.id,
    'provider', pay.provider,
    'paymentAmount', pay.amount,
    'refundAmount', case when reason is null then pay.amount - fee else pay.amount end,
    'settingsRevision', settings.revision);
end $$

-- 4. 결정 기록. 환불 접수(입고완료 → 처리중)를 적는 함수가 주문·요청·결제 잠금 안에서 부른다. 같은 요청은 첫 결정이 이긴다.
create function private.record_return_fee_deduction(p_claim_id uuid, p_actor uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare plan jsonb; claim public.order_cancellation_requests; inserted private.claim_refund_deductions;
begin
  plan := private.return_fee_deduction_plan(p_claim_id);
  if plan is null or (plan->>'applicable')::boolean is distinct from true then return; end if;
  select * into claim from public.order_cancellation_requests where id = p_claim_id;
  insert into private.claim_refund_deductions(claim_id, order_id, payment_id, provider, payment_amount, one_way_amount, basis,
    initial_shipping_fee, deduction_amount, refund_amount, settings_revision, decided_by)
  values (p_claim_id, claim.order_id, (plan->>'paymentId')::uuid, (plan->>'provider')::public.payment_provider,
    (plan->>'paymentAmount')::bigint, (plan->>'oneWayAmount')::integer, plan->>'basis', (plan->>'initialShippingFee')::bigint,
    (plan->>'deductionAmount')::bigint, (plan->>'refundAmount')::bigint, (plan->>'settingsRevision')::integer, p_actor)
  on conflict (claim_id) do nothing
  returning * into inserted;
  if inserted.claim_id is not null then
    insert into public.audit_log(actor_id, action, target, diff)
    values (p_actor, 'admin.order.claim_refund_deduction_decided', 'order:' || claim.order_id::text,
      jsonb_build_object('claimId', p_claim_id, 'paymentAmount', inserted.payment_amount, 'deductionAmount', inserted.deduction_amount,
        'refundAmount', inserted.refund_amount, 'basis', inserted.basis, 'oneWayAmount', inserted.one_way_amount,
        'settingsRevision', inserted.settings_revision));
  end if;
end $$

-- 카드 finalizer가 환불 원장에 적을 금액. 결제사 부분 취소를 확인하지 않은 차감(planned)이 있으면 확정하지 않는다 —
-- 오케스트레이터가 부분 취소 확인을 적거나(provider_confirmed) 전액 환불로 돌린(not_applied) 뒤에만 끝난다.
create function private.claim_refund_settled_amount(p_payment_id uuid) returns bigint
language plpgsql stable security definer set search_path = '' as $$
declare d private.claim_refund_deductions; amount bigint;
begin
  select p.amount into amount from public.payments p where p.id = p_payment_id;
  select * into d from private.claim_refund_deductions where payment_id = p_payment_id;
  if not found or d.state = 'not_applied' then return amount; end if;
  if d.state in ('provider_confirmed', 'applied') then return d.refund_amount; end if;
  raise check_violation using message = 'refund_deduction_evidence_required';
end $$

-- 6. 화면·감사·알림이 읽는 모양. 결정이 있으면 결정을, 없으면 접수 전 단계의 판정을 보인다(접수 뒤에 결정이 없으면 차감이
--    없으므로 아무것도 보이지 않는다). 스위치가 꺼져 있고 결정이 없으면 null.
create function private.claim_refund_deduction_view(p_claim_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare d private.claim_refund_deductions; claim public.order_cancellation_requests; plan jsonb;
begin
  select * into d from private.claim_refund_deductions where claim_id = p_claim_id;
  if found then
    return jsonb_build_object('source', 'decision', 'state', d.state, 'applicable', d.state <> 'not_applied',
      'reason', case when d.state = 'not_applied' then d.not_applied_reason else null end,
      'oneWayAmount', d.one_way_amount, 'basis', d.basis, 'initialShippingFee', d.initial_shipping_fee,
      'deductionAmount', d.deduction_amount, 'paymentId', d.payment_id, 'provider', d.provider, 'paymentAmount', d.payment_amount,
      'refundAmount', case when d.state = 'not_applied' then d.payment_amount else d.refund_amount end,
      'decidedAt', d.decided_at, 'appliedAt', d.applied_at);
  end if;
  select * into claim from public.order_cancellation_requests where id = p_claim_id;
  if not found or (case when claim.stage = 'on_hold' then coalesce(claim.held_from, 'requested') else claim.stage end)
    not in ('requested', 'in_review', 'collecting', 'collected') then
    return null;
  end if;
  plan := private.return_fee_deduction_plan(p_claim_id);
  if plan is null then return null; end if;
  return jsonb_build_object('source', 'plan', 'state', null) || (plan - 'settingsRevision');
end $$

-- 구매자 알림 문구. 차감 결정이 없으면 null(부르는 쪽의 기존 문구 그대로).
create function private.claim_refund_deduction_notice(p_claim_id uuid, p_event text) returns text
language plpgsql stable security definer set search_path = '' as $$
declare d private.claim_refund_deductions; reason text;
begin
  select * into d from private.claim_refund_deductions where claim_id = p_claim_id;
  if not found or d.state = 'not_applied' then return null; end if;
  reason := case when d.basis = 'round_trip'
    then format('최초 무료배송이라 왕복 반품배송비 %s', private.format_krw(d.deduction_amount))
    else format('반품배송비 %s', private.format_krw(d.deduction_amount)) end;
  if p_event = 'filed_bank_transfer' then
    return format('단순 변심 반품이라 %s을 뺀 %s을 등록하신 환불계좌로 송금하도록 접수했습니다.', reason, private.format_krw(d.refund_amount));
  elsif p_event = 'filed' then
    return format('환불 절차를 시작했습니다. 단순 변심 반품이라 결제 금액 %s에서 %s을 뺀 %s을 환불합니다. 결제사 취소가 확인되면 다시 알려드립니다.',
      private.format_krw(d.payment_amount), reason, private.format_krw(d.refund_amount));
  elsif p_event = 'provider_completed' and d.state = 'applied' then
    return format('결제 금액 %s 가운데 %s을 뺀 %s을 결제사에서 취소했습니다. 카드 부분 취소는 카드사 처리에 영업일 기준 3~4일이 걸릴 수 있습니다.',
      private.format_krw(d.payment_amount), reason, private.format_krw(d.refund_amount));
  elsif p_event = 'completed' and d.state = 'applied' then
    return format('%s을 뺀 %s의 환급 처리가 완료됐습니다. 결제수단에 따라 반영 시점이 다를 수 있습니다.', reason, private.format_krw(d.refund_amount));
  end if;
  return null;
end $$

-- 함수 본문 치환 도우미(이 migration 안에서만 쓰고 지운다). 앵커마다 정확히 한 번 나와야 한다.
create function private.t12a_patch_function(p_function regprocedure, p_pairs text[]) returns void
language plpgsql set search_path = '' as $$
declare definition text := pg_get_functiondef(p_function); i integer;
begin
  if array_length(p_pairs, 1) is null or array_length(p_pairs, 1) % 2 <> 0 then raise exception 't12a patch pairs'; end if;
  for i in 1 .. array_length(p_pairs, 1) / 2 loop
    if (length(definition) - length(replace(definition, p_pairs[2 * i - 1], ''))) / length(p_pairs[2 * i - 1]) <> 1 then
      raise exception '% anchor % must appear once', p_function, i;
    end if;
    definition := replace(definition, p_pairs[2 * i - 1], p_pairs[2 * i]);
  end loop;
  execute definition;
end $$

-- 1. 환불 접수·완료 기록: 접수 때 차감을 결정하고 원장 금액을 확정 환불액으로 연다. 감사·구매자 알림에 차감을 남긴다.
select private.t12a_patch_function('public.admin_record_order_claim_refund(uuid,text,text,text)'::regprocedure, array[
$a$      on conflict (order_id) do nothing;

      insert into public.refunds ($a$,
$a$      on conflict (order_id) do nothing;

      -- 반품배송비 차감(QNA-033, ADR-0031): 단순 변심 반품이고 스위치가 켜져 있으면 여기서 한 번 결정한다.
      -- 환불 원장 금액은 '결제액 − 차감액'으로 연다. 결정이 없으면 차감 0 — 지금과 같은 전액이다.
      perform private.record_return_fee_deduction(p_claim_id, v_actor);

      insert into public.refunds ($a$,
$a$        payment.id,
        payment.amount,
        v_claim.reason,$a$,
$a$        payment.id,
        payment.amount - private.claim_refund_active_deduction(payment.id),
        v_claim.reason,$a$,
$a$        reason = coalesce(public.refunds.reason, excluded.reason),
        status = case$a$,
$a$        reason = coalesce(public.refunds.reason, excluded.reason),
        amount = case
          when public.refunds.status <> 'done' and private.claim_refund_active_deduction(public.refunds.payment_id) > 0
            then excluded.amount
          else public.refunds.amount
        end,
        status = case$a$,
$a$        'from', v_claim.stage,
        'to', 'processing'
      )
    );$a$,
$a$        'from', v_claim.stage,
        'to', 'processing'
      ) || private.claim_refund_deduction_audit(p_claim_id)
    );$a$,
$a$      '환불 접수가 완료됐어요',
      case$a$,
$a$      '환불 접수가 완료됐어요',
      coalesce(private.claim_refund_deduction_notice(p_claim_id,
        case when p_method = 'bank_transfer' then 'filed_bank_transfer' else 'filed' end), case$a$,
$a$        else '결제사에 결제 취소를 접수했습니다. 카드사 처리 일정에 따라 반영 시점이 다를 수 있습니다.'
      end
    );$a$,
$a$        else '결제사에 결제 취소를 접수했습니다. 카드사 처리 일정에 따라 반영 시점이 다를 수 있습니다.'
      end)
    );$a$,
$a$      'refundRows', v_refund_count,
      'settlementNote', p_note
    )
  );$a$,
$a$      'refundRows', v_refund_count,
      'settlementNote', p_note
    ) || private.claim_refund_deduction_audit(p_claim_id)
  );$a$,
$a$    '환불이 완료됐어요',
    '환급 처리가 완료됐습니다. 결제수단에 따라 반영 시점이 다를 수 있습니다.'
  );$a$,
$a$    '환불이 완료됐어요',
    coalesce(private.claim_refund_deduction_notice(p_claim_id, 'completed'),
      '환급 처리가 완료됐습니다. 결제수단에 따라 반영 시점이 다를 수 있습니다.')
  );$a$
])

-- 3. 취소 요청 완료: 감사에 차감을, 구매자 알림에 부분 취소 금액을 남긴다.
select private.t12a_patch_function('public.complete_order_cancellation_request(uuid,text[],uuid)'::regprocedure, array[
$a$      'providerRefundCount', v_provider_refund_count
    ) || case when p_actor_id is null$a$,
$a$      'providerRefundCount', v_provider_refund_count
    ) || private.claim_refund_deduction_audit(p_request_id) || case when p_actor_id is null$a$,
$a$      '결제 금액 전액을 결제사에서 취소했습니다. 카드사 처리 일정에 따라 환급 반영 시점이 다를 수 있습니다.'$a$,
$a$      coalesce(private.claim_refund_deduction_notice(p_request_id, 'provider_completed'),
        '결제 금액 전액을 결제사에서 취소했습니다. 카드사 처리 일정에 따라 환급 반영 시점이 다를 수 있습니다.')$a$
])

-- 8-2. 결제사 부분 취소를 조회로 확인한 결과를 적는다. 같은 확인의 재전송은 같은 결과다.
create function public.service_record_order_claim_partial_refund(p_request_id uuid, p_payment_id uuid, p_refunded_amount bigint,
  p_provider_payment_key text, p_provider_transaction_key text, p_actor_id uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare claim public.order_cancellation_requests; pay public.payments; d private.claim_refund_deductions;
begin
  if p_actor_id is not null and not private.can_finish_operator_cancellation(p_request_id, p_actor_id) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  if p_refunded_amount is null or p_refunded_amount <= 0 or p_provider_payment_key is null
    or (p_provider_transaction_key is not null and p_provider_transaction_key !~ '^[\x21-\x7e]{1,64}$') then
    raise invalid_parameter_value using message = 'refund_deduction_evidence_invalid';
  end if;
  select * into claim from public.order_cancellation_requests where id = p_request_id;
  if not found then raise no_data_found using message = 'cancellation_request_not_found'; end if;
  perform id from public.orders where id = claim.order_id for update;
  select * into claim from public.order_cancellation_requests where id = p_request_id for update;
  if p_actor_id is null and claim.claim_type <> 'cancel' then
    raise insufficient_privilege using message = 'staff required';
  end if;
  select * into pay from public.payments where id = p_payment_id and purpose = 'order' and ref_id = claim.order_id for update;
  select * into d from private.claim_refund_deductions where claim_id = p_request_id for update;
  if d.claim_id is null or pay.id is null or d.payment_id <> pay.id or pay.provider <> 'toss' then
    raise check_violation using message = 'refund_deduction_not_found';
  end if;
  if pay.payment_key is distinct from p_provider_payment_key or p_refunded_amount <> d.refund_amount then
    raise check_violation using message = 'refund_deduction_evidence_mismatch';
  end if;
  if d.state in ('provider_confirmed', 'applied') then return d.state; end if;
  if d.state <> 'planned' or claim.status not in ('processing', 'needs_review') then
    raise check_violation using message = 'refund_deduction_not_planned';
  end if;
  update private.claim_refund_deductions set state = 'provider_confirmed', provider_confirmed_at = clock_timestamp(),
    provider_transaction_key = p_provider_transaction_key where claim_id = p_request_id;
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor_id, case when p_actor_id is null then 'system.order.claim_refund_deduction_confirmed' else 'admin.order.claim_refund_deduction_confirmed' end,
    'order:' || claim.order_id::text,
    jsonb_build_object('claimId', p_request_id, 'paymentId', pay.id, 'refundedAmount', p_refunded_amount,
      'deductionAmount', d.deduction_amount, 'paymentAmount', d.payment_amount));
  return 'provider_confirmed';
end $$

-- 8-3. 결제사가 부분 취소를 받지 않는 결제(조회로 확인, 돈이 움직이기 전)는 차감하지 않고 전액 환불로 돌린다.
--      결제사 부분 취소를 이미 확인한 결정은 되돌리지 않는다.
create function public.service_fallback_order_claim_refund_deduction(p_request_id uuid, p_payment_id uuid, p_actor_id uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare claim public.order_cancellation_requests; pay public.payments; d private.claim_refund_deductions;
begin
  if p_actor_id is not null and not private.can_finish_operator_cancellation(p_request_id, p_actor_id) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  select * into claim from public.order_cancellation_requests where id = p_request_id;
  if not found then raise no_data_found using message = 'cancellation_request_not_found'; end if;
  perform id from public.orders where id = claim.order_id for update;
  select * into claim from public.order_cancellation_requests where id = p_request_id for update;
  if p_actor_id is null and claim.claim_type <> 'cancel' then
    raise insufficient_privilege using message = 'staff required';
  end if;
  select * into pay from public.payments where id = p_payment_id and purpose = 'order' and ref_id = claim.order_id for update;
  perform r.id from public.refunds r where r.payment_id = p_payment_id for update;
  select * into d from private.claim_refund_deductions where claim_id = p_request_id for update;
  if d.claim_id is null or pay.id is null or d.payment_id <> pay.id or pay.provider <> 'toss' then
    raise check_violation using message = 'refund_deduction_not_found';
  end if;
  if d.state = 'not_applied' then return d.state; end if;
  if d.state <> 'planned' then raise check_violation using message = 'refund_deduction_already_confirmed'; end if;
  update private.claim_refund_deductions set state = 'not_applied', not_applied_reason = 'partial_cancel_unavailable',
    not_applied_at = clock_timestamp() where claim_id = p_request_id;
  update public.refunds set amount = pay.amount where payment_id = pay.id and status <> 'done';
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor_id, case when p_actor_id is null then 'system.order.claim_refund_deduction_not_applied' else 'admin.order.claim_refund_deduction_not_applied' end,
    'order:' || claim.order_id::text,
    jsonb_build_object('claimId', p_request_id, 'paymentId', pay.id, 'reason', 'partial_cancel_unavailable',
      'deductionAmount', d.deduction_amount, 'refundAmount', pay.amount));
  return 'not_applied';
end $$

create function private.order_partial_cancellation_blockers(p_order_id uuid) returns text[]
language plpgsql stable security definer set search_path = '' as $$
declare purchase public.orders; pay public.payments; payment_count integer; blockers text[] := array[]::text[];
begin
  if not private.order_partial_cancel_enabled() then blockers := array_append(blockers, 'partial_cancel_disabled'); end if;
  select * into purchase from public.orders where id = p_order_id;
  if not found then return array_append(blockers, 'order_not_found'); end if;
  if purchase.status not in ('paid', 'confirmed') or purchase.shipped_at is not null or purchase.delivered_at is not null or purchase.done_at is not null then
    blockers := array_append(blockers, 'order_not_partial_cancelable');
  end if;
  if exists(select 1 from public.order_shipments s where s.order_id = p_order_id
      and (s.status not in ('ready', 'canceled') or s.shipped_at is not null or s.delivered_at is not null)) then
    blockers := array_append(blockers, 'shipment_already_dispatched');
  end if;
  if exists(select 1 from public.order_cancellation_requests r where r.order_id = p_order_id and r.status in ('requested', 'processing', 'needs_review'))
    or exists(select 1 from public.order_cancellation_claims c where c.order_id = p_order_id) then
    blockers := array_append(blockers, 'order_claim_in_progress');
  end if;
  if private.order_partial_cancel_in_flight(p_order_id) then blockers := array_append(blockers, 'partial_cancel_in_progress'); end if;
  if exists(select 1 from public.payment_attempts a where a.purpose = 'order' and a.ref_id = p_order_id
      and a.state in ('prepared', 'confirming', 'unknown', 'needs_review')) then
    blockers := array_append(blockers, 'payment_reconciliation_required');
  end if;
  if purchase.calculation_version is distinct from 2 then blockers := array_append(blockers, 'legacy_order'); end if;
  select count(*) into payment_count from public.payments p where p.purpose = 'order' and p.ref_id = p_order_id and p.status <> 'failed';
  pay := private.order_partial_cancellation_payment(p_order_id);
  if payment_count <> 1 or pay.id is null or pay.status <> 'paid' or pay.amount <= 0 or pay.amount <> purchase.total then
    blockers := array_append(blockers, 'payment_unavailable');
  elsif pay.provider not in ('toss', 'bank_transfer')
    or pay.provider = 'toss' and nullif(btrim(pay.payment_key), '') is null
    -- 정기배송(billing) 결제는 결제사 부분 취소 계약이 없다.
    or exists(select 1 from public.payment_attempts a join private.payment_provider_bindings b on b.attempt_id = a.id
      where a.purpose = 'order' and a.ref_id = p_order_id)
    -- 토스 가상계좌는 입금 전 부분 취소가 없고 환불계좌 경로가 다르다.
    or pay.provider = 'toss' and exists(select 1 from public.payment_attempts a
      join private.payment_provider_evidence e on e.payment_attempt_id = a.id
      where a.purpose = 'order' and a.ref_id = p_order_id and (e.payment_method = '가상계좌' or e.result_code = 'DONE_virtual_account')) then
    blockers := array_append(blockers, 'partial_cancel_unsupported');
  end if;
  return blockers;
end $$

create function private.order_partial_cancellation_item_blocker(p_order_item_id uuid) returns text
language plpgsql stable security definer set search_path = '' as $$
declare item public.order_items; physical record; target record; link public.order_shipment_items; active integer;
begin
  select * into item from public.order_items where id = p_order_item_id;
  if not found then return 'order_item_not_found'; end if;
  active := private.order_item_active_qty(item.id);
  if active <= 0 then return 'fully_canceled'; end if;
  if item.supply_source <> 'stock' then return 'preorder_item'; end if;
  if item.production_terms_snapshot is not null or exists(select 1 from private.order_production_jobs j where j.order_item_id = item.id) then
    return 'production_item';
  end if;
  if coalesce(item.fulfillment_terms_snapshot->>'mode', '') in ('digital', 'no_delivery') then return 'digital_item'; end if;
  if not exists(select 1 from private.order_price_allocations a where a.order_item_id = item.id and a.order_id = item.order_id) then
    return 'allocation_missing';
  end if;
  select * into link from public.order_shipment_items where order_item_id = item.id and order_id = item.order_id;
  if not found or link.qty <> active then return 'shipment_missing'; end if;
  if exists(select 1 from public.order_shipments s where s.id = link.shipment_id and (s.status <> 'ready' or s.delivery_method = 'digital')) then
    return 'shipment_missing';
  end if;
  -- 상품 통합(재고 승계)·교환 재출고 배정 이력이 있는 품목은 재고 복원 단위가 품목 전체라 수량 단위로 나누지 않는다.
  select * into physical from private.order_item_physical_unit(item.id);
  select * into target from private.resolve_goods_stock_successor(physical.good_id, physical.variant_id);
  if target.hop_count > 0 or physical.good_id <> item.good_id
    or exists(select 1 from private.group_claim_reshipment_allocations where order_item_id = item.id) then
    return 'stock_topology_changed';
  end if;
  return null;
end $$

-- 5. 계산(읽기 전용). 확인창 미리보기와 시작이 같은 함수를 쓴다. 입력·판정이 맞지 않으면 사유 코드로 거절한다.
create function private.order_partial_cancellation_plan(p_order_id uuid, p_items jsonb) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  blockers text[]; purchase public.orders; pay public.payments; entry jsonb; item public.order_items; allocation private.order_price_allocations;
  link public.order_shipment_items; ship public.order_shipments; item_blocker text; qty integer; canceled_before integer; canceled_after integer;
  lines jsonb := '[]'::jsonb; closed jsonb := '[]'::jsonb; touched uuid[] := array[]::uuid[]; seen uuid[] := array[]::uuid[];
  goods bigint := 0; shipping bigint := 0; credit bigint := 0; balance bigint; line_paid bigint; line_volume bigint; line_coupon bigint;
  line_credit bigint; stop_required boolean := false; remaining integer; shipment_left integer; ship_id uuid;
begin
  blockers := private.order_partial_cancellation_blockers(p_order_id);
  if cardinality(blockers) > 0 then raise check_violation using message = blockers[1]; end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 100 then
    raise invalid_parameter_value using message = 'invalid_partial_cancel_items';
  end if;
  select * into purchase from public.orders where id = p_order_id;
  pay := private.order_partial_cancellation_payment(p_order_id);
  for entry in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(entry) <> 'object' or (select count(*) from jsonb_object_keys(entry)) <> 2 or not entry ?& array['orderItemId', 'qty']
      or jsonb_typeof(entry->'orderItemId') <> 'string' or coalesce(entry->>'orderItemId', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or jsonb_typeof(entry->'qty') <> 'number' or coalesce(entry->>'qty', '') !~ '^[1-9][0-9]{0,5}$' then
      raise invalid_parameter_value using message = 'invalid_partial_cancel_items';
    end if;
    if (entry->>'orderItemId')::uuid = any(seen) then raise invalid_parameter_value using message = 'invalid_partial_cancel_items'; end if;
    seen := seen || (entry->>'orderItemId')::uuid;
    select * into item from public.order_items where id = (entry->>'orderItemId')::uuid and order_id = p_order_id;
    if not found then raise check_violation using message = 'partial_cancel_item_not_found'; end if;
    item_blocker := private.order_partial_cancellation_item_blocker(item.id);
    if item_blocker is not null then raise check_violation using message = 'partial_cancel_item_' || item_blocker; end if;
    qty := (entry->>'qty')::integer;
    canceled_before := private.order_item_partially_canceled_qty(item.id);
    if qty > item.qty - canceled_before then raise check_violation using message = 'partial_cancel_qty_exceeds_remaining'; end if;
    canceled_after := canceled_before + qty;
    select * into allocation from private.order_price_allocations where order_item_id = item.id and order_id = p_order_id;
    select * into link from public.order_shipment_items where order_item_id = item.id and order_id = p_order_id;
    select * into ship from public.order_shipments where id = link.shipment_id;
    line_paid := private.partial_cancel_prorate(allocation.paid_goods_total, canceled_after, item.qty)
      - private.partial_cancel_prorate(allocation.paid_goods_total, canceled_before, item.qty);
    line_volume := private.partial_cancel_prorate(allocation.volume_discount, canceled_after, item.qty)
      - private.partial_cancel_prorate(allocation.volume_discount, canceled_before, item.qty);
    line_coupon := private.partial_cancel_prorate(allocation.coupon_discount, canceled_after, item.qty)
      - private.partial_cancel_prorate(allocation.coupon_discount, canceled_before, item.qty);
    line_credit := private.partial_cancel_prorate(allocation.store_credit_discount, canceled_after, item.qty)
      - private.partial_cancel_prorate(allocation.store_credit_discount, canceled_before, item.qty);
    goods := goods + line_paid;
    credit := credit + line_credit;
    if ship.exported_at is not null then stop_required := true; end if;
    if not ship.id = any(touched) then touched := touched || ship.id; end if;
    lines := lines || jsonb_build_object('orderItemId', item.id, 'shipmentId', ship.id, 'shipmentNumber', ship.shipment_number,
      'originName', ship.origin_name_snapshot, 'exported', ship.exported_at is not null,
      'goodName', item.good_name_snapshot, 'variantName', item.variant_name_snapshot, 'variantCode', item.variant_code_snapshot,
      'qty', qty, 'orderedQty', item.qty, 'canceledQtyBefore', canceled_before, 'remainingQtyAfter', item.qty - canceled_after,
      'grossAmount', qty::bigint * item.unit_price - line_volume, 'volumeDiscount', line_volume, 'couponDiscount', line_coupon,
      'storeCreditDiscount', line_credit, 'goodsRefundAmount', line_paid);
  end loop;
  -- 배송 건에 남는 품목이 없으면 그 배송 건을 닫고 선결제 배송비를 함께 돌려준다.
  foreach ship_id in array touched loop
    select coalesce(sum(l.qty), 0) - coalesce((select sum((x->>'qty')::integer) from jsonb_array_elements(lines) x
        where (x->>'shipmentId')::uuid = ship_id), 0)
      into shipment_left from public.order_shipment_items l where l.shipment_id = ship_id;
    if shipment_left = 0 then
      select * into ship from public.order_shipments where id = ship_id;
      -- 합포장 팩에 묶인 배송 건을 닫으면 같은 팩의 다른 배송 건이 출고·해제되지 못한다. 먼저 합포장을 해제한다.
      if exists(select 1 from private.shipment_pack_members m where m.shipment_id = ship.id and m.released_at is null) then
        raise check_violation using message = 'partial_cancel_shipment_packed';
      end if;
      shipping := shipping + ship.shipping_fee;
      closed := closed || jsonb_build_object('shipmentId', ship.id, 'shipmentNumber', ship.shipment_number, 'originName', ship.origin_name_snapshot,
        'shippingFeeRefund', ship.shipping_fee, 'shippingCollectFee', ship.shipping_collect_fee, 'exported', ship.exported_at is not null);
    end if;
  end loop;
  select coalesce(sum(l.qty), 0) - coalesce((select sum((x->>'qty')::integer) from jsonb_array_elements(lines) x), 0)
    into remaining from public.order_shipment_items l where l.order_id = p_order_id;
  if remaining <= 0 then raise check_violation using message = 'partial_cancel_leaves_nothing'; end if;
  balance := pay.amount - private.payment_partial_refunded_amount(pay.id);
  -- 환불액 0원은 결제사를 부르지 않고 바로 적용한다. 남는 잔액이 0원이면 남은 잔액 전부를 결제사 부분 취소로 보낸다.
  if goods + shipping > balance then raise check_violation using message = 'partial_cancel_exceeds_balance'; end if;
  return jsonb_build_object('orderId', p_order_id, 'orderNumber', purchase.order_number, 'paymentId', pay.id, 'provider', pay.provider,
    'paymentAmount', pay.amount, 'balanceBefore', balance, 'goodsRefundAmount', goods, 'shippingRefundAmount', shipping,
    'refundAmount', goods + shipping, 'balanceAfter', balance - goods - shipping, 'storeCreditRestoreAmount', credit,
    'warehouseStopRequired', stop_required, 'remainingQty', remaining, 'lines', lines, 'closedShipments', closed);
end $$

-- 6. 수량 단위 재고 복원(재고 품목·통합 이력 없음만). 주문 전체 취소의 복원(restore_order_item_supply)은 다음 migration에서
--    이미 부분 취소로 복원한 수량을 빼고 남은 수량만 복원하도록 바뀐다.
-- p_follow_successor: 결제사 취소 뒤 상품 통합(재고 승계)이 바뀌어 적용이 막힌 건을 결제 담당이 해소할 때만 참이다. 그때는 승계를 따라
-- 지금의 실물 옵션에 되돌린다(주문 전체 취소의 승계 복원과 같은 대상). 예약 판매 품목은 언제나 거절한다.
create function private.restore_order_item_partial_supply(p_order_item_id uuid, p_qty integer, p_partial_cancellation_id uuid, p_reason text,
  p_follow_successor boolean default false)
returns void language plpgsql set search_path = '' as $$
declare item public.order_items; physical record; target record;
begin
  select * into item from public.order_items where id = p_order_item_id;
  if not found then raise no_data_found using message = 'order_item_not_found'; end if;
  if p_qty is null or p_qty <= 0 then raise invalid_parameter_value using message = 'invalid_partial_cancel_items'; end if;
  perform 1 from public.orders where id = item.order_id for update;
  perform private.lock_goods_stock_successor_topology();
  select * into physical from private.order_item_physical_unit(item.id);
  select * into target from private.resolve_goods_stock_successor(physical.good_id, physical.variant_id);
  perform 1 from public.goods where id = any(array[item.good_id, physical.good_id, target.good_id]) order by id for update nowait;
  perform 1 from public.goods_variants where id = any(array[item.variant_id, physical.variant_id, target.variant_id]) order by id for update nowait;
  if item.supply_source <> 'stock' then raise check_violation using message = 'partial_cancel_item_preorder_item'; end if;
  if not p_follow_successor and (target.hop_count > 0 or physical.good_id <> item.good_id
    or exists(select 1 from private.group_claim_reshipment_allocations where order_item_id = item.id)) then
    raise check_violation using message = 'partial_cancel_item_stock_topology_changed';
  end if;
  perform private.apply_group_physical_stock_deltas(jsonb_build_array(jsonb_build_object('goodId', target.good_id, 'variantId', target.variant_id, 'delta', p_qty)));
  -- 주문 전체 취소의 복원(order.option_stock_restored, 품목마다 한 번)과 다른 액션이다 — 재고 대조·불량 재고 방어선이 둘을 섞지 않는다.
  insert into public.audit_log(actor_id, action, target, diff) values(auth.uid(), 'order.option_stock_partially_restored', 'order:' || item.order_id::text,
    jsonb_build_object('orderItemId', item.id, 'goodId', target.good_id, 'variantId', target.variant_id, 'delta', p_qty,
      'originalGoodId', item.good_id, 'originalVariantId', item.variant_id, 'physicalGoodId', physical.good_id, 'physicalVariantId', physical.variant_id,
      'generationKind', physical.generation_kind, 'generationId', physical.generation_id, 'operationPath', target.operation_path,
      'supplySource', item.supply_source, 'preorderPolicyId', item.preorder_policy_id, 'reason', p_reason,
      'partialCancellationId', p_partial_cancellation_id, 'followedSuccessor', p_follow_successor));
exception when lock_not_available then raise sqlstate 'PT409' using message = 'goods_group_retry';
end $$

-- 7. 취소한 품목에 배분된 적립금 몫을 적립금으로 되돌린다. 주문 전체 취소의 되돌림(release_order_store_credits)과 같은 방식이고,
--    사용 배정(store_credit_allocations)의 금액을 그만큼 줄여 뒤의 전체 취소가 남은 몫만 되돌리게 한다.
create function private.restore_order_store_credit_portion(p_order_id uuid, p_user_id uuid, p_amount bigint) returns bigint
language plpgsql security definer set search_path = '' as $$
declare allocation private.store_credit_allocations; lot private.store_credit_lots; root private.store_credit_lots;
  release_at timestamptz := clock_timestamp(); expires timestamptz; take bigint; debt_reduction bigint; restored bigint; left_amount bigint := p_amount;
begin
  if p_amount is null or p_amount <= 0 then return 0; end if;
  perform private.lock_store_credit_account(p_user_id);
  perform private.expire_store_credit_lots(p_user_id, release_at);
  for allocation in select * from private.store_credit_allocations where order_id = p_order_id and state = 'consumed' order by lot_id for update loop
    exit when left_amount <= 0;
    take := least(left_amount, allocation.amount);
    select * into lot from private.store_credit_lots where id = allocation.lot_id for update;
    if not found or lot.user_id <> p_user_id or allocation.user_id <> p_user_id then
      raise check_violation using message = 'store_credit_allocation_mismatch';
    end if;
    expires := case when allocation.original_expires_at > release_at then allocation.original_expires_at
      else release_at + make_interval(days => allocation.restore_grace_days) end;
    if lot.revoked_at is not null then
      select * into root from private.store_credit_lots where id = lot.root_lot_id for update;
      debt_reduction := least(take, root.debt_amount);
      update private.store_credit_lots set debt_amount = debt_amount - debt_reduction where id = root.id;
      update private.store_credit_lots set spent_amount = spent_amount - take, revoked_amount = revoked_amount + take where id = lot.id;
      insert into public.store_credit_ledger(user_id, kind, amount, reserved_delta, debt_delta, order_id, lot_id)
        values(p_user_id, 'restore', 0, 0, -debt_reduction, p_order_id, lot.id);
      restored := take - debt_reduction;
      if restored > 0 then perform private.issue_store_credit_lot(p_user_id, restored, expires, 'restoration', p_order_id, null, null, ''); end if;
    else
      update private.store_credit_lots set spent_amount = spent_amount - take, transferred_amount = transferred_amount + take where id = lot.id;
      perform private.issue_store_credit_lot(p_user_id, take, expires, 'restoration', p_order_id, null, null, '', lot.root_lot_id);
    end if;
    if take = allocation.amount then
      update private.store_credit_allocations set state = 'released', released_at = release_at where order_id = p_order_id and lot_id = lot.id;
    else
      update private.store_credit_allocations set amount = amount - take where order_id = p_order_id and lot_id = lot.id;
    end if;
    left_amount := left_amount - take;
  end loop;
  if left_amount > 0 then raise check_violation using message = 'store_credit_allocation_mismatch'; end if;
  perform private.expire_store_credit_lots(p_user_id, release_at);
  return p_amount;
end $$

create function private.notify_order_partial_cancellation(p_id uuid, p_event text) returns void
language plpgsql security definer set search_path = '' as $$
declare head private.order_partial_cancellations; purchase public.orders; label text; body text; title text;
begin
  select * into head from private.order_partial_cancellations where id = p_id;
  select * into purchase from public.orders where id = head.order_id;
  label := left(coalesce(private.partial_cancellation_items_label(p_id), '일부 굿즈'), 200);
  if p_event = 'applied' then
    title := '주문 일부가 취소됐어요';
    body := format('재고가 부족해 %s를 취소했습니다. %s%s나머지 굿즈는 그대로 보내드립니다.', label,
      case when head.refund_amount = 0 then '돌려드릴 결제 금액은 없습니다. '
        when head.provider = 'bank_transfer'
        then format('환불 %s은 등록하신 환불계좌로 송금해 드립니다. ', private.format_krw(head.refund_amount))
        else format('%s을 결제사에서 부분 취소했습니다(카드사 처리에 영업일 기준 3~4일). ', private.format_krw(head.refund_amount)) end,
      case when head.store_credit_restore_amount > 0
        then format('사용하신 적립금 %s은 적립금으로 되돌려 드렸습니다. ', private.format_krw(head.store_credit_restore_amount)) else '' end);
  elsif p_event = 'transferred' then
    title := '부분 취소 환불을 송금했어요';
    body := format('취소한 %s의 환불 %s을 환불계좌로 송금했습니다.', label, private.format_krw(head.refund_amount));
  else
    return;
  end if;
  insert into public.notifications(user_id, type, title, body, link_path, source_type, source_id, dedupe_key)
  values (purchase.user_id, 'claim_updated', title, left(body, 500), '/orders/' || purchase.id::text, 'order_partial_cancellation', head.id::text,
    'partial-cancel:' || p_event || ':' || head.id::text)
  on conflict (user_id, dedupe_key) do nothing;
end $$

-- 8. 적용: 결제사 확인 뒤(토스) 또는 시작 때(무통장) 한 트랜잭션에서 재고·배송 건·적립금·카드팩을 바꾼다. 호출자가 주문을 잠근다.
create function private.apply_order_partial_cancellation(p_id uuid, p_actor uuid, p_next_state text, p_follow_successor boolean default false) returns void
language plpgsql security definer set search_path = '' as $$
declare head private.order_partial_cancellations; purchase public.orders; line record; ship_id uuid; obligation private.shipping_collect_obligations;
  policy record; remaining numeric; active_targets integer;
begin
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  if head.applied_at is not null then return; end if;
  if p_next_state not in ('completed', 'awaiting_transfer') then raise invalid_parameter_value using message = 'invalid_partial_cancel_state'; end if;
  select * into purchase from public.orders where id = head.order_id for update;
  perform s.id from public.order_shipments s where s.order_id = head.order_id order by s.id for update;
  if purchase.status not in ('paid', 'confirmed') or purchase.shipped_at is not null or purchase.delivered_at is not null
    or exists(select 1 from public.order_shipments s where s.order_id = head.order_id
      and (s.status not in ('ready', 'canceled') or s.shipped_at is not null or s.delivered_at is not null)) then
    raise check_violation using message = 'partial_cancel_state_changed';
  end if;
  for line in select l.*, link.qty as link_qty, link.shipment_id as link_shipment
    from private.order_partial_cancellation_items l
    left join public.order_shipment_items link on link.order_item_id = l.order_item_id and link.order_id = l.order_id
    where l.partial_cancellation_id = p_id order by l.order_item_id loop
    if line.link_qty is null or line.link_shipment <> line.shipment_id or line.link_qty < line.qty
      or private.order_item_partially_canceled_qty(line.order_item_id) <> line.canceled_qty_before then
      raise check_violation using message = 'partial_cancel_state_changed';
    end if;
  end loop;
  update private.order_partial_cancellations set state = p_next_state, applied_at = clock_timestamp(),
    completed_at = case when p_next_state = 'completed' then clock_timestamp() else completed_at end, last_error_code = null
  where id = p_id;
  for line in select * from private.order_partial_cancellation_items where partial_cancellation_id = p_id order by order_item_id loop
    delete from public.order_shipment_items where order_item_id = line.order_item_id and order_id = line.order_id and qty = line.qty;
    if not found then
      update public.order_shipment_items set qty = qty - line.qty where order_item_id = line.order_item_id and order_id = line.order_id;
    end if;
    perform private.restore_order_item_partial_supply(line.order_item_id, line.qty, p_id, '재고 부족 부분 취소', p_follow_successor);
  end loop;
  for ship_id in select shipment_id from private.order_partial_cancellation_shipments where partial_cancellation_id = p_id order by shipment_id loop
    if exists(select 1 from public.order_shipment_items where shipment_id = ship_id) then
      raise check_violation using message = 'partial_cancel_state_changed';
    end if;
    update public.order_shipments set status = 'canceled', updated_at = now() where id = ship_id and status = 'ready';
    select * into obligation from private.shipping_collect_obligations where shipment_id = ship_id for update;
    if found and obligation.state = 'planned' then
      update private.shipping_collect_obligations set state = 'void', revision = revision + 1, updated_at = clock_timestamp() where shipment_id = ship_id;
      insert into private.shipping_collect_events(operation_id, shipment_id, event, amount, evidence, previous_state, previous_revision)
      values (extensions.gen_random_uuid(), ship_id, 'void', 0,
        jsonb_build_object('orderId', head.order_id, 'reason', 'shipment_partially_canceled_before_dispatch', 'partialCancellationId', p_id),
        obligation.state, obligation.revision);
    end if;
  end loop;
  if head.store_credit_restore_amount > 0 then
    perform private.restore_order_store_credit_portion(head.order_id, purchase.user_id, head.store_credit_restore_amount);
  end if;
  -- 카드팩: 지급 조건(대상 품목이 있고 대상 금액 >= 최소 금액)의 거울이다. 정책 범위에 살아 있는 수량이 남은 대상 품목이 없거나
  -- 남은 수량의 대상 금액이 최소 금액에 못 미치면 열지 않은 카드팩을 회수한다(열어 본 것은 그대로). 최소 금액이 0원인 정책도
  -- 대상 품목이 모두 취소되면 회수한다(PR #652 리뷰).
  for policy in select distinct rp.id, rp.target_ip_id, rp.target_good_id, rp.min_amount
    from public.draw_tickets t join public.reward_policies rp on rp.id = t.reward_policy_id
    where t.source = 'order_paid' and t.source_id = head.order_id and t.consumed_at is null and t.revoked_at is null loop
    select coalesce(sum(private.order_item_active_qty(i.id)::numeric * i.unit_price), 0),
      count(*) filter (where private.order_item_active_qty(i.id) > 0)
      into remaining, active_targets
    from public.order_items i where i.order_id = head.order_id and i.good_ip_id_snapshot = policy.target_ip_id
      and (policy.target_good_id is null or i.good_id = policy.target_good_id);
    if active_targets = 0 or remaining < policy.min_amount then
      perform t.id from public.draw_tickets t where t.source = 'order_paid' and t.source_id = head.order_id
        and t.reward_policy_id = policy.id and t.consumed_at is null and t.revoked_at is null order by t.id for update;
      update public.draw_tickets set revoked_at = now() where source = 'order_paid' and source_id = head.order_id
        and reward_policy_id = policy.id and consumed_at is null and revoked_at is null;
    end if;
  end loop;
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor, 'admin.order.partial_cancellation_applied', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'state', p_next_state, 'provider', head.provider, 'refundAmount', head.refund_amount,
      'goodsRefundAmount', head.goods_refund_amount, 'shippingRefundAmount', head.shipping_refund_amount,
      'storeCreditRestoreAmount', head.store_credit_restore_amount,
      'lines', (select jsonb_agg(jsonb_build_object('orderItemId', l.order_item_id, 'shipmentId', l.shipment_id, 'qty', l.qty,
        'goodsRefundAmount', l.goods_refund_amount) order by l.order_item_id) from private.order_partial_cancellation_items l where l.partial_cancellation_id = p_id),
      'closedShipments', coalesce((select jsonb_agg(c.shipment_id order by c.shipment_id) from private.order_partial_cancellation_shipments c
        where c.partial_cancellation_id = p_id), '[]'::jsonb)));
  perform private.notify_order_partial_cancellation(p_id, 'applied');
end $$

-- 10. 운영자 RPC.
-- 10-1. 주문 상세 패널. 스위치가 꺼져 있고 기록이 없으면 {enabled:false, history:[]} — 화면은 아무것도 그리지 않는다.
-- 운영자 능력 검사가 행 잠금을 쓰므로 PostgREST 읽기 전용 트랜잭션에 걸리지 않게 VOLATILE이다(cs_reply_read_transaction_mode).
-- 기록 읽기는 주문 조회 권한(sales.read)이면 열린다(상담 운영자도 일부 취소 사실을 본다). 시작·해소·송금 같은 처리는 sales.manage다.
create function public.admin_order_partial_cancellation_context(p_order_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare enabled boolean; blockers text[]; history jsonb; pay public.payments; items jsonb; can_manage boolean; level text;
begin
  perform private.require_operator_capability('sales.read', false);
  can_manage := public.has_operator_capability('sales.manage', false);
  -- sales.read는 고객 결정 요약까지, 처리 권한(sales.manage)은 운영 메모·처리자까지, 송금 증빙·계좌·해소 사유는 레거시 관리자만(T03·ADR-0010).
  level := case when public.has_operator_capability('sales.manage', true) then 'legacy' when can_manage then 'manage' else 'read' end;
  enabled := private.order_partial_cancel_enabled();
  select coalesce(jsonb_agg(private.order_partial_cancellation_json(head.id, level) order by head.sequence), '[]'::jsonb) into history
  from private.order_partial_cancellations head where head.order_id = p_order_id;
  if not enabled then
    return jsonb_build_object('enabled', false, 'canManage', can_manage, 'blockers', jsonb_build_array('partial_cancel_disabled'), 'history', history);
  end if;
  if not can_manage then
    return jsonb_build_object('enabled', true, 'canManage', false, 'blockers', '[]'::jsonb, 'history', history);
  end if;
  if not exists(select 1 from public.orders where id = p_order_id) then raise no_data_found using message = 'order_not_found'; end if;
  blockers := private.order_partial_cancellation_blockers(p_order_id);
  pay := private.order_partial_cancellation_payment(p_order_id);
  select coalesce(jsonb_agg(jsonb_build_object('orderItemId', item.id, 'goodName', item.good_name_snapshot, 'variantName', item.variant_name_snapshot,
      'variantCode', item.variant_code_snapshot, 'orderedQty', item.qty, 'canceledQty', private.order_item_partially_canceled_qty(item.id),
      'activeQty', private.order_item_active_qty(item.id), 'unitPrice', item.unit_price,
      'shipmentId', link.shipment_id, 'shipmentNumber', ship.shipment_number, 'originName', ship.origin_name_snapshot,
      'exported', ship.exported_at is not null, 'blocker', private.order_partial_cancellation_item_blocker(item.id))
    order by ship.shipment_number nulls last, item.good_name_snapshot, item.id), '[]'::jsonb) into items
  from public.order_items item
  left join public.order_shipment_items link on link.order_item_id = item.id and link.order_id = item.order_id
  left join public.order_shipments ship on ship.id = link.shipment_id
  where item.order_id = p_order_id;
  return jsonb_build_object('enabled', true, 'canManage', true, 'blockers', to_jsonb(blockers), 'provider', pay.provider, 'paymentAmount', pay.amount,
    'gift', exists(select 1 from private.gift_intents g where g.order_id = p_order_id),
    'balance', case when pay.id is null then null else pay.amount - private.payment_partial_refunded_amount(pay.id) end,
    'items', items, 'history', history);
end $$

-- 10-3. 시작. 같은 operation_id 재전송은 같은 결과다. 토스는 processing(결제사 확인 대기), 무통장은 바로 적용 + 송금 대기.
create function public.admin_start_order_partial_cancellation(p_order_id uuid, p_items jsonb, p_customer_decision text, p_note text,
  p_warehouse_stop_confirmed boolean, p_expected_refund_amount bigint, p_operation_id uuid, p_refund_account jsonb default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_actor uuid := (select auth.uid()); decision text := nullif(btrim(coalesce(p_customer_decision, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), ''); existing private.order_partial_cancellations; plan jsonb; v_id uuid;
  v_sequence integer; line jsonb; closed jsonb; v_state text; zero boolean;
begin
  perform private.require_actor_operator_capability(v_actor, 'sales.manage', false);
  if p_operation_id is null then raise invalid_parameter_value using message = 'invalid_partial_cancel_operation'; end if;
  if decision is null or char_length(decision) not between 2 and 500 or translate(decision, E'\n\r\t', '') ~ '[[:cntrl:]]' then
    raise check_violation using message = 'partial_cancel_customer_decision_required';
  end if;
  if v_note is not null and (char_length(v_note) > 500 or translate(v_note, E'\n\r\t', '') ~ '[[:cntrl:]]') then
    raise check_violation using message = 'invalid_partial_cancel_note';
  end if;
  -- 공통 잠금 순서: order → shipments → attempts → payments → 부분 취소 원장.
  perform 1 from public.orders where id = p_order_id for update;
  if not found then raise no_data_found using message = 'order_not_found'; end if;
  select * into existing from private.order_partial_cancellations where operation_id = p_operation_id;
  if found then
    if existing.order_id <> p_order_id or existing.created_by <> v_actor then
      raise unique_violation using message = 'partial_cancel_operation_conflict';
    end if;
    return jsonb_build_object('id', existing.id, 'state', existing.state, 'provider', existing.provider, 'refundAmount', existing.refund_amount, 'replayed', true);
  end if;
  perform s.id from public.order_shipments s where s.order_id = p_order_id order by s.id for update;
  perform a.id from public.payment_attempts a where a.purpose = 'order' and a.ref_id = p_order_id order by a.id for update;
  perform p.id from public.payments p where p.purpose = 'order' and p.ref_id = p_order_id order by p.id for update;
  plan := private.order_partial_cancellation_plan(p_order_id, p_items);
  if p_expected_refund_amount is distinct from (plan->>'refundAmount')::bigint then
    raise check_violation using message = 'partial_cancel_amount_changed';
  end if;
  if (plan->>'warehouseStopRequired')::boolean and p_warehouse_stop_confirmed is distinct from true then
    raise check_violation using message = 'warehouse_stop_confirmation_required';
  end if;
  zero := (plan->>'refundAmount')::bigint = 0;
  if plan->>'provider' = 'bank_transfer' and not zero then
    if p_refund_account is null or jsonb_typeof(p_refund_account) <> 'object' or (select count(*) from jsonb_object_keys(p_refund_account)) <> 3
      or not p_refund_account ?& array['bankName', 'accountNumber', 'accountHolder']
      or coalesce(p_refund_account->>'bankName', '') !~ '^\S(.{0,38}\S)?$' or coalesce(p_refund_account->>'accountNumber', '') !~ '^[0-9-]{8,30}$'
      or coalesce(p_refund_account->>'accountHolder', '') !~ '^\S(.{0,38}\S)?$'
      or (p_refund_account->>'bankName') ~ '[[:cntrl:]]' or (p_refund_account->>'accountHolder') ~ '[[:cntrl:]]' then
      raise check_violation using message = 'partial_cancel_refund_account_required';
    end if;
  elsif p_refund_account is not null and p_refund_account <> 'null'::jsonb then
    raise check_violation using message = 'partial_cancel_refund_account_not_allowed';
  end if;
  select coalesce(max(sequence), 0) + 1 into v_sequence from private.order_partial_cancellations where order_id = p_order_id;
  -- 0원 환불은 결제사·송금 없이 바로 적용·완료한다. 무통장은 결제사가 없어 바로 적용하고 송금 대기로 둔다.
  v_state := case when zero then 'completed' when plan->>'provider' = 'bank_transfer' then 'awaiting_transfer' else 'processing' end;
  insert into private.order_partial_cancellations(order_id, payment_id, provider, sequence, reason_code, customer_decision, note,
    warehouse_stop_confirmed, payment_amount, balance_before, goods_refund_amount, shipping_refund_amount, refund_amount,
    store_credit_restore_amount, state, operation_id, created_by, filed_at, filed_by)
  values (p_order_id, (plan->>'paymentId')::uuid, (plan->>'provider')::public.payment_provider, v_sequence, 'out_of_stock', decision, v_note,
    (plan->>'warehouseStopRequired')::boolean, (plan->>'paymentAmount')::bigint, (plan->>'balanceBefore')::bigint,
    (plan->>'goodsRefundAmount')::bigint, (plan->>'shippingRefundAmount')::bigint, (plan->>'refundAmount')::bigint,
    (plan->>'storeCreditRestoreAmount')::bigint, 'processing', p_operation_id, v_actor,
    case when v_state = 'awaiting_transfer' then clock_timestamp() end, case when v_state = 'awaiting_transfer' then v_actor end)
  returning id into v_id;
  for line in select value from jsonb_array_elements(plan->'lines') loop
    insert into private.order_partial_cancellation_items(partial_cancellation_id, order_id, order_item_id, shipment_id, qty, canceled_qty_before,
      gross_amount, volume_discount, coupon_discount, store_credit_discount, goods_refund_amount)
    values (v_id, p_order_id, (line->>'orderItemId')::uuid, (line->>'shipmentId')::uuid, (line->>'qty')::integer, (line->>'canceledQtyBefore')::integer,
      (line->>'grossAmount')::bigint, (line->>'volumeDiscount')::bigint, (line->>'couponDiscount')::bigint,
      (line->>'storeCreditDiscount')::bigint, (line->>'goodsRefundAmount')::bigint);
  end loop;
  for closed in select value from jsonb_array_elements(plan->'closedShipments') loop
    insert into private.order_partial_cancellation_shipments(partial_cancellation_id, order_id, shipment_id, shipping_fee_refund)
    values (v_id, p_order_id, (closed->>'shipmentId')::uuid, (closed->>'shippingFeeRefund')::bigint);
  end loop;
  insert into public.audit_log(actor_id, action, target, diff)
  values (v_actor, 'admin.order.partial_cancellation_started', 'order:' || p_order_id::text,
    jsonb_build_object('partialCancellationId', v_id, 'sequence', v_sequence, 'provider', plan->>'provider', 'reasonCode', 'out_of_stock',
      'customerDecision', decision, 'note', v_note, 'warehouseStopConfirmed', (plan->>'warehouseStopRequired')::boolean,
      'refundAmount', (plan->>'refundAmount')::bigint, 'goodsRefundAmount', (plan->>'goodsRefundAmount')::bigint,
      'shippingRefundAmount', (plan->>'shippingRefundAmount')::bigint, 'balanceBefore', (plan->>'balanceBefore')::bigint,
      'lines', plan->'lines', 'closedShipments', plan->'closedShipments'));
  if v_state = 'awaiting_transfer' then
    insert into private.order_partial_cancellation_refund_accounts(partial_cancellation_id, bank_name, account_number, account_holder, masked_account, masked_holder)
    values (v_id, p_refund_account->>'bankName', p_refund_account->>'accountNumber', p_refund_account->>'accountHolder',
      (p_refund_account->>'bankName') || ' ' || public.mask_refund_account_number(p_refund_account->>'accountNumber'),
      public.mask_refund_account_holder(p_refund_account->>'accountHolder'));
    perform private.apply_order_partial_cancellation(v_id, v_actor, 'awaiting_transfer');
  elsif v_state = 'completed' then
    perform private.apply_order_partial_cancellation(v_id, v_actor, 'completed');
  end if;
  return jsonb_build_object('id', v_id, 'state', v_state, 'provider', plan->>'provider', 'refundAmount', (plan->>'refundAmount')::bigint, 'replayed', false);
end $$

-- 10-4. 무통장 송금 완료(불변 송금 증빙). T03·ADR-0010과 같은 권한(송금 담당 = sales.manage + 레거시 관리자, 로그인 세션 확인).
create function public.admin_record_order_partial_cancellation_transfer(p_id uuid, p_evidence text, p_note text, p_operation_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_actor uuid := (select auth.uid()); v_session uuid; head private.order_partial_cancellations;
  evidence text := nullif(btrim(coalesce(p_evidence, '')), ''); v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  begin v_session := (auth.jwt()->>'session_id')::uuid;
  exception when invalid_text_representation then raise insufficient_privilege using message = 'bank_refund_permission_required'; end;
  perform private.require_bank_transfer_refund_identity(v_actor, v_session);
  if p_operation_id is null or evidence is null or char_length(evidence) not between 2 and 300 or v_note is null or char_length(v_note) not between 2 and 300 then
    raise check_violation using message = 'partial_cancel_transfer_evidence_required';
  end if;
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  perform 1 from public.orders where id = head.order_id for update;
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if head.provider <> 'bank_transfer' then raise check_violation using message = 'partial_cancel_not_bank_transfer'; end if;
  if head.state = 'completed' then
    if head.transfer_operation_id = p_operation_id then
      return jsonb_build_object('id', head.id, 'state', head.state, 'replayed', true);
    end if;
    raise check_violation using message = 'partial_cancel_transfer_already_recorded';
  end if;
  if head.state <> 'awaiting_transfer' then raise check_violation using message = 'partial_cancel_not_awaiting_transfer'; end if;
  update private.order_partial_cancellations set state = 'completed', completed_at = clock_timestamp(), transfer_operation_id = p_operation_id,
    transferred_by = v_actor, transferred_at = clock_timestamp(), transfer_evidence = evidence, transfer_note = v_note
  where id = p_id;
  update private.order_partial_cancellation_refund_accounts set purge_after = coalesce(purge_after, now() + interval '30 days')
  where partial_cancellation_id = p_id and purged_at is null;
  insert into public.audit_log(actor_id, action, target, diff)
  values (v_actor, 'admin.order.partial_cancellation_transferred', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'refundAmount', head.refund_amount, 'evidence', evidence, 'note', v_note));
  perform private.notify_order_partial_cancellation(p_id, 'transferred');
  return jsonb_build_object('id', p_id, 'state', 'completed', 'replayed', false);
end $$

-- 10-5. 송금할 계좌 원문 열람(감사 기록). 송금 대기 중에만 열린다.
create function public.admin_view_order_partial_cancellation_refund_account(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_actor uuid := (select auth.uid()); v_session uuid; head private.order_partial_cancellations; account private.order_partial_cancellation_refund_accounts;
begin
  begin v_session := (auth.jwt()->>'session_id')::uuid;
  exception when invalid_text_representation then raise insufficient_privilege using message = 'bank_refund_permission_required'; end;
  perform private.require_bank_transfer_refund_identity(v_actor, v_session);
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  if head.state <> 'awaiting_transfer' then raise check_violation using message = 'partial_cancel_not_awaiting_transfer'; end if;
  select * into account from private.order_partial_cancellation_refund_accounts where partial_cancellation_id = p_id;
  if not found or account.purged_at is not null then raise no_data_found using message = 'partial_cancel_refund_account_missing'; end if;
  insert into public.audit_log(actor_id, action, target, diff)
  values (v_actor, 'admin.order.partial_cancellation_account_viewed', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'maskedAccount', account.masked_account));
  return jsonb_build_object('bankName', account.bank_name, 'accountNumber', account.account_number, 'accountHolder', account.account_holder,
    'amount', head.refund_amount);
end $$

-- 결제사 부분 취소를 조회로 확인한 결과를 적고 품목 취소를 적용한다. 같은 확인의 재전송은 같은 결과다.
create function public.service_complete_order_partial_cancellation(p_id uuid, p_refunded_amount bigint, p_provider_payment_key text,
  p_provider_transaction_key text, p_actor_id uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare head private.order_partial_cancellations; pay public.payments;
begin
  perform private.require_partial_cancellation_actor(p_actor_id);
  if p_refunded_amount is null or p_refunded_amount <= 0 or nullif(btrim(coalesce(p_provider_payment_key, '')), '') is null
    or p_provider_transaction_key is null or p_provider_transaction_key !~ '^[\x21-\x7e]{1,64}$' then
    raise invalid_parameter_value using message = 'partial_cancel_evidence_invalid';
  end if;
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  perform 1 from public.orders where id = head.order_id for update;
  perform s.id from public.order_shipments s where s.order_id = head.order_id order by s.id for update;
  select * into pay from public.payments where id = head.payment_id for update;
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if head.provider <> 'toss' or pay.provider <> 'toss' or pay.payment_key is distinct from p_provider_payment_key or p_refunded_amount <> head.refund_amount then
    raise check_violation using message = 'partial_cancel_evidence_mismatch';
  end if;
  if head.state = 'completed' then
    if head.provider_transaction_key is distinct from p_provider_transaction_key then raise check_violation using message = 'partial_cancel_evidence_mismatch'; end if;
    return 'completed';
  end if;
  if head.state not in ('processing', 'needs_review') then raise check_violation using message = 'partial_cancel_not_processing'; end if;
  update private.order_partial_cancellations set provider_confirmed_at = clock_timestamp(), provider_transaction_key = p_provider_transaction_key
  where id = p_id;
  perform private.apply_order_partial_cancellation(p_id, p_actor_id, 'completed');
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor_id, 'admin.order.partial_cancellation_completed', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'paymentId', pay.id, 'refundedAmount', p_refunded_amount,
      'balanceAfter', head.balance_before - p_refunded_amount));
  return 'completed';
end $$

-- 결제사가 이 결제의 부분 취소를 받지 않는다(돈이 움직이지 않음을 조회로 확인). 품목 부분 취소를 진행하지 않고 닫는다.
create function public.service_reject_order_partial_cancellation(p_id uuid, p_reason_code text, p_actor_id uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare head private.order_partial_cancellations;
begin
  perform private.require_partial_cancellation_actor(p_actor_id);
  if p_reason_code is distinct from 'provider_partial_cancel_unavailable' then raise invalid_parameter_value using message = 'invalid_partial_cancel_reason'; end if;
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  perform 1 from public.orders where id = head.order_id for update;
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if head.state = 'rejected' then return 'rejected'; end if;
  if head.state not in ('processing', 'needs_review') then raise check_violation using message = 'partial_cancel_not_processing'; end if;
  update private.order_partial_cancellations set state = 'rejected', rejected_at = clock_timestamp(), last_error_code = p_reason_code where id = p_id;
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor_id, 'admin.order.partial_cancellation_rejected', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'reason', p_reason_code, 'refundAmount', head.refund_amount));
  return 'rejected';
end $$

-- 결과가 모호하거나 대조가 맞지 않는다. 출고는 계속 막고 같은 경로로 다시 확인한다.
create function public.service_mark_order_partial_cancellation_needs_review(p_id uuid, p_code text, p_actor_id uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare head private.order_partial_cancellations;
begin
  perform private.require_partial_cancellation_actor(p_actor_id);
  if p_code is null or p_code !~ '^[a-z0-9_]{1,64}$' then raise invalid_parameter_value using message = 'invalid_partial_cancel_reason'; end if;
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  perform 1 from public.orders where id = head.order_id for update;
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if head.state not in ('processing', 'needs_review') then return head.state; end if;
  update private.order_partial_cancellations set state = 'needs_review', last_error_code = p_code where id = p_id;
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor_id, 'admin.order.partial_cancellation_needs_review', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'code', p_code));
  return 'needs_review';
end $$

-- 11-2. 결제확인필요 해소(결제 담당 = sales.manage + 레거시 관리자, 로그인 세션, 사유 필수, 감사 기록).
--  서비스 전용이다: 해소 방법·관측 잔액·거래 키는 서버가 결제사를 조회해(inspectOrderPartialCancellationResolution) 정한 값이고,
--  브라우저 세션이 PostgREST로 직접 부르면 결제사 조회 없이 '적용 강제'나 '진행하지 않음'을 만들 수 있어 authenticated에는 열지 않는다.
--  운영자 신원(p_actor_id·p_session_id)은 서버가 증명하고 DB가 service_export_* 와 같은 판정(세션·프로필·sales.manage 레거시)으로 다시 확인한다.
--  not_moved: 서버가 결제사 조회로 잔액이 시작 때 잔액 그대로임(돈이 움직이지 않음)을 확인했다 → 진행하지 않음(rejected).
--  already_canceled: 결제사 조회로 잔액이 '시작 때 잔액 − 환불액'이고 그 취소 거래 키를 확인했다 → 그 키로 적용을 강제한다.
--    재고 승계(상품 통합)가 그 사이 바뀌어 수량 단위 복원이 막혔으면 승계를 따라 지금의 실물 옵션에 복원한다.
create function public.service_resolve_order_partial_cancellation(p_id uuid, p_resolution text, p_reason text, p_provider_transaction_key text,
  p_observed_balance bigint, p_actor_id uuid, p_session_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_actor uuid := p_actor_id; head private.order_partial_cancellations; pay public.payments; buyer uuid;
  reason text := nullif(btrim(coalesce(p_reason, '')), ''); topology boolean := false;
begin
  if v_actor is null or p_session_id is null
    or not exists(select 1 from auth.sessions where id = p_session_id and user_id = v_actor and (not_after is null or not_after > statement_timestamp()))
    or not exists(select 1 from public.profiles where id = v_actor) then
    raise insufficient_privilege using message = 'refund_account_auth_changed';
  end if;
  if not private.has_operator_capability(v_actor, 'sales.manage', true) then raise insufficient_privilege using message = 'bank_refund_permission_required'; end if;
  if p_resolution is null or p_resolution not in ('not_moved', 'already_canceled') then
    raise invalid_parameter_value using message = 'invalid_partial_cancel_resolution';
  end if;
  if reason is null or char_length(reason) not between 5 and 500 or translate(reason, E'\n\r\t', '') ~ '[[:cntrl:]]' then
    raise check_violation using message = 'partial_cancel_resolution_reason_required';
  end if;
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  select o.user_id into buyer from public.orders o where o.id = head.order_id;
  perform private.lock_operator_subjects(array[v_actor, buyer]);
  perform private.require_actor_operator_capability(v_actor, 'sales.manage', true);
  perform id from auth.sessions where id = p_session_id and user_id = v_actor and (not_after is null or not_after > clock_timestamp()) for share;
  if not found then raise insufficient_privilege using message = 'refund_account_auth_changed'; end if;
  perform 1 from public.orders where id = head.order_id for update;
  perform s.id from public.order_shipments s where s.order_id = head.order_id order by s.id for update;
  select * into pay from public.payments where id = head.payment_id for update;
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if head.provider <> 'toss' or head.state <> 'needs_review' then raise check_violation using message = 'partial_cancel_not_needs_review'; end if;
  if p_resolution = 'not_moved' then
    if p_observed_balance is distinct from head.balance_before then raise check_violation using message = 'partial_cancel_resolution_evidence_mismatch'; end if;
    update private.order_partial_cancellations set state = 'rejected', rejected_at = clock_timestamp(), last_error_code = 'manual_not_moved',
      resolution = 'not_moved', resolution_reason = reason, resolved_by = v_actor, resolved_at = clock_timestamp() where id = p_id;
  else
    if p_observed_balance is distinct from head.balance_before - head.refund_amount
      or p_provider_transaction_key is null or p_provider_transaction_key !~ '^[\x21-\x7e]{1,64}$' then
      raise check_violation using message = 'partial_cancel_resolution_evidence_mismatch';
    end if;
    update private.order_partial_cancellations set provider_confirmed_at = clock_timestamp(), provider_transaction_key = p_provider_transaction_key,
      resolution = 'already_canceled', resolution_reason = reason, resolved_by = v_actor, resolved_at = clock_timestamp() where id = p_id;
    begin
      perform private.apply_order_partial_cancellation(p_id, v_actor, 'completed', false);
    exception when check_violation then
      if sqlerrm <> 'partial_cancel_item_stock_topology_changed' then raise; end if;
      topology := true;
    end;
    if topology then perform private.apply_order_partial_cancellation(p_id, v_actor, 'completed', true); end if;
  end if;
  insert into public.audit_log(actor_id, action, target, diff)
  values (v_actor, 'admin.order.partial_cancellation_resolved', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'resolution', p_resolution, 'reason', reason, 'observedBalance', p_observed_balance,
      'providerTransactionKey', p_provider_transaction_key, 'followedSuccessor', topology, 'previousCode', head.last_error_code));
  return jsonb_build_object('id', p_id, 'state', case when p_resolution = 'not_moved' then 'rejected' else 'completed' end, 'followedSuccessor', topology);
end $$

-- 11-3. 환불 송금 대기 엑셀(T03)의 무통장 부분 취소 계좌 원문. 서버가 증명한 운영자·세션으로 클레임 계좌 반출(service_export_bank_
--   transfer_refund_accounts)과 같은 판정을 하고, 같은 반출 번호(p_export_id)로 줄마다 열람 감사를 남긴다(원문은 남기지 않는다).
create function public.service_export_order_partial_cancellation_refund_accounts(p_actor_id uuid, p_session_id uuid, p_export_id uuid, p_items jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid := p_actor_id; target record; head private.order_partial_cancellations; account private.order_partial_cancellation_refund_accounts;
  results jsonb[] := '{}'; revealed integer := 0; order_ids uuid[]; ids uuid[]; happened timestamptz;
begin
  if actor is null or p_session_id is null or p_export_id is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) > 10000
    or exists(select 1 from jsonb_array_elements(p_items) item where jsonb_typeof(item) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(item) k where k not in ('partialCancellationId', 'orderId'))
      or coalesce(item->>'partialCancellationId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or coalesce(item->>'orderId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
    raise invalid_parameter_value using message = 'invalid_bank_refund_export';
  end if;
  select coalesce(array_agg(distinct (item->>'orderId')::uuid), '{}'), coalesce(array_agg(distinct (item->>'partialCancellationId')::uuid), '{}')
    into order_ids, ids from jsonb_array_elements(p_items) item;
  if cardinality(ids) <> jsonb_array_length(p_items) then raise invalid_parameter_value using message = 'invalid_bank_refund_export'; end if;
  if not exists(select 1 from auth.sessions where id = p_session_id and user_id = actor and (not_after is null or not_after > statement_timestamp()))
    or not exists(select 1 from public.profiles where id = actor) then
    raise insufficient_privilege using message = 'refund_account_auth_changed';
  end if;
  if not private.has_operator_capability(actor, 'sales.manage', true) then raise insufficient_privilege using message = 'bank_refund_permission_required'; end if;
  perform private.lock_operator_subjects(array[actor] || coalesce((select array_agg(purchase.user_id) from public.orders purchase where purchase.id = any(order_ids)), '{}'));
  perform private.require_actor_operator_capability(actor, 'sales.manage', true);
  perform id from auth.sessions where id = p_session_id and user_id = actor and (not_after is null or not_after > clock_timestamp()) for share;
  if not found then raise insufficient_privilege using message = 'refund_account_auth_changed'; end if;
  perform purchase.id from public.orders purchase where purchase.id = any(order_ids) order by purchase.id for update;
  perform h.id from private.order_partial_cancellations h where h.id = any(ids) order by h.id for update;
  happened := clock_timestamp();
  for target in select (item.value->>'partialCancellationId')::uuid id, (item.value->>'orderId')::uuid order_id
    from jsonb_array_elements(p_items) with ordinality item(value, ord) order by item.ord loop
    select * into head from private.order_partial_cancellations where id = target.id and order_id = target.order_id;
    if head.id is null or head.provider <> 'bank_transfer' or head.state <> 'awaiting_transfer' then
      raise sqlstate 'PT409' using message = 'bank_refund_export_changed';
    end if;
    select * into account from private.order_partial_cancellation_refund_accounts where partial_cancellation_id = head.id;
    if account.partial_cancellation_id is not null and account.purged_at is null and account.account_number is not null then
      insert into public.audit_log(actor_id, action, target, diff)
      values (actor, 'admin.order.partial_cancellation_account_viewed', 'order:' || head.order_id::text,
        jsonb_build_object('partialCancellationId', head.id, 'purpose', 'list_export', 'exportId', p_export_id, 'maskedAccount', account.masked_account));
      revealed := revealed + 1;
      results := array_append(results, jsonb_build_object('partialCancellationId', head.id, 'status', 'revealed',
        'bankName', account.bank_name, 'accountNumber', account.account_number, 'accountHolder', account.account_holder));
    else
      results := array_append(results, jsonb_build_object('partialCancellationId', head.id, 'status', 'unavailable',
        'bankName', null, 'accountNumber', null, 'accountHolder', null));
    end if;
  end loop;
  insert into public.audit_log(actor_id, action, target, diff)
  values (actor, 'admin.list_export.partial_cancel_refund_accounts_revealed', 'admin_screen:refund-transfers',
    jsonb_build_object('exportId', p_export_id, 'partialCancellationCount', jsonb_array_length(p_items), 'revealedCount', revealed, 'at', happened));
  return jsonb_build_object('exportId', p_export_id, 'rows', to_jsonb(results));
end $$

create function private.t12b_patch_function(p_function regprocedure, p_pairs text[]) returns void
language plpgsql set search_path = '' as $$
declare definition text := pg_get_functiondef(p_function); i integer;
begin
  if array_length(p_pairs, 1) is null or array_length(p_pairs, 1) % 2 <> 0 then raise exception 't12b patch pairs'; end if;
  for i in 1 .. array_length(p_pairs, 1) / 2 loop
    if (length(definition) - length(replace(definition, p_pairs[2 * i - 1], ''))) / length(p_pairs[2 * i - 1]) <> 1 then
      raise exception '% anchor % must appear once', p_function, i;
    end if;
    definition := replace(definition, p_pairs[2 * i - 1], p_pairs[2 * i]);
  end loop;
  execute definition;
end $$

