create policy gift_shipment_extra_trackings_private_read on public.order_shipment_extra_trackings
  as restrictive for select to authenticated
  using (public.gift_direct_order_read_allowed(order_id))

-- 회신 행의 extraTrackingNumbers(선택)를 정규화한다. 대표와 같거나 겹치는 번호, 형식 오류, 19개 초과(대표 포함 20개)는 거절한다.
create function private.reply_extra_tracking_numbers(p_extras jsonb, p_representative text) returns text[]
language plpgsql immutable set search_path = '' as $$
declare value jsonb; normalized text; result text[] := '{}'::text[];
begin
  if p_extras is null or p_extras = 'null'::jsonb then return result; end if;
  if jsonb_typeof(p_extras) <> 'array' or jsonb_array_length(p_extras) > 19 then
    raise invalid_parameter_value using message = 'invalid_tracking_row'; end if;
  for value in select entry from jsonb_array_elements(p_extras) entry loop
    if jsonb_typeof(value) <> 'string' then raise invalid_parameter_value using message = 'invalid_tracking_row'; end if;
    normalized := private.normalize_tracking_number(value #>> '{}');
    if normalized is null or normalized !~ '^[A-Z0-9]{8,30}$' then raise check_violation using message = 'invalid_tracking_input'; end if;
    if normalized = p_representative or normalized = any(result) then raise invalid_parameter_value using message = 'invalid_tracking_row'; end if;
    result := array_append(result, normalized);
  end loop;
  return result;
end $$

-- 서원 회신 반입 전 검사(배송 건은 호출자가 이미 잠갔다). 발송 대기 건은 추가 운송장이 다른 배송 건에 쓰이지 않아야 하고,
-- 이미 발송된 건(다른 운영자가 같은 회신을 먼저 등록)은 회신의 추가 운송장이 모두 이미 붙어 있어야 한다 — 덮어쓰거나 더하지 않는다.
create function private.assert_reply_extra_trackings(p_rows jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare row_value jsonb; shipment public.order_shipments; extras text[]; number text;
begin
  for row_value in select value from jsonb_array_elements(p_rows) loop
    if not (row_value ? 'extraTrackingNumbers') then continue; end if;
    select * into strict shipment from public.order_shipments where id = (row_value->>'reference')::uuid;
    extras := private.reply_extra_tracking_numbers(row_value->'extraTrackingNumbers', private.normalize_tracking_number(row_value->>'trackingNumber'));
    foreach number in array extras loop
      if shipment.status = 'ready' then
        if private.shipment_tracking_in_use_elsewhere(shipment.id, nullif(btrim(row_value->>'carrier'), ''), number) then
          raise check_violation using message = 'tracking_number_in_use'; end if;
      elsif not exists(select 1 from public.order_shipment_extra_trackings x where x.shipment_id = shipment.id
          and x.carrier = shipment.carrier and x.tracking_number = number) then
        raise check_violation using message = 'shipment_tracking_conflict';
      end if;
    end loop;
  end loop;
end $$

-- 반입이 끝난 행에 추가 운송장을 붙이고 결과 행에 extraTrackingNumbers를 싣는다. 성공한 행이면 모두 붙인다 — 합포장의 다른
-- 구성원 행이 먼저 묶음 전체를 발송해 이 행이 '그대로'(dispatched=false)로 끝나도 이 배송 건의 추가 운송장은 이번 회신의 것이다.
-- 반입 전 검사가 발송 대기 건은 다른 배송 건 번호가 아님을, 이미 발송된 건은 같은 번호가 이미 붙어 있음을 확인했으므로
-- 이미 발송된 건에는 새로 붙는 번호가 없다(덮어쓰거나 더하지 않는다). 결과 행 수·순서는 그대로다.
create function private.attach_reply_extra_trackings(p_rows jsonb, p_results jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare outcome jsonb; input jsonb; shipment public.order_shipments; extras text[]; number text; output jsonb := '[]'::jsonb;
  actor uuid := (select auth.uid()); added integer;
begin
  if jsonb_typeof(p_results) is distinct from 'array' then return p_results; end if;
  for outcome in select value from jsonb_array_elements(p_results) loop
    select r.value into input from jsonb_array_elements(p_rows) r where r.value->>'reference' = outcome->>'reference' limit 1;
    if outcome->>'ok' = 'true' and input is not null and input ? 'extraTrackingNumbers' then
      select * into strict shipment from public.order_shipments where id = (input->>'reference')::uuid;
      extras := private.reply_extra_tracking_numbers(input->'extraTrackingNumbers', shipment.tracking_number);
      added := 0;
      foreach number in array extras loop
        insert into public.order_shipment_extra_trackings(order_id, shipment_id, carrier, tracking_number, source, created_by)
        values (shipment.order_id, shipment.id, shipment.carrier, number, 'warehouse_reply', actor)
        on conflict (shipment_id, carrier, tracking_number) do nothing;
        if found then
          added := added + 1;
          insert into private.order_shipment_tracking_changes(order_id, shipment_id, action, carrier, tracking_number, source, actor_id)
          values (shipment.order_id, shipment.id, 'added', shipment.carrier, number, 'warehouse_reply', actor);
          insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.shipment.extra_tracking_added', 'order:' || shipment.order_id,
            jsonb_build_object('shipmentId', shipment.id, 'originName', shipment.origin_name_snapshot, 'carrier', shipment.carrier,
              'trackingNumber', number, 'source', 'warehouse_reply'));
        end if;
      end loop;
      outcome := outcome || jsonb_build_object('extraTrackingNumbers', to_jsonb(extras), 'extraTrackingsAdded', added);
    end if;
    output := output || jsonb_build_array(outcome);
  end loop;
  return output;
end $$

-- 4. 운영자 추가·삭제. 운송장 정정(admin_update_shipment_tracking)과 같은 출고 권한이고 사유가 필수다.
create function public.admin_add_shipment_extra_tracking(p_shipment_id uuid, p_carrier text, p_tracking_number text, p_reason text, p_operation_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; shipment public.order_shipments; carrier_value text := nullif(btrim(coalesce(p_carrier, '')), '');
  tracking_value text := private.normalize_tracking_number(p_tracking_number); reason_value text := nullif(btrim(coalesce(p_reason, '')), '');
  previous private.order_shipment_tracking_changes; added public.order_shipment_extra_trackings;
begin
  actor := private.require_operator_capability('sales.dispatch', false);
  if p_shipment_id is null or p_operation_id is null then raise invalid_parameter_value using message = 'invalid_extra_tracking'; end if;
  if reason_value is null or char_length(reason_value) > 500 then raise check_violation using message = 'extra_tracking_reason_required'; end if;
  if carrier_value is null or tracking_value is null or tracking_value !~ '^[A-Z0-9]{8,30}$' then
    raise check_violation using message = 'invalid_tracking_input'; end if;
  select * into previous from private.order_shipment_tracking_changes where operation_id = p_operation_id;
  if found then
    if previous.action <> 'added' or previous.shipment_id <> p_shipment_id or previous.carrier <> carrier_value
      or previous.tracking_number <> tracking_value or previous.actor_id is distinct from actor then
      raise check_violation using message = 'extra_tracking_operation_conflict'; end if;
    return jsonb_build_object('status', 'unchanged', 'shipmentId', previous.shipment_id, 'orderId', previous.order_id);
  end if;
  perform private.lock_parcel_shipment(p_shipment_id);
  select * into shipment from public.order_shipments where id = p_shipment_id;
  if shipment.status not in ('shipping', 'delivered') or exists(select 1 from public.orders where id = shipment.order_id and status = 'canceled') then
    raise check_violation using message = 'order_not_shipped'; end if;
  if shipment.tracking_number is null then raise check_violation using message = 'tracking_required'; end if;
  if not exists(select 1 from public.shipping_carriers where code = carrier_value and is_active) then
    raise check_violation using message = 'inactive_shipping_carrier'; end if;
  if carrier_value = shipment.carrier and tracking_value = shipment.tracking_number then
    raise check_violation using message = 'extra_tracking_is_representative'; end if;
  if exists(select 1 from public.order_shipment_extra_trackings where shipment_id = shipment.id and carrier = carrier_value and tracking_number = tracking_value) then
    raise check_violation using message = 'extra_tracking_duplicate'; end if;
  if (select count(*) from public.order_shipment_extra_trackings where shipment_id = shipment.id) >= 19 then
    raise check_violation using message = 'extra_tracking_limit'; end if;
  if private.shipment_tracking_in_use_elsewhere(shipment.id, carrier_value, tracking_value) then
    raise check_violation using message = 'tracking_number_in_use'; end if;
  insert into public.order_shipment_extra_trackings(order_id, shipment_id, carrier, tracking_number, source, created_by)
  values (shipment.order_id, shipment.id, carrier_value, tracking_value, 'operator', actor) returning * into added;
  insert into private.order_shipment_tracking_changes(order_id, shipment_id, action, carrier, tracking_number, source, reason, actor_id, operation_id)
  values (shipment.order_id, shipment.id, 'added', carrier_value, tracking_value, 'operator', reason_value, actor, p_operation_id);
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.shipment.extra_tracking_added', 'order:' || shipment.order_id,
    jsonb_build_object('shipmentId', shipment.id, 'originName', shipment.origin_name_snapshot, 'carrier', carrier_value,
      'trackingNumber', tracking_value, 'source', 'operator', 'reason', reason_value, 'operationId', p_operation_id));
  return jsonb_build_object('status', 'added', 'id', added.id, 'shipmentId', shipment.id, 'orderId', shipment.order_id);
end $$

create function public.admin_remove_shipment_extra_tracking(p_extra_tracking_id uuid, p_reason text, p_operation_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; extra public.order_shipment_extra_trackings; shipment public.order_shipments;
  reason_value text := nullif(btrim(coalesce(p_reason, '')), ''); previous private.order_shipment_tracking_changes;
begin
  actor := private.require_operator_capability('sales.dispatch', false);
  if p_extra_tracking_id is null or p_operation_id is null then raise invalid_parameter_value using message = 'invalid_extra_tracking'; end if;
  if reason_value is null or char_length(reason_value) > 500 then raise check_violation using message = 'extra_tracking_reason_required'; end if;
  select * into previous from private.order_shipment_tracking_changes where operation_id = p_operation_id;
  if found then
    if previous.action <> 'removed' or previous.actor_id is distinct from actor then
      raise check_violation using message = 'extra_tracking_operation_conflict'; end if;
    return jsonb_build_object('status', 'unchanged', 'shipmentId', previous.shipment_id, 'orderId', previous.order_id);
  end if;
  select * into extra from public.order_shipment_extra_trackings where id = p_extra_tracking_id;
  if not found then raise no_data_found using message = 'extra_tracking_not_found'; end if;
  perform private.lock_parcel_shipment(extra.shipment_id);
  select * into extra from public.order_shipment_extra_trackings where id = p_extra_tracking_id for update;
  if not found then raise no_data_found using message = 'extra_tracking_not_found'; end if;
  select * into shipment from public.order_shipments where id = extra.shipment_id;
  delete from public.order_shipment_extra_trackings where id = extra.id;
  insert into private.order_shipment_tracking_changes(order_id, shipment_id, action, carrier, tracking_number, source, reason, actor_id, operation_id)
  values (extra.order_id, extra.shipment_id, 'removed', extra.carrier, extra.tracking_number, 'operator', reason_value, actor, p_operation_id);
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.shipment.extra_tracking_removed', 'order:' || extra.order_id,
    jsonb_build_object('shipmentId', extra.shipment_id, 'originName', shipment.origin_name_snapshot, 'carrier', extra.carrier,
      'trackingNumber', extra.tracking_number, 'reason', reason_value, 'operationId', p_operation_id));
  return jsonb_build_object('status', 'removed', 'shipmentId', extra.shipment_id, 'orderId', extra.order_id);
end $$

-- 6. 운영자 계약. 바꾼 함수는 등록된 능력·분류를 그대로 두고 지문만 다시 적는다. 새 RPC는 출고 권한이다.
do $contracts$
declare
  signature text;
  fn regprocedure;
  contract record;
begin
  foreach signature in array array[
    'public.admin_origin_tracking_candidates(uuid,text[],text[])',
    'public.admin_import_seowon_tracking_batch(uuid,jsonb)',
    'public.admin_search_order_items_console(text,date,date,text,integer,integer,text,text,text,text)'
  ] loop
    fn := signature::regprocedure;
    select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure = fn;
    if not found then raise exception 'shipment_extra_trackings_contract_missing: %', signature; end if;
    perform private.register_operator_rpc_contract(fn, contract.capability, contract.guard_kind, contract.legacy_admin_only);
  end loop;
  foreach signature in array array[
    'private.admin_search_shipments_console_before_custom_inputs(text,uuid,text,date,date,integer,integer,text,text,text,text,text)',
    'private.admin_sales_order_matches(public.orders,date,date,text,text,text,text)',
    'private.gift_detail(uuid,uuid)'
  ] loop
    fn := signature::regprocedure;
    if not exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure = fn) then
      raise exception 'shipment_extra_trackings_internal_contract_missing: %', signature; end if;
    perform private.register_operator_internal_contract(fn);
  end loop;
  perform private.register_operator_rpc_contract('public.admin_add_shipment_extra_tracking(uuid,text,text,text,uuid)'::regprocedure, 'sales.dispatch', 'write', false);
  perform private.register_operator_rpc_contract('public.admin_remove_shipment_extra_tracking(uuid,text,uuid)'::regprocedure, 'sales.dispatch', 'write', false);
  perform private.register_operator_policy_contract('public.order_shipment_extra_trackings'::regclass, 'order_shipment_extra_trackings_owner_staff_read', 'sales.read');
  perform private.register_operator_policy_contract('public.order_shipment_extra_trackings'::regclass, 'gift_shipment_extra_trackings_private_read', 'sales.read');
end $contracts$

-- 스위치 변경은 누가(migration·SQL 편집기 포함) 언제 바꿨는지 감사 기록에 남긴다. 행을 지우지 못하게 한다.
create function private.audit_delivery_tracking_settings() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then raise check_violation using message = 'delivery_tracking_settings_required'; end if;
  insert into public.audit_log(actor_id, action, target, diff) values (null, 'system.delivery_tracking.settings_changed', 'delivery_tracking_settings',
    jsonb_build_object('before', to_jsonb(old) - 'singleton', 'after', to_jsonb(new) - 'singleton', 'sessionUser', session_user::text));
  return new;
end $$

-- 6. 서비스 경로(service_role 전용 — 추적 cron만 부른다)
-- 이번 회차에 조회할 운송장. 꺼져 있으면 아무것도 고르지 않는다. 최근 30일 안에 발송한 배송 중 택배 건의 운송장 가운데
-- 기준 시각 이후 아직 배달완료가 아니고 조회 간격이 지난 것을, 오래 조회하지 않은 것부터 고른다.
create function public.service_delivery_tracking_targets(p_limit integer) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare settings private.delivery_tracking_settings;
begin
  if p_limit is null or p_limit not between 1 and 200 then raise invalid_parameter_value using message = 'invalid_delivery_tracking_limit'; end if;
  select * into settings from private.delivery_tracking_settings where singleton;
  if not found or not settings.auto_delivery_enabled then return jsonb_build_object('enabled', false); end if;
  return jsonb_build_object('enabled', true, 'provider', settings.provider, 'targets', coalesce((
    select jsonb_agg(jsonb_build_object('carrier', due.carrier, 'trackingNumber', due.tracking_number) order by due.polled_at nulls first, due.shipped_at, due.carrier, due.tracking_number)
    from (
      select tracking.carrier, tracking.tracking_number, min(s.shipped_at) shipped_at, max(poll.last_polled_at) polled_at
      from public.order_shipments s join public.orders o on o.id = s.order_id
      cross join lateral private.shipment_current_trackings(s.id) tracking
      left join private.shipment_tracking_polls poll on poll.carrier = tracking.carrier and poll.tracking_number = tracking.tracking_number
      where s.status = 'shipping' and s.delivery_method = 'parcel' and o.status <> 'canceled' and s.shipped_at >= now() - interval '30 days'
        and (poll.last_polled_at is null or poll.last_polled_at < now() - make_interval(mins => settings.poll_interval_minutes))
        and (private.tracking_latest_event(tracking.carrier, tracking.tracking_number, tracking.since)).status is distinct from 'delivered'
      group by tracking.carrier, tracking.tracking_number
      order by max(poll.last_polled_at) nulls first, min(s.shipped_at), tracking.carrier, tracking.tracking_number
      limit p_limit
    ) due), '[]'::jsonb));
end $$

-- 조회 결과를 남긴다. results: [{carrier, trackingNumber, outcome: ok|not_found|error, errorCode?, events: [...]}].
-- 이벤트: {eventKey, status, occurredAt, description?, location?, raw{}}. 지금 배송 건에 붙어 있지 않은 운송장은 무시한다(ignored).
-- 한 운송장의 결과나 이벤트 하나라도 형식이 틀리면(하루 넘게 미래인 시각 포함) 그 운송장의 이벤트는 남기지 않고 조회 오류
-- (invalid_event)로 기록한다 — 나쁜 이벤트 하나가 회차 전체의 기록·판정을 막지 않는다. 운송장을 알아볼 수 없는 결과는 세기만 한다.
-- 원본이 8KB를 넘으면 원본 대신 잘렸다는 표시만 남긴다. 결과 목록 자체가 틀린 모양이면(배열 아님·200개 초과) 거절한다.
create function public.service_record_delivery_tracking(p_provider text, p_results jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare settings private.delivery_tracking_settings; result jsonb; event jsonb; carrier_value text; tracking_value text;
  outcome_value text; error_value text; occurred timestamptz; valid boolean; payload_value jsonb;
  recorded integer := 0; duplicates integer := 0; ignored integer := 0; invalid integer := 0;
begin
  select * into settings from private.delivery_tracking_settings where singleton;
  if not found or not settings.auto_delivery_enabled then raise check_violation using message = 'delivery_tracking_disabled'; end if;
  if p_provider is distinct from settings.provider then raise check_violation using message = 'delivery_tracking_provider_mismatch'; end if;
  if jsonb_typeof(p_results) is distinct from 'array' or jsonb_array_length(p_results) > 200 then
    raise invalid_parameter_value using message = 'invalid_delivery_tracking_results'; end if;
  for result in select value from jsonb_array_elements(p_results) loop
    if jsonb_typeof(result) is distinct from 'object' or jsonb_typeof(result->'carrier') is distinct from 'string'
      or jsonb_typeof(result->'trackingNumber') is distinct from 'string' then invalid := invalid + 1; continue; end if;
    carrier_value := result->>'carrier';
    tracking_value := private.normalize_tracking_number(result->>'trackingNumber');
    if tracking_value is null or tracking_value !~ '^[A-Z0-9]{8,30}$' then invalid := invalid + 1; continue; end if;
    if not exists(select 1 from public.order_shipments s where s.carrier = carrier_value and s.tracking_number = tracking_value and s.delivery_method = 'parcel')
      and not exists(select 1 from public.order_shipment_extra_trackings x where x.carrier = carrier_value and x.tracking_number = tracking_value) then
      ignored := ignored + 1; continue;
    end if;
    outcome_value := result->>'outcome';
    error_value := null;
    valid := coalesce(outcome_value, '') in ('ok','not_found','error')
      and (not (result ? 'events') or (jsonb_typeof(result->'events') = 'array' and jsonb_array_length(result->'events') <= 100));
    if valid and outcome_value = 'error' then
      error_value := coalesce(nullif(result->>'errorCode', ''), 'upstream_error');
      if error_value !~ '^[a-z0-9_]{1,64}$' then error_value := 'upstream_error'; end if;
    end if;
    if valid then
      for event in select value from jsonb_array_elements(coalesce(result->'events', '[]'::jsonb)) loop
        if jsonb_typeof(event) is distinct from 'object' or jsonb_typeof(event->'eventKey') is distinct from 'string'
          or char_length(event->>'eventKey') not between 1 and 200
          or coalesce(event->>'status', '') not in ('accepted','in_transit','out_for_delivery','delivered','exception','returned','unknown')
          or jsonb_typeof(event->'occurredAt') is distinct from 'string' or jsonb_typeof(event->'raw') is distinct from 'object' then
          valid := false; exit;
        end if;
        begin occurred := (event->>'occurredAt')::timestamptz;
        exception when others then valid := false;
        end;
        -- 추적 서비스 시계가 하루 넘게 앞선 시각은 받지 않는다(배송완료 시각은 지금을 넘지 않게 따로 자른다).
        if not valid or occurred > now() + interval '1 day' then valid := false; exit; end if;
      end loop;
    end if;
    if not valid then
      invalid := invalid + 1; outcome_value := 'error'; error_value := 'invalid_event';
    else
      for event in select value from jsonb_array_elements(coalesce(result->'events', '[]'::jsonb)) loop
        payload_value := case when octet_length((event->'raw')::text) <= 8192 then event->'raw' else '{"truncated": true}'::jsonb end;
        insert into private.shipment_tracking_events(provider, carrier, tracking_number, event_key, status, occurred_at, description, location, payload)
        values (p_provider, carrier_value, tracking_value, event->>'eventKey', event->>'status', (event->>'occurredAt')::timestamptz,
          nullif(left(event->>'description', 200), ''), nullif(left(event->>'location', 100), ''), payload_value)
        on conflict (provider, carrier, tracking_number, event_key) do nothing;
        if found then recorded := recorded + 1; else duplicates := duplicates + 1; end if;
      end loop;
    end if;
    insert into private.shipment_tracking_polls(carrier, tracking_number, last_polled_at, last_outcome, last_error_code, consecutive_failures)
    values (carrier_value, tracking_value, now(), outcome_value, error_value, case when outcome_value = 'error' then 1 else 0 end)
    on conflict (carrier, tracking_number) do update set last_polled_at = excluded.last_polled_at, last_outcome = excluded.last_outcome,
      last_error_code = excluded.last_error_code,
      consecutive_failures = case when excluded.last_outcome = 'error' then private.shipment_tracking_polls.consecutive_failures + 1 else 0 end;
  end loop;
  return jsonb_build_object('recorded', recorded, 'duplicates', duplicates, 'ignored', ignored, 'invalid', invalid);
end $$

-- 모든 운송장이 기준 시각 이후 배달완료인 배송 중 택배 건을 배송완료로 바꾼다. 운영 배송완료(admin_update_shipment_status)와 같은 전이
-- 규칙이다: 발주확인 이후 주문, 배송 중 → 배송완료, 택배만, 합포장은 묶음 전체.
-- 잠금: 이번 회차 후보(합포장 묶음 포함)의 주문을 id 순으로, 그다음 배송 건을 id 순으로 — 운영자 일괄 처리(lock_shipment_pack_scope)와
-- 같은 전역 순서로 — 기다리지 않고(skip locked) 잡히는 것만 잡는다. 이 회차는 어떤 잠금도 기다리지 않으므로 운영자 일괄 배송완료·운송장
-- 일괄 등록과 교착이 생기지 않고, 잡지 못한 묶음은 보류 없이 다음 회차에 다시 본다. 묶음마다 저장점을 두어 한 건의 실패가 다른 건을 막지 않는다.
create function public.service_complete_tracked_deliveries(p_limit integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare settings private.delivery_tracking_settings; candidates uuid[]; scopes jsonb := '{}'::jsonb; candidate uuid; scope uuid[];
  scope_ids uuid[] := '{}'::uuid[]; locked_orders uuid[] := '{}'::uuid[]; locked_shipments uuid[] := '{}'::uuid[]; locked record;
  processed uuid[] := '{}'::uuid[]; latest_at timestamptz; basis_value jsonb; member record; delivered_value timestamptz;
  completed jsonb := '[]'::jsonb; held jsonb := '[]'::jsonb; skipped integer := 0;
begin
  if p_limit is null or p_limit not between 1 and 200 then raise invalid_parameter_value using message = 'invalid_delivery_tracking_limit'; end if;
  select * into settings from private.delivery_tracking_settings where singleton;
  if not found or not settings.auto_delivery_enabled then
    return jsonb_build_object('enabled', false, 'completed', '[]'::jsonb, 'held', '[]'::jsonb, 'skipped', 0); end if;
  -- 잡은 뒤 트리거 등이 다른 잠금을 오래 기다리지 않게 한다(그 묶음은 다음 회차에).
  perform set_config('lock_timeout', '3s', true);
  -- 1) 후보는 잠그지 않고 발송 순으로 고른다.
  select coalesce(array_agg(c.id order by c.shipped_at, c.id), '{}'::uuid[]) into candidates from (
    select s.id, s.shipped_at from public.order_shipments s join public.orders o on o.id = s.order_id
    where s.status = 'shipping' and s.delivery_method = 'parcel' and s.tracking_number is not null and s.shipped_at is not null
      and o.status in ('confirmed','shipping','delivered')
      and not exists(select 1 from private.shipment_auto_deliveries a where a.shipment_id = s.id and a.state = 'held' and a.updated_at > now() - interval '6 hours')
      and private.shipment_trackings_delivered(s.id)
    order by s.shipped_at, s.id limit p_limit) c;
  -- 2) 후보마다 합포장 묶음(잠근 뒤 바뀌었는지 다시 본다).
  foreach candidate in array candidates loop
    scope := private.shipment_pack_scope(array[candidate]);
    scopes := scopes || jsonb_build_object(candidate::text, to_jsonb(scope));
    scope_ids := scope_ids || scope;
  end loop;
  -- 3) 전역 순서(주문 id → 배송 건 id)로, 기다리지 않고 잡을 수 있는 것만 잡는다.
  for locked in select o.id from public.orders o
    where o.id in (select s.order_id from public.order_shipments s where s.id = any(scope_ids)) order by o.id for update skip locked loop
    locked_orders := locked_orders || locked.id;
  end loop;
  for locked in select s.id from public.order_shipments s where s.id = any(scope_ids) and s.order_id = any(locked_orders)
    order by s.id for update skip locked loop
    locked_shipments := locked_shipments || locked.id;
  end loop;
  -- 4) 묶음별로 다시 보고 바꾼다.
  foreach candidate in array candidates loop
    if candidate = any(processed) then continue; end if;
    scope := array(select value::uuid from jsonb_array_elements_text(scopes->(candidate::text)) value);
    processed := processed || scope;
    if not (scope <@ locked_shipments) then skipped := skipped + 1; continue; end if;
    begin
      -- 잡은 뒤 다시 본다. 묶음이 바뀌었거나, 묶음의 다른 배송 건이 아직이거나, 상태가 바뀌었으면 이번에는 넘긴다(보류 아님).
      if private.shipment_pack_scope(array[candidate]) is distinct from scope
        or exists(select 1 from public.order_shipments s join public.orders o on o.id = s.order_id where s.id = any(scope)
          and (s.status <> 'shipping' or s.delivery_method <> 'parcel' or s.tracking_number is null or s.shipped_at is null
            or o.status not in ('confirmed','shipping','delivered')))
        or exists(select 1 from unnest(scope) member_id where not private.shipment_trackings_delivered(member_id)) then
        skipped := skipped + 1; continue;
      end if;
      select max(e.occurred_at), jsonb_agg(jsonb_build_object('shipmentId', t.shipment_id, 'carrier', t.carrier, 'trackingNumber', t.tracking_number,
          'eventId', e.id, 'provider', e.provider, 'occurredAt', e.occurred_at, 'since', t.since) order by t.shipment_id, t.carrier, t.tracking_number)
        into latest_at, basis_value
      from (select member_id shipment_id, tracking.carrier, tracking.tracking_number, tracking.since from unnest(scope) member_id
        cross join lateral private.shipment_current_trackings(member_id) tracking) t
      cross join lateral private.tracking_latest_event(t.carrier, t.tracking_number, t.since) e;
      for member in select s.* from public.order_shipments s where s.id = any(scope) order by s.id loop
        -- 가장 늦은 도착 시각(모든 근거가 기준 시각 = 출고지시·발주확인 이후다. 회신 등록이 늦어도 배송완료 시각은 등록 시각 밑으로 내리지 않는다). 추적 시계가 앞서도 지금을 넘지 않는다(청약철회·자동 구매확정 기산).
        delivered_value := least(greatest(latest_at, member.shipped_at), clock_timestamp());
        update public.order_shipments set status = 'delivered', delivered_at = delivered_value, updated_at = clock_timestamp() where id = member.id;
        insert into private.shipment_auto_deliveries(shipment_id, state, delivered_at, provider, basis, attempts, last_error, updated_at)
        values (member.id, 'completed', delivered_value, settings.provider, coalesce((select jsonb_agg(entry) from jsonb_array_elements(basis_value) entry
          where entry->>'shipmentId' = member.id::text), '[]'::jsonb), 1, null, now())
        on conflict (shipment_id) do update set state = 'completed', delivered_at = excluded.delivered_at, provider = excluded.provider,
          basis = excluded.basis, attempts = private.shipment_auto_deliveries.attempts + 1, last_error = null, updated_at = now();
        insert into public.audit_log(actor_id, action, target, diff) values (null, 'system.shipment.tracking_delivered', 'order:' || member.order_id,
          jsonb_build_object('shipmentId', member.id, 'originName', member.origin_name_snapshot, 'from', 'shipping', 'to', 'delivered',
            'deliveredAt', delivered_value, 'provider', settings.provider, 'carrier', member.carrier, 'trackingNumber', member.tracking_number,
            'trackings', (select jsonb_agg(entry - 'shipmentId') from jsonb_array_elements(basis_value) entry where entry->>'shipmentId' = member.id::text)));
        completed := completed || jsonb_build_array(jsonb_build_object('shipmentId', member.id, 'orderId', member.order_id, 'deliveredAt', delivered_value));
      end loop;
    exception when lock_not_available or deadlock_detected then
      -- 트리거가 다른 잠금을 기다리다 넘은 건은 보류로 남기지 않는다(다음 회차에 그대로 다시 본다).
      skipped := skipped + 1;
    when others then
      -- 바꾸지 못한 이유(취소·반품 진행, 묶음 변경 등)를 남기고 6시간 뒤 다시 본다. 운영자는 배송현황에서 수동으로 처리할 수 있다.
      insert into private.shipment_auto_deliveries(shipment_id, state, attempts, last_error, updated_at)
      values (candidate, 'held', 1, left(sqlerrm, 200), now())
      on conflict (shipment_id) do update set state = 'held', attempts = private.shipment_auto_deliveries.attempts + 1,
        last_error = excluded.last_error, updated_at = now()
      where private.shipment_auto_deliveries.state <> 'completed';
      held := held || jsonb_build_array(jsonb_build_object('shipmentId', candidate, 'error', left(sqlerrm, 200)));
    end;
  end loop;
  return jsonb_build_object('enabled', true, 'completed', completed, 'held', held, 'skipped', skipped);
end $$

-- 7. 배송현황 표시. 추가 운송장은 늘, 자동·수동 구분과 추적 진행은 스위치가 켜진 때만 싣는다(꺼져 있으면 화면이 그대로다).
-- 추적 진행은 판정과 같은 기준 시각 이후 이벤트만 센다.
create function public.admin_shipment_tracking_summaries(p_ids uuid[]) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare enabled boolean;
begin
  if (select auth.uid()) is null or not public.has_operator_capability('sales.dispatch', false) then
    raise insufficient_privilege using message = 'operator_capability_required'; end if;
  if p_ids is null or cardinality(p_ids) > 1000 or array_position(p_ids, null) is not null then
    raise invalid_parameter_value using message = 'invalid_shipment_selection'; end if;
  enabled := coalesce((select auto_delivery_enabled from private.delivery_tracking_settings where singleton), false);
  return jsonb_build_object('autoDelivery', enabled, 'shipments', coalesce((select jsonb_object_agg(s.id, jsonb_build_object(
    'extraTrackings', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'carrier', x.carrier, 'trackingNumber', x.tracking_number,
        'source', x.source, 'createdAt', x.created_at) order by x.created_at, x.id)
      from public.order_shipment_extra_trackings x where x.shipment_id = s.id), '[]'::jsonb),
    'deliveredBy', case when not enabled or s.status <> 'delivered' or s.delivery_method <> 'parcel' then null
      when exists(select 1 from private.shipment_auto_deliveries a where a.shipment_id = s.id and a.state = 'completed'
        and a.delivered_at = s.delivered_at) then 'tracking' else 'manual' end,
    'tracking', case when not enabled or s.status <> 'shipping' or s.delivery_method <> 'parcel' or s.tracking_number is null then null
      else (select jsonb_build_object('total', count(*), 'delivered', count(*) filter (where latest.status = 'delivered'),
          'latestStatus', (array_agg(latest.status order by latest.occurred_at desc nulls last))[1],
          'latestAt', max(latest.occurred_at),
          'held', exists(select 1 from private.shipment_auto_deliveries a where a.shipment_id = s.id and a.state = 'held'))
        from private.shipment_current_trackings(s.id) t cross join lateral private.tracking_latest_event(t.carrier, t.tracking_number, t.since) latest) end))
    from public.order_shipments s where s.id = any(p_ids)), '{}'::jsonb));
end $$

-- 주소록 저장. 새 주소는 p_id null·p_expected_updated_at null, 수정은 둘 다 필요하다(낙관적 잠금).
create function public.admin_save_return_address(p_id uuid,p_values jsonb,p_expected_updated_at timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());previous public.return_addresses;saved public.return_addresses;
 name_value text;address_value text;phone_value text;
begin
 perform private.require_operator_capability('platform.manage',true);
 if actor is null then raise insufficient_privilege using message='admin_required';end if;
 if jsonb_typeof(p_values) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_values) k where k not in('name','address','phone'))
  or jsonb_typeof(p_values->'name') is distinct from 'string' or jsonb_typeof(p_values->'address') is distinct from 'string'
  or jsonb_typeof(p_values->'phone') is distinct from 'string' then
  raise invalid_parameter_value using message='invalid_return_address';end if;
 name_value:=btrim(p_values->>'name');address_value:=btrim(p_values->>'address');phone_value:=btrim(p_values->>'phone');
 if char_length(name_value) not between 1 and 60 or char_length(address_value) not between 1 and 500
  or name_value ~ '[[:cntrl:]]' or address_value ~ '[[:cntrl:]]' or phone_value !~ '^[0-9][0-9-]{6,18}[0-9]$' or phone_value ~ '--' then
  raise invalid_parameter_value using message='invalid_return_address';end if;
 if p_id is null then
  if p_expected_updated_at is not null then raise invalid_parameter_value using message='invalid_return_address';end if;
  if exists(select 1 from public.return_addresses where name=name_value) then raise unique_violation using message='return_address_name_taken';end if;
  insert into public.return_addresses(name,address,phone,updated_by) values(name_value,address_value,phone_value,actor) returning * into saved;
 else
  select * into previous from public.return_addresses where id=p_id for update;
  if not found then raise no_data_found using message='return_address_not_found';end if;
  if p_expected_updated_at is null or previous.updated_at is distinct from p_expected_updated_at then
   raise sqlstate 'PT409' using message='return_address_conflict';end if;
  if exists(select 1 from public.return_addresses where name=name_value and id<>p_id) then raise unique_violation using message='return_address_name_taken';end if;
  if previous.name=name_value and previous.address=address_value and previous.phone=phone_value then
   return jsonb_build_object('id',previous.id,'updatedAt',previous.updated_at,'replayed',true);end if;
  update public.return_addresses set name=name_value,address=address_value,phone=phone_value,updated_by=actor,
   updated_at=greatest(clock_timestamp(),previous.updated_at+interval '1 microsecond') where id=p_id returning * into saved;
 end if;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.return_address.saved','return_addresses:'||saved.id,
  jsonb_build_object('before',case when previous.id is null then null else jsonb_build_object('name',previous.name,'address',previous.address,'phone',previous.phone) end,
   'after',jsonb_build_object('name',saved.name,'address',saved.address,'phone',saved.phone)));
 return jsonb_build_object('id',saved.id,'updatedAt',saved.updated_at,'replayed',false);
exception when unique_violation then
 -- 같은 이름의 동시 등록은 이름 유일 제약이 막는다. 화면에는 같은 문구로 돌려준다.
 if sqlerrm='return_address_name_taken' or sqlerrm like '%return_addresses_name_key%' then raise unique_violation using message='return_address_name_taken';end if;
 raise;
end $$

-- 주소록 삭제. 상품이 고른 주소는 지울 수 없다(상품에서 먼저 비운다). 이미 접수된 클레임의 회수 묶음은
-- 스냅샷이라 삭제와 무관하다.
create function public.admin_delete_return_address(p_id uuid,p_expected_updated_at timestamptz)
returns boolean language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());previous public.return_addresses;
begin
 perform private.require_operator_capability('platform.manage',true);
 if actor is null then raise insufficient_privilege using message='admin_required';end if;
 select * into previous from public.return_addresses where id=p_id for update;
 if not found then raise no_data_found using message='return_address_not_found';end if;
 if p_expected_updated_at is null or previous.updated_at is distinct from p_expected_updated_at then
  raise sqlstate 'PT409' using message='return_address_conflict';end if;
 if exists(select 1 from public.goods where return_address_id=p_id) then raise foreign_key_violation using message='return_address_in_use';end if;
 begin
  delete from public.return_addresses where id=p_id;
 exception when foreign_key_violation then raise foreign_key_violation using message='return_address_in_use';
 end;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.return_address.deleted','return_addresses:'||p_id,
  jsonb_build_object('before',jsonb_build_object('name',previous.name,'address',previous.address,'phone',previous.phone)));
 return true;
end $$

-- 상품 저장: 반품·교환 조건과 같은 칸 묶음으로 반품지를 받는다(최소 앵커 치환 — T15b가 섹션 호출로 이어받는다).
do $migration$
declare definition text:=pg_get_functiondef('public.admin_save_good_claim_policy(text,jsonb,timestamptz)'::regprocedure);
 anchors text[]:=array[
  $a$next_free_return_fee bigint; next_exchange_fee bigint;$a$,
  $a$where key not in ('returnAllowed','exchangeAllowed','restrictionReason','returnFee','returnFreeShippingFee','exchangeFee')) then$a$,
  $a$  if target_policy ? 'restrictionReason' and jsonb_typeof(target_policy->'restrictionReason') not in ('string','null') then
    raise invalid_parameter_value using message='invalid_good_claim_policy';
  end if;$a$,
  $a$  next_exchange_fee:=case when target_policy?'exchangeFee' then (target_policy->>'exchangeFee')::bigint else previous.claim_exchange_fee end;$a$,
  $a$'returnFreeShippingFee',previous.claim_return_free_shipping_fee,'exchangeFee',previous.claim_exchange_fee);$a$,
  $a$'returnFee',next_return_fee,'returnFreeShippingFee',next_free_return_fee,'exchangeFee',next_exchange_fee);$a$,
  $a$claim_exchange_fee=next_exchange_fee where id=target_good_id returning * into saved;$a$];
 replacements text[]:=array[
  $a$next_free_return_fee bigint; next_exchange_fee bigint; next_return_address uuid;$a$,
  $a$where key not in ('returnAllowed','exchangeAllowed','restrictionReason','returnFee','returnFreeShippingFee','exchangeFee','returnAddressId')) then$a$,
  $a$  if target_policy ? 'restrictionReason' and jsonb_typeof(target_policy->'restrictionReason') not in ('string','null') then
    raise invalid_parameter_value using message='invalid_good_claim_policy';
  end if;
  -- 반품/교환지(S36-040): 주소록 id 또는 null(출고지 반품 주소).
  if target_policy ? 'returnAddressId' and not (jsonb_typeof(target_policy->'returnAddressId')='null'
    or (jsonb_typeof(target_policy->'returnAddressId')='string'
      and target_policy->>'returnAddressId' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')) then
    raise invalid_parameter_value using message='invalid_good_claim_policy';
  end if;$a$,
  $a$  next_exchange_fee:=case when target_policy?'exchangeFee' then (target_policy->>'exchangeFee')::bigint else previous.claim_exchange_fee end;
  next_return_address:=case when target_policy?'returnAddressId' then (target_policy->>'returnAddressId')::uuid else previous.return_address_id end;
  -- 잠금 순서: 상품(위 for update) → 주소록(for share). 승인 스냅샷(prepare_claim_collections)도 같은 순서다.
  if next_return_address is not null then
    perform 1 from public.return_addresses where id=next_return_address for share;
    if not found then raise check_violation using message='return_address_not_found'; end if;
  end if;$a$,
  $a$'returnFreeShippingFee',previous.claim_return_free_shipping_fee,'exchangeFee',previous.claim_exchange_fee,'returnAddressId',previous.return_address_id);$a$,
  $a$'returnFee',next_return_fee,'returnFreeShippingFee',next_free_return_fee,'exchangeFee',next_exchange_fee,'returnAddressId',next_return_address);$a$,
  $a$claim_exchange_fee=next_exchange_fee,return_address_id=next_return_address where id=target_good_id returning * into saved;$a$];
 i integer;
begin
 for i in 1..array_length(anchors,1) loop
  if (length(definition)-length(replace(definition,anchors[i],'')))/length(anchors[i])<>1 then
   raise exception 'admin_save_good_claim_policy anchor % must appear once',i;end if;
  definition:=replace(definition,anchors[i],replacements[i]);
 end loop;
 execute definition;
end $migration$

-- 공개 상세의 회수 주소: 상품 반품지가 있으면 그 주소, 없으면 출고지 반품 주소(T19 본문 위 앵커 치환).
do $migration$
declare definition text:=pg_get_functiondef('public.get_good_shipping_policy(text)'::regprocedure);
 address_anchor text:=$a$'returnAddress', origin.return_address,$a$;
 address_replacement text:=$a$'returnAddress', coalesce(return_place.address, origin.return_address),$a$;
 join_anchor text:=$a$join public.fulfillment_origins origin on origin.id = policy_good.origin_id and origin.is_active$a$;
 join_replacement text:=$a$join public.fulfillment_origins origin on origin.id = policy_good.origin_id and origin.is_active
