-- 재정의한 함수의 등록된 계약을 새 본문·ACL로 다시 적는다(분류는 기존 행 그대로).
do $$declare fn regprocedure;contract record;begin
 foreach fn in array array[
  'public.admin_save_good_claim_policy(text,jsonb,timestamptz)'::regprocedure,
  'public.get_good_shipping_policy(text)'::regprocedure,
  'private.admin_clone_good_before_discount_display(uuid,text,text,text,text)'::regprocedure,
  'private.create_goods_group_product(text,uuid,text,uuid)'::regprocedure] loop
  select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure=fn;
  if found then perform private.register_operator_rpc_contract(fn,contract.capability,contract.guard_kind,contract.legacy_admin_only);
  elsif exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure=fn) then
   perform private.register_operator_internal_contract(fn);
  end if;
 end loop;
end $$

-- 승인 스냅샷: 배송 건 행(지금까지와 같은 키)과 그 아래 반품지별 묶음을 함께 만든다.
create or replace function private.prepare_claim_collections(target_claim uuid,require_address boolean default true) returns void
language plpgsql security invoker set search_path='' as $$
declare claim public.order_cancellation_requests;
begin
 select * into claim from public.order_cancellation_requests where id=target_claim;
 if claim.collection_policy<>'origin' or not claim.collection_required then return; end if;
 -- Caller owns order → shipment → claim locks. 회수지 설정(출고지 반품 주소 → 상품 반품지 → 주소록)이 스냅샷 도중
 -- 바뀌지 않게 이 순서로 UUID·ID 순 공유 잠금한다. 상품 저장(admin_save_good_claim_policy)도 상품 → 주소록 순서다.
 perform o.id from public.fulfillment_origins o where o.id in(select s.origin_id from public.order_shipments s where s.order_id=claim.order_id and s.delivery_method<>'digital') order by o.id for share;
 perform g.id from public.goods g where g.id in(select i.good_id from public.order_items i where i.order_id=claim.order_id) order by g.id for share;
 perform r.id from public.return_addresses r where r.id in(select g.return_address_id from public.goods g join public.order_items i on i.good_id=g.id
  where i.order_id=claim.order_id) order by r.id for share;
 if require_address and exists(select 1 from private.claim_shipment_return_lines(claim.order_id) l where btrim(l.return_address)='') then
   raise check_violation using message='claim_return_address_required'; end if;
 insert into public.order_claim_collections(claim_id,shipment_id,origin_id,origin_name_snapshot,return_address_snapshot,items_snapshot)
 select claim.id,s.id,s.origin_id,s.origin_name_snapshot,
   coalesce((select string_agg(d.return_address,' / ' order by d.first_item) from(select l.return_address,min(l.order_item_id::text) first_item
     from private.claim_shipment_return_lines(claim.order_id) l where l.shipment_id=s.id and btrim(l.return_address)<>'' group by l.return_address) d),''),
   (select jsonb_agg(jsonb_build_object('orderItemId',i.id,'name',i.good_name_snapshot,'qty',link.qty) order by i.id)
    from public.order_shipment_items link join public.order_items i on i.id=link.order_item_id where link.shipment_id=s.id)
 from public.order_shipments s
 where s.order_id=claim.order_id and s.delivery_method<>'digital' and exists(select 1 from public.order_shipment_items i where i.shipment_id=s.id)
 on conflict(claim_id,shipment_id) do nothing;
 insert into public.order_claim_collection_bundles(claim_id,shipment_id,return_address_id,return_name_snapshot,return_address_snapshot,return_phone_snapshot,items_snapshot)
 select claim.id,l.shipment_id,l.return_address_id,min(l.return_name),min(l.return_address),min(l.return_phone),
   jsonb_agg(jsonb_build_object('orderItemId',l.order_item_id,'name',l.item_name,'qty',l.qty) order by l.order_item_id)
 from private.claim_shipment_return_lines(claim.order_id) l
 -- 묶음은 배송 건 행을 처음 만들 때 한 번만 나눈다(다시 불려도 이미 나눈 묶음에 품목을 겹쳐 넣지 않는다).
 where exists(select 1 from public.order_claim_collections x where x.claim_id=claim.id and x.shipment_id=l.shipment_id)
  and not exists(select 1 from public.order_claim_collection_bundles b where b.claim_id=claim.id and b.shipment_id=l.shipment_id)
 group by l.shipment_id,l.return_address_id
 on conflict on constraint order_claim_collection_bundles_destination_key do nothing;
 if require_address and not exists(select 1 from public.order_claim_collections where claim_id=target_claim) then
   raise check_violation using message='claim_collections_incomplete'; end if;
end $$

-- 회수 확인의 단일 지점. 묶음 id가 없으면 배송 건의 유일한 묶음을 확인한다(묶음이 둘 이상이면 묶음을 골라야 한다).
-- 배송 건의 모든 묶음이 입고되면 배송 건 행을 회수 완료로 적고, 클레임 회수 완료는 private.complete_order_claim_collection이 정한다.
create function private.record_order_claim_collection_bundle(p_claim_id uuid,p_shipment_id uuid,p_bundle_id uuid,p_evidence text,p_received_on date)
returns text language plpgsql security invoker set search_path='' as $$
declare actor uuid:=(select auth.uid());claim public.order_cancellation_requests;collection public.order_claim_collections;
 bundle public.order_claim_collection_bundles;order_key uuid;shipment_key uuid:=p_shipment_id;address_value text;bundle_count integer;
 order_day date;today date:=(clock_timestamp() at time zone 'Asia/Seoul')::date;received date;shipment_collected boolean:=false;
begin
 if p_evidence is null or p_evidence<>btrim(p_evidence) or char_length(p_evidence) not between 1 and 500 or translate(p_evidence,E'\n\r\t','') ~ '[[:cntrl:]]' then
   raise check_violation using message='invalid_collection_evidence'; end if;
 select order_id into order_key from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found'; end if;
 select (created_at at time zone 'Asia/Seoul')::date into order_day from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 if claim.collection_policy<>'origin' or not claim.collection_required then raise check_violation using message='claim_type_has_no_collection'; end if;
 if p_bundle_id is not null then
   select b.shipment_id into shipment_key from public.order_claim_collection_bundles b where b.id=p_bundle_id and b.claim_id=p_claim_id;
   if not found or (p_shipment_id is not null and shipment_key<>p_shipment_id) then raise no_data_found using message='claim_collection_not_found'; end if;
 end if;
 -- 잠금 순서: 주문 → 배송 건 → 클레임 → 배송 건 회수 행 → 묶음(다른 클레임 함수의 배송 건 회수 행 잠금과 같은 순서).
 select * into collection from public.order_claim_collections where claim_id=p_claim_id and shipment_id=shipment_key for update;
 if not found then raise no_data_found using message='claim_collection_not_found'; end if;
 if p_bundle_id is null then
   select count(*) into bundle_count from public.order_claim_collection_bundles where claim_id=p_claim_id and shipment_id=shipment_key;
   if bundle_count=0 then
     -- 묶음 없이 남은 배송 건 행(배포 경합으로 옛 본문 승인이 만든 행)은 잠근 배송 건 행으로 기본 묶음 하나를 만든다(백필과 같은 값).
     insert into public.order_claim_collection_bundles(claim_id,shipment_id,return_address_id,return_name_snapshot,return_address_snapshot,
      return_phone_snapshot,items_snapshot) values(p_claim_id,shipment_key,null,'',collection.return_address_snapshot,'',collection.items_snapshot)
     on conflict on constraint order_claim_collection_bundles_destination_key do nothing;
     bundle_count:=1;
   end if;
   if bundle_count>1 then raise check_violation using message='claim_collection_bundle_required'; end if;
   select * into bundle from public.order_claim_collection_bundles where claim_id=p_claim_id and shipment_id=shipment_key for update;
 else
   select * into bundle from public.order_claim_collection_bundles where id=p_bundle_id for update;
 end if;
 if bundle.id is null then raise no_data_found using message='claim_collection_not_found'; end if;
 if bundle.collected_at is not null then
   -- 같은 근거·같은 입고일의 재전송은 멱등하다. 입고일 없이 부르는 옛 경로는 근거만 맞춰 본다.
   if bundle.evidence=p_evidence and (p_received_on is null or bundle.received_on is not distinct from p_received_on) then
     return case when private.claim_collections_complete(p_claim_id) then 'collected' else 'collecting' end; end if;
   raise unique_violation using message='claim_collection_conflict';
 end if;
 received:=coalesce(p_received_on,today);
 if received>today or received<order_day then raise check_violation using message='invalid_collection_received_on'; end if;
 if claim.stage not in ('collecting','collected','processing','needs_review') then raise exception using message='claim_not_collectable'; end if;
 address_value:=bundle.return_address_snapshot;
 if btrim(address_value)='' then
   -- 승인 때 출고지 반품 주소가 비어 있던 출고지 기본 묶음(이 기능 전 클레임 포함)만 지금 출고지 주소로 채운다.
   -- 상품 반품지 묶음은 주소록이 주소를 요구하므로 비지 않는다.
   select return_address into address_value from public.fulfillment_origins where id=collection.origin_id for share;
   if coalesce(btrim(address_value),'')='' then raise check_violation using message='claim_return_address_required'; end if;
 end if;
 update public.order_claim_collection_bundles set return_address_snapshot=address_value,collected_at=clock_timestamp(),collected_by=actor,
  evidence=p_evidence,received_on=received where id=bundle.id;
 if not exists(select 1 from public.order_claim_collection_bundles where claim_id=p_claim_id and shipment_id=shipment_key and collected_at is null) then
   shipment_collected:=true;
   update public.order_claim_collections set
     return_address_snapshot=case when btrim(return_address_snapshot)<>'' then return_address_snapshot
       else (select string_agg(distinct b.return_address_snapshot,' / ') from public.order_claim_collection_bundles b where b.claim_id=p_claim_id and b.shipment_id=shipment_key) end,
     collected_at=clock_timestamp(),collected_by=actor,evidence=p_evidence,
     received_on=(select max(coalesce(b.received_on,(b.collected_at at time zone 'Asia/Seoul')::date)) from public.order_claim_collection_bundles b
       where b.claim_id=p_claim_id and b.shipment_id=shipment_key)
   where claim_id=p_claim_id and shipment_id=shipment_key and collected_at is null;
 end if;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.claim_origin_collected','order:'||order_key::text,
  jsonb_build_object('claimId',p_claim_id,'shipmentId',shipment_key,'bundleId',bundle.id,'returnAddressId',bundle.return_address_id,
   'originId',collection.origin_id,'items',bundle.items_snapshot,'returnAddress',address_value,'evidence',p_evidence,
   'receivedOn',received,'shipmentCollected',shipment_collected,'collectionWaived',private.claim_collection_waived(p_claim_id,shipment_key)));
 -- 회수 완료는 회수가 끝날 때 한 번 적고 알린다(private.complete_order_claim_collection, ADR-0041 회수 생략 규칙 포함).
 perform private.complete_order_claim_collection(p_claim_id);
 return case when private.claim_collections_complete(p_claim_id) then 'collected' else 'collecting' end;
end $$

-- 배송 건 키(지금까지의 계약): 묶음이 하나인 배송 건을 확인한다.
create or replace function public.admin_record_order_claim_origin_collection(p_claim_id uuid, p_shipment_id uuid, p_evidence text, p_received_on date)
 returns text
 language plpgsql
 security definer
 set search_path to ''
as $function$
declare actor uuid:=(select auth.uid());
begin
 perform private.require_operator_capability('sales.manage',false);
 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required'; end if;
 if p_shipment_id is null then raise no_data_found using message='claim_collection_not_found'; end if;
 return private.record_order_claim_collection_bundle(p_claim_id,p_shipment_id,null,p_evidence,p_received_on);
end $function$

-- 회수 묶음 키: 반품지가 갈린 배송 건은 묶음마다 확인한다.
create function public.admin_record_order_claim_collection_bundle(p_claim_id uuid, p_bundle_id uuid, p_evidence text, p_received_on date)
 returns text
 language plpgsql
 security definer
 set search_path to ''
as $function$
declare actor uuid:=(select auth.uid());
begin
 perform private.require_operator_capability('sales.manage',false);
 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required'; end if;
 if p_bundle_id is null then raise no_data_found using message='claim_collection_not_found'; end if;
 return private.record_order_claim_collection_bundle(p_claim_id,null,p_bundle_id,p_evidence,p_received_on);
end $function$

-- 앵커 치환(재정의 최소화). 각 앵커는 정확히 한 번 나와야 한다.
create function pg_temp.patch_function(p_function regprocedure,p_anchor text,p_replacement text) returns void language plpgsql as $$
declare definition text:=pg_get_functiondef(p_function);
begin
 if (length(definition)-length(replace(definition,p_anchor,'')))/length(p_anchor)<>1 then
  raise exception '% anchor must appear once',p_function;end if;
 execute replace(definition,p_anchor,p_replacement);
end $$

-- 회수 묶음의 회수 주소 읽기(승인 뒤 배송 건마다). 본인(선물이면 받는 분)·운영자만, 보낸 분은 null. 묶음이 생기기 전(승인 전)은 빈 배열이다.
create function public.read_my_claim_return_bundles(p_claim uuid,p_actor uuid,p_session uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare viewer text;begin
 perform private.purchase_confirmation_identity(p_actor,p_session,false);
 select case when g.recipient_id=p_actor then 'recipient' when g.sender_id=p_actor then 'sender' when g.id is null and o.user_id=p_actor then 'buyer' end
 into viewer from public.order_cancellation_requests c join public.orders o on o.id=c.order_id left join private.gift_intents g on g.order_id=o.id where c.id=p_claim;
 if viewer is null then raise no_data_found using message='claim_not_found';end if;
 if viewer='sender' then return null;end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('shipmentId',x.shipment_id,'returnBundles',private.claim_collection_bundles_json(x.claim_id,x.shipment_id,false)) order by x.shipment_id),'[]'::jsonb)
  from public.order_claim_collections x where x.claim_id=p_claim);
end $$

create function public.admin_read_claim_return_bundles(p_claim uuid,p_actor uuid,p_session uuid) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 perform private.purchase_confirmation_identity(p_actor,p_session,true);
 return(select coalesce(jsonb_agg(jsonb_build_object('shipmentId',x.shipment_id,'returnBundles',private.claim_collection_bundles_json(x.claim_id,x.shipment_id,false)) order by x.shipment_id),'[]'::jsonb)
  from public.order_claim_collections x where x.claim_id=p_claim);
end $$

-- 일부만 입고된 배송 건은 회수 생략을 거절한다(회수 생략 결정·회수 생략 재출고 둘 다). 배송 건 행 입고는 기존 collection_waiver_not_needed가,
-- 묶음 일부 입고는 collection_waiver_partially_received가 막는다 — 입고된 묶음 품목이 재고 대조 회수 수량에서 사라지지 않게 한다.
select pg_temp.patch_function('private.record_claim_collection_waiver(public.order_cancellation_requests,uuid,text,uuid[],uuid,timestamptz)'::regprocedure,
 $a$if target.collected_at is not null then raise check_violation using message='collection_waiver_not_needed';end if;$a$,
 $a$if target.collected_at is not null then raise check_violation using message='collection_waiver_not_needed';end if;
 if private.claim_collection_partially_received(p_claim.id,p_shipment_id) then raise check_violation using message='collection_waiver_partially_received';end if;$a$)

select pg_temp.patch_function('private.record_order_claim_shipment_reshipment(uuid,uuid,text,text,jsonb,jsonb)'::regprocedure,
 $a$if target.collected_at is not null then raise check_violation using message='collection_waiver_not_needed';end if;$a$,
 $a$if target.collected_at is not null then raise check_violation using message='collection_waiver_not_needed';end if;
  if private.claim_collection_partially_received(p_claim_id,p_shipment_id) then raise check_violation using message='collection_waiver_partially_received';end if;$a$)

-- 기록된 행은 불변이다. 선택(planned)만 바꾸거나 지울 수 있고 기록은 planned → recorded 한 번뿐이다.
create function private.guard_claim_defective_stock() returns trigger
language plpgsql security invoker set search_path = '' as $$
begin
  if tg_op = 'DELETE' then
    if old.state = 'recorded' then raise check_violation using message = 'defective_stock_ledger_immutable'; end if;
    return old;
  end if;
  if old.state = 'recorded' then raise check_violation using message = 'defective_stock_ledger_immutable'; end if;
  if new.claim_id <> old.claim_id or new.order_item_id <> old.order_item_id or new.qty <> old.qty
    or new.planned_by <> old.planned_by or new.planned_at <> old.planned_at then
    raise check_violation using message = 'defective_stock_plan_fields_immutable';
  end if;
  return new;
end $$

-- restore_order_item_supply: 불량으로 고른 품목은 재고를 복원하지 않는다.
-- 앵커 치환으로 최소 변경한다(T12b도 이 함수를 고친다 — 앵커 한 줄만 더한다).
do $patch$
declare definition text; anchor text; patch text;
begin
  definition := pg_get_functiondef('private.restore_order_item_supply(uuid,text)'::regprocedure);
  anchor := E'\n affected:=target.hop_count>0';
  patch := E'\n -- 반품 불량 재고(QNA-035): 불량으로 고른 품목은 판매 재고로 되돌리지 않는다. 선택 행은 기록 뒤에도 남아 재호출에도 같다.\n'
    || E' if exists(select 1 from private.claim_defective_stock d join public.order_cancellation_requests c on c.id=d.claim_id\n'
    || E'  where d.order_item_id=item.id and c.claim_type=''return'' and c.stage not in (''rejected'',''withdrawn'')) then\n'
    || E'  if item.supply_source=''preorder'' then\n'
    || E'   update private.goods_preorder_reservations set state=''returned'',released_at=clock_timestamp(),released_by=auth.uid(),release_reason=reason_value where order_item_id=item.id;\n'
    || E'  end if;\n'
    || E'  return;\n'
    || E' end if;';
  if (length(definition) - length(replace(definition, anchor, ''))) / length(anchor) <> 1 then
    raise exception 'restore_order_item_supply anchor must match once';
  end if;
  execute replace(definition, anchor, patch || anchor);
end $patch$

-- 선택 저장. 재고가 정해지기 전(환불 확정·무통장 [취소 확정] 전)에만 부를 수 있다. 비어 있으면 모두 복원으로 되돌린다.
-- 잠금 순서는 주문 → 클레임이다(환불 확정·전환 함수와 같다).
create function public.admin_plan_claim_defective_stock(p_claim_id uuid, p_order_item_ids uuid[])
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare actor uuid; claim public.order_cancellation_requests; ord public.orders; ids uuid[]; item record; planned_count integer; target_order uuid;
begin
  actor := private.require_operator_capability('sales.manage', false);
  if p_claim_id is null or p_order_item_ids is null or cardinality(p_order_item_ids) > 200 then
    raise invalid_parameter_value using message = 'invalid_defective_stock_plan';
  end if;
  ids := coalesce(array(select distinct x from unnest(p_order_item_ids) x order by x), '{}');
  if exists(select 1 from unnest(ids) x where x is null) then raise invalid_parameter_value using message = 'invalid_defective_stock_plan'; end if;
  select c.order_id into target_order from public.order_cancellation_requests c where c.id = p_claim_id;
  if not found then raise no_data_found using message = 'claim_not_found'; end if;
  select * into ord from public.orders where id = target_order for update;
  select * into claim from public.order_cancellation_requests where id = p_claim_id for update;
  if not found or claim.order_id <> target_order then raise sqlstate 'PT409' using message = 'defective_stock_plan_conflict'; end if;
  if claim.claim_type <> 'return' then raise check_violation using message = 'defective_stock_return_only'; end if;
  -- 재고가 정해진 뒤에는 선택을 바꿀 수 없다: 주문이 canceled(finalizer가 복원함)이거나 무통장 환불이 취소 확정 단계에 들어갔다.
  if claim.stage in ('completed','rejected','withdrawn') or ord.status = 'canceled'
    or exists(select 1 from private.bank_transfer_claim_refunds b where b.claim_id = p_claim_id or b.order_id = claim.order_id) then
    raise check_violation using message = 'defective_stock_claim_closed';
  end if;
  if exists(select 1 from unnest(ids) x where not exists(select 1 from public.order_items oi where oi.id = x and oi.order_id = claim.order_id)) then
    raise check_violation using message = 'defective_stock_item_not_in_order';
  end if;
  -- 재고 부족 부분 취소(ADR-0032)로 남은 수량이 없는 품목은 고를 수 없다. 불량 수량은 살아 있는 수량이다
  -- (부분 취소분은 이미 판매 재고로 복원됐고, restore_order_item_supply도 남은 수량만 복원한다). 출고 판정보다 먼저 본다.
  if exists(select 1 from unnest(ids) x where coalesce(private.order_item_active_qty(x), 0) <= 0) then
    raise check_violation using message = 'defective_stock_item_fully_canceled';
  end if;
  if exists(select 1 from unnest(ids) x where not private.defective_stock_item_eligible(x)) then
    raise check_violation using message = 'defective_stock_item_not_shipped';
  end if;
  -- 거절·철회됐거나 반품이 아니게 된(교환 전환) 다른 클레임의 낡은 선택은 이 품목을 막지 않는다.
  delete from private.claim_defective_stock d using public.order_cancellation_requests c
  where c.id = d.claim_id and d.state = 'planned' and d.order_item_id = any(ids) and d.claim_id <> p_claim_id
    and (c.stage in ('rejected','withdrawn') or c.claim_type <> 'return');
  if exists(select 1 from private.claim_defective_stock d where d.order_item_id = any(ids) and d.claim_id <> p_claim_id) then
    raise unique_violation using message = 'defective_stock_item_in_other_claim';
  end if;
  delete from private.claim_defective_stock d where d.claim_id = p_claim_id and d.state = 'planned' and not (d.order_item_id = any(ids));
  for item in select oi.id, private.order_item_active_qty(oi.id) as qty from public.order_items oi where oi.id = any(ids) order by oi.id loop
    insert into private.claim_defective_stock(claim_id, order_item_id, qty, planned_by) values (p_claim_id, item.id, item.qty, actor)
    on conflict (order_item_id) do nothing;
  end loop;
  select count(*) into planned_count from private.claim_defective_stock where claim_id = p_claim_id;
  if planned_count <> cardinality(ids) then raise sqlstate 'PT409' using message = 'defective_stock_plan_conflict'; end if;
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.order.claim_defective_stock_planned', 'order:' || claim.order_id::text,
    jsonb_build_object('claimId', p_claim_id, 'orderItemIds', to_jsonb(ids)));
  return jsonb_build_object('claimId', p_claim_id, 'planned', planned_count);
end $$

-- 재고가 정해진 직후 기록. 반품 클레임이고 거절·철회가 아니며 주문이 canceled(재고 복원 단계가 끝남)일 때만 선택을 원장으로
-- 확정한다. 이미 복원된 품목이 있으면 거절한다(이중 계상 방어선). 멱등이다.
create function public.admin_record_claim_defective_stock(p_claim_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare actor uuid; claim public.order_cancellation_requests; ord public.orders; row_ private.claim_defective_stock; item public.order_items;
  physical record; target record; target_variant public.goods_variants; target_good public.goods;
  recorded_now integer := 0; recorded_total integer; target_order uuid;
begin
  actor := private.require_operator_capability('sales.manage', false);
  if p_claim_id is null then raise invalid_parameter_value using message = 'invalid_defective_stock_record'; end if;
  select c.order_id into target_order from public.order_cancellation_requests c where c.id = p_claim_id;
  if not found then raise no_data_found using message = 'claim_not_found'; end if;
  select * into ord from public.orders where id = target_order for update;
  select * into claim from public.order_cancellation_requests where id = p_claim_id for update;
  if exists(select 1 from private.claim_defective_stock where claim_id = p_claim_id and state = 'planned') then
    if claim.claim_type <> 'return' then raise check_violation using message = 'defective_stock_return_only'; end if;
    if claim.stage in ('rejected','withdrawn') or ord.status <> 'canceled' then
      raise check_violation using message = 'defective_stock_claim_not_completed';
    end if;
    for row_ in select * from private.claim_defective_stock where claim_id = p_claim_id and state = 'planned' order by order_item_id for update loop
      select * into item from public.order_items where id = row_.order_item_id;
      if exists(select 1 from public.audit_log a where a.target = 'order:' || claim.order_id::text and a.action = 'order.option_stock_restored'
          and a.diff->>'orderItemId' = item.id::text)
        or exists(select 1 from private.group_stock_restorations g where g.order_item_id = item.id and g.cause = 'refund') then
        raise check_violation using message = 'defective_stock_item_already_restored';
      end if;
      select * into physical from private.order_item_physical_unit(item.id);
      select * into target from private.resolve_goods_stock_successor(physical.good_id, physical.variant_id);
      select * into target_variant from public.goods_variants where id = target.variant_id;
      select * into target_good from public.goods where id = target.good_id;
      update private.claim_defective_stock set state = 'recorded', good_id = target.good_id, variant_id = target.variant_id,
        good_name = target_good.name, variant_name = target_variant.name, variant_code = target_variant.code,
        recorded_by = actor, recorded_at = clock_timestamp() where id = row_.id;
      insert into public.audit_log(actor_id, action, target, diff) values (actor, 'order.claim_defective_stock_recorded', 'order:' || claim.order_id::text,
        jsonb_build_object('claimId', p_claim_id, 'orderItemId', item.id, 'goodId', target.good_id, 'variantId', target.variant_id,
          'qty', row_.qty, 'physicalStockDelta', 0));
      recorded_now := recorded_now + 1;
    end loop;
  end if;
  select count(*) into recorded_total from private.claim_defective_stock where claim_id = p_claim_id and state = 'recorded';
  return jsonb_build_object('claimId', p_claim_id, 'recorded', recorded_now, 'total', recorded_total,
    'pending', (select count(*) from private.claim_defective_stock where claim_id = p_claim_id and state = 'planned'));
end $$

-- 재고 대조 화면의 참고 칸: 옵션별 불량 수량(판매 재고에 들어 있지 않다).
create function public.admin_defective_stock_by_variant(p_variant_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.has_operator_capability('catalog.read', false) then raise insufficient_privilege using message = 'operator_capability_required'; end if;
  if p_variant_ids is null or cardinality(p_variant_ids) > 2000 then raise invalid_parameter_value using message = 'invalid_defective_stock_variants'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('variantId', d.variant_id, 'qty', d.qty) order by d.variant_id) from (
    select x.variant_id, sum(x.qty)::integer as qty from private.claim_defective_stock x
    where x.state = 'recorded' and x.variant_id = any(p_variant_ids) group by x.variant_id) d), '[]'::jsonb);
end $$

-- 구매확정을 막는 이유. 막을지 말지는 purchase_confirmation_eligible + 보류 하나로만 정하고, 여기서는 막힌 이유만 고른다
-- (판정이 두 군데로 갈라지지 않게 eligible이 참이면 보류 말고는 막지 않는다). null = 확정할 수 있거나 이미 확정됨.
create function private.purchase_confirmation_block_reason(p_order_id uuid) returns text
language plpgsql stable security definer set search_path='' as $$
declare target public.orders; on_hold boolean;
begin
 select * into target from public.orders where id=p_order_id;
 if not found then return 'order_missing';end if;
 if target.status='done' then return null;end if;
 if target.status<>'delivered' then return 'not_delivered';end if;
 select c.held into on_hold from private.order_purchase_confirmations c where c.order_id=target.id;
 if private.purchase_confirmation_eligible(target.id) then return case when coalesce(on_hold,false) then 'held' end;end if;
 if exists(select 1 from public.order_cancellation_requests r where r.order_id=target.id and r.status in('requested','processing','needs_review'))
  or exists(select 1 from public.order_cancellation_claims k where k.order_id=target.id) then return 'claim_in_progress';end if;
 if not private.order_all_items_delivered(target.id) then return 'not_all_delivered';end if;
 if private.is_account_write_fenced(target.user_id) then return 'account_restricted';end if;
 return 'unavailable';
end $$

-- 기존 리뷰 작성 함수는 확정 안내를 거치지 않으므로 미확정 주문에는 리뷰를 남기지 않는다.
-- 다른 자격 오류(기간·중복·결제 원본)가 먼저 나오도록 저장 직전에 검사한다. create_good_review(v1)도 이 함수를 거친다.
do $$
declare signature regprocedure:='public.create_good_review_v2(uuid,text,integer,text,text[],text)'::regprocedure;
 source text; anchor text:='paths:=private.assert_own_review_image_paths(target_image_paths,actor);';
begin
 source:=pg_get_functiondef(signature);
 if (length(source)-length(replace(source,anchor,'')))/length(anchor)<>1 then raise exception 'review_confirms_purchase_create_source_changed';end if;
 execute replace(source,anchor,
  '-- 1014-079: 새 리뷰는 구매확정된 주문에만 남는다. 미확정 주문은 create_good_review_v3가 확정한 뒤 이 함수를 부른다.
 if ordered.status=''delivered'' then raise check_violation using message=''review_purchase_confirmation_required'';end if;
 '||anchor);
end $$

-- 리뷰 등록 = 구매확정. 미확정 주문이면 확인 체크(p_acknowledged)를 받아 구매확정한 뒤 같은 트랜잭션에서 리뷰를 저장한다.
-- 리뷰 저장이 어떤 이유로든 실패하면 구매확정도 함께 되돌아간다. 이미 확정된 주문은 확인 없이 리뷰만 저장한다.
-- 같은 리뷰를 다시 보내면 review_already_exists로 끝나며 확정·적립은 늘지 않는다(주문당 확정 1회, 주문×굿즈×유형당 리뷰 1개).
create function public.create_good_review_v3(target_order_id uuid,target_good_id text,target_rating integer,target_body text,target_image_paths text[],target_kind text,
 p_acknowledged boolean,p_actor uuid,p_session uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid();current_status public.order_status;ordered public.orders;confirmation_revision bigint;reason text;created uuid;confirmed boolean:=false;
begin
 if actor is null then raise invalid_authorization_specification using message='auth_required';end if;
 -- 구매확정이 필요한 주문(배송완료·미확정)만 구매확정 경계를 지난다. 이미 확정된 주문 등은 create_good_review_v2로 바로 넘겨
 -- 프로필을 NO KEY UPDATE로 잡지 않는다(v2는 행위자 → 계정 작업 → 프로필 FOR SHARE만 잡는다). 판정은 잠근 뒤 다시 한다.
 select o.status into current_status from public.orders o where o.id=target_order_id and o.user_id=actor;
 if current_status='delivered' then
  -- 잠금 순서: 행위자 → 계정 작업 → 프로필(NO KEY UPDATE, purchase_confirmation_identity) → 주문 → 확정 행.
  -- 결제·선물(행위자 → 계정 작업 → 프로필)·운영자 고객 RPC(계정 작업 → 프로필)·[구매확정] 버튼과 같은 순서다.
  -- 뒤에 부르는 create_good_review_v2의 계정 잠금(gift_lock_subjects·lock_operator_subjects)은 이미 쥔 잠금을 다시 잡을 뿐이다.
  perform pg_advisory_xact_lock(hashtextextended(actor::text,0));
  perform private.purchase_confirmation_identity(p_actor,p_session,false);
  select * into ordered from public.orders where id=target_order_id and user_id=actor for update;
  -- 잠그는 사이 자동 구매확정 등으로 확정됐으면 확정 없이 리뷰만 저장한다.
  if ordered.status='delivered' then
   if p_acknowledged is distinct from true then raise invalid_parameter_value using message='review_purchase_confirmation_ack_required';end if;
   reason:=private.purchase_confirmation_block_reason(ordered.id);
   if reason is not null then raise check_violation using message='review_purchase_confirmation_blocked',detail=reason;end if;
   -- 정책 저장의 소급 기한 채우기도 확정 행 revision을 올리므로, 확정 행을 잠근 뒤의 revision으로 확정한다.
   select c.revision into confirmation_revision from private.order_purchase_confirmations c where c.order_id=ordered.id for update;
   perform private.change_purchase_confirmation(ordered.id,'confirm','리뷰 등록과 함께 확정',coalesce(confirmation_revision,0),gen_random_uuid(),p_actor,p_session,false);
   confirmed:=true;
  end if;
 end if;
 created:=public.create_good_review_v2(target_order_id,target_good_id,target_rating,target_body,coalesce(target_image_paths,'{}'::text[]),target_kind);
 return jsonb_build_object('reviewId',created,'purchaseConfirmed',confirmed);
end $$

do $$
declare source text:=pg_get_functiondef('public.settle_delivered_orders()'::regprocedure);
begin
 source:=pg_temp.settle_anchor(source,'and private.purchase_confirmation_eligible(o.id)','and private.purchase_confirmation_candidate(o.id)');
 source:=pg_temp.settle_anchor(source,'perform 1 from public.profiles where id=item.user_id and suspended_at is null for no key update skip locked;',
$p$begin
  -- 주문마다 하위 트랜잭션. 결제·선물·리뷰 경로와 같은 순서(행위자 → 계정 작업 → 프로필 → 주문 → 확정 행)로 기다리지 않고
  -- 잡는다(키는 gift_lock_subjects·lock_account_action_subject와 같다). 못 잡거나 확정할 수 없으면 PC001로 이 주문만 되돌린다.
  if not pg_try_advisory_xact_lock(hashtextextended(item.user_id::text,0))
   or not pg_try_advisory_xact_lock(hashtextextended('account-action:'||item.user_id::text,0)) then raise sqlstate 'PC001';end if;
  perform 1 from public.profiles where id=item.user_id and suspended_at is null for no key update skip locked;$p$);
 source:=pg_temp.settle_anchor(source,'if not found then continue;end if;','if not found then raise sqlstate ''PC001'';end if;',2);
 source:=pg_temp.settle_anchor(source,'select * into confirmation from private.order_purchase_confirmations where order_id=item.id for update;',
$p$select * into confirmation from private.order_purchase_confirmations where order_id=item.id for update skip locked;
  if not found then raise sqlstate 'PC001';end if;$p$);
 source:=pg_temp.settle_anchor(source,'or not private.purchase_confirmation_eligible(item.id) then continue;end if;',
  'or not private.purchase_confirmation_eligible(item.id) then raise sqlstate ''PC001'';end if;');
 source:=pg_temp.settle_anchor(source,'n:=n+1;',
$p$n:=n+1;
  exception when sqlstate 'PC001' or lock_not_available or deadlock_detected then
   -- 경합(잠금 실패, 확정 뒤 trigger의 lock_timeout 초과)이나 자격 변화: 이 주문의 잠금·변경을 모두 되돌리고 다음 실행에 맡긴다.
   null;
  end;$p$);
 execute source;
end $$

-- 지연 안내 원장의 요청·재시도·이메일 결속이 안내 종류에 맞는 스냅샷으로 대상 변경을 판정한다(앵커 1곳).
do $patch$
declare definition text:=pg_get_functiondef('private.order_delay_notice_target_current(uuid)'::regprocedure);
  anchor text:='t.snapshot=private.order_delay_notice_snapshot(t.order_id,t.shipment_ids)';
begin
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'delay_notice_target_current_anchor_changed'; end if;
  execute replace(definition,anchor,'t.snapshot=case when n.kind=''preorder_schedule'' then private.preorder_schedule_notice_snapshot(t.order_id,t.shipment_ids)'
    ||' else private.order_delay_notice_snapshot(t.order_id,t.shipment_ids) end');
end $patch$

-- 지연 탭의 '지연 안내 결과'·안내여부 필터는 발송 지연 안내만 센다. 약속일 전에 보낸 일정 변경 안내가
-- 그 뒤 다시 늦어진 배송 건의 '미발송'을 가리지 않게 한다(앵커 1곳).
do $patch$
declare definition text:=pg_get_functiondef('private.shipment_delay_notice_summary(uuid)'::regprocedure);
  anchor text:='join private.order_delay_notices n on n.id=t.notice_id and n.requested_at is not null';
begin
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'shipment_delay_notice_summary_anchor_changed'; end if;
  execute replace(definition,anchor,anchor||' and n.kind=''dispatch_delay''');
end $patch$

-- 6) 대상 범위 검증. 상품·옵션·날짜가 맞지 않으면 미리보기와 확정 모두 같은 이유로 거절한다.
create function private.goods_preorder_schedule_scope(p_good_id text,p_variant_id uuid,p_to_date date)
returns public.goods language plpgsql stable security definer set search_path='' as $$
declare good public.goods;
begin
  if p_good_id is null or p_to_date is null or p_to_date<(statement_timestamp() at time zone 'Asia/Seoul')::date then
    raise invalid_parameter_value using message='invalid_preorder_schedule_change';
  end if;
  select * into good from public.goods where id=p_good_id;
  if not found then raise no_data_found using message='good_not_found'; end if;
  if p_variant_id is not null then
    if good.option_sale_mode='random' then raise check_violation using message='preorder_schedule_random_whole_good'; end if;
    if not exists(select 1 from public.goods_variants where id=p_variant_id and good_id=good.id) then
      raise no_data_found using message='goods_variant_not_found';
    end if;
  end if;
  return good;
end $$

-- 10) 미리보기. 아무것도 바꾸지 않는다. 대상·제외 사유·접수 중인 예약 조건(교체 가능 여부)·채널 준비 상태를 돌려준다.
create function public.admin_preview_goods_preorder_schedule_change(p_good_id text,p_variant_id uuid,p_expected_ship_date date)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=(select auth.uid()); good public.goods; plan jsonb;
begin
  if not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='operator_capability_required'; end if;
  if actor is null then raise insufficient_privilege using message='staff required'; end if;
  good:=private.goods_preorder_schedule_scope(p_good_id,p_variant_id,p_expected_ship_date);
  plan:=private.goods_preorder_schedule_plan(good.id,p_variant_id,p_expected_ship_date);
  return plan||jsonb_build_object('goodId',good.id,'goodName',good.name,'randomSale',good.option_sale_mode='random',
   'variantId',p_variant_id,'variantName',(select name from public.goods_variants where id=p_variant_id),
   'variantCount',(select count(*) from public.goods_variants where good_id=good.id and archived_at is null),
   'expectedShipDate',p_expected_ship_date,'limit',3000,
   'canReplacePolicies',private.has_operator_capability(actor,'platform.manage',true) and private.has_operator_capability(actor,'catalog.manage',false),
   'emailEnabled',coalesce((select enabled from private.order_delay_notice_delivery_control where singleton),false),
   'smsEnabled',coalesce((select sms_enabled from private.order_delay_notice_delivery_control where singleton),false));
end $$

-- 11) 확정. 미리보기에서 본 대상 그대로(운영자가 뺀 배송 건 제외) 일정을 바꾸고 같은 트랜잭션에서 앱 알림·이메일을 요청한다.
--     접수 중 조건이 있으면 p_policy_mode가 필요하다: 'replace'(활성화 권한 — 남은 물량·접수 기간을 이어받은 새 버전으로 교체,
--     랜덤 판매는 모든 옵션) 또는 'acknowledge'(교체하지 않음을 확인, 감사에 남김).
--     잠금 순서: 요청 → 상품(일괄) → 주문 → 구매자 → 배송 건 → 지연 메모 → (교체 시) 상품 행·옵션 행 → 예약 조건.
--     주문 접수(place_order)도 주문 → 구매자 → 상품·옵션 순이라 교착이 없고, 교체 때는 상품·옵션을 잠근 뒤 다시 계산해
--     그 사이 들어온 주문이 있으면 지문이 달라져 거절한다(옛 날짜로 남는 주문이 없다).
create function public.admin_apply_goods_preorder_schedule_change(p_request_id uuid,p_good_id text,p_variant_id uuid,
  p_expected_ship_date date,p_reason text,p_customer_title text,p_customer_body text,p_preview_fingerprint text,
  p_excluded_shipments uuid[] default '{}'::uuid[],p_sms_requested boolean default false,p_policy_mode text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid()); existing private.goods_preorder_schedule_changes%rowtype; good public.goods;
  excluded uuid[]; digest text; plan jsonb; targets jsonb; target_ids uuid[]; order_ids uuid[]; open_policies jsonb;
  notice uuid:=extensions.gen_random_uuid(); changed_at timestamptz:=clock_timestamp(); sms boolean; order_total integer;
  policy_action text; policy_record jsonb:='[]'::jsonb; policy jsonb; v_reference text;
  g record; v_labels text[]; v_message text; v_date_line text; v_snapshot jsonb; v_buyer uuid; v_email text; v_buyer_name text;
begin
  perform private.require_operator_capability('sales.manage',false);
  if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required'; end if;
  if p_request_id is null or p_preview_fingerprint is null or p_preview_fingerprint !~ '^[0-9a-f]{32}$'
   or p_reason is null or length(btrim(p_reason)) not between 1 and 2000
   or p_customer_title is null or length(btrim(p_customer_title)) not between 1 and 80 or p_customer_title ~ '[[:cntrl:]]'
   or p_customer_body is null or length(btrim(p_customer_body)) not between 1 and 350
   or cardinality(coalesce(p_excluded_shipments,'{}'::uuid[]))>50000 or array_position(coalesce(p_excluded_shipments,'{}'::uuid[]),null) is not null
   or (p_policy_mode is not null and p_policy_mode not in ('replace','acknowledge'))
  then raise invalid_parameter_value using message='invalid_preorder_schedule_change'; end if;
  select coalesce(array_agg(distinct x order by x),'{}'::uuid[]) into excluded from unnest(coalesce(p_excluded_shipments,'{}'::uuid[])) x;
  digest:=md5(jsonb_build_array(p_good_id,p_variant_id,p_expected_ship_date,btrim(p_reason),btrim(p_customer_title),btrim(p_customer_body),
   p_preview_fingerprint,to_jsonb(excluded),coalesce(p_sms_requested,false),p_policy_mode)::text);
  perform pg_advisory_xact_lock(hashtextextended('goods_preorder_schedule_change:'||p_request_id::text,0));
  select * into existing from private.goods_preorder_schedule_changes where id=p_request_id;
  if found then
    if existing.actor_id<>actor or existing.request_digest<>digest then
      raise unique_violation using message='preorder_schedule_idempotency_conflict';
    end if;
    return private.goods_preorder_schedule_change_document(p_request_id);
  end if;
  good:=private.goods_preorder_schedule_scope(p_good_id,p_variant_id,p_expected_ship_date);
  if not coalesce((select enabled from private.order_delay_notice_delivery_control where singleton),false) then
    raise check_violation using message='delay_notice_delivery_disabled';
  end if;
  if p_policy_mode='replace' and not (private.has_operator_capability(actor,'platform.manage',true)
    and private.has_operator_capability(actor,'catalog.manage',false)) then
    raise insufficient_privilege using message='preorder_admin_required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('goods_preorder_schedule_good:'||good.id,0));
  plan:=private.goods_preorder_schedule_plan(good.id,p_variant_id,p_expected_ship_date);
  select array_agg(distinct (value->>'orderId')::uuid),array_agg((value->>'shipmentId')::uuid)
   into order_ids,target_ids from jsonb_array_elements(plan->'targets') value;
  if order_ids is null then raise sqlstate 'PT409' using message='preorder_schedule_stale'; end if;
  perform 1 from public.orders where id=any(order_ids) order by id for update;
  perform 1 from public.profiles where id in (select user_id from public.orders where id=any(order_ids)) order by id for share;
  perform 1 from public.order_shipments where id=any(target_ids) order by id for update;
  perform 1 from public.order_dispatch_delays where order_id=any(order_ids) order by order_id for share;
  if p_policy_mode='replace' then
    perform 1 from public.goods where id=good.id for update;
    perform 1 from public.goods_variants where good_id=good.id order by id for update;
  end if;
  plan:=private.goods_preorder_schedule_plan(good.id,p_variant_id,p_expected_ship_date);
  if plan->>'fingerprint' is distinct from p_preview_fingerprint then raise sqlstate 'PT409' using message='preorder_schedule_stale'; end if;
  if exists(select 1 from unnest(excluded) x where not exists(select 1 from jsonb_array_elements(plan->'targets') value
    where (value->>'shipmentId')::uuid=x)) then raise invalid_parameter_value using message='invalid_preorder_schedule_change'; end if;
  select coalesce(jsonb_agg(value order by value->>'shipmentId'),'[]'::jsonb) into targets from jsonb_array_elements(plan->'targets') value
   where not ((value->>'shipmentId')::uuid=any(excluded));
  if jsonb_array_length(targets)=0 then raise check_violation using message='preorder_schedule_no_targets'; end if;
  if jsonb_array_length(targets)>3000 then raise check_violation using message='preorder_schedule_too_many'; end if;
  select array_agg((value->>'shipmentId')::uuid order by (value->>'shipmentId')::uuid),count(distinct value->>'orderId')
   into target_ids,order_total from jsonb_array_elements(targets) value;
  sms:=coalesce(p_sms_requested,false) and coalesce((select sms_enabled from private.order_delay_notice_delivery_control where singleton),false);

  -- 접수 중 예약 조건: 새 날짜로 교체하거나 그대로 둔다는 확인이 있어야 한다.
  open_policies:=coalesce(plan->'openPolicies','[]'::jsonb);
  if jsonb_array_length(open_policies)>0 then
    if p_policy_mode is null then raise check_violation using message='preorder_schedule_policy_decision_required'; end if;
    policy_action:=case p_policy_mode when 'replace' then 'replaced' else 'acknowledged' end;
    if p_policy_mode='replace' then
      if plan->>'policyBlockReason' is not null then raise check_violation using message='preorder_schedule_policy_not_replaceable'; end if;
      v_reference:=left(coalesce((select approval_reference from private.goods_preorder_policies where id=(open_policies->0->>'policyId')::uuid),'')
        ||E'\n'||'발송 예정일 변경 '||to_char(p_expected_ship_date,'YYYY-MM-DD')||'(예약 주문 일괄 변경): '||btrim(p_reason),2000);
      if good.option_sale_mode='random' then
        perform public.admin_save_random_goods_preorders(good.id,'stopped',null,(select jsonb_agg(jsonb_build_object('variantId',p->>'variantId',
          'policyId',p->>'policyId','expectedRevision',(p->>'revision')::integer)) from jsonb_array_elements(open_policies) p));
        perform public.admin_save_random_goods_preorders(good.id,'active',jsonb_build_object('startsAt',open_policies->0->'startsAt',
          'endsAt',open_policies->0->'endsAt','expectedShipDate',p_expected_ship_date::text,'approvalReference',v_reference),
          (select jsonb_agg(jsonb_build_object('variantId',p->>'variantId','policyId',null,'expectedRevision',null,
            'capacityQty',(p->>'remainingQty')::integer)) from jsonb_array_elements(open_policies) p));
      else
        for policy in select value from jsonb_array_elements(open_policies) loop
          perform public.admin_save_goods_preorder(good.id,(policy->>'variantId')::uuid,(policy->>'policyId')::uuid,
            '{"state":"stopped"}'::jsonb,(policy->>'revision')::integer);
          perform public.admin_save_goods_preorder(good.id,(policy->>'variantId')::uuid,null,jsonb_build_object('state','active',
            'capacityQty',(policy->>'remainingQty')::integer,'startsAt',policy->'startsAt','endsAt',policy->'endsAt',
            'expectedShipDate',p_expected_ship_date::text,'approvalReference',left(coalesce((select approval_reference
              from private.goods_preorder_policies where id=(policy->>'policyId')::uuid),'')||E'\n'||'발송 예정일 변경 '
              ||to_char(p_expected_ship_date,'YYYY-MM-DD')||'(예약 주문 일괄 변경): '||btrim(p_reason),2000)),null);
        end loop;
      end if;
      select coalesce(jsonb_agg(p||jsonb_build_object('newPolicyId',(select v.preorder_policy_id from public.goods_variants v
        where v.id=(p->>'variantId')::uuid),'newExpectedShipDate',p_expected_ship_date)),'[]'::jsonb)
       into policy_record from jsonb_array_elements(open_policies) p;
    else
      policy_record:=open_policies;
    end if;
  end if;

  insert into private.order_delay_notices(id,kind,actor_id,shipment_ids,title,customer_body,expected_ship_date)
   values(notice,'preorder_schedule',actor,target_ids,btrim(p_customer_title),btrim(p_customer_body),p_expected_ship_date);
  insert into private.goods_preorder_schedule_changes(id,good_id,variant_id,to_date,reason,actor_id,notice_id,request_digest,
   preview_fingerprint,excluded_shipment_ids,shipment_count,order_count,sms_queued,policy_action,policies,created_at)
   values(p_request_id,good.id,p_variant_id,p_expected_ship_date,btrim(p_reason),actor,notice,digest,p_preview_fingerprint,excluded,
    cardinality(target_ids),order_total,sms,policy_action,policy_record,changed_at);
  -- 배송 건마다 이력: 바꾼 건은 지금 → 새 날짜, 안내만 한 건(개별 변경을 처음 알림)은 같은 날짜로 남겨 다음 일괄에서 다시 알리지 않는다.
  insert into private.order_shipment_promise_changes(shipment_id,from_date,to_date,reason,actor_id,created_at,bulk_change_id)
   select (value->>'shipmentId')::uuid,(value->>'currentDate')::date,(value->>'newDate')::date,btrim(p_reason),actor,changed_at,p_request_id
   from jsonb_array_elements(targets) value;
  update public.order_shipments s set expected_ship_date=(value->>'newDate')::date,updated_at=changed_at
   from jsonb_array_elements(targets) value where s.id=(value->>'shipmentId')::uuid and value->>'newDate'<>value->>'currentDate';
  insert into public.audit_log(actor_id,action,target,diff)
   select actor,'admin.shipment.preorder_promise_changed','order:'||(value->>'orderId'),jsonb_build_object('shipmentId',value->>'shipmentId',
    'originalDate',value->>'originalDate','fromDate',value->>'currentDate','toDate',value->>'newDate','reason',btrim(p_reason),
    'noticeOnly',(value->>'noticeOnly')::boolean,'goodId',good.id,'bulkChangeId',p_request_id,'noticeId',notice,'trigger','goods_preorder_bulk')
   from jsonb_array_elements(targets) value order by value->>'orderId',value->>'shipmentId';

  -- 주문마다 구매자(선물 주문은 받는 분도) 안내 대상을 만든다. 날짜 줄의 이전 날짜는 고객이 마지막으로 안내받은 날짜다.
  for g in select (value->>'orderId')::uuid order_id,array_agg((value->>'shipmentId')::uuid order by (value->>'shipmentId')::uuid) shipment_ids,
    array_agg(distinct (value->>'knownDate')::date) from_dates,array_agg(distinct (value->>'newDate')::date) to_dates
   from jsonb_array_elements(targets) value group by 1 order by 1 loop
   v_snapshot:=private.preorder_schedule_notice_snapshot(g.order_id,g.shipment_ids);
   if v_snapshot is null then raise sqlstate 'PT409' using message='preorder_schedule_stale'; end if;
   select o.user_id,nullif(lower(btrim(p.email)),''),coalesce(nullif(p.nickname,''),'구매자') into v_buyer,v_email,v_buyer_name
    from public.orders o join public.profiles p on p.id=o.user_id where o.id=g.order_id;
   select array_agg(origin_name_snapshot||' · '||coalesce(shipment_number,upper(right(id::text,8))) order by id) into v_labels
    from public.order_shipments where id=any(g.shipment_ids);
   v_date_line:=case when cardinality(g.from_dates)=1 and cardinality(g.to_dates)=1
     then '발송 예정일: '||to_char(g.from_dates[1],'YYYY-MM-DD')||' → '||to_char(g.to_dates[1],'YYYY-MM-DD')
     else '변경된 발송 예정일: '||(select to_char(min(x),'YYYY-MM-DD') from unnest(g.to_dates) x)
      ||case when cardinality(g.to_dates)>1 then ' ~ '||(select to_char(max(x),'YYYY-MM-DD') from unnest(g.to_dates) x) else '' end end;
   v_message:=btrim(p_customer_body)||E'\n\n'||v_date_line||E'\n안내 대상 배송 건: '
    ||(select string_agg(coalesce(s.shipment_number,upper(right(s.id::text,8))),', ' order by s.id) from public.order_shipments s where s.id=any(g.shipment_ids[1:3]))
    ||case when cardinality(g.shipment_ids)>3 then ' 외 '||(cardinality(g.shipment_ids)-3)::text||'건' else '' end;
   insert into private.order_delay_notice_targets(notice_id,order_id,buyer_id,recipient_email,buyer_name,shipment_ids,shipment_labels,snapshot,
    message_body,email_status,error_code)
    values(notice,g.order_id,v_buyer,v_email,v_buyer_name,g.shipment_ids,v_labels,v_snapshot,v_message,
     case when v_email is null or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'suppressed' else 'prepared' end,
     case when v_email is null or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'recipient_missing' else null end);
   insert into private.order_delay_notice_targets(notice_id,order_id,buyer_id,recipient_email,buyer_name,shipment_ids,shipment_labels,snapshot,
    message_body,email_status,error_code,audience)
    select notice,g.order_id,p.id,nullif(lower(btrim(p.email)),''),coalesce(nullif(p.nickname,''),'받는 분'),g.shipment_ids,v_labels,v_snapshot,v_message,
     case when p.email is null or btrim(p.email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'suppressed' else 'prepared' end,
     case when p.email is null or btrim(p.email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'recipient_missing' else null end,'recipient'
    from private.gift_intents gift join public.profiles p on p.id=gift.recipient_id where gift.order_id=g.order_id;
  end loop;

  -- 지연 안내 요청 경로 그대로: 대상 재확인 → 앱 알림 발행 → 이메일 작업 등록 → 감사.
  perform public.admin_request_order_delay_notice(notice);
  if sms then
    insert into private.order_delay_notice_sms_jobs(target_id) select id from private.order_delay_notice_targets where notice_id=notice;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.good.preorder_schedule_changed','goods:'||good.id,
   jsonb_build_object('changeId',p_request_id,'noticeId',notice,'variantId',p_variant_id,'toDate',p_expected_ship_date,
    'shipments',cardinality(target_ids),'noticeOnly',(select count(*) from jsonb_array_elements(targets) value where (value->>'noticeOnly')::boolean),
    'orders',order_total,'excluded',cardinality(excluded),'sms',sms,'policyAction',policy_action,'policies',policy_record));
  return private.goods_preorder_schedule_change_document(p_request_id);
end $$

-- 12) 결과 다시 읽기와 상품의 최근 일괄 변경 목록(화면을 떠난 뒤 결과·재시도로 돌아온다).
create function public.admin_read_goods_preorder_schedule_change(p_change_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
  if not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='operator_capability_required'; end if;
  if (select auth.uid()) is null then raise insufficient_privilege using message='staff required'; end if;
  result:=private.goods_preorder_schedule_change_document(p_change_id);
  if result is null then raise no_data_found using message='preorder_schedule_change_not_found'; end if;
  return result;
end $$

create function public.admin_list_goods_preorder_schedule_changes(p_good_id text)
returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
  if not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='operator_capability_required'; end if;
  if (select auth.uid()) is null then raise insufficient_privilege using message='staff required'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'expectedShipDate',c.to_date,'variantName',v.name,'createdAt',c.created_at,
    'actorName',a.nickname,'shipmentCount',c.shipment_count,'orderCount',c.order_count,'requestedAt',n.requested_at) order by c.created_at desc,c.id)
   from (select * from private.goods_preorder_schedule_changes where good_id=p_good_id order by created_at desc,id limit 20) c
   left join public.goods_variants v on v.id=c.variant_id left join public.profiles a on a.id=c.actor_id
   join private.order_delay_notices n on n.id=c.notice_id),'[]'::jsonb);
end $$

-- 13) SMS 작업(service role 전용, cron). 보내기 전에 설정·대상 변경·SMS 수신 동의를 다시 확인한다.
create function public.claim_order_delay_sms_jobs(batch_limit integer default 25)
returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb; enabled boolean;
begin
  if batch_limit is null or batch_limit not between 1 and 50 then raise invalid_parameter_value using message='invalid_delay_sms_batch'; end if;
  -- 잠금이 끝난 처리 중 작업은 보냈는지 알 수 없다. 다시 보내지 않고 결과 불명으로 둔다.
  update private.order_delay_notice_sms_jobs set status='unknown',reason='lease_expired',claim_token=null,lease_until=null,updated_at=now()
   where status='processing' and lease_until<now();
  -- 하루가 지난 대기 작업은 낡은 일정 안내라 보내지 않는다.
  update private.order_delay_notice_sms_jobs set status='skipped',reason='expired',updated_at=now()
   where status='queued' and created_at<now()-interval '24 hours';
  select coalesce(control.sms_enabled,false) into enabled from private.order_delay_notice_delivery_control control where control.singleton;
  if not coalesce(enabled,false) then
    update private.order_delay_notice_sms_jobs set status='skipped',reason='sms_disabled',updated_at=now() where status='queued';
    return '[]'::jsonb;
  end if;
  with picked as (
   select job.target_id from private.order_delay_notice_sms_jobs job where job.status='queued'
   order by job.created_at,job.target_id for update skip locked limit batch_limit
  ), checked as (
   select picked.target_id,coalesce(private.order_delay_notice_target_current(picked.target_id),false) current_target,
    exists(select 1 from private.order_delay_notice_targets t join private.customer_marketing_consents consent
     on consent.user_id=t.buyer_id and consent.channel='sms' and consent.agreed where t.id=picked.target_id) consented
   from picked
  ), skipped as (
   update private.order_delay_notice_sms_jobs job set status='skipped',
    reason=case when not checked.current_target then 'target_changed' else 'consent_required' end,updated_at=now()
   from checked where job.target_id=checked.target_id and not (checked.current_target and checked.consented) returning job.target_id
  ), claimed as (
   update private.order_delay_notice_sms_jobs job set status='processing',claim_token=extensions.gen_random_uuid(),
    lease_until=now()+interval '10 minutes',attempts=job.attempts+1,updated_at=now()
   from checked where job.target_id=checked.target_id and checked.current_target and checked.consented returning job.*
  )
  select coalesce(jsonb_agg(jsonb_build_object('id',c.target_id,'claimToken',c.claim_token,'userId',t.buyer_id,'orderId',t.order_id,
    'orderNumber',o.order_number,'audience',t.audience,'title',n.title,'body',t.message_body) order by c.created_at,c.target_id),'[]'::jsonb)
   into result
  from claimed c join private.order_delay_notice_targets t on t.id=c.target_id
  join private.order_delay_notices n on n.id=t.notice_id join public.orders o on o.id=t.order_id;
  return result;
end $$

create function public.finish_order_delay_sms_job(p_target_id uuid,p_claim uuid,p_status text,p_reason text)
returns boolean language plpgsql security definer set search_path='' as $$
declare job private.order_delay_notice_sms_jobs%rowtype;
begin
  if p_target_id is null or p_claim is null or p_status is null or p_status not in ('sent','failed','skipped')
   or (p_status='sent')<>(p_reason is null)
   or (p_reason is not null and p_reason not in ('sms_disabled','consent_required','no_verified_phone','account_unavailable','provider_unavailable','invalid_body'))
   or (p_status='failed' and p_reason not in ('provider_unavailable','invalid_body'))
   or (p_status='skipped' and p_reason not in ('sms_disabled','consent_required','no_verified_phone','account_unavailable'))
  then raise invalid_parameter_value using message='invalid_delay_sms_result'; end if;
  select * into job from private.order_delay_notice_sms_jobs where target_id=p_target_id for update;
  if not found or job.status<>'processing' or job.claim_token is distinct from p_claim then return false; end if;
  update private.order_delay_notice_sms_jobs set status=p_status,reason=p_reason,claim_token=null,lease_until=null,
   sent_at=case when p_status='sent' then now() end,updated_at=now() where target_id=p_target_id;
  insert into public.audit_log(actor_id,action,target,diff) values(null,'system.order.delay_notice_sms_result','delay_notice_target:'||p_target_id,
   jsonb_build_object('status',p_status,'reason',p_reason));
  return true;
end $$

-- 14) 지연 탭 이력·읽기에 안내 종류를 싣는다. 일정 변경 안내는 지연 탭에서 일괄 결과 문서(이메일 없음)로 열도록 일괄 변경 ID도 준다(앵커 1곳씩).
do $patch$
declare definition text:=pg_get_functiondef('public.admin_list_order_delay_notices(uuid)'::regprocedure);
  anchor text:='''requestedAt'',n.requested_at) order by n.created_at desc';
begin
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'delay_notice_list_anchor_changed'; end if;
  execute replace(definition,anchor,'''requestedAt'',n.requested_at,''kind'',n.kind,''scheduleChangeId'',(select c.id from private.goods_preorder_schedule_changes c where c.notice_id=n.id)) order by n.created_at desc');
end $patch$

do $patch$
declare definition text:=pg_get_functiondef('public.admin_get_order_delay_notice(uuid)'::regprocedure);
  anchor text:='''createdAt'',n.created_at,''expiresAt'',n.expires_at,''requestedAt'',n.requested_at,';
begin
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'delay_notice_get_anchor_changed'; end if;
  execute replace(definition,anchor,anchor||'''kind'',n.kind,');
end $patch$

-- 15) 배송 건 일정 변경 이력에 일괄 변경 ID와 '안내만'(일정 그대로, 고객에게 알린 기록) 표시를 싣는다(앵커 1곳).
do $patch$
declare definition text:=pg_get_functiondef('public.admin_list_shipment_promise_changes(uuid)'::regprocedure);
  anchor text:='''changedAt'',change.created_at)';
begin
  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'shipment_promise_changes_anchor_changed'; end if;
  execute replace(definition,anchor,'''changedAt'',change.created_at,''bulkChangeId'',change.bulk_change_id,''noticeOnly'',(change.from_date=change.to_date and change.bulk_change_id is not null))');
end $patch$

do $$declare signature text;fn regprocedure;contract record;registered boolean;begin
 foreach signature in array ARRAY['private.shipment_delay_notice_summary(uuid)','private.order_delay_notice_target_current(uuid)',
  'public.admin_list_order_delay_notices(uuid)','public.admin_get_order_delay_notice(uuid)','public.admin_list_shipment_promise_changes(uuid)'] loop
  fn:=signature::regprocedure;registered:=false;
  select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure=fn;
  if found then perform private.register_operator_rpc_contract(fn,contract.capability,contract.guard_kind,contract.legacy_admin_only);registered:=true; end if;
  if exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure=fn) then
   perform private.register_operator_internal_contract(fn);registered:=true;
  end if;
  if signature<>'private.order_delay_notice_target_current(uuid)' and not registered then raise exception 'operational_rpc_contract_missing: %',signature; end if;
 end loop;
end $$

select private.goods_kc_self_declaration_patch('private.goods_kc_review_problems(text,jsonb)'::regprocedure, jsonb_build_array(
