$patched$)))

-- 항목 하나: {kind, agency, number, visible}. 종류·인증번호는 필수, 인증기관은 선택이다. 한 줄 입력이라
-- 제어 문자를 거절하고 앞뒤 공백(JavaScript trim과 같은 문자)을 지운다. 같은 종류·번호는 한 번만 둔다.
-- 이 규칙은 lib/admin/goods-kc-other-certifications.ts와 같아야 한다.
create function private.normalize_goods_other_certifications(p_entries jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare entry jsonb; normalized jsonb:='[]'::jsonb; cert_kind text; cert_agency text; cert_number text;
  seen text[]:='{}'; entry_key text;
begin
  if p_entries is null or jsonb_typeof(p_entries)<>'array' or jsonb_array_length(p_entries)>20 then
    raise check_violation using message='invalid_goods_other_certifications';
  end if;
  for entry in select value from jsonb_array_elements(p_entries) loop
    if jsonb_typeof(entry)<>'object' or not (entry ?& array['kind','agency','number','visible'])
      or exists(select 1 from jsonb_object_keys(entry) key where key not in ('kind','agency','number','visible'))
      or jsonb_typeof(entry->'kind')<>'string' or jsonb_typeof(entry->'agency')<>'string'
      or jsonb_typeof(entry->'number')<>'string' or jsonb_typeof(entry->'visible')<>'boolean' then
      raise check_violation using message='invalid_goods_other_certifications';
    end if;
    cert_kind:=private.goods_kc_trim(entry->>'kind');
    cert_agency:=private.goods_kc_trim(entry->>'agency');
    cert_number:=private.goods_kc_trim(entry->>'number');
    if char_length(cert_kind)>100 or char_length(cert_agency)>100 or char_length(cert_number)>100
      or cert_kind ~ '[[:cntrl:]]' or cert_agency ~ '[[:cntrl:]]' or cert_number ~ '[[:cntrl:]]' then
      raise check_violation using message='invalid_goods_other_certifications';
    end if;
    if cert_kind='' or cert_number='' then
      raise check_violation using message='goods_other_certification_incomplete';
    end if;
    entry_key:=lower(cert_kind)||chr(31)||lower(cert_number);
    if entry_key=any(seen) then raise check_violation using message='goods_other_certification_duplicate'; end if;
    seen:=array_append(seen,entry_key);
    normalized:=normalized||jsonb_build_array(jsonb_build_object('kind',cert_kind,'agency',cert_agency,'number',cert_number,
      'visible',(entry->>'visible')::boolean));
  end loop;
  return normalized;
end $$

create function public.admin_read_goods_other_certifications(p_good_id text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare good public.goods; certification private.goods_other_certifications;
begin
  if not public.has_operator_capability('catalog.read',false) then
    raise insufficient_privilege using message='operator_capability_required';
  end if;
  select * into good from public.goods where id=p_good_id;
  if not found then raise no_data_found using message='good_not_found'; end if;
  select * into certification from private.goods_other_certifications where good_id=p_good_id;
  return jsonb_build_object('revision',certification.revision,'entries',coalesce(certification.entries,'[]'::jsonb),
    'publishedAt',good.published_at,'archivedAt',good.archived_at,'updatedAt',certification.updated_at,
    'updatedByName',(select nickname from public.profiles where id=certification.updated_by));
end $$

-- 잠금 순서는 상품 행 → 기타 인증 행(admin_save_goods_kc의 상품 행 → KC 행과 같다).
create function public.admin_save_goods_other_certifications(p_good_id text, p_entries jsonb, p_expected_revision integer)
returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid; good public.goods; current_set private.goods_other_certifications;
  saved_set private.goods_other_certifications; normalized_entries jsonb;
begin
  actor:=private.require_operator_capability('catalog.manage',false);
  normalized_entries:=private.normalize_goods_other_certifications(p_entries);
  select * into good from public.goods where id=p_good_id for update;
  if not found then raise no_data_found using message='good_not_found'; end if;
  if good.archived_at is not null then raise check_violation using message='catalog_item_archived'; end if;
  select * into current_set from private.goods_other_certifications where good_id=p_good_id for update;
  if current_set.revision is distinct from p_expected_revision then
    raise sqlstate 'PT409' using message='goods_other_certifications_changed';
  end if;
  if coalesce(current_set.entries,'[]'::jsonb)=normalized_entries then
    return jsonb_build_object('changed',false,'configuration',public.admin_read_goods_other_certifications(p_good_id));
  end if;
  insert into private.goods_other_certifications(good_id,revision,entries,updated_by,updated_at)
    values(p_good_id,coalesce(current_set.revision,0)+1,normalized_entries,actor,clock_timestamp())
    on conflict(good_id) do update set revision=excluded.revision,entries=excluded.entries,
      updated_by=excluded.updated_by,updated_at=excluded.updated_at
    returning * into saved_set;
  -- 트리거가 원본에서 고객 표시 목록을 다시 계산한다(넣는 값은 무시된다).
  update public.goods set other_certification_disclosures='[]'::jsonb where id=p_good_id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.good.other_certifications_saved','goods:'||p_good_id,
    jsonb_build_object('revision',saved_set.revision,'before',coalesce(current_set.entries,'[]'::jsonb),'after',normalized_entries));
  return jsonb_build_object('changed',true,'configuration',public.admin_read_goods_other_certifications(p_good_id));
end $$

-- ---------------------------------------------------------------------------
-- 등록 화면 원자 저장 — otherCertifications 섹션({entries, expectedRevision})
-- ---------------------------------------------------------------------------
-- 현재 정의에서 앵커가 정확히 한 번 나올 때만 바꾼다(다른 migration이 같은 줄을 고쳤으면 실패한다).
create function private.goods_other_certifications_patch(p_function regprocedure, p_patches jsonb)
returns void
language plpgsql
volatile
set search_path = ''
as $helper$
declare
  v_definition text := pg_catalog.pg_get_functiondef(p_function);
  v_patch jsonb;
  v_found integer;
begin
  for v_patch in select value from pg_catalog.jsonb_array_elements(p_patches) loop
    v_found := (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_patch->>0, '')))
      / pg_catalog.length(v_patch->>0);
    if v_found <> 1 then
      raise exception 'goods_other_certifications_anchor_changed: % (% matches)', p_function, v_found;
    end if;
    v_definition := pg_catalog.replace(v_definition, v_patch->>0, v_patch->>1);
  end loop;
  execute v_definition;
end;
$helper$

do $backfill$
declare item record; enabled_triggers jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object('name', tgname, 'mode', tgenabled) order by tgname), '[]'::jsonb) into enabled_triggers
    from pg_trigger where tgrelid = 'public.goods'::regclass and not tgisinternal and tgenabled <> 'D';
  for item in select value->>'name' as name from jsonb_array_elements(enabled_triggers) loop
    execute format('alter table public.goods disable trigger %I', item.name);
  end loop;
  update public.goods good set product_no = numbered.position
    from (select id, row_number() over (order by created_at, id) as position from public.goods) numbered
    where numbered.id = good.id;
  for item in select value->>'name' as name, value->>'mode' as mode from jsonb_array_elements(enabled_triggers) loop
    execute format(case item.mode when 'A' then 'alter table public.goods enable always trigger %I'
      when 'R' then 'alter table public.goods enable replica trigger %I' else 'alter table public.goods enable trigger %I' end, item.name);
  end loop;
end $backfill$

-- 2. 상품번호 발급. 같은 상품 URL(id)의 행이 이미 있으면(수정 저장의 INSERT … ON CONFLICT) 그 번호를 싣고 순번을 쓰지 않는다.
--    없으면 다음 순번을 쓴다. 값을 직접 넣을 수 없다. 다른 BEFORE INSERT 검사가 먼저 거절하면 순번을 쓰지 않도록
--    이름을 맨 뒤(zz_)로 둔다 — 같은 시점의 트리거는 이름 순서로 돈다.
--    SECURITY INVOKER다: BEFORE INSERT 트리거는 RLS WITH CHECK보다 먼저 돌므로, 정의자 권한이면 RLS가 거절할 직접 INSERT도 번호를
--    하나씩 써 버린다. 순번 권한은 소유자(postgres — 상품을 저장하는 정의자 RPC의 소유자)에게만 있어, 다른 역할의 새 행은
--    nextval이 권한 오류로 끝나고 번호를 쓰지 않는다.
create function private.assign_goods_product_no() returns trigger
language plpgsql security invoker set search_path = '' as $$
declare existing_no bigint;
begin
  if new.product_no is not null then
    raise exception using errcode = '22023', message = 'goods_product_no_system_assigned';
  end if;
  select good.product_no into existing_no from public.goods good where good.id = new.id;
  if existing_no is not null then
    new.product_no := existing_no;
  else
    new.product_no := nextval('private.goods_product_no_seq');
  end if;
  return new;
end $$

-- 3. 상품번호 불변. 값 지정·NULL·다른 번호로 바꾸는 갱신을 모두 막는다.
create function private.guard_goods_product_no() returns trigger
language plpgsql security invoker set search_path = '' as $$
begin
  if new.product_no is distinct from old.product_no then
    raise exception using errcode = '22023', message = 'goods_product_no_immutable';
  end if;
  return new;
end $$

-- 등록된 운영자 계약이 있으면 새 본문·ACL로 다시 등록한다(없으면 아무것도 하지 않는다).
do $$declare fn regprocedure; contract record; begin
 foreach fn in array array['private.admin_goods_console_matches(text,text,text,text,uuid,text,jsonb)'::regprocedure,
   'public.admin_search_goods_console(text,text,text,text,uuid,text,integer,integer,jsonb)'::regprocedure,
   'public.admin_search_goods(text)'::regprocedure] loop
  select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure = fn;
  if found then perform private.register_operator_rpc_contract(fn, contract.capability, contract.guard_kind, contract.legacy_admin_only);
  elsif exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure = fn) then
   perform private.register_operator_internal_contract(fn);
  end if;
 end loop;
end $$

-- 3. 새 IP 삽입 트리거: 생성 RPC만 내부 ID와 다른 공개 URL을 정할 수 있고, 퇴역 ID는 누구도 다시 쓰지 못한다 ---
create or replace function private.default_ip_public_slug()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  existing_public_slug text;
begin
  -- `admin_upsert_ip` uses INSERT ... ON CONFLICT(id) DO UPDATE. Its
  -- pre-existing call shape has no public_slug argument, so an update of a
  -- renamed IP must retain the current canonical value instead of treating
  -- the immutable id as a fresh slug candidate.
  select ip.public_slug
    into existing_public_slug
  from public.ips as ip
  where ip.id = new.id;
  if found then
    if new.public_slug is null then
      new.public_slug := existing_public_slug;
      return new;
    end if;
    if new.public_slug is distinct from existing_public_slug then
      raise insufficient_privilege using message = 'ip_public_slug_write_requires_rpc';
    end if;
    return new;
  end if;

  -- A direct INSERT may only derive public_slug from the new internal ID.
  -- admin_create_ip issues the internal ID from the requested public slug and
  -- marks its own insert, so only that RPC may store a different public slug.
  if new.public_slug is null then
    new.public_slug := new.id;
  elsif new.public_slug is distinct from new.id
    and coalesce(pg_catalog.current_setting('app.ip_public_slug_write', true), '') <> 'admin_create_ip'
  then
    raise insufficient_privilege using message = 'ip_public_slug_write_requires_rpc';
  end if;

  -- Only the namespace check for a genuinely new ID needs the global lock.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ip_public_slug_identity', 0)
  );
  -- A deleted draft's internal ID is never issued again (audit and FK-less
  -- references keep pointing at the deleted record, not at a new IP).
  if exists (
    select 1 from private.retired_ip_ids as retired where retired.id = new.id
  ) then
    raise unique_violation using message = 'catalog_id_retired';
  end if;
  if exists (
    select 1 from public.ips as ip where ip.public_slug = new.public_slug
  ) or exists (
    select 1 from public.ip_public_slug_aliases as alias where alias.slug = new.public_slug
  ) then
    raise unique_violation using message = 'ip_public_slug_taken';
  end if;
  return new;
end;
$$

-- 4. 공개 URL 변경: 다른 IP의 내부 ID와 같은 주소도 거절한다(앵커 치환 — 권한·잠금·감사는 그대로) ------------
do $migration$
declare
  definition text := pg_catalog.pg_get_functiondef('public.admin_update_ip_identity(text,text,text)'::regprocedure);
  anchor constant text := $anchor$    where ip.public_slug = target_public_slug
      and ip.id <> target_id$anchor$;
  replacement constant text := $replacement$    where (ip.public_slug = target_public_slug or ip.id = target_public_slug)
      and ip.id <> target_id$replacement$;
begin
  if (pg_catalog.length(definition) - pg_catalog.length(pg_catalog.replace(definition, anchor, '')))
     / pg_catalog.length(anchor) <> 1 then
    raise exception 'admin_update_ip_identity anchor must occur exactly once';
  end if;
  execute pg_catalog.replace(definition, anchor, replacement);
end;
$migration$

-- 5. 새 IP 등록: 내부 ID 자동 발급 ------------------------------------------------------------------
create function public.admin_create_ip(
  target_public_slug text,
  target_title text,
  target_sub text,
  target_vertical_key text,
  target_tagline text,
  target_synopsis text,
  target_glyph text,
  target_bg text,
  target_image_path text,
  target_publish boolean default null
)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor_id uuid;
  requested_slug text := pg_catalog.btrim(coalesce(target_public_slug, ''));
  requested_title text := pg_catalog.btrim(coalesce(target_title, ''));
  issued_id text;
  suffix integer := 1;
begin
  actor_id := private.require_operator_capability('platform.manage', false);

  if requested_slug !~ '^[a-z0-9](?:[a-z0-9-]{0,78}[a-z0-9])?$' or requested_slug = 'aouad' then
    raise invalid_parameter_value using message = 'invalid_ip_public_slug';
  end if;
  if requested_title = '' then
    raise invalid_parameter_value using message = 'invalid_ip_title';
  end if;
  if target_vertical_key is null
     or not exists (select 1 from public.verticals as vertical where vertical.key = target_vertical_key)
  then
    raise invalid_parameter_value using message = 'invalid_ip_vertical';
  end if;

  -- Slug, alias and ID checks share the identity lock with admin_update_ip_identity,
  -- the insert trigger and admin_delete_draft_ip.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ip_public_slug_identity', 0)
  );
  if exists (
    select 1 from public.ips as ip
    where ip.public_slug = requested_slug or ip.id = requested_slug
  ) or exists (
    select 1 from public.ip_public_slug_aliases as alias where alias.slug = requested_slug
  ) then
    raise unique_violation using message = 'ip_public_slug_taken';
  end if;

  issued_id := requested_slug;
  while exists (
    select 1 from public.ips as ip where ip.id = issued_id or ip.public_slug = issued_id
  ) or exists (
    select 1 from public.ip_public_slug_aliases as alias where alias.slug = issued_id
  ) or exists (
    select 1 from private.retired_ip_ids as retired where retired.id = issued_id
  ) loop
    suffix := suffix + 1;
    issued_id := requested_slug || '-' || suffix::text;
  end loop;

  perform pg_catalog.set_config('app.ip_public_slug_write', 'admin_create_ip', true);
  insert into public.ips (
    id, public_slug, title, sub, vertical_key, tagline, synopsis, glyph, bg, image_path, featured
  )
  values (
    issued_id, requested_slug, requested_title, target_sub, target_vertical_key,
    target_tagline, target_synopsis, target_glyph, target_bg, target_image_path, false
  );
  perform pg_catalog.set_config('app.ip_public_slug_write', '', true);

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'catalog.ip.upsert',
    'ips:' || issued_id,
    pg_catalog.jsonb_build_object(
      'id', issued_id,
      'title', requested_title,
      'vertical_key', target_vertical_key,
      'mode', 'create',
      'public_slug', requested_slug,
      'id_issued', true
    )
  );

  -- 게시 상태는 저장과 같은 transaction 에서 한 번만 전환하고 별도로 감사한다(admin_upsert_ip와 같다).
  if target_publish is not null then
    perform private.set_ip_published(issued_id, target_publish);
  end if;

  return issued_id;
end;
$$

-- 6. 삭제 가능 여부 ---------------------------------------------------------------------------------
-- 참조 수는 항상 같은 키로 돌려준다(0건도 근거로 보여 준다). IP를 가리키는 FK는 카탈로그에서 읽어 앞으로
-- 생기는 FK도 빠짐없이 센다 — 아는 표는 이름이 있는 키로, 모르는 표는 other로.
create function private.ip_delete_readiness(target_id text)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  ip_row public.ips;
  alias_slugs text[];
  names text[];
  counts jsonb := pg_catalog.jsonb_build_object(
    'goods', 0, 'cards', 0, 'card_pools', 0, 'reward_policies', 0, 'events', 0,
    'home_curations', 0, 'coupons', 0, 'order_items', 0, 'ip_follows', 0, 'posts', 0, 'other', 0
  );
  reference record;
  reference_key text;
  reference_count bigint;
  reference_total bigint;
  public_history boolean;
  state text;
begin
  select * into ip_row from public.ips as ip where ip.id = target_id;
  if not found then
    return null;
  end if;

  state := case
    when ip_row.archived_at is not null then 'archived'
    when ip_row.published_at is not null then 'published'
    else 'draft'
  end;
  public_history := ip_row.published_at is not null
    or exists (select 1 from private.ip_public_history as history where history.ip_id = target_id)
    or exists (
      select 1 from public.audit_log as audit
      where audit.target = 'ips:' || target_id
        and audit.action in ('admin.ip.published', 'admin.ip.unpublished')
    );

  select coalesce(pg_catalog.array_agg(alias.slug order by alias.slug), '{}')
    into alias_slugs
  from public.ip_public_slug_aliases as alias
  where alias.ip_id = target_id;
  names := alias_slugs || array[target_id, ip_row.public_slug];

  for reference in
    select
      namespace.nspname as schema_name,
      relation.relname as table_name,
      column_row.attname as column_name,
      referenced.attname as referenced_column
    from pg_catalog.pg_constraint as constraint_row
    join pg_catalog.pg_class as relation on relation.oid = constraint_row.conrelid
    join pg_catalog.pg_namespace as namespace on namespace.oid = relation.relnamespace
    cross join lateral unnest(constraint_row.conkey, constraint_row.confkey) as pair(conkey, confkey)
    join pg_catalog.pg_attribute as column_row
      on column_row.attrelid = constraint_row.conrelid and column_row.attnum = pair.conkey
    join pg_catalog.pg_attribute as referenced
      on referenced.attrelid = constraint_row.confrelid and referenced.attnum = pair.confkey
    where constraint_row.contype = 'f'
      and constraint_row.confrelid = 'public.ips'::regclass
      and referenced.attname in ('id', 'public_slug')
    order by 1, 2, 3
  loop
    reference_key := case reference.schema_name || '.' || reference.table_name
      when 'public.goods' then 'goods'
      when 'public.cards' then 'cards'
      when 'public.card_pools' then 'card_pools'
      when 'public.reward_policies' then 'reward_policies'
      when 'public.events' then 'events'
      when 'public.home_curations' then 'home_curations'
      when 'public.ip_follows' then 'ip_follows'
      when 'public.posts' then 'posts'
      -- The IP's own evidence and former URLs are not references to it.
      when 'private.ip_public_history' then null
      when 'public.ip_public_slug_aliases' then null
      else 'other'
    end;
    continue when reference_key is null;
    execute pg_catalog.format(
      'select pg_catalog.count(*) from %I.%I where %I = $1',
      reference.schema_name, reference.table_name, reference.column_name
    )
      into reference_count
      using case when reference.referenced_column = 'public_slug' then ip_row.public_slug else target_id end;
    counts := pg_catalog.jsonb_set(
      counts, array[reference_key],
      pg_catalog.to_jsonb((counts ->> reference_key)::bigint + reference_count)
    );
  end loop;

  select pg_catalog.count(*) into reference_count
  from public.coupons as coupon
  where target_id = any(coupon.target_ip_ids);
  counts := pg_catalog.jsonb_set(counts, '{coupons}', pg_catalog.to_jsonb(reference_count));

  select pg_catalog.count(*) into reference_count
  from public.order_items as item
  where item.good_ip_id_snapshot = target_id;
  counts := pg_catalog.jsonb_set(counts, '{order_items}', pg_catalog.to_jsonb(reference_count));

  -- Banners and curations that link to the IP page by path (rows bound by FK were counted above).
  select pg_catalog.count(*) into reference_count
  from public.home_curations as curation
  where curation.ip_id is distinct from target_id
    and curation.link_path is not null
    and (
      pg_catalog.substring(curation.link_path, '^/ip/([^/?#]+)') = any(names)
      or pg_catalog.substring(curation.link_path, '^/ip[?](?:[^#]*&)?ip=([^&#]+)') = any(names)
    );
  counts := pg_catalog.jsonb_set(
    counts, '{home_curations}',
    pg_catalog.to_jsonb((counts ->> 'home_curations')::bigint + reference_count)
  );

  select coalesce(pg_catalog.sum(entry.value::bigint), 0) into reference_total
  from pg_catalog.jsonb_each_text(counts) as entry;

  return pg_catalog.jsonb_build_object(
    'id', ip_row.id,
    'title', ip_row.title,
    'publicSlug', ip_row.public_slug,
    'state', state,
    'publicHistory', public_history,
    'aliases', pg_catalog.to_jsonb(alias_slugs),
    'references', counts,
    'referenceTotal', reference_total,
    'deletable', state = 'draft' and not public_history and reference_total = 0
  );
end;
$$

create function public.admin_ip_delete_readiness(target_id text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.has_operator_capability('platform.manage', false) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  if target_id is null or target_id !~ '^[a-z0-9][a-z0-9-]*$' then
    raise invalid_parameter_value using message = 'invalid_ip_id';
  end if;
  return private.ip_delete_readiness(target_id);
end;
$$

-- 7. 미사용 초안 삭제 -------------------------------------------------------------------------------
create function public.admin_delete_draft_ip(target_id text)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor_id uuid;
  ip_row public.ips;
  readiness jsonb;
  deletion_audit_id uuid;
begin
  -- 되돌릴 수 없는 물리 삭제라 legacy 운영에서는 admin만, 설정된 운영자 권한에서는 platform.manage만 연다.
  actor_id := private.require_operator_capability('platform.manage', true);
  if target_id is null or target_id !~ '^[a-z0-9][a-z0-9-]*$' then
    raise invalid_parameter_value using message = 'invalid_ip_id';
  end if;

  -- Identity lock first, then the row lock (same order as admin_update_ip_identity).
  -- The row lock blocks concurrent FK inserts (FOR KEY SHARE) and publish/archive writers.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ip_public_slug_identity', 0)
  );
  select * into ip_row from public.ips as ip where ip.id = target_id for update of ip;
  if not found then
    -- A replay after a successful delete is a no-op, not a new audit event.
    if exists (select 1 from private.retired_ip_ids as retired where retired.id = target_id) then
      return false;
    end if;
    raise no_data_found using message = 'catalog_not_found';
  end if;

  readiness := private.ip_delete_readiness(target_id);
  if readiness ->> 'state' <> 'draft' then
    raise check_violation using message = 'ip_not_draft';
  end if;
  if (readiness ->> 'publicHistory')::boolean then
    raise check_violation using message = 'ip_has_public_history';
  end if;
  if (readiness ->> 'referenceTotal')::bigint <> 0 then
    raise check_violation using message = 'ip_has_references';
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'catalog.ip.deleted',
    'ips:' || target_id,
    pg_catalog.jsonb_build_object(
      'snapshot', pg_catalog.to_jsonb(ip_row),
      'aliases', readiness -> 'aliases',
      'references', readiness -> 'references',
      'public_history', false,
      'retired_id', target_id
    )
  )
  returning id into deletion_audit_id;

  insert into private.retired_ip_ids (id, public_slug, retired_by, audit_log_id)
  values (target_id, ip_row.public_slug, actor_id, deletion_audit_id);

  delete from public.ip_public_slug_aliases where ip_id = target_id;
  delete from public.ips where id = target_id;
  return true;
end;
$$

-- 8. 쿠폰 대상 IP 잠금 ---------------------------------------------------------------------------------
-- 이번 쓰기로 추가되는 대상만 본다 — 기존 정의는 이미 가리키던 IP(보관 IP 포함)를 그대로 둘 수 있다(쿠폰 RPC와 같은 규칙).
create function private.lock_coupon_target_ips()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  previous_ids text[] := '{}';
  added_ids text[];
  locked_count integer;
begin
  if tg_op = 'UPDATE' then
    previous_ids := coalesce(old.target_ip_ids, '{}');
  end if;
  select coalesce(pg_catalog.array_agg(distinct target.id order by target.id), '{}')
    into added_ids
  from pg_catalog.unnest(coalesce(new.target_ip_ids, '{}')) as target(id)
  where not target.id = any(previous_ids);
  if pg_catalog.cardinality(added_ids) = 0 then
    return new;
  end if;

  -- FOR KEY SHARE in ID order: an IP deletion (FOR UPDATE) either waits for this coupon to commit
  -- and then counts it as a reference, or commits first so that this write no longer finds the IP.
  select pg_catalog.count(*) into locked_count
  from (
    select ip.id
    from public.ips as ip
    where ip.id = any(added_ids)
    order by ip.id
    for key share of ip
  ) as kept;
  if locked_count <> pg_catalog.cardinality(added_ids) then
    raise check_violation using message = 'coupon_target_ip_unavailable';
  end if;
  return new;
end;
$$

create trigger coupons_lock_target_ips
before insert or update of target_ip_ids on public.coupons
for each row execute function private.lock_coupon_target_ips()

do $patch$
declare
  item record;
  body text;
  token constant text := $a$'platform.manage'$a$;
  guard constant text := $a$(require_operator_capability|has_operator_capability)\('platform\.manage'$a$;
  found_tokens integer;
  found_guards integer;
begin
  for item in select * from (values
    ('public.admin_import_erp_items(jsonb)'),
    ('public.admin_search_erp_items(text,integer)'),
    ('public.admin_list_erp_items(text,integer,integer)'),
    ('public.admin_list_erp_categories()'),
    ('public.admin_set_erp_category_mapping(text,uuid)'),
    ('public.admin_set_erp_category_mappings(jsonb)')
  ) as target(signature)
  loop
    body := pg_get_functiondef(item.signature::regprocedure);
    found_tokens := (length(body) - length(replace(body, token, ''))) / length(token);
    select count(*) into found_guards from regexp_matches(body, guard, 'g');
    if found_tokens <> 2 or found_guards <> 2 then
      raise exception 'erp_items_catalog_manage_anchor_changed: % (tokens %, guards %)', item.signature, found_tokens, found_guards;
    end if;
    execute replace(body, token, $a$'catalog.manage'$a$);
  end loop;
end $patch$

-- 미리보기: 비교 범위(붙여넣은 ERP 코드 또는 전체)의 계획을 operation에 고정하고 돌려준다. 상품은 바꾸지 않는다.
-- 같은 operation id로 다시 부르면 고정해 둔 미리보기를 돌려준다. 값이 다른 행이 없으면 operation을 남기지 않는다.
create function public.admin_preview_erp_linked_goods(p_operation_id uuid, p_codes text[] default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_existing private.erp_goods_apply_operations;
  v_codes text[];
  v_plan jsonb;
  v_rows jsonb;
  v_total integer;
  v_expires timestamptz := pg_catalog.clock_timestamp() + interval '15 minutes';
  v_result jsonb;
begin
  perform private.require_operator_capability('catalog.manage', false);
  if v_actor is null or not public.has_operator_capability('catalog.manage', false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if p_operation_id is null then
    raise invalid_parameter_value using message = 'invalid_erp_goods_apply_request';
  end if;
  if p_codes is not null then
    if pg_catalog.cardinality(p_codes) not between 1 and 5000
       or exists (select 1 from pg_catalog.unnest(p_codes) as code(value)
                  where code.value is null or pg_catalog.length(code.value) > 200) then
      raise invalid_parameter_value using message = 'invalid_erp_goods_apply_request';
    end if;
    -- 반입과 같은 규칙으로 다듬어 저장된 ERP 코드와 맞춘다.
    select coalesce(pg_catalog.array_agg(distinct normalized.value), array[]::text[]) into v_codes
    from (select private.erp_item_text(code.value, false) as value from pg_catalog.unnest(p_codes) as code(value)) as normalized
    where normalized.value is not null;
  end if;

  select * into v_existing from private.erp_goods_apply_operations where id = p_operation_id;
  if found then
    if v_existing.actor_id <> v_actor then
      raise insufficient_privilege using message = 'erp_goods_apply_unavailable';
    end if;
    return v_existing.preview;
  end if;

  -- 지난 미리보기·영수증은 30일만 둔다(반영 내역은 감사 기록에 남는다).
  delete from private.erp_goods_apply_operations where created_at < pg_catalog.clock_timestamp() - interval '30 days';

  v_plan := private.erp_linked_goods_plan(v_codes);
  v_total := pg_catalog.jsonb_array_length(v_plan -> 'rows');
  select coalesce(pg_catalog.jsonb_agg(entry.value order by entry.ordinality), '[]'::jsonb) into v_rows
  from pg_catalog.jsonb_array_elements(v_plan -> 'rows') with ordinality as entry(value, ordinality)
  where entry.ordinality <= 500;

  v_result := pg_catalog.jsonb_build_object(
    'operationId', p_operation_id,
    'expiresAt', v_expires,
    'scopeCount', case when v_codes is null then null else pg_catalog.cardinality(v_codes) end,
    'linked', v_plan -> 'linked',
    'total', v_total,
    'truncated', v_total > 500,
    'rows', v_rows);

  if v_total > 0 then
    insert into private.erp_goods_apply_operations (id, actor_id, scope_codes, preview, expires_at)
    values (p_operation_id, v_actor, v_codes, v_result, v_expires);
  end if;
  return v_result;
end;
$$

-- 확정: 미리보기에서 고른 행(key)만 반영한다. 같은 operation을 다시 보내면 남겨 둔 결과를 돌려준다.
-- 고른 행이 미리보기에 없거나 건너뛰는 행이면 요청 오류, 같은 상품의 판매가 행을 일부만 골라 옵션 판매가가 상품 판매가보다
-- 낮아지면 erp_goods_apply_partial_price(상품 이름은 detail), 다른 작업이 같은 상품을 저장 중이면 erp_goods_apply_busy로 거절하고
-- operation은 그대로 둔다(고쳐서 다시 확정할 수 있다). 미리보기 뒤 값이 바뀌었거나 15분이 지났으면 아무것도 바꾸지 않은
-- 거절 결과를 남긴다(다시 비교해야 한다).
create function public.admin_commit_erp_linked_goods(p_operation_id uuid, p_keys text[])
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_operation private.erp_goods_apply_operations;
  v_keys text[];
  v_selected jsonb;
  v_current jsonb;
  v_good_ids text[];
  v_variant_ids uuid[];
  v_good_id text;
  v_good public.goods;
  v_final_base integer;
  v_options jsonb;
  v_baseline jsonb;
  v_row jsonb;
  v_identity private.goods_variant_external_identity;
  v_failure text;
  v_applied jsonb := '[]'::jsonb;
  v_failed jsonb := '[]'::jsonb;
  v_receipt jsonb;
begin
  perform private.require_operator_capability('catalog.manage', false);
  if v_actor is null or not public.has_operator_capability('catalog.manage', false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if p_operation_id is null or p_keys is null
     or pg_catalog.cardinality(p_keys) not between 1 and 500
     or pg_catalog.array_position(p_keys, null) is not null then
    raise invalid_parameter_value using message = 'invalid_erp_goods_apply_keys';
  end if;
  select pg_catalog.array_agg(distinct key.value) into v_keys from pg_catalog.unnest(p_keys) as key(value);

  select * into v_operation from private.erp_goods_apply_operations where id = p_operation_id for update;
  if not found or v_operation.actor_id <> v_actor then
    raise insufficient_privilege using message = 'erp_goods_apply_unavailable';
  end if;
  if v_operation.receipt is not null then
    return v_operation.receipt;
  end if;

  select coalesce(pg_catalog.jsonb_agg(entry.value order by entry.ordinality), '[]'::jsonb) into v_selected
  from pg_catalog.jsonb_array_elements(v_operation.preview -> 'rows') with ordinality as entry(value, ordinality)
  where entry.value ->> 'key' = any(v_keys) and entry.value ->> 'status' = 'apply';
  if pg_catalog.jsonb_array_length(v_selected) <> pg_catalog.cardinality(v_keys) then
    raise invalid_parameter_value using message = 'invalid_erp_goods_apply_keys';
  end if;

  if v_operation.expires_at <= pg_catalog.clock_timestamp() then
    v_receipt := pg_catalog.jsonb_build_object('state', 'rejected', 'operationId', p_operation_id, 'error', 'erp_goods_apply_expired');
    update private.erp_goods_apply_operations set receipt = v_receipt where id = p_operation_id;
    return v_receipt;
  end if;

  select pg_catalog.array_agg(distinct row.value ->> 'goodId' order by row.value ->> 'goodId'),
         pg_catalog.array_agg(distinct (row.value ->> 'variantId')::uuid)
  into v_good_ids, v_variant_ids
  from pg_catalog.jsonb_array_elements(v_selected) as row(value);

  -- 잠금 순서: ERP 반입(값 고정) → 카테고리 트리 → 상품별 편집 잠금 → 상품 행 → 옵션 행 → 옵션 ERP 식별자.
  -- 상품 저장(admin_save_good)과 같은 순서라 편집 화면 저장과 교착하지 않는다.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.erp_items.import', 0));
  perform private.lock_catalog_category_tree();
  foreach v_good_id in array v_good_ids loop
    if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('admin_good:' || v_good_id, 0)) then
      raise sqlstate 'PT409' using message = 'erp_goods_apply_busy';
    end if;
  end loop;
  perform 1 from public.goods where id = any(v_good_ids) order by id for update;
  perform 1 from public.goods_variants where good_id = any(v_good_ids) order by id for update;
  perform 1 from private.goods_variant_external_identity where variant_id = any(v_variant_ids) order by variant_id for update;

  -- 잠근 뒤 같은 계산을 다시 해 고른 행이 미리보기와 같은지 본다. 하나라도 다르면 아무것도 바꾸지 않는다.
  -- 행 키로 찾을 수 있게 key → 행 객체로 묶는다(고른 행마다 전체 계획을 다시 펼치지 않는다).
  select coalesce(pg_catalog.jsonb_object_agg(fresh.value ->> 'key', fresh.value), '{}'::jsonb) into v_current
  from pg_catalog.jsonb_array_elements(private.erp_linked_goods_plan(v_operation.scope_codes) -> 'rows') as fresh(value);
  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(v_selected) as chosen(value)
    where v_current -> (chosen.value ->> 'key') is null
       or (v_current -> (chosen.value ->> 'key') -> 'goodId') is distinct from chosen.value -> 'goodId'
       or (v_current -> (chosen.value ->> 'key') -> 'current') is distinct from chosen.value -> 'current'
       or (v_current -> (chosen.value ->> 'key') -> 'next') is distinct from chosen.value -> 'next'
       or (v_current -> (chosen.value ->> 'key') -> 'status') is distinct from chosen.value -> 'status'
  ) then
    v_receipt := pg_catalog.jsonb_build_object('state', 'rejected', 'operationId', p_operation_id, 'error', 'erp_goods_apply_changed');
    update private.erp_goods_apply_operations set receipt = v_receipt where id = p_operation_id;
    return v_receipt;
  end if;

  -- 같은 상품의 판매가 행을 일부만 고르면 미리보기에서 본 상품 단위 검사와 결과가 달라질 수 있다. 고른 행만으로 다시 본다.
  foreach v_good_id in array v_good_ids loop
    if not exists (select 1 from pg_catalog.jsonb_array_elements(v_selected) as row(value)
                   where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price') then
      continue;
    end if;
    select * into v_good from public.goods where id = v_good_id;
    v_final_base := coalesce((
      select (row.value ->> 'next')::integer
      from pg_catalog.jsonb_array_elements(v_selected) as row(value)
      join public.goods_variants as variant on variant.id = (row.value ->> 'variantId')::uuid
      where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price' and variant.is_default
    ), v_good.price);
    if exists (
         select 1
         from public.goods_variants as variant
         left join pg_catalog.jsonb_array_elements(v_selected) as row(value)
           on row.value ->> 'field' = 'price' and (row.value ->> 'variantId')::uuid = variant.id
         where variant.good_id = v_good_id
           and (variant.archived_at is null or variant.is_default)
           and coalesce((row.value ->> 'next')::integer, variant.price) < v_final_base
       ) then
      raise check_violation using message = 'erp_goods_apply_partial_price', detail = v_good.name;
    end if;
  end loop;

  foreach v_good_id in array v_good_ids loop
    select * into v_good from public.goods where id = v_good_id;

    -- 판매가: 상품 목록의 판매가 바로 수정과 같은 상품 저장 RPC(admin_save_good)를 부른다. 고르지 않은 옵션의 판매 금액은 그대로 둔다.
    -- 옵션 행은 상품 편집 저장과 같다(lib/admin/goods-option-editor.ts initialGoodsOptionRows: 사용 중인 옵션 + 사용 중지된 기본 옵션,
    -- 기본 옵션이 첫 행). private.save_goods_options는 첫 행을 기본 옵션으로 정하므로, 사용 중지된 기본 옵션을 isActive=false로
    -- 첫 행에 실어 기본 옵션이 다른 옵션으로 바뀌지 않게 한다. 그 밖의 사용 중지 옵션은 싣지 않아 그대로 남는다.
    if exists (select 1 from pg_catalog.jsonb_array_elements(v_selected) as row(value)
               where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price') then
      v_final_base := coalesce((
        select (row.value ->> 'next')::integer
        from pg_catalog.jsonb_array_elements(v_selected) as row(value)
        join public.goods_variants as variant on variant.id = (row.value ->> 'variantId')::uuid
        where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price' and variant.is_default
      ), v_good.price);
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'id', variant.id, 'name', variant.name, 'attributes', variant.attributes, 'code', variant.code,
          'extraPrice', coalesce((chosen.value ->> 'next')::integer, variant.price) - v_final_base,
          'stockQty', variant.stock_qty, 'expectedStockQty', variant.stock_qty, 'isActive', variant.archived_at is null,
          'lowStockThreshold', variant.low_stock_threshold)
        order by variant.is_default desc, variant.sort_order, variant.id)
      into v_options
      from public.goods_variants as variant
      left join pg_catalog.jsonb_array_elements(v_selected) as chosen(value)
        on chosen.value ->> 'field' = 'price' and (chosen.value ->> 'variantId')::uuid = variant.id
      where variant.good_id = v_good_id and (variant.archived_at is null or variant.is_default);
      select coalesce(pg_catalog.jsonb_agg(variant.id::text order by variant.id), '[]'::jsonb) into v_baseline
      from public.goods_variants as variant
      where variant.good_id = v_good_id and variant.archived_at is null;
      begin
        perform public.admin_save_good(pg_catalog.to_jsonb(v_good) || pg_catalog.jsonb_build_object(
          'previous_id', v_good.id, 'publish', null, 'custom_inputs_expected_revision', v_good.custom_inputs_revision,
          'price', v_final_base, 'variants', v_options, 'variant_baseline', v_baseline));
        select v_applied || coalesce(pg_catalog.jsonb_agg(row.value order by row.value ->> 'key'), '[]'::jsonb) into v_applied
        from pg_catalog.jsonb_array_elements(v_selected) as row(value)
        where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price';
      exception when others then
        get stacked diagnostics v_failure = message_text;
        select v_failed || coalesce(pg_catalog.jsonb_agg(row.value || pg_catalog.jsonb_build_object('error',
            case when v_failure ~ '^[a-z][a-z0-9_]{0,100}$' then v_failure else 'goods_save_rejected' end)
          order by row.value ->> 'key'), '[]'::jsonb) into v_failed
        from pg_catalog.jsonb_array_elements(v_selected) as row(value)
        where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price';
      end;
    end if;

    -- 바코드: 옵션 ERP 식별자 저장 함수로 바꾼다(잠금·낙관적 확인·감사 기록이 그 함수에 있다). ERP 코드·품명은 그대로 둔다.
    for v_row in
      select row.value from pg_catalog.jsonb_array_elements(v_selected) as row(value)
      where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'barcode'
      order by row.value ->> 'key'
    loop
      begin
        select * into v_identity from private.goods_variant_external_identity
        where variant_id = (v_row ->> 'variantId')::uuid;
        perform private.save_goods_variant_external_identity(
          v_good_id, (v_row ->> 'variantId')::uuid, v_identity.erp_code, v_identity.erp_name,
          v_row ->> 'next', v_identity.updated_at, v_actor);
        v_applied := v_applied || pg_catalog.jsonb_build_array(v_row);
      exception when others then
        get stacked diagnostics v_failure = message_text;
        v_failed := v_failed || pg_catalog.jsonb_build_array(v_row || pg_catalog.jsonb_build_object('error',
          case when v_failure ~ '^[a-z][a-z0-9_]{0,100}$' then v_failure else 'goods_save_rejected' end));
      end;
    end loop;
  end loop;

  v_receipt := pg_catalog.jsonb_build_object(
    'state', 'completed',
    'operationId', p_operation_id,
    'applied', pg_catalog.jsonb_build_object(
      'price', (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_applied) as row(value) where row.value ->> 'field' = 'price'),
      'barcode', (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_applied) as row(value) where row.value ->> 'field' = 'barcode'),
      'goods', (select pg_catalog.count(distinct row.value ->> 'goodId') from pg_catalog.jsonb_array_elements(v_applied) as row(value))),
    'failed', (
      select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'key', row.value ->> 'key', 'field', row.value ->> 'field', 'goodId', row.value ->> 'goodId',
          'goodName', row.value ->> 'goodName', 'optionName', row.value ->> 'optionName', 'error', row.value ->> 'error')
        order by row.value ->> 'key'), '[]'::jsonb)
      from pg_catalog.jsonb_array_elements(v_failed) as row(value)));

  insert into public.audit_log (actor_id, action, target, diff)
  values (v_actor, 'admin.erp_items.linked_goods_applied', 'erp_items', pg_catalog.jsonb_build_object(
    'operationId', p_operation_id,
    'scopeCount', case when v_operation.scope_codes is null then null else pg_catalog.cardinality(v_operation.scope_codes) end,
    'applied', (
      select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'key', row.value ->> 'key', 'field', row.value ->> 'field', 'goodId', row.value ->> 'goodId',
          'variantId', row.value ->> 'variantId', 'erpCode', row.value ->> 'erpCode',
          'before', row.value -> 'current', 'after', row.value -> 'next', 'warning', row.value -> 'warning')
        order by row.value ->> 'key'), '[]'::jsonb)
      from pg_catalog.jsonb_array_elements(v_applied) as row(value)),
    'failed', v_receipt -> 'failed'));

  update private.erp_goods_apply_operations set receipt = v_receipt where id = p_operation_id;
  return v_receipt;
end;
$$

create function private.goods_announcement_placement_patch(p_function regprocedure, p_patches jsonb)
returns void
language plpgsql
volatile
set search_path = ''
as $helper$
declare
  v_definition text := pg_catalog.pg_get_functiondef(p_function);
  v_patch jsonb;
  v_found integer;
begin
  for v_patch in select value from pg_catalog.jsonb_array_elements(p_patches) loop
    v_found := (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_patch->>0, '')))
      / pg_catalog.length(v_patch->>0);
    if v_found <> 1 then
      raise exception 'goods_announcement_placement_anchor_changed: % (% matches)', p_function, v_found;
    end if;
    v_definition := pg_catalog.replace(v_definition, v_patch->>0, v_patch->>1);
  end loop;
  execute v_definition;
end;
$helper$

