create function public.admin_save_shipping_notice_template_v2(
  target_id uuid, target_code text, target_version integer, target_name text,
  target_shipping_notice text, target_return_exchange_notice text, target_remote_area_notice text,
  target_cs_name text, target_cs_phone text, target_cs_email text, expected_updated_at timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  actor uuid := (select auth.uid());
  previous public.shipping_notice_templates;
  saved public.shipping_notice_templates;
  normalized_code text := btrim(coalesce(target_code, ''), E' \t\n\r');
  normalized_name text := btrim(coalesce(target_name, ''), E' \t\n\r');
  normalized_shipping text := btrim(coalesce(target_shipping_notice, ''), E' \t\n\r');
  normalized_return_exchange text := btrim(coalesce(target_return_exchange_notice, ''), E' \t\n\r');
  normalized_remote_area text := btrim(coalesce(target_remote_area_notice, ''), E' \t\n\r');
  normalized_cs_name text := btrim(coalesce(target_cs_name, ''), E' \t\n\r');
  normalized_cs_phone text := btrim(coalesce(target_cs_phone, ''), E' \t\n\r');
  normalized_cs_email text := btrim(coalesce(target_cs_email, ''), E' \t\n\r');
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null or not public.has_operator_capability('catalog.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if normalized_code !~ '^[a-z][a-z0-9-]{1,39}$'
    or target_version is null or target_version not between 1 and 1000000
    or char_length(normalized_name) not between 1 and 80
    or char_length(normalized_shipping) > 4000 or char_length(normalized_return_exchange) > 4000
    or char_length(normalized_remote_area) > 4000
    or char_length(normalized_cs_name) > 120 or char_length(normalized_cs_phone) > 80
    or char_length(normalized_cs_email) > 320
    or private.has_disallowed_shipping_notice_control(normalized_shipping)
    or private.has_disallowed_shipping_notice_control(normalized_return_exchange)
    or private.has_disallowed_shipping_notice_control(normalized_remote_area)
    or private.has_disallowed_shipping_notice_control(normalized_cs_name)
    or private.has_disallowed_shipping_notice_control(normalized_cs_phone)
    or private.has_disallowed_shipping_notice_control(normalized_cs_email)
  then
    raise invalid_parameter_value using message = 'invalid_shipping_notice_template';
  end if;

  if target_id is not null then
    select * into previous from public.shipping_notice_templates where id = target_id for update;
    if not found then raise no_data_found using message = 'shipping_notice_template_not_found'; end if;
    if previous.updated_at is distinct from expected_updated_at then
      raise exception using errcode = 'PT409', message = 'shipping_notice_template_conflict';
    end if;
    if previous.status <> 'draft' then
      raise check_violation using message = 'shipping_notice_template_active_immutable';
    end if;
    if previous.code <> normalized_code or previous.version <> target_version then
      raise check_violation using message = 'shipping_notice_template_identity_locked';
    end if;
    update public.shipping_notice_templates set
      name = normalized_name,
      shipping_notice = normalized_shipping,
      return_exchange_notice = normalized_return_exchange,
      remote_area_notice = normalized_remote_area,
      cs_name = normalized_cs_name,
      cs_phone = normalized_cs_phone,
      cs_email = normalized_cs_email,
      updated_at = greatest(clock_timestamp(), previous.updated_at + interval '1 microsecond')
      where id = target_id returning * into saved;
  else
    if expected_updated_at is not null then
      raise invalid_parameter_value using message = 'invalid_shipping_notice_template';
    end if;
    insert into public.shipping_notice_templates(
      code, version, name, shipping_notice, return_exchange_notice, remote_area_notice, cs_name, cs_phone, cs_email
    ) values (
      normalized_code, target_version, normalized_name, normalized_shipping, normalized_return_exchange,
      normalized_remote_area, normalized_cs_name, normalized_cs_phone, normalized_cs_email
    ) returning * into saved;
  end if;

  insert into public.audit_log(actor_id, action, target, diff)
    values (
      actor,
      case when target_id is null then 'catalog.shipping_notice_template.created'
        else 'catalog.shipping_notice_template.updated' end,
      'shipping_notice_templates:' || saved.id::text,
      jsonb_build_object('before', to_jsonb(previous), 'after', to_jsonb(saved))
    );
  return jsonb_build_object('id', saved.id, 'version', saved.version, 'updatedAt', saved.updated_at);
end;
$function$

-- ==========================================================================
-- ICONS · 상품 상세 배송 안내의 지역별 추가 배송비(S36-038, 묶음 15)
--
-- 상세 배송 안내에 '제주 +₩3,000 · 도서산간 +₩5,000~₩7,000(배송 묶음당 1회)'처럼 이
-- 굿즈의 출고지·현재 기본 택배사에 지금 적용되는 활성 지역 정책의 추가료를 싣는다.
-- 굿즈마다 부과하는 정책은 단위를 '굿즈당 1회'로 밝힌다(feeUnit). 규칙이 없거나 상세에서
-- 한 문장으로 말할 수 없으면 화면은 지금 문장을 둔다.
--
-- 지역명과 금액은 그 정책 지역표의 '추가료 부과'·0원 초과 행에서 그대로 모은다(같은
-- 지역명은 최소~최대, 실제 지역 수도 함께). 계산하거나 일부만 고르지 않는다.
-- 이 굿즈에 추가료가 붙는지, 부과 단위, 무료배송 기준 면제는 주문서와 같은 견적 함수
-- (private.apply_shipping_region_quote)를 대표 행 하나로 견적해 정한다 — 대표 행
-- 금액 그대로 붙으면 다른 행도 그 행의 금액 그대로 붙는다(부과 여부·단위는 행이 아니라
-- 굿즈 배송 유형과 정책 설정이 정한다). 굿즈 1개 견적은 배송 건당·굿즈당 모두 그 행 금액이고,
-- 굿즈당은 대상 굿즈 수만큼 곱해진다. 무료배송 기준 금액으로 한 번 더 견적해 0원이면 면제를
-- 함께 싣는다.
--
-- 'unresolved'(지금 문장)로 두는 경우: 새 거래 런타임이 켜져 있음(묶음그룹 지역표·수령
-- 방식·수량 운임이 행마다 금액을 바꿀 수 있다), 부과 단위를 모름, 견적이 다른 정책·다른 행·
-- 다른 금액으로 판정함. 'none'(지금 문장): 정책이 없음·도입 전 출고지·이 굿즈에 추가료가
-- 붙지 않음. 공개 정보(지역명·금액·지역 수·부과 단위·면제 여부·다음 정책 경계)만 싣고 정책
-- ID·근거 문서·우편번호 구간은 싣지 않는다. 지역 목록은 최소 금액순 20개까지 싣고
-- regionCount가 실제 지역 수다.
-- ==========================================================================

create function public.get_good_shipping_region_fees(target_good_id text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  selected public.goods;
  owner public.goods;
  origin public.fulfillment_origins;
  probe_at timestamptz := statement_timestamp();
  policy private.shipping_region_policies;
  representative record;
  lines jsonb;
  destination jsonb;
  quote_group jsonb;
  fee numeric;
  fee_unit text;
  waived boolean := false;
  regions jsonb;
  region_count integer;
  next_change timestamptz;
  result jsonb;
begin
  -- 공개 배송 정책(get_good_shipping_policy)과 같은 공개 범위·같은 정책 상품·같은 출고지.
  select g.* into selected
  from public.goods g join public.ips ip on ip.id = g.ip_id
  where g.id = target_good_id and g.archived_at is null and g.published_at is not null
    and private.good_sale_restriction_visible(g.sale_restriction, (select auth.uid()))
    and ip.archived_at is null and ip.published_at is not null;
  if not found then return null; end if;
  select * into owner from public.goods where id = private.goods_aggregation_owner(selected.id);
  select * into origin from public.fulfillment_origins where id = owner.origin_id and is_active;
  if not found then return null; end if;

  -- 기존 주문 경로(quote_goods_sales_for_address)와 같은 줄 모양. 합산 관계가 있는 굿즈는
  -- 원상품의 정책을 따른다(기존 경로는 그 굿즈 주문을 막는다). 단가 0원 = 무료 기준 전.
  lines := jsonb_build_array(jsonb_build_object('origin_id', owner.origin_id, 'good_id', owner.id, 'qty', 1,
    'unit_price', 0, 'fee_type', owner.shipping_fee_type, 'individual_fee', owner.individual_fee));
  -- 정책 시작·종료·도입 시각이 오면 상세를 다시 읽는다(주소 없는 견적이 같은 경계를 낸다).
  next_change := (private.apply_shipping_region_quote(private.calculate_goods_shipping(lines), lines, null, probe_at)
    ->>'nextChangeAt')::timestamptz;
  result := jsonb_build_object('state', 'none', 'regions', '[]'::jsonb, 'regionCount', 0, 'feeUnit', null,
    'waivedAtFreeThreshold', false, 'nextChangeAt', next_change);

  if coalesce((select runtime.enabled from private.goods_transaction_runtime runtime where runtime.singleton), false) then
    return result || jsonb_build_object('state', 'unresolved');
  end if;

  select p.* into policy
  from private.shipping_region_policies p
  where p.origin_id = origin.id and p.carrier_code = origin.default_carrier and p.status = 'active'
    and p.starts_at <= probe_at and (p.ends_at is null or probe_at < p.ends_at)
  order by p.starts_at desc, p.version desc
  limit 1;
  if not found then return result; end if;

  -- 대표 행: 0원 초과 추가료 행 중 우편번호·주소 시작문구가 가장 앞선 행. 행의 첫 우편번호와
  -- 주소 시작문구(없으면 아무 기본주소)는 그 행에만 들어간다 — 활성 정책은 겹치는 행을 받지 않는다.
  select (rule->>'id')::uuid as rule_id, (rule->>'amount')::numeric as amount,
    rule->>'postalFrom' as postal_code, rule->>'addressPrefix' as address_prefix
  into representative
  from jsonb_array_elements(policy.configuration->'rules') rule
  where rule->>'disposition' = 'surcharge' and (rule->>'amount')::numeric > 0
  order by rule->>'postalFrom', rule->>'addressPrefix'
  limit 1;
  if not found then return result; end if;
  destination := jsonb_build_object('postalCode', representative.postal_code,
    'address1', coalesce(nullif(representative.address_prefix, ''), '주소'));

  quote_group := private.apply_shipping_region_quote(private.calculate_goods_shipping(lines), lines, destination, probe_at)->'groups'->0;
  -- 도입 전 출고지는 기존 배송비로 확정한다 — 지역료가 없다.
  if quote_group->>'regionMode' = 'legacy_base_only' then return result; end if;
  if quote_group->>'regionStatus' is distinct from 'surcharge'
    or (quote_group->>'policyId')::uuid is distinct from policy.id
    or (quote_group->>'ruleId')::uuid is distinct from representative.rule_id then
    return result || jsonb_build_object('state', 'unresolved');
  end if;
  fee := (quote_group->>'regionalFee')::numeric;
  -- 이 굿즈의 배송 유형에는 지역료를 붙이지 않는 정책이다.
  if fee = 0 then return result; end if;
  -- 굿즈 1개 견적은 배송 건당(최대 1회)·굿즈당(대상 굿즈 수만큼) 모두 그 행 금액이다. 단위는 화면이 밝힌다.
  fee_unit := quote_group->>'feeUnit';
  if fee_unit is null or fee_unit not in ('per_shipment', 'per_good') or fee is distinct from representative.amount then
    return result || jsonb_build_object('state', 'unresolved');
  end if;

  -- 무료배송 기준 면제: 기준 금액으로 다시 견적해 0원이면 면제, 대표 행 금액 그대로면 면제 없음.
  if origin.free_threshold is not null then
    lines := jsonb_set(lines, '{0,unit_price}', to_jsonb(origin.free_threshold));
    quote_group := private.apply_shipping_region_quote(private.calculate_goods_shipping(lines), lines, destination, probe_at)->'groups'->0;
    if quote_group->>'regionStatus' is distinct from 'surcharge'
      or (quote_group->>'ruleId')::uuid is distinct from representative.rule_id
      or quote_group->>'regionalFee' is null
      or (quote_group->>'regionalFee')::numeric not in (0, representative.amount) then
      return result || jsonb_build_object('state', 'unresolved');
    end if;
    waived := (quote_group->>'regionalFee')::numeric = 0;
  end if;

  select count(*)::integer,
    coalesce(jsonb_agg(jsonb_build_object('label', label, 'minFee', min_fee, 'maxFee', max_fee)
      order by min_fee, max_fee, label) filter (where position <= 20), '[]'::jsonb)
  into region_count, regions
  from (
    select label, min_fee, max_fee, row_number() over (order by min_fee, max_fee, label) as position
    from (
      select rule->>'regionLabel' as label, min((rule->>'amount')::numeric) as min_fee, max((rule->>'amount')::numeric) as max_fee
      from jsonb_array_elements(policy.configuration->'rules') rule
      where rule->>'disposition' = 'surcharge' and (rule->>'amount')::numeric > 0
      group by rule->>'regionLabel'
    ) grouped
  ) ranked;

  return result || jsonb_build_object('state', 'listed', 'regions', regions, 'regionCount', region_count,
    'feeUnit', fee_unit, 'waivedAtFreeThreshold', waived);
end;
$function$

alter table public.catalog_categories add constraint catalog_categories_good_type_check check (
  good_type is null or good_type in ('피규어','인형','키링','아크릴','문구','쿠션','파우치','세트','기타')
)

-- --------------------------------------------------------------------------
-- 4. 초안의 유형은 카테고리 연결값으로 맞춘다.
--    공개 중인 행은 건드리지 않는다(저장된 유형 유지). 연결값이 없으면 들어온 값을 둔다 — 그 초안은 공개할 수 없다.
--    그룹 상품의 공통 칸(유형 포함)은 그룹 공통 저장(이 트랜잭션의 쓰기 허가)에서만 바꾼다.
--    이름 순서상 goods_group_common_information_guard·goods_kc_guard보다 먼저 돈다(둘 다 바뀐 유형을 본다).
-- --------------------------------------------------------------------------
create function private.derive_goods_type_from_category()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  derived text;
begin
  if new.published_at is not null then return new; end if;
  derived := private.goods_category_type(new.category_id);
  if derived = '' or new.type is not distinct from derived then return new; end if;
  if tg_op = 'UPDATE'
     and exists(select 1 from private.goods_group_members as member where member.good_id = old.id)
     and not exists(select 1 from private.goods_group_write_authorizations as grant_row
       where grant_row.transaction_id = txid_current() and grant_row.good_id = old.id and grant_row.actor_id = auth.uid()) then
    return new;
  end if;
  new.type := derived;
  return new;
end;
$function$

create trigger goods_category_type_derive
  before insert or update of category_id, type, published_at, archived_at on public.goods
  for each row execute function private.derive_goods_type_from_category()

create function public.admin_upsert_category(
  target_operation_id uuid,
  target_category_id uuid,
  target_code text,
  target_name text,
  target_parent_id uuid,
  target_sort_order integer,
  target_expected_updated_at timestamp with time zone,
  target_good_type text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  actor_id uuid := (select auth.uid());
  category_row public.catalog_categories;
  next_depth integer;
  next_good_type text;
  result_id uuid;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  request_payload jsonb;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor_id is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message = 'forbidden'; end if;
  if target_operation_id is null or target_code is null or target_code !~ '^[a-z0-9][a-z0-9-]*$' or length(target_code) > 80
     or target_name is null or btrim(target_name) = '' or length(target_name) > 120
     or target_sort_order is null or target_sort_order < 0 then
    raise invalid_parameter_value using message = 'invalid_category';
  end if;
  if target_good_type is not null and target_good_type <> ''
     and target_good_type not in ('피규어','인형','키링','아크릴','문구','쿠션','파우치','세트','기타') then
    raise invalid_parameter_value using message = 'invalid_category_good_type';
  end if;
  request_payload := jsonb_build_object(
    'category_id', target_category_id,
    'code', target_code,
    'name', btrim(target_name),
    'parent_id', target_parent_id,
    'sort_order', target_sort_order,
    'expected_updated_at', target_expected_updated_at,
    'good_type', target_good_type
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || target_operation_id::text, 0));
  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;
  if found then
    if existing_actor_id = actor_id
       and existing_action in ('admin.catalog.category.created', 'admin.catalog.category.updated')
       and existing_diff -> 'request' = request_payload
    then
      result_id := coalesce(target_category_id, nullif(existing_diff ->> 'category_id', '')::uuid);
      next_depth := nullif(existing_diff #>> '{after,depth}', '')::integer;
      if result_id is not null and next_depth is not null then
        return jsonb_build_object('id', result_id, 'depth', next_depth, 'goodType', existing_diff #>> '{after,good_type}');
      end if;
    end if;
    raise unique_violation using message = 'operation_conflict';
  end if;
  perform private.lock_catalog_category_tree();

  if target_category_id is null then
    if exists (select 1 from public.catalog_categories where code = target_code) then raise unique_violation using message = 'category_code_taken'; end if;
    result_id := extensions.gen_random_uuid();
    next_depth := private.category_validate_parent(result_id, target_parent_id);
    next_good_type := nullif(target_good_type, '');
    insert into public.catalog_categories (id, code, name, parent_id, depth, sort_order, good_type)
    values (result_id, target_code, btrim(target_name), target_parent_id, next_depth, target_sort_order, next_good_type);
    insert into public.audit_log(id, actor_id, action, target, diff)
    values (target_operation_id, actor_id, 'admin.catalog.category.created', 'catalog_categories:' || result_id::text,
      jsonb_build_object('category_id', result_id, 'request', request_payload,
        'after', jsonb_build_object('code', target_code, 'name', btrim(target_name), 'parent_id', target_parent_id, 'depth', next_depth,
          'good_type', next_good_type)));
  else
    select * into category_row from public.catalog_categories where id = target_category_id for update;
    if not found then raise no_data_found using message = 'category_not_found'; end if;
    if target_expected_updated_at is null or category_row.updated_at is distinct from target_expected_updated_at then raise exception using errcode = 'PT409', message = 'category_changed'; end if;
    if exists (select 1 from public.catalog_categories where code = target_code and id <> target_category_id) then raise unique_violation using message = 'category_code_taken'; end if;
    next_depth := private.category_validate_parent(target_category_id, target_parent_id);
    next_good_type := case when target_good_type is null then category_row.good_type else nullif(target_good_type, '') end;
    -- 연결값·상위가 바뀌면 catalog_categories_good_type_refresh가 그 아래 초안 상품의 유형을 맞춘다.
    update public.catalog_categories
    set code = target_code, name = btrim(target_name), parent_id = target_parent_id, depth = next_depth,
        sort_order = target_sort_order, good_type = next_good_type, updated_at = pg_catalog.now()
    where id = target_category_id;
    with recursive descendants as (
      select category.id, 1 as relative_depth
      from public.catalog_categories as category
      where category.parent_id = target_category_id
      union all
      select child.id, descendants.relative_depth + 1
      from descendants
      join public.catalog_categories as child on child.parent_id = descendants.id
    )
    update public.catalog_categories as child
    set depth = next_depth + descendants.relative_depth, updated_at = pg_catalog.now()
    from descendants
    where child.id = descendants.id;
    result_id := target_category_id;
    insert into public.audit_log(id, actor_id, action, target, diff)
    values (target_operation_id, actor_id, 'admin.catalog.category.updated', 'catalog_categories:' || target_category_id::text,
      jsonb_build_object('category_id', target_category_id, 'request', request_payload,
        'before', jsonb_build_object('good_type', category_row.good_type),
        'after', jsonb_build_object('code', target_code, 'name', btrim(target_name), 'parent_id', target_parent_id, 'depth', next_depth,
          'good_type', next_good_type)));
  end if;
  return jsonb_build_object('id', result_id, 'depth', next_depth, 'goodType', next_good_type);
end;
$function$

-- --------------------------------------------------------------------------
-- 7. 앵커 치환: 현재 정의에서 앵커가 정확히 한 번 나올 때만 바꾼다(다른 migration이 같은 줄을 고쳤으면 실패한다).
-- --------------------------------------------------------------------------
create function private.goods_type_from_category_patch(p_function regprocedure, p_patches jsonb)
returns void
language plpgsql
volatile
set search_path = ''
as $helper$
declare
  v_definition text := pg_catalog.pg_get_functiondef(p_function);
  v_patch jsonb;
  v_found integer;
begin
  for v_patch in select value from pg_catalog.jsonb_array_elements(p_patches) loop
    v_found := (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_patch->>0, '')))
      / pg_catalog.length(v_patch->>0);
    if v_found <> 1 then
      raise exception 'goods_type_from_category_anchor_changed: % (% matches)', p_function, v_found;
    end if;
    v_definition := pg_catalog.replace(v_definition, v_patch->>0, v_patch->>1);
  end loop;
  execute v_definition;
end;
$helper$

-- 7-1. 공개 전환: 필수 입력 확인(goods_publish_incomplete) 뒤에, 대표 카테고리 경로에 연결값이 있고 저장된 유형이 그 값이어야 공개한다.
--      (초안 저장 때 트리거가 맞추므로 다른 경우는 배포 전 초안이나 그룹 개별 저장처럼 아직 맞추지 않은 초안뿐이다.)
select private.goods_type_from_category_patch('private.set_good_published(text,boolean)'::regprocedure, jsonb_build_array(
  jsonb_build_array(
    $anchor$declare selected public.goods; transition_at timestamptz;$anchor$,
    $patched$declare selected public.goods; transition_at timestamptz; category_type text;$patched$),
  jsonb_build_array(
    $anchor$  ) then raise check_violation using message='goods_publish_incomplete'; end if;
$anchor$,
    $patched$  ) then raise check_violation using message='goods_publish_incomplete'; end if;
  -- SHEET-003(ADR-0037): 상품 유형은 대표 카테고리(없으면 가까운 상위)의 연결값이다.
  if publish_requested then
    category_type:=private.goods_category_type(selected.category_id);
    if category_type='' then raise check_violation using message='goods_type_category_required'; end if;
    if selected.type is distinct from category_type then raise check_violation using message='goods_type_category_changed'; end if;
  end if;
$patched$)))

-- 7-2. 상품 저장의 카테고리 층: 공개 중 카테고리 변경은 유형이 그대로일 때만 된다(유형 잠금과 같다).
--      공개 요청은 안쪽 층들처럼 이 층 끝으로 미룬다 — 카테고리를 바꾸며 공개해도 공개 판정이 새 카테고리의 유형을 본다.
select private.goods_type_from_category_patch('private.admin_save_good_before_purchase_cost(jsonb)'::regprocedure, jsonb_build_array(
  jsonb_build_array(
    $anchor$declare saved jsonb; current_good public.goods; category_value uuid; code_value text; code_id uuid;$anchor$,
    $patched$declare saved jsonb; current_good public.goods; category_value uuid; code_value text; code_id uuid;
  defer_publish boolean := false; next_type text;$patched$),
  jsonb_build_array(
    $anchor$  saved:=private.admin_save_good_before_category(target_good-'category_id'-'category_code');$anchor$,
    $patched$  -- SHEET-003: 첫 공개는 카테고리를 바꾼 뒤에 한다(공개 판정이 새 카테고리 유형을 본다).
  defer_publish:=target_good->>'publish'='true';
  saved:=private.admin_save_good_before_category(case when defer_publish
    then (target_good-'category_id'-'category_code')||'{"publish":null}'::jsonb else target_good-'category_id'-'category_code' end);$patched$),
  jsonb_build_array(
    $anchor$  if current_good.category_id is distinct from category_value then
    update public.goods set category_id=category_value where id=current_good.id;$anchor$,
    $patched$  if current_good.category_id is distinct from category_value then
    -- SHEET-003: 공개 중에는 상품 유형이 바뀌는(연결 없음 포함) 카테고리로 옮길 수 없다. 초안 전환 후 바꾼다.
    if current_good.published_at is not null then
      next_type:=private.goods_category_type(category_value);
      if next_type='' then raise check_violation using message='goods_type_category_required'; end if;
      if next_type is distinct from current_good.type then raise check_violation using message='goods_type_category_locked'; end if;
    end if;
    update public.goods set category_id=category_value where id=current_good.id;$patched$),
  jsonb_build_array(
    $anchor$        jsonb_build_object('before',current_good.category_id,'after',category_value));
  end if;
  return saved;$anchor$,
    $patched$        jsonb_build_object('before',current_good.category_id,'after',category_value));
  end if;
  if defer_publish then perform public.admin_set_good_published(saved->>'id',true); end if;
  return saved;$patched$)))

-- 7-3. 카테고리 화면의 대표 분류 적용도 같은 공개 중 유형 잠금을 지킨다.
select private.goods_type_from_category_patch('private.admin_assign_good_category_before_additional(uuid,text,uuid,timestamp with time zone)'::regprocedure, jsonb_build_array(
  jsonb_build_array(
    $anchor$  good_category_id uuid;
$anchor$,
    $patched$  good_category_id uuid;
  good_published_at timestamptz;
  good_type text;
  next_type text;
$patched$),
  jsonb_build_array(
    $anchor$  select updated_at, category_id into good_updated_at, good_category_id
  from public.goods where id = target_good_id for update;$anchor$,
    $patched$  select updated_at, category_id, published_at, type into good_updated_at, good_category_id, good_published_at, good_type
  from public.goods where id = target_good_id for update;$patched$),
  jsonb_build_array(
    $anchor$  update public.goods set category_id = target_category_id, updated_at = pg_catalog.now() where id = target_good_id;$anchor$,
    $patched$  -- SHEET-003: 공개 중에는 상품 유형이 바뀌는(연결 없음 포함) 카테고리로 옮길 수 없다. 초안 전환 후 바꾼다.
  if good_published_at is not null and good_category_id is distinct from target_category_id then
    next_type := private.goods_category_type(target_category_id);
    if next_type = '' then raise check_violation using message = 'goods_type_category_required'; end if;
    if next_type is distinct from good_type then raise check_violation using message = 'goods_type_category_locked'; end if;
  end if;
  update public.goods set category_id = target_category_id, updated_at = pg_catalog.now() where id = target_good_id;$patched$)))

-- 7-4. 판매 준비: 초안은 지금 카테고리 연결값으로 판정하고(없으면 type_missing, 저장된 유형과 다르면
--      type_category_mismatch로 공개를 막는다), 공개 중 상품은 저장된 유형을 유지한 채 다르면 검토 사유로만 알린다.
select private.goods_type_from_category_patch('private.admin_goods_readiness(public.goods)'::regprocedure, jsonb_build_array(
  jsonb_build_array(
    $anchor$kc_current boolean; kc_legacy boolean; notice_complete boolean; unknown_read boolean := false;$anchor$,
    $patched$kc_current boolean; kc_legacy boolean; notice_complete boolean; unknown_read boolean := false;
  category_type text; type_review boolean := false; type_no_category boolean := false;$patched$),
  jsonb_build_array(
    $anchor$  if nullif(btrim(p_good.type),'') is null then blockers:=array_append(blockers,'type_missing'); end if;$anchor$,
    $patched$  -- SHEET-003(ADR-0037): 상품 유형은 대표 카테고리(없으면 가까운 상위)의 연결값이다.
  category_type:=private.goods_category_type(p_good.category_id);
  if p_good.published_at is null then
    if category_type='' then blockers:=array_append(blockers,'type_missing');
    elsif category_type is distinct from p_good.type then blockers:=array_append(blockers,'type_category_mismatch'); end if;
  elsif category_type is distinct from p_good.type then
    -- 대표 카테고리가 아예 없는 공개 상품은 '연결 안내'가 아니라 '대표 카테고리 지정'이 할 일이다.
    type_review:=true; type_no_category:=p_good.category_id is null;
  end if;$patched$),
  jsonb_build_array(
    $anchor$  reasons:=blockers;
$anchor$,
    $patched$  reasons:=blockers;
  if type_review then reasons:=array_append(reasons,case when type_no_category then 'type_no_category' else 'type_category_mismatch' end); end if;
$patched$)))

-- --------------------------------------------------------------------------
-- 8. 초기값 결과 요약(배포 로그). 목록은 supabase/tests/goods_type_from_category.sql 맨 위 읽기 쿼리로 본다.
-- --------------------------------------------------------------------------
do $$
declare
  linked integer; tied integer; unlinked_with_goods integer; mismatched integer; uncategorized integer;
begin
  select count(*) into linked from public.catalog_categories where good_type is not null;
  select count(*) into tied from private.goods_category_type_majority() as majority where majority.tied_types is not null;
  select count(distinct good.category_id) into unlinked_with_goods from public.goods as good
    where good.category_id is not null and good.archived_at is null and private.goods_category_type(good.category_id) = '';
  select count(*) into mismatched from public.goods as good
    where good.archived_at is null and good.category_id is not null and private.goods_category_type(good.category_id) <> ''
      and good.type is distinct from private.goods_category_type(good.category_id);
  select count(*) into uncategorized from public.goods as good where good.archived_at is null and good.category_id is null;
  raise notice 'goods_type_from_category: linked categories %, tied %, unlinked categories with goods %, goods differing from link %, uncategorized goods %',
    linked, tied, unlinked_with_goods, mismatched, uncategorized;
end $$

-- 상품 편집이 여는 즉시할인 기간 상태(읽기). 결과의 fingerprint를 저장 요청의 expectedFingerprint로 되돌려 받는다.
create function public.admin_goods_instant_discount_period(p_good_id text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.has_operator_capability('catalog.read', false) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  if p_good_id is null or not exists(select 1 from public.goods where id = p_good_id) then return null; end if;
  return private.goods_instant_discount_schedule(p_good_id);
end;
$$

create function public.admin_save_good(target_good jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  previous public.goods;
  request jsonb;
  request_mode text;
  amount integer;
  starts timestamptz;
  ends timestamptz;
  schedule jsonb;
  saved jsonb;
  saved_id text;
  target_price bigint;
  target_compare bigint;
  own_ids uuid[] := array[]::uuid[];
  own_row private.goods_variant_price_periods;
  variant_row public.goods_variants;
  stopped boolean := false;
  inserted boolean := false;
  unchanged boolean;
  failure text;
begin
  perform private.require_operator_capability('catalog.manage', false);
  if pg_catalog.jsonb_typeof(target_good) is distinct from 'object' then
    raise invalid_parameter_value using message = 'invalid_good';
  end if;
  -- 위임 저장과 같은 잠금 순서(카테고리 트리 → 상품 행).
  perform private.lock_catalog_category_tree();
  select * into previous from public.goods
    where id = coalesce(nullif(target_good->>'previous_id', ''), target_good->>'id') for update;

  -- 한 상품에 할인은 하나다: 진행·예정 기간 할인이 있는 상품에 기간 없는 즉시할인(정가 표시)을 새로 걸거나 바꾸지 않는다.
  -- 이미 함께 있던 상품의 다른 입력 저장은 막지 않는다(정가 값이 그대로면 통과). 즉시할인 기간 지시가 있는 저장은 아래에서
  -- 상품 편집이 다루는 기간 할인을 먼저 멈추거나(none) 정가 표시를 거절한다(period).
  if not target_good ? 'instant_discount_period' and target_good ? 'compare_at_price' and coalesce(target_good->>'compare_at_price', '') ~ '^[0-9]{1,10}$' then
    target_compare := (target_good->>'compare_at_price')::bigint;
    target_price := case when coalesce(target_good->>'price', '') ~ '^[0-9]{1,10}$' then (target_good->>'price')::bigint
      else previous.price end;
    if previous.id is not null and target_compare > target_price
      and previous.compare_at_price::bigint is distinct from target_compare
      and exists(select 1 from private.goods_variant_price_periods p
        where p.good_id = previous.id and p.state = 'active' and p.ends_at > pg_catalog.statement_timestamp()) then
      raise check_violation using message = 'instant_discount_period_conflict';
    end if;
  end if;

  if not target_good ? 'instant_discount_period' then
    return private.admin_save_good_before_instant_discount_period(target_good);
  end if;

  request := target_good->'instant_discount_period';
  request_mode := request->>'mode';
  if pg_catalog.jsonb_typeof(request) is distinct from 'object' or request_mode is null or request_mode not in ('none', 'period')
    or pg_catalog.jsonb_typeof(request->'expectedFingerprint') is distinct from 'string'
    or pg_catalog.length(request->>'expectedFingerprint') not between 1 and 64
    or (request_mode = 'none' and (select pg_catalog.array_agg(key order by key) from pg_catalog.jsonb_object_keys(request) key)
      is distinct from array['expectedFingerprint', 'mode'])
    or (request_mode = 'period' and (select pg_catalog.array_agg(key order by key) from pg_catalog.jsonb_object_keys(request) key)
      is distinct from array['amount', 'endsAt', 'expectedFingerprint', 'mode', 'startsAt']) then
    raise check_violation using message = 'invalid_instant_discount_period';
  end if;
  if request_mode = 'period' then
    if pg_catalog.jsonb_typeof(request->'amount') is distinct from 'number' or request->>'amount' !~ '^[1-9][0-9]{0,9}$'
      or (request->>'amount')::numeric > 2147483647
      or pg_catalog.jsonb_typeof(request->'startsAt') is distinct from 'string' or request->>'startsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$'
      or pg_catalog.jsonb_typeof(request->'endsAt') is distinct from 'string' or request->>'endsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' then
      raise check_violation using message = 'invalid_instant_discount_period';
    end if;
    amount := (request->>'amount')::integer;
    begin
      starts := (request->>'startsAt')::timestamptz;
      ends := (request->>'endsAt')::timestamptz;
    exception when others then
      raise check_violation using message = 'invalid_instant_discount_period';
    end;
    if not pg_catalog.isfinite(starts) or not pg_catalog.isfinite(ends) or starts >= ends then
      raise check_violation using message = 'invalid_instant_discount_period';
    end if;
    if ends <= pg_catalog.statement_timestamp() then
      raise check_violation using message = 'instant_discount_period_ended';
    end if;
    -- 기간 즉시할인 상품의 판매가는 할인 전 가격이다(정가 표시를 함께 쓰지 않는다).
    if coalesce(target_good->>'compare_at_price', '') <> '' then
      raise check_violation using message = 'instant_discount_period_conflict';
    end if;
  end if;

  -- 화면이 본 할인 묶음과 지금 묶음이 같아야 한다(다른 곳에서 걸거나 멈춘 할인을 덮지 않는다).
  schedule := private.goods_instant_discount_schedule(previous.id);
  if schedule->>'fingerprint' is distinct from request->>'expectedFingerprint' then
    raise sqlstate 'PT409' using message = 'instant_discount_period_changed';
  end if;
  if schedule->>'state' = 'managed' then
    raise check_violation using message = 'instant_discount_period_managed';
  end if;
  if previous.id is not null then
    select coalesce(pg_catalog.array_agg(p.id order by p.id), '{}') into own_ids
    from private.goods_variant_price_periods p
    where p.good_id = previous.id and p.state = 'active' and p.ends_at > pg_catalog.statement_timestamp();
    perform 1 from private.goods_variant_price_periods where id = any(own_ids) order by id for update;
  end if;

  if request_mode = 'none' or pg_catalog.cardinality(own_ids) = 0 then
    if pg_catalog.cardinality(own_ids) > 0 then
      for own_row in select * from private.goods_variant_price_periods where id = any(own_ids) order by id loop
        perform public.admin_save_goods_price_period(own_row.good_id, own_row.variant_id, own_row.id, pg_catalog.jsonb_build_object(
          'state', 'disabled', 'discountPrice', own_row.discount_price, 'startsAt', own_row.starts_at, 'endsAt', own_row.ends_at), own_row.revision);
      end loop;
      stopped := true;
    end if;
    saved := private.admin_save_good_before_instant_discount_period(target_good - 'instant_discount_period');
  else
    -- 판매가·옵션 금액이 그대로면 지금 할인을 그대로 두거나 바꾼 것만 새로 쓴다. 금액이 바뀌면 기간 할인 가드
    -- (active_price_period_requires_reset)가 막으므로, 그때만 이 상품 편집이 다루는 할인을 먼저 멈추고 다시 저장한다.
    begin
      saved := private.admin_save_good_before_instant_discount_period(target_good - 'instant_discount_period');
    exception when check_violation then
      get stacked diagnostics failure = message_text;
      if failure is distinct from 'active_price_period_requires_reset' then raise; end if;
      saved := null;
    end;
    if saved is null then
      for own_row in select * from private.goods_variant_price_periods where id = any(own_ids) order by id loop
        perform public.admin_save_goods_price_period(own_row.good_id, own_row.variant_id, own_row.id, pg_catalog.jsonb_build_object(
          'state', 'disabled', 'discountPrice', own_row.discount_price, 'startsAt', own_row.starts_at, 'endsAt', own_row.ends_at), own_row.revision);
      end loop;
      stopped := true;
      saved := private.admin_save_good_before_instant_discount_period(target_good - 'instant_discount_period');
    end if;
  end if;
  saved_id := saved->>'id';
  if coalesce(saved_id, '') = '' then raise check_violation using message = 'invalid_good'; end if;

  if request_mode = 'period' then
    perform 1 from public.goods_variants where good_id = saved_id order by id for update;
    if exists(select 1 from public.goods_variants v where v.good_id = saved_id and v.archived_at is null and v.price::bigint - amount < 1) then
      raise check_violation using message = 'instant_discount_period_price_invalid';
    end if;
    if not exists(select 1 from public.goods_variants v where v.good_id = saved_id and v.archived_at is null) then
      raise check_violation using message = 'price_period_variant_inactive';
    end if;
    unchanged := not stopped and pg_catalog.cardinality(own_ids) > 0
      and pg_catalog.cardinality(own_ids) = (select count(*) from public.goods_variants v where v.good_id = saved_id and v.archived_at is null)
      and not exists(
        select 1 from public.goods_variants v
        where v.good_id = saved_id and v.archived_at is null and not exists(
          select 1 from private.goods_variant_price_periods p
          where p.id = any(own_ids) and p.variant_id = v.id and p.state = 'active' and p.regular_price = v.price
            and p.discount_price = v.price - amount and p.starts_at = starts and p.ends_at = ends));
    if not unchanged then
      if not stopped then
        for own_row in select * from private.goods_variant_price_periods where id = any(own_ids) order by id loop
          perform public.admin_save_goods_price_period(own_row.good_id, own_row.variant_id, own_row.id, pg_catalog.jsonb_build_object(
            'state', 'disabled', 'discountPrice', own_row.discount_price, 'startsAt', own_row.starts_at, 'endsAt', own_row.ends_at), own_row.revision);
        end loop;
        stopped := pg_catalog.cardinality(own_ids) > 0;
      end if;
      for variant_row in select * from public.goods_variants v where v.good_id = saved_id and v.archived_at is null order by v.id loop
        perform public.admin_save_goods_price_period(saved_id, variant_row.id, null, pg_catalog.jsonb_build_object(
          'state', 'active', 'discountPrice', variant_row.price - amount, 'startsAt', request->'startsAt', 'endsAt', request->'endsAt'), null);
      end loop;
      inserted := true;
    end if;
  end if;

  if stopped or inserted then
    insert into public.audit_log(actor_id, action, target, diff)
    values (auth.uid(), 'admin.good.instant_discount_period_saved', 'goods:' || saved_id, pg_catalog.jsonb_build_object(
      'mode', request_mode, 'amount', amount, 'startsAt', starts, 'endsAt', ends,
      'before', schedule, 'stopped', stopped, 'inserted', inserted));
  end if;
  return saved || pg_catalog.jsonb_build_object('instantDiscountPeriod', private.goods_instant_discount_schedule(saved_id));
end;
$function$

-- --------------------------------------------------------------------------
-- 3. 앵커 치환(현재 정의에서 앵커가 정확히 한 번 나올 때만 바꾼다)
-- --------------------------------------------------------------------------
create function private.goods_instant_discount_period_patch(p_function regprocedure, p_patches jsonb)
returns void
language plpgsql
volatile
set search_path = ''
as $helper$
declare
  v_definition text := pg_catalog.pg_get_functiondef(p_function);
  v_patch jsonb;
  v_found integer;
begin
  for v_patch in select value from pg_catalog.jsonb_array_elements(p_patches) loop
    v_found := (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_patch->>0, '')))
      / pg_catalog.length(v_patch->>0);
    if v_found <> 1 then
      raise exception 'goods_instant_discount_period_anchor_changed: % (% matches)', p_function, v_found;
    end if;
    v_definition := pg_catalog.replace(v_definition, v_patch->>0, v_patch->>1);
  end loop;
  execute v_definition;
end;
$helper$

-- 3-4. 일괄 변경 확정: 상품 1개 할인 중지(includeInstant)는 기간 할인을 멈춘 뒤 기간 없는 즉시할인을 판매가(할인 전)로 되돌린다.
--      옵션 추가금·재고는 그대로이고, 상품 목록 판매가 변경과 같은 상품 저장 RPC를 같은 페이로드 모양으로 부른다.
select private.goods_instant_discount_period_patch('public.admin_commit_goods_bulk(uuid,uuid,uuid)'::regprocedure, jsonb_build_array(
  jsonb_build_array(
    $anchor$        'discountPrice',p.discount_price,'startsAt',p.starts_at,'endsAt',p.ends_at),p.revision);
      end loop;
     end if;$anchor$,
    $replacement$        'discountPrice',p.discount_price,'startsAt',p.starts_at,'endsAt',p.ends_at),p.revision);
      end loop;
      if values_doc->>'includeInstant'='true' and g.compare_at_price is not null and g.compare_at_price>g.price then
       select jsonb_agg(jsonb_build_object('id',id,'name',name,'attributes',attributes,'code',code,'extraPrice',price-g.price,
        'stockQty',stock_qty,'expectedStockQty',stock_qty,'isActive',archived_at is null,'lowStockThreshold',low_stock_threshold)
        order by is_default desc,sort_order,id) into options from public.goods_variants where good_id=g.id;
       select coalesce(jsonb_agg(id::text order by id),'[]') into baseline from public.goods_variants where good_id=g.id and archived_at is null;
       perform public.admin_save_good(to_jsonb(g)||jsonb_build_object('previous_id',g.id,'publish',null,'custom_inputs_expected_revision',g.custom_inputs_revision,
        'price',g.compare_at_price,'compare_at_price',null,'variants',options,'variant_baseline',baseline));
      end if;
     end if;$replacement$)))

-- 3-8. 기간 할인 패널: 기간 없는 즉시할인(정가 표시)이 걸린 상품에는 기간 할인을 새로 활성화하지 못한다(한 상품 한 시점 할인 하나, 반대 방향).
-- 이 상품 편집(T20)은 정가 표시를 비운 뒤 기간 행을 쓰므로 영향이 없다.
select private.goods_instant_discount_period_patch('public.admin_save_goods_price_period(text,uuid,uuid,jsonb,integer)'::regprocedure, jsonb_build_array(
  jsonb_build_array(
    $anchor$  perform 1 from public.goods where id=p_good_id for update;$anchor$,
    $replacement$  perform 1 from public.goods where id=p_good_id for update;
  if next_state='active' and exists(select 1 from public.goods g where g.id=p_good_id and g.compare_at_price>g.price) then
    raise check_violation using message='instant_discount_period_conflict';
  end if;$replacement$)))

-- TKT-019·TKT-099 문의 자동 안내 저장 권한.
-- 원래 요청(스펙 #501 US19): "CS 담당으로서, 문의 카테고리별 자동 첫 안내 문구를 운영 설정에서 켜고 끄고 고치길 원한다".
-- 사용자 결정(2026-11-11 묶음 16) "아무나 가능하게" → 확인(2026-11-12 묶음 21) "이대로 (Recommended)":
-- 자동 첫 안내 설정 화면을 여는 모든 운영자가 켜고 끄고 문구를 저장한다. 화면을 여는 권한은 지금처럼 스토어 관리(store.manage —
-- 통합·주·부매니저·인플루언서·대행사, 매니저 권한 전환 전 호환 단계의 기존 운영자 전원)다.
-- 지금까지 이 섹션은 호환 단계에서 admin만 저장했다(legacy_admin_only=true). 그 조건만 이 섹션에서 뺀다.
-- 같은 RPC의 다른 섹션(사업자·CS 연락처·무통장 계좌 = seller.manage, 호환 단계 admin 전용)은 그대로다.
-- 저장 감사(admin.store_settings.updated, 변경 전후)와 버전 충돌 검사는 바꾸지 않는다.
--
-- 다른 트랙이 같은 함수를 고칠 수 있어 pg_get_functiondef + 앵커 치환으로 최소만 바꾼다(앵커가 정확히 3번 — 진입 잠금 검사,
-- 공개 능력 검사, 행 단위 능력 검사 — 나와야 한다). 같은 migration 끝에서 운영자 계약 지문을 다시 적는다(분류는 기존 행 그대로).
do $patch$
declare
  body text;
  anchor constant text := $a$case when target_section='inquiry_auto_replies' then 'store.manage' else 'seller.manage' end,true$a$;
  found_count integer;
begin
  body := pg_get_functiondef('public.admin_save_store_settings(text,jsonb,timestamp with time zone)'::regprocedure);
  found_count := (length(body) - length(replace(body, anchor, ''))) / length(anchor);
  if found_count <> 3 then
    raise exception 'inquiry_auto_reply_save_anchor_changed: % (expected 3)', found_count;
  end if;
  -- 호환 단계 admin 전용 여부를 섹션으로 정한다: 문의 자동 안내만 false, 나머지(사업자·계좌)는 지금처럼 true.
  execute replace(body, anchor,
    $a$case when target_section='inquiry_auto_replies' then 'store.manage' else 'seller.manage' end,target_section is distinct from 'inquiry_auto_replies'$a$);
end $patch$

-- 1014-103 상담 중 고객의 구매이력.
-- 원래 요청(10/14 회의): "얘가 뭘 샀는지 알아야 돼. 얘랑 상담을 해야 돼. 안 그러면 여기에서 다 뒤져야 돼."
-- 사용자 결정(2026-11-11 묶음 16) "전부 다 아무나 볼 수 있게" → 확인(2026-11-12 묶음 21) "이대로 (Recommended)":
-- 상담 화면을 여는 모든 운영자 역할(부매니저·대행사 포함 — 문의 응대 권한 cs.manage)이 상담 중 고객의 전체 구매이력
-- (금액·상태 포함)을 본다. 열람마다 감사 기록(상담·고객·운영자)을 남긴다.
--
-- 범위는 '그 문의의 고객'이다. 문의 번호로만 부르고 그 문의를 쓴 고객의 주문만 돌려준다. 고객 관리의
-- admin_operator_customer_history(주문 조회 sales.read)는 그대로 두어, 아무 고객 번호로 주문을 읽는 길은 넓히지 않는다.
-- 돌려주는 값은 주문 목록(주문번호·상태·결제 금액·대표 상품·품목 수·주문 시각)과 그 문의에 연결된 주문 요약뿐이다.
-- 배송지·연락처·결제수단·클레임은 싣지 않는다. 연결 주문은 그 고객의 주문일 때만 싣는다.
--
-- 감사: admin.inquiry.purchase_history_viewed(target inquiries:<문의>, diff에 고객·페이지·건수·보여 준 주문 ID 목록·연결 주문 ID).
-- 상담 화면은 새 메시지·재연결마다 화면을 다시 그리므로, 같은 운영자가 같은 문의의 같은 페이지에서 10분 안에 똑같은 목록
-- (보여 준 주문 ID 목록과 연결 주문이 모두 같음)을 다시 읽을 때만 기록을 겹쳐 남기지 않는다. 첫 열람, 다른 페이지, 그사이 새 주문이나
-- 바뀐 연결 주문으로 보여 준 내용이 달라진 열람은 늘 남는다.
-- 감사 기록을 쓰므로 VOLATILE이다(PostgREST가 STABLE 함수를 읽기 전용 트랜잭션으로 부르기 때문).
create function public.admin_inquiry_purchase_history(target_inquiry_id uuid, target_page integer default 1)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare
  actor uuid;
  thread public.inquiries;
  total bigint;
  page integer;
  page_size constant integer := 20;
  items jsonb;
  shown uuid[];
  linked jsonb := null;
begin
  actor := private.require_operator_capability('cs.manage');
  if target_inquiry_id is null then
    raise invalid_parameter_value using message = 'inquiry_purchase_history_invalid';
  end if;
  select * into thread from public.inquiries where id = target_inquiry_id;
  if not found then
    raise no_data_found using message = 'inquiry_not_found';
  end if;

  select count(*) into total from public.orders where user_id = thread.user_id;
  page := least(greatest(coalesce(target_page, 1), 1), greatest(1, (total + page_size - 1) / page_size)::integer);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id, 'orderNumber', r.order_number, 'status', r.status, 'amount', r.total, 'createdAt', r.created_at,
      'title', coalesce((select i.good_name_snapshot from public.order_items i where i.order_id = r.id order by i.id limit 1), '주문 상품'),
      'itemCount', (select count(*) from public.order_items i where i.order_id = r.id)
    ) order by r.created_at desc, r.id desc), '[]'::jsonb),
    coalesce(array_agg(r.id order by r.created_at desc, r.id desc), '{}'::uuid[])
  into items, shown
  from (
    select o.id, o.order_number, o.status, o.total, o.created_at
    from public.orders o
    where o.user_id = thread.user_id
    order by o.created_at desc, o.id desc
    limit page_size offset (page - 1) * page_size
  ) r;

  if thread.order_id is not null then
    select jsonb_build_object(
      'id', o.id, 'orderNumber', o.order_number, 'status', o.status, 'amount', o.total, 'createdAt', o.created_at,
      'title', coalesce((select i.good_name_snapshot from public.order_items i where i.order_id = o.id order by i.id limit 1), '주문 상품'),
      'quantity', (select coalesce(sum(i.qty), 0) from public.order_items i where i.order_id = o.id))
    into linked
    from public.orders o
    where o.id = thread.order_id and o.user_id = thread.user_id;
  end if;

  if not exists (
    select 1 from public.audit_log a
    where a.target = 'inquiries:' || thread.id::text
      and a.action = 'admin.inquiry.purchase_history_viewed'
      and a.actor_id = actor
      and a.created_at > clock_timestamp() - interval '10 minutes'
      and a.diff->>'page' = page::text
      and a.diff->'orderIds' = to_jsonb(shown)
      and a.diff->>'linkedOrderId' is not distinct from (linked->>'id')
  ) then
    insert into public.audit_log(actor_id, action, target, diff)
    values (actor, 'admin.inquiry.purchase_history_viewed', 'inquiries:' || thread.id::text,
      jsonb_build_object('customerId', thread.user_id, 'page', page, 'total', total, 'orderIds', to_jsonb(shown),
        'linkedOrderId', linked->'id'));
  end if;

  return jsonb_build_object('inquiryId', thread.id, 'customerId', thread.user_id, 'linkedOrder', linked,
    'items', items, 'page', page, 'pageSize', page_size, 'total', total);
end $$

-- 문의 하나의 처리 이력. 문의를 여는 운영자(cs.manage) 누구나 읽는다. 읽기만 하므로 STABLE이고 열람 감사는 남기지 않는다
-- (그 문의의 메시지·내부 메모·담당자와 같은 범위다). 이름은 다른 문의 화면과 같은 표시명 규칙(닉네임, 없으면 '운영자_' + ID 앞 6자리)을 쓴다.
create function public.admin_inquiry_processing_history(target_inquiry_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare
  thread public.inquiries;
  events jsonb;
  total integer;
  event_limit constant integer := 100;
begin
  if not public.has_operator_capability('cs.manage') then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  if target_inquiry_id is null then
    raise invalid_parameter_value using message = 'inquiry_history_invalid';
  end if;
  select * into thread from public.inquiries where id = target_inquiry_id;
  if not found then
    raise no_data_found using message = 'inquiry_not_found';
  end if;

  select count(*) into total from public.audit_log a
  where a.target = 'inquiries:' || thread.id::text
    and a.action in ('admin.inquiry.assigned', 'admin.inquiry.reassigned', 'admin.inquiry.answered', 'admin.inquiry.closed');

  with picked as (
    select a.id, a.created_at, a.action, a.actor_id, a.diff,
      case a.action when 'admin.inquiry.assigned' then 0 when 'admin.inquiry.answered' then 1
        when 'admin.inquiry.reassigned' then 2 else 3 end as step,
      case when a.diff->>'before' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (a.diff->>'before')::uuid end as before_id,
      case when a.diff->>'after' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (a.diff->>'after')::uuid end as after_id
    from public.audit_log a
    where a.target = 'inquiries:' || thread.id::text
      and a.action in ('admin.inquiry.assigned', 'admin.inquiry.reassigned', 'admin.inquiry.answered', 'admin.inquiry.closed')
    order by a.created_at desc,
      case a.action when 'admin.inquiry.assigned' then 0 when 'admin.inquiry.answered' then 1
        when 'admin.inquiry.reassigned' then 2 else 3 end desc,
      a.id desc
    limit event_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id::text,
      'at', p.created_at,
      'kind', case p.action when 'admin.inquiry.assigned' then 'assigned' when 'admin.inquiry.reassigned' then 'reassigned'
        when 'admin.inquiry.answered' then 'answered' else 'closed' end,
      'actorName', case when p.actor_id is null then null
        else coalesce(nullif(btrim(actor.nickname), ''), '운영자_' || left(p.actor_id::text, 6)) end,
      'fromName', case when p.action = 'admin.inquiry.reassigned' and p.before_id is not null
        then coalesce(nullif(btrim(before_profile.nickname), ''), '운영자_' || left(p.before_id::text, 6)) end,
      'toName', case when p.action in ('admin.inquiry.reassigned', 'admin.inquiry.assigned') and p.after_id is not null
        then coalesce(nullif(btrim(after_profile.nickname), ''), '운영자_' || left(p.after_id::text, 6)) end,
      'reason', case when p.action = 'admin.inquiry.reassigned' then nullif(btrim(p.diff->>'reason'), '') end
    ) order by p.created_at, p.step, p.id), '[]'::jsonb)
  into events
  from picked p
  left join public.profiles actor on actor.id = p.actor_id
  left join public.profiles before_profile on before_profile.id = p.before_id
  left join public.profiles after_profile on after_profile.id = p.after_id;

  -- 자동 종결(close_stale_answered_inquiries)은 실행자가 없어 감사 기록이 없다. 운영자 완료 기록이 없는 종결 문의만 종결 시각으로 보인다.
  if thread.status = 'closed' and thread.closed_at is not null and not exists (
    select 1 from public.audit_log a where a.target = 'inquiries:' || thread.id::text and a.action = 'admin.inquiry.closed'
  ) then
    events := events || jsonb_build_array(jsonb_build_object('id', 'auto-close:' || thread.id::text, 'at', thread.closed_at,
      'kind', 'auto_closed', 'actorName', null, 'fromName', null, 'toName', null, 'reason', null));
    total := total + 1;
  end if;

  return jsonb_build_object('inquiryId', thread.id, 'events', events, 'total', total, 'limit', event_limit);
end $$

create function public.admin_save_faq_entry_with_widget_topic(
  target_id uuid,
  target_category text,
  target_question text,
  target_answer text,
  target_sort_order integer,
  target_published boolean,
  expected_updated_at timestamptz,
  target_widget_topic text
)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  actor uuid := (select auth.uid());
  saved_id uuid;
  previous_topic text;
  displaced_id uuid;
begin
  perform private.require_operator_capability('cs.manage', false);

  if actor is null or not public.has_operator_capability('cs.manage', false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if target_widget_topic is not null and target_widget_topic not in ('delivery', 'cancel', 'return') then
    raise invalid_parameter_value using message = 'invalid_faq_widget_topic';
  end if;

  -- 버튼을 지정하는 저장끼리는 줄을 세운다(잠금 전에는 어떤 FAQ 행도 잡지 않는다).
  if target_widget_topic is not null then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('public.faq_entries.widget_topic', 0));
  end if;

  saved_id := public.admin_save_faq_entry(
    target_id, target_category, target_question, target_answer,
    target_sort_order, target_published, expected_updated_at
  );

  select entry.widget_topic into previous_topic
  from public.faq_entries as entry
  where entry.id = saved_id
  for update;

  if previous_topic is not distinct from target_widget_topic then
    return saved_id;
  end if;

  if target_widget_topic is not null then
    update public.faq_entries as entry
    set widget_topic = null,
      updated_at = greatest(clock_timestamp(), entry.updated_at + interval '1 microsecond')
    where entry.widget_topic = target_widget_topic
      and entry.id <> saved_id
    returning entry.id into displaced_id;

    if displaced_id is not null then
      insert into public.audit_log(actor_id, action, target, diff)
      values (actor, 'faq.widget_topic', 'faq:' || displaced_id::text,
        jsonb_build_object('before', target_widget_topic, 'after', null, 'replacedBy', saved_id));
    end if;
  end if;

  update public.faq_entries
  set widget_topic = target_widget_topic
  where id = saved_id;

  insert into public.audit_log(actor_id, action, target, diff)
  values (actor, 'faq.widget_topic', 'faq:' || saved_id::text,
    jsonb_build_object('before', previous_topic, 'after', target_widget_topic, 'replaced', displaced_id));

  return saved_id;
end;
$$

-- 재정의한 함수에 등록된 운영자 계약이 있으면 새 본문·ACL로 다시 적는다(분류는 기존 행 그대로).
do $$declare fn regprocedure:='private.stock_reconcile_flows(uuid[],timestamptz)'::regprocedure;contract record;begin
 select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure=fn;
 if found then perform private.register_operator_rpc_contract(fn,contract.capability,contract.guard_kind,contract.legacy_admin_only);
 elsif exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure=fn) then
  perform private.register_operator_internal_contract(fn);
 end if;
end $$

do $do$
declare
