end $$

create function private.sync_collection_bundle_receipt() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.collected_at is not null and old.collected_at is null then
  perform private.sync_single_collection_bundle_receipt(new.claim_id,new.shipment_id);
 end if;
 return new;
end $$

do $migration$
declare definition text:=pg_get_functiondef('private.stock_reconcile_flows(uuid[],timestamptz)'::regprocedure);
 anchor text:=$a$from public.order_claim_collections x
    join public.order_cancellation_requests c on c.id=x.claim_id$a$;
 replacement text:=$a$from public.order_claim_collection_bundles x
    join public.order_cancellation_requests c on c.id=x.claim_id$a$;
 occurrences integer;
begin
 occurrences:=(length(definition)-length(replace(definition,anchor,'')))/length(anchor);
 if occurrences=0 and position('public.order_claim_collection_bundles x' in definition)>0 then
  raise notice 'stock_reconcile_flows already counts collection bundles';
  return;
 end if;
 if occurrences=0 then
  raise exception 'stock_reconcile_flows has no per-shipment collection CTE (20261113120000 not applied or its anchor changed)';
 end if;
 if occurrences<>1 then raise exception 'stock_reconcile_flows anchor must appear once';end if;
 execute replace(definition,anchor,replacement);
 perform private.register_operator_internal_contract('private.stock_reconcile_flows(uuid[],timestamptz)'::regprocedure)
 where exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure='private.stock_reconcile_flows(uuid[],timestamptz)'::regprocedure);
end $migration$

-- 불량으로 고른 품목은 '돌아온 수량'으로 세지 않는다. 판매 재고로 돌아오지 않는 실물이라
-- 세면 대조 목표 수량(target_qty)에 그 수량이 더해져 반영이 불량품을 판매 재고로 되돌린다. 앵커 치환으로 최소 변경한다.
do $patch$
declare definition text; anchor_end text; anchor text; patch text;
begin
  definition := pg_get_functiondef('private.stock_reconcile_flows(uuid[],timestamptz)'::regprocedure);
  -- collected의 두 union 가지(출고지별 회수·레거시 회수)에 클레임 id를 더해, 선택을 '그 클레임의 회수분'에만 건다.
  -- 같은 품목이 교환(V1 회수)된 뒤 반품(불량)돼도 교환 때 돌아온 수량은 그대로 센다.
  anchor_end := E'end as restored\n';
  if (length(definition) - length(replace(definition, anchor_end, ''))) / length(anchor_end) <> 2 then
    raise exception 'stock_reconcile_flows restored anchor must match twice';
  end if;
  definition := replace(definition, anchor_end, E'end as restored,c.id as claim_id\n');
  anchor := E'    from collected c join members m on m.member_id=c.returned_variant_id\n';
  patch := E'    from collected c join members m on m.member_id=c.returned_variant_id\n'
    || E'    where not exists(select 1 from private.claim_defective_stock d join public.order_cancellation_requests dc on dc.id=d.claim_id\n'
    || E'      where d.order_item_id=c.item_id and d.claim_id=c.claim_id and dc.claim_type=\'return\' and dc.stage not in (\'rejected\',\'withdrawn\'))\n';
  if (length(definition) - length(replace(definition, anchor, ''))) / length(anchor) <> 1 then
    raise exception 'stock_reconcile_flows anchor must match once';
  end if;
  execute replace(definition, anchor, patch);
end $patch$

-- 스위치·출고지 계약 변경은 누가(migration·SQL 편집기 포함) 언제 바꿨는지 감사 기록에 남기고 리비전을 올린다. 행은 지우지 못한다.
create function private.audit_return_pickup_settings() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then raise check_violation using message = 'return_pickup_settings_required'; end if;
  if tg_when = 'BEFORE' then
    if tg_table_name = 'return_pickup_settings' then
      new.revision := old.revision + 1;
      -- 꺼졌다 다시 켜면 켠 시각을 새로 적는다 — 꺼져 있던 동안 승인돼 고객이 이미 착불로 보냈을 수 있는 묶음을 접수하지 않는다.
      if new.pickup_enabled and not old.pickup_enabled then new.pickup_enabled_at := clock_timestamp(); end if;
    elsif new.enabled and not old.enabled then new.enabled_at := clock_timestamp();
    end if;
    new.updated_at := clock_timestamp();
    return new;
  end if;
  insert into public.audit_log(actor_id, action, target, diff)
  values (null, 'system.return_pickup.settings_changed', tg_table_name,
    jsonb_build_object('operation', lower(tg_op), 'before', case when tg_op = 'INSERT' then null else to_jsonb(old) - 'singleton' end,
      'after', to_jsonb(new) - 'singleton', 'sessionUser', session_user::text));
  return new;
end $$

-- 회수지(고객 쪽) 주소. 클레임 연락처 정정과 같은 순서로 고른다: 회수 주소 정정(암호문, 앱이 연다) → 판매자 접수 회수 주소 → 주문 배송지.
-- 보존 기한이 지났거나 읽을 수 없으면 null(접수하지 않고 실패로 남긴다).
create function private.claim_return_pickup_sender(p_order uuid, p_claim uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare view jsonb;
begin
  view := private.contact_target(p_order, p_claim, 'collection', true, private.contact_retention(p_claim, clock_timestamp()));
  if view->>'piiState' is distinct from 'available' then return null; end if;
  if view#>>'{source,sourceKind}' = 'contact_plan' then
    return jsonb_build_object('source', 'sealed', 'orderId', p_order, 'claimId', p_claim, 'plan', view->'plan');
  end if;
  return jsonb_build_object('source', 'plain', 'address', view->'sourceAddress');
end $$

-- 5. 서비스 경로(service_role 전용 — 회수 접수 크론만 부른다)
-- 이번 회차의 할 일. 꺼져 있으면 아무것도 만들지 않는다. 순서: 새 묶음을 큐에 넣는다 → 필요 없어진 접수를 닫거나 취소로 돌린다
-- → 기한이 된 접수·취소를 임대(lease 10분)해 돌려준다. 다른 회차·운영자 재시도와는 행 잠금(skip locked)으로 겹치지 않는다.
create function public.service_return_pickup_work(p_limit integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare settings private.return_pickup_settings; now_at timestamptz := clock_timestamp(); pickup private.claim_return_pickups;
  bundle public.order_claim_collection_bundles; reason text; token uuid; items jsonb := '[]'::jsonb; queued integer := 0; closed integer := 0;
begin
  if p_limit is null or p_limit not between 1 and 100 then raise invalid_parameter_value using message = 'invalid_return_pickup_limit'; end if;
  select * into settings from private.return_pickup_settings where singleton;
  if not found or not settings.pickup_enabled then return jsonb_build_object('enabled', false); end if;

  insert into private.claim_return_pickups(bundle_id, claim_id, shipment_id, order_id, origin_id, provider, carrier, idempotency_key, next_attempt_at)
  select b.id, b.claim_id, b.shipment_id, c.order_id, x.origin_id, settings.provider, origin.carrier,
    'icons-return-' || replace(b.id::text, '-', ''), now_at
  from public.order_claim_collection_bundles b
  join public.order_cancellation_requests c on c.id = b.claim_id
  join public.order_claim_collections x on x.claim_id = b.claim_id and x.shipment_id = b.shipment_id
  join private.return_pickup_origins origin on origin.origin_id = x.origin_id and origin.enabled
  where c.stage = 'collecting' and b.collected_at is null and b.created_at >= greatest(settings.pickup_enabled_at, origin.enabled_at)
    and not exists(select 1 from private.claim_return_pickups p where p.bundle_id = b.id)
    and private.claim_return_pickup_eligible(b)
  order by b.created_at, b.id
  limit 500
  on conflict (bundle_id) do nothing;
  get diagnostics queued = row_count;

  for pickup in select p.* from private.claim_return_pickups p
    where p.state in ('pending','failed','requested') and (p.lease_until is null or p.lease_until < now_at)
    order by p.id for update skip locked loop
    select * into bundle from public.order_claim_collection_bundles where id = pickup.bundle_id;
    reason := private.claim_return_pickup_block(bundle);
    -- 아직 한 번도 보내지 않은 접수는, 그 사이 운영자·판매자가 회수 방법을 따로 기록했으면 보내지 않고 닫는다(이중 수거 방지).
    if reason is null and pickup.attempts = 0 and pickup.state = 'pending'
      and (exists(select 1 from private.claim_collection_plans plan where plan.claim_id = pickup.claim_id and plan.shipment_id = pickup.shipment_id and plan.requested_once)
        or exists(select 1 from private.seller_order_claim_intakes intake cross join lateral jsonb_array_elements(intake.payload->'collections') item
          where intake.claim_id = pickup.claim_id and item->>'shipmentId' = pickup.shipment_id::text and coalesce(item->>'method', 'not_requested') <> 'not_requested')) then
      reason := 'manual';
    end if;
    continue when reason is null;
    if reason = 'collected' and pickup.state = 'requested' then
      update private.claim_return_pickups set state = 'collected', next_attempt_at = null, lease_token = null, lease_until = null, updated_at = now_at
      where id = pickup.id;
    elsif pickup.state <> 'requested' and pickup.attempts = 0 then
      update private.claim_return_pickups set state = 'canceled', cancel_reason = reason, canceled_at = now_at, next_attempt_at = null,
        lease_token = null, lease_until = null, updated_at = now_at where id = pickup.id;
      insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome) values (pickup.id, 'local_cancel', 'canceled');
    else
      update private.claim_return_pickups set state = 'cancel_pending', cancel_reason = reason, next_attempt_at = now_at, cancel_retry_base = cancel_attempts,
        lease_token = null, lease_until = null, updated_at = now_at where id = pickup.id;
    end if;
    closed := closed + 1;
  end loop;

  for pickup in select p.* from private.claim_return_pickups p
    where p.state in ('pending','failed','cancel_pending','cancel_failed') and p.next_attempt_at is not null and p.next_attempt_at <= now_at
      and (p.lease_until is null or p.lease_until < now_at)
      -- 접수는 수거중 단계에서만 보낸다(보류·처리중 등은 단계가 돌아올 때까지 기다린다). 취소는 단계와 관계없이 보낸다.
      and (p.state in ('cancel_pending','cancel_failed')
        or exists(select 1 from public.order_cancellation_requests c where c.id = p.claim_id and c.stage = 'collecting'))
    order by p.next_attempt_at, p.id limit p_limit for update skip locked loop
    token := gen_random_uuid();
    if pickup.state in ('pending','failed') then
      update private.claim_return_pickups set lease_token = token, lease_until = now_at + interval '10 minutes', attempts = attempts + 1, updated_at = now_at
      where id = pickup.id;
      items := items || jsonb_build_array(private.claim_return_pickup_request_item(pickup.id, token));
    else
      update private.claim_return_pickups set lease_token = token, lease_until = now_at + interval '10 minutes', cancel_attempts = cancel_attempts + 1, updated_at = now_at
      where id = pickup.id;
      items := items || jsonb_build_array(jsonb_build_object('kind', 'cancel', 'pickupId', pickup.id, 'leaseToken', token, 'provider', pickup.provider,
        'idempotencyKey', pickup.idempotency_key, 'carrier', pickup.carrier, 'trackingNumber', pickup.tracking_number, 'externalId', pickup.external_id));
    end if;
  end loop;
  return jsonb_build_object('enabled', true, 'provider', settings.provider, 'queued', queued, 'closed', closed, 'items', items);
end $$

-- 접수·취소 결과를 남긴다. results: [{pickupId, leaseToken, kind: request|cancel, outcome, trackingNumber?, externalId?, errorCode?}].
-- 임대가 바뀐(다른 회차가 다시 잡은) 결과는 stale로 센다. 접수되면 회수 송장을 저장하고 클레임 회수 이력(claim_collection_events)·
-- 감사 기록에 남기고 고객에게 알린다. 감사·이력에는 개인정보(회수지 이름·연락처·주소)를 싣지 않는다.
create function public.service_record_return_pickup_results(p_results jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare settings private.return_pickup_settings; result jsonb; pickup private.claim_return_pickups; tracking text; external text; code text;
  bundle public.order_claim_collection_bundles; label text; recorded integer := 0; requested integer := 0; failed integer := 0; canceled integer := 0;
  cancel_failed integer := 0; stale integer := 0; invalid integer := 0; deferred integer := 0; late text; system_actor constant uuid := '00000000-0000-0000-0000-000000000000';
begin
  if jsonb_typeof(p_results) is distinct from 'array' or jsonb_array_length(p_results) > 100 then
    raise invalid_parameter_value using message = 'invalid_return_pickup_results'; end if;
  select * into settings from private.return_pickup_settings where singleton;
  for result in select value from jsonb_array_elements(p_results) loop
    if jsonb_typeof(result) is distinct from 'object' or coalesce(result->>'pickupId', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or coalesce(result->>'leaseToken', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or coalesce(result->>'kind', '') not in ('request','cancel') then invalid := invalid + 1; continue; end if;
    select * into pickup from private.claim_return_pickups where id = (result->>'pickupId')::uuid for update;
    if not found or pickup.lease_token is distinct from (result->>'leaseToken')::uuid
      or (result->>'kind' = 'request') <> (pickup.state in ('pending','failed')) then stale := stale + 1; continue; end if;
    -- 회차 시간 예산이 끝나 보내지 못한 일: 한 번도 보내지 않았으니 임대를 풀고 이번 회차가 센 시도를 되돌린다(다음 회차가 다시 잡는다).
    if result->>'outcome' = 'deferred' then
      update private.claim_return_pickups set lease_token = null, lease_until = null, updated_at = clock_timestamp(),
        attempts = case when result->>'kind' = 'request' then greatest(attempts - 1, retry_base) else attempts end,
        cancel_attempts = case when result->>'kind' = 'cancel' then greatest(cancel_attempts - 1, cancel_retry_base) else cancel_attempts end
      where id = pickup.id;
      deferred := deferred + 1;
      continue;
    end if;
    code := nullif(result->>'errorCode', '');
    if code is not null and code !~ '^[a-z0-9_]{1,64}$' then code := 'upstream_error'; end if;
    if result->>'kind' = 'request' then
      tracking := upper(regexp_replace(coalesce(result->>'trackingNumber', ''), '[^A-Za-z0-9]', '', 'g'));
      external := nullif(result->>'externalId', '');
      if result->>'outcome' = 'requested' and tracking ~ '^[A-Z0-9]{8,30}$' and (external is null or external ~ '^[\x21-\x7e]{1,100}$') then
        update private.claim_return_pickups set state = 'requested', tracking_number = tracking, external_id = external, requested_at = clock_timestamp(),
          last_error_code = null, next_attempt_at = null, lease_token = null, lease_until = null, updated_at = clock_timestamp()
        where id = pickup.id;
        insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome) values (pickup.id, 'request', 'requested');
        select * into bundle from public.order_claim_collection_bundles where id = pickup.bundle_id;
        -- 요청이 나가는 사이 철회·거절됐거나 회수가 필요 없어졌으면 접수됐다고 알리지 않고 바로 취소로 돌린다('collected'는 정상 종료라 다음 회차가 닫는다).
        late := private.claim_return_pickup_block(bundle);
        if late is not null and late <> 'collected' then
          update private.claim_return_pickups set state = 'cancel_pending', cancel_reason = late, next_attempt_at = clock_timestamp(),
            cancel_retry_base = cancel_attempts, updated_at = clock_timestamp() where id = pickup.id;
        end if;
        label := coalesce(nullif(bundle.return_name_snapshot, ''), '출고지 반품 주소');
        insert into private.claim_collection_events(id, claim_id, shipment_id, actor_id, session_id, request, result)
        values (gen_random_uuid(), pickup.claim_id, pickup.shipment_id, system_actor, system_actor,
          jsonb_build_object('claimId', pickup.claim_id, 'shipmentId', pickup.shipment_id, 'bundleId', pickup.bundle_id, 'source', 'return_pickup',
            'values', jsonb_build_object('method', 'seller_arranged', 'carrier', pickup.carrier, 'trackingNumber', tracking,
              'evidence', case when late is not null and late <> 'collected' then '자동 회수 접수 후 즉시 취소 · ' else '자동 회수 접수 · ' end || label)),
          jsonb_build_object('pickupId', pickup.id, 'state', 'requested'));
        insert into public.audit_log(actor_id, action, target, diff) values (null, 'system.order.claim_return_pickup_requested', 'order:' || pickup.order_id,
          jsonb_build_object('claimId', pickup.claim_id, 'shipmentId', pickup.shipment_id, 'bundleId', pickup.bundle_id, 'pickupId', pickup.id,
            'provider', pickup.provider, 'carrier', pickup.carrier, 'trackingNumber', tracking, 'attempts', pickup.attempts,
            'canceledAtOnce', case when late is not null and late <> 'collected' then late else null end));
        if late is null then
          perform private.notify_order_claim(pickup.claim_id, 'return_pickup_requested', '방문 회수가 접수됐어요',
            '택배 기사가 방문해 굿즈를 회수합니다. 주문 상세의 회수 정보에서 회수 송장을 확인해주세요.');
        end if;
        requested := requested + 1;
      else
        update private.claim_return_pickups set state = 'failed',
          last_error_code = case when result->>'outcome' = 'requested' then 'invalid_tracking' else coalesce(code, 'upstream_error') end,
          next_attempt_at = private.claim_return_pickup_next_attempt(pickup.attempts - pickup.retry_base, settings),
          lease_token = null, lease_until = null, updated_at = clock_timestamp()
        where id = pickup.id;
        insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome, error_code)
        values (pickup.id, 'request', 'error', case when result->>'outcome' = 'requested' then 'invalid_tracking' else coalesce(code, 'upstream_error') end);
        failed := failed + 1;
      end if;
    else
      if result->>'outcome' in ('canceled','not_found') then
        update private.claim_return_pickups set state = 'canceled', canceled_at = clock_timestamp(), last_error_code = null, next_attempt_at = null,
          lease_token = null, lease_until = null, updated_at = clock_timestamp() where id = pickup.id;
        insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome) values (pickup.id, 'cancel', result->>'outcome');
        if pickup.tracking_number is not null then
          insert into private.claim_collection_events(id, claim_id, shipment_id, actor_id, session_id, request, result)
          values (gen_random_uuid(), pickup.claim_id, pickup.shipment_id, system_actor, system_actor,
            jsonb_build_object('claimId', pickup.claim_id, 'shipmentId', pickup.shipment_id, 'bundleId', pickup.bundle_id, 'source', 'return_pickup',
              'values', jsonb_build_object('method', 'seller_arranged', 'carrier', pickup.carrier, 'trackingNumber', pickup.tracking_number,
                'evidence', '자동 회수 취소 · ' || case pickup.cancel_reason when 'withdrawn' then '요청 철회' when 'rejected' then '요청 거절'
                  when 'completed' then '요청 종결' when 'waived' then '회수 생략' when 'customer_sent' then '고객 직접 발송' when 'manual' then '수거 방법 별도 기록' else '회수 불필요' end)),
            jsonb_build_object('pickupId', pickup.id, 'state', 'canceled'));
        end if;
        insert into public.audit_log(actor_id, action, target, diff) values (null, 'system.order.claim_return_pickup_canceled', 'order:' || pickup.order_id,
          jsonb_build_object('claimId', pickup.claim_id, 'bundleId', pickup.bundle_id, 'pickupId', pickup.id, 'provider', pickup.provider,
            'carrier', pickup.carrier, 'trackingNumber', pickup.tracking_number, 'reason', pickup.cancel_reason, 'outcome', result->>'outcome'));
        canceled := canceled + 1;
      else
        update private.claim_return_pickups set state = 'cancel_failed', last_error_code = coalesce(code, 'upstream_error'),
          next_attempt_at = private.claim_return_pickup_next_attempt(pickup.cancel_attempts - pickup.cancel_retry_base, settings),
          lease_token = null, lease_until = null, updated_at = clock_timestamp() where id = pickup.id;
        insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome, error_code) values (pickup.id, 'cancel', 'error', coalesce(code, 'upstream_error'));
        cancel_failed := cancel_failed + 1;
      end if;
    end if;
    recorded := recorded + 1;
  end loop;
  return jsonb_build_object('recorded', recorded, 'requested', requested, 'failed', failed, 'canceled', canceled, 'cancelFailed', cancel_failed,
    'stale', stale, 'invalid', invalid, 'deferred', deferred);
end $$

-- 자동 수거 실패(접수 실패·취소 실패)를 지금 다시 시도하도록 큐에 돌린다. 크론이 다음 회차에 같은 멱등 키로 다시 보낸다.
create function public.admin_retry_claim_return_pickup(p_claim_id uuid, p_bundle_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid := (select auth.uid()); settings private.return_pickup_settings; pickup private.claim_return_pickups; next_state text;
begin
  perform private.require_operator_capability('sales.manage', false);
  if actor is null or not public.has_operator_capability('sales.manage', false) then raise insufficient_privilege using message = 'staff required'; end if;
  select * into settings from private.return_pickup_settings where singleton;
  if not found or not settings.pickup_enabled then raise check_violation using message = 'return_pickup_disabled'; end if;
  select * into pickup from private.claim_return_pickups where bundle_id = p_bundle_id and claim_id = p_claim_id for update;
  if not found then raise no_data_found using message = 'return_pickup_not_found'; end if;
  if pickup.lease_until is not null and pickup.lease_until > clock_timestamp() then raise sqlstate 'PT409' using message = 'return_pickup_in_progress'; end if;
  if pickup.state not in ('failed','cancel_failed') then
    return jsonb_build_object('pickupId', pickup.id, 'state', pickup.state, 'nextAttemptAt', pickup.next_attempt_at, 'replayed', true);
  end if;
  next_state := case pickup.state when 'failed' then 'pending' else 'cancel_pending' end;
  update private.claim_return_pickups set state = next_state, next_attempt_at = clock_timestamp(),
    retry_base = case when pickup.state = 'failed' then attempts else retry_base end,
    cancel_retry_base = case when pickup.state = 'cancel_failed' then cancel_attempts else cancel_retry_base end,
    lease_token = null, lease_until = null, updated_at = clock_timestamp()
  where id = pickup.id;
  insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome, actor_id) values (pickup.id, 'retry', 'scheduled', actor);
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.order.claim_return_pickup_retried', 'order:' || pickup.order_id,
    jsonb_build_object('claimId', pickup.claim_id, 'bundleId', pickup.bundle_id, 'pickupId', pickup.id, 'previousState', pickup.state,
      'lastErrorCode', pickup.last_error_code, 'attempts', pickup.attempts, 'cancelAttempts', pickup.cancel_attempts));
  return jsonb_build_object('pickupId', pickup.id, 'state', next_state, 'nextAttemptAt', clock_timestamp(), 'replayed', false);
end $$

-- 8. 회수 묶음 읽기(운영 상세·일괄 사실·고객 회수 주소)에 회수 접수를 더한다. 행이 있는 묶음에만 'pickup' 키가 생긴다.
-- 앵커 치환(재정의 최소화). 각 앵커는 정확히 한 번 나와야 한다.
create or replace function pg_temp.return_pickup_patch(p_function regprocedure, p_anchor text, p_replacement text) returns void language plpgsql as $$
declare definition text := pg_get_functiondef(p_function);
begin
  if (length(definition) - length(replace(definition, p_anchor, ''))) / length(p_anchor) <> 1 then
    raise exception '% anchor must appear once', p_function; end if;
  execute replace(definition, p_anchor, p_replacement);
end $$

-- 재정의한 함수의 등록된 계약을 새 본문·ACL로 다시 적는다(분류는 기존 행 그대로).
do $$declare fn regprocedure; contract record; begin
  foreach fn in array array['private.claim_collection_bundles_json(uuid,uuid,boolean)'::regprocedure] loop
    select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure = fn;
    if found then perform private.register_operator_rpc_contract(fn, contract.capability, contract.guard_kind, contract.legacy_admin_only);
    elsif exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure = fn) then
      perform private.register_operator_internal_contract(fn);
    end if;
  end loop;
end $$

-- 행마다 회수 묶음을 찾는다(쓰기 없음). rows: [{rowNumber, trackingNumber?, orderNumber?, phone?, receivedOn('YYYY-MM-DD')}].
create function private.claim_return_intake_match(p_rows jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare entry jsonb; results jsonb := '[]'::jsonb; used uuid[] := '{}'; seen integer[] := '{}'; row_no integer; tracking text; order_no text;
  phone text; received date; status text; matched_by text; candidates uuid[]; open_bundles uuid[]; bundle public.order_claim_collection_bundles;
  claim public.order_cancellation_requests; order_row public.orders; label text; items text;
  today date := (clock_timestamp() at time zone 'Asia/Seoul')::date;
begin
  if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 1000 then
    raise invalid_parameter_value using message = 'invalid_return_intake_rows'; end if;
  for entry in select value from jsonb_array_elements(p_rows) loop
    if jsonb_typeof(entry) is distinct from 'object' or coalesce(entry->>'rowNumber', '') !~ '^[1-9][0-9]{0,6}$'
      or exists(select 1 from jsonb_object_keys(entry) key where key not in ('rowNumber','trackingNumber','orderNumber','phone','receivedOn'))
      or exists(select 1 from jsonb_each(entry) field where field.key <> 'rowNumber' and jsonb_typeof(field.value) not in ('string','null'))
      or char_length(coalesce(entry->>'trackingNumber', '')) > 60 or char_length(coalesce(entry->>'orderNumber', '')) > 60
      or char_length(coalesce(entry->>'phone', '')) > 40 or char_length(coalesce(entry->>'receivedOn', '')) > 10 then
      raise invalid_parameter_value using message = 'invalid_return_intake_rows'; end if;
    row_no := (entry->>'rowNumber')::integer;
    if row_no = any(seen) then raise invalid_parameter_value using message = 'invalid_return_intake_rows'; end if;
    seen := seen || row_no;
    tracking := nullif(upper(regexp_replace(coalesce(entry->>'trackingNumber', ''), '[^A-Za-z0-9]', '', 'g')), '');
    order_no := nullif(regexp_replace(coalesce(entry->>'orderNumber', ''), '[^0-9]', '', 'g'), '');
    phone := nullif(regexp_replace(coalesce(entry->>'phone', ''), '[^0-9]', '', 'g'), '');
    status := null; matched_by := null; received := null; candidates := '{}'; bundle := null; claim := null; order_row := null;
    if coalesce(entry->>'receivedOn', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then status := 'received_on_invalid';
    else
      begin received := to_date(entry->>'receivedOn', 'YYYY-MM-DD');
      exception when others then status := 'received_on_invalid'; end;
      if status is null and to_char(received, 'YYYY-MM-DD') <> entry->>'receivedOn' then status := 'received_on_invalid'; end if;
      if status is null and received > today then status := 'received_on_future'; end if;
    end if;
    if status is null then
      if tracking is not null then
        select coalesce(array_agg(distinct p.bundle_id), '{}') into candidates from private.claim_return_pickups p
        where p.tracking_number = tracking and p.state in ('requested','collected');
        if cardinality(candidates) = 0 then
          select coalesce(array_agg(distinct b.id), '{}') into candidates from private.claim_collection_plans plan
          join public.order_claim_collection_bundles b on b.claim_id = plan.claim_id and b.shipment_id = plan.shipment_id
          where plan.tracking_number = tracking;
        end if;
        if cardinality(candidates) > 0 then matched_by := 'tracking'; end if;
      end if;
      if cardinality(candidates) = 0 and order_no is not null and char_length(coalesce(phone, '')) >= 8 then
        select coalesce(array_agg(b.id), '{}') into candidates from public.orders o
        join public.order_cancellation_requests c on c.order_id = o.id and c.claim_type in ('return','exchange')
        join public.order_claim_collection_bundles b on b.claim_id = c.id
        where o.order_number = order_no
          and (right(regexp_replace(coalesce(private.operational_order_address(o.id)->>'phone', ''), '[^0-9]', '', 'g'), 8) = right(phone, 8)
            or exists(select 1 from private.seller_order_claim_intakes intake where intake.claim_id = c.id
              and right(regexp_replace(coalesce(intake.payload#>>'{collectionAddress,phone}', ''), '[^0-9]', '', 'g'), 8) = right(phone, 8)));
        if cardinality(candidates) > 0 then matched_by := 'order_phone'; end if;
      end if;
      if cardinality(candidates) = 0 then
        status := case when tracking is null and order_no is not null and char_length(coalesce(phone, '')) < 8 then 'phone_required' else 'not_found' end;
      else
        select coalesce(array_agg(b.id order by b.created_at, b.id), '{}') into open_bundles from public.order_claim_collection_bundles b
        join public.order_cancellation_requests c on c.id = b.claim_id
        where b.id = any(candidates) and b.collected_at is null and c.stage not in ('withdrawn','rejected','completed');
        if cardinality(open_bundles) = 0 then
          select b.* into bundle from public.order_claim_collection_bundles b where b.id = any(candidates)
          order by b.collected_at desc nulls last, b.id limit 1;
          status := case when bundle.collected_at is not null then 'already_collected' else 'not_collectable' end;
        elsif cardinality(open_bundles) > 1 then
          status := 'ambiguous';
          select b.* into bundle from public.order_claim_collection_bundles b where b.id = open_bundles[1];
        else
          select b.* into bundle from public.order_claim_collection_bundles b where b.id = open_bundles[1];
        end if;
      end if;
    end if;
    if bundle.id is not null then
      select * into claim from public.order_cancellation_requests where id = bundle.claim_id;
      select * into order_row from public.orders where id = claim.order_id;
      if status is null then
        if claim.stage not in ('collecting','collected','processing','needs_review') then status := 'not_collectable';
        elsif private.claim_collection_waived(claim.id, bundle.shipment_id) then status := 'waived';
        elsif received < (order_row.created_at at time zone 'Asia/Seoul')::date then status := 'received_on_before_order';
        elsif bundle.id = any(used) then status := 'duplicate';
        else status := 'matched'; used := used || bundle.id;
        end if;
      end if;
      select coalesce(nullif(bundle.return_name_snapshot, ''), x.origin_name_snapshot) into label from public.order_claim_collections x
      where x.claim_id = bundle.claim_id and x.shipment_id = bundle.shipment_id;
      select string_agg((j.value->>'name') || ' ' || (j.value->>'qty') || '개', ', ' order by j.ordinality) into items
      from jsonb_array_elements(bundle.items_snapshot) with ordinality j;
    end if;
    results := results || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('rowNumber', row_no, 'status', status, 'matchedBy', matched_by,
      'trackingNumber', tracking, 'receivedOn', case when received is null then null else to_char(received, 'YYYY-MM-DD') end,
      'claimId', claim.id, 'claimType', claim.claim_type, 'claimReference', claim.reference, 'orderId', order_row.id, 'orderNumber', order_row.order_number,
      'bundleId', bundle.id, 'shipmentId', bundle.shipment_id, 'returnLabel', case when bundle.id is null then null else label end,
      'items', case when bundle.id is null then null else items end)));
  end loop;
  return results;
end $$

-- 미리보기(쓰기 없음). 꺼져 있으면 거절한다.
create function public.admin_preview_claim_return_intake(p_rows jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare settings private.return_pickup_settings; matches jsonb;
begin
  perform private.require_operator_capability('sales.manage', false);
  select * into settings from private.return_pickup_settings where singleton;
  if not found or not settings.intake_enabled then raise check_violation using message = 'claim_return_intake_disabled'; end if;
  matches := private.claim_return_intake_match(p_rows);
  return jsonb_build_object('rows', matches, 'counts', coalesce((select jsonb_object_agg(t.status, t.n)
    from (select value->>'status' status, count(*) n from jsonb_array_elements(matches) group by 1) t), '{}'::jsonb));
end $$

-- 확정. rows는 미리보기에 보낸 줄에 운영자가 확인한 묶음(bundleId, 확정하지 않을 줄은 null)을 더한 것이다. DB가 다시 맞춰 보고
-- 미리보기와 같은 묶음일 때만 회수 확인을 기록한다(달라졌으면 'changed'). 줄마다 따로 기록해 한 줄의 실패가 다른 줄을 막지 않는다.
-- 주문 순서로 처리해 다른 회수 확인과 같은 잠금 순서(주문 → 배송 건 → 클레임 → 회수 행 → 묶음)를 지킨다.
-- 같은 operation 재전송은 저장된 결과를 돌려준다(요청이 다르면 충돌).
create function public.admin_confirm_claim_return_intake(p_rows jsonb, p_file_sha256 text, p_operation uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid := (select auth.uid()); settings private.return_pickup_settings; prior private.claim_return_intake_imports; request_md5 text;
  matches jsonb; item record; outcome text; error_code text; results jsonb := '[]'::jsonb; recorded integer := 0; changed integer := 0;
  failed integer := 0; skipped integer := 0; recorded_bundles uuid[] := '{}'; result jsonb;
begin
  perform private.require_operator_capability('sales.manage', false);
  if actor is null or not public.has_operator_capability('sales.manage', false) then raise insufficient_privilege using message = 'staff required'; end if;
  select * into settings from private.return_pickup_settings where singleton;
  if not found or not settings.intake_enabled then raise check_violation using message = 'claim_return_intake_disabled'; end if;
  if p_operation is null or coalesce(p_file_sha256, '') !~ '^[0-9a-f]{64}$' or jsonb_typeof(p_rows) is distinct from 'array'
    or jsonb_array_length(p_rows) not between 1 and 1000
    or exists(select 1 from jsonb_array_elements(p_rows) r where jsonb_typeof(r) is distinct from 'object' or not (r ? 'bundleId')
      or (r->'bundleId' <> 'null'::jsonb and coalesce(r->>'bundleId', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')) then
    raise invalid_parameter_value using message = 'invalid_return_intake_rows'; end if;
  perform pg_advisory_xact_lock(hashtextextended('claim-return-intake:' || p_operation::text, 0));
  request_md5 := md5(jsonb_build_array(p_rows, p_file_sha256)::text);
  select * into prior from private.claim_return_intake_imports where id = p_operation;
  if found then
    if prior.actor_id <> actor or prior.request_md5 <> request_md5 then raise sqlstate 'PT409' using message = 'claim_return_intake_conflict'; end if;
    return prior.result || jsonb_build_object('replayed', true);
  end if;
  matches := private.claim_return_intake_match((select jsonb_agg(r.value - 'bundleId' order by r.ordinality) from jsonb_array_elements(p_rows) with ordinality r));
  for item in
    select m.value match, nullif(r.value->>'bundleId', '')::uuid expected
    from jsonb_array_elements(matches) m
    join jsonb_array_elements(p_rows) r on (r.value->>'rowNumber')::integer = (m.value->>'rowNumber')::integer
    order by m.value->>'orderId' nulls last, (m.value->>'rowNumber')::integer
  loop
    error_code := null;
    if item.expected is null then outcome := 'skipped'; skipped := skipped + 1;
    elsif item.match->>'status' <> 'matched' or (item.match->>'bundleId')::uuid <> item.expected then outcome := 'changed'; changed := changed + 1;
    else
      begin
        perform private.record_order_claim_collection_bundle((item.match->>'claimId')::uuid, null, item.expected,
          format('반품입고 회신 파일 SHA-256 %s · %s행', p_file_sha256, item.match->>'rowNumber'), (item.match->>'receivedOn')::date);
        outcome := 'recorded'; recorded := recorded + 1; recorded_bundles := recorded_bundles || item.expected;
      exception when others then
        outcome := 'failed'; failed := failed + 1;
        error_code := case when sqlerrm ~ '^[a-z][a-z0-9_]{1,63}$' then sqlerrm else 'unexpected' end;
      end;
    end if;
    results := results || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('rowNumber', (item.match->>'rowNumber')::integer, 'outcome', outcome,
      'status', item.match->>'status', 'errorCode', error_code, 'claimId', item.match->>'claimId', 'claimType', item.match->>'claimType',
      'claimReference', item.match->'claimReference', 'orderNumber', item.match->>'orderNumber', 'bundleId', item.match->>'bundleId',
      'returnLabel', item.match->>'returnLabel', 'receivedOn', item.match->>'receivedOn')));
  end loop;
  result := jsonb_build_object('operationId', p_operation, 'fileSha256', p_file_sha256, 'recorded', recorded, 'changed', changed, 'failed', failed,
    'skipped', skipped, 'rows', (select jsonb_agg(value order by (value->>'rowNumber')::integer) from jsonb_array_elements(results)), 'replayed', false);
  insert into private.claim_return_intake_imports(id, actor_id, file_sha256, request_md5, row_count, recorded, result)
  values (p_operation, actor, p_file_sha256, request_md5, jsonb_array_length(p_rows), recorded, result);
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.order.claim_return_intake_confirmed', 'claim_return_intake:' || p_operation,
    jsonb_build_object('operationId', p_operation, 'fileSha256', p_file_sha256, 'rows', jsonb_array_length(p_rows), 'recorded', recorded,
      'changed', changed, 'failed', failed, 'skipped', skipped, 'bundleIds', to_jsonb(recorded_bundles)));
  return result;
end $$

-- ---------------------------------------------------------------------------
-- 2. 나머지 설정 저장. admin_save_good_workspace(새 상품의 기본 저장 직후, 같은 트랜잭션)만 부른다.
--    섹션마다 기존 저장 RPC를 그대로 부르고, 새 상품이라 기대 버전은 지금 저장값(없으면 0)이다. 작업 ID는 섹션마다 새로 만든다
--    — 같은 등록 요청의 재시도는 래퍼 영수증이 저장 결과를 돌려주므로 섹션 RPC에 다시 들어가지 않는다.
--    순서: 매입단가 → 기간 할인 → 추가 구성 → 사은품 → A/S → 사이즈 → 색상칩 → 복수구매 할인·배송비 → 묶음그룹 →
--    정기배송 → 수령 방식 → 제작 → 판매 방식. 판매 방식(랜덤 전환)을 맨 뒤에 두어, 기존 전환 검사(goods_random_option_switch_problem)가
--    같은 요청의 정기배송·기간 할인을 모두 본다. 예약판매·제작·디지털 등 함께 쓸 수 없는 조합은 각 RPC가 지금처럼 거절한다.
create function private.save_goods_workspace_extra_sections(p_good_id text, p_sections jsonb, p_new_variants uuid[])
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor uuid := auth.uid();
  session_id uuid;
  section text;
  entry jsonb;
  value jsonb;
  variant uuid;
  saved jsonb := '{}'::jsonb;
  result jsonb;
  results jsonb;
  good_updated timestamptz;
  revision bigint;
  good_row public.goods;
  origin_doc jsonb;
  group_revision integer;
  uuid_pattern constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
begin
  if p_good_id is null or jsonb_typeof(p_sections) is distinct from 'object' then
    raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
  end if;
  -- 로그인 세션에 묶인 저장(수령 방식·제작·묶음그룹)은 지금 요청의 세션으로 부른다. 없으면 각 RPC가 권한 오류로 거절한다.
  session_id := case when coalesce(auth.jwt()->>'session_id', '') ~ uuid_pattern then (auth.jwt()->>'session_id')::uuid end;
  foreach section in array array['purchaseCosts','pricePeriods','additional','benefits','afterSales','sizeChart',
    'listingColors','transactionTerms','shippingChargeGroup','subscriptionPolicy','fulfillment','production','optionSaleMode'] loop
    continue when not (p_sections ? section);
    value := p_sections->section;
    begin
      case section
      when 'optionSaleMode' then
        if jsonb_typeof(value) is distinct from 'string' or value #>> '{}' not in ('select','random') then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        -- 새 상품은 옵션 선택 판매로 만들어진다. 랜덤 판매를 고른 경우만 전환하고, 조건은 기존 전환 RPC가 판정한다.
        if value #>> '{}' = 'random' then
          select updated_at into good_updated from public.goods where id = p_good_id;
          result := public.admin_set_goods_option_sale_mode(p_good_id, 'random', good_updated);
        else
          result := jsonb_build_object('optionSaleMode', 'select');
        end if;
      when 'purchaseCosts' then
        if jsonb_typeof(value) is distinct from 'array' or jsonb_array_length(value) > 100 then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        results := '[]'::jsonb;
        for entry in select item from jsonb_array_elements(value) item loop
          if jsonb_typeof(entry) is distinct from 'object'
            or (select array_agg(key order by key) from jsonb_object_keys(entry) key) is distinct from array['taxBasis','unitCostKrw','variant']
            or jsonb_typeof(entry->'unitCostKrw') not in ('null','number')
            or (jsonb_typeof(entry->'unitCostKrw') = 'number' and (entry->>'unitCostKrw' !~ '^(0|[1-9][0-9]*)$' or (entry->>'unitCostKrw')::numeric > 2147483647))
            or jsonb_typeof(entry->'taxBasis') not in ('null','string') then
            raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
          end if;
          variant := private.resolve_goods_workspace_variant(p_good_id, entry->'variant', p_new_variants, 'purchase_cost');
          results := results || jsonb_build_array(public.admin_save_goods_variant_purchase_cost(p_good_id, variant,
            (entry->>'unitCostKrw')::integer, entry->>'taxBasis', null) || jsonb_build_object('variantId', variant));
        end loop;
        result := results;
      when 'pricePeriods' then
        if jsonb_typeof(value) is distinct from 'array' or jsonb_array_length(value) > 100 then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        results := '[]'::jsonb;
        for entry in select item from jsonb_array_elements(value) item loop
          if jsonb_typeof(entry) is distinct from 'object'
            or (select array_agg(key order by key) from jsonb_object_keys(entry) key) is distinct from array['period','variant']
            or jsonb_typeof(entry->'period') is distinct from 'object' then
            raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
          end if;
          variant := private.resolve_goods_workspace_variant(p_good_id, entry->'variant', p_new_variants, 'price_period');
          results := results || jsonb_build_array(public.admin_save_goods_price_period(p_good_id, variant, null, entry->'period', null)
            || jsonb_build_object('variantId', variant));
        end loop;
        result := results;
      when 'additional' then
        if jsonb_typeof(value) is distinct from 'array' or jsonb_array_length(value) > 50
          or exists(select 1 from jsonb_array_elements(value) item where jsonb_typeof(item) is distinct from 'string') then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        result := public.admin_save_goods_additional(p_good_id, array(select item from jsonb_array_elements_text(value) item),
          (select sets.revision from private.goods_additional_sets sets where sets.good_id = p_good_id));
      when 'benefits' then
        select coalesce(max(content.revision), 0) into revision from private.goods_benefit_content content where content.good_id = p_good_id;
        result := public.admin_save_goods_benefit_content(p_good_id, revision::integer, gen_random_uuid(), value);
      when 'afterSales' then
        select coalesce(max(content.revision), 0) into revision from private.goods_after_sales_content content where content.good_id = p_good_id;
        result := public.admin_save_goods_after_sales_content(p_good_id, revision::integer, gen_random_uuid(), value);
      when 'sizeChart' then
        select coalesce(max(chart.revision), 0) into revision from private.goods_size_charts chart where chart.good_id = p_good_id;
        result := public.admin_save_goods_size_chart(p_good_id, revision::integer, gen_random_uuid(), value);
      when 'listingColors' then
        select coalesce(max(colors.revision), 0) into revision from private.goods_listing_colors colors where colors.good_id = p_good_id;
        result := public.admin_save_goods_listing_colors(p_good_id, value, revision, gen_random_uuid());
      when 'transactionTerms' then
        if jsonb_typeof(value) is distinct from 'object'
          or exists(select 1 from jsonb_object_keys(value) key where key not in ('volume','delivery'))
          or coalesce(jsonb_typeof(value->'volume'), 'null') not in ('null','object')
          or coalesce(jsonb_typeof(value->'delivery'), 'null') not in ('null','object') then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        select coalesce(max(config.revision), 0) into revision from private.goods_transaction_configs config where config.good_id = p_good_id;
        select updated_at into good_updated from public.goods where id = p_good_id;
        result := public.admin_save_good_transaction_terms(p_good_id, revision::integer, good_updated,
          case when jsonb_typeof(value->'volume') = 'object' then value->'volume' end,
          case when jsonb_typeof(value->'delivery') = 'object' then value->'delivery' end,
          gen_random_uuid(), actor);
      when 'shippingChargeGroup' then
        -- 화면이 고른 그룹과 그때 본 그룹 버전만 받는다. 상품·출고지 기준값은 같은 트랜잭션의 지금 저장값으로 만든다.
        if jsonb_typeof(value) is distinct from 'object'
          or (select array_agg(key order by key) from jsonb_object_keys(value) key) is distinct from array['expectedRevision','groupId']
          or jsonb_typeof(value->'groupId') is distinct from 'string' or value->>'groupId' !~ uuid_pattern
          or jsonb_typeof(value->'expectedRevision') is distinct from 'number' or value->>'expectedRevision' !~ '^[1-9][0-9]*$'
          or (value->>'expectedRevision')::numeric > 2147483647 then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        select * into good_row from public.goods where id = p_good_id;
        origin_doc := case when good_row.origin_id is null then null else private.shipping_charge_group_origin(good_row.origin_id) end;
        result := public.admin_assign_shipping_charge_group(jsonb_build_object(
          'operationId', gen_random_uuid(), 'command', 'assign', 'groupId', lower(value->>'groupId'),
          'expectedRevision', (value->>'expectedRevision')::integer, 'expectedActorId', actor, 'expectedSessionId', session_id,
          'origins', case when origin_doc is null then '[]'::jsonb else jsonb_build_array(origin_doc) end,
          'goods', jsonb_build_array(private.shipping_charge_group_good_guard(good_row))));
      when 'subscriptionPolicy' then
        if jsonb_typeof(value) is distinct from 'object'
          or (select array_agg(key order by key) from jsonb_object_keys(value) key) is distinct from array['enabled','intervals','message']
          or jsonb_typeof(value->'enabled') is distinct from 'boolean' or jsonb_typeof(value->'message') is distinct from 'string' then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        select coalesce(max(policy.revision), 0) into revision from private.goods_subscription_policies policy where policy.good_id = p_good_id;
        select updated_at into good_updated from public.goods where id = p_good_id;
        result := public.admin_save_goods_subscription_policy(actor, p_good_id, revision, good_updated, gen_random_uuid(),
          (value->>'enabled')::boolean, value->'intervals', value->>'message');
      when 'fulfillment' then
        select coalesce(max(settings.revision), 0) into revision from private.goods_fulfillment_settings settings where settings.good_id = p_good_id;
        result := public.admin_save_goods_fulfillment(p_good_id, value, revision, gen_random_uuid(), actor, session_id);
      when 'production' then
        select coalesce(max(settings.revision), 0) into revision from private.goods_production_settings settings where settings.good_id = p_good_id;
        result := public.admin_save_goods_production(p_good_id, value, revision, gen_random_uuid(), actor, session_id);
      end case;
    exception when others then
      -- 어느 섹션이 실패했는지 담아 다시 던진다(같은 오류 코드). 래퍼 트랜잭션 전체가 되돌아간다.
      raise exception using errcode = sqlstate, message = 'goods_workspace_section_failed:' || section || ':' || sqlerrm;
    end;
    saved := saved || jsonb_build_object(section, coalesce(result, 'null'::jsonb));
  end loop;
  return saved;
end
$$

-- ---------------------------------------------------------------------------
-- 3. 원자 저장 래퍼. T16a(기타 인증)·T16b(유형 확인)가 앵커 치환한 현재 정의에서 최소 변경한다.
select private.goods_workspace_all_sections_patch('public.admin_save_good_workspace(jsonb)'::regprocedure, jsonb_build_array(
  jsonb_build_array(
    $anchor$  other_certifications jsonb; other_saved jsonb;$anchor$,
    $patched$  other_certifications jsonb; other_saved jsonb;
  extra_sections jsonb:='{}'::jsonb; extra_saved jsonb; publish_requested boolean:=false; publish_result jsonb;$patched$),
  jsonb_build_array(
    $anchor$where key not in ('kc','preorders','otherCertifications')) then$anchor$,
    $patched$where key not in ('kc','preorders','otherCertifications','optionSaleMode','purchaseCosts','pricePeriods','additional',
    'benefits','afterSales','sizeChart','listingColors','transactionTerms','shippingChargeGroup','subscriptionPolicy','fulfillment','production')) then$patched$),
  jsonb_build_array(
    $anchor$  -- 공개는 기존 게시 상태 전환이 맡는다. 래퍼는 초안 저장만 한다.
  if coalesce(good->'publish','null'::jsonb) not in ('null'::jsonb,'false'::jsonb) then
    raise check_violation using message='goods_workspace_publish_unsupported';
  end if;$anchor$,
    $patched$  -- T15b(0901-008): 새 상품의 '저장 후 공개'. 기본 저장 체인은 초안으로 저장하고, 모든 섹션을 저장한 뒤 같은 요청에서 공개를
  -- 시도한다(아래 9). 저장된 상품의 공개는 지금처럼 게시 상태 전환(admin_save_good·판매 준비 카드)이 맡는다.
  if coalesce(good->'publish','null'::jsonb) not in ('null'::jsonb,'false'::jsonb,'true'::jsonb) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  publish_requested:=coalesce(good->'publish','null'::jsonb)='true'::jsonb;
  if publish_requested and nullif(good->>'previous_id','') is not null then
    raise check_violation using message='goods_workspace_publish_unsupported';
  end if;
  if publish_requested then good:=good-'publish'; end if;$patched$),
  jsonb_build_array(
    $anchor$  previous_id:=nullif(good->>'previous_id','');$anchor$,
    $patched$  previous_id:=nullif(good->>'previous_id','');
  -- T15b(1027T-024): 나머지 설정은 새 상품의 첫 저장에서만 함께 저장한다. 저장된 상품은 독립 패널이 자기 버전으로 저장한다.
  extra_sections:=sections-array['kc','preorders','otherCertifications'];
  if extra_sections<>'{}'::jsonb and previous_id is not null then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;$patched$),
  jsonb_build_array(
    $anchor$    if kc is not null or coalesce(jsonb_array_length(preorders),0)>0 or other_certifications is not null then$anchor$,
    $patched$    if kc is not null or coalesce(jsonb_array_length(preorders),0)>0 or other_certifications is not null
      or extra_sections<>'{}'::jsonb or publish_requested then$patched$),
  jsonb_build_array(
    $anchor$    result:=jsonb_build_object('id',saved_id,'operationId',operation,'created',previous_id is null,'good',saved,$anchor$,
    $patched$    -- 8. T15b(1027T-024): 나머지 설정. 각 섹션의 기존 저장 RPC가 권한·검증을 다시 하고, 실패하면 기본 입력까지 되돌린다.
    if extra_sections<>'{}'::jsonb then
      extra_saved:=private.save_goods_workspace_extra_sections(saved_id,extra_sections,new_variants);
    end if;
    result:=jsonb_build_object('id',saved_id,'operationId',operation,'created',previous_id is null,'good',saved,$patched$),
  jsonb_build_array(
    $anchor$      'otherCertifications',case when other_saved is null then null else jsonb_build_object('changed',other_saved->'changed',
        'revision',other_saved#>'{configuration,revision}') end);$anchor$,
    $patched$      'otherCertifications',case when other_saved is null then null else jsonb_build_object('changed',other_saved->'changed',
        'revision',other_saved#>'{configuration,revision}') end,
      'sections',coalesce(extra_saved,'{}'::jsonb));
    -- 9. T15b(0901-008): 저장 후 공개. 판정은 기존 공개 경로 그대로이고, 거절되면 그 시도만 되돌려 저장은 남긴다.
    if publish_requested then
      begin
        perform public.admin_set_good_published(saved_id,true);
        publish_result:=jsonb_build_object('requested',true,'published',true,'error',null,'code',null);
      exception when others then
        publish_result:=jsonb_build_object('requested',true,'published',false,'error',sqlerrm,'code',sqlstate);
      end;
      result:=result||jsonb_build_object('publish',publish_result);
    end if;$patched$),
  jsonb_build_array(
    $anchor$'preorders',coalesce(jsonb_array_length(preorders),0),'draftAlreadyCompleted',$anchor$,
    $patched$'preorders',coalesce(jsonb_array_length(preorders),0),
      'sections',(select coalesce(jsonb_agg(key order by key),'[]'::jsonb) from jsonb_object_keys(extra_sections) key),
      'publishRequested',publish_requested,'published',coalesce((publish_result->>'published')::boolean,false),
      'draftAlreadyCompleted',$patched$)))

create function private.t22i_patch_function(p_function regprocedure, p_pairs text[]) returns void
language plpgsql set search_path = '' as $$
declare definition text := pg_get_functiondef(p_function); i integer;
begin
  if array_length(p_pairs, 1) is null or array_length(p_pairs, 1) % 2 <> 0 then raise exception 't22i patch pairs'; end if;
  for i in 1 .. array_length(p_pairs, 1) / 2 loop
    if (length(definition) - length(replace(definition, p_pairs[2 * i - 1], ''))) / length(p_pairs[2 * i - 1]) <> 1 then
      raise exception '% anchor % must appear once', p_function, i;
    end if;
    definition := replace(definition, p_pairs[2 * i - 1], p_pairs[2 * i]);
  end loop;
  execute definition;
end $$

-- 1. 장바구니 다시 결제 초안이 원 주문을 기억한다.
select private.t22i_patch_function('public.service_create_checkout_retry_draft(uuid,uuid)'::regprocedure, array[
$a$  v_draft uuid;
begin$a$,
$a$  v_draft uuid;
  v_existing private.checkout_drafts%rowtype;
begin$a$,
$a$  perform private.trim_checkout_drafts(p_user_id);
  insert into private.checkout_drafts (user_id, source, lines, expires_at)
  values (p_user_id, 'selection', v_lines, pg_catalog.clock_timestamp() + private.checkout_draft_ttl())
  returning id into v_draft;$a$,
$a$  perform private.trim_checkout_drafts(p_user_id);
  -- 같은 주문의 다시 결제 초안은 하나다(T22i). 이미 그 초안으로 결제·접수·결제 확인 중 주문을 만들었으면 다시 만들지 않는다.
  select draft.* into v_existing from private.checkout_drafts as draft
  where draft.retry_order_id = p_order_id and draft.user_id = p_user_id
  for update;
  if found then
    if v_existing.order_id is not null
      and (private.checkout_draft_order_settled(v_existing.order_id) or private.checkout_draft_order_payment_unresolved(v_existing.order_id)) then
      return null;
    end if;
    update private.checkout_drafts set retry_order_id = null where id = v_existing.id;
  end if;
  insert into private.checkout_drafts (user_id, source, lines, expires_at, retry_order_id)
  values (p_user_id, 'selection', v_lines, pg_catalog.clock_timestamp() + private.checkout_draft_ttl(), p_order_id)
  returning id into v_draft;$a$
])

-- 재정의한 함수의 등록된 계약을 새 본문·ACL로 다시 적는다(분류는 기존 행 그대로).
do $$declare fn regprocedure; contract record; begin
  foreach fn in array array[
    'private.order_claim_refund_account_blocker(public.order_cancellation_requests,public.orders)'::regprocedure,
    'private.bank_transfer_refund_blocker(public.order_cancellation_requests,public.orders,text)'::regprocedure,
    'public.admin_record_order_claim_refund(uuid,text,text,text)'::regprocedure,
    'public.service_create_checkout_retry_draft(uuid,uuid)'::regprocedure,
    'public.service_list_order_retry_sources(uuid,uuid[])'::regprocedure] loop
    select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure = fn;
    if found then perform private.register_operator_rpc_contract(fn, contract.capability, contract.guard_kind, contract.legacy_admin_only);
    elsif exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure = fn) then
      perform private.register_operator_internal_contract(fn);
    end if;
  end loop;
end $$

-- 2. 나누기(화면·엑셀의 allocateSettledAmount와 같은 조건): 0원이면 모두 0, 가중치 합이 금액보다 작으면 나눌 수 없음(null).
create function private.order_v1_allocate(p_amount bigint, p_weights jsonb) returns jsonb
language plpgsql immutable set search_path = '' as $$
begin
  if p_amount = 0 then
    return (select jsonb_object_agg(w->>'id', 0) from jsonb_array_elements(p_weights) w);
  end if;
  if (select coalesce(sum((w->>'weight')::numeric), 0) from jsonb_array_elements(p_weights) w) < p_amount then return null; end if;
  return private.allocate_transaction_amount(p_amount, p_weights);
end $$

-- 3. 계산(읽기 전용). 같은 입력이면 언제나 같은 결과다. ok가 거짓이면 issue가 이유다.
--  issue: payment_unavailable(결제 한 건·결제액 = 주문 총액 아님 — 기존 막힘이 같이 잡는다) · items_missing · unsupported_discount
--   (복수구매 할인·배송비 쿠폰 — 버전 1에 없는 항목) · coupon_unrecorded(쿠폰 기록·대상 범위·대상 판정 없음)
--   · coupon_amount_mismatch · coupon_target_mismatch · credit_mismatch · shipping_snapshot_mismatch · amount_mismatch(핵심 합계 검사).
create function private.order_v1_allocation_derive(p_order_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  rule constant text := 'v1-a5-largest-remainder-1';
  purchase public.orders; pay public.payments; payment_count integer; redemption public.coupon_redemptions; terms jsonb;
  item_rows jsonb; ship_rows jsonb; coupon_alloc jsonb; credit_alloc jsonb; entry jsonb; result_items jsonb := '[]'::jsonb;
  eligible_total bigint := 0; goods_total bigint := 0; shipping_total bigint := 0; paid_total bigint := 0;
  line_coupon bigint; line_credit bigint; line_paid bigint; input jsonb;
begin
  select * into purchase from public.orders where id = p_order_id;
  if not found then return jsonb_build_object('ok', false, 'issue', 'order_not_found', 'ruleVersion', rule); end if;
  if purchase.calculation_version is distinct from 1 then return jsonb_build_object('ok', false, 'issue', 'not_v1', 'ruleVersion', rule); end if;
  select count(*) into payment_count from public.payments p where p.purpose = 'order' and p.ref_id = p_order_id and p.status <> 'failed';
  pay := private.order_partial_cancellation_payment(p_order_id);
  if payment_count <> 1 or pay.id is null or pay.amount <= 0 or pay.amount <> purchase.total then
    return jsonb_build_object('ok', false, 'issue', 'payment_unavailable', 'ruleVersion', rule);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'goodId', i.good_id, 'ipId', i.good_ip_id_snapshot, 'qty', i.qty,
      'unitPrice', i.unit_price, 'subtotal', i.qty::bigint * i.unit_price::bigint, 'volumeDiscount', i.volume_discount_total) order by i.id), '[]'::jsonb)
    into item_rows from public.order_items i where i.order_id = p_order_id;
  if jsonb_array_length(item_rows) = 0 then return jsonb_build_object('ok', false, 'issue', 'items_missing', 'ruleVersion', rule); end if;
  if purchase.volume_discount_total <> 0 or purchase.shipping_coupon_discount_total <> 0
    or exists(select 1 from jsonb_array_elements(item_rows) x where (x->>'volumeDiscount')::bigint <> 0)
    or exists(select 1 from public.coupon_redemptions r where r.order_id = p_order_id and r.status = 'applied' and r.benefit_kind <> 'goods') then
    return jsonb_build_object('ok', false, 'issue', 'unsupported_discount', 'ruleVersion', rule);
  end if;
  select coalesce(sum((x->>'subtotal')::bigint), 0) into goods_total from jsonb_array_elements(item_rows) x;

  -- 쿠폰: 화면·엑셀(admin_order_item_allocation_inputs)과 같은 기록(적용된 상품 쿠폰 중 첫 번째)과 같은 대상 판정.
  if purchase.discount_total > 0 then
    select * into redemption from public.coupon_redemptions r
      where r.order_id = p_order_id and r.status = 'applied' and r.benefit_kind = 'goods' order by r.application_index limit 1;
    terms := redemption.terms_snapshot;
    if redemption.id is null or terms is null or jsonb_typeof(terms) <> 'object' or redemption.eligible_subtotal is null
      or coalesce(terms->>'goodsScope', '') not in ('all', 'selected_goods', 'selected_categories', 'selected_ips')
      or coalesce(jsonb_typeof(terms->'targetGoodIds'), 'null') not in ('null', 'array')
      or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(terms->'targetGoodIds') = 'array' then terms->'targetGoodIds' else '[]'::jsonb end) t
        where jsonb_typeof(t) <> 'string')
      or terms ? 'targetCategoryIds' and (jsonb_typeof(terms->'targetCategoryIds') <> 'array'
        or exists(select 1 from jsonb_array_elements(terms->'targetCategoryIds') t where jsonb_typeof(t) <> 'string'))
      or terms ? 'targetIpIds' and (jsonb_typeof(terms->'targetIpIds') <> 'array'
        or exists(select 1 from jsonb_array_elements(terms->'targetIpIds') t where jsonb_typeof(t) <> 'string')) then
      return jsonb_build_object('ok', false, 'issue', 'coupon_unrecorded', 'ruleVersion', rule);
    end if;
    if redemption.discount_amount <> purchase.discount_total then
      return jsonb_build_object('ok', false, 'issue', 'coupon_amount_mismatch', 'ruleVersion', rule);
    end if;
    select jsonb_agg(x || jsonb_build_object('couponEligible', private.coupon_line_eligible_now(terms, x->>'goodId', x->>'ipId')) order by x->>'id')
      into item_rows from jsonb_array_elements(item_rows) x;
    if exists(select 1 from jsonb_array_elements(item_rows) x where jsonb_typeof(x->'couponEligible') <> 'boolean') then
      return jsonb_build_object('ok', false, 'issue', 'coupon_unrecorded', 'ruleVersion', rule);
    end if;
    select coalesce(sum((x->>'subtotal')::bigint) filter (where (x->>'couponEligible')::boolean), 0) into eligible_total
      from jsonb_array_elements(item_rows) x;
    if eligible_total <> redemption.eligible_subtotal then
      return jsonb_build_object('ok', false, 'issue', 'coupon_target_mismatch', 'ruleVersion', rule);
    end if;
    coupon_alloc := private.order_v1_allocate(purchase.discount_total, (select jsonb_agg(jsonb_build_object('id', x->>'id',
      'weight', case when (x->>'couponEligible')::boolean then (x->>'subtotal')::bigint else 0 end)) from jsonb_array_elements(item_rows) x));
    if coupon_alloc is null then return jsonb_build_object('ok', false, 'issue', 'coupon_target_mismatch', 'ruleVersion', rule); end if;
  else
    coupon_alloc := (select jsonb_object_agg(x->>'id', 0) from jsonb_array_elements(item_rows) x);
  end if;

  -- 적립금: 쿠폰 뒤 품목 금액 비례.
  credit_alloc := private.order_v1_allocate(purchase.store_credit_total, (select jsonb_agg(jsonb_build_object('id', x->>'id',
    'weight', (x->>'subtotal')::bigint - (coupon_alloc->>(x->>'id'))::bigint)) from jsonb_array_elements(item_rows) x));
  if credit_alloc is null then return jsonb_build_object('ok', false, 'issue', 'credit_mismatch', 'ruleVersion', rule); end if;

  for entry in select value from jsonb_array_elements(item_rows) loop
    line_coupon := (coupon_alloc->>(entry->>'id'))::bigint;
    line_credit := (credit_alloc->>(entry->>'id'))::bigint;
    line_paid := (entry->>'subtotal')::bigint - (entry->>'volumeDiscount')::bigint - line_coupon - line_credit;
    if line_paid < 0 then return jsonb_build_object('ok', false, 'issue', 'amount_mismatch', 'ruleVersion', rule); end if;
    paid_total := paid_total + line_paid;
    result_items := result_items || jsonb_build_object('orderItemId', entry->>'id', 'subtotal', (entry->>'subtotal')::bigint,
      'volumeDiscount', (entry->>'volumeDiscount')::bigint, 'netSubtotal', (entry->>'subtotal')::bigint - (entry->>'volumeDiscount')::bigint,
      'couponDiscount', line_coupon, 'storeCreditDiscount', line_credit, 'paidGoodsTotal', line_paid);
  end loop;

  -- 배송 건 선결제 배송비: 주문 배송비 스냅숏 그대로.
  select coalesce(jsonb_agg(jsonb_build_object('shipmentId', s.id, 'shippingFee', s.shipping_fee,
      'snapshotTotalFee', s.shipping_fee_snapshot->'totalFee') order by s.id), '[]'::jsonb)
    into ship_rows from public.order_shipments s where s.order_id = p_order_id;
  if jsonb_array_length(ship_rows) = 0 or exists(select 1 from jsonb_array_elements(ship_rows) x
      where case when coalesce(jsonb_typeof(x->'snapshotTotalFee'), 'missing') <> 'number' or (x->>'snapshotTotalFee') !~ '^[0-9]{1,15}$' then true
        else (x->>'snapshotTotalFee')::bigint <> (x->>'shippingFee')::bigint end) then
    return jsonb_build_object('ok', false, 'issue', 'shipping_snapshot_mismatch', 'ruleVersion', rule);
  end if;
  select coalesce(sum((x->>'shippingFee')::bigint), 0) into shipping_total from jsonb_array_elements(ship_rows) x;
  if shipping_total <> purchase.shipping_fee then
    return jsonb_build_object('ok', false, 'issue', 'shipping_snapshot_mismatch', 'ruleVersion', rule);
  end if;

  -- 핵심 검사: 품목 결제 몫 합 + 배송 건 배송비 합 = 결제액(1원 단위).
  if paid_total + shipping_total <> pay.amount then
    return jsonb_build_object('ok', false, 'issue', 'amount_mismatch', 'ruleVersion', rule);
  end if;

  input := jsonb_build_object('ruleVersion', rule,
    'order', jsonb_build_object('id', purchase.id, 'calculationVersion', purchase.calculation_version, 'total', purchase.total,
      'shippingFee', purchase.shipping_fee, 'discountTotal', purchase.discount_total, 'storeCreditTotal', purchase.store_credit_total,
      'volumeDiscountTotal', purchase.volume_discount_total, 'shippingCouponDiscountTotal', purchase.shipping_coupon_discount_total),
    'payment', jsonb_build_object('id', pay.id, 'amount', pay.amount),
    'coupon', case when redemption.id is null then null else jsonb_build_object('redemptionId', redemption.id, 'code', redemption.coupon_code,
      'discountAmount', redemption.discount_amount, 'eligibleSubtotal', redemption.eligible_subtotal, 'terms', terms) end,
    'items', item_rows, 'shipments', ship_rows);
  return jsonb_build_object('ok', true, 'issue', null, 'ruleVersion', rule,
    'inputHash', encode(extensions.digest(convert_to(input::text, 'UTF8'), 'sha256'), 'hex'), 'input', input,
    'paymentId', pay.id, 'paymentAmount', pay.amount, 'goodsTotal', goods_total, 'volumeDiscountTotal', 0,
    'couponDiscountTotal', purchase.discount_total, 'storeCreditTotal', purchase.store_credit_total, 'paidGoodsTotal', paid_total,
    'shippingTotal', shipping_total, 'items', result_items,
    'shipments', (select jsonb_agg(jsonb_build_object('shipmentId', x->'shipmentId', 'prepaidShippingFee', (x->>'shippingFee')::bigint)
      order by x->>'shipmentId') from jsonb_array_elements(ship_rows) x));
end $$

-- 화면 문맥: 버전 1 주문의 원장 상태(얼렸는지·막힌 이유). 버전 1이 아니면 null.
create function private.order_v1_allocation_state(p_order_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare derived jsonb;
begin
  if (select calculation_version from public.orders where id = p_order_id) is distinct from 1 then return null; end if;
  if exists(select 1 from private.order_v1_price_allocation_heads where order_id = p_order_id) then
    return jsonb_build_object('frozen', true, 'issue', null);
  end if;
  derived := private.order_v1_allocation_derive(p_order_id);
  return jsonb_build_object('frozen', false, 'issue', derived->>'issue');
end $$

-- 4. 얼리기. 첫 부분 취소 시작이 주문 행을 잠근 뒤 부른다. 이미 있으면 그대로 둔다(다시 계산하지 않는다).
create function private.freeze_order_v1_allocation(p_order_id uuid, p_actor uuid, p_operation_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare derived jsonb; blocker text; line jsonb;
begin
  perform 1 from public.orders where id = p_order_id and calculation_version = 1 for update;
  if not found then return; end if;
  if exists(select 1 from private.order_v1_price_allocation_heads where order_id = p_order_id) then return; end if;
  derived := private.order_v1_allocation_derive(p_order_id);
  if not coalesce((derived->>'ok')::boolean, false) then
    blocker := coalesce(private.order_v1_allocation_blocker(derived->>'issue'), 'payment_unavailable');
    raise check_violation using message = blocker;
  end if;
  insert into private.order_v1_price_allocation_heads(order_id, payment_id, source_calculation_version, rule_version, input_hash, input_snapshot,
    payment_amount, goods_total, volume_discount_total, coupon_discount_total, store_credit_total, paid_goods_total, shipping_total,
    frozen_by, frozen_operation_id)
  values (p_order_id, (derived->>'paymentId')::uuid, 1, derived->>'ruleVersion', derived->>'inputHash', derived->'input',
    (derived->>'paymentAmount')::bigint, (derived->>'goodsTotal')::bigint, (derived->>'volumeDiscountTotal')::bigint,
    (derived->>'couponDiscountTotal')::bigint, (derived->>'storeCreditTotal')::bigint, (derived->>'paidGoodsTotal')::bigint,
    (derived->>'shippingTotal')::bigint, p_actor, p_operation_id);
  for line in select value from jsonb_array_elements(derived->'items') loop
    insert into private.order_v1_price_allocations(order_item_id, order_id, calculation_version, subtotal, volume_discount, net_subtotal,
      coupon_discount, store_credit_discount, paid_goods_total)
    values ((line->>'orderItemId')::uuid, p_order_id, 1, (line->>'subtotal')::bigint, (line->>'volumeDiscount')::bigint,
      (line->>'netSubtotal')::bigint, (line->>'couponDiscount')::bigint, (line->>'storeCreditDiscount')::bigint, (line->>'paidGoodsTotal')::bigint);
  end loop;
  for line in select value from jsonb_array_elements(derived->'shipments') loop
    insert into private.order_v1_shipment_allocations(shipment_id, order_id, prepaid_shipping_fee)
    values ((line->>'shipmentId')::uuid, p_order_id, (line->>'prepaidShippingFee')::bigint);
  end loop;
  -- 줄 합계가 머리와 같아야 한다(머리 제약이 결제액 = 품목 결제 몫 + 배송비를 지킨다).
  if (select count(*) from private.order_v1_price_allocations where order_id = p_order_id)
      <> (select count(*) from public.order_items where order_id = p_order_id)
    or (select count(*) from private.order_v1_shipment_allocations where order_id = p_order_id)
      <> (select count(*) from public.order_shipments where order_id = p_order_id)
    or (select (sum(subtotal), sum(coupon_discount), sum(store_credit_discount), sum(paid_goods_total))
        from private.order_v1_price_allocations where order_id = p_order_id)
      is distinct from (select (goods_total::numeric, coupon_discount_total::numeric, store_credit_total::numeric, paid_goods_total::numeric)
        from private.order_v1_price_allocation_heads where order_id = p_order_id)
    or (select sum(prepaid_shipping_fee) from private.order_v1_shipment_allocations where order_id = p_order_id)
      is distinct from (select shipping_total::numeric from private.order_v1_price_allocation_heads where order_id = p_order_id) then
    raise check_violation using message = 'partial_cancel_v1_allocation_mismatch';
  end if;
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor, 'admin.order.v1_allocation_frozen', 'order:' || p_order_id::text,
    jsonb_build_object('ruleVersion', derived->>'ruleVersion', 'inputHash', derived->>'inputHash', 'operationId', p_operation_id,
      'paymentId', derived->>'paymentId', 'paymentAmount', (derived->>'paymentAmount')::bigint, 'paidGoodsTotal', (derived->>'paidGoodsTotal')::bigint,
      'shippingTotal', (derived->>'shippingTotal')::bigint, 'couponDiscountTotal', (derived->>'couponDiscountTotal')::bigint,
      'storeCreditTotal', (derived->>'storeCreditTotal')::bigint, 'items', derived->'items', 'shipments', derived->'shipments'));
end $$

-- 5. 원장 읽기 seam(판정·금액). 품목: 불변 원장(버전 2 원장 또는 얼린 버전 1 원장), 아직 얼리지 않은 버전 1 주문은 같은 계산.
--    배송 건: 버전 1은 원장(또는 같은 계산)의 선결제 배송비, 그 밖은 배송 건 배송비(지금과 같다).
create function private.order_item_price_allocation(p_order_item_id uuid) returns private.order_price_allocations
language plpgsql stable security definer set search_path = '' as $$
declare result private.order_price_allocations; item public.order_items; derived jsonb; entry jsonb;
begin
  select l.order_item_id, l.order_id, l.calculation_version, l.subtotal, l.volume_discount, l.net_subtotal, l.coupon_discount,
    l.store_credit_discount, l.paid_goods_total
    into result from private.order_price_allocation_ledger l where l.order_item_id = p_order_item_id;
  if found then return result; end if;
  select * into item from public.order_items where id = p_order_item_id;
  if not found or (select calculation_version from public.orders where id = item.order_id) is distinct from 1
    or exists(select 1 from private.order_v1_price_allocation_heads where order_id = item.order_id) then
    return null;
  end if;
  derived := private.order_v1_allocation_derive(item.order_id);
  if not coalesce((derived->>'ok')::boolean, false) then return null; end if;
  select value into entry from jsonb_array_elements(derived->'items') where value->>'orderItemId' = p_order_item_id::text;
  if entry is null then return null; end if;
  result := row(p_order_item_id, item.order_id, 1, (entry->>'subtotal')::bigint, (entry->>'volumeDiscount')::bigint,
    (entry->>'netSubtotal')::bigint, (entry->>'couponDiscount')::bigint, (entry->>'storeCreditDiscount')::bigint,
    (entry->>'paidGoodsTotal')::bigint)::private.order_price_allocations;
  return result;
end $$

create function private.order_shipment_prepaid_fee(p_shipment_id uuid) returns bigint
language plpgsql stable security definer set search_path = '' as $$
declare ship public.order_shipments; fee bigint; derived jsonb;
begin
  select * into ship from public.order_shipments where id = p_shipment_id;
  if not found then raise no_data_found using message = 'shipment_not_found'; end if;
  if (select calculation_version from public.orders where id = ship.order_id) is distinct from 1 then return ship.shipping_fee; end if;
  if exists(select 1 from private.order_v1_price_allocation_heads where order_id = ship.order_id) then
    select prepaid_shipping_fee into fee from private.order_v1_shipment_allocations where shipment_id = p_shipment_id;
  else
    derived := private.order_v1_allocation_derive(ship.order_id);
    if coalesce((derived->>'ok')::boolean, false) then
      select (value->>'prepaidShippingFee')::bigint into fee from jsonb_array_elements(derived->'shipments') where value->>'shipmentId' = p_shipment_id::text;
    end if;
  end if;
  if fee is null then raise check_violation using message = 'partial_cancel_v1_allocation_unavailable'; end if;
  return fee;
end $$

-- 6. T12b 판정·계산·시작을 seam에 잇는다(런타임 정의에 대한 앵커 치환 — 앵커는 정확히 1회).
create function private.t12c_patch_function(p_function regprocedure, p_pairs text[]) returns void
language plpgsql set search_path = '' as $$
declare definition text := pg_get_functiondef(p_function); i integer;
begin
  if array_length(p_pairs, 1) is null or array_length(p_pairs, 1) % 2 <> 0 then raise exception 't12c patch pairs'; end if;
  for i in 1 .. array_length(p_pairs, 1) / 2 loop
    if (length(definition) - length(replace(definition, p_pairs[2 * i - 1], ''))) / length(p_pairs[2 * i - 1]) <> 1 then
      raise exception '% anchor % must appear once', p_function, i;
    end if;
    definition := replace(definition, p_pairs[2 * i - 1], p_pairs[2 * i]);
  end loop;
  execute definition;
end $$

-- 시작: 판정이 열려 있으면 계산 전에 버전 1 주문의 배분을 얼린다(주문 행 잠금 아래, 한 번만). 막혀 있으면 아래 계산이 그 이유로 거절한다.
select private.t12c_patch_function('public.admin_start_order_partial_cancellation(uuid,jsonb,text,text,boolean,bigint,uuid,jsonb)'::regprocedure, array[
$a$  plan := private.order_partial_cancellation_plan(p_order_id, p_items);$a$,
$a$  if cardinality(private.order_partial_cancellation_blockers(p_order_id)) = 0 then
    perform private.freeze_order_v1_allocation(p_order_id, v_actor, p_operation_id);
  end if;
  plan := private.order_partial_cancellation_plan(p_order_id, p_items);$a$
])

do $$declare fn regprocedure; contract record; begin
  foreach fn in array array[
    'private.order_partial_cancellation_blockers(uuid)'::regprocedure,
    'private.order_partial_cancellation_item_blocker(uuid)'::regprocedure,
    'private.order_partial_cancellation_plan(uuid,jsonb)'::regprocedure,
    'public.admin_start_order_partial_cancellation(uuid,jsonb,text,text,boolean,bigint,uuid,jsonb)'::regprocedure,
    'public.admin_order_partial_cancellation_context(uuid)'::regprocedure] loop
    select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure = fn;
    if found then perform private.register_operator_rpc_contract(fn, contract.capability, contract.guard_kind, contract.legacy_admin_only);
    elsif exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure = fn) then
      perform private.register_operator_internal_contract(fn);
    end if;
  end loop;
end $$

