-- QA 라운드 2: 웨이브 2의 반품/교환지(claimReturnAddressId)가 화면 입력 기록(GOOD_LOCAL_DRAFT_FIELDS)과 서버 임시저장 값에 실리는데
-- admin_save_goods_draft 허용 키에 없어 상품 등록 [임시저장]이 매번 invalid_goods_draft로 실패했다.
-- 화면 허용 키와 DB 허용 키를 전수 대조한 결과(11/13) 어긋난 키는 이 하나뿐이다. 값은 반품지 id 규칙(빈 문자열 또는 UUID)과 같게 검사한다.
-- 앵커 치환은 정확히 1회 일치해야 하고, 아니면 migration이 멈춘다.
do $patch$
declare
  def text := pg_get_functiondef('public.admin_save_goods_draft(uuid,jsonb,integer)'::regprocedure);
  patched text;
  pairs text[][] := array[
    array[$a$'claimReturnFee','claimReturnFreeShippingFee','claimExchangeFee',$a$,
          $r$'claimReturnFee','claimReturnFreeShippingFee','claimExchangeFee','claimReturnAddressId',$r$],
    array[$a$    or coalesce(p_values->>'variantBaseline','[]')<>'[]' or coalesce(p_values->>'customInputsExpectedRevision','0')<>'0'$a$,
          $r$    or coalesce(p_values->>'variantBaseline','[]')<>'[]' or coalesce(p_values->>'customInputsExpectedRevision','0')<>'0'
    or coalesce(p_values->>'claimReturnAddressId','')<>'' and p_values->>'claimReturnAddressId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'$r$]
  ];
  i int;
begin
  patched := def;
  for i in 1..array_length(pairs, 1) loop
    if (length(patched) - length(replace(patched, pairs[i][1], ''))) / length(pairs[i][1]) <> 1 then
      raise exception 'goods_draft_return_address_key anchor % must match exactly once', i;
    end if;
    patched := replace(patched, pairs[i][1], pairs[i][2]);
  end loop;
  execute patched;
end
$patch$

-- QA 라운드 2(T14d): 다른 예약 상품과 함께 묶인 배송 건이 그 상품의 예정일 때문에 입력한 새 날짜로 바뀌지 못해 지금 날짜와 같아지면
-- 제외 사유가 '이미 같은 발송 예정일(unchanged)'로 보였다(입력 날짜와 지금 날짜는 다른데도). 이 경우의 진짜 이유는 묶음 상품의 예정일이므로
-- other_preorder로 먼저 판정한다. 입력 날짜가 지금 날짜와 정말 같아서 바뀔 것이 없는 건(묶음 배송이어도)은 그대로 unchanged다.
-- 미리보기와 확정이 같은 계획 함수를 쓰므로 둘 다 바뀐다. 앵커 치환은 정확히 1회 일치해야 하고 아니면 migration이 멈춘다.
do $patch$
declare
  def text := pg_get_functiondef('private.goods_preorder_schedule_plan(text,uuid,date)'::regprocedure);
  anchor text := $a$    when d.new_date=d.current_date_value and not d.notice_only then 'unchanged'$a$;
  replacement text := $r$    when d.other_bound is not null and p_to_date<d.other_bound and p_to_date<>d.current_date_value
      and d.new_date=d.current_date_value and not d.notice_only then 'other_preorder'
    when d.new_date=d.current_date_value and not d.notice_only then 'unchanged'$r$;
begin
  if (length(def) - length(replace(def, anchor, ''))) / length(anchor) <> 1 then
    raise exception 'preorder_schedule_exclusion_reason_order anchor must match exactly once';
  end if;
  execute replace(def, anchor, replacement);
end
$patch$

create function public.admin_tracking_reply_shipment_links(p_references text[]) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  refs text[];
  result jsonb;
begin
  if auth.uid() is null or not public.has_operator_capability('sales.dispatch', false) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  if p_references is null or coalesce(array_length(p_references, 1), 0) > 2000 then
    raise exception using message = 'tracking_reply_references_invalid';
  end if;
  select coalesce(array_agg(distinct pg_catalog.lower(btrim(ref))), array[]::text[]) into refs
  from unnest(p_references) as ref where ref is not null and btrim(ref) <> '';
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('reference', found.reference, 'shipmentId', found.shipment_id)), '[]'::jsonb) into result
  from (
    select distinct on (match.reference, link.shipment_id) match.reference, link.shipment_id
    from (
      select pg_catalog.lower(i.product_order_number) as reference, i.id as item_id
      from public.order_items i where pg_catalog.lower(i.product_order_number) = any(refs)
      union all
      select i.id::text, i.id from public.order_items i where i.id::text = any(refs)
    ) match
    join public.order_shipment_items link on link.order_item_id = match.item_id
  ) found;
  return result;
end $$

create function public.admin_shipment_partial_cancel_flags(p_ids uuid[]) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare result jsonb;
begin
  if auth.uid() is null or not public.has_operator_capability('sales.dispatch', false) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  if p_ids is null or coalesce(array_length(p_ids, 1), 0) > 1000 then
    raise exception using message = 'shipment_ids_invalid';
  end if;
  select coalesce(pg_catalog.jsonb_agg(s.id order by s.id), '[]'::jsonb) into result
  from public.order_shipments s
  where s.id = any(p_ids) and private.order_partial_cancel_in_flight(s.order_id);
  return result;
end $$

