create or replace function private.store_navigation_valid(settings jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
declare entry jsonb; ids text[]:='{}'; label text;
begin
  if jsonb_typeof(settings) is distinct from 'array' then return false; end if;
  if jsonb_array_length(settings)<>9 then return false; end if;
  for entry in select value from jsonb_array_elements(settings) loop
    if jsonb_typeof(entry) is distinct from 'object' then return false; end if;
    if not entry ?& array['id','label','visible'] or (select count(*) from jsonb_object_keys(entry))<>3
      or jsonb_typeof(entry->'id') is distinct from 'string'
      or entry->>'id' not in ('new','best','shop','popups','events','iphub','packs','community','stories')
      or jsonb_typeof(entry->'label') is distinct from 'string'
      or jsonb_typeof(entry->'visible') is distinct from 'boolean'
      or entry->>'id'=any(ids) then return false; end if;
    label:=entry->>'label';
    if length(label) not between 1 and 20 or label ~ '[[:cntrl:]]'
      or label<>btrim(label,E' \t\n\r\f\v'||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
      or (entry->>'id'='shop' and not (entry->>'visible')::boolean) then return false; end if;
    ids:=array_append(ids,entry->>'id');
  end loop;
  return true;
end $$

-- 저장된 8개 설정을 9개로 옮기는 순수 변환. 이 migration 이 쓰고, 옮기는 규칙을 SQL 시험이 직접 부를 수 있게 남겨 둔다.
create function private.upgrade_store_navigation_popups(settings jsonb)
returns jsonb language plpgsql stable set search_path='' as $$
declare
  old_default constant jsonb:='[{"id":"new","label":"NEW","visible":true},{"id":"best","label":"BEST","visible":true},{"id":"shop","label":"카테고리","visible":true},{"id":"iphub","label":"온라인 팝업","visible":true},{"id":"packs","label":"카드팩","visible":true},{"id":"events","label":"이벤트","visible":true},{"id":"community","label":"커뮤니티","visible":true},{"id":"stories","label":"쇼핑스토리","visible":true}]'::jsonb;
  new_default constant jsonb:='[{"id":"new","label":"NEW","visible":true},{"id":"best","label":"BEST","visible":true},{"id":"shop","label":"카테고리","visible":true},{"id":"popups","label":"POP-UP","visible":true},{"id":"events","label":"EVENT","visible":true},{"id":"iphub","label":"온라인 팝업","visible":false},{"id":"packs","label":"카드팩","visible":false},{"id":"community","label":"커뮤니티","visible":false},{"id":"stories","label":"쇼핑스토리","visible":false}]'::jsonb;
begin
  if settings=old_default then return new_default; end if;
  if jsonb_typeof(settings) is distinct from 'array'
    or exists(select 1 from jsonb_array_elements(settings) entry where entry->>'id'='popups') then return settings; end if;
  return (
    select jsonb_agg(item order by position) from (
      select case when entry->>'id'='stories' then jsonb_set(entry,'{visible}','false'::jsonb) else entry end as item, ordinal::numeric as position
      from jsonb_array_elements(settings) with ordinality entries(entry,ordinal)
      union all
      select '{"id":"popups","label":"POP-UP","visible":true}'::jsonb, ordinal::numeric+0.5
      from jsonb_array_elements(settings) with ordinality entries(entry,ordinal) where entry->>'id'='shop'
    ) rebuilt
  );
end $$

-- X SQUARE 홈(ADR-0043): 고정 홈 블록 2개(NEW ARRIVAL = new_arrivals, 홈 스트립 배너 = strip_banner)와
-- 상품 모음의 '그리드형(5열)'(layout 'grid'). 정의 원본은 20261020085320_home_free_product_collections.sql이며
-- 허용 목록만 바꿨다 — 필수 키 집합(원래 다섯 개)·나머지 규칙은 그대로라 새 키가 없는 옛 저장값·옛 요청도 계속 유효하다.
-- `private.save_home_curation`은 `private.is_valid_home_product_collection`만 부르므로 고치지 않는다.

-- 1) 상품 모음: layout 'grid'는 item_count 5 또는 10, image_shape 'square' 고정. list(3~12)·full_image(1~8) 범위는 그대로.
create or replace function private.is_valid_home_product_collection(candidate jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
declare item jsonb;seen text[]:='{}';count_value numeric;
begin
 if candidate is null or jsonb_typeof(candidate)<>'object' then return false;end if;
 if not candidate ?& array['layout','image_shape','item_count','good_ids']
  or candidate-array['layout','image_shape','item_count','good_ids']<>'{}'::jsonb
  or jsonb_typeof(candidate->'layout') is distinct from 'string'
  or candidate->>'layout' not in ('list','full_image','grid')
  or jsonb_typeof(candidate->'image_shape') is distinct from 'string'
  or candidate->>'image_shape' not in ('square','portrait','landscape')
  or jsonb_typeof(candidate->'item_count') is distinct from 'number'
  or jsonb_typeof(candidate->'good_ids') is distinct from 'array' then return false;end if;
 count_value:=(candidate->>'item_count')::numeric;
 if count_value<>trunc(count_value)
  or (candidate->>'layout'='list' and count_value not between 3 and 12)
  or (candidate->>'layout'='full_image' and count_value not between 1 and 8)
  or (candidate->>'layout'='grid' and (count_value not in (5,10) or candidate->>'image_shape'<>'square'))
  or jsonb_array_length(candidate->'good_ids')>100 then return false;end if;
 for item in select value from jsonb_array_elements(candidate->'good_ids') loop
  if jsonb_typeof(item)<>'string' or item#>>'{}'!~'^[A-Za-z0-9_-]{1,64}$' or (item#>>'{}')=any(seen) then return false;end if;
  seen:=array_append(seen,item#>>'{}');
 end loop;
 return true;
end $$

-- 2) 레이아웃 검증: 고정 키에 new_arrivals·strip_banner 추가(저장 레이아웃에는 선택 키다).
CREATE OR REPLACE FUNCTION private.is_valid_home_layout_blocks(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare entry jsonb; block_key text; seen text[] := '{}';
begin
  if candidate is null then return true; end if;
  if pg_catalog.jsonb_typeof(candidate) <> 'array'
    or pg_catalog.jsonb_array_length(candidate) not between 5 and 1000 then return false; end if;
  for entry in select value from pg_catalog.jsonb_array_elements(candidate)
  loop
    if pg_catalog.jsonb_typeof(entry) <> 'object'
      or pg_catalog.jsonb_typeof(entry->'key') is distinct from 'string'
      or pg_catalog.jsonb_typeof(entry->'enabled') is distinct from 'boolean'
      or exists(select 1 from pg_catalog.jsonb_object_keys(entry) field where field not in ('key','enabled'))
    then return false; end if;
    block_key := entry->>'key';
    if block_key = any(seen) then return false; end if;
    if block_key not in ('hero','editor_picks','category_best','popular','benefits','stories','new_arrivals','strip_banner')
      and block_key !~ '^(band|sales|reviews|mosaic|products):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then return false; end if;
    seen := pg_catalog.array_append(seen, block_key);
  end loop;
  return array['hero','editor_picks','category_best','popular','benefits']::text[] <@ seen;
end;
$function$

-- 3) 공개 순서 RPC: 두 키를 공개 렌더 키로 인정하고, 저장 레이아웃에 없으면 stories와 같은 방식으로 맨 뒤에
--    stories → new_arrivals → strip_banner 순서로 붙인다(명시적으로 숨긴 키는 되살리지 않는다).
CREATE OR REPLACE FUNCTION public.get_home_layout_order()
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare configured jsonb; result text[];
begin
  select blocks into configured from public.home_layout_settings where singleton;
  if configured is null then return null; end if;
  with requested as (
    select item->>'key' as key, item->'enabled'='true'::jsonb as enabled, position
    from pg_catalog.jsonb_array_elements(configured) with ordinality entries(item,position)
  ), active_bands as (
    select (case kind when 'band_banner' then 'band:' when 'sales_best' then 'sales:' when 'review_best' then 'reviews:' when 'product_mosaic' then 'mosaic:' else 'products:' end)||id::text as key,
      case kind when 'band_banner' then 0 when 'sales_best' then 1 when 'review_best' then 2 when 'product_mosaic' then 3 else 4 end as kind_order,display_order, active_from, id
    from public.home_curations
    where kind in ('band_banner','sales_best','review_best','product_mosaic','product_collection') and enabled and active_from<=now()
      and (active_to is null or active_to>now())
      and (kind<>'product_collection' or jsonb_array_length(private.public_home_product_collection_goods(payload))>0)
  ), ordered as (
    select requested.key, requested.position
    from requested
    where requested.enabled and (
      requested.key in ('hero','editor_picks','category_best','popular','benefits','stories','new_arrivals','strip_banner')
      or exists(select 1 from active_bands where active_bands.key=requested.key)
    )
    union all
    select active_bands.key,
      pg_catalog.jsonb_array_length(configured)+row_number() over(order by kind_order,display_order,active_from,id)
    from active_bands where not exists(select 1 from requested where requested.key=active_bands.key)
    union all
    select fixed.key,pg_catalog.jsonb_array_length(configured)+(select count(*) from active_bands)+fixed.slot
    from (values ('stories',1),('new_arrivals',2),('strip_banner',3)) fixed(key,slot)
    where not exists(select 1 from requested where requested.key=fixed.key)
  )
  select coalesce(pg_catalog.array_agg(key order by position),'{}'::text[]) into result from ordered;
  return result;
end;
$function$

-- 4) 이행: 저장된 레이아웃이 있으면 new_arrivals를 editor_picks 바로 뒤, strip_banner를 그 뒤에 켠 상태로 끼운다.
--    이미 있는 키는 건드리지 않고(운영자가 숨겼다면 그대로), 한쪽만 있으면 나머지 하나만 알맞은 자리에 더한다.
--    저장된 레이아웃이 없으면(null) 코드 기본 순서가 같은 위치를 쓰므로 바꾸지 않는다. revision을 올려 열려 있던
--    어드민 화면이 옛 값으로 덮어쓰지 못하게 한다(낙관적 충돌). 시스템 이행이라 감사 기록 선례가 없어 audit_log는 쓰지 않는다.
do $$
declare current_blocks jsonb; rebuilt jsonb:='[]'::jsonb; entry jsonb; has_arrivals boolean; has_strip boolean;
begin
  select blocks into current_blocks from public.home_layout_settings where singleton for update;
  if current_blocks is null then return; end if;
  has_arrivals:=exists(select 1 from pg_catalog.jsonb_array_elements(current_blocks) e where e->>'key'='new_arrivals');
  has_strip:=exists(select 1 from pg_catalog.jsonb_array_elements(current_blocks) e where e->>'key'='strip_banner');
  if has_arrivals and has_strip then return; end if;
  for entry in select value from pg_catalog.jsonb_array_elements(current_blocks) with ordinality entries(value,position) order by position loop
    rebuilt:=rebuilt||pg_catalog.jsonb_build_array(entry);
    if entry->>'key'='editor_picks' and not has_arrivals then
      rebuilt:=rebuilt||'[{"key":"new_arrivals","enabled":true}]'::jsonb;
      if not has_strip then rebuilt:=rebuilt||'[{"key":"strip_banner","enabled":true}]'::jsonb; end if;
    elsif entry->>'key'='new_arrivals' and not has_strip then
      rebuilt:=rebuilt||'[{"key":"strip_banner","enabled":true}]'::jsonb;
    end if;
  end loop;
  update public.home_layout_settings set blocks=rebuilt,revision=revision+1,updated_at=clock_timestamp() where singleton;
end $$

do $$
declare
  body text;
  anchors text[] := array[
    $a$'recommended','name_asc','name_desc','price_asc','price_desc','oldest','newest'$a$,
    $a$), ranked as materialized ($a$,
    $a$   case when p_query->>'sort'='price_asc' then current_price end asc,$a$
  ];
  replacements text[] := array[
    $a$'recommended','name_asc','name_desc','price_asc','price_desc','oldest','newest','popular','sales','reviews'$a$,
    $a$), metrics as materialized (select * from private.goods_listing_metrics()), ranked as materialized ($a$,
    $a$   case when p_query->>'sort'='popular' then (select coalesce(m.sales_30d,0)+coalesce(m.wish_count,0) from metrics m where m.good_id=filtered.id) end desc nulls last,
   case when p_query->>'sort'='sales' then (select m.sales_total from metrics m where m.good_id=filtered.id) end desc nulls last,
   case when p_query->>'sort'='reviews' then (select m.review_count from metrics m where m.good_id=filtered.id) end desc nulls last,
   case when p_query->>'sort'='price_asc' then current_price end asc,$a$
  ];
  i integer;
begin
  body := pg_get_functiondef('private.category_display_page(uuid,jsonb,jsonb,integer,text,bigint)'::regprocedure);
  for i in 1..array_length(anchors, 1) loop
    if (length(body) - length(replace(body, anchors[i], ''))) / length(anchors[i]) <> 1 then
      raise exception 'category_display_listing_sorts_anchor_missing: %', anchors[i];
    end if;
    body := replace(body, anchors[i], replacements[i]);
  end loop;
  execute body;
end $$

-- 저장: 값을 정리하고(공백 제거·빈 문자열 → null) 모두 비면 행을 지운다. 감사 기록에 전후 값을 남긴다.
-- 머리말은 admin_upsert_campaign 과 같은 순서다(운영자 권한 → 인증 → 권한 재확인). 캠페인 행을 잠가
-- 같은 캠페인의 동시 저장이 직렬화되게 하고, 감사 기록의 이전 값이 어긋나지 않게 한다.
create function public.admin_save_campaign_presentation(
  target_campaign_id text,
  target_popup_mode text,
  target_popup_location text,
  target_card_link_path text
)
returns void
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  actor_id uuid := (select auth.uid());
  normalized_id text := btrim(coalesce(target_campaign_id, ''), E' \t\n\r\f\v');
  normalized_mode text := nullif(btrim(coalesce(target_popup_mode, ''), E' \t\n\r\f\v'), '');
  normalized_location text := nullif(btrim(coalesce(target_popup_location, ''), E' \t\n\r\f\v'), '');
  normalized_link text := nullif(btrim(coalesce(target_card_link_path, ''), E' \t\n\r\f\v'), '');
  before_value jsonb;
  after_value jsonb;
begin
  perform private.require_operator_capability('promotion.manage', false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.has_operator_capability('promotion.manage', false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  perform 1 from public.campaigns where id = normalized_id for update;

  if not found then
    raise exception 'campaign_not_found' using errcode = 'P0002';
  end if;

  -- POP-UP 에 싣지 않으면 장소도 없다.
  if normalized_mode is null then
    normalized_location := null;
  end if;

  if (normalized_mode is not null and normalized_mode not in ('online', 'offline', 'hybrid'))
    or (normalized_location is not null and char_length(normalized_location) > 120)
    or (normalized_link is not null
      and (char_length(normalized_link) > 300 or normalized_link !~ '^/(?![/\\])[^\s]*$')) then
    raise exception 'invalid_campaign_presentation' using errcode = '22023';
  end if;

  select jsonb_build_object('popupMode', p.popup_mode, 'popupLocation', p.popup_location, 'cardLinkPath', p.card_link_path)
  into before_value
  from public.campaign_presentations p
  where p.campaign_id = normalized_id;

  if normalized_mode is null and normalized_location is null and normalized_link is null then
    delete from public.campaign_presentations where campaign_id = normalized_id;
    after_value := null;
  else
    insert into public.campaign_presentations (campaign_id, popup_mode, popup_location, card_link_path, updated_at, updated_by)
    values (normalized_id, normalized_mode, normalized_location, normalized_link, now(), actor_id)
    on conflict (campaign_id) do update set
      popup_mode = excluded.popup_mode,
      popup_location = excluded.popup_location,
      card_link_path = excluded.card_link_path,
      updated_at = excluded.updated_at,
      updated_by = excluded.updated_by;
    after_value := jsonb_build_object('popupMode', normalized_mode, 'popupLocation', normalized_location, 'cardLinkPath', normalized_link);
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'admin.campaign.presentation_saved',
    'campaigns:' || normalized_id,
    jsonb_build_object('before', before_value, 'after', after_value)
  );
end;
$$

