-- 5. 뒤바뀐 운송장 맞바꾸기. 두 주문의 운송장이 서로 바뀌어 등록되면 위 판정 때문에 어느 쪽도 상대 번호로 정정할 수 없다.
--    운영자가 두 배송 건(합포장이면 묶음 전체)의 대표 운송장을 한 트랜잭션에서 맞바꾼다. 화면이 본 두 번호(p_expected_*)가 지금 값과
--    같을 때만 바꾸므로 같은 요청을 다시 보내도 되돌아가지 않는다(두 번째는 shipment_tracking_changed). 추가 운송장은 그대로다.
create function public.admin_swap_shipment_trackings(p_shipment_id uuid, p_expected_tracking text, p_other_reference text,
  p_expected_other_tracking text, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; other_id uuid; reason_value text := nullif(btrim(coalesce(p_reason, '')), '');
  first_scope uuid[]; second_scope uuid[]; first public.order_shipments; second public.order_shipments; member public.order_shipments;
begin
  actor := private.require_operator_capability('sales.dispatch', false);
  if p_shipment_id is null or p_other_reference is null then raise invalid_parameter_value using message = 'invalid_tracking_swap'; end if;
  if reason_value is null or char_length(reason_value) > 500 then raise check_violation using message = 'tracking_swap_reason_required'; end if;
  other_id := private.resolve_shipment_reference(p_other_reference);
  if other_id = p_shipment_id then raise invalid_parameter_value using message = 'invalid_tracking_swap'; end if;
  -- 주문 → 배송 건 순서로 두 묶음을 한 번에 잠근다(다른 등록 경로와 같은 순서).
  perform private.lock_shipment_pack_scope(array[p_shipment_id, other_id]);
  first_scope := private.shipment_pack_scope(array[p_shipment_id]);
  second_scope := private.shipment_pack_scope(array[other_id]);
  if first_scope && second_scope then raise check_violation using message = 'tracking_swap_same_pack'; end if;
  select * into first from public.order_shipments where id = p_shipment_id;
  select * into second from public.order_shipments where id = other_id;
  if exists(select 1 from public.order_shipments s join public.orders o on o.id = s.order_id
    where s.id = any(first_scope || second_scope)
      and (s.delivery_method <> 'parcel' or s.status not in ('shipping', 'delivered') or o.status = 'canceled' or s.tracking_number is null)) then
    raise check_violation using message = 'order_not_shipped'; end if;
  if first.tracking_number is distinct from private.normalize_tracking_number(p_expected_tracking)
    or second.tracking_number is distinct from private.normalize_tracking_number(p_expected_other_tracking)
    or exists(select 1 from public.order_shipments where id = any(first_scope) and (carrier, tracking_number) is distinct from (first.carrier, first.tracking_number))
    or exists(select 1 from public.order_shipments where id = any(second_scope) and (carrier, tracking_number) is distinct from (second.carrier, second.tracking_number)) then
    raise check_violation using message = 'shipment_tracking_changed'; end if;
  if (first.carrier, first.tracking_number) = (second.carrier, second.tracking_number) then
    raise check_violation using message = 'invalid_tracking_swap'; end if;
  perform pg_advisory_xact_lock(key) from (select unnest(array[private.tracking_number_lock_key(first.carrier, first.tracking_number),
    private.tracking_number_lock_key(second.carrier, second.tracking_number)]) key order by 1) keys;
  update public.order_shipments set carrier = second.carrier, tracking_number = second.tracking_number, updated_at = clock_timestamp() where id = any(first_scope);
  update public.order_shipments set carrier = first.carrier, tracking_number = first.tracking_number, updated_at = clock_timestamp() where id = any(second_scope);
  -- 맞바꾼 뒤에도 각 번호를 다른 주문(추가 운송장·재출고 포함)이 쓰고 있으면 바꾸지 않는다.
  if private.tracking_number_conflict(second.carrier, second.tracking_number, first_scope, null) is not null
    or private.tracking_number_conflict(first.carrier, first.tracking_number, second_scope, null) is not null then
    raise check_violation using message = 'tracking_number_in_use'; end if;
  for member in select * from public.order_shipments where id = any(first_scope || second_scope) order by id loop
    insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.shipment.tracking_updated', 'order:' || member.order_id,
      jsonb_build_object('shipmentId', member.id, 'originName', member.origin_name_snapshot,
        'fromCarrier', case when member.id = any(first_scope) then first.carrier else second.carrier end,
        'fromTrackingNumber', case when member.id = any(first_scope) then first.tracking_number else second.tracking_number end,
        'toCarrier', member.carrier, 'toTrackingNumber', member.tracking_number,
        'swappedWithShipmentId', case when member.id = any(first_scope) then second.id else first.id end, 'reason', reason_value));
  end loop;
  return jsonb_build_object('status', 'swapped', 'shipmentId', first.id, 'orderId', first.order_id, 'otherShipmentId', second.id, 'otherOrderId', second.order_id,
    'trackingNumber', second.tracking_number, 'otherTrackingNumber', first.tracking_number);
end $$

-- 6. 중복 확인 후 등록. 판정이 다른 주문의 쓰임으로 거절했지만 같은 상자가 맞는 경우(7일이 지난 합배송 확인, 받는 분 표기가 달라
--    열쇠가 어긋난 같은 집 등) 운영자가 사유를 적어 그 배송 건에 그 번호를 등록한다. 형식 검사는 그대로이고, 승인·감사 기록이 남는다.
--    발송 대기 건은 발송처리, 발송된 건은 운송장 정정과 같은 경로(합포장 묶음 전체)를 지난다.
create function public.admin_register_shipment_tracking_duplicate(p_shipment_id uuid, p_carrier text, p_tracking_number text, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; carrier_value text := nullif(btrim(coalesce(p_carrier, '')), ''); tracking_value text := private.normalize_tracking_number(p_tracking_number);
  reason_value text := nullif(btrim(coalesce(p_reason, '')), ''); scope uuid[]; shipment public.order_shipments; conflict jsonb; outcome text;
begin
  actor := private.require_operator_capability('sales.dispatch', false);
  if p_shipment_id is null then raise invalid_parameter_value using message = 'invalid_tracking_duplicate'; end if;
  if reason_value is null or char_length(reason_value) > 500 then raise check_violation using message = 'tracking_duplicate_reason_required'; end if;
  if carrier_value is null or tracking_value is null or tracking_value !~ '^[A-Z0-9]{8,30}$' then
    raise check_violation using message = 'invalid_tracking_input'; end if;
  if not exists(select 1 from public.shipping_carriers where code = carrier_value and is_active) then
    raise check_violation using message = 'inactive_shipping_carrier'; end if;
  if not private.tracking_number_format_ok(carrier_value, tracking_value) then
    raise check_violation using message = 'tracking_number_format_mismatch'; end if;
  scope := private.lock_shipment_pack_scope(array[p_shipment_id]);
  select * into shipment from public.order_shipments where id = p_shipment_id;
  if shipment.delivery_method <> 'parcel' then raise check_violation using message = 'delivery_method_evidence_required'; end if;
  if shipment.status not in ('ready', 'shipping', 'delivered') then raise check_violation using message = 'invalid_shipment_transition'; end if;
  perform pg_advisory_xact_lock(private.tracking_number_lock_key(carrier_value, tracking_value));
  conflict := private.tracking_number_conflict(carrier_value, tracking_value, scope, null);
  if conflict is null then raise check_violation using message = 'tracking_duplicate_not_needed'; end if;
  insert into private.tracking_duplicate_approvals(shipment_id, carrier, tracking_number, reason, conflict, actor_id)
  values (shipment.id, carrier_value, tracking_value, reason_value, conflict, actor)
  on conflict (shipment_id, carrier, tracking_number) do update
    set reason = excluded.reason, conflict = excluded.conflict, actor_id = excluded.actor_id, created_at = excluded.created_at;
  if shipment.status = 'ready' then
    perform public.admin_update_shipment_status(shipment.id, 'shipping', carrier_value, tracking_value); outcome := 'dispatched';
  else
    perform public.admin_update_shipment_tracking(shipment.id, carrier_value, tracking_value); outcome := 'corrected';
  end if;
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.shipment.tracking_duplicate_registered', 'order:' || shipment.order_id,
    jsonb_build_object('shipmentId', shipment.id, 'originName', shipment.origin_name_snapshot, 'carrier', carrier_value, 'trackingNumber', tracking_value,
      'reason', reason_value, 'outcome', outcome, 'fromTrackingNumber', shipment.tracking_number,
      'otherSource', conflict->>'source', 'otherOrderId', conflict->>'orderId', 'otherShipmentId', conflict->>'shipmentId'));
  return jsonb_build_object('status', outcome, 'shipmentId', shipment.id, 'orderId', shipment.order_id,
    'packedShipments', (select jsonb_agg(jsonb_build_object('shipmentId', s.id, 'orderId', s.order_id) order by s.id) from public.order_shipments s where s.id = any(scope)));
end $$

-- 7. 택배사 운송장 형식 편집(택배사 관리 화면, 최고 관리자). 형식과 안내 문구는 함께 저장·삭제하고, 형식을 둘 때는 확인용 번호가
--    공통 형식과 새 형식에 맞아야 저장한다(잘못된 식으로 모든 발송이 막히지 않게). 택배사 저장과 같은 잠금·충돌 검사·감사 기록이다.
create function public.admin_save_shipping_carrier_tracking_format(target_code text, target_pattern text, target_rule text, target_sample text,
  expected_updated_at timestamptz)
returns timestamptz language plpgsql security definer set search_path = '' as $format$
declare actor uuid := (select auth.uid()); previous public.shipping_carriers; saved public.shipping_carriers;
  code_value text := btrim(coalesce(target_code, '')); pattern_value text := nullif(btrim(coalesce(target_pattern, '')), '');
  rule_value text := nullif(btrim(coalesce(target_rule, '')), ''); sample_value text := private.normalize_tracking_number(target_sample);
begin
  perform private.require_operator_capability('platform.manage', true);
  if actor is null or not public.has_operator_capability('platform.manage', true) then raise insufficient_privilege using message = 'admin_required'; end if;
  if (pattern_value is null) <> (rule_value is null) or char_length(coalesce(pattern_value, '')) > 200 or char_length(coalesce(rule_value, '')) > 60
    or (pattern_value is not null and pattern_value !~ '^\^.+\$$') then
    raise invalid_parameter_value using message = 'invalid_tracking_number_format'; end if;
  if pattern_value is not null then
    begin
      if sample_value is null or sample_value !~ '^[A-Z0-9]{8,30}$' or not (sample_value ~ pattern_value) then
        raise invalid_parameter_value using message = 'tracking_number_format_sample_mismatch'; end if;
    exception when invalid_regular_expression then
      raise invalid_parameter_value using message = 'invalid_tracking_number_format';
    end;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('shipping_carrier:' || code_value, 0));
  select * into previous from public.shipping_carriers where code = code_value for update;
  if not found then raise no_data_found using message = 'shipping_carrier_not_found'; end if;
  if expected_updated_at is distinct from previous.updated_at then raise sqlstate 'PT409' using message = 'store_settings_conflict'; end if;
  update public.shipping_carriers set tracking_number_pattern = pattern_value, tracking_number_rule = rule_value
    where code = code_value returning * into saved;
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.shipping_carrier.saved', 'shipping_carriers:' || code_value,
    jsonb_build_object('before', to_jsonb(previous), 'after', to_jsonb(saved)));
  return saved.updated_at;
end $format$

-- 8. 운영자 계약. 바꾼 함수는 등록된 능력·분류를 그대로 두고 지문만 다시 적는다. 맞바꾸기·중복 확인 후 등록은 운송장 정정과 같은 출고
--    권한, 운송장 형식 편집은 택배사 저장과 같은 최고 관리자 권한이다.
do $contracts$
declare
  signature text;
  fn regprocedure;
  contract record;
begin
  foreach signature in array array[
    'public.admin_add_shipment_extra_tracking(uuid,text,text,text,uuid)',
    'public.admin_import_shipment_tracking_batch(jsonb)',
    'public.admin_import_warehouse_tracking_batch(uuid,jsonb)',
    'public.admin_import_seowon_tracking_batch(uuid,jsonb)'
  ] loop
    fn := signature::regprocedure;
    select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure = fn;
    if not found then raise exception 'tracking_integrity_contract_missing: %', signature; end if;
    perform private.register_operator_rpc_contract(fn, contract.capability, contract.guard_kind, contract.legacy_admin_only);
  end loop;
  foreach signature in array array[
    'public.admin_add_shipment_extra_tracking(uuid,text,text,text,uuid)',
    'public.admin_import_shipment_tracking_batch(jsonb)',
    'public.admin_import_warehouse_tracking_batch(uuid,jsonb)',
    'public.admin_import_seowon_tracking_batch(uuid,jsonb)',
    'private.admin_import_item_tracking_batch_before_identity_guard(jsonb)',
    'private.record_order_claim_shipment_reshipment(uuid,uuid,text,text,jsonb,jsonb)',
    'private.admin_update_shipment_status_before_delivery_methods(uuid,text,text,text)',
    'private.admin_update_shipment_tracking_before_delivery_methods(uuid,text,text)',
    'private.assert_reply_extra_trackings(jsonb)'
  ] loop
    fn := signature::regprocedure;
    if exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure = fn) then
      perform private.register_operator_internal_contract(fn);
    end if;
  end loop;
  perform private.register_operator_rpc_contract('public.admin_swap_shipment_trackings(uuid,text,text,text,text)'::regprocedure, 'sales.dispatch', 'write', false);
  perform private.register_operator_rpc_contract('public.admin_register_shipment_tracking_duplicate(uuid,text,text,text)'::regprocedure, 'sales.dispatch', 'write', false);
  perform private.register_operator_rpc_contract('public.admin_save_shipping_carrier_tracking_format(text,text,text,text,timestamp with time zone)'::regprocedure,
    'platform.manage', 'write', true);
end $contracts$

alter table public.goods add constraint goods_type_check check (
  type = any (array['', '피규어', '인형', '키링', '아크릴', '문구', '쿠션', '파우치', '세트', '기타'])
)

-- --------------------------------------------------------------------------
-- 3. 앵커 치환: 현재 정의에서 앵커가 정확히 한 번 나올 때만 바꾼다(다른 migration이 같은 줄을 고쳤으면 실패한다).
-- --------------------------------------------------------------------------
create function private.goods_type_retire_patch(p_function regprocedure, p_patches jsonb)
returns void
language plpgsql
volatile
set search_path = ''
as $helper$
declare
  v_definition text := pg_catalog.pg_get_functiondef(p_function);
  v_patch jsonb;
  v_found integer;
begin
  for v_patch in select value from pg_catalog.jsonb_array_elements(p_patches) loop
    v_found := (pg_catalog.length(v_definition) - pg_catalog.length(pg_catalog.replace(v_definition, v_patch->>0, '')))
      / pg_catalog.length(v_patch->>0);
    if v_found <> 1 then
      raise exception 'goods_type_retire_anchor_changed: % (% matches)', p_function, v_found;
    end if;
    v_definition := pg_catalog.replace(v_definition, v_patch->>0, v_patch->>1);
  end loop;
  execute v_definition;
end;
$helper$

-- 3-3. 카테고리 화면의 대표 분류 적용도 같은 규칙을 따른다.
select private.goods_type_retire_patch('private.admin_assign_good_category_before_additional(uuid,text,uuid,timestamp with time zone)'::regprocedure, jsonb_build_array(
  jsonb_build_array(
    $anchor$  good_published_at timestamptz;
  good_type text;
  next_type text;
$anchor$,
    $patched$  good_published_at timestamptz;
$patched$),
  jsonb_build_array(
    $anchor$  select updated_at, category_id, published_at, type into good_updated_at, good_category_id, good_published_at, good_type$anchor$,
    $patched$  select updated_at, category_id, published_at into good_updated_at, good_category_id, good_published_at$patched$),
  jsonb_build_array(
    $anchor$  -- SHEET-003: 공개 중에는 상품 유형이 바뀌는(연결 없음 포함) 카테고리로 옮길 수 없다. 초안 전환 후 바꾼다.
  if good_published_at is not null and good_category_id is distinct from target_category_id then
    next_type := private.goods_category_type(target_category_id);
    if next_type = '' then raise check_violation using message = 'goods_type_category_required'; end if;
    if next_type is distinct from good_type then raise check_violation using message = 'goods_type_category_locked'; end if;
  end if;
$anchor$,
    $patched$  -- ADR-0044: 공개 중 상품은 다른 대표 카테고리로 옮길 수 있지만 비울 수는 없다(공개 조건).
  if good_published_at is not null and good_category_id is not null and target_category_id is null then
    raise check_violation using message = 'goods_published_category_clear';
  end if;
$patched$)))

-- 3-4. 판매 준비: 유형 사유 3종(type_missing·type_category_mismatch·type_no_category)을 category_missing 하나로 바꾼다.
--      초안은 공개를 막고(blocking), 공개 중이면 검토 사유로 알린다.
select private.goods_type_retire_patch('private.admin_goods_readiness(public.goods)'::regprocedure, jsonb_build_array(
  jsonb_build_array(
    $anchor$  category_type text; type_review boolean := false; type_no_category boolean := false;$anchor$,
    $patched$  category_review boolean := false;$patched$),
  jsonb_build_array(
    $anchor$  -- SHEET-003(ADR-0037): 상품 유형은 대표 카테고리(없으면 가까운 상위)의 연결값이다.
  category_type:=private.goods_category_type(p_good.category_id);
  if p_good.published_at is null then
    if category_type='' then blockers:=array_append(blockers,'type_missing');
    elsif category_type is distinct from p_good.type then blockers:=array_append(blockers,'type_category_mismatch'); end if;
  elsif category_type is distinct from p_good.type then
    -- 대표 카테고리가 아예 없는 공개 상품은 '연결 안내'가 아니라 '대표 카테고리 지정'이 할 일이다.
    type_review:=true; type_no_category:=p_good.category_id is null;
  end if;
$anchor$,
    $patched$  -- ADR-0044: 상품 유형은 없다. 대표 카테고리가 있어야 공개하고, 공개 중인데 없으면 검토 사유로 알린다.
  if p_good.category_id is null then
    if p_good.published_at is null then blockers:=array_append(blockers,'category_missing');
    else category_review:=true; end if;
  end if;
$patched$),
  jsonb_build_array(
    $anchor$  if type_review then reasons:=array_append(reasons,case when type_no_category then 'type_no_category' else 'type_category_mismatch' end); end if;$anchor$,
    $patched$  if category_review then reasons:=array_append(reasons,'category_missing'); end if;$patched$)))

create function private.t7_patch_function(p_function regprocedure, p_pairs text[]) returns void
language plpgsql set search_path = '' as $$
declare definition text := pg_get_functiondef(p_function); i integer;
begin
  if array_length(p_pairs, 1) is null or array_length(p_pairs, 1) % 2 <> 0 then raise exception 't7 patch pairs'; end if;
  for i in 1 .. array_length(p_pairs, 1) / 2 loop
    if (length(definition) - length(replace(definition, p_pairs[2 * i - 1], ''))) / length(p_pairs[2 * i - 1]) <> 1 then
      raise exception '% anchor % must appear once', p_function, i;
    end if;
    definition := replace(definition, p_pairs[2 * i - 1], p_pairs[2 * i]);
  end loop;
  execute definition;
end $$

-- 시스템 상태 화면(platform.manage). STABLE — 잠금 없는 권한 판정만 쓴다.
create function public.admin_system_health() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if (select auth.uid()) is null or not public.has_operator_capability('platform.manage', false) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  return private.system_health_report();
end $$

-- 4. 결제 상태 다시 확인(운영자) --------------------------------------------------------------------------------------
-- 감사 기록을 남기고 서버 액션이 재정합 seam에 넘길 caseRef를 돌려준다. 같은 요청번호의 재요청은 같은 caseRef를 돌려준다
-- (재정합 자체가 멱등이다). 결제사 조회 남용을 막아 같은 시도는 1분에 한 번만 새로 확인한다.
create function public.admin_begin_payment_reconciliation(p_attempt_id uuid, p_operation_id uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare actor uuid; attempt public.payment_attempts; prior_row public.audit_log; case_ref text;
begin
  actor := private.require_operator_capability('sales.manage', false);
  if p_attempt_id is null or p_operation_id is null then
    raise invalid_parameter_value using message = 'invalid_payment_reconciliation';
  end if;
  case_ref := 'admin-' || replace(p_operation_id::text, '-', '');
  select * into prior_row from public.audit_log where id = p_operation_id;
  if found then
    if prior_row.action is distinct from 'admin.payment_attempt.reconcile_requested' or prior_row.actor_id is distinct from actor
      or prior_row.target is distinct from 'payment_attempt:' || p_attempt_id::text then
      raise unique_violation using message = 'payment_reconciliation_operation_conflict';
    end if;
  else
    select * into attempt from public.payment_attempts where id = p_attempt_id;
    if not found then raise no_data_found using message = 'payment_attempt_not_found'; end if;
    if not private.payment_attempt_unresolved(attempt.state, attempt.claim_expires_at, clock_timestamp()) then
      raise object_not_in_prerequisite_state using message = 'payment_attempt_not_unresolved';
    end if;
    if exists(select 1 from private.goods_payment_reconciliation_audits g where g.target_id = p_attempt_id and g.requested_at > clock_timestamp() - interval '1 minute')
      or exists(select 1 from private.ticket_payment_reconciliation_audits t where t.target_id = p_attempt_id and t.requested_at > clock_timestamp() - interval '1 minute') then
      raise object_not_in_prerequisite_state using message = 'payment_reconciliation_cooldown';
    end if;
    insert into public.audit_log(id, actor_id, action, target, diff)
    values (p_operation_id, actor, 'admin.payment_attempt.reconcile_requested', 'payment_attempt:' || attempt.id::text,
      jsonb_build_object('purpose', attempt.purpose, 'provider', attempt.provider, 'stateBefore', attempt.state,
        'refId', attempt.ref_id, 'caseRef', case_ref));
  end if;
  select * into attempt from public.payment_attempts where id = p_attempt_id;
  if not found then raise no_data_found using message = 'payment_attempt_not_found'; end if;
  return jsonb_build_object('attemptId', attempt.id, 'purpose', attempt.purpose, 'provider', attempt.provider,
    'state', attempt.state, 'refId', attempt.ref_id, 'caseRef', case_ref);
end $$

-- 6. 결제 기한 만료 sweep: 주문마다 예외를 가둔다 ----------------------------------------------------------------------
-- 한 주문의 오류(데이터 이상·트리거 거절)가 매분 sweep 전체(최대 200건)를 되돌려 다른 주문의 재고·쿠폰까지 묶던 것을 막는다.
-- 블록 안의 변경만 되돌아가고 그 주문은 다음 회차에 다시 본다. 건너뛴 건수·SQLSTATE·대상(주문 id)만 실패 기록에 남긴다.
select private.t7_patch_function('public.expire_stale_checkouts()'::regprocedure, array[
$a$  v_attempt public.payment_attempts%rowtype;
begin$a$,
$a$  v_attempt public.payment_attempts%rowtype;
  v_failed integer := 0;
  v_failed_state text;
  v_failed_refs text[] := array[]::text[];
begin$a$,
$a$    for update of orders skip locked
  loop
    v_can_expire := true;$a$,
$a$    for update of orders skip locked
  loop
  begin
    v_can_expire := true;$a$,
$a$    v_count := v_count + 1;
  end loop;

  -- Ticket checkout follows$a$,
$a$    v_count := v_count + 1;
  exception when others then
    get stacked diagnostics v_failed_state = returned_sqlstate;
    v_failed := v_failed + 1;
    if cardinality(v_failed_refs) < 5 then v_failed_refs := v_failed_refs || ('order:' || r.id::text); end if;
  end;
  end loop;

  -- Ticket checkout follows$a$,
$a$    for update of ticket_orders skip locked
  loop
    v_can_expire := true;$a$,
$a$    for update of ticket_orders skip locked
  loop
  begin
    v_can_expire := true;$a$,
$a$    v_count := v_count + 1;
  end loop;
  return v_count;$a$,
$a$    v_count := v_count + 1;
  exception when others then
    get stacked diagnostics v_failed_state = returned_sqlstate;
    v_failed := v_failed + 1;
    if cardinality(v_failed_refs) < 5 then v_failed_refs := v_failed_refs || ('ticket_order:' || r.id::text); end if;
  end;
  end loop;
  if v_failed > 0 then
    begin
      perform private.record_system_job_failure('expire-stale-checkouts', 'pg_cron', '결제 기한 만료 정리', null, null,
        'sqlstate_' || coalesce(v_failed_state, 'unknown'),
        pg_catalog.jsonb_build_object('skipped', v_failed, 'targets', pg_catalog.to_jsonb(v_failed_refs)));
    exception when others then
      raise warning 'expire_stale_checkouts skipped % rows; failure record unavailable', v_failed;
    end;
  end if;
  return v_count;$a$
])

-- 8. 정리 잡(10분): pg_cron 잡을 처음 본 시각을 남기고(새 잡의 멈춤 오탐 방지), 실패 기록 30일·30일 동안 실행이 없던 작업 상태 행·
--    미종결이 아닌 시도의 자동 재확인 표식을 지운다.
create function private.maintain_system_job_records() returns void
language plpgsql set search_path = '' as $$
begin
  insert into private.system_pg_cron_jobs(jobname, first_seen_at)
  select j.jobname, clock_timestamp() from cron.job j where j.jobname is not null
  on conflict (jobname) do nothing;
  delete from private.system_pg_cron_jobs s where not exists(select 1 from cron.job j where j.jobname = s.jobname);
  delete from private.system_job_failures where occurred_at < now() - interval '30 days';
  delete from private.system_job_status where updated_at < now() - interval '30 days';
  delete from private.payment_reconciliation_auto_checks m using public.payment_attempts a
  where a.id = m.attempt_id and not private.payment_attempt_unresolved(a.state, a.claim_expires_at, clock_timestamp());
end $$

do $$declare fn regprocedure; contract record; begin
  foreach fn in array array[
    'private.operator_alert_capability(text)'::regprocedure,
    'public.admin_operation_alerts(text,text,timestamp with time zone,uuid,integer)'::regprocedure,
    'public.admin_update_operation_alerts(text,uuid[],timestamp with time zone,text,text)'::regprocedure,
    'public.admin_operation_tasks()'::regprocedure,
    'public.expire_stale_checkouts()'::regprocedure] loop
    select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure = fn;
    if found then perform private.register_operator_rpc_contract(fn, contract.capability, contract.guard_kind, contract.legacy_admin_only);
    elsif exists(select 1 from private.operator_internal_contracts r where r.signature::regprocedure = fn) then
      perform private.register_operator_internal_contract(fn);
    end if;
  end loop;
end $$

create function private.t8_patch_function(p_signature text,p_anchor text,p_replacement text)
returns void language plpgsql volatile set search_path='' as $$
declare body text; found_count integer;
begin
  body:=pg_get_functiondef(p_signature::regprocedure);
  found_count:=(length(body)-length(replace(body,p_anchor,'')))/length(p_anchor);
  if found_count<>1 then raise exception 't8_anchor_changed: % (found %)',p_signature,found_count; end if;
  execute replace(body,p_anchor,p_replacement);
end $$

-- 지금 요청의 JWT가 이 사용자의 aal2 세션이고 그 세션 행도 아직 aal2로 살아 있는가.
create function private.operator_mfa_session_verified(p_actor uuid) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare claims jsonb:=(select auth.jwt()); session_text text;
begin
  if p_actor is null or claims is null or p_actor is distinct from (select auth.uid()) or claims->>'aal' is distinct from 'aal2' then return false; end if;
  session_text:=claims->>'session_id';
  if session_text is null or session_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return false; end if;
  return private.operator_mfa_session_ok(p_actor,session_text::uuid);
end $$

-- 운영자 판정을 막아야 하는가. 판정 대상이 지금 요청의 로그인 사용자이고 JWT 역할이 authenticated일 때만 막는다.
-- 스위치 행을 먼저 본다: 꺼져 있으면 JWT를 풀지 않고 바로 돌아간다(판정마다 붙는 비용을 PK 읽기 한 번으로 줄인다).
-- service_role이 사용자·세션을 인자로 넘기는 경로는 JWT가 없으므로 그 함수가 넘겨받은 세션을 operator_mfa_session_ok로 따로 본다.
create function private.operator_mfa_blocks(p_actor uuid) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare claims jsonb;
begin
  if p_actor is null or not exists(select 1 from private.operator_mfa_policy p where p.singleton and p.required) then return false; end if;
  claims:=(select auth.jwt());
  if claims is null or claims->>'role' is distinct from 'authenticated' or p_actor is distinct from (select auth.uid()) then return false; end if;
  return not private.operator_mfa_session_verified(p_actor);
end $$

-- 2. 공통 진입에 MFA 판정을 더한다. 능력이 있는 운영자에게만 스위치를 읽는다(고객·능력 없는 판정은 앞에서 false).
select private.t8_patch_function('private.has_operator_capability(uuid,text,boolean)',
$a$if access->>'mode'='legacy' and p_legacy_admin_only then$a$,
$a$-- 운영자 2단계 인증(OPS-006): 스위치가 켜지면 지금 요청의 aal2 세션만 운영자로 본다.
  if private.operator_mfa_blocks(p_actor) then return false; end if;
  if access->>'mode'='legacy' and p_legacy_admin_only then$a$)

select private.t8_patch_function('private.inquiry_file_session(uuid,uuid,boolean)',
$a$if p_staff then perform private.require_actor_operator_capability(p_actor,'cs.manage');end if;$a$,
$a$if p_staff then perform private.require_actor_operator_capability(p_actor,'cs.manage');
  if not private.operator_mfa_service_session_ok(p_actor,p_session) then raise insufficient_privilege using message='operator_mfa_required';end if;
 end if;$a$)

-- 3. 세션 끊기. auth.sessions를 지우면 refresh_tokens·mfa_amr_claims가 cascade로 지워진다.
create function private.operator_revoke_auth_sessions(p_user uuid) returns integer
language plpgsql volatile security definer set search_path='' as $$
declare removed integer;
begin
  if p_user is null then return 0; end if;
  delete from auth.sessions where user_id=p_user;
  get diagnostics removed=row_count;
  return removed;
end $$

-- 켜기: 켜는 사람의 지금 세션이 aal2여야 하고(본인부터 잠기지 않게), 운영자 전원이 TOTP를 등록해 있어야 한다.
-- 끄기: 켜진 동안에는 권한 가드가 이미 aal2를 요구한다. 2단계 인증 기기를 모두 잃은 비상 해제는 런북의 SQL로 한다.
create function public.admin_save_operator_mfa_policy(p_required boolean,p_expected_revision bigint,p_operation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid; previous private.operator_mfa_policy; saved private.operator_mfa_policy; request jsonb; receipt jsonb; unenrolled integer;
begin
  actor:=private.require_operator_capability('operators.manage',true);
  if p_required is null or p_expected_revision is null or p_expected_revision<1 or p_operation_id is null
    then raise invalid_parameter_value using message='invalid_operator_mfa_policy'; end if;
  request:=jsonb_build_object('required',p_required,'expectedRevision',p_expected_revision);
  perform pg_advisory_xact_lock(hashtextextended('operator-mfa-policy-operation:'||p_operation_id::text,0));
  receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.operator.mfa_policy',request);
  if receipt is not null then return receipt; end if;
  select * into previous from private.operator_mfa_policy where singleton for update;
  if not found then raise no_data_found using message='operator_mfa_policy_missing'; end if;
  if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='operator_mfa_policy_changed'; end if;
  if p_required and not previous.required then
    if not private.operator_mfa_session_verified(actor) then raise insufficient_privilege using message='operator_mfa_self_required'; end if;
    select count(*) into unenrolled from public.profiles p
    where p.role in ('staff','admin') and private.operator_access_for(p.id)->>'mode'<>'none'
      and not exists(select 1 from auth.mfa_factors f where f.user_id=p.id and f.status::text='verified' and f.factor_type::text='totp');
    if unenrolled>0 then raise invalid_parameter_value using message='operator_mfa_unenrolled', detail=unenrolled::text; end if;
  end if;
  update private.operator_mfa_policy set required=p_required,revision=revision+1,updated_by=actor,updated_at=clock_timestamp()
    where singleton returning * into saved;
  receipt:=jsonb_build_object('required',saved.required,'revision',saved.revision,'updatedAt',saved.updated_at);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.operator.mfa_policy','operator_mfa_policy',
    jsonb_build_object('request',request,'before',jsonb_build_object('required',previous.required,'revision',previous.revision),'result',receipt));
  return receipt;
end $$

-- 기기 분실 초기화: 최고 관리자(통합 매니저, 전환 전에는 admin)만. 본인은 내 보안 설정에서 직접 바꾼다.
-- 대상의 로그인 세션을 모두 끊고 감사 기록을 남긴다. 요소 삭제는 앱 서버가 이 RPC 성공 뒤 admin API로 하고, 삭제 뒤 같은 요청 ID로
-- 한 번 더 불러 그 사이 생긴 세션까지 끊는다(실패하면 같은 요청 ID로 다시 불러 같은 기록을 받고 삭제를 다시 시도한다).
create function public.admin_reset_operator_mfa(p_profile_id uuid,p_operation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid; request jsonb; receipt jsonb; factor_count integer; revoked integer;
begin
  actor:=private.require_operator_capability('operators.manage',true);
  if p_profile_id is null or p_operation_id is null then raise invalid_parameter_value using message='invalid_operator_mfa_reset'; end if;
  request:=jsonb_build_object('profileId',p_profile_id);
  perform pg_advisory_xact_lock(hashtextextended('operator-mfa-reset-operation:'||p_operation_id::text,0));
  if private.operator_access_for(actor)->>'mode'='configured'
    and not exists(select 1 from private.operator_memberships m where m.profile_id=actor and m.manager_role='owner')
    then raise insufficient_privilege using message='operator_mfa_reset_owner_only'; end if;
  receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.operator.mfa_reset',request);
  if receipt is not null then
    -- 같은 요청의 재시도와 요소 삭제 뒤 마무리 호출도 세션을 다시 끊는다. 첫 시도와 요소 삭제 사이에 새로 만든 세션을 남기지 않는다.
    perform private.operator_revoke_auth_sessions(p_profile_id);
    return receipt;
  end if;
  if p_profile_id=actor then raise insufficient_privilege using message='operator_self_change_denied'; end if;
  if not exists(select 1 from public.profiles p where p.id=p_profile_id and p.role in ('staff','admin'))
    then raise invalid_parameter_value using message='operator_mfa_reset_target_invalid'; end if;
  select count(*) into factor_count from auth.mfa_factors f where f.user_id=p_profile_id;
  revoked:=private.operator_revoke_auth_sessions(p_profile_id);
  receipt:=jsonb_build_object('profileId',p_profile_id,'factorCount',factor_count,'sessionsRevoked',revoked);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.operator.mfa_reset','profile:'||p_profile_id::text,
    jsonb_build_object('request',request,'result',receipt));
  return receipt;
end $$

-- 4-1. 성능: 운영자 판정을 행마다 부르던 RLS 정책을 initplan(`(select ...)`)으로 감싸 문장마다 한 번만 판정한다.
-- 감싼 판정은 모두 상수 능력 이름만 받아 행에 의존하지 않는다. 판정 결과는 요청 JWT로 정해져 한 문장 안에서 바뀌지 않는다.
-- 정책 본문은 deparse한 식에서 판정 호출만 바꾸고(나머지 식은 그대로), 운영자 RLS 계약 지문을 기존 능력값으로 다시 적는다.
do $policies$
declare
  item record; qual text; check_expr text; next_qual text; next_check text; changed integer:=0;
  call_pattern constant text:='has_operator_capability\(('||chr(39)||'[a-z._]+'||chr(39)||'::text)(, (true|false))?\)';
begin
  for item in select c.oid as relid,n.nspname,c.relname,p.polname,p.polqual,p.polwithcheck,k.capability
    from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
    left join private.operator_policy_contracts k on k.schema_name=n.nspname and k.table_name=c.relname and k.policy_name=p.polname
    where (n.nspname,c.relname,p.polname) in (
      ('public','admin_goods_drafts','admin_goods_drafts_owner_read'),
      ('public','coupon_redemptions','coupon_redemptions_select_own_or_staff'),
      ('public','coupons','coupons_select_held_or_staff'),
      ('public','goods_announcement_goods','goods_announcement_goods_staff_read'),
      ('public','goods_announcements','goods_announcements_staff_read'),
      ('public','goods_photo_library','goods_photo_library_staff_read'),
      ('public','goods_relation_hotspots','goods_relation_hotspots_operator_read'),
      ('public','home_curations','home_curations_staff_read'),
      ('public','loyalty_grade_events','loyalty_grade_events_select_own_or_staff'),
      ('public','order_cancellation_requests','gift_claims_private_read'),
      ('public','order_claim_collections','order_claim_collections_owner_staff'),
      ('public','order_shipment_email_jobs','shipment_email_jobs_staff_read'),
      ('public','order_shipment_extra_trackings','order_shipment_extra_trackings_owner_staff_read'),
      ('public','order_shipment_items','shipment_items_owner_staff_read'),
      ('public','order_shipments','shipments_owner_staff_read'),
      ('public','shopping_stories','shopping_stories_operator_read'),
      ('public','shopping_story_goods','shopping_story_goods_operator_read'),
      ('public','shopping_story_sections','shopping_story_sections_operator_read'),
      ('public','user_coupons','user_coupons_select_own_or_staff'))
  loop
    if item.capability is null then raise exception 't8_policy_contract_missing: %.%',item.relname,item.polname; end if;
    qual:=pg_get_expr(item.polqual,item.relid); check_expr:=pg_get_expr(item.polwithcheck,item.relid);
    if coalesce(qual,'')||coalesce(check_expr,'') ~ 'SELECT has_operator_capability' then
      raise exception 't8_policy_already_wrapped: %.%',item.relname,item.polname; end if;
    next_qual:=regexp_replace(qual,call_pattern,'( SELECT has_operator_capability(\1\2) AS has_operator_capability)','g');
    next_check:=regexp_replace(check_expr,call_pattern,'( SELECT has_operator_capability(\1\2) AS has_operator_capability)','g');
    if next_qual is not distinct from qual and next_check is not distinct from check_expr then
      raise exception 't8_policy_anchor_changed: %.%',item.relname,item.polname; end if;
    execute format('alter policy %I on %I.%I',item.polname,item.nspname,item.relname)
      ||case when next_qual is not null then format(' using (%s)',next_qual) else '' end
      ||case when next_check is not null then format(' with check (%s)',next_check) else '' end;
    perform private.register_operator_policy_contract(item.relid::regclass,item.polname,item.capability);
    changed:=changed+1;
  end loop;
  if changed<>19 then raise exception 't8_policy_count_changed: %',changed; end if;

  -- 상품 엑셀 반입 읽기 정책은 앞 판정이 이미 감싸져 있고, EXISTS 안의 관리자 판정 하나만 남아 있다.
  select c.oid,p.polname,p.polqual,k.capability into item
    from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
    join private.operator_policy_contracts k on k.schema_name=n.nspname and k.table_name=c.relname and k.policy_name=p.polname
    where n.nspname='public' and c.relname='admin_goods_imports' and p.polname='admin_goods_imports_owner_read' and p.polwithcheck is null;
  if not found then raise exception 't8_policy_contract_missing: admin_goods_imports_owner_read'; end if;
  qual:=pg_get_expr(item.polqual,item.oid);
  if (length(qual)-length(replace(qual,'AND has_operator_capability(''platform.manage''::text, true))','')))
    /length('AND has_operator_capability(''platform.manage''::text, true))')<>1 then
    raise exception 't8_policy_anchor_changed: admin_goods_imports_owner_read'; end if;
  next_qual:=replace(qual,'AND has_operator_capability(''platform.manage''::text, true))',
    'AND ( SELECT has_operator_capability(''platform.manage''::text, true) AS has_operator_capability))');
  execute format('alter policy admin_goods_imports_owner_read on public.admin_goods_imports using (%s)',next_qual);
  perform private.register_operator_policy_contract('public.admin_goods_imports'::regclass,'admin_goods_imports_owner_read',item.capability);
end $policies$

create function private.guard_pii_access_log_change()
returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_op = 'DELETE' and old.accessed_at < now() - private.pii_access_log_retention() then
    return old;
  end if;
  raise insufficient_privilege using message = 'pii_access_log_append_only';
end $$

create trigger operator_pii_access_log_append_only
  before update or delete on private.operator_pii_access_log
  for each row execute function private.guard_pii_access_log_change()

create trigger operator_pii_access_log_no_truncate
  before truncate on private.operator_pii_access_log
  for each statement execute function private.guard_pii_access_log_truncate()

-- 기록. 서버(서비스 키)만 부른다. 행위자는 서버가 확인한 로그인 계정이고, 열람이 이미 일어난 뒤의 기록이라 권한을 다시
-- 판정해 거절하지 않는다(권한이 바뀐 직후의 열람도 남아야 한다). 계정이 실제로 있는지만 본다.
create function public.service_record_operator_pii_access(
  p_actor_id uuid,
  p_action text,
  p_surface text,
  p_path text,
  p_client_ip inet,
  p_subject_kind text,
  p_subject_ids uuid[],
  p_subject_count integer,
  p_detail jsonb
) returns bigint
language plpgsql volatile security definer set search_path = '' as $$
declare
  actor public.profiles;
  access jsonb;
  access_label text;
  ids uuid[];
  members uuid[] := '{}';
  order_ids uuid[] := '{}';
  print text;
  existing bigint;
  recorded bigint;
begin
  select * into actor from public.profiles where id = p_actor_id;
  if p_actor_id is null or not found then
    raise insufficient_privilege using message = 'pii_access_actor_invalid';
  end if;
  if p_action is null or p_action not in ('view', 'search', 'export', 'reveal', 'correct') then
    raise invalid_parameter_value using message = 'pii_access_action_invalid';
  end if;
  if p_surface is null or p_surface !~ '^[a-z][a-z_]{0,31}([.][a-z][a-z_]{0,31}){0,2}$' then
    raise invalid_parameter_value using message = 'pii_access_surface_invalid';
  end if;
  if p_path is null or length(p_path) > 300 or p_path !~ '^/(admin|api/admin)(/[A-Za-z0-9._~%-]+)*$' then
    raise invalid_parameter_value using message = 'pii_access_path_invalid';
  end if;
  if p_subject_kind is null or p_subject_kind not in ('member', 'order', 'claim', 'shipment', 'gift', 'review', 'none') then
    raise invalid_parameter_value using message = 'pii_access_subject_invalid';
  end if;
  if p_subject_ids is not null and array_position(p_subject_ids, null) is not null then
    raise invalid_parameter_value using message = 'pii_access_subject_invalid';
  end if;
  select coalesce(array_agg(distinct s order by s), '{}') into ids from unnest(coalesce(p_subject_ids, '{}')) s;
  if cardinality(ids) > 1000 or p_subject_count is null or p_subject_count < cardinality(ids) or p_subject_count > 1000000
    or (p_subject_kind = 'none' and (cardinality(ids) > 0 or p_subject_count > 0)) then
    raise invalid_parameter_value using message = 'pii_access_subject_invalid';
  end if;
  -- 상세 값은 짧은 코드·숫자·참값만(화면 id·검색 유형·건수·감사 ID). 개인정보 원문이 들어올 길을 좁힌다.
  if p_detail is null or jsonb_typeof(p_detail) <> 'object' or octet_length(p_detail::text) > 2000
    or exists (
      select 1 from jsonb_each(p_detail) d
      where d.key !~ '^[a-z][A-Za-z0-9]{0,39}$'
        or jsonb_typeof(d.value) not in ('string', 'number', 'boolean', 'null')
        or (jsonb_typeof(d.value) = 'string' and length(d.value #>> '{}') > 120)
    ) then
    raise invalid_parameter_value using message = 'pii_access_detail_invalid';
  end if;

  -- 대상의 회원: 주문·클레임·배송 건은 그 주문의 구매자와 선물 주문이면 받는 사람(배송지·연락처의 주인), 선물은 보낸 사람·받는 사람,
  -- 리뷰는 작성자. '이 회원의 정보를 누가 봤나'를 member_ids 하나로 찾는다(대상 1,000개에서 최대 2,000명).
  order_ids := case p_subject_kind
    when 'order' then ids
    when 'claim' then (select coalesce(array_agg(distinct c.order_id), '{}') from public.order_cancellation_requests c where c.id = any(ids))
    when 'shipment' then (select coalesce(array_agg(distinct s.order_id), '{}') from public.order_shipments s where s.id = any(ids))
    else '{}'::uuid[] end;
  members := case p_subject_kind
    when 'member' then ids
    when 'gift' then (select coalesce(array_agg(distinct m.id order by m.id), '{}')
      from private.gift_intents g cross join lateral unnest(array[g.sender_id, g.recipient_id]) as m(id)
      where g.id = any(ids) and m.id is not null)
    when 'review' then (select coalesce(array_agg(distinct r.user_id order by r.user_id), '{}') from public.reviews r
      where r.id = any(ids) and r.user_id is not null)
    else (select coalesce(array_agg(distinct x.id order by x.id), '{}') from (
        select o.user_id as id from public.orders o where o.id = any(order_ids)
        union select g.recipient_id from private.gift_intents g where g.order_id = any(order_ids)
      ) as x where x.id is not null)
    end;
  members := members[1:2000];

  access := private.operator_access_for(p_actor_id);
  access_label := case access->>'mode'
    when 'configured' then coalesce(access->>'managerRole', 'none')
    when 'legacy' then 'legacy_' || actor.role::text
    else 'none' end;

  print := md5(concat_ws('|', p_action, p_surface, p_path, p_subject_kind, ids::text, p_subject_count::text,
    p_detail::text, coalesce(host(p_client_ip), '')));
  if p_action in ('view', 'search') then
    select l.id into existing from private.operator_pii_access_log l
    where l.actor_id = p_actor_id and l.fingerprint = print and l.accessed_at > clock_timestamp() - interval '10 minutes'
    order by l.accessed_at desc, l.id desc limit 1;
    if found then
      return existing;
    end if;
  end if;

  insert into private.operator_pii_access_log (actor_id, actor_access, client_ip, action, surface, path, subject_kind,
    subject_ids, subject_count, member_ids, detail, fingerprint)
  values (p_actor_id, access_label, p_client_ip, p_action, p_surface, p_path, p_subject_kind,
    ids, p_subject_count, members, p_detail, print)
  returning id into recorded;
  return recorded;
end $$

create function private.validate_pii_access_log_filters(
  p_from date, p_to date, p_action text, p_surface text, p_flag text
) returns void language plpgsql immutable set search_path = '' as $$
begin
  if p_from is null or p_to is null or p_from > p_to or p_to - p_from > 366 then
    raise invalid_parameter_value using message = 'pii_access_log_range_invalid';
  end if;
  if (p_action is not null and p_action not in ('view', 'search', 'export', 'reveal', 'correct'))
    or (p_surface is not null and p_surface !~ '^[a-z][a-z_]{0,31}([.][a-z][a-z_]{0,31}){0,2}$')
    or (p_flag is not null and p_flag not in ('any', 'off_hours', 'bulk', 'burst')) then
    raise invalid_parameter_value using message = 'pii_access_log_filter_invalid';
  end if;
end $$

-- 점검 화면 목록(50건씩, 최신순)과 같은 조건의 이상 징후 건수, 그 기간에 기록이 있는 운영자 목록.
create function public.admin_pii_access_log(
  p_from date, p_to date, p_actor uuid default null, p_action text default null, p_surface text default null,
  p_subject uuid default null, p_flag text default null, p_page integer default 1
) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  page_size constant integer := 50;
  total bigint;
  page integer;
  items jsonb;
  summary jsonb;
  actors jsonb;
begin
  if not public.has_operator_capability('operators.manage', true) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  perform private.validate_pii_access_log_filters(p_from, p_to, p_action, p_surface, p_flag);

  select jsonb_build_object(
      'total', count(*),
      'offHours', count(*) filter (where e.off_hours),
      'bulk', count(*) filter (where e.bulk),
      'burst', count(*) filter (where e.burst),
      'flagged', count(*) filter (where e.off_hours or e.bulk or e.burst))
  into summary
  from private.pii_access_log_entries(p_from, p_to, p_actor, p_action, p_surface, p_subject, null) e;

  select count(*) into total from private.pii_access_log_entries(p_from, p_to, p_actor, p_action, p_surface, p_subject, p_flag);
  page := least(greatest(coalesce(p_page, 1), 1), greatest(1, ((total + page_size - 1) / page_size))::integer);

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', e.id::text,
      'at', e.accessed_at,
      'actorId', e.actor_id,
      'actorName', private.pii_access_log_actor_name(e.actor_id),
      'actorAccess', e.actor_access,
      'ip', host(e.client_ip),
      'action', e.action,
      'surface', e.surface,
      'path', e.path,
      'subjectKind', e.subject_kind,
      'subjectIds', to_jsonb(e.subject_ids[1:5]),
      'subjectCount', e.subject_count,
      'memberIds', to_jsonb(e.member_ids[1:5]),
      'memberCount', cardinality(e.member_ids),
      'detail', e.detail,
      'flags', to_jsonb(array_remove(array[
        case when e.off_hours then 'off_hours' end,
        case when e.bulk then 'bulk' end,
        case when e.burst then 'burst' end], null))
    ) order by e.accessed_at desc, e.id desc), '[]'::jsonb)
  into items
  from (
    select * from private.pii_access_log_entries(p_from, p_to, p_actor, p_action, p_surface, p_subject, p_flag) x
    order by x.accessed_at desc, x.id desc
    limit page_size offset (page - 1) * page_size
  ) e;

  select coalesce(jsonb_agg(jsonb_build_object('id', a.actor_id, 'name', private.pii_access_log_actor_name(a.actor_id),
      'count', a.entries) order by a.entries desc, a.actor_id), '[]'::jsonb)
  into actors
  from (
    select e.actor_id, count(*) as entries
    from private.pii_access_log_entries(p_from, p_to, null, null, null, null, null) e
    group by e.actor_id
  ) a;

  return jsonb_build_object('from', p_from, 'to', p_to, 'page', page, 'pageSize', page_size, 'total', total,
    'summary', summary, 'items', items, 'actors', actors);
end $$

-- 보관 기간이 지난 기록 정리. 삭제 트리거가 같은 기준으로 그 행만 통과시킨다.
create function private.purge_pii_access_log()
returns integer language plpgsql security definer set search_path = '' as $$
declare removed integer;
begin
  delete from private.operator_pii_access_log where accessed_at < now() - private.pii_access_log_retention();
  get diagnostics removed = row_count;
  return removed;
end $$

-- ERP 데이터 읽기(20261109120000)는 public·private의 업무 표를 모두 내보낸다. 접속기록은 운영자 IP·열람 대상을 담은 보안 기록이라
-- ERP 읽기 접근 기록처럼 내보내지 않는다. 다른 제외 표를 건드리지 않게 마지막 이름 뒤에만 덧붙인다.
do $patch$
declare
  definition text := pg_get_functiondef('private.erp_read_tables()'::regprocedure);
  anchor constant text := $a$'erp_read_access_rollup'$a$;
begin
  if (length(definition) - length(replace(definition, anchor, ''))) / length(anchor) <> 1 then
    raise exception 'erp_read_tables anchor must appear once';
  end if;
  execute replace(definition, anchor, $r$'erp_read_access_rollup', 'operator_pii_access_log'$r$);
end $patch$

create function private.t10_withdrawal_patch_function(p_function regprocedure, p_pairs text[]) returns void
language plpgsql set search_path = '' as $$
declare definition text := pg_get_functiondef(p_function); i integer;
begin
  if array_length(p_pairs, 1) is null or array_length(p_pairs, 1) % 2 <> 0 then raise exception 't10 withdrawal patch pairs'; end if;
  for i in 1 .. array_length(p_pairs, 1) / 2 loop
    if (length(definition) - length(replace(definition, p_pairs[2 * i - 1], ''))) / length(p_pairs[2 * i - 1]) <> 1 then
      raise exception '% anchor % must appear once', p_function, i;
    end if;
    definition := replace(definition, p_pairs[2 * i - 1], p_pairs[2 * i]);
  end loop;
  execute definition;
end $$

-- 3. 로그인 세션 종료. 세션 행을 지우면 refresh token·MFA 기록이 함께 지워지고(외래키 cascade) Auth의 사용자 조회가
--    'session_not_found'로 실패한다. 세션 없는 옛 refresh token도 지운다. 이미 발급된 access token은 만료(기본 1시간)까지
--    PostgREST에서 유효하다 — 그동안 정지를 확인하는 쓰기(구매·예매·작성·카드팩 개봉·게임, 마케팅 새 동의·재입고 알림 신청
--    (20261118165100), 계정 유형이 아닌 문의)는 거절되지만 위시처럼 정지를 확인하지 않는 본인 행 쓰기는 만료 전까지 될 수 있다.
--    지운 세션 수를 돌려준다.
create function private.revoke_member_auth_sessions(p_user_id uuid) returns integer
language plpgsql volatile security definer set search_path = '' as $$
declare revoked integer;
begin
  if p_user_id is null then raise invalid_parameter_value using message = 'member_withdrawal_member_required'; end if;
  delete from auth.refresh_tokens where user_id = p_user_id::text and session_id is null;
  delete from auth.sessions where user_id = p_user_id;
  get diagnostics revoked = row_count;
  return revoked;
end $$

-- 5. 처리. 잠금 순서는 정지와 같다(운영자·대상 계정 행동 잠금 → 프로필 → 각 저장소 잠금).
create function public.admin_process_member_withdrawal(target_profile_id uuid, target_inquiry_reference bigint, target_note text)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  actor uuid := (select auth.uid());
  note text := pg_catalog.btrim(coalesce(target_note, ''), E' \t\n\r\f\v');
  inquiry_owner uuid;
  blockers jsonb;
  suspension jsonb;
  changed_at timestamptz;
  consent record;
  revoked integer;
  erased_address integer;
  erased_phone integer;
  withdrawn_marketing integer := 0;
  erased_demographics integer;
  erased_activity_events integer;
  withdrawn_activity integer;
  erased_email_changes integer;
  erased_restock_alerts integer;
  erased jsonb;
begin
  perform private.lock_operator_subjects(array[actor, target_profile_id]);
  perform private.require_operator_capability('platform.manage', false);

  if target_profile_id is null or target_inquiry_reference is null or target_inquiry_reference < 1
    or pg_catalog.char_length(note) not between 2 and 200 or pg_catalog.translate(note, E'\n\t', '') ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message = 'invalid_member_withdrawal';
  end if;
  if target_profile_id = actor then
    raise exception 'cannot_withdraw_self' using errcode = '22023';
  end if;
  if not exists (select 1 from public.profiles p where p.id = target_profile_id) then
    raise exception 'profile_not_found' using errcode = 'P0002';
  end if;

  -- 이미 처리한 회원: 처음 기록을 돌려준다. 재로그인 차단 전에 다시 로그인했을 수 있어 세션만 다시 끊는다.
  if exists (select 1 from private.member_withdrawal_processings w where w.user_id = target_profile_id) then
    revoked := private.revoke_member_auth_sessions(target_profile_id);
    return private.member_withdrawal_document(target_profile_id)
      || jsonb_build_object('status', 'already_processed', 'revokedSessions', revoked);
  end if;

  select i.user_id into inquiry_owner from public.inquiries i where i.reference = target_inquiry_reference;
  if inquiry_owner is null or inquiry_owner <> target_profile_id then
    raise no_data_found using message = 'member_withdrawal_inquiry_not_found';
  end if;

  -- 탈퇴 신청과 같은 진행 중 의무 판정. 운영자 소속(매니저 역할)은 프로필 역할과 별개라 따로 본다.
  blockers := private.account_deletion_blockers(target_profile_id);
  if exists (select 1 from private.operator_memberships m where m.profile_id = target_profile_id)
    and not blockers @> '[{"code":"staff_handover"}]'::jsonb then
    blockers := blockers || jsonb_build_array(jsonb_build_object('code', 'staff_handover', 'count', 1, 'path', '/settings'));
  end if;
  if blockers <> '[]'::jsonb then
    return jsonb_build_object('status', 'blocked', 'blockers', blockers);
  end if;

  suspension := public.admin_suspend_user(target_profile_id,
    pg_catalog.left('탈퇴 요청 처리 · 문의 #' || target_inquiry_reference::text || ' · ' || note, 200));
  changed_at := pg_catalog.clock_timestamp();

  erased_address := private.erase_member_address_book(target_profile_id);
  erased_phone := private.erase_member_phone(target_profile_id);

  -- 마케팅 정보 수신 동의: 동의 중인 수단마다 철회를 원장에 남기고 파생값을 맞춘다(원장 먼저 — 동기화 트리거는 같으면 아무것도 하지 않는다).
  for consent in
    select c.channel, c.notice_version from private.customer_marketing_consents c
    where c.user_id = target_profile_id and c.agreed order by c.channel
  loop
    perform private.write_customer_marketing_consent(target_profile_id, consent.channel, false, consent.notice_version,
      'member_withdrawal', changed_at);
    withdrawn_marketing := withdrawn_marketing + 1;
  end loop;
  update public.profiles set consents = jsonb_set(coalesce(consents, '{}'::jsonb), '{marketing}', 'false'::jsonb, true)
  where id = target_profile_id and consents->'marketing' is distinct from 'false'::jsonb;

  -- 탈퇴 봉인 트리거(erase_fenced_customer_demographics·member_activity_fenced·erase_fenced_member_email_change)와 같은 범위.
  update private.customer_demographic_consents
  set choice = 'declined', gender = null, accepted_at = null, revision = revision + 1, updated_at = changed_at
  where user_id = target_profile_id and choice = 'accepted';
  get diagnostics erased_demographics = row_count;
  delete from private.member_activity_events where user_id = target_profile_id;
  get diagnostics erased_activity_events = row_count;
  update private.member_activity_consents
  set choice = 'declined', accepted_at = null, revision = revision + 1, updated_at = changed_at
  where user_id = target_profile_id and choice = 'accepted';
  get diagnostics withdrawn_activity = row_count;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-email:user:' || target_profile_id::text, 0));
  delete from private.member_email_change_challenges where user_id = target_profile_id;
  get diagnostics erased_email_changes = row_count;
  -- 재입고 알림은 정지와 무관하게 메일·알림을 보내므로 아직 알리지 않은(대기) 신청을 지운다. 알린 기록(발송 이력)은 남긴다.
  delete from public.restock_alerts where user_id = target_profile_id and status = 'pending';
  get diagnostics erased_restock_alerts = row_count;

  revoked := private.revoke_member_auth_sessions(target_profile_id);
  erased := jsonb_build_object(
    'addressBookEntries', erased_address,
    'phoneNumbers', erased_phone,
    'marketingConsents', withdrawn_marketing,
    'demographicConsents', erased_demographics,
    'activityEvents', erased_activity_events,
    'activityConsents', withdrawn_activity,
    'emailChangeRequests', erased_email_changes,
    'restockAlerts', erased_restock_alerts);

  insert into private.member_withdrawal_processings (user_id, inquiry_reference, processed_by, processed_at)
  values (target_profile_id, target_inquiry_reference, actor, changed_at);
  insert into public.audit_log (actor_id, action, target, diff)
  values (actor, 'admin.member.withdrawal_processed', 'profile:' || target_profile_id::text, jsonb_build_object(
    'inquiryReference', target_inquiry_reference,
    'suspended', coalesce((suspension->>'changed')::boolean, false),
    'erased', erased,
    'revokedSessions', revoked));

  return private.member_withdrawal_document(target_profile_id) || jsonb_build_object(
    'status', 'processed',
    'suspended', coalesce((suspension->>'changed')::boolean, false),
    'erased', erased,
    'revokedSessions', revoked);
end $$

-- 6. 재로그인 차단 확인. 앱 서버가 Auth 관리 API로 차단(ban)을 적용한 뒤 부른다. 앱의 말을 믿지 않고 auth.users.banned_until을
--    직접 읽어 장기 차단이 걸려 있을 때만 기록·감사한다. 차단 직전에 생긴 세션도 다시 끊는다. 이미 확인했으면 그 기록을 돌려준다.
create function public.admin_confirm_member_withdrawal_signin_block(target_profile_id uuid)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  actor uuid := (select auth.uid());
  processing private.member_withdrawal_processings;
  banned timestamptz;
  revoked integer;
  confirmed_at timestamptz;
begin
  perform private.lock_operator_subjects(array[actor, target_profile_id]);
  perform private.require_operator_capability('platform.manage', false);
  if target_profile_id is null then raise invalid_parameter_value using message = 'invalid_member_withdrawal'; end if;

  select * into processing from private.member_withdrawal_processings w where w.user_id = target_profile_id for update;
  if not found then raise no_data_found using message = 'member_withdrawal_not_processed'; end if;
  if processing.signin_blocked_at is not null then
    return private.member_withdrawal_document(target_profile_id) || jsonb_build_object('replayed', true, 'revokedSessions', 0);
  end if;

  select u.banned_until into banned from auth.users u where u.id = target_profile_id;
  if banned is null or banned < pg_catalog.clock_timestamp() + interval '50 years' then
    raise check_violation using message = 'member_withdrawal_signin_not_blocked';
  end if;

  revoked := private.revoke_member_auth_sessions(target_profile_id);
  confirmed_at := greatest(pg_catalog.clock_timestamp(), processing.processed_at);
  update private.member_withdrawal_processings
  set signin_blocked_at = confirmed_at, signin_blocked_by = actor
  where user_id = target_profile_id;
  insert into public.audit_log (actor_id, action, target, diff)
  values (actor, 'admin.member.withdrawal_signin_blocked', 'profile:' || target_profile_id::text,
    jsonb_build_object('inquiryReference', processing.inquiry_reference, 'revokedSessions', revoked));
  return private.member_withdrawal_document(target_profile_id) || jsonb_build_object('replayed', false, 'revokedSessions', revoked);
end $$

-- 7. 고객 상세가 읽는 처리 상태. STABLE이라 PostgREST가 READ ONLY 트랜잭션으로 부른다 — 잠그는 권한 검사를 쓰지 않는다.
create function public.admin_member_withdrawal_status(target_profile_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null or not public.has_operator_capability('platform.manage', false) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  if target_profile_id is null then raise invalid_parameter_value using message = 'invalid_member_withdrawal'; end if;
  return private.member_withdrawal_document(target_profile_id);
end $$

-- 8. 탈퇴 처리한 계정은 정지를 풀지 않는다(지운 정보는 돌아오지 않고, 처리 기록과 계정 상태가 어긋난다).
select private.t10_withdrawal_patch_function('public.admin_unsuspend_user(uuid)'::regprocedure, array[
$a$  if selected_suspended_at is null then$a$,
$a$  if exists(select 1 from private.member_withdrawal_processings w where w.user_id = target_profile_id) then
    raise exception 'member_withdrawn' using errcode = '22023';
  end if;

  if selected_suspended_at is null then$a$
])

do $$declare contract record; begin
  select * into contract from private.operator_rpc_contracts r where r.signature::regprocedure = 'public.admin_unsuspend_user(uuid)'::regprocedure;
  if not found then raise exception 'admin_unsuspend_user contract missing'; end if;
  perform private.register_operator_rpc_contract('public.admin_unsuspend_user(uuid)'::regprocedure, contract.capability, contract.guard_kind, contract.legacy_admin_only);
end $$

create function private.t10_followup_patch_function(p_function regprocedure, p_pairs text[]) returns void
language plpgsql set search_path = '' as $$
declare definition text := pg_get_functiondef(p_function); i integer;
begin
  if array_length(p_pairs, 1) is null or array_length(p_pairs, 1) % 2 <> 0 then raise exception 't10 followup patch pairs'; end if;
  for i in 1 .. array_length(p_pairs, 1) / 2 loop
    if (length(definition) - length(replace(definition, p_pairs[2 * i - 1], ''))) / length(p_pairs[2 * i - 1]) <> 1 then
      raise exception '% anchor % must appear once', p_function, i;
    end if;
    definition := replace(definition, p_pairs[2 * i - 1], p_pairs[2 * i]);
  end loop;
  execute definition;
end $$

-- 1-b. 이어 쓰기: 정지 회원은 자기 계정 문의에만, 첨부 없이 이어 쓴다.
select private.t10_followup_patch_function('public.append_inquiry_message(uuid,text,text[])'::regprocedure, array[
$a$  if v_status = 'closed' then$a$,
$a$  -- 정지 회원은 계정 문의(탈퇴 요청·정지 문의)에만 글로 이어 쓴다.
  if exists (select 1 from public.profiles as profile where profile.id = v_actor and profile.suspended_at is not null) then
    if (select thread.category from public.inquiries as thread where thread.id = target_inquiry_id) <> 'account' then
      raise insufficient_privilege using message = 'account_suspended';
    end if;
    if cardinality(coalesce(target_image_paths, '{}'::text[])) > 0 then
      raise insufficient_privilege using message = 'account_suspended_inquiry_limited';
    end if;
  end if;

  if v_status = 'closed' then$a$
])

-- 2-a. 마케팅 정보 수신 동의: 정지 회원은 동의하지 않은 수단을 새로 켜지 못한다. 철회·이미 동의 중인 수단 유지는 받는다.
select private.t10_followup_patch_function('public.set_my_marketing_consents(boolean,boolean,text,text)'::regprocedure, array[
$a$ if not found then raise insufficient_privilege using message='marketing_consent_auth_required'; end if;$a$,
