CREATE OR REPLACE FUNCTION private.address_book_actor(p_new_write boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  actor_profile public.profiles;
begin
  if actor is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;
  -- 계정 행동 잠금을 먼저 잡는다(위 잠금 순서). 봉인된 계정은 여기서 끝난다.
  if private.is_account_write_fenced(actor) then
    raise object_not_in_prerequisite_state using message = 'account_deletion_write_fenced';
  end if;
  if p_new_write is distinct from false then
    select * into actor_profile from public.profiles where id = actor;
    if not found then
      raise exception 'auth_required' using errcode = '28000';
    end if;
    if actor_profile.suspended_at is not null then
      raise insufficient_privilege using message = 'account_suspended';
    end if;
    -- 개인정보처리방침에 동의하고 온보딩을 마친 회원만 연락처·주소를 저장한다(subscription_lock_actor 관례).
    if actor_profile.onboarded_at is null
      or actor_profile.consents->>'terms' is distinct from 'true'
      or actor_profile.consents->>'privacy' is distinct from 'true' then
      raise insufficient_privilege using message = 'onboarding_required';
    end if;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('address-book:' || actor::text, 0)
  );
  return actor;
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_assign_good_category_before_additional(target_operation_id uuid, target_good_id text, target_category_id uuid, target_expected_updated_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  category_row public.catalog_categories;
  good_updated_at timestamptz;
  good_category_id uuid;
  good_published_at timestamptz;
  existing_actor_id uuid;
  existing_action text;
  existing_diff jsonb;
  request_payload jsonb;
begin
  if actor_id is null or not public.is_staff() then raise insufficient_privilege using message = 'forbidden'; end if;
  if target_operation_id is null or target_good_id is null then raise invalid_parameter_value using message = 'invalid_good_category'; end if;
  request_payload := jsonb_build_object(
    'good_id', target_good_id,
    'category_id', target_category_id,
    'expected_updated_at', target_expected_updated_at
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || target_operation_id::text, 0));
  select audit.actor_id, audit.action, audit.diff into existing_actor_id, existing_action, existing_diff
  from public.audit_log as audit where audit.id = target_operation_id;
  if found then
    if existing_actor_id = actor_id and existing_action = 'admin.catalog.good.category_updated' and existing_diff -> 'request' = request_payload then
      return true;
    end if;
    raise unique_violation using message = 'operation_conflict';
  end if;
  perform private.lock_catalog_category_tree();
  select updated_at, category_id, published_at into good_updated_at, good_category_id, good_published_at
  from public.goods where id = target_good_id for update;
  if not found then raise no_data_found using message = 'goods_not_found'; end if;
  if target_category_id is not null then
    select * into category_row from public.catalog_categories where id = target_category_id for update;
    if not found then raise no_data_found using message = 'category_not_found'; end if;
    if category_row.archived_at is not null and good_category_id is distinct from target_category_id then raise check_violation using message = 'category_archived'; end if;
    if exists(select 1 from public.catalog_categories where parent_id = target_category_id and archived_at is null) then raise check_violation using message = 'category_not_leaf'; end if;
  end if;
  if target_expected_updated_at is not null and good_updated_at is distinct from target_expected_updated_at then raise exception using errcode = 'PT409', message = 'goods_changed'; end if;
  -- ADR-0044: 공개 중 상품은 다른 대표 카테고리로 옮길 수 있지만 비울 수는 없다(공개 조건).
  if good_published_at is not null and good_category_id is not null and target_category_id is null then
    raise check_violation using message = 'goods_published_category_clear';
  end if;
  update public.goods set category_id = target_category_id, updated_at = pg_catalog.now() where id = target_good_id;
  insert into public.audit_log(id, actor_id, action, target, diff)
  values (target_operation_id, actor_id, 'admin.catalog.good.category_updated', 'goods:' || target_good_id,
    jsonb_build_object('request', request_payload));
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_clone_good_before_additional_categories(target_operation_id uuid, target_source_good_id text, target_new_id text DEFAULT NULL::text, target_new_code text DEFAULT NULL::text, target_new_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb; replay boolean; source_enabled boolean;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
  -- Take the exact existing operation lock before observing its receipt. A
  -- concurrent retry must not reset a clone that has already been edited.
  perform pg_advisory_xact_lock(hashtextextended('admin.goods.clone.operation:'||target_operation_id::text,0));
  select exists(select 1 from public.audit_log where id=target_operation_id) into replay;
  saved := private.admin_clone_good_before_discount_display(target_operation_id,target_source_good_id,target_new_id,target_new_code,target_new_name);
  if not replay then
    select show_discount_rate into source_enabled from public.goods where id=saved->>'sourceGoodId';
    perform private.apply_goods_discount_display(saved->>'id',source_enabled);
  end if;
  return saved;
end $function$

CREATE OR REPLACE FUNCTION private.admin_clone_good_before_custom_inputs(target_operation_id uuid, target_source_good_id text, target_new_id text DEFAULT NULL::text, target_new_code text DEFAULT NULL::text, target_new_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb; replay boolean; category_ids uuid[];
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
  perform pg_advisory_xact_lock(hashtextextended('admin.goods.clone.operation:'||target_operation_id::text,0));
  select exists(select 1 from public.audit_log where id=target_operation_id) into replay;
  saved:=private.admin_clone_good_before_additional_categories(target_operation_id,target_source_good_id,target_new_id,target_new_code,target_new_name);
  if not replay then
    select coalesce(array_agg(membership.category_id),'{}'::uuid[]) into category_ids
      from public.goods_additional_categories membership join public.catalog_categories category on category.id=membership.category_id
      where membership.good_id=saved->>'sourceGoodId' and category.archived_at is null;
    perform private.apply_goods_additional_categories(saved->>'id',category_ids);
  end if;
  return saved;
end $function$

CREATE OR REPLACE FUNCTION private.admin_clone_good_before_discount_display(target_operation_id uuid, target_source_good_id text, target_new_id text DEFAULT NULL::text, target_new_code text DEFAULT NULL::text, target_new_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  source_good public.goods;
  source_ip_id text;
  category_value uuid;
  category_row public.catalog_categories;
  source_variants jsonb;
  target_payload jsonb;
  source_attribute_entries jsonb; clone_attribute_fields jsonb; clone_attribute_revision integer;
  clone_attribute_submission jsonb; clone_attribute_entries jsonb;
  saved jsonb;
  saved_good public.goods;
  saved_code text;
  saved_id text;
  effective_name text;
  normalized_source_id text := nullif(pg_catalog.btrim(coalesce(target_source_good_id, '')), '');
  normalized_new_id text := nullif(pg_catalog.lower(pg_catalog.btrim(coalesce(target_new_id, ''))), '');
  normalized_new_code text := nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(target_new_code, ''))), '');
  normalized_new_name text := nullif(pg_catalog.btrim(coalesce(target_new_name, '')), '');
  request_payload jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_diff jsonb;
begin
  if actor_id is null or not public.is_staff() then
    raise insufficient_privilege using message = 'forbidden';
  end if;
  if target_operation_id is null then
    raise invalid_parameter_value using message = 'invalid_operation_id';
  end if;
  if normalized_source_id is null or normalized_source_id !~ '^[a-z0-9][a-z0-9-]{0,63}$' then
    raise invalid_parameter_value using message = 'invalid_source_good_id';
  end if;
  if normalized_new_id is not null and normalized_new_id !~ '^[a-z0-9][a-z0-9-]{0,63}$' then
    raise invalid_parameter_value using message = 'invalid_clone_good_id';
  end if;
  if normalized_new_code is not null and normalized_new_code !~ '^[A-Z0-9][A-Z0-9-]{0,99}$' then
    raise invalid_parameter_value using message = 'invalid_clone_good_code';
  end if;
  if normalized_new_name is not null and pg_catalog.char_length(normalized_new_name) > 200 then
    raise invalid_parameter_value using message = 'invalid_clone_good_name';
  end if;

  request_payload := pg_catalog.jsonb_build_object(
    'source_good_id', normalized_source_id,
    'new_id', normalized_new_id,
    'new_code', normalized_new_code,
    'new_name', normalized_new_name
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin.goods.clone.operation:' || target_operation_id::text, 0)
  );
  select audit.actor_id, audit.action, audit.diff
    into existing_actor_id, existing_action, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;
  if found then
    if existing_actor_id = actor_id
       and existing_action = 'admin.catalog.good.cloned'
       and existing_diff -> 'request' = request_payload
       and existing_diff ? 'result'
    then
      return existing_diff -> 'result';
    end if;
    raise unique_violation using message = 'goods_clone_operation_conflict';
  end if;

  -- Checkout locks goods before its IP. Never hold the parent while waiting for
  -- this source or an existing manual target. A multi-item checkout may already
  -- hold this IP SHARE from an earlier item, so parent contention must fail fast.
  perform private.lock_catalog_category_tree();
  select * into source_good
  from public.goods
  where id = normalized_source_id
  for update;
  if not found then
    raise no_data_found using message = 'goods_clone_source_not_found';
  end if;
  if source_good.archived_at is not null then
    raise check_violation using message = 'goods_clone_source_archived';
  end if;
  if normalized_new_id is not null and normalized_new_id = source_good.id then
    raise unique_violation using message = 'good_clone_id_taken';
  end if;
  if normalized_new_id is not null and exists(select 1 from public.goods where id=normalized_new_id) then
    raise unique_violation using message='catalog_id_taken';
  end if;
  if normalized_new_code is not null and exists(select 1 from public.goods where code=normalized_new_code) then
    raise unique_violation using message='goods_code_key';
  end if;
  begin
    select id into source_ip_id from public.ips where id=source_good.ip_id for update nowait;
  exception when lock_not_available then
    raise sqlstate 'PT409' using message='goods_clone_source_busy';
  end;
  if not found then raise no_data_found using message='goods_clone_source_not_found'; end if;

  -- Lock the complete source option set before reading it. The payload below
  -- intentionally omits source option IDs, codes, external identities and cost.
  perform 1
  from public.goods_variants as variant
  where variant.good_id = source_good.id
  order by variant.id
  for update;
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'name', variant.name,
        'attributes', coalesce(variant.attributes, '{}'::jsonb),
        'extraPrice', greatest(0,variant.price - source_good.price),
        'stockQty', 0,
        'isActive', variant.archived_at is null,
        'lowStockThreshold', variant.low_stock_threshold,
        'orderMaxQty', variant.order_max_qty,
        'memberMaxQty', variant.member_max_qty
      ) order by variant.is_default desc, variant.sort_order, variant.id
    ), '[]'::jsonb
  )
  into source_variants
  from public.goods_variants as variant
  where variant.good_id = source_good.id
    and (variant.archived_at is null or variant.is_default);
  if pg_catalog.jsonb_array_length(source_variants) = 0 then
    raise check_violation using message = 'goods_clone_source_options_missing';
  end if;
  if exists (
    select 1
    from public.goods_variants as variant
    where variant.good_id = source_good.id
      and variant.archived_at is null
      and variant.price < source_good.price
  ) then
    raise check_violation using message = 'goods_clone_source_options_invalid';
  end if;

  -- A category is copied only while it is an active leaf. Archived or changed
  -- source category values become an explicitly unclassified draft.
  if source_good.category_id is not null then
    select * into category_row
    from public.catalog_categories as category
    where category.id = source_good.category_id
    for share;
    if found and category_row.archived_at is null
       and not exists (
         select 1 from public.catalog_categories as child
         where child.parent_id = category_row.id and child.archived_at is null
       ) then
      category_value := category_row.id;
    end if;
  end if;

  effective_name := coalesce(normalized_new_name, source_good.name || ' 복사본');
  target_payload := pg_catalog.jsonb_build_object(
    'id', normalized_new_id,
    'code', normalized_new_code,
    'ip_id', source_good.ip_id,
    'name', effective_name,
    'name_en', source_good.name_en,
    'origin_id', source_good.origin_id,
    'shipping_fee_type', source_good.shipping_fee_type,
    'individual_fee', source_good.individual_fee,
    'allow_card_payment', source_good.allow_card_payment,
    'allow_bank_transfer', source_good.allow_bank_transfer,
    'sale_restriction', source_good.sale_restriction,
    'order_quantity_limit_enabled', source_good.order_quantity_limit_enabled,
    'min_order_qty', source_good.min_order_qty,
    'max_order_qty', source_good.max_order_qty,
    'member_purchase_limit_enabled', source_good.member_purchase_limit_enabled,
    'member_lifetime_qty_limit', source_good.member_lifetime_qty_limit,
    'claim_policy', jsonb_build_object('returnAllowed',source_good.claim_return_allowed,
      'exchangeAllowed',source_good.claim_exchange_allowed,'restrictionReason',source_good.claim_restriction_reason,
      'returnFee',source_good.claim_return_fee,'returnFreeShippingFee',source_good.claim_return_free_shipping_fee,
      'exchangeFee',source_good.claim_exchange_fee,'returnAddressId',source_good.return_address_id),
    'price', source_good.price,
    'compare_at_price', source_good.compare_at_price,
    'badge', source_good.badge,
    'stock', 'ok',
    'bg', source_good.bg,
    'image_path', null,
    'notice_maker', source_good.notice_maker,
    'notice_origin', source_good.notice_origin,
    'notice_material', source_good.notice_material,
    'notice_size', source_good.notice_size,
    'notice_made_on', source_good.notice_made_on,
    'notice_as_manager', source_good.notice_as_manager,
    'notice_as_contact', source_good.notice_as_contact,
    'description', source_good.description,
    'description_format', source_good.description_format,
    'description_image_paths', '[]'::jsonb,
    'gallery_paths', '[]'::jsonb,
    'detail_image_path', null,
    'search_keywords', coalesce(to_jsonb(source_good.search_keywords), '[]'::jsonb),
    'category_id', category_value,
    'publish', false,
    'variants', source_variants,
    'variant_baseline', '[]'::jsonb
  );

  -- The existing safe writer owns validation, ID/code allocation, option code
  -- allocation, deferred default-option checks, and its established audit.

  -- The category tree and source good are already locked, so a competing schema
  -- or product edit cannot mix its definition with the copied values.
  select entries into source_attribute_entries from public.goods_attribute_values where good_id=source_good.id for share;
  select fields,revision into clone_attribute_fields,clone_attribute_revision
    from public.catalog_category_attribute_schemas where category_id=category_value for share;
  source_attribute_entries:=coalesce(source_attribute_entries,'[]');
  clone_attribute_fields:=coalesce(clone_attribute_fields,'[]');
  clone_attribute_submission:=jsonb_build_object('categoryId',category_value,'schemaRevision',coalesce(clone_attribute_revision,0),
    'expectedRevision',0,'values',coalesce((select jsonb_object_agg(entry#>>'{field,id}',entry->'value')
      from jsonb_array_elements(source_attribute_entries) entry
      where exists(select 1 from jsonb_array_elements(clone_attribute_fields) field where field->>'id'=entry#>>'{field,id}'
        and field->>'kind'=entry#>>'{field,kind}' and field->>'unit'=entry#>>'{field,unit}'
        and private.goods_attribute_value_valid(field,entry->'value'))),'{}'),
    'removeIds','[]'::jsonb);
  clone_attribute_entries:=private.merge_goods_attributes(source_attribute_entries,clone_attribute_fields,clone_attribute_submission->'values','[]');
  target_payload:=target_payload||jsonb_build_object('product_attributes',clone_attribute_submission);
  saved := public.admin_save_good(target_payload);

  saved_id := saved ->> 'id';
  if saved_id is null then
    raise check_violation using message = 'goods_clone_result_missing';
  end if;


  -- Creation remains one transaction/version, including values retained after a
  -- source category change. Publication still exposes only matching definitions.
  update public.goods_attribute_values set entries=clone_attribute_entries
    where good_id=saved_id and entries is distinct from clone_attribute_entries;
  if clone_attribute_entries<>'[]'::jsonb then
    insert into public.audit_log(actor_id,action,target,diff) values(actor_id,'catalog.goods_attributes_cloned','goods:'||saved_id,
      jsonb_build_object('sourceGoodId',source_good.id,'after',clone_attribute_entries,'revision',1));
  end if;

  perform private.clone_goods_benefit_content(source_good.id,saved_id,actor_id);

  perform private.clone_goods_after_sales_content(source_good.id,saved_id,actor_id);

  perform private.clone_goods_size_chart(source_good.id,saved_id,actor_id);
  -- Stopped non-default rows are historical configuration, not rows of the
  -- active editor. Preserve their absolute price and duplicate old attributes
  -- without reactivating them or importing old IDs/codes, stock, or ledgers.
  insert into public.goods_variants(good_id,name,attributes,price,stock_qty,sort_order,is_default,low_stock_threshold,archived_at)
    select saved_id,variant.name,variant.attributes,variant.price,0,
      (jsonb_array_length(source_variants)+row_number() over(order by variant.sort_order,variant.id)-1)::integer,
      false,variant.low_stock_threshold,clock_timestamp()
    from public.goods_variants variant
    where variant.good_id=source_good.id and variant.archived_at is not null and not variant.is_default;
  update public.goods_variants copied
    set price=original.price
    from public.goods_variants original
    where copied.good_id=saved_id and copied.is_default
      and original.good_id=source_good.id and original.is_default and original.archived_at is not null;

  insert into private.goods_artwork_copy_authorizations(transaction_id,target_good_id,source_good_id,actor_id,allowed_paths)
    values(txid_current(),saved_id,source_good.id,actor_id,
      array_remove(array[source_good.image_path,source_good.detail_image_path]||coalesce(source_good.gallery_paths,'{}')||coalesce(source_good.description_image_paths,'{}'),null));
  update public.goods set image_path=source_good.image_path,gallery_paths=source_good.gallery_paths,
    detail_image_path=source_good.detail_image_path,description_image_paths=source_good.description_image_paths where id=saved_id;
  delete from private.goods_artwork_copy_authorizations where transaction_id=txid_current() and target_good_id=saved_id;

  -- Shipping notice is an immutable snapshot on the source good. Applying the
  -- exact references/snapshot avoids resolving a later template revision.
  update public.goods
  set shipping_notice_template_id = source_good.shipping_notice_template_id,
      shipping_notice_template_version = source_good.shipping_notice_template_version,
      shipping_notice_snapshot = source_good.shipping_notice_snapshot
  where id = saved_id;

  select good.* into saved_good from public.goods as good where good.id = saved_id for update;
  saved_code := saved_good.code;
  if saved_code is null then
    raise check_violation using message = 'goods_clone_result_missing';
  end if;

  insert into public.audit_log(id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.catalog.good.cloned',
    'goods:' || saved_id,
    pg_catalog.jsonb_build_object(
      'request', request_payload,
      'sourceGoodId', source_good.id,
      'copiedOptions',(select jsonb_agg(jsonb_build_object('id',variant.id,'name',variant.name,'attributes',variant.attributes,
        'price',variant.price,'lowStockThreshold',variant.low_stock_threshold,'active',variant.archived_at is null)
        order by variant.sort_order,variant.id) from public.goods_variants variant where variant.good_id=saved_id),
      'copiedArtwork',jsonb_build_object('imagePath',source_good.image_path,'galleryPaths',source_good.gallery_paths,'detailImagePath',source_good.detail_image_path,'descriptionImagePaths',source_good.description_image_paths),
      'copiedDescription',jsonb_build_object('format',source_good.description_format,'description',source_good.description),
      'result', pg_catalog.jsonb_build_object(
        'id', saved_id,
        'code', saved_code,
        'sourceGoodId', source_good.id,
        'operationId', target_operation_id
      )
    )
  );
  return pg_catalog.jsonb_build_object(
    'id', saved_id,
    'code', saved_code,
    'sourceGoodId', source_good.id,
    'operationId', target_operation_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_commit_goods_import_group_before_category(target_batch uuid, target_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare batch public.admin_goods_imports; entry jsonb; target jsonb; images jsonb; saved jsonb; result jsonb; current_good public.goods; error_code text; error_message text;
begin
 if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
 select * into batch from public.admin_goods_imports where id=target_batch and actor_id=auth.uid() for update;
 if not found then raise insufficient_privilege using message='import_not_found'; end if;
 if batch.expires_at<=now() then raise check_violation using message='import_expired'; end if;
 if batch.state not in ('ready','complete') or target_index<0 or target_index>=jsonb_array_length(batch.plan) then raise invalid_parameter_value using message='import_not_ready'; end if;
 if batch.results ? target_index::text then return batch.results->target_index::text; end if;
 entry:=batch.plan->target_index;
 if entry->>'kind'='unchanged' then result:=jsonb_build_object('status','unchanged');
 elsif entry->>'kind'='error' then result:=jsonb_build_object('status','failed','error','validation_failed');
 else
  begin
   target:=entry->'target';
   if target is null or jsonb_typeof(target)<>'object' then raise invalid_parameter_value using message='invalid_import_plan'; end if;
   if nullif(target->>'previous_id','') is not null then
    select * into current_good from public.goods where id=target->>'previous_id' for update;
    if not found or private.goods_import_fingerprint(current_good.id) is distinct from entry->>'fingerprint' then
     raise sqlstate 'PT409' using message='import_product_changed';
    end if;
   elsif nullif(target->>'code','') is not null and exists(select 1 from public.goods where code=target->>'code') then
    raise sqlstate 'PT409' using message='import_product_changed';
   end if;
   images:=coalesce(batch.prepared_images->target_index::text,'{}');
   if exists(select 1 from jsonb_object_keys(images) key where key not in ('image_path','gallery_paths','detail_image_path')) then raise invalid_parameter_value using message='invalid_import_images'; end if;
   target:=target||images;
   if coalesce(target->>'image_path','') like 'import-image:%' or coalesce(target->>'detail_image_path','') like 'import-image:%'
    or exists(select 1 from jsonb_array_elements_text(coalesce(target->'gallery_paths','[]')) path where path like 'import-image:%')
    then raise check_violation using message='import_images_not_ready'; end if;
   if entry ? 'guidanceOnly' and entry->'guidanceOnly' <> 'true'::jsonb then
    raise invalid_parameter_value using message='invalid_import_guidance_only';
   end if;
   if entry->'guidanceOnly' = 'true'::jsonb then
    if entry->>'kind' is distinct from 'update' or current_good.id is null or current_good.archived_at is not null
     or not target ?& array['previous_id','code'] or target-array['previous_id','code'] <> '{}'::jsonb
     or target->>'previous_id' is distinct from current_good.id or target->>'code' is distinct from current_good.code
     or images <> '{}'::jsonb or entry->'guidance' is null or jsonb_typeof(entry->'guidance') <> 'object'
     or entry->'guidance' = '{}'::jsonb then
     raise invalid_parameter_value using message='invalid_import_guidance_only';
    end if;
    saved:=jsonb_build_object('id',current_good.id,'code',current_good.code);
   else
    saved:=public.admin_save_good(target);
   end if;
   perform private.apply_goods_import_guidance(batch.id,target_index,saved->>'id',entry->'guidance');
   result:=jsonb_build_object('status','success','id',saved->>'id','code',saved->>'code');
   insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.goods_import.applied','goods:'||(saved->>'id'),
    jsonb_build_object('batch_id',batch.id,'rows',entry->'rows','kind',entry->>'kind'));
  exception when others then
   get stacked diagnostics error_code=returned_sqlstate,error_message=message_text;
   result:=jsonb_build_object('status','failed','error',error_message,'code',error_code);
  end;
 end if;
 update public.admin_goods_imports set results=jsonb_set(results,array[target_index::text],result,true),
  state=case when (select count(*) from jsonb_object_keys(results))+1>=jsonb_array_length(plan) then 'complete' else 'ready' end
  where id=batch.id;
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.admin_commit_goods_import_group_before_purchase_cost(target_batch uuid, target_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  perform private.lock_catalog_category_tree();
  return private.admin_commit_goods_import_group_before_category(target_batch,target_index);
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_enqueue_shipment_emails_before_delivery_methods(target_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare expected integer; valid integer;
begin
  if (select auth.uid()) is null or not public.is_staff() then raise insufficient_privilege using message='staff_required';end if;
  if jsonb_typeof(target_rows) is distinct from 'array' or jsonb_array_length(target_rows)>1000 then
    raise invalid_parameter_value using message='invalid_shipment_email_rows';end if;
  if exists(select 1 from jsonb_array_elements(target_rows) e where jsonb_typeof(e) is distinct from 'object'
    or jsonb_typeof(e->'orderId') is distinct from 'string' or jsonb_typeof(e->'shipmentId') is distinct from 'string') then
    raise invalid_parameter_value using message='invalid_shipment_email_rows';end if;
  if exists(select 1 from jsonb_array_elements(target_rows) e cross join lateral jsonb_object_keys(e) k
    where k not in ('orderId','shipmentId')) then raise invalid_parameter_value using message='invalid_shipment_email_rows';end if;
  perform o.id from public.orders o where o.id in (select (e->>'orderId')::uuid from jsonb_array_elements(target_rows) e)
    order by o.id for update;
  select count(distinct ((e->>'orderId')::uuid,(e->>'shipmentId')::uuid)) into expected from jsonb_array_elements(target_rows) e;
  select count(*) into valid from public.order_shipments s join public.orders o on o.id=s.order_id
    where (s.order_id,s.id) in (select (e->>'orderId')::uuid,(e->>'shipmentId')::uuid from jsonb_array_elements(target_rows) e)
    and s.status in ('shipping','delivered') and o.status in ('shipping','delivered','done');
  if valid<>expected then raise check_violation using message='shipment_email_unavailable';end if;
  insert into public.order_shipment_email_jobs(order_id,shipment_id)
    select distinct (e->>'orderId')::uuid,(e->>'shipmentId')::uuid from jsonb_array_elements(target_rows) e
    order by 1,2 on conflict(shipment_id) do nothing;
  return jsonb_build_object('queued',valid);
end $function$

CREATE OR REPLACE FUNCTION private.admin_goods_console_matches(p_query text, p_ip_id text, p_status text, p_stock text, p_category_id uuid, p_readiness text, p_filters jsonb)
 RETURNS TABLE(good public.goods, readiness jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  field_value text := coalesce(p_filters->>'field', 'all');
  date_field text := coalesce(p_filters->>'dateField', 'created');
  sort_value text := coalesce(p_filters->>'sort', 'created_desc');
  payment_value text := coalesce(p_filters->>'payment', 'all');
  sale_type text := coalesce(p_filters->>'saleType', 'all');
  image_value text := coalesce(p_filters->>'image', 'all');
  restriction_value text := coalesce(p_filters->>'restriction', 'all');
  sale_period_value text := coalesce(p_filters->>'salePeriod', 'all');
  query_value text := lower(btrim(coalesce(p_query, '')));
  from_value date;
  to_value date;
  origin_value uuid;
begin
  if auth.uid() is null or not coalesce(public.is_staff(), false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if jsonb_typeof(p_filters) is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(p_filters) key where key not in
      ('field','dateField','sort','payment','saleType','image','restriction','from','to','originId','salePeriod'))
    or exists(select 1 from jsonb_each(p_filters) item where jsonb_typeof(item.value) not in ('string','null'))
    or field_value not in ('all','name','number','id','code','erp','barcode')
    or date_field not in ('created','updated','published')
    or sort_value not in ('created_desc','updated_desc','name_asc','number_asc','number_desc','id_asc','price_asc','price_desc','stock_asc','stock_desc')
    or payment_value not in ('all','card','bank','none')
    or sale_type not in ('all','stock','preorder')
    or image_value not in ('all','with','without')
    or restriction_value not in ('all','none','adult')
    or sale_period_value not in ('all','scheduled','ended')
    or length(query_value) > 100 then
    raise invalid_parameter_value using message = 'invalid_goods_console_filter';
  end if;
  if nullif(p_filters->>'from','') is not null then
    if p_filters->>'from' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
      raise invalid_parameter_value using message = 'invalid_goods_console_date';
    end if;
    from_value := (p_filters->>'from')::date;
  end if;
  if nullif(p_filters->>'to','') is not null then
    if p_filters->>'to' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
      raise invalid_parameter_value using message = 'invalid_goods_console_date';
    end if;
    to_value := (p_filters->>'to')::date;
  end if;
  if from_value > to_value then
    raise invalid_parameter_value using message = 'invalid_goods_console_date';
  end if;
  if nullif(p_filters->>'originId','') is not null then
    origin_value := (p_filters->>'originId')::uuid;
  end if;

  return query
    select source.good, source.readiness
    from private.admin_goods_workspace_matches(
      case when field_value = 'all' then p_query else '' end,
      p_ip_id, p_status, p_stock, p_category_id, p_readiness
    ) source
    cross join lateral (select case date_field
      when 'updated' then (source.good).updated_at
      when 'published' then (source.good).published_at
      else (source.good).created_at end as at) event_date
    where (from_value is null or event_date.at >= (from_value::timestamp at time zone 'Asia/Seoul'))
      and (to_value is null or event_date.at < ((to_value + 1)::timestamp at time zone 'Asia/Seoul'))
      and (origin_value is null or (source.good).origin_id = origin_value)
      and case payment_value
        when 'card' then (source.good).allow_card_payment
        when 'bank' then (source.good).allow_bank_transfer
        when 'none' then not (source.good).allow_card_payment and not (source.good).allow_bank_transfer
        else true end
      and (restriction_value = 'all' or (source.good).sale_restriction::text = restriction_value)
      and private.admin_goods_sale_period_matches(sale_period_value,(source.good).sale_starts_at,(source.good).sale_ends_at)
      and case image_value
        when 'with' then nullif(btrim((source.good).image_path),'') is not null
        when 'without' then nullif(btrim((source.good).image_path),'') is null
        else true end
      and (sale_type = 'all' or (
        exists(select 1 from public.goods_variants variant where variant.good_id = (source.good).id
          and variant.archived_at is null and variant.preorder_policy_id is not null)
        = (sale_type = 'preorder')
      ))
      and (query_value = '' or field_value = 'all' or case field_value
        when 'name' then strpos(lower((source.good).name),query_value) > 0
          or strpos(lower(coalesce((source.good).name_en,'')),query_value) > 0
        when 'number' then (source.good).product_no::text = any(regexp_split_to_array(query_value,'[[:space:],]+'))
        when 'id' then lower((source.good).id) = any(regexp_split_to_array(query_value,'[[:space:],]+'))
        when 'code' then strpos(lower((source.good).code),query_value) > 0
          or exists(select 1 from public.goods_variants variant where variant.good_id = (source.good).id
            and strpos(lower(variant.code),query_value) > 0)
        when 'erp' then exists(select 1 from public.goods_variants variant
          join private.goods_variant_external_identity identity on identity.variant_id = variant.id
          where variant.good_id = (source.good).id and
            (strpos(lower(identity.erp_code),query_value) > 0 or strpos(lower(identity.erp_name),query_value) > 0))
        when 'barcode' then exists(select 1 from public.goods_variants variant
          join private.goods_variant_external_identity identity on identity.variant_id = variant.id
          where variant.good_id = (source.good).id and strpos(lower(identity.barcode),query_value) > 0)
        else false end);
end $function$

CREATE OR REPLACE FUNCTION private.admin_goods_readiness(p_good public.goods)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  reasons text[] := array[]::text[]; blockers text[] := array[]::text[];
  available bigint; active_qty bigint; active_options integer; low_options integer;
  min_price integer; max_price integer; ip public.ips;
  kc_current boolean; kc_legacy boolean; notice_complete boolean; unknown_read boolean := false;
  category_review boolean := false;
begin
  select * into ip from public.ips where id=p_good.ip_id;
  select count(*)::integer into active_options from public.goods_variants where good_id=p_good.id and archived_at is null;
  active_qty:=public.admin_goods_active_stock_qty(p_good);
  low_options:=public.admin_goods_low_stock_option_count(p_good);
  notice_complete := not exists(select 1 from unnest(array[p_good.notice_maker,p_good.notice_origin,p_good.notice_material,
    p_good.notice_size,p_good.notice_made_on,p_good.notice_as_manager,p_good.notice_as_contact]) value where nullif(btrim(value),'') is null);
  -- A malformed supply/review must remain an unknown item in the queue, never 0/ready.
  begin
    available := public.goods_sale_available_qty(p_good);
    select min(price.effective_price),max(price.effective_price) into min_price,max_price
      from public.goods_variants variant cross join lateral private.resolve_goods_variant_price(variant.id,statement_timestamp()) price
      where variant.good_id=p_good.id and variant.archived_at is null;
    kc_current := private.goods_kc_review_current(p_good.id);
    kc_legacy := p_good.published_at is not null and not exists(select 1 from private.goods_kc_reviews where good_id=p_good.id);
  exception when others then
    available:=null; min_price:=null; max_price:=null; kc_current:=null; kc_legacy:=false; unknown_read:=true;
  end;
  if p_good.archived_at is not null then blockers:=array_append(blockers,'archived');
  elsif p_good.published_at is null then blockers:=array_append(blockers,'draft'); end if;
  if p_good.stock='soldout' then blockers:=array_append(blockers,'stopped'); end if;
  if ip.archived_at is not null then blockers:=array_append(blockers,'ip_archived');
  elsif ip.published_at is null then blockers:=array_append(blockers,'ip_unpublished'); end if;
  -- ADR-0044: 상품 유형은 없다. 대표 카테고리가 있어야 공개하고, 공개 중인데 없으면 검토 사유로 알린다.
  if p_good.category_id is null then
    if p_good.published_at is null then blockers:=array_append(blockers,'category_missing');
    else category_review:=true; end if;
  end if;
  if nullif(btrim(p_good.image_path),'') is null then blockers:=array_append(blockers,'image_missing'); end if;
  if not notice_complete then blockers:=array_append(blockers,'notice_missing'); end if;
  if active_options=0 then blockers:=array_append(blockers,'no_active_options');
  elsif available=0 and p_good.stock<>'soldout' and p_good.archived_at is null then blockers:=array_append(blockers,'stock_unavailable'); end if;
  if not p_good.allow_card_payment and not p_good.allow_bank_transfer then blockers:=array_append(blockers,'payment_disabled'); end if;
  -- 성인 상품은 인증 성인에게 판매된다(ADR-0024). 그 밖의 판매 제한 유형만 차단 사유다.
  if p_good.sale_restriction not in ('none','adult') then blockers:=array_append(blockers,'restricted_sale'); end if;
  if not exists(select 1 from public.fulfillment_origins where id=p_good.origin_id and is_active) then blockers:=array_append(blockers,'shipping_unavailable'); end if;
  reasons:=blockers;
  if category_review then reasons:=array_append(reasons,'category_missing'); end if;
  if unknown_read then reasons:=array_append(reasons,'readiness_unknown');
  elsif kc_legacy then reasons:=array_append(reasons,'kc_legacy_unrecorded');
  elsif not kc_current then reasons:=array_append(reasons,'kc_required'); end if;
  return jsonb_build_object(
    'state',case when unknown_read then 'unknown' when cardinality(blockers)>0 then 'blocked' when cardinality(reasons)>0 then 'review_required' else 'ready' end,
    'checkedAt',statement_timestamp(),
    'publication',case when p_good.archived_at is not null then 'archived' when p_good.published_at is null then 'draft' else 'published' end,
    'operation',case when p_good.stock='soldout' then 'stopped' else 'active' end,
    'availableQty',available,'activeStockQty',active_qty,'activeOptionCount',active_options,'lowStockOptionCount',low_options,
    'priceMin',min_price,'priceMax',max_price,'noticeComplete',notice_complete,
    'publicReview',case when unknown_read then 'unknown' when kc_current then 'current' when kc_legacy then 'legacy_unrecorded' else 'required' end,
    'saleSettings',case when unknown_read then 'unknown' when cardinality(blockers)>0 then 'blocked' else 'ready' end,
    'reviewRequired',cardinality(reasons)>0,'reasonCodes',to_jsonb(reasons),'blockingCodes',to_jsonb(blockers));
end $function$

CREATE OR REPLACE FUNCTION private.admin_import_item_tracking_batch_before_identity_guard(target_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  input jsonb; normalized jsonb:='[]'; delegated jsonb:='[]'; results jsonb:='[]';
  outcomes jsonb:='{}'; group_errors jsonb:='{}'; completed jsonb; outcome jsonb;
  reference_value text; item_key uuid; shipment_key uuid; order_key uuid;
  carrier_value text; tracking_value text; row_error text; group_error text; batch_error text;
  grouped record; seen uuid[]:='{}';
begin
  perform private.require_operator_capability('sales.dispatch',false);
  if jsonb_typeof(target_rows) is distinct from 'array' then raise invalid_parameter_value using message='invalid_tracking_batch';end if;
  if jsonb_array_length(target_rows) not between 1 and 1000 then raise invalid_parameter_value using message='invalid_tracking_batch';end if;

  for input in select value from jsonb_array_elements(target_rows) loop
    reference_value:=null;item_key:=null;shipment_key:=null;order_key:=null;
    carrier_value:=null;tracking_value:=null;row_error:=null;
    begin
      if jsonb_typeof(input) is distinct from 'object' then raise invalid_parameter_value using message='invalid_tracking_row';end if;
      if jsonb_typeof(input->'reference') is distinct from 'string' then raise invalid_parameter_value using message='invalid_item_order_reference';end if;
      reference_value:=btrim(input->>'reference');
      if reference_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        raise invalid_parameter_value using message='invalid_item_order_reference';end if;
      item_key:=reference_value::uuid;
      select link.shipment_id,link.order_id into shipment_key,order_key from public.order_shipment_items link where link.order_item_id=item_key;
      if shipment_key is null then raise no_data_found using message='shipment_item_not_found';end if;
      -- Resolve before the remaining validation so one malformed item row blocks
      -- every sibling in its shipment, including a valid row earlier in the file.
      if exists(select 1 from jsonb_object_keys(input) key where key not in('line','reference','carrier','trackingNumber','recipientName','recipientPhone'))
        or jsonb_typeof(input->'line') is distinct from 'number' or (input->>'line') !~ '^[0-9]+$'
        or (input->>'line')::numeric not between 1 and 2147483647
        or jsonb_typeof(input->'carrier') is distinct from 'string'
        or jsonb_typeof(input->'trackingNumber') is distinct from 'string' then
        raise invalid_parameter_value using message='invalid_tracking_row';end if;
      carrier_value:=btrim(input->>'carrier');
      tracking_value:=upper(regexp_replace(btrim(input->>'trackingNumber'),'[[:space:]-]','','g'));
      if carrier_value='' or char_length(carrier_value)>100 or tracking_value !~ '^[A-Z0-9]{8,30}$' then
        raise check_violation using message='invalid_tracking_input';end if;
      perform private.assert_reply_recipient(order_key, input);
    exception when others then row_error:=sqlerrm;
    end;
    normalized:=normalized||jsonb_build_array(jsonb_build_object('line',input->'line','reference',reference_value,
      'shipmentId',shipment_key,'orderId',order_key,'carrier',carrier_value,'trackingNumber',tracking_value,'error',row_error));
  end loop;

  for grouped in select value->>'shipmentId' as id,jsonb_agg(value) as rows
    from jsonb_array_elements(normalized) where value->>'shipmentId' is not null
    group by value->>'shipmentId' order by value->>'shipmentId'
  loop
    select value->>'error' into group_error from jsonb_array_elements(grouped.rows) where value->>'error' is not null limit 1;
    if group_error is null and (
      (select count(distinct value->>'carrier') from jsonb_array_elements(grouped.rows))<>1
      or (select count(distinct value->>'trackingNumber') from jsonb_array_elements(grouped.rows))<>1
    ) then group_error:='conflicting_shipment_tracking';end if;
    group_errors:=group_errors||jsonb_build_object(grouped.id,group_error);
    -- Invalid groups remain in the existing whole-pack preflight with empty
    -- assignment data. Omitting them could dispatch a pack via a valid sibling.
    delegated:=delegated||jsonb_build_array(jsonb_build_object('line',1,'reference',grouped.id,
      'carrier',case when group_error is null then grouped.rows->0->>'carrier' else '' end,
      'trackingNumber',case when group_error is null then grouped.rows->0->>'trackingNumber' else '' end));
  end loop;
  if jsonb_array_length(delegated)>0 then
    begin
      completed:=public.admin_import_shipment_tracking_batch(delegated);
      if jsonb_typeof(completed) is distinct from 'array' or jsonb_array_length(completed)<>jsonb_array_length(delegated) then
        raise check_violation using message='tracking_batch_result_missing';end if;
      select jsonb_object_agg(value->>'reference',value) into outcomes from jsonb_array_elements(completed);
    exception when others then
      batch_error:=sqlerrm;
      select jsonb_object_agg(value->>'reference',jsonb_build_object('ok',false,'error',batch_error)) into outcomes from jsonb_array_elements(delegated);
    end;
  end if;

  for input in select value from jsonb_array_elements(normalized) loop
    shipment_key:=(input->>'shipmentId')::uuid;
    if shipment_key is null then outcome:=jsonb_build_object('ok',false,'error',input->>'error');
    elsif group_errors->>shipment_key::text is not null then
      outcome:=jsonb_build_object('ok',false,'error',group_errors->>shipment_key::text);
    else outcome:=outcomes->shipment_key::text;end if;
    if outcome->>'ok'='true' then
      if shipment_key=any(seen) then outcome:=outcome||jsonb_build_object('duplicate',true,'dispatched',false);
      else seen:=array_append(seen,shipment_key);outcome:=outcome||jsonb_build_object('duplicate',false);end if;
    end if;
    results:=results||jsonb_build_array(outcome||jsonb_build_object('line',input->'line','reference',input->>'reference',
      'shipmentId',shipment_key,'orderId',input->'orderId'));
  end loop;
  return results;
end $function$

CREATE OR REPLACE FUNCTION private.admin_import_item_tracking_batch_before_numbers(target_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare input jsonb;identified jsonb:='[]';reference_value text;shipment_key uuid;order_key uuid;row_error text;
begin
  perform private.require_operator_capability('sales.dispatch',false);
  if jsonb_typeof(target_rows) is distinct from 'array' then raise invalid_parameter_value using message='invalid_tracking_batch';end if;
  if jsonb_array_length(target_rows) not between 1 and 1000 then raise invalid_parameter_value using message='invalid_tracking_batch';end if;
  for input in select value from jsonb_array_elements(target_rows) loop
    reference_value:=null;shipment_key:=null;order_key:=null;row_error:=null;
    if jsonb_typeof(input) is distinct from 'object' then row_error:='invalid_tracking_row';
    elsif jsonb_typeof(input->'reference') is distinct from 'string' then row_error:='invalid_item_order_reference';
    else
      reference_value:=btrim(input->>'reference');
      if reference_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then row_error:='invalid_item_order_reference';
      else
        select link.shipment_id,link.order_id into shipment_key,order_key from public.order_shipment_items link where link.order_item_id=reference_value::uuid;
        if shipment_key is null then row_error:='shipment_item_not_found';end if;
      end if;
    end if;
    identified:=identified||jsonb_build_array(jsonb_build_object('line',input->'line','reference',reference_value,
      'shipmentId',shipment_key,'orderId',order_key,'error',row_error));
  end loop;
  if exists(select 1 from jsonb_array_elements(identified) row_value where row_value->>'error' is not null) then
    return(select jsonb_agg(row_value.value||jsonb_build_object('ok',false,
      'error',coalesce(row_value.value->>'error','item_tracking_identity_unresolved')) order by row_value.ordinality)
      from jsonb_array_elements(identified) with ordinality row_value(value,ordinality));
  end if;
  return private.admin_import_item_tracking_batch_before_identity_guard(target_rows);
end $function$

CREATE OR REPLACE FUNCTION private.admin_order_claim_detail_before_custom_inputs(p_claim_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  detail jsonb;
  fee public.order_cancellation_requests;
begin
  if actor is null or not public.is_staff() then raise insufficient_privilege using message = 'staff_required'; end if;
  detail := private.admin_order_claim_detail_before_operational_fee(p_claim_id);
  if detail is null then return null; end if;
  select * into fee from public.order_cancellation_requests where id = p_claim_id;
  return detail || jsonb_build_object('claim', (detail->'claim') || jsonb_build_object(
    'operationalFee', jsonb_build_object(
      'kind', fee.operational_fee_kind,
      'amount', fee.operational_fee_amount,
      'note', fee.operational_fee_note,
      'evidence', fee.operational_fee_evidence,
      'confirmedBy', fee.operational_fee_confirmed_by,
      'confirmedAt', fee.operational_fee_confirmed_at,
      'updatedAt', fee.updated_at
    ),
    'updatedAt', fee.updated_at,
    -- 운영자 전액 취소(ADR-0018)의 발원과 운영 사유. 구매자 컬럼 grant 밖의 운영 정보라
    -- staff 게이트가 붙은 이 RPC로만 싣는다.
    'origin', fee.origin,
    'staffReasonCode', fee.staff_reason_code,
    'staffNote', fee.staff_note
  ));
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_order_detail_before_custom_inputs(target_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; items jsonb;
begin
  result:=private.admin_order_detail_before_preorder(target_order_id);
  if result is null then return null; end if;
  select coalesce(jsonb_agg(line.value||jsonb_build_object('supplySource',item.supply_source,
    'preorderExpectedShipDate',item.preorder_expected_ship_date,'preorderSnapshot',item.preorder_snapshot,'optionSaleMode',coalesce(item.option_sale_mode_snapshot,'select')) order by line.ordinality),'[]') into items
    from jsonb_array_elements(result->'items') with ordinality line(value,ordinality)
    join public.order_items item on item.id=(line.value->>'id')::uuid and item.order_id=target_order_id;
  return result||jsonb_build_object('order',(result->'order')||jsonb_build_object('storeCreditTotal',
    (select store_credit_total from public.orders where id=target_order_id)),
    'shipments',private.order_shipment_records(target_order_id),'items',items);
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_additional_categories(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb;
begin
  if auth.uid() is null then raise invalid_authorization_specification using message='auth_required'; end if;
  if not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
  if jsonb_typeof(target_good) is distinct from 'object' then raise invalid_parameter_value using message='invalid_good'; end if;
  if target_good ? 'show_discount_rate' and jsonb_typeof(target_good->'show_discount_rate') is distinct from 'boolean' then
    raise invalid_parameter_value using message='invalid_discount_display';
  end if;
  -- The existing writer owns tree -> product locking, rename, validation and
  -- publication. Its transaction locks remain held while this field is applied.
  saved := private.admin_save_good_before_discount_display(target_good-'show_discount_rate');
  if target_good ? 'show_discount_rate' then
    perform private.apply_goods_discount_display(saved->>'id',(target_good->>'show_discount_rate')::boolean);
  end if;
  return saved;
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_attributes(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb; config jsonb; fields jsonb; previous public.goods; expected_revision integer;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
  if jsonb_typeof(target_good) is distinct from 'object' then raise invalid_parameter_value using message='invalid_good'; end if;
  if target_good ? 'custom_inputs' then
    config:=target_good->'custom_inputs';
    if jsonb_typeof(config) is distinct from 'object' or not config ?& array['enabled','fields']
      or exists(select 1 from jsonb_object_keys(config) key where key not in ('enabled','fields'))
      or jsonb_typeof(config->'enabled') is distinct from 'boolean'
      or jsonb_typeof(target_good->'custom_inputs_expected_revision') is distinct from 'number'
      or target_good->>'custom_inputs_expected_revision' !~ '^(0|[1-9][0-9]*)$' then
      raise check_violation using message='invalid_goods_custom_input_fields';
    end if;
    fields:=private.normalize_goods_custom_input_fields(config->'fields');
    expected_revision:=(target_good->>'custom_inputs_expected_revision')::integer;
    perform private.lock_catalog_category_tree();
    select * into previous from public.goods where id=coalesce(nullif(target_good->>'previous_id',''),target_good->>'id') for update;
    if expected_revision<>coalesce(previous.custom_inputs_revision,0) then raise sqlstate 'PT409' using message='goods_custom_inputs_changed'; end if;
  end if;
  saved:=private.admin_save_good_before_custom_inputs(target_good-'custom_inputs'-'custom_inputs_expected_revision');
  if config is not null then
    update public.goods set custom_inputs_enabled=(config->>'enabled')::boolean,custom_input_fields=fields where id=saved->>'id';
    if (coalesce(previous.custom_inputs_enabled,false),coalesce(previous.custom_input_fields,'[]'::jsonb))
      is distinct from ((config->>'enabled')::boolean,fields) then
      insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.good.custom_inputs_saved','goods:'||(saved->>'id'),
        jsonb_build_object('before',jsonb_build_object('enabled',coalesce(previous.custom_inputs_enabled,false),'fields',coalesce(previous.custom_input_fields,'[]'::jsonb)),
          'after',config,'revision',(select custom_inputs_revision from public.goods where id=saved->>'id')));
    end if;
  end if;
  return saved||jsonb_build_object('customInputsRevision',(select custom_inputs_revision from public.goods where id=saved->>'id'));
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_category(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  saved jsonb;
  legacy_payload jsonb;
  template_code text;
  template_version integer;
  template_fields_present boolean;
  template_version_text text;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  template_fields_present := target_good ? 'shipping_notice_template_code'
    or target_good ? 'shipping_notice_template_version'
    or target_good ? 'shippingNoticeTemplateCode'
    or target_good ? 'shippingNoticeTemplateVersion';
  legacy_payload := target_good - 'shipping_notice_template_code' - 'shipping_notice_template_version'
    - 'shippingNoticeTemplateCode' - 'shippingNoticeTemplateVersion';
  if template_fields_present then
    if (target_good ? 'shipping_notice_template_code' and jsonb_typeof(target_good->'shipping_notice_template_code') not in ('string','null'))
      or (target_good ? 'shippingNoticeTemplateCode' and jsonb_typeof(target_good->'shippingNoticeTemplateCode') not in ('string','null')) then
      raise invalid_parameter_value using message='invalid_shipping_notice_template';
    end if;
    template_code := nullif(btrim(coalesce(target_good->>'shipping_notice_template_code', target_good->>'shippingNoticeTemplateCode', '')), '');
    template_version_text := nullif(btrim(coalesce(target_good->>'shipping_notice_template_version', target_good->>'shippingNoticeTemplateVersion', '')), '');
    if template_version_text is not null then
      begin
        template_version := template_version_text::integer;
      exception when others then
        raise invalid_parameter_value using message='invalid_shipping_notice_template';
      end;
    end if;
    if template_code is not null and (template_code !~ '^[a-z][a-z0-9-]{1,39}$' or template_version is null or template_version not between 1 and 1000000) then
      raise invalid_parameter_value using message='invalid_shipping_notice_template';
    end if;
    if template_code is null and template_version is not null then
      raise invalid_parameter_value using message='invalid_shipping_notice_template';
    end if;
  end if;

  -- Defer first publication until the template snapshot has been applied.
  -- Keep an explicit unpublish in the preceding writer so restocking in the
  -- same request cannot notify customers about a good being taken offline.
  saved := private.admin_save_good_before_shipping_notice(case when legacy_payload->>'publish'='true'
    then legacy_payload||'{"publish":null}'::jsonb else legacy_payload end);
  if template_fields_present then
    perform private.apply_shipping_notice_template_reference(saved->>'id',template_code,template_version);
    saved := saved||jsonb_build_object('shippingNoticeTemplateCode',template_code,'shippingNoticeTemplateVersion',template_version);
  end if;
  if legacy_payload->>'publish'='true' then
    perform public.admin_set_good_published(saved->>'id',true);
  end if;
  return saved;
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_claim_policy(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  if jsonb_typeof(target_good->'variants')='array' and exists(
    select 1 from jsonb_array_elements(target_good->'variants') item where item?'purchaseCost'
  ) and not private.can_manage_goods_purchase_costs() then
    raise insufficient_privilege using message='purchase_cost_admin_required';
  end if;
  saved:=private.admin_save_good_before_purchase_cost(target_good);
  -- save_goods_options already applied cost metadata using its actual saved IDs.
  return saved;
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_custom_inputs(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb; category_ids uuid[];
begin
  if auth.uid() is null then raise invalid_authorization_specification using message='auth_required'; end if;
  if not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
  if jsonb_typeof(target_good) is distinct from 'object' then raise invalid_parameter_value using message='invalid_good'; end if;
  if target_good ? 'additional_category_ids' then
    if jsonb_typeof(target_good->'additional_category_ids') is distinct from 'array' then
      raise invalid_parameter_value using message='invalid_additional_categories';
    end if;
    if exists(select 1 from jsonb_array_elements(target_good->'additional_category_ids') item where jsonb_typeof(item)<>'string') then
      raise invalid_parameter_value using message='invalid_additional_categories';
    end if;
    begin
      select coalesce(array_agg(value::uuid),'{}'::uuid[]) into category_ids from jsonb_array_elements_text(target_good->'additional_category_ids');
    exception when invalid_text_representation then raise invalid_parameter_value using message='invalid_additional_categories'; end;
  end if;
  -- Always acquire tree before product/option locks; omission still needs to
  -- remove a redundant membership if the existing primary category changes.
  perform private.lock_catalog_category_tree();
  saved:=private.admin_save_good_before_additional_categories(target_good-'additional_category_ids');
  perform private.apply_goods_additional_categories(saved->>'id',coalesce(category_ids,private.goods_additional_category_ids(saved->>'id')));
  return saved;
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_description(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare update_data jsonb; existing_id text; good public.goods; saved jsonb; before_review private.goods_kc_reviews;
  next_review private.goods_kc_reviews; model_row jsonb; code_value jsonb; ids jsonb; variant_id uuid; models jsonb:='[]';
begin
  if not coalesce(public.is_staff(),false) then raise insufficient_privilege using message='staff required'; end if;
  if not(target_good ? 'kc_update') then return private.admin_save_good_before_kc(target_good); end if;
  update_data:=target_good->'kc_update';
  if jsonb_typeof(update_data)<>'object' or not(update_data ?& array['models','expectedRevision','expectedContextFingerprint'])
    or exists(select 1 from jsonb_object_keys(update_data) key where key not in ('models','expectedRevision','expectedContextFingerprint'))
    or jsonb_typeof(update_data->'models')<>'array' or jsonb_array_length(update_data->'models')>50
    or (jsonb_typeof(update_data->'expectedRevision') not in ('null','number'))
    or (jsonb_typeof(update_data->'expectedRevision')='number' and update_data->>'expectedRevision' !~ '^[1-9][0-9]{0,9}$')
    or (jsonb_typeof(update_data->'expectedContextFingerprint') not in ('null','string')) then
    raise check_violation using message='invalid_goods_kc_import';
  end if;
  if target_good->>'publish'='true' then raise check_violation using message='goods_kc_import_review_requires_draft'; end if;
  existing_id:=coalesce(nullif(btrim(target_good->>'previous_id'),''),nullif(btrim(target_good->>'id'),''));
  select * into good from public.goods where id=existing_id for update;
  if found then
    if good.published_at is not null and target_good->>'publish' is distinct from 'false' then
      raise check_violation using message='goods_kc_published_edit_requires_draft';
    end if;
    select * into before_review from private.goods_kc_reviews where good_id=good.id for update;
    if (update_data->>'expectedRevision')::bigint is distinct from before_review.revision::bigint
      or update_data->>'expectedContextFingerprint' is distinct from private.goods_kc_fingerprint(good.id) then
      raise sqlstate 'PT409' using message='goods_kc_review_changed';
    end if;
  elsif update_data->>'expectedRevision' is not null or update_data->>'expectedContextFingerprint' is not null then
    raise sqlstate 'PT409' using message='goods_kc_review_changed';
  end if;
  saved:=private.admin_save_good_before_kc(target_good-'kc_update');
  for model_row in select elem from jsonb_array_elements(update_data->'models') elem loop
    if jsonb_typeof(model_row)<>'object' or model_row ? 'variantIds' or not(model_row ? 'variantCodes')
      or jsonb_typeof(model_row->'variantCodes')<>'array' or jsonb_array_length(model_row->'variantCodes')>200 then
      raise check_violation using message='invalid_goods_kc_import';
    end if;
    ids:='[]';
    for code_value in select elem from jsonb_array_elements(model_row->'variantCodes') elem loop
      if jsonb_typeof(code_value)<>'string' or btrim(code_value#>>'{}')='' then raise check_violation using message='invalid_goods_kc_import'; end if;
      select variant.id into variant_id from public.goods_variants variant where variant.good_id=saved->>'id' and variant.code=code_value#>>'{}';
      if not found then raise check_violation using message='goods_kc_variant_code_not_found'; end if;
      ids:=ids||jsonb_build_array(variant_id::text);
    end loop;
    models:=models||jsonb_build_array((model_row-'variantCodes')||jsonb_build_object('variantIds',ids));
  end loop;
  select * into next_review from private.goods_kc_reviews where good_id=saved->>'id';
  perform public.admin_save_goods_kc(saved->>'id',models,'unreviewed',next_review.revision,private.goods_kc_fingerprint(saved->>'id'),false);
  return saved;
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_discount_display(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid:=(select auth.uid());
  previous_good public.goods;
  description_value text:=nullif(btrim(target_good->>'description',E' \t\n\r\f\v'),'');
  format_value text;
  image_paths text[];
  saved jsonb;
  before_value jsonb;
  after_value jsonb;
begin
  if v_actor_id is null then raise invalid_authorization_specification using message='auth_required'; end if;
  if not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
  if jsonb_typeof(target_good) is distinct from 'object' then raise invalid_parameter_value using message='invalid_good'; end if;
  -- Match category assignment and cloning: tree before product advisory/row.
  -- Taking a product lock first would deadlock with those existing writers.
  perform private.lock_catalog_category_tree();
  if nullif(target_good->>'previous_id','') is not null then
    perform pg_advisory_xact_lock(hashtextextended('admin_good:'||(target_good->>'previous_id'),0));
    select * into previous_good from public.goods where id=target_good->>'previous_id' for update;
    if not found then raise no_data_found using message='catalog_record_missing'; end if;
  end if;
  format_value:=case when target_good ? 'description_format' then target_good->>'description_format' else coalesce(previous_good.description_format,'plain') end;
  if format_value is null or format_value not in ('plain','html') then raise check_violation using message='goods_description_format'; end if;
  -- Keep legacy plain rows and their clone path compatible. The existing form
  -- still caps newly edited plain text at 2,000; this new DB cap is HTML-only.
  if format_value='html' and char_length(description_value)>200000 then
    raise check_violation using message='goods_description_length';
  end if;
  if target_good ? 'description_image_paths' then
    if jsonb_typeof(target_good->'description_image_paths') is distinct from 'array' then raise check_violation using message='goods_description_images'; end if;
    if jsonb_array_length(target_good->'description_image_paths')>20
      or exists(select 1 from jsonb_array_elements(target_good->'description_image_paths') item where jsonb_typeof(item)<>'string' or item='""'::jsonb)
    then raise check_violation using message='goods_description_images'; end if;
    image_paths:=array(select jsonb_array_elements_text(target_good->'description_image_paths'));
  else
    image_paths:=case when format_value='html' and description_value is not distinct from previous_good.description then coalesce(previous_good.description_image_paths,'{}') else '{}' end;
  end if;
  if format_value='plain' and cardinality(image_paths)>0 then raise check_violation using message='goods_description_images'; end if;
  before_value:=jsonb_build_object('format',coalesce(previous_good.description_format,'plain'),'description',previous_good.description,'imagePaths',coalesce(previous_good.description_image_paths,'{}'));
  saved:=private.admin_save_good_before_description(target_good-'description_format'-'description_image_paths');
  if previous_good.id is not null then
    -- The lower writer may have removed the old main/gallery/detail slot or
    -- renamed this draft. Preserve only this locked source row's verified paths
    -- across the final HTML update. The destination now exists under saved.id,
    -- so no authorization FK ever points at an intermediate or another good.
    insert into private.goods_artwork_copy_authorizations(transaction_id,target_good_id,source_good_id,actor_id,allowed_paths)
      values(txid_current(),saved->>'id',saved->>'id',v_actor_id,
        array_remove(array[previous_good.image_path,previous_good.detail_image_path]
          || coalesce(previous_good.gallery_paths,'{}') || coalesce(previous_good.description_image_paths,'{}'),null))
      on conflict(transaction_id,target_good_id) do nothing;
  end if;
  update public.goods set description_format=format_value,description_image_paths=image_paths where id=saved->>'id';
  if previous_good.id is not null then
    delete from private.goods_artwork_copy_authorizations permission
      where permission.transaction_id=txid_current() and permission.target_good_id=saved->>'id'
        and permission.source_good_id=saved->>'id' and permission.actor_id=v_actor_id;
  end if;
  after_value:=jsonb_build_object('format',format_value,'description',description_value,'imagePaths',image_paths);
  if before_value is distinct from after_value then
    insert into public.audit_log(actor_id,action,target,diff)
      values(v_actor_id,'admin.good.description_saved','goods:'||(saved->>'id'),jsonb_build_object('before',before_value,'after',after_value));
  end if;
  return saved;
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_english_name(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb; wants_publish boolean:=coalesce((target_good->>'publish')::boolean,false);
begin
 if not(target_good?'variants') then return private.admin_save_good_before_options(target_good); end if;
 saved:=private.admin_save_good_before_options(case when wants_publish then target_good||jsonb_build_object('publish',null) else target_good end);
 perform private.save_goods_options(saved->>'id',target_good->'variants',target_good->'variant_baseline',nullif(btrim(target_good->>'previous_id'),'') is null);
 if wants_publish then perform private.set_good_published(saved->>'id',true); end if;
 return saved||jsonb_build_object('default_variant_code',(select code from public.goods_variants where good_id=saved->>'id' and is_default));
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_external_identity(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  saved jsonb;
  previous_name text;
  next_name text;
  previous_search_keywords text[];
  next_search_keywords text[];
  previous_display_order integer;
  next_display_order integer;
  metadata_diff jsonb := '{}'::jsonb;
  has_search_keywords boolean := target_good ? 'search_keywords';
  has_display_order boolean := target_good ? 'display_order';
begin
  if auth.uid() is null or not public.is_staff() then
    raise insufficient_privilege using message='staff_required';
  end if;

  if target_good ? 'name_en' then
    if jsonb_typeof(target_good->'name_en') not in ('string','null') then
      raise check_violation using message='invalid_good_english_name';
    end if;
    next_name := nullif(btrim(target_good->>'name_en'), '');
    if char_length(next_name) > 200 then
      raise check_violation using message='invalid_good_english_name';
    end if;
  end if;

  if has_search_keywords then
    if target_good->'search_keywords' is null
      or jsonb_typeof(target_good->'search_keywords') = 'null' then
      next_search_keywords := '{}'::text[];
    elsif jsonb_typeof(target_good->'search_keywords') <> 'array'
      or jsonb_array_length(target_good->'search_keywords') > 50
      or exists (
        select 1 from jsonb_array_elements(target_good->'search_keywords') as item(value)
        where jsonb_typeof(item.value) <> 'string'
      )
      or exists (
        select 1 from jsonb_array_elements_text(target_good->'search_keywords') as item(value)
        where char_length(btrim(item.value)) > 80
      ) then
      raise check_violation using message='invalid_good_search_keywords';
    else
      select coalesce(array_agg(keyword order by ordinal), '{}'::text[])
        into next_search_keywords
      from (
        select distinct on (lower(btrim(item.value)))
          btrim(item.value) as keyword,
          item.ordinal
        from jsonb_array_elements_text(target_good->'search_keywords')
          with ordinality as item(value, ordinal)
        where btrim(item.value) <> ''
        order by lower(btrim(item.value)), item.ordinal
      ) as deduplicated;
      if not private.good_search_keywords_valid(next_search_keywords) then
        raise check_violation using message='invalid_good_search_keywords';
      end if;
    end if;
  end if;

  if has_display_order then
    if target_good->'display_order' is null
      or jsonb_typeof(target_good->'display_order') = 'null' then
      next_display_order := null;
    elsif jsonb_typeof(target_good->'display_order') <> 'number'
      or target_good->>'display_order' !~ '^[0-9]+$'
      or (target_good->>'display_order')::numeric > 2147483647 then
      raise check_violation using message='invalid_good_display_order';
    else
      next_display_order := (target_good->>'display_order')::integer;
    end if;
  end if;

  saved := private.admin_save_good_before_english_name(target_good);

  if target_good ? 'name_en' then
    select name_en into previous_name
    from public.goods
    where id=saved->>'id'
    for update;
    if previous_name is distinct from next_name then
      update public.goods set name_en=next_name where id=saved->>'id';
      insert into public.audit_log(actor_id,action,target,diff)
      values(auth.uid(),'admin.good.english_name_saved','goods:'||(saved->>'id'),
        jsonb_build_object('before',previous_name,'after',next_name));
    end if;
  end if;

  if has_search_keywords or has_display_order then
    select search_keywords, display_order
      into previous_search_keywords, previous_display_order
    from public.goods
    where id=saved->>'id'
    for update;

    if has_search_keywords and previous_search_keywords is distinct from next_search_keywords then
      update public.goods
      set search_keywords=next_search_keywords
      where id=saved->>'id';
      metadata_diff := metadata_diff || jsonb_build_object(
        'search_keywords_before', previous_search_keywords,
        'search_keywords_after', next_search_keywords
      );
    end if;
    if has_display_order and previous_display_order is distinct from next_display_order then
      update public.goods
      set display_order=next_display_order
      where id=saved->>'id';
      metadata_diff := metadata_diff || jsonb_build_object(
        'display_order_before', previous_display_order,
        'display_order_after', next_display_order
      );
    end if;
    if metadata_diff <> '{}'::jsonb then
      insert into public.audit_log(actor_id,action,target,diff)
      values(auth.uid(),'admin.good.discovery_metadata_saved','goods:'||(saved->>'id'),metadata_diff);
    end if;
  end if;

  return saved;
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_fulfillment(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid:=(select auth.uid());
  previous_id text:=nullif(btrim(target_good->>'previous_id'),'');
  target_id text:=nullif(btrim(target_good->>'id'),'');
  target_ip text:=target_good->>'ip_id';
  previous_ip text;
  previous_code text;
  requested_code text:=nullif(upper(btrim(target_good->>'code')),'');
  requested_variant_code text:=nullif(upper(btrim(target_good->>'default_variant_code')),'');
  saved_code text; saved_variant_code text;
begin
  if actor_id is null then raise invalid_authorization_specification using message='auth_required'; end if;
  if not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
  if jsonb_typeof(target_good) is distinct from 'object' then raise invalid_parameter_value using message='invalid_good'; end if;
  if previous_id is not null then
    perform pg_advisory_xact_lock(hashtextextended('admin_good:'||previous_id,0));
    select ip_id,code into previous_ip,previous_code from public.goods where id=previous_id for update;
    if not found then raise no_data_found using message='catalog_record_missing'; end if;
  end if;
  if target_id is null then
    perform pg_advisory_xact_lock(hashtextextended('goods_slug:'||private.goods_slug_from_name(target_good->>'name'),0));
    target_id:=private.available_goods_slug(target_good->>'name',previous_id);
  end if;
  if target_id !~ '^[a-z0-9][a-z0-9-]{0,63}$' then raise invalid_parameter_value using message='invalid_goods_slug'; end if;
  if previous_id is not null and previous_id is distinct from target_id then
    update public.goods set id=target_id where id=previous_id;
    update public.reward_policies set target_good_id=target_id where target_good_id=previous_id;
    update public.home_curations set payload=jsonb_set(payload,'{good_ids}',(
      select jsonb_agg(case when item=to_jsonb(previous_id) then to_jsonb(target_id) else item end order by position)
      from jsonb_array_elements(payload->'good_ids') with ordinality items(item,position)
    )) where jsonb_typeof(payload->'good_ids')='array' and payload->'good_ids' ? previous_id;
    update public.campaigns campaign set sections=(
      select jsonb_agg(case when jsonb_typeof(section->'good_ids')='array' and section->'good_ids' ? previous_id
        then jsonb_set(section,'{good_ids}',(
          select jsonb_agg(case when item=to_jsonb(previous_id) then to_jsonb(target_id) else item end order by item_position)
          from jsonb_array_elements(section->'good_ids') with ordinality items(item,item_position)
        )) else section end order by section_position)
      from jsonb_array_elements(campaign.sections) with ordinality sections(section,section_position)
    ) where campaign.sections @> jsonb_build_array(jsonb_build_object('good_ids',jsonb_build_array(previous_id)));
  end if;

  perform public.admin_upsert_good(
    target_id,target_ip,target_good->>'name',target_good->>'type',(target_good->>'price')::integer,
    target_good->>'badge',target_good->>'stock',target_good->>'bg',target_good->>'image_path',
    target_good->>'notice_maker',target_good->>'notice_origin',target_good->>'notice_material',target_good->>'notice_size',
    target_good->>'notice_made_on',target_good->>'notice_as_manager',target_good->>'notice_as_contact',
    target_good->>'description',array(select jsonb_array_elements_text(coalesce(target_good->'gallery_paths','[]'::jsonb))),
    target_good->>'detail_image_path',case when previous_id is null then null else target_id end,
    nullif(target_good->>'compare_at_price','')::integer,
    (target_good->>'publish')::boolean
  );
  if requested_code is not null then update public.goods set code=requested_code where id=target_id; end if;
  if requested_variant_code is not null then
    update public.goods_variants set code=requested_variant_code where good_id=target_id and is_default;
  end if;
  select code into saved_code from public.goods where id=target_id;
  select code into saved_variant_code from public.goods_variants where good_id=target_id and is_default;
  insert into public.audit_log(actor_id,action,target,diff) values(actor_id,'admin.good.identifiers_saved','goods:'||target_id,
    jsonb_build_object('previous_id',previous_id,'id',target_id,'previous_code',previous_code,'code',saved_code,'default_variant_code',saved_variant_code));
  return jsonb_build_object('id',target_id,'code',saved_code,'default_variant_code',saved_variant_code);
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_instant_discount_period(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous public.goods; saved jsonb; bounds jsonb; starts timestamptz; ends timestamptz;
 expected integer; saved_revision integer; changed boolean;
begin
 perform private.require_operator_capability('catalog.manage',false);
 if jsonb_typeof(target_good) is distinct from 'object' then raise invalid_parameter_value using message='invalid_good';end if;
 if not target_good ? 'sale_period' then return private.admin_save_good_before_sale_period(target_good);end if;
 bounds:=target_good->'sale_period';
 if jsonb_typeof(bounds) is distinct from 'object' or not bounds ?& array['startsAt','endsAt','expectedRevision']
  or (select count(*) from jsonb_object_keys(bounds))<>3
  or jsonb_typeof(bounds->'expectedRevision') is distinct from 'number' or bounds->>'expectedRevision' !~ '^(0|[1-9][0-9]*)$'
  or (bounds->>'expectedRevision')::numeric>2147483647 then raise check_violation using message='invalid_goods_sale_period';end if;
 expected:=(bounds->>'expectedRevision')::integer;
 if bounds->'startsAt'<>'null'::jsonb or bounds->'endsAt'<>'null'::jsonb then
  if jsonb_typeof(bounds->'startsAt') is distinct from 'string' or jsonb_typeof(bounds->'endsAt') is distinct from 'string'
   or bounds->>'startsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' or bounds->>'endsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' then
   raise check_violation using message='invalid_goods_sale_period';end if;
  begin starts:=(bounds->>'startsAt')::timestamptz;ends:=(bounds->>'endsAt')::timestamptz;
  exception when others then raise check_violation using message='invalid_goods_sale_period';end;
  if not isfinite(starts) or not isfinite(ends) or starts>=ends then raise check_violation using message='invalid_goods_sale_period';end if;
 end if;
 -- Same lock order as the delegated product editor, including category edits.
 perform private.lock_catalog_category_tree();
 select * into previous from public.goods where id=coalesce(nullif(target_good->>'previous_id',''),target_good->>'id') for update;
 if coalesce(previous.sale_period_revision,0)<>expected then raise sqlstate 'PT409' using message='goods_sale_period_changed';end if;
 saved:=private.admin_save_good_before_sale_period(target_good-'sale_period');
 changed:=previous.sale_starts_at is distinct from starts or previous.sale_ends_at is distinct from ends;
 update public.goods set sale_starts_at=starts,sale_ends_at=ends where id=saved->>'id'
  returning sale_period_revision into saved_revision;
 if changed then insert into public.audit_log(actor_id,action,target,diff)
  values(auth.uid(),'catalog.goods_sale_period_saved','goods:'||(saved->>'id'),
   jsonb_build_object('before',jsonb_build_object('startsAt',previous.sale_starts_at,'endsAt',previous.sale_ends_at),
    'after',jsonb_build_object('startsAt',starts,'endsAt',ends),'revision',saved_revision));end if;
 return saved||jsonb_build_object('salePeriodRevision',saved_revision);
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_kc(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb; current_good public.goods;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  saved:=private.admin_save_good_before_claim_policy(target_good-'claim_policy');
  if target_good?'claim_policy' then
    select * into current_good from public.goods where id=saved->>'id' for update;
    perform public.admin_save_good_claim_policy(current_good.id,target_good->'claim_policy',current_good.updated_at);
  end if;
  return saved;
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_options(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb; previous public.goods; updated public.goods; origin_key uuid; fee_type text; fee_value bigint;
begin
  if (select auth.uid()) is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  if target_good ? 'origin_id' then
    origin_key:=(target_good->>'origin_id')::uuid;
  end if;
  if target_good ? 'shipping_fee_type' then
    fee_type:=target_good->>'shipping_fee_type';
    if fee_type is null or fee_type not in ('policy','free','individual') then raise invalid_parameter_value using message='invalid_good_shipping_type'; end if;
  end if;
  if target_good ? 'individual_fee' then
    fee_value:=(target_good->>'individual_fee')::bigint;
    if fee_value is null or fee_value not between 0 and 1000000 then raise invalid_parameter_value using message='invalid_individual_fee'; end if;
  end if;
  -- Keep publication at its prior state while this transaction sets shipping.
  -- A new draft can fill its origin and publish in the same save.
  saved:=private.admin_save_good_before_fulfillment(case when target_good->>'publish'='true'
    and target_good ?| array['origin_id','shipping_fee_type','individual_fee'] then target_good||'{"publish":null}'::jsonb else target_good end);
  if target_good ?| array['origin_id','shipping_fee_type','individual_fee'] then
    select * into previous from public.goods where id=saved->>'id' for update;
    update public.goods set origin_id=case when target_good ? 'origin_id' then origin_key else origin_id end,shipping_fee_type=coalesce(fee_type,shipping_fee_type),
      individual_fee=coalesce(fee_value,individual_fee) where id=previous.id returning * into updated;
    insert into public.audit_log(actor_id,action,target,diff) values((select auth.uid()),'catalog.good.fulfillment_updated','goods:'||updated.id,
      jsonb_build_object('before',jsonb_build_object('origin_id',previous.origin_id,'shipping_fee_type',previous.shipping_fee_type,'individual_fee',previous.individual_fee),
        'after',jsonb_build_object('origin_id',updated.origin_id,'shipping_fee_type',updated.shipping_fee_type,'individual_fee',updated.individual_fee)));
  end if;
  if target_good->>'publish'='true' then perform public.admin_set_good_published(saved->>'id',true); end if;
  return saved;
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_purchase_cost(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb; current_good public.goods; category_value uuid; code_value text; code_id uuid;
  defer_publish boolean := false;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  if not (target_good ? 'category_id' or target_good ? 'category_code') then
    return private.admin_save_good_before_category(target_good);
  end if;
  perform private.lock_catalog_category_tree();
  if target_good ? 'category_id' then
    if jsonb_typeof(target_good->'category_id') not in ('string','null') then
      raise invalid_parameter_value using message='invalid_good_category';
    end if;
    begin category_value:=nullif(btrim(target_good->>'category_id'),'')::uuid;
    exception when invalid_text_representation then raise invalid_parameter_value using message='invalid_good_category'; end;
  end if;
  if target_good ? 'category_code' then
    if jsonb_typeof(target_good->'category_code') not in ('string','null') then
      raise invalid_parameter_value using message='invalid_good_category';
    end if;
    code_value:=nullif(btrim(target_good->>'category_code'),'');
    if code_value is not null then
      select id into code_id from public.catalog_categories where code=code_value;
      if not found then raise no_data_found using message='category_not_found'; end if;
    end if;
    if target_good ? 'category_id' and code_id is distinct from category_value then
      raise invalid_parameter_value using message='good_category_identity_mismatch';
    end if;
    category_value:=code_id;
  end if;
  -- 첫 공개는 카테고리를 바꾼 뒤에 한다(공개 판정이 새 대표 카테고리를 본다, ADR-0044).
  defer_publish:=target_good->>'publish'='true';
  saved:=private.admin_save_good_before_category(case when defer_publish
    then (target_good-'category_id'-'category_code')||'{"publish":null}'::jsonb else target_good-'category_id'-'category_code' end);
  select * into current_good from public.goods where id=saved->>'id' for update;
  if current_good.category_id is distinct from category_value then
    -- ADR-0044: 공개 중 상품은 다른 대표 카테고리로 옮길 수 있지만 비울 수는 없다(공개 조건).
    if current_good.published_at is not null and category_value is null then
      raise check_violation using message='goods_published_category_clear';
    end if;
    update public.goods set category_id=category_value where id=current_good.id;
    insert into public.audit_log(actor_id,action,target,diff)
      values(auth.uid(),'admin.catalog.good.category_changed','goods:'||current_good.id,
        jsonb_build_object('before',current_good.category_id,'after',category_value));
  end if;
  if defer_publish then perform public.admin_set_good_published(saved->>'id',true); end if;
  return saved;
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_sale_period(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb; previous public.goods; previous_values public.goods_attribute_values; schema_row public.catalog_category_attribute_schemas;
  submission jsonb; category uuid; code_value text; code_id uuid; next_entries jsonb; next_revision integer;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if auth.uid() is null or private.is_account_write_fenced(auth.uid()) then raise insufficient_privilege using message='staff_required'; end if;
  if auth.uid() is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='staff_required'; end if;
  if jsonb_typeof(target_good) is distinct from 'object' then raise invalid_parameter_value using message='invalid_good'; end if;
  perform private.lock_catalog_category_tree();
  select * into previous from public.goods where id=coalesce(nullif(target_good->>'previous_id',''),target_good->>'id') for update;
  category:=previous.category_id;
  if target_good ? 'category_id' then
    if jsonb_typeof(target_good->'category_id') not in ('string','null') then raise invalid_parameter_value using message='invalid_good_category'; end if;
    begin category:=nullif(btrim(target_good->>'category_id'),'')::uuid;
    exception when invalid_text_representation then raise invalid_parameter_value using message='invalid_good_category'; end;
  end if;
  if target_good ? 'category_code' then
    if jsonb_typeof(target_good->'category_code') not in ('string','null') then raise invalid_parameter_value using message='invalid_good_category'; end if;
    code_value:=nullif(btrim(target_good->>'category_code'),'');
    if code_value is not null then select id into code_id from public.catalog_categories where code=code_value;
      if not found then raise no_data_found using message='category_not_found'; end if; end if;
    if target_good ? 'category_id' and code_id is distinct from category then raise invalid_parameter_value using message='good_category_identity_mismatch'; end if;
    category:=code_id;
  end if;
  select * into previous_values from public.goods_attribute_values where good_id=previous.id for update;
  select * into schema_row from public.catalog_category_attribute_schemas where category_id=category for share;
  if target_good ? 'product_attributes' then
    submission:=target_good->'product_attributes';
    if jsonb_typeof(submission) is distinct from 'object' then raise check_violation using message='invalid_goods_attributes'; end if;
    if not submission ?& array['categoryId','schemaRevision','expectedRevision','values','removeIds'] or (select count(*) from jsonb_object_keys(submission))<>5
      or (submission->>'categoryId')::uuid is distinct from category
      or jsonb_typeof(submission->'schemaRevision') is distinct from 'number' or submission->>'schemaRevision' !~ '^(0|[1-9][0-9]*)$'
      or jsonb_typeof(submission->'expectedRevision') is distinct from 'number' or submission->>'expectedRevision' !~ '^(0|[1-9][0-9]*)$' then raise check_violation using message='invalid_goods_attributes'; end if;
    if (submission->>'schemaRevision')::numeric<>coalesce(schema_row.revision,0) then raise sqlstate 'PT409' using message='goods_attribute_schema_changed'; end if;
    if (submission->>'expectedRevision')::numeric<>coalesce(previous_values.revision,0) then raise sqlstate 'PT409' using message='goods_attributes_changed'; end if;
    next_entries:=private.merge_goods_attributes(coalesce(previous_values.entries,'[]'),coalesce(schema_row.fields,'[]'),submission->'values',submission->'removeIds');
  elsif previous.id is null or category is distinct from previous.category_id then
    -- Old clients may preserve an existing product unchanged. New/category-changed products still satisfy the current mandatory schema.
    next_entries:=private.merge_goods_attributes(coalesce(previous_values.entries,'[]'),coalesce(schema_row.fields,'[]'),'{}','[]');
  end if;
  saved:=private.admin_save_good_before_attributes(target_good-'product_attributes');
  if next_entries is not null and (next_entries<>coalesce(previous_values.entries,'[]') or submission is not null) then
    insert into public.goods_attribute_values(good_id,entries) values(saved->>'id',next_entries)
      on conflict(good_id) do update set entries=excluded.entries,revision=goods_attribute_values.revision+1,updated_at=clock_timestamp() returning revision into next_revision;
    insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'catalog.goods_attributes_saved','goods:'||(saved->>'id'),
      jsonb_build_object('before',coalesce(previous_values.entries,'[]'),'after',next_entries,'categoryId',category,'schemaRevision',coalesce(schema_row.revision,0),'revision',next_revision));
  end if;
  return saved||jsonb_build_object('attributesRevision',coalesce(next_revision,previous_values.revision,0));
end $function$

CREATE OR REPLACE FUNCTION private.admin_save_good_before_sales_policy(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  saved jsonb;
begin
  if auth.uid() is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
