CREATE OR REPLACE FUNCTION private.admin_shipment_export_before_preorder(target_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare expected_count integer;result jsonb;
begin
 if (select auth.uid()) is null or not public.is_staff() then raise insufficient_privilege using message='staff required';end if;
 expected_count:=cardinality(target_ids);
 if expected_count is null or expected_count not between 1 and 1000 or expected_count<>(select count(distinct id) from unnest(target_ids) id) then raise invalid_parameter_value using message='invalid_export_selection';end if;
 if (select count(*) from public.order_shipments s join public.orders o on o.id=s.order_id where s.id=any(target_ids)
   and s.status='ready' and o.status in ('confirmed','shipping'))<>expected_count then raise check_violation using message='shipment_not_ready';end if;
 if exists(select 1 from public.order_cancellation_requests r join public.order_shipments s on s.order_id=r.order_id where s.id=any(target_ids) and r.status in ('requested','processing','needs_review'))
 or exists(select 1 from public.order_cancellation_claims c join public.order_shipments s on s.order_id=c.order_id where s.id=any(target_ids))
 or exists(select 1 from public.order_shipments s where s.id=any(target_ids) and private.order_partial_cancel_in_flight(s.order_id)) then raise check_violation using message='order cancellation in progress';end if;
 if exists(select 1 from public.order_shipments s where s.id=any(target_ids) and private.order_fulfillment_held(s.order_id)) then raise check_violation using message='order fulfillment hold';end if;
 if (select count(*) from public.order_shipment_items where shipment_id=any(target_ids))>10000 then raise check_violation using message='export_item_limit';end if;
 select jsonb_build_object('shipments',jsonb_agg(jsonb_build_object('id',s.id,'updatedAt',s.updated_at,'originId',s.origin_id,
  'originName',s.origin_name_snapshot,'shippingFee',s.shipping_fee,'template',origin.export_template,'columns',origin.export_columns,
  'lines',coalesce((select jsonb_agg(jsonb_build_object('shipmentId',s.id,'orderId',o.id,'recipient',coalesce(private.operational_order_address(o.id)->>'recipientName',''),
   'phone',coalesce(private.operational_order_address(o.id)->>'phone',''),'postalCode',coalesce(private.operational_order_address(o.id)->>'postalCode',''),
   'address',concat_ws(' ',private.operational_order_address(o.id)->>'address1',nullif(private.operational_order_address(o.id)->>'address2','')),'goodCode',coalesce(g.code,i.good_id,''),
   'variantCode',coalesce(i.variant_code_snapshot,''),'goodName',i.good_name_snapshot,'optionName',concat_ws(' / ',nullif(i.variant_name_snapshot,''),(select string_agg((field->>'name')||': '||(field->>'value'),' / ' order by entry.ordinality) from jsonb_array_elements(i.custom_inputs_snapshot->'fields') with ordinality entry(field,ordinality))),'qty',link.qty,'unitPrice',i.unit_price,'deliveryNote',coalesce(private.operational_order_address(o.id)->>'deliveryNote',''),'carrier',coalesce(carrier.label,''),
   'barcode',coalesce(identity_snapshot.barcode,identity_live.barcode,''),
   'erpCode',coalesce(identity_snapshot.erp_code,identity_live.erp_code,''),
   'erpName',coalesce(identity_snapshot.erp_name,identity_live.erp_name,'')) order by i.id)
   from public.order_shipment_items link join public.order_items i on i.id=link.order_item_id left join public.goods g on g.id=i.good_id
   left join private.order_item_external_identity_snapshots identity_snapshot on identity_snapshot.order_item_id=i.id
   left join private.goods_variant_external_identity identity_live on identity_live.variant_id=i.variant_id
   where link.shipment_id=s.id),'[]')) order by origin.code,s.created_at,s.id)) into result
 from public.order_shipments s join public.orders o on o.id=s.order_id join public.fulfillment_origins origin on origin.id=s.origin_id
 left join public.shipping_carriers carrier on carrier.code=origin.default_carrier where s.id=any(target_ids);
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.admin_shipment_export_before_production(target_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare result jsonb;begin
 if auth.uid() is null or not public.has_operator_capability('sales.dispatch',false) then
  raise insufficient_privilege using message='operator_capability_required';end if;
 if exists(select 1 from public.order_shipments where id=any(target_ids) and delivery_method<>'parcel') then
  raise check_violation using message='delivery_method_evidence_required';end if;
 perform private.assert_whole_shipment_packs(target_ids);
 result:=private.admin_shipment_export_before_delivery_methods(target_ids);
 return jsonb_set(result,'{shipments}',(select jsonb_agg(entry.value||jsonb_build_object(
  'isGift',exists(select 1 from private.gift_intents g where g.order_id=s.order_id),
  'shippingCollectFee',s.shipping_collect_fee,'pack',private.shipment_pack_summary(s.id),
  'collector',(select group_value->'collector' from jsonb_array_elements(t.original_receipt#>'{display,shipping}') group_value
   where group_value->>'originId'=s.origin_id::text)) order by entry.ordinality)
  from jsonb_array_elements(result->'shipments') with ordinality entry(value,ordinality)
  join public.order_shipments s on s.id=(entry.value->>'id')::uuid
  left join private.order_goods_transactions t on t.order_id=s.order_id));
end $function$

CREATE OR REPLACE FUNCTION private.admin_update_shipment_status_before_delivery_methods(p_shipment_id uuid, p_status text, p_carrier text, p_tracking_number text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); shipment public.order_shipments; purchase public.orders;
 carrier_value text:=nullif(btrim(p_carrier),'');tracking_value text:=nullif(btrim(p_tracking_number),'');
begin
 if actor is null or not public.is_staff() then raise insufficient_privilege using message='staff required';end if;
 select o.* into purchase from public.orders o join public.order_shipments s on s.order_id=o.id where s.id=p_shipment_id for update of o;
 if not found then raise no_data_found using message='shipment_not_found';end if;
 select * into shipment from public.order_shipments where id=p_shipment_id for update;
 if p_status is null or p_status not in ('shipping','delivered') then raise check_violation using message='invalid_shipment_status';end if;
 if shipment.status=p_status then return;end if;
 if purchase.status not in ('confirmed','shipping','delivered')
   or not ((shipment.status='ready' and p_status='shipping') or (shipment.status='shipping' and p_status='delivered')) then
   raise check_violation using message='invalid_shipment_transition';
 end if;
 if p_status<>'delivered' then perform private.assert_order_dispatch_allowed(purchase.id);end if;
 carrier_value:=coalesce(carrier_value,shipment.carrier);tracking_value:=coalesce(tracking_value,shipment.tracking_number);
 if carrier_value is null or tracking_value is null then raise check_violation using message='tracking_required';end if;
 if tracking_value !~ '^[A-Z0-9]{8,30}$' then raise check_violation using message='invalid_tracking_input';end if;
 if carrier_value is distinct from shipment.carrier and not exists(select 1 from public.shipping_carriers where code=carrier_value and is_active) then
   raise check_violation using message='inactive_shipping_carrier';end if;
 if carrier_value is distinct from shipment.carrier or tracking_value is distinct from shipment.tracking_number then
   perform private.assert_tracking_registrable(carrier_value,tracking_value,array[shipment.id],null);end if;
 update public.order_shipments set status=p_status,carrier=carrier_value,tracking_number=tracking_value,
   shipped_at=case when p_status='shipping' then clock_timestamp() else shipped_at end,
   delivered_at=case when p_status='delivered' then clock_timestamp() else delivered_at end,updated_at=clock_timestamp()
   where id=p_shipment_id;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.shipment.status_updated','order:'||purchase.id,
   jsonb_build_object('shipmentId',shipment.id,'originName',shipment.origin_name_snapshot,'from',shipment.status,'to',p_status,'carrier',carrier_value,'trackingNumber',tracking_value));
end $function$

CREATE OR REPLACE FUNCTION private.admin_update_shipment_tracking_before_delivery_methods(p_shipment_id uuid, p_carrier text, p_tracking_number text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid());shipment public.order_shipments;purchase public.orders;
 carrier_value text:=nullif(btrim(p_carrier),'');tracking_value text:=nullif(btrim(p_tracking_number),'');
begin
 if actor is null or not public.is_staff() then raise insufficient_privilege using message='staff required';end if;
 select o.* into purchase from public.orders o join public.order_shipments s on s.order_id=o.id where s.id=p_shipment_id for update of o;
 if not found then raise no_data_found using message='shipment_not_found';end if;
 select * into shipment from public.order_shipments where id=p_shipment_id for update;
 if shipment.status not in ('shipping','delivered') or purchase.status='canceled' then raise check_violation using message='order_not_shipped';end if;
 if carrier_value is null or tracking_value is null then raise check_violation using message='tracking_required';end if;
 if tracking_value !~ '^[A-Z0-9]{8,30}$' then raise check_violation using message='invalid_tracking_input';end if;
 if shipment.carrier is not distinct from carrier_value and shipment.tracking_number is not distinct from tracking_value then return;end if;
 if carrier_value is distinct from shipment.carrier and not exists(select 1 from public.shipping_carriers where code=carrier_value and is_active) then
   raise check_violation using message='inactive_shipping_carrier';end if;
 perform private.assert_tracking_registrable(carrier_value,tracking_value,array[shipment.id],null);
 update public.order_shipments set carrier=carrier_value,tracking_number=tracking_value,updated_at=clock_timestamp() where id=p_shipment_id;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.shipment.tracking_updated','order:'||purchase.id,
   jsonb_build_object('shipmentId',shipment.id,'originName',shipment.origin_name_snapshot,'fromCarrier',shipment.carrier,'fromTrackingNumber',shipment.tracking_number,'toCarrier',carrier_value,'toTrackingNumber',tracking_value));
end $function$

CREATE OR REPLACE FUNCTION private.allocate_goods_code(target_ip_id text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare prefix_value text:=private.goods_code_prefix(target_ip_id); ordinal bigint; candidate text;
begin
  loop
    insert into private.goods_code_counters(prefix,last_number) values(prefix_value,1)
    on conflict(prefix) do update set last_number=private.goods_code_counters.last_number+1
    returning last_number into ordinal;
    candidate:=prefix_value||'-'||lpad(ordinal::text,greatest(4,length(ordinal::text)),'0');
    if not exists(select 1 from public.goods where code=candidate)
      and not exists(select 1 from public.goods_variants where code=candidate||'-01') then return candidate; end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION private.allocate_random_option_items(p_order_id uuid, p_user_id uuid, p_cart_item_id uuid, p_good_id text, p_cart_variant_id uuid, p_qty integer, p_at timestamp with time zone, p_custom_inputs jsonb, p_sales_policy jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare good public.goods; key_price record; candidate record; supply record; price record;
  pool_ids uuid[]:='{}'; pool_left integer[]:='{}'; pool_cap bigint[]:='{}'; pool_before jsonb:='[]'; counts integer[];
  pool_mode text; any_open boolean:=false; remaining bigint:=0; feasible bigint:=0; weight bigint; cap bigint; in_order bigint;
  roll bigint; walk bigint; slot integer; allocated jsonb:='[]';
  draw_rolls bigint[]; draw_bounds bigint[]; draw_slots integer[]; slot_draws jsonb[];
  draw uuid:=pg_catalog.gen_random_uuid(); item_id uuid; subtotal bigint:=0; step integer;
  rng constant text:='pgcrypto.gen_random_bytes:rejection';
begin
  if p_qty is null or p_qty<1 then raise check_violation using message='invalid cart item'; end if;
  select * into good from public.goods where id=p_good_id;
  if not found or good.option_sale_mode<>'random' then
    raise check_violation using message=format('random_option_unavailable: %s',p_good_id);
  end if;
  select * into key_price from private.resolve_goods_variant_price(p_cart_variant_id,p_at);
  for candidate in select v.id,v.order_max_qty,v.member_max_qty from public.goods_variants v
    where v.good_id=p_good_id and v.archived_at is null order by v.id for update loop
    select * into supply from private.resolve_goods_variant_supply(candidate.id,p_at);
    select * into price from private.resolve_goods_variant_price(candidate.id,p_at);
    -- 견적은 장바구니 키 옵션 가격으로 보였다. 배정 옵션 가격이 다르면 청구가 달라지므로 주문하지 않는다.
    -- 일반 재고·예약이 섞이면 배정에 따라 발송 약속이 달라지므로 주문하지 않는다(조건 함수가 저장도 막는다).
    if (pool_mode is not null and supply.mode<>pool_mode) or price.effective_price is distinct from key_price.effective_price
      or price.regular_price is distinct from key_price.regular_price then
      raise check_violation using message=format('random_option_unavailable: %s',p_good_id);
    end if;
    pool_mode:=supply.mode;
    any_open:=any_open or supply.state='open';
    cap:=null;
    if candidate.order_max_qty is not null then
      select coalesce(sum(item.qty::bigint),0) into in_order from public.order_items item
        where item.order_id=p_order_id and item.variant_id=candidate.id;
      cap:=greatest(candidate.order_max_qty-in_order,0);
    end if;
    if candidate.member_max_qty is not null then
      cap:=least(coalesce(cap,9223372036854775807),
        greatest(candidate.member_max_qty-private.member_variant_reserved_qty(p_user_id,candidate.id),0));
    end if;
    pool_ids:=pool_ids||candidate.id;
    pool_left:=pool_left||greatest(supply.available_qty,0);
    pool_cap:=array_append(pool_cap,cap);
    -- 증빙 모양은 상한이 없으면 20261028160100과 같다. 상한이 있으면 그 옵션의 배정 가능 잔여(capQty)를 더한다.
    pool_before:=pool_before||jsonb_build_array(jsonb_build_object('variantId',candidate.id,'availableQty',greatest(supply.available_qty,0))
      ||case when cap is null then '{}'::jsonb else jsonb_build_object('capQty',cap) end);
    remaining:=remaining+greatest(supply.available_qty,0);
    feasible:=feasible+least(greatest(supply.available_qty,0)::bigint,coalesce(cap,9223372036854775807));
  end loop;
  if cardinality(pool_ids)<2 then raise check_violation using message=format('random_option_unavailable: %s',p_good_id); end if;
  if pool_mode='preorder' then
    if not any_open then raise check_violation using message='preorder_sale_not_open'; end if;
    if remaining<p_qty then raise check_violation using message='preorder_capacity_exceeded'; end if;
  elsif remaining<p_qty then
    raise check_violation using message=format('out of stock: %s',p_good_id);
  end if;
  if feasible<p_qty then raise check_violation using message=format('random_option_limit_exceeded: %s',p_good_id); end if;
  counts:=array_fill(0,array[cardinality(pool_ids)]);
  -- 추출 근거는 고정 길이 배열에 모은다(원소 대입은 제자리라 수량에 선형). jsonb 변환은 루프 뒤 한 번이다.
  draw_rolls:=array_fill(0::bigint,array[p_qty]); draw_bounds:=array_fill(0::bigint,array[p_qty]); draw_slots:=array_fill(0,array[p_qty]);
  for step in 1..p_qty loop
    weight:=0;
    for slot in 1..cardinality(pool_ids) loop
      if pool_cap[slot] is null or counts[slot]<pool_cap[slot] then weight:=weight+pool_left[slot]; end if;
    end loop;
    roll:=private.random_below(weight);
    walk:=roll; slot:=1;
    loop
      if pool_cap[slot] is null or counts[slot]<pool_cap[slot] then
        exit when walk<pool_left[slot];
        walk:=walk-pool_left[slot];
      end if;
      slot:=slot+1;
    end loop;
    draw_rolls[step]:=roll; draw_bounds[step]:=weight; draw_slots[step]:=slot;
    pool_left[slot]:=pool_left[slot]-1; counts[slot]:=counts[slot]+1;
  end loop;
  -- 배정 행마다 그 옵션에 떨어진 추출만 담는다(같은 근거를 행마다 복사하지 않는다). 풀 순서(slot)대로 한 번에 묶는다.
  select array_agg(coalesce(grouped.steps,'[]'::jsonb) order by slot_index.value) into slot_draws
  from generate_series(1,cardinality(pool_ids)) slot_index(value)
  left join (select drawn.slot_no,jsonb_agg(jsonb_build_object('step',drawn.step,'roll',drawn.roll,'bound',drawn.bound,
        'variantId',pool_ids[drawn.slot_no]) order by drawn.step) steps
      from unnest(draw_rolls,draw_bounds,draw_slots) with ordinality drawn(roll,bound,slot_no,step)
      group by drawn.slot_no) grouped on grouped.slot_no=slot_index.value;
  for slot in 1..cardinality(pool_ids) loop
    continue when counts[slot]=0;
    select * into supply from private.resolve_goods_variant_supply(pool_ids[slot],p_at);
    select * into price from private.resolve_goods_variant_price(pool_ids[slot],p_at);
    if supply.mode='stock' then
      perform private.change_goods_variant_stock(p_good_id,pool_ids[slot],-counts[slot]::bigint);
    end if;
    insert into public.order_items(order_id,good_id,variant_id,qty,unit_price,good_name_snapshot,good_ip_id_snapshot,
      regular_unit_price_snapshot,price_period_id,price_evaluated_at,sales_policy_snapshot,supply_source,preorder_policy_id,
      preorder_expected_ship_date,preorder_snapshot,custom_inputs_snapshot,option_sale_mode_snapshot)
    values(p_order_id,p_good_id,pool_ids[slot],counts[slot],price.effective_price,good.name,good.ip_id,
      price.regular_price,price.price_period_id,p_at,p_sales_policy,supply.mode,supply.policy_id,supply.expected_ship_date,
      case when supply.mode='preorder' then jsonb_build_object('version',1,'policyId',supply.policy_id,
        'policyRevision',supply.policy_revision,'startsAt',supply.starts_at,'endsAt',supply.ends_at,
        'expectedShipDate',supply.expected_ship_date) end,
      p_custom_inputs,'random')
    returning id into item_id;
    if supply.mode='preorder' then
      perform private.reserve_goods_preorder_item(item_id,p_at);
    end if;
    insert into private.order_item_random_allocations(order_item_id,order_id,user_id,good_id,draw_id,cart_item_id,cart_variant_id,
      variant_id,qty,pool_before,draws,rng)
    values(item_id,p_order_id,p_user_id,p_good_id,draw,p_cart_item_id,p_cart_variant_id,pool_ids[slot],counts[slot],pool_before,slot_draws[slot],rng);
    allocated:=allocated||jsonb_build_array(jsonb_build_object('orderItemId',item_id,'variantId',pool_ids[slot],'qty',counts[slot]));
    subtotal:=subtotal+price.effective_price::bigint*counts[slot];
  end loop;
  insert into public.audit_log(actor_id,action,target,diff) values(p_user_id,'order.random_option_allocated','order:'||p_order_id,
    jsonb_build_object('drawId',draw,'goodId',p_good_id,'cartVariantId',p_cart_variant_id,'qty',p_qty,'rng',rng,
      'supplySource',pool_mode,'pool',pool_before,'allocations',allocated));
  return subtotal;
end $function$

CREATE OR REPLACE FUNCTION private.allocate_transaction_amount(p_total numeric, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$declare denominator numeric;result jsonb;begin
 if p_total is null or p_total<0 or p_total>9007199254740991 or trunc(p_total)<>p_total or jsonb_typeof(p_rows) is distinct from 'array'
  or jsonb_array_length(p_rows) not between 1 and 19239 then raise invalid_parameter_value using message='invalid_transaction_allocation';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) r where not private.transaction_json_keys(r,array['id','weight'])
  or jsonb_typeof(r->'id') is distinct from 'string' or char_length(r->>'id') not between 1 and 256 or not private.transaction_uint(r->'weight'))
  or (select count(distinct r->>'id') from jsonb_array_elements(p_rows) r)<>jsonb_array_length(p_rows) then
  raise invalid_parameter_value using message='invalid_transaction_allocation';end if;
 select sum((r->>'weight')::numeric) into denominator from jsonb_array_elements(p_rows) r;
 if denominator=0 then
  if p_total<>0 then raise invalid_parameter_value using message='transaction_allocation_zero_weight';end if;
  select jsonb_object_agg(r->>'id',0) into result from jsonb_array_elements(p_rows) r;return result;
 end if;
 with parts as(select r->>'id' id,trunc(p_total*(r->>'weight')::numeric/denominator) base,
   mod(p_total*(r->>'weight')::numeric,denominator) remainder from jsonb_array_elements(p_rows) r),
 ranked as(select *,row_number() over(order by remainder desc,id collate "C") position,sum(base) over() allocated from parts)
 select jsonb_object_agg(id,base+case when position<=p_total-allocated then 1 else 0 end) into result from ranked;
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.apply_goods_additional_categories(target_good_id text, target_category_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous_ids uuid[]; next_ids uuid[]; primary_id uuid; category_id uuid; category_row public.catalog_categories;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  perform private.lock_catalog_category_tree();
  select good.category_id into primary_id from public.goods good where good.id=target_good_id for update;
  if not found then raise no_data_found using message='goods_not_found'; end if;
  previous_ids:=private.goods_additional_category_ids(target_good_id);
  if target_category_ids is null or array_position(target_category_ids,null) is not null then
    raise invalid_parameter_value using message='invalid_additional_categories';
  end if;
  select coalesce(array_agg(id order by id),'{}'::uuid[]) into next_ids
    from (select distinct unnest(target_category_ids) as id) candidates where id is distinct from primary_id;
  if previous_ids=next_ids then return; end if;
  foreach category_id in array next_ids loop
    select * into category_row from public.catalog_categories category where category.id=category_id for share;
    if not found then raise foreign_key_violation using message='category_not_found'; end if;
    if category_row.archived_at is not null and not category_id=any(previous_ids) then
      raise check_violation using message='category_archived';
    end if;
    if exists(select 1 from public.catalog_categories where parent_id=category_id and archived_at is null) then
      raise check_violation using message='category_not_leaf';
    end if;
  end loop;
  delete from public.goods_additional_categories membership where membership.good_id=target_good_id and not membership.category_id=any(next_ids);
  insert into public.goods_additional_categories(good_id,category_id)
    select target_good_id,id from unnest(next_ids) ids(id) where not id=any(previous_ids);
  update public.goods set updated_at=clock_timestamp(), base_revision=base_revision+1 where id=target_good_id;
  insert into public.audit_log(actor_id,action,target,diff)
    values(auth.uid(),'admin.good.additional_categories_saved','goods:'||target_good_id,
      jsonb_build_object('before',to_jsonb(previous_ids),'after',to_jsonb(next_ids)));
end $function$

CREATE OR REPLACE FUNCTION private.apply_goods_discount_display(target_good_id text, target_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous_enabled boolean;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  if target_enabled is null then raise invalid_parameter_value using message='invalid_discount_display'; end if;
  select show_discount_rate into previous_enabled from public.goods where id=target_good_id for update;
  if not found then raise no_data_found using message='good_not_found'; end if;
  if previous_enabled is not distinct from target_enabled then return; end if;
  update public.goods set show_discount_rate=target_enabled where id=target_good_id;
  insert into public.audit_log(actor_id,action,target,diff)
    values(auth.uid(),'admin.good.discount_display_saved','goods:'||target_good_id,
      jsonb_build_object('before',jsonb_build_object('show_discount_rate',previous_enabled),
        'after',jsonb_build_object('show_discount_rate',target_enabled)));
end $function$

CREATE OR REPLACE FUNCTION private.apply_goods_import_guidance(p_batch_id uuid, p_index integer, p_good_id text, p_guidance jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
  item record;
  expected_revision integer;
  operation_id uuid;
begin
  perform private.require_actor_operator_capability(actor, 'catalog.manage');
  if p_guidance is null then return; end if;
  if p_batch_id is null or p_index is null or p_index < 0 or p_good_id is null
    or jsonb_typeof(p_guidance) <> 'object' or p_guidance = '{}'::jsonb
    or p_guidance - array['afterSales','sizeChart'] <> '{}'::jsonb then
    raise invalid_parameter_value using message = 'invalid_import_guidance';
  end if;
  if not exists (
    select 1 from public.admin_goods_imports batch
    where batch.id = p_batch_id and batch.actor_id = actor
      and p_index < jsonb_array_length(batch.plan)
      and batch.plan->p_index->'guidance' = p_guidance
  ) then raise insufficient_privilege using message = 'import_not_found'; end if;
  for item in select key, value from jsonb_each(p_guidance) order by key loop
    if jsonb_typeof(item.value) <> 'object'
      or not item.value ?& array['expectedRevision','values']
      or item.value - array['expectedRevision','values'] <> '{}'::jsonb
      or jsonb_typeof(item.value->'expectedRevision') <> 'number'
      or (item.value->>'expectedRevision') !~ '^(0|[1-9][0-9]{0,9})$'
      or jsonb_typeof(item.value->'values') <> 'object' then
      raise invalid_parameter_value using message = 'invalid_import_guidance';
    end if;
    if (item.value->>'expectedRevision')::numeric > 2147483646 then
      raise invalid_parameter_value using message = 'invalid_import_guidance';
    end if;
    expected_revision := (item.value->>'expectedRevision')::integer;
    -- A trusted batch, actor, row index and child kind fix the receipt identity.
    operation_id := md5('goods-import-guidance:v1:' || p_batch_id::text || ':' ||
      actor::text || ':' || p_index::text || ':' || item.key)::uuid;
    if item.key = 'afterSales' then
      perform public.admin_save_goods_after_sales_content(
        p_good_id, expected_revision, operation_id, item.value->'values');
    else
      perform public.admin_save_goods_size_chart(
        p_good_id, expected_revision, operation_id, item.value->'values');
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_goods_provider_cancellation(p_attempt_id uuid, p_provider_status text, p_provider_balance bigint, p_case_ref text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare attempt public.payment_attempts; payment public.payments; purchase public.orders; canceled bigint; recorded bigint; unexplained bigint;
  inserted integer; hold_id uuid; verdict text; observed bigint;
begin
  select * into attempt from public.payment_attempts where id = p_attempt_id;
  if attempt.id is null or attempt.provider <> 'toss' or attempt.purpose <> 'order' or attempt.ref_id is null
    or attempt.state <> 'approved' or attempt.payment_id is null then
    verdict := 'not_applicable';
  else
    -- 주문 → 결제 순서로 잠근다(취소·클레임 경로와 같은 순서).
    select * into purchase from public.orders where id = attempt.ref_id for update;
    select * into payment from public.payments where id = attempt.payment_id for share;
    if purchase.id is null or purchase.status = 'canceled' or payment.id is null or payment.status <> 'paid' then
      verdict := 'not_applicable';
    else
      select least(p_provider_balance, coalesce((select c.observed_balance from private.goods_provider_cancellation_checks c
        where c.attempt_id = attempt.id), p_provider_balance)) into observed;
      if p_provider_balance > payment.amount then raise invalid_parameter_value using message = 'invalid_provider_cancellation'; end if;
      canceled := payment.amount - observed;
      recorded := private.payment_partial_refunded_amount(payment.id);
      unexplained := canceled - recorded;
      if canceled = 0 or unexplained <= 0 then
        verdict := 'consistent';
      -- 우리가 결제사 취소를 냈을 수 있는 처리가 진행 중이면 미룬다. 접수만 된 요청(requested — 보류·회수 중 포함)은 결제사 취소를
      -- 낸 적이 없고, 교환은 환불을 만들지 않으므로 여기에 넣지 않는다.
      elsif exists(select 1 from public.order_cancellation_requests r where r.order_id = purchase.id
          and r.status in ('processing', 'needs_review') and r.claim_type <> 'exchange')
        or exists(select 1 from public.order_cancellation_claims c where c.order_id = purchase.id)
        or private.order_partial_cancel_in_flight(purchase.id)
        or exists(select 1 from public.refunds rf where rf.payment_id = payment.id and rf.status in ('requested', 'awaiting_transfer')) then
        verdict := 'in_flight';
      else
        insert into private.order_fulfillment_holds(order_id, reason, evidence_key, payment_attempt_id, detail)
        values (purchase.id, 'provider_canceled', 'provider_canceled:' || attempt.id::text || ':' || unexplained::text, attempt.id,
          jsonb_build_object('providerStatus', p_provider_status, 'providerCanceledAmount', canceled, 'recordedRefundedAmount', recorded,
            'unexplainedAmount', unexplained, 'paymentAmount', payment.amount, 'caseRef', p_case_ref))
        on conflict (order_id, reason, evidence_key) do nothing
        returning id into hold_id;
        get diagnostics inserted = row_count;
        if inserted = 0 then
          verdict := 'already_recorded';
        else
          verdict := 'held';
          insert into public.audit_log(actor_id, action, target, diff) values (null, 'system.order.fulfillment_hold_placed', 'order:' || purchase.id,
            jsonb_build_object('reason', 'provider_canceled', 'attemptId', attempt.id, 'providerStatus', p_provider_status,
              'providerCanceledAmount', canceled, 'recordedRefundedAmount', recorded, 'unexplainedAmount', unexplained, 'caseRef', p_case_ref));
          -- 결제사 직접 취소는 드물고 바로 확인할 일이라 운영 알림에도 남긴다(테스트 키 보류는 결제마다 생겨 알림에 싣지 않는다).
          insert into private.admin_operation_alerts(event_key, category, title, href)
          values ('order_fulfillment_holds:' || hold_id::text || ':placed', 'orders', '결제사에서 취소된 주문이 출고 보류되었습니다.', '/admin/sales/orders/' || purchase.id)
          on conflict (event_key) do nothing;
        end if;
      end if;
    end if;
  end if;
  -- 감지 기록: 관측을 남기고, 미룬 판정은 대기로 둔다(sweep이 다시 본다). 대상이 아닌 시도(주문 없음)는 남기지 않는다.
  if attempt.id is not null and attempt.ref_id is not null and exists(select 1 from public.orders where id = attempt.ref_id) then
    insert into private.goods_provider_cancellation_checks as checks(attempt_id, order_id, last_lookup_at, observed_status, observed_balance, observed_at,
      case_ref, pending, pending_since, last_verdict)
    values (attempt.id, attempt.ref_id, clock_timestamp(), p_provider_status, p_provider_balance, clock_timestamp(), p_case_ref,
      verdict = 'in_flight', case when verdict = 'in_flight' then clock_timestamp() end, verdict)
    on conflict (attempt_id) do update set
      observed_status = case when checks.observed_balance is null or excluded.observed_balance <= checks.observed_balance
        then excluded.observed_status else checks.observed_status end,
      observed_balance = least(coalesce(checks.observed_balance, excluded.observed_balance), excluded.observed_balance),
      observed_at = excluded.observed_at, case_ref = excluded.case_ref, pending = excluded.pending,
      pending_since = case when excluded.pending then coalesce(checks.pending_since, excluded.pending_since) end,
      last_verdict = excluded.last_verdict, updated_at = clock_timestamp();
  end if;
  return verdict;
end $function$

CREATE OR REPLACE FUNCTION private.apply_group_physical_stock_deltas(p_deltas jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item record;
begin
 if jsonb_typeof(p_deltas) is distinct from 'array' or jsonb_array_length(p_deltas)>2000 then
  raise check_violation using message='group_stock_deltas_invalid';
 end if;
 perform 1 from public.goods g where g.id in(select x->>'goodId' from jsonb_array_elements(p_deltas) x) order by g.id for update nowait;
 perform 1 from public.goods_variants v where v.id in(select (x->>'variantId')::uuid from jsonb_array_elements(p_deltas) x) order by v.id for update nowait;
 for item in select x->>'goodId' good_id,(x->>'variantId')::uuid variant_id,sum((x->>'delta')::bigint) delta
  from jsonb_array_elements(p_deltas) x group by 1,2 loop
  if not exists(select 1 from public.goods_variants v where v.id=item.variant_id and v.good_id=item.good_id) then
   raise check_violation using message='goods_stock_successor_pair_invalid';
  end if;
  if (select v.stock_qty::bigint+item.delta from public.goods_variants v where v.id=item.variant_id) not between 0 and 2147483647 then
   raise check_violation using message='insufficient_or_overflowing_stock';
  end if;
 end loop;
 for item in select x->>'goodId' good_id,sum((x->>'delta')::bigint) delta from jsonb_array_elements(p_deltas) x group by 1 loop
  if (select coalesce(sum(v.stock_qty::bigint),0)+item.delta from public.goods_variants v where v.good_id=item.good_id) not between 0 and 2147483647 then
   raise check_violation using message='stock_aggregate_overflow';
  end if;
 end loop;
 for item in select x->>'goodId' good_id,(x->>'variantId')::uuid variant_id,sum((x->>'delta')::bigint) delta
  from jsonb_array_elements(p_deltas) x group by 1,2 having sum((x->>'delta')::bigint)<>0 order by 1,3,2 loop
  perform private.change_goods_variant_stock(item.good_id,item.variant_id,item.delta::bigint);
 end loop;
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_order_claim_withdrawal(p_claim_id uuid, p_operation_id uuid, p_expected_revision integer, p_reason text, p_confirmed boolean, p_as_operator boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();purchase public.orders;claim public.order_cancellation_requests;previous private.order_claim_withdrawals;
 order_key uuid;buyer uuid;blocker text;kind text:=case when p_as_operator then 'operator' else 'customer' end;reason text:=btrim(p_reason);happened timestamptz;
begin
 if actor is null then raise insufficient_privilege using message='auth_required';end if;
 if p_as_operator and not private.has_operator_capability(actor,'sales.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 or p_confirmed is distinct from true
  or reason is null or char_length(reason) not between 2 and 500 or reason~'[[:cntrl:]]' then raise invalid_parameter_value using message='invalid_claim_withdrawal';end if;
 select c.order_id,o.user_id into order_key,buyer from public.order_cancellation_requests c join public.orders o on o.id=c.order_id where c.id=p_claim_id;
 if order_key is null or not p_as_operator and private.gift_claim_actor(p_claim_id) is distinct from actor then raise no_data_found using message='claim_not_found';end if;
 -- Existing-order recovery remains available to its owner, including suspended owners.
 perform private.lock_operator_subjects(array[actor,buyer]);
 if p_as_operator then perform private.require_actor_operator_capability(actor,'sales.manage',false);end if;
 perform pg_advisory_xact_lock(hashtextextended('claim-withdrawal:'||p_operation_id::text,0));
 select * into previous from private.order_claim_withdrawals where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.actor_kind<>kind or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision or previous.reason<>reason then
   raise unique_violation using message='claim_withdrawal_request_conflict';end if;
  return private.order_claim_withdrawal_receipt(p_operation_id,actor);
 end if;
 select * into purchase from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 perform shipment_id from public.order_claim_collections where claim_id=p_claim_id order by shipment_id for update;
 if claim.claim_revision<>p_expected_revision then raise sqlstate 'PT409' using message='claim_changed';end if;
 blocker:=private.order_claim_withdrawal_blocker(claim);
 if blocker is not null then raise check_violation using message=blocker;end if;
 happened:=clock_timestamp();
 insert into private.order_claim_withdrawals(id,claim_id,order_id,actor_id,actor_kind,expected_revision,reason,from_stage,created_at)
 values(p_operation_id,p_claim_id,order_key,actor,kind,p_expected_revision,reason,claim.stage,happened);
 update public.order_cancellation_requests set stage='withdrawn',withdrawn_at=happened,decided_at=happened,decided_by=actor,
  decision_note=null,held_from=null,hold_reason=null,held_at=null,updated_at=happened where id=p_claim_id;
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'order.claim_withdrawn','order:'||order_key,
  jsonb_build_object('claimId',p_claim_id,'claimType',claim.claim_type,'from',claim.stage,'to','withdrawn','actorKind',kind,'customerConfirmed',true));
 perform private.notify_order_claim(p_claim_id,'withdrawn','요청을 철회했어요',
  case when p_as_operator then '고객님과 확인한 요청 철회를 담당자가 기록했습니다. 주문과 결제는 유지되며 환불을 실행하지 않습니다.'
  else '요청을 철회했습니다. 주문과 결제는 유지되며 환불을 실행하지 않습니다.' end);
 return private.order_claim_withdrawal_receipt(p_operation_id,actor);
end $function$

CREATE OR REPLACE FUNCTION private.apply_order_partial_cancellation(p_id uuid, p_actor uuid, p_next_state text, p_follow_successor boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare head private.order_partial_cancellations; purchase public.orders; line record; ship_id uuid; obligation private.shipping_collect_obligations;
  policy record; remaining numeric; active_targets integer;
begin
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  if head.applied_at is not null then return; end if;
  if p_next_state not in ('completed', 'awaiting_transfer') then raise invalid_parameter_value using message = 'invalid_partial_cancel_state'; end if;
  select * into purchase from public.orders where id = head.order_id for update;
  perform s.id from public.order_shipments s where s.order_id = head.order_id order by s.id for update;
  if purchase.status not in ('paid', 'confirmed') or purchase.shipped_at is not null or purchase.delivered_at is not null
    or exists(select 1 from public.order_shipments s where s.order_id = head.order_id
      and (s.status not in ('ready', 'canceled') or s.shipped_at is not null or s.delivered_at is not null)) then
    raise check_violation using message = 'partial_cancel_state_changed';
  end if;
  for line in select l.*, link.qty as link_qty, link.shipment_id as link_shipment
    from private.order_partial_cancellation_items l
    left join public.order_shipment_items link on link.order_item_id = l.order_item_id and link.order_id = l.order_id
    where l.partial_cancellation_id = p_id order by l.order_item_id loop
    if line.link_qty is null or line.link_shipment <> line.shipment_id or line.link_qty < line.qty
      or private.order_item_partially_canceled_qty(line.order_item_id) <> line.canceled_qty_before then
      raise check_violation using message = 'partial_cancel_state_changed';
    end if;
  end loop;
  update private.order_partial_cancellations set state = p_next_state, applied_at = clock_timestamp(),
    completed_at = case when p_next_state = 'completed' then clock_timestamp() else completed_at end, last_error_code = null
  where id = p_id;
  for line in select * from private.order_partial_cancellation_items where partial_cancellation_id = p_id order by order_item_id loop
    delete from public.order_shipment_items where order_item_id = line.order_item_id and order_id = line.order_id and qty = line.qty;
    if not found then
      update public.order_shipment_items set qty = qty - line.qty where order_item_id = line.order_item_id and order_id = line.order_id;
    end if;
    perform private.restore_order_item_partial_supply(line.order_item_id, line.qty, p_id, '재고 부족 부분 취소', p_follow_successor);
  end loop;
  for ship_id in select shipment_id from private.order_partial_cancellation_shipments where partial_cancellation_id = p_id order by shipment_id loop
    if exists(select 1 from public.order_shipment_items where shipment_id = ship_id) then
      raise check_violation using message = 'partial_cancel_state_changed';
    end if;
    update public.order_shipments set status = 'canceled', updated_at = now() where id = ship_id and status = 'ready';
    select * into obligation from private.shipping_collect_obligations where shipment_id = ship_id for update;
    if found and obligation.state = 'planned' then
      update private.shipping_collect_obligations set state = 'void', revision = revision + 1, updated_at = clock_timestamp() where shipment_id = ship_id;
      insert into private.shipping_collect_events(operation_id, shipment_id, event, amount, evidence, previous_state, previous_revision)
      values (extensions.gen_random_uuid(), ship_id, 'void', 0,
        jsonb_build_object('orderId', head.order_id, 'reason', 'shipment_partially_canceled_before_dispatch', 'partialCancellationId', p_id),
        obligation.state, obligation.revision);
    end if;
  end loop;
  if head.store_credit_restore_amount > 0 then
    perform private.restore_order_store_credit_portion(head.order_id, purchase.user_id, head.store_credit_restore_amount);
  end if;
  -- 카드팩: 지급 조건(대상 품목이 있고 대상 금액 >= 최소 금액)의 거울이다. 정책 범위에 살아 있는 수량이 남은 대상 품목이 없거나
  -- 남은 수량의 대상 금액이 최소 금액에 못 미치면 열지 않은 카드팩을 회수한다(열어 본 것은 그대로). 최소 금액이 0원인 정책도
  -- 대상 품목이 모두 취소되면 회수한다(PR #652 리뷰).
  for policy in select distinct rp.id, rp.target_ip_id, rp.target_good_id, rp.min_amount
    from public.draw_tickets t join public.reward_policies rp on rp.id = t.reward_policy_id
    where t.source = 'order_paid' and t.source_id = head.order_id and t.consumed_at is null and t.revoked_at is null loop
    select coalesce(sum(private.order_item_active_qty(i.id)::numeric * i.unit_price), 0),
      count(*) filter (where private.order_item_active_qty(i.id) > 0)
      into remaining, active_targets
    from public.order_items i where i.order_id = head.order_id and i.good_ip_id_snapshot = policy.target_ip_id
      and (policy.target_good_id is null or i.good_id = policy.target_good_id);
    if active_targets = 0 or remaining < policy.min_amount then
      perform t.id from public.draw_tickets t where t.source = 'order_paid' and t.source_id = head.order_id
        and t.reward_policy_id = policy.id and t.consumed_at is null and t.revoked_at is null order by t.id for update;
      update public.draw_tickets set revoked_at = now() where source = 'order_paid' and source_id = head.order_id
        and reward_policy_id = policy.id and consumed_at is null and revoked_at is null;
    end if;
  end loop;
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor, 'admin.order.partial_cancellation_applied', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'state', p_next_state, 'provider', head.provider, 'refundAmount', head.refund_amount,
      'goodsRefundAmount', head.goods_refund_amount, 'shippingRefundAmount', head.shipping_refund_amount,
      'storeCreditRestoreAmount', head.store_credit_restore_amount,
      'lines', (select jsonb_agg(jsonb_build_object('orderItemId', l.order_item_id, 'shipmentId', l.shipment_id, 'qty', l.qty,
        'goodsRefundAmount', l.goods_refund_amount) order by l.order_item_id) from private.order_partial_cancellation_items l where l.partial_cancellation_id = p_id),
      'closedShipments', coalesce((select jsonb_agg(c.shipment_id order by c.shipment_id) from private.order_partial_cancellation_shipments c
        where c.partial_cancellation_id = p_id), '[]'::jsonb)));
  perform private.notify_order_partial_cancellation(p_id, 'applied');
end $function$

CREATE OR REPLACE FUNCTION private.apply_shipping_charge_group_assignment_locked(p_good_id text, p_group_id uuid, p_expected_group_revision integer, p_expected_assignment_revision integer, p_expected_assignment_version_id uuid, p_expected_family_good_ids text[], p_expected_final_good_updated_at timestamp with time zone, p_expected_origin_updated_at timestamp with time zone, p_operation_id uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare good public.goods;origin public.fulfillment_origins;previous private.shipping_charge_group_assignments;group_row private.shipping_charge_groups;
 version_id uuid:=gen_random_uuid();assignment_id uuid;revision integer;blocker text;guard jsonb;
begin
 perform private.require_shipping_charge_group_identity(p_actor,p_session);
 if p_good_id is null or p_operation_id is null or p_expected_group_revision is null or p_expected_group_revision<0
  or ((p_group_id is null) is distinct from (p_expected_group_revision=0))
  or p_expected_assignment_revision is null or p_expected_assignment_revision<0
  or ((p_expected_assignment_revision=0) is distinct from (p_expected_assignment_version_id is null))
  or p_expected_family_good_ids is null or cardinality(p_expected_family_good_ids) not between 1 and 100
  or array_position(p_expected_family_good_ids,null) is not null or p_expected_final_good_updated_at is null or not isfinite(p_expected_final_good_updated_at)
  or (p_expected_origin_updated_at is not null and not isfinite(p_expected_origin_updated_at)) then
  raise invalid_parameter_value using message='invalid_shipping_charge_group_assignment';end if;
 select * into good from public.goods where id=p_good_id and archived_at is null for update nowait;
 if not found then raise no_data_found using message='shipping_charge_group_goods_unavailable';end if;
 guard:=private.shipping_charge_group_good_guard(good);
 if good.updated_at is distinct from p_expected_final_good_updated_at
  or guard->'familyGoodIds' is distinct from to_jsonb(p_expected_family_good_ids) then
  raise sqlstate 'PT409' using message='shipping_charge_group_goods_changed';end if;
 if private.goods_aggregation_owner(good.id)<>good.id then raise check_violation using message='goods_aggregation_policy_owned_by_source';end if;
 select * into previous from private.shipping_charge_group_assignments where owner_good_id=good.id;
 if coalesce(previous.revision,0)<>p_expected_assignment_revision or previous.version_id is distinct from p_expected_assignment_version_id then
  raise sqlstate 'PT409' using message='shipping_charge_group_assignment_changed';end if;
 if good.origin_id is null and p_group_id is null and previous.group_id is null then
  if p_expected_origin_updated_at is not null then raise sqlstate 'PT409' using message='shipping_charge_group_origin_changed';end if;
  perform 1 from private.goods_transaction_runtime where singleton and enabled for share nowait;
  if not found then raise check_violation using message='checkout_contract_upgrade_required';end if;
  return guard;
 end if;
 select * into origin from public.fulfillment_origins where id=good.origin_id for share nowait;
 if not found or (p_group_id is not null and not origin.is_active) then raise check_violation using message='shipping_charge_group_origin_unavailable';end if;
 if origin.updated_at is distinct from p_expected_origin_updated_at then raise sqlstate 'PT409' using message='shipping_charge_group_origin_changed';end if;
 select * into group_row from private.shipping_charge_groups where id=p_group_id for share nowait;
 if p_group_id is not null and (not found or group_row.revision<>p_expected_group_revision) then
  raise sqlstate 'PT409' using message='shipping_charge_group_changed';end if;
 perform 1 from private.goods_transaction_runtime where singleton for share nowait;
 perform 1 from private.shipping_collect_contracts where origin_id=origin.id for share nowait;
 blocker:=private.shipping_charge_group_assignment_blocker(good,p_group_id,p_group_id is null);
 if blocker is not null then raise check_violation using message=blocker;end if;
 if previous.group_id is not distinct from p_group_id then return guard;end if;
 assignment_id:=coalesce(previous.id,gen_random_uuid());revision:=coalesce(previous.revision,0)+1;
 insert into private.shipping_charge_group_assignments(id,owner_good_id,group_id,revision,version_id,updated_by)
 values(assignment_id,good.id,p_group_id,revision,version_id,p_actor)
 on conflict(owner_good_id) do update set group_id=excluded.group_id,revision=excluded.revision,version_id=excluded.version_id,
  updated_by=p_actor,updated_at=greatest(clock_timestamp(),private.shipping_charge_group_assignments.updated_at+interval '1 microsecond');
 insert into private.shipping_charge_group_assignment_versions(id,assignment_id,revision,owner_good_id_at_write,origin_id,group_id,group_revision,created_by,session_id,operation_id)
 values(version_id,assignment_id,revision,good.id,origin.id,p_group_id,case when p_group_id is null then null else p_expected_group_revision end,p_actor,p_session,p_operation_id);
 -- Only templates which explicitly owned group assignment detach. A legacy or
 -- preserve directive still owns its original fields. The caller can attach its
 -- newly-applied template after this helper returns.
 if good.shipping_settings_snapshot#>>'{settings,chargeGroup,mode}' in('assign','clear')
  and good.shipping_settings_snapshot#>>'{appliedChargeGroup,groupId}' is distinct from p_group_id::text then
  update public.goods set updated_at=greatest(clock_timestamp(),updated_at+interval '1 microsecond'),
   shipping_settings_template_id=null,shipping_settings_template_revision=null,shipping_settings_snapshot=null where id=good.id returning * into good;
 else
  update public.goods set updated_at=greatest(clock_timestamp(),updated_at+interval '1 microsecond') where id=good.id returning * into good;
 end if;
 perform private.assert_shipping_charge_group_owner_assignment(good.id);
 return private.shipping_charge_group_good_guard(good);
exception when lock_not_available then raise sqlstate 'PT409' using message='shipping_charge_group_retry';
end $function$

CREATE OR REPLACE FUNCTION private.apply_shipping_notice_template_reference(target_good_id text, target_code text, target_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  template_id uuid;
  good_stamp timestamptz;
begin
  if nullif(btrim(coalesce(target_code, ''), E' \t\n\r'), '') is null then
    select updated_at into good_stamp from public.goods where id = target_good_id;
    if not found then raise no_data_found using message = 'good_not_found'; end if;
    return public.admin_apply_shipping_notice_template(target_good_id, null, good_stamp);
  end if;
  if target_version is null then raise invalid_parameter_value using message = 'shipping_notice_template_version_required'; end if;
  select id into template_id from public.shipping_notice_templates
    where code = btrim(target_code) and version = target_version;
  if not found then raise check_violation using message = 'shipping_notice_template_not_found'; end if;
  select updated_at into good_stamp from public.goods where id = target_good_id;
  if not found then raise no_data_found using message = 'good_not_found'; end if;
  return public.admin_apply_shipping_notice_template(target_good_id, template_id, good_stamp);
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_shipping_region_quote(p_base_quote jsonb, p_lines jsonb, p_destination jsonb, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare destination jsonb:=private.shipping_region_destination(p_destination); group_value jsonb; groups jsonb:='[]';
  origin public.fulfillment_origins; policy private.shipping_region_policies; managed_from timestamptz;
  rule jsonb; matched_rule jsonb; candidate_count integer; postal_candidates integer; eligible_goods integer;
  status text; mode text; contract_fee bigint; region_fee bigint; final_fee bigint; total bigint:=0;
  allowed boolean:=true; units integer; next_change timestamptz; group_change timestamptz; policy_present boolean;
begin
  if p_at is null or not isfinite(p_at) then raise invalid_parameter_value using message='shipping_quote_time_invalid'; end if;
  for group_value in select value from jsonb_array_elements(p_base_quote->'groups') loop
    select * into origin from public.fulfillment_origins where id=(group_value->>'originId')::uuid;
    if not found or not origin.is_active then raise check_violation using message='fulfillment_origin_inactive'; end if;
    select adoption.managed_from into managed_from from private.shipping_region_adoptions adoption where origin_id=origin.id;
    select min(moment) into group_change from (
      select region.starts_at moment from private.shipping_region_policies region where region.origin_id=origin.id and region.status='active' and region.starts_at>p_at
      union all select region.ends_at from private.shipping_region_policies region where region.origin_id=origin.id and region.status='active' and region.ends_at>p_at
      union all select managed_from where managed_from>p_at
    ) moments;
    next_change:=least(next_change,group_change);
    policy:=null; matched_rule:=null; units:=0; contract_fee:=null; region_fee:=null; final_fee:=null;
    policy_present:=false;
    if managed_from is null or p_at<managed_from then
      mode:='legacy_base_only'; status:='unconfigured'; region_fee:=0; final_fee:=(group_value->>'totalFee')::bigint;
    else
      mode:='managed';
      select region.* into policy from private.shipping_region_policies region where region.origin_id=origin.id and region.carrier_code=origin.default_carrier
        and region.status='active' and region.starts_at<=p_at and (region.ends_at is null or p_at<region.ends_at) order by region.starts_at desc limit 1;
      policy_present:=found;
      if not exists(select 1 from public.shipping_carriers where code=origin.default_carrier and is_active) then
        status:='carrier_mismatch'; policy_present:=false; policy:=null;
      elsif not policy_present then
        status:=case when exists(select 1 from private.shipping_region_policies region where region.origin_id=origin.id
          and region.status='active' and region.starts_at<=p_at and (region.ends_at is null or p_at<region.ends_at) and region.carrier_code<>origin.default_carrier)
          then 'carrier_mismatch' else 'policy_unavailable' end;
      elsif destination is null then status:='address_required';
      else
        candidate_count:=0; postal_candidates:=0;
        for rule in select value from jsonb_array_elements(policy.configuration->'rules')
          where value->>'postalFrom'<=destination->>'postalCode' and destination->>'postalCode'<=value->>'postalTo' loop
          postal_candidates:=postal_candidates+1;
          if rule->>'addressPrefix'='' or destination->>'address1'=rule->>'addressPrefix'
            or starts_with(destination->>'address1',(rule->>'addressPrefix')||' ') then
            candidate_count:=candidate_count+1; matched_rule:=rule;
          end if;
        end loop;
        if candidate_count>1 or (postal_candidates>0 and candidate_count=0) then
          status:='manual_review'; matched_rule:=null;
        elsif candidate_count=1 then status:=matched_rule->>'disposition';
        else status:=policy.configuration->>'unlistedDisposition'; end if;
        if status='standard' then contract_fee:=0; region_fee:=0;
        elsif status='surcharge' then
          contract_fee:=(matched_rule->>'amount')::bigint;
          select count(distinct line.good_id)::integer into eligible_goods
          from jsonb_to_recordset(p_lines) line(origin_id uuid,good_id text,fee_type text)
          where line.origin_id=origin.id and case line.fee_type
            when 'policy' then (policy.configuration->>'chargePolicyGoods')::boolean
              and not ((policy.configuration->>'waivePolicyThreshold')::boolean and group_value->>'freeThreshold' is not null
                and (group_value->>'policySubtotal')::bigint>=(group_value->>'freeThreshold')::bigint)
            when 'free' then (policy.configuration->>'chargeFreeGoods')::boolean
            when 'individual' then (policy.configuration->>'chargeIndividualGoods')::boolean else false end;
          units:=case when policy.configuration->>'feeUnit'='per_shipment' then least(eligible_goods,1) else eligible_goods end;
          region_fee:=contract_fee*units;
        end if;
        if region_fee is not null then final_fee:=(group_value->>'totalFee')::bigint+region_fee; end if;
      end if;
    end if;
    if final_fee is null then allowed:=false; end if;
    total:=total+(group_value->>'totalFee')::bigint+coalesce(region_fee,0);
    groups:=groups||jsonb_build_array(group_value||jsonb_build_object(
      'totalFee',(group_value->>'totalFee')::bigint+coalesce(region_fee,0),'regionMode',mode,'regionStatus',status,
      'regionalContractFee',contract_fee,'regionalFee',region_fee,'finalFee',final_fee,
      'policyId',case when policy_present then policy.id end,'policyVersion',case when policy_present then policy.version end,
      'ruleId',(matched_rule->>'id')::uuid,'regionLabel',matched_rule->>'regionLabel','carrierCode',origin.default_carrier,
      'feeUnit',case when policy_present then policy.configuration->>'feeUnit' end,'unitCount',units,
      'destinationPostalCode',destination->>'postalCode','matchedAddressPrefix',nullif(matched_rule->>'addressPrefix','')));
  end loop;
  return p_base_quote||jsonb_build_object('groups',groups,'totalFee',total,'finalTotalFee',case when allowed then total end,
    'checkoutAllowed',allowed,'destination',destination,'nextChangeAt',next_change);
end $function$

CREATE OR REPLACE FUNCTION private.assert_active_user(target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  selected_suspended_at timestamptz;
begin
  if target_user_id is null then
    raise exception 'profile_not_found' using errcode = '22023';
  end if;

  select profile.suspended_at
    into selected_suspended_at
  from public.profiles as profile
  where profile.id = target_user_id
  for share;

  if not found then
    raise exception 'profile_not_found' using errcode = '22023';
  end if;

  if selected_suspended_at is not null then
    raise exception 'account_suspended' using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_claim_destination_same_price(p_order uuid, p_before jsonb, p_after jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare before_value jsonb:=private.shipping_region_destination(p_before);after_value jsonb:=private.shipping_region_destination(p_after);
 shipment public.order_shipments;raw jsonb;policies jsonb;policy jsonb;group_value jsonb;old_match jsonb;new_match jsonb;counted integer:=0;
begin
 if before_value is null or after_value is null then raise sqlstate 'PT409' using message='claim_contact_address_price_unknown';end if;
 if before_value=after_value then return;end if;
 for shipment in select * from public.order_shipments where order_id=p_order order by id loop
  counted:=counted+1;raw:=shipment.shipping_fee_snapshot;policies:='[]';
  if shipment.delivery_method<>'parcel' then raise sqlstate 'PT409' using message='claim_contact_address_price_unknown';end if;
  if jsonb_typeof(raw->'chargeGroupContract')='object' then
   if jsonb_typeof(raw#>'{chargeGroupContract,originRegionPolicy,configuration}')='object' then
    policies:=policies||jsonb_build_array(raw#>'{chargeGroupContract,originRegionPolicy,configuration}');
   elsif raw#>>'{chargeGroupContract,originRegionResult,regionMode}'='legacy_base_only' then
    raise sqlstate 'PT409' using message='claim_contact_address_price_unknown';
   end if;
   for group_value in select value from jsonb_array_elements(raw#>'{chargeGroupContract,groups}') loop
    if group_value->>'regionMode'='override' then
     policies:=policies||jsonb_build_array(group_value#>'{versionSnapshot,policy_values,regional,policy}');
    elsif group_value->>'regionMode' is distinct from 'inherit' then raise sqlstate 'PT409' using message='claim_contact_address_price_unknown';end if;
   end loop;
  elsif raw->>'regionMode'='managed' and raw->>'policyId' is not null then
   select configuration into policy from private.shipping_region_policies where id=(raw->>'policyId')::uuid and version=(raw->>'policyVersion')::integer;
   if found then policies:=jsonb_build_array(policy);end if;
  end if;
  if jsonb_array_length(policies)=0 then raise sqlstate 'PT409' using message='claim_contact_address_price_unknown';end if;
  for policy in select value from jsonb_array_elements(policies) loop
   if jsonb_typeof(policy->'rules') is distinct from 'array' then raise sqlstate 'PT409' using message='claim_contact_address_price_unknown';end if;
   old_match:=private.shipping_charge_group_region_match(policy,before_value);new_match:=private.shipping_charge_group_region_match(policy,after_value);
   if old_match->>'fee' is null or new_match->>'fee' is null then raise sqlstate 'PT409' using message='claim_contact_address_price_unknown';end if;
   -- Compare each tariff independently: a fee increase at one origin cannot be hidden by a decrease at another.
   if old_match->'fee' is distinct from new_match->'fee' then raise sqlstate 'PT409' using message='claim_contact_address_price_changed';end if;
  end loop;
 end loop;
 if counted=0 then raise sqlstate 'PT409' using message='claim_contact_address_price_unknown';end if;
end $function$

