CREATE OR REPLACE FUNCTION private.assert_reply_extra_trackings(p_rows jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_value jsonb; shipment public.order_shipments; extras text[]; number text;
begin
  for row_value in select value from jsonb_array_elements(p_rows) loop
    if not (row_value ? 'extraTrackingNumbers') then continue; end if;
    select * into strict shipment from public.order_shipments where id = (row_value->>'reference')::uuid;
    extras := private.reply_extra_tracking_numbers(row_value->'extraTrackingNumbers', private.normalize_tracking_number(row_value->>'trackingNumber'));
    foreach number in array extras loop
      if shipment.status = 'ready' then
        perform private.assert_tracking_registrable(nullif(btrim(row_value->>'carrier'), ''), number, array[shipment.id], null);
      elsif not exists(select 1 from public.order_shipment_extra_trackings x where x.shipment_id = shipment.id
          and x.carrier = shipment.carrier and x.tracking_number = number) then
        raise check_violation using message = 'shipment_tracking_conflict';
      end if;
    end loop;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION private.assert_reply_recipient(p_order uuid, p_row jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare address jsonb; replied_name text; replied_phone text; stored_name text; stored_phone text;
begin
  if jsonb_typeof(p_row) is distinct from 'object' or not (p_row ? 'recipientName' or p_row ? 'recipientPhone') then return; end if;
  if (p_row ? 'recipientName' and jsonb_typeof(p_row->'recipientName') <> 'string')
    or (p_row ? 'recipientPhone' and jsonb_typeof(p_row->'recipientPhone') <> 'string') then
    raise invalid_parameter_value using message = 'invalid_tracking_row'; end if;
  -- 선물 주문은 orders.address가 비어 있고 받는 분은 배송 스냅샷에 있다 — 출고 화면과 같은 운영 주소를 읽는다.
  select private.operational_order_address(o.id) into address from public.orders o where o.id = p_order;
  if not found then return; end if;
  replied_name := lower(regexp_replace(coalesce(p_row->>'recipientName', ''), '[[:space:]]', '', 'g'));
  stored_name := lower(regexp_replace(coalesce(address->>'recipientName', ''), '[[:space:]]', '', 'g'));
  if replied_name <> '' and position('*' in replied_name) = 0 and stored_name <> ''
    and not starts_with(replied_name, stored_name) and not starts_with(stored_name, replied_name) then
    raise check_violation using message = 'tracking_reply_recipient_mismatch'; end if;
  replied_phone := btrim(coalesce(p_row->>'recipientPhone', ''));
  -- 주문에 저장된 값과 회신 값에 같은 전화번호 열쇠(숫자만, 국가번호 82·앞자리 0 제거)를 쓴다.
  stored_phone := private.tracking_phone_key(address->>'phone');
  if replied_phone ~ '^[0-9[:space:]()+.-]+$' then
    replied_phone := private.tracking_phone_key(replied_phone);
    if length(coalesce(replied_phone, '')) >= 8 and stored_phone is not null and replied_phone <> stored_phone then
      raise check_violation using message = 'tracking_reply_recipient_mismatch'; end if;
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.assert_shipping_charge_group_owner_assignment(p_good_id text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare owner public.goods;assignment private.shipping_charge_group_assignments;group_row private.shipping_charge_groups;begin
 select * into owner from public.goods where id=p_good_id;
 if not found then return;end if;
 select * into assignment from private.shipping_charge_group_assignments where owner_good_id=p_good_id;
 if not found then return;end if;
 if private.goods_aggregation_owner(p_good_id)<>p_good_id then raise check_violation using message='goods_aggregation_policy_owned_by_source';end if;
 if assignment.group_id is not null then
  select * into group_row from private.shipping_charge_groups where id=assignment.group_id;
