CREATE OR REPLACE FUNCTION private.close_direct_order_for_retry(p_user_id uuid, p_order_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hold private.cart_order_holds%rowtype;
  v_result text;
  v_status public.order_status;
  v_suspended_at timestamptz;
begin
  if p_user_id is null or p_order_id is null then
    raise invalid_parameter_value using message = 'invalid_checkout_retry';
  end if;
  select profile.suspended_at into v_suspended_at from public.profiles as profile where profile.id = p_user_id;
  if not found then
    raise exception 'profile_not_found' using errcode = '22023';
  end if;
  if v_suspended_at is not null then
    raise exception 'account_suspended' using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text, 0));
  select hold.* into v_hold from private.cart_order_holds as hold
  where hold.order_id = p_order_id and hold.user_id = p_user_id and hold.source in ('direct_checkout', 'direct_transaction');
  if not found then
    return null;
  end if;
  if v_hold.state = 'awaiting_payment' then
    v_result := private.close_unpaid_cart_order(p_order_id, '고객이 진행 중인 미결제 주문을 취소하고 주문을 계속함', 'customer_released');
    if v_result in ('payment_confirming', 'unresolved') then
      return 'payment_in_progress';
    end if;
  end if;
  select o.status into v_status from public.orders as o where o.id = p_order_id;
  if v_status = 'pending' and private.checkout_draft_order_payment_unresolved(p_order_id) then
    return 'payment_in_progress';
  end if;
  return case when v_status = 'canceled' then 'closed' else 'not_retryable' end;
end;
$function$

CREATE OR REPLACE FUNCTION private.close_unpaid_cart_order(p_order_id uuid, p_reason text, p_trigger text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.orders%rowtype;
  v_attempt public.payment_attempts%rowtype;
  v_has_attempt boolean := false;
  v_attempt_canceled boolean := false;
  v_request record;
  v_request_id uuid;
begin
  select o.* into v_order from public.orders as o where o.id = p_order_id for update;
  if not found or v_order.status <> 'pending' or v_order.payment_method <> 'card' then
    return 'not_pending';
  end if;
  -- finalize·claim과 같은 순서(주문 → account-action → profiles). 취소 트리거(등급 재계산)가
  -- profiles를 잠그기 전에 account-action을 먼저 쥐어, 같은 계정의 다른 주문 finalize와 엇갈려
  -- 기다리지 않게 한다.
  perform private.lock_account_action_subject(v_order.user_id);

  -- 같은 임계 구역: order → request → attempt (claim·finalizer·sweep과 같은 순서).
  select request.id, request.reason, request.status
    into v_request
  from public.order_cancellation_requests as request
  where request.order_id = p_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id desc
  limit 1
  for update;
  if found and v_request.status <> 'requested' then
    -- 승인된 결제의 취소(환불)가 진행 중이다. 돈이 움직였으므로 닫지 않는다.
    return 'unresolved';
  end if;

  select attempt.* into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'order' and attempt.ref_id = p_order_id
  for update;
  v_has_attempt := found;

  if v_has_attempt and v_attempt.state = 'confirming'
    and v_attempt.claim_expires_at is not null
    and v_attempt.claim_expires_at > pg_catalog.clock_timestamp()
  then
    return 'payment_confirming';
  end if;
  if (v_has_attempt and v_attempt.state in ('confirming', 'unknown', 'needs_review', 'approved'))
    or exists (
      select 1 from public.payments as payment
      where payment.purpose = 'order' and payment.ref_id = p_order_id
        and payment.status in ('pending', 'paid')
    )
  then
    return 'unresolved';
  end if;

  if v_has_attempt and v_attempt.state = 'prepared' then
    update public.payment_attempts as attempt
    set state = 'canceled', claim_token = null, claim_expires_at = null
    where attempt.id = v_attempt.id and attempt.state = 'prepared';
    v_attempt_canceled := found;
  end if;

  -- 보류를 먼저 닫아야 아래 취소 트리거가 사유를 order_closed로 덮지 않는다.
  update private.cart_order_holds
  set state = 'released', settled_at = pg_catalog.clock_timestamp(), release_reason = 'superseded'
  where order_id = p_order_id and state = 'awaiting_payment';

  if v_request.id is not null then
    -- 결제 중 접수된 고객 취소 요청. 시도가 결제 없이 끝났으므로(방금 canceled로
    -- 바꿨거나 이미 declined/canceled) sweep과 같이 요청을 종결하고 알린다.
    v_request_id := v_request.id;
    perform public.finalize_order_cancellation_with_provider_evidence(
      p_order_id, v_request.reason, array[]::text[]);
    update public.order_cancellation_requests as request
    set status = 'completed',
        completed_at = coalesce(request.completed_at, pg_catalog.clock_timestamp()),
        updated_at = pg_catalog.clock_timestamp()
    where request.id = v_request_id and request.status = 'requested';
    perform private.notify_order_claim(
      v_request_id, 'completed', '주문이 취소됐어요',
      '결제가 완료되지 않은 주문이라 결제 없이 취소했습니다.');
  else
    perform public.cancel_order(p_order_id, p_reason);
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    null,
    'system.order.unpaid_cart_order_closed',
    'order:' || p_order_id::text,
    pg_catalog.jsonb_build_object(
      'trigger', p_trigger,
      'attemptState', case when v_has_attempt then v_attempt.state::text end,
      'attemptCanceled', v_attempt_canceled,
      'requestId', v_request_id,
      'actor', 'system'
    )
  );
  return 'closed';
end;
$function$

CREATE OR REPLACE FUNCTION private.confirm_paid_order(p_order_id uuid, p_actor uuid, p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform private.assert_order_dispatch_allowed(p_order_id);
 update public.orders set status='confirmed',confirmed_at=clock_timestamp() where id=p_order_id and status='paid';
 if not found then raise exception using message='invalid_order_transition';end if;
 insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'admin.order.status_updated','order:'||p_order_id,
  jsonb_build_object('from','paid','to','confirmed')||coalesce(p_context,'{}'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION private.contact_assert_context(p_claim public.order_cancellation_requests, p_target text, p_command text, p_type text, p_revision integer, p_expected jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare view jsonb;due jsonb;begin
 if p_claim.claim_type<>p_type or p_claim.claim_revision<>p_revision then raise sqlstate 'PT409' using message='claim_contact_changed';end if;
 perform private.contact_runtime();due:=private.contact_retention(p_claim.id,clock_timestamp());
 if due->>'state'='purged' then raise sqlstate 'PT410' using message='claim_contact_purged';end if;
 if due->>'state'='due' then raise sqlstate 'PT410' using message='claim_contact_retention_due';end if;
 if private.contact_blocker(p_claim,p_target,p_command) is not null then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
 view:=private.contact_target(p_claim.order_id,p_claim.id,p_target,true,due);
 if view->>'piiState'<>'available' then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
 if not private.contact_keys(p_expected,array['sourceKind','sourceId','sourceRevision','sourceFingerprint','planRevision','piiVersion','addressHmac','addressHmacKeyVersion'])
 or not private.contact_digest(p_expected->'addressHmac') or not private.contact_key_version(p_expected->'addressHmacKeyVersion') then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 if p_expected-array['addressHmac','addressHmacKeyVersion'] is distinct from view->'source' then raise sqlstate 'PT409' using message='claim_contact_changed';end if;
 return view;
end $function$

CREATE OR REPLACE FUNCTION private.contact_base64url(p_value jsonb, p_bytes integer, p_max integer)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare value text;decoded bytea;begin
 if jsonb_typeof(p_value) is distinct from 'string' then return false;end if;value:=p_value#>>'{}';
 if length(value)>p_max or value!~'^[A-Za-z0-9_-]*$' or length(value)%4=1 then return false;end if;
 decoded:=decode(translate(value,'-_','+/')||repeat('=',(4-length(value)%4)%4),'base64');
 return(p_bytes is null or octet_length(decoded)=p_bytes) and rtrim(translate(replace(encode(decoded,'base64'),E'\n',''),'+/','-_'),'=')=value;
 exception when others then return false;end $function$

CREATE OR REPLACE FUNCTION private.contact_blocker(p_claim public.order_cancellation_requests, p_target text, p_command text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare stage text:=case when p_claim.stage='on_hold' then p_claim.held_from else p_claim.stage end;intake jsonb;row jsonb;
begin
 if p_claim.claim_type not in('return','exchange') or(p_target='reshipment' and p_claim.claim_type<>'exchange') then return 'not_applicable';end if;
 if exists(select 1 from public.orders where id=p_claim.order_id and status='canceled') or exists(select 1 from public.order_cancellation_claims where order_id=p_claim.order_id)
 or exists(select 1 from public.refunds r join public.payments p on p.id=r.payment_id where p.ref_id=p_claim.order_id and p.purpose='order') then return 'financial_state';end if;
 if stage is null or stage not in('requested','in_review','collecting','collected') then return 'claim_stage';end if;
 if p_target='reshipment' then
  if p_command='reshipment' then
   -- 이 migration 전의 클레임 단위 재출고 흔적이 있으면 배송 건 기록을 덧대지 않는다.
   if p_claim.reship_carrier is not null or p_claim.reship_tracking_number is not null or p_claim.reship_delivered_at is not null
   or exists(select 1 from private.group_claim_reshipment_receipts where claim_id=p_claim.id)
   or exists(select 1 from public.order_claim_reshipment_items where claim_id=p_claim.id and reshipment_id is null)
   or exists(select 1 from private.group_claim_reshipment_allocations where claim_id=p_claim.id and reshipment_id is null)
   or exists(select 1 from private.order_claim_reshipment_destinations where claim_id=p_claim.id and reshipment_id is null)
   or not exists(select 1 from private.claim_reshipment_targets(p_claim.id) t where not exists(
    select 1 from public.order_claim_reshipments r where r.claim_id=p_claim.id and r.shipment_id is not distinct from t.shipment_id)) then return 'reshipment_started';end if;
   if p_claim.stage not in('collecting','collected') or(p_claim.stage<>'collected' and not(p_claim.collection_policy='origin' and p_claim.collection_required)) then return 'claim_stage';end if;
   if not exists(select 1 from private.claim_reshipment_targets(p_claim.id) t where not exists(
    select 1 from public.order_claim_reshipments r where r.claim_id=p_claim.id and r.shipment_id is not distinct from t.shipment_id)
    and(not t.collection_tracked or t.collected_at is not null or p_claim.reason_type='defect')) then return 'collection_incomplete';end if;
  elsif p_claim.reshipped_at is not null or p_claim.reship_carrier is not null or p_claim.reship_tracking_number is not null or p_claim.reship_delivered_at is not null
  or exists(select 1 from private.claim_reshipment_items_read(p_claim.id)) or exists(select 1 from private.group_claim_reshipment_receipts where claim_id=p_claim.id)
  or exists(select 1 from public.order_claim_reshipments where claim_id=p_claim.id)
  or exists(select 1 from private.order_claim_reshipment_destinations where claim_id=p_claim.id) then return 'reshipment_started';end if;
 else
  if stage not in('requested','in_review') or p_claim.collecting_at is not null or p_claim.collected_at is not null
  or exists(select 1 from public.order_claim_collections where claim_id=p_claim.id and(collected_at is not null or collected_by is not null or evidence is not null)) then return 'collection_started';end if;
  if exists(select 1 from private.claim_collection_plans where claim_id=p_claim.id and requested_once) then return 'collection_started';end if;
  select payload->'collections' into intake from private.seller_order_claim_intakes where claim_id=p_claim.id;
  if found then
   if jsonb_typeof(intake) is distinct from 'array' or jsonb_array_length(intake)=0 then return 'collection_unknown';end if;
   for row in select value from jsonb_array_elements(intake) loop
    if not private.contact_keys(row,array['shipmentId','method','carrier','trackingNumber','note']) or not private.contact_uuid(row->'shipmentId')
    or row->>'method' is distinct from 'not_requested' or row->'carrier' is distinct from 'null'::jsonb or row->'trackingNumber' is distinct from 'null'::jsonb then return 'collection_started';end if;
   end loop;
  end if;
 end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION private.contact_lock_scope(p_order uuid, p_claim uuid, p_parties uuid[])
 RETURNS public.order_cancellation_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claim public.order_cancellation_requests;begin
 perform 1 from public.orders where id=p_order for update;
 if not found or private.contact_parties(p_order) is distinct from p_parties then raise sqlstate 'PT409' using message='claim_contact_changed';end if;
 perform 1 from public.order_shipments where order_id=p_order order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim and order_id=p_order for update;
 if not found or claim.claim_type not in('return','exchange') then raise no_data_found using message='claim_not_found';end if;
 perform 1 from public.order_claim_collections where claim_id=p_claim order by shipment_id for update;
 perform 1 from private.order_claim_contact_retention_cases where claim_id=p_claim order by case_ref for update;
 perform 1 from private.order_claim_contact_plans where claim_id=p_claim order by target for update;
 return claim;
end $function$

CREATE OR REPLACE FUNCTION private.contact_order_obligations(p_order uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare purchase public.orders;begin
 select * into purchase from public.orders where id=p_order;if not found then return 'operational_unknown';end if;
 if purchase.status not in('delivered','done','canceled') or exists(select 1 from public.order_cancellation_requests where order_id=p_order and status in('requested','processing','needs_review'))
 or exists(select 1 from public.order_cancellation_claims where order_id=p_order)
 or exists(select 1 from public.payments p where p.ref_id=p_order and p.purpose='order' and p.status='pending')
 or exists(select 1 from public.payment_attempts where ref_id=p_order and purpose='order' and(state in('prepared','confirming','unknown','needs_review') or(state='approved' and payment_id is null)))
 or exists(select 1 from public.refunds r join public.payments p on p.id=r.payment_id where p.ref_id=p_order and p.purpose='order' and r.status<>'done') then return 'operational_pending';end if;
 if purchase.status in('delivered','done') and not private.order_all_items_delivered(p_order) then return 'operational_unknown';end if;
 if purchase.status='canceled' and(not exists(select 1 from public.order_items where order_id=p_order)
 or exists(select 1 from public.order_items i where i.order_id=p_order and coalesce((select sum(l.qty) from public.order_shipment_items l join public.order_shipments s on s.id=l.shipment_id
 where l.order_item_id=i.id and l.order_id=p_order and s.shipped_at is not null and s.delivered_at is not null),0)<>private.order_item_active_qty(i.id))) then return 'operational_unknown';end if;
 if purchase.status='canceled' and(not exists(select 1 from public.order_cancellation_requests c where c.order_id=p_order and c.claim_type='return' and c.stage='completed' and c.collected_at is not null and c.completed_at is not null)
 or(purchase.total>0 and(not exists(select 1 from public.payments p join public.refunds r on r.payment_id=p.id where p.ref_id=p_order and p.purpose='order' and p.status='refunded' and r.status='done' and r.completed_at is not null)
 or exists(select 1 from public.payments p where p.ref_id=p_order and p.purpose='order' and p.status in('pending','paid'))))) then return 'operational_unknown';end if;
 -- 회수 생략으로 재출고한 배송 건은 입고 기록 없이도 끝난 회수다.
 if exists(select 1 from public.order_cancellation_requests c where c.order_id=p_order and private.claim_reshipment_delivery_pending(c))
 or exists(select 1 from public.order_cancellation_requests c where c.order_id=p_order and c.stage='completed' and c.collection_required and c.collected_at is null
  and not(c.claim_type='exchange' and private.claim_collections_complete(c.id)
   and exists(select 1 from public.order_claim_reshipments r where r.claim_id=c.id and r.collection_waived)))
 or exists(select 1 from public.order_cancellation_requests c join public.order_claim_collections x on x.claim_id=c.id where c.order_id=p_order and c.stage='completed' and c.collection_required
  and(x.collected_at is null or x.collected_by is null or x.evidence is null)
  and not exists(select 1 from public.order_claim_reshipments r where r.claim_id=x.claim_id and r.shipment_id=x.shipment_id and r.collection_waived))
 or exists(select 1 from public.refunds r join public.payments p on p.id=r.payment_id where p.ref_id=p_order and r.status='done' and r.completed_at is null)
 then return 'operational_unknown';end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION private.contact_require_identity(p_actor uuid, p_session uuid, p_capability text, p_admin boolean, p_parties uuid[], p_pii boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.role() is distinct from 'service_role' or p_actor is null or p_session is null then raise insufficient_privilege using message='auth_changed';end if;
 perform private.gift_lock_subjects(array_append(coalesce(p_parties,'{}'),p_actor));
 -- Membership updates use the same subject fence. Keep that membership locked
 -- through completion even when a caller is retrying a historical operation.
 perform private.lock_operator_subjects(array[p_actor]);
 perform 1 from auth.sessions where id=p_session and user_id=p_actor and(not_after is null or not_after>clock_timestamp()) for share;
 if not found or exists(select 1 from public.profiles where id=p_actor and suspended_at is not null)
 or exists(select 1 from private.account_action_fences where subject_user_id=p_actor)
 or(p_capability is not null and (not private.has_operator_capability(p_actor,p_capability,p_admin)
  or not private.operator_mfa_service_session_ok(p_actor,p_session))) then
 raise insufficient_privilege using message='auth_changed';end if;
 if p_pii and exists(select 1 from private.account_action_fences where subject_user_id=any(p_parties)) then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
end $function$

CREATE OR REPLACE FUNCTION private.contact_retention(p_claim uuid, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.order_cancellation_requests;state text;ended timestamptz;base_at timestamptz;effective timestamptz;hold_until timestamptz;active_count integer;expired_count integer;
begin
 select * into c from public.order_cancellation_requests where id=p_claim;
 state:=private.contact_order_obligations(c.order_id);
 if state is null then
  ended:=case c.stage when 'completed' then c.completed_at when 'rejected' then c.decided_at when 'withdrawn' then c.withdrawn_at else null end;
  if c.stage not in('completed','rejected','withdrawn') then state:='operational_pending';elsif ended is null or not isfinite(ended) or ended>p_now then state:='operational_unknown';end if;
 end if;
 select count(*) filter(where r.state='held' and r.retain_until>p_now),count(*) filter(where r.state='held' and r.retain_until<=p_now),max(r.retain_until) filter(where r.state='held' and r.retain_until>p_now)
 into active_count,expired_count,hold_until from private.order_claim_contact_retention_cases r where r.claim_id=p_claim;
 if state is null then
  select greatest(ended,(select max(delivered_at) from public.order_shipments where order_id=c.order_id),
   (select max(greatest(completed_at,reship_delivered_at,decided_at,withdrawn_at,operational_fee_confirmed_at)) from public.order_cancellation_requests where order_id=c.order_id),
   (select max(r.delivered_at) from public.order_claim_reshipments r where r.order_id=c.order_id),
   (select max(r.completed_at) from public.refunds r join public.payments p on p.id=r.payment_id where p.ref_id=c.order_id and p.purpose='order'),
   (select max(case_closed_at) from private.order_claim_contact_retention_cases where claim_id=p_claim and legal_basis='dispute_resolution')) into ended;
  base_at:=ended+interval '30 days';effective:=greatest(base_at,hold_until);
  state:=case when effective<=p_now then 'due' when hold_until>base_at then 'held' else 'not_due' end;
 end if;
 if exists(select 1 from private.order_claim_contact_plans where claim_id=p_claim and purged_at is not null) then state:='purged';end if;
 return jsonb_build_object('state',state,'purposeEndedAt',ended,'basePurgeAt',base_at,'effectivePurgeAt',effective,'activeHoldCount',active_count,'expiredHoldCount',expired_count);
end $function$

CREATE OR REPLACE FUNCTION private.contact_source_address(p_raw jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare field text;value text;address jsonb;begin
 if jsonb_typeof(p_raw) is distinct from 'object' or not p_raw ?& array['recipientName','phone','postalCode','address1'] then return null;end if;
 foreach field in array array['recipientName','phone','postalCode','address1','address2'] loop
  if field='address2' and(p_raw->field is null or p_raw->field='null') then continue;end if;
  if jsonb_typeof(p_raw->field) is distinct from 'string' or p_raw->>field~('['||chr(1)||'-'||chr(31)||chr(127)||'-'||chr(159)||']') then return null;end if;
 end loop;
 if p_raw->>'phone'!~'^[0-9 ()+-]+$' then return null;end if;
 address:=jsonb_build_object('recipientName',private.contact_trim(p_raw->>'recipientName'),
 'phone',regexp_replace(p_raw->>'phone','[ ()+-]','','g'),'postalCode',p_raw->>'postalCode','address1',p_raw->>'address1',
 'address2',private.contact_trim(coalesce(p_raw->>'address2','')));
 if char_length(address->>'recipientName') not between 1 and 50 or address->>'phone'!~'^[0-9]{8,15}$'
 or char_length(address->>'postalCode') not between 1 and 20 or private.contact_trim(address->>'postalCode')=''
 or char_length(address->>'address1') not between 1 and 200 or private.contact_trim(address->>'address1')='' or char_length(address->>'address2')>200 then return null;end if;
 return address;
end $function$

CREATE OR REPLACE FUNCTION private.contact_target(p_order uuid, p_claim uuid, p_target text, p_access boolean, p_due jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.order_cancellation_requests;plan private.order_claim_contact_plans;raw jsonb;address jsonb;source jsonb;kind text;source_id uuid;source_revision text;
 result jsonb:=jsonb_build_object('target',p_target,'piiState','unavailable','source',null,'referenceOnly',false,'sourceAddress',null,'plan',null,'unavailableReason','source_unavailable');
begin
 select * into c from public.order_cancellation_requests where id=p_claim and order_id=p_order;
 if p_target='reshipment' and c.claim_type<>'exchange' then return result||jsonb_build_object('piiState','not_applicable','unavailableReason',null);end if;
 if not p_access then return result||jsonb_build_object('piiState','restricted','unavailableReason',null);end if;
 -- Do not read a source address or ciphertext until lifecycle gates pass.
 if p_due->>'state'='purged' then return result||jsonb_build_object('piiState','purged','unavailableReason',null);end if;
 if p_due->>'state'='due' then return result||jsonb_build_object('unavailableReason','retention_due');end if;
 select * into plan from private.order_claim_contact_plans where claim_id=p_claim and target=p_target;
 if found then
  if plan.purged_at is not null then return result||jsonb_build_object('piiState','purged','unavailableReason',null);end if;
  return result||jsonb_build_object('piiState','available','unavailableReason',null,'plan',plan.sealed_plan,
   'source',jsonb_build_object('sourceKind','contact_plan','sourceId',plan.id,'sourceRevision',null,'sourceFingerprint',null,'planRevision',plan.revision,'piiVersion',plan.pii_version));
 end if;
 if p_target='collection' then
  select payload->'collectionAddress' into raw from private.seller_order_claim_intakes where claim_id=p_claim;
  if found then kind:='seller_intake';source_id:=p_claim;end if;
 end if;
 if kind is null then
  source:=private.order_delivery_snapshot(p_order);raw:=source->'address';kind:='order_delivery';source_id:=p_order;source_revision:=source->>'addressRevision';
  if source_revision is null or source_revision!~'^(0|[1-9][0-9]*)$' then return result;end if;
 end if;
 address:=private.contact_source_address(raw);if address is null then return result;end if;
 source:=jsonb_build_object('sourceKind',kind,'sourceId',source_id,'sourceRevision',source_revision,'planRevision',0,'piiVersion',null,
 'sourceFingerprint',encode(extensions.digest(convert_to(jsonb_build_array('claim-contact-source-v1',p_order,p_claim,p_target,kind,source_id,source_revision,
 raw->>'recipientName',raw->>'phone',raw->>'postalCode',raw->>'address1',coalesce(raw->>'address2',''))::text,'UTF8'),'sha256'),'hex'));
 return result||jsonb_build_object('piiState','available','unavailableReason',null,'source',source,'sourceAddress',address,'referenceOnly',kind='order_delivery');
end $function$

CREATE OR REPLACE FUNCTION private.coupon_good_matches(p_scope text, p_goods text[], p_categories uuid[], p_good text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare matches boolean;
begin
 if p_scope='all' then return true;end if;
 if p_scope='selected_goods' then return p_good=any(p_goods) or private.goods_aggregation_owner(p_good)=any(p_goods);end if;
 if p_scope is distinct from 'selected_categories' then return false;end if;
 -- Checkout already holds goods rows. Do not wait behind a category writer that
 -- can hold the tree lock while waiting for those same rows. Fail and re-quote.
 if not pg_try_advisory_xact_lock_shared(hashtextextended('catalog_category_tree',0)) then
  raise exception using errcode='PT409',message='coupon_category_changed';end if;
 with recursive assigned as (
  select g.category_id as id from public.goods g where g.id=p_good and g.category_id is not null
  union select a.category_id from public.goods_additional_categories a where a.good_id=p_good
 ), ancestors(start_id,id,parent_id,active,matched,visited) as (
  select c.id,c.id,c.parent_id,c.archived_at is null,c.id=any(p_categories),array[c.id]
   from public.catalog_categories c join assigned a on a.id=c.id
  union all select a.start_id,c.id,c.parent_id,a.active and c.archived_at is null,a.matched or c.id=any(p_categories),a.visited||c.id
   from public.catalog_categories c join ancestors a on a.parent_id=c.id
   where cardinality(a.visited)<4 and not c.id=any(a.visited)
 ) select exists(select 1 from ancestors where parent_id is null and active and matched) into matches;
 return matches;
end $function$

CREATE OR REPLACE FUNCTION private.coupon_line_eligible_now(p_terms jsonb, p_good text, p_ip text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare scope text:=p_terms->>'goodsScope'; categories uuid[]; category_match boolean;
begin
  if p_terms is null or p_good is null or jsonb_typeof(p_terms)<>'object' then return null; end if;
  if scope='all' then return true; end if;
  if scope='selected_goods' then
    return coalesce(p_good in (select jsonb_array_elements_text(coalesce(p_terms->'targetGoodIds','[]'::jsonb))),false)
      or coalesce(private.goods_aggregation_owner(p_good) in (select jsonb_array_elements_text(coalesce(p_terms->'targetGoodIds','[]'::jsonb))),false);
  end if;
  if scope='selected_ips' then
    return p_ip is not null and coalesce(p_ip in (select jsonb_array_elements_text(coalesce(p_terms->'targetIpIds','[]'::jsonb))),false);
  end if;
  if scope is distinct from 'selected_categories' then return null; end if;
  categories:=array(select value::uuid from jsonb_array_elements_text(coalesce(p_terms->'targetCategoryIds','[]'::jsonb)) value);
  -- private.coupon_good_matches의 카테고리 분기와 같은 판정이다(읽기 전용이라 체크아웃 잠금은 잡지 않는다).
  with recursive assigned as (
    select g.category_id as id from public.goods g where g.id=p_good and g.category_id is not null
    union select a.category_id from public.goods_additional_categories a where a.good_id=p_good
  ), ancestors(start_id,id,parent_id,active,matched,visited) as (
    select c.id,c.id,c.parent_id,c.archived_at is null,c.id=any(categories),array[c.id]
      from public.catalog_categories c join assigned a on a.id=c.id
    union all select a.start_id,c.id,c.parent_id,a.active and c.archived_at is null,a.matched or c.id=any(categories),a.visited||c.id
      from public.catalog_categories c join ancestors a on a.parent_id=c.id
      where cardinality(a.visited)<4 and not c.id=any(a.visited)
  ) select exists(select 1 from ancestors where parent_id is null and active and matched) into category_match;
  return category_match;
end $function$

CREATE OR REPLACE FUNCTION private.create_goods_group_product(p_source_good_id text, p_source_variant_id uuid, p_name text, p_actor uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 source_good public.goods;source_variant public.goods_variants;category_value uuid;
 source_variants jsonb;target_payload jsonb;source_attribute_entries jsonb;clone_attribute_fields jsonb;clone_attribute_revision integer;
 clone_attribute_submission jsonb;clone_attribute_entries jsonb;saved jsonb;saved_id text;actor_id uuid:=p_actor;
 category_ids uuid[];
begin
 select * into source_good from public.goods where id=p_source_good_id;
 select * into source_variant from public.goods_variants where id=p_source_variant_id and good_id=p_source_good_id and archived_at is null;
 if source_good.id is null or source_variant.id is null or p_actor is distinct from auth.uid()
   or p_name is null or char_length(p_name) not between 1 and 200 then
  raise check_violation using message='goods_group_source_invalid';end if;
 category_value:=source_good.category_id;
 if category_value is not null and not exists(select 1 from public.catalog_categories c where c.id=category_value and c.archived_at is null
  and not exists(select 1 from public.catalog_categories child where child.parent_id=c.id and child.archived_at is null)) then
  raise check_violation using message='goods_group_category_review_required';end if;
 source_variants:=jsonb_build_array(jsonb_build_object('name','기본 옵션','attributes','{}'::jsonb,'extraPrice',0,'stockQty',0,
   'isActive',true,'lowStockThreshold',source_variant.low_stock_threshold));
  target_payload := pg_catalog.jsonb_build_object(
    'id', null,
    'code', null,
    'ip_id', source_good.ip_id,
    'name', p_name,
    'name_en', source_good.name_en,
    'origin_id', source_good.origin_id,
    'shipping_fee_type', source_good.shipping_fee_type,
    'individual_fee', source_good.individual_fee,
    'allow_card_payment', source_good.allow_card_payment,
    'allow_bank_transfer', source_good.allow_bank_transfer,
    'sale_restriction', source_good.sale_restriction,
    'order_quantity_limit_enabled', source_good.order_quantity_limit_enabled,
    'min_order_qty', source_good.min_order_qty,
    'max_order_qty', source_good.max_order_qty,
    'member_purchase_limit_enabled', source_good.member_purchase_limit_enabled,
    'member_lifetime_qty_limit', source_good.member_lifetime_qty_limit,
    'claim_policy', jsonb_build_object('returnAllowed',source_good.claim_return_allowed,
      'exchangeAllowed',source_good.claim_exchange_allowed,'restrictionReason',source_good.claim_restriction_reason,
      'returnFee',source_good.claim_return_fee,'returnFreeShippingFee',source_good.claim_return_free_shipping_fee,
      'exchangeFee',source_good.claim_exchange_fee,'returnAddressId',source_good.return_address_id),
    'price', source_variant.price,
    'compare_at_price', case when source_good.compare_at_price is null then null else source_good.compare_at_price+(source_variant.price-source_good.price) end,
    'badge', source_good.badge,
    'stock', 'ok',
    'bg', source_good.bg,
    'image_path', null,
    'notice_maker', source_good.notice_maker,
    'notice_origin', source_good.notice_origin,
    'notice_material', source_good.notice_material,
    'notice_size', source_good.notice_size,
    'notice_made_on', source_good.notice_made_on,
    'notice_as_manager', source_good.notice_as_manager,
    'notice_as_contact', source_good.notice_as_contact,
    'description', source_good.description,
    'description_format', source_good.description_format,
    'description_image_paths', '[]'::jsonb,
    'gallery_paths', '[]'::jsonb,
    'detail_image_path', null,
    'search_keywords', coalesce(to_jsonb(source_good.search_keywords), '[]'::jsonb),
    'category_id', category_value,
    'publish', false,
    'variants', source_variants,
    'variant_baseline', '[]'::jsonb
  );

  select entries into source_attribute_entries from public.goods_attribute_values where good_id=source_good.id for share;
  select fields,revision into clone_attribute_fields,clone_attribute_revision
    from public.catalog_category_attribute_schemas where category_id=category_value for share;
  source_attribute_entries:=coalesce(source_attribute_entries,'[]');
  clone_attribute_fields:=coalesce(clone_attribute_fields,'[]');
  clone_attribute_submission:=jsonb_build_object('categoryId',category_value,'schemaRevision',coalesce(clone_attribute_revision,0),
    'expectedRevision',0,'values',coalesce((select jsonb_object_agg(entry#>>'{field,id}',entry->'value')
      from jsonb_array_elements(source_attribute_entries) entry
      where exists(select 1 from jsonb_array_elements(clone_attribute_fields) field where field->>'id'=entry#>>'{field,id}'
        and field->>'kind'=entry#>>'{field,kind}' and field->>'unit'=entry#>>'{field,unit}'
        and private.goods_attribute_value_valid(field,entry->'value'))),'{}'),
    'removeIds','[]'::jsonb);
  clone_attribute_entries:=private.merge_goods_attributes(source_attribute_entries,clone_attribute_fields,clone_attribute_submission->'values','[]');
  target_payload:=target_payload||jsonb_build_object('product_attributes',clone_attribute_submission);
  saved := public.admin_save_good(target_payload);

  saved_id := saved ->> 'id';
  if saved_id is null then
    raise check_violation using message = 'goods_clone_result_missing';
  end if;


  -- Creation remains one transaction/version, including values retained after a
  -- source category change. Publication still exposes only matching definitions.
  update public.goods_attribute_values set entries=clone_attribute_entries
    where good_id=saved_id and entries is distinct from clone_attribute_entries;
  if clone_attribute_entries<>'[]'::jsonb then
    insert into public.audit_log(actor_id,action,target,diff) values(actor_id,'catalog.goods_attributes_cloned','goods:'||saved_id,
      jsonb_build_object('sourceGoodId',source_good.id,'after',clone_attribute_entries,'revision',1));
  end if;

  perform private.clone_goods_benefit_content(source_good.id,saved_id,actor_id);

  perform private.clone_goods_after_sales_content(source_good.id,saved_id,actor_id);

  perform private.clone_goods_size_chart(source_good.id,saved_id,actor_id);
  insert into private.goods_artwork_copy_authorizations(transaction_id,target_good_id,source_good_id,actor_id,allowed_paths)
    values(txid_current(),saved_id,source_good.id,actor_id,
      array_remove(array[source_good.image_path,source_good.detail_image_path]||coalesce(source_good.gallery_paths,'{}')||coalesce(source_good.description_image_paths,'{}'),null));
  update public.goods set image_path=source_good.image_path,gallery_paths=source_good.gallery_paths,
    detail_image_path=source_good.detail_image_path,description_image_paths=source_good.description_image_paths where id=saved_id;
  delete from private.goods_artwork_copy_authorizations where transaction_id=txid_current() and target_good_id=saved_id;

  -- Shipping notice is an immutable snapshot on the source good. Applying the
  -- exact references/snapshot avoids resolving a later template revision.
  update public.goods
  set shipping_notice_template_id = source_good.shipping_notice_template_id,
      shipping_notice_template_version = source_good.shipping_notice_template_version,
      shipping_notice_snapshot = source_good.shipping_notice_snapshot
  where id = saved_id;


 update public.goods copied set custom_inputs_enabled=source_good.custom_inputs_enabled,custom_input_fields=source_good.custom_input_fields,
  show_discount_rate=source_good.show_discount_rate,sale_starts_at=source_good.sale_starts_at,sale_ends_at=source_good.sale_ends_at,
  shipping_settings_template_id=source_good.shipping_settings_template_id,
  shipping_settings_template_revision=source_good.shipping_settings_template_revision,shipping_settings_snapshot=source_good.shipping_settings_snapshot
 where copied.id=saved_id;
 select coalesce(array_agg(m.category_id),'{}'::uuid[]) into category_ids from public.goods_additional_categories m
  join public.catalog_categories c on c.id=m.category_id where m.good_id=p_source_good_id and c.archived_at is null;
 perform private.apply_goods_additional_categories(saved_id,category_ids);
 insert into private.goods_listing_colors(good_id,colors,revision)
  select saved_id,colors,1 from private.goods_listing_colors where good_id=p_source_good_id;
 insert into private.goods_additional_sets(good_id,revision,updated_by)
  select saved_id,1,p_actor from private.goods_additional_sets where good_id=p_source_good_id;
 insert into private.goods_additional_links(base_good_id,target_good_id,sort_order)
  select saved_id,target_good_id,sort_order from private.goods_additional_links where base_good_id=p_source_good_id;
 perform 1 from private.goods_media_assets where id in(select video_asset_id from private.goods_media_bindings where good_id=p_source_good_id
  union select shortclip_asset_id from private.goods_media_bindings where good_id=p_source_good_id) order by id for share;
 if exists(select 1 from private.goods_media_bindings b join private.goods_media_assets a on a.id in(b.video_asset_id,b.shortclip_asset_id)
   where b.good_id=p_source_good_id and a.status<>'attached') then
  raise check_violation using message='goods_group_media_unavailable';end if;
 insert into private.goods_media_bindings(good_id,video_asset_id,video_title,shortclip_asset_id,shortclip_title,revision)
  select saved_id,video_asset_id,video_title,shortclip_asset_id,shortclip_title,1 from private.goods_media_bindings where good_id=p_source_good_id;
 insert into private.goods_group_write_authorizations(transaction_id,good_id,actor_id) values(txid_current(),saved_id,p_actor);
 return saved_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.create_inquiry_before_system_notice(target_category text, target_title text, target_body text, target_order_id uuid DEFAULT NULL::uuid, target_good_id text DEFAULT NULL::text, target_image_paths text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_category text := btrim(coalesce(target_category, ''));
  v_title text := btrim(coalesce(target_title, ''));
  v_body text := btrim(coalesce(target_body, ''));
  v_paths text[];
  v_inquiry_id uuid;
begin
  if v_actor is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_actor
      and profile.suspended_at is not null
  ) and (v_category <> 'account' or cardinality(coalesce(target_image_paths, '{}'::text[])) > 0
    or target_order_id is not null or target_good_id is not null) then
    -- 정지 회원은 계정 문의(탈퇴 요청·정지 문의)를 글로만 접수한다 — 탈퇴 경로가 막히지 않게(원장 CUS-035).
    raise insufficient_privilege using message = case when v_category <> 'account' then 'account_suspended'
      else 'account_suspended_inquiry_limited' end;
  end if;

  if v_category not in ('order', 'claim', 'good', 'account', 'etc') then
    raise invalid_parameter_value using message = 'invalid_inquiry_category';
  end if;
  if char_length(v_title) not between 1 and 80 then
    raise invalid_parameter_value using message = 'invalid_inquiry_title';
  end if;
  if char_length(v_body) not between 1 and 2000 then
    raise invalid_parameter_value using message = 'invalid_inquiry_body';
  end if;

  -- 연결은 본인 주문에만 허용한다. 남의 주문번호를 실어 문의를 열면 어드민 컨텍스트
  -- 패널이 그 주문 요약을 그려 준다 — 문의 접수만으로 타인 주문을 들여다보는 창이 된다.
  if target_order_id is not null and not exists (
    select 1
    from public.orders as target
    where target.id = target_order_id
      and target.user_id = v_actor
  ) then
    raise no_data_found using message = 'inquiry_order_not_found';
  end if;

  if target_good_id is not null and not exists (
    select 1
    from public.goods as target
    where target.id = target_good_id
  ) then
    raise no_data_found using message = 'inquiry_good_not_found';
  end if;

  -- 하루 접수 상한. 스레드 자체가 공개 표면은 아니지만 무제한 생성은 운영 큐를 마비시킨다.
  if (
    select count(*)
    from public.inquiries as thread
    where thread.user_id = v_actor
      and thread.created_at > now() - interval '1 day'
  ) >= 20 then
    raise check_violation using message = 'inquiry_rate_limited';
  end if;

  v_paths := private.assert_own_inquiry_image_paths(target_image_paths, v_actor);

  insert into public.inquiries (
    user_id,
    category,
    title,
    status,
    order_id,
    good_id
  )
  values (
    v_actor,
    v_category,
    v_title,
    'open',
    target_order_id,
    target_good_id
  )
  returning id into v_inquiry_id;

  insert into public.inquiry_messages (inquiry_id, author, author_id, body, image_paths)
  values (v_inquiry_id, 'user', v_actor, v_body, v_paths);

  return v_inquiry_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.create_order_shipments_before_preorder(target_order uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare purchase public.orders;fee jsonb;shipment_key uuid;selection_id uuid;method text;expected_count integer;begin
 select * into purchase from public.orders where id=target_order for update;if not found then raise no_data_found;end if;
 if purchase.calculation_version<>2 then perform private.create_shipments_before_fulfillment(target_order);return;end if;
 if exists(select 1 from public.order_shipments where order_id=target_order) then return;end if;
 select count(distinct(origin_id_snapshot,coalesce(fulfillment_terms_snapshot->>'method','parcel'))) into expected_count from public.order_items where order_id=target_order;
 if expected_count=0 or expected_count<>jsonb_array_length(purchase.shipping_fee_breakdown)
  or(select coalesce(sum((value->>'totalFee')::bigint),0) from jsonb_array_elements(purchase.shipping_fee_breakdown))<>purchase.shipping_fee then raise check_violation using message='invalid_order_shipment_breakdown';end if;
 for fee in select value from jsonb_array_elements(purchase.shipping_fee_breakdown) order by value->>'originId',value->>'deliveryMethod' loop
  method:=coalesce(fee->>'deliveryMethod','parcel');selection_id:=case when method='parcel' then null else gen_random_uuid() end;
  insert into public.order_shipments(order_id,origin_id,origin_name_snapshot,shipping_fee,shipping_fee_snapshot,fulfillment_partition,delivery_method,delivery_policy_id,delivery_method_snapshot,delivery_selection_id)
   values(target_order,(fee->>'originId')::uuid,fee->>'originName',(fee->>'totalFee')::bigint,fee,method,method,
    case when method in('parcel','digital') then null else(fee#>>'{deliveryPolicy,policyId}')::uuid end,
    case when method='parcel' then null else fee->'deliveryPolicy' end,selection_id) returning id into shipment_key;
  insert into public.order_shipment_items(order_id,shipment_id,order_item_id)
   select target_order,shipment_key,id from public.order_items where order_id=target_order and origin_id_snapshot=(fee->>'originId')::uuid and coalesce(fulfillment_terms_snapshot->>'method','parcel')=method;
  if not found then raise check_violation using message='shipment_method_without_items';end if;
  if selection_id is not null then
   insert into private.shipment_delivery_operations(id,shipment_id,kind,actor_id,request_digest,evidence)
    values(selection_id,shipment_key,'method_selected',purchase.user_id,extensions.digest(fee::text,'sha256'),
     jsonb_build_object('fromMethod',null,'toMethod',method,'checkout',true,'policyId',fee#>'{deliveryPolicy,policyId}','policyRevision',fee#>'{deliveryPolicy,revision}'));
  end if;
 end loop;
 if(select count(*) from public.order_shipment_items where order_id=target_order)<>(select count(*) from public.order_items where order_id=target_order) then raise check_violation using message='shipment_item_missing';end if;
end $function$

CREATE OR REPLACE FUNCTION private.create_shipments_before_fulfillment(target_order uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare purchase public.orders; fee jsonb; shipment_key uuid; expected_count integer;
begin
  select * into purchase from public.orders where id=target_order for update;
  if not found then raise no_data_found using message='order_not_found'; end if;
  if exists(select 1 from public.order_shipments where order_id=target_order) then return; end if;
  select count(distinct origin_id_snapshot) into expected_count from public.order_items where order_id=target_order;
  if expected_count=0 or expected_count<>jsonb_array_length(purchase.shipping_fee_breakdown)
    or (select coalesce(sum((value->>'totalFee')::bigint),0) from jsonb_array_elements(purchase.shipping_fee_breakdown))<>purchase.shipping_fee then
    raise check_violation using message='invalid_order_shipment_breakdown';
  end if;
  for fee in select value from jsonb_array_elements(purchase.shipping_fee_breakdown) order by value->>'originId' loop
    insert into public.order_shipments(order_id,origin_id,origin_name_snapshot,shipping_fee,shipping_fee_snapshot)
      values(target_order,(fee->>'originId')::uuid,fee->>'originName',(fee->>'totalFee')::bigint,fee)
      returning id into shipment_key;
    insert into public.order_shipment_items(order_id,shipment_id,order_item_id)
      select target_order,shipment_key,id from public.order_items where order_id=target_order and origin_id_snapshot=(fee->>'originId')::uuid;
    if not found then raise check_violation using message='shipment_origin_without_items'; end if;
  end loop;
  if (select count(*) from public.order_shipment_items where order_id=target_order)
    <>(select count(*) from public.order_items where order_id=target_order) then
    raise check_violation using message='shipment_item_missing';
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.customer_segment_execution_members(p_segment_id uuid, p_expected_revision integer, p_expected_hash text)
 RETURNS TABLE(customer_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare segment private.customer_segments;
begin
 select * into segment from private.customer_segments where id=p_segment_id and archived_at is null;
 if not found then raise no_data_found using message='customer_segment_not_found';end if;
 if segment.revision is distinct from p_expected_revision or segment.rule_hash is distinct from p_expected_hash then
  raise sqlstate 'PT409' using message='customer_segment_changed';end if;
 return query select members.customer_id from private.customer_segment_members(segment.rule,statement_timestamp()) members where members.marketing_consent;
end $function$

CREATE OR REPLACE FUNCTION private.decide_order_claim(p_claim_id uuid, p_decision text, p_note text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_order_id uuid;
  v_order_status public.order_status;
  v_delivered_at timestamptz;
  v_claim record;
  v_next_stage text;
  v_payment_count integer;
  /*
   * 보류를 벗긴 실질 단계.
   *
   * on_hold는 절차의 단계가 아니라 그 위에 덮인 표시다. 보류 중인 클레임을
   * 판정할 때 stage만 보면 processing에서 건 보류가 "아직 착수 전"으로 보인다.
   * lib/orders/claims.ts의 orderClaimEffectiveStage와 같은 정의다.
   */
  v_effective_stage text;
begin
  perform private.require_operator_capability('sales.manage',false);

  if v_actor is null or not public.has_operator_capability('sales.manage',false) then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if p_decision not in ('review', 'approve', 'reject', 'hold', 'resume') then
    raise check_violation using message = 'invalid claim decision';
  end if;

  select request.order_id
  into v_order_id
  from public.order_cancellation_requests as request
  where request.id = p_claim_id;

  if v_order_id is null then
    raise no_data_found using message = 'claim_not_found';
  end if;

  -- 잠금 순서: 주문 → 클레임. admin_decide_order_cancellation과 같다.
  select orders.status, orders.delivered_at
  into v_order_status, v_delivered_at
  from public.orders
  where orders.id = v_order_id
  for update;

  perform s.id from public.order_shipments s where s.order_id=v_order_id order by s.id for update;

  select request.*
  into v_claim
  from public.order_cancellation_requests as request
  where request.id = p_claim_id
  for update;

  if v_claim.stage in ('completed', 'rejected') then
    raise exception using message = 'claim_not_decidable';
  end if;

  v_effective_stage := case
    when v_claim.stage = 'on_hold' then coalesce(v_claim.held_from, 'requested')
    else v_claim.stage
  end;

  if p_decision = 'reject' then
    if p_note is null
      or btrim(p_note) <> p_note
      or length(p_note) not between 10 and 200
    then
      raise check_violation using message = 'invalid rejection reason';
    end if;

    /*
     * 거절은 처리에 착수하기 전에만 가능하다.
     *
     * processing·needs_review는 이미 durable claim과 refunds(status='requested')를
     * 열어 둔 상태다. 그 상태에서 요청만 rejected로 닫으면 주문은 "취소 진행 중"인
     * 채로 남고 complete_order_cancellation_request가 cancellation_request_not_processing
     * 으로 막아 돈이 갇힌다. needs_review는 Korpay 수동 복구 seam까지 함께 닫혀
     * 복구 경로가 하나도 남지 않는다. 그 단계에서 되돌릴 일이 있으면 거절이 아니라
     * 보류·정합화로 처리한다.
     */
    if v_effective_stage not in ('requested', 'in_review', 'collecting', 'collected') then
      raise exception using message = 'claim_not_rejectable';
    end if;

    /*
     * 한 출고지라도 교환품을 재출고했으면 거부할 수 없다(TKT-166·ADR-0041).
     * 나간 소포의 재고 차감과 배송 기록이 남으므로, 남은 출고지를 재출고해 종결하거나 보류한다.
     */
    if v_claim.reshipped_at is not null
      or exists (select 1 from public.order_claim_reshipments as reshipment where reshipment.claim_id = p_claim_id)
    then
      raise exception using message = 'claim_not_rejectable';
    end if;

    update public.order_cancellation_requests
    set
      stage = 'rejected',
      decided_by = v_actor,
      decision_note = p_note,
      decided_at = now(),
      updated_at = now()
    where id = p_claim_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_actor,
      'admin.order.claim_rejected',
      'order:' || v_order_id::text,
      jsonb_build_object(
        'claimId', p_claim_id,
        'claimType', v_claim.claim_type,
        'from', v_claim.stage,
        'to', 'rejected',
        'reason', p_note
      )
    );

    perform private.notify_order_claim(
      p_claim_id,
      'rejected',
      '클레임 요청이 거절됐어요',
      '요청이 거절됐습니다. 사유: ' || p_note
    );
    return 'rejected';
  end if;

  if p_decision = 'hold' then
    if p_note is null
      or btrim(p_note) <> p_note
      or length(p_note) not between 10 and 200
    then
      raise check_violation using message = 'invalid hold reason';
    end if;
    if v_claim.stage = 'on_hold' then
      return 'on_hold';
    end if;

    update public.order_cancellation_requests
    set
      stage = 'on_hold',
      held_from = v_claim.stage,
      hold_reason = p_note,
      held_at = now(),
      updated_at = now()
    where id = p_claim_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_actor,
      'admin.order.claim_held',
      'order:' || v_order_id::text,
      jsonb_build_object(
        'claimId', p_claim_id,
        'claimType', v_claim.claim_type,
        'from', v_claim.stage,
        'to', 'on_hold',
        'reason', p_note
      )
    );

    perform private.notify_order_claim(
      p_claim_id,
      'held',
      '클레임 처리가 보류됐어요',
      '처리가 보류됐습니다. 사유: ' || p_note
    );
    return 'on_hold';
  end if;

  if p_decision = 'resume' then
    if v_claim.stage <> 'on_hold' then
      raise exception using message = 'claim_not_held';
    end if;

    v_next_stage := coalesce(v_claim.held_from, 'requested');

    -- status를 여기서 계산하지 않는다. held_from이 needs_review면 이 자리에서
    -- 'requested'를 적어 투영 CHECK에 막혔고, 보류가 영원히 풀리지 않았다(F3).
    update public.order_cancellation_requests
    set
      stage = v_next_stage,
      held_from = null,
      hold_reason = null,
      held_at = null,
      updated_at = now()
    where id = p_claim_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_actor,
      'admin.order.claim_resumed',
      'order:' || v_order_id::text,
      jsonb_build_object(
        'claimId', p_claim_id,
        'claimType', v_claim.claim_type,
        'from', 'on_hold',
        'to', v_next_stage
      )
    );

    perform private.notify_order_claim(
      p_claim_id,
      'resumed',
      '클레임 처리가 재개됐어요',
      '보류가 해제되어 처리가 다시 시작됐습니다.'
    );
    return v_next_stage;
  end if;

  if p_decision = 'review' then
    if v_claim.stage <> 'requested' then
      raise exception using message = 'claim_not_decidable';
    end if;

    update public.order_cancellation_requests
    set
      stage = 'in_review',
      decided_by = v_actor,
      updated_at = now()
    where id = p_claim_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_actor,
      'admin.order.claim_in_review',
      'order:' || v_order_id::text,
      jsonb_build_object(
        'claimId', p_claim_id,
        'claimType', v_claim.claim_type,
        'from', 'requested',
        'to', 'in_review'
      )
    );
    return 'in_review';
  end if;

  -- 승인.
  if v_claim.stage not in ('requested', 'in_review') then
    raise exception using message = 'claim_not_decidable';
  end if;

  if v_order_status not in (
    'pending', 'paid', 'confirmed', 'shipping', 'delivered', 'done'
  ) then
    raise exception using message = 'order_not_cancelable';
  end if;

  if v_claim.claim_type='cancel' and not private.order_cancel_eligible(v_order_id) then raise exception using message='order_not_cancelable'; end if;
  if v_claim.claim_type in ('return','exchange') and not private.order_return_intake_eligible(v_order_id) then raise exception using message='order_not_claimable'; end if;
  perform private.prepare_claim_collections(p_claim_id);

  -- Money/deadline approval continues to use the original request time.
  if public.order_withdrawal_deadline_passed(
    v_delivered_at,
    v_claim.reason_type,
    v_claim.requested_at
  ) then
    raise check_violation using message = 'withdrawal_deadline_expired';
  end if;

  -- 취소는 회수할 물건이 없으므로 곧장 환불 처리로 간다. 반품·교환은 수거부터다.
  if v_claim.claim_type = 'cancel' then
    v_next_stage := 'processing';
  else
    v_next_stage := 'collecting';
  end if;

  if v_next_stage = 'processing' then
    insert into public.order_cancellation_claims (
      order_id,
      requested_by,
      previous_status
    )
    values (v_order_id, v_claim.requested_by, v_order_status)
    on conflict (order_id) do nothing;

    insert into public.refunds (
      payment_id,
      amount,
      reason,
      status,
      cancellation_request_id
    )
    select
      payment.id,
      payment.amount - private.payment_partial_refunded_amount(payment.id),
      v_claim.reason,
      case when refund.status = 'done' then 'done' else 'requested' end,
      p_claim_id
    from public.payments as payment
    left join public.refunds as refund on refund.payment_id = payment.id
    where payment.purpose = 'order'
      and payment.ref_id = v_order_id
      and payment.status in ('pending', 'paid', 'canceled', 'refunded')
    on conflict (payment_id) do update
    set
      cancellation_request_id = excluded.cancellation_request_id,
      reason = coalesce(public.refunds.reason, excluded.reason),
      status = case
        when public.refunds.status = 'done' then 'done'
        else 'requested'
      end;

    select count(*)::integer
    into v_payment_count
    from public.payments as payment
    where payment.purpose = 'order'
      and payment.ref_id = v_order_id
      and payment.status in ('pending', 'paid', 'canceled', 'refunded');
  end if;

  update public.order_cancellation_requests
  set
    stage = v_next_stage,
    decided_by = v_actor,
    decision_note = null,
    decided_at = now(),
    provider_started_at = case when v_next_stage = 'processing' then now() else provider_started_at end,
    collecting_at = case when v_next_stage = 'collecting' then now() else collecting_at end,
    updated_at = now()
  where id = p_claim_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.claim_approved',
    'order:' || v_order_id::text,
    jsonb_build_object(
      'claimId', p_claim_id,
      'claimType', v_claim.claim_type,
      'from', v_claim.stage,
      'to', v_next_stage,
      'previousOrderStatus', v_order_status::text,
      'reasonType', v_claim.reason_type,
      'paymentCount', coalesce(v_payment_count, 0)
    )
  );

  perform private.notify_order_claim(
    p_claim_id,
    'approved',
    '클레임 요청이 승인됐어요',
    case
      when v_next_stage = 'collecting'
        then '요청이 승인됐습니다. 안내받은 방법으로 굿즈를 반송해주세요.'
      else '요청이 승인됐습니다. 결제 취소 처리를 시작합니다.'
    end
  );

  return v_next_stage;
end;
$function$

CREATE OR REPLACE FUNCTION private.default_ip_public_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  existing_public_slug text;
begin
  -- `admin_upsert_ip` uses INSERT ... ON CONFLICT(id) DO UPDATE. Its
  -- pre-existing call shape has no public_slug argument, so an update of a
  -- renamed IP must retain the current canonical value instead of treating
  -- the immutable id as a fresh slug candidate.
  select ip.public_slug
    into existing_public_slug
  from public.ips as ip
  where ip.id = new.id;
  if found then
    if new.public_slug is null then
      new.public_slug := existing_public_slug;
      return new;
    end if;
    if new.public_slug is distinct from existing_public_slug then
      raise insufficient_privilege using message = 'ip_public_slug_write_requires_rpc';
    end if;
    return new;
  end if;

  -- A direct INSERT may only derive public_slug from the new internal ID.
  -- admin_create_ip issues the internal ID from the requested public slug and
  -- marks its own insert, so only that RPC may store a different public slug.
  if new.public_slug is null then
    new.public_slug := new.id;
  elsif new.public_slug is distinct from new.id
    and coalesce(pg_catalog.current_setting('app.ip_public_slug_write', true), '') <> 'admin_create_ip'
  then
    raise insufficient_privilege using message = 'ip_public_slug_write_requires_rpc';
  end if;

  -- Only the namespace check for a genuinely new ID needs the global lock.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ip_public_slug_identity', 0)
  );
  -- A deleted draft's internal ID is never issued again (audit and FK-less
  -- references keep pointing at the deleted record, not at a new IP).
  if exists (
    select 1 from private.retired_ip_ids as retired where retired.id = new.id
  ) then
    raise unique_violation using message = 'catalog_id_retired';
  end if;
  if exists (
    select 1 from public.ips as ip where ip.public_slug = new.public_slug
  ) or exists (
    select 1 from public.ip_public_slug_aliases as alias where alias.slug = new.public_slug
  ) then
    raise unique_violation using message = 'ip_public_slug_taken';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.destroy_email_dispatch_evidence(p_before timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ids uuid[]:='{}';event_count integer:=0;fence_count integer:=0;intent_count integer:=0;
begin
 if p_before is null or p_before>now()-interval '24 hours' then raise check_violation using message='invalid_email_retention_cutoff';end if;
 if not exists(select 1 from private.email_dispatch_control where singleton and privacy_retention_ready)
  then raise object_not_in_prerequisite_state using message='email_retention_policy_not_ready';end if;
 select coalesce(array_agg(id),'{}'::uuid[]) into ids from private.email_intents
  where updated_at<p_before and state in ('delivered','bounced','complained','suppressed','failed')
   and source not in ('account_deletion','order_delay_notice','operator_invitation');
 delete from private.email_provider_events where intent_id=any(ids) or intent_id is null and received_at<p_before;get diagnostics event_count=row_count;
 delete from private.email_intent_fences where intent_id=any(ids);get diagnostics fence_count=row_count;
 delete from private.email_intents where id=any(ids);get diagnostics intent_count=row_count;
 return jsonb_build_object('eventsDestroyed',event_count,'fencesDestroyed',fence_count,'intentsDestroyed',intent_count);
end $function$

CREATE OR REPLACE FUNCTION private.destroy_legacy_email_delivery_plaintext(p_before timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_count integer;
begin
  if p_before is null or p_before > pg_catalog.now() then
    raise check_violation using message = 'invalid_email_retention_cutoff';
  end if;
  if not exists (
    select 1 from private.email_dispatch_control as control
    where control.singleton and control.privacy_retention_ready
  ) then
    raise object_not_in_prerequisite_state using message = 'email_retention_policy_not_ready';
  end if;
  update public.email_deliveries set
    recipient = 'redacted@invalid.local',
    subject = 'legacy_' || template,
    last_error = case when last_error is null then null else 'legacy_failure' end,
    retention_disposition = 'destroyed',
    destroyed_at = coalesce(destroyed_at, pg_catalog.now())
  where created_at < p_before
    and retention_disposition = 'pending_policy';
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION private.detach_changed_shipping_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if new.shipping_settings_template_id is not null and (
  ((new.shipping_settings_snapshot->'settings')-array['delivery','chargeGroup','fulfillment']) is distinct from private.good_shipping_settings(new)
  or (new.shipping_settings_snapshot#>>'{settings,delivery,mode}'='replace'
   and new.shipping_settings_snapshot->'appliedDelivery' is distinct from private.shipping_settings_delivery_input(old.id))) then
  new.shipping_settings_template_id:=null;new.shipping_settings_template_revision:=null;new.shipping_settings_snapshot:=null;
 end if;
 if new.shipping_settings_snapshot is distinct from old.shipping_settings_snapshot or private.good_shipping_settings(new) is distinct from private.good_shipping_settings(old) then
  new.updated_at:=greatest(clock_timestamp(),old.updated_at+interval '1 microsecond');end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.digital_download_context(p_actor uuid, p_session uuid, p_item uuid, p_asset uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare purchase public.orders;item public.order_items;asset private.goods_digital_assets;begin
 select * into item from public.order_items where id=p_item;
 if not found or p_actor is null or p_session is null then raise no_data_found;end if;
 perform private.gift_lock_subjects(array[p_actor]);perform private.assert_active_user(p_actor);
 perform 1 from auth.sessions where id=p_session and user_id=p_actor and(not_after is null or not_after>clock_timestamp()) for share;
 if not found or private.is_account_write_fenced(p_actor) then raise insufficient_privilege;end if;
 select * into purchase from public.orders where id=item.order_id for update;
 if not found or purchase.user_id<>p_actor or purchase.status not in('paid','confirmed','shipping','delivered','done')
  or item.fulfillment_terms_snapshot->>'mode' is distinct from 'digital' or not private.production_payment_valid(purchase.id)
  or exists(select 1 from public.order_cancellation_requests where order_id=purchase.id and stage not in('completed','rejected','withdrawn'))
  or exists(select 1 from public.order_cancellation_claims where order_id=purchase.id)
  or exists(select 1 from public.refunds r join public.payments p on p.id=r.payment_id where p.purpose='order' and p.ref_id=purchase.id and r.status in('requested','processing','done'))
  or not(item.fulfillment_terms_snapshot->'files' @> jsonb_build_array(jsonb_build_object('id',p_asset))) then raise check_violation using message='digital_access_unavailable';end if;
 if private.order_fulfillment_held(purchase.id) then raise check_violation using message='digital_access_on_hold';end if;
 if (select count(*) from private.order_digital_downloads where actor_id=p_actor and created_at>clock_timestamp()-interval '1 minute')>=30 then raise sqlstate 'PT429' using message='digital_download_rate_limited';end if;
 perform id from public.order_shipments where order_id=purchase.id order by id for update;
 select * into asset from private.goods_digital_assets where id=p_asset and state='verified';
 if not found then raise check_violation using message='digital_asset_unavailable';end if;
 return jsonb_build_object('orderId',purchase.id,'itemId',item.id,'assetId',asset.id,'name',asset.filename,'mimeType',asset.mime_type,'size',asset.size_bytes,'sha256',asset.sha256,'path',asset.path);
end $function$

