CREATE OR REPLACE FUNCTION private.erp_read_settled_before()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_oldest timestamptz;
  v_now timestamptz := clock_timestamp();
begin
  if current_setting('transaction_isolation') <> 'read committed'
     or not pg_has_role(current_user, 'pg_read_all_stats', 'member') then
    raise exception 'erp_read_horizon_unavailable' using errcode = '55000';
  end if;
  perform pg_stat_clear_snapshot();
  select min(a.xact_start) into v_oldest
  from pg_catalog.pg_stat_activity as a
  where a.datname = current_database() and a.xact_start is not null and a.backend_type <> 'autovacuum worker';
  if v_oldest is null then
    raise exception 'erp_read_horizon_unavailable' using errcode = '55000';
  end if;
  return greatest(v_oldest, v_now - interval '1 hour') - interval '5 seconds';
end;
$function$

CREATE OR REPLACE FUNCTION private.erp_read_trim(p_rows jsonb, p_keep text[])
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(d.doc order by d.ord) filter (where d.before < 2097152), '[]'::jsonb)
  from (
    select s.doc, s.ord,
      coalesce(sum(octet_length(s.doc::text)) over (order by s.ord rows between unbounded preceding and 1 preceding), 0) as before
    from (
      select case when octet_length(e.value::text) > 2097152
        then (select jsonb_object_agg(k, e.value->k) from unnest(p_keep) as k)
          || jsonb_build_object('_erp_read_omitted', 'oversize_row')
        else e.value end as doc,
        e.ordinality as ord
      from jsonb_array_elements(p_rows) with ordinality as e
    ) as s
  ) as d;
$function$

CREATE OR REPLACE FUNCTION private.erp_read_where(p_rel regclass, p_order text[], p_cursor text, p_after jsonb, p_where jsonb, p_settled_before timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_parts text[] := array['true'];
  v_after text;
  v_filter text;
begin
  if p_after is not null then
    if jsonb_typeof(p_after) <> 'object' or jsonb_typeof(p_after->'key') is distinct from 'object' or exists (
      select 1 from unnest(p_order) as o(col)
      where (case when o.col = p_cursor then p_after->>'at' else p_after->'key'->>o.col end) is null
    ) then
      raise exception 'erp_read_invalid_cursor' using errcode = '22023';
    end if;
    select format('(%s) > (%s)',
        string_agg(format('t.%I', o.col), ', ' order by o.ord),
        string_agg(format('%L::%s', case when o.col = p_cursor then p_after->>'at'
                                         else p_after->'key'->>o.col end, c.type), ', ' order by o.ord))
      into v_after
    from unnest(p_order) with ordinality as o(col, ord)
    join private.erp_read_columns(p_rel) as c on c.name = o.col;
    v_parts := v_parts || v_after;
  end if;
  if p_settled_before is not null and p_cursor is not null then
    v_parts := v_parts || format('t.%I < %L::timestamptz', p_cursor, p_settled_before);
  end if;
  if p_where is null then
    return array_to_string(v_parts, ' and ');
  end if;
  if jsonb_typeof(p_where) <> 'object' or exists (
    select 1 from jsonb_each(p_where) as w
    where jsonb_typeof(w.value) <> 'array' or jsonb_array_length(w.value) > 1000
      or w.key not in (select c.name from private.erp_read_columns(p_rel) as c)
  ) then
    raise exception 'erp_read_invalid_where' using errcode = '22023';
  end if;
  select string_agg(format('t.%I = any(%L::%s[])', c.name,
      (select array_agg(v) from jsonb_array_elements_text(w.value) as v)::text, c.type), ' and ')
    into v_filter
  from jsonb_each(p_where) as w
  join private.erp_read_columns(p_rel) as c on c.name = w.key;
  return array_to_string(v_parts || coalesce(v_filter, 'true'), ' and ');
end;
$function$

CREATE OR REPLACE FUNCTION private.evaluate_coupon_target_lines_at(p_user_coupon_id uuid, p_user_id uuid, p_lines jsonb, p_order_id uuid, p_at timestamp with time zone, p_replace_unpaid boolean, OUT o_reason text, OUT o_discount bigint, OUT o_coupon_code text, OUT o_eligible_subtotal bigint, OUT o_terms_snapshot jsonb)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare held public.user_coupons; coupon public.coupons;
begin
 if p_at is null or not isfinite(p_at) then raise invalid_parameter_value using message='invalid_coupon_evaluation_time';end if;
 o_reason:=null; o_discount:=0; o_coupon_code:=null; o_eligible_subtotal:=0; o_terms_snapshot:=null;
 select * into held from public.user_coupons where id=p_user_coupon_id;
 if not found or held.user_id is distinct from p_user_id then o_reason:='coupon_not_owned'; return; end if;
 o_coupon_code:=held.coupon_code;
 -- 다음 새 주문이 닫을 결제 대기 주문이 잡은 쿠폰은 그 주문이 닫힌 것으로 본다(견적·선택만, QA1 S-D2-08).
 if held.status='used' and not (p_replace_unpaid is true and private.unpaid_order_replaceable(held.used_order_id,p_user_id)) then o_reason:='coupon_already_used'; return; end if;
 select * into coupon from public.coupons where code=held.coupon_code;
 if not found or coupon.status<>'active' then o_reason:='coupon_not_found'; return; end if;
 if p_at<(case when coupon.issue_starts_at is null then coupon.starts_at else held.usable_from end) then o_reason:='coupon_not_started'; return; end if;
 if (coupon.issue_starts_at is null and coupon.ends_at is not null and p_at>coupon.ends_at) or (held.expires_at is not null and p_at>held.expires_at)
   then o_reason:='coupon_expired'; return; end if;
 o_reason:=private.coupon_recipient_reason(coupon.recipient_segment,p_user_id);
 if o_reason is not null then return; end if;
 if coupon.recipient_segment='first_purchase' then
   if exists(select 1 from private.coupon_first_purchase_claims where user_id=p_user_id and state='reserved' and order_id is distinct from p_order_id and not (p_replace_unpaid is true and private.unpaid_order_replaceable(order_id,p_user_id)))
     then o_reason:='coupon_first_purchase_reserved'; return; end if;
   if exists(select 1 from public.orders where user_id=p_user_id and status='pending' and id is distinct from p_order_id and not (p_replace_unpaid is true and private.unpaid_order_replaceable(id,p_user_id)))
     then o_reason:='coupon_first_purchase_pending'; return; end if;
 end if;
 select coalesce(sum(line.subtotal),0) into o_eligible_subtotal
   from jsonb_to_recordset(p_lines) line(good_id text,subtotal bigint)
   where private.coupon_good_matches(coupon.goods_scope,coupon.target_good_ids,coupon.target_category_ids,coupon.target_ip_ids,line.good_id);
 o_terms_snapshot:=jsonb_build_object('revision',coupon.terms_revision,'recipientSegment',coupon.recipient_segment,'goodsScope',coupon.goods_scope,
   'targetGoodIds',coupon.target_good_ids,'eligibleSubtotal',o_eligible_subtotal,'discountType',coupon.discount_type,'discountValue',coupon.discount_value,
   'maxDiscountAmount',coupon.max_discount_amount,'minSubtotal',coupon.min_subtotal,'startsAt',coupon.starts_at,'endsAt',coupon.ends_at,'expiresAt',held.expires_at,'usableFrom',held.usable_from,'issueStartsAt',coupon.issue_starts_at,'issueEndsAt',coupon.issue_ends_at,'validDays',coupon.valid_days)
  ||case when coupon.goods_scope='selected_categories' then jsonb_build_object('targetCategoryIds',coupon.target_category_ids) else '{}'::jsonb end
  ||case when coupon.goods_scope='selected_ips' then jsonb_build_object('targetIpIds',coupon.target_ip_ids) else '{}'::jsonb end
  ||case when coupon.issuance_mode='targeted' then jsonb_build_object('issuanceMode',coupon.issuance_mode) else '{}'::jsonb end;
 if o_eligible_subtotal=0 then o_reason:='coupon_no_eligible_goods'; return; end if;
 if o_eligible_subtotal<coupon.min_subtotal then o_reason:='coupon_min_subtotal'; return; end if;
 o_discount:=case when coupon.discount_type='fixed' then least(coupon.discount_value::bigint,o_eligible_subtotal)
   else least((o_eligible_subtotal*coupon.discount_value::bigint)/100,coalesce(coupon.max_discount_amount::bigint,o_eligible_subtotal),o_eligible_subtotal) end;
end $function$

CREATE OR REPLACE FUNCTION private.evaluate_user_coupon(p_user_coupon_id uuid, p_user_id uuid, p_subtotal bigint, OUT o_reason text, OUT o_discount bigint, OUT o_coupon_code text)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare lines jsonb; evaluated record;
begin
 if exists(select 1 from public.user_coupons held join public.coupons c on c.code=held.coupon_code where held.id=p_user_coupon_id and c.benefit_kind='shipping') then o_reason:='coupon_checkout_required';o_discount:=0;o_coupon_code:=null;return;end if;

 select coalesce(jsonb_agg(jsonb_build_object('good_id',cart.good_id,'subtotal',cart.qty::bigint*price.effective_price::bigint)),'[]') into lines
 from public.cart_items cart join public.goods_variants variant on variant.id=cart.variant_id and variant.good_id=cart.good_id
 cross join lateral private.resolve_goods_variant_price(variant.id,statement_timestamp()) price where cart.user_id=p_user_id;
 select * into evaluated from private.evaluate_coupon_target_lines_at(p_user_coupon_id,p_user_id,lines,null,statement_timestamp(),true);
 o_reason:=evaluated.o_reason; o_discount:=evaluated.o_discount; o_coupon_code:=evaluated.o_coupon_code;
end $function$

CREATE OR REPLACE FUNCTION private.expire_store_credit_lots(p_user_id uuid, p_at timestamp with time zone)
