  raise check_violation using message='gift_payment_not_ready';end if;
end $function$

CREATE OR REPLACE FUNCTION private.gift_selection_display(p_selection jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb;good public.goods;variant public.goods_variants;custom jsonb;result jsonb:='[]';begin
 if jsonb_typeof(p_selection) is distinct from 'array' or jsonb_array_length(p_selection) not between 1 and 100 or octet_length(p_selection::text)>100000 then
  raise invalid_parameter_value using message='gift_selection_invalid';end if;
 if (select count(distinct jsonb_build_array(e->'goodId',e->'variantId',e->'inputRevision',e->'inputValues')) from jsonb_array_elements(p_selection)e)<>jsonb_array_length(p_selection) then
  raise invalid_parameter_value using message='gift_selection_duplicate';end if;
 for item in select e from jsonb_array_elements(p_selection)e loop
  if not private.transaction_json_keys(item,array['goodId','variantId','qty','inputRevision','inputValues'])
   or jsonb_typeof(item->'goodId') is distinct from 'string' or char_length(item->>'goodId') not between 1 and 200
   or jsonb_typeof(item->'variantId') is distinct from 'string' or item->>'variantId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or not private.transaction_uint(item->'qty',1,2147483647) or not private.transaction_uint(item->'inputRevision',0,2147483647)
   or jsonb_typeof(item->'inputValues') is distinct from 'object' or (select count(*) from jsonb_object_keys(item->'inputValues'))>5
   or exists(select 1 from jsonb_each(item->'inputValues')e where e.key!~'^[0-9a-f-]{36}$' or jsonb_typeof(e.value)<>'string' or char_length(e.value#>>'{}')>100) then
   raise invalid_parameter_value using message='gift_selection_invalid';end if;
  select g.* into good from public.goods g join public.ips ip on ip.id=g.ip_id where g.id=item->>'goodId' and g.archived_at is null and g.published_at is not null
   and g.sale_restriction='none' and ip.archived_at is null and ip.published_at is not null;
  if not found then raise no_data_found using message='gift_good_unavailable';end if;
  -- 랜덤 판매 굿즈(D5②)는 선물로 준비·수락하지 않는다(받는 사람 화면에 배정 전 기본 옵션 이름이 남지 않게 한다).
  if good.option_sale_mode='random' then raise check_violation using message='gift_random_option_unsupported';end if;
  select * into variant from public.goods_variants where id=(item->>'variantId')::uuid and good_id=good.id and archived_at is null;
  if not found then raise no_data_found using message='gift_variant_unavailable';end if;
  custom:=private.resolve_goods_custom_inputs(good.id,(item->>'inputRevision')::integer,item->'inputValues');
  result:=result||jsonb_build_array(jsonb_build_object('goodId',good.id,'variantId',variant.id,'name',good.name,'variantName',variant.name,
   'qty',(item->>'qty')::integer,'imagePath',good.image_path,'customInputs',custom));
 end loop;return result;
end $function$

CREATE OR REPLACE FUNCTION private.goods_attribute_fields_valid(fields jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare field jsonb; opt jsonb; ids text[]:='{}'; names text[]:='{}'; option_ids text[]; labels text[];
begin
  if jsonb_typeof(fields) is distinct from 'array' then return false; end if;
  if jsonb_array_length(fields)>30 then return false; end if;
  for field in select value from jsonb_array_elements(fields) loop
    if jsonb_typeof(field) is distinct from 'object' then return false; end if;
    if not field ?& array['id','name','kind','required','unit','options'] or (select count(*) from jsonb_object_keys(field))<>6
      or jsonb_typeof(field->'id') is distinct from 'string' or field->>'id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or field->>'id'=any(ids) or jsonb_typeof(field->'name') is distinct from 'string' or char_length(field->>'name') not between 1 and 60
      or field->>'name'<>private.goods_attribute_trim(field->>'name') or field->>'name'=any(names)
      or coalesce(field->>'kind','') not in ('single','multi','text','number') or jsonb_typeof(field->'required') is distinct from 'boolean'
      or jsonb_typeof(field->'unit') is distinct from 'string' or char_length(field->>'unit')>20 or field->>'unit'<>private.goods_attribute_trim(field->>'unit')
      or (field->>'kind'<>'number' and field->>'unit'<>'') or jsonb_typeof(field->'options') is distinct from 'array' then return false; end if;
    ids:=array_append(ids,field->>'id'); names:=array_append(names,field->>'name'); option_ids:='{}'; labels:='{}';
    if jsonb_array_length(field->'options')>100 or (field->>'kind' in ('single','multi') and jsonb_array_length(field->'options')=0)
      or (field->>'kind' in ('text','number') and jsonb_array_length(field->'options')<>0) then return false; end if;
    for opt in select value from jsonb_array_elements(field->'options') loop
      if jsonb_typeof(opt) is distinct from 'object' then return false; end if;
      if not opt ?& array['id','label'] or (select count(*) from jsonb_object_keys(opt))<>2
        or jsonb_typeof(opt->'id') is distinct from 'string' or opt->>'id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or opt->>'id'=any(option_ids) or jsonb_typeof(opt->'label') is distinct from 'string' or char_length(opt->>'label') not between 1 and 80
        or opt->>'label'<>private.goods_attribute_trim(opt->>'label') or opt->>'label'=any(labels) then return false; end if;
      option_ids:=array_append(option_ids,opt->>'id'); labels:=array_append(labels,opt->>'label');
    end loop;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.goods_attribute_value_valid(field jsonb, val jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare kind text:=field->>'kind'; n numeric;
begin
  if val is null or val='null' then return false; end if;
  if kind='text' then return jsonb_typeof(val)='string' and char_length(val#>>'{}') between 1 and 500 and val#>>'{}'=private.goods_attribute_trim(val#>>'{}'); end if;
  if kind='number' then
    if jsonb_typeof(val)<>'number' then return false; end if;
    n:=(val#>>'{}')::numeric; return abs(n)<=1000000000 and n=round(n,6);
  end if;
  if kind='single' then return jsonb_typeof(val)='string' and exists(select 1 from jsonb_array_elements(field->'options') opt where opt->'id'=val); end if;
  if kind='multi' then
    if jsonb_typeof(val)<>'array' then return false; end if;
    return jsonb_array_length(val) between 1 and 100 and (select count(distinct value) from jsonb_array_elements(val))=jsonb_array_length(val)
      and not exists(select 1 from jsonb_array_elements(val) v where jsonb_typeof(v)<>'string' or not exists(select 1 from jsonb_array_elements(field->'options') opt where opt->'id'=v));
  end if;
  return false;
end $function$

CREATE OR REPLACE FUNCTION private.goods_bulk_discount_price(p_price integer, p_values jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare result numeric;amount numeric:=(p_values->>'value')::numeric;
begin
 result:=case p_values->>'mode' when 'amount' then p_price-amount when 'rate' then floor(p_price*(100-amount)/100) end;
 if result is null or result<1 or result>=p_price then return null;end if;
 return result::integer;
end $function$

CREATE OR REPLACE FUNCTION private.goods_delivery_quantity_terms_valid(p_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$begin
 if not private.transaction_uint(p_value->'baseFee',0,1000000) then return false;end if;
 if p_value->>'kind'='repeat' then
  return private.transaction_json_keys(p_value,array['kind','baseFee','interval']) and private.transaction_uint(p_value->'interval',1,2147483647);
 end if;
 if not private.transaction_uint(p_value->'firstLimit',1,2147483647) or not private.transaction_uint(p_value->'extra1',0,1000000) then return false;end if;
 if p_value->>'kind'='tier2' then return private.transaction_json_keys(p_value,array['kind','baseFee','firstLimit','extra1']);end if;
 if p_value->>'kind'='tier3' then
  return private.transaction_json_keys(p_value,array['kind','baseFee','firstLimit','secondLimit','extra1','extra2'])
   and private.transaction_uint(p_value->'secondLimit',(p_value->>'firstLimit')::numeric+1,2147483647)
   and private.transaction_uint(p_value->'extra2',(p_value->>'extra1')::numeric,1000000);
 end if;return false;
end $function$

CREATE OR REPLACE FUNCTION private.goods_fulfillment_selected_terms(p_good text, p_choice jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare config private.goods_fulfillment_settings;method text;terms jsonb;begin
 select * into config from private.goods_fulfillment_settings where good_id=p_good;
 if not found then
  if jsonb_typeof(p_choice)='object' and p_choice->>'method'<>'parcel' then return jsonb_build_object('invalid',true);end if;return null;
 end if;
 method:=case when jsonb_typeof(p_choice)='object' then p_choice->>'method' when jsonb_array_length(config.methods)=1 then config.methods->0->>'method' end;
 select value into terms from jsonb_array_elements(config.methods) where value->>'method'=method;
 if terms is null or method<>'parcel' and coalesce(case when jsonb_typeof(p_choice)='object' then p_choice->>'paymentMode' else p_choice#>>'{}' end,'prepaid')<>'prepaid' then return jsonb_build_object('invalid',true);end if;
 return jsonb_build_object('version',1,'goodId',p_good,'revision',config.revision,'mode',config.mode,'method',method,'terms',terms,'files',private.digital_file_metadata(config.asset_ids),'publicNote',config.public_note);
end $function$

CREATE OR REPLACE FUNCTION private.goods_group_lock_conversion_source(p_good_id text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare source_ip text;
begin
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 if not pg_try_advisory_xact_lock(hashtextextended('goods-additional-graph',0)) then
  raise sqlstate 'PT409' using message='goods_group_retry';end if;
 perform private.lock_catalog_category_tree();
 perform 1 from public.goods where id in(p_good_id,private.goods_aggregation_owner(p_good_id)) order by id for update;
 perform 1 from public.goods_variants where good_id=p_good_id order by id for update;
 select ip_id into source_ip from public.goods where id=p_good_id;
 if source_ip is null then raise no_data_found using message='goods_group_source_not_found';end if;
 perform 1 from public.ips where id=source_ip for update nowait;
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$function$

CREATE OR REPLACE FUNCTION private.goods_kc_review_problems(p_good_id text, p_models jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row jsonb; errors text[]:='{}'; scheme text; subject boolean; covered uuid[];
begin
  if jsonb_array_length(p_models)=0 then return array['KC 모델 검토가 필요합니다.']; end if;
  for row in select elem from jsonb_array_elements(p_models) elem loop
    scheme:=row->>'scheme';
    subject:=scheme is distinct from 'not_applicable';
    if row->>'family'='' or scheme='' or (subject and (row->>'productCategory'='' or row->>'modelName'=''
      or row->>'businessRole'='' or row->>'businessName'='')) then
      errors:=array_append(errors,'제품군·제도·품목·모델·사업자를 입력해주세요.');
    end if;
    -- 1007-034(ADR-0036): 적용 판단 사유와 근거 참조는 선택 입력이다.
    if jsonb_array_length(row->'variantIds')=0 then errors:=array_append(errors,'모델에 적용 옵션을 연결해주세요.'); end if;
    if exists(select 1 from jsonb_array_elements_text(row->'variantIds') linked(variant_id) where not exists(
      select 1 from public.goods_variants variant where variant.good_id=p_good_id and variant.id=linked.variant_id::uuid)) then
      errors:=array_append(errors,'이 상품에 없는 옵션이 포함되어 있습니다.');
    end if;
    if scheme in ('safety_certification','safety_confirmation') then
      if row->>'identifier'='' then
        errors:=array_append(errors,'인증·신고번호가 필요합니다.');
      end if;
    elsif row->>'identifier'<>'' then
      errors:=array_append(errors,'선택한 제도에는 인증·신고번호를 입력하지 않습니다.');
    end if;
    -- 공급자적합성확인의 시험성적서·공급자 확인서 참조는 선택 입력이다(1007-034).
  end loop;
  select coalesce(array_agg(distinct linked.variant_id::uuid),'{}') into covered from jsonb_array_elements(p_models) model
    cross join lateral jsonb_array_elements_text(model->'variantIds') linked(variant_id);
  if exists(select 1 from public.goods_variants variant where variant.good_id=p_good_id and variant.archived_at is null
    and not(variant.id=any(covered))) then errors:=array_append(errors,'모든 사용 중인 옵션의 모델 검토가 필요합니다.'); end if;
  return errors;
end $function$

CREATE OR REPLACE FUNCTION private.goods_listing_colors_valid(p_colors jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare chip jsonb; labels text[]:='{}';
begin
 if jsonb_typeof(p_colors) is distinct from 'array' then return false;end if;
 if jsonb_array_length(p_colors)>20 then return false;end if;
 for chip in select value from jsonb_array_elements(p_colors) loop
  if jsonb_typeof(chip) is distinct from 'object' then return false;end if;
  if (select count(*) from jsonb_object_keys(chip))<>2 or not chip ?& array['label','hex']
   or jsonb_typeof(chip->'label') is distinct from 'string' or jsonb_typeof(chip->'hex') is distinct from 'string'
   or char_length(chip->>'label') not between 1 and 30 or chip->>'label' ~ '[[:cntrl:]]'
   or chip->>'label'<>btrim(chip->>'label',E' \t\n\r\f\v'||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
   or chip->>'hex' !~ '^#[0-9a-f]{6}$' or chip->>'label'=any(labels) then return false;end if;
  labels:=array_append(labels,chip->>'label');
 end loop;return true;
end $function$

CREATE OR REPLACE FUNCTION private.goods_preorder_schedule_scope(p_good_id text, p_variant_id uuid, p_to_date date)
 RETURNS public.goods
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare good public.goods;
begin
  if p_good_id is null or p_to_date is null or p_to_date<(statement_timestamp() at time zone 'Asia/Seoul')::date then
    raise invalid_parameter_value using message='invalid_preorder_schedule_change';
  end if;
  select * into good from public.goods where id=p_good_id;
  if not found then raise no_data_found using message='good_not_found'; end if;
  if p_variant_id is not null then
    if good.option_sale_mode='random' then raise check_violation using message='preorder_schedule_random_whole_good'; end if;
    if not exists(select 1 from public.goods_variants where id=p_variant_id and good_id=good.id) then
      raise no_data_found using message='goods_variant_not_found';
    end if;
  end if;
  return good;
end $function$

CREATE OR REPLACE FUNCTION private.goods_quantity_delivery_fee(p_quantity numeric, p_terms jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$declare fee numeric;begin
 if p_quantity is null or p_quantity<1 or trunc(p_quantity)<>p_quantity or p_quantity>9007199254740991
  or not private.goods_delivery_quantity_terms_valid(p_terms) then raise invalid_parameter_value using message='invalid_quantity_delivery';end if;
 fee:=(p_terms->>'baseFee')::numeric;
 if p_terms->>'kind'='repeat' then fee:=ceil(p_quantity/(p_terms->>'interval')::numeric)*fee;
 elsif p_quantity>(p_terms->>'firstLimit')::numeric then
  fee:=fee+case when p_terms->>'kind'='tier3' and p_quantity>(p_terms->>'secondLimit')::numeric then (p_terms->>'extra2')::numeric else (p_terms->>'extra1')::numeric end;
 end if;
 if fee>9007199254740991 then raise numeric_value_out_of_range using message='transaction_amount_overflow';end if;
 return fee::bigint;
end $function$

CREATE OR REPLACE FUNCTION private.goods_random_option_problem(p_good_id text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare good public.goods;
begin
  select * into good from public.goods where id=p_good_id;
  if not found then return 'good_not_found'; end if;
  if (select count(*) from public.goods_variants where good_id=p_good_id and archived_at is null)<2 then return 'random_option_count'; end if;
  if not exists(select 1 from public.goods_variants where good_id=p_good_id and is_default and archived_at is null) then
    return 'random_option_default_inactive';
  end if;
  -- 예약판매: 판매 중 옵션이 모두 예약을 선택했거나 모두 일반 재고이고, 예약이면 접수 시작·종료·발송 예정일이 같아야 한다.
  if (exists(select 1 from public.goods_variants where good_id=p_good_id and archived_at is null and preorder_policy_id is null)
      and exists(select 1 from public.goods_variants where good_id=p_good_id and archived_at is null and preorder_policy_id is not null))
    or (select count(distinct format('%s|%s|%s',policy.starts_at,policy.ends_at,policy.expected_ship_date))
      from public.goods_variants variant join private.goods_preorder_policies policy on policy.id=variant.preorder_policy_id
      where variant.good_id=p_good_id and variant.archived_at is null)>1 then
    return 'random_option_preorder_mismatch';
  end if;
  if (select count(distinct price) from public.goods_variants where good_id=p_good_id and archived_at is null)>1
    or (select count(distinct coalesce(schedule.signature,'')) from public.goods_variants variant
      cross join lateral (select string_agg(format('%s|%s|%s',period.starts_at,period.ends_at,period.discount_price),','
          order by period.starts_at,period.ends_at,period.discount_price) signature
        from private.goods_variant_price_periods period
        where period.variant_id=variant.id and period.state='active' and period.ends_at>clock_timestamp()) schedule
      where variant.good_id=p_good_id and variant.archived_at is null)>1 then
    return 'random_option_price_mismatch';
  end if;
  -- 같은 옵션 배정 상한: 고객은 옵션을 고르지 않으므로 판매 중 모든 옵션이 같은 값이어야 한다(null = 상한 없음).
  if (select count(distinct format('%s|%s',order_max_qty,member_max_qty)) from public.goods_variants
    where good_id=p_good_id and archived_at is null)>1 then
    return 'random_option_limit_mismatch';
  end if;
  if good.custom_inputs_enabled then return 'random_option_custom_inputs'; end if;
  if exists(select 1 from private.goods_aggregation_members where good_id=p_good_id or root_good_id=p_good_id)
    or exists(select 1 from private.goods_aggregation_roots where root_good_id=p_good_id) then
    return 'random_option_aggregation';
  end if;
  if exists(select 1 from private.goods_group_members where good_id=p_good_id)
    or exists(select 1 from private.goods_groups where common_good_id=p_good_id) then
    return 'random_option_group';
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.goods_sales_conditions_core(items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  input record;
  line record;
  good public.goods;
  quantity_policy public.goods;
  variant public.goods_variants;
  price record;
  normalized jsonb:='[]';
  quoted_lines jsonb:='[]';
  quoted_goods jsonb:='[]';
  at_time timestamptz:=statement_timestamp();
  actor uuid:=auth.uid();
  subtotal bigint:=0;
  card_allowed boolean:=true;
  bank_allowed boolean:=true;
  reserved_qty bigint;
  quantity_error text;
begin
  if jsonb_typeof(items) is distinct from 'array' or jsonb_array_length(items)>1000 then
    raise invalid_parameter_value using message='invalid_sales_quote_items';
  end if;
  for input in select value from jsonb_array_elements(items) loop
    if jsonb_typeof(input.value) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(input.value) key where key not in ('goodId','variantId','qty'))
      or jsonb_typeof(input.value->'goodId') is distinct from 'string'
      or nullif(btrim(input.value->>'goodId'),'') is null
      or jsonb_typeof(input.value->'variantId') is distinct from 'string'
      or input.value->>'variantId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or jsonb_typeof(input.value->'qty') is distinct from 'number'
      or input.value->>'qty' !~ '^[1-9][0-9]*$' then
      raise invalid_parameter_value using message='invalid_sales_quote_items';
    end if;
    if (input.value->>'qty')::numeric>2147483647 then
      raise invalid_parameter_value using message='invalid_sales_quote_items';
    end if;
    normalized:=normalized||jsonb_build_array(jsonb_build_object('good_id',input.value->>'goodId',
      'variant_id',(input.value->>'variantId')::uuid,'qty',(input.value->>'qty')::integer));
  end loop;
  for line in select good_id,variant_id,sum(qty::bigint)::bigint qty
    from jsonb_to_recordset(normalized) as item(good_id text,variant_id uuid,qty integer)
    group by good_id,variant_id order by good_id,variant_id
  loop
    select g.* into good from public.goods g join public.ips ip on ip.id=g.ip_id
      where g.id=line.good_id and g.archived_at is null and g.published_at is not null and private.good_sale_restriction_visible(g.sale_restriction,(select auth.uid()))
        and ip.archived_at is null and ip.published_at is not null;
    if not found then raise check_violation using message='sales_quote_good_unavailable'; end if;
    select * into variant from public.goods_variants
      where id=line.variant_id and good_id=good.id and archived_at is null;
    if not found then raise check_violation using message='sales_quote_variant_unavailable'; end if;
    select * into price from private.resolve_goods_variant_price(variant.id,at_time);
    quoted_lines:=quoted_lines||jsonb_build_array(jsonb_build_object('goodId',good.id,'variantId',variant.id,'qty',line.qty,
      'regularPrice',price.regular_price,'effectivePrice',price.effective_price,'pricePeriodId',price.price_period_id,
      'startsAt',price.starts_at,'endsAt',price.ends_at,'available',good.stock<>'soldout' and line.qty<=variant.stock_qty));
    subtotal:=subtotal+line.qty*price.effective_price::bigint;
    card_allowed:=card_allowed and good.allow_card_payment;
    bank_allowed:=bank_allowed and good.allow_bank_transfer;
  end loop;
  for line in select good_id,sum(qty::bigint)::bigint qty
    from jsonb_to_recordset(normalized) as item(good_id text,variant_id uuid,qty integer)
    group by good_id order by good_id
  loop
    select * into good from public.goods where id=line.good_id;
    select * into quantity_policy from public.goods where id=private.goods_aggregation_owner(good.id);
    reserved_qty:=case when actor is null then null else private.member_goods_reserved_qty(actor,good.id) end;
    quantity_error:=private.check_goods_purchase_quantity(good,actor,(select sum(item.qty::bigint)::bigint from jsonb_to_recordset(normalized) item(good_id text,qty integer) where private.goods_aggregation_owner(item.good_id)=private.goods_aggregation_owner(good.id)),true);
    quoted_goods:=quoted_goods||jsonb_build_array(jsonb_build_object('goodId',good.id,'qty',line.qty,
      'orderQuantityLimitEnabled',quantity_policy.order_quantity_limit_enabled,'minOrderQty',quantity_policy.min_order_qty,'maxOrderQty',quantity_policy.max_order_qty,
      'memberPurchaseLimitEnabled',quantity_policy.member_purchase_limit_enabled,'memberLifetimeQtyLimit',quantity_policy.member_lifetime_qty_limit,
      'memberReservedQty',reserved_qty,'memberRemainingQty',case when not quantity_policy.member_purchase_limit_enabled or actor is null
        then null else greatest(0,quantity_policy.member_lifetime_qty_limit::bigint-reserved_qty) end,'reason',quantity_error));
  end loop;
  return jsonb_build_object('calculatedAt',at_time,'subtotal',subtotal,'lines',quoted_lines,'goods',quoted_goods,
    'nextChangeAt',(select min(boundary.change_at) from private.goods_variant_price_periods schedule
      cross join lateral (values(schedule.starts_at),(schedule.ends_at)) boundary(change_at)
      where schedule.state='active' and boundary.change_at>at_time
        and schedule.variant_id in (select (value->>'variant_id')::uuid from jsonb_array_elements(normalized))),
    'paymentMethods',jsonb_build_object('card',card_allowed and jsonb_array_length(normalized)>0,
      'bankTransfer',bank_allowed and jsonb_array_length(normalized)>0));
end $function$

CREATE OR REPLACE FUNCTION private.goods_sales_conditions_quote(items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare quote jsonb;lines jsonb:='[]';line jsonb;supply jsonb;next_change timestamptz;selling boolean;
begin
 quote:=private.goods_sales_conditions_core(items);
 next_change:=(quote->>'nextChangeAt')::timestamptz;
 for line in select value from jsonb_array_elements(quote->'lines') loop
  select public.goods_variant_supply(variant),good.stock<>'soldout' into supply,selling
   from public.goods_variants variant join public.goods good on good.id=variant.good_id
   where variant.id=(line->>'variantId')::uuid and good.id=line->>'goodId';
  if supply is null then raise check_violation using message='sales_quote_variant_unavailable';end if;
  lines:=lines||jsonb_build_array(line||jsonb_build_object('supply',supply,'available',selling and (line->>'qty')::bigint<=(supply->>'availableQty')::integer));
  next_change:=least(next_change,(supply->>'nextChangeAt')::timestamptz);
 end loop;
 return quote||jsonb_build_object('lines',lines,'nextChangeAt',next_change);
end $function$

CREATE OR REPLACE FUNCTION private.goods_shipping_fee_for(target_order uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare origin_key uuid; lines jsonb; quote jsonb; destination jsonb; block_reason text;
begin
  for origin_key in select origin.id from public.fulfillment_origins origin where origin.id in (
    select item.origin_id_snapshot from public.order_items item where item.order_id=target_order
  ) order by origin.id for share loop
    if not (select is_active from public.fulfillment_origins where id=origin_key) then
      raise check_violation using message='fulfillment_origin_inactive'; end if;
  end loop;
  select jsonb_build_object('postalCode',address->>'postalCode','address1',address->>'address1') into destination from public.orders where id=target_order;
  if not found then raise no_data_found using message='order_not_found'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('origin_id',origin_id_snapshot,'good_id',good_id,'qty',qty,
    'unit_price',unit_price,'fee_type',shipping_fee_type_snapshot,'individual_fee',individual_fee_snapshot)),'[]')
    into lines from public.order_items where order_id=target_order;
  quote:=private.apply_shipping_region_quote(private.calculate_goods_shipping(lines),lines,destination,clock_timestamp());
  if not (quote->>'checkoutAllowed')::boolean then
    select value->>'regionStatus' into block_reason from jsonb_array_elements(quote->'groups') where value->>'finalFee' is null limit 1;
    raise check_violation using message='shipping_region_'||coalesce(block_reason,'unresolved');
  end if;
  update public.orders set shipping_fee_breakdown=quote->'groups' where id=target_order;
  return (quote->>'finalTotalFee')::bigint;
end $function$

CREATE OR REPLACE FUNCTION private.goods_slug_from_name(target_name text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  initials text[]:=array['g','kk','n','d','tt','r','m','b','pp','s','ss','','j','jj','ch','k','t','p','h'];
  vowels text[]:=array['a','ae','ya','yae','eo','e','yeo','ye','o','wa','wae','oe','yo','u','wo','we','wi','yu','eu','ui','i'];
  finals text[]:=array['','k','kk','ks','n','nj','nh','t','l','lk','lm','lb','ls','lt','lp','lh','m','p','ps','t','t','ng','t','t','k','t','p','h'];
  character text; syllable integer; result text:=''; position integer;
begin
  for position in 1..char_length(coalesce(target_name,'')) loop
    character:=substr(target_name,position,1);
    syllable:=ascii(character)-44032;
    if syllable between 0 and 11171 then
      result:=result||initials[syllable/588+1]||vowels[(syllable%588)/28+1]||finals[syllable%28+1];
    else result:=result||character; end if;
  end loop;
  result:=btrim(regexp_replace(lower(normalize(result,NFKD)),'[^a-z0-9]+','-','g'),'-');
  return coalesce(nullif(btrim(left(result,56),'-'),''),'good');
end;
$function$

CREATE OR REPLACE FUNCTION private.goods_variant_purchase_limit_problem(p_variant_id uuid, p_user_id uuid, p_qty bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare variant public.goods_variants;
begin
  select * into variant from public.goods_variants where id=p_variant_id;
  if not found or p_qty is null then return null; end if;
  if variant.order_max_qty is not null and p_qty>variant.order_max_qty then return 'option_order_limit_exceeded'; end if;
  if variant.member_max_qty is not null and p_user_id is not null
    and private.member_variant_reserved_qty(p_user_id,p_variant_id)+p_qty>variant.member_max_qty then
    return 'option_member_limit_exceeded';
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.goods_volume_terms_valid(p_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare starts timestamptz;ends timestamptz;begin
 if not private.transaction_json_keys(p_value,array['condition','threshold','discountKind','discountValue','startsAt','endsAt'])
  or coalesce(p_value->>'condition','') not in ('quantity','regular_subtotal') or coalesce(p_value->>'discountKind','') not in ('fixed','percent')
  or not private.transaction_uint(p_value->'threshold',case when p_value->>'condition'='quantity' then 2 else 1 end,
   case when p_value->>'condition'='quantity' then 2147483647 else 999999999999 end)
  or not private.transaction_uint(p_value->'discountValue',1,case when p_value->>'discountKind'='percent' then 100 else 2147483647 end) then return false;end if;
 if p_value->'startsAt'='null'::jsonb and p_value->'endsAt'='null'::jsonb then return true;end if;
 if not private.transaction_instant_valid(p_value->'startsAt') or not private.transaction_instant_valid(p_value->'endsAt') then return false;end if;
 starts:=(p_value->>'startsAt')::timestamptz;ends:=(p_value->>'endsAt')::timestamptz;
 return isfinite(starts) and isfinite(ends) and starts<ends;
exception when invalid_datetime_format or datetime_field_overflow then return false;
end $function$

