    raise check_violation using message = 'catalog_item_archived';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_category_tree()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_catalog_category_tree();
  if new.parent_id is not null then
    if tg_op='INSERT' then
      if exists(select 1 from public.goods where category_id=new.parent_id)
        or exists(select 1 from public.goods_additional_categories where category_id=new.parent_id) then
        raise check_violation using message='category_has_goods';
      end if;
    elsif (old.parent_id is distinct from new.parent_id or (old.archived_at is not null and new.archived_at is null))
      and (exists(select 1 from public.goods where category_id=new.parent_id)
        or exists(select 1 from public.goods_additional_categories where category_id=new.parent_id)) then
      raise check_violation using message='category_has_goods';
    end if;
  end if;
  new.depth:=private.category_validate_parent(new.id,new.parent_id);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_claim_defective_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.state = 'recorded' then raise check_violation using message = 'defective_stock_ledger_immutable'; end if;
    return old;
  end if;
  if old.state = 'recorded' then raise check_violation using message = 'defective_stock_ledger_immutable'; end if;
  if new.claim_id <> old.claim_id or new.order_item_id <> old.order_item_id or new.qty <> old.qty
    or new.planned_by <> old.planned_by or new.planned_at <> old.planned_at
    or new.source <> old.source or new.shipment_id is distinct from old.shipment_id then
    raise check_violation using message = 'defective_stock_plan_fields_immutable';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_community_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  selected_enabled boolean := false;
  moderation_hide_only boolean := false;
begin
  if private.is_community_write_maintenance() then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    moderation_hide_only := new.status = 'hidden'
      and (pg_catalog.to_jsonb(new) - 'status' - 'updated_at')
        is not distinct from
        (pg_catalog.to_jsonb(old) - 'status' - 'updated_at');

    if moderation_hide_only then
      return new;
    end if;
  end if;

  select case
    when tg_relid = 'public.posts'::regclass and tg_op = 'INSERT'
      then control.post_create_enabled
    when tg_relid = 'public.posts'::regclass and tg_op = 'UPDATE'
      then control.post_edit_enabled
    when tg_relid = 'public.comments'::regclass and tg_op = 'INSERT'
      then control.comment_create_enabled
    when tg_relid = 'public.comments'::regclass and tg_op = 'UPDATE'
      then control.comment_edit_enabled
    else false
  end
    into selected_enabled
  from private.community_write_control as control
  where control.singleton;

  if not coalesce(selected_enabled, false) then
    raise exception 'community_writes_disabled' using errcode = '55000';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_coupon_recipient()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare segment text; reason text;
begin
 select recipient_segment into segment from public.coupons where code=new.coupon_code;
 reason:=private.coupon_recipient_reason(segment,new.user_id);
 if reason is not null then raise check_violation using message=reason; end if;
 return new;
