CREATE OR REPLACE FUNCTION private.guard_good_category()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare child_count integer; archived_at timestamptz;
begin
  if new.category_id is null then return new; end if;
  select category.archived_at,
    (select count(*)::integer from public.catalog_categories as child where child.parent_id = category.id and child.archived_at is null)
    into archived_at, child_count
  from public.catalog_categories as category where category.id = new.category_id for share;
  if not found then raise foreign_key_violation using message = 'category_not_found'; end if;
  if archived_at is not null then
    if tg_op = 'UPDATE' then
      if old.category_id is not distinct from new.category_id then return new; end if;
    end if;
    raise check_violation using message = 'category_archived';
  end if;
  if child_count > 0 then raise check_violation using message = 'category_not_leaf'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_good_fulfillment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.published_at is not null then
    if new.origin_id is null then raise check_violation using message='fulfillment_origin_required'; end if;
    if tg_op='INSERT' or new.origin_id is distinct from old.origin_id or old.published_at is null then
      perform id from public.fulfillment_origins where id=new.origin_id and is_active for share;
      if not found then raise check_violation using message='fulfillment_origin_inactive'; end if;
    end if;
  end if;
  -- Keep the last input when its fee type is inactive; quoting still branches on fee type.
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_goods_additional_category()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare category_row public.catalog_categories;
begin
  perform private.lock_catalog_category_tree();
  select * into category_row from public.catalog_categories where id=new.category_id for share;
  if not found then raise foreign_key_violation using message='category_not_found'; end if;
  if category_row.archived_at is not null then raise check_violation using message='category_archived'; end if;
  if exists(select 1 from public.catalog_categories where parent_id=new.category_id and archived_at is null) then
    raise check_violation using message='category_not_leaf';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_goods_aggregation_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare owner_id text;owner_row public.goods;field text;begin
 owner_id:=private.goods_aggregation_owner(new.id);
 if owner_id=new.id then return new;end if;
 select * into owner_row from public.goods where id=owner_id;
 foreach field in array array['origin_id','shipping_fee_type','individual_fee','order_quantity_limit_enabled','min_order_qty','max_order_qty',
  'member_purchase_limit_enabled','member_lifetime_qty_limit'] loop
  -- An unrelated stale editor save is harmless. A deliberate separate policy is not.
  if to_jsonb(new)->field is distinct from to_jsonb(old)->field and to_jsonb(new)->field is distinct from to_jsonb(owner_row)->field then
   raise check_violation using message='goods_aggregation_policy_owned_by_source';end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_goods_custom_input_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  new.custom_input_fields:=private.normalize_goods_custom_input_fields(new.custom_input_fields);
  if new.custom_inputs_enabled and not exists(select 1 from jsonb_array_elements(new.custom_input_fields) field where (field->>'active')::boolean) then
    raise check_violation using message='invalid_goods_custom_input_fields';
  end if;
  if tg_op='INSERT' then
    new.custom_inputs_revision:=case when new.custom_inputs_enabled or new.custom_input_fields<>'[]' then 1 else 0 end;
  elsif (new.custom_inputs_enabled,new.custom_input_fields) is distinct from (old.custom_inputs_enabled,old.custom_input_fields) then
    new.custom_inputs_revision:=old.custom_inputs_revision+1;
  else new.custom_inputs_revision:=old.custom_inputs_revision;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_goods_group_common_information()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_good text;new_good text;before_value jsonb;after_value jsonb;
begin
 if tg_op<>'INSERT' then old_good:=case when tg_table_name='goods' then to_jsonb(old)->>'id' else to_jsonb(old)->>'good_id' end;end if;
 if tg_op<>'DELETE' then new_good:=case when tg_table_name='goods' then to_jsonb(new)->>'id' else to_jsonb(new)->>'good_id' end;end if;
 if tg_table_name='goods' then
  before_value:=private.goods_group_common_public_fields(to_jsonb(old));after_value:=private.goods_group_common_public_fields(to_jsonb(new));
 elsif tg_table_name='goods_attribute_values' then
  before_value:=coalesce(to_jsonb(old)->'entries','[]');after_value:=coalesce(to_jsonb(new)->'entries','[]');
 elsif tg_table_name='goods_after_sales_content' then
  if tg_op<>'INSERT' then before_value:=jsonb_build_array(old.phone,old.guide,old.seller_special_notes);end if;
  if tg_op<>'DELETE' then after_value:=jsonb_build_array(new.phone,new.guide,new.seller_special_notes);end if;
 elsif tg_table_name='goods_size_charts' then
  if tg_op<>'INSERT' then before_value:=jsonb_build_array(old.enabled,old.chart);end if;
  if tg_op<>'DELETE' then after_value:=jsonb_build_array(new.enabled,new.chart);end if;
 elsif tg_table_name='goods_additional_categories' then
  if tg_op='INSERT' and exists(select 1 from public.goods_additional_categories where good_id=new.good_id and category_id=new.category_id) then return new;end if;
  if tg_op<>'INSERT' then before_value:=jsonb_build_array(old.good_id,old.category_id);end if;
  if tg_op<>'DELETE' then after_value:=jsonb_build_array(new.good_id,new.category_id);end if;
 end if;
 if old_good is not null then perform private.assert_goods_group_common_write(old_good,before_value,after_value);end if;
 if new_good is distinct from old_good then perform private.assert_goods_group_common_write(new_good,before_value,after_value);end if;
 if tg_op='DELETE' then return old;end if;return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_goods_group_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from private.goods_group_members where good_id=old.id) then
  if new.id is distinct from old.id then raise check_violation using message='goods_group_identity_immutable';end if;
  if new.name is distinct from old.name and not exists(select 1 from private.goods_group_write_authorizations
   where transaction_id=txid_current() and good_id=old.id and actor_id=auth.uid()) then
   raise check_violation using message='goods_group_name_owned_by_group';end if;
 end if;
 return new;
