$function$

CREATE OR REPLACE FUNCTION private.guard_goods_kc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare changed boolean;
begin
  if new.archived_at is not null then new.published_at:=null; end if;
  if tg_op='INSERT' then
    new.kc_disclosures:='[]';
    if new.published_at is not null then raise check_violation using message='goods_kc_review_required'; end if;
    return new;
  end if;
  changed:=row(old.ip_id,old.name,old.notice_maker,old.notice_origin,old.notice_material,old.notice_size)
    is distinct from row(new.ip_id,new.name,new.notice_maker,new.notice_origin,new.notice_material,new.notice_size);
  if changed then
    if new.published_at is not null then raise check_violation using message='goods_kc_reassessment_required'; end if;
    perform private.invalidate_goods_kc_review(old.id,'goods_context_changed');
  end if;
  if new.published_at is not null and old.published_at is null and (changed or not private.goods_kc_review_current(old.id)) then
    raise check_violation using message='goods_kc_review_required';
  end if;
  -- The column cannot be supplied by any generic catalog writer, clone payload,
  -- workbook, or trusted direct update. It is always an explicit public allowlist.
  new.kc_disclosures:=case when changed then '[]'::jsonb else private.goods_kc_public_disclosures(old.id) end;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_goods_option_sale_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target text; problem text; candidates text[];
begin
  if tg_table_name='goods' then
    candidates:=array[new.id];
  else
    candidates:=array[
      case when tg_op<>'DELETE' then to_jsonb(new)->>'good_id' end,
      case when tg_op<>'INSERT' then to_jsonb(old)->>'good_id' end,
      case when tg_op<>'DELETE' then to_jsonb(new)->>'root_good_id' end,
      case when tg_op<>'DELETE' then to_jsonb(new)->>'common_good_id' end];
  end if;
  for target in select distinct candidate from unnest(candidates) candidate where candidate is not null loop
    if exists(select 1 from public.goods where id=target and option_sale_mode='random') then
      problem:=private.goods_random_option_problem(target);
      if problem is not null then raise check_violation using message=problem; end if;
    end if;
  end loop;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.guard_goods_price_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare variant public.goods_variants;
begin
  perform 1 from public.goods where id=new.good_id for update;
  select * into variant from public.goods_variants
    where id=new.variant_id and good_id=new.good_id for update;
  if not found then raise check_violation using message='goods_variant_not_found'; end if;
  if tg_op='UPDATE' then
    -- A never-published good can still change its draft slug. Its immutable
    -- option id remains the identity while the composite FK cascades good_id.
    if (new.id,new.variant_id,new.created_at,new.created_by)
      is distinct from (old.id,old.variant_id,old.created_at,old.created_by) then
      raise check_violation using message='price_period_identity_immutable';
    end if;
    if old.state in ('active','disabled') and (
      (new.regular_price,new.discount_price,new.starts_at,new.ends_at)
        is distinct from (old.regular_price,old.discount_price,old.starts_at,old.ends_at)
      or new.state='draft' or (old.state='disabled' and new.state<>'disabled')
    ) then raise check_violation using message='price_period_requires_new_version'; end if;
  end if;
  if new.state='active' then
    if variant.archived_at is not null then
      raise check_violation using message='price_period_variant_inactive';
    end if;
    if new.regular_price is distinct from variant.price then
      raise check_violation using message='price_period_regular_price_changed';
    end if;
    if exists(select 1 from private.goods_variant_price_periods period
      where period.variant_id=new.variant_id and period.id<>new.id and period.state='active'
        and tstzrange(period.starts_at,period.ends_at,'[)') && tstzrange(new.starts_at,new.ends_at,'[)')) then
      raise exclusion_violation using message='price_period_overlap';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_goods_public_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='UPDATE' then
    if old.first_published_at is not null and new.id is distinct from old.id then
      raise check_violation using message='goods_slug_locked';
    end if;
    if old.first_published_at is not null then new.first_published_at:=old.first_published_at; end if;
  end if;
  if new.archived_at is not null then new.published_at:=null; end if;
  if new.published_at is not null and new.first_published_at is null then new.first_published_at:=clock_timestamp(); end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_goods_stock_cache()
