CREATE OR REPLACE FUNCTION private.guard_home_collection_banner_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  effective_start timestamptz;
  window_end timestamptz;
  overlapping integer;
begin
  if new.kind <> 'collection_banner' or not new.enabled or new.archived_at is not null then
    return new;
  end if;
  if tg_op = 'UPDATE'
    and old.kind = new.kind
    and old.slot is not distinct from new.slot
    and old.enabled = new.enabled
    and old.archived_at is not distinct from new.archived_at
    and old.active_from = new.active_from
    and old.active_to is not distinct from new.active_to
  then
    return new;
  end if;

  effective_start := greatest(new.active_from, pg_catalog.now());
  window_end := coalesce(new.active_to, 'infinity'::timestamptz);
  if window_end <= effective_start then
    -- The window is already over: this row can never be shown again.
    return new;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('home_collection_banner_live:' || coalesce(new.slot, ''), 0)
  );

  select count(*)
    into overlapping
  from public.home_curations as curation
  where curation.kind = 'collection_banner'
    and curation.slot = new.slot
    and curation.enabled
    and curation.archived_at is null
    and curation.id <> new.id
    and curation.active_from < window_end
    and coalesce(curation.active_to, 'infinity'::timestamptz) > effective_start;

  if overlapping >= 10 then
    raise check_violation using message = 'collection_banner_limit';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_home_free_product_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and new.kind is distinct from old.kind and (old.kind='product_collection' or new.kind='product_collection') then
  raise invalid_parameter_value using message='curation_kind_change_not_allowed';end if;
 if new.kind not in ('product_mosaic','product_collection') then return new;end if;
 if tg_op='UPDATE' and old.kind in ('product_mosaic','product_collection') then return new;end if;
 perform pg_advisory_xact_lock(hashtextextended('home_free_product_count',0));
 if (select count(*) from public.home_curations where kind in ('product_mosaic','product_collection') and id<>new.id)>=5 then
  raise check_violation using message='home_free_product_limit';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_home_mosaic_artwork()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare image text; previous_paths text[]:='{}'; claim public.admin_artwork_upload_claims;
begin
  if new.kind<>'product_mosaic' then return new; end if;
  if not private.is_valid_home_mosaic(new.payload) then raise invalid_parameter_value using message='invalid_curation_mosaic'; end if;
  if tg_op='UPDATE' and old.kind='product_mosaic' then
    select coalesce(array_agg(distinct item->>'image_path') filter(where item->>'image_path' is not null),'{}')
      into previous_paths from jsonb_array_elements(old.payload->'slots') item;
  end if;
  for image in select distinct item->>'image_path' from jsonb_array_elements(new.payload->'slots') item
    where item->>'image_path' is not null order by 1
  loop
    if image=any(previous_paths) then continue; end if;
    select * into claim from public.admin_artwork_upload_claims where path=substr(image,length('public-media/')+1) for update;
    if not found or claim.actor_id is distinct from auth.uid() or claim.kind<>'curation' or claim.status<>'verified'
      or claim.verified_at is null or claim.final_size is null or claim.attached_at is not null or claim.expires_at<=clock_timestamp()
    then raise check_violation using message='unverified_artwork'; end if;
    if claim.source_size>900*1024 or claim.final_size>900*1024 then raise check_violation using message='mosaic_image_too_large'; end if;
    update public.admin_artwork_upload_claims set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp() where path=claim.path;
  end loop;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_home_promotion_banner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous_live boolean:=false; next_live boolean;
begin
 -- Version precision and legacy long-copy preservation remain unchanged.
 if tg_op='UPDATE' then
  new.updated_at:=greatest(clock_timestamp(),old.updated_at+interval '1 microsecond');
  previous_live:=old.kind='hero' and old.archived_at is null;
 end if;
 next_live:=new.kind='hero' and new.archived_at is null;
 -- Both exits and entries serialize through the same count pool. Row locks are
 -- already owned on updates; the pool holder never locks another curation row.
 if previous_live is distinct from next_live then
  perform pg_advisory_xact_lock(hashtextextended('home_promotion_banner_count',0));
  if next_live and (select count(*) from public.home_curations where kind='hero' and archived_at is null and id<>new.id)>=10 then
   raise check_violation using message='home_hero_limit';
  end if;
 end if;
 if new.kind<>'hero' then return new;end if;
 if (tg_op='INSERT' or old.kind<>'hero' or new.title is distinct from old.title) and char_length(new.title)>40 then
  raise invalid_parameter_value using message='invalid_hero_title';
 end if;
 if (tg_op='INSERT' or old.kind<>'hero' or new.payload->>'subtitle' is distinct from old.payload->>'subtitle')
  and (char_length(new.payload->>'subtitle')>150 or cardinality(string_to_array(new.payload->>'subtitle',chr(10)))>3) then
  raise invalid_parameter_value using message='invalid_hero_subtitle';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_ip_directory_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  -- Legacy metadata writers can already hold an IP row lock. Refuse contention
  -- rather than waiting behind a directory RPC that holds the global lock first.
  if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('ip_directory_settings',0)) then
    raise sqlstate 'PT409' using message='ip_directory_conflict';
  end if;
  if tg_op='INSERT' and new.sort_order=0 then
    select coalesce(max(sort_order),0)+1 into new.sort_order from public.ips;
  end if;
  if new.featured and (select count(*) from public.ips where featured and id<>new.id)>=5 then
    raise check_violation using message='ip_featured_limit';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_ip_hall_banner_artwork()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_actor_id uuid := (select auth.uid());
  previous_paths text[] := '{}';
  banner_path text;
begin
  if tg_op = 'UPDATE' then
    previous_paths := pg_catalog.array_remove(
      array[old.hall_banner_image_path, old.hall_banner_mobile_image_path], null
    );
  end if;

  for banner_path in
    select distinct candidate
    from pg_catalog.unnest(array[new.hall_banner_image_path, new.hall_banner_mobile_image_path]) as paths(candidate)
    where candidate is not null
    order by candidate
  loop
    if banner_path = any(previous_paths) then continue; end if;

    if current_actor_id is null then
      -- Migrations and seeds run as postgres without a request actor.
      if session_user = 'postgres' then continue; end if;
      raise check_violation using message = 'unverified_artwork';
    end if;

    update public.admin_artwork_upload_claims as claim
    set
      status = 'attached',
      attached_at = pg_catalog.clock_timestamp(),
      resolved_at = pg_catalog.clock_timestamp()
    where claim.actor_id = current_actor_id
      and claim.path = pg_catalog.substr(banner_path, pg_catalog.length('public-media/') + 1)
      and claim.kind = 'ip'
      and claim.status = 'verified'
      and claim.verified_at is not null
      and claim.final_size is not null
      and claim.attached_at is null
      and claim.expires_at > pg_catalog.clock_timestamp();

    if not found then
      raise check_violation using message = 'unverified_artwork';
    end if;
  end loop;

  return new;
end $function$

