CREATE OR REPLACE FUNCTION private.guard_order_item_variant_purchase_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare variant public.goods_variants; buyer uuid; in_order bigint;
begin
  select * into variant from public.goods_variants where id=new.variant_id;
  if not found or (variant.order_max_qty is null and variant.member_max_qty is null) then return new; end if;
  if variant.order_max_qty is not null then
    select coalesce(sum(item.qty::bigint),0) into in_order from public.order_items item
      where item.order_id=new.order_id and item.variant_id=new.variant_id;
    if in_order+new.qty>variant.order_max_qty then
      raise check_violation using message=format('option_order_limit_exceeded: %s',new.variant_id);
    end if;
  end if;
  if variant.member_max_qty is not null then
    select o.user_id into buyer from public.orders o where o.id=new.order_id;
    if buyer is not null and private.member_variant_reserved_qty(buyer,new.variant_id)+new.qty>variant.member_max_qty then
      raise check_violation using message=format('option_member_limit_exceeded: %s',new.variant_id);
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_order_transaction_terms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare version integer;begin
 select calculation_version into version from public.orders where id=new.order_id;
 if version=2 then
  if not exists(select 1 from private.order_goods_transactions where order_id=new.order_id) then
   raise check_violation using message='transaction_order_binding_required';end if;
 elsif exists(select 1 from private.shipping_charge_group_assignments where owner_good_id=private.goods_aggregation_owner(new.good_id) and group_id is not null) then
  raise check_violation using message='checkout_contract_upgrade_required';
 elsif exists(select 1 from private.goods_aggregation_members where good_id=new.good_id) then
  raise check_violation using message='checkout_contract_upgrade_required';
 elsif exists(select 1 from private.goods_transaction_configs c left join private.goods_volume_discount_versions v on v.id=c.volume_version_id
  left join private.goods_delivery_versions d on d.id=c.delivery_version_id where c.good_id=new.good_id and (v.status='active' or d.status='active')) then
  raise check_violation using message='checkout_contract_upgrade_required';
 elsif new.volume_unit_discount<>0 or new.volume_discount_total<>0 then raise check_violation using message='transaction_order_binding_required';end if;
 return new;
end $function$

