CREATE OR REPLACE FUNCTION private.guard_shipment_delivery_method()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare operation private.shipment_delivery_operations;begin
 if tg_op='INSERT' then
  if new.delivery_method<>'parcel' or new.fulfillment_partition<>'parcel' then
   if new.fulfillment_partition<>new.delivery_method or not exists(select 1 from public.orders o join private.order_goods_transactions t on t.order_id=o.id
    where o.id=new.order_id and o.calculation_version=2 and o.shipping_fee_breakdown @> jsonb_build_array(new.shipping_fee_snapshot)
     and new.shipping_fee_snapshot->>'deliveryMethod'=new.delivery_method and new.shipping_fee_snapshot->'deliveryPolicy'=new.delivery_method_snapshot)
    then raise check_violation using message='delivery_method_selection_required';end if;
  end if;return new;
 end if;
 if new.fulfillment_partition is distinct from old.fulfillment_partition then raise check_violation using message='fulfillment_partition_immutable';end if;
 if new.delivery_method is distinct from old.delivery_method or new.delivery_selection_id is distinct from old.delivery_selection_id or new.delivery_method_snapshot is distinct from old.delivery_method_snapshot or new.delivery_policy_id is distinct from old.delivery_policy_id then
  if old.fulfillment_partition in('none','digital') then raise check_violation using message='delivery_method_fixed';end if;
  select * into operation from private.shipment_delivery_operations where id=new.delivery_selection_id and shipment_id=new.id and kind='method_selected';
  if not found or old.status<>'ready' or new.status<>'ready' or old.exported_at is not null or operation.evidence->>'toMethod' is distinct from new.delivery_method
   or operation.evidence->>'fromMethod' is distinct from old.delivery_method then raise check_violation using message='delivery_method_selection_required';end if;
 end if;
 if new.delivery_method<>'parcel' then
  if new.carrier is not null or new.tracking_number is not null or new.exported_at is distinct from old.exported_at then raise check_violation using message='delivery_method_evidence_required';end if;
  if new.status in('shipping','delivered') and(new.status is distinct from old.status or new.shipped_at is distinct from old.shipped_at or new.delivered_at is distinct from old.delivered_at) then
   select * into operation from private.shipment_delivery_operations where id=new.delivery_event_id and shipment_id=new.id;
   if not found or not(
    new.delivery_method in('quick','direct','freight') and old.status='ready' and new.status='shipping' and operation.kind=new.delivery_method||'_handoff'
    or new.delivery_method in('quick','direct','freight') and old.status='shipping' and new.status='delivered' and operation.kind=new.delivery_method||'_receive'
    or new.delivery_method in('pickup','none') and old.status='ready' and new.status='delivered' and operation.kind=new.delivery_method||'_receive'
    or new.delivery_method='digital' and old.status='ready' and new.status='delivered' and operation.kind='digital_access'
    or new.delivery_method in('quick','direct','freight','pickup','none') and old.status in('ready','shipping') and new.status='delivered' and operation.kind='forced_delivered'
   ) then raise check_violation using message='delivery_method_evidence_required';end if;
   if(operation.evidence->>'occurredAt')::timestamptz is distinct from(case when new.status='shipping' then new.shipped_at else new.delivered_at end) then raise check_violation using message='delivery_method_evidence_required';end if;
   if new.delivery_method='digital' then
    if exists(select 1 from public.order_shipment_items i where i.shipment_id=new.id and not exists(select 1 from private.order_digital_downloads d where d.order_item_id=i.order_item_id and d.order_id=new.order_id)) then raise check_violation using message='digital_delivery_incomplete';end if;
   elsif new.status='delivered' and operation.kind<>'forced_delivered' and not exists(select 1 from private.shipment_receipt_confirmations c where c.shipment_id=new.id and c.selection_id=new.delivery_selection_id and c.consumed_operation_id=new.delivery_event_id and c.consumed_at is not null) then raise check_violation using message='delivery_method_evidence_required';end if;
   perform private.assert_shipment_preorder_ready(new.id);
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_subscription_immutable_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare before jsonb:=to_jsonb(old);after jsonb:=to_jsonb(new);field text;begin
 if tg_table_name in('goods_subscription_terms','goods_subscription_operations','goods_subscription_proposals','billing_credential_operations','payment_provider_bindings','billing_refund_operations') then
  raise check_violation using message='subscription_evidence_immutable';
 elsif tg_table_name='billing_profiles' then
  if after-'enabled' is distinct from before-'enabled' then raise check_violation using message='billing_profile_immutable';end if;
 elsif tg_table_name='billing_customers' then
  if after is distinct from before then raise check_violation using message='billing_customer_immutable';end if;
 elsif tg_table_name='billing_credentials' then
  if after-array['envelope','state','revision','revoked_at','revoke_claim_token','revoke_lease_until','revoke_fence','revoke_next_check_at']
   is distinct from before-array['envelope','state','revision','revoked_at','revoke_claim_token','revoke_lease_until','revoke_fence','revoke_next_check_at'] then
   raise check_violation using message='billing_credential_identity_immutable';end if;
 elsif tg_table_name='billing_enrollments' then
  if after-array['auth_envelope','auth_fingerprint','state','claim_token','lease_until','claim_fence','first_dispatched_at','recovery_until','updated_at','safe_reason']
   is distinct from before-array['auth_envelope','auth_fingerprint','state','claim_token','lease_until','claim_fence','first_dispatched_at','recovery_until','updated_at','safe_reason'] then
   raise check_violation using message='billing_registration_identity_immutable';end if;
 elsif tg_table_name='goods_subscription_plans' then
  foreach field in array array['id','owner_id','creation_operation_id','creation_request_hash','first_cycle_id'] loop
   if after->field is distinct from before->field then raise check_violation using message='subscription_identity_immutable';end if;
  end loop;
 elsif tg_table_name='goods_subscription_cycles' then
  foreach field in array array['id','plan_id','owner_id','cycle_number','schedule_slot','terms_id'] loop
   if after->field is distinct from before->field then raise check_violation using message='subscription_cycle_identity_immutable';end if;
  end loop;
  foreach field in array array['order_id','attempt_id','dispatched_at'] loop
   if before->>field is not null and after->field is distinct from before->field then raise check_violation using message='subscription_cycle_identity_immutable';end if;
  end loop;
  if after->'scheduled_at' is distinct from before->'scheduled_at' and not(before->>'state'='draft' and after->>'state'='prepared') then
   raise check_violation using message='subscription_cycle_identity_immutable';end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.has_operator_capability(p_actor uuid, p_capability text, p_legacy_admin_only boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare access jsonb;
begin
  access := private.operator_access_for(p_actor);
  if not coalesce(access->'capabilities' ? p_capability,false)
    -- sales.manage는 출고 전용 sales.dispatch를 포함한다(1014-084).
    and not (p_capability='sales.dispatch' and coalesce(access->'capabilities' ? 'sales.manage',false)) then return false; end if;
  -- 운영자 2단계 인증(OPS-006): 스위치가 켜지면 지금 요청의 aal2 세션만 운영자로 본다.
  if private.operator_mfa_blocks(p_actor) then return false; end if;
  if access->>'mode'='legacy' and p_legacy_admin_only then
    return exists(select 1 from public.profiles where id=p_actor and role='admin' and suspended_at is null);
  end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.has_recent_account_authentication(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_session_id_text text := auth.jwt() ->> 'session_id';
  v_session_id uuid;
begin
  if p_user_id is null
    or v_session_id_text is null
    or v_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  then
    return false;
  end if;

  begin
    v_session_id := v_session_id_text::uuid;
  exception
    when invalid_text_representation then
      return false;
  end;

  return exists (
    select 1
    from auth.sessions as auth_session
    where auth_session.id = v_session_id
      and auth_session.user_id = p_user_id
      and auth_session.created_at >= pg_catalog.now() - interval '10 minutes'
      and (
        auth_session.not_after is null
        or auth_session.not_after > pg_catalog.now()
      )
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.inquiry_file_session(p_actor uuid, p_session uuid, p_staff boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if p_actor is null or p_session is null then raise insufficient_privilege;end if;
 perform private.lock_account_action_subject(p_actor);
 perform private.assert_active_user(p_actor);
 if private.is_account_write_fenced(p_actor) then raise insufficient_privilege;end if;
 perform 1 from auth.sessions where id=p_session and user_id=p_actor and(not_after is null or not_after>clock_timestamp()) for share;
 if not found then raise insufficient_privilege;end if;
 if p_staff then perform private.require_actor_operator_capability(p_actor,'cs.manage');
  if not private.operator_mfa_service_session_ok(p_actor,p_session) then raise insufficient_privilege using message='operator_mfa_required';end if;
 end if;
end $function$

CREATE OR REPLACE FUNCTION private.inquiry_satisfaction_current(p_inquiry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare state private.inquiry_satisfaction_state%rowtype; answer uuid; answer_at timestamptz; current_value text; current_rated_at timestamptz; current_revision bigint:=0;
begin
 select * into state from private.inquiry_satisfaction_state where inquiry_id=p_inquiry_id;
 if found then
  current_revision:=state.revision;
  select id,created_at into answer,answer_at from public.inquiry_messages
   where id=state.latest_answer_id and inquiry_id=p_inquiry_id and author='staff';
  if answer is not null and answer=state.value_answer_id then current_value:=state.value;current_rated_at:=state.rated_at;end if;
 else
  select id,created_at into answer,answer_at from public.inquiry_messages
   where inquiry_id=p_inquiry_id and author='staff' order by created_at desc,id desc limit 1;
 end if;
 return jsonb_build_object('inquiryId',p_inquiry_id,'answerId',answer,'answerCreatedAt',answer_at,
  'value',current_value,'revision',current_revision,'ratedAt',current_rated_at);
end $function$

CREATE OR REPLACE FUNCTION private.inquiry_satisfaction_request(p_operation_id uuid, p_inquiry_id uuid, p_expected_actor_id uuid, p_expected_session_id uuid, p_expected_answer_id uuid, p_expected_revision bigint, p_desired_value text, p_write boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor uuid:=private.inquiry_satisfaction_viewer();
begin
 if p_operation_id is null or p_inquiry_id is null or p_expected_actor_id is null or p_expected_session_id is null
  or p_expected_answer_id is null or p_expected_revision is null or p_expected_revision<0 or p_expected_revision>9007199254740991
  or p_desired_value is not null and p_desired_value not in ('satisfied','dissatisfied') or p_write is null then
  raise invalid_parameter_value using message='inquiry_satisfaction_invalid_request';end if;
 if actor is null or actor<>p_expected_actor_id or (auth.jwt()->>'session_id')::uuid<>p_expected_session_id then
  raise invalid_authorization_specification using message='inquiry_satisfaction_auth_required';end if;
 perform private.lock_account_action_subject(actor);
 perform 1 from auth.users where id=actor for share nowait;
 perform 1 from public.profiles where id=actor for share nowait;
 perform 1 from auth.sessions where id=p_expected_session_id and user_id=actor for share nowait;
 if private.inquiry_satisfaction_viewer() is distinct from actor then
  raise invalid_authorization_specification using message='inquiry_satisfaction_auth_required';end if;
 if p_write and not private.inquiry_satisfaction_active(actor) then
  raise insufficient_privilege using message='inquiry_satisfaction_account_unavailable';end if;
 perform pg_advisory_xact_lock(hashtextextended('inquiry-satisfaction-operation:'||actor::text||':'||p_operation_id::text,0));
 return jsonb_build_object('operationId',p_operation_id,'inquiryId',p_inquiry_id,'expectedActorId',actor,
  'expectedSessionId',p_expected_session_id,'expectedAnswerId',p_expected_answer_id,'expectedRevision',p_expected_revision,'desiredValue',p_desired_value);
end $function$

CREATE OR REPLACE FUNCTION private.insert_discount_promotion_period(p_promotion_id uuid, p_good_id text, p_variant_id uuid, p_discount_price integer, p_starts timestamp with time zone, p_ends timestamp with time zone, p_actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare variant public.goods_variants; saved private.goods_variant_price_periods;
begin
  perform 1 from public.goods where id=p_good_id for update;
  select * into variant from public.goods_variants where id=p_variant_id and good_id=p_good_id for update;
  if not found then raise check_violation using message='goods_variant_not_found'; end if;
  insert into private.goods_variant_price_periods(good_id,variant_id,state,regular_price,discount_price,starts_at,ends_at,created_by,updated_by,promotion_id)
  values(p_good_id,p_variant_id,'active',variant.price,p_discount_price,p_starts,p_ends,p_actor,p_actor,p_promotion_id)
  returning * into saved;
  insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'admin.good.price_period_saved','goods:'||p_good_id,
    jsonb_build_object('before',null,'after',to_jsonb(saved)));
  return saved.id;
end $function$

CREATE OR REPLACE FUNCTION private.insert_operator_invitation(p_entry jsonb, p_actor uuid, p_created_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare entry jsonb:=private.normalize_operator_invitation(p_entry); intent jsonb; invitation_id uuid:=(entry->>'id')::uuid;
begin
  if exists(select 1 from auth.users u join private.operator_memberships m on m.profile_id=u.id where u.email_confirmed_at is not null and lower(u.email)=entry->>'email')
    then raise invalid_parameter_value using message='operator_already_manager'; end if;
  if exists(select 1 from private.operator_invitations where recipient_email=entry->>'email' and status='pending' and expires_at>p_created_at)
    then raise invalid_parameter_value using message='operator_invitation_pending'; end if;
  if (select count(*) from private.operator_memberships where manager_role<>'owner')+
    (select count(*) from private.operator_invitations where status='pending' and expires_at>p_created_at)>=1000
    then raise invalid_parameter_value using message='operator_limit'; end if;
  intent:=public.enqueue_email_intent('operator_invitation',entry->>'sourceDigest',entry->>'recipientDigest','operator_invitation','operator_invitation_v1');
  insert into private.operator_invitations(id,recipient_email,recipient_name,recipient_digest,token_hash,manager_role,duty,created_by,created_at,expires_at,email_intent_id)
  values(invitation_id,entry->>'email',entry->>'name',decode(entry->>'recipientDigest','hex'),decode(entry->>'tokenHash','hex'),entry->>'managerRole',entry->>'duty',p_actor,p_created_at,p_created_at+interval '7 days',(intent->>'intentId')::uuid);
  return invitation_id;
end $function$

CREATE OR REPLACE FUNCTION private.invalidate_claim_fee_basis()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i private.claim_fee_invoices;changed boolean:=false;begin
 if new.claim_type is not distinct from old.claim_type and new.reason_type is not distinct from old.reason_type and new.reason is not distinct from old.reason
  and not(new.stage in('rejected','withdrawn') and new.stage is distinct from old.stage) then return null;end if;
 for i in select * from private.claim_fee_invoices where claim_id=new.id and state in('unpaid','reported','paid') order by id for update loop
  update private.claim_fee_invoices set state=case when i.state='paid' then 'refund_due' else 'voided' end,updated_at=clock_timestamp() where id=i.id;
  insert into private.claim_fee_events(id,claim_id,invoice_id,kind,request) values(gen_random_uuid(),new.id,i.id,'basis_changed','{}');changed:=true;
 end loop;
 if changed then update private.claim_fee_ledgers set revision=revision+1 where claim_id=new.id;end if;return null;
end $function$

