CREATE OR REPLACE FUNCTION private.is_safe_home_curation_link(candidate text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  candidate_length integer := pg_catalog.char_length(candidate);
  character_position integer := 1;
  consumed_characters integer;
  current_character text;
  first_byte integer;
  second_byte integer;
  third_byte integer;
  fourth_byte integer;
  decoded_codepoint integer;
  decoded_link text;
begin
  if candidate_length not between 1 and 2048
    or pg_catalog.left(candidate, 1) <> '/'
    or pg_catalog.left(candidate, 2) = '//'
    or pg_catalog.strpos(candidate, E'\\') > 0
    or candidate ~ '[[:cntrl:]]'
    or candidate ~ U&'[\061C\200E\200F\2028-\202E\2066-\2069]'
  then
    return false;
  end if;

  decoded_link := '';
  while character_position <= candidate_length loop
    current_character := pg_catalog.substr(candidate, character_position, 1);
    if current_character <> '%' then
      decoded_link := decoded_link || current_character;
      character_position := character_position + 1;
      continue;
    end if;

    if character_position + 2 > candidate_length
      or pg_catalog.substr(candidate, character_position + 1, 2)
        !~ '^[0-9A-Fa-f]{2}$'
    then
      return false;
    end if;

    first_byte := pg_catalog.get_byte(
      pg_catalog.decode(
        pg_catalog.substr(candidate, character_position + 1, 2),
        'hex'
      ),
      0
    );

    if first_byte <= 127 then
      decoded_codepoint := first_byte;
      consumed_characters := 3;
    elsif first_byte between 194 and 223 then
      if character_position + 5 > candidate_length
        or pg_catalog.substr(candidate, character_position + 3, 1) <> '%'
        or pg_catalog.substr(candidate, character_position + 4, 2)
          !~ '^[0-9A-Fa-f]{2}$'
      then
        return false;
      end if;
      second_byte := pg_catalog.get_byte(
        pg_catalog.decode(
          pg_catalog.substr(candidate, character_position + 4, 2),
          'hex'
        ),
        0
      );
      if second_byte not between 128 and 191 then
        return false;
      end if;
      decoded_codepoint := ((first_byte & 31) << 6) | (second_byte & 63);
      consumed_characters := 6;
    elsif first_byte between 224 and 239 then
      if character_position + 8 > candidate_length
        or pg_catalog.substr(candidate, character_position + 3, 1) <> '%'
        or pg_catalog.substr(candidate, character_position + 6, 1) <> '%'
        or pg_catalog.substr(candidate, character_position + 4, 2)
          !~ '^[0-9A-Fa-f]{2}$'
        or pg_catalog.substr(candidate, character_position + 7, 2)
          !~ '^[0-9A-Fa-f]{2}$'
      then
        return false;
      end if;
      second_byte := pg_catalog.get_byte(
        pg_catalog.decode(
          pg_catalog.substr(candidate, character_position + 4, 2),
          'hex'
        ),
        0
      );
      third_byte := pg_catalog.get_byte(
        pg_catalog.decode(
          pg_catalog.substr(candidate, character_position + 7, 2),
          'hex'
        ),
        0
      );
      if second_byte not between 128 and 191
        or third_byte not between 128 and 191
        or (first_byte = 224 and second_byte < 160)
        or (first_byte = 237 and second_byte > 159)
      then
        return false;
      end if;
      decoded_codepoint := ((first_byte & 15) << 12)
        | ((second_byte & 63) << 6)
        | (third_byte & 63);
      consumed_characters := 9;
    elsif first_byte between 240 and 244 then
      if character_position + 11 > candidate_length
        or pg_catalog.substr(candidate, character_position + 3, 1) <> '%'
        or pg_catalog.substr(candidate, character_position + 6, 1) <> '%'
        or pg_catalog.substr(candidate, character_position + 9, 1) <> '%'
        or pg_catalog.substr(candidate, character_position + 4, 2)
          !~ '^[0-9A-Fa-f]{2}$'
        or pg_catalog.substr(candidate, character_position + 7, 2)
          !~ '^[0-9A-Fa-f]{2}$'
        or pg_catalog.substr(candidate, character_position + 10, 2)
          !~ '^[0-9A-Fa-f]{2}$'
      then
        return false;
      end if;
      second_byte := pg_catalog.get_byte(
        pg_catalog.decode(
          pg_catalog.substr(candidate, character_position + 4, 2),
          'hex'
        ),
        0
      );
      third_byte := pg_catalog.get_byte(
        pg_catalog.decode(
          pg_catalog.substr(candidate, character_position + 7, 2),
          'hex'
        ),
        0
      );
      fourth_byte := pg_catalog.get_byte(
        pg_catalog.decode(
          pg_catalog.substr(candidate, character_position + 10, 2),
          'hex'
        ),
        0
      );
      if second_byte not between 128 and 191
        or third_byte not between 128 and 191
        or fourth_byte not between 128 and 191
        or (first_byte = 240 and second_byte < 144)
        or (first_byte = 244 and second_byte > 143)
      then
        return false;
      end if;
      decoded_codepoint := ((first_byte & 7) << 18)
        | ((second_byte & 63) << 12)
        | ((third_byte & 63) << 6)
        | (fourth_byte & 63);
      consumed_characters := 12;
    else
      return false;
    end if;

    if decoded_codepoint between 0 and 31
      or decoded_codepoint between 127 and 159
      or decoded_codepoint = 1564
      or decoded_codepoint in (8206, 8207)
      or decoded_codepoint between 8232 and 8238
      or decoded_codepoint between 8294 and 8297
    then
      return false;
    end if;

    decoded_link := decoded_link || pg_catalog.chr(decoded_codepoint);
    character_position := character_position + consumed_characters;
  end loop;

  return pg_catalog.left(decoded_link, 1) = '/'
    and pg_catalog.left(decoded_link, 2) <> '//'
    and pg_catalog.strpos(decoded_link, E'\\') = 0
    and decoded_link !~ '[[:cntrl:]]'
    and decoded_link !~ U&'[\061C\200E\200F\2028-\202E\2066-\2069]';
end;
$function$

CREATE OR REPLACE FUNCTION private.is_valid_home_collection_banner(candidate_title text, candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  field text;
  value text;
begin
  if candidate_title is null
    or candidate_title <> pg_catalog.btrim(candidate_title)
    or pg_catalog.char_length(candidate_title) not between 1 and 40
    or candidate_title ~ '[[:cntrl:]]'
  then
    return false;
  end if;
  if candidate is null then return true; end if;
  if pg_catalog.jsonb_typeof(candidate) <> 'object' then return false; end if;
  if exists (
    select 1 from pg_catalog.jsonb_object_keys(candidate) as keys(key)
    where key not in ('subtitle', 'mobile_image_path', 'image_alt', 'image_dim', 'text_color')
  ) then
    return false;
  end if;
  foreach field in array array['subtitle', 'image_alt'] loop
    if not candidate ? field then continue; end if;
    if pg_catalog.jsonb_typeof(candidate -> field) <> 'string' then return false; end if;
    value := candidate ->> field;
    if value <> pg_catalog.btrim(value)
      or pg_catalog.char_length(value) not between 1 and (case field when 'subtitle' then 80 else 100 end)
      or value ~ '[[:cntrl:]]'
    then
      return false;
    end if;
  end loop;
  if candidate ? 'mobile_image_path' and (
    pg_catalog.jsonb_typeof(candidate -> 'mobile_image_path') <> 'string'
    or candidate ->> 'mobile_image_path'
      !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  ) then
    return false;
  end if;
  return private.is_valid_home_hero_style(candidate);
end $function$

CREATE OR REPLACE FUNCTION private.is_valid_home_hero_alt(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare field text; value text;
begin
  if candidate is null then return true;end if;
  if jsonb_typeof(candidate)<>'object' then return false;end if;
  if not (candidate ?| array['alt_enabled','alt_title','alt_content']) then return true;end if;
  if jsonb_typeof(candidate->'alt_enabled') is distinct from 'boolean' then return false;end if;
  if candidate->'alt_enabled'='false'::jsonb then return not (candidate ?| array['alt_title','alt_content']);end if;
  foreach field in array array['alt_title','alt_content'] loop
    if not candidate ? field then continue;end if;
    if jsonb_typeof(candidate->field) is distinct from 'string' then return false;end if;
    value:=candidate->>field;
    if value<>btrim(value) or char_length(value)<1 or char_length(value)>(case field when 'alt_title' then 40 else 150 end)
      or (case field when 'alt_title' then value else replace(value,chr(10),'') end) ~ '[[:cntrl:]]'
    then return false;end if;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.is_valid_home_hero_style(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
 if candidate is null then return true;end if;
 if jsonb_typeof(candidate)<>'object' then return false;end if;
 if candidate ? 'image_dim' and (jsonb_typeof(candidate->'image_dim') is distinct from 'string'
   or candidate->>'image_dim' not in ('none','white','black')) then return false;end if;
 if candidate ? 'text_color' and (jsonb_typeof(candidate->'text_color') is distinct from 'string'
   or candidate->>'text_color' not in ('white','black')) then return false;end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION private.is_valid_home_layout_blocks(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare entry jsonb; block_key text; seen text[] := '{}';
begin
  if candidate is null then return true; end if;
  if pg_catalog.jsonb_typeof(candidate) <> 'array'
    or pg_catalog.jsonb_array_length(candidate) not between 5 and 1000 then return false; end if;
  for entry in select value from pg_catalog.jsonb_array_elements(candidate)
  loop
    if pg_catalog.jsonb_typeof(entry) <> 'object'
      or pg_catalog.jsonb_typeof(entry->'key') is distinct from 'string'
      or pg_catalog.jsonb_typeof(entry->'enabled') is distinct from 'boolean'
      or exists(select 1 from pg_catalog.jsonb_object_keys(entry) field where field not in ('key','enabled'))
    then return false; end if;
    block_key := entry->>'key';
    if block_key = any(seen) then return false; end if;
    if block_key not in ('hero','editor_picks','category_best','popular','benefits','stories','new_arrivals','strip_banner')
      and block_key !~ '^(band|sales|reviews|mosaic|products):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then return false; end if;
    seen := pg_catalog.array_append(seen, block_key);
  end loop;
  return array['hero','editor_picks','category_best','popular','benefits']::text[] <@ seen;
end;
$function$

CREATE OR REPLACE FUNCTION private.is_valid_home_mosaic(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare slot jsonb; field text; caption text;
begin
  if jsonb_typeof(candidate) is distinct from 'object' or not(candidate ?& array['mosaic_title','mosaic_subtitle','slots'])
    or (select count(*) from jsonb_object_keys(candidate))<>3 then return false; end if;
  foreach field in array array['mosaic_title','mosaic_subtitle'] loop
    if jsonb_typeof(candidate->field) is distinct from 'string' then return false; end if;
    caption:=candidate->>field;
    if caption<>btrim(caption,E' \t\n\r\f\v'||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') or caption ~ '[[:cntrl:]]'
      or char_length(caption)>(case field when 'mosaic_title' then 10 else 20 end) then return false; end if;
  end loop;
  if jsonb_typeof(candidate->'slots') is distinct from 'array' or jsonb_array_length(candidate->'slots')<>8 then return false; end if;
  for slot in select value from jsonb_array_elements(candidate->'slots') loop
    if jsonb_typeof(slot) is distinct from 'object' or not(slot ?& array['good_id','image_path'])
      or (select count(*) from jsonb_object_keys(slot))<>2 then return false; end if;
    if slot->'good_id'<>'null'::jsonb and (jsonb_typeof(slot->'good_id')<>'string' or slot->>'good_id' !~ '^[A-Za-z0-9_-]{1,64}$') then return false; end if;
    if slot->'image_path'<>'null'::jsonb and (jsonb_typeof(slot->'image_path')<>'string'
      or slot->>'image_path' !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$') then return false; end if;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.is_valid_home_notice_page_types(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  -- plpgsql keeps the evaluation order explicit: the array functions below
  -- would raise on a scalar instead of rejecting it.
  if candidate is null or pg_catalog.jsonb_typeof(candidate) <> 'array' then return false; end if;
  if pg_catalog.jsonb_array_length(candidate) not between 1 and 5 then return false; end if;
  if exists (
    select 1 from pg_catalog.jsonb_array_elements(candidate) as entries(entry)
    where pg_catalog.jsonb_typeof(entry) <> 'string'
      or entry #>> '{}' not in ('home', 'collection', 'product', 'content', 'other')
  ) then
    return false;
  end if;
  return (
    select pg_catalog.count(distinct entry)
    from pg_catalog.jsonb_array_elements_text(candidate) as entries(entry)
  ) = pg_catalog.jsonb_array_length(candidate);
end $function$

CREATE OR REPLACE FUNCTION private.is_valid_home_notice_payload(candidate_kind text, candidate jsonb, candidate_link text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  label text;
begin
  if candidate_kind is null or candidate_kind not in ('notice_bar', 'notice_strip') then return true; end if;
  if candidate is not null and pg_catalog.jsonb_typeof(candidate) <> 'object' then return false; end if;

  if candidate_kind = 'notice_strip' then
    if candidate is null then return true; end if;
    if exists (
      select 1 from pg_catalog.jsonb_object_keys(candidate) as keys(key)
      where key not in ('mobile_image_path', 'page_types')
    ) then
      return false;
    end if;
    return not (candidate ? 'page_types')
      or private.is_valid_home_notice_page_types(candidate -> 'page_types');
  end if;

  if candidate is null or not (candidate ? 'page_types') then return false; end if;
  if exists (
    select 1 from pg_catalog.jsonb_object_keys(candidate) as keys(key)
    where key not in ('cta_label', 'page_types')
  ) then
    return false;
  end if;
  if not private.is_valid_home_notice_page_types(candidate -> 'page_types') then return false; end if;
  -- A button needs a destination and a destination needs a visible button.
  if candidate_link is null then return not (candidate ? 'cta_label'); end if;
  if not (candidate ? 'cta_label') or pg_catalog.jsonb_typeof(candidate -> 'cta_label') <> 'string' then
    return false;
  end if;
  label := candidate ->> 'cta_label';
  return label = pg_catalog.btrim(label)
    and pg_catalog.char_length(label) between 1 and 12
    and label !~ '[[:cntrl:]]';
end $function$

CREATE OR REPLACE FUNCTION private.is_valid_home_product_collection(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare item jsonb;seen text[]:='{}';count_value numeric;
begin
 if candidate is null or jsonb_typeof(candidate)<>'object' then return false;end if;
 if not candidate ?& array['layout','image_shape','item_count','good_ids']
  or candidate-array['layout','image_shape','item_count','good_ids']<>'{}'::jsonb
  or jsonb_typeof(candidate->'layout') is distinct from 'string'
  or candidate->>'layout' not in ('list','full_image','grid')
  or jsonb_typeof(candidate->'image_shape') is distinct from 'string'
  or candidate->>'image_shape' not in ('square','portrait','landscape')
  or jsonb_typeof(candidate->'item_count') is distinct from 'number'
  or jsonb_typeof(candidate->'good_ids') is distinct from 'array' then return false;end if;
 count_value:=(candidate->>'item_count')::numeric;
 if count_value<>trunc(count_value)
  or (candidate->>'layout'='list' and count_value not between 3 and 12)
  or (candidate->>'layout'='full_image' and count_value not between 1 and 8)
  or (candidate->>'layout'='grid' and (count_value not in (5,10) or candidate->>'image_shape'<>'square'))
  or jsonb_array_length(candidate->'good_ids')>100 then return false;end if;
 for item in select value from jsonb_array_elements(candidate->'good_ids') loop
  if jsonb_typeof(item)<>'string' or item#>>'{}'!~'^[A-Za-z0-9_-]{1,64}$' or (item#>>'{}')=any(seen) then return false;end if;
  seen:=array_append(seen,item#>>'{}');
 end loop;
 return true;
end $function$

CREATE OR REPLACE FUNCTION private.is_valid_home_ranked_curation(candidate_kind text, candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if candidate_kind not in ('sales_best','review_best') then return true; end if;
  if candidate is null or jsonb_typeof(candidate)<>'object' then return false; end if;
  if candidate_kind='sales_best' then
    return coalesce(candidate->>'exposure_mode' in ('single','all')
      and candidate->>'period' in ('realtime','daily','weekly','monthly')
      and not exists(select 1 from jsonb_object_keys(candidate) k where k not in ('exposure_mode','period')),false);
  end if;
  if candidate->>'selection_mode'='rating' then
    return candidate='{"selection_mode":"rating"}'::jsonb;
  end if;
  if candidate->>'selection_mode' is distinct from 'manual'
    or jsonb_typeof(candidate->'good_ids') is distinct from 'array'
    or exists(select 1 from jsonb_object_keys(candidate) k where k not in ('selection_mode','good_ids'))
  then return false; end if;
  if jsonb_array_length(candidate->'good_ids')>20 then return false; end if;
  return not exists(select 1 from jsonb_array_elements(candidate->'good_ids') e
    where jsonb_typeof(e)<>'string' or e#>>'{}' !~ '^[A-Za-z0-9_-]{1,64}$')
    and jsonb_array_length(candidate->'good_ids')=(select count(distinct value) from jsonb_array_elements_text(candidate->'good_ids'));
end $function$

CREATE OR REPLACE FUNCTION private.is_valid_home_search_terms(candidate_title text, candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if candidate_title is null
    or candidate_title <> pg_catalog.btrim(candidate_title)
    or pg_catalog.char_length(candidate_title) not between 1 and 40
    or candidate_title ~ '[[:cntrl:]]'
  then
    return false;
  end if;
  -- plpgsql keeps the evaluation order explicit: the array functions below
  -- would raise on a scalar instead of rejecting it.
  if candidate is null or pg_catalog.jsonb_typeof(candidate) <> 'object' then return false; end if;
  if exists (
    select 1 from pg_catalog.jsonb_object_keys(candidate) as keys(key) where key <> 'terms'
  ) then
    return false;
  end if;
  if pg_catalog.jsonb_typeof(candidate -> 'terms') is distinct from 'array' then return false; end if;
  if pg_catalog.jsonb_array_length(candidate -> 'terms') not between 1 and 10 then return false; end if;
  if exists (
    select 1 from pg_catalog.jsonb_array_elements(candidate -> 'terms') as entries(entry)
    where pg_catalog.jsonb_typeof(entry) <> 'string'
      or entry #>> '{}' <> pg_catalog.btrim(entry #>> '{}')
      or pg_catalog.char_length(entry #>> '{}') not between 1 and 20
      or entry #>> '{}' ~ '[[:cntrl:]]'
      or entry #>> '{}' ~ '[[:space:]][[:space:]]'
  ) then
    return false;
  end if;
  return (
    select pg_catalog.count(distinct pg_catalog.lower(entry))
    from pg_catalog.jsonb_array_elements_text(candidate -> 'terms') as entries(entry)
  ) = pg_catalog.jsonb_array_length(candidate -> 'terms');
end $function$

CREATE OR REPLACE FUNCTION private.issue_coupon_code(p_code text, p_user_id uuid, p_source text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare coupon public.coupons; held_id uuid; issued timestamptz; reason text;
begin
  if p_source is null or p_source not in ('code_entry','admin_grant','kakao_channel') then raise invalid_parameter_value using message='invalid_coupon_issue_source';end if;
  perform private.assert_active_user(p_user_id);
  if private.is_account_write_fenced(p_user_id) then raise insufficient_privilege using message='account_write_fenced';end if;
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
  select * into coupon from public.coupons where code=upper(btrim(coalesce(p_code,''))) for update;
  if not found or coupon.status<>'active' then raise check_violation using message='coupon_not_found';end if;
  if p_source='kakao_channel' and coupon.issuance_mode<>'targeted' then raise check_violation using message='coupon_kakao_channel_requires_targeted';end if;
  select id into held_id from public.user_coupons where user_id=p_user_id and coupon_code=coupon.code
    order by (status='active') desc,issued_at desc,id limit 1;
  -- An existing held coupon survives the end of the issuance period. Applying it
  -- still rechecks its own expiry, status, recipient and eligible goods.
  if held_id is not null then return held_id;end if;
  if p_source='code_entry' and coupon.issuance_mode='targeted' then raise check_violation using message='coupon_designated_recipient_required';end if;
  issued:=clock_timestamp();
  if issued<coalesce(coupon.issue_starts_at,coupon.starts_at) then raise check_violation using message=case when coupon.issue_starts_at is null then 'coupon_not_started' else 'coupon_issue_not_started' end;end if;
  if (case when coupon.issue_starts_at is null then coupon.ends_at else coupon.issue_ends_at end)<=issued then raise check_violation using message=case when coupon.issue_starts_at is null then 'coupon_expired' else 'coupon_issue_ended' end;end if;
  if coupon.ends_at is not null and coupon.ends_at<=issued then raise check_violation using message='coupon_expired';end if;
  reason:=private.coupon_recipient_reason(coupon.recipient_segment,p_user_id);
  if reason is not null then raise check_violation using message=reason;end if;
  if coupon.issue_limit is not null and coupon.issued_count>=coupon.issue_limit then raise check_violation using message='coupon_exhausted';end if;
  insert into public.user_coupons(coupon_code,user_id,issued_source,issued_at,expires_at)
    values(coupon.code,p_user_id,p_source,issued,private.coupon_issue_expiry(coupon,issued)) returning id into held_id;
  update public.coupons set issued_count=issued_count+1 where code=coupon.code;
  return held_id;
end $function$

CREATE OR REPLACE FUNCTION private.issue_store_credit_lot(p_user_id uuid, p_amount bigint, p_expires_at timestamp with time zone, p_source text, p_order_id uuid, p_actor uuid, p_operation uuid, p_reason text, p_root uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare new_id uuid:=extensions.gen_random_uuid(); outstanding bigint:=p_amount; take bigint; debt_lot private.store_credit_lots;
begin
  perform private.lock_store_credit_account(p_user_id);
  if p_amount<=0 or p_expires_at is null then raise invalid_parameter_value using message='invalid_store_credit_grant'; end if;
  if p_root is not null and not exists(select 1 from private.store_credit_lots where id=p_root and root_lot_id=id and user_id=p_user_id and revoked_at is null)
    then raise check_violation using message='store_credit_source_mismatch'; end if;
  insert into private.store_credit_lots(id,user_id,root_lot_id,source_order_id,source_kind,issued_amount,available_amount,expires_at)
    values(new_id,p_user_id,coalesce(p_root,new_id),p_order_id,p_source,p_amount,p_amount,p_expires_at);
  insert into public.store_credit_ledger(user_id,kind,amount,available_delta,order_id,lot_id,actor_id,operation_id,reason,expires_at)
    values(p_user_id,case p_source when 'admin' then 'adjustment_credit' when 'restoration' then 'restore' else 'grant' end,p_amount,p_amount,p_order_id,new_id,p_actor,p_operation,p_reason,p_expires_at);
  for debt_lot in select * from private.store_credit_lots where user_id=p_user_id and debt_amount>0 order by created_at,id for update loop
    take:=least(outstanding,debt_lot.debt_amount);
    update private.store_credit_lots set debt_amount=debt_amount-take where id=debt_lot.id;
    update private.store_credit_lots set available_amount=available_amount-take,offset_amount=offset_amount+take where id=new_id;
    insert into public.store_credit_ledger(user_id,kind,amount,available_delta,debt_delta,order_id,lot_id,actor_id,operation_id)
      values(p_user_id,'debt_offset',-take,-take,-take,p_order_id,debt_lot.id,p_actor,p_operation);
    outstanding:=outstanding-take;
    exit when outstanding=0;
  end loop;
  return new_id;
end $function$

CREATE OR REPLACE FUNCTION private.keep_marketing_consent_shape()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.consents->'marketing' is distinct from old.consents->'marketing'
  and jsonb_typeof(new.consents->'marketing') is distinct from 'boolean' then
  new.consents:=jsonb_set(coalesce(new.consents,'{}'::jsonb),'{marketing}',coalesce(old.consents->'marketing','false'::jsonb),true);
 end if;
 if new.suspended_at is not null and new.consents->'marketing' = 'true'::jsonb
  and old.consents->'marketing' is distinct from 'true'::jsonb then
  new.consents:=jsonb_set(coalesce(new.consents,'{}'::jsonb),'{marketing}',coalesce(old.consents->'marketing','false'::jsonb),true);
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.lock_account_action_subject(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_user_id is null then
    raise not_null_violation using message = 'account_action_subject_required';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('account-action:' || p_user_id::text, 0)
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.lock_bank_transfer_refund_identity(p_order uuid, p_claim uuid, p_actor uuid, p_session uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payer uuid;recipient uuid;
begin
 perform private.require_bank_transfer_refund_identity(p_actor,p_session);
 select o.user_id,g.recipient_id into payer,recipient from public.orders o
  join public.order_cancellation_requests c on c.order_id=o.id and c.id=p_claim
  left join private.gift_intents g on g.order_id=o.id where o.id=p_order;
 if payer is null then raise sqlstate 'PT404' using message='claim_not_found';end if;
 -- Include the payer/recipient account fence before any order lock, in the same
 -- sorted order used by gift requests and account-deletion admission.
 perform private.lock_operator_subjects(array[p_actor,payer,recipient]);
 perform private.require_operator_capability('sales.manage',true);
 perform private.lock_claim_refund_account_session(p_actor,p_session);
 perform private.require_bank_transfer_refund_identity(p_actor,p_session);
end $function$

CREATE OR REPLACE FUNCTION private.lock_coupon_target_ips()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  previous_ids text[] := '{}';
  added_ids text[];
  locked_count integer;
begin
  if tg_op = 'UPDATE' then
    previous_ids := coalesce(old.target_ip_ids, '{}');
  end if;
  select coalesce(pg_catalog.array_agg(distinct target.id order by target.id), '{}')
    into added_ids
  from pg_catalog.unnest(coalesce(new.target_ip_ids, '{}')) as target(id)
  where not target.id = any(previous_ids);
  if pg_catalog.cardinality(added_ids) = 0 then
    return new;
  end if;

  -- FOR KEY SHARE in ID order: an IP deletion (FOR UPDATE) either waits for this coupon to commit
  -- and then counts it as a reference, or commits first so that this write no longer finds the IP.
  select pg_catalog.count(*) into locked_count
  from (
    select ip.id
    from public.ips as ip
    where ip.id = any(added_ids)
    order by ip.id
    for key share of ip
  ) as kept;
  if locked_count <> pg_catalog.cardinality(added_ids) then
    raise check_violation using message = 'coupon_target_ip_unavailable';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.lock_goods_transaction_actor(p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if p_actor is null then raise invalid_parameter_value using message='invalid_transaction_actor';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 perform private.lock_account_action_subject(p_actor);
 perform 1 from public.profiles where id=p_actor for share;
end $function$

CREATE OR REPLACE FUNCTION private.lock_goods_transaction_catalog(p_actor uuid, p_selection jsonb, p_user_coupon_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 -- All mutable catalog parents precede all variants and supply policies.
 perform 1 from public.goods g where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection)) order by g.id for update;
 perform 1 from public.goods_variants v where v.id in(select (value->>'variantId')::uuid from jsonb_array_elements(p_selection)) order by v.good_id,v.id for update;
 perform 1 from public.ips ip where ip.id in(select g.ip_id from public.goods g where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by ip.id for share;
 perform 1 from private.goods_preorder_policies p where p.id in(select v.preorder_policy_id from public.goods_variants v
  where v.id in(select (value->>'variantId')::uuid from jsonb_array_elements(p_selection))) order by p.id for update;
 perform 1 from public.fulfillment_origins o where o.id in(select g.origin_id from public.goods g
  where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by o.id for share;
 perform 1 from public.shipping_carriers c where c.code in(select o.default_carrier from public.fulfillment_origins o join public.goods g on g.origin_id=o.id
  where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by c.code for share;
 perform 1 from private.shipping_charge_group_assignments a where a.owner_good_id in(select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection)) order by a.owner_good_id for share;
 perform 1 from private.shipping_charge_groups g where g.id in(select a.group_id from private.shipping_charge_group_assignments a where a.owner_good_id in(select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by g.id for share;
 if p_user_coupon_id is not null then
  perform 1 from public.user_coupons h where h.id=p_user_coupon_id for update;
  perform 1 from public.coupons c join public.user_coupons h on h.coupon_code=c.code where h.id=p_user_coupon_id for share of c;
 end if;
 perform 1 from private.store_credit_policy where singleton for share;
 perform private.lock_store_credit_account(p_actor);
 perform 1 from private.store_credit_lots where user_id=p_actor order by expires_at,id for update;
end $function$

CREATE OR REPLACE FUNCTION private.lock_goods_transaction_combined_catalog(p_actor uuid, p_selection jsonb, p_user_coupon_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 -- All mutable catalog parents precede all variants and supply policies.
 perform 1 from public.goods g where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection)) order by g.id for update;
 perform 1 from public.goods_variants v where v.id in(select (value->>'variantId')::uuid from jsonb_array_elements(p_selection)) order by v.good_id,v.id for update;
 perform 1 from public.ips ip where ip.id in(select g.ip_id from public.goods g where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by ip.id for share;
 perform 1 from private.goods_preorder_policies p where p.id in(select v.preorder_policy_id from public.goods_variants v
  where v.id in(select (value->>'variantId')::uuid from jsonb_array_elements(p_selection))) order by p.id for update;
 perform 1 from public.fulfillment_origins o where o.id in(select g.origin_id from public.goods g
  where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by o.id for share;
 perform 1 from public.shipping_carriers c where c.code in(select o.default_carrier from public.fulfillment_origins o join public.goods g on g.origin_id=o.id
  where g.id in(select value->>'goodId' from jsonb_array_elements(p_selection) union select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by c.code for share;
 perform 1 from private.shipping_charge_group_assignments a where a.owner_good_id in(select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection)) order by a.owner_good_id for share;
 perform 1 from private.shipping_charge_groups g where g.id in(select a.group_id from private.shipping_charge_group_assignments a where a.owner_good_id in(select private.goods_aggregation_owner(value->>'goodId') from jsonb_array_elements(p_selection))) order by g.id for share;
 if cardinality(p_user_coupon_ids)>0 then
  perform 1 from public.user_coupons h where h.id=any(p_user_coupon_ids) order by h.id for update;
  perform 1 from public.coupons c join public.user_coupons h on h.coupon_code=c.code where h.id=any(p_user_coupon_ids) order by c.code for share of c;
 end if;
 perform 1 from private.coupon_combination_policy where singleton for share;
 perform 1 from private.store_credit_policy where singleton for share;
 perform private.lock_store_credit_account(p_actor);
 perform 1 from private.store_credit_lots where user_id=p_actor order by expires_at,id for update;
end $function$

CREATE OR REPLACE FUNCTION private.lock_goods_transaction_source(p_actor uuid, p_source jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare source_id uuid;begin
 if p_actor is null or not private.transaction_json_keys(p_source,array['kind','id','revision'])
  or coalesce(p_source->>'kind','') not in ('cart','gift','subscription','direct') or jsonb_typeof(p_source->'id') is distinct from 'string'
  or p_source->>'id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or jsonb_typeof(p_source->'revision') is distinct from 'string' or char_length(p_source->>'revision') not between 1 and 256
  or p_source->>'revision'<>btrim(p_source->>'revision') or p_source->>'revision'~'[[:cntrl:]]' then
  raise invalid_parameter_value using message='invalid_transaction_source';end if;
 source_id:=(p_source->>'id')::uuid;
 if p_source->>'kind' in ('cart','direct') and source_id<>p_actor then raise insufficient_privilege using message='transaction_source_forbidden';end if;
 perform private.lock_goods_transaction_actor(p_actor);
 if p_source->>'kind'='cart' then perform pg_advisory_xact_lock(hashtextextended('cart:'||p_actor::text,0));
 else perform pg_advisory_xact_lock(hashtextextended('goods-transaction-source:'||(p_source->>'kind')||':'||source_id::text,0));end if;
end $function$

CREATE OR REPLACE FUNCTION private.lock_operator_invitation_dispatch(p_intent_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare invitation private.operator_invitations;
begin
  if not exists(select 1 from private.email_intents where id=p_intent_id and source='operator_invitation') then return true; end if;
  perform 1 from private.operator_access_state where id for update;
  select * into invitation from private.operator_invitations where email_intent_id=p_intent_id;
  if not found then return false; end if;
  perform private.lock_operator_subjects(array[invitation.created_by,invitation.dispatch_actor_id]);
  select * into invitation from private.operator_invitations where email_intent_id=p_intent_id for update;
  return invitation.status='pending' and invitation.expires_at>clock_timestamp() and invitation.dispatch_claim_id is not null
    and private.has_operator_capability(invitation.created_by,'operators.manage',true)
    and private.has_operator_capability(invitation.dispatch_actor_id,'operators.manage',true);
end $function$

CREATE OR REPLACE FUNCTION private.lock_operator_subjects(p_profile_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare subject uuid;
begin
  for subject in select distinct id from unnest(p_profile_ids) as ids(id) where id is not null order by id loop
    perform private.lock_account_action_subject(subject);
  end loop;
  perform 1 from public.profiles where id=any(p_profile_ids) order by id for share;
  perform 1 from private.operator_memberships where profile_id=any(p_profile_ids) order by profile_id for share;
end $function$

CREATE OR REPLACE FUNCTION private.lock_order_delay_notice_target(target_order uuid, target_shipments uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform 1 from public.orders where id=target_order for update;
 perform 1 from public.profiles where id=(select user_id from public.orders where id=target_order) for share;
 perform 1 from public.order_shipments where order_id=target_order and id=any(target_shipments) order by id for update;
 perform 1 from public.order_dispatch_delays where order_id=target_order for share;
end $function$

CREATE OR REPLACE FUNCTION private.lock_parcel_shipment(p_shipment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare method text;
begin
  perform purchase.id from public.orders purchase join public.order_shipments shipment on shipment.order_id=purchase.id
    where shipment.id=p_shipment_id for update of purchase;
  if not found then raise no_data_found using message='shipment_not_found'; end if;
  select delivery_method into method from public.order_shipments where id=p_shipment_id for update;
  if method<>'parcel' then raise check_violation using message='delivery_method_evidence_required'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.lock_shipment_pack_scope(p_ids uuid[])
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ids uuid[];begin
 if cardinality(p_ids) is null or cardinality(p_ids) not between 1 and 1000 or array_position(p_ids,null) is not null then raise invalid_parameter_value;end if;
 ids:=private.shipment_pack_scope(p_ids);
 -- Resolve before any order lock. If membership changed while waiting, abort;
 -- never append a new, lower order key after acquiring part of the lock set.
 perform o.id from public.orders o where exists(select 1 from public.order_shipments s where s.order_id=o.id and s.id=any(ids)) order by o.id for update;
 if ids is distinct from private.shipment_pack_scope(p_ids) then raise sqlstate 'PT409' using message='shipment_pack_changed';end if;
 perform id from public.order_shipments where id=any(ids) order by id for update;
 if (select count(*) from public.order_shipments where id=any(ids))<>cardinality(ids) then raise no_data_found using message='shipment_not_found';end if;
 return ids;
end $function$

CREATE OR REPLACE FUNCTION private.lock_tracking_batch(p_rows jsonb, p_origin uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare origin_carrier text; entries jsonb := '[]'; row_value jsonb; carrier_value text; row_shipment uuid; lock_key bigint; conflicts text[];
begin
  if jsonb_typeof(p_rows) is distinct from 'array' then return '{}'; end if;
  if p_origin is not null then select default_carrier into origin_carrier from public.fulfillment_origins where id = p_origin; end if;
  for row_value in select value from jsonb_array_elements(p_rows) loop
    if jsonb_typeof(row_value) is distinct from 'object' then continue; end if;
    carrier_value := coalesce(origin_carrier, nullif(btrim(row_value->>'carrier'), ''));
    row_shipment := private.tracking_batch_shipment(row_value, p_origin);
    entries := entries || jsonb_build_array(jsonb_build_object('shipmentId', row_shipment,
      'carrier', carrier_value, 'trackingNumber', private.normalize_tracking_number(row_value->>'trackingNumber')));
    if jsonb_typeof(row_value->'extraTrackingNumbers') = 'array' then
      entries := entries || coalesce((select jsonb_agg(jsonb_build_object('shipmentId', row_shipment, 'carrier', carrier_value,
        'trackingNumber', private.normalize_tracking_number(extra #>> '{}')))
        from jsonb_array_elements(row_value->'extraTrackingNumbers') extra where jsonb_typeof(extra) = 'string'), '[]');
    end if;
  end loop;
  -- 여러 번호를 잡는 모든 경로(일괄·회신 반입, 맞바꾸기)는 잠금 열쇠 값 순서로 잡는다 — 번호가 엇갈린 두 요청이 교착하지 않는다.
  for lock_key in select distinct private.tracking_number_lock_key(value->>'carrier', value->>'trackingNumber') from jsonb_array_elements(entries)
    where value->>'carrier' is not null and value->>'trackingNumber' is not null order by 1 loop
    perform pg_advisory_xact_lock(lock_key);
  end loop;
  with batch_rows as (
    select distinct (value->>'shipmentId')::uuid sid, value->>'carrier' carrier, value->>'trackingNumber' tracking
    from jsonb_array_elements(entries)
    where value->>'shipmentId' is not null and value->>'carrier' is not null and value->>'trackingNumber' is not null
  )
  select coalesce(array_agg(distinct a.carrier || ':' || a.tracking), '{}') into conflicts
  from batch_rows a join batch_rows b on a.carrier = b.carrier and a.tracking = b.tracking and a.sid < b.sid
  where not private.tracking_shipments_related(a.sid, b.sid);
  return conflicts;
end $function$

CREATE OR REPLACE FUNCTION private.loyalty_criteria_valid(tiers jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare entry jsonb; i integer:=0; disabled boolean:=false; last_amount bigint:=0; last_count bigint:=0;
  amount numeric; item_count numeric; names text[]:=array['silver','gold','platinum'];
begin
  if jsonb_typeof(tiers) is distinct from 'array' then return false; end if;
  if jsonb_array_length(tiers)<>3 then return false; end if;
  for entry in select value from jsonb_array_elements(tiers) loop
    i:=i+1;
    if jsonb_typeof(entry) is distinct from 'object' then return false; end if;
    if not entry ?& array['grade','enabled','amount','itemCount'] or (select count(*) from jsonb_object_keys(entry))<>4
      or entry->>'grade' is distinct from names[i] or jsonb_typeof(entry->'enabled') is distinct from 'boolean'
      or jsonb_typeof(entry->'amount') not in ('number','null') or jsonb_typeof(entry->'itemCount') not in ('number','null') then return false; end if;
    amount:=(entry->>'amount')::numeric; item_count:=(entry->>'itemCount')::numeric;
    if (amount is not null and (amount<>trunc(amount) or amount<1 or amount>1000000000000))
      or (item_count is not null and (item_count<>trunc(item_count) or item_count<1 or item_count>1000000)) then return false; end if;
    if not (entry->>'enabled')::boolean then disabled:=true; continue; end if;
    if disabled or (amount is null and item_count is null)
      or (amount is not null and amount<=last_amount) or (item_count is not null and item_count<=last_count) then return false; end if;
    if amount is not null then last_amount:=amount::bigint; end if;
    if item_count is not null then last_count:=item_count::bigint; end if;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.maintain_system_job_records()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  insert into private.system_pg_cron_jobs(jobname, first_seen_at)
  select j.jobname, clock_timestamp() from cron.job j where j.jobname is not null
  on conflict (jobname) do nothing;
  delete from private.system_pg_cron_jobs s where not exists(select 1 from cron.job j where j.jobname = s.jobname);
  delete from private.system_job_failures where occurred_at < now() - interval '30 days';
  delete from private.system_job_status where updated_at < now() - interval '30 days';
  delete from private.payment_reconciliation_auto_checks m using public.payment_attempts a
  where a.id = m.attempt_id and not private.payment_attempt_unresolved(a.state, a.claim_expires_at, clock_timestamp());
end $function$

CREATE OR REPLACE FUNCTION private.make_room_for_goods_draft(p_owner_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous public.admin_goods_drafts;
begin
  if p_owner_id is distinct from auth.uid() or not public.is_staff() then raise insufficient_privilege using message='forbidden'; end if;
  -- The public callers already hold the per-owner advisory lock.
  if (select count(*) from public.admin_goods_drafts where owner_id=p_owner_id and archived_at is null)<40 then return; end if;
  select * into previous from public.admin_goods_drafts where owner_id=p_owner_id and archived_at is null
    order by updated_at,id limit 1 for update;
  if not found then raise exception 'goods_draft_changed' using errcode='PT409'; end if;
  update public.admin_goods_drafts set archived_at=clock_timestamp(),updated_at=clock_timestamp(),revision=revision+1 where id=previous.id;
  insert into public.audit_log(actor_id,action,target,diff) values(p_owner_id,'admin.goods.draft.archived','goods_draft:'||previous.id::text,
    jsonb_build_object('revision',previous.revision+1,'archived',true,'reason','recent_40_limit'));
end $function$

CREATE OR REPLACE FUNCTION private.marketing_schedule_times(p_schedule jsonb, p_at timestamp with time zone)
 RETURNS timestamp with time zone[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare kind text; start_date date; end_date date; local_time time; at_value timestamptz; weekday integer; times timestamptz[];
begin
 if jsonb_typeof(p_schedule) is distinct from 'object' or jsonb_typeof(p_schedule->'kind') is distinct from 'string' then raise invalid_parameter_value using message='invalid_marketing_schedule';end if;
 kind:=p_schedule->>'kind';
 if kind='immediate' then
  if p_schedule<>'{"kind":"immediate"}' then raise invalid_parameter_value using message='invalid_marketing_schedule';end if;
  if (p_at at time zone 'Asia/Seoul')::time<time '08:00' or (p_at at time zone 'Asia/Seoul')::time>=time '20:00' then raise check_violation using message='marketing_outside_window';end if;
  return array[p_at];
 elsif kind='once' then
  if jsonb_typeof(p_schedule->'at') is distinct from 'string' or exists(select 1 from jsonb_object_keys(p_schedule) key where key<>all(array['kind','at'])) then raise invalid_parameter_value using message='invalid_marketing_schedule';end if;
  begin at_value:=(p_schedule->>'at')::timestamptz;exception when others then raise invalid_parameter_value using message='invalid_marketing_schedule';end;
  times:=array[at_value];
 elsif kind='weekly' then
  if not(p_schedule ?& array['kind','startDate','endDate','weekday','time']) or exists(select 1 from jsonb_object_keys(p_schedule) key where key<>all(array['kind','startDate','endDate','weekday','time']))
   or jsonb_typeof(p_schedule->'startDate') is distinct from 'string' or p_schedule->>'startDate' !~ '^\d{4}-\d{2}-\d{2}$'
   or jsonb_typeof(p_schedule->'endDate') is distinct from 'string' or p_schedule->>'endDate' !~ '^\d{4}-\d{2}-\d{2}$'
   or jsonb_typeof(p_schedule->'time') is distinct from 'string' or p_schedule->>'time' !~ '^(0[89]|1[0-9]):[0-5][0-9]$'
   or jsonb_typeof(p_schedule->'weekday') is distinct from 'number' or p_schedule->>'weekday' !~ '^[0-6]$' then raise invalid_parameter_value using message='invalid_marketing_schedule';end if;
  begin start_date:=(p_schedule->>'startDate')::date;end_date:=(p_schedule->>'endDate')::date;local_time:=(p_schedule->>'time')::time;
  exception when others then raise invalid_parameter_value using message='invalid_marketing_schedule';end;
  weekday:=(p_schedule->>'weekday')::integer;
  if end_date<start_date or end_date-start_date>365 then raise invalid_parameter_value using message='invalid_marketing_schedule';end if;
  select array_agg((day::date+local_time) at time zone 'Asia/Seoul' order by day) into times from generate_series(start_date::timestamp,end_date::timestamp,interval '1 day')day where extract(dow from day)=weekday;
 else raise invalid_parameter_value using message='invalid_marketing_schedule';end if;
 if coalesce(cardinality(times),0)=0 or exists(select 1 from unnest(times) t where t is null or not isfinite(t) or t<=p_at or t>p_at+interval '366 days'
  or (t at time zone 'Asia/Seoul')::time<time '08:00' or (t at time zone 'Asia/Seoul')::time>=time '20:00') then raise invalid_parameter_value using message='invalid_marketing_schedule';end if;
 return times;
end $function$

