      where c.created_at > now_at - interval '1 hour'
        and ((p_column = 'user' and c.user_id = p_value::uuid)
          or (p_column = 'phone' and c.phone_digest = p_value)
          or (p_column = 'ip' and c.ip_digest = p_value));
