CREATE OR REPLACE FUNCTION private.normalize_customer_segment_rule(p_rule jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare target text; scope text; good_ids text[]; grades text[]; age_bands integer[]; months integer; days integer;
 category_id uuid; ip_id text; coupon_code text; item jsonb;
begin
 if p_rule is null or jsonb_typeof(p_rule)<>'object' or p_rule->'version' is distinct from '1'::jsonb
  or jsonb_typeof(p_rule->'target') is distinct from 'string'
  or exists(select 1 from jsonb_object_keys(p_rule) key where key not in
   ('version','target','goodsScope','goodIds','categoryId','months','activityDays','grades','ageBands','ipId','couponCode')) then
  raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 target:=p_rule->>'target';scope:=coalesce(p_rule->>'goodsScope','all');
 if target not in ('first_purchase','cart_unpurchased','wishlist_unpurchased','unused_coupon','ip_notifications','purchased','first_purchase_recent','lapsed_purchase','repeat_purchase','visited','not_visited','product_viewed','video_viewed','similar_product_viewed')
  or scope not in ('all','goods','category')
  or (p_rule ? 'goodsScope' and jsonb_typeof(p_rule->'goodsScope')<>'string')
  or jsonb_typeof(coalesce(p_rule->'goodIds','[]'))<>'array'
  or jsonb_array_length(coalesce(p_rule->'goodIds','[]'))>100
  or jsonb_typeof(coalesce(p_rule->'grades','[]'))<>'array'
  or jsonb_array_length(coalesce(p_rule->'grades','[]'))>4
  or jsonb_typeof(coalesce(p_rule->'ageBands','[]'))<>'array'
  or jsonb_array_length(coalesce(p_rule->'ageBands','[]'))>6 then
  raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 for item in select value from jsonb_array_elements(coalesce(p_rule->'goodIds','[]')) loop
  if jsonb_typeof(item)<>'string' or (item#>>'{}')!~'^[a-z0-9][a-z0-9-]{0,199}$' then
   raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 end loop;
 select coalesce(array_agg(value order by value),'{}'::text[]) into good_ids from jsonb_array_elements_text(coalesce(p_rule->'goodIds','[]'));
 if cardinality(good_ids)<>(select count(distinct value) from unnest(good_ids) value) then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 for item in select value from jsonb_array_elements(coalesce(p_rule->'grades','[]')) loop
  if jsonb_typeof(item)<>'string' or (item#>>'{}') not in ('welcome','silver','gold','platinum') then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 end loop;
 select coalesce(array_agg(value order by value),'{}'::text[]) into grades from jsonb_array_elements_text(coalesce(p_rule->'grades','[]'));
 if cardinality(grades)<>(select count(distinct value) from unnest(grades) value) then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 for item in select value from jsonb_array_elements(coalesce(p_rule->'ageBands','[]')) loop
  if jsonb_typeof(item)<>'number' or item::text not in ('10','20','30','40','50','60') then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 end loop;
 select coalesce(array_agg(value::integer order by value::integer),'{}'::integer[]) into age_bands from jsonb_array_elements_text(coalesce(p_rule->'ageBands','[]'));
 if cardinality(age_bands)<>(select count(distinct value) from unnest(age_bands) value) then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 if coalesce(p_rule->'categoryId','null')<>'null'::jsonb then
  if jsonb_typeof(p_rule->'categoryId')<>'string' or (p_rule->>'categoryId')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
  category_id:=(p_rule->>'categoryId')::uuid;
 end if;
 if (scope='all' and (cardinality(good_ids)>0 or category_id is not null))
  or (scope='goods' and (cardinality(good_ids)=0 or category_id is not null))
  or (scope='category' and (category_id is null or cardinality(good_ids)>0))
  or (target not in ('cart_unpurchased','wishlist_unpurchased','purchased','product_viewed','video_viewed','similar_product_viewed') and scope<>'all') then
  raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 if coalesce(p_rule->'months','null')<>'null'::jsonb then
  if jsonb_typeof(p_rule->'months')<>'number' or (p_rule->'months')::text not in ('1','3','6') then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
  months:=(p_rule->>'months')::integer;
 end if;
 if (target='first_purchase_recent' and months is null) or (target='lapsed_purchase' and coalesce(months,0) not in (3,6))
  or (target='repeat_purchase' and months is not null and months not in (1,3))
  or (target not in ('first_purchase_recent','lapsed_purchase','repeat_purchase','purchased') and months is not null) then
  raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 if coalesce(p_rule->'activityDays','null')<>'null'::jsonb then
  if jsonb_typeof(p_rule->'activityDays')<>'number' or (p_rule->'activityDays')::text not in ('7','30','90')
   or target not in ('cart_unpurchased','wishlist_unpurchased','visited','not_visited','product_viewed','video_viewed','similar_product_viewed') then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
  days:=(p_rule->>'activityDays')::integer;
 end if;
 if coalesce(p_rule->'ipId','null')<>'null'::jsonb then
  if jsonb_typeof(p_rule->'ipId')<>'string' or (p_rule->>'ipId')!~'^[a-z0-9][a-z0-9-]{0,199}$' or target<>'ip_notifications' then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
  ip_id:=p_rule->>'ipId';
 end if;
 if coalesce(p_rule->'couponCode','null')<>'null'::jsonb then
  if jsonb_typeof(p_rule->'couponCode')<>'string' or (p_rule->>'couponCode')!~'^[A-Z0-9][A-Z0-9-]{2,23}$' or target<>'unused_coupon' then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
  coupon_code:=p_rule->>'couponCode';
 end if;
 if target in ('visited','not_visited','product_viewed','video_viewed','similar_product_viewed') then days:=coalesce(days,30);end if;
 if target='similar_product_viewed' and scope<>'goods' then raise invalid_parameter_value using message='invalid_customer_segment_rule';end if;
 return jsonb_build_object('version',1,'target',target,'goodsScope',scope,'goodIds',to_jsonb(good_ids),'categoryId',category_id,
  'months',months,'activityDays',days,'grades',to_jsonb(grades),'ageBands',to_jsonb(age_bands),'ipId',ip_id,'couponCode',coupon_code);
end $function$

CREATE OR REPLACE FUNCTION private.normalize_erp_item_row(p_item jsonb, OUT o_code text, OUT o_name text, OUT o_category text, OUT o_sale_price integer, OUT o_barcode text, OUT o_has_category boolean, OUT o_has_sale_price boolean, OUT o_has_barcode boolean, OUT o_reason text)
 RETURNS record
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_price_text text;
  v_price numeric;
begin
  if p_item is null or pg_catalog.jsonb_typeof(p_item) <> 'object' then
    o_reason := 'invalid_row';
    return;
  end if;

  if p_item -> 'code' is null or pg_catalog.jsonb_typeof(p_item -> 'code') = 'null' then
    o_reason := 'missing_code';
    return;
  end if;
  if pg_catalog.jsonb_typeof(p_item -> 'code') <> 'string' then
    o_reason := 'invalid_code';
    return;
  end if;
  o_code := private.erp_item_text(p_item ->> 'code', false);
  if o_code is null then
    o_reason := 'missing_code';
    return;
  end if;
  if pg_catalog.length(o_code) > 120 or o_code ~ '[\u0001-\u001f\u007f-\u009f]' then
    o_code := null;
    o_reason := 'invalid_code';
    return;
  end if;

  if p_item -> 'name' is null or pg_catalog.jsonb_typeof(p_item -> 'name') = 'null' then
    o_reason := 'missing_name';
    return;
  end if;
  if pg_catalog.jsonb_typeof(p_item -> 'name') <> 'string' then
    o_reason := 'invalid_name';
    return;
  end if;
  o_name := private.erp_item_text(p_item ->> 'name', true);
  if o_name is null then
    o_reason := 'missing_name';
    return;
  end if;
  if pg_catalog.length(o_name) > 200 or o_name ~ '[\u0001-\u001f\u007f-\u009f]' then
    o_name := null;
    o_reason := 'invalid_name';
    return;
  end if;

  o_has_category := p_item ? 'category';
  if o_has_category and pg_catalog.jsonb_typeof(p_item -> 'category') <> 'null' then
    if pg_catalog.jsonb_typeof(p_item -> 'category') <> 'string' then
      o_reason := 'invalid_category';
      return;
    end if;
    o_category := private.erp_item_text(p_item ->> 'category', true);
    if pg_catalog.length(coalesce(o_category, '')) > 200 or o_category ~ '[\u0001-\u001f\u007f-\u009f]' then
      o_category := null;
      o_reason := 'invalid_category';
      return;
    end if;
  end if;

  o_has_sale_price := p_item ? 'sale_price';
  if o_has_sale_price and pg_catalog.jsonb_typeof(p_item -> 'sale_price') <> 'null' then
    if pg_catalog.jsonb_typeof(p_item -> 'sale_price') = 'number' then
      v_price := (p_item ->> 'sale_price')::numeric;
    elsif pg_catalog.jsonb_typeof(p_item -> 'sale_price') = 'string' then
      -- 엑셀 서식 값(12,000원 · ₩12,000)을 허용한다. 서버 액션은 이미 정수로 보낸다.
      v_price_text := pg_catalog.regexp_replace(
        p_item ->> 'sale_price', '[ \t 　,원₩￦\\]', '', 'g');
      if v_price_text = '' then
        v_price := null;
      elsif v_price_text ~ '^[0-9]{1,12}([.]0+)?$' then
        v_price := v_price_text::numeric;
      else
        o_reason := 'invalid_sale_price';
        return;
      end if;
    else
      o_reason := 'invalid_sale_price';
      return;
    end if;
    if v_price is not null then
      if v_price <> pg_catalog.trunc(v_price) or v_price < 0 or v_price > 2147483647 then
        o_reason := 'invalid_sale_price';
        return;
      end if;
      o_sale_price := v_price::integer;
    end if;
  end if;

  o_has_barcode := p_item ? 'barcode';
  if o_has_barcode and pg_catalog.jsonb_typeof(p_item -> 'barcode') <> 'null' then
    if pg_catalog.jsonb_typeof(p_item -> 'barcode') <> 'string' then
      o_reason := 'invalid_barcode';
      return;
    end if;
    o_barcode := private.erp_item_text(p_item ->> 'barcode', false);
    if pg_catalog.length(coalesce(o_barcode, '')) > 120 or o_barcode ~ '[\u0001-\u001f\u007f-\u009f]' then
      o_barcode := null;
      o_reason := 'invalid_barcode';
      return;
    end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.normalize_goods_custom_input_fields(p_fields jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare result jsonb:='[]'; field jsonb; field_id uuid; ids uuid[]:='{}'; names text[]:='{}';
begin
  if jsonb_typeof(p_fields) is distinct from 'array' or jsonb_array_length(p_fields)>5 then
    raise check_violation using message='invalid_goods_custom_input_fields';
  end if;
  for field in select value from jsonb_array_elements(p_fields) loop
    if jsonb_typeof(field)<>'object' or not field ?& array['id','name','active']
      or exists(select 1 from jsonb_object_keys(field) key where key not in ('id','name','active'))
      or jsonb_typeof(field->'id')<>'string' or jsonb_typeof(field->'name')<>'string' or jsonb_typeof(field->'active')<>'boolean'
      or length(field->>'name') not between 1 and 25 or field->>'name'<>btrim(field->>'name') or field->>'name'~'[[:cntrl:]]' then
      raise check_violation using message='invalid_goods_custom_input_fields';
    end if;
    begin field_id:=(field->>'id')::uuid;
    exception when invalid_text_representation then raise check_violation using message='invalid_goods_custom_input_fields'; end;
    if field_id=any(ids) or field->>'name'=any(names) then raise check_violation using message='invalid_goods_custom_input_fields'; end if;
    ids:=array_append(ids,field_id); names:=array_append(names,field->>'name');
    result:=result||jsonb_build_array(jsonb_build_object('id',field_id,'name',field->>'name','active',(field->>'active')::boolean));
  end loop;
  return result;
end $function$

CREATE OR REPLACE FUNCTION private.normalize_goods_kc_models(p_models jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare row jsonb; item jsonb; normalized jsonb; models jsonb:='[]'; field text; value text; ids jsonb; evidence jsonb;
  fields text[]:=array['family','scheme','productCategory','modelName','businessRole','businessName','identifier','publicNote','variantIds','basis','evidence'];
begin
  if p_models is null or jsonb_typeof(p_models)<>'array' or jsonb_array_length(p_models)>50 then
    raise check_violation using message='invalid_goods_kc_models';
  end if;
  for row in select elem from jsonb_array_elements(p_models) elem loop
    if jsonb_typeof(row)<>'object' or not (row ?& fields)
      or exists(select 1 from jsonb_object_keys(row) key where not(key=any(fields))) then
      raise check_violation using message='invalid_goods_kc_models';
    end if;
    normalized:='{}';
    foreach field in array array['family','scheme','productCategory','modelName','businessRole','businessName','identifier','publicNote','basis'] loop
      if jsonb_typeof(row->field)<>'string' then raise check_violation using message='invalid_goods_kc_models'; end if;
      value:=private.goods_kc_trim(row->>field);
      if length(value)>(case field when 'basis' then 2000 when 'publicNote' then 1000 when 'identifier' then 100 else 200 end)
        or (field not in ('basis','publicNote') and value ~ '[[:cntrl:]]')
        or (field in ('basis','publicNote') and replace(replace(replace(value,E'\n',''),E'\r',''),E'\t','') ~ '[[:cntrl:]]') then
        raise check_violation using message='invalid_goods_kc_models';
      end if;
      normalized:=normalized||jsonb_build_object(field,value);
    end loop;
    if normalized->>'family' not in ('','electrical','living','children','other')
      or normalized->>'scheme' not in ('','safety_certification','safety_confirmation','supplier_conformity','safety_standard_compliance','not_applicable')
      or normalized->>'businessRole' not in ('','manufacturer','importer')
      or (normalized->>'scheme'<>'' and (normalized->>'family'=''
        or (normalized->>'family'='other' and normalized->>'scheme'<>'not_applicable')
        or (normalized->>'scheme'='safety_standard_compliance' and normalized->>'family'<>'living'))) then
      raise check_violation using message='invalid_goods_kc_combination';
    end if;
    if jsonb_typeof(row->'variantIds')<>'array' or jsonb_array_length(row->'variantIds')>200 then
      raise check_violation using message='invalid_goods_kc_models';
    end if;
    for item in select elem from jsonb_array_elements(row->'variantIds') elem loop
      if jsonb_typeof(item)<>'string' or item#>>'{}' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        raise check_violation using message='invalid_goods_kc_models';
      end if;
    end loop;
    select coalesce(jsonb_agg(lower(id) order by lower(id)),'[]') into ids from jsonb_array_elements_text(row->'variantIds') id;
    if (select count(distinct lower(id)) from jsonb_array_elements_text(row->'variantIds') id)<>jsonb_array_length(ids) then
      raise check_violation using message='invalid_goods_kc_models';
    end if;
    if jsonb_typeof(row->'evidence')<>'object' or not(row->'evidence' ?& array['applicability','certificate','testReport','declaration'])
      or exists(select 1 from jsonb_object_keys(row->'evidence') key where key not in ('applicability','certificate','testReport','declaration')) then
      raise check_violation using message='invalid_goods_kc_models';
    end if;
    evidence:='{}';
    foreach field in array array['applicability','certificate','testReport','declaration'] loop
      if jsonb_typeof(row->'evidence'->field)<>'string' then raise check_violation using message='invalid_goods_kc_models'; end if;
      value:=private.goods_kc_trim(row->'evidence'->>field);
      if length(value)>500 or value ~ '[[:cntrl:]]' then raise check_violation using message='invalid_goods_kc_models'; end if;
      evidence:=evidence||jsonb_build_object(field,value);
    end loop;
    models:=models||jsonb_build_array(normalized||jsonb_build_object('variantIds',ids,'evidence',evidence));
  end loop;
  return models;
end $function$

CREATE OR REPLACE FUNCTION private.normalize_goods_notice_kc_template(value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare model jsonb;
begin
  if value is null or value='null'::jsonb then return null; end if;
  if jsonb_typeof(value) is distinct from 'object' then raise invalid_parameter_value using message='invalid_goods_notice_kc_template'; end if;
  if not value ?& array['family','scheme','publicNote'] or (select count(*) from jsonb_object_keys(value))<>3
    or jsonb_typeof(value->'family') is distinct from 'string' or coalesce(value->>'family','')=''
    or jsonb_typeof(value->'scheme') is distinct from 'string' or coalesce(value->>'scheme','')=''
    or jsonb_typeof(value->'publicNote') is distinct from 'string'
    or (value->>'scheme'<>'not_applicable' and private.goods_kc_trim(value->>'publicNote')<>'') then
    raise invalid_parameter_value using message='invalid_goods_notice_kc_template';
  end if;
  -- Reuse the model-domain combination and text checks; template-only fields are allowlisted above.
  model:=private.normalize_goods_kc_models(jsonb_build_array(jsonb_build_object(
    'family',value->'family','scheme',value->'scheme','publicNote',value->'publicNote',
    'productCategory','','modelName','','businessRole','','businessName','','identifier','',
    'variantIds','[]'::jsonb,'basis','','evidence',jsonb_build_object('applicability','','certificate','','testReport','','declaration','')
  )))->0;
  if model->>'family'='' or model->>'scheme'='' then raise invalid_parameter_value using message='invalid_goods_notice_kc_template'; end if;
  return jsonb_build_object('family',model->'family','scheme',model->'scheme','publicNote',model->'publicNote');
end $function$

CREATE OR REPLACE FUNCTION private.normalize_goods_other_certifications(p_entries jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare entry jsonb; normalized jsonb:='[]'::jsonb; cert_kind text; cert_agency text; cert_number text;
  seen text[]:='{}'; entry_key text;
begin
  if p_entries is null or jsonb_typeof(p_entries)<>'array' or jsonb_array_length(p_entries)>20 then
    raise check_violation using message='invalid_goods_other_certifications';
  end if;
  for entry in select value from jsonb_array_elements(p_entries) loop
    if jsonb_typeof(entry)<>'object' or not (entry ?& array['kind','agency','number','visible'])
      or exists(select 1 from jsonb_object_keys(entry) key where key not in ('kind','agency','number','visible'))
      or jsonb_typeof(entry->'kind')<>'string' or jsonb_typeof(entry->'agency')<>'string'
      or jsonb_typeof(entry->'number')<>'string' or jsonb_typeof(entry->'visible')<>'boolean' then
      raise check_violation using message='invalid_goods_other_certifications';
    end if;
    cert_kind:=private.goods_kc_trim(entry->>'kind');
    cert_agency:=private.goods_kc_trim(entry->>'agency');
    cert_number:=private.goods_kc_trim(entry->>'number');
    if char_length(cert_kind)>100 or char_length(cert_agency)>100 or char_length(cert_number)>100
      or cert_kind ~ '[[:cntrl:]]' or cert_agency ~ '[[:cntrl:]]' or cert_number ~ '[[:cntrl:]]' then
      raise check_violation using message='invalid_goods_other_certifications';
    end if;
    if cert_kind='' or cert_number='' then
      raise check_violation using message='goods_other_certification_incomplete';
    end if;
    entry_key:=lower(cert_kind)||chr(31)||lower(cert_number);
    if entry_key=any(seen) then raise check_violation using message='goods_other_certification_duplicate'; end if;
    seen:=array_append(seen,entry_key);
    normalized:=normalized||jsonb_build_array(jsonb_build_object('kind',cert_kind,'agency',cert_agency,'number',cert_number,
      'visible',(entry->>'visible')::boolean));
  end loop;
  return normalized;
end $function$

CREATE OR REPLACE FUNCTION private.normalize_goods_transaction_address(p_address jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$declare name text;phone text;postal text;address1 text;begin
 if p_address='{"kind":"none"}'::jsonb then return p_address;end if;
 if jsonb_typeof(p_address) is distinct from 'object' or not(p_address ?& array['recipientName','phone','postalCode','address1'])
  or p_address-array['recipientName','phone','postalCode','address1','address2','deliveryNote']<>'{}'::jsonb
  or exists(select 1 from jsonb_each(p_address) e where jsonb_typeof(e.value) is distinct from 'string'
   or (e.value#>>'{}')<>btrim(e.value#>>'{}') or (e.value#>>'{}')~'[[:cntrl:]]') then
  raise invalid_parameter_value using message='invalid_checkout_address';end if;
 name:=p_address->>'recipientName';phone:=p_address->>'phone';postal:=p_address->>'postalCode';address1:=p_address->>'address1';
 if char_length(name) not between 1 and 50 or phone!~'^[0-9]{8,15}$' or postal!~'^[0-9]{5}$'
  or char_length(address1) not between 1 and 200 or char_length(coalesce(p_address->>'address2',''))>200
  or char_length(coalesce(p_address->>'deliveryNote',''))>200 then raise invalid_parameter_value using message='invalid_checkout_address';end if;
 return jsonb_build_object('recipientName',name,'phone',phone,'postalCode',postal,'address1',address1,
  'address2',coalesce(p_address->>'address2',''),'deliveryNote',coalesce(p_address->>'deliveryNote',''));
end $function$

CREATE OR REPLACE FUNCTION private.normalize_marketing_content(p_content jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare template text; title text; body text; image_path text; ids text[]; button jsonb; buttons jsonb:='[]'; max_lines integer;
begin
 if p_content is null or jsonb_typeof(p_content)<>'object' or not(p_content ?& array['template','title','body','imagePath','goodIds','buttons'])
  or exists(select 1 from jsonb_object_keys(p_content) key where key<>all(array['template','title','body','imagePath','goodIds','buttons','couponCode']))
  or jsonb_typeof(p_content->'template') is distinct from 'string' or jsonb_typeof(p_content->'title') is distinct from 'string'
  or jsonb_typeof(p_content->'body') is distinct from 'string' or jsonb_typeof(p_content->'imagePath') not in ('null','string')
  or jsonb_typeof(p_content->'goodIds') is distinct from 'array' or jsonb_typeof(p_content->'buttons') is distinct from 'array'
 then raise invalid_parameter_value using message='invalid_marketing_content';end if;
 if p_content?'couponCode' and (jsonb_typeof(p_content->'couponCode') not in ('null','string') or p_content->>'couponCode' !~ '^[A-Z0-9][A-Z0-9-]{2,23}$') then raise invalid_parameter_value using message='invalid_marketing_coupon';end if;
 template:=p_content->>'template';title:=btrim(p_content->>'title');body:=btrim(replace(p_content->>'body',E'\r\n',E'\n'));image_path:=p_content->>'imagePath';
 max_lines:=case template when 'text' then 16 when 'image' then 8 when 'product_list' then 2 when 'product_cards' then 2 end;
 if max_lines is null or char_length(title) not between 1 and 120 or title~'[[:cntrl:]]' or char_length(body) not between 1 and 500
  or body~E'[\\x01-\\x08\\x0B-\\x1F\\x7F]' or cardinality(string_to_array(body,E'\n'))>max_lines
  or image_path is not null and image_path !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  or template='image' and image_path is null or template in ('text','product_cards') and image_path is not null
  or jsonb_array_length(p_content->'goodIds')>6 or jsonb_array_length(p_content->'buttons')>2
  or exists(select 1 from jsonb_array_elements(p_content->'goodIds') v where jsonb_typeof(v)<>'string' or v#>>'{}' !~ '^[a-z0-9][a-z0-9-]{0,119}$')
 then raise invalid_parameter_value using message='invalid_marketing_content';end if;
 select coalesce(array_agg(value order by position),'{}'::text[]) into ids from jsonb_array_elements_text(p_content->'goodIds') with ordinality a(value,position);
 if cardinality(ids)<>(select count(distinct id) from unnest(ids) id)
  or template in ('text','image') and cardinality(ids)<>0 or template='product_list' and cardinality(ids) not between 1 and 3
  or template='product_cards' and cardinality(ids) not between 1 and 6 then raise invalid_parameter_value using message='invalid_marketing_content';end if;
 for button in select value from jsonb_array_elements(p_content->'buttons') loop
  if jsonb_typeof(button)<>'object' or not(button ?& array['label','path'])
   or exists(select 1 from jsonb_object_keys(button) key where key<>all(array['label','path']))
   or jsonb_typeof(button->'label') is distinct from 'string' or char_length(btrim(button->>'label')) not between 1 and 20 or button->>'label'~'[[:cntrl:]]'
   or jsonb_typeof(button->'path') is distinct from 'string' or char_length(button->>'path') not between 1 and 500
   or button->>'path' !~ '^/([^/].*)?$' or button->>'path'~'[[:cntrl:]]' or strpos(button->>'path',chr(92))>0
   or button->>'path'~* '^/(admin|api|auth|login|logout)(/|[?#]|$)' or strpos(button->>'path','%')>0
  then raise invalid_parameter_value using message='invalid_marketing_button';end if;
  buttons:=buttons||jsonb_build_array(jsonb_build_object('label',btrim(button->>'label'),'path',button->>'path'));
 end loop;
 return jsonb_build_object('template',template,'title',title,'body',body,'imagePath',image_path,'goodIds',to_jsonb(ids),'buttons',buttons)||case when p_content?'couponCode' then jsonb_build_object('couponCode',p_content->'couponCode') else '{}'::jsonb end;
end $function$

CREATE OR REPLACE FUNCTION private.normalize_shipping_charge_group_values(p_origin_id uuid, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare regional jsonb;policy jsonb;begin
 if not private.transaction_json_keys(p_values,array['name','enabled','archived','isDefault','calculationMode','regional'])
  or jsonb_typeof(p_values->'name') is distinct from 'string' or char_length(p_values->>'name') not between 1 and 80
  or p_values->>'name' is distinct from private.shipping_region_text(p_values->>'name') or p_values->>'name'~'[[:cntrl:]]'
  or jsonb_typeof(p_values->'enabled') is distinct from 'boolean' or jsonb_typeof(p_values->'archived') is distinct from 'boolean'
  or jsonb_typeof(p_values->'isDefault') is distinct from 'boolean' or coalesce(p_values->>'calculationMode','') not in('min','max')
  or ((p_values->>'archived')::boolean and (p_values->>'enabled')::boolean)
  or ((p_values->>'isDefault')::boolean and (not(p_values->>'enabled')::boolean or (p_values->>'archived')::boolean)) then
  raise invalid_parameter_value using message='invalid_shipping_charge_group_values';end if;
 regional:=p_values->'regional';
 if not private.transaction_json_keys(regional,array['mode','policy']) or coalesce(regional->>'mode','') not in('inherit','override')
  or ((regional->>'mode'='inherit') is distinct from (regional->'policy'='null'::jsonb)) then
  raise invalid_parameter_value using message='invalid_shipping_charge_group_region';end if;
 if regional->>'mode'='override' then
  policy:=private.shipping_charge_group_region_adapter(p_origin_id,p_values->>'name',regional->'policy');
  if (p_values->>'enabled')::boolean then perform private.assert_shipping_region_policy_complete(policy);end if;
  policy:=policy-array['originId','name','feeUnit','chargePolicyGoods','waivePolicyThreshold','chargeFreeGoods','chargeIndividualGoods'];
  regional:=jsonb_build_object('mode','override','policy',policy);
 end if;
 return jsonb_set(p_values,'{regional}',regional);
end $function$

CREATE OR REPLACE FUNCTION private.normalize_shipping_region_policy(p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb; rule jsonb; rules jsonb:='[]'; key text; rule_id uuid; seen_ids uuid[]:='{}';
begin
  if p_values is null or jsonb_typeof(p_values)<>'object' or not (p_values ?& array[
    'originId','carrierCode','name','startsAt','endsAt','openEnded','sourceEvidence','unlistedDisposition','feeUnit',
    'chargePolicyGoods','waivePolicyThreshold','chargeFreeGoods','chargeIndividualGoods','noRulesConfirmed','rules'])
    or exists(select 1 from jsonb_object_keys(p_values) field where field not in (
      'originId','carrierCode','name','startsAt','endsAt','openEnded','sourceEvidence','unlistedDisposition','feeUnit',
      'chargePolicyGoods','waivePolicyThreshold','chargeFreeGoods','chargeIndividualGoods','noRulesConfirmed','rules'))
    or jsonb_typeof(p_values->'originId')<>'string' or nullif(p_values->>'originId','') is null
    or jsonb_typeof(p_values->'carrierCode')<>'string' or nullif(btrim(p_values->>'carrierCode'),'') is null or length(p_values->>'carrierCode')>80
    or jsonb_typeof(p_values->'name')<>'string' or length(p_values->>'name')>100
    or jsonb_typeof(p_values->'sourceEvidence')<>'string' or length(p_values->>'sourceEvidence')>2000
    or jsonb_typeof(p_values->'noRulesConfirmed')<>'boolean'
    or jsonb_typeof(p_values->'rules')<>'array' or jsonb_array_length(p_values->'rules')>1000
    or jsonb_typeof(p_values->'unlistedDisposition') not in ('null','string')
    or (p_values->>'unlistedDisposition' is not null and p_values->>'unlistedDisposition' not in ('standard','manual_review'))
    or jsonb_typeof(p_values->'feeUnit') not in ('null','string')
    or (p_values->>'feeUnit' is not null and p_values->>'feeUnit' not in ('per_shipment','per_good')) then
    raise invalid_parameter_value using message='shipping_region_input_invalid';
  end if;
  perform (p_values->>'originId')::uuid;
  foreach key in array array['openEnded','chargePolicyGoods','waivePolicyThreshold','chargeFreeGoods','chargeIndividualGoods'] loop
    if jsonb_typeof(p_values->key) not in ('boolean','null') then raise invalid_parameter_value using message='shipping_region_input_invalid'; end if;
  end loop;
  foreach key in array array['startsAt','endsAt'] loop
    if jsonb_typeof(p_values->key) not in ('string','null') or (p_values->>key is not null and not isfinite((p_values->>key)::timestamptz)) then
      raise invalid_parameter_value using message='shipping_region_input_invalid';
    end if;
  end loop;
  if p_values->>'startsAt' is not null and p_values->>'endsAt' is not null
    and (p_values->>'startsAt')::timestamptz >= (p_values->>'endsAt')::timestamptz then
    raise invalid_parameter_value using message='shipping_region_period_invalid';
  end if;
  for rule in select value from jsonb_array_elements(p_values->'rules') loop
    if jsonb_typeof(rule)<>'object' or not (rule ?& array['id','postalFrom','postalTo','addressPrefix','regionLabel','disposition','amount'])
      or exists(select 1 from jsonb_object_keys(rule) field where field not in ('id','postalFrom','postalTo','addressPrefix','regionLabel','disposition','amount'))
      or jsonb_typeof(rule->'id') not in ('null','string')
      or jsonb_typeof(rule->'postalFrom')<>'string' or (rule->>'postalFrom')!~'^(\d{5})?$'
      or jsonb_typeof(rule->'postalTo')<>'string' or (rule->>'postalTo')!~'^(\d{5})?$'
      or jsonb_typeof(rule->'addressPrefix')<>'string' or length(rule->>'addressPrefix')>200
      or jsonb_typeof(rule->'regionLabel')<>'string' or length(rule->>'regionLabel')>100
      or jsonb_typeof(rule->'disposition')<>'string' or rule->>'disposition' not in ('','standard','surcharge','unavailable','manual_review')
      or jsonb_typeof(rule->'amount') not in ('null','number')
      or (rule->>'amount' is not null and ((rule->>'amount')!~'^\d+$' or (rule->>'amount')::numeric not between 0 and 1000000)) then
      raise invalid_parameter_value using message='shipping_region_rule_invalid';
    end if;
    rule_id:=coalesce((rule->>'id')::uuid,gen_random_uuid());
    if rule_id=any(seen_ids) then raise invalid_parameter_value using message='shipping_region_rule_invalid'; end if;
    seen_ids:=array_append(seen_ids,rule_id);
    rules:=rules||jsonb_build_array(rule||jsonb_build_object('id',rule_id,
      'addressPrefix',private.shipping_region_text(rule->>'addressPrefix'),'regionLabel',private.shipping_region_text(rule->>'regionLabel')));
  end loop;
  result:=p_values||jsonb_build_object('originId',(p_values->>'originId')::uuid,'carrierCode',btrim(p_values->>'carrierCode'),
    'name',private.shipping_region_text(p_values->>'name'),'sourceEvidence',btrim(p_values->>'sourceEvidence'),
    'startsAt',(p_values->>'startsAt')::timestamptz,'endsAt',(p_values->>'endsAt')::timestamptz,'rules',rules);
  return result;
end $function$

CREATE OR REPLACE FUNCTION private.normalize_stock_digest_recipients(p_values text[], p_limit integer)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare value text;normalized text[]:='{}'::text[];
begin
  if p_values is null then raise invalid_parameter_value using message='invalid_stock_digest_recipient';end if;
  foreach value in array p_values loop
    value:=lower(btrim(coalesce(value,''),E' \t\n\r\f\v'));
    if value='' then continue;end if;
    if char_length(value)>254 or value!~'^[^@[:space:][:cntrl:],;<>"]{1,64}@[^@[:space:][:cntrl:],;<>"]+\.[^@[:space:][:cntrl:],;<>".]+$' then
      raise invalid_parameter_value using message='invalid_stock_digest_recipient';
    end if;
    if not value=any(normalized) then normalized:=normalized||value;end if;
  end loop;
  if cardinality(normalized)>p_limit then raise invalid_parameter_value using message='stock_digest_recipient_limit';end if;
  return normalized;
end $function$

CREATE OR REPLACE FUNCTION private.notify_goods_restock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  -- 판매 가능 술어가 거짓→참으로 전이할 때만 발화한다.
  if not (private.restock_parent_open(new) and new.stock_qty > 0)
    or (private.restock_parent_open(old) and old.stock_qty > 0) then
    return new;
  end if;

  perform private.wake_restock_alerts(new, null);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.notify_goods_variant_restock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_good public.goods;
begin
  -- 트리거 WHEN 과 같은 조건이다. 함수가 다른 자리에 다시 쓰여도 뜻이 바뀌지 않게 여기서도 본다.
  -- 예약판매 옵션에 실물이 입고돼도(할당 전 재고 조정) 재고 판매가 아니라 깨우지 않는다. 재고 판매로
  -- 바꾸는 순간(preorder_policy_id → null) 재고가 남아 있으면 그때가 이 옵션의 재입고다.
  if not (new.archived_at is null and new.preorder_policy_id is null and new.stock_qty > 0)
    or (old.archived_at is null and old.preorder_policy_id is null and old.stock_qty > 0) then
    return null;
  end if;

  -- 굿즈 행을 잠근 뒤에 신청을 본다. 신청 RPC 는 같은 행을 for share 로 잡은 채 판정·삽입하므로
  -- 잠그지 않고 보면 커밋 직전의 신청을 놓쳐 그 신청이 다음 사이클까지 침묵한다. 재고를 쓰는
  -- 경로는 이미 이 행을 잠갔고(재고 캐시 갱신 트리거도 같은 잠금을 잡는다) 잠금 순서도 그대로다.
  select * into target_good from public.goods where id = new.good_id for update;
  if not found then
    return null;
  end if;

  -- 재고 외 판매 가능 조건(판매 기간 포함). 재고 조건은 이 옵션의 전이 자체다. 닫혀 있으면 신청은 pending 으로
  -- 남고, 조건이 다시 열릴 때 ① 트리거나 청소 작업이 깨운다.
  if not private.restock_parent_open(target_good) then
    return null;
  end if;

  perform private.wake_restock_alerts(target_good, new.id);
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.notify_order_partial_cancellation(p_id uuid, p_event text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare head private.order_partial_cancellations; purchase public.orders; label text; body text; title text;
begin
  select * into head from private.order_partial_cancellations where id = p_id;
  select * into purchase from public.orders where id = head.order_id;
  label := left(coalesce(private.partial_cancellation_items_label(p_id), '일부 굿즈'), 200);
  if p_event = 'applied' then
    title := '주문 일부가 취소됐어요';
    body := format('재고가 부족해 %s를 취소했습니다. %s%s나머지 굿즈는 그대로 보내드립니다.', label,
      case when head.refund_amount = 0 then '돌려드릴 결제 금액은 없습니다. '
        when head.provider = 'bank_transfer'
        then format('환불 %s은 등록하신 환불계좌로 송금해 드립니다. ', private.format_krw(head.refund_amount))
        else format('%s을 결제사에서 부분 취소했습니다(카드사 처리에 영업일 기준 3~4일). ', private.format_krw(head.refund_amount)) end,
      case when head.store_credit_restore_amount > 0
        then format('사용하신 적립금 %s은 적립금으로 되돌려 드렸습니다. ', private.format_krw(head.store_credit_restore_amount)) else '' end);
  elsif p_event = 'transferred' then
    title := '부분 취소 환불을 송금했어요';
    body := format('취소한 %s의 환불 %s을 환불계좌로 송금했습니다.', label, private.format_krw(head.refund_amount));
  else
    return;
  end if;
  insert into public.notifications(user_id, type, title, body, link_path, source_type, source_id, dedupe_key)
  values (purchase.user_id, 'claim_updated', title, left(body, 500), '/orders/' || purchase.id::text, 'order_partial_cancellation', head.id::text,
    'partial-cancel:' || p_event || ':' || head.id::text)
  on conflict (user_id, dedupe_key) do nothing;
end $function$

CREATE OR REPLACE FUNCTION private.operator_access_for(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  state private.operator_access_state;
  actor public.profiles;
  membership private.operator_memberships;
  access_mode text := 'none';
  caps text[] := '{}';
begin
  select * into state from private.operator_access_state where id;
  select * into actor from public.profiles where id=p_actor;
  if found and actor.role in ('staff','admin') and actor.suspended_at is null
    and not exists(select 1 from private.account_action_fences where subject_user_id=p_actor) then
    select * into membership from private.operator_memberships where profile_id=p_actor;
    if found then
      access_mode := 'configured';
      caps := private.operator_role_capabilities(membership.manager_role);
    elsif not state.configured and exists(select 1 from private.operator_legacy_cohort where profile_id=p_actor) then
      access_mode := 'legacy';
      caps := private.operator_role_capabilities('primary');
      if actor.role <> 'admin' then caps := array_remove(caps,'operators.manage'); end if;
    end if;
  end if;
  return jsonb_build_object('mode',access_mode,'managerRole',membership.manager_role,
    'capabilities',to_jsonb(caps),'revision',coalesce(state.revision,1),
    'setupRequired',not coalesce(state.configured,false));
end $function$

CREATE OR REPLACE FUNCTION private.operator_lifecycle_replay(p_actor uuid, p_operation_id uuid, p_action text, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous public.audit_log;
begin
  select * into previous from public.audit_log where id=p_operation_id;
  if not found then return null; end if;
  if previous.actor_id=p_actor and previous.action=p_action and previous.diff->'request'=p_request then return previous.diff->'result'; end if;
  raise unique_violation using message='operation_conflict';
end $function$

CREATE OR REPLACE FUNCTION private.operator_mfa_blocks(p_actor uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claims jsonb;
begin
  if p_actor is null or not exists(select 1 from private.operator_mfa_policy p where p.singleton and p.required) then return false; end if;
  claims:=(select auth.jwt());
  if claims is null or claims->>'role' is distinct from 'authenticated' or p_actor is distinct from (select auth.uid()) then return false; end if;
  return not private.operator_mfa_session_verified(p_actor);
end $function$

CREATE OR REPLACE FUNCTION private.operator_mfa_session_verified(p_actor uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claims jsonb:=(select auth.jwt()); session_text text;
begin
  if p_actor is null or claims is null or p_actor is distinct from (select auth.uid()) or claims->>'aal' is distinct from 'aal2' then return false; end if;
  session_text:=claims->>'session_id';
  if session_text is null or session_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return false; end if;
  return private.operator_mfa_session_ok(p_actor,session_text::uuid);
end $function$

CREATE OR REPLACE FUNCTION private.operator_revoke_auth_sessions(p_user uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare removed integer;
begin
  if p_user is null then return 0; end if;
  delete from auth.sessions where user_id=p_user;
  get diagnostics removed=row_count;
  return removed;
end $function$

CREATE OR REPLACE FUNCTION private.order_item_price_allocation(p_order_item_id uuid)
 RETURNS private.order_price_allocations
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result private.order_price_allocations; item public.order_items; derived jsonb; entry jsonb;
begin
  select l.order_item_id, l.order_id, l.calculation_version, l.subtotal, l.volume_discount, l.net_subtotal, l.coupon_discount,
    l.store_credit_discount, l.paid_goods_total
    into result from private.order_price_allocation_ledger l where l.order_item_id = p_order_item_id;
  if found then return result; end if;
  select * into item from public.order_items where id = p_order_item_id;
  if not found or (select calculation_version from public.orders where id = item.order_id) is distinct from 1
    or exists(select 1 from private.order_v1_price_allocation_heads where order_id = item.order_id) then
    return null;
  end if;
  derived := private.order_v1_allocation_derive(item.order_id);
  if not coalesce((derived->>'ok')::boolean, false) then return null; end if;
  select value into entry from jsonb_array_elements(derived->'items') where value->>'orderItemId' = p_order_item_id::text;
  if entry is null then return null; end if;
  result := row(p_order_item_id, item.order_id, 1, (entry->>'subtotal')::bigint, (entry->>'volumeDiscount')::bigint,
    (entry->>'netSubtotal')::bigint, (entry->>'couponDiscount')::bigint, (entry->>'storeCreditDiscount')::bigint,
    (entry->>'paidGoodsTotal')::bigint)::private.order_price_allocations;
  return result;
end $function$

CREATE OR REPLACE FUNCTION private.order_partial_cancellation_blockers(p_order_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare purchase public.orders; pay public.payments; payment_count integer; blockers text[] := array[]::text[];
begin
  if not private.order_partial_cancel_enabled() then blockers := array_append(blockers, 'partial_cancel_disabled'); end if;
  select * into purchase from public.orders where id = p_order_id;
  if not found then return array_append(blockers, 'order_not_found'); end if;
  if purchase.status not in ('paid', 'confirmed') or purchase.shipped_at is not null or purchase.delivered_at is not null or purchase.done_at is not null then
    blockers := array_append(blockers, 'order_not_partial_cancelable');
  end if;
  if exists(select 1 from public.order_shipments s where s.order_id = p_order_id
      and (s.status not in ('ready', 'canceled') or s.shipped_at is not null or s.delivered_at is not null)) then
    blockers := array_append(blockers, 'shipment_already_dispatched');
  end if;
  if exists(select 1 from public.order_cancellation_requests r where r.order_id = p_order_id and r.status in ('requested', 'processing', 'needs_review'))
    or exists(select 1 from public.order_cancellation_claims c where c.order_id = p_order_id) then
    blockers := array_append(blockers, 'order_claim_in_progress');
  end if;
  if private.order_partial_cancel_in_flight(p_order_id) then blockers := array_append(blockers, 'partial_cancel_in_progress'); end if;
  if exists(select 1 from public.payment_attempts a where a.purpose = 'order' and a.ref_id = p_order_id
      and a.state in ('prepared', 'confirming', 'unknown', 'needs_review')) then
    blockers := array_append(blockers, 'payment_reconciliation_required');
  end if;
  -- 버전 1 주문은 첫 부분 취소 때 얼리는 파생 배분 원장을 쓴다(ADR-0032 보완). 배분을 확정할 수 없으면 그 이유로 막는다.
  if purchase.calculation_version = 1 then blockers := blockers || private.order_v1_allocation_blockers(p_order_id);
  elsif purchase.calculation_version is distinct from 2 then blockers := array_append(blockers, 'legacy_order'); end if;
  select count(*) into payment_count from public.payments p where p.purpose = 'order' and p.ref_id = p_order_id and p.status <> 'failed';
  pay := private.order_partial_cancellation_payment(p_order_id);
  if payment_count <> 1 or pay.id is null or pay.status <> 'paid' or pay.amount <= 0 or pay.amount <> purchase.total then
    blockers := array_append(blockers, 'payment_unavailable');
  elsif pay.provider not in ('toss', 'bank_transfer')
    or pay.provider = 'toss' and nullif(btrim(pay.payment_key), '') is null
    -- 정기배송(billing) 결제는 결제사 부분 취소 계약이 없다.
    or exists(select 1 from public.payment_attempts a join private.payment_provider_bindings b on b.attempt_id = a.id
      where a.purpose = 'order' and a.ref_id = p_order_id)
    -- 토스 가상계좌는 입금 전 부분 취소가 없고 환불계좌 경로가 다르다.
    or pay.provider = 'toss' and exists(select 1 from public.payment_attempts a
      join private.payment_provider_evidence e on e.payment_attempt_id = a.id
      where a.purpose = 'order' and a.ref_id = p_order_id and (e.payment_method = '가상계좌' or e.result_code = 'DONE_virtual_account')) then
    blockers := array_append(blockers, 'partial_cancel_unsupported');
  end if;
  return blockers;
end $function$

CREATE OR REPLACE FUNCTION private.order_partial_cancellation_item_blocker(p_order_item_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item public.order_items; physical record; target record; link public.order_shipment_items; active integer;
begin
  select * into item from public.order_items where id = p_order_item_id;
  if not found then return 'order_item_not_found'; end if;
  active := private.order_item_active_qty(item.id);
  if active <= 0 then return 'fully_canceled'; end if;
  if item.supply_source <> 'stock' then return 'preorder_item'; end if;
  if item.production_terms_snapshot is not null or exists(select 1 from private.order_production_jobs j where j.order_item_id = item.id) then
    return 'production_item';
  end if;
  if coalesce(item.fulfillment_terms_snapshot->>'mode', '') in ('digital', 'no_delivery') then return 'digital_item'; end if;
  if (private.order_item_price_allocation(item.id)).order_item_id is distinct from item.id then
    return 'allocation_missing';
  end if;
  select * into link from public.order_shipment_items where order_item_id = item.id and order_id = item.order_id;
  if not found or link.qty <> active then return 'shipment_missing'; end if;
  if exists(select 1 from public.order_shipments s where s.id = link.shipment_id and (s.status <> 'ready' or s.delivery_method = 'digital')) then
    return 'shipment_missing';
  end if;
  -- 상품 통합(재고 승계)·교환 재출고 배정 이력이 있는 품목은 재고 복원 단위가 품목 전체라 수량 단위로 나누지 않는다.
  select * into physical from private.order_item_physical_unit(item.id);
  select * into target from private.resolve_goods_stock_successor(physical.good_id, physical.variant_id);
  if target.hop_count > 0 or physical.good_id <> item.good_id
    or exists(select 1 from private.group_claim_reshipment_allocations where order_item_id = item.id) then
    return 'stock_topology_changed';
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.order_partial_cancellation_plan(p_order_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  blockers text[]; purchase public.orders; pay public.payments; entry jsonb; item public.order_items; allocation private.order_price_allocations;
  link public.order_shipment_items; ship public.order_shipments; item_blocker text; qty integer; canceled_before integer; canceled_after integer;
  lines jsonb := '[]'::jsonb; closed jsonb := '[]'::jsonb; touched uuid[] := array[]::uuid[]; seen uuid[] := array[]::uuid[];
  goods bigint := 0; shipping bigint := 0; credit bigint := 0; balance bigint; line_paid bigint; line_volume bigint; line_coupon bigint;
  line_credit bigint; stop_required boolean := false; remaining integer; shipment_left integer; ship_id uuid;
begin
  blockers := private.order_partial_cancellation_blockers(p_order_id);
  if cardinality(blockers) > 0 then raise check_violation using message = blockers[1]; end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 100 then
    raise invalid_parameter_value using message = 'invalid_partial_cancel_items';
  end if;
  select * into purchase from public.orders where id = p_order_id;
  pay := private.order_partial_cancellation_payment(p_order_id);
  for entry in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(entry) <> 'object' or (select count(*) from jsonb_object_keys(entry)) <> 2 or not entry ?& array['orderItemId', 'qty']
      or jsonb_typeof(entry->'orderItemId') <> 'string' or coalesce(entry->>'orderItemId', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or jsonb_typeof(entry->'qty') <> 'number' or coalesce(entry->>'qty', '') !~ '^[1-9][0-9]{0,5}$' then
      raise invalid_parameter_value using message = 'invalid_partial_cancel_items';
    end if;
    if (entry->>'orderItemId')::uuid = any(seen) then raise invalid_parameter_value using message = 'invalid_partial_cancel_items'; end if;
    seen := seen || (entry->>'orderItemId')::uuid;
    select * into item from public.order_items where id = (entry->>'orderItemId')::uuid and order_id = p_order_id;
    if not found then raise check_violation using message = 'partial_cancel_item_not_found'; end if;
    item_blocker := private.order_partial_cancellation_item_blocker(item.id);
    if item_blocker is not null then raise check_violation using message = 'partial_cancel_item_' || item_blocker; end if;
    qty := (entry->>'qty')::integer;
    canceled_before := private.order_item_partially_canceled_qty(item.id);
    if qty > item.qty - canceled_before then raise check_violation using message = 'partial_cancel_qty_exceeds_remaining'; end if;
    canceled_after := canceled_before + qty;
    allocation := private.order_item_price_allocation(item.id);
    select * into link from public.order_shipment_items where order_item_id = item.id and order_id = p_order_id;
    select * into ship from public.order_shipments where id = link.shipment_id;
    line_paid := private.partial_cancel_prorate(allocation.paid_goods_total, canceled_after, item.qty)
      - private.partial_cancel_prorate(allocation.paid_goods_total, canceled_before, item.qty);
    line_volume := private.partial_cancel_prorate(allocation.volume_discount, canceled_after, item.qty)
      - private.partial_cancel_prorate(allocation.volume_discount, canceled_before, item.qty);
    line_coupon := private.partial_cancel_prorate(allocation.coupon_discount, canceled_after, item.qty)
      - private.partial_cancel_prorate(allocation.coupon_discount, canceled_before, item.qty);
    line_credit := private.partial_cancel_prorate(allocation.store_credit_discount, canceled_after, item.qty)
      - private.partial_cancel_prorate(allocation.store_credit_discount, canceled_before, item.qty);
    goods := goods + line_paid;
    credit := credit + line_credit;
    if ship.exported_at is not null then stop_required := true; end if;
    if not ship.id = any(touched) then touched := touched || ship.id; end if;
    lines := lines || jsonb_build_object('orderItemId', item.id, 'shipmentId', ship.id, 'shipmentNumber', ship.shipment_number,
      'originName', ship.origin_name_snapshot, 'exported', ship.exported_at is not null,
      'goodName', item.good_name_snapshot, 'variantName', item.variant_name_snapshot, 'variantCode', item.variant_code_snapshot,
      'qty', qty, 'orderedQty', item.qty, 'canceledQtyBefore', canceled_before, 'remainingQtyAfter', item.qty - canceled_after,
      'grossAmount', qty::bigint * item.unit_price - line_volume, 'volumeDiscount', line_volume, 'couponDiscount', line_coupon,
      'storeCreditDiscount', line_credit, 'goodsRefundAmount', line_paid);
  end loop;
  -- 배송 건에 남는 품목이 없으면 그 배송 건을 닫고 선결제 배송비를 함께 돌려준다.
  foreach ship_id in array touched loop
    select coalesce(sum(l.qty), 0) - coalesce((select sum((x->>'qty')::integer) from jsonb_array_elements(lines) x
        where (x->>'shipmentId')::uuid = ship_id), 0)
      into shipment_left from public.order_shipment_items l where l.shipment_id = ship_id;
    if shipment_left = 0 then
      select * into ship from public.order_shipments where id = ship_id;
      -- 합포장 팩에 묶인 배송 건을 닫으면 같은 팩의 다른 배송 건이 출고·해제되지 못한다. 먼저 합포장을 해제한다.
      if exists(select 1 from private.shipment_pack_members m where m.shipment_id = ship.id and m.released_at is null) then
        raise check_violation using message = 'partial_cancel_shipment_packed';
      end if;
      shipping := shipping + private.order_shipment_prepaid_fee(ship.id);
      closed := closed || jsonb_build_object('shipmentId', ship.id, 'shipmentNumber', ship.shipment_number, 'originName', ship.origin_name_snapshot,
        'shippingFeeRefund', private.order_shipment_prepaid_fee(ship.id), 'shippingCollectFee', ship.shipping_collect_fee, 'exported', ship.exported_at is not null);
    end if;
  end loop;
  select coalesce(sum(l.qty), 0) - coalesce((select sum((x->>'qty')::integer) from jsonb_array_elements(lines) x), 0)
    into remaining from public.order_shipment_items l where l.order_id = p_order_id;
  if remaining <= 0 then raise check_violation using message = 'partial_cancel_leaves_nothing'; end if;
  balance := pay.amount - private.payment_partial_refunded_amount(pay.id);
  -- 환불액 0원은 결제사를 부르지 않고 바로 적용한다. 남는 잔액이 0원이면 남은 잔액 전부를 결제사 부분 취소로 보낸다.
  if goods + shipping > balance then raise check_violation using message = 'partial_cancel_exceeds_balance'; end if;
  return jsonb_build_object('orderId', p_order_id, 'orderNumber', purchase.order_number, 'paymentId', pay.id, 'provider', pay.provider,
    'paymentAmount', pay.amount, 'balanceBefore', balance, 'goodsRefundAmount', goods, 'shippingRefundAmount', shipping,
    'refundAmount', goods + shipping, 'balanceAfter', balance - goods - shipping, 'storeCreditRestoreAmount', credit,
    'warehouseStopRequired', stop_required, 'remainingQty', remaining, 'lines', lines, 'closedShipments', closed);
end $function$

CREATE OR REPLACE FUNCTION private.order_shipment_prepaid_fee(p_shipment_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ship public.order_shipments; fee bigint; derived jsonb;
begin
  select * into ship from public.order_shipments where id = p_shipment_id;
  if not found then raise no_data_found using message = 'shipment_not_found'; end if;
  if (select calculation_version from public.orders where id = ship.order_id) is distinct from 1 then return ship.shipping_fee; end if;
  if exists(select 1 from private.order_v1_price_allocation_heads where order_id = ship.order_id) then
    select prepaid_shipping_fee into fee from private.order_v1_shipment_allocations where shipment_id = p_shipment_id;
  else
    derived := private.order_v1_allocation_derive(ship.order_id);
    if coalesce((derived->>'ok')::boolean, false) then
      select (value->>'prepaidShippingFee')::bigint into fee from jsonb_array_elements(derived->'shipments') where value->>'shipmentId' = p_shipment_id::text;
    end if;
  end if;
  if fee is null then raise check_violation using message = 'partial_cancel_v1_allocation_unavailable'; end if;
  return fee;
end $function$

CREATE OR REPLACE FUNCTION private.order_v1_allocate(p_amount bigint, p_weights jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if p_amount = 0 then
    return (select jsonb_object_agg(w->>'id', 0) from jsonb_array_elements(p_weights) w);
  end if;
  if (select coalesce(sum((w->>'weight')::numeric), 0) from jsonb_array_elements(p_weights) w) < p_amount then return null; end if;
  return private.allocate_transaction_amount(p_amount, p_weights);
end $function$

CREATE OR REPLACE FUNCTION private.order_v1_allocation_derive(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  rule constant text := 'v1-a5-largest-remainder-1';
  purchase public.orders; pay public.payments; payment_count integer; redemption public.coupon_redemptions; terms jsonb;
  item_rows jsonb; ship_rows jsonb; coupon_alloc jsonb; credit_alloc jsonb; entry jsonb; result_items jsonb := '[]'::jsonb;
  eligible_total bigint := 0; goods_total bigint := 0; shipping_total bigint := 0; paid_total bigint := 0;
  line_coupon bigint; line_credit bigint; line_paid bigint; input jsonb;
begin
  select * into purchase from public.orders where id = p_order_id;
  if not found then return jsonb_build_object('ok', false, 'issue', 'order_not_found', 'ruleVersion', rule); end if;
  if purchase.calculation_version is distinct from 1 then return jsonb_build_object('ok', false, 'issue', 'not_v1', 'ruleVersion', rule); end if;
  select count(*) into payment_count from public.payments p where p.purpose = 'order' and p.ref_id = p_order_id and p.status <> 'failed';
  pay := private.order_partial_cancellation_payment(p_order_id);
  if payment_count <> 1 or pay.id is null or pay.amount <= 0 or pay.amount <> purchase.total then
    return jsonb_build_object('ok', false, 'issue', 'payment_unavailable', 'ruleVersion', rule);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'goodId', i.good_id, 'ipId', i.good_ip_id_snapshot, 'qty', i.qty,
      'unitPrice', i.unit_price, 'subtotal', i.qty::bigint * i.unit_price::bigint, 'volumeDiscount', i.volume_discount_total) order by i.id), '[]'::jsonb)
    into item_rows from public.order_items i where i.order_id = p_order_id;
  if jsonb_array_length(item_rows) = 0 then return jsonb_build_object('ok', false, 'issue', 'items_missing', 'ruleVersion', rule); end if;
  if purchase.volume_discount_total <> 0 or purchase.shipping_coupon_discount_total <> 0
    or exists(select 1 from jsonb_array_elements(item_rows) x where (x->>'volumeDiscount')::bigint <> 0)
    or exists(select 1 from public.coupon_redemptions r where r.order_id = p_order_id and r.status = 'applied' and r.benefit_kind <> 'goods') then
    return jsonb_build_object('ok', false, 'issue', 'unsupported_discount', 'ruleVersion', rule);
  end if;
  select coalesce(sum((x->>'subtotal')::bigint), 0) into goods_total from jsonb_array_elements(item_rows) x;

  -- 쿠폰: 화면·엑셀(admin_order_item_allocation_inputs)과 같은 기록(적용된 상품 쿠폰 중 첫 번째)과 같은 대상 판정.
  if purchase.discount_total > 0 then
    select * into redemption from public.coupon_redemptions r
      where r.order_id = p_order_id and r.status = 'applied' and r.benefit_kind = 'goods' order by r.application_index limit 1;
    terms := redemption.terms_snapshot;
    if redemption.id is null or terms is null or jsonb_typeof(terms) <> 'object' or redemption.eligible_subtotal is null
      or coalesce(terms->>'goodsScope', '') not in ('all', 'selected_goods', 'selected_categories', 'selected_ips')
      or coalesce(jsonb_typeof(terms->'targetGoodIds'), 'null') not in ('null', 'array')
      or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(terms->'targetGoodIds') = 'array' then terms->'targetGoodIds' else '[]'::jsonb end) t
        where jsonb_typeof(t) <> 'string')
      or terms ? 'targetCategoryIds' and (jsonb_typeof(terms->'targetCategoryIds') <> 'array'
        or exists(select 1 from jsonb_array_elements(terms->'targetCategoryIds') t where jsonb_typeof(t) <> 'string'))
      or terms ? 'targetIpIds' and (jsonb_typeof(terms->'targetIpIds') <> 'array'
        or exists(select 1 from jsonb_array_elements(terms->'targetIpIds') t where jsonb_typeof(t) <> 'string')) then
      return jsonb_build_object('ok', false, 'issue', 'coupon_unrecorded', 'ruleVersion', rule);
    end if;
    if redemption.discount_amount <> purchase.discount_total then
      return jsonb_build_object('ok', false, 'issue', 'coupon_amount_mismatch', 'ruleVersion', rule);
    end if;
    select jsonb_agg(x || jsonb_build_object('couponEligible', private.coupon_line_eligible_now(terms, x->>'goodId', x->>'ipId')) order by x->>'id')
      into item_rows from jsonb_array_elements(item_rows) x;
    if exists(select 1 from jsonb_array_elements(item_rows) x where jsonb_typeof(x->'couponEligible') <> 'boolean') then
      return jsonb_build_object('ok', false, 'issue', 'coupon_unrecorded', 'ruleVersion', rule);
    end if;
    select coalesce(sum((x->>'subtotal')::bigint) filter (where (x->>'couponEligible')::boolean), 0) into eligible_total
      from jsonb_array_elements(item_rows) x;
    if eligible_total <> redemption.eligible_subtotal then
      return jsonb_build_object('ok', false, 'issue', 'coupon_target_mismatch', 'ruleVersion', rule);
    end if;
    coupon_alloc := private.order_v1_allocate(purchase.discount_total, (select jsonb_agg(jsonb_build_object('id', x->>'id',
      'weight', case when (x->>'couponEligible')::boolean then (x->>'subtotal')::bigint else 0 end)) from jsonb_array_elements(item_rows) x));
    if coupon_alloc is null then return jsonb_build_object('ok', false, 'issue', 'coupon_target_mismatch', 'ruleVersion', rule); end if;
  else
    coupon_alloc := (select jsonb_object_agg(x->>'id', 0) from jsonb_array_elements(item_rows) x);
  end if;

  -- 적립금: 쿠폰 뒤 품목 금액 비례.
  credit_alloc := private.order_v1_allocate(purchase.store_credit_total, (select jsonb_agg(jsonb_build_object('id', x->>'id',
    'weight', (x->>'subtotal')::bigint - (coupon_alloc->>(x->>'id'))::bigint)) from jsonb_array_elements(item_rows) x));
  if credit_alloc is null then return jsonb_build_object('ok', false, 'issue', 'credit_mismatch', 'ruleVersion', rule); end if;

  for entry in select value from jsonb_array_elements(item_rows) loop
    line_coupon := (coupon_alloc->>(entry->>'id'))::bigint;
    line_credit := (credit_alloc->>(entry->>'id'))::bigint;
    line_paid := (entry->>'subtotal')::bigint - (entry->>'volumeDiscount')::bigint - line_coupon - line_credit;
    if line_paid < 0 then return jsonb_build_object('ok', false, 'issue', 'amount_mismatch', 'ruleVersion', rule); end if;
    paid_total := paid_total + line_paid;
    result_items := result_items || jsonb_build_object('orderItemId', entry->>'id', 'subtotal', (entry->>'subtotal')::bigint,
      'volumeDiscount', (entry->>'volumeDiscount')::bigint, 'netSubtotal', (entry->>'subtotal')::bigint - (entry->>'volumeDiscount')::bigint,
      'couponDiscount', line_coupon, 'storeCreditDiscount', line_credit, 'paidGoodsTotal', line_paid);
  end loop;

  -- 배송 건 선결제 배송비: 주문 배송비 스냅숏 그대로.
  select coalesce(jsonb_agg(jsonb_build_object('shipmentId', s.id, 'shippingFee', s.shipping_fee,
      'snapshotTotalFee', s.shipping_fee_snapshot->'totalFee') order by s.id), '[]'::jsonb)
    into ship_rows from public.order_shipments s where s.order_id = p_order_id;
  if jsonb_array_length(ship_rows) = 0 or exists(select 1 from jsonb_array_elements(ship_rows) x
      where case when coalesce(jsonb_typeof(x->'snapshotTotalFee'), 'missing') <> 'number' or (x->>'snapshotTotalFee') !~ '^[0-9]{1,15}$' then true
        else (x->>'snapshotTotalFee')::bigint <> (x->>'shippingFee')::bigint end) then
    return jsonb_build_object('ok', false, 'issue', 'shipping_snapshot_mismatch', 'ruleVersion', rule);
  end if;
  select coalesce(sum((x->>'shippingFee')::bigint), 0) into shipping_total from jsonb_array_elements(ship_rows) x;
  if shipping_total <> purchase.shipping_fee then
    return jsonb_build_object('ok', false, 'issue', 'shipping_snapshot_mismatch', 'ruleVersion', rule);
  end if;

  -- 핵심 검사: 품목 결제 몫 합 + 배송 건 배송비 합 = 결제액(1원 단위).
  if paid_total + shipping_total <> pay.amount then
    return jsonb_build_object('ok', false, 'issue', 'amount_mismatch', 'ruleVersion', rule);
  end if;

  input := jsonb_build_object('ruleVersion', rule,
    'order', jsonb_build_object('id', purchase.id, 'calculationVersion', purchase.calculation_version, 'total', purchase.total,
      'shippingFee', purchase.shipping_fee, 'discountTotal', purchase.discount_total, 'storeCreditTotal', purchase.store_credit_total,
      'volumeDiscountTotal', purchase.volume_discount_total, 'shippingCouponDiscountTotal', purchase.shipping_coupon_discount_total),
    'payment', jsonb_build_object('id', pay.id, 'amount', pay.amount),
    'coupon', case when redemption.id is null then null else jsonb_build_object('redemptionId', redemption.id, 'code', redemption.coupon_code,
      'discountAmount', redemption.discount_amount, 'eligibleSubtotal', redemption.eligible_subtotal, 'terms', terms) end,
    'items', item_rows, 'shipments', ship_rows);
  return jsonb_build_object('ok', true, 'issue', null, 'ruleVersion', rule,
    'inputHash', encode(extensions.digest(convert_to(input::text, 'UTF8'), 'sha256'), 'hex'), 'input', input,
    'paymentId', pay.id, 'paymentAmount', pay.amount, 'goodsTotal', goods_total, 'volumeDiscountTotal', 0,
    'couponDiscountTotal', purchase.discount_total, 'storeCreditTotal', purchase.store_credit_total, 'paidGoodsTotal', paid_total,
    'shippingTotal', shipping_total, 'items', result_items,
    'shipments', (select jsonb_agg(jsonb_build_object('shipmentId', x->'shipmentId', 'prepaidShippingFee', (x->>'shippingFee')::bigint)
      order by x->>'shipmentId') from jsonb_array_elements(ship_rows) x));
end $function$

CREATE OR REPLACE FUNCTION private.order_v1_allocation_state(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare derived jsonb;
begin
  if (select calculation_version from public.orders where id = p_order_id) is distinct from 1 then return null; end if;
  if exists(select 1 from private.order_v1_price_allocation_heads where order_id = p_order_id) then
    return jsonb_build_object('frozen', true, 'issue', null);
  end if;
  derived := private.order_v1_allocation_derive(p_order_id);
  return jsonb_build_object('frozen', false, 'issue', derived->>'issue');
end $function$

CREATE OR REPLACE FUNCTION private.pg_settlement_account_matches(p_query jsonb, p_job private.pg_settlement_imports)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare key text:=nullif(p_query->>'account','');begin
 if key is null then return p_job.integration='toss_payment';end if;
 if key='current' then return false;end if;
 if key!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise invalid_parameter_value using message='settlement_invalid_account';end if;
 return exists(select 1 from private.pg_settlement_accounts where id=key::uuid and integration=p_job.integration
  and billing_profile_id is not distinct from p_job.billing_profile_id and mid=p_job.mid and mode=p_job.mode);
end $function$

CREATE OR REPLACE FUNCTION private.pg_settlement_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare parent_id uuid;next_parent_id uuid;
begin
 if tg_table_name='pg_settlement_imports' then
  if tg_op='UPDATE' and (new.integration,new.billing_profile_id,new.mid,new.mode,new.scope_hash) is distinct from (old.integration,old.billing_profile_id,old.mid,old.mode,old.scope_hash) then raise check_violation using message='settlement_account_immutable';end if;if old.state='complete' then raise object_not_in_prerequisite_state using message='settlement_snapshot_immutable';end if;
 else
  parent_id:=case when tg_op='INSERT' then new.import_id else old.import_id end;
  if tg_op<>'DELETE' then next_parent_id:=new.import_id;end if;
  if exists(select 1 from private.pg_settlement_imports where id=any(array[parent_id,next_parent_id]) and state='complete') then
   raise object_not_in_prerequisite_state using message='settlement_snapshot_immutable';end if;
 end if;
 return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION private.pg_settlement_match_account(p_record jsonb, p_job private.pg_settlement_imports)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare attempt public.payment_attempts;binding private.payment_provider_bindings;begin
 select * into attempt from public.payment_attempts where provider='toss' and provider_order_id=p_record->>'orderId';
 if not found then return private.pg_settlement_match(p_record);end if;
 select * into binding from private.payment_provider_bindings where attempt_id=attempt.id;
 if found then
  if p_job.integration<>'toss_billing' or p_job.billing_profile_id<>binding.profile_id or p_job.mid<>binding.merchant_id or p_job.mode<>binding.environment
   or binding.integration<>'toss_billing' then return jsonb_build_object('state','mismatch','reason','integration_binding_mismatch');end if;
 elsif p_job.integration='toss_billing' then return jsonb_build_object('state','mismatch','reason','integration_binding_missing');end if;
 return private.pg_settlement_match(p_record);
end $function$

CREATE OR REPLACE FUNCTION private.pg_settlement_match(p_record jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare a public.payment_attempts;p public.payments;candidate_count integer;record_kind text;reason text;reference_number text;reference_total bigint;reference_user uuid;refund_count integer;refund_amount numeric;
begin
 record_kind:=case when p_record->'cancel'='null'::jsonb then 'approval' else 'cancel' end;
 select count(*) into candidate_count from public.payment_attempts where provider='toss' and provider_order_id=p_record->>'orderId';
 if candidate_count=0 then return jsonb_build_object('state','unlinked','reason','payment_not_found');end if;
 select * into a from public.payment_attempts where provider='toss' and provider_order_id=p_record->>'orderId';
 select * into p from public.payments where id=a.payment_id;
 if not found then return jsonb_build_object('state','unlinked','reason','payment_not_finalized');end if;
 if (select count(*)from public.payments where provider='toss' and payment_key=p_record->>'paymentKey')>1 then
  return jsonb_build_object('state','mismatch','reason','ambiguous_payment');end if;
 if p.provider<>'toss' or p.payment_key is distinct from p_record->>'paymentKey' or p.purpose<>a.purpose or p.ref_id is distinct from a.ref_id
  or p.user_id<>a.user_id or p.amount<>a.amount or a.currency<>p_record->>'currency' or a.state not in('approved','canceled') or p.status not in('paid','canceled','refunded') then
  return jsonb_build_object('state','mismatch','reason','payment_identity_mismatch');end if;
 if a.purpose='order' then select total,user_id,upper(left(id::text,8)) into reference_total,reference_user,reference_number from public.orders where id=a.ref_id;
 elsif a.purpose='ticket' then select total,user_id,upper(left(id::text,8)) into reference_total,reference_user,reference_number from public.ticket_orders where id=a.ref_id;
 else return jsonb_build_object('state','unlinked','reason','unsupported_purpose');end if;
 if reference_total is null or reference_total<>p.amount or reference_user<>p.user_id then return jsonb_build_object('state','mismatch','reason','reference_mismatch');end if;
 if record_kind='approval' then
  if (p_record->>'amount')::numeric<>p.amount then reason:='amount_mismatch';
  elsif not exists(select 1 from private.payment_provider_evidence e where e.payment_attempt_id=a.id and e.evidence_kind='confirm_approved'
   and e.provider_payment_key=p.payment_key and e.provider_transaction_id=p_record->>'transactionKey') then reason:='transaction_evidence_missing';end if;
 else
  if exists(select 1 from private.order_partial_cancellations pc where pc.payment_id=p.id and pc.state='completed'
   and pc.provider_transaction_key=p_record->>'transactionKey') then
   if (p_record#>>'{cancel,cancelAmount}')::numeric<>(select pc.refund_amount from private.order_partial_cancellations pc
     where pc.payment_id=p.id and pc.state='completed' and pc.provider_transaction_key=p_record->>'transactionKey') then reason:='refund_amount_mismatch';end if;
  elsif not exists(select 1 from private.payment_provider_evidence e where e.payment_attempt_id=a.id and e.evidence_kind='refund_approved'
   and e.provider_payment_key=p.payment_key and e.provider_transaction_id=p_record->>'transactionKey') then reason:='transaction_evidence_missing';
  else
   select count(*),sum(amount) into refund_count,refund_amount from public.refunds where payment_id=p.id and status='done';
   -- Current finalized refunds are whole-payment records. Do not guess which
   -- partial refund a repeated equal amount represents.
   if (select count(distinct e2.provider_transaction_id) from private.payment_provider_evidence e2 where e2.payment_attempt_id=a.id and e2.evidence_kind='refund_approved'
     and not exists(select 1 from private.order_partial_cancellations pc where pc.payment_id=p.id
       and pc.provider_transaction_key=e2.provider_transaction_id))<>1 then reason:='ambiguous_refund';
   elsif refund_count<>1 or (p_record#>>'{cancel,cancelAmount}')::numeric<>refund_amount then reason:='refund_amount_mismatch';end if;
  end if;
 end if;
 return jsonb_build_object('state',case when reason is null then 'matched' when reason='transaction_evidence_missing' then 'unlinked' else 'mismatch' end,'reason',coalesce(reason,'verified'),
  'purpose',a.purpose,'referenceId',a.ref_id,'orderNumber',reference_number);
end $function$

CREATE OR REPLACE FUNCTION private.pg_settlement_query(p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare first_date date;last_date date;
begin
 if jsonb_typeof(p_query) is distinct from 'object' or p_query->>'dateType' not in('soldDate','paidOutDate')
  or coalesce(p_query->>'startDate','')!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}$' or coalesce(p_query->>'endDate','')!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}$' then
  raise invalid_parameter_value using message='settlement_invalid_query';end if;
 first_date:=(p_query->>'startDate')::date;last_date:=(p_query->>'endDate')::date;
 if p_query->>'dateType' is null or last_date not between first_date and first_date+30 then raise invalid_parameter_value using message='settlement_invalid_query';end if;
 return jsonb_build_object('dateType',p_query->>'dateType','startDate',first_date::text,'endDate',last_date::text);
exception when datetime_field_overflow or invalid_datetime_format then raise invalid_parameter_value using message='settlement_invalid_query';
end $function$

CREATE OR REPLACE FUNCTION private.pg_settlement_report(p_query jsonb, p_export boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare q jsonb;job private.pg_settlement_imports;v_mode text;v_kind text;v_match text;v_search text;v_currency text;v_import uuid;
 v_page integer;v_size integer;v_total integer;v_transactions jsonb;v_totals jsonb;v_daily jsonb;v_fees jsonb;v_jobs jsonb;v_fingerprint text;
begin
 q:=private.pg_settlement_query(p_query);
 v_mode:=p_query->>'mode';v_kind:=coalesce(p_query->>'kind','all');v_match:=coalesce(p_query->>'match','all');
 v_search:=coalesce(p_query->>'query','');v_currency:=coalesce(p_query->>'currency','');
 if v_mode is null or v_mode not in('test','live') or v_kind not in('all','approval','cancel') or v_match not in('all','matched','unlinked','mismatch')
  or char_length(v_search)>100 or v_search~'[[:cntrl:]]' or (v_currency<>'' and v_currency!~'^[A-Z]{3}$')
  or coalesce(p_query->>'page','1')!~'^[0-9]{1,7}$' or coalesce(p_query->>'pageSize','20') not in('20','50','100')
  or (p_query->>'importId' is not null and p_query->>'importId'!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') then
  raise invalid_parameter_value using message='settlement_invalid_query';end if;
 v_page:=coalesce((p_query->>'page')::int,1);v_size:=coalesce((p_query->>'pageSize')::int,20);v_import:=(p_query->>'importId')::uuid;
 if v_page not between 1 and 1000000 then raise invalid_parameter_value using message='settlement_invalid_query';end if;
 select * into job from private.pg_settlement_imports where state='complete' and mode=v_mode and date_type=q->>'dateType' and private.pg_settlement_account_matches(p_query,pg_settlement_imports)
  and start_date=(q->>'startDate')::date and end_date=(q->>'endDate')::date and (v_import is null or id=v_import)
  order by completed_at desc,id desc limit 1;
 select coalesce(jsonb_agg(private.pg_settlement_job(recent.id) order by recent.started_at desc,recent.id desc),'[]'::jsonb) into v_jobs
 from(select id,started_at from private.pg_settlement_imports where actor_id=auth.uid() and mode=v_mode and date_type=q->>'dateType' and private.pg_settlement_account_matches(p_query,pg_settlement_imports)
  and start_date=(q->>'startDate')::date and end_date=(q->>'endDate')::date order by started_at desc,id desc limit 10)recent;
 -- This single relational statement provides every view of the exact same
 -- filtered immutable snapshot. Only whitelisted safe columns are projected.
 with filtered as materialized(
  select r.*,r.record as data,case when job.date_type='soldDate' then r.sold_date else r.paid_out_date end as report_date
  from private.pg_settlement_records r where r.import_id=job.id and (v_kind='all' or r.kind=v_kind)
   and (v_match='all' or r.match_state=v_match) and (v_currency='' or r.currency=v_currency)
   and (v_search='' or position(lower(v_search) in lower(coalesce(r.order_number,'')))>0
    or position(lower(v_search) in coalesce(r.reference_id::text,''))>0)
 ), money as materialized(
  select f.*,(data->>'amount')::numeric as amount,(data->>'interestFee')::numeric as interest_fee,
   coalesce((select sum((fee->>'fee')::numeric)from jsonb_array_elements(data->'fees')fee),0) as fee_amount,
   (data->>'supplyAmount')::numeric as supply_amount,(data->>'vat')::numeric as vat,(data->>'payOutAmount')::numeric as pay_out_amount,
   coalesce((data#>>'{cancel,cancelAmount}')::numeric,0) as cancel_amount from filtered f
 ), aggregates as(
  select currency,kind,report_date,count(*) as count,sum(amount) as amount,sum(interest_fee) as interest_fee,sum(fee_amount) as fee_amount,
   sum(supply_amount) as supply_amount,sum(vat) as vat,sum(pay_out_amount) as pay_out_amount,sum(cancel_amount) as cancel_amount,
   grouping(report_date) as is_total from money group by grouping sets((currency,kind),(currency,kind,report_date))
 ), rendered as(
  select is_total,report_date,currency,kind,jsonb_build_object('currency',currency,'kind',kind,'count',count,'amount',trim_scale(amount)::text,
   'interestFee',trim_scale(interest_fee)::text,'feeAmount',trim_scale(fee_amount)::text,'supplyAmount',trim_scale(supply_amount)::text,
   'vat',trim_scale(vat)::text,'payOutAmount',trim_scale(pay_out_amount)::text,'cancelAmount',trim_scale(cancel_amount)::text) value from aggregates
 ), fee_rows as(
  select f.currency,f.kind,fee->>'type' as type,count(distinct f.id) as count,trim_scale(sum((fee->>'fee')::numeric))::text as fee
  from filtered f cross join lateral jsonb_array_elements(f.data->'fees') fee group by f.currency,f.kind,fee->>'type'
 ), transactions as(
  select r.report_date,r.id,jsonb_build_object('id',r.id,'kind',r.kind,'currency',r.currency,'method',r.data->>'method',
   'amount',r.data->>'amount','interestFee',r.data->>'interestFee','fees',r.data->'fees','supplyAmount',r.data->>'supplyAmount',
   'vat',r.data->>'vat','payOutAmount',r.data->>'payOutAmount','cancelAmount',r.data#>>'{cancel,cancelAmount}',
   'approvedAt',r.data->>'approvedAt','soldDate',r.sold_date,'paidOutDate',r.paid_out_date,'canceledAt',r.data#>>'{cancel,canceledAt}',
   'matchState',r.match_state,'matchReason',r.match_reason,'purpose',r.purpose,'referenceId',r.reference_id,'orderNumber',r.order_number) as value
  from filtered r order by r.report_date desc,r.id limit case when p_export then 20000 else v_size end offset case when p_export then 0 else (v_page-1)*v_size end
 ) select (select count(*)from filtered),
  coalesce((select jsonb_agg(value order by report_date desc,id)from transactions),'[]'::jsonb),
  coalesce((select jsonb_agg(value order by currency,kind)from rendered where is_total=1),'[]'::jsonb),
  coalesce((select jsonb_agg(value||jsonb_build_object('date',report_date) order by report_date desc,currency,kind)from rendered where is_total=0),'[]'::jsonb),
  coalesce((select jsonb_agg(to_jsonb(fee_rows)order by currency,kind,type)from fee_rows),'[]'::jsonb)
 into v_total,v_transactions,v_totals,v_daily,v_fees;
 if job.id is not null then
  v_fingerprint:=encode(extensions.digest(jsonb_build_object('version',1,'importId',job.id,'kind',v_kind,'match',v_match,'currency',v_currency,'query',v_search)::text,'sha256'),'hex');
 end if;
 return jsonb_build_object('query',q,'coverage',case when job.id is null then 'uncollected' when job.record_count=0 then 'empty' else 'complete' end,
  'snapshot',private.pg_settlement_job(job.id),'jobs',v_jobs,'totals',v_totals,'daily',v_daily,'transactions',v_transactions,'fees',v_fees,
  'pagination',jsonb_build_object('page',case when p_export then 1 else v_page end,'pageSize',case when p_export then 20000 else v_size end,'total',v_total),'fingerprint',v_fingerprint);
end $function$

CREATE OR REPLACE FUNCTION private.pg_settlement_validate_record(p_record jsonb, p_job private.pg_settlement_imports)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare key text;value jsonb;fee jsonb;at_date date;
begin
 if jsonb_typeof(p_record) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_record))<>16
  or not p_record ?& array['mId','paymentKey','transactionKey','orderId','currency','method','amount','interestFee','fees','supplyAmount','vat','payOutAmount','approvedAt','soldDate','paidOutDate','cancel'] then
  raise invalid_parameter_value using message='settlement_invalid_record';end if;
 if p_record->>'mId' is distinct from p_job.mid or coalesce(p_record->>'paymentKey','')!~'^[!-~]{1,200}$'
  or coalesce(p_record->>'transactionKey','')!~'^[!-~]{1,64}$' or coalesce(p_record->>'orderId','')!~'^[A-Za-z0-9_-]{6,64}$'
  or coalesce(p_record->>'currency','')!~'^[A-Z]{3}$' or char_length(coalesce(p_record->>'method','')) not between 1 and 40
  or p_record->>'method'~'[[:cntrl:]]' or btrim(p_record->>'method')='' then raise invalid_parameter_value using message='settlement_invalid_record';end if;
 for key,value in select j.key,j.value from jsonb_each(p_record) j where j.key not in('fees','cancel') loop
  if jsonb_typeof(value)<>'string' then raise invalid_parameter_value using message='settlement_invalid_record';end if;
 end loop;
 foreach key in array array['amount','interestFee','supplyAmount','vat','payOutAmount'] loop
  if p_record->>key!~'^-?(0|[1-9][0-9]{0,17})(\.[0-9]{1,8})?$' or trim_scale((p_record->>key)::numeric)::text<>p_record->>key then
   raise invalid_parameter_value using message='settlement_invalid_record';end if;
 end loop;
 foreach key in array array['soldDate','paidOutDate'] loop
  if p_record->>key!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}$' then raise invalid_parameter_value using message='settlement_invalid_record';end if;
  at_date:=(p_record->>key)::date;
 end loop;
 at_date:=(p_record->>p_job.date_type)::date;
 if at_date not between p_job.start_date and p_job.end_date then raise invalid_parameter_value using message='settlement_invalid_record';end if;
 if p_record->>'approvedAt'!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
  raise invalid_parameter_value using message='settlement_invalid_record';end if;
 perform (p_record->>'approvedAt')::timestamptz;
 if jsonb_typeof(p_record->'fees') is distinct from 'array' or jsonb_array_length(p_record->'fees')>100 then raise invalid_parameter_value using message='settlement_invalid_record';end if;
 for fee in select * from jsonb_array_elements(p_record->'fees') loop
  if jsonb_typeof(fee) is distinct from 'object' or (select count(*)from jsonb_object_keys(fee))<>2
   or not fee ?& array['type','fee'] or jsonb_typeof(fee->'type') is distinct from 'string' or jsonb_typeof(fee->'fee') is distinct from 'string'
   or coalesce(fee->>'type','')!~'^[A-Z_]{1,40}$' or coalesce(fee->>'fee','')!~'^-?(0|[1-9][0-9]{0,17})(\.[0-9]{1,8})?$'
   or trim_scale((fee->>'fee')::numeric)::text<>fee->>'fee' then raise invalid_parameter_value using message='settlement_invalid_record';end if;
 end loop;
 if p_record->'cancel'<>'null'::jsonb then
  value:=p_record->'cancel';
  if jsonb_typeof(value) is distinct from 'object' or (select count(*)from jsonb_object_keys(value))<>3
   or not value ?& array['cancelAmount','canceledAt','transactionKey'] or jsonb_typeof(value->'cancelAmount') is distinct from 'string'
   or jsonb_typeof(value->'canceledAt') is distinct from 'string' or jsonb_typeof(value->'transactionKey') is distinct from 'string'
   or value->>'transactionKey' is distinct from p_record->>'transactionKey'
   or coalesce(value->>'cancelAmount','')!~'^-?(0|[1-9][0-9]{0,17})(\.[0-9]{1,8})?$'
   or trim_scale((value->>'cancelAmount')::numeric)::text<>value->>'cancelAmount'
   or coalesce(value->>'canceledAt','')!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
   raise invalid_parameter_value using message='settlement_invalid_record';end if;
  perform (value->>'canceledAt')::timestamptz;
 end if;
exception when data_exception then raise invalid_parameter_value using message='settlement_invalid_record';
end $function$

CREATE OR REPLACE FUNCTION private.place_goods_transaction(p_actor uuid, p_source jsonb, p_selection jsonb, p_address jsonb, p_quote_id uuid, p_checkout_key uuid, p_payment_method public.order_payment_method)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<transaction_place>>
declare selection jsonb;address jsonb;existing private.order_goods_transactions;quoted private.goods_transaction_quotes;calculation jsonb;
 order_id uuid;at_time timestamptz;expires timestamptz;request_salt uuid:=gen_random_uuid();receipt jsonb;totals jsonb;line jsonb;coupon jsonb;
 raw_group jsonb;component jsonb;shipment_id uuid;shipping_snapshot jsonb;reserved_credit bigint;item_id uuid;delivery_terms jsonb;
begin
 perform private.lock_goods_transaction_source(p_actor,p_source);
 if p_quote_id is null or p_checkout_key is null or p_payment_method is null then raise invalid_parameter_value using message='invalid_transaction_place';end if;
 selection:=private.normalize_goods_transaction_selection(p_selection);address:=private.normalize_goods_transaction_address(p_address);
 -- Durable success replay is intentionally before quote expiry/PII cleanup,
 -- current cart, current source lifecycle, and present-day price calculations.
 select * into existing from private.order_goods_transactions where actor_id=p_actor and checkout_key=p_checkout_key;
 if found then
  if existing.quote_id<>p_quote_id or existing.source_kind<>p_source->>'kind' or existing.source_id<>(p_source->>'id')::uuid
   or existing.source_revision<>p_source->>'revision' or existing.request_digest is distinct from
    private.goods_transaction_request_digest(existing.request_salt,p_source,selection,address,p_quote_id,p_payment_method) then
   raise sqlstate 'PT409' using message='checkout_key_conflict';end if;
  return existing.order_id;
 end if;
 if exists(select 1 from public.orders where user_id=p_actor and checkout_key=p_checkout_key) then raise sqlstate 'PT409' using message='checkout_key_conflict';end if;
 perform private.assert_goods_transaction_actor(p_actor);
 select * into quoted from private.goods_transaction_quotes where id=p_quote_id and actor_id=p_actor for update;
 if not found or quoted.source is distinct from p_source or quoted.selection is distinct from selection or quoted.address is distinct from address then
  raise sqlstate 'PT409' using message='transaction_quote_changed';end if;
 if quoted.order_id is not null then raise sqlstate 'PT409' using message='transaction_quote_already_used';end if;
 if quoted.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='transaction_quote_expired';end if;
 if p_source->>'kind'='gift' and to_regprocedure('private.bind_goods_transaction_delivery_snapshot(uuid,uuid,jsonb,jsonb,jsonb)') is null then
  raise check_violation using message='gift_delivery_owner_not_ready';end if;
 expires:=case when p_payment_method='bank_transfer' then clock_timestamp()+interval '24 hours' else clock_timestamp()+interval '15 minutes' end;
 insert into public.orders(user_id,status,total,shipping_fee,address,expires_at,checkout_key,payment_method,calculation_version)
  values(p_actor,'pending',0,0,case when p_source->>'kind'='gift' or address->>'kind'='none' then null else address end,expires,p_checkout_key,p_payment_method,2) returning id into order_id;
 perform private.assert_first_purchase_checkout(p_actor,order_id);
 if quoted.user_coupon_ids is null then perform private.lock_goods_transaction_catalog(p_actor,selection,quoted.user_coupon_id);
 else perform private.lock_goods_transaction_combined_catalog(p_actor,selection,quoted.user_coupon_ids);end if;
 perform private.assert_goods_transaction_runtime();
 at_time:=clock_timestamp();
 if quoted.expires_at<=at_time then raise sqlstate 'PT409' using message='transaction_quote_expired';end if;
 if quoted.user_coupon_ids is null then
 calculation:=private.calculate_goods_transaction_locked(p_actor,selection,address,quoted.delivery_choices,quoted.user_coupon_id,quoted.store_credit_amount,at_time,quoted.line_ids,order_id);
 else calculation:=private.calculate_goods_transaction_combined_locked(p_actor,selection,address,quoted.delivery_choices,quoted.user_coupon_ids,quoted.store_credit_amount,at_time,quoted.line_ids,order_id);end if;
 if calculation->>'state'<>'calculated' or private.goods_transaction_calculation_contract(calculation) is distinct from private.goods_transaction_calculation_contract(quoted.calculation) then
  raise sqlstate 'PT409' using message='transaction_quote_changed';end if;
 if not (calculation#>>array['display','paymentMethods',case when p_payment_method='bank_transfer' then 'bankTransfer' else 'card' end])::boolean then
  raise check_violation using message='transaction_payment_method_unavailable';end if;
 if p_source->>'kind'='gift' and exists(select 1 from jsonb_array_elements(calculation->'lines')l where l#>>'{fulfillmentTermsSnapshot,mode}'='digital') then raise check_violation using message='digital_gift_unavailable';end if;
 totals:=calculation#>'{display,totals}';receipt:=jsonb_build_object('orderId',order_id,'quoteId',p_quote_id,'display',calculation->'display');
 insert into private.order_goods_transactions(order_id,actor_id,source_kind,source_id,source_revision,quote_id,checkout_key,request_digest,request_salt,original_receipt)
  values(order_id,p_actor,p_source->>'kind',(p_source->>'id')::uuid,p_source->>'revision',p_quote_id,p_checkout_key,
   private.goods_transaction_request_digest(request_salt,p_source,selection,address,p_quote_id,p_payment_method),request_salt,receipt);
 update private.goods_transaction_quotes set order_id=transaction_place.order_id where id=p_quote_id;
 if p_source->>'kind'='gift' then
  perform private.bind_goods_transaction_delivery_snapshot(order_id,p_actor,p_source,address,calculation->'shippingRaw');
 end if;
 for line in select value from jsonb_array_elements(calculation->'lines') loop
  if line->>'supplySource'='stock' then perform private.change_goods_variant_stock(line->>'goodId',(line->>'variantId')::uuid,-(line->>'qty')::bigint);end if;
  item_id:=(line->>'lineId')::uuid;
  insert into public.order_items(id,order_id,good_id,variant_id,qty,unit_price,good_name_snapshot,good_ip_id_snapshot,
   regular_unit_price_snapshot,price_period_id,price_evaluated_at,sales_policy_snapshot,supply_source,preorder_policy_id,preorder_expected_ship_date,
   preorder_snapshot,custom_inputs_snapshot,volume_unit_discount,volume_discount_total,volume_discount_snapshot,production_terms_snapshot,fulfillment_terms_snapshot)
  values(item_id,order_id,line->>'goodId',(line->>'variantId')::uuid,(line->>'qty')::integer,(line->>'unitPrice')::integer,
   line->>'goodName',line->>'goodIpId',(line->>'regularUnitPrice')::integer,(line->>'pricePeriodId')::uuid,at_time,line->'salesPolicySnapshot',
   line->>'supplySource',(line->>'preorderPolicyId')::uuid,(line->>'preorderExpectedShipDate')::date,
   case when line->>'supplySource'='preorder' then jsonb_build_object('version',1,'policyId',line->'preorderPolicyId','policyRevision',line->'preorderPolicyRevision',
    'startsAt',line->'preorderStartsAt','endsAt',line->'preorderEndsAt','expectedShipDate',line->'preorderExpectedShipDate') end,
   nullif(line->'customInputsSnapshot','null'::jsonb),(line->>'volumeUnitDiscount')::bigint,(line->>'volumeDiscountTotal')::bigint,
   jsonb_build_object('calculationVersion',2,'policy',line->'volumePolicySnapshot','applied',line->>'volumePolicyId' is not null),nullif(line->'productionTermsSnapshot','null'::jsonb),nullif(line->'fulfillmentTermsSnapshot','null'::jsonb));
  if line->>'supplySource'='preorder' then perform private.reserve_goods_preorder_item(item_id,at_time);end if;
  insert into private.order_price_allocations(order_item_id,order_id,calculation_version,subtotal,volume_discount,net_subtotal,coupon_discount,store_credit_discount,paid_goods_total)
   values(item_id,order_id,2,(line->>'subtotal')::bigint,(line->>'volumeDiscountTotal')::bigint,(line->>'netSubtotal')::bigint,
    (line->>'couponDiscount')::bigint,(line->>'storeCreditDiscount')::bigint,(line->>'paidGoodsTotal')::bigint);
 end loop;
 for coupon in select value from jsonb_array_elements(case when calculation ? 'coupons' then calculation->'coupons' when quoted.user_coupon_id is not null then jsonb_build_array(calculation->'coupon') else '[]'::jsonb end) loop
  perform private.reserve_first_purchase_coupon(order_id,p_actor,coupon->>'couponCode');
  update public.user_coupons set status='used',used_at=at_time,used_order_id=order_id where id=(coupon->>'userCouponId')::uuid and user_id=p_actor and status<>'used';
  if not found then raise check_violation using message='coupon_already_used';end if;
  insert into public.coupon_redemptions(user_coupon_id,coupon_code,user_id,order_id,discount_amount,eligible_subtotal,terms_snapshot,benefit_kind,application_index)
   values((coupon->>'userCouponId')::uuid,coupon->>'couponCode',p_actor,order_id,(coupon->>'discount')::bigint,(coupon->>'eligibleSubtotal')::bigint,coupon->'termsSnapshot',coalesce(coupon->>'benefitKind','goods'),coalesce((coupon->>'applicationIndex')::integer,1));
 end loop;
 reserved_credit:=private.reserve_order_store_credits_explicit(order_id,p_actor,(totals->>'netGoodsTotal')::bigint,(totals->>'couponDiscountTotal')::bigint,
  (totals->>'prepaidShippingTotal')::bigint,quoted.store_credit_amount,at_time);
 if reserved_credit<>(totals->>'storeCreditTotal')::bigint then raise check_violation using message='transaction_credit_snapshot_mismatch';end if;
 shipping_snapshot:=private.goods_transaction_public_shipping(p_source->>'kind',calculation->'shippingRaw');
 update public.orders set total=(totals->>'onlineTotal')::bigint,shipping_fee=(totals->>'prepaidShippingTotal')::bigint,
  store_credit_policy_snapshot=nullif(calculation->'creditPolicy','null'::jsonb),
  shipping_coupon_discount_total=coalesce((totals->>'shippingCouponDiscountTotal')::bigint,0),volume_discount_total=(totals->>'volumeDiscountTotal')::bigint,discount_total=(totals->>'couponDiscountTotal')::bigint,
  store_credit_total=reserved_credit,shipping_collect_total=(totals->>'collectShippingTotal')::bigint,shipping_fee_breakdown=shipping_snapshot where id=order_id;
 perform private.create_order_shipments(order_id);
 for raw_group in select value from jsonb_array_elements(calculation->'shippingRaw') loop
  update public.order_shipments set shipping_collect_fee=(raw_group->>'collectFee')::bigint
   where order_shipments.order_id=transaction_place.order_id and origin_id=(raw_group->>'originId')::uuid and fulfillment_partition=coalesce(raw_group->>'deliveryMethod','parcel') returning id into shipment_id;
  for component in select value from jsonb_array_elements(raw_group->'components') loop
   select value into delivery_terms from jsonb_array_elements(raw_group->'deliveryTerms') where value->>'goodId'=component->>'goodId';
   insert into private.shipping_charge_components(order_id,shipment_id,good_id,origin_id,calculation_version,payment_mode,base_fee,regional_fee,total_fee,installation_fee,shipping_coupon_discount,
    delivery_policy_id,collect_contract_id,terms_snapshot)
   values(order_id,shipment_id,component->>'goodId',(raw_group->>'originId')::uuid,2,component->>'paymentMode',(component->>'baseFee')::bigint,
    (component->>'regionalFee')::bigint,(component->>'totalFee')::bigint,coalesce((component->>'installationFee')::bigint,0),coalesce((component->>'shippingCouponDiscount')::bigint,0),(component->>'deliveryPolicyId')::uuid,(raw_group->>'collectContractId')::uuid,
    jsonb_build_object('deliveryTerms',delivery_terms,'regionalPolicyId',raw_group->'policyId','regionalPolicyVersion',raw_group->'policyVersion',
     'regionStatus',raw_group->'regionStatus','collectContract',raw_group->'collectContractSnapshot'));
  end loop;
  if (raw_group->>'collectFee')::bigint>0 then
   insert into private.shipping_collect_obligations(shipment_id,order_id,amount,contract_snapshot)
    values(shipment_id,order_id,(raw_group->>'collectFee')::bigint,raw_group->'collectContractSnapshot');
   insert into private.shipping_collect_events(operation_id,shipment_id,event,amount,evidence)
    values(gen_random_uuid(),shipment_id,'planned',(raw_group->>'collectFee')::bigint,jsonb_build_object('orderId',order_id,'quoteId',p_quote_id));
  end if;
 end loop;
 if not private.goods_order_snapshot_matches(order_id,(totals->>'onlineTotal')::bigint,(totals->>'prepaidShippingTotal')::bigint) then
  raise check_violation using message='transaction_order_snapshot_mismatch';end if;
 if quoted.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='transaction_quote_expired';end if;
 perform private.assert_order_goods_sale_period(order_id);
 if p_payment_method='bank_transfer' then
  perform public.prepare_goods_payment_attempt(p_actor,order_id,'bank_transfer');
  insert into public.notifications(user_id,type,title,body,link_path,source_type,source_id,dedupe_key)
   values(p_actor,'order_bank_transfer_pending','입금 안내를 확인해주세요',format('%s원을 기한 안에 입금해주세요. 입금자명 끝에 주문코드 %s를 붙이면 확인이 빨라집니다.',
    to_char((totals->>'onlineTotal')::bigint,'FM999,999,999,999,999,999'),private.bank_transfer_deposit_code(order_id)),
    '/checkout/'||order_id::text,'order',order_id::text,'order:bank_transfer_pending:'||order_id::text) on conflict(user_id,dedupe_key) do nothing;
 end if;
 return order_id;
end $function$

CREATE OR REPLACE FUNCTION private.place_order_before_shipments(p_address jsonb, p_checkout_key uuid, p_payment_method public.order_payment_method)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  -- 결제사 최소 결제액(20260813242000 가드·lib/coupons.ts MIN_PAYABLE_TOTAL와 동치).
  -- 할인이 총액을 이 밑으로 내리면 가드가 주문 전체를 롤백하므로, 여기서 캡한다.
  c_min_payable_total constant bigint := 1000;
  v_user uuid := (select auth.uid());
  v_order uuid;
  v_existing_address jsonb;
  v_existing_payment_method public.order_payment_method;
  v_expires_at timestamptz;
  v_subtotal bigint := 0;
  v_shipping_fee bigint := 0;
  v_item_count integer := 0;
  v_recipient_name text;
  v_phone text;
  v_postal_code text;
  v_address1 text;
  v_optional text;
  v_selected_coupon uuid;
  v_coupon_eval record;
  v_discount bigint := 0;
  v_store_credit bigint := 0;
  r record;
  v_variant public.goods_variants;
  v_price record;
  v_price_at timestamptz;
  v_limit_good public.goods;
  v_good_qty bigint;
  v_last_good_id text;
  v_quantity_error text;
  v_supply record;
  v_new_order_item uuid;
  v_custom_inputs_snapshot jsonb;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if not exists (
    select 1
    from public.profiles as profile
    join auth.users as auth_user on auth_user.id = profile.id
    where profile.id = v_user
      and nullif(btrim(coalesce(profile.email, auth_user.email)), '') is not null
      and nullif(btrim(profile.nickname), '') is not null
      and profile.birth_date is not null
      and profile.birth_date <= current_date
      and profile.onboarded_at is not null
      and profile.consents ->> 'terms' = 'true'
      and profile.consents ->> 'privacy' = 'true'
  ) then
    raise insufficient_privilege using message = 'onboarding required';
  end if;

  if p_checkout_key is null then
    raise not_null_violation using message = 'checkout key required';
  end if;

  if p_address is null or jsonb_typeof(p_address) <> 'object' then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if not (p_address ?& array['recipientName', 'phone', 'postalCode', 'address1'])
     or exists (
       select 1
       from jsonb_object_keys(p_address) as address_key(key)
       where address_key.key not in (
         'recipientName', 'phone', 'postalCode', 'address1', 'address2', 'deliveryNote'
       )
     )
     or exists (
       select 1
       from jsonb_each(p_address) as address_value(key, value)
       where jsonb_typeof(address_value.value) <> 'string'
     ) then
    raise check_violation using message = 'invalid checkout address';
  end if;

  v_recipient_name := p_address ->> 'recipientName';
  v_phone := p_address ->> 'phone';
  v_postal_code := p_address ->> 'postalCode';
  v_address1 := p_address ->> 'address1';

  if v_recipient_name <> btrim(v_recipient_name, E' \t\n\r\f\v')
     or length(v_recipient_name) not between 1 and 50
     or v_phone !~ '^[0-9]{8,15}$'
     or v_postal_code !~ '^[0-9]{5}$'
     or v_address1 <> btrim(v_address1, E' \t\n\r\f\v')
     or length(v_address1) not between 1 and 200 then
    raise check_violation using message = 'invalid checkout address';
  end if;

  if p_address ? 'address2' then
    v_optional := p_address ->> 'address2';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  if p_address ? 'deliveryNote' then
    v_optional := p_address ->> 'deliveryNote';
    if v_optional <> btrim(v_optional, E' \t\n\r\f\v') or length(v_optional) > 200 then
      raise check_violation using message = 'invalid checkout address';
    end if;
  end if;

  -- 같은 사용자의 다른 탭 주문을 직렬화한다. 동일 키 재시도는 먼저 생성된
  -- 주문을 반환하고, 다른 키는 첫 주문이 비운 장바구니를 확인하게 된다.
  -- 쿠폰 적용·해제도 같은 잠금을 잡으므로 선택 교체와 소비가 경합하지 않는다.
  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  select orders.id, orders.address, orders.payment_method
    into v_order, v_existing_address, v_existing_payment_method
  from public.orders
  where orders.user_id = v_user
    and orders.checkout_key = p_checkout_key;

  if found then
    -- 같은 checkout key로 결제수단만 바꿔 다시 부르면 24시간 선점을 15분 주문에
    -- 덧씌우거나 그 반대가 된다. 주소와 같은 등급의 충돌로 막는다.
    if v_existing_address is distinct from p_address
      or v_existing_payment_method is distinct from p_payment_method
    then
      raise unique_violation using message = 'checkout key conflict';
    end if;
    return v_order;
  end if;

  if p_payment_method is null then
    raise invalid_parameter_value using message='payment method required';
  end if;

  -- 카드 15분 · 무통장 24시간. 무통장은 사람이 은행 앱을 열고 이체할 시간을
  -- 줘야 해서 선점 창이 길고, 그만큼 재고가 오래 묶인다 — 한정 드롭은
  -- goods.allow_bank_transfer로 아예 차단한다(ADR-0007).
  v_expires_at := case
    when p_payment_method = 'bank_transfer' then now() + interval '24 hours'
    else now() + interval '15 minutes'
  end;

  insert into public.orders (
    user_id, status, total, shipping_fee, address, expires_at, checkout_key, payment_method
  )
  values (v_user, 'pending', 0, 0, p_address, v_expires_at, p_checkout_key, p_payment_method)
  returning id into v_order;

  perform private.assert_first_purchase_checkout(v_user,v_order);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('cart:'||v_user::text,0));
  -- This timestamp is fixed after the member/cart locks. Waiting for a competing
  -- checkout cannot select a stale pre-lock clock value. Each order has one price
  -- boundary, including all its coupon and shipping calculations.
  v_price_at:=clock_timestamp();
  -- Lock parents before opening the cart cursor. Locking the same parent in
  -- that cursor while stock triggers update it can make PostgreSQL skip rows
  -- after a cursor fetch boundary. Cart rows themselves remain locked below.
  perform 1 from public.goods good
    join (select distinct source.good_id from private.checkout_source_lines(v_user,false) as source) selected on selected.good_id=good.id
    order by good.id for update of good;
  for r in
    select
      cart.cart_item_id,
      cart.good_id,
      cart.variant_id,
      cart.qty,
      cart.input_revision,
      cart.input_values,
      good.price,
      good.stock,
      good.stock_qty,
      good.name,
      good.ip_id,
      good.allow_bank_transfer,
      good.allow_card_payment,
      good.sale_restriction,
      good.published_at,
      good.archived_at,
      good.option_sale_mode
    -- 주문 줄 원본(ADR-0030): 장바구니 전체·선택 줄·바로구매 초안. 장바구니 행은 원본 함수가 이 순서로 잠근다.
    from private.checkout_source_lines(v_user,true) as cart
    join public.goods as good on good.id = cart.good_id
    order by cart.good_id, cart.variant_id, cart.cart_item_id
  loop
    -- The locked good fixes its parent association. Keep the IP SHARE lock until
    -- this order commits, serializing new purchases with an unpublish UPDATE.
    perform private.assert_ip_purchasable(r.ip_id);
    if r.published_at is null or r.archived_at is not null then
      raise check_violation using message='catalog_item_unavailable';
    end if;
    select * into v_variant from public.goods_variants where id=r.variant_id and good_id=r.good_id for update;
    if not found or v_variant.archived_at is not null then raise check_violation using message='catalog_item_unavailable'; end if;
    v_item_count := v_item_count + 1;
    v_custom_inputs_snapshot:=private.resolve_goods_custom_inputs(r.good_id,r.input_revision,r.input_values);

    -- A variant may have several buyer-input lines. Check a good before its
    -- first line is consumed, summing every selected line and optional add-on.
    if v_last_good_id is distinct from r.good_id then
      select * into v_limit_good from public.goods where id=r.good_id;
      select sum(source.qty::bigint) into v_good_qty from private.checkout_source_lines(v_user,false) as source where source.good_id=r.good_id;
      v_quantity_error:=private.check_goods_purchase_quantity(v_limit_good,v_user,v_good_qty,true);
      if v_quantity_error is not null then
        raise check_violation using message=v_quantity_error||': '||r.good_id;
      end if;
      v_last_good_id:=r.good_id;
    end if;
    -- 랜덤 판매 굿즈(D5②): 장바구니 키 옵션 대신 같은 굿즈의 활성 옵션 풀에서 배정한다.
    -- 굿즈 단위 수량 판정은 위에서 끝났고, 결제수단·판매 제한 판정은 일반 줄과 같다.
    if r.option_sale_mode = 'random' then
      if r.stock = 'soldout' then
        raise check_violation using message = format('out of stock: %s', r.good_id);
      end if;
      if p_payment_method = 'card' and not r.allow_card_payment then
        raise check_violation using message=format('card payment blocked: %s',r.good_id);
      end if;
      if p_payment_method = 'bank_transfer' and not r.allow_bank_transfer then
        raise check_violation using message = format('bank transfer blocked: %s', r.good_id);
      end if;
      if r.sale_restriction <> 'none' then
        raise check_violation using message = format('restricted good blocked: %s', r.good_id);
      end if;
      v_subtotal := v_subtotal + private.allocate_random_option_items(v_order, v_user, r.cart_item_id, r.good_id, r.variant_id, r.qty,
        v_price_at, v_custom_inputs_snapshot,
        jsonb_build_object('version',1,'allowCardPayment',r.allow_card_payment,'allowBankTransfer',r.allow_bank_transfer,
          'orderQuantityLimitEnabled',v_limit_good.order_quantity_limit_enabled,
          'minOrderQty',v_limit_good.min_order_qty,'maxOrderQty',v_limit_good.max_order_qty,
          'memberPurchaseLimitEnabled',v_limit_good.member_purchase_limit_enabled,
          'memberLifetimeQtyLimit',v_limit_good.member_lifetime_qty_limit));
      if not (p_payment_method = 'card' and private.cart_retention_active()) then
        delete from public.cart_items
        where user_id = v_user
          and id = r.cart_item_id;
      end if;
      continue;
    end if;
    select * into v_price from private.resolve_goods_variant_price(v_variant.id,v_price_at);


    select * into v_supply from private.resolve_goods_variant_supply(v_variant.id,v_price_at);
    if r.stock = 'soldout' then
      raise check_violation using message = format('out of stock: %s', r.good_id);
    end if;
    if v_supply.mode='preorder' then
      if v_supply.state<>'open' then raise check_violation using message='preorder_sale_not_open'; end if;
      if v_supply.available_qty<r.qty then raise check_violation using message='preorder_capacity_exceeded'; end if;
    elsif v_supply.available_qty<r.qty then
      raise check_violation using message = format('out of stock: %s', r.good_id);
    end if;

    if p_payment_method = 'card' and not r.allow_card_payment then
      raise check_violation using message=format('card payment blocked: %s',r.good_id);
    end if;

    if p_payment_method = 'bank_transfer' and not r.allow_bank_transfer then
      raise check_violation using message = format('bank transfer blocked: %s', r.good_id);
    end if;

    -- 성인 상품은 유효한 성인 인증(ADR-0024)이 있는 계정만 주문한다. 그 밖의 판매
    -- 제한 유형은 계속 막는다. 결제수단과 무관한 상품 축이라 무통장 검사와 별개다.
    if r.sale_restriction = 'adult' and not private.adult_verification_valid(v_user) then
      raise check_violation using message = format('adult verification required: %s', r.good_id);
    elsif r.sale_restriction not in ('none', 'adult') then
      raise check_violation using message = format('restricted good blocked: %s', r.good_id);
    end if;

    if v_supply.mode='stock' then
      perform private.change_goods_variant_stock(r.good_id, r.variant_id, -r.qty::bigint);
    end if;

    insert into public.order_items (
      order_id,
      good_id,
      variant_id,
      qty,
      unit_price,
      good_name_snapshot,
      good_ip_id_snapshot,
      regular_unit_price_snapshot,
      price_period_id,
      price_evaluated_at,
      sales_policy_snapshot,
      supply_source,
      preorder_policy_id,
      preorder_expected_ship_date,
      preorder_snapshot,
      custom_inputs_snapshot
    )
    values (
      v_order,
      r.good_id,
      r.variant_id,
      r.qty,
      v_price.effective_price,
      r.name,
      r.ip_id,
      v_price.regular_price,
      v_price.price_period_id,
      v_price_at,
      jsonb_build_object('version',1,'allowCardPayment',r.allow_card_payment,'allowBankTransfer',r.allow_bank_transfer,
        'orderQuantityLimitEnabled',v_limit_good.order_quantity_limit_enabled,
        'minOrderQty',v_limit_good.min_order_qty,'maxOrderQty',v_limit_good.max_order_qty,
        'memberPurchaseLimitEnabled',v_limit_good.member_purchase_limit_enabled,
        'memberLifetimeQtyLimit',v_limit_good.member_lifetime_qty_limit),
      v_supply.mode,
      v_supply.policy_id,
      v_supply.expected_ship_date,
      case when v_supply.mode='preorder' then jsonb_build_object('version',1,'policyId',v_supply.policy_id,
        'policyRevision',v_supply.policy_revision,'startsAt',v_supply.starts_at,'endsAt',v_supply.ends_at,
        'expectedShipDate',v_supply.expected_ship_date) end,
      v_custom_inputs_snapshot
    ) returning id into v_new_order_item;
    if v_supply.mode='preorder' then
      perform private.reserve_goods_preorder_item(v_new_order_item,v_price_at);
    end if;

    -- 조회 시 잠근 스냅샷 행만 지운다. 동시에 새로 담긴 다른 상품까지
    -- 마지막 broad delete가 없애지 않도록 상품 단위로 소비한다.
    -- 카드 장바구니 주문은 결제 확정 때 장바구니에서 뺀다(ADR-0026).
    if not (p_payment_method = 'card' and private.cart_retention_active()) then
      delete from public.cart_items
      where user_id = v_user
        and id = r.cart_item_id;
    end if;

    v_subtotal := v_subtotal + (v_price.effective_price::bigint * r.qty::bigint);
  end loop;

  if v_item_count = 0 then
    raise check_violation using message = 'cart empty';
  end if;

  -- Shipping uses the period-adjusted item subtotal before coupon/credit deductions.
  -- Its order-item inputs already contain the immutable effective price.
  v_shipping_fee := private.goods_shipping_fee_for(v_order);

  -- 카트에 적용해 둔 쿠폰을 여기서 최종 검증하고 소비한다. 조건 미달이면 주문
  -- 전체를 거부한다 — 할인을 기대한 사용자를 조용히 정가로 결제시키지 않는다.
  -- 장바구니·선택 주문은 장바구니 쿠폰 선택, 바로구매는 주문서에서 고른 쿠폰이다(ADR-0030).
  v_selected_coupon := private.checkout_source_coupon(v_user);

  if v_selected_coupon is not null then
    -- 상태 전이 전에 보유 행을 잠근다. 같은 유저는 advisory lock으로 이미
    -- 직렬화되어 있고, 이 잠금은 향후 다른 경로가 생겨도 이중 사용을 막는 안전벨트다.
    perform held.id
    from public.user_coupons as held
    where held.id = v_selected_coupon
    for update;

    select * into v_coupon_eval
    from private.evaluate_order_user_coupon(v_selected_coupon, v_user, v_order);
    if v_coupon_eval.o_reason is not null then
      raise check_violation using message = v_coupon_eval.o_reason;
    end if;
    -- 결제사 최소 결제액을 지키도록 할인을 캡한다 — 전액 쿠폰이 주문을
    -- 결제 불가(총액 < 1,000원)로 만들면 혜택이 주문 실패로 둔갑한다.
    v_discount := least(
      v_coupon_eval.o_discount,
      greatest(0, v_subtotal + v_shipping_fee - c_min_payable_total)
    );

    if v_discount<=0 then raise check_violation using message='coupon_no_discount'; end if;
    perform private.reserve_first_purchase_coupon(v_order,v_user,v_coupon_eval.o_coupon_code);

    update public.user_coupons
    set status = 'used',
        used_at = now(),
        used_order_id = v_order
    where id = v_selected_coupon;

    insert into public.coupon_redemptions (
      user_coupon_id, coupon_code, user_id, order_id, discount_amount, eligible_subtotal, terms_snapshot
    )
    values (
      v_selected_coupon, v_coupon_eval.o_coupon_code, v_user, v_order, v_discount, v_coupon_eval.o_eligible_subtotal, v_coupon_eval.o_terms_snapshot
    );

    -- 소비한 선택만 지운다. 주문 진행 중 다른 탭이 교체한 새 선택은 남는다.
    if not (p_payment_method = 'card' and private.cart_retention_active()) then
      delete from public.cart_coupon_selections
      where user_id = v_user
        and user_coupon_id = v_selected_coupon;
    end if;
  end if;

  v_store_credit := private.reserve_order_store_credits(v_order,v_user,v_subtotal,v_discount,v_shipping_fee);

  update public.orders
  set total = v_subtotal + v_shipping_fee - v_discount - v_store_credit,
      shipping_fee = v_shipping_fee,
      store_credit_total = v_store_credit,
      discount_total = v_discount
  where id = v_order;

  -- 무통장에는 결제사 왕복이 없다. 그래서 원장 anchor(payment_attempts)를 여기서
  -- 바로 연다 — 없으면 운영자가 입금을 확인할 대상 자체가 없고, "결제 준비" 버튼을
  -- 눌러야 생기는 구조는 구매자가 이미 이체한 뒤에도 확인이 안 되는 창을 만든다.
  -- 새 함수를 두지 않고 카드와 같은 prepare를 부른다: 소유권·금액·스냅샷·정지
  -- 계정 검사가 한 곳에만 있어야 한다.
  if p_payment_method = 'bank_transfer' then
    perform public.prepare_goods_payment_attempt(v_user, v_order, 'bank_transfer');
  end if;

  -- 무통장 주문은 만든 순간이 안내 시점이다. 금액·입금자명 코드·기한이 모두
  -- 정해졌고, 이 알림을 놓치면 구매자는 어디로 얼마를 보낼지 알 수 없다.
  if p_payment_method = 'bank_transfer' then
    insert into public.notifications (
      user_id, type, title, body, link_path, source_type, source_id, dedupe_key
    )
    values (
      v_user,
      'order_bank_transfer_pending',
      '입금 안내를 확인해주세요',
      format(
        '%s원을 기한 안에 입금해주세요. 입금자명 끝에 주문코드 %s를 붙이면 확인이 빨라집니다.',
        to_char(v_subtotal + v_shipping_fee - v_discount - v_store_credit, 'FM999,999,999'),
        private.bank_transfer_deposit_code(v_order)
      ),
      '/checkout/' || v_order::text,
      'order',
      v_order::text,
      'order:bank_transfer_pending:' || v_order::text
    )
    on conflict (user_id, dedupe_key) do nothing;
  end if;

  perform private.assert_order_goods_sale_period(v_order);
  return v_order;
end;
$function$

CREATE OR REPLACE FUNCTION private.play_game_without_catalog_guard(p_game_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user uuid := (select auth.uid());
  v_game record;
  v_pool record;
  v_today date;
  v_count integer;
  v_last jsonb;
  v_play uuid;
  v_idem text;
  v_seed text;
  v_cards jsonb;
  v_result jsonb;
begin
  if v_user is null then
    raise exception 'auth required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'play_game:' || v_user::text || ':' || p_game_id,
      0
    )
  );

  select game.id,
         game.reward_pool_id,
         game.per_user_daily_limit,
         game.active_from,
         game.active_to
    into v_game
  from public.games as game
  where game.id = p_game_id
  for share;

  if v_game.id is null then
    raise exception 'game not found';
  end if;

  if now() < v_game.active_from
    or (v_game.active_to is not null and now() >= v_game.active_to)
  then
    raise exception 'game not active';
  end if;

  if v_game.reward_pool_id is null then
    raise exception 'game has no reward pool';
  end if;

  v_today := (now() at time zone 'Asia/Seoul')::date;

  select count(*)
    into v_count
  from public.game_plays
  where game_id = p_game_id
    and user_id = v_user
    and (created_at at time zone 'Asia/Seoul')::date = v_today;

  if v_count >= v_game.per_user_daily_limit then
    select result
      into v_last
    from public.game_plays
    where idempotency_key = 'game_play:' || p_game_id || ':' || v_user::text || ':'
      || to_char(v_today, 'YYYY-MM-DD') || ':' || v_count;

    if v_last is null then
      raise exception 'daily limit state corrupted';
    end if;

    return v_last;
  end if;

  select pool.id, pool.active_from, pool.active_to
    into v_pool
  from public.card_pools as pool
  where pool.id = v_game.reward_pool_id
  for share;

  if v_pool.id is null
    or now() < v_pool.active_from
    or (v_pool.active_to is not null and now() >= v_pool.active_to)
  then
    raise exception 'reward_pool_not_active' using errcode = '55000';
  end if;

  v_play := extensions.gen_random_uuid();
  v_idem := 'game_play:' || p_game_id || ':' || v_user::text || ':'
    || to_char(v_today, 'YYYY-MM-DD') || ':' || (v_count + 1);
  v_seed := encode(extensions.gen_random_bytes(16), 'hex');

  v_cards := public.grant_cards(
    v_user,
    v_game.reward_pool_id,
    'game_play',
    v_play,
    v_idem,
    1
  );

  v_result := jsonb_build_object(
    'playId', v_play,
    'rewards', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object('kind', 'card') || reward.elem
          order by reward.ordinality
        ),
        '[]'::jsonb
      )
      from jsonb_array_elements(v_cards) with ordinality as reward(elem, ordinality)
    ),
    'animationSeed', v_seed
  );

  insert into public.game_plays (id, game_id, user_id, result, idempotency_key)
  values (v_play, p_game_id, v_user, v_result, v_idem);

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_claim_collections(target_claim uuid, require_address boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare claim public.order_cancellation_requests;
begin
 select * into claim from public.order_cancellation_requests where id=target_claim;
 if claim.collection_policy<>'origin' or not claim.collection_required then return; end if;
 -- Caller owns order → shipment → claim locks. 회수지 설정(출고지 반품 주소 → 상품 반품지 → 주소록)이 스냅샷 도중
 -- 바뀌지 않게 이 순서로 UUID·ID 순 공유 잠금한다. 상품 저장(admin_save_good_claim_policy)도 상품 → 주소록 순서다.
 perform o.id from public.fulfillment_origins o where o.id in(select s.origin_id from public.order_shipments s where s.order_id=claim.order_id and s.delivery_method<>'digital') order by o.id for share;
 perform g.id from public.goods g where g.id in(select i.good_id from public.order_items i where i.order_id=claim.order_id) order by g.id for share;
 perform r.id from public.return_addresses r where r.id in(select g.return_address_id from public.goods g join public.order_items i on i.good_id=g.id
  where i.order_id=claim.order_id) order by r.id for share;
 if require_address and exists(select 1 from private.claim_shipment_return_lines(claim.order_id) l where btrim(l.return_address)='') then
   raise check_violation using message='claim_return_address_required'; end if;
 insert into public.order_claim_collections(claim_id,shipment_id,origin_id,origin_name_snapshot,return_address_snapshot,items_snapshot)
 select claim.id,s.id,s.origin_id,s.origin_name_snapshot,
   coalesce((select string_agg(d.return_address,' / ' order by d.first_item) from(select l.return_address,min(l.order_item_id::text) first_item
     from private.claim_shipment_return_lines(claim.order_id) l where l.shipment_id=s.id and btrim(l.return_address)<>'' group by l.return_address) d),''),
   (select jsonb_agg(jsonb_build_object('orderItemId',i.id,'name',i.good_name_snapshot,'qty',link.qty) order by i.id)
    from public.order_shipment_items link join public.order_items i on i.id=link.order_item_id where link.shipment_id=s.id)
 from public.order_shipments s
 where s.order_id=claim.order_id and s.delivery_method<>'digital' and exists(select 1 from public.order_shipment_items i where i.shipment_id=s.id)
 on conflict(claim_id,shipment_id) do nothing;
 insert into public.order_claim_collection_bundles(claim_id,shipment_id,return_address_id,return_name_snapshot,return_address_snapshot,return_phone_snapshot,items_snapshot)
 select claim.id,l.shipment_id,l.return_address_id,min(l.return_name),min(l.return_address),min(l.return_phone),
   jsonb_agg(jsonb_build_object('orderItemId',l.order_item_id,'name',l.item_name,'qty',l.qty) order by l.order_item_id)
 from private.claim_shipment_return_lines(claim.order_id) l
 -- 묶음은 배송 건 행을 처음 만들 때 한 번만 나눈다(다시 불려도 이미 나눈 묶음에 품목을 겹쳐 넣지 않는다).
 where exists(select 1 from public.order_claim_collections x where x.claim_id=claim.id and x.shipment_id=l.shipment_id)
  and not exists(select 1 from public.order_claim_collection_bundles b where b.claim_id=claim.id and b.shipment_id=l.shipment_id)
 group by l.shipment_id,l.return_address_id
 on conflict on constraint order_claim_collection_bundles_destination_key do nothing;
 if require_address and not exists(select 1 from public.order_claim_collections where claim_id=target_claim) then
   raise check_violation using message='claim_collections_incomplete'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.prepare_goods_payment_before_sale_period(p_user_id uuid, p_order_id uuid, p_provider public.payment_provider)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.orders%rowtype;
  v_attempt public.payment_attempts%rowtype;
  v_attempt_id uuid;
  v_attempt_expires_at timestamptz;
begin
  if p_user_id is null
    or p_order_id is null
    or p_provider not in ('toss', 'nicepay', 'bank_transfer')
  then
    raise exception 'goods_payment_unavailable' using errcode = '55000';
  end if;

  select order_record.*
  into v_order
  from public.orders as order_record
  where order_record.id = p_order_id
  for update;

  if not found or v_order.user_id is distinct from p_user_id then
    raise no_data_found using message = 'goods_order_not_found';
  end if;

  -- 결제수단은 주문 생성 시점에 고정된다. 선점 창(카드 15분 · 무통장 24시간)이
  -- 그때 결정되므로, 여기서 수단을 갈아타게 두면 재고 보유 시간이 주문 기록과
  -- 어긋난다. 바꾸려면 취소하고 다시 주문해야 한다.
  if (p_provider = 'bank_transfer' and v_order.payment_method <> 'bank_transfer')
    or (p_provider <> 'bank_transfer' and v_order.payment_method <> 'card')
  then
    raise object_not_in_prerequisite_state using message = 'goods_payment_method_mismatch';
  end if;

  if v_order.status is distinct from 'pending'
    or v_order.expires_at is null
    or v_order.expires_at <= pg_catalog.clock_timestamp()
    or v_order.total <= 0
  then
    raise object_not_in_prerequisite_state using message = 'goods_order_not_payable';
  end if;

  -- 판매 제한 상품 포함 여부가 카드 provider를 파생한다(#392). 제한 주문은
  -- 전용 PG(nicepay — 2026-11-05 코페이에서 전환), 일반 주문은 toss만 카드 경로다.
  -- korpay는 진행 중 결제 drain만 남아 새 결제를 준비하지 않는다. 무통장(bank_transfer)은
  -- PG가 아니라 업종 제한과 무관하므로 양쪽 모두 허용된다.
  if p_provider <> 'bank_transfer' then
    if exists (
      select 1
      from public.order_items as item
      join public.goods as good on good.id = item.good_id
      where item.order_id = v_order.id
        and good.sale_restriction <> 'none'
    ) then
      if p_provider <> 'nicepay' then
        raise exception 'goods_payment_provider_mismatch' using errcode = '55000';
      end if;
    elsif p_provider <> 'toss' then
      raise exception 'goods_payment_provider_mismatch' using errcode = '55000';
    end if;
  end if;

  if private.is_account_write_fenced(p_user_id)
    or exists (
      select 1
      from public.profiles as profile
      where profile.id = p_user_id
        and profile.suspended_at is not null
    )
  then
    raise insufficient_privilege using message = 'goods_payment_account_blocked';
  end if;

  if not private.goods_order_snapshot_matches(
    v_order.id,
    v_order.total,
    v_order.shipping_fee
  ) then
    raise check_violation using message = 'goods_order_snapshot_mismatch';
  end if;

  if exists (
    select 1
    from public.order_cancellation_requests as request
    where request.order_id = v_order.id
      and request.status in ('requested', 'processing', 'needs_review')
  ) or exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'order'
      and payment.ref_id = v_order.id
      and payment.status in ('pending', 'paid')
  ) then
    raise object_not_in_prerequisite_state using message = 'goods_order_not_payable';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'order'
    and attempt.ref_id = v_order.id
  for update;

  if found then
    if v_attempt.user_id is distinct from p_user_id
      or v_attempt.provider is distinct from p_provider
      or v_attempt.amount is distinct from v_order.total
      or v_attempt.currency is distinct from 'KRW'
      or v_attempt.state is distinct from 'prepared'
      or v_attempt.expires_at <= pg_catalog.clock_timestamp()
    then
      raise object_not_in_prerequisite_state using message = 'goods_payment_attempt_not_preparable';
    end if;
    return private.goods_payment_attempt_json(v_attempt);
  end if;

  v_attempt_id := extensions.gen_random_uuid();
  -- 카드 action은 10분이면 충분하고 짧을수록 안전하다. 무통장은 attempt TTL이
  -- 곧 입금 기한이라 주문 선점 창과 같아야 한다 — 짧게 잡으면 입금 확인이
  -- 만료된 attempt를 붙잡고 실패한다.
  v_attempt_expires_at := case
    when p_provider = 'bank_transfer' then v_order.expires_at
    else least(
      v_order.expires_at,
      pg_catalog.clock_timestamp() + interval '10 minutes'
    )
  end;

  insert into public.payment_attempts (
    id,
    provider,
    user_id,
    purpose,
    ref_id,
    amount,
    currency,
    state,
    idempotency_key,
    provider_order_id,
    provider_product_code,
    expires_at
  )
  values (
    v_attempt_id,
    p_provider,
    p_user_id,
    'order',
    v_order.id,
    v_order.total,
    'KRW',
    'prepared',
    'goods:' || v_order.id::text,
    'O' || pg_catalog.replace(v_attempt_id::text, '-', ''),
    'P' || pg_catalog.replace(v_attempt_id::text, '-', ''),
    v_attempt_expires_at
  )
  returning * into v_attempt;

  return private.goods_payment_attempt_json(v_attempt);
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_pack_tracking_batch(p_rows jsonb, p_origin uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_value jsonb;sid uuid;ids uuid[]:='{}';pack_key uuid;seen jsonb:='{}';assignment jsonb;carrier text;begin
 if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 1000 then raise invalid_parameter_value using message='invalid_tracking_batch';end if;
 if p_origin is not null then select default_carrier into carrier from public.fulfillment_origins where id=p_origin;end if;
 for row_value in select value from jsonb_array_elements(p_rows) loop
  sid:=null;
  begin
   if p_origin is null then sid:=private.resolve_shipment_reference(row_value->>'reference');
   else select id into strict sid from public.order_shipments where order_id=private.warehouse_reply_order_id(btrim(row_value->>'reference')) and origin_id=p_origin;end if;
  exception when others then sid:=null;end;
  if sid is not null then ids:=array_append(ids,sid);end if;
 end loop;
 if cardinality(ids)>0 then perform private.lock_shipment_pack_scope(ids);end if;
 for row_value in select value from jsonb_array_elements(p_rows) loop
  sid:=null;
  begin
   if p_origin is null then sid:=private.resolve_shipment_reference(row_value->>'reference');
   else select id into strict sid from public.order_shipments where order_id=private.warehouse_reply_order_id(btrim(row_value->>'reference')) and origin_id=p_origin;end if;
  exception when others then sid:=null;end;
  pack_key:=private.shipment_pack_id(sid);
  if pack_key is not null then
   assignment:=jsonb_build_array(case when p_origin is null then btrim(row_value->>'carrier') else carrier end,upper(regexp_replace(btrim(row_value->>'trackingNumber'),'[[:space:]-]','','g')));
   if seen ? pack_key::text and seen->pack_key::text<>assignment then raise check_violation using message='shipment_pack_tracking_conflict';end if;
   seen:=seen||jsonb_build_object(pack_key::text,assignment);
  end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION private.prepare_stock_safety_digest(p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s private.stock_safety_digest_settings;today date;due timestamptz;items jsonb;recipient text;target record;
  delivered text[]:='{}'::text[];deliveries integer:=0;
begin
  if p_now is null then raise invalid_parameter_value using message='invalid_stock_safety_digest_run';end if;
  select * into s from private.stock_safety_digest_settings where singleton;
  if not found or not s.enabled then return jsonb_build_object('status','disabled');end if;
  today:=(p_now at time zone 'Asia/Seoul')::date;
  due:=(today+s.send_time) at time zone 'Asia/Seoul';
  if p_now<due then return jsonb_build_object('status','before_time','dueAt',due);end if;
  if exists(select 1 from private.stock_safety_digest_runs where digest_date=today) then
    return jsonb_build_object('status','already_prepared','digestDate',today);
  end if;
  -- 동시 틱을 직렬화하고 설정 변경과 겹치지 않게 한다.
  perform pg_advisory_xact_lock(hashtextextended('stock-safety-digest-prepare',0));
  select * into s from private.stock_safety_digest_settings where singleton for share;
  if not s.enabled then return jsonb_build_object('status','disabled');end if;
  if exists(select 1 from private.stock_safety_digest_runs where digest_date=today) then
    return jsonb_build_object('status','already_prepared','digestDate',today);
  end if;
  items:=private.stock_safety_digest_items();
  insert into private.stock_safety_digest_runs(digest_date,settings_revision,send_time,item_count,items)
    values(today,s.revision,s.send_time,jsonb_array_length(items),items);
  if jsonb_array_length(items)>0 then
    foreach recipient in array s.operator_recipients loop
      insert into private.stock_safety_digest_deliveries(digest_date,audience,recipient,item_count)
        values(today,'operator',recipient,jsonb_array_length(items));
      delivered:=delivered||recipient;deliveries:=deliveries+1;
    end loop;
    for target in
      select contact.address,array_agg(o.id order by o.name,o.id) as origin_ids,array_agg(o.name order by o.name,o.id) as origin_names
      from private.stock_safety_digest_origin_recipients r
      join public.fulfillment_origins o on o.id=r.origin_id
      cross join unnest(r.recipients) as contact(address)
      where exists(select 1 from jsonb_array_elements(items) i where i->>'originId'=o.id::text)
        and not contact.address=any(delivered)
      group by contact.address
      order by min(o.name),contact.address
    loop
      insert into private.stock_safety_digest_deliveries(digest_date,audience,origin_ids,origin_names,recipient,item_count)
        values(today,'origin',target.origin_ids,target.origin_names,target.address,
          (select count(*) from jsonb_array_elements(items) i where i->>'originId'=any(target.origin_ids::text[])));
      deliveries:=deliveries+1;
    end loop;
  end if;
  update private.stock_safety_digest_runs set delivery_count=deliveries where digest_date=today;
  insert into public.audit_log(actor_id,action,target,diff) values(null,'system.stock_safety_digest.prepared','stock_safety_digest:'||today,
    jsonb_build_object('digestDate',today,'settingsRevision',s.revision,'items',jsonb_array_length(items),'deliveries',deliveries));
  return jsonb_build_object('status','prepared','digestDate',today,'items',jsonb_array_length(items),'deliveries',deliveries);
end $function$

CREATE OR REPLACE FUNCTION private.preserve_order_confirmation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and old.confirmed_at is not null then new.confirmed_at:=old.confirmed_at; end if;
 if new.status in ('confirmed','shipping','delivered','done') then
   new.confirmed_at:=coalesce(new.confirmed_at,new.shipped_at,new.delivered_at,new.done_at,clock_timestamp());
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.process_marketing_run(p_run_id uuid, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare campaign private.marketing_campaigns; run private.marketing_runs; segment private.customer_segments; subjects uuid[]; recipient_ids uuid[];
 rec private.marketing_recipients; reason_value text; notification uuid; inserted_count integer:=0; excluded_count integer:=0; eligible_ids uuid[]; execution_at timestamptz;
begin
 select * into run from private.marketing_runs where id=p_run_id;
 if not found or run.state not in ('queued','processing') or run.scheduled_at>coalesce(p_at,clock_timestamp()) then return jsonb_build_object('processed',false);end if;
 select * into campaign from private.marketing_campaigns where id=run.campaign_id;
 select array_agg(id order by id),array_agg(customer_id order by id) into recipient_ids,subjects from
  (select id,customer_id from private.marketing_recipients where run_id=p_run_id and state='pending' order by id limit 100) pending;
 perform private.lock_operator_subjects(array_append(coalesce(subjects,'{}'),campaign.sender_id));
 select * into campaign from private.marketing_campaigns where id=run.campaign_id for update skip locked;
 if not found then return jsonb_build_object('processed',false);end if;
 select * into run from private.marketing_runs where id=p_run_id for update skip locked;
 if not found or run.state not in ('queued','processing') or run.scheduled_at>coalesce(p_at,clock_timestamp()) then return jsonb_build_object('processed',false);end if;
 if campaign.archived_at is not null or campaign.sender_id is null or not private.has_operator_capability(campaign.sender_id,'marketing.manage',false) then reason_value:='sender_permission';
 else
  select * into segment from private.customer_segments where id=campaign.segment_id for share;
  if not found or segment.archived_at is not null or segment.revision<>campaign.segment_revision or segment.rule_hash<>campaign.rule_hash or not private.customer_segment_references_available(campaign.rule) then reason_value:='segment_changed';
  elsif not private.marketing_content_available(campaign.content) then reason_value:='product_unavailable';end if;
 end if;
 execution_at:=coalesce(p_at,clock_timestamp());
 if reason_value is not null then
  update private.marketing_runs set state='blocked',reason=reason_value,completed_at=execution_at where id=p_run_id;
  update private.marketing_recipients set state='excluded',reason=reason_value where run_id=p_run_id and state='pending';
  return jsonb_build_object('processed',true,'state','blocked','reason',reason_value);
 end if;
 if run.state='queued' and run.scheduled_at+interval '1 hour'<execution_at then
  update private.marketing_runs set state='expired',reason='start_deadline',completed_at=execution_at where id=p_run_id;return jsonb_build_object('processed',true,'state','expired');end if;
 if (execution_at at time zone 'Asia/Seoul')::time<time '08:00' or (execution_at at time zone 'Asia/Seoul')::time>=time '20:00' then
  if run.state='processing' then
   update private.marketing_recipients set state='excluded',reason='delivery_window_ended' where run_id=p_run_id and state='pending';
   update private.marketing_runs set state='completed',reason='delivery_window_ended',completed_at=execution_at where id=p_run_id;return jsonb_build_object('processed',true,'state','completed');
  end if;return jsonb_build_object('processed',false);
 end if;
 if run.state='queued' then
  insert into private.marketing_recipients(run_id,customer_id)
   select p_run_id,m.customer_id from private.customer_segment_members(campaign.rule,execution_at)m where m.marketing_consent;
  get diagnostics inserted_count=row_count;
  update private.marketing_runs set state=case when inserted_count=0 then 'completed' else 'processing' end,started_at=execution_at,candidate_count=inserted_count,completed_at=case when inserted_count=0 then execution_at end where id=p_run_id;
  return jsonb_build_object('processed',true,'state',case when inserted_count=0 then 'completed' else 'processing' end,'candidateCount',inserted_count,'sentCount',0);
 end if;
 -- Resolve the full segment once per batch after all selected profile locks.
 select coalesce(array_agg(m.customer_id),'{}'::uuid[]) into eligible_ids from private.customer_segment_members(campaign.rule,execution_at)m where m.marketing_consent and m.customer_id=any(coalesce(subjects,'{}'));
 for rec in select * from private.marketing_recipients where id=any(coalesce(recipient_ids,'{}')) and run_id=p_run_id and state='pending' order by id for update loop
  reason_value:=null;
  if rec.customer_id is null or not(rec.customer_id=any(eligible_ids)) then reason_value:='customer_no_longer_eligible';
  elsif campaign.exclusion<>'none' and exists(select 1 from private.marketing_recipients prior join private.marketing_runs earlier on earlier.id=prior.run_id left join public.notifications n on n.id=prior.notification_id
   where earlier.campaign_id=campaign.id and earlier.id<>run.id and prior.customer_id=rec.customer_id and prior.state='sent' and (campaign.exclusion='received' or n.read_at is not null)) then reason_value:='already_'||campaign.exclusion;end if;
  if reason_value is not null then
   update private.marketing_recipients set state='excluded',reason=reason_value where id=rec.id;excluded_count:=excluded_count+1;
  else
   insert into public.notifications(user_id,type,title,body,link_path,source_type,source_id,dedupe_key)
   values(rec.customer_id,'marketing_message',campaign.content->>'title',campaign.content->>'body','/notifications/marketing/'||rec.id,'marketing_campaign',campaign.id::text,'marketing:'||rec.id)
   on conflict(user_id,dedupe_key) do update set dedupe_key=excluded.dedupe_key returning id into notification;
   update private.marketing_recipients set state='sent',notification_id=notification,registered_at=execution_at where id=rec.id;inserted_count:=inserted_count+1;
  end if;
 end loop;
 if not exists(select 1 from private.marketing_recipients where run_id=p_run_id and state='pending') then update private.marketing_runs set state='completed',completed_at=execution_at where id=p_run_id;end if;
 return jsonb_build_object('processed',true,'state',(select state from private.marketing_runs where id=p_run_id),'sentCount',inserted_count,'excludedCount',excluded_count);
end $function$

CREATE OR REPLACE FUNCTION private.process_review_best_reward_jobs(p_review_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job private.review_best_reward_jobs; review public.reviews; selection private.review_best_selections; reward private.review_best_rewards;
 eligible boolean; balance jsonb; amount bigint; grant_id uuid; lot_id uuid; expires timestamptz; processed integer:=0; failed integer:=0; result text;
begin
 if p_limit is null or p_limit not between 1 and 100 then raise invalid_parameter_value;end if;
 for job in select * from private.review_best_reward_jobs j where j.state='pending' and j.next_at<=clock_timestamp()
  and (p_review_id is null or j.review_id=p_review_id) order by j.id limit p_limit for update skip locked loop
  begin
   -- Same order as cancellation's financial transition, then BEST invalidation.
   perform 1 from public.orders where id=job.order_id for update;
   perform private.lock_store_credit_account(job.user_id);
   perform pg_advisory_xact_lock(hashtextextended('review-best-order:'||job.order_id::text,0));
   select * into review from public.reviews where id=job.review_id for update;
   select * into selection from private.review_best_selections where review_id=job.review_id for update;
   select * into reward from private.review_best_rewards where review_id=job.review_id for update;
   eligible:=review.id is not null and selection.selected and selection.invalidated_at is null
    and selection.review_fingerprint=private.review_event_review_fingerprint(review) and private.review_best_problem(review) is null
    and exists(select 1 from public.profiles where id=job.user_id and role='user' and suspended_at is null)
    and not private.is_account_write_fenced(job.user_id);
   result:='not_eligible';
   if reward.review_id is not null then
    if (not job.selected or not coalesce(eligible,false)) and reward.revoked_at is null and reward.policy_snapshot->>'reversal'='revoke' then
     perform private.reverse_best_review_reward(job.review_id);result:='revoked';
    else result:='already_processed';end if;
   elsif job.selected and coalesce(eligible,false) and selection.revision=job.selection_revision and job.policy_snapshot->'enabled'='true'::jsonb then
    perform private.expire_store_credit_lots(job.user_id,clock_timestamp());balance:=private.store_credit_balance(job.user_id);
    amount:=least((job.policy_snapshot->>'amount')::bigint,greatest(0,(job.policy_snapshot->>'maxBalance')::bigint-(balance->>'available')::bigint-(balance->>'reserved')::bigint)+(balance->>'debt')::bigint);
    expires:=clock_timestamp()+make_interval(days=>(job.policy_snapshot->>'validityDays')::integer);grant_id:=gen_random_uuid();lot_id:=null;
    if amount>0 then lot_id:=private.issue_store_credit_lot(job.user_id,amount,expires,'admin',job.order_id,job.actor_id,grant_id,'BEST 리뷰 보상');end if;
    insert into private.review_best_rewards(review_id,order_id,user_id,lot_id,amount,planned_amount,policy_snapshot,selection_revision,expires_at,grant_operation_id)
     values(job.review_id,job.order_id,job.user_id,lot_id,amount,(job.policy_snapshot->>'amount')::bigint,job.policy_snapshot,job.selection_revision,expires,grant_id);
    insert into public.audit_log(id,actor_id,action,target,diff) values(grant_id,case when exists(select 1 from public.profiles where id=job.actor_id) then job.actor_id end,
     'review.best.reward_granted','review:'||job.review_id,jsonb_build_object('amount',amount,'plannedAmount',job.policy_snapshot->'amount','lotId',lot_id,'policyRevision',job.policy_snapshot->'revision'));
    result:=case when amount<(job.policy_snapshot->>'amount')::bigint then 'balance_limited' else 'granted' end;
   elsif job.policy_snapshot->'enabled' is distinct from 'true'::jsonb then result:='disabled';
   end if;
   update private.review_best_reward_jobs set state='done',outcome=result,completed_at=clock_timestamp(),last_error=null where id=job.id;processed:=processed+1;
  exception when others then
   update private.review_best_reward_jobs set attempts=attempts+1,last_error=sqlstate,
    next_at=clock_timestamp()+make_interval(mins=>least(60,power(2,least(attempts,6))::integer)) where id=job.id;failed:=failed+1;
  end;
 end loop;
 return jsonb_build_object('processed',processed,'failed',failed);
end $function$

CREATE OR REPLACE FUNCTION private.product_detail_experience_values_valid(p_section text, p_values jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare field text;
begin
 if jsonb_typeof(p_values) is distinct from 'object' then return false;end if;
 if p_section='messages' then
  if (select count(*) from jsonb_object_keys(p_values))<>7
   or not p_values ?& array['buyers','minBuyers','twoYears','repeatBuyers','minRepeatBuyers','bestSeller','newProduct'] then return false;end if;
  foreach field in array array['buyers','twoYears','repeatBuyers','bestSeller','newProduct'] loop
   if jsonb_typeof(p_values->field) is distinct from 'boolean' then return false;end if;
  end loop;
  foreach field in array array['minBuyers','minRepeatBuyers'] loop
   if jsonb_typeof(p_values->field) is distinct from 'number' or p_values->>field !~ '^[0-9]+$'
    or (p_values->>field)::numeric not between 10 and 1000 then return false;end if;
  end loop;
  return true;
 elsif p_section='discovery' then
  return (select count(*)=2 from jsonb_object_keys(p_values)) and p_values ?& array['interests','shippingSavings']
   and jsonb_typeof(p_values->'interests')='boolean' and jsonb_typeof(p_values->'shippingSavings')='boolean';
 end if;
 return false;
exception when others then return false;
end $function$

CREATE OR REPLACE FUNCTION private.product_detail_values_valid(p_section text, p_values jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare entry jsonb; start_day date; end_day date;
begin
 if jsonb_typeof(p_values) is distinct from 'object' then return false;end if;
 if p_section='otherComposition' then
  return coalesce((select count(*)=1 from jsonb_object_keys(p_values))
   and jsonb_typeof(p_values->'enabled')='boolean',false);
 end if;
 if p_section='modules' then
  return coalesce((select count(*)=5 from jsonb_object_keys(p_values))
   and p_values ?& array['reviewSummary','similar','together','categoryPopular','storePopular']
   and not exists(select 1 from jsonb_each(p_values) e where jsonb_typeof(e.value)<>'boolean'),false);
 end if;
 if p_section<>'banner' or (select count(*) from jsonb_object_keys(p_values))<>10
  or not p_values ?& array['enabled','style','title','text','periodEnabled','startsOn','endsOn','targetType','goodIds','categoryIds']
  or jsonb_typeof(p_values->'enabled') is distinct from 'boolean' or jsonb_typeof(p_values->'periodEnabled') is distinct from 'boolean'
  or jsonb_typeof(p_values->'title') is distinct from 'string' or jsonb_typeof(p_values->'text') is distinct from 'string'
  or jsonb_typeof(p_values->'style') is distinct from 'string' or jsonb_typeof(p_values->'targetType') is distinct from 'string'
  or p_values->>'style' not in ('light','dark') or p_values->>'targetType' not in ('all','goods','categories')
  or char_length(p_values->>'title')>10 or char_length(p_values->>'text')>20
  or (p_values->>'title') ~ '[[:cntrl:]]' or (p_values->>'text') ~ '[[:cntrl:]]'
  or (p_values->>'title')<>btrim(p_values->>'title') or (p_values->>'text')<>btrim(p_values->>'text')
  or jsonb_typeof(p_values->'goodIds') is distinct from 'array' or jsonb_typeof(p_values->'categoryIds') is distinct from 'array'
 then return false;end if;
 if jsonb_array_length(p_values->'goodIds')>200 or jsonb_array_length(p_values->'categoryIds')>10 then return false;end if;
 for entry in select value from jsonb_array_elements(p_values->'goodIds') loop
  if jsonb_typeof(entry)<>'string' or entry#>>'{}' !~ '^[a-z0-9][a-z0-9-]{0,199}$' then return false;end if;
 end loop;
 for entry in select value from jsonb_array_elements(p_values->'categoryIds') loop
  if jsonb_typeof(entry)<>'string' or entry#>>'{}' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return false;end if;
 end loop;
 if (select count(*)<>count(distinct value) from jsonb_array_elements(p_values->'goodIds'))
  or (select count(*)<>count(distinct value) from jsonb_array_elements(p_values->'categoryIds')) then return false;end if;
 if p_values->>'targetType'<>'goods' and jsonb_array_length(p_values->'goodIds')>0
  or p_values->>'targetType'<>'categories' and jsonb_array_length(p_values->'categoryIds')>0 then return false;end if;
 if (p_values->>'periodEnabled')::boolean then
  if jsonb_typeof(p_values->'startsOn') is distinct from 'string' or jsonb_typeof(p_values->'endsOn') is distinct from 'string'
   or p_values->>'startsOn' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or p_values->>'endsOn' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return false;end if;
  begin start_day:=(p_values->>'startsOn')::date;end_day:=(p_values->>'endsOn')::date;
  exception when others then return false;end;
  if start_day<date '2000-01-01' or end_day>date '2099-12-31' or start_day>end_day then return false;end if;
 elsif p_values->'startsOn'<>'null'::jsonb or p_values->'endsOn'<>'null'::jsonb then return false;end if;
 return not (p_values->>'enabled')::boolean or (
  char_length(p_values->>'title')>0 and char_length(p_values->>'text')>0
  and (p_values->>'targetType'<>'goods' or jsonb_array_length(p_values->'goodIds')>0)
  and (p_values->>'targetType'<>'categories' or jsonb_array_length(p_values->'categoryIds')>0));
end $function$

CREATE OR REPLACE FUNCTION private.production_claim_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item public.order_items;basis timestamptz;begin
 if new.reshipped_at is not null and(old.reshipped_at is null or old.reshipped_at is distinct from new.reshipped_at) then
  if exists(select 1 from public.order_items i where i.order_id=new.order_id and i.production_terms_snapshot is not null
   and(not exists(select 1 from public.order_claim_reshipments r where r.claim_id=new.id)
    or exists(select 1 from public.order_claim_reshipments r where r.claim_id=new.id and(r.shipment_id is null
     or exists(select 1 from public.order_shipment_items l where l.shipment_id=r.shipment_id and l.order_item_id=i.id))))
   and not exists(select 1 from private.order_production_jobs j where j.order_item_id=i.id and j.claim_id=new.id and j.state='completed')) then raise check_violation using message='production_incomplete';end if;
 end if;
 if new.claim_type='exchange' and new.stage='collected' then
  basis:=coalesce(new.collected_at,clock_timestamp());
  for item in select * from public.order_items where order_id=new.order_id and production_terms_snapshot is not null order by id loop
   perform private.open_claim_production_job(new.order_id,item.id,new.id,item.production_terms_snapshot,basis);
  end loop;
 elsif new.stage in('withdrawn','rejected') or new.claim_type<>'exchange' then update private.order_production_jobs set state='canceled',revision=revision+1,updated_at=clock_timestamp() where claim_id=new.id and state<>'canceled';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.production_deadline(p_at timestamp with time zone, p_terms jsonb)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare day_value date:=(p_at at time zone 'Asia/Seoul')::date;counted integer:=0;wanted integer:=(p_terms->>'leadDays')::integer;begin
 if p_at is null then return null;end if;
 if wanted is null or wanted not between 1 and 365 then raise invalid_parameter_value;end if;
 while counted<wanted loop
  day_value:=day_value+1;
  if p_terms->>'dayBasis'='calendar' or extract(isodow from day_value)<6 and not(p_terms->'closedDates' ? day_value::text) then counted:=counted+1;end if;
 end loop;
 return ((day_value+1)::timestamp at time zone 'Asia/Seoul')-interval '1 microsecond';
end $function$

CREATE OR REPLACE FUNCTION private.production_identity(p_actor uuid, p_session uuid, p_order uuid, p_capability text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parties uuid[];begin
 if p_actor is null or p_actor is distinct from auth.uid() or p_session is null or auth.jwt()->>'session_id' is distinct from p_session::text then raise insufficient_privilege;end if;
 parties:=case when p_order is null then array[p_actor] else array_append(private.contact_parties(p_order),p_actor) end;
 perform private.gift_lock_subjects(parties);perform private.lock_operator_subjects(parties);perform private.assert_active_user(p_actor);
 perform 1 from auth.sessions where id=p_session and user_id=p_actor and(not_after is null or not_after>clock_timestamp()) for share;
 if not found or exists(select 1 from private.account_action_fences where subject_user_id=any(parties)) then raise insufficient_privilege;end if;
 perform private.require_operator_capability(p_capability,false);
end $function$

CREATE OR REPLACE FUNCTION private.production_item_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
