CREATE OR REPLACE FUNCTION private.purchase_confirmation_block_reason(p_order_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.orders; on_hold boolean;
begin
 select * into target from public.orders where id=p_order_id;
 if not found then return 'order_missing';end if;
 if target.status='done' then return null;end if;
 if target.status<>'delivered' then return 'not_delivered';end if;
 select c.held into on_hold from private.order_purchase_confirmations c where c.order_id=target.id;
 if private.purchase_confirmation_eligible(target.id) then return case when coalesce(on_hold,false) then 'held' end;end if;
 if exists(select 1 from public.order_cancellation_requests r where r.order_id=target.id and r.status in('requested','processing','needs_review'))
  or exists(select 1 from public.order_cancellation_claims k where k.order_id=target.id) then return 'claim_in_progress';end if;
 if not private.order_all_items_delivered(target.id) then return 'not_all_delivered';end if;
 if private.is_account_write_fenced(target.user_id) then return 'account_restricted';end if;
 return 'unavailable';
end $function$

CREATE OR REPLACE FUNCTION private.purchase_confirmation_identity(p_actor uuid, p_session uuid, p_admin boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if p_actor is null or p_actor is distinct from auth.uid() or p_session is null or auth.jwt()->>'session_id' is distinct from p_session::text then
  raise insufficient_privilege using message='purchase_confirmation_auth_changed';end if;
 perform 1 from auth.sessions where id=p_session and user_id=p_actor and (not_after is null or not_after>clock_timestamp()) for share;
 if not found then raise insufficient_privilege using message='purchase_confirmation_auth_changed';end if;
 if p_admin then perform private.require_operator_capability('sales.manage',false);
 else perform private.lock_account_action_subject(p_actor);perform 1 from public.profiles where id=p_actor for no key update;perform private.assert_active_user(p_actor);
  if private.is_account_write_fenced(p_actor) then raise insufficient_privilege using message='account_write_fenced';end if;
 end if;return p_actor;
end $function$

