begin
  if actor is null or p_user_coupon_id is null then return null; end if;
  -- 배송비 쿠폰은 legacy 주문서가 받지 않는다(장바구니 선택 RPC와 같은 거절).
  if exists (select 1 from public.user_coupons as held join public.coupons as c on c.code = held.coupon_code
    where held.id = p_user_coupon_id and c.benefit_kind = 'shipping') then
    return jsonb_build_object('userCouponId', p_user_coupon_id, 'couponCode', '', 'eligibleSubtotal', 0, 'discount', 0, 'reason', 'coupon_checkout_required');
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('good_id', line ->> 'goodId', 'subtotal', (line ->> 'qty')::bigint * (line ->> 'effectivePrice')::bigint)), '[]')
    into lines from jsonb_array_elements(p_lines) as line;
  select * into evaluated from private.evaluate_coupon_target_lines_at(p_user_coupon_id, actor, lines, null, statement_timestamp(), true);
  discount := case when evaluated.o_reason is null then least(evaluated.o_discount, greatest(0, p_subtotal + p_shipping_fee - 1000)) else 0 end;
  return jsonb_build_object('userCouponId', p_user_coupon_id, 'couponCode', coalesce(evaluated.o_coupon_code, ''),
    'eligibleSubtotal', evaluated.o_eligible_subtotal, 'discount', discount,
    'reason', case when evaluated.o_reason is null and discount = 0 then 'coupon_no_discount' else evaluated.o_reason end);
end;
$function$

CREATE OR REPLACE FUNCTION private.random_below(p_bound bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare accept_below bigint; drawn bigint;
  span constant bigint:=4611686018427387904;
begin
  if p_bound is null or p_bound<1 or p_bound>span then raise invalid_parameter_value using message='invalid_random_bound'; end if;
  accept_below:=span-(span%p_bound);
  loop
    drawn:=('x'||encode(extensions.gen_random_bytes(8),'hex'))::bit(64)::bigint & 4611686018427387903;
    if drawn<accept_below then return drawn%p_bound; end if;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION private.random_option_pool_supply(p_good_id text, p_at timestamp with time zone)
 RETURNS TABLE(mode text, available_qty integer, policy_id uuid, policy_revision integer, state text, starts_at timestamp with time zone, ends_at timestamp with time zone, expected_ship_date date, next_change_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare key_supply record; total bigint; any_active boolean;
begin
  if p_at is null then raise invalid_parameter_value using message='supply_time_required'; end if;
  select supply.* into key_supply from public.goods_variants key_variant
    cross join lateral private.resolve_goods_variant_supply(key_variant.id,p_at) supply
    where key_variant.good_id=p_good_id and key_variant.is_default and key_variant.archived_at is null
    limit 1;
  if not found then return; end if;
  select least(coalesce(sum(greatest(supply.available_qty,0)::bigint),0),2147483647),coalesce(bool_or(policy.state='active'),false)
    into total,any_active
    from public.goods_variants variant
    cross join lateral private.resolve_goods_variant_supply(variant.id,p_at) supply
    left join private.goods_preorder_policies policy on policy.id=supply.policy_id
    where variant.good_id=p_good_id and variant.archived_at is null and supply.mode=key_supply.mode;
  if key_supply.mode='stock' then
    return query select 'stock'::text,total::integer,null::uuid,null::integer,'stock'::text,
      null::timestamptz,null::timestamptz,null::date,key_supply.next_change_at;
    return;
  end if;
  return query select 'preorder'::text,
    case when any_active and p_at>=key_supply.starts_at and p_at<key_supply.ends_at then total::integer else 0 end,
    key_supply.policy_id,key_supply.policy_revision,
    case when not any_active then 'stopped' when p_at<key_supply.starts_at then 'scheduled'
      when p_at>=key_supply.ends_at then 'closed' else 'open' end,
    key_supply.starts_at,key_supply.ends_at,key_supply.expected_ship_date,
    case when not any_active then null when p_at<key_supply.starts_at then key_supply.starts_at
      when p_at<key_supply.ends_at then key_supply.ends_at else null end;
end $function$

CREATE OR REPLACE FUNCTION private.read_body_templates(p_expected_actor_id uuid, p_capability text, p_id uuid, p_archived boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); target private.admin_body_templates;
begin
 if actor is null or p_expected_actor_id is distinct from actor then
  raise insufficient_privilege using message='body_template_actor_changed';end if;
 if not public.has_operator_capability(p_capability,false) then
  raise insufficient_privilege using message='operator_capability_required';end if;
 if p_id is not null then
  select * into target from private.admin_body_templates where owner_id=actor and id=p_id;
  if not found then raise no_data_found using message='body_template_not_found';end if;
  return private.body_template_summary(target)||jsonb_build_object('bodyHtml',target.body_html);
 end if;
 if p_archived is null then raise invalid_parameter_value using message='invalid_body_template';end if;
 return jsonb_build_object('limit',50,
  'total',(select count(*) from private.admin_body_templates where owner_id=actor),
  'archivedCount',(select count(*) from private.admin_body_templates where owner_id=actor and archived_at is not null),
  'rows',(select coalesce(jsonb_agg(private.body_template_summary(t) order by t.updated_at desc,t.id),'[]'::jsonb)
    from private.admin_body_templates t where t.owner_id=actor and (t.archived_at is not null)=p_archived));
end $function$

CREATE OR REPLACE FUNCTION private.read_order_claim_withdrawal_context(p_claim_id uuid, p_actor uuid, p_as_operator boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claim public.order_cancellation_requests;purchase public.orders;blocker text;
begin
 if p_actor is null then raise insufficient_privilege using message='auth_required';end if;
 if p_as_operator and not private.has_operator_capability(p_actor,'sales.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 select * into claim from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found';end if;
 select * into purchase from public.orders where id=claim.order_id;
 if not p_as_operator and private.gift_claim_actor(p_claim_id) is distinct from p_actor then raise no_data_found using message='claim_not_found';end if;
 blocker:=private.order_claim_withdrawal_blocker(claim);
 return jsonb_build_object('claimId',claim.id,'orderId',claim.order_id,'claimType',claim.claim_type,'stage',claim.stage,
  'revision',claim.claim_revision,'allowed',blocker is null,'blocker',blocker,'orderTotal',case when p_as_operator or purchase.user_id=p_actor then purchase.total else null end,
  'withdrawal',(select jsonb_build_object('actorKind',w.actor_kind,'reason',case when exists(select 1 from private.gift_intents where order_id=claim.order_id) then '선물 요청 철회' else w.reason end,'createdAt',w.created_at) from private.order_claim_withdrawals w where w.claim_id=claim.id));
end $function$

CREATE OR REPLACE FUNCTION private.recalculate_loyalty_grade(p_user_id uuid)
 RETURNS public.loyalty_grade
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  c_window constant interval := interval '90 days';
  v_current public.loyalty_grade;
  v_spend bigint;
  v_item_count bigint;
  v_policy public.loyalty_settings;
  v_manual_floor public.loyalty_grade;
  v_next public.loyalty_grade;
begin
  -- 같은 유저의 동시 재산정(두 주문이 동시에 paid)을 직렬화한다.
  select profile.loyalty_grade
  into v_current
  from public.profiles as profile
  where profile.id = p_user_id
  for update;

  if not found then
    return null;
  end if;

  select * into strict v_policy from public.loyalty_settings where singleton for share;
  select activity.spend, activity.item_count into v_spend, v_item_count
    from private.loyalty_activity(p_user_id) activity;

  -- 창 안의 수동 보정은 재산정의 바닥이다 — 오프라인 실적 보정이 다음 온라인
  -- 주문 한 건에 지워지면 안 된다(감사 이벤트가 그 근거다). 창을 벗어난 보정은
  -- 온라인 실적과 같은 규칙으로 소멸한다.
  select event.next_grade
  into v_manual_floor
  from public.loyalty_grade_events as event
  where event.user_id = p_user_id
    and event.reason = 'manual_adjustment'
    and event.created_at >= now() - c_window
  order by event.created_at desc
  limit 1;

  v_next := greatest(
    private.loyalty_grade_for_activity(v_spend, v_item_count, v_policy.tiers),
    coalesce(v_manual_floor, 'welcome'::public.loyalty_grade)
  );

  if v_next = v_current then
    return v_current;
  end if;

  update public.profiles
  set loyalty_grade = v_next
  where id = p_user_id;

  insert into public.loyalty_grade_events (user_id, previous_grade, next_grade, reason, basis)
  values (
    p_user_id, v_current, v_next, 'recalculation',
    jsonb_build_object('spend', v_spend, 'itemCount', v_item_count, 'windowDays', 90, 'policyRevision', v_policy.revision, 'criteria', v_policy.tiers)
  );

  if v_next > v_current then
    perform private.grant_grade_benefit_coupons(p_user_id, v_current, v_next);

    -- 강등 후 재승급도 알림 가치가 있다 — 같은 dedupe 키는 재부상시킨다.
    insert into public.notifications (
      user_id, type, title, body, link_path, source_type, source_id, dedupe_key
    )
    values (
      p_user_id,
      'loyalty_grade_upgraded',
      '회원 등급이 올랐어요',
      format('%s 등급이 되었어요. 등급 혜택 쿠폰은 쿠폰함에서 확인할 수 있어요.', upper(v_next::text)),
      '/my/coupons',
      'profile',
      p_user_id::text,
      'loyalty:upgrade:' || p_user_id::text || ':' || v_next::text
    )
    on conflict (user_id, dedupe_key) do update set
      read_at = null,
      created_at = now();
  end if;

  return v_next;
end;
$function$

CREATE OR REPLACE FUNCTION private.recalculate_loyalty_on_order_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  begin
    perform private.recalculate_loyalty_grade(new.user_id);
