CREATE OR REPLACE FUNCTION private.reconcile_account_deletion_request(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request private.account_deletion_requests%rowtype;
  v_blockers jsonb;
  v_internal_status text;
begin
  perform private.lock_account_action_subject(p_user_id);

  select request.*
    into v_request
  from private.account_deletion_requests as request
  where request.subject_user_id = p_user_id
  for update;

  if not found then
    return null;
  end if;

  v_blockers := private.account_deletion_blockers(p_user_id);
  v_internal_status := case
    when v_blockers = '[]'::jsonb then 'awaiting_email_intent'
    else 'blocked_active_obligation'
  end;

  perform private.snapshot_account_deletion_legal_records(
    v_request.deletion_event_id,
    p_user_id
  );

  update private.account_deletion_requests as request
  set
    status = v_internal_status,
    blocker_summary = v_blockers,
    updated_at = pg_catalog.now()
  where request.deletion_event_id = v_request.deletion_event_id;

  return private.account_deletion_public_status(p_user_id);
end;
$function$

CREATE OR REPLACE FUNCTION private.reconcile_order_collect_after_cancel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare obligation private.shipping_collect_obligations;shipment public.order_shipments;next_state text;reason text;begin
 perform 1 from public.order_shipments where order_id=new.id order by id for update;
 for obligation in select * from private.shipping_collect_obligations where order_id=new.id order by shipment_id for update loop
  if obligation.state in('void','refunded','refund_review') then continue;end if;
  select * into shipment from public.order_shipments where id=obligation.shipment_id;
  if obligation.state='planned' and shipment.shipped_at is null and shipment.delivered_at is null and shipment.status::text not in('shipping','delivered') then
   next_state:='void';reason:='order_canceled_before_dispatch';
  else next_state:='refund_review';reason:='order_canceled_collection_review';end if;
  update private.shipping_collect_obligations set state=next_state,revision=revision+1,updated_at=clock_timestamp() where shipment_id=obligation.shipment_id;
  insert into private.shipping_collect_events(operation_id,shipment_id,event,amount,evidence,previous_state,previous_revision)
   values(gen_random_uuid(),obligation.shipment_id,next_state,case when next_state='void' then 0 else obligation.amount end,
    jsonb_build_object('orderId',new.id,'reason',reason),obligation.state,obligation.revision);
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.record_cart_order_hold(p_order_id uuid, p_user_id uuid, p_source text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_lines jsonb;
begin
  if not exists (
    select 1 from public.orders as o
    where o.id = p_order_id and o.user_id = p_user_id
      and o.status = 'pending' and o.payment_method = 'card'
  ) then
    raise check_violation using message = 'cart_order_hold_order_invalid';
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'goodId', cart.good_id, 'variantId', cart.variant_id, 'inputKey', cart.input_key,
      'inputRevision', cart.input_revision, 'inputValues', cart.input_values, 'qty', cart.qty)
      order by cart.good_id, cart.variant_id, cart.input_key), '[]'::jsonb)
    into v_lines
  from public.cart_items as cart
  where cart.user_id = p_user_id;
  if pg_catalog.jsonb_array_length(v_lines) = 0 then
    raise check_violation using message = 'cart_order_hold_empty';
  end if;
  insert into private.cart_order_holds (order_id, user_id, source, lines)
  values (p_order_id, p_user_id, p_source, v_lines)
  on conflict (order_id) do nothing;
end;
$function$

