CREATE OR REPLACE FUNCTION private.record_claim_collection_waiver(p_claim public.order_cancellation_requests, p_shipment_id uuid, p_reason text, p_evidence uuid[], p_actor uuid, p_at timestamp with time zone)
 RETURNS public.order_claim_collection_waivers
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare target record;decision public.order_claim_collection_waivers;begin
 select * into decision from public.order_claim_collection_waivers where claim_id=p_claim.id and shipment_id=p_shipment_id;
 if found then
  if decision.reason=p_reason and decision.evidence_file_ids=p_evidence then return decision;end if;
  raise unique_violation using message='collection_waiver_conflict';
 end if;
 select * into target from private.claim_reshipment_targets(p_claim.id) t where t.shipment_id is not distinct from p_shipment_id;
 if not found then raise check_violation using message='reshipment_shipment_not_found';end if;
 if not target.collection_tracked then raise check_violation using message='collection_waiver_unavailable';end if;
 if p_claim.reason_type<>'defect' then raise check_violation using message='collection_waiver_not_allowed';end if;
 if target.collected_at is not null then raise check_violation using message='collection_waiver_not_needed';end if;
 if private.claim_collection_partially_received(p_claim.id,p_shipment_id) then raise check_violation using message='collection_waiver_partially_received';end if;
 if (select count(*) from private.claim_evidence_files f where f.id=any(p_evidence) and f.claim_id=p_claim.id)<>cardinality(p_evidence) then
  raise check_violation using message='collection_waiver_evidence_required';end if;
 insert into public.order_claim_collection_waivers(claim_id,shipment_id,order_id,reason,evidence_file_ids,waived_by,waived_at)
 values(p_claim.id,p_shipment_id,p_claim.order_id,p_reason,p_evidence,p_actor,p_at) returning * into decision;
 perform private.ensure_claim_production_jobs(p_claim.id,target.item_ids,p_at);
 return decision;
end $function$

CREATE OR REPLACE FUNCTION private.record_claim_exchange_defective_stock(p_claim_id uuid, p_reshipment_id uuid, p_shipment_id uuid, p_actor uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare row_ private.claim_defective_stock; claim_order uuid; returned_good text; returned_variant uuid; returned_qty integer;
  target_good public.goods; target_variant public.goods_variants; recorded integer := 0;
begin
  select order_id into claim_order from public.order_cancellation_requests where id = p_claim_id;
  for row_ in select d.* from private.claim_defective_stock d
    where d.claim_id = p_claim_id and d.state = 'planned' and d.source = 'exchange'
      and (exists(select 1 from public.order_claim_reshipment_items ri where ri.reshipment_id = p_reshipment_id and ri.order_item_id = d.order_item_id)
        or exists(select 1 from private.group_claim_reshipment_allocations a where a.reshipment_id = p_reshipment_id and a.order_item_id = d.order_item_id))
    order by d.order_item_id for update loop
    returned_good := null; returned_variant := null; returned_qty := null;
    select x.good_id, x.variant_id, x.qty into returned_good, returned_variant, returned_qty from (
      select ri.good_id, ri.source_variant_id as variant_id, ri.qty from public.order_claim_reshipment_items ri
      where ri.reshipment_id = p_reshipment_id and ri.order_item_id = row_.order_item_id
      union all
      select a.returned_good_id, a.returned_variant_id, a.qty from private.group_claim_reshipment_allocations a
      where a.reshipment_id = p_reshipment_id and a.order_item_id = row_.order_item_id) x limit 1;
    -- 선택 때의 수량과 회수품 수량이 다르면 선택이 낡았다. 재출고 전체를 되돌리고 다시 고르게 한다.
    if returned_qty is distinct from row_.qty then raise sqlstate 'PT409' using message = 'defective_stock_plan_conflict'; end if;
    select * into target_good from public.goods where id = returned_good;
    select * into target_variant from public.goods_variants where id = returned_variant;
    update private.claim_defective_stock set state = 'recorded', good_id = returned_good, variant_id = returned_variant,
      good_name = target_good.name, variant_name = target_variant.name, variant_code = target_variant.code,
      reshipment_id = p_reshipment_id, recorded_by = p_actor, recorded_at = clock_timestamp()
    where id = row_.id;
    insert into public.audit_log(actor_id, action, target, diff) values (p_actor, 'order.claim_defective_stock_recorded', 'order:' || claim_order::text,
      jsonb_build_object('claimId', p_claim_id, 'claimType', 'exchange', 'orderItemId', row_.order_item_id, 'goodId', returned_good,
        'variantId', returned_variant, 'qty', row_.qty, 'reshipmentId', p_reshipment_id, 'shipmentId', p_shipment_id, 'physicalStockDelta', 0));
    recorded := recorded + 1;
  end loop;
  return recorded;
end $function$

CREATE OR REPLACE FUNCTION private.record_direct_order_hold(p_order_id uuid, p_user_id uuid, p_source text, p_lines jsonb, p_base_good_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_source not in ('direct_checkout', 'direct_transaction') or nullif(btrim(p_base_good_id), '') is null then
    raise invalid_parameter_value using message = 'direct_order_hold_invalid';
  end if;
  if not exists (
    select 1 from public.orders as o
    where o.id = p_order_id and o.user_id = p_user_id
      and o.status = 'pending' and o.payment_method = 'card'
  ) then
    raise check_violation using message = 'cart_order_hold_order_invalid';
  end if;
  if pg_catalog.jsonb_typeof(p_lines) is distinct from 'array' or pg_catalog.jsonb_array_length(p_lines) = 0 then
    raise check_violation using message = 'cart_order_hold_empty';
  end if;
  insert into private.cart_order_holds (order_id, user_id, source, lines, base_good_id)
  values (p_order_id, p_user_id, p_source,
    (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('goodId', line ->> 'goodId', 'variantId', line ->> 'variantId',
        'inputKey', case when (line ->> 'inputRevision')::integer = 0 and line -> 'inputValues' = '{}'::jsonb then ''
          else pg_catalog.md5((line ->> 'inputRevision') || ':' || (line -> 'inputValues')::text) end,
        'inputRevision', (line ->> 'inputRevision')::integer, 'inputValues', line -> 'inputValues', 'qty', (line ->> 'qty')::integer)
        order by position)
      from pg_catalog.jsonb_array_elements(p_lines) with ordinality as entries(line, position)),
    p_base_good_id)
  on conflict (order_id) do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION private.record_goods_stock_successor(p_source_good_id text, p_source_variant_id uuid, p_target_good_id text, p_target_variant_id uuid, p_operation_id uuid, p_moved_qty integer, p_actor_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.goods_variants%rowtype;t public.goods_variants%rowtype;
begin
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 if p_moved_qty is null or p_moved_qty<0 or p_source_good_id is not distinct from p_target_good_id
  or p_source_variant_id is not distinct from p_target_variant_id
  or not exists(select 1 from private.goods_group_operations o where o.operation_id=p_operation_id
    and o.actor_id=p_actor_id and o.command='convert' and o.completed_at is null) then
  raise check_violation using message='goods_stock_successor_invalid';
 end if;
 perform 1 from public.goods where id=any(array[p_source_good_id,p_target_good_id]) order by id for update nowait;
 perform 1 from public.goods_variants where id=any(array[p_source_variant_id,p_target_variant_id]) order by id for update nowait;
 select * into s from public.goods_variants where id=p_source_variant_id and good_id=p_source_good_id;
 select * into t from public.goods_variants where id=p_target_variant_id and good_id=p_target_good_id;
 if s.id is null or t.id is null or s.archived_at is null or s.stock_qty<>0
  or t.archived_at is not null or t.stock_qty<>p_moved_qty
  or exists(select 1 from private.goods_stock_successors where source_variant_id=p_source_variant_id
    or source_variant_id=p_target_variant_id or target_variant_id=p_target_variant_id)
  or exists(select 1 from public.order_items where good_id=p_target_good_id)
  or not exists(select 1 from private.goods_group_write_authorizations
    where transaction_id=txid_current() and good_id=p_target_good_id and actor_id=p_actor_id) then
  raise check_violation using message='goods_stock_successor_invalid';
 end if;
 insert into private.goods_stock_successors(source_variant_id,source_good_id,target_variant_id,target_good_id,operation_id,moved_qty,actor_id)
 values(p_source_variant_id,p_source_good_id,p_target_variant_id,p_target_good_id,p_operation_id,p_moved_qty,p_actor_id);
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$function$

CREATE OR REPLACE FUNCTION private.record_group_claim_reshipment(p_claim_id uuid, p_carrier text, p_tracking text, p_selections jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();claim public.order_cancellation_requests;order_state public.order_status;receipt private.group_claim_reshipment_receipts;
 item public.order_items;physical record;target record;choice record;selected_variant uuid;allocations jsonb:='[]';entry jsonb;
 good_ids text[];variant_ids uuid[];deltas jsonb;shipped_items jsonb;inserted integer;
begin
 perform private.require_operator_capability('sales.manage',false);
 select * into claim from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found';end if;
 select status into order_state from public.orders where id=claim.order_id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 if claim.claim_type<>'exchange' then raise check_violation using message='claim_type_has_no_reshipment';end if;
 select * into receipt from private.group_claim_reshipment_receipts where claim_id=p_claim_id;
 if found then
  if claim.stage='completed' and receipt.actor_id=actor and receipt.carrier=p_carrier and receipt.tracking_number=p_tracking and receipt.selections=p_selections then return 'completed';end if;
  raise unique_violation using message='reshipment_conflict';
 end if;
 if claim.stage='completed' or exists(select 1 from public.order_claim_reshipment_items where claim_id=p_claim_id) then
  raise unique_violation using message='reshipment_conflict';
 end if;
 perform private.assert_claim_collections_complete(p_claim_id);
 if claim.stage<>'collected' or order_state not in ('shipping','delivered','done') or exists(select 1 from public.order_cancellation_claims where order_id=claim.order_id) then
  raise check_violation using message='claim_not_reshippable';
 end if;
 if not exists(select 1 from public.shipping_carriers where code=p_carrier and is_active) then raise check_violation using message='unknown shipping carrier';end if;
 if exists(select 1 from jsonb_array_elements(p_selections) x where not exists(select 1 from public.order_items oi where oi.id=(x->>'orderItemId')::uuid and oi.order_id=claim.order_id)) then
  raise check_violation using message='invalid reshipment items';
 end if;
 perform private.lock_goods_stock_successor_topology();
 for item in select * from public.order_items where order_id=claim.order_id and private.order_item_active_qty(id)>0 order by good_id,id loop
  select * into physical from private.order_item_physical_unit(item.id);
  select * into target from private.resolve_goods_stock_successor(physical.good_id,physical.variant_id);
  select (x->>'variantId')::uuid into selected_variant from jsonb_array_elements(p_selections) x where (x->>'orderItemId')::uuid=item.id;
  selected_variant:=coalesce(selected_variant,target.variant_id);
  select * into choice from private.order_item_reshipment_options(item.id) where variant_id=selected_variant;
  if not found then raise check_violation using message='reshipment_variant_unavailable';end if;
  allocations:=allocations||jsonb_build_array(jsonb_build_object('orderItemId',item.id,'originalGoodId',item.good_id,'originalVariantId',item.variant_id,
   'sourceGoodId',physical.good_id,'sourceVariantId',physical.variant_id,'generationKind',physical.generation_kind,'generationId',physical.generation_id,
   'returnedGoodId',target.good_id,'returnedVariantId',target.variant_id,'operationPath',to_jsonb(target.operation_path),
   'goodId',choice.good_id,'variantId',choice.variant_id,'goodName',choice.good_name,'variantName',choice.variant_name,'variantCode',choice.variant_code,'qty',private.order_item_active_qty(item.id)));
 end loop;
 if jsonb_array_length(allocations) not between 1 and 1000 then raise check_violation using message='invalid reshipment items';end if;
 select array_agg(distinct id order by id) into good_ids from (
  select x->>'originalGoodId' id from jsonb_array_elements(allocations) x union select x->>'sourceGoodId' from jsonb_array_elements(allocations) x
  union select x->>'returnedGoodId' from jsonb_array_elements(allocations) x union select x->>'goodId' from jsonb_array_elements(allocations) x) ids;
 select array_agg(distinct id order by id) into variant_ids from (
  select (x->>'originalVariantId')::uuid id from jsonb_array_elements(allocations) x union select (x->>'sourceVariantId')::uuid from jsonb_array_elements(allocations) x
  union select (x->>'returnedVariantId')::uuid from jsonb_array_elements(allocations) x union select (x->>'variantId')::uuid from jsonb_array_elements(allocations) x) ids;
 perform 1 from public.goods where id=any(good_ids) order by id for update nowait;
 perform 1 from public.goods_variants where id=any(variant_ids) order by id for update nowait;
 -- Metadata and availability are read again after locks; topology remains fixed.
 for entry in select value from jsonb_array_elements(allocations) loop
  if not exists(select 1 from private.order_item_reshipment_options((entry->>'orderItemId')::uuid) where variant_id=(entry->>'variantId')::uuid) then
   raise sqlstate 'PT409' using message='reshipment_variant_unavailable';
  end if;
 end loop;
 insert into private.group_claim_reshipment_receipts(claim_id,actor_id,carrier,tracking_number,selections) values(p_claim_id,actor,p_carrier,p_tracking,p_selections);
 for entry in select value from jsonb_array_elements(allocations) loop
  insert into private.group_stock_restorations(order_item_id,generation_kind,generation_id,original_good_id,original_variant_id,
   source_good_id,source_variant_id,target_good_id,target_variant_id,operation_path,qty,cause,claim_id,actor_id,reason)
  values((entry->>'orderItemId')::uuid,entry->>'generationKind',(entry->>'generationId')::uuid,entry->>'originalGoodId',(entry->>'originalVariantId')::uuid,
   entry->>'sourceGoodId',(entry->>'sourceVariantId')::uuid,entry->>'returnedGoodId',(entry->>'returnedVariantId')::uuid,
   array(select value::uuid from jsonb_array_elements_text(entry->'operationPath')),(entry->>'qty')::integer,'exchange',p_claim_id,actor,'교환 회수품 입고') on conflict do nothing;
  get diagnostics inserted=row_count;
  if inserted<>1 then raise check_violation using message='physical_generation_already_restored';end if;
  insert into private.group_claim_reshipment_allocations(claim_id,order_item_id,original_good_id,original_variant_id,source_good_id,source_variant_id,
   source_generation_kind,source_generation_id,returned_good_id,returned_variant_id,operation_path,target_good_id,target_variant_id,
   good_name_snapshot,variant_name_snapshot,variant_code_snapshot,qty)
  select p_claim_id,(entry->>'orderItemId')::uuid,entry->>'originalGoodId',(entry->>'originalVariantId')::uuid,entry->>'sourceGoodId',(entry->>'sourceVariantId')::uuid,
   entry->>'generationKind',(entry->>'generationId')::uuid,entry->>'returnedGoodId',(entry->>'returnedVariantId')::uuid,
   array(select value::uuid from jsonb_array_elements_text(entry->'operationPath')),entry->>'goodId',(entry->>'variantId')::uuid,g.name,v.name,v.code,(entry->>'qty')::integer
  from public.goods g join public.goods_variants v on v.good_id=g.id where v.id=(entry->>'variantId')::uuid and g.id=entry->>'goodId';
 end loop;
 select jsonb_agg(value) into deltas from (
  select jsonb_build_object('goodId',a.returned_good_id,'variantId',a.returned_variant_id,'delta',a.qty) value from private.group_claim_reshipment_allocations a where claim_id=p_claim_id
  union all select jsonb_build_object('goodId',a.target_good_id,'variantId',a.target_variant_id,'delta',-a.qty) from private.group_claim_reshipment_allocations a where claim_id=p_claim_id) movement;
 perform private.apply_group_physical_stock_deltas(deltas);
 select coalesce(jsonb_agg(jsonb_build_object('orderItemId',r.order_item_id,'originalGoodId',r.original_good_id,'sourceGoodId',r.source_good_id,'sourceVariantId',r.source_variant_id,
  'goodId',r.good_id,'variantId',r.variant_id,'qty',r.qty) order by r.order_item_id),'[]') into shipped_items from private.claim_reshipment_items_read(p_claim_id) r;
 update public.order_cancellation_requests set stage='completed',reship_carrier=p_carrier,reship_tracking_number=p_tracking,reshipped_at=clock_timestamp(),completed_at=clock_timestamp(),updated_at=clock_timestamp() where id=p_claim_id;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.claim_reshipped','order:'||claim.order_id::text,
  jsonb_build_object('claimId',p_claim_id,'claimType','exchange','from','collected','to','completed','carrier',p_carrier,'items',shipped_items));
 perform private.notify_order_claim(p_claim_id,'reshipped','교환 상품이 재출고됐어요','교환 상품을 새 운송장으로 발송했습니다.');
 return 'completed';
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$function$

CREATE OR REPLACE FUNCTION private.record_order_claim_collection_bundle(p_claim_id uuid, p_shipment_id uuid, p_bundle_id uuid, p_evidence text, p_received_on date)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid());claim public.order_cancellation_requests;collection public.order_claim_collections;
 bundle public.order_claim_collection_bundles;order_key uuid;shipment_key uuid:=p_shipment_id;address_value text;bundle_count integer;
 order_day date;today date:=(clock_timestamp() at time zone 'Asia/Seoul')::date;received date;shipment_collected boolean:=false;
begin
 if p_evidence is null or p_evidence<>btrim(p_evidence) or char_length(p_evidence) not between 1 and 500 or translate(p_evidence,E'\n\r\t','') ~ '[[:cntrl:]]' then
   raise check_violation using message='invalid_collection_evidence'; end if;
 select order_id into order_key from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found'; end if;
 select (created_at at time zone 'Asia/Seoul')::date into order_day from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 if claim.collection_policy<>'origin' or not claim.collection_required then raise check_violation using message='claim_type_has_no_collection'; end if;
 if p_bundle_id is not null then
   select b.shipment_id into shipment_key from public.order_claim_collection_bundles b where b.id=p_bundle_id and b.claim_id=p_claim_id;
   if not found or (p_shipment_id is not null and shipment_key<>p_shipment_id) then raise no_data_found using message='claim_collection_not_found'; end if;
 end if;
 -- 잠금 순서: 주문 → 배송 건 → 클레임 → 배송 건 회수 행 → 묶음(다른 클레임 함수의 배송 건 회수 행 잠금과 같은 순서).
 select * into collection from public.order_claim_collections where claim_id=p_claim_id and shipment_id=shipment_key for update;
 if not found then raise no_data_found using message='claim_collection_not_found'; end if;
 if p_bundle_id is null then
   select count(*) into bundle_count from public.order_claim_collection_bundles where claim_id=p_claim_id and shipment_id=shipment_key;
   if bundle_count=0 then
     -- 묶음 없이 남은 배송 건 행(배포 경합으로 옛 본문 승인이 만든 행)은 잠근 배송 건 행으로 기본 묶음 하나를 만든다(백필과 같은 값).
     insert into public.order_claim_collection_bundles(claim_id,shipment_id,return_address_id,return_name_snapshot,return_address_snapshot,
      return_phone_snapshot,items_snapshot) values(p_claim_id,shipment_key,null,'',collection.return_address_snapshot,'',collection.items_snapshot)
     on conflict on constraint order_claim_collection_bundles_destination_key do nothing;
     bundle_count:=1;
   end if;
   if bundle_count>1 then raise check_violation using message='claim_collection_bundle_required'; end if;
   select * into bundle from public.order_claim_collection_bundles where claim_id=p_claim_id and shipment_id=shipment_key for update;
 else
   select * into bundle from public.order_claim_collection_bundles where id=p_bundle_id for update;
 end if;
 if bundle.id is null then raise no_data_found using message='claim_collection_not_found'; end if;
 if bundle.collected_at is not null then
   -- 같은 근거·같은 입고일의 재전송은 멱등하다. 입고일 없이 부르는 옛 경로는 근거만 맞춰 본다.
   if bundle.evidence=p_evidence and (p_received_on is null or bundle.received_on is not distinct from p_received_on) then
     return case when private.claim_collections_complete(p_claim_id) then 'collected' else 'collecting' end; end if;
   raise unique_violation using message='claim_collection_conflict';
 end if;
 received:=coalesce(p_received_on,today);
 if received>today or received<order_day then raise check_violation using message='invalid_collection_received_on'; end if;
 if claim.stage not in ('collecting','collected','processing','needs_review') then raise exception using message='claim_not_collectable'; end if;
 address_value:=bundle.return_address_snapshot;
 if btrim(address_value)='' then
   -- 승인 때 출고지 반품 주소가 비어 있던 출고지 기본 묶음(이 기능 전 클레임 포함)만 지금 출고지 주소로 채운다.
   -- 상품 반품지 묶음은 주소록이 주소를 요구하므로 비지 않는다.
   select return_address into address_value from public.fulfillment_origins where id=collection.origin_id for share;
   if coalesce(btrim(address_value),'')='' then raise check_violation using message='claim_return_address_required'; end if;
 end if;
 update public.order_claim_collection_bundles set return_address_snapshot=address_value,collected_at=clock_timestamp(),collected_by=actor,
  evidence=p_evidence,received_on=received where id=bundle.id;
 if not exists(select 1 from public.order_claim_collection_bundles where claim_id=p_claim_id and shipment_id=shipment_key and collected_at is null) then
   shipment_collected:=true;
   update public.order_claim_collections set
     return_address_snapshot=case when btrim(return_address_snapshot)<>'' then return_address_snapshot
       else (select string_agg(distinct b.return_address_snapshot,' / ') from public.order_claim_collection_bundles b where b.claim_id=p_claim_id and b.shipment_id=shipment_key) end,
     collected_at=clock_timestamp(),collected_by=actor,evidence=p_evidence,
     received_on=(select max(coalesce(b.received_on,(b.collected_at at time zone 'Asia/Seoul')::date)) from public.order_claim_collection_bundles b
       where b.claim_id=p_claim_id and b.shipment_id=shipment_key)
   where claim_id=p_claim_id and shipment_id=shipment_key and collected_at is null;
 end if;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.claim_origin_collected','order:'||order_key::text,
  jsonb_build_object('claimId',p_claim_id,'shipmentId',shipment_key,'bundleId',bundle.id,'returnAddressId',bundle.return_address_id,
   'originId',collection.origin_id,'items',bundle.items_snapshot,'returnAddress',address_value,'evidence',p_evidence,
   'receivedOn',received,'shipmentCollected',shipment_collected,'collectionWaived',private.claim_collection_waived(p_claim_id,shipment_key)));
 -- 회수 완료는 회수가 끝날 때 한 번 적고 알린다(private.complete_order_claim_collection, ADR-0041 회수 생략 규칙 포함).
 perform private.complete_order_claim_collection(p_claim_id);
 return case when private.claim_collections_complete(p_claim_id) then 'collected' else 'collecting' end;
end $function$

CREATE OR REPLACE FUNCTION private.record_order_claim_reshipment_physical(p_claim_id uuid, p_carrier text, p_tracking_number text, p_items jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 actor uuid:=(select auth.uid());selected_order uuid;order_status public.order_status;
 claim public.order_cancellation_requests;carrier text:=nullif(btrim(p_carrier),'');tracking text:=nullif(btrim(p_tracking_number),'');
 selections jsonb;requested jsonb;recorded public.order_claim_reshipments;targets integer;single_target uuid;
begin
 perform private.require_operator_capability('sales.manage',false);
 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required';end if;
 if carrier is null or tracking is null or tracking!~'^[A-Z0-9]{8,30}$' then raise check_violation using message='invalid reshipment tracking';end if;
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>1000 then raise check_violation using message='invalid reshipment items';end if;
 for requested in select value from jsonb_array_elements(p_items) loop
  if jsonb_typeof(requested) is distinct from 'object' or not(requested ?& array['orderItemId','variantId'])
   or (select count(*) from jsonb_object_keys(requested))<>2
   or (requested->>'orderItemId') is null or (requested->>'variantId') is null
   or requested->>'orderItemId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or requested->>'variantId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   then raise check_violation using message='invalid reshipment items';end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(p_items) x group by (x->>'orderItemId')::uuid having count(*)>1) then
  raise check_violation using message='invalid reshipment items';end if;
 select coalesce(jsonb_agg(jsonb_build_object('orderItemId',(x->>'orderItemId')::uuid,'variantId',(x->>'variantId')::uuid)
  order by (x->>'orderItemId')::uuid),'[]') into selections from jsonb_array_elements(p_items) x;
 select order_id into selected_order from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found';end if;
 -- Cancellation, payment finalization and claim operations all lock order first.
 select status into order_status from public.orders where id=selected_order for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 if claim.claim_type<>'exchange' then raise exception using message='claim_type_has_no_reshipment';end if;
 -- 배송 건 기록이 있으면 그 기록이 진실원이다. 옛 진입점은 배송 건이 하나인 종결 건의 같은 기록만 재생한다.
 if exists(select 1 from public.order_claim_reshipments where claim_id=p_claim_id) then
  select * into recorded from public.order_claim_reshipments where claim_id=p_claim_id order by reshipped_at,id limit 1;
  if claim.stage='completed' and (select count(*) from public.order_claim_reshipments where claim_id=p_claim_id)=1
   and recorded.carrier=carrier and recorded.tracking_number=tracking and not recorded.collection_waived
   and private.claim_reshipment_selections_match(recorded,selections) then
   return 'completed';end if;
  raise unique_violation using message='reshipment_conflict';
 end if;
 -- 출고 보류(테스트 결제·결제사 취소) 주문에는 교환품을 새로 내보내지 않는다(이미 기록된 재출고의 재생은 위에서 끝났다).
 if private.order_fulfillment_held(selected_order) then raise check_violation using message='order_fulfillment_hold';end if;
 if exists(select 1 from private.group_claim_reshipment_receipts where claim_id=p_claim_id) then
  return private.record_group_claim_reshipment(p_claim_id,carrier,tracking,selections);
 end if;
 if claim.stage='completed' then
  if claim.reship_carrier=carrier and claim.reship_tracking_number=tracking and not exists(
   select 1 from jsonb_array_elements(selections) selected where not exists(
    select 1 from public.order_claim_reshipment_items shipped where shipped.claim_id=p_claim_id
     and shipped.order_item_id=(selected->>'orderItemId')::uuid and shipped.variant_id=(selected->>'variantId')::uuid))
   then return 'completed';end if;
  raise unique_violation using message='reshipment_conflict';
 end if;
 select count(*) into targets from private.claim_reshipment_targets(p_claim_id);
 if targets<>1 then
  -- 회수 확인 전 단계의 오류 순서를 옛 경로와 같게 둔다(전체 회수 → 단계 → 배송 건).
  perform private.assert_claim_collections_complete(p_claim_id);
  if claim.stage<>'collected' then raise exception using message='claim_not_reshippable';end if;
  raise check_violation using message='reshipment_shipment_required';
 end if;
 select t.shipment_id into single_target from private.claim_reshipment_targets(p_claim_id) t;
 return private.record_order_claim_shipment_reshipment(p_claim_id,single_target,carrier,tracking,selections,null);
end $function$

CREATE OR REPLACE FUNCTION private.record_order_claim_shipment_reshipment(p_claim_id uuid, p_shipment_id uuid, p_carrier text, p_tracking_number text, p_items jsonb, p_waiver jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 actor uuid:=(select auth.uid());carrier text:=nullif(btrim(p_carrier),'');tracking text:=nullif(btrim(p_tracking_number),'');
 requested_waiver boolean:=p_waiver is not null and p_waiver<>'null'::jsonb;waived boolean:=false;decided boolean:=false;
 waiver_reason text;evidence uuid[];decision public.order_claim_collection_waivers;
 selections jsonb;requested jsonb;order_key uuid;order_state public.order_status;claim public.order_cancellation_requests;
 target record;existing public.order_claim_reshipments;record_id uuid;item record;source_variant uuid;selected_variant uuid;
 variant public.goods_variants;grouped boolean;physical record;successor record;choice record;allocations jsonb:='[]';entry jsonb;
 good_ids text[];variant_ids uuid[];deltas jsonb;shipped_items jsonb;inserted integer;target_count integer;reshipped_count integer;
 stage_before text;completed boolean;now_at timestamptz;title text;body text;defective_ids uuid[]:='{}';defective_recorded integer;
begin
 perform private.require_operator_capability('sales.manage',false);
 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required';end if;
 if carrier is null or tracking is null or tracking!~'^[A-Z0-9]{8,30}$' then raise check_violation using message='invalid reshipment tracking';end if;
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>1000 then raise check_violation using message='invalid reshipment items';end if;
 for requested in select value from jsonb_array_elements(p_items) loop
  if jsonb_typeof(requested) is distinct from 'object' or not(requested ?& array['orderItemId','variantId'])
   or (select count(*) from jsonb_object_keys(requested))<>2
   or (requested->>'orderItemId') is null or (requested->>'variantId') is null
   or requested->>'orderItemId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or requested->>'variantId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   then raise check_violation using message='invalid reshipment items';end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(p_items) x group by (x->>'orderItemId')::uuid having count(*)>1) then
  raise check_violation using message='invalid reshipment items';end if;
 select coalesce(jsonb_agg(jsonb_build_object('orderItemId',(x->>'orderItemId')::uuid,'variantId',(x->>'variantId')::uuid)
  order by (x->>'orderItemId')::uuid),'[]') into selections from jsonb_array_elements(p_items) x;
 if requested_waiver then select v.reason,v.evidence into waiver_reason,evidence from private.claim_collection_waiver_values(p_waiver) v;end if;
 select order_id into order_key from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found';end if;
 -- Cancellation, payment finalization and claim operations all lock order first.
 select status into order_state from public.orders where id=order_key for update;
 perform 1 from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 if claim.claim_type<>'exchange' then raise exception using message='claim_type_has_no_reshipment';end if;
 perform private.lock_goods_stock_successor_topology();
 -- 먼저 결정한 회수 생략(주문제작 배송 건)은 그 결정이 이 재출고의 회수 생략이다. 같은 요청에 다른 사유·사진을 실으면 거절한다.
 if p_shipment_id is not null and claim.reason_type='defect' then
  select * into decision from public.order_claim_collection_waivers w where w.claim_id=p_claim_id and w.shipment_id=p_shipment_id;
  decided:=found;
 end if;
 if decided then
  if requested_waiver and(decision.reason<>waiver_reason or decision.evidence_file_ids<>evidence) then
   raise unique_violation using message='collection_waiver_conflict';end if;
  waived:=true;waiver_reason:=decision.reason;evidence:=decision.evidence_file_ids;
 else
  waived:=requested_waiver;
 end if;
 select * into existing from public.order_claim_reshipments where claim_id=p_claim_id and shipment_id is not distinct from p_shipment_id for update;
 if found then
  -- 같은 배송 건·같은 운송장·같은 선택의 재전송만 같은 결과다. 재고는 다시 움직이지 않는다.
  if existing.carrier=carrier and existing.tracking_number=tracking and existing.collection_waived=waived
   and existing.waiver_reason is not distinct from waiver_reason and existing.waiver_evidence_file_ids is not distinct from evidence
   and private.claim_reshipment_selections_match(existing,selections) then
   return case when claim.stage='completed' then 'completed' else 'reshipped' end;
  end if;
  raise unique_violation using message='reshipment_conflict';
 end if;
 -- 이 migration 전의 클레임 단위 재출고(한 쌍)는 그대로 종결 기록이다. 배송 건 기록을 덧대지 않는다.
 if claim.stage='completed' or claim.reship_tracking_number is not null
  or exists(select 1 from private.group_claim_reshipment_receipts where claim_id=p_claim_id)
  or exists(select 1 from public.order_claim_reshipment_items where claim_id=p_claim_id and reshipment_id is null)
  or exists(select 1 from private.group_claim_reshipment_allocations where claim_id=p_claim_id and reshipment_id is null) then
  raise unique_violation using message='reshipment_conflict';end if;
 select * into target from private.claim_reshipment_targets(p_claim_id) t where t.shipment_id is not distinct from p_shipment_id;
 if not found then raise check_violation using message='reshipment_shipment_not_found';end if;
 if not waived then
  if target.collection_tracked and target.collected_at is null then raise check_violation using message='claim_collections_incomplete';end if;
 elsif not decided then
  if not target.collection_tracked then raise check_violation using message='collection_waiver_unavailable';end if;
  if claim.reason_type<>'defect' then raise check_violation using message='collection_waiver_not_allowed';end if;
  if target.collected_at is not null then raise check_violation using message='collection_waiver_not_needed';end if;
  if private.claim_collection_partially_received(p_claim_id,p_shipment_id) then raise check_violation using message='collection_waiver_partially_received';end if;
  if (select count(*) from private.claim_evidence_files f where f.id=any(evidence) and f.claim_id=p_claim_id)<>cardinality(evidence) then
   raise check_violation using message='collection_waiver_evidence_required';end if;
 end if;
 if claim.stage not in('collecting','collected') or(not target.collection_tracked and claim.stage<>'collected')
  or order_state not in('shipping','delivered','done')
  or exists(select 1 from public.order_cancellation_claims where order_id=order_key) then
  raise exception using message='claim_not_reshippable';end if;
 if not exists(select 1 from public.shipping_carriers c where c.code=carrier and c.is_active) then raise check_violation using message='unknown shipping carrier';end if;
 if exists(select 1 from jsonb_array_elements(selections) s where not((s->>'orderItemId')::uuid=any(target.item_ids))) then
  raise check_violation using message='invalid reshipment items';end if;
 -- 교환 회수 불량 재고(CLM-046): 회수품을 복원하는 재출고는 그 출고지에서 고른 불량 품목을 복원하지 않는다. 하자·오배송 교환은
 -- 출고지의 재고 처리 결정(불량 분리 또는 정상 복원)이 있어야 재출고한다. 회수 생략 재출고는 회수품이 없어 남은 선택을 지운다.
 if not waived then
  defective_ids:=array(select d.order_item_id from private.claim_defective_stock d where d.claim_id=p_claim_id and d.state='planned'
   and d.source='exchange' and d.order_item_id=any(target.item_ids) order by d.order_item_id);
  if claim.reason_type='defect' and not exists(select 1 from private.claim_exchange_stock_decisions sd
   where sd.claim_id=p_claim_id and sd.shipment_id is not distinct from p_shipment_id) then
   raise check_violation using message='exchange_stock_decision_required';end if;
 else
  delete from private.claim_defective_stock d where d.claim_id=p_claim_id and d.state='planned' and d.order_item_id=any(target.item_ids);
 end if;
 -- 재출고와 같은 요청의 회수 생략은 여기서 결정으로 남긴다. 주문제작 품목은 제작 작업이 막 생겨 아래 검사에서 거절되고
 -- 결정도 함께 되돌린다 — 그 배송 건은 회수 생략을 먼저 결정(admin_waive_order_claim_collection)해 제작을 시작한다.
 if waived and not decided then
  decision:=private.record_claim_collection_waiver(claim,p_shipment_id,waiver_reason,evidence,actor,clock_timestamp());
 end if;
 -- 제작 완료 뒤 재출고: 이 배송 건의 주문제작 품목만 본다(다른 출고지의 제작은 그 출고지 재출고가 기다린다).
 if exists(select 1 from public.order_items i where i.id=any(target.item_ids) and i.production_terms_snapshot is not null
  and not exists(select 1 from private.order_production_jobs j where j.order_item_id=i.id and j.claim_id=p_claim_id and j.state='completed')) then
  raise check_violation using message='production_incomplete';end if;
 grouped:=exists(select 1 from public.order_items oi cross join lateral private.order_item_physical_unit(oi.id) unit
   where oi.id=any(target.item_ids) and(unit.good_id<>oi.good_id
    or exists(select 1 from private.goods_stock_successors where source_variant_id=unit.variant_id)
    or exists(select 1 from private.goods_group_members where variant_id=unit.variant_id)
    or exists(select 1 from private.group_claim_reshipment_allocations where order_item_id=oi.id)))
  or exists(select 1 from jsonb_array_elements(selections) x join public.order_items oi on oi.id=(x->>'orderItemId')::uuid
   join public.goods_variants v on v.id=(x->>'variantId')::uuid where oi.good_id<>v.good_id);
 perform private.assert_tracking_registrable(carrier,tracking,case when p_shipment_id is null then '{}'::uuid[] else array[p_shipment_id] end,order_key);
 now_at:=clock_timestamp();
 insert into public.order_claim_reshipments(claim_id,order_id,shipment_id,origin_name_snapshot,carrier,tracking_number,reshipped_at,reshipped_by,
  selections,collection_waived,waiver_reason,waiver_evidence_file_ids)
 values(p_claim_id,order_key,p_shipment_id,target.origin_name,carrier,tracking,now_at,actor,selections,waived,waiver_reason,evidence) returning id into record_id;
 if not grouped then
  perform 1 from public.goods g where g.id in(select good_id from public.order_items where id=any(target.item_ids)) order by g.id for update;
  for item in select * from public.order_items where id=any(target.item_ids) order by good_id,id loop
   source_variant:=private.order_item_stock_variant(item.id);
   selected_variant:=null;
   select (s->>'variantId')::uuid into selected_variant from jsonb_array_elements(selections) s where (s->>'orderItemId')::uuid=item.id;
   selected_variant:=coalesce(selected_variant,source_variant);
   select * into variant from public.goods_variants where id=selected_variant and good_id=item.good_id;
   if not found or(variant.archived_at is not null and selected_variant<>source_variant) then raise check_violation using message='reshipment_variant_unavailable';end if;
   insert into public.order_claim_reshipment_items(claim_id,order_item_id,good_id,source_variant_id,variant_id,variant_name_snapshot,variant_code_snapshot,qty,reshipment_id)
   values(p_claim_id,item.id,item.good_id,source_variant,selected_variant,variant.name,variant.code,private.order_item_active_qty(item.id),record_id);
  end loop;
  -- 이 배송 건의 회수품(+)과 보낸 옵션(−)을 먼저 상쇄한다. 회수 생략이면 보낸 옵션만 뺀다.
  for item in select changes.good_id,changes.variant_id,sum(changes.delta)::bigint delta from(
    select good_id,source_variant_id variant_id,qty::bigint delta from public.order_claim_reshipment_items where reshipment_id=record_id and not waived
     and not(order_item_id=any(defective_ids))
    union all select good_id,variant_id,-qty::bigint from public.order_claim_reshipment_items where reshipment_id=record_id
   ) changes group by changes.good_id,changes.variant_id having sum(changes.delta)<>0 order by changes.good_id,delta desc,changes.variant_id loop
   perform private.change_goods_variant_stock(item.good_id,item.variant_id,item.delta);
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('orderItemId',order_item_id,'goodId',good_id,'sourceVariantId',source_variant_id,'variantId',variant_id,'qty',qty) order by order_item_id),'[]')
   into shipped_items from public.order_claim_reshipment_items where reshipment_id=record_id;
 else
  for item in select * from public.order_items where id=any(target.item_ids) order by good_id,id loop
   select * into physical from private.order_item_physical_unit(item.id);
   select * into successor from private.resolve_goods_stock_successor(physical.good_id,physical.variant_id);
   selected_variant:=null;
   select (x->>'variantId')::uuid into selected_variant from jsonb_array_elements(selections) x where (x->>'orderItemId')::uuid=item.id;
   selected_variant:=coalesce(selected_variant,successor.variant_id);
   select * into choice from private.order_item_reshipment_options(item.id) where variant_id=selected_variant;
   if not found then raise check_violation using message='reshipment_variant_unavailable';end if;
   allocations:=allocations||jsonb_build_array(jsonb_build_object('orderItemId',item.id,'originalGoodId',item.good_id,'originalVariantId',item.variant_id,
    'sourceGoodId',physical.good_id,'sourceVariantId',physical.variant_id,'generationKind',physical.generation_kind,'generationId',physical.generation_id,
    'returnedGoodId',successor.good_id,'returnedVariantId',successor.variant_id,'operationPath',to_jsonb(successor.operation_path),
    'goodId',choice.good_id,'variantId',choice.variant_id,'goodName',choice.good_name,'variantName',choice.variant_name,'variantCode',choice.variant_code,'qty',private.order_item_active_qty(item.id)));
  end loop;
  if jsonb_array_length(allocations) not between 1 and 1000 then raise check_violation using message='invalid reshipment items';end if;
  select array_agg(distinct id order by id) into good_ids from(
   select x->>'originalGoodId' id from jsonb_array_elements(allocations) x union select x->>'sourceGoodId' from jsonb_array_elements(allocations) x
   union select x->>'returnedGoodId' from jsonb_array_elements(allocations) x union select x->>'goodId' from jsonb_array_elements(allocations) x) ids;
  select array_agg(distinct id order by id) into variant_ids from(
   select (x->>'originalVariantId')::uuid id from jsonb_array_elements(allocations) x union select (x->>'sourceVariantId')::uuid from jsonb_array_elements(allocations) x
   union select (x->>'returnedVariantId')::uuid from jsonb_array_elements(allocations) x union select (x->>'variantId')::uuid from jsonb_array_elements(allocations) x) ids;
  perform 1 from public.goods where id=any(good_ids) order by id for update nowait;
  perform 1 from public.goods_variants where id=any(variant_ids) order by id for update nowait;
  -- Metadata and availability are read again after locks; topology remains fixed.
  for entry in select value from jsonb_array_elements(allocations) loop
   if not exists(select 1 from private.order_item_reshipment_options((entry->>'orderItemId')::uuid) where variant_id=(entry->>'variantId')::uuid) then
    raise sqlstate 'PT409' using message='reshipment_variant_unavailable';end if;
  end loop;
  for entry in select value from jsonb_array_elements(allocations) loop
   if not waived and not((entry->>'orderItemId')::uuid=any(defective_ids)) then
    insert into private.group_stock_restorations(order_item_id,generation_kind,generation_id,original_good_id,original_variant_id,
     source_good_id,source_variant_id,target_good_id,target_variant_id,operation_path,qty,cause,claim_id,actor_id,reason)
    values((entry->>'orderItemId')::uuid,entry->>'generationKind',(entry->>'generationId')::uuid,entry->>'originalGoodId',(entry->>'originalVariantId')::uuid,
     entry->>'sourceGoodId',(entry->>'sourceVariantId')::uuid,entry->>'returnedGoodId',(entry->>'returnedVariantId')::uuid,
     array(select value::uuid from jsonb_array_elements_text(entry->'operationPath')),(entry->>'qty')::integer,'exchange',p_claim_id,actor,'교환 회수품 입고') on conflict do nothing;
    get diagnostics inserted=row_count;
    if inserted<>1 then raise check_violation using message='physical_generation_already_restored';end if;
   end if;
   insert into private.group_claim_reshipment_allocations(claim_id,order_item_id,original_good_id,original_variant_id,source_good_id,source_variant_id,
    source_generation_kind,source_generation_id,returned_good_id,returned_variant_id,operation_path,target_good_id,target_variant_id,
    good_name_snapshot,variant_name_snapshot,variant_code_snapshot,qty,reshipment_id)
   select p_claim_id,(entry->>'orderItemId')::uuid,entry->>'originalGoodId',(entry->>'originalVariantId')::uuid,entry->>'sourceGoodId',(entry->>'sourceVariantId')::uuid,
    entry->>'generationKind',(entry->>'generationId')::uuid,entry->>'returnedGoodId',(entry->>'returnedVariantId')::uuid,
    array(select value::uuid from jsonb_array_elements_text(entry->'operationPath')),entry->>'goodId',(entry->>'variantId')::uuid,g.name,v.name,v.code,(entry->>'qty')::integer,record_id
   from public.goods g join public.goods_variants v on v.good_id=g.id where v.id=(entry->>'variantId')::uuid and g.id=entry->>'goodId';
  end loop;
  select jsonb_agg(value) into deltas from(
   select jsonb_build_object('goodId',a.returned_good_id,'variantId',a.returned_variant_id,'delta',a.qty) value
   from private.group_claim_reshipment_allocations a where a.reshipment_id=record_id and not waived and not(a.order_item_id=any(defective_ids))
   union all select jsonb_build_object('goodId',a.target_good_id,'variantId',a.target_variant_id,'delta',-a.qty)
   from private.group_claim_reshipment_allocations a where a.reshipment_id=record_id) movement;
  perform private.apply_group_physical_stock_deltas(deltas);
  select coalesce(jsonb_agg(jsonb_build_object('orderItemId',a.order_item_id,'originalGoodId',a.original_good_id,'sourceGoodId',a.source_good_id,'sourceVariantId',a.source_variant_id,
   'goodId',a.target_good_id,'variantId',a.target_variant_id,'qty',a.qty) order by a.order_item_id),'[]') into shipped_items
  from private.group_claim_reshipment_allocations a where a.reshipment_id=record_id;
 end if;
 if cardinality(defective_ids)>0 then
  defective_recorded:=private.record_claim_exchange_defective_stock(p_claim_id,record_id,p_shipment_id,actor);
  if defective_recorded<>cardinality(defective_ids) then raise sqlstate 'PT409' using message='defective_stock_plan_conflict';end if;
 end if;
 select count(*) into target_count from private.claim_reshipment_targets(p_claim_id);
 select count(*) into reshipped_count from public.order_claim_reshipments r where r.claim_id=p_claim_id;
 completed:=not exists(select 1 from private.claim_reshipment_targets(p_claim_id) t where not exists(
  select 1 from public.order_claim_reshipments r where r.claim_id=p_claim_id and r.shipment_id is not distinct from t.shipment_id));
 stage_before:=claim.stage;
 update public.order_cancellation_requests set reshipped_at=coalesce(reshipped_at,now_at),
  stage=case when completed then 'completed' else stage end,
  completed_at=case when completed then now_at else completed_at end,
  reship_carrier=case when completed and target_count=1 then carrier else reship_carrier end,
  reship_tracking_number=case when completed and target_count=1 then tracking else reship_tracking_number end,
  updated_at=now_at
 where id=p_claim_id returning * into claim;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.claim_reshipped','order:'||order_key::text,
  jsonb_build_object('claimId',p_claim_id,'claimType','exchange','from',stage_before,'to',claim.stage,'carrier',carrier,'items',shipped_items,
   'reshipmentId',record_id,'shipmentId',p_shipment_id,'originName',target.origin_name,'trackingNumber',tracking,
   'collectionWaived',waived,'defectiveOrderItemIds',to_jsonb(defective_ids),'waiverReason',waiver_reason,'evidenceFileIds',to_jsonb(evidence),'reshippedCount',reshipped_count,'targetCount',target_count));
 title:=case when waived then '교환 상품을 회수 없이 다시 보내드려요' when completed then '교환 상품이 재출고됐어요' else '교환 상품 일부가 먼저 재출고됐어요' end;
 body:=case when waived then '교환 상품을 새 운송장으로 발송했어요. 주문 상세에서 운송장을 확인해주세요.'
  when completed then '교환 상품을 새 운송장으로 발송했습니다.'
  else '준비된 교환 상품을 새 운송장으로 먼저 발송했어요. 나머지 교환 상품도 준비되는 대로 보내드려요.' end;
 -- 배송 건마다 한 번씩 알린다(같은 거래에서 두 배송 건을 처리해도 알림 키가 겹치지 않게 배송 건을 키에 넣는다).
 perform private.notify_order_claim(p_claim_id,'reshipped:'||coalesce(p_shipment_id::text,'order'),title,body);
 return case when completed then 'completed' else 'reshipped' end;
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end $function$

CREATE OR REPLACE FUNCTION private.redact_legacy_email_delivery_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    -- The transient recipient/subject still reach the provider from application
    -- memory, but a new legacy row never receives a plaintext copy.
    new.recipient := 'redacted@invalid.local';
    new.subject := 'legacy_' || new.template;
    new.last_error := case when new.last_error is null then null else 'legacy_failure' end;
  elsif new.retention_disposition = 'destroyed'
    and old.retention_disposition = 'pending_policy'
    and new.destroyed_at is not null
  then
    -- The readiness-guarded retention hook is the only transition that may
    -- destroy pre-migration evidence.
    new.recipient := 'redacted@invalid.local';
    new.subject := 'legacy_' || new.template;
    new.last_error := case when old.last_error is null then null else 'legacy_failure' end;
  else
    -- Retry/completion remains operational while preserving the approved
    -- retention scope. It cannot replace old plaintext or introduce a new raw
    -- provider error after this migration.
    new.recipient := old.recipient;
    new.subject := old.subject;
    new.last_error := case
      when old.last_error is not null then old.last_error
      when new.last_error is null then null
      else 'legacy_failure'
    end;
  end if;
  new.evidence_class := 'legacy_unverified';
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_active_catalog_counts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  previous_ip_id text;
  current_ip_id text;
begin
  if tg_op = 'INSERT' then
    current_ip_id := new.ip_id;
  elsif tg_op = 'DELETE' then
    previous_ip_id := old.ip_id;
  else
    previous_ip_id := old.ip_id;
    current_ip_id := new.ip_id;
  end if;

  if tg_table_name = 'goods' then
    update public.ips as ip
    set goods_count = (
      select count(*)::integer
      from public.goods as good
      where good.ip_id = ip.id
        and good.archived_at is null
    )
    where ip.id = previous_ip_id
       or ip.id = current_ip_id;
  elsif tg_table_name = 'cards' then
    update public.ips as ip
    set cards_count = (
      select count(*)::integer
      from public.cards as card
      where card.ip_id = ip.id
        and card.archived_at is null
    )
    where ip.id = previous_ip_id
       or ip.id = current_ip_id;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_goods_variant_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_good_id text; total_stock bigint;
begin
  target_good_id := case when tg_op='DELETE' then old.good_id else new.good_id end;
  perform 1 from public.goods where id=target_good_id for update;
  if not found then return null; end if; -- parent cascade deletion
  select coalesce(sum(stock_qty),0) into total_stock from public.goods_variants where good_id=target_good_id;
  if total_stock > 2147483647 then raise numeric_value_out_of_range using message='stock_out_of_range'; end if;
  update public.goods set stock_qty=total_stock::integer
    where id=target_good_id and stock_qty is distinct from total_stock::integer;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_order_fulfillment(target_order uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare purchase public.orders; next_status public.order_status; first_shipped timestamptz; last_delivered timestamptz;
begin
  select * into purchase from public.orders where id=target_order for update;
  if not found or purchase.status in ('pending','canceled','done') then return; end if;
  next_status:=private.derive_order_shipment_status(target_order);
  select min(shipped_at),case when bool_and(status='delivered' and delivered_at is not null) then max(delivered_at) end
    into first_shipped,last_delivered from public.order_shipments where order_id=target_order and not private.shipment_closed_by_partial_cancel(id);
  update public.orders set status=next_status,shipped_at=first_shipped,delivered_at=last_delivered where id=target_order;
end $function$

