CREATE OR REPLACE FUNCTION private.release_order_store_credits(p_order_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allocation private.store_credit_allocations; lot private.store_credit_lots; root private.store_credit_lots;
  release_at timestamptz:=clock_timestamp(); expires timestamptz; debt_reduction bigint; restored bigint;
begin
  perform private.expire_store_credit_lots(p_user_id,release_at);
  for allocation in select * from private.store_credit_allocations where order_id=p_order_id and state<>'released' order by lot_id for update loop
    select * into lot from private.store_credit_lots where id=allocation.lot_id for update;
    if not found or lot.user_id<>p_user_id or allocation.user_id<>p_user_id then raise check_violation using message='store_credit_allocation_mismatch'; end if;
    expires:=case when allocation.original_expires_at>release_at then allocation.original_expires_at
      else release_at+make_interval(days=>allocation.restore_grace_days) end;
    if lot.revoked_at is not null then
      select * into root from private.store_credit_lots where id=lot.root_lot_id for update;
      debt_reduction:=least(allocation.amount,root.debt_amount);
      update private.store_credit_lots set debt_amount=debt_amount-debt_reduction where id=root.id;
      update private.store_credit_lots set
        reserved_amount=reserved_amount-case when allocation.state='reserved' then allocation.amount else 0 end,
        spent_amount=spent_amount-case when allocation.state='consumed' then allocation.amount else 0 end,
        revoked_amount=revoked_amount+allocation.amount where id=lot.id;
      insert into public.store_credit_ledger(user_id,kind,amount,reserved_delta,debt_delta,order_id,lot_id)
        values(p_user_id,'restore',0,case when allocation.state='reserved' then -allocation.amount else 0 end,-debt_reduction,p_order_id,lot.id);
      restored:=allocation.amount-debt_reduction;
      -- A prior future grant already discharged this debt. Return exactly that
      -- discharged part; never fabricate a cash receivable or provider refund.
      if restored>0 then perform private.issue_store_credit_lot(p_user_id,restored,expires,'restoration',p_order_id,null,null,''); end if;
    else
      update private.store_credit_lots set
        reserved_amount=reserved_amount-case when allocation.state='reserved' then allocation.amount else 0 end,
        spent_amount=spent_amount-case when allocation.state='consumed' then allocation.amount else 0 end,
        transferred_amount=transferred_amount+allocation.amount where id=lot.id;
      -- Reserve release is a separate zero-amount movement; the new lot records
      -- the restored value once and retains the original earning root.
      if allocation.state='reserved' then
        insert into public.store_credit_ledger(user_id,kind,amount,reserved_delta,order_id,lot_id) values(p_user_id,'restore',0,-allocation.amount,p_order_id,lot.id);
      end if;
      perform private.issue_store_credit_lot(p_user_id,allocation.amount,expires,'restoration',p_order_id,null,null,'',lot.root_lot_id);
    end if;
    update private.store_credit_allocations set state='released',released_at=release_at where order_id=p_order_id and lot_id=lot.id;
  end loop;
  -- An explicitly configured zero-day grace keeps an expired restoration expired.
  perform private.expire_store_credit_lots(p_user_id,release_at);
end $function$

CREATE OR REPLACE FUNCTION private.release_shipment_pack_member_on_cancel(p_shipment uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_pack uuid;
  v_order uuid;
  v_remaining uuid[];
  v_dissolved boolean;
begin
  select m.pack_id into v_pack from private.shipment_pack_members m where m.shipment_id=p_shipment and m.released_at is null;
  if v_pack is null then return false; end if;
  perform 1 from private.shipment_packs where id=v_pack for update;
  -- 잠금을 기다리는 동안 같은 묶음의 다른 취소가 묶음을 풀었을 수 있다.
  update private.shipment_pack_members set released_at=clock_timestamp()
   where pack_id=v_pack and shipment_id=p_shipment and released_at is null;
  if not found then return false; end if;
  select coalesce(array_agg(m.shipment_id order by m.shipment_id),'{}'::uuid[]) into v_remaining
    from private.shipment_pack_members m where m.pack_id=v_pack and m.released_at is null;
  v_dissolved:=cardinality(v_remaining)<2;
  if v_dissolved then
    update private.shipment_pack_members set released_at=clock_timestamp() where pack_id=v_pack and released_at is null;
    update private.shipment_packs set released_at=clock_timestamp(),release_reason='구성 배송 건 취소로 자동 해제',revision=revision+1 where id=v_pack;
  else
    update private.shipment_packs set revision=revision+1 where id=v_pack;
  end if;
  select s.order_id into v_order from public.order_shipments s where s.id=p_shipment;
  insert into public.audit_log(actor_id,action,target,diff) values(null,'system.shipment.pack_member_canceled',v_pack::text,
    jsonb_build_object('packId',v_pack,'shipmentId',p_shipment,'orderId',v_order,'dissolved',v_dissolved,
      'remainingShipmentIds',to_jsonb(v_remaining),'reason','shipment_canceled'));
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.reopen_ineffective_collection_waivers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pending uuid[];
begin
 if old.claim_type='exchange' and old.reason_type='defect' and not(new.claim_type='exchange' and new.reason_type='defect')
  and(new.stage='collected' or new.stage='on_hold' and new.held_from='collected') then
  select array_agg(x.shipment_id order by x.shipment_id) into pending
  from public.order_claim_collection_waivers w join public.order_claim_collections x on x.claim_id=w.claim_id and x.shipment_id=w.shipment_id
  where w.claim_id=new.id and x.collected_at is null;
  if pending is not null then
   if new.stage='collected' then new.stage:='collecting';else new.held_from:='collecting';end if;
   new.collected_at:=null;new.collection_received_on:=null;
   insert into public.audit_log(actor_id,action,target,diff) values((select auth.uid()),'admin.order.claim_collection_reopened','order:'||new.order_id::text,
    jsonb_build_object('claimId',new.id,'claimType',new.claim_type,'reasonType',new.reason_type,'from','collected','to','collecting',
     'shipmentIds',to_jsonb(pending),'cause','collection_waiver_ineffective'));
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.replay_goods_transaction_receipt(p_actor uuid, p_source jsonb, p_quote_id uuid, p_checkout_key uuid, p_payment_method public.order_payment_method)
