CREATE OR REPLACE FUNCTION private.reply_extra_tracking_numbers(p_extras jsonb, p_representative text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare value jsonb; normalized text; result text[] := '{}'::text[];
begin
  if p_extras is null or p_extras = 'null'::jsonb then return result; end if;
  if jsonb_typeof(p_extras) <> 'array' or jsonb_array_length(p_extras) > 19 then
    raise invalid_parameter_value using message = 'invalid_tracking_row'; end if;
  for value in select entry from jsonb_array_elements(p_extras) entry loop
    if jsonb_typeof(value) <> 'string' then raise invalid_parameter_value using message = 'invalid_tracking_row'; end if;
    normalized := private.normalize_tracking_number(value #>> '{}');
    if normalized is null or normalized !~ '^[A-Z0-9]{8,30}$' then raise check_violation using message = 'invalid_tracking_input'; end if;
    if normalized = p_representative or normalized = any(result) then raise invalid_parameter_value using message = 'invalid_tracking_row'; end if;
    result := array_append(result, normalized);
  end loop;
  return result;
end $function$

CREATE OR REPLACE FUNCTION private.require_actor_operator_capability(p_actor uuid, p_capability text, p_legacy_admin_only boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_actor is null then raise insufficient_privilege using message='operator_capability_required'; end if;
  perform private.lock_operator_subjects(array[p_actor]);
  if not private.has_operator_capability(p_actor,p_capability,p_legacy_admin_only) then
    if private.operator_mfa_blocks(p_actor) and private.operator_access_for(p_actor)->>'mode'<>'none' then
      raise insufficient_privilege using message='operator_mfa_required';
    end if;
    raise insufficient_privilege using message='operator_capability_required';
  end if;
  return p_actor;
end $function$

