CREATE OR REPLACE FUNCTION private.reserve_goods_preorder_item(p_order_item_id uuid, p_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item public.order_items; policy private.goods_preorder_policies; existing private.goods_preorder_reservations;
begin
  select * into item from public.order_items where id=p_order_item_id;
  if not found or item.supply_source<>'preorder' or item.preorder_policy_id is null then
    raise check_violation using message='preorder_item_required';
  end if;
  select * into existing from private.goods_preorder_reservations where order_item_id=item.id;
  if found then
    if existing.order_id<>item.order_id or existing.policy_id<>item.preorder_policy_id or existing.qty<>item.qty then
      raise check_violation using message='preorder_reservation_conflict';
    end if;
    return;
  end if;
  if not exists(select 1 from public.orders where id=item.order_id and status='pending') then
    raise check_violation using message='preorder_order_not_pending';
  end if;
  select * into policy from private.goods_preorder_policies where id=item.preorder_policy_id for update;
  if not found or policy.variant_id<>item.variant_id or policy.expected_ship_date<>item.preorder_expected_ship_date
    or item.preorder_snapshot->>'policyRevision' is distinct from policy.revision::text
    or (item.preorder_snapshot->>'startsAt')::timestamptz is distinct from policy.starts_at
    or (item.preorder_snapshot->>'endsAt')::timestamptz is distinct from policy.ends_at then
    raise check_violation using message='preorder_snapshot_mismatch';
  end if;
  if policy.state<>'active' or p_at is null or p_at<policy.starts_at or p_at>=policy.ends_at
    or not exists(select 1 from public.goods_variants where id=item.variant_id and preorder_policy_id=policy.id and archived_at is null) then
    raise check_violation using message='preorder_sale_not_open';
  end if;
  if private.goods_preorder_remaining(policy.id)<item.qty then raise check_violation using message='preorder_capacity_exceeded'; end if;
  insert into private.goods_preorder_reservations(order_item_id,order_id,policy_id,qty) values(item.id,item.order_id,policy.id,item.qty);
end $function$

CREATE OR REPLACE FUNCTION private.reserve_order_store_credits_explicit(p_order_id uuid, p_user_id uuid, p_subtotal bigint, p_coupon_discount bigint, p_shipping_fee bigint, p_requested_amount bigint, p_at timestamp with time zone)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare policy private.store_credit_policy;balance jsonb;outstanding bigint;take bigint;lot private.store_credit_lots;begin
 if p_at is null or not isfinite(p_at) or p_requested_amount is null or p_requested_amount not between 0 and 999999999999 then
  raise invalid_parameter_value using message='store_credit_amount_invalid';end if;
 perform 1 from public.orders where id=p_order_id and user_id=p_user_id and status='pending';
 if not found then raise check_violation using message='store_credit_order_invalid';end if;
 select * into policy from private.store_credit_policy where singleton for share;
 update public.orders set store_credit_policy_snapshot=case when policy.enabled then private.store_credit_policy_for_member(p_user_id)-'evidence' else null end where id=p_order_id;
 if p_requested_amount=0 then return 0;end if;
 if not policy.enabled then raise check_violation using message='store_credit_disabled';end if;
 if p_requested_amount<policy.min_use or p_requested_amount>policy.max_use or p_requested_amount>greatest(0,p_subtotal-p_coupon_discount)
  or p_subtotal::numeric+p_shipping_fee-p_coupon_discount-p_requested_amount<1000 then raise check_violation using message='store_credit_amount_invalid';end if;
 perform private.expire_store_credit_lots(p_user_id,p_at);balance:=private.store_credit_balance(p_user_id);
 if (balance->>'debt')::bigint>0 then raise check_violation using message='store_credit_debt';end if;
 if (balance->>'available')::bigint<p_requested_amount then raise check_violation using message='store_credit_insufficient';end if;
 outstanding:=p_requested_amount;
 for lot in select * from private.store_credit_lots where user_id=p_user_id and available_amount>0 and revoked_at is null and expires_at>p_at order by expires_at,id for update loop
  take:=least(outstanding,lot.available_amount);
  update private.store_credit_lots set available_amount=available_amount-take,reserved_amount=reserved_amount+take where id=lot.id;
  insert into private.store_credit_allocations(order_id,user_id,lot_id,amount,original_expires_at,restore_grace_days)
   values(p_order_id,p_user_id,lot.id,take,lot.expires_at,policy.restore_grace_days);
  insert into public.store_credit_ledger(user_id,kind,amount,available_delta,reserved_delta,order_id,lot_id,expires_at)
   values(p_user_id,'reserve',-take,-take,take,p_order_id,lot.id,lot.expires_at);
  outstanding:=outstanding-take;exit when outstanding=0;
 end loop;
 if outstanding<>0 then raise check_violation using message='store_credit_insufficient';end if;return p_requested_amount;
end $function$

CREATE OR REPLACE FUNCTION private.resolve_goods_custom_inputs(p_good_id text, p_revision integer, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare good public.goods; fields jsonb:='[]'; field jsonb; value text; count_fields integer:=0;
begin
  if p_revision is null or p_revision<0 or jsonb_typeof(p_values) is distinct from 'object' then raise check_violation using message='invalid_goods_custom_inputs'; end if;
  select * into good from public.goods where id=p_good_id;
  if not found then raise check_violation using message='catalog_item_unavailable'; end if;
  if not good.custom_inputs_enabled then
    if p_revision<>0 or p_values<>'{}' then raise check_violation using message='goods_custom_inputs_changed'; end if;
    return null;
  end if;
  if p_revision<>good.custom_inputs_revision then raise check_violation using message='goods_custom_inputs_changed'; end if;
  for field in select item from jsonb_array_elements(good.custom_input_fields) item where (item->>'active')::boolean loop
    count_fields:=count_fields+1;
    if jsonb_typeof(p_values->(field->>'id')) is distinct from 'string' then raise check_violation using message='invalid_goods_custom_inputs'; end if;
    value:=p_values->>(field->>'id');
    if length(value) not between 1 and 100 or value<>btrim(value) or value~'[[:cntrl:]]' then raise check_violation using message='invalid_goods_custom_inputs'; end if;
    fields:=fields||jsonb_build_array(jsonb_build_object('id',field->>'id','name',field->>'name','value',value));
  end loop;
  if count_fields=0 or count_fields<>(select count(*) from jsonb_object_keys(p_values)) then raise check_violation using message='invalid_goods_custom_inputs'; end if;
  return jsonb_build_object('revision',p_revision,'fields',fields);
end $function$

CREATE OR REPLACE FUNCTION private.resolve_goods_stock_successor(p_good_id text, p_variant_id uuid)
 RETURNS TABLE(good_id text, variant_id uuid, hop_count integer, operation_path uuid[])
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare edge private.goods_stock_successors%rowtype; seen uuid[];
begin
 good_id:=p_good_id;variant_id:=p_variant_id;hop_count:=0;operation_path:='{}';seen:=array[p_variant_id];
 loop
  if not exists(select 1 from public.goods_variants v where v.id=resolve_goods_stock_successor.variant_id and v.good_id=resolve_goods_stock_successor.good_id) then
   raise check_violation using message='goods_stock_successor_pair_invalid';
  end if;
  select * into edge from private.goods_stock_successors s where s.source_variant_id=resolve_goods_stock_successor.variant_id;
  if not found then return next;return;end if;
  if edge.source_good_id<>good_id or edge.target_variant_id=any(seen) or hop_count>=128 then
   raise check_violation using message='goods_stock_successor_invalid';
  end if;
  good_id:=edge.target_good_id;variant_id:=edge.target_variant_id;hop_count:=hop_count+1;
  operation_path:=array_append(operation_path,edge.operation_id);seen:=array_append(seen,variant_id);
 end loop;
end;
$function$

CREATE OR REPLACE FUNCTION private.resolve_goods_variant_supply(p_variant_id uuid, p_at timestamp with time zone)
 RETURNS TABLE(mode text, available_qty integer, policy_id uuid, policy_revision integer, state text, starts_at timestamp with time zone, ends_at timestamp with time zone, expected_ship_date date, next_change_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare variant public.goods_variants; policy private.goods_preorder_policies; good public.goods;
begin
 select * into variant from public.goods_variants where id=p_variant_id;
 if not found then raise no_data_found using message='goods_variant_not_found';end if;
 if p_at is null then raise invalid_parameter_value using message='supply_time_required';end if;
 if variant.preorder_policy_id is null then
  select * into good from public.goods where id=variant.good_id;
  return query select 'stock'::text,case when variant.archived_at is null
   and (good.sale_starts_at is null or p_at>=good.sale_starts_at and p_at<good.sale_ends_at) then variant.stock_qty else 0 end,
   null::uuid,null::integer,'stock'::text,null::timestamptz,null::timestamptz,null::date,
   case when p_at<good.sale_starts_at then good.sale_starts_at when p_at<good.sale_ends_at then good.sale_ends_at else null end;
  return;
 end if;
 select * into policy from private.goods_preorder_policies where id=variant.preorder_policy_id and variant_id=variant.id;
 if not found or policy.state='draft' then raise check_violation using message='preorder_policy_not_configured';end if;
 return query select 'preorder'::text,
  case when variant.archived_at is null and policy.state='active' and p_at>=policy.starts_at and p_at<policy.ends_at
   then private.goods_preorder_remaining(policy.id) else 0 end,
  policy.id,policy.revision,case when policy.state='stopped' then 'stopped' when p_at<policy.starts_at then 'scheduled'
   when p_at>=policy.ends_at then 'closed' else 'open' end,policy.starts_at,policy.ends_at,policy.expected_ship_date,
  case when policy.state<>'active' then null when p_at<policy.starts_at then policy.starts_at when p_at<policy.ends_at then policy.ends_at else null end;
end $function$

CREATE OR REPLACE FUNCTION private.resolve_goods_workspace_variant(p_good_id text, p_ref jsonb, p_new_variants uuid[], p_section text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare matched uuid[]; invalid text; unresolved text;
begin
  if p_section is null or p_section not in ('kc','preorder','price_period','purchase_cost') then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  invalid:='invalid_goods_workspace_'||p_section||'_variant';
  unresolved:='goods_workspace_'||p_section||'_variant_unresolved';
  if jsonb_typeof(p_ref) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_ref))<>1 then
    raise check_violation using message=invalid;
  end if;
  if p_ref ? 'id' then
    if jsonb_typeof(p_ref->'id') is distinct from 'string'
      or p_ref->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise check_violation using message=invalid;
    end if;
    select array_agg(id) into matched from public.goods_variants where id=(p_ref->>'id')::uuid and good_id=p_good_id;
  elsif p_ref ? 'attributes' then
    if jsonb_typeof(p_ref->'attributes') is distinct from 'object' then
      raise check_violation using message=invalid;
    end if;
    select array_agg(id) into matched from public.goods_variants
      where good_id=p_good_id and archived_at is null and attributes=p_ref->'attributes';
    if coalesce(cardinality(matched),0)=0 then
      select array_agg(id) into matched from public.goods_variants
        where good_id=p_good_id and id=any(coalesce(p_new_variants,'{}')) and attributes=p_ref->'attributes';
    end if;
  else
    raise check_violation using message=invalid;
  end if;
  if coalesce(cardinality(matched),0)<>1 then raise check_violation using message=unresolved; end if;
  return matched[1];
end $function$

CREATE OR REPLACE FUNCTION private.resolve_shipment_reference(target_reference text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare reference_value text:=btrim(target_reference);shipment_key uuid;matches integer;
begin
 if reference_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   select id into shipment_key from public.order_shipments where id=reference_value::uuid;
   if shipment_key is null then shipment_key:=private.single_order_shipment(reference_value::uuid);end if;
 elsif reference_value ~ '^[0-9]{8}3[0-9]{7}$' then
   select id into shipment_key from public.order_shipments where shipment_number=reference_value;
 elsif private.is_commerce_number(reference_value,1::smallint) then
   select id into shipment_key from public.orders where order_number=reference_value;
   if shipment_key is not null then shipment_key:=private.single_order_shipment(shipment_key);end if;
 elsif reference_value ~* '^[0-9a-f]{8}$' then
   select count(*),(array_agg(id))[1] into matches,shipment_key from public.order_shipments
    where right(id::text,8)=lower(reference_value) or right(order_id::text,8)=lower(reference_value);
   if matches>1 then raise check_violation using message='shipment_reference_required';end if;
 else raise invalid_parameter_value using message='invalid_shipment_reference';end if;
 if shipment_key is null then raise no_data_found using message='shipment_not_found';end if;
 return shipment_key;
end $function$

CREATE OR REPLACE FUNCTION private.restore_order_item_partial_supply(p_order_item_id uuid, p_qty integer, p_partial_cancellation_id uuid, p_reason text, p_follow_successor boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item public.order_items; physical record; target record;
begin
  select * into item from public.order_items where id = p_order_item_id;
  if not found then raise no_data_found using message = 'order_item_not_found'; end if;
  if p_qty is null or p_qty <= 0 then raise invalid_parameter_value using message = 'invalid_partial_cancel_items'; end if;
  perform 1 from public.orders where id = item.order_id for update;
  perform private.lock_goods_stock_successor_topology();
  select * into physical from private.order_item_physical_unit(item.id);
  select * into target from private.resolve_goods_stock_successor(physical.good_id, physical.variant_id);
  perform 1 from public.goods where id = any(array[item.good_id, physical.good_id, target.good_id]) order by id for update nowait;
  perform 1 from public.goods_variants where id = any(array[item.variant_id, physical.variant_id, target.variant_id]) order by id for update nowait;
  if item.supply_source <> 'stock' then raise check_violation using message = 'partial_cancel_item_preorder_item'; end if;
  if not p_follow_successor and (target.hop_count > 0 or physical.good_id <> item.good_id
    or exists(select 1 from private.group_claim_reshipment_allocations where order_item_id = item.id)) then
    raise check_violation using message = 'partial_cancel_item_stock_topology_changed';
  end if;
  perform private.apply_group_physical_stock_deltas(jsonb_build_array(jsonb_build_object('goodId', target.good_id, 'variantId', target.variant_id, 'delta', p_qty)));
  -- 주문 전체 취소의 복원(order.option_stock_restored, 품목마다 한 번)과 다른 액션이다 — 재고 대조·불량 재고 방어선이 둘을 섞지 않는다.
  insert into public.audit_log(actor_id, action, target, diff) values(auth.uid(), 'order.option_stock_partially_restored', 'order:' || item.order_id::text,
    jsonb_build_object('orderItemId', item.id, 'goodId', target.good_id, 'variantId', target.variant_id, 'delta', p_qty,
      'originalGoodId', item.good_id, 'originalVariantId', item.variant_id, 'physicalGoodId', physical.good_id, 'physicalVariantId', physical.variant_id,
      'generationKind', physical.generation_kind, 'generationId', physical.generation_id, 'operationPath', target.operation_path,
      'supplySource', item.supply_source, 'preorderPolicyId', item.preorder_policy_id, 'reason', p_reason,
      'partialCancellationId', p_partial_cancellation_id, 'followedSuccessor', p_follow_successor));
exception when lock_not_available then raise sqlstate 'PT409' using message = 'goods_group_retry';
end $function$

CREATE OR REPLACE FUNCTION private.restore_order_item_supply(p_order_item_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item public.order_items;reservation private.goods_preorder_reservations;physical record;target record;
 reason_value text:=coalesce(nullif(btrim(p_reason),''),'주문 전체 취소');affected boolean;inserted integer;
begin
 select * into item from public.order_items where id=p_order_item_id;
 if not found then raise no_data_found using message='order_item_not_found';end if;
 -- 재고 부족 부분 취소(ADR-0032)로 이미 복원한 수량은 다시 복원하지 않는다. 부분 취소가 없으면 그대로 주문 수량이다.
 item.qty:=item.qty-private.order_item_partially_canceled_qty(item.id);
 if item.qty<=0 then return;end if;
 -- All public writers own this order first; the reentrant lock also protects
 -- internal direct retries from restoring one physical generation twice.
 perform 1 from public.orders where id=item.order_id for update;
 perform private.lock_goods_stock_successor_topology();
 select * into physical from private.order_item_physical_unit(item.id);
 select * into target from private.resolve_goods_stock_successor(physical.good_id,physical.variant_id);
 perform 1 from public.goods where id=any(array[item.good_id,physical.good_id,target.good_id]) order by id for update nowait;
 perform 1 from public.goods_variants where id=any(array[item.variant_id,physical.variant_id,target.variant_id]) order by id for update nowait;
 if item.supply_source='preorder' then
  select * into reservation from private.goods_preorder_reservations where order_item_id=item.id for update;
  if not found then raise check_violation using message='preorder_reservation_missing';end if;
  if reservation.state in ('released','returned') then return;end if;
  if reservation.state='reserved' then
   update private.goods_preorder_reservations set state='released',released_at=clock_timestamp(),released_by=auth.uid(),release_reason=reason_value where order_item_id=item.id;
   insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'order.preorder_capacity_released','order:'||item.order_id::text,
    jsonb_build_object('orderItemId',item.id,'goodId',item.good_id,'variantId',item.variant_id,'policyId',reservation.policy_id,'qty',item.qty,'physicalStockDelta',0,'reason',reason_value));
   return;
  end if;
 end if;
 -- 반품 불량 재고(QNA-035): 불량으로 고른 품목은 판매 재고로 되돌리지 않는다. 선택 행은 기록 뒤에도 남아 재호출에도 같다.
 if exists(select 1 from private.claim_defective_stock d join public.order_cancellation_requests c on c.id=d.claim_id
  where d.order_item_id=item.id and c.claim_type='return' and c.stage not in ('rejected','withdrawn')) then
  if item.supply_source='preorder' then
   update private.goods_preorder_reservations set state='returned',released_at=clock_timestamp(),released_by=auth.uid(),release_reason=reason_value where order_item_id=item.id;
  end if;
  return;
 end if;
 affected:=target.hop_count>0 or physical.good_id<>item.good_id or exists(select 1 from private.group_claim_reshipment_allocations where order_item_id=item.id);
 if affected then
  insert into private.group_stock_restorations(order_item_id,generation_kind,generation_id,original_good_id,original_variant_id,
   source_good_id,source_variant_id,target_good_id,target_variant_id,operation_path,qty,cause,actor_id,reason)
  values(item.id,physical.generation_kind,physical.generation_id,item.good_id,item.variant_id,
   physical.good_id,physical.variant_id,target.good_id,target.variant_id,target.operation_path,item.qty,'refund',auth.uid(),reason_value)
  on conflict do nothing;
  get diagnostics inserted=row_count;
  if inserted=0 then return;end if;
 end if;
 perform private.apply_group_physical_stock_deltas(jsonb_build_array(jsonb_build_object('goodId',target.good_id,'variantId',target.variant_id,'delta',item.qty)));
 if item.supply_source='preorder' then
  update private.goods_preorder_reservations set state='returned',released_at=clock_timestamp(),released_by=auth.uid(),release_reason=reason_value where order_item_id=item.id;
 end if;
 insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'order.option_stock_restored','order:'||item.order_id::text,
  jsonb_build_object('orderItemId',item.id,'goodId',target.good_id,'variantId',target.variant_id,'delta',item.qty,
   'originalGoodId',item.good_id,'originalVariantId',item.variant_id,'physicalGoodId',physical.good_id,'physicalVariantId',physical.variant_id,
   'generationKind',physical.generation_kind,'generationId',physical.generation_id,'operationPath',target.operation_path,
   'supplySource',item.supply_source,'preorderPolicyId',item.preorder_policy_id,'reason',p_reason));
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$function$

CREATE OR REPLACE FUNCTION private.restore_order_store_credit_portion(p_order_id uuid, p_user_id uuid, p_amount bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allocation private.store_credit_allocations; lot private.store_credit_lots; root private.store_credit_lots;
  release_at timestamptz := clock_timestamp(); expires timestamptz; take bigint; debt_reduction bigint; restored bigint; left_amount bigint := p_amount;
begin
  if p_amount is null or p_amount <= 0 then return 0; end if;
  perform private.lock_store_credit_account(p_user_id);
  perform private.expire_store_credit_lots(p_user_id, release_at);
  for allocation in select * from private.store_credit_allocations where order_id = p_order_id and state = 'consumed' order by lot_id for update loop
    exit when left_amount <= 0;
    take := least(left_amount, allocation.amount);
    select * into lot from private.store_credit_lots where id = allocation.lot_id for update;
    if not found or lot.user_id <> p_user_id or allocation.user_id <> p_user_id then
      raise check_violation using message = 'store_credit_allocation_mismatch';
    end if;
    expires := case when allocation.original_expires_at > release_at then allocation.original_expires_at
      else release_at + make_interval(days => allocation.restore_grace_days) end;
    if lot.revoked_at is not null then
      select * into root from private.store_credit_lots where id = lot.root_lot_id for update;
      debt_reduction := least(take, root.debt_amount);
      update private.store_credit_lots set debt_amount = debt_amount - debt_reduction where id = root.id;
      update private.store_credit_lots set spent_amount = spent_amount - take, revoked_amount = revoked_amount + take where id = lot.id;
      insert into public.store_credit_ledger(user_id, kind, amount, reserved_delta, debt_delta, order_id, lot_id)
        values(p_user_id, 'restore', 0, 0, -debt_reduction, p_order_id, lot.id);
      restored := take - debt_reduction;
      if restored > 0 then perform private.issue_store_credit_lot(p_user_id, restored, expires, 'restoration', p_order_id, null, null, ''); end if;
    else
      update private.store_credit_lots set spent_amount = spent_amount - take, transferred_amount = transferred_amount + take where id = lot.id;
      perform private.issue_store_credit_lot(p_user_id, take, expires, 'restoration', p_order_id, null, null, '', lot.root_lot_id);
    end if;
    if take = allocation.amount then
      update private.store_credit_allocations set state = 'released', released_at = release_at where order_id = p_order_id and lot_id = lot.id;
    else
      update private.store_credit_allocations set amount = amount - take where order_id = p_order_id and lot_id = lot.id;
    end if;
    left_amount := left_amount - take;
  end loop;
  if left_amount > 0 then raise check_violation using message = 'store_credit_allocation_mismatch'; end if;
  perform private.expire_store_credit_lots(p_user_id, release_at);
  return p_amount;
end $function$

CREATE OR REPLACE FUNCTION private.return_fee_deduction_plan(p_claim_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  settings private.return_fee_deduction_settings;
  claim public.order_cancellation_requests;
  purchase public.orders;
  pay public.payments;
  payment_count integer;
  basis text;
  fee bigint;
  reason text;
begin
  select * into settings from private.return_fee_deduction_settings where singleton;
  if not found or not settings.enabled then return null; end if;
  select * into claim from public.order_cancellation_requests where id = p_claim_id;
  if not found or claim.claim_type <> 'return' or claim.reason_type <> 'change_of_mind' then return null; end if;
  select * into purchase from public.orders where id = claim.order_id;
  -- 왕복은 '최초 배송비를 한 푼도 내지 않은' 주문만이다. 선결제 배송비(shipping_fee)와 착불(shipping_collect_total) 둘 다 0원일 때.
  basis := case when coalesce(purchase.shipping_fee, 0) = 0 and coalesce(purchase.shipping_collect_total, 0) = 0 then 'round_trip' else 'one_way' end;
  fee := settings.one_way_amount::bigint * case when basis = 'round_trip' then 2 else 1 end;
  select count(*) into payment_count from public.payments p
   where p.purpose = 'order' and p.ref_id = claim.order_id and p.status <> 'failed';
  select * into pay from public.payments p
   where p.purpose = 'order' and p.ref_id = claim.order_id and p.status <> 'failed'
   order by p.created_at desc, p.id desc limit 1;
  reason := case
    when payment_count <> 1 or pay.id is null or pay.amount <= 0 then 'payment_unavailable'
    when exists(select 1 from private.gift_intents g where g.order_id = claim.order_id) then 'gift_order'
    when pay.provider not in ('toss', 'bank_transfer') then 'partial_cancel_unsupported'
    -- 정기배송(billing) 결제는 결제사 부분 취소 계약이 없다 — 차감을 결정하지 않고 전액 환불 + 배송비 청구로 간다.
    when exists(select 1 from public.payment_attempts a
      join private.payment_provider_bindings b on b.attempt_id = a.id
      where a.purpose = 'order' and a.ref_id = claim.order_id) then 'partial_cancel_unsupported'
    when pay.provider = 'toss' and exists(select 1 from public.payment_attempts a
      join private.payment_provider_evidence e on e.payment_attempt_id = a.id
      where a.purpose = 'order' and a.ref_id = claim.order_id
        and (e.payment_method = '가상계좌' or e.result_code = 'DONE_virtual_account')) then 'partial_cancel_unsupported'
    when exists(select 1 from private.claim_fee_invoices i where i.claim_id = claim.id and i.state in ('unpaid', 'reported', 'paid')) then 'claim_fee_invoiced'
    when fee >= pay.amount - private.payment_partial_refunded_amount(pay.id) then 'fee_exceeds_payment'
    else null end;
  return jsonb_build_object(
    'applicable', reason is null,
    'reason', reason,
    'oneWayAmount', settings.one_way_amount,
    'basis', basis,
    'initialShippingFee', coalesce(purchase.shipping_fee, 0) + coalesce(purchase.shipping_collect_total, 0),
    'deductionAmount', fee,
    'paymentId', pay.id,
    'provider', pay.provider,
    'paymentAmount', pay.amount - private.payment_partial_refunded_amount(pay.id),
    'refundAmount', case when reason is null then pay.amount - private.payment_partial_refunded_amount(pay.id) - fee
      else pay.amount - private.payment_partial_refunded_amount(pay.id) end,
    'settingsRevision', settings.revision);
end $function$

CREATE OR REPLACE FUNCTION private.reverse_best_review_reward(p_review_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare reward private.review_best_rewards;lot private.store_credit_lots;debt bigint:=0; recovered bigint:=0;
begin
 select * into reward from private.review_best_rewards where review_id=p_review_id for update;
 if not found or reward.revoked_at is not null or reward.policy_snapshot->>'reversal'<>'revoke' then return;end if;
 perform private.expire_store_credit_lots(reward.user_id,clock_timestamp());
 if reward.lot_id is not null then
  if not exists(select 1 from private.store_credit_lots where id=reward.lot_id and root_lot_id=id and user_id=reward.user_id and source_kind='admin') then
   raise check_violation using message='best_reward_lot_mismatch';end if;
  for lot in select * from private.store_credit_lots where root_lot_id=reward.lot_id order by id for update loop
   if lot.revoked_at is not null then continue;end if;
   debt:=debt+lot.reserved_amount+lot.spent_amount+lot.offset_amount;recovered:=recovered+lot.available_amount;
   update private.store_credit_lots set available_amount=0,revoked_amount=revoked_amount+lot.available_amount,revoked_at=clock_timestamp() where id=lot.id;
   insert into public.store_credit_ledger(user_id,kind,amount,available_delta,debt_delta,order_id,lot_id,operation_id,reason)
    values(reward.user_id,'earned_reversal',-lot.available_amount,-lot.available_amount,lot.reserved_amount+lot.spent_amount+lot.offset_amount,
     reward.order_id,lot.id,reward.revocation_operation_id,'BEST 리뷰 보상 회수');
  end loop;
  update private.store_credit_lots set debt_amount=debt_amount+debt where id=reward.lot_id;
 end if;
 update private.review_best_rewards set revoked_at=clock_timestamp() where review_id=p_review_id;
 insert into public.audit_log(id,action,target,diff) values(reward.revocation_operation_id,'review.best.reward_revoked','review:'||p_review_id,
  jsonb_build_object('recovered',recovered,'futureCreditOffset',debt,'lotId',reward.lot_id));
end $function$

CREATE OR REPLACE FUNCTION private.reverse_order_earned_store_credits(p_order_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare root private.store_credit_lots; lot private.store_credit_lots; debt bigint:=0;
begin
  perform private.lock_store_credit_account(p_user_id);
  select * into root from private.store_credit_lots where source_order_id=p_order_id and source_kind='order_done' for update;
  if not found or root.revoked_at is not null then return; end if;
  if root.user_id<>p_user_id then raise check_violation using message='store_credit_source_mismatch'; end if;
  -- Descendant restoration lots keep root attribution: refunding a purchase does
  -- not launder its already restored earnings into an unrelated grant.
  for lot in select * from private.store_credit_lots where root_lot_id=root.id order by id for update loop
    debt:=debt+lot.reserved_amount+lot.spent_amount+lot.offset_amount;
    update private.store_credit_lots set available_amount=0,revoked_amount=revoked_amount+lot.available_amount,revoked_at=clock_timestamp() where id=lot.id;
    insert into public.store_credit_ledger(user_id,kind,amount,available_delta,debt_delta,order_id,lot_id)
      values(p_user_id,'earned_reversal',-lot.available_amount,-lot.available_amount,lot.reserved_amount+lot.spent_amount+lot.offset_amount,p_order_id,lot.id);
  end loop;
  update private.store_credit_lots set debt_amount=debt_amount+debt where id=root.id;
end $function$

CREATE OR REPLACE FUNCTION private.reverse_review_event_award(p_entry_id uuid, p_reason text, p_actor uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare award private.review_event_awards%rowtype; lot private.store_credit_lots%rowtype; debt bigint:=0; recovered bigint:=0;
begin
 select * into award from private.review_event_awards where entry_id=p_entry_id;
 if not found then return false;end if;
 perform private.lock_store_credit_account(award.user_id);
 select * into award from private.review_event_awards where entry_id=p_entry_id for update;
 if award.revoked_at is not null then return false;end if;
 perform private.expire_store_credit_lots(award.user_id,clock_timestamp());
 if not exists(select 1 from private.store_credit_lots where id=award.lot_id and root_lot_id=id and user_id=award.user_id and source_kind='admin')
 then raise check_violation using message='review_event_credit_source_mismatch';end if;
 for lot in select * from private.store_credit_lots where root_lot_id=award.lot_id order by id for update loop
  if lot.user_id<>award.user_id then raise check_violation using message='review_event_credit_source_mismatch';end if;
  debt:=debt+lot.reserved_amount+lot.spent_amount+lot.offset_amount;recovered:=recovered+lot.available_amount;
  update private.store_credit_lots set available_amount=0,revoked_amount=revoked_amount+lot.available_amount,revoked_at=clock_timestamp() where id=lot.id;
  insert into public.store_credit_ledger(user_id,kind,amount,available_delta,debt_delta,lot_id,actor_id,operation_id,reason)
   values(award.user_id,'adjustment_debit',-lot.available_amount,-lot.available_amount,lot.reserved_amount+lot.spent_amount+lot.offset_amount,
    lot.id,p_actor,award.revoke_operation_id,'리뷰 이벤트 혜택 회수: '||left(coalesce(p_reason,''),900));
 end loop;
 update private.store_credit_lots set debt_amount=debt_amount+debt where id=award.lot_id;
 update private.review_event_awards set revoked_at=clock_timestamp(),revoked_by=p_actor,revoke_reason=p_reason where entry_id=p_entry_id;
 insert into public.audit_log(id,actor_id,action,target,diff) values(award.revoke_operation_id,p_actor,'review_event.reward.reversed','review_event_entry:'||p_entry_id,
  jsonb_build_object('eventId',award.event_id,'entryId',p_entry_id,'lotId',award.lot_id,'reason',p_reason,'availableRecovered',recovered,'futureOffset',debt));
 return true;
end $function$

CREATE OR REPLACE FUNCTION private.review_best_problem(p_review public.reviews)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_review.id is null then return 'review_deleted';end if;
 if p_review.status<>'visible' then return 'review_hidden';end if;
 if not private.review_event_purchase_eligible(p_review.order_id,p_review.user_id,p_review.good_id) then return 'purchase_ineligible';end if;
 if not exists(select 1 from public.profiles where id=p_review.user_id and suspended_at is null)
   or private.is_account_write_fenced(p_review.user_id) then return 'customer_unavailable';end if;
 if not exists(select 1 from public.goods g join public.ips ip on ip.id=g.ip_id where g.id=p_review.good_id
   and g.archived_at is null and g.published_at is not null and g.sale_restriction='none' and ip.archived_at is null and ip.published_at is not null) then return 'good_unavailable';end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION private.review_best_purchase_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare changed_order_id uuid;
begin
 if tg_table_name='orders' then
  if new.status='canceled' then changed_order_id:=new.id;end if;
 elsif tg_table_name='payments' then
  if new.purpose='order' and new.status='refunded' then changed_order_id:=new.ref_id;end if;
 elsif new.claim_type in ('cancel','return') and (new.status='completed' or new.stage='completed') then changed_order_id:=new.order_id;
 end if;
 if changed_order_id is not null then
  perform pg_advisory_xact_lock(hashtextextended('review-best-order:'||changed_order_id::text,0));
  perform private.invalidate_review_best(array(select id from public.reviews r where r.order_id=changed_order_id),'purchase_changed');
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.review_best_state(p_review public.reviews)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare chosen private.review_best_selections; problem text;
begin
 select * into chosen from private.review_best_selections where review_id=p_review.id;
 problem:=private.review_best_problem(p_review);
 if problem is null and chosen.selected and (chosen.invalidated_at is not null or chosen.review_fingerprint is distinct from private.review_event_review_fingerprint(p_review)) then problem:=case when chosen.invalidation_reason='purchase_changed' then 'purchase_changed' else 'review_changed' end;end if;
 return jsonb_build_object('reviewId',p_review.id,'selected',coalesce(chosen.selected,false),'revision',coalesce(chosen.revision,0),
   'reviewFingerprint',private.review_event_review_fingerprint(p_review),'selectedAt',chosen.selected_at,'reason',chosen.reason,
   'problem',problem,'state',case when not coalesce(chosen.selected,false) then 'not_selected' when problem is null then 'selected' else 'needs_review' end);
end $function$

CREATE OR REPLACE FUNCTION private.review_event_entry_problem(p_entry private.review_event_entries)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare review public.reviews%rowtype;
begin
 select * into review from public.reviews where id=p_entry.review_id;
 if not found then return 'review_deleted';end if;
 if review.status<>'visible' then return 'review_hidden';end if;
 if review.user_id<>p_entry.user_id or review.order_id<>p_entry.order_id or review.good_id<>p_entry.good_id then return 'review_changed';end if;
 if not private.review_event_purchase_eligible(p_entry.order_id,p_entry.user_id,p_entry.good_id) then return 'purchase_ineligible';end if;
 if not exists(select 1 from public.profiles p where p.id=p_entry.user_id and p.suspended_at is null)
  or private.is_account_write_fenced(p_entry.user_id) then return 'customer_unavailable';end if;
 if not exists(select 1 from public.goods g join public.ips ip on ip.id=g.ip_id where g.id=review.good_id
  and g.archived_at is null and g.published_at is not null and g.sale_restriction='none' and ip.archived_at is null and ip.published_at is not null) then return 'good_unavailable';end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION private.review_event_export_snapshot(p_filters jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare mode_value text; query_value text; state_value text; date_field text; from_day date; to_day date;
 target_event_id uuid; filter_value text; event_doc jsonb; exported jsonb; fingerprint_rows jsonb; row_count integer; fingerprint text;
begin
 if p_filters is null or jsonb_typeof(p_filters)<>'object' or octet_length(p_filters::text)>2000
  or exists(select 1 from jsonb_each(p_filters) f where jsonb_typeof(f.value) not in ('string','null')) then
  raise invalid_parameter_value using message='invalid_review_event_export';end if;
 mode_value:=p_filters->>'mode'; query_value:=p_filters->>'query';
 if mode_value is null or mode_value not in ('events','entries') or query_value is null or char_length(query_value)>100 or query_value<>btrim(query_value) then
  raise invalid_parameter_value using message='invalid_review_event_export';end if;
 if mode_value='events' then
  if (select array_agg(key order by key) from jsonb_object_keys(p_filters) key)<>array['dateField','from','mode','query','state','to'] then
   raise invalid_parameter_value using message='invalid_review_event_export';end if;
  state_value:=p_filters->>'state';date_field:=p_filters->>'dateField';
  if state_value is null or state_value not in ('all','scheduled','active','closed','ready','announced','archived')
   or date_field is null or date_field not in ('created','start','end','announce')
   or (p_filters->>'from' is not null and p_filters->>'from'!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}$')
   or (p_filters->>'to' is not null and p_filters->>'to'!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}$') then
   raise invalid_parameter_value using message='invalid_review_event_export';end if;
  from_day:=(p_filters->>'from')::date;to_day:=(p_filters->>'to')::date;
  if from_day is not null and to_day is not null and from_day>to_day then raise invalid_parameter_value using message='invalid_review_event_export';end if;
  with candidates as (
   select e.*,private.review_event_state(e,statement_timestamp()) state,
    case date_field when 'start' then starts_on when 'end' then ends_on when 'announce' then announces_on else (created_at at time zone 'Asia/Seoul')::date end filter_day
   from private.review_events e where query_value='' or position(lower(query_value) in lower(e.title))>0 or e.number::text=query_value or e.id::text=query_value
  ), filtered as (select * from candidates where (state_value='all' and archived_at is null or state=state_value)
   and (from_day is null or filter_day>=from_day) and (to_day is null or filter_day<=to_day)), bounded as (
   select * from filtered order by created_at desc,id limit 10001
  ), documents as (
   select id,created_at,private.review_event_document(id) value from bounded
  ) select count(*),coalesce(jsonb_agg((value-'goodIds'-'categoryIds')||jsonb_build_object(
   'targetCount',jsonb_array_length(value->'goodIds')+jsonb_array_length(value->'categoryIds'),
   'targetsFingerprint',encode(extensions.digest(jsonb_build_array(value->'goodIds',value->'categoryIds')::text,'sha256'),'hex'))
   order by created_at desc,id),'[]'::jsonb) into row_count,exported from documents;
  fingerprint_rows:=exported;
 else
  if (select array_agg(key order by key) from jsonb_object_keys(p_filters) key)<>array['eventId','filter','mode','query']
   or p_filters->>'eventId' is null or p_filters->>'eventId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   raise invalid_parameter_value using message='invalid_review_event_export';end if;
  target_event_id:=(p_filters->>'eventId')::uuid;filter_value:=p_filters->>'filter';
  if filter_value is null or filter_value not in ('all','eligible','selected','awarded','revoked','unavailable') then
   raise invalid_parameter_value using message='invalid_review_event_export';end if;
  event_doc:=private.review_event_document(target_event_id);
  if event_doc is null then raise no_data_found using message='review_event_not_found';end if;
  with candidates as materialized (
   select entry.*,r.body,r.rating,r.updated_at review_updated_at,private.review_event_review_fingerprint(r) review_fingerprint,
    cardinality(coalesce(r.image_paths,'{}')) image_count,coalesce(nullif(btrim(profile.nickname),''),'고객') nickname,
    coalesce(g.name,'삭제된 상품') good_name,coalesce(g.code,'') good_code,private.review_event_entry_problem(entry) problem,
    award.granted_at,award.revoked_at,award.expires_at
   from private.review_event_entries entry left join public.reviews r on r.id=entry.review_id
   left join public.profiles profile on profile.id=entry.user_id left join public.goods g on g.id=entry.good_id
   left join private.review_event_awards award on award.entry_id=entry.id where entry.event_id=target_event_id
  ), filtered as (
   select * from candidates where (query_value='' or position(lower(query_value) in lower(nickname||' '||good_name||' '||coalesce(body,'')))>0 or source_review_id::text=query_value)
    and (filter_value='all' or filter_value='eligible' and problem is null and granted_at is null or filter_value='selected' and selected
     or filter_value='awarded' and granted_at is not null and revoked_at is null or filter_value='revoked' and revoked_at is not null or filter_value='unavailable' and problem is not null)
  ), bounded as (select * from filtered order by entered_at desc,id limit 10001), documents as (
   select entered_at,id,review_fingerprint,jsonb_build_object('id',id,'reviewId',source_review_id,'goodId',good_id,'goodCode',good_code,'goodName',good_name,
    'nickname',nickname,'rating',rating,'imageCount',image_count,'enteredAt',entered_at,'reviewUpdatedAt',review_updated_at,
    'selected',selected,'selectionChanged',selected and (selected_review_updated_at is distinct from review_updated_at or selected_review_fingerprint is distinct from review_fingerprint),
    'problem',problem,'creditAmount',credit_amount,'creditValidityDays',credit_validity_days,'eventRevision',event_revision,
    'grantedAt',granted_at,'revokedAt',revoked_at,'expiresAt',expires_at) value from bounded
  ) select count(*),coalesce(jsonb_agg(value order by entered_at desc,id),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_array(value,review_fingerprint) order by entered_at desc,id),'[]'::jsonb)
   into row_count,exported,fingerprint_rows from documents;
 end if;
 if row_count>10000 then raise program_limit_exceeded using message='review_event_export_limit';end if;
 fingerprint:=encode(extensions.digest(jsonb_build_object('filters',p_filters,'event',event_doc,'rows',fingerprint_rows)::text,'sha256'),'hex');
 return jsonb_build_object('filters',p_filters,'event',event_doc,'total',row_count,'rows',exported,'fingerprint',fingerprint,'capturedAt',statement_timestamp());
end $function$

CREATE OR REPLACE FUNCTION private.review_event_purchase_revocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_table_name='orders' then
  if new.status='canceled' then perform private.reverse_review_event_order_awards(new.id,'원주문 취소');end if;
 elsif tg_table_name='payments' then
  if new.purpose='order' and new.status='refunded' then
   -- Wait for an in-flight publisher before scanning its newly committed awards.
   -- Publishing locks original orders before credit accounts, as refund finalizers do.
   perform 1 from public.orders where id=new.ref_id for update;
   perform private.reverse_review_event_order_awards(new.ref_id,'원결제 환불');
  end if;
 elsif new.claim_type in ('cancel','return') and (new.status='completed' or new.stage='completed') then
  perform 1 from public.orders where id=new.order_id for update;
  perform private.reverse_review_event_order_awards(new.order_id,'원주문 취소·반품 완료');
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.review_event_review_revocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare award record;
begin
 if tg_op='DELETE' or new.status='hidden' then
  for award in select entry_id from private.review_event_awards where source_review_id=old.id and revoked_at is null order by user_id,entry_id loop
   perform private.reverse_review_event_award(award.entry_id,case when tg_op='DELETE' then '리뷰 삭제' else '리뷰 비공개' end,null);
  end loop;
 end if;
 return coalesce(new,old);
end $function$

CREATE OR REPLACE FUNCTION private.review_event_values_valid(p_values jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare item jsonb; start_day date; end_day date; announce_day date;
begin
 if jsonb_typeof(p_values) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_values))<>12
  or not p_values ?& array['title','description','targetType','startsOn','endsOn','announcesOn','plannedWinners','creditAmount','creditValidityDays','bannerStyle','goodIds','categoryIds']
  or jsonb_typeof(p_values->'title') is distinct from 'string' or jsonb_typeof(p_values->'description') is distinct from 'string'
  or char_length(p_values->>'title') not between 1 and 15 or char_length(p_values->>'description') not between 1 and 30
  or private.review_event_template_text_valid(p_values->>'title',15) is distinct from true or private.review_event_template_text_valid(p_values->>'description',30) is distinct from true
  or ((p_values->>'title')||(p_values->>'description')) ~ '[[:cntrl:]]'
  or jsonb_typeof(p_values->'targetType') is distinct from 'string' or p_values->>'targetType' not in ('all','goods','categories')
  or jsonb_typeof(p_values->'bannerStyle') is distinct from 'string' or p_values->>'bannerStyle' not in ('basic','emphasis')
  or jsonb_typeof(p_values->'goodIds') is distinct from 'array' or jsonb_typeof(p_values->'categoryIds') is distinct from 'array'
  or jsonb_array_length(p_values->'goodIds')>500 or jsonb_array_length(p_values->'categoryIds')>500
 then return false;end if;
 foreach item in array array[p_values->'plannedWinners',p_values->'creditAmount',p_values->'creditValidityDays'] loop
  if jsonb_typeof(item) is distinct from 'number' or item::text !~ '^[0-9]+$' then return false;end if;
 end loop;
 if (p_values->>'plannedWinners')::numeric not between 1 and 1000 or (p_values->>'creditAmount')::numeric not between 1 and 999999999999
  or (p_values->>'creditValidityDays')::numeric not between 1 and 36500 then return false;end if;
 for item in select value from jsonb_array_elements(p_values->'goodIds') loop
  if jsonb_typeof(item)<>'string' or item#>>'{}' !~ '^[a-z0-9][a-z0-9-]{0,199}$' then return false;end if;
 end loop;
 for item in select value from jsonb_array_elements(p_values->'categoryIds') loop
  if jsonb_typeof(item)<>'string' or item#>>'{}' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return false;end if;
 end loop;
 if (select count(*)<>count(distinct value) from jsonb_array_elements(p_values->'goodIds'))
  or (select count(*)<>count(distinct value) from jsonb_array_elements(p_values->'categoryIds'))
  or p_values->>'targetType'<>'goods' and jsonb_array_length(p_values->'goodIds')>0
  or p_values->>'targetType'<>'categories' and jsonb_array_length(p_values->'categoryIds')>0
  or p_values->>'targetType'='goods' and jsonb_array_length(p_values->'goodIds')=0
  or p_values->>'targetType'='categories' and jsonb_array_length(p_values->'categoryIds')=0 then return false;end if;
 foreach item in array array[p_values->'startsOn',p_values->'endsOn',p_values->'announcesOn'] loop
  if jsonb_typeof(item) is distinct from 'string' or item#>>'{}' !~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}$' then return false;end if;
 end loop;
 begin start_day:=(p_values->>'startsOn')::date;end_day:=(p_values->>'endsOn')::date;announce_day:=(p_values->>'announcesOn')::date;
 exception when others then return false;end;
 return end_day between start_day+1 and start_day+31 and announce_day between end_day+3 and end_day+10;
end $function$

CREATE OR REPLACE FUNCTION private.review_type_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ordered public.orders;w record;begin
 if tg_op='UPDATE' then
  if (new.review_kind,new.repeat_purchase,new.write_deadline_at,new.type_policy_revision,new.month_reward_eligible) is distinct from
     (old.review_kind,old.repeat_purchase,old.write_deadline_at,old.type_policy_revision,old.month_reward_eligible) then raise check_violation using message='review_type_snapshot_immutable';end if;
  return new;
 end if;
 select * into ordered from public.orders where id=new.order_id;
 select * into w from private.review_type_window(ordered,new.review_kind);
 if new.review_kind='month' and (w.opens_at is null or statement_timestamp()<w.opens_at or statement_timestamp()>w.deadline_at) then
  raise check_violation using message='review_month_window_closed';end if;
 new.write_deadline_at:=w.deadline_at;new.type_policy_revision:=w.policy_revision;new.month_reward_eligible:=coalesce(w.reward_eligible,false);
 new.repeat_purchase:=exists(select 1 from public.orders prior join public.order_items i on i.order_id=prior.id
  where prior.id<>ordered.id and prior.user_id=new.user_id and i.good_id=new.good_id and prior.created_at<ordered.created_at
  and prior.status in('delivered','done') and prior.delivered_at between statement_timestamp()-interval '180 days' and statement_timestamp()
  and private.review_event_purchase_eligible(prior.id,new.user_id,new.good_id));
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.revoke_member_auth_sessions(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare revoked integer;
begin
  if p_user_id is null then raise invalid_parameter_value using message = 'member_withdrawal_member_required'; end if;
  delete from auth.refresh_tokens where user_id = p_user_id::text and session_id is null;
  delete from auth.sessions where user_id = p_user_id;
  get diagnostics revoked = row_count;
  return revoked;
end $function$

CREATE OR REPLACE FUNCTION private.run_auto_order_confirmation(p_now timestamp with time zone, p_batch integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s private.auto_order_confirmation_settings;run private.auto_order_confirmation_runs;today date;cutoff timestamptz;
 candidate record;purchase public.orders;outcome text;detail text;confirmed integer:=0;excluded integer:=0;seen integer:=0;
 base_timeout text:=current_setting('lock_timeout');
begin
 if p_now is null or p_batch is null or p_batch not between 1 and 1000 then raise invalid_parameter_value using message='invalid_auto_order_confirmation_run';end if;
 today:=(p_now at time zone 'Asia/Seoul')::date;
 -- 잠금 없는 사전 확인: 대부분의 틱은 여기서 끝난다.
 select * into s from private.auto_order_confirmation_settings where singleton;
 if not found or not s.enabled then return jsonb_build_object('status','disabled');end if;
 if not exists(select 1 from private.auto_order_confirmation_runs where finished_at is null and run_date<=today) then
  cutoff:=(today+s.run_time) at time zone 'Asia/Seoul';
  if p_now<cutoff then return jsonb_build_object('status','before_cutoff','cutoffAt',cutoff);end if;
  if s.enabled_at>=cutoff then return jsonb_build_object('status','enabled_after_cutoff','cutoffAt',cutoff);end if;
  if exists(select 1 from private.auto_order_confirmation_runs where run_date=today) then return jsonb_build_object('status','already_ran','runDate',today);end if;
 end if;
 -- 동시 틱을 직렬화하고, 실행 중에는 설정 변경을 기다리게 한다.
 perform pg_advisory_xact_lock(hashtextextended('auto-order-confirmation-run',0));
 select * into s from private.auto_order_confirmation_settings where singleton for share;
 if not s.enabled then return jsonb_build_object('status','disabled');end if;
 -- 이전 날짜에서 넘어온 실행을 포함해 가장 이른 미완료 실행을 먼저 이어 간다.
 select * into run from private.auto_order_confirmation_runs where finished_at is null and run_date<=today order by run_date limit 1 for update;
 if found then
  -- 실행 도중 껐다 켜면 새 켠 시각 이전 결제분을 더 처리하지 않고 그 실행을 닫는다.
  if s.enabled_at is distinct from run.enabled_at then
   perform private.finish_auto_order_confirmation_run(run.run_date,'settings_changed');
   return jsonb_build_object('status','settings_changed','runDate',run.run_date);
  end if;
 else
  cutoff:=(today+s.run_time) at time zone 'Asia/Seoul';
  if p_now<cutoff then return jsonb_build_object('status','before_cutoff','cutoffAt',cutoff);end if;
  if s.enabled_at>=cutoff then return jsonb_build_object('status','enabled_after_cutoff','cutoffAt',cutoff);end if;
  insert into private.auto_order_confirmation_runs(run_date,cutoff_at,enabled_at,settings_revision)
   values(today,cutoff,s.enabled_at,s.revision) on conflict(run_date) do nothing;
  select * into run from private.auto_order_confirmation_runs where run_date=today for update;
  if run.finished_at is not null then return jsonb_build_object('status','already_ran','runDate',today);end if;
 end if;
 for candidate in
  select picked.id from (
   select o.id from public.orders o join private.order_paid_marks m on m.order_id=o.id
   where o.status='paid' and m.paid_at>=run.enabled_at and m.paid_at<=run.cutoff_at
    and not exists(select 1 from private.auto_order_confirmation_outcomes x where x.run_date=run.run_date and x.order_id=o.id)
   order by m.paid_at,o.id limit p_batch) picked
  order by picked.id
 loop
  seen:=seen+1;detail:=null;
  -- 잠그기 전에 이미 보이는 제외 사유는 잠금 없이 남긴다.
  outcome:=private.auto_order_confirmation_blocker(candidate.id);
  if outcome is null then
   begin
    perform set_config('lock_timeout','3s',true);
    -- 고객 직접 취소·수동 발주확인과 같은 주문 → 배송 건 순서. 먼저 잠근 쪽만 반영된다.
    select * into purchase from public.orders where id=candidate.id for update;
    perform id from public.order_shipments where order_id=candidate.id order by id for update;
    if purchase.status<>'paid' then raise sqlstate 'AOC01' using message='status_changed';end if;
    outcome:=private.auto_order_confirmation_blocker(candidate.id);
    if outcome is not null then raise sqlstate 'AOC01' using message=outcome;end if;
    perform private.confirm_paid_order(candidate.id,null,jsonb_build_object('trigger','auto_order_confirmation','runDate',run.run_date,'cutoffAt',run.cutoff_at));
    outcome:='confirmed';
    perform set_config('lock_timeout',base_timeout,true);
   exception
    -- 블록을 되돌리므로 제외·실패한 주문의 잠금은 여기서 풀린다.
    when sqlstate 'AOC01' then outcome:=sqlerrm;
    when lock_not_available or deadlock_detected then outcome:='locked';detail:=sqlstate;
    when others then outcome:='failed';detail:=left(sqlstate||' '||sqlerrm,300);
   end;
  end if;
  insert into private.auto_order_confirmation_outcomes(run_date,order_id,outcome,detail) values(run.run_date,candidate.id,outcome,detail);
  if outcome='confirmed' then confirmed:=confirmed+1;elsif outcome<>'status_changed' then excluded:=excluded+1;end if;
 end loop;
 update private.auto_order_confirmation_runs set confirmed_count=confirmed_count+confirmed,excluded_count=excluded_count+excluded,
  batch_count=batch_count+1 where run_date=run.run_date;
 if seen<p_batch then perform private.finish_auto_order_confirmation_run(run.run_date,'completed');end if;
 return jsonb_build_object('status',case when seen<p_batch then 'finished' else 'continuing' end,'runDate',run.run_date,
  'confirmed',confirmed,'excluded',excluded);
end $function$

CREATE OR REPLACE FUNCTION private.run_monthly_grade_coupons(p_now timestamp with time zone, p_batch integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_month date;
  v_label text;
  v_run private.loyalty_monthly_coupon_runs;
  v_stale date;
  v_member_ids uuid[];
  v_member_grades public.loyalty_grade[] := '{}';
  v_member uuid;
  v_grade public.loyalty_grade;
  v_skipped integer := 0;
  v_scanned integer;
  v_last_member uuid;
  v_live_codes text[];
  v_granted_codes text[] := '{}';
  v_granted_users uuid[] := '{}';
  v_recipients integer := 0;
  v_notified integer := 0;
  v_status text;
begin
  if p_now is null or not isfinite(p_now) or p_batch is null or p_batch not between 1 and 1000 then
    raise invalid_parameter_value using message = 'invalid_monthly_grade_coupon_run';
  end if;

  v_month := date_trunc('month', p_now at time zone 'Asia/Seoul')::date;
  v_label := to_char(v_month, 'YYYY-MM');

  -- 잠금 없는 사전 확인: 그 달 실행이 끝났으면 대부분의 틱은 여기서 끝난다.
  if exists (
    select 1 from private.loyalty_monthly_coupon_runs as run
    where run.grant_month = v_month and run.finished_at is not null
  ) then
    return jsonb_build_object('status', 'already_ran', 'grantMonth', v_label);
  end if;

  -- 끝나지 못한 지난달 실행은 이번 달에 이어 주지 않고 닫는다 — 놓친 몫을 몰아서 주지 않는다.
  for v_stale in
    select run.grant_month
    from private.loyalty_monthly_coupon_runs as run
    where run.grant_month < v_month and run.finished_at is null
    order by run.grant_month
    for update
  loop
    perform private.finish_monthly_grade_coupon_run(v_stale, p_now, 'month_ended');
  end loop;

  -- 그 달 첫 실행이 지급할 정의를 고정한다. 동시 틱은 실행 행 잠금으로 줄을 선다.
  insert into private.loyalty_monthly_coupon_runs (grant_month, started_at, coupon_codes)
  select v_month, p_now, coalesce(array_agg(coupon.code order by coupon.code), '{}'::text[])
  from public.coupons as coupon
  where coupon.grade_benefit_cadence = 'monthly'
    and private.grade_benefit_coupon_grantable(coupon, p_now)
  on conflict (grant_month) do nothing;

  select * into v_run
  from private.loyalty_monthly_coupon_runs as run
  where run.grant_month = v_month
  for update;

  if v_run.finished_at is not null then
    return jsonb_build_object('status', 'already_ran', 'grantMonth', v_label);
  end if;

  if cardinality(v_run.coupon_codes) = 0 then
    perform private.finish_monthly_grade_coupon_run(v_month, p_now, 'no_monthly_coupons');
    return jsonb_build_object('status', 'finished', 'grantMonth', v_label, 'reason', 'no_monthly_coupons', 'granted', 0);
  end if;

  -- 이번 묶음 회원(등급이 WELCOME 보다 높게 캐시된 이용 가능 고객)을 id 순으로 먼저 잠근다(회원 → 쿠폰 순서).
  -- FOR UPDATE: 아래 재산정이 같은 잠금을 쓰고, 코드 입력·주문 경로는 이 회원 잠금에서 먼저 기다린다.
  select coalesce(array_agg(member.id order by member.id), '{}'::uuid[]), count(*)::integer
  into v_member_ids, v_scanned
  from (
    select profile.id
    from public.profiles as profile
    where profile.id > coalesce(v_run.cursor_user_id, '00000000-0000-0000-0000-000000000000'::uuid)
      and private.monthly_grade_coupon_recipient(profile, p_now)
    order by profile.id
    limit p_batch
    for update of profile
  ) as member;

  if v_scanned = 0 then
    perform private.finish_monthly_grade_coupon_run(v_month, p_now, 'completed');
    return jsonb_build_object('status', 'finished', 'grantMonth', v_label, 'reason', 'completed', 'granted', 0);
  end if;

  v_last_member := v_member_ids[v_scanned];

  -- 고정한 정의가 모두 닫혔으면 재산정 없이 끝낸다(잠그기 전 확인 — 아래에서 잠근 뒤 다시 본다).
  if not exists (
    select 1 from public.coupons as coupon
    where coupon.code = any (v_run.coupon_codes)
      and coupon.grade_benefit_cadence = 'monthly'
      and private.grade_benefit_coupon_grantable(coupon, p_now)
  ) then
    perform private.finish_monthly_grade_coupon_run(v_month, p_now, 'coupons_closed');
    return jsonb_build_object('status', 'finished', 'grantMonth', v_label, 'reason', 'coupons_closed', 'granted', 0);
  end if;

  -- '그 시점 등급'을 확정한다. 캐시(profiles.loyalty_grade)는 결제·취소 때만 갱신돼 90일 실적이 빠져도
  -- 남으므로, 기존 재산정을 그대로 불러(강등 이력·승급 쿠폰·승급 알림 포함) 그 결과로 판정한다.
  -- 잠금 대기·교착·취소는 틱을 실패시켜 다음 분에 다시 돌고, 그 밖의 재산정 실패는 그 회원만 이번 달
  -- 지급에서 뺀다(한 회원 때문에 그 달 실행이 멈추지 않게).
  foreach v_member in array v_member_ids loop
    begin
      v_grade := private.recalculate_loyalty_grade(v_member);
    exception
      when lock_not_available or deadlock_detected or query_canceled then
        raise;
      when others then
        raise warning 'monthly grade coupon recalculation skipped for %: % %', v_member, sqlstate, sqlerrm;
        v_grade := null;
        v_skipped := v_skipped + 1;
    end;
    v_member_grades := v_member_grades || coalesce(v_grade, 'welcome'::public.loyalty_grade);
  end loop;

  -- 고정한 정의 중 지금도 지급할 수 있는 것만 잠근다 — 발급 수·한도를 이 트랜잭션이 확정한다.
  select coalesce(array_agg(locked.code order by locked.code), '{}'::text[])
  into v_live_codes
  from (
    select coupon.code
    from public.coupons as coupon
    where coupon.code = any (v_run.coupon_codes)
      and coupon.grade_benefit_cadence = 'monthly'
      and private.grade_benefit_coupon_grantable(coupon, p_now)
    order by coupon.code
    for update of coupon
  ) as locked;

  if cardinality(v_live_codes) = 0 then
    perform private.finish_monthly_grade_coupon_run(v_month, p_now, 'coupons_closed');
    return jsonb_build_object('status', 'finished', 'grantMonth', v_label, 'reason', 'coupons_closed', 'granted', 0);
  end if;

  -- (쿠폰, 회원, 월) 하나에 한 장. 회원 등급이 쿠폰 등급 이상이면 준다. 발급 한도가 남은 만큼만 회원 id 순으로.
  with candidates as (
    select coupon.code, coupon.issue_limit, coupon.issued_count, member.id as user_id,
      row_number() over (partition by coupon.code order by member.id) as position
    from public.coupons as coupon
    join unnest(v_member_ids, v_member_grades) as member(id, grade) on member.grade >= coupon.grade_benefit
    where coupon.code = any (v_live_codes)
      and private.coupon_recipient_reason(coupon.recipient_segment, member.id) is null
      and not exists (
        select 1 from public.user_coupons as held
        where held.grade_benefit_month = v_month
          and held.coupon_code = coupon.code
          and held.user_id = member.id
      )
  ), inserted as (
    insert into public.user_coupons (coupon_code, user_id, issued_source, issued_at, expires_at, grade_benefit_month)
    select candidate.code, candidate.user_id, 'grade_benefit', p_now, private.coupon_issue_expiry(coupon, p_now), v_month
    from candidates as candidate
    join public.coupons as coupon on coupon.code = candidate.code
    where candidate.issue_limit is null
       or candidate.position <= candidate.issue_limit - candidate.issued_count
    order by candidate.code, candidate.user_id
    on conflict (grade_benefit_month, coupon_code, user_id) where grade_benefit_month is not null do nothing
    returning coupon_code, user_id
  )
  select coalesce(array_agg(inserted.coupon_code order by inserted.coupon_code, inserted.user_id), '{}'::text[]),
         coalesce(array_agg(inserted.user_id order by inserted.coupon_code, inserted.user_id), '{}'::uuid[])
  into v_granted_codes, v_granted_users
  from inserted;

  update public.coupons as coupon
  set issued_count = coupon.issued_count + granted.issued
  from (
    select code, count(*)::integer as issued
    from unnest(v_granted_codes) as code
    group by code
  ) as granted
  where coupon.code = granted.code;

  -- 회원·월마다 알림 한 건. 같은 달에 두 번 쓰지 않는다(dedupe).
  with recipients as (
    select recipient.user_id, count(*)::integer as coupons
    from unnest(v_granted_users) as recipient(user_id)
    group by recipient.user_id
  ), sent as (
    insert into public.notifications (
      user_id, type, title, body, link_path, source_type, source_id, dedupe_key
    )
    select
      recipient.user_id,
      'loyalty_monthly_coupons_issued',
      '이번 달 등급 혜택 쿠폰이 도착했어요',
      format('%s 등급 혜택 쿠폰 %s장을 드렸어요. 쿠폰함에서 확인할 수 있어요.', upper(profile.loyalty_grade::text), recipient.coupons),
      '/my/coupons',
      'loyalty_monthly_coupons',
      v_label,
      'loyalty:monthly-coupons:' || recipient.user_id::text || ':' || v_label
    from recipients as recipient
    join public.profiles as profile on profile.id = recipient.user_id
    on conflict (user_id, dedupe_key) do nothing
    returning 1
  )
  select (select count(*)::integer from recipients), (select count(*)::integer from sent)
  into v_recipients, v_notified;

  update private.loyalty_monthly_coupon_runs as run
  set cursor_user_id = v_last_member,
      member_count = run.member_count + v_scanned,
      recipient_count = run.recipient_count + v_recipients,
      granted_count = run.granted_count + cardinality(v_granted_codes),
      notified_count = run.notified_count + v_notified,
      skipped_count = run.skipped_count + v_skipped,
      batch_count = run.batch_count + 1
  where run.grant_month = v_month;

  -- 묶음이 덜 찼다고 끝으로 보지 않는다(잠금 중 조건이 바뀐 행은 LIMIT 위에서 빠진다). 커서 뒤에 대상
  -- 회원이 남았는지로 판정한다.
  if exists (
    select 1 from public.profiles as profile
    where profile.id > v_last_member
      and private.monthly_grade_coupon_recipient(profile, p_now)
  ) then
    v_status := 'continuing';
  else
    perform private.finish_monthly_grade_coupon_run(v_month, p_now, 'completed');
    v_status := 'finished';
  end if;

  return jsonb_build_object(
    'status', v_status,
    'grantMonth', v_label,
    'members', v_scanned,
    'granted', cardinality(v_granted_codes),
    'recipients', v_recipients,
    'notified', v_notified,
    'skipped', v_skipped
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.save_goods_options(target_id text, target_rows jsonb, baseline jsonb, is_new boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 actor_id uuid:=auth.uid(); good public.goods%rowtype; variant public.goods_variants%rowtype;
 item jsonb; option_id uuid; retained uuid[]:='{}'::uuid[]; ordinal integer:=0; expected_qty integer; desired_qty integer;
 current_ids jsonb; before_rows jsonb; saved_rows jsonb; seen_attributes jsonb[]:='{}'::jsonb[]; desired_price bigint;
begin
 if actor_id is null then raise exception 'auth_required' using errcode='28000'; end if;
 if not public.is_staff() then raise exception 'forbidden' using errcode='42501'; end if;
 if target_rows is null or jsonb_typeof(target_rows)<>'array' or jsonb_array_length(target_rows) not between 1 and 100
   or baseline is null or jsonb_typeof(baseline)<>'array' then raise check_violation using message='invalid_goods_options'; end if;
 select * into good from public.goods where id=target_id for update;
 if not found or good.archived_at is not null then raise check_violation using message='good_unavailable'; end if;
 perform 1 from public.goods_variants where good_id=target_id order by id for update;
 select coalesce(jsonb_agg(id::text order by id),'[]') into current_ids from public.goods_variants where good_id=target_id and archived_at is null;
 if not is_new and current_ids is distinct from (select coalesce(jsonb_agg(value order by value),'[]') from jsonb_array_elements_text(baseline)) then
   raise sqlstate 'PT409' using message='goods_options_changed';
 end if;
 select jsonb_agg(to_jsonb(v) order by v.sort_order,v.id) into before_rows from public.goods_variants v where v.good_id=target_id;
 -- The first submitted row becomes the default. The deferred invariant checks the complete batch.
 update public.goods_variants set is_default=false where good_id=target_id and is_default
   and id::text is distinct from nullif(target_rows->0->>'id','');
 if is_new then delete from public.goods_variants where good_id=target_id; end if;
 for item in select value from jsonb_array_elements(target_rows) loop
   if jsonb_typeof(item)<>'object' or char_length(btrim(coalesce(item->>'name',''))) not between 1 and 200
     or jsonb_typeof(item->'attributes') is distinct from 'object'
     or exists(select 1 from jsonb_each(item->'attributes') a where char_length(btrim(a.key)) not between 1 and 40
       or jsonb_typeof(a.value)<>'string' or char_length(btrim(a.value#>>'{}')) not between 1 and 80)
     or coalesce(item->>'extraPrice','') !~ '^[0-9]+$' or coalesce(item->>'stockQty','') !~ '^[0-9]+$'
     or char_length(btrim(coalesce(item->>'code','')))>120
     or coalesce(jsonb_typeof(item->'code'),'null') not in ('string','null')
     or item->'attributes'=any(seen_attributes) then raise check_violation using message='invalid_goods_options'; end if;
   if item?'lowStockThreshold' and item->'lowStockThreshold'<>'null'::jsonb and (
     jsonb_typeof(item->'lowStockThreshold')<>'number' or item->>'lowStockThreshold' !~ '^[0-9]+$'
     or (item->>'lowStockThreshold')::numeric>2147483647
   ) then raise check_violation using message='invalid_goods_options'; end if;
   if exists(select 1 from unnest(array['orderMaxQty','memberMaxQty']) limit_key
     where item?limit_key and item->limit_key<>'null'::jsonb and (jsonb_typeof(item->limit_key)<>'number'
       or item->>limit_key !~ '^[1-9][0-9]*$' or (item->>limit_key)::numeric>2147483647)) then
     raise check_violation using message='invalid_goods_options'; end if;
   if item?'isActive' and jsonb_typeof(item->'isActive') is distinct from 'boolean' then
     raise check_violation using message='invalid_goods_options'; end if;
   seen_attributes:=array_append(seen_attributes,item->'attributes');
   desired_price:=good.price::bigint+(item->>'extraPrice')::bigint;
   desired_qty:=(item->>'stockQty')::integer;
   if desired_price>2147483647 then raise numeric_value_out_of_range using message='invalid_goods_options'; end if;
   option_id:=nullif(item->>'id','')::uuid;
   if option_id is not null then
     select * into variant from public.goods_variants where id=option_id and good_id=target_id;
     if not found or option_id=any(retained) or coalesce(item->>'expectedStockQty','') !~ '^[0-9]+$' then
       raise check_violation using message='invalid_goods_options'; end if;
     expected_qty:=(item->>'expectedStockQty')::integer;
     -- An untouched quantity is metadata, not an instruction to restore stock sold meanwhile.
     if desired_qty<>expected_qty then
       if variant.stock_qty<>expected_qty then raise sqlstate 'PT409' using message='stock_changed'; end if;
       perform private.change_goods_variant_stock(target_id,option_id,desired_qty::bigint-variant.stock_qty);
     end if;
     update public.goods_variants set name=btrim(item->>'name'),attributes=item->'attributes',price=desired_price::integer,
       low_stock_threshold=case when item?'lowStockThreshold' then (item->>'lowStockThreshold')::integer else variant.low_stock_threshold end,
       order_max_qty=case when item?'orderMaxQty' then (item->>'orderMaxQty')::integer else variant.order_max_qty end,
       member_max_qty=case when item?'memberMaxQty' then (item->>'memberMaxQty')::integer else variant.member_max_qty end,
       archived_at=case when item?'isActive' then case when (item->>'isActive')::boolean then null
         else coalesce(variant.archived_at,clock_timestamp()) end else variant.archived_at end,
       code=coalesce(nullif(item->>'code',''),variant.code),sort_order=ordinal,is_default=(ordinal=0) where id=option_id;
   else
     insert into public.goods_variants(good_id,name,attributes,price,code,sort_order,is_default,low_stock_threshold,archived_at,order_max_qty,member_max_qty)
       values(target_id,btrim(item->>'name'),item->'attributes',desired_price::integer,nullif(item->>'code',''),ordinal,ordinal=0,
         (item->>'lowStockThreshold')::integer,
         case when coalesce((item->>'isActive')::boolean,true) then null else clock_timestamp() end,
         (item->>'orderMaxQty')::integer,(item->>'memberMaxQty')::integer)
       returning id into option_id;
     if desired_qty<>0 then perform private.change_goods_variant_stock(target_id,option_id,desired_qty); end if;
   end if;
   retained:=array_append(retained,option_id); ordinal:=ordinal+1;
 end loop;
 for variant in select * from public.goods_variants where good_id=target_id and archived_at is null and not(id=any(retained)) order by id loop
   if exists(select 1 from public.order_items where variant_id=variant.id)
     or exists(select 1 from public.cart_items where variant_id=variant.id)
     or exists(select 1 from public.order_claim_reshipment_items where variant_id=variant.id or source_variant_id=variant.id) then
     update public.goods_variants set archived_at=now() where id=variant.id;
   else
     -- Later features may attach immutable history without an order/cart row.
     -- Let their FK be the lifetime boundary instead of naming not-yet-created
     -- tables here. A failed DELETE and all of its cascades roll back together.
     begin
       delete from public.goods_variants where id=variant.id;
     exception when foreign_key_violation then
       update public.goods_variants set archived_at=coalesce(archived_at,clock_timestamp()) where id=variant.id;
     end;
   end if;
 end loop;
 -- Bind metadata to the exact INSERT/UPDATE results while the full option set
 -- is still locked. Attributes/sort order can also belong to historical rows,
 -- including newly submitted stopped options, so they are not option identity.
 select jsonb_agg(submitted.value || jsonb_build_object('id',retained[submitted.ordinality::integer]) order by submitted.ordinality)
   into saved_rows
   from jsonb_array_elements(target_rows) with ordinality as submitted(value,ordinality);
 perform private.save_goods_variant_external_identities(target_id,saved_rows,actor_id);
 perform private.save_goods_variant_purchase_costs(target_id,saved_rows);
 insert into public.audit_log(actor_id,action,target,diff) values(actor_id,'admin.good.options_saved','goods:'||target_id,
   jsonb_build_object('before',before_rows,'after',(select jsonb_agg(to_jsonb(v) order by v.sort_order,v.id) from public.goods_variants v where v.good_id=target_id)));
end;
$function$

CREATE OR REPLACE FUNCTION private.save_goods_variant_external_identities(target_good_id text, target_rows jsonb, target_actor uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := coalesce(target_actor, auth.uid());
  item jsonb;
  ordinal integer;
  variant_id uuid;
  external_identity jsonb;
  has_external_fields boolean;
  code_value text;
  name_value text;
  barcode_value text;
  expected_updated_at timestamptz;
begin
  if actor_id is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if target_rows is null or jsonb_typeof(target_rows) is distinct from 'array' then
    raise check_violation using message = 'invalid_goods_options';
  end if;

  for item, ordinal in
    select value, ordinality::integer
    from jsonb_array_elements(target_rows) with ordinality
  loop
    if jsonb_typeof(item) is distinct from 'object' then
      raise check_violation using message = 'invalid_goods_options';
    end if;
    external_identity := case
      when item ? 'externalIdentity' then item -> 'externalIdentity'
      else item
    end;
    has_external_fields :=
      external_identity ? 'erpCode' or external_identity ? 'erpName' or external_identity ? 'barcode'
      or external_identity ? 'erp_code' or external_identity ? 'erp_name';
    if not has_external_fields then
      continue;
    end if;
    if jsonb_typeof(external_identity) is distinct from 'object' then
      raise check_violation using message = 'invalid_goods_variant_external_identity';
    end if;

    code_value := case when external_identity ? 'erpCode' then external_identity ->> 'erpCode' else external_identity ->> 'erp_code' end;
    name_value := case when external_identity ? 'erpName' then external_identity ->> 'erpName' else external_identity ->> 'erp_name' end;
    barcode_value := external_identity ->> 'barcode';
    expected_updated_at := null;
    if external_identity ? 'externalUpdatedAt' or external_identity ? 'external_updated_at' then
      begin
        expected_updated_at := coalesce(external_identity ->> 'externalUpdatedAt', external_identity ->> 'external_updated_at')::timestamptz;
      exception when others then
        raise check_violation using message = 'invalid_goods_variant_external_identity';
      end;
    end if;

    if nullif(item ->> 'id', '') is not null then
      if (item ->> 'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        raise check_violation using message = 'invalid_goods_variant_external_identity';
      end if;
      variant_id := (item ->> 'id')::uuid;
    else
      select variant.id into variant_id
      from public.goods_variants variant
      where variant.good_id = target_good_id and variant.sort_order = ordinal - 1
        and variant.attributes = coalesce(item -> 'attributes', '{}'::jsonb)
      order by variant.id
      limit 1;
    end if;
    if variant_id is null then
      raise check_violation using message = 'goods_variant_not_found';
    end if;

    perform private.save_goods_variant_external_identity(
      target_good_id, variant_id, code_value, name_value, barcode_value, expected_updated_at, actor_id
    );
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION private.save_goods_variant_external_identity(target_good_id text, target_variant_id uuid, target_erp_code text, target_erp_name text, target_barcode text, target_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, target_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := coalesce(target_actor, auth.uid());
  variant public.goods_variants;
  previous private.goods_variant_external_identity;
  saved private.goods_variant_external_identity;
  previous_json jsonb;
  next_erp_code text := nullif(btrim(target_erp_code), '');
  next_erp_name text := nullif(btrim(target_erp_name), '');
  next_barcode text := nullif(btrim(target_barcode), '');
begin
  if actor_id is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if target_good_id is null or btrim(target_good_id) = '' or char_length(target_good_id) > 200 then
    raise invalid_parameter_value using message = 'invalid_goods_variant_external_identity';
  end if;

  -- Keep the catalog lock order used by the option editor and checkout:
  -- parent good, then variant, then its private external_identity row.
  perform 1 from public.goods where id = target_good_id for update;
  if not found then
    raise no_data_found using message = 'goods_variant_not_found';
  end if;
  select * into variant
  from public.goods_variants
  where id = target_variant_id and good_id = target_good_id
  for update;
  if not found then
    raise no_data_found using message = 'goods_variant_not_found';
  end if;

  select * into previous
  from private.goods_variant_external_identity
  where variant_id = target_variant_id
  for update;

  -- Presence-aware optimistic concurrency: NULL expected means the editor saw
  -- no external_identity row. It is valid for a first write, but conflicts when another
  -- operator created a row after that read. Conversely, an existing row must
  -- always be submitted with its exact revision, including when it is being
  -- cleared.
  if (case when previous.variant_id is null then null::timestamptz else previous.updated_at end)
    is distinct from target_expected_updated_at then
    -- PT409 is a business stale-write response. Using PostgreSQL's 40001 here
    -- makes PostgREST retry the RPC as if it were a transient transaction
    -- serialization failure.
    raise exception using errcode = 'PT409', message = 'goods_variant_external_identity_changed';
  end if;

  if next_erp_code is not null and char_length(next_erp_code) > 120
    or next_erp_name is not null and char_length(next_erp_name) > 200
    or next_barcode is not null and char_length(next_barcode) > 120 then
    raise check_violation using message = 'invalid_goods_variant_external_identity';
  end if;

  previous_json := jsonb_build_object(
    'erpCode', case when previous.variant_id is null then null else previous.erp_code end,
    'erpName', case when previous.variant_id is null then null else previous.erp_name end,
    'barcode', case when previous.variant_id is null then null else previous.barcode end
  );

  if next_erp_code is null and next_erp_name is null and next_barcode is null then
    delete from private.goods_variant_external_identity where variant_id = target_variant_id;
  else
    insert into private.goods_variant_external_identity (variant_id, erp_code, erp_name, barcode)
    values (target_variant_id, next_erp_code, next_erp_name, next_barcode)
    on conflict (variant_id) do update set
      erp_code = excluded.erp_code,
      erp_name = excluded.erp_name,
      barcode = excluded.barcode;
  end if;

  select * into saved
  from private.goods_variant_external_identity
  where variant_id = target_variant_id;

  if previous_json is distinct from jsonb_build_object(
    'erpCode', case when saved.variant_id is null then null else saved.erp_code end,
    'erpName', case when saved.variant_id is null then null else saved.erp_name end,
    'barcode', case when saved.variant_id is null then null else saved.barcode end
  ) then
    insert into public.audit_log(actor_id, action, target, diff)
    values (
      actor_id,
      'admin.good.variant_external_identity_saved',
      'goods_variant:' || target_variant_id::text,
      jsonb_build_object(
        'before', previous_json,
        'after', jsonb_build_object(
          'erpCode', case when saved.variant_id is null then null else saved.erp_code end,
          'erpName', case when saved.variant_id is null then null else saved.erp_name end,
          'barcode', case when saved.variant_id is null then null else saved.barcode end
        )
      )
    );
  end if;

  return jsonb_build_object(
    'variantId', target_variant_id,
    'goodId', target_good_id,
    'erpCode', case when saved.variant_id is null then null else saved.erp_code end,
    'erpName', case when saved.variant_id is null then null else saved.erp_name end,
    'barcode', case when saved.variant_id is null then null else saved.barcode end,
    'updatedAt', case when saved.variant_id is null then null else saved.updated_at end
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.save_goods_variant_purchase_cost(p_good_id text, p_variant_id uuid, p_unit_cost_krw integer, p_tax_basis text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  previous private.goods_variant_purchase_costs;
  saved private.goods_variant_purchase_costs;
  normalized_tax text:=nullif(btrim(p_tax_basis),'');
  change_id uuid;
  previous_value jsonb;
  next_value jsonb;
begin
  if not private.can_manage_goods_purchase_costs() then raise insufficient_privilege using message='purchase_cost_admin_required'; end if;
  if p_good_id is null or nullif(btrim(p_good_id),'') is null or p_variant_id is null
    or p_unit_cost_krw<0 or (p_unit_cost_krw is null)<>(normalized_tax is null)
    or (normalized_tax is not null and normalized_tax not in ('included','excluded','exempt'))
    or (p_expected_revision is not null and p_expected_revision<1) then
    raise check_violation using message='invalid_goods_purchase_cost';
  end if;
  -- Same parent->option order as catalog, stock and checkout writers.
  perform 1 from public.goods where id=p_good_id for update;
  if not found then raise no_data_found using message='goods_variant_not_found'; end if;
  perform 1 from public.goods_variants where id=p_variant_id and good_id=p_good_id for update;
  if not found then raise no_data_found using message='goods_variant_not_found'; end if;
  select * into previous from private.goods_variant_purchase_costs where variant_id=p_variant_id for update;
  if found then
    if p_expected_revision is null or p_expected_revision<>previous.revision then
      raise sqlstate 'PT409' using message='goods_purchase_cost_changed';
    end if;
    if (previous.unit_cost_krw,previous.tax_basis) is not distinct from (p_unit_cost_krw,normalized_tax) then
      return jsonb_build_object('revision',previous.revision,'changed',false);
    end if;
    previous_value:=jsonb_build_object('unitCostKrw',previous.unit_cost_krw,'taxBasis',previous.tax_basis);
    update private.goods_variant_purchase_costs set unit_cost_krw=p_unit_cost_krw,tax_basis=normalized_tax,
      revision=revision+1,updated_at=clock_timestamp(),updated_by=auth.uid()
    where variant_id=p_variant_id returning * into saved;
  else
    if p_expected_revision is not null then raise sqlstate 'PT409' using message='goods_purchase_cost_changed'; end if;
    if p_unit_cost_krw is null then return jsonb_build_object('revision',null,'changed',false); end if;
    insert into private.goods_variant_purchase_costs(variant_id,unit_cost_krw,tax_basis,revision,updated_by)
    values(p_variant_id,p_unit_cost_krw,normalized_tax,1,auth.uid()) returning * into saved;
  end if;
  next_value:=jsonb_build_object('unitCostKrw',saved.unit_cost_krw,'taxBasis',saved.tax_basis);
  insert into private.goods_variant_purchase_cost_changes(variant_id,good_id_snapshot,revision,before_value,after_value,actor_id)
  values(p_variant_id,p_good_id,saved.revision,previous_value,next_value,auth.uid()) returning id into change_id;
  -- audit_log is staff-readable. Never place a cost amount or tax basis in it.
  insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.good.purchase_cost_saved','goods:'||p_good_id,
    jsonb_build_object('variantId',p_variant_id,'changeId',change_id,'detailsAccess','admin'));
  return jsonb_build_object('revision',saved.revision,'changed',true);
end $function$

CREATE OR REPLACE FUNCTION private.save_goods_variant_purchase_costs(p_good_id text, p_rows jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb; ordinal integer; cost jsonb; variant_key uuid; amount integer; basis text; expected integer;
begin
  if jsonb_typeof(p_rows) is distinct from 'array' then raise check_violation using message='invalid_goods_options'; end if;
  for item,ordinal in select value,ordinality::integer from jsonb_array_elements(p_rows) with ordinality loop
    if not (item?'purchaseCost') then continue; end if;
    if not private.can_manage_goods_purchase_costs() then raise insufficient_privilege using message='purchase_cost_admin_required'; end if;
    cost:=item->'purchaseCost'; amount:=null; basis:=null; expected:=null;
    if jsonb_typeof(cost) is distinct from 'object' or not(cost ?& array['unitCostKrw','taxBasis','expectedRevision'])
      or exists(select 1 from jsonb_object_keys(cost) key where key not in ('unitCostKrw','taxBasis','expectedRevision')) then
      raise check_violation using message='invalid_goods_purchase_cost';
    end if;
    if jsonb_typeof(cost->'unitCostKrw')<>'null' then
      if jsonb_typeof(cost->'unitCostKrw')<>'number' or cost->>'unitCostKrw' !~ '^[0-9]+$'
        or (cost->>'unitCostKrw')::numeric>2147483647 then
        raise check_violation using message='invalid_goods_purchase_cost';
      end if;
      amount:=(cost->>'unitCostKrw')::integer;
    end if;
    if jsonb_typeof(cost->'taxBasis')<>'null' then
      if jsonb_typeof(cost->'taxBasis')<>'string' then raise check_violation using message='invalid_goods_purchase_cost'; end if;
      basis:=cost->>'taxBasis';
    end if;
    if jsonb_typeof(cost->'expectedRevision')<>'null' then
      if jsonb_typeof(cost->'expectedRevision')<>'number' or cost->>'expectedRevision' !~ '^[1-9][0-9]*$'
        or (cost->>'expectedRevision')::numeric>2147483647 then
        raise check_violation using message='invalid_goods_purchase_cost';
      end if;
      expected:=(cost->>'expectedRevision')::integer;
    end if;
    variant_key:=null;
    if nullif(item->>'id','') is not null then variant_key:=(item->>'id')::uuid;
    else
      select id into variant_key from public.goods_variants where good_id=p_good_id and sort_order=ordinal-1
        and attributes=coalesce(item->'attributes','{}'::jsonb) order by id limit 1;
    end if;
    if variant_key is null then raise no_data_found using message='goods_variant_not_found'; end if;
    perform private.save_goods_variant_purchase_cost(p_good_id,variant_key,amount,basis,expected);
  end loop;
end $function$

CREATE OR REPLACE FUNCTION private.save_goods_workspace_extra_sections(p_good_id text, p_sections jsonb, p_new_variants uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
  session_id uuid;
  section text;
  entry jsonb;
  value jsonb;
  variant uuid;
  saved jsonb := '{}'::jsonb;
  result jsonb;
  results jsonb;
  good_updated timestamptz;
  revision bigint;
  good_row public.goods;
  origin_doc jsonb;
  group_revision integer;
  uuid_pattern constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
begin
  if p_good_id is null or jsonb_typeof(p_sections) is distinct from 'object' then
    raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
  end if;
  -- 로그인 세션에 묶인 저장(수령 방식·제작·묶음그룹)은 지금 요청의 세션으로 부른다. 없으면 각 RPC가 권한 오류로 거절한다.
  session_id := case when coalesce(auth.jwt()->>'session_id', '') ~ uuid_pattern then (auth.jwt()->>'session_id')::uuid end;
  foreach section in array array['purchaseCosts','pricePeriods','additional','benefits','afterSales','sizeChart',
    'listingColors','transactionTerms','shippingChargeGroup','subscriptionPolicy','fulfillment','production','optionSaleMode'] loop
    continue when not (p_sections ? section);
    value := p_sections->section;
    begin
      case section
      when 'optionSaleMode' then
        if jsonb_typeof(value) is distinct from 'string' or value #>> '{}' not in ('select','random') then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        -- 새 상품은 옵션 선택 판매로 만들어진다. 랜덤 판매를 고른 경우만 전환하고, 조건은 기존 전환 RPC가 판정한다.
        if value #>> '{}' = 'random' then
          select updated_at into good_updated from public.goods where id = p_good_id;
          result := public.admin_set_goods_option_sale_mode(p_good_id, 'random', good_updated);
        else
          result := jsonb_build_object('optionSaleMode', 'select');
        end if;
      when 'purchaseCosts' then
        if jsonb_typeof(value) is distinct from 'array' or jsonb_array_length(value) > 100 then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        results := '[]'::jsonb;
        for entry in select item from jsonb_array_elements(value) item loop
          if jsonb_typeof(entry) is distinct from 'object'
            or (select array_agg(key order by key) from jsonb_object_keys(entry) key) is distinct from array['taxBasis','unitCostKrw','variant']
            or jsonb_typeof(entry->'unitCostKrw') not in ('null','number')
            or (jsonb_typeof(entry->'unitCostKrw') = 'number' and (entry->>'unitCostKrw' !~ '^(0|[1-9][0-9]*)$' or (entry->>'unitCostKrw')::numeric > 2147483647))
            or jsonb_typeof(entry->'taxBasis') not in ('null','string') then
            raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
          end if;
          variant := private.resolve_goods_workspace_variant(p_good_id, entry->'variant', p_new_variants, 'purchase_cost');
          results := results || jsonb_build_array(public.admin_save_goods_variant_purchase_cost(p_good_id, variant,
            (entry->>'unitCostKrw')::integer, entry->>'taxBasis', null) || jsonb_build_object('variantId', variant));
        end loop;
        result := results;
      when 'pricePeriods' then
        if jsonb_typeof(value) is distinct from 'array' or jsonb_array_length(value) > 100 then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        results := '[]'::jsonb;
        for entry in select item from jsonb_array_elements(value) item loop
          if jsonb_typeof(entry) is distinct from 'object'
            or (select array_agg(key order by key) from jsonb_object_keys(entry) key) is distinct from array['period','variant']
            or jsonb_typeof(entry->'period') is distinct from 'object' then
            raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
          end if;
          variant := private.resolve_goods_workspace_variant(p_good_id, entry->'variant', p_new_variants, 'price_period');
          results := results || jsonb_build_array(public.admin_save_goods_price_period(p_good_id, variant, null, entry->'period', null)
            || jsonb_build_object('variantId', variant));
        end loop;
        result := results;
      when 'additional' then
        if jsonb_typeof(value) is distinct from 'array' or jsonb_array_length(value) > 50
          or exists(select 1 from jsonb_array_elements(value) item where jsonb_typeof(item) is distinct from 'string') then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        result := public.admin_save_goods_additional(p_good_id, array(select item from jsonb_array_elements_text(value) item),
          (select sets.revision from private.goods_additional_sets sets where sets.good_id = p_good_id));
      when 'benefits' then
        select coalesce(max(content.revision), 0) into revision from private.goods_benefit_content content where content.good_id = p_good_id;
        result := public.admin_save_goods_benefit_content(p_good_id, revision::integer, gen_random_uuid(), value);
      when 'afterSales' then
        select coalesce(max(content.revision), 0) into revision from private.goods_after_sales_content content where content.good_id = p_good_id;
        result := public.admin_save_goods_after_sales_content(p_good_id, revision::integer, gen_random_uuid(), value);
      when 'sizeChart' then
        select coalesce(max(chart.revision), 0) into revision from private.goods_size_charts chart where chart.good_id = p_good_id;
        result := public.admin_save_goods_size_chart(p_good_id, revision::integer, gen_random_uuid(), value);
      when 'listingColors' then
        select coalesce(max(colors.revision), 0) into revision from private.goods_listing_colors colors where colors.good_id = p_good_id;
        result := public.admin_save_goods_listing_colors(p_good_id, value, revision, gen_random_uuid());
      when 'transactionTerms' then
        if jsonb_typeof(value) is distinct from 'object'
          or exists(select 1 from jsonb_object_keys(value) key where key not in ('volume','delivery'))
          or coalesce(jsonb_typeof(value->'volume'), 'null') not in ('null','object')
          or coalesce(jsonb_typeof(value->'delivery'), 'null') not in ('null','object') then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        select coalesce(max(config.revision), 0) into revision from private.goods_transaction_configs config where config.good_id = p_good_id;
        select updated_at into good_updated from public.goods where id = p_good_id;
        result := public.admin_save_good_transaction_terms(p_good_id, revision::integer, good_updated,
          case when jsonb_typeof(value->'volume') = 'object' then value->'volume' end,
          case when jsonb_typeof(value->'delivery') = 'object' then value->'delivery' end,
          gen_random_uuid(), actor);
      when 'shippingChargeGroup' then
        -- 화면이 고른 그룹과 그때 본 그룹 버전만 받는다. 상품·출고지 기준값은 같은 트랜잭션의 지금 저장값으로 만든다.
        if jsonb_typeof(value) is distinct from 'object'
          or (select array_agg(key order by key) from jsonb_object_keys(value) key) is distinct from array['expectedRevision','groupId']
          or jsonb_typeof(value->'groupId') is distinct from 'string' or value->>'groupId' !~ uuid_pattern
          or jsonb_typeof(value->'expectedRevision') is distinct from 'number' or value->>'expectedRevision' !~ '^[1-9][0-9]*$'
          or (value->>'expectedRevision')::numeric > 2147483647 then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        select * into good_row from public.goods where id = p_good_id;
        origin_doc := case when good_row.origin_id is null then null else private.shipping_charge_group_origin(good_row.origin_id) end;
        result := public.admin_assign_shipping_charge_group(jsonb_build_object(
          'operationId', gen_random_uuid(), 'command', 'assign', 'groupId', lower(value->>'groupId'),
          'expectedRevision', (value->>'expectedRevision')::integer, 'expectedActorId', actor, 'expectedSessionId', session_id,
          'origins', case when origin_doc is null then '[]'::jsonb else jsonb_build_array(origin_doc) end,
          'goods', jsonb_build_array(private.shipping_charge_group_good_guard(good_row))));
      when 'subscriptionPolicy' then
        if jsonb_typeof(value) is distinct from 'object'
          or (select array_agg(key order by key) from jsonb_object_keys(value) key) is distinct from array['enabled','intervals','message']
          or jsonb_typeof(value->'enabled') is distinct from 'boolean' or jsonb_typeof(value->'message') is distinct from 'string' then
          raise invalid_parameter_value using message = 'invalid_goods_workspace_request';
        end if;
        select coalesce(max(policy.revision), 0) into revision from private.goods_subscription_policies policy where policy.good_id = p_good_id;
        select updated_at into good_updated from public.goods where id = p_good_id;
        result := public.admin_save_goods_subscription_policy(actor, p_good_id, revision, good_updated, gen_random_uuid(),
          (value->>'enabled')::boolean, value->'intervals', value->>'message');
      when 'fulfillment' then
        select coalesce(max(settings.revision), 0) into revision from private.goods_fulfillment_settings settings where settings.good_id = p_good_id;
        result := public.admin_save_goods_fulfillment(p_good_id, value, revision, gen_random_uuid(), actor, session_id);
      when 'production' then
        select coalesce(max(settings.revision), 0) into revision from private.goods_production_settings settings where settings.good_id = p_good_id;
        result := public.admin_save_goods_production(p_good_id, value, revision, gen_random_uuid(), actor, session_id);
      end case;
    exception when others then
      -- 어느 섹션이 실패했는지 담아 다시 던진다(같은 오류 코드). 래퍼 트랜잭션 전체가 되돌아간다.
      raise exception using errcode = sqlstate, message = 'goods_workspace_section_failed:' || section || ':' || sqlerrm;
    end;
    saved := saved || jsonb_build_object(section, coalesce(result, 'null'::jsonb));
  end loop;
  return saved;
end
$function$

CREATE OR REPLACE FUNCTION private.save_home_curation(target_operation_id uuid, target_curation_id uuid, target_kind text, target_ip_id text, target_title text, target_image_path text, target_link_path text, target_display_order integer, target_active_from timestamp with time zone, target_active_to timestamp with time zone, target_enabled boolean, target_slot text, target_payload jsonb, target_expected_updated_at timestamp with time zone, require_saved_version boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  -- Alias with a column-safe name: inside the claim UPDATE below, a bare
  -- actor_id would be ambiguous against admin_artwork_upload_claims.actor_id.
  claim_owner_id uuid := actor_id;
  normalized_kind text := pg_catalog.btrim(target_kind);
  normalized_ip_id text := nullif(pg_catalog.btrim(target_ip_id), '');
  normalized_title text := pg_catalog.btrim(target_title);
  normalized_image_path text := nullif(pg_catalog.btrim(target_image_path), '');
  normalized_link_path text := nullif(pg_catalog.btrim(target_link_path),'');
  normalized_slot text := nullif(pg_catalog.btrim(target_slot), '');
  normalized_payload jsonb := case
    when target_payload is null or target_payload = '{}'::jsonb then null
    else target_payload
  end;
  allowed_payload_keys text[];
  payload_key text;
  payload_text_value text;
  payload_good_ids jsonb;
  payload_good_id_limit integer;
  payload_good_id text;
  payload_mobile_image_path text;
  previous_mobile_image_path text;
  referenced_archived_at timestamptz;
  request_payload jsonb;
  previous_payload jsonb := 'null'::jsonb;
  after_payload jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  previous_curation public.home_curations%rowtype;
  curation_exists boolean := false;
begin
  perform private.require_operator_capability('store.manage',false);

  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  perform 1 from public.profiles where id=actor_id and role in ('staff','admin') and suspended_at is null for share;
  if not found then
    raise insufficient_privilege using message = 'forbidden';
  end if;

  if target_operation_id is null then
    raise null_value_not_allowed using message = 'invalid_operation_id';
  end if;
  if target_curation_id is null then
    raise null_value_not_allowed using message = 'invalid_curation_id';
  end if;
  if normalized_kind is null
    or normalized_kind not in (
      'hero', 'featured_ip', 'announcement',
      'notice_strip', 'notice_bar', 'editor_pick', 'band_banner', 'best_tab', 'benefit', 'sales_best', 'review_best', 'product_mosaic', 'product_collection',
      'collection_banner', 'search_terms'
    )
  then
    raise invalid_parameter_value using message = 'invalid_curation_kind';
  end if;
  if normalized_title is null
    or pg_catalog.char_length(normalized_title) not between (case when normalized_kind='hero' then 0 else 1 end) and 120
    or (normalized_kind in ('sales_best','review_best','product_mosaic','product_collection') and pg_catalog.char_length(normalized_title)>15)
    -- The text notice bar is one short line of copy in the global shell.
    or (normalized_kind='notice_bar' and (pg_catalog.char_length(normalized_title)>60 or normalized_title ~ '[[:cntrl:]]'))
    -- Collection banner copy and the search-term list name are one short line.
    or (normalized_kind in ('collection_banner','search_terms') and (pg_catalog.char_length(normalized_title)>40 or normalized_title ~ '[[:cntrl:]]'))
  then
    raise invalid_parameter_value using message = 'invalid_curation_title';
  end if;
  if normalized_kind = 'featured_ip' and normalized_ip_id is null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind <> 'featured_ip' and normalized_ip_id is not null then
    raise invalid_parameter_value using message = 'invalid_curation_ip';
  end if;
  if normalized_kind in ('hero', 'notice_strip', 'editor_pick', 'band_banner', 'collection_banner')
    and normalized_image_path is null
  then
    raise check_violation using message = 'curation_image_required';
  end if;
  if normalized_kind = 'notice_bar' and normalized_image_path is not null then
    raise invalid_parameter_value using message = 'invalid_curation_notice';
  end if;
  -- Suggested search terms are text chips only.
  if normalized_kind = 'search_terms' and normalized_image_path is not null then
    raise invalid_parameter_value using message = 'invalid_curation_search_terms';
  end if;
  if normalized_image_path is not null
    and normalized_image_path !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  then
    raise check_violation using message = 'invalid_curation_image_path';
  end if;
  if (normalized_link_path is null and normalized_kind not in ('hero','product_collection','notice_bar','collection_banner','search_terms'))
    or (normalized_kind in ('product_collection','search_terms') and normalized_link_path is not null)
    or (normalized_link_path is not null and not private.is_safe_home_curation_link(normalized_link_path))
  then
    raise invalid_parameter_value using message = 'invalid_curation_link_path';
  end if;
  if target_display_order is null or target_display_order < 0 then
    raise invalid_parameter_value using message = 'invalid_curation_display_order';
  end if;
  if target_active_from is null then
    raise null_value_not_allowed using message = 'invalid_curation_active_from';
  end if;
  if not pg_catalog.isfinite(target_active_from) then
    raise invalid_parameter_value using message = 'invalid_curation_active_from';
  end if;
  if target_active_to is not null
    and (
      not pg_catalog.isfinite(target_active_to)
      or target_active_to <= target_active_from
    )
  then
    raise check_violation using message = 'invalid_curation_active_window';
  end if;
  if target_enabled is null then
    raise null_value_not_allowed using message = 'invalid_curation_enabled';
  end if;

  if normalized_kind = 'best_tab' then
    if normalized_slot is null or normalized_slot not in ('category', 'popular') then
      raise invalid_parameter_value using message = 'invalid_curation_slot';
    end if;
  -- A collection banner names the collection page it heads: the whole goods
  -- shop slider, BEST or NEW. Category display pages carry no banner.
  elsif normalized_kind = 'collection_banner' then
    if normalized_slot is null or normalized_slot not in ('all', 'best', 'new') then
      raise invalid_parameter_value using message = 'invalid_curation_slot';
    end if;
  elsif normalized_slot is not null then
    raise invalid_parameter_value using message = 'invalid_curation_slot';
  end if;

  -- Per-kind payload whitelist. Unknown keys are rejected outright so typos
  -- never ship silently dead configuration.
  allowed_payload_keys := case normalized_kind
    when 'hero' then array['subtitle', 'mobile_image_path', 'alt_enabled', 'alt_title', 'alt_content', 'image_dim', 'text_color']
    when 'notice_strip' then array['mobile_image_path', 'page_types']
    when 'notice_bar' then array['cta_label', 'page_types']
    when 'editor_pick' then array['badge', 'description']
    when 'band_banner' then array['subcopy', 'good_ids']
    when 'best_tab' then array['good_ids', 'selection_mode', 'item_count']
    when 'benefit' then array['description']
    when 'sales_best' then array['exposure_mode','period']
    when 'review_best' then array['selection_mode','good_ids']
    when 'product_mosaic' then array['mosaic_title','mosaic_subtitle','slots']
    when 'product_collection' then array['layout','image_shape','item_count','good_ids']
    when 'collection_banner' then array['subtitle', 'mobile_image_path', 'image_alt', 'image_dim', 'text_color']
    when 'search_terms' then array['terms']
    else array[]::text[]
  end;

  if normalized_payload is not null then
    if pg_catalog.jsonb_typeof(normalized_payload) <> 'object' then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    if pg_catalog.cardinality(allowed_payload_keys) = 0 then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;
    for payload_key in
      select key from pg_catalog.jsonb_object_keys(normalized_payload) as keys(key)
    loop
      if not payload_key = any (allowed_payload_keys) then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
    end loop;

    for payload_key in
      select unnest from pg_catalog.unnest(array['subtitle', 'badge', 'description', 'subcopy'])
    loop
      if normalized_payload ? payload_key then
        if pg_catalog.jsonb_typeof(normalized_payload -> payload_key) <> 'string' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        payload_text_value := pg_catalog.btrim(normalized_payload ->> payload_key);
        if pg_catalog.char_length(payload_text_value) not between 1 and 200
          or (payload_key = 'badge' and pg_catalog.char_length(payload_text_value) > 20)
        then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
        normalized_payload := pg_catalog.jsonb_set(
          normalized_payload, array[payload_key], pg_catalog.to_jsonb(payload_text_value)
        );
      end if;
    end loop;

    if normalized_payload ? 'good_ids' then
      payload_good_ids := normalized_payload -> 'good_ids';
      payload_good_id_limit := case normalized_kind when 'best_tab' then 12 when 'review_best' then 20 when 'product_collection' then 100 else 4 end;
      if pg_catalog.jsonb_typeof(payload_good_ids) <> 'array'
        or pg_catalog.jsonb_array_length(payload_good_ids) not between (case when normalized_kind in ('review_best','product_collection') then 0 else 1 end) and payload_good_id_limit
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      for payload_good_id in
        select value from pg_catalog.jsonb_array_elements_text(payload_good_ids) as elements(value)
      loop
        if payload_good_id !~ '^[A-Za-z0-9_-]{1,64}$' then
          raise invalid_parameter_value using message = 'invalid_curation_payload';
        end if;
      end loop;
    end if;

    -- Automatic selection is a rule, never a saved snapshot of product IDs.
    if normalized_kind='best_tab' and normalized_payload ? 'selection_mode' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'selection_mode') <> 'string'
        or normalized_payload ->> 'selection_mode' <> 'latest'
        or normalized_payload ? 'good_ids'
        or not normalized_payload ? 'item_count'
        or pg_catalog.jsonb_typeof(normalized_payload -> 'item_count') <> 'number'
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      if (normalized_payload ->> 'item_count')::numeric not between 3 and 10
        or pg_catalog.trunc((normalized_payload ->> 'item_count')::numeric)
          <> (normalized_payload ->> 'item_count')::numeric
      then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['item_count'],
        pg_catalog.to_jsonb(((normalized_payload ->> 'item_count')::numeric)::integer)
      );
    elsif normalized_kind='best_tab' and normalized_payload ? 'item_count' then
      raise invalid_parameter_value using message = 'invalid_curation_payload';
    end if;

    if normalized_payload ? 'mobile_image_path' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'mobile_image_path') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_payload';
      end if;
      payload_mobile_image_path := normalized_payload ->> 'mobile_image_path';
      if payload_mobile_image_path
        !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
      then
        raise check_violation using message = 'invalid_curation_image_path';
      end if;
    end if;

    if normalized_payload ? 'cta_label' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'cta_label') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_notice';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['cta_label'],
        pg_catalog.to_jsonb(pg_catalog.btrim(normalized_payload ->> 'cta_label'))
      );
    end if;

    if normalized_payload ? 'image_alt' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'image_alt') <> 'string' then
        raise invalid_parameter_value using message = 'invalid_curation_collection_banner';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['image_alt'],
        pg_catalog.to_jsonb(pg_catalog.btrim(normalized_payload ->> 'image_alt'))
      );
    end if;

    -- Each suggested term is stored exactly as the chip label and search query:
    -- trimmed with inner whitespace collapsed (lib/search.ts normalizeSearchQuery).
    if normalized_payload ? 'terms' then
      if pg_catalog.jsonb_typeof(normalized_payload -> 'terms') <> 'array' then
        raise invalid_parameter_value using message = 'invalid_curation_search_terms';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['terms'],
        coalesce((
          select pg_catalog.jsonb_agg(
            case when pg_catalog.jsonb_typeof(term.value) = 'string'
              then pg_catalog.to_jsonb(pg_catalog.btrim(pg_catalog.regexp_replace(term.value #>> '{}', '[[:space:]]+', ' ', 'g')))
              else term.value
            end
            order by term.ordinality
          )
          from pg_catalog.jsonb_array_elements(normalized_payload -> 'terms') with ordinality as term(value, ordinality)
        ), '[]'::jsonb)
      );
    end if;

    -- Page-type targeting is stored in one canonical order so an identical
    -- operator request replays byte-for-byte (operation receipt comparison).
    if normalized_payload ? 'page_types' then
      if not private.is_valid_home_notice_page_types(normalized_payload -> 'page_types') then
        raise invalid_parameter_value using message = 'invalid_curation_notice';
      end if;
      normalized_payload := pg_catalog.jsonb_set(
        normalized_payload, array['page_types'],
        (
          select pg_catalog.jsonb_agg(page_type order by pg_catalog.array_position(
            array['home', 'collection', 'product', 'content', 'other']::text[], page_type
          ))
          from pg_catalog.jsonb_array_elements_text(normalized_payload -> 'page_types') as page_types(page_type)
        )
      );
    end if;
  end if;

  if not private.is_valid_home_ranked_curation(normalized_kind, normalized_payload) then
    raise invalid_parameter_value using message='invalid_curation_payload';
  end if;

  if not private.is_valid_home_notice_payload(normalized_kind, normalized_payload, normalized_link_path) then
    raise invalid_parameter_value using message='invalid_curation_notice';
  end if;

  if normalized_kind='product_mosaic' and (not private.is_valid_home_mosaic(normalized_payload) or normalized_image_path is not null) then
    raise invalid_parameter_value using message='invalid_curation_mosaic';
  end if;

  if normalized_kind='hero' and not private.is_valid_home_hero_style(normalized_payload) then
    raise invalid_parameter_value using message='invalid_hero_style';
  end if;

  if normalized_kind='collection_banner' and (
    not private.is_valid_home_hero_style(normalized_payload)
    or not private.is_valid_home_collection_banner(normalized_title, normalized_payload)
  ) then
    raise invalid_parameter_value using message='invalid_curation_collection_banner';
  end if;

  if normalized_kind='search_terms' and not private.is_valid_home_search_terms(normalized_title, normalized_payload) then
    raise invalid_parameter_value using message='invalid_curation_search_terms';
  end if;

  if normalized_kind='hero' and not private.is_valid_home_hero_alt(normalized_payload) then
    raise invalid_parameter_value using message='invalid_hero_alt';
  end if;

  if normalized_kind='product_collection' and (not private.is_valid_home_product_collection(normalized_payload)
    or normalized_image_path is not null or normalized_title~'[[:cntrl:]]') then
    raise invalid_parameter_value using message='invalid_curation_product_collection';
  end if;

  request_payload := pg_catalog.jsonb_build_object(
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  if require_saved_version then
    request_payload := request_payload || pg_catalog.jsonb_build_object('expected_updated_at',target_expected_updated_at);
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.home_curation.upserted'
      and existing_target = 'home_curations:' || target_curation_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_curation_id;
    end if;

    raise unique_violation using message = 'operation_conflict';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_home_curation:' || target_curation_id::text,
      0
    )
  );

  if normalized_ip_id is not null then
    select ip.archived_at
      into referenced_archived_at
    from public.ips as ip
    where ip.id = normalized_ip_id
    for update of ip;

    if not found then
      raise no_data_found using message = 'curation_ip_not_found';
    end if;
    if referenced_archived_at is not null then
      raise check_violation using message = 'catalog_item_archived';
    end if;
  end if;

  select curation.*
    into previous_curation
  from public.home_curations as curation
  where curation.id = target_curation_id
  for update of curation;
  curation_exists := found;
  if curation_exists and previous_curation.archived_at is not null then
    raise sqlstate 'PT409' using message='curation_archived';
  end if;

  if require_saved_version and ((curation_exists and previous_curation.updated_at is distinct from target_expected_updated_at)
    or (not curation_exists and target_expected_updated_at is not null)) then
    raise sqlstate 'PT409' using message='curation_conflict';
  end if;

  if curation_exists then
    previous_payload := pg_catalog.jsonb_build_object(
      'id', previous_curation.id,
      'kind', previous_curation.kind,
      'ip_id', previous_curation.ip_id,
      'title', previous_curation.title,
      'image_path', previous_curation.image_path,
      'link_path', previous_curation.link_path,
      'display_order', previous_curation.display_order,
      'active_from', previous_curation.active_from,
      'active_to', previous_curation.active_to,
      'enabled', previous_curation.enabled,
      'slot', previous_curation.slot,
      'payload', previous_curation.payload
    );
    previous_mobile_image_path := previous_curation.payload ->> 'mobile_image_path';
  end if;

  -- The artwork-claim trigger only guards the image_path column, so the
  -- mobile artwork carried inside payload consumes its verified upload claim
  -- here, under the same actor/kind/single-use rules (#112 contract).
  if payload_mobile_image_path is not null
    and payload_mobile_image_path is distinct from previous_mobile_image_path
  then
    update public.admin_artwork_upload_claims as claim
    set
      status = 'attached',
      attached_at = pg_catalog.clock_timestamp(),
      resolved_at = pg_catalog.clock_timestamp()
    where claim.actor_id = claim_owner_id
      and claim.path = pg_catalog.substr(
        payload_mobile_image_path,
        pg_catalog.length('public-media/') + 1
      )
      and claim.kind = 'curation'
      and claim.status = 'verified'
      and claim.verified_at is not null
      and claim.final_size is not null
      and claim.attached_at is null
      and claim.expires_at > pg_catalog.clock_timestamp();

    if not found then
      raise check_violation using message = 'unverified_artwork';
    end if;
  end if;

  if curation_exists then
    update public.home_curations
    set
      kind = normalized_kind,
      ip_id = normalized_ip_id,
      title = normalized_title,
      image_path = normalized_image_path,
      link_path = normalized_link_path,
      display_order = target_display_order,
      active_from = target_active_from,
      active_to = target_active_to,
      enabled = target_enabled,
      slot = normalized_slot,
      payload = normalized_payload
    where id = target_curation_id;
  else
    insert into public.home_curations (
      id, kind, ip_id, title, image_path, link_path,
      display_order, active_from, active_to, enabled, slot, payload
    )
    values (
      target_curation_id, normalized_kind, normalized_ip_id, normalized_title,
      normalized_image_path, normalized_link_path, target_display_order,
      target_active_from, target_active_to, target_enabled, normalized_slot,
      normalized_payload
    );
  end if;

  after_payload := pg_catalog.jsonb_build_object(
    'id', target_curation_id,
    'kind', normalized_kind,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'image_path', normalized_image_path,
    'link_path', normalized_link_path,
    'display_order', target_display_order,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'enabled', target_enabled,
    'slot', normalized_slot,
    'payload', normalized_payload
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.home_curation.upserted',
    'home_curations:' || target_curation_id::text,
    pg_catalog.jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_curation_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.seller_cancel_intake_block(p_order_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare target public.orders;
begin
 select * into target from public.orders where id=p_order_id;
 if not found then return 'order_not_found';end if;
 if target.status='canceled' then return 'already_canceled';end if;
 if not private.order_cancel_eligible(p_order_id) then return 'not_cancelable';end if;
 if exists(select 1 from public.order_cancellation_requests where order_id=p_order_id and status in('requested','processing','needs_review')) then return 'already_requested';end if;
 if exists(select 1 from public.order_cancellation_claims where order_id=p_order_id) then return 'reconciliation_in_progress';end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION private.seller_claim_intake_block(p_order_id uuid, p_reason_type text, p_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare target public.orders;
begin
  select * into target from public.orders where id = p_order_id;
  if not found then return 'order_not_found'; end if;
  if target.status = 'canceled' then return 'already_canceled'; end if;
  if not private.order_return_intake_eligible(p_order_id) then return 'not_claimable'; end if;
  if public.order_withdrawal_deadline_passed(target.delivered_at, p_reason_type, p_at) then return 'deadline_expired'; end if;
  if exists (select 1 from public.order_cancellation_requests where order_id = p_order_id and status in ('requested', 'processing', 'needs_review')) then return 'already_requested'; end if;
  if exists (select 1 from public.order_cancellation_claims where order_id = p_order_id) then return 'reconciliation_in_progress'; end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.set_cart_quantity_with_inputs(p_good_id text, p_variant_id uuid, p_qty integer, p_input_revision integer, p_input_values jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); available_stock integer; other_qty bigint; key_value text; snapshot jsonb;
  sale_mode text; cart_variant uuid; target_qty bigint:=p_qty;
begin
  if actor is null then raise insufficient_privilege using message='auth required'; end if;
  perform private.lock_goods_transaction_actor(actor);
  perform private.assert_active_user(actor);
  if nullif(btrim(p_good_id),'') is null or p_variant_id is null or p_qty is null or p_qty<0
    or p_input_revision is null or p_input_revision<0 or jsonb_typeof(p_input_values) is distinct from 'object' then
    raise invalid_parameter_value using message='invalid cart item';
  end if;
  key_value:=case when p_input_revision=0 and p_input_values='{}' then '' else md5(p_input_revision::text||':'||p_input_values::text) end;
  perform pg_advisory_xact_lock(hashtextextended('cart:'||actor::text,0));
  -- 랜덤 판매 굿즈는 기본 옵션 한 줄로 담는다(D5②). 배정은 주문 때 DB가 한다.
  select good.option_sale_mode into sale_mode from public.goods good where good.id=p_good_id;
  cart_variant:=case when sale_mode='random' then private.cart_variant_key(p_good_id,p_variant_id) else p_variant_id end;
  if exists(select 1 from public.cart_items where user_id=actor and variant_id=cart_variant and input_key=key_value
    and (input_revision,input_values) is distinct from (p_input_revision,p_input_values)) then raise check_violation using message='cart_input_identity_conflict'; end if;
  -- Removing an obsolete definition must remain possible. A legacy call with
  -- empty inputs can only remove the legacy empty-input row, never custom rows.
  if p_qty=0 then
    delete from public.cart_items where user_id=actor and good_id=p_good_id and variant_id=p_variant_id and input_key=key_value;
    return;
  end if;
  -- 성인 상품은 유효한 성인 인증이 있어야 담긴다. 일반 품절·비공개와 구분되는 오류로
  -- 알려야 화면이 인증 안내로 보낼 수 있다(ADR-0024).
  if exists(select 1 from public.goods restricted where restricted.id=p_good_id and restricted.sale_restriction='adult'
    and not private.adult_verification_valid(actor)) then raise check_violation using message='adult_verification_required'; end if;
  snapshot:=private.resolve_goods_custom_inputs(p_good_id,p_input_revision,p_input_values);
  select supply.available_qty into available_stock from public.goods_variants variant
    join public.goods good on good.id=variant.good_id join public.ips ip on ip.id=good.ip_id
    cross join lateral private.resolve_goods_variant_supply(variant.id,statement_timestamp()) supply
    where variant.id=cart_variant and variant.good_id=p_good_id and variant.archived_at is null
      and good.published_at is not null and good.archived_at is null and private.good_sale_restriction_visible(good.sale_restriction,actor)
      and good.stock<>'soldout' and (good.allow_card_payment or good.allow_bank_transfer)
      and ip.published_at is not null and ip.archived_at is null;
  if not found then raise check_violation using message='catalog_item_unavailable'; end if;
  if sale_mode='random' then
    -- 가용 = 활성 일반재고 옵션 풀 합계. 같은 굿즈의 다른 줄(키가 바뀌기 전 줄 포함)과 합쳐 판정한다.
    -- 일반 재고·예약 모두 풀 합계(예약은 접수 중일 때만 남은 예약 물량 합).
    available_stock:=private.random_option_pool_qty(p_good_id,statement_timestamp());
    select coalesce(sum(qty::bigint),0) into other_qty from public.cart_items where user_id=actor and good_id=p_good_id
      and not (variant_id in (cart_variant,p_variant_id) and input_key=key_value);
    -- 랜덤 전환 전에 담긴 비기본 옵션 줄(p_variant_id)을 고객이 바꾸면 그 줄의 새 수량을 기본 옵션(키) 줄에 더해 합친다.
    -- 키 줄의 기존 수량은 보존한다. 병합·추가 담기는 키 줄 기준 수량을 키 id로 넘기므로 이 분기를 타지 않는다.
    if cart_variant<>p_variant_id and exists(select 1 from public.cart_items
      where user_id=actor and good_id=p_good_id and variant_id=p_variant_id and input_key=key_value) then
      select p_qty+coalesce(sum(qty::bigint),0) into target_qty from public.cart_items
        where user_id=actor and variant_id=cart_variant and input_key=key_value;
      delete from public.cart_items where user_id=actor and good_id=p_good_id and variant_id=p_variant_id and input_key=key_value;
    end if;
  else
    select coalesce(sum(qty::bigint),0) into other_qty from public.cart_items where user_id=actor and variant_id=p_variant_id and input_key<>key_value;
  end if;
  if other_qty+target_qty>available_stock or target_qty>2147483647 then raise check_violation using message='out of stock'; end if;
  insert into public.cart_items(user_id,good_id,variant_id,qty,input_revision,input_values,input_snapshot)
    values(actor,p_good_id,cart_variant,target_qty::integer,p_input_revision,p_input_values,snapshot)
    on conflict(user_id,variant_id,input_key) do update set qty=excluded.qty;
end $function$

CREATE OR REPLACE FUNCTION private.set_catalog_archived(target_kind text, target_id text, archive_requested boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  selected_archived_at timestamptz;
  transition_at timestamptz;
  audit_action text;
  audit_target text;
begin
  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  if not public.is_staff() then
    raise insufficient_privilege using message = 'forbidden';
  end if;

  if target_kind = 'ip' then
    select ip.archived_at
      into selected_archived_at
    from public.ips as ip
    where ip.id = target_id
    for update of ip;

    if not found then
      raise no_data_found using message = 'catalog_not_found';
    end if;
    if archive_requested = (selected_archived_at is not null) then
      return false;
    end if;

    if archive_requested and exists (
      select 1
      from public.home_curations as curation
      where curation.kind = 'featured_ip'
        and curation.ip_id = target_id
        and curation.enabled
        and (curation.active_to is null or curation.active_to > pg_catalog.now())
    ) then
      raise check_violation using message = 'ip_has_active_home_curation';
    end if;

    transition_at := case when archive_requested then pg_catalog.clock_timestamp() else null end;
    update public.ips
    set archived_at = transition_at, published_at = null
    where id = target_id;
    audit_action := case when archive_requested then 'catalog.ip.archived' else 'catalog.ip.unarchived' end;
    audit_target := 'ips:' || target_id;

  elsif target_kind = 'good' then
    select good.archived_at
      into selected_archived_at
    from public.goods as good
    where good.id = target_id
    for update of good;

    if not found then
      raise no_data_found using message = 'catalog_not_found';
    end if;
    if archive_requested = (selected_archived_at is not null) then
      return false;
    end if;

    if archive_requested and exists (
      select 1
      from public.goods as good
      where good.id = target_id
        and good.stock_qty > 0
    ) then
      raise check_violation using message = 'good_has_stock';
    end if;

    if archive_requested and exists (
      select 1
      from public.reward_policies as policy
      where policy.target_good_id = target_id
        and policy.active
        and (policy.active_to is null or policy.active_to > pg_catalog.now())
    ) then
      raise check_violation using message = 'good_has_active_policy';
    end if;

    transition_at := case when archive_requested then pg_catalog.clock_timestamp() else null end;
    update public.goods set archived_at = transition_at where id = target_id;
    audit_action := case when archive_requested then 'catalog.good.archived' else 'catalog.good.unarchived' end;
    audit_target := 'goods:' || target_id;

  elsif target_kind = 'card' then
    select card.archived_at
      into selected_archived_at
    from public.cards as card
    where card.id = target_id
    for update of card;

    if not found then
      raise no_data_found using message = 'catalog_not_found';
    end if;
    if archive_requested = (selected_archived_at is not null) then
      return false;
    end if;

    if archive_requested and exists (
      select 1
      from public.cards as card
      join public.card_pools as pool on pool.id = card.pool_id
      where card.id = target_id
        and (pool.active_to is null or pool.active_to > pg_catalog.now())
    ) then
      raise check_violation using message = 'card_has_open_pool';
    end if;

    if archive_requested and exists (
      select 1
      from public.cards as card
      join public.draw_tickets as ticket on ticket.pool_id = card.pool_id
      where card.id = target_id
        and ticket.consumed_at is null
        and ticket.revoked_at is null
    ) then
      raise check_violation using message = 'card_has_open_tickets';
    end if;

    transition_at := case when archive_requested then pg_catalog.clock_timestamp() else null end;
    update public.cards set archived_at = transition_at where id = target_id;
    audit_action := case when archive_requested then 'catalog.card.archived' else 'catalog.card.unarchived' end;
    audit_target := 'cards:' || target_id;

  elsif target_kind = 'event' then
    select event_record.archived_at
      into selected_archived_at
    from public.events as event_record
    where event_record.id = target_id
    for update of event_record;

    if not found then
      raise no_data_found using message = 'catalog_not_found';
    end if;
    if archive_requested = (selected_archived_at is not null) then
      return false;
    end if;

    if archive_requested and exists (
      select 1
      from public.events as event_record
      join public.ticket_types as ticket_type on ticket_type.event_id = event_record.id
      where event_record.id = target_id
        and event_record.status in ('예정', '예매중', '진행중')
    ) then
      raise check_violation using message = 'event_has_open_ticketing';
    end if;

    if archive_requested and exists (
      select 1
      from public.games as game
      where game.event_id = target_id
        and (game.active_to is null or game.active_to > pg_catalog.now())
    ) then
      raise check_violation using message = 'event_has_open_game';
    end if;

    transition_at := case when archive_requested then pg_catalog.clock_timestamp() else null end;
    update public.events set archived_at = transition_at where id = target_id;
    audit_action := case when archive_requested then 'catalog.event.archived' else 'catalog.event.unarchived' end;
    audit_target := 'events:' || target_id;
  else
    raise invalid_parameter_value using message = 'invalid_catalog_kind';
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    audit_action,
    audit_target,
    pg_catalog.jsonb_build_object('archived_at', transition_at)
      || case when target_kind = 'ip'
        then pg_catalog.jsonb_build_object('published_at', null)
        else '{}'::jsonb end
  );

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_good_published(target_id text, publish_requested boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare selected public.goods; transition_at timestamptz;
begin
  if auth.uid() is null or not public.is_staff() then raise insufficient_privilege using message='staff_required'; end if;
  if publish_requested is null then raise invalid_parameter_value using message='invalid_publish_state'; end if;
  select * into selected from public.goods where id=target_id for update;
  if not found then raise no_data_found using message='catalog_not_found'; end if;
  if selected.archived_at is not null then raise check_violation using message='catalog_item_archived'; end if;
  if publish_requested=(selected.published_at is not null) then return false; end if;
  if publish_requested and (
    nullif(btrim(selected.name),'') is null
    or nullif(btrim(selected.image_path),'') is null
    or exists(select 1 from unnest(array[selected.notice_maker,selected.notice_origin,selected.notice_material,
      selected.notice_size,selected.notice_made_on,selected.notice_as_manager,selected.notice_as_contact]) field
      where nullif(btrim(field),'') is null)
    or not exists(select 1 from public.goods_variants where good_id=target_id and archived_at is null)
  ) then raise check_violation using message='goods_publish_incomplete'; end if;
  -- ADR-0044: 상품 유형은 없다. 공개하려면 대표 카테고리가 있어야 한다.
  if publish_requested and selected.category_id is null then
    raise check_violation using message='goods_category_required';
  end if;
  transition_at:=case when publish_requested then clock_timestamp() else null end;
  update public.goods set published_at=transition_at where id=target_id;
  insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),
    case when publish_requested then 'admin.good.published' else 'admin.good.unpublished' end,'goods:'||target_id,
    jsonb_build_object('published_at',transition_at,'previous_published_at',selected.published_at));
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.set_goods_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  new.code:=nullif(upper(btrim(new.code)),'');
  if new.code is null then
    if tg_op='INSERT' then select code into new.code from public.goods where id=new.id; end if;
    new.code:=coalesce(new.code,private.allocate_goods_code(new.ip_id));
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_goods_variant_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parent_code text; ordinal bigint:=1; candidate text;
begin
  new.code:=nullif(upper(btrim(new.code)),'');
  if new.code is not null then return new; end if;
  select code into parent_code from public.goods where id=new.good_id for update;
  loop
    candidate:=parent_code||'-'||lpad(ordinal::text,greatest(2,length(ordinal::text)),'0');
    if not exists(select 1 from public.goods_variants where code=candidate) then new.code:=candidate; return new; end if;
    ordinal:=ordinal+1;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_ip_published(target_id text, publish_requested boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  selected_archived_at timestamptz;
  selected_published_at timestamptz;
  selected_title text;
  transition_at timestamptz;
begin
  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  if not public.is_staff() then
    raise insufficient_privilege using message = 'forbidden';
  end if;

  if publish_requested is null then
    raise invalid_parameter_value using message = 'invalid_publish_state';
  end if;

  select ip.archived_at, ip.published_at, ip.title
    into selected_archived_at, selected_published_at, selected_title
  from public.ips as ip
  where ip.id = target_id
  for update of ip;

  if not found then
    raise no_data_found using message = 'catalog_not_found';
  end if;

  if selected_archived_at is not null then
    raise check_violation using message = 'catalog_item_archived';
  end if;

  if publish_requested = (selected_published_at is not null) then
    return false;
  end if;

  -- 공개 전환의 최소 요건. 앱 폼이 같은 규칙(ID·이름·버티컬)을 먼저 검증하지만, 초안은
  -- 직접 DML·과거 데이터로도 만들어질 수 있으므로 공개 경계에서 다시 확인한다.
  -- 버티컬은 FK(not null)가, ID 는 PK 가 이미 보장한다.
  if publish_requested and pg_catalog.btrim(coalesce(selected_title, '')) = '' then
    raise check_violation using message = 'ip_publish_incomplete';
  end if;

  transition_at := case when publish_requested then pg_catalog.clock_timestamp() else null end;

  update public.ips
  set published_at = transition_at,
      updated_at = pg_catalog.now()
  where id = target_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    case when publish_requested then 'admin.ip.published' else 'admin.ip.unpublished' end,
    'ips:' || target_id,
    pg_catalog.jsonb_build_object('published_at', transition_at)
  );

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.settle_cart_order_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hold private.cart_order_holds%rowtype;
  v_line jsonb;
  v_cart public.cart_items%rowtype;
  v_ordered integer;
  v_outcome text;
  v_result jsonb := '[]'::jsonb;
  v_cleared integer := 0;
begin
  if new.status = 'canceled' then
    update private.cart_order_holds
    set state = 'released', settled_at = pg_catalog.clock_timestamp(), release_reason = 'order_closed'
    where order_id = new.id and state = 'awaiting_payment';
    return null;
  end if;

  select hold.* into v_hold
  from private.cart_order_holds as hold
  where hold.order_id = new.id and hold.state = 'awaiting_payment'
  for update;
  if not found then
    return null;
  end if;

  -- 결제는 이미 확정됐다. 장바구니 정리가 어떤 이유로 실패해도 결제 확정을 되돌리지 않는다.
  -- 장바구니 advisory('cart:')는 잡지 않고 해당 줄의 행 잠금만 쓴다. 장바구니 변경 RPC는 'cart:'를
  -- 쥔 채 INSERT 계정 fence에서 account-action을 기다리는데, finalizer는 이미 account-action을 쥐고
  -- 있으므로 여기서 'cart:'를 기다리면 교착한다. 새 장바구니 주문은 이전 주문 행을 먼저 잠그므로
  -- 이 정리와 스냅샷 비교가 엇갈리지 않는다.
  begin
    -- 바로구매 보류(ADR-0030)는 장바구니 줄을 건너뛴다 — 장바구니를 읽지도 바꾸지도 않은 주문이다.
    for v_line in select value from pg_catalog.jsonb_array_elements(case when v_hold.source in ('direct_checkout', 'direct_transaction') then '[]'::jsonb else v_hold.lines end) loop
      v_ordered := (v_line ->> 'qty')::integer;
      select cart.* into v_cart
      from public.cart_items as cart
      where cart.user_id = v_hold.user_id
        and cart.variant_id = (v_line ->> 'variantId')::uuid
        and cart.input_key = v_line ->> 'inputKey'
      for update;
      if not found then
        v_outcome := 'absent';
      elsif v_cart.qty > v_ordered then
        begin
          update public.cart_items
          set qty = qty - v_ordered
          where user_id = v_hold.user_id and variant_id = v_cart.variant_id and input_key = v_cart.input_key;
          v_outcome := 'decreased';
        exception when others then
          -- 장바구니 행 트리거·잠금 등으로 수량을 바꾸지 못했다. 결제는 확정됐으므로 줄은 그대로 둔다.
          v_outcome := 'kept';
        end;
      else
        delete from public.cart_items
        where user_id = v_hold.user_id and variant_id = v_cart.variant_id and input_key = v_cart.input_key;
        v_outcome := 'removed';
      end if;
      v_result := v_result || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'variantId', v_line -> 'variantId', 'inputKey', v_line -> 'inputKey', 'orderedQty', v_ordered,
        'cartQtyBefore', case when v_outcome = 'absent' then null else v_cart.qty end, 'outcome', v_outcome));
    end loop;

    delete from public.cart_coupon_selections as selection
    where selection.user_id = v_hold.user_id
      and selection.user_coupon_id in (
        select redemption.user_coupon_id from public.coupon_redemptions as redemption
        where redemption.order_id = new.id and redemption.status = 'applied');
    get diagnostics v_cleared = row_count;

    update private.cart_order_holds
    set state = 'consumed', settled_at = pg_catalog.clock_timestamp(),
        consumption = pg_catalog.jsonb_build_object('lines', v_result, 'couponSelectionCleared', v_cleared > 0)
    where order_id = new.id;
  exception when others then
    update private.cart_order_holds
    set state = 'consumed', settled_at = pg_catalog.clock_timestamp(),
        consumption = pg_catalog.jsonb_build_object('failed', sqlstate)
    where order_id = new.id and state = 'awaiting_payment';
  end;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.shipping_charge_group_assignment_blocker(p_good public.goods, p_group_id uuid, p_clear boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare origin public.fulfillment_origins;group_values jsonb;group_origin uuid;delivery jsonb;begin
 if private.goods_aggregation_owner(p_good.id)<>p_good.id then return 'goods_aggregation_policy_owned_by_source';end if;
 select * into origin from public.fulfillment_origins where id=p_good.origin_id;
 if (not p_clear and (not found or not origin.is_active)) or (p_clear and p_good.origin_id is not null and not found)
  or (p_clear and p_good.origin_id is null and exists(select 1 from private.shipping_charge_group_assignments where owner_good_id=p_good.id and group_id is not null)) then return 'shipping_charge_group_origin_unavailable';end if;
 if not coalesce((select enabled from private.goods_transaction_runtime where singleton),false) then return 'checkout_contract_upgrade_required';end if;
 if p_group_id is not null then
  select v.policy_values,g.origin_id into group_values,group_origin from private.shipping_charge_groups g
   join private.shipping_charge_group_versions v on v.id=g.version_id where g.id=p_group_id;
  if not found or not(group_values->>'enabled')::boolean or (group_values->>'archived')::boolean then return 'shipping_charge_group_unavailable';end if;
  if group_origin<>p_good.origin_id then return 'shipping_charge_group_origin_mismatch';end if;
 end if;
 delivery:=private.shipping_settings_delivery_input(p_good.id);
 if not p_clear and delivery->>'status'='active' and delivery->>'paymentMode'<>'prepaid' and not exists(
  select 1 from private.shipping_collect_contracts c join private.shipping_collect_contract_versions v on v.id=c.version_id
  where c.origin_id=p_good.origin_id and v.status='active') then return 'collect_contract_not_ready';end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION private.shipping_charge_group_effective_lines(p_owner_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare grouped jsonb:='[]';input record;delivery private.goods_delivery_versions;assignment private.shipping_charge_group_assignments;
 group_row private.shipping_charge_groups;group_version private.shipping_charge_group_versions;origin public.fulfillment_origins;fee numeric;line jsonb;
begin
 for input in select good_id,origin_id,sum(qty::numeric) qty,sum(qty::numeric*unit_price) subtotal,max(fee_type) fee_type,max(individual_fee) individual_fee
  from jsonb_to_recordset(p_owner_lines) l(good_id text,origin_id uuid,qty integer,unit_price bigint,fee_type text,individual_fee bigint)
  group by good_id,origin_id order by good_id loop
  if input.qty not between 1 and 9007199254740991 or input.subtotal not between 0 and 9007199254740991 then
   raise numeric_value_out_of_range using message='transaction_amount_overflow';end if;
  select * into origin from public.fulfillment_origins where id=input.origin_id and is_active;
  if not found then raise check_violation using message='fulfillment_origin_inactive';end if;
  select d.* into delivery from private.goods_transaction_configs c join private.goods_delivery_versions d on d.id=c.delivery_version_id
   where c.good_id=input.good_id and d.status='active';
  fee:=case when delivery.quantity_terms is not null then private.goods_quantity_delivery_fee(input.qty,delivery.quantity_terms)
   when input.fee_type='individual' then input.individual_fee else 0 end;
  select * into assignment from private.shipping_charge_group_assignments where owner_good_id=input.good_id;
  group_row:=null;group_version:=null;
  if assignment.group_id is not null then
   select * into group_row from private.shipping_charge_groups where id=assignment.group_id;
   select * into group_version from private.shipping_charge_group_versions where id=group_row.version_id;
   if group_row.id is null or group_row.origin_id is distinct from input.origin_id
    or not coalesce((group_version.policy_values->>'enabled')::boolean,false) or coalesce((group_version.policy_values->>'archived')::boolean,true) then
    raise check_violation using message='shipping_charge_group_unavailable';end if;
  end if;
  line:=jsonb_build_object('goodId',input.good_id,'originId',input.origin_id,'qty',input.qty,'subtotal',input.subtotal,
   'feeType',case when delivery.quantity_terms is not null then 'individual' else input.fee_type end,'individualFee',fee,'configuredPaymentMode',coalesce(delivery.payment_mode,'prepaid'),
   'deliveryPolicyId',delivery.id,'deliveryPolicyRevision',delivery.revision,'quantityTerms',delivery.quantity_terms,
   'chargeGroupId',assignment.group_id,'assignmentVersionId',assignment.version_id,'assignmentRevision',coalesce(assignment.revision,0),
   'groupVersionId',group_row.version_id,'groupRevision',group_row.revision,'regionMode',coalesce(group_version.policy_values#>>'{regional,mode}','inherit'));
  grouped:=grouped||jsonb_build_array(line);
 end loop;
 return grouped;
end $function$

CREATE OR REPLACE FUNCTION private.shipping_charge_group_region_adapter(p_origin_id uuid, p_name text, p_policy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if not private.transaction_json_keys(p_policy,array['carrierCode','startsAt','endsAt','openEnded','sourceEvidence','unlistedDisposition','noRulesConfirmed','rules']) then
  raise invalid_parameter_value using message='invalid_shipping_charge_group_region';end if;
 return private.normalize_shipping_region_policy(p_policy||jsonb_build_object('originId',p_origin_id,'name',p_name,
  'feeUnit','per_shipment','chargePolicyGoods',true,'waivePolicyThreshold',false,'chargeFreeGoods',true,'chargeIndividualGoods',true));
