CREATE OR REPLACE FUNCTION private.shipping_settings_charge_blocker(p_good public.goods, p_settings jsonb, p_current_delivery jsonb, p_origin jsonb, p_group jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare reason text;directive text;begin
 reason:=private.shipping_settings_delivery_blocker(p_good.id,p_settings,p_current_delivery,p_origin);
 if reason is not null then return reason;end if;
 if p_settings#>>'{fulfillment,mode}'='replace' and not coalesce((select enabled from private.goods_transaction_runtime where singleton),false) then
  return 'checkout_contract_upgrade_required';end if;
 directive:=coalesce(p_settings#>>'{chargeGroup,mode}','preserve');
 if directive='assign' and (p_group is null or p_group='null'::jsonb) then return 'shipping_charge_group_unavailable';end if;
 if p_group is not null and p_group<>'null'::jsonb then
  if p_group->>'originId' is distinct from p_settings->>'originId' then return 'shipping_charge_group_origin_mismatch';end if;
  if not coalesce((p_group->>'enabled')::boolean,false) or coalesce((p_group->>'archived')::boolean,true) then
   return 'shipping_charge_group_unavailable';end if;
 end if;
 if ((p_group is not null and p_group<>'null'::jsonb) or directive='clear')
  and not coalesce((select enabled from private.goods_transaction_runtime where singleton),false) then
  return 'checkout_contract_upgrade_required';end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION private.shipping_settings_delivery_blocker(p_good_id text, p_settings jsonb, p_current jsonb, p_origin jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare final_delivery jsonb;begin
 if private.goods_aggregation_owner(p_good_id)<>p_good_id then return 'goods_aggregation_policy_owned_by_source';end if;
 final_delivery:=case when p_settings#>>'{delivery,mode}'='replace' then p_settings#>'{delivery,policy}' else p_current end;
 if p_settings#>>'{delivery,mode}'='replace' and final_delivery is distinct from p_current and final_delivery->>'status'='active'
  and not coalesce((select enabled from private.goods_transaction_runtime where singleton),false) then return 'checkout_contract_upgrade_required';end if;
 if final_delivery->>'status'='active' and final_delivery->>'paymentMode'<>'prepaid' and p_origin->>'collectReady'<>'true' then
  return 'collect_contract_not_ready';end if;
 return null;
end $function$

