CREATE OR REPLACE FUNCTION private.store_analytics_day_coverage(p_day date, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare began timestamptz; ended timestamptz; expected integer; observed integer; first_at timestamptz; state_value text; archived private.store_analytics_daily_coverage; collection_enabled boolean;
begin
 if p_day>(p_at at time zone 'Asia/Seoul')::date then return jsonb_build_object('state','future','expectedMinutes',0,'observedMinutes',0,'archived',false);end if;
 if p_day<((p_at at time zone 'Asia/Seoul')::date-interval '13 months')::date then return jsonb_build_object('state','expired','expectedMinutes',0,'observedMinutes',0,'archived',false);end if;
 select * into archived from private.store_analytics_daily_coverage where day=p_day;
 if found then return jsonb_build_object('state',archived.state,'expectedMinutes',archived.expected_minutes,'observedMinutes',archived.observed_minutes,'archived',true,'observedUntil',archived.observed_until);end if;
 select activated_at,enabled into first_at,collection_enabled from private.store_analytics_settings where id;
 if first_at is null or p_day<(first_at at time zone 'Asia/Seoul')::date then
  return jsonb_build_object('state','unmeasured','expectedMinutes',0,'observedMinutes',0,'archived',false);end if;
 began:=p_day::timestamp at time zone 'Asia/Seoul';ended:=least((p_day+1)::timestamp at time zone 'Asia/Seoul',date_trunc('minute',p_at));
 select floor(coalesce(sum(greatest(0,extract(epoch from (least(coalesce(w.ended_at,p_at),ended)-greatest(w.started_at,began)))))/60,0))::integer
 into expected from private.store_analytics_windows w where w.started_at<ended and coalesce(w.ended_at,p_at)>began;
 select count(*)::integer into observed from private.store_analytics_health h where h.minute>=began and h.minute<ended;
 if p_day=(p_at at time zone 'Asia/Seoul')::date and collection_enabled then state_value:='collecting';
 elsif expected=0 then state_value:='paused';
 elsif expected>=1440 and observed>=expected then state_value:='observed';
 else state_value:='partial';end if;
 return jsonb_build_object('state',state_value,'expectedMinutes',expected,'observedMinutes',observed,'archived',false,'observedUntil',p_at);
end $function$

CREATE OR REPLACE FUNCTION private.store_analytics_page(p_kind text, p_target text, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$declare result jsonb;
begin
 if p_kind='home' and p_target='home' or p_kind='shop' and p_target in ('all','new','best')
  or p_kind='stories' and p_target='all' or p_kind='events' and p_target='all' then return '{}';end if;
 if p_kind='shop' and p_target~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  and exists(select 1 from public.get_catalog_categories() where id=p_target::uuid) then return jsonb_build_object('categoryId',p_target);end if;
 if p_kind='good' then
  select jsonb_build_object('ipId',g.ip_id,'categoryId',g.category_id) into result
  from public.goods g join public.ips ip on ip.id=g.ip_id where g.id=p_target and g.published_at is not null and g.archived_at is null
   and g.sale_restriction='none' and ip.published_at is not null and ip.archived_at is null;
 elsif p_kind='ip' then
  select jsonb_build_object('ipId',id) into result from public.ips where public_slug=p_target and published_at is not null and archived_at is null;
 elsif p_kind='story' and p_target~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
  select '{}'::jsonb into result from public.shopping_stories where id=p_target::uuid and deleted_at is null
   and(starts_at is null or starts_at<=p_at) and(ends_at is null or ends_at>p_at);
 elsif p_kind='event' then
  select jsonb_build_object('ipId',e.ip_id) into result from public.events e join public.ips ip on ip.id=e.ip_id
   where e.id=p_target and e.archived_at is null and ip.published_at is not null and ip.archived_at is null;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.store_branding_valid(settings jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare field text; value text; platform text; social jsonb; host_pattern text;
begin
  if jsonb_typeof(settings) is distinct from 'object' then return false; end if;
  if not settings ?& array['displayName','logoMode','logoPath','mobileLogoPath','introduction','showIntroduction','socials']
    or (select count(*) from jsonb_object_keys(settings))<>(case when settings ? 'profileImagePath' then 8 else 7 end) then return false; end if;
  foreach field in array array['displayName','introduction'] loop
    if jsonb_typeof(settings->field) is distinct from 'string' then return false; end if;
    value:=settings->>field;
    if value<>btrim(value,E' \t\n\r\f\v'||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
      or value ~ '[[:cntrl:]]' or length(value)>(case field when 'displayName' then 30 else 50 end)
      or (field='displayName' and value='') then return false; end if;
  end loop;
  if settings->>'logoMode' not in ('text','image') or jsonb_typeof(settings->'logoMode') is distinct from 'string'
    or jsonb_typeof(settings->'showIntroduction') is distinct from 'boolean' then return false; end if;
  if (settings->>'showIntroduction')::boolean and settings->>'introduction'='' then return false; end if;
  foreach field in array array['logoPath','mobileLogoPath','profileImagePath'] loop
    if settings->field<>'null'::jsonb and (jsonb_typeof(settings->field) is distinct from 'string'
      or settings->>field !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|png|webp)$') then return false; end if;
  end loop;
  if settings->>'logoMode'='image' and settings->'logoPath'='null'::jsonb then return false; end if;
  if jsonb_typeof(settings->'socials') is distinct from 'object' then return false; end if;
  if not (settings->'socials') ?& array['blog','facebook','instagram'] or (select count(*) from jsonb_object_keys(settings->'socials'))<>3 then return false; end if;
  foreach platform in array array['blog','facebook','instagram'] loop
    social:=settings->'socials'->platform;
    if jsonb_typeof(social) is distinct from 'object' then return false; end if;
    if not social ?& array['enabled','url'] or (select count(*) from jsonb_object_keys(social))<>2
      or jsonb_typeof(social->'enabled') is distinct from 'boolean' or jsonb_typeof(social->'url') is distinct from 'string' then return false; end if;
    value:=social->>'url';
    if value='' then
      if (social->>'enabled')::boolean then return false; end if;
    else
      host_pattern:=case platform when 'blog' then '(blog\.naver\.com|m\.blog\.naver\.com)' when 'facebook' then '((www\.|m\.)?facebook\.com)' else '((www\.)?instagram\.com)' end;
      if length(value)>2048 or value ~ '[[:space:][:cntrl:]]' or position(chr(92) in value)>0
        or value !~ ('^https://'||host_pattern||'([/?#].*)?$') then return false; end if;
    end if;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.store_credit_checkout_quote_for_items(p_requested_amount bigint, p_destination jsonb, p_items jsonb, p_cart_coupon boolean, p_user_coupon_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); policy private.store_credit_policy; balance jsonb; sales jsonb;
  subtotal bigint; shipping bigint; coupon_quote jsonb; coupon bigint := 0; maximum bigint := 0; reason text;
begin
  if actor is null then raise insufficient_privilege using message = 'auth_required'; end if;
  if p_requested_amount is null or p_requested_amount not between 0 and 999999999999 then
    raise invalid_parameter_value using message = 'store_credit_amount_invalid'; end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 19239 or p_cart_coupon is null then
    raise invalid_parameter_value using message = 'invalid_store_credit_items'; end if;
  select * into policy from private.store_credit_policy where singleton;
  perform private.expire_store_credit_lots(actor, clock_timestamp()); balance := private.store_credit_balance(actor);
  if not policy.enabled then reason := 'store_credit_disabled';
  elsif (balance ->> 'debt')::bigint > 0 then reason := 'store_credit_debt';
  else
    sales := public.quote_goods_sales_for_address(p_items, p_destination);
    subtotal := (sales ->> 'subtotal')::bigint; shipping := (sales -> 'shipping' ->> 'totalFee')::bigint;
    coupon_quote := case when p_cart_coupon then sales -> 'coupon' else private.quote_user_coupon(p_user_coupon_id, sales -> 'lines', subtotal, shipping) end;
    if not (sales -> 'shipping' ->> 'checkoutAllowed')::boolean then reason := 'shipping_region_unresolved';
    elsif coupon_quote ->> 'reason' is not null then reason := coupon_quote ->> 'reason';
    else coupon := coalesce((coupon_quote ->> 'discount')::bigint, 0); end if;
    if reason is null then
      maximum := least(policy.max_use, (balance ->> 'available')::bigint, greatest(0, subtotal - coupon), greatest(0, subtotal + shipping - coupon - 1000));
      if p_requested_amount > 0 and (p_requested_amount < policy.min_use or p_requested_amount > maximum) then reason := 'store_credit_amount_invalid'; end if;
    end if;
  end if;
  return balance || jsonb_build_object('enabled', policy.enabled, 'minUse', policy.min_use, 'maxUse', maximum,
    'requestedAmount', p_requested_amount, 'valid', p_requested_amount = 0 or reason is null, 'reason', reason);
end;
$function$

CREATE OR REPLACE FUNCTION private.store_credit_checkout_quote(p_requested_amount bigint, p_destination jsonb, p_with_address boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); policy private.store_credit_policy; balance jsonb; items jsonb; sales jsonb;
  subtotal bigint; shipping bigint; coupon bigint:=0; maximum bigint:=0; reason text;
begin
  if actor is null then raise insufficient_privilege using message='auth_required'; end if;
  if p_requested_amount is null or p_requested_amount not between 0 and 999999999999 then
    raise invalid_parameter_value using message='store_credit_amount_invalid'; end if;
  select * into policy from private.store_credit_policy where singleton;
  perform private.expire_store_credit_lots(actor,clock_timestamp()); balance:=private.store_credit_balance(actor);
  if not policy.enabled then reason:='store_credit_disabled';
  elsif (balance->>'debt')::bigint>0 then reason:='store_credit_debt';
  else
    select coalesce(jsonb_agg(jsonb_build_object('goodId',good_id,'variantId',variant_id,'qty',qty)),'[]') into items
      from public.cart_items where user_id=actor;
    sales:=case when p_with_address then public.quote_goods_sales_for_address(items,p_destination) else public.quote_goods_sales(items) end;
    subtotal:=(sales->>'subtotal')::bigint; shipping:=(sales->'shipping'->>'totalFee')::bigint;
    if p_with_address and not (sales->'shipping'->>'checkoutAllowed')::boolean then reason:='shipping_region_unresolved';
    elsif sales->'coupon'->>'reason' is not null then reason:=sales->'coupon'->>'reason';
    else coupon:=coalesce((sales->'coupon'->>'discount')::bigint,0); end if;
    if reason is null then
      maximum:=least(policy.max_use,(balance->>'available')::bigint,greatest(0,subtotal-coupon),greatest(0,subtotal+shipping-coupon-1000));
      if p_requested_amount>0 and (p_requested_amount<policy.min_use or p_requested_amount>maximum) then reason:='store_credit_amount_invalid'; end if;
    end if;
  end if;
  return balance||jsonb_build_object('enabled',policy.enabled,'minUse',policy.min_use,'maxUse',maximum,
    'requestedAmount',p_requested_amount,'valid',p_requested_amount=0 or reason is null,'reason',reason);
end $function$

CREATE OR REPLACE FUNCTION private.store_credit_history(p_user_id uuid, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare balance jsonb; rows jsonb; row_count bigint; page_number integer:=greatest(1,coalesce(p_page,1));
begin
  if page_number>1000000 then raise invalid_parameter_value using message='store_credit_page_invalid'; end if;
  perform private.expire_store_credit_lots(p_user_id,clock_timestamp());
  balance:=private.store_credit_balance(p_user_id);
  select count(*) into row_count from public.store_credit_ledger where user_id=p_user_id;
  select coalesce(jsonb_agg(jsonb_build_object('id',id::text,'kind',kind,'amount',amount,'availableDelta',available_delta,'reservedDelta',reserved_delta,'debtDelta',debt_delta,
    'orderId',order_id,'lotId',lot_id,'actorId',actor_id,'reason',reason,'expiresAt',expires_at,'createdAt',created_at) order by created_at desc,id desc),'[]') into rows
  from (select * from public.store_credit_ledger where user_id=p_user_id order by created_at desc,id desc limit 30 offset (page_number-1)*30) page;
  return balance||jsonb_build_object('userId',p_user_id,'enabled',(select enabled from private.store_credit_policy where singleton),'total',row_count,'page',page_number,'pageSize',30,'items',rows);
end $function$

CREATE OR REPLACE FUNCTION private.store_credit_order_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allocation private.store_credit_allocations; lot private.store_credit_lots; basis bigint; earned bigint; policy jsonb; balance jsonb;
begin
  if new.status is not distinct from old.status then return null; end if;
  if new.status='paid' and new.store_credit_total>0 then
    perform private.lock_store_credit_account(new.user_id);
    for allocation in select * from private.store_credit_allocations where order_id=new.id and state='reserved' order by lot_id for update loop
      select * into lot from private.store_credit_lots where id=allocation.lot_id for update;
      if not found or lot.user_id<>new.user_id or allocation.user_id<>new.user_id or lot.reserved_amount<allocation.amount
        then raise check_violation using message='store_credit_allocation_mismatch'; end if;
      update private.store_credit_lots set reserved_amount=reserved_amount-allocation.amount,spent_amount=spent_amount+allocation.amount where id=allocation.lot_id;
      update private.store_credit_allocations set state='consumed',consumed_at=clock_timestamp() where order_id=new.id and lot_id=allocation.lot_id;
      insert into public.store_credit_ledger(user_id,kind,amount,reserved_delta,order_id,lot_id)
        values(new.user_id,'consume',0,-allocation.amount,new.id,allocation.lot_id);
    end loop;
    if coalesce((select sum(amount) from private.store_credit_allocations where order_id=new.id and state='consumed'),0)<>new.store_credit_total
      then raise check_violation using message='store_credit_allocation_mismatch'; end if;
  elsif new.status='canceled' then
    -- Only authoritative terminal order cancellation reaches this trigger.
    -- Declined/unknown attempts alone do not release a still-payable reservation.
    perform private.expire_store_credit_lots(new.user_id,clock_timestamp());
    perform private.reverse_order_earned_store_credits(new.id,new.user_id);
    perform private.release_order_store_credits(new.id,new.user_id);
  elsif new.status='done' and new.store_credit_policy_snapshot is not null then
    policy:=new.store_credit_policy_snapshot;
    perform private.expire_store_credit_lots(new.user_id,clock_timestamp());
    if exists(select 1 from private.store_credit_lots where source_order_id=new.id and source_kind='order_done') then return null; end if;
    basis:=greatest(0,new.total-new.shipping_fee-private.order_partial_canceled_goods_amount(new.id));
    if basis=0 then return null; end if;
    earned:=case when policy->>'earnKind'='rate_bps' then floor(basis::numeric*(policy->>'earnValue')::numeric/10000)::bigint else (policy->>'earnValue')::bigint end;
    earned:=least(earned,(policy->>'earnMaxPerOrder')::bigint);
    balance:=private.store_credit_balance(new.user_id);
    earned:=least(earned,greatest(0,(policy->>'maxBalance')::bigint-(balance->>'available')::bigint-(balance->>'reserved')::bigint)+(balance->>'debt')::bigint);
    if earned>0 then
      perform private.issue_store_credit_lot(new.user_id,earned,clock_timestamp()+make_interval(days=>(policy->>'validityDays')::integer),'order_done',new.id,null,null,'');
    end if;
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.store_credit_policy_for_member(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb:=private.store_credit_policy_json(); policy private.customer_reward_policy; grade text; rate bigint;
begin
 select * into policy from private.customer_reward_policy where singleton;
 if not policy.grade_enabled or result->'enabled' is distinct from 'true'::jsonb then return result;end if;
 select loyalty_grade::text into grade from public.profiles where id=p_user_id;
 if grade is null then return result;end if;
 rate:=(policy.grade_rates->>grade)::bigint;
 if rate is null then raise object_not_in_prerequisite_state using message='customer_reward_rate_missing';end if;
 return result||jsonb_build_object('earnKind','rate_bps','earnValue',rate,'gradeReward',jsonb_build_object('grade',grade,'policyRevision',policy.revision));
end $function$

CREATE OR REPLACE FUNCTION private.store_navigation_valid(settings jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare entry jsonb; ids text[]:='{}'; label text;
begin
  if jsonb_typeof(settings) is distinct from 'array' then return false; end if;
  if jsonb_array_length(settings)<>9 then return false; end if;
  for entry in select value from jsonb_array_elements(settings) loop
    if jsonb_typeof(entry) is distinct from 'object' then return false; end if;
    if not entry ?& array['id','label','visible'] or (select count(*) from jsonb_object_keys(entry))<>3
      or jsonb_typeof(entry->'id') is distinct from 'string'
      or entry->>'id' not in ('new','best','shop','popups','events','iphub','packs','community','stories')
      or jsonb_typeof(entry->'label') is distinct from 'string'
      or jsonb_typeof(entry->'visible') is distinct from 'boolean'
      or entry->>'id'=any(ids) then return false; end if;
    label:=entry->>'label';
    if length(label) not between 1 and 20 or label ~ '[[:cntrl:]]'
      or label<>btrim(label,E' \t\n\r\f\v'||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
      or (entry->>'id'='shop' and not (entry->>'visible')::boolean) then return false; end if;
    ids:=array_append(ids,entry->>'id');
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.subscription_lock_actor(p_actor uuid, p_new_write boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare profile public.profiles;begin
 if p_actor is null or p_new_write is null then raise insufficient_privilege using message='subscription_actor_required';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 perform private.lock_account_action_subject(p_actor);
 select * into profile from public.profiles where id=p_actor for share;
 if not found then raise insufficient_privilege using message='subscription_actor_unavailable';end if;
 if p_new_write and (profile.suspended_at is not null or private.is_account_write_fenced(p_actor)
  or profile.onboarded_at is null or profile.birth_date is null or profile.birth_date>current_date
  or nullif(btrim(profile.nickname),'') is null or nullif(btrim(coalesce(profile.email,(select email from auth.users where id=p_actor))),'') is null
  or profile.consents->>'terms' is distinct from 'true' or profile.consents->>'privacy' is distinct from 'true') then
  raise insufficient_privilege using message='subscription_actor_unavailable';end if;
end $function$

CREATE OR REPLACE FUNCTION private.subscription_normalize_schedule(p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$declare anchor date; cadence integer;begin
 if not coalesce(private.subscription_json_keys(p_value,array['unit','interval','anchorDate','time','monthEnd']),false)
  or jsonb_typeof(p_value->'unit') is distinct from 'string' or p_value->>'unit' not in('week','month')
  or jsonb_typeof(p_value->'interval') is distinct from 'number' or p_value->>'interval'!~'^[1-4]$'
  or jsonb_typeof(p_value->'anchorDate') is distinct from 'string' or p_value->>'anchorDate'!~'^(20|21)[0-9]{2}-[0-9]{2}-[0-9]{2}$'
  or jsonb_typeof(p_value->'time') is distinct from 'string' or p_value->>'time'!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'
  or jsonb_typeof(p_value->'monthEnd') is distinct from 'boolean' then
  raise invalid_parameter_value using message='invalid_subscription_schedule';end if;
 anchor:=(p_value->>'anchorDate')::date;cadence:=(p_value->>'interval')::integer;
 if (p_value->>'unit'='week' and (cadence not in(1,2,4) or (p_value->>'monthEnd')::boolean))
  or (p_value->>'unit'='month' and cadence not in(1,2,3)) then
  raise invalid_parameter_value using message='invalid_subscription_schedule';end if;
 return jsonb_build_object('unit',p_value->>'unit','interval',cadence,'anchorDate',anchor::text,'time',p_value->>'time','monthEnd',(p_value->>'monthEnd')::boolean);
exception when datetime_field_overflow or invalid_datetime_format then
 raise invalid_parameter_value using message='invalid_subscription_schedule';
end $function$

CREATE OR REPLACE FUNCTION private.subscription_operation_replay(p_actor uuid, p_plan uuid, p_operation uuid, p_command text, p_request_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare entry private.goods_subscription_operations;begin
 if p_operation is null then raise invalid_parameter_value using message='invalid_subscription_operation';end if;
 perform pg_advisory_xact_lock(hashtextextended('subscription-operation:'||p_operation::text,0));
 select * into entry from private.goods_subscription_operations where operation_id=p_operation;
 if not found then return null;end if;
 if entry.owner_id<>p_actor or entry.plan_id<>p_plan or entry.command<>p_command or entry.request_hash<>p_request_hash then
  raise sqlstate 'PT409' using message='subscription_operation_conflict';end if;
 return entry.receipt;
end $function$

CREATE OR REPLACE FUNCTION private.subscription_release_unpaid_order(p_order_id uuid, p_allow_declined boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare order_state public.order_status;begin
 if p_order_id is null then return;end if;
 select status into order_state from public.orders where id=p_order_id for update;
 if order_state<>'pending' then return;end if;
 if exists(select 1 from public.order_cancellation_requests where order_id=p_order_id and status in('requested','processing','needs_review'))
  or exists(select 1 from public.payments where purpose='order' and ref_id=p_order_id and status in('pending','paid'))
  or exists(select 1 from public.payment_attempts a left join private.payment_provider_bindings b on b.attempt_id=a.id
   where a.purpose='order' and a.ref_id=p_order_id and (a.state not in('prepared','declined') or (b.first_dispatched_at is not null and (not p_allow_declined or a.state<>'declined')))) then return;end if;
 perform public.cancel_order(p_order_id,'정기배송 미청구 회차 정리');
end $function$

CREATE OR REPLACE FUNCTION private.subscription_slot_at(p_schedule jsonb, p_slot integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$declare schedule jsonb;anchor date;target date;last_day date;begin
 schedule:=private.subscription_normalize_schedule(p_schedule);
 if p_slot is null or p_slot not between 0 and 1200 then raise invalid_parameter_value using message='invalid_subscription_schedule';end if;
 anchor:=(schedule->>'anchorDate')::date;
 if schedule->>'unit'='week' then target:=anchor+(7*(schedule->>'interval')::integer*p_slot);
 else
  target:=(date_trunc('month',anchor::timestamp)+make_interval(months=>(schedule->>'interval')::integer*p_slot))::date;
  last_day:=(target+interval '1 month'-interval '1 day')::date;
  target:=case when (schedule->>'monthEnd')::boolean then last_day
   else target+(least(extract(day from anchor)::integer,extract(day from last_day)::integer)-1) end;
 end if;
 return (target+(schedule->>'time')::time) at time zone 'Asia/Seoul';
end $function$

CREATE OR REPLACE FUNCTION private.subscription_stop_cycle(p_cycle_id uuid, p_reason text, p_canceled boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare cycle private.goods_subscription_cycles;begin
 select * into cycle from private.goods_subscription_cycles where id=p_cycle_id for update;
 if not found or cycle.dispatched_at is not null or cycle.state not in('draft','ready','prepared') then return;end if;
 perform private.subscription_release_unpaid_order(cycle.order_id);
 update private.goods_subscription_cycles set state=case when p_canceled then 'canceled' else 'skipped' end,safe_reason=p_reason,
  claim_token=null,lease_until=null,claim_fence=claim_fence+1,revision=revision+1,updated_at=clock_timestamp() where id=p_cycle_id;
end $function$

CREATE OR REPLACE FUNCTION private.subscription_sync_cycle_outcome(p_cycle_id uuid, p_outcome public.payment_attempt_state)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare cycle private.goods_subscription_cycles;plan private.goods_subscription_plans;terms private.goods_subscription_terms;slot integer;due timestamptz;new_cycle uuid;
begin
 select * into cycle from private.goods_subscription_cycles where id=p_cycle_id for update;
 if not found then raise no_data_found using message='subscription_cycle_not_found';end if;
 if cycle.state in('approved','declined','canceled','skipped') then return;end if;
 select * into plan from private.goods_subscription_plans where id=cycle.plan_id for update;
 if p_outcome not in('approved','declined','canceled','unknown','needs_review') then raise invalid_parameter_value using message='invalid_subscription_outcome';end if;
 update private.goods_subscription_cycles set state=p_outcome::text,claim_token=null,lease_until=null,claim_fence=claim_fence+1,revision=revision+1,
  settled_at=case when p_outcome in('approved','declined','canceled') then clock_timestamp() end,
  next_check_at=case when p_outcome='unknown' and claim_fence<12 then clock_timestamp()+interval '5 minutes' end,
  safe_reason=case when p_outcome='approved' then null when p_outcome='declined' then 'payment_failed' else 'payment_review' end,updated_at=clock_timestamp()
  where id=p_cycle_id;
 if p_outcome='unknown' and cycle.claim_fence>=12 then
  update private.goods_subscription_cycles set state='needs_review',next_check_at=null where id=p_cycle_id;
  p_outcome:='needs_review';
 end if;
 if p_outcome='approved' and (plan.state in('active','awaiting_first_payment') or plan.state='paused' and plan.pause_reason='payment_review') then
  select * into terms from private.goods_subscription_terms where id=plan.current_terms_id;
  slot:=case when terms.id=cycle.terms_id then cycle.schedule_slot+1 else 0 end;
  if slot>1200 then
   update private.goods_subscription_plans set state='paused',pause_reason='schedule_missed',next_run_at=null,revision=revision+1,updated_at=clock_timestamp() where id=plan.id;return;
  end if;
  due:=private.subscription_slot_at(terms.schedule,slot);
  if due<=clock_timestamp() then
   update private.goods_subscription_plans set state='paused',pause_reason='schedule_missed',next_run_at=null,revision=revision+1,updated_at=clock_timestamp() where id=plan.id;return;
  end if;
  new_cycle:=gen_random_uuid();
  insert into private.goods_subscription_cycles(id,plan_id,owner_id,cycle_number,schedule_slot,terms_id,scheduled_at,state)
   values(new_cycle,plan.id,plan.owner_id,plan.last_cycle_number+1,slot,terms.id,due,'ready');
  update private.goods_subscription_plans set state='active',pause_reason=null,next_slot=slot,next_run_at=due,
   last_cycle_number=last_cycle_number+1,revision=revision+1,updated_at=clock_timestamp() where id=plan.id;
 elsif p_outcome in('declined','canceled') then
  if p_outcome='declined' then perform private.subscription_release_unpaid_order(cycle.order_id,true);end if;
  update private.goods_subscription_plans set state='paused',pause_reason='payment_failed',next_run_at=null,revision=revision+1,updated_at=clock_timestamp()
   where id=plan.id and state in('active','awaiting_first_payment');
 elsif p_outcome='needs_review' then
  update private.goods_subscription_plans set state='paused',pause_reason='payment_review',next_run_at=null,revision=revision+1,updated_at=clock_timestamp()
   where id=plan.id and state in('active','awaiting_first_payment');
 end if;
end $function$

CREATE OR REPLACE FUNCTION private.supersede_unpaid_cart_orders(p_user_id uuid, p_new_order boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_user_id is null or p_new_order is null then
    raise invalid_parameter_value using message = 'cart_order_supersede_invalid';
  end if;
  return private.supersede_unpaid_checkout_orders(p_user_id, p_new_order,
    case when p_new_order then null else array['legacy_checkout', 'cart_transaction'] end,
    case when p_new_order then 'new_cart_order' else 'returned_to_cart' end);
end;
$function$

CREATE OR REPLACE FUNCTION private.supersede_unpaid_checkout_orders(p_user_id uuid, p_new_order boolean, p_sources text[], p_trigger text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  v_result text;
  v_closed integer := 0;
  v_reason text;
begin
  if p_user_id is null or p_new_order is null
    or p_trigger is null or p_trigger not in ('new_cart_order', 'returned_to_cart', 'new_direct_order', 'customer_released') then
    raise invalid_parameter_value using message = 'cart_order_supersede_invalid';
  end if;
  v_reason := case p_trigger
    when 'new_cart_order' then '같은 장바구니로 새 주문을 만들어 결제 대기 주문 자동 취소'
    when 'returned_to_cart' then '장바구니로 돌아와 결제 대기 주문 자동 취소'
    when 'new_direct_order' then '바로구매로 새 주문을 만들어 결제 대기 주문 자동 취소'
    else '고객이 진행 중인 미결제 주문을 취소하고 주문을 계속함' end;
  perform 1
  from public.orders as o
  join private.cart_order_holds as hold on hold.order_id = o.id
  where hold.user_id = p_user_id and hold.state = 'awaiting_payment'
    and (p_sources is null or hold.source = any (p_sources))
  order by o.id
  for update of o;
  if not found then
    return 0;
  end if;
  perform private.lock_account_action_subject(p_user_id);
  for r in
    select hold.order_id
    from private.cart_order_holds as hold
    where hold.user_id = p_user_id and hold.state = 'awaiting_payment'
      and (p_sources is null or hold.source = any (p_sources))
    order by hold.created_at, hold.order_id
  loop
    v_result := private.close_unpaid_cart_order(r.order_id, v_reason, p_trigger);
    if v_result = 'closed' then
      v_closed := v_closed + 1;
    elsif v_result = 'payment_confirming' and p_new_order then
      -- detail = 승인 확인 중인 주문. 주문서가 '결제 확인 중인 주문이 있어요'와 그 주문으로 안내한다.
      raise sqlstate 'PT409' using message = 'checkout_payment_in_progress', detail = r.order_id::text;
    elsif v_result = 'unresolved' and p_new_order then
      update private.cart_order_holds
      set state = 'released', settled_at = pg_catalog.clock_timestamp(), release_reason = 'detached'
      where order_id = r.order_id and state = 'awaiting_payment';
      insert into public.audit_log (actor_id, action, target, diff)
      values (null, 'system.order.cart_hold_detached', 'order:' || r.order_id::text,
        pg_catalog.jsonb_build_object('trigger', p_trigger, 'actor', 'system'));
    end if;
  end loop;
  return v_closed;
end;
$function$

CREATE OR REPLACE FUNCTION private.sweep_goods_provider_cancellation_checks(p_limit integer DEFAULT 200)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item record; settled integer := 0; verdict text;
begin
  perform set_config('lock_timeout', '3s', true);
  for item in select attempt_id, observed_status, observed_balance, case_ref from private.goods_provider_cancellation_checks
    where pending order by updated_at, attempt_id limit greatest(1, least(coalesce(p_limit, 200), 1000)) loop
    begin
      verdict := private.apply_goods_provider_cancellation(item.attempt_id, item.observed_status, item.observed_balance, item.case_ref);
      if verdict <> 'in_flight' then settled := settled + 1; end if;
    exception when lock_not_available or deadlock_detected then
      -- 이번 회차에 못 본 행도 뒤로 보낸다(같은 행이 매번 앞을 막지 않게).
      update private.goods_provider_cancellation_checks set updated_at = clock_timestamp() where attempt_id = item.attempt_id;
    end;
  end loop;
  return settled;
end $function$

CREATE OR REPLACE FUNCTION private.sync_marketing_consent_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare wanted boolean; derived boolean; channel_value text; changed_at timestamptz:=clock_timestamp();
begin
 if new.consents->'marketing' is not distinct from old.consents->'marketing' then return null; end if;
 wanted:=coalesce(new.consents->'marketing'='true'::jsonb,false);
 derived:=exists(select 1 from private.customer_marketing_consents c where c.user_id=new.id and c.agreed);
 if wanted=derived then return null; end if;
 if wanted then
  perform private.write_customer_marketing_consent(new.id,'email',true,'marketing-legacy-v0','legacy_app',changed_at);
 else
  for channel_value in select c.channel from private.customer_marketing_consents c where c.user_id=new.id and c.agreed order by c.channel loop
   perform private.write_customer_marketing_consent(new.id,channel_value,false,'marketing-legacy-v0','legacy_app',changed_at);
  end loop;
 end if;
 return null;
end $function$

