CREATE OR REPLACE FUNCTION private.validate_goods_relation_composition(p_values jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare relation_kind text; visual jsonb; ids text[]; point jsonb; seen text[]:='{}'; labels_seen text[]:='{}'; label_value text; starts_value timestamptz;ends_value timestamptz;
begin
 if jsonb_typeof(p_values) is distinct from 'object'
  or not(p_values ?& array['kind','title','representativeGoodId','enabled','startsAt','endsAt','goodIds','visual'])
  or exists(select 1 from jsonb_object_keys(p_values) key where key<>all(array['kind','title','representativeGoodId','enabled','startsAt','endsAt','goodIds','visual']||case when p_values->>'kind'='other_composition' then array['compositionLabels'] else '{}'::text[] end))
  or jsonb_typeof(p_values->'kind') is distinct from 'string' or p_values->>'kind' not in ('together','similar','codi','other_composition')
  or jsonb_typeof(p_values->'title') is distinct from 'string' or char_length(btrim(p_values->>'title')) not between 1 and 15
  or jsonb_typeof(p_values->'representativeGoodId') is distinct from 'string' or jsonb_typeof(p_values->'enabled') is distinct from 'boolean'
  or jsonb_typeof(p_values->'goodIds') is distinct from 'array' or jsonb_typeof(p_values->'startsAt') not in ('null','string')
  or jsonb_typeof(p_values->'endsAt') not in ('null','string') or jsonb_typeof(p_values->'visual') not in ('null','object')
 then raise invalid_parameter_value using message='invalid_goods_relation';end if;
 relation_kind:=p_values->>'kind';visual:=nullif(p_values->'visual','null'::jsonb);
 if jsonb_array_length(p_values->'goodIds') not between 2 and (case when visual is not null or relation_kind='codi' then 5 when relation_kind='together' then 6 else 10 end)
  or exists(select 1 from jsonb_array_elements(p_values->'goodIds') item where jsonb_typeof(item)<>'string' or item#>>'{}' !~ '^[a-z0-9][a-z0-9-]{0,119}$')
 then raise invalid_parameter_value using message='invalid_goods_relation_goods';end if;
 select array_agg(value order by position) into ids from jsonb_array_elements_text(p_values->'goodIds') with ordinality item(value,position);
 if cardinality(ids)<>(select count(distinct id) from unnest(ids) id) or not(p_values->>'representativeGoodId'=any(ids)) then raise invalid_parameter_value using message='invalid_goods_relation_goods';end if;
 begin starts_value:=(p_values->>'startsAt')::timestamptz;ends_value:=(p_values->>'endsAt')::timestamptz;
 exception when invalid_datetime_format or datetime_field_overflow then raise invalid_parameter_value using message='invalid_goods_relation_period';end;
 if starts_value is not null and not isfinite(starts_value) or ends_value is not null and not isfinite(ends_value)
  or starts_value is not null and ends_value is not null and starts_value>=ends_value then raise invalid_parameter_value using message='invalid_goods_relation_period';end if;
 if relation_kind='codi' and visual is null or relation_kind in ('similar','other_composition') and visual is not null then raise invalid_parameter_value using message='invalid_goods_relation_visual';end if;
 if relation_kind='other_composition' then
  if btrim(p_values->>'title')<>btrim(p_values->>'title',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') or (p_values->>'title') ~ '[[:cntrl:]]' then
   raise invalid_parameter_value using message='invalid_goods_relation';end if;
  if jsonb_typeof(p_values->'compositionLabels') is distinct from 'array' or jsonb_array_length(p_values->'compositionLabels')>10 then
   raise invalid_parameter_value using message='invalid_goods_relation_composition_labels';end if;
  for point in select value from jsonb_array_elements(p_values->'compositionLabels') loop
   if jsonb_typeof(point) is distinct from 'object' or not(point ?& array['goodId','label'])
    or (select count(*) from jsonb_object_keys(point))<>2
    or jsonb_typeof(point->'goodId') is distinct from 'string' or not(point->>'goodId'=any(ids)) or point->>'goodId'=any(labels_seen)
    or jsonb_typeof(point->'label') is distinct from 'string' then
     raise invalid_parameter_value using message='invalid_goods_relation_composition_labels';end if;
   label_value:=point->>'label';
   if char_length(label_value) not between 1 and 40 or label_value<>btrim(label_value,U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
    or label_value ~ '[[:cntrl:]]' then raise invalid_parameter_value using message='invalid_goods_relation_composition_labels';end if;
   labels_seen:=array_append(labels_seen,point->>'goodId');
  end loop;
 end if;
 if visual is null then return;end if;
 if not(visual ?& array['imagePath','alt','description','hotspots'])
  or exists(select 1 from jsonb_object_keys(visual) key where key<>all(array['imagePath','alt','description','hotspots']))
  or jsonb_typeof(visual->'imagePath') is distinct from 'string'
  or visual->>'imagePath' !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  or jsonb_typeof(visual->'alt') is distinct from 'string' or char_length(btrim(visual->>'alt')) not between 1 and 120
  or jsonb_typeof(visual->'description') is distinct from 'string' or char_length(btrim(visual->>'description'))>90
  or jsonb_typeof(visual->'hotspots') is distinct from 'array' or jsonb_array_length(visual->'hotspots')>5
 then raise invalid_parameter_value using message='invalid_goods_relation_visual';end if;
 for point in select value from jsonb_array_elements(visual->'hotspots') loop
  if jsonb_typeof(point) is distinct from 'object' or not(point ?& array['goodId','x','y'])
   or exists(select 1 from jsonb_object_keys(point) key where key<>all(array['goodId','x','y']))
   or jsonb_typeof(point->'goodId') is distinct from 'string' or not(point->>'goodId'=any(ids)) or point->>'goodId'=any(seen)
   or jsonb_typeof(point->'x') is distinct from 'number' or point->>'x' !~ '^[0-9]{1,5}$'
   or jsonb_typeof(point->'y') is distinct from 'number' or point->>'y' !~ '^[0-9]{1,5}$'
  then raise invalid_parameter_value using message='invalid_goods_relation_visual';end if;
  if (point->>'x')::integer>10000 or (point->>'y')::integer>10000 then raise invalid_parameter_value using message='invalid_goods_relation_visual';end if;
  seen:=array_append(seen,point->>'goodId');
 end loop;
end $function$

CREATE OR REPLACE FUNCTION private.validate_goods_size_chart(p_chart jsonb, p_allow_empty boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
 size_item jsonb; measure_item jsonb; cell_item jsonb; label text; cell_value text; note_value text;
 sizes jsonb:='[]'; measures jsonb:='[]'; cells jsonb; names text[]:='{}'; normalized_size text[]:='{}';
begin
 if p_chart is null or jsonb_typeof(p_chart)<>'object'
  or not p_chart ?& array['unit','sizes','measurements','note']
  or p_chart-array['unit','sizes','measurements','note']<>'{}'::jsonb
  or jsonb_typeof(p_chart->'unit')<>'string' or p_chart->>'unit' not in ('cm','mm')
  or jsonb_typeof(p_chart->'sizes')<>'array' or jsonb_typeof(p_chart->'measurements')<>'array'
  or jsonb_typeof(p_chart->'note')<>'string' then
  raise invalid_parameter_value using message='invalid_goods_size_chart';
 end if;
 note_value:=btrim(replace(replace(p_chart->>'note',E'\r\n',E'\n'),E'\r',E'\n'),E' \n\t');
 if char_length(note_value)>500 or translate(note_value,E'\n\t','')~'[[:cntrl:]]' or note_value~'[<>]' then
  raise invalid_parameter_value using message='invalid_goods_size_chart';
 end if;
 if p_allow_empty and p_chart->'sizes'='[]'::jsonb and p_chart->'measurements'='[]'::jsonb and note_value='' then
  return jsonb_build_object('unit',p_chart->>'unit','sizes','[]'::jsonb,'measurements','[]'::jsonb,'note','');
 end if;
 if jsonb_array_length(p_chart->'sizes') not between 1 and 10 or jsonb_array_length(p_chart->'measurements') not between 1 and 10 then
  raise invalid_parameter_value using message='invalid_goods_size_chart';
 end if;
 for size_item in select value from jsonb_array_elements(p_chart->'sizes') loop
  if jsonb_typeof(size_item)<>'string' then raise invalid_parameter_value using message='invalid_goods_size_chart';end if;
  label:=btrim(size_item#>>'{}',E' \n\r\t');
  if char_length(label) not between 1 and 10 or label~'[[:cntrl:]<>]' or label=any(normalized_size) then
   raise invalid_parameter_value using message='invalid_goods_size_chart';end if;
  normalized_size:=array_append(normalized_size,label);sizes:=sizes||jsonb_build_array(label);
 end loop;
 for measure_item in select value from jsonb_array_elements(p_chart->'measurements') loop
  if jsonb_typeof(measure_item)<>'object' or not measure_item ?& array['name','values']
   or measure_item-array['name','values']<>'{}'::jsonb or jsonb_typeof(measure_item->'name')<>'string'
   or jsonb_typeof(measure_item->'values')<>'array' then
   raise invalid_parameter_value using message='invalid_goods_size_chart';end if;
  label:=btrim(measure_item->>'name',E' \n\r\t');
  if char_length(label) not between 1 and 20 or label~'[[:cntrl:]<>]' or label=any(names)
   or jsonb_array_length(measure_item->'values')<>jsonb_array_length(sizes) then
   raise invalid_parameter_value using message='invalid_goods_size_chart';end if;
  names:=array_append(names,label);cells:='[]';
  for cell_item in select value from jsonb_array_elements(measure_item->'values') loop
   if jsonb_typeof(cell_item)<>'string' then raise invalid_parameter_value using message='invalid_goods_size_chart';end if;
   cell_value:=btrim(cell_item#>>'{}',E' \n\r\t');
   if cell_value!~'^(0|[1-9][0-9]{0,4})(\.[0-9])?$' then raise invalid_parameter_value using message='invalid_goods_size_chart';end if;
   if cell_value::numeric<0.1 or cell_value::numeric>99999 then raise invalid_parameter_value using message='invalid_goods_size_chart';end if;
   cell_value:=regexp_replace(cell_value,'\.0$','');
   cells:=cells||jsonb_build_array(cell_value);
  end loop;
  measures:=measures||jsonb_build_array(jsonb_build_object('name',label,'values',cells));
 end loop;
 return jsonb_build_object('unit',p_chart->>'unit','sizes',sizes,'measurements',measures,'note',note_value);
end $function$

CREATE OR REPLACE FUNCTION private.validate_order_custom_inputs_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare snapshot jsonb:=new.custom_inputs_snapshot; canonical jsonb; values_by_id jsonb;
begin
  if snapshot is null then
    perform private.resolve_goods_custom_inputs(new.good_id,0,'{}');
    return new;
  end if;
  if jsonb_typeof(snapshot) is distinct from 'object' or jsonb_typeof(snapshot->'fields') is distinct from 'array'
    or jsonb_typeof(snapshot->'revision') is distinct from 'number' then raise check_violation using message='invalid_goods_custom_inputs'; end if;
  select coalesce(jsonb_object_agg(field->>'id',field->'value'),'{}') into values_by_id from jsonb_array_elements(snapshot->'fields') field;
  canonical:=private.resolve_goods_custom_inputs(new.good_id,(snapshot->>'revision')::integer,values_by_id);
  if canonical is distinct from snapshot then raise check_violation using message='invalid_goods_custom_inputs'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.validate_pii_access_log_filters(p_from date, p_to date, p_action text, p_surface text, p_flag text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if p_from is null or p_to is null or p_from > p_to or p_to - p_from > 366 then
    raise invalid_parameter_value using message = 'pii_access_log_range_invalid';
  end if;
  if (p_action is not null and p_action not in ('view', 'search', 'export', 'reveal', 'correct'))
    or (p_surface is not null and p_surface !~ '^[a-z][a-z_]{0,31}([.][a-z][a-z_]{0,31}){0,2}$')
    or (p_flag is not null and p_flag not in ('any', 'off_hours', 'bulk', 'burst')) then
    raise invalid_parameter_value using message = 'pii_access_log_filter_invalid';
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.validate_shipping_settings_charge_apply(p_request jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$declare legacy jsonb;row jsonb;target jsonb;begin
 if not private.transaction_json_keys(p_request,array['operationId','command','templateId','expectedRevision','expectedActorId','expectedSessionId',
  'originUpdatedAt','collectRevision','collectVersionId','goods','targetGroup']) then
  raise invalid_parameter_value using message='invalid_shipping_settings_application';end if;
 if jsonb_typeof(p_request->'goods') is distinct from 'array' then
  raise invalid_parameter_value using message='invalid_shipping_settings_targets';end if;
 target:=p_request->'targetGroup';
 if target<>'null'::jsonb and not coalesce(private.transaction_json_keys(target,array['id','revision'])
  and private.shipping_settings_uuid(target->'id') and private.transaction_uint(target->'revision',1,2147483647),false) then
  raise invalid_parameter_value using message='invalid_shipping_settings_charge_group';end if;
 for row in select value from jsonb_array_elements(p_request->'goods') loop
  if not private.transaction_json_keys(row-'fulfillmentRevision',array['id','updatedAt','ownerGoodId','ownerUpdatedAt','familyGoodIds','transactionRevision','deliveryVersionId',
   'assignmentRevision','assignmentVersionId','groupId','groupRevision'])
   or (row ? 'fulfillmentRevision' and not private.transaction_uint(row->'fulfillmentRevision',0,2147483647))
   or not private.transaction_uint(row->'assignmentRevision',0,2147483647)
   or not(row->'assignmentVersionId'='null'::jsonb or private.shipping_settings_uuid(row->'assignmentVersionId'))
   or (row->>'assignmentRevision'='0') is distinct from (row->'assignmentVersionId'='null'::jsonb)
   or not(row->'groupId'='null'::jsonb or private.shipping_settings_uuid(row->'groupId'))
   or not(row->'groupRevision'='null'::jsonb or private.transaction_uint(row->'groupRevision',1,2147483647))
   or (row->'groupId'='null'::jsonb) is distinct from (row->'groupRevision'='null'::jsonb)
   or (row->'groupId'<>'null'::jsonb and row->>'assignmentRevision'='0') then
   raise invalid_parameter_value using message='invalid_shipping_settings_targets';end if;
 end loop;
 legacy:=(p_request-'targetGroup')||jsonb_build_object('goods',(select jsonb_agg(value-array['assignmentRevision','assignmentVersionId','groupId','groupRevision','fulfillmentRevision'])
  from jsonb_array_elements(p_request->'goods')));
 perform private.validate_shipping_settings_apply(legacy);
end $function$

CREATE OR REPLACE FUNCTION private.validate_shipping_settings_charge(p_settings jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$declare directive jsonb;begin
 perform private.validate_shipping_settings_extended(p_settings-array['chargeGroup','fulfillment']);
 if p_settings ? 'fulfillment' then perform private.validate_shipping_settings_fulfillment(p_settings->'fulfillment');end if;
 if not(p_settings ? 'chargeGroup') then return;end if;
 directive:=p_settings->'chargeGroup';
 if private.transaction_json_keys(directive,array['mode']) and directive->>'mode' in('preserve','clear') then return;end if;
 if not coalesce(private.transaction_json_keys(directive,array['mode','groupId']) and directive->>'mode'='assign'
  and private.shipping_settings_uuid(directive->'groupId'),false) then
