CREATE OR REPLACE FUNCTION private.validate_shipping_settings_fulfillment(p_directive jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare p jsonb;m jsonb;begin
 if private.transaction_json_keys(p_directive,array['mode']) and p_directive->>'mode'='preserve' then return;end if;
 if not private.transaction_json_keys(p_directive,array['mode','policy']) or p_directive->>'mode' is distinct from 'replace' then raise invalid_parameter_value using message='invalid_shipping_settings_fulfillment';end if;
 p:=p_directive->'policy';
 if not private.transaction_json_keys(p,array['mode','methods','publicNote','evidence','confirmed']) or coalesce(p->>'mode','') not in('shipping','no_delivery')
  or p->'confirmed' is distinct from 'true'::jsonb or jsonb_typeof(p->'methods') is distinct from 'array' or jsonb_array_length(p->'methods') not between 1 and 5
  or jsonb_typeof(p->'publicNote') is distinct from 'string' or char_length(p->>'publicNote')>1000 or p->>'publicNote'<>btrim(p->>'publicNote')
  or jsonb_typeof(p->'evidence') is distinct from 'string' or char_length(p->>'evidence') not between 2 and 1000 or p->>'evidence'<>btrim(p->>'evidence')
  or ((p->>'publicNote')||(p->>'evidence'))~'[[:cntrl:]]' then raise invalid_parameter_value using message='invalid_shipping_settings_fulfillment';end if;
 if (select count(distinct value->>'method') from jsonb_array_elements(p->'methods'))<>jsonb_array_length(p->'methods') then raise invalid_parameter_value;end if;
 for m in select value from jsonb_array_elements(p->'methods') loop
  if not private.transaction_json_keys(m,array['method','feeAmount','feeBasis','installationFee']) or coalesce(m->>'method','') not in('parcel','quick','pickup','direct','freight','none')
   or coalesce(m->>'feeBasis','') not in('per_order','per_item') or not private.transaction_uint(m->'installationFee',0,1000000)
   or (m->>'method'='parcel') is distinct from (m->'feeAmount'='null'::jsonb)
   or m->>'method'<>'parcel' and not private.transaction_uint(m->'feeAmount',0,1000000)
   or m->>'method' in('pickup','none') and (m->'feeAmount'<>'0'::jsonb or m->'installationFee'<>'0'::jsonb)
   or m->>'method'='parcel' and m->>'feeBasis'<>'per_order'
   or p->>'mode'='shipping' and m->>'method'='none' or p->>'mode'='no_delivery' and m->>'method'<>'none'
   then raise invalid_parameter_value using message='invalid_shipping_settings_fulfillment';end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION private.validate_shopping_story_values(p_values jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare section_value jsonb; item jsonb; image_value jsonb; section_ids uuid[]:='{}'; good_ids text[]:='{}'; images text[]:='{}'; section_id uuid; start_value timestamptz; end_value timestamptz;
begin
 if p_values is null or jsonb_typeof(p_values)<>'object'
  or exists(select 1 from jsonb_object_keys(p_values) k where k not in ('title','bodyHtml','imagePaths','startsAt','endsAt','sections'))
  or not(p_values ?& array['title','bodyHtml','imagePaths','startsAt','endsAt','sections'])
  or jsonb_typeof(p_values->'title')<>'string' or char_length(btrim(p_values->>'title')) not between 1 and 50
  or jsonb_typeof(p_values->'bodyHtml')<>'string' or char_length(p_values->>'bodyHtml') not between 1 and 30000
  or jsonb_typeof(p_values->'imagePaths')<>'array' or jsonb_array_length(p_values->'imagePaths')>20
  or jsonb_typeof(p_values->'sections')<>'array' or jsonb_array_length(p_values->'sections')>10
  or jsonb_typeof(p_values->'startsAt') not in ('null','string') or jsonb_typeof(p_values->'endsAt') not in ('null','string')
  or (p_values->>'startsAt' is not null and (p_values->>'startsAt')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$')
  or (p_values->>'endsAt' is not null and (p_values->>'endsAt')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$')
 then raise invalid_parameter_value using message='invalid_shopping_story';end if;
 begin
  start_value:=(p_values->>'startsAt')::timestamptz; end_value:=(p_values->>'endsAt')::timestamptz;
 exception when others then raise invalid_parameter_value using message='invalid_shopping_story_window';end;
 if (start_value is not null and not isfinite(start_value)) or (end_value is not null and not isfinite(end_value))
  or (start_value is not null and end_value is not null and start_value>=end_value)
 then raise invalid_parameter_value using message='invalid_shopping_story_window';end if;
 for image_value in select value from jsonb_array_elements(p_values->'imagePaths') loop
  if jsonb_typeof(image_value)<>'string' or (image_value#>>'{}')!~'^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
   or (image_value#>>'{}')=any(images) then raise invalid_parameter_value using message='invalid_shopping_story_images';end if;
  images:=array_append(images,image_value#>>'{}');
 end loop;
 for section_value in select value from jsonb_array_elements(p_values->'sections') loop
  if jsonb_typeof(section_value)<>'object'
   or exists(select 1 from jsonb_object_keys(section_value) k where k not in ('id','title','imageShape','goodIds'))
   or not(section_value ?& array['id','title','imageShape','goodIds'])
   or jsonb_typeof(section_value->'id')<>'string' or (section_value->>'id')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(section_value->'title')<>'string' or char_length(btrim(section_value->>'title')) not between 1 and 13
   or jsonb_typeof(section_value->'imageShape')<>'string' or section_value->>'imageShape' not in ('square','portrait')
   or jsonb_typeof(section_value->'goodIds')<>'array' or jsonb_array_length(section_value->'goodIds') not between 1 and 200
  then raise invalid_parameter_value using message='invalid_shopping_story_section';end if;
  section_id:=(section_value->>'id')::uuid;
  if section_id=any(section_ids) then raise invalid_parameter_value using message='invalid_shopping_story_section';end if;
  section_ids:=array_append(section_ids,section_id);
  for item in select value from jsonb_array_elements(section_value->'goodIds') loop
   if jsonb_typeof(item)<>'string' or (item#>>'{}')!~'^[a-z0-9][a-z0-9-]{0,119}$' or (item#>>'{}')=any(good_ids)
   then raise invalid_parameter_value using message='invalid_shopping_story_goods';end if;
   good_ids:=array_append(good_ids,item#>>'{}');
  end loop;
 end loop;
 if cardinality(good_ids)>300 then raise invalid_parameter_value using message='shopping_story_goods_limit';end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.write_customer_marketing_consent(p_user uuid, p_channel text, p_choice boolean, p_notice_version text, p_source text, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_row private.customer_marketing_consents; had_row boolean;
begin
 select * into current_row from private.customer_marketing_consents c where c.user_id=p_user and c.channel=p_channel for update;
 had_row:=found;
 if had_row and current_row.agreed=p_choice then return false; end if;
 insert into private.customer_marketing_consents(user_id,channel,agreed,notice_version,source,agreed_at,withdrawn_at,revision,updated_at)
 values(p_user,p_channel,p_choice,p_notice_version,p_source,
  case when p_choice then p_at end,
  case when not p_choice and had_row and current_row.agreed then p_at end,
  coalesce(current_row.revision,0)+1,p_at)
 on conflict(user_id,channel) do update set agreed=excluded.agreed,notice_version=excluded.notice_version,source=excluded.source,
  agreed_at=excluded.agreed_at,withdrawn_at=excluded.withdrawn_at,revision=excluded.revision,updated_at=excluded.updated_at;
 insert into private.customer_marketing_consent_events(user_id,channel,agreed,notice_version,source,occurred_at)
 values(p_user,p_channel,p_choice,p_notice_version,p_source,p_at);
 return true;
end $function$

CREATE OR REPLACE FUNCTION private.write_shipping_charge_group_version(p_group_id uuid, p_origin_id uuid, p_values jsonb, p_actor uuid, p_session uuid, p_operation uuid, p_confirmed_by uuid, p_confirmed_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare previous private.shipping_charge_groups;version_id uuid:=gen_random_uuid();revision integer;begin
 select * into previous from private.shipping_charge_groups where id=p_group_id;
 if found and previous.origin_id<>p_origin_id then raise check_violation using message='shipping_charge_group_origin_immutable';end if;
 revision:=coalesce(previous.revision,0)+1;
 insert into private.shipping_charge_groups(id,origin_id,revision,version_id,is_default,created_by,updated_by)
 values(p_group_id,p_origin_id,revision,version_id,(p_values->>'isDefault')::boolean,p_actor,p_actor)
 on conflict(id) do update set revision=excluded.revision,version_id=excluded.version_id,is_default=excluded.is_default,
  updated_by=p_actor,updated_at=greatest(clock_timestamp(),private.shipping_charge_groups.updated_at+interval '1 microsecond');
 insert into private.shipping_charge_group_versions(id,group_id,revision,policy_values,regional_confirmed_by,regional_confirmed_at,created_by,session_id,operation_id)
 values(version_id,p_group_id,revision,p_values,p_confirmed_by,p_confirmed_at,p_actor,p_session,p_operation);
end $function$

CREATE OR REPLACE FUNCTION public.accept_operator_invitation(p_token_hash text, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); state private.operator_access_state; invitation private.operator_invitations; current_email text; confirmed_at timestamptz; result jsonb; request jsonb;
begin
  if actor is null then raise insufficient_privilege using message='authentication_required'; end if;
  if p_operation_id is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then raise invalid_parameter_value using message='invalid_operator_invitation'; end if;
  select * into strict state from private.operator_access_state where id for update;
  select * into invitation from private.operator_invitations where token_hash=decode(p_token_hash,'hex');
  if not found then raise insufficient_privilege using message='operator_invitation_unavailable'; end if;
  perform private.lock_operator_subjects(array[actor,invitation.created_by]);
  select * into invitation from private.operator_invitations where id=invitation.id for update;
  if not state.configured or not exists(select 1 from public.profiles where id=actor and suspended_at is null)
    or exists(select 1 from private.account_action_fences where subject_user_id=actor) then raise insufficient_privilege using message='operator_invitation_unavailable'; end if;
  select lower(email),email_confirmed_at into current_email,confirmed_at from auth.users where id=actor for share;
  if confirmed_at is null then raise insufficient_privilege using message='operator_invitation_email_unverified'; end if;
  if invitation.status='accepted' and invitation.accepted_by=actor then
    return jsonb_build_object('status','accepted','managerRole',(select manager_role from private.operator_memberships where profile_id=actor),
      'accessActive',coalesce(private.operator_access_for(actor)->>'mode'='configured',false),'accessRevision',state.revision);
  end if;
  if invitation.recipient_email is distinct from current_email or invitation.status<>'pending' or invitation.expires_at<=clock_timestamp()
    or not private.has_operator_capability(invitation.created_by,'operators.manage',true) then raise insufficient_privilege using message='operator_invitation_unavailable'; end if;
  if exists(select 1 from private.operator_memberships where profile_id=actor) then raise invalid_parameter_value using message='operator_already_manager'; end if;
  if (select count(*) from private.operator_memberships where manager_role<>'owner')>=1000 then raise invalid_parameter_value using message='operator_limit'; end if;
  request:=jsonb_build_object('invitationId',invitation.id);
  if exists(select 1 from public.audit_log where id=p_operation_id) then raise unique_violation using message='operation_conflict'; end if;
  update public.profiles set role=case when role='user' then 'staff'::public.user_role else role end where id=actor;
  insert into private.operator_memberships(profile_id,manager_role,updated_by) values(actor,invitation.manager_role,invitation.created_by);
  insert into public.operator_assignments(profile_id,duty) values(actor,invitation.duty)
    on conflict(profile_id) do update set duty=excluded.duty,revision=operator_assignments.revision+1,updated_at=clock_timestamp();
  update private.operator_invitations set status='accepted',revision=revision+1,accepted_by=actor,accepted_at=clock_timestamp() where id=invitation.id;
  update private.operator_access_state set revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id returning * into state;
  result:=jsonb_build_object('status','accepted','managerRole',invitation.manager_role,'accessActive',true,'accessRevision',state.revision);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'operator.invitation_accepted','operator-invitation:'||invitation.id::text,jsonb_build_object('request',request,'result',result));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.add_cart_selection(p_base_good_id text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); item record; actual_qty integer; next_qty bigint; key_value text; seen text[]:='{}';
begin
  if actor is null then raise insufficient_privilege using message='auth required'; end if;
  perform private.lock_goods_transaction_actor(actor);
  perform private.assert_active_user(actor);
  if nullif(btrim(p_base_good_id),'') is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 51 then
    raise invalid_parameter_value using message='invalid cart selection';
  end if;
  if exists(select 1 from jsonb_array_elements(p_items) line where jsonb_typeof(line)<>'object'
    or not line ?& array['good_id','variant_id','qty','expected_qty']
    or exists(select 1 from jsonb_object_keys(line) key where key not in ('good_id','variant_id','qty','expected_qty','input_revision','input_values'))
    or jsonb_typeof(line->'good_id')<>'string' or jsonb_typeof(line->'variant_id')<>'string'
    or jsonb_typeof(line->'qty')<>'number' or jsonb_typeof(line->'expected_qty')<>'number'
    or line->>'qty' !~ '^[1-9][0-9]*$' or line->>'expected_qty' !~ '^(0|[1-9][0-9]*)$') then
    raise invalid_parameter_value using message='invalid cart selection';
  end if;
  if not exists(select 1 from jsonb_to_recordset(p_items) input(good_id text) where input.good_id=p_base_good_id) then raise invalid_parameter_value using message='invalid cart selection'; end if;
  perform pg_advisory_xact_lock(hashtextextended('cart:'||actor::text,0));
  for item in select good_id,variant_id,qty,expected_qty,coalesce(input_revision,0) input_revision,coalesce(input_values,'{}') input_values
    from jsonb_to_recordset(p_items) input(good_id text,variant_id uuid,qty integer,expected_qty integer,input_revision integer,input_values jsonb)
    order by good_id,variant_id loop
    if nullif(btrim(item.good_id),'') is null or item.variant_id is null or item.qty<1 or item.expected_qty<0 then raise invalid_parameter_value using message='invalid cart selection'; end if;
    key_value:=case when item.input_revision=0 and item.input_values='{}' then '' else md5(item.input_revision::text||':'||item.input_values::text) end;
    if private.cart_variant_key(item.good_id,item.variant_id)::text||':'||key_value=any(seen) then raise invalid_parameter_value using message='invalid cart selection'; end if;
    seen:=array_append(seen,private.cart_variant_key(item.good_id,item.variant_id)::text||':'||key_value);
    if item.good_id<>p_base_good_id and not exists(select 1 from private.goods_additional_links where base_good_id=p_base_good_id and target_good_id=item.good_id) then
      raise check_violation using message='additional_good_unavailable';
    end if;
    -- 19금 본품은 인증 성인만 담는다(ADR-0024). 추가 구성은 계속 일반 굿즈만이다.
    if item.good_id=p_base_good_id then
      if not private.goods_selection_base_available(item.good_id,actor) then
        if exists(select 1 from public.goods good where good.id=item.good_id and good.sale_restriction='adult')
          and not private.adult_verification_valid(actor) then
          raise check_violation using message='adult_verification_required';
        end if;
        raise check_violation using message='additional_good_unavailable';
      end if;
    elsif not private.goods_additional_available(item.good_id) then
      raise check_violation using message='additional_good_unavailable';
    end if;
    select coalesce((select qty from public.cart_items where user_id=actor and good_id=item.good_id and variant_id=private.cart_variant_key(item.good_id,item.variant_id) and input_key=key_value),0) into actual_qty;
    if actual_qty<>item.expected_qty then raise sqlstate 'PT409' using message='cart_selection_changed'; end if;
    next_qty:=actual_qty::bigint+item.qty;
    if next_qty>2147483647 then raise check_violation using message='invalid cart selection'; end if;
    perform private.set_cart_quantity_with_inputs(item.good_id,private.cart_variant_key(item.good_id,item.variant_id),next_qty::integer,item.input_revision,item.input_values);
  end loop;
  return (select coalesce(jsonb_agg(jsonb_build_object('goodId',good_id,'variantId',variant_id,'qty',qty)
    ||case when input_snapshot is null then '{}' else jsonb_build_object('customInputs',input_snapshot) end
    order by created_at,good_id,variant_id,input_key),'[]') from public.cart_items where user_id=actor);
end $function$

CREATE OR REPLACE FUNCTION public.admin_activate_operator_access(p_assignments jsonb, p_expected_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); state private.operator_access_state; ids uuid[]; mapping_ids uuid[];
  item jsonb; target uuid; role_name text; request jsonb; result jsonb; owner_id uuid; assigned_count integer;
begin
  if actor is null then raise insufficient_privilege using message='operator_capability_required'; end if;
  if p_operation_id is null or p_expected_revision is null or p_expected_revision<1 or jsonb_typeof(p_assignments) is distinct from 'array'
    then raise invalid_parameter_value using message='operator_setup_incomplete'; end if;
  if jsonb_array_length(p_assignments)=0 or jsonb_array_length(p_assignments)>10000 then raise invalid_parameter_value using message='operator_setup_incomplete'; end if;
  for item in select value from jsonb_array_elements(p_assignments) loop
    if jsonb_typeof(item) is distinct from 'object' or jsonb_typeof(item->'profileId') is distinct from 'string'
      or item->>'profileId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or not item ? 'managerRole' or (item->'managerRole'<>'null'::jsonb and item->>'managerRole' not in ('owner','primary','deputy','influencer','agency','logistics'))
      or item-array['profileId','managerRole']::text[]<>'{}'::jsonb then raise invalid_parameter_value using message='operator_setup_incomplete'; end if;
  end loop;
  select array_agg((value->>'profileId')::uuid order by (value->>'profileId')::uuid),
    jsonb_build_object('assignments',jsonb_agg(jsonb_build_object('profileId',(value->>'profileId')::uuid,'managerRole',value->'managerRole') order by (value->>'profileId')::uuid),'expectedRevision',p_expected_revision)
    into mapping_ids,request from jsonb_array_elements(p_assignments);
  if cardinality(mapping_ids)<>(select count(distinct value) from unnest(mapping_ids) value) then raise invalid_parameter_value using message='operator_setup_incomplete'; end if;
  select * into strict state from private.operator_access_state where id for update;
  select coalesce(array_agg(id order by id),'{}'::uuid[]) into ids from public.profiles where role in ('staff','admin');
  perform private.lock_operator_subjects(ids||mapping_ids||array[actor]);
  perform private.require_actor_operator_capability(actor,'operators.manage',true);
  result:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.operator.access_activated',request);
  if result is not null then return result; end if;
  if state.configured or state.revision<>p_expected_revision then raise sqlstate 'PT409' using message='operator_access_changed'; end if;
  if not exists(select 1 from public.profiles where id=actor and role='admin' and suspended_at is null)
    then raise insufficient_privilege using message='operator_capability_required'; end if;
  if mapping_ids is distinct from ids or exists(select 1 from private.operator_memberships where not(profile_id=any(ids)))
    then raise invalid_parameter_value using message='operator_setup_incomplete'; end if;
  if (select count(*) from jsonb_array_elements(p_assignments) where value->>'managerRole'='owner')<>1 then raise invalid_parameter_value using message='operator_owner_required'; end if;
  select (value->>'profileId')::uuid into owner_id from jsonb_array_elements(p_assignments) where value->>'managerRole'='owner';
  if not exists(select 1 from public.profiles where id=owner_id and role='admin' and suspended_at is null)
    or exists(select 1 from private.account_action_fences where subject_user_id=owner_id)
    then raise invalid_parameter_value using message='operator_owner_required'; end if;
  if not exists(select 1 from jsonb_array_elements(p_assignments) where (value->>'profileId')::uuid=actor and value->>'managerRole' in ('owner','primary'))
    then raise invalid_parameter_value using message='operator_actor_mapping_required'; end if;
  select count(*) into assigned_count from jsonb_array_elements(p_assignments) where value->>'managerRole' is not null;
  if assigned_count>1001 then raise invalid_parameter_value using message='operator_limit'; end if;
  if exists(select 1 from jsonb_array_elements(p_assignments) a join public.profiles p on p.id=(a.value->>'profileId')::uuid
      where a.value->>'managerRole' is not null and (p.suspended_at is not null or exists(select 1 from private.account_action_fences f where f.subject_user_id=p.id)))
    then raise invalid_parameter_value using message='operator_suspended_target'; end if;
  -- Clear any pre-activation explicit assignments only within the mapped set.
  delete from private.operator_memberships where profile_id=any(ids);
  for item in select value from jsonb_array_elements(p_assignments) loop
    target:=(item->>'profileId')::uuid; role_name:=item->>'managerRole';
    if role_name is null then update public.profiles set role='user' where id=target;
      -- 전환 때 회수되는 운영자의 로그인 세션도 끊는다(OPS-005).
      perform private.operator_revoke_auth_sessions(target);
    else insert into private.operator_memberships(profile_id,manager_role,updated_by) values(target,role_name,actor); end if;
  end loop;
  update private.operator_access_state set configured=true,revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id returning * into state;
  result:=jsonb_build_object('revision',state.revision,'accessRevision',state.revision,'ownerId',owner_id,'assignedCount',assigned_count);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.operator.access_activated','operators',jsonb_build_object('request',request,'result',result));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_activate_shipping_notice_template(target_id uuid, expected_updated_at timestamp with time zone, evidence text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  previous public.shipping_notice_templates;
  saved public.shipping_notice_templates;
  normalized_evidence text := btrim(coalesce(evidence, ''), E' \t\n\r');
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null or not public.has_operator_capability('catalog.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  select * into previous from public.shipping_notice_templates where id = target_id for update;
  if not found then raise no_data_found using message = 'shipping_notice_template_not_found'; end if;
  if previous.status <> 'draft' then raise check_violation using message = 'shipping_notice_template_not_draft'; end if;
  if previous.updated_at is distinct from expected_updated_at then
    raise exception using errcode = 'PT409', message = 'shipping_notice_template_conflict';
  end if;
  if char_length(btrim(previous.shipping_notice, E' \t\n\r')) = 0
    or char_length(btrim(previous.return_exchange_notice, E' \t\n\r')) = 0
    or char_length(btrim(previous.cs_name, E' \t\n\r')) = 0
    or (char_length(btrim(previous.cs_phone, E' \t\n\r')) = 0 and char_length(btrim(previous.cs_email, E' \t\n\r')) = 0)
    or char_length(normalized_evidence) = 0 or char_length(normalized_evidence) > 2000
    or private.has_disallowed_shipping_notice_control(normalized_evidence) then
    raise check_violation using message = 'shipping_notice_template_required';
  end if;
  update public.shipping_notice_templates set
    status = 'active', confirmation_evidence = normalized_evidence,
    confirmed_by = actor, confirmed_at = clock_timestamp(),
    updated_at = greatest(clock_timestamp(), previous.updated_at + interval '1 microsecond')
    where id = target_id returning * into saved;
  insert into public.audit_log(actor_id, action, target, diff)
    values (actor, 'catalog.shipping_notice_template.activated', 'shipping_notice_templates:' || saved.id::text,
      jsonb_build_object('before', to_jsonb(previous), 'after', to_jsonb(saved)));
  return jsonb_build_object('id', saved.id, 'version', saved.version, 'updatedAt', saved.updated_at, 'status', saved.status);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_add_customer_note(target_user_id uuid, target_body text, operation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); normalized_body text:=btrim(target_body); written boolean;
begin
  perform private.lock_operator_subjects(array[(select auth.uid()),target_user_id]);
  perform private.require_operator_capability('platform.manage',false);

 if actor is null or not public.has_operator_capability('platform.manage',false) then raise insufficient_privilege using message='staff_required'; end if;
 if normalized_body is null or char_length(normalized_body) not between 1 and 2000 or normalized_body !~ '[^[:space:]]'
 then raise invalid_parameter_value using message='customer_note_invalid'; end if;
 if operation_id is null then raise invalid_parameter_value using message='customer_note_operation_required'; end if;
 perform 1 from public.profiles where id=target_user_id for key share;
 if not found then raise no_data_found using message='customer_not_found'; end if;
 insert into public.customer_notes(id,customer_id,author_id,body)
 values(operation_id,target_user_id,actor,normalized_body) on conflict(id) do nothing returning true into written;
 if coalesce(written,false) then
  insert into public.audit_log(actor_id,action,target,diff)
  values(actor,'admin.customer.note_added','profile:'||target_user_id,jsonb_build_object('noteId',operation_id));
 elsif not exists(select 1 from public.customer_notes where id=operation_id and customer_id=target_user_id
   and author_id=actor and body=normalized_body) then raise invalid_parameter_value using message='customer_note_operation_conflict';
 end if;
 return coalesce(written,false);
end;
$function$

