CREATE OR REPLACE FUNCTION public.admin_add_shipment_extra_tracking(p_shipment_id uuid, p_carrier text, p_tracking_number text, p_reason text, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; shipment public.order_shipments; carrier_value text := nullif(btrim(coalesce(p_carrier, '')), '');
  tracking_value text := private.normalize_tracking_number(p_tracking_number); reason_value text := nullif(btrim(coalesce(p_reason, '')), '');
  previous private.order_shipment_tracking_changes; added public.order_shipment_extra_trackings;
begin
  actor := private.require_operator_capability('sales.dispatch', false);
  if p_shipment_id is null or p_operation_id is null then raise invalid_parameter_value using message = 'invalid_extra_tracking'; end if;
  if reason_value is null or char_length(reason_value) > 500 then raise check_violation using message = 'extra_tracking_reason_required'; end if;
  if carrier_value is null or tracking_value is null or tracking_value !~ '^[A-Z0-9]{8,30}$' then
    raise check_violation using message = 'invalid_tracking_input'; end if;
  select * into previous from private.order_shipment_tracking_changes where operation_id = p_operation_id;
  if found then
    if previous.action <> 'added' or previous.shipment_id <> p_shipment_id or previous.carrier <> carrier_value
      or previous.tracking_number <> tracking_value or previous.actor_id is distinct from actor then
      raise check_violation using message = 'extra_tracking_operation_conflict'; end if;
    return jsonb_build_object('status', 'unchanged', 'shipmentId', previous.shipment_id, 'orderId', previous.order_id);
  end if;
  perform private.lock_parcel_shipment(p_shipment_id);
  select * into shipment from public.order_shipments where id = p_shipment_id;
  if shipment.status not in ('shipping', 'delivered') or exists(select 1 from public.orders where id = shipment.order_id and status = 'canceled') then
    raise check_violation using message = 'order_not_shipped'; end if;
  if shipment.tracking_number is null then raise check_violation using message = 'tracking_required'; end if;
  if not exists(select 1 from public.shipping_carriers where code = carrier_value and is_active) then
    raise check_violation using message = 'inactive_shipping_carrier'; end if;
  if carrier_value = shipment.carrier and tracking_value = shipment.tracking_number then
    raise check_violation using message = 'extra_tracking_is_representative'; end if;
  if exists(select 1 from public.order_shipment_extra_trackings where shipment_id = shipment.id and carrier = carrier_value and tracking_number = tracking_value) then
    raise check_violation using message = 'extra_tracking_duplicate'; end if;
  if (select count(*) from public.order_shipment_extra_trackings where shipment_id = shipment.id) >= 19 then
    raise check_violation using message = 'extra_tracking_limit'; end if;
  perform private.assert_tracking_registrable(carrier_value, tracking_value, array[shipment.id], null);
  insert into public.order_shipment_extra_trackings(order_id, shipment_id, carrier, tracking_number, source, created_by)
  values (shipment.order_id, shipment.id, carrier_value, tracking_value, 'operator', actor) returning * into added;
  insert into private.order_shipment_tracking_changes(order_id, shipment_id, action, carrier, tracking_number, source, reason, actor_id, operation_id)
  values (shipment.order_id, shipment.id, 'added', carrier_value, tracking_value, 'operator', reason_value, actor, p_operation_id);
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.shipment.extra_tracking_added', 'order:' || shipment.order_id,
    jsonb_build_object('shipmentId', shipment.id, 'originName', shipment.origin_name_snapshot, 'carrier', carrier_value,
      'trackingNumber', tracking_value, 'source', 'operator', 'reason', reason_value, 'operationId', p_operation_id));
  return jsonb_build_object('status', 'added', 'id', added.id, 'shipmentId', shipment.id, 'orderId', shipment.order_id);
end $function$

CREATE OR REPLACE FUNCTION public.admin_adjust_loyalty_grade(p_user_id uuid, p_grade public.loyalty_grade, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  v_current public.loyalty_grade;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  perform private.lock_operator_subjects(array[(select auth.uid()),p_user_id]);
  perform private.require_operator_capability('marketing.manage',false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.has_operator_capability('marketing.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if v_note is null then
    raise check_violation using message = 'note_required';
  end if;

  select profile.loyalty_grade
  into v_current
  from public.profiles as profile
  where profile.id = p_user_id
  for update;

  if not found then
    raise exception 'member_missing' using errcode = 'P0002';
  end if;

  if v_current is distinct from p_grade then
    update public.profiles
    set loyalty_grade = p_grade
    where id = p_user_id;

    insert into public.loyalty_grade_events (
      user_id, previous_grade, next_grade, reason, actor_id, note
    )
    values (p_user_id, v_current, p_grade, 'manual_adjustment', actor_id, v_note);

    -- 수동 승급도 자동 산정과 같은 대우다(US7) — 혜택 쿠폰과 승급 알림을 함께 준다.
    if p_grade > v_current then
      perform private.grant_grade_benefit_coupons(p_user_id, v_current, p_grade);

      insert into public.notifications (
        user_id, type, title, body, link_path, source_type, source_id, dedupe_key
      )
      values (
        p_user_id,
        'loyalty_grade_upgraded',
        '회원 등급이 올랐어요',
        format('%s 등급이 되었어요. 등급 혜택 쿠폰은 쿠폰함에서 확인할 수 있어요.', upper(p_grade::text)),
        '/my/coupons',
        'profile',
        p_user_id::text,
        'loyalty:upgrade:' || p_user_id::text || ':' || p_grade::text
      )
      on conflict (user_id, dedupe_key) do update set
        read_at = null,
        created_at = now();
    end if;
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'loyalty.grade.adjust',
    'profiles:' || p_user_id::text,
    jsonb_build_object('from', v_current, 'to', p_grade, 'note', v_note)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_adjust_stock(target_adjustment_id uuid, target_good_id text, target_variant_id uuid, target_expected_stock_qty integer, target_delta integer, target_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid:=(select auth.uid()); normalized_reason text:=btrim(target_reason,E' \t\n\r\f\v');
  previous_stock integer; next_stock bigint; existing public.audit_log; requested_diff jsonb;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null then raise sqlstate '28000' using message='auth_required'; end if;
  if not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='forbidden'; end if;
  if target_adjustment_id is null then raise null_value_not_allowed using message='invalid_adjustment_id'; end if;
  if target_variant_id is null then raise invalid_parameter_value using message='goods_variant_required'; end if;
  if target_expected_stock_qty is null or target_expected_stock_qty<0 then raise invalid_parameter_value using message='invalid_expected_stock_qty'; end if;
  if target_delta is null or target_delta=0 then raise invalid_parameter_value using message='invalid_stock_delta'; end if;
  if normalized_reason is null or char_length(normalized_reason) not between 1 and 200 then raise invalid_parameter_value using message='invalid_stock_reason'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin_stock_adjustment:'||target_adjustment_id::text,0));
  next_stock:=target_expected_stock_qty::bigint+target_delta::bigint;
  requested_diff:=jsonb_build_object('variantId',target_variant_id,'from',target_expected_stock_qty,'delta',target_delta,'to',next_stock,'reason',normalized_reason);
  select * into existing from public.audit_log where id=target_adjustment_id;
  if found then
    if existing.actor_id=actor and existing.action='admin.good.stock_adjusted'
      and existing.target='goods:'||target_good_id and existing.diff=requested_diff then return (existing.diff->>'to')::integer; end if;
    raise unique_violation using message='adjustment_conflict';
  end if;
  perform 1 from public.goods where id=target_good_id for update;
  if not found then raise no_data_found using message='good_not_found'; end if;
  if exists(select 1 from public.goods where id=target_good_id and archived_at is not null) then raise check_violation using message='catalog_archived'; end if;
  select stock_qty into previous_stock from public.goods_variants where id=target_variant_id and good_id=target_good_id and archived_at is null for update;
  if not found then raise no_data_found using message='goods_variant_not_found'; end if;
  if previous_stock<>target_expected_stock_qty then raise exception using message='stock_changed'; end if;
  next_stock:=private.change_goods_variant_stock(target_good_id,target_variant_id,target_delta::bigint);
  insert into public.audit_log(id,actor_id,action,target,diff)
    values(target_adjustment_id,actor,'admin.good.stock_adjusted','goods:'||target_good_id,requested_diff);
  return next_stock::integer;
end $function$

CREATE OR REPLACE FUNCTION public.admin_adjust_store_credit(p_operation_id uuid, p_user_id uuid, p_amount bigint, p_expires_at timestamp with time zone, p_reason text, p_expected_available bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; policy private.store_credit_policy; operation private.store_credit_operations; payload jsonb; before_balance jsonb; after_balance jsonb; outstanding bigint; take bigint; lot private.store_credit_lots;
begin
  perform private.lock_operator_subjects(array[(select auth.uid()),p_user_id]);
  perform private.require_operator_capability('marketing.manage',true);

  actor:=private.assert_store_credit_admin();
  if p_operation_id is null or p_user_id is null or p_amount is null or p_amount=0 or abs(p_amount::numeric)>999999999999
    or p_expected_available is null or length(btrim(coalesce(p_reason,''))) not between 1 and 1000
    or not exists(select 1 from public.profiles where id=p_user_id) then raise invalid_parameter_value using message='invalid_store_credit_adjustment'; end if;
  payload:=jsonb_build_object('userId',p_user_id,'amount',p_amount,'expiresAt',p_expires_at,'reason',btrim(p_reason),'expectedAvailable',p_expected_available);
  perform pg_advisory_xact_lock(hashtextextended('store_credit_operation:'||p_operation_id::text,0));
  select * into operation from private.store_credit_operations where operation_id=p_operation_id;
  if found then
    if operation.actor_id<>actor or operation.kind<>'adjustment' or operation.payload is distinct from payload then raise exception using errcode='PT409',message='store_credit_operation_conflict'; end if;
    return operation.result;
  end if;
  perform private.assert_active_user(p_user_id);
  if private.is_account_write_fenced(p_user_id) then raise insufficient_privilege using message='account_deletion_in_progress'; end if;
  select * into policy from private.store_credit_policy where singleton for share;
  if not policy.enabled then raise check_violation using message='store_credit_disabled'; end if;
  perform private.expire_store_credit_lots(p_user_id,clock_timestamp());
  before_balance:=private.store_credit_balance(p_user_id);
  if (before_balance->>'available')::bigint<>p_expected_available then raise exception using errcode='PT409',message='store_credit_balance_conflict'; end if;
  if p_amount>0 then
    if p_expires_at is null or p_expires_at<=clock_timestamp() or p_expires_at>clock_timestamp()+make_interval(days=>policy.validity_days)
      then raise check_violation using message='store_credit_expiry_invalid'; end if;
    if p_amount>(before_balance->>'debt')::bigint and (before_balance->>'available')::bigint+(before_balance->>'reserved')::bigint+p_amount-(before_balance->>'debt')::bigint>policy.max_balance
      then raise check_violation using message='store_credit_balance_limit'; end if;
    perform private.issue_store_credit_lot(p_user_id,p_amount,p_expires_at,'admin',null,actor,p_operation_id,btrim(p_reason));
  else
    if p_expires_at is not null then raise invalid_parameter_value using message='store_credit_debit_expiry'; end if;
    outstanding:=-p_amount;
    if (before_balance->>'available')::bigint<outstanding then raise check_violation using message='store_credit_insufficient'; end if;
    for lot in select * from private.store_credit_lots where user_id=p_user_id and available_amount>0 order by expires_at,id for update loop
      take:=least(outstanding,lot.available_amount);
      update private.store_credit_lots set available_amount=available_amount-take,revoked_amount=revoked_amount+take where id=lot.id;
      insert into public.store_credit_ledger(user_id,kind,amount,available_delta,lot_id,actor_id,operation_id,reason)
        values(p_user_id,'adjustment_debit',-take,-take,lot.id,actor,p_operation_id,btrim(p_reason));
      outstanding:=outstanding-take; exit when outstanding=0;
    end loop;
  end if;
  after_balance:=private.store_credit_balance(p_user_id);
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.store_credit.adjusted','store_credit:'||p_user_id::text,
    jsonb_build_object('before',before_balance,'after',after_balance,'request',payload,'operationId',p_operation_id));
  insert into private.store_credit_operations(operation_id,actor_id,kind,payload,result) values(p_operation_id,actor,'adjustment',payload,after_balance);
  return after_balance;
end $function$

CREATE OR REPLACE FUNCTION public.admin_allocate_goods_preorders(p_good_id text, p_order_item_ids uuid[], p_expected_stock jsonb, p_receipt_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); order_key uuid; variant_row record; reservation_row record; expected_qty numeric; allocated_count integer:=0;
  evidence_value text:=nullif(btrim(p_receipt_reference),'');
begin
  perform private.require_operator_capability('sales.manage',false);

  if actor is null or not coalesce(public.has_operator_capability('sales.manage',false),false) then raise insufficient_privilege using message='staff required'; end if;
  if cardinality(p_order_item_ids) is null or cardinality(p_order_item_ids) not between 1 and 100
    or cardinality(p_order_item_ids)<>(select count(distinct id) from unnest(p_order_item_ids) id)
    or jsonb_typeof(p_expected_stock) is distinct from 'object' or evidence_value is null or length(evidence_value)>2000 then
    raise invalid_parameter_value using message='invalid_preorder_allocation';
  end if;
  if (select count(*) from private.goods_preorder_reservations reservation join public.order_items item on item.id=reservation.order_item_id
    where reservation.order_item_id=any(p_order_item_ids) and item.good_id=p_good_id)<>cardinality(p_order_item_ids) then
    raise check_violation using message='preorder_reservation_missing';
  end if;
  -- Existing order-first shipment/cancellation writers and receipt allocation
  -- share this order -> goods -> option -> reservation locking sequence.
  for order_key in select purchase.id from public.orders purchase where exists(select 1 from private.goods_preorder_reservations reservation
    where reservation.order_id=purchase.id and reservation.order_item_id=any(p_order_item_ids)) order by purchase.id for update loop
    if exists(select 1 from private.goods_preorder_reservations reservation where reservation.order_id=order_key
      and reservation.order_item_id=any(p_order_item_ids) and reservation.state='reserved') then
      if not exists(select 1 from public.orders where id=order_key and status in ('paid','confirmed','shipping')) then
        raise check_violation using message='preorder_payment_required';
      end if;
      perform private.assert_order_dispatch_allowed(order_key);
    end if;
  end loop;
  if exists(select 1 from private.goods_preorder_reservations where order_item_id=any(p_order_item_ids) and state not in ('reserved','allocated')) then
    raise check_violation using message='preorder_reservation_released';
  end if;
  perform good.id from public.goods good where exists(select 1 from public.order_items item where item.id=any(p_order_item_ids) and item.good_id=good.id)
    order by good.id for update;
  perform variant.id from public.goods_variants variant where exists(select 1 from public.order_items item where item.id=any(p_order_item_ids) and item.variant_id=variant.id)
    order by variant.id for update;
  perform reservation.order_item_id from private.goods_preorder_reservations reservation where reservation.order_item_id=any(p_order_item_ids)
    order by reservation.order_item_id for update;
  for variant_row in select variant.id,variant.good_id,variant.stock_qty,sum(reservation.qty::bigint)::bigint qty
    from private.goods_preorder_reservations reservation join public.order_items item on item.id=reservation.order_item_id
    join public.goods_variants variant on variant.id=item.variant_id
    where reservation.order_item_id=any(p_order_item_ids) and reservation.state='reserved' group by variant.id order by variant.good_id,variant.id loop
    if jsonb_typeof(p_expected_stock->variant_row.id::text) is distinct from 'number'
      or p_expected_stock->>variant_row.id::text !~ '^(0|[1-9][0-9]*)$' then raise invalid_parameter_value using message='invalid_preorder_allocation'; end if;
    expected_qty:=(p_expected_stock->>variant_row.id::text)::numeric;
    if expected_qty<>variant_row.stock_qty then raise sqlstate 'PT409' using message='preorder_physical_stock_changed'; end if;
    if variant_row.stock_qty<variant_row.qty then raise check_violation using message='preorder_physical_stock_shortfall'; end if;
    perform private.change_goods_variant_stock(variant_row.good_id,variant_row.id,-variant_row.qty);
  end loop;
  for reservation_row in select reservation.*,item.good_id,item.variant_id from private.goods_preorder_reservations reservation
    join public.order_items item on item.id=reservation.order_item_id where reservation.order_item_id=any(p_order_item_ids) and reservation.state='reserved'
    order by reservation.order_item_id loop
    update private.goods_preorder_reservations set state='allocated',allocated_at=clock_timestamp(),allocated_by=actor,allocation_reference=evidence_value
      where order_item_id=reservation_row.order_item_id;
    insert into public.audit_log(actor_id,action,target,diff) values(actor,'order.preorder_stock_allocated','order:'||reservation_row.order_id::text,
      jsonb_build_object('orderItemId',reservation_row.order_item_id,'goodId',reservation_row.good_id,'variantId',reservation_row.variant_id,
        'policyId',reservation_row.policy_id,'qty',reservation_row.qty,'physicalStockDelta',-reservation_row.qty,'receiptReference',evidence_value));
    allocated_count:=allocated_count+1;
  end loop;
  if allocated_count>0 then
    update public.order_shipments shipment set updated_at=clock_timestamp() where exists(select 1 from public.order_shipment_items link
      where link.shipment_id=shipment.id and link.order_item_id=any(p_order_item_ids));
  end if;
  return jsonb_build_object('allocatedItems',allocated_count,'alreadyAllocatedItems',cardinality(p_order_item_ids)-allocated_count);
end $function$

CREATE OR REPLACE FUNCTION public.admin_answer_inquiry(target_inquiry_id uuid, target_body text, target_image_paths text[] DEFAULT '{}'::text[])
 RETURNS TABLE(message_id uuid, recipient_id uuid, recipient_email text, inquiry_reference bigint, inquiry_title text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_body text := btrim(coalesce(target_body, ''));
  v_paths text[];
  v_thread public.inquiries%rowtype;
  v_message_id uuid;
begin
  perform private.require_operator_capability('cs.manage',false);

  if v_actor is null or not public.has_operator_capability('cs.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if char_length(v_body)>2000 or (v_body='' and cardinality(coalesce(target_image_paths,'{}'))=0) then
    raise invalid_parameter_value using message = 'invalid_inquiry_body';
  end if;

  select *
  into v_thread
  from public.inquiries as thread
  where thread.id = target_inquiry_id
  for update;

  if not found then
    raise no_data_found using message = 'inquiry_not_found';
  end if;
  if v_thread.status = 'closed' then
    raise check_violation using message = 'inquiry_closed';
  end if;

  v_paths := private.assert_own_inquiry_image_paths(target_image_paths, v_actor);
  if v_body='' and exists(select 1 from unnest(v_paths) image(path) where not exists(
    select 1 from storage.objects object where object.bucket_id='user-uploads' and object.name=image.path)) then
    raise check_violation using message='inquiry_image_missing';
  end if;

  insert into public.inquiry_messages (inquiry_id, author, author_id, body, image_paths)
  values (target_inquiry_id, 'staff', v_actor, v_body, v_paths)
  returning id into v_message_id;

  update public.inquiries as thread
  set
    status = 'answered',
    handled_by = v_actor,
    answered_at = coalesce(thread.answered_at, now()),
    last_message_at = now()
  where thread.id = target_inquiry_id;

  insert into public.notifications (
    user_id,
    type,
    title,
    body,
    link_path,
    source_type,
    source_id,
    dedupe_key
  )
  values (
    v_thread.user_id,
    'inquiry_answered',
    '문의에 답변이 등록됐어요',
    left('문의 #' || v_thread.reference::text || ' — ' || v_thread.title, 500),
    '/my/inquiries/' || target_inquiry_id::text,
    'inquiry',
    target_inquiry_id::text,
    'inquiry:answered:' || v_message_id::text
  )
  on conflict (user_id, dedupe_key) do nothing;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.inquiry.answered',
    'inquiries:' || target_inquiry_id::text,
    jsonb_build_object(
      'messageId', v_message_id,
      'previousStatus', v_thread.status,
      'attachmentCount', cardinality(v_paths)
    )
  );

  return query
    select
      v_message_id,
      v_thread.user_id,
      profile.email,
      v_thread.reference,
      v_thread.title
    from public.profiles as profile
    where profile.id = v_thread.user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_answer_product_question(target_question_id uuid, target_answer_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_answer text := btrim(coalesce(target_answer_body, ''), E' \t\n\r\f\v');
  v_user_id uuid;
  v_good_id text;
  v_good_name text;
  v_previous text;
begin
  perform private.require_operator_capability('cs.manage',false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.has_operator_capability('cs.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if char_length(normalized_answer) not between 1 and 2000 then
    raise exception 'invalid_question_answer' using errcode = '22023';
  end if;

  select question.user_id, question.good_id, question.answer_body
    into v_user_id, v_good_id, v_previous
  from public.product_questions as question
  where question.id = target_question_id
  for update;

  if not found then
    raise exception 'question_not_found' using errcode = 'P0002';
  end if;

  update public.product_questions
  set answer_body = normalized_answer,
      answered_at = now(),
      answered_by = actor_id
  where id = target_question_id;

  select good.name into v_good_name
  from public.goods as good
  where good.id = v_good_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'product_question.answer',
    'product_questions:' || target_question_id::text,
    jsonb_build_object(
      'goodId', v_good_id,
      'isEdit', v_previous is not null,
      'answerLength', char_length(normalized_answer)
    )
  );

  -- body CHECK 상한은 500자다. 굿즈 이름이 길어 알림 insert가 실패하면 답변
  -- 저장까지 함께 되돌아간다 — 이름을 잘라서라도 답변은 남긴다.
  insert into public.notifications (
    user_id, type, title, body, link_path, source_type, source_id, dedupe_key
  )
  values (
    v_user_id,
    'product_question_answered',
    -- 용어 규율(CONTEXT.md): 공개 상품 Q&A를 1:1 '문의'와 섞어 부르지 않는다.
    '상품 Q&A에 답변이 등록됐어요',
    left(coalesce(v_good_name, '굿즈'), 100) || ' 질문에 ICONS 운영자가 답변을 남겼습니다.',
    '/my/questions',
    'product_question',
    target_question_id::text,
    'product_question_answered:' || target_question_id::text
  )
  on conflict (user_id, dedupe_key) do update set
    title = excluded.title,
    body = excluded.body,
    read_at = null,
    created_at = now();
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_apply_goods_preorder_schedule_change(p_request_id uuid, p_good_id text, p_variant_id uuid, p_expected_ship_date date, p_reason text, p_customer_title text, p_customer_body text, p_preview_fingerprint text, p_excluded_shipments uuid[] DEFAULT '{}'::uuid[], p_sms_requested boolean DEFAULT false, p_policy_mode text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); existing private.goods_preorder_schedule_changes%rowtype; good public.goods;
  excluded uuid[]; digest text; plan jsonb; targets jsonb; target_ids uuid[]; order_ids uuid[]; open_policies jsonb;
  notice uuid:=extensions.gen_random_uuid(); changed_at timestamptz:=clock_timestamp(); sms boolean; order_total integer;
  policy_action text; policy_record jsonb:='[]'::jsonb; policy jsonb; v_reference text;
  g record; v_labels text[]; v_message text; v_date_line text; v_snapshot jsonb; v_buyer uuid; v_email text; v_buyer_name text;
begin
  perform private.require_operator_capability('sales.manage',false);
  if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required'; end if;
  if p_request_id is null or p_preview_fingerprint is null or p_preview_fingerprint !~ '^[0-9a-f]{32}$'
   or p_reason is null or length(btrim(p_reason)) not between 1 and 2000
   or p_customer_title is null or length(btrim(p_customer_title)) not between 1 and 80 or p_customer_title ~ '[[:cntrl:]]'
   or p_customer_body is null or length(btrim(p_customer_body)) not between 1 and 350
   or cardinality(coalesce(p_excluded_shipments,'{}'::uuid[]))>50000 or array_position(coalesce(p_excluded_shipments,'{}'::uuid[]),null) is not null
   or (p_policy_mode is not null and p_policy_mode not in ('replace','acknowledge'))
  then raise invalid_parameter_value using message='invalid_preorder_schedule_change'; end if;
  select coalesce(array_agg(distinct x order by x),'{}'::uuid[]) into excluded from unnest(coalesce(p_excluded_shipments,'{}'::uuid[])) x;
  digest:=md5(jsonb_build_array(p_good_id,p_variant_id,p_expected_ship_date,btrim(p_reason),btrim(p_customer_title),btrim(p_customer_body),
   p_preview_fingerprint,to_jsonb(excluded),coalesce(p_sms_requested,false),p_policy_mode)::text);
  perform pg_advisory_xact_lock(hashtextextended('goods_preorder_schedule_change:'||p_request_id::text,0));
  select * into existing from private.goods_preorder_schedule_changes where id=p_request_id;
  if found then
    if existing.actor_id<>actor or existing.request_digest<>digest then
      raise unique_violation using message='preorder_schedule_idempotency_conflict';
    end if;
    return private.goods_preorder_schedule_change_document(p_request_id);
  end if;
  good:=private.goods_preorder_schedule_scope(p_good_id,p_variant_id,p_expected_ship_date);
  if not coalesce((select enabled from private.order_delay_notice_delivery_control where singleton),false) then
    raise check_violation using message='delay_notice_delivery_disabled';
  end if;
  if p_policy_mode='replace' and not (private.has_operator_capability(actor,'platform.manage',true)
    and private.has_operator_capability(actor,'catalog.manage',false)) then
    raise insufficient_privilege using message='preorder_admin_required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('goods_preorder_schedule_good:'||good.id,0));
  plan:=private.goods_preorder_schedule_plan(good.id,p_variant_id,p_expected_ship_date);
  select array_agg(distinct (value->>'orderId')::uuid),array_agg((value->>'shipmentId')::uuid)
   into order_ids,target_ids from jsonb_array_elements(plan->'targets') value;
  if order_ids is null then raise sqlstate 'PT409' using message='preorder_schedule_stale'; end if;
  perform 1 from public.orders where id=any(order_ids) order by id for update;
  perform 1 from public.profiles where id in (select user_id from public.orders where id=any(order_ids)) order by id for share;
  perform 1 from public.order_shipments where id=any(target_ids) order by id for update;
  perform 1 from public.order_dispatch_delays where order_id=any(order_ids) order by order_id for share;
  if p_policy_mode='replace' then
    perform 1 from public.goods where id=good.id for update;
    perform 1 from public.goods_variants where good_id=good.id order by id for update;
  end if;
  plan:=private.goods_preorder_schedule_plan(good.id,p_variant_id,p_expected_ship_date);
  if plan->>'fingerprint' is distinct from p_preview_fingerprint then raise sqlstate 'PT409' using message='preorder_schedule_stale'; end if;
  if exists(select 1 from unnest(excluded) x where not exists(select 1 from jsonb_array_elements(plan->'targets') value
    where (value->>'shipmentId')::uuid=x)) then raise invalid_parameter_value using message='invalid_preorder_schedule_change'; end if;
  select coalesce(jsonb_agg(value order by value->>'shipmentId'),'[]'::jsonb) into targets from jsonb_array_elements(plan->'targets') value
   where not ((value->>'shipmentId')::uuid=any(excluded));
  if jsonb_array_length(targets)=0 then raise check_violation using message='preorder_schedule_no_targets'; end if;
  if jsonb_array_length(targets)>3000 then raise check_violation using message='preorder_schedule_too_many'; end if;
  select array_agg((value->>'shipmentId')::uuid order by (value->>'shipmentId')::uuid),count(distinct value->>'orderId')
   into target_ids,order_total from jsonb_array_elements(targets) value;
  sms:=coalesce(p_sms_requested,false) and coalesce((select sms_enabled from private.order_delay_notice_delivery_control where singleton),false);

  -- 접수 중 예약 조건: 새 날짜로 교체하거나 그대로 둔다는 확인이 있어야 한다.
  open_policies:=coalesce(plan->'openPolicies','[]'::jsonb);
  if jsonb_array_length(open_policies)>0 then
    if p_policy_mode is null then raise check_violation using message='preorder_schedule_policy_decision_required'; end if;
    policy_action:=case p_policy_mode when 'replace' then 'replaced' else 'acknowledged' end;
    if p_policy_mode='replace' then
      if plan->>'policyBlockReason' is not null then raise check_violation using message='preorder_schedule_policy_not_replaceable'; end if;
      v_reference:=left(coalesce((select approval_reference from private.goods_preorder_policies where id=(open_policies->0->>'policyId')::uuid),'')
        ||E'\n'||'발송 예정일 변경 '||to_char(p_expected_ship_date,'YYYY-MM-DD')||'(예약 주문 일괄 변경): '||btrim(p_reason),2000);
      if good.option_sale_mode='random' then
        perform public.admin_save_random_goods_preorders(good.id,'stopped',null,(select jsonb_agg(jsonb_build_object('variantId',p->>'variantId',
          'policyId',p->>'policyId','expectedRevision',(p->>'revision')::integer)) from jsonb_array_elements(open_policies) p));
        perform public.admin_save_random_goods_preorders(good.id,'active',jsonb_build_object('startsAt',open_policies->0->'startsAt',
          'endsAt',open_policies->0->'endsAt','expectedShipDate',p_expected_ship_date::text,'approvalReference',v_reference),
          (select jsonb_agg(jsonb_build_object('variantId',p->>'variantId','policyId',null,'expectedRevision',null,
            'capacityQty',(p->>'remainingQty')::integer)) from jsonb_array_elements(open_policies) p));
      else
        for policy in select value from jsonb_array_elements(open_policies) loop
          perform public.admin_save_goods_preorder(good.id,(policy->>'variantId')::uuid,(policy->>'policyId')::uuid,
            '{"state":"stopped"}'::jsonb,(policy->>'revision')::integer);
          perform public.admin_save_goods_preorder(good.id,(policy->>'variantId')::uuid,null,jsonb_build_object('state','active',
            'capacityQty',(policy->>'remainingQty')::integer,'startsAt',policy->'startsAt','endsAt',policy->'endsAt',
            'expectedShipDate',p_expected_ship_date::text,'approvalReference',left(coalesce((select approval_reference
              from private.goods_preorder_policies where id=(policy->>'policyId')::uuid),'')||E'\n'||'발송 예정일 변경 '
              ||to_char(p_expected_ship_date,'YYYY-MM-DD')||'(예약 주문 일괄 변경): '||btrim(p_reason),2000)),null);
        end loop;
      end if;
      select coalesce(jsonb_agg(p||jsonb_build_object('newPolicyId',(select v.preorder_policy_id from public.goods_variants v
        where v.id=(p->>'variantId')::uuid),'newExpectedShipDate',p_expected_ship_date)),'[]'::jsonb)
       into policy_record from jsonb_array_elements(open_policies) p;
    else
      policy_record:=open_policies;
    end if;
  end if;

  insert into private.order_delay_notices(id,kind,actor_id,shipment_ids,title,customer_body,expected_ship_date)
   values(notice,'preorder_schedule',actor,target_ids,btrim(p_customer_title),btrim(p_customer_body),p_expected_ship_date);
  insert into private.goods_preorder_schedule_changes(id,good_id,variant_id,to_date,reason,actor_id,notice_id,request_digest,
   preview_fingerprint,excluded_shipment_ids,shipment_count,order_count,sms_queued,policy_action,policies,created_at,condition_excluded_counts)
   values(p_request_id,good.id,p_variant_id,p_expected_ship_date,btrim(p_reason),actor,notice,digest,p_preview_fingerprint,excluded,
    cardinality(target_ids),order_total,sms,policy_action,policy_record,changed_at,coalesce(plan->'excludedCounts','{}'::jsonb));
  -- 배송 건마다 이력: 바꾼 건은 지금 → 새 날짜, 안내만 한 건(개별 변경을 처음 알림)은 같은 날짜로 남겨 다음 일괄에서 다시 알리지 않는다.
  insert into private.order_shipment_promise_changes(shipment_id,from_date,to_date,reason,actor_id,created_at,bulk_change_id)
   select (value->>'shipmentId')::uuid,(value->>'currentDate')::date,(value->>'newDate')::date,btrim(p_reason),actor,changed_at,p_request_id
   from jsonb_array_elements(targets) value;
  update public.order_shipments s set expected_ship_date=(value->>'newDate')::date,updated_at=changed_at
   from jsonb_array_elements(targets) value where s.id=(value->>'shipmentId')::uuid and value->>'newDate'<>value->>'currentDate';
  insert into public.audit_log(actor_id,action,target,diff)
   select actor,'admin.shipment.preorder_promise_changed','order:'||(value->>'orderId'),jsonb_build_object('shipmentId',value->>'shipmentId',
    'originalDate',value->>'originalDate','fromDate',value->>'currentDate','toDate',value->>'newDate','reason',btrim(p_reason),
    'noticeOnly',(value->>'noticeOnly')::boolean,'goodId',good.id,'bulkChangeId',p_request_id,'noticeId',notice,'trigger','goods_preorder_bulk')
   from jsonb_array_elements(targets) value order by value->>'orderId',value->>'shipmentId';

  -- 주문마다 구매자(선물 주문은 받는 분도) 안내 대상을 만든다. 날짜 줄의 이전 날짜는 고객이 마지막으로 안내받은 날짜다.
  for g in select (value->>'orderId')::uuid order_id,array_agg((value->>'shipmentId')::uuid order by (value->>'shipmentId')::uuid) shipment_ids,
    array_agg(distinct (value->>'knownDate')::date) from_dates,array_agg(distinct (value->>'newDate')::date) to_dates
   from jsonb_array_elements(targets) value group by 1 order by 1 loop
   v_snapshot:=private.preorder_schedule_notice_snapshot(g.order_id,g.shipment_ids);
   if v_snapshot is null then raise sqlstate 'PT409' using message='preorder_schedule_stale'; end if;
   select o.user_id,nullif(lower(btrim(p.email)),''),coalesce(nullif(p.nickname,''),'구매자') into v_buyer,v_email,v_buyer_name
    from public.orders o join public.profiles p on p.id=o.user_id where o.id=g.order_id;
   select array_agg(origin_name_snapshot||' · '||coalesce(shipment_number,upper(right(id::text,8))) order by id) into v_labels
    from public.order_shipments where id=any(g.shipment_ids);
   v_date_line:=case when cardinality(g.from_dates)=1 and cardinality(g.to_dates)=1
     then '발송 예정일: '||to_char(g.from_dates[1],'YYYY-MM-DD')||' → '||to_char(g.to_dates[1],'YYYY-MM-DD')
     else '변경된 발송 예정일: '||(select to_char(min(x),'YYYY-MM-DD') from unnest(g.to_dates) x)
      ||case when cardinality(g.to_dates)>1 then ' ~ '||(select to_char(max(x),'YYYY-MM-DD') from unnest(g.to_dates) x) else '' end end;
   v_message:=btrim(p_customer_body)||E'\n\n'||v_date_line||E'\n안내 대상 배송 건: '
    ||(select string_agg(coalesce(s.shipment_number,upper(right(s.id::text,8))),', ' order by s.id) from public.order_shipments s where s.id=any(g.shipment_ids[1:3]))
    ||case when cardinality(g.shipment_ids)>3 then ' 외 '||(cardinality(g.shipment_ids)-3)::text||'건' else '' end;
   insert into private.order_delay_notice_targets(notice_id,order_id,buyer_id,recipient_email,buyer_name,shipment_ids,shipment_labels,snapshot,
    message_body,email_status,error_code)
    values(notice,g.order_id,v_buyer,v_email,v_buyer_name,g.shipment_ids,v_labels,v_snapshot,v_message,
     case when v_email is null or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'suppressed' else 'prepared' end,
     case when v_email is null or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'recipient_missing' else null end);
   insert into private.order_delay_notice_targets(notice_id,order_id,buyer_id,recipient_email,buyer_name,shipment_ids,shipment_labels,snapshot,
    message_body,email_status,error_code,audience)
    select notice,g.order_id,p.id,nullif(lower(btrim(p.email)),''),coalesce(nullif(p.nickname,''),'받는 분'),g.shipment_ids,v_labels,v_snapshot,v_message,
     case when p.email is null or btrim(p.email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'suppressed' else 'prepared' end,
     case when p.email is null or btrim(p.email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'recipient_missing' else null end,'recipient'
    from private.gift_intents gift join public.profiles p on p.id=gift.recipient_id where gift.order_id=g.order_id;
  end loop;

  -- 지연 안내 요청 경로 그대로: 대상 재확인 → 앱 알림 발행 → 이메일 작업 등록 → 감사.
  perform public.admin_request_order_delay_notice(notice);
  if sms then
    insert into private.order_delay_notice_sms_jobs(target_id) select id from private.order_delay_notice_targets where notice_id=notice;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.good.preorder_schedule_changed','goods:'||good.id,
   jsonb_build_object('changeId',p_request_id,'noticeId',notice,'variantId',p_variant_id,'toDate',p_expected_ship_date,
    'shipments',cardinality(target_ids),'noticeOnly',(select count(*) from jsonb_array_elements(targets) value where (value->>'noticeOnly')::boolean),
    'orders',order_total,'excluded',cardinality(excluded),'sms',sms,'policyAction',policy_action,'policies',policy_record));
  return private.goods_preorder_schedule_change_document(p_request_id);
end $function$

CREATE OR REPLACE FUNCTION public.admin_apply_shipping_notice_template(target_good_id text, target_template_id uuid, expected_good_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  template public.shipping_notice_templates;
  previous public.goods;
  saved public.goods;
  snapshot jsonb;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null or not public.has_operator_capability('catalog.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  select * into previous from public.goods where id = target_good_id for update;
  if not found then raise no_data_found using message = 'good_not_found'; end if;
  if expected_good_updated_at is null or previous.updated_at is distinct from expected_good_updated_at then
    raise exception using errcode = 'PT409', message = 'good_shipping_notice_conflict';
  end if;
  if previous.archived_at is not null then raise check_violation using message='good_archived'; end if;
  if target_template_id is not distinct from previous.shipping_notice_template_id then
    return jsonb_build_object('goodId',previous.id,'templateId',previous.shipping_notice_template_id,
      'templateVersion',previous.shipping_notice_template_version,'updatedAt',previous.updated_at);
  end if;
  if target_template_id is null then
    update public.goods set
      shipping_notice_template_id = null,
      shipping_notice_template_version = null,
      shipping_notice_snapshot = null,
      updated_at = greatest(clock_timestamp(), previous.updated_at + interval '1 microsecond')
      where id = target_good_id returning * into saved;
    insert into public.audit_log(actor_id, action, target, diff)
      values (actor, 'catalog.good.shipping_notice_template_cleared', 'goods:' || saved.id,
        jsonb_build_object('before', jsonb_build_object(
          'templateId', previous.shipping_notice_template_id,
          'templateVersion', previous.shipping_notice_template_version,
          'snapshot', previous.shipping_notice_snapshot
        ), 'after', null));
    return jsonb_build_object('goodId', saved.id, 'templateId', null, 'templateVersion', null, 'updatedAt', saved.updated_at);
  end if;
  select * into template from public.shipping_notice_templates where id = target_template_id;
  if not found then raise no_data_found using message = 'shipping_notice_template_not_found'; end if;
  if template.status <> 'active' then raise check_violation using message = 'shipping_notice_template_not_active'; end if;
  snapshot := jsonb_build_object(
    'templateId', template.id,
    'templateVersion', template.version,
    'code', template.code,
    'name', template.name,
    'shippingNotice', template.shipping_notice,
    'returnExchangeNotice', template.return_exchange_notice,
    'remoteAreaNotice', template.remote_area_notice,
    'csName', template.cs_name,
    'csPhone', template.cs_phone,
    'csEmail', template.cs_email
  );
  update public.goods set
    shipping_notice_template_id = template.id,
    shipping_notice_template_version = template.version,
    shipping_notice_snapshot = snapshot,
    updated_at = greatest(clock_timestamp(), previous.updated_at + interval '1 microsecond')
    where id = target_good_id returning * into saved;
  insert into public.audit_log(actor_id, action, target, diff)
    values (actor, 'catalog.good.shipping_notice_template_applied', 'goods:' || saved.id,
      jsonb_build_object('before', jsonb_build_object(
        'templateId', previous.shipping_notice_template_id,
        'templateVersion', previous.shipping_notice_template_version,
        'snapshot', previous.shipping_notice_snapshot
      ), 'after', jsonb_build_object(
        'templateId', saved.shipping_notice_template_id,
        'templateVersion', saved.shipping_notice_template_version,
        'snapshot', saved.shipping_notice_snapshot
      )));
  return jsonb_build_object(
    'goodId', saved.id,
    'templateId', saved.shipping_notice_template_id,
    'templateVersion', saved.shipping_notice_template_version,
    'updatedAt', saved.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_apply_shipping_settings_template_v2(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare context jsonb;payload_hash text;receipt jsonb;template public.shipping_settings_templates;origin public.fulfillment_origins;origin_doc jsonb;
 good public.goods;target text;ids text[];row jsonb;actual jsonb;current_delivery jsonb;blocker text;child_operation uuid;transaction_receipt jsonb;
 previous jsonb;results jsonb:='[]';config private.goods_transaction_configs;
begin
 -- Reject missing authority before parsing caller-controlled operation JSON.
 if (select auth.uid()) is null then raise invalid_authorization_specification using message='auth_required';end if;
 if not public.has_operator_capability('catalog.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';
 end if;
 context:=private.shipping_settings_operation_context(p_request);
 perform private.require_shipping_settings_identity((context->>'expectedActorId')::uuid,(context->>'expectedSessionId')::uuid);
 perform private.validate_shipping_settings_apply(p_request);
 p_request:=jsonb_set(p_request,'{goods}',(select jsonb_agg(value order by value->>'id') from jsonb_array_elements(p_request->'goods')));
 payload_hash:=encode(extensions.digest(p_request::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('shipping-settings-operation:'||(context->>'operationId'),0));
 receipt:=private.shipping_settings_prior(context,payload_hash);if receipt is not null then return receipt;end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 select * into template from public.shipping_settings_templates where id=(context->>'templateId')::uuid for share;
 if not found or not template.enabled then raise check_violation using message='shipping_settings_template_unavailable';end if;
 if template.revision<>(context->>'expectedRevision')::integer then raise sqlstate 'PT409' using message='shipping_settings_template_changed';end if;
 perform private.validate_shipping_settings_extended(template.settings);
 select array_agg(value->>'id' order by value->>'id') into ids from jsonb_array_elements(p_request->'goods');
 -- Claim operation/editor advisory locks before product rows. NOWAIT keeps
 -- cross-workflow contention recoverable instead of reversing lock order.
 foreach target in array ids loop
  if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||target,0)) then raise sqlstate 'PT409' using message='shipping_settings_retry';end if;
  child_operation:=md5('shipping-settings-delivery:'||(context->>'operationId')||':'||target)::uuid;
  if not pg_try_advisory_xact_lock(hashtextextended('goods-transaction-operation:'||child_operation::text,0)) then
   raise sqlstate 'PT409' using message='shipping_settings_retry';end if;
 end loop;
 perform 1 from public.goods where id=any(ids) order by id for update nowait;
 if (select count(*) from public.goods where id=any(ids) and archived_at is null)<>cardinality(ids) then
  raise check_violation using message='shipping_settings_goods_unavailable';end if;
 if exists(select 1 from unnest(ids) id where private.goods_aggregation_owner(id)<>id) then
  raise check_violation using message='goods_aggregation_policy_owned_by_source';end if;
 perform 1 from private.goods_transaction_configs where good_id=any(ids) order by good_id for update nowait;
 if exists(select 1 from private.shipping_charge_group_assignments where owner_good_id=any(ids) and group_id is not null) then raise check_violation using message='shipping_settings_preview_upgrade_required';end if;
 for good in select * from public.goods where id=any(ids) order by id loop
  select value into row from jsonb_array_elements(p_request->'goods') where value->>'id'=good.id;
  actual:=private.shipping_settings_good_guard(good);
  if actual->>'ownerGoodId' is distinct from row->>'ownerGoodId' or actual->'familyGoodIds' is distinct from row->'familyGoodIds'
   or (actual->>'updatedAt')::timestamptz is distinct from (row->>'updatedAt')::timestamptz
   or (actual->>'ownerUpdatedAt')::timestamptz is distinct from (row->>'ownerUpdatedAt')::timestamptz
   or actual->'transactionRevision' is distinct from row->'transactionRevision' or actual->'deliveryVersionId' is distinct from row->'deliveryVersionId' then
   raise sqlstate 'PT409' using message='shipping_settings_goods_changed';end if;
 end loop;
 select * into origin from public.fulfillment_origins where id=(template.settings->>'originId')::uuid for share nowait;
 if not found or not origin.is_active then raise check_violation using message='shipping_settings_origin_unavailable';end if;
 perform 1 from private.shipping_collect_contracts where origin_id=origin.id for share nowait;
 origin_doc:=private.shipping_settings_origin(origin);
 if origin.updated_at is distinct from (p_request->>'originUpdatedAt')::timestamptz
  or origin_doc->'collectRevision' is distinct from p_request->'collectRevision' or origin_doc->'collectVersionId' is distinct from p_request->'collectVersionId' then
  raise sqlstate 'PT409' using message='shipping_settings_origin_changed';end if;
 -- Hold the activation state while creating active delivery versions.
 perform 1 from private.goods_transaction_runtime where singleton for share nowait;
 for good in select * from public.goods where id=any(ids) order by id loop
  current_delivery:=private.shipping_settings_delivery_input(good.id);
