CREATE OR REPLACE FUNCTION public.admin_apply_shipping_settings_template(p_request_id uuid, p_template_id uuid, p_expected_revision integer, p_expected_origin_updated_at timestamp with time zone, p_goods jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); payload jsonb; existing private.shipping_settings_applications;
 template public.shipping_settings_templates; origin public.fulfillment_origins; good public.goods; previous jsonb; item jsonb;
 ids text[]; target_count integer; result jsonb; results jsonb:='[]';
begin
  perform private.require_operator_capability('catalog.manage',false);

 if actor is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='staff_required'; end if;
 if p_request_id is null or p_template_id is null or p_expected_revision is null or p_expected_revision<1 or p_expected_origin_updated_at is null
  or jsonb_typeof(p_goods) is distinct from 'array' then raise invalid_parameter_value using message='invalid_shipping_settings_application'; end if;
 if jsonb_array_length(p_goods) not between 1 and 100 then raise invalid_parameter_value using message='invalid_shipping_settings_targets'; end if;
 for item in select value from jsonb_array_elements(p_goods) loop
  if jsonb_typeof(item) is distinct from 'object' or not(item ?& array['id','updatedAt'])
   or exists(select 1 from jsonb_object_keys(item) k where k not in ('id','updatedAt'))
   or jsonb_typeof(item->'id') is distinct from 'string' or char_length(item->>'id') not between 1 and 120
   or jsonb_typeof(item->'updatedAt') is distinct from 'string' or (item->>'updatedAt')::timestamptz is null
  then raise invalid_parameter_value using message='invalid_shipping_settings_targets'; end if;
 end loop;
 select array_agg(value->>'id' order by value->>'id'),count(distinct value->>'id') into ids,target_count from jsonb_array_elements(p_goods);
 if target_count<>jsonb_array_length(p_goods) then raise invalid_parameter_value using message='invalid_shipping_settings_targets'; end if;
 payload:=jsonb_build_object('templateId',p_template_id,'revision',p_expected_revision,'originUpdatedAt',p_expected_origin_updated_at,
  'goods',(select jsonb_agg(value order by value->>'id') from jsonb_array_elements(p_goods)));
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('shipping_settings_apply:'||p_request_id,0));
 select * into existing from private.shipping_settings_applications where id=p_request_id;
 if found then
  if existing.actor_id<>actor or existing.payload<>payload then raise exception using errcode='PT409',message='shipping_settings_request_conflict'; end if;
  return existing.result;
 end if;
 select * into template from public.shipping_settings_templates where id=p_template_id for share;
 if not found or not template.enabled then raise check_violation using message='shipping_settings_template_unavailable'; end if;
 if template.settings ? 'delivery' then raise check_violation using message='shipping_settings_preview_upgrade_required';end if;
 if template.revision<>p_expected_revision then raise exception using errcode='PT409',message='shipping_settings_template_changed'; end if;
 -- Lock every target before inspecting/applying any copied field. A conflict
 -- aborts the statement so neither a prefix nor its audits can be committed.
 perform g.id from public.goods g where g.id=any(ids) order by g.id for update;
 if exists(select 1 from private.shipping_charge_group_assignments where owner_good_id in(select private.goods_aggregation_owner(id) from unnest(ids) id) and group_id is not null) then raise check_violation using message='shipping_settings_preview_upgrade_required';end if;
 if (select count(*) from public.goods g where g.id=any(ids) and g.archived_at is null)<>target_count then
  raise check_violation using message='shipping_settings_goods_unavailable'; end if;
 if exists(select 1 from jsonb_array_elements(p_goods) x join public.goods g on g.id=x->>'id'
  where g.updated_at is distinct from (x->>'updatedAt')::timestamptz) then
  raise exception using errcode='PT409',message='shipping_settings_goods_changed'; end if;
 select * into origin from public.fulfillment_origins where id=(template.settings->>'originId')::uuid for share;
 if not found or not origin.is_active then raise check_violation using message='shipping_settings_origin_unavailable'; end if;
 if origin.updated_at is distinct from p_expected_origin_updated_at then raise exception using errcode='PT409',message='shipping_settings_origin_changed'; end if;
 for good in select * from public.goods where id=any(ids) order by id loop
  previous:=private.good_shipping_settings(good);
  -- Reuse existing validation and the null/zero contract for claim guidance.
  perform public.admin_save_good_claim_policy(good.id,template.settings->'claimPolicy',good.updated_at);
  update public.goods set origin_id=origin.id,shipping_fee_type=template.settings->>'feeType',
   individual_fee=(template.settings->>'individualFee')::bigint,
   shipping_settings_template_id=template.id,shipping_settings_template_revision=template.revision,
   shipping_settings_snapshot=jsonb_build_object('templateId',template.id,'templateRevision',template.revision,'name',template.name,
    'settings',template.settings,'appliedAt',clock_timestamp(),'originUpdatedAt',origin.updated_at)
  where id=good.id returning * into good;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'catalog.good.shipping_settings_applied','goods:'||good.id,
   jsonb_build_object('requestId',p_request_id,'templateId',template.id,'templateRevision',template.revision,
    'before',previous,'after',private.good_shipping_settings(good),'originUpdatedAt',origin.updated_at));
  results:=results||jsonb_build_array(jsonb_build_object('id',good.id,'updatedAt',good.updated_at));
 end loop;
 result:=jsonb_build_object('requestId',p_request_id,'templateId',template.id,'templateRevision',template.revision,'appliedCount',target_count,'goods',results);
 insert into private.shipping_settings_applications(id,actor_id,payload,result) values(p_request_id,actor,payload,result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_apply_stock_reconcile(p_snapshot_id uuid, p_expected_changes integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;reason text;snap private.stock_reconcile_snapshots;item record;conflicts jsonb:='[]'::jsonb;
  preview_changes integer;changed_ids uuid[];now_difference bigint;target bigint;delta integer;increased integer:=0;decreased integer:=0;
  shortages integer:=0;total_delta bigint:=0;result jsonb;
  matched_ids uuid[];now_target bigint;flow_changed boolean;stock_changed boolean;
  checked_ids uuid[]:='{}';checked_stock integer[]:='{}';checked_pending integer[]:='{}';checked_shipped integer[]:='{}';
  checked_returned integer[]:='{}';checked_awaiting integer[]:='{}';
begin
  actor:=private.require_operator_capability('catalog.manage',false);
  reason:=btrim(coalesce(p_reason,''),E' \t\n\r\f\v');
  if p_snapshot_id is null or p_expected_changes is null or p_expected_changes<0 then
    raise invalid_parameter_value using message='invalid_stock_reconcile_apply';
  end if;
  if char_length(reason) not between 1 and 200 or reason ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message='invalid_stock_reconcile_reason';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('stock_reconcile:'||p_snapshot_id::text,0));
  select * into snap from private.stock_reconcile_snapshots where id=p_snapshot_id for update;
  if not found then raise no_data_found using message='stock_reconcile_not_found';end if;
  if snap.applied_at is not null then
    if snap.applied_by=actor and snap.apply_reason=reason and (snap.apply_result->>'expectedChanges')::integer=p_expected_changes then
      return jsonb_build_object('status','applied','replayed',true,'snapshot',private.stock_reconcile_document(snap.id));
    end if;
    raise sqlstate 'PT409' using message='stock_reconcile_already_applied';
  end if;
  if snap.created_at<clock_timestamp()-interval '24 hours' then
    raise check_violation using message='stock_reconcile_expired';
  end if;
  changed_ids:=array(select i.variant_id from private.stock_reconcile_snapshot_items i where i.snapshot_id=snap.id and i.target_qty<>i.stock_qty);
  preview_changes:=cardinality(changed_ids);
  if preview_changes<>p_expected_changes then raise sqlstate 'PT409' using message='stock_reconcile_preview_mismatch';end if;

  perform 1 from public.goods g where g.id in(select v.good_id from public.goods_variants v where v.id=any(changed_ids)) order by g.id for update;
  perform 1 from public.goods_variants v where v.id=any(changed_ids) order by v.id for update;

  -- 잠금 뒤 미리보기한 옵션 전부를 다시 잰다(QA1 S-T07-01). 운영자가 확인한 숫자 그대로만 재고를 바꾼다.
  --   · 바뀌는 옵션: 맞춘 뒤 재고수량(출고 대기 등 실물 흐름이 바뀌면 달라진다)과 차이(재고수량을 직접 바꾸면 달라진다)가
  --     미리보기와 같아야 한다. 상품 보관·옵션 사용 중지도 거절한다.
  --   · 같은 옵션: 지금도 반영할 것이 없어야 한다(주문으로 재고수량과 맞춘 뒤 값이 함께 움직인 것은 괜찮다).
  -- 하나라도 어긋나면 아무것도 바꾸지 않고 바뀐 옵션을 돌려준다. 통과하면 반영 시점 값을 기록한다(결과 표·감사가 쓴다).
  matched_ids:=array(select s.variant_id from private.stock_reconcile_snapshot_items s where s.snapshot_id=snap.id);
  for item in
    select i.*,v.good_id as current_good_id,v.stock_qty as current_stock,v.archived_at as variant_archived_at,g.archived_at as goods_archived_at,
      g.name as goods_name,v.name as option_name,v.code as option_code,f.pending_qty as now_pending,f.shipped_since_qty as now_shipped,
      f.returned_since_qty as now_returned,f.awaiting_return_qty as now_awaiting
    from private.stock_reconcile_snapshot_items i
    join public.goods_variants v on v.id=i.variant_id
    join public.goods g on g.id=v.good_id
    join private.stock_reconcile_flows(matched_ids,snap.as_of) f on f.variant_id=i.variant_id
    where i.snapshot_id=snap.id
    order by v.good_id,i.variant_id
  loop
    now_difference:=item.file_qty::bigint-(item.current_stock::bigint+item.now_pending+item.now_awaiting+item.now_shipped-item.now_returned);
    now_target:=greatest(item.file_qty::bigint-item.now_pending-item.now_awaiting-item.now_shipped+item.now_returned,0);
    flow_changed:=item.now_pending+item.now_awaiting+item.now_shipped-item.now_returned
      <>item.pending_qty::bigint+item.awaiting_return_qty+item.shipped_since_qty-item.returned_since_qty;
    stock_changed:=now_difference<>item.difference;
    if (item.target_qty<>item.stock_qty and (item.variant_archived_at is not null or item.goods_archived_at is not null))
      or stock_changed
      or (item.target_qty<>item.stock_qty and now_target<>item.target_qty)
      or (item.target_qty=item.stock_qty and now_target<>item.current_stock) then
      conflicts:=conflicts||jsonb_build_object('variantId',item.variant_id,'goodsName',item.goods_name,'optionName',item.option_name,
        'optionCode',item.option_code,'previewStockQty',item.stock_qty,'currentStockQty',item.current_stock,
        'previewPendingQty',item.pending_qty,'currentPendingQty',item.now_pending,'previewTargetQty',item.target_qty,'currentTargetQty',now_target,
        'previewDifference',item.difference,'currentDifference',now_difference,
        'reason',case when item.target_qty<>item.stock_qty and item.goods_archived_at is not null then 'goods_archived'
          when item.target_qty<>item.stock_qty and item.variant_archived_at is not null then 'option_stopped'
          when flow_changed and stock_changed then 'pending_and_stock_changed'
          when stock_changed then 'stock_changed' else 'pending_changed' end);
    end if;
    checked_ids:=array_append(checked_ids,item.variant_id);
    checked_stock:=array_append(checked_stock,item.current_stock);
    checked_pending:=array_append(checked_pending,item.now_pending::integer);
    checked_shipped:=array_append(checked_shipped,item.now_shipped::integer);
    checked_returned:=array_append(checked_returned,item.now_returned::integer);
    checked_awaiting:=array_append(checked_awaiting,item.now_awaiting::integer);
  end loop;
  if jsonb_array_length(conflicts)>0 then
    return jsonb_build_object('status','conflict','conflicts',conflicts);
  end if;
  update private.stock_reconcile_snapshot_items i set stock_before=c.stock_before,applied_pending_qty=c.pending_qty,
    applied_shipped_since_qty=c.shipped_since_qty,applied_returned_since_qty=c.returned_since_qty,applied_awaiting_return_qty=c.awaiting_return_qty
  from unnest(checked_ids,checked_stock,checked_pending,checked_shipped,checked_returned,checked_awaiting)
    as c(variant_id,stock_before,pending_qty,shipped_since_qty,returned_since_qty,awaiting_return_qty)
  where i.snapshot_id=snap.id and i.variant_id=c.variant_id;

  for item in
    select i.*,v.good_id as current_good_id,v.stock_qty as current_stock from private.stock_reconcile_snapshot_items i
    join public.goods_variants v on v.id=i.variant_id
    where i.snapshot_id=snap.id and i.target_qty<>i.stock_qty
    order by v.good_id,i.variant_id
  loop
    -- 잠금 뒤 다시 잰 맞춘 뒤 재고수량이 미리보기와 같음을 위에서 확인했다. 운영자가 확인한 그 값으로 맞춘다.
    target:=item.target_qty;
    delta:=(target-item.current_stock)::integer;
    if delta<>0 then
      perform private.change_goods_variant_stock(item.current_good_id,item.variant_id,delta::bigint);
    end if;
    update private.stock_reconcile_snapshot_items set applied_delta=delta,stock_after=target::integer
      where snapshot_id=snap.id and variant_id=item.variant_id;
    if delta>0 then increased:=increased+1;elsif delta<0 then decreased:=decreased+1;end if;
    if item.current_stock::bigint+item.difference<0 then shortages:=shortages+1;end if;
    total_delta:=total_delta+delta;
    insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.good.stock_reconciled','goods:'||item.current_good_id,
      jsonb_build_object('snapshotId',snap.id,'variantId',item.variant_id,'from',item.current_stock,'delta',delta,'to',target,
        'fileQty',item.file_qty,'pendingQty',item.applied_pending_qty,'shippedSinceQty',item.applied_shipped_since_qty,
        'returnedSinceQty',item.applied_returned_since_qty,'awaitingReturnQty',item.applied_awaiting_return_qty,
        'previewStockQty',item.stock_qty,'previewPendingQty',item.pending_qty,'asOf',snap.as_of,'reason',reason));
  end loop;

  result:=jsonb_build_object('expectedChanges',p_expected_changes,'changed',increased+decreased,'increased',increased,
    'decreased',decreased,'shortages',shortages,'totalDelta',total_delta);
  update private.stock_reconcile_snapshots set applied_at=clock_timestamp(),applied_by=actor,apply_reason=reason,apply_result=result
    where id=snap.id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.stock_reconcile.applied','stock_reconcile:'||snap.id,
    result||jsonb_build_object('originId',snap.origin_id,'asOf',snap.as_of,'sourceLabel',snap.source_label,'reason',reason));
  return jsonb_build_object('status','applied','replayed',false,'snapshot',private.stock_reconcile_document(snap.id));
end $function$

CREATE OR REPLACE FUNCTION public.admin_archive_category(target_operation_id uuid, target_category_id uuid, target_expected_updated_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  category_row public.catalog_categories;
  existing_actor_id uuid;
  existing_action text;
  existing_diff jsonb;
  request_payload jsonb;
  changed boolean;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor_id is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message = 'forbidden'; end if;
  if target_operation_id is null or target_category_id is null or target_expected_updated_at is null then raise invalid_parameter_value using message = 'invalid_category_operation'; end if;
  request_payload := jsonb_build_object('category_id', target_category_id, 'expected_updated_at', target_expected_updated_at);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || target_operation_id::text, 0));
  select audit.actor_id, audit.action, audit.diff into existing_actor_id, existing_action, existing_diff
  from public.audit_log as audit where audit.id = target_operation_id;
  if found then
    if existing_actor_id = actor_id and existing_action = 'admin.catalog.category.archived' and existing_diff -> 'request' = request_payload then
      return coalesce((existing_diff ->> 'changed')::boolean, true);
    end if;
    raise unique_violation using message = 'operation_conflict';
  end if;
  perform private.lock_catalog_category_tree();
  select * into category_row from public.catalog_categories where id = target_category_id for update;
  if not found then raise no_data_found using message = 'category_not_found'; end if;
  if category_row.updated_at is distinct from target_expected_updated_at then raise exception using errcode = 'PT409', message = 'category_changed'; end if;
  if category_row.archived_at is not null then
    changed := false;
  else
    if exists (select 1 from public.catalog_categories where parent_id = target_category_id and archived_at is null) then raise check_violation using message = 'category_has_active_children'; end if;
    update public.catalog_categories set archived_at = pg_catalog.now(), updated_at = pg_catalog.now() where id = target_category_id;
    changed := true;
  end if;
  insert into public.audit_log(id, actor_id, action, target, diff)
  values (target_operation_id, actor_id, 'admin.catalog.category.archived', 'catalog_categories:' || target_category_id::text,
    jsonb_build_object('request', request_payload, 'changed', changed));
  return changed;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_archive_cs_reply_template(p_id uuid, p_archived boolean, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); previous public.cs_reply_templates; saved public.cs_reply_templates;
begin
  perform private.require_operator_capability('cs.manage',false);

 if actor is null or not public.has_operator_capability('cs.manage',false) then raise insufficient_privilege using message='staff_required'; end if;
 if p_id is null or p_archived is null or p_expected_revision is null then raise invalid_parameter_value using message='invalid_cs_reply_template'; end if;
 perform pg_advisory_xact_lock(hashtextextended('cs_reply_template:'||p_id::text,0));
 select * into previous from public.cs_reply_templates where id=p_id for update;
 if not found then raise no_data_found using message='cs_reply_template_not_found'; end if;
 if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='cs_reply_template_changed'; end if;
 if (previous.archived_at is not null)=p_archived then return to_jsonb(previous); end if;
 update public.cs_reply_templates set archived_at=case when p_archived then clock_timestamp() else null end,
   revision=revision+1,updated_by=actor,updated_at=clock_timestamp() where id=p_id returning * into saved;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.cs_reply_template.archived','cs_reply_templates:'||p_id::text,
   jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
 return to_jsonb(saved);
end $function$

CREATE OR REPLACE FUNCTION public.admin_archive_customer_segments(p_entries jsonb, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; entry jsonb; ids uuid[]:='{}'::uuid[]; id_value uuid; previous private.customer_segments; request jsonb; replay jsonb; result jsonb;
begin
 actor:=private.require_operator_capability('marketing.manage',false);
 if p_operation_id is null or p_entries is null or jsonb_typeof(p_entries)<>'array' or jsonb_array_length(p_entries) not between 1 and 100 then
  raise invalid_parameter_value using message='invalid_customer_segment_archive';end if;
 for entry in select value from jsonb_array_elements(p_entries) loop
  if jsonb_typeof(entry)<>'object' or not(entry ?& array['id','revision']) or (select count(*) from jsonb_object_keys(entry))<>2
   or jsonb_typeof(entry->'id')<>'string' or (entry->>'id')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(entry->'revision')<>'number' or (entry->>'revision')!~'^[1-9][0-9]{0,8}$' then
   raise invalid_parameter_value using message='invalid_customer_segment_archive';end if;
  id_value:=(entry->>'id')::uuid;
  if id_value=any(ids) then raise invalid_parameter_value using message='invalid_customer_segment_archive';end if;
  ids:=array_append(ids,id_value);
 end loop;
 select jsonb_agg(value order by value->>'id') into request from jsonb_array_elements(p_entries);
 perform pg_advisory_xact_lock(hashtextextended('customer-segment-operation:'||p_operation_id::text,0));
 replay:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.customer_segments.archived',request);
 if replay is not null then return replay;end if;
 perform pg_advisory_xact_lock(hashtextextended('customer-segment-catalog',0));
 for id_value in select value from unnest(ids) value order by value loop
  select * into previous from private.customer_segments where id=id_value for update;
  if not found or previous.archived_at is not null then raise no_data_found using message='customer_segment_not_found';end if;
  if previous.preset_key is not null then raise insufficient_privilege using message='customer_segment_preset_readonly';end if;
  if previous.revision<>(select (value->>'revision')::integer from jsonb_array_elements(request) where (value->>'id')::uuid=id_value) then
   raise sqlstate 'PT409' using message='customer_segment_changed';end if;
 end loop;
 update private.customer_segments set archived_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id=any(ids);
 delete from private.customer_segment_favorites where segment_id=any(ids);
 result:=jsonb_build_object('archivedCount',cardinality(ids));
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.customer_segments.archived','customer_segments',jsonb_build_object('request',request,'result',result));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_archive_goods_group(p_group_id uuid, p_expected_revision bigint, p_operation_id uuid, p_expected_actor_id uuid, p_expected_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior private.goods_group_operations;current_group private.goods_groups;expected_hash text;before_value jsonb;result jsonb;
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 if p_group_id is null or p_expected_revision is null or p_expected_revision<1 or p_operation_id is null then
  raise invalid_parameter_value using message='invalid_goods_group_operation';end if;
 expected_hash:=encode(extensions.digest(jsonb_build_array('archive',p_group_id,p_expected_revision)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('goods-group-operation:'||p_operation_id::text,0));
 select * into prior from private.goods_group_operations where operation_id=p_operation_id;
 if found then
  if prior.actor_id<>p_expected_actor_id or prior.session_id<>p_expected_session_id or prior.command<>'archive'
   or prior.target_group_id is distinct from p_group_id or prior.expected_revision is distinct from p_expected_revision
   or prior.receipt is null then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  if prior.receipt->>'state'='sealed' then return prior.receipt;end if;
  if prior.request_hash<>expected_hash then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  return prior.receipt;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 select * into current_group from private.goods_groups where id=p_group_id for update;
 if not found or current_group.revision<>p_expected_revision or current_group.archived_at is not null then
  raise sqlstate 'PT409' using message='goods_group_changed';end if;
 before_value:=private.goods_group_snapshot(p_group_id);
 insert into private.goods_group_operations(operation_id,actor_id,session_id,command,target_group_id,expected_revision,request_hash)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,'archive',p_group_id,p_expected_revision,expected_hash);
 delete from private.goods_group_members where group_id=p_group_id;
 update private.goods_groups set revision=revision+1,archived_at=clock_timestamp(),updated_at=clock_timestamp(),updated_by=p_expected_actor_id where id=p_group_id;
 result:=jsonb_build_object('state','completed','operationId',p_operation_id,'group',private.goods_group_snapshot(p_group_id));
 insert into private.goods_group_changes(group_id,operation_id,actor_id,revision,before_value,after_value)
 values(p_group_id,p_operation_id,p_expected_actor_id,current_group.revision+1,before_value,result->'group');
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'catalog.goods_group.archived','goods_group:'||p_group_id::text,
  jsonb_build_object('before',before_value,'after',result->'group','aggregationRelationshipsPreserved',true));
 update private.goods_group_operations set receipt=result,completed_at=clock_timestamp() where operation_id=p_operation_id;
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_archive_review_event(p_id uuid, p_expected_revision integer, p_operation_id uuid, p_archived boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); event private.review_events%rowtype; request jsonb; receipt jsonb;
begin
 perform private.require_actor_operator_capability(actor,'cs.manage',false);
 if p_id is null or p_expected_revision is null or p_operation_id is null or p_archived is null then raise invalid_parameter_value using message='invalid_review_event';end if;
 request:=jsonb_build_object('id',p_id,'revision',p_expected_revision,'archived',p_archived);
 perform pg_advisory_xact_lock(hashtextextended('review-event:operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.review_event.archived',request);if receipt is not null then return receipt;end if;
 select * into event from private.review_events where id=p_id for update;
 if not found or event.revision<>p_expected_revision then raise sqlstate 'PT409' using message='review_event_changed';end if;
 if (clock_timestamp() at time zone 'Asia/Seoul')::date>=event.starts_on or event.announced_at is not null then raise check_violation using message='review_event_terms_locked';end if;
 update private.review_events set archived_at=case when p_archived then coalesce(archived_at,clock_timestamp()) else null end,revision=revision+1,updated_at=clock_timestamp() where id=p_id;
 receipt:=private.review_event_document(p_id);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.review_event.archived','review_event:'||p_id,jsonb_build_object('request',request,'result',receipt));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_assign_good_category(target_operation_id uuid, target_good_id text, target_category_id uuid, target_expected_updated_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare changed boolean; replay boolean;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if auth.uid() is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='forbidden'; end if;
  perform pg_advisory_xact_lock(hashtextextended('admin.catalog.category.operation:'||target_operation_id::text,0));
