CREATE OR REPLACE FUNCTION public.admin_assign_shipping_charge_group(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare context jsonb;request_hash text;receipt jsonb;ids text[];target text;good public.goods;origin public.fulfillment_origins;
 row jsonb;actual jsonb;expected_origin jsonb;results jsonb:='[]';group_row private.shipping_charge_groups;
begin
 -- Reject missing authority before parsing caller-controlled operation JSON.
 if (select auth.uid()) is null then raise invalid_authorization_specification using message='auth_required';end if;
 if not public.has_operator_capability('catalog.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';
 end if;
 context:=private.shipping_charge_group_context(p_request);
 perform private.require_shipping_charge_group_identity((context->>'expectedActorId')::uuid,(context->>'expectedSessionId')::uuid);
 perform private.validate_shipping_charge_group_assignment(p_request);
 p_request:=jsonb_set(jsonb_set(p_request,'{goods}',(select jsonb_agg(value order by value->>'id') from jsonb_array_elements(p_request->'goods'))),
  '{origins}',(select coalesce(jsonb_agg(value order by value->>'id'),'[]') from jsonb_array_elements(p_request->'origins')));
 request_hash:=encode(extensions.digest(p_request::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('shipping-charge-group-operation:'||(context->>'operationId'),0));
 receipt:=private.shipping_charge_group_prior(context,request_hash);if receipt is not null then return receipt;end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 select array_agg(value->>'id' order by value->>'id') into ids from jsonb_array_elements(p_request->'goods');
 foreach target in array ids loop
  if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||target,0)) then raise sqlstate 'PT409' using message='shipping_charge_group_retry';end if;
 end loop;
 perform 1 from public.goods where id=any(ids) order by id for update nowait;
 if (select count(*) from public.goods where id=any(ids) and archived_at is null)<>cardinality(ids) then
  raise no_data_found using message='shipping_charge_group_goods_unavailable';end if;
 perform 1 from private.goods_transaction_configs where good_id=any(ids) order by good_id for share nowait;
 perform 1 from public.fulfillment_origins where id in(select (value->>'id')::uuid from jsonb_array_elements(p_request->'origins')) order by id for share nowait;
 for expected_origin in select value from jsonb_array_elements(p_request->'origins') loop
  if private.shipping_charge_group_origin((expected_origin->>'id')::uuid) is distinct from expected_origin then
   raise sqlstate 'PT409' using message='shipping_charge_group_origin_changed';end if;
 end loop;
 select * into group_row from private.shipping_charge_groups where id=(context->>'groupId')::uuid for share nowait;
 if context->>'groupId' is not null and (not found or group_row.revision<>(context->>'expectedRevision')::integer) then
  raise sqlstate 'PT409' using message='shipping_charge_group_changed';end if;
 perform 1 from private.shipping_charge_group_assignments where owner_good_id=any(ids) order by owner_good_id for update nowait;
 for good in select * from public.goods where id=any(ids) order by id loop
  select value into row from jsonb_array_elements(p_request->'goods') where value->>'id'=good.id;
  actual:=private.shipping_charge_group_good_guard(good);
  -- Compare timestamps as instants; preserve their microseconds in the DTO.
  if (actual-array['updatedAt','ownerUpdatedAt']) is distinct from (row-array['updatedAt','ownerUpdatedAt'])
   or (actual->>'updatedAt')::timestamptz is distinct from (row->>'updatedAt')::timestamptz
   or (actual->>'ownerUpdatedAt')::timestamptz is distinct from (row->>'ownerUpdatedAt')::timestamptz then
   raise sqlstate 'PT409' using message='shipping_charge_group_goods_changed';end if;
 end loop;
 for good in select * from public.goods where id=any(ids) order by id loop
  select value into row from jsonb_array_elements(p_request->'goods') where value->>'id'=good.id;
  select * into origin from public.fulfillment_origins where id=good.origin_id;
  actual:=private.apply_shipping_charge_group_assignment_locked(good.id,(context->>'groupId')::uuid,(context->>'expectedRevision')::integer,
   (row->>'assignmentRevision')::integer,(row->>'assignmentVersionId')::uuid,
   array(select jsonb_array_elements_text(row->'familyGoodIds')),good.updated_at,origin.updated_at,
   (context->>'operationId')::uuid,(context->>'expectedActorId')::uuid,(context->>'expectedSessionId')::uuid);
  results:=results||jsonb_build_array(actual);
 end loop;
 receipt:=private.shipping_charge_group_receipt(context,'assigned',private.shipping_charge_group_document((context->>'groupId')::uuid),null,results);
 insert into public.audit_log(id,actor_id,action,target,diff) values((context->>'operationId')::uuid,(context->>'expectedActorId')::uuid,
  'catalog.shipping_charge_group.assigned','shipping_charge_groups:'||coalesce(context->>'groupId','clear'),
  jsonb_build_object('context',context,'before',p_request->'goods','after',results));
 perform private.record_shipping_charge_group_operation(context,request_hash,receipt);return receipt;
exception when lock_not_available then raise sqlstate 'PT409' using message='shipping_charge_group_retry';
end $function$

CREATE OR REPLACE FUNCTION public.admin_bank_transfer_refund_context(p_order_id uuid, p_claim_id uuid, p_expected_actor_id uuid, p_expected_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare purchase public.orders;claim public.order_cancellation_requests;payment public.payments;refund public.refunds;
 lifecycle private.bank_transfer_claim_refunds;account private.claim_refund_accounts;
begin
 perform private.require_bank_transfer_refund_identity(p_expected_actor_id,p_expected_session_id);
 select * into purchase from public.orders where id=p_order_id;
 select * into claim from public.order_cancellation_requests where id=p_claim_id and order_id=purchase.id;
 if purchase.id is null or claim.id is null then raise sqlstate 'PT404' using message='claim_not_found';end if;
 select * into payment from public.payments where purpose='order' and ref_id=p_order_id order by id limit 1;
 select * into refund from public.refunds where payment_id=payment.id and cancellation_request_id=claim.id;
 select * into lifecycle from private.bank_transfer_claim_refunds where claim_id=claim.id;
 select * into account from private.claim_refund_accounts where claim_id=claim.id;
 return jsonb_build_object('actorId',p_expected_actor_id,'orderId',purchase.id,'claimId',claim.id,'claimType',claim.claim_type,
  'revision',claim.claim_revision,'amount',purchase.total,'stage',claim.stage,
  'phase',coalesce(lifecycle.state,case when private.bank_transfer_refund_legacy_completed_claim(purchase.id,claim.id) then 'completed' else 'not_confirmed' end),'filedAt',refund.filed_at,
  'confirmedAt',lifecycle.confirmed_at,'transferredAt',lifecycle.transferred_at,
  'confirmationNotBefore',greatest(payment.created_at,claim.requested_at),
  'transferNotBefore',greatest(payment.created_at,refund.filed_at,lifecycle.confirmed_at),
  'maskedAccount',account.masked_account,'maskedHolder',account.masked_holder,
  'confirmBlocker',private.bank_transfer_refund_blocker(claim,purchase,'confirm_cancellation'),
  'fileBlocker',private.bank_transfer_refund_blocker(claim,purchase,'file_transfer'),
  'completeBlocker',private.bank_transfer_refund_blocker(claim,purchase,'complete_transfer'),
  'viewBlocker',private.bank_transfer_refund_blocker(claim,purchase,'view_account'),
  'gift',exists(select 1 from private.gift_intents where order_id=purchase.id))||private.claim_refund_deduction_field(claim.id)
  ||case when coalesce(private.payment_partial_refunded_amount(payment.id),0)>0 then jsonb_build_object('partialRefund',jsonb_build_object(
    'refundedAmount',private.payment_partial_refunded_amount(payment.id),
    'refundAmount',greatest(payment.amount-private.claim_refund_active_deduction(payment.id),0))) else '{}'::jsonb end;
end $function$

CREATE OR REPLACE FUNCTION public.admin_begin_order_cancellation_reconcile(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_order_id uuid;
  v_request_status text;
begin
  perform private.require_operator_capability('sales.manage',false);

  if v_actor is null or not public.has_operator_capability('sales.manage',false) then
    raise insufficient_privilege using message = 'staff required';
  end if;

  select request.order_id
  into v_order_id
  from public.order_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'cancellation_request_not_found';
  end if;

  perform orders.id
  from public.orders
  where orders.id = v_order_id
  for update;

  select request.status
  into v_request_status
  from public.order_cancellation_requests as request
  where request.id = p_request_id
  for update;

  perform public.assert_order_cancellation_reconciliation_allowed(p_request_id,v_actor);

  if v_request_status = 'processing' then
    return;
  end if;

  if v_request_status <> 'needs_review' then
    raise exception using message = 'cancellation_request_not_reconcilable';
  end if;

  if not exists (
    select 1
    from public.order_cancellation_claims as claim
    where claim.order_id = v_order_id
  ) then
    raise exception using message = 'cancellation_claim_missing';
  end if;

  update public.refunds
  set status = 'requested'
  where cancellation_request_id = p_request_id
    and status = 'failed';

  update public.order_cancellation_requests
  set
    status = 'processing',
    decided_by = coalesce(decided_by, v_actor),
    decided_at = coalesce(decided_at, now()),
    provider_started_at = coalesce(provider_started_at, now()),
    updated_at = now()
  where id = p_request_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.cancellation_reconcile_started',
    'order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'from', 'needs_review',
      'to', 'processing'
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_begin_payment_reconciliation(p_attempt_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; attempt public.payment_attempts; prior_row public.audit_log; case_ref text;
begin
  actor := private.require_operator_capability('sales.manage', false);
  if p_attempt_id is null or p_operation_id is null then
    raise invalid_parameter_value using message = 'invalid_payment_reconciliation';
  end if;
  case_ref := 'admin-' || replace(p_operation_id::text, '-', '');
  select * into prior_row from public.audit_log where id = p_operation_id;
  if found then
    if prior_row.action is distinct from 'admin.payment_attempt.reconcile_requested' or prior_row.actor_id is distinct from actor
      or prior_row.target is distinct from 'payment_attempt:' || p_attempt_id::text then
      raise unique_violation using message = 'payment_reconciliation_operation_conflict';
    end if;
  else
    select * into attempt from public.payment_attempts where id = p_attempt_id;
    if not found then raise no_data_found using message = 'payment_attempt_not_found'; end if;
    if not private.payment_attempt_unresolved(attempt.state, attempt.claim_expires_at, clock_timestamp()) then
      raise object_not_in_prerequisite_state using message = 'payment_attempt_not_unresolved';
    end if;
    if exists(select 1 from private.goods_payment_reconciliation_audits g where g.target_id = p_attempt_id and g.requested_at > clock_timestamp() - interval '1 minute')
      or exists(select 1 from private.ticket_payment_reconciliation_audits t where t.target_id = p_attempt_id and t.requested_at > clock_timestamp() - interval '1 minute') then
      raise object_not_in_prerequisite_state using message = 'payment_reconciliation_cooldown';
    end if;
    insert into public.audit_log(id, actor_id, action, target, diff)
    values (p_operation_id, actor, 'admin.payment_attempt.reconcile_requested', 'payment_attempt:' || attempt.id::text,
      jsonb_build_object('purpose', attempt.purpose, 'provider', attempt.provider, 'stateBefore', attempt.state,
        'refId', attempt.ref_id, 'caseRef', case_ref));
  end if;
  select * into attempt from public.payment_attempts where id = p_attempt_id;
  if not found then raise no_data_found using message = 'payment_attempt_not_found'; end if;
  return jsonb_build_object('attemptId', attempt.id, 'purpose', attempt.purpose, 'provider', attempt.provider,
    'state', attempt.state, 'refId', attempt.ref_id, 'caseRef', case_ref);
end $function$

CREATE OR REPLACE FUNCTION public.admin_benefit_issuances(p_from timestamp with time zone, p_to timestamp with time zone, p_query text DEFAULT ''::text, p_discount text DEFAULT 'all'::text, p_segment text DEFAULT 'all'::text, p_code text DEFAULT ''::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  result jsonb;
  needle text := btrim(coalesce(p_query,''));
  pattern text;
begin
  if (select auth.uid()) is null or not public.has_operator_capability('marketing.manage',false) then
    raise insufficient_privilege using message='operator_capability_required';
  end if;
  if p_from is null or p_to is null or not isfinite(p_from) or not isfinite(p_to)
    or p_to<=p_from or p_to-p_from>interval '366 days' or length(needle)>100
    or p_discount is null or p_discount not in ('all','fixed','percent')
    or p_segment is null or p_segment not in ('all','first_purchase','repeat_purchase','targeted')
    or p_code is null or btrim(p_code)='' or length(p_code)>24
    or p_limit is null or p_limit not between 1 and 10001
    or p_offset is null or p_offset<0 then
    raise invalid_parameter_value using message='invalid_benefit_issuances';
  end if;
  pattern := '%'||replace(replace(replace(needle,E'\\',E'\\\\'),'%',E'\\%'),'_',E'\\_')||'%';

  -- One statement snapshot for rows, unpaged counts and the response timestamp.
  -- A JSON response avoids the Data API's default table-row response limit.
  with definitions as materialized (
    select c.code from public.coupons c
    where c.code=p_code
      and (needle='' or c.code ilike pattern escape E'\\' or c.name ilike pattern escape E'\\')
      and (p_discount='all' or c.discount_type=p_discount)
      and (p_segment='all' or (p_segment='targeted' and c.issuance_mode='targeted') or (p_segment<>'targeted' and c.recipient_segment=p_segment))
  ), issued as materialized (
    select u.id,u.coupon_code,u.issued_at,
      exists(select 1 from public.coupon_redemptions r join public.orders o on o.id=r.order_id
        where r.user_coupon_id=u.id and r.status='applied' and o.status=any(private.revenue_order_statuses())) as is_paid_use
    from public.user_coupons u join definitions d on d.code=u.coupon_code
    where u.issued_at>=p_from and u.issued_at<p_to
  ), totals as (
    select count(*) as total_count,count(*) filter (where is_paid_use) as paid_use_count from issued
  )
  select jsonb_build_object(
    'rows',coalesce((select jsonb_agg(jsonb_build_object(
      'id',page.id,'couponCode',page.coupon_code,'issuedAt',page.issued_at,'isPaidUse',page.is_paid_use
    ) order by page.issued_at desc,page.id)
      from (select * from issued order by issued_at desc,id limit p_limit offset p_offset) page),'[]'::jsonb),
    'totalCount',totals.total_count,
    'paidUseCount',totals.paid_use_count,
    'asOf',statement_timestamp()
  ) into result from totals;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_bulk_create_categories(p_operation_id uuid, p_paths jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  request jsonb;
  receipt jsonb;
  entry record;
  segments text[];
  segment text;
  path_keys text[];
  parent uuid;
  matched uuid[];
  new_id uuid;
  base_code text;
  new_code text;
  suffix integer;
  line_ids uuid[];
  created_ids uuid[] := array[]::uuid[];
  lines jsonb[] := array[]::jsonb[];
  reason text;
  created_lines integer := 0;
  skipped_lines integer := 0;
  failed_lines integer := 0;
begin
  perform private.require_operator_capability('catalog.manage', false);
  if actor is null or not public.has_operator_capability('catalog.manage', false) then
    raise insufficient_privilege using message = 'forbidden';
  end if;
  if p_operation_id is null or p_paths is null or pg_catalog.jsonb_typeof(p_paths) <> 'array'
     or pg_catalog.jsonb_array_length(p_paths) not between 1 and 1000
     or exists (
       select 1 from pg_catalog.jsonb_array_elements(p_paths) as item(value)
       where pg_catalog.jsonb_typeof(item.value) <> 'string' or pg_catalog.char_length(item.value #>> '{}') > 1000
     ) then
    raise invalid_parameter_value using message = 'invalid_category_paths';
  end if;

  request := pg_catalog.jsonb_build_object('paths', p_paths);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || p_operation_id::text, 0));
  receipt := private.operator_lifecycle_replay(actor, p_operation_id, 'admin.catalog.category.bulk_created', request);
  if receipt is not null then return receipt; end if;
  perform private.lock_catalog_category_tree();

  for entry in
    select item.value #>> '{}' as raw, item.ordinality::integer as line
    from pg_catalog.jsonb_array_elements(p_paths) with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    segments := private.catalog_category_path_segments(entry.raw);
    reason := null;
    line_ids := array[]::uuid[];
    if segments is null then
      reason := 'invalid_category_path';
    elsif pg_catalog.cardinality(segments) > 4 then
      reason := 'category_depth_exceeded';
    elsif exists (select 1 from pg_catalog.unnest(segments) as name where pg_catalog.char_length(name) > 120) then
      reason := 'invalid_category_name';
    end if;

    if reason is null then
      begin
        parent := null;
        path_keys := array[]::text[];
        foreach segment in array segments loop
          path_keys := pg_catalog.array_append(path_keys, private.catalog_category_name_key(segment));
          select pg_catalog.array_agg(category.id) into matched
          from public.catalog_categories as category
          where category.archived_at is null
            and case when parent is null then category.parent_id is null else category.parent_id = parent end
            and private.catalog_category_name_key(category.name) = private.catalog_category_name_key(segment);
          if pg_catalog.cardinality(matched) > 1 then
            raise check_violation using message = 'category_path_ambiguous';
          end if;
          if matched is not null then
            parent := matched[1];
            continue;
          end if;
          new_id := extensions.gen_random_uuid();
          base_code := 'c-' || pg_catalog.left(pg_catalog.md5(pg_catalog.array_to_string(path_keys, '>')), 10);
          new_code := base_code;
          suffix := 1;
          while exists (select 1 from public.catalog_categories as category where category.code = new_code) loop
            suffix := suffix + 1;
            new_code := base_code || '-' || suffix::text;
          end loop;
          insert into public.catalog_categories (id, code, name, parent_id, depth, sort_order)
          values (
            new_id, new_code, segment, parent, pg_catalog.cardinality(path_keys),
            coalesce((
              select pg_catalog.max(sibling.sort_order) + 1 from public.catalog_categories as sibling
              where case when parent is null then sibling.parent_id is null else sibling.parent_id = parent end
            ), 0)
          );
          line_ids := pg_catalog.array_append(line_ids, new_id);
          parent := new_id;
        end loop;
      exception when check_violation or foreign_key_violation or unique_violation or invalid_parameter_value then
        get stacked diagnostics reason = message_text;
        line_ids := array[]::uuid[];
      end;
    end if;

    if reason is not null then
      failed_lines := failed_lines + 1;
      lines := pg_catalog.array_append(lines, pg_catalog.jsonb_build_object(
        'line', entry.line, 'path', pg_catalog.left(entry.raw, 300), 'status', 'failed', 'created', 0, 'reason', reason));
    elsif pg_catalog.cardinality(line_ids) > 0 then
      created_lines := created_lines + 1;
      created_ids := created_ids || line_ids;
      lines := pg_catalog.array_append(lines, pg_catalog.jsonb_build_object(
        'line', entry.line, 'path', pg_catalog.array_to_string(segments, '>'), 'status', 'created',
        'created', pg_catalog.cardinality(line_ids), 'reason', null));
    else
      skipped_lines := skipped_lines + 1;
      lines := pg_catalog.array_append(lines, pg_catalog.jsonb_build_object(
        'line', entry.line, 'path', pg_catalog.array_to_string(segments, '>'), 'status', 'skipped', 'created', 0, 'reason', null));
    end if;
  end loop;

  receipt := pg_catalog.jsonb_build_object(
    'createdCategories', pg_catalog.cardinality(created_ids),
    'createdLines', created_lines,
    'skippedLines', skipped_lines,
    'failedLines', failed_lines,
    'lines', pg_catalog.to_jsonb(lines));
  insert into public.audit_log (id, actor_id, action, target, diff)
  values (p_operation_id, actor, 'admin.catalog.category.bulk_created', 'catalog_categories',
    pg_catalog.jsonb_build_object('request', request, 'result', receipt, 'created_ids', pg_catalog.to_jsonb(created_ids)));
  return receipt;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_cancel_operator_invitation(p_invitation_id uuid, p_expected_revision integer, p_expected_access_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); state private.operator_access_state; invitation private.operator_invitations; request jsonb; result jsonb;
begin
  if actor is null then raise insufficient_privilege using message='operator_capability_required'; end if;
  if p_invitation_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<1 or p_expected_access_revision is null or p_expected_access_revision<1 then raise invalid_parameter_value using message='invalid_operator_invitation'; end if;
  select * into strict state from private.operator_access_state where id for update;
  perform private.require_actor_operator_capability(actor,'operators.manage',true);
  request:=jsonb_build_object('invitationId',p_invitation_id,'expectedRevision',p_expected_revision,'expectedAccessRevision',p_expected_access_revision);
  result:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.operator.invitation_cancelled',request);
  if result is not null then return result; end if;
  if state.revision<>p_expected_access_revision then raise sqlstate 'PT409' using message='operator_access_changed'; end if;
  select * into invitation from private.operator_invitations where id=p_invitation_id for update;
  if not found or invitation.revision<>p_expected_revision then raise sqlstate 'PT409' using message='operator_invitation_changed'; end if;
  if invitation.status<>'pending' then raise invalid_parameter_value using message='operator_invitation_not_pending'; end if;
  update private.operator_invitations set status='cancelled',revision=revision+1,cancelled_at=clock_timestamp(),cancelled_by=actor,cancellation_reason='operator_cancelled' where id=p_invitation_id;
  update private.operator_access_state set revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id returning * into state;
  result:=jsonb_build_object('revision',invitation.revision+1,'accessRevision',state.revision);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.operator.invitation_cancelled','operator-invitation:'||p_invitation_id::text,jsonb_build_object('request',request,'result',result));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_cancel_unpaid_bank_transfer_order(p_order_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_reason text := btrim(coalesce(p_reason, ''));
  v_order public.orders%rowtype;
  v_attempt public.payment_attempts%rowtype;
begin
  perform private.require_operator_capability('sales.manage',false);

  if v_actor is null or not public.has_operator_capability('sales.manage',false) then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if char_length(v_reason) not between 5 and 200 then
    raise check_violation using message = 'invalid cancellation reason';
  end if;

  select orders.* into v_order
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise no_data_found using message = 'order_not_found';
  end if;

  if v_order.payment_method is distinct from 'bank_transfer' then
    raise check_violation using message = 'order_not_bank_transfer';
  end if;

  if v_order.status is distinct from 'pending' then
    raise object_not_in_prerequisite_state using message = 'order_not_unpaid';
  end if;

  select attempt.* into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'order'
    and attempt.ref_id = v_order.id
    and attempt.provider = 'bank_transfer'
  for update;

  if found then
    if v_attempt.state not in ('prepared', 'needs_review', 'unknown') then
      raise object_not_in_prerequisite_state using message = 'bank_transfer_attempt_not_cancelable';
    end if;

    if exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'order'
        and payment.ref_id = v_order.id
        and payment.status in ('pending', 'paid')
    ) then
      raise object_not_in_prerequisite_state using message = 'bank_transfer_payment_exists';
    end if;

    update public.payment_attempts
    set state = 'canceled',
        claim_token = null,
        claim_expires_at = null
    where id = v_attempt.id;
  end if;

  perform public.cancel_order(v_order.id, v_reason);

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.bank_transfer_canceled',
    'order:' || v_order.id::text,
    jsonb_build_object(
      'reason', v_reason,
      'amount', v_order.total,
      'attemptState', v_attempt.state
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_change_marketing_campaign(p_id uuid, p_expected_revision integer, p_operation_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; campaign private.marketing_campaigns; request jsonb; replay jsonb; result jsonb; affected integer; new_revision integer;
begin
 actor:=private.require_operator_capability('marketing.manage',false);
 if p_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<1 or p_action is null or p_action not in ('cancel','archive') then raise invalid_parameter_value using message='invalid_marketing_action';end if;
 request:=jsonb_build_object('id',p_id,'revision',p_expected_revision,'action',p_action);
 perform pg_advisory_xact_lock(hashtextextended('marketing-operation:'||p_operation_id::text,0));
 replay:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.marketing.'||p_action,request);if replay is not null then return replay;end if;
 select * into campaign from private.marketing_campaigns where id=p_id for update;
 if not found or campaign.revision<>p_expected_revision or campaign.archived_at is not null then raise sqlstate 'PT409' using message='marketing_campaign_changed';end if;
 if p_action='cancel' then
  update private.marketing_runs set state='canceled',completed_at=clock_timestamp() where campaign_id=p_id and state='queued';get diagnostics affected=row_count;
  if affected=0 then raise check_violation using message='marketing_nothing_to_cancel';end if;
 else
  if exists(select 1 from private.marketing_runs where campaign_id=p_id and state in ('queued','processing')) then raise check_violation using message='marketing_campaign_active';end if;
  update private.marketing_campaigns set archived_at=clock_timestamp() where id=p_id;affected:=1;
 end if;
 update private.marketing_campaigns set revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id=p_id returning revision into new_revision;
 result:=jsonb_build_object('id',p_id,'revision',new_revision,'affectedCount',affected);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.marketing.'||p_action,'marketing_campaign:'||p_id,jsonb_build_object('request',request,'result',result));return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_change_operator_role(p_profile_id uuid, p_manager_role text, p_expected_revision integer, p_expected_access_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); state private.operator_access_state; previous private.operator_memberships; actor_role text; request jsonb; result jsonb; next_revision integer;
begin
  if actor is null then raise insufficient_privilege using message='operator_capability_required'; end if;
  if p_profile_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<1 or p_expected_access_revision is null or p_expected_access_revision<1
    or (p_manager_role is not null and p_manager_role not in ('primary','deputy','influencer','agency','logistics'))
    then raise invalid_parameter_value using message='invalid_operator_role'; end if;
  select * into strict state from private.operator_access_state where id for update;
  perform private.lock_operator_subjects(array[actor,p_profile_id]);
  perform private.require_actor_operator_capability(actor,'operators.manage',true);
  request:=jsonb_build_object('profileId',p_profile_id,'managerRole',p_manager_role,'expectedRevision',p_expected_revision,'expectedAccessRevision',p_expected_access_revision);
  result:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.operator.role_changed',request);
  if result is not null then return result; end if;
  if not state.configured then raise invalid_parameter_value using message='operator_setup_required'; end if;
  if state.revision<>p_expected_access_revision then raise sqlstate 'PT409' using message='operator_access_changed'; end if;
  if p_profile_id=actor then raise insufficient_privilege using message='operator_self_change_denied'; end if;
  select * into previous from private.operator_memberships where profile_id=p_profile_id for update;
  if not found or previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='operator_membership_changed'; end if;
  if previous.manager_role='owner' then raise insufficient_privilege using message='operator_owner_change_denied'; end if;
  select manager_role into actor_role from private.operator_memberships where profile_id=actor;
  if actor_role='primary' and previous.manager_role='primary' and p_manager_role is null then raise insufficient_privilege using message='operator_primary_revoke_denied'; end if;
  if p_manager_role is not null and (not exists(select 1 from public.profiles where id=p_profile_id and role in ('staff','admin') and suspended_at is null)
    or exists(select 1 from private.account_action_fences where subject_user_id=p_profile_id)) then raise invalid_parameter_value using message='operator_suspended_target'; end if;
  if p_manager_role is null then
    delete from private.operator_memberships where profile_id=p_profile_id;
    update public.profiles set role='user' where id=p_profile_id;
    -- 회수한 운영자의 로그인 세션을 모두 끊는다(OPS-005). 이미 받은 access token은 만료까지 남지만 운영자 능력이 없다.
    perform private.operator_revoke_auth_sessions(p_profile_id);
    next_revision:=0;
  else
    update private.operator_memberships set manager_role=p_manager_role,revision=revision+1,updated_at=clock_timestamp(),updated_by=actor
      where profile_id=p_profile_id returning revision into next_revision;
  end if;
  update private.operator_access_state set revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id returning * into state;
  result:=jsonb_build_object('revision',next_revision,'accessRevision',state.revision,'profileId',p_profile_id,'managerRole',p_manager_role);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.operator.role_changed','profile:'||p_profile_id::text,
    jsonb_build_object('before',to_jsonb(previous),'request',request,'result',result));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_change_order_address(p_operation_id uuid, p_order_id uuid, p_expected_revision integer, p_address jsonb, p_reason text, p_customer_agreed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();purchase public.orders; previous private.order_address_changes; address_value jsonb;
 reason text:=nullif(btrim(p_reason),'');blocked text;shipment public.order_shipments;base_groups jsonb:='[]';lines jsonb;
 quote jsonb;origin_key uuid;group_value jsonb;changed_fields jsonb;delivery jsonb;is_gift boolean;v2_lines jsonb;choices jsonb;
begin
 perform private.require_actor_operator_capability(actor,'sales.manage',false);
 if p_operation_id is null or p_order_id is null or p_expected_revision is null or p_expected_revision<0
  or p_customer_agreed is distinct from true or reason is null or char_length(reason)>500 or reason~'[[:cntrl:]]' then
  raise invalid_parameter_value using message='invalid_order_address_change';end if;
 address_value:=private.normalize_order_address_change(p_address);
 perform pg_advisory_xact_lock(hashtextextended('order_address_change:'||p_operation_id::text,0));
 select * into previous from private.order_address_changes where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.order_id<>p_order_id or previous.expected_order_revision<>p_expected_revision
   or previous.after_address<>address_value or previous.reason<>reason then raise unique_violation using message='order_address_request_conflict';end if;
  return private.order_address_change_receipt(p_operation_id,actor);
 end if;
 select * into purchase from public.orders where id=p_order_id for update;
 if not found then raise no_data_found using message='order_not_found';end if;
 perform id from public.order_shipments where order_id=p_order_id order by id for update;
 perform private.lock_order_private_delivery(p_order_id);
 delivery:=private.order_delivery_snapshot(p_order_id);
 is_gift:=exists(select 1 from private.gift_intents where order_id=p_order_id);
 if (delivery->>'addressRevision')::integer<>p_expected_revision then raise sqlstate 'PT409' using message='order_address_changed';end if;
 blocked:=private.order_address_change_blocker(purchase);
 if blocked is not null then raise check_violation using message=blocked;end if;
 select jsonb_agg(k order by k) into changed_fields from jsonb_object_keys(address_value)k where coalesce((delivery->'address')->>k,'')<>address_value->>k;
 if changed_fields is null then raise invalid_parameter_value using message='order_address_unchanged';end if;
 -- Contact/detail-note corrections preserve the destination quote. A changed
 -- postal/base address must remain deliverable at every frozen shipment amount.
 if (delivery->'address')->>'postalCode' is distinct from address_value->>'postalCode'
  or private.shipping_region_text((delivery->'address')->>'address1') is distinct from private.shipping_region_text(address_value->>'address1') then
  if purchase.calculation_version=2 then
   -- Match quote/place's catalog lock order before any origin policy lock.
   perform id from public.goods where id in(select good_id from public.order_items where order_id=p_order_id) order by id for share;
   perform private.lock_order_transaction_configurations(p_order_id);
  end if;
  for origin_key in select distinct origin_id from public.order_shipments where order_id=p_order_id order by origin_id loop
   perform id from public.fulfillment_origins where id=origin_key for share;
  end loop;
  if purchase.calculation_version=2 then
   select jsonb_agg(jsonb_build_object('good_id',good_id,'origin_id',origin_id_snapshot,'qty',qty,'unit_price',unit_price,'fee_type',shipping_fee_type_snapshot,'individual_fee',individual_fee_snapshot)) into v2_lines
    from public.order_items where order_id=p_order_id;
   select jsonb_object_agg(good_id,payment_mode) into choices from private.shipping_charge_components where order_id=p_order_id;
   quote:=private.calculate_goods_transaction_shipping(v2_lines,jsonb_build_object('postalCode',address_value->>'postalCode','address1',address_value->>'address1'),choices,clock_timestamp());
   if quote->>'state'='blocked' then raise check_violation using message='order_address_region_unavailable';end if;
   if (quote->>'prepaidFee')::bigint<>purchase.shipping_fee or (quote->>'collectFee')::bigint<>purchase.shipping_collect_total
    or exists(select 1 from jsonb_array_elements(quote->'rawGroups')g full join (select * from public.order_shipments where order_id=p_order_id)s on s.origin_id=(g->>'originId')::uuid
     where (s.id is null or g is null or (g->>'prepaidFee')::bigint<>s.shipping_fee or (g->>'collectFee')::bigint<>s.shipping_collect_fee)) then
    raise check_violation using message='order_address_shipping_fee_changed';end if;
  else
  for shipment in select * from public.order_shipments where order_id=p_order_id order by id loop
   group_value:=shipment.shipping_fee_snapshot;
   if shipment.delivery_method<>'parcel' or group_value->>'originId' is distinct from shipment.origin_id::text
    or not(group_value ?& array['policySubtotal','baseFee','freeThreshold','policyFee','individualFee','totalFee'])
    or jsonb_typeof(group_value->'totalFee') is distinct from 'number'
    or (group_value->>'totalFee')::bigint<>shipment.shipping_fee then
    raise check_violation using message='order_address_quote_unavailable';end if;
   base_groups:=base_groups||jsonb_build_array(group_value||jsonb_build_object('totalFee',shipment.shipping_fee-coalesce((group_value->>'regionalFee')::bigint,0)));
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('origin_id',origin_id_snapshot,'good_id',good_id,'fee_type',shipping_fee_type_snapshot)),'[]') into lines
   from public.order_items where order_id=p_order_id;
  quote:=private.apply_shipping_region_quote(jsonb_build_object('groups',base_groups),lines,
   jsonb_build_object('postalCode',address_value->>'postalCode','address1',address_value->>'address1'),clock_timestamp());
  if not coalesce((quote->>'checkoutAllowed')::boolean,false) then raise check_violation using message='order_address_region_unavailable';end if;
  if (quote->>'finalTotalFee')::bigint<>purchase.shipping_fee or exists(
   select 1 from jsonb_array_elements(quote->'groups')g join public.order_shipments s on s.order_id=p_order_id and s.origin_id=(g->>'originId')::uuid
   where (g->>'finalFee')::bigint<>s.shipping_fee) then raise check_violation using message='order_address_shipping_fee_changed';end if;
  end if;
 end if;
 insert into private.order_address_changes(id,order_id,actor_id,expected_order_revision,before_address,after_address,reason,destination_quote)
 values(p_operation_id,p_order_id,actor,p_expected_revision,delivery->'address',address_value,reason,quote);
 if is_gift then
  perform private.update_order_private_delivery(p_order_id,address_value);
 else update public.orders set address=address_value,updated_at=clock_timestamp() where id=p_order_id;end if;
 -- Invalidate any export prepared before the change but not yet marked sent.
 update public.order_shipments set updated_at=clock_timestamp() where order_id=p_order_id;
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.order.address_changed','order:'||p_order_id,
  jsonb_build_object('changedFields',changed_fields,'customerAgreed',true,'agreementParty',case when is_gift then 'recipient' else 'buyer' end,'shipmentCount',(select count(*) from public.order_shipments where order_id=p_order_id),'shippingFeeUnchanged',true));
 return private.order_address_change_receipt(p_operation_id,actor);
end $function$

CREATE OR REPLACE FUNCTION public.admin_change_order_claim_hold(p_claim_id uuid, p_operation_id uuid, p_expected_revision integer, p_expected_claim_type text, p_decision text, p_note text, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();order_key uuid;buyer uuid;claim public.order_cancellation_requests;
 previous private.order_claim_hold_operations;next_stage text;note text:=btrim(p_note);result_revision integer;
begin
 if actor is null or p_expected_actor_id is distinct from actor
  or not private.has_operator_capability(actor,'sales.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';end if;
 if p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or p_expected_claim_type is null or p_expected_claim_type not in('cancel','return','exchange')
  or p_decision is null or p_decision not in('hold','resume') then
  raise invalid_parameter_value using message='invalid_claim_hold';end if;
 if p_decision='hold' and(note is null or char_length(note) not between 10 and 200 or note~'[[:cntrl:]]') then
  raise check_violation using message='invalid hold reason';end if;
 if p_decision='resume' and p_note is not null then raise invalid_parameter_value using message='invalid_claim_hold';end if;
 select c.order_id,o.user_id into order_key,buyer from public.order_cancellation_requests c join public.orders o on o.id=c.order_id where c.id=p_claim_id;
 if order_key is null then raise no_data_found using message='claim_not_found';end if;
 -- Account fences precede operation and parent locks, matching conversion and withdrawal.
 perform private.lock_operator_subjects(array[actor,buyer]);
 perform private.require_actor_operator_capability(actor,'sales.manage',false);
 perform pg_advisory_xact_lock(hashtextextended('claim-hold:'||p_operation_id::text,0));
 select * into previous from private.order_claim_hold_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision
   or previous.claim_type<>p_expected_claim_type or previous.decision<>p_decision or previous.note is distinct from note then
   raise unique_violation using message='claim_hold_request_conflict';end if;
  return private.order_claim_hold_receipt(p_operation_id,actor);
 end if;
 perform id from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 if claim.claim_revision<>p_expected_revision or claim.claim_type<>p_expected_claim_type then
  raise sqlstate 'PT409' using message='claim_changed';end if;
 if claim.stage in('completed','rejected','withdrawn') then raise check_violation using message='claim_hold_unavailable';end if;
 if p_decision='hold' and claim.stage='on_hold' then raise check_violation using message='claim_already_held';end if;
 if p_decision='resume' and (claim.stage<>'on_hold' or coalesce(claim.held_from,'requested') not in('requested','in_review','collecting','collected','processing','needs_review')) then
  raise check_violation using message='claim_not_held';end if;
 -- Reuse the single stage/held_from, buyer notification and audit implementation.
 next_stage:=private.decide_order_claim(p_claim_id,p_decision,note);
 select claim_revision into result_revision from public.order_cancellation_requests where id=p_claim_id;
 insert into private.order_claim_hold_operations(id,actor_id,claim_id,order_id,claim_type,expected_revision,
  decision,note,from_stage,to_stage,result_revision)
 values(p_operation_id,actor,p_claim_id,order_key,claim.claim_type,p_expected_revision,p_decision,note,
  claim.stage,next_stage,result_revision);
 return private.order_claim_hold_receipt(p_operation_id,actor);
end $function$

CREATE OR REPLACE FUNCTION public.admin_change_order_claim_reason(p_claim_id uuid, p_operation_id uuid, p_expected_revision integer, p_expected_actor_id uuid, p_reason_type text, p_reason text, p_agreement text, p_confirmed boolean, p_fee_reviewed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();claim public.order_cancellation_requests;purchase public.orders;previous private.order_claim_reason_operations;
 order_key uuid;buyer uuid;reason_text text:=btrim(p_reason);agreement_text text:=btrim(p_agreement);blocker text;happened timestamptz;
 changed boolean;result_revision integer;
begin
 if actor is null or actor is distinct from p_expected_actor_id or not private.has_operator_capability(actor,'sales.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';end if;
 if p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or p_reason_type is null or p_reason_type not in('change_of_mind','defect') or p_confirmed is distinct from true or p_fee_reviewed is null
  or reason_text is null or char_length(reason_text) not between 1 and 200 or p_reason~'[[:cntrl:]]'
  or agreement_text is null or char_length(agreement_text) not between 2 and 500 or p_agreement~'[[:cntrl:]]' then
  raise invalid_parameter_value using message='invalid_claim_reason_change';end if;
 select c.order_id,o.user_id into order_key,buyer from public.order_cancellation_requests c join public.orders o on o.id=c.order_id where c.id=p_claim_id;
 if order_key is null then raise no_data_found using message='claim_not_found';end if;
 perform private.lock_operator_subjects(array[actor,buyer]);
 perform private.require_actor_operator_capability(actor,'sales.manage',false);
 perform pg_advisory_xact_lock(hashtextextended('claim-reason-change:'||p_operation_id::text,0));
 select * into previous from private.order_claim_reason_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision
   or previous.to_reason_type<>p_reason_type or previous.to_reason<>reason_text or previous.agreement<>agreement_text
   or previous.fee_reviewed<>p_fee_reviewed then raise unique_violation using message='claim_reason_request_conflict';end if;
  return private.order_claim_reason_receipt(p_operation_id,actor);
 end if;
 select * into purchase from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 perform shipment_id from public.order_claim_collections where claim_id=p_claim_id order by shipment_id for update;
 if claim.claim_revision<>p_expected_revision or claim.order_id is distinct from order_key or purchase.user_id is distinct from buyer then
  raise sqlstate 'PT409' using message='claim_changed';end if;
 blocker:=private.order_claim_reason_blocker(claim);
 if blocker is not null then raise check_violation using message=blocker;end if;
 if claim.operational_fee_amount is not null and not p_fee_reviewed then raise check_violation using message='claim_reason_fee_review_required';end if;
 -- The new classification is evaluated at original intake, never the edit time.
 if claim.reason_type<>p_reason_type and public.order_withdrawal_deadline_passed(purchase.delivered_at,p_reason_type,claim.requested_at) then
  raise check_violation using message='claim_reason_original_deadline_expired';end if;
 changed:=(claim.reason_type,claim.reason) is distinct from(p_reason_type,reason_text);
 happened:=clock_timestamp();result_revision:=claim.claim_revision;
 if changed then
  update public.order_cancellation_requests set reason_type=p_reason_type,reason=reason_text,updated_at=happened
   where id=p_claim_id returning claim_revision into result_revision;
 end if;
 insert into private.order_claim_reason_operations(id,claim_id,order_id,actor_id,expected_revision,result_revision,
  from_reason_type,from_reason,to_reason_type,to_reason,agreement,fee_reviewed,changed,from_stage,requested_at,delivered_at,created_at)
 values(p_operation_id,p_claim_id,order_key,actor,p_expected_revision,result_revision,claim.reason_type,claim.reason,
  p_reason_type,reason_text,agreement_text,p_fee_reviewed,changed,claim.stage,claim.requested_at,purchase.delivered_at,happened);
 if changed then
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.order.claim_reason_changed','order:'||order_key,
   jsonb_build_object('claimId',p_claim_id,'fromReasonType',claim.reason_type,'toReasonType',p_reason_type,
    'descriptionChanged',claim.reason<>reason_text,'customerConfirmed',true,'feeReviewed',p_fee_reviewed));
  insert into public.notifications(user_id,type,title,body,link_path,source_type,source_id,dedupe_key)
   values(buyer,'claim_updated','교환 요청 사유가 정정됐어요',
    case p_reason_type when 'defect' then '상품 하자·오배송' else '단순 변심' end||': '||reason_text,
    '/orders/'||order_key,'order_claim',p_claim_id::text,'claim:reason_changed:'||p_operation_id)
   on conflict(user_id,dedupe_key) do nothing;
 end if;
 return private.order_claim_reason_receipt(p_operation_id,actor);
end $function$

CREATE OR REPLACE FUNCTION public.admin_change_order_production(p_job uuid, p_kind text, p_revision bigint, p_operation uuid, p_actor uuid, p_session uuid, p_evidence text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_key uuid;job private.order_production_jobs;prior private.order_production_events;request jsonb;result jsonb;document jsonb;row_value jsonb;at_value timestamptz:=clock_timestamp();begin
 select order_id into order_key from private.order_production_jobs where id=p_job;if order_key is null then raise no_data_found;end if;
 perform private.production_identity(p_actor,p_session,order_key,'sales.manage');
 if p_kind is null or p_kind not in('start','complete') or p_revision is null or p_revision<1 or p_operation is null or p_evidence is null or char_length(btrim(p_evidence)) not between 2 and 1000 or p_evidence~'[[:cntrl:]]' then raise invalid_parameter_value;end if;
 perform id from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 perform id from public.order_cancellation_requests where order_id=order_key order by id for update;
 select * into job from private.order_production_jobs where id=p_job for update;
 request:=jsonb_build_object('jobId',p_job,'kind',p_kind,'revision',p_revision,'sessionId',p_session,'evidence',btrim(p_evidence));
 select * into prior from private.order_production_events where id=p_operation;
 if found then if prior.actor_id is distinct from p_actor or prior.request is distinct from request then raise sqlstate 'PT409' using message='production_operation_conflict';end if;return prior.result;end if;
 if job.revision<>p_revision then raise sqlstate 'PT409' using message='production_changed';end if;
 document:=private.order_production_document(order_key,true);select value into row_value from jsonb_array_elements(document->'jobs') where value->>'id'=p_job::text;
 if (row_value->>case when p_kind='start' then 'canStart' else 'canComplete' end)::boolean is distinct from true then raise check_violation using message='production_transition_unavailable';end if;
 at_value:=clock_timestamp();
 update private.order_production_jobs set state=case when p_kind='start' then 'started' else 'completed' end,revision=revision+1,
 started_at=case when p_kind='start' then at_value else started_at end,completed_at=case when p_kind='complete' then at_value else completed_at end,updated_at=at_value where id=p_job;
 if job.claim_id is null then update public.order_shipments set updated_at=clock_timestamp() where id in(select shipment_id from public.order_shipment_items where order_item_id=job.order_item_id);end if;
 result:=jsonb_build_object('jobId',p_job,'orderId',order_key,'revision',p_revision+1,'state',case when p_kind='start' then 'started' else 'completed' end);
 insert into private.order_production_events(id,job_id,actor_id,session_id,kind,request,result) values(p_operation,p_job,p_actor,p_session,p_kind,request,result);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation,p_actor,'order.production.'||p_kind,'order:'||order_key,jsonb_build_object('jobId',p_job,'claimId',job.claim_id,'itemId',job.order_item_id,'revision',p_revision+1,'evidence',btrim(p_evidence)));return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_change_shipment_pack(p_ids uuid[], p_kind text, p_version text, p_reason text, p_operation uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ids uuid[];parties uuid[];e private.shipment_pack_events;request jsonb;document jsonb;pack_key uuid;result jsonb;begin
 perform private.purchase_confirmation_identity(p_actor,p_session,true);
 if cardinality(p_ids) is null or cardinality(p_ids) not between 1 and 100 or array_position(p_ids,null) is not null
  or(select count(distinct id) from unnest(p_ids)id)<>cardinality(p_ids) or p_kind is null or p_kind not in('create','release')
  or p_version is null or p_version!~'^[a-f0-9]{64}$' or p_operation is null or p_reason is null or char_length(btrim(p_reason)) not between 2 and 500 or p_reason~'[[:cntrl:]]' then raise invalid_parameter_value;end if;
 select array_agg(id order by id) into p_ids from unnest(p_ids)id;
 select array_agg(distinct subject) into parties from public.order_shipments s cross join lateral unnest(private.contact_parties(s.order_id))subject where s.id=any(private.shipment_pack_scope(p_ids));
 perform private.gift_lock_subjects(array_append(parties,p_actor));perform private.lock_operator_subjects(array_append(parties,p_actor));
 if exists(select 1 from private.account_action_fences where subject_user_id=p_actor) then raise insufficient_privilege;end if;
 perform private.require_operator_capability('sales.manage',false);
 perform pg_advisory_xact_lock(hashtextextended('shipment-pack:'||p_operation,0));
 request:=jsonb_build_object('ids',to_jsonb(p_ids),'kind',p_kind,'version',p_version,'reason',btrim(p_reason));
 select * into e from private.shipment_pack_events where id=p_operation;
 if found then
  if e.actor_id<>p_actor or e.session_id<>p_session or e.request<>request then raise sqlstate 'PT409' using message='shipment_pack_conflict';end if;return e.result;end if;
 ids:=private.lock_shipment_pack_scope(p_ids);document:=private.shipment_pack_document(p_ids);
 if document->>'version'<>p_version then raise sqlstate 'PT409' using message='shipment_pack_changed';end if;
 if p_kind='create' then
  if document->>'canCreate'<>'true' then raise check_violation using message='shipment_pack_ineligible';end if;
  pack_key:=p_operation;insert into private.shipment_packs(id,created_by) values(pack_key,p_actor);
  insert into private.shipment_pack_members(pack_id,shipment_id,identity_digest) select pack_key,id,encode(extensions.digest(private.shipment_pack_identity(id)::text,'sha256'),'hex') from unnest(ids)id;
 else
  select private.shipment_pack_id(p_ids[1]) into pack_key;
  if pack_key is null or exists(select 1 from unnest(ids)id where private.shipment_pack_id(id) is distinct from pack_key)
   or not coalesce((private.shipment_pack_summary(p_ids[1])->>'canRelease')::boolean,false) then raise check_violation using message='shipment_pack_release_blocked';end if;
  update private.shipment_packs set released_at=clock_timestamp(),release_reason=btrim(p_reason),revision=revision+1 where id=pack_key;
  update private.shipment_pack_members set released_at=clock_timestamp() where pack_id=pack_key and released_at is null;
 end if;
 -- Membership changes invalidate a file prepared just before this transaction.
 update public.order_shipments set updated_at=clock_timestamp() where id=any(ids);
 result:=jsonb_build_object('packId',pack_key,'kind',p_kind,'shipmentIds',to_jsonb(ids));
 insert into private.shipment_pack_events(id,pack_id,actor_id,session_id,kind,request,result) values(p_operation,pack_key,p_actor,p_session,p_kind,request,result);
 insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'admin.shipment.pack_'||p_kind,pack_key::text,jsonb_build_object('operationId',p_operation,'shipmentIds',to_jsonb(ids),'reason',btrim(p_reason)));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_change_shipment_preorder_date(p_shipment_id uuid, p_expected_ship_date date, p_reason text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); shipment public.order_shipments; purchase public.orders; changed_at timestamptz:=clock_timestamp();
begin
  perform private.require_operator_capability('sales.manage',false);

  if actor is null or not coalesce(public.has_operator_capability('sales.manage',false),false) then raise insufficient_privilege using message='staff required'; end if;
  if p_expected_ship_date is null or p_expected_ship_date<(statement_timestamp() at time zone 'Asia/Seoul')::date
    or nullif(btrim(p_reason),'') is null or length(btrim(p_reason))>2000 or p_expected_updated_at is null then
    raise invalid_parameter_value using message='invalid_preorder_shipment_promise';
  end if;
  select purchase_row.* into purchase from public.orders purchase_row join public.order_shipments shipment_row on shipment_row.order_id=purchase_row.id
    where shipment_row.id=p_shipment_id for update of purchase_row;
  if not found then raise no_data_found using message='shipment_not_found'; end if;
  select * into shipment from public.order_shipments where id=p_shipment_id for update;
  if shipment.status<>'ready' or purchase.status not in ('pending','paid','confirmed','shipping') then
    raise check_violation using message='preorder_shipment_already_dispatched';
  end if;
  if shipment.original_expected_ship_date is null then raise check_violation using message='shipment_not_preorder'; end if;
  if shipment.updated_at is distinct from p_expected_updated_at then raise sqlstate 'PT409' using message='shipment_promise_changed'; end if;
  perform private.assert_order_dispatch_allowed(purchase.id);
  if shipment.expected_ship_date=p_expected_ship_date then return jsonb_build_object('changed',false,'updatedAt',shipment.updated_at); end if;
  insert into private.order_shipment_promise_changes(shipment_id,from_date,to_date,reason,actor_id,created_at)
    values(shipment.id,shipment.expected_ship_date,p_expected_ship_date,btrim(p_reason),actor,changed_at);
  update public.order_shipments set expected_ship_date=p_expected_ship_date,updated_at=changed_at where id=shipment.id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.shipment.preorder_promise_changed','order:'||purchase.id,
    jsonb_build_object('shipmentId',shipment.id,'originalDate',shipment.original_expected_ship_date,'fromDate',shipment.expected_ship_date,
      'toDate',p_expected_ship_date,'reason',btrim(p_reason)));
  return jsonb_build_object('changed',true,'updatedAt',changed_at,'orderId',purchase.id);
end $function$

