CREATE OR REPLACE FUNCTION public.admin_clone_good(target_operation_id uuid, target_source_good_id text, target_new_id text DEFAULT NULL::text, target_new_code text DEFAULT NULL::text, target_new_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved jsonb; replay boolean;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if auth.uid() is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='forbidden'; end if;
  perform pg_advisory_xact_lock(hashtextextended('admin.goods.clone.operation:'||target_operation_id::text,0));
  select exists(select 1 from public.audit_log where id=target_operation_id) into replay;
  saved:=private.admin_clone_good_before_custom_inputs(target_operation_id,target_source_good_id,target_new_id,target_new_code,target_new_name);
  if not replay then
    update public.goods copied set custom_inputs_enabled=source.custom_inputs_enabled,custom_input_fields=source.custom_input_fields
      from public.goods source where source.id=saved->>'sourceGoodId' and copied.id=saved->>'id';
  end if;
  return saved;
end $function$

CREATE OR REPLACE FUNCTION public.admin_close_inquiry(target_inquiry_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_status text;
begin
  perform private.require_operator_capability('cs.manage',false);

  if v_actor is null or not public.has_operator_capability('cs.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;

  select thread.status
  into v_status
  from public.inquiries as thread
  where thread.id = target_inquiry_id
  for update;

  if not found then
    raise no_data_found using message = 'inquiry_not_found';
  end if;

  -- 이미 닫힌 문의를 다시 닫아도 실패로 만들지 않는다. 목록에서 두 번 눌린 종결이
  -- 오류 배너로 돌아오면 운영자가 "안 닫혔다"고 읽는다.
  if v_status = 'closed' then
    return;
  end if;

  update public.inquiries as thread
  set
    status = 'closed',
    closed_at = now(),
    handled_by = coalesce(thread.handled_by, v_actor)
  where thread.id = target_inquiry_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.inquiry.closed',
    'inquiries:' || target_inquiry_id::text,
    jsonb_build_object('previousStatus', v_status)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_commit_discount_promotion(p_id uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare operation private.discount_promotion_operations; applied_ids text[]; id_value text; line jsonb; g public.goods;
  variant public.goods_variants; starts timestamptz; ends timestamptz; period_count integer:=0; skipped jsonb; result jsonb; failure text;
begin
  perform private.require_goods_group_identity(p_actor,p_session);
  if p_id is null then raise invalid_parameter_value using message='discount_promotion_invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('discount-promotion:'||p_id::text,0));
  select * into operation from private.discount_promotion_operations where id=p_id for update;
  if not found or operation.actor_id<>p_actor or operation.session_id<>p_session then
    raise insufficient_privilege using message='discount_promotion_operation_unavailable';
  end if;
  if operation.receipt is not null then return operation.receipt; end if;
  starts:=(operation.request->>'startsAt')::timestamptz; ends:=(operation.request->>'endsAt')::timestamptz;
  applied_ids:=array(select key from jsonb_object_keys(operation.guards) key order by key);
  select coalesce(jsonb_agg(jsonb_build_object('id',item->>'id','name',item->>'name','code',item->'code','reason',item->>'skip') order by ordinality),'[]'::jsonb)
    into skipped from jsonb_array_elements(operation.preview->'goods') with ordinality goods(item,ordinality) where nullif(item->>'skip','') is not null;
  begin
    foreach id_value in array applied_ids loop
      if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||id_value,0)) then
        raise sqlstate 'PT409' using message='discount_promotion_busy';
      end if;
    end loop;
    begin
      perform 1 from public.goods where id=any(applied_ids) order by id for update nowait;
      perform 1 from public.goods_variants where good_id=any(applied_ids) order by id for update nowait;
      perform 1 from private.goods_variant_price_periods where good_id=any(applied_ids) order by id for update nowait;
    exception when lock_not_available then raise sqlstate 'PT409' using message='discount_promotion_busy';
    end;
    -- 잠근 뒤 다시 본다: 유효기간, 그리고 옵션 가격·옵션 구성·기간할인이 비교 이후 바뀌었는지(재고 변동은 보지 않는다).
    if operation.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='discount_promotion_preview_expired'; end if;
    if exists(select 1 from unnest(applied_ids) id where private.goods_bulk_price_fingerprint(id) is distinct from operation.guards->>id) then
      raise sqlstate 'PT409' using message='discount_promotion_changed';
    end if;
    if ends<=clock_timestamp() then raise check_violation using message='discount_promotion_period_ended'; end if;
    insert into private.discount_promotions(id,name,state,starts_at,ends_at,target_kind,target_ids,target_label,default_rule,request,
      goods_count,applied_count,created_by)
    values(p_id,operation.request->>'name','active',starts,ends,operation.preview#>>'{target,kind}',
      array(select value from jsonb_array_elements_text(operation.preview#>'{target,ids}') with ordinality item(value,ordinality) order by ordinality),
      operation.preview#>>'{target,label}',operation.request->'rule',operation.request,
      jsonb_array_length(operation.preview->'goods'),cardinality(applied_ids),p_actor);
    insert into private.discount_promotion_goods(promotion_id,good_id,position,name,code,rule,skip_reason)
    select p_id,item->>'id',ordinality,item->>'name',item->>'code',item->'rule',nullif(item->>'skip','')
    from jsonb_array_elements(operation.preview->'goods') with ordinality goods(item,ordinality);
    for line in select item from jsonb_array_elements(operation.preview->'goods') with ordinality goods(item,ordinality)
      where nullif(item->>'skip','') is null order by ordinality loop
      select * into g from public.goods where id=line->>'id';
      for variant in select * from public.goods_variants where good_id=g.id and archived_at is null order by id loop
        perform private.insert_discount_promotion_period(p_id,g.id,variant.id,private.discount_promotion_price(g.price,variant.price,line->'rule'),
          starts,ends,p_actor);
        period_count:=period_count+1;
      end loop;
    end loop;
    result:=jsonb_build_object('state','completed','operationId',p_id,'promotionId',p_id,'goodsCount',cardinality(applied_ids),
      'periodCount',period_count,'skipped',skipped,'error',null);
    insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'catalog.discount_promotion.created','discount_promotion:'||p_id::text,
      jsonb_build_object('request',operation.request,'preview',operation.preview,'receipt',result));
  exception when others then
    -- 하위 트랜잭션이 프로모션·기간할인·감사 행을 모두 되돌린다. 거절도 영수증으로 남겨 불명확한 응답을 재실행하지 않는다.
    get stacked diagnostics failure=message_text;
    result:=jsonb_build_object('state','rejected','operationId',p_id,'promotionId',null,'goodsCount',0,'periodCount',0,'skipped','[]'::jsonb,
      'error',case when failure ~ '^[a-z][a-z0-9_]{0,100}$' then failure else 'discount_promotion_rejected' end);
  end;
  update private.discount_promotion_operations set receipt=result where id=p_id;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_commit_erp_linked_goods(p_operation_id uuid, p_keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_operation private.erp_goods_apply_operations;
  v_keys text[];
  v_selected jsonb;
  v_current jsonb;
  v_good_ids text[];
  v_variant_ids uuid[];
  v_good_id text;
  v_good public.goods;
  v_final_base integer;
  v_options jsonb;
  v_baseline jsonb;
  v_row jsonb;
  v_identity private.goods_variant_external_identity;
  v_failure text;
  v_applied jsonb := '[]'::jsonb;
  v_failed jsonb := '[]'::jsonb;
  v_receipt jsonb;
begin
  perform private.require_operator_capability('catalog.manage', false);
  if v_actor is null or not public.has_operator_capability('catalog.manage', false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if p_operation_id is null or p_keys is null
     or pg_catalog.cardinality(p_keys) not between 1 and 500
     or pg_catalog.array_position(p_keys, null) is not null then
    raise invalid_parameter_value using message = 'invalid_erp_goods_apply_keys';
  end if;
  select pg_catalog.array_agg(distinct key.value) into v_keys from pg_catalog.unnest(p_keys) as key(value);

  select * into v_operation from private.erp_goods_apply_operations where id = p_operation_id for update;
  if not found or v_operation.actor_id <> v_actor then
    raise insufficient_privilege using message = 'erp_goods_apply_unavailable';
  end if;
  if v_operation.receipt is not null then
    return v_operation.receipt;
  end if;

  select coalesce(pg_catalog.jsonb_agg(entry.value order by entry.ordinality), '[]'::jsonb) into v_selected
  from pg_catalog.jsonb_array_elements(v_operation.preview -> 'rows') with ordinality as entry(value, ordinality)
  where entry.value ->> 'key' = any(v_keys) and entry.value ->> 'status' = 'apply';
  if pg_catalog.jsonb_array_length(v_selected) <> pg_catalog.cardinality(v_keys) then
    raise invalid_parameter_value using message = 'invalid_erp_goods_apply_keys';
  end if;

  if v_operation.expires_at <= pg_catalog.clock_timestamp() then
    v_receipt := pg_catalog.jsonb_build_object('state', 'rejected', 'operationId', p_operation_id, 'error', 'erp_goods_apply_expired');
    update private.erp_goods_apply_operations set receipt = v_receipt where id = p_operation_id;
    return v_receipt;
  end if;

  select pg_catalog.array_agg(distinct row.value ->> 'goodId' order by row.value ->> 'goodId'),
         pg_catalog.array_agg(distinct (row.value ->> 'variantId')::uuid)
  into v_good_ids, v_variant_ids
  from pg_catalog.jsonb_array_elements(v_selected) as row(value);

  -- 잠금 순서: ERP 반입(값 고정) → 카테고리 트리 → 상품별 편집 잠금 → 상품 행 → 옵션 행 → 옵션 ERP 식별자.
  -- 상품 저장(admin_save_good)과 같은 순서라 편집 화면 저장과 교착하지 않는다.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.erp_items.import', 0));
  perform private.lock_catalog_category_tree();
  foreach v_good_id in array v_good_ids loop
    if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('admin_good:' || v_good_id, 0)) then
      raise sqlstate 'PT409' using message = 'erp_goods_apply_busy';
    end if;
  end loop;
  perform 1 from public.goods where id = any(v_good_ids) order by id for update;
  perform 1 from public.goods_variants where good_id = any(v_good_ids) order by id for update;
  perform 1 from private.goods_variant_external_identity where variant_id = any(v_variant_ids) order by variant_id for update;

  -- 잠근 뒤 같은 계산을 다시 해 고른 행이 미리보기와 같은지 본다. 하나라도 다르면 아무것도 바꾸지 않는다.
  -- 행 키로 찾을 수 있게 key → 행 객체로 묶는다(고른 행마다 전체 계획을 다시 펼치지 않는다).
  select coalesce(pg_catalog.jsonb_object_agg(fresh.value ->> 'key', fresh.value), '{}'::jsonb) into v_current
  from pg_catalog.jsonb_array_elements(private.erp_linked_goods_plan(v_operation.scope_codes) -> 'rows') as fresh(value);
  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(v_selected) as chosen(value)
    where v_current -> (chosen.value ->> 'key') is null
       or (v_current -> (chosen.value ->> 'key') -> 'goodId') is distinct from chosen.value -> 'goodId'
       or (v_current -> (chosen.value ->> 'key') -> 'current') is distinct from chosen.value -> 'current'
       or (v_current -> (chosen.value ->> 'key') -> 'next') is distinct from chosen.value -> 'next'
       or (v_current -> (chosen.value ->> 'key') -> 'status') is distinct from chosen.value -> 'status'
  ) then
    v_receipt := pg_catalog.jsonb_build_object('state', 'rejected', 'operationId', p_operation_id, 'error', 'erp_goods_apply_changed');
    update private.erp_goods_apply_operations set receipt = v_receipt where id = p_operation_id;
    return v_receipt;
  end if;

  -- 같은 상품의 판매가 행을 일부만 고르면 미리보기에서 본 상품 단위 검사와 결과가 달라질 수 있다. 고른 행만으로 다시 본다.
  foreach v_good_id in array v_good_ids loop
    if not exists (select 1 from pg_catalog.jsonb_array_elements(v_selected) as row(value)
                   where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price') then
      continue;
    end if;
    select * into v_good from public.goods where id = v_good_id;
    v_final_base := coalesce((
      select (row.value ->> 'next')::integer
      from pg_catalog.jsonb_array_elements(v_selected) as row(value)
      join public.goods_variants as variant on variant.id = (row.value ->> 'variantId')::uuid
      where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price' and variant.is_default
    ), v_good.price);
    if exists (
         select 1
         from public.goods_variants as variant
         left join pg_catalog.jsonb_array_elements(v_selected) as row(value)
           on row.value ->> 'field' = 'price' and (row.value ->> 'variantId')::uuid = variant.id
         where variant.good_id = v_good_id
           and (variant.archived_at is null or variant.is_default)
           and coalesce((row.value ->> 'next')::integer, variant.price) < v_final_base
       ) then
      raise check_violation using message = 'erp_goods_apply_partial_price', detail = v_good.name;
    end if;
  end loop;

  foreach v_good_id in array v_good_ids loop
    select * into v_good from public.goods where id = v_good_id;

    -- 판매가: 상품 목록의 판매가 바로 수정과 같은 상품 저장 RPC(admin_save_good)를 부른다. 고르지 않은 옵션의 판매 금액은 그대로 둔다.
    -- 옵션 행은 상품 편집 저장과 같다(lib/admin/goods-option-editor.ts initialGoodsOptionRows: 사용 중인 옵션 + 사용 중지된 기본 옵션,
    -- 기본 옵션이 첫 행). private.save_goods_options는 첫 행을 기본 옵션으로 정하므로, 사용 중지된 기본 옵션을 isActive=false로
    -- 첫 행에 실어 기본 옵션이 다른 옵션으로 바뀌지 않게 한다. 그 밖의 사용 중지 옵션은 싣지 않아 그대로 남는다.
    if exists (select 1 from pg_catalog.jsonb_array_elements(v_selected) as row(value)
               where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price') then
      v_final_base := coalesce((
        select (row.value ->> 'next')::integer
        from pg_catalog.jsonb_array_elements(v_selected) as row(value)
        join public.goods_variants as variant on variant.id = (row.value ->> 'variantId')::uuid
        where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price' and variant.is_default
      ), v_good.price);
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'id', variant.id, 'name', variant.name, 'attributes', variant.attributes, 'code', variant.code,
          'extraPrice', coalesce((chosen.value ->> 'next')::integer, variant.price) - v_final_base,
          'stockQty', variant.stock_qty, 'expectedStockQty', variant.stock_qty, 'isActive', variant.archived_at is null,
          'lowStockThreshold', variant.low_stock_threshold)
        order by variant.is_default desc, variant.sort_order, variant.id)
      into v_options
      from public.goods_variants as variant
      left join pg_catalog.jsonb_array_elements(v_selected) as chosen(value)
        on chosen.value ->> 'field' = 'price' and (chosen.value ->> 'variantId')::uuid = variant.id
      where variant.good_id = v_good_id and (variant.archived_at is null or variant.is_default);
      select coalesce(pg_catalog.jsonb_agg(variant.id::text order by variant.id), '[]'::jsonb) into v_baseline
      from public.goods_variants as variant
      where variant.good_id = v_good_id and variant.archived_at is null;
      begin
        perform public.admin_save_good(pg_catalog.to_jsonb(v_good) || pg_catalog.jsonb_build_object(
          'previous_id', v_good.id, 'publish', null, 'custom_inputs_expected_revision', v_good.custom_inputs_revision,
          'price', v_final_base, 'variants', v_options, 'variant_baseline', v_baseline));
        select v_applied || coalesce(pg_catalog.jsonb_agg(row.value order by row.value ->> 'key'), '[]'::jsonb) into v_applied
        from pg_catalog.jsonb_array_elements(v_selected) as row(value)
        where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price';
      exception when others then
        get stacked diagnostics v_failure = message_text;
        select v_failed || coalesce(pg_catalog.jsonb_agg(row.value || pg_catalog.jsonb_build_object('error',
            case when v_failure ~ '^[a-z][a-z0-9_]{0,100}$' then v_failure else 'goods_save_rejected' end)
          order by row.value ->> 'key'), '[]'::jsonb) into v_failed
        from pg_catalog.jsonb_array_elements(v_selected) as row(value)
        where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'price';
      end;
    end if;

    -- 바코드: 옵션 ERP 식별자 저장 함수로 바꾼다(잠금·낙관적 확인·감사 기록이 그 함수에 있다). ERP 코드·품명은 그대로 둔다.
    for v_row in
      select row.value from pg_catalog.jsonb_array_elements(v_selected) as row(value)
      where row.value ->> 'goodId' = v_good_id and row.value ->> 'field' = 'barcode'
      order by row.value ->> 'key'
    loop
      begin
        select * into v_identity from private.goods_variant_external_identity
        where variant_id = (v_row ->> 'variantId')::uuid;
        perform private.save_goods_variant_external_identity(
          v_good_id, (v_row ->> 'variantId')::uuid, v_identity.erp_code, v_identity.erp_name,
          v_row ->> 'next', v_identity.updated_at, v_actor);
        v_applied := v_applied || pg_catalog.jsonb_build_array(v_row);
      exception when others then
        get stacked diagnostics v_failure = message_text;
        v_failed := v_failed || pg_catalog.jsonb_build_array(v_row || pg_catalog.jsonb_build_object('error',
          case when v_failure ~ '^[a-z][a-z0-9_]{0,100}$' then v_failure else 'goods_save_rejected' end));
      end;
    end loop;
  end loop;

  v_receipt := pg_catalog.jsonb_build_object(
    'state', 'completed',
    'operationId', p_operation_id,
    'applied', pg_catalog.jsonb_build_object(
      'price', (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_applied) as row(value) where row.value ->> 'field' = 'price'),
      'barcode', (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_applied) as row(value) where row.value ->> 'field' = 'barcode'),
      'goods', (select pg_catalog.count(distinct row.value ->> 'goodId') from pg_catalog.jsonb_array_elements(v_applied) as row(value))),
    'failed', (
      select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'key', row.value ->> 'key', 'field', row.value ->> 'field', 'goodId', row.value ->> 'goodId',
          'goodName', row.value ->> 'goodName', 'optionName', row.value ->> 'optionName', 'error', row.value ->> 'error')
        order by row.value ->> 'key'), '[]'::jsonb)
      from pg_catalog.jsonb_array_elements(v_failed) as row(value)));

  insert into public.audit_log (actor_id, action, target, diff)
  values (v_actor, 'admin.erp_items.linked_goods_applied', 'erp_items', pg_catalog.jsonb_build_object(
    'operationId', p_operation_id,
    'scopeCount', case when v_operation.scope_codes is null then null else pg_catalog.cardinality(v_operation.scope_codes) end,
    'applied', (
      select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'key', row.value ->> 'key', 'field', row.value ->> 'field', 'goodId', row.value ->> 'goodId',
          'variantId', row.value ->> 'variantId', 'erpCode', row.value ->> 'erpCode',
          'before', row.value -> 'current', 'after', row.value -> 'next', 'warning', row.value -> 'warning')
        order by row.value ->> 'key'), '[]'::jsonb)
      from pg_catalog.jsonb_array_elements(v_applied) as row(value)),
    'failed', v_receipt -> 'failed'));

  update private.erp_goods_apply_operations set receipt = v_receipt where id = p_operation_id;
  return v_receipt;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_commit_goods_bulk(p_id uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare operation private.goods_bulk_operations;ids text[];lock_ids text[];id_value text;group_value jsonb;g public.goods;v public.goods_variants;
 p private.goods_variant_price_periods;command text;values_doc jsonb;payload jsonb;result jsonb;failure text;options jsonb;baseline jsonb;
 skipped_ids text[];skipped jsonb;
begin
 perform private.require_goods_group_identity(p_actor,p_session);
 perform pg_advisory_xact_lock(hashtextextended('goods-bulk:'||p_id::text,0));
 select * into operation from private.goods_bulk_operations where id=p_id for update;
 if not found or operation.actor_id<>p_actor or operation.session_id<>p_session then raise insufficient_privilege using message='goods_bulk_operation_unavailable';end if;
 if operation.receipt is not null then return operation.receipt;end if;
 command:=operation.request->>'command';values_doc:=operation.request->'values';
 select array_agg(key order by key) into ids from jsonb_object_keys(operation.guards) key;
 -- Skips were frozen in the reviewed preview; a preview stored before this
 -- change has no skip key and therefore applies to every good as before.
 select coalesce(array_agg(r->>'id' order by r->>'id'),'{}'),
  coalesce(jsonb_agg(jsonb_build_object('id',r->>'id','name',r->>'name','code',r->'code','reason',r->>'skip') order by r->>'id'),'[]')
  into skipped_ids,skipped from jsonb_array_elements(operation.preview->'goods') r where nullif(r->>'skip','') is not null;
 begin
  perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
  perform private.lock_catalog_category_tree();
  for group_value in select value from jsonb_array_elements(operation.preview->'groups') loop
   perform 1 from private.goods_groups where id=(group_value->>'id')::uuid and revision=(group_value->>'revision')::bigint and archived_at is null for update nowait;
   if not found then raise sqlstate 'PT409' using message='goods_bulk_changed';end if;
  end loop;
  select array_agg(distinct id order by id) into lock_ids from (select unnest(ids) id union select private.goods_aggregation_owner(unnest(ids))) members;
  foreach id_value in array lock_ids loop
   if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||id_value,0)) then raise sqlstate 'PT409' using message='goods_bulk_busy';end if;
  end loop;
  perform 1 from public.goods where id=any(lock_ids) order by id for update nowait;
  perform 1 from public.goods_variants where good_id=any(ids) order by id for update nowait;
  perform 1 from private.goods_variant_price_periods where good_id=any(ids) order by id for update nowait;
  perform 1 from public.ips where id in(select ip_id from public.goods where id=any(ids)) order by id for update nowait;
  -- Recheck expiration after lock acquisition, and reject the entire batch if
  -- an option, stock, discount, membership or catalog value changed meanwhile.
  -- Discount commands guard prices, options and periods but not stock.
  if operation.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='goods_bulk_preview_expired';end if;
  -- A discount preview stored before this migration carries a full fingerprint
  -- and is rejected here as changed, which only asks the operator to re-review.
  if exists(select 1 from unnest(ids) id where (case when command in ('discount','discount_stop')
     then private.goods_bulk_price_fingerprint(id) else private.goods_bulk_fingerprint(id) end) is distinct from operation.guards->>id) then
   raise sqlstate 'PT409' using message='goods_bulk_changed';end if;
  if command='dissolve' then
   for group_value in select value from jsonb_array_elements(operation.preview->'groups') loop
    perform public.admin_archive_goods_group((group_value->>'id')::uuid,(group_value->>'revision')::bigint,
     md5('goods-bulk-group:'||p_id::text||':'||(group_value->>'id'))::uuid,p_actor,p_session);
   end loop;
  else
   for g in select * from public.goods where id=any(ids) and not id=any(skipped_ids) order by id loop
    if command='publish' then perform public.admin_set_good_published(g.id,true);
    elsif command='unpublish' then perform public.admin_set_good_published(g.id,false);
    elsif command='archive' then perform public.admin_archive_good(g.id);
    elsif command='restore' then perform public.admin_unarchive_good(g.id);
    elsif command in ('discount','discount_stop') then
     if command='discount' then
      for v in select * from public.goods_variants where good_id=g.id and archived_at is null order by id loop
       perform public.admin_save_goods_price_period(g.id,v.id,null,jsonb_build_object('state','active',
        'discountPrice',private.goods_bulk_price(v.price,values_doc),'startsAt',values_doc->'startsAt','endsAt',values_doc->'endsAt'),null);
      end loop;
     else
      for p in select * from private.goods_variant_price_periods where good_id=g.id and state='active' and ends_at>clock_timestamp() order by id loop
       perform public.admin_save_goods_price_period(g.id,p.variant_id,p.id,jsonb_build_object('state','disabled',
        'discountPrice',p.discount_price,'startsAt',p.starts_at,'endsAt',p.ends_at),p.revision);
      end loop;
      if values_doc->>'includeInstant'='true' and g.compare_at_price is not null and g.compare_at_price>g.price then
       select jsonb_agg(jsonb_build_object('id',id,'name',name,'attributes',attributes,'code',code,'extraPrice',price-g.price,
        'stockQty',stock_qty,'expectedStockQty',stock_qty,'isActive',archived_at is null,'lowStockThreshold',low_stock_threshold)
        order by is_default desc,sort_order,id) into options from public.goods_variants where good_id=g.id;
       select coalesce(jsonb_agg(id::text order by id),'[]') into baseline from public.goods_variants where good_id=g.id and archived_at is null;
       perform public.admin_save_good(to_jsonb(g)||jsonb_build_object('previous_id',g.id,'publish',null,'custom_inputs_expected_revision',g.custom_inputs_revision,
        'price',g.compare_at_price,'compare_at_price',null,'variants',options,'variant_baseline',baseline));
      end if;
     end if;
    else
     payload:=to_jsonb(g)||jsonb_build_object('previous_id',g.id,'publish',null,'custom_inputs_expected_revision',g.custom_inputs_revision);
     if command='start' then payload:=payload||'{"stock":"ok"}'::jsonb;
     elsif command='stop' then payload:=payload||'{"stock":"soldout"}'::jsonb;
     elsif command='period' then payload:=payload||jsonb_build_object('sale_period',values_doc||jsonb_build_object('expectedRevision',g.sale_period_revision));
     elsif command='price' then
      select jsonb_agg(jsonb_build_object('id',id,'name',name,'attributes',attributes,'code',code,'extraPrice',price-g.price,
       'stockQty',stock_qty,'expectedStockQty',stock_qty,'isActive',archived_at is null,'lowStockThreshold',low_stock_threshold)
       order by is_default desc,sort_order,id) into options from public.goods_variants where good_id=g.id;
      select coalesce(jsonb_agg(id::text order by id),'[]') into baseline from public.goods_variants where good_id=g.id and archived_at is null;
      payload:=payload||jsonb_build_object('price',private.goods_bulk_price(g.price,values_doc),'variants',options,'variant_baseline',baseline);
     end if;
     perform public.admin_save_good(payload);
    end if;
   end loop;
  end if;
  result:=jsonb_build_object('state','completed','operationId',p_id,'goodsCount',cardinality(ids)-cardinality(skipped_ids),'groupsCount',jsonb_array_length(operation.preview->'groups'),'error',null)
   ||case when command in ('discount','discount_stop') then jsonb_build_object('skipped',skipped) else '{}'::jsonb end;
  insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'catalog.goods_bulk.completed','goods_bulk:'||p_id::text,
   jsonb_build_object('request',operation.request,'preview',operation.preview,'receipt',result));
 exception when others then
  -- The subtransaction rolls back every product and child-operation change.
  -- Persist a terminal rejection so an uncertain network reply cannot replay it.
  get stacked diagnostics failure=message_text;
  result:=jsonb_build_object('state','rejected','operationId',p_id,'goodsCount',0,'groupsCount',0,
   'error',case when failure ~ '^[a-z][a-z0-9_]{0,100}$' then failure else 'goods_bulk_rejected' end);
 end;
 update private.goods_bulk_operations set receipt=result where id=p_id;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_commit_goods_import_group(target_batch uuid, target_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.require_operator_capability('catalog.manage',false);

  if auth.uid() is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='staff_required'; end if;
  if exists(select 1 from public.admin_goods_imports where id=target_batch and actor_id=auth.uid() and requires_admin)
    and not private.can_manage_goods_purchase_costs() then
    raise insufficient_privilege using message='purchase_cost_admin_required';
  end if;
  return private.admin_commit_goods_import_group_before_purchase_cost(target_batch,target_index);
end $function$

CREATE OR REPLACE FUNCTION public.admin_complete_shipments(target_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare shipment_key uuid;results jsonb:='[]'::jsonb;
begin
  perform private.require_operator_capability('sales.dispatch',false);

 if (select auth.uid()) is null or not public.has_operator_capability('sales.dispatch',false) then raise insufficient_privilege using message='staff required';end if;
 if cardinality(target_ids) is null or cardinality(target_ids) not between 1 and 1000 then raise invalid_parameter_value using message='invalid_shipment_selection';end if;
 perform private.lock_shipment_pack_scope(target_ids);
 perform o.id from public.orders o where exists(select 1 from public.order_shipments s where s.order_id=o.id and s.id=any(target_ids)) order by o.id for update;
 for shipment_key in select distinct id from unnest(target_ids) id order by id loop
  begin
   perform public.admin_update_shipment_status(shipment_key,'delivered',null,null);
   results:=results||jsonb_build_array(jsonb_build_object('id',shipment_key,'ok',true,'affectedIds',to_jsonb(private.shipment_pack_scope(array[shipment_key]))));
  exception when others then results:=results||jsonb_build_array(jsonb_build_object('id',shipment_key,'ok',false,'error',sqlerrm));end;
 end loop;
 return results;
end $function$

CREATE OR REPLACE FUNCTION public.admin_confirm_bank_transfer_deposit(p_order_id uuid, p_memo text)
 RETURNS public.payment_attempt_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_memo text := btrim(coalesce(p_memo, ''));
  v_order public.orders%rowtype;
  v_attempt public.payment_attempts%rowtype;
  v_claim_token uuid := extensions.gen_random_uuid();
  v_outcome public.payment_attempt_state;
begin
  perform private.require_operator_capability('sales.manage',false);

  if v_actor is null or not public.has_operator_capability('sales.manage',false) then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if char_length(v_memo) not between 5 and 200 then
    raise check_violation using message = 'invalid deposit memo';
  end if;

  -- 전역 잠금 순서: orders → payment_attempts → payments.
  select orders.* into v_order
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise no_data_found using message = 'order_not_found';
  end if;

  if v_order.payment_method is distinct from 'bank_transfer' then
    raise check_violation using message = 'order_not_bank_transfer';
  end if;

  if v_order.status is distinct from 'pending' then
    raise object_not_in_prerequisite_state using message = 'order_not_unpaid';
  end if;

  select attempt.* into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'order'
    and attempt.ref_id = v_order.id
    and attempt.provider = 'bank_transfer'
  for update;

  if not found then
    raise no_data_found using message = 'bank_transfer_attempt_not_found';
  end if;

  -- 만료 스윕이 이미 attempt를 닫았으면 여기서 멈춘다. finalizer는 종결 상태를
  -- 그대로 되돌려 주므로 그냥 부르면 "확인했는데 아무 일도 없다"가 된다.
  if v_attempt.state is distinct from 'prepared' then
    raise object_not_in_prerequisite_state using message = 'bank_transfer_attempt_not_confirmable';
  end if;

  update public.payment_attempts
  set
    state = 'confirming',
    claim_token = v_claim_token,
    claim_expires_at = now() + interval '5 minutes'
  where id = v_attempt.id;

  insert into public.bank_transfer_confirmations (order_id, attempt_id, confirmed_by, memo)
  values (v_order.id, v_attempt.id, v_actor, v_memo);

  v_outcome := public.finalize_goods_payment_attempt(
    v_attempt.id,
    v_claim_token,
    'approved',
    'bank_transfer:' || v_attempt.id::text,
    null,
    null,
    null,
    'bank_transfer',
    null,
    now()
  );

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.bank_transfer_confirmed',
    'order:' || v_order.id::text,
    jsonb_build_object(
      'attemptId', v_attempt.id,
      'amount', v_order.total,
      'depositCode', private.bank_transfer_deposit_code(v_order.id),
      'memo', v_memo,
      'outcome', v_outcome
    )
  );

  return v_outcome;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_confirm_claim_return_intake(p_rows jsonb, p_file_sha256 text, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); settings private.return_pickup_settings; prior private.claim_return_intake_imports; request_md5 text;
  matches jsonb; item record; outcome text; error_code text; results jsonb := '[]'::jsonb; recorded integer := 0; changed integer := 0;
  failed integer := 0; skipped integer := 0; recorded_bundles uuid[] := '{}'; result jsonb;
begin
  perform private.require_operator_capability('sales.manage', false);
  if actor is null or not public.has_operator_capability('sales.manage', false) then raise insufficient_privilege using message = 'staff required'; end if;
  select * into settings from private.return_pickup_settings where singleton;
  if not found or not settings.intake_enabled then raise check_violation using message = 'claim_return_intake_disabled'; end if;
  if p_operation is null or coalesce(p_file_sha256, '') !~ '^[0-9a-f]{64}$' or jsonb_typeof(p_rows) is distinct from 'array'
    or jsonb_array_length(p_rows) not between 1 and 1000
    or exists(select 1 from jsonb_array_elements(p_rows) r where jsonb_typeof(r) is distinct from 'object' or not (r ? 'bundleId')
      or (r->'bundleId' <> 'null'::jsonb and coalesce(r->>'bundleId', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')) then
    raise invalid_parameter_value using message = 'invalid_return_intake_rows'; end if;
  perform pg_advisory_xact_lock(hashtextextended('claim-return-intake:' || p_operation::text, 0));
  request_md5 := md5(jsonb_build_array(p_rows, p_file_sha256)::text);
  select * into prior from private.claim_return_intake_imports where id = p_operation;
  if found then
    if prior.actor_id <> actor or prior.request_md5 <> request_md5 then raise sqlstate 'PT409' using message = 'claim_return_intake_conflict'; end if;
    return prior.result || jsonb_build_object('replayed', true);
  end if;
  matches := private.claim_return_intake_match((select jsonb_agg(r.value - 'bundleId' order by r.ordinality) from jsonb_array_elements(p_rows) with ordinality r));
  for item in
    select m.value match, nullif(r.value->>'bundleId', '')::uuid expected
    from jsonb_array_elements(matches) m
    join jsonb_array_elements(p_rows) r on (r.value->>'rowNumber')::integer = (m.value->>'rowNumber')::integer
    order by m.value->>'orderId' nulls last, (m.value->>'rowNumber')::integer
  loop
    error_code := null;
    if item.expected is null then outcome := 'skipped'; skipped := skipped + 1;
    elsif item.match->>'status' <> 'matched' or (item.match->>'bundleId')::uuid <> item.expected then outcome := 'changed'; changed := changed + 1;
    else
      begin
        perform private.record_order_claim_collection_bundle((item.match->>'claimId')::uuid, null, item.expected,
          format('반품입고 회신 파일 SHA-256 %s · %s행', p_file_sha256, item.match->>'rowNumber'), (item.match->>'receivedOn')::date);
        outcome := 'recorded'; recorded := recorded + 1; recorded_bundles := recorded_bundles || item.expected;
      exception when others then
        outcome := 'failed'; failed := failed + 1;
        error_code := case when sqlerrm ~ '^[a-z][a-z0-9_]{1,63}$' then sqlerrm else 'unexpected' end;
      end;
    end if;
    results := results || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('rowNumber', (item.match->>'rowNumber')::integer, 'outcome', outcome,
      'status', item.match->>'status', 'errorCode', error_code, 'claimId', item.match->>'claimId', 'claimType', item.match->>'claimType',
      'claimReference', item.match->'claimReference', 'orderNumber', item.match->>'orderNumber', 'bundleId', item.match->>'bundleId',
      'returnLabel', item.match->>'returnLabel', 'receivedOn', item.match->>'receivedOn')));
  end loop;
  result := jsonb_build_object('operationId', p_operation, 'fileSha256', p_file_sha256, 'recorded', recorded, 'changed', changed, 'failed', failed,
    'skipped', skipped, 'rows', (select jsonb_agg(value order by (value->>'rowNumber')::integer) from jsonb_array_elements(results)), 'replayed', false);
  insert into private.claim_return_intake_imports(id, actor_id, file_sha256, request_md5, row_count, recorded, result)
  values (p_operation, actor, p_file_sha256, request_md5, jsonb_array_length(p_rows), recorded, result);
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.order.claim_return_intake_confirmed', 'claim_return_intake:' || p_operation,
    jsonb_build_object('operationId', p_operation, 'fileSha256', p_file_sha256, 'rows', jsonb_array_length(p_rows), 'recorded', recorded,
      'changed', changed, 'failed', failed, 'skipped', skipped, 'bundleIds', to_jsonb(recorded_bundles)));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_confirm_goods_group_conversion(p_preview_id uuid, p_operation_id uuid, p_expected_actor_id uuid, p_expected_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare preview private.goods_group_conversion_previews;prior private.goods_group_operations;
 source_good public.goods;source_variant public.goods_variants;cost private.goods_variant_purchase_costs;
 external_row private.goods_variant_external_identity;source_id text;first_variant_id uuid;first_price integer;
 group_id uuid:=gen_random_uuid();request_hash text;selection record;target_good_id text;target_variant_id uuid;
 members jsonb:='[]';new_ids text[]:='{}';target_name text;target_values text[];family_id uuid;v_receipt jsonb;before_stock bigint;after_stock bigint;
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 if p_preview_id is null or p_operation_id is null then raise invalid_parameter_value using message='invalid_goods_group_operation';end if;
 request_hash:=encode(extensions.digest(jsonb_build_array('convert',p_preview_id)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('goods-group-operation:'||p_operation_id::text,0));
 select * into prior from private.goods_group_operations where operation_id=p_operation_id;
 if found then
  if prior.actor_id<>p_expected_actor_id or prior.session_id<>p_expected_session_id or prior.command<>'convert'
   or prior.request_hash<>request_hash or prior.receipt is null then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  return prior.receipt;
 end if;
 select * into preview from private.goods_group_conversion_previews where id=p_preview_id for update;
 if not found or preview.actor_id<>p_expected_actor_id or preview.session_id<>p_expected_session_id then
  raise insufficient_privilege using message='goods_group_preview_unavailable';end if;
 if preview.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='goods_group_preview_expired';end if;
 source_id:=preview.request->>'sourceGoodId';
 perform private.goods_group_lock_conversion_source(source_id);
 if preview.source_hash is distinct from private.goods_group_source_hash(source_id)
  or cardinality(private.goods_group_conversion_blockers(source_id))>0 then
  raise sqlstate 'PT409' using message='goods_group_source_changed';end if;
 select * into source_good from public.goods where id=source_id;
 select sum(stock_qty::bigint) into before_stock from public.goods_variants where good_id=source_id;
 first_variant_id:=(preview.request#>>'{selections,0,variantId}')::uuid;
 select price into first_price from public.goods_variants where id=first_variant_id and good_id=source_id and archived_at is null;
 if first_price is null then raise sqlstate 'PT409' using message='goods_group_source_changed';end if;
 insert into private.goods_group_operations(operation_id,actor_id,session_id,command,request_hash)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,'convert',request_hash);
 insert into private.goods_group_write_authorizations(transaction_id,good_id,actor_id) values(txid_current(),source_id,p_expected_actor_id);
 -- Every resulting product is reviewed before publication, including the source
 -- whose name/options changed. Historical public slugs and first-publication dates remain.
 update public.goods set published_at=null where id=source_id;
 perform private.invalidate_goods_kc_review(source_id,'goods_group_converted');
 for selection in select value,ordinality from jsonb_array_elements(preview.request->'selections') with ordinality loop
  select * into source_variant from public.goods_variants where id=(selection.value->>'variantId')::uuid and good_id=source_id and archived_at is null;
  if not found then raise sqlstate 'PT409' using message='goods_group_source_changed';end if;
  target_values:=array(select jsonb_array_elements_text(selection.value->'values'));
  target_name:=preview.request->>'name'||' '||array_to_string(target_values,' / ');
  if selection.ordinality=1 then target_good_id:=source_id;target_variant_id:=first_variant_id;
  else
   target_good_id:=private.create_goods_group_product(source_id,source_variant.id,target_name,p_expected_actor_id);
   select id into target_variant_id from public.goods_variants where good_id=target_good_id and is_default and archived_at is null;
   if target_variant_id is null then raise check_violation using message='goods_group_result_missing';end if;
   new_ids:=array_append(new_ids,target_good_id);
   insert into private.goods_variant_price_periods(good_id,variant_id,state,regular_price,discount_price,starts_at,ends_at,created_by,updated_by,promotion_id)
    select target_good_id,target_variant_id,state,regular_price,discount_price,starts_at,ends_at,p_expected_actor_id,p_expected_actor_id,promotion_id
    from private.goods_variant_price_periods where variant_id=source_variant.id and state in('active','draft') order by id;
   select * into cost from private.goods_variant_purchase_costs where variant_id=source_variant.id;
   if found and cost.unit_cost_krw is not null then
    perform private.save_goods_variant_purchase_cost(target_good_id,target_variant_id,cost.unit_cost_krw,cost.tax_basis,null);
   end if;
   select * into external_row from private.goods_variant_external_identity where variant_id=source_variant.id for update;
   if found then
    insert into private.goods_group_external_identity_moves(source_variant_id,target_variant_id,operation_id,before_value,actor_id)
    values(source_variant.id,target_variant_id,p_operation_id,to_jsonb(external_row),p_expected_actor_id);
    delete from private.goods_variant_external_identity where variant_id=source_variant.id;
    insert into private.goods_variant_external_identity(variant_id,erp_code,erp_name,barcode)
     values(target_variant_id,external_row.erp_code,external_row.erp_name,external_row.barcode);
   end if;
   if source_variant.stock_qty>0 then
    perform private.change_goods_variant_stock(source_id,source_variant.id,-source_variant.stock_qty::bigint);
    perform private.change_goods_variant_stock(target_good_id,target_variant_id,source_variant.stock_qty::bigint);
   end if;
  end if;
  members:=members||jsonb_build_array(jsonb_build_object('sourceVariantId',source_variant.id,'goodId',target_good_id,'variantId',target_variant_id,
    'values',to_jsonb(target_values),'sortOrder',selection.ordinality-1,'movedQty',case when selection.ordinality=1 then 0 else source_variant.stock_qty end));
 end loop;
 family_id:=private.bind_goods_aggregation(source_id,new_ids,p_operation_id,p_expected_actor_id);
 update private.goods_variant_price_periods set state='disabled',updated_by=p_expected_actor_id,updated_at=clock_timestamp()
  where good_id=source_id and variant_id<>first_variant_id and state='active';
 -- No old option is physically deleted. Even unselected, never-ordered options
 -- retain their quantities and immutable identity for a later explicit decision.
 update public.goods_variants set is_default=false where good_id=source_id and is_default;
 update public.goods_variants set archived_at=coalesce(archived_at,clock_timestamp()) where good_id=source_id and id<>first_variant_id;
 update public.goods_variants set is_default=true,name='기본 옵션',attributes='{}',sort_order=0 where id=first_variant_id;
 update public.goods set name=preview.request->>'name'||' '||array_to_string(array(select jsonb_array_elements_text(preview.request#>'{selections,0,values}')),' / '),
  price=first_price,compare_at_price=case when source_good.compare_at_price is null then null else source_good.compare_at_price+(first_price-source_good.price) end
  where id=source_id;
 for selection in select value from jsonb_array_elements(members) loop
  if selection.value->>'goodId'<>source_id then
   perform private.record_goods_stock_successor(source_id,(selection.value->>'sourceVariantId')::uuid,selection.value->>'goodId',
    (selection.value->>'variantId')::uuid,p_operation_id,(selection.value->>'movedQty')::integer,p_expected_actor_id);
  end if;
 end loop;
 insert into private.goods_groups(id,name,option_names,common_good_id,created_by,updated_by)
 values(group_id,preview.request->>'name',array(select jsonb_array_elements_text(preview.request->'optionNames')),source_id,p_expected_actor_id,p_expected_actor_id);
 insert into private.goods_group_members(group_id,good_id,variant_id,option_values,sort_order)
 select group_id,m->>'goodId',(m->>'variantId')::uuid,array(select jsonb_array_elements_text(m->'values')),(m->>'sortOrder')::integer
 from jsonb_array_elements(members) m;
 select sum(stock_qty::bigint) into after_stock from public.goods_variants where good_id=any(array_append(new_ids,source_id));
 if before_stock is distinct from after_stock then raise check_violation using message='goods_group_stock_conservation_failed';end if;
 v_receipt:=jsonb_build_object('state','completed','operationId',p_operation_id,'group',private.goods_group_snapshot(group_id),'aggregationId',family_id);
 insert into private.goods_group_changes(group_id,operation_id,actor_id,revision,after_value)
 values(group_id,p_operation_id,p_expected_actor_id,1,v_receipt->'group');
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'catalog.goods_group.converted','goods_group:'||group_id::text,
  jsonb_build_object('sourceGoodId',source_id,'previewId',p_preview_id,'members',members,'stockBefore',before_stock,'stockAfter',after_stock,'aggregationId',family_id));
 update private.goods_group_operations set receipt=v_receipt,completed_at=clock_timestamp() where operation_id=p_operation_id;
 delete from private.goods_group_write_authorizations where transaction_id=txid_current() and actor_id=p_expected_actor_id and good_id=any(array_append(new_ids,source_id));
 return v_receipt;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_confirm_member_withdrawal_signin_block(target_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  processing private.member_withdrawal_processings;
  banned timestamptz;
  revoked integer;
  confirmed_at timestamptz;
begin
  perform private.lock_operator_subjects(array[actor, target_profile_id]);
  perform private.require_operator_capability('platform.manage', false);
  if target_profile_id is null then raise invalid_parameter_value using message = 'invalid_member_withdrawal'; end if;

  select * into processing from private.member_withdrawal_processings w where w.user_id = target_profile_id for update;
  if not found then raise no_data_found using message = 'member_withdrawal_not_processed'; end if;
  if processing.signin_blocked_at is not null then
    return private.member_withdrawal_document(target_profile_id) || jsonb_build_object('replayed', true, 'revokedSessions', 0);
  end if;

  select u.banned_until into banned from auth.users u where u.id = target_profile_id;
  if banned is null or banned < pg_catalog.clock_timestamp() + interval '50 years' then
    raise check_violation using message = 'member_withdrawal_signin_not_blocked';
  end if;

  revoked := private.revoke_member_auth_sessions(target_profile_id);
  confirmed_at := greatest(pg_catalog.clock_timestamp(), processing.processed_at);
  update private.member_withdrawal_processings
  set signin_blocked_at = confirmed_at, signin_blocked_by = actor
  where user_id = target_profile_id;
  insert into public.audit_log (actor_id, action, target, diff)
  values (actor, 'admin.member.withdrawal_signin_blocked', 'profile:' || target_profile_id::text,
    jsonb_build_object('inquiryReference', processing.inquiry_reference, 'revokedSessions', revoked));
  return private.member_withdrawal_document(target_profile_id) || jsonb_build_object('replayed', false, 'revokedSessions', revoked);
end $function$

CREATE OR REPLACE FUNCTION public.admin_convert_order_claim_type(p_claim_id uuid, p_operation_id uuid, p_expected_revision integer, p_to_type text, p_agreement text, p_confirmed boolean, p_refund_account jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();claim public.order_cancellation_requests;purchase public.orders;previous private.order_claim_type_changes;
 order_key uuid;buyer uuid;agreement text:=btrim(p_agreement);blocker text;account_digest text;field text;happened timestamptz;defective_plans_cleared integer:=0;stock_decisions_cleared integer:=0;
begin
 if not private.has_operator_capability(actor,'sales.manage',false) then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or p_to_type is null or p_to_type not in('return','exchange') or p_confirmed is distinct from true
  or agreement is null or char_length(agreement) not between 2 and 500 or agreement~'[[:cntrl:]]' then
  raise invalid_parameter_value using message='invalid_claim_conversion';end if;
 if p_refund_account is not null and p_refund_account<>'null'::jsonb then
  if p_to_type<>'return' or jsonb_typeof(p_refund_account) is distinct from 'object'
   or not(p_refund_account?&array['bankName','accountNumber','accountHolder'])
   or exists(select 1 from jsonb_object_keys(p_refund_account)k where k not in('bankName','accountNumber','accountHolder'))
   or exists(select 1 from jsonb_each(p_refund_account)x where jsonb_typeof(x.value)<>'string')
   or coalesce(p_refund_account->>'accountNumber','')!~'^[0-9-]{8,30}$' then raise invalid_parameter_value using message='invalid_claim_conversion_account';end if;
  foreach field in array array['bankName','accountHolder'] loop
   if p_refund_account->>field<>btrim(p_refund_account->>field) or char_length(p_refund_account->>field) not between 1 and 40
    or p_refund_account->>field~'[[:cntrl:]]' then raise invalid_parameter_value using message='invalid_claim_conversion_account';end if;
  end loop;
  account_digest:=encode(extensions.digest(p_refund_account::text,'sha256'),'hex');
 end if;
 select c.order_id,o.user_id into order_key,buyer from public.order_cancellation_requests c join public.orders o on o.id=c.order_id where c.id=p_claim_id;
 if order_key is null then raise no_data_found using message='claim_not_found';end if;
 perform private.lock_operator_subjects(array[actor,buyer]);
 perform private.require_actor_operator_capability(actor,'sales.manage',false);
 perform pg_advisory_xact_lock(hashtextextended('claim-type-change:'||p_operation_id::text,0));
 select * into previous from private.order_claim_type_changes where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision
   or previous.to_type<>p_to_type or previous.agreement<>agreement or previous.refund_account_digest is distinct from account_digest then
   raise unique_violation using message='claim_conversion_request_conflict';end if;
  return private.order_claim_type_change_receipt(p_operation_id,actor);
 end if;
 select * into purchase from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 perform shipment_id from public.order_claim_collections where claim_id=p_claim_id order by shipment_id for update;
 if claim.claim_revision<>p_expected_revision then raise sqlstate 'PT409' using message='claim_changed';end if;
 blocker:=private.order_claim_type_change_blocker(claim);
 if blocker is not null then raise check_violation using message=blocker;end if;
 if claim.claim_type=p_to_type then raise check_violation using message='claim_conversion_same_type';end if;
 -- Account purging takes only this row lock. Re-check after waiting for it, so
 -- a concurrent purge cannot turn a successful conversion into a missing account.
 perform claim_id from private.claim_refund_accounts where claim_id=p_claim_id for update;
 if p_to_type='return' and purchase.payment_method='bank_transfer' and purchase.total>0 and account_digest is null
  and not exists(select 1 from private.claim_refund_accounts where claim_id=p_claim_id and purged_at is null
   and bank_name is not null and account_number is not null and account_holder is not null) then
  raise check_violation using message='claim_conversion_account_required';end if;
 happened:=clock_timestamp();
 if account_digest is not null then
  insert into private.claim_refund_accounts(claim_id,bank_name,account_number,account_holder,masked_account,masked_holder)
  values(p_claim_id,p_refund_account->>'bankName',p_refund_account->>'accountNumber',p_refund_account->>'accountHolder',
   (p_refund_account->>'bankName')||' '||public.mask_refund_account_number(p_refund_account->>'accountNumber'),public.mask_refund_account_holder(p_refund_account->>'accountHolder'))
  on conflict(claim_id) do update set bank_name=excluded.bank_name,account_number=excluded.account_number,account_holder=excluded.account_holder,
   masked_account=excluded.masked_account,masked_holder=excluded.masked_holder,created_at=happened,purge_after=null,purged_at=null;
 elsif p_to_type='return' then
  update private.claim_refund_accounts set purge_after=null where claim_id=p_claim_id and purged_at is null;
 end if;
 if p_to_type='exchange' then
  update private.claim_refund_accounts set purge_after=coalesce(purge_after,happened+interval '30 days') where claim_id=p_claim_id and purged_at is null;
 end if;
 insert into private.order_claim_type_changes(id,claim_id,order_id,actor_id,expected_revision,from_type,to_type,agreement,refund_account_digest,from_stage,created_at)
 values(p_operation_id,p_claim_id,order_key,actor,p_expected_revision,claim.claim_type,p_to_type,agreement,account_digest,claim.stage,happened);
 update public.order_cancellation_requests set claim_type=p_to_type,updated_at=happened where id=p_claim_id;
 -- 반품 불량 재고(QNA-035): 이전 반품 단계에 저장한 '불량' 선택은 전환 뒤에 남기지 않는다. 다시 반품이 되면 기본(판매 재고 복원)부터 고른다.
 delete from private.claim_defective_stock where claim_id=p_claim_id and state='planned';
 get diagnostics defective_plans_cleared=row_count;
 -- 교환 회수 불량 재고(CLM-046): 교환 출고지의 재고 처리 결정도 같은 규칙이다. 다시 교환이 되면 결정부터 다시 한다.
 delete from private.claim_exchange_stock_decisions where claim_id=p_claim_id;
 get diagnostics stock_decisions_cleared=row_count;
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.order.claim_type_changed','order:'||order_key,
  jsonb_build_object('claimId',p_claim_id,'fromType',claim.claim_type,'toType',p_to_type,'customerConfirmed',true,'accountSupplied',account_digest is not null,'defectivePlanCleared',defective_plans_cleared,'stockDecisionCleared',stock_decisions_cleared));
 perform private.notify_order_claim(p_claim_id,'type_changed','반품·교환 요청이 변경됐어요',
  case when p_to_type='exchange' then '고객님과 확인한 반품 요청을 교환으로 변경했습니다. 기존 접수와 수거 이력은 유지됩니다.'
  else '고객님과 확인한 교환 요청을 반품으로 변경했습니다. 환불은 이후 승인·회수 확인 절차에 따라 별도로 처리됩니다.' end);
 return private.order_claim_type_change_receipt(p_operation_id,actor);
end $function$

