CREATE OR REPLACE FUNCTION public.admin_create_ip(target_public_slug text, target_title text, target_sub text, target_vertical_key text, target_tagline text, target_synopsis text, target_glyph text, target_bg text, target_image_path text, target_publish boolean DEFAULT NULL::boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  requested_slug text := pg_catalog.btrim(coalesce(target_public_slug, ''));
  requested_title text := pg_catalog.btrim(coalesce(target_title, ''));
  issued_id text;
  suffix integer := 1;
begin
  actor_id := private.require_operator_capability('platform.manage', false);

  if requested_slug !~ '^[a-z0-9](?:[a-z0-9-]{0,78}[a-z0-9])?$' or requested_slug = 'aouad' then
    raise invalid_parameter_value using message = 'invalid_ip_public_slug';
  end if;
  if requested_title = '' then
    raise invalid_parameter_value using message = 'invalid_ip_title';
  end if;
  if target_vertical_key is null
     or not exists (select 1 from public.verticals as vertical where vertical.key = target_vertical_key)
  then
    raise invalid_parameter_value using message = 'invalid_ip_vertical';
  end if;

  -- Slug, alias and ID checks share the identity lock with admin_update_ip_identity,
  -- the insert trigger and admin_delete_draft_ip.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ip_public_slug_identity', 0)
  );
  if exists (
    select 1 from public.ips as ip
    where ip.public_slug = requested_slug or ip.id = requested_slug
  ) or exists (
    select 1 from public.ip_public_slug_aliases as alias where alias.slug = requested_slug
  ) then
    raise unique_violation using message = 'ip_public_slug_taken';
  end if;

  issued_id := requested_slug;
  while exists (
    select 1 from public.ips as ip where ip.id = issued_id or ip.public_slug = issued_id
  ) or exists (
    select 1 from public.ip_public_slug_aliases as alias where alias.slug = issued_id
  ) or exists (
    select 1 from private.retired_ip_ids as retired where retired.id = issued_id
  ) loop
    suffix := suffix + 1;
    issued_id := requested_slug || '-' || suffix::text;
  end loop;

  perform pg_catalog.set_config('app.ip_public_slug_write', 'admin_create_ip', true);
  insert into public.ips (
    id, public_slug, title, sub, vertical_key, tagline, synopsis, glyph, bg, image_path, featured
  )
  values (
    issued_id, requested_slug, requested_title, target_sub, target_vertical_key,
    target_tagline, target_synopsis, target_glyph, target_bg, target_image_path, false
  );
  perform pg_catalog.set_config('app.ip_public_slug_write', '', true);

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'catalog.ip.upsert',
    'ips:' || issued_id,
    pg_catalog.jsonb_build_object(
      'id', issued_id,
      'title', requested_title,
      'vertical_key', target_vertical_key,
      'mode', 'create',
      'public_slug', requested_slug,
      'id_issued', true
    )
  );

  -- 게시 상태는 저장과 같은 transaction 에서 한 번만 전환하고 별도로 감사한다(admin_upsert_ip와 같다).
  if target_publish is not null then
    perform private.set_ip_published(issued_id, target_publish);
  end if;

  return issued_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_operator_invitations(p_entries jsonb, p_expected_access_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); state private.operator_access_state; entries jsonb; entry jsonb; request jsonb; result jsonb; ids uuid[]:='{}'; created_time timestamptz:=clock_timestamp();
begin
  if actor is null then raise insufficient_privilege using message='operator_capability_required'; end if;
  if p_operation_id is null or p_expected_access_revision is null or p_expected_access_revision<1 or jsonb_typeof(p_entries) is distinct from 'array' then raise invalid_parameter_value using message='invalid_operator_invitation'; end if;
  if jsonb_array_length(p_entries) not between 1 and 10 then raise invalid_parameter_value using message='operator_invitation_batch_limit'; end if;
  select jsonb_agg(private.normalize_operator_invitation(value) order by value->>'id') into entries from jsonb_array_elements(p_entries);
  if (select count(distinct value->>'email') from jsonb_array_elements(entries))<>jsonb_array_length(entries)
    or (select count(distinct value->>'id') from jsonb_array_elements(entries))<>jsonb_array_length(entries) then raise invalid_parameter_value using message='operator_invitation_duplicate'; end if;
  request:=jsonb_build_object('entriesDigest',encode(extensions.digest(entries::text,'sha256'),'hex'),'expectedAccessRevision',p_expected_access_revision);
  select * into strict state from private.operator_access_state where id for update;
  perform private.require_actor_operator_capability(actor,'operators.manage',true);
  result:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.operator.invited',request);
  if result is not null then return result; end if;
  if not state.configured then raise invalid_parameter_value using message='operator_setup_required'; end if;
  if state.revision<>p_expected_access_revision then raise sqlstate 'PT409' using message='operator_access_changed'; end if;
  for entry in select value from jsonb_array_elements(entries) loop ids:=array_append(ids,private.insert_operator_invitation(entry,actor,created_time)); end loop;
  update private.operator_access_state set revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id returning * into state;
  result:=jsonb_build_object('invitationIds',to_jsonb(ids),'count',cardinality(ids),'accessRevision',state.revision);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.operator.invited','operators',jsonb_build_object('request',request,'result',result));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_create_settled_export(p_request_id uuid, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 actor uuid:=(select auth.uid()); start_date date; end_date date; query_text text; date_basis text; search_field text; normalized jsonb;
 receipt private.settled_export_receipts; captured jsonb; order_count integer; item_count integer;
begin
  perform private.require_operator_capability('sales.manage',false);

 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required'; end if;
 if p_request_id is null or p_filters is null or jsonb_typeof(p_filters)<>'object'
  or exists(select 1 from jsonb_object_keys(p_filters) k where k not in('from','to','query','dateField','field')) then
  raise check_violation using message='settled_export_invalid_filters'; end if;
 if exists(select 1 from jsonb_each(p_filters) e where jsonb_typeof(e.value) not in('string','null')) then
  raise check_violation using message='settled_export_invalid_filters'; end if;
 begin
  if nullif(p_filters->>'from','') is not null then
   if (p_filters->>'from') !~ '^\d{4}-\d{2}-\d{2}$' then raise invalid_datetime_format; end if;
   start_date:=(p_filters->>'from')::date;
  end if;
  if nullif(p_filters->>'to','') is not null then
   if (p_filters->>'to') !~ '^\d{4}-\d{2}-\d{2}$' then raise invalid_datetime_format; end if;
   end_date:=(p_filters->>'to')::date;
  end if;
 exception when invalid_datetime_format or datetime_field_overflow then
  raise check_violation using message='settled_export_invalid_filters';
 end;
 date_basis:=coalesce(nullif(p_filters->>'dateField',''),'ordered');
 if date_basis not in ('ordered','paid','confirmed','shipped','delivered','settled') then raise check_violation using message='settled_export_invalid_filters';end if;
 search_field:=coalesce(nullif(p_filters->>'field',''),'all');
 if search_field not in('all','order','nickname','email','recipient','tracking','phone','product') then
  raise check_violation using message='settled_export_invalid_filters';end if;
 query_text:=nullif(btrim(p_filters->>'query'),'');
 if start_date>end_date or char_length(query_text)>100 then raise check_violation using message='settled_export_invalid_filters'; end if;
 normalized:=jsonb_build_object('from',start_date,'to',end_date,'query',coalesce(query_text,''));
 if date_basis<>'ordered' then normalized:=normalized||jsonb_build_object('dateField',date_basis);end if;
 if search_field<>'all' then normalized:=normalized||jsonb_build_object('field',search_field);end if;
 perform pg_advisory_xact_lock(hashtextextended('settled-export:'||actor::text||':'||p_request_id::text,0));
 select * into receipt from private.settled_export_receipts where actor_id=actor and request_id=p_request_id;
 if found then
  if receipt.filters<>normalized then raise check_violation using message='settled_export_request_conflict'; end if;
  return jsonb_build_object('id',receipt.id,'capturedAt',receipt.payload->>'capturedAt','orderCount',jsonb_array_length(receipt.payload->'orders'));
 end if;
 -- This STABLE SQL function uses one statement snapshot for every source table.
 captured:=private.collect_settled_export_for_search(start_date,end_date,query_text,date_basis,search_field);
 order_count:=jsonb_array_length(captured->'orders');
 select coalesce(sum(jsonb_array_length(value->'items')),0) into item_count from jsonb_array_elements(captured->'orders');
 if order_count=0 then raise check_violation using message='settled_export_empty'; end if;
 if order_count>1000 or item_count>10000 then raise check_violation using message='settled_export_limit'; end if;
 insert into private.settled_export_receipts(actor_id,request_id,filters,payload)
 values(actor,p_request_id,normalized,captured||jsonb_build_object('filters',normalized)) returning * into receipt;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.settled_export.created','settled_export:'||receipt.id,
  jsonb_build_object('filters',normalized,'orderCount',order_count,'itemCount',item_count,'capturedAt',captured->>'capturedAt'));
 return jsonb_build_object('id',receipt.id,'capturedAt',captured->>'capturedAt','orderCount',order_count);
end $function$

CREATE OR REPLACE FUNCTION public.admin_cs_reply_context(p_surface text, p_target_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  perform private.require_operator_capability('cs.manage',false);
  if p_surface is null or p_surface not in('product_question','review') or p_target_id is null then
    raise invalid_parameter_value using message='invalid_cs_reply_target'; end if;
  if p_surface='product_question' then
    select jsonb_build_object('id',id,'surface',p_surface,'body',body,'reply',answer_body,'replyAt',answered_at,
      'status',status,'revision',reply_source_revision::text) into result from public.product_questions where id=p_target_id;
  else
    select jsonb_build_object('id',id,'surface',p_surface,'body',body,'reply',admin_reply,'replyAt',admin_reply_at,
      'status',status,'revision',reply_source_revision::text,'rating',rating,'imagePaths',image_paths)
      into result from public.reviews where id=p_target_id;
  end if;
  if result is null then raise no_data_found using message='cs_reply_target_not_found'; end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_cs_reply_operation(p_operation_id uuid, p_actor_id uuid, p_surface text, p_target_id uuid, p_body text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; previous private.cs_reply_operations;
begin
  actor:=private.require_operator_capability('cs.manage',false);
  if actor is distinct from p_actor_id then raise insufficient_privilege using message='cs_reply_account_changed'; end if;
  if p_operation_id is null or p_target_id is null or p_surface is null or p_surface not in('product_question','review')
    or p_expected_revision is null or p_expected_revision<0 or p_body is null then
    raise invalid_parameter_value using message='invalid_cs_reply_request'; end if;
  select * into previous from private.cs_reply_operations where operation_id=p_operation_id;
  -- A read does not reveal another actor's receipt, even for a guessed UUID.
  if not found or previous.actor_id<>actor then return null; end if;
  if previous.surface<>p_surface or previous.target_id<>p_target_id or previous.expected_revision<>p_expected_revision
    or previous.body<>btrim(p_body,E' \t\n\r\f\v') then raise sqlstate 'PT409' using message='cs_reply_operation_changed'; end if;
  return previous.result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_customer_segment_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare at_value timestamptz:=statement_timestamp(); interested_count bigint; buyer_count bigint; loyal_count bigint; first_count bigint; visitor_count bigint; potential_count bigint;
begin
 if not public.has_operator_capability('marketing.manage') then raise insufficient_privilege using message='operator_capability_required';end if;
 if (select enabled from private.member_activity_settings where singleton) then
  select count(*) into visitor_count from private.customer_segment_members('{"version":1,"target":"visited"}',at_value);
  select count(*) into potential_count from private.customer_segment_members('{"version":1,"target":"not_visited"}',at_value);
 end if;
 select count(*) into first_count from private.customer_segment_members('{"version":1,"target":"first_purchase"}',at_value);
 select count(*) into buyer_count from private.customer_segment_members('{"version":1,"target":"purchased"}',at_value);
 select count(*) into loyal_count from private.customer_segment_members('{"version":1,"target":"repeat_purchase"}',at_value);
 select count(distinct customer_id) into interested_count from (
  select customer_id from private.customer_segment_members('{"version":1,"target":"cart_unpurchased"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"wishlist_unpurchased"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"unused_coupon"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"ip_notifications"}',at_value)
 ) interested;
 if (select enabled from private.member_activity_settings where singleton) then
 select count(distinct customer_id) into interested_count from (
  select customer_id from private.customer_segment_members('{"version":1,"target":"cart_unpurchased"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"wishlist_unpurchased"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"unused_coupon"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"ip_notifications"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"product_viewed"}',at_value)
  union all select customer_id from private.customer_segment_members('{"version":1,"target":"video_viewed"}',at_value)
 ) interested;
 end if;
 return jsonb_build_object('checkedAt',at_value,'groups',jsonb_build_object('potential',potential_count,'visitor',visitor_count,'interested',interested_count,'buyer',buyer_count,'loyal',loyal_count),
  'firstPurchaseMembers',first_count,'memberCount',first_count+buyer_count);
end $function$

CREATE OR REPLACE FUNCTION public.admin_decide_order_cancellation(p_request_id uuid, p_decision text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_order_id uuid;
  v_order_status public.order_status;
  v_delivered_at timestamptz;
  v_request record;
  v_payment_count integer;
begin
  perform private.require_operator_capability('sales.manage',false);

  if v_actor is null or not public.has_operator_capability('sales.manage',false) then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if p_decision not in ('approve', 'reject') then
    raise check_violation using message = 'invalid cancellation decision';
  end if;

  select request.order_id
  into v_order_id
  from public.order_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'cancellation_request_not_found';
  end if;

  select orders.status, orders.delivered_at
  into v_order_status, v_delivered_at
  from public.orders
  where orders.id = v_order_id
  for update;

  perform s.id from public.order_shipments s where s.order_id=v_order_id order by s.id for update;

  select request.*
  into v_request
  from public.order_cancellation_requests as request
  where request.id = p_request_id
  for update;

  if v_request.status <> 'requested' then
    raise exception using message = 'cancellation_request_not_decidable';
  end if;

  -- status만으로는 부족하다. 새 stage는 전부 'requested'로 투영된다.
  if v_request.claim_type <> 'cancel' or v_request.stage <> 'requested' then
    raise exception using message = 'claim_requires_claim_console';
  end if;

  if v_order_status not in (
    'pending', 'paid', 'confirmed', 'shipping', 'delivered', 'done'
  ) then
    raise exception using message = 'order_not_cancelable';
  end if;

  if p_decision = 'reject' then
    if p_note is null
      or btrim(p_note) <> p_note
      or length(p_note) not between 10 and 200
    then
      raise check_violation using message = 'invalid rejection reason';
    end if;

    update public.order_cancellation_requests
    set
      status = 'rejected',
      decided_by = v_actor,
      decision_note = p_note,
      decided_at = now(),
      updated_at = now()
    where id = p_request_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_actor,
      'admin.order.cancellation_rejected',
      'order:' || v_order_id::text,
      jsonb_build_object(
        'requestId', p_request_id,
        'from', 'requested',
        'to', 'rejected',
        'reason', p_note
      )
    );
    return;
  end if;

  if not private.order_cancel_eligible(v_order_id) then raise exception using message='order_not_cancelable'; end if;

  if public.order_withdrawal_deadline_passed(
    v_delivered_at,
    v_request.reason_type,
    v_request.requested_at
  ) then
    raise check_violation using message = 'withdrawal_deadline_expired';
  end if;

  insert into public.order_cancellation_claims (
    order_id,
    requested_by,
    previous_status
  )
  values (
    v_order_id,
    v_request.requested_by,
    v_order_status
  )
  on conflict (order_id) do nothing;

  insert into public.refunds (
    payment_id,
    amount,
    reason,
    status,
    cancellation_request_id
  )
  select
    payment.id,
    payment.amount - private.payment_partial_refunded_amount(payment.id),
    v_request.reason,
    case when refund.status = 'done' then 'done' else 'requested' end,
    p_request_id
  from public.payments as payment
  left join public.refunds as refund on refund.payment_id = payment.id
  where payment.purpose = 'order'
    and payment.ref_id = v_order_id
    and payment.status in ('pending', 'paid', 'canceled', 'refunded')
  on conflict (payment_id) do update
  set
    cancellation_request_id = excluded.cancellation_request_id,
    reason = coalesce(public.refunds.reason, excluded.reason),
    status = case
      when public.refunds.status = 'done' then 'done'
      else 'requested'
    end;

  select count(*)::integer
  into v_payment_count
  from public.payments as payment
  where payment.purpose = 'order'
    and payment.ref_id = v_order_id
    and payment.status in ('pending', 'paid', 'canceled', 'refunded');

  update public.order_cancellation_requests
  set
    status = 'processing',
    decided_by = v_actor,
    decision_note = null,
    decided_at = now(),
    provider_started_at = now(),
    updated_at = now()
  where id = p_request_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.cancellation_approved',
    'order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'from', 'requested',
      'to', 'processing',
      'previousOrderStatus', v_order_status::text,
      'reasonType', v_request.reason_type,
      'paymentCount', v_payment_count
    )
  );
end;
$function$

