CREATE OR REPLACE FUNCTION public.admin_delete_draft_ip(target_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  ip_row public.ips;
  readiness jsonb;
  deletion_audit_id uuid;
begin
  -- 되돌릴 수 없는 물리 삭제라 legacy 운영에서는 admin만, 설정된 운영자 권한에서는 platform.manage만 연다.
  actor_id := private.require_operator_capability('platform.manage', true);
  if target_id is null or target_id !~ '^[a-z0-9][a-z0-9-]*$' then
    raise invalid_parameter_value using message = 'invalid_ip_id';
  end if;

  -- Identity lock first, then the row lock (same order as admin_update_ip_identity).
  -- The row lock blocks concurrent FK inserts (FOR KEY SHARE) and publish/archive writers.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ip_public_slug_identity', 0)
  );
  select * into ip_row from public.ips as ip where ip.id = target_id for update of ip;
  if not found then
    -- A replay after a successful delete is a no-op, not a new audit event.
    if exists (select 1 from private.retired_ip_ids as retired where retired.id = target_id) then
      return false;
    end if;
    raise no_data_found using message = 'catalog_not_found';
  end if;

  readiness := private.ip_delete_readiness(target_id);
  if readiness ->> 'state' <> 'draft' then
    raise check_violation using message = 'ip_not_draft';
  end if;
  if (readiness ->> 'publicHistory')::boolean then
    raise check_violation using message = 'ip_has_public_history';
  end if;
  if (readiness ->> 'referenceTotal')::bigint <> 0 then
    raise check_violation using message = 'ip_has_references';
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'catalog.ip.deleted',
    'ips:' || target_id,
    pg_catalog.jsonb_build_object(
      'snapshot', pg_catalog.to_jsonb(ip_row),
      'aliases', readiness -> 'aliases',
      'references', readiness -> 'references',
      'public_history', false,
      'retired_id', target_id
    )
  )
  returning id into deletion_audit_id;

  insert into private.retired_ip_ids (id, public_slug, retired_by, audit_log_id)
  values (target_id, ip_row.public_slug, actor_id, deletion_audit_id);

  delete from public.ip_public_slug_aliases where ip_id = target_id;
  delete from public.ips where id = target_id;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_erp_items(p_codes text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_requested integer;
  v_deleted integer;
  v_items jsonb;
begin
  perform private.require_operator_capability('platform.manage',false);

  if v_actor is null or not public.has_operator_capability('platform.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if p_codes is null
     or pg_catalog.cardinality(p_codes) not between 1 and 500
     or exists (select 1 from pg_catalog.unnest(p_codes) as requested(code) where requested.code is null) then
    raise invalid_parameter_value using message = 'invalid_erp_item_codes';
  end if;
  select pg_catalog.count(distinct requested.code)::integer into v_requested
  from pg_catalog.unnest(p_codes) as requested(code);

  -- 반입과 같은 잠금으로 직렬화해 지우는 중인 코드가 동시에 다시 반입되며 섞이지 않게 한다.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.erp_items.import', 0));

  with deleted as (
    delete from public.erp_items as item
    where item.code = any(p_codes)
    returning item.code, item.name, item.category, item.sale_price, item.barcode, item.imported_at, item.imported_by
  )
  select
    pg_catalog.count(*)::integer,
    coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'code', deleted.code,
      'name', deleted.name,
      'category', deleted.category,
      'sale_price', deleted.sale_price,
      'barcode', deleted.barcode,
      'imported_at', deleted.imported_at,
      'imported_by', deleted.imported_by
    ) order by deleted.code), '[]'::jsonb)
  into v_deleted, v_items
  from deleted;

  if v_deleted > 0 then
    insert into public.audit_log (actor_id, action, target, diff)
    values (v_actor, 'admin.erp_items.deleted', 'erp_items', pg_catalog.jsonb_build_object(
      'requested', v_requested,
      'deleted', v_deleted,
      'items', v_items));
  end if;

  return pg_catalog.jsonb_build_object(
    'requested', v_requested,
    'deleted', v_deleted,
    'missing', v_requested - v_deleted);
end;
$function$

