CREATE OR REPLACE FUNCTION public.admin_grant_draw_tickets_unguarded(target_operation_id uuid, target_profile_id uuid, target_pool_id uuid, target_quantity integer, target_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_reason text;
  requested_diff jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  recipient record;
  pool_record public.card_pools%rowtype;
  pool_is_ready boolean := false;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  -- 발급 정책 콘솔과 같은 권한선을 쓴다. staff는 이미 조건 없는 자동 발급 정책을 만들 수
  -- 있으므로 수동 발급만 admin으로 좁히는 것은 실질 방어가 되지 않는다. 대신 수량 상한과
  -- 감사 기록으로 막는다.
  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if target_quantity is null or target_quantity not between 1 and 10 then
    raise exception 'invalid_grant_quantity' using errcode = '22023';
  end if;

  normalized_reason := btrim(coalesce(target_reason, ''), E' \t\n\r\f\v');
  if char_length(normalized_reason) < 1 or char_length(normalized_reason) > 200 then
    raise exception 'invalid_grant_reason' using errcode = '22023';
  end if;

  -- 응답이 유실된 재시도는 먼저 커밋된 감사 기록을 관측한 뒤에 판단해야 한다.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_draw_ticket_grant:' || target_operation_id::text, 0)
  );

  requested_diff := jsonb_build_object(
    'poolId', target_pool_id,
    'quantity', target_quantity,
    'reason', normalized_reason
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.draw_ticket.granted'
      and existing_target = 'profiles:' || target_profile_id::text
      and existing_diff = requested_diff
    then
      return (existing_diff ->> 'quantity')::integer;
    end if;

    raise exception 'grant_conflict' using errcode = '23505';
  end if;

  select profile.id, profile.suspended_at
    into recipient
  from public.profiles as profile
  where profile.id = target_profile_id
  for key share;

  if not found then
    raise exception 'profile_not_found' using errcode = 'P0002';
  end if;

  -- 정지 계정은 개봉 자체가 막혀 있다(trg_draw_tickets_active_consumption).
  -- 열 수 없는 티켓을 쌓아두지 않는다.
  if recipient.suspended_at is not null then
    raise exception 'recipient_suspended' using errcode = '55000';
  end if;

  select pool.*
    into pool_record
  from public.card_pools as pool
  where pool.id = target_pool_id
  for share;

  if not found then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  if pool_record.active_to is not null and now() >= pool_record.active_to then
    raise exception 'reward_pool_not_ready' using errcode = '55000';
  end if;

  -- 발급 정책 콘솔과 같은 준비 판정이다. 확률 합이 100%가 아니거나 확률이 양수인 등급에
  -- 카드가 없으면 개봉이 'pool has no card of rarity'로 실패한다 — 열 수 없는 티켓을
  -- 만들지 않는다.
  select
    count(*) = 5
    and coalesce(sum(pool_odd.probability), 0) = 1
    and coalesce(bool_and(pool_odd.probability between 0 and 1), false)
    and not exists (
      select 1
      from public.pool_odds as positive_odd
      where positive_odd.pool_id = target_pool_id
        and positive_odd.probability > 0
        and not exists (
          select 1
          from public.cards as card
          where card.pool_id = target_pool_id
            and card.rarity = positive_odd.rarity
        )
    )
    into pool_is_ready
  from public.pool_odds as pool_odd
  where pool_odd.pool_id = target_pool_id;

  if not pool_is_ready then
    raise exception 'reward_pool_not_ready' using errcode = '55000';
  end if;

  -- source_id = operation_id 라서 unique (source, source_id, ordinal)이 재시도 이중 발급을
  -- DB 레벨에서 한 번 더 막는다. reward_policy_id는 비워 정책 집계와 분리한다.
  insert into public.draw_tickets (
    user_id,
    pool_id,
    source,
    source_id,
    ordinal
  )
  select
    target_profile_id,
    target_pool_id,
    'admin_grant',
    target_operation_id,
    grant_series.n
  from generate_series(1, target_quantity) as grant_series(n)
  on conflict (source, source_id, ordinal) do nothing;

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.draw_ticket.granted',
    'profiles:' || target_profile_id::text,
    requested_diff
  );

  return target_quantity;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_grant_draw_tickets(target_operation_id uuid, target_profile_id uuid, target_pool_id uuid, target_quantity integer, target_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  perform private.lock_operator_subjects(array[(select auth.uid()),target_profile_id]);
  perform private.require_operator_capability('platform.manage',false);

  perform private.require_card_rewards_enabled();
  return public.admin_grant_draw_tickets_unguarded(
    target_operation_id,
    target_profile_id,
    target_pool_id,
    target_quantity,
    target_reason
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_hide_community_comment(target_comment_id uuid, target_report_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := auth.uid();
  previous_status public.post_status;
  target_ip_id text;
  target_post_id uuid;
  linked_report_target public.report_target;
  linked_report_target_id text;
  linked_report_status public.report_status;
begin
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null or not public.has_operator_capability('platform.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select comments.post_id
    into target_post_id
    from public.comments
    where comments.id = target_comment_id;

  if not found then
    raise exception 'comment_not_found' using errcode = '22023';
  end if;

  select posts.ip_id
    into target_ip_id
    from public.posts
    where posts.id = target_post_id
    for update;

  if not found then
    raise exception 'comment_not_found' using errcode = '22023';
  end if;

  select comments.status
    into previous_status
    from public.comments
    where comments.id = target_comment_id
      and comments.post_id = target_post_id
    for update;

  if not found then
    raise exception 'comment_not_found' using errcode = '22023';
  end if;

  if target_report_id is not null then
    select reports.target_type, reports.target_id, reports.status
      into linked_report_target, linked_report_target_id, linked_report_status
      from public.reports
      where reports.id = target_report_id
      for update;

    if not found then
      raise exception 'report_not_found' using errcode = '22023';
    end if;

    if linked_report_target <> 'comment'
      or linked_report_target_id <> target_comment_id::text then
      raise exception 'report_target_mismatch' using errcode = '22023';
    end if;
  end if;

  if previous_status = 'hidden' then
    if target_report_id is not null and linked_report_status <> 'resolved' then
      raise exception 'comment_already_hidden' using errcode = '22023';
    end if;

    return jsonb_build_object('ipId', target_ip_id);
  end if;

  update public.comments
  set status = 'hidden'
  where id = target_comment_id;

  if target_report_id is not null then
    update public.reports
    set status = 'resolved'
    where id = target_report_id;
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'community_comment_hide',
    'comment:' || target_comment_id::text,
    jsonb_build_object(
      'from', previous_status,
      'to', 'hidden',
      'reportId', target_report_id
    )
  );

  return jsonb_build_object('ipId', target_ip_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_hide_community_post(target_post_id uuid, target_report_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := auth.uid();
  previous_status post_status;
  target_ip_id text;
  linked_report_target report_target;
  linked_report_target_id text;
  linked_report_post_id uuid;
begin
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null or not public.has_operator_capability('platform.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select posts.status, posts.ip_id
    into previous_status, target_ip_id
    from public.posts
    where posts.id = target_post_id
    for update;

  if not found then
    raise exception 'post_not_found' using errcode = '22023';
  end if;

  update public.posts
  set status = 'hidden'
  where posts.id = target_post_id;

  if target_report_id is not null then
    select reports.target_type, reports.target_id
      into linked_report_target, linked_report_target_id
      from public.reports
      where reports.id = target_report_id
      for update;

    if not found then
      raise exception 'report_not_found' using errcode = '22023';
    end if;

    if linked_report_target = 'post' then
      if linked_report_target_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        raise exception 'report_target_mismatch' using errcode = '22023';
      end if;

      linked_report_post_id := linked_report_target_id::uuid;
    elsif linked_report_target = 'comment' then
      if linked_report_target_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        raise exception 'report_target_mismatch' using errcode = '22023';
      end if;

      select comments.post_id
        into linked_report_post_id
        from public.comments
        where comments.id = linked_report_target_id::uuid;

      if not found then
        raise exception 'report_target_mismatch' using errcode = '22023';
      end if;
    else
      /* 'user'와 'review'가 여기로 온다. 둘 다 포스트 숨김으로는 해소되지 않는다. */
      raise exception 'report_target_mismatch' using errcode = '22023';
    end if;

    if linked_report_post_id <> target_post_id then
      raise exception 'report_target_mismatch' using errcode = '22023';
    end if;

    update public.reports
    set status = 'resolved'
    where reports.id = target_report_id;
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'community_post_hide',
    'post:' || target_post_id::text,
    jsonb_build_object('from', previous_status, 'to', 'hidden', 'reportId', target_report_id)
  );

  return jsonb_build_object('ipId', target_ip_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_ignore_bank_deposit(p_deposit_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  perform private.require_operator_capability('sales.manage',false);

  if v_actor is null or not public.has_operator_capability('sales.manage',false) then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if char_length(v_reason) not between 5 and 200 then
    raise check_violation using message = 'invalid ignore reason';
  end if;

  update public.bank_deposits
  set
    status = 'ignored',
    decided_by = v_actor,
    decision_note = v_reason
  where id = p_deposit_id
    and status = 'unmatched';

  if not found then
    raise no_data_found using message = 'deposit_not_ignorable';
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.bank_deposit.ignored',
    'bank_deposit:' || p_deposit_id::text,
    jsonb_build_object('reason', v_reason)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_import_erp_items(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_row record;
  v_existing public.erp_items;
  v_category text;
  v_sale_price integer;
  v_barcode text;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_unchanged integer := 0;
  v_rejected jsonb[] := array[]::jsonb[];
  v_changed_codes text[] := array[]::text[];
  v_now timestamptz := pg_catalog.now();
begin
  perform private.require_operator_capability('catalog.manage',false);

  if v_actor is null or not public.has_operator_capability('catalog.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if p_rows is null
     or pg_catalog.jsonb_typeof(p_rows) <> 'array'
     or pg_catalog.jsonb_array_length(p_rows) not between 1 and 5000 then
    raise invalid_parameter_value using message = 'invalid_erp_item_rows';
  end if;

  -- 같은 ERP 코드를 다른 순서로 잠그는 동시 반입끼리 교착하지 않도록 반입을 직렬화한다.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.erp_items.import', 0));

  for v_row in
    with input as (
      select element.value as item, element.ordinality::integer as ord
      from pg_catalog.jsonb_array_elements(p_rows) with ordinality as element(value, ordinality)
    ), normalized as (
      select
        input.ord,
        case
          when pg_catalog.jsonb_typeof(input.item -> 'row') = 'number'
            and (input.item ->> 'row') ~ '^[0-9]{1,9}$'
          then (input.item ->> 'row')::integer
          else input.ord
        end as source_row,
        case
          when pg_catalog.jsonb_typeof(input.item -> 'code') = 'string'
          then pg_catalog.left(
            pg_catalog.regexp_replace(input.item ->> 'code', '[\u0001-\u001f\u007f-\u009f]', ' ', 'g'), 120)
        end as raw_code,
        normalized_row.*
      from input
      cross join lateral private.normalize_erp_item_row(input.item) as normalized_row
    )
    select
      normalized.*,
      coalesce(
        normalized.o_reason is null
          and normalized.ord < pg_catalog.max(normalized.ord)
            filter (where normalized.o_reason is null)
            over (partition by normalized.o_code),
        false
      ) as superseded
    from normalized
    order by normalized.ord
  loop
    if v_row.o_reason is not null or v_row.superseded then
      v_rejected := pg_catalog.array_append(v_rejected, pg_catalog.jsonb_build_object(
        'row', v_row.source_row,
        'code', coalesce(v_row.o_code, v_row.raw_code),
        'reason', coalesce(v_row.o_reason, 'duplicate_code')));
      continue;
    end if;

    select * into v_existing
    from public.erp_items as item
    where item.code = v_row.o_code
    for update;

    if not found then
      insert into public.erp_items (code, name, category, sale_price, barcode, imported_at, imported_by, updated_at)
      values (v_row.o_code, v_row.o_name, v_row.o_category, v_row.o_sale_price, v_row.o_barcode, v_now, v_actor, v_now);
      v_inserted := v_inserted + 1;
      if pg_catalog.cardinality(v_changed_codes) < 100 then
        v_changed_codes := pg_catalog.array_append(v_changed_codes, v_row.o_code);
      end if;
      continue;
    end if;

    v_category := case when v_row.o_has_category then v_row.o_category else v_existing.category end;
    v_sale_price := case when v_row.o_has_sale_price then v_row.o_sale_price else v_existing.sale_price end;
    v_barcode := case when v_row.o_has_barcode then v_row.o_barcode else v_existing.barcode end;

    if (v_existing.name, v_existing.category, v_existing.sale_price, v_existing.barcode)
       is not distinct from (v_row.o_name, v_category, v_sale_price, v_barcode) then
      v_unchanged := v_unchanged + 1;
    else
      update public.erp_items as item
      set name = v_row.o_name,
          category = v_category,
          sale_price = v_sale_price,
          barcode = v_barcode,
          imported_at = v_now,
          imported_by = v_actor,
          updated_at = v_now
      where item.code = v_row.o_code;
      v_updated := v_updated + 1;
      if pg_catalog.cardinality(v_changed_codes) < 100 then
        v_changed_codes := pg_catalog.array_append(v_changed_codes, v_row.o_code);
      end if;
    end if;
  end loop;

  insert into public.audit_log (actor_id, action, target, diff)
  values (v_actor, 'admin.erp_items.imported', 'erp_items', pg_catalog.jsonb_build_object(
    'rows', pg_catalog.jsonb_array_length(p_rows),
    'inserted', v_inserted,
    'updated', v_updated,
    'unchanged', v_unchanged,
    'rejected', pg_catalog.cardinality(v_rejected),
    'changed_codes', pg_catalog.to_jsonb(v_changed_codes),
    'changed_codes_truncated', v_inserted + v_updated > pg_catalog.cardinality(v_changed_codes)));

  return pg_catalog.jsonb_build_object(
    'inserted', v_inserted,
    'updated', v_updated,
    'unchanged', v_unchanged,
    'rejected', pg_catalog.to_jsonb(v_rejected));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_import_item_tracking_batch(target_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare input jsonb; normalized jsonb:='[]'; result jsonb; number text; item_id uuid;
begin
  perform private.require_operator_capability('sales.dispatch',false);
  if jsonb_typeof(target_rows) is distinct from 'array' or jsonb_array_length(target_rows) not between 1 and 1000 then
    raise invalid_parameter_value using message='invalid_tracking_batch';end if;
  for input in select value from jsonb_array_elements(target_rows) loop
    number:=case when jsonb_typeof(input->'reference')='string' then btrim(input->>'reference') end;
    if private.is_commerce_number(number,2::smallint) then
      select id into item_id from public.order_items where product_order_number=number;
      -- Leave unresolved numbers unchanged: the identity guard rejects the
      -- whole batch, including valid siblings, before delegating any writes.
      if item_id is not null then input:=jsonb_set(input,'{reference}',to_jsonb(item_id::text));end if;
    end if;
    normalized:=normalized||jsonb_build_array(input);
  end loop;
  result:=private.admin_import_item_tracking_batch_before_numbers(normalized);
  if jsonb_typeof(result) is distinct from 'array' or jsonb_array_length(result)<>jsonb_array_length(target_rows) then
    raise check_violation using message='tracking_batch_result_missing';end if;
  return (select jsonb_agg(outcome.value||case when jsonb_typeof(target_rows->(outcome.ordinality::integer-1)->'reference')='string'
      then jsonb_build_object('reference',btrim(target_rows->(outcome.ordinality::integer-1)->>'reference')) else '{}'::jsonb end order by outcome.ordinality)
    from jsonb_array_elements(result) with ordinality outcome(value,ordinality));
end $function$

CREATE OR REPLACE FUNCTION public.admin_import_seowon_tracking_batch(target_origin_id uuid, target_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare origin public.fulfillment_origins;row_value jsonb;sid uuid;ids uuid[]:='{}';scope_ids uuid[];
 shipment public.order_shipments;tracking_value text;carrier_value text;
begin
 perform private.require_operator_capability('sales.dispatch',false);
 if target_origin_id is null or jsonb_typeof(target_rows) is distinct from 'array'
  or jsonb_array_length(target_rows) not between 1 and 1000 then raise invalid_parameter_value using message='invalid_tracking_batch';end if;
 select * into origin from public.fulfillment_origins where id=target_origin_id;
 if not found then raise no_data_found using message='warehouse_origin_not_found';end if;
 if not origin.is_active or origin.export_template<>'seowon_xlsx' then raise check_violation using message='warehouse_origin_unavailable';end if;
 for row_value in select value from jsonb_array_elements(target_rows) loop
  if jsonb_typeof(row_value) is distinct from 'object' or jsonb_typeof(row_value->'reference') is distinct from 'string'
   or row_value->>'reference'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   raise invalid_parameter_value using message='invalid_tracking_row';end if;
  sid:=(row_value->>'reference')::uuid;
  if sid=any(ids) then raise check_violation using message='duplicate_shipment_reference';end if;
  ids:=array_append(ids,sid);
 end loop;
 scope_ids:=private.lock_shipment_pack_scope(ids);
 perform private.assert_whole_shipment_packs(ids);
 -- Validate all matching/scope evidence before delegating to per-row savepoints.
 for row_value in select value from jsonb_array_elements(target_rows) loop
  sid:=(row_value->>'reference')::uuid;
  select * into strict shipment from public.order_shipments where id=sid;
  carrier_value:=nullif(btrim(row_value->>'carrier'),'');
  tracking_value:=nullif(upper(regexp_replace(btrim(row_value->>'trackingNumber'),'[[:space:]-]','','g')),'');
  if shipment.origin_id<>origin.id then raise check_violation using message='warehouse_origin_mismatch';end if;
  if shipment.delivery_method<>'parcel' then raise check_violation using message='delivery_method_evidence_required';end if;
  if carrier_value is distinct from origin.default_carrier or tracking_value is null then
   raise check_violation using message='invalid_tracking_row';end if;
  if shipment.status='ready' then
   if shipment.exported_at is null then raise check_violation using message='shipment_not_exported';end if;
   if exists(select 1 from public.order_shipments where id=any(private.shipment_pack_scope(array[sid])) and status<>'ready') then
    raise check_violation using message='shipment_tracking_conflict';end if;
   perform private.assert_order_dispatch_allowed(shipment.order_id);
   perform private.assert_shipment_preorder_ready(sid);
   if(private.shipment_production_summary(sid)->>'ready')::boolean is distinct from true then
    raise check_violation using message='production_incomplete';end if;
  elsif shipment.status not in('shipping','delivered') or exists(select 1 from public.orders where id=shipment.order_id and status='canceled') then
   raise check_violation using message='order_not_shipped';
  elsif shipment.carrier is distinct from carrier_value or shipment.tracking_number is distinct from tracking_value then
   raise check_violation using message='shipment_tracking_conflict';
  end if;
 end loop;
 perform private.prepare_pack_tracking_batch(target_rows);
 perform private.lock_tracking_batch(target_rows,null);
 perform private.assert_reply_extra_trackings(target_rows);
 return private.attach_reply_extra_trackings(target_rows,public.admin_import_shipment_tracking_batch(target_rows));
end $function$

CREATE OR REPLACE FUNCTION public.admin_import_shipment_tracking_batch(target_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare input jsonb;shipment_key uuid;completed jsonb;results jsonb:='[]'::jsonb;seen uuid[]:='{}'::uuid[];conflicts text[];
begin
  perform private.require_operator_capability('sales.dispatch',false);

 if (select auth.uid()) is null or not public.has_operator_capability('sales.dispatch',false) then raise insufficient_privilege using message='staff required';end if;
 if jsonb_typeof(target_rows) is distinct from 'array' or jsonb_array_length(target_rows) not between 1 and 1000 then raise invalid_parameter_value using message='invalid_tracking_batch';end if;
 perform private.prepare_pack_tracking_batch(target_rows);
 -- Hold all existing target order locks in one stable order before per-row savepoints.
 -- Different files may list the same warehouses in opposite orders.
 perform o.id from public.orders o where exists(select 1 from public.order_shipments s
   where s.order_id=o.id and exists(select 1 from jsonb_array_elements(target_rows) row_value
     where lower(btrim(row_value->>'reference')) in (s.id::text,o.id::text,right(s.id::text,8),right(o.id::text,8)))) order by o.id for update;
 -- 주문 잠금 뒤에 번호를 열쇠 순서로 잠근다(주문 → 번호 순서는 모든 등록 경로가 같다).
 conflicts:=private.lock_tracking_batch(target_rows,null);
 for input in select value from jsonb_array_elements(target_rows) loop
  begin
   if jsonb_typeof(input) is distinct from 'object' then raise invalid_parameter_value using message='invalid_tracking_row';end if;
   shipment_key:=private.resolve_shipment_reference(input->>'reference');
   if shipment_key=any(seen) then raise check_violation using message='duplicate_shipment_reference';end if;
   if nullif(btrim(input->>'carrier'),'')||':'||private.normalize_tracking_number(input->>'trackingNumber')=any(conflicts)
    or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(input->'extraTrackingNumbers')='array' then input->'extraTrackingNumbers' else '[]'::jsonb end) extra
     where jsonb_typeof(extra)='string' and nullif(btrim(input->>'carrier'),'')||':'||private.normalize_tracking_number(extra#>>'{}')=any(conflicts)) then
    raise check_violation using message='tracking_number_shared_in_reply';end if;
   completed:=public.admin_import_shipment_tracking(shipment_key::text,input->>'carrier',input->>'trackingNumber');
   seen:=array_append(seen,shipment_key);
   results:=results||jsonb_build_array(completed||jsonb_build_object('line',input->'line','reference',input->>'reference','ok',true));
  exception when others then
   results:=results||jsonb_build_array(jsonb_build_object('line',input->'line','reference',input->>'reference','ok',false,'error',sqlerrm));
  end;
 end loop;
 return results;
end $function$

CREATE OR REPLACE FUNCTION public.admin_import_shipment_tracking(p_reference text, p_carrier text, p_tracking_number text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare reference_key uuid;shipment_key uuid;shipment public.order_shipments;changed boolean;scope_ids uuid[];
 carrier_value text:=nullif(btrim(p_carrier),'');
 tracking_value text:=nullif(upper(regexp_replace(btrim(p_tracking_number),'[[:space:]-]','','g')),'');
begin
 perform private.require_operator_capability('sales.dispatch',false);
 reference_key:=btrim(p_reference)::uuid;
 select id into shipment_key from public.order_shipments where id=reference_key;
 if shipment_key is null then shipment_key:=private.single_order_shipment(reference_key);end if;
 scope_ids:=private.lock_shipment_pack_scope(array[shipment_key]);
 select * into shipment from public.order_shipments where id=shipment_key;
 changed:=shipment.status='ready';
 if changed then
  -- A pack moves together. Existing dispatch evidence must never be overwritten
  -- by importing a ready sibling from a stale or inconsistent reply.
  if exists(select 1 from public.order_shipments where id=any(scope_ids) and status<>'ready') then
   raise check_violation using message='shipment_tracking_conflict';end if;
  perform public.admin_update_shipment_status(shipment.id,'shipping',carrier_value,tracking_value);
 else
  perform private.lock_parcel_shipment(shipment.id);
  if exists(select 1 from public.order_shipments s join public.orders o on o.id=s.order_id
   where s.id=any(scope_ids) and(s.delivery_method<>'parcel' or s.status not in('shipping','delivered') or o.status='canceled')) then
   raise check_violation using message='order_not_shipped';end if;
  if exists(select 1 from public.order_shipments where id=any(scope_ids)
   and(carrier is distinct from carrier_value or tracking_number is distinct from tracking_value)) then
   raise check_violation using message='shipment_tracking_conflict';end if;
 end if;
 return jsonb_build_object('shipmentId',shipment.id,'orderId',shipment.order_id,'dispatched',changed,
  'packedShipments',(select jsonb_agg(jsonb_build_object('shipmentId',s.id,'orderId',s.order_id) order by s.id)
   from public.order_shipments s where s.id=any(scope_ids)))
  ||case when changed then '{}'::jsonb else jsonb_build_object('unchanged',true) end;
end $function$

CREATE OR REPLACE FUNCTION public.admin_import_warehouse_tracking_batch(target_origin_id uuid, target_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  input jsonb;
  normalized jsonb := '[]';
  outcomes jsonb := '{}';
  results jsonb := '[]';
  reference_value text;
  order_key uuid;
  shipment_key uuid;
  tracking_value text;
  row_error text;
  group_error text;
  group_row record;
  matches integer;
  origin public.fulfillment_origins;
  completed jsonb;
  outcome jsonb;
  seen uuid[] := '{}';
  conflicts text[];
begin
  perform private.require_operator_capability('sales.dispatch',false);

  if (select auth.uid()) is null or not public.has_operator_capability('sales.dispatch',false) then
    raise insufficient_privilege using message='staff required';
  end if;
  if jsonb_typeof(target_rows) is distinct from 'array' then
    raise invalid_parameter_value using message='invalid_tracking_batch';
  end if;
  if jsonb_array_length(target_rows) not between 1 and 1000 then
    raise invalid_parameter_value using message='invalid_tracking_batch';
  end if;
  if target_origin_id is null then
    raise invalid_parameter_value using message='warehouse_origin_required';
  end if;

  for input in select value from jsonb_array_elements(target_rows) loop
    reference_value := null;
    order_key := null;
    tracking_value := null;
    row_error := null;
    begin
      if jsonb_typeof(input) is distinct from 'object' then
        raise invalid_parameter_value using message='invalid_tracking_row';
      end if;
      reference_value := btrim(input->>'reference');
      if jsonb_typeof(input->'reference') is distinct from 'string'
        or (reference_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          and reference_value !~ '^[0-9]{10,32}$') then
        raise invalid_parameter_value using message='invalid_warehouse_order_reference';
      end if;
      order_key := private.warehouse_reply_order_id(reference_value);
      if order_key is null then raise no_data_found using message='shipment_not_found'; end if;
      -- Keep the parsed order on row errors so an invalid sibling cannot let the
      -- first valid row write half of the same shipment group.
      if exists(select 1 from jsonb_object_keys(input) key where key not in ('line','reference','trackingNumber','recipientName','recipientPhone'))
        or jsonb_typeof(input->'line') is distinct from 'number'
        or (input->>'line') !~ '^[0-9]+$'
        or (input->>'line')::numeric not between 1 and 2147483647
        or jsonb_typeof(input->'trackingNumber') is distinct from 'string' then
        raise invalid_parameter_value using message='invalid_tracking_row';
      end if;
      tracking_value := upper(regexp_replace(btrim(input->>'trackingNumber'),'[[:space:]-]','','g'));
      if tracking_value !~ '^[A-Z0-9]{8,30}$' then
        raise check_violation using message='invalid_tracking_input';
      end if;
      -- 회신의 받는 분이 주문과 다르면(두 주문의 운송장이 뒤바뀐 회신 의심) 그 주문의 줄만 실패한다.
      perform private.assert_reply_recipient(order_key, input);
    exception when others then row_error := sqlerrm;
    end;
    normalized := normalized || jsonb_build_array(jsonb_build_object(
      'line',input->'line','reference',reference_value,'orderId',order_key,
      'trackingNumber',tracking_value,'error',row_error));
  end loop;

  perform private.prepare_pack_tracking_batch(target_rows,target_origin_id);
  -- Same global order->origin->shipment lock ordering as order/dispatch writers.
  -- Lock every existing order before per-shipment savepoints, including groups
  -- with invalid tracking data. Opposite file row orders cannot deadlock.
  perform o.id from public.orders o where exists(
    select 1 from jsonb_array_elements(normalized) row_value
    where row_value->>'orderId'=o.id::text
  ) order by o.id for update;
  select * into origin from public.fulfillment_origins where id=target_origin_id for share;
  if not found then raise no_data_found using message='warehouse_origin_not_found'; end if;
  if not origin.is_active then raise check_violation using message='warehouse_origin_inactive'; end if;
  if origin.export_template<>'wms_csv' then raise check_violation using message='warehouse_template_required'; end if;
  if origin.default_carrier is null then raise check_violation using message='warehouse_carrier_required'; end if;
  perform code from public.shipping_carriers where code=origin.default_carrier and is_active for share;
  if not found then raise check_violation using message='inactive_shipping_carrier'; end if;
  conflicts := private.lock_tracking_batch(target_rows, target_origin_id);

  for group_row in
    select (value->>'orderId')::uuid order_id, jsonb_agg(value) rows
    from jsonb_array_elements(normalized)
    where value->>'orderId' is not null
    group by value->>'orderId' order by value->>'orderId'
  loop
    begin
      select value->>'error' into group_error from jsonb_array_elements(group_row.rows)
        where value->>'error' is not null limit 1;
      if group_error is not null then raise check_violation using message=group_error; end if;
      if (select count(distinct value->>'trackingNumber') from jsonb_array_elements(group_row.rows))<>1 then
        raise check_violation using message='conflicting_shipment_tracking';
      end if;
      select count(*),(array_agg(id))[1] into matches,shipment_key
        from public.order_shipments where order_id=group_row.order_id and origin_id=origin.id;
      if matches=0 then raise no_data_found using message='shipment_not_found'; end if;
      if matches<>1 then raise check_violation using message='shipment_reference_required'; end if;
      tracking_value := group_row.rows->0->>'trackingNumber';
      if origin.default_carrier || ':' || tracking_value = any(conflicts) then
        raise check_violation using message='tracking_number_shared_in_reply';
      end if;
      completed := public.admin_import_shipment_tracking(shipment_key::text,origin.default_carrier,tracking_value);
      outcomes := outcomes || jsonb_build_object(group_row.order_id::text,completed||jsonb_build_object('ok',true));
    exception when others then
      outcomes := outcomes || jsonb_build_object(group_row.order_id::text,jsonb_build_object('ok',false,'error',sqlerrm));
    end;
  end loop;

  -- Return one outcome per original row, in file order. Only the first successful
  -- row represents the mutation; duplicate rows must not count or enqueue twice.
  for input in select value from jsonb_array_elements(normalized) loop
    order_key := (input->>'orderId')::uuid;
    outcome := case when order_key is null then jsonb_build_object('ok',false,'error',input->>'error')
      else outcomes->order_key::text end;
    if outcome->>'ok'='true' then
      if order_key=any(seen) then
        outcome := outcome || jsonb_build_object('duplicate',true,'dispatched',false);
      else
        seen := array_append(seen,order_key);
        outcome := outcome || jsonb_build_object('duplicate',false);
      end if;
    end if;
    results := results || jsonb_build_array(outcome||jsonb_build_object('line',input->'line','reference',input->>'reference'));
  end loop;
  return results;
end $function$

CREATE OR REPLACE FUNCTION public.admin_inquiry_chat_context(p_inquiry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_customer uuid;
begin
  if (select auth.uid()) is null or not public.has_operator_capability('cs.manage',false) then
    raise insufficient_privilege using message='operator_capability_required';end if;
  select user_id into v_customer from public.inquiries where id=p_inquiry_id;
  if not found then raise no_data_found using message='inquiry_not_found';end if;
  return jsonb_build_object('inquiryId',p_inquiry_id,
    'tags',coalesce((select jsonb_agg(label order by label) from private.inquiry_chat_tags where inquiry_id=p_inquiry_id),'[]'::jsonb),
    'previousCount',(select count(*) from public.inquiries where user_id=v_customer and id<>p_inquiry_id),
    'previous',coalesce((select jsonb_agg(jsonb_build_object('id',prior.id,'reference',prior.reference,'title',prior.title,
      'status',prior.status,'lastMessageAt',prior.last_message_at) order by prior.last_message_at desc,prior.id)
      from (select id,reference,title,status,last_message_at from public.inquiries where user_id=v_customer and id<>p_inquiry_id
        order by last_message_at desc,id limit 20) prior),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.admin_inquiry_processing_history(target_inquiry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  thread public.inquiries;
  events jsonb;
  total integer;
  event_limit constant integer := 100;
begin
  if not public.has_operator_capability('cs.manage') then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  if target_inquiry_id is null then
    raise invalid_parameter_value using message = 'inquiry_history_invalid';
  end if;
  select * into thread from public.inquiries where id = target_inquiry_id;
  if not found then
    raise no_data_found using message = 'inquiry_not_found';
  end if;

  select count(*) into total from public.audit_log a
  where a.target = 'inquiries:' || thread.id::text
    and a.action in ('admin.inquiry.assigned', 'admin.inquiry.reassigned', 'admin.inquiry.answered', 'admin.inquiry.closed');

  with picked as (
    select a.id, a.created_at, a.action, a.actor_id, a.diff,
      case a.action when 'admin.inquiry.assigned' then 0 when 'admin.inquiry.answered' then 1
        when 'admin.inquiry.reassigned' then 2 else 3 end as step,
      case when a.diff->>'before' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (a.diff->>'before')::uuid end as before_id,
      case when a.diff->>'after' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (a.diff->>'after')::uuid end as after_id
    from public.audit_log a
    where a.target = 'inquiries:' || thread.id::text
      and a.action in ('admin.inquiry.assigned', 'admin.inquiry.reassigned', 'admin.inquiry.answered', 'admin.inquiry.closed')
    order by a.created_at desc,
      case a.action when 'admin.inquiry.assigned' then 0 when 'admin.inquiry.answered' then 1
        when 'admin.inquiry.reassigned' then 2 else 3 end desc,
      a.id desc
    limit event_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id::text,
      'at', p.created_at,
      'kind', case p.action when 'admin.inquiry.assigned' then 'assigned' when 'admin.inquiry.reassigned' then 'reassigned'
        when 'admin.inquiry.answered' then 'answered' else 'closed' end,
      'actorName', case when p.actor_id is null then null
        else coalesce(nullif(btrim(actor.nickname), ''), '운영자_' || left(p.actor_id::text, 6)) end,
      'fromName', case when p.action = 'admin.inquiry.reassigned' and p.before_id is not null
        then coalesce(nullif(btrim(before_profile.nickname), ''), '운영자_' || left(p.before_id::text, 6)) end,
      'toName', case when p.action in ('admin.inquiry.reassigned', 'admin.inquiry.assigned') and p.after_id is not null
        then coalesce(nullif(btrim(after_profile.nickname), ''), '운영자_' || left(p.after_id::text, 6)) end,
      'reason', case when p.action = 'admin.inquiry.reassigned' then nullif(btrim(p.diff->>'reason'), '') end
    ) order by p.created_at, p.step, p.id), '[]'::jsonb)
  into events
  from picked p
  left join public.profiles actor on actor.id = p.actor_id
  left join public.profiles before_profile on before_profile.id = p.before_id
  left join public.profiles after_profile on after_profile.id = p.after_id;

  -- 자동 종결(close_stale_answered_inquiries)은 실행자가 없어 감사 기록이 없다. 운영자 완료 기록이 없는 종결 문의만 종결 시각으로 보인다.
  if thread.status = 'closed' and thread.closed_at is not null and not exists (
    select 1 from public.audit_log a where a.target = 'inquiries:' || thread.id::text and a.action = 'admin.inquiry.closed'
  ) then
    events := events || jsonb_build_array(jsonb_build_object('id', 'auto-close:' || thread.id::text, 'at', thread.closed_at,
      'kind', 'auto_closed', 'actorName', null, 'fromName', null, 'toName', null, 'reason', null));
    total := total + 1;
  end if;

  return jsonb_build_object('inquiryId', thread.id, 'events', events, 'total', total, 'limit', event_limit);
end $function$

CREATE OR REPLACE FUNCTION public.admin_inquiry_purchase_history(target_inquiry_id uuid, target_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid;
  thread public.inquiries;
  total bigint;
  page integer;
  page_size constant integer := 20;
  items jsonb;
  shown uuid[];
  linked jsonb := null;
begin
  actor := private.require_operator_capability('cs.manage');
  if target_inquiry_id is null then
    raise invalid_parameter_value using message = 'inquiry_purchase_history_invalid';
  end if;
  select * into thread from public.inquiries where id = target_inquiry_id;
  if not found then
    raise no_data_found using message = 'inquiry_not_found';
  end if;

  select count(*) into total from public.orders where user_id = thread.user_id;
  page := least(greatest(coalesce(target_page, 1), 1), greatest(1, (total + page_size - 1) / page_size)::integer);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id, 'orderNumber', r.order_number, 'status', r.status, 'amount', r.total, 'createdAt', r.created_at,
      'title', coalesce((select i.good_name_snapshot from public.order_items i where i.order_id = r.id order by i.id limit 1), '주문 상품'),
      'itemCount', (select count(*) from public.order_items i where i.order_id = r.id)
    ) order by r.created_at desc, r.id desc), '[]'::jsonb),
    coalesce(array_agg(r.id order by r.created_at desc, r.id desc), '{}'::uuid[])
  into items, shown
  from (
    select o.id, o.order_number, o.status, o.total, o.created_at
    from public.orders o
    where o.user_id = thread.user_id
    order by o.created_at desc, o.id desc
    limit page_size offset (page - 1) * page_size
  ) r;

  if thread.order_id is not null then
    select jsonb_build_object(
      'id', o.id, 'orderNumber', o.order_number, 'status', o.status, 'amount', o.total, 'createdAt', o.created_at,
      'title', coalesce((select i.good_name_snapshot from public.order_items i where i.order_id = o.id order by i.id limit 1), '주문 상품'),
      'quantity', (select coalesce(sum(i.qty), 0) from public.order_items i where i.order_id = o.id))
    into linked
    from public.orders o
    where o.id = thread.order_id and o.user_id = thread.user_id;
  end if;

  if not exists (
    select 1 from public.audit_log a
    where a.target = 'inquiries:' || thread.id::text
      and a.action = 'admin.inquiry.purchase_history_viewed'
      and a.actor_id = actor
      and a.created_at > clock_timestamp() - interval '10 minutes'
      and a.diff->>'page' = page::text
      and a.diff->'orderIds' = to_jsonb(shown)
      and a.diff->>'linkedOrderId' is not distinct from (linked->>'id')
  ) then
    insert into public.audit_log(actor_id, action, target, diff)
    values (actor, 'admin.inquiry.purchase_history_viewed', 'inquiries:' || thread.id::text,
      jsonb_build_object('customerId', thread.user_id, 'page', page, 'total', total, 'orderIds', to_jsonb(shown),
        'linkedOrderId', linked->'id'));
  end if;

  return jsonb_build_object('inquiryId', thread.id, 'customerId', thread.user_id, 'linkedOrder', linked,
    'items', items, 'page', page, 'pageSize', page_size, 'total', total);
end $function$

CREATE OR REPLACE FUNCTION public.admin_inquiry_status_counts()
 RETURNS TABLE(status text, total bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.has_operator_capability('cs.manage',false) then raise insufficient_privilege using message='operator_capability_required'; end if;

  if (select auth.uid()) is null or not public.has_operator_capability('cs.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;

  return query
  select
    allowed.value::text,
    coalesce(counted.tally, 0)::bigint
  from (values ('open'), ('answered'), ('closed')) as allowed(value)
  left join (
    select thread.status as value, pg_catalog.count(*) as tally
    from public.inquiries as thread
    group by thread.status
  ) as counted on counted.value = allowed.value;
end;
$function$

