CREATE OR REPLACE FUNCTION public.admin_list_shipping_settings_templates(p_query text DEFAULT ''::text, p_state text DEFAULT 'all'::text, p_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; pattern text;
begin
  if not public.has_operator_capability('catalog.read',false) then raise insufficient_privilege using message='operator_capability_required'; end if;

 if (select auth.uid()) is null or not public.has_operator_capability('catalog.read',false) then raise insufficient_privilege using message='staff_required'; end if;
 if p_query is null or char_length(p_query)>80 or p_state is null or p_state not in ('all','enabled','disabled') or p_page is null or p_page not between 1 and 100000
 then raise invalid_parameter_value using message='invalid_shipping_settings_filter'; end if;
 pattern:='%'||replace(replace(replace(btrim(p_query),E'\\',E'\\\\'),'%',E'\\%'),'_',E'\\_')||'%';
 with matched as (select * from public.shipping_settings_templates t where t.name ilike pattern escape E'\\'
  and (p_state='all' or t.enabled=(p_state='enabled'))), page as (select * from matched order by updated_at desc,id limit 20 offset (p_page-1)*20)
 select jsonb_build_object('total',(select count(*) from matched),'rows',coalesce(jsonb_agg(private.shipping_settings_template_json(page) order by page.updated_at desc,page.id),'[]')) into result from page;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_list_shopping_stories(p_query text DEFAULT ''::text, p_state text DEFAULT 'all'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_sort text DEFAULT 'created_desc'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare at_value timestamptz:=statement_timestamp(); result_value jsonb;
begin
 if not public.has_operator_capability('store.manage') then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_query is null or char_length(p_query)>100 or p_state is null or p_state not in ('all','scheduled','active','ended')
  or p_sort is null or p_sort not in ('created_desc','created_asc','updated_desc') or p_limit is null or p_limit not between 1 and 100 or p_offset is null or p_offset<0
  or (p_from is not null and p_to is not null and p_from>p_to) then raise invalid_parameter_value using message='invalid_shopping_story_filter';end if;
 with filtered as (
  select s.*,private.shopping_story_state(s.starts_at,s.ends_at,at_value) display_state from public.shopping_stories s
  where s.deleted_at is null and (p_query='' or position(lower(p_query) in lower(s.title))>0)
   and (p_state='all' or private.shopping_story_state(s.starts_at,s.ends_at,at_value)=p_state)
   and (p_from is null or s.created_at>=p_from::timestamp at time zone 'Asia/Seoul')
   and (p_to is null or s.created_at<(p_to+1)::timestamp at time zone 'Asia/Seoul')
 ), page as (
  select * from filtered order by case when p_sort='created_asc' then created_at end asc,
   case when p_sort='updated_desc' then updated_at end desc,created_at desc,id desc limit p_limit offset p_offset
 ) select jsonb_build_object('total',(select count(*) from filtered),'checkedAt',at_value,'rows',coalesce((select jsonb_agg(jsonb_build_object(
  'id',p.id,'reference',p.reference,'title',p.title,'startsAt',p.starts_at,'endsAt',p.ends_at,'state',p.display_state,'revision',p.revision,
  'createdAt',p.created_at,'updatedAt',p.updated_at,'sectionCount',(select count(*) from public.shopping_story_sections x where x.story_id=p.id),
  'goodCount',(select count(*) from public.shopping_story_goods x where x.story_id=p.id)) order by case when p_sort='created_asc' then p.created_at end asc,
   case when p_sort='updated_desc' then p.updated_at end desc,p.created_at desc,p.id desc) from page p),'[]'::jsonb)) into result_value;
 return result_value;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_mark_inquiry_chat_read(p_inquiry_id uuid, p_message_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid;v_inserted integer;
begin
  v_actor:=private.require_operator_capability('cs.manage',false);
  if p_inquiry_id is null or p_message_ids is null or cardinality(p_message_ids) not between 1 and 500
    or array_position(p_message_ids,null) is not null then
    raise invalid_parameter_value using message='invalid_inquiry_chat_read';
  end if;
  if not exists(select 1 from public.inquiries where id=p_inquiry_id) then
    raise no_data_found using message='inquiry_not_found';
  end if;
  if exists(select 1 from unnest(p_message_ids) ids(id) where not exists(
    select 1 from public.inquiry_messages message where message.id=ids.id and message.inquiry_id=p_inquiry_id and message.author='user')) then
    raise invalid_parameter_value using message='invalid_inquiry_chat_message';
  end if;
  insert into private.inquiry_chat_reads(actor_id,message_id)
    select v_actor,message.id from public.inquiry_messages message
    where message.inquiry_id=p_inquiry_id and message.author='user' and message.id=any(p_message_ids)
    on conflict(actor_id,message_id) do nothing;
  get diagnostics v_inserted=row_count;
  return v_inserted;
end $function$

CREATE OR REPLACE FUNCTION public.admin_mark_shipments_exported(target_versions jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_value record;shipment public.order_shipments;total integer:=0;actor uuid:=(select auth.uid());
begin
  perform private.require_operator_capability('sales.dispatch',false);

 if actor is null or not public.has_operator_capability('sales.dispatch',false) then raise insufficient_privilege using message='staff required';end if;
 if jsonb_typeof(target_versions) is distinct from 'array' or jsonb_array_length(target_versions) not between 1 and 1000 then raise invalid_parameter_value using message='invalid_export_selection';end if;
 if (select count(distinct value->>'id') from jsonb_array_elements(target_versions))<>jsonb_array_length(target_versions) then raise invalid_parameter_value using message='invalid_export_selection';end if;
 perform private.lock_shipment_pack_scope(array(select (value->>'id')::uuid from jsonb_array_elements(target_versions)));
 perform private.assert_whole_shipment_packs(array(select (value->>'id')::uuid from jsonb_array_elements(target_versions)));
 -- Global order sequence matches all other shipment mutations.
 perform o.id from public.orders o where exists(select 1 from public.order_shipments s join jsonb_to_recordset(target_versions) v(id uuid,"updatedAt" timestamptz) on v.id=s.id where s.order_id=o.id) order by o.id for update;
 for row_value in select * from jsonb_to_recordset(target_versions) as v(id uuid,"updatedAt" timestamptz) order by id loop
  select * into shipment from public.order_shipments where id=row_value.id for update;
  if not found or shipment.status<>'ready' or row_value."updatedAt" is null or shipment.updated_at<>row_value."updatedAt"
    or not exists(select 1 from public.orders where id=shipment.order_id and status in ('confirmed','shipping')) then raise sqlstate 'PT409' using message='shipment_changed';end if;
  perform private.assert_order_dispatch_allowed(shipment.order_id);
  update public.order_shipments set exported_at=clock_timestamp(),exported_by=actor,updated_at=clock_timestamp() where id=shipment.id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.shipment.exported','order:'||shipment.order_id,jsonb_build_object('shipmentId',shipment.id,'originName',shipment.origin_name_snapshot));
  total:=total+1;
 end loop;
 return total;
end $function$

CREATE OR REPLACE FUNCTION public.admin_mark_staging_test_delivered(p_order_number text, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;purchase public.orders;targets uuid[];ids uuid[];shipment record;delivered integer:=0;at_value timestamptz;request jsonb;receipt jsonb;
begin
 actor:=private.require_operator_capability('sales.manage',false);
 if not private.staging_test_tools_available() then raise insufficient_privilege using message='staging_test_delivery_unavailable';end if;
 if p_order_number is null or not private.is_commerce_number(p_order_number,1::smallint) or p_operation_id is null then
  raise invalid_parameter_value using message='invalid_staging_test_delivery';end if;
 request:=jsonb_build_object('orderNumber',p_order_number);
 perform pg_advisory_xact_lock(hashtextextended('staging-test-delivery:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.staging.test_delivered',request);
 if receipt is not null then return receipt;end if;
 select * into purchase from public.orders where order_number=p_order_number;
 if not found then raise no_data_found using message='order_not_found';end if;
 select coalesce(array_agg(id order by id),'{}'::uuid[]) into targets from public.order_shipments where order_id=purchase.id and status in ('ready','shipping');
 if cardinality(targets)=0 then
  select * into purchase from public.orders where id=purchase.id for update;
  if purchase.status not in ('confirmed','shipping') then raise check_violation using message='staging_test_delivery_requires_confirmed';end if;
  raise check_violation using message='staging_test_delivery_nothing_to_deliver';
 end if;
 ids:=private.lock_shipment_pack_scope(targets);
 if exists(select 1 from public.order_shipments where order_id=purchase.id and status in ('ready','shipping') and id<>all(ids)) then
  raise sqlstate 'PT409' using message='shipment_pack_changed';end if;
 if exists(select 1 from public.orders o where o.id in(select order_id from public.order_shipments where id=any(ids)) and o.status not in ('confirmed','shipping')) then
  raise check_violation using message='staging_test_delivery_requires_confirmed';end if;
 perform private.assert_order_dispatch_allowed(order_id) from (select distinct order_id from public.order_shipments where id=any(ids) order by order_id) packed;
 if exists(select 1 from public.order_shipments where id=any(ids) and status in ('ready','shipping') and delivery_method<>'parcel') then
  raise check_violation using message='staging_test_delivery_parcel_only';end if;
 at_value:=clock_timestamp();
 for shipment in select id from public.order_shipments where id=any(ids) and status in ('ready','shipping') order by id loop
  perform private.assert_shipment_preorder_ready(shipment.id);
  update public.order_shipments set status='delivered',shipped_at=coalesce(shipped_at,at_value),delivered_at=at_value where id=shipment.id;
  delivered:=delivered+1;
 end loop;
 if delivered=0 then raise check_violation using message='staging_test_delivery_nothing_to_deliver';end if;
 select * into purchase from public.orders where id=purchase.id;
 receipt:=jsonb_build_object('orderId',purchase.id,'orderNumber',purchase.order_number,'status',purchase.status,'deliveredShipments',delivered,
  'orderCount',(select count(distinct order_id) from public.order_shipments where id=any(ids))::integer,'deliveredAt',at_value);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.staging.test_delivered','order:'||purchase.id,
  jsonb_build_object('request',request,'result',receipt,'staging',true,'shipmentIds',to_jsonb(ids)));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_member_moderation_context(p_profile_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); legacy boolean; actor_role public.user_role;
begin
  if not public.has_operator_capability('platform.manage',false) then
    raise insufficient_privilege using message='operator_capability_required';end if;
  if p_profile_ids is null or cardinality(p_profile_ids)>100 or array_position(p_profile_ids,null) is not null then
    raise invalid_parameter_value using message='invalid_member_moderation_targets';end if;
  legacy:=(private.operator_access_for(actor)->>'mode')='legacy';
  select role into actor_role from public.profiles where id=actor;
  return (select coalesce(jsonb_agg(jsonb_build_object('profileId',profile.id,'managerRole',membership.manager_role,
    'loyaltyGrade',profile.loyalty_grade,
    'canModerate',profile.id<>actor and coalesce(membership.manager_role not in ('owner','primary'),true)
      and (not legacy or (profile.role<>'admin' and (actor_role<>'staff' or profile.role='user')))
  ) order by profile.id),'[]') from public.profiles profile
  left join private.operator_memberships membership on membership.profile_id=profile.id
  where profile.id=any(p_profile_ids));
end $function$

