CREATE OR REPLACE FUNCTION public.admin_order_claim_bulk_context(p_claim_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='operator_capability_required'; end if;
  if auth.uid() is null then raise insufficient_privilege using message='staff required'; end if;
  if p_claim_ids is null or cardinality(p_claim_ids) not between 1 and 50 or array_position(p_claim_ids,null) is not null then
    raise check_violation using message='invalid_claim_bulk_ids'; end if;
  -- 고른 순서대로, 같은 요청은 한 번만, 없는 요청은 빼고 돌려준다.
  return coalesce((select jsonb_agg(private.order_claim_bulk_context_row(picked.id) order by picked.position)
    from (select distinct on (u.id) u.id,u.position from unnest(p_claim_ids) with ordinality u(id,position) order by u.id,u.position) picked
    where exists(select 1 from public.order_cancellation_requests c where c.id=picked.id)),'[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.admin_order_claim_detail(p_claim_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  if not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='operator_capability_required'; end if;

  if auth.uid() is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message = 'staff required'; end if;
  result := private.admin_order_claim_detail_before_custom_inputs(p_claim_id);
  if result is null then return null; end if;
  if result->'order' is not null and result->'order' <> 'null'::jsonb then
    result := jsonb_set(result, '{order,items}', private.with_order_item_custom_inputs(result#>'{order,items}'));
  end if;
  if jsonb_typeof(result->'order')='object' then
    result:=jsonb_set(result,'{order}',(result->'order')||jsonb_build_object('orderNumber',
      (select order_number from public.orders where id=(result#>>'{order,id}')::uuid),
      -- 적용된 재고 부족 부분 취소 수량(ADR-0032). 품목 목록(items)은 살아 있는 수량이고 모두 취소된 품목은 빠지므로, 앱은 원 거래
      -- 영수증 줄을 '원 수량 − 이 수량'으로 대조한다. 부분 취소가 없으면 빈 배열이다.
      'partialCancels',coalesce((select jsonb_agg(jsonb_build_object('orderItemId',item.id,'canceledQty',totals.qty) order by item.id)
        from public.order_items item cross join lateral private.order_item_partial_cancel_totals(item.id) totals
        where item.order_id=(result#>>'{order,id}')::uuid and totals.qty>0),'[]'::jsonb)));
  end if;
  -- 배송 건별 재출고(TKT-166·QNA-039): 대상 배송 건, 배송 건 재출고 기록, 회수 생략 가능 여부.
  if jsonb_typeof(result->'claim')='object' then
    result:=jsonb_set(result,'{claim}',(result->'claim')||jsonb_build_object('reshipmentTargets',private.claim_reshipment_targets_json(p_claim_id),
      'reshipments',private.claim_reshipment_records_json(p_claim_id),
      'collectionWaiverAllowed',(select c.claim_type='exchange' and c.reason_type='defect' and c.collection_policy='origin' and c.collection_required
        from public.order_cancellation_requests c where c.id=p_claim_id)));
  end if;
  -- 실제 입고일(1027T-033): 클레임의 회수 완료일. 환급 기한은 이 날부터 센다(비어 있으면 옛 기록이라 collectedAt).
  if jsonb_typeof(result->'claim')='object' then
    result:=jsonb_set(result,'{claim}',(result->'claim')||jsonb_build_object('collectionReceivedOn',
      (select c.collection_received_on from public.order_cancellation_requests c where c.id=p_claim_id)));
  end if;
  -- 반품배송비 차감(QNA-033): 결정 또는 접수 전 판정. 스위치가 꺼져 있고 결정이 없으면 덧붙이지 않는다.
  result := result || private.claim_refund_deduction_field(p_claim_id);
  return result || jsonb_build_object('sellerIntake', private.seller_claim_intake_json(p_claim_id),'gift',private.gift_admin_claim_party(p_claim_id));
end $function$

