CREATE OR REPLACE FUNCTION public.admin_order_partial_cancellation_context(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare enabled boolean; blockers text[]; history jsonb; pay public.payments; items jsonb; can_manage boolean; level text;
begin
  perform private.require_operator_capability('sales.read', false);
  can_manage := public.has_operator_capability('sales.manage', false);
  -- sales.read는 고객 결정 요약까지, 처리 권한(sales.manage)은 운영 메모·처리자까지, 송금 증빙·계좌·해소 사유는 레거시 관리자만(T03·ADR-0010).
  level := case when public.has_operator_capability('sales.manage', true) then 'legacy' when can_manage then 'manage' else 'read' end;
  enabled := private.order_partial_cancel_enabled();
  select coalesce(jsonb_agg(private.order_partial_cancellation_json(head.id, level) order by head.sequence), '[]'::jsonb) into history
  from private.order_partial_cancellations head where head.order_id = p_order_id;
  if not enabled then
    return jsonb_build_object('enabled', false, 'canManage', can_manage, 'blockers', jsonb_build_array('partial_cancel_disabled'), 'history', history);
  end if;
  if not can_manage then
    return jsonb_build_object('enabled', true, 'canManage', false, 'blockers', '[]'::jsonb, 'history', history);
  end if;
  if not exists(select 1 from public.orders where id = p_order_id) then raise no_data_found using message = 'order_not_found'; end if;
  blockers := private.order_partial_cancellation_blockers(p_order_id);
  pay := private.order_partial_cancellation_payment(p_order_id);
  select coalesce(jsonb_agg(jsonb_build_object('orderItemId', item.id, 'goodName', item.good_name_snapshot, 'variantName', item.variant_name_snapshot,
      'variantCode', item.variant_code_snapshot, 'orderedQty', item.qty, 'canceledQty', private.order_item_partially_canceled_qty(item.id),
      'activeQty', private.order_item_active_qty(item.id), 'unitPrice', item.unit_price,
      'shipmentId', link.shipment_id, 'shipmentNumber', ship.shipment_number, 'originName', ship.origin_name_snapshot,
      'exported', ship.exported_at is not null, 'blocker', private.order_partial_cancellation_item_blocker(item.id))
    order by ship.shipment_number nulls last, item.good_name_snapshot, item.id), '[]'::jsonb) into items
  from public.order_items item
  left join public.order_shipment_items link on link.order_item_id = item.id and link.order_id = item.order_id
  left join public.order_shipments ship on ship.id = link.shipment_id
  where item.order_id = p_order_id;
  return jsonb_build_object('enabled', true, 'canManage', true, 'blockers', to_jsonb(blockers), 'provider', pay.provider, 'paymentAmount', pay.amount,
    'gift', exists(select 1 from private.gift_intents g where g.order_id = p_order_id),
    'calculationVersion', (select o.calculation_version from public.orders o where o.id = p_order_id),
    'v1Allocation', private.order_v1_allocation_state(p_order_id),
    'balance', case when pay.id is null then null else pay.amount - private.payment_partial_refunded_amount(pay.id) end,
    'items', items, 'history', history);
end $function$

CREATE OR REPLACE FUNCTION public.admin_pii_access_log(p_from date, p_to date, p_actor uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_surface text DEFAULT NULL::text, p_subject uuid DEFAULT NULL::uuid, p_flag text DEFAULT NULL::text, p_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  page_size constant integer := 50;
  total bigint;
  page integer;
  items jsonb;
  summary jsonb;
  actors jsonb;
begin
  if not public.has_operator_capability('operators.manage', true) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  perform private.validate_pii_access_log_filters(p_from, p_to, p_action, p_surface, p_flag);

  select jsonb_build_object(
      'total', count(*),
      'offHours', count(*) filter (where e.off_hours),
      'bulk', count(*) filter (where e.bulk),
      'burst', count(*) filter (where e.burst),
      'flagged', count(*) filter (where e.off_hours or e.bulk or e.burst))
  into summary
  from private.pii_access_log_entries(p_from, p_to, p_actor, p_action, p_surface, p_subject, null) e;

  select count(*) into total from private.pii_access_log_entries(p_from, p_to, p_actor, p_action, p_surface, p_subject, p_flag);
  page := least(greatest(coalesce(p_page, 1), 1), greatest(1, ((total + page_size - 1) / page_size))::integer);

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', e.id::text,
      'at', e.accessed_at,
      'actorId', e.actor_id,
      'actorName', private.pii_access_log_actor_name(e.actor_id),
      'actorAccess', e.actor_access,
      'ip', host(e.client_ip),
      'action', e.action,
      'surface', e.surface,
      'path', e.path,
      'subjectKind', e.subject_kind,
      'subjectIds', to_jsonb(e.subject_ids[1:5]),
      'subjectCount', e.subject_count,
      'memberIds', to_jsonb(e.member_ids[1:5]),
      'memberCount', cardinality(e.member_ids),
      'detail', e.detail,
      'flags', to_jsonb(array_remove(array[
        case when e.off_hours then 'off_hours' end,
        case when e.bulk then 'bulk' end,
        case when e.burst then 'burst' end], null))
    ) order by e.accessed_at desc, e.id desc), '[]'::jsonb)
  into items
  from (
    select * from private.pii_access_log_entries(p_from, p_to, p_actor, p_action, p_surface, p_subject, p_flag) x
    order by x.accessed_at desc, x.id desc
    limit page_size offset (page - 1) * page_size
  ) e;

  select coalesce(jsonb_agg(jsonb_build_object('id', a.actor_id, 'name', private.pii_access_log_actor_name(a.actor_id),
      'count', a.entries) order by a.entries desc, a.actor_id), '[]'::jsonb)
  into actors
  from (
    select e.actor_id, count(*) as entries
    from private.pii_access_log_entries(p_from, p_to, null, null, null, null, null) e
    group by e.actor_id
  ) a;

  return jsonb_build_object('from', p_from, 'to', p_to, 'page', page, 'pageSize', page_size, 'total', total,
    'summary', summary, 'items', items, 'actors', actors);
end $function$

CREATE OR REPLACE FUNCTION public.admin_plan_claim_defective_stock(p_claim_id uuid, p_order_item_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; claim public.order_cancellation_requests; ord public.orders; ids uuid[]; item record; planned_count integer; target_order uuid;
begin
  actor := private.require_operator_capability('sales.manage', false);
  if p_claim_id is null or p_order_item_ids is null or cardinality(p_order_item_ids) > 200 then
    raise invalid_parameter_value using message = 'invalid_defective_stock_plan';
  end if;
  ids := coalesce(array(select distinct x from unnest(p_order_item_ids) x order by x), '{}');
  if exists(select 1 from unnest(ids) x where x is null) then raise invalid_parameter_value using message = 'invalid_defective_stock_plan'; end if;
  select c.order_id into target_order from public.order_cancellation_requests c where c.id = p_claim_id;
  if not found then raise no_data_found using message = 'claim_not_found'; end if;
  select * into ord from public.orders where id = target_order for update;
  select * into claim from public.order_cancellation_requests where id = p_claim_id for update;
  if not found or claim.order_id <> target_order then raise sqlstate 'PT409' using message = 'defective_stock_plan_conflict'; end if;
  if claim.claim_type <> 'return' then raise check_violation using message = 'defective_stock_return_only'; end if;
  -- 재고가 정해진 뒤에는 선택을 바꿀 수 없다: 주문이 canceled(finalizer가 복원함)이거나 무통장 환불이 취소 확정 단계에 들어갔다.
  if claim.stage in ('completed','rejected','withdrawn') or ord.status = 'canceled'
    or exists(select 1 from private.bank_transfer_claim_refunds b where b.claim_id = p_claim_id or b.order_id = claim.order_id) then
    raise check_violation using message = 'defective_stock_claim_closed';
  end if;
  if exists(select 1 from unnest(ids) x where not exists(select 1 from public.order_items oi where oi.id = x and oi.order_id = claim.order_id)) then
    raise check_violation using message = 'defective_stock_item_not_in_order';
  end if;
  -- 재고 부족 부분 취소(ADR-0032)로 남은 수량이 없는 품목은 고를 수 없다. 불량 수량은 살아 있는 수량이다
  -- (부분 취소분은 이미 판매 재고로 복원됐고, restore_order_item_supply도 남은 수량만 복원한다). 출고 판정보다 먼저 본다.
  if exists(select 1 from unnest(ids) x where coalesce(private.order_item_active_qty(x), 0) <= 0) then
    raise check_violation using message = 'defective_stock_item_fully_canceled';
  end if;
  if exists(select 1 from unnest(ids) x where not private.defective_stock_item_eligible(x)) then
    raise check_violation using message = 'defective_stock_item_not_shipped';
  end if;
  -- 거절·철회됐거나 반품이 아니게 된(교환 전환) 다른 클레임의 낡은 선택은 이 품목을 막지 않는다.
  delete from private.claim_defective_stock d using public.order_cancellation_requests c
  where c.id = d.claim_id and d.state = 'planned' and d.order_item_id = any(ids) and d.claim_id <> p_claim_id
    and (c.stage in ('rejected','withdrawn') or c.claim_type <> d.source);
  if exists(select 1 from private.claim_defective_stock d where d.order_item_id = any(ids) and d.claim_id <> p_claim_id and d.state = 'planned') then
    raise unique_violation using message = 'defective_stock_item_in_other_claim';
  end if;
  delete from private.claim_defective_stock d where d.claim_id = p_claim_id and d.state = 'planned' and not (d.order_item_id = any(ids));
  for item in select oi.id, private.order_item_active_qty(oi.id) as qty from public.order_items oi where oi.id = any(ids) order by oi.id loop
    insert into private.claim_defective_stock(claim_id, order_item_id, qty, planned_by) values (p_claim_id, item.id, item.qty, actor)
    on conflict do nothing;
  end loop;
  select count(*) into planned_count from private.claim_defective_stock where claim_id = p_claim_id;
  if planned_count <> cardinality(ids) then raise sqlstate 'PT409' using message = 'defective_stock_plan_conflict'; end if;
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.order.claim_defective_stock_planned', 'order:' || claim.order_id::text,
    jsonb_build_object('claimId', p_claim_id, 'orderItemIds', to_jsonb(ids)));
  return jsonb_build_object('claimId', p_claim_id, 'planned', planned_count);
end $function$

CREATE OR REPLACE FUNCTION public.admin_plan_claim_exchange_defective_stock(p_claim_id uuid, p_shipment_id uuid, p_order_item_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; claim public.order_cancellation_requests; ord public.orders; ids uuid[]; target record; item record;
  planned_count integer; target_order uuid; collected boolean; at_value timestamptz := clock_timestamp();
begin
  actor := private.require_operator_capability('sales.manage', false);
  if p_claim_id is null or p_order_item_ids is null or cardinality(p_order_item_ids) > 200 then
    raise invalid_parameter_value using message = 'invalid_defective_stock_plan';
  end if;
  ids := coalesce(array(select distinct x from unnest(p_order_item_ids) x order by x), '{}');
  if exists(select 1 from unnest(ids) x where x is null) then raise invalid_parameter_value using message = 'invalid_defective_stock_plan'; end if;
  select c.order_id into target_order from public.order_cancellation_requests c where c.id = p_claim_id;
  if not found then raise no_data_found using message = 'claim_not_found'; end if;
  select * into ord from public.orders where id = target_order for update;
  perform 1 from public.order_shipments where order_id = target_order order by id for update;
  select * into claim from public.order_cancellation_requests where id = p_claim_id for update;
  if not found or claim.order_id <> target_order then raise sqlstate 'PT409' using message = 'defective_stock_plan_conflict'; end if;
  if claim.claim_type <> 'exchange' then raise check_violation using message = 'defective_stock_exchange_only'; end if;
  -- 재출고할 수 있는 단계(보류 중이면 보류 전 단계)의 교환만. 이 기능 전의 클레임 단위 재출고 기록이 있으면 닫힌 교환이다.
  if not (claim.stage in ('collecting','collected') or (claim.stage = 'on_hold' and claim.held_from in ('collecting','collected')))
    or ord.status = 'canceled' or claim.reship_tracking_number is not null
    or exists(select 1 from private.group_claim_reshipment_receipts r where r.claim_id = p_claim_id)
    or exists(select 1 from public.order_claim_reshipment_items ri where ri.claim_id = p_claim_id and ri.reshipment_id is null) then
    raise check_violation using message = 'defective_stock_claim_closed';
  end if;
  select * into target from private.claim_reshipment_targets(p_claim_id) t where t.shipment_id is not distinct from p_shipment_id;
  if not found then raise check_violation using message = 'reshipment_shipment_not_found'; end if;
  -- 재출고한 출고지는 재고가 정해졌다.
  if exists(select 1 from public.order_claim_reshipments r where r.claim_id = p_claim_id and r.shipment_id is not distinct from p_shipment_id) then
    raise check_violation using message = 'defective_stock_claim_closed';
  end if;
  -- 회수 생략이 효력 있는 출고지는 회수품이 창고로 오지 않는다(재출고도 회수품을 복원하지 않는다).
  if p_shipment_id is not null and private.claim_collection_waived(p_claim_id, p_shipment_id) then
    raise check_violation using message = 'exchange_defective_collection_waived';
  end if;
  collected := case when target.collection_tracked then target.collected_at is not null else claim.collected_at is not null end;
  if not collected then raise check_violation using message = 'exchange_defective_not_collected'; end if;
  if exists(select 1 from unnest(ids) x where not (x = any(target.item_ids))) then
    raise check_violation using message = 'defective_stock_item_not_in_order';
  end if;
  -- 불량 수량은 재출고가 회수품으로 되돌릴 수량(살아 있는 수량)이다. 남은 수량이 없는 품목은 고를 수 없다.
  if exists(select 1 from unnest(ids) x where coalesce(private.order_item_active_qty(x), 0) <= 0) then
    raise check_violation using message = 'defective_stock_item_fully_canceled';
  end if;
  delete from private.claim_defective_stock d using public.order_cancellation_requests c
  where c.id = d.claim_id and d.state = 'planned' and d.order_item_id = any(ids) and d.claim_id <> p_claim_id
    and (c.stage in ('rejected','withdrawn') or c.claim_type <> d.source);
  if exists(select 1 from private.claim_defective_stock d where d.order_item_id = any(ids) and d.claim_id <> p_claim_id and d.state = 'planned') then
    raise unique_violation using message = 'defective_stock_item_in_other_claim';
  end if;
  delete from private.claim_defective_stock d where d.claim_id = p_claim_id and d.state = 'planned'
    and d.order_item_id = any(target.item_ids) and not (d.order_item_id = any(ids));
  for item in select oi.id, private.order_item_active_qty(oi.id) as qty from public.order_items oi where oi.id = any(ids) order by oi.id loop
    insert into private.claim_defective_stock(claim_id, order_item_id, qty, planned_by, source, shipment_id)
    values (p_claim_id, item.id, item.qty, actor, 'exchange', p_shipment_id)
    on conflict do nothing;
  end loop;
  select count(*) into planned_count from private.claim_defective_stock d
  where d.claim_id = p_claim_id and d.state = 'planned' and d.source = 'exchange' and d.order_item_id = any(target.item_ids);
  if planned_count <> cardinality(ids) then raise sqlstate 'PT409' using message = 'defective_stock_plan_conflict'; end if;
  insert into private.claim_exchange_stock_decisions(claim_id, shipment_id, order_id, decided_by, decided_at)
  values (p_claim_id, p_shipment_id, claim.order_id, actor, at_value)
  on conflict on constraint claim_exchange_stock_decisions_key do update set decided_by = excluded.decided_by, decided_at = excluded.decided_at;
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.order.claim_defective_stock_planned', 'order:' || claim.order_id::text,
    jsonb_build_object('claimId', p_claim_id, 'claimType', 'exchange', 'shipmentId', p_shipment_id, 'originName', target.origin_name,
      'orderItemIds', to_jsonb(ids),
      'restoredOrderItemIds', to_jsonb(array(select x from unnest(target.item_ids) x where not (x = any(ids)) order by x))));
  return jsonb_build_object('claimId', p_claim_id, 'shipmentId', p_shipment_id, 'planned', planned_count, 'decided', true);
end $function$

CREATE OR REPLACE FUNCTION public.admin_prepare_gift_export(p_expected_actor_id uuid, p_state text DEFAULT 'awaiting_acceptance'::text, p_search text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare rows jsonb;receipt private.gift_export_receipts;begin
 if auth.uid() is null or auth.uid() is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_operator_required';end if;
 perform private.require_actor_operator_capability(auth.uid(),'sales.read',false);perform private.gift_console_query(p_state,p_search);
 select coalesce(jsonb_agg(private.gift_console_row(id) order by created_at desc,id desc),'[]'::jsonb) into rows from
  (select * from private.gift_console_ids(p_state,p_search) order by created_at desc,id desc limit 10001) limited;
 if jsonb_array_length(rows)>10000 then raise program_limit_exceeded using message='gift_export_limit';end if;
 insert into private.gift_export_receipts(actor_id,filters,payload,fingerprint) values(auth.uid(),jsonb_build_object('state',p_state,'query',p_search),rows,
  encode(sha256(convert_to(rows::text,'UTF8')),'hex')) returning * into receipt;
 return jsonb_build_object('receiptId',receipt.id,'fingerprint',receipt.fingerprint,'rows',rows,'total',jsonb_array_length(rows),'asOf',receipt.snapshot_at);
end $function$

