CREATE OR REPLACE FUNCTION public.admin_prepare_order_delay_notice(target_notice uuid, target_shipments uuid[], customer_title text, customer_body text, expected_ship_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid());ids uuid[];n private.order_delay_notices%rowtype;g record;v_snapshot jsonb;
 email text;buyer uuid;buyer_name text;labels text[];message text;
begin
  perform private.require_operator_capability('sales.manage',false);

 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required';end if;
 if target_notice is null or target_shipments is null or cardinality(target_shipments) not between 1 and 100
  or array_position(target_shipments,null) is not null or length(btrim(customer_title)) not between 1 and 80
  or customer_title is null or customer_title ~ '[[:cntrl:]]' or customer_body is null or length(btrim(customer_body)) not between 1 and 350
  or expected_ship_date<(statement_timestamp() at time zone 'Asia/Seoul')::date
 then raise invalid_parameter_value using message='invalid_delay_notice';end if;
 select array_agg(distinct x order by x) into ids from unnest(target_shipments)x;
 perform pg_advisory_xact_lock(hashtextextended('order_delay_notice:'||target_notice::text,0));
 select * into n from private.order_delay_notices where id=target_notice for update;
 if found then
  if n.actor_id<>actor or n.shipment_ids<>ids or n.title<>btrim(customer_title) or n.customer_body<>btrim(customer_body)
    or n.expected_ship_date is distinct from expected_ship_date then raise unique_violation using message='delay_notice_idempotency_conflict';end if;
  return public.admin_get_order_delay_notice(target_notice);
 end if;
 if (select count(*) from public.order_shipments where id=any(ids))<>cardinality(ids) then raise check_violation using message='delay_notice_ineligible';end if;
 insert into private.order_delay_notices(id,actor_id,shipment_ids,title,customer_body,expected_ship_date)
  values(target_notice,actor,ids,btrim(customer_title),btrim(customer_body),expected_ship_date);
 for g in select order_id,array_agg(id order by id) shipment_ids from public.order_shipments where id=any(ids) group by order_id order by order_id loop
  perform private.lock_order_delay_notice_target(g.order_id,g.shipment_ids);
  v_snapshot:=private.order_delay_notice_snapshot(g.order_id,g.shipment_ids);
  if v_snapshot is null then raise check_violation using message='delay_notice_ineligible';end if;
  select o.user_id,nullif(lower(btrim(p.email)),''),coalesce(nullif(p.nickname,''),'구매자') into buyer,email,buyer_name
   from public.orders o join public.profiles p on p.id=o.user_id where o.id=g.order_id;
  select array_agg(origin_name_snapshot||' · '||coalesce(shipment_number,upper(right(id::text,8))) order by id) into labels from public.order_shipments where id=any(g.shipment_ids);
  message:=btrim(customer_body)||E'\n\n발송 예정일: '||coalesce(to_char(expected_ship_date,'YYYY-MM-DD'),'확인 중')||
   E'\n안내 대상 배송 건: '||(select string_agg(coalesce(s.shipment_number,upper(right(s.id::text,8))),', ' order by s.id) from public.order_shipments s where s.id=any(g.shipment_ids[1:3]))||
   case when cardinality(g.shipment_ids)>3 then ' 외 '||(cardinality(g.shipment_ids)-3)::text||'건' else '' end;
  insert into private.order_delay_notice_targets(notice_id,order_id,buyer_id,recipient_email,buyer_name,shipment_ids,shipment_labels,snapshot,message_body,email_status,error_code)
   values(target_notice,g.order_id,buyer,email,buyer_name,g.shipment_ids,labels,v_snapshot,message,
    case when email is null or email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'suppressed' else 'prepared' end,
    case when email is null or email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'recipient_missing' else null end);
  insert into private.order_delay_notice_targets(notice_id,order_id,buyer_id,recipient_email,buyer_name,
   shipment_ids,shipment_labels,snapshot,message_body,email_status,error_code,audience)
  select target_notice,g.order_id,p.id,nullif(lower(btrim(p.email)),''),coalesce(nullif(p.nickname,''),'받는 분'),
   g.shipment_ids,labels,v_snapshot,message,
   case when p.email is null or btrim(p.email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'suppressed' else 'prepared' end,
   case when p.email is null or btrim(p.email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then 'recipient_missing' else null end,'recipient'
  from (select order_id,recipient_id from private.gift_intents) gift
  join public.profiles p on p.id=gift.recipient_id where gift.order_id=g.order_id;
 end loop;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.delay_notice_prepared','delay_notice:'||target_notice,
  jsonb_build_object('orders',(select count(*) from private.order_delay_notice_targets where notice_id=target_notice),'shipments',cardinality(ids),'channels',jsonb_build_array('in_app','email')));
 return public.admin_get_order_delay_notice(target_notice);
end $function$

CREATE OR REPLACE FUNCTION public.admin_prepare_subscription_inspection(p_expected_actor_id uuid, p_cycle_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare actor uuid:=auth.uid();cycle private.goods_subscription_cycles;request jsonb;result jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id or p_operation_id is null then raise insufficient_privilege using message='subscription_operator_required';end if;
 perform private.require_actor_operator_capability(actor,'sales.manage',false);
 request:=jsonb_build_object('cycleId',p_cycle_id);
 perform pg_advisory_xact_lock(hashtextextended('subscription-inspection:'||p_operation_id::text,0));
 result:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.subscription.inspection_requested',request);if result is not null then return result;end if;
 select * into cycle from private.goods_subscription_cycles where id=p_cycle_id;
 if not found or cycle.dispatched_at is null or cycle.state not in('dispatching','unknown','needs_review') then raise object_not_in_prerequisite_state using message='subscription_inspection_unavailable';end if;
 result:=jsonb_build_object('operationId',p_operation_id,'cycleId',cycle.id,'planId',cycle.plan_id);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.subscription.inspection_requested','subscription-cycle:'||p_cycle_id::text,
  jsonb_build_object('request',request,'result',result));return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_preview_claim_return_intake(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare settings private.return_pickup_settings; matches jsonb;
begin
  perform private.require_operator_capability('sales.manage', false);
  select * into settings from private.return_pickup_settings where singleton;
  if not found or not settings.intake_enabled then raise check_violation using message = 'claim_return_intake_disabled'; end if;
  matches := private.claim_return_intake_match(p_rows);
  return jsonb_build_object('rows', matches, 'counts', coalesce((select jsonb_object_agg(t.status, t.n)
    from (select value->>'status' status, count(*) n from jsonb_array_elements(matches) group by 1) t), '{}'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.admin_preview_coupon_issue(p_id uuid, p_coupon_code text, p_targets jsonb, p_expected_actor uuid, p_expected_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;coupon public.coupons;segment private.customer_segments;batch private.coupon_issue_batches;ids uuid[];target jsonb;request jsonb;rows jsonb;result jsonb;
 needed integer;existing integer;invalid integer;issue text;at_value timestamptz:=clock_timestamp();
begin
 actor:=private.coupon_issue_identity(p_expected_actor,p_expected_session);
 if p_id is null or p_coupon_code is null or p_coupon_code!~'^[A-Z0-9][A-Z0-9-]{2,23}$' or jsonb_typeof(p_targets) is distinct from 'object' then raise invalid_parameter_value using message='invalid_coupon_issue';end if;
 if p_targets->>'kind'='customers' then
  if (select count(*) from jsonb_object_keys(p_targets))<>2 or jsonb_typeof(p_targets->'userIds') is distinct from 'array' or jsonb_array_length(p_targets->'userIds') not between 1 and 1000
   or exists(select 1 from jsonb_array_elements(p_targets->'userIds') v where jsonb_typeof(v)<>'string' or v#>>'{}'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then raise invalid_parameter_value using message='invalid_coupon_issue_targets';end if;
  select array_agg(value::uuid order by value::uuid) into ids from jsonb_array_elements_text(p_targets->'userIds');
  if cardinality(ids)<>(select count(distinct v) from unnest(ids) v) then raise invalid_parameter_value using message='duplicate_coupon_issue_target';end if;
  target:=jsonb_build_object('kind','customers','userIds',to_jsonb(ids));
 elsif p_targets->>'kind'='segment' then
  if (select count(*) from jsonb_object_keys(p_targets))<>3 or p_targets->>'segmentId'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(p_targets->'revision') is distinct from 'number' or p_targets->>'revision'!~'^[1-9][0-9]{0,8}$' then raise invalid_parameter_value using message='invalid_coupon_issue_targets';end if;
  target:=p_targets;
 else raise invalid_parameter_value using message='invalid_coupon_issue_targets';end if;
 request:=jsonb_build_object('couponCode',p_coupon_code,'targets',target,'sessionId',p_expected_session);
 perform pg_advisory_xact_lock(hashtextextended('coupon-issue-batch:'||p_id::text,0));
 select * into batch from private.coupon_issue_batches where id=p_id;
 if found then
  if batch.actor_id<>actor or batch.request is distinct from request then raise sqlstate 'PT409' using message='coupon_issue_operation_conflict';end if;
  return private.coupon_issue_batch_document(p_id);
 end if;
 if target->>'kind'='segment' then
  select * into segment from private.customer_segments where id=(target->>'segmentId')::uuid and archived_at is null for share;
  if not found or segment.revision<>(target->>'revision')::integer or not private.customer_segment_references_available(segment.rule) then raise sqlstate 'PT409' using message='customer_segment_changed';end if;
  select coalesce(array_agg(customer_id order by customer_id),'{}') into ids from (select customer_id from private.customer_segment_members(segment.rule,at_value) order by customer_id limit 1001) members;
  if cardinality(ids)>1000 then raise program_limit_exceeded using message='coupon_issue_target_limit';end if;
 end if;
 select * into coupon from public.coupons where code=p_coupon_code for share;
 if not found or coupon.status<>'active' then raise check_violation using message='coupon_not_found';end if;
 if at_value<coalesce(coupon.issue_starts_at,coupon.starts_at) then raise check_violation using message='coupon_issue_not_started';end if;
 if (case when coupon.issue_starts_at is null then coupon.ends_at else coupon.issue_ends_at end)<=at_value or coupon.ends_at<=at_value then raise check_violation using message='coupon_issue_ended';end if;
 rows:=private.coupon_issue_rows(coupon,ids);
 select count(*) filter(where value->>'reason' is null and value->>'userCouponId' is null),count(*) filter(where value->>'userCouponId' is not null),count(*) filter(where value->>'reason' is not null)
  into needed,existing,invalid from jsonb_array_elements(rows);
 issue:=case when cardinality(ids)=0 then 'coupon_issue_no_targets' when invalid>0 then 'coupon_issue_invalid_targets' when coupon.issue_limit is not null and needed>coupon.issue_limit-coupon.issued_count then 'coupon_exhausted' end;
 result:=jsonb_build_object('id',p_id,'couponCode',coupon.code,'couponName',coupon.name,'couponRevision',coupon.terms_revision,'targetKind',target->>'kind',
  'segmentName',segment.name,'status',case when issue is null then 'prepared' else 'invalid' end,'targetCount',cardinality(ids),'plannedCount',needed,'existingCount',existing,'invalidCount',invalid,
  'issuedCount',0,'createdAt',at_value,'validUntil',at_value+interval '15 minutes','finishedAt',null,'error',issue,'rows',rows);
 insert into private.coupon_issue_batches(id,actor_id,session_id,coupon_code,coupon_revision,targets,user_ids,segment_rule,request,status,result,created_at,valid_until)
 values(p_id,actor,p_expected_session,coupon.code,coupon.terms_revision,target,ids,segment.rule,request,result->>'status',result,at_value,at_value+interval '15 minutes');
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.coupon.issue_previewed','coupon_issue_batch:'||p_id,jsonb_build_object('couponCode',coupon.code,'targetCount',cardinality(ids),'plannedCount',needed));
 return private.coupon_issue_batch_document(p_id);
end $function$

CREATE OR REPLACE FUNCTION public.admin_preview_discount_promotion(p_id uuid, p_request jsonb, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior private.discount_promotion_operations; kind text; target_ids text[]; ids text[]; label text; g public.goods;
  rows jsonb:='[]'::jsonb; guards jsonb:='{}'::jsonb; applied integer:=0; window_range tstzrange; rule jsonb; skip text; overlap jsonb;
  min_price integer; max_price integer; next_min integer; next_max integer; expires timestamptz; result jsonb;
begin
  perform private.require_goods_group_identity(p_actor,p_session);
  perform private.discount_promotion_validate(p_request);
  if p_id is null then raise invalid_parameter_value using message='discount_promotion_invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('discount-promotion:'||p_id::text,0));
  select * into prior from private.discount_promotion_operations where id=p_id;
  if found then
    if prior.actor_id<>p_actor or prior.session_id<>p_session or prior.request<>p_request then
      raise sqlstate 'PT409' using message='discount_promotion_operation_conflict';
    end if;
    if prior.receipt is not null or prior.expires_at<=clock_timestamp() then
      raise sqlstate 'PT409' using message='discount_promotion_preview_expired';
    end if;
    return prior.preview;
  end if;
  if (p_request->>'endsAt')::timestamptz<=clock_timestamp() then raise check_violation using message='discount_promotion_period_ended'; end if;
  kind:=p_request#>>'{target,kind}';
  target_ids:=array(select value from jsonb_array_elements_text(p_request#>'{target,ids}') with ordinality item(value,ordinality) order by ordinality);
  if kind='campaign' then
    select title into label from public.campaigns where id=target_ids[1];
    if not found then raise check_violation using message='discount_promotion_campaign_unavailable'; end if;
    -- 기획전 본문의 굿즈 블록 순서대로, 처음 나온 자리를 쓴다. 지금 없는 상품 ID는 대상이 아니다.
    ids:=array(select entry.good_id from (
        select item.value good_id,min(section.ordinality*100+item.ordinality) first_seen
        from public.campaigns campaign
        cross join lateral jsonb_array_elements(campaign.sections) with ordinality section(value,ordinality)
        cross join lateral jsonb_array_elements_text(case when section.value->>'type'='goods' and jsonb_typeof(section.value->'good_ids')='array'
          then section.value->'good_ids' else '[]'::jsonb end) with ordinality item(value,ordinality)
        where campaign.id=target_ids[1] and exists(select 1 from public.goods where id=item.value)
        group by item.value) entry order by entry.first_seen,entry.good_id);
  elsif kind='ip' then
    select title into label from public.ips where id=target_ids[1] and archived_at is null;
    if not found then raise check_violation using message='discount_promotion_ip_unavailable'; end if;
    ids:=array(select id from public.goods where ip_id=target_ids[1] and archived_at is null order by id);
  else
    ids:=target_ids;
    if (select count(*) from public.goods where id=any(ids))<>cardinality(ids) then
      raise check_violation using message='discount_promotion_good_unavailable';
    end if;
  end if;
  if coalesce(cardinality(ids),0)=0 then raise check_violation using message='discount_promotion_no_goods'; end if;
  if cardinality(ids)>1000 then raise check_violation using message='discount_promotion_target_limit'; end if;
  if exists(select 1 from jsonb_array_elements(p_request->'exceptions') item where not (item->>'goodId'=any(ids))) then
    raise check_violation using message='discount_promotion_exception_outside_target';
  end if;
  window_range:=tstzrange((p_request->>'startsAt')::timestamptz,(p_request->>'endsAt')::timestamptz,'[)');
  -- 요약과 지문을 같은 시점에 고정한다(일괄 변경과 같은 잠금). 판매로 인한 재고 변동은 지문에 들지 않는다.
  begin
    perform 1 from public.goods where id=any(ids) order by id for share nowait;
    perform 1 from public.goods_variants where good_id=any(ids) order by id for share nowait;
  exception when lock_not_available then raise sqlstate 'PT409' using message='discount_promotion_busy';
  end;
  for g in select goods.* from unnest(ids) with ordinality target(id,ordinality) join public.goods goods on goods.id=target.id order by target.ordinality loop
    rule:=coalesce(
      (select jsonb_build_object('source','exception','mode',item->>'mode','value',item->'value')
        from jsonb_array_elements(p_request->'exceptions') item where item->>'goodId'=g.id),
      jsonb_build_object('source','default','mode',p_request#>>'{rule,mode}','value',p_request#>'{rule,value}'));
    select min(price),max(price) into min_price,max_price from public.goods_variants where good_id=g.id and archived_at is null;
    skip:=null; overlap:=null; next_min:=null; next_max:=null;
    if rule->>'mode'='exclude' then skip:='discount_promotion_excluded';
    elsif g.archived_at is not null then skip:='good_archived';
    elsif g.compare_at_price is not null and g.compare_at_price>g.price then skip:='instant_discount_active';
    elsif min_price is null then skip:='price_period_variant_inactive';
    else
      select jsonb_build_object('promotionId',period.promotion_id,'promotionName',promotion.name,'startsAt',period.starts_at,'endsAt',period.ends_at)
        into overlap
      from public.goods_variants variant
      join private.goods_variant_price_periods period on period.variant_id=variant.id and period.good_id=variant.good_id
      left join private.discount_promotions promotion on promotion.id=period.promotion_id
      where variant.good_id=g.id and variant.archived_at is null and period.state='active'
        and tstzrange(period.starts_at,period.ends_at,'[)') && window_range
      order by period.starts_at,period.id limit 1;
      if overlap is not null then skip:='price_period_overlap';
      elsif exists(select 1 from public.goods_variants variant where variant.good_id=g.id and variant.archived_at is null
          and private.discount_promotion_price(g.price,variant.price,rule) is null) then skip:='goods_bulk_price_invalid';
      else
        select min(private.discount_promotion_price(g.price,variant.price,rule)),max(private.discount_promotion_price(g.price,variant.price,rule))
          into next_min,next_max from public.goods_variants variant where variant.good_id=g.id and variant.archived_at is null;
      end if;
    end if;
    if skip is null then
      applied:=applied+1;
      guards:=guards||jsonb_build_object(g.id,private.goods_bulk_price_fingerprint(g.id));
    end if;
    rows:=rows||jsonb_build_array(jsonb_build_object('id',g.id,'name',g.name,'code',g.code,'price',g.price,
      'priceMin',min_price,'priceMax',max_price,'nextMin',next_min,'nextMax',next_max,
      'published',g.published_at is not null,'archived',g.archived_at is not null,'rule',rule,'skip',skip,'overlap',overlap));
  end loop;
  if applied=0 then raise check_violation using message='discount_promotion_all_skipped'; end if;
  expires:=clock_timestamp()+interval '15 minutes';
  result:=jsonb_build_object('state','ready','operationId',p_id,'request',p_request,
    'target',jsonb_build_object('kind',kind,'ids',to_jsonb(target_ids),'label',label),'goods',rows,'expiresAt',expires);
  insert into private.discount_promotion_operations(id,actor_id,session_id,request,guards,preview,expires_at)
  values(p_id,p_actor,p_session,p_request,guards,result,expires);
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_preview_erp_linked_goods(p_operation_id uuid, p_codes text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_existing private.erp_goods_apply_operations;
  v_codes text[];
  v_plan jsonb;
  v_rows jsonb;
  v_total integer;
  v_expires timestamptz := pg_catalog.clock_timestamp() + interval '15 minutes';
  v_result jsonb;
begin
  perform private.require_operator_capability('catalog.manage', false);
  if v_actor is null or not public.has_operator_capability('catalog.manage', false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if p_operation_id is null then
    raise invalid_parameter_value using message = 'invalid_erp_goods_apply_request';
  end if;
  if p_codes is not null then
    if pg_catalog.cardinality(p_codes) not between 1 and 5000
       or exists (select 1 from pg_catalog.unnest(p_codes) as code(value)
                  where code.value is null or pg_catalog.length(code.value) > 200) then
      raise invalid_parameter_value using message = 'invalid_erp_goods_apply_request';
    end if;
    -- 반입과 같은 규칙으로 다듬어 저장된 ERP 코드와 맞춘다.
    select coalesce(pg_catalog.array_agg(distinct normalized.value), array[]::text[]) into v_codes
    from (select private.erp_item_text(code.value, false) as value from pg_catalog.unnest(p_codes) as code(value)) as normalized
    where normalized.value is not null;
  end if;

  select * into v_existing from private.erp_goods_apply_operations where id = p_operation_id;
  if found then
    if v_existing.actor_id <> v_actor then
      raise insufficient_privilege using message = 'erp_goods_apply_unavailable';
    end if;
    return v_existing.preview;
  end if;

  -- 지난 미리보기·영수증은 30일만 둔다(반영 내역은 감사 기록에 남는다).
  delete from private.erp_goods_apply_operations where created_at < pg_catalog.clock_timestamp() - interval '30 days';

  v_plan := private.erp_linked_goods_plan(v_codes);
  v_total := pg_catalog.jsonb_array_length(v_plan -> 'rows');
  select coalesce(pg_catalog.jsonb_agg(entry.value order by entry.ordinality), '[]'::jsonb) into v_rows
  from pg_catalog.jsonb_array_elements(v_plan -> 'rows') with ordinality as entry(value, ordinality)
  where entry.ordinality <= 500;

  v_result := pg_catalog.jsonb_build_object(
    'operationId', p_operation_id,
    'expiresAt', v_expires,
    'scopeCount', case when v_codes is null then null else pg_catalog.cardinality(v_codes) end,
    'linked', v_plan -> 'linked',
    'total', v_total,
    'truncated', v_total > 500,
    'rows', v_rows);

  if v_total > 0 then
    insert into private.erp_goods_apply_operations (id, actor_id, scope_codes, preview, expires_at)
    values (p_operation_id, v_actor, v_codes, v_result, v_expires);
  end if;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_preview_goods_bulk(p_id uuid, p_request jsonb, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior private.goods_bulk_operations;ids text[];groups jsonb:='[]';rows jsonb:='[]';guards jsonb:='{}';g public.goods;
 next_price integer;min_price integer;max_price integer;next_min integer;next_max integer;expires timestamptz;result jsonb;
 command text:=p_request->>'command';kind text:=p_request->>'kind';target_limit integer;skip text;applied integer:=0;
 window_range tstzrange;discounts jsonb;instant jsonb;
begin
 perform private.require_goods_group_identity(p_actor,p_session);
 perform private.goods_bulk_validate(p_request);
 if p_id is null then raise invalid_parameter_value using message='goods_bulk_invalid';end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-bulk:'||p_id::text,0));
 select * into prior from private.goods_bulk_operations where id=p_id;
 if found then
  if prior.actor_id<>p_actor or prior.session_id<>p_session or prior.request<>p_request then raise sqlstate 'PT409' using message='goods_bulk_operation_conflict';end if;
  if prior.receipt is not null or prior.expires_at<=clock_timestamp() then raise sqlstate 'PT409' using message='goods_bulk_preview_expired';end if;
  return prior.preview;
 end if;
 -- Group membership is stable while expanding the exact selected group set.
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 target_limit:=case when kind='ip' then 1000 else 100 end;
 if kind='groups' then
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'revision',revision) order by id),'[]') into groups
   from private.goods_groups where id in(select value::uuid from jsonb_array_elements_text(p_request->'ids')) and archived_at is null;
  if jsonb_array_length(groups)<>jsonb_array_length(p_request->'ids') then raise check_violation using message='goods_bulk_group_unavailable';end if;
  select array_agg(distinct good_id order by good_id) into ids from private.goods_group_members
   where group_id in(select value::uuid from jsonb_array_elements_text(p_request->'ids'));
 elsif kind='ip' then
  -- The IP filter result: every non-archived good of that IP at preview time.
  if not exists(select 1 from public.ips where id=p_request->'ids'->>0 and archived_at is null) then raise check_violation using message='goods_bulk_ip_unavailable';end if;
  select array_agg(id order by id) into ids from public.goods where ip_id=p_request->'ids'->>0 and archived_at is null;
 else select array_agg(value order by value) into ids from jsonb_array_elements_text(p_request->'ids');end if;
 if coalesce(cardinality(ids),0) not between 1 and target_limit then raise check_violation using message='goods_bulk_target_limit';end if;
 if (select count(*) from public.goods where id=any(ids))<>cardinality(ids) then raise check_violation using message='goods_bulk_good_unavailable';end if;
 if command='discount' then window_range:=tstzrange((p_request#>>'{values,startsAt}')::timestamptz,(p_request#>>'{values,endsAt}')::timestamptz,'[)');end if;
 -- One statement owns both the summary and fingerprint to avoid torn previews.
 for g in select * from public.goods where id=any(ids) order by id for share nowait loop
  perform 1 from public.goods_variants where good_id=g.id order by id for share nowait;
  if g.archived_at is not null and command not in ('restore','archive','dissolve') then raise check_violation using message='good_archived';end if;
  next_price:=case when command='price' then private.goods_bulk_price(g.price,p_request->'values') else g.price end;
  select min(price),max(price) into min_price,max_price from public.goods_variants where good_id=g.id and archived_at is null;
  next_min:=min_price;next_max:=max_price;skip:=null;discounts:=null;instant:=null;
  if command='price' then
   -- Same predicate as private.guard_goods_variant_period_price (every option, current or upcoming).
   if exists(select 1 from private.goods_variant_price_periods p where p.good_id=g.id and p.state='active' and p.ends_at>statement_timestamp()) then
    raise check_violation using message='active_price_period_requires_reset';end if;
   if g.compare_at_price is not null and g.compare_at_price<=next_price then raise check_violation using message='goods_compare_at_price_invalid';end if;
   if exists(select 1 from public.goods_variants where good_id=g.id and (price<g.price or price::bigint-g.price+next_price>2147483647)) then
    raise check_violation using message='goods_bulk_price_invalid';end if;
   next_min:=min_price-g.price+next_price;next_max:=max_price-g.price+next_price;
  elsif command='discount' then
   -- A good is skipped (not the whole batch) when it cannot take this discount.
   if g.compare_at_price is not null and g.compare_at_price>g.price then skip:='instant_discount_active';
   elsif min_price is null then skip:='price_period_variant_inactive';
   elsif exists(select 1 from public.goods_variants v join private.goods_variant_price_periods p on p.variant_id=v.id and p.good_id=v.good_id
     where v.good_id=g.id and v.archived_at is null and p.state='active' and tstzrange(p.starts_at,p.ends_at,'[)') && window_range) then skip:='price_period_overlap';
   elsif exists(select 1 from public.goods_variants v where v.good_id=g.id and v.archived_at is null and private.goods_bulk_discount_price(v.price,p_request->'values') is null) then skip:='goods_bulk_price_invalid';
   else next_min:=private.goods_bulk_price(min_price,p_request->'values');next_max:=private.goods_bulk_price(max_price,p_request->'values');end if;
  elsif command='discount_stop' then
   select case when count(*)=0 then null else jsonb_build_object('count',count(*),'minPrice',min(p.discount_price),'maxPrice',max(p.discount_price),
     'startsAt',min(p.starts_at),'endsAt',max(p.ends_at)) end into discounts
    from private.goods_variant_price_periods p where p.good_id=g.id and p.state='active' and p.ends_at>statement_timestamp();
   if p_request#>>'{values,includeInstant}'='true' and g.compare_at_price is not null and g.compare_at_price>g.price then
    instant:=jsonb_build_object('regularPrice',g.compare_at_price,'salePrice',g.price);
    next_price:=g.compare_at_price;next_min:=min_price-g.price+g.compare_at_price;next_max:=max_price-g.price+g.compare_at_price;
   end if;
   if discounts is null and instant is null then skip:='no_active_discount';end if;
  end if;
  if skip is null then applied:=applied+1;end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('id',g.id,'name',g.name,'code',g.code,'price',g.price,'nextPrice',next_price,
   'priceMin',min_price,'priceMax',max_price,'nextMin',next_min,'nextMax',next_max,'published',g.published_at is not null,
   'archived',g.archived_at is not null,'stopped',g.stock='soldout','skip',skip,'discounts',discounts)||case when instant is null then '{}'::jsonb else jsonb_build_object('instantDiscount',instant) end);
  guards:=guards||jsonb_build_object(g.id,case when command in ('discount','discount_stop') then private.goods_bulk_price_fingerprint(g.id) else private.goods_bulk_fingerprint(g.id) end);
 end loop;
 if applied=0 then raise check_violation using message=case when command='discount_stop' then 'goods_bulk_no_active_discount' else 'goods_bulk_all_skipped' end;end if;
 expires:=clock_timestamp()+interval '15 minutes';
 result:=jsonb_build_object('state','ready','operationId',p_id,'request',p_request,'groups',groups,'goods',rows,'expiresAt',expires);
 insert into private.goods_bulk_operations(id,actor_id,session_id,request,guards,preview,expires_at) values(p_id,p_actor,p_session,p_request,guards,result,expires);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_preview_goods_group_conversion(p_request jsonb, p_expected_actor_id uuid, p_expected_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_id text;preview private.goods_group_conversion_previews;plan jsonb;blockers text[];
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 perform private.validate_goods_group_conversion(p_request);
 source_id:=p_request->>'sourceGoodId';
 perform private.goods_group_lock_conversion_source(source_id);
 blockers:=private.goods_group_conversion_blockers(source_id);
 if cardinality(blockers)>0 then return jsonb_build_object('state','blocked','blockers',to_jsonb(blockers));end if;
 if exists(select 1 from jsonb_array_elements(p_request->'selections') s
  left join public.goods_variants v on v.id=(s->>'variantId')::uuid and v.good_id=source_id and v.archived_at is null
  where v.id is null) then raise check_violation using message='goods_group_selection_changed';end if;
 plan:=jsonb_build_object('sourceGoodId',source_id,'name',p_request->'name','optionNames',p_request->'optionNames',
  'members',(select jsonb_agg(jsonb_build_object('sourceVariantId',v.id,'sourceVariantName',v.name,'values',s.value->'values',
    'retainsGoodId',s.ordinality=1,'goodId',case when s.ordinality=1 then source_id end,
    'price',v.price,'stockQty',v.stock_qty,'name',p_request->>'name'||' '||array_to_string(array(select jsonb_array_elements_text(s.value->'values')),' / ')) order by s.ordinality)
    from jsonb_array_elements(p_request->'selections') with ordinality s(value,ordinality)
    join public.goods_variants v on v.id=(s.value->>'variantId')::uuid),
  'unselectedOptions',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'name',v.name,'stockQty',v.stock_qty) order by v.sort_order,v.id)
    from public.goods_variants v where v.good_id=source_id and v.archived_at is null
      and not exists(select 1 from jsonb_array_elements(p_request->'selections') s where s->>'variantId'=v.id::text)),'[]'::jsonb),
  'requiresKcReview',true,'allProductsUnpublished',true,'aggregationPreserved',true,
  'historicalOrdersPreserved',true,'unselectedStockPreserved',true,'activeCartSelectionsRequireReview',true);
 insert into private.goods_group_conversion_previews(actor_id,session_id,request,source_hash,public_plan)
 values(p_expected_actor_id,p_expected_session_id,p_request,private.goods_group_source_hash(source_id),plan) returning * into preview;
 return jsonb_build_object('state','ready','previewId',preview.id,'expiresAt',preview.expires_at,'plan',preview.public_plan);
