CREATE OR REPLACE FUNCTION public.admin_preview_stock_reconcile(p_origin_id uuid, p_as_of timestamp with time zone, p_source_label text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;label text;snapshot uuid;resolved jsonb;matched integer;issues jsonb;variant_ids uuid[];now_at timestamptz:=clock_timestamp();
begin
  actor:=private.require_operator_capability('catalog.manage',false);
  label:=btrim(coalesce(p_source_label,''),E' \t\n\r\f\v');
  if p_as_of is null or p_as_of>now_at+interval '5 minutes' or p_as_of<now_at-interval '7 days' then
    raise invalid_parameter_value using message='invalid_stock_reconcile_as_of';
  end if;
  if char_length(label) not between 1 and 200 or label ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message='invalid_stock_reconcile_label';
  end if;
  if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 2000 then
    raise invalid_parameter_value using message='invalid_stock_reconcile_rows';
  end if;
  -- CASE로 순서를 고정한다(OR는 평가 순서를 보장하지 않아 객체가 아닌 값에 jsonb_each·형 변환이 먼저 돌 수 있다).
  if exists(select 1 from jsonb_array_elements(p_rows) x where case
      when jsonb_typeof(x) is distinct from 'object' then true
      when jsonb_typeof(x->'row') is distinct from 'number' or (x->>'row')!~'^[1-9][0-9]{0,8}$' then true
      when jsonb_typeof(x->'qty') is distinct from 'number' or (x->>'qty')!~'^(0|[1-9][0-9]{0,8})$' then true
      when (x->>'qty')::bigint>100000000 then true
      when not (x ? 'goodsCode' or x ? 'optionCode' or x ? 'erpCode' or x ? 'barcode') then true
      else exists(select 1 from jsonb_each(x) field where field.key not in ('row','qty','goodsCode','optionCode','erpCode','barcode')
        or (field.key<>'row' and field.key<>'qty' and case when jsonb_typeof(field.value) is distinct from 'string' then true
          else char_length(btrim(field.value#>>'{}')) not between 1 and 200 or (field.value#>>'{}') ~ '[[:cntrl:]]' end))
    end)
    or (select count(distinct x->>'row') from jsonb_array_elements(p_rows) x)<>jsonb_array_length(p_rows) then
    raise invalid_parameter_value using message='invalid_stock_reconcile_rows';
  end if;
  if p_origin_id is not null and not exists(select 1 from public.fulfillment_origins where id=p_origin_id) then
    raise no_data_found using message='fulfillment_origin_not_found';
  end if;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.source_row),'[]'::jsonb) into resolved
  from private.stock_reconcile_resolve(p_rows,p_origin_id) r;
  select count(*) into matched from jsonb_to_recordset(resolved) as r(issue text) where r.issue is null;
  select coalesce(jsonb_agg(jsonb_build_object('row',r.source_row,'key',r.match_key,'fileQty',r.file_qty,'reason',r.issue) order by r.source_row),'[]'::jsonb)
    into issues from jsonb_to_recordset(resolved) as r(source_row integer,match_key text,file_qty integer,issue text) where r.issue is not null;
  variant_ids:=array(select (e->>'variant_id')::uuid from jsonb_array_elements(resolved) e where e->>'issue' is null);

  insert into private.stock_reconcile_snapshots(origin_id,source_label,as_of,created_by,created_at,row_count,matched_count,issue_count,issues)
  values(p_origin_id,label,p_as_of,actor,now_at,jsonb_array_length(p_rows),matched,jsonb_array_length(issues),issues)
  returning id into snapshot;

  insert into private.stock_reconcile_snapshot_items(snapshot_id,variant_id,good_id,source_row,match_kind,file_qty,stock_qty,
    pending_qty,shipped_since_qty,returned_since_qty,awaiting_return_qty,adjusted_since_count,adjusted_since_qty,difference,target_qty)
  select snapshot,r.variant_id,v.good_id,r.source_row,r.match_kind,r.file_qty,v.stock_qty,
    f.pending_qty::integer,f.shipped_since_qty::integer,f.returned_since_qty::integer,f.awaiting_return_qty::integer,
    adj.adjusted_count,adj.adjusted_qty::integer,
    (r.file_qty::bigint-(v.stock_qty::bigint+f.pending_qty+f.awaiting_return_qty+f.shipped_since_qty-f.returned_since_qty))::integer,
    greatest(r.file_qty::bigint-f.pending_qty-f.awaiting_return_qty-f.shipped_since_qty+f.returned_since_qty,0)::integer
  from jsonb_to_recordset(resolved) as r(source_row integer,variant_id uuid,good_id text,match_kind text,file_qty integer,issue text)
  join public.goods_variants v on v.id=r.variant_id
  join private.stock_reconcile_flows(variant_ids,p_as_of) f on f.variant_id=r.variant_id
  join private.stock_reconcile_adjustments(variant_ids,p_as_of) adj on adj.variant_id=r.variant_id
  where r.issue is null;

  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.stock_reconcile.previewed','stock_reconcile:'||snapshot,
    jsonb_build_object('originId',p_origin_id,'asOf',p_as_of,'sourceLabel',label,'rows',jsonb_array_length(p_rows),
      'matched',matched,'issues',jsonb_array_length(issues)));
  return private.stock_reconcile_document(snapshot);
end $function$

CREATE OR REPLACE FUNCTION public.admin_preview_store_credit_batch(p_id uuid, p_targets text[], p_amount bigint, p_expires_at timestamp with time zone, p_reason text, p_purpose text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; policy private.store_credit_policy; previous private.store_credit_batches; payload jsonb; rows jsonb:='[]';
 target text; matched uuid; matches integer; balance jsonb; issue text; seen uuid[]:='{}'; invalid integer:=0; offset_total bigint:=0; result jsonb;
begin
  perform private.require_operator_capability('marketing.manage',true);

 actor:=private.assert_store_credit_admin();
 if p_id is null or coalesce(cardinality(p_targets),0) not between 1 and 1000 or p_amount is null or p_amount not between 1 and 999999999999
  or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 or p_purpose is null or p_purpose not in ('promotion','general')
  or exists(select 1 from unnest(p_targets) t where t is null or length(btrim(t)) not between 1 and 200)
  then raise invalid_parameter_value using message='store_credit_batch_invalid'; end if;
 payload:=jsonb_build_object('targets',to_jsonb(p_targets),'amount',p_amount,'expiresAt',p_expires_at,'reason',btrim(p_reason),'purpose',p_purpose);
 perform pg_advisory_xact_lock(hashtextextended('store_credit_batch:'||p_id::text,0));
 select * into previous from private.store_credit_batches where id=p_id;
 if found then
  if previous.actor_id<>actor or previous.payload is distinct from payload then raise exception using errcode='PT409',message='store_credit_batch_conflict'; end if;
  return previous.result;
 end if;
 select * into policy from private.store_credit_policy where singleton for share;
 if not policy.enabled then raise check_violation using message='store_credit_disabled'; end if;
 if p_expires_at is null or p_expires_at<=clock_timestamp() or p_expires_at>clock_timestamp()+make_interval(days=>policy.validity_days)
  then raise check_violation using message='store_credit_expiry_invalid'; end if;
 foreach target in array p_targets loop
  issue:=null; matched:=null; balance:='{"available":0,"reserved":0,"debt":0}';
  select count(*), (array_agg(id order by id))[1] into matches,matched from public.profiles where id::text=btrim(target) or lower(email)=lower(btrim(target));
  if matches<>1 then issue:='customer_not_found';
  elsif matched=any(seen) then issue:='duplicate_customer';
  else
   seen:=array_append(seen,matched); balance:=private.store_credit_preview_balance(matched);
   if exists(select 1 from public.profiles where id=matched and suspended_at is not null) or exists(select 1 from private.account_action_fences fence where fence.subject_user_id=matched) then issue:='customer_unavailable';
   elsif p_amount>(balance->>'debt')::bigint and (balance->>'available')::bigint+(balance->>'reserved')::bigint+p_amount-(balance->>'debt')::bigint>policy.max_balance then issue:='store_credit_balance_limit'; end if;
  end if;
  if issue is not null then invalid:=invalid+1; else offset_total:=offset_total+least(p_amount,(balance->>'debt')::bigint); end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('target',target,'userId',matched,'nickname',(select nickname from public.profiles where id=matched),
   'error',issue,'balance',balance,'offset',case when issue is null then least(p_amount,(balance->>'debt')::bigint) else 0 end));
 end loop;
 result:=jsonb_build_object('id',p_id,'status',case when invalid>0 then 'invalid' else 'prepared' end,'purpose',p_purpose,'reason',btrim(p_reason),
  'amount',p_amount,'expiresAt',p_expires_at,'count',cardinality(p_targets),'invalidCount',invalid,'gross',p_amount*cardinality(p_targets),
  'offset',offset_total,'net',p_amount*cardinality(p_targets)-offset_total,'rows',rows,'createdAt',clock_timestamp(),'error',null);
 if invalid=0 then
  insert into private.store_credit_batches(id,actor_id,purpose,amount,reason,expires_at,policy_version,payload,result)
   values(p_id,actor,p_purpose,p_amount,btrim(p_reason),p_expires_at,policy.version,payload,result);
  insert into private.store_credit_batch_recipients(batch_id,user_id,operation_id,expected_balance)
   select p_id,(r->>'userId')::uuid,extensions.gen_random_uuid(),r->'balance' from jsonb_array_elements(rows) r;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_process_member_withdrawal(target_profile_id uuid, target_inquiry_reference bigint, target_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  note text := pg_catalog.btrim(coalesce(target_note, ''), E' \t\n\r\f\v');
  inquiry_owner uuid;
  blockers jsonb;
  suspension jsonb;
  changed_at timestamptz;
  consent record;
  revoked integer;
  erased_address integer;
  erased_phone integer;
  withdrawn_marketing integer := 0;
  erased_demographics integer;
  erased_activity_events integer;
  withdrawn_activity integer;
  erased_email_changes integer;
  erased_restock_alerts integer;
  erased jsonb;
begin
  perform private.lock_operator_subjects(array[actor, target_profile_id]);
  perform private.require_operator_capability('platform.manage', false);

  if target_profile_id is null or target_inquiry_reference is null or target_inquiry_reference < 1
    or pg_catalog.char_length(note) not between 2 and 200 or pg_catalog.translate(note, E'\n\t', '') ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message = 'invalid_member_withdrawal';
  end if;
  if target_profile_id = actor then
    raise exception 'cannot_withdraw_self' using errcode = '22023';
  end if;
  if not exists (select 1 from public.profiles p where p.id = target_profile_id) then
    raise exception 'profile_not_found' using errcode = 'P0002';
  end if;

  -- 이미 처리한 회원: 처음 기록을 돌려준다. 재로그인 차단 전에 다시 로그인했을 수 있어 세션만 다시 끊는다.
  if exists (select 1 from private.member_withdrawal_processings w where w.user_id = target_profile_id) then
    revoked := private.revoke_member_auth_sessions(target_profile_id);
    return private.member_withdrawal_document(target_profile_id)
      || jsonb_build_object('status', 'already_processed', 'revokedSessions', revoked);
  end if;

  select i.user_id into inquiry_owner from public.inquiries i where i.reference = target_inquiry_reference;
  if inquiry_owner is null or inquiry_owner <> target_profile_id then
    raise no_data_found using message = 'member_withdrawal_inquiry_not_found';
  end if;

  -- 탈퇴 신청과 같은 진행 중 의무 판정. 운영자 소속(매니저 역할)은 프로필 역할과 별개라 따로 본다.
  blockers := private.account_deletion_blockers(target_profile_id);
  if exists (select 1 from private.operator_memberships m where m.profile_id = target_profile_id)
    and not blockers @> '[{"code":"staff_handover"}]'::jsonb then
    blockers := blockers || jsonb_build_array(jsonb_build_object('code', 'staff_handover', 'count', 1, 'path', '/settings'));
  end if;
  if blockers <> '[]'::jsonb then
    return jsonb_build_object('status', 'blocked', 'blockers', blockers);
  end if;

  suspension := public.admin_suspend_user(target_profile_id,
    pg_catalog.left('탈퇴 요청 처리 · 문의 #' || target_inquiry_reference::text || ' · ' || note, 200));
  changed_at := pg_catalog.clock_timestamp();

  erased_address := private.erase_member_address_book(target_profile_id);
  erased_phone := private.erase_member_phone(target_profile_id);

  -- 마케팅 정보 수신 동의: 동의 중인 수단마다 철회를 원장에 남기고 파생값을 맞춘다(원장 먼저 — 동기화 트리거는 같으면 아무것도 하지 않는다).
  for consent in
    select c.channel, c.notice_version from private.customer_marketing_consents c
    where c.user_id = target_profile_id and c.agreed order by c.channel
  loop
    perform private.write_customer_marketing_consent(target_profile_id, consent.channel, false, consent.notice_version,
      'member_withdrawal', changed_at);
    withdrawn_marketing := withdrawn_marketing + 1;
  end loop;
  update public.profiles set consents = jsonb_set(coalesce(consents, '{}'::jsonb), '{marketing}', 'false'::jsonb, true)
  where id = target_profile_id and consents->'marketing' is distinct from 'false'::jsonb;

  -- 탈퇴 봉인 트리거(erase_fenced_customer_demographics·member_activity_fenced·erase_fenced_member_email_change)와 같은 범위.
  update private.customer_demographic_consents
  set choice = 'declined', gender = null, accepted_at = null, revision = revision + 1, updated_at = changed_at
  where user_id = target_profile_id and choice = 'accepted';
  get diagnostics erased_demographics = row_count;
  delete from private.member_activity_events where user_id = target_profile_id;
  get diagnostics erased_activity_events = row_count;
  update private.member_activity_consents
  set choice = 'declined', accepted_at = null, revision = revision + 1, updated_at = changed_at
  where user_id = target_profile_id and choice = 'accepted';
  get diagnostics withdrawn_activity = row_count;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-email:user:' || target_profile_id::text, 0));
  delete from private.member_email_change_challenges where user_id = target_profile_id;
  get diagnostics erased_email_changes = row_count;
  -- 재입고 알림은 정지와 무관하게 메일·알림을 보내므로 아직 알리지 않은(대기) 신청을 지운다. 알린 기록(발송 이력)은 남긴다.
  delete from public.restock_alerts where user_id = target_profile_id and status = 'pending';
  get diagnostics erased_restock_alerts = row_count;

  revoked := private.revoke_member_auth_sessions(target_profile_id);
  erased := jsonb_build_object(
    'addressBookEntries', erased_address,
    'phoneNumbers', erased_phone,
    'marketingConsents', withdrawn_marketing,
    'demographicConsents', erased_demographics,
    'activityEvents', erased_activity_events,
    'activityConsents', withdrawn_activity,
    'emailChangeRequests', erased_email_changes,
    'restockAlerts', erased_restock_alerts);

  insert into private.member_withdrawal_processings (user_id, inquiry_reference, processed_by, processed_at)
  values (target_profile_id, target_inquiry_reference, actor, changed_at);
  insert into public.audit_log (actor_id, action, target, diff)
  values (actor, 'admin.member.withdrawal_processed', 'profile:' || target_profile_id::text, jsonb_build_object(
    'inquiryReference', target_inquiry_reference,
    'suspended', coalesce((suspension->>'changed')::boolean, false),
    'erased', erased,
    'revokedSessions', revoked));

  return private.member_withdrawal_document(target_profile_id) || jsonb_build_object(
    'status', 'processed',
    'suspended', coalesce((suspension->>'changed')::boolean, false),
    'erased', erased,
    'revokedSessions', revoked);
end $function$

CREATE OR REPLACE FUNCTION public.admin_process_review_best_reward(p_review_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.require_operator_capability('cs.manage',true);
 if p_review_id is null then raise invalid_parameter_value;end if;
 perform private.process_review_best_reward_jobs(p_review_id,30);
 return public.admin_get_review_best_reward(p_review_id);
