CREATE OR REPLACE FUNCTION public.admin_retry_claim_return_pickup(p_claim_id uuid, p_bundle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); settings private.return_pickup_settings; pickup private.claim_return_pickups; next_state text;
begin
  perform private.require_operator_capability('sales.manage', false);
  if actor is null or not public.has_operator_capability('sales.manage', false) then raise insufficient_privilege using message = 'staff required'; end if;
  select * into settings from private.return_pickup_settings where singleton;
  if not found or not settings.pickup_enabled then raise check_violation using message = 'return_pickup_disabled'; end if;
  select * into pickup from private.claim_return_pickups where bundle_id = p_bundle_id and claim_id = p_claim_id for update;
  if not found then raise no_data_found using message = 'return_pickup_not_found'; end if;
  if pickup.lease_until is not null and pickup.lease_until > clock_timestamp() then raise sqlstate 'PT409' using message = 'return_pickup_in_progress'; end if;
  if pickup.state not in ('failed','cancel_failed') then
    return jsonb_build_object('pickupId', pickup.id, 'state', pickup.state, 'nextAttemptAt', pickup.next_attempt_at, 'replayed', true);
  end if;
  next_state := case pickup.state when 'failed' then 'pending' else 'cancel_pending' end;
  update private.claim_return_pickups set state = next_state, next_attempt_at = clock_timestamp(),
    retry_base = case when pickup.state = 'failed' then attempts else retry_base end,
    cancel_retry_base = case when pickup.state = 'cancel_failed' then cancel_attempts else cancel_retry_base end,
    lease_token = null, lease_until = null, updated_at = clock_timestamp()
  where id = pickup.id;
  insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome, actor_id) values (pickup.id, 'retry', 'scheduled', actor);
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.order.claim_return_pickup_retried', 'order:' || pickup.order_id,
    jsonb_build_object('claimId', pickup.claim_id, 'bundleId', pickup.bundle_id, 'pickupId', pickup.id, 'previousState', pickup.state,
      'lastErrorCode', pickup.last_error_code, 'attempts', pickup.attempts, 'cancelAttempts', pickup.cancel_attempts));
  return jsonb_build_object('pickupId', pickup.id, 'state', next_state, 'nextAttemptAt', clock_timestamp(), 'replayed', false);
end $function$

CREATE OR REPLACE FUNCTION public.admin_retry_order_delay_notice(target_notice uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid());t private.order_delay_notice_targets%rowtype;i private.email_intents%rowtype;retried integer:=0;
begin
  perform private.require_operator_capability('sales.manage',false);

 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required';end if;
 if not (select enabled from private.order_delay_notice_delivery_control where singleton) then raise check_violation using message='delay_notice_delivery_disabled';end if;
 perform 1 from private.order_delay_notices where id=target_notice and requested_at is not null for update;
 if not found then raise no_data_found using message='delay_notice_not_found';end if;
 for t in select * from private.order_delay_notice_targets where notice_id=target_notice and email_status='failed' and retryable order by order_id for update loop
  select * into i from private.email_intents where id=t.email_intent_id for update;
  if i.id is not null and i.idempotency_expires_at<=now()+interval '5 minutes' and i.accepted_at is null then
   update private.order_delay_notice_targets set email_status='unknown',error_code='delivery_needs_review',retryable=false,available_at=null,updated_at=now() where id=t.id;
   continue;
  end if;
  if i.id is not null and (i.accepted_at is not null or i.state not in ('queued','unknown')) then continue;end if;
  perform private.lock_order_delay_notice_target(t.order_id,t.shipment_ids);
  if not private.order_delay_notice_target_current(t.id) then
   update private.order_delay_notice_targets set email_status=case when coalesce(i.attempt_count,0)>0 then 'unknown' else 'suppressed' end,
    error_code='target_changed',retryable=false,available_at=null,updated_at=now() where id=t.id;
  else
   update private.order_delay_notice_targets set email_status='queued',retryable=false,available_at=now(),error_code=null,updated_at=now() where id=t.id;retried:=retried+1;
  end if;
 end loop;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.delay_notice_retried','delay_notice:'||target_notice,jsonb_build_object('queuedEmails',retried));
 return public.admin_get_order_delay_notice(target_notice);
end $function$

CREATE OR REPLACE FUNCTION public.admin_review_rating_comparison(p_as_of date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare contract private.review_rating_observation_contracts; comparison_day date; observation private.review_rating_daily_observations; state text;
begin
 if current_setting('role',true) is distinct from 'authenticated' or auth.uid() is null or not public.has_operator_capability('cs.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';end if;
 if p_as_of is null or not isfinite(p_as_of) then raise invalid_parameter_value using message='invalid_review_rating_date';end if;
 if p_as_of<>(statement_timestamp() at time zone 'Asia/Seoul')::date-1 then
  raise sqlstate 'PT409' using message='review_rating_date_changed';end if;
 select * into strict contract from private.review_rating_observation_contracts order by version desc limit 1;
 perform private.assert_review_rating_contract(contract.version);
 comparison_day:=(p_as_of::timestamp-interval '3 months')::date;
 select * into observation from private.review_rating_daily_observations where version=contract.version and as_of=comparison_day;
 state:=case when found then 'available'
  when contract.collection_started_at is null or comparison_day+1<(contract.collection_started_at at time zone 'Asia/Seoul')::date then 'before_collection_start'
  when comparison_day<contract.purged_before_as_of then 'outside_retention' else 'not_collected' end;
 return jsonb_build_object('version',contract.version,'asOf',p_as_of,'comparisonAsOf',comparison_day,'status',state,
  'enabled',contract.enabled,'collectionStartedAt',contract.collection_started_at,'lastSuccessAt',contract.last_success_at,
  'purgedBeforeAsOf',contract.purged_before_as_of,'lastPurgedAt',contract.last_purged_at,
  'observation',case when state<>'available' then null else jsonb_build_object('version',observation.version,'asOf',observation.as_of,
   'observationDay',observation.observation_day,'observedAt',observation.observed_at,'sixMonthFrom',observation.six_month_from,
   'averageRating',round(observation.average_rating,2),'sixMonthRating',round(observation.six_month_rating,2),
   'eligibleProductCount',observation.eligible_product_count,'ratedProductCount',observation.rated_product_count,
   'sixMonthRatedProductCount',observation.six_month_rated_product_count,'reviewCount',observation.review_count,
   'sixMonthReviewCount',observation.six_month_review_count,'fingerprint',observation.fingerprint) end);
end $function$

CREATE OR REPLACE FUNCTION public.admin_revoke_review_event_award(p_entry_id uuid, p_operation_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); target_user uuid; event_id uuid; request jsonb; receipt jsonb;
begin
 select user_id,a.event_id into target_user,event_id from private.review_event_awards a where entry_id=p_entry_id;
 perform private.lock_operator_subjects(array[actor,target_user]);perform private.require_operator_capability('marketing.manage',true);
 if p_entry_id is null or p_operation_id is null or char_length(btrim(coalesce(p_reason,''))) not between 2 and 500 then raise invalid_parameter_value using message='invalid_review_event_revoke';end if;
 request:=jsonb_build_object('entryId',p_entry_id,'reason',btrim(p_reason));
 perform pg_advisory_xact_lock(hashtextextended('review-event:operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.review_event.reward_revoked',request);if receipt is not null then return receipt;end if;
 if target_user is null then raise no_data_found using message='review_event_award_missing';end if;
 perform private.reverse_review_event_award(p_entry_id,btrim(p_reason),actor);
 receipt:=private.review_event_document(event_id);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.review_event.reward_revoked','review_event_entry:'||p_entry_id,jsonb_build_object('request',request,'result',receipt));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_sales_goods_page(p_from timestamp with time zone, p_to timestamp with time zone, p_ip_id text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ip text := nullif(btrim(p_ip_id), '');
  v_result jsonb;
begin
  if not public.has_operator_capability('stats.read', false) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  -- UI selection is at most 366 days; a previous-year derived range can be 367.
  if p_from is null or p_to is null or not isfinite(p_from) or not isfinite(p_to)
    or p_to <= p_from or p_to - p_from > interval '367 days' then
    raise invalid_parameter_value using message = 'invalid_report_range';
  end if;
  -- 10001 is an export sentinel; the application rejects exports over 10000.
  if p_page is null or p_page < 1 or p_page_size is null
    or p_page_size not in (20, 50, 100, 10001) then
    raise invalid_parameter_value using message = 'invalid_report_page';
  end if;

  with goods as materialized (
    select item.good_id,
      max(item.good_name_snapshot) as name,
      max(item.good_ip_id_snapshot) as ip_id,
      sum(private.order_item_active_qty(item.id)) as qty,
      sum(item.qty::numeric*item.unit_price::numeric-coalesce((select allocation.volume_discount from private.order_price_allocations allocation where allocation.order_item_id=item.id),0)
        -(select c.gross_amount from private.order_item_partial_cancel_totals(item.id) c)) as revenue
    from public.order_items item
    join public.orders purchase on purchase.id = item.order_id
    where purchase.status = any (private.revenue_order_statuses())
      and purchase.created_at >= p_from and purchase.created_at < p_to
      and (v_ip is null or item.good_ip_id_snapshot = v_ip)
    group by item.good_id having sum(private.order_item_active_qty(item.id)) > 0
  ), totals as (
    select count(*) as total_count from goods
  ), paging as (
    select total_count,
      least(p_page::bigint, greatest(1::bigint, (total_count + p_page_size - 1) / p_page_size)) as page
    from totals
  ), ranked as (
    select goods.*, row_number() over (order by revenue desc, qty desc, good_id) as rank
    from goods
  )
  select jsonb_build_object(
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rank', row.rank, 'goodId', row.good_id, 'name', row.name,
        'ipId', row.ip_id, 'qty', row.qty, 'revenue', row.revenue
      ) order by row.rank)
      from (
        select * from ranked
        order by rank limit p_page_size offset ((paging.page - 1) * p_page_size)
      ) row
    ), '[]'::jsonb),
    'totalCount', paging.total_count,
    'page', paging.page,
    'pageSize', p_page_size,
    'asOf', statement_timestamp()
  ) into v_result from paging;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_sales_hourly_report(p_compare_date date DEFAULT NULL::date, p_ip_id text DEFAULT NULL::text, p_cutoff timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_as_of timestamptz := statement_timestamp();
  v_today date := (v_as_of at time zone 'Asia/Seoul')::date;
  v_start timestamptz := v_today::timestamp at time zone 'Asia/Seoul';
  v_latest timestamptz := date_trunc('hour',v_as_of at time zone 'Asia/Seoul') at time zone 'Asia/Seoul';
  v_cutoff timestamptz := coalesce(p_cutoff,v_latest);
  v_compare date := coalesce(p_compare_date,v_today-7);
  v_compare_start timestamptz;
  v_compare_cutoff timestamptz;
  v_hours integer;
  v_ip text := nullif(btrim(coalesce(p_ip_id,'')),'');
  result jsonb;
begin
  if (select auth.uid()) is null or not public.has_operator_capability('stats.read',false) then
    raise insufficient_privilege using message='operator_capability_required';
  end if;
  if not isfinite(v_compare) or v_compare<date '0001-01-01' or v_compare>=v_today or length(v_ip)>64
    or not isfinite(v_cutoff) or v_cutoff<v_start or v_cutoff>v_latest
    or date_trunc('hour',v_cutoff at time zone 'Asia/Seoul')<>(v_cutoff at time zone 'Asia/Seoul') then
    raise invalid_parameter_value using message='invalid_sales_hourly_filters';
  end if;
  v_compare_start := v_compare::timestamp at time zone 'Asia/Seoul';
  v_compare_cutoff := v_compare_start+(v_cutoff-v_start);
  v_hours := extract(epoch from (v_cutoff-v_start))::integer/3600;

  -- Both calendar days and both ranking windows share this statement snapshot.
  -- At midnight the last completed hour belongs to the preceding calendar day.
  with ranges(side,starts_at,ends_at,day_starts_at) as (
    values ('current',least(v_start,v_cutoff-interval '1 hour'),v_cutoff,v_start),
      ('comparison',least(v_compare_start,v_compare_cutoff-interval '1 hour'),v_compare_cutoff,v_compare_start)
  ), scoped as materialized (
    select r.side,r.day_starts_at,r.ends_at,o.id,o.total-private.order_partial_refunded_amount(o.id) as total,o.created_at
    from ranges r join public.orders o on o.created_at>=r.starts_at and o.created_at<r.ends_at
    where o.status=any(private.revenue_order_statuses())
  ), hourly as (
    select side,extract(hour from created_at at time zone 'Asia/Seoul')::integer as hour,
      count(*) as orders,coalesce(sum(total),0) as revenue
    from scoped where created_at>=day_starts_at group by side,hour
  ), hours as (
    select h.hour,
      case when h.hour<v_hours then coalesce(c.orders,0) end as orders,
      case when h.hour<v_hours then coalesce(c.revenue,0) end as revenue,
      case when h.hour<v_hours then coalesce(p.orders,0) end as comparison_orders,
      case when h.hour<v_hours then coalesce(p.revenue,0) end as comparison_revenue
    from generate_series(0,23) h(hour)
    left join hourly c on c.side='current' and c.hour=h.hour
    left join hourly p on p.side='comparison' and p.hour=h.hour
  ), accumulated as (
    select *,
      case when hour<v_hours then sum(orders) over(order by hour) end as cumulative_orders,
      case when hour<v_hours then sum(revenue) over(order by hour) end as cumulative_revenue,
      case when hour<v_hours then sum(comparison_orders) over(order by hour) end as comparison_cumulative_orders,
      case when hour<v_hours then sum(comparison_revenue) over(order by hour) end as comparison_cumulative_revenue
    from hours
  ), goods as materialized (
    select w.period,s.side,item.good_id,max(item.good_name_snapshot) as name,
      max(item.good_ip_id_snapshot) as ip_id,sum(private.order_item_active_qty(item.id)) as qty,
      sum(item.qty::numeric*item.unit_price::numeric-coalesce((select allocation.volume_discount from private.order_price_allocations allocation where allocation.order_item_id=item.id),0)
      -(select c.gross_amount from private.order_item_partial_cancel_totals(item.id) c)) as revenue
    from scoped s join public.order_items item on item.order_id=s.id
    cross join (values ('today'),('lastHour')) w(period)
    where (v_ip is null or item.good_ip_id_snapshot=v_ip)
      and s.created_at>=case when w.period='today' then s.day_starts_at else s.ends_at-interval '1 hour' end
    group by w.period,s.side,item.good_id having sum(private.order_item_active_qty(item.id)) > 0
  ), ranked as (
    select goods.*,row_number() over(partition by period order by revenue desc,qty desc,good_id) as rank
    from goods where side='current'
  ), top_goods as (
    select c.period,c.rank,c.good_id,c.name,c.ip_id,c.qty,c.revenue,
      coalesce(p.qty,0) as comparison_qty,coalesce(p.revenue,0) as comparison_revenue
    from ranked c left join goods p on p.side='comparison' and p.period=c.period and p.good_id=c.good_id
    where c.rank<=10
  )
  select jsonb_build_object(
    'asOf',v_as_of,'date',v_today,'comparisonDate',v_compare,'cutoff',v_cutoff,
    'comparisonCutoff',v_compare_cutoff,'completedHours',v_hours,'ipId',coalesce(v_ip,''),
    'lastHourFrom',v_cutoff-interval '1 hour','comparisonLastHourFrom',v_compare_cutoff-interval '1 hour',
    'summary',jsonb_build_object(
      'current',case when v_hours>0 then jsonb_build_object('orderCount',(select coalesce(sum(orders),0) from hours),'revenue',(select coalesce(sum(revenue),0) from hours)) end,
      'comparison',case when v_hours>0 then jsonb_build_object('orderCount',(select coalesce(sum(comparison_orders),0) from hours),'revenue',(select coalesce(sum(comparison_revenue),0) from hours)) end
    ),
    'hours',(select jsonb_agg(jsonb_build_object(
      'hour',hour,'orderCount',orders,'revenue',revenue,
      'comparisonOrderCount',comparison_orders,'comparisonRevenue',comparison_revenue,
      'cumulativeOrderCount',cumulative_orders,'cumulativeRevenue',cumulative_revenue,
      'comparisonCumulativeOrderCount',comparison_cumulative_orders,'comparisonCumulativeRevenue',comparison_cumulative_revenue
    ) order by hour) from accumulated),
    'todayGoods',coalesce((select jsonb_agg(jsonb_build_object(
      'rank',rank,'goodId',good_id,'name',name,'ipId',ip_id,'qty',qty,'revenue',revenue,
      'comparisonQty',comparison_qty,'comparisonRevenue',comparison_revenue
    ) order by rank) from top_goods where period='today'),'[]'::jsonb),
    'lastHourGoods',coalesce((select jsonb_agg(jsonb_build_object(
      'rank',rank,'goodId',good_id,'name',name,'ipId',ip_id,'qty',qty,'revenue',revenue,
      'comparisonQty',comparison_qty,'comparisonRevenue',comparison_revenue
    ) order by rank) from top_goods where period='lastHour'),'[]'::jsonb)
  ) into result;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_sales_order_counts(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_query text DEFAULT NULL::text, p_field text DEFAULT 'all'::text, p_date_field text DEFAULT 'ordered'::text, p_payment_method text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;needle text:=nullif(btrim(p_query),'');
begin
  if not public.has_operator_capability('sales.read',false) then raise insufficient_privilege using message='operator_capability_required'; end if;

 if (select auth.uid()) is null or not public.has_operator_capability('sales.read',false) then raise insufficient_privilege using message='staff required';end if;
 perform private.admin_validate_sales_search(p_field,p_date_field,'newest',p_payment_method,p_from,p_to,needle);
 select jsonb_object_agg(known.value,coalesce(matched.total,0)) into result
 from unnest(enum_range(null::public.order_status)) known(value)
 left join (select o.status,count(*) total from public.orders o
  where private.admin_sales_order_matches(o,p_from,p_to,needle,p_field,p_date_field,p_payment_method)
  group by o.status) matched on matched.status=known.value;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_auto_order_confirmation(p_enabled boolean, p_run_time text, p_expected_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;previous private.auto_order_confirmation_settings;request jsonb;receipt jsonb;at_value timestamptz;
begin
 actor:=private.require_operator_capability('sales.manage',false);
 if p_enabled is null or p_run_time is null or p_run_time!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'
  or p_expected_revision is null or p_expected_revision<1 or p_operation_id is null then
  raise invalid_parameter_value using message='invalid_auto_order_confirmation';end if;
 request:=jsonb_build_object('enabled',p_enabled,'runTime',p_run_time,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('auto-order-confirmation-operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.auto_order_confirmation.settings',request);
 if receipt is not null then return receipt;end if;
 select * into previous from private.auto_order_confirmation_settings where singleton for update;
 if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='auto_order_confirmation_changed';end if;
 at_value:=clock_timestamp();
 update private.auto_order_confirmation_settings set revision=revision+1,enabled=p_enabled,run_time=p_run_time::time,
  enabled_at=case when p_enabled and not previous.enabled then at_value else previous.enabled_at end,
  updated_by=actor,updated_at=at_value where singleton;
 -- 끄면 이어 가던 실행도 닫는다. 다시 켜면 새 켠 시각 기준의 실행이 새로 시작된다.
 if not p_enabled then
  perform private.finish_auto_order_confirmation_run(r.run_date,'disabled')
  from private.auto_order_confirmation_runs r where r.finished_at is null order by r.run_date;
 end if;
 receipt:=private.auto_order_confirmation_document(at_value);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.auto_order_confirmation.settings','auto_order_confirmation',
  jsonb_build_object('request',request,'before',jsonb_build_object('enabled',previous.enabled,'runTime',to_char(previous.run_time,'HH24:MI'),'enabledAt',previous.enabled_at),'result',receipt));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_campaign_presentation(target_campaign_id text, target_popup_mode text, target_popup_location text, target_card_link_path text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_id text := btrim(coalesce(target_campaign_id, ''), E' \t\n\r\f\v');
  normalized_mode text := nullif(btrim(coalesce(target_popup_mode, ''), E' \t\n\r\f\v'), '');
  normalized_location text := nullif(btrim(coalesce(target_popup_location, ''), E' \t\n\r\f\v'), '');
  normalized_link text := nullif(btrim(coalesce(target_card_link_path, ''), E' \t\n\r\f\v'), '');
  before_value jsonb;
  after_value jsonb;
begin
  perform private.require_operator_capability('promotion.manage', false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.has_operator_capability('promotion.manage', false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  perform 1 from public.campaigns where id = normalized_id for update;

  if not found then
    raise exception 'campaign_not_found' using errcode = 'P0002';
  end if;

  -- POP-UP 에 싣지 않으면 장소도 없다.
  if normalized_mode is null then
    normalized_location := null;
  end if;

  if (normalized_mode is not null and normalized_mode not in ('online', 'offline', 'hybrid'))
    or (normalized_location is not null and char_length(normalized_location) > 120)
    or (normalized_link is not null
      and (char_length(normalized_link) > 300 or (normalized_link !~ '^/(?![/\\])[^\s\\]*$' or normalized_link ~* '^[^?#]*/(\.|%2e){1,2}([/?#]|$)'))) then
    raise exception 'invalid_campaign_presentation' using errcode = '22023';
  end if;

  select jsonb_build_object('popupMode', p.popup_mode, 'popupLocation', p.popup_location, 'cardLinkPath', p.card_link_path)
  into before_value
  from public.campaign_presentations p
  where p.campaign_id = normalized_id;

  if normalized_mode is null and normalized_location is null and normalized_link is null then
    delete from public.campaign_presentations where campaign_id = normalized_id;
    after_value := null;
  else
    insert into public.campaign_presentations (campaign_id, popup_mode, popup_location, card_link_path, updated_at, updated_by)
    values (normalized_id, normalized_mode, normalized_location, normalized_link, now(), actor_id)
    on conflict (campaign_id) do update set
      popup_mode = excluded.popup_mode,
      popup_location = excluded.popup_location,
      card_link_path = excluded.card_link_path,
      updated_at = excluded.updated_at,
      updated_by = excluded.updated_by;
    after_value := jsonb_build_object('popupMode', normalized_mode, 'popupLocation', normalized_location, 'cardLinkPath', normalized_link);
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'admin.campaign.presentation_saved',
    'campaigns:' || normalized_id,
    jsonb_build_object('before', before_value, 'after', after_value)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_catalog_category_templates(p_items jsonb, p_archived boolean, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); item jsonb; items jsonb; request jsonb; receipt jsonb;
  previous private.catalog_category_templates; snapshot jsonb; before_rows jsonb:='[]'; result_rows jsonb:='[]'; category uuid; expected integer;
begin
  perform private.require_actor_operator_capability(actor,'catalog.manage');
  if p_archived is null or p_operation_id is null or p_items is null or jsonb_typeof(p_items)<>'array' then
    raise invalid_parameter_value using message='invalid_category_templates';
  end if;
  if jsonb_array_length(p_items) not between 1 and 100 then raise invalid_parameter_value using message='invalid_category_templates';end if;
  for item in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(item)<>'object' or jsonb_typeof(item->'categoryId') is distinct from 'string'
      or jsonb_typeof(item->'revision') is distinct from 'number'
      or (item->>'revision')!~'^[0-9]{1,9}$'
      or exists(select 1 from jsonb_object_keys(item) key where key not in ('categoryId','revision')) then
      raise invalid_parameter_value using message='invalid_category_templates';
    end if;
    begin category:=(item->>'categoryId')::uuid; exception when invalid_text_representation then raise invalid_parameter_value using message='invalid_category_templates';end;
  end loop;
  if (select count(distinct (value->>'categoryId')::uuid) from jsonb_array_elements(p_items))<>jsonb_array_length(p_items) then
    raise invalid_parameter_value using message='invalid_category_templates';
  end if;
  select jsonb_agg(jsonb_build_object('categoryId',(value->>'categoryId')::uuid,'revision',(value->>'revision')::integer) order by (value->>'categoryId')::uuid)
    into items from jsonb_array_elements(p_items);
  request:=jsonb_build_object('items',items,'archived',p_archived);
  perform pg_advisory_xact_lock(hashtextextended('category-template-operation:'||p_operation_id::text,0));
  receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.catalog.category_templates.saved',request);
  if receipt is not null then return receipt;end if;
  -- The same lock as catalog edits prevents a leaf from gaining a child between validation and commit.
  perform private.lock_catalog_category_tree();
  for item in select value from jsonb_array_elements(items) loop
    category:=(item->>'categoryId')::uuid;expected:=(item->>'revision')::integer;
    snapshot:=private.catalog_category_template_document(category);
    if snapshot is null then raise no_data_found using message='category_not_found';end if;
    if not p_archived and not (snapshot->>'usable')::boolean then raise check_violation using message='category_not_usable';end if;
    select * into previous from private.catalog_category_templates where category_id=category for update;
    if coalesce(previous.revision,0)<>expected or (previous.category_id is null and p_archived) then
      raise sqlstate 'PT409' using message='category_templates_changed';
    end if;
    before_rows:=before_rows||jsonb_build_array(snapshot);
    insert into private.catalog_category_templates(category_id,updated_by) values(category,actor)
    on conflict(category_id) do update set revision=catalog_category_templates.revision+1,
      archived_at=case when p_archived then coalesce(catalog_category_templates.archived_at,clock_timestamp()) else null end,
      updated_at=clock_timestamp(),updated_by=actor;
    result_rows:=result_rows||jsonb_build_array(private.catalog_category_template_document(category));
  end loop;
  receipt:=jsonb_build_object('rows',result_rows);
