CREATE OR REPLACE FUNCTION public.admin_save_category_display(p_category_id uuid, p_values jsonb, p_expected_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;previous private.category_display_compositions;before_values jsonb;request jsonb;receipt public.audit_log;result jsonb;artwork_path text;category jsonb;
begin
 actor:=private.require_operator_capability('store.manage',false);
 if p_category_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 or not private.category_display_valid(p_values)
 then raise invalid_parameter_value using message='invalid_category_display';end if;
 request:=jsonb_build_object('categoryId',p_category_id,'values',p_values,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('category-display-operation:'||p_operation_id::text,0));
 select * into receipt from public.audit_log where id=p_operation_id;
 if found then
  if receipt.actor_id=actor and receipt.action='admin.category_display.saved' and receipt.target='category-display:'||p_category_id::text and receipt.diff->'request'=request then return receipt.diff->'result';end if;
  raise unique_violation using message='operation_conflict';
 end if;
 -- Same existing tree lock as category/assignment writers, before product rows.
 perform pg_advisory_xact_lock(hashtextextended('catalog_category_tree',0));
 category:=private.category_display_category(p_category_id);if category is null then raise no_data_found using message='category_not_found';end if;
 perform 1 from public.catalog_categories c where c.id in(select value::uuid from jsonb_array_elements_text(p_values->'categoryIds')) order by c.id for share;
 if exists(select 1 from jsonb_array_elements_text(p_values->'categoryIds') id where private.category_display_source_category(id::uuid) is null) then raise check_violation using message='category_source_missing';end if;
 perform 1 from public.goods g where g.id in(
  select value from jsonb_array_elements_text(p_values->'goodIds') union select value from jsonb_array_elements_text(p_values#>'{recommendations,goodIds}')
  union select p_values#>>'{video,goodId}' union select good_id from private.category_display_goods where category_id=p_category_id
  union select video_good_id from private.category_display_compositions where category_id=p_category_id
 ) order by g.id for share;
 if exists(select 1 from (select value id from jsonb_array_elements_text(p_values->'goodIds') union select value from jsonb_array_elements_text(p_values#>'{recommendations,goodIds}') union select p_values#>>'{video,goodId}') selected
  where selected.id is not null and not exists(select 1 from public.goods g where g.id=selected.id)) then raise check_violation using message='category_display_good_missing';end if;
 insert into private.category_display_compositions(category_id,banner,recommendations)
 values(p_category_id,private.category_display_defaults(p_category_id)->'banner',(private.category_display_defaults(p_category_id)->'recommendations')-'goodIds') on conflict(category_id) do nothing;
 select * into previous from private.category_display_compositions where category_id=p_category_id for update;
 if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='category_display_conflict';end if;
 before_values:=private.category_display_values(p_category_id);
 for artwork_path in select distinct value from jsonb_each_text(p_values->'banner') where key in('imagePath','mobileImagePath') and value is not null
  and value is distinct from previous.banner->>'imagePath' and value is distinct from previous.banner->>'mobileImagePath' order by value
 loop
  update public.admin_artwork_upload_claims as claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
  where claim.actor_id=actor and claim.path=substr(artwork_path,length('public-media/')+1) and claim.kind='curation'
   and claim.status='verified' and claim.verified_at is not null and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
  if not found then raise check_violation using message='unverified_artwork';end if;
 end loop;
 delete from private.category_display_sources where category_id=p_category_id;
 insert into private.category_display_sources(category_id,source_category_id,position)
 select p_category_id,value::uuid,ordinality-1 from jsonb_array_elements_text(p_values->'categoryIds') with ordinality;
 delete from private.category_display_goods where category_id=p_category_id;
 insert into private.category_display_goods(category_id,slot,good_id,position)
 select p_category_id,'main',value,ordinality-1 from jsonb_array_elements_text(p_values->'goodIds') with ordinality
 union all select p_category_id,'recommend',value,ordinality-1 from jsonb_array_elements_text(p_values#>'{recommendations,goodIds}') with ordinality;
 update private.category_display_compositions set enabled=(p_values->>'enabled')::boolean,mode=p_values->>'mode',banner=p_values->'banner',
  video_enabled=(p_values#>>'{video,enabled}')::boolean,video_good_id=p_values#>>'{video,goodId}',recommendations=(p_values->'recommendations')-'goodIds',
  revision=previous.revision+1,updated_at=greatest(clock_timestamp(),updated_at+interval '1 microsecond') where category_id=p_category_id;
 result:=jsonb_build_object('category',category,'revision',previous.revision+1,'values',private.category_display_values(p_category_id),'checkedAt',clock_timestamp());
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.category_display.saved','category-display:'||p_category_id::text,jsonb_build_object('request',request,'before',before_values,'result',result));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_claim_collection_plan(p_claim uuid, p_shipment uuid, p_revision bigint, p_claim_revision integer, p_values jsonb, p_operation uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_key uuid;parties uuid[];c public.order_cancellation_requests;plan private.claim_collection_plans;prior private.claim_collection_events;
 request jsonb;result jsonb;original jsonb;requested boolean;sent boolean;begin
 perform private.purchase_confirmation_identity(p_actor,p_session,true);
 if p_claim is null or p_shipment is null or p_operation is null or p_revision is null or p_revision<0 or p_claim_revision is null or p_claim_revision<0
  or not private.transaction_json_keys(p_values,array['method','carrier','trackingNumber','evidence','confirmed'])
  or coalesce(p_values->>'method','') not in('not_requested','seller_arranged','customer_sent') or p_values->'confirmed' is distinct from 'true'::jsonb
  or jsonb_typeof(p_values->'evidence') is distinct from 'string' or char_length(btrim(p_values->>'evidence')) not between 2 and 500
  or (p_values->>'evidence')~'[[:cntrl:]]'
  or (p_values->'carrier'='null'::jsonb) is distinct from (p_values->'trackingNumber'='null'::jsonb)
  or not(p_values->'carrier'='null'::jsonb or jsonb_typeof(p_values->'carrier')='string' and jsonb_typeof(p_values->'trackingNumber')='string' and p_values->>'trackingNumber'~'^[A-Z0-9]{8,40}$')
  or p_values->>'method'='not_requested' and p_values->'carrier'<>'null'::jsonb
  or p_values->>'method'='customer_sent' and p_values->'carrier'='null'::jsonb then raise invalid_parameter_value using message='claim_collection_invalid';end if;
 select order_id into order_key from public.order_cancellation_requests where id=p_claim;
 if order_key is null then raise no_data_found using message='claim_not_found';end if;
 parties:=private.contact_parties(order_key);perform private.lock_operator_subjects(parties);
 if exists(select 1 from private.account_action_fences where subject_user_id=any(parties)) then raise insufficient_privilege;end if;
 perform pg_advisory_xact_lock(hashtextextended('claim-collection:'||p_operation,0));
 request:=jsonb_build_object('claimId',p_claim,'shipmentId',p_shipment,'revision',p_revision,'claimRevision',p_claim_revision,'values',p_values);
 select * into prior from private.claim_collection_events where id=p_operation;
 if found then
  if prior.actor_id<>p_actor or prior.session_id<>p_session or prior.request<>request then raise sqlstate 'PT409' using message='claim_collection_conflict';end if;
  return prior.result;
 end if;
 c:=private.contact_lock_scope(order_key,p_claim,parties);
 if c.claim_revision<>p_claim_revision then raise sqlstate 'PT409' using message='claim_collection_changed';end if;
 if (private.claim_collection_document(p_claim)->>'editable')::boolean is distinct from true or not exists(select 1 from public.order_shipments where id=p_shipment and order_id=order_key)
  or exists(select 1 from public.order_claim_reshipments where claim_id=p_claim and shipment_id=p_shipment) then
  raise sqlstate 'PT409' using message='claim_collection_blocked';end if;
 select * into plan from private.claim_collection_plans where claim_id=p_claim and shipment_id=p_shipment for update;
 if coalesce(plan.revision,0)<>p_revision then raise sqlstate 'PT409' using message='claim_collection_changed';end if;
 if p_values->>'carrier' is not null and not exists(select 1 from public.shipping_carriers where code=p_values->>'carrier' and is_active) then raise invalid_parameter_value using message='claim_collection_invalid';end if;
 select value into original from private.seller_order_claim_intakes z cross join lateral jsonb_array_elements(z.payload->'collections') where z.claim_id=p_claim and value->>'shipmentId'=p_shipment::text;
 requested:=coalesce(plan.requested_once,false) or coalesce(original->>'method','not_requested')<>'not_requested' or c.collecting_at is not null or c.collected_at is not null;
 sent:=coalesce(plan.customer_sent_once,false) or original->>'method'='customer_sent';
 if requested and p_values->>'method'='not_requested' then raise sqlstate 'PT409' using message='claim_collection_already_started';end if;
 insert into private.claim_collection_plans(claim_id,shipment_id,revision,method,carrier,tracking_number,evidence,requested_once,customer_sent_once)
 values(p_claim,p_shipment,p_revision+1,p_values->>'method',p_values->>'carrier',p_values->>'trackingNumber',btrim(p_values->>'evidence'),
  requested or p_values->>'method'<>'not_requested',coalesce(sent,false) or p_values->>'method'='customer_sent')
 on conflict(claim_id,shipment_id) do update set revision=excluded.revision,method=excluded.method,carrier=excluded.carrier,tracking_number=excluded.tracking_number,
  evidence=excluded.evidence,requested_once=excluded.requested_once,customer_sent_once=excluded.customer_sent_once,updated_at=clock_timestamp();
 update public.order_cancellation_requests set updated_at=clock_timestamp() where id=p_claim;
 result:=private.claim_collection_document(p_claim);
 insert into private.claim_collection_events(id,claim_id,shipment_id,actor_id,session_id,request,result) values(p_operation,p_claim,p_shipment,p_actor,p_session,request,result);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation,p_actor,'admin.order.claim_collection_corrected','order:'||order_key,
  jsonb_build_object('claimId',p_claim,'shipmentId',p_shipment,'method',p_values->>'method','revision',p_revision+1));
 perform private.notify_order_claim(p_claim,'claim_updated','회수 안내가 변경됐어요','판매자가 확인한 회수 방식과 송장 정보가 반영됐습니다.');
 return result;
end $function$

