CREATE OR REPLACE FUNCTION public.admin_save_cs_reply_template(p_id uuid, p_surface text, p_category text, p_title text, p_body text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); previous public.cs_reply_templates; saved public.cs_reply_templates;
 title_value text:=btrim(coalesce(p_title,'')); body_value text:=btrim(coalesce(p_body,''),E' \t\n\r\f\v');
begin
  perform private.require_operator_capability('cs.manage',false);

 if actor is null or not public.has_operator_capability('cs.manage',false) then raise insufficient_privilege using message='staff_required'; end if;
 if p_id is null or p_surface is null or p_surface not in ('product_question','review')
   or p_category is null or p_category not in ('product','shipping','return','exchange','refund','other')
   or char_length(title_value) not between 1 and 35 or title_value ~ '[[:cntrl:]]'
   or char_length(body_value) not between (case when p_surface='review' then 2 else 1 end) and (case when p_surface='review' then 1000 else 2000 end)
   or p_expected_revision is null or p_expected_revision<0 then
   raise invalid_parameter_value using message='invalid_cs_reply_template';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('cs_reply_template:'||p_id::text,0));
 select * into previous from public.cs_reply_templates where id=p_id for update;
 if found then
   if previous.surface<>p_surface or previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='cs_reply_template_changed'; end if;
   if previous.archived_at is not null then raise check_violation using message='cs_reply_template_archived'; end if;
   if (previous.category,previous.title,previous.body)=(p_category,title_value,body_value) then return to_jsonb(previous); end if;
   update public.cs_reply_templates set category=p_category,title=title_value,body=body_value,revision=revision+1,
     updated_by=actor,updated_at=clock_timestamp() where id=p_id returning * into saved;
 else
   if p_expected_revision<>0 then raise sqlstate 'PT409' using message='cs_reply_template_changed'; end if;
   insert into public.cs_reply_templates(id,surface,category,title,body,created_by,updated_by)
     values(p_id,p_surface,p_category,title_value,body_value,actor,actor) returning * into saved;
 end if;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.cs_reply_template.saved','cs_reply_templates:'||p_id::text,
   jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
 return to_jsonb(saved);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_cs_reply(p_operation_id uuid, p_actor_id uuid, p_surface text, p_target_id uuid, p_body text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; previous private.cs_reply_operations; current_revision bigint; current_reply text;
  body_value text:=btrim(coalesce(p_body,''),E' \t\n\r\f\v'); result jsonb; did_change boolean;
begin
  actor:=private.require_operator_capability('cs.manage',false);
  if actor is distinct from p_actor_id then raise insufficient_privilege using message='cs_reply_account_changed'; end if;
  if p_operation_id is null or p_target_id is null or p_surface is null or p_surface not in('product_question','review')
    or p_expected_revision is null or p_expected_revision<0
    or char_length(body_value) not between (case when p_surface='review' then 2 else 1 end) and (case when p_surface='review' then 1000 else 2000 end) then
    raise invalid_parameter_value using message='invalid_cs_reply_request'; end if;
  perform pg_advisory_xact_lock(hashtextextended('cs_reply_operation:'||p_operation_id::text,0));
  select * into previous from private.cs_reply_operations where operation_id=p_operation_id;
  if found then
    if previous.actor_id<>actor or previous.surface<>p_surface or previous.target_id<>p_target_id
      or previous.expected_revision<>p_expected_revision or previous.body<>body_value then
      raise sqlstate 'PT409' using message='cs_reply_operation_changed'; end if;
    return previous.result;
  end if;
  if p_surface='product_question' then
    select reply_source_revision,answer_body into current_revision,current_reply
      from public.product_questions where id=p_target_id for update;
  else
    select reply_source_revision,admin_reply into current_revision,current_reply
      from public.reviews where id=p_target_id for update;
  end if;
  if not found then raise no_data_found using message='cs_reply_target_not_found'; end if;
  -- CAS precedes the no-op check: stale same-body requests cannot silently pass.
  if current_revision<>p_expected_revision then raise sqlstate 'PT409' using message='cs_reply_source_changed'; end if;
  did_change:=current_reply is distinct from body_value;
  if did_change then
    if p_surface='product_question' then perform public.admin_answer_product_question(p_target_id,body_value);
    else perform public.admin_reply_to_review(p_target_id,body_value); end if;
    current_revision:=current_revision+1;
  end if;
  result:=jsonb_build_object('operationId',p_operation_id,'accountId',actor,'surface',p_surface,'id',p_target_id,
    'expectedRevision',p_expected_revision::text,'revision',current_revision::text,'body',body_value,
    'changed',did_change,'savedAt',clock_timestamp());
  insert into private.cs_reply_operations(operation_id,actor_id,surface,target_id,expected_revision,body,result)
    values(p_operation_id,actor,p_surface,p_target_id,p_expected_revision,body_value,result);
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_customer_reward_policy(p_values jsonb, p_expected_revision bigint, p_operation_id uuid, p_expected_actor uuid, p_expected_session uuid)
 RETURNS jsonb
