AS $function$
declare actor uuid; previous private.customer_reward_policy; prior public.audit_log; request jsonb; result jsonb; item record; base_enabled boolean;
begin
 actor:=private.assert_store_credit_admin();
 if actor is distinct from p_expected_actor or p_expected_session is null or auth.jwt()->>'session_id' is distinct from p_expected_session::text
  or not exists(select 1 from auth.sessions where id=p_expected_session and user_id=actor and (not_after is null or not_after>clock_timestamp())) then
  raise insufficient_privilege using message='customer_reward_auth_changed';end if;
 if p_operation_id is null or p_expected_revision is null or p_expected_revision<1 or jsonb_typeof(p_values) is distinct from 'object'
  or (select count(*) from jsonb_object_keys(p_values))<>8
  or exists(select 1 from jsonb_object_keys(p_values) k where k not in ('gradeEnabled','gradeRates','bestEnabled','bestAmount','bestValidityDays','bestReversal','evidence','acknowledged'))
  or jsonb_typeof(p_values->'gradeEnabled') is distinct from 'boolean' or jsonb_typeof(p_values->'bestEnabled') is distinct from 'boolean'
  or p_values->'acknowledged' is distinct from 'true'::jsonb or jsonb_typeof(p_values->'evidence') is distinct from 'string'
  or char_length(btrim(p_values->>'evidence')) not between 1 and 2000 or jsonb_typeof(p_values->'gradeRates') is distinct from 'object'
  or (select count(*) from jsonb_object_keys(p_values->'gradeRates'))<>4
  or exists(select 1 from jsonb_object_keys(p_values->'gradeRates') k where k not in ('welcome','silver','gold','platinum')) then
  raise invalid_parameter_value using message='invalid_customer_reward_policy';end if;
 for item in select key,value from jsonb_each(p_values->'gradeRates') loop
  if item.value<>'null'::jsonb and (jsonb_typeof(item.value)<>'number' or item.value::text !~ '^[0-9]+$' or item.value::numeric>10000)
   or (p_values->>'gradeEnabled')::boolean and item.value='null'::jsonb then raise invalid_parameter_value using message='invalid_customer_reward_rate';end if;
 end loop;
 if p_values->'bestAmount'<>'null'::jsonb and (jsonb_typeof(p_values->'bestAmount')<>'number' or (p_values->'bestAmount')::text !~ '^[1-9][0-9]*$' or (p_values->>'bestAmount')::numeric>999999999999)
  or p_values->'bestValidityDays'<>'null'::jsonb and (jsonb_typeof(p_values->'bestValidityDays')<>'number' or (p_values->'bestValidityDays')::text !~ '^[1-9][0-9]*$' or (p_values->>'bestValidityDays')::numeric>36500)
  or p_values->'bestReversal'<>'null'::jsonb and (jsonb_typeof(p_values->'bestReversal')<>'string' or p_values->>'bestReversal' not in ('keep','revoke'))
  or (p_values->>'bestEnabled')::boolean and (p_values->'bestAmount'='null'::jsonb or p_values->'bestValidityDays'='null'::jsonb or p_values->'bestReversal'='null'::jsonb)
  then raise invalid_parameter_value using message='invalid_customer_reward_best';end if;
 -- All money policies are locked before their dependent configuration.
 select enabled into base_enabled from private.store_credit_policy where singleton for share;
 if not base_enabled and ((p_values->>'gradeEnabled')::boolean or (p_values->>'bestEnabled')::boolean) then raise object_not_in_prerequisite_state using message='store_credit_policy_required';end if;
 select * into previous from private.customer_reward_policy where singleton for update;
 request:=jsonb_build_object('values',p_values,'revision',p_expected_revision,'sessionId',p_expected_session);
 select * into prior from public.audit_log where id=p_operation_id;
 if found then
  if prior.actor_id is distinct from actor or prior.action<>'marketing.customer_reward_policy' or prior.diff->'request' is distinct from request then raise sqlstate 'PT409' using message='customer_reward_operation_conflict';end if;
  return prior.diff->'result';
 end if;
 if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='customer_reward_policy_changed';end if;
 update private.customer_reward_policy set grade_enabled=(p_values->>'gradeEnabled')::boolean,grade_rates=p_values->'gradeRates',
  best_enabled=(p_values->>'bestEnabled')::boolean,best_amount=(p_values->>'bestAmount')::bigint,best_validity_days=(p_values->>'bestValidityDays')::integer,
  best_reversal=p_values->>'bestReversal',evidence=btrim(p_values->>'evidence'),revision=revision+1,updated_at=clock_timestamp() where singleton;
 result:=private.customer_reward_policy_document();
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'marketing.customer_reward_policy','customer_rewards',jsonb_build_object('request',request,'result',result));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_customer_segment(p_id uuid, p_expected_revision integer, p_operation_id uuid, p_name text, p_rule jsonb, p_estimate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; normalized_rule jsonb; hash text; estimate private.customer_segment_estimates; previous private.customer_segments;
 request jsonb; replay jsonb; result jsonb; name_value text:=btrim(p_name); saved_revision integer;
begin
 actor:=private.require_operator_capability('marketing.manage',false);
 if p_id is null or p_expected_revision is null or p_expected_revision<0 or p_operation_id is null or p_estimate_id is null
  or name_value is null or char_length(name_value) not between 1 and 50 or name_value ~ '[[:cntrl:]]' then
  raise invalid_parameter_value using message='invalid_customer_segment';end if;
 normalized_rule:=private.normalize_customer_segment_rule(p_rule);hash:=private.customer_segment_rule_hash(normalized_rule);
 request:=jsonb_build_object('id',p_id,'expectedRevision',p_expected_revision,'name',name_value,'rule',normalized_rule,'estimateId',p_estimate_id);
 perform pg_advisory_xact_lock(hashtextextended('customer-segment-operation:'||p_operation_id::text,0));
 replay:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.customer_segment.saved',request);
 if replay is not null then return replay;end if;
 perform pg_advisory_xact_lock(hashtextextended('customer-segment-catalog',0));
 select * into previous from private.customer_segments where id=p_id for update;
 if found then
  if previous.archived_at is not null then raise no_data_found using message='customer_segment_not_found';end if;
  if previous.preset_key is not null then raise insufficient_privilege using message='customer_segment_preset_readonly';end if;
  if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='customer_segment_changed';end if;
 elsif p_expected_revision<>0 then raise no_data_found using message='customer_segment_not_found';
 elsif (select count(*) from private.customer_segments where archived_at is null and preset_key is null)>=1000 then
  raise check_violation using message='customer_segment_limit';
 end if;
 select * into estimate from private.customer_segment_estimates where id=p_estimate_id;
 if not found or estimate.actor_id is distinct from actor or estimate.rule_hash<>hash or estimate.rule<>normalized_rule
  or estimate.valid_until<=clock_timestamp() then raise object_not_in_prerequisite_state using message='customer_segment_estimate_required';end if;
 if not private.customer_segment_references_available(normalized_rule) then raise object_not_in_prerequisite_state using message='customer_segment_target_unavailable';end if;
 if previous.id is null then
  insert into private.customer_segments(id,name,rule_version,rule,rule_hash,estimate_id,created_by,updated_by)
  values(p_id,name_value,1,normalized_rule,hash,p_estimate_id,actor,actor) returning revision into saved_revision;
 else
  update private.customer_segments set name=name_value,rule_version=1,rule=normalized_rule,rule_hash=hash,estimate_id=p_estimate_id,
   revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id=p_id returning revision into saved_revision;
 end if;
 result:=jsonb_build_object('id',p_id,'revision',saved_revision,'ruleHash',hash);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.customer_segment.saved','customer_segment:'||p_id::text,
  jsonb_build_object('request',request,'previousRuleHash',previous.rule_hash,'result',result));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_delivery_policy(p_origin_id uuid, p_method text, p_policy_id uuid, p_values jsonb, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); policy private.fulfillment_delivery_policies; values_object jsonb:='{}'; field text; state_value text;
  origin public.fulfillment_origins; instant timestamptz:=clock_timestamp();
begin
  perform private.require_operator_capability('platform.manage',true);

  if actor is null or not public.has_operator_capability('platform.manage',true) or not exists(select 1 from public.profiles where id=actor and private.has_operator_capability(id,'platform.manage',true)) then
    raise insufficient_privilege using message='admin_required'; end if;
  if p_method is null or p_method not in ('quick','pickup','direct','freight','none') or jsonb_typeof(p_values) is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(p_values) key where key not in ('state','contactName','contactPhone','handoffLocation','handoffInstructions',
      'appointmentInstructions','allowDelegate','completionInstructions','cancellationInstructions','approvalReference')) then
    raise invalid_parameter_value using message='invalid_delivery_policy'; end if;
  state_value:=p_values->>'state';
  if state_value is null or state_value not in ('draft','active','stopped') then raise invalid_parameter_value using message='invalid_delivery_policy'; end if;
  select * into origin from public.fulfillment_origins where id=p_origin_id for update;
  if not found then raise no_data_found using message='fulfillment_origin_not_found'; end if;
  if p_policy_id is not null then
    select * into policy from private.fulfillment_delivery_policies where id=p_policy_id and origin_id=p_origin_id and method=p_method for update;
    if not found then raise no_data_found using message='delivery_policy_not_found'; end if;
    if p_expected_revision is null or policy.revision<>p_expected_revision then raise sqlstate 'PT409' using message='delivery_policy_changed'; end if;
  elsif p_expected_revision is not null or state_value='stopped' then raise invalid_parameter_value using message='invalid_delivery_policy'; end if;
  if state_value='stopped' then values_object:=policy.terms;
  else
    foreach field in array array['contactName','contactPhone','handoffLocation','handoffInstructions','appointmentInstructions',
      'completionInstructions','cancellationInstructions','approvalReference'] loop
      if p_values?field and jsonb_typeof(p_values->field) not in ('null','string') then raise invalid_parameter_value using message='invalid_delivery_policy'; end if;
      values_object:=values_object||jsonb_build_object(field,nullif(btrim(p_values->>field),''));
    end loop;
    values_object:=values_object||jsonb_build_object('allowDelegate',coalesce(p_values->'allowDelegate','null'::jsonb));
    if not private.valid_delivery_policy_terms(values_object,state_value='active') then
      raise check_violation using message='delivery_policy_incomplete'; end if;
  end if;
  if state_value='active' and not origin.is_active then raise check_violation using message='delivery_policy_unavailable'; end if;
  if policy.activated_at is not null and (values_object is distinct from policy.terms or state_value not in ('active','stopped')
    or (policy.state='stopped' and state_value<>'stopped')) then raise check_violation using message='activated_delivery_policy_immutable'; end if;
  if state_value='active' and exists(select 1 from private.fulfillment_delivery_policies existing where existing.origin_id=p_origin_id
    and existing.method=p_method and existing.state='active' and existing.id is distinct from p_policy_id) then
    raise check_violation using message='delivery_policy_already_active'; end if;
  if p_policy_id is null then
    insert into private.fulfillment_delivery_policies(origin_id,method,state,terms,created_by,updated_by,activated_at)
    values(p_origin_id,p_method,state_value,values_object,actor,actor,case when state_value='active' then instant end) returning * into policy;
  else
    if policy.state=state_value and policy.terms=values_object then return jsonb_build_object('id',policy.id,'revision',policy.revision,'changed',false); end if;
    update private.fulfillment_delivery_policies set state=state_value,terms=values_object,revision=revision+1,updated_by=actor,updated_at=instant,
      activated_at=case when state_value='active' then coalesce(activated_at,instant) else activated_at end,
      stopped_at=case when state_value='stopped' then coalesce(stopped_at,instant) else stopped_at end where id=policy.id returning * into policy;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.fulfillment_delivery_policy.saved','origin:'||p_origin_id,
    jsonb_build_object('policyId',policy.id,'method',p_method,'state',state_value,'revision',policy.revision));
  return jsonb_build_object('id',policy.id,'revision',policy.revision,'changed',true);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_faq_entry_with_widget_topic(target_id uuid, target_category text, target_question text, target_answer text, target_sort_order integer, target_published boolean, expected_updated_at timestamp with time zone, target_widget_topic text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  saved_id uuid;
  previous_topic text;
  displaced_id uuid;
begin
  perform private.require_operator_capability('cs.manage', false);

  if actor is null or not public.has_operator_capability('cs.manage', false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if target_widget_topic is not null and target_widget_topic not in ('delivery', 'cancel', 'return') then
    raise invalid_parameter_value using message = 'invalid_faq_widget_topic';
  end if;

  -- 버튼을 지정하는 저장끼리는 줄을 세운다(잠금 전에는 어떤 FAQ 행도 잡지 않는다).
  if target_widget_topic is not null then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('public.faq_entries.widget_topic', 0));
  end if;

  saved_id := public.admin_save_faq_entry(
    target_id, target_category, target_question, target_answer,
    target_sort_order, target_published, expected_updated_at
  );

  select entry.widget_topic into previous_topic
  from public.faq_entries as entry
  where entry.id = saved_id
  for update;

  if previous_topic is not distinct from target_widget_topic then
    return saved_id;
  end if;

  if target_widget_topic is not null then
    update public.faq_entries as entry
    set widget_topic = null,
      updated_at = greatest(clock_timestamp(), entry.updated_at + interval '1 microsecond')
    where entry.widget_topic = target_widget_topic
      and entry.id <> saved_id
    returning entry.id into displaced_id;

    if displaced_id is not null then
      insert into public.audit_log(actor_id, action, target, diff)
      values (actor, 'faq.widget_topic', 'faq:' || displaced_id::text,
        jsonb_build_object('before', target_widget_topic, 'after', null, 'replacedBy', saved_id));
    end if;
  end if;

  update public.faq_entries
  set widget_topic = target_widget_topic
  where id = saved_id;

  insert into public.audit_log(actor_id, action, target, diff)
  values (actor, 'faq.widget_topic', 'faq:' || saved_id::text,
    jsonb_build_object('before', previous_topic, 'after', target_widget_topic, 'replaced', displaced_id));

  return saved_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_faq_entry(target_id uuid, target_category text, target_question text, target_answer text, target_sort_order integer, target_published boolean, expected_updated_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  previous public.faq_entries;
  saved public.faq_entries;
begin
  perform private.require_operator_capability('cs.manage',false);

  if actor is null or not public.has_operator_capability('cs.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if target_category is null or target_category not in ('order','claim','good','account','etc')
    or char_length(btrim(coalesce(target_question,''))) not between 1 and 200
    or char_length(btrim(coalesce(target_answer,''))) not between 1 and 6000
    or target_sort_order is null or target_sort_order not between 0 and 9999
    or target_published is null then
    raise invalid_parameter_value using message = 'invalid_faq_entry';
  end if;
  if target_id is null then
    insert into public.faq_entries(category,question,answer,sort_order,is_published)
    values(target_category,btrim(target_question),btrim(target_answer),target_sort_order,target_published)
    returning * into saved;
  else
    select * into previous from public.faq_entries where id = target_id for update;
    if not found then raise no_data_found using message = 'faq_not_found'; end if;
    if expected_updated_at is distinct from previous.updated_at then
      raise sqlstate 'PT409' using message = 'faq_conflict';
    end if;
    update public.faq_entries set category = target_category, question = btrim(target_question),
      answer = btrim(target_answer), sort_order = target_sort_order, is_published = target_published,
      updated_at = greatest(clock_timestamp(), previous.updated_at + interval '1 microsecond')
    where id = target_id returning * into saved;
  end if;
  insert into public.audit_log(actor_id,action,target,diff)
    values(actor,case when target_id is null then 'faq.create' else 'faq.update' end,
      'faq:' || saved.id::text,jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
  return saved.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_fulfillment_origin(target_id uuid, target_values jsonb, expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); previous public.fulfillment_origins; saved public.fulfillment_origins;
 code_value text; name_value text; carrier_value text; base_value bigint; threshold_value bigint; active_value boolean;
begin
  perform private.require_operator_capability('platform.manage',true);

  if actor is null or not public.has_operator_capability('platform.manage',true) or not exists(select 1 from public.profiles where id=actor and private.has_operator_capability(id,'platform.manage',true)) then
    raise insufficient_privilege using message='admin_required';
  end if;
  if jsonb_typeof(target_values) is distinct from 'object' or exists(select 1 from jsonb_object_keys(target_values) k
    where k not in ('code','name','default_carrier','base_fee','free_threshold','return_address','cutoff','export_template','is_active')) then
    raise invalid_parameter_value using message='invalid_fulfillment_origin';
  end if;
  code_value:=btrim(target_values->>'code'); name_value:=btrim(target_values->>'name');
  carrier_value:=nullif(target_values->>'default_carrier','');
  base_value:=(target_values->>'base_fee')::bigint; threshold_value:=nullif(target_values->>'free_threshold','')::bigint;
  active_value:=(target_values->>'is_active')::boolean;
  if code_value is null or code_value !~ '^[a-z][a-z0-9-]{1,39}$' or name_value is null or length(name_value) not between 1 and 80
    or base_value is null or base_value not between 0 and 1000000 or threshold_value not between 0 and 100000000 or active_value is null
    or coalesce(target_values->>'return_address','') ~ '[[:cntrl:]]'
    or length(coalesce(target_values->>'return_address',''))>500
    or coalesce(target_values->>'export_template','') not in ('standard','wms_csv','seowon_xlsx') then
    raise invalid_parameter_value using message='invalid_fulfillment_origin';
  end if;
  if carrier_value is not null and not exists(select 1 from public.shipping_carriers where code=carrier_value and is_active) then
    raise check_violation using message='shipping_carrier_inactive';
  end if;
  if active_value and carrier_value is null then raise check_violation using message='shipping_carrier_required'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('fulfillment_origin:'||code_value,0));
  if target_id is not null then
    select * into previous from public.fulfillment_origins where id=target_id for update;
    if not found then raise no_data_found using message='fulfillment_origin_not_found'; end if;
    if previous.updated_at is distinct from expected_updated_at then raise sqlstate 'PT409' using message='fulfillment_origin_conflict'; end if;
    if previous.code<>code_value then raise check_violation using message='fulfillment_origin_code_locked'; end if;
    update public.fulfillment_origins set name=name_value,default_carrier=carrier_value,base_fee=base_value,free_threshold=threshold_value,
      return_address=btrim(coalesce(target_values->>'return_address','')),cutoff=nullif(target_values->>'cutoff','')::time,
      export_template=target_values->>'export_template',is_active=active_value,
      updated_at=greatest(clock_timestamp(),previous.updated_at+interval '1 microsecond')
      where id=target_id returning * into saved;
  else
    if expected_updated_at is not null then raise invalid_parameter_value using message='invalid_fulfillment_origin'; end if;
    insert into public.fulfillment_origins(code,name,default_carrier,base_fee,free_threshold,return_address,cutoff,export_template,is_active)
      values(code_value,name_value,carrier_value,base_value,threshold_value,btrim(coalesce(target_values->>'return_address','')),
        nullif(target_values->>'cutoff','')::time,target_values->>'export_template',active_value) returning * into saved;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.fulfillment_origin.saved','fulfillment_origins:'||saved.id,
    jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
  return jsonb_build_object('id',saved.id,'updatedAt',saved.updated_at);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_good_claim_policy(target_good_id text, target_policy jsonb, expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); previous public.goods; saved public.goods;
  next_return boolean; next_exchange boolean; next_reason text; next_return_fee bigint;
  next_free_return_fee bigint; next_exchange_fee bigint; next_return_address uuid; field text; before_policy jsonb; after_policy jsonb;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='staff_required'; end if;
  if jsonb_typeof(target_policy) is distinct from 'object' or exists(select 1 from jsonb_object_keys(target_policy) key
    where key not in ('returnAllowed','exchangeAllowed','restrictionReason','returnFee','returnFreeShippingFee','exchangeFee','returnAddressId')) then
    raise invalid_parameter_value using message='invalid_good_claim_policy';
  end if;
  foreach field in array array['returnAllowed','exchangeAllowed'] loop
    if target_policy ? field and jsonb_typeof(target_policy->field) not in ('boolean','null') then
      raise invalid_parameter_value using message='invalid_good_claim_policy';
    end if;
  end loop;
  foreach field in array array['returnFee','returnFreeShippingFee','exchangeFee'] loop
    if target_policy ? field and jsonb_typeof(target_policy->field)<>'null' then
      if jsonb_typeof(target_policy->field)<>'number' or target_policy->>field !~ '^[0-9]+$'
        or (target_policy->>field)::numeric>1000000 then
        raise invalid_parameter_value using message='invalid_good_claim_policy';
      end if;
    end if;
  end loop;
  if target_policy ? 'restrictionReason' and jsonb_typeof(target_policy->'restrictionReason') not in ('string','null') then
    raise invalid_parameter_value using message='invalid_good_claim_policy';
  end if;
  -- 반품/교환지(S36-040): 주소록 id 또는 null(출고지 반품 주소).
  if target_policy ? 'returnAddressId' and not (jsonb_typeof(target_policy->'returnAddressId')='null'
    or (jsonb_typeof(target_policy->'returnAddressId')='string'
      and target_policy->>'returnAddressId' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')) then
    raise invalid_parameter_value using message='invalid_good_claim_policy';
  end if;
  select * into previous from public.goods where id=target_good_id for update;
  if not found then raise no_data_found using message='good_not_found'; end if;
  if previous.archived_at is not null then raise check_violation using message='good_archived'; end if;
  if expected_updated_at is null or previous.updated_at is distinct from expected_updated_at then
    raise exception using errcode='PT409',message='good_claim_policy_conflict';
  end if;
  next_return:=case when target_policy?'returnAllowed' then (target_policy->>'returnAllowed')::boolean else previous.claim_return_allowed end;
  next_exchange:=case when target_policy?'exchangeAllowed' then (target_policy->>'exchangeAllowed')::boolean else previous.claim_exchange_allowed end;
  next_reason:=case when target_policy?'restrictionReason' then nullif(btrim(target_policy->>'restrictionReason',E' \t\n\r'),'') else previous.claim_restriction_reason end;
  next_return_fee:=case when target_policy?'returnFee' then (target_policy->>'returnFee')::bigint else previous.claim_return_fee end;
  next_free_return_fee:=case when target_policy?'returnFreeShippingFee' then (target_policy->>'returnFreeShippingFee')::bigint else previous.claim_return_free_shipping_fee end;
  next_exchange_fee:=case when target_policy?'exchangeFee' then (target_policy->>'exchangeFee')::bigint else previous.claim_exchange_fee end;
  next_return_address:=case when target_policy?'returnAddressId' then (target_policy->>'returnAddressId')::uuid else previous.return_address_id end;
  -- 잠금 순서: 상품(위 for update) → 주소록(for share). 승인 스냅샷(prepare_claim_collections)도 같은 순서다.
  if next_return_address is not null then
    perform 1 from public.return_addresses where id=next_return_address for share;
    if not found then raise check_violation using message='return_address_not_found'; end if;
  end if;
  if char_length(coalesce(next_reason,''))>2000 or private.has_disallowed_shipping_notice_control(next_reason)
    or ((next_return=false or next_exchange=false) and next_reason is null) then
    raise check_violation using message='invalid_good_claim_policy';
  end if;
  before_policy:=jsonb_build_object('returnAllowed',previous.claim_return_allowed,'exchangeAllowed',previous.claim_exchange_allowed,
    'restrictionReason',previous.claim_restriction_reason,'returnFee',previous.claim_return_fee,
    'returnFreeShippingFee',previous.claim_return_free_shipping_fee,'exchangeFee',previous.claim_exchange_fee,'returnAddressId',previous.return_address_id);
  after_policy:=jsonb_build_object('returnAllowed',next_return,'exchangeAllowed',next_exchange,'restrictionReason',next_reason,
    'returnFee',next_return_fee,'returnFreeShippingFee',next_free_return_fee,'exchangeFee',next_exchange_fee,'returnAddressId',next_return_address);
  if before_policy=after_policy then return after_policy||jsonb_build_object('goodId',previous.id,'updatedAt',previous.updated_at); end if;
  update public.goods set claim_return_allowed=next_return,claim_exchange_allowed=next_exchange,
    claim_restriction_reason=next_reason,claim_return_fee=next_return_fee,claim_return_free_shipping_fee=next_free_return_fee,
    claim_exchange_fee=next_exchange_fee,return_address_id=next_return_address where id=target_good_id returning * into saved;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'catalog.good.claim_policy_updated','goods:'||saved.id,
    jsonb_build_object('before',before_policy,'after',after_policy));
  return after_policy||jsonb_build_object('goodId',saved.id,'updatedAt',saved.updated_at);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_good_from_draft(target_good jsonb, p_draft_id uuid, p_draft_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.admin_goods_drafts; result jsonb;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if auth.uid() is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='forbidden'; end if;
  if p_draft_id is null or p_draft_revision is null or p_draft_revision<1 or target_good is null or jsonb_typeof(target_good)<>'object'
    or nullif(target_good->>'previous_id','') is not null then raise invalid_parameter_value using message='invalid_goods_draft'; end if;
  perform pg_advisory_xact_lock(hashtextextended('goods-drafts-owner:'||auth.uid()::text,0));
  select * into d from public.admin_goods_drafts where id=p_draft_id and owner_id=auth.uid() for update;
  if not found then raise no_data_found using message='goods_draft_not_found'; end if;
  if d.completed_result is not null and d.revision=p_draft_revision+1 then return d.completed_result||jsonb_build_object('draftAlreadyCompleted',true); end if;
  if d.archived_at is not null or d.revision<>p_draft_revision then raise exception 'goods_draft_changed' using errcode='PT409'; end if;
  result:=public.admin_save_good(target_good);
  if coalesce(result->>'id','')='' then raise check_violation using message='goods_draft_completion_failed'; end if;
  update public.admin_goods_drafts set archived_at=clock_timestamp(),updated_at=clock_timestamp(),revision=revision+1,
    completed_good_id=result->>'id',completed_result=result where id=p_draft_id;
  insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.goods.draft.completed','goods_draft:'||p_draft_id::text,
    jsonb_build_object('goodId',result->>'id','revision',d.revision+1));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_good_media(p_good_id text, p_values jsonb, p_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();previous private.goods_media_bindings%rowtype;claimed private.goods_media_assets%rowtype;receipt public.audit_log%rowtype;
 field text; value jsonb; selected uuid; video_id uuid; clip_id uuid; video_label text; clip_label text; canonical jsonb:='{}'; request jsonb;before_data jsonb;result jsonb;
begin
 perform private.require_actor_operator_capability(actor,'catalog.manage');
 if p_good_id is null or p_good_id!~'^[a-z0-9][a-z0-9-]{0,199}$' or p_revision is null or p_revision<0 or p_operation_id is null
  or jsonb_typeof(p_values)<>'object' or (select count(*) from jsonb_object_keys(p_values))<>2 or not p_values ?& array['video','shortclip'] then raise check_violation using message='invalid_good_media';end if;
 foreach field in array array['video','shortclip'] loop
  value:=p_values->field;
  if value='null'::jsonb then canonical:=canonical||jsonb_build_object(field,null);continue;end if;
  if jsonb_typeof(value)<>'object' or (select count(*) from jsonb_object_keys(value))<>2 or not value ?& array['id','title']
   or jsonb_typeof(value->'id')<>'string' or (value->>'id')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(value->'title')<>'string' or length(btrim(value->>'title')) not between 1 and 20 or (value->>'title')~'[[:cntrl:]]' then raise check_violation using message='invalid_good_media';end if;
  selected:=(value->>'id')::uuid;
  if field='video' then video_id:=selected;video_label:=btrim(value->>'title');else clip_id:=selected;clip_label:=btrim(value->>'title');end if;
  canonical:=canonical||jsonb_build_object(field,jsonb_build_object('id',selected,'title',btrim(value->>'title')));
 end loop;
 if video_id is not null and video_id=clip_id then raise check_violation using message='invalid_good_media';end if;
 request:=jsonb_build_object('goodId',p_good_id,'values',canonical,'revision',p_revision);
 perform pg_advisory_xact_lock(hashtextextended('goods-media-operation:'||p_operation_id::text,0));
 select * into receipt from public.audit_log where id=p_operation_id;
 if found then
  if receipt.actor_id is distinct from actor or receipt.action<>'admin.goods_media.updated' or receipt.diff->'request'<>request then raise unique_violation using message='operation_conflict';end if;
  return receipt.diff->'result';
 end if;
 perform 1 from public.goods where id=p_good_id and archived_at is null for update;
 if not found then raise no_data_found using message='good_unavailable';end if;
 insert into private.goods_media_bindings(good_id) values(p_good_id) on conflict(good_id) do nothing;
 select * into previous from private.goods_media_bindings where good_id=p_good_id for update;
 if previous.revision<>p_revision then raise sqlstate 'PT409' using message='revision_conflict';end if;
 before_data:=private.good_media_snapshot(p_good_id);
 perform 1 from private.goods_media_assets where id=any(array[video_id,clip_id,previous.video_asset_id,previous.shortclip_asset_id]) order by id for update;
 foreach field in array array['video','shortclip'] loop
  selected:=case when field='video' then video_id else clip_id end;
  if selected is null then continue;end if;
  select * into claimed from private.goods_media_assets where id=selected;
  if not found or claimed.kind<>field or not private.goods_media_metadata_valid(claimed.metadata,claimed.source_size) then raise check_violation using message='goods_media_asset_unavailable';end if;
  if selected is not distinct from (case when field='video' then previous.video_asset_id else previous.shortclip_asset_id end) then
   if claimed.status<>'attached' then raise check_violation using message='goods_media_asset_unavailable';end if;
  elsif claimed.actor_id is distinct from actor or claimed.status<>'verified' or claimed.expires_at<=clock_timestamp()
   or exists(select 1 from private.goods_media_bindings b where b.video_asset_id=selected or b.shortclip_asset_id=selected) then
   raise check_violation using message='goods_media_asset_unavailable';
  end if;
  if not exists(select 1 from storage.objects o where o.bucket_id='goods-videos' and o.name=claimed.path and o.metadata->>'mimetype'='video/mp4' and o.metadata->>'size'=claimed.source_size::text) then raise check_violation using message='goods_media_asset_unavailable';end if;
 end loop;
 update private.goods_media_assets set status='attached',attached_at=coalesce(attached_at,clock_timestamp()) where id=any(array[video_id,clip_id]);
 update private.goods_media_bindings set video_asset_id=video_id,video_title=video_label,shortclip_asset_id=clip_id,shortclip_title=clip_label,revision=revision+1,updated_at=clock_timestamp() where good_id=p_good_id;
 update private.goods_media_assets set status='retired',expires_at=clock_timestamp()+interval '7 days' where id=any(array[previous.video_asset_id,previous.shortclip_asset_id])
  and id is distinct from video_id and id is distinct from clip_id and not exists(select 1 from private.goods_media_bindings b where b.video_asset_id=goods_media_assets.id or b.shortclip_asset_id=goods_media_assets.id);
 result:=private.good_media_snapshot(p_good_id);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.goods_media.updated',p_good_id,jsonb_build_object('request',request,'before',before_data,'result',result));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_good_transaction_terms(p_good_id text, p_expected_revision integer, p_expected_good_updated_at timestamp with time zone, p_volume jsonb, p_delivery jsonb, p_operation_id uuid, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();previous private.goods_transaction_configs;good public.goods;request jsonb;receipt jsonb;
 before_document jsonb;volume_changed boolean;delivery_changed boolean;changed boolean;new_revision integer;volume_id uuid;delivery_id uuid;
begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='auth_context_changed';end if;
 perform private.require_actor_operator_capability(actor,'catalog.manage');
 if p_good_id is null or char_length(p_good_id) not between 1 and 200 or p_good_id<>btrim(p_good_id) or p_good_id~'[[:cntrl:]]'
  or p_expected_revision is null or p_expected_revision<0 or p_expected_good_updated_at is null or not isfinite(p_expected_good_updated_at) or p_operation_id is null
  or (p_volume is not null and not private.goods_volume_input_valid(p_volume))
  or (p_delivery is not null and not private.goods_delivery_input_valid(p_delivery)) then
  raise invalid_parameter_value using message='invalid_goods_transaction_terms';end if;
 request:=jsonb_build_object('goodId',p_good_id,'expectedRevision',p_expected_revision,'expectedGoodUpdatedAt',p_expected_good_updated_at,
  'volume',p_volume,'delivery',p_delivery);
 perform pg_advisory_xact_lock(hashtextextended('goods-transaction-operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.goods.transaction_terms.saved',request);
 if receipt is not null then return receipt;end if;
 select * into good from public.goods where id=p_good_id and archived_at is null for update;
 if not found then raise no_data_found using message='good_not_found';end if;
 select * into previous from private.goods_transaction_configs where good_id=p_good_id for update;
 if coalesce(previous.revision,0)<>p_expected_revision or good.updated_at is distinct from p_expected_good_updated_at then
  raise sqlstate 'PT409' using message='goods_transaction_terms_changed';end if;
 before_document:=private.goods_transaction_terms_document(p_good_id);
 volume_changed:=p_volume is not null and p_volume is distinct from case when before_document->'volume'='null'::jsonb then null else (before_document->'volume')-array['id','goodId','revision'] end;
 delivery_changed:=p_delivery is not null and p_delivery is distinct from case when before_document->'delivery'='null'::jsonb then null else (before_document->'delivery')-array['id','goodId','revision'] end;
 changed:=volume_changed or delivery_changed;new_revision:=coalesce(previous.revision,0)+case when changed then 1 else 0 end;
 volume_id:=previous.volume_version_id;delivery_id:=previous.delivery_version_id;
 if (volume_changed and p_volume->>'status'='active') or (delivery_changed and p_delivery->>'status'='active') then
  perform 1 from private.goods_transaction_runtime where singleton and enabled for share;
  if not found then raise check_violation using message='checkout_contract_upgrade_required';end if;
 end if;
 if delivery_changed and p_delivery->>'status'='active' and p_delivery->>'paymentMode'<>'prepaid' then
  -- Parent goods precedes origin; checkout uses this same order.
  perform 1 from public.fulfillment_origins where id=good.origin_id and is_active for share;
  if not found then raise check_violation using message='collect_contract_not_ready';end if;
  perform 1 from private.shipping_collect_contracts c join private.shipping_collect_contract_versions v on v.id=c.version_id
   where c.origin_id=good.origin_id and v.status='active' for share of c;
  if not found then raise check_violation using message='collect_contract_not_ready';end if;
 end if;
 if volume_changed then
  insert into private.goods_volume_discount_versions(good_id,revision,status,terms,draft_values,created_by)
   values(p_good_id,new_revision,p_volume->>'status',nullif(p_volume->'terms','null'::jsonb),p_volume->'draftValues',actor) returning id into volume_id;
 end if;
 if delivery_changed then
  insert into private.goods_delivery_versions(good_id,revision,status,payment_mode,quantity_terms,draft_values,created_by)
   values(p_good_id,new_revision,p_delivery->>'status',p_delivery->>'paymentMode',nullif(p_delivery->'quantityTerms','null'::jsonb),p_delivery->'draftValues',actor) returning id into delivery_id;
 end if;
 if changed then
  insert into private.goods_transaction_configs(good_id,revision,volume_version_id,delivery_version_id,updated_by)
   values(p_good_id,new_revision,volume_id,delivery_id,actor) on conflict(good_id) do update set revision=excluded.revision,
    volume_version_id=excluded.volume_version_id,delivery_version_id=excluded.delivery_version_id,updated_at=clock_timestamp(),updated_by=actor;
  update public.goods set updated_at=clock_timestamp() where id=p_good_id;
 end if;
 receipt:=private.goods_transaction_terms_document(p_good_id)||jsonb_build_object('operationId',p_operation_id,'changed',changed);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.goods.transaction_terms.saved','goods:'||p_good_id,
  jsonb_build_object('request',request,'before',before_document,'result',receipt));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_good_workspace(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; operation uuid; good jsonb; draft jsonb; sections jsonb; kc jsonb; preorders jsonb;
  request_hash text; prior private.goods_workspace_operations; previous_id text; current_review private.goods_kc_reviews;
  saved jsonb; saved_id text; models jsonb:='[]'::jsonb; model jsonb; resolved jsonb; kc_revision integer; kc_saved jsonb;
  entry jsonb; variant uuid; policy jsonb; preorder_results jsonb:='[]'::jsonb; result jsonb;
  prior_variants uuid[]:='{}'; new_variants uuid[]:='{}';
  other_certifications jsonb; other_saved jsonb;
  extra_sections jsonb:='{}'::jsonb; extra_saved jsonb; publish_requested boolean:=false; publish_result jsonb;
  uuid_pattern constant text:='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
begin
  actor:=private.require_operator_capability('catalog.manage',false);
  if jsonb_typeof(p_request) is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(p_request) key where key not in ('operationId','good','draft','sections'))
    or jsonb_typeof(p_request->'operationId') is distinct from 'string' or p_request->>'operationId' !~ uuid_pattern
    or jsonb_typeof(p_request->'good') is distinct from 'object'
    or coalesce(jsonb_typeof(p_request->'draft'),'null') not in ('null','object')
    or coalesce(jsonb_typeof(p_request->'sections'),'null') not in ('null','object') then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  operation:=(p_request->>'operationId')::uuid;
  good:=p_request->'good';
  draft:=case when jsonb_typeof(p_request->'draft')='object' then p_request->'draft' end;
  sections:=case when jsonb_typeof(p_request->'sections')='object' then p_request->'sections' else '{}'::jsonb end;
  if exists(select 1 from jsonb_object_keys(sections) key where key not in ('kc','preorders','otherCertifications','optionSaleMode','purchaseCosts','pricePeriods','additional',
    'benefits','afterSales','sizeChart','listingColors','transactionTerms','shippingChargeGroup','subscriptionPolicy','fulfillment','production')) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  if draft is not null and (exists(select 1 from jsonb_object_keys(draft) key where key not in ('id','revision'))
    or jsonb_typeof(draft->'id') is distinct from 'string' or draft->>'id' !~ uuid_pattern
    or jsonb_typeof(draft->'revision') is distinct from 'number' or draft->>'revision' !~ '^[1-9][0-9]*$'
    or (draft->>'revision')::numeric>2147483647) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  -- T15b(0901-008): 새 상품의 '저장 후 공개'. 기본 저장 체인은 초안으로 저장하고, 모든 섹션을 저장한 뒤 같은 요청에서 공개를
  -- 시도한다(아래 9). 저장된 상품의 공개는 지금처럼 게시 상태 전환(admin_save_good·판매 준비 카드)이 맡는다.
  if coalesce(good->'publish','null'::jsonb) not in ('null'::jsonb,'false'::jsonb,'true'::jsonb) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  publish_requested:=coalesce(good->'publish','null'::jsonb)='true'::jsonb;
  if publish_requested and nullif(good->>'previous_id','') is not null then
    raise check_violation using message='goods_workspace_publish_unsupported';
  end if;
  if publish_requested then good:=good-'publish'; end if;
  kc:=case when jsonb_typeof(sections->'kc')='object' then sections->'kc' end;
  if sections ? 'kc' and coalesce(jsonb_typeof(sections->'kc'),'null') not in ('null','object') then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  if kc is not null and ((select array_agg(key order by key) from jsonb_object_keys(kc) key)
      is distinct from array['attested','expectedContextFingerprint','expectedRevision','models','status']
    or jsonb_typeof(kc->'models') is distinct from 'array' or jsonb_array_length(kc->'models')>50
    or jsonb_typeof(kc->'attested') is distinct from 'boolean'
    or jsonb_typeof(kc->'status') is distinct from 'string' or kc->>'status' not in ('unreviewed','reviewed')
    or jsonb_typeof(kc->'expectedRevision') not in ('null','number')
    or (jsonb_typeof(kc->'expectedRevision')='number' and (kc->>'expectedRevision' !~ '^[1-9][0-9]*$' or (kc->>'expectedRevision')::numeric>2147483647))
    or jsonb_typeof(kc->'expectedContextFingerprint') not in ('null','string')) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  preorders:=case when jsonb_typeof(sections->'preorders')='array' then sections->'preorders' end;
  if sections ? 'preorders' and coalesce(jsonb_typeof(sections->'preorders'),'null') not in ('null','array') then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  if preorders is not null and (jsonb_array_length(preorders)>100 or exists(select 1 from jsonb_array_elements(preorders) item
    where jsonb_typeof(item) is distinct from 'object'
      or (select array_agg(key order by key) from jsonb_object_keys(item) key) is distinct from array['expectedRevision','policyId','values','variant']
      or jsonb_typeof(item->'policyId') not in ('null','string') or (jsonb_typeof(item->'policyId')='string' and item->>'policyId' !~ uuid_pattern)
      or jsonb_typeof(item->'expectedRevision') not in ('null','number')
      or (jsonb_typeof(item->'expectedRevision')='number' and (item->>'expectedRevision' !~ '^[1-9][0-9]*$' or (item->>'expectedRevision')::numeric>2147483647))
      or jsonb_typeof(item->'values') is distinct from 'object')) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  -- 기타 인증(SHEET-014): {entries, expectedRevision}. 항목 규칙은 admin_save_goods_other_certifications가 검사한다.
  other_certifications:=case when jsonb_typeof(sections->'otherCertifications')='object' then sections->'otherCertifications' end;
  if sections ? 'otherCertifications' and coalesce(jsonb_typeof(sections->'otherCertifications'),'null') not in ('null','object') then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  if other_certifications is not null and ((select array_agg(key order by key) from jsonb_object_keys(other_certifications) key)
      is distinct from array['entries','expectedRevision']
    or jsonb_typeof(other_certifications->'entries') is distinct from 'array' or jsonb_array_length(other_certifications->'entries')>20
    or jsonb_typeof(other_certifications->'expectedRevision') not in ('null','number')
    or (jsonb_typeof(other_certifications->'expectedRevision')='number' and (other_certifications->>'expectedRevision' !~ '^[1-9][0-9]*$'
      or (other_certifications->>'expectedRevision')::numeric>2147483647))) then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;
  previous_id:=nullif(good->>'previous_id','');
  -- T15b(1027T-024): 나머지 설정은 새 상품의 첫 저장에서만 함께 저장한다. 저장된 상품은 독립 패널이 자기 버전으로 저장한다.
  extra_sections:=sections-array['kc','preorders','otherCertifications'];
  if extra_sections<>'{}'::jsonb and previous_id is not null then
    raise invalid_parameter_value using message='invalid_goods_workspace_request';
  end if;

  -- 1. 작업 영수증. 같은 요청의 재시도는 저장 결과를 그대로 돌려준다.
  request_hash:=encode(extensions.digest(convert_to(p_request::text,'UTF8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('goods-workspace-operation:'||operation::text,0));
  select * into prior from private.goods_workspace_operations where operation_id=operation;
  if found then
    if prior.actor_id<>actor or prior.request_hash<>request_hash then
      raise sqlstate 'PT409' using message='goods_workspace_operation_conflict';
    end if;
    return prior.receipt||jsonb_build_object('replayed',true);
  end if;

  -- 2. 저장 전 CAS. admin_save_good(카테고리 트리 → 상품 행)·admin_save_goods_kc(상품 행 → KC 행)와 같은 잠금 순서다.
  perform private.lock_catalog_category_tree();
  if previous_id is not null then
    perform 1 from public.goods where id=previous_id for update;
    -- 저장 전 옵션. 저장 뒤 이 목록에 없는 옵션이 이번 저장이 만든 새 옵션이다(옵션 참조 해석).
    select coalesce(array_agg(id),'{}') into prior_variants from public.goods_variants where good_id=previous_id;
    if kc is not null then
      select * into current_review from private.goods_kc_reviews where good_id=previous_id for update;
      if current_review.revision is distinct from (kc->>'expectedRevision')::integer
        or kc->>'expectedContextFingerprint' is distinct from private.goods_kc_fingerprint(previous_id) then
        raise sqlstate 'PT409' using message='goods_kc_review_changed';
      end if;
    end if;
  elsif kc is not null and (kc->'expectedRevision'<>'null'::jsonb or kc->'expectedContextFingerprint'<>'null'::jsonb) then
    raise sqlstate 'PT409' using message='goods_kc_review_changed';
  end if;

  -- 3. 기본 상품·옵션 저장
  if draft is null then saved:=public.admin_save_good(good);
  else saved:=public.admin_save_good_from_draft(good,(draft->>'id')::uuid,(draft->>'revision')::integer);
  end if;
  saved_id:=saved->>'id';
  if coalesce(saved_id,'')='' then raise check_violation using message='goods_workspace_save_failed'; end if;

  if coalesce((saved->>'draftAlreadyCompleted')::boolean,false) then
    -- 이 임시저장은 다른 요청(다른 탭·다른 작업 ID)이 이미 상품으로 등록했다. 같은 작업의 재시도는 위 영수증이 돌려주므로,
    -- 여기 온 요청의 KC·예약판매 섹션은 그 등록에 들어간 적이 없다. 섹션이 있으면 저장되지 않은 입력을 성공으로
    -- 알리지 않도록 거절한다(화면 입력은 유지된다). 섹션이 없으면 등록된 상품을 돌려준다.
    if kc is not null or coalesce(jsonb_array_length(preorders),0)>0 or other_certifications is not null
      or extra_sections<>'{}'::jsonb or publish_requested then
      raise sqlstate 'PT409' using message='goods_workspace_draft_completed_sections_skipped';
    end if;
    result:=jsonb_build_object('id',saved_id,'operationId',operation,'created',false,'draftAlreadyCompleted',true,
      'good',saved,'kc',null,'preorders','[]'::jsonb,'otherCertifications',null);
  else
    select coalesce(array_agg(id),'{}') into new_variants from public.goods_variants
      where good_id=saved_id and not (id=any(prior_variants));
    -- 4·5. KC: 옵션 참조를 저장된 옵션 id로 바꾼 뒤 저장 후의 새 버전·맥락 지문으로 저장한다.
    if kc is not null then
      for model in select value from jsonb_array_elements(kc->'models') loop
        if jsonb_typeof(model) is distinct from 'object' or model ? 'variantIds'
          or jsonb_typeof(model->'variantRefs') is distinct from 'array' or jsonb_array_length(model->'variantRefs')>200 then
          raise check_violation using message='invalid_goods_kc_models';
        end if;
        select coalesce(jsonb_agg(id order by id),'[]'::jsonb) into resolved from (
          select distinct private.resolve_goods_workspace_variant(saved_id,ref,new_variants,'kc')::text id
          from jsonb_array_elements(model->'variantRefs') ref) refs;
        models:=models||jsonb_build_array((model-'variantRefs')||jsonb_build_object('variantIds',resolved));
      end loop;
      select revision into kc_revision from private.goods_kc_reviews where good_id=saved_id;
      kc_saved:=public.admin_save_goods_kc(saved_id,models,kc->>'status',kc_revision,
        private.goods_kc_fingerprint(saved_id),(kc->>'attested')::boolean);
    end if;
    -- 6. 예약판매: 옵션별 정책. 활성화 권한·조건은 admin_save_goods_preorder가 검사한다.
    if preorders is not null then
      for entry in select value from jsonb_array_elements(preorders) loop
        variant:=private.resolve_goods_workspace_variant(saved_id,entry->'variant',new_variants,'preorder');
        policy:=public.admin_save_goods_preorder(saved_id,variant,(entry->>'policyId')::uuid,entry->'values',
          (entry->>'expectedRevision')::integer);
        preorder_results:=preorder_results||jsonb_build_array(policy||jsonb_build_object('variantId',variant));
      end loop;
    end if;
    -- 7. 기타 인증: 저장된 상품에 같은 트랜잭션으로 저장한다. 실패하면 기본 입력까지 되돌린다.
    if other_certifications is not null then
      other_saved:=public.admin_save_goods_other_certifications(saved_id,other_certifications->'entries',
        (other_certifications->>'expectedRevision')::integer);
    end if;
    -- 8. T15b(1027T-024): 나머지 설정. 각 섹션의 기존 저장 RPC가 권한·검증을 다시 하고, 실패하면 기본 입력까지 되돌린다.
    if extra_sections<>'{}'::jsonb then
      extra_saved:=private.save_goods_workspace_extra_sections(saved_id,extra_sections,new_variants);
    end if;
    result:=jsonb_build_object('id',saved_id,'operationId',operation,'created',previous_id is null,'good',saved,
      'kc',case when kc_saved is null then null else jsonb_build_object('changed',kc_saved->'changed',
        'status',kc_saved#>'{configuration,status}','revision',kc_saved#>'{configuration,revision}') end,
      'preorders',preorder_results,
      'otherCertifications',case when other_saved is null then null else jsonb_build_object('changed',other_saved->'changed',
        'revision',other_saved#>'{configuration,revision}') end,
      'sections',coalesce(extra_saved,'{}'::jsonb));
    -- 9. T15b(0901-008): 저장 후 공개. 판정은 기존 공개 경로 그대로이고, 거절되면 그 시도만 되돌려 저장은 남긴다.
    if publish_requested then
      begin
        perform public.admin_set_good_published(saved_id,true);
        publish_result:=jsonb_build_object('requested',true,'published',true,'error',null,'code',null);
      exception when others then
        publish_result:=jsonb_build_object('requested',true,'published',false,'error',sqlerrm,'code',sqlstate);
      end;
      result:=result||jsonb_build_object('publish',publish_result);
    end if;
  end if;
  insert into private.goods_workspace_operations(operation_id,actor_id,request_hash,good_id,receipt)
    values(operation,actor,request_hash,saved_id,result);
  insert into public.audit_log(id,actor_id,action,target,diff) values(operation,actor,'admin.good.workspace_saved','goods:'||saved_id,
    jsonb_build_object('created',previous_id is null,'draft',draft is not null,'kc',kc is not null,
      'otherCertifications',coalesce(jsonb_array_length(other_certifications->'entries'),0),
      'preorders',coalesce(jsonb_array_length(preorders),0),
      'sections',(select coalesce(jsonb_agg(key order by key),'[]'::jsonb) from jsonb_object_keys(extra_sections) key),
      'publishRequested',publish_requested,'published',coalesce((publish_result->>'published')::boolean,false),
      'draftAlreadyCompleted',coalesce((saved->>'draftAlreadyCompleted')::boolean,false)));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_good(target_good jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  previous public.goods;
  request jsonb;
  request_mode text;
  amount integer;
  starts timestamptz;
  ends timestamptz;
  schedule jsonb;
  saved jsonb;
  saved_id text;
  target_price bigint;
  target_compare bigint;
  own_ids uuid[] := array[]::uuid[];
  own_row private.goods_variant_price_periods;
  variant_row public.goods_variants;
  stopped boolean := false;
  inserted boolean := false;
  unchanged boolean;
  failure text;
begin
  perform private.require_operator_capability('catalog.manage', false);
  if pg_catalog.jsonb_typeof(target_good) is distinct from 'object' then
    raise invalid_parameter_value using message = 'invalid_good';
  end if;
  -- 위임 저장과 같은 잠금 순서(카테고리 트리 → 상품 행).
  perform private.lock_catalog_category_tree();
  select * into previous from public.goods
    where id = coalesce(nullif(target_good->>'previous_id', ''), target_good->>'id') for update;

  -- 상품 기본 칸 동시 수정(CAT-027·CAT-028): 편집 화면이 연 시점의 버전(base_expected_revision)과 지금 버전이 다르면
  -- 다른 작업(다른 운영자 저장·목록 일괄·바로 수정·ERP 반영·엑셀 반입)이 바꾼 값을 되돌리지 않게 저장 전체를 거절한다.
  -- 값이 없는 요청(새 상품·옛 화면·서버 내부 경로)은 지금처럼 저장한다. 저장된 상품을 고치는 요청인데 그 상품이 없어졌으면
  -- (그사이 URL을 바꿨거나 지웠으면) 새 상품을 만들지 않고 같은 충돌로 알린다.
  if target_good ? 'base_expected_revision' then
    if pg_catalog.jsonb_typeof(target_good->'base_expected_revision') is distinct from 'number'
      or target_good->>'base_expected_revision' !~ '^(0|[1-9][0-9]{0,17})$' then
      raise check_violation using message = 'invalid_goods_base_revision';
    end if;
    if nullif(target_good->>'previous_id', '') is not null
      and (previous.id is null or previous.base_revision <> (target_good->>'base_expected_revision')::bigint) then
      raise sqlstate 'PT409' using message = 'goods_base_changed';
    end if;
    target_good := target_good - 'base_expected_revision';
  end if;

  -- 한 상품에 할인은 하나다: 진행·예정 기간 할인이 있는 상품에 기간 없는 즉시할인(정가 표시)을 새로 걸거나 바꾸지 않는다.
  -- 이미 함께 있던 상품의 다른 입력 저장은 막지 않는다(정가 값이 그대로면 통과). 즉시할인 기간 지시가 있는 저장은 아래에서
  -- 상품 편집이 다루는 기간 할인을 먼저 멈추거나(none) 정가 표시를 거절한다(period).
  if not target_good ? 'instant_discount_period' and target_good ? 'compare_at_price' and coalesce(target_good->>'compare_at_price', '') ~ '^[0-9]{1,10}$' then
    target_compare := (target_good->>'compare_at_price')::bigint;
    target_price := case when coalesce(target_good->>'price', '') ~ '^[0-9]{1,10}$' then (target_good->>'price')::bigint
      else previous.price end;
    if previous.id is not null and target_compare > target_price
      and previous.compare_at_price::bigint is distinct from target_compare
      and exists(select 1 from private.goods_variant_price_periods p
        where p.good_id = previous.id and p.state = 'active' and p.ends_at > pg_catalog.statement_timestamp()) then
      raise check_violation using message = 'instant_discount_period_conflict';
    end if;
  end if;

  if not target_good ? 'instant_discount_period' then
    return private.admin_save_good_before_instant_discount_period(target_good);
  end if;

  request := target_good->'instant_discount_period';
  request_mode := request->>'mode';
  if pg_catalog.jsonb_typeof(request) is distinct from 'object' or request_mode is null or request_mode not in ('none', 'period')
    or pg_catalog.jsonb_typeof(request->'expectedFingerprint') is distinct from 'string'
    or pg_catalog.length(request->>'expectedFingerprint') not between 1 and 64
    or (request_mode = 'none' and (select pg_catalog.array_agg(key order by key) from pg_catalog.jsonb_object_keys(request) key)
      is distinct from array['expectedFingerprint', 'mode'])
    or (request_mode = 'period' and (select pg_catalog.array_agg(key order by key) from pg_catalog.jsonb_object_keys(request) key)
      is distinct from array['amount', 'endsAt', 'expectedFingerprint', 'mode', 'startsAt']) then
    raise check_violation using message = 'invalid_instant_discount_period';
  end if;
  if request_mode = 'period' then
    if pg_catalog.jsonb_typeof(request->'amount') is distinct from 'number' or request->>'amount' !~ '^[1-9][0-9]{0,9}$'
      or (request->>'amount')::numeric > 2147483647
      or pg_catalog.jsonb_typeof(request->'startsAt') is distinct from 'string' or request->>'startsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$'
      or pg_catalog.jsonb_typeof(request->'endsAt') is distinct from 'string' or request->>'endsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' then
      raise check_violation using message = 'invalid_instant_discount_period';
    end if;
    amount := (request->>'amount')::integer;
    begin
      starts := (request->>'startsAt')::timestamptz;
      ends := (request->>'endsAt')::timestamptz;
    exception when others then
      raise check_violation using message = 'invalid_instant_discount_period';
    end;
    if not pg_catalog.isfinite(starts) or not pg_catalog.isfinite(ends) or starts >= ends then
      raise check_violation using message = 'invalid_instant_discount_period';
    end if;
    if ends <= pg_catalog.statement_timestamp() then
      raise check_violation using message = 'instant_discount_period_ended';
    end if;
    -- 기간 즉시할인 상품의 판매가는 할인 전 가격이다(정가 표시를 함께 쓰지 않는다).
    if coalesce(target_good->>'compare_at_price', '') <> '' then
      raise check_violation using message = 'instant_discount_period_conflict';
    end if;
  end if;

  -- 화면이 본 할인 묶음과 지금 묶음이 같아야 한다(다른 곳에서 걸거나 멈춘 할인을 덮지 않는다).
  schedule := private.goods_instant_discount_schedule(previous.id);
  if schedule->>'fingerprint' is distinct from request->>'expectedFingerprint' then
    raise sqlstate 'PT409' using message = 'instant_discount_period_changed';
  end if;
  if schedule->>'state' = 'managed' then
    raise check_violation using message = 'instant_discount_period_managed';
  end if;
  if previous.id is not null then
    select coalesce(pg_catalog.array_agg(p.id order by p.id), '{}') into own_ids
    from private.goods_variant_price_periods p
    where p.good_id = previous.id and p.state = 'active' and p.ends_at > pg_catalog.statement_timestamp();
    perform 1 from private.goods_variant_price_periods where id = any(own_ids) order by id for update;
  end if;

  if request_mode = 'none' or pg_catalog.cardinality(own_ids) = 0 then
    if pg_catalog.cardinality(own_ids) > 0 then
      for own_row in select * from private.goods_variant_price_periods where id = any(own_ids) order by id loop
        perform public.admin_save_goods_price_period(own_row.good_id, own_row.variant_id, own_row.id, pg_catalog.jsonb_build_object(
          'state', 'disabled', 'discountPrice', own_row.discount_price, 'startsAt', own_row.starts_at, 'endsAt', own_row.ends_at), own_row.revision);
      end loop;
      stopped := true;
    end if;
    saved := private.admin_save_good_before_instant_discount_period(target_good - 'instant_discount_period');
  else
    -- 판매가·옵션 금액이 그대로면 지금 할인을 그대로 두거나 바꾼 것만 새로 쓴다. 금액이 바뀌면 기간 할인 가드
    -- (active_price_period_requires_reset)가 막으므로, 그때만 이 상품 편집이 다루는 할인을 먼저 멈추고 다시 저장한다.
    begin
      saved := private.admin_save_good_before_instant_discount_period(target_good - 'instant_discount_period');
    exception when check_violation then
      get stacked diagnostics failure = message_text;
      if failure is distinct from 'active_price_period_requires_reset' then raise; end if;
      saved := null;
    end;
    if saved is null then
      for own_row in select * from private.goods_variant_price_periods where id = any(own_ids) order by id loop
        perform public.admin_save_goods_price_period(own_row.good_id, own_row.variant_id, own_row.id, pg_catalog.jsonb_build_object(
          'state', 'disabled', 'discountPrice', own_row.discount_price, 'startsAt', own_row.starts_at, 'endsAt', own_row.ends_at), own_row.revision);
      end loop;
      stopped := true;
      saved := private.admin_save_good_before_instant_discount_period(target_good - 'instant_discount_period');
    end if;
  end if;
  saved_id := saved->>'id';
  if coalesce(saved_id, '') = '' then raise check_violation using message = 'invalid_good'; end if;

  if request_mode = 'period' then
    perform 1 from public.goods_variants where good_id = saved_id order by id for update;
    if exists(select 1 from public.goods_variants v where v.good_id = saved_id and v.archived_at is null and v.price::bigint - amount < 1) then
      raise check_violation using message = 'instant_discount_period_price_invalid';
    end if;
    if not exists(select 1 from public.goods_variants v where v.good_id = saved_id and v.archived_at is null) then
      raise check_violation using message = 'price_period_variant_inactive';
    end if;
    unchanged := not stopped and pg_catalog.cardinality(own_ids) > 0
      and pg_catalog.cardinality(own_ids) = (select count(*) from public.goods_variants v where v.good_id = saved_id and v.archived_at is null)
      and not exists(
        select 1 from public.goods_variants v
        where v.good_id = saved_id and v.archived_at is null and not exists(
          select 1 from private.goods_variant_price_periods p
          where p.id = any(own_ids) and p.variant_id = v.id and p.state = 'active' and p.regular_price = v.price
            and p.discount_price = v.price - amount and p.starts_at = starts and p.ends_at = ends));
    if not unchanged then
      if not stopped then
        for own_row in select * from private.goods_variant_price_periods where id = any(own_ids) order by id loop
          perform public.admin_save_goods_price_period(own_row.good_id, own_row.variant_id, own_row.id, pg_catalog.jsonb_build_object(
            'state', 'disabled', 'discountPrice', own_row.discount_price, 'startsAt', own_row.starts_at, 'endsAt', own_row.ends_at), own_row.revision);
        end loop;
        stopped := pg_catalog.cardinality(own_ids) > 0;
      end if;
      for variant_row in select * from public.goods_variants v where v.good_id = saved_id and v.archived_at is null order by v.id loop
        perform public.admin_save_goods_price_period(saved_id, variant_row.id, null, pg_catalog.jsonb_build_object(
          'state', 'active', 'discountPrice', variant_row.price - amount, 'startsAt', request->'startsAt', 'endsAt', request->'endsAt'), null);
      end loop;
      inserted := true;
    end if;
  end if;

  if stopped or inserted then
    insert into public.audit_log(actor_id, action, target, diff)
    values (auth.uid(), 'admin.good.instant_discount_period_saved', 'goods:' || saved_id, pg_catalog.jsonb_build_object(
      'mode', request_mode, 'amount', amount, 'startsAt', starts, 'endsAt', ends,
      'before', schedule, 'stopped', stopped, 'inserted', inserted));
  end if;
  return saved || pg_catalog.jsonb_build_object('instantDiscountPeriod', private.goods_instant_discount_schedule(saved_id));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_additional(p_good_id text, p_target_good_ids text[], p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_set private.goods_additional_sets; before_ids text[]; next_revision integer; target_id text;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if not coalesce(public.has_operator_capability('catalog.manage',false),false) then raise insufficient_privilege using message='staff required'; end if;
  if p_target_good_ids is null or cardinality(p_target_good_ids)>50
    or exists(select 1 from unnest(p_target_good_ids) id where id is null or btrim(id)='' or id<>btrim(id))
    or cardinality(p_target_good_ids)<>(select count(distinct id) from unnest(p_target_good_ids) id)
    or p_good_id=any(p_target_good_ids) then raise check_violation using message='invalid_additional_goods'; end if;
  -- All graph writers take this before examining reachability, so simultaneous
  -- A -> B and B -> A saves cannot independently pass the cycle check.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('goods-additional-graph',0));
  perform 1 from public.goods where id=p_good_id and archived_at is null for key share;
  if not found then raise no_data_found using message='good_not_found'; end if;
  select * into current_set from private.goods_additional_sets where good_id=p_good_id for update;
  if current_set.revision is distinct from p_expected_revision then raise sqlstate 'PT409' using message='additional_goods_changed'; end if;
  select coalesce(array_agg(target_good_id order by sort_order),'{}') into before_ids
    from private.goods_additional_links where base_good_id=p_good_id;
  if before_ids=p_target_good_ids then return jsonb_build_object('revision',current_set.revision,'changed',false); end if;
  for target_id in select id from unnest(p_target_good_ids) id order by id loop
    perform 1 from public.goods where id=target_id for key share;
    if not found or (not target_id=any(before_ids) and not private.goods_additional_available(target_id)) then
      raise check_violation using message='additional_good_unavailable';
    end if;
  end loop;
  if exists(with recursive reachable(good_id) as (
    select unnest(p_target_good_ids)
    union
    select link.target_good_id from private.goods_additional_links link
      join reachable on reachable.good_id=link.base_good_id where link.base_good_id<>p_good_id
  ) select 1 from reachable where good_id=p_good_id) then raise check_violation using message='additional_goods_cycle'; end if;
  next_revision:=coalesce(current_set.revision,0)+1;
  insert into private.goods_additional_sets(good_id,revision,updated_at,updated_by)
    values(p_good_id,next_revision,now(),auth.uid())
    on conflict(good_id) do update set revision=excluded.revision,updated_at=excluded.updated_at,updated_by=excluded.updated_by;
  delete from private.goods_additional_links where base_good_id=p_good_id;
  insert into private.goods_additional_links(base_good_id,target_good_id,sort_order)
    select p_good_id,target.id,(target.ordinality-1)::integer from unnest(p_target_good_ids) with ordinality target(id,ordinality);
  insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.good.additional_saved','goods:'||p_good_id,
    jsonb_build_object('before',before_ids,'after',p_target_good_ids,'revision',next_revision));
  return jsonb_build_object('revision',next_revision,'changed',true);
end $function$

