CREATE OR REPLACE FUNCTION public.admin_save_goods_attribute_schema(p_category_id uuid, p_fields jsonb, p_expected_revision integer, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); previous public.catalog_category_attribute_schemas; saved public.catalog_category_attribute_schemas; audit public.audit_log; result jsonb;
begin
  perform private.require_operator_capability('platform.manage',true);

  if actor is null or private.is_account_write_fenced(actor) then raise insufficient_privilege using message='admin_required'; end if;
  perform 1 from public.profiles where id=actor and private.has_operator_capability(id,'platform.manage',true) and suspended_at is null for share;
  if not found then raise insufficient_privilege using message='admin_required'; end if;
  if p_category_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 or not coalesce(private.goods_attribute_fields_valid(p_fields),false) then raise invalid_parameter_value using message='invalid_attribute_schema'; end if;
  perform private.lock_catalog_category_tree();
  if not exists(select 1 from public.catalog_categories where id=p_category_id and archived_at is null)
    or exists(select 1 from public.catalog_categories where parent_id=p_category_id and archived_at is null) then raise check_violation using message='category_not_leaf'; end if;
  select * into previous from public.catalog_category_attribute_schemas where category_id=p_category_id for update;
  select * into audit from public.audit_log where id=p_operation_id;
  if found then
    if audit.actor_id=actor and audit.action='catalog.attribute_schema_saved' and audit.target=p_category_id::text
      and audit.diff->'after'=p_fields and (audit.diff->>'expectedRevision')::integer=p_expected_revision then return audit.diff->'result'; end if;
    raise unique_violation using message='operation_conflict';
  end if;
  if coalesce(previous.revision,0)<>p_expected_revision then raise sqlstate 'PT409' using message='goods_attribute_schema_changed'; end if;
  insert into public.catalog_category_attribute_schemas(category_id,fields) values(p_category_id,p_fields)
    on conflict(category_id) do update set fields=excluded.fields,revision=catalog_category_attribute_schemas.revision+1,updated_at=clock_timestamp() returning * into saved;
  result:=jsonb_build_object('categoryId',saved.category_id,'revision',saved.revision,'fields',saved.fields);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'catalog.attribute_schema_saved',p_category_id::text,
    jsonb_build_object('before',coalesce(previous.fields,'[]'::jsonb),'after',p_fields,'expectedRevision',p_expected_revision,'result',result));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_benefit_content(p_good_id text, p_expected_revision integer, p_operation_id uuid, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();previous private.goods_benefit_content;request jsonb;receipt jsonb;images text[];candidate text;event_value text;gift_value text;
begin
 perform private.require_actor_operator_capability(actor,'catalog.manage');
 if p_good_id is null or p_expected_revision is null or p_expected_revision<0 or p_operation_id is null or p_values is null or jsonb_typeof(p_values)<>'object'
  or not p_values ?& array['eventText','giftText','giftImagePaths'] or p_values-array['eventText','giftText','giftImagePaths']<>'{}'::jsonb
  or jsonb_typeof(p_values->'eventText')<>'string' or jsonb_typeof(p_values->'giftText')<>'string' or jsonb_typeof(p_values->'giftImagePaths')<>'array' then
  raise invalid_parameter_value using message='invalid_goods_benefit_content';end if;
 event_value:=btrim(p_values->>'eventText');gift_value:=btrim(p_values->>'giftText');
 if char_length(event_value)>40 or char_length(gift_value)>100 or event_value~'[[:cntrl:]]' or gift_value~'[[:cntrl:]]'
  or jsonb_array_length(p_values->'giftImagePaths')>3 or exists(select 1 from jsonb_array_elements(p_values->'giftImagePaths') path where jsonb_typeof(path)<>'string') then
  raise invalid_parameter_value using message='invalid_goods_benefit_content';end if;
 select coalesce(array_agg(value order by position),'{}') into images from jsonb_array_elements_text(p_values->'giftImagePaths') with ordinality paths(value,position);
 if cardinality(images)<>(select count(distinct value) from unnest(images) value) or (cardinality(images)>0 and gift_value='')
  or exists(select 1 from unnest(images) path where path!~'^public-media/catalog/good/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$') then
  raise invalid_parameter_value using message='invalid_goods_benefit_images';end if;
 request:=jsonb_build_object('goodId',p_good_id,'expectedRevision',p_expected_revision,'eventText',event_value,'giftText',gift_value,'giftImagePaths',images);
 perform pg_advisory_xact_lock(hashtextextended('goods-benefit-operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.goods.benefits.saved',request);if receipt is not null then return receipt;end if;
 perform 1 from public.goods where id=p_good_id and archived_at is null for update;
 if not found then raise no_data_found using message='good_not_found';end if;
 select * into previous from private.goods_benefit_content where good_id=p_good_id for update;
 if coalesce(previous.revision,0)<>p_expected_revision then raise sqlstate 'PT409' using message='goods_benefits_changed';end if;
 -- Photo library archive takes the same row before checking all product references.
 for candidate in select value from unnest(images) value order by value loop
  continue when candidate=any(coalesce(previous.gift_image_paths,'{}'));
  if private.can_reuse_shared_goods_artwork(candidate) then continue;end if;
  update public.admin_artwork_upload_claims claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
   where claim.actor_id=actor and claim.kind='good' and claim.path=substr(candidate,length('public-media/')+1)
    and claim.status='verified' and claim.verified_at is not null and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
  if not found then raise check_violation using message='unverified_artwork';end if;
 end loop;
 insert into private.goods_benefit_content(good_id,event_text,gift_text,gift_image_paths,updated_by) values(p_good_id,event_value,gift_value,images,actor)
 on conflict(good_id) do update set event_text=excluded.event_text,gift_text=excluded.gift_text,gift_image_paths=excluded.gift_image_paths,
 revision=goods_benefit_content.revision+1,updated_at=clock_timestamp(),updated_by=actor;
 receipt:=private.goods_benefit_document(p_good_id);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.goods.benefits.saved','goods:'||p_good_id,
 jsonb_build_object('request',request,'before',to_jsonb(previous),'result',receipt));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_draft(p_id uuid, p_values jsonb, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); previous public.admin_goods_drafts; saved public.admin_goods_drafts;
  paths text[]; owned_paths text[]:='{}'; current_path text;
  allowed_fields constant text[]:=array[
    'id','ipId','name','nameEn','searchKeywords','displayOrder','categoryId','additionalCategoryIds','shippingNoticeTemplate','type','code','defaultVariantCode',
    'price','compareAtPrice','showDiscountRate','badge','stock','description','descriptionFormat','descriptionUploadPath','descriptionImageAlt','imagePath','detailImagePath',
    'originId','shippingFeeType','individualFee','variants','variantBaseline','customInputs','customInputsExpectedRevision','salePeriodEnabled','saleStartsAt','saleEndsAt','salePeriodRevision','productAttributes','productAttributeDraft','optionUsage',
    'optionAxisName0','optionAxisValues0','optionAxisName1','optionAxisValues1','optionAxisName2','optionAxisValues2',
    'regularPrice','discountEnabled','discountValue','discountUnit','discountPeriodEnabled','discountStartsAt','discountEndsAt','allowCardPayment','allowBankTransfer','saleRestriction','orderQuantityLimitEnabled',
    'minOrderQty','maxOrderQty','memberPurchaseLimitEnabled','memberLifetimeQtyLimit','claimReturnAllowed','claimExchangeAllowed','claimRestrictionReason',
    'claimReturnFee','claimReturnFreeShippingFee','claimExchangeFee','claimReturnAddressId','noticeMaker','noticeOrigin','noticeMaterial','noticeSize','noticeMadeOn','noticeAsManager','noticeAsContact',
    'galleryPath0','galleryPath1','galleryPath2','galleryPath3','galleryPath4','galleryPath5','galleryPath6','galleryPath7','galleryPath8'];
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='forbidden'; end if;
  if p_id is null or p_expected_revision is null or p_expected_revision<0 or p_values is null or jsonb_typeof(p_values)<>'object'
    or octet_length(p_values::text)>2097152 then raise invalid_parameter_value using message='invalid_goods_draft'; end if;
  if not p_values ? 'name' or char_length(btrim(p_values->>'name')) not between 1 and 100
    or exists(select 1 from jsonb_each(p_values) entry where not entry.key=any(allowed_fields) or jsonb_typeof(entry.value)<>'string')
    or exists(select 1 from jsonb_each_text(p_values) entry where entry.value ~* '^\s*(blob:|data:)')
    or coalesce(p_values->>'variantBaseline','[]')<>'[]' or coalesce(p_values->>'customInputsExpectedRevision','0')<>'0'
    or coalesce(p_values->>'claimReturnAddressId','')<>'' and p_values->>'claimReturnAddressId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  then raise invalid_parameter_value using message='invalid_goods_draft'; end if;
  if exists(select 1 from jsonb_each_text(p_values) e where (e.key in ('imagePath','detailImagePath','descriptionUploadPath') or e.key like 'galleryPath%')
    and e.value<>'' and e.value !~ '^public-media/catalog/good/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$')
  then raise check_violation using message='unverified_artwork'; end if;
  perform pg_advisory_xact_lock(hashtextextended('goods-drafts-owner:'||actor::text,0));
  select * into previous from public.admin_goods_drafts where id=p_id for update;
  if found then
    if previous.owner_id<>actor then raise insufficient_privilege using message='forbidden'; end if;
    if previous.archived_at is not null then raise exception 'goods_draft_changed' using errcode='PT409'; end if;
    if previous.form_values=p_values and previous.revision=p_expected_revision+1 then return private.goods_draft_summary(previous); end if;
    if previous.revision<>p_expected_revision then raise exception 'goods_draft_changed' using errcode='PT409'; end if;
  else
    if p_expected_revision<>0 then raise exception 'goods_draft_changed' using errcode='PT409'; end if;
    perform private.make_room_for_goods_draft(actor);
  end if;
  select coalesce(array_agg(distinct match[1]),'{}') into paths from regexp_matches(p_values::text,
    '(public-media/catalog/good/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](?:jpg|png|webp))','g') match;
  foreach current_path in array paths loop
    if current_path=any(coalesce(previous.owned_image_paths,'{}')) or private.can_reuse_own_goods_draft_artwork(current_path) then
      owned_paths:=array_append(owned_paths,current_path);
    elsif private.can_reuse_shared_goods_artwork(current_path) then null;
    else
      update public.admin_artwork_upload_claims set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
        where actor_id=actor and path=substr(current_path,14) and kind='good' and status='verified' and expires_at>clock_timestamp();
      if not found then raise check_violation using message='unverified_artwork'; end if;
      owned_paths:=array_append(owned_paths,current_path);
    end if;
  end loop;
  insert into public.admin_goods_drafts(id,owner_id,form_values,image_paths,owned_image_paths) values(p_id,actor,p_values,paths,owned_paths)
    on conflict(id) do update set form_values=excluded.form_values,image_paths=excluded.image_paths,owned_image_paths=excluded.owned_image_paths,
      revision=admin_goods_drafts.revision+1,updated_at=clock_timestamp() returning * into saved;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.goods.draft.saved','goods_draft:'||p_id::text,
    jsonb_build_object('revision',saved.revision,'fieldCount',(select count(*) from jsonb_object_keys(p_values))));
  return private.goods_draft_summary(saved);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_event_template(p_id uuid, p_event_text text, p_archived boolean, p_expected_revision integer, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();previous private.goods_event_templates;request jsonb;receipt jsonb;saved private.goods_event_templates;
begin
 perform private.require_actor_operator_capability(actor,'catalog.manage');
 if p_id is null or p_event_text is null or char_length(btrim(p_event_text)) not between 1 and 40 or p_event_text~'[[:cntrl:]]'
  or p_archived is null or p_expected_revision is null or p_expected_revision<0 or p_operation_id is null then raise invalid_parameter_value using message='invalid_goods_event_template';end if;
 request:=jsonb_build_object('id',p_id,'eventText',btrim(p_event_text),'archived',p_archived,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('goods-event-template-operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.goods.event_template.saved',request);if receipt is not null then return receipt;end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-event-template:'||p_id::text,0));
 select * into previous from private.goods_event_templates where id=p_id for update;
 if coalesce(previous.revision,0)<>p_expected_revision or (previous.id is null and p_archived) then raise sqlstate 'PT409' using message='goods_event_template_changed';end if;
 insert into private.goods_event_templates(id,event_text,updated_by) values(p_id,btrim(p_event_text),actor)
 on conflict(id) do update set event_text=excluded.event_text,archived_at=case when p_archived then coalesce(goods_event_templates.archived_at,clock_timestamp()) else null end,
 revision=goods_event_templates.revision+1,updated_at=clock_timestamp(),updated_by=actor returning * into saved;
 receipt:=jsonb_build_object('id',saved.id,'eventText',saved.event_text,'revision',saved.revision,'archived',saved.archived_at is not null,'createdAt',saved.created_at);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.goods.event_template.saved','goods_event_template:'||p_id,
 jsonb_build_object('request',request,'before',to_jsonb(previous),'result',receipt));return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_fulfillment(p_good text, p_values jsonb, p_revision bigint, p_operation uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old private.goods_fulfillment_settings;prior public.audit_log;request jsonb;result jsonb;method jsonb;asset_ids uuid[];good public.goods;begin
 perform private.production_identity(p_actor,p_session,null,'catalog.manage');
 if p_revision is null or p_revision<0 or p_operation is null or not private.transaction_json_keys(p_values,array['mode','methods','assetIds','publicNote','evidence','confirmed'])
  or coalesce(p_values->>'mode','') not in('shipping','no_delivery','digital') or p_values->'confirmed' is distinct from 'true'::jsonb
  or jsonb_typeof(p_values->'methods') is distinct from 'array' or jsonb_array_length(p_values->'methods') not between 1 and 5
  or jsonb_typeof(p_values->'assetIds') is distinct from 'array' or jsonb_array_length(p_values->'assetIds')>10
  or jsonb_typeof(p_values->'publicNote') is distinct from 'string' or char_length(p_values->>'publicNote')>1000
  or jsonb_typeof(p_values->'evidence') is distinct from 'string' or char_length(btrim(p_values->>'evidence')) not between 2 and 1000
  or ((p_values->>'publicNote')||(p_values->>'evidence'))~'[[:cntrl:]]' then raise invalid_parameter_value;end if;
 if (select count(distinct value->>'method') from jsonb_array_elements(p_values->'methods'))<>jsonb_array_length(p_values->'methods') then raise invalid_parameter_value;end if;
 for method in select value from jsonb_array_elements(p_values->'methods') loop
  if not private.transaction_json_keys(method,array['method','feeAmount','feeBasis','installationFee'])
   or coalesce(method->>'method','') not in('parcel','quick','pickup','direct','freight','none','digital')
   or coalesce(method->>'feeBasis','') not in('per_order','per_item')
   or jsonb_typeof(method->'installationFee') is distinct from 'number' or method->>'installationFee'!~'^(0|[1-9][0-9]*)$' or (method->>'installationFee')::numeric>1000000
   or (method->>'method'='parcel') is distinct from (method->'feeAmount'='null'::jsonb)
   or method->>'method'<>'parcel' and (jsonb_typeof(method->'feeAmount') is distinct from 'number' or method->>'feeAmount'!~'^(0|[1-9][0-9]*)$' or (method->>'feeAmount')::numeric>1000000)
   or method->>'method' in('pickup','none','digital') and (method->'feeAmount'<>'0'::jsonb or method->'installationFee'<>'0'::jsonb)
   or method->>'method'='parcel' and method->>'feeBasis'<>'per_order'
   or p_values->>'mode'='shipping' and method->>'method' not in('parcel','quick','pickup','direct','freight')
   or p_values->>'mode'='no_delivery' and method->>'method'<>'none'
   or p_values->>'mode'='digital' and method->>'method'<>'digital' then raise invalid_parameter_value;end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(p_values->'assetIds') a where jsonb_typeof(a)<>'string' or a#>>'{}'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then raise invalid_parameter_value;end if;
 select coalesce(array_agg((a#>>'{}')::uuid),'{}') into asset_ids from jsonb_array_elements(p_values->'assetIds') a;
 if cardinality(asset_ids)<>(select count(distinct a) from unnest(asset_ids)a) or (p_values->>'mode'='digital') is distinct from (cardinality(asset_ids)>0) then raise invalid_parameter_value;end if;
 select * into good from public.goods where id=p_good and archived_at is null for update;if not found then raise no_data_found;end if;
 select * into old from private.goods_fulfillment_settings where good_id=p_good for update;
 request:=jsonb_build_object('goodId',p_good,'values',p_values,'revision',p_revision,'sessionId',p_session);
 select * into prior from public.audit_log where id=p_operation;
 if found then if prior.actor_id is distinct from p_actor or prior.action<>'goods.fulfillment.settings' or prior.diff->'request' is distinct from request then raise sqlstate 'PT409';end if;return prior.diff->'result';end if;
 if coalesce(old.revision,0)<>p_revision then raise sqlstate 'PT409' using message='fulfillment_changed';end if;
 perform private.assert_goods_transaction_runtime();
 if p_values->>'mode'='digital' and (exists(select 1 from private.goods_production_settings where good_id=p_good and enabled)
  or exists(select 1 from public.goods_variants where good_id=p_good and preorder_policy_id is not null and archived_at is null)) then raise check_violation using message='digital_supply_conflict';end if;
 -- Files are immutable after verification; replacing a product's selection does
 -- not replace files purchased under an earlier order contract.
 perform id from private.goods_digital_assets where id=any(asset_ids) order by id for share;
 if (select count(*) from private.goods_digital_assets where id=any(asset_ids) and state='verified')<>cardinality(asset_ids) then raise check_violation using message='digital_asset_unavailable';end if;
 insert into private.goods_fulfillment_settings(good_id,revision,mode,methods,asset_ids,public_note,evidence)
 values(p_good,p_revision+1,p_values->>'mode',p_values->'methods',asset_ids,btrim(p_values->>'publicNote'),btrim(p_values->>'evidence'))
 on conflict(good_id) do update set revision=excluded.revision,mode=excluded.mode,methods=excluded.methods,asset_ids=excluded.asset_ids,
 public_note=excluded.public_note,evidence=excluded.evidence,updated_at=clock_timestamp();
 result:=private.goods_fulfillment_document(p_good,true);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation,p_actor,'goods.fulfillment.settings','good:'||p_good,jsonb_build_object('request',request,'result',result));return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_group_common(p_group_id uuid, p_expected_revision bigint, p_values jsonb, p_operation_id uuid, p_expected_actor_id uuid, p_expected_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior private.goods_group_operations;current_group private.goods_groups;target_ids text[];lock_ids text[];target_id text;item public.goods;
 expected_hash text;before_group jsonb;before_common jsonb;after_common jsonb;individual_before jsonb;individual_after jsonb;variant_before jsonb;variant_after jsonb;
 payload jsonb;source_paths text[];attribute_revision integer;child_revision integer;child_operation uuid;result jsonb;
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 perform private.validate_goods_group_common_values(p_values);
 if p_group_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision not between 1 and 9007199254740990 then
  raise invalid_parameter_value using message='invalid_goods_group_operation';end if;
 expected_hash:=encode(extensions.digest(jsonb_build_array('common',p_group_id,p_expected_revision,p_values)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('goods-group-operation:'||p_operation_id::text,0));
 select * into prior from private.goods_group_operations where operation_id=p_operation_id;
 if found then
  if prior.actor_id<>p_expected_actor_id or prior.session_id<>p_expected_session_id or prior.command<>'common'
   or prior.target_group_id is distinct from p_group_id or prior.expected_revision is distinct from p_expected_revision or prior.receipt is null then
   raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  if prior.receipt->>'state'='sealed' then return prior.receipt;end if;
  if prior.request_hash<>expected_hash then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  return prior.receipt;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 perform private.lock_catalog_category_tree();
 select * into current_group from private.goods_groups where id=p_group_id for update;
 if not found or current_group.archived_at is not null or current_group.revision<>p_expected_revision then
  raise sqlstate 'PT409' using message='goods_group_changed';end if;
 select array_agg(good_id order by good_id) into target_ids from private.goods_group_members where group_id=p_group_id;
 if cardinality(target_ids) not between 1 and 100 or not(current_group.common_good_id=any(target_ids)) then
  raise check_violation using message='goods_group_members_invalid';end if;
 select array_agg(distinct id order by id) into lock_ids from (
  select unnest(target_ids) id union select private.goods_aggregation_owner(id) from unnest(target_ids) id) all_goods;
 -- Existing normal editors acquire admin_good advisory before their goods row.
 -- Claim those locks without waiting before owning the union of goods rows.
 foreach target_id in array lock_ids loop
  if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||target_id,0)) then raise sqlstate 'PT409' using message='goods_group_retry';end if;
  if target_id=any(target_ids) and (not pg_try_advisory_xact_lock(hashtextextended('goods-after-sales-operation:'||md5('goods-group-common-after-sales:'||p_operation_id::text||':'||target_id)::uuid::text,0))
   or not pg_try_advisory_xact_lock(hashtextextended('goods-size-operation:'||md5('goods-group-common-size:'||p_operation_id::text||':'||target_id)::uuid::text,0))) then
   raise sqlstate 'PT409' using message='goods_group_retry';end if;
 end loop;
 perform 1 from public.goods where id=any(lock_ids) order by id for update nowait;
 if exists(select 1 from public.goods where id=any(target_ids) and archived_at is not null) then raise check_violation using message='goods_group_member_unavailable';end if;
 perform 1 from public.goods_variants where good_id=any(target_ids) order by id for update nowait;
 perform 1 from public.ips where id in(select ip_id from public.goods where id=any(target_ids) union select p_values#>>'{goods,ip_id}') order by id for share nowait;
 if not exists(select 1 from public.ips where id=p_values#>>'{goods,ip_id}' and archived_at is null) then
  raise check_violation using message='catalog_parent_archived';end if;
 before_group:=private.goods_group_snapshot(p_group_id);before_common:=private.goods_group_common_identity(current_group.common_good_id);
 if exists(select 1 from unnest(target_ids) id where private.goods_group_common_identity(id) is distinct from before_common) then
  raise check_violation using message='goods_group_common_mismatch';end if;
 select jsonb_object_agg(g.id,to_jsonb(g)-array['ip_id','type','category_id','name_en','notice_maker','notice_origin','notice_material','notice_size','notice_made_on',
  'notice_as_manager','notice_as_contact','description','description_format','description_image_paths','search_keywords','published_at','updated_at','kc_disclosures','base_revision']) into individual_before
 from public.goods g where id=any(target_ids);
 select jsonb_agg(to_jsonb(v) order by v.id) into variant_before from public.goods_variants v where good_id=any(target_ids);
 insert into private.goods_group_operations(operation_id,actor_id,session_id,command,target_group_id,expected_revision,request_hash)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,'common',p_group_id,p_expected_revision,expected_hash);
 insert into private.goods_group_write_authorizations(transaction_id,good_id,actor_id)
 select txid_current(),id,p_expected_actor_id from unnest(target_ids) id;
 update public.goods set published_at=null where id=any(target_ids) and published_at is not null;
 -- Save and validate the common source first. Its new HTML images acquire their
 -- real single-use upload claim there before sealed copying to other members.
 for item in select * from public.goods where id=any(target_ids) order by (id=current_group.common_good_id) desc,id loop
  select coalesce(revision,0) into attribute_revision from public.goods_attribute_values where good_id=item.id;
  payload:=to_jsonb(item)||(p_values->'goods')||jsonb_build_object('previous_id',item.id,'id',item.id,'publish',false,
   'product_attributes',case when item.id=current_group.common_good_id then p_values->'attributes'
    else jsonb_set(p_values->'attributes','{expectedRevision}',to_jsonb(coalesce(attribute_revision,0))) end);
  if item.id<>current_group.common_good_id then
   insert into private.goods_artwork_copy_authorizations(transaction_id,target_good_id,source_good_id,actor_id,allowed_paths)
   values(txid_current(),item.id,current_group.common_good_id,p_expected_actor_id,
    array_remove(array[item.image_path,item.detail_image_path]||coalesce(item.gallery_paths,'{}')||coalesce(item.description_image_paths,'{}')||coalesce(source_paths,'{}'),null));
  end if;
  perform public.admin_save_good(payload);
  if item.id=current_group.common_good_id then select description_image_paths into source_paths from public.goods where id=item.id;end if;
  delete from private.goods_artwork_copy_authorizations where transaction_id=txid_current() and target_good_id=item.id and actor_id=p_expected_actor_id;
  select coalesce(revision,0) into child_revision from private.goods_after_sales_content where good_id=item.id;
  child_operation:=md5('goods-group-common-after-sales:'||p_operation_id::text||':'||item.id)::uuid;
  perform public.admin_save_goods_after_sales_content(item.id,coalesce(child_revision,0),child_operation,p_values->'afterSales');
  select coalesce(revision,0) into child_revision from private.goods_size_charts where good_id=item.id;
  child_operation:=md5('goods-group-common-size:'||p_operation_id::text||':'||item.id)::uuid;
  perform public.admin_save_goods_size_chart(item.id,coalesce(child_revision,0),child_operation,p_values->'sizeChart');
  perform private.invalidate_goods_kc_review(item.id,'goods_group_common_changed');
  update public.goods set kc_disclosures='[]' where id=item.id;
 end loop;
 after_common:=private.goods_group_common_identity(current_group.common_good_id);
 if exists(select 1 from unnest(target_ids) id where private.goods_group_common_identity(id) is distinct from after_common) then
  raise check_violation using message='goods_group_common_mismatch';end if;
 select jsonb_object_agg(g.id,to_jsonb(g)-array['ip_id','type','category_id','name_en','notice_maker','notice_origin','notice_material','notice_size','notice_made_on',
  'notice_as_manager','notice_as_contact','description','description_format','description_image_paths','search_keywords','published_at','updated_at','kc_disclosures','base_revision']) into individual_after
 from public.goods g where id=any(target_ids);
 select jsonb_agg(to_jsonb(v) order by v.id) into variant_after from public.goods_variants v where good_id=any(target_ids);
 if individual_after is distinct from individual_before or variant_after is distinct from variant_before then
  raise check_violation using message='goods_group_individual_fields_changed';end if;
 update private.goods_groups set revision=revision+1,updated_at=clock_timestamp(),updated_by=p_expected_actor_id where id=p_group_id;
 result:=jsonb_build_object('state','completed','operationId',p_operation_id,'group',private.goods_group_snapshot(p_group_id));
 insert into private.goods_group_changes(group_id,operation_id,actor_id,revision,before_value,after_value)
 values(p_group_id,p_operation_id,p_expected_actor_id,p_expected_revision+1,before_group||jsonb_build_object('common',before_common),
  (result->'group')||jsonb_build_object('common',after_common));
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'catalog.goods_group.common_saved','goods_group:'||p_group_id::text,
  jsonb_build_object('before',before_common,'after',after_common,'goodIds',to_jsonb(target_ids),'allProductsUnpublished',true,'requiresKcReview',true));
 update private.goods_group_operations set receipt=result,completed_at=clock_timestamp() where operation_id=p_operation_id;
 delete from private.goods_group_write_authorizations where transaction_id=txid_current() and actor_id=p_expected_actor_id and good_id=any(target_ids);
 return result;
exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_group(p_group_id uuid, p_expected_revision bigint, p_values jsonb, p_operation_id uuid, p_expected_actor_id uuid, p_expected_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior private.goods_group_operations;existing private.goods_groups;expected_hash text;target_ids text[];lock_ids text[];
 common_id text;common_data jsonb;source_ip text;row record;unit_id uuid;before_value jsonb;result jsonb;current_command text;
begin
 perform private.require_goods_group_identity(p_expected_actor_id,p_expected_session_id);
 perform private.validate_goods_group_structure(p_values);
 if p_group_id is null or p_expected_revision is null or p_expected_revision<0 or p_operation_id is null then
  raise invalid_parameter_value using message='invalid_goods_group_operation';end if;
 current_command:=case when p_expected_revision=0 then 'create' else 'update' end;
 expected_hash:=encode(extensions.digest(jsonb_build_array(current_command,p_group_id,p_expected_revision,p_values)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('goods-group-operation:'||p_operation_id::text,0));
 select * into prior from private.goods_group_operations where operation_id=p_operation_id;
 if found then
  if prior.actor_id<>p_expected_actor_id or prior.session_id<>p_expected_session_id or prior.command<>current_command
   or prior.target_group_id is distinct from p_group_id or prior.expected_revision is distinct from p_expected_revision
   or prior.receipt is null then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  if prior.receipt->>'state'='sealed' then return prior.receipt;end if;
  if prior.request_hash<>expected_hash then raise sqlstate 'PT409' using message='goods_group_operation_conflict';end if;
  return prior.receipt;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-stock-successor-topology:v1',0));
 perform private.lock_catalog_category_tree();
 select * into existing from private.goods_groups where id=p_group_id for update;
 if (existing.id is null and p_expected_revision<>0) or (existing.id is not null and existing.revision<>p_expected_revision)
  or existing.archived_at is not null then raise sqlstate 'PT409' using message='goods_group_changed';end if;
 if existing.id is null and jsonb_array_length(p_values->'members')<2 then
  raise check_violation using message='goods_group_members_required';end if;
 before_value:=private.goods_group_snapshot(p_group_id);
 target_ids:=array(select m->>'goodId' from jsonb_array_elements(p_values->'members') m);
 lock_ids:=array(select distinct id from(
  select unnest(target_ids) id union select good_id from private.goods_group_members where group_id=p_group_id
  union select private.goods_aggregation_owner(unnest(target_ids))) all_ids order by id);
 perform 1 from public.goods where id=any(lock_ids) order by id for update;
 perform 1 from public.goods_variants where good_id=any(lock_ids) order by good_id,id for update;
 for source_ip in select distinct ip_id from public.goods where id=any(target_ids) order by ip_id loop
  begin perform 1 from public.ips where id=source_ip for update nowait;
  exception when lock_not_available then raise sqlstate 'PT409' using message='goods_group_retry';end;
 end loop;
 if (select count(*) from public.goods where id=any(target_ids) and archived_at is null)<>cardinality(target_ids)
  or exists(select 1 from private.goods_group_members where good_id=any(target_ids) and group_id<>p_group_id) then
  raise check_violation using message='goods_group_member_unavailable';end if;
 common_id:=case when existing.common_good_id=any(target_ids) then existing.common_good_id else target_ids[1] end;
 common_data:=private.goods_group_common_identity(common_id);
 if exists(select 1 from unnest(target_ids) id where private.goods_group_common_identity(id) is distinct from common_data) then
  raise check_violation using message='goods_group_common_information_differs';end if;
 if exists(select 1 from unnest(target_ids) target(id) where (select count(*) from public.goods_variants v where v.good_id=target.id and v.archived_at is null)<>1
  or not exists(select 1 from public.goods_variants v where v.good_id=target.id and v.archived_at is null and v.is_default)) then
  raise check_violation using message='goods_group_single_variant_required';end if;
 insert into private.goods_group_operations(operation_id,actor_id,session_id,command,target_group_id,expected_revision,request_hash)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,current_command,p_group_id,p_expected_revision,expected_hash);
 insert into private.goods_group_write_authorizations(transaction_id,good_id,actor_id)
 select txid_current(),id,p_expected_actor_id from unnest(target_ids) id;
 if existing.id is null then
  insert into private.goods_groups(id,name,option_names,common_good_id,created_by,updated_by)
  values(p_group_id,p_values->>'name',array(select jsonb_array_elements_text(p_values->'optionNames')),common_id,p_expected_actor_id,p_expected_actor_id);
 else
  update private.goods_groups set name=p_values->>'name',option_names=array(select jsonb_array_elements_text(p_values->'optionNames')),
   common_good_id=common_id,revision=revision+1,updated_by=p_expected_actor_id,updated_at=clock_timestamp() where id=p_group_id;
 end if;
 delete from private.goods_group_members where group_id=p_group_id;
 for row in select value,ordinality from jsonb_array_elements(p_values->'members') with ordinality loop
  select id into unit_id from public.goods_variants where good_id=row.value->>'goodId' and archived_at is null and is_default;
  update public.goods set published_at=null,name=p_values->>'name'||' '||array_to_string(array(select jsonb_array_elements_text(row.value->'values')),' / ')
   where id=row.value->>'goodId';
  perform private.invalidate_goods_kc_review(row.value->>'goodId','goods_group_updated');
  update public.goods_variants set name='기본 옵션',attributes='{}' where id=unit_id;
  insert into private.goods_group_members(group_id,good_id,variant_id,option_values,sort_order)
  values(p_group_id,row.value->>'goodId',unit_id,array(select jsonb_array_elements_text(row.value->'values')),row.ordinality-1);
 end loop;
 result:=jsonb_build_object('state','completed','operationId',p_operation_id,'group',private.goods_group_snapshot(p_group_id));
 insert into private.goods_group_changes(group_id,operation_id,actor_id,revision,before_value,after_value)
 values(p_group_id,p_operation_id,p_expected_actor_id,(result#>>'{group,revision}')::bigint,before_value,result->'group');
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'catalog.goods_group.'||current_command,'goods_group:'||p_group_id::text,
  jsonb_build_object('before',before_value,'after',result->'group','aggregationRelationshipsPreserved',true));
 update private.goods_group_operations set receipt=result,completed_at=clock_timestamp() where operation_id=p_operation_id;
 delete from private.goods_group_write_authorizations where transaction_id=txid_current() and actor_id=p_expected_actor_id and good_id=any(target_ids);
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_kc(p_good_id text, p_models jsonb, p_status text, p_expected_revision integer, p_expected_context_fingerprint text, p_attested boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare good public.goods; current_review private.goods_kc_reviews; changed private.goods_kc_reviews;
  models jsonb; errors text[]; next_revision integer;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if not coalesce(public.has_operator_capability('catalog.manage',false),false) then raise insufficient_privilege using message='staff required'; end if;
  if p_status is null or p_status not in ('unreviewed','reviewed') then raise check_violation using message='invalid_goods_kc_review_status'; end if;
  models:=private.normalize_goods_kc_models(p_models);
  select * into good from public.goods where id=p_good_id for update;
  if not found then raise no_data_found using message='good_not_found'; end if;
  if good.archived_at is not null then raise check_violation using message='catalog_item_archived'; end if;
  select * into current_review from private.goods_kc_reviews where good_id=p_good_id for update;
  if current_review.revision is distinct from p_expected_revision or p_expected_context_fingerprint is null
    or p_expected_context_fingerprint is distinct from private.goods_kc_fingerprint(p_good_id) then
    raise sqlstate 'PT409' using message='goods_kc_review_changed';
  end if;
  if p_status='reviewed' then
    if p_attested is distinct from true then raise check_violation using message='goods_kc_attestation_required'; end if;
    errors:=private.goods_kc_review_problems(p_good_id,models);
    if cardinality(errors)>0 then raise check_violation using message='goods_kc_review_incomplete',detail=array_to_string(errors,' '); end if;
  end if;
  if current_review.models is not distinct from models and current_review.status is not distinct from p_status then
    return jsonb_build_object('changed',false,'configuration',public.admin_read_goods_kc(p_good_id));
  end if;
  if good.published_at is not null then raise check_violation using message='goods_kc_published_edit_requires_draft'; end if;
  next_revision:=coalesce(current_review.revision,0)+1;
  insert into private.goods_kc_reviews(good_id,revision,status,models,context_snapshot,reviewed_by,reviewed_at,updated_by,updated_at)
    values(p_good_id,next_revision,p_status,models,private.goods_kc_context(p_good_id),
      case when p_status='reviewed' then auth.uid() end,case when p_status='reviewed' then clock_timestamp() end,auth.uid(),clock_timestamp())
    on conflict(good_id) do update set revision=excluded.revision,status=excluded.status,models=excluded.models,
      context_snapshot=excluded.context_snapshot,reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,
      updated_by=excluded.updated_by,updated_at=excluded.updated_at returning * into changed;
  insert into private.goods_kc_review_events(good_id,revision,snapshot,reason,actor_id)
    values(p_good_id,next_revision,to_jsonb(changed),case when p_status='reviewed' then 'review_completed' else 'draft_saved' end,auth.uid());
  update public.goods set kc_disclosures='[]' where id=p_good_id;
  insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.good.kc_saved','goods:'||p_good_id,
    jsonb_build_object('before_status',current_review.status,'status',p_status,'revision',next_revision,'model_count',jsonb_array_length(models)));
  return jsonb_build_object('changed',true,'configuration',public.admin_read_goods_kc(p_good_id));
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_listing_colors(p_good_id text, p_colors jsonb, p_expected_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); previous private.goods_listing_colors%rowtype; request jsonb; receipt jsonb;
begin
 perform private.require_actor_operator_capability(actor,'catalog.manage',false);
 if p_operation_id is null or p_good_id is null or p_expected_revision is null or p_expected_revision<0 or private.goods_listing_colors_valid(p_colors) is distinct from true then
  raise invalid_parameter_value using message='invalid_goods_listing_colors';end if;
 request:=jsonb_build_object('goodId',p_good_id,'colors',p_colors,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('goods-listing-colors:operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.goods_listing_colors.updated',request);
 if receipt is not null then return receipt;end if;
 -- Serialize with rename/archive and make the first empty row participate in CAS.
 perform 1 from public.goods where id=p_good_id and archived_at is null for update;
 if not found then raise no_data_found using message='good_missing';end if;
 insert into private.goods_listing_colors(good_id) values(p_good_id) on conflict do nothing;
 select * into previous from private.goods_listing_colors where good_id=p_good_id for update;
 if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='goods_listing_colors_conflict';end if;
 update private.goods_listing_colors set colors=p_colors,revision=revision+1,updated_at=clock_timestamp() where good_id=p_good_id;
 receipt:=jsonb_build_object('colors',p_colors,'revision',previous.revision+1);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.goods_listing_colors.updated','goods:'||p_good_id,
  jsonb_build_object('request',request,'result',receipt,'before',previous.colors));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_media_settings(p_values jsonb, p_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();stored private.goods_media_settings%rowtype;receipt public.audit_log%rowtype;request jsonb;result jsonb;
begin
 perform private.require_actor_operator_capability(actor,'store.manage');
 if p_revision is null or p_revision<0 or p_operation_id is null or jsonb_typeof(p_values)<>'object' or (select count(*) from jsonb_object_keys(p_values))<>2
  or not p_values ?& array['priority','shortclips'] or jsonb_typeof(p_values->'priority')<>'string' or p_values->>'priority' not in('image','video','shortclip') or jsonb_typeof(p_values->'shortclips')<>'boolean' then raise check_violation using message='invalid_goods_media_settings';end if;
 request:=jsonb_build_object('values',p_values,'revision',p_revision);
 perform pg_advisory_xact_lock(hashtextextended('goods-media-operation:'||p_operation_id::text,0));
 select * into receipt from public.audit_log where id=p_operation_id;
 if found then
  if receipt.actor_id is distinct from actor or receipt.action<>'admin.goods_media_settings.updated' or receipt.diff->'request'<>request then raise unique_violation using message='operation_conflict';end if;
  return receipt.diff->'result';
 end if;
 select * into stored from private.goods_media_settings where id for update;
 if stored.revision<>p_revision then raise sqlstate 'PT409' using message='revision_conflict';end if;
 update private.goods_media_settings set priority=p_values->>'priority',shortclips=(p_values->>'shortclips')::boolean,revision=revision+1 where id;
 result:=jsonb_build_object('values',p_values,'revision',stored.revision+1);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.goods_media_settings.updated','product-detail',jsonb_build_object('request',request,'result',result));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_notice_preset(target_id uuid, target_name text, target_notice jsonb, expected_updated_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  normalized_name text := btrim(coalesce(target_name, ''), E' \t\n\r\f\v');
  normalized_notice jsonb;
  normalized_kc jsonb;
  previous public.goods_notice_presets;
  saved public.goods_notice_presets;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null or not public.has_operator_capability('catalog.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if char_length(normalized_name) not between 1 and 80
    or jsonb_typeof(target_notice) is distinct from 'object' then
    raise invalid_parameter_value using message = 'invalid_goods_notice_preset';
  end if;
  if not target_notice ?& array['maker','origin','material','size','madeOn','asManager','asContact']
    or exists (select 1 from jsonb_each(target_notice) as field
      where field.key not in ('maker','origin','material','size','madeOn','asManager','asContact','kcTemplate')
        or (field.key<>'kcTemplate' and jsonb_typeof(field.value) <> 'string')) then
    raise invalid_parameter_value using message = 'invalid_goods_notice_preset';
  end if;
  select jsonb_object_agg(field.key, btrim(field.value, E' \t\n\r\f\v'))
    into normalized_notice from jsonb_each_text(target_notice) as field where field.key<>'kcTemplate';
  if target_notice ? 'kcTemplate' then normalized_kc:=private.normalize_goods_notice_kc_template(target_notice->'kcTemplate'); end if;
  if exists (select 1 from jsonb_each_text(normalized_notice) as field
    where char_length(field.value) not between 1 and 1000) then
    raise invalid_parameter_value using message = 'invalid_goods_notice_preset';
  end if;

  if target_id is not null then
    select * into previous from public.goods_notice_presets where id = target_id for update;
    if not found then raise no_data_found using message = 'goods_notice_preset_not_found'; end if;
    if expected_updated_at is distinct from previous.updated_at then
      raise sqlstate 'PT409' using message = 'goods_notice_preset_conflict';
    end if;
  end if;

  if target_id is null then
    insert into public.goods_notice_presets(name,maker,origin,material,size,made_on,as_manager,as_contact,kc_template)
    values (normalized_name,normalized_notice->>'maker',normalized_notice->>'origin',
      normalized_notice->>'material',normalized_notice->>'size',normalized_notice->>'madeOn',
      normalized_notice->>'asManager',normalized_notice->>'asContact',normalized_kc) returning * into saved;
  else
    update public.goods_notice_presets set name = normalized_name,
      maker = normalized_notice->>'maker', origin = normalized_notice->>'origin',
      material = normalized_notice->>'material', size = normalized_notice->>'size',
      made_on = normalized_notice->>'madeOn', as_manager = normalized_notice->>'asManager',
      as_contact = normalized_notice->>'asContact',
      kc_template = case when target_notice ? 'kcTemplate' then normalized_kc else previous.kc_template end,
      updated_at = greatest(clock_timestamp(), previous.updated_at + interval '1 microsecond')
    where id = target_id returning * into saved;
  end if;

  insert into public.audit_log(actor_id,action,target,diff)
    values(actor, case when target_id is null then 'catalog.goods_notice_preset.created'
      else 'catalog.goods_notice_preset.updated' end, 'goods_notice_presets:' || saved.id::text,
      jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
  return saved.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_other_certifications(p_good_id text, p_entries jsonb, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; good public.goods; current_set private.goods_other_certifications;
  saved_set private.goods_other_certifications; normalized_entries jsonb;
begin
  actor:=private.require_operator_capability('catalog.manage',false);
  normalized_entries:=private.normalize_goods_other_certifications(p_entries);
  select * into good from public.goods where id=p_good_id for update;
  if not found then raise no_data_found using message='good_not_found'; end if;
  if good.archived_at is not null then raise check_violation using message='catalog_item_archived'; end if;
  select * into current_set from private.goods_other_certifications where good_id=p_good_id for update;
  if current_set.revision is distinct from p_expected_revision then
    raise sqlstate 'PT409' using message='goods_other_certifications_changed';
  end if;
  if coalesce(current_set.entries,'[]'::jsonb)=normalized_entries then
    return jsonb_build_object('changed',false,'configuration',public.admin_read_goods_other_certifications(p_good_id));
  end if;
  insert into private.goods_other_certifications(good_id,revision,entries,updated_by,updated_at)
    values(p_good_id,coalesce(current_set.revision,0)+1,normalized_entries,actor,clock_timestamp())
    on conflict(good_id) do update set revision=excluded.revision,entries=excluded.entries,
      updated_by=excluded.updated_by,updated_at=excluded.updated_at
    returning * into saved_set;
  -- 트리거가 원본에서 고객 표시 목록을 다시 계산한다(넣는 값은 무시된다).
  update public.goods set other_certification_disclosures='[]'::jsonb where id=p_good_id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.good.other_certifications_saved','goods:'||p_good_id,
    jsonb_build_object('revision',saved_set.revision,'before',coalesce(current_set.entries,'[]'::jsonb),'after',normalized_entries));
  return jsonb_build_object('changed',true,'configuration',public.admin_read_goods_other_certifications(p_good_id));
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_photo(p_id uuid, p_image_path text, p_name text, p_expected_revision integer, p_archived boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); previous public.goods_photo_library; saved public.goods_photo_library; object_path text; refs jsonb; clean_name text;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='forbidden'; end if;
  -- macOS 파일 이름(NFD 한글)도 화면에 보이는 그대로의 NFC로 저장해 검색에 걸리게 한다.
  clean_name:=normalize(btrim(p_name),NFC);
  if p_id is null or clean_name is null or char_length(clean_name) not between 1 and 100 or p_expected_revision is null or p_expected_revision<0 or p_archived is null then raise invalid_parameter_value using message='invalid_goods_photo'; end if;
  perform pg_advisory_xact_lock(hashtextextended('goods-photo:'||p_id::text,0));
  select * into previous from public.goods_photo_library where id=p_id for update;
  if found then
    if previous.image_path is distinct from p_image_path then raise check_violation using message='photo_path_immutable'; end if;
    -- Register retries are safe only for the exact creator and original payload.
    if p_expected_revision=0 and previous.created_by=actor and previous.revision=1 and previous.name=clean_name and previous.archived_at is null and not p_archived then
      return jsonb_build_object('id',previous.id,'revision',previous.revision);
    end if;
    if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='goods_photo_changed'; end if;
    refs:=private.goods_photo_references(previous.image_path);
    if p_archived and jsonb_array_length(refs)>0 then raise check_violation using message='goods_photo_in_use'; end if;
    update public.goods_photo_library set name=clean_name,archived_at=case when p_archived then coalesce(archived_at,clock_timestamp()) else null end,revision=revision+1,updated_at=clock_timestamp() where id=p_id returning * into saved;
  else
    if p_expected_revision<>0 or p_archived then raise sqlstate 'PT409' using message='goods_photo_changed'; end if;
    if p_image_path is null or p_image_path !~ '^public-media/catalog/good/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$' then raise check_violation using message='unverified_artwork'; end if;
    object_path:=substr(p_image_path,length('public-media/')+1);
    update public.admin_artwork_upload_claims claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
      where claim.actor_id=actor and claim.path=object_path and claim.kind='good' and claim.status='verified'
        and claim.verified_at is not null and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
    if not found then raise check_violation using message='unverified_artwork'; end if;
    insert into public.goods_photo_library(id,image_path,name,created_by) values(p_id,p_image_path,clean_name,actor) returning * into saved;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.goods.photo.saved','goods_photo:'||p_id::text,jsonb_build_object('before',case when previous.id is null then null else to_jsonb(previous) end,'after',to_jsonb(saved)));
  return jsonb_build_object('id',saved.id,'revision',saved.revision);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_preorder(p_good_id text, p_variant_id uuid, p_policy_id uuid, p_values jsonb, p_expected_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); variant public.goods_variants; previous private.goods_preorder_policies; saved private.goods_preorder_policies;
  state_value text; capacity_value integer; starts_value timestamptz; ends_value timestamptz; date_value date; evidence_value text; is_admin boolean;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor is null or not coalesce(public.has_operator_capability('catalog.manage',false),false) then raise insufficient_privilege using message='staff required'; end if;
  is_admin:=exists(select 1 from public.profiles where id=actor and private.has_operator_capability(id,'platform.manage',true));
  if jsonb_typeof(p_values) is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(p_values) key where key not in ('state','capacityQty','startsAt','endsAt','expectedShipDate','approvalReference')) then
    raise invalid_parameter_value using message='invalid_preorder_policy';
  end if;
  state_value:=p_values->>'state';
  if state_value is null or state_value not in ('draft','active','stopped') then raise check_violation using message='invalid_preorder_policy'; end if;
  if state_value='active' and not is_admin then raise insufficient_privilege using message='preorder_admin_required'; end if;
  perform 1 from public.goods where id=p_good_id and archived_at is null for update;
  if not found then raise no_data_found using message='good_not_found'; end if;
  select * into variant from public.goods_variants where id=p_variant_id and good_id=p_good_id for update;
  if not found then raise no_data_found using message='goods_variant_not_found'; end if;
  if p_policy_id is not null then
    select * into previous from private.goods_preorder_policies where id=p_policy_id and variant_id=p_variant_id for update;
    if not found then raise no_data_found using message='preorder_policy_not_found'; end if;
  end if;
  if previous.revision is distinct from p_expected_revision then raise sqlstate 'PT409' using message='preorder_policy_changed'; end if;
  if state_value='stopped' then
    if previous.state is null or previous.state='draft' then raise check_violation using message='preorder_not_active'; end if;
    if previous.state='stopped' then return jsonb_build_object('id',previous.id,'revision',previous.revision,'changed',false); end if;
    update private.goods_preorder_policies set state='stopped',stopped_by=actor,stopped_at=clock_timestamp(),
      revision=revision+1,updated_at=clock_timestamp() where id=previous.id returning * into saved;
  else
    if previous.state is not null and previous.state<>'draft' then raise check_violation using message='preorder_policy_immutable'; end if;
    if p_values->'capacityQty' is not null and p_values->'capacityQty'<>'null'::jsonb then
      if jsonb_typeof(p_values->'capacityQty')<>'number' or p_values->>'capacityQty' !~ '^[1-9][0-9]*$'
        or (p_values->>'capacityQty')::numeric>2147483647 then raise check_violation using message='invalid_preorder_policy'; end if;
      capacity_value:=(p_values->>'capacityQty')::integer;
    end if;
    if nullif(p_values->>'startsAt','') is not null then
      if jsonb_typeof(p_values->'startsAt')<>'string' or p_values->>'startsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' then raise check_violation using message='invalid_preorder_policy'; end if;
      starts_value:=(p_values->>'startsAt')::timestamptz;
    end if;
    if nullif(p_values->>'endsAt','') is not null then
      if jsonb_typeof(p_values->'endsAt')<>'string' or p_values->>'endsAt' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' then raise check_violation using message='invalid_preorder_policy'; end if;
      ends_value:=(p_values->>'endsAt')::timestamptz;
    end if;
    if nullif(p_values->>'expectedShipDate','') is not null then
      if p_values->>'expectedShipDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise check_violation using message='invalid_preorder_policy'; end if;
      date_value:=(p_values->>'expectedShipDate')::date;
    end if;
    if p_values->'approvalReference' is not null and p_values->'approvalReference'<>'null'::jsonb and jsonb_typeof(p_values->'approvalReference')<>'string' then
      raise check_violation using message='invalid_preorder_policy';
    end if;
    evidence_value:=nullif(btrim(p_values->>'approvalReference'),'');
    if (starts_value is not null and not isfinite(starts_value)) or (ends_value is not null and not isfinite(ends_value))
      or (starts_value is not null and ends_value is not null and starts_value>=ends_value)
      or length(evidence_value)>2000 then raise check_violation using message='invalid_preorder_policy'; end if;
    if state_value='active' then
      if to_regprocedure('private.preorder_checkout_ready()') is null then raise check_violation using message='preorder_runtime_not_ready'; end if;
      if capacity_value is null or starts_value is null or ends_value is null or date_value is null or evidence_value is null
        or ends_value<=clock_timestamp() or date_value<(ends_value at time zone 'Asia/Seoul')::date then
        raise check_violation using message='preorder_policy_not_configured';
      end if;
      if variant.archived_at is not null then raise check_violation using message='goods_variant_inactive'; end if;
      if exists(select 1 from private.goods_preorder_policies where variant_id=variant.id and state='active' and id is distinct from previous.id) then
        raise check_violation using message='preorder_policy_already_active';
      end if;
    end if;
    if previous.id is null then
      insert into private.goods_preorder_policies(variant_id,state,capacity_qty,starts_at,ends_at,expected_ship_date,approval_reference,created_by,activated_by,activated_at)
      values(variant.id,state_value,capacity_value,starts_value,ends_value,date_value,evidence_value,actor,
        case when state_value='active' then actor end,case when state_value='active' then clock_timestamp() end) returning * into saved;
    else
      update private.goods_preorder_policies set state=state_value,capacity_qty=capacity_value,starts_at=starts_value,ends_at=ends_value,
        expected_ship_date=date_value,approval_reference=evidence_value,revision=revision+1,updated_at=clock_timestamp(),
        activated_by=case when state_value='active' then actor end,activated_at=case when state_value='active' then clock_timestamp() end
        where id=previous.id returning * into saved;
    end if;
    if saved.state='active' then update public.goods_variants set preorder_policy_id=saved.id where id=variant.id; end if;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.good.preorder_saved','goods:'||p_good_id,
    jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
  return jsonb_build_object('id',saved.id,'revision',saved.revision,'changed',true);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_price_period(p_good_id text, p_variant_id uuid, p_period_id uuid, p_period jsonb, p_expected_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  previous private.goods_variant_price_periods;
  saved private.goods_variant_price_periods;
  variant public.goods_variants;
  next_state text;
  next_price integer;
  next_start timestamptz;
  next_end timestamptz;
  next_regular integer;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if auth.uid() is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message='staff_required'; end if;
  if jsonb_typeof(p_period) is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(p_period) key where key not in ('state','discountPrice','startsAt','endsAt'))
    or p_period->>'state' is null or p_period->>'state' not in ('draft','active','disabled') then
    raise check_violation using message='invalid_price_period';
  end if;
  next_state:=p_period->>'state';
  if coalesce(jsonb_typeof(p_period->'discountPrice'),'null')<>'null' then
    if jsonb_typeof(p_period->'discountPrice')<>'number' or p_period->>'discountPrice' !~ '^[1-9][0-9]*$'
      or (p_period->>'discountPrice')::numeric>2147483647 then
      raise check_violation using message='invalid_price_period';
    end if;
    next_price:=(p_period->>'discountPrice')::integer;
  end if;
  if coalesce(jsonb_typeof(p_period->'startsAt'),'null')<>'null' then
    if jsonb_typeof(p_period->'startsAt')<>'string' or p_period->>'startsAt' !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' then
      raise check_violation using message='price_period_timezone_required';
    end if;
    next_start:=(p_period->>'startsAt')::timestamptz;
  end if;
  if coalesce(jsonb_typeof(p_period->'endsAt'),'null')<>'null' then
    if jsonb_typeof(p_period->'endsAt')<>'string' or p_period->>'endsAt' !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' then
      raise check_violation using message='price_period_timezone_required';
    end if;
    next_end:=(p_period->>'endsAt')::timestamptz;
  end if;
  if next_state='active' and (next_price is null or next_start is null or next_end is null) then
    raise check_violation using message='price_period_not_configured';
  end if;
  if (next_start is not null and not isfinite(next_start)) or (next_end is not null and not isfinite(next_end))
    or (next_start is not null and next_end is not null and next_start>=next_end) then
    raise check_violation using message='invalid_price_period';
  end if;
  perform 1 from public.goods where id=p_good_id for update;
  if next_state='active' and exists(select 1 from public.goods g where g.id=p_good_id and g.compare_at_price>g.price) then
    raise check_violation using message='instant_discount_period_conflict';
  end if;
  select * into variant from public.goods_variants where id=p_variant_id and good_id=p_good_id for update;
  if not found then raise check_violation using message='goods_variant_not_found'; end if;
  next_regular:=variant.price;
  if p_period_id is not null then
    select * into previous from private.goods_variant_price_periods
      where id=p_period_id and good_id=p_good_id and variant_id=p_variant_id for update;
    if not found then raise no_data_found using message='price_period_not_found'; end if;
    if p_expected_revision is null or previous.revision<>p_expected_revision then
      raise sqlstate 'PT409' using message='price_period_changed';
    end if;
    if previous.state<>'draft' then next_regular:=previous.regular_price; end if;
    update private.goods_variant_price_periods set state=next_state,regular_price=next_regular,
      discount_price=next_price,starts_at=next_start,ends_at=next_end,revision=revision+1,
      updated_by=auth.uid(),updated_at=clock_timestamp()
    where id=p_period_id returning * into saved;
  else
    if p_expected_revision is not null then raise check_violation using message='invalid_price_period'; end if;
    insert into private.goods_variant_price_periods(good_id,variant_id,state,regular_price,discount_price,starts_at,ends_at,created_by,updated_by)
    values(p_good_id,p_variant_id,next_state,next_regular,next_price,next_start,next_end,auth.uid(),auth.uid())
    returning * into saved;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(auth.uid(),'admin.good.price_period_saved','goods:'||p_good_id,
    jsonb_build_object('before',case when previous.id is null then null else to_jsonb(previous) end,'after',to_jsonb(saved)));
  return jsonb_build_object('id',saved.id,'revision',saved.revision,
    'ipId',(select ip_id from public.goods where id=p_good_id));
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_production(p_good text, p_values jsonb, p_revision bigint, p_operation uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old private.goods_production_settings;prior public.audit_log;request jsonb;result jsonb;dates date[];entry jsonb;begin
 perform private.production_identity(p_actor,p_session,null,'catalog.manage');
 if p_operation is null or p_revision is null or p_revision<0 or not private.transaction_json_keys(p_values,array['enabled','leadDays','dayBasis','closedDates','publicNote','evidence','confirmed'])
  or jsonb_typeof(p_values->'enabled') is distinct from 'boolean' or coalesce(p_values->>'dayBasis','') not in('calendar','business')
  or p_values->'leadDays'<>'null'::jsonb and(jsonb_typeof(p_values->'leadDays')<>'number' or p_values->>'leadDays'!~'^[1-9][0-9]*$' or (p_values->>'leadDays')::numeric>365)
  or p_values->'enabled'='true'::jsonb and p_values->'leadDays'='null'::jsonb
  or jsonb_typeof(p_values->'closedDates') is distinct from 'array' or jsonb_array_length(p_values->'closedDates')>1000
  or jsonb_typeof(p_values->'publicNote') is distinct from 'string' or char_length(p_values->>'publicNote')>1000
  or jsonb_typeof(p_values->'evidence') is distinct from 'string' or char_length(btrim(p_values->>'evidence')) not between 2 and 1000
  or ((p_values->>'evidence')||(p_values->>'publicNote'))~'[[:cntrl:]]' or p_values->'confirmed' is distinct from 'true'::jsonb then raise invalid_parameter_value;end if;
 dates:='{}';
 for entry in select value from jsonb_array_elements(p_values->'closedDates') loop
  if jsonb_typeof(entry)<>'string' or entry#>>'{}'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise invalid_parameter_value;end if;
  begin dates:=array_append(dates,(entry#>>'{}')::date);exception when others then raise invalid_parameter_value;end;
 end loop;
 if cardinality(dates)<>(select count(distinct d) from unnest(dates)d) then raise invalid_parameter_value;end if;
 if p_values->>'dayBasis'='calendar' and cardinality(dates)>0 then raise invalid_parameter_value;end if;
 perform 1 from public.goods where id=p_good and archived_at is null for update;if not found then raise no_data_found;end if;
 select * into old from private.goods_production_settings where good_id=p_good for update;
 request:=jsonb_build_object('goodId',p_good,'values',p_values,'revision',p_revision,'sessionId',p_session);
 select * into prior from public.audit_log where id=p_operation;
 if found then if prior.actor_id is distinct from p_actor or prior.action<>'admin.goods.production_policy' or prior.diff->'request' is distinct from request then raise sqlstate 'PT409';end if;return prior.diff->'result';end if;
 if coalesce(old.revision,0)<>p_revision then raise sqlstate 'PT409' using message='production_changed';end if;
 if p_values->'enabled'='true'::jsonb then
  perform private.assert_goods_transaction_runtime();
  if exists(select 1 from public.goods_variants where good_id=p_good and preorder_policy_id is not null and archived_at is null) then raise check_violation using message='production_preorder_conflict';end if;
 end if;
 insert into private.goods_production_settings(good_id,revision,enabled,lead_days,day_basis,closed_dates,public_note,evidence)
 values(p_good,p_revision+1,(p_values->>'enabled')::boolean,(p_values->>'leadDays')::integer,p_values->>'dayBasis',array(select d from unnest(dates)d order by d),btrim(p_values->>'publicNote'),btrim(p_values->>'evidence'))
 on conflict(good_id) do update set revision=excluded.revision,enabled=excluded.enabled,lead_days=excluded.lead_days,day_basis=excluded.day_basis,
  closed_dates=excluded.closed_dates,public_note=excluded.public_note,evidence=excluded.evidence,updated_at=clock_timestamp();
 result:=private.goods_production_document(p_good);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation,p_actor,'admin.goods.production_policy','good:'||p_good,jsonb_build_object('request',request,'result',result));return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_relation_composition(p_id uuid, p_expected_revision integer, p_operation_id uuid, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();prior public.goods_relations;saved public.goods_relations;existing public.audit_log;
 request_value jsonb;result_value jsonb;before_document jsonb;visual jsonb;ids text[];bad_id text;image_value text;
begin
 perform private.require_operator_capability('catalog.manage',false);
 if p_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 then raise invalid_parameter_value using message='invalid_goods_relation';end if;
 perform private.validate_goods_relation_composition(p_values);
 request_value:=jsonb_build_object('expectedRevision',p_expected_revision,'values',p_values);
 perform pg_advisory_xact_lock(hashtextextended('goods-relation-operation:'||p_operation_id::text,0));
 select * into existing from public.audit_log where id=p_operation_id;
 if found then
  if existing.actor_id=actor and existing.action='admin.goods.relation.saved' and existing.target='goods_relation:'||p_id::text and existing.diff->'request'=request_value then return existing.diff->'result';end if;
  raise sqlstate 'PT409' using message='goods_relation_operation_conflict';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-relation:'||p_id::text,0));
 select * into prior from public.goods_relations where id=p_id for update;
 if found then
  if prior.revision<>p_expected_revision then raise sqlstate 'PT409' using message='goods_relation_changed';end if;
  before_document:=private.goods_relation_document(p_id);
 elsif p_expected_revision<>0 then raise sqlstate 'PT409' using message='goods_relation_changed';end if;
 select array_agg(value order by position) into ids from jsonb_array_elements_text(p_values->'goodIds') with ordinality item(value,position);
 perform 1 from public.goods where id=any(ids) order by id for share;
 -- Retain the existing relation contract: unavailable records can remain in a
 -- composition, while both public readers independently apply visibility gates.
 select requested.id into bad_id from unnest(ids) requested(id) left join public.goods g on g.id=requested.id where g.id is null limit 1;
 if bad_id is not null then raise invalid_parameter_value using message='invalid_goods_relation_goods';end if;
 visual:=nullif(p_values->'visual','null'::jsonb);image_value:=visual->>'imagePath';
 if image_value is not null and image_value is distinct from prior.image_path then
  update public.admin_artwork_upload_claims claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
  where claim.actor_id=actor and claim.kind='curation' and claim.path=substr(image_value,length('public-media/')+1)
   and claim.status='verified' and claim.verified_at is not null and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
  if not found then raise check_violation using message='unverified_artwork';end if;
 end if;
 if prior.id is null then
  insert into public.goods_relations(id,kind,title,representative_good_id,enabled,starts_at,ends_at,image_path,image_alt,description,created_by,updated_by)
  values(p_id,p_values->>'kind',btrim(p_values->>'title'),p_values->>'representativeGoodId',(p_values->>'enabled')::boolean,
   (p_values->>'startsAt')::timestamptz,(p_values->>'endsAt')::timestamptz,image_value,coalesce(btrim(visual->>'alt'),''),coalesce(btrim(visual->>'description'),''),actor,actor) returning * into saved;
 else
  update public.goods_relations set kind=p_values->>'kind',title=btrim(p_values->>'title'),representative_good_id=p_values->>'representativeGoodId',enabled=(p_values->>'enabled')::boolean,
   starts_at=(p_values->>'startsAt')::timestamptz,ends_at=(p_values->>'endsAt')::timestamptz,image_path=image_value,image_alt=coalesce(btrim(visual->>'alt'),''),description=coalesce(btrim(visual->>'description'),''),
   revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id=p_id returning * into saved;
 end if;
 -- Member replacement cascades old points; recreated points must target the new members.
 delete from public.goods_relation_members where relation_id=p_id;
 insert into public.goods_relation_members(relation_id,good_id,position,composition_label)
 select p_id,id,position::integer,case when p_values->>'kind'='other_composition' then
  (select entry->>'label' from jsonb_array_elements(p_values->'compositionLabels') entry where entry->>'goodId'=id) else null end
 from unnest(ids) with ordinality item(id,position);
 if visual is not null then
  insert into public.goods_relation_hotspots(relation_id,good_id,x,y) select p_id,item->>'goodId',(item->>'x')::integer,(item->>'y')::integer from jsonb_array_elements(visual->'hotspots')item;
 end if;
 result_value:=jsonb_build_object('id',p_id,'revision',saved.revision);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.goods.relation.saved','goods_relation:'||p_id,
  jsonb_build_object('request',request_value,'before',before_document,'after',private.goods_relation_document(p_id),'result',result_value));
 return result_value;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_goods_relation(p_id uuid, p_expected_revision integer, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform private.require_operator_capability('catalog.manage',false);
 if jsonb_typeof(p_values) is distinct from 'object' or p_values ? 'visual' or p_values->>'kind' not in ('together','similar')
  or exists(select 1 from public.goods_relations where id=p_id and (image_path is not null or kind='other_composition')) then raise invalid_parameter_value using message='goods_relation_visual_required';end if;
