CREATE OR REPLACE FUNCTION public.admin_save_home_layout(target_operation_id uuid, expected_revision bigint, target_blocks jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid()); previous public.home_layout_settings; saved public.home_layout_settings;
  audit_entry public.audit_log; request_payload jsonb; block_ref record;
begin
  perform private.require_operator_capability('store.manage',false);

  if actor is null then raise invalid_authorization_specification using message='auth_required'; end if;
  if not public.has_operator_capability('store.manage',false) then raise insufficient_privilege using message='forbidden'; end if;
  if target_operation_id is null or expected_revision is null or expected_revision<0
    or target_blocks is null or not private.is_valid_home_layout_blocks(target_blocks)
  then raise invalid_parameter_value using message='invalid_home_layout'; end if;
  request_payload := pg_catalog.jsonb_build_object('expected_revision',expected_revision,'blocks',target_blocks);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin_home_layout_operation:'||target_operation_id::text,0));
  select * into audit_entry from public.audit_log where id=target_operation_id;
  if found then
    if audit_entry.actor_id=actor and audit_entry.action='admin.home_layout.saved'
      and audit_entry.target='home_layout_settings' and audit_entry.diff->'request'=request_payload
    then return (audit_entry.diff->'after'->>'revision')::bigint; end if;
    raise unique_violation using message='operation_conflict';
  end if;

  select * into previous from public.home_layout_settings where singleton for update;
  if not found or previous.revision<>expected_revision then
    raise sqlstate 'PT409' using message='home_layout_conflict';
  end if;
  for block_ref in
    select split_part(entry->>'key',':',2)::uuid as id,
      case split_part(entry->>'key',':',1) when 'band' then 'band_banner' when 'sales' then 'sales_best' when 'reviews' then 'review_best' when 'mosaic' then 'product_mosaic' else 'product_collection' end as kind
    from pg_catalog.jsonb_array_elements(target_blocks) entry
    where position(':' in (entry->>'key'))>0 order by entry->>'key'
  loop
    perform 1 from public.home_curations where id=block_ref.id and kind=block_ref.kind for share;
    if not found then raise no_data_found using message='home_layout_block_not_found'; end if;
  end loop;

  update public.home_layout_settings set blocks=target_blocks,revision=revision+1,updated_at=clock_timestamp()
  where singleton returning * into saved;
  insert into public.audit_log(id,actor_id,action,target,diff)
  values(target_operation_id,actor,'admin.home_layout.saved','home_layout_settings',pg_catalog.jsonb_build_object(
    'request',request_payload,
    'before',pg_catalog.jsonb_build_object('blocks',previous.blocks,'revision',previous.revision),
    'after',pg_catalog.jsonb_build_object('blocks',saved.blocks,'revision',saved.revision)
  ));
  return saved.revision;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_ip_hall_banner(target_ip_id text, target_image_path text, target_mobile_image_path text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_image_path text := nullif(pg_catalog.btrim(target_image_path), '');
  normalized_mobile_image_path text := nullif(pg_catalog.btrim(target_mobile_image_path), '');
  previous_ip public.ips%rowtype;
  saved_at timestamptz;
begin
  perform private.require_operator_capability('platform.manage', false);

  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;
  if target_ip_id is null or pg_catalog.btrim(target_ip_id) = '' then
    raise invalid_parameter_value using message = 'invalid_ip_id';
  end if;
  if (normalized_image_path is not null
      and normalized_image_path !~ '^public-media/catalog/ip/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$')
    or (normalized_mobile_image_path is not null
      and normalized_mobile_image_path !~ '^public-media/catalog/ip/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$')
  then
    raise check_violation using message = 'invalid_ip_banner_image_path';
  end if;

  select ip.* into previous_ip from public.ips as ip where ip.id = target_ip_id for update of ip;
  if not found then
    raise no_data_found using message = 'catalog_record_missing';
  end if;

  -- Saving the same pair again is a no-op: no new version, no audit noise.
  if previous_ip.hall_banner_image_path is not distinct from normalized_image_path
    and previous_ip.hall_banner_mobile_image_path is not distinct from normalized_mobile_image_path
  then
    return previous_ip.updated_at;
  end if;

  update public.ips
  set
    hall_banner_image_path = normalized_image_path,
    hall_banner_mobile_image_path = normalized_mobile_image_path
  where id = target_ip_id
  returning updated_at into saved_at;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'catalog.ip.hall_banner',
    'ips:' || target_ip_id,
    pg_catalog.jsonb_build_object(
      'before', pg_catalog.jsonb_build_object(
        'hall_banner_image_path', previous_ip.hall_banner_image_path,
        'hall_banner_mobile_image_path', previous_ip.hall_banner_mobile_image_path
      ),
      'after', pg_catalog.jsonb_build_object(
        'hall_banner_image_path', normalized_image_path,
        'hall_banner_mobile_image_path', normalized_mobile_image_path
      )
    )
  );

  return saved_at;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_loyalty_policy(p_tiers jsonb, p_expected_revision integer, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); previous public.loyalty_settings; saved public.loyalty_settings; existing public.audit_log; result jsonb;
begin
  perform private.require_operator_capability('marketing.manage',true);

  if private.is_account_write_fenced(actor) then raise insufficient_privilege using message='admin_required'; end if;
  perform 1 from public.profiles where id=actor and private.has_operator_capability(id,'marketing.manage',true) and suspended_at is null for share;
  if not found then raise insufficient_privilege using message='admin_required'; end if;
  if p_operation_id is null or p_expected_revision is null or p_expected_revision<1 or not coalesce(private.loyalty_criteria_valid(p_tiers),false)
    then raise invalid_parameter_value using message='invalid_loyalty_policy'; end if;
  select * into strict previous from public.loyalty_settings where singleton for update;
  select * into existing from public.audit_log where id=p_operation_id;
  if found then
    if existing.actor_id=actor and existing.action='commerce.loyalty.policy_updated' and existing.target='loyalty_settings'
      and existing.diff->'after'=p_tiers and (existing.diff->>'expectedRevision')::integer=p_expected_revision then return existing.diff->'result'; end if;
    raise unique_violation using message='operation_conflict';
  end if;
  if previous.revision<>p_expected_revision then raise sqlstate 'PT409' using message='loyalty_policy_changed'; end if;
  update public.loyalty_settings set tiers=p_tiers,revision=revision+1,updated_at=clock_timestamp() where singleton returning * into saved;
  result:=jsonb_build_object('revision',saved.revision,'updatedAt',saved.updated_at);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'commerce.loyalty.policy_updated','loyalty_settings',
    jsonb_build_object('before',previous.tiers,'after',saved.tiers,'expectedRevision',p_expected_revision,'result',result));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_marketing_campaign(p_id uuid, p_expected_revision integer, p_operation_id uuid, p_values jsonb, p_publish boolean, p_estimate_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; segment private.customer_segments; previous private.marketing_campaigns; estimate private.customer_segment_estimates;
 content_value jsonb; name_value text; request jsonb; replay jsonb; result jsonb; times timestamptz[]; new_revision integer; image_value text;
begin
 actor:=private.require_operator_capability('marketing.manage',false);
 if p_id is null or p_expected_revision is null or p_expected_revision<0 or p_operation_id is null or p_publish is null
  or jsonb_typeof(p_values) is distinct from 'object' or not(p_values ?& array['name','segmentId','segmentRevision','content','schedule','exclusion'])
  or exists(select 1 from jsonb_object_keys(p_values) key where key<>all(array['name','segmentId','segmentRevision','content','schedule','exclusion','copyFrom']))
  or jsonb_typeof(p_values->'name') is distinct from 'string' or char_length(btrim(p_values->>'name')) not between 1 and 50 or p_values->>'name'~'[[:cntrl:]]'
  or jsonb_typeof(p_values->'segmentId') is distinct from 'string' or p_values->>'segmentId' !~* '^[0-9a-f-]{36}$'
  or jsonb_typeof(p_values->'segmentRevision') is distinct from 'number' or p_values->>'segmentRevision' !~ '^[1-9][0-9]{0,8}$'
  or jsonb_typeof(p_values->'exclusion') is distinct from 'string' or p_values->>'exclusion' not in ('none','received','read')
 then raise invalid_parameter_value using message='invalid_marketing_campaign';end if;
 content_value:=private.normalize_marketing_content(p_values->'content');name_value:=btrim(p_values->>'name');
 request:=jsonb_build_object('id',p_id,'revision',p_expected_revision,'values',p_values,'publish',p_publish,'estimateId',p_estimate_id);
 perform pg_advisory_xact_lock(hashtextextended('marketing-operation:'||p_operation_id::text,0));
 replay:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.marketing.saved',request);if replay is not null then return replay;end if;
 perform pg_advisory_xact_lock(hashtextextended('marketing-campaign:'||p_id::text,0));
 select * into previous from private.marketing_campaigns where id=p_id for update;
 if found and (previous.revision<>p_expected_revision or previous.archived_at is not null or previous.state<>'draft') or not found and p_expected_revision<>0 then raise sqlstate 'PT409' using message='marketing_campaign_changed';end if;
 select * into segment from private.customer_segments where id=(p_values->>'segmentId')::uuid and archived_at is null for share;
 if not found or segment.revision<>(p_values->>'segmentRevision')::integer or not private.customer_segment_references_available(segment.rule) then raise sqlstate 'PT409' using message='customer_segment_changed';end if;
 if not private.marketing_content_available(content_value) then raise check_violation using message='marketing_product_unavailable';end if;
 -- Future schedules are validated for drafts as well. Immediate drafts can be saved outside the delivery window.
 if p_publish or p_values->'schedule' <> '{"kind":"immediate"}' then times:=private.marketing_schedule_times(p_values->'schedule',statement_timestamp());end if;
 if p_publish then
  select * into estimate from private.customer_segment_estimates where id=p_estimate_id;
  if not found or estimate.actor_id is distinct from actor or estimate.rule_hash<>segment.rule_hash or estimate.rule<>segment.rule or estimate.valid_until<=statement_timestamp() then raise check_violation using message='customer_segment_estimate_required';end if;
 end if;
 image_value:=content_value->>'imagePath';
 if image_value is not null and image_value is distinct from previous.content->>'imagePath' then
  if p_values->>'copyFrom' is not null and previous.id is null and exists(select 1 from private.marketing_campaigns src where src.id::text=p_values->>'copyFrom' and src.content->>'imagePath'=image_value) then null;
  else
   update public.admin_artwork_upload_claims claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
   where claim.actor_id=actor and claim.kind='curation' and claim.path=substr(image_value,14) and claim.status='verified' and claim.verified_at is not null and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
   if not found then raise check_violation using message='unverified_artwork';end if;
  end if;
 end if;
 if previous.id is null then
  insert into private.marketing_campaigns(id,name,segment_id,segment_revision,rule,rule_hash,content,schedule,exclusion,state,sender_id,estimate_id,created_by,updated_by)
