CREATE OR REPLACE FUNCTION public.admin_save_review_event(p_id uuid, p_expected_revision integer, p_operation_id uuid, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); existing private.review_events%rowtype; request jsonb; receipt jsonb; before_value jsonb; target text; policy private.store_credit_policy;
begin
 perform private.require_actor_operator_capability(actor,'cs.manage',false);
 if p_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 or private.review_event_values_valid(p_values) is distinct from true then raise invalid_parameter_value using message='invalid_review_event';end if;
 request:=jsonb_build_object('id',p_id,'revision',p_expected_revision,'values',p_values);
 perform pg_advisory_xact_lock(hashtextextended('review-event:operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.review_event.saved',request);if receipt is not null then return receipt;end if;
 perform pg_advisory_xact_lock(hashtextextended('review-event:'||p_id::text,0));
 select * into existing from private.review_events where id=p_id for update;
 if found then
  if existing.revision<>p_expected_revision then raise sqlstate 'PT409' using message='review_event_changed';end if;
  if existing.archived_at is not null or existing.announced_at is not null or (clock_timestamp() at time zone 'Asia/Seoul')::date>=existing.starts_on then raise check_violation using message='review_event_terms_locked';end if;
 elsif p_expected_revision<>0 then raise sqlstate 'PT409' using message='review_event_changed';end if;
 if (p_values->>'startsOn')::date<=(clock_timestamp() at time zone 'Asia/Seoul')::date then raise check_violation using message='review_event_start_tomorrow';end if;
 select * into policy from private.store_credit_policy where singleton for share;
 if not policy.enabled or (p_values->>'creditAmount')::bigint>policy.max_balance or (p_values->>'creditValidityDays')::integer>policy.validity_days then raise check_violation using message='review_event_credit_policy';end if;
 before_value:=private.review_event_document(p_id);
 for target in select value from jsonb_array_elements_text(p_values->'goodIds') order by value loop
  perform 1 from public.goods where id=target and archived_at is null for key share;
  if not found then raise no_data_found using message='review_event_target_missing';end if;
 end loop;
 for target in select value from jsonb_array_elements_text(p_values->'categoryIds') order by value loop
  perform 1 from public.catalog_categories where id=target::uuid and archived_at is null for key share;
  if not found then raise no_data_found using message='review_event_target_missing';end if;
 end loop;
 insert into private.review_events(id,title,description,target_type,starts_on,ends_on,announces_on,planned_winners,credit_amount,credit_validity_days,banner_style,created_by)
 values(p_id,p_values->>'title',p_values->>'description',p_values->>'targetType',(p_values->>'startsOn')::date,(p_values->>'endsOn')::date,(p_values->>'announcesOn')::date,
  (p_values->>'plannedWinners')::integer,(p_values->>'creditAmount')::bigint,(p_values->>'creditValidityDays')::integer,p_values->>'bannerStyle',actor)
 on conflict(id) do update set title=excluded.title,description=excluded.description,target_type=excluded.target_type,starts_on=excluded.starts_on,ends_on=excluded.ends_on,
  announces_on=excluded.announces_on,planned_winners=excluded.planned_winners,credit_amount=excluded.credit_amount,credit_validity_days=excluded.credit_validity_days,
  banner_style=excluded.banner_style,revision=private.review_events.revision+1,updated_at=clock_timestamp();
 delete from private.review_event_goods where event_id=p_id;delete from private.review_event_categories where event_id=p_id;
 insert into private.review_event_goods select p_id,value from jsonb_array_elements_text(p_values->'goodIds');
 insert into private.review_event_categories select p_id,value::uuid from jsonb_array_elements_text(p_values->'categoryIds');
 receipt:=private.review_event_document(p_id);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.review_event.saved','review_event:'||p_id,jsonb_build_object('request',request,'result',receipt,'before',before_value));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_review_type_policy(p_values jsonb, p_revision bigint, p_operation uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare policy private.review_type_policy;prior public.audit_log;request jsonb;result jsonb;k text;begin
 if p_actor is null or p_actor is distinct from auth.uid() or p_session is null or auth.jwt()->>'session_id' is distinct from p_session::text then raise insufficient_privilege;end if;
 perform private.gift_lock_subjects(array[p_actor]);perform private.lock_operator_subjects(array[p_actor]);
 perform private.assert_active_user(p_actor);perform private.require_operator_capability('cs.manage',false);
 perform 1 from auth.sessions where id=p_session and user_id=p_actor and(not_after is null or not_after>clock_timestamp()) for share;
 if not found or private.is_account_write_fenced(p_actor) then raise insufficient_privilege;end if;
 if p_operation is null or p_revision is null or p_revision<1 or not private.transaction_json_keys(p_values,array['enabled','basis','startDays','endDays','maxOrderDays','rewardEligible','evidence','confirmed'])
 or jsonb_typeof(p_values->'enabled') is distinct from 'boolean' or jsonb_typeof(p_values->'rewardEligible') is distinct from 'boolean'
 or coalesce(p_values->>'basis','') not in('delivered','confirmed') or p_values->'confirmed' is distinct from 'true'::jsonb
 or jsonb_typeof(p_values->'evidence') is distinct from 'string' or char_length(btrim(p_values->>'evidence')) not between 2 and 1000
 or (p_values->>'evidence')~'[[:cntrl:]]' then raise invalid_parameter_value;end if;
 foreach k in array array['startDays','endDays','maxOrderDays'] loop
  if p_values->k<>'null'::jsonb and (jsonb_typeof(p_values->k)<>'number' or p_values->>k!~'^[1-9][0-9]*$' or (p_values->>k)::numeric>1095) then raise invalid_parameter_value;end if;
 end loop;
 if (p_values->>'startDays')::integer not between 30 and 365 or (p_values->>'endDays')::integer not between 30 and 730
  or (p_values->>'endDays')::integer<(p_values->>'startDays')::integer
  or p_values->'enabled'='true'::jsonb and (p_values->'startDays'='null'::jsonb or p_values->'endDays'='null'::jsonb) then raise invalid_parameter_value;end if;
 select * into policy from private.review_type_policy where singleton for update;
 request:=jsonb_build_object('values',p_values,'revision',p_revision,'sessionId',p_session);
 select * into prior from public.audit_log where id=p_operation;
 if found then
  if prior.actor_id is distinct from p_actor or prior.action<>'admin.review_type.policy' or prior.diff->'request' is distinct from request then raise sqlstate 'PT409';end if;
  return prior.diff->'result';end if;
 if policy.revision<>p_revision then raise sqlstate 'PT409' using message='review_type_policy_changed';end if;
 if policy.reward_eligible is distinct from (p_values->>'rewardEligible')::boolean then perform private.require_operator_capability('marketing.manage',true);end if;
 update private.review_type_policy set revision=revision+1,enabled=(p_values->>'enabled')::boolean,basis=p_values->>'basis',start_days=(p_values->>'startDays')::integer,
  end_days=(p_values->>'endDays')::integer,max_order_days=(p_values->>'maxOrderDays')::integer,reward_eligible=(p_values->>'rewardEligible')::boolean,
  evidence=btrim(p_values->>'evidence'),updated_at=clock_timestamp() where singleton;
 result:=private.review_type_policy_document();
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation,p_actor,'admin.review_type.policy','review_type',jsonb_build_object('request',request,'result',result));return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_shipping_carrier_tracking_format(target_code text, target_pattern text, target_rule text, target_sample text, expected_updated_at timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); previous public.shipping_carriers; saved public.shipping_carriers;
  code_value text := btrim(coalesce(target_code, '')); pattern_value text := nullif(btrim(coalesce(target_pattern, '')), '');
  rule_value text := nullif(btrim(coalesce(target_rule, '')), ''); sample_value text := private.normalize_tracking_number(target_sample);
begin
  perform private.require_operator_capability('platform.manage', true);
  if actor is null or not public.has_operator_capability('platform.manage', true) then raise insufficient_privilege using message = 'admin_required'; end if;
  if (pattern_value is null) <> (rule_value is null) or char_length(coalesce(pattern_value, '')) > 200 or char_length(coalesce(rule_value, '')) > 60
    or (pattern_value is not null and pattern_value !~ '^\^.+\$$') then
    raise invalid_parameter_value using message = 'invalid_tracking_number_format'; end if;
  if pattern_value is not null then
    begin
      if sample_value is null or sample_value !~ '^[A-Z0-9]{8,30}$' or not (sample_value ~ pattern_value) then
        raise invalid_parameter_value using message = 'tracking_number_format_sample_mismatch'; end if;
    exception when invalid_regular_expression then
      raise invalid_parameter_value using message = 'invalid_tracking_number_format';
    end;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('shipping_carrier:' || code_value, 0));
  select * into previous from public.shipping_carriers where code = code_value for update;
  if not found then raise no_data_found using message = 'shipping_carrier_not_found'; end if;
  if expected_updated_at is distinct from previous.updated_at then raise sqlstate 'PT409' using message = 'store_settings_conflict'; end if;
  update public.shipping_carriers set tracking_number_pattern = pattern_value, tracking_number_rule = rule_value
    where code = code_value returning * into saved;
  insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.shipping_carrier.saved', 'shipping_carriers:' || code_value,
    jsonb_build_object('before', to_jsonb(previous), 'after', to_jsonb(saved)));
  return saved.updated_at;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_shipping_carrier(target_code text, target_label text, target_url text, target_active boolean, expected_updated_at timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); previous public.shipping_carriers; saved public.shipping_carriers;
  code_value text:=btrim(coalesce(target_code,'')); label_value text:=btrim(coalesce(target_label,'')); url_value text:=btrim(coalesce(target_url,''));
begin
  perform private.require_operator_capability('platform.manage',true);

  if actor is null or not public.has_operator_capability('platform.manage',true) or not exists(select 1 from public.profiles where id=actor and private.has_operator_capability(id,'platform.manage',true)) then raise insufficient_privilege using message='admin_required'; end if;
  if code_value !~ '^[a-z0-9_]{2,32}$' or length(label_value) not between 1 and 60 or target_active is null
    or length(url_value)>500 or position('{trackingNumber}' in url_value)=0
    or url_value !~ '^https://[A-Za-z0-9][A-Za-z0-9.-]*(:[0-9]{1,5})?[/#?]'
    or url_value ~ '[[:space:]\\]' then raise invalid_parameter_value using message='invalid_shipping_carrier'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('shipping_carrier:'||code_value,0));
  select * into previous from public.shipping_carriers where code=code_value for update;
  if found then
    if expected_updated_at is distinct from previous.updated_at then raise sqlstate 'PT409' using message='store_settings_conflict'; end if;
    update public.shipping_carriers set label=label_value,tracking_url_template=url_value,is_active=target_active
      where code=code_value returning * into saved;
  else
    if expected_updated_at is not null then raise no_data_found using message='shipping_carrier_not_found'; end if;
    insert into public.shipping_carriers(code,label,tracking_url_template,is_active)
      values(code_value,label_value,url_value,target_active) returning * into saved;
  end if;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.shipping_carrier.saved','shipping_carriers:'||code_value,
    jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
  return saved.updated_at;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_shipping_charge_group(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare context jsonb;request_hash text;receipt jsonb;origin public.fulfillment_origins;previous private.shipping_charge_groups;
 previous_version private.shipping_charge_group_versions;default_group private.shipping_charge_groups;default_version private.shipping_charge_group_versions;
 policy_values jsonb;region_changed boolean;requires_confirmation boolean;confirmed_by uuid;confirmed_at timestamptz;default_result jsonb;before_document jsonb;
begin
 -- Reject missing authority before parsing caller-controlled operation JSON.
 if (select auth.uid()) is null then raise invalid_authorization_specification using message='auth_required';end if;
 if not public.has_operator_capability('catalog.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';
 end if;
 context:=private.shipping_charge_group_context(p_request);
 perform private.require_shipping_charge_group_identity((context->>'expectedActorId')::uuid,(context->>'expectedSessionId')::uuid);
 if not private.transaction_json_keys(p_request,array['operationId','command','groupId','expectedRevision','expectedActorId','expectedSessionId',
  'originId','originUpdatedAt','expectedDefaultGroupId','expectedDefaultGroupRevision','values','attestRegional']) or context->>'command'<>'save'
  or not private.shipping_settings_uuid(p_request->'originId') or not private.transaction_instant_valid(p_request->'originUpdatedAt')
  or not (p_request->'expectedDefaultGroupId'='null'::jsonb or private.shipping_settings_uuid(p_request->'expectedDefaultGroupId'))
  or not private.transaction_uint(p_request->'expectedDefaultGroupRevision',0,2147483646)
  or ((p_request->'expectedDefaultGroupId'='null'::jsonb) is distinct from (p_request->>'expectedDefaultGroupRevision'='0'))
  or jsonb_typeof(p_request->'attestRegional') is distinct from 'boolean' then
  raise invalid_parameter_value using message='invalid_shipping_charge_group_save';end if;
 request_hash:=encode(extensions.digest(p_request::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('shipping-charge-group-operation:'||(context->>'operationId'),0));
 receipt:=private.shipping_charge_group_prior(context,request_hash);if receipt is not null then return receipt;end if;
 -- Origin serializes first-default creation and all default changes. No member
 -- product locks are acquired here; checkout acquires origin before group rows.
 select * into origin from public.fulfillment_origins where id=(p_request->>'originId')::uuid for update nowait;
 if not found then raise check_violation using message='shipping_charge_group_origin_unavailable';end if;
 if origin.updated_at is distinct from (p_request->>'originUpdatedAt')::timestamptz then raise sqlstate 'PT409' using message='shipping_charge_group_origin_changed';end if;
 perform 1 from private.shipping_charge_groups where origin_id=origin.id or id=(context->>'groupId')::uuid order by id for update nowait;
 select * into previous from private.shipping_charge_groups where id=(context->>'groupId')::uuid;
 if (found and previous.revision<>(context->>'expectedRevision')::integer) or (not found and context->>'expectedRevision'<>'0') then
  raise sqlstate 'PT409' using message='shipping_charge_group_changed';end if;
 if previous.id is not null and previous.origin_id<>origin.id then raise check_violation using message='shipping_charge_group_origin_immutable';end if;
 select * into default_group from private.shipping_charge_groups where origin_id=origin.id and is_default;
 if default_group.id is distinct from (p_request->>'expectedDefaultGroupId')::uuid
  or coalesce(default_group.revision,0)<>(p_request->>'expectedDefaultGroupRevision')::integer then
  raise sqlstate 'PT409' using message='shipping_charge_group_default_changed';end if;
 select * into previous_version from private.shipping_charge_group_versions where id=previous.version_id;
 policy_values:=private.normalize_shipping_charge_group_values(origin.id,p_request->'values');
 if (policy_values->>'enabled')::boolean and not origin.is_active then raise check_violation using message='shipping_charge_group_origin_unavailable';end if;
 if (not(policy_values->>'enabled')::boolean or (policy_values->>'archived')::boolean)
  and exists(select 1 from private.shipping_charge_group_assignments where group_id=previous.id) then
  raise check_violation using message='shipping_charge_group_has_assignments';end if;
 region_changed:=case when previous.id is null then policy_values#>>'{regional,mode}'='override'
  else previous_version.policy_values->'regional' is distinct from policy_values->'regional' end;
 requires_confirmation:=region_changed or (policy_values#>>'{regional,mode}'='override' and (policy_values->>'enabled')::boolean
  and not coalesce((previous_version.policy_values->>'enabled')::boolean,false));
 if requires_confirmation then
  perform private.require_operator_capability('platform.manage',true);
  if not(p_request->>'attestRegional')::boolean then raise check_violation using message='shipping_charge_group_region_confirmation_required';end if;
 end if;
 confirmed_by:=previous_version.regional_confirmed_by;confirmed_at:=previous_version.regional_confirmed_at;
 if policy_values#>>'{regional,mode}'='inherit' then confirmed_by:=null;confirmed_at:=null;
 elsif requires_confirmation then confirmed_by:=(context->>'expectedActorId')::uuid;confirmed_at:=clock_timestamp();end if;
 if policy_values#>>'{regional,mode}'='override' and (policy_values->>'enabled')::boolean then
  perform 1 from public.shipping_carriers where code=policy_values#>>'{regional,policy,carrierCode}' for share nowait;
  if confirmed_by is null or not exists(select 1 from public.shipping_carriers where code=policy_values#>>'{regional,policy,carrierCode}' and is_active)
   or policy_values#>>'{regional,policy,carrierCode}' is distinct from origin.default_carrier then
   raise check_violation using message='shipping_charge_group_region_unavailable';end if;
 end if;
 if (policy_values->>'enabled')::boolean then
  perform 1 from private.goods_transaction_runtime where singleton and enabled for share nowait;
  if not found then raise check_violation using message='checkout_contract_upgrade_required';end if;
 end if;
 before_document:=private.shipping_charge_group_document(previous.id);
 if (policy_values->>'isDefault')::boolean and default_group.id is not null and default_group.id<>(context->>'groupId')::uuid then
  select * into default_version from private.shipping_charge_group_versions where id=default_group.version_id;
  perform private.write_shipping_charge_group_version(default_group.id,origin.id,jsonb_set(default_version.policy_values,'{isDefault}','false'),
   (context->>'expectedActorId')::uuid,(context->>'expectedSessionId')::uuid,(context->>'operationId')::uuid,
   default_version.regional_confirmed_by,default_version.regional_confirmed_at);
  default_result:=private.shipping_charge_group_document(default_group.id);
 end if;
 if previous.id is null or previous_version.policy_values is distinct from policy_values then
  perform private.write_shipping_charge_group_version((context->>'groupId')::uuid,origin.id,policy_values,
   (context->>'expectedActorId')::uuid,(context->>'expectedSessionId')::uuid,(context->>'operationId')::uuid,confirmed_by,confirmed_at);
 end if;
 receipt:=private.shipping_charge_group_receipt(context,'saved',private.shipping_charge_group_document((context->>'groupId')::uuid),default_result);
 insert into public.audit_log(id,actor_id,action,target,diff) values((context->>'operationId')::uuid,(context->>'expectedActorId')::uuid,
  'catalog.shipping_charge_group.saved','shipping_charge_groups:'||(context->>'groupId'),
  jsonb_build_object('context',context,'before',before_document,'after',receipt->'group','changedDefaultGroup',default_result,
   'regionalChanged',region_changed,'regionalConfirmed',requires_confirmation));
 perform private.record_shipping_charge_group_operation(context,request_hash,receipt);return receipt;
exception when lock_not_available then raise sqlstate 'PT409' using message='shipping_charge_group_retry';
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_shipping_collect_contract(p_origin_id uuid, p_expected_revision integer, p_status text, p_values jsonb, p_operation_id uuid, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();previous private.shipping_collect_contracts;request jsonb;receipt jsonb;version_id uuid;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='auth_context_changed';end if;
 perform private.require_actor_operator_capability(actor,'platform.manage',true);
 if p_origin_id is null or p_expected_revision is null or p_expected_revision<0 or p_operation_id is null
  or not private.shipping_collect_contract_input_valid(p_values,p_status) then raise invalid_parameter_value using message='invalid_collect_contract';end if;
 request:=jsonb_build_object('originId',p_origin_id,'expectedRevision',p_expected_revision,'status',p_status,'values',p_values);
 perform pg_advisory_xact_lock(hashtextextended('shipping-collect-operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.shipping.collect_contract.saved',request);if receipt is not null then return receipt;end if;
 perform 1 from public.fulfillment_origins where id=p_origin_id and is_active for update;
 if not found then raise no_data_found using message='fulfillment_origin_not_found';end if;
 select * into previous from private.shipping_collect_contracts where origin_id=p_origin_id for update;
 if coalesce(previous.revision,0)<>p_expected_revision then raise sqlstate 'PT409' using message='collect_contract_changed';end if;
 insert into private.shipping_collect_contract_versions(origin_id,revision,status,contract_values,created_by)
  values(p_origin_id,p_expected_revision+1,p_status,p_values,actor) returning id into version_id;
 insert into private.shipping_collect_contracts(origin_id,revision,version_id) values(p_origin_id,p_expected_revision+1,version_id)
  on conflict(origin_id) do update set revision=excluded.revision,version_id=excluded.version_id;
 receipt:=private.shipping_collect_contract_document(p_origin_id)||jsonb_build_object('operationId',p_operation_id);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.shipping.collect_contract.saved','fulfillment_origins:'||p_origin_id,
