CREATE OR REPLACE FUNCTION public.admin_save_store_settings(target_section text, target_values jsonb, expected_updated_at timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); previous public.store_settings; saved public.store_settings; normalized jsonb; allowed text[]; filled integer; category text; notice jsonb; body_value text;
begin
  perform private.require_operator_capability(case when target_section='inquiry_auto_replies' then 'store.manage' else 'seller.manage' end,target_section is distinct from 'inquiry_auto_replies');

  if actor is null or not public.has_operator_capability(case when target_section='inquiry_auto_replies' then 'store.manage' else 'seller.manage' end,target_section is distinct from 'inquiry_auto_replies') or not exists(select 1 from public.profiles where id=actor and private.has_operator_capability(id,case when target_section='inquiry_auto_replies' then 'store.manage' else 'seller.manage' end,target_section is distinct from 'inquiry_auto_replies')) then
    raise insufficient_privilege using message='admin_required';
  end if;
  if target_section='inquiry_auto_replies' then
    if jsonb_typeof(target_values) is distinct from 'object' then
      raise invalid_parameter_value using message='invalid_inquiry_auto_replies';
    end if;
    if not target_values ?& array['order','claim','good','account','etc']
      or (select count(*) from jsonb_object_keys(target_values))<>5 then
      raise invalid_parameter_value using message='invalid_inquiry_auto_replies';
    end if;
    normalized:='{}'::jsonb;
    for category,notice in select key,value from jsonb_each(target_values) loop
      if jsonb_typeof(notice) is distinct from 'object' then
        raise invalid_parameter_value using message='invalid_inquiry_auto_replies';
      end if;
      if jsonb_typeof(notice->'enabled') is distinct from 'boolean'
        or jsonb_typeof(notice->'body') is distinct from 'string'
        or (select count(*) from jsonb_object_keys(notice))<>2 then
        raise invalid_parameter_value using message='invalid_inquiry_auto_replies';
      end if;
      -- Match JavaScript trim while preserving newlines inside operator-authored text.
      body_value:=btrim(notice->>'body',E' \t\n\r\f\v'||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF');
      if length(body_value)>2000 or ((notice->>'enabled')::boolean and body_value='')
        or regexp_replace(body_value,E'[\t\n\r]','','g') ~ '[[:cntrl:]]' then
        raise invalid_parameter_value using message='invalid_inquiry_auto_reply_body';
      end if;
      normalized:=normalized||jsonb_build_object(category,jsonb_build_object('enabled',notice->'enabled','body',body_value));
    end loop;
    select * into previous from public.store_settings where singleton for update;
    if expected_updated_at is distinct from previous.updated_at then
      raise sqlstate 'PT409' using message='store_settings_conflict';
    end if;
    update public.store_settings set inquiry_auto_replies=normalized,
      updated_at=greatest(clock_timestamp(),previous.updated_at+interval '1 microsecond')
      where singleton returning * into saved;
    insert into public.audit_log(actor_id,action,target,diff)
      values(actor,'admin.store_settings.updated','store_settings:inquiry_auto_replies',
        jsonb_build_object('before',previous.inquiry_auto_replies,'after',normalized));
    return saved.updated_at;
  end if;
  if target_section not in ('business','bank_transfer') or target_section is null or jsonb_typeof(target_values) is distinct from 'object' then
    raise invalid_parameter_value using message='invalid_store_settings';
  end if;
  allowed:=case target_section when 'business' then array['companyName','representative','registrationNumber','mailOrderNumber','address','phone','email','hostingProvider'] else array['bank','accountNumber','holder'] end;
  if exists(select 1 from jsonb_each(target_values) where not(key=any(allowed)) or jsonb_typeof(value)<>'string') then
    raise invalid_parameter_value using message='invalid_store_settings';
  end if;
  select coalesce(jsonb_object_agg(key,btrim(value,E' \t\n\r\f\v')),'{}') into normalized from jsonb_each_text(target_values);
  if exists(select 1 from jsonb_each_text(normalized) where length(value)>500 or value ~ '[[:cntrl:]]')
    or (target_section='business' and coalesce(normalized->>'email','')<>'' and normalized->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then
    raise invalid_parameter_value using message='invalid_store_settings';
  end if;
  if target_section='bank_transfer' then
    select count(*) into filled from jsonb_each_text(normalized) where value<>'';
    if not normalized ?& allowed or filled not in (0,3) then raise invalid_parameter_value using message='incomplete_bank_account'; end if;
  end if;
  select * into previous from public.store_settings where singleton for update;
  if expected_updated_at is distinct from previous.updated_at then raise sqlstate 'PT409' using message='store_settings_conflict'; end if;
  update public.store_settings set
    business=case when target_section='business' then normalized else business end,
    bank_transfer=case when target_section='bank_transfer' then normalized else bank_transfer end,
    updated_at=greatest(clock_timestamp(),previous.updated_at+interval '1 microsecond') where singleton returning * into saved;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.store_settings.updated','store_settings:'||target_section,
    jsonb_build_object('before',case target_section when 'business' then previous.business else previous.bank_transfer end,
      'after',normalized));
  return saved.updated_at;
end $function$

CREATE OR REPLACE FUNCTION public.admin_seal_shipping_charge_group_operation(p_context jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare context jsonb;receipt jsonb;begin
 -- Reject missing authority before parsing caller-controlled operation JSON.
 if (select auth.uid()) is null then raise invalid_authorization_specification using message='auth_required';end if;
 if not public.has_operator_capability('catalog.manage',false) then
  raise insufficient_privilege using message='operator_capability_required';
 end if;
 context:=private.shipping_charge_group_context(p_context);
 if context is distinct from p_context then raise invalid_parameter_value using message='invalid_shipping_charge_group_operation';end if;
 perform private.require_shipping_charge_group_identity((context->>'expectedActorId')::uuid,(context->>'expectedSessionId')::uuid);
 perform pg_advisory_xact_lock(hashtextextended('shipping-charge-group-operation:'||(context->>'operationId'),0));
 receipt:=private.shipping_charge_group_prior(context);if receipt is not null then return receipt;end if;
 receipt:=private.shipping_charge_group_receipt(context,'sealed');perform private.record_shipping_charge_group_operation(context,null,receipt);
 insert into public.audit_log(id,actor_id,action,target,diff) values((context->>'operationId')::uuid,(context->>'expectedActorId')::uuid,
  'catalog.shipping_charge_group.operation_sealed','shipping_charge_groups:'||coalesce(context->>'groupId','clear'),jsonb_build_object('context',context));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_seal_shipping_collect_operation(p_order_id uuid, p_shipment_id uuid, p_operation_id uuid, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();previous public.audit_log;request jsonb;receipt jsonb;
begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='auth_context_changed';end if;
 perform private.require_actor_operator_capability(actor,'sales.manage');
 if p_order_id is null or p_shipment_id is null or p_operation_id is null then raise invalid_parameter_value using message='invalid_shipping_collect_operation';end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-collect-operation:'||p_operation_id::text,0));
 request:=jsonb_build_object('orderId',p_order_id,'shipmentId',p_shipment_id);
 select * into previous from public.audit_log where id=p_operation_id;
 if found then
  if previous.actor_id is distinct from actor or previous.diff#>>'{request,orderId}' is distinct from p_order_id::text or previous.diff#>>'{request,shipmentId}' is distinct from p_shipment_id::text then raise unique_violation using message='operation_conflict';end if;
  if previous.action='admin.shipping.collect_recorded' then return jsonb_build_object('state','recorded','receipt',previous.diff->'result');end if;
  if previous.action='admin.shipping.collect_abandoned' then return previous.diff->'result';end if;
  raise unique_violation using message='operation_conflict';
 end if;
 if not exists(select 1 from private.shipping_collect_obligations where shipment_id=p_shipment_id and order_id=p_order_id) then raise no_data_found using message='shipping_collect_not_found';end if;
 receipt:=jsonb_build_object('state','sealed','operationId',p_operation_id,'orderId',p_order_id,'shipmentId',p_shipment_id);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.shipping.collect_abandoned','order:'||p_order_id::text,jsonb_build_object('request',request,'result',receipt));
 return receipt;
end $function$

