CREATE OR REPLACE FUNCTION public.admin_search_coupon_categories(p_query text DEFAULT ''::text, p_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
