CREATE OR REPLACE FUNCTION public.admin_select_review_event_entries(p_id uuid, p_expected_revision integer, p_operation_id uuid, p_entries jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); event private.review_events%rowtype; request jsonb; receipt jsonb; item jsonb; candidate private.review_event_entries%rowtype;
 review public.reviews%rowtype; ids uuid[]:='{}'; item_id uuid; expected_time timestamptz; before_ids jsonb;
begin
 perform private.require_actor_operator_capability(actor,'cs.manage',false);
 if p_id is null or p_expected_revision is null or p_operation_id is null or jsonb_typeof(p_entries) is distinct from 'array' or jsonb_array_length(p_entries)>1000
  or char_length(btrim(coalesce(p_reason,''))) not between 2 and 500 then raise invalid_parameter_value using message='invalid_review_event_selection';end if;
 for item in select value from jsonb_array_elements(p_entries) loop
  if jsonb_typeof(item) is distinct from 'object' or (select count(*) from jsonb_object_keys(item))<>3 or not item ?& array['id','reviewUpdatedAt','reviewFingerprint']
   or jsonb_typeof(item->'id') is distinct from 'string' or jsonb_typeof(item->'reviewUpdatedAt') is distinct from 'string'
   or jsonb_typeof(item->'reviewFingerprint') is distinct from 'string' or item->>'reviewFingerprint' !~ '^[0-9a-f]{32}$' then raise invalid_parameter_value using message='invalid_review_event_selection';end if;
  begin item_id:=(item->>'id')::uuid;expected_time:=(item->>'reviewUpdatedAt')::timestamptz;exception when others then raise invalid_parameter_value using message='invalid_review_event_selection';end;
  if item_id=any(ids) then raise invalid_parameter_value using message='invalid_review_event_selection';end if;
  ids:=array_append(ids,item_id);
 end loop;
 request:=jsonb_build_object('id',p_id,'revision',p_expected_revision,'entries',p_entries,'reason',btrim(p_reason));
 perform pg_advisory_xact_lock(hashtextextended('review-event:operation:'||p_operation_id::text,0));
 receipt:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.review_event.selected',request);if receipt is not null then return receipt;end if;
 select * into event from private.review_events where id=p_id for update;
 if not found or event.revision<>p_expected_revision then raise sqlstate 'PT409' using message='review_event_changed';end if;
 if event.archived_at is not null or event.announced_at is not null or (clock_timestamp() at time zone 'Asia/Seoul')::date<=event.ends_on then raise check_violation using message='review_event_selection_closed';end if;
 -- Review deletion/status writers lock the review before its entry FK or award.
 perform 1 from public.reviews r join private.review_event_entries entry on entry.review_id=r.id where entry.id=any(ids) order by r.id for share of r;
 for item in select value from jsonb_array_elements(p_entries) order by value->>'id' loop
  select * into candidate from private.review_event_entries where id=(item->>'id')::uuid and event_id=p_id for update;
  if not found or private.review_event_entry_problem(candidate) is not null then raise check_violation using message='review_event_entry_ineligible';end if;
  select * into review from public.reviews where id=candidate.review_id;
  if review.updated_at is distinct from (item->>'reviewUpdatedAt')::timestamptz or private.review_event_review_fingerprint(review) is distinct from item->>'reviewFingerprint'
  then raise sqlstate 'PT409' using message='review_event_review_changed';end if;
 end loop;
 if (select count(*)<>count(distinct user_id) from private.review_event_entries where id=any(ids)) then raise check_violation using message='review_event_customer_once';end if;
 select coalesce(jsonb_agg(id order by id),'[]'::jsonb) into before_ids from private.review_event_entries where event_id=p_id and selected;
 update private.review_event_entries set selected=false,selected_review_updated_at=null,selected_review_fingerprint=null,selected_at=null,selected_by=null,selection_reason=null where event_id=p_id and selected;
 update private.review_event_entries entry set selected=true,selected_review_updated_at=current_review.updated_at,selected_review_fingerprint=private.review_event_review_fingerprint(current_review),selected_at=clock_timestamp(),selected_by=actor,selection_reason=btrim(p_reason)
 from public.reviews current_review where entry.id=any(ids) and current_review.id=entry.review_id;
 update private.review_events set revision=revision+1,updated_at=clock_timestamp() where id=p_id;
 receipt:=private.review_event_document(p_id);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.review_event.selected','review_event:'||p_id,jsonb_build_object('request',request,'result',receipt,'before',before_ids));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.admin_select_shipment_delivery_method(p_shipment_id uuid, p_method text, p_policy_id uuid, p_customer_request_reference text, p_fee_consent_reference text, p_fee_unchanged boolean, p_expected_updated_at timestamp with time zone, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); shipment public.order_shipments; purchase public.orders; policy private.fulfillment_delivery_policies;
  operation private.shipment_delivery_operations; evidence jsonb; fingerprint bytea; snapshot jsonb; instant timestamptz:=clock_timestamp();
begin
  perform private.require_operator_capability('sales.manage',false);

  if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff_required'; end if;
  if p_method is null or p_method not in ('parcel','quick','pickup','direct','freight') or p_operation_id is null or p_fee_unchanged is distinct from true
    or length(coalesce(btrim(p_customer_request_reference),'')) not between 1 and 2000
    or length(coalesce(btrim(p_fee_consent_reference),'')) not between 1 and 2000
    or (p_method='parcel' and p_policy_id is not null) or (p_method<>'parcel' and p_policy_id is null) then
    raise invalid_parameter_value using message='invalid_delivery_selection'; end if;
  select purchase_row.* into purchase from public.orders purchase_row join public.order_shipments shipment_row on shipment_row.order_id=purchase_row.id
    where shipment_row.id=p_shipment_id for update of purchase_row;
  if not found then raise no_data_found using message='shipment_not_found'; end if;
  select * into shipment from public.order_shipments where id=p_shipment_id for update;
  fingerprint:=extensions.digest(jsonb_build_object('actor',actor,'method',p_method,'policyId',p_policy_id,
    'request',btrim(p_customer_request_reference),'consent',btrim(p_fee_consent_reference),'expectedAt',p_expected_updated_at)::text,'sha256');
  select * into operation from private.shipment_delivery_operations where id=p_operation_id;
  if found then
    if operation.shipment_id<>shipment.id or operation.kind<>'method_selected' or operation.actor_id is distinct from actor
      or operation.request_digest is distinct from fingerprint then raise sqlstate 'PT409' using message='delivery_operation_conflict'; end if;
    return jsonb_build_object('ok',true,'replayed',true,'shipmentId',shipment.id);
  end if;
  if p_expected_updated_at is null or shipment.updated_at<>p_expected_updated_at then raise sqlstate 'PT409' using message='shipment_delivery_changed'; end if;
  if shipment.status<>'ready' or shipment.exported_at is not null or shipment.carrier is not null or shipment.tracking_number is not null
    or purchase.status not in ('paid','confirmed','shipping') then raise check_violation using message='delivery_method_selection_unavailable'; end if;
  perform private.assert_order_dispatch_allowed(purchase.id);
  if p_method<>'parcel' then
    -- All policy writers lock the origin first; only SHARE is needed by selection.
    perform id from public.fulfillment_origins where id=shipment.origin_id and is_active for share;
    if not found then raise check_violation using message='delivery_policy_unavailable'; end if;
    select * into policy from private.fulfillment_delivery_policies where id=p_policy_id and origin_id=shipment.origin_id and method=p_method for share;
    if not found or policy.state<>'active' or not private.valid_delivery_policy_terms(policy.terms,true) then
      raise check_violation using message='delivery_policy_unavailable'; end if;
    snapshot:=(policy.terms-'approvalReference')||jsonb_build_object('version',1,'policyId',policy.id,'revision',policy.revision,
      'feeRule','order_fee_unchanged','confirmationRule','recipient_code');
  end if;
  evidence:=jsonb_build_object('fromMethod',shipment.delivery_method,'toMethod',p_method,'policyId',p_policy_id,
    'policyRevision',policy.revision,'customerRequestReference',btrim(p_customer_request_reference),'feeConsentReference',btrim(p_fee_consent_reference),
    'shippingFee',shipment.shipping_fee,'orderTotal',purchase.total,'feeRule','order_fee_unchanged');
  insert into private.shipment_delivery_operations(id,shipment_id,kind,actor_id,request_digest,evidence)
    values(p_operation_id,shipment.id,'method_selected',actor,fingerprint,evidence);
  update public.order_shipments set delivery_method=p_method,delivery_policy_id=p_policy_id,delivery_method_snapshot=snapshot,
    delivery_selection_id=p_operation_id,delivery_event_id=null,updated_at=instant where id=shipment.id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.shipment.delivery_method_selected','order:'||purchase.id,
    jsonb_build_object('shipmentId',shipment.id,'operationId',p_operation_id,'from',shipment.delivery_method,'to',p_method,'shippingFee',shipment.shipping_fee));
  return jsonb_build_object('ok',true,'replayed',false,'shipmentId',shipment.id);
end $function$

CREATE OR REPLACE FUNCTION public.admin_seller_claim_intake_context(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.orders; result jsonb; observed_at timestamptz := clock_timestamp();
begin
  if not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='operator_capability_required'; end if;

  perform (select auth.uid());
  select * into target from public.orders where id = p_order_id;
  if not found then return null; end if;
  select jsonb_build_object(
    'orderId', target.id, 'orderNumber', target.order_number, 'orderStatus', target.status, 'orderTotal', target.total,
    'buyerName', profile.nickname, 'createdAt', target.created_at, 'deliveredAt', target.delivered_at,
    'address', target.address, 'observedAt', observed_at,
    'cancelBlockedReason',private.seller_cancel_intake_block(target.id),
    'digitalExchangeBlocked',private.order_has_digital_items(target.id),
    'blockedReasons', jsonb_build_object(
      'change_of_mind', private.seller_claim_intake_block(target.id, 'change_of_mind', observed_at),
      'defect', private.seller_claim_intake_block(target.id, 'defect', observed_at)),
    'activeClaim', (select jsonb_build_object('id', c.id, 'claimType', c.claim_type, 'stage', c.stage)
      from public.order_cancellation_requests c where c.order_id = target.id and c.status in ('requested', 'processing', 'needs_review') order by c.requested_at desc limit 1),
    'collections', private.seller_claim_collection_targets(target.id),
    'carriers', coalesce((select jsonb_agg(jsonb_build_object('code', c.code, 'label', c.label, 'active', c.is_active, 'trackingUrlTemplate', c.tracking_url_template) order by c.sort_order, c.code)
      from public.shipping_carriers c where c.is_active), '[]'),
    'inquiries', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'reference', i.reference, 'title', i.title, 'createdAt', i.created_at) order by i.created_at desc)
      from (select * from public.inquiries where user_id = target.user_id and order_id = target.id order by created_at desc, id limit 50) i), '[]')
  ) into result from public.profiles profile where profile.id = target.user_id;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_send_inquiry_chat_message(p_inquiry uuid, p_body text, p_files uuid[], p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();body text:=btrim(coalesce(p_body,''));files uuid[]:=coalesce(p_files,'{}');thread public.inquiries;receipt private.inquiry_chat_send_receipts;request jsonb;message uuid;begin
 perform private.require_operator_capability('cs.manage',false);
 if p_operation is null or p_inquiry is null or char_length(body)>2000 or(body='' and cardinality(files)=0) or cardinality(files)>3
  or array_position(files,null) is not null or cardinality(files)<>(select count(distinct x) from unnest(files)x) then raise invalid_parameter_value;end if;
 request:=jsonb_build_object('inquiryId',p_inquiry,'body',body,'fileIds',files);
 perform pg_advisory_xact_lock(hashtextextended('inquiry-send:'||p_operation::text,0));
 select * into receipt from private.inquiry_chat_send_receipts where operation_id=p_operation;
 if found then
  if receipt.actor_id is distinct from actor or receipt.request is distinct from request then raise sqlstate 'PT409';end if;
  message:=receipt.message_id;
 else
  select * into thread from public.inquiries where id=p_inquiry for update;
  if not found then raise no_data_found using message='inquiry_not_found';end if;
  if thread.status='closed' then raise check_violation using message='inquiry_closed';end if;
  perform id from private.inquiry_chat_files where id=any(files) order by id for share;
  if(select count(*) from private.inquiry_chat_files where id=any(files) and state='verified' and(in_library or actor_id=actor and expires_at>clock_timestamp()))<>cardinality(files) then raise check_violation using message='inquiry_file_unavailable';end if;
  insert into public.inquiry_messages(inquiry_id,author,author_id,body,file_ids) values(p_inquiry,'staff',actor,body,files) returning id into message;
  update public.inquiries set status='answered',handled_by=actor,answered_at=coalesce(answered_at,now()),last_message_at=now() where id=p_inquiry;
  insert into public.notifications(user_id,type,title,body,link_path,source_type,source_id,dedupe_key)
  values(thread.user_id,'inquiry_answered','문의에 답변이 등록됐어요',left('문의 #'||thread.reference::text||' — '||thread.title,500),'/my/inquiries/'||p_inquiry::text,'inquiry',p_inquiry::text,'inquiry:answered:'||message::text) on conflict(user_id,dedupe_key) do nothing;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.inquiry.answered','inquiries:'||p_inquiry,jsonb_build_object('messageId',message,'previousStatus',thread.status,'attachmentCount',cardinality(files),'operationId',p_operation));
  insert into private.inquiry_chat_send_receipts(operation_id,actor_id,inquiry_id,request,message_id) values(p_operation,actor,p_inquiry,request,message);
 end if;
 return(select jsonb_build_object('messageId',message,'recipientId',i.user_id,'recipientEmail',p.email,'reference',i.reference,'title',i.title,'operationId',p_operation) from public.inquiries i join public.profiles p on p.id=i.user_id where i.id=p_inquiry);
end $function$

CREATE OR REPLACE FUNCTION public.admin_send_marketing_test(p_campaign_id uuid, p_expected_revision integer, p_operation_id uuid, p_expected_actor uuid, p_expected_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; campaign private.marketing_campaigns; request jsonb; replay jsonb; result jsonb; notification uuid; moment timestamptz;
begin
 actor:=private.require_operator_capability('marketing.manage',false);
 if p_expected_actor is distinct from actor or p_expected_session is null or auth.jwt()->>'session_id' is distinct from p_expected_session::text
  or not exists(select 1 from auth.sessions where id=p_expected_session and user_id=actor and (not_after is null or not_after>clock_timestamp())) then raise insufficient_privilege using message='marketing_test_auth_changed';end if;
 if p_campaign_id is null or p_expected_revision is null or p_expected_revision<1 or p_operation_id is null then raise invalid_parameter_value;end if;
 request:=jsonb_build_object('campaignId',p_campaign_id,'revision',p_expected_revision,'sessionId',p_expected_session);
 perform pg_advisory_xact_lock(hashtextextended('marketing-test:'||p_operation_id::text,0));
 replay:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.marketing.test_sent',request);if replay is not null then return replay;end if;
 select * into campaign from private.marketing_campaigns where id=p_campaign_id for share;
 if not found or campaign.revision<>p_expected_revision or campaign.archived_at is not null then raise sqlstate 'PT409' using message='marketing_campaign_changed';end if;
 if not private.marketing_content_available(campaign.content) then raise check_violation using message='marketing_product_unavailable';end if;
 moment:=clock_timestamp();
 insert into public.notifications(user_id,type,title,body,link_path,source_type,source_id,dedupe_key)
 values(actor,'marketing_message','[테스트] '||left(campaign.content->>'title',110),campaign.content->>'body','/notifications/marketing-test/'||p_operation_id,
  'marketing_test',p_operation_id::text,'marketing-test:'||p_operation_id) returning id into notification;
 insert into private.marketing_test_receipts(id,actor_id,campaign_id,campaign_revision,session_id,content,notification_id,registered_at)
  values(p_operation_id,actor,campaign.id,campaign.revision,p_expected_session,campaign.content,notification,moment);
 result:=jsonb_build_object('receiptId',p_operation_id,'notificationId',notification,'registeredAt',moment,'linkPath','/notifications/marketing-test/'||p_operation_id);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.marketing.test_sent','marketing_campaign:'||p_campaign_id,jsonb_build_object('request',request,'result',result));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_send_notification(target_operation_id uuid, target_scope text, target_ip_id text, target_title text, target_body text)
 RETURNS TABLE(recipient_count bigint, sent_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_scope text := pg_catalog.btrim(target_scope, E' \t\n\r\f\v');
  normalized_ip_id text := nullif(
    pg_catalog.btrim(target_ip_id, E' \t\n\r\f\v'),
    ''
  );
  normalized_title text := pg_catalog.btrim(target_title, E' \t\n\r\f\v');
  normalized_body text := pg_catalog.btrim(target_body, E' \t\n\r\f\v');
  request_payload jsonb;
  requested_target text;
  selected_ip_title text;
  actual_recipient_count bigint;
  sent_timestamp timestamptz;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  existing_sent_at timestamptz;
begin
  perform private.require_operator_capability('marketing.manage',false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.has_operator_capability('marketing.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if normalized_scope is null
    or normalized_scope not in ('all', 'ip_followers')
  then
    raise exception 'invalid_notification_scope' using errcode = '22023';
  end if;

  if normalized_scope = 'all' then
    if normalized_ip_id is not null then
      raise exception 'invalid_notification_target' using errcode = '22023';
    end if;
    requested_target := 'notifications:all';
  else
    if normalized_ip_id is null then
      raise exception 'invalid_notification_target' using errcode = '22023';
    end if;
    requested_target := 'notifications:ip_followers:' || normalized_ip_id;
  end if;

  if normalized_title is null
    or pg_catalog.char_length(normalized_title) < 1
    or pg_catalog.char_length(normalized_title) > 120
  then
    raise exception 'invalid_notification_title' using errcode = '22023';
  end if;

  if normalized_body is null
    or pg_catalog.char_length(normalized_body) < 1
    or pg_catalog.char_length(normalized_body) > 500
  then
    raise exception 'invalid_notification_body' using errcode = '22023';
  end if;

  request_payload := pg_catalog.jsonb_build_object(
    'scope', normalized_scope,
    'ip_id', normalized_ip_id,
    'title', normalized_title,
    'body', normalized_body
  );

  -- A lost-response retry must observe the first commit before deciding whether
  -- the operation is an idempotent replay or a conflicting reuse.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_notification_operation:' || target_operation_id::text,
      0
    )
  );

  select
    audit.actor_id,
    audit.action,
    audit.target,
    audit.diff,
    audit.created_at
  into
    existing_actor_id,
    existing_action,
    existing_target,
    existing_diff,
    existing_sent_at
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.notification.sent'
      and existing_target = requested_target
      and existing_diff -> 'request' = request_payload
    then
      return query
        select
          (existing_diff #>> '{result,recipient_count}')::bigint,
          existing_sent_at;
      return;
    end if;

    raise exception 'operation_conflict' using errcode = '23505';
  end if;

  if normalized_scope = 'ip_followers' then
    select ip.title
      into selected_ip_title
    from public.ips as ip
    where ip.id = normalized_ip_id
    for key share;

    if not found then
      raise exception 'ip_not_found' using errcode = 'P0002';
    end if;
  end if;

  if normalized_scope = 'all' then
    insert into public.notifications (
      user_id,
      type,
      title,
      body,
      link_path,
      source_type,
      source_id,
      dedupe_key
    )
    select
      profile.id,
      'announcement',
      normalized_title,
      normalized_body,
      '/notifications',
      'admin_announcement',
      target_operation_id::text,
      'announcement:' || target_operation_id::text
    from public.profiles as profile;
  else
    insert into public.notifications (
      user_id,
      type,
      title,
      body,
      link_path,
      source_type,
      source_id,
      dedupe_key
    )
    select
      follow.user_id,
      'announcement',
      normalized_title,
      normalized_body,
      '/notifications',
      'admin_announcement',
      target_operation_id::text,
      'announcement:' || target_operation_id::text
    from public.ip_follows as follow
    where follow.ip_id = normalized_ip_id;
  end if;

  get diagnostics actual_recipient_count = row_count;

  if actual_recipient_count = 0 then
    raise exception 'notification_no_recipients' using errcode = '22023';
  end if;

  sent_timestamp := pg_catalog.clock_timestamp();

  insert into public.audit_log (
    id,
    actor_id,
    action,
    target,
    diff,
    created_at
  )
  values (
    target_operation_id,
    actor_id,
    'admin.notification.sent',
    requested_target,
    pg_catalog.jsonb_build_object(
      'request', request_payload,
      'result', pg_catalog.jsonb_build_object(
        'ip_title', selected_ip_title,
        'link_path', '/notifications',
        'recipient_count', actual_recipient_count
      )
    ),
    sent_timestamp
  );

  return query
    select actual_recipient_count, sent_timestamp;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_category_activation(target_operation_id uuid, target_customer_enabled boolean, target_erp_enabled boolean, target_evidence jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := (select auth.uid());
  customer jsonb := coalesce(target_evidence->'customer', '{}'::jsonb);
  erp jsonb := coalesce(target_evidence->'erp', '{}'::jsonb);
  existing_actor_id uuid;
  existing_action text;
  existing_diff jsonb;
  request_payload jsonb;
begin
  perform private.require_operator_capability('platform.manage',false);

  if v_actor_id is null or not public.has_operator_capability('platform.manage',false) then raise insufficient_privilege using message = 'forbidden'; end if;
  if target_operation_id is null or target_evidence is null then raise invalid_parameter_value using message = 'invalid_category_activation'; end if;
  request_payload := jsonb_build_object(
    'customer_enabled', target_customer_enabled,
    'erp_enabled', target_erp_enabled,
    'evidence', target_evidence
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || target_operation_id::text, 0));
  select audit.actor_id, audit.action, audit.diff into existing_actor_id, existing_action, existing_diff
  from public.audit_log as audit where audit.id = target_operation_id;
  if found then
    if existing_actor_id = v_actor_id and existing_action = 'admin.catalog.category.activation_updated' and existing_diff -> 'request' = request_payload then
      return true;
    end if;
    raise unique_violation using message = 'operation_conflict';
  end if;
  if target_customer_enabled and (
    btrim(coalesce(customer->>'source', '')) = '' or btrim(coalesce(customer->>'reference', '')) = ''
    or btrim(coalesce(customer->>'verifiedAt', '')) = '' or not exists(select 1 from public.catalog_categories where archived_at is null)
  ) then raise check_violation using message = 'category_activation_unready'; end if;
  if target_erp_enabled and (
    btrim(coalesce(erp->>'source', '')) = '' or btrim(coalesce(erp->>'reference', '')) = ''
    or btrim(coalesce(erp->>'verifiedAt', '')) = '' or not exists(
      select 1 from public.catalog_categories as category
      where category.archived_at is null
        and not exists (select 1 from public.catalog_categories as child where child.parent_id = category.id and child.archived_at is null)
    ) or exists(
      select 1
      from public.catalog_categories as category
      left join public.catalog_category_erp_mappings as mapping on mapping.category_id = category.id
      where category.archived_at is null
        and not exists (select 1 from public.catalog_categories as child where child.parent_id = category.id and child.archived_at is null)
        and mapping.category_id is null
    )
  ) then raise check_violation using message = 'category_activation_unready'; end if;
  update public.category_activation_control
  set customer_enabled = target_customer_enabled, erp_enabled = target_erp_enabled, evidence = target_evidence,
      actor_id = v_actor_id, updated_at = pg_catalog.now()
  where id = 'catalog';
  insert into public.audit_log(id, actor_id, action, target, diff)
  values (target_operation_id, v_actor_id, 'admin.catalog.category.activation_updated', 'category_activation_control:catalog',
    jsonb_build_object('request', request_payload));
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_category_display_node_image(p_node_id uuid, p_image_path text, p_expected_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;previous private.category_display_nodes;current_revision bigint;receipt public.audit_log;request jsonb;result jsonb;
begin
 actor:=private.require_operator_capability('store.manage',false);
 if p_node_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or p_image_path is not null and p_image_path !~ '^public-media/catalog/curation/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|png|webp)$'
 then raise invalid_parameter_value using message='invalid_display_node_image';end if;
 request:=jsonb_build_object('nodeId',p_node_id,'imagePath',p_image_path,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('category-display-operation:'||p_operation_id,0));
 select * into receipt from public.audit_log where id=p_operation_id;
 if found then
  if receipt.actor_id=actor and receipt.action='admin.category_display.image_changed' and receipt.target='category-display:'||p_node_id and receipt.diff->'request'=request then return receipt.diff->'result';end if;
  raise unique_violation using message='operation_conflict';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('catalog_category_tree',0));
 select revision into current_revision from private.category_display_tree_control where singleton for update;
 if current_revision<>p_expected_revision then raise sqlstate 'PT409' using message='category_display_tree_conflict';end if;
 select * into previous from private.category_display_nodes where id=p_node_id for update;
 if not found then raise no_data_found using message='display_node_missing';end if;
 if p_image_path is not null and p_image_path is distinct from previous.image_path then
  update public.admin_artwork_upload_claims as claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
  where claim.actor_id=actor and claim.path=substr(p_image_path,length('public-media/')+1) and claim.kind='curation'
   and claim.status='verified' and claim.verified_at is not null and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
  if not found then raise check_violation using message='unverified_artwork';end if;
 end if;
 update private.category_display_nodes set image_path=p_image_path,updated_at=clock_timestamp() where id=p_node_id;
 update private.category_display_tree_control set revision=current_revision+1 where singleton;
 result:=jsonb_build_object('nodeId',p_node_id,'directory',public.admin_list_category_displays());
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.category_display.image_changed','category-display:'||p_node_id,
  jsonb_build_object('request',request,'before',jsonb_build_object('imagePath',previous.image_path),'result',result));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_category_erp_mapping(target_operation_id uuid, target_category_id uuid, target_erp_code text, target_erp_name text, target_source text, target_verified_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  existing_actor_id uuid;
  existing_action text;
  existing_diff jsonb;
  request_payload jsonb;
begin
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null or not public.has_operator_capability('platform.manage',false) then raise insufficient_privilege using message = 'forbidden'; end if;
  if target_operation_id is null or target_category_id is null or btrim(coalesce(target_erp_code, '')) = ''
     or btrim(coalesce(target_erp_name, '')) = '' or btrim(coalesce(target_source, '')) = '' or target_verified_at is null then
    raise invalid_parameter_value using message = 'invalid_category_erp_mapping';
  end if;
  request_payload := jsonb_build_object(
    'category_id', target_category_id,
    'erp_code', btrim(target_erp_code),
    'erp_name', btrim(target_erp_name),
    'source', btrim(target_source),
    'verified_at', target_verified_at
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || target_operation_id::text, 0));
  select audit.actor_id, audit.action, audit.diff into existing_actor_id, existing_action, existing_diff
  from public.audit_log as audit where audit.id = target_operation_id;
  if found then
    if existing_actor_id = actor_id and existing_action = 'admin.catalog.category.erp_mapping_updated' and existing_diff -> 'request' = request_payload then
      return true;
    end if;
    raise unique_violation using message = 'operation_conflict';
  end if;
  perform private.lock_catalog_category_tree();
  if not exists (select 1 from public.catalog_categories where id = target_category_id and archived_at is null) then raise no_data_found using message = 'category_not_found'; end if;
  if exists (select 1 from public.catalog_category_erp_mappings where erp_code = btrim(target_erp_code) and category_id <> target_category_id) then raise unique_violation using message = 'category_erp_code_taken'; end if;
  insert into public.catalog_category_erp_mappings(category_id, erp_code, erp_name, source, verified_at, verified_by)
  values (target_category_id, btrim(target_erp_code), btrim(target_erp_name), btrim(target_source), target_verified_at, actor_id)
  on conflict(category_id) do update set erp_code = excluded.erp_code, erp_name = excluded.erp_name, source = excluded.source,
    verified_at = excluded.verified_at, verified_by = excluded.verified_by, updated_at = pg_catalog.now();
  insert into public.audit_log(id, actor_id, action, target, diff)
  values (target_operation_id, actor_id, 'admin.catalog.category.erp_mapping_updated', 'catalog_categories:' || target_category_id::text,
    jsonb_build_object('request', request_payload));
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_coupon_status(p_code text, p_expected_revision integer, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); existing public.coupons; saved public.coupons;
begin
  perform private.require_operator_capability('marketing.manage',false);

 if actor is null or not public.has_operator_capability('marketing.manage',false) then raise insufficient_privilege using message='staff_required';end if;
 if p_status is null or p_status not in('active','archived') or p_expected_revision is null then raise invalid_parameter_value using message='invalid_coupon_status';end if;
 select * into existing from public.coupons where code=p_code for update;
 if not found then raise no_data_found using message='coupon_not_found';end if;
 if existing.terms_revision<>p_expected_revision then raise exception using errcode='PT409',message='coupon_terms_changed';end if;
 if existing.status=p_status then return jsonb_build_object('code',existing.code,'changed',false);end if;
 update public.coupons set status=p_status where code=p_code returning * into saved;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'commerce.coupon.status_changed','coupons:'||p_code,
 jsonb_build_object('before',existing.status,'after',saved.status,'previousRevision',existing.terms_revision,'revision',saved.terms_revision));
 return jsonb_build_object('code',saved.code,'changed',true,'revision',saved.terms_revision);
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_customer_segment_favorite(p_segment_id uuid, p_favorite boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;
begin
 actor:=private.require_operator_capability('marketing.manage',false);
 if p_segment_id is null or p_favorite is null then raise invalid_parameter_value using message='invalid_customer_segment_favorite';end if;
 perform 1 from private.customer_segments where id=p_segment_id and archived_at is null for share;
 if not found then raise no_data_found using message='customer_segment_not_found';end if;
 if p_favorite then
  if exists(select 1 from private.customer_segment_favorites where actor_id=actor and segment_id=p_segment_id) then return true;end if;
  if (select count(*) from private.customer_segment_favorites where actor_id=actor)>=3 then raise check_violation using message='customer_segment_favorite_limit';end if;
  insert into private.customer_segment_favorites(actor_id,segment_id) values(actor,p_segment_id);
 else delete from private.customer_segment_favorites where actor_id=actor and segment_id=p_segment_id;end if;
 return p_favorite;
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_erp_category_mapping(p_erp_category text, p_category_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_erp_category text := private.erp_item_text(p_erp_category, true);
  v_before uuid;
  v_archived_at timestamptz;
  v_changed boolean := false;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if v_actor is null or not public.has_operator_capability('catalog.manage',false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if v_erp_category is null
     or pg_catalog.length(v_erp_category) > 200
     or v_erp_category ~ '[\u0001-\u001f\u007f-\u009f]' then
    raise invalid_parameter_value using message = 'invalid_erp_category';
  end if;

  -- 카테고리 보관·이동과 같은 트리 잠금을 잡아 말단 검사와 연결 저장 사이에 트리가 바뀌지 않게 한다.
  perform private.lock_catalog_category_tree();

  select mapping.category_id into v_before
  from public.erp_category_mappings as mapping
  where mapping.erp_category = v_erp_category
  for update;

  if p_category_id is null then
    if v_before is not null then
      delete from public.erp_category_mappings as mapping
      where mapping.erp_category = v_erp_category;
      v_changed := true;
    end if;
  else
    select category.archived_at into v_archived_at
    from public.catalog_categories as category
    where category.id = p_category_id
    for share;
    if not found then
      raise no_data_found using message = 'category_not_found';
    end if;
    if v_archived_at is not null then
      raise check_violation using message = 'category_archived';
    end if;
    if exists (
      select 1
      from public.catalog_categories as child
      where child.parent_id = p_category_id
        and child.archived_at is null
    ) then
      raise check_violation using message = 'category_not_leaf';
    end if;
    if v_before is distinct from p_category_id then
      insert into public.erp_category_mappings (erp_category, category_id, updated_by, updated_at)
      values (v_erp_category, p_category_id, v_actor, pg_catalog.now())
      on conflict (erp_category) do update
        set category_id = excluded.category_id,
            updated_by = excluded.updated_by,
            updated_at = excluded.updated_at;
      v_changed := true;
    end if;
  end if;

  if v_changed then
    insert into public.audit_log (actor_id, action, target, diff)
    values (v_actor, 'admin.erp_items.category_mapping_updated', 'erp_category_mappings:' || v_erp_category,
      pg_catalog.jsonb_build_object('erp_category', v_erp_category, 'before', v_before, 'after', p_category_id));
  end if;

  return pg_catalog.jsonb_build_object(
    'erp_category', v_erp_category,
    'category_id', p_category_id,
    'changed', v_changed);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_erp_category_mappings(p_entries jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_entry jsonb;
  v_index integer;
  v_raw text;
  v_erp_category text;
  v_seen text[] := array[]::text[];
  v_result jsonb;
  v_changed integer := 0;
  v_unchanged integer := 0;
  v_rejected jsonb := '[]'::jsonb;
begin
  perform private.require_operator_capability('catalog.manage', false);

  if v_actor is null or not public.has_operator_capability('catalog.manage', false) then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if p_entries is null
     or pg_catalog.jsonb_typeof(p_entries) <> 'array'
     or pg_catalog.jsonb_array_length(p_entries) not between 1 and 500 then
    raise invalid_parameter_value using message = 'invalid_erp_category_mappings';
  end if;

  -- 카테고리 보관·이동과 같은 트리 잠금을 처음에 잡아 묶음 전체를 같은 트리로 검사한다.
  -- 단건 RPC가 다시 잡아도 같은 트랜잭션이라 기다리지 않는다.
  perform private.lock_catalog_category_tree();

  for v_entry, v_index in
    select item.value, item.ordinality::integer - 1
    from pg_catalog.jsonb_array_elements(p_entries) with ordinality as item(value, ordinality)
  loop
    v_raw := case
      when pg_catalog.jsonb_typeof(v_entry) = 'object' and pg_catalog.jsonb_typeof(v_entry -> 'erp_category') = 'string'
        then v_entry ->> 'erp_category'
    end;
    v_erp_category := private.erp_item_text(v_raw, true);

    if v_erp_category is null then
      v_rejected := v_rejected || pg_catalog.jsonb_build_object('index', v_index, 'erp_category', v_raw, 'reason', 'invalid_erp_category');
      continue;
    end if;
    if v_erp_category = any(v_seen) then
      v_rejected := v_rejected || pg_catalog.jsonb_build_object('index', v_index, 'erp_category', v_raw, 'reason', 'duplicate_erp_category');
      continue;
    end if;
    v_seen := v_seen || v_erp_category;

    -- category_id는 있어야 하고 uuid 문자열 또는 null이다(null은 연결 해제).
    if coalesce(pg_catalog.jsonb_typeof(v_entry -> 'category_id'), '') not in ('string', 'null') then
      v_rejected := v_rejected || pg_catalog.jsonb_build_object('index', v_index, 'erp_category', v_raw, 'reason', 'invalid_category_id');
      continue;
    end if;

    begin
      v_result := public.admin_set_erp_category_mapping(v_erp_category, (v_entry ->> 'category_id')::uuid);
      if (v_result ->> 'changed')::boolean then
        v_changed := v_changed + 1;
      else
        v_unchanged := v_unchanged + 1;
      end if;
    exception
      when invalid_text_representation then
        v_rejected := v_rejected || pg_catalog.jsonb_build_object('index', v_index, 'erp_category', v_raw, 'reason', 'invalid_category_id');
      when invalid_parameter_value or check_violation or no_data_found then
        v_rejected := v_rejected || pg_catalog.jsonb_build_object('index', v_index, 'erp_category', v_raw, 'reason', sqlerrm);
    end;
  end loop;

  return pg_catalog.jsonb_build_object('changed', v_changed, 'unchanged', v_unchanged, 'rejected', v_rejected);
end;
$function$

