CREATE OR REPLACE FUNCTION public.admin_shipment_tracking_summaries(p_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare enabled boolean;
begin
  if (select auth.uid()) is null or not public.has_operator_capability('sales.dispatch', false) then
    raise insufficient_privilege using message = 'operator_capability_required'; end if;
  if p_ids is null or cardinality(p_ids) > 1000 or array_position(p_ids, null) is not null then
    raise invalid_parameter_value using message = 'invalid_shipment_selection'; end if;
  enabled := coalesce((select auto_delivery_enabled from private.delivery_tracking_settings where singleton), false);
  return jsonb_build_object('autoDelivery', enabled, 'shipments', coalesce((select jsonb_object_agg(s.id, jsonb_build_object(
    'extraTrackings', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'carrier', x.carrier, 'trackingNumber', x.tracking_number,
        'source', x.source, 'createdAt', x.created_at) order by x.created_at, x.id)
      from public.order_shipment_extra_trackings x where x.shipment_id = s.id), '[]'::jsonb),
    'deliveredBy', case when not enabled or s.status <> 'delivered' or s.delivery_method <> 'parcel' then null
      when exists(select 1 from private.shipment_auto_deliveries a where a.shipment_id = s.id and a.state = 'completed'
        and a.delivered_at = s.delivered_at) then 'tracking' else 'manual' end,
    'tracking', case when not enabled or s.status <> 'shipping' or s.delivery_method <> 'parcel' or s.tracking_number is null then null
      else (select jsonb_build_object('total', count(*), 'delivered', count(*) filter (where latest.status = 'delivered'),
          'latestStatus', (array_agg(latest.status order by latest.occurred_at desc nulls last))[1],
          'latestAt', max(latest.occurred_at),
          'held', exists(select 1 from private.shipment_auto_deliveries a where a.shipment_id = s.id and a.state = 'held'))
        from private.shipment_current_trackings(s.id) t cross join lateral private.tracking_latest_event(t.carrier, t.tracking_number, t.since) latest) end))
    from public.order_shipments s where s.id = any(p_ids)), '{}'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.admin_start_order_partial_cancellation(p_order_id uuid, p_items jsonb, p_customer_decision text, p_note text, p_warehouse_stop_confirmed boolean, p_expected_refund_amount bigint, p_operation_id uuid, p_refund_account jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); decision text := nullif(btrim(coalesce(p_customer_decision, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), ''); existing private.order_partial_cancellations; plan jsonb; v_id uuid;
  v_sequence integer; line jsonb; closed jsonb; v_state text; zero boolean;
begin
  perform private.require_actor_operator_capability(v_actor, 'sales.manage', false);
  if p_operation_id is null then raise invalid_parameter_value using message = 'invalid_partial_cancel_operation'; end if;
  if decision is null or char_length(decision) not between 2 and 500 or translate(decision, E'\n\r\t', '') ~ '[[:cntrl:]]' then
    raise check_violation using message = 'partial_cancel_customer_decision_required';
  end if;
  if v_note is not null and (char_length(v_note) > 500 or translate(v_note, E'\n\r\t', '') ~ '[[:cntrl:]]') then
    raise check_violation using message = 'invalid_partial_cancel_note';
  end if;
  -- 공통 잠금 순서: order → shipments → attempts → payments → 부분 취소 원장.
  perform 1 from public.orders where id = p_order_id for update;
  if not found then raise no_data_found using message = 'order_not_found'; end if;
  select * into existing from private.order_partial_cancellations where operation_id = p_operation_id;
  if found then
    if existing.order_id <> p_order_id or existing.created_by <> v_actor then
      raise unique_violation using message = 'partial_cancel_operation_conflict';
    end if;
    return jsonb_build_object('id', existing.id, 'state', existing.state, 'provider', existing.provider, 'refundAmount', existing.refund_amount, 'replayed', true);
  end if;
  perform s.id from public.order_shipments s where s.order_id = p_order_id order by s.id for update;
  perform a.id from public.payment_attempts a where a.purpose = 'order' and a.ref_id = p_order_id order by a.id for update;
  perform p.id from public.payments p where p.purpose = 'order' and p.ref_id = p_order_id order by p.id for update;
  if cardinality(private.order_partial_cancellation_blockers(p_order_id)) = 0 then
    perform private.freeze_order_v1_allocation(p_order_id, v_actor, p_operation_id);
  end if;
  plan := private.order_partial_cancellation_plan(p_order_id, p_items);
  if p_expected_refund_amount is distinct from (plan->>'refundAmount')::bigint then
    raise check_violation using message = 'partial_cancel_amount_changed';
  end if;
  if (plan->>'warehouseStopRequired')::boolean and p_warehouse_stop_confirmed is distinct from true then
    raise check_violation using message = 'warehouse_stop_confirmation_required';
  end if;
  zero := (plan->>'refundAmount')::bigint = 0;
  if plan->>'provider' = 'bank_transfer' and not zero then
    if p_refund_account is null or jsonb_typeof(p_refund_account) <> 'object' or (select count(*) from jsonb_object_keys(p_refund_account)) <> 3
      or not p_refund_account ?& array['bankName', 'accountNumber', 'accountHolder']
      or coalesce(p_refund_account->>'bankName', '') !~ '^\S(.{0,38}\S)?$' or coalesce(p_refund_account->>'accountNumber', '') !~ '^[0-9-]{8,30}$'
      or coalesce(p_refund_account->>'accountHolder', '') !~ '^\S(.{0,38}\S)?$'
      or (p_refund_account->>'bankName') ~ '[[:cntrl:]]' or (p_refund_account->>'accountHolder') ~ '[[:cntrl:]]' then
      raise check_violation using message = 'partial_cancel_refund_account_required';
    end if;
  elsif p_refund_account is not null and p_refund_account <> 'null'::jsonb then
    raise check_violation using message = 'partial_cancel_refund_account_not_allowed';
  end if;
  select coalesce(max(sequence), 0) + 1 into v_sequence from private.order_partial_cancellations where order_id = p_order_id;
  -- 0원 환불은 결제사·송금 없이 바로 적용·완료한다. 무통장은 결제사가 없어 바로 적용하고 송금 대기로 둔다.
  v_state := case when zero then 'completed' when plan->>'provider' = 'bank_transfer' then 'awaiting_transfer' else 'processing' end;
  insert into private.order_partial_cancellations(order_id, payment_id, provider, sequence, reason_code, customer_decision, note,
    warehouse_stop_confirmed, payment_amount, balance_before, goods_refund_amount, shipping_refund_amount, refund_amount,
    store_credit_restore_amount, state, operation_id, created_by, filed_at, filed_by)
  values (p_order_id, (plan->>'paymentId')::uuid, (plan->>'provider')::public.payment_provider, v_sequence, 'out_of_stock', decision, v_note,
    (plan->>'warehouseStopRequired')::boolean, (plan->>'paymentAmount')::bigint, (plan->>'balanceBefore')::bigint,
    (plan->>'goodsRefundAmount')::bigint, (plan->>'shippingRefundAmount')::bigint, (plan->>'refundAmount')::bigint,
    (plan->>'storeCreditRestoreAmount')::bigint, 'processing', p_operation_id, v_actor,
    case when v_state = 'awaiting_transfer' then clock_timestamp() end, case when v_state = 'awaiting_transfer' then v_actor end)
  returning id into v_id;
  for line in select value from jsonb_array_elements(plan->'lines') loop
    insert into private.order_partial_cancellation_items(partial_cancellation_id, order_id, order_item_id, shipment_id, qty, canceled_qty_before,
      gross_amount, volume_discount, coupon_discount, store_credit_discount, goods_refund_amount)
    values (v_id, p_order_id, (line->>'orderItemId')::uuid, (line->>'shipmentId')::uuid, (line->>'qty')::integer, (line->>'canceledQtyBefore')::integer,
      (line->>'grossAmount')::bigint, (line->>'volumeDiscount')::bigint, (line->>'couponDiscount')::bigint,
      (line->>'storeCreditDiscount')::bigint, (line->>'goodsRefundAmount')::bigint);
  end loop;
  for closed in select value from jsonb_array_elements(plan->'closedShipments') loop
    insert into private.order_partial_cancellation_shipments(partial_cancellation_id, order_id, shipment_id, shipping_fee_refund)
    values (v_id, p_order_id, (closed->>'shipmentId')::uuid, (closed->>'shippingFeeRefund')::bigint);
  end loop;
  insert into public.audit_log(actor_id, action, target, diff)
  values (v_actor, 'admin.order.partial_cancellation_started', 'order:' || p_order_id::text,
    jsonb_build_object('partialCancellationId', v_id, 'sequence', v_sequence, 'provider', plan->>'provider', 'reasonCode', 'out_of_stock',
      'customerDecision', decision, 'note', v_note, 'warehouseStopConfirmed', (plan->>'warehouseStopRequired')::boolean,
      'refundAmount', (plan->>'refundAmount')::bigint, 'goodsRefundAmount', (plan->>'goodsRefundAmount')::bigint,
      'shippingRefundAmount', (plan->>'shippingRefundAmount')::bigint, 'balanceBefore', (plan->>'balanceBefore')::bigint,
      'lines', plan->'lines', 'closedShipments', plan->'closedShipments'));
  if v_state = 'awaiting_transfer' then
    insert into private.order_partial_cancellation_refund_accounts(partial_cancellation_id, bank_name, account_number, account_holder, masked_account, masked_holder)
    values (v_id, p_refund_account->>'bankName', p_refund_account->>'accountNumber', p_refund_account->>'accountHolder',
      (p_refund_account->>'bankName') || ' ' || public.mask_refund_account_number(p_refund_account->>'accountNumber'),
      public.mask_refund_account_holder(p_refund_account->>'accountHolder'));
    perform private.apply_order_partial_cancellation(v_id, v_actor, 'awaiting_transfer');
  elsif v_state = 'completed' then
    perform private.apply_order_partial_cancellation(v_id, v_actor, 'completed');
  end if;
  return jsonb_build_object('id', v_id, 'state', v_state, 'provider', plan->>'provider', 'refundAmount', (plan->>'refundAmount')::bigint, 'replayed', false);
end $function$

CREATE OR REPLACE FUNCTION public.admin_stop_discount_promotion(p_promotion_id uuid, p_operation_id uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare promotion private.discount_promotions; period private.goods_variant_price_periods; ids text[]; id_value text;
  disabled integer:=0; result jsonb;
begin
  perform private.require_goods_group_identity(p_actor,p_session);
  if p_promotion_id is null or p_operation_id is null then raise invalid_parameter_value using message='discount_promotion_invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('discount-promotion:'||p_promotion_id::text,0));
  select * into promotion from private.discount_promotions where id=p_promotion_id for update;
  if not found then raise no_data_found using message='discount_promotion_not_found'; end if;
  if promotion.state='stopped' then
    if promotion.stop_operation_id=p_operation_id then return promotion.stop_receipt; end if;
    raise sqlstate 'PT409' using message='discount_promotion_already_stopped';
  end if;
  ids:=array(select distinct good_id from private.goods_variant_price_periods
    where promotion_id=p_promotion_id and state='active' and ends_at>clock_timestamp() order by good_id);
  if cardinality(ids)=0 and promotion.ends_at<=clock_timestamp() then raise check_violation using message='discount_promotion_ended'; end if;
  foreach id_value in array ids loop
    if not pg_try_advisory_xact_lock(hashtextextended('admin_good:'||id_value,0)) then
      raise sqlstate 'PT409' using message='discount_promotion_busy';
    end if;
  end loop;
  begin
    perform 1 from public.goods where id=any(ids) order by id for update nowait;
    perform 1 from public.goods_variants where good_id=any(ids) order by id for update nowait;
    perform 1 from private.goods_variant_price_periods where good_id=any(ids) order by id for update nowait;
  exception when lock_not_available then raise sqlstate 'PT409' using message='discount_promotion_busy';
  end;
  for period in select * from private.goods_variant_price_periods
    where promotion_id=p_promotion_id and state='active' and ends_at>clock_timestamp() order by good_id,variant_id,id loop
    perform public.admin_save_goods_price_period(period.good_id,period.variant_id,period.id,jsonb_build_object('state','disabled',
      'discountPrice',period.discount_price,'startsAt',period.starts_at,'endsAt',period.ends_at),period.revision);
    disabled:=disabled+1;
  end loop;
  result:=jsonb_build_object('state','completed','operationId',p_operation_id,'promotionId',p_promotion_id,
    'disabledCount',disabled,'goodsCount',cardinality(ids),'stoppedAt',clock_timestamp());
  update private.discount_promotions set state='stopped',stopped_by=p_actor,stopped_at=clock_timestamp(),stop_operation_id=p_operation_id,
    stop_receipt=result,revision=revision+1 where id=p_promotion_id;
  insert into public.audit_log(actor_id,action,target,diff) values(p_actor,'catalog.discount_promotion.stopped','discount_promotion:'||p_promotion_id::text,
    jsonb_build_object('before',to_jsonb(promotion),'receipt',result));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_submit_seller_claim_intake(p_request_id uuid, p_payload jsonb, p_refund_account jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid()); target public.orders;
  previous private.seller_order_claim_intakes; saved_payload jsonb; collections jsonb; targets jsonb;
  block text; submitted_at timestamptz; requested_at timestamptz; target_id uuid;
begin
  perform private.require_operator_capability('sales.manage',false);

  if p_request_id is null then raise invalid_parameter_value using message = 'invalid_seller_claim_request'; end if;
  perform private.validate_seller_claim_intake(p_payload, p_refund_account);
  target_id := (p_payload->>'orderId')::uuid;
  requested_at := (p_payload->>'customerRequestedAt')::timestamptz;
  -- Raw bank details have exactly one storage destination and its existing purge
  -- lifecycle. The idempotency receipt stores only their SHA-256 fingerprint.
  saved_payload := p_payload || jsonb_build_object('refundAccountDigest',
    case when p_refund_account is null or p_refund_account = 'null'::jsonb then null
      else encode(extensions.digest(p_refund_account::text, 'sha256'), 'hex') end);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('seller_claim_intake:' || p_request_id, 0));
  select * into previous from private.seller_order_claim_intakes where claim_id = p_request_id;
  if found then
    if previous.actor_id <> actor or previous.payload <> saved_payload then
      raise exception using errcode = 'PT409', message = 'seller_claim_request_conflict';
    end if;
    return private.seller_claim_intake_json(p_request_id);
  end if;
  if exists(select 1 from public.order_cancellation_requests where id = p_request_id) then
    raise exception using errcode = 'PT409', message = 'seller_claim_request_conflict';
  end if;

  -- Same parent-first order as customer intake and dispatch. No financial
  -- operation is performed after these locks; they only stabilize eligibility.
  select * into target from public.orders where id = target_id for update;
  if not found then raise no_data_found using message = 'order_not_found'; end if;
  perform s.id from public.order_shipments s where s.order_id = target_id order by s.id for update;
  perform attempt.id from public.payment_attempts attempt where attempt.purpose = 'order' and attempt.ref_id = target_id order by attempt.id for update;
  if p_payload->>'claimType'='exchange' and private.order_has_digital_items(target_id) then
    raise check_violation using message='digital_exchange_unavailable'; end if;
  submitted_at := clock_timestamp();
  block := case when p_payload->>'claimType'='cancel' then private.seller_cancel_intake_block(target_id)
    else private.seller_claim_intake_block(target_id, p_payload->>'reasonType', submitted_at) end;
  if block is not null then raise check_violation using message = block; end if;
  if requested_at < target.created_at or requested_at > submitted_at then
    raise invalid_parameter_value using message = 'invalid_seller_claim_customer_time';
  end if;
  if p_payload->>'source' = 'inquiry' then
    perform 1 from public.inquiries where id = (p_payload->>'inquiryId')::uuid and user_id = target.user_id and order_id = target_id for share;
    if not found then raise check_violation using message = 'seller_claim_inquiry_mismatch'; end if;
  end if;
  if p_payload->>'claimType'='cancel' then
    collections:='[]'::jsonb;
  else
  targets := private.seller_claim_collection_targets(target_id);
  if jsonb_array_length(targets) <> jsonb_array_length(p_payload->'collections')
    or (select count(distinct (x->>'shipmentId')::uuid) from jsonb_array_elements(p_payload->'collections') x) <> jsonb_array_length(targets)
    or exists(select 1 from jsonb_array_elements(p_payload->'collections') x where not exists(select 1 from jsonb_array_elements(targets) t where (t->>'shipmentId')::uuid = (x->>'shipmentId')::uuid))
  then raise check_violation using message = 'seller_claim_collections_changed'; end if;
  if exists(select 1 from jsonb_array_elements(p_payload->'collections') x where x->>'carrier' is not null
    and not exists(select 1 from public.shipping_carriers carrier where carrier.code = x->>'carrier' and carrier.is_active))
  then raise check_violation using message = 'unknown_shipping_carrier'; end if;
  select jsonb_agg(x || jsonb_build_object('originId', t->>'originId', 'originName', t->>'originName', 'items', t->'items') order by t->>'originId', t->>'shipmentId')
    into collections from jsonb_array_elements(p_payload->'collections') x join jsonb_array_elements(targets) t on (x->>'shipmentId')::uuid = (t->>'shipmentId')::uuid;

  end if;

  insert into public.order_cancellation_requests(id, order_id, requested_by, claim_type, reason_type, reason, stage, requested_at)
    values(p_request_id, target_id, target.user_id, p_payload->>'claimType', p_payload->>'reasonType', p_payload->>'reason', 'requested', submitted_at);
  insert into private.seller_order_claim_intakes(claim_id, actor_id, payload, collection_snapshot, created_at)
    values(p_request_id, actor, saved_payload, collections, submitted_at);
  -- Preserve the submitted payload for exact idempotency while the immutable
  -- target labels/items are stored separately inside the same private receipt.
  -- They are returned by joining the original input with its intake snapshot.
  if p_refund_account is not null and p_refund_account <> 'null'::jsonb then
    insert into private.claim_refund_accounts(claim_id, bank_name, account_number, account_holder, masked_account, masked_holder)
      values(p_request_id, p_refund_account->>'bankName', p_refund_account->>'accountNumber', p_refund_account->>'accountHolder',
        (p_refund_account->>'bankName') || ' ' || public.mask_refund_account_number(p_refund_account->>'accountNumber'),
        public.mask_refund_account_holder(p_refund_account->>'accountHolder'));
  end if;
  insert into public.audit_log(actor_id, action, target, diff) values(actor, 'admin.order.claim_intake_created', 'order:' || target_id::text,
    jsonb_build_object('claimId', p_request_id, 'claimType', p_payload->>'claimType', 'to', 'requested', 'source', p_payload->>'source',
      'inquiryId', p_payload->>'inquiryId', 'customerRequestedAt', requested_at, 'collectionCount', jsonb_array_length(collections)));
  perform private.notify_order_claim(p_request_id, 'seller_requested', case when p_payload->>'claimType'='cancel' then '취소 요청이 접수됐어요' else '반품·교환 요청이 접수됐어요' end,
    '고객님과 확인한 내용을 바탕으로 담당자가 요청을 접수했습니다. 승인과 이후 처리는 별도로 진행됩니다.');
  return private.seller_claim_intake_json(p_request_id);
end $function$

CREATE OR REPLACE FUNCTION public.admin_suggest_goods_identifiers(target_ip_id text, target_name text)
 RETURNS TABLE(code text, slug text, default_variant_code text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prefix_value text; ordinal bigint; candidate text;
begin
  if not public.has_operator_capability('catalog.read',false) then raise insufficient_privilege using message='operator_capability_required'; end if;

  if (select auth.uid()) is null then raise invalid_authorization_specification using message='auth_required'; end if;
  if not public.has_operator_capability('catalog.read',false) then raise insufficient_privilege using message='forbidden'; end if;
  if not exists(select 1 from public.ips where id=target_ip_id and archived_at is null) then
    raise no_data_found using message='ip_not_found';
  end if;
  prefix_value:=private.goods_code_prefix(target_ip_id);
  select coalesce((select last_number from private.goods_code_counters where prefix=prefix_value),0)+1 into ordinal;
  loop
    candidate:=prefix_value||'-'||lpad(ordinal::text,greatest(4,length(ordinal::text)),'0');
    exit when not exists(select 1 from public.goods good where good.code=candidate)
      and not exists(select 1 from public.goods_variants variant where variant.code=candidate||'-01');
    ordinal:=ordinal+1;
  end loop;
  code:=candidate;
  slug:=private.available_goods_slug(target_name);
  default_variant_code:=code||'-01';
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_suspend_user(target_profile_id uuid, target_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  actor_role public.user_role;
  actor_suspended_at timestamptz;
  selected_role public.user_role;
  selected_suspended_at timestamptz;
  normalized_reason text := nullif(
    pg_catalog.btrim(target_reason, E' \t\n\r\f\v'),
    ''
  );
  changed_at timestamptz;
begin
  perform private.lock_operator_subjects(array[(select auth.uid()),target_profile_id]);
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  select profile.role, profile.suspended_at
    into actor_role, actor_suspended_at
  from public.profiles as profile
  where profile.id = actor_id
  for update;

  if not found
    or actor_role not in ('staff', 'admin')
    or actor_suspended_at is not null
  then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_profile_id = actor_id then
    raise exception 'cannot_suspend_self' using errcode = '22023';
  end if;

  if normalized_reason is null or pg_catalog.length(normalized_reason) > 200 then
    raise exception 'invalid_suspension_reason' using errcode = '22023';
  end if;

  select profile.role, profile.suspended_at
    into selected_role, selected_suspended_at
  from public.profiles as profile
  where profile.id = target_profile_id
  for update;

  if not found then
    raise exception 'profile_not_found' using errcode = 'P0002';
  end if;

  -- A primary manager cannot bypass the peer-revocation rule through sanctions.
  -- Owner transfer or an explicit manager-role change must happen first.
  if exists(select 1 from private.operator_memberships
    where profile_id=target_profile_id and manager_role in ('owner','primary')) then
    raise exception 'operator_manager_change_required' using errcode='42501';
  end if;
  if (private.operator_access_for(actor_id)->>'mode')='legacy'
    and (selected_role='admin' or (actor_role='staff' and selected_role<>'user')) then
    raise exception 'forbidden' using errcode='42501';
  end if;

  if selected_suspended_at is not null then
    return jsonb_build_object(
      'profileId', target_profile_id,
      'changed', false,
      'suspendedAt', selected_suspended_at
    );
  end if;

  changed_at := pg_catalog.clock_timestamp();

  update public.profiles as profile
  set
    suspended_at = changed_at,
    suspension_reason = normalized_reason
  where profile.id = target_profile_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'admin.member.suspended',
    'profile:' || target_profile_id::text,
    jsonb_build_object('from', 'active', 'to', 'suspended')
  );

  return jsonb_build_object(
    'profileId', target_profile_id,
    'changed', true,
    'suspendedAt', changed_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_swap_shipment_trackings(p_shipment_id uuid, p_expected_tracking text, p_other_reference text, p_expected_other_tracking text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; other_id uuid; reason_value text := nullif(btrim(coalesce(p_reason, '')), '');
  first_scope uuid[]; second_scope uuid[]; first public.order_shipments; second public.order_shipments; member public.order_shipments;
begin
  actor := private.require_operator_capability('sales.dispatch', false);
  if p_shipment_id is null or p_other_reference is null then raise invalid_parameter_value using message = 'invalid_tracking_swap'; end if;
  if reason_value is null or char_length(reason_value) > 500 then raise check_violation using message = 'tracking_swap_reason_required'; end if;
  other_id := private.resolve_shipment_reference(p_other_reference);
  if other_id = p_shipment_id then raise invalid_parameter_value using message = 'invalid_tracking_swap'; end if;
  -- 주문 → 배송 건 순서로 두 묶음을 한 번에 잠근다(다른 등록 경로와 같은 순서).
  perform private.lock_shipment_pack_scope(array[p_shipment_id, other_id]);
  first_scope := private.shipment_pack_scope(array[p_shipment_id]);
  second_scope := private.shipment_pack_scope(array[other_id]);
  if first_scope && second_scope then raise check_violation using message = 'tracking_swap_same_pack'; end if;
  select * into first from public.order_shipments where id = p_shipment_id;
  select * into second from public.order_shipments where id = other_id;
  if exists(select 1 from public.order_shipments s join public.orders o on o.id = s.order_id
    where s.id = any(first_scope || second_scope)
      and (s.delivery_method <> 'parcel' or s.status not in ('shipping', 'delivered') or o.status = 'canceled' or s.tracking_number is null)) then
    raise check_violation using message = 'order_not_shipped'; end if;
  if first.tracking_number is distinct from private.normalize_tracking_number(p_expected_tracking)
    or second.tracking_number is distinct from private.normalize_tracking_number(p_expected_other_tracking)
    or exists(select 1 from public.order_shipments where id = any(first_scope) and (carrier, tracking_number) is distinct from (first.carrier, first.tracking_number))
    or exists(select 1 from public.order_shipments where id = any(second_scope) and (carrier, tracking_number) is distinct from (second.carrier, second.tracking_number)) then
    raise check_violation using message = 'shipment_tracking_changed'; end if;
  if (first.carrier, first.tracking_number) = (second.carrier, second.tracking_number) then
    raise check_violation using message = 'invalid_tracking_swap'; end if;
  perform pg_advisory_xact_lock(key) from (select unnest(array[private.tracking_number_lock_key(first.carrier, first.tracking_number),
    private.tracking_number_lock_key(second.carrier, second.tracking_number)]) key order by 1) keys;
  update public.order_shipments set carrier = second.carrier, tracking_number = second.tracking_number, updated_at = clock_timestamp() where id = any(first_scope);
  update public.order_shipments set carrier = first.carrier, tracking_number = first.tracking_number, updated_at = clock_timestamp() where id = any(second_scope);
  -- 맞바꾼 뒤에도 각 번호를 다른 주문(추가 운송장·재출고 포함)이 쓰고 있으면 바꾸지 않는다.
  if private.tracking_number_conflict(second.carrier, second.tracking_number, first_scope, null) is not null
    or private.tracking_number_conflict(first.carrier, first.tracking_number, second_scope, null) is not null then
    raise check_violation using message = 'tracking_number_in_use'; end if;
  for member in select * from public.order_shipments where id = any(first_scope || second_scope) order by id loop
    insert into public.audit_log(actor_id, action, target, diff) values (actor, 'admin.shipment.tracking_updated', 'order:' || member.order_id,
      jsonb_build_object('shipmentId', member.id, 'originName', member.origin_name_snapshot,
        'fromCarrier', case when member.id = any(first_scope) then first.carrier else second.carrier end,
        'fromTrackingNumber', case when member.id = any(first_scope) then first.tracking_number else second.tracking_number end,
        'toCarrier', member.carrier, 'toTrackingNumber', member.tracking_number,
        'swappedWithShipmentId', case when member.id = any(first_scope) then second.id else first.id end, 'reason', reason_value));
  end loop;
  return jsonb_build_object('status', 'swapped', 'shipmentId', first.id, 'orderId', first.order_id, 'otherShipmentId', second.id, 'otherOrderId', second.order_id,
    'trackingNumber', second.tracking_number, 'otherTrackingNumber', first.tracking_number);
end $function$

CREATE OR REPLACE FUNCTION public.admin_tracking_reply_shipment_links(p_references text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  refs text[];
  result jsonb;
begin
  if auth.uid() is null or not public.has_operator_capability('sales.dispatch', false) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  if p_references is null or coalesce(array_length(p_references, 1), 0) > 2000 then
    raise exception using message = 'tracking_reply_references_invalid';
  end if;
  select coalesce(array_agg(distinct pg_catalog.lower(btrim(ref))), array[]::text[]) into refs
  from unnest(p_references) as ref where ref is not null and btrim(ref) <> '';
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('reference', found.reference, 'shipmentId', found.shipment_id)), '[]'::jsonb) into result
  from (
    select distinct on (match.reference, link.shipment_id) match.reference, link.shipment_id
    from (
      select pg_catalog.lower(i.product_order_number) as reference, i.id as item_id
      from public.order_items i where pg_catalog.lower(i.product_order_number) = any(refs)
      union all
      select i.id::text, i.id from public.order_items i where i.id::text = any(refs)
    ) match
    join public.order_shipment_items link on link.order_item_id = match.item_id
  ) found;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_transfer_operator_owner(p_profile_id uuid, p_expected_owner_revision integer, p_expected_target_revision integer, p_expected_access_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); state private.operator_access_state; previous_owner private.operator_memberships; target private.operator_memberships; request jsonb; result jsonb; next_revision integer;
begin
  if actor is null then raise insufficient_privilege using message='operator_capability_required'; end if;
  if p_profile_id is null or p_operation_id is null or p_expected_owner_revision is null or p_expected_owner_revision<1 or p_expected_target_revision is null or p_expected_target_revision<1 or p_expected_access_revision is null or p_expected_access_revision<1
    then raise invalid_parameter_value using message='invalid_operator_transfer'; end if;
  select * into strict state from private.operator_access_state where id for update;
  perform private.lock_operator_subjects(array[actor,p_profile_id]);
  -- The former owner becomes primary. Allow only its exact completed operation
  -- to be read again after the transfer capability has been removed.
  perform private.require_actor_operator_capability(actor,'operators.manage',true);
  request:=jsonb_build_object('profileId',p_profile_id,'expectedOwnerRevision',p_expected_owner_revision,'expectedTargetRevision',p_expected_target_revision,'expectedAccessRevision',p_expected_access_revision);
  result:=private.operator_lifecycle_replay(actor,p_operation_id,'admin.operator.owner_transferred',request);
  if result is not null then return result; end if;
  perform private.require_actor_operator_capability(actor,'operators.transfer',false);
  if not state.configured then raise invalid_parameter_value using message='operator_setup_required'; end if;
  if state.revision<>p_expected_access_revision then raise sqlstate 'PT409' using message='operator_access_changed'; end if;
  if actor=p_profile_id then raise insufficient_privilege using message='operator_self_change_denied'; end if;
  select * into previous_owner from private.operator_memberships where profile_id=actor for update;
  select * into target from private.operator_memberships where profile_id=p_profile_id for update;
  if previous_owner.manager_role is distinct from 'owner' then raise insufficient_privilege using message='operator_capability_required'; end if;
  if previous_owner.revision<>p_expected_owner_revision or target.revision is distinct from p_expected_target_revision then raise sqlstate 'PT409' using message='operator_membership_changed'; end if;
  if target.manager_role<>'primary' then raise invalid_parameter_value using message='operator_primary_target_required'; end if;
  if not exists(select 1 from public.profiles where id=p_profile_id and role in ('staff','admin') and suspended_at is null)
    or exists(select 1 from private.account_action_fences where subject_user_id=p_profile_id) then raise invalid_parameter_value using message='operator_suspended_target'; end if;
  update private.operator_memberships set manager_role='primary',revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where profile_id=actor;
  update private.operator_memberships set manager_role='owner',revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where profile_id=p_profile_id returning revision into next_revision;
  update private.operator_access_state set revision=revision+1,updated_at=clock_timestamp(),updated_by=actor where id returning * into state;
  result:=jsonb_build_object('revision',next_revision,'accessRevision',state.revision,'ownerId',p_profile_id,'previousOwnerId',actor);
  insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.operator.owner_transferred','operators',
    jsonb_build_object('request',request,'result',result));
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_unarchive_category(target_operation_id uuid, target_category_id uuid, target_expected_updated_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  category_row public.catalog_categories;
  next_depth integer;
  existing_actor_id uuid;
  existing_action text;
  existing_diff jsonb;
  request_payload jsonb;
  changed boolean;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor_id is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message = 'forbidden'; end if;
  if target_operation_id is null or target_category_id is null or target_expected_updated_at is null then raise invalid_parameter_value using message = 'invalid_category_operation'; end if;
  request_payload := jsonb_build_object('category_id', target_category_id, 'expected_updated_at', target_expected_updated_at);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || target_operation_id::text, 0));
  select audit.actor_id, audit.action, audit.diff into existing_actor_id, existing_action, existing_diff
  from public.audit_log as audit where audit.id = target_operation_id;
  if found then
    if existing_actor_id = actor_id and existing_action = 'admin.catalog.category.unarchived' and existing_diff -> 'request' = request_payload then
      return coalesce((existing_diff ->> 'changed')::boolean, true);
    end if;
    raise unique_violation using message = 'operation_conflict';
  end if;
  perform private.lock_catalog_category_tree();
  select * into category_row from public.catalog_categories where id = target_category_id for update;
  if not found then raise no_data_found using message = 'category_not_found'; end if;
  if category_row.updated_at is distinct from target_expected_updated_at then raise exception using errcode = 'PT409', message = 'category_changed'; end if;
  if category_row.archived_at is null then
    changed := false;
    next_depth := category_row.depth;
  else
    next_depth := private.category_validate_parent(target_category_id, category_row.parent_id);
    update public.catalog_categories set archived_at = null, depth = next_depth, updated_at = pg_catalog.now() where id = target_category_id;
    changed := true;
  end if;
  insert into public.audit_log(id, actor_id, action, target, diff)
  values (target_operation_id, actor_id, 'admin.catalog.category.unarchived', 'catalog_categories:' || target_category_id::text,
    jsonb_build_object('request', request_payload, 'changed', changed, 'depth', next_depth));
  return changed;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_unsuspend_user(target_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  actor_role public.user_role;
  actor_suspended_at timestamptz;
  selected_role public.user_role;
  selected_suspended_at timestamptz;
begin
  perform private.lock_operator_subjects(array[(select auth.uid()),target_profile_id]);
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  select profile.role, profile.suspended_at
    into actor_role, actor_suspended_at
  from public.profiles as profile
  where profile.id = actor_id
  for update;

  if not found
    or actor_role not in ('staff', 'admin')
    or actor_suspended_at is not null
  then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_profile_id = actor_id then
    raise exception 'cannot_unsuspend_self' using errcode = '22023';
  end if;

  select profile.role, profile.suspended_at
    into selected_role, selected_suspended_at
  from public.profiles as profile
  where profile.id = target_profile_id
  for update;

  if not found then
    raise exception 'profile_not_found' using errcode = 'P0002';
  end if;

  -- A primary manager cannot bypass the peer-revocation rule through sanctions.
  -- Owner transfer or an explicit manager-role change must happen first.
  if exists(select 1 from private.operator_memberships
    where profile_id=target_profile_id and manager_role in ('owner','primary')) then
    raise exception 'operator_manager_change_required' using errcode='42501';
  end if;
  if (private.operator_access_for(actor_id)->>'mode')='legacy'
    and (selected_role='admin' or (actor_role='staff' and selected_role<>'user')) then
    raise exception 'forbidden' using errcode='42501';
  end if;

  if exists(select 1 from private.member_withdrawal_processings w where w.user_id = target_profile_id) then
    raise exception 'member_withdrawn' using errcode = '22023';
  end if;

  if selected_suspended_at is null then
    return jsonb_build_object(
      'profileId', target_profile_id,
      'changed', false,
      'suspendedAt', null
    );
  end if;

  update public.profiles as profile
  set
    suspended_at = null,
    suspension_reason = null
  where profile.id = target_profile_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'admin.member.unsuspended',
    'profile:' || target_profile_id::text,
    jsonb_build_object('from', 'suspended', 'to', 'active')
  );

  return jsonb_build_object(
    'profileId', target_profile_id,
    'changed', true,
    'suspendedAt', null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_category_display_tree(p_change jsonb, p_expected_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; action_name text; node_id uuid; parent_node_id uuid; node_name text; destination integer;
 previous private.category_display_nodes; current_revision bigint; receipt public.audit_log; request jsonb; result jsonb;
 parent_depth integer; subtree_height integer; sibling_count integer; member record; ordered_ids uuid[];
begin
 actor:=private.require_operator_capability('store.manage',false);
 if p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or jsonb_typeof(p_change) is distinct from 'object' or jsonb_typeof(p_change->'action') is distinct from 'string'
  or p_change->>'action' not in('create','update','archive','restore')
  or jsonb_typeof(p_change->'id') is distinct from 'string'
  or p_change->>'id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 then raise invalid_parameter_value using message='invalid_display_tree_change';end if;
 action_name:=p_change->>'action';node_id:=(p_change->>'id')::uuid;
 if action_name in('create','update') then
  if (select count(*) from jsonb_object_keys(p_change))<>5 or not p_change ?& array['action','id','name','parentId','position']
   or jsonb_typeof(p_change->'name') is distinct from 'string' or btrim(p_change->>'name')=''
   or p_change->>'name' ~ '[\x00-\x1f\x7f]' or p_change->>'name'<>btrim(p_change->>'name')
   or jsonb_typeof(p_change->'parentId') not in('string','null')
   or p_change->>'parentId' is not null and p_change->>'parentId' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(p_change->'position') is distinct from 'number' or p_change->>'position' !~ '^[0-9]{1,6}$'
   then raise invalid_parameter_value using message='invalid_display_tree_details';end if;
  parent_node_id:=(p_change->>'parentId')::uuid;node_name:=p_change->>'name';destination:=(p_change->>'position')::integer;
 elsif (select count(*) from jsonb_object_keys(p_change))<>2 then raise invalid_parameter_value using message='invalid_display_tree_lifecycle';end if;
 request:=jsonb_build_object('change',p_change,'expectedRevision',p_expected_revision);
 perform pg_advisory_xact_lock(hashtextextended('category-display-operation:'||p_operation_id,0));
 select * into receipt from public.audit_log where id=p_operation_id;
 if found then
  if receipt.actor_id=actor and receipt.action='admin.category_display.tree_changed' and receipt.target='category-display:'||node_id and receipt.diff->'request'=request then return receipt.diff->'result';end if;
  raise unique_violation using message='operation_conflict';
 end if;
 -- The same lock precedes source-category/product locks in composition writes.
 perform pg_advisory_xact_lock(hashtextextended('catalog_category_tree',0));
 select revision into current_revision from private.category_display_tree_control where singleton for update;
 if current_revision<>p_expected_revision then raise sqlstate 'PT409' using message='category_display_tree_conflict';end if;
 select * into previous from private.category_display_nodes where id=node_id for update;
 if action_name='create' and found then raise unique_violation using message='display_node_exists';end if;
 if action_name<>'create' and not found then raise no_data_found using message='display_node_missing';end if;
 if action_name in('create','update') then
  if char_length(node_name)>20 and (action_name='create' or node_name is distinct from previous.name) then raise check_violation using message='display_node_name_limit';end if;
  if node_id=parent_node_id then raise check_violation using message='display_tree_cycle';end if;
  if parent_node_id is not null then
   if not exists(select 1 from private.category_display_nodes where id=parent_node_id and archived_at is null)
    or exists(with recursive ancestors as (select * from private.category_display_nodes where id=parent_node_id
      union all select p.* from private.category_display_nodes p join ancestors a on p.id=a.parent_id)
      select 1 from ancestors where id=node_id or archived_at is not null)
    then raise check_violation using message='display_parent_unavailable';end if;
   parent_depth:=(private.category_display_category(parent_node_id)->>'depth')::integer;
  else parent_depth:=0;end if;
  if action_name='create' or parent_node_id is distinct from previous.parent_id then
   with recursive descendants as (select node_id id,1 height union all select n.id,d.height+1 from private.category_display_nodes n join descendants d on n.parent_id=d.id)
   select max(height) into subtree_height from descendants;
   if parent_depth+subtree_height>3 then raise check_violation using message='display_tree_depth_limit';end if;
  end if;
  if action_name='create' or parent_node_id is distinct from previous.parent_id then
   select count(*) into sibling_count from private.category_display_nodes where parent_id is not distinct from parent_node_id and archived_at is null and id<>node_id;
   if sibling_count>=(case when parent_node_id is null then 19 else 15 end) then raise check_violation using message='display_tree_sibling_limit';end if;
  end if;
  if action_name='create' then
   insert into private.category_display_nodes(id,parent_id,name,sort_order) values(node_id,parent_node_id,node_name,0);
  else
   update private.category_display_nodes set name=node_name,parent_id=parent_node_id,updated_at=clock_timestamp() where id=node_id;
  end if;
  select coalesce(array_agg(id order by sort_order,coalesce(legacy_sort_key,id::text),id),'{}'::uuid[]) into ordered_ids from private.category_display_nodes where parent_id is not distinct from parent_node_id and id<>node_id;
  if destination>cardinality(ordered_ids) then raise invalid_parameter_value using message='display_tree_position_out_of_range';end if;
  ordered_ids:=coalesce(ordered_ids[1:destination],'{}'::uuid[])||array[node_id]||coalesce(ordered_ids[destination+1:cardinality(ordered_ids)],'{}'::uuid[]);
  for member in select id,ordinality-1 position from unnest(ordered_ids) with ordinality ids(id,ordinality) loop
   update private.category_display_nodes set sort_order=member.position,updated_at=clock_timestamp() where id=member.id and sort_order<>member.position;
  end loop;
 elsif action_name='archive' then
  if previous.archived_at is not null then raise check_violation using message='display_node_already_archived';end if;
  update private.category_display_nodes set archived_at=clock_timestamp(),updated_at=clock_timestamp() where id=node_id;
 else
  if previous.archived_at is null then raise check_violation using message='display_node_not_archived';end if;
  select count(*) into sibling_count from private.category_display_nodes where parent_id is not distinct from previous.parent_id and archived_at is null;
  if sibling_count>=(case when previous.parent_id is null then 19 else 15 end) then raise check_violation using message='display_tree_sibling_limit';end if;
  if previous.parent_id is not null and exists(with recursive ancestors as (select * from private.category_display_nodes where id=previous.parent_id
    union all select p.* from private.category_display_nodes p join ancestors a on p.id=a.parent_id) select 1 from ancestors where archived_at is not null)
    then raise check_violation using message='display_parent_unavailable';end if;
  update private.category_display_nodes set archived_at=null,updated_at=clock_timestamp() where id=node_id;
 end if;
 update private.category_display_tree_control set revision=current_revision+1 where singleton;
 result:=jsonb_build_object('nodeId',node_id,'directory',public.admin_list_category_displays());
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'admin.category_display.tree_changed','category-display:'||node_id,
  jsonb_build_object('request',request,'before',case when action_name='create' then null else to_jsonb(previous) end,'result',result));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_update_inquiry_chat_tag(p_expected_actor_id uuid, p_inquiry_id uuid, p_label text, p_present boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid;v_label text:=btrim(coalesce(p_label,''));v_changed integer;
begin
  v_actor:=private.require_operator_capability('cs.manage',false);
  if p_expected_actor_id is distinct from v_actor then raise insufficient_privilege using message='inquiry_chat_actor_changed';end if;
  if p_inquiry_id is null or p_present is null or char_length(v_label) not between 1 and 20 or v_label ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message='invalid_inquiry_chat_tag';end if;
  perform 1 from public.inquiries where id=p_inquiry_id for update;
  if not found then raise no_data_found using message='inquiry_not_found';end if;
  if p_present then
    if not exists(select 1 from private.inquiry_chat_tags where inquiry_id=p_inquiry_id and label=v_label)
      and (select count(*) from private.inquiry_chat_tags where inquiry_id=p_inquiry_id)>=10 then
      raise check_violation using message='inquiry_chat_tag_limit';end if;
    insert into private.inquiry_chat_tags(inquiry_id,label,actor_id) values(p_inquiry_id,v_label,v_actor)
      on conflict(inquiry_id,label) do nothing;
  else
    delete from private.inquiry_chat_tags where inquiry_id=p_inquiry_id and label=v_label;
  end if;
  get diagnostics v_changed=row_count;
  if v_changed>0 then
    insert into public.audit_log(actor_id,action,target,diff) values(v_actor,'admin.inquiry.chat_tag_changed','inquiries:'||p_inquiry_id::text,
      jsonb_build_object('label',v_label,'present',p_present));
  end if;
  return public.admin_inquiry_chat_context(p_inquiry_id);
end $function$

CREATE OR REPLACE FUNCTION public.admin_update_ip_identity(target_id text, target_public_slug text, target_expected_public_slug text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  current_public_slug text;
begin
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;
  if not public.has_operator_capability('platform.manage',false) then
    raise insufficient_privilege using message = 'forbidden';
  end if;
  if target_id is null
     or target_id !~ '^[a-z0-9][a-z0-9-]*$'
     or target_public_slug is null
     or target_expected_public_slug is null
  then
    raise invalid_parameter_value using message = 'invalid_ip_identity';
  end if;
  if target_public_slug !~ '^[a-z0-9](?:[a-z0-9-]{0,78}[a-z0-9])?$'
     or target_public_slug = 'aouad'
  then
    raise invalid_parameter_value using message = 'invalid_ip_public_slug';
  end if;

  -- All slug checks and the alias append happen under one global identity lock.
  -- The row lock then makes the expected slug a real stale-write guard.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ip_public_slug_identity', 0)
  );
  select ip.public_slug
    into current_public_slug
  from public.ips as ip
  where ip.id = target_id
  for update of ip;

  if not found then
    raise no_data_found using message = 'catalog_not_found';
  end if;
  if current_public_slug is distinct from target_expected_public_slug then
    -- PostgREST retries SQLSTATE 40001 indefinitely. This is an expected
    -- business stale-write response, so use a private 409 class instead.
    raise exception using errcode = 'PT409', message = 'ip_public_slug_conflict';
  end if;
  if current_public_slug = target_public_slug then
    return false;
  end if;

  if exists (
    select 1 from public.ips as ip
    where (ip.public_slug = target_public_slug or ip.id = target_public_slug)
      and ip.id <> target_id
  ) or exists (
    select 1 from public.ip_public_slug_aliases as alias
    where alias.slug = target_public_slug
  ) then
    raise unique_violation using message = 'ip_public_slug_taken';
  end if;

  -- This FK deliberately prevents hard deletion of an IP whose old URL is a
  -- historical alias. The alias row is append-only and uniquely owned.
  insert into public.ip_public_slug_aliases (slug, ip_id)
  values (current_public_slug, target_id);

  perform pg_catalog.set_config('app.ip_public_slug_write', 'admin_update_ip_identity', true);
  update public.ips
  set public_slug = target_public_slug,
      updated_at = pg_catalog.now()
  where id = target_id;
  perform pg_catalog.set_config('app.ip_public_slug_write', '', true);

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'admin.ip.identity_updated',
    'ips:' || target_id,
    pg_catalog.jsonb_build_object(
      'internal_id', target_id,
      'previous_public_slug', current_public_slug,
      'public_slug', target_public_slug,
      'alias_preserved', true
    )
  );

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_order_status(p_order_id uuid, p_status public.order_status, p_carrier text, p_tracking_number text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid());purchase public.orders;
begin
  perform private.require_operator_capability('sales.manage',false);

 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required';end if;
 if p_status in ('shipping','delivered') then
   perform public.admin_update_shipment_status(private.single_order_shipment(p_order_id),p_status::text,p_carrier,p_tracking_number);return;
 end if;
 select * into purchase from public.orders where id=p_order_id for update;
 if not found then raise no_data_found using message='order_not_found';end if;
 perform id from public.order_shipments where order_id=p_order_id order by id for update;
 if p_status is null or p_status not in ('confirmed','shipping','delivered') then raise check_violation using message='invalid_order_status';end if;
 if p_status in ('shipping','delivered') then
   perform public.admin_update_shipment_status(private.single_order_shipment(p_order_id),p_status::text,p_carrier,p_tracking_number);return;
 end if;
 if purchase.status='confirmed' then return;end if;
 if purchase.status<>'paid' then raise exception using message='invalid_order_transition';end if;
 perform private.confirm_paid_order(p_order_id,actor,'{}'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.admin_update_order_tracking(p_order_id uuid, p_carrier text, p_tracking_number text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.require_operator_capability('sales.manage',false);

 if (select auth.uid()) is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required';end if;
 perform private.lock_shipment_pack_scope(array[private.single_order_shipment(p_order_id)]);
 perform id from public.orders where id=p_order_id for update;
 if not found then raise no_data_found using message='order_not_found';end if;
 perform public.admin_update_shipment_tracking(private.single_order_shipment(p_order_id),p_carrier,p_tracking_number);
end $function$

CREATE OR REPLACE FUNCTION public.admin_update_report_status(target_report_id uuid, target_status public.report_status)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := auth.uid();
  previous_status report_status;
begin
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null or not public.has_operator_capability('platform.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select reports.status
    into previous_status
    from public.reports
    where reports.id = target_report_id
    for update;

  if not found then
    raise exception 'report_not_found' using errcode = '22023';
  end if;

  update public.reports
  set status = target_status
  where reports.id = target_report_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'community_report_status_update',
    'report:' || target_report_id::text,
    jsonb_build_object('from', previous_status, 'to', target_status)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_campaign(target_id text, target_kind text, target_title text, target_subtitle text, target_status text, target_starts_at timestamp with time zone, target_ends_at timestamp with time zone, target_hero_image_path text, target_card_image_path text, target_banner_image_path text, target_featured_order integer, target_sections jsonb, target_previous_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_id text := btrim(coalesce(target_id, ''), E' \t\n\r\f\v');
  normalized_previous_id text := nullif(btrim(coalesce(target_previous_id, ''), E' \t\n\r\f\v'), '');
  normalized_title text := btrim(coalesce(target_title, ''), E' \t\n\r\f\v');
  normalized_subtitle text := nullif(btrim(coalesce(target_subtitle, ''), E' \t\n\r\f\v'), '');
  normalized_status text := coalesce(nullif(btrim(coalesce(target_status, '')), ''), 'draft');
  normalized_sections jsonb := coalesce(target_sections, '[]'::jsonb);
  v_coupon_code text;
begin
  perform private.require_operator_capability('promotion.manage',false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.has_operator_capability('promotion.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if normalized_id !~ '^[a-z0-9][a-z0-9-]{1,63}$' then
    raise exception 'invalid_campaign_id' using errcode = '22023';
  end if;

  if target_kind is null or target_kind not in ('event', 'drop') then
    raise exception 'invalid_campaign_kind' using errcode = '22023';
  end if;

  if char_length(normalized_title) not between 1 and 120 then
    raise exception 'invalid_campaign_title' using errcode = '22023';
  end if;

  if normalized_status not in ('draft', 'published', 'ended') then
    raise exception 'invalid_campaign_status' using errcode = '22023';
  end if;

  if target_starts_at is null or target_ends_at is null or target_ends_at <= target_starts_at then
    raise exception 'invalid_campaign_period' using errcode = '22023';
  end if;

  if target_featured_order is not null and target_featured_order <= 0 then
    raise exception 'invalid_campaign_featured_order' using errcode = '22023';
  end if;

  perform private.validate_campaign_sections(normalized_sections);

  -- coupon 블록의 코드는 실재하는 쿠폰이어야 한다. jsonb 안이라 FK를 걸 수 없는
  -- 자리인데, 오타 하나가 그대로 통과하면 랜딩에는 멀쩡한 경품처럼 걸리고 사용자는
  -- 장바구니에 넣는 순간에야 없는 쿠폰이라는 걸 안다 — 저장 시점에 막는다.
  -- (구조 검증을 통과한 뒤라 sections는 배열이고 coupon_code는 문자열이다.)
  for v_coupon_code in
    select distinct section.entry ->> 'coupon_code'
    from jsonb_array_elements(normalized_sections) as section(entry)
    where section.entry ->> 'type' = 'coupon'
  loop
    if not exists (select 1 from public.coupons where code = v_coupon_code) then
      raise exception 'unknown_coupon_code'
        using errcode = '23503', detail = v_coupon_code;
    end if;
  end loop;

  if normalized_previous_id is not null then
    if normalized_previous_id is distinct from normalized_id then
      raise exception 'catalog_id_immutable' using errcode = '22023';
    end if;

    perform 1 from public.campaigns where id = normalized_id for update;

    if not found then
      raise exception 'catalog_record_missing' using errcode = 'P0002';
    end if;
  else
    -- 슬러그 섀도잉 차단. 레거시 /events/[id] 리다이렉트가 살아 있는 동안
    -- 같은 id의 캠페인이 생기면 그 리다이렉트가 무엇을 가리키는지 알 수 없다.
    -- (반대 방향 — 캠페인이 선점한 슬러그로 이벤트를 만드는 경로 — 은
    --  admin_upsert_event 소관이라 여기서 다루지 않는다.)
    if exists (select 1 from public.events where id = normalized_id) then
      raise exception 'catalog_id_taken' using errcode = '23505';
    end if;
  end if;

  insert into public.campaigns (
    id, kind, title, subtitle, status, starts_at, ends_at,
    hero_image_path, card_image_path, banner_image_path, featured_order, sections
  )
  values (
    normalized_id,
    target_kind,
    normalized_title,
    normalized_subtitle,
    normalized_status,
    target_starts_at,
    target_ends_at,
    nullif(btrim(coalesce(target_hero_image_path, '')), ''),
    nullif(btrim(coalesce(target_card_image_path, '')), ''),
    nullif(btrim(coalesce(target_banner_image_path, '')), ''),
    target_featured_order,
    normalized_sections
  )
  on conflict (id) do update set
    kind = excluded.kind,
    title = excluded.title,
    subtitle = excluded.subtitle,
    status = excluded.status,
    starts_at = excluded.starts_at,
    ends_at = excluded.ends_at,
    hero_image_path = excluded.hero_image_path,
    card_image_path = excluded.card_image_path,
    banner_image_path = excluded.banner_image_path,
    featured_order = excluded.featured_order,
    sections = excluded.sections
  where normalized_previous_id is not null;

  if not found then
    raise exception 'catalog_id_taken' using errcode = '23505';
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'campaign.upsert',
    'campaigns:' || normalized_id,
    jsonb_build_object(
      'mode', case when normalized_previous_id is null then 'create' else 'update' end,
      'after', jsonb_build_object(
        'id', normalized_id,
        'kind', target_kind,
        'title', normalized_title,
        'status', normalized_status,
        'startsAt', target_starts_at,
        'endsAt', target_ends_at,
        'featuredOrder', target_featured_order,
        'sectionCount', jsonb_array_length(normalized_sections)
      )
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_card_pool(target_operation_id uuid, target_pool_id uuid, target_ip_id text, target_name text, target_active_from timestamp with time zone, target_active_to timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_ip_id text := btrim(target_ip_id, E' \t\n\r\f\v');
  normalized_name text := btrim(target_name, E' \t\n\r\f\v');
  request_payload jsonb;
  previous_pool public.card_pools%rowtype;
  previous_payload jsonb := null;
  after_payload jsonb;
  pool_exists boolean := false;
  has_dependency boolean := false;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
begin
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.has_operator_capability('platform.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if target_pool_id is null then
    raise exception 'invalid_pool_id' using errcode = '22004';
  end if;

  if normalized_ip_id is null or normalized_ip_id = '' then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  if normalized_name is null or normalized_name = '' then
    raise exception 'invalid_pool_name' using errcode = '22023';
  end if;

  if target_active_from is null then
    raise exception 'invalid_active_from' using errcode = '22004';
  end if;

  if target_active_to is not null and target_active_to <= target_active_from then
    raise exception 'invalid_pool_active_window' using errcode = '23514';
  end if;

  request_payload := jsonb_build_object(
    'ip_id', normalized_ip_id,
    'name', normalized_name,
    'active_from', target_active_from,
    'active_to', target_active_to
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_card_pool_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.card_pool.upserted'
      and existing_target = 'card_pools:' || target_pool_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_pool_id;
    end if;

    raise exception 'operation_conflict' using errcode = '23505';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_card_pool:' || target_pool_id::text, 0)
  );

  perform 1
  from public.ips
  where id = normalized_ip_id
  for key share;

  if not found then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  select pool.*
    into previous_pool
  from public.card_pools as pool
  where pool.id = target_pool_id
  for update;

  pool_exists := found;

  if pool_exists then
    previous_payload := jsonb_build_object(
      'id', previous_pool.id,
      'ip_id', previous_pool.ip_id,
      'name', previous_pool.name,
      'active_from', previous_pool.active_from,
      'active_to', previous_pool.active_to
    );

    if previous_pool.ip_id is distinct from normalized_ip_id then
      select exists (
        select 1 from public.cards where pool_id = target_pool_id
        union all
        select 1 from public.reward_policies where pool_id = target_pool_id
        union all
        select 1 from public.games where reward_pool_id = target_pool_id
        union all
        select 1 from public.draw_tickets where pool_id = target_pool_id
        union all
        select 1 from public.card_grants where pool_id = target_pool_id
      ) into has_dependency;

      if has_dependency then
        raise exception 'pool_ip_locked' using errcode = '23514';
      end if;
    end if;

    update public.card_pools
    set ip_id = normalized_ip_id,
        name = normalized_name,
        active_from = target_active_from,
        active_to = target_active_to
    where id = target_pool_id;
  else
    insert into public.card_pools (id, ip_id, name, active_from, active_to)
    values (
      target_pool_id,
      normalized_ip_id,
      normalized_name,
      target_active_from,
      target_active_to
    );
  end if;

  after_payload := jsonb_build_object(
    'id', target_pool_id,
    'ip_id', normalized_ip_id,
    'name', normalized_name,
    'active_from', target_active_from,
    'active_to', target_active_to
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.card_pool.upserted',
    'card_pools:' || target_pool_id::text,
    jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_pool_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_card(target_id text, target_ip_id text, target_name text, target_no text, target_rarity public.rarity, target_bg text, target_image_path text, target_pool_id uuid DEFAULT NULL::uuid, target_pool_binding_provided boolean DEFAULT false, target_previous_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_id text := btrim(target_id, E' \t\n\r\f\v');
  normalized_ip_id text := btrim(target_ip_id, E' \t\n\r\f\v');
  normalized_name text := btrim(target_name, E' \t\n\r\f\v');
  normalized_previous_id text := nullif(btrim(coalesce(target_previous_id, ''), E' \t\n\r\f\v'), '');
  previous_card public.cards%rowtype;
  previous_payload jsonb := null;
  after_payload jsonb;
  request_payload jsonb;
  card_exists boolean := false;
  effective_pool_id uuid;
  target_pool_ip_id text;
begin
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.has_operator_capability('platform.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if normalized_id is null or normalized_id = '' then
    raise exception 'invalid_card_id' using errcode = '22023';
  end if;

  if normalized_ip_id is null or normalized_ip_id = '' then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  if normalized_name is null or normalized_name = '' then
    raise exception 'invalid_card_name' using errcode = '22023';
  end if;

  if target_rarity is null then
    raise exception 'invalid_card_rarity' using errcode = '22004';
  end if;

  if target_pool_binding_provided is null
    or (not target_pool_binding_provided and target_pool_id is not null)
  then
    raise exception 'invalid_pool_binding_mode' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_card:' || normalized_id, 0)
  );

  select card.*
    into previous_card
  from public.cards as card
  where card.id = normalized_id
  for update;

  card_exists := found;

  -- #181 신규 등록이 기존 카드를 덮어쓰지 못하게 한다.
  if normalized_previous_id is null then
    if card_exists then
      raise exception 'catalog_id_taken' using errcode = '23505';
    end if;
  else
    if normalized_previous_id is distinct from normalized_id then
      raise exception 'catalog_id_immutable' using errcode = '22023';
    end if;

    if not card_exists then
      raise exception 'catalog_record_missing' using errcode = 'P0002';
    end if;
  end if;

  if target_pool_binding_provided then
    effective_pool_id := target_pool_id;
  elsif card_exists then
    effective_pool_id := previous_card.pool_id;
  else
    effective_pool_id := null;
  end if;

  perform pool.id
  from public.card_pools as pool
  where pool.id = previous_card.pool_id
     or pool.id = effective_pool_id
  order by pool.id
  for update;

  perform 1
  from public.ips
  where id = normalized_ip_id
  for key share;

  if not found then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  if card_exists then
    previous_payload := jsonb_build_object(
      'id', previous_card.id,
      'ip_id', previous_card.ip_id,
      'name', previous_card.name,
      'no', previous_card.no,
      'rarity', previous_card.rarity,
      'bg', previous_card.bg,
      'image_path', previous_card.image_path,
      'pool_id', previous_card.pool_id
    );

    if previous_card.pool_id is not null
      and (
        previous_card.ip_id is distinct from normalized_ip_id
        or previous_card.rarity is distinct from target_rarity
      )
    then
      raise exception 'pooled_card_catalog_contract_locked' using errcode = '23514';
    end if;
  end if;

  if effective_pool_id is not null then
    select pool.ip_id
      into target_pool_ip_id
    from public.card_pools as pool
    where pool.id = effective_pool_id;

    if not found then
      raise exception 'pool_not_found' using errcode = 'P0002';
    end if;

    if target_pool_ip_id is distinct from normalized_ip_id then
      raise exception 'card_pool_ip_mismatch' using errcode = '23514';
    end if;
  end if;

  if card_exists
    and previous_card.pool_id is not null
    and previous_card.pool_id is distinct from effective_pool_id
    and exists (
      select 1
      from public.pool_odds
      where pool_id = previous_card.pool_id
        and rarity = previous_card.rarity
        and probability > 0
    )
    and not exists (
      select 1
      from public.cards as other_card
      where other_card.pool_id = previous_card.pool_id
        and other_card.rarity = previous_card.rarity
        and other_card.id <> previous_card.id
    )
  then
    raise exception 'pool_rarity_uncovered' using errcode = '23514';
  end if;

  request_payload := jsonb_build_object(
    'id', normalized_id,
    'ip_id', normalized_ip_id,
    'name', normalized_name,
    'no', target_no,
    'rarity', target_rarity,
    'bg', target_bg,
    'image_path', target_image_path,
    'pool_id', effective_pool_id,
    'pool_binding_provided', target_pool_binding_provided,
    'mode', case when normalized_previous_id is null then 'create' else 'update' end
  );

  insert into public.cards (
    id,
    ip_id,
    name,
    no,
    rarity,
    bg,
    image_path,
    pool_id
  )
  values (
    normalized_id,
    normalized_ip_id,
    normalized_name,
    target_no,
    target_rarity,
    target_bg,
    target_image_path,
    effective_pool_id
  )
  on conflict (id) do update set
    ip_id = excluded.ip_id,
    name = excluded.name,
    no = excluded.no,
    rarity = excluded.rarity,
    bg = excluded.bg,
    image_path = excluded.image_path,
    pool_id = excluded.pool_id;

  update public.ips
  set cards_count = (
      select count(*)::integer from public.cards where cards.ip_id = ips.id
    ),
    updated_at = now()
  where id in (normalized_ip_id, previous_card.ip_id);

  after_payload := jsonb_build_object(
    'id', normalized_id,
    'ip_id', normalized_ip_id,
    'name', normalized_name,
    'no', target_no,
    'rarity', target_rarity,
    'bg', target_bg,
    'image_path', target_image_path,
    'pool_id', effective_pool_id
  );

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'catalog.card.upsert',
    'cards:' || normalized_id,
    jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_category(target_operation_id uuid, target_category_id uuid, target_code text, target_name text, target_parent_id uuid, target_sort_order integer, target_expected_updated_at timestamp with time zone, target_good_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  category_row public.catalog_categories;
  next_depth integer;
  result_id uuid;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  request_payload jsonb;
begin
  perform private.require_operator_capability('catalog.manage',false);

  if actor_id is null or not public.has_operator_capability('catalog.manage',false) then raise insufficient_privilege using message = 'forbidden'; end if;
  if target_operation_id is null or target_code is null or target_code !~ '^[a-z0-9][a-z0-9-]*$' or length(target_code) > 80
     or target_name is null or btrim(target_name) = '' or length(target_name) > 120
     or target_sort_order is null or target_sort_order < 0 then
    raise invalid_parameter_value using message = 'invalid_category';
  end if;
  -- ADR-0044: 상품 유형 연결은 없다. target_good_type은 배포 사이 이전 화면 호환으로만 받고 무시한다.
  request_payload := jsonb_build_object(
    'category_id', target_category_id,
    'code', target_code,
    'name', btrim(target_name),
    'parent_id', target_parent_id,
    'sort_order', target_sort_order,
    'expected_updated_at', target_expected_updated_at
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('admin.catalog.category.operation:' || target_operation_id::text, 0));
  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;
  if found then
    if existing_actor_id = actor_id
       and existing_action in ('admin.catalog.category.created', 'admin.catalog.category.updated')
       -- 이 migration 전에 저장된 작업은 요청에 'good_type' 키가 있다. 같은 작업 ID 재시도가 충돌로 바뀌지 않게 그 키를 빼고 비교한다.
       and (existing_diff -> 'request') - 'good_type' = request_payload
    then
      result_id := coalesce(target_category_id, nullif(existing_diff ->> 'category_id', '')::uuid);
      next_depth := nullif(existing_diff #>> '{after,depth}', '')::integer;
      if result_id is not null and next_depth is not null then
        return jsonb_build_object('id', result_id, 'depth', next_depth);
      end if;
    end if;
    raise unique_violation using message = 'operation_conflict';
  end if;
  perform private.lock_catalog_category_tree();

  if target_category_id is null then
    if exists (select 1 from public.catalog_categories where code = target_code) then raise unique_violation using message = 'category_code_taken'; end if;
    result_id := extensions.gen_random_uuid();
    next_depth := private.category_validate_parent(result_id, target_parent_id);
    insert into public.catalog_categories (id, code, name, parent_id, depth, sort_order)
    values (result_id, target_code, btrim(target_name), target_parent_id, next_depth, target_sort_order);
    insert into public.audit_log(id, actor_id, action, target, diff)
    values (target_operation_id, actor_id, 'admin.catalog.category.created', 'catalog_categories:' || result_id::text,
      jsonb_build_object('category_id', result_id, 'request', request_payload,
        'after', jsonb_build_object('code', target_code, 'name', btrim(target_name), 'parent_id', target_parent_id, 'depth', next_depth)));
  else
    select * into category_row from public.catalog_categories where id = target_category_id for update;
    if not found then raise no_data_found using message = 'category_not_found'; end if;
    if target_expected_updated_at is null or category_row.updated_at is distinct from target_expected_updated_at then raise exception using errcode = 'PT409', message = 'category_changed'; end if;
    if exists (select 1 from public.catalog_categories where code = target_code and id <> target_category_id) then raise unique_violation using message = 'category_code_taken'; end if;
    next_depth := private.category_validate_parent(target_category_id, target_parent_id);
    update public.catalog_categories
    set code = target_code, name = btrim(target_name), parent_id = target_parent_id, depth = next_depth,
        sort_order = target_sort_order, updated_at = pg_catalog.now()
    where id = target_category_id;
    with recursive descendants as (
      select category.id, 1 as relative_depth
      from public.catalog_categories as category
      where category.parent_id = target_category_id
      union all
      select child.id, descendants.relative_depth + 1
      from descendants
      join public.catalog_categories as child on child.parent_id = descendants.id
    )
    update public.catalog_categories as child
    set depth = next_depth + descendants.relative_depth, updated_at = pg_catalog.now()
    from descendants
    where child.id = descendants.id;
    result_id := target_category_id;
    insert into public.audit_log(id, actor_id, action, target, diff)
    values (target_operation_id, actor_id, 'admin.catalog.category.updated', 'catalog_categories:' || target_category_id::text,
      jsonb_build_object('category_id', target_category_id, 'request', request_payload,
        'after', jsonb_build_object('code', target_code, 'name', btrim(target_name), 'parent_id', target_parent_id, 'depth', next_depth)));
  end if;
  return jsonb_build_object('id', result_id, 'depth', next_depth);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_coin_exchange_offer(target_id uuid, target_pool_id uuid, target_label text, target_coin_cost integer, target_ticket_count integer, target_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_label text := btrim(coalesce(target_label, ''), E' \t\n\r\f\v');
  normalized_status text := coalesce(nullif(btrim(coalesce(target_status, '')), ''), 'active');
  normalized_ticket_count integer := coalesce(target_ticket_count, 1);
  offer_id uuid;
begin
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.has_operator_capability('platform.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if char_length(normalized_label) not between 1 and 80 then
    raise exception 'invalid_offer_label' using errcode = '22023';
  end if;

  if target_coin_cost is null or target_coin_cost not between 1 and 100000 then
    raise exception 'invalid_offer_coin_cost' using errcode = '22023';
  end if;

  if normalized_ticket_count not between 1 and 10 then
    raise exception 'invalid_offer_ticket_count' using errcode = '22023';
  end if;

  if normalized_status not in ('active', 'disabled') then
    raise exception 'invalid_offer_status' using errcode = '22023';
  end if;

  -- 없는 풀을 가리키는 상품은 캠페인 화면에 "교환 가능"으로 그려진 뒤 교환
  -- 시점에야 실패한다. 등록 시점에 막는다.
  perform 1 from public.card_pools where id = target_pool_id for share;
  if not found then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  if target_id is null then
    insert into public.coin_exchange_offers (pool_id, label, coin_cost, ticket_count, status)
    values (target_pool_id, normalized_label, target_coin_cost, normalized_ticket_count, normalized_status)
    returning id into offer_id;
  else
    update public.coin_exchange_offers
    set pool_id = target_pool_id,
        label = normalized_label,
        coin_cost = target_coin_cost,
        ticket_count = normalized_ticket_count,
        status = normalized_status
    where id = target_id
    returning id into offer_id;

    if not found then
      raise exception 'catalog_record_missing' using errcode = 'P0002';
    end if;
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    actor_id,
    'coin.exchange_offer.upsert',
    'coin_exchange_offers:' || offer_id::text,
    jsonb_build_object(
      'mode', case when target_id is null then 'create' else 'update' end,
      'after', jsonb_build_object(
        'poolId', target_pool_id,
        'label', normalized_label,
        'coinCost', target_coin_cost,
        'ticketCount', normalized_ticket_count,
        'status', normalized_status
      )
    )
  );

  return offer_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_coupon_scheduled(target_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid:=auth.uid(); saved public.coupons; previous public.coupons;
  issue_start timestamptz:=(target_payload->>'target_issue_starts_at')::timestamptz;
  issue_end timestamptz:=(target_payload->>'target_issue_ends_at')::timestamptz;
  usage_end timestamptz:=(target_payload->>'target_ends_at')::timestamptz;
  days integer:=(target_payload->>'target_valid_days')::integer;
  normalized_code text:=upper(btrim(target_payload->>'target_code')); benefit text; combined boolean; cadence text;
begin
  perform private.require_operator_capability('marketing.manage',false);

  perform private.assert_active_user(actor);
  if not public.has_operator_capability('marketing.manage',false) or private.is_account_write_fenced(actor) then raise insufficient_privilege using message='staff_required';end if;
  if issue_start is null or (issue_end is not null and issue_end<=issue_start)
    or (days is not null and (days not between 1 and 365 or usage_end is not null))
    or (days is null and usage_end is not null and (issue_start>=usage_end or issue_end>usage_end))
    then raise invalid_parameter_value using message='invalid_coupon_issue_schedule';end if;
  perform pg_advisory_xact_lock(hashtextextended('coupon_admin:'||normalized_code,0));
  select * into previous from public.coupons where code=normalized_code for update;
  benefit:=coalesce(target_payload->>'target_benefit_kind',previous.benefit_kind,'goods');
  if benefit not in('goods','shipping') or (target_payload ? 'target_stackable' and jsonb_typeof(target_payload->'target_stackable') is distinct from 'boolean') then raise invalid_parameter_value using message='invalid_coupon_benefit';end if;
  combined:=coalesce((target_payload->>'target_stackable')::boolean,previous.stackable,false);
  if target_payload ? 'target_grade_benefit_cadence' and (jsonb_typeof(target_payload->'target_grade_benefit_cadence') is distinct from 'string'
    or target_payload->>'target_grade_benefit_cadence' not in ('upgrade','monthly')) then raise invalid_parameter_value using message='invalid_coupon_grade_cadence';end if;
  cadence:=case when nullif(btrim(coalesce(target_payload->>'target_grade_benefit','')),'') is null then 'upgrade'
    else coalesce(target_payload->>'target_grade_benefit_cadence',previous.grade_benefit_cadence,'upgrade') end;
  perform public.admin_upsert_coupon_targeted(target_payload-array['target_issue_starts_at','target_issue_ends_at','target_valid_days','target_benefit_kind','target_stackable','target_grade_benefit_cadence']);
  update public.coupons set benefit_kind=benefit,stackable=combined,issue_starts_at=issue_start,issue_ends_at=issue_end,valid_days=days,grade_benefit_cadence=cadence where code=normalized_code returning * into saved;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'commerce.coupon.schedule_updated','coupons:'||normalized_code,
    jsonb_build_object('before',case when previous.code is null then null else jsonb_build_object('issueStartsAt',previous.issue_starts_at,'issueEndsAt',previous.issue_ends_at,'validDays',previous.valid_days,'benefitKind',previous.benefit_kind,'stackable',previous.stackable,'gradeBenefitCadence',previous.grade_benefit_cadence) end,
      'after',jsonb_build_object('issueStartsAt',saved.issue_starts_at,'issueEndsAt',saved.issue_ends_at,'validDays',saved.valid_days,'benefitKind',saved.benefit_kind,'stackable',saved.stackable,'gradeBenefitCadence',saved.grade_benefit_cadence),'revision',saved.terms_revision));
  return jsonb_build_object('code',saved.code,'revision',saved.terms_revision);
end $function$

CREATE OR REPLACE FUNCTION public.admin_upsert_coupon_targeted(target_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); previous public.coupons; saved public.coupons;
  normalized_code text:=upper(btrim(target_payload->>'target_code')); previous_code text:=nullif(upper(btrim(target_payload->>'target_previous_code')),'');
  segment text:=target_payload->>'target_recipient_segment'; scope text:=target_payload->>'target_goods_scope'; good_ids text[]; category_ids uuid[]; ip_ids text[]; issue_mode text;
  next_status text:=coalesce(target_payload->>'target_status','active');
begin
  perform private.require_operator_capability('marketing.manage',false);

 perform private.assert_active_user(actor);
 if not public.has_operator_capability('marketing.manage',false) or private.is_account_write_fenced(actor) then raise insufficient_privilege using message='staff_required'; end if;
 if jsonb_typeof(target_payload) is distinct from 'object' or exists(select 1 from jsonb_object_keys(target_payload) k
    where k not in ('target_code','target_name','target_discount_type','target_discount_value','target_max_discount_amount','target_min_subtotal','target_starts_at','target_ends_at','target_issue_limit','target_status','target_grade_benefit','target_previous_code','target_recipient_segment','target_goods_scope','target_good_ids','target_expected_revision','target_category_ids','target_issuance_mode','target_ip_ids'))
    or segment is null or segment not in ('all','first_purchase','repeat_purchase') or scope is null or scope not in ('all','selected_goods','selected_categories','selected_ips')
    or next_status not in ('active','archived')
    or jsonb_typeof(target_payload->'target_good_ids') is distinct from 'array' or jsonb_array_length(target_payload->'target_good_ids')>1000
    or exists(select 1 from jsonb_array_elements(target_payload->'target_good_ids') e where jsonb_typeof(e)<>'string' or length(e#>>'{}') not between 1 and 200)
    then raise invalid_parameter_value using message='invalid_coupon_targeting'; end if;
 select coalesce(array_agg(distinct btrim(value) order by btrim(value)),'{}') into good_ids from jsonb_array_elements_text(target_payload->'target_good_ids');
 if scope<>'selected_goods' and cardinality(good_ids)>0 then raise invalid_parameter_value using message='invalid_coupon_targeting'; end if;
 if scope='selected_goods' and next_status='active' and cardinality(good_ids)=0 then raise check_violation using message='coupon_goods_scope_ready'; end if;
 if previous_code is not null and previous_code is distinct from normalized_code then raise invalid_parameter_value using message='catalog_id_immutable'; end if;
 -- Per-code lock covers a new definition before its row exists and prevents a
 -- concurrent creator from being converted into an update.
 perform pg_advisory_xact_lock(hashtextextended('coupon_admin:'||normalized_code,0));
 select * into previous from public.coupons where code=normalized_code for update;
 if previous_code is null and found then raise unique_violation using message='catalog_id_taken'; end if;
 if previous_code is not null then
   if previous.code is null then raise no_data_found using message='catalog_record_missing'; end if;
   if (target_payload->>'target_expected_revision')::integer is distinct from previous.terms_revision then raise exception using errcode='PT409',message='coupon_terms_changed'; end if;
 end if;
 issue_mode:=coalesce(target_payload->>'target_issuance_mode',previous.issuance_mode,'code');
 if issue_mode not in ('code','targeted') or (target_payload?'target_issuance_mode' and jsonb_typeof(target_payload->'target_issuance_mode') is distinct from 'string') then raise invalid_parameter_value using message='invalid_coupon_targeting';end if;
 if target_payload?'target_category_ids' then
  if jsonb_typeof(target_payload->'target_category_ids') is distinct from 'array' or jsonb_array_length(target_payload->'target_category_ids')>100
   or exists(select 1 from jsonb_array_elements(target_payload->'target_category_ids') e where jsonb_typeof(e)<>'string' or e#>>'{}' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') then raise invalid_parameter_value using message='invalid_coupon_category_targeting';end if;
  select coalesce(array_agg(distinct value::uuid order by value::uuid),'{}') into category_ids from jsonb_array_elements_text(target_payload->'target_category_ids');
 else category_ids:=case when scope='selected_categories' then coalesce(previous.target_category_ids,'{}') else '{}' end;end if;
 if (scope<>'selected_categories' and cardinality(category_ids)>0) or (scope='selected_categories' and next_status='active' and cardinality(category_ids)=0) then raise check_violation using message='coupon_category_scope_ready';end if;
 if target_payload?'target_ip_ids' then
  if jsonb_typeof(target_payload->'target_ip_ids') is distinct from 'array' or jsonb_array_length(target_payload->'target_ip_ids')>100
   or exists(select 1 from jsonb_array_elements(target_payload->'target_ip_ids') e where jsonb_typeof(e)<>'string' or e#>>'{}' !~ '^[a-z0-9][a-z0-9-]{0,99}$') then raise invalid_parameter_value using message='invalid_coupon_ip_targeting';end if;
  select coalesce(array_agg(distinct value order by value),'{}') into ip_ids from jsonb_array_elements_text(target_payload->'target_ip_ids');
 else ip_ids:=case when scope='selected_ips' then coalesce(previous.target_ip_ids,'{}') else '{}' end;end if;
 if (scope<>'selected_ips' and cardinality(ip_ids)>0) or (scope='selected_ips' and next_status='active' and cardinality(ip_ids)=0) then raise check_violation using message='coupon_ip_scope_ready';end if;
 -- An archived IP may stay on an existing definition (its goods are not sold), but cannot be newly targeted.
 if exists(select 1 from unnest(ip_ids) selected(id) left join public.ips ip on ip.id=selected.id
   where ip.id is null or ip.archived_at is not null and not selected.id=any(coalesce(previous.target_ip_ids,'{}'))) then raise check_violation using message='coupon_target_ip_unavailable';end if;
 if issue_mode='targeted' and nullif(target_payload->>'target_grade_benefit','') is not null then raise check_violation using message='coupon_targeted_grade_exclusive';end if;
 if cardinality(category_ids)>0 then
  if not pg_try_advisory_xact_lock_shared(hashtextextended('catalog_category_tree',0)) then raise exception using errcode='PT409',message='coupon_category_changed';end if;
  if exists(select 1 from unnest(category_ids) selected(id) left join private.coupon_category_catalog() c on c.id=selected.id
   where c.id is null or c.blocked and not selected.id=any(coalesce(previous.target_category_ids,'{}'))) then raise check_violation using message='coupon_target_category_unavailable';end if;
 end if;
 if exists(select 1 from unnest(good_ids) target(id) where not exists(select 1 from public.goods g where g.id=target.id and (g.archived_at is null or target.id=any(previous.target_good_ids))))
   then raise check_violation using message='coupon_target_good_unavailable'; end if;
 -- Install validated targeting, issuance mode and status together before the
 -- legacy definition writer. A single transaction preserves grade/status checks
 -- during mode changes and never exposes partially updated terms.
 if previous.code is not null then
   update public.coupons set status=next_status,recipient_segment=segment,goods_scope=scope,target_good_ids=good_ids,target_category_ids=category_ids,target_ip_ids=ip_ids,issuance_mode=issue_mode,grade_benefit=case when issue_mode='targeted' then null else grade_benefit end where code=normalized_code;
 end if;
 perform public.admin_upsert_coupon(
   normalized_code,target_payload->>'target_name',target_payload->>'target_discount_type',(target_payload->>'target_discount_value')::integer,
   (target_payload->>'target_max_discount_amount')::integer,(target_payload->>'target_min_subtotal')::integer,
   (target_payload->>'target_starts_at')::timestamptz,(target_payload->>'target_ends_at')::timestamptz,
   (target_payload->>'target_issue_limit')::integer,next_status,(target_payload->>'target_grade_benefit')::public.loyalty_grade,previous_code);
 update public.coupons set recipient_segment=segment,goods_scope=scope,target_good_ids=good_ids,target_category_ids=category_ids,target_ip_ids=ip_ids,issuance_mode=issue_mode where code=normalized_code returning * into saved;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'commerce.coupon.targeting_updated','coupons:'||normalized_code,
   jsonb_build_object('before',case when previous.code is null then null else jsonb_build_object('recipientSegment',previous.recipient_segment,'goodsScope',previous.goods_scope,'targetGoodIds',previous.target_good_ids,'targetCategoryIds',previous.target_category_ids,'targetIpIds',previous.target_ip_ids,'issuanceMode',previous.issuance_mode,'revision',previous.terms_revision) end,
     'after',jsonb_build_object('recipientSegment',saved.recipient_segment,'goodsScope',saved.goods_scope,'targetGoodIds',saved.target_good_ids,'targetCategoryIds',saved.target_category_ids,'targetIpIds',saved.target_ip_ids,'issuanceMode',saved.issuance_mode,'revision',saved.terms_revision)));
 return jsonb_build_object('code',saved.code,'revision',saved.terms_revision);
end $function$

CREATE OR REPLACE FUNCTION public.admin_upsert_game_unguarded(target_operation_id uuid, target_previous_game_id text, target_game_id text, target_title text, target_reward_pool_id uuid, target_event_id text, target_per_user_daily_limit integer, target_active_from timestamp with time zone, target_active_to timestamp with time zone, target_end_now boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_previous_game_id text := case
    when target_previous_game_id is null then null
    else nullif(btrim(target_previous_game_id, E' \t\n\r\f\v'), '')
  end;
  normalized_game_id text := case
    when target_game_id is null then null
    else nullif(btrim(target_game_id, E' \t\n\r\f\v'), '')
  end;
  normalized_title text := case
    when target_title is null then null
    else nullif(btrim(target_title, E' \t\n\r\f\v'), '')
  end;
  normalized_event_id text := case
    when target_event_id is null then null
    else nullif(btrim(target_event_id, E' \t\n\r\f\v'), '')
  end;
  request_payload jsonb;
  previous_game public.games%rowtype;
  new_pool public.card_pools%rowtype;
  new_event public.events%rowtype;
  previous_payload jsonb := null;
  after_payload jsonb;
  generated_config jsonb;
  effective_config jsonb;
  rarity_lineup jsonb;
  previous_game_exists boolean := false;
  has_plays boolean := false;
  pool_is_ready boolean := false;
  effective_end timestamptz;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
  locked_game_id text;
  locked_pool_id uuid;
  locked_event_id text;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if target_end_now is true then
    if normalized_previous_game_id is null
      or normalized_previous_game_id !~ '^[a-z0-9][a-z0-9-]*$'
    then
      raise exception 'invalid_game_id' using errcode = '22023';
    end if;

    request_payload := jsonb_build_object(
      'game_id', normalized_previous_game_id,
      'end_now', true
    );

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'admin_game_operation:' || target_operation_id::text,
        0
      )
    );

    select audit.actor_id, audit.action, audit.target, audit.diff
      into existing_actor_id, existing_action, existing_target, existing_diff
    from public.audit_log as audit
    where audit.id = target_operation_id;

    if found then
      if existing_actor_id = actor_id
        and existing_action = 'admin.game.ended'
        and existing_target = 'games:' || normalized_previous_game_id
        and existing_diff -> 'request' = request_payload
      then
        return normalized_previous_game_id;
      end if;

      raise exception 'operation_conflict' using errcode = '23505';
    end if;

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'admin_game:' || normalized_previous_game_id,
        0
      )
    );

    select game.*
      into previous_game
    from public.games as game
    where game.id = normalized_previous_game_id
    for update;

    if not found then
      raise exception 'game_not_found' using errcode = 'P0002';
    end if;

    if previous_game.type is distinct from 'marble_roulette'
      or previous_game.config #>> '{variant,kind}' is distinct from 'card'
      or previous_game.config ->> 'marbleCount' is distinct from '10'
      or previous_game.reward_pool_id is null
    then
      raise exception 'game_variant_read_only' using errcode = '23514';
    end if;

    effective_end := statement_timestamp();

    if effective_end <= previous_game.active_from
      or (
        previous_game.active_to is not null
        and effective_end >= previous_game.active_to
      )
    then
      raise exception 'game_not_active' using errcode = '55000';
    end if;

    previous_payload := jsonb_build_object(
      'id', previous_game.id,
      'type', previous_game.type,
      'title', previous_game.title,
      'event_id', previous_game.event_id,
      'config', previous_game.config,
      'reward_pool_id', previous_game.reward_pool_id,
      'per_user_daily_limit', previous_game.per_user_daily_limit,
      'active_from', previous_game.active_from,
      'active_to', previous_game.active_to
    );

    update public.games
    set active_to = effective_end
    where id = normalized_previous_game_id;

    after_payload := previous_payload || jsonb_build_object('active_to', effective_end);

    insert into public.audit_log (id, actor_id, action, target, diff)
    values (
      target_operation_id,
      actor_id,
      'admin.game.ended',
      'games:' || normalized_previous_game_id,
      jsonb_build_object(
        'request', request_payload,
        'before', previous_payload,
        'after', after_payload
      )
    );

    return normalized_previous_game_id;
  end if;

  if normalized_game_id is null
    or normalized_game_id !~ '^[a-z0-9][a-z0-9-]*$'
    or (
      normalized_previous_game_id is not null
      and normalized_previous_game_id !~ '^[a-z0-9][a-z0-9-]*$'
    )
  then
    raise exception 'invalid_game_id' using errcode = '22023';
  end if;

  if normalized_title is null then
    raise exception 'invalid_game_title' using errcode = '22023';
  end if;

  if target_per_user_daily_limit is null
    or target_per_user_daily_limit not between 1 and 100
  then
    raise exception 'invalid_game_daily_limit' using errcode = '22023';
  end if;

  if target_active_from is null then
    raise exception 'invalid_game_active_from' using errcode = '22004';
  end if;

  if target_active_to is not null and target_active_to <= target_active_from then
    raise exception 'invalid_game_active_window' using errcode = '23514';
  end if;

  if target_reward_pool_id is null then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  request_payload := jsonb_build_object(
    'previous_game_id', normalized_previous_game_id,
    'game_id', normalized_game_id,
    'title', normalized_title,
    'reward_pool_id', target_reward_pool_id,
    'event_id', normalized_event_id,
    'per_user_daily_limit', target_per_user_daily_limit,
    'active_from', target_active_from,
    'active_to', target_active_to,
    'end_now', false
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_game_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.game.upserted'
      and existing_target = 'games:' || normalized_game_id
      and existing_diff -> 'request' = request_payload
    then
      return normalized_game_id;
    end if;

    raise exception 'operation_conflict' using errcode = '23505';
  end if;

  -- A->B and B->A renames take identical advisory locks in lexical order.
  for locked_game_id in
    select distinct locked.id
    from unnest(array[normalized_previous_game_id, normalized_game_id]::text[])
      as locked(id)
    where locked.id is not null
    order by locked.id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('admin_game:' || locked_game_id, 0)
    );
  end loop;

  if normalized_previous_game_id is null then
    perform 1
    from public.games as game
    where game.id = normalized_game_id
    for update;

    if found then
      raise exception 'game_id_conflict' using errcode = '23505';
    end if;
  else
    select game.*
      into previous_game
    from public.games as game
    where game.id = normalized_previous_game_id
    for update;

    if not found then
      raise exception 'game_not_found' using errcode = 'P0002';
    end if;

    previous_game_exists := true;

    if previous_game.type is distinct from 'marble_roulette'
      or previous_game.config #>> '{variant,kind}' is distinct from 'card'
      or previous_game.config ->> 'marbleCount' is distinct from '10'
      or previous_game.reward_pool_id is null
    then
      raise exception 'game_variant_read_only' using errcode = '23514';
    end if;

    if normalized_game_id is distinct from normalized_previous_game_id then
      perform 1
      from public.games as game
      where game.id = normalized_game_id
      for update;

      if found then
        raise exception 'game_id_conflict' using errcode = '23505';
      end if;
    end if;

    -- This separate statement runs after the row lock wait, so a concurrent
    -- play committed ahead of us is visible before any immutable mutation.
    select exists (
      select 1
      from public.game_plays as game_play
      where game_play.game_id = normalized_previous_game_id
    ) into has_plays;

    if has_plays and (
      normalized_game_id is distinct from previous_game.id
      or target_reward_pool_id is distinct from previous_game.reward_pool_id
      or normalized_event_id is distinct from previous_game.event_id
    ) then
      raise exception 'game_catalog_locked' using errcode = '23514';
    end if;
  end if;

  -- Pool rows are shared in a stable order. This serializes both play/runtime
  -- reads and pool-window mutations with the same catalog snapshot.
  for locked_pool_id in
    select distinct locked.id
    from unnest(array[
      case when previous_game_exists then previous_game.reward_pool_id else null end,
      target_reward_pool_id
    ]::uuid[]) as locked(id)
    where locked.id is not null
    order by locked.id
  loop
    perform 1
    from public.card_pools as pool
    where pool.id = locked_pool_id
    for share;
  end loop;

  select pool.*
    into new_pool
  from public.card_pools as pool
  where pool.id = target_reward_pool_id;

  if not found then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  if new_pool.active_to is not null
    and statement_timestamp() >= new_pool.active_to
  then
    raise exception 'reward_pool_not_ready' using errcode = '55000';
  end if;

  select
    count(*) = 5
    and coalesce(sum(pool_odd.probability), 0) = 1
    and coalesce(bool_and(pool_odd.probability between 0 and 1), false)
    and not exists (
      select 1
      from public.pool_odds as positive_odd
      where positive_odd.pool_id = target_reward_pool_id
        and positive_odd.probability > 0
        and not exists (
          select 1
          from public.cards as card
          where card.pool_id = target_reward_pool_id
            and card.rarity = positive_odd.rarity
        )
    )
    into pool_is_ready
  from public.pool_odds as pool_odd
  where pool_odd.pool_id = target_reward_pool_id;

  if not pool_is_ready then
    raise exception 'reward_pool_not_ready' using errcode = '55000';
  end if;

  if new_pool.active_from > target_active_from
    or (target_active_to is null and new_pool.active_to is not null)
    or (
      target_active_to is not null
      and new_pool.active_to is not null
      and new_pool.active_to < target_active_to
    )
  then
    raise exception 'game_pool_window_not_covered' using errcode = '23514';
  end if;

  -- Existing and requested events are shared in lexical order. FOR SHARE is
  -- required because IP/mode updates do not necessarily change key columns.
  for locked_event_id in
    select distinct locked.id
    from unnest(array[
      case when previous_game_exists then previous_game.event_id else null end,
      normalized_event_id
    ]::text[]) as locked(id)
    where locked.id is not null
    order by locked.id
  loop
    perform 1
    from public.events as event
    where event.id = locked_event_id
    for share;
  end loop;

  if normalized_event_id is not null then
    select event.*
      into new_event
    from public.events as event
    where event.id = normalized_event_id;

    if not found then
      raise exception 'event_not_found' using errcode = 'P0002';
    end if;

    if new_event.ip_id is distinct from new_pool.ip_id then
      raise exception 'game_event_ip_mismatch' using errcode = '23514';
    end if;

    if new_event.mode is distinct from '온라인' then
      raise exception 'game_event_mode_invalid' using errcode = '23514';
    end if;
  end if;

  -- Hamilton/largest-remainder allocation. Equal remainders and the final
  -- cosmetic lineup both use the public.rarity enum order N,R,SR,SSR,HOLO.
  with slot_share as (
    select
      pool_odd.rarity,
      floor(pool_odd.probability * 10)::integer as base_slots,
      pool_odd.probability * 10 - floor(pool_odd.probability * 10) as remainder
    from public.pool_odds as pool_odd
    where pool_odd.pool_id = target_reward_pool_id
  ),
  ranked_share as (
    select
      slot_share.*,
      row_number() over (
        order by slot_share.remainder desc, slot_share.rarity
      ) as remainder_rank,
      10 - sum(slot_share.base_slots) over () as remaining_slots
    from slot_share
  ),
  expanded_slot as (
    select ranked_share.rarity, generated.slot
    from ranked_share
    cross join lateral generate_series(
      1,
      ranked_share.base_slots
        + case
            when ranked_share.remainder_rank <= ranked_share.remaining_slots then 1
            else 0
          end
    ) as generated(slot)
  )
  select jsonb_agg(to_jsonb(expanded_slot.rarity::text)
    order by expanded_slot.rarity, expanded_slot.slot)
    into rarity_lineup
  from expanded_slot;

  generated_config := jsonb_build_object(
    'marbleCount', 10,
    'variant', jsonb_build_object(
      'kind', 'card',
      'rarityLineup', rarity_lineup
    )
  );

  if previous_game_exists then
    previous_payload := jsonb_build_object(
      'id', previous_game.id,
      'type', previous_game.type,
      'title', previous_game.title,
      'event_id', previous_game.event_id,
      'config', previous_game.config,
      'reward_pool_id', previous_game.reward_pool_id,
      'per_user_daily_limit', previous_game.per_user_daily_limit,
      'active_from', previous_game.active_from,
      'active_to', previous_game.active_to
    );
  end if;

  effective_config := case
    when has_plays then previous_game.config
    else generated_config
  end;

  if previous_game_exists then
    update public.games
    set
      id = normalized_game_id,
      type = 'marble_roulette',
      title = normalized_title,
      event_id = normalized_event_id,
      config = effective_config,
      reward_pool_id = target_reward_pool_id,
      per_user_daily_limit = target_per_user_daily_limit,
      active_from = target_active_from,
      active_to = target_active_to
    where id = normalized_previous_game_id;
  else
    insert into public.games (
      id,
      type,
      title,
      event_id,
      config,
      reward_pool_id,
      per_user_daily_limit,
      active_from,
      active_to
    )
    values (
      normalized_game_id,
      'marble_roulette',
      normalized_title,
      normalized_event_id,
      effective_config,
      target_reward_pool_id,
      target_per_user_daily_limit,
      target_active_from,
      target_active_to
    );
  end if;

  after_payload := jsonb_build_object(
    'id', normalized_game_id,
    'type', 'marble_roulette',
    'title', normalized_title,
    'event_id', normalized_event_id,
    'config', effective_config,
    'reward_pool_id', target_reward_pool_id,
    'per_user_daily_limit', target_per_user_daily_limit,
    'active_from', target_active_from,
    'active_to', target_active_to
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.game.upserted',
    'games:' || normalized_game_id,
    jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return normalized_game_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_inquiry_reply_template(target_template_id uuid, target_title text, target_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_title text := btrim(coalesce(target_title, ''));
  v_body text := btrim(coalesce(target_body, ''));
  v_id uuid := coalesce(target_template_id, extensions.gen_random_uuid());
begin
  if v_actor is null or not public.is_staff() then
    raise insufficient_privilege using message = 'staff_required';
  end if;
  if char_length(v_title) not between 1 and 40 then
    raise invalid_parameter_value using message = 'invalid_template_title';
  end if;
  if char_length(v_body) not between 1 and 2000 then
    raise invalid_parameter_value using message = 'invalid_template_body';
  end if;

  insert into public.inquiry_reply_templates (id, title, body, created_by)
  values (v_id, v_title, v_body, v_actor)
  on conflict (id) do update set
    title = excluded.title,
    body = excluded.body;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_order_dispatch_delay(p_order_id uuid, p_reason text, p_expected_ship_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_status public.order_status;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  perform private.require_operator_capability('sales.manage',false);

  if v_actor is null or not public.has_operator_capability('sales.manage',false) then
    raise insufficient_privilege using message = 'staff required';
  end if;

  select orders.status into v_status
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise no_data_found using message = 'order_not_found';
  end if;

  -- 발송 전 주문에만 붙는 메모다. 이미 나간 주문의 "지연 사유"는 기록이 아니라 혼선이다.
  if v_status not in ('paid', 'confirmed') then
    raise check_violation using message = 'order_already_dispatched';
  end if;

  if v_reason is null then
    delete from public.order_dispatch_delays where order_id = p_order_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_actor,
      'admin.order.dispatch_delay_cleared',
      'order:' || p_order_id::text,
      jsonb_build_object('status', v_status::text)
    );
    return;
  end if;

  insert into public.order_dispatch_delays (order_id, reason, expected_ship_date, noted_by)
  values (p_order_id, v_reason, p_expected_ship_date, v_actor)
  on conflict (order_id) do update set
    reason = excluded.reason,
    expected_ship_date = excluded.expected_ship_date,
    noted_by = excluded.noted_by;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_actor,
    'admin.order.dispatch_delay_noted',
    'order:' || p_order_id::text,
    jsonb_build_object(
      'reason', v_reason,
      'expectedShipDate', p_expected_ship_date,
      'status', v_status::text
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_reward_policy_unguarded(target_operation_id uuid, target_policy_id uuid, target_pool_id uuid, target_trigger text, target_ip_id text, target_good_id text, target_min_amount bigint, target_tickets_per_grant integer, target_active boolean, target_active_from timestamp with time zone, target_active_to timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_trigger text := btrim(target_trigger, E' \t\n\r\f\v');
  normalized_ip_id text := btrim(target_ip_id, E' \t\n\r\f\v');
  normalized_good_id text := case
    when target_good_id is null then null
    else btrim(target_good_id, E' \t\n\r\f\v')
  end;
  request_payload jsonb;
  previous_policy public.reward_policies%rowtype;
  previous_payload jsonb := null;
  after_payload jsonb;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if target_policy_id is null then
    raise exception 'invalid_reward_policy_id' using errcode = '22004';
  end if;

  if target_pool_id is null then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  if normalized_trigger is distinct from 'order_paid' then
    raise exception 'invalid_reward_trigger' using errcode = '22023';
  end if;

  if normalized_ip_id is null or normalized_ip_id = '' then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  if normalized_good_id = '' then
    raise exception 'good_not_found' using errcode = 'P0002';
  end if;

  if target_min_amount is null or target_min_amount < 0 then
    raise exception 'invalid_min_amount' using errcode = '22023';
  end if;

  if target_tickets_per_grant is null
    or target_tickets_per_grant not between 1 and 100
  then
    raise exception 'invalid_tickets_per_grant' using errcode = '22023';
  end if;

  if target_active is null then
    raise exception 'invalid_reward_policy_active' using errcode = '22004';
  end if;

  if target_active_from is null then
    raise exception 'invalid_reward_policy_active_from' using errcode = '22004';
  end if;

  if target_active_to is not null and target_active_to <= target_active_from then
    raise exception 'invalid_reward_policy_active_window' using errcode = '23514';
  end if;

  request_payload := jsonb_build_object(
    'pool_id', target_pool_id,
    'trigger', normalized_trigger,
    'target_ip_id', normalized_ip_id,
    'target_good_id', normalized_good_id,
    'min_amount', target_min_amount,
    'tickets_per_grant', target_tickets_per_grant,
    'active', target_active,
    'active_from', target_active_from,
    'active_to', target_active_to
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'admin_reward_policy_operation:' || target_operation_id::text,
      0
    )
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.reward_policy.upserted'
      and existing_target = 'reward_policies:' || target_policy_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_policy_id;
    end if;

    raise exception 'operation_conflict' using errcode = '23505';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_reward_policy:' || target_policy_id::text, 0)
  );

  select reward_policy.*
    into previous_policy
  from public.reward_policies as reward_policy
  where reward_policy.id = target_policy_id
  for update;

  if found then
    previous_payload := jsonb_build_object(
      'id', previous_policy.id,
      'pool_id', previous_policy.pool_id,
      'trigger', previous_policy.trigger,
      'target_ip_id', previous_policy.target_ip_id,
      'target_good_id', previous_policy.target_good_id,
      'min_amount', previous_policy.min_amount,
      'tickets_per_grant', previous_policy.tickets_per_grant,
      'active', previous_policy.active,
      'active_from', previous_policy.active_from,
      'active_to', previous_policy.active_to
    );

    update public.reward_policies
    set
      pool_id = target_pool_id,
      trigger = normalized_trigger,
      target_ip_id = normalized_ip_id,
      target_good_id = normalized_good_id,
      min_amount = target_min_amount,
      tickets_per_grant = target_tickets_per_grant,
      active = target_active,
      active_from = target_active_from,
      active_to = target_active_to
    where id = target_policy_id;
  else
    insert into public.reward_policies (
      id,
      pool_id,
      trigger,
      target_ip_id,
      target_good_id,
      min_amount,
      tickets_per_grant,
      active,
      active_from,
      active_to
    )
    values (
      target_policy_id,
      target_pool_id,
      normalized_trigger,
      normalized_ip_id,
      normalized_good_id,
      target_min_amount,
      target_tickets_per_grant,
      target_active,
      target_active_from,
      target_active_to
    );
  end if;

  after_payload := jsonb_build_object(
    'id', target_policy_id,
    'pool_id', target_pool_id,
    'trigger', normalized_trigger,
    'target_ip_id', normalized_ip_id,
    'target_good_id', normalized_good_id,
    'min_amount', target_min_amount,
    'tickets_per_grant', target_tickets_per_grant,
    'active', target_active,
    'active_from', target_active_from,
    'active_to', target_active_to
  );

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.reward_policy.upserted',
    'reward_policies:' || target_policy_id::text,
    jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_policy_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_ticket_type(target_operation_id uuid, target_ticket_type_id uuid, target_event_id text, target_name text, target_price integer, target_capacity integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  normalized_event_id text := btrim(target_event_id, E' \t\n\r\f\v');
  normalized_name text := btrim(target_name, E' \t\n\r\f\v');
  request_payload jsonb;
  previous_ticket_type public.ticket_types%rowtype;
  previous_payload jsonb := null;
  after_payload jsonb;
  ticket_type_exists boolean := false;
  has_ticket_history boolean := false;
  existing_actor_id uuid;
  existing_action text;
  existing_target text;
  existing_diff jsonb;
begin
  perform private.require_operator_capability('platform.manage',false);

  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not public.has_operator_capability('platform.manage',false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'invalid_operation_id' using errcode = '22004';
  end if;

  if target_ticket_type_id is null then
    raise exception 'invalid_ticket_type_id' using errcode = '22004';
  end if;

  if normalized_event_id is null or normalized_event_id = '' then
    raise exception 'event_not_found' using errcode = 'P0002';
  end if;

  if normalized_name is null or normalized_name = '' then
    raise exception 'invalid_ticket_type_name' using errcode = '22023';
  end if;

  if target_price is null or target_price < 0 then
    raise exception 'invalid_ticket_type_price' using errcode = '22023';
  end if;

  if target_capacity is null or target_capacity < 0 then
    raise exception 'invalid_ticket_type_capacity' using errcode = '22023';
  end if;

  request_payload := jsonb_build_object(
    'event_id', normalized_event_id,
    'name', normalized_name,
    'price', target_price,
    'capacity', target_capacity
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_ticket_type_operation:' || target_operation_id::text, 0)
  );

  select audit.actor_id, audit.action, audit.target, audit.diff
    into existing_actor_id, existing_action, existing_target, existing_diff
  from public.audit_log as audit
  where audit.id = target_operation_id;

  if found then
    if existing_actor_id = actor_id
      and existing_action = 'admin.ticket_type.upserted'
      and existing_target = 'ticket_types:' || target_ticket_type_id::text
      and existing_diff -> 'request' = request_payload
    then
      return target_ticket_type_id;
    end if;

    raise exception 'operation_conflict' using errcode = '23505';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('admin_ticket_type:' || target_ticket_type_id::text, 0)
  );

  perform 1
  from public.events
  where id = normalized_event_id
  for key share;

  if not found then
    raise exception 'event_not_found' using errcode = 'P0002';
  end if;

  select ticket_type.*
    into previous_ticket_type
  from public.ticket_types as ticket_type
  where ticket_type.id = target_ticket_type_id
  for update;

  ticket_type_exists := found;

  if ticket_type_exists then
    if target_capacity < previous_ticket_type.sold then
      raise exception 'capacity_below_sold' using errcode = '23514';
    end if;

    select exists (
      select 1
      from public.tickets as ticket
      where ticket.ticket_type_id = target_ticket_type_id
    ) into has_ticket_history;

    if has_ticket_history and (
      previous_ticket_type.event_id is distinct from normalized_event_id
      or previous_ticket_type.name is distinct from normalized_name
      or previous_ticket_type.price is distinct from target_price
    ) then
      raise exception 'ticket_type_catalog_locked' using errcode = '23514';
    end if;

    previous_payload := jsonb_build_object(
      'event_id', previous_ticket_type.event_id,
      'name', previous_ticket_type.name,
      'price', previous_ticket_type.price,
      'capacity', previous_ticket_type.capacity,
      'sold', previous_ticket_type.sold
    );

    update public.ticket_types
    set event_id = normalized_event_id,
        name = normalized_name,
        price = target_price,
        capacity = target_capacity
    where id = target_ticket_type_id;

    after_payload := jsonb_build_object(
      'event_id', normalized_event_id,
      'name', normalized_name,
      'price', target_price,
      'capacity', target_capacity,
      'sold', previous_ticket_type.sold
    );
  else
    insert into public.ticket_types (id, event_id, name, price, capacity)
    values (
      target_ticket_type_id,
      normalized_event_id,
      normalized_name,
      target_price,
      target_capacity
    );

    after_payload := jsonb_build_object(
      'event_id', normalized_event_id,
      'name', normalized_name,
      'price', target_price,
      'capacity', target_capacity,
      'sold', 0
    );
  end if;

  insert into public.audit_log (id, actor_id, action, target, diff)
  values (
    target_operation_id,
    actor_id,
    'admin.ticket_type.upserted',
    'ticket_types:' || target_ticket_type_id::text,
    jsonb_build_object(
      'request', request_payload,
      'before', previous_payload,
      'after', after_payload
    )
  );

  return target_ticket_type_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_use_stock_supply(p_good_id text, p_variant_id uuid, p_expected_policy_id uuid, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); variant public.goods_variants; policy private.goods_preorder_policies;
begin
  perform private.require_operator_capability('platform.manage',true);

  if actor is null or not coalesce(public.has_operator_capability('platform.manage',true),false) or not exists(select 1 from public.profiles where id=actor and private.has_operator_capability(id,'platform.manage',true)) then
    raise insufficient_privilege using message='preorder_admin_required';
  end if;
  perform 1 from public.goods where id=p_good_id and archived_at is null for update;
  if not found then raise no_data_found using message='good_not_found'; end if;
  select * into variant from public.goods_variants where id=p_variant_id and good_id=p_good_id for update;
  if not found then raise no_data_found using message='goods_variant_not_found'; end if;
  if variant.preorder_policy_id is null and p_expected_policy_id is null then return jsonb_build_object('changed',false); end if;
  if variant.preorder_policy_id is distinct from p_expected_policy_id then raise sqlstate 'PT409' using message='preorder_policy_changed'; end if;
  select * into policy from private.goods_preorder_policies where id=variant.preorder_policy_id for update;
  if policy.revision is distinct from p_expected_revision then raise sqlstate 'PT409' using message='preorder_policy_changed'; end if;
  if policy.state<>'stopped' then raise check_violation using message='stop_preorder_before_stock_supply'; end if;
  if exists(select 1 from private.goods_preorder_reservations reservation join private.goods_preorder_policies source on source.id=reservation.policy_id
    where source.variant_id=variant.id and reservation.state='reserved') then raise check_violation using message='preorder_allocations_pending'; end if;
  update public.goods_variants set preorder_policy_id=null where id=variant.id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.good.stock_supply_selected','goods:'||p_good_id,
    jsonb_build_object('variantId',variant.id,'previousPolicyId',policy.id));
  return jsonb_build_object('changed',true);
end $function$

CREATE OR REPLACE FUNCTION public.admin_view_bank_transfer_refund_account(p_order_id uuid, p_claim_id uuid, p_view_id uuid, p_expected_revision integer, p_expected_actor_id uuid, p_expected_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare purchase public.orders;claim public.order_cancellation_requests;account private.claim_refund_accounts;blocker text;happened timestamptz;
begin
 perform private.lock_bank_transfer_refund_identity(p_order_id,p_claim_id,p_expected_actor_id,p_expected_session_id);
 if p_view_id is null or p_expected_revision is null or p_expected_revision<0 then raise invalid_parameter_value using message='invalid_bank_refund_operation';end if;
 select * into purchase from public.orders where id=p_order_id for update;
 perform id from public.order_shipments where order_id=p_order_id order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id and order_id=p_order_id for update;
 if not found then raise sqlstate 'PT404' using message='claim_not_found';end if;
 if claim.claim_revision<>p_expected_revision then raise sqlstate 'PT409' using message='claim_changed';end if;
 perform id from public.payments where purpose='order' and ref_id=p_order_id order by id for update;
 perform r.id from public.refunds r join public.payments p on p.id=r.payment_id where p.purpose='order' and p.ref_id=p_order_id order by r.id for update of r;
 select * into account from private.claim_refund_accounts where claim_id=claim.id for share;
 blocker:=private.bank_transfer_refund_blocker(claim,purchase,'view_account');
 if blocker is not null then raise check_violation using message=blocker;end if;
 happened:=clock_timestamp();
 -- No account data enters the audit payload or durable response receipts. A
 -- duplicate view UUID is rejected rather than returning a cached plaintext.
 insert into private.bank_transfer_refund_account_views(id,actor_id,session_id,order_id,claim_id,created_at)
 values(p_view_id,p_expected_actor_id,p_expected_session_id,p_order_id,p_claim_id,happened);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_view_id,p_expected_actor_id,'admin.order.bank_refund_account_viewed','order:'||p_order_id,
  jsonb_build_object('claimId',p_claim_id,'purpose','prepare_bank_transfer','revision',p_expected_revision));
 perform set_config('response.headers','[{"Cache-Control":"no-store, private"},{"Pragma":"no-cache"}]',true);
 return jsonb_build_object('viewId',p_view_id,'actorId',p_expected_actor_id,'orderId',p_order_id,'claimId',p_claim_id,'revision',p_expected_revision,
  'bankName',account.bank_name,'accountNumber',account.account_number,'accountHolder',account.account_holder,'viewedAt',happened);
end $function$

CREATE OR REPLACE FUNCTION public.admin_view_order_partial_cancellation_refund_account(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_session uuid; head private.order_partial_cancellations; account private.order_partial_cancellation_refund_accounts;
begin
  begin v_session := (auth.jwt()->>'session_id')::uuid;
  exception when invalid_text_representation then raise insufficient_privilege using message = 'bank_refund_permission_required'; end;
  perform private.require_bank_transfer_refund_identity(v_actor, v_session);
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  if head.state <> 'awaiting_transfer' then raise check_violation using message = 'partial_cancel_not_awaiting_transfer'; end if;
  select * into account from private.order_partial_cancellation_refund_accounts where partial_cancellation_id = p_id;
  if not found or account.purged_at is not null then raise no_data_found using message = 'partial_cancel_refund_account_missing'; end if;
  insert into public.audit_log(actor_id, action, target, diff)
  values (v_actor, 'admin.order.partial_cancellation_account_viewed', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'maskedAccount', account.masked_account));
  return jsonb_build_object('bankName', account.bank_name, 'accountNumber', account.account_number, 'accountHolder', account.account_holder,
    'amount', head.refund_amount);
end $function$

CREATE OR REPLACE FUNCTION public.admin_waive_order_claim_collection(p_claim_id uuid, p_shipment_id uuid, p_waiver jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid());reason text;evidence uuid[];order_key uuid;order_state public.order_status;
 claim public.order_cancellation_requests;decision public.order_claim_collection_waivers;target record;replayed boolean:=false;at_value timestamptz:=clock_timestamp();
begin
 perform private.require_operator_capability('sales.manage',false);
 if actor is null or not public.has_operator_capability('sales.manage',false) then raise insufficient_privilege using message='staff required';end if;
 if p_claim_id is null or p_shipment_id is null then raise check_violation using message='reshipment_shipment_not_found';end if;
 select v.reason,v.evidence into reason,evidence from private.claim_collection_waiver_values(p_waiver) v;
 select order_id into order_key from public.order_cancellation_requests where id=p_claim_id;
 if not found then raise no_data_found using message='claim_not_found';end if;
 select status into order_state from public.orders where id=order_key for update;
 perform 1 from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id for update;
 if claim.claim_type<>'exchange' then raise exception using message='claim_type_has_no_reshipment';end if;
 select * into decision from public.order_claim_collection_waivers where claim_id=p_claim_id and shipment_id=p_shipment_id;
 if found then
  if decision.reason<>reason or decision.evidence_file_ids<>evidence then raise unique_violation using message='collection_waiver_conflict';end if;
  replayed:=true;
 else
  if claim.stage not in('collecting','collected') or order_state not in('shipping','delivered','done')
   or exists(select 1 from public.order_cancellation_claims where order_id=order_key) then
   raise exception using message='claim_not_reshippable';end if;
  if exists(select 1 from public.order_claim_reshipments where claim_id=p_claim_id and shipment_id=p_shipment_id) then
   raise unique_violation using message='reshipment_conflict';end if;
  decision:=private.record_claim_collection_waiver(claim,p_shipment_id,reason,evidence,actor,at_value);
  update public.order_cancellation_requests set updated_at=at_value where id=p_claim_id;
  insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.order.claim_collection_waived','order:'||order_key::text,
   jsonb_build_object('claimId',p_claim_id,'claimType','exchange','shipmentId',p_shipment_id,
    'originName',(select origin_name_snapshot from public.order_claim_collections where claim_id=p_claim_id and shipment_id=p_shipment_id),
    'waiverReason',reason,'evidenceFileIds',to_jsonb(evidence)));
 end if;
 perform private.complete_order_claim_collection(p_claim_id,'collection_waiver_decided');
 select * into target from private.claim_reshipment_targets(p_claim_id) t where t.shipment_id=p_shipment_id;
 return jsonb_build_object('claimId',p_claim_id,'shipmentId',p_shipment_id,'waivedAt',decision.waived_at,'replayed',replayed,
  'productionPending',exists(select 1 from public.order_items i where i.id=any(target.item_ids) and i.production_terms_snapshot is not null
   and not exists(select 1 from private.order_production_jobs j where j.order_item_id=i.id and j.claim_id=p_claim_id and j.state='completed')));
end $function$

CREATE OR REPLACE FUNCTION public.append_inquiry_message(target_inquiry_id uuid, target_body text, target_image_paths text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_body text := btrim(coalesce(target_body, ''));
  v_paths text[];
  v_status text;
  v_message_id uuid;
begin
  if v_actor is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;
  if char_length(v_body)>2000 or (v_body='' and cardinality(coalesce(target_image_paths,'{}'))=0) then
    raise invalid_parameter_value using message = 'invalid_inquiry_body';
  end if;

  select thread.status
  into v_status
  from public.inquiries as thread
  where thread.id = target_inquiry_id
    and thread.user_id = v_actor
  for update;

  if not found then
    raise no_data_found using message = 'inquiry_not_found';
  end if;

  -- 종결 후 재문의는 새 스레드다. 닫힌 대화를 되살리면 어드민 큐의 처리 이력과
  -- 자동 종결 기준(마지막 답변 시각)이 한 행 안에서 여러 번 뒤집힌다.
  -- 정지 회원은 계정 문의(탈퇴 요청·정지 문의)에만 글로 이어 쓴다.
  if exists (select 1 from public.profiles as profile where profile.id = v_actor and profile.suspended_at is not null) then
    if (select thread.category from public.inquiries as thread where thread.id = target_inquiry_id) <> 'account' then
      raise insufficient_privilege using message = 'account_suspended';
    end if;
    if cardinality(coalesce(target_image_paths, '{}'::text[])) > 0 then
      raise insufficient_privilege using message = 'account_suspended_inquiry_limited';
    end if;
  end if;

  if v_status = 'closed' then
    raise check_violation using message = 'inquiry_closed';
  end if;

  v_paths := private.assert_own_inquiry_image_paths(target_image_paths, v_actor);
  if v_body='' and exists(select 1 from unnest(v_paths) image(path) where not exists(
    select 1 from storage.objects object where object.bucket_id='user-uploads' and object.name=image.path)) then
    raise check_violation using message='inquiry_image_missing';
  end if;

  insert into public.inquiry_messages (inquiry_id, author, author_id, body, image_paths)
  values (target_inquiry_id, 'user', v_actor, v_body, v_paths)
  returning id into v_message_id;

  update public.inquiries as thread
  set
    status = 'open',
    last_message_at = now()
  where thread.id = target_inquiry_id;

  return v_message_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_cart_coupon_code(p_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); held_id uuid; evaluated record;
begin
  if actor is null then raise insufficient_privilege using message='auth required';end if;
  held_id:=private.claim_coupon_code(p_code,actor);
  select * into evaluated from private.evaluate_user_coupon(held_id,actor,private.cart_subtotal(actor));
  if evaluated.o_reason is not null and evaluated.o_reason not in ('coupon_min_subtotal','coupon_no_eligible_goods') then raise check_violation using message=evaluated.o_reason;end if;
  insert into public.cart_coupon_selections(user_id,user_coupon_id) values(actor,held_id)
    on conflict(user_id) do update set user_coupon_id=excluded.user_coupon_id,created_at=now();
  return held_id;
end $function$

CREATE OR REPLACE FUNCTION public.apply_cart_coupon(p_user_coupon_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user uuid := (select auth.uid());
  v_subtotal bigint;
  v_eval record;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if p_user_coupon_id is null then
    raise check_violation using message = 'coupon_not_owned';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  -- 코드 입력과 같은 계약: 최소 금액 미달만은 선택으로 받아들인다.
  v_subtotal := private.cart_subtotal(v_user);
  select * into v_eval from private.evaluate_user_coupon(p_user_coupon_id, v_user, v_subtotal);
  if v_eval.o_reason is not null and v_eval.o_reason not in ('coupon_min_subtotal','coupon_no_eligible_goods') then
    raise check_violation using message = v_eval.o_reason;
  end if;

  insert into public.cart_coupon_selections (user_id, user_coupon_id)
  values (v_user, p_user_coupon_id)
  on conflict (user_id) do update set
    user_coupon_id = excluded.user_coupon_id,
    created_at = now();
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_order_cancellation_reconciliation_allowed(p_request_id uuid, p_actor_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claim public.order_cancellation_requests;purchase public.orders;order_key uuid;
begin
 -- p_actor_id null = 시스템(서버 자동 발행). 아래에서 취소 유형만 허용한다.
 if p_actor_id is not null then
    perform private.require_actor_operator_capability(p_actor_id,'sales.manage',false);
  end if;
 select order_id into order_key from public.order_cancellation_requests where id=p_request_id;
 if not found then raise no_data_found using message='cancellation_request_not_found'; end if;
 select * into purchase from public.orders where id=order_key for update;
 perform id from public.order_shipments where order_id=order_key order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_request_id for update;
 if p_actor_id is null and claim.claim_type<>'cancel' then
   raise insufficient_privilege using message='staff required'; end if;
 if claim.stage='completed' and purchase.status='canceled' then return 'completed'; end if;
 if claim.stage='on_hold' then raise check_violation using message='claim_on_hold'; end if;
 if claim.claim_type='exchange' or claim.status not in ('processing','needs_review') then
   raise check_violation using message='cancellation_request_not_processing'; end if;
 perform private.assert_claim_collections_complete(p_request_id);
 if claim.claim_type='cancel' and not claim.collection_required and not private.order_cancel_eligible(order_key) then
   raise check_violation using message='order_not_cancelable'; end if;
 if p_actor_id is not null then
  insert into private.operator_cancellation_authorizations(request_id,actor_id)
  values(p_request_id,p_actor_id) on conflict(request_id,actor_id) do nothing;
 end if;
 return 'allowed';
end $function$

CREATE OR REPLACE FUNCTION public.assert_pool_odds_total()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pool_ids uuid[];
  v_pool     uuid;
  v_total    numeric;
begin
  if tg_op = 'INSERT' then
    v_pool_ids := array[new.pool_id];
  elsif tg_op = 'DELETE' then
    v_pool_ids := array[old.pool_id];
  else
    v_pool_ids := array[old.pool_id, new.pool_id];
  end if;

  for v_pool in select distinct pool_id from unnest(v_pool_ids) as changed(pool_id) loop
    if v_pool is null then continue; end if;
    if not exists (select 1 from public.card_pools where id = v_pool) then continue; end if;

    select coalesce(sum(probability), 0) into v_total
      from public.pool_odds where pool_id = v_pool;
    if v_total <> 1 then raise exception 'pool odds must sum to 1'; end if;
  end loop;

  return null;
end; $function$

CREATE OR REPLACE FUNCTION public.attendance_check_in()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := (select auth.uid());
  v_today date;
  v_inserted integer;
  v_balance integer;
begin
  if v_user is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_user
      and profile.suspended_at is not null
  ) then
    raise exception 'account_suspended' using errcode = '55000';
  end if;

  -- 탈퇴 신청으로 쓰기가 봉인된 계정. 적립은 삭제 대상 계정에 새 잔액을 만드는
  -- 일이고, 그 잔액은 교환으로만 빠져나간다 — 봉인 뒤에 새로 생기면 안 된다
  -- (20260813193000 의 계정 fence 관례를 그대로 미러한다).
  if private.is_account_write_fenced(v_user) then
    raise object_not_in_prerequisite_state
      using message = 'account_deletion_write_fenced';
  end if;

  v_today := (now() at time zone 'Asia/Seoul')::date;

  -- 같은 날 두 번째 호출은 아무것도 바꾸지 않는다. 경합하는 두 탭도 PK가
  -- 직렬화한다 — 하나만 원장을 남기고 다른 하나는 already_checked를 받는다.
  insert into public.coin_attendance (user_id, attended_on)
  values (v_user, v_today)
  on conflict (user_id, attended_on) do nothing;

  get diagnostics v_inserted = row_count;

  if v_inserted = 0 then
    select balance into v_balance
    from public.coin_balances
    where user_id = v_user;

    return jsonb_build_object(
      'status', 'already_checked',
      'balance', coalesce(v_balance, 0),
      'attended_on', v_today
    );
  end if;

  insert into public.coin_ledger (user_id, amount, reason, attended_on)
  values (v_user, 1, 'attendance', v_today);

  insert into public.coin_balances (user_id, balance)
  values (v_user, 1)
  on conflict (user_id) do update set
    balance = coin_balances.balance + 1,
    updated_at = now()
  returning balance into v_balance;

  return jsonb_build_object(
    'status', 'checked',
    'balance', v_balance,
    'attended_on', v_today
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_ticket_cancellation_reconcile(p_request_id uuid, p_user_id uuid, p_attempt_token uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order_id uuid;
  v_requested_by uuid;
  v_status text;
  v_attempt_token uuid;
  v_provider_started_at timestamptz;
begin
  if p_attempt_token is null then
    raise not_null_violation using message = 'attempt token required';
  end if;

  select request.ticket_order_id, request.requested_by
  into v_order_id, v_requested_by
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null or p_user_id is null or v_requested_by is distinct from p_user_id then
    raise no_data_found using message = 'ticket cancellation request not found';
  end if;

  perform ticket_order.id
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;

  select request.status, request.attempt_token, request.provider_started_at
  into v_status, v_attempt_token, v_provider_started_at
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id
  for update of request;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket'
    and payment.ref_id = v_order_id
  order by payment.id
  for update of payment;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order_id
  order by ticket.id
  for update of ticket;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id in (
    select ticket.ticket_type_id
    from public.tickets as ticket
    where ticket.ticket_order_id = v_order_id
  )
  order by ticket_type.id
  for update of ticket_type;

  if v_status = 'completed' then
    return 'completed';
  end if;

  if v_status = 'processing' then
    if v_attempt_token = p_attempt_token then
      return 'processing';
    end if;

    if v_attempt_token is not null
      and v_provider_started_at is not null
      and v_provider_started_at > now() - interval '5 minutes'
    then
      return 'in_progress';
    end if;

    update public.ticket_cancellation_requests
    set
      attempt_token = p_attempt_token,
      provider_started_at = now(),
      last_error_code = null
    where id = p_request_id;

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      p_user_id,
      'ticket.cancellation.processing_reclaimed',
      'ticket_order:' || v_order_id::text,
      jsonb_build_object(
        'requestId', p_request_id,
        'from', 'processing',
        'to', 'processing'
      )
    );

    return 'processing';
  end if;

  if v_status not in ('requested', 'needs_review') then
    raise check_violation using message = 'ticket cancellation not reconcilable';
  end if;

  update public.ticket_cancellation_requests
  set
    status = 'processing',
    attempt_token = p_attempt_token,
    provider_started_at = now(),
    last_error_code = null
  where id = p_request_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_user_id,
    'ticket.cancellation.processing',
    'ticket_order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'from', v_status,
      'to', 'processing'
    )
  );

  return 'processing';
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_ticket_payment_approval(p_user_id uuid, p_ticket_order_id uuid, p_payment_key text, p_amount bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order_user_id uuid;
  v_order_total bigint;
  v_order_status public.ticket_order_status;
  v_expires_at timestamptz;
  v_matching_payment_count integer;
  v_existing_payment public.payments%rowtype;
  v_has_existing_payment boolean := false;
begin
  if p_payment_key is null
    or nullif(btrim(p_payment_key), '') is null
    or btrim(p_payment_key) <> p_payment_key
    or length(p_payment_key) > 200
    or p_amount is null
    or p_amount <= 0
  then
    raise check_violation using message = 'invalid payment approval evidence';
  end if;

  select
    ticket_order.user_id,
    ticket_order.total,
    ticket_order.status,
    ticket_order.expires_at
  into
    v_order_user_id,
    v_order_total,
    v_order_status,
    v_expires_at
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;

  if not found or p_user_id is null or v_order_user_id is distinct from p_user_id then
    raise no_data_found using message = 'ticket order not found';
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = p_ticket_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;

  if found then
    raise check_violation using message = 'ticket cancellation in progress';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ticket_payment:' || p_payment_key, 0)
  );

  perform payment.id
  from public.payments as payment
  where (
      payment.purpose = 'ticket'
      and payment.ref_id = p_ticket_order_id
    )
    or payment.idempotency_key = p_payment_key
    or payment.payment_key = p_payment_key
  order by payment.id
  for update of payment;

  select count(*)::integer
  into v_matching_payment_count
  from public.payments as payment
  where payment.idempotency_key = p_payment_key
     or payment.payment_key = p_payment_key;

  if v_matching_payment_count > 1 then
    raise unique_violation using message = 'payment approval conflict';
  end if;

  select payment.*
  into v_existing_payment
  from public.payments as payment
  where payment.idempotency_key = p_payment_key
     or payment.payment_key = p_payment_key;

  v_has_existing_payment := found;

  if p_amount is distinct from v_order_total then
    raise check_violation using message = 'amount mismatch';
  end if;

  if v_has_existing_payment then
    if v_existing_payment.purpose <> 'ticket'
      or v_existing_payment.ref_id is distinct from p_ticket_order_id
      or v_existing_payment.user_id is distinct from p_user_id
      or v_existing_payment.amount is distinct from p_amount
      or v_existing_payment.idempotency_key is distinct from p_payment_key
      or (
        v_existing_payment.payment_key is not null
        and v_existing_payment.payment_key is distinct from p_payment_key
      )
    then
      raise unique_violation using message = 'payment approval conflict';
    end if;
  end if;

  if exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = p_ticket_order_id
      and payment.status in ('pending', 'paid', 'refunded')
      and payment.id is distinct from v_existing_payment.id
  ) then
    raise unique_violation using message = 'payment approval conflict';
  end if;

  if v_has_existing_payment then
    if v_existing_payment.status = 'paid' then
      if v_order_status <> 'paid' then
        raise unique_violation using message = 'payment approval conflict';
      end if;
      return 'already_confirmed';
    end if;

    if v_existing_payment.status = 'refunded' then
      if v_order_status <> 'canceled' then
        raise unique_violation using message = 'payment approval conflict';
      end if;
      return 'already_confirmed';
    end if;

    if v_existing_payment.status <> 'pending' then
      raise check_violation using message = 'payment not payable';
    end if;
  end if;

  if v_order_status <> 'pending' then
    raise check_violation using message = 'ticket order not payable';
  end if;

  if v_expires_at is not null and now() >= v_expires_at then
    raise check_violation using message = 'ticket order expired';
  end if;

  if v_has_existing_payment then
    update public.payments
    set payment_key = p_payment_key
    where id = v_existing_payment.id;
  else
    insert into public.payments (
      user_id,
      purpose,
      ref_id,
      amount,
      status,
      payment_key,
      idempotency_key,
      raw
    )
    values (
      p_user_id,
      'ticket',
      p_ticket_order_id,
      p_amount,
      'pending',
      p_payment_key,
      p_payment_key,
      null
    );
  end if;

  return 'pending';
end;
$function$

CREATE OR REPLACE FUNCTION public.bind_goods_payment_callback_nonce(p_attempt_id uuid, p_callback_nonce_digest text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_attempt public.payment_attempts%rowtype;
begin
  if p_attempt_id is null
    or p_callback_nonce_digest is null
    or p_callback_nonce_digest !~ '^[0-9a-f]{64}$'
  then
    raise invalid_parameter_value using message = 'goods_payment_nonce_invalid';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.purpose = 'order'
  for update;

  if not found or v_attempt.provider not in ('toss', 'korpay', 'nicepay') then
    raise no_data_found using message = 'goods_payment_attempt_not_found';
  end if;

  if v_attempt.state is distinct from 'prepared'
    or v_attempt.expires_at <= pg_catalog.clock_timestamp()
  then
    raise object_not_in_prerequisite_state using message = 'goods_payment_attempt_not_preparable';
  end if;

  if v_attempt.callback_nonce_digest is null then
    update public.payment_attempts
    set callback_nonce_digest = p_callback_nonce_digest
    where id = v_attempt.id;
  elsif v_attempt.callback_nonce_digest is distinct from p_callback_nonce_digest then
    raise unique_violation using message = 'goods_payment_nonce_conflict';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.bind_order_delay_email_intent(target_id uuid, target_claim uuid, target_intent uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t private.order_delay_notice_targets%rowtype;i private.email_intents%rowtype;
begin
 select * into t from private.order_delay_notice_targets where id=target_id for update;
 if not found or t.email_status<>'processing' or t.claim_token is distinct from target_claim or t.lease_until<=now() then return false;end if;
 select * into i from private.email_intents where id=target_intent for update;
 if not found or i.source<>'order_delay_notice' or i.message_kind<>'order_delay_notice' or i.content_revision<>'order_delay_v1'
  or (t.email_intent_id is not null and t.email_intent_id<>i.id) then raise check_violation using message='delay_notice_intent_mismatch';end if;
 update private.order_delay_notice_targets set email_intent_id=i.id where id=t.id;
 -- Committed provider acceptance wins even if the order subsequently ships or the lease response was lost.
 if i.state in ('accepted','sent','delivered','delayed','bounced','complained','suppressed','failed') then return true;end if;
 perform private.lock_order_delay_notice_target(t.order_id,t.shipment_ids);
 if not private.order_delay_notice_target_current(t.id) then
  update private.order_delay_notice_targets set email_status=case when i.attempt_count>0 then 'unknown' else 'suppressed' end,
   error_code='target_changed',available_at=null,retryable=false,claim_token=null,lease_until=null,updated_at=now() where id=t.id;
  insert into public.audit_log(actor_id,action,target,diff) values(null,'system.order.delay_notice_suppressed','delay_notice_target:'||t.id,jsonb_build_object('attempted',i.attempt_count>0));
  return false;
 end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.bind_stock_safety_digest_intent(target_id uuid, target_claim uuid, target_intent uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d private.stock_safety_digest_deliveries%rowtype;i private.email_intents%rowtype;
begin
  select * into d from private.stock_safety_digest_deliveries where id=target_id for update;
  if not found or d.email_status<>'processing' or d.claim_token is distinct from target_claim or d.lease_until<=clock_timestamp() then return false;end if;
  select * into i from private.email_intents where id=target_intent for update;
  if not found or i.source<>'stock_safety_digest' or i.message_kind<>'stock_safety_digest' or i.content_revision<>'stock_safety_digest_v1'
    or (d.email_intent_id is not null and d.email_intent_id<>i.id) then raise check_violation using message='stock_digest_intent_mismatch';end if;
  update private.stock_safety_digest_deliveries set email_intent_id=i.id where id=d.id;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.bind_store_analytics_order(p_token_hash text, p_order_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare session private.store_analytics_sessions; target public.orders; previous private.store_analytics_order_bindings; at_time timestamptz;
begin
 perform private.store_analytics_require_service();
 if p_token_hash is null or p_token_hash!~'^[0-9a-f]{64}$' or p_order_id is null or p_user_id is null then
  raise invalid_parameter_value using message='analytics_invalid_binding';end if;
 -- Account -> settings -> session -> order. The service boundary supplies the
 -- authenticated actor; this argument is never accepted from a browser body.
 perform private.lock_operator_subjects(array[p_user_id]);
 if private.is_account_write_fenced(p_user_id) or not exists(select 1 from public.profiles where id=p_user_id and role='user' and suspended_at is null) then
  raise insufficient_privilege using message='analytics_order_unavailable';end if;
 perform 1 from private.store_analytics_settings where id and enabled for share;
 if not found then return false;end if;
 select * into session from private.store_analytics_sessions where token_hash=p_token_hash for update;
 at_time:=clock_timestamp();
 if not found or session.revoked_at is not null or session.event_count=0
  or at_time>=session.last_seen_at+interval '30 minutes' or at_time>=session.created_at+interval '24 hours'
  or(at_time at time zone 'Asia/Seoul')::date<>(session.created_at at time zone 'Asia/Seoul')::date then return false;end if;
 select * into target from public.orders where id=p_order_id for update;
 if not found or target.user_id<>p_user_id then raise insufficient_privilege using message='analytics_order_unavailable';end if;
 select * into previous from private.store_analytics_order_bindings where order_id=p_order_id;
 if found then
  if previous.session_id<>session.id then raise exception using errcode='PT409',message='analytics_order_binding_conflict';end if;
  return true;
 end if;
 if target.status<>'pending' or target.created_at<session.created_at or target.created_at<at_time-interval '2 minutes'
  or target.payment_method not in ('card','bank_transfer') or target.total<=0 then return false;end if;
 insert into private.store_analytics_order_bindings(order_id,session_id,bound_at,channel,source,medium,link_id,page_kind,page_target)
 values(target.id,session.id,at_time,session.channel,session.source,session.medium,session.last_link_id,session.last_page_kind,session.last_page_target);
 return true;
end $function$

