CREATE OR REPLACE FUNCTION public.block_community_user(target_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := auth.uid();
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if target_user_id = actor_id then
    raise exception 'cannot_block_self' using errcode = '22023';
  end if;

  perform 1
  from public.profiles
  where profiles.id = target_user_id;

  if not found then
    raise exception 'target_not_found' using errcode = '42501';
  end if;

  insert into public.blocks (user_id, blocked_user_id)
  values (actor_id, target_user_id)
  on conflict (user_id, blocked_user_id) do nothing;

  return jsonb_build_object('blockedUserId', target_user_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.change_my_goods_subscription_state(p_expected_actor_id uuid, p_plan_id uuid, p_expected_revision bigint, p_operation_id uuid, p_command text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare actor uuid:=auth.uid();plan private.goods_subscription_plans;cycle_id uuid;request_hash text;result jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id or p_command is null or p_command not in('pause','cancel') then
  raise insufficient_privilege using message='subscription_actor_changed';end if;
 perform private.subscription_lock_actor(actor,false);
 request_hash:=encode(sha256(convert_to(jsonb_build_array(p_expected_revision,p_command)::text,'UTF8')),'hex');
 result:=private.subscription_operation_replay(actor,p_plan_id,p_operation_id,p_command,request_hash);if result is not null then return result;end if;
 select * into plan from private.goods_subscription_plans where id=p_plan_id and owner_id=actor for update;
 if not found then raise no_data_found using message='subscription_not_found';end if;
 if plan.revision is distinct from p_expected_revision or (p_command='pause' and plan.state not in('active','awaiting_first_payment','needs_confirmation')) then
  raise sqlstate 'PT409' using message='subscription_state_changed';end if;
 if plan.state<>'canceled' then
  for cycle_id in select id from private.goods_subscription_cycles where plan_id=p_plan_id and state in('draft','ready','prepared') order by id loop
   perform private.subscription_stop_cycle(cycle_id,case when p_command='cancel' then 'customer_canceled' else 'customer_paused' end,p_command='cancel');
  end loop;
  update private.goods_subscription_plans set state=case when p_command='cancel' then 'canceled' else 'paused' end,
   pause_reason=case when p_command='pause' then 'customer_paused' else null end,canceled_at=case when p_command='cancel' then clock_timestamp() else null end,
   next_run_at=null,revision=revision+1,updated_at=clock_timestamp() where id=p_plan_id returning * into plan;
 end if;
 result:=jsonb_build_object('operationId',p_operation_id,'planId',p_plan_id,'revision',plan.revision,'state',plan.state);
 return private.subscription_record_operation(actor,p_plan_id,p_operation_id,p_command,request_hash,result);
end $function$

CREATE OR REPLACE FUNCTION public.check_in_ticket(p_staff_id uuid, p_qr_token text)
 RETURNS TABLE(result text, checked_at timestamp with time zone, event_id text, event_title text, ticket_type_id uuid, ticket_type_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order_id uuid;
  v_order_status public.ticket_order_status;
  v_ticket_id uuid;
  v_ticket_status public.ticket_status;
  v_ticket_type_id uuid;
  v_event_id text;
  v_event_title text;
  v_ticket_type_name text;
  v_checked_at timestamptz;
begin
  perform private.require_actor_operator_capability(p_staff_id,'platform.manage',false);

  if p_staff_id is null or not exists (
    select 1
    from public.profiles as profile
    where profile.id = p_staff_id
      and profile.role in ('staff', 'admin')
  ) then
    raise insufficient_privilege using message = 'staff access required';
  end if;

  if p_qr_token is null or p_qr_token !~ '^[0-9a-f]{32}$' then
    raise check_violation using message = 'invalid qr token';
  end if;

  -- QR lookup 자체는 잠그지 않는다. order 잠금이 검표·취소의 직렬화 기준이다.
  select ticket.id, ticket.ticket_order_id
  into v_ticket_id, v_order_id
  from public.tickets as ticket
  where ticket.qr_token = p_qr_token;

  if not found then
    return query
    select
      'not_found'::text,
      null::timestamptz,
      null::text,
      null::text,
      null::uuid,
      null::text;
    return;
  end if;

  select ticket_order.status
  into v_order_status
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;

  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = v_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;

  if found then
    raise check_violation using message = 'ticket cancellation in progress';
  end if;

  select
    ticket.status,
    ticket.ticket_type_id,
    ticket_type.event_id,
    event.title,
    ticket_type.name
  into
    v_ticket_status,
    v_ticket_type_id,
    v_event_id,
    v_event_title,
    v_ticket_type_name
  from public.tickets as ticket
  join public.ticket_types as ticket_type on ticket_type.id = ticket.ticket_type_id
  join public.events as event on event.id = ticket_type.event_id
  where ticket.id = v_ticket_id
    and ticket.ticket_order_id = v_order_id
    and ticket.qr_token = p_qr_token
  for update of ticket;

  if not found then
    raise check_violation using message = 'ticket changed during check-in';
  end if;

  if v_ticket_status = 'valid' then
    if v_order_status <> 'paid' then
      raise check_violation using message = 'ticket order not paid';
    end if;

    v_checked_at := clock_timestamp();

    update public.tickets
    set status = 'used'
    where id = v_ticket_id;

    insert into public.check_ins (ticket_id, checked_at, by_staff)
    values (v_ticket_id, v_checked_at, p_staff_id);

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      p_staff_id,
      'admin.ticket.checked_in',
      format('tickets:%s', v_ticket_id),
      jsonb_build_object(
        'before', jsonb_build_object('status', 'valid'),
        'after', jsonb_build_object('status', 'used')
      )
    );

    return query
    select
      'checked_in'::text,
      v_checked_at,
      v_event_id,
      v_event_title,
      v_ticket_type_id,
      v_ticket_type_name;
    return;
  end if;

  if v_ticket_status = 'used' then
    select check_in.checked_at
    into v_checked_at
    from public.check_ins as check_in
    where check_in.ticket_id = v_ticket_id;

    if not found then
      raise check_violation using message = 'used ticket check-in ledger missing';
    end if;

    return query
    select
      'already_used'::text,
      v_checked_at,
      v_event_id,
      v_event_title,
      v_ticket_type_id,
      v_ticket_type_name;
    return;
  end if;

  if v_ticket_status = 'refunded' then
    return query
    select
      'refunded'::text,
      null::timestamptz,
      v_event_id,
      v_event_title,
      v_ticket_type_id,
      v_ticket_type_name;
    return;
  end if;

  raise check_violation using message = 'unsupported ticket status';
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_adult_verification_callback(p_callback_nonce_digest text, p_registration_key text, p_claim_token uuid, p_completion_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_session private.adult_verification_sessions%rowtype;
begin
  if p_callback_nonce_digest is null
    or p_callback_nonce_digest !~ '^[0-9a-f]{64}$'
    or p_registration_key is null
    or p_registration_key !~ '^[A-Za-z0-9]{1,40}$'
    or p_claim_token is null
    or p_completion_token_digest is null
    or p_completion_token_digest !~ '^[0-9a-f]{64}$'
  then
    raise invalid_parameter_value using message = 'adult_verification_callback_invalid';
  end if;

  select session.*
  into v_session
  from private.adult_verification_sessions as session
  where session.callback_nonce_digest = p_callback_nonce_digest
  for update;

  if not found
    or v_session.registration_key is null
    or v_session.registration_key is distinct from p_registration_key
  then
    raise no_data_found using message = 'adult_verification_callback_invalid';
  end if;

  if v_session.state in ('verified', 'underage', 'failed', 'expired') then
    return pg_catalog.jsonb_build_object(
      'claimStatus', 'terminal',
      'state', v_session.state,
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.expires_at <= v_now then
    perform private.close_adult_verification_session(v_session.id, 'expired', 'session_expired');
    return pg_catalog.jsonb_build_object(
      'claimStatus', 'terminal',
      'state', 'expired',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.state = 'awaiting_owner' then
    return pg_catalog.jsonb_build_object(
      'claimStatus', 'staged',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.state = 'confirming' then
    if v_session.claim_expires_at > v_now then
      return pg_catalog.jsonb_build_object(
        'claimStatus', 'in_progress',
        'presentation', v_session.presentation,
        'returnPath', v_session.return_path
      );
    end if;

    perform private.close_adult_verification_session(v_session.id, 'failed', 'claim_expired');
    return pg_catalog.jsonb_build_object(
      'claimStatus', 'terminal',
      'state', 'failed',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  -- 거래등록만 끝난 registered만 남는다.
  update private.adult_verification_sessions
  set
    state = 'confirming',
    claim_token = p_claim_token,
    claim_expires_at = v_now + interval '2 minutes',
    completion_token_digest = p_completion_token_digest
  where id = v_session.id
  returning * into v_session;

  return pg_catalog.jsonb_build_object(
    'claimStatus', 'claimed',
    'sessionId', v_session.id,
    'providerMode', v_session.provider_mode,
    'providerOrderId', v_session.provider_order_id,
    'registrationKey', v_session.registration_key,
    'presentation', v_session.presentation,
    'returnPath', v_session.return_path
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_email_delivery(target_dedupe_key text, target_template text, target_recipient text, target_subject text, target_retry_after interval DEFAULT '00:10:00'::interval)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  normalized_key text := btrim(coalesce(target_dedupe_key, ''), E' \t\n\r\f\v');
  normalized_subject text := btrim(coalesce(target_subject, ''), E' \t\n\r\f\v');
  normalized_recipient text := btrim(coalesce(target_recipient, ''), E' \t\n\r\f\v');
  existing record;
begin
  if char_length(normalized_key) < 1 or char_length(normalized_key) > 200 then
    raise exception 'invalid_dedupe_key' using errcode = '22023';
  end if;
  if target_template is null
    or target_template not in ('order_confirmation', 'order_shipped', 'inquiry_answered', 'restock_alert')
  then
    raise exception 'invalid_email_template' using errcode = '22023';
  end if;
  if char_length(normalized_recipient) < 3 or char_length(normalized_recipient) > 320 then
    raise exception 'invalid_email_recipient' using errcode = '22023';
  end if;
  if char_length(normalized_subject) < 1 or char_length(normalized_subject) > 200 then
    raise exception 'invalid_email_subject' using errcode = '22023';
  end if;

  -- 응답이 유실된 재시도는 먼저 커밋된 클레임을 관측한 뒤에 판단해야 한다.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('email_delivery:' || normalized_key, 0)
  );

  select delivery.id, delivery.status, delivery.attempt_count, delivery.claimed_at
    into existing
  from public.email_deliveries as delivery
  where delivery.dedupe_key = normalized_key
  for update;

  if found then
    if existing.status = 'sent' then
      return false;
    end if;
    if existing.status = 'pending'
      and existing.claimed_at > now() - coalesce(target_retry_after, interval '10 minutes')
    then
      return false;
    end if;
    if existing.attempt_count >= 1000 then
      return false;
    end if;

    update public.email_deliveries
    set
      status = 'pending',
      attempt_count = existing.attempt_count + 1,
      subject = normalized_subject,
      recipient = normalized_recipient,
      claimed_at = now(),
      completed_at = null
    where id = existing.id;

    return true;
  end if;

  insert into public.email_deliveries (
    dedupe_key,
    template,
    recipient,
    subject,
    status
  )
  values (
    normalized_key,
    target_template,
    normalized_recipient,
    normalized_subject,
    'pending'
  );

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_email_intent_dispatch(target_intent_id uuid, target_recipient_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_control private.email_dispatch_control%rowtype;v_intent private.email_intents%rowtype;
 v_recipient_digest bytea:=private.email_digest_from_hex(target_recipient_digest);v_claim_id uuid;v_delay_enabled boolean;
begin
 if not private.lock_operator_invitation_dispatch(target_intent_id) then
  return jsonb_build_object('kind','disabled','state',(select state from private.email_intents where id=target_intent_id));
 end if;
 select * into strict v_control from private.email_dispatch_control where singleton for share;
 select enabled into strict v_delay_enabled from private.order_delay_notice_delivery_control where singleton for share;
 select * into v_intent from private.email_intents where id=target_intent_id for update;
 if not found then raise no_data_found using message='email_intent_not_found';end if;
 if v_intent.recipient_digest is distinct from v_recipient_digest then raise check_violation using message='email_intent_recipient_mismatch';end if;
 if not exists(select 1 from private.email_intent_fences where intent_id=v_intent.id) then raise object_not_in_prerequisite_state using message='email_intent_fence_missing';end if;
 if not (case when v_intent.source='order_delay_notice' then v_delay_enabled when v_intent.source='stock_safety_digest' then coalesce((select d.enabled from private.stock_safety_digest_settings d where d.singleton),false) else v_control.enabled end)
  then return jsonb_build_object('kind','disabled','state',v_intent.state);end if;
 if v_intent.state in ('accepted','sent','delivered','delayed','bounced','complained','suppressed','failed')
  then return jsonb_build_object('kind','already_dispatched','state',v_intent.state);end if;
 if v_intent.state='needs_review' then return jsonb_build_object('kind','needs_review','state',v_intent.state);end if;
 if v_intent.idempotency_expires_at is not null and now()+interval '5 minutes'>=v_intent.idempotency_expires_at then
  update private.email_intents set state='needs_review',updated_at=now() where id=v_intent.id;
  return jsonb_build_object('kind','needs_review','state','needs_review');
 end if;
 if v_intent.state='dispatching' and v_intent.claimed_at>now()-interval '10 minutes'
  then return jsonb_build_object('kind','in_progress','state',v_intent.state);end if;
 if v_intent.attempt_count>=100 then
  update private.email_intents set state='needs_review',updated_at=now() where id=v_intent.id;
  return jsonb_build_object('kind','needs_review','state','needs_review');
 end if;
 v_claim_id:=extensions.gen_random_uuid();
 update private.email_intents set state='dispatching',dispatch_claim_id=v_claim_id,attempt_count=attempt_count+1,claimed_at=now(),
  first_dispatched_at=coalesce(first_dispatched_at,now()),idempotency_expires_at=coalesce(idempotency_expires_at,now()+interval '24 hours'),updated_at=now()
  where id=v_intent.id returning * into v_intent;
 return jsonb_build_object('kind','claimed','intentId',v_intent.id,'claimId',v_intent.dispatch_claim_id,'idempotencyKey',v_intent.idempotency_key);
end $function$

CREATE OR REPLACE FUNCTION public.claim_goods_payment_attempt(p_provider public.payment_provider, p_provider_order_id text, p_callback_nonce_digest text, p_claim_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;order_id uuid;begin
 result:=private.claim_goods_payment_before_sale_period(p_provider,p_provider_order_id,p_callback_nonce_digest,p_claim_token);
 if result->>'claim_status'='claimed' then
  select ref_id into order_id from public.payment_attempts where provider=p_provider and provider_order_id=p_provider_order_id and purpose='order';
  perform private.assert_order_goods_sale_period(order_id);
 end if;
 -- Terminal/in-progress retries and all reconciliation/finalizer paths retain
 -- their original snapshot contract after money has already been approved.
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.claim_goods_payment_reconciliation(p_attempt_id uuid, p_claim_token uuid, p_case_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_attempt public.payment_attempts%rowtype;
  v_order public.orders%rowtype;
begin
  if p_attempt_id is null
    or p_claim_token is null
    or p_case_ref is null
    or p_case_ref !~ '^[A-Za-z0-9_-]{16,128}$'
  then
    raise invalid_parameter_value using message = 'goods_reconciliation_claim_invalid';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.purpose = 'order'
    and attempt.provider in ('toss', 'korpay', 'nicepay');
  if not found then
    raise no_data_found using message = 'goods_payment_attempt_not_found';
  end if;

  if v_attempt.state in ('approved', 'declined', 'canceled') then
    perform private.record_goods_reconciliation_audit(
      p_claim_token,
      'payment',
      p_attempt_id,
      'goods_payment_reconciliation_service_v1',
      p_case_ref,
      'terminal',
      v_attempt.state
    );
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.goods_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;
  if v_attempt.state = 'confirming'
    and v_attempt.claim_expires_at is not null
    and v_attempt.claim_expires_at > pg_catalog.clock_timestamp()
  then
    perform private.record_goods_reconciliation_audit(
      p_claim_token,
      'payment',
      p_attempt_id,
      'goods_payment_reconciliation_service_v1',
      p_case_ref,
      'in_progress'
    );
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.goods_payment_attempt_json(v_attempt)
    );
  end if;

  select order_record.*
  into v_order
  from public.orders as order_record
  where order_record.id = v_attempt.ref_id
  for update;
  if not found then
    raise no_data_found using message = 'goods_order_not_found';
  end if;

  perform request.id
  from public.order_cancellation_requests as request
  where request.order_id = v_order.id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.purpose = 'order'
    and attempt.provider in ('toss', 'korpay', 'nicepay')
  for update;
  if not found then
    raise no_data_found using message = 'goods_payment_attempt_not_found';
  end if;

  if v_attempt.state in ('approved', 'declined', 'canceled') then
    perform private.record_goods_reconciliation_audit(
      p_claim_token,
      'payment',
      p_attempt_id,
      'goods_payment_reconciliation_service_v1',
      p_case_ref,
      'terminal',
      v_attempt.state
    );
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.goods_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;
  if v_attempt.state = 'confirming'
    and v_attempt.claim_expires_at is not null
    and v_attempt.claim_expires_at > pg_catalog.clock_timestamp()
  then
    perform private.record_goods_reconciliation_audit(
      p_claim_token,
      'payment',
      p_attempt_id,
      'goods_payment_reconciliation_service_v1',
      p_case_ref,
      'in_progress'
    );
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.goods_payment_attempt_json(v_attempt)
    );
  end if;
  if v_attempt.state not in ('unknown', 'needs_review', 'confirming') then
    raise object_not_in_prerequisite_state using message = 'goods_payment_not_reconcilable';
  end if;

  update public.payment_attempts
  set
    state = 'confirming',
    claim_token = p_claim_token,
    claim_expires_at = pg_catalog.clock_timestamp() + interval '10 minutes'
  where id = v_attempt.id
  returning * into v_attempt;

  perform private.record_goods_reconciliation_audit(
    p_claim_token,
    'payment',
    p_attempt_id,
    'goods_payment_reconciliation_service_v1',
    p_case_ref,
    'claimed'
  );

  return pg_catalog.jsonb_build_object(
    'claim_status', 'claimed',
    'attempt', private.goods_payment_attempt_json(v_attempt)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_order_delay_sms_jobs(batch_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; enabled boolean;
begin
  if batch_limit is null or batch_limit not between 1 and 50 then raise invalid_parameter_value using message='invalid_delay_sms_batch'; end if;
  -- 잠금이 끝난 처리 중 작업은 보냈는지 알 수 없다. 다시 보내지 않고 결과 불명으로 둔다.
  update private.order_delay_notice_sms_jobs set status='unknown',reason='lease_expired',claim_token=null,lease_until=null,updated_at=now()
   where status='processing' and lease_until<now();
  -- 하루가 지난 대기 작업은 낡은 일정 안내라 보내지 않는다.
  update private.order_delay_notice_sms_jobs set status='skipped',reason='expired',updated_at=now()
   where status='queued' and created_at<now()-interval '24 hours';
  select coalesce(control.sms_enabled,false) into enabled from private.order_delay_notice_delivery_control control where control.singleton;
  if not coalesce(enabled,false) then
    update private.order_delay_notice_sms_jobs set status='skipped',reason='sms_disabled',updated_at=now() where status='queued';
    return '[]'::jsonb;
  end if;
  with picked as (
   select job.target_id from private.order_delay_notice_sms_jobs job where job.status='queued'
   order by job.created_at,job.target_id for update skip locked limit batch_limit
  ), checked as (
   select picked.target_id,coalesce(private.order_delay_notice_target_current(picked.target_id),false) current_target,
    exists(select 1 from private.order_delay_notice_targets t join private.customer_marketing_consents consent
     on consent.user_id=t.buyer_id and consent.channel='sms' and consent.agreed where t.id=picked.target_id) consented
   from picked
  ), skipped as (
   update private.order_delay_notice_sms_jobs job set status='skipped',
    reason=case when not checked.current_target then 'target_changed' else 'consent_required' end,updated_at=now()
   from checked where job.target_id=checked.target_id and not (checked.current_target and checked.consented) returning job.target_id
  ), claimed as (
   update private.order_delay_notice_sms_jobs job set status='processing',claim_token=extensions.gen_random_uuid(),
    lease_until=now()+interval '10 minutes',attempts=job.attempts+1,updated_at=now()
   from checked where job.target_id=checked.target_id and checked.current_target and checked.consented returning job.*
  )
  select coalesce(jsonb_agg(jsonb_build_object('id',c.target_id,'claimToken',c.claim_token,'userId',t.buyer_id,'orderId',t.order_id,
    'orderNumber',o.order_number,'audience',t.audience,'title',n.title,'body',t.message_body) order by c.created_at,c.target_id),'[]'::jsonb)
   into result
  from claimed c join private.order_delay_notice_targets t on t.id=c.target_id
  join private.order_delay_notices n on n.id=t.notice_id join public.orders o on o.id=t.order_id;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.claim_ticket_payment_attempt(p_provider public.payment_provider, p_provider_order_id text, p_callback_nonce_digest text, p_claim_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_attempt public.payment_attempts%rowtype;
  v_order public.ticket_orders%rowtype;
begin
  if p_provider not in ('toss', 'korpay')
    or p_provider_order_id is null
    or pg_catalog.length(p_provider_order_id) not between 1 and 200
    or p_callback_nonce_digest is null
    or p_callback_nonce_digest !~ '^[0-9a-f]{64}$'
    or p_claim_token is null
  then
    raise invalid_parameter_value using message = 'ticket_payment_callback_invalid';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.provider = p_provider
    and attempt.provider_order_id = p_provider_order_id
    and attempt.purpose = 'ticket';

  if not found
    or v_attempt.callback_nonce_digest is null
    or v_attempt.callback_nonce_digest is distinct from p_callback_nonce_digest
  then
    raise no_data_found using message = 'ticket_payment_callback_invalid';
  end if;

  if v_attempt.state in ('approved', 'declined', 'canceled', 'unknown', 'needs_review') then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;
  if v_attempt.state = 'confirming' then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;

  select ticket_order.*
  into v_order
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_attempt.ref_id
  for update;
  if not found then
    raise no_data_found using message = 'ticket_order_not_found';
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = v_order.id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;
  -- A cancellation may race an already-created provider session. Keep the
  -- request fenced, but still learn provider truth for this known order+nonce.
  -- The finalizer records approval without issuing QR and makes it refund-ready.

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.provider = p_provider
    and attempt.provider_order_id = p_provider_order_id
    and attempt.purpose = 'ticket'
  for update;

  if not found
    or v_attempt.callback_nonce_digest is null
    or v_attempt.callback_nonce_digest is distinct from p_callback_nonce_digest
  then
    raise no_data_found using message = 'ticket_payment_callback_invalid';
  end if;
  if v_attempt.state in ('approved', 'declined', 'canceled', 'unknown', 'needs_review') then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;
  if v_attempt.state = 'confirming' then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;

  if v_attempt.state is distinct from 'prepared'
    or v_attempt.expires_at <= pg_catalog.clock_timestamp()
    or v_order.user_id is distinct from v_attempt.user_id
    or v_order.status is distinct from 'pending'
    or v_order.expires_at is null
    or v_order.expires_at <= pg_catalog.clock_timestamp()
    or v_order.total is distinct from v_attempt.amount
    or v_attempt.currency is distinct from 'KRW'
    or private.is_account_write_fenced(v_attempt.user_id)
    or exists (
      select 1 from public.profiles as profile
      where profile.id = v_attempt.user_id and profile.suspended_at is not null
    )
    or not private.ticket_order_snapshot_matches(
      v_order.id,
      v_order.event_id,
      v_order.total
    )
    or exists (
      select 1 from public.tickets as ticket
      where ticket.ticket_order_id = v_order.id
    )
    or exists (
      select 1 from public.payments as payment
      where payment.purpose = 'ticket'
        and payment.ref_id = v_order.id
        and payment.status in ('pending', 'paid')
    )
  then
    raise object_not_in_prerequisite_state using message = 'ticket_order_not_payable';
  end if;

  update public.payment_attempts
  set
    state = 'confirming',
    claim_token = p_claim_token,
    claim_expires_at = pg_catalog.clock_timestamp() + interval '10 minutes'
  where id = v_attempt.id
  returning * into v_attempt;

  return pg_catalog.jsonb_build_object(
    'claim_status', 'claimed',
    'attempt', private.ticket_payment_attempt_json(v_attempt)
  );
end;
$function$

