      p_claim_token,
      'payment',
      p_attempt_id,
      'payment_reconciliation_service_v1',
      p_case_ref,
      'terminal',
      v_attempt.state
    );
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', v_attempt.state
    );
  end if;
  if v_attempt.state = 'confirming'
    and v_attempt.claim_expires_at is not null
    and v_attempt.claim_expires_at > pg_catalog.clock_timestamp()
  then
    perform private.record_ticket_reconciliation_audit(
      p_claim_token,
      'payment',
      p_attempt_id,
      'payment_reconciliation_service_v1',
      p_case_ref,
      'in_progress'
    );
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;
  if v_attempt.state not in ('unknown', 'needs_review', 'confirming') then
    raise object_not_in_prerequisite_state using message = 'ticket_payment_not_reconcilable';
  end if;

  update public.payment_attempts
  set
    state = 'confirming',
    claim_token = p_claim_token,
    claim_expires_at = pg_catalog.clock_timestamp() + interval '10 minutes'
  where id = v_attempt.id
  returning * into v_attempt;

  perform private.record_ticket_reconciliation_audit(
    p_claim_token,
    'payment',
    p_attempt_id,
    'payment_reconciliation_service_v1',
    p_case_ref,
    'claimed'
  );

  return pg_catalog.jsonb_build_object(
    'claim_status', 'claimed',
    'attempt', private.ticket_payment_attempt_json(v_attempt)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_ticket_payment_refund(p_request_id uuid, p_user_id uuid, p_claim_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.ticket_orders%rowtype;
  v_request public.ticket_cancellation_requests%rowtype;
  v_attempt public.payment_attempts%rowtype;
begin
  if p_request_id is null or p_user_id is null or p_claim_token is null then
    raise invalid_parameter_value using message = 'ticket_refund_claim_invalid';
  end if;

  select ticket_order.*
  into v_order
  from public.ticket_orders as ticket_order
  join public.ticket_cancellation_requests as request
    on request.ticket_order_id = ticket_order.id
  where request.id = p_request_id
  for update of ticket_order;
  if not found or v_order.user_id is distinct from p_user_id then
    raise no_data_found using message = 'ticket_refund_not_found';
  end if;

  select request.*
  into v_request
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id
    and request.ticket_order_id = v_order.id
    and request.requested_by = p_user_id
  for update;
  if not found then
    raise no_data_found using message = 'ticket_refund_not_found';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'ticket'
    and attempt.ref_id = v_order.id
  for update;

  if not found or v_attempt.provider not in ('toss', 'korpay') then
    return pg_catalog.jsonb_build_object('claim_status', 'legacy');
  end if;

  if v_request.status = 'completed' then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', 'approved'
    );
  end if;
  if v_request.status = 'needs_review' then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', 'needs_review'
    );
  end if;
  if v_attempt.state = 'prepared' then
    -- A provider session exists but no callback truth does. Do not call refund
    -- or release capacity; callback drain or authoritative attempt TTL must win.
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;
  if v_request.status = 'processing'
    and v_request.attempt_token is distinct from p_claim_token
    and v_request.attempt_token is not null
    and v_request.provider_started_at > pg_catalog.clock_timestamp() - interval '5 minutes'
  then
    return pg_catalog.jsonb_build_object(
      'claim_status', 'in_progress',
      'attempt', private.ticket_payment_attempt_json(v_attempt)
    );
  end if;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order.id
  order by ticket.id
  for update of ticket;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  join public.ticket_order_reservations as reservation
    on reservation.ticket_type_id = ticket_type.id
  where reservation.ticket_order_id = v_order.id
  for update of ticket_type;

  if v_request.status not in ('requested', 'processing')
    or v_order.status is distinct from 'paid'
    or v_attempt.state is distinct from 'approved'
    or v_attempt.payment_id is null
    or not exists (
      select 1
      from public.payments as payment
      where payment.id = v_attempt.payment_id
        and payment.provider = v_attempt.provider
        and payment.purpose = 'ticket'
        and payment.ref_id = v_order.id
        and payment.user_id = p_user_id
        and payment.amount = v_order.total
        and payment.status = 'paid'
    )
    or not exists (
      select 1 from public.tickets as ticket
      where ticket.ticket_order_id = v_order.id
    )
    or exists (
      select 1 from public.tickets as ticket
      where ticket.ticket_order_id = v_order.id
        and ticket.status <> 'valid'
    )
  then
    update public.ticket_cancellation_requests
    set
      status = 'needs_review',
      attempt_token = null,
      last_error_code = 'payment_not_refundable'
    where id = v_request.id;

    return pg_catalog.jsonb_build_object(
      'claim_status', 'terminal',
      'attempt', private.ticket_payment_attempt_json(v_attempt),
      'outcome', 'needs_review'
    );
  end if;

  update public.ticket_cancellation_requests
  set
    status = 'processing',
    attempt_token = p_claim_token,
    provider_started_at = pg_catalog.clock_timestamp(),
    last_error_code = null
  where id = v_request.id;

  return pg_catalog.jsonb_build_object(
    'claim_status', 'claimed',
    'attempt', private.ticket_payment_attempt_json(v_attempt)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.clear_cart_coupon()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  delete from public.cart_coupon_selections where user_id = v_user;
end;
$function$

CREATE OR REPLACE FUNCTION public.close_my_gift(p_id uuid, p_expected_revision bigint, p_operation_id uuid, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare actor uuid:=auth.uid();gift private.gift_intents;request jsonb;begin
 if actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_lock(p_id,actor);perform private.gift_require_actor(actor,false);
 if gift.sender_id<>actor and gift.recipient_id is distinct from actor then raise insufficient_privilege using message='gift_not_found';end if;
 request:=jsonb_build_object('revision',p_expected_revision);
 if private.gift_operation_replay(actor,p_id,'closed',request,p_operation_id) then return private.gift_operation_result(actor,p_operation_id);end if;
 if p_expected_revision is null or gift.revision<>p_expected_revision then raise sqlstate 'PT409' using message='gift_changed';end if;
 if gift.state not in('awaiting_acceptance','accepted') or gift.order_id is not null then raise check_violation using message='gift_close_unavailable';end if;
 update private.gift_intents set state='canceled',closed_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where id=p_id;
 update private.gift_link_tokens set revoked_at=clock_timestamp() where gift_id=p_id and revoked_at is null;
 delete from private.gift_claim_sessions s using private.gift_link_tokens t where s.token_hash=t.token_hash and t.gift_id=p_id;
 delete from private.goods_transaction_quotes where actor_id=gift.sender_id and source->>'kind'='gift' and source->>'id'=gift.id::text and order_id is null;
 delete from private.gift_recipient_addresses where gift_id=p_id;
 perform private.gift_record_operation(actor,p_id,'closed',request,p_operation_id);return private.gift_operation_result(actor,p_operation_id);
end $function$

CREATE OR REPLACE FUNCTION public.complete_my_adult_verification(p_callback_nonce_digest text, p_completion_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := (select auth.uid());
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_session private.adult_verification_sessions%rowtype;
  v_evidence private.adult_verifications%rowtype;
  v_moved record;
begin
  if v_user is null then
    raise insufficient_privilege using message = 'auth required';
  end if;

  if p_callback_nonce_digest is null
    or p_callback_nonce_digest !~ '^[0-9a-f]{64}$'
    or p_completion_token_digest is null
    or p_completion_token_digest !~ '^[0-9a-f]{64}$'
  then
    raise invalid_parameter_value using message = 'adult_verification_invalid';
  end if;

  -- 잠금 순서: 계정(fence 잠금) → 세션 → 명의. begin과 같은 계정 잠금을 먼저 잡아
  -- 탈퇴 신청·새 인증 시작과 직렬화한다.
  if private.is_account_write_fenced(v_user) then
    raise insufficient_privilege using message = 'adult_verification_account_blocked';
  end if;

  select session.*
  into v_session
  from private.adult_verification_sessions as session
  where session.callback_nonce_digest = p_callback_nonce_digest
  for update;

  if not found
    or v_session.user_id is distinct from v_user
    or v_session.completion_token_digest is null
    or v_session.completion_token_digest is distinct from p_completion_token_digest
  then
    raise no_data_found using message = 'adult_verification_not_found';
  end if;

  if v_session.state in ('verified', 'underage', 'failed', 'expired') then
    return pg_catalog.jsonb_build_object(
      'outcome', v_session.state,
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.expires_at <= v_now then
    perform private.close_adult_verification_session(v_session.id, 'expired', 'session_expired');
    return pg_catalog.jsonb_build_object(
      'outcome', 'expired',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  -- 결과 조회 중이다. 선점이 만료됐으면 처리기가 중간에 죽은 것이고 콜백은 다시 오지
  -- 않는다 — 기다리게 두지 않고 실패로 닫아 다시 시작하게 한다.
  if v_session.state = 'confirming' and v_session.claim_expires_at <= v_now then
    perform private.close_adult_verification_session(v_session.id, 'failed', 'claim_expired');
    return pg_catalog.jsonb_build_object(
      'outcome', 'failed',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.state <> 'awaiting_owner' then
    return pg_catalog.jsonb_build_object(
      'outcome', 'pending',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_user
      and profile.suspended_at is not null
  ) then
    perform private.close_adult_verification_session(v_session.id, 'failed', 'account_blocked');
    return pg_catalog.jsonb_build_object(
      'outcome', 'failed',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  if v_session.staged_outcome = 'underage' then
    update private.adult_verifications
    set revoked_at = v_now, revoked_reason = 'underage_result'
    where user_id = v_user
      and revoked_at is null;

    perform private.close_adult_verification_session(v_session.id, 'underage', null);

    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_user,
      'identity.adult_verification.underage',
      'profiles:' || v_user::text,
      pg_catalog.jsonb_build_object(
        'provider', v_session.provider,
        'providerMode', v_session.provider_mode,
        'policyVersion', v_session.staged_policy_version
      )
    );

    return pg_catalog.jsonb_build_object(
      'outcome', 'underage',
      'presentation', v_session.presentation,
      'returnPath', v_session.return_path
    );
  end if;

  -- 같은 명의의 동시 확정을 직렬화한다. 두 계정이 같은 DI로 동시에 확정해도
  -- 활성 증거는 하나만 남고, 나중에 확정한 계정이 그 명의를 가진다.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('adult-verification-subject:' || v_session.staged_subject_digest, 0)
  );

  -- 아래 두 해제가 건드릴 활성 증거(내 증거 + 이 명의의 다른 계정 증거)를 id 순서로 먼저
  -- 잠근다. 인증된 두 계정이 서로의 명의로 동시에 확정하면 명의 잠금이 달라 직렬화되지
  -- 않고, 각자 자기 증거를 먼저 잠근 뒤 상대 증거를 기다려 교착될 수 있다 — 잠금 순서를
  -- 하나로 고정해 한쪽이 기다리게 한다.
  perform 1
  from private.adult_verifications as evidence
  where evidence.revoked_at is null
    and (evidence.user_id = v_user or evidence.subject_digest = v_session.staged_subject_digest)
  order by evidence.id
  for update;

  update private.adult_verifications
  set revoked_at = v_now, revoked_reason = 'superseded'
  where user_id = v_user
    and revoked_at is null;

  for v_moved in
    update private.adult_verifications
    set revoked_at = v_now, revoked_reason = 'subject_moved'
    where subject_digest = v_session.staged_subject_digest
      and user_id <> v_user
      and revoked_at is null
    returning user_id
  loop
    insert into public.audit_log (actor_id, action, target, diff)
    values (
      v_user,
      'identity.adult_verification.subject_moved',
      'profiles:' || v_moved.user_id::text,
      pg_catalog.jsonb_build_object('toUser', v_user)
    );
  end loop;

  insert into private.adult_verifications (
    user_id,
    session_id,
    provider,
    provider_mode,
    subject_digest,
    transaction_digest,
    policy_version,
    verified_at,
    expires_at
  )
  values (
    v_user,
    v_session.id,
    v_session.provider,
    v_session.provider_mode,
    v_session.staged_subject_digest,
    v_session.staged_transaction_digest,
    v_session.staged_policy_version,
    v_now,
    v_now + interval '1 year'
  )
  returning * into v_evidence;

  perform private.close_adult_verification_session(v_session.id, 'verified', null);

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    v_user,
    'identity.adult_verification.verified',
    'profiles:' || v_user::text,
    pg_catalog.jsonb_build_object(
      'provider', v_evidence.provider,
      'providerMode', v_evidence.provider_mode,
      'policyVersion', v_evidence.policy_version,
      'expiresAt', v_evidence.expires_at
    )
  );

  return pg_catalog.jsonb_build_object(
    'outcome', 'verified',
    'presentation', v_session.presentation,
    'returnPath', v_session.return_path,
    'expiresAt', v_evidence.expires_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_order_cancellation_request(p_request_id uuid, p_provider_payment_keys text[], p_actor_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order_id uuid;
  v_reason text;
  v_request_status text;
  v_claim_type text;
  v_provider_payment_keys text[];
  v_refund_count integer;
  v_provider_refund_count integer;
begin
  -- p_actor_id null = 시스템(서버 자동 발행). 취소 유형만 허용한다.
  if p_actor_id is not null and not private.can_finish_operator_cancellation(p_request_id,p_actor_id) then
    raise insufficient_privilege using message='operator_capability_required';
  end if;

  select request.order_id
  into v_order_id
  from public.order_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'cancellation_request_not_found';
  end if;

  perform orders.id
  from public.orders
  where orders.id = v_order_id
  for update;

  select request.status, request.reason, request.claim_type
  into v_request_status, v_reason, v_claim_type
  from public.order_cancellation_requests as request
  where request.id = p_request_id
  for update;

  if p_actor_id is null and v_claim_type <> 'cancel' then
    raise insufficient_privilege using message = 'staff required';
  end if;

  if v_request_status = 'completed' then
    return;
  end if;

  if v_request_status <> 'processing' then
    raise exception using message = 'cancellation_request_not_processing';
  end if;

  if not exists (
    select 1
    from public.order_cancellation_claims as claim
    where claim.order_id = v_order_id
  ) then
    raise exception using message = 'cancellation_claim_missing';
  end if;

  select coalesce(array_agg(keys.payment_key order by keys.payment_key), array[]::text[])
  into v_provider_payment_keys
  from (
    select distinct btrim(payment_key) as payment_key
    from unnest(coalesce(p_provider_payment_keys, array[]::text[])) as input(payment_key)
    where payment_key is not null
      and btrim(payment_key) <> ''
  ) as keys;

  -- 로컬 장부가 canceled/refunded여도 provider 취소 완료의 진실원은 fresh GET이다.
  -- 실제 capture가 없었던 failed 결제만 증거 대상에서 제외한다.
  if exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'order'
      and payment.ref_id = v_order_id
      and payment.status <> 'failed'
      and (
        payment.payment_key is null
        or not (payment.payment_key = any(v_provider_payment_keys))
      )
  ) then
    raise exception using message = 'provider cancellation required';
  end if;

  perform public.finalize_order_cancellation_with_provider_evidence(
    v_order_id,
    v_reason,
    v_provider_payment_keys
  );

  update public.refunds as refund
  set cancellation_request_id = p_request_id
  from public.payments as payment
  where refund.payment_id = payment.id
    and payment.purpose = 'order'
    and payment.ref_id = v_order_id
    and (
      refund.cancellation_request_id is null
      or refund.cancellation_request_id = p_request_id
    );

  if exists (
    select 1
    from public.refunds as refund
    where refund.cancellation_request_id = p_request_id
      and refund.status <> 'done'
  ) then
    raise exception using message = 'provider cancellation required';
  end if;

  select count(*)::integer
  into v_refund_count
  from public.refunds as refund
  where refund.cancellation_request_id = p_request_id
    and refund.status = 'done';

  /*
   * 토스 취소가 fresh 조회로 검증된 결제는 여기서 환불 원장까지 닫는다.
   *
   * 검증된 키에 대해서만 적는다 — 이 함수에 들어온 키는 오케스트레이터가 취소 API
   * 발행 뒤 조회로 전액 취소를 확인한 것뿐이다. 수단·처리자·시각은 첫 기록이
   * 이긴다(admin_record_order_claim_refund와 같은 규칙). 계좌 송금이 이미 접수된
   * 결제에는 오케스트레이터가 취소를 발행하지 않으므로 여기 들어오지 않는다.
   */
  update public.refunds as refund
  set
    method = coalesce(refund.method, 'pg_cancel'),
    handled_by = coalesce(refund.handled_by, p_actor_id),
    filed_at = coalesce(refund.filed_at, now()),
    completed_at = coalesce(refund.completed_at, now())
  from public.payments as payment
  where refund.payment_id = payment.id
    and refund.cancellation_request_id = p_request_id
    and refund.status = 'done'
    and payment.purpose = 'order'
    and payment.ref_id = v_order_id
    and payment.provider in ('toss', 'nicepay')
    and payment.payment_key = any(v_provider_payment_keys);

  get diagnostics v_provider_refund_count = row_count;

  update public.order_cancellation_requests
  set
    status = 'completed',
    completed_at = coalesce(completed_at, now()),
    updated_at = now()
  where id = p_request_id
    and status = 'processing';

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_actor_id,
    case when p_actor_id is null
      then 'system.order.cancellation_completed'
      else 'admin.order.cancellation_completed'
    end,
    'order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'to', 'completed',
      'refundCount', v_refund_count,
      'providerRefundCount', v_provider_refund_count
    ) || private.claim_refund_deduction_audit(p_request_id) || case when p_actor_id is null
      then jsonb_build_object('actor', 'system')
      else '{}'::jsonb
    end
  );

  -- 구매자 알림은 실제 취소가 검증된 뒤에만 보낸다.
  if v_provider_refund_count > 0 then
    perform private.notify_order_claim(
      p_request_id,
      'refund_completed',
      '결제 취소가 완료됐어요',
      coalesce(private.claim_refund_deduction_notice(p_request_id, 'provider_completed'),
        '결제 금액 전액을 결제사에서 취소했습니다. 카드사 처리 일정에 따라 환급 반영 시점이 다를 수 있습니다.')
    );
  elsif v_refund_count = 0 then
    perform private.notify_order_claim(
      p_request_id,
      'completed',
      '주문이 취소됐어요',
      '결제가 완료되지 않은 주문이라 결제 취소 없이 주문을 취소했습니다.'
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_ticket_cancellation_request(p_request_id uuid, p_attempt_token uuid, p_provider_payment_keys text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order_id uuid;
  v_order_user_id uuid;
  v_reason text;
  v_status text;
  v_current_attempt_token uuid;
  v_provider_payment_keys text[];
  v_key text;
begin
  select request.ticket_order_id, request.requested_by, request.reason
  into v_order_id, v_order_user_id, v_reason
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'ticket cancellation request not found';
  end if;

  perform ticket_order.id
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;

  select request.status, request.attempt_token
  into v_status, v_current_attempt_token
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id
  for update of request;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket'
    and payment.ref_id = v_order_id
  order by payment.id
  for update of payment;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order_id
  order by ticket.id
  for update of ticket;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id in (
    select ticket.ticket_type_id
    from public.tickets as ticket
    where ticket.ticket_order_id = v_order_id
  )
  order by ticket_type.id
  for update of ticket_type;

  if v_status = 'completed' then
    return;
  end if;

  if v_status <> 'processing' then
    raise check_violation using message = 'ticket cancellation not processing';
  end if;

  if p_attempt_token is null or v_current_attempt_token is distinct from p_attempt_token then
    raise check_violation using message = 'ticket cancellation attempt mismatch';
  end if;

  select coalesce(array_agg(keys.payment_key order by keys.payment_key), array[]::text[])
  into v_provider_payment_keys
  from (
    select distinct btrim(input.payment_key) as payment_key
    from unnest(coalesce(p_provider_payment_keys, array[]::text[])) as input(payment_key)
    where input.payment_key is not null
      and btrim(input.payment_key) <> ''
  ) as keys;

  if exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = v_order_id
      and payment.status <> 'failed'
      and (
        payment.payment_key is null
        or not (payment.payment_key = any(v_provider_payment_keys))
      )
  ) or exists (
    select 1
    from unnest(v_provider_payment_keys) as input(payment_key)
    where not exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'ticket'
        and payment.ref_id = v_order_id
        and payment.user_id = v_order_user_id
        and payment.payment_key = input.payment_key
        and payment.idempotency_key = input.payment_key
    )
  ) then
    raise check_violation using message = 'provider cancellation required';
  end if;

  foreach v_key in array v_provider_payment_keys
  loop
    perform public.record_ticket_provider_cancellation_evidence(
      v_order_id,
      v_reason,
      v_key
    );
  end loop;

  perform public.finalize_ticket_cancellation_request(p_request_id, v_order_user_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_my_goods_subscription_change(p_expected_actor_id uuid, p_plan_id uuid, p_expected_revision bigint, p_proposal_id uuid, p_terms_id uuid, p_quote_id uuid, p_credential_id uuid, p_operation_id uuid, p_consent boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();plan private.goods_subscription_plans;proposal private.goods_subscription_proposals;terms private.goods_subscription_terms;
 credential private.billing_credentials;request_hash text;result jsonb;quoted jsonb;renewal_terms jsonb;cycle_id uuid;due timestamptz;
begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='subscription_actor_changed';end if;
 perform private.lock_goods_transaction_source(actor,private.subscription_source(p_proposal_id,p_terms_id::text));
 select * into proposal from private.goods_subscription_proposals where id=p_proposal_id and owner_id=actor and plan_id=p_plan_id;
 if not found then raise no_data_found using message='subscription_proposal_not_found';end if;
 request_hash:=encode(sha256(convert_to(jsonb_build_array(p_expected_revision,p_proposal_id,p_terms_id,p_quote_id,p_credential_id,p_consent)::text,'UTF8')),'hex');
 result:=private.subscription_operation_replay(actor,p_plan_id,p_operation_id,proposal.command,request_hash);if result is not null then return result;end if;
 select * into plan from private.goods_subscription_plans where id=p_plan_id and owner_id=actor for update;
 if plan.revision is distinct from p_expected_revision or proposal.expected_revision<>p_expected_revision or plan.state not in('active','paused','needs_confirmation')
  or proposal.terms_id is distinct from p_terms_id or proposal.expires_at<=clock_timestamp() or p_consent is distinct from true then
  raise sqlstate 'PT409' using message='subscription_proposal_changed';end if;
 perform private.subscription_lock_actor(actor,true);
 if not(select charge_enabled from private.goods_subscription_runtime where singleton) then raise object_not_in_prerequisite_state using message='subscriptions_unavailable';end if;
 if exists(select 1 from private.goods_subscription_cycles where plan_id=p_plan_id and dispatched_at is not null and state in('dispatching','unknown','needs_review')) then
  raise object_not_in_prerequisite_state using message='subscription_payment_pending';end if;
 select * into terms from private.goods_subscription_terms where id=p_terms_id and plan_id=p_plan_id;
 if not found or terms.renewal_quote_id is distinct from p_quote_id or terms.policy_terms_version<>(select terms_version from private.goods_subscription_runtime where singleton) then
  raise sqlstate 'PT409' using message='subscription_terms_changed';end if;
 due:=private.subscription_slot_at(terms.schedule,0);if due<=clock_timestamp() then raise sqlstate 'PT409' using message='subscription_future_schedule_required';end if;
 select * into credential from private.billing_credentials where id=p_credential_id and owner_id=actor and state='active' for update;
 if not found or not exists(select 1 from private.billing_profiles where id=credential.profile_id and enabled) then
  raise object_not_in_prerequisite_state using message='subscription_card_unavailable';end if;
 quoted:=private.quote_goods_transaction(actor,private.subscription_source(p_proposal_id,terms.id::text),terms.selection,terms.address,terms.delivery_choices,null,0);
 if quoted->>'state'<>'quoted' or not private.subscription_selection_allowed(terms.selection,terms.schedule) then raise sqlstate 'PT409' using message='subscription_terms_changed';end if;
 renewal_terms:=private.subscription_renewal_terms(quoted->'display',terms.selection,terms.schedule,terms.address_revision);
 if renewal_terms is distinct from terms.renewal_terms then raise sqlstate 'PT409' using message='subscription_terms_changed';end if;
 for cycle_id in select id from private.goods_subscription_cycles where plan_id=p_plan_id and state in('draft','ready','prepared') order by id loop
  perform private.subscription_stop_cycle(cycle_id,'terms_replaced');
 end loop;
 insert into private.goods_subscription_cycles(id,plan_id,owner_id,cycle_number,schedule_slot,terms_id,scheduled_at,state)
  values(p_proposal_id,p_plan_id,actor,plan.last_cycle_number+1,0,terms.id,due,'ready');
 update private.goods_subscription_plans set state='active',pause_reason=null,current_terms_id=terms.id,credential_id=credential.id,
  next_slot=0,next_run_at=due,last_cycle_number=last_cycle_number+1,revision=revision+1,consented_at=clock_timestamp(),updated_at=clock_timestamp()
  where id=p_plan_id returning * into plan;
 result:=jsonb_build_object('operationId',p_operation_id,'planId',p_plan_id,'revision',plan.revision,'state',plan.state,'cycleId',p_proposal_id);
 return private.subscription_record_operation(actor,p_plan_id,p_operation_id,proposal.command,request_hash,result);
end $function$

CREATE OR REPLACE FUNCTION public.confirm_my_goods_subscription(p_expected_actor_id uuid, p_plan_id uuid, p_cycle_id uuid, p_expected_revision bigint, p_quote_id uuid, p_terms_id uuid, p_credential_id uuid, p_operation_id uuid, p_consent boolean)
