 if not(select public_enabled and charge_enabled from private.goods_subscription_runtime where singleton) then
  raise object_not_in_prerequisite_state using message='subscriptions_unavailable';end if;
 if terms.policy_terms_version<>(select terms_version from private.goods_subscription_runtime where singleton) then raise sqlstate 'PT409' using message='subscription_terms_changed';end if;
 select * into credential from private.billing_credentials where id=p_credential_id and owner_id=actor and state='active' for update;
 if not found or not exists(select 1 from private.billing_profiles where id=credential.profile_id and enabled) then
  raise object_not_in_prerequisite_state using message='subscription_card_unavailable';end if;
 renewal_quote:=private.quote_goods_transaction(actor,private.subscription_source(cycle.id,terms.id::text),terms.selection,terms.address,terms.delivery_choices,null,0);
 if renewal_quote->>'state'<>'quoted' or not private.subscription_selection_allowed(terms.selection,terms.schedule) then raise sqlstate 'PT409' using message='subscription_terms_changed';end if;
 current_renewal:=private.subscription_renewal_terms(renewal_quote->'display',terms.selection,terms.schedule,terms.address_revision);
 if current_renewal is distinct from terms.renewal_terms then raise sqlstate 'PT409' using message='subscription_terms_changed';end if;
 order_id:=private.place_goods_transaction(actor,private.subscription_source(cycle.id,terms.id::text),terms.selection,terms.address,p_quote_id,cycle.id,'card');
 update private.goods_subscription_cycles set state='prepared',order_id=subscription_confirm.order_id,revision=revision+1,scheduled_at=clock_timestamp(),updated_at=clock_timestamp() where id=cycle.id;
 update private.goods_subscription_plans set state='awaiting_first_payment',credential_id=p_credential_id,revision=revision+1,consented_at=clock_timestamp(),updated_at=clock_timestamp(),next_run_at=clock_timestamp() where id=p_plan_id returning * into plan;
 result:=jsonb_build_object('operationId',p_operation_id,'planId',p_plan_id,'revision',plan.revision,'state',plan.state,'cycleId',cycle.id,'orderId',order_id);
 return private.subscription_record_operation(actor,p_plan_id,p_operation_id,'confirm',request_hash,result);
end $function$

CREATE OR REPLACE FUNCTION public.confirm_order_payment(p_idempotency_key text, p_order_id uuid, p_payment_key text, p_amount bigint, p_raw jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user uuid;
  v_total bigint;
  v_status public.order_status;
  v_expires_at timestamptz;
  v_existing record;
begin
  select orders.user_id, orders.total, orders.status, orders.expires_at
    into v_user, v_total, v_status, v_expires_at
  from public.orders
  where orders.id = p_order_id
  for update;

  select payments.id, payments.purpose, payments.ref_id, payments.amount, payments.status
    into v_existing
  from public.payments
  where payments.idempotency_key = p_idempotency_key
  for update;

  if v_existing.id is not null then
    if v_existing.purpose <> 'order' or v_existing.ref_id is distinct from p_order_id then
      raise exception 'idempotency conflict';
    end if;
    if v_existing.status in ('paid', 'refunded') then
      return;
    end if;
    if v_existing.status <> 'pending' then
      raise exception 'payment not payable';
    end if;
  end if;

  if exists (
    select 1
    from public.order_cancellation_claims as claim
    where claim.order_id = p_order_id
  ) then
    raise exception 'order not payable';
  end if;

  if v_user is null then
    raise exception 'order not found';
  end if;
  if v_status <> 'pending' then
    raise exception 'order not payable';
  end if;
  if v_expires_at is not null and now() >= v_expires_at then
    raise exception 'order expired';
  end if;
  if p_amount <> v_total then
    raise exception 'amount mismatch';
  end if;
  if v_existing.id is not null and v_existing.amount <> p_amount then
    raise exception 'amount mismatch';
  end if;

  insert into public.payments (
    user_id,
    purpose,
    ref_id,
    amount,
    status,
    payment_key,
    idempotency_key,
    raw
  )
  values (
    v_user,
    'order',
    p_order_id,
    p_amount,
    'paid',
    p_payment_key,
    p_idempotency_key,
    p_raw
  )
  on conflict (idempotency_key) do update
    set
      status = 'paid',
      payment_key = excluded.payment_key,
      raw = excluded.raw;

  if v_status = 'pending' then
    update public.orders
    set status = 'paid', expires_at = null
    where id = p_order_id;

    insert into public.draw_tickets (
      user_id,
      pool_id,
      source,
      source_id,
      ordinal,
      reward_policy_id
    )
    select
      v_user,
      reward_policy.pool_id,
      'order_paid',
      p_order_id,
      row_number() over (order by reward_policy.id, grant_series.n),
      reward_policy.id
    from public.reward_policies as reward_policy
    join public.card_pools as card_pool
      on card_pool.id = reward_policy.pool_id
    join lateral (
      select sum(order_item.qty * order_item.unit_price) as target_subtotal
      from public.order_items as order_item
      where order_item.order_id = p_order_id
        and order_item.good_ip_id_snapshot = reward_policy.target_ip_id
        and (
          reward_policy.target_good_id is null
          or order_item.good_id = reward_policy.target_good_id
        )
    ) as subtotal on true
    cross join lateral generate_series(
      1,
      reward_policy.tickets_per_grant
    ) as grant_series(n)
    where reward_policy.trigger = 'order_paid'
      and reward_policy.active
      and subtotal.target_subtotal is not null
      and subtotal.target_subtotal >= reward_policy.min_amount
      and now() >= reward_policy.active_from
      and (reward_policy.active_to is null or now() < reward_policy.active_to)
      and now() >= card_pool.active_from
      and (card_pool.active_to is null or now() < card_pool.active_to)
    on conflict (source, source_id, ordinal) do nothing;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_ticket_payment(p_idempotency_key text, p_ticket_order_id uuid, p_payment_key text, p_amount bigint, p_raw jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.ticket_orders%rowtype;
  v_payment public.payments%rowtype;
  v_reservation public.ticket_order_reservations%rowtype;
  v_ticket_count integer;
begin
  if p_idempotency_key is null
    or p_idempotency_key is distinct from p_payment_key
    or nullif(btrim(p_payment_key), '') is null
    or btrim(p_payment_key) <> p_payment_key
    or length(p_payment_key) > 200
    or p_amount is null
    or p_amount <= 0
  then
    raise check_violation using message = 'invalid payment evidence';
  end if;

  select ticket_order.*
  into v_order
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update;
  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = v_order.id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;
  if found then
    raise check_violation using message = 'ticket cancellation in progress';
  end if;

  select payment.*
  into v_payment
  from public.payments as payment
  where payment.idempotency_key = p_idempotency_key
    and payment.payment_key = p_payment_key
  for update;
  if not found
    or v_payment.provider is distinct from 'toss'
    or v_payment.purpose is distinct from 'ticket'
    or v_payment.ref_id is distinct from v_order.id
    or v_payment.user_id is distinct from v_order.user_id
    or v_payment.amount is distinct from p_amount
    or v_order.total is distinct from p_amount
  then
    raise object_not_in_prerequisite_state using message = 'legacy_toss_payment_unknown';
  end if;

  if v_payment.status in ('paid', 'refunded') then
    return;
  end if;
  if v_payment.status is distinct from 'pending'
    or v_order.status is distinct from 'pending'
    or (v_order.expires_at is not null and now() >= v_order.expires_at)
  then
    raise check_violation using message = 'payment not payable';
  end if;

  select reservation.*
  into v_reservation
  from public.ticket_order_reservations as reservation
  where reservation.ticket_order_id = v_order.id
  for update;
  if not found
    or v_reservation.quantity::bigint * v_reservation.unit_price::bigint <> v_order.total
  then
    raise check_violation using message = 'legacy ticket reservation mismatch';
  end if;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order.id
  order by ticket.id
  for update of ticket;

  select count(*)::integer
  into v_ticket_count
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order.id
    and ticket.ticket_type_id = v_reservation.ticket_type_id
    and ticket.status = 'valid';
  if v_ticket_count <> v_reservation.quantity then
    raise object_not_in_prerequisite_state using message = 'legacy_toss_payment_unknown';
  end if;

  update public.payments
  set status = 'paid', raw = p_raw
  where id = v_payment.id;

  update public.ticket_orders
  set status = 'paid', expires_at = null
  where id = v_order.id;

  update public.tickets
  set qr_token = encode(extensions.gen_random_bytes(16), 'hex')
  where ticket_order_id = v_order.id
    and qr_token is null;
end;
$function$

CREATE OR REPLACE FUNCTION public.coupon_recipient_state(target_coupon public.coupons)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); coupon public.coupons; reason text;
begin
 if actor is null or not exists(select 1 from public.user_coupons where user_id=actor and coupon_code=target_coupon.code) then raise insufficient_privilege using message='coupon_not_owned'; end if;
 -- Ignore client-supplied composite policy fields; read the held definition.
 select * into coupon from public.coupons where code=target_coupon.code;
 reason:=private.coupon_recipient_reason(coupon.recipient_segment,actor);
 if reason is null and coupon.recipient_segment='first_purchase' and exists(select 1 from public.orders where user_id=actor and status='pending' and not private.unpaid_order_replaceable(id,actor)) then reason:='coupon_first_purchase_pending'; end if;
 return reason;
end $function$

CREATE OR REPLACE FUNCTION public.create_good_review_v2(target_order_id uuid, target_good_id text, target_rating integer, target_body text, target_image_paths text[] DEFAULT '{}'::text[], target_kind text DEFAULT 'ordinary'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();ordered public.orders;w record;paths text[];created uuid;begin
 if actor is null then raise invalid_authorization_specification using message='auth_required';end if;
 perform private.gift_lock_subjects(array[actor]);perform private.lock_operator_subjects(array[actor]);
 perform private.assert_active_user(actor);if private.is_account_write_fenced(actor) then raise insufficient_privilege;end if;
 if target_kind is null or target_kind not in('ordinary','month') then raise invalid_parameter_value using message='invalid_review_kind';end if;
 if target_rating is null or target_rating not between 1 and 5 then raise invalid_parameter_value using message='invalid_review_rating';end if;
 if char_length(btrim(coalesce(target_body,''))) not between 5 and 1000 then raise invalid_parameter_value using message='invalid_review_body';end if;
 select * into ordered from public.orders where id=target_order_id and user_id=actor for update;
 if not found then raise no_data_found using message='review_order_not_found';end if;
 if ordered.status not in('delivered','done') or ordered.delivered_at is null then raise check_violation using message='review_order_not_delivered';end if;
 if not exists(select 1 from public.order_items where order_id=ordered.id and good_id=target_good_id) then raise no_data_found using message='review_good_not_in_order';end if;
 if target_kind='month' and not private.review_event_purchase_eligible(ordered.id,actor,target_good_id) then raise check_violation using message='review_purchase_ineligible';end if;
 -- Share policy after order locks; policy edits never lock orders.
 perform 1 from private.review_type_policy where singleton for share;
 select * into w from private.review_type_window(ordered,target_kind);
 if w.opens_at is null or statement_timestamp()<w.opens_at or statement_timestamp()>w.deadline_at then
  raise check_violation using message=case when target_kind='month' then 'review_month_window_closed' else 'review_window_closed' end;end if;
 -- 1014-079: 새 리뷰는 구매확정된 주문에만 남는다. 미확정 주문은 create_good_review_v3가 확정한 뒤 이 함수를 부른다.
 if ordered.status='delivered' then raise check_violation using message='review_purchase_confirmation_required';end if;
 paths:=private.assert_own_review_image_paths(target_image_paths,actor);
 begin
  insert into public.reviews(user_id,good_id,order_id,rating,body,image_paths,review_kind) values(actor,target_good_id,ordered.id,target_rating,btrim(target_body),paths,target_kind) returning id into created;
 exception when unique_violation then raise unique_violation using message='review_already_exists';end;
 return created;
end $function$

CREATE OR REPLACE FUNCTION public.create_good_review_v3(target_order_id uuid, target_good_id text, target_rating integer, target_body text, target_image_paths text[], target_kind text, p_acknowledged boolean, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();current_status public.order_status;ordered public.orders;confirmation_revision bigint;reason text;created uuid;confirmed boolean:=false;
begin
 if actor is null then raise invalid_authorization_specification using message='auth_required';end if;
 -- 구매확정이 필요한 주문(배송완료·미확정)만 구매확정 경계를 지난다. 이미 확정된 주문 등은 create_good_review_v2로 바로 넘겨
 -- 프로필을 NO KEY UPDATE로 잡지 않는다(v2는 행위자 → 계정 작업 → 프로필 FOR SHARE만 잡는다). 판정은 잠근 뒤 다시 한다.
 select o.status into current_status from public.orders o where o.id=target_order_id and o.user_id=actor;
 if current_status='delivered' then
  -- 잠금 순서: 행위자 → 계정 작업 → 프로필(NO KEY UPDATE, purchase_confirmation_identity) → 주문 → 확정 행.
  -- 결제·선물(행위자 → 계정 작업 → 프로필)·운영자 고객 RPC(계정 작업 → 프로필)·[구매확정] 버튼과 같은 순서다.
  -- 뒤에 부르는 create_good_review_v2의 계정 잠금(gift_lock_subjects·lock_operator_subjects)은 이미 쥔 잠금을 다시 잡을 뿐이다.
  perform pg_advisory_xact_lock(hashtextextended(actor::text,0));
  perform private.purchase_confirmation_identity(p_actor,p_session,false);
  select * into ordered from public.orders where id=target_order_id and user_id=actor for update;
  -- 잠그는 사이 자동 구매확정 등으로 확정됐으면 확정 없이 리뷰만 저장한다.
  if ordered.status='delivered' then
   if p_acknowledged is distinct from true then raise invalid_parameter_value using message='review_purchase_confirmation_ack_required';end if;
   reason:=private.purchase_confirmation_block_reason(ordered.id);
   if reason is not null then raise check_violation using message='review_purchase_confirmation_blocked',detail=reason;end if;
   -- 정책 저장의 소급 기한 채우기도 확정 행 revision을 올리므로, 확정 행을 잠근 뒤의 revision으로 확정한다.
   select c.revision into confirmation_revision from private.order_purchase_confirmations c where c.order_id=ordered.id for update;
   perform private.change_purchase_confirmation(ordered.id,'confirm','리뷰 등록과 함께 확정',coalesce(confirmation_revision,0),gen_random_uuid(),p_actor,p_session,false);
   confirmed:=true;
  end if;
 end if;
 created:=public.create_good_review_v2(target_order_id,target_good_id,target_rating,target_body,coalesce(target_image_paths,'{}'::text[]),target_kind);
 return jsonb_build_object('reviewId',created,'purchaseConfirmed',confirmed);
end $function$

CREATE OR REPLACE FUNCTION public.create_inquiry(target_category text, target_title text, target_body text, target_order_id uuid DEFAULT NULL::uuid, target_good_id text DEFAULT NULL::text, target_image_paths text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare thread_id uuid; notice jsonb;
begin
  thread_id:=private.create_inquiry_before_system_notice(target_category,target_title,target_body,target_order_id,target_good_id,target_image_paths);
  select settings.inquiry_auto_replies->thread.category into notice
    from public.store_settings settings cross join public.inquiries thread
    where settings.singleton and thread.id=thread_id;
  if (notice->>'enabled')::boolean then
    insert into public.inquiry_messages(inquiry_id,author,author_id,body,created_at)
      values(thread_id,'system',null,notice->>'body',clock_timestamp());
  end if;
  -- Do not change status/answered_at/handled_by/assignment/waiting_since or enqueue notifications.
  return thread_id;
end $function$

CREATE OR REPLACE FUNCTION public.create_my_gift(p_id uuid, p_selection jsonb, p_message text, p_operation_id uuid, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();request jsonb;display jsonb;line jsonb;ordinal bigint;begin
 if actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 if p_id is null or p_message is null or char_length(p_message)>300 or p_message~'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]' then raise invalid_parameter_value using message='gift_input_invalid';end if;
 perform private.gift_lock_subjects(array[actor]);
 perform private.lock_goods_transaction_source(actor,jsonb_build_object('kind','gift','id',p_id,'revision','new'));
 request:=jsonb_build_object('selection',p_selection,'message',p_message);
 if private.gift_operation_replay(actor,p_id,'created',request,p_operation_id) then return private.gift_operation_result(actor,p_operation_id);end if;
 perform private.gift_require_actor(actor);perform private.gift_require_runtime();
 if exists(select 1 from private.gift_intents where id=p_id) then raise unique_violation using message='gift_identity_conflict';end if;
 if (select count(*) from private.gift_intents where sender_id=actor and state in('awaiting_acceptance','accepted') and expires_at>clock_timestamp())>=50 then
  raise check_violation using message='gift_open_limit';end if;
 display:=private.gift_selection_display(p_selection);
 insert into private.gift_intents(id,sender_id,message,sender_label,expires_at) values(p_id,actor,p_message,(select nickname from public.profiles where id=actor),clock_timestamp()+interval '7 days');
 for line,ordinal in select value,ordinality from jsonb_array_elements(p_selection) with ordinality as entries(value,ordinality) loop
  insert into private.gift_items(gift_id,position,good_id,variant_id,qty,input_revision,input_values,item_display)
  values(p_id,ordinal-1,line->>'goodId',(line->>'variantId')::uuid,(line->>'qty')::integer,(line->>'inputRevision')::bigint,line->'inputValues',display->(ordinal::integer-1));
 end loop;
 perform private.gift_record_operation(actor,p_id,'created',request,p_operation_id);return private.gift_operation_result(actor,p_operation_id);
end $function$

CREATE OR REPLACE FUNCTION public.create_post_comment(target_post_id uuid, comment_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := auth.uid();
  normalized_text text := nullif(btrim(comment_text), '');
  inserted_comment_id uuid;
  post_ip_id text;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if normalized_text is null then
    raise exception 'comment_text_required' using errcode = '22023';
  end if;

  select posts.ip_id
    into post_ip_id
    from public.posts
    where posts.id = target_post_id
      and posts.status = 'visible';

  if not found then
    raise exception 'post_not_visible' using errcode = '42501';
  end if;

  insert into public.comments (post_id, user_id, text)
  values (target_post_id, actor_id, normalized_text)
  returning id into inserted_comment_id;

  return jsonb_build_object('commentId', inserted_comment_id, 'ipId', post_ip_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_demographic_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); session_value uuid:=(auth.jwt()->>'session_id')::uuid;
 c private.customer_demographic_consents;
begin
 if actor is null or session_value is null or not exists(select 1 from auth.sessions
  where id=session_value and user_id=actor and (not_after is null or not_after>statement_timestamp())) then
  raise insufficient_privilege using message='customer_demographic_auth_changed'; end if;
 if not exists(select 1 from public.profiles p where p.id=actor and p.role='user'
  and p.onboarded_at is not null and p.suspended_at is null
  and p.consents->'terms'='true'::jsonb and p.consents->'privacy'='true'::jsonb
  and p.birth_date<=((statement_timestamp() at time zone 'Asia/Seoul')::date-interval '14 years')::date)
  or exists(select 1 from private.account_action_fences where subject_user_id=actor) then return null; end if;
 select * into c from private.customer_demographic_consents where user_id=actor;
 return jsonb_build_object('actorId',actor,'sessionId',session_value,'choice',coalesce(c.choice,'unset'),
  'gender',c.gender,'revision',coalesce(c.revision,0),'noticeVersion','customer-demographics-v1','acceptedAt',c.accepted_at);
end $function$

CREATE OR REPLACE FUNCTION public.delete_good_review(target_review_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_paths text[];
begin
  if v_actor is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  delete from public.reviews
  where id = target_review_id
    and user_id = v_actor
  returning image_paths into v_paths;

  if not found then
    raise no_data_found using message = 'review_not_found';
  end if;

  -- 첨부 파일 정리는 호출자가 소유자 권한으로 한다. 여기서 지우려면 RPC가
  -- storage.objects 쓰기 권한을 가져야 하는데, 그 권한을 열면 이 함수 하나가
  -- 버킷 전체를 지울 수 있는 도구가 된다.
  return coalesce(v_paths, '{}'::text[]);
end;
$function$

