CREATE OR REPLACE FUNCTION public.edit_own_post(target_post_id uuid, post_text text, post_ip_id text, post_tag text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := auth.uid();
  normalized_text text := nullif(btrim(post_text), '');
  normalized_ip_id text := nullif(btrim(post_ip_id), '');
  normalized_tag text := nullif(btrim(post_tag), '');
  previous_ip_id text;
  selected_archived_at timestamptz;
  edited_at timestamptz;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if normalized_text is null then
    raise exception 'invalid_post_text' using errcode = '22023';
  end if;

  select post.ip_id
    into previous_ip_id
  from public.posts as post
  where post.id = target_post_id
    and post.user_id = actor_id
    and post.status = 'visible'
  for update of post;

  if not found then
    raise exception 'post_not_editable' using errcode = '42501';
  end if;

  if normalized_ip_id is distinct from previous_ip_id then
    select ip.archived_at
      into selected_archived_at
    from public.ips as ip
    where ip.id = normalized_ip_id
    for share of ip;

    if not found then
      raise exception 'invalid_post_ip' using errcode = '22023';
    end if;

    if selected_archived_at is not null then
      raise check_violation using message = 'catalog_item_archived';
    end if;
  end if;

  update public.posts
  set
    text = normalized_text,
    ip_id = normalized_ip_id,
    tag = normalized_tag
  where id = target_post_id
  returning updated_at into edited_at;

  return jsonb_build_object(
    'previousIpId', previous_ip_id,
    'ipId', normalized_ip_id,
    'updatedAt', edited_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_admin_catalog_artwork_claim()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_actor_id uuid := (select auth.uid());
  object_path text;
  expected_kind text := tg_argv[0];
begin
  if new.image_path is null then
    return new;
  end if;

  if tg_op = 'UPDATE' and new.image_path is not distinct from old.image_path then
    return new;
  end if;

  if expected_kind='good' and tg_table_schema='public' and tg_table_name='goods' and tg_op='UPDATE' then
    if new.image_path=any(array_remove(array[old.detail_image_path]||coalesce(old.gallery_paths,'{}')||coalesce(old.description_image_paths,'{}'),null)) then
      return new;
    end if;
  end if;

  if expected_kind='good' and tg_table_schema='public' and tg_table_name='goods'
    and private.can_copy_goods_artwork(new.id::text,new.image_path) then return new; end if;
  if expected_kind='good' and tg_table_schema='public' and tg_table_name='goods'
    and (private.can_reuse_shared_goods_artwork(new.image_path) or private.can_reuse_own_goods_draft_artwork(new.image_path)) then return new; end if;

  if current_actor_id is null then
    if session_user = 'postgres' then
      return new;
    end if;
    raise exception 'unverified_artwork' using errcode = '23514';
  end if;

  if not public.is_staff()
    or new.image_path !~ '^public-media/catalog/(ip|good|card|event|curation)/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$'
  then
    raise exception 'unverified_artwork' using errcode = '23514';
  end if;

  object_path := substring(new.image_path from length('public-media/') + 1);
  if object_path not like 'catalog/' || expected_kind || '/%' then
    raise exception 'unverified_artwork' using errcode = '23514';
  end if;

  update public.admin_artwork_upload_claims as claim
  set
    status = 'attached',
    attached_at = clock_timestamp(),
    resolved_at = clock_timestamp()
  where claim.actor_id = current_actor_id
    and claim.path = object_path
    and claim.kind = expected_kind
    and claim.status = 'verified'
    and claim.verified_at is not null
    and claim.final_size is not null
    and claim.attached_at is null
    and claim.expires_at > clock_timestamp();

  if not found then
    raise exception 'unverified_artwork' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_admin_goods_content_artwork_claim()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid:=(select auth.uid());
  old_paths text[]:='{}';
  new_paths text[];
  candidate text;
begin
  if tg_op='UPDATE' then
    old_paths:=array_remove(array[old.image_path,old.detail_image_path]
      || coalesce(old.gallery_paths,'{}') || coalesce(old.description_image_paths,'{}'),null);
  end if;
  select coalesce(array_agg(distinct path),'{}') into new_paths
    from unnest(array_remove(array[new.detail_image_path]
      || coalesce(new.gallery_paths,'{}') || coalesce(new.description_image_paths,'{}'),null)) path;
  foreach candidate in array new_paths loop
    continue when candidate=any(old_paths);
    -- The existing main-image AFTER trigger validates this same row's image.
    continue when candidate=new.image_path;
    continue when private.can_copy_goods_artwork(new.id::text,candidate);
    continue when (private.can_reuse_shared_goods_artwork(candidate) or private.can_reuse_own_goods_draft_artwork(candidate));
    if v_actor_id is null then
      if session_user='postgres' then continue; end if;
      raise check_violation using message='unverified_artwork';
    end if;
    if not public.is_staff() or candidate !~ '^public-media/catalog/good/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](jpg|png|webp)$' then
      raise check_violation using message='unverified_artwork';
    end if;
    update public.admin_artwork_upload_claims claim set status='attached',attached_at=clock_timestamp(),resolved_at=clock_timestamp()
      where claim.actor_id=v_actor_id and claim.path=substring(candidate from length('public-media/')+1)
        and claim.kind='good' and claim.status='verified' and claim.verified_at is not null
        and claim.final_size is not null and claim.attached_at is null and claim.expires_at>clock_timestamp();
    if not found then raise check_violation using message='unverified_artwork'; end if;
  end loop;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.enqueue_email_intent_batch(target_intents jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_length integer;
  v_item record;
  v_outcomes jsonb := '{}'::jsonb;
  v_outcome jsonb;
begin
  if pg_catalog.jsonb_typeof(target_intents) is distinct from 'array' then
    raise check_violation using message = 'invalid_email_dispatch_batch';
  end if;
  v_length := pg_catalog.jsonb_array_length(target_intents);
  if v_length < 1 or v_length > 10 then
    raise check_violation using message = 'invalid_email_dispatch_batch_size';
  end if;
  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(target_intents) as entry(item)
    group by item ->> 'source', item ->> 'sourceReferenceDigest'
    having pg_catalog.count(*) > 1
  ) then
    raise unique_violation using message = 'duplicate_email_dispatch_batch_source';
  end if;

  -- Stable ordering avoids advisory-lock inversion when the same batch races.
  for v_item in
    select entry.item, entry.ordinality
    from pg_catalog.jsonb_array_elements(target_intents)
      with ordinality as entry(item, ordinality)
    order by entry.item ->> 'source', entry.item ->> 'sourceReferenceDigest'
  loop
    if pg_catalog.jsonb_typeof(v_item.item) is distinct from 'object' then
      raise check_violation using message = 'invalid_email_dispatch_batch_item';
    end if;
    v_outcome := public.enqueue_email_intent(
      v_item.item ->> 'source',
      v_item.item ->> 'sourceReferenceDigest',
      v_item.item ->> 'recipientDigest',
      v_item.item ->> 'messageKind',
      v_item.item ->> 'contentRevision'
    );
    v_outcomes := pg_catalog.jsonb_set(
      v_outcomes,
      array[(v_item.ordinality - 1)::text],
      v_outcome,
      true
    );
  end loop;

  return (
    select pg_catalog.jsonb_agg(
      v_outcomes -> ((position.index - 1)::text)
      order by position.index
    )
    from pg_catalog.generate_series(1, v_length) as position(index)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_email_intent(target_source text, target_source_reference_digest text, target_recipient_digest text, target_message_kind text, target_content_revision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_digest bytea:=private.email_digest_from_hex(target_source_reference_digest);
 recipient_digest bytea:=private.email_digest_from_hex(target_recipient_digest);intent private.email_intents%rowtype;created boolean:=false;
begin
 if target_source not in ('auth_hook','account_deletion','order_delay_notice','operator_invitation','stock_safety_digest') then raise check_violation using message='invalid_email_source';end if;
 if target_message_kind not in ('auth_signup','auth_recovery','auth_email_change_current','auth_email_change_new','auth_reauthentication','account_deletion_notice','order_delay_notice','operator_invitation','stock_safety_digest')
 then raise check_violation using message='invalid_email_message_kind';end if;
 if (target_source='order_delay_notice') is distinct from (target_message_kind='order_delay_notice') then raise check_violation using message='invalid_email_message_kind';end if;
 if (target_source='operator_invitation') is distinct from (target_message_kind='operator_invitation') then raise check_violation using message='invalid_email_message_kind';end if;
 if (target_source='stock_safety_digest') is distinct from (target_message_kind='stock_safety_digest') then raise check_violation using message='invalid_email_message_kind';end if;
 if target_content_revision is null or target_content_revision !~ '^[a-z0-9_]{1,80}$' then raise check_violation using message='invalid_email_content_revision';end if;
 perform pg_advisory_xact_lock(hashtextextended('email_intent:'||target_source||':'||encode(source_digest,'hex'),0));
 select * into intent from private.email_intents i where i.source=target_source and i.source_reference_digest=source_digest for update;
 if found then
  if intent.recipient_digest is distinct from recipient_digest or intent.message_kind is distinct from target_message_kind or intent.content_revision is distinct from target_content_revision
   then raise unique_violation using message='email_intent_idempotency_conflict';end if;
 else
  insert into private.email_intents(source,source_reference_digest,recipient_digest,message_kind,content_revision)
   values(target_source,source_digest,recipient_digest,target_message_kind,target_content_revision) returning * into intent;created:=true;
 end if;
 insert into private.email_intent_fences(intent_id,source,source_reference_digest) values(intent.id,intent.source,intent.source_reference_digest) on conflict(intent_id) do nothing;
 if not exists(select 1 from private.email_intent_fences f where f.intent_id=intent.id and f.source=intent.source and f.source_reference_digest=intent.source_reference_digest)
  then raise integrity_constraint_violation using message='email_intent_fence_missing';end if;
 return jsonb_build_object('kind',case when created then 'enqueued' else 'existing' end,'intentId',intent.id,'idempotencyKey',intent.idempotency_key,'state',intent.state);
end $function$

CREATE OR REPLACE FUNCTION public.exchange_coins_for_draw_tickets(p_operation_id uuid, p_offer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := (select auth.uid());
  v_offer public.coin_exchange_offers%rowtype;
  v_ledger_owner uuid;
  v_ledger_offer uuid;
  v_balance integer;
  v_issued integer;
  v_existing_count integer;
begin
  if v_user is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_user
      and profile.suspended_at is not null
  ) then
    raise exception 'account_suspended' using errcode = '55000';
  end if;

  -- 탈퇴 신청으로 쓰기가 봉인된 계정(20260813193000 의 계정 fence 관례).
  if private.is_account_write_fenced(v_user) then
    raise object_not_in_prerequisite_state
      using message = 'account_deletion_write_fenced';
  end if;

  if p_operation_id is null then
    raise exception 'invalid_operation' using errcode = '22004';
  end if;

  -- 응답이 유실된 재시도는 먼저 커밋된 원장을 관측한 뒤에 판단해야 한다
  -- (admin_grant_draw_tickets와 같은 관용구). 잠금이 없으면 두 재시도가 모두
  -- "없음"을 보고 각자 차감한 뒤 하나가 unique 위반으로 되돌아간다.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('coin_exchange:' || p_operation_id::text, 0)
  );

  select ledger.user_id, ledger.offer_id
    into v_ledger_owner, v_ledger_offer
  from public.coin_ledger as ledger
  where ledger.operation_id = p_operation_id;

  if found then
    -- 남의 멱등 키를 재생해 잔액·발급 수를 읽어 가는 경로를 막는다.
    if v_ledger_owner is distinct from v_user then
      raise exception 'exchange_operation_conflict' using errcode = '23505';
    end if;

    -- 같은 키인데 다른 상품이면 재시도가 아니라 다른 요청이다. 캠페인 한 장에
    -- 교환 블록이 여러 개일 때 화면이 키를 공유하면 여기로 온다 — already_exchanged
    -- 로 답하면 두 번째 상품은 교환되지 않았는데 성공으로 읽힌다.
    if v_ledger_offer is distinct from p_offer_id then
      raise exception 'exchange_operation_conflict' using errcode = '23505',
        detail = 'operation_id is bound to a different offer';
    end if;

    select coalesce(balance, 0) into v_balance
    from public.coin_balances
    where user_id = v_user;

    select count(*)::integer into v_existing_count
    from public.draw_tickets as ticket
    where ticket.source = 'coin_exchange'
      and ticket.source_id = p_operation_id;

    -- 이미 성립한 교환의 재생은 캠페인 상태를 다시 묻지 않는다. 커밋된 사실을
    -- 나중의 편성 변경으로 뒤집으면, 응답만 유실된 사용자가 발급받은 카드팩을
    -- 설명할 수 없는 상태가 된다.
    return jsonb_build_object(
      'status', 'already_exchanged',
      'balance', coalesce(v_balance, 0),
      'issued_count', v_existing_count
    );
  end if;

  select offer.*
    into v_offer
  from public.coin_exchange_offers as offer
  where offer.id = p_offer_id
  for share;

  if not found or v_offer.status <> 'active' then
    raise exception 'offer_unavailable' using errcode = 'P0002';
  end if;

  -- 노출 경로 확인. sections는 admin_upsert_campaign의 검증을 통과한 배열이라
  -- exchange 블록의 offer_id는 uuid 문자열이다. 대소문자만 정규화한다 —
  -- 검증 정규식이 대소문자를 가리지 않아 대문자 uuid도 저장될 수 있다.
  if not exists (
    select 1
    from public.campaigns as campaign,
      lateral pg_catalog.jsonb_array_elements(campaign.sections) as section(entry)
    where campaign.status = 'published'
      and campaign.starts_at <= now()
      and now() < campaign.ends_at
      and section.entry ->> 'type' = 'exchange'
      and pg_catalog.lower(section.entry ->> 'offer_id') = p_offer_id::text
  ) then
    raise exception 'offer_unavailable' using errcode = 'P0002';
  end if;

  perform private.assert_card_pool_ready(v_offer.pool_id);

  -- 직렬화 지점. 두 세션이 같은 잔액을 노리면 뒤에 온 쪽은 잠금 해제 후 갱신된
  -- 행으로 조건을 다시 평가해 0행을 얻는다 — 초과 인출이 성립할 창이 없다.
  update public.coin_balances
  set balance = balance - v_offer.coin_cost,
      updated_at = now()
  where user_id = v_user
    and balance >= v_offer.coin_cost
  returning balance into v_balance;

  if not found then
    raise exception 'insufficient_coins';
  end if;

  insert into public.coin_ledger (user_id, amount, reason, operation_id, offer_id)
  values (v_user, -v_offer.coin_cost, 'exchange', p_operation_id, v_offer.id);

  -- source_id = operation_id 라서 unique (source, source_id, ordinal)이 재시도
  -- 이중 발급을 DB 레벨에서 한 번 더 막는다.
  insert into public.draw_tickets (user_id, pool_id, source, source_id, ordinal)
  select v_user, v_offer.pool_id, 'coin_exchange', p_operation_id, issue_series.n
  from pg_catalog.generate_series(1, v_offer.ticket_count) as issue_series(n);

  get diagnostics v_issued = row_count;

  -- 게이트가 행을 삼켰다. 코인 차감·원장·잔액까지 전부 되돌린다.
  if v_issued <> v_offer.ticket_count then
    raise exception 'card_rewards_disabled' using errcode = '55000';
  end if;

  -- 알림은 draw_tickets STATEMENT 트리거(20260716090001)가 보낸다. 여기서 직접
  -- 넣으면 발급 한 건에 알림이 두 번 간다.
  return jsonb_build_object(
    'status', 'exchanged',
    'balance', v_balance,
    'issued_count', v_issued
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.expire_stale_checkouts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_count integer := 0;
  v_can_expire boolean;
  v_expired_prepared_transitioned boolean;
  v_cancel_reason text;
  v_request_id uuid;
  v_request_outcome text;
  r record;
  v_request record;
  v_attempt public.payment_attempts%rowtype;
  v_failed integer := 0;
  v_failed_state text;
  v_failed_refs text[] := array[]::text[];
begin
  for r in
    select orders.id
    from public.orders
    where orders.status = 'pending'
      and orders.expires_at is not null
      and orders.expires_at < now() - interval '5 minutes'
      and not exists (
        select 1
        from public.payments as payment
        where payment.purpose = 'order'
          and payment.ref_id = orders.id
          and payment.status in ('pending', 'paid')
      )
      and not exists (
        select 1
        from public.order_cancellation_requests as request
        where request.order_id = orders.id
          and request.status in ('processing', 'needs_review')
      )
      and not exists (
        select 1
        from public.payment_attempts as attempt
        where attempt.purpose = 'order'
          and attempt.ref_id = orders.id
          and attempt.state in ('confirming', 'unknown', 'needs_review', 'approved')
      )
    order by orders.expires_at
    limit 200
    for update of orders skip locked
  loop
  begin
    v_can_expire := true;
    v_expired_prepared_transitioned := false;
    v_cancel_reason := '결제 시간 만료 자동 취소';
    v_request_id := null;
    v_request_outcome := null;

    -- The baseline partial unique index guarantees one attempt per goods
    -- order. Locking it only after the order matches claim/finalize exactly.
    select attempt.*
    into v_attempt
    from public.payment_attempts as attempt
    where attempt.purpose = 'order'
      and attempt.ref_id = r.id
    for update;

    if found then
      if v_attempt.state = 'prepared' then
        if v_attempt.expires_at > pg_catalog.clock_timestamp() then
          v_can_expire := false;
        else
          update public.payment_attempts as attempt
          set
            state = 'canceled',
            claim_token = null,
            claim_expires_at = null
          where attempt.id = v_attempt.id
            and attempt.state = 'prepared'
            and attempt.expires_at <= pg_catalog.clock_timestamp()
          returning true into v_expired_prepared_transitioned;

          if not coalesce(v_expired_prepared_transitioned, false) then
            v_can_expire := false;
          end if;
        end if;
      elsif v_attempt.state in (
        'confirming',
        'unknown',
        'needs_review',
        'approved'
      ) then
        -- Defensive recheck after locking: a callback may have won after the
        -- candidate snapshot but before this transaction acquired the order.
        v_can_expire := false;
      end if;
    end if;

    if not v_can_expire then
      continue;
    end if;

    -- A user can request cancellation while the provider action is still
    -- valid. That request intentionally holds inventory until the attempt TTL
    -- proves the provider can no longer claim it. Lock and finish that durable
    -- request in this same transaction; the compatibility cancel_order wrapper
    -- correctly rejects active requests and therefore is used only when none
    -- exists.
    select request.id, request.reason
    into v_request
    from public.order_cancellation_requests as request
    where request.order_id = r.id
      and request.status = 'requested'
    order by request.requested_at desc, request.id desc
    limit 1
    for update;

    if found then
      -- A durable request is provider-sensitive evidence. Close it only when
      -- this exact order→attempt critical section proved the action TTL and
      -- performed prepared→canceled itself, or when the locked attempt already
      -- ended without capture (declined/canceled, no payment row, no non-failed
      -- ledger). The latter used to continue forever: a request accepted while
      -- the provider confirm was in flight stayed requested after a decline and
      -- held stock, coupons and store credit indefinitely (2026-10-12 audit).
      -- An absent attempt or a legacy failed-ledger order is still not proof.
      if not v_expired_prepared_transitioned
        and not (
          v_attempt.id is not null
          and v_attempt.state in ('declined', 'canceled')
          and v_attempt.payment_id is null
          and not exists (
            select 1
            from public.payments as payment
            where payment.purpose = 'order'
              and payment.ref_id = r.id
              and payment.status <> 'failed'
          )
        )
      then
        continue;
      end if;

      v_request_id := v_request.id;
      v_cancel_reason := v_request.reason;
      -- 구매자 알림 문구를 가르는 결과. 이 임계 구역이 만료를 증명했으면 결제창이
      -- 결제 기한까지 끝나지 않은 것이고, 아니면 잠근 attempt가 결제 없이 끝난 것이다.
      v_request_outcome := case
        when v_expired_prepared_transitioned then 'expired'
        else v_attempt.state::text
      end;
    end if;

    if v_request_id is null then
      perform public.cancel_order(r.id, v_cancel_reason);
    else
      perform public.finalize_order_cancellation_with_provider_evidence(
        r.id,
        v_cancel_reason,
        array[]::text[]
      );

      update public.order_cancellation_requests as request
      set
        status = 'completed',
        completed_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
      where request.id = v_request_id
        and request.status = 'requested';

      -- 구매자는 "담당자가 확인한 뒤 진행 상황을 알려드립니다"를 받은 채 기다리고
      -- 있었다. 담당자 없이 sweep이 닫았으므로 결과를 직접 알리고, 같은 결과를
      -- finalizer의 결제 없는 종결과 같은 감사 행으로 남긴다(2026-10-12 QA-7).
      insert into public.audit_log (actor_id, action, target, diff)
      values (
        null,
        'system.order.cancellation_completed',
        'order:' || r.id::text,
        pg_catalog.jsonb_build_object(
          'requestId', v_request_id,
          'to', 'completed',
          'refundCount', 0,
          'attemptOutcome', v_request_outcome,
          'trigger', 'checkout_expiry_sweep',
          'actor', 'system'
        )
      );

      perform private.notify_order_claim(
        v_request_id,
        'completed',
        '주문이 취소됐어요',
        case v_request_outcome
          when 'expired' then '결제 기한까지 결제가 완료되지 않아 결제 없이 주문을 취소했습니다.'
          when 'declined' then '결제가 승인되지 않아 결제 없이 주문을 취소했습니다.'
          else '결제가 취소되어 주문을 취소했습니다.'
        end
      );
    end if;

    v_count := v_count + 1;
  exception when others then
    get stacked diagnostics v_failed_state = returned_sqlstate;
    v_failed := v_failed + 1;
    if cardinality(v_failed_refs) < 5 then v_failed_refs := v_failed_refs || ('order:' || r.id::text); end if;
  end;
  end loop;

  -- Ticket checkout follows the same lock order and attempt-TTL proof. A
  -- durable cancellation request is completed only when this critical section
  -- itself transitions its expired prepared attempt to canceled.
  for r in
    select ticket_orders.id
    from public.ticket_orders
    where ticket_orders.status = 'pending'
      and ticket_orders.expires_at is not null
      and ticket_orders.expires_at < now() - interval '5 minutes'
      and not exists (
        select 1 from public.payments as payment
        where payment.purpose = 'ticket'
          and payment.ref_id = ticket_orders.id
          and payment.status in ('pending', 'paid')
      )
      and not exists (
        select 1 from public.ticket_cancellation_requests as request
        where request.ticket_order_id = ticket_orders.id
          and request.status in ('processing', 'needs_review')
      )
      and not exists (
        select 1 from public.payment_attempts as attempt
        where attempt.purpose = 'ticket'
          and attempt.ref_id = ticket_orders.id
          and attempt.state in ('confirming', 'unknown', 'needs_review', 'approved')
      )
    order by ticket_orders.expires_at
    limit 200
    for update of ticket_orders skip locked
  loop
  begin
    v_can_expire := true;
    v_expired_prepared_transitioned := false;
    v_request_id := null;

    select attempt.*
    into v_attempt
    from public.payment_attempts as attempt
    where attempt.purpose = 'ticket'
      and attempt.ref_id = r.id
    for update;

    if found then
      if v_attempt.state = 'prepared' then
        if v_attempt.expires_at > pg_catalog.clock_timestamp() then
          v_can_expire := false;
        else
          update public.payment_attempts as attempt
          set
            state = 'canceled',
            claim_token = null,
            claim_expires_at = null
          where attempt.id = v_attempt.id
            and attempt.state = 'prepared'
            and attempt.expires_at <= pg_catalog.clock_timestamp()
          returning true into v_expired_prepared_transitioned;

          if not coalesce(v_expired_prepared_transitioned, false) then
            v_can_expire := false;
          end if;
        end if;
      elsif v_attempt.state in (
        'confirming',
        'unknown',
        'needs_review',
        'approved'
      ) then
        v_can_expire := false;
      end if;
    end if;

    if not v_can_expire then
      continue;
    end if;

    select request.id, request.requested_by
    into v_request
    from public.ticket_cancellation_requests as request
    where request.ticket_order_id = r.id
      and request.status = 'requested'
    order by request.requested_at desc, request.id desc
    limit 1
    for update;

    if found then
      if not v_expired_prepared_transitioned then
        continue;
      end if;

      v_request_id := v_request.id;
    end if;

    if v_request_id is null then
      perform public.refund_ticket_order(r.id, '결제 시간 만료 자동 취소');
    else
      perform public.finalize_ticket_cancellation_request(
        v_request_id,
        v_request.requested_by
      );
    end if;

    v_count := v_count + 1;
  exception when others then
    get stacked diagnostics v_failed_state = returned_sqlstate;
    v_failed := v_failed + 1;
    if cardinality(v_failed_refs) < 5 then v_failed_refs := v_failed_refs || ('ticket_order:' || r.id::text); end if;
  end;
  end loop;
  if v_failed > 0 then
    begin
      perform private.record_system_job_failure('expire-stale-checkouts', 'pg_cron', '결제 기한 만료 정리', null, null,
        'sqlstate_' || coalesce(v_failed_state, 'unknown'),
        pg_catalog.jsonb_build_object('skipped', v_failed, 'targets', pg_catalog.to_jsonb(v_failed_refs)));
    exception when others then
      raise warning 'expire_stale_checkouts skipped % rows; failure record unavailable', v_failed;
    end;
  end if;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_goods_manual_payment_recovery(p_attempt_id uuid, p_actor_id uuid, p_request_id uuid, p_case_ref text, p_operation text, p_claim_token uuid, p_operator_attested boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order_id uuid;
  v_order public.orders%rowtype;
  v_request public.order_cancellation_requests%rowtype;
  v_attempt public.payment_attempts%rowtype;
  v_manual_claim private.goods_payment_manual_recovery_claims%rowtype;
  v_terminal private.goods_payment_manual_recovery_audits%rowtype;
  v_payment public.payments%rowtype;
  v_cancellation_claim public.order_cancellation_claims%rowtype;
  v_provider_keys text[] := array[]::text[];
  v_final_attempt_state public.payment_attempt_state;
  v_has_payment boolean := false;
begin
  if p_attempt_id is null
    or p_actor_id is null
    or p_request_id is null
    or p_claim_token is null
    or p_operation is distinct from 'provider_cancel_confirmed'
    or p_case_ref is null
    or p_case_ref !~ '^case_v1_[0-9a-f]{32}$'
    or p_operator_attested is distinct from true
  then
    raise invalid_parameter_value using
      message = 'goods_manual_recovery_attestation_invalid';
  end if;

  if not private.can_finish_operator_manual_recovery(p_attempt_id,p_request_id,p_actor_id,p_operation,p_case_ref,p_claim_token) then
    raise insufficient_privilege using message = 'admin required';
  end if;

  select attempt.ref_id
  into v_order_id
  from public.payment_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.provider = 'korpay'
    and attempt.purpose = 'order';

  if v_order_id is null then
    raise no_data_found using message = 'goods_payment_attempt_not_found';
  end if;

  -- Keep the same global lock order as claim and cancellation writers.
  select order_record.*
  into v_order
  from public.orders as order_record
  where order_record.id = v_order_id
  for update;

  if not found then
    raise no_data_found using message = 'goods_order_not_found';
  end if;

  select request.*
  into v_request
  from public.order_cancellation_requests as request
  where request.id = p_request_id
    and request.order_id = v_order.id
  for update;

  if not found then
    raise no_data_found using message = 'cancellation_request_not_found';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.provider = 'korpay'
    and attempt.purpose = 'order'
    and attempt.ref_id = v_order.id
  for update;

  if not found then
    raise no_data_found using message = 'goods_payment_attempt_not_found';
  end if;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'order'
    and payment.ref_id = v_order.id
  order by payment.id
  for update;

  select audit.*
  into v_terminal
  from private.goods_payment_manual_recovery_audits as audit
  where audit.attempt_id = v_attempt.id
    and audit.operation = p_operation;

  if found then
    if v_terminal.order_id is distinct from v_order.id
      or v_terminal.request_id is distinct from v_request.id
    then
      raise object_not_in_prerequisite_state using
        message = 'goods_manual_recovery_terminal_mismatch';
    end if;
    return v_terminal.outcome;
  end if;

  perform private.assert_claim_collections_complete(v_request.id);

  if v_request.status not in ('processing', 'needs_review') then
    raise object_not_in_prerequisite_state using
      message = 'cancellation_request_not_recoverable';
  end if;

  if v_attempt.user_id is distinct from v_order.user_id
    or v_attempt.amount is distinct from v_order.total
    or v_attempt.currency is distinct from 'KRW'
    or v_request.requested_by is distinct from v_order.user_id
    or not private.goods_order_snapshot_matches(
      v_order.id,
      v_order.total,
      v_order.shipping_fee
    )
  then
    raise object_not_in_prerequisite_state using
      message = 'goods_manual_recovery_order_attempt_mismatch';
  end if;

  select claim.*
  into v_cancellation_claim
  from public.order_cancellation_claims as claim
  where claim.order_id = v_order.id
  for update;

  if not found
    or v_cancellation_claim.requested_by is distinct from v_request.requested_by
  then
    raise object_not_in_prerequisite_state using
      message = 'cancellation_claim_required';
  end if;

  select claim.*
  into v_manual_claim
  from private.goods_payment_manual_recovery_claims as claim
  where claim.attempt_id = v_attempt.id
  for update;

  if not found
    or v_manual_claim.order_id is distinct from v_order.id
    or v_manual_claim.request_id is distinct from v_request.id
    or v_manual_claim.actor_id is distinct from p_actor_id
    or v_manual_claim.operation is distinct from p_operation
    or v_manual_claim.case_ref is distinct from p_case_ref
    or v_manual_claim.claim_token is distinct from p_claim_token
  then
    raise object_not_in_prerequisite_state using
      message = 'goods_manual_recovery_claim_invalid';
  end if;

  if v_manual_claim.prior_attempt_state in ('confirming', 'unknown', 'needs_review') then
    if v_attempt.state is distinct from 'confirming'
      or v_attempt.claim_token is distinct from p_claim_token
    then
      raise object_not_in_prerequisite_state using
        message = 'goods_manual_recovery_attempt_claim_invalid';
    end if;

    v_final_attempt_state := public.finalize_goods_payment_attempt(
      v_attempt.id,
      p_claim_token,
      'canceled'::public.payment_attempt_state
    );

    if v_final_attempt_state is distinct from 'canceled' then
      raise object_not_in_prerequisite_state using
        message = 'goods_manual_recovery_attempt_not_canceled';
    end if;

    -- An ambiguous attempt does not prove that an approved provider payment
    -- ever existed. Close only the attempt and preserve the absence of payment
    -- and refund rows instead of synthesizing provider history.
    if exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'order'
        and payment.ref_id = v_order.id
        and payment.status <> 'failed'
    ) then
      raise object_not_in_prerequisite_state using
        message = 'goods_manual_recovery_payment_ambiguous';
    end if;
  elsif v_manual_claim.prior_attempt_state = 'approved' then
    if v_attempt.state is distinct from 'approved'
      or v_attempt.payment_id is null
    then
      raise object_not_in_prerequisite_state using
        message = 'goods_approved_payment_evidence_invalid';
    end if;

    select payment.*
    into v_payment
    from public.payments as payment
    where payment.id = v_attempt.payment_id;

    if not found
      or v_payment.user_id is distinct from v_attempt.user_id
      or v_payment.purpose is distinct from 'order'
      or v_payment.ref_id is distinct from v_order.id
      or v_payment.provider is distinct from 'korpay'
      or v_payment.amount is distinct from v_attempt.amount
      or v_payment.idempotency_key is distinct from 'attempt:' || v_attempt.id::text
      or v_payment.status not in ('paid', 'canceled', 'refunded')
      or v_payment.raw is not null
      or (v_payment.status = 'paid' and v_payment.payment_key is null)
      or exists (
        select 1
        from public.payments as other_payment
        where other_payment.purpose = 'order'
          and other_payment.ref_id = v_order.id
          and other_payment.id <> v_payment.id
          and other_payment.status <> 'failed'
      )
    then
      raise object_not_in_prerequisite_state using
        message = 'goods_approved_payment_evidence_invalid';
    end if;

    if v_payment.status = 'paid' then
      v_provider_keys := array[v_payment.payment_key];
    end if;
    v_has_payment := true;
  else
    raise object_not_in_prerequisite_state using
      message = 'goods_manual_recovery_prior_state_invalid';
  end if;

  perform public.finalize_order_cancellation_with_provider_evidence(
    v_order.id,
    v_request.reason,
    v_provider_keys
  );

  if v_has_payment then
    update public.refunds as refund
    set cancellation_request_id = v_request.id
    where refund.payment_id = v_payment.id
      and (
        refund.cancellation_request_id is null
        or refund.cancellation_request_id = v_request.id
      );

    if not exists (
      select 1
      from public.refunds as refund
      where refund.payment_id = v_payment.id
        and refund.cancellation_request_id = v_request.id
        and refund.amount = v_payment.amount
        and refund.status = 'done'
    ) then
      raise object_not_in_prerequisite_state using
        message = 'goods_manual_recovery_refund_invalid';
    end if;
  end if;

  update public.order_cancellation_requests as request
  set
    status = 'completed',
    last_error_code = null,
    completed_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where request.id = v_request.id;

  insert into private.goods_payment_manual_recovery_audits (
    attempt_id,
    order_id,
    request_id,
    actor_id,
    operation,
    case_ref,
    prior_attempt_state,
    outcome
  )
  values (
    v_attempt.id,
    v_order.id,
    v_request.id,
    p_actor_id,
    p_operation,
    p_case_ref,
    v_manual_claim.prior_attempt_state,
    'provider_cancel_confirmed'
  );

  delete from private.goods_payment_manual_recovery_claims as claim
  where claim.attempt_id = v_attempt.id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_actor_id,
    'admin.payment.goods_manual_provider_cancel_confirmed',
    'order:' || v_order.id::text,
    pg_catalog.jsonb_build_object(
      'attemptId', v_attempt.id,
      'requestId', v_request.id,
      'operation', p_operation,
      'caseRef', p_case_ref,
      'outcome', 'provider_cancel_confirmed'
    )
  );

  return 'provider_cancel_confirmed';
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_order_cancellation_with_provider_evidence(p_order_id uuid, p_reason text, p_provider_payment_keys text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.order_status;
  v_provider_payment_keys text[] := coalesce(
    array_remove(p_provider_payment_keys, null),
    array[]::text[]
  );
  v_item record;
begin
  if exists(select 1 from public.payments where purpose='order' and ref_id=p_order_id and provider='bank_transfer' and status<>'failed') then
    perform private.finalize_bank_transfer_claim_refund(p_order_id,p_reason);
    return;
  end if;
  select orders.status
  into v_status
  from public.orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise no_data_found using message = 'order not found';
  end if;

  perform s.id from public.order_shipments s where s.order_id=p_order_id order by s.id for update;
  perform private.assert_order_collections_complete(p_order_id);

  if v_status not in (
    'pending', 'paid', 'confirmed', 'shipping', 'delivered', 'done', 'canceled'
  ) then
    raise exception using
      errcode = 'P0001',
      message = 'order not cancelable';
  end if;

  -- 배송이 나간 뒤의 취소는 staff 결정이 남긴 durable claim이 반드시 선행한다.
  -- claim이 없다는 것은 승인 경로 밖에서 들어왔다는 뜻이므로 거절한다.
  if v_status in ('shipping', 'delivered', 'done') and not exists (
    select 1
    from public.order_cancellation_claims as claim
    where claim.order_id = p_order_id
  ) then
    raise exception using
      errcode = 'P0001',
      message = 'order not cancelable';
  end if;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'order'
    and payment.ref_id = p_order_id
  order by payment.id
  for update;

  if exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'order'
      and payment.ref_id = p_order_id
      and payment.status in ('pending', 'paid')
      and (
        payment.payment_key is null
        or not (payment.payment_key = any(v_provider_payment_keys))
      )
  ) then
    raise exception using
      errcode = 'P0001',
      message = 'provider cancellation required';
  end if;

  if v_status in ('paid', 'confirmed', 'shipping', 'delivered', 'done')
    and not exists (
      select 1
      from public.payments as payment
      where payment.purpose = 'order'
        and payment.ref_id = p_order_id
        and (
          payment.status in ('canceled', 'refunded')
          or payment.payment_key = any(v_provider_payment_keys)
        )
    )
  then
    raise exception using
      errcode = 'P0001',
      message = 'payment evidence required';
  end if;

  if v_status <> 'canceled' then
    for v_item in
      select order_item.id, order_item.good_id, order_item.qty, private.order_item_stock_variant(order_item.id) as variant_id
      from public.order_items as order_item
      where order_item.order_id = p_order_id
      order by order_item.good_id, order_item.id
    loop
      perform private.restore_order_item_supply(v_item.id,p_reason);
    end loop;

    perform ticket.id
    from public.draw_tickets as ticket
    where ticket.source = 'order_paid'
      and ticket.source_id = p_order_id
      and ticket.consumed_at is null
      and ticket.revoked_at is null
    order by ticket.id
    for update;

    update public.draw_tickets as ticket
    set revoked_at = now()
    where ticket.source = 'order_paid'
      and ticket.source_id = p_order_id
      and ticket.consumed_at is null
      and ticket.revoked_at is null;
  end if;

  insert into public.refunds (payment_id, amount, reason, status)
  select
    payment.id,
    -- 확정 환불액(ADR-0031): 차감 결정이 없거나 전액 환불로 돌렸으면 결제액, 결제사 부분 취소를 확인했으면 '결제액 − 차감액'.
    private.claim_refund_settled_amount(payment.id),
    p_reason,
    'done'
  from public.payments as payment
  where payment.purpose = 'order'
    and payment.ref_id = p_order_id
    and (
      payment.status in ('canceled', 'refunded')
      or payment.payment_key = any(v_provider_payment_keys)
    )
  on conflict (payment_id) do update
  set
    amount = excluded.amount,
    reason = coalesce(public.refunds.reason, excluded.reason),
    status = 'done';

  update private.claim_refund_deductions as deduction
  set state = 'applied', applied_at = coalesce(deduction.applied_at, clock_timestamp())
  where deduction.order_id = p_order_id
    and deduction.state = 'provider_confirmed';

  update public.payments as payment
  set status = 'refunded'
  where payment.purpose = 'order'
    and payment.ref_id = p_order_id
    and (
      payment.status in ('canceled', 'refunded')
      or payment.payment_key = any(v_provider_payment_keys)
    );

  if v_status <> 'canceled' then
    update public.orders
    set
      status = 'canceled',
      expires_at = null
    where id = p_order_id;
  end if;

  delete from public.order_cancellation_claims
  where order_id = p_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_ticket_cancellation_request(p_request_id uuid, p_actor_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order_id uuid;
  v_order_status public.ticket_order_status;
  v_request_status text;
  v_request_source text;
  v_reservation public.ticket_order_reservations%rowtype;
  v_refund_count integer;
begin
  select request.ticket_order_id
  into v_order_id
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id;
  if v_order_id is null then
    raise no_data_found using message = 'ticket cancellation request not found';
  end if;

  select ticket_order.status
  into v_order_status
  from public.ticket_orders as ticket_order
  where ticket_order.id = v_order_id
  for update of ticket_order;
  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;

  select request.status, request.source
  into v_request_status, v_request_source
  from public.ticket_cancellation_requests as request
  where request.id = p_request_id
  for update of request;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket' and payment.ref_id = v_order_id
  order by payment.id
  for update of payment;

  perform attempt.id
  from public.payment_attempts as attempt
  where attempt.purpose = 'ticket' and attempt.ref_id = v_order_id
  order by attempt.id
  for update of attempt;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = v_order_id
  order by ticket.id
  for update of ticket;

  select reservation.*
  into v_reservation
  from public.ticket_order_reservations as reservation
  where reservation.ticket_order_id = v_order_id
  for update;
  if not found then
    raise check_violation using message = 'ticket reservation missing';
  end if;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id = v_reservation.ticket_type_id
  for update of ticket_type;

  if v_request_status = 'completed' then
    return 'completed';
  end if;
  if v_order_status = 'canceled' then
    update public.ticket_cancellation_requests
    set
      status = 'completed',
      attempt_token = null,
      completed_at = coalesce(completed_at, now()),
      last_error_code = null
    where id = p_request_id;
    return 'completed';
  end if;
  if v_order_status not in ('pending', 'paid') then
    raise check_violation using message = 'ticket order not cancelable';
  end if;

  if exists (
    select 1 from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = v_order_id
      and payment.status in ('pending', 'paid')
  ) or exists (
    select 1 from public.payment_attempts as attempt
    where attempt.purpose = 'ticket'
      and attempt.ref_id = v_order_id
      and attempt.state in ('prepared', 'confirming', 'approved', 'unknown', 'needs_review')
  ) then
    return 'processing';
  end if;

  if v_order_status = 'paid' and not exists (
    select 1
    from public.payments as payment
    join public.refunds as refund on refund.payment_id = payment.id
    where payment.purpose = 'ticket'
      and payment.ref_id = v_order_id
      and payment.status = 'refunded'
      and refund.status = 'done'
  ) then
    raise check_violation using message = 'payment evidence required';
  end if;

  if exists (
    select 1 from public.tickets as ticket
    where ticket.ticket_order_id = v_order_id and ticket.status = 'used'
  ) then
    update public.ticket_cancellation_requests
    set
      status = 'needs_review',
      attempt_token = null,
      last_error_code = 'used_ticket_after_provider_cancellation'
    where id = p_request_id;
    return 'needs_review';
  end if;

  update public.payment_attempts
  set
    state = 'canceled',
    claim_token = null,
    claim_expires_at = null
  where purpose = 'ticket'
    and ref_id = v_order_id
    and state = 'prepared';

  update public.ticket_types
  set sold = sold - v_reservation.quantity
  where id = v_reservation.ticket_type_id;

  update public.tickets
  set status = 'refunded'
  where ticket_order_id = v_order_id;

  update public.ticket_orders
  set status = 'canceled', expires_at = null
  where id = v_order_id;

  update public.ticket_cancellation_requests
  set
    status = 'completed',
    attempt_token = null,
    completed_at = coalesce(completed_at, now()),
    last_error_code = null
  where id = p_request_id;

  select count(*)::integer
  into v_refund_count
  from public.refunds as refund
  where refund.ticket_cancellation_request_id = p_request_id
    and refund.status = 'done';

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_actor_id,
    'ticket.cancellation.completed',
    'ticket_order:' || v_order_id::text,
    jsonb_build_object(
      'requestId', p_request_id,
      'source', v_request_source,
      'to', 'completed',
      'refundCount', v_refund_count
    )
  );
  return 'completed';
end;
$function$

CREATE OR REPLACE FUNCTION public.finish_order_delay_email_job(target_id uuid, target_claim uuid, target_status text, target_error text, target_retryable boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t private.order_delay_notice_targets%rowtype;i private.email_intents%rowtype;status text:=target_status;code text:=target_error;can_retry boolean:=target_retryable;
begin
 if target_status is null or target_status not in ('sent','queued','failed','unknown','suppressed') or target_retryable is null
  or target_error is not null and target_error not in ('provider_suppressed','provider_rejected','delivery_disabled','delivery_in_progress','delivery_needs_review','delivery_outcome_unknown','provider_retryable','provider_not_configured')
 then raise invalid_parameter_value using message='invalid_delay_email_result';end if;
 select * into t from private.order_delay_notice_targets where id=target_id for update;
 if not found or t.email_status<>'processing' or t.claim_token is distinct from target_claim then return false;end if;
 select * into i from private.email_intents where id=t.email_intent_id for update;
 if i.state in ('accepted','sent','delivered','delayed') then status:='sent';code:=null;can_retry:=false;
 elsif i.state in ('bounced','complained','failed') then status:='failed';code:='provider_rejected';can_retry:=false;
 elsif i.state='suppressed' then status:='suppressed';code:='provider_suppressed';can_retry:=false;
 elsif i.state='needs_review' then status:='unknown';code:='delivery_needs_review';can_retry:=false;
 elsif status='sent' then raise check_violation using message='delay_notice_acceptance_required';
 end if;
 update private.order_delay_notice_targets set email_status=status,error_code=code,retryable=can_retry and status='failed',
  available_at=case when status='queued' or status='unknown' and code='delivery_outcome_unknown' then now()+interval '2 minutes' else null end,
  claim_token=null,lease_until=null,updated_at=now() where id=t.id;
 insert into public.audit_log(actor_id,action,target,diff) values(null,'system.order.delay_notice_email_result','delay_notice_target:'||t.id,
  jsonb_build_object('status',status,'errorCode',code,'retryable',can_retry,'attempts',t.attempts));
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.finish_order_delay_sms_job(p_target_id uuid, p_claim uuid, p_status text, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job private.order_delay_notice_sms_jobs%rowtype;
begin
  if p_target_id is null or p_claim is null or p_status is null or p_status not in ('sent','failed','skipped')
   or (p_status='sent')<>(p_reason is null)
   or (p_reason is not null and p_reason not in ('sms_disabled','consent_required','no_verified_phone','account_unavailable','provider_unavailable','invalid_body'))
   or (p_status='failed' and p_reason not in ('provider_unavailable','invalid_body'))
   or (p_status='skipped' and p_reason not in ('sms_disabled','consent_required','no_verified_phone','account_unavailable'))
  then raise invalid_parameter_value using message='invalid_delay_sms_result'; end if;
  select * into job from private.order_delay_notice_sms_jobs where target_id=p_target_id for update;
  if not found or job.status<>'processing' or job.claim_token is distinct from p_claim then return false; end if;
  update private.order_delay_notice_sms_jobs set status=p_status,reason=p_reason,claim_token=null,lease_until=null,
   sent_at=case when p_status='sent' then now() end,updated_at=now() where target_id=p_target_id;
  insert into public.audit_log(actor_id,action,target,diff) values(null,'system.order.delay_notice_sms_result','delay_notice_target:'||p_target_id,
   jsonb_build_object('status',p_status,'reason',p_reason));
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.finish_shipment_email_job(target_shipment uuid, target_claim uuid, outcome text, error_code text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job public.order_shipment_email_jobs; next_status text; code text:=error_code;
begin
  if outcome is null or outcome not in ('sent','already_delivered','retry','review')
    or (error_code is not null and error_code not in ('provider_retryable','provider_not_configured','delivery_in_progress',
      'delivery_outcome_unknown','delivery_rejected','shipment_unavailable','recipient_missing')) then
    raise invalid_parameter_value using message='invalid_shipment_email_outcome';end if;
  select * into job from public.order_shipment_email_jobs where shipment_id=target_shipment for update;
  if not found or job.status<>'processing' or job.claim_token is distinct from target_claim or job.lease_until<=clock_timestamp() then
    return 'stale';end if;
  if outcome='sent' then next_status:='completed';code:=null;
  elsif outcome='already_delivered' then
    -- The existing sender also uses this result while another delivery claim is pending.
    if exists(select 1 from public.email_deliveries d
      where d.dedupe_key='order_shipped:'||job.order_id||':'||job.shipment_id and d.status='sent') then
      next_status:='completed';code:=null;
    else next_status:='pending';code:='delivery_in_progress';end if;
  elsif outcome='retry' then next_status:='pending';
  else next_status:='review';end if;
  if next_status='pending' and job.attempts>=8 then next_status:='review';end if;
  update public.order_shipment_email_jobs set status=next_status,claim_token=null,lease_until=null,last_error_code=code,
    available_at=clock_timestamp()+case when code='delivery_in_progress' then interval '15 minutes'
      else make_interval(secs=>least(3600,60*power(2,job.attempts-1))::integer) end,
    completed_at=case when next_status='completed' then clock_timestamp() end,updated_at=clock_timestamp()
    where shipment_id=target_shipment;
  return next_status;
end $function$

CREATE OR REPLACE FUNCTION public.finish_stock_safety_digest_job(target_id uuid, target_claim uuid, target_status text, target_error text, target_retryable boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d private.stock_safety_digest_deliveries%rowtype;i private.email_intents%rowtype;status text:=target_status;code text:=target_error;can_retry boolean:=target_retryable;
begin
  if target_status is null or target_status not in ('sent','queued','failed','unknown','suppressed') or target_retryable is null
    or target_error is not null and target_error not in ('provider_suppressed','provider_rejected','delivery_disabled','delivery_in_progress',
      'delivery_needs_review','delivery_outcome_unknown','provider_retryable','provider_not_configured')
  then raise invalid_parameter_value using message='invalid_stock_digest_result';end if;
  select * into d from private.stock_safety_digest_deliveries where id=target_id for update;
  if not found or d.email_status<>'processing' or d.claim_token is distinct from target_claim then return false;end if;
  select * into i from private.email_intents where id=d.email_intent_id for update;
  -- 공급사 수락이 커밋됐으면 응답 유실과 무관하게 그 결과가 이긴다.
  if i.state in ('accepted','sent','delivered','delayed') then status:='sent';code:=null;can_retry:=false;
  elsif i.state in ('bounced','complained','failed') then status:='failed';code:='provider_rejected';can_retry:=false;
  elsif i.state='suppressed' then status:='suppressed';code:='provider_suppressed';can_retry:=false;
  elsif i.state='needs_review' then status:='unknown';code:='delivery_needs_review';can_retry:=false;
  elsif status='sent' then raise check_violation using message='stock_digest_acceptance_required';
  end if;
  if status='failed' and can_retry then
    -- 재시도 가능한 실패(공급사 일시 오류·발송 설정 대기)는 10분 뒤 다시 줄을 선다. 하루가 지나면 선점 단계가 만료시킨다.
    update private.stock_safety_digest_deliveries set email_status='queued',error_code=code,retryable=true,
      available_at=clock_timestamp()+interval '10 minutes',claim_token=null,lease_until=null,updated_at=clock_timestamp()
      where id=d.id;
  else
    update private.stock_safety_digest_deliveries set email_status=status,error_code=code,retryable=false,
      available_at=case when status='queued' or (status='unknown' and code='delivery_outcome_unknown')
        then clock_timestamp()+interval '2 minutes' end,
      claim_token=null,lease_until=null,updated_at=clock_timestamp()
      where id=d.id;
  end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.follow_ip(target_ip_id text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := auth.uid();
  inserted_count integer := 0;
  current_fans_count integer := 0;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  perform 1
  from public.ips as ip
  where ip.id = target_ip_id
    and ip.archived_at is null
  for update of ip;

  if not found then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  insert into public.ip_follows (user_id, ip_id)
  values (actor_id, target_ip_id)
  on conflict (user_id, ip_id) do nothing;

  get diagnostics inserted_count = row_count;

  if inserted_count > 0 then
    update public.ips
    set fans_count = fans_count + 1,
        updated_at = now()
    where id = target_ip_id
    returning fans_count into current_fans_count;
  else
    select fans_count into current_fans_count
    from public.ips
    where id = target_ip_id;
  end if;

  return coalesce(current_fans_count, 0);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_good_attribute_rows(p_good_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare fields jsonb; entries jsonb; field jsonb; entry jsonb; label text; result jsonb:='[]';
begin
  select schema.fields,vals.entries into fields,entries from public.goods g join public.ips ip on ip.id=g.ip_id
    join public.catalog_category_attribute_schemas schema on schema.category_id=g.category_id
    join public.goods_attribute_values vals on vals.good_id=g.id
    where g.id=p_good_id and g.published_at is not null and g.archived_at is null and private.good_sale_restriction_visible(g.sale_restriction,(select auth.uid())) and ip.published_at is not null and ip.archived_at is null;
  if fields is null then return result; end if;
  for field in select value from jsonb_array_elements(fields) loop
    select e into entry from jsonb_array_elements(entries) e where e#>>'{field,id}'=field->>'id'
      and e#>>'{field,kind}'=field->>'kind' and e#>>'{field,unit}'=field->>'unit' and private.goods_attribute_value_valid(field,e->'value');
    if entry is null then continue; end if;
    if field->>'kind'='single' then select opt->>'label' into label from jsonb_array_elements(field->'options') opt where opt->'id'=entry->'value';
    elsif field->>'kind'='multi' then select string_agg(opt->>'label',', ' order by v.ordinality) into label
      from jsonb_array_elements(entry->'value') with ordinality v(value,ordinality) join jsonb_array_elements(field->'options') opt on opt->'id'=v.value;
    else label:=(entry->'value'#>>'{}')||case when field->>'unit'<>'' then ' '||(field->>'unit') else '' end; end if;
    result:=result||jsonb_build_array(jsonb_build_object('id',field->>'id','name',field->>'name','value',label));
  end loop;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.get_good_other_compositions(p_good_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; enabled boolean;
begin
 if p_good_id is null or p_good_id !~ '^[a-z0-9][a-z0-9-]{0,119}$' then
  raise invalid_parameter_value using message='invalid_other_composition_good';end if;
 select (values->>'enabled')::boolean into enabled from private.product_detail_settings where section='otherComposition';
 if not coalesce(enabled,false) then return jsonb_build_object('groups','[]'::jsonb,'nextChangeAt',null);end if;
 with matching as materialized(
  select r.* from public.goods_relations r where r.kind='other_composition' and r.enabled
   and exists(select 1 from public.goods_relation_members m where m.relation_id=r.id and m.good_id=p_good_id)
 ),public_members as materialized(
  select m.relation_id,m.good_id,m.position,m.composition_label
  from public.goods_relation_members m join matching r on r.id=m.relation_id
  join public.goods g on g.id=m.good_id join public.ips ip on ip.id=g.ip_id
  where g.archived_at is null and g.published_at is not null and private.good_sale_restriction_visible(g.sale_restriction,(select auth.uid()))
   and ip.archived_at is null and ip.published_at is not null
 ),eligible as materialized(
  select r.* from matching r where exists(select 1 from public_members m where m.relation_id=r.id and m.good_id=p_good_id)
   and exists(select 1 from public_members m where m.relation_id=r.id and m.good_id<>p_good_id)
 ),active as(
  select * from eligible where (starts_at is null or starts_at<=statement_timestamp())
   and (ends_at is null or ends_at>statement_timestamp())
 )
 select jsonb_build_object('groups',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'title',r.title,
  'goods',(select jsonb_agg(jsonb_build_object('goodId',m.good_id,'compositionLabel',m.composition_label) order by m.position)
   from public_members m where m.relation_id=r.id and m.good_id<>p_good_id)) order by r.created_at,r.id) from active r),'[]'::jsonb),
  'nextChangeAt',(select min(boundary) from eligible r cross join lateral(values(r.starts_at),(r.ends_at))changes(boundary)
   where boundary>statement_timestamp())) into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.get_good_shipping_region_fees(target_good_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  selected public.goods;
  owner public.goods;
  origin public.fulfillment_origins;
  probe_at timestamptz := statement_timestamp();
  policy private.shipping_region_policies;
  representative record;
  lines jsonb;
  destination jsonb;
  quote_group jsonb;
  fee numeric;
  fee_unit text;
  waived boolean := false;
  regions jsonb;
  region_count integer;
  next_change timestamptz;
  result jsonb;
begin
  -- 공개 배송 정책(get_good_shipping_policy)과 같은 공개 범위·같은 정책 상품·같은 출고지.
  select g.* into selected
  from public.goods g join public.ips ip on ip.id = g.ip_id
  where g.id = target_good_id and g.archived_at is null and g.published_at is not null
    and private.good_sale_restriction_visible(g.sale_restriction, (select auth.uid()))
    and ip.archived_at is null and ip.published_at is not null;
  if not found then return null; end if;
  select * into owner from public.goods where id = private.goods_aggregation_owner(selected.id);
  select * into origin from public.fulfillment_origins where id = owner.origin_id and is_active;
  if not found then return null; end if;

  -- 기존 주문 경로(quote_goods_sales_for_address)와 같은 줄 모양. 합산 관계가 있는 굿즈는
  -- 원상품의 정책을 따른다(기존 경로는 그 굿즈 주문을 막는다). 단가 0원 = 무료 기준 전.
  lines := jsonb_build_array(jsonb_build_object('origin_id', owner.origin_id, 'good_id', owner.id, 'qty', 1,
    'unit_price', 0, 'fee_type', owner.shipping_fee_type, 'individual_fee', owner.individual_fee));
  -- 정책 시작·종료·도입 시각이 오면 상세를 다시 읽는다(주소 없는 견적이 같은 경계를 낸다).
  next_change := (private.apply_shipping_region_quote(private.calculate_goods_shipping(lines), lines, null, probe_at)
    ->>'nextChangeAt')::timestamptz;
  result := jsonb_build_object('state', 'none', 'regions', '[]'::jsonb, 'regionCount', 0, 'feeUnit', null,
    'waivedAtFreeThreshold', false, 'nextChangeAt', next_change);

  if coalesce((select runtime.enabled from private.goods_transaction_runtime runtime where runtime.singleton), false) then
    return result || jsonb_build_object('state', 'unresolved');
  end if;

  select p.* into policy
  from private.shipping_region_policies p
  where p.origin_id = origin.id and p.carrier_code = origin.default_carrier and p.status = 'active'
    and p.starts_at <= probe_at and (p.ends_at is null or probe_at < p.ends_at)
  order by p.starts_at desc, p.version desc
  limit 1;
  if not found then return result; end if;

  -- 대표 행: 0원 초과 추가료 행 중 우편번호·주소 시작문구가 가장 앞선 행. 행의 첫 우편번호와
  -- 주소 시작문구(없으면 아무 기본주소)는 그 행에만 들어간다 — 활성 정책은 겹치는 행을 받지 않는다.
  select (rule->>'id')::uuid as rule_id, (rule->>'amount')::numeric as amount,
    rule->>'postalFrom' as postal_code, rule->>'addressPrefix' as address_prefix
  into representative
  from jsonb_array_elements(policy.configuration->'rules') rule
  where rule->>'disposition' = 'surcharge' and (rule->>'amount')::numeric > 0
  order by rule->>'postalFrom', rule->>'addressPrefix'
  limit 1;
  if not found then return result; end if;
  destination := jsonb_build_object('postalCode', representative.postal_code,
    'address1', coalesce(nullif(representative.address_prefix, ''), '주소'));

  quote_group := private.apply_shipping_region_quote(private.calculate_goods_shipping(lines), lines, destination, probe_at)->'groups'->0;
  -- 도입 전 출고지는 기존 배송비로 확정한다 — 지역료가 없다.
  if quote_group->>'regionMode' = 'legacy_base_only' then return result; end if;
  if quote_group->>'regionStatus' is distinct from 'surcharge'
    or (quote_group->>'policyId')::uuid is distinct from policy.id
    or (quote_group->>'ruleId')::uuid is distinct from representative.rule_id then
    return result || jsonb_build_object('state', 'unresolved');
  end if;
  fee := (quote_group->>'regionalFee')::numeric;
  -- 이 굿즈의 배송 유형에는 지역료를 붙이지 않는 정책이다.
  if fee = 0 then return result; end if;
  -- 굿즈 1개 견적은 배송 건당(최대 1회)·굿즈당(대상 굿즈 수만큼) 모두 그 행 금액이다. 단위는 화면이 밝힌다.
  fee_unit := quote_group->>'feeUnit';
  if fee_unit is null or fee_unit not in ('per_shipment', 'per_good') or fee is distinct from representative.amount then
    return result || jsonb_build_object('state', 'unresolved');
  end if;

  -- 무료배송 기준 면제: 기준 금액으로 다시 견적해 0원이면 면제, 대표 행 금액 그대로면 면제 없음.
  if origin.free_threshold is not null then
    lines := jsonb_set(lines, '{0,unit_price}', to_jsonb(origin.free_threshold));
    quote_group := private.apply_shipping_region_quote(private.calculate_goods_shipping(lines), lines, destination, probe_at)->'groups'->0;
    if quote_group->>'regionStatus' is distinct from 'surcharge'
      or (quote_group->>'ruleId')::uuid is distinct from representative.rule_id
      or quote_group->>'regionalFee' is null
      or (quote_group->>'regionalFee')::numeric not in (0, representative.amount) then
      return result || jsonb_build_object('state', 'unresolved');
    end if;
    waived := (quote_group->>'regionalFee')::numeric = 0;
  end if;

  select count(*)::integer,
    coalesce(jsonb_agg(jsonb_build_object('label', label, 'minFee', min_fee, 'maxFee', max_fee)
      order by min_fee, max_fee, label) filter (where position <= 20), '[]'::jsonb)
  into region_count, regions
  from (
    select label, min_fee, max_fee, row_number() over (order by min_fee, max_fee, label) as position
    from (
      select rule->>'regionLabel' as label, min((rule->>'amount')::numeric) as min_fee, max((rule->>'amount')::numeric) as max_fee
      from jsonb_array_elements(policy.configuration->'rules') rule
      where rule->>'disposition' = 'surcharge' and (rule->>'amount')::numeric > 0
      group by rule->>'regionLabel'
    ) grouped
  ) ranked;

  return result || jsonb_build_object('state', 'listed', 'regions', regions, 'regionCount', region_count,
    'feeUnit', fee_unit, 'waivedAtFreeThreshold', waived);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_goods_subscription_offers(p_good_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if p_good_ids is null or cardinality(p_good_ids) not between 1 and 100 then raise invalid_parameter_value using message='invalid_subscription_goods';end if;
 if not(select public_enabled and charge_enabled and worker_enabled from private.goods_subscription_runtime where singleton)
  or not(select enabled from private.goods_transaction_runtime where singleton) then return '[]'::jsonb;end if;
 return coalesce((select jsonb_agg(jsonb_build_object('goodId',g.id,'intervals',p.intervals,'message',p.message) order by g.id)
  from public.goods g join private.goods_subscription_policies p on p.good_id=g.id and p.enabled
  join public.ips ip on ip.id=g.ip_id and ip.archived_at is null and ip.published_at is not null
  where g.id=any(p_good_ids) and g.archived_at is null and g.published_at is not null and g.sale_restriction='none'
   and g.allow_card_payment and g.option_sale_mode<>'random' and exists(select 1 from public.goods_variants where good_id=g.id and archived_at is null and preorder_policy_id is null)),'[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.get_home_layout_order()
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare configured jsonb; result text[];
begin
  select blocks into configured from public.home_layout_settings where singleton;
  if configured is null then return null; end if;
  with requested as (
    select item->>'key' as key, item->'enabled'='true'::jsonb as enabled, position
    from pg_catalog.jsonb_array_elements(configured) with ordinality entries(item,position)
  ), active_bands as (
    select (case kind when 'band_banner' then 'band:' when 'sales_best' then 'sales:' when 'review_best' then 'reviews:' when 'product_mosaic' then 'mosaic:' else 'products:' end)||id::text as key,
      case kind when 'band_banner' then 0 when 'sales_best' then 1 when 'review_best' then 2 when 'product_mosaic' then 3 else 4 end as kind_order,display_order, active_from, id
    from public.home_curations
    where kind in ('band_banner','sales_best','review_best','product_mosaic','product_collection') and enabled and active_from<=now()
      and (active_to is null or active_to>now())
      and (kind<>'product_collection' or jsonb_array_length(private.public_home_product_collection_goods(payload))>0)
  ), ordered as (
    select requested.key, requested.position
    from requested
    where requested.enabled and (
      requested.key in ('hero','editor_picks','category_best','popular','benefits','stories','new_arrivals','strip_banner')
      or exists(select 1 from active_bands where active_bands.key=requested.key)
    )
    union all
    select active_bands.key,
      pg_catalog.jsonb_array_length(configured)+row_number() over(order by kind_order,display_order,active_from,id)
    from active_bands where not exists(select 1 from requested where requested.key=active_bands.key)
    union all
    select fixed.key,pg_catalog.jsonb_array_length(configured)+(select count(*) from active_bands)+fixed.slot
    from (values ('stories',1),('new_arrivals',2),('strip_banner',3)) fixed(key,slot)
    where not exists(select 1 from requested where requested.key=fixed.key)
  )
  select coalesce(pg_catalog.array_agg(key order by position),'{}'::text[]) into result from ordered;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_loyalty_grade_benefits()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  member_grade public.loyalty_grade;
  credit_enabled boolean;
  reward_enabled boolean;
  reward_rates jsonb;
  rates_effective boolean;
  result jsonb;
begin
  if actor is null then
    raise insufficient_privilege using message = 'auth_required';
  end if;

  -- 프로필이 없으면(가입 직후 경합 등) 가입 기본 등급으로 본다 — 상위 등급 쿠폰은 요약만 나간다.
  select coalesce(profile.loyalty_grade, 'welcome'::public.loyalty_grade) into member_grade
  from public.profiles as profile
  where profile.id = actor;
  member_grade := coalesce(member_grade, 'welcome'::public.loyalty_grade);

  select policy.enabled into credit_enabled
  from private.store_credit_policy as policy
  where policy.singleton;

  select policy.grade_enabled, policy.grade_rates into reward_enabled, reward_rates
  from private.customer_reward_policy as policy
  where policy.singleton;

  rates_effective := coalesce(credit_enabled, false) and coalesce(reward_enabled, false);

  with grades as (
    select grade.value as grade, grade.position
    from pg_catalog.unnest(pg_catalog.enum_range(null::public.loyalty_grade)) with ordinality as grade(value, position)
  ), grantable as (
    -- private.grant_grade_benefit_coupons 와 같은 거름(받는 회원 조건만 값으로 남긴다).
    select coupon.*
    from public.coupons as coupon
    where coupon.grade_benefit is not null
      and coupon.grade_benefit > 'welcome'::public.loyalty_grade
      and coupon.status = 'active'
      and (coupon.ends_at is null or coupon.ends_at > statement_timestamp())
      and (coupon.issue_starts_at is null or coupon.issue_starts_at <= statement_timestamp())
      and (coupon.issue_starts_at is null or coupon.issue_ends_at is null or coupon.issue_ends_at > statement_timestamp())
      and (coupon.issue_limit is null or coupon.issued_count < coupon.issue_limit)
  )
  select jsonb_build_object(
    'creditRatesEnabled', rates_effective,
    'grades', jsonb_agg(
      jsonb_build_object(
        'grade', grades.grade,
        -- 내가 오른 등급(이하)인지. 오르지 않은 등급은 쿠폰 내용 대신 종류별 장수만 싣는다.
        'reached', grades.grade <= member_grade,
        'creditRateBps', case when rates_effective then (reward_rates ->> grades.grade::text)::integer end,
        'couponCounts', jsonb_build_object(
          'goods', (select count(*) from grantable as coupon where coupon.grade_benefit = grades.grade and coupon.benefit_kind = 'goods'),
          'shipping', (select count(*) from grantable as coupon where coupon.grade_benefit = grades.grade and coupon.benefit_kind = 'shipping'),
          'monthly', (select count(*) from grantable as coupon where coupon.grade_benefit = grades.grade and coupon.grade_benefit_cadence = 'monthly')
        ),
        'coupons', case when grades.grade > member_grade then '[]'::jsonb else coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'name', coupon.name,
              'benefitKind', coupon.benefit_kind,
              'discountType', coupon.discount_type,
              'discountValue', coupon.discount_value,
              'maxDiscountAmount', coupon.max_discount_amount,
              'minSubtotal', coupon.min_subtotal,
              'goodsScope', coupon.goods_scope,
              'recipientSegment', coupon.recipient_segment,
              'startsAt', coupon.starts_at,
              'endsAt', coupon.ends_at,
              'validDays', coupon.valid_days,
              'cadence', coupon.grade_benefit_cadence
            )
            -- 코드는 정렬의 마지막 결정자로만 쓰고 내보내지 않는다(같은 조건의 정의도 순서가 흔들리지 않게).
            order by coupon.min_subtotal, coupon.benefit_kind, coupon.discount_type, coupon.discount_value desc, coupon.name, coupon.code
          )
          from grantable as coupon
          where coupon.grade_benefit = grades.grade
        ), '[]'::jsonb) end
      )
      order by grades.position
    )
  )
  into result
  from grades;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_account_deletion_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
begin
  if v_user_id is null then
    raise insufficient_privilege using message = 'authentication_required';
  end if;
  if not exists (
    select 1 from public.profiles as profile where profile.id = v_user_id
  ) then
    raise no_data_found using message = 'account_not_found';
  end if;

  return coalesce(
    private.reconcile_account_deletion_request(v_user_id),
    pg_catalog.jsonb_build_object(
      'status', 'not_requested',
      'phase', 'none',
      'nextAction', '/settings',
      'blockers', '[]'::jsonb
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_adult_verification()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := (select auth.uid());
  v_evidence private.adult_verifications%rowtype;
begin
  if v_user is null then
    return pg_catalog.jsonb_build_object('status', 'none');
  end if;

  select evidence.*
  into v_evidence
  from private.adult_verifications as evidence
  where evidence.user_id = v_user
  order by evidence.verified_at desc, evidence.id desc
  limit 1;

  if not found then
    return pg_catalog.jsonb_build_object('status', 'none');
  end if;

  if v_evidence.revoked_at is not null then
    return pg_catalog.jsonb_build_object(
      'status', 'revoked',
      'reason', v_evidence.revoked_reason,
      'revokedAt', v_evidence.revoked_at
    );
  end if;

  if v_evidence.expires_at <= pg_catalog.now() then
    return pg_catalog.jsonb_build_object(
      'status', 'expired',
      'verifiedAt', v_evidence.verified_at,
      'expiresAt', v_evidence.expires_at
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'status', 'verified',
    'verifiedAt', v_evidence.verified_at,
    'expiresAt', v_evidence.expires_at
  );
end;
$function$

