CREATE OR REPLACE FUNCTION public.get_product_detail_experience(p_good_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_good public.goods%rowtype; config jsonb; messages jsonb:='[]'; window_row record; customer_count bigint; sale_rank bigint;
 at_time timestamptz:=statement_timestamp(); today timestamptz:=date_trunc('day',statement_timestamp() at time zone 'Asia/Seoul') at time zone 'Asia/Seoul';
 next_change timestamptz;
begin
 select g.* into current_good from public.goods g join public.ips ip on ip.id=g.ip_id
 where g.id=p_good_id and g.published_at is not null and g.archived_at is null and private.good_sale_restriction_visible(g.sale_restriction,(select auth.uid()))
  and ip.published_at is not null and ip.archived_at is null;
 if not found then return null;end if;
 select values into config from private.product_detail_experience_settings where section='messages';
 if (config->>'buyers')::boolean then
  for window_row in select * from (values
   (1,'today',today),(2,'week',today-interval '6 days'),(3,'sixMonths',today-interval '6 months'),
   (4,'year',today-interval '1 year'),(5,'twoYears',today-interval '2 years')
  ) periods(position,key,starts_at) where key<>'twoYears' or (config->>'twoYears')::boolean order by position loop
   select count(distinct o.user_id) into customer_count from private.product_detail_paid_orders(window_row.starts_at,at_time) paid
    join public.orders o on o.id=paid.id where exists(select 1 from public.order_items i where i.order_id=o.id and i.good_id=p_good_id);
   if customer_count >= (case when window_row.key='twoYears' then 1 else (config->>'minBuyers')::integer end) then
    messages:=messages||jsonb_build_array(jsonb_build_object('kind','buyers','window',window_row.key,'count',customer_count));exit;
   end if;
  end loop;
 end if;
 if (config->>'repeatBuyers')::boolean then
  for window_row in select * from (values
   (1,'threeMonths',today-interval '3 months'),(2,'sixMonths',today-interval '6 months'),(3,'year',today-interval '1 year')
  ) periods(position,key,starts_at) order by position loop
   select count(*) into customer_count from (
    select o.user_id from private.product_detail_paid_orders(window_row.starts_at,at_time) paid
     join public.orders o on o.id=paid.id where exists(select 1 from public.order_items i where i.order_id=o.id and i.good_id=p_good_id)
     group by o.user_id having count(distinct o.id)>=2
   ) repeated;
   if customer_count >= (config->>'minRepeatBuyers')::integer then
    messages:=messages||jsonb_build_array(jsonb_build_object('kind','repeatBuyers','window',window_row.key,'count',customer_count));exit;
   end if;
  end loop;
 end if;
 if (config->>'bestSeller')::boolean then
  with sales as (
   select item.good_id,sum(item.qty::bigint) quantity from private.product_detail_paid_orders(today-interval '3 days',today) paid
    join public.order_items item on item.order_id=paid.id join public.goods g on g.id=item.good_id join public.ips ip on ip.id=g.ip_id
   where g.published_at is not null and g.archived_at is null and private.good_sale_restriction_visible(g.sale_restriction,(select auth.uid()))
    and ip.published_at is not null and ip.archived_at is null group by item.good_id
  ), ranked as (select good_id,row_number() over(order by quantity desc,good_id) rank from sales where quantity>0)
  select rank into sale_rank from ranked where good_id=p_good_id and rank<=10;
  if sale_rank is not null then messages:=messages||jsonb_build_array(jsonb_build_object('kind','bestSeller','rank',sale_rank));end if;
 end if;
 if (config->>'newProduct')::boolean and current_good.created_at<=at_time and current_good.created_at>at_time-interval '7 days' then
  messages:=messages||jsonb_build_array(jsonb_build_object('kind','newProduct'));
  next_change:=current_good.created_at+interval '7 days';
 end if;
 if (config->>'buyers')::boolean or (config->>'repeatBuyers')::boolean or (config->>'bestSeller')::boolean then next_change:=least(next_change,today+interval '1 day');end if;
 return jsonb_build_object('messages',messages,'discovery',public.get_product_detail_experience_config(),'nextChangeAt',next_change);
end $function$

CREATE OR REPLACE FUNCTION public.get_product_detail_presentation(p_good_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_good public.goods%rowtype; banner_config jsonb; modules jsonb; banner jsonb:=null; reviews jsonb:=null;
 recommendations jsonb:='{"similar":[],"together":[],"categoryPopular":[],"storePopular":[]}';
 starts_at timestamptz; ends_at timestamptz; next_change timestamptz; target_matches boolean:=false;
 today timestamptz:=date_trunc('day',statement_timestamp() at time zone 'Asia/Seoul') at time zone 'Asia/Seoul';
begin
 select g.* into current_good from public.goods g join public.ips ip on ip.id=g.ip_id
 where g.id=p_good_id and g.archived_at is null and g.published_at is not null and private.good_sale_restriction_visible(g.sale_restriction,(select auth.uid()))
  and ip.archived_at is null and ip.published_at is not null;
 if not found then return null;end if;
 select values into banner_config from private.product_detail_settings where section='banner';
 select values into modules from private.product_detail_settings where section='modules';
 if (banner_config->>'enabled')::boolean then
  target_matches:=banner_config->>'targetType'='all' or (banner_config->>'targetType'='goods'
   and exists(select 1 from private.product_detail_banner_goods where good_id=p_good_id));
  if banner_config->>'targetType'='categories' then
   with recursive public_categories as materialized (select * from public.get_catalog_categories()),
   descendants as (
    select c.id from public_categories c join private.product_detail_banner_categories selected on selected.category_id=c.id
    union select c.id from public_categories c join descendants parent on c.parent_id=parent.id
   ) select exists(select 1 from descendants c where c.id=current_good.category_id
    or exists(select 1 from public.goods_additional_categories a where a.good_id=p_good_id and a.category_id=c.id)) into target_matches;
  end if;
  if (banner_config->>'periodEnabled')::boolean then
   starts_at:=(banner_config->>'startsOn')::date::timestamp at time zone 'Asia/Seoul';
   ends_at:=((banner_config->>'endsOn')::date+1)::timestamp at time zone 'Asia/Seoul';
   if target_matches then select min(moment) into next_change from unnest(array[starts_at,ends_at]) moment where moment>statement_timestamp();end if;
  end if;
  if target_matches and (starts_at is null or starts_at<=statement_timestamp()) and (ends_at is null or ends_at>statement_timestamp()) then
   banner:=jsonb_build_object('style',banner_config->>'style','title',banner_config->>'title','text',banner_config->>'text');
  end if;
 end if;
 if (modules->>'reviewSummary')::boolean then
  select jsonb_build_object('count',count(*),'positiveCount',count(*) filter(where rating>=4),
   'cards',coalesce((select jsonb_agg(card order by has_photo desc,rating desc,created_at desc,id) from (
    select r.id,r.rating,r.created_at,cardinality(r.image_paths)>0 has_photo,
     jsonb_build_object('id',r.id,'rating',r.rating,'body',r.body,'authorName',coalesce(nullif(btrim(p.nickname),''),'구매자'),
      'createdAt',r.created_at,'imagePaths',coalesce(to_jsonb(r.image_paths),'[]'::jsonb)) card
    from public.reviews r left join public.public_profiles p on p.id=r.user_id
    where r.good_id=p_good_id and r.status='visible' and r.rating>=4
    order by cardinality(r.image_paths)>0 desc,r.rating desc,r.created_at desc,r.id limit 10
   ) selected),'[]'::jsonb)) into reviews from public.reviews where good_id=p_good_id and status='visible';
 end if;
 if (modules->>'similar')::boolean or (modules->>'together')::boolean or (modules->>'categoryPopular')::boolean or (modules->>'storePopular')::boolean then
  with eligible as materialized (
   select g.id,g.ip_id,g.category_id,g.created_at from public.goods g join public.ips ip on ip.id=g.ip_id
   where g.id<>p_good_id and g.archived_at is null and g.published_at is not null and private.good_sale_restriction_visible(g.sale_restriction,(select auth.uid()))
    and ip.archived_at is null and ip.published_at is not null
  ), category as (
   select c.id from public.get_catalog_categories() c where c.id=current_good.category_id and c.depth>=2
    and not exists(select 1 from public.catalog_categories child where child.parent_id=c.id and child.archived_at is null)
  ), paid as materialized (
   select * from private.product_detail_paid_orders(today-interval '30 days',today)
   where (modules->>'together')::boolean or (modules->>'categoryPopular')::boolean or (modules->>'storePopular')::boolean
  ), quantities as (
   select item.good_id,sum(item.qty::bigint) qty from paid join public.order_items item on item.order_id=paid.id
   join eligible e on e.id=item.good_id group by item.good_id
  ), wishes as (
   select w.good_id,count(*) qty from public.wishlists w join eligible e on e.id=w.good_id group by w.good_id
  ), popular as (
   select e.*,coalesce(q.qty,0) sale_qty,coalesce(w.qty,0) wish_qty from eligible e
   left join quantities q on q.good_id=e.id left join wishes w on w.good_id=e.id
   where coalesce(q.qty,0)>0 or coalesce(w.qty,0)>0
  ), together as (
   select item.good_id,count(distinct paid.id) co_orders,sum(item.qty::bigint) qty
   from paid join public.order_items item on item.order_id=paid.id join eligible e on e.id=item.good_id
   where exists(select 1 from public.order_items source where source.order_id=paid.id and source.good_id=p_good_id)
   group by item.good_id
  ), similar_ids as (
   select e.id from eligible e where (modules->>'similar')::boolean and (e.category_id in(select id from category) or e.ip_id=current_good.ip_id)
   order by coalesce(e.category_id in(select id from category),false) desc,e.created_at desc,e.id limit 30
  ), together_ids as (
   select good_id id from together where (modules->>'together')::boolean order by co_orders desc,qty desc,good_id limit 30
  ), category_ids as (
   select id from popular where (modules->>'categoryPopular')::boolean and category_id in(select id from category)
   order by sale_qty desc,wish_qty desc,created_at desc,id limit 12
  ), store_ids as (
   select id from popular where (modules->>'storePopular')::boolean order by sale_qty desc,wish_qty desc,created_at desc,id limit 12
  ) select jsonb_build_object(
   'similar',case when (select count(*) from similar_ids)>=5 then (select jsonb_agg(id) from similar_ids) else '[]'::jsonb end,
   'together',case when (select count(*) from together_ids)>=5 then (select jsonb_agg(id) from together_ids) else '[]'::jsonb end,
   'categoryPopular',coalesce((select jsonb_agg(id) from category_ids),'[]'::jsonb),
   'storePopular',coalesce((select jsonb_agg(id) from store_ids),'[]'::jsonb)) into recommendations;
  next_change:=least(next_change,today+interval '1 day');
 end if;
 return jsonb_build_object('banner',banner,'reviews',reviews,'recommendations',recommendations,'nextChangeAt',next_change);
end $function$

CREATE OR REPLACE FUNCTION public.get_product_shipping_savings(p_good_id text, p_variant_id uuid, p_qty integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_good public.goods%rowtype; candidate record; base_items jsonb; other_items jsonb; base_quote jsonb; other_quote jsonb; combined_quote jsonb;
 rows jsonb:='[]'; separate_fee bigint; combined_fee bigint; result jsonb; next_change timestamptz;
begin
 if p_good_id is null or p_variant_id is null or p_qty is null or p_qty not between 1 and 1000 then raise invalid_parameter_value using message='invalid_shipping_savings_selection';end if;
 if not (public.get_product_detail_experience_config()->>'shippingSavings')::boolean then return jsonb_build_object('items','[]'::jsonb,'nextChangeAt',null);end if;
 select g.* into current_good from public.goods g join public.ips ip on ip.id=g.ip_id join public.goods policy on policy.id=private.goods_aggregation_owner(g.id)
 where g.id=p_good_id and g.published_at is not null and g.archived_at is null and private.good_sale_restriction_visible(g.sale_restriction,(select auth.uid()))
  and ip.published_at is not null and ip.archived_at is null;
 if not found then return null;end if;
 base_items:=jsonb_build_array(jsonb_build_object('goodId',p_good_id,'variantId',p_variant_id,'qty',p_qty));
 base_quote:=private.shipping_savings_sales_quote(base_items);
 if exists(select 1 from jsonb_array_elements(base_quote->'lines') l where not (l->>'available')::boolean)
  or exists(select 1 from jsonb_array_elements(base_quote->'goods') g where g->'reason'<>'null'::jsonb) then
  return jsonb_build_object('items','[]'::jsonb,'selectionUnavailable',true,'nextChangeAt',base_quote->'nextChangeAt');end if;
 next_change:=(base_quote->>'nextChangeAt')::timestamptz;
 for candidate in
  select g.id,chosen.id variant_id,case when g.option_sale_mode='random' then '랜덤'::text else chosen.name end variant_name,case when policy.order_quantity_limit_enabled then policy.min_order_qty else 1 end qty
  from public.goods g join public.ips ip on ip.id=g.ip_id join public.goods policy on policy.id=private.goods_aggregation_owner(g.id)
  join lateral (
   select v.id,v.name from public.goods_variants v cross join lateral (select resolved.mode,case when g.option_sale_mode='random'
     then private.random_option_pool_qty(g.id,statement_timestamp()) else resolved.available_qty end available_qty
     from private.resolve_goods_variant_supply(v.id,statement_timestamp()) resolved) supply
    cross join lateral private.resolve_goods_variant_price(v.id,statement_timestamp()) pricing
   where v.good_id=g.id and v.archived_at is null and (supply.available_qty is null or supply.available_qty>=case when policy.order_quantity_limit_enabled then policy.min_order_qty else 1 end)
   order by v.is_default desc,pricing.effective_price,v.id limit 1
  ) chosen on true
  where g.id<>p_good_id and policy.origin_id=(select origin_id from public.goods where id=private.goods_aggregation_owner(current_good.id)) and g.published_at is not null and g.archived_at is null and private.good_sale_restriction_visible(g.sale_restriction,(select auth.uid()))
   and ip.published_at is not null and ip.archived_at is null and (not policy.order_quantity_limit_enabled or policy.min_order_qty between 1 and 1000)
  order by md5(g.id||(statement_timestamp() at time zone 'Asia/Seoul')::date::text),g.id limit 50
 loop
  other_items:=jsonb_build_array(jsonb_build_object('goodId',candidate.id,'variantId',candidate.variant_id,'qty',candidate.qty));
  begin
   other_quote:=private.shipping_savings_sales_quote(other_items);combined_quote:=private.shipping_savings_sales_quote(base_items||other_items);
  exception when check_violation or no_data_found then continue;end;
  if exists(select 1 from jsonb_array_elements(combined_quote->'lines') l where not (l->>'available')::boolean)
   or exists(select 1 from jsonb_array_elements(combined_quote->'goods') g where g->'reason'<>'null'::jsonb) then continue;end if;
  separate_fee:=(base_quote#>>'{shipping,totalFee}')::bigint+(other_quote#>>'{shipping,totalFee}')::bigint;
  combined_fee:=(combined_quote#>>'{shipping,totalFee}')::bigint;
  if combined_fee<separate_fee then
   rows:=rows||jsonb_build_array(jsonb_build_object('goodId',candidate.id,'variantId',candidate.variant_id,'variantName',candidate.variant_name,'qty',candidate.qty,
    'separateFee',separate_fee,'combinedFee',combined_fee,'savings',separate_fee-combined_fee));
   next_change:=least(next_change,(combined_quote->>'nextChangeAt')::timestamptz);
  end if;
  exit when jsonb_array_length(rows)>=12;
 end loop;
 result:=jsonb_build_object('items',rows,'nextChangeAt',next_change,'calculatedAt',statement_timestamp());
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.get_random_option_good_ids(p_good_ids text[], p_gift_session_hash text DEFAULT NULL::text)
 RETURNS SETOF text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  invited_gift uuid;
begin
  if actor is null then
    raise insufficient_privilege using message = 'auth required';
  end if;
  if p_good_ids is null or cardinality(p_good_ids) > 1000 then
    raise invalid_parameter_value using message = 'invalid_random_option_goods';
  end if;
  if p_gift_session_hash is not null then
    invited_gift := private.gift_session_id(p_gift_session_hash, statement_timestamp());
  end if;
  return query
  select good.id
  from public.goods good
  join public.ips ip on ip.id = good.ip_id
  where good.id = any(p_good_ids)
    and good.option_sale_mode = 'random'
    and (
      (good.published_at is not null and good.archived_at is null
        and ip.published_at is not null and ip.archived_at is null
        and private.good_sale_restriction_visible(good.sale_restriction, actor))
      or exists (
        select 1
        from private.gift_items item
        join private.gift_intents gift on gift.id = item.gift_id
        where item.good_id = good.id
          and (gift.sender_id = actor or gift.recipient_id = actor or gift.id = invited_gift)
      )
    )
  order by good.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_review_event(p_id uuid, p_winner_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare event private.review_events%rowtype;
begin
 if p_winner_page is null or p_winner_page not between 1 and 100000 then raise invalid_parameter_value using message='invalid_review_event_search';end if;
 select * into event from private.review_events where id=p_id;
 if not found or not private.review_event_public_period(event,statement_timestamp()) or not exists(select 1 from private.review_event_target_goods(p_id)) then return null;end if;
 return (with winners as materialized(
  select r.id review_id,r.good_id,g.name good_name,coalesce(nullif(btrim(profile.nickname),''),'구매자') nickname,r.body,award.granted_at
  from private.review_event_awards award join public.reviews r on r.id=award.source_review_id and r.status='visible'
  join public.goods g on g.id=r.good_id and g.published_at is not null and g.archived_at is null and g.sale_restriction='none'
  join public.ips ip on ip.id=g.ip_id and ip.published_at is not null and ip.archived_at is null left join public.public_profiles profile on profile.id=award.user_id
  where award.event_id=p_id and event.announced_at is not null and award.revoked_at is null
 ), page as(select * from winners order by granted_at,review_id limit 50 offset (p_winner_page-1)*50)
 select jsonb_build_object('event',private.review_event_public_document(p_id),'winnerTotal',(select count(*) from winners),'winnerPage',p_winner_page,
  'winners',coalesce((select jsonb_agg(jsonb_build_object('reviewId',review_id,'goodId',good_id,'goodName',good_name,'nickname',nickname,'body',left(body,250)) order by granted_at,review_id) from page),'[]'::jsonb)));
end $function$

CREATE OR REPLACE FUNCTION public.get_shopping_story(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare at_value timestamptz:=statement_timestamp(); story public.shopping_stories;
begin
 select * into story from public.shopping_stories s where s.id=p_id and s.deleted_at is null and private.shopping_story_state(s.starts_at,s.ends_at,at_value)='active';
 if not found then return null;end if;
 return jsonb_build_object('id',story.id,'reference',story.reference,'title',story.title,'bodyHtml',story.body_html,
  'imagePaths',to_jsonb(story.body_image_paths),'createdAt',story.created_at,'startsAt',story.starts_at,'endsAt',story.ends_at,'nextChangeAt',story.ends_at,
  'sections',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'title',x.title,'imageShape',x.image_shape,
   'goodIds',coalesce((select jsonb_agg(links.good_id order by links.sort_order) from public.shopping_story_goods links join public.goods g on g.id=links.good_id join public.ips ip on ip.id=g.ip_id
    where links.section_id=x.id and g.archived_at is null and g.published_at is not null and ip.archived_at is null and ip.published_at is not null and g.sale_restriction='none'),'[]'::jsonb)) order by x.sort_order)
    from public.shopping_story_sections x where x.story_id=p_id),'[]'::jsonb),
  -- A single JSON aggregate contains every related product. It cannot be cut
  -- to a PostgREST row page, and 300 long IDs never become an oversized GET URL.
  'goods',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'price',g.price,'compareAtPrice',g.compare_at_price,
   'salePeriod',public.goods_sale_period(g),'showDiscountRate',g.show_discount_rate,'badge',g.badge,'stock',g.stock,'imagePath',g.image_path,'bg',g.bg,
   'variants',coalesce((select jsonb_agg(jsonb_build_object('price',v.price,'pricing',public.goods_variant_pricing(v),'supply',public.goods_variant_supply(v)) order by v.id)
    from public.goods_variants v where v.good_id=g.id and v.archived_at is null),'[]'::jsonb)) order by g.id)
   from public.shopping_story_goods links join public.goods g on g.id=links.good_id join public.ips ip on ip.id=g.ip_id
   where links.story_id=p_id and g.archived_at is null and g.published_at is not null and ip.archived_at is null and ip.published_at is not null and g.sale_restriction='none'),'[]'::jsonb));
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_cards(p_user_id uuid, p_pool_id uuid, p_source text, p_source_id uuid, p_idempotency_key text, p_count integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_existing jsonb;
  v_cards jsonb := '[]'::jsonb;
  v_rarity rarity;
  v_card text;
  v_new boolean;
begin
  if p_count < 1 or p_count > 100 then
    raise exception 'invalid count';
  end if;

  perform 1
  from public.card_pools
  where id = p_pool_id
  for share;

  if not found then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  select granted_cards
    into v_existing
  from public.card_grants
  where idempotency_key = p_idempotency_key;

  if v_existing is not null then
    return v_existing;
  end if;

  for i in 1..p_count loop
    v_rarity := public.roll_rarity(p_pool_id);

    select card.id
      into v_card
    from public.cards as card
    where card.pool_id = p_pool_id
      and card.rarity = v_rarity
      and card.archived_at is null
    order by random()
    limit 1;

    if v_card is null then
      if exists (
        select 1
        from public.cards as archived_card
        where archived_card.pool_id = p_pool_id
          and archived_card.rarity = v_rarity
          and archived_card.archived_at is not null
      ) then
        raise check_violation using message = 'catalog_item_archived';
      end if;

      raise exception 'pool has no card of rarity %', v_rarity;
    end if;

    v_new := not exists (
      select 1
      from public.user_cards
      where user_id = p_user_id
        and card_id = v_card
    );

    insert into public.user_cards as user_card (user_id, card_id, qty)
    values (p_user_id, v_card, 1)
    on conflict on constraint user_cards_pkey
    do update set qty = user_card.qty + 1;

    v_cards := v_cards || jsonb_build_object(
      'cardId', v_card,
      'rarity', v_rarity,
      'isNew', v_new
    );
  end loop;

  insert into public.card_grants (
    user_id,
    pool_id,
    source,
    source_id,
    granted_cards,
    idempotency_key
  )
  values (
    p_user_id,
    p_pool_id,
    p_source,
    p_source_id,
    v_cards,
    p_idempotency_key
  );

  return v_cards;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_active_reward_policy_pool_window()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if exists (
    select 1
    from public.reward_policies as reward_policy
    where reward_policy.pool_id = new.id
      and reward_policy.active
      and greatest(reward_policy.active_from, new.active_from)
        >= least(
          coalesce(reward_policy.active_to, 'infinity'::timestamptz),
          coalesce(new.active_to, 'infinity'::timestamptz)
        )
  ) then
    raise exception 'active_reward_policy_window_conflict' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_game_event_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if (
    old.ip_id is distinct from new.ip_id
    or old.mode is distinct from new.mode
  ) and exists (
    select 1
    from public.games as game
    where game.event_id = old.id
  ) then
    raise exception 'game_event_contract_locked' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_game_pool_window()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if exists (
    select 1
    from public.games as game
    where game.reward_pool_id = new.id
      and (
        new.active_from > game.active_from
        or (game.active_to is null and new.active_to is not null)
        or (
          game.active_to is not null
          and new.active_to is not null
          and new.active_to < game.active_to
        )
      )
  ) then
    raise exception 'game_pool_window_conflict' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_played_game_catalog_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if (
    old.id is distinct from new.id
    or old.type is distinct from new.type
    or old.reward_pool_id is distinct from new.reward_pool_id
    or old.event_id is distinct from new.event_id
    or old.config is distinct from new.config
  ) and exists (
    select 1
    from public.game_plays as game_play
    where game_play.game_id = old.id
  ) then
    raise exception 'game_catalog_locked' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_my_gift_link(p_id uuid, p_expected_revision bigint, p_token_hash text, p_operation_id uuid, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare actor uuid:=auth.uid();gift private.gift_intents;request jsonb;generation bigint;begin
 if actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_lock(p_id,actor);
 if gift.sender_id<>actor then raise insufficient_privilege using message='gift_not_found';end if;
 if p_token_hash is null or p_token_hash!~'^[a-f0-9]{64}$' or p_expected_revision is null then raise invalid_parameter_value using message='gift_link_invalid';end if;
 request:=jsonb_build_object('revision',p_expected_revision,'tokenHash',p_token_hash);
 if private.gift_operation_replay(actor,p_id,'link_issued',request,p_operation_id) then
  if not exists(select 1 from private.gift_link_tokens where token_hash=p_token_hash and revoked_at is null and consumed_at is null and expires_at>clock_timestamp()) then raise check_violation using message='gift_link_closed';end if;
  return private.gift_operation_result(actor,p_operation_id)||jsonb_build_object('generation',(select t.generation from private.gift_link_tokens t where token_hash=p_token_hash));
 end if;
 perform private.gift_require_actor(actor);perform private.gift_require_runtime();
 if gift.revision<>p_expected_revision then raise sqlstate 'PT409' using message='gift_changed';end if;
 if gift.state<>'awaiting_acceptance' or gift.expires_at<=clock_timestamp() then raise check_violation using message='gift_link_closed';end if;
 select coalesce(max(t.generation),0)+1 into generation from private.gift_link_tokens t where gift_id=p_id;
 if generation>100 then raise check_violation using message='gift_link_limit';end if;
 update private.gift_link_tokens set revoked_at=clock_timestamp() where gift_id=p_id and revoked_at is null;
 delete from private.gift_claim_sessions s using private.gift_link_tokens t where s.token_hash=t.token_hash and t.gift_id=p_id;
 insert into private.gift_link_tokens(token_hash,gift_id,generation,expires_at) values(p_token_hash,p_id,generation,gift.expires_at);
 update private.gift_intents set revision=revision+1,updated_at=clock_timestamp() where id=p_id;
 perform private.gift_record_operation(actor,p_id,'link_issued',request,p_operation_id);
 return private.gift_operation_result(actor,p_operation_id)||jsonb_build_object('generation',generation);
end $function$

CREATE OR REPLACE FUNCTION public.issue_shipment_receipt_confirmation(p_shipment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); shipment public.order_shipments; purchase public.orders; confirmation_value text; instant timestamptz:=clock_timestamp();
begin
  if actor is null or not exists(select 1 from public.profiles where id=actor and suspended_at is null) then
    raise insufficient_privilege using message='authentication_required'; end if;
  select purchase_row.* into purchase from public.orders purchase_row join public.order_shipments shipment_row on shipment_row.order_id=purchase_row.id
    where shipment_row.id=p_shipment_id and purchase_row.user_id=actor for update of purchase_row;
  if not found then raise no_data_found using message='shipment_not_found'; end if;
  select * into shipment from public.order_shipments where id=p_shipment_id for update;
  if purchase.status not in ('confirmed','shipping') or not ((shipment.delivery_method in('pickup','none') and shipment.status='ready')
    or (shipment.delivery_method in('quick','direct','freight') and shipment.status='shipping')) then raise check_violation using message='delivery_receipt_code_unavailable'; end if;
  begin
    perform private.assert_order_dispatch_allowed(purchase.id);
  exception when check_violation then
    if sqlerrm is distinct from 'order fulfillment hold' or shipment.status <> 'shipping' then raise; end if;
  end;
  confirmation_value:=upper(encode(extensions.gen_random_bytes(6),'hex'));
  insert into private.shipment_receipt_confirmations(shipment_id,selection_id,owner_id,confirmation_digest,issued_at,expires_at)
    values(shipment.id,shipment.delivery_selection_id,actor,extensions.digest(confirmation_value,'sha256'),instant,instant+interval '10 minutes')
    on conflict(shipment_id) do update set selection_id=excluded.selection_id,owner_id=excluded.owner_id,confirmation_digest=excluded.confirmation_digest,
      issued_at=excluded.issued_at,expires_at=excluded.expires_at,failed_attempts=0,consumed_at=null,consumed_operation_id=null;
  return jsonb_build_object('code',confirmation_value,'expiresAt',instant+interval '10 minutes','maxAttempts',5);
end $function$

