CREATE OR REPLACE FUNCTION public.merge_cart_items(p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); item record; current_qty integer; key_value text;
begin
  if actor is null then raise insufficient_privilege using message='auth required'; end if;
  perform private.lock_goods_transaction_actor(actor);
  perform private.assert_active_user(actor);
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>1000 then raise check_violation using message='cart items must be an array'; end if;
  perform pg_advisory_xact_lock(hashtextextended('cart:'||actor::text,0));
  if exists(select 1 from jsonb_to_recordset(p_items) as candidate(qty integer) where candidate.qty is null or candidate.qty<=0) then
    raise check_violation using message='invalid cart item'; end if;
  -- 같은 장바구니 키로 모이는 서로 다른 옵션 줄(랜덤 판매 굿즈의 옵션 줄)은 수량을 더해 한 번만 반영한다(D5②).
  -- 같은 옵션 줄이 한 요청에 겹쳐 오면 지금처럼 큰 값 하나다(재시도 멱등 — cart_items.sql).
  for item in select grouped.good_id,grouped.variant_id,least(sum(grouped.qty::bigint),2147483647)::integer qty,grouped.input_revision,grouped.input_values
    from (select requested.good_id,private.cart_variant_key(requested.good_id,requested.variant_id) variant_id,requested.qty,
        requested.input_revision,requested.input_values
      from (select candidate.good_id,candidate.variant_id,max(candidate.qty) qty,
          coalesce(candidate.input_revision,0) input_revision,coalesce(candidate.input_values,'{}') input_values
        from jsonb_to_recordset(p_items) as candidate(good_id text,variant_id uuid,qty integer,input_revision integer,input_values jsonb)
        group by candidate.good_id,candidate.variant_id,coalesce(candidate.input_revision,0),coalesce(candidate.input_values,'{}')) requested) grouped
    group by grouped.good_id,grouped.variant_id,grouped.input_revision,grouped.input_values
    order by grouped.good_id,grouped.variant_id loop
    if item.qty is null or item.qty<=0 then raise check_violation using message='invalid cart item'; end if;
    key_value:=case when item.input_revision=0 and item.input_values='{}' then '' else md5(item.input_revision::text||':'||item.input_values::text) end;
    select qty into current_qty from public.cart_items where user_id=actor and variant_id=private.cart_variant_key(item.good_id,item.variant_id) and input_key=key_value;
    perform private.set_cart_quantity_with_inputs(item.good_id,private.cart_variant_key(item.good_id,item.variant_id),greatest(item.qty,coalesce(current_qty,0)),item.input_revision,item.input_values);
  end loop;
end $function$

