CREATE OR REPLACE FUNCTION public.open_draw_ticket_unguarded(p_ticket_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user uuid := (select auth.uid());
  v_ticket record;
  v_cards jsonb;
  v_idem text;
begin
  if v_user is null then
    raise exception 'auth required';
  end if;

  select ticket.id,
         ticket.user_id,
         ticket.pool_id,
         ticket.consumed_at,
         ticket.revoked_at
    into v_ticket
  from public.draw_tickets as ticket
  where ticket.id = p_ticket_id
  for update;

  if v_ticket.id is null then
    raise exception 'ticket not found';
  end if;
  if v_ticket.user_id <> v_user then
    raise exception 'forbidden';
  end if;
  if v_ticket.revoked_at is not null then
    raise exception 'ticket_revoked' using errcode = '55000';
  end if;

  v_idem := 'draw_ticket:' || v_ticket.id::text;

  if v_ticket.consumed_at is not null then
    select grant_record.granted_cards
      into v_cards
    from public.card_grants as grant_record
    where grant_record.idempotency_key = v_idem;

    if v_cards is not null then
      return v_cards;
    end if;

    raise exception 'ticket already consumed';
  end if;

  v_cards := public.grant_cards(
    v_user,
    v_ticket.pool_id,
    'draw_ticket',
    v_ticket.id,
    v_idem,
    1
  );

  update public.draw_tickets
  set consumed_at = now()
  where id = p_ticket_id
    and consumed_at is null
    and revoked_at is null;

  return v_cards;
end;
$function$

CREATE OR REPLACE FUNCTION public.open_notification(target_notification_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  notification_link text;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  update public.notifications as notification
  set read_at = coalesce(notification.read_at, now())
  where notification.id = target_notification_id
    and notification.user_id = actor_id
  returning notification.link_path into notification_link;

  if not found then
    raise exception 'notification_not_found' using errcode = 'P0002';
  end if;

  return notification_link;
end;
$function$

