CREATE OR REPLACE FUNCTION public.place_cart_goods_transaction(p_user_id uuid, p_expected_cart jsonb, p_address jsonb, p_quote_id uuid, p_checkout_key uuid, p_payment_method public.order_payment_method)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare selection jsonb;source jsonb;selected_coupon uuid;quoted_coupon uuid;combined boolean;result uuid;begin
 selection:=private.cart_goods_transaction_expected_selection(p_expected_cart);source:=private.goods_cart_transaction_source(p_user_id,selection);
 -- 계정 단위 직렬화는 사용자 advisory만 먼저 잡는다. account-action·profiles(actor 잠금)는
 -- 이전 주문 행을 잠근 뒤에 잡아야 claim·prepare·finalize(주문 → account-action)와 엇갈리지 않는다.
 if p_user_id is null then raise invalid_parameter_value using message='invalid_transaction_actor';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
 if exists(select 1 from private.order_goods_transactions where actor_id=p_user_id and checkout_key=p_checkout_key) then
  perform private.lock_goods_transaction_source(p_user_id,source);
  return private.place_goods_transaction(p_user_id,source,selection,p_address,p_quote_id,p_checkout_key,p_payment_method);end if;
 -- 이전 미결제 장바구니 주문의 재고·쿠폰·적립금·구매 한도를 먼저 돌려준다(ADR-0026).
 perform private.supersede_unpaid_cart_orders(p_user_id,true);
 perform private.lock_goods_transaction_source(p_user_id,source);
 perform private.assert_cart_goods_transaction_selection(p_user_id,selection);
 select user_coupon_id into selected_coupon from public.cart_coupon_selections where user_id=p_user_id;
 select user_coupon_id,user_coupon_ids is not null into quoted_coupon,combined from private.goods_transaction_quotes where id=p_quote_id and actor_id=p_user_id;
 if found and not combined and selected_coupon is distinct from quoted_coupon then raise sqlstate 'PT409' using message='coupon_snapshot_changed';end if;
 result:=private.place_goods_transaction(p_user_id,source,selection,p_address,p_quote_id,p_checkout_key,p_payment_method);
 if p_payment_method='bank_transfer' then
  -- 무통장은 접수 = 주문 완료(입금대기)다. 종전처럼 지금 장바구니에서 뺀다.
  -- Only this adapter owns the live cart. Gift/subscription never read it.
  delete from public.cart_items cart where user_id=p_user_id and exists(select 1 from jsonb_array_elements(selection) selected
   where selected->>'goodId'=cart.good_id and (selected->>'variantId')::uuid=cart.variant_id and (selected->>'qty')::integer=cart.qty
    and (selected->>'inputRevision')::integer=cart.input_revision and selected->'inputValues'=cart.input_values);
  delete from public.cart_coupon_selections where user_id=p_user_id and (combined or user_coupon_id=quoted_coupon);
 else
  -- 카드는 결제 확정 때 장바구니에서 뺀다(ADR-0026).
  -- 보류 줄 = 고른 줄(ADR-0030). 고른 줄은 위에서 지금 장바구니와 정확히 같다고 단언했다.
 perform private.record_checkout_order_hold(result,p_user_id,'cart_transaction',(select jsonb_agg(jsonb_build_object('goodId',cart.good_id,'variantId',cart.variant_id,
   'inputKey',cart.input_key,'inputRevision',cart.input_revision,'inputValues',cart.input_values,'qty',cart.qty) order by cart.good_id,cart.variant_id,cart.input_key)
   from public.cart_items cart where cart.user_id=p_user_id and exists(select 1 from jsonb_array_elements(selection) selected
    where selected->>'goodId'=cart.good_id and (selected->>'variantId')::uuid=cart.variant_id
     and (selected->>'inputRevision')::integer=cart.input_revision and selected->'inputValues'=cart.input_values)));
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.place_direct_goods_transaction(p_user_id uuid, p_draft_id uuid, p_address jsonb, p_quote_id uuid, p_checkout_key uuid, p_payment_method public.order_payment_method)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare existing private.order_goods_transactions; selection jsonb; source jsonb; base_good text; draft_lines jsonb; result uuid;
begin
  if p_user_id is null or p_draft_id is null then raise invalid_parameter_value using message = 'invalid_transaction_actor'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));
  -- 같은 checkout key의 재요청은 초안(만료됐을 수 있다)을 다시 보지 않고 원래 영수증을 돌려준다.
  select * into existing from private.order_goods_transactions where actor_id = p_user_id and checkout_key = p_checkout_key;
  if found then
    if existing.source_kind <> 'direct' then raise sqlstate 'PT409' using message = 'checkout_key_conflict'; end if;
    perform private.lock_goods_transaction_actor(p_user_id);
    return (private.replay_goods_transaction_receipt(p_user_id,
      jsonb_build_object('kind', existing.source_kind, 'id', existing.source_id, 'revision', existing.source_revision),
      p_quote_id, p_checkout_key, p_payment_method) ->> 'orderId')::uuid;
  end if;
  selection := private.direct_goods_transaction_selection(p_user_id, p_draft_id, true);
  source := private.goods_direct_transaction_source(p_user_id, selection);
  select draft.base_good_id, draft.lines into base_good, draft_lines from private.checkout_drafts as draft where draft.id = p_draft_id;
  -- 이전 미결제 주문(장바구니·바로구매 모두)의 재고·쿠폰·적립금·첫구매 예약·구매 한도를 먼저 돌려준다(ADR-0026·0030).
  perform private.supersede_unpaid_checkout_orders(p_user_id, true, null, 'new_direct_order');
  perform private.lock_goods_transaction_source(p_user_id, source);
  result := private.place_goods_transaction(p_user_id, source, selection, p_address, p_quote_id, p_checkout_key, p_payment_method);
  -- 같은 초안의 재제출을 막는 연결(무통장 접수·결제 완료 뒤에는 checkout_draft_used).
  update private.checkout_drafts set order_id = result where id = p_draft_id;
  if p_payment_method = 'bank_transfer' then
    -- 무통장은 접수 = 주문 완료다. 장바구니 줄은 건드리지 않고, 이 주문이 쓴 쿠폰의 장바구니 선택만 해제한다.
    delete from public.cart_coupon_selections as selection_row
    where selection_row.user_id = p_user_id
      and selection_row.user_coupon_id in (select redemption.user_coupon_id from public.coupon_redemptions as redemption
        where redemption.order_id = result and redemption.status = 'applied');
  else
    -- 카드는 장바구니 효과 없는 보류를 남긴다(다음 주문이 이 미결제 점유를 닫는 색인, 결제 확정 때 쿠폰 선택만 정리).
    perform private.record_direct_order_hold(result, p_user_id, 'direct_transaction', draft_lines, base_good);
  end if;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.place_direct_order(p_user_id uuid, p_draft_id uuid, p_address jsonb, p_checkout_key uuid, p_payment_method public.order_payment_method, p_store_credit_amount bigint, p_user_coupon_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_draft private.checkout_drafts%rowtype;
  placed uuid;
begin
  if p_user_id is null or p_checkout_key is null or p_draft_id is null then
    raise invalid_parameter_value using message = 'invalid_checkout_direct';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));
  -- 같은 키 재요청은 초안·장바구니를 다시 보지 않고 원래 주문(쓴 쿠폰까지)을 돌려준다.
  if exists (select 1 from public.orders where user_id = p_user_id and checkout_key = p_checkout_key) then
    return public.place_order_with_store_credits(p_user_id, p_address, p_checkout_key, p_payment_method, p_store_credit_amount, p_user_coupon_id);
  end if;
  -- 이 초안으로 만든 주문을 먼저 잠근 뒤, 이미 무통장 접수·결제 완료면 새 키의 재제출(다른 탭·뒤로 가기)을 PT409
  -- checkout_draft_used로, 결제가 아직 확정되지 않았으면(승인 확인 중·결과 불명) PT409 checkout_payment_in_progress로
  -- 거절한다. 승인 전에 끝난 카드 미결제 주문이면 아래 supersede가 그 주문을 닫고 새 주문을 만든다.
  v_draft := private.checkout_draft_for_order(p_user_id, p_draft_id, 'direct', true);
  -- 배송비 쿠폰은 legacy 주문서가 받지 않는다(장바구니 쿠폰 선택과 같은 거절).
  if p_user_coupon_id is not null and exists (
    select 1 from public.user_coupons as held join public.coupons as c on c.code = held.coupon_code
    where held.id = p_user_coupon_id and c.benefit_kind = 'shipping'
  ) then
    raise check_violation using message = 'coupon_checkout_required';
  end if;
  -- 이전 미결제 주문(장바구니·바로구매 모두)의 재고·쿠폰·적립금·첫구매 예약·구매 한도를 먼저 돌려준다(ADR-0026·0030).
  perform private.supersede_unpaid_checkout_orders(p_user_id, true, null, 'new_direct_order');
  perform private.lock_account_action_subject(p_user_id);
  update private.checkout_drafts set user_coupon_id = p_user_coupon_id where id = p_draft_id;
  -- 카드는 쿠폰의 장바구니 선택을 결제 확정 때 정리한다(보류). 무통장은 접수 때 코어가 같은 쿠폰 선택만 지운다.
  if p_payment_method = 'card' then perform set_config('icons.cart_order_retention', 'on', true); end if;
  perform set_config('icons.checkout_draft', p_draft_id::text, true);
  placed := public.place_order_with_store_credits(p_user_id, p_address, p_checkout_key, p_payment_method, p_store_credit_amount);
  perform set_config('icons.checkout_draft', '', true);
  perform set_config('icons.cart_order_retention', '', true);
  update private.checkout_drafts set order_id = placed where id = p_draft_id;
  if p_payment_method = 'card' then
    perform private.record_direct_order_hold(placed, p_user_id, 'direct_checkout', v_draft.lines, v_draft.base_good_id);
  end if;
  return placed;
end;
$function$

CREATE OR REPLACE FUNCTION public.place_my_gift(p_id uuid, p_quote_id uuid, p_checkout_key uuid, p_payment_method public.order_payment_method, p_expected_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();gift private.gift_intents;address jsonb;selection jsonb;receipt jsonb;quoted private.goods_transaction_quotes;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_checkout_source(p_id,actor);
 -- Recovery uses only the durable receipt. It survives quote/address retention,
 -- account fencing, runtime closure, and an already ordered gift.
 receipt:=private.replay_goods_transaction_receipt(actor,private.gift_source(gift),p_quote_id,p_checkout_key,p_payment_method);
 if receipt is not null then return (receipt->>'orderId')::uuid;end if;
 perform private.gift_require_payment_ready(gift);
 select * into quoted from private.goods_transaction_quotes where id=p_quote_id and actor_id=actor;
 if not found or quoted.source is distinct from private.gift_source(gift) then raise sqlstate 'PT409' using message='gift_source_changed';end if;
 if (quoted.calculation#>>'{display,totals,collectShippingTotal}')::numeric<>0 then raise check_violation using message='gift_prepaid_required';end if;
 selection:=private.gift_selection(gift.id);
 select a.address into address from private.gift_recipient_addresses a where a.gift_id=gift.id;
 return private.place_goods_transaction(actor,private.gift_source(gift),selection,address,p_quote_id,p_checkout_key,p_payment_method);
end $function$

CREATE OR REPLACE FUNCTION public.place_order_with_cart_selection(p_user_id uuid, p_draft_id uuid, p_address jsonb, p_checkout_key uuid, p_payment_method public.order_payment_method, p_store_credit_amount bigint, p_expected_user_coupon_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_draft private.checkout_drafts%rowtype;
  v_hold_lines jsonb;
  v_matched integer;
  placed uuid;
begin
  if p_user_id is null or p_checkout_key is null or p_draft_id is null then
    raise invalid_parameter_value using message = 'invalid_checkout_selection';
  end if;
  -- 주문 생성·쿠폰 선택과 같은 계정 잠금. 같은 키 재요청은 지금 장바구니·초안을 보지 않고 원래 주문을 돌려준다.
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));
  if exists (select 1 from public.orders where user_id = p_user_id and checkout_key = p_checkout_key) then
    return public.place_order_with_store_credits(p_user_id, p_address, p_checkout_key, p_payment_method, p_store_credit_amount, p_expected_user_coupon_id);
  end if;
  -- 이 초안으로 만든 주문을 먼저 잠근 뒤, 이미 무통장 접수·결제 완료면 새 키의 재제출(다른 탭·뒤로 가기)을 PT409
  -- checkout_draft_used로, 결제가 아직 확정되지 않았으면 PT409 checkout_payment_in_progress로 거절한다.
  v_draft := private.checkout_draft_for_order(p_user_id, p_draft_id, 'selection', true);
  -- 이전 미결제 주문의 재고·쿠폰·적립금·구매 한도를 먼저 돌려준다(ADR-0026, 출처 무관).
  perform private.supersede_unpaid_cart_orders(p_user_id, true);
  -- 주문 → account-action → 장바구니 순서. 새 주문 INSERT의 계정 fence도 같은 키를 다시 잡는다.
  perform private.lock_account_action_subject(p_user_id);
  perform pg_advisory_xact_lock(hashtextextended('cart:' || p_user_id::text, 0));
  -- 고른 장바구니 행을 id 순으로 잠그고, 초안의 줄과 정확히 같은지 본다(수량·직접입력값까지).
  perform 1 from public.cart_items as cart
  where cart.user_id = p_user_id
    and cart.id in (select (line ->> 'cartItemId')::uuid from jsonb_array_elements(v_draft.lines) as line)
  order by cart.id
  for update;
  select count(*),
    coalesce(jsonb_agg(jsonb_build_object('goodId', cart.good_id, 'variantId', cart.variant_id, 'inputKey', cart.input_key,
      'inputRevision', cart.input_revision, 'inputValues', cart.input_values, 'qty', cart.qty)
      order by cart.good_id, cart.variant_id, cart.input_key), '[]'::jsonb)
    into v_matched, v_hold_lines
  from public.cart_items as cart
  join jsonb_array_elements(v_draft.lines) as line on (line ->> 'cartItemId')::uuid = cart.id
  where cart.user_id = p_user_id
    and cart.good_id = line ->> 'goodId' and cart.variant_id = (line ->> 'variantId')::uuid
    and cart.qty = (line ->> 'qty')::integer and cart.input_revision = (line ->> 'inputRevision')::integer
    and cart.input_values = line -> 'inputValues';
  if v_matched <> jsonb_array_length(v_draft.lines) then
    raise sqlstate 'PT409' using message = 'cart_snapshot_changed';
  end if;
  if p_payment_method = 'card' then perform set_config('icons.cart_order_retention', 'on', true); end if;
  perform set_config('icons.checkout_draft', p_draft_id::text, true);
  placed := public.place_order_with_store_credits(p_user_id, p_address, p_checkout_key, p_payment_method, p_store_credit_amount, p_expected_user_coupon_id);
  perform set_config('icons.checkout_draft', '', true);
  perform set_config('icons.cart_order_retention', '', true);
  update private.checkout_drafts set order_id = placed where id = p_draft_id;
  -- 카드는 결제 확정 때 장바구니에서 뺀다(ADR-0026). 보류 줄 = 고른 줄이라 고르지 않은 줄은 결제 뒤에도 남는다.
  if p_payment_method = 'card' then
    perform private.record_checkout_order_hold(placed, p_user_id, 'legacy_checkout', v_hold_lines);
  end if;
  return placed;
end;
$function$

CREATE OR REPLACE FUNCTION public.place_order_with_cart_snapshot(p_user_id uuid, p_address jsonb, p_checkout_key uuid, p_payment_method public.order_payment_method, p_store_credit_amount bigint, p_expected_user_coupon_id uuid, p_expected_cart jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare expected_cart jsonb; actual_cart jsonb; entry jsonb; placed uuid;
begin
 if p_user_id is null or p_checkout_key is null then raise invalid_parameter_value using message='invalid_checkout_cart_snapshot'; end if;
 -- Match the pre-existing checkout/coupon lock order: user, then cart. Replays
 -- validate their original order contract without looking at today's cart.
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
 if exists(select 1 from public.orders where user_id=p_user_id and checkout_key=p_checkout_key) then
   return public.place_order_with_store_credits(p_user_id,p_address,p_checkout_key,p_payment_method,p_store_credit_amount,p_expected_user_coupon_id);
 end if;
 if jsonb_typeof(p_expected_cart) is distinct from 'array' then raise invalid_parameter_value using message='invalid_checkout_cart_snapshot'; end if;
 for entry in select value from jsonb_array_elements(p_expected_cart) loop
   if jsonb_typeof(entry)<>'object' or not(entry ?& array['good_id','variant_id','qty','input_revision','input_values'])
     or exists(select 1 from jsonb_object_keys(entry) key where key not in ('good_id','variant_id','qty','input_revision','input_values'))
     or jsonb_typeof(entry->'good_id')<>'string' or nullif(btrim(entry->>'good_id'),'') is null
     or jsonb_typeof(entry->'variant_id')<>'string' or entry->>'variant_id'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or jsonb_typeof(entry->'qty')<>'number' or entry->>'qty'!~'^[1-9][0-9]*$'
     or jsonb_typeof(entry->'input_revision')<>'number' or entry->>'input_revision'!~'^(0|[1-9][0-9]*)$'
     or jsonb_typeof(entry->'input_values')<>'object' then
     raise invalid_parameter_value using message='invalid_checkout_cart_snapshot';
   end if;
 end loop;
 -- 이전 미결제 장바구니 주문의 재고·쿠폰·적립금·구매 한도를 먼저 돌려준다(ADR-0026).
 perform private.supersede_unpaid_cart_orders(p_user_id,true);
 -- 주문 → account-action → 장바구니 순서. 새 주문 INSERT의 계정 fence도 같은 키를 다시 잡는다.
 perform private.lock_account_action_subject(p_user_id);
 -- Compare canonical values, not labels or hashes supplied by the browser.
 select coalesce(jsonb_agg(value order by value->>'good_id',(value->>'variant_id')::uuid,value->>'input_revision',(value->'input_values')::text),'[]')
   into expected_cart from jsonb_array_elements(p_expected_cart);
 perform pg_advisory_xact_lock(hashtextextended('cart:'||p_user_id::text,0));
 select coalesce(jsonb_agg(jsonb_build_object('good_id',good_id,'variant_id',variant_id,'qty',qty,
   'input_revision',input_revision,'input_values',input_values) order by good_id,variant_id,input_revision::text,input_values::text),'[]')
   into actual_cart from public.cart_items where user_id=p_user_id;
 if expected_cart is distinct from actual_cart then raise sqlstate 'PT409' using message='cart_snapshot_changed'; end if;
 if p_payment_method='card' then perform set_config('icons.cart_order_retention','on',true); end if;
 placed:=public.place_order_with_store_credits(p_user_id,p_address,p_checkout_key,p_payment_method,p_store_credit_amount,p_expected_user_coupon_id);
 perform set_config('icons.cart_order_retention','',true);
 if p_payment_method='card' then perform private.record_cart_order_hold(placed,p_user_id,'legacy_checkout'); end if;
 return placed;
end $function$

CREATE OR REPLACE FUNCTION public.place_order_with_store_credits(p_user_id uuid, p_address jsonb, p_checkout_key uuid, p_payment_method public.order_payment_method, p_store_credit_amount bigint, p_expected_user_coupon_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare existing_order public.orders; recorded_coupon_ids uuid[]; selected_coupon_id uuid;
begin
 if p_user_id is null or p_checkout_key is null or p_store_credit_amount is null
  or p_store_credit_amount not between 0 and 999999999999 then
  raise invalid_parameter_value using message='store_credit_amount_invalid';
 end if;
 -- apply_cart_coupon, clear_cart_coupon, and the existing five-argument
 -- checkout all use this same user lock. The comparison and consumption are
 -- therefore one operation even if another browser tab changes its selection.
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
 select * into existing_order from public.orders
  where user_id=p_user_id and checkout_key=p_checkout_key for update;
 if found then
  -- The cart was consumed on the first request and may now contain a different
  -- selection. Compare the original order's record, including a released
  -- redemption after cancellation; never reinterpret an old checkout key.
  select array_agg(distinct r.user_coupon_id) into recorded_coupon_ids
   from public.coupon_redemptions r where r.order_id=existing_order.id;
  if coalesce(cardinality(recorded_coupon_ids),0)>1
   or (existing_order.discount_total>0 and coalesce(cardinality(recorded_coupon_ids),0)=0) then
   raise exception using errcode='PT409',message='coupon_selection_changed';
  end if;
  selected_coupon_id:=recorded_coupon_ids[1];
 else
  select user_coupon_id into selected_coupon_id from public.cart_coupon_selections where user_id=p_user_id;
 end if;
 if selected_coupon_id is distinct from p_expected_user_coupon_id then
  raise exception using errcode='PT409',message='coupon_selection_changed';
 end if;
 -- Preserve the original address/payment-method/credit-amount replay checks,
 -- stock/coupon/credit reservation, pricing, and shipment creation exactly.
 return public.place_order_with_store_credits(p_user_id,p_address,p_checkout_key,p_payment_method,p_store_credit_amount);
end $function$

CREATE OR REPLACE FUNCTION public.place_order_with_store_credits(p_user_id uuid, p_address jsonb, p_checkout_key uuid, p_payment_method public.order_payment_method, p_store_credit_amount bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare existing_amount bigint; existing_order public.orders;
begin
  if p_user_id is null or p_checkout_key is null or p_store_credit_amount is null or p_store_credit_amount not between 0 and 999999999999
    then raise invalid_parameter_value using message='store_credit_amount_invalid'; end if;
  -- Same serialization as existing coupon/cart checkout, before any new order.
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
  select * into existing_order from public.orders where user_id=p_user_id and checkout_key=p_checkout_key;
  if found and existing_order.store_credit_total<>p_store_credit_amount then
    raise exception using errcode='PT409',message='checkout key conflict';
  end if;
  insert into private.store_credit_checkout_intents(user_id,checkout_key,amount) values(p_user_id,p_checkout_key,p_store_credit_amount) on conflict do nothing;
  select amount into existing_amount from private.store_credit_checkout_intents where user_id=p_user_id and checkout_key=p_checkout_key;
  if existing_amount<>p_store_credit_amount then raise exception using errcode='PT409',message='checkout key conflict'; end if;
  return public.place_order(p_user_id,p_address,p_checkout_key,p_payment_method);
end $function$

CREATE OR REPLACE FUNCTION public.place_order(p_address jsonb, p_checkout_key uuid, p_payment_method public.order_payment_method)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_key uuid;
begin
  if not exists(select 1 from public.orders where user_id=auth.uid() and checkout_key=p_checkout_key)
   and exists(select 1 from private.checkout_source_lines(auth.uid(),false) cart join private.goods_aggregation_members family on family.good_id=cart.good_id) then
   raise check_violation using message='checkout_contract_upgrade_required';end if;
  if not exists(select 1 from public.orders where user_id=auth.uid() and checkout_key=p_checkout_key) and exists(select 1 from private.checkout_source_lines(auth.uid(),false) c join private.shipping_charge_group_assignments a on a.owner_good_id=private.goods_aggregation_owner(c.good_id) and a.group_id is not null) then
   raise check_violation using message='checkout_contract_upgrade_required';end if;
  order_key:=private.place_order_before_shipments(p_address,p_checkout_key,p_payment_method);
  perform private.create_order_shipments(order_key);
  return order_key;
end $function$

CREATE OR REPLACE FUNCTION public.place_order(p_user_id uuid, p_address jsonb, p_checkout_key uuid, p_payment_method public.order_payment_method)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  previous_subject text := pg_catalog.current_setting('request.jwt.claim.sub', true);
  placed_order_id uuid;
begin
  if p_user_id is null then
    raise not_null_violation using message = 'user required';
  end if;

  perform pg_catalog.set_config('request.jwt.claim.sub', p_user_id::text, true);
  placed_order_id := public.place_order(p_address, p_checkout_key, p_payment_method);
  perform pg_catalog.set_config('request.jwt.claim.sub', coalesce(previous_subject, ''), true);
  return placed_order_id;
exception
  when others then
    perform pg_catalog.set_config('request.jwt.claim.sub', coalesce(previous_subject, ''), true);
    raise;
end;
$function$

