end $function$

CREATE OR REPLACE FUNCTION public.process_member_activity_retention()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare removed bigint; cutoff timestamptz:=(((clock_timestamp() at time zone 'Asia/Seoul')::date-89)::timestamp at time zone 'Asia/Seoul');
begin
