CREATE OR REPLACE FUNCTION public.quote_goods_sales_for_address(items jsonb, destination jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare quote jsonb; shipping jsonb; lines jsonb;
begin
  quote:=public.quote_goods_sales(items);
  select coalesce(jsonb_agg(jsonb_build_object('origin_id',good.origin_id,'good_id',good.id,'fee_type',good.shipping_fee_type)),'[]') into lines
    from jsonb_to_recordset(items) line("goodId" text,"variantId" uuid,qty integer) join public.goods good on good.id=line."goodId";
  shipping:=private.apply_shipping_region_quote(quote->'shipping',lines,destination,statement_timestamp());
  shipping:=shipping||jsonb_build_object('groups',(
    select coalesce(jsonb_agg(grp.value||jsonb_build_object('carrierLabel',carrier.label) order by grp.ordinality),'[]'::jsonb)
    from jsonb_array_elements(shipping->'groups') with ordinality as grp(value,ordinality)
    left join public.shipping_carriers carrier on carrier.code=grp.value->>'carrierCode' and carrier.is_active));
  return quote||jsonb_build_object('shipping',shipping,
    'nextChangeAt',least((quote->>'nextChangeAt')::timestamptz,(shipping->>'nextChangeAt')::timestamptz),
    'coupon',private.quote_selected_coupon(quote->'lines',(quote->>'subtotal')::bigint,(shipping->>'totalFee')::bigint));
end $function$

CREATE OR REPLACE FUNCTION public.quote_goods_sales(items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare quote jsonb; lines jsonb:='[]'; line jsonb; supply jsonb; next_change timestamptz; selling boolean; shipping_quote jsonb;
  variant public.goods_variants; actor uuid:=auth.uid(); reserved bigint; limit_reason text; sale_mode text; good_qty bigint; available boolean;
  option_count bigint; order_max bigint; member_max bigint;
begin
  quote:=private.quote_goods_sales_before_preorder(items);
  next_change:=(quote->>'nextChangeAt')::timestamptz;
  for line in select value from jsonb_array_elements(quote->'lines') loop
    select public.goods_variant_supply(v),good.stock<>'soldout',good.option_sale_mode into supply,selling,sale_mode
      from public.goods_variants v join public.goods good on good.id=v.good_id
      where v.id=(line->>'variantId')::uuid and good.id=line->>'goodId';
    if supply is null then raise check_violation using message='sales_quote_variant_unavailable'; end if;
    select * into variant from public.goods_variants where id=(line->>'variantId')::uuid;
    if sale_mode='random' then
      select coalesce(sum((other->>'qty')::bigint),0) into good_qty from jsonb_array_elements(quote->'lines') other where other->>'goodId'=line->>'goodId';
      available:=selling and good_qty<=(supply->>'availableQty')::bigint;
      select count(*) into option_count from public.goods_variants where good_id=variant.good_id and archived_at is null;
      order_max:=case when variant.order_max_qty is null then null else least(variant.order_max_qty::bigint*option_count,2147483647) end;
      member_max:=case when variant.member_max_qty is null then null else least(variant.member_max_qty::bigint*option_count,2147483647) end;
      reserved:=case when actor is null or member_max is null then null else (select coalesce(sum(item.qty::bigint),0)
        from public.orders o join public.order_items item on item.order_id=o.id
        where o.user_id=actor and o.status<>'canceled' and item.good_id=variant.good_id) end;
      limit_reason:=case
        when order_max is not null and good_qty>order_max then 'option_order_limit_exceeded'
        when reserved is not null and reserved+good_qty>member_max then 'option_member_limit_exceeded' end;
    else
      available:=selling and (line->>'qty')::bigint<=(supply->>'availableQty')::integer;
      order_max:=variant.order_max_qty; member_max:=variant.member_max_qty;
      reserved:=case when actor is null or variant.member_max_qty is null then null
        else private.member_variant_reserved_qty(actor,variant.id) end;
      limit_reason:=case
        when variant.order_max_qty is not null and (line->>'qty')::bigint>variant.order_max_qty then 'option_order_limit_exceeded'
        when reserved is not null and reserved+(line->>'qty')::bigint>variant.member_max_qty then 'option_member_limit_exceeded' end;
    end if;
    lines:=lines||jsonb_build_array(line||jsonb_build_object('supply',supply,'available',available,'optionSaleMode',sale_mode,
      'optionLimit',jsonb_build_object('orderMaxQty',order_max,'memberMaxQty',member_max,
        'memberReservedQty',reserved,'memberRemainingQty',case when reserved is null then null else greatest(0,member_max-reserved) end,
        'reason',limit_reason)));
    next_change:=least(next_change,(supply->>'nextChangeAt')::timestamptz);
  end loop;
  shipping_quote:=public.quote_goods_shipping(items);
  return quote||jsonb_build_object('lines',lines,'nextChangeAt',next_change,'shipping',shipping_quote,
    'coupon',private.quote_selected_coupon(lines,(quote->>'subtotal')::bigint,(shipping_quote->>'totalFee')::bigint));
end $function$

CREATE OR REPLACE FUNCTION public.quote_goods_shipping_for_address(items jsonb, destination jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base_quote jsonb; lines jsonb;
begin
  base_quote:=public.quote_goods_shipping(items);
  select coalesce(jsonb_agg(jsonb_build_object('origin_id',good.origin_id,'good_id',good.id,'fee_type',good.shipping_fee_type)),'[]') into lines
    from jsonb_to_recordset(items) line("goodId" text,"variantId" uuid,qty integer) join public.goods good on good.id=line."goodId";
  return private.apply_shipping_region_quote(base_quote,lines,destination,statement_timestamp());
end $function$

CREATE OR REPLACE FUNCTION public.quote_goods_shipping(items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare quote jsonb; groups jsonb:='[]'; group_value jsonb; planned_date date; has_preorder boolean; has_stock boolean;
begin
  quote:=private.quote_goods_shipping_before_preorder(items);
  quote:=private.goods_transaction_base_shipping_quote(items,quote,statement_timestamp());
  for group_value in select value from jsonb_array_elements(quote->'groups') loop
    select max(supply.expected_ship_date) filter(where supply.mode='preorder'),bool_or(supply.mode='preorder'),bool_or(supply.mode='stock')
      into planned_date,has_preorder,has_stock
    from jsonb_to_recordset(items) line("goodId" text,"variantId" uuid,qty integer)
    join public.goods good on good.id=line."goodId"
    cross join lateral private.resolve_goods_variant_supply(line."variantId",statement_timestamp()) supply
    where good.origin_id::text=group_value->>'originId';
    groups:=groups||jsonb_build_array(group_value||jsonb_build_object('expectedShipDate',planned_date,
      'hasPreorder',coalesce(has_preorder,false),'hasStockItems',coalesce(has_stock,false)));
  end loop;
  return quote||jsonb_build_object('groups',groups);
end $function$

CREATE OR REPLACE FUNCTION public.quote_my_gift(p_id uuid, p_expected_revision bigint, p_user_coupon_id uuid, p_store_credit_amount bigint, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();gift private.gift_intents;address jsonb;selection jsonb;choices jsonb;quoted jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_checkout_source(p_id,actor,p_expected_revision);perform private.gift_require_payment_ready(gift);
 selection:=private.gift_selection(gift.id);
 select a.address into address from private.gift_recipient_addresses a where a.gift_id=gift.id;
 select jsonb_object_agg(value->>'goodId','prepaid') into choices from jsonb_array_elements(selection);
 quoted:=private.quote_goods_transaction(actor,private.gift_source(gift),selection,address,choices,p_user_coupon_id,p_store_credit_amount);
 if quoted->>'state'='quoted' and (quoted#>>'{display,totals,collectShippingTotal}')::numeric<>0 then
  raise check_violation using message='gift_prepaid_required';end if;
 return quoted;
end $function$

CREATE OR REPLACE FUNCTION public.read_my_claim_collection_plan(p_claim uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare doc jsonb;order_key uuid;viewer text;begin
 perform private.purchase_confirmation_identity(p_actor,p_session,false);
 select c.order_id,case when g.recipient_id=p_actor then 'recipient' when g.sender_id=p_actor then 'sender' when g.id is null and o.user_id=p_actor then 'buyer' end
 into order_key,viewer from public.order_cancellation_requests c join public.orders o on o.id=c.order_id left join private.gift_intents g on g.order_id=o.id where c.id=p_claim;
 if viewer is null then raise no_data_found using message='claim_not_found';end if;
 if viewer='sender' then return null;end if;
 doc:=private.claim_collection_document(p_claim);
 return doc||jsonb_build_object('editable',false,'history','[]'::jsonb,'rows',(select coalesce(jsonb_agg(value||jsonb_build_object('evidence','')),'[]') from jsonb_array_elements(doc->'rows')));
end $function$

CREATE OR REPLACE FUNCTION public.read_my_claim_return_bundles(p_claim uuid, p_actor uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare viewer text;begin
 perform private.purchase_confirmation_identity(p_actor,p_session,false);
 select case when g.recipient_id=p_actor then 'recipient' when g.sender_id=p_actor then 'sender' when g.id is null and o.user_id=p_actor then 'buyer' end
 into viewer from public.order_cancellation_requests c join public.orders o on o.id=c.order_id left join private.gift_intents g on g.order_id=o.id where c.id=p_claim;
 if viewer is null then raise no_data_found using message='claim_not_found';end if;
 if viewer='sender' then return null;end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('shipmentId',x.shipment_id,'returnBundles',private.claim_collection_bundles_json(x.claim_id,x.shipment_id,false)) order by x.shipment_id),'[]'::jsonb)
  from public.order_claim_collections x where x.claim_id=p_claim);
end $function$

CREATE OR REPLACE FUNCTION public.read_my_gift_invitation(p_session_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
