CREATE OR REPLACE FUNCTION public.read_my_inquiry_satisfaction_operation(p_operation_id uuid, p_inquiry_id uuid, p_expected_actor_id uuid, p_expected_session_id uuid, p_expected_answer_id uuid, p_expected_revision bigint, p_desired_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare fingerprint jsonb; old_operation private.inquiry_satisfaction_operations%rowtype; current_state jsonb;
begin
 fingerprint:=private.inquiry_satisfaction_request(p_operation_id,p_inquiry_id,p_expected_actor_id,p_expected_session_id,p_expected_answer_id,p_expected_revision,p_desired_value,false);
 current_state:=public.get_my_inquiry_satisfaction(p_inquiry_id);
 select * into old_operation from private.inquiry_satisfaction_operations where actor_id=p_expected_actor_id and operation_id=p_operation_id;
 if found then
  if old_operation.request_fingerprint is distinct from fingerprint then raise sqlstate 'PT409' using message='inquiry_satisfaction_operation_conflict';end if;
  return jsonb_build_object('operation','completed','receipt',old_operation.receipt,'current',current_state);
 end if;
 return jsonb_build_object('operation','unresolved','receipt',null,'current',current_state);
exception when lock_not_available then raise sqlstate 'PT409' using message='inquiry_satisfaction_retry';
end $function$

CREATE OR REPLACE FUNCTION public.read_my_order_claim_refund_account_operation(p_order_id uuid, p_claim_id uuid, p_operation_id uuid, p_expected_revision integer, p_expected_actor_id uuid, p_expected_session_id uuid, p_seal boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous private.order_claim_refund_account_operations;
begin
 perform private.require_claim_refund_account_identity(p_expected_actor_id,p_expected_session_id);
 if p_order_id is null or p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0 or p_seal is null then
  raise invalid_parameter_value using message='invalid_claim_refund_account';end if;
 if not exists(select 1 from public.orders o join public.order_cancellation_requests c on c.order_id=o.id
  where o.id=p_order_id and o.user_id=p_expected_actor_id and c.id=p_claim_id)
  or exists(select 1 from private.gift_intents where order_id=p_order_id) then raise sqlstate 'PT404' using message='claim_not_found';end if;
 perform private.lock_operator_subjects(array[p_expected_actor_id]);
 perform private.lock_claim_refund_account_session(p_expected_actor_id,p_expected_session_id);
 -- A read waits for the current writer; sealing also excludes a delayed writer.
 perform pg_advisory_xact_lock(hashtextextended('claim-refund-account:'||p_operation_id::text,0));
 select * into previous from private.order_claim_refund_account_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>p_expected_actor_id or previous.session_id<>p_expected_session_id or previous.order_id<>p_order_id
   or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision then
   raise unique_violation using message='refund_account_request_conflict';end if;
 elsif p_seal then
  insert into private.order_claim_refund_account_operations(id,actor_id,session_id,order_id,claim_id,expected_revision,result_revision,state)
  values(p_operation_id,p_expected_actor_id,p_expected_session_id,p_order_id,p_claim_id,p_expected_revision,p_expected_revision,'sealed');
 end if;
 return private.order_claim_refund_account_receipt(p_operation_id,p_expected_actor_id,p_expected_session_id);
end $function$

CREATE OR REPLACE FUNCTION public.read_my_order_claim_withdrawal(p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();begin
 if actor is null or p_operation_id is null then raise insufficient_privilege using message='auth_required';end if;
 perform private.lock_operator_subjects(array[actor]);
 perform pg_advisory_xact_lock(hashtextextended('claim-withdrawal:'||p_operation_id::text,0));
 if not exists(select 1 from private.order_claim_withdrawals where id=p_operation_id and actor_id=actor and actor_kind='customer') then return null;end if;
 return private.order_claim_withdrawal_receipt(p_operation_id,actor);
end $function$

CREATE OR REPLACE FUNCTION public.reconcile_expired_prepared_goods_cancellation(p_request_id uuid, p_actor_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order_id uuid;
  v_order public.orders%rowtype;
  v_request public.order_cancellation_requests%rowtype;
  v_attempt public.payment_attempts%rowtype;
  v_cancellation_claim public.order_cancellation_claims%rowtype;
  v_transitioned boolean := false;
begin
  -- p_actor_id null = 시스템(서버 자동 발행). 유형 제한은
  -- assert_order_cancellation_reconciliation_allowed가 잠금 아래에서 다시 본다.
  if p_request_id is null then
    raise invalid_parameter_value using
      message = 'prepared_goods_cancellation_input_invalid';
  end if;

  if p_actor_id is not null then
    perform private.require_actor_operator_capability(p_actor_id,'sales.manage',false);
  end if;

  -- Resolve only the lock key first. Every money and stock writer below uses
  -- the shared order -> request -> attempt -> payments ordering.
  select request.order_id
  into v_order_id
  from public.order_cancellation_requests as request
  where request.id = p_request_id;

  if v_order_id is null then
    raise no_data_found using message = 'cancellation_request_not_found';
  end if;

  select order_record.*
  into v_order
  from public.orders as order_record
  where order_record.id = v_order_id
  for update;

  if not found then
    raise no_data_found using message = 'goods_order_not_found';
  end if;

  select request.*
  into v_request
  from public.order_cancellation_requests as request
  where request.id = p_request_id
    and request.order_id = v_order.id
  for update;

  if not found then
    raise no_data_found using message = 'cancellation_request_not_found';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.purpose = 'order'
    and attempt.ref_id = v_order.id
    and attempt.provider in ('toss', 'korpay', 'nicepay')
  order by attempt.id
  limit 1
  for update;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'order'
    and payment.ref_id = v_order.id
  order by payment.id
  for update;

  if v_request.status = 'completed' then
    -- loadContext and this lock can be separated by another successful Toss,
    -- Korpay manual, or terminal-attempt reconciliation. A completed request
    -- plus canceled order is the provider-neutral terminal identity.
    if v_order.status = 'canceled' then
      return 'completed';
    end if;
    raise object_not_in_prerequisite_state using
      message = 'prepared_goods_cancellation_terminal_mismatch';
  end if;

  if v_request.status not in ('processing', 'needs_review') then
    raise object_not_in_prerequisite_state using
      message = 'cancellation_request_not_recoverable';
  end if;

  perform public.assert_order_cancellation_reconciliation_allowed(p_request_id,p_actor_id);

  if v_attempt.id is null then
    return 'not_applicable';
  end if;

  -- A callback or another evidence path that moved the attempt beyond
  -- prepared owns the resolution. Do not fall through to the Toss empty-ledger
  -- completion path and do not mutate the request to needs_review here.
  -- An approved, identity-matched Toss ledger is a captured payment, never a
  -- no-capture timeout. Continue to provider reconciliation without mutating it.
  if v_attempt.state='approved' and v_attempt.provider in ('toss','nicepay')
    and v_attempt.user_id=v_order.user_id and v_attempt.amount=v_order.total and v_attempt.currency='KRW'
    and exists(select 1 from public.payments p where p.id=v_attempt.payment_id and p.provider=v_attempt.provider
      and p.purpose='order' and p.ref_id=v_order.id and p.user_id=v_order.user_id and p.amount=v_order.total
      and p.status in ('paid','canceled','refunded') and nullif(btrim(p.payment_key),'') is not null) then
    return 'not_applicable';
  end if;
  if v_attempt.state in ('confirming', 'approved', 'unknown', 'needs_review') then
    return 'in_progress';
  end if;

  if v_attempt.state in ('declined', 'canceled') then
    return 'not_applicable';
  end if;

  if v_attempt.state is distinct from 'prepared' then
    raise object_not_in_prerequisite_state using
      message = 'prepared_goods_payment_attempt_invalid';
  end if;

  if v_order.status is distinct from 'pending'
    or v_attempt.user_id is distinct from v_order.user_id
    or v_attempt.amount is distinct from v_order.total
    or v_attempt.currency is distinct from 'KRW'
    or v_request.requested_by is distinct from v_order.user_id
    or not private.goods_order_snapshot_matches(
      v_order.id,
      v_order.total,
      v_order.shipping_fee
    )
  then
    raise object_not_in_prerequisite_state using
      message = 'prepared_goods_cancellation_order_attempt_mismatch';
  end if;

  select claim.*
  into v_cancellation_claim
  from public.order_cancellation_claims as claim
  where claim.order_id = v_order.id
  for update;

  if not found
    or v_cancellation_claim.requested_by is distinct from v_request.requested_by
  then
    raise object_not_in_prerequisite_state using
      message = 'cancellation_claim_required';
  end if;

  if exists (
    select 1
    from public.payments as payment
    where payment.purpose = 'order'
      and payment.ref_id = v_order.id
      and payment.status <> 'failed'
  ) then
    raise object_not_in_prerequisite_state using
      message = 'prepared_goods_cancellation_payment_evidence_invalid';
  end if;

  if v_attempt.expires_at is null
    or v_attempt.expires_at > pg_catalog.clock_timestamp()
  then
    return 'in_progress';
  end if;

  update public.payment_attempts as attempt
  set
    state = 'canceled',
    claim_token = null,
    claim_expires_at = null
  where attempt.id = v_attempt.id
    and attempt.state = 'prepared'
    and attempt.expires_at is not null
    and attempt.expires_at <= pg_catalog.clock_timestamp()
  returning true into v_transitioned;

  if not coalesce(v_transitioned, false) then
    return 'in_progress';
  end if;

  perform public.finalize_order_cancellation_with_provider_evidence(
    v_order.id,
    v_request.reason,
    array[]::text[]
  );

  update public.order_cancellation_requests as request
  set
    status = 'completed',
    last_error_code = null,
    completed_at = coalesce(request.completed_at, pg_catalog.clock_timestamp()),
    updated_at = pg_catalog.clock_timestamp()
  where request.id = v_request.id
    and request.status in ('processing', 'needs_review');

  if not found then
    raise object_not_in_prerequisite_state using
      message = 'prepared_goods_cancellation_request_changed';
  end if;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_actor_id,
    case when p_actor_id is null
      then 'system.order.prepared_goods_cancellation_completed'
      else 'admin.order.prepared_goods_cancellation_completed'
    end,
    'order:' || v_order.id::text,
    pg_catalog.jsonb_build_object(
      'attemptId', v_attempt.id,
      'requestId', v_request.id,
      'outcome', 'expired_no_capture'
    ) || case when p_actor_id is null
      then pg_catalog.jsonb_build_object('actor', 'system')
      else '{}'::jsonb
    end
  );

  return 'completed';
end;
$function$

CREATE OR REPLACE FUNCTION public.record_email_intent_accepted(target_intent_id uuid, target_provider_reference_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_provider_digest bytea := private.email_digest_from_hex(target_provider_reference_digest);
  v_intent private.email_intents%rowtype;
  v_owner private.email_intents%rowtype;
  v_event record;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'email-provider:' || encode(v_provider_digest, 'hex'),
      0
    )
  );

  select * into v_intent
  from private.email_intents as intent
  where intent.id = target_intent_id
  for update;
  if not found then raise no_data_found using message = 'email_intent_not_found'; end if;

  if v_intent.provider_reference_digest is not null
    and v_intent.provider_reference_digest is distinct from v_provider_digest
  then
    update private.email_intents set state = 'needs_review', updated_at = pg_catalog.now()
    where id = v_intent.id;
    return pg_catalog.jsonb_build_object('state', 'needs_review');
  end if;
  if v_intent.provider_reference_digest = v_provider_digest then
    return pg_catalog.jsonb_build_object('state', v_intent.state);
  end if;
  if v_intent.state = 'needs_review' then
    return pg_catalog.jsonb_build_object('state', 'needs_review');
  end if;
  if v_intent.state not in ('dispatching', 'unknown', 'accepted', 'sent', 'delivered', 'delayed') then
    raise object_not_in_prerequisite_state using message = 'email_intent_not_dispatchable';
  end if;

  select * into v_owner
  from private.email_intents as intent
  where intent.provider_reference_digest = v_provider_digest
    and intent.id <> v_intent.id
  for update;
  if found then
    update private.email_intents set state = 'needs_review', updated_at = pg_catalog.now()
    where id in (v_intent.id, v_owner.id);
    return pg_catalog.jsonb_build_object('state', 'needs_review');
  end if;

  update private.email_intents set
    provider_reference_digest = v_provider_digest,
    state = case when state in ('sent', 'delivered', 'delayed') then state else 'accepted' end,
    accepted_at = coalesce(accepted_at, pg_catalog.now()),
    updated_at = pg_catalog.now()
  where id = v_intent.id
  returning * into v_intent;

  -- A timeout can lose the HTTP response after Resend accepted and emitted a webhook.
  -- Attach any PII-free unmatched events now that the provider reference is durable,
  -- then reduce the strongest lifecycle evidence without requiring a provider replay.
  update private.email_provider_events
  set intent_id = v_intent.id
  where intent_id is null
    and provider_reference_digest = v_provider_digest;

  select event.event_type, event.occurred_at
    into v_event
  from private.email_provider_events as event
  where event.intent_id = v_intent.id
  order by
    private.email_terminal_rank(event.event_type) desc,
    event.occurred_at desc,
    event.svix_id desc
  limit 1;

  if found and private.email_terminal_rank(v_event.event_type)
    > private.email_terminal_rank(v_intent.state)
  then
    update private.email_intents set
      state = v_event.event_type,
      state_occurred_at = v_event.occurred_at,
      delivered_at = case when v_event.event_type = 'delivered'
        then coalesce(delivered_at, v_event.occurred_at) else delivered_at end,
      terminal_at = case when v_event.event_type in ('bounced', 'complained', 'suppressed', 'failed')
        then coalesce(terminal_at, v_event.occurred_at) else terminal_at end,
      updated_at = pg_catalog.now()
    where id = v_intent.id
    returning * into v_intent;
  end if;

  return pg_catalog.jsonb_build_object('state', v_intent.state);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_email_intent_dispatch_failure(target_intent_id uuid, target_failure text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_state text;
  v_retryable boolean;
begin
  if target_failure not in ('retryable', 'ambiguous', 'permanent') then
    raise check_violation using message = 'invalid_email_dispatch_failure';
  end if;

  v_state := case target_failure
    when 'retryable' then 'queued'
    when 'ambiguous' then 'unknown'
    else 'needs_review'
  end;
  v_retryable := target_failure in ('retryable', 'ambiguous');

  update private.email_intents set state = v_state, updated_at = pg_catalog.now()
  where id = target_intent_id and state = 'dispatching';
  if not found then
    raise object_not_in_prerequisite_state using message = 'email_intent_not_dispatching';
  end if;

  return pg_catalog.jsonb_build_object('state', v_state, 'retryable', v_retryable);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_member_activity_event(p_event_id uuid, p_kind text, p_page_kind text, p_target_id text, p_asset_id uuid, p_expected_revision bigint, p_expected_actor uuid, p_expected_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c private.member_activity_consents; target jsonb; old private.member_activity_events; s private.member_activity_settings; at_value timestamptz:=clock_timestamp();
begin
 select * into s from private.member_activity_settings where singleton for share;
 perform private.require_member_activity_identity(p_expected_actor,p_expected_session);
 select * into c from private.member_activity_consents where user_id=p_expected_actor for share;
 if not s.enabled or c.choice is distinct from 'accepted' or c.revision is distinct from p_expected_revision then
  raise insufficient_privilege using message='member_activity_consent_required';end if;
 if p_event_id is null or p_kind is null or p_kind not in ('visit','video_started','video_completed') or p_page_kind is null
  or p_page_kind not in ('home','shop','good','stories','story','ip','events','event') or p_target_id is null or char_length(p_target_id) not between 1 and 200
  or (p_kind='visit')<>(p_asset_id is null) then raise invalid_parameter_value using message='invalid_member_activity_event';end if;
 target:=private.store_analytics_page(p_page_kind,p_target_id,at_value);
 if target is null then raise no_data_found using message='member_activity_target_unavailable';end if;
 if p_kind<>'visit' and (p_page_kind<>'good' or not exists(select 1 from private.goods_media_bindings b join private.goods_media_assets a on a.id=p_asset_id and a.status='attached'
   where b.good_id=p_target_id and p_asset_id in (b.video_asset_id,b.shortclip_asset_id))) then
  raise no_data_found using message='member_activity_video_unavailable';end if;
 select * into old from private.member_activity_events where user_id=p_expected_actor and event_id=p_event_id;
 if found then
  if old.consent_revision<>c.revision or old.kind<>p_kind or old.page_kind<>p_page_kind or old.target_id<>p_target_id or old.asset_id is distinct from p_asset_id then
   raise sqlstate 'PT409' using message='member_activity_event_conflict';end if;
  return jsonb_build_object('recorded',true,'duplicate',true);
 end if;
 if (select count(*) from private.member_activity_events where user_id=p_expected_actor and observed_at>at_value-interval '1 minute')>=120 then
  raise sqlstate 'P0429' using message='member_activity_rate_limited';end if;
 insert into private.member_activity_events(user_id,event_id,consent_revision,kind,page_kind,target_id,asset_id,category_id,observed_at)
  values(p_expected_actor,p_event_id,c.revision,p_kind,p_page_kind,p_target_id,p_asset_id,(target->>'categoryId')::uuid,at_value);
 return jsonb_build_object('recorded',true,'duplicate',false);
end $function$

CREATE OR REPLACE FUNCTION public.record_store_analytics_event(p_token_hash text, p_event_id uuid, p_page_kind text, p_target_id text, p_channel text, p_source text, p_medium text, p_link_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare session private.store_analytics_sessions; existing private.store_analytics_events; target jsonb; linked private.marketing_links;
 at_time timestamptz; fingerprint text; landing uuid;
begin
 perform private.store_analytics_require_service();
 if p_token_hash is null or p_token_hash!~'^[0-9a-f]{64}$' or p_event_id is null
  or p_page_kind is null or p_page_kind not in ('home','shop','good','stories','story','ip','events','event')
  or p_target_id is null or length(p_target_id) not between 1 and 200 or p_target_id~'[[:cntrl:]]'
  or p_channel is null or p_channel not in ('direct','search','social','email','paid','referral','internal')
  or p_source is null or p_source not in ('none','google','naver','bing','daum','instagram','facebook','youtube','kakao','x','threads','email','other','icons')
  or p_medium is null or p_medium not in ('none','organic','social','email','cpc','paid_social','referral','internal')
  or(p_link_token is not null and p_link_token!~'^[0-9a-f]{32}$') then raise invalid_parameter_value using message='analytics_invalid_event';end if;
 perform 1 from private.store_analytics_settings where id and enabled for share;
 if not found then raise object_not_in_prerequisite_state using message='analytics_disabled';end if;
 select * into session from private.store_analytics_sessions where token_hash=p_token_hash for update;
 at_time:=clock_timestamp();
 if not found or session.revoked_at is not null then raise invalid_authorization_specification using message='analytics_session_unavailable';end if;
 fingerprint:=encode(extensions.digest(jsonb_build_array(p_page_kind,p_target_id,p_channel,p_source,p_medium,p_link_token)::text,'sha256'),'hex');
 select * into existing from private.store_analytics_events where id=p_event_id;
 if found then
  if existing.session_id<>session.id or existing.payload_hash<>fingerprint then raise exception using errcode='PT409',message='analytics_event_conflict';end if;
  return jsonb_build_object('recorded',true,'replayed',true);
 end if;
 if at_time>=session.last_seen_at+interval '30 minutes' or at_time>=session.created_at+interval '24 hours'
  or (at_time at time zone 'Asia/Seoul')::date<>(session.created_at at time zone 'Asia/Seoul')::date then
  raise invalid_authorization_specification using message='analytics_session_expired';end if;
 if session.event_count>=2000 then raise exception using errcode='P0429',message='analytics_rate_limited';end if;
 target:=private.store_analytics_page(p_page_kind,p_target_id,at_time);
 if target is null then raise no_data_found using message='analytics_page_unavailable';end if;
 if p_link_token is not null then
  select * into linked from private.marketing_links where token=p_link_token;
  if not found or not private.marketing_link_available(linked)
   or not((linked.source='home' and p_page_kind='home') or(linked.source='good' and p_page_kind='good' and linked.good_id=p_target_id)
    or(linked.source='story' and p_page_kind='story' and linked.story_id::text=p_target_id)
    or(linked.source='category' and p_page_kind='shop' and linked.category_id::text=p_target_id)) then
   raise invalid_parameter_value using message='analytics_link_target_mismatch';end if;
  landing:=linked.id;
 end if;
 perform private.store_analytics_rate('events',10000,at_time);
 perform private.store_analytics_rate('session:'||session.id::text,120,at_time);
 -- Direct/internal navigation keeps the most recent measured acquisition.
 if session.event_count=0 or landing is not null or p_channel not in ('direct','internal') then
  session.channel:=p_channel;session.source:=p_source;session.medium:=p_medium;session.last_link_id:=landing;
 end if;
 insert into private.store_analytics_events(id,session_id,observed_at,page_kind,target_id,ip_id,category_id,channel,source,medium,link_id,landing_link_id,payload_hash)
 values(p_event_id,session.id,at_time,p_page_kind,p_target_id,target->>'ipId',(target->>'categoryId')::uuid,
  session.channel,session.source,session.medium,session.last_link_id,landing,fingerprint);
 update private.store_analytics_sessions set last_seen_at=at_time,event_count=event_count+1,
  channel=session.channel,source=session.source,medium=session.medium,last_link_id=session.last_link_id,last_page_kind=p_page_kind,last_page_target=p_target_id where id=session.id;
 insert into private.store_analytics_health(minute,observed_at) values(date_trunc('minute',at_time),at_time) on conflict(minute) do nothing;
 return jsonb_build_object('recorded',true,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.record_store_analytics_notice_event(p_token_hash text, p_event_id uuid, p_curation_id uuid, p_interaction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare session private.store_analytics_sessions; existing private.store_analytics_notice_events; at_time timestamptz;
 fingerprint text; notice_kind text; recorded integer;
begin
 perform private.store_analytics_require_service();
 if p_token_hash is null or p_token_hash!~'^[0-9a-f]{64}$' or p_event_id is null or p_curation_id is null
  or p_interaction is null or p_interaction not in ('impression','click') then
  raise invalid_parameter_value using message='analytics_invalid_event';end if;
 perform 1 from private.store_analytics_settings where id and enabled for share;
 if not found then raise object_not_in_prerequisite_state using message='analytics_disabled';end if;
 select * into session from private.store_analytics_sessions where token_hash=p_token_hash for update;
 at_time:=clock_timestamp();
 if not found or session.revoked_at is not null then raise invalid_authorization_specification using message='analytics_session_unavailable';end if;
 fingerprint:=encode(extensions.digest(jsonb_build_array('notice',p_curation_id,p_interaction)::text,'sha256'),'hex');
 select * into existing from private.store_analytics_notice_events where id=p_event_id;
 if found then
  if existing.session_id<>session.id or existing.payload_hash<>fingerprint then raise exception using errcode='PT409',message='analytics_event_conflict';end if;
  return jsonb_build_object('recorded',true,'replayed',true);
 end if;
 if at_time>=session.last_seen_at+interval '30 minutes' or at_time>=session.created_at+interval '24 hours'
  or (at_time at time zone 'Asia/Seoul')::date<>(session.created_at at time zone 'Asia/Seoul')::date then
  raise invalid_authorization_specification using message='analytics_session_expired';end if;
 -- Only a notice the public shell can show at this instant is countable; an
 -- arbitrary identifier, a disabled, scheduled, ended or other-kind row is not.
 select c.kind into notice_kind from public.home_curations c
  where c.id=p_curation_id and c.kind in ('notice_bar','notice_strip') and c.enabled and c.archived_at is null
   and c.active_from<=at_time and (c.active_to is null or c.active_to>at_time);
 if not found then raise no_data_found using message='analytics_notice_unavailable';end if;
 -- A click must follow an impression of the same notice in the same session.
 if p_interaction='click' and not exists(select 1 from private.store_analytics_notice_events e
  where e.session_id=session.id and e.curation_id=p_curation_id and e.interaction='impression') then
  raise invalid_parameter_value using message='analytics_notice_not_shown';end if;
 select count(*) into recorded from private.store_analytics_notice_events where session_id=session.id;
 if recorded>=500 then raise exception using errcode='P0429',message='analytics_rate_limited';end if;
 perform private.store_analytics_rate('notice-events',10000,at_time);
 -- Shares the session's page-view budget: one browsing session, one limit.
 perform private.store_analytics_rate('session:'||session.id::text,120,at_time);
 insert into private.store_analytics_notice_events(id,session_id,observed_at,curation_id,placement,interaction,payload_hash)
 values(p_event_id,session.id,at_time,p_curation_id,notice_kind,p_interaction,fingerprint);
 insert into private.store_analytics_health(minute,observed_at) values(date_trunc('minute',at_time),at_time) on conflict(minute) do nothing;
 return jsonb_build_object('recorded',true,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.recover_email_acceptance_persistence_failure(target_intent_id uuid, target_claim_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_intent private.email_intents%rowtype;
begin
  if target_intent_id is null or target_claim_id is null then
    raise check_violation using message = 'invalid_email_dispatch_recovery_claim';
  end if;

  select * into v_intent
  from private.email_intents as intent
  where intent.id = target_intent_id
  for update;
  if not found then raise no_data_found using message = 'email_intent_not_found'; end if;

  if v_intent.state = 'dispatching'
    and v_intent.dispatch_claim_id = target_claim_id
  then
    update private.email_intents set
      state = 'unknown',
      dispatch_claim_id = null,
      updated_at = pg_catalog.now()
    where id = v_intent.id
    returning * into v_intent;
    return pg_catalog.jsonb_build_object('kind', 'released', 'state', 'unknown');
  end if;

  return pg_catalog.jsonb_build_object('kind', 'preserved', 'state', v_intent.state);
end;
$function$

CREATE OR REPLACE FUNCTION public.reduce_email_provider_event(target_svix_id text, target_provider_reference_digest text, target_event_type text, target_occurred_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_provider_digest bytea := private.email_digest_from_hex(target_provider_reference_digest);
  v_intent private.email_intents%rowtype;
  v_existing private.email_provider_events%rowtype;
  v_next_state text;
  v_matched boolean := false;
begin
  if target_svix_id is null or target_svix_id !~ '^[A-Za-z0-9._:-]{1,200}$' then
    raise check_violation using message = 'invalid_email_provider_event_id';
  end if;
  if target_event_type not in ('sent', 'delivered', 'delayed', 'bounced', 'complained', 'suppressed', 'failed') then
    raise check_violation using message = 'invalid_email_provider_event_type';
  end if;
  if target_occurred_at is null or target_occurred_at > pg_catalog.now() + interval '5 minutes' then
    raise check_violation using message = 'invalid_email_provider_event_time';
  end if;

  -- Every provider-reference owner/attachment path takes the digest lock first.
  -- Event reducers then take the svix lock. This global order makes acceptance
  -- versus webhook attachment atomic and makes concurrent duplicate delivery a
  -- durable replay instead of a unique-violation response.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'email-provider:' || encode(v_provider_digest, 'hex'),
      0
    )
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('email-provider-event:' || target_svix_id, 0)
  );

  select * into v_existing
  from private.email_provider_events as event
  where event.svix_id = target_svix_id;
  if found then
    if v_existing.provider_reference_digest is distinct from v_provider_digest
      or v_existing.event_type is distinct from target_event_type
      or v_existing.occurred_at is distinct from target_occurred_at
    then
      raise unique_violation using message = 'email_provider_event_id_conflict';
    end if;
    return pg_catalog.jsonb_build_object(
      'kind', 'duplicate',
      'state', coalesce((select state from private.email_intents where id = v_existing.intent_id), 'unknown')
    );
  end if;

  select * into v_intent
  from private.email_intents as intent
  where intent.provider_reference_digest = v_provider_digest
  for update;
  v_matched := found;

  insert into private.email_provider_events (
    svix_id, intent_id, provider_reference_digest, event_type, occurred_at
  ) values (
    target_svix_id,
    case when v_matched then v_intent.id else null end,
    v_provider_digest,
    target_event_type,
    target_occurred_at
  );

  if not v_matched then
    return pg_catalog.jsonb_build_object('kind', 'unmatched', 'state', 'unknown');
  end if;

  -- Lifecycle rank is monotonic, so out-of-order delivery cannot regress delivered to
  -- sent/delayed or erase a bounce with a later replay. Repeated events at the same rank
  -- retain the latest provider occurrence timestamp.
  v_next_state := v_intent.state;
  if v_intent.state <> 'needs_review'
    and private.email_terminal_rank(target_event_type)
    > private.email_terminal_rank(v_intent.state)
  then
    v_next_state := target_event_type;
  end if;

  update private.email_intents set
    state = v_next_state,
    state_occurred_at = case
      when v_next_state = target_event_type then greatest(
        coalesce(state_occurred_at, '-infinity'::timestamptz),
        target_occurred_at
      )
      else state_occurred_at
    end,
    delivered_at = case when target_event_type = 'delivered'
      then coalesce(delivered_at, target_occurred_at) else delivered_at end,
    terminal_at = case when target_event_type in ('bounced', 'complained', 'suppressed', 'failed')
      then coalesce(terminal_at, target_occurred_at) else terminal_at end,
    updated_at = pg_catalog.now()
  where id = v_intent.id
  returning * into v_intent;

  return pg_catalog.jsonb_build_object(
    'kind', 'reduced', 'intentId', v_intent.id, 'state', v_intent.state
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.refund_ticket_order(p_ticket_order_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order_status public.ticket_order_status;
  v_reservation public.ticket_order_reservations%rowtype;
begin
  -- Keep the legacy signature stable for callers while retaining the reason
  -- as an explicit input to this operational path.
  perform p_reason;

  select ticket_order.status
  into v_order_status
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;
  if not found then
    raise no_data_found using message = 'ticket order not found';
  end if;
  if v_order_status = 'canceled' then
    return;
  end if;

  perform request.id
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = p_ticket_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  for update of request;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket' and payment.ref_id = p_ticket_order_id
  order by payment.id
  for update of payment;

  perform attempt.id
  from public.payment_attempts as attempt
  where attempt.purpose = 'ticket' and attempt.ref_id = p_ticket_order_id
  order by attempt.id
  for update of attempt;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = p_ticket_order_id
  order by ticket.id
  for update of ticket;

  select reservation.*
  into v_reservation
  from public.ticket_order_reservations as reservation
  where reservation.ticket_order_id = p_ticket_order_id
  for update;
  if not found then
    raise check_violation using message = 'ticket reservation missing';
  end if;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id = v_reservation.ticket_type_id
  for update of ticket_type;

  if v_order_status <> 'pending' then
    raise check_violation using message = 'payment evidence required';
  end if;
  if exists (
    select 1 from public.payments as payment
    where payment.purpose = 'ticket'
      and payment.ref_id = p_ticket_order_id
      and payment.status in ('pending', 'paid')
  ) then
    raise check_violation using message = 'provider cancellation required';
  end if;
  if exists (
    select 1 from public.payment_attempts as attempt
    where attempt.purpose = 'ticket'
      and attempt.ref_id = p_ticket_order_id
      and attempt.state in ('confirming', 'approved', 'unknown', 'needs_review')
  ) then
    raise check_violation using message = 'provider reconciliation required';
  end if;

  update public.payment_attempts
  set
    state = 'canceled',
    claim_token = null,
    claim_expires_at = null
  where purpose = 'ticket'
    and ref_id = p_ticket_order_id
    and state = 'prepared';

  update public.ticket_types
  set sold = sold - v_reservation.quantity
  where id = v_reservation.ticket_type_id;

  update public.tickets
  set status = 'refunded'
  where ticket_order_id = p_ticket_order_id;

  update public.ticket_orders
  set status = 'canceled', expires_at = null
  where id = p_ticket_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.release_unpaid_cart_orders(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_user_id is null then
    raise invalid_parameter_value using message = 'cart_order_supersede_invalid';
  end if;
  -- 주문 생성·쿠폰 선택과 같은 계정 잠금. 장바구니 잠금은 잡지 않는다.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text, 0));
  if not exists (
    select 1 from private.cart_order_holds as hold
    where hold.user_id = p_user_id and hold.state = 'awaiting_payment'
  ) then
    return 0;
  end if;
  return private.supersede_unpaid_cart_orders(p_user_id, false);
end;
$function$

CREATE OR REPLACE FUNCTION public.release_unpaid_checkout_orders(p_user_id uuid, p_order_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  v_result text;
  v_released integer := 0;
  v_confirming integer := 0;
begin
  if p_user_id is null or p_order_ids is null or pg_catalog.cardinality(p_order_ids) not between 1 and 20
    or pg_catalog.array_position(p_order_ids, null) is not null then
    raise invalid_parameter_value using message = 'cart_order_supersede_invalid';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text, 0));
  perform 1
  from public.orders as o
  join private.cart_order_holds as hold on hold.order_id = o.id
  where hold.user_id = p_user_id and hold.state = 'awaiting_payment' and o.id = any (p_order_ids)
  order by o.id
  for update of o;
  if found then
    perform private.lock_account_action_subject(p_user_id);
    for r in
      select hold.order_id
      from private.cart_order_holds as hold
      where hold.user_id = p_user_id and hold.state = 'awaiting_payment' and hold.order_id = any (p_order_ids)
      order by hold.created_at, hold.order_id
    loop
      v_result := private.close_unpaid_cart_order(r.order_id, '고객이 진행 중인 미결제 주문을 취소하고 주문을 계속함', 'customer_released');
      if v_result = 'closed' then
        v_released := v_released + 1;
      elsif v_result in ('payment_confirming', 'unresolved') then
        v_confirming := v_confirming + 1;
      end if;
    end loop;
  end if;
  return pg_catalog.jsonb_build_object('released', v_released, 'confirming', v_confirming);
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_cart_lines(p_lines jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
  removed integer := 0;
begin
  if actor is null then
    raise insufficient_privilege using message = 'auth required';
  end if;
  if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) not between 1 and 19239
    or exists (
      select 1 from jsonb_array_elements(p_lines) as line
      where jsonb_typeof(line) <> 'object'
        or not line ?& array['good_id', 'variant_id', 'input_revision', 'input_values']
        or exists (select 1 from jsonb_object_keys(line) as key
          where key not in ('good_id', 'variant_id', 'input_revision', 'input_values'))
        or jsonb_typeof(line -> 'good_id') <> 'string' or nullif(btrim(line ->> 'good_id'), '') is null
        or jsonb_typeof(line -> 'variant_id') <> 'string'
        or line ->> 'variant_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(line -> 'input_revision') <> 'number' or line ->> 'input_revision' !~ '^(0|[1-9][0-9]*)$'
        or jsonb_typeof(line -> 'input_values') <> 'object'
    )
  then
    raise invalid_parameter_value using message = 'invalid cart lines';
  end if;
  -- 담기·수량 변경·병합과 같은 순서로 잠근다(20261020085341). 정지 계정은 장바구니를 바꾸지 못한다.
  perform private.lock_goods_transaction_actor(actor);
  perform private.assert_active_user(actor);
  perform pg_advisory_xact_lock(hashtextextended('cart:' || actor::text, 0));
  delete from public.cart_items as cart
  using (
    select distinct line.good_id, line.variant_id, line.input_revision, line.input_values
    from jsonb_to_recordset(p_lines) as line(good_id text, variant_id uuid, input_revision integer, input_values jsonb)
  ) as requested
  where cart.user_id = actor
    and cart.good_id = requested.good_id
    and cart.variant_id = requested.variant_id
    and cart.input_revision = requested.input_revision
    and cart.input_values = requested.input_values;
  get diagnostics removed = row_count;
  return removed;
end;
$function$

CREATE OR REPLACE FUNCTION public.replay_my_gift_order(p_id uuid, p_quote_id uuid, p_checkout_key uuid, p_payment_method public.order_payment_method, p_expected_actor_id uuid)
 RETURNS uuid
