CREATE OR REPLACE FUNCTION public.request_my_account_deletion(p_confirmation text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_enabled boolean := false;
  v_existing private.account_deletion_requests%rowtype;
  v_blockers jsonb;
  v_internal_status text;
  v_deletion_event_id uuid;
begin
  if v_user_id is null then
    raise insufficient_privilege using message = 'authentication_required';
  end if;
  if p_confirmation is distinct from '회원 탈퇴를 신청합니다' then
    raise check_violation using message = 'account_deletion_confirmation_mismatch';
  end if;
  if p_idempotency_key is null then
    raise not_null_violation using message = 'account_deletion_idempotency_key_required';
  end if;

  select control.phase_one_enabled
    into v_enabled
  from private.account_deletion_control as control
  where control.singleton
  for share;
  if not coalesce(v_enabled, false) then
    raise object_not_in_prerequisite_state
      using message = 'account_deletion_not_available';
  end if;

  if not exists (
    select 1 from public.profiles as profile where profile.id = v_user_id
  ) then
    raise no_data_found using message = 'account_not_found';
  end if;

  if not private.has_recent_account_authentication(v_user_id) then
    raise object_not_in_prerequisite_state
      using message = 'account_deletion_reauthentication_required';
  end if;

  perform private.lock_account_action_subject(v_user_id);

  select request.*
    into v_existing
  from private.account_deletion_requests as request
  where request.subject_user_id = v_user_id;

  if found then
    if v_existing.idempotency_key is distinct from p_idempotency_key then
      raise unique_violation using message = 'account_deletion_idempotency_conflict';
    end if;
    return private.reconcile_account_deletion_request(v_user_id);
  end if;

  v_blockers := private.account_deletion_blockers(v_user_id);
  v_internal_status := case
    when v_blockers = '[]'::jsonb then 'awaiting_email_intent'
    else 'blocked_active_obligation'
  end;

  insert into private.account_deletion_requests (
    subject_user_id,
    idempotency_key,
    status,
    blocker_summary
  )
  values (v_user_id, p_idempotency_key, v_internal_status, v_blockers)
  returning deletion_event_id into v_deletion_event_id;

  perform private.snapshot_account_deletion_legal_records(
    v_deletion_event_id,
    v_user_id
  );

  insert into private.account_action_fences (
    subject_user_id,
    deletion_event_id
  )
  values (v_user_id, v_deletion_event_id);

  return private.account_deletion_public_status(v_user_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.request_my_billing_credential_revocation(p_expected_actor_id uuid, p_credential_id uuid, p_expected_revision bigint, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare actor uuid:=auth.uid();credential private.billing_credentials;operation private.billing_credential_operations;result jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id or p_operation_id is null then raise insufficient_privilege using message='subscription_actor_changed';end if;
 perform private.subscription_lock_actor(actor,false);
 perform pg_advisory_xact_lock(hashtextextended('billing-credential-operation:'||p_operation_id::text,0));
 select * into operation from private.billing_credential_operations where operation_id=p_operation_id;
 if found then
  if operation.owner_id<>actor or operation.credential_id<>p_credential_id or operation.expected_revision is distinct from p_expected_revision then
   raise sqlstate 'PT409' using message='billing_credential_operation_conflict';end if;return operation.receipt;
 end if;
 select * into credential from private.billing_credentials where id=p_credential_id and owner_id=actor for update;
 if not found then raise no_data_found using message='billing_credential_not_found';end if;
 if credential.revision is distinct from p_expected_revision then raise sqlstate 'PT409' using message='billing_credential_changed';end if;
 if exists(select 1 from private.goods_subscription_plans where credential_id=p_credential_id and state in('active','awaiting_first_payment','paused','needs_confirmation'))
  or exists(select 1 from private.goods_subscription_cycles c join private.payment_provider_bindings b on b.cycle_id=c.id
   where b.credential_id=p_credential_id and c.state in('dispatching','unknown','needs_review')) then
  raise object_not_in_prerequisite_state using message='billing_credential_in_use';end if;
 if credential.state<>'revoked' then
  update private.billing_credentials set state='revoking',revision=revision+1,revoke_next_check_at=clock_timestamp() where id=p_credential_id returning * into credential;
 end if;
 result:=jsonb_build_object('operationId',p_operation_id,'credentialId',credential.id,'revision',credential.revision,'state',credential.state);
 insert into private.billing_credential_operations(operation_id,owner_id,credential_id,expected_revision,receipt)
  values(p_operation_id,actor,p_credential_id,p_expected_revision,result);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,actor,'billing.card.revocation_requested','billing-credential:'||p_credential_id::text,
  jsonb_build_object('revision',credential.revision,'state',credential.state));return result;
end $function$

CREATE OR REPLACE FUNCTION public.request_my_gift_claim(p_gift_id uuid, p_claim_type text, p_reason_type text, p_operation_id uuid, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare actor uuid:=auth.uid();gift private.gift_intents;previous private.gift_claim_operations;request_hash text;outcome jsonb;claim_id uuid;result jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 if p_operation_id is null or p_claim_type is null or p_claim_type not in('return','exchange') or p_reason_type is null or p_reason_type not in('change_of_mind','defect') then raise invalid_parameter_value using message='invalid_gift_claim';end if;
 select * into gift from private.gift_intents where id=p_gift_id and(actor=sender_id or actor=recipient_id);
 if not found or gift.order_id is null then raise no_data_found using message='gift_not_found';end if;
 perform private.gift_lock_subjects(array[actor,gift.sender_id,gift.recipient_id]);
 perform pg_advisory_xact_lock(hashtextextended('gift-claim-operation:'||p_operation_id,0));
 request_hash:=encode(extensions.digest(jsonb_build_array(p_gift_id,p_claim_type,p_reason_type)::text,'sha256'),'hex');
 select * into previous from private.gift_claim_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.gift_id<>p_gift_id or previous.kind<>'requested' or previous.request_hash<>request_hash then raise unique_violation using message='gift_operation_conflict';end if;
  return jsonb_build_object('receipt',previous.result,'context',private.gift_claim_context(actor,p_gift_id));
 end if;
 outcome:=private.request_order_claim_for_parties(gift.order_id,actor,gift.sender_id,gift.id,p_claim_type,
  case p_reason_type when 'defect' then '상품 하자' else '단순 변심' end,p_reason_type);
 if outcome->>'outcome'<>'requested' then raise check_violation using message=outcome->>'outcome';end if;
 claim_id:=(outcome->>'claimId')::uuid;
 result:=jsonb_build_object('operationId',p_operation_id,'kind','requested','claimId',claim_id);
 insert into private.gift_claim_operations(id,actor_id,gift_id,kind,request_hash,result) values(p_operation_id,actor,p_gift_id,'requested',request_hash,result);
 return jsonb_build_object('receipt',result,'context',private.gift_claim_context(actor,p_gift_id));
end $function$

CREATE OR REPLACE FUNCTION public.request_restock_alert(target_good_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := (select auth.uid());
  good_stock text;
  good_archived_at timestamptz;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if private.is_account_write_fenced(actor_id) then
    raise object_not_in_prerequisite_state using message = 'account_deletion_write_fenced';
  end if;

  if exists (select 1 from public.profiles as profile where profile.id = actor_id and profile.suspended_at is not null) then
    raise insufficient_privilege using message = 'account_suspended';
  end if;

  -- 판정과 신청 사이에 재입고 전이가 끼지 않도록 굿즈 행을 잠근다(전이 쪽은 for update).
  select good.stock, good.archived_at
  into good_stock, good_archived_at
  from public.goods as good
  where good.id = target_good_id
  for share;

  if not found or good_archived_at is not null then
    raise exception 'good_missing' using errcode = 'P0002';
  end if;

  -- 판매 중인 굿즈에 신청이 붙으면 전이 조건(거짓→참)이 영영 성립하지 않는다.
  if good_stock <> 'soldout' and exists (
    select 1 from public.goods_variants as variant
    where variant.good_id = target_good_id
      and variant.archived_at is null
      and variant.preorder_policy_id is null
      and variant.stock_qty > 0
  ) then
    raise exception 'good_available' using errcode = '22023';
  end if;

  insert into public.restock_alerts (user_id, good_id, variant_id)
  values (actor_id, target_good_id, null)
  on conflict (user_id, good_id, variant_id)
  do update set status = 'pending', notified_at = null, created_at = now();
end;
$function$

CREATE OR REPLACE FUNCTION public.request_ticket_cancellation(p_user_id uuid, p_ticket_order_id uuid)
 RETURNS TABLE(request_id uuid, result text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order_user_id uuid;
  v_order_status public.ticket_order_status;
  v_order_total bigint;
  v_event_id text;
  v_cutoff_at timestamptz;
  v_existing_request record;
  v_reservation public.ticket_order_reservations%rowtype;
begin
  select
    ticket_order.user_id,
    ticket_order.status,
    ticket_order.total,
    ticket_order.event_id
  into
    v_order_user_id,
    v_order_status,
    v_order_total,
    v_event_id
  from public.ticket_orders as ticket_order
  where ticket_order.id = p_ticket_order_id
  for update of ticket_order;

  if not found or p_user_id is null or v_order_user_id is distinct from p_user_id then
    request_id := null;
    result := 'not_found';
    return next;
    return;
  end if;
  if v_order_status = 'canceled' then
    select request.id into request_id
    from public.ticket_cancellation_requests as request
    where request.ticket_order_id = p_ticket_order_id
      and request.status = 'completed'
    order by request.requested_at desc, request.id
    limit 1;
    result := case when request_id is null then 'already_canceled' else 'completed' end;
    return next;
    return;
  end if;
  if v_order_status not in ('pending', 'paid') then
    request_id := null;
    result := 'not_cancelable';
    return next;
    return;
  end if;

  select request.id, request.status
  into v_existing_request
  from public.ticket_cancellation_requests as request
  where request.ticket_order_id = p_ticket_order_id
    and request.status in ('requested', 'processing', 'needs_review')
  order by request.requested_at desc, request.id
  limit 1
  for update of request;
  if found then
    request_id := v_existing_request.id;
    result := v_existing_request.status;
    return next;
    return;
  end if;

  select event_record.starts_at
  into v_cutoff_at
  from public.events as event_record
  where event_record.id = v_event_id
  for share of event_record;
  if v_cutoff_at is null or now() >= v_cutoff_at then
    request_id := null;
    result := 'policy_closed';
    return next;
    return;
  end if;

  perform payment.id
  from public.payments as payment
  where payment.purpose = 'ticket' and payment.ref_id = p_ticket_order_id
  order by payment.id
  for update of payment;

  perform attempt.id
  from public.payment_attempts as attempt
  where attempt.purpose = 'ticket' and attempt.ref_id = p_ticket_order_id
  order by attempt.id
  for update of attempt;

  perform ticket.id
  from public.tickets as ticket
  where ticket.ticket_order_id = p_ticket_order_id
  order by ticket.id
  for update of ticket;

  select reservation.*
  into v_reservation
  from public.ticket_order_reservations as reservation
  where reservation.ticket_order_id = p_ticket_order_id
  for update;
  if not found then
    request_id := null;
    result := 'not_cancelable';
    return next;
    return;
  end if;

  perform ticket_type.id
  from public.ticket_types as ticket_type
  where ticket_type.id = v_reservation.ticket_type_id
  for update of ticket_type;

  if v_order_status = 'paid' and (
    not exists (
      select 1 from public.tickets as ticket
      where ticket.ticket_order_id = p_ticket_order_id
    )
    or exists (
      select 1 from public.tickets as ticket
      where ticket.ticket_order_id = p_ticket_order_id
        and ticket.status <> 'valid'
    )
  ) then
    request_id := null;
    result := 'not_cancelable';
    return next;
    return;
  end if;

  insert into public.ticket_cancellation_requests (
    ticket_order_id,
    requested_by,
    source,
    status,
    policy_code,
    cutoff_at,
    gross_amount,
    fee_amount,
    refund_amount,
    reason
  )
  values (
    p_ticket_order_id,
    p_user_id,
    'user',
    'requested',
    'event_start_full_refund_v1',
    v_cutoff_at,
    v_order_total,
    0,
    v_order_total,
    '사용자 예매 취소 요청'
  )
  returning id into request_id;

  insert into public.audit_log (actor_id, action, target, diff)
  values (
    p_user_id,
    'ticket.cancellation.requested',
    'ticket_order:' || p_ticket_order_id::text,
    jsonb_build_object(
      'requestId', request_id,
      'source', 'user',
      'policyCode', 'event_start_full_refund_v1',
      'to', 'requested'
    )
  );

  if v_order_status = 'pending'
    and not exists (
      select 1 from public.payments as payment
      where payment.purpose = 'ticket'
        and payment.ref_id = p_ticket_order_id
        and payment.status in ('pending', 'paid')
    )
    and not exists (
      select 1 from public.payment_attempts as attempt
      where attempt.purpose = 'ticket'
        and attempt.ref_id = p_ticket_order_id
        and attempt.state in ('prepared', 'confirming', 'approved', 'unknown', 'needs_review')
    )
  then
    result := public.finalize_ticket_cancellation_request(request_id, p_user_id);
  else
    result := 'requested';
  end if;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_variant_restock_alert(target_good_id text, target_variant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  good_stock text;
  good_archived_at timestamptz;
  variant_stock_qty integer;
  variant_archived_at timestamptz;
  variant_preorder_policy_id uuid;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if target_good_id is null or target_variant_id is null then
    raise exception 'variant_missing' using errcode = 'P0002';
  end if;

  if private.is_account_write_fenced(actor_id) then
    raise object_not_in_prerequisite_state using message = 'account_deletion_write_fenced';
  end if;

  if exists (select 1 from public.profiles as profile where profile.id = actor_id and profile.suspended_at is not null) then
    raise insufficient_privilege using message = 'account_suspended';
  end if;

  -- 굿즈 단위 신청과 같은 잠금. 옵션 행은 잠그지 않는다 — 재고를 쓰는 경로가 굿즈 → 옵션
  -- 순서로 잠그고, 옵션 재고 갱신 트리거와 옵션 전이 트리거가 굿즈 행을 for update 로 다시
  -- 잡으므로 이 잠금 하나로 판정·삽입과 전이가 직렬화된다.
  select good.stock, good.archived_at
  into good_stock, good_archived_at
  from public.goods as good
  where good.id = target_good_id
  for share;

  if not found or good_archived_at is not null then
    raise exception 'good_missing' using errcode = 'P0002';
  end if;

  -- 랜덤 판매 굿즈(D5②)는 옵션별 재고를 고객에게 숨긴다. 옵션 품절 여부로 판정하면 배정 결과가 드러난다.
  if exists(select 1 from public.goods as good where good.id = target_good_id and good.option_sale_mode = 'random') then
    if not exists(select 1 from public.goods_variants as variant
      where variant.id = target_variant_id and variant.good_id = target_good_id and variant.archived_at is null) then
      raise exception 'variant_missing' using errcode = 'P0002';
    end if;
    if good_stock <> 'soldout' and exists(select 1 from public.goods_variants as variant
      where variant.good_id = target_good_id and variant.archived_at is null
        and variant.preorder_policy_id is null and variant.stock_qty > 0) then
      raise exception 'variant_available' using errcode = '22023';
    end if;
    insert into public.restock_alerts (user_id, good_id, variant_id)
    values (actor_id, target_good_id, null)
    on conflict (user_id, good_id, variant_id)
    do update set status = 'pending', notified_at = null, created_at = now();
    return;
  end if;

  select variant.stock_qty, variant.archived_at, variant.preorder_policy_id
  into variant_stock_qty, variant_archived_at, variant_preorder_policy_id
  from public.goods_variants as variant
  where variant.id = target_variant_id
    and variant.good_id = target_good_id;

  if not found or variant_archived_at is not null then
    raise exception 'variant_missing' using errcode = 'P0002';
  end if;

  if variant_preorder_policy_id is not null then
    raise exception 'variant_preorder' using errcode = '22023';
  end if;

  if good_stock <> 'soldout' and variant_stock_qty > 0 then
    raise exception 'variant_available' using errcode = '22023';
  end if;

  insert into public.restock_alerts (user_id, good_id, variant_id)
  values (actor_id, target_good_id, target_variant_id)
  on conflict (user_id, good_id, variant_id)
  do update set status = 'pending', notified_at = null, created_at = now();
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_tickets(p_user_id uuid, p_ticket_type_id uuid, p_qty integer, p_reservation_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user uuid := p_user_id;
  v_event_id text;
  v_locked_event_id text;
  v_event_status text;
  v_ip_id text;
  v_capacity integer;
  v_sold integer;
  v_price integer;
  v_per_user_limit integer;
  v_sales_open_at timestamptz;
  v_existing_order public.ticket_orders%rowtype;
  v_existing_reservation public.ticket_order_reservations%rowtype;
  v_already_reserved bigint;
  v_order_id uuid;
begin
  if v_user is null then
    raise not_null_violation using message = 'user required';
  end if;

  perform private.assert_active_user(v_user);

  if not exists (
    select 1
    from public.profiles as profile
    join auth.users as auth_user on auth_user.id = profile.id
    where profile.id = v_user
      and nullif(btrim(coalesce(profile.email, auth_user.email)), '') is not null
      and nullif(btrim(profile.nickname), '') is not null
      and profile.birth_date is not null
      and profile.birth_date <= current_date
      and profile.onboarded_at is not null
      and profile.consents ->> 'terms' = 'true'
      and profile.consents ->> 'privacy' = 'true'
  ) or private.is_account_write_fenced(v_user) then
    raise insufficient_privilege using message = 'onboarding required';
  end if;

  if p_qty is null or p_qty < 1 then
    raise check_violation using message = 'quantity must be positive';
  end if;
  if p_reservation_key is null then
    raise not_null_violation using message = 'reservation key required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'ticket_reservation:' || v_user::text || ':' || p_reservation_key::text,
      0
    )
  );

  select ticket_order.*
  into v_existing_order
  from public.ticket_orders as ticket_order
  where ticket_order.user_id = v_user
    and ticket_order.reservation_key = p_reservation_key
  for share;

  if found then
    select reservation.*
    into v_existing_reservation
    from public.ticket_order_reservations as reservation
    where reservation.ticket_order_id = v_existing_order.id;

    if found
      and v_existing_reservation.ticket_type_id = p_ticket_type_id
      and v_existing_reservation.quantity = p_qty
    then
      return v_existing_order.id;
    end if;
    raise unique_violation using message = 'reservation conflict';
  end if;

  select ticket_type.event_id
  into v_event_id
  from public.ticket_types as ticket_type
  where ticket_type.id = p_ticket_type_id;
  if not found then
    raise no_data_found using message = 'ticket type not found';
  end if;

  select event_record.status, event_record.ip_id
  into v_event_status, v_ip_id
  from public.events as event_record
  where event_record.id = v_event_id
  for share of event_record;
  if not found then
    raise no_data_found using message = 'event not found';
  end if;

  -- Event SHARE fixes ip_id; the parent SHARE lock lives through reservation
  -- commit. Platform events without an IP remain bookable.
  perform private.assert_ip_purchasable(v_ip_id);

  select
    ticket_type.event_id,
    ticket_type.capacity,
    ticket_type.sold,
    ticket_type.price,
    ticket_type.per_user_limit,
    ticket_type.sales_open_at
  into
    v_locked_event_id,
    v_capacity,
    v_sold,
    v_price,
    v_per_user_limit,
    v_sales_open_at
  from public.ticket_types as ticket_type
  where ticket_type.id = p_ticket_type_id
  for update of ticket_type;

  if not found then
    raise no_data_found using message = 'ticket type not found';
  end if;
  if v_locked_event_id is distinct from v_event_id then
    raise serialization_failure using message = 'ticket type changed';
  end if;
  if v_event_status <> '예매중' then
    raise check_violation using message = 'event not bookable';
  end if;
  if v_price <= 0 then
    raise check_violation using message = 'paid ticket required';
  end if;
  if v_sales_open_at is not null and now() < v_sales_open_at then
    raise check_violation using message = 'sales not open';
  end if;
  if p_qty::bigint > v_capacity::bigint - v_sold::bigint then
    raise check_violation using message = 'sold out';
  end if;

  select coalesce(sum(reservation.quantity), 0)
  into v_already_reserved
  from public.ticket_order_reservations as reservation
  join public.ticket_orders as ticket_order
    on ticket_order.id = reservation.ticket_order_id
  where reservation.ticket_type_id = p_ticket_type_id
    and ticket_order.user_id = v_user
    and ticket_order.status <> 'canceled';

  if v_already_reserved + p_qty::bigint > v_per_user_limit::bigint then
    raise check_violation using message = 'per-user limit exceeded';
  end if;

  update public.ticket_types
  set sold = sold + p_qty
  where id = p_ticket_type_id;

  insert into public.ticket_orders (
    user_id,
    event_id,
    status,
    total,
    expires_at,
    reservation_key
  )
  values (
    v_user,
    v_event_id,
    'pending',
    v_price::bigint * p_qty::bigint,
    now() + interval '10 minutes',
    p_reservation_key
  )
  returning id into v_order_id;

  insert into public.ticket_order_reservations (
    ticket_order_id,
    ticket_type_id,
    quantity,
    unit_price
  )
  values (v_order_id, p_ticket_type_id, p_qty, v_price);

  return v_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_gift(p_id uuid, p_session_hash text, p_accept boolean, p_address jsonb, p_expected_revision bigint, p_operation_id uuid, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();gift private.gift_intents;request jsonb;address jsonb;at_time timestamptz;begin
 if actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_lock(p_id,actor);
 if p_accept is null or p_expected_revision is null then raise invalid_parameter_value using message='gift_response_invalid';end if;
 address:=case when p_accept then private.normalize_order_address_change(p_address) else null end;
 if not p_accept and p_address is not null then raise invalid_parameter_value using message='gift_response_invalid';end if;
 request:=jsonb_build_object('sessionHash',p_session_hash,'accept',p_accept,'address',address,'revision',p_expected_revision);
 if private.gift_operation_replay(actor,p_id,'responded',request,p_operation_id) then return private.gift_operation_result(actor,p_operation_id);end if;
 perform private.gift_require_actor(actor);perform private.gift_require_runtime();
 at_time:=clock_timestamp();
 if private.gift_session_id(p_session_hash,at_time) is distinct from p_id then raise insufficient_privilege using message='gift_invitation_unavailable';end if;
 if gift.revision<>p_expected_revision then raise sqlstate 'PT409' using message='gift_changed';end if;
 if gift.state<>'awaiting_acceptance' or gift.expires_at<=at_time then raise check_violation using message='gift_response_closed';end if;
 perform private.gift_require_actor(gift.sender_id);
 if p_accept then
  perform private.gift_selection_display(private.gift_selection(p_id));
  insert into private.gift_recipient_addresses(gift_id,recipient_id,address) values(p_id,actor,address);
 end if;
 update private.gift_intents set recipient_id=actor,recipient_label=(select nickname from public.profiles where id=actor),state=case when p_accept then 'accepted' else 'declined' end,
  accepted_at=case when p_accept then clock_timestamp() end,closed_at=case when not p_accept then clock_timestamp() end,revision=revision+1,updated_at=clock_timestamp() where id=p_id;
 update private.gift_link_tokens set consumed_at=clock_timestamp() where gift_id=p_id and revoked_at is null;
 perform private.gift_record_operation(actor,p_id,'responded',request,p_operation_id);return private.gift_operation_result(actor,p_operation_id);
end $function$

CREATE OR REPLACE FUNCTION public.resume_cart_goods_transaction(p_user_id uuid, p_quote_id uuid, p_checkout_key uuid, p_payment_method public.order_payment_method, p_allow_new boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare existing private.order_goods_transactions;quoted private.goods_transaction_quotes;source jsonb;receipt jsonb;expected_cart jsonb;begin
 if p_user_id is null then raise invalid_parameter_value using message='invalid_transaction_actor';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
 if p_quote_id is null or p_checkout_key is null or p_payment_method is null or p_allow_new is null then
  raise invalid_parameter_value using message='invalid_transaction_resume';end if;
 select * into existing from private.order_goods_transactions where actor_id=p_user_id and checkout_key=p_checkout_key;
 if found then
  perform private.lock_goods_transaction_actor(p_user_id);
  if existing.source_kind<>'cart' then raise sqlstate 'PT409' using message='checkout_key_conflict';end if;
  source:=jsonb_build_object('kind',existing.source_kind,'id',existing.source_id,'revision',existing.source_revision);
  receipt:=private.replay_goods_transaction_receipt(p_user_id,source,p_quote_id,p_checkout_key,p_payment_method);
  return (receipt->>'orderId')::uuid;
 end if;
 if not p_allow_new then raise check_violation using message='transaction_new_payment_disabled';end if;
 select * into quoted from private.goods_transaction_quotes where id=p_quote_id and actor_id=p_user_id;
 if not found or quoted.source->>'kind'<>'cart' or quoted.source->>'id'<>p_user_id::text then
  raise sqlstate 'PT409' using message='transaction_quote_expired';end if;
 select jsonb_agg(jsonb_build_object('good_id',value->'goodId','variant_id',value->'variantId','qty',value->'qty',
  'input_revision',value->'inputRevision','input_values',value->'inputValues')) into expected_cart from jsonb_array_elements(quoted.selection);
 return public.place_cart_goods_transaction(p_user_id,expected_cart,quoted.address,p_quote_id,p_checkout_key,p_payment_method);
end $function$

CREATE OR REPLACE FUNCTION public.resume_direct_goods_transaction(p_user_id uuid, p_draft_id uuid, p_quote_id uuid, p_checkout_key uuid, p_payment_method public.order_payment_method, p_allow_new boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare existing private.order_goods_transactions; quoted private.goods_transaction_quotes;
begin
  if p_user_id is null then raise invalid_parameter_value using message = 'invalid_transaction_actor'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));
  if p_quote_id is null or p_checkout_key is null or p_payment_method is null or p_allow_new is null then
    raise invalid_parameter_value using message = 'invalid_transaction_resume'; end if;
  select * into existing from private.order_goods_transactions where actor_id = p_user_id and checkout_key = p_checkout_key;
  if found then
    perform private.lock_goods_transaction_actor(p_user_id);
    if existing.source_kind <> 'direct' then raise sqlstate 'PT409' using message = 'checkout_key_conflict'; end if;
    return (private.replay_goods_transaction_receipt(p_user_id,
      jsonb_build_object('kind', existing.source_kind, 'id', existing.source_id, 'revision', existing.source_revision),
      p_quote_id, p_checkout_key, p_payment_method) ->> 'orderId')::uuid;
  end if;
  if not p_allow_new then raise check_violation using message = 'transaction_new_payment_disabled'; end if;
  select * into quoted from private.goods_transaction_quotes where id = p_quote_id and actor_id = p_user_id;
  if not found or quoted.source ->> 'kind' <> 'direct' or quoted.source ->> 'id' <> p_user_id::text then
    raise sqlstate 'PT409' using message = 'transaction_quote_expired'; end if;
  return public.place_direct_goods_transaction(p_user_id, p_draft_id, quoted.address, p_quote_id, p_checkout_key, p_payment_method);
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_store_analytics_session(p_token_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare session private.store_analytics_sessions;
begin
 perform private.store_analytics_require_service();
 if p_token_hash is null or p_token_hash!~'^[0-9a-f]{64}$' then raise invalid_parameter_value using message='analytics_invalid_session';end if;
 select * into session from private.store_analytics_sessions where token_hash=p_token_hash for update;
 if not found then return;end if;
 -- Delete the entire observed session, including its last target and token hash.
 -- Missing tokens are rejected exactly like revoked tokens; no tombstone is needed.
 delete from private.store_analytics_rate_buckets where scope='session:'||session.id::text;
 delete from private.store_analytics_sessions where id=session.id;
end $function$

CREATE OR REPLACE FUNCTION public.roll_rarity(p_pool_id uuid)
 RETURNS public.rarity
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_r numeric := random(); v_acc numeric := 0; v_total numeric; rec record;
begin
  select coalesce(sum(probability), 0) into v_total
    from pool_odds where pool_id = p_pool_id;
  if v_total <> 1 then raise exception 'pool odds must sum to 1'; end if;

  for rec in select rarity, probability from pool_odds where pool_id = p_pool_id order by rarity loop
    v_acc := v_acc + rec.probability;
    if v_r < v_acc then return rec.rarity; end if;
  end loop;
  raise exception 'failed to roll rarity';
end; $function$

CREATE OR REPLACE FUNCTION public.save_my_address_book_entry(p_entry_id uuid, p_label text, p_address jsonb, p_make_default boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid;
  clean_label text := btrim(coalesce(p_label, ''));
  normalized jsonb;
  target public.address_book_entries;
  entry_count integer;
  becomes_default boolean;
  saved_id uuid;
begin
  actor := private.address_book_actor(true);

  if char_length(clean_label) not between 1 and 20 or clean_label ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message = 'address_book_invalid';
  end if;
  if p_address is null or jsonb_typeof(p_address) <> 'object' or p_address ? 'deliveryNote' then
    raise invalid_parameter_value using message = 'address_book_invalid';
  end if;
  begin
    normalized := private.normalize_order_address_change(p_address);
  exception when invalid_parameter_value then
    raise invalid_parameter_value using message = 'address_book_invalid';
  end;

  if p_entry_id is null then
    select count(*) into entry_count
    from public.address_book_entries
    where user_id = actor;

    if entry_count >= 10 then
      raise check_violation using message = 'address_book_full';
    end if;

    becomes_default := coalesce(p_make_default, false) or entry_count = 0;
    if becomes_default then
      -- 기본 해제는 회원의 수정이 아니다 — updated_at 을 그대로 둔다.
      update public.address_book_entries
      set is_default = false
      where user_id = actor and is_default;
    end if;

    insert into public.address_book_entries (
      user_id, label, recipient_name, phone, postal_code, address1, address2, is_default
    )
    values (
      actor,
      clean_label,
      normalized->>'recipientName',
      normalized->>'phone',
      normalized->>'postalCode',
      normalized->>'address1',
      nullif(normalized->>'address2', ''),
      becomes_default
    )
    returning id into saved_id;

    return saved_id;
  end if;

  select * into target
  from public.address_book_entries
  where id = p_entry_id and user_id = actor
  for update;

  if not found then
    raise no_data_found using message = 'address_book_entry_missing';
  end if;

  becomes_default := target.is_default or coalesce(p_make_default, false);
  if becomes_default and not target.is_default then
    update public.address_book_entries
    set is_default = false
    where user_id = actor and is_default;
  end if;

  update public.address_book_entries
  set label = clean_label,
      recipient_name = normalized->>'recipientName',
      phone = normalized->>'phone',
      postal_code = normalized->>'postalCode',
      address1 = normalized->>'address1',
      address2 = nullif(normalized->>'address2', ''),
      is_default = becomes_default,
      updated_at = clock_timestamp()
  where id = target.id;

  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_begin_gift_claim_session(p_token_hash text, p_session_hash text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare token private.gift_link_tokens;gift private.gift_intents;ends timestamptz;begin
 if p_token_hash is null or p_token_hash!~'^[a-f0-9]{64}$' or p_session_hash is null or p_session_hash!~'^[a-f0-9]{64}$' then return null;end if;
 select * into token from private.gift_link_tokens where token_hash=p_token_hash;
 if not found then return null;end if;
 gift:=private.gift_lock(token.gift_id);select * into token from private.gift_link_tokens where token_hash=p_token_hash for update;
 if gift.state<>'awaiting_acceptance' or token.revoked_at is not null or token.consumed_at is not null or token.expires_at<=clock_timestamp() then return null;end if;
 delete from private.gift_claim_sessions where token_hash=p_token_hash and expires_at<=clock_timestamp();
 if (select count(*) from private.gift_claim_sessions where token_hash=p_token_hash)>=5 then return null;end if;
 ends:=least(token.expires_at,clock_timestamp()+interval '10 minutes');
 insert into private.gift_claim_sessions(session_hash,token_hash,expires_at) values(p_session_hash,p_token_hash,ends);return ends;
end $function$

CREATE OR REPLACE FUNCTION public.service_begin_goods_media_verification(p_actor_id uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claimed private.goods_media_assets%rowtype;
begin
 perform private.require_actor_operator_capability(p_actor_id,'catalog.manage');
 perform pg_advisory_xact_lock(hashtextextended('goods-media-actor:'||p_actor_id::text,0));
 select * into claimed from private.goods_media_assets where id=p_id and actor_id=p_actor_id for update;
 if not found or claimed.expires_at<=clock_timestamp() or claimed.status not in('pending','processing','verified','attached') then return null;end if;
 if claimed.status in('verified','attached') then
  return jsonb_build_object('id',claimed.id,'path',claimed.path,'kind',claimed.kind,'sourceSize',claimed.source_size,'status',claimed.status,'metadata',claimed.metadata);
 end if;
 if claimed.status='processing' or exists(select 1 from private.goods_media_assets where actor_id=p_actor_id and status='processing' and expires_at>clock_timestamp()) then
  return jsonb_build_object('status','processing','id',claimed.id);
 end if;
 update private.goods_media_assets set status='processing',processing_started_at=clock_timestamp(),expires_at=clock_timestamp()+interval '15 minutes' where id=claimed.id;
 return jsonb_build_object('id',claimed.id,'path',claimed.path,'kind',claimed.kind,'sourceSize',claimed.source_size,'status','claimed');
end $function$

CREATE OR REPLACE FUNCTION public.service_begin_goods_provider_cancellation_check(p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare attempt public.payment_attempts; ledger_key text; claimed uuid;
begin
  if p_attempt_id is null then raise invalid_parameter_value using message = 'invalid_provider_cancellation'; end if;
  select a.* into attempt from public.payment_attempts a
  where a.id = p_attempt_id and a.provider = 'toss' and a.purpose = 'order' and a.state = 'approved' and a.ref_id is not null;
  if not found then return null; end if;
  select p.payment_key into ledger_key from public.payments p join public.orders o on o.id = p.ref_id
  where p.id = attempt.payment_id and p.purpose = 'order' and p.ref_id = attempt.ref_id and p.status = 'paid' and p.payment_key is not null
    and o.status <> 'canceled';
  if not found then return null; end if;
  insert into private.goods_provider_cancellation_checks as checks(attempt_id, order_id, last_lookup_at)
  values (attempt.id, attempt.ref_id, clock_timestamp())
  on conflict (attempt_id) do update set last_lookup_at = excluded.last_lookup_at, updated_at = clock_timestamp()
    where checks.last_lookup_at <= clock_timestamp() - interval '2 minutes'
  returning checks.attempt_id into claimed;
  if claimed is null then return jsonb_build_object('status', 'cooldown'); end if;
  return jsonb_build_object('status', 'proceed',
    'attempt', jsonb_build_object('id', attempt.id, 'provider', attempt.provider, 'purpose', attempt.purpose, 'ref_id', attempt.ref_id,
      'amount', attempt.amount, 'currency', attempt.currency, 'idempotency_key', attempt.idempotency_key, 'provider_order_id', attempt.provider_order_id,
      'provider_product_code', attempt.provider_product_code, 'expires_at', attempt.expires_at),
    'paymentKey', ledger_key);
end $function$

CREATE OR REPLACE FUNCTION public.service_change_order_claim_contact(p_order_id uuid, p_claim_id uuid, p_actor_id uuid, p_session_id uuid, p_operation_id uuid, p_target text, p_expected_claim_type text, p_expected_claim_revision integer, p_expected_context jsonb, p_sealed_change jsonb, p_request_hmac text, p_hmac_key_version text, p_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parties uuid[]:=private.contact_parties(p_order_id);op private.order_claim_contact_operations;c public.order_cancellation_requests;view jsonb;plan jsonb;hist jsonb;fields text[];result_revision integer;old_plan private.order_claim_contact_plans;begin
 perform private.contact_operation_input(p_operation_id,'change',p_target,p_expected_claim_type,p_expected_claim_revision);
 perform private.contact_require_identity(p_actor_id,p_session_id,'sales.manage',false,parties,false);
 perform pg_advisory_xact_lock(hashtextextended('claim-contact-operation:'||p_operation_id,0));
 c:=private.contact_lock_scope(p_order_id,p_claim_id,parties);
 select id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,result_claim_revision,
 state,changed_fields,request_hmac,hmac_key_version,null::jsonb,created_at,purged_at into op
 from private.order_claim_contact_operations where id=p_operation_id;
 if found then
  perform private.contact_operation_scope(op,p_order_id,p_claim_id,p_actor_id,p_session_id,'change',p_target,p_expected_claim_type,p_expected_claim_revision);
  if op.state='sealed' then raise sqlstate 'PT409' using message='claim_contact_operation_sealed';end if;
  if op.purged_at is not null then raise sqlstate 'PT410' using message='claim_contact_purged';end if;
  if op.request_hmac is distinct from p_request_hmac or op.hmac_key_version is distinct from p_hmac_key_version then raise unique_violation using message='claim_contact_operation_conflict';end if;
  return private.contact_operation_receipt(op);
 end if;
 if exists(select 1 from private.account_action_fences where subject_user_id=any(parties)) then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
 if p_confirmed is distinct from true or not private.contact_digest(to_jsonb(p_request_hmac)) or not private.contact_key_version(to_jsonb(p_hmac_key_version))
 or not private.contact_keys(p_sealed_change- 'destinationCheck',array['effect','changedFields','beforeAddressHmac','afterAddressHmac','addressHmacKeyVersion','plan','history'])
 or not private.contact_digest(p_sealed_change->'beforeAddressHmac') or not private.contact_digest(p_sealed_change->'afterAddressHmac')
 or not private.contact_key_version(p_sealed_change->'addressHmacKeyVersion') or jsonb_typeof(p_sealed_change->'changedFields') is distinct from 'array'
 or jsonb_typeof(p_sealed_change->'effect') is distinct from 'string' or p_sealed_change->>'effect' not in('change','noop') then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 fields:=array(select jsonb_array_elements_text(p_sealed_change->'changedFields'));
 if cardinality(fields)>5 or fields is distinct from array(select f from unnest(array['recipientName','phone','address2','postalCode','address1']) f where f=any(fields)) then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 view:=private.contact_assert_context(c,p_target,'change',p_expected_claim_type,p_expected_claim_revision,p_expected_context);
 if fields && array['postalCode','address1'] then
  if not private.contact_keys(p_sealed_change->'destinationCheck',array['before','after']) then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
  perform private.assert_claim_destination_same_price(p_order_id,p_sealed_change#>'{destinationCheck,before}',p_sealed_change#>'{destinationCheck,after}');
 elsif p_sealed_change ? 'destinationCheck' then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;

 if p_sealed_change->>'effect'='noop' then
  if fields<>'{}' or p_sealed_change->'plan' is distinct from 'null'::jsonb or p_sealed_change->'history' is distinct from 'null'::jsonb or p_sealed_change->'beforeAddressHmac' is distinct from p_sealed_change->'afterAddressHmac' then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
  result_revision:=c.claim_revision;
 else
  plan:=p_sealed_change->'plan';hist:=p_sealed_change->'history';
  if cardinality(fields)=0 or not private.contact_plan_envelope(plan) or not private.contact_history_envelope(hist)
   or plan->'addressHmac' is distinct from p_sealed_change->'afterAddressHmac' or plan->'addressHmacKeyVersion' is distinct from p_sealed_change->'addressHmacKeyVersion'
   or plan->'keyVersion' is distinct from hist->'keyVersion'
   or p_sealed_change->'beforeAddressHmac'=p_sealed_change->'afterAddressHmac' then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
  select * into old_plan from private.order_claim_contact_plans where claim_id=p_claim_id and target=p_target;
  if (old_plan.id is not null and(old_plan.id is distinct from(plan->>'planId')::uuid or old_plan.pii_version=(plan->>'piiVersion')::uuid))
   or exists(select 1 from private.order_claim_contact_operations where claim_id=p_claim_id and target=p_target and history->>'piiVersion'=plan->>'piiVersion') then raise sqlstate 'PT409' using message='claim_contact_changed';end if;
  insert into private.order_claim_contact_plans(id,order_id,claim_id,target,revision,pii_version,sealed_plan,source_kind,source_id,source_revision,last_operation_id)
  values((plan->>'planId')::uuid,p_order_id,p_claim_id,p_target,1,(plan->>'piiVersion')::uuid,plan,coalesce(old_plan.source_kind,view#>>'{source,sourceKind}'),coalesce(old_plan.source_id,(view#>>'{source,sourceId}')::uuid),case when old_plan.id is not null then old_plan.source_revision else view#>>'{source,sourceRevision}' end,p_operation_id)
  on conflict(claim_id,target) do update set revision=private.order_claim_contact_plans.revision+1,pii_version=excluded.pii_version,sealed_plan=excluded.sealed_plan,last_operation_id=p_operation_id,updated_at=clock_timestamp();
  update public.order_cancellation_requests set updated_at=clock_timestamp() where id=p_claim_id returning claim_revision into result_revision;
  insert into public.audit_log(actor_id,action,target,diff) values(p_actor_id,'admin.order.claim_contact_changed','order:'||p_order_id,
   jsonb_build_object('claimId',p_claim_id,'operationId',p_operation_id,'target',p_target,'changedFields',to_jsonb(fields),'claimRevision',result_revision));
  perform private.notify_order_claim(p_claim_id,'claim_updated','클레임 연락처가 변경됐어요','고객과 확인한 연락처 정보로 변경했습니다.');
 end if;
 insert into private.order_claim_contact_operations(id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,result_claim_revision,state,changed_fields,request_hmac,hmac_key_version,history)
 values(p_operation_id,p_actor_id,p_session_id,p_order_id,p_claim_id,'change',p_target,p_expected_claim_type,p_expected_claim_revision,result_revision,
 case when p_sealed_change->>'effect'='noop' then 'noop' else 'saved' end,fields,p_request_hmac,p_hmac_key_version,hist) returning * into op;
 return private.contact_operation_receipt(op);
end $function$

CREATE OR REPLACE FUNCTION public.service_claim_billing_credential_revocation(p_actor_id uuid, p_credential_id uuid, p_claim_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare credential private.billing_credentials;begin
 perform private.subscription_require_service();perform private.subscription_lock_actor(p_actor_id,false);
 if p_claim_token is null then raise invalid_parameter_value using message='invalid_billing_claim';end if;
 select * into credential from private.billing_credentials where id=p_credential_id and owner_id=p_actor_id for update;
 if not found or credential.state<>'revoking' or credential.revoke_claim_token is not null and credential.revoke_lease_until>clock_timestamp() then return null;end if;
 if exists(select 1 from private.goods_subscription_plans where credential_id=p_credential_id and state in('active','awaiting_first_payment','paused','needs_confirmation'))
  or exists(select 1 from private.goods_subscription_cycles c join private.payment_provider_bindings b on b.cycle_id=c.id
   where b.credential_id=p_credential_id and c.state in('dispatching','unknown','needs_review')) then return null;end if;
 update private.billing_credentials set revoke_claim_token=p_claim_token,revoke_lease_until=clock_timestamp()+interval '10 minutes',revoke_fence=revoke_fence+1
  where id=p_credential_id returning * into credential;
 return jsonb_build_object('id',credential.id,'ownerId',credential.owner_id,'claimToken',credential.revoke_claim_token,'claimFence',credential.revoke_fence,
  'expiresAt',credential.revoke_lease_until,'envelope',credential.envelope,'profile',(select jsonb_build_object('profileId',p.id,'merchantId',p.merchant_id,'environment',p.environment)
   from private.billing_profiles p where p.id=credential.profile_id));
end $function$

CREATE OR REPLACE FUNCTION public.service_claim_billing_registration(p_actor_id uuid, p_session_id uuid, p_id uuid, p_nonce_digest text, p_auth_envelope jsonb, p_auth_fingerprint text, p_claim_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare entry private.billing_enrollments;at_time timestamptz;begin
 perform private.subscription_require_service();perform private.subscription_lock_actor(p_actor_id,false);
 if p_session_id is null or p_claim_token is null or not exists(select 1 from auth.sessions where id=p_session_id and user_id=p_actor_id)
  or not private.subscription_valid_envelope(p_auth_envelope) or p_auth_fingerprint is null or p_auth_fingerprint!~'^[0-9a-f]{64}$' then
  raise invalid_parameter_value using message='invalid_billing_registration';end if;
 select * into entry from private.billing_enrollments where id=p_id and owner_id=p_actor_id and session_id=p_session_id for update;
 if not found or entry.nonce_digest is distinct from p_nonce_digest then raise insufficient_privilege using message='billing_registration_forbidden';end if;
 if entry.state in('ready','declined','expired') then return private.billing_registration_summary(p_id,true)||jsonb_build_object('kind','terminal');end if;
 at_time:=clock_timestamp();
 if entry.first_dispatched_at is null then
  perform private.subscription_lock_actor(p_actor_id,true);
  if entry.expires_at<=at_time or not(select public_enabled from private.goods_subscription_runtime where singleton) then
   update private.billing_enrollments set state='expired',updated_at=at_time where id=p_id;
   return private.billing_registration_summary(p_id,true)||jsonb_build_object('kind','terminal');end if;
 else
  if entry.auth_fingerprint is distinct from p_auth_fingerprint then raise invalid_parameter_value using message='billing_registration_conflict';end if;
  if entry.recovery_until<=at_time then return private.billing_registration_summary(p_id,true)||jsonb_build_object('kind','expired_recovery');end if;
 end if;
 if entry.claim_token is not null and entry.lease_until>at_time then return private.billing_registration_summary(p_id,false)||jsonb_build_object('kind','busy');end if;
 update private.billing_enrollments set state='processing',claim_token=p_claim_token,claim_fence=claim_fence+1,
  lease_until=at_time+interval '10 minutes',first_dispatched_at=coalesce(first_dispatched_at,at_time),
  recovery_until=coalesce(recovery_until,at_time+interval '24 hours'),auth_envelope=coalesce(auth_envelope,p_auth_envelope),
  auth_fingerprint=coalesce(auth_fingerprint,p_auth_fingerprint),updated_at=at_time where id=p_id;
 return private.billing_registration_summary(p_id,true)||jsonb_build_object('kind','claimed');
end $function$

CREATE OR REPLACE FUNCTION public.service_claim_goods_media_cleanup(p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare candidate private.goods_media_assets%rowtype;result jsonb:='[]';mode text;
begin
 for candidate in select a.* from private.goods_media_assets a where (
   (a.status in('verified','attached','retired') and a.staging_cleaned_at is null)
   or (a.status in('pending','processing','verified','rejected','retired') and a.expires_at<=clock_timestamp())
   or (a.status='cleanup' and a.cleanup_claimed_at<clock_timestamp()-interval '10 minutes')
   -- Storage can finish after a worker's lease and even after its profile was
   -- deleted. The immutable path is sufficient evidence for service cleanup.
   or (a.status='cleaned' and exists(select 1 from storage.objects o where o.bucket_id in('goods-video-staging','goods-videos') and o.name=a.path))
  ) order by a.created_at,a.id for update skip locked limit greatest(1,least(coalesce(p_limit,20),50)) loop
  mode:=case when candidate.status in('verified','attached','retired') and candidate.staging_cleaned_at is null then 'staging' else 'all' end;
  if mode='all' and exists(select 1 from private.goods_media_bindings b where b.video_asset_id=candidate.id or b.shortclip_asset_id=candidate.id) then continue;end if;
  if mode='all' then update private.goods_media_assets set status='cleanup',cleanup_claimed_at=clock_timestamp() where id=candidate.id;end if;
  result:=result||jsonb_build_array(jsonb_build_object('id',candidate.id,'path',candidate.path,'mode',mode));
 end loop;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.service_claim_goods_subscription_work(p_claim_token uuid, p_cycle_id uuid DEFAULT NULL::uuid, p_manual_review boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare cycle private.goods_subscription_cycles;begin
 perform private.subscription_require_service();
 if p_claim_token is null or p_manual_review is null or p_manual_review and p_cycle_id is null then raise invalid_parameter_value using message='invalid_subscription_claim';end if;
 select c.* into cycle from private.goods_subscription_cycles c where (p_cycle_id is null or c.id=p_cycle_id)
  and (c.claim_token is null or c.lease_until<=clock_timestamp()) and (
   (not p_manual_review and c.dispatched_at is null and c.state in('ready','prepared') and c.scheduled_at<=clock_timestamp()
    and (select worker_enabled and charge_enabled from private.goods_subscription_runtime where singleton))
   or (c.dispatched_at is not null and (c.state in('dispatching','unknown') or p_manual_review and c.state='needs_review')
    and (p_manual_review or coalesce(c.next_check_at,c.scheduled_at)<=clock_timestamp())))
 order by coalesce(c.next_check_at,c.scheduled_at),c.id for update skip locked limit 1;
 if not found then return null;end if;
 update private.goods_subscription_cycles set claim_token=p_claim_token,lease_until=clock_timestamp()+interval '10 minutes',claim_fence=claim_fence+1,
  updated_at=clock_timestamp() where id=cycle.id returning * into cycle;
 return jsonb_build_object('cycleId',cycle.id,'actorId',cycle.owner_id,'termsId',cycle.terms_id,'token',cycle.claim_token,'fence',cycle.claim_fence,'expiresAt',cycle.lease_until,'profile',(select jsonb_build_object('profileId',p.id,'merchantId',p.merchant_id,'environment',p.environment)
  from private.billing_profiles p where p.id=coalesce((select b.profile_id from private.payment_provider_bindings b where b.cycle_id=cycle.id),
   (select c.profile_id from private.billing_credentials c join private.goods_subscription_plans g on g.credential_id=c.id where g.id=cycle.plan_id))));
end $function$

CREATE OR REPLACE FUNCTION public.service_claim_pg_settlement_import(p_actor_id uuid, p_import_id uuid, p_scope_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job private.pg_settlement_imports;token uuid:=extensions.gen_random_uuid();
begin
 perform private.pg_settlement_require_actor(p_actor_id);
 select * into job from private.pg_settlement_imports where id=p_import_id for update;
 if not found or job.actor_id<>p_actor_id then raise insufficient_privilege using message='settlement_import_unavailable';end if;
 if job.state in('complete','failed') then return jsonb_build_object('kind',job.state,'job',private.pg_settlement_job(job.id));end if;
 if job.scope_hash is distinct from p_scope_hash then
  update private.pg_settlement_imports set state='failed',error_code='scope_changed',claim_id=null,lease_until=null,updated_at=clock_timestamp() where id=job.id;
  return jsonb_build_object('kind','failed','job',private.pg_settlement_job(job.id));end if;
 if job.lease_until>clock_timestamp() then return jsonb_build_object('kind','busy','job',private.pg_settlement_job(job.id));end if;
 update private.pg_settlement_imports set claim_id=token,lease_until=clock_timestamp()+interval '120 seconds',error_code=null,updated_at=clock_timestamp() where id=job.id;
 return jsonb_build_object('kind','ready','job',private.pg_settlement_job(job.id),'claimId',token,'scan',job.scan,'page',job.next_page,
  'query',jsonb_build_object('dateType',job.date_type,'startDate',job.start_date,'endDate',job.end_date));
end $function$

CREATE OR REPLACE FUNCTION public.service_cleanup_fenced_gift(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare gift private.gift_intents;begin
 begin gift:=private.gift_lock(p_id);exception when no_data_found then return jsonb_build_object('giftId',p_id,'state','missing');end;
 if gift.id is null then return jsonb_build_object('giftId',p_id,'state','missing');end if;
 if gift.order_id is not null then return jsonb_build_object('giftId',p_id,'state','ordered');end if;
 if not exists(select 1 from private.account_action_fences where subject_user_id in(gift.sender_id,gift.recipient_id)) then return jsonb_build_object('giftId',p_id,'state','not_fenced');end if;
 if gift.state in('awaiting_acceptance','accepted') then update private.gift_intents set state='canceled',closed_at=clock_timestamp(),updated_at=clock_timestamp(),revision=revision+1 where id=gift.id;end if;
 update private.gift_link_tokens set revoked_at=coalesce(revoked_at,clock_timestamp()) where gift_id=gift.id;
 delete from private.gift_claim_sessions where token_hash in(select token_hash from private.gift_link_tokens where gift_id=gift.id);
 delete from private.goods_transaction_quotes where actor_id=gift.sender_id and source->>'kind'='gift' and source->>'id'=gift.id::text and order_id is null;
 delete from private.gift_recipient_addresses where gift_id=gift.id;
 return jsonb_build_object('giftId',p_id,'state','cleaned');
end $function$

CREATE OR REPLACE FUNCTION public.service_cleanup_fenced_goods_transactions(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare event_id uuid;blocked jsonb;removed integer;begin
 if p_actor is null then raise invalid_parameter_value using message='invalid_account_cleanup';end if;
 perform private.subscription_lock_actor(p_actor,false);
 select deletion_event_id into event_id from private.account_deletion_requests where subject_user_id=p_actor for update;
 if not found or not private.is_account_write_fenced(p_actor) then return jsonb_build_object('state','not_fenced');end if;
 perform private.snapshot_goods_subscription_contracts(event_id,p_actor);
 delete from private.goods_transaction_quotes where actor_id=p_actor;
 get diagnostics removed=row_count;
 blocked:=private.goods_subscription_account_blockers(p_actor);
 if blocked='[]'::jsonb then perform private.purge_goods_subscription_account_data(p_actor);end if;
 return jsonb_build_object('state',case when blocked='[]'::jsonb then 'cleaned' else 'deferred' end,'quotesRemoved',removed);
end $function$

