CREATE OR REPLACE FUNCTION public.service_complete_member_onboarding(p_user_id uuid, p_require_phone boolean)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_at timestamptz;
  completed_at timestamptz;
begin
  if p_user_id is null or p_require_phone is null then
    raise invalid_parameter_value using message = 'onboarding_completion_invalid';
  end if;

  select p.onboarded_at into current_at from public.profiles p where p.id = p_user_id for update;
  if not found then
    raise no_data_found using message = 'onboarding_profile_missing';
  end if;
  -- 이미 마친 계정은 완료 시각을 바꾸지 않는다(번호를 옮겨 가 다시 인증한 회원 포함).
  if current_at is not null then
    return current_at;
  end if;

  -- 약관·개인정보 동의와 만 14세 확인(1단계)을 마친 계정만 끝낼 수 있다.
  if not private.member_phone_onboarding_ready(p_user_id) then
    raise insufficient_privilege using message = 'onboarding_step_required';
  end if;
  if p_require_phone and not exists (
    select 1 from private.member_phone_numbers n where n.user_id = p_user_id and n.phone_e164 is not null
  ) then
    raise insufficient_privilege using message = 'onboarding_phone_required';
  end if;

  completed_at := pg_catalog.now();
  update public.profiles set onboarded_at = completed_at where id = p_user_id;
  return completed_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_complete_order_partial_cancellation(p_id uuid, p_refunded_amount bigint, p_provider_payment_key text, p_provider_transaction_key text, p_actor_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare head private.order_partial_cancellations; pay public.payments;
begin
  perform private.require_partial_cancellation_actor(p_actor_id);
  if p_refunded_amount is null or p_refunded_amount <= 0 or nullif(btrim(coalesce(p_provider_payment_key, '')), '') is null
    or p_provider_transaction_key is null or p_provider_transaction_key !~ '^[\x21-\x7e]{1,64}$' then
    raise invalid_parameter_value using message = 'partial_cancel_evidence_invalid';
  end if;
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  perform 1 from public.orders where id = head.order_id for update;
  perform s.id from public.order_shipments s where s.order_id = head.order_id order by s.id for update;
  select * into pay from public.payments where id = head.payment_id for update;
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if head.provider <> 'toss' or pay.provider <> 'toss' or pay.payment_key is distinct from p_provider_payment_key or p_refunded_amount <> head.refund_amount then
    raise check_violation using message = 'partial_cancel_evidence_mismatch';
  end if;
  if head.state = 'completed' then
    if head.provider_transaction_key is distinct from p_provider_transaction_key then raise check_violation using message = 'partial_cancel_evidence_mismatch'; end if;
    return 'completed';
  end if;
  if head.state not in ('processing', 'needs_review') then raise check_violation using message = 'partial_cancel_not_processing'; end if;
  update private.order_partial_cancellations set provider_confirmed_at = clock_timestamp(), provider_transaction_key = p_provider_transaction_key
  where id = p_id;
  perform private.apply_order_partial_cancellation(p_id, p_actor_id, 'completed');
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor_id, 'admin.order.partial_cancellation_completed', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'paymentId', pay.id, 'refundedAmount', p_refunded_amount,
      'balanceAfter', head.balance_before - p_refunded_amount));
  return 'completed';
end $function$

CREATE OR REPLACE FUNCTION public.service_complete_tracked_deliveries(p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare settings private.delivery_tracking_settings; candidates uuid[]; scopes jsonb := '{}'::jsonb; candidate uuid; scope uuid[];
  scope_ids uuid[] := '{}'::uuid[]; locked_orders uuid[] := '{}'::uuid[]; locked_shipments uuid[] := '{}'::uuid[]; locked record;
  processed uuid[] := '{}'::uuid[]; latest_at timestamptz; basis_value jsonb; member record; delivered_value timestamptz;
  completed jsonb := '[]'::jsonb; held jsonb := '[]'::jsonb; skipped integer := 0;
begin
  if p_limit is null or p_limit not between 1 and 200 then raise invalid_parameter_value using message = 'invalid_delivery_tracking_limit'; end if;
  select * into settings from private.delivery_tracking_settings where singleton;
  if not found or not settings.auto_delivery_enabled then
    return jsonb_build_object('enabled', false, 'completed', '[]'::jsonb, 'held', '[]'::jsonb, 'skipped', 0); end if;
  -- 잡은 뒤 트리거 등이 다른 잠금을 오래 기다리지 않게 한다(그 묶음은 다음 회차에).
  perform set_config('lock_timeout', '3s', true);
  -- 1) 후보는 잠그지 않고 발송 순으로 고른다.
  select coalesce(array_agg(c.id order by c.shipped_at, c.id), '{}'::uuid[]) into candidates from (
    select s.id, s.shipped_at from public.order_shipments s join public.orders o on o.id = s.order_id
    where s.status = 'shipping' and s.delivery_method = 'parcel' and s.tracking_number is not null and s.shipped_at is not null
      and o.status in ('confirmed','shipping','delivered')
      and not exists(select 1 from private.shipment_auto_deliveries a where a.shipment_id = s.id and a.state = 'held' and a.updated_at > now() - interval '6 hours')
      and private.shipment_trackings_delivered(s.id)
    order by s.shipped_at, s.id limit p_limit) c;
  -- 2) 후보마다 합포장 묶음(잠근 뒤 바뀌었는지 다시 본다).
  foreach candidate in array candidates loop
    scope := private.shipment_pack_scope(array[candidate]);
    scopes := scopes || jsonb_build_object(candidate::text, to_jsonb(scope));
    scope_ids := scope_ids || scope;
  end loop;
  -- 3) 전역 순서(주문 id → 배송 건 id)로, 기다리지 않고 잡을 수 있는 것만 잡는다.
  for locked in select o.id from public.orders o
    where o.id in (select s.order_id from public.order_shipments s where s.id = any(scope_ids)) order by o.id for update skip locked loop
    locked_orders := locked_orders || locked.id;
  end loop;
  for locked in select s.id from public.order_shipments s where s.id = any(scope_ids) and s.order_id = any(locked_orders)
    order by s.id for update skip locked loop
    locked_shipments := locked_shipments || locked.id;
  end loop;
  -- 4) 묶음별로 다시 보고 바꾼다.
  foreach candidate in array candidates loop
    if candidate = any(processed) then continue; end if;
    scope := array(select value::uuid from jsonb_array_elements_text(scopes->(candidate::text)) value);
    processed := processed || scope;
    if not (scope <@ locked_shipments) then skipped := skipped + 1; continue; end if;
    begin
      -- 잡은 뒤 다시 본다. 묶음이 바뀌었거나, 묶음의 다른 배송 건이 아직이거나, 상태가 바뀌었으면 이번에는 넘긴다(보류 아님).
      if private.shipment_pack_scope(array[candidate]) is distinct from scope
        or exists(select 1 from public.order_shipments s join public.orders o on o.id = s.order_id where s.id = any(scope)
          and (s.status <> 'shipping' or s.delivery_method <> 'parcel' or s.tracking_number is null or s.shipped_at is null
            or o.status not in ('confirmed','shipping','delivered')))
        or exists(select 1 from unnest(scope) member_id where not private.shipment_trackings_delivered(member_id)) then
        skipped := skipped + 1; continue;
      end if;
      select max(e.occurred_at), jsonb_agg(jsonb_build_object('shipmentId', t.shipment_id, 'carrier', t.carrier, 'trackingNumber', t.tracking_number,
          'eventId', e.id, 'provider', e.provider, 'occurredAt', e.occurred_at, 'since', t.since) order by t.shipment_id, t.carrier, t.tracking_number)
        into latest_at, basis_value
      from (select member_id shipment_id, tracking.carrier, tracking.tracking_number, tracking.since from unnest(scope) member_id
        cross join lateral private.shipment_current_trackings(member_id) tracking) t
      cross join lateral private.tracking_latest_event(t.carrier, t.tracking_number, t.since) e;
      for member in select s.* from public.order_shipments s where s.id = any(scope) order by s.id loop
        -- 가장 늦은 도착 시각(모든 근거가 기준 시각 = 출고지시·발주확인 이후다. 회신 등록이 늦어도 배송완료 시각은 등록 시각 밑으로 내리지 않는다). 추적 시계가 앞서도 지금을 넘지 않는다(청약철회·자동 구매확정 기산).
        delivered_value := least(greatest(latest_at, member.shipped_at), clock_timestamp());
        update public.order_shipments set status = 'delivered', delivered_at = delivered_value, updated_at = clock_timestamp() where id = member.id;
        insert into private.shipment_auto_deliveries(shipment_id, state, delivered_at, provider, basis, attempts, last_error, updated_at)
        values (member.id, 'completed', delivered_value, settings.provider, coalesce((select jsonb_agg(entry) from jsonb_array_elements(basis_value) entry
          where entry->>'shipmentId' = member.id::text), '[]'::jsonb), 1, null, now())
        on conflict (shipment_id) do update set state = 'completed', delivered_at = excluded.delivered_at, provider = excluded.provider,
          basis = excluded.basis, attempts = private.shipment_auto_deliveries.attempts + 1, last_error = null, updated_at = now();
        insert into public.audit_log(actor_id, action, target, diff) values (null, 'system.shipment.tracking_delivered', 'order:' || member.order_id,
          jsonb_build_object('shipmentId', member.id, 'originName', member.origin_name_snapshot, 'from', 'shipping', 'to', 'delivered',
            'deliveredAt', delivered_value, 'provider', settings.provider, 'carrier', member.carrier, 'trackingNumber', member.tracking_number,
            'trackings', (select jsonb_agg(entry - 'shipmentId') from jsonb_array_elements(basis_value) entry where entry->>'shipmentId' = member.id::text)));
        completed := completed || jsonb_build_array(jsonb_build_object('shipmentId', member.id, 'orderId', member.order_id, 'deliveredAt', delivered_value));
      end loop;
    exception when lock_not_available or deadlock_detected then
      -- 트리거가 다른 잠금을 기다리다 넘은 건은 보류로 남기지 않는다(다음 회차에 그대로 다시 본다).
      skipped := skipped + 1;
    when others then
      -- 바꾸지 못한 이유(취소·반품 진행, 묶음 변경 등)를 남기고 6시간 뒤 다시 본다. 운영자는 배송현황에서 수동으로 처리할 수 있다.
      insert into private.shipment_auto_deliveries(shipment_id, state, attempts, last_error, updated_at)
      values (candidate, 'held', 1, left(sqlerrm, 200), now())
      on conflict (shipment_id) do update set state = 'held', attempts = private.shipment_auto_deliveries.attempts + 1,
        last_error = excluded.last_error, updated_at = now()
      where private.shipment_auto_deliveries.state <> 'completed';
      held := held || jsonb_build_array(jsonb_build_object('shipmentId', candidate, 'error', left(sqlerrm, 200)));
    end;
  end loop;
  return jsonb_build_object('enabled', true, 'completed', completed, 'held', held, 'skipped', skipped);
end $function$

CREATE OR REPLACE FUNCTION public.service_create_checkout_direct_draft(p_user_id uuid, p_base_good_id text, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  item record;
  v_variant uuid;
  v_key text;
  v_seen text[] := '{}';
  v_snapshot jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_draft uuid;
begin
  if p_user_id is null or nullif(btrim(p_base_good_id), '') is null
    or jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) not between 1 and 51
    or exists (
      select 1 from jsonb_array_elements(p_lines) as line
      where jsonb_typeof(line) <> 'object' or not line ?& array['good_id', 'variant_id', 'qty']
        or exists (select 1 from jsonb_object_keys(line) as key where key not in ('good_id', 'variant_id', 'qty', 'input_revision', 'input_values'))
        or jsonb_typeof(line -> 'good_id') <> 'string' or nullif(btrim(line ->> 'good_id'), '') is null
        or jsonb_typeof(line -> 'variant_id') <> 'string'
        or line ->> 'variant_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(line -> 'qty') <> 'number' or line ->> 'qty' !~ '^[1-9][0-9]{0,8}$'
        or (line ? 'input_revision' and (jsonb_typeof(line -> 'input_revision') <> 'number' or line ->> 'input_revision' !~ '^(0|[1-9][0-9]*)$'))
        or (line ? 'input_values' and jsonb_typeof(line -> 'input_values') <> 'object')
    )
    or not exists (select 1 from jsonb_array_elements(p_lines) as line where line ->> 'good_id' = p_base_good_id)
  then
    raise invalid_parameter_value using message = 'invalid_checkout_direct';
  end if;
  perform private.assert_active_user(p_user_id);
  for item in
    select line ->> 'good_id' as good_id, (line ->> 'variant_id')::uuid as variant_id, (line ->> 'qty')::integer as qty,
      coalesce((line ->> 'input_revision')::integer, 0) as input_revision, coalesce(line -> 'input_values', '{}'::jsonb) as input_values,
      position
    from jsonb_array_elements(p_lines) with ordinality as entries(line, position)
    order by position
  loop
    -- 랜덤 판매 굿즈(D5②)는 장바구니 키(기본 옵션)로 모은다. 배정은 주문 생성이 한다.
    v_variant := private.cart_variant_key(item.good_id, item.variant_id);
    v_key := v_variant::text || ':' || case when item.input_revision = 0 and item.input_values = '{}'::jsonb then ''
      else md5(item.input_revision::text || ':' || item.input_values::text) end;
    if v_key = any (v_seen) then
      raise invalid_parameter_value using message = 'invalid_checkout_direct';
    end if;
    v_seen := array_append(v_seen, v_key);
    -- 담기(add_cart_selection)와 같은 규칙: 본품은 판매 중(19금은 인증 성인만), 추가 구성은 연결된 일반 굿즈만.
    if item.good_id = p_base_good_id then
      if not private.goods_selection_base_available(item.good_id, p_user_id) then
        if exists (select 1 from public.goods as good where good.id = item.good_id and good.sale_restriction = 'adult')
          and not private.adult_verification_valid(p_user_id) then
          raise check_violation using message = 'adult_verification_required';
        end if;
        raise check_violation using message = 'catalog_item_unavailable';
      end if;
    elsif not exists (select 1 from private.goods_additional_links as link where link.base_good_id = p_base_good_id and link.target_good_id = item.good_id)
      or not private.goods_additional_available(item.good_id) then
      raise check_violation using message = 'additional_good_unavailable';
    end if;
    if not exists (
      select 1 from public.goods_variants as variant
      where variant.id = v_variant and variant.good_id = item.good_id and variant.archived_at is null
    ) then
      raise check_violation using message = 'catalog_item_unavailable';
    end if;
    v_snapshot := private.resolve_goods_custom_inputs(item.good_id, item.input_revision, item.input_values);
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('goodId', item.good_id, 'variantId', v_variant, 'qty', item.qty,
      'inputRevision', item.input_revision, 'inputValues', item.input_values, 'inputSnapshot', v_snapshot));
  end loop;
  perform private.trim_checkout_drafts(p_user_id);
  insert into private.checkout_drafts (user_id, source, base_good_id, lines, expires_at)
  values (p_user_id, 'direct', p_base_good_id, v_lines, pg_catalog.clock_timestamp() + private.checkout_draft_ttl())
  returning id into v_draft;
  return v_draft;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_create_checkout_retry_draft(p_user_id uuid, p_order_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hold private.cart_order_holds%rowtype;
  v_lines jsonb;
  v_draft uuid;
  v_existing private.checkout_drafts%rowtype;
begin
  if p_user_id is null or p_order_id is null then
    raise invalid_parameter_value using message = 'invalid_checkout_retry';
  end if;
  perform private.assert_active_user(p_user_id);
  select hold.* into v_hold from private.cart_order_holds as hold
  where hold.order_id = p_order_id and hold.user_id = p_user_id
    and hold.source in ('legacy_checkout', 'cart_transaction')
    and (hold.state = 'awaiting_payment' or (hold.state = 'released' and hold.release_reason <> 'detached'));
  if not found then
    return null;
  end if;
  select jsonb_agg(jsonb_build_object('cartItemId', cart.id, 'goodId', cart.good_id, 'variantId', cart.variant_id,
      'qty', cart.qty, 'inputRevision', cart.input_revision, 'inputValues', cart.input_values, 'inputSnapshot', cart.input_snapshot)
      order by cart.good_id, cart.variant_id, cart.input_key)
    into v_lines
  from public.cart_items as cart
  where cart.user_id = p_user_id
    and exists (select 1 from jsonb_array_elements(v_hold.lines) as line
      where (line ->> 'variantId')::uuid = cart.variant_id and line ->> 'inputKey' = cart.input_key);
  if v_lines is null then
    return null;
  end if;
  perform private.trim_checkout_drafts(p_user_id);
  -- 같은 주문의 다시 결제 초안은 하나다(T22i). 이미 그 초안으로 결제·접수·결제 확인 중 주문을 만들었으면 다시 만들지 않는다.
  select draft.* into v_existing from private.checkout_drafts as draft
  where draft.retry_order_id = p_order_id and draft.user_id = p_user_id
  for update;
  if found then
    if v_existing.order_id is not null
      and (private.checkout_draft_order_settled(v_existing.order_id) or private.checkout_draft_order_payment_unresolved(v_existing.order_id)) then
      return null;
    end if;
    update private.checkout_drafts set retry_order_id = null where id = v_existing.id;
  end if;
  insert into private.checkout_drafts (user_id, source, lines, expires_at, retry_order_id)
  values (p_user_id, 'selection', v_lines, pg_catalog.clock_timestamp() + private.checkout_draft_ttl(), p_order_id)
  returning id into v_draft;
  return v_draft;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_create_checkout_selection_draft(p_user_id uuid, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_lines jsonb;
  v_count integer;
  v_draft uuid;
begin
  if p_user_id is null or jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) not between 1 and 19239
    or exists (
      select 1 from jsonb_array_elements(p_lines) as entry
      where jsonb_typeof(entry) <> 'object' or not (entry ?& array['good_id', 'variant_id', 'qty', 'input_revision', 'input_values'])
        or exists (select 1 from jsonb_object_keys(entry) as key where key not in ('good_id', 'variant_id', 'qty', 'input_revision', 'input_values'))
        or jsonb_typeof(entry -> 'good_id') <> 'string' or nullif(btrim(entry ->> 'good_id'), '') is null
        or jsonb_typeof(entry -> 'variant_id') <> 'string'
        or entry ->> 'variant_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(entry -> 'qty') <> 'number' or entry ->> 'qty' !~ '^[1-9][0-9]*$'
        or jsonb_typeof(entry -> 'input_revision') <> 'number' or entry ->> 'input_revision' !~ '^(0|[1-9][0-9]*)$'
        or jsonb_typeof(entry -> 'input_values') <> 'object'
    )
  then
    raise invalid_parameter_value using message = 'invalid_checkout_selection';
  end if;
  perform private.assert_active_user(p_user_id);
  select coalesce(jsonb_agg(jsonb_build_object('cartItemId', cart.id, 'goodId', cart.good_id, 'variantId', cart.variant_id,
      'qty', cart.qty, 'inputRevision', cart.input_revision, 'inputValues', cart.input_values, 'inputSnapshot', cart.input_snapshot)
      order by cart.good_id, cart.variant_id, cart.input_key), '[]'::jsonb),
    count(*)
    into v_lines, v_count
  from public.cart_items as cart
  where cart.user_id = p_user_id
    and exists (
      select 1 from jsonb_to_recordset(p_lines) as entry(good_id text, variant_id uuid, qty integer, input_revision integer, input_values jsonb)
      where entry.good_id = cart.good_id and entry.variant_id = cart.variant_id and entry.qty = cart.qty
        and entry.input_revision = cart.input_revision and entry.input_values = cart.input_values
    );
  -- 화면이 넘긴 줄마다 같은 장바구니 행이 하나씩 있어야 한다(중복 줄·사라진 줄·바뀐 수량은 모두 불일치).
  if v_count <> jsonb_array_length(p_lines) then
    raise sqlstate 'PT409' using message = 'cart_snapshot_changed';
  end if;
  perform private.trim_checkout_drafts(p_user_id);
  insert into private.checkout_drafts (user_id, source, lines, expires_at)
  values (p_user_id, 'selection', v_lines, pg_catalog.clock_timestamp() + private.checkout_draft_ttl())
  returning id into v_draft;
  return v_draft;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_create_pg_settlement_import(p_actor_id uuid, p_operation_id uuid, p_query jsonb, p_mode text, p_scope_hash text, p_mid text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q jsonb;job private.pg_settlement_imports;
begin
 perform private.pg_settlement_require_actor(p_actor_id);q:=private.pg_settlement_query(p_query);
 if p_operation_id is null or p_mode is null or p_mode not in('test','live') or p_scope_hash is null or p_scope_hash!~'^[0-9a-f]{64}$'
  or p_mid is null or p_mid!~'^[!-~]{1,14}$' then raise invalid_parameter_value using message='settlement_invalid_import';end if;
 perform pg_advisory_xact_lock(hashtextextended('pg-settlement-operation:'||p_operation_id::text,0));
 select * into job from private.pg_settlement_imports where operation_id=p_operation_id;
 if found then
  if job.actor_id<>p_actor_id or job.mode<>p_mode or job.scope_hash<>p_scope_hash or job.mid<>p_mid
   or job.date_type<>q->>'dateType' or job.start_date<>(q->>'startDate')::date or job.end_date<>(q->>'endDate')::date then
   raise unique_violation using message='settlement_operation_conflict';end if;
  return jsonb_build_object('job',private.pg_settlement_job(job.id));
 end if;
 insert into private.pg_settlement_imports(operation_id,actor_id,mode,scope_hash,mid,date_type,start_date,end_date)
 values(p_operation_id,p_actor_id,p_mode,p_scope_hash,p_mid,q->>'dateType',(q->>'startDate')::date,(q->>'endDate')::date) returning * into job;
 insert into public.audit_log(actor_id,action,target,diff) values(p_actor_id,'admin.pg_settlement.import_started','pg-settlement:'||job.id::text,
  jsonb_build_object('importId',job.id,'mode',job.mode,'query',q));
 return jsonb_build_object('job',private.pg_settlement_job(job.id));
end $function$

