CREATE OR REPLACE FUNCTION public.service_delivery_tracking_targets(p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare settings private.delivery_tracking_settings;
begin
  if p_limit is null or p_limit not between 1 and 200 then raise invalid_parameter_value using message = 'invalid_delivery_tracking_limit'; end if;
  select * into settings from private.delivery_tracking_settings where singleton;
  if not found or not settings.auto_delivery_enabled then return jsonb_build_object('enabled', false); end if;
  return jsonb_build_object('enabled', true, 'provider', settings.provider, 'targets', coalesce((
    select jsonb_agg(jsonb_build_object('carrier', due.carrier, 'trackingNumber', due.tracking_number) order by due.polled_at nulls first, due.shipped_at, due.carrier, due.tracking_number)
    from (
      select tracking.carrier, tracking.tracking_number, min(s.shipped_at) shipped_at, max(poll.last_polled_at) polled_at
      from public.order_shipments s join public.orders o on o.id = s.order_id
      cross join lateral private.shipment_current_trackings(s.id) tracking
      left join private.shipment_tracking_polls poll on poll.carrier = tracking.carrier and poll.tracking_number = tracking.tracking_number
      where s.status = 'shipping' and s.delivery_method = 'parcel' and o.status <> 'canceled' and s.shipped_at >= now() - interval '30 days'
        and (poll.last_polled_at is null or poll.last_polled_at < now() - make_interval(mins => settings.poll_interval_minutes))
        and (private.tracking_latest_event(tracking.carrier, tracking.tracking_number, tracking.since)).status is distinct from 'delivered'
      group by tracking.carrier, tracking.tracking_number
      order by max(poll.last_polled_at) nulls first, min(s.shipped_at), tracking.carrier, tracking.tracking_number
      limit p_limit
    ) due), '[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.service_erp_read(p_table text DEFAULT NULL::text, p_columns text[] DEFAULT NULL::text[], p_after jsonb DEFAULT NULL::jsonb, p_where jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 500, p_settled boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_table record;
  v_order text[];
  v_select text;
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 1000);
  v_settled_before timestamptz;
  v_rows jsonb;
  v_kept jsonb;
  v_last jsonb;
  v_filters text[];
begin
  if p_table is null then
    insert into private.erp_read_access_log (outcome, row_count) values ('ok', null);
    return private.erp_read_catalog();
  end if;
  select * into v_table from private.erp_read_tables() as t where t.name = p_table;
  if not found then
    raise exception 'erp_read_unknown_table' using errcode = '22023';
  end if;
  v_order := case when v_table.cursor_column is null then v_table.key_columns
                  else array[v_table.cursor_column] || v_table.key_columns end;
  select string_agg(format('t.%I', c.name), ', ') into v_select
  from private.erp_read_columns(v_table.rel) as c
  where p_columns is null or c.name = any(p_columns) or c.name = any(v_order);
  -- 값으로 거른 다시 읽기는 지금 보이는 것을 그대로, 이어 읽기(커서 진행)만 안전 경계를 쓴다.
  if v_table.cursor_column is not null and coalesce(p_settled, p_where is null) then
    v_settled_before := private.erp_read_settled_before();
  end if;
  begin
    execute format('select coalesce(jsonb_agg(to_jsonb(r)), ''[]''::jsonb) from '
        || '(select %s from %s as t where %s order by %s limit %s) as r',
        v_select, v_table.rel,
        private.erp_read_where(v_table.rel, v_order, v_table.cursor_column, p_after, p_where, v_settled_before),
        (select string_agg(format('t.%I', col), ', ') from unnest(v_order) as col), v_limit)
      into v_rows;
  exception when data_exception then
    raise exception 'erp_read_invalid_value' using errcode = '22023';
  end;
  v_kept := private.erp_read_trim(v_rows, v_order);
  v_last := v_kept->-1;
  if p_where is not null then
    select array_agg(k order by k) into v_filters from jsonb_object_keys(p_where) as k;
  end if;
  -- 읽기와 같은 트랜잭션: 기록이 실패하면 이 호출 전체가 실패하고 줄도 나가지 않는다.
  if jsonb_array_length(v_kept) > 0 or p_where is not null then
    insert into private.erp_read_access_log (outcome, table_name, column_names, filter_columns, row_count)
    values ('ok', v_table.name, p_columns, v_filters, jsonb_array_length(v_kept));
  else
    insert into private.erp_read_access_rollup (bucket, table_name, outcome, calls, last_at)
    values (date_trunc('day', clock_timestamp(), 'Asia/Seoul'), v_table.name, 'idle', 1, clock_timestamp())
    on conflict (bucket, table_name, outcome)
    do update set calls = private.erp_read_access_rollup.calls + 1, last_at = excluded.last_at;
  end if;
  return jsonb_build_object(
    'table', v_table.name,
    'key', to_jsonb(v_table.key_columns),
    'cursor', v_table.cursor_column,
    'rows', v_kept,
    'settled_before', v_settled_before,
    'next', case when jsonb_array_length(v_rows) < v_limit and jsonb_array_length(v_kept) = jsonb_array_length(v_rows)
      then null else jsonb_build_object(
        'at', v_last->v_table.cursor_column,
        'key', (select jsonb_object_agg(k, v_last->k) from unnest(v_table.key_columns) as k)) end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.service_expire_gifts(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare candidate uuid;ids uuid[];subjects uuid[];gift private.gift_intents;changed integer:=0;begin
 ids:=array(select id from private.gift_intents where order_id is null and state in('awaiting_acceptance','accepted') and expires_at<=clock_timestamp()
  order by id limit greatest(1,least(coalesce(p_limit,100),100)));
 select array_agg(distinct subject order by subject) into subjects from private.gift_intents g cross join lateral unnest(array[g.sender_id,g.recipient_id]) subject where g.id=any(ids) and subject is not null;
 perform private.gift_lock_subjects(subjects);
 -- A recipient may have committed while the initial sender locks were waiting.
 -- Abort before any source lock; a fresh transaction can acquire the complete set.
 if exists(select 1 from private.gift_intents where id=any(ids) and recipient_id is not null and not(recipient_id=any(subjects))) then raise sqlstate 'PT409' using message='gift_changed';end if;
 foreach candidate in array ids loop
  begin gift:=private.gift_lock(candidate);exception when sqlstate 'PT409' then continue;end;
  if gift.order_id is not null or gift.state not in('awaiting_acceptance','accepted') or gift.expires_at>clock_timestamp() then continue;end if;
  update private.gift_intents set state='expired',closed_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where id=gift.id;
  update private.gift_link_tokens set revoked_at=clock_timestamp() where gift_id=gift.id and revoked_at is null;
  delete from private.goods_transaction_quotes where actor_id=gift.sender_id and source->>'kind'='gift' and source->>'id'=gift.id::text and order_id is null;
  delete from private.gift_recipient_addresses where gift_id=gift.id;changed:=changed+1;
 end loop;
 delete from private.gift_claim_sessions s where s.expires_at<=clock_timestamp() or exists(select 1 from private.gift_link_tokens t where t.token_hash=s.token_hash and(t.revoked_at is not null or t.consumed_at is not null));
 return jsonb_build_object('expired',changed);
end $function$

CREATE OR REPLACE FUNCTION public.service_export_bank_transfer_refund_accounts(p_actor_id uuid, p_session_id uuid, p_export_id uuid, p_claims jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 actor uuid:=p_actor_id; target record; purchase public.orders; claim public.order_cancellation_requests;
 lifecycle private.bank_transfer_claim_refunds; account private.claim_refund_accounts; blocker text; view_id uuid;
 happened timestamptz; results jsonb[]:='{}'; revealed integer:=0; order_ids uuid[]; claim_ids uuid[];
begin
 if actor is null or p_session_id is null or p_export_id is null or jsonb_typeof(p_claims) is distinct from 'array'
  or jsonb_array_length(p_claims)>10000
  or exists(select 1 from jsonb_array_elements(p_claims) item where jsonb_typeof(item) is distinct from 'object'
   or exists(select 1 from jsonb_object_keys(item) item_key where item_key not in('claimId','orderId','revision'))
   or jsonb_typeof(item->'claimId') is distinct from 'string' or jsonb_typeof(item->'orderId') is distinct from 'string'
   or jsonb_typeof(item->'revision') is distinct from 'number'
   or item->>'claimId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or item->>'orderId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or item->>'revision' !~ '^[0-9]{1,9}$') then
  raise invalid_parameter_value using message='invalid_bank_refund_export';
 end if;
 select coalesce(array_agg(distinct (item->>'orderId')::uuid),'{}'),coalesce(array_agg(distinct (item->>'claimId')::uuid),'{}')
  into order_ids,claim_ids from jsonb_array_elements(p_claims) item;
 -- 한 주문에는 송금 대기 무통장 환불이 하나뿐이다(private.bank_transfer_claim_refunds.order_id 고유).
 if cardinality(order_ids)<>jsonb_array_length(p_claims) or cardinality(claim_ids)<>jsonb_array_length(p_claims) then
  raise invalid_parameter_value using message='invalid_bank_refund_export';
 end if;

 -- 서버가 확인한 운영자 세션이 지금도 살아 있어야 한다(require_claim_refund_account_identity와 같은 규칙, 서버 증명이라 JWT 대신 인자로 받는다).
 if not exists(select 1 from auth.sessions where id=p_session_id and user_id=actor and (not_after is null or not_after>statement_timestamp()))
  or not exists(select 1 from public.profiles where id=actor) then
  raise insufficient_privilege using message='refund_account_auth_changed';
 end if;
 if not private.has_operator_capability(actor,'sales.manage',true) or not private.operator_mfa_service_session_ok(actor,p_session_id) then
  raise insufficient_privilege using message='bank_refund_permission_required';
 end if;
 -- 요청 상세 열람(lock_bank_transfer_refund_identity)과 같은 순서: 운영자·결제자·수령인 계정 울타리 → 권한 재확인 → 세션 행.
 perform private.lock_operator_subjects(array[actor]||coalesce((select array_agg(subject) from (
   select purchase_row.user_id subject from public.orders purchase_row where purchase_row.id=any(order_ids)
   union select gift.recipient_id from private.gift_intents gift where gift.order_id=any(order_ids)) subjects where subject is not null),'{}'));
 perform private.require_actor_operator_capability(actor,'sales.manage',true);
 perform id from auth.sessions where id=p_session_id and user_id=actor and (not_after is null or not_after>clock_timestamp()) for share;
 if not found then raise insufficient_privilege using message='refund_account_auth_changed'; end if;
 -- 행 잠금은 다른 쓰기와 같은 주문 → 배송 → 요청 → 결제 → 환불 → 계좌 순서이고, 각 단계 안에서는 id 순서다.
 perform purchase_row.id from public.orders purchase_row where purchase_row.id=any(order_ids) order by purchase_row.id for update;
 perform shipment.id from public.order_shipments shipment where shipment.order_id=any(order_ids) order by shipment.id for update;
 perform request.id from public.order_cancellation_requests request where request.id=any(claim_ids) order by request.id for update;
 perform payment.id from public.payments payment where payment.purpose='order' and payment.ref_id=any(order_ids) order by payment.id for update;
 perform refund.id from public.refunds refund join public.payments payment on payment.id=refund.payment_id
  where payment.purpose='order' and payment.ref_id=any(order_ids) order by refund.id for update of refund;
 perform stored.claim_id from private.claim_refund_accounts stored where stored.claim_id=any(claim_ids) order by stored.claim_id for share;

 happened:=clock_timestamp();
 for target in select (item.value->>'claimId')::uuid claim_id,(item.value->>'orderId')::uuid order_id,(item.value->>'revision')::integer revision
  from jsonb_array_elements(p_claims) with ordinality item(value,ord) order by item.ord loop
  select * into purchase from public.orders where id=target.order_id;
  select * into claim from public.order_cancellation_requests where id=target.claim_id and order_id=target.order_id;
  select * into lifecycle from private.bank_transfer_claim_refunds where claim_id=target.claim_id and order_id=target.order_id;
  if purchase.id is null or claim.id is null or claim.claim_revision<>target.revision or lifecycle.state is distinct from 'awaiting_transfer' then
   raise sqlstate 'PT409' using message='bank_refund_export_changed';
  end if;
  blocker:=private.bank_transfer_refund_blocker(claim,purchase,'view_account');
  if blocker is null then
   select * into account from private.claim_refund_accounts where claim_id=claim.id;
   view_id:=gen_random_uuid();
   -- 계좌 원문은 감사 기록에 남기지 않는다. 요청 상세 열람과 같은 열람 기록·주문 감사 기록을 요청마다 남긴다.
   insert into private.bank_transfer_refund_account_views(id,actor_id,session_id,order_id,claim_id,created_at)
   values(view_id,actor,p_session_id,purchase.id,claim.id,happened);
   insert into public.audit_log(id,actor_id,action,target,diff) values(view_id,actor,'admin.order.bank_refund_account_viewed','order:'||purchase.id,
    jsonb_build_object('claimId',claim.id,'purpose','list_export','revision',claim.claim_revision,'exportId',p_export_id));
   revealed:=revealed+1;
   results:=array_append(results,jsonb_build_object('claimId',claim.id,'status','revealed',
    'bankName',account.bank_name,'accountNumber',account.account_number,'accountHolder',account.account_holder));
  else
   results:=array_append(results,jsonb_build_object('claimId',claim.id,
    'status',case when blocker in('bank_refund_filing_required','claim_refund_account_missing') then 'not_filed' else 'unavailable' end,
    'bankName',null,'accountNumber',null,'accountHolder',null));
  end if;
 end loop;
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_export_id,actor,'admin.list_export.bank_refund_accounts_revealed',
  'admin_screen:refund-transfers',jsonb_build_object('claimCount',jsonb_array_length(p_claims),'revealedCount',revealed));
 return jsonb_build_object('exportId',p_export_id,'rows',to_jsonb(results));
end $function$

CREATE OR REPLACE FUNCTION public.service_export_order_partial_cancellation_refund_accounts(p_actor_id uuid, p_session_id uuid, p_export_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := p_actor_id; target record; head private.order_partial_cancellations; account private.order_partial_cancellation_refund_accounts;
  results jsonb[] := '{}'; revealed integer := 0; order_ids uuid[]; ids uuid[]; happened timestamptz;
begin
  if actor is null or p_session_id is null or p_export_id is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) > 10000
    or exists(select 1 from jsonb_array_elements(p_items) item where jsonb_typeof(item) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(item) k where k not in ('partialCancellationId', 'orderId'))
      or coalesce(item->>'partialCancellationId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or coalesce(item->>'orderId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
    raise invalid_parameter_value using message = 'invalid_bank_refund_export';
  end if;
  select coalesce(array_agg(distinct (item->>'orderId')::uuid), '{}'), coalesce(array_agg(distinct (item->>'partialCancellationId')::uuid), '{}')
    into order_ids, ids from jsonb_array_elements(p_items) item;
  if cardinality(ids) <> jsonb_array_length(p_items) then raise invalid_parameter_value using message = 'invalid_bank_refund_export'; end if;
  if not exists(select 1 from auth.sessions where id = p_session_id and user_id = actor and (not_after is null or not_after > statement_timestamp()))
    or not exists(select 1 from public.profiles where id = actor) then
    raise insufficient_privilege using message = 'refund_account_auth_changed';
  end if;
  if not private.has_operator_capability(actor, 'sales.manage', true) or not private.operator_mfa_service_session_ok(actor, p_session_id) then raise insufficient_privilege using message = 'bank_refund_permission_required'; end if;
  perform private.lock_operator_subjects(array[actor] || coalesce((select array_agg(purchase.user_id) from public.orders purchase where purchase.id = any(order_ids)), '{}'));
  perform private.require_actor_operator_capability(actor, 'sales.manage', true);
  perform id from auth.sessions where id = p_session_id and user_id = actor and (not_after is null or not_after > clock_timestamp()) for share;
  if not found then raise insufficient_privilege using message = 'refund_account_auth_changed'; end if;
  perform purchase.id from public.orders purchase where purchase.id = any(order_ids) order by purchase.id for update;
  perform h.id from private.order_partial_cancellations h where h.id = any(ids) order by h.id for update;
  happened := clock_timestamp();
  for target in select (item.value->>'partialCancellationId')::uuid id, (item.value->>'orderId')::uuid order_id
    from jsonb_array_elements(p_items) with ordinality item(value, ord) order by item.ord loop
    select * into head from private.order_partial_cancellations where id = target.id and order_id = target.order_id;
    if head.id is null or head.provider <> 'bank_transfer' or head.state <> 'awaiting_transfer' then
      raise sqlstate 'PT409' using message = 'bank_refund_export_changed';
    end if;
    select * into account from private.order_partial_cancellation_refund_accounts where partial_cancellation_id = head.id;
    if account.partial_cancellation_id is not null and account.purged_at is null and account.account_number is not null then
      insert into public.audit_log(actor_id, action, target, diff)
      values (actor, 'admin.order.partial_cancellation_account_viewed', 'order:' || head.order_id::text,
        jsonb_build_object('partialCancellationId', head.id, 'purpose', 'list_export', 'exportId', p_export_id, 'maskedAccount', account.masked_account));
      revealed := revealed + 1;
      results := array_append(results, jsonb_build_object('partialCancellationId', head.id, 'status', 'revealed',
        'bankName', account.bank_name, 'accountNumber', account.account_number, 'accountHolder', account.account_holder));
    else
      results := array_append(results, jsonb_build_object('partialCancellationId', head.id, 'status', 'unavailable',
        'bankName', null, 'accountNumber', null, 'accountHolder', null));
    end if;
  end loop;
  insert into public.audit_log(actor_id, action, target, diff)
  values (actor, 'admin.list_export.partial_cancel_refund_accounts_revealed', 'admin_screen:refund-transfers',
    jsonb_build_object('exportId', p_export_id, 'partialCancellationCount', jsonb_array_length(p_items), 'revealedCount', revealed, 'at', happened));
  return jsonb_build_object('exportId', p_export_id, 'rows', to_jsonb(results));
end $function$

CREATE OR REPLACE FUNCTION public.service_fail_member_email_change(p_challenge_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_challenge_id is null or p_user_id is null then
    raise invalid_parameter_value using message = 'invalid_member_email_change';
  end if;
  update private.member_email_change_challenges
    set status = 'send_failed', resolved_at = clock_timestamp(), email = null
    where id = p_challenge_id and user_id = p_user_id and status = 'pending';
  return found;
end;
$function$

