CREATE OR REPLACE FUNCTION public.service_fail_pg_settlement_import(p_actor_id uuid, p_import_id uuid, p_claim_id uuid, p_scope_hash text, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job private.pg_settlement_imports;
begin
 perform private.pg_settlement_require_actor(p_actor_id);
 select * into job from private.pg_settlement_imports where id=p_import_id for update;
 if not found or job.actor_id<>p_actor_id then raise insufficient_privilege using message='settlement_import_unavailable';end if;
 if job.state in('complete','failed') then return jsonb_build_object('kind',job.state,'job',private.pg_settlement_job(job.id));end if;
 if job.scope_hash is distinct from p_scope_hash then p_error:='scope_changed';
 elsif p_claim_id is null or job.claim_id is distinct from p_claim_id or job.lease_until<=clock_timestamp() then return jsonb_build_object('kind','stale','job',private.pg_settlement_job(job.id));end if;
 if p_error is null or p_error not in('invalid_request','invalid_response','merchant_mismatch','duplicate_transaction','provider_unavailable','provider_credentials','response_too_large','page_limit','scope_changed','snapshot_changed') then
  raise invalid_parameter_value using message='settlement_invalid_error';end if;
 update private.pg_settlement_imports set state=case when p_error='provider_unavailable' then job.state else 'failed' end,error_code=p_error,
  claim_id=null,lease_until=null,updated_at=clock_timestamp() where id=job.id;
 return jsonb_build_object('kind',case when p_error='provider_unavailable' then 'accepted' else 'failed' end,'job',private.pg_settlement_job(job.id));
end $function$

CREATE OR REPLACE FUNCTION public.service_fake_billing_command(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare profile_uuid uuid;kind text;at_time timestamptz;reference text;existing jsonb;current_hash text;credential private.fake_billing_credentials;result jsonb;
begin
 perform private.subscription_require_service();
 if jsonb_typeof(p_command) is distinct from 'object' or p_command-array['kind','profileId','operationRef','payloadHash','credentialRef','customerRef','orderRef','attemptId','amount','at','decline']<>'{}'::jsonb
  or not(p_command?&array['kind','profileId','at']) or p_command->>'kind' not in('register','charge','inspect','refund','revoke') then
  raise invalid_parameter_value using message='invalid_fake_billing_command';end if;
 profile_uuid:=(p_command->>'profileId')::uuid;kind:=p_command->>'kind';at_time:=(p_command->>'at')::timestamptz;
 if not(select fake_local_enabled from private.goods_subscription_runtime where singleton)
  or not exists(select 1 from private.billing_profiles p where p.id=profile_uuid and p.adapter='fake' and p.environment='test') then
  raise insufficient_privilege using message='fake_billing_disabled';end if;
 if at_time is null or at_time<clock_timestamp()-interval '5 minutes' or at_time>clock_timestamp()+interval '5 minutes' then
  raise invalid_parameter_value using message='invalid_fake_billing_time';end if;
 perform pg_advisory_xact_lock(hashtextextended('fake-billing:'||profile_uuid::text,0));
 result:=jsonb_build_object('state','conflict','at',at_time);
 if kind='inspect' then
  return coalesce((select receipt from private.fake_billing_payments p where p.profile_id=profile_uuid and p.order_ref=p_command->>'orderRef'),jsonb_build_object('state','not_found','at',at_time));
 elsif kind='revoke' then
  update private.fake_billing_credentials c set revoked=true where c.profile_id=profile_uuid and c.credential_ref=p_command->>'credentialRef';
  return jsonb_build_object('state',case when found then 'revoked' else 'not_found' end,'at',at_time);
 end if;
 if coalesce(p_command->>'operationRef','')!~'^[0-9a-f]{64}$' or coalesce(p_command->>'payloadHash','')!~'^[0-9a-f]{64}$' then return result;end if;
 select o.payload_hash,o.receipt into current_hash,existing from private.fake_billing_operations o where o.profile_id=profile_uuid and o.operation_ref=p_command->>'operationRef';
 if found then return case when current_hash=p_command->>'payloadHash' then existing else result end;end if;
 if kind='register' then
  if coalesce(p_command->>'credentialRef','')!~'^[0-9a-f]{64}$' or coalesce(p_command->>'customerRef','')!~'^[0-9a-f]{64}$' then return result;end if;
  select * into credential from private.fake_billing_credentials c where c.profile_id=profile_uuid and c.credential_ref=p_command->>'credentialRef';
  if found and (credential.revoked or credential.customer_ref<>p_command->>'customerRef') then return result;end if;
  insert into private.fake_billing_credentials(profile_id,credential_ref,customer_ref) values(profile_uuid,p_command->>'credentialRef',p_command->>'customerRef') on conflict do nothing;
  result:=jsonb_build_object('state','registered','at',at_time);
 else
  if coalesce(p_command->>'orderRef','')!~'^[0-9a-f]{64}$' or p_command->>'attemptId' is null
   or jsonb_typeof(p_command->'amount') is distinct from 'number' or p_command->>'amount'!~'^[0-9]+$'
   or (p_command->>'amount')::numeric not between 100 and 999999999999 then return result;end if;
  perform (p_command->>'attemptId')::uuid;
  select receipt into existing from private.fake_billing_payments p where p.profile_id=profile_uuid and p.order_ref=p_command->>'orderRef';
  if kind='charge' then
   if found then return result;end if;
   select * into credential from private.fake_billing_credentials c where c.profile_id=profile_uuid and c.credential_ref=p_command->>'credentialRef';
   if not found or credential.revoked or credential.customer_ref is distinct from p_command->>'customerRef' then result:=jsonb_build_object('state','declined','at',at_time);
   else
    result:=jsonb_build_object('state',case when coalesce((p_command->>'decline')::boolean,false) then 'declined' else 'approved' end,
     'attemptId',p_command->>'attemptId','amount',p_command->'amount','paymentKey','fake_payment_'||replace(p_command->>'attemptId','-',''),
     'transactionId','fake_approval_'||replace(p_command->>'attemptId','-',''),'at',at_time);
    insert into private.fake_billing_payments(profile_id,order_ref,receipt) values(profile_uuid,p_command->>'orderRef',result);
   end if;
  else
   if existing is null or existing->>'attemptId' is distinct from p_command->>'attemptId' or existing->'amount' is distinct from p_command->'amount' then
    return jsonb_build_object('state','not_found','at',at_time);end if;
   if existing->>'state'='canceled' then result:=existing;
   elsif existing->>'state'<>'approved' then return result;
   else result:=existing||jsonb_build_object('state','canceled','transactionId','fake_cancel_'||replace(p_command->>'attemptId','-',''),'at',at_time);
    update private.fake_billing_payments p set receipt=result where p.profile_id=profile_uuid and p.order_ref=p_command->>'orderRef';
   end if;
  end if;
 end if;
 insert into private.fake_billing_operations(profile_id,operation_ref,payload_hash,receipt) values(profile_uuid,p_command->>'operationRef',p_command->>'payloadHash',result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.service_fallback_order_claim_refund_deduction(p_request_id uuid, p_payment_id uuid, p_actor_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claim public.order_cancellation_requests; pay public.payments; d private.claim_refund_deductions;
begin
  if p_actor_id is not null and not private.can_finish_operator_cancellation(p_request_id, p_actor_id) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  select * into claim from public.order_cancellation_requests where id = p_request_id;
  if not found then raise no_data_found using message = 'cancellation_request_not_found'; end if;
  perform id from public.orders where id = claim.order_id for update;
  select * into claim from public.order_cancellation_requests where id = p_request_id for update;
  if p_actor_id is null and claim.claim_type <> 'cancel' then
    raise insufficient_privilege using message = 'staff required';
  end if;
  select * into pay from public.payments where id = p_payment_id and purpose = 'order' and ref_id = claim.order_id for update;
  perform r.id from public.refunds r where r.payment_id = p_payment_id for update;
  select * into d from private.claim_refund_deductions where claim_id = p_request_id for update;
  if d.claim_id is null or pay.id is null or d.payment_id <> pay.id or pay.provider <> 'toss' then
    raise check_violation using message = 'refund_deduction_not_found';
  end if;
  if d.state = 'not_applied' then return d.state; end if;
  if d.state <> 'planned' then raise check_violation using message = 'refund_deduction_already_confirmed'; end if;
  update private.claim_refund_deductions set state = 'not_applied', not_applied_reason = 'partial_cancel_unavailable',
    not_applied_at = clock_timestamp() where claim_id = p_request_id;
  update public.refunds set amount = pay.amount - private.payment_partial_refunded_amount(pay.id) where payment_id = pay.id and status <> 'done';
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor_id, case when p_actor_id is null then 'system.order.claim_refund_deduction_not_applied' else 'admin.order.claim_refund_deduction_not_applied' end,
    'order:' || claim.order_id::text,
    jsonb_build_object('claimId', p_request_id, 'paymentId', pay.id, 'reason', 'partial_cancel_unavailable',
      'deductionAmount', d.deduction_amount, 'refundAmount', pay.amount - private.payment_partial_refunded_amount(pay.id)));
  return 'not_applied';
end $function$

CREATE OR REPLACE FUNCTION public.service_finalize_subscription_payment_reconciliation(p_attempt_id uuid, p_claim_token uuid, p_outcome public.payment_attempt_state, p_provider_payment_key text DEFAULT NULL::text, p_provider_transaction_id text DEFAULT NULL::text, p_provider_approval_reference text DEFAULT NULL::text, p_result_code text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text, p_masked_payment_method text DEFAULT NULL::text, p_approved_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS public.payment_attempt_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare binding private.payment_provider_bindings;cycle private.goods_subscription_cycles;result public.payment_attempt_state;begin
 perform private.subscription_require_service();
 select * into binding from private.payment_provider_bindings where attempt_id=p_attempt_id;
 if not found then raise no_data_found using message='billing_binding_missing';end if;
 perform private.lock_goods_transaction_source(binding.owner_id,private.subscription_source(binding.cycle_id,'reconcile'));
 select * into cycle from private.goods_subscription_cycles where id=binding.cycle_id;
 if not found then
  return public.finalize_goods_payment_reconciliation(p_attempt_id,p_claim_token,p_outcome,p_provider_payment_key,p_provider_transaction_id,
   p_provider_approval_reference,p_result_code,p_payment_method,p_masked_payment_method,p_approved_at);
 end if;
 perform 1 from private.goods_subscription_plans where id=cycle.plan_id for update;
 perform 1 from private.goods_subscription_cycles where id=cycle.id for update;
 result:=public.finalize_goods_payment_reconciliation(p_attempt_id,p_claim_token,p_outcome,p_provider_payment_key,p_provider_transaction_id,
  p_provider_approval_reference,p_result_code,p_payment_method,p_masked_payment_method,p_approved_at);
 perform private.subscription_sync_cycle_outcome(cycle.id,result);return result;
end $function$

CREATE OR REPLACE FUNCTION public.service_finish_billing_credential_revocation(p_actor_id uuid, p_credential_id uuid, p_claim_token uuid, p_claim_fence bigint, p_state text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare credential private.billing_credentials;begin
 perform private.subscription_require_service();perform private.subscription_lock_actor(p_actor_id,false);
 select * into credential from private.billing_credentials where id=p_credential_id and owner_id=p_actor_id for update;
 if not found then raise no_data_found using message='billing_credential_not_found';end if;
 if credential.state='revoked' then return jsonb_build_object('id',credential.id,'state','revoked','revision',credential.revision);end if;
 if credential.state<>'revoking' or p_claim_token is null or p_claim_fence is null or p_claim_fence<1
  or credential.revoke_claim_token is null or credential.revoke_lease_until is null
  or credential.revoke_claim_token is distinct from p_claim_token or credential.revoke_fence is distinct from p_claim_fence or credential.revoke_lease_until<=clock_timestamp() then
  raise sqlstate 'PT409' using message='billing_credential_claim_stale';end if;
 if p_state is null or p_state not in('revoked','unknown','needs_review') then raise invalid_parameter_value using message='invalid_billing_revoke_result';end if;
 update private.billing_credentials set state=case when p_state='revoked' then 'revoked' when p_state='needs_review' or revoke_fence>=12 then 'needs_review' else 'revoking' end,
  envelope=case when p_state='revoked' then null else envelope end,revoked_at=case when p_state='revoked' then clock_timestamp() end,
  revoke_claim_token=null,revoke_lease_until=null,revoke_next_check_at=case when p_state='unknown' and revoke_fence<12 then clock_timestamp()+interval '5 minutes' end,
  revision=revision+1 where id=p_credential_id returning * into credential;
 return jsonb_build_object('id',credential.id,'state',credential.state,'revision',credential.revision);
end $function$

CREATE OR REPLACE FUNCTION public.service_finish_billing_registration(p_actor_id uuid, p_id uuid, p_claim_token uuid, p_claim_fence bigint, p_state text, p_envelope jsonb DEFAULT NULL::jsonb, p_card jsonb DEFAULT NULL::jsonb, p_authenticated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare entry private.billing_enrollments;available boolean;begin
 perform private.subscription_require_service();perform private.subscription_lock_actor(p_actor_id,false);
 select * into entry from private.billing_enrollments where id=p_id and owner_id=p_actor_id for update;
 if not found then raise no_data_found using message='billing_registration_not_found';end if;
 if entry.state='ready' then return private.billing_registration_summary(p_id,false);end if;
 if entry.state<>'processing' or p_claim_token is null or p_claim_fence is null or p_claim_fence<1
  or entry.claim_token is null or entry.lease_until is null or entry.first_dispatched_at is null
  or entry.claim_token is distinct from p_claim_token or entry.claim_fence is distinct from p_claim_fence or entry.lease_until<=clock_timestamp() then
  raise sqlstate 'PT409' using message='billing_registration_claim_stale';end if;
 if p_state is null or p_state not in('ready','declined','unknown','needs_review') or (p_reason is not null and p_reason!~'^[a-z0-9_]{1,64}$') then
  raise invalid_parameter_value using message='invalid_billing_registration_result';end if;
 if p_state='ready' then
  if not private.subscription_valid_envelope(p_envelope) or not coalesce(private.subscription_json_keys(p_card,array['issuerCode','number']),false)
   or p_card->>'issuerCode'!~'^[A-Z0-9]{2}$' or p_card->>'number'!~'^[0-9*]{8,20}$'
   or length(replace(p_card->>'number','*',''))>12 or length(p_card->>'number')-length(replace(p_card->>'number','*',''))<4
   or p_card->>'number'~'[0-9]{9}' or p_authenticated_at is null or p_authenticated_at>clock_timestamp()+interval '5 minutes' then
   raise invalid_parameter_value using message='invalid_billing_registration_result';end if;
  available:=not private.is_account_write_fenced(p_actor_id) and exists(select 1 from public.profiles where id=p_actor_id and suspended_at is null);
  insert into private.billing_credentials(id,owner_id,customer_id,profile_id,envelope,state,issuer_code,masked_number,authenticated_at)
   values(entry.credential_id,p_actor_id,entry.customer_id,entry.profile_id,p_envelope,case when available then 'active' else 'revoking' end,
    p_card->>'issuerCode',p_card->>'number',p_authenticated_at);
 end if;
 update private.billing_enrollments set state=p_state,claim_token=null,lease_until=null,
  auth_envelope=case when p_state in('ready','declined') then null else auth_envelope end,safe_reason=p_reason,updated_at=clock_timestamp() where id=p_id;
 return private.billing_registration_summary(p_id,false);
end $function$

CREATE OR REPLACE FUNCTION public.service_finish_goods_subscription_work(p_actor_id uuid, p_cycle_id uuid, p_claim_token uuid, p_claim_fence bigint, p_outcome public.payment_attempt_state, p_provider_payment_key text DEFAULT NULL::text, p_provider_transaction_id text DEFAULT NULL::text, p_provider_approval_reference text DEFAULT NULL::text, p_result_code text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text, p_masked_payment_method text DEFAULT NULL::text, p_approved_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS public.payment_attempt_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cycle private.goods_subscription_cycles;result public.payment_attempt_state;begin
 perform private.subscription_require_service();perform private.lock_goods_transaction_source(p_actor_id,private.subscription_source(p_cycle_id,'finish'));
 select * into cycle from private.goods_subscription_cycles where id=p_cycle_id and owner_id=p_actor_id;
 if not found then raise no_data_found using message='subscription_cycle_not_found';end if;
 perform 1 from private.goods_subscription_plans where id=cycle.plan_id for update;
 select * into cycle from private.goods_subscription_cycles where id=p_cycle_id for update;
 if cycle.state in('approved','declined','canceled') then return cycle.state::public.payment_attempt_state;end if;
 if p_claim_token is null or p_claim_fence is null or p_claim_fence<1 or cycle.claim_token is null or cycle.lease_until is null
  or cycle.claim_token is distinct from p_claim_token or cycle.claim_fence is distinct from p_claim_fence or cycle.lease_until<=clock_timestamp() then
  raise sqlstate 'PT409' using message='subscription_claim_stale';end if;
 if cycle.attempt_id is null or cycle.dispatched_at is null then raise object_not_in_prerequisite_state using message='subscription_not_dispatched';end if;
 result:=public.finalize_goods_payment_attempt(cycle.attempt_id,p_claim_token,p_outcome,p_provider_payment_key,p_provider_transaction_id,
  p_provider_approval_reference,p_result_code,p_payment_method,p_masked_payment_method,p_approved_at);
 update private.goods_payment_reconciliation_audits set claim_status='terminal',outcome=result,finalized_at=clock_timestamp()
  where claim_token=p_claim_token and operation='payment' and target_id=cycle.attempt_id;
 perform private.subscription_sync_cycle_outcome(cycle.id,result);return result;
end $function$

CREATE OR REPLACE FUNCTION public.service_finish_operator_invitation_email(p_invitation_id uuid, p_claim_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare affected integer;
begin
  if p_error is not null and p_error not in ('provider_not_configured','delivery_disabled','delivery_in_progress','delivery_outcome_unknown','provider_rejected','provider_retryable','delivery_needs_review','token_key_changed')
    then raise invalid_parameter_value using message='invalid_operator_invitation_delivery_error'; end if;
  -- Completes only a pre-authorized dispatch receipt. Never changes membership,
  -- pending/accepted/cancelled state, or the token after authority is revoked.
  update private.operator_invitations set dispatch_claim_id=null,delivery_error=p_error where id=p_invitation_id and dispatch_claim_id=p_claim_id;
  get diagnostics affected=row_count;
  return affected=1;
end $function$

CREATE OR REPLACE FUNCTION public.service_finish_pg_settlement_import(p_actor_id uuid, p_import_id uuid, p_claim_id uuid, p_scope_hash text, p_page jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job private.pg_settlement_imports;prior private.pg_settlement_pages;item jsonb;key text;input_hash text;v_source_count integer;v_record_count integer;is_terminal boolean;matching jsonb;failure text;
begin
 perform private.pg_settlement_require_actor(p_actor_id);
 select * into job from private.pg_settlement_imports where id=p_import_id for update;
 if not found or job.actor_id<>p_actor_id then raise insufficient_privilege using message='settlement_import_unavailable';end if;
 if job.state not in('complete','failed') and job.scope_hash is distinct from p_scope_hash then
  update private.pg_settlement_imports set state='failed',error_code='scope_changed',claim_id=null,lease_until=null,updated_at=clock_timestamp() where id=job.id;
  return jsonb_build_object('kind','failed','job',private.pg_settlement_job(job.id));end if;
 input_hash:=encode(extensions.digest(p_page::text,'sha256'),'hex');
 select * into prior from private.pg_settlement_pages where import_id=job.id and claim_id=p_claim_id;
 if found then
  if prior.input_hash is distinct from input_hash then raise unique_violation using message='settlement_page_conflict';end if;
  return jsonb_build_object('kind',case when job.state in('complete','failed')then job.state else 'accepted' end,'job',private.pg_settlement_job(job.id));end if;
 if job.state in('complete','failed') then return jsonb_build_object('kind',job.state,'job',private.pg_settlement_job(job.id));end if;
 if p_claim_id is null or job.claim_id is distinct from p_claim_id or job.lease_until<=clock_timestamp() then
  return jsonb_build_object('kind','stale','job',private.pg_settlement_job(job.id));end if;
 begin
  if pg_column_size(p_page)>8388608 or jsonb_typeof(p_page) is distinct from 'object' or jsonb_typeof(p_page->'records') is distinct from 'array'
   or jsonb_typeof(p_page->'sourceTransactionKeys') is distinct from 'array' or jsonb_typeof(p_page->'terminal') is distinct from 'boolean'
   or coalesce(p_page->>'page','')!~'^[0-9]{1,2}$' or (p_page->>'page')::int<>job.next_page
   or coalesce(p_page->>'sourceCount','')!~'^[0-9]{1,4}$' or (p_page->>'sourceCount')::int not between 0 and 1000
   or coalesce(p_page->>'sourceHash','')!~'^[0-9a-f]{64}$' or coalesce(p_page->>'recordsHash','')!~'^[0-9a-f]{64}$' then
   raise invalid_parameter_value using message='invalid_response';end if;
  v_source_count:=(p_page->>'sourceCount')::int;v_record_count:=jsonb_array_length(p_page->'records');is_terminal:=(p_page->>'terminal')::boolean;
  if v_record_count>v_source_count or jsonb_array_length(p_page->'sourceTransactionKeys')<>v_source_count or is_terminal<>(v_source_count<1000)
   or (job.next_page=21 and v_source_count>0) or coalesce((select sum(p.source_count) from private.pg_settlement_pages p where p.import_id=job.id and p.scan=job.scan),0)+v_source_count>20000 then raise invalid_parameter_value using message='page_limit';end if;
  for item in select * from jsonb_array_elements(p_page->'sourceTransactionKeys') loop
   key:=item#>>'{}';
   if jsonb_typeof(item)<>'string' or key!~'^[!-~]{1,64}$' then raise invalid_parameter_value using message='invalid_response';end if;
   insert into private.pg_settlement_source_keys(import_id,scan,transaction_key) values(job.id,job.scan,key);
  end loop;
  for item in select * from jsonb_array_elements(p_page->'records') loop
   perform private.pg_settlement_validate_record(item,job);key:=item->>'transactionKey';
   if not p_page->'sourceTransactionKeys' ? key then raise invalid_parameter_value using message='invalid_response';end if;
   if job.scan=1 then
    insert into private.pg_settlement_records(import_id,transaction_key,record,record_hash,kind,currency,sold_date,paid_out_date)
    values(job.id,key,item,encode(extensions.digest(item::text,'sha256'),'hex'),case when item->'cancel'='null'::jsonb then 'approval' else 'cancel' end,
     item->>'currency',(item->>'soldDate')::date,(item->>'paidOutDate')::date);
   else
    update private.pg_settlement_records set verified=true where import_id=job.id and transaction_key=key and not verified
     and record=item and record_hash=encode(extensions.digest(item::text,'sha256'),'hex');
    if not found then raise invalid_parameter_value using message='snapshot_changed';end if;
   end if;
  end loop;
  insert into private.pg_settlement_pages(import_id,scan,page,claim_id,source_count,record_count,source_hash,records_hash,input_hash,terminal)
  values(job.id,job.scan,job.next_page,p_claim_id,v_source_count,v_record_count,p_page->>'sourceHash',p_page->>'recordsHash',input_hash,is_terminal);
  if is_terminal and job.scan=2 then
   if exists(select 1 from private.pg_settlement_records where import_id=job.id and not verified) then raise invalid_parameter_value using message='snapshot_changed';end if;
   for item in select jsonb_build_object('id',id,'match',private.pg_settlement_match_account(record,job)) from private.pg_settlement_records where import_id=job.id loop
    matching:=item->'match';
    update private.pg_settlement_records set match_state=matching->>'state',match_reason=matching->>'reason',purpose=matching->>'purpose',
     reference_id=(matching->>'referenceId')::uuid,order_number=matching->>'orderNumber' where id=(item->>'id')::uuid;
   end loop;
   update private.pg_settlement_imports set state='complete',source_count=job.source_count+v_source_count,claim_id=null,lease_until=null,error_code=null,
    completed_at=clock_timestamp(),updated_at=clock_timestamp() where id=job.id;
   insert into public.audit_log(actor_id,action,target,diff) values(p_actor_id,'admin.pg_settlement.import_completed','pg-settlement:'||job.id::text,
    jsonb_build_object('importId',job.id,'mode',job.mode,'recordCount',job.record_count));
  elsif is_terminal then
   update private.pg_settlement_imports set state='verifying',scan=2,next_page=1,record_count=job.record_count+v_record_count,source_count=job.source_count+v_source_count,
    claim_id=null,lease_until=null,error_code=null,updated_at=clock_timestamp() where id=job.id;
  else
   update private.pg_settlement_imports set next_page=job.next_page+1,record_count=job.record_count+case when job.scan=1 then v_record_count else 0 end,
    source_count=job.source_count+v_source_count,claim_id=null,lease_until=null,error_code=null,updated_at=clock_timestamp() where id=job.id;
  end if;
 exception when unique_violation then failure:='duplicate_transaction';
 when data_exception then failure:=case when sqlerrm in('snapshot_changed','page_limit')then sqlerrm else 'invalid_response' end;
 end;
 if failure is not null then update private.pg_settlement_imports set state='failed',error_code=failure,claim_id=null,lease_until=null,updated_at=clock_timestamp() where id=job.id;end if;
 return jsonb_build_object('kind',case when failure is not null then 'failed' when is_terminal and job.scan=2 then 'complete' else 'accepted' end,'job',private.pg_settlement_job(job.id));
end $function$

CREATE OR REPLACE FUNCTION public.service_get_billing_registration(p_actor_id uuid, p_session_id uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.subscription_require_service();
 if not exists(select 1 from auth.sessions where id=p_session_id and user_id=p_actor_id)
  or not exists(select 1 from private.billing_enrollments where id=p_id and owner_id=p_actor_id and session_id=p_session_id) then
  raise insufficient_privilege using message='billing_registration_forbidden';end if;
 return private.billing_registration_summary(p_id,true);
end $function$

CREATE OR REPLACE FUNCTION public.service_get_nicepay_payment_references(p_attempt_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_attempt_id is null then
    raise invalid_parameter_value using message = 'nicepay_reference_invalid';
  end if;

  if not exists (
    select 1
    from public.payment_attempts as attempt
    where attempt.id = p_attempt_id
      and attempt.provider = 'nicepay'
      and attempt.purpose = 'order'
  ) then
    raise no_data_found using message = 'goods_payment_attempt_not_found';
  end if;

  return array(
    select distinct reference.transaction_id
    from (
      select pg_catalog.btrim(evidence.provider_transaction_id) as transaction_id
      from private.payment_provider_evidence as evidence
      where evidence.payment_attempt_id = p_attempt_id
        and evidence.provider_transaction_id is not null
      union all
      select pg_catalog.btrim(evidence.provider_payment_key)
      from private.payment_provider_evidence as evidence
      where evidence.payment_attempt_id = p_attempt_id
        and evidence.provider_payment_key is not null
    ) as reference
    where reference.transaction_id ~ '^[A-Za-z0-9]{10,30}$'
    order by reference.transaction_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.service_get_order_claim_contact_context(p_order_id uuid, p_claim_id uuid, p_actor_id uuid, p_session_id uuid, p_target text, p_command text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parties uuid[]:=private.contact_parties(p_order_id);c public.order_cancellation_requests;view jsonb;due jsonb;blocker text;begin
 if p_target is null or p_target not in('collection','reshipment') or p_command is null or p_command not in('change','reshipment') or(p_command='reshipment' and p_target<>'reshipment') then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 perform private.contact_require_identity(p_actor_id,p_session_id,'sales.manage',false,parties,true);
 c:=private.contact_lock_scope(p_order_id,p_claim_id,parties);perform private.contact_runtime();
 due:=private.contact_retention(p_claim_id,clock_timestamp());view:=private.contact_target(p_order_id,p_claim_id,p_target,true,due);
 blocker:=private.contact_blocker(c,p_target,p_command);
 if view->>'piiState'<>'available' then blocker:=coalesce(view->>'unavailableReason',view->>'piiState');end if;
 return jsonb_build_object('orderId',p_order_id,'claimId',p_claim_id,'target',p_target,'command',p_command,'claimType',c.claim_type,'claimRevision',c.claim_revision,'allowed',blocker is null,'blocker',blocker,'current',view);
end $function$

CREATE OR REPLACE FUNCTION public.service_get_order_transaction_receipt(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare receipt jsonb;version integer;begin
 select o.calculation_version,t.original_receipt into version,receipt from public.orders o
  left join private.order_goods_transactions t on t.order_id=o.id where o.id=p_order_id;
 if not found or version=1 then return null;end if;
 if receipt is null then raise check_violation using message='order_transaction_receipt_missing';end if;
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.service_get_payment_gateway_binding(p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare binding private.payment_provider_bindings;attempt public.payment_attempts;payment_key text;begin
 perform private.subscription_require_service();
 select * into attempt from public.payment_attempts where id=p_attempt_id;
 if not found then raise no_data_found using message='payment_attempt_not_found';end if;
 select * into binding from private.payment_provider_bindings where attempt_id=p_attempt_id;
 if not found then
  if exists(select 1 from private.goods_subscription_cycles where attempt_id=p_attempt_id) then
   raise object_not_in_prerequisite_state using message='billing_binding_missing';end if;
  return null;
 end if;
 if attempt.provider<>'toss' or attempt.purpose<>'order' or attempt.user_id<>binding.owner_id then
  raise object_not_in_prerequisite_state using message='billing_binding_invalid';end if;
 select p.payment_key into payment_key from public.payments p where p.id=attempt.payment_id;
 return jsonb_build_object('integration',binding.integration,'attemptId',binding.attempt_id,'ownerId',binding.owner_id,
  'profileId',binding.profile_id,'merchantId',binding.merchant_id,'environment',binding.environment,'credentialId',binding.credential_id,
  'cycleId',binding.cycle_id,'writeKeyVersion',binding.write_key_version,'firstDispatchedAt',binding.first_dispatched_at,'providerPaymentKey',payment_key);
end $function$

CREATE OR REPLACE FUNCTION public.service_get_subscription_availability(p_actor_id uuid, p_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.subscription_require_service();
 if p_actor_id is null or not exists(select 1 from public.profiles where id=p_actor_id) then raise insufficient_privilege using message='subscription_actor_required';end if;
 return jsonb_build_object('publicEnabled',(select public_enabled from private.goods_subscription_runtime where singleton),
  'profile',(select jsonb_build_object('profileId',p.id,'merchantId',p.merchant_id,'environment',p.environment,'adapter',p.adapter)
    from private.billing_profiles p where p.id=p_profile_id and p.enabled and (p.adapter<>'fake' or (select fake_local_enabled from private.goods_subscription_runtime where singleton))),
  'hasHistory',exists(select 1 from private.billing_credentials where owner_id=p_actor_id and state<>'revoked')
    or exists(select 1 from private.goods_subscription_plans where owner_id=p_actor_id));
end $function$

CREATE OR REPLACE FUNCTION public.service_grant_kakao_channel_friend_coupon(p_user_id uuid, p_channel_public_id text, p_coupon_code text, p_granted_via text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  existing private.kakao_channel_friend_rewards;
  held_id uuid;
  kst_today date := (statement_timestamp() at time zone 'Asia/Seoul')::date;
begin
  if p_user_id is null
    or p_channel_public_id is null or p_channel_public_id !~ '^_[A-Za-z0-9]{1,64}$'
    or p_coupon_code is null or p_coupon_code !~ '^[A-Z0-9][A-Z0-9-]{2,23}$'
    or p_granted_via is null or p_granted_via not in ('login', 'onboarding', 'webhook', 'settings') then
    raise invalid_parameter_value using message = 'invalid_kakao_channel_reward';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text, 0));
  if private.is_account_write_fenced(p_user_id) then
    return jsonb_build_object('status', 'unavailable', 'reason', 'customer_unavailable');
  end if;

  select * into existing from private.kakao_channel_friend_rewards r
    where r.user_id = p_user_id and r.channel_public_id = p_channel_public_id;
  if found then
    return jsonb_build_object('status', 'already_granted', 'userCouponId', existing.user_coupon_id);
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = p_user_id and p.role = 'user' and p.suspended_at is null and p.onboarded_at is not null
      and p.birth_date is not null and p.birth_date <= (kst_today - interval '14 years')::date
  ) then
    return jsonb_build_object('status', 'unavailable', 'reason', 'customer_unavailable');
  end if;

  begin
    held_id := private.issue_coupon_code(p_coupon_code, p_user_id, 'kakao_channel');
  exception when check_violation or insufficient_privilege or invalid_parameter_value then
    -- 쿠폰이 없거나 끝났거나 한도를 다 썼거나 지정 고객 발급 쿠폰이 아닌 경우다. 원장을 남기지 않아 운영자가 쿠폰을
    -- 고치면 다음 확인 때 발급된다.
    return jsonb_build_object('status', 'unavailable', 'reason', sqlerrm);
  end;

  insert into private.kakao_channel_friend_rewards (user_id, channel_public_id, coupon_code, user_coupon_id, granted_via)
    values (p_user_id, p_channel_public_id, upper(btrim(p_coupon_code)), held_id, p_granted_via);
  return jsonb_build_object('status', 'granted', 'userCouponId', held_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.service_inquiry_file_download(p_actor uuid, p_session uuid, p_file uuid, p_message uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare f private.inquiry_chat_files;staff boolean;begin
 perform private.inquiry_file_session(p_actor,p_session,false);staff:=private.has_operator_capability(p_actor,'cs.manage',false) and private.operator_mfa_service_session_ok(p_actor,p_session);
 select * into f from private.inquiry_chat_files where id=p_file and sha256 is not null and state in('verified','retired');
 if not found then raise insufficient_privilege;end if;
 if p_message is null then
  if not staff or not f.in_library or f.state<>'verified' then raise insufficient_privilege;end if;
 elsif not exists(select 1 from public.inquiry_messages m join public.inquiries i on i.id=m.inquiry_id
  where m.id=p_message and p_file=any(m.file_ids) and(staff or i.user_id=p_actor)) then raise insufficient_privilege;end if;
 return (private.inquiry_file_metadata(array[p_file])->0)||jsonb_build_object('path',f.path,'sha256',f.sha256);
end $function$

CREATE OR REPLACE FUNCTION public.service_inventory_order_claim_contact_data(p_subject_id uuid, p_actor_id uuid, p_session_id uuid, p_limit integer, p_after_claim_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare scopes jsonb:='[]';claim record;next_id uuid;n integer:=0;recorded timestamptz:=statement_timestamp();begin
 if p_subject_id is null or p_limit is null or p_limit not between 1 and 1000 then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 perform private.contact_require_identity(p_actor_id,p_session_id,'platform.manage',true,array[p_subject_id],false);
 for claim in select c.id from public.order_cancellation_requests c where c.claim_type in('return','exchange') and private.contact_subject(c.order_id)=p_subject_id
 and(p_after_claim_id is null or c.id>p_after_claim_id) order by c.id limit p_limit+1 loop
  n:=n+1;if n>p_limit then exit;end if;
  scopes:=scopes||jsonb_build_array(private.contact_retention_scope(claim.id,recorded));next_id:=claim.id;
 end loop;
 if n<=p_limit then next_id:=null;end if;
 return jsonb_build_object('subjectId',p_subject_id,'actorId',p_actor_id,'sessionId',p_session_id,'recordedAt',recorded,'scopes',scopes,'nextClaimId',next_id,
 'operatorReferenceCount',(select count(*) from private.order_claim_contact_operations where actor_id=p_subject_id));
end $function$

CREATE OR REPLACE FUNCTION public.service_issue_member_email_change(p_challenge_id uuid, p_user_id uuid, p_session_id uuid, p_email text, p_email_digest text, p_ip_digest text, p_code_digest text, p_ttl_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  now_at timestamptz;
  retry_after integer;
  last_at timestamptz;
  profile_suspended timestamptz;
  current_email text;
begin
  if p_challenge_id is null or p_user_id is null or p_session_id is null
    or p_email is null or char_length(p_email) not between 6 and 254 or p_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
    or p_email <> pg_catalog.lower(pg_catalog.btrim(p_email))
    or p_email_digest is null or p_email_digest !~ '^[A-Za-z0-9_-]{32,128}$'
    or (p_ip_digest is not null and p_ip_digest !~ '^[A-Za-z0-9_-]{32,128}$')
    or p_code_digest is null or p_code_digest !~ '^[A-Za-z0-9_-]{32,128}$'
    or p_ttl_seconds is null or p_ttl_seconds not between 60 and 1800 then
    raise invalid_parameter_value using message = 'invalid_member_email_change';
  end if;

  if private.is_account_write_fenced(p_user_id) then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-email:user:' || p_user_id::text, 0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-email:address:' || p_email_digest, 0));

  select p.suspended_at into profile_suspended from public.profiles p where p.id = p_user_id;
  if not found or profile_suspended is not null then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  -- 로그인 이메일이 쓸 수 있는 주소인 계정은 이 경로로 바꾸지 않는다(현재 주소 확인을 건너뛰는 길이 되지 않게).
  if not private.member_login_email_unusable(p_user_id) then
    return jsonb_build_object('ok', false, 'reason', 'not_eligible');
  end if;
  -- 요청한 세션 자체가 최근 로그인이어야 한다(온보딩은 막 로그인한 직후라 걸리지 않는다). 세션 id는 앱 서버가 서명 검증한
  -- JWT에서 읽어 넘긴다 — 이 RPC는 service_role 전용이다.
  if not exists (
    select 1 from auth.sessions s
    where s.id = p_session_id
      and s.user_id = p_user_id
      and s.created_at >= clock_timestamp() - interval '30 minutes'
      and (s.not_after is null or s.not_after > clock_timestamp())
  ) then
    return jsonb_build_object('ok', false, 'reason', 'reauthentication_required');
  end if;
  -- 새 주소도 쓸 수 있는 주소여야 한다.
  if p_email like '%@privaterelay.appleid.com' then
    return jsonb_build_object('ok', false, 'reason', 'email_unusable');
  end if;
  select pg_catalog.lower(u.email) into current_email from auth.users u where u.id = p_user_id;
  if current_email = p_email then
    return jsonb_build_object('ok', false, 'reason', 'same_email');
  end if;

  if exists (select 1 from private.member_email_change_challenges c where c.id = p_challenge_id) then
    raise unique_violation using message = 'member_email_change_replayed';
  end if;

  now_at := clock_timestamp();

  -- 같은 회원은 60초 안에 다시 보내지 않는다(주소 단위로 세지 않는다 — 다른 회원의 요청 여부가 드러나지 않게).
  select max(c.created_at) into last_at from private.member_email_change_challenges c
    where c.user_id = p_user_id and c.created_at > now_at - interval '60 seconds';
  if last_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'cooldown',
      'retryAfterSeconds', greatest(1, ceil(extract(epoch from (last_at + interval '60 seconds' - now_at)))::integer));
  end if;

  retry_after := coalesce(
    private.member_email_change_rate_limited('user', p_user_id::text, 5, 10),
    private.member_email_change_rate_limited('email', p_email_digest, 5, 10),
    private.member_email_change_rate_limited('ip', p_ip_digest, 10, 30)
  );
  if retry_after is not null then
    return jsonb_build_object('ok', false, 'reason', 'rate_limited', 'retryAfterSeconds', retry_after);
  end if;

  update private.member_email_change_challenges
    set status = 'superseded', resolved_at = now_at, email = null
    where user_id = p_user_id and status = 'pending';

  insert into private.member_email_change_challenges (
    id, user_id, email, email_digest, ip_digest, code_digest, status, attempts, created_at, expires_at
  ) values (
    p_challenge_id, p_user_id, p_email, p_email_digest, p_ip_digest, p_code_digest, 'pending', 0,
    now_at, now_at + make_interval(secs => p_ttl_seconds)
  );

  return jsonb_build_object('ok', true, 'expiresAt', now_at + make_interval(secs => p_ttl_seconds));
end;
$function$

CREATE OR REPLACE FUNCTION public.service_issue_member_phone_verification(p_challenge_id uuid, p_user_id uuid, p_phone_e164 text, p_phone_digest text, p_ip_digest text, p_code_digest text, p_ttl_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  now_at timestamptz;
  retry_after integer;
  last_at timestamptz;
  profile_suspended timestamptz;
begin
  if p_challenge_id is null or p_user_id is null
    or p_phone_e164 is null or p_phone_e164 !~ '^\+[1-9][0-9]{6,14}$'
    or p_phone_digest is null or p_phone_digest !~ '^[A-Za-z0-9_-]{32,128}$'
    or (p_ip_digest is not null and p_ip_digest !~ '^[A-Za-z0-9_-]{32,128}$')
    or p_code_digest is null or p_code_digest !~ '^[A-Za-z0-9_-]{32,128}$'
    or p_ttl_seconds is null or p_ttl_seconds not between 60 and 900 then
    raise invalid_parameter_value using message = 'invalid_member_phone_verification';
  end if;

  if private.is_account_write_fenced(p_user_id) then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-phone:user:' || p_user_id::text, 0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-phone:number:' || p_phone_digest, 0));

  select p.suspended_at into profile_suspended from public.profiles p where p.id = p_user_id;
  if not found or profile_suspended is not null then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  -- 동의·만 14세 확인 전에는 번호를 받지 않는다(요청 행도 남기지 않는다).
  if not private.member_phone_onboarding_ready(p_user_id) then
    return jsonb_build_object('ok', false, 'reason', 'onboarding_required');
  end if;

  if exists (select 1 from private.member_phone_verification_challenges c where c.id = p_challenge_id) then
    raise unique_violation using message = 'member_phone_verification_replayed';
  end if;

  now_at := clock_timestamp();

  -- 같은 회원이나 같은 번호로 60초 안에 다시 보내지 않는다.
  select max(c.created_at) into last_at from private.member_phone_verification_challenges c
    where (c.user_id = p_user_id or c.phone_digest = p_phone_digest) and c.created_at > now_at - interval '60 seconds';
  if last_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'cooldown',
      'retryAfterSeconds', greatest(1, ceil(extract(epoch from (last_at + interval '60 seconds' - now_at)))::integer));
  end if;

  retry_after := coalesce(
    private.member_phone_rate_limited('user', p_user_id::text, 5, 10),
    private.member_phone_rate_limited('phone', p_phone_digest, 5, 10),
    private.member_phone_rate_limited('ip', p_ip_digest, 10, 30)
  );
  if retry_after is not null then
    return jsonb_build_object('ok', false, 'reason', 'rate_limited', 'retryAfterSeconds', retry_after);
  end if;

  update private.member_phone_verification_challenges
    set status = 'superseded', resolved_at = now_at, phone_e164 = null
    where user_id = p_user_id and status = 'pending';

  insert into private.member_phone_verification_challenges (
    id, user_id, phone_e164, phone_digest, ip_digest, code_digest, status, attempts, created_at, expires_at
  ) values (
    p_challenge_id, p_user_id, p_phone_e164, p_phone_digest, p_ip_digest, p_code_digest, 'pending', 0,
    now_at, now_at + make_interval(secs => p_ttl_seconds)
  );

  return jsonb_build_object('ok', true, 'expiresAt', now_at + make_interval(secs => p_ttl_seconds));
end;
$function$

CREATE OR REPLACE FUNCTION public.service_mark_order_partial_cancellation_needs_review(p_id uuid, p_code text, p_actor_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare head private.order_partial_cancellations;
begin
  perform private.require_partial_cancellation_actor(p_actor_id);
  if p_code is null or p_code !~ '^[a-z0-9_]{1,64}$' then raise invalid_parameter_value using message = 'invalid_partial_cancel_reason'; end if;
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  perform 1 from public.orders where id = head.order_id for update;
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if head.state not in ('processing', 'needs_review') then return head.state; end if;
  update private.order_partial_cancellations set state = 'needs_review', last_error_code = p_code where id = p_id;
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor_id, 'admin.order.partial_cancellation_needs_review', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'code', p_code));
  return 'needs_review';
end $function$

CREATE OR REPLACE FUNCTION public.service_member_sms_recipient(p_user_id uuid, p_purpose text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  phone text;
  consent_agreed_at timestamptz;
begin
  if p_user_id is null or p_purpose is null or p_purpose not in ('advertising', 'transactional') then
    raise invalid_parameter_value using message = 'invalid_sms_recipient_request';
  end if;
  if private.is_account_write_fenced(p_user_id)
    or not exists (select 1 from public.profiles p where p.id = p_user_id and p.suspended_at is null) then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  select n.phone_e164 into phone from private.member_phone_numbers n where n.user_id = p_user_id;
  if phone is null then
    return jsonb_build_object('ok', false, 'reason', 'no_verified_phone');
  end if;
  if p_purpose = 'advertising' then
    select c.agreed_at into consent_agreed_at from private.customer_marketing_consents c
      where c.user_id = p_user_id and c.channel = 'sms' and c.agreed;
    if consent_agreed_at is null then
      return jsonb_build_object('ok', false, 'reason', 'consent_required');
    end if;
  end if;
  return jsonb_build_object('ok', true, 'phoneE164', phone, 'smsConsentAgreedAt', consent_agreed_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.service_observe_review_rating_daily()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare contract private.review_rating_observation_contracts; result jsonb; purge_before date; purge_time timestamptz;
begin
 if current_setting('role',true) is distinct from 'service_role' then raise insufficient_privilege using message='review_rating_service_required';end if;
 -- Global lock shared with the reviewed operations SQL; never wait across midnight.
 if not pg_try_advisory_xact_lock(1920168564,1) then
  return jsonb_build_object('status','busy','version',null,'asOf',null,'observedAt',null,'fingerprint',null);end if;
 select * into strict contract from private.review_rating_observation_contracts order by version desc limit 1;
 perform private.assert_review_rating_contract(contract.version);
 if contract.enabled then
  with instant as materialized (select clock_timestamp() observed_at),
  observed as materialized (
   select observed_at,(observed_at at time zone 'Asia/Seoul')::date observation_day,
    (observed_at at time zone 'Asia/Seoul')::time observation_time from instant
  ), needed as materialized (
   select o.* from observed o where o.observation_time>=time '00:05'
    and not exists(select 1 from private.review_rating_daily_observations d where d.version=contract.version and d.as_of=o.observation_day-1)
  ), measured as materialized (
   select n.*,m.* from needed n cross join lateral private.review_rating_snapshot(n.observed_at) m
  ), inserted as (
   insert into private.review_rating_daily_observations(version,as_of,observation_day,observed_at,six_month_from,
    average_rating,six_month_rating,eligible_product_count,rated_product_count,six_month_rated_product_count,review_count,six_month_review_count,fingerprint)
   select contract.version,m.observation_day-1,m.observation_day,m.observed_at,(m.observation_day::timestamp-interval '6 months')::date,
    m.average_rating,m.six_month_rating,m.eligible_product_count,m.rated_product_count,m.six_month_rated_product_count,m.review_count,m.six_month_review_count,
    encode(extensions.digest(convert_to(jsonb_build_object('version',contract.version,'asOf',m.observation_day-1,
     'observedAt',m.observed_at,'sixMonthFrom',(m.observation_day::timestamp-interval '6 months')::date,
     'averageRating',m.average_rating,'sixMonthRating',m.six_month_rating,'eligibleProductCount',m.eligible_product_count,
     'ratedProductCount',m.rated_product_count,'sixMonthRatedProductCount',m.six_month_rated_product_count,
     'reviewCount',m.review_count,'sixMonthReviewCount',m.six_month_review_count)::text,'UTF8'),'sha256'),'hex') from measured m
   returning *
  ) select case when i.version is not null then jsonb_build_object('status','recorded','version',i.version,'asOf',i.as_of,'observedAt',i.observed_at,'fingerprint',i.fingerprint)
   when d.version is not null then jsonb_build_object('status','already_recorded','version',d.version,'asOf',d.as_of,'observedAt',d.observed_at,'fingerprint',d.fingerprint)
   else jsonb_build_object('status','too_early','version',contract.version,'asOf',null,'observedAt',null,'fingerprint',null) end into result
  from observed o left join inserted i on true left join private.review_rating_daily_observations d on d.version=contract.version and d.as_of=o.observation_day-1;
  if result->>'status'='recorded' then
   update private.review_rating_observation_contracts set last_success_at=(result->>'observedAt')::timestamptz where version=contract.version;
  end if;
 else
  result:=jsonb_build_object('status','disabled','version',contract.version,'asOf',null,'observedAt',null,'fingerprint',null);
 end if;
 -- Retention continues while collection is stopped. Boundary metadata records a
 -- completed DELETE range, including empty ranges, not proof of prior collection.
 purge_time:=clock_timestamp();
 purge_before:=((purge_time at time zone 'Asia/Seoul')::date::timestamp-interval '13 months')::date;
 delete from private.review_rating_daily_observations where as_of<purge_before;
 update private.review_rating_observation_contracts set purged_before_as_of=greatest(purged_before_as_of,purge_before),last_purged_at=purge_time
  where collection_started_at is not null;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.service_prepare_billing_refund(p_attempt_id uuid, p_idempotency_key text, p_amount bigint, p_request_hash text, p_key_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare binding private.payment_provider_bindings;attempt public.payment_attempts;operation private.billing_refund_operations;begin
 perform private.subscription_require_service();
 if p_idempotency_key is null or char_length(p_idempotency_key) not between 1 and 300 or p_idempotency_key!~'^[!-~]+$'
  or p_request_hash is null or p_request_hash!~'^[0-9a-f]{64}$' or p_key_version is null or p_key_version!~'^[A-Za-z0-9_-]{1,64}$' then
  raise invalid_parameter_value using message='invalid_billing_refund';end if;
 perform pg_advisory_xact_lock(hashtextextended('billing-refund:'||p_attempt_id::text,0));
 select * into binding from private.payment_provider_bindings where attempt_id=p_attempt_id;
 select * into attempt from public.payment_attempts where id=p_attempt_id;
 if binding.attempt_id is null or binding.first_dispatched_at is null or attempt.id is null or attempt.amount is distinct from p_amount
  or attempt.provider<>'toss' or attempt.purpose<>'order' or attempt.payment_id is null then
  raise invalid_parameter_value using message='invalid_billing_refund';end if;
 select * into operation from private.billing_refund_operations where attempt_id=p_attempt_id for update;
 if found then
  if operation.idempotency_key<>p_idempotency_key or operation.amount<>p_amount or operation.request_hash<>p_request_hash then
   raise sqlstate 'PT409' using message='billing_refund_conflict';end if;
 else
  insert into private.billing_refund_operations(attempt_id,idempotency_key,amount,request_hash,write_key_version)
   values(p_attempt_id,p_idempotency_key,p_amount,p_request_hash,p_key_version) returning * into operation;
 end if;
 return jsonb_build_object('writeKeyVersion',operation.write_key_version,'firstDispatchedAt',operation.first_dispatched_at);
end $function$

CREATE OR REPLACE FUNCTION public.service_prepare_billing_registration(p_actor_id uuid, p_session_id uuid, p_operation_id uuid, p_profile_id uuid, p_nonce_digest text, p_nonce_envelope jsonb, p_write_key_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare entry private.billing_enrollments;customer_id uuid;profile private.billing_profiles;at_time timestamptz;
begin
 perform private.subscription_require_service();perform private.subscription_lock_actor(p_actor_id,false);
 if p_operation_id is null or p_session_id is null or p_profile_id is null or not exists(select 1 from auth.sessions where id=p_session_id and user_id=p_actor_id)
  or p_nonce_digest is null or p_nonce_digest!~'^[0-9a-f]{64}$' or not private.subscription_valid_envelope(p_nonce_envelope)
  or p_write_key_version is null or p_write_key_version!~'^[A-Za-z0-9_-]{1,64}$' then
  raise invalid_parameter_value using message='invalid_billing_registration';end if;
 select * into entry from private.billing_enrollments where id=p_operation_id for update;
 if found then
  if entry.owner_id<>p_actor_id or entry.session_id<>p_session_id or entry.profile_id<>p_profile_id then
   raise insufficient_privilege using message='billing_registration_conflict';end if;
  return private.billing_registration_summary(entry.id,true);
 end if;
 perform private.subscription_lock_actor(p_actor_id,true);
 if not (select public_enabled from private.goods_subscription_runtime where singleton) then
  raise object_not_in_prerequisite_state using message='subscriptions_unavailable';end if;
 select * into profile from private.billing_profiles where id=p_profile_id and enabled for share;
 if not found or (profile.adapter='fake' and not(select fake_local_enabled from private.goods_subscription_runtime where singleton)) then
  raise object_not_in_prerequisite_state using message='billing_profile_unavailable';end if;
 if (select count(*) from private.billing_enrollments where owner_id=p_actor_id and state in('prepared','processing','unknown','needs_review')
  and created_at>clock_timestamp()-interval '24 hours')>=10 then raise check_violation using message='billing_registration_limit';end if;
 insert into private.billing_customers(user_id,profile_id) values(p_actor_id,p_profile_id)
 on conflict(user_id,profile_id) do update set profile_id=excluded.profile_id returning id into customer_id;
 at_time:=clock_timestamp();
 insert into private.billing_enrollments(id,owner_id,session_id,profile_id,customer_id,credential_id,nonce_digest,nonce_envelope,
  write_key_version,idempotency_key,created_at,updated_at,expires_at)
 values(p_operation_id,p_actor_id,p_session_id,p_profile_id,customer_id,gen_random_uuid(),p_nonce_digest,p_nonce_envelope,
  p_write_key_version,'billing-register:'||p_operation_id::text,at_time,at_time,at_time+interval '10 minutes');
 return private.billing_registration_summary(p_operation_id,true);
end $function$

CREATE OR REPLACE FUNCTION public.service_prepare_digital_asset(p_actor uuid, p_session uuid, p_id uuid, p_name text, p_mime text, p_size integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare asset private.goods_digital_assets;extension text;begin
 perform private.digital_operator_session(p_actor,p_session);
 extension:=case p_mime when 'application/pdf' then 'pdf' when 'application/zip' then 'zip' when 'image/png' then 'png' when 'image/jpeg' then 'jpg' when 'audio/mpeg' then 'mp3' when 'video/mp4' then 'mp4' when 'text/plain' then 'txt' end;
 if p_id is null or p_size is null or p_size not between 1 and 52428800 or extension is null or p_name is null or char_length(btrim(p_name)) not between 1 and 160 or p_name~'[[:cntrl:]/\\]' then raise invalid_parameter_value;end if;
 perform pg_advisory_xact_lock(hashtextextended('digital-upload:'||p_actor::text,0));
 select * into asset from private.goods_digital_assets where id=p_id for update;
 if found then
  if asset.actor_id is distinct from p_actor or asset.session_id<>p_session or asset.filename<>btrim(p_name) or asset.mime_type<>p_mime or asset.size_bytes<>p_size then raise sqlstate 'PT409';end if;
  if asset.state not in('pending','verified') or asset.state='pending' and asset.expires_at<=clock_timestamp() then raise check_violation using message='digital_upload_expired';end if;
 else
  if (select count(*) from private.goods_digital_assets where actor_id=p_actor and created_at>clock_timestamp()-interval '1 minute')>=10
   or (select count(*) from private.goods_digital_assets where actor_id=p_actor and state='pending' and expires_at>clock_timestamp())>=10 then raise check_violation using message='digital_upload_budget';end if;
  insert into private.goods_digital_assets(id,actor_id,session_id,filename,mime_type,size_bytes,path,expires_at)
   values(p_id,p_actor,p_session,btrim(p_name),p_mime,p_size,p_actor::text||'/'||p_id::text||'.'||extension,clock_timestamp()+interval '30 minutes') returning * into asset;
 end if;
 return jsonb_build_object('id',asset.id,'path',asset.path,'state',asset.state,'name',asset.filename,'mimeType',asset.mime_type,'size',asset.size_bytes,'sha256',asset.sha256);
end $function$

CREATE OR REPLACE FUNCTION public.service_prepare_goods_media_upload(p_actor_id uuid, p_id uuid, p_kind text, p_source_size integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claimed private.goods_media_assets%rowtype;
begin
 perform private.require_actor_operator_capability(p_actor_id,'catalog.manage');
 if p_id is null or p_kind is null or p_kind not in('video','shortclip') or p_source_size is null or p_source_size not between 1 and 52428800 then raise check_violation using message='invalid_goods_media_upload';end if;
 perform pg_advisory_xact_lock(hashtextextended('goods-media-actor:'||p_actor_id::text,0));
 select * into claimed from private.goods_media_assets where id=p_id for update;
 if found then
  if claimed.actor_id is distinct from p_actor_id or claimed.kind<>p_kind or claimed.source_size<>p_source_size then raise unique_violation using message='goods_media_claim_conflict';end if;
  if claimed.status<>'pending' or claimed.expires_at<=clock_timestamp() then raise check_violation using message='goods_media_claim_closed';end if;
  return jsonb_build_object('id',claimed.id,'path',claimed.path,'kind',claimed.kind,'sourceSize',claimed.source_size,'status',claimed.status);
 end if;
 if (select count(*) from private.goods_media_assets where actor_id=p_actor_id and created_at>clock_timestamp()-interval '1 minute')>=4
  or (select count(*) from private.goods_media_assets where actor_id=p_actor_id and status in('pending','processing') and expires_at>clock_timestamp())>=4
  or (select count(*) from private.goods_media_assets where actor_id=p_actor_id and status='verified' and expires_at>clock_timestamp())>=12 then raise check_violation using message='goods_media_upload_budget';end if;
 insert into private.goods_media_assets(id,actor_id,kind,path,source_size,expires_at) values(p_id,p_actor_id,p_kind,p_kind||'/'||p_id::text||'.mp4',p_source_size,clock_timestamp()+interval '15 minutes') returning * into claimed;
 return jsonb_build_object('id',claimed.id,'path',claimed.path,'kind',claimed.kind,'sourceSize',claimed.source_size,'status',claimed.status);
end $function$

CREATE OR REPLACE FUNCTION public.service_prepare_goods_subscription_work(p_actor_id uuid, p_cycle_id uuid, p_claim_token uuid, p_claim_fence bigint, p_profile_id uuid, p_write_key_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<subscription_work>>
declare cycle private.goods_subscription_cycles;plan private.goods_subscription_plans;terms private.goods_subscription_terms;credential private.billing_credentials;
 profile private.billing_profiles;attempt public.payment_attempts;quoted jsonb;current_terms jsonb;attempt_data jsonb;claim_data jsonb;reason text;
 order_id uuid;enabled boolean;at_time timestamptz;
begin
 perform private.subscription_require_service();perform private.lock_goods_transaction_source(p_actor_id,private.subscription_source(p_cycle_id,'work'));
 select * into cycle from private.goods_subscription_cycles where id=p_cycle_id and owner_id=p_actor_id;
 if not found then raise no_data_found using message='subscription_cycle_not_found';end if;
 select * into plan from private.goods_subscription_plans where id=cycle.plan_id and owner_id=p_actor_id for update;
 select * into cycle from private.goods_subscription_cycles where id=p_cycle_id for update;
 if p_claim_token is null or p_claim_fence is null or p_claim_fence<1 or cycle.claim_token is null or cycle.lease_until is null
  or cycle.claim_token is distinct from p_claim_token or cycle.claim_fence is distinct from p_claim_fence or cycle.lease_until<=clock_timestamp() then
  raise sqlstate 'PT409' using message='subscription_claim_stale';end if;
 if cycle.dispatched_at is not null then
  claim_data:=public.claim_goods_payment_reconciliation(cycle.attempt_id,p_claim_token,'subscription_'||replace(cycle.id::text,'-',''));
  if claim_data->>'claim_status'='terminal' then
   perform private.subscription_sync_cycle_outcome(cycle.id,(claim_data->>'outcome')::public.payment_attempt_state);
   return jsonb_build_object('kind','terminal','outcome',claim_data->>'outcome','orderId',
    case when claim_data->>'outcome'='approved' and exists(select 1 from public.orders where id=cycle.order_id and user_id=p_actor_id and status not in('pending','canceled')) then cycle.order_id end);
  elsif claim_data->>'claim_status'<>'claimed' then
   update private.goods_subscription_cycles set claim_token=null,lease_until=null,next_check_at=clock_timestamp()+interval '5 minutes' where id=cycle.id;
   return jsonb_build_object('kind','wait');
  end if;
  return jsonb_build_object('kind','inspect','attempt',claim_data->'attempt','binding',public.service_get_payment_gateway_binding(cycle.attempt_id));
 end if;
 if plan.state not in('active','awaiting_first_payment') then
  perform private.subscription_stop_cycle(cycle.id,'plan_stopped',plan.state='canceled');return jsonb_build_object('kind','stopped');end if;
 if cycle.state not in('ready','prepared') or cycle.scheduled_at>clock_timestamp() then raise object_not_in_prerequisite_state using message='subscription_cycle_not_due';end if;
 reason:=null;
 begin perform private.subscription_lock_actor(p_actor_id,true);exception when insufficient_privilege then reason:='account_unavailable';end;
 if cycle.scheduled_at<clock_timestamp()-interval '24 hours' then reason:='schedule_missed';end if;
 select * into terms from private.goods_subscription_terms where id=cycle.terms_id;
 if cycle.terms_id<>plan.current_terms_id or terms.policy_terms_version<>(select terms_version from private.goods_subscription_runtime where singleton) then reason:='terms_changed';end if;
 select * into credential from private.billing_credentials where id=plan.credential_id and owner_id=p_actor_id for update;
 if not found or credential.state<>'active' or credential.envelope is null then reason:='card_unavailable';end if;
 if reason is not null then
  perform private.subscription_stop_cycle(cycle.id,reason);
  update private.goods_subscription_plans set state=case when reason='terms_changed' then 'needs_confirmation' else 'paused' end,
   pause_reason=reason,next_run_at=null,revision=revision+1,updated_at=clock_timestamp() where id=plan.id;
  return jsonb_build_object('kind','stopped','reason',reason);
 end if;
 select * into profile from private.billing_profiles where id=credential.profile_id for share;
 if profile.id is distinct from p_profile_id or not profile.enabled or p_write_key_version is null or p_write_key_version!~'^[A-Za-z0-9_-]{1,64}$' then
  raise object_not_in_prerequisite_state using message='subscription_profile_unavailable';end if;
 if cycle.order_id is not null then
  perform 1 from public.orders where id=cycle.order_id for update;
  if not exists(select 1 from public.orders where id=cycle.order_id and status='pending' and expires_at>clock_timestamp()) then
   perform private.subscription_stop_cycle(cycle.id,'order_unavailable');
   update private.goods_subscription_plans set state='paused',pause_reason='payment_failed',next_run_at=null,revision=revision+1,updated_at=clock_timestamp() where id=plan.id;
   return jsonb_build_object('kind','stopped','reason','payment_failed');end if;
  perform private.lock_goods_transaction_catalog(p_actor_id,terms.selection,null);
 else
  quoted:=private.quote_goods_transaction(p_actor_id,private.subscription_source(cycle.id,terms.id::text),terms.selection,terms.address,terms.delivery_choices,null,0);
  if quoted->>'state'<>'quoted' then reason:=case when quoted#>>'{issues,0,code}' in('shipping_unresolved','collect_not_ready','delivery_choice_required') then 'delivery_unavailable' else 'goods_unavailable' end;
  else
   current_terms:=private.subscription_renewal_terms(quoted->'display',terms.selection,terms.schedule,terms.address_revision);
   if current_terms is distinct from terms.renewal_terms then reason:='terms_changed';end if;
  end if;
 end if;
 if not private.subscription_selection_allowed(terms.selection,terms.schedule) then reason:='goods_unavailable';end if;
 if reason is not null then
  perform private.subscription_stop_cycle(cycle.id,reason);
  update private.goods_subscription_plans set state=case when reason='terms_changed' then 'needs_confirmation' else 'paused' end,
   pause_reason=reason,next_run_at=null,revision=revision+1,updated_at=clock_timestamp() where id=plan.id;
  return jsonb_build_object('kind','stopped','reason',reason);
 end if;
 select charge_enabled into enabled from private.goods_subscription_runtime where singleton for share;
 if not enabled then
  update private.goods_subscription_cycles set claim_token=null,lease_until=null where id=cycle.id;return jsonb_build_object('kind','gate_closed');end if;
 if cycle.order_id is null then
  order_id:=private.place_goods_transaction(p_actor_id,private.subscription_source(cycle.id,terms.id::text),terms.selection,terms.address,(quoted->>'quoteId')::uuid,cycle.id,'card');
  update private.goods_subscription_cycles set order_id=subscription_work.order_id,quote_id=(quoted->>'quoteId')::uuid,state='prepared',revision=revision+1 where id=cycle.id;
 else order_id:=cycle.order_id;end if;
 attempt_data:=public.prepare_goods_payment_attempt(p_actor_id,order_id,'toss');
 select * into attempt from public.payment_attempts where id=(attempt_data->>'id')::uuid for update;
 if attempt.state<>'prepared' or attempt.user_id<>p_actor_id then raise object_not_in_prerequisite_state using message='subscription_attempt_unavailable';end if;
 at_time:=clock_timestamp();
 insert into private.payment_provider_bindings(attempt_id,integration,owner_id,profile_id,merchant_id,environment,credential_id,cycle_id,write_key_version,first_dispatched_at)
  values(attempt.id,'toss_billing',p_actor_id,profile.id,profile.merchant_id,profile.environment,credential.id,cycle.id,p_write_key_version,at_time);
 update public.payment_attempts set state='confirming',claim_token=p_claim_token,claim_expires_at=at_time+interval '10 minutes' where id=attempt.id;
 update private.goods_subscription_cycles set attempt_id=attempt.id,state='dispatching',dispatched_at=at_time,revision=revision+1,updated_at=at_time where id=cycle.id;
 return jsonb_build_object('kind','charge','attempt',attempt_data,'binding',public.service_get_payment_gateway_binding(attempt.id),
  'customerKey',(select customer_key from private.billing_customers where id=credential.customer_id),'envelope',credential.envelope);
end $function$

CREATE OR REPLACE FUNCTION public.service_prepare_inquiry_file(p_actor uuid, p_session uuid, p_id uuid, p_name text, p_mime text, p_size integer, p_library boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare f private.inquiry_chat_files;extension text;begin
 perform private.inquiry_file_session(p_actor,p_session,true);extension:=private.inquiry_file_extension(p_mime);
 if p_id is null or p_library is null or p_size is null or p_size not between 1 and 20971520 or extension is null
 or p_name is null or char_length(btrim(p_name)) not between 1 and 160 or p_name~'[[:cntrl:]/\\]' then raise invalid_parameter_value;end if;
 perform pg_advisory_xact_lock(hashtextextended('inquiry-file-library',0));
