CREATE OR REPLACE FUNCTION public.service_read_order_claim_contact_history(p_order_id uuid, p_claim_id uuid, p_actor_id uuid, p_session_id uuid, p_viewer_kind text, p_limit integer, p_cursor jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parties uuid[]:=private.contact_parties(p_order_id);c public.order_cancellation_requests;kind text;access boolean;due jsonb;entries jsonb:='[]';entry jsonb;op private.order_claim_contact_operations;
 dest private.order_claim_reshipment_destinations;dest_view jsonb;next_cursor jsonb;cursor_at timestamptz;cursor_id uuid;n integer:=0;pii_state text;reason text;begin
 if p_viewer_kind is null or p_viewer_kind not in('operator','customer') or p_limit is null or p_limit not between 1 and 20 then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 if p_cursor is not null and p_cursor<>'null'::jsonb then
  if not private.contact_keys(p_cursor,array['recordedAt','operationId']) or not private.contact_uuid(p_cursor->'operationId') or jsonb_typeof(p_cursor->'recordedAt') is distinct from 'string' then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
  begin cursor_at:=(p_cursor->>'recordedAt')::timestamptz;cursor_id:=(p_cursor->>'operationId')::uuid;exception when others then raise invalid_parameter_value using message='invalid_claim_contact_request';end;
  if not isfinite(cursor_at) then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 end if;
 perform private.contact_require_identity(p_actor_id,p_session_id,case when p_viewer_kind='operator' then 'sales.manage' end,false,parties,true);
 c:=private.contact_lock_scope(p_order_id,p_claim_id,parties);
 if p_viewer_kind='operator' then kind:='operator';
 else
  select case when g.recipient_id=p_actor_id then 'gift_recipient' when g.sender_id=p_actor_id then 'gift_sender' when g.id is null and o.user_id=p_actor_id then 'buyer' end into kind
  from public.orders o left join private.gift_intents g on g.order_id=o.id where o.id=p_order_id;
  if kind is null then raise no_data_found using message='claim_not_found';end if;
 end if;
 access:=kind<>'gift_sender';perform private.contact_runtime();due:=private.contact_retention(p_claim_id,clock_timestamp());
 for op in select id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,result_claim_revision,
 state,changed_fields,null::text,null::text,case when access and due->>'state' not in('due','purged') and purged_at is null then history else null end,created_at,purged_at
 from private.order_claim_contact_operations where claim_id=p_claim_id and order_id=p_order_id and state='saved' and command='change'
 and(cursor_at is null or(created_at,id)<(cursor_at,cursor_id)) order by created_at desc,id desc limit p_limit+1 loop
  n:=n+1;if n>p_limit then exit;end if;
  pii_state:=case when not access then 'restricted' when op.purged_at is not null then 'purged' when due->>'state'='due' then 'unavailable' when op.history is null then 'unavailable' else 'available' end;
  reason:=case when pii_state='unavailable' then case when due->>'state'='due' then 'retention_due' else 'source_unavailable' end end;
  entry:=jsonb_build_object('operationId',op.id,'target',op.target,'changedFields',to_jsonb(op.changed_fields),'recordedAt',op.created_at,'resultClaimRevision',op.result_claim_revision,
   'piiState',pii_state,'actorId',case when kind='operator' then op.actor_id end,'unavailableReason',reason,'ciphertext',case when pii_state='available' then
   (op.history||jsonb_build_object('recordId',op.id,'agreement',case when kind='operator' then op.history->'agreement' else 'null'::jsonb end)) else null end);
  entries:=entries||jsonb_build_array(entry);next_cursor:=jsonb_build_object('recordedAt',op.created_at,'operationId',op.id);
 end loop;
 if n<=p_limit then next_cursor:=null;end if;
 select claim_id,order_id,operation_id,confirmed_claim_revision,case when access and due->>'state' not in('due','purged') and purged_at is null then destination else null end,confirmed_at,purged_at
 into dest from private.order_claim_reshipment_destinations where claim_id=p_claim_id order by confirmed_at desc,operation_id desc limit 1;
 pii_state:=case when c.claim_type<>'exchange' or(dest.claim_id is null and c.reshipped_at is null) then 'not_applicable'
 when not access then 'restricted' when dest.purged_at is not null or due->>'state'='purged' then 'purged'
 when due->>'state'='due' then 'unavailable' when dest.destination is null then 'unavailable' else 'available' end;
 dest_view:=jsonb_build_object('source',case when dest.claim_id is not null then 'v2_confirmed' when c.reshipped_at is not null then 'legacy_unconfirmed' else 'none' end,
 'operationId',dest.operation_id,'recordedAt',dest.confirmed_at,'piiState',pii_state,'destination',case when pii_state='available' then dest.destination else null end,
 'unavailableReason',case when pii_state='unavailable' then case when due->>'state'='due' then 'retention_due' else 'source_unavailable' end end);
 return jsonb_build_object('viewerId',p_actor_id,'sessionId',p_session_id,'orderId',p_order_id,'claimId',p_claim_id,'viewerKind',kind,'piiAccess',access,
 'current',jsonb_build_object('collection',private.contact_target(p_order_id,p_claim_id,'collection',access,due),'reshipment',private.contact_target(p_order_id,p_claim_id,'reshipment',access,due)),
 'entries',entries,'nextCursor',next_cursor,'reshipmentDestination',dest_view);
end $function$

CREATE OR REPLACE FUNCTION public.service_read_order_claim_contact_operation(p_order_id uuid, p_claim_id uuid, p_actor_id uuid, p_session_id uuid, p_operation_id uuid, p_command text, p_target text, p_expected_claim_type text, p_expected_claim_revision integer, p_seal_if_absent boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parties uuid[]:=private.contact_parties(p_order_id);op private.order_claim_contact_operations;c public.order_cancellation_requests;begin
 perform private.contact_operation_input(p_operation_id,p_command,p_target,p_expected_claim_type,p_expected_claim_revision);
 if p_seal_if_absent is null then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 perform private.contact_require_identity(p_actor_id,p_session_id,'sales.manage',false,parties,false);
 perform pg_advisory_xact_lock(hashtextextended('claim-contact-operation:'||p_operation_id,0));
 -- Scope locking validates current relationship but never fetches PII.
 c:=private.contact_lock_scope(p_order_id,p_claim_id,parties);
 select id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,result_claim_revision,
 state,changed_fields,null::text,hmac_key_version,null::jsonb,created_at,purged_at into op
 from private.order_claim_contact_operations where id=p_operation_id;
 if found then perform private.contact_operation_scope(op,p_order_id,p_claim_id,p_actor_id,p_session_id,p_command,p_target,p_expected_claim_type,p_expected_claim_revision);
 elsif p_seal_if_absent then
  insert into private.order_claim_contact_operations(id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,state)
  values(p_operation_id,p_actor_id,p_session_id,p_order_id,p_claim_id,p_command,p_target,p_expected_claim_type,p_expected_claim_revision,'sealed') returning * into op;
 end if;
 return jsonb_build_object('receipt',case when op.id is null then null else private.contact_operation_receipt(op) end,'hmacKeyVersion',op.hmac_key_version);
end $function$

CREATE OR REPLACE FUNCTION public.service_record_delivery_tracking(p_provider text, p_results jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare settings private.delivery_tracking_settings; result jsonb; event jsonb; carrier_value text; tracking_value text;
  outcome_value text; error_value text; occurred timestamptz; valid boolean; payload_value jsonb;
  recorded integer := 0; duplicates integer := 0; ignored integer := 0; invalid integer := 0;
begin
  select * into settings from private.delivery_tracking_settings where singleton;
  if not found or not settings.auto_delivery_enabled then raise check_violation using message = 'delivery_tracking_disabled'; end if;
  if p_provider is distinct from settings.provider then raise check_violation using message = 'delivery_tracking_provider_mismatch'; end if;
  if jsonb_typeof(p_results) is distinct from 'array' or jsonb_array_length(p_results) > 200 then
    raise invalid_parameter_value using message = 'invalid_delivery_tracking_results'; end if;
  for result in select value from jsonb_array_elements(p_results) loop
    if jsonb_typeof(result) is distinct from 'object' or jsonb_typeof(result->'carrier') is distinct from 'string'
      or jsonb_typeof(result->'trackingNumber') is distinct from 'string' then invalid := invalid + 1; continue; end if;
    carrier_value := result->>'carrier';
    tracking_value := private.normalize_tracking_number(result->>'trackingNumber');
    if tracking_value is null or tracking_value !~ '^[A-Z0-9]{8,30}$' then invalid := invalid + 1; continue; end if;
    if not exists(select 1 from public.order_shipments s where s.carrier = carrier_value and s.tracking_number = tracking_value and s.delivery_method = 'parcel')
      and not exists(select 1 from public.order_shipment_extra_trackings x where x.carrier = carrier_value and x.tracking_number = tracking_value) then
      ignored := ignored + 1; continue;
    end if;
    outcome_value := result->>'outcome';
    error_value := null;
    valid := coalesce(outcome_value, '') in ('ok','not_found','error')
      and (not (result ? 'events') or (jsonb_typeof(result->'events') = 'array' and jsonb_array_length(result->'events') <= 100));
    if valid and outcome_value = 'error' then
      error_value := coalesce(nullif(result->>'errorCode', ''), 'upstream_error');
      if error_value !~ '^[a-z0-9_]{1,64}$' then error_value := 'upstream_error'; end if;
    end if;
    if valid then
      for event in select value from jsonb_array_elements(coalesce(result->'events', '[]'::jsonb)) loop
        if jsonb_typeof(event) is distinct from 'object' or jsonb_typeof(event->'eventKey') is distinct from 'string'
          or char_length(event->>'eventKey') not between 1 and 200
          or coalesce(event->>'status', '') not in ('accepted','in_transit','out_for_delivery','delivered','exception','returned','unknown')
          or jsonb_typeof(event->'occurredAt') is distinct from 'string' or jsonb_typeof(event->'raw') is distinct from 'object' then
          valid := false; exit;
        end if;
        begin occurred := (event->>'occurredAt')::timestamptz;
        exception when others then valid := false;
        end;
        -- 추적 서비스 시계가 하루 넘게 앞선 시각은 받지 않는다(배송완료 시각은 지금을 넘지 않게 따로 자른다).
        if not valid or occurred > now() + interval '1 day' then valid := false; exit; end if;
      end loop;
    end if;
    if not valid then
      invalid := invalid + 1; outcome_value := 'error'; error_value := 'invalid_event';
    else
      for event in select value from jsonb_array_elements(coalesce(result->'events', '[]'::jsonb)) loop
        payload_value := case when octet_length((event->'raw')::text) <= 8192 then event->'raw' else '{"truncated": true}'::jsonb end;
        insert into private.shipment_tracking_events(provider, carrier, tracking_number, event_key, status, occurred_at, description, location, payload)
        values (p_provider, carrier_value, tracking_value, event->>'eventKey', event->>'status', (event->>'occurredAt')::timestamptz,
          nullif(left(event->>'description', 200), ''), nullif(left(event->>'location', 100), ''), payload_value)
        on conflict (provider, carrier, tracking_number, event_key) do nothing;
        if found then recorded := recorded + 1; else duplicates := duplicates + 1; end if;
      end loop;
    end if;
    insert into private.shipment_tracking_polls(carrier, tracking_number, last_polled_at, last_outcome, last_error_code, consecutive_failures)
    values (carrier_value, tracking_value, now(), outcome_value, error_value, case when outcome_value = 'error' then 1 else 0 end)
    on conflict (carrier, tracking_number) do update set last_polled_at = excluded.last_polled_at, last_outcome = excluded.last_outcome,
      last_error_code = excluded.last_error_code,
      consecutive_failures = case when excluded.last_outcome = 'error' then private.shipment_tracking_polls.consecutive_failures + 1 else 0 end;
  end loop;
  return jsonb_build_object('recorded', recorded, 'duplicates', duplicates, 'ignored', ignored, 'invalid', invalid);
end $function$

CREATE OR REPLACE FUNCTION public.service_record_digital_download(p_actor uuid, p_session uuid, p_item uuid, p_asset uuid, p_operation uuid, p_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare context jsonb;prior private.order_digital_downloads;shipment public.order_shipments;at_value timestamptz;begin
 if p_operation is null or p_sha256 is null or p_sha256!~'^[0-9a-f]{64}$' then raise invalid_parameter_value;end if;
 context:=private.digital_download_context(p_actor,p_session,p_item,p_asset);
 if context->>'sha256'<>p_sha256 then raise check_violation using message='digital_content_changed';end if;
 select * into prior from private.order_digital_downloads where id=p_operation;
 if found then
  if prior.actor_id is distinct from p_actor or prior.session_id<>p_session or prior.order_item_id<>p_item or prior.asset_id<>p_asset or prior.sha256<>p_sha256 then raise sqlstate 'PT409';end if;
  return jsonb_build_object('operationId',p_operation,'itemId',p_item,'assetId',p_asset,'recordedAt',prior.created_at);
 end if;
 at_value:=clock_timestamp();
 insert into private.order_digital_downloads(id,order_id,order_item_id,asset_id,actor_id,session_id,sha256,created_at)
  values(p_operation,(context->>'orderId')::uuid,p_item,p_asset,p_actor,p_session,p_sha256,at_value);
 select s.* into shipment from public.order_shipments s join public.order_shipment_items i on i.shipment_id=s.id where i.order_item_id=p_item;
 if shipment.delivery_method<>'digital' then raise check_violation using message='digital_shipment_mismatch';end if;
 if shipment.status='ready' and not exists(select 1 from public.order_shipment_items i where i.shipment_id=shipment.id
  and not exists(select 1 from private.order_digital_downloads d where d.order_item_id=i.order_item_id and d.order_id=shipment.order_id)) then
  insert into private.shipment_delivery_operations(id,shipment_id,kind,actor_id,request_digest,evidence)
   values(p_operation,shipment.id,'digital_access',p_actor,extensions.digest(context::text,'sha256'),jsonb_build_object('downloadId',p_operation,'occurredAt',at_value));
  update public.order_shipments set status='delivered',shipped_at=at_value,delivered_at=at_value,delivery_event_id=p_operation,updated_at=at_value where id=shipment.id;
 end if;
 return jsonb_build_object('operationId',p_operation,'itemId',p_item,'assetId',p_asset,'recordedAt',at_value);
end $function$

CREATE OR REPLACE FUNCTION public.service_record_encrypted_list_export(p_actor_id uuid, p_screen text, p_filters jsonb, p_row_count integer, p_record_count integer, p_file_sha256 text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=p_actor_id; recorded_id uuid;
begin
 perform private.require_actor_operator_capability(actor,case when p_screen='orders' then 'sales.read' else 'sales.manage' end,coalesce(p_screen='refund-transfers',false));
 if actor is null then raise insufficient_privilege using message='operator_capability_required';end if;
 if p_screen is null or p_screen not in('orders','unpaid','dispatch','shipping','claims-cancels','claims-returns','claims-exchanges','refund-transfers') then
  raise invalid_parameter_value using message='invalid_list_export_screen';end if;
 if p_filters is null or jsonb_typeof(p_filters)<>'object' or octet_length(p_filters::text)>2000
  or exists(select 1 from jsonb_each(p_filters) f where f.key not in
   ('view','field','query','status','state','from','to','dateField','paymentMethod','sort','fingerprint','tab','originId','method','delayNotice','stage','reasonType','accountExportId')
   or jsonb_typeof(f.value) not in('string','null')) then
  raise invalid_parameter_value using message='invalid_list_export_filters';end if;
 -- 계좌를 실은 환불 송금 대기 파일은 같은 운영자의 계좌 열람 요약 기록(service_export_bank_transfer_refund_accounts)을 가리킨다.
 if p_filters ? 'accountExportId' and (p_screen<>'refund-transfers' or not exists(select 1 from public.audit_log revealed
   where revealed.id=case when p_filters->>'accountExportId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     then (p_filters->>'accountExportId')::uuid end
    and revealed.actor_id=actor and revealed.action='admin.list_export.bank_refund_accounts_revealed')) then
  raise invalid_parameter_value using message='invalid_list_export_filters';end if;
 if p_row_count is null or p_row_count not between 0 and 10000 or p_record_count is null or p_record_count not between 0 and p_row_count then
  raise invalid_parameter_value using message='invalid_list_export_count';end if;
 if p_file_sha256 is null or p_file_sha256!~'^[a-f0-9]{64}$' then
  raise invalid_parameter_value using message='invalid_export_file_hash';end if;
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'admin.list_export.file_issued','admin_screen:'||p_screen,
  jsonb_build_object('screen',p_screen,'filters',p_filters,'rowCount',p_row_count,'recordCount',p_record_count,
   'format','xlsx','encryption','ECMA-376-Agile','fileSha256',p_file_sha256)) returning id into recorded_id;
 return recorded_id;
end $function$

