CREATE OR REPLACE FUNCTION public.service_record_nicepay_payment_reference(p_attempt_id uuid, p_transaction_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_attempt public.payment_attempts%rowtype;
  v_existing text;
begin
  if p_attempt_id is null
    or p_transaction_id is null
    or p_transaction_id !~ '^[A-Za-z0-9]{10,30}$'
  then
    raise invalid_parameter_value using message = 'nicepay_reference_invalid';
  end if;

  select attempt.*
  into v_attempt
  from public.payment_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.provider = 'nicepay'
    and attempt.purpose = 'order'
  for update;

  if not found then
    raise no_data_found using message = 'goods_payment_attempt_not_found';
  end if;

  if v_attempt.state is distinct from 'confirming'
    or v_attempt.claim_expires_at is null
    or v_attempt.claim_expires_at <= pg_catalog.clock_timestamp()
  then
    raise object_not_in_prerequisite_state using message = 'nicepay_reference_claim_required';
  end if;

  select evidence.provider_transaction_id
  into v_existing
  from private.payment_provider_evidence as evidence
  where evidence.payment_attempt_id = v_attempt.id
    and evidence.evidence_kind = 'nicepay_authenticated'
  order by evidence.recorded_at, evidence.id
  limit 1;

  if found then
    if v_existing is distinct from p_transaction_id then
      raise object_not_in_prerequisite_state using message = 'nicepay_reference_conflict';
    end if;
    return;
  end if;

  insert into private.payment_provider_evidence (
    payment_attempt_id,
    evidence_kind,
    provider_transaction_id
  )
  values (
    v_attempt.id,
    'nicepay_authenticated',
    p_transaction_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.service_record_operator_pii_access(p_actor_id uuid, p_action text, p_surface text, p_path text, p_client_ip inet, p_subject_kind text, p_subject_ids uuid[], p_subject_count integer, p_detail jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.profiles;
  access jsonb;
  access_label text;
  ids uuid[];
  members uuid[] := '{}';
  order_ids uuid[] := '{}';
  print text;
  existing bigint;
  recorded bigint;
begin
  select * into actor from public.profiles where id = p_actor_id;
  if p_actor_id is null or not found then
    raise insufficient_privilege using message = 'pii_access_actor_invalid';
  end if;
  if p_action is null or p_action not in ('view', 'search', 'export', 'reveal', 'correct') then
    raise invalid_parameter_value using message = 'pii_access_action_invalid';
  end if;
  if p_surface is null or p_surface !~ '^[a-z][a-z_]{0,31}([.][a-z][a-z_]{0,31}){0,2}$' then
    raise invalid_parameter_value using message = 'pii_access_surface_invalid';
  end if;
  if p_path is null or length(p_path) > 300 or p_path !~ '^/(admin|api/admin)(/[A-Za-z0-9._~%-]+)*$' then
    raise invalid_parameter_value using message = 'pii_access_path_invalid';
  end if;
  if p_subject_kind is null or p_subject_kind not in ('member', 'order', 'claim', 'shipment', 'gift', 'review', 'none') then
    raise invalid_parameter_value using message = 'pii_access_subject_invalid';
  end if;
  if p_subject_ids is not null and array_position(p_subject_ids, null) is not null then
    raise invalid_parameter_value using message = 'pii_access_subject_invalid';
  end if;
  select coalesce(array_agg(distinct s order by s), '{}') into ids from unnest(coalesce(p_subject_ids, '{}')) s;
  if cardinality(ids) > 1000 or p_subject_count is null or p_subject_count < cardinality(ids) or p_subject_count > 1000000
    or (p_subject_kind = 'none' and (cardinality(ids) > 0 or p_subject_count > 0)) then
    raise invalid_parameter_value using message = 'pii_access_subject_invalid';
  end if;
  -- 상세 값은 짧은 코드·숫자·참값만(화면 id·검색 유형·건수·감사 ID). 개인정보 원문이 들어올 길을 좁힌다.
  if p_detail is null or jsonb_typeof(p_detail) <> 'object' or octet_length(p_detail::text) > 2000
    or exists (
      select 1 from jsonb_each(p_detail) d
      where d.key !~ '^[a-z][A-Za-z0-9]{0,39}$'
        or jsonb_typeof(d.value) not in ('string', 'number', 'boolean', 'null')
        or (jsonb_typeof(d.value) = 'string' and length(d.value #>> '{}') > 120)
    ) then
    raise invalid_parameter_value using message = 'pii_access_detail_invalid';
  end if;

  -- 대상의 회원: 주문·클레임·배송 건은 그 주문의 구매자와 선물 주문이면 받는 사람(배송지·연락처의 주인), 선물은 보낸 사람·받는 사람,
  -- 리뷰는 작성자. '이 회원의 정보를 누가 봤나'를 member_ids 하나로 찾는다(대상 1,000개에서 최대 2,000명).
  order_ids := case p_subject_kind
    when 'order' then ids
    when 'claim' then (select coalesce(array_agg(distinct c.order_id), '{}') from public.order_cancellation_requests c where c.id = any(ids))
    when 'shipment' then (select coalesce(array_agg(distinct s.order_id), '{}') from public.order_shipments s where s.id = any(ids))
    else '{}'::uuid[] end;
  members := case p_subject_kind
    when 'member' then ids
    when 'gift' then (select coalesce(array_agg(distinct m.id order by m.id), '{}')
      from private.gift_intents g cross join lateral unnest(array[g.sender_id, g.recipient_id]) as m(id)
      where g.id = any(ids) and m.id is not null)
    when 'review' then (select coalesce(array_agg(distinct r.user_id order by r.user_id), '{}') from public.reviews r
      where r.id = any(ids) and r.user_id is not null)
    else (select coalesce(array_agg(distinct x.id order by x.id), '{}') from (
        select o.user_id as id from public.orders o where o.id = any(order_ids)
        union select g.recipient_id from private.gift_intents g where g.order_id = any(order_ids)
      ) as x where x.id is not null)
    end;
  members := members[1:2000];

  access := private.operator_access_for(p_actor_id);
  access_label := case access->>'mode'
    when 'configured' then coalesce(access->>'managerRole', 'none')
    when 'legacy' then 'legacy_' || actor.role::text
    else 'none' end;

  print := md5(concat_ws('|', p_action, p_surface, p_path, p_subject_kind, ids::text, p_subject_count::text,
    p_detail::text, coalesce(host(p_client_ip), '')));
  if p_action in ('view', 'search') then
    select l.id into existing from private.operator_pii_access_log l
    where l.actor_id = p_actor_id and l.fingerprint = print and l.accessed_at > clock_timestamp() - interval '10 minutes'
    order by l.accessed_at desc, l.id desc limit 1;
    if found then
      return existing;
    end if;
  end if;

  insert into private.operator_pii_access_log (actor_id, actor_access, client_ip, action, surface, path, subject_kind,
    subject_ids, subject_count, member_ids, detail, fingerprint)
  values (p_actor_id, access_label, p_client_ip, p_action, p_surface, p_path, p_subject_kind,
    ids, p_subject_count, members, p_detail, print)
  returning id into recorded;
  return recorded;
end $function$

CREATE OR REPLACE FUNCTION public.service_record_order_claim_contact_retention_case(p_order_id uuid, p_claim_id uuid, p_actor_id uuid, p_session_id uuid, p_operation_id uuid, p_expected_case_revision bigint, p_case jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parties uuid[]:=private.contact_parties(p_order_id);claim public.order_cancellation_requests;old private.order_claim_contact_retention_cases;
 op private.order_claim_contact_retention_operations;occurred timestamptz;until_at timestamptz;request_hash text;receipt jsonb;action text;recorded timestamptz;begin
 if p_operation_id is null or p_expected_case_revision is null or p_expected_case_revision not between 0 and 9007199254740990
 or not private.contact_keys(p_case,array['action','caseRef','approvalRef','legalBasis','retainUntil','occurredAt'])
 or jsonb_typeof(p_case->'action') is distinct from 'string' or p_case->>'action' not in('hold','extend','release','close')
 or jsonb_typeof(p_case->'caseRef') is distinct from 'string' or p_case->>'caseRef'!~'^[A-Za-z0-9:_./-]{1,120}$'
 or jsonb_typeof(p_case->'approvalRef') is distinct from 'string' or p_case->>'approvalRef'!~'^[A-Za-z0-9:_./-]{1,120}$'
 or jsonb_typeof(p_case->'legalBasis') is distinct from 'string' or p_case->>'legalBasis' not in('dispute_resolution','statutory_preservation','verified_rights_request')
 then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 action:=p_case->>'action';occurred:=private.contact_instant(p_case->'occurredAt');
 if action in('hold','extend') then until_at:=private.contact_instant(p_case->'retainUntil');
 elsif p_case->'retainUntil' is distinct from 'null'::jsonb then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 request_hash:=encode(extensions.digest(convert_to(jsonb_build_array('claim-contact-case-v1',p_order_id,p_claim_id,p_actor_id,p_session_id,p_operation_id,p_expected_case_revision,
 action,p_case->>'caseRef',p_case->>'approvalRef',p_case->>'legalBasis',occurred,until_at)::text,'UTF8'),'sha256'),'hex');
 perform private.contact_require_identity(p_actor_id,p_session_id,'platform.manage',true,parties,false);
 perform pg_advisory_xact_lock(hashtextextended('claim-contact-retention-operation:'||p_operation_id,0));
 claim:=private.contact_lock_scope(p_order_id,p_claim_id,parties);
 select * into op from private.order_claim_contact_retention_operations where id=p_operation_id;
 if found then
  if op.actor_id is distinct from p_actor_id or op.session_id is distinct from p_session_id or op.command<>'case' or op.request_hash<>request_hash then raise unique_violation using message='claim_contact_operation_conflict';end if;
  return op.receipt;
 end if;
 select * into old from private.order_claim_contact_retention_cases where claim_id=p_claim_id and case_ref=p_case->>'caseRef' for update;
 if coalesce(old.revision,0)<>p_expected_case_revision or(old.claim_id is not null and old.legal_basis<>p_case->>'legalBasis') then raise sqlstate 'PT409' using message='claim_contact_changed';end if;
 -- Bind validation and the receipt to the same instant after every lock wait.
 recorded:=clock_timestamp();
 if occurred>recorded or(old.last_occurred_at is not null and occurred<old.last_occurred_at)
 or(action in('hold','extend') and(until_at<=recorded or until_at<=occurred)) then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 if old.state='closed' or(action='hold' and old.state is not null and old.state<>'released') or(action='extend' and(old.state is distinct from 'held' or until_at<=old.retain_until))
 or(action='release' and old.state is distinct from 'held') or(action='close' and old.state is not null and old.state not in('held','released')) then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
 if exists(select 1 from private.order_claim_contact_plans where claim_id=p_claim_id and purged_at is not null) and action in('hold','extend') then raise sqlstate 'PT410' using message='claim_contact_purged';end if;
 insert into private.order_claim_contact_retention_cases(claim_id,case_ref,order_id,legal_basis,revision,state,retain_until,case_closed_at,released_at,last_occurred_at,last_operation_id,updated_at)
 values(p_claim_id,p_case->>'caseRef',p_order_id,p_case->>'legalBasis',p_expected_case_revision+1,case when action in('hold','extend') then 'held' when action='release' then 'released' else 'closed' end,
 until_at,case when action='close' then occurred end,case when action='release' then occurred else old.released_at end,occurred,p_operation_id,recorded)
 on conflict(claim_id,case_ref) do update set revision=excluded.revision,state=excluded.state,retain_until=excluded.retain_until,case_closed_at=excluded.case_closed_at,released_at=excluded.released_at,
 last_occurred_at=excluded.last_occurred_at,last_operation_id=excluded.last_operation_id,updated_at=excluded.updated_at returning * into old;
 receipt:=jsonb_build_object('operationId',p_operation_id,'orderId',p_order_id,'claimId',p_claim_id,'actorId',p_actor_id,'sessionId',p_session_id,'caseRef',old.case_ref,
 'action',action,'legalBasis',old.legal_basis,'expectedRevision',p_expected_case_revision,'resultRevision',old.revision,'state',old.state,'retainUntil',old.retain_until,
 'caseClosedAt',old.case_closed_at,'releasedAt',old.released_at,'occurredAt',occurred,'recordedAt',recorded);
 insert into private.order_claim_contact_retention_operations(id,actor_id,session_id,command,request_hash,receipt) values(p_operation_id,p_actor_id,p_session_id,'case',request_hash,receipt);
 insert into public.audit_log(actor_id,action,target,diff) values(p_actor_id,'admin.order.claim_contact_retention','claim:'||p_claim_id,
 jsonb_build_object('operationId',p_operation_id,'caseRef',old.case_ref,'approvalRef',p_case->>'approvalRef','legalBasis',old.legal_basis,'action',action,'caseRevision',old.revision));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.service_record_order_claim_partial_refund(p_request_id uuid, p_payment_id uuid, p_refunded_amount bigint, p_provider_payment_key text, p_provider_transaction_key text, p_actor_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claim public.order_cancellation_requests; pay public.payments; d private.claim_refund_deductions;
begin
  if p_actor_id is not null and not private.can_finish_operator_cancellation(p_request_id, p_actor_id) then
    raise insufficient_privilege using message = 'operator_capability_required';
  end if;
  if p_refunded_amount is null or p_refunded_amount <= 0 or p_provider_payment_key is null
    or (p_provider_transaction_key is not null and p_provider_transaction_key !~ '^[\x21-\x7e]{1,64}$') then
    raise invalid_parameter_value using message = 'refund_deduction_evidence_invalid';
  end if;
  select * into claim from public.order_cancellation_requests where id = p_request_id;
  if not found then raise no_data_found using message = 'cancellation_request_not_found'; end if;
  perform id from public.orders where id = claim.order_id for update;
  select * into claim from public.order_cancellation_requests where id = p_request_id for update;
  if p_actor_id is null and claim.claim_type <> 'cancel' then
    raise insufficient_privilege using message = 'staff required';
  end if;
  select * into pay from public.payments where id = p_payment_id and purpose = 'order' and ref_id = claim.order_id for update;
  select * into d from private.claim_refund_deductions where claim_id = p_request_id for update;
  if d.claim_id is null or pay.id is null or d.payment_id <> pay.id or pay.provider <> 'toss' then
    raise check_violation using message = 'refund_deduction_not_found';
  end if;
  if pay.payment_key is distinct from p_provider_payment_key or p_refunded_amount <> d.refund_amount then
    raise check_violation using message = 'refund_deduction_evidence_mismatch';
  end if;
  if d.state in ('provider_confirmed', 'applied') then return d.state; end if;
  if d.state <> 'planned' or claim.status not in ('processing', 'needs_review') then
    raise check_violation using message = 'refund_deduction_not_planned';
  end if;
  update private.claim_refund_deductions set state = 'provider_confirmed', provider_confirmed_at = clock_timestamp(),
    provider_transaction_key = p_provider_transaction_key where claim_id = p_request_id;
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor_id, case when p_actor_id is null then 'system.order.claim_refund_deduction_confirmed' else 'admin.order.claim_refund_deduction_confirmed' end,
    'order:' || claim.order_id::text,
    jsonb_build_object('claimId', p_request_id, 'paymentId', pay.id, 'refundedAmount', p_refunded_amount,
      'deductionAmount', d.deduction_amount, 'paymentAmount', d.payment_amount));
  return 'provider_confirmed';
end $function$

CREATE OR REPLACE FUNCTION public.service_record_order_claim_reshipment_v2(p_order_id uuid, p_claim_id uuid, p_actor_id uuid, p_session_id uuid, p_operation_id uuid, p_expected_claim_revision integer, p_expected_context jsonb, p_sealed_destination jsonb, p_request_hmac text, p_hmac_key_version text, p_carrier text, p_tracking_number text, p_items jsonb, p_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target uuid;targets integer;begin
 select count(*) into targets from private.claim_reshipment_targets(p_claim_id);
 if targets=1 then select t.shipment_id into target from private.claim_reshipment_targets(p_claim_id) t;
 elsif targets>1 and not exists(select 1 from private.order_claim_contact_operations where id=p_operation_id) then
  raise invalid_parameter_value using message='reshipment_shipment_required';
 end if;
 -- 대상이 없으면(승인 전·종결 뒤) 아래 경계가 최종 주소 확인 단계에서 막힌 상태로 답한다.
 return public.service_record_order_claim_shipment_reshipment(p_order_id,p_claim_id,target,p_actor_id,p_session_id,p_operation_id,p_expected_claim_revision,
  p_expected_context,p_sealed_destination,p_request_hmac,p_hmac_key_version,p_carrier,p_tracking_number,p_items,null,p_confirmed);
end $function$

CREATE OR REPLACE FUNCTION public.service_record_order_claim_shipment_reshipment(p_order_id uuid, p_claim_id uuid, p_shipment_id uuid, p_actor_id uuid, p_session_id uuid, p_operation_id uuid, p_expected_claim_revision integer, p_expected_context jsonb, p_sealed_destination jsonb, p_request_hmac text, p_hmac_key_version text, p_carrier text, p_tracking_number text, p_items jsonb, p_collection_waiver jsonb, p_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parties uuid[]:=private.contact_parties(p_order_id);op private.order_claim_contact_operations;c public.order_cancellation_requests;view jsonb;result_revision integer;
 previous_subject text:=current_setting('request.jwt.claim.sub',true);record_id uuid;begin
 perform private.contact_operation_input(p_operation_id,'reshipment','reshipment','exchange',p_expected_claim_revision);
 perform private.contact_require_identity(p_actor_id,p_session_id,'sales.manage',false,parties,false);
 perform pg_advisory_xact_lock(hashtextextended('claim-contact-operation:'||p_operation_id,0));
 c:=private.contact_lock_scope(p_order_id,p_claim_id,parties);
 select id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,result_claim_revision,
 state,changed_fields,request_hmac,hmac_key_version,null::jsonb,created_at,purged_at into op
 from private.order_claim_contact_operations where id=p_operation_id;
 if found then
  perform private.contact_operation_scope(op,p_order_id,p_claim_id,p_actor_id,p_session_id,'reshipment','reshipment','exchange',p_expected_claim_revision);
  if op.state='sealed' then raise sqlstate 'PT409' using message='claim_contact_operation_sealed';end if;
  if op.purged_at is not null then raise sqlstate 'PT410' using message='claim_contact_purged';end if;
  if op.request_hmac is distinct from p_request_hmac or op.hmac_key_version is distinct from p_hmac_key_version then raise unique_violation using message='claim_contact_operation_conflict';end if;
  return private.contact_operation_receipt(op);
 end if;
 if exists(select 1 from private.account_action_fences where subject_user_id=any(parties)) then raise sqlstate 'PT409' using message='claim_contact_blocked';end if;
 if p_confirmed is distinct from true or not private.contact_digest(to_jsonb(p_request_hmac)) or not private.contact_key_version(to_jsonb(p_hmac_key_version))
 or not private.contact_keys(p_sealed_destination,array['piiVersion','keyVersion','address','addressHmac','addressHmacKeyVersion','sourceKind','sourceId','sourceRevision','sourcePlanRevision','sourcePiiVersion'])
 or not private.contact_uuid(p_sealed_destination->'piiVersion') or not private.contact_key_version(p_sealed_destination->'keyVersion')
 or not private.contact_key_version(p_sealed_destination->'addressHmacKeyVersion') or not private.contact_digest(p_sealed_destination->'addressHmac')
 or not private.contact_address_envelope(p_sealed_destination->'address',p_sealed_destination->>'keyVersion')
 or p_carrier is null or char_length(p_carrier) not between 1 and 40 or p_carrier<>btrim(p_carrier) or p_tracking_number is null or p_tracking_number!~'^[A-Z0-9]{8,30}$'
 then raise invalid_parameter_value using message='invalid_claim_contact_request';end if;
 view:=private.contact_assert_context(c,'reshipment','reshipment','exchange',p_expected_claim_revision,p_expected_context);
 if jsonb_build_object('sourceKind',p_sealed_destination->'sourceKind','sourceId',p_sealed_destination->'sourceId','sourceRevision',p_sealed_destination->'sourceRevision',
 'planRevision',p_sealed_destination->'sourcePlanRevision','piiVersion',p_sealed_destination->'sourcePiiVersion') is distinct from((view->'source')-'sourceFingerprint')
 then raise sqlstate 'PT409' using message='claim_contact_changed';end if;
 -- 이미 재출고한 배송 건에 새 작업을 덧대지 않는다. 같은 요청의 재전송은 위 작업 영수증이 받는다.
 if exists(select 1 from public.order_claim_reshipments where claim_id=p_claim_id and shipment_id is not distinct from p_shipment_id) then
  raise unique_violation using message='reshipment_conflict';end if;
 -- 출고 보류(테스트 결제·결제사 취소) 주문에는 교환품을 새로 내보내지 않는다.
 if private.order_fulfillment_held(p_order_id) then raise check_violation using message='order_fulfillment_hold';end if;
 -- Preserve the explicit actor only for the already-verified physical call.
 begin
  perform set_config('request.jwt.claim.sub',p_actor_id::text,true);
  perform private.record_order_claim_shipment_reshipment(p_claim_id,p_shipment_id,p_carrier,p_tracking_number,p_items,p_collection_waiver);
  perform set_config('request.jwt.claim.sub',coalesce(previous_subject,''),true);
 exception when others then perform set_config('request.jwt.claim.sub',coalesce(previous_subject,''),true);raise;end;
 select id into record_id from public.order_claim_reshipments where claim_id=p_claim_id and shipment_id is not distinct from p_shipment_id;
 select claim_revision into result_revision from public.order_cancellation_requests where id=p_claim_id;
 insert into private.order_claim_contact_operations(id,actor_id,session_id,order_id,claim_id,command,target,expected_claim_type,expected_claim_revision,result_claim_revision,state,request_hmac,hmac_key_version)
 values(p_operation_id,p_actor_id,p_session_id,p_order_id,p_claim_id,'reshipment','reshipment','exchange',p_expected_claim_revision,result_revision,'saved',p_request_hmac,p_hmac_key_version) returning * into op;
 insert into private.order_claim_reshipment_destinations(claim_id,order_id,operation_id,confirmed_claim_revision,destination,reshipment_id)
 values(p_claim_id,p_order_id,p_operation_id,result_revision,p_sealed_destination,record_id);
 return private.contact_operation_receipt(op);
end $function$

CREATE OR REPLACE FUNCTION public.service_record_return_pickup_results(p_results jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare settings private.return_pickup_settings; result jsonb; pickup private.claim_return_pickups; tracking text; external text; code text;
  bundle public.order_claim_collection_bundles; label text; recorded integer := 0; requested integer := 0; failed integer := 0; canceled integer := 0;
  cancel_failed integer := 0; stale integer := 0; invalid integer := 0; deferred integer := 0; late text; system_actor constant uuid := '00000000-0000-0000-0000-000000000000';
begin
  if jsonb_typeof(p_results) is distinct from 'array' or jsonb_array_length(p_results) > 100 then
    raise invalid_parameter_value using message = 'invalid_return_pickup_results'; end if;
  select * into settings from private.return_pickup_settings where singleton;
  for result in select value from jsonb_array_elements(p_results) loop
    if jsonb_typeof(result) is distinct from 'object' or coalesce(result->>'pickupId', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or coalesce(result->>'leaseToken', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or coalesce(result->>'kind', '') not in ('request','cancel') then invalid := invalid + 1; continue; end if;
    select * into pickup from private.claim_return_pickups where id = (result->>'pickupId')::uuid for update;
    if not found or pickup.lease_token is distinct from (result->>'leaseToken')::uuid
      or (result->>'kind' = 'request') <> (pickup.state in ('pending','failed')) then stale := stale + 1; continue; end if;
    -- 회차 시간 예산이 끝나 보내지 못한 일: 한 번도 보내지 않았으니 임대를 풀고 이번 회차가 센 시도를 되돌린다(다음 회차가 다시 잡는다).
    if result->>'outcome' = 'deferred' then
      update private.claim_return_pickups set lease_token = null, lease_until = null, updated_at = clock_timestamp(),
        attempts = case when result->>'kind' = 'request' then greatest(attempts - 1, retry_base) else attempts end,
        cancel_attempts = case when result->>'kind' = 'cancel' then greatest(cancel_attempts - 1, cancel_retry_base) else cancel_attempts end
      where id = pickup.id;
      deferred := deferred + 1;
      continue;
    end if;
    code := nullif(result->>'errorCode', '');
    if code is not null and code !~ '^[a-z0-9_]{1,64}$' then code := 'upstream_error'; end if;
    if result->>'kind' = 'request' then
      tracking := upper(regexp_replace(coalesce(result->>'trackingNumber', ''), '[^A-Za-z0-9]', '', 'g'));
      external := nullif(result->>'externalId', '');
      if result->>'outcome' = 'requested' and tracking ~ '^[A-Z0-9]{8,30}$' and (external is null or external ~ '^[\x21-\x7e]{1,100}$') then
        update private.claim_return_pickups set state = 'requested', tracking_number = tracking, external_id = external, requested_at = clock_timestamp(),
          last_error_code = null, next_attempt_at = null, lease_token = null, lease_until = null, updated_at = clock_timestamp()
        where id = pickup.id;
        insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome) values (pickup.id, 'request', 'requested');
        select * into bundle from public.order_claim_collection_bundles where id = pickup.bundle_id;
        -- 요청이 나가는 사이 철회·거절됐거나 회수가 필요 없어졌으면 접수됐다고 알리지 않고 바로 취소로 돌린다('collected'는 정상 종료라 다음 회차가 닫는다).
        late := private.claim_return_pickup_block(bundle);
        if late is not null and late <> 'collected' then
          update private.claim_return_pickups set state = 'cancel_pending', cancel_reason = late, next_attempt_at = clock_timestamp(),
            cancel_retry_base = cancel_attempts, updated_at = clock_timestamp() where id = pickup.id;
        end if;
        label := coalesce(nullif(bundle.return_name_snapshot, ''), '출고지 반품 주소');
        insert into private.claim_collection_events(id, claim_id, shipment_id, actor_id, session_id, request, result)
        values (gen_random_uuid(), pickup.claim_id, pickup.shipment_id, system_actor, system_actor,
          jsonb_build_object('claimId', pickup.claim_id, 'shipmentId', pickup.shipment_id, 'bundleId', pickup.bundle_id, 'source', 'return_pickup',
            'values', jsonb_build_object('method', 'seller_arranged', 'carrier', pickup.carrier, 'trackingNumber', tracking,
              'evidence', case when late is not null and late <> 'collected' then '자동 회수 접수 후 즉시 취소 · ' else '자동 회수 접수 · ' end || label)),
          jsonb_build_object('pickupId', pickup.id, 'state', 'requested'));
        insert into public.audit_log(actor_id, action, target, diff) values (null, 'system.order.claim_return_pickup_requested', 'order:' || pickup.order_id,
          jsonb_build_object('claimId', pickup.claim_id, 'shipmentId', pickup.shipment_id, 'bundleId', pickup.bundle_id, 'pickupId', pickup.id,
            'provider', pickup.provider, 'carrier', pickup.carrier, 'trackingNumber', tracking, 'attempts', pickup.attempts,
            'canceledAtOnce', case when late is not null and late <> 'collected' then late else null end));
        if late is null then
          perform private.notify_order_claim(pickup.claim_id, 'return_pickup_requested', '방문 회수가 접수됐어요',
            '택배 기사가 방문해 굿즈를 회수합니다. 주문 상세의 회수 정보에서 회수 송장을 확인해주세요.');
        end if;
        requested := requested + 1;
      else
        update private.claim_return_pickups set state = 'failed',
          last_error_code = case when result->>'outcome' = 'requested' then 'invalid_tracking' else coalesce(code, 'upstream_error') end,
          next_attempt_at = private.claim_return_pickup_next_attempt(pickup.attempts - pickup.retry_base, settings),
          lease_token = null, lease_until = null, updated_at = clock_timestamp()
        where id = pickup.id;
        insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome, error_code)
        values (pickup.id, 'request', 'error', case when result->>'outcome' = 'requested' then 'invalid_tracking' else coalesce(code, 'upstream_error') end);
        failed := failed + 1;
      end if;
    else
      if result->>'outcome' in ('canceled','not_found') then
        update private.claim_return_pickups set state = 'canceled', canceled_at = clock_timestamp(), last_error_code = null, next_attempt_at = null,
          lease_token = null, lease_until = null, updated_at = clock_timestamp() where id = pickup.id;
        insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome) values (pickup.id, 'cancel', result->>'outcome');
        if pickup.tracking_number is not null then
          insert into private.claim_collection_events(id, claim_id, shipment_id, actor_id, session_id, request, result)
          values (gen_random_uuid(), pickup.claim_id, pickup.shipment_id, system_actor, system_actor,
            jsonb_build_object('claimId', pickup.claim_id, 'shipmentId', pickup.shipment_id, 'bundleId', pickup.bundle_id, 'source', 'return_pickup',
              'values', jsonb_build_object('method', 'seller_arranged', 'carrier', pickup.carrier, 'trackingNumber', pickup.tracking_number,
                'evidence', '자동 회수 취소 · ' || case pickup.cancel_reason when 'withdrawn' then '요청 철회' when 'rejected' then '요청 거절'
                  when 'completed' then '요청 종결' when 'waived' then '회수 생략' when 'customer_sent' then '고객 직접 발송' when 'manual' then '수거 방법 별도 기록' else '회수 불필요' end)),
            jsonb_build_object('pickupId', pickup.id, 'state', 'canceled'));
        end if;
        insert into public.audit_log(actor_id, action, target, diff) values (null, 'system.order.claim_return_pickup_canceled', 'order:' || pickup.order_id,
          jsonb_build_object('claimId', pickup.claim_id, 'bundleId', pickup.bundle_id, 'pickupId', pickup.id, 'provider', pickup.provider,
            'carrier', pickup.carrier, 'trackingNumber', pickup.tracking_number, 'reason', pickup.cancel_reason, 'outcome', result->>'outcome'));
        canceled := canceled + 1;
      else
        update private.claim_return_pickups set state = 'cancel_failed', last_error_code = coalesce(code, 'upstream_error'),
          next_attempt_at = private.claim_return_pickup_next_attempt(pickup.cancel_attempts - pickup.cancel_retry_base, settings),
          lease_token = null, lease_until = null, updated_at = clock_timestamp() where id = pickup.id;
        insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome, error_code) values (pickup.id, 'cancel', 'error', coalesce(code, 'upstream_error'));
        cancel_failed := cancel_failed + 1;
      end if;
    end if;
    recorded := recorded + 1;
  end loop;
  return jsonb_build_object('recorded', recorded, 'requested', requested, 'failed', failed, 'canceled', canceled, 'cancelFailed', cancel_failed,
    'stale', stale, 'invalid', invalid, 'deferred', deferred);
end $function$

CREATE OR REPLACE FUNCTION public.service_record_review_export_v2(p_actor_id uuid, p_session_id uuid, p_filters jsonb, p_fingerprint text, p_row_count integer, p_captured_at timestamp with time zone, p_file_sha256 text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare snapshot jsonb;recorded_id uuid;query_units integer;
begin
 if current_setting('role',true) is distinct from 'service_role' or p_actor_id is null or p_session_id is null then
  raise insufficient_privilege using message='review_export_auth_changed';end if;
 if p_fingerprint is null or p_fingerprint!~'^[a-f0-9]{64}$' or p_file_sha256 is null or p_file_sha256!~'^[a-f0-9]{64}$'
  or p_row_count is null or p_row_count not between 0 and 10000 or p_captured_at is null or not isfinite(p_captured_at)
  or p_captured_at>clock_timestamp() then raise invalid_parameter_value using message='invalid_review_export_issuance';end if;
 perform private.lock_operator_subjects(array[p_actor_id]);
 perform 1 from auth.users u where u.id=p_actor_id and u.deleted_at is null
  and (u.banned_until is null or u.banned_until<=clock_timestamp()) for share;
 if not found then raise insufficient_privilege using message='review_export_auth_changed';end if;
 perform 1 from auth.sessions s where s.id=p_session_id and s.user_id=p_actor_id
  and (s.not_after is null or s.not_after>clock_timestamp()) for share;
 if not found or not private.has_operator_capability(p_actor_id,'cs.manage',false) or not private.operator_mfa_service_session_ok(p_actor_id,p_session_id) then
  raise insufficient_privilege using message='review_export_auth_changed';end if;
 snapshot:=private.review_export_snapshot_v2(p_actor_id,p_filters);
 if snapshot->>'fingerprint' is distinct from p_fingerprint or (snapshot->>'total')::integer is distinct from p_row_count then
  raise sqlstate 'PT409' using message='review_export_changed';end if;
 select coalesce(sum(case when ascii(unit.ch)>65535 then 2 else 1 end),0)::integer
  into query_units from regexp_split_to_table(p_filters->>'query','') as unit(ch) where unit.ch<>'';
 insert into public.audit_log(actor_id,action,target,diff) values(p_actor_id,'admin.review_export.file_issued','admin_screen:reviews',
  jsonb_build_object('screen','reviews','filters',p_filters-'query','queryPresent',(p_filters->>'query')<>'','queryLength',query_units,
   'rowCount',p_row_count,'recordCount',p_row_count,'fingerprint',p_fingerprint,'capturedAt',p_captured_at,
   'format','xlsx','encryption','ECMA-376-Agile','fileSha256',p_file_sha256)) returning id into recorded_id;
 return recorded_id;
end $function$

