CREATE OR REPLACE FUNCTION public.service_reject_order_partial_cancellation(p_id uuid, p_reason_code text, p_actor_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare head private.order_partial_cancellations;
begin
  perform private.require_partial_cancellation_actor(p_actor_id);
  if p_reason_code is distinct from 'provider_partial_cancel_unavailable' then raise invalid_parameter_value using message = 'invalid_partial_cancel_reason'; end if;
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  perform 1 from public.orders where id = head.order_id for update;
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if head.state = 'rejected' then return 'rejected'; end if;
  if head.state not in ('processing', 'needs_review') then raise check_violation using message = 'partial_cancel_not_processing'; end if;
  update private.order_partial_cancellations set state = 'rejected', rejected_at = clock_timestamp(), last_error_code = p_reason_code where id = p_id;
  insert into public.audit_log(actor_id, action, target, diff)
  values (p_actor_id, 'admin.order.partial_cancellation_rejected', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'reason', p_reason_code, 'refundAmount', head.refund_amount));
  return 'rejected';
end $function$

CREATE OR REPLACE FUNCTION public.service_reject_profile_avatar_claim(p_user_id uuid, p_avatar_path text)
 RETURNS TABLE(rejected boolean, cleanup_safe boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text;
begin
  select claim.status
  into v_status
  from public.profile_avatar_claims as claim
  where claim.path = p_avatar_path
    and claim.user_id = p_user_id
  for update;

  if not found or v_status <> 'pending' then
    return query select false, false;
    return;
  end if;

  update public.profile_avatar_claims as claim
  set
    status = 'rejected',
    resolved_at = now()
  where claim.path = p_avatar_path
    and claim.user_id = p_user_id
    and claim.status = 'pending';

  if not found then
    return query select false, false;
    return;
  end if;

  return query select true, true;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_resolve_order_partial_cancellation(p_id uuid, p_resolution text, p_reason text, p_provider_transaction_key text, p_observed_balance bigint, p_actor_id uuid, p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := p_actor_id; head private.order_partial_cancellations; pay public.payments; buyer uuid;
  reason text := nullif(btrim(coalesce(p_reason, '')), ''); topology boolean := false;
begin
  if v_actor is null or p_session_id is null
    or not exists(select 1 from auth.sessions where id = p_session_id and user_id = v_actor and (not_after is null or not_after > statement_timestamp()))
    or not exists(select 1 from public.profiles where id = v_actor) then
    raise insufficient_privilege using message = 'refund_account_auth_changed';
  end if;
  if not private.has_operator_capability(v_actor, 'sales.manage', true) or not private.operator_mfa_service_session_ok(v_actor, p_session_id) then raise insufficient_privilege using message = 'bank_refund_permission_required'; end if;
  if p_resolution is null or p_resolution not in ('not_moved', 'already_canceled') then
    raise invalid_parameter_value using message = 'invalid_partial_cancel_resolution';
  end if;
  if reason is null or char_length(reason) not between 5 and 500 or translate(reason, E'\n\r\t', '') ~ '[[:cntrl:]]' then
    raise check_violation using message = 'partial_cancel_resolution_reason_required';
  end if;
  select * into head from private.order_partial_cancellations where id = p_id;
  if not found then raise no_data_found using message = 'partial_cancellation_not_found'; end if;
  select o.user_id into buyer from public.orders o where o.id = head.order_id;
  perform private.lock_operator_subjects(array[v_actor, buyer]);
  perform private.require_actor_operator_capability(v_actor, 'sales.manage', true);
  perform id from auth.sessions where id = p_session_id and user_id = v_actor and (not_after is null or not_after > clock_timestamp()) for share;
  if not found then raise insufficient_privilege using message = 'refund_account_auth_changed'; end if;
  perform 1 from public.orders where id = head.order_id for update;
  perform s.id from public.order_shipments s where s.order_id = head.order_id order by s.id for update;
  select * into pay from public.payments where id = head.payment_id for update;
  select * into head from private.order_partial_cancellations where id = p_id for update;
  if head.provider <> 'toss' or head.state <> 'needs_review' then raise check_violation using message = 'partial_cancel_not_needs_review'; end if;
  if p_resolution = 'not_moved' then
    if p_observed_balance is distinct from head.balance_before then raise check_violation using message = 'partial_cancel_resolution_evidence_mismatch'; end if;
    update private.order_partial_cancellations set state = 'rejected', rejected_at = clock_timestamp(), last_error_code = 'manual_not_moved',
      resolution = 'not_moved', resolution_reason = reason, resolved_by = v_actor, resolved_at = clock_timestamp() where id = p_id;
  else
    if p_observed_balance is distinct from head.balance_before - head.refund_amount
      or p_provider_transaction_key is null or p_provider_transaction_key !~ '^[\x21-\x7e]{1,64}$' then
      raise check_violation using message = 'partial_cancel_resolution_evidence_mismatch';
    end if;
    update private.order_partial_cancellations set provider_confirmed_at = clock_timestamp(), provider_transaction_key = p_provider_transaction_key,
      resolution = 'already_canceled', resolution_reason = reason, resolved_by = v_actor, resolved_at = clock_timestamp() where id = p_id;
    begin
      perform private.apply_order_partial_cancellation(p_id, v_actor, 'completed', false);
    exception when check_violation then
      if sqlerrm <> 'partial_cancel_item_stock_topology_changed' then raise; end if;
      topology := true;
    end;
    if topology then perform private.apply_order_partial_cancellation(p_id, v_actor, 'completed', true); end if;
  end if;
  insert into public.audit_log(actor_id, action, target, diff)
  values (v_actor, 'admin.order.partial_cancellation_resolved', 'order:' || head.order_id::text,
    jsonb_build_object('partialCancellationId', p_id, 'resolution', p_resolution, 'reason', reason, 'observedBalance', p_observed_balance,
      'providerTransactionKey', p_provider_transaction_key, 'followedSuccessor', topology, 'previousCode', head.last_error_code));
  return jsonb_build_object('id', p_id, 'state', case when p_resolution = 'not_moved' then 'rejected' else 'completed' end, 'followedSuccessor', topology);
end $function$

CREATE OR REPLACE FUNCTION public.service_retire_digital_asset(p_actor uuid, p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 -- Cancellation remains possible after privilege revocation, but only for the
 -- original uploader's unattached file.
 if p_actor is null then return false;end if;
 perform 1 from private.goods_digital_assets where id=p_id for update;
 if private.digital_asset_referenced(p_id) then return false;end if;
 update private.goods_digital_assets set state='retired',expires_at=clock_timestamp() where id=p_id and actor_id=p_actor and state in('pending','verified','retired');return found;
end $function$

CREATE OR REPLACE FUNCTION public.service_retry_direct_order(p_user_id uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result text;
  v_hold private.cart_order_holds%rowtype;
  v_existing private.checkout_drafts%rowtype;
  v_lines jsonb;
  v_draft uuid;
begin
  v_result := private.close_direct_order_for_retry(p_user_id, p_order_id);
  if v_result is null then
    return null;
  end if;
  if v_result <> 'closed' then
    return pg_catalog.jsonb_build_object('result', v_result);
  end if;
  select draft.* into v_existing from private.checkout_drafts as draft
  where draft.retry_order_id = p_order_id and draft.user_id = p_user_id
  for update;
  if found then
    if v_existing.order_id is not null and private.checkout_draft_order_settled(v_existing.order_id) then
      return pg_catalog.jsonb_build_object('result', 'not_retryable', 'orderId', v_existing.order_id);
    end if;
    if v_existing.order_id is not null and private.checkout_draft_order_payment_unresolved(v_existing.order_id) then
      return pg_catalog.jsonb_build_object('result', 'payment_in_progress', 'orderId', v_existing.order_id);
    end if;
    if v_existing.scrubbed_at is null and v_existing.expires_at > pg_catalog.clock_timestamp() then
      return pg_catalog.jsonb_build_object('result', 'draft', 'draftId', v_existing.id);
    end if;
    update private.checkout_drafts set retry_order_id = null where id = v_existing.id;
  end if;
  select hold.* into v_hold from private.cart_order_holds as hold where hold.order_id = p_order_id;
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('good_id', line ->> 'goodId', 'variant_id', line ->> 'variantId',
      'qty', (line ->> 'qty')::integer, 'input_revision', coalesce((line ->> 'inputRevision')::integer, 0),
      'input_values', coalesce(line -> 'inputValues', '{}'::jsonb)) order by position)
    into v_lines
  from pg_catalog.jsonb_array_elements(v_hold.lines) with ordinality as entries(line, position);
  -- 닫기는 남기고 초안만 되돌린다 — 지금 같은 줄을 살 수 없으면(판매 중지·옵션 정리·직접입력 설정 변경·성인 인증) 굿즈 상세로.
  begin
    v_draft := public.service_create_checkout_direct_draft(p_user_id, v_hold.base_good_id, v_lines);
  exception when check_violation or invalid_parameter_value then
    return pg_catalog.jsonb_build_object('result', 'unavailable', 'baseGoodId', v_hold.base_good_id, 'reason', sqlerrm);
  end;
  update private.checkout_drafts set retry_order_id = p_order_id where id = v_draft;
  return pg_catalog.jsonb_build_object('result', 'draft', 'draftId', v_draft);
end;
$function$

CREATE OR REPLACE FUNCTION public.service_return_pickup_work(p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare settings private.return_pickup_settings; now_at timestamptz := clock_timestamp(); pickup private.claim_return_pickups;
  bundle public.order_claim_collection_bundles; reason text; token uuid; items jsonb := '[]'::jsonb; queued integer := 0; closed integer := 0;
begin
  if p_limit is null or p_limit not between 1 and 100 then raise invalid_parameter_value using message = 'invalid_return_pickup_limit'; end if;
  select * into settings from private.return_pickup_settings where singleton;
  if not found or not settings.pickup_enabled then return jsonb_build_object('enabled', false); end if;

  insert into private.claim_return_pickups(bundle_id, claim_id, shipment_id, order_id, origin_id, provider, carrier, idempotency_key, next_attempt_at)
  select b.id, b.claim_id, b.shipment_id, c.order_id, x.origin_id, settings.provider, origin.carrier,
    'icons-return-' || replace(b.id::text, '-', ''), now_at
  from public.order_claim_collection_bundles b
  join public.order_cancellation_requests c on c.id = b.claim_id
  join public.order_claim_collections x on x.claim_id = b.claim_id and x.shipment_id = b.shipment_id
  join private.return_pickup_origins origin on origin.origin_id = x.origin_id and origin.enabled
  where c.stage = 'collecting' and b.collected_at is null and b.created_at >= greatest(settings.pickup_enabled_at, origin.enabled_at)
    and not exists(select 1 from private.claim_return_pickups p where p.bundle_id = b.id)
    and private.claim_return_pickup_eligible(b)
  order by b.created_at, b.id
  limit 500
  on conflict (bundle_id) do nothing;
  get diagnostics queued = row_count;

  for pickup in select p.* from private.claim_return_pickups p
    where p.state in ('pending','failed','requested') and (p.lease_until is null or p.lease_until < now_at)
    order by p.id for update skip locked loop
    select * into bundle from public.order_claim_collection_bundles where id = pickup.bundle_id;
    reason := private.claim_return_pickup_block(bundle);
    -- 아직 한 번도 보내지 않은 접수는, 그 사이 운영자·판매자가 회수 방법을 따로 기록했으면 보내지 않고 닫는다(이중 수거 방지).
    if reason is null and pickup.attempts = 0 and pickup.state = 'pending'
      and (exists(select 1 from private.claim_collection_plans plan where plan.claim_id = pickup.claim_id and plan.shipment_id = pickup.shipment_id and plan.requested_once)
        or exists(select 1 from private.seller_order_claim_intakes intake cross join lateral jsonb_array_elements(intake.payload->'collections') item
          where intake.claim_id = pickup.claim_id and item->>'shipmentId' = pickup.shipment_id::text and coalesce(item->>'method', 'not_requested') <> 'not_requested')) then
      reason := 'manual';
    end if;
    continue when reason is null;
    if reason = 'collected' and pickup.state = 'requested' then
      update private.claim_return_pickups set state = 'collected', next_attempt_at = null, lease_token = null, lease_until = null, updated_at = now_at
      where id = pickup.id;
    elsif pickup.state <> 'requested' and pickup.attempts = 0 then
      update private.claim_return_pickups set state = 'canceled', cancel_reason = reason, canceled_at = now_at, next_attempt_at = null,
        lease_token = null, lease_until = null, updated_at = now_at where id = pickup.id;
      insert into private.claim_return_pickup_attempts(pickup_id, kind, outcome) values (pickup.id, 'local_cancel', 'canceled');
    else
      update private.claim_return_pickups set state = 'cancel_pending', cancel_reason = reason, next_attempt_at = now_at, cancel_retry_base = cancel_attempts,
        lease_token = null, lease_until = null, updated_at = now_at where id = pickup.id;
    end if;
    closed := closed + 1;
  end loop;

  for pickup in select p.* from private.claim_return_pickups p
    where p.state in ('pending','failed','cancel_pending','cancel_failed') and p.next_attempt_at is not null and p.next_attempt_at <= now_at
      and (p.lease_until is null or p.lease_until < now_at)
      -- 접수는 수거중 단계에서만 보낸다(보류·처리중 등은 단계가 돌아올 때까지 기다린다). 취소는 단계와 관계없이 보낸다.
      and (p.state in ('cancel_pending','cancel_failed')
        or exists(select 1 from public.order_cancellation_requests c where c.id = p.claim_id and c.stage = 'collecting'))
    order by p.next_attempt_at, p.id limit p_limit for update skip locked loop
    token := gen_random_uuid();
    if pickup.state in ('pending','failed') then
      update private.claim_return_pickups set lease_token = token, lease_until = now_at + interval '10 minutes', attempts = attempts + 1, updated_at = now_at
      where id = pickup.id;
      items := items || jsonb_build_array(private.claim_return_pickup_request_item(pickup.id, token));
    else
      update private.claim_return_pickups set lease_token = token, lease_until = now_at + interval '10 minutes', cancel_attempts = cancel_attempts + 1, updated_at = now_at
      where id = pickup.id;
      items := items || jsonb_build_array(jsonb_build_object('kind', 'cancel', 'pickupId', pickup.id, 'leaseToken', token, 'provider', pickup.provider,
        'idempotencyKey', pickup.idempotency_key, 'carrier', pickup.carrier, 'trackingNumber', pickup.tracking_number, 'externalId', pickup.external_id));
    end if;
  end loop;
  return jsonb_build_object('enabled', true, 'provider', settings.provider, 'queued', queued, 'closed', closed, 'items', items);
end $function$

CREATE OR REPLACE FUNCTION public.service_update_profile_identity(p_user_id uuid, p_nickname text, p_avatar_path text, p_replace_avatar boolean)
 RETURNS TABLE(applied boolean, error_code text, cleanup_safe boolean, previous_avatar_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_previous_avatar_path text;
  v_claim_status text;
  v_error_code text;
  v_rejected_count bigint := 0;
begin
  if p_user_id is null or p_nickname is null or p_replace_avatar is null then
    return query select false, '22023'::text, false, null::text;
    return;
  end if;

  if p_replace_avatar and p_avatar_path is null then
    return query select false, '22023'::text, false, null::text;
    return;
  end if;

  if not p_replace_avatar and p_avatar_path is not null then
    return query select false, '22023'::text, false, null::text;
    return;
  end if;

  select profile.avatar_path
  into v_previous_avatar_path
  from public.profiles as profile
  where profile.id = p_user_id
  for update;

  if not found then
    return query select false, 'P0002'::text, false, null::text;
    return;
  end if;

  if p_replace_avatar then
    select claim.status
    into v_claim_status
    from public.profile_avatar_claims as claim
    where claim.path = p_avatar_path
      and claim.user_id = p_user_id
    for update;

    if not found then
      return query select false, 'avatar_unclaimed'::text, false, null::text;
      return;
    end if;

    if v_claim_status <> 'pending' then
      return query select false, 'avatar_replayed'::text, false, null::text;
      return;
    end if;
  end if;

  begin
    update public.profiles as profile
    set
      nickname = p_nickname,
      avatar_path = case
        when p_replace_avatar then p_avatar_path
        else profile.avatar_path
      end
    where profile.id = p_user_id;

    if p_replace_avatar and v_previous_avatar_path is not null then
      update public.profile_avatar_claims as claim
      set
        status = 'retired',
        resolved_at = now()
      where claim.path = v_previous_avatar_path
        and claim.user_id = p_user_id
        and claim.status = 'active';

      if not found then
        raise exception using
          errcode = '23514',
          message = 'active previous avatar claim is missing';
      end if;
    end if;

    if p_replace_avatar then
      update public.profile_avatar_claims as claim
      set
        status = 'active',
        resolved_at = now()
      where claim.path = p_avatar_path
        and claim.user_id = p_user_id
        and claim.status = 'pending';

      if not found then
        raise exception using
          errcode = '23514',
          message = 'pending avatar claim changed during finalization';
      end if;
    end if;
  exception
    when others then
      get stacked diagnostics v_error_code = returned_sqlstate;

      if p_replace_avatar then
        update public.profile_avatar_claims as claim
        set
          status = 'rejected',
          resolved_at = now()
        where claim.path = p_avatar_path
          and claim.user_id = p_user_id
          and claim.status = 'pending';

        get diagnostics v_rejected_count = row_count;
      end if;

      return query select false, v_error_code, v_rejected_count = 1, null::text;
      return;
  end;

  return query select true, null::text, false, v_previous_avatar_path;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_verify_digital_asset(p_actor uuid, p_session uuid, p_id uuid, p_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare asset private.goods_digital_assets;begin
 perform private.digital_operator_session(p_actor,p_session);
 select * into asset from private.goods_digital_assets where id=p_id and actor_id=p_actor and session_id=p_session for update;
 if not found or p_sha256 is null or p_sha256!~'^[0-9a-f]{64}$' then raise insufficient_privilege;end if;
 if asset.state='verified' then if asset.sha256<>p_sha256 then raise sqlstate 'PT409';end if;
 elsif asset.state='pending' and asset.expires_at>clock_timestamp() and exists(select 1 from storage.objects o where o.bucket_id='goods-digital-private' and o.name=asset.path
  and o.metadata->>'mimetype'=asset.mime_type and o.metadata->>'size'=asset.size_bytes::text) then
  update private.goods_digital_assets set state='verified',sha256=p_sha256,verified_at=clock_timestamp(),expires_at=clock_timestamp()+interval '24 hours' where id=p_id;
 else raise check_violation using message='digital_upload_unverified';end if;
 return private.digital_file_metadata(array[p_id])->0;
end $function$

CREATE OR REPLACE FUNCTION public.service_verify_goods_media_upload(p_actor_id uuid, p_id uuid, p_metadata jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claimed private.goods_media_assets%rowtype;
begin
 perform private.require_actor_operator_capability(p_actor_id,'catalog.manage');
 select * into claimed from private.goods_media_assets where id=p_id and actor_id=p_actor_id for update;
 if not found then return false;end if;
 if claimed.status in('verified','attached') then return claimed.metadata=p_metadata;end if;
 if claimed.status<>'processing' or claimed.expires_at<=clock_timestamp() or not private.goods_media_metadata_valid(p_metadata,claimed.source_size)
  or not exists(select 1 from storage.objects o where o.bucket_id='goods-videos' and o.name=claimed.path and o.metadata->>'mimetype'='video/mp4' and o.metadata->>'size'=claimed.source_size::text) then return false;end if;
 update private.goods_media_assets set status='verified',metadata=p_metadata,verified_at=clock_timestamp(),expires_at=clock_timestamp()+interval '2 hours' where id=claimed.id;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.service_verify_inquiry_file(p_actor uuid, p_session uuid, p_id uuid, p_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
