 else raise check_violation using message='inquiry_file_unverified';end if;
 return private.inquiry_file_metadata(array[p_id])->0;
end $function$

CREATE OR REPLACE FUNCTION public.service_verify_member_email_change(p_challenge_id uuid, p_user_id uuid, p_code_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  challenge private.member_email_change_challenges;
  peek_digest text;
  now_at timestamptz;
  new_email text;
begin
  if p_challenge_id is null or p_user_id is null
    or p_code_digest is null or p_code_digest !~ '^[A-Za-z0-9_-]{32,128}$' then
    raise invalid_parameter_value using message = 'invalid_member_email_change';
  end if;

  select c.email_digest into peek_digest from private.member_email_change_challenges c
    where c.id = p_challenge_id and c.user_id = p_user_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  if private.is_account_write_fenced(p_user_id) then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-email:user:' || p_user_id::text, 0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-email:address:' || peek_digest, 0));

  select * into challenge from private.member_email_change_challenges c
    where c.id = p_challenge_id and c.user_id = p_user_id
    for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if challenge.status <> 'pending' then
    return jsonb_build_object('ok', false, 'reason', challenge.status);
  end if;

  now_at := clock_timestamp();
  if challenge.expires_at <= now_at then
    update private.member_email_change_challenges
      set status = 'expired', resolved_at = now_at, email = null
      where id = challenge.id;
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;

  if challenge.code_digest <> p_code_digest then
    if challenge.attempts + 1 >= 5 then
      update private.member_email_change_challenges
        set attempts = challenge.attempts + 1, status = 'exhausted', resolved_at = now_at, email = null
        where id = challenge.id;
      return jsonb_build_object('ok', false, 'reason', 'exhausted');
    end if;
    update private.member_email_change_challenges
      set attempts = challenge.attempts + 1
      where id = challenge.id;
    return jsonb_build_object('ok', false, 'reason', 'mismatch', 'remainingAttempts', 5 - (challenge.attempts + 1));
  end if;

  -- 요청 뒤 조건이 바뀌었으면(정지·이미 바꾼 이메일) 닫는다.
  if exists (select 1 from public.profiles p where p.id = p_user_id and p.suspended_at is not null)
    or not private.member_login_email_unusable(p_user_id) then
    update private.member_email_change_challenges
      set status = 'refused', resolved_at = now_at, email = null
      where id = challenge.id;
    return jsonb_build_object('ok', false, 'reason', 'not_eligible');
  end if;

  new_email := challenge.email;
  if exists (select 1 from auth.users u where pg_catalog.lower(u.email) = new_email and u.id <> p_user_id) then
    update private.member_email_change_challenges
      set status = 'email_taken', resolved_at = now_at, email = null
      where id = challenge.id;
    return jsonb_build_object('ok', false, 'reason', 'email_taken');
  end if;

  update private.member_email_change_challenges
    set status = 'verified', resolved_at = now_at, email = null
    where id = challenge.id;
  return jsonb_build_object('ok', true, 'email', new_email);
end;
$function$

CREATE OR REPLACE FUNCTION public.service_verify_member_phone_verification(p_challenge_id uuid, p_user_id uuid, p_code_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  challenge private.member_phone_verification_challenges;
  peek_digest text;
  now_at timestamptz;
  released_user uuid;
begin
  if p_challenge_id is null or p_user_id is null
    or p_code_digest is null or p_code_digest !~ '^[A-Za-z0-9_-]{32,128}$' then
    raise invalid_parameter_value using message = 'invalid_member_phone_verification';
  end if;

  select c.phone_digest into peek_digest from private.member_phone_verification_challenges c
    where c.id = p_challenge_id and c.user_id = p_user_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  if private.is_account_write_fenced(p_user_id) then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-phone:user:' || p_user_id::text, 0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-phone:number:' || peek_digest, 0));

  select * into challenge from private.member_phone_verification_challenges c
    where c.id = p_challenge_id and c.user_id = p_user_id
    for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if challenge.status = 'verified' then
    return jsonb_build_object('ok', true, 'replayed', true);
  end if;
  if challenge.status <> 'pending' then
    return jsonb_build_object('ok', false, 'reason', challenge.status);
  end if;

  now_at := clock_timestamp();
  if challenge.expires_at <= now_at then
    update private.member_phone_verification_challenges
      set status = 'expired', resolved_at = now_at, phone_e164 = null
      where id = challenge.id;
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;

  if challenge.code_digest <> p_code_digest then
    if challenge.attempts + 1 >= 5 then
      update private.member_phone_verification_challenges
        set attempts = challenge.attempts + 1, status = 'exhausted', resolved_at = now_at, phone_e164 = null
        where id = challenge.id;
      return jsonb_build_object('ok', false, 'reason', 'exhausted');
    end if;
    update private.member_phone_verification_challenges
      set attempts = challenge.attempts + 1
      where id = challenge.id;
    return jsonb_build_object('ok', false, 'reason', 'mismatch', 'remainingAttempts', 5 - (challenge.attempts + 1));
  end if;

  if exists (select 1 from public.profiles p where p.id = p_user_id and p.suspended_at is not null) then
    return jsonb_build_object('ok', false, 'reason', 'account_unavailable');
  end if;
  -- 요청 뒤 동의·연령 조건이 깨졌으면 기록하지 않고 요청을 닫는다(번호 원문도 지운다).
  if not private.member_phone_onboarding_ready(p_user_id) then
    update private.member_phone_verification_challenges
      set status = 'refused', resolved_at = now_at, phone_e164 = null
      where id = challenge.id;
    return jsonb_build_object('ok', false, 'reason', 'onboarding_required');
  end if;

  -- 같은 번호를 인증해 둔 다른 계정이 있으면 번호를 옮기고, 그 계정에는 재인증 필요 표시만 남긴다.
  for released_user in
    update private.member_phone_numbers n
      set phone_e164 = null, verified_at = null, released_at = now_at, updated_at = now_at
      where n.phone_e164 = challenge.phone_e164 and n.user_id <> p_user_id
      returning n.user_id
  loop
    insert into private.member_phone_verification_events (user_id, event, phone_digest, occurred_at)
      values (released_user, 'released', challenge.phone_digest, now_at);
  end loop;

  insert into private.member_phone_numbers (user_id, phone_e164, verified_at, released_at, updated_at)
    values (p_user_id, challenge.phone_e164, now_at, null, now_at)
    on conflict (user_id) do update
      set phone_e164 = excluded.phone_e164, verified_at = excluded.verified_at, released_at = null,
        updated_at = excluded.updated_at;
  insert into private.member_phone_verification_events (user_id, event, phone_digest, occurred_at)
    values (p_user_id, 'verified', challenge.phone_digest, now_at);
  update private.member_phone_verification_challenges
    set status = 'verified', resolved_at = now_at, phone_e164 = null
    where id = challenge.id;

  return jsonb_build_object('ok', true, 'replayed', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_ip_notification_preferences(target_ip_id text, target_notify_drops boolean DEFAULT NULL::boolean, target_notify_events boolean DEFAULT NULL::boolean, target_auto_follow boolean DEFAULT false)
 RETURNS TABLE(notify_drops boolean, notify_events boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := (select auth.uid());
  updated_notify_drops boolean;
  updated_notify_events boolean;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if target_auto_follow then
    perform public.follow_ip(target_ip_id);
  end if;

  update public.ip_follows as follow
  set
    notify_drops = coalesce(target_notify_drops, follow.notify_drops),
    notify_events = coalesce(target_notify_events, follow.notify_events)
  where follow.user_id = actor_id
    and follow.ip_id = target_ip_id
  returning follow.notify_drops, follow.notify_events
  into updated_notify_drops, updated_notify_events;

  if not found then
    raise exception 'notification_preferences_not_found' using errcode = 'P0002';
  end if;

  return query
    select updated_notify_drops, updated_notify_events;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_member_activity_consent(p_choice text, p_expected_revision bigint, p_expected_actor uuid, p_expected_session uuid, p_notice_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c private.member_activity_consents; s private.member_activity_settings;
begin
 select * into s from private.member_activity_settings where singleton for share;
 perform private.require_member_activity_identity(p_expected_actor,p_expected_session);
 if p_choice is null or p_choice not in ('accepted','declined') or p_expected_revision is null or p_expected_revision<0 or p_notice_version is distinct from 'member-activity-v1' then
  raise invalid_parameter_value using message='invalid_member_activity_choice';end if;
 if p_choice='accepted' and not s.enabled then raise object_not_in_prerequisite_state using message='member_activity_disabled';end if;
 select * into c from private.member_activity_consents where user_id=p_expected_actor for update;
 if coalesce(c.revision,0)<>p_expected_revision then raise sqlstate 'PT409' using message='member_activity_choice_changed';end if;
 if c.choice is distinct from p_choice then
  insert into private.member_activity_consents(user_id,choice,notice_version,revision,accepted_at)
   values(p_expected_actor,p_choice,p_notice_version,coalesce(c.revision,0)+1,case when p_choice='accepted' then clock_timestamp() end)
   on conflict(user_id) do update set choice=excluded.choice,notice_version=excluded.notice_version,revision=excluded.revision,accepted_at=excluded.accepted_at,updated_at=clock_timestamp();
 end if;
 if p_choice='declined' then delete from private.member_activity_events where user_id=p_expected_actor;end if;
 return public.member_activity_state();
end $function$

CREATE OR REPLACE FUNCTION public.set_my_default_address_book_entry(p_entry_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid;
begin
  actor := private.address_book_actor(true);

  if p_entry_id is null or not exists (
    select 1 from public.address_book_entries where id = p_entry_id and user_id = actor
  ) then
    raise no_data_found using message = 'address_book_entry_missing';
  end if;

  update public.address_book_entries
  set is_default = false
  where user_id = actor and is_default and id <> p_entry_id;

  update public.address_book_entries
  set is_default = true
  where id = p_entry_id and user_id = actor and not is_default;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_gift_claim_refund_account(p_gift_id uuid, p_claim_id uuid, p_operation_id uuid, p_bank_name text, p_account_number text, p_account_holder text, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare actor uuid:=auth.uid();gift private.gift_intents;claim public.order_cancellation_requests;purchase public.orders;previous private.gift_claim_operations;request_hash text;result jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 if p_operation_id is null or p_bank_name is null or p_bank_name<>btrim(p_bank_name) or length(p_bank_name) not between 1 and 40
  or p_account_number is null or p_account_number!~'^[0-9-]{8,30}$' or p_account_holder is null or p_account_holder<>btrim(p_account_holder) or length(p_account_holder) not between 1 and 40 then
  raise invalid_parameter_value using message='invalid_refund_account';end if;
 select * into gift from private.gift_intents where id=p_gift_id and sender_id=actor;
 if not found or gift.order_id is null then raise no_data_found using message='gift_not_found';end if;
 perform private.gift_lock_subjects(array[actor,gift.recipient_id]);
 perform pg_advisory_xact_lock(hashtextextended('gift-claim-operation:'||p_operation_id,0));
 request_hash:=encode(extensions.digest(jsonb_build_array(p_operation_id,p_gift_id,p_claim_id,p_bank_name,p_account_number,p_account_holder)::text,'sha256'),'hex');
 select * into previous from private.gift_claim_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>actor or previous.gift_id<>p_gift_id or previous.kind<>'refund_account' or previous.request_hash<>request_hash then raise unique_violation using message='gift_operation_conflict';end if;
  return jsonb_build_object('receipt',previous.result,'context',private.gift_claim_context(actor,p_gift_id));
 end if;
 select * into purchase from public.orders where id=gift.order_id for update;
 perform id from public.order_shipments where order_id=purchase.id order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id and order_id=purchase.id for update;
 if not found or (purchase.payment_method<>'bank_transfer' and claim.stage<>'needs_review') or claim.claim_type='exchange' or claim.stage not in('requested','in_review','collecting','collected','on_hold','processing','needs_review') then raise check_violation using message='gift_refund_account_closed';end if;
 if exists(select 1 from private.bank_transfer_claim_refunds where claim_id=claim.id)
  or exists(select 1 from public.refunds r join public.payments p on p.id=r.payment_id where p.purpose='order' and p.ref_id=purchase.id
   and(r.filed_at is not null or r.completed_at is not null or r.method is not null)) then raise check_violation using message='gift_refund_account_closed';end if;
 if exists(select 1 from private.claim_refund_accounts where claim_id=claim.id) then raise check_violation using message='gift_refund_account_exists';end if;
 insert into private.claim_refund_accounts(claim_id,bank_name,account_number,account_holder,masked_account,masked_holder)
 values(claim.id,p_bank_name,p_account_number,p_account_holder,p_bank_name||' '||public.mask_refund_account_number(p_account_number),public.mask_refund_account_holder(p_account_holder));
 result:=jsonb_build_object('operationId',p_operation_id,'kind','refund_account','claimId',claim.id);
 insert into private.gift_claim_operations(id,actor_id,gift_id,kind,request_hash,result) values(p_operation_id,actor,gift.id,'refund_account',request_hash,result);
 insert into public.audit_log(actor_id,action,target,diff) values(actor,'gift.refund_account_confirmed','order:'||purchase.id,jsonb_build_object('claimId',claim.id,'giftId',gift.id));
 return jsonb_build_object('receipt',result,'context',private.gift_claim_context(actor,gift.id));
end $function$

CREATE OR REPLACE FUNCTION public.set_my_inquiry_satisfaction(p_operation_id uuid, p_inquiry_id uuid, p_expected_actor_id uuid, p_expected_session_id uuid, p_expected_answer_id uuid, p_expected_revision bigint, p_desired_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare fingerprint jsonb; old_operation private.inquiry_satisfaction_operations%rowtype; current_state jsonb;
 before_value text; after_revision bigint; outcome text; stamp timestamptz; receipt jsonb;
begin
 fingerprint:=private.inquiry_satisfaction_request(p_operation_id,p_inquiry_id,p_expected_actor_id,p_expected_session_id,p_expected_answer_id,p_expected_revision,p_desired_value,true);
 select * into old_operation from private.inquiry_satisfaction_operations where actor_id=p_expected_actor_id and operation_id=p_operation_id;
 if found then
  if old_operation.request_fingerprint is distinct from fingerprint then raise sqlstate 'PT409' using message='inquiry_satisfaction_operation_conflict';end if;
  return jsonb_build_object('operation','completed','receipt',old_operation.receipt,'current',public.get_my_inquiry_satisfaction(p_inquiry_id));
 end if;
 perform 1 from public.inquiries where id=p_inquiry_id and user_id=p_expected_actor_id for update nowait;
 if not found then raise no_data_found using message='inquiry_satisfaction_inquiry_unavailable';end if;
 perform 1 from private.inquiry_satisfaction_state where inquiry_id=p_inquiry_id for update nowait;
 current_state:=private.inquiry_satisfaction_current(p_inquiry_id);
 if (current_state->>'answerId')::uuid is distinct from p_expected_answer_id then raise sqlstate 'PT409' using message='inquiry_satisfaction_answer_changed';end if;
 if (current_state->>'revision')::bigint<>p_expected_revision then raise sqlstate 'PT409' using message='inquiry_satisfaction_revision_conflict';end if;
 -- Lock the current answer to prevent staff-profile/message deletion from
 -- removing it between CAS and commit; NOWAIT avoids reversing FK lock order.
 perform 1 from public.inquiry_messages where id=p_expected_answer_id and inquiry_id=p_inquiry_id and author='staff' for share nowait;
 if not found then raise sqlstate 'PT409' using message='inquiry_satisfaction_answer_changed';end if;
 stamp:=clock_timestamp();before_value:=current_state->>'value'; after_revision:=p_expected_revision;outcome:='unchanged';
 if before_value is distinct from p_desired_value then
  after_revision:=p_expected_revision+1;outcome:='changed';
  insert into private.inquiry_satisfaction_state(inquiry_id,latest_answer_id,value_answer_id,value,rated_at,revision,updated_at)
  values(p_inquiry_id,p_expected_answer_id,case when p_desired_value is null then null else p_expected_answer_id end,
   p_desired_value,case when p_desired_value is null then null else stamp end,after_revision,stamp)
  on conflict(inquiry_id) do update set latest_answer_id=excluded.latest_answer_id,value_answer_id=excluded.value_answer_id,
   value=excluded.value,rated_at=excluded.rated_at,revision=excluded.revision,updated_at=excluded.updated_at;
  -- audit_log.actor_id has a legacy NO ACTION FK. Keep the actor identifier in
  -- the minimal event payload so a new rating cannot block account FK cleanup.
  insert into public.audit_log(actor_id,action,target,diff) values(null,'inquiry.satisfaction.changed','inquiries:'||p_inquiry_id::text,
   jsonb_build_object('actorId',p_expected_actor_id,'operationId',p_operation_id,'inquiryId',p_inquiry_id,'answerId',p_expected_answer_id,
    'beforeValue',before_value,'afterValue',p_desired_value,'beforeRevision',p_expected_revision,'afterRevision',after_revision));
 end if;
 receipt:=fingerprint||jsonb_build_object('beforeValue',before_value,'afterValue',p_desired_value,'beforeRevision',p_expected_revision,
  'afterRevision',after_revision,'outcome',outcome,'createdAt',stamp);
 insert into private.inquiry_satisfaction_operations(actor_id,operation_id,session_id,inquiry_id,answer_id,expected_revision,desired_value,request_fingerprint,
  before_value,after_value,before_revision,after_revision,outcome,created_at,receipt)
 values(p_expected_actor_id,p_operation_id,p_expected_session_id,p_inquiry_id,p_expected_answer_id,p_expected_revision,p_desired_value,fingerprint,
  before_value,p_desired_value,p_expected_revision,after_revision,outcome,stamp,receipt);
 return jsonb_build_object('operation','completed','receipt',receipt,'current',public.get_my_inquiry_satisfaction(p_inquiry_id));
exception when lock_not_available then raise sqlstate 'PT409' using message='inquiry_satisfaction_retry';
end $function$

CREATE OR REPLACE FUNCTION public.set_my_marketing_consents_v2(p_email boolean, p_sms boolean, p_kakao boolean, p_notice_version text, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); profile_consents jsonb; changed_at timestamptz:=clock_timestamp(); derived boolean;
begin
 if actor is null then raise insufficient_privilege using message='marketing_consent_auth_required'; end if;
 if p_email is null or p_sms is null or p_kakao is null or p_notice_version is distinct from 'marketing-channels-v2'
  or p_source is null or p_source not in ('onboarding','settings') then
  raise invalid_parameter_value using message='invalid_marketing_consent'; end if;
 if private.is_account_write_fenced(actor) then
  raise object_not_in_prerequisite_state using message='account_deletion_write_fenced'; end if;
 select p.consents into profile_consents from public.profiles p where p.id=actor for update;
 if not found then raise insufficient_privilege using message='marketing_consent_auth_required'; end if;
 -- 정지 회원은 새로 동의할 수 없다(탈퇴 처리 직후 남은 토큰 포함). 철회는 언제나 받는다.
 if exists(select 1 from public.profiles p where p.id=actor and p.suspended_at is not null)
  and ((p_email and not exists(select 1 from private.customer_marketing_consents c where c.user_id=actor and c.channel='email' and c.agreed))
   or (p_sms and not exists(select 1 from private.customer_marketing_consents c where c.user_id=actor and c.channel='sms' and c.agreed))
   or (p_kakao and not exists(select 1 from private.customer_marketing_consents c where c.user_id=actor and c.channel='kakao' and c.agreed))) then
  raise insufficient_privilege using message='account_suspended'; end if;
 perform private.write_customer_marketing_consent(actor,'email',p_email,p_notice_version,p_source,changed_at);
 perform private.write_customer_marketing_consent(actor,'sms',p_sms,p_notice_version,p_source,changed_at);
 perform private.write_customer_marketing_consent(actor,'kakao',p_kakao,p_notice_version,p_source,changed_at);
 derived:=p_email or p_sms or p_kakao;
 if profile_consents->'marketing' is distinct from to_jsonb(derived) then
  update public.profiles set consents=coalesce(consents,'{}'::jsonb)||jsonb_build_object('marketing',derived) where id=actor;
 end if;
 return private.customer_marketing_consent_document(actor);
end $function$

CREATE OR REPLACE FUNCTION public.set_my_marketing_consents(p_email boolean, p_sms boolean, p_notice_version text, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); profile_consents jsonb; changed_at timestamptz:=clock_timestamp(); derived boolean;
begin
 if actor is null then raise insufficient_privilege using message='marketing_consent_auth_required'; end if;
 if p_email is null or p_sms is null or p_notice_version is distinct from 'marketing-channels-v1'
  or p_source is null or p_source not in ('onboarding','settings') then
  raise invalid_parameter_value using message='invalid_marketing_consent'; end if;
 -- 계정 잠금(account-action)을 회원 행보다 먼저 잡는다 — 결제 확정·미결제 주문 닫기가 계정 잠금 →
 -- 회원 행(등급 재산정) 순서라, 반대로 잡으면 같은 회원의 동시 처리와 교착한다(ADR-0026 잠금 순서).
 if private.is_account_write_fenced(actor) then
  raise object_not_in_prerequisite_state using message='account_deletion_write_fenced'; end if;
 -- 회원 행 잠금으로 같은 회원의 동시 저장(다른 탭·온보딩 재제출·옛 앱 직접 쓰기)을 직렬화한다.
 select p.consents into profile_consents from public.profiles p where p.id=actor for update;
 if not found then raise insufficient_privilege using message='marketing_consent_auth_required'; end if;
 -- 정지 회원은 새로 동의할 수 없다(탈퇴 처리 직후 남은 토큰 포함). 철회는 언제나 받는다.
 if exists(select 1 from public.profiles p where p.id=actor and p.suspended_at is not null)
  and ((p_email and not exists(select 1 from private.customer_marketing_consents c where c.user_id=actor and c.channel='email' and c.agreed))
   or (p_sms and not exists(select 1 from private.customer_marketing_consents c where c.user_id=actor and c.channel='sms' and c.agreed))) then
  raise insufficient_privilege using message='account_suspended'; end if;
 perform private.write_customer_marketing_consent(actor,'email',p_email,p_notice_version,p_source,changed_at);
 perform private.write_customer_marketing_consent(actor,'sms',p_sms,p_notice_version,p_source,changed_at);
 derived:=p_email or p_sms or exists(select 1 from private.customer_marketing_consents c where c.user_id=actor and c.channel='kakao' and c.agreed);
 -- 원장을 먼저 쓰고 파생값을 맞춘다. 아래 동기화 트리거는 파생값과 원장이 같으면 아무것도 하지 않는다.
 if profile_consents->'marketing' is distinct from to_jsonb(derived) then
  update public.profiles set consents=coalesce(consents,'{}'::jsonb)||jsonb_build_object('marketing',derived) where id=actor;
 end if;
 return private.customer_marketing_consent_document(actor);
end $function$

CREATE OR REPLACE FUNCTION public.set_my_order_claim_refund_account(p_order_id uuid, p_claim_id uuid, p_operation_id uuid, p_expected_revision integer, p_bank_name text, p_account_number text, p_account_holder text, p_expected_actor_id uuid, p_expected_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare purchase public.orders;claim public.order_cancellation_requests;previous private.order_claim_refund_account_operations;
 request_hash text;blocker text;result_revision integer;
begin
 perform private.require_claim_refund_account_identity(p_expected_actor_id,p_expected_session_id);
 if p_order_id is null or p_claim_id is null or p_operation_id is null or p_expected_revision is null or p_expected_revision<0
  or p_bank_name is null or p_bank_name<>btrim(p_bank_name) or char_length(p_bank_name) not between 1 and 40 or p_bank_name~'[[:cntrl:]]'
  or p_account_number is null or p_account_number!~'^[0-9-]{8,30}$' or p_account_number!~'[0-9]'
  or p_account_holder is null or p_account_holder<>btrim(p_account_holder) or char_length(p_account_holder) not between 1 and 40 or p_account_holder~'[[:cntrl:]]'
  then raise invalid_parameter_value using message='invalid_claim_refund_account';end if;
 if not exists(select 1 from public.orders o join public.order_cancellation_requests c on c.order_id=o.id
  where o.id=p_order_id and o.user_id=p_expected_actor_id and c.id=p_claim_id)
  or exists(select 1 from private.gift_intents where order_id=p_order_id) then raise sqlstate 'PT404' using message='claim_not_found';end if;
 -- Match existing account-deletion, claim, and refund ordering. Existing-order
 -- recovery remains available to its owner even when new purchases are fenced.
 perform private.lock_operator_subjects(array[p_expected_actor_id]);
 perform private.lock_claim_refund_account_session(p_expected_actor_id,p_expected_session_id);
 perform pg_advisory_xact_lock(hashtextextended('claim-refund-account:'||p_operation_id::text,0));
 request_hash:=encode(extensions.digest(jsonb_build_array(p_operation_id,p_order_id,p_claim_id,p_expected_actor_id,
  p_expected_session_id,p_expected_revision,p_bank_name,p_account_number,p_account_holder)::text,'sha256'),'hex');
 select * into previous from private.order_claim_refund_account_operations where id=p_operation_id;
 if found then
  if previous.actor_id<>p_expected_actor_id or previous.session_id<>p_expected_session_id or previous.order_id<>p_order_id
   or previous.claim_id<>p_claim_id or previous.expected_revision<>p_expected_revision then
   raise unique_violation using message='refund_account_request_conflict';end if;
  if previous.state='sealed' then raise check_violation using message='refund_account_request_sealed';end if;
  if previous.request_hash is null then raise check_violation using message='refund_account_request_expired';end if;
  if previous.request_hash<>request_hash then raise unique_violation using message='refund_account_request_conflict';end if;
  return private.order_claim_refund_account_receipt(p_operation_id,p_expected_actor_id,p_expected_session_id);
 end if;
 select * into purchase from public.orders where id=p_order_id and user_id=p_expected_actor_id for update;
 if not found then raise sqlstate 'PT404' using message='claim_not_found';end if;
 perform id from public.order_shipments where order_id=purchase.id order by id for update;
 select * into claim from public.order_cancellation_requests where id=p_claim_id and order_id=purchase.id for update;
 if not found then raise sqlstate 'PT404' using message='claim_not_found';end if;
 if claim.claim_revision<>p_expected_revision then raise sqlstate 'PT409' using message='claim_changed';end if;
 perform id from public.payments where purpose='order' and ref_id=purchase.id order by id for update;
 perform r.id from public.refunds r join public.payments p on p.id=r.payment_id
  where p.purpose='order' and p.ref_id=purchase.id order by r.id for update of r;
 blocker:=private.order_claim_refund_account_blocker(claim,purchase);
 if blocker is not null then raise check_violation using message=blocker;end if;
 insert into private.claim_refund_accounts(claim_id,bank_name,account_number,account_holder,masked_account,masked_holder)
 values(claim.id,p_bank_name,p_account_number,p_account_holder,p_bank_name||' '||public.mask_refund_account_number(p_account_number),public.mask_refund_account_holder(p_account_holder));
 update public.order_cancellation_requests set updated_at=clock_timestamp() where id=claim.id returning claim_revision into result_revision;
 insert into private.order_claim_refund_account_operations(id,actor_id,session_id,order_id,claim_id,expected_revision,result_revision,state,request_hash)
 values(p_operation_id,p_expected_actor_id,p_expected_session_id,purchase.id,claim.id,p_expected_revision,result_revision,'saved',request_hash);
 insert into public.audit_log(id,actor_id,action,target,diff) values(p_operation_id,p_expected_actor_id,'order.claim_refund_account_confirmed','order:'||purchase.id,
  jsonb_build_object('claimId',claim.id,'claimType',claim.claim_type,'revision',p_expected_revision,'resultRevision',result_revision));
 return private.order_claim_refund_account_receipt(p_operation_id,p_expected_actor_id,p_expected_session_id);
end $function$

CREATE OR REPLACE FUNCTION public.set_post_like(target_post_id uuid, should_like boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := auth.uid();
  post_ip_id text;
  current_liked boolean;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  select posts.ip_id
    into post_ip_id
    from public.posts
    where posts.id = target_post_id
      and posts.status = 'visible';

  if not found then
    raise exception 'post_not_visible' using errcode = '42501';
  end if;

  if coalesce(should_like, false) then
    insert into public.likes (post_id, user_id)
    values (target_post_id, actor_id)
    on conflict (post_id, user_id) do nothing;
  else
    delete from public.likes
    where post_id = target_post_id
      and user_id = actor_id;
  end if;

  select exists (
    select 1
    from public.likes
    where likes.post_id = target_post_id
      and likes.user_id = actor_id
  ) into current_liked;

  return jsonb_build_object('liked', current_liked, 'ipId', post_ip_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_review_helpful(p_good_id text, p_review_id uuid, p_marked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;review_good text;review_author uuid;scope_ids text[];helpful_count bigint;marked boolean;session_id uuid;
begin
 if p_good_id is null or p_good_id!~'^[A-Za-z0-9_-]{1,200}$' or p_review_id is null or p_marked is null then
  raise invalid_parameter_value using message='invalid_review_helpful_request';end if;
 actor:=private.review_helpful_viewer_id();
 if actor is null then raise invalid_authorization_specification using message='review_helpful_auth_required';end if;
 session_id:=(auth.jwt()->>'session_id')::uuid;
 -- Same account key as deletion/participation, before profile/catalog/review rows.
 -- It also serializes simultaneous desired-state retries by the same participant.
 perform private.lock_account_action_subject(actor);
 perform 1 from auth.users where id=actor for share nowait;
 perform 1 from public.profiles where id=actor for share nowait;
 perform 1 from auth.sessions where id=session_id and user_id=actor for share nowait;
 if private.review_helpful_viewer_id() is distinct from actor then
  raise invalid_authorization_specification using message='review_helpful_auth_required';end if;
 if not private.review_helpful_actor_is_active(actor) then
  raise insufficient_privilege using message='review_helpful_account_unavailable';end if;
 -- Group structure writers own this key exclusively. Taking it shared first
 -- keeps the original review's membership stable without a new topology system.
 if not pg_try_advisory_xact_lock_shared(hashtextextended('goods-stock-successor-topology:v1',0)) then
  raise sqlstate 'PT409' using message='review_helpful_retry';end if;
 select good_id,user_id into review_good,review_author from public.reviews where id=p_review_id;
 if not found then raise no_data_found using message='review_helpful_review_unavailable';end if;
 perform 1 from public.goods where id=any(array[p_good_id,review_good]) order by id for share nowait;
 perform 1 from public.ips where id in(select ip_id from public.goods where id=any(array[p_good_id,review_good])) order by id for share nowait;
 -- Share blocks moderation/edit/delete while allowing different participants to
 -- mark one review concurrently. The unique key and account key prevent doubles.
 perform 1 from public.reviews where id=p_review_id and good_id=review_good and user_id=review_author and status='visible' for share nowait;
 if not found then raise no_data_found using message='review_helpful_review_unavailable';end if;
 scope_ids:=private.goods_group_review_good_ids(p_good_id);
 if not (review_good=any(scope_ids)) then raise no_data_found using message='review_helpful_review_unavailable';end if;
 if review_author=actor then raise insufficient_privilege using message='review_helpful_own_review';end if;
 if p_marked then
  insert into private.review_helpful_votes(review_id,user_id) values(p_review_id,actor) on conflict(review_id,user_id) do nothing;
 else
  delete from private.review_helpful_votes where review_id=p_review_id and user_id=actor;
 end if;
 select count(*)::bigint,coalesce(bool_or(user_id=actor),false) into helpful_count,marked
 from private.review_helpful_votes where review_id=p_review_id;
 return jsonb_build_object('reviewId',p_review_id,'helpfulCount',helpful_count,'helpfulByMe',marked,'canMarkHelpful',true);
exception when lock_not_available then raise sqlstate 'PT409' using message='review_helpful_retry';
end $function$

CREATE OR REPLACE FUNCTION public.set_store_analytics_collection(p_enabled boolean, p_notice_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare at_time timestamptz; current private.store_analytics_settings;
begin
 perform private.store_analytics_require_service();
 if p_enabled is null or p_notice_version is distinct from 'analytics-v1' then raise invalid_parameter_value using message='analytics_invalid_activation';end if;
 select * into current from private.store_analytics_settings where id for update;
 at_time:=clock_timestamp();
 if current.enabled is distinct from p_enabled then
  update private.store_analytics_settings set enabled=p_enabled,revision=revision+1,
   activated_at=case when p_enabled then coalesce(activated_at,at_time) else activated_at end where id;
  if p_enabled then insert into private.store_analytics_windows(started_at) values(at_time);
  else update private.store_analytics_windows set ended_at=at_time where ended_at is null;end if;
 end if;
 return public.get_store_analytics_state();
end $function$

CREATE OR REPLACE FUNCTION public.settle_delivered_orders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '100ms'
AS $function$
declare item record;confirmation private.order_purchase_confirmations;at_value timestamptz;n integer:=0;
begin
 if not (select auto_enabled from private.purchase_confirmation_policy where singleton) then return 0;end if;
 for item in select o.id,o.user_id from public.orders o join private.order_purchase_confirmations pc on pc.order_id=o.id
  where o.status='delivered' and not pc.held and pc.confirmed_at is null and pc.auto_due_at<=clock_timestamp()
   and private.purchase_confirmation_candidate(o.id)
  order by o.user_id,pc.auto_due_at,o.id limit 1000 loop
  begin
  -- 주문마다 하위 트랜잭션. 결제·선물·리뷰 경로와 같은 순서(행위자 → 계정 작업 → 프로필 → 주문 → 확정 행)로 기다리지 않고
  -- 잡는다(키는 gift_lock_subjects·lock_account_action_subject와 같다). 못 잡거나 확정할 수 없으면 PC001로 이 주문만 되돌린다.
  if not pg_try_advisory_xact_lock(hashtextextended(item.user_id::text,0))
   or not pg_try_advisory_xact_lock(hashtextextended('account-action:'||item.user_id::text,0)) then raise sqlstate 'PC001';end if;
  perform 1 from public.profiles where id=item.user_id and suspended_at is null for no key update skip locked;
  if not found then raise sqlstate 'PC001';end if;
  perform 1 from public.orders where id=item.id and status='delivered' for no key update skip locked;
  if not found then raise sqlstate 'PC001';end if;
  select * into confirmation from private.order_purchase_confirmations where order_id=item.id for update skip locked;
  if not found then raise sqlstate 'PC001';end if;
  at_value:=clock_timestamp();
  if not (select auto_enabled from private.purchase_confirmation_policy where singleton) or confirmation.held or confirmation.confirmed_at is not null
   or confirmation.auto_due_at is null or confirmation.auto_due_at>at_value or not private.purchase_confirmation_eligible(item.id) then raise sqlstate 'PC001';end if;
  update private.order_purchase_confirmations set revision=revision+1,confirmed_at=at_value,confirmation_kind='automatic' where order_id=item.id;
  insert into private.purchase_confirmation_events(id,order_id,kind,note,request,created_at)
   values(gen_random_uuid(),item.id,'automatic','',jsonb_build_object('policy',confirmation.policy_snapshot,'dueAt',confirmation.auto_due_at),at_value);
  update public.orders set status='done',done_at=at_value where id=item.id and status='delivered';
  n:=n+1;
  exception when sqlstate 'PC001' or lock_not_available or deadlock_detected then
   -- 경합(잠금 실패, 확정 뒤 trigger의 lock_timeout 초과)이나 자격 변화: 이 주문의 잠금·변경을 모두 되돌리고 다음 실행에 맡긴다.
   null;
  end;
 end loop;return n;
end $function$

CREATE OR REPLACE FUNCTION public.start_store_analytics_session(p_token_hash text, p_notice_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare at_time timestamptz;
begin
 perform private.store_analytics_require_service();
 if p_token_hash is null or p_token_hash!~'^[0-9a-f]{64}$' or p_notice_version is distinct from 'analytics-v1' then
  raise invalid_parameter_value using message='analytics_invalid_session';end if;
 perform 1 from private.store_analytics_settings where id and enabled for share;
 if not found then raise object_not_in_prerequisite_state using message='analytics_disabled';end if;
 at_time:=clock_timestamp();
 perform private.store_analytics_rate('session-start',1000,at_time);
 insert into private.store_analytics_sessions(token_hash,notice_version,created_at,last_seen_at)
 values(p_token_hash,p_notice_version,at_time,at_time);
 return jsonb_build_object('startedAt',at_time);
end $function$

CREATE OR REPLACE FUNCTION public.submit_community_report(target_type public.report_target, target_id text, reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := auth.uid();
  target_uuid uuid;
  normalized_reason text := nullif(btrim(reason), '');
  target_ip_id text := null;
  target_post_id uuid;
  inserted_report_id uuid;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if target_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'target_not_found' using errcode = '22023';
  end if;

  target_uuid := target_id::uuid;

  if target_type = 'post' then
    select posts.ip_id
      into target_ip_id
      from public.posts
      where posts.id = target_uuid
        and posts.status = 'visible';

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  elsif target_type = 'comment' then
    select comments.post_id
      into target_post_id
      from public.comments
      where comments.id = target_uuid;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;

    select posts.ip_id
      into target_ip_id
      from public.posts
      where posts.id = target_post_id
        and posts.status = 'visible'
      for share;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;

    perform 1
    from public.comments
    where comments.id = target_uuid
      and comments.post_id = target_post_id
      and comments.status = 'visible'
    for share;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  elsif target_type = 'review' then
    -- 리뷰는 IP가 아니라 굿즈에 매인다. 반환값의 ipId는 커뮤니티 피드 갱신용
    -- 힌트라 리뷰에는 해당이 없다 — 굿즈의 IP를 넣어 주면 신고 한 번이 엉뚱한
    -- IP 피드를 다시 그리게 만든다. null로 둔다.
    perform 1
    from public.reviews
    where reviews.id = target_uuid
      and reviews.status = 'visible'
    for share;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  elsif target_type = 'user' then
    perform 1
    from public.profiles
    where profiles.id = target_uuid;

    if not found then
      raise exception 'target_not_found' using errcode = '42501';
    end if;
  else
    raise exception 'target_not_found' using errcode = '22023';
  end if;

  insert into public.reports (target_type, target_id, reporter_id, reason)
  values (target_type, target_uuid::text, actor_id, normalized_reason)
  returning id into inserted_report_id;

  return jsonb_build_object('reportId', inserted_report_id, 'ipId', target_ip_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.unfollow_ip(target_ip_id text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_id uuid := auth.uid();
  deleted_count integer := 0;
  current_fans_count integer := 0;
begin
  if actor_id is null then
    raise exception 'auth_required' using errcode = '28000';
  end if;

  if not exists (select 1 from public.ips where id = target_ip_id) then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  delete from public.ip_follows
  where user_id = actor_id and ip_id = target_ip_id;

  get diagnostics deleted_count = row_count;

  if deleted_count > 0 then
    update public.ips
    set fans_count = greatest(fans_count - 1, 0),
        updated_at = now()
    where id = target_ip_id
    returning fans_count into current_fans_count;
  else
    select fans_count into current_fans_count
    from public.ips
    where id = target_ip_id;
  end if;

  return coalesce(current_fans_count, 0);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_good_review(target_review_id uuid, target_rating integer, target_body text, target_image_paths text[] DEFAULT '{}'::text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_body text := btrim(coalesce(target_body, ''));
  v_paths text[];
  v_status text;
  v_order_id uuid;
  v_delivered_at timestamptz;
  v_deadline timestamptz;
begin
  if v_actor is null then
    raise invalid_authorization_specification using message = 'auth_required';
  end if;

  perform private.gift_lock_subjects(array[v_actor]);
  perform private.lock_operator_subjects(array[v_actor]);
  perform private.assert_active_user(v_actor);
  if private.is_account_write_fenced(v_actor) then raise insufficient_privilege;end if;

  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_actor
      and profile.suspended_at is not null
  ) then
    raise insufficient_privilege using message = 'account_suspended';
  end if;

  if target_rating is null or target_rating not between 1 and 5 then
    raise invalid_parameter_value using message = 'invalid_review_rating';
  end if;
  if char_length(v_body) not between 5 and 1000 then
    raise invalid_parameter_value using message = 'invalid_review_body';
  end if;

  select order_id into v_order_id from public.reviews where id=target_review_id and user_id=v_actor;
  perform 1 from public.orders where id=v_order_id for update;
  select review.status, review.order_id, review.write_deadline_at
    into v_status, v_order_id, v_deadline
  from public.reviews as review
  where review.id = target_review_id
    and review.user_id = v_actor
  for update;

  if not found then
    raise no_data_found using message = 'review_not_found';
  end if;
  if v_status <> 'visible' then
    raise insufficient_privilege using message = 'review_hidden';
  end if;

  select target.delivered_at
    into v_delivered_at
  from public.orders as target
  where target.id = v_order_id;

  if v_delivered_at is null or now() > coalesce(v_deadline,private.review_write_deadline(v_delivered_at)) then
    raise check_violation using message = 'review_window_closed';
  end if;

  if not exists(select 1 from public.reviews r where r.id=target_review_id and (r.review_kind='ordinary' or private.review_event_purchase_eligible(r.order_id,r.user_id,r.good_id))) then raise check_violation using message='review_purchase_ineligible';end if;
  v_paths := private.assert_own_review_image_paths(target_image_paths, v_actor);

  update public.reviews
  set
    rating = target_rating::smallint,
    body = v_body,
    image_paths = v_paths,
    edited_at = now()
  where id = target_review_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_gift_address(p_id uuid, p_address jsonb, p_expected_revision bigint, p_operation_id uuid, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare actor uuid:=auth.uid();gift private.gift_intents;address_value jsonb;request jsonb;begin
 if actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 gift:=private.gift_lock(p_id,actor);perform private.gift_require_actor(actor,false);
 if gift.recipient_id is distinct from actor then raise insufficient_privilege using message='gift_not_found';end if;
 address_value:=private.normalize_order_address_change(p_address);request:=jsonb_build_object('address',address_value,'revision',p_expected_revision);
 if private.gift_operation_replay(actor,p_id,'address_changed',request,p_operation_id) then return private.gift_operation_result(actor,p_operation_id);end if;
 if p_expected_revision is null or gift.revision<>p_expected_revision then raise sqlstate 'PT409' using message='gift_changed';end if;
 if gift.state<>'accepted' or gift.order_id is not null or gift.expires_at<=clock_timestamp() then raise check_violation using message='gift_address_closed';end if;
 delete from private.goods_transaction_quotes where actor_id=gift.sender_id and source->>'kind'='gift' and source->>'id'=gift.id::text and order_id is null;
 update private.gift_recipient_addresses set address=address_value,revision=revision+1,updated_at=clock_timestamp() where gift_id=p_id;
 update private.gift_intents set revision=revision+1,updated_at=clock_timestamp() where id=p_id;
 perform private.gift_record_operation(actor,p_id,'address_changed',request,p_operation_id);return private.gift_operation_result(actor,p_operation_id);
end $function$

CREATE OR REPLACE FUNCTION public.validate_reward_policy_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  pool_record public.card_pools%rowtype;
  good_ip_id text;
  pool_is_ready boolean := false;
  requires_eligible_pool boolean;
begin
  if new.trigger is distinct from 'order_paid' then
    raise exception 'invalid_reward_trigger' using errcode = '22023';
  end if;

  if new.min_amount is null or new.min_amount < 0 then
    raise exception 'invalid_min_amount' using errcode = '22023';
  end if;

  if new.tickets_per_grant is null or new.tickets_per_grant not between 1 and 100 then
    raise exception 'invalid_tickets_per_grant' using errcode = '22023';
  end if;

  if new.active_from is null then
    raise exception 'invalid_reward_policy_active_from' using errcode = '22004';
  end if;

  if new.active_to is not null and new.active_to <= new.active_from then
    raise exception 'invalid_reward_policy_active_window' using errcode = '23514';
  end if;

  select pool.*
    into pool_record
  from public.card_pools as pool
  where pool.id = new.pool_id
  for share;

  if not found then
    raise exception 'pool_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.ips
  where id = new.target_ip_id
  for key share;

  if not found then
    raise exception 'ip_not_found' using errcode = 'P0002';
  end if;

  if new.target_good_id is not null then
    select good.ip_id
      into good_ip_id
    from public.goods as good
    where good.id = new.target_good_id
    for key share;

    if not found then
      raise exception 'good_not_found' using errcode = 'P0002';
    end if;

    if good_ip_id is distinct from new.target_ip_id then
      raise exception 'reward_policy_good_ip_mismatch' using errcode = '23514';
    end if;
  end if;

  if tg_op = 'UPDATE'
    and old.pool_id is distinct from new.pool_id
    and exists (
      select 1
      from public.draw_tickets as ticket
      where ticket.reward_policy_id = old.id
    )
  then
    raise exception 'reward_policy_pool_locked' using errcode = '23514';
  end if;

  requires_eligible_pool := new.active
    or tg_op = 'INSERT'
    or (tg_op = 'UPDATE' and old.pool_id is distinct from new.pool_id);

  if requires_eligible_pool then
    if pool_record.active_to is not null and now() >= pool_record.active_to then
      raise exception 'reward_pool_not_ready' using errcode = '55000';
    end if;

    select
      count(*) = 5
      and coalesce(sum(pool_odd.probability), 0) = 1
      and coalesce(bool_and(pool_odd.probability between 0 and 1), false)
      and not exists (
        select 1
        from public.pool_odds as positive_odd
        where positive_odd.pool_id = new.pool_id
          and positive_odd.probability > 0
          and not exists (
            select 1
            from public.cards as card
            where card.pool_id = new.pool_id
              and card.rarity = positive_odd.rarity
          )
      )
      into pool_is_ready
    from public.pool_odds as pool_odd
    where pool_odd.pool_id = new.pool_id;

    if not pool_is_ready then
      raise exception 'reward_pool_not_ready' using errcode = '55000';
    end if;

    if new.active
      and greatest(new.active_from, pool_record.active_from)
      >= least(
        coalesce(new.active_to, 'infinity'::timestamptz),
        coalesce(pool_record.active_to, 'infinity'::timestamptz)
      )
    then
      raise exception 'reward_policy_pool_window_disjoint' using errcode = '23514';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.withdraw_my_gift_claim(p_gift_id uuid, p_claim_id uuid, p_operation_id uuid, p_expected_revision integer, p_expected_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare actor uuid:=auth.uid();receipt jsonb;begin
 if actor is null or actor is distinct from p_expected_actor_id then raise insufficient_privilege using message='gift_auth_changed';end if;
 if not exists(select 1 from private.gift_intents g join public.order_cancellation_requests c on c.order_id=g.order_id where g.id=p_gift_id and c.id=p_claim_id and(actor=g.sender_id or actor=g.recipient_id)) then raise no_data_found using message='gift_not_found';end if;
 receipt:=private.apply_order_claim_withdrawal(p_claim_id,p_operation_id,p_expected_revision,'선물 요청 철회',true,false);
 return jsonb_build_object('receipt',jsonb_build_object('operationId',p_operation_id,'kind','withdrawn','claimId',p_claim_id),'context',private.gift_claim_context(actor,p_gift_id));
end $function$

CREATE OR REPLACE FUNCTION storage.enforce_bucket_name_length()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if length(new.name) > 100 then
        raise exception 'bucket name "%" is too long (% characters). Max is 100.', new.name, length(new.name);
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION storage.list_objects_with_delimiter(_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''::text, next_token text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text)
 RETURNS TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;

    -- Configuration
    v_is_asc BOOLEAN;
    v_prefix TEXT;
    v_start TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_is_asc := lower(coalesce(sort_order, 'asc')) = 'asc';
    v_prefix := coalesce(prefix_param, '');
    v_start := CASE WHEN coalesce(next_token, '') <> '' THEN next_token ELSE coalesce(start_after, '') END;
    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);

    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE "C")
    IF v_prefix = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix, 1) = delimiter_param THEN
        v_upper_bound := left(v_prefix, -1) || chr(ascii(delimiter_param) + 1);
    ELSE
        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" >= $2 ' ||
                'AND o.name COLLATE "C" < $3 ORDER BY o.name COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" >= $2 ' ||
                'ORDER BY o.name COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" < $2 ' ||
                'AND o.name COLLATE "C" >= $3 ORDER BY o.name COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" < $2 ' ||
                'ORDER BY o.name COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- ========================================================================
    -- SEEK INITIALIZATION: Determine starting position
    -- ========================================================================
    IF v_start = '' THEN
        IF v_is_asc THEN
            v_next_seek := v_prefix;
        ELSE
            -- DESC without cursor: find the last item in range
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_prefix AND o.name COLLATE "C" < v_upper_bound
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix <> '' THEN
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            END IF;

            IF v_next_seek IS NOT NULL THEN
                v_next_seek := v_next_seek || delimiter_param;
            ELSE
                RETURN;
            END IF;
        END IF;
    ELSE
        -- Cursor provided: determine if it refers to a folder or leaf
        IF EXISTS (
            SELECT 1 FROM storage.objects o
            WHERE o.bucket_id = _bucket_id
              AND o.name COLLATE "C" LIKE v_start || delimiter_param || '%'
            LIMIT 1
        ) THEN
            -- Cursor refers to a folder
            IF v_is_asc THEN
                v_next_seek := v_start || chr(ascii(delimiter_param) + 1);
            ELSE
                v_next_seek := v_start || delimiter_param;
            END IF;
        ELSE
            -- Cursor refers to a leaf object
            IF v_is_asc THEN
                v_next_seek := v_start || delimiter_param;
            ELSE
                v_next_seek := v_start;
            END IF;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= max_keys;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_next_seek AND o.name COLLATE "C" < v_upper_bound
                ORDER BY o.name COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_next_seek
                ORDER BY o.name COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Emit and skip to next folder (no heap access needed)
            name := rtrim(v_common_prefix, delimiter_param);
            id := NULL;
            updated_at := NULL;
            created_at := NULL;
            last_accessed_at := NULL;
            metadata := NULL;
            RETURN NEXT;
            v_count := v_count + 1;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := left(v_common_prefix, -1) || chr(ascii(delimiter_param) + 1);
            ELSE
                v_next_seek := v_common_prefix;
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query USING _bucket_id, v_next_seek,
                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := v_current.name;
                    EXIT;
                END IF;

                -- Emit file
                name := v_current.name;
                id := v_current.id;
                updated_at := v_current.updated_at;
                created_at := v_current.created_at;
                last_accessed_at := v_current.last_accessed_at;
                metadata := v_current.metadata;
                RETURN NEXT;
                v_count := v_count + 1;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := v_current.name || delimiter_param;
                ELSE
                    v_next_seek := v_current.name;
                END IF;

                EXIT WHEN v_count >= max_keys;
            END LOOP;
        END IF;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, sort_column text DEFAULT 'name'::text, sort_column_after text DEFAULT ''::text)
 RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_sort_col text;
    v_sort_ord text;
    v_limit int;
BEGIN
    -- Cap limit to maximum of 1500 records
    v_limit := LEAST(coalesce(limits, 100), 1500);

    -- Validate and normalize sort_order
    v_sort_ord := lower(coalesce(sort_order, 'asc'));
    IF v_sort_ord NOT IN ('asc', 'desc') THEN
        v_sort_ord := 'asc';
    END IF;

    -- Validate and normalize sort_column
    v_sort_col := lower(coalesce(sort_column, 'name'));
    IF v_sort_col NOT IN ('name', 'updated_at', 'created_at') THEN
        v_sort_col := 'name';
    END IF;

    -- Route to appropriate implementation
    IF v_sort_col = 'name' THEN
        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))
        RETURN QUERY
        SELECT
            split_part(l.name, '/', levels) AS key,
            l.name AS name,
            l.id,
            l.updated_at,
            l.created_at,
            l.last_accessed_at,
            l.metadata
        FROM storage.list_objects_with_delimiter(
            bucket_name,
            coalesce(prefix, ''),
            '/',
            v_limit,
            start_after,
            '',
            v_sort_ord
        ) l;
    ELSE
        -- Use aggregation approach for timestamp sorting
        -- Not efficient for large datasets but supports correct pagination
        RETURN QUERY SELECT * FROM storage.search_by_timestamp(
            prefix, bucket_name, v_limit, levels, start_after,
            v_sort_ord, v_sort_col, sort_column_after
        );
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text)
 RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;
    v_delimiter CONSTANT TEXT := '/';

    -- Configuration
    v_limit INT;
    v_prefix TEXT;
    v_prefix_lower TEXT;
    v_is_asc BOOLEAN;
    v_order_by TEXT;
    v_sort_order TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;
    v_skipped INT := 0;
BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_limit := LEAST(coalesce(limits, 100), 1500);
    v_prefix := coalesce(prefix, '') || coalesce(search, '');
    v_prefix_lower := lower(v_prefix);
    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';
    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);

    -- Validate sort column
    CASE lower(coalesce(sortcolumn, 'name'))
        WHEN 'name' THEN v_order_by := 'name';
        WHEN 'updated_at' THEN v_order_by := 'updated_at';
        WHEN 'created_at' THEN v_order_by := 'created_at';
        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';
        ELSE v_order_by := 'name';
    END CASE;

    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;

    -- ========================================================================
    -- NON-NAME SORTING: Use path_tokens approach (unchanged)
    -- ========================================================================
    IF v_order_by != 'name' THEN
        RETURN QUERY EXECUTE format(
            $sql$
            WITH folders AS (
                SELECT path_tokens[$1] AS folder
                FROM storage.objects
                WHERE objects.name ILIKE $2 || '%%'
                  AND bucket_id = $3
                  AND array_length(objects.path_tokens, 1) <> $1
                GROUP BY folder
                ORDER BY folder %s
            )
            (SELECT folder AS "name",
                   NULL::uuid AS id,
                   NULL::timestamptz AS updated_at,
                   NULL::timestamptz AS created_at,
                   NULL::timestamptz AS last_accessed_at,
                   NULL::jsonb AS metadata FROM folders)
            UNION ALL
            (SELECT path_tokens[$1] AS "name",
                   id, updated_at, created_at, last_accessed_at, metadata
             FROM storage.objects
             WHERE objects.name ILIKE $2 || '%%'
               AND bucket_id = $3
               AND array_length(objects.path_tokens, 1) = $1
             ORDER BY %I %s)
            LIMIT $4 OFFSET $5
            $sql$, v_sort_order, v_order_by, v_sort_order
        ) USING levels, v_prefix, bucketname, v_limit, offsets;
        RETURN;
    END IF;

    -- ========================================================================
    -- NAME SORTING: Hybrid skip-scan with batch optimization
    -- ========================================================================

    -- Calculate upper bound for prefix filtering
    IF v_prefix_lower = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);
    ELSE
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'AND lower(o.name) COLLATE "C" < $3 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'AND lower(o.name) COLLATE "C" >= $3 ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- Initialize seek position
    IF v_is_asc THEN
        v_next_seek := v_prefix_lower;
    ELSE
        -- DESC: find the last item in range first (static SQL)
        IF v_upper_bound IS NOT NULL THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower AND lower(o.name) COLLATE "C" < v_upper_bound
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSIF v_prefix_lower <> '' THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSE
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        END IF;

        IF v_peek_name IS NOT NULL THEN
            v_next_seek := lower(v_peek_name) || v_delimiter;
        ELSE
            RETURN;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= v_limit;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix_lower <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Handle offset, emit if needed, skip to next folder
            IF v_skipped < offsets THEN
                v_skipped := v_skipped + 1;
            ELSE
                name := split_part(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter), v_delimiter, levels);
                id := NULL;
                updated_at := NULL;
                created_at := NULL;
                last_accessed_at := NULL;
                metadata := NULL;
                RETURN NEXT;
                v_count := v_count + 1;
            END IF;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);
            ELSE
                v_next_seek := lower(v_common_prefix);
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query
                USING bucketname, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := lower(v_current.name);
                    EXIT;
                END IF;

                -- Handle offset skipping
                IF v_skipped < offsets THEN
                    v_skipped := v_skipped + 1;
                ELSE
                    -- Emit file
                    name := split_part(v_current.name, v_delimiter, levels);
                    id := v_current.id;
                    updated_at := v_current.updated_at;
                    created_at := v_current.created_at;
                    last_accessed_at := v_current.last_accessed_at;
                    metadata := v_current.metadata;
                    RETURN NEXT;
                    v_count := v_count + 1;
                END IF;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := lower(v_current.name) || v_delimiter;
                ELSE
                    v_next_seek := lower(v_current.name);
                END IF;

                EXIT WHEN v_count >= v_limit;
            END LOOP;
        END IF;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION storage.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW; 
END;
$function$
